/**
 * Bridges `useFolderDrop`'s imperative `handleDropCapture` out of `AssistantDock` to the wrapping
 * `<aside onDropCapture={...}>` in `App.tsx` (SPEC-053) — `AssistantDock.tsx` itself holds "props
 * interface + JSX, and nothing else" per this file's own header, so the `useEffect` that publishes
 * the handler through a caller-supplied ref lives here, not there. Not a `use*Seam` wrapper like its
 * neighbors above: `useFolderDrop` is this feature's own new hook, not an existing DOM/IO hook this
 * component previously called bare, so there is no "real hook to default to when no override is
 * given" to resolve — `useComposerVoiceInput` (a bare call in `AssistantDock.tsx`, no seam) is the
 * closer precedent, not the eight/nine `use*Seam` hooks.
 *
 * @param input - {@link UseFolderDropInput} — passed straight through to `useFolderDrop`.
 * @param onReady - `AssistantDockProps.onFolderDropCaptureReady`. Invoked once per identity change
 *   of `handleDropCapture` (which itself only changes if `input.composerHandle` or `useFolderDrop`'s
 *   internal callbacks change — effectively once per mount). `undefined` when the caller (e.g. a
 *   test rendering `AssistantDock` directly) does not care to receive it.
 * @returns {@link UseFolderDrop} — `AssistantDock.tsx` renders `notice`/`dismiss`/`retry` from this
 *   directly; `handleDropCapture` is consumed only via `onReady` above, never by `AssistantDock.tsx`
 *   itself (nothing there needs to call it directly).
 * @complexity Time/space: O(1) beyond what `useFolderDrop` itself costs.
 */
export function useFolderDropBridge(
  input: UseFolderDropInput,
  onReady: ((handleDropCapture: (event: DragEvent<HTMLElement>) => void) => void) | undefined,
  proposeSkillFiles?: (files: readonly File[], paths?: readonly string[]) => Promise<void>,
  onSkillDropError?: (message: string) => void,
): UseFolderDrop {
  const folderDrop = useFolderDrop(input);
  const handleDropCapture = useCallback((event: DragEvent<HTMLElement>) => {
    if (proposeSkillFiles && captureSkillDrop({ event, proposeFiles: proposeSkillFiles, fallback: folderDrop.handleDropCapture }, onSkillDropError ? { onError: onSkillDropError } : {})) return;
    folderDrop.handleDropCapture(event);
  }, [proposeSkillFiles, folderDrop.handleDropCapture, onSkillDropError]);
  useEffect(() => { onReady?.(handleDropCapture); }, [onReady, handleDropCapture]);
  return { ...folderDrop, handleDropCapture };
}

type ChatPackageKind = "skill" | "site-plugin" | "agent-plugin" | "attachment";
type CentralDirectory = { count: number; offset: number; size: number };

const END_RECORD_SIGNATURE = 0x06054b50;
const CENTRAL_HEADER_SIGNATURE = 0x02014b50;
const END_RECORD_SIZE = 22;
const CENTRAL_HEADER_SIZE = 46;
/** End record plus the largest possible ZIP comment. */
const END_RECORD_SEARCH_BYTES = 65557;
const MAX_ENTRIES = 4096;
const MAX_DIRECTORY_BYTES = 1024 * 1024;
const PACKAGE_MARKER = /^(?:[^/]+\/)?(?:SKILL\.md|(?:jini|tovu)\.plugin\.json|plugin\.json)$/;

/** Scans backwards for the end record whose comment length reaches exactly the end of the file; -1 when none does. */
function findEndRecord({ tail }: { tail: Uint8Array }): number {
  const view = new DataView(tail.buffer);
  for (let eocd = tail.length - END_RECORD_SIZE; eocd >= 0; eocd--) {
    if (view.getUint32(eocd, true) === END_RECORD_SIGNATURE && eocd + END_RECORD_SIZE + view.getUint16(eocd + 20, true) === tail.length) return eocd;
  }
  return -1;
}

/** Locates a single-disk, bounded, self-consistent central directory; null keeps the file an attachment. */
function readCentralDirectory({ tail, tailStart }: { tail: Uint8Array; tailStart: number }): CentralDirectory | null {
  const eocd = findEndRecord({ tail });
  if (eocd < 0) return null;
  const end = new DataView(tail.buffer);
  if (end.getUint16(eocd + 4, true) !== 0 || end.getUint16(eocd + 6, true) !== 0) return null;
  const count = end.getUint16(eocd + 10, true);
  const size = end.getUint32(eocd + 12, true), offset = end.getUint32(eocd + 16, true);
  if (count > MAX_ENTRIES || count !== end.getUint16(eocd + 8, true) || size > MAX_DIRECTORY_BYTES || offset + size !== tailStart + eocd) return null;
  return { count, offset, size };
}

/** Reads one central header's normalized name and the next header's offset; null when the header is malformed. */
function readEntry({ bytes, view, cursor }: { bytes: Uint8Array; view: DataView; cursor: number }): { name: string; next: number } | null {
  if (cursor + CENTRAL_HEADER_SIZE > bytes.length || view.getUint32(cursor, true) !== CENTRAL_HEADER_SIGNATURE) return null;
  const length = view.getUint16(cursor + 28, true);
  const next = cursor + CENTRAL_HEADER_SIZE + length + view.getUint16(cursor + 30, true) + view.getUint16(cursor + 32, true);
  if (next > bytes.length) return null;
  const name = new TextDecoder().decode(bytes.subarray(cursor + CENTRAL_HEADER_SIZE, cursor + CENTRAL_HEADER_SIZE + length)).replaceAll("\\", "/").replace(/^\.\//, "");
  return { name, next };
}

/** Collects package marker filenames at the archive root or one folder deep; null when the directory is not exactly `count` headers. */
function readPackageMarkers({ bytes, count }: { bytes: Uint8Array; count: number }): Set<string> | null {
  const view = new DataView(bytes.buffer), names = new Set<string>();
  let cursor = 0;
  for (let i = 0; i < count; i++) {
    const entry = readEntry({ bytes, view, cursor });
    if (!entry) return null;
    if (PACKAGE_MARKER.test(entry.name) && !entry.name.startsWith("__MACOSX/")) names.add(entry.name.split("/").at(-1)!);
    cursor = entry.next;
  }
  return cursor === bytes.length ? names : null;
}

function kindFromMarkers({ names }: { names: Set<string> }): ChatPackageKind {
  // A plugin may bundle skills. Its manifest takes precedence so it can reach the assistant.
  if (names.has("jini.plugin.json") || names.has("tovu.plugin.json")) return "site-plugin"; // tovu.plugin.json: legacy alias
  if (names.has("plugin.json")) return "agent-plugin";
  return names.has("SKILL.md") ? "skill" : "attachment";
}

async function zipPackageKind({ file }: { file: File }): Promise<ChatPackageKind> {
  const tailStart = Math.max(0, file.size - END_RECORD_SEARCH_BYTES);
  const tail = new Uint8Array(await file.slice(tailStart).arrayBuffer());
  const directory = readCentralDirectory({ tail, tailStart });
  if (!directory) return "attachment";
  const bytes = new Uint8Array(await file.slice(directory.offset, directory.offset + directory.size).arrayBuffer());
  const names = readPackageMarkers({ bytes, count: directory.count });
  return names ? kindFromMarkers({ names }) : "attachment";
}

/** ZIP names are a routing hint, never install validation. Read only the bounded central directory:
 * deflated payloads need no decompression, and malformed/ZIP64 archives remain ordinary attachments.
 * Generic ZIP name inspection is tracked for Jini extraction (Jini is read-only in this dispatch).
 */
export async function chatPackageKind(
  { file }: { file: File },
  _optional: Record<string, never> = {},
): Promise<ChatPackageKind> {
  if (file.name === "SKILL.md") return "skill";
  if (!file.name.toLowerCase().endsWith(".zip")) return "attachment";
  try {
    return await zipPackageKind({ file });
  } catch {
    return "attachment";
  }
}

/** Jini annotates expanded browser folders with relativePath. Keep a skill's companion files
 * together, but let a plugin manifest at that folder root override all its bundled SKILL.md files. */
export async function partitionChatPackages(
  { files }: { files: readonly File[] },
  _optional: Record<string, never> = {},
): Promise<{ skills: File[]; attachments: File[] }> {
  const paths = files.map(file => ((file as File & { relativePath?: string }).relativePath || file.webkitRelativePath || "").replaceAll("\\", "/"));
  const roots = paths.map(value => value.includes("/") ? value.slice(0, value.indexOf("/") + 1) : "");
  const pluginRoots = new Set(roots.filter((root, index) => root && (paths[index] === `${root}plugin.json` || paths[index] === `${root}jini.plugin.json` || paths[index] === `${root}tovu.plugin.json`))); // tovu.plugin.json: legacy alias
  const skillRoots = new Set(roots.filter((root, index) => root && files[index]!.name === "SKILL.md" && !pluginRoots.has(root)));
  const kinds = await Promise.all(files.map(file => chatPackageKind({ file })));
  const skills: File[] = [], attachments: File[] = [];
  files.forEach((file, index) => {
    const root = roots[index]!;
    const isSkill = root && pluginRoots.has(root) ? false : (root && skillRoots.has(root)) || kinds[index] === "skill";
    (isSkill ? skills : attachments).push(file);
  });
  return { skills, attachments };
}

import type { ComposerDiscoveryOutcome, ComposerDiscoverySelection } from "@jini-ai/chat/react";

import {
  resolveTovuComposerDiscoveryRoute,
  type ComposerCapabilityProjection,
  type ComposerHostBinding,
} from "@/features/plugins/composer-capabilities";
import { draftAfterSkillSelection, type SelectedComposerSkill } from "@/features/plugins/selected-skills";
import { loadSkillDraft } from "@/features/skills/api";

export interface ResolveComposerDiscoveryOutcomeDeps {
  readonly capabilities: ComposerCapabilityProjection;
  readonly navigate: (path: string) => void;
  /** Structurally `@jini-ai/chat/react`'s `McpUiToolCallHandler` — the same instance registered
   * for MCP-UI surface rendering in `AssistantDock.tsx` (`mcpUiToolCaller`), reused rather than
   * re-instantiated. */
  readonly callAllowlistedTool: (call: { name: string; arguments: Record<string, unknown> }) => Promise<unknown> | unknown;
  /**
   * Pins a selected capability's `pluginRefId` (`composer-capabilities.ts`'s own doc on that
   * field) as a removable chip — {@link UseSelectedAgentPlugins.addPluginRef}. Optional so every
   * existing caller of this function keeps compiling and passing unchanged even when it projects no
   * `pluginRefId` capability; a selection that resolves to a `pluginRefId` capability with this omitted is simply
   * a no-op rather than a crash, matching `resolveTovuComposerDiscoveryRoute`'s own "no route, no
   * effect" posture for an id nothing recognizes.
   */
  readonly addPluginRef?: (pluginRefId: string) => void;
  readonly skillsAvailable?: boolean;
  readonly addSkill?: (skill: SelectedComposerSkill) => void;
  readonly readDraft?: () => string;
}

/**
 * Resolves one composer selection into its effect — the host half of debate 2's projection
 * ("Composer slash commands"). Checks the existing client-local route first (`/mcp`'s settings
 * navigation, unchanged since before this projection existed), then falls through to a projected
 * capability's own {@link ComposerHostBinding} (see `composer-capabilities.ts`'s module doc for
 * what each binding kind means). Returns the `ComposerDiscoveryOutcome`
 * Jini's `Composer` applies to the draft, or `undefined` when nothing should change it — e.g. `/mcp`
 * navigating away, or an unresolvable item id (never true for a live selection, but not assumed).
 *
 * A free function rather than inline in the component: every dependency is explicit and injected,
 * so the resolution logic (including the `'allowlisted-tool-call'` branch, unreachable through any
 * bundled capability today) is provable without rendering `AssistantDock` at all.
 *
 * Per `INFO.md`'s Components rule 2 it is re-exported by name from `AssistantDock.tsx` — see that
 * file — which is the path its own suite imports it through.
 *
 * @complexity O(1) plus the cost of `callAllowlistedTool` when a tool-call binding is resolved.
 * @overallScore 100
 */
export async function resolveComposerDiscoveryOutcome(
  selection: ComposerDiscoverySelection,
  deps: ResolveComposerDiscoveryOutcomeDeps,
): Promise<ComposerDiscoveryOutcome | void> {
  const route = resolveTovuComposerDiscoveryRoute(selection.item.id);
  if (route) {
    deps.navigate(route);
    return;
  }

  const capability = deps.capabilities.byItemId.get(selection.item.id);

  // Pinning a plugin ref never leaves anything of its own in the draft — the chip IS the visible
  // effect, rendered by `AssistantDock.tsx`'s own `leadingAccessories` slot from
  // `useSelectedAgentPlugins` state, not by anything Jini's `Composer` applies. Checked before
  // `capability?.resolve` below: today's bundled catalog never sets both on the same capability,
  // but if a future one did, pinning the chip should not be skipped just because a `resolve`
  // binding also exists.
  //
  // `{ draft: "" }`, not a bare `return` (2026-08-23): the "+" menu and a plain (no-`command`)
  // slash selection both already clear the draft themselves, in `Composer.tsx`, via this
  // capability's own `insertText: ""` — this outcome was a no-op for those paths. But the
  // `command`-bearing slash path (`/ui-ux-design`, added the same day) is a `selectSlashItem`
  // branch that skips that same insertText-driven clear (see `composer-capabilities.ts`'s
  // `command` doc), so without this the literal typed `/ui-ux-design` would sit in the box after
  // pinning. Same "host explicitly clears it" pattern the `allowlisted-tool-call` branch below
  // already uses.
  if (capability?.pluginRefId) {
    deps.addPluginRef?.(capability.pluginRefId);
    return { draft: "" };
  }

  if (!capability?.resolve) return;

  return applyBinding({ selection, label: capability.item.label, binding: capability.resolve(selection.argument) }, deps);
}

/** Applies one resolved {@link ComposerHostBinding}; every kind leaves a draft for the composer. */
async function applyBinding(
  { selection, label, binding }: { selection: ComposerDiscoverySelection; label: string; binding: ComposerHostBinding },
  deps: ResolveComposerDiscoveryOutcomeDeps,
): Promise<ComposerDiscoveryOutcome> {
  if (binding.kind === "compose-text") return { draft: binding.text };
  if (binding.kind === "installed-skill") return selectInstalledSkill({ selection, label, toolId: binding.toolId }, deps);

  // 'allowlisted-tool-call': POSTs through the same session-authenticated, allowlist-gated route
  // MCP-UI surface confirmations already use. Rejects with `TOOL_NOT_ALLOWLISTED` (403) for any
  // tool id not on `MCP_UI_REDEEMABLE_TOOL_IDS`'s allowlist — true for every binding in the bundled
  // catalog today, since none is wired to this kind yet. The rejection propagates to the caller,
  // where Jini's `runComposerHostEffect` reports it and leaves the draft untouched.
  await Promise.resolve(deps.callAllowlistedTool({ name: binding.toolName, arguments: binding.params }));
  return { draft: "" };
}

/** Pins an installed skill's guidance for the run (never pasted into the draft) and keeps the user's own text. */
async function selectInstalledSkill(
  { selection, label, toolId }: { selection: ComposerDiscoverySelection; label: string; toolId: string },
  deps: ResolveComposerDiscoveryOutcomeDeps,
): Promise<ComposerDiscoveryOutcome> {
  if (deps.skillsAvailable === false) throw new Error("This runtime has no tools. Choose a runtime with tools to use skills.");
  const draft = draftAfterSkillSelection(deps.readDraft?.() ?? "", selection.source);
  const guidance = await loadSkillDraft(toolId);
  const name = label.replace(/ · Skill$/, "");
  deps.addSkill?.({ toolId, name, guidance });
  return { draft };
}

import { useCallback, useEffect, useRef, useState } from "react";
import { useFetchQuery, useInvalidate } from "@jini-ai/ui/fetch-query";

import { CHAT_DISPLAY_NAMESPACE } from "../chat-display-preferences";
import { DEFAULT_ASSISTANT_RUNTIME_PREFERENCES, type AssistantRuntimePreferences } from "../assistant-runtime-preferences";

/** The shape of `assistantRuntimePreferencesPort`; a test passes a fake. */
export interface AssistantRuntimePreferencesPort {
  load(input?: Record<string, never>, options?: Record<string, never>): Promise<AssistantRuntimePreferences>;
  save(input: { next: AssistantRuntimePreferences; previous: AssistantRuntimePreferences }, options?: Record<string, never>): Promise<void>;
  subscribe(input: { listener: () => void }, options?: Record<string, never>): () => void;
}

export interface AssistantRuntimePreferencesController {
  preferences: AssistantRuntimePreferences;
  /** Applies a change at once and saves it for this person; the server reads it at the next run. */
  update: (patch: Partial<AssistantRuntimePreferences>) => void;
  /** The last save failed; the choice still shows until the page reloads. */
  saveFailed: boolean;
}

const QUERY_KEY = ["settings", CHAT_DISPLAY_NAMESPACE, "assistant-runtime"];

/**
 * The gear's runtime switches and Reply length choice, live — the same
 * optimistic-then-stored flow as `useChatAgentPlugins`: a flip shows at once, is saved per person,
 * and the optimistic copy is dropped once the stored values agree, so a change made elsewhere shows up.
 * {@link DEFAULT_ASSISTANT_RUNTIME_PREFERENCES} until the stored values arrive; a failed read keeps them.
 * @complexity O(1) per change.
 */
export function useAssistantRuntimePreferences(
  { port }: { port: AssistantRuntimePreferencesPort }, _options: Record<string, never> = {},
): AssistantRuntimePreferencesController {
  const fetchPreferences = useCallback(() => port.load({}, {}), [port]);
  const query = useFetchQuery({ key: QUERY_KEY, fetch: fetchPreferences }, { staleTime: 0 });
  const invalidate = useInvalidate();
  const [optimistic, setOptimistic] = useState<AssistantRuntimePreferences | null>(null);
  const [saveFailed, setSaveFailed] = useState(false);
  const lastRequested = useRef<AssistantRuntimePreferences | null>(null);
  const pendingSaves = useRef(0);
  const preferences = optimistic ?? query.data ?? DEFAULT_ASSISTANT_RUNTIME_PREFERENCES;

  useEffect(() => port.subscribe({ listener: () => invalidate({ key: QUERY_KEY }) }, {}), [port, invalidate]);
  useEffect(() => {
    if (pendingSaves.current === 0 && optimistic && query.data
      && optimistic.preferSubagents === query.data.preferSubagents && optimistic.useClaudeInChrome === query.data.useClaudeInChrome
      && optimistic.replyLength === query.data.replyLength) {
      lastRequested.current = null;
      setOptimistic(null);
    }
  }, [optimistic, query.data]);

  const update = useCallback((patch: Partial<AssistantRuntimePreferences>) => {
    // A quick second flip must diff against the last requested values, not a not-yet-re-read copy.
    const previous = lastRequested.current ?? preferences;
    const next = { ...previous, ...patch };
    lastRequested.current = next;
    pendingSaves.current += 1;
    setOptimistic(next);
    port.save({ next, previous }, {}).then(
      () => {
        pendingSaves.current -= 1;
        setSaveFailed(false);
        invalidate({ key: QUERY_KEY });
      },
      () => {
        pendingSaves.current -= 1;
        setSaveFailed(true);
      },
    );
  }, [preferences, port, invalidate]);

  return { preferences, update, saveFailed };
}

import { useEffect, useMemo, useRef, useState } from "react";
import type { ChatPaneRuntimeAccess } from "@jini-ai/chat/react";
import type { DetectedAgent, ExecutionPort } from "@jini-ai/ui";
import { createExecutionPort } from "../../../lib/execution-settings";
import { selectedAgentWarning } from "../../../features/settings/ai-agent-presentation";

type AuthDetectionPort = Pick<ExecutionPort, "detectLocalAgents" | "rescanLocalAgents">;

/**
 * D-21(b): the dock's half of the Settings "AI agent" sign-in warning.
 *
 * The picker's own `/api/agents` inventory carries no authentication status, so this reads the same
 * detection Settings renders (`createExecutionPort`'s module-cached sweep — no extra process scan on
 * mount) and hands it to the already-tested `selectedAgentWarning`, which only warns on a CONFIRMED
 * missing sign-in, never on unknown, and never in BYOK mode.
 *
 * The returned `runtimeAccess` wraps the picker's Rescan so a sign-in done mid-session clears the
 * warning: the picker's own answer is returned untouched and unblocked, and the auth re-probe runs
 * beside it. A failed detection leaves no warning rather than inventing one.
 *
 * @param input.mode The persisted execution mode (`"local-cli"` | `"byok"`).
 * @param input.agentId The picker's selected agent; `useLocalCliSelection` already defaults it to Claude.
 * @param input.locale Admin locale for the warning copy.
 * @param input.runtimeAccess The picker's runtime access to wrap.
 * @param options.port Detection port; defaults to the shared Settings port.
 * @returns `{ warning, runtimeAccess }` — `warning` is null when nothing needs attention.
 * @complexity O(n) over the detected agents per settled scan.
 */
export function useSelectedAgentAuthWarning(
  { mode, agentId, locale, runtimeAccess }: {
    mode: string; agentId: string | null | undefined; locale: string; runtimeAccess: ChatPaneRuntimeAccess;
  },
  { port: injectedPort }: { port?: AuthDetectionPort } = {},
) {
  const [port] = useState<AuthDetectionPort>(() => injectedPort ?? createExecutionPort());
  const [agents, setAgents] = useState<readonly DetectedAgent[]>([]);
  const generation = useRef(0);
  const live = useRef(true);
  useEffect(() => {
    live.current = true;
    return () => { live.current = false; };
  }, []);

  const scanRef = useRef((request: () => Promise<readonly DetectedAgent[]>) => {
    const scan = ++generation.current;
    // Through a promise so a port that throws synchronously still lands in the no-warning branch.
    Promise.resolve().then(request).then(
      // A slow first detection must not overwrite a newer rescan's result.
      (next) => { if (live.current && scan === generation.current) setAgents(next); },
      () => { if (live.current && scan === generation.current) setAgents([]); },
    );
  });

  // Re-read on mode/agent change: cheap (module-cached), and Settings may have rescanned meanwhile.
  useEffect(() => {
    if (mode === "local-cli") scanRef.current(() => port.detectLocalAgents());
  }, [mode, agentId, port]);

  const wrappedAccess = useMemo<ChatPaneRuntimeAccess>(() => ({
    ...runtimeAccess,
    rescanAgents: () => {
      scanRef.current(() => port.rescanLocalAgents ? port.rescanLocalAgents() : port.detectLocalAgents());
      return runtimeAccess.rescanAgents();
    },
  }), [runtimeAccess, port]);

  return {
    warning: selectedAgentWarning({ mode, agentId: agentId ?? "claude", agents, locale }),
    runtimeAccess: wrappedAccess,
  };
}

import { useEffect, useRef, useState, type RefObject } from "react";

/**
 * @file Detects whether a ref'd element's CONTENT no longer fits its own box — the trigger for the
 * chat pane's "Show in modal" affordance (owner request, chat-overflow fix 2026-08-30): a button
 * that appears only on content that genuinely doesn't fit, never unconditionally on every card.
 *
 * `ResizeObserver` on the element itself (not a child, not the window) — the same primitive
 * `@jini-ai/chat`'s own `useChatPaneControlsHeight`/`MessageList` sticky-scroll effect already uses,
 * but NOT the same guarantee: `ResizeObserver` only ever reports a change in the OBSERVED ELEMENT'S
 * OWN box (its content-box, by default) — never "this element's content changed" in general, and
 * never a descendant's box on its own. `useChatPaneControlsHeight` gets away with that distinction
 * not mattering because its target (`.jini-chat-pane__controls`) is unclipped: its own box IS sized
 * to its content, so a content change and a box change are the same event there. This element is
 * the opposite on purpose — it exists to catch content that no longer fits a box the surrounding
 * layout holds FIXED (the 380px dock this hook's own module doc opens with) — so the two are NOT
 * interchangeable here: a genuinely fixed-width axis can grow its `scrollWidth` arbitrarily far past
 * `clientWidth` while its own box, by construction, never moves, and `ResizeObserver` will not fire
 * for that. What DOES reliably fire it in this hook's real usage is a change on an axis this
 * element's OWN box is not externally pinned on — concretely, its height: `McpUiHost`
 * (`@jini-ai/ui/mcp-ui`) renders its iframe wrapper at an explicit, JS-driven height (not iframe-
 * intrinsic), and since this wrapper itself has no height of its own, that wrapper's growth (a
 * surface reporting a taller real size asynchronously via `ui/notifications/size-changed` — the same
 * late growth `MessageList.tsx`'s own doc describes) grows THIS element's own content-box height in
 * lockstep, which is a real, observable resize of the element `ResizeObserver` is watching. That
 * stops being true past `McpUiHost`'s own `maxHeight` cap — see the known limitation below — and it
 * was never true for width, since `McpUiHost` renders its iframe at a flat `width: '100%'`
 * regardless of content, so a width overflow through this specific child cannot currently occur at
 * all. The mount-time call below (`setIsOverflowing(isElementOverflowing(el))`, run once
 * synchronously, independent of any observer notification) is what actually covers content already
 * overflowing at first paint on ANY axis, `ResizeObserver` or not — a future caller that reuses this
 * hook against genuinely width-varying, non-iframe content should not assume a later-arriving width
 * change on a pinned axis will be caught the same way.
 *
 * Known limitation, stated rather than silently shipped: `McpUiHost` (`@jini-ai/ui/mcp-ui`) applies
 * its own `maxHeight` cap to the iframe wrapper's inline `height` style before this hook ever sees
 * the box, so a surface whose REAL content is taller than that cap reads as "clipped inside its own
 * iframe" without this wrapper's `scrollHeight` ever exceeding its `clientHeight` — the overflow is
 * real but happens one sandboxed frame away from where this hook measures. Catching that case would
 * need `McpUiHost` itself to expose whether it is currently capped (its reported vs. applied size),
 * which is a `@jini-ai/ui` change with its own rebuild step, not something this hook can see from
 * the outside. This hook reliably covers what it CAN see today: height growth up to that cap (the
 * only overflow axis this specific `McpUiHost`-backed caller can currently produce) plus whatever
 * either axis already looks like at first paint.
 */
export interface UseOverflowDetectionResult<T extends HTMLElement> {
  /** Attach to the element whose rendered content should be checked for overflow. */
  containerRef: RefObject<T | null>;
  /** True once the element's scrollable content exceeds its own box, in either axis. */
  isOverflowing: boolean;
}

/** Slack, in px, before a fractional layout rounding difference counts as "overflowing" — mirrors
 *  `MessageList.tsx`'s own `AT_BOTTOM_THRESHOLD_PX` reasoning for the same kind of sub-pixel noise. */
const OVERFLOW_SLACK_PX = 1;

function isElementOverflowing(el: HTMLElement): boolean {
  return el.scrollWidth > el.clientWidth + OVERFLOW_SLACK_PX || el.scrollHeight > el.clientHeight + OVERFLOW_SLACK_PX;
}

/**
 * @returns `containerRef` to attach to the measured element, plus its live overflow state.
 * @complexity Time/space: O(1) per resize notification — one comparison, no accumulation.
 */
export function useOverflowDetection<T extends HTMLElement = HTMLDivElement>(): UseOverflowDetectionResult<T> {
  const containerRef = useRef<T | null>(null);
  const [isOverflowing, setIsOverflowing] = useState(false);

  useEffect(() => {
    const el = containerRef.current;
    if (!el || typeof ResizeObserver !== "function") return;
    const observer = new ResizeObserver(() => setIsOverflowing(isElementOverflowing(el)));
    observer.observe(el);
    setIsOverflowing(isElementOverflowing(el));
    return () => observer.disconnect();
  }, []);

  return { containerRef, isOverflowing };
}

import { useEffect, useState, type CSSProperties } from "react";
import { agentHandle } from "@jini-ai/agentic";

/**
 * @file The Desktop/Tablet/Mobile device-width preview shared by every admin editor that previews a
 * rendered document: `PageEditor.tsx`, `ThemeExplore.tsx` and `PostEditor.tsx` (2026-09-22 — the
 * three used to carry their own copies of the toggle, the scaling frame and the pane measurement;
 * Posts had none at all). `DevicePreviewToggle.tsx` and `DevicePreviewFrame.tsx` render; everything
 * they derive lives here, per this repo's `<Name>.tsx`/`<Name>.hooks.ts` split.
 */

/**
 * Viewport widths the preview renders AT, independent of how much room the pane actually has.
 *
 * This is the point of the whole preview mechanism, not a nice-to-have. With the assistant dock
 * open the editor pane is well under half the window, so a preview rendered at its container's real
 * width would show a layout at ~900px that ships at 1280+ — the operator would be judging, and
 * asking the model to fix, breakpoints nobody will ever see. The document is rendered at the chosen
 * width and scaled down to fit instead.
 */
export const DEVICE_PREVIEW_WIDTHS = { desktop: 1280, tablet: 834, mobile: 390 } as const;

export type DevicePreviewDevice = keyof typeof DEVICE_PREVIEW_WIDTHS;

/** The toggle's buttons, in display order. `label` is the untranslated key the caller's `t()` reads. */
export const DEVICE_PREVIEW_OPTIONS: ReadonlyArray<{ key: DevicePreviewDevice; label: string }> = [
  { key: "desktop", label: "Desktop" },
  { key: "tablet", label: "Tablet" },
  { key: "mobile", label: "Mobile" },
];

/** The unscaled viewport height every preview renders at before it is scaled to fit the pane. */
export const DEVICE_PREVIEW_HEIGHT = 900;

/** The pane width assumed before the first real measurement lands — keeps the first paint's scale
 *  sane instead of `Infinity`/`NaN` from a zero-width frame. */
export const DEVICE_PREVIEW_DEFAULT_PANE_WIDTH = 880;

/**
 * The factor a `width`-px document is scaled by to fit a `paneWidth`-px pane: never above 1 (a
 * narrow Mobile preview in a wide pane renders 1:1, not blown up), and floored above zero. The floor
 * matters for the expanded frame: a zero-width observation (the frame measured during a paint where
 * its column has no width yet) would make its scaler height `calc(100% / 0)` — an INVALID
 * declaration CSS drops entirely, silently reverting the height to `auto`. No real measurement gets
 * anywhere near it.
 *
 * @complexity O(1).
 */
export function devicePreviewScale({ paneWidth, width }: { paneWidth: number; width: number }): number {
  return Math.max(0.01, Math.min(1, paneWidth / width));
}

/**
 * Inline styles for `DevicePreviewFrame`'s two boxes. Collapsed, the frame is a fixed
 * `900 * scale` box and the scaler the literal `900px`. Expanded, the frame gets NO inline height —
 * it takes its height from the fullscreen panel's flex column (`.page-preview-expanded
 * .page-preview-frame` / `.post-preview-expanded .page-preview-frame`), and an inline height would
 * beat that rule — and the scaler's `calc(100% / scale)` renders, after `scale(scale)`, exactly as
 * tall as the frame, so the previewed viewport grows with the panel.
 *
 * @complexity O(1).
 */
export function devicePreviewFrameStyles({
  paneWidth,
  width,
  expanded,
}: {
  paneWidth: number;
  width: number;
  expanded: boolean;
}): { frame: CSSProperties | undefined; scaler: CSSProperties } {
  const scale = devicePreviewScale({ paneWidth, width });
  return {
    frame: expanded ? undefined : { height: `${DEVICE_PREVIEW_HEIGHT * scale}px` },
    scaler: {
      width: `${width}px`,
      height: expanded ? `calc(100% / ${scale})` : `${DEVICE_PREVIEW_HEIGHT}px`,
      transform: `scale(${scale})`,
    },
  };
}

/**
 * The `agentHandle()` spread for one toggle button, or nothing when the caller gave no handle
 * prefix. With a prefix, the handle is `${prefix}-${key}` (e.g. `page-preview-width-mobile`).
 *
 * @complexity O(1).
 */
export function devicePreviewButtonHandleProps(
  handlePrefix: string | undefined,
  entry: { key: DevicePreviewDevice; label: string },
) {
  if (!handlePrefix) return {};
  return agentHandle({ handle: `${handlePrefix}-${entry.key}` }, { role: "button", label: `Preview at ${entry.label} width` });
}

/** Same 640px phone breakpoint as `styles.css`'s phone rules (card tables, swipeable tabs). */
const PHONE_VIEWPORT_QUERY = "(max-width: 640px)";

function matchesPhoneViewport(): boolean {
  return typeof window.matchMedia === "function" && window.matchMedia(PHONE_VIEWPORT_QUERY).matches;
}

/**
 * The device a preview opens at when its caller names none: Mobile on a phone, Desktop otherwise.
 * On a 375px phone a 1280px preview scales by ~0.27 and its body text lands near 4px — unreadable
 * (mobile catalog P-7/PG-4/TH-4, 2026-10-06); the phone's own width is the useful first view there.
 *
 * @complexity O(1).
 */
export function defaultDevicePreviewDevice({ isPhone }: { isPhone: boolean }): DevicePreviewDevice {
  return isPhone ? "mobile" : "desktop";
}

/**
 * The selected device plus its pixel width. View state only; the viewport check is read once, on
 * mount, so rotating or resizing later never overrides a device the operator picked.
 *
 * @param initial - The device to open at. @default Mobile on a phone viewport, else Desktop
 * @param optional.isPhone - Whether the viewport is phone-width. @default matchMedia (640px)
 * @complexity O(1).
 */
export function useDevicePreviewDevice(
  initial?: DevicePreviewDevice,
  { isPhone = matchesPhoneViewport }: { readonly isPhone?: () => boolean } = {},
): {
  device: DevicePreviewDevice;
  setDevice: (value: DevicePreviewDevice) => void;
  width: number;
} {
  const [device, setDevice] = useState<DevicePreviewDevice>(() => initial ?? defaultDevicePreviewDevice({ isPhone: isPhone() }));
  return { device, setDevice, width: DEVICE_PREVIEW_WIDTHS[device] };
}

/**
 * The preview frame's REAL rendered width, measured live via `ResizeObserver` rather than a guessed
 * constant — a flat `880` meant the scale computed once and stayed frozen across a window resize, a
 * sidebar collapse, or the assistant dock opening/closing.
 *
 * `frameRef` is a CALLBACK ref (a piece of state plus its setter), NOT a `useRef`, and the effect is
 * keyed off the NODE itself. A `useRef` has no way to notify anything when React attaches a node, so
 * an effect keyed on anything else can run before the frame exists (e.g. while the editor still
 * shows its loading notice), find `null`, bail, and never run again — measured live on a real page:
 * a 1131px pane rendering at the `880/1280` scale. React calls a callback ref exactly when the node
 * mounts, however late, and with `null` on unmount, so every mount gets a fresh observer and every
 * unmount disconnects it.
 *
 * jsdom implements no `ResizeObserver` (`__tests__/setup.ts` deliberately leaves it unstubbed), so the
 * guard below keeps every unit test rendering at the `880` default.
 *
 * @returns The callback ref to attach and the frame's last-measured width.
 * @complexity O(1) per resize callback — one observed element, at most one entry.
 */
export function usePreviewPaneWidth(): {
  frameRef: (node: HTMLDivElement | null) => void;
  paneWidth: number;
} {
  const [frameNode, setFrameNode] = useState<HTMLDivElement | null>(null);
  const [paneWidth, setPaneWidth] = useState<number>(DEVICE_PREVIEW_DEFAULT_PANE_WIDTH);
  useEffect(() => {
    if (!frameNode || typeof ResizeObserver !== "function") return;
    const observer = new ResizeObserver((entries) => {
      const entry = entries[0];
      if (entry) setPaneWidth(entry.contentRect.width);
    });
    observer.observe(frameNode);
    return () => observer.disconnect();
  }, [frameNode]);
  return { frameRef: setFrameNode, paneWidth };
}

import type { WidgetPickerPort } from "../WidgetPickerDialog/widget-picker-port.hooks";
import { useState } from "react";
import { useWidgetAddControl } from "../WidgetPickerDialog/WidgetPickerDialog";

/**
 * @file `EmbedInsertControl`'s own state — the menu open/closed flag, the Media-picker-open flag,
 * the Widget…-mode flag, and the two pinned `useWidgetAddControl` instances (Form/Menu) — split out
 * of the component so it can be swapped for a fake via the `useEmbed` prop on
 * `EmbedInsertControlProps`, see that prop's doc comment in `EmbedInsertControl.tsx`. Same split
 * `ConfirmDialog`/`ConfirmDialog.hooks.tsx` uses in `@jini-ai/admin`, and the same one
 * `WidgetPickerDialog.tsx`/`WidgetPickerDialog.hooks.tsx` already applies in this app.
 */

export interface EmbedEditor {
  commands: {
    // 2026-09-11: the "Media" menu item now inserts the generic `media` node (`insertMediaEmbed`,
    // `lib/media-embed-extension.tsx`) instead of the legacy `image`-only ref node. That node's own
    // `insertMediaRef` command is gone — deleted as dead code in 2f53240d once this control stopped
    // calling it; `MediaImage` still RENDERS backward-compat ref content, it just has no insert
    // command of its own any more, and the "Insert image by URL" button uses the unrelated legacy
    // `src`-only `setImage`. See `media-embed-extension.tsx`'s header for why one dispatching node
    // replaces a per-kind one.
    insertMediaEmbed: (attrs: { assetId: string; transformName: string; alt?: string }) => boolean;
    insertWidgetEmbed: (attrs: { placementId: string; widgetEntryId: string }) => boolean;
  };
}

/** Same placement-id minting `widget-embed-extension.tsx`'s own (private) helper uses — duplicated
 *  here rather than exported from that file, to avoid touching a file with its own existing test
 *  coverage for an unrelated reason. */
function newPlacementId(): string {
  return globalThis.crypto?.randomUUID?.() ?? `placement-${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

/**
 * Owns `EmbedInsertControl`'s menu/dialog visibility state and the two pinned "shortcut"
 * `useWidgetAddControl` instances the Form/Menu menu items drive directly via `setPickerType`
 * (never through `useWidgetAddControl`'s own `selectedType`/`<Select>` step — that path is only
 * exercised by the "Widget…" full flow, via the untouched `WidgetAddControl`).
 *
 * @param editor - The live TipTap editor, or `null` before it's ready. Read only through
 *   `insertWidget`'s optional chaining here — the component's own `if (!editor) return null`
 *   early-return still guards the JSX, same as before this split.
 */
export function useEmbedInsertControl(editor: EmbedEditor | null, { widgetPort, mintPlacementId = newPlacementId }: { widgetPort?: WidgetPickerPort; mintPlacementId?: () => string } = {}) {
  const [open, setOpen] = useState(false);
  const [widgetMode, setWidgetMode] = useState(false);
  const [mediaPicking, setMediaPicking] = useState(false);

  // A TipTap command returns false when it cannot apply (the schema refuses the node at the current
  // selection). Ignoring that reported a placement that never happened as a success: the picker
  // closed and nothing appeared. Throwing hands it to `useWidgetAddControl`'s existing onResolved
  // catch, which shows "failed to place widget" / "created but not placed" in the control's error
  // slot. A null editor stays a no-op: the component renders nothing until the editor exists.
  const insertWidget = (widgetEntryId: string) => {
    if (!editor) return;
    const placed = editor.commands.insertWidgetEmbed({ placementId: mintPlacementId(), widgetEntryId });
    if (!placed) throw new Error("the editor could not place the widget at the cursor");
  };

  const formControl = useWidgetAddControl({ triggerLabel: "Form", onResolved: insertWidget }, { port: widgetPort });
  const menuControl = useWidgetAddControl({ triggerLabel: "Menu", onResolved: insertWidget }, { port: widgetPort });
  const galleryControl = useWidgetAddControl({ triggerLabel: "Gallery", onResolved: insertWidget }, { port: widgetPort });

  // `insertWidget` is returned too, not just consumed by the two pinned controls above — the
  // "Widget…" full-flow path in the component's JSX (via the untouched `WidgetAddControl`) calls it
  // directly from its own `onResolved`, exactly as the pre-split component did inline.
  return { open, setOpen, widgetMode, setWidgetMode, mediaPicking, setMediaPicking, formControl, menuControl, galleryControl, insertWidget };
}

import { useCachedLoader } from "@jini-ai/ui/fetch-query";
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useHostMediaPicker } from '../../integrations/jini-admin/modules.hooks';
import { defaultMediaPickerPort } from './media-picker-dependencies.hooks';
import type { MediaPickerPort } from './media-picker-port.hooks';
import type { MediaPickerDialogProps } from './MediaPickerDialog';
/** The shared dialog is the compatibility boundary for editor, SEO and widget callers.
 * The service selects an asset; the host resolves its CMS fields (notably readable slug)
 * through the same authenticated route, without leaking those fields into the generic port. */
export function useJiniMediaPicker(props: MediaPickerDialogProps, { port = defaultMediaPickerPort }: { port?: MediaPickerPort } = {}) {
  const picker = useHostMediaPicker();
  const key = useMemo(() => ["media"] as const, []);
  const fetchMedia = useCallback(() => port.listMedia(), [port]);
  const media = useCachedLoader({ key, fetch: fetchMedia }, { staleTime: 0 });
  const enabled = !!picker && !props.useDialog;
  const callbacks = useRef(props); callbacks.current = props;
  const [error, setError] = useState<string | null>(null);
  useEffect(() => {
    if (!enabled || !picker) return;
    const abort = new AbortController();
    void picker.pick({ accept: callbacks.current.accept ?? [] }, { signal: abort.signal }).then(async selected => {
      if (abort.signal.aborted) return;
      if (!selected) { callbacks.current.onCancel(); return; }
      const rows = await media.load();
      const row = rows.media.find(item => item.id === selected.id && item.status === 'active');
      if (!row) throw new Error('Selected media is unavailable');
      if (!abort.signal.aborted) callbacks.current.onSelect(row);
    }).catch(() => { if (!abort.signal.aborted) setError('Unable to choose media. Please try again.'); });
    return () => abort.abort();
  }, [picker, enabled, media]);
  return { enabled, error, onCancel: props.onCancel };
}

import { useJiniMediaPicker } from "./JiniMediaPicker.hooks";
import { Dialog } from "@jini-ai/ui-kit/react";
import "../../styles/native-domain-dialogs.css";
import { agentHandle } from "@jini-ai/agentic";
import type { AdminMedia } from "../../lib/api";
import { buildAgentListHandles } from "@jini-ai/agentic";
import { splitOnPlaceholders } from "@jini-ai/ui/panel-kit";
import { acceptedMediaItems, useWiredMediaPickerDialog } from "./MediaPickerDialog.hooks";

/**
 * @file `MediaPickerDialog` — lets an operator choose an EXISTING asset from the Media library
 * instead of typing a URL. First call site: the Posts/Pages editors' toolbar ("Insert from Media
 * Library"), replacing the old blind `window.prompt("Image URL:")` flow with a real picker over
 * the same library `features/media/Media.tsx` already manages.
 *
 * Reuses Jini's native dialog owner, like `WidgetPickerDialog.tsx`: the browser provides
 * modal isolation and Jini owns open/close, Escape, backdrop dismissal and focus return. Unlike
 * `WidgetPickerDialog`, there is no "create new" branch here: a new asset is uploaded through
 * `features/media/Media.tsx`'s own upload flow, not inline from an editor toolbar (uploading a
 * file mid-edit, with its own alt/caption/credit fields, is a bigger surface than this picker's
 * job — "choose one of the assets that already exist").
 *
 * Reuses the same `/media` data path `features/media/`'s own `useMedia`/`MediaPreview` already
 * read — rather than a second query against the same table — via the injected `useDialog` hook's
 * `MediaPickerPort` (`listMedia`, `mediaOriginalUrl`; see `media-picker-port.hooks.ts`).
 * Deliberately does NOT reuse `MediaPreview`'s full video/unsupported-type fallback chain
 * (`use-media-preview.hooks.ts`): this picker only ever inserts an `image` node, so a thumbnail
 * grid needs just the image case, not the video/`<video>`/download-link branches a general asset
 * preview does. `active` assets only — a trashed asset is not a legal choice for new content.
 *
 * Domain state/effects — the once-per-mount media fetch — live in
 * `MediaPickerDialog.hooks.tsx`, split out the same way `ConfirmDialog`/`ConfirmDialog.hooks.tsx`
 * does in `@jini-ai/admin`: this file stays props-and-JSX only, and the `useDialog` prop below lets
 * a test render this JSX against a fake hook — no real `api.listMedia()` call and no real
 * `document`-level keydown listener required.
 *
 * ## Agent handles
 *
 * Given `agentHandle="post-media"` this publishes:
 *
 * | element | handle | role |
 * |---|---|---|
 * | one grid item, keyed by the asset's own `id` | `post-media-item-<slug of id>` | `button` |
 * | the Cancel button | `post-media-cancel` | `button` |
 *
 * Items sit under their own `-item-` namespace via `@jini-ai/agentic`'s `buildAgentListHandles`,
 * the same "caller data cannot collide with this component's own literal segments" reasoning
 * `source-config-list/agent-handles.ts` documents for its own `-field-`/`-item-` namespaces. Omit
 * `agentHandle` and no `data-agent-*` markup is emitted at all.
 */

export interface MediaPickerDialogProps {
  onSelect: (item: AdminMedia) => void;
  onCancel: () => void;
  /** Injectable seam for the dialog's data-fetch and Escape-to-cancel hook. Defaults to the real
   *  {@link useWiredMediaPickerDialog}; a test can pass a fake here to exercise `MediaPickerDialog`'s
   *  rendering without invoking `api.listMedia()` or a real `document` keydown listener at all. */
  useDialog?: typeof useWiredMediaPickerDialog;
  /** This dialog's own base handle — see this file's "Agent handles" doc for the full scheme. Omit
   *  to leave it untagged. */
  agentHandle?: string;
  /** Content types this caller can use, e.g. `["image/*"]` (2026-10-05: the featured-image chooser
   *  offered videos). Same matching as Jini's `acceptsMedia`: an asset with no known type is hidden
   *  once a filter is given. Omit (or `[]`) to offer every asset — existing callers' behavior. */
  accept?: readonly string[];
}

function LegacyMediaPickerDialog({ useDialog = useWiredMediaPickerDialog, agentHandle: base, accept, ...props }: MediaPickerDialogProps) {
  const dialog = useDialog(props.onSelect, props.onCancel);
  const { error, select, mediaOriginalUrl, t } = dialog;
  const items = acceptedMediaItems(dialog.items, accept);
  // Native modality keeps Tab inside; Jini also restores the opener when this dialog unmounts.
  // Cancel is always present regardless of loading/error/empty/populated state, the same reason
  // useMediaLightbox has an always-available Close target.
  const itemHandles = base && items ? buildAgentListHandles({ prefix: `${base}-item`, ids: items.map((item) => item.id) }) : undefined;
  // `{link}` must render as a real `<a>` node, not plain text — interpolate() can't produce that,
  // so this splits the template around the token instead. See `lib/template-i18n.ts`'s own header.
  const [emptyStateBefore, emptyStateAfter] = splitOnPlaceholders({ template: t("No media uploaded yet. Upload an asset from the {link} screen first."), tokens: ["{link}"] }
  );

  return (
    <Dialog open title={t("Choose an image")} onClose={() => props.onCancel()}
      className="settings-dialog jini-domain-dialog media-picker-dialog">

        <div className="media-picker-body">
          {error ? <div className="notice error">{error}</div> : null}
          {items === null ? (
            <p className="notice">{t("Loading media…")}</p>
          ) : items.length === 0 ? (
            <p className="notice">
              {emptyStateBefore}
              <a href="/admin/media">{t("Media")}</a>
              {emptyStateAfter}
            </p>
          ) : (
            <div className="media-picker-grid">
              {items.map((item, index) => (
                <button
                  key={item.id}
                  type="button"
                  className="media-picker-item"
                  title={item.title}
                  onClick={() => select(item)}
                  {...(itemHandles ? agentHandle({ handle: itemHandles[index]! }, { role: "button", label: item.title }) : {})}
                >
                  <img src={mediaOriginalUrl(item.id)} alt={item.alt || item.title} loading="lazy" />
                  <span className="media-picker-item-title">{item.title}</span>
                </button>
              ))}
            </div>
          )}
        </div>

        <div className="widget-picker-footer">
          <span className="editor-actions">
            <button
              data-jini-autofocus=""
              type="button"
              className="btn-secondary"
              onClick={props.onCancel}
              {...(base ? agentHandle({ handle: `${base}-cancel` }, { role: "button", label: "Close without choosing an image" }) : {})}
            >
              {t("Cancel")}
            </button>
          </span>
        </div>
    </Dialog>
  );
}

/** Existing callers keep their CMS callbacks; the mounted admin supplies Jini's promise service. */
export function MediaPickerDialog(props: MediaPickerDialogProps, _optional: Record<string, never> = {}) {
  const vm = useJiniMediaPicker(props);
  return vm.enabled ? <>{vm.error && <div role="alert">{vm.error}<button type="button" onClick={vm.onCancel}>Cancel</button></div>}</> : <LegacyMediaPickerDialog {...props} />;
}

import { useCallback as useQueryFetchCallback } from "react";
import { useFetchQuery } from "@jini-ai/ui/fetch-query";

import { resolveThemeLayout } from "@tovu/theme-layout";

import type { ThemeTier } from "@/lib/api";
import { defaultTemplateSourcePort } from "./template-source-dependencies.hooks";
import type { TemplateSourcePort } from "./template-source-port.hooks";

/**
 * @file `TemplateSourceModal`'s template-source fetch, split out per the `use-<thing>.hooks.ts`
 * convention. `port` is injected (see `template-source-port.hooks.ts`) rather than calling global
 * `fetch` directly, so a test can describe "this template loaded/failed" against
 * `createFakeTemplateSourcePort` instead of stubbing `fetch`.
 *
 * Moved here from `features/posts/hooks/use-post-template-source.hooks.ts` (2026-09-24): "View
 * Template" started as a Post-only affordance (2026-08-10), then `features/pages`' `PageEditor.tsx`
 * grew the identical eye-icon button/modal next to its own template picker — the fetch/URL-building
 * logic below was already feature-agnostic (it only ever took a theme id, tier, apiVersion and
 * filename, none of them Post-specific), so the move is a rename plus a relocation, not a rewrite.
 * `features/posts/PostEditor.tsx` and `features/pages/PageEditor.tsx` both import from here now,
 * instead of Pages copy-pasting a second implementation.
 *
 * 2026-08-19 architecture audit finding 1: this used to build `/theme-assets/{theme}/pages/{file}`
 * unconditionally — the v1 layout. Every current static theme (`src/themes/static/basic` and its six
 * siblings) is `apiVersion: 2`, whose page templates live under `render/pages/`, so "View Template"
 * 404ed for every real built-in theme. `templateAssetUrl` now takes the active theme's `apiVersion`
 * and resolves the folder through `@tovu/theme-layout` — the same resolver `explore.ts`'s server route
 * uses — instead of a second, independently-spelled `pages`/`render/pages` literal.
 */

export type TemplateSourceFetchState =
  | { status: "loading" }
  | { status: "loaded"; html: string }
  | { status: "error"; message: string };

/** `/theme-assets/{themeId}/{pagesDir}/{templateFilename}` — the exact route
 *  `theme-static-assets.ts` serves a static-tier theme's page templates under (verified live,
 *  2026-08-10: `GET /theme-assets/basic/render/pages/blog-sidebar-template.html` → 200 with the raw
 *  HTML). `pagesDir` comes from `resolveThemeLayout(apiVersion)` — `pages` for a v1 theme,
 *  `render/pages` for `apiVersion: 2`. `encodeURIComponent` on the theme id and filename segments: a
 *  theme id or filename with a space/`#`/`?` would otherwise either 404 against the exact static path
 *  or get parsed as a query string; `pagesDir`'s own `/` is intentionally left unencoded, matching a
 *  real static path segment. */
export function templateAssetUrl(themeId: string, templateFilename: string, apiVersion: 2 | undefined): string {
  const { pagesDir } = resolveThemeLayout(apiVersion);
  return `/theme-assets/${encodeURIComponent(themeId)}/${pagesDir}/${encodeURIComponent(templateFilename)}`;
}

/**
 * Route path (not a full URL — matches this app's `navigate()`, see `apps/admin/src/lib/router.ts`)
 * for the Theme Explore screen with this template preselected — `TemplateSourceModal`'s "Edit"
 * button target (owner ask, 2026-09-22). The viewer stays read-only; this only ever points the
 * operator at Explore, which is where the real edit happens.
 *
 * Builds the short `?page=<label>` form Theme Explore documents and writes for an ordinary page
 * (`theme-explore-url.hooks.ts`'s file header and `writeThemeExploreSelectionToUrl`), not the
 * longer `?file=<full path>` form — every template this modal can show is itself a static-tier
 * page template, so `resolveThemeExploreSelectionValue`'s label match (`kind === "page"`, basename
 * minus `.html`) always resolves it without needing `pagesDir` at all. Built with `URLSearchParams`,
 * matching that module's own encoding.
 *
 * @param themeId - The active theme id.
 * @param templateFilename - The selected template's filename (e.g. `posts-default.html`).
 * @returns A `/themes/explore?theme=...&page=...` route path.
 * @complexity O(1).
 */
export function templateEditUrl(themeId: string, templateFilename: string): string {
  const params = new URLSearchParams({ theme: themeId, page: templateFilename.replace(/\.html$/, "") });
  return `/themes/explore?${params.toString()}`;
}

/**
 * Fetches a static-tier theme's template source as plain text via the injected `port`. Kept out
 * of the component body so the three outcomes (loading/loaded/error) are the function's only
 * branches — no theme-tier decision in here, that gate lives in the caller
 * (`TemplateSourceModal`'s render), which is also why this never fetches at all for a non-static
 * theme.
 *
 * @param themeId - The active theme id — used to build the fetch URL.
 * @param themeTier - The active theme's capability tier. Only `"static"` triggers a fetch;
 *   anything else (including `null`, meaning the tier itself could not be determined) leaves this
 *   in its initial `loading` state forever, since the caller renders its own explanation instead
 *   of ever showing that state.
 * @param themeApiVersion - The active theme's manifest `apiVersion` — `2` or `undefined` (v1) — used
 *   to pick the right `pages`/`render/pages` folder via `templateAssetUrl`. Unknown-but-tier-known
 *   (e.g. presentation settings loaded but the theme's own `apiVersion` field wasn't in that
 *   response) is treated the same as `undefined` (v1), matching `resolveThemeLayout`'s own default.
 * @param templateFilename - The selected template's filename.
 * @param port - Injected {@link TemplateSourcePort} — see `template-source-port.hooks.ts`.
 * @returns The current {@link TemplateSourceFetchState}.
 * @complexity Time/space: O(n) in the fetched document's size — one request, no retry loop.
 */
export function useTemplateSource(
  themeId: string,
  themeTier: ThemeTier | null,
  themeApiVersion: 2 | undefined,
  templateFilename: string,
  port: TemplateSourcePort,
): TemplateSourceFetchState {
  // Keyed reads replace the cleanup flag: a prior route's source cannot populate this key.
  const queryFetch = useQueryFetchCallback(async () => {
    try { return await port.fetchTemplateSource(templateAssetUrl(themeId, templateFilename, themeApiVersion)); }
    catch (error) { throw new Error(error instanceof Error ? error.message : "failed to load the template"); }
  }, [port, themeId, themeApiVersion, templateFilename]);
  // Query ownership handles StrictMode cleanup/replay without a module-level disposed flag
  // surviving the second mount (apps/admin/INFO.md's disposed-flag trap).
  // Nothing to fetch — the caller renders the tier explanation instead for non-static themes.
  const query = useFetchQuery({ key: ["themes", "template-source", themeId, themeApiVersion ?? 1, templateFilename], fetch: queryFetch }, { enabled: themeTier === "static", staleTime: 0 });
  const state: TemplateSourceFetchState = query.error ? { status: "error", message: query.error.message }
    : query.data !== undefined ? { status: "loaded", html: query.data } : { status: "loading" };

  return state;
}

/**
 * Binds the real `/theme-assets/...` fetch — see `template-source-dependencies.hooks.ts`.
 *
 * The zero-dependencies half of the `useX(dependencies)` / `useWiredX()` pair, so
 * `TemplateSourceModal.tsx` composes this and a test composes {@link useTemplateSource} with
 * `createFakeTemplateSourcePort`.
 *
 * @param themeId - See {@link useTemplateSource}.
 * @param themeTier - See {@link useTemplateSource}.
 * @param themeApiVersion - See {@link useTemplateSource}.
 * @param templateFilename - See {@link useTemplateSource}.
 * @returns The current {@link TemplateSourceFetchState}.
 */
export function useWiredTemplateSource(
  themeId: string,
  themeTier: ThemeTier | null,
  themeApiVersion: 2 | undefined,
  templateFilename: string,
): TemplateSourceFetchState {
  return useTemplateSource(themeId, themeTier, themeApiVersion, templateFilename, defaultTemplateSourcePort);
}

import { MediaContentEditor } from "./MediaContentEditor";
import { agentHandle } from "@jini-ai/agentic";
import { isUserCollection } from "../../features/collections/rules";
import type { AdminContentType, AdminFormDefinition, AdminMenu, AdminWidgetType, ContentTypeFieldKind } from "../../lib/api";
import type { Translate } from "@jini-ai/ui/panel-kit";
import { interpolate } from "@jini-ai/ui/panel-kit";
import {
  COLLECTION_DISPLAYABLE_FIELD_KINDS,
  humanizeFieldName,
  useFetchedOptions,
  useRecentEntriesConfig,
  useSocialLinksConfig,
} from "./WidgetConfigFields.hooks";
import { defaultWidgetConfigFieldsPort } from "./widget-config-fields-dependencies.hooks";

/**
 * @file Per-widget-type config sub-forms (`ui.spec.md` §2/§3.4) — one component per v1 widget type,
 * field sets read directly off `src/widgets/registry.ts`'s five `configSchema` records (no field
 * here is invented). Shared between `WidgetInstanceEditor.tsx` (full create/edit form) and
 * `WidgetPickerDialog.tsx` (the "create new" path of the reuse-vs-duplicate picker, REQ-33) so the
 * config-editing UI is defined once, not duplicated per call site.
 *
 * Client-side constraints here (maxItems range, links cap) are UX guidance only — the real
 * validator is server-side (REQ-02); a `WidgetConfigValidationError` must still be handled by the
 * caller even when these constraints appear satisfied (`ui.spec.md` §5/§8).
 *
 * Split into this file (the JSX per widget type) and `WidgetConfigFields.hooks.tsx` (the
 * data-fetching state `MenuConfigFields`/`ContactFormConfigFields` need), per the `@jini-ai/admin`
 * `<Name>.tsx`/`<Name>.hooks.tsx` extraction pattern. Unlike `Select`/`WidgetPickerDialog`, there is
 * no single hook this whole exported `WidgetConfigFields` switch renders off of — it dispatches to
 * five independent, unexported per-type sub-components, and only two of them (`MenuConfigFields`,
 * `ContactFormConfigFields`) touch IO at all. The `useFetchedOptions` seam below is threaded through
 * `WidgetConfigFields`'s own props down to those two sub-components (the same
 * `{ useFetchedOptions: useOptions = useFetchedOptions, ...props }` destructure-and-rename shape
 * `RowMenu.tsx` uses for its own `useRowMenu` prop in `@jini-ai/admin`) rather than living on a
 * component-level hook the way `Select`'s `useDropdown`/`WidgetPickerDialog`'s `useDialog` do.
 *
 * The two `fetchList` closures passed into `useFetchedOptions` read through
 * `widget-config-fields-dependencies.hooks.ts`'s `defaultWidgetConfigFieldsPort` rather than
 * `lib/api`'s `api` directly — that file is the only one in this folder that imports `api`. This
 * is a second, NESTED seam underneath the already-reachable `useFetchedOptions` prop (not a new
 * component prop of its own): a test overriding `useFetchedOptions` with a fake never calls the
 * closure at all, so the port is exercised only on the real path, the same "one seam per reachable
 * boundary" reasoning `apps/admin/INFO.md`'s Components section gives for not double-injecting
 * `useWidgetPickerDialog`'s inner `useExistingInstances`.
 *
 * ## Agent handles
 *
 * `WidgetConfigFields` itself renders exactly one of the five sub-forms below (never more than
 * one), so its own `agentHandle` prop is just forwarded to whichever type is active — the field
 * names below are then each type's own, appended as `<base>-<field>`:
 *
 * | widget type | fields |
 * |---|---|
 * | `text` | `<base>-body` |
 * | `social-links` | per row `i` (0-based): `<base>-link-<i>-platform`, `<base>-link-<i>-url`, `<base>-link-<i>-remove`; plus `<base>-add` |
 * | `recent-entries` (labeled "Collection list") | `<base>-max-items`, `<base>-collection`, `<base>-sort`, `<base>-layout`, `<base>-columns` (cards layout only), `<base>-field-<fieldName>` per checkbox, `<base>-filter-field`, `<base>-filter-value` (filter row, shown only once a collection is chosen), `<base>-category-term-id` |
 * | `menu` | `<base>-menu-ref` (a real `<select>` — `page.select_option` resolves it) |
 * | `contact-form` | `<base>-form-definition-id` (a real `<select>`), `<base>-success-message` |
 * | `media` / `gallery` | see `MediaContentEditor.tsx`'s own "Agent handles" section |
 *
 * `social-links` rows are keyed by array INDEX, not a stable id — the one deliberate exception to
 * this workspace's "never an index" list-handle rule (see `@jini-ai/agentic`'s
 * `buildAgentListHandles`). `SocialLink` (`{ platform, url }`) carries no id of its own in the
 * widget's own `configSchema` (`src/widgets/registry.ts`), and inventing one here would mean
 * changing a schema this component does not own, for a value that is re-fetched fresh on every
 * page load anyway — removing a link DOES shift every later row's handle down by one for the rest
 * of THIS editing session, a real but narrow tradeoff against redesigning a persisted schema this
 * component only renders. Every other row/list handle in this app keeps the stable-id rule.
 * `agentHandle` itself is NOT sanitized — the caller's own explicit choice of name, which fails
 * loudly at first render if invalid. Omit it and no `data-agent-*` markup is emitted at all.
 */

function textValue(config: Record<string, unknown>, key: string): string {
  const v = config[key];
  return typeof v === "string" ? v : "";
}

/** `text` (`src/widgets/registry.ts` TEXT_REGISTRATION: `{ body: string }`). */
function TextConfigFields(props: {
  config: Record<string, unknown>;
  onChange: (config: Record<string, unknown>) => void;
  agentHandle?: string;
  t: Translate;
}) {
  return (
    <div className="widget-config-fields">
      <label htmlFor="widget-field-body">{props.t("Text")}</label>
      <textarea
        id="widget-field-body"
        rows={6}
        value={textValue(props.config, "body")}
        onChange={(e) => props.onChange({ ...props.config, body: e.target.value })}
        {...(props.agentHandle ? agentHandle({ handle: `${props.agentHandle}-body` }, { role: "field", label: "Text" }) : {})}
      />
    </div>
  );
}

/** `social-links` (SOCIAL_LINKS_REGISTRATION: `{ links: [{platform,url}], max 20 }`). */
function SocialLinksConfigFields(props: {
  config: Record<string, unknown>;
  onChange: (config: Record<string, unknown>) => void;
  agentHandle?: string;
  t: Translate;
}) {
  const { links, updateLink, removeLink, addLink } = useSocialLinksConfig(props.config, props.onChange);
  const base = props.agentHandle;
  const { t } = props;

  return (
    <div className="widget-config-fields">
      <p>{t("Social links")}</p>
      {links.map((link, i) => (
        <fieldset key={i} className="widget-config-social-link-row">
          <legend>{interpolate({ template: t("Link {n}"), vars: { n: i + 1 } })}</legend>
          <label htmlFor={`widget-social-platform-${i}`}>{t("Platform")}</label>
          <input
            id={`widget-social-platform-${i}`}
            value={link.platform}
            onChange={(e) => updateLink(i, { platform: e.target.value })}
            placeholder={t("e.g. a project link")}
            {...(base ? agentHandle({ handle: `${base}-link-${i}-platform` }, { role: "field", label: `Link ${i + 1} platform` }) : {})}
          />
          <label htmlFor={`widget-social-url-${i}`}>{t("URL")}</label>
          <input
            id={`widget-social-url-${i}`}
            value={link.url}
            onChange={(e) => updateLink(i, { url: e.target.value })}
            placeholder={t("https://…")}
            {...(base ? agentHandle({ handle: `${base}-link-${i}-url` }, { role: "field", label: `Link ${i + 1} URL` }) : {})}
          />
          <button
            type="button"
            onClick={() => removeLink(i)}
            {...(base ? agentHandle({ handle: `${base}-link-${i}-remove` }, { role: "button", label: `Remove link ${i + 1}` }) : {})}
          >
            {t("Remove")}
          </button>
        </fieldset>
      ))}
      <button
        type="button"
        onClick={addLink}
        disabled={links.length >= 20}
        {...(base ? agentHandle({ handle: `${base}-add` }, { role: "button", label: "Add a social link" }) : {})}
      >
        {t("Add link")}
      </button>
    </div>
  );
}

/** A displayable field of the chosen collection's content type (never `relation`/`json` — see
 *  `COLLECTION_DISPLAYABLE_FIELD_KINDS`), as the four sub-controls below need it. */
type DisplayableField = AdminContentType["fields"][number];

/** `base ? agentHandle(...) : {}`, factored out so `RecentEntriesConfigFields` (four fields of its
 *  own, on top of its four sub-components) doesn't count one branch per field for this — every
 *  other sub-component in this file still writes the ternary inline, since none of them repeats it
 *  often enough to threaten the complexity ceiling. */
function maybeAgentHandle(base: string | undefined, suffix: string, opts: { role: "field" | "button"; label: string }) {
  return base ? agentHandle({ handle: `${base}-${suffix}` }, opts) : {};
}

/** `collections?.find((ct) => ct.key === key) ?? null`, pulled out for the same reason as
 *  {@link maybeAgentHandle} — one call site, not two branches, in `RecentEntriesConfigFields`. */
function findContentType(collections: AdminContentType[] | null, key: string): AdminContentType | null {
  if (collections === null) return null;
  return collections.find((ct) => ct.key === key) ?? null;
}

/** A displayable field's name, reduced to what `agentHandle` actually accepts: lowercase letters
 *  and digits joined by single hyphens (`@jini-ai/agentic`'s `HANDLE_PATTERN`). Content-type field
 *  names are operator-chosen and commonly snake_case — `docs_page`, the very field this file's own
 *  `tovu_feature` example collection carries — which `agentHandle` throws on verbatim. Used only
 *  for the handle text; the visible label still goes through {@link humanizeFieldName}. */
function fieldHandleSegment(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}

/** The Collection `<select>` — its own component because the loading/error states from
 *  `useFetchedOptions` (mirrors `MenuConfigFields`) replace the whole field, label included, with
 *  a notice, the same shape `MenuConfigFields`/`ContactFormConfigFields` already use. */
function CollectionSelect(props: {
  collections: AdminContentType[] | null;
  error: string | null;
  value: string;
  onChange: (value: string) => void;
  base?: string;
  t: Translate;
}) {
  if (props.error) return <div className="notice error">{props.error}</div>;
  return (
    <>
      <label htmlFor="widget-field-collection">{props.t("Collection")}</label>
      <select
        id="widget-field-collection"
        value={props.value}
        disabled={!props.collections}
        onChange={(e) => props.onChange(e.target.value)}
        {...(props.base ? agentHandle({ handle: `${props.base}-collection` }, { role: "field", label: "Collection" }) : {})}
      >
        <option value="">{props.t("All collections")}</option>
        {(props.collections ?? []).map((ct) => (
          <option key={ct.key} value={ct.key}>
            {ct.label}
          </option>
        ))}
      </select>
    </>
  );
}

/** Sort — the three built-in options plus ascending/descending per displayable field (empty
 *  before a collection is chosen, so it degrades to just the built-ins). */
function SortSelect(props: { value: string; fields: readonly DisplayableField[]; onChange: (value: string) => void; base?: string; t: Translate }) {
  return (
    <>
      <label htmlFor="widget-field-sort">{props.t("Sort")}</label>
      <select
        id="widget-field-sort"
        value={props.value}
        onChange={(e) => props.onChange(e.target.value)}
        {...(props.base ? agentHandle({ handle: `${props.base}-sort` }, { role: "field", label: "Sort" }) : {})}
      >
        <option value="">{props.t("Default (recently updated)")}</option>
        <option value="newest">{props.t("Newest first")}</option>
        <option value="oldest">{props.t("Oldest first")}</option>
        <option value="title">{props.t("Title (A–Z)")}</option>
        {props.fields.map((f) => (
          <option key={f.name} value={f.name}>
            {interpolate({ template: props.t("{field} (ascending)"), vars: { field: humanizeFieldName(f.name) } })}
          </option>
        ))}
        {props.fields.map((f) => (
          <option key={`-${f.name}`} value={`-${f.name}`}>
            {interpolate({ template: props.t("{field} (descending)"), vars: { field: humanizeFieldName(f.name) } })}
          </option>
        ))}
      </select>
    </>
  );
}

/** One checkbox per displayable field of the chosen collection, only rendered once one is chosen
 *  (there is no single field list to check boxes against for "All collections"). */
function FieldsCheckboxes(props: {
  fields: readonly DisplayableField[];
  selected: readonly string[];
  onToggle: (name: string, checked: boolean) => void;
  base?: string;
  t: Translate;
}) {
  return (
    <fieldset className="widget-config-fields-checkboxes">
      <legend>{props.t("Fields to show")}</legend>
      {props.fields.map((f) => (
        <label key={f.name} htmlFor={`widget-field-field-${f.name}`}>
          <input
            id={`widget-field-field-${f.name}`}
            type="checkbox"
            checked={props.selected.includes(f.name)}
            onChange={(e) => props.onToggle(f.name, e.target.checked)}
            {...(props.base ? agentHandle({ handle: `${props.base}-field-${fieldHandleSegment(f.name)}` }, { role: "field", label: `Show ${f.name}` }) : {})}
          />
          {humanizeFieldName(f.name)}
        </label>
      ))}
    </fieldset>
  );
}

/** The one supported filter row (field + value, plan A1) — the value input only appears once a
 *  field is picked, and its raw text is coerced against that field's own kind (boolean/number). */
function FilterRow(props: {
  fields: readonly DisplayableField[];
  field: string;
  value: string;
  onFieldChange: (name: string) => void;
  onValueChange: (raw: string, kind: ContentTypeFieldKind | undefined) => void;
  base?: string;
  t: Translate;
}) {
  const kind = props.fields.find((f) => f.name === props.field)?.kind;
  return (
    <div className="widget-config-filter-row">
      <label htmlFor="widget-field-filter-field">{props.t("Filter")}</label>
      <select
        id="widget-field-filter-field"
        value={props.field}
        onChange={(e) => props.onFieldChange(e.target.value)}
        {...(props.base ? agentHandle({ handle: `${props.base}-filter-field` }, { role: "field", label: "Filter field" }) : {})}
      >
        <option value="">{props.t("No filter")}</option>
        {props.fields.map((f) => (
          <option key={f.name} value={f.name}>
            {humanizeFieldName(f.name)}
          </option>
        ))}
      </select>
      {props.field && (
        <>
          <label htmlFor="widget-field-filter-value">{props.t("Filter value")}</label>
          <input
            id="widget-field-filter-value"
            value={props.value}
            placeholder={props.t("Value")}
            onChange={(e) => props.onValueChange(e.target.value, kind)}
            {...(props.base ? agentHandle({ handle: `${props.base}-filter-value` }, { role: "field", label: "Filter value" }) : {})}
          />
        </>
      )}
    </div>
  );
}

/**
 * `recent-entries` (RECENT_ENTRIES_REGISTRATION), labeled "Collection list" in this UI (R1 renamed
 * the widget's behavior, not its type key — `widgetType`/stored config are unaffected). Fetches
 * the content-type registry itself, the same `useFetchedOptions` seam `MenuConfigFields`/
 * `ContactFormConfigFields` use, filtered to `isUserCollection` (system types never appear here —
 * A2's own rule). All config mutation lives in `useRecentEntriesConfig`
 * (`WidgetConfigFields.hooks.tsx`); the Collection/Sort/Fields/Filter controls each live in their
 * own small component above (this function was over the complexity ceiling as one block) — this
 * function only assembles them.
 *
 * "All collections" (an empty `collection`) keeps today's behavior: every user content type,
 * newest-updated first (D7). Fields/Filter are per-content-type, so both are hidden until a
 * specific collection is chosen — there is no single field list to check boxes against otherwise.
 */
function RecentEntriesConfigFields({
  useFetchedOptions: useOptions = useFetchedOptions,
  t,
  ...props
}: {
  config: Record<string, unknown>;
  onChange: (config: Record<string, unknown>) => void;
  agentHandle?: string;
  t: Translate;
} & FetchedOptionsSeam) {
  const maxItems = typeof props.config.maxItems === "number" ? props.config.maxItems : 5;
  const base = props.agentHandle;
  const { items: collections, error: collectionsError } = useOptions<AdminContentType>(
    { fetchList: () => defaultWidgetConfigFieldsPort.listContentTypes().then((r) => r.items.filter((ct) => isUserCollection(ct.key))), key: ["collections", "options"] },
    { errorFallback: t("failed to load collections") },
  );
  const c = useRecentEntriesConfig(props.config, props.onChange);
  const selectedType = findContentType(collections, c.collection);
  const displayableFields = selectedType ? selectedType.fields.filter((f) => COLLECTION_DISPLAYABLE_FIELD_KINDS.has(f.kind)) : [];
  const showFieldsAndFilter = selectedType !== null && displayableFields.length > 0;

  return (
    <div className="widget-config-fields">
      <label htmlFor="widget-field-maxItems">{t("Max items")}</label>
      <input
        id="widget-field-maxItems"
        type="number"
        min={1}
        max={20}
        step={1}
        value={maxItems}
        onChange={(e) => props.onChange({ ...props.config, maxItems: e.target.value === "" ? undefined : Number(e.target.value) })}
        {...maybeAgentHandle(base, "max-items", { role: "field", label: "Max items" })}
      />

      <CollectionSelect collections={collections} error={collectionsError} value={c.collection} onChange={c.setCollection} base={base} t={t} />

      <SortSelect value={c.sort} fields={displayableFields} onChange={c.setSort} base={base} t={t} />

      <label htmlFor="widget-field-layout">{t("Layout")}</label>
      <select
        id="widget-field-layout"
        value={c.layout}
        onChange={(e) => c.setLayout(e.target.value)}
        {...maybeAgentHandle(base, "layout", { role: "field", label: "Layout" })}
      >
        <option value="">{t("Default (cards)")}</option>
        <option value="cards">{t("Cards")}</option>
        <option value="list">{t("List")}</option>
      </select>

      {c.layout !== "list" && (
        <>
          <label htmlFor="widget-field-columns">{t("Columns")}</label>
          <input
            id="widget-field-columns"
            type="number"
            min={1}
            max={6}
            step={1}
            value={c.columns}
            onChange={(e) => c.setColumns(e.target.value)}
            {...maybeAgentHandle(base, "columns", { role: "field", label: "Columns" })}
          />
        </>
      )}

      {showFieldsAndFilter && <FieldsCheckboxes fields={displayableFields} selected={c.fields} onToggle={c.toggleField} base={base} t={t} />}

      {showFieldsAndFilter && (
        <FilterRow fields={displayableFields} field={c.filterField} value={c.filterValue} onFieldChange={c.setFilterField} onValueChange={c.setFilterValue} base={base} t={t} />
      )}

      {/* REQ-32/EC-03: a documented soft reference — plain text input, no taxonomy-term picker exists yet in this admin app. */}
      <label htmlFor="widget-field-categoryTermId">{t("Category term id (optional)")}</label>
      <input
        id="widget-field-categoryTermId"
        value={textValue(props.config, "categoryTermId")}
        onChange={(e) => props.onChange({ ...props.config, categoryTermId: e.target.value || undefined })}
        {...maybeAgentHandle(base, "category-term-id", { role: "field", label: "Category term id" })}
      />
    </div>
  );
}

interface FetchedOptionsSeam {
  /** Injectable seam for this sub-component's data-fetching hook. Defaults to the real
   *  {@link useFetchedOptions}; a test can pass a fake here to exercise rendering without the real
   *  `api.listMenus`/`api.listForms` fetch. */
  useFetchedOptions?: typeof useFetchedOptions;
}

/** `menu` (MENU_REGISTRATION: `{ menuRef: string }`) — dropdown over `api.listMenus()`, mirrors
 * `Seo.tsx`'s `EntryPicker` exactly. */
function MenuConfigFields({
  useFetchedOptions: useOptions = useFetchedOptions,
  t,
  ...props
}: {
  config: Record<string, unknown>;
  onChange: (config: Record<string, unknown>) => void;
  agentHandle?: string;
  t: Translate;
} & FetchedOptionsSeam) {
  const { items: menus, error } = useOptions<AdminMenu>(
    { fetchList: () => defaultWidgetConfigFieldsPort.listMenus().then((r) => r.menus), key: ["menus", "options"] },
    { errorFallback: t("failed to load menus") },
  );

  if (error) return <div className="notice error">{error}</div>;
  if (!menus) return <div className="notice">{t("Loading menus…")}</div>;

  return (
    <div className="widget-config-fields">
      <label htmlFor="widget-field-menuRef">{t("Menu")}</label>
      <select
        id="widget-field-menuRef"
        value={textValue(props.config, "menuRef")}
        onChange={(e) => props.onChange({ ...props.config, menuRef: e.target.value })}
        {...(props.agentHandle
          ? agentHandle({ handle: `${props.agentHandle}-menu-ref` }, {
              role: "field",
              label: "Menu — set with page.select_option, not click",
            })
          : {})}
      >
        <option value="">{t("Choose a menu…")}</option>
        {menus.map((menu) => (
          <option key={menu.id} value={menu.id}>
            {menu.title} ({menu.status})
          </option>
        ))}
      </select>
    </div>
  );
}

/** `contact-form` (CONTACT_FORM_REGISTRATION: `{ formDefinitionId: string, successMessage? }`) —
 * dropdown over `api.listForms()`; each option discloses `status` inline (REQ-38 — an operator
 * shouldn't be surprised later by the disabled-form placeholder render). */
function ContactFormConfigFields({
  useFetchedOptions: useOptions = useFetchedOptions,
  t,
  ...props
}: {
  config: Record<string, unknown>;
  onChange: (config: Record<string, unknown>) => void;
  agentHandle?: string;
  t: Translate;
} & FetchedOptionsSeam) {
  const { items: forms, error } = useOptions<AdminFormDefinition>(
    { fetchList: () => defaultWidgetConfigFieldsPort.listForms().then((r) => r.data), key: ["forms", "options"] },
    { errorFallback: t("failed to load forms") },
  );

  if (error) return <div className="notice error">{error}</div>;
  if (!forms) return <div className="notice">{t("Loading forms…")}</div>;

  return (
    <div className="widget-config-fields">
      <label htmlFor="widget-field-formDefinitionId">{t("Form")}</label>
      <select
        id="widget-field-formDefinitionId"
        value={textValue(props.config, "formDefinitionId")}
        onChange={(e) => props.onChange({ ...props.config, formDefinitionId: e.target.value })}
        {...(props.agentHandle
          ? agentHandle({ handle: `${props.agentHandle}-form-definition-id` }, {
              role: "field",
              label: "Form — set with page.select_option, not click",
            })
          : {})}
      >
        <option value="">{t("Choose a form…")}</option>
        {forms.map((form) => (
          <option key={form.id} value={form.id}>
            {form.name} — {form.status}
          </option>
        ))}
      </select>
      <label htmlFor="widget-field-successMessage">{t("Success message (optional)")}</label>
      <input
        id="widget-field-successMessage"
        value={textValue(props.config, "successMessage")}
        onChange={(e) => props.onChange({ ...props.config, successMessage: e.target.value || undefined })}
        {...(props.agentHandle
          ? agentHandle({ handle: `${props.agentHandle}-success-message` }, { role: "field", label: "Success message" })
          : {})}
      />
    </div>
  );
}

export function WidgetConfigFields(
  props: {
    widgetType: AdminWidgetType;
    config: Record<string, unknown>;
    onChange: (config: Record<string, unknown>) => void;
    /** This sub-form's own base handle — see this file's "Agent handles" doc for the per-type
     *  field list. Forwarded as-is to whichever of the five sub-forms below is active; omit to
     *  leave every field untagged. */
    agentHandle?: string;
    /** Translates this component's own per-type static copy (field labels/placeholders, the
     *  `menu`/`contact-form` sub-forms' loading/error/empty-option text) —
     *  `components/shared-components-i18n.ts`'s dictionary. Same optional-with-passthrough-default
     *  convention as `Select.tsx`'s `t` prop: `WidgetConfigFields` has no hook of its own to resolve
     *  a locale from (see this file's header), so its callers bind one — `WidgetPickerDialog.tsx`
     *  reuses its own dialog `t`, `WidgetInstanceEditor.tsx` builds a second `t` off this same
     *  dictionary since its own `t` is bound to `widgets-i18n.ts` instead. Omit (or a test) and every
     *  sub-form renders the English source strings unchanged. */
    t?: Translate;
  } & FetchedOptionsSeam
) {
  const { t = (key: string) => key } = props;
  switch (props.widgetType) {
    // Gallery is a compatibility alias over the media widget's resolver (mediawidget contract), so
    // both get the same two-tab Media / Raw HTML editor; legacy `images` configs are read in place.
    case "media":
    case "gallery":
      return <MediaContentEditor widgetType={props.widgetType} config={props.config} onChange={props.onChange} t={t} agentHandle={props.agentHandle} />;
    case "text":
      return <TextConfigFields config={props.config} onChange={props.onChange} agentHandle={props.agentHandle} t={t} />;
    case "social-links":
      return <SocialLinksConfigFields config={props.config} onChange={props.onChange} agentHandle={props.agentHandle} t={t} />;
    case "recent-entries":
      return (
        <RecentEntriesConfigFields
          config={props.config}
          onChange={props.onChange}
          agentHandle={props.agentHandle}
          useFetchedOptions={props.useFetchedOptions}
          t={t}
        />
      );
    case "menu":
      return (
        <MenuConfigFields
          config={props.config}
          onChange={props.onChange}
          agentHandle={props.agentHandle}
          useFetchedOptions={props.useFetchedOptions}
          t={t}
        />
      );
    case "contact-form":
      return (
        <ContactFormConfigFields
          config={props.config}
          onChange={props.onChange}
          agentHandle={props.agentHandle}
          useFetchedOptions={props.useFetchedOptions}
          t={t}
        />
      );
    default:
      return null;
  }
}

/** The five closed v1 type keys (REQ-09) — a client-side constant, mirroring
 * `MenuEditor.tsx`'s equally-closed, equally-hardcoded `AdminMenuTargetKind` `<select>` options; no
 * server round-trip to "list widget types" exists or is needed for v1 (`ui.spec.md` §5). */
export const WIDGET_TYPE_OPTIONS: Array<{ value: AdminWidgetType; label: string }> = [
  { value: "media", label: "Media" },
  { value: "gallery", label: "Gallery" },
  { value: "text", label: "Text" },
  { value: "social-links", label: "Social Links" },
  { value: "recent-entries", label: "Collection list" },
  { value: "menu", label: "Menu" },
  { value: "contact-form", label: "Contact Form" },
];

/** Default (empty-but-valid-shaped) config per type, for a freshly-opened create form. */
export function defaultWidgetConfig(widgetType: AdminWidgetType): Record<string, unknown> {
  switch (widgetType) {
    case "media":
      return { mode: "media", items: [], layout: "single" };
    case "gallery":
      return { images: [], layout: "grid", columns: 3 };
    case "text":
      return { body: "" };
    case "social-links":
      return { links: [] };
    case "recent-entries":
      return { maxItems: 5 };
    case "menu":
      return { menuRef: "" };
    case "contact-form":
      return { formDefinitionId: "" };
    default:
      return {};
  }
}

import type { AdminMedia } from "../../lib/api";
import { parseMediaHtmlAttributes } from "../../features/media/rules";

/**
 * @file Pure rules behind `MediaContentEditor` — the two-tab ("Media" / "Raw HTML") editor for a
 * `media` widget's config, a `gallery` widget's config (Gallery is a compatibility alias over the
 * same Jini resolver), and a `widgetEmbed` node's per-placement `content` override. The shapes are
 * the mediawidget server contract (`ADS-memory/.local-artifacts/codex/2026-10-10-16/w8-out/
 * mediawidget-CONTRACT.md`); the server's `parseGalleryConfig` stays the real validator — every
 * check here is UX guidance that mirrors it, never a second source of truth.
 *
 * No React and no I/O, so every branch is asserted directly (`media-content-rules.unit.test.ts`).
 */

/** Contract cap on structured items (`MAX_GALLERY_IMAGES` on the server). */
export const MAX_MEDIA_ITEMS = 50;
/** Contract cap on `html` in the Raw HTML mode. */
export const MAX_MEDIA_HTML_LENGTH = 65_536;
/** Contract bound on a library slug used as a lookup key. */
const MAX_SLUG_LENGTH = 200;

export type MediaContentMode = "media" | "html";
export type MediaLayout = "single" | "grid" | "carousel" | "masonry";

/** Layouts the structured tab offers, in toolbar order. A saved `gallery` widget's own
 *  `configSchema` enum has no `single` (Jini `registry.ts`), so the gallery alias drops it. */
export function mediaLayoutsFor(widgetType: string): readonly MediaLayout[] {
  return widgetType === "gallery" ? ["grid", "carousel", "masonry"] : ["single", "grid", "carousel", "masonry"];
}

/** Columns only mean something when more than one item sits side by side. */
export function layoutUsesColumns(layout: MediaLayout): boolean {
  return layout !== "single";
}

export interface MediaItem {
  slug: string;
  alt?: string;
  caption?: string;
}

/** The structured tab's whole state — everything `{ mode: "media" }` config carries. */
export interface MediaDraft {
  items: MediaItem[];
  layout: MediaLayout;
  columns?: number;
  aspectRatio?: string;
  cssClass?: string;
  htmlAttributes?: string;
}

/** Both tabs' content, read once from a config. Only one is ever saved (see {@link toMediaConfig}). */
export interface MediaContentState {
  mode: MediaContentMode;
  media: MediaDraft;
  html: string;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function optionalString(value: unknown): string | undefined {
  return typeof value === "string" ? value : undefined;
}

/** A row for `slug` carrying the record's string `alt`/`caption` and nothing else. */
function itemWithText(slug: string, record: Record<string, unknown>): MediaItem {
  const item: MediaItem = { slug };
  const alt = optionalString(record.alt);
  const caption = optionalString(record.caption);
  if (alt !== undefined) item.alt = alt;
  if (caption !== undefined) item.caption = caption;
  return item;
}

/** Copies only the keys a structured item may carry — never `src`/`mediaId` (contract). */
function readItem(value: unknown): MediaItem[] {
  return isRecord(value) && typeof value.slug === "string" ? [itemWithText(value.slug, value)] : [];
}

/**
 * Legacy Gallery configs store `images: [{ mediaId, alt, caption }]` by asset id. New content is
 * slug-first, so each image is mapped to its library slug; an id the library no longer has keeps
 * the id as its slug so the row stays visible (flagged "not in the media library") instead of
 * silently vanishing from the operator's list.
 *
 * @complexity O(n + m) for n images and m library assets (one id index).
 */
export function legacyImagesToItems(required: { images: unknown[]; library: readonly AdminMedia[] | null }): MediaItem[] {
  const slugById = new Map((required.library ?? []).map((asset) => [asset.id, asset.slug]));
  return required.images.flatMap((image) => {
    if (!isRecord(image) || typeof image.mediaId !== "string") return [];
    return [itemWithText(slugById.get(image.mediaId) ?? image.mediaId, image)];
  });
}

/** An explicit `mode` wins; a mode-less config is Raw HTML only when it carries an `html` string. */
function readMode(config: Record<string, unknown>): MediaContentMode {
  return config.mode === "html" || (config.mode === undefined && typeof config.html === "string") ? "html" : "media";
}

/** Structured `items` win over legacy `images`; neither means an empty list. */
function readItems(config: Record<string, unknown>, library: readonly AdminMedia[] | null): MediaItem[] {
  if (Array.isArray(config.items)) return config.items.flatMap(readItem);
  return Array.isArray(config.images) ? legacyImagesToItems({ images: config.images, library }) : [];
}

/**
 * Reads any accepted config (new `mode` content, mode-less `items`/`html`, or legacy `images`) into
 * both tabs' state. The inactive tab starts empty; the default layout follows the widget type.
 *
 * @complexity O(n + m) — see {@link legacyImagesToItems}.
 */
export function readMediaContent(
  required: { config: Record<string, unknown>; widgetType: string },
  optional: { library?: readonly AdminMedia[] | null } = {},
): MediaContentState {
  const { config, widgetType } = required;
  const mode = readMode(config);
  const layouts = mediaLayoutsFor(widgetType);
  const layout = layouts.find((candidate) => candidate === config.layout) ?? layouts[0]!;
  const media: MediaDraft = { items: readItems(config, optional.library ?? null), layout };
  if (typeof config.columns === "number") media.columns = config.columns;
  for (const key of ["aspectRatio", "cssClass", "htmlAttributes"] as const) {
    const value = optionalString(config[key]);
    if (value !== undefined) media[key] = value;
  }
  return { mode, media, html: mode === "html" ? optionalString(config.html) ?? "" : "" };
}

/**
 * The complete replacement config for the ACTIVE tab only — the contract says "do not retain
 * inactive-mode data in a replacement config", so switching to Raw HTML and saving drops the item
 * list, and vice versa. Blank optional strings are omitted rather than saved as `""`.
 *
 * @complexity O(n) over items (a shallow copy).
 */
export function toMediaConfig(required: { state: MediaContentState }): Record<string, unknown> {
  const { state } = required;
  if (state.mode === "html") return { mode: "html", html: state.html };
  const { media } = state;
  const config: Record<string, unknown> = { mode: "media", items: media.items.map((item) => ({ ...item })), layout: media.layout };
  if (media.columns !== undefined && layoutUsesColumns(media.layout)) config.columns = media.columns;
  for (const key of ["aspectRatio", "cssClass", "htmlAttributes"] as const) {
    const value = media[key]?.trim();
    if (value) config[key] = value;
  }
  return config;
}

/** Whether a tab holds anything that saving the OTHER tab would discard. */
export function hasModeContent(required: { state: MediaContentState; mode: MediaContentMode }): boolean {
  return required.mode === "html" ? required.state.html.trim() !== "" : required.state.media.items.length > 0;
}

/** Each tab's content as last seen in the editor, kept locally so flipping tabs loses nothing. */
export interface MediaContentStash {
  media?: MediaDraft;
  html?: string;
}

/** `viewMode` set and different from the stored mode: a tab is shown that nothing was typed in yet. */
function isPendingView(stored: MediaContentState, viewMode: MediaContentMode | null): viewMode is MediaContentMode {
  return viewMode !== null && viewMode !== stored.mode;
}

/**
 * What the editor shows. Switching to an EMPTY tab does not touch the config (owner, 2026-10-11:
 * "Leave site?" appeared after only flipping Media ↔ Raw HTML), so until the first edit there the
 * shown tab (`viewMode`) differs from the stored one and its content comes from the stash. Every
 * edit emits this view, which is what commits the new tab.
 *
 * @param required.stored - The config as read by {@link readMediaContent}.
 * @param required.viewMode - The tab shown without a config change, or `null`.
 * @param required.stash - {@link MediaContentStash}.
 * @returns The state the tabs render and edit.
 */
export function viewedMediaContent(required: { stored: MediaContentState; viewMode: MediaContentMode | null; stash: MediaContentStash }): MediaContentState {
  const { stored, viewMode, stash } = required;
  if (!isPendingView(stored, viewMode)) return stored;
  if (viewMode === "html") return { ...stored, mode: "html", html: stash.html ?? "" };
  return { ...stored, mode: "media", media: stash.media ?? stored.media };
}

/**
 * One tab switch. Back to the stored tab: only the view changes. To the other tab: the stored tab
 * is stashed, then the switch emits only when the target tab holds content (saving it really would
 * change the config); an empty target is just shown (`viewMode`) until something is typed there.
 *
 * @param required.stored - The config as read by {@link readMediaContent}.
 * @param required.stash - {@link MediaContentStash}.
 * @param required.mode - The tab being switched to (never the one already shown).
 * @returns The next stash and view, and the state to emit (`null` = leave the config alone).
 */
export function switchMediaContentMode(required: { stored: MediaContentState; stash: MediaContentStash; mode: MediaContentMode }): {
  stash: MediaContentStash; viewMode: MediaContentMode | null; emit: MediaContentState | null;
} {
  const { stored, stash, mode } = required;
  if (mode === stored.mode) return { stash, viewMode: null, emit: null };
  const nextStash = stored.mode === "html" ? { ...stash, html: stored.html } : { ...stash, media: stored.media };
  const target: MediaContentState = { mode, media: nextStash.media ?? stored.media, html: nextStash.html ?? stored.html };
  return hasModeContent({ state: target, mode }) ? { stash: nextStash, viewMode: null, emit: target } : { stash: nextStash, viewMode: mode, emit: null };
}

/**
 * Whether saving now would drop the hidden tab's content — the "Saving keeps only this tab"
 * notice. Never while an untouched tab is shown: the save then keeps the stored tab, so nothing
 * is lost.
 */
export function inactiveTabWillBeDropped(required: { stored: MediaContentState; viewMode: MediaContentMode | null; stash: MediaContentStash }): boolean {
  const { stored, viewMode, stash } = required;
  if (isPendingView(stored, viewMode)) return false;
  const other: MediaContentMode = stored.mode === "html" ? "media" : "html";
  return hasModeContent({ state: { mode: other, media: stash.media ?? { ...stored.media, items: [] }, html: stash.html ?? "" }, mode: other });
}

/** Moves the item at `from` to `to` (both clamped to the list). Returns the same array when the
 *  move is a no-op so callers can skip an update. @complexity O(n). */
export function moveMediaItem(required: { items: MediaItem[]; from: number; to: number }): MediaItem[] {
  const { items, from } = required;
  const to = Math.max(0, Math.min(items.length - 1, required.to));
  if (from < 0 || from >= items.length || from === to) return items;
  const next = items.slice();
  const [moved] = next.splice(from, 1);
  next.splice(to, 0, moved!);
  return next;
}

/** Why a slug cannot be added (or saved in a row), or `null` when it can. */
export type MediaSlugProblem = "empty" | "invalid" | "duplicate" | "unknown" | "full";

/**
 * Whether an unfocused slug box may show the slug's END (`direction: rtl` in
 * `media-content-editor.css`). Rows' slugs often share a long start, so the end is what tells them
 * apart. Safe only when the slug starts with a letter and ends with a letter or digit: then every
 * character resolves left-to-right and RTL just moves the overflow. A leading digit or a trailing
 * hyphen would be visibly reordered ("2024-gala" shown as "gala-2024"), so those keep the plain box.
 */
export function slugCanShowEnd(slug: string): boolean {
  return /^[a-z](?:.*[a-z0-9])?$/is.test(slug);
}

/** The server's slug key rule: nonempty, at most 200 characters, no slash or whitespace. */
export function isValidMediaSlug(slug: string): boolean {
  return slug.length > 0 && slug.length <= MAX_SLUG_LENGTH && !/[\s/]/.test(slug);
}

/**
 * Checks one slug before it joins the list. `library === null` (still loading) skips the
 * "unknown" check — an unknown slug is only a render diagnostic on the server, never a save error,
 * so the editor must not block on a library it has not seen yet.
 *
 * @complexity O(n + m) for n items and m library assets.
 */
export function mediaSlugProblem(required: { slug: string; items: readonly MediaItem[]; library: readonly AdminMedia[] | null }): MediaSlugProblem | null {
  const slug = required.slug.trim();
  if (slug === "") return "empty";
  if (!isValidMediaSlug(slug)) return "invalid";
  if (required.items.length >= MAX_MEDIA_ITEMS) return "full";
  if (required.items.some((item) => item.slug === slug)) return "duplicate";
  if (required.library && !required.library.some((asset) => asset.slug === slug)) return "unknown";
  return null;
}

/**
 * Appends library picks (by slug) in pick order, skipping slugs already listed and anything past
 * the 50-item cap. Library alt/caption are NOT copied: an omitted alt already falls back to the
 * library's alt at render time (contract), and copying would freeze today's text into the widget.
 *
 * @complexity O(n + k) for n existing items and k picks.
 */
export function appendMediaSlugs(required: { items: MediaItem[]; slugs: readonly string[] }): MediaItem[] {
  const seen = new Set(required.items.map((item) => item.slug));
  const next = required.items.slice();
  for (const slug of required.slugs) {
    if (next.length >= MAX_MEDIA_ITEMS) break;
    if (seen.has(slug)) continue;
    seen.add(slug);
    next.push({ slug });
  }
  return next;
}

export type MediaKind = "image" | "video" | "audio" | "unknown";

/** Which thumbnail a row shows: a real image, or an icon for video/audio. */
export function mediaKindOf(contentType: string | null | undefined): MediaKind {
  if (!contentType) return "unknown";
  if (contentType.startsWith("image/")) return "image";
  if (contentType.startsWith("video/")) return "video";
  if (contentType.startsWith("audio/")) return "audio";
  return "unknown";
}

/** One editable `name = value` row of the HTML attributes section. */
export interface HtmlAttributeRow {
  name: string;
  value: string;
}

/** Same loose token shape as `features/media/rules.ts`'s `HTML_ATTRIBUTE_TOKEN` (not exported
 *  there): `name`, or `name="value"` / `name='value'` / `name=value`. */
const ATTRIBUTE_TOKEN = /([^\s="']+)(?:=(?:"([^"]*)"|'([^']*)'|([^\s"']+)))?/g;

/** Values are stored as typed; only a double quote inside a double-quoted value is escaped. */
function decodeAttributeValue(value: string): string {
  return value.replace(/&quot;/g, '"');
}

/** Quotes one value: double quotes, or single quotes when it holds `"` but no `'`, else `&quot;`. */
function quoteAttributeValue(value: string): string {
  if (!value.includes('"')) return `"${value}"`;
  if (!value.includes("'")) return `'${value}'`;
  return `"${value.replace(/"/g, "&quot;")}"`;
}

/**
 * Splits the stored `htmlAttributes` string into rows, keeping EVERY token — including ones the
 * renderer will drop — so the operator sees and can fix them. Text the tokenizer cannot read
 * (a stray quote) becomes one row with the fragment as its name, so nothing typed is lost.
 *
 * @complexity O(n) in the string length (one regex pass).
 */
export function htmlAttributesToRows(text: string | undefined): HtmlAttributeRow[] {
  const source = (text ?? "").trim();
  const rows: HtmlAttributeRow[] = [];
  ATTRIBUTE_TOKEN.lastIndex = 0;
  let consumed = 0;
  for (let match = ATTRIBUTE_TOKEN.exec(source); match !== null; match = ATTRIBUTE_TOKEN.exec(source)) {
    const skipped = source.slice(consumed, match.index).trim();
    if (skipped !== "") rows.push({ name: skipped, value: "" });
    consumed = match.index + match[0].length;
    rows.push({ name: match[1]!, value: decodeAttributeValue(match[2] ?? match[3] ?? match[4] ?? "") });
  }
  const trailing = source.slice(consumed).trim();
  if (trailing !== "") rows.push({ name: trailing, value: "" });
  return rows;
}

/**
 * Joins rows back into the stored string: `name="value"` (quoted per {@link quoteAttributeValue}), a bare `name` for an
 * empty value (a boolean attribute), rows without a name skipped. Inverse of
 * {@link htmlAttributesToRows} for every well-formed row list.
 *
 * @complexity O(total row text).
 */
export function rowsToHtmlAttributes(rows: readonly HtmlAttributeRow[]): string {
  return rows
    .filter((row) => row.name.trim() !== "")
    .map((row) => {
      const name = row.name.trim();
      return row.value === "" ? name : `${name}=${quoteAttributeValue(row.value)}`;
    })
    .join(" ");
}

/** Whether the renderer's allowlist will drop this row (event handler, unsafe URL/style, a name
 *  off the list) — reuses the media attribute validator rather than a second allowlist. */
export function isDroppedAttributeRow(row: HtmlAttributeRow): boolean {
  if (row.name.trim() === "") return false;
  return parseMediaHtmlAttributes(rowsToHtmlAttributes([row])).error !== null;
}

/**
 * The markup "Insert media…" drops into Raw HTML for one library asset: slug-first, never a URL
 * (contract: `data-media-slug` fills src, srcset, alt and size at render time). Authored alt is
 * included for images because it overrides the stored fallback and keeps the source readable.
 */
export function mediaSnippetFor(required: { slug: string; alt?: string; contentType?: string | null }): string {
  const slug = required.slug.replace(/&/g, "&amp;").replace(/"/g, "&quot;");
  const kind = mediaKindOf(required.contentType);
  if (kind === "video") return `<video data-media-slug="${slug}" controls></video>`;
  if (kind === "audio") return `<audio data-media-slug="${slug}" controls></audio>`;
  const alt = (required.alt ?? "").replace(/&/g, "&amp;").replace(/"/g, "&quot;");
  return `<img data-media-slug="${slug}" alt="${alt}">`;
}

/** Replaces `[start, end)` of `text` with `insert` and returns the new text plus the caret after
 *  it. Out-of-range positions clamp to the text. @complexity O(n). */
export function insertAtSelection(required: { text: string; start: number; end: number; insert: string }): { text: string; caret: number } {
  const start = Math.max(0, Math.min(required.text.length, required.start));
  const end = Math.max(start, Math.min(required.text.length, required.end));
  return { text: required.text.slice(0, start) + required.insert + required.text.slice(end), caret: start + required.insert.length };
}

/** Line count for the Raw HTML gutter (an empty text is still one line). */
export function lineCount(text: string): number {
  let count = 1;
  for (let i = 0; i < text.length; i++) if (text.charCodeAt(i) === 10) count++;
  return count;
}

import { Dialog } from "@jini-ai/ui-kit/react";
import "../../styles/native-domain-dialogs.css";
import { agentHandle, type AgentElementRole } from "@jini-ai/agentic";
import type { AdminWidget, AdminWidgetType } from "../../lib/api";
import { interpolate } from "@jini-ai/ui/panel-kit";
import { widgetTypeLabel } from "@jini-ai/admin/widgets";
import { t as translateWidgets } from "../../features/widgets/widgets-i18n";
import { WidgetConfigFields, WIDGET_TYPE_OPTIONS } from "../WidgetConfigFields/WidgetConfigFields";
import { Select, type SelectOption } from "../Select/Select";
import { useWidgetAddControl, useWiredWidgetAddControl, useWiredWidgetPickerDialog } from "./WidgetPickerDialog.hooks";

/**
 * @file `WidgetPickerDialog` (`ui.spec.md` §2/§3.9/§4.8) — REQ-33's explicit reuse-vs-duplicate
 * modal. Two call sites: `RegionPlacementList.onAddWidgetRequest` and `WidgetEmbedNode`'s toolbar
 * insertion trigger (`widget-embed-extension.tsx`) — no third call site is authorized by the spec.
 *
 * Reuses Jini's native dialog owner, like `Collections.tsx`; no second focus trap, global
 * Escape listener or backdrop lifecycle is needed.
 *
 * `ui.spec.md` §5's rendering rule (followed literally per its own §8 disclosure against ADR-047
 * Amendment 5's "default to reuse" prose): when `existingInstances.length > 0`, BOTH "use existing"
 * and "create new" render as explicit, equally-weighted options with no pre-selected default —
 * implemented here as two always-visible sections, not tabs defaulting to one or the other.
 *
 * Split into this file (props + JSX for both `WidgetPickerDialog` and `WidgetAddControl`) and
 * `WidgetPickerDialog.hooks.tsx` (their state, effects, and the `useExistingInstances` fetch both
 * lean on), per the `@jini-ai/admin` `<Name>.tsx`/`<Name>.hooks.tsx` extraction pattern
 * (`ConfirmDialog.tsx`/`ConfirmDialog.hooks.tsx` in that package). Both components below carry the
 * same kind of injectable seam `ConfirmDialog`'s `useDialog` prop is (`useDialog` here, and
 * `useAddControl` on `WidgetAddControl`) — each does real IO (`useExistingInstances`'s fetch,
 * `useWidgetAddControl`'s `api.createWidget`) or DOM work (the deferred autofocus
 * effect), so a test can swap either for a fake without touching the network.
 *
 * ## Agent handles
 *
 * Given `agentHandle="place-widget"` this publishes:
 *
 * | element | handle | role |
 * |---|---|---|
 * | the "use existing" select (when shown) | `place-widget-existing-select` | via `Select`'s own scheme |
 * | the "Use this widget" submit | `place-widget-existing-submit` | `button` |
 * | the new-title field | `place-widget-new-title` | `field` |
 * | the config sub-form | `place-widget-new-config` | via `WidgetConfigFields`'s own scheme |
 * | the "Create and place" submit | `place-widget-new-submit` | `button` |
 * | the Cancel button | `place-widget-cancel` | `button` |
 *
 * Omit `agentHandle` and no `data-agent-*` markup is emitted at all, including inside the two
 * composed components above — they only tag their own sub-elements when handed a base.
 */

/** `{...(base ? agentHandle(\`${base}-<suffix>\`, opts) : {})}` as a named helper — same
 *  complexity-budget rationale as `Select.tsx`'s `resolveSelectTriggerHandleProps`: this dialog
 *  spreads a conditional agent-handle six times, and each was its own branch in
 *  `WidgetPickerDialog`'s own cyclomatic count. `{}` (no markup) when `base` is unset, same as
 *  every inline occurrence it replaces. */
function handleSpread(base: string | undefined, suffix: string, opts: { role: AgentElementRole; label: string }): Record<string, unknown> {
  return base ? agentHandle({ handle: `${base}-${suffix}` }, opts) : {};
}

/** `base ? \`${base}-<suffix>\` : undefined` as a named helper — the sub-handle string handed to a
 *  composed component (`Select`/`WidgetConfigFields`) rather than spread as `data-agent-*`
 *  attributes directly. Same rationale as {@link handleSpread}. */
function subHandle(base: string | undefined, suffix: string): string | undefined {
  return base ? `${base}-${suffix}` : undefined;
}

/** The existing-instance `Select`'s options as a named helper — the map's shape conversion, out
 *  of `WidgetPickerDialog`'s own scope: one `SelectOption` per loaded instance. It used to take
 *  `instances ?? []`; its only caller renders after `hasExisting`, so it now takes the loaded list. */
function toExistingOptions(instances: readonly AdminWidget[]): SelectOption[] {
  return instances.map((instance) => ({ value: instance.id, label: instance.title }));
}

export interface WidgetPickerDialogProps {
  widgetType: AdminWidgetType;
  onUseExisting: (widgetInstanceId: string) => void;
  onCreateNew: (title: string, config: Record<string, unknown>) => void;
  onCancel: () => void;
  /** Injectable seam for the dialog's fetch/form/Escape-listener/autofocus state. Defaults to the
   *  real {@link useWiredWidgetPickerDialog}; a test can pass a fake here to exercise this
   *  component's rendering without the real `listWidgets` fetch or `document`-level Escape
   *  listener. */
  useDialog?: typeof useWiredWidgetPickerDialog;
  /** This dialog's own base handle — see this file's "Agent handles" doc for the full scheme. Omit
   *  to leave it untagged. */
  agentHandle?: string;
  /** Embed the same forms in a parent native dialog, without a nested modal lifecycle. */
  presentation?: "dialog" | "inline";
}

export function WidgetPickerDialog({ useDialog = useWiredWidgetPickerDialog, agentHandle: base, ...props }: WidgetPickerDialogProps) {
  const {
    instances,
    loadError,
    selectedExistingId,
    setSelectedExistingId,
    newTitle,
    setNewTitle,
    newConfig,
    setNewConfig,
    error,
    existingSelectId,
    newTitleInputId,
    newTitleInputRef,
    typeLabel,
    hasExisting,
    submitUseExisting,
    submitCreateNew,
    t,
  } = useDialog(props);
  // Native modality keeps Tab inside; Jini also restores the opener when this dialog unmounts.

  const content = (
    <>
        <div className="widget-picker-body">
          {loadError ? <div className="notice error">{loadError}</div> : null}
          {error ? (
            <span className="save-error" role="alert">
              {error}
            </span>
          ) : null}

          {hasExisting ? (
            <form onSubmit={submitUseExisting} className="widget-picker-section">
              <h3>{t("Use existing")}</h3>
              <div className="field">
                <label className="field-label" htmlFor={existingSelectId}>
                  {interpolate({ template: t("Existing {typeLabel} widgets"), vars: { typeLabel } })}
                </label>
                <Select
                  id={existingSelectId}
                  value={selectedExistingId}
                  onChange={setSelectedExistingId}
                  // `hasExisting` is `(instances?.length ?? 0) > 0` (the hook), so this section only
                  // renders once `instances` is a loaded, non-empty list; the old `?? []` here could not fire.
                  options={toExistingOptions(instances!)}
                  placeholder={t("Choose a widget…")}
                  agentHandle={subHandle(base, "existing-select")}
                  t={t}
                />
              </div>
              <button type="submit" {...handleSpread(base, "existing-submit", { role: "button", label: "Use this widget" })}>
                {t("Use this widget")}
              </button>
            </form>
          ) : null}

          <form onSubmit={submitCreateNew} className="widget-picker-section">
            <h3>{t("Create new")}</h3>
            <div className="field">
              <label className="field-label" htmlFor={newTitleInputId}>
                {t("Title")}
              </label>
              <input
                id={newTitleInputId}
                ref={newTitleInputRef}
                value={newTitle}
                onChange={(e) => setNewTitle(e.target.value)}
                {...handleSpread(base, "new-title", { role: "field", label: "The new widget's title" })}
              />
            </div>
            <WidgetConfigFields
              widgetType={props.widgetType}
              config={newConfig}
              onChange={setNewConfig}
              agentHandle={subHandle(base, "new-config")}
              t={t}
            />
            <button type="submit" {...handleSpread(base, "new-submit", { role: "button", label: "Create and place this widget" })}>
              {t("Create and place")}
            </button>
          </form>
        </div>

        <div className="widget-picker-footer">
          <span className="editor-actions">
            <button
              type="button"
              className="btn-secondary"
              data-jini-autofocus=""
              onClick={props.onCancel}
              {...handleSpread(base, "cancel", { role: "button", label: "Close without placing a widget" })}
            >
              {t("Cancel")}
            </button>
          </span>
        </div>
    </>
  );
  if (props.presentation === "inline") return content;
  return (
    <Dialog open title={interpolate({ template: t("Place a {typeLabel} widget"), vars: { typeLabel } })}
      onClose={() => props.onCancel()} className="settings-dialog jini-domain-dialog widget-picker-dialog">
      {content}
    </Dialog>
  );
}

/**
 * The shared "choose a type, then open `WidgetPickerDialog`" two-step trigger (`ui.spec.md` §4.7's
 * `RegionPlacementList.onAddWidgetRequest` and §4.9's `WidgetEmbedNode.onInsertRequest` both name
 * this exact flow). One small control, reused by `WidgetRegionEditor.tsx`'s "+ Add widget" and the
 * TipTap toolbar's "Insert widget" button — avoids two independent implementations of the same
 * type-choice step.
 *
 * ## Agent handles
 *
 * Given `agentHandle="add-widget"` this publishes `<base>-type` (the type `Select`, via its own
 * scheme) and `<base>-open` (the trigger button); the nested `WidgetPickerDialog`, once opened,
 * gets `<base>-picker` as ITS OWN base — see that component's "Agent handles" doc for what that
 * expands to. Omit `agentHandle` and none of it is tagged.
 */
export interface WidgetAddControlProps {
  triggerLabel: string;
  onResolved: (widgetInstanceId: string) => void | Promise<void>;
  /** Injectable seam for the two-step type-choice/create-or-reuse state. Defaults to the real
   *  {@link useWiredWidgetAddControl}; a test can pass a fake here to exercise this component's
   *  rendering without the real `api.createWidget` call. */
  useAddControl?: typeof useWiredWidgetAddControl;
  /** This control's own base handle — see this file's "Agent handles" doc above. Omit to leave it
   *  (and the dialog it opens) untagged. */
  agentHandle?: string;
  /** Open directly at this type when the control is mounted inside a picker dialog. */
  initialWidgetType?: AdminWidgetType;
}

/** The retained host catalog owns type labels for both inline controls and the native picker. */
function widgetTypeOptions({ locale }: { locale: string }, _optional: Record<string, never> = {}): SelectOption[] {
  return WIDGET_TYPE_OPTIONS.map((o) => ({ value: o.value, label: widgetTypeLabel({ widgetType: o.value, types: WIDGET_TYPE_OPTIONS }, { t: key => translateWidgets({ locale, key }) }) }));
}

export function WidgetAddControl({ useAddControl = useWiredWidgetAddControl, agentHandle: base, ...props }: WidgetAddControlProps) {
  const { pickerType, setPickerType, selectedType, setSelectedType, error, handleCreateNew, handleUseExisting, t, locale } =
    useAddControl(props);
  // `WIDGET_TYPE_OPTIONS`'s own labels are the English source strings; translate them through the
  // same `widgetTypeLabel` lookup `WidgetPickerDialog.hooks.tsx`'s `typeLabel` uses, so this type
  // picker and the dialog it opens agree on one widget type's display name per locale.
  const typeOptions = widgetTypeOptions({ locale });

  return (
    <span className="widget-add-control">
      <Select
        value={selectedType}
        onChange={(v) => setSelectedType(v as AdminWidgetType)}
        options={typeOptions}
        aria-label={t("Widget type")}
        agentHandle={base ? `${base}-type` : undefined}
        t={t}
      />
      <button
        type="button"
        onClick={() => setPickerType(selectedType)}
        {...(base ? agentHandle({ handle: `${base}-open` }, { role: "button", label: props.triggerLabel }) : {})}
      >
        {props.triggerLabel}
      </button>
      {error ? (
        <span className="save-error" role="alert">
          {error}
        </span>
      ) : null}
      {pickerType ? (
        <WidgetPickerDialog
          widgetType={pickerType}
          onUseExisting={handleUseExisting}
          onCreateNew={handleCreateNew}
          onCancel={() => setPickerType(null)}
          agentHandle={base ? `${base}-picker` : undefined}
        />
      ) : null}
    </span>
  );
}

export { useWidgetAddControl };

/** Full widget flow for Embed: one native dialog owns dismissal and focus, while
 * type changes remount only the forms so drafts and late fetches cannot cross types.
 * A settled create also refreshes the forms, exposing its new widget under Use existing
 * if placement fails, as the add-control owner's recovery message promises.
 * Creation and placement still go through the existing add-control owner. */
export function WidgetSelectionDialog({ useAddControl = useWiredWidgetAddControl, agentHandle: base, onCancel, ...props }: {
  onResolved: WidgetAddControlProps["onResolved"];
  onCancel: () => void;
  agentHandle?: string | undefined;
  useAddControl?: typeof useWiredWidgetAddControl;
  useDialog?: typeof useWiredWidgetPickerDialog;
}, _optional: Record<string, never> = {}) {
  const vm = useAddControl({ triggerLabel: "Insert widget", onResolved: props.onResolved, initialWidgetType: "text" });
  return (
    <Dialog open title={vm.t("Insert widget")} onClose={() => onCancel()}
      className="settings-dialog jini-domain-dialog widget-picker-dialog">
      <Select value={vm.selectedType}
        onChange={(value) => { vm.setSelectedType(value as AdminWidgetType); vm.setPickerType(value as AdminWidgetType); }}
        options={widgetTypeOptions({ locale: vm.locale })} aria-label={vm.t("Widget type")}
        agentHandle={subHandle(base, "type")} t={vm.t} />
      {vm.error ? <span className="save-error" role="alert">{vm.error}</span> : null}
      <WidgetPickerDialog key={`${vm.selectedType}:${vm.pickerType === null ? "settled" : "draft"}`}
        widgetType={vm.selectedType} presentation="inline"
        onUseExisting={vm.handleUseExisting} onCreateNew={vm.handleCreateNew} onCancel={onCancel}
        useDialog={props.useDialog}
        agentHandle={subHandle(base, "picker")} />
    </Dialog>
  );
}

import { useId, type InputHTMLAttributes, type ReactNode } from "react";
import { InfoTip } from "@jini-ai/ui/admin-widgets";
import type { AgentHandleProps } from "@jini-ai/agentic";

/**
 * One on/off setting on the AI Assistant screen: checkbox, bold label, and an ⓘ holding the
 * explainer that used to sit inline under it (2026-10-09 redesign — the copy stays, it just no
 * longer pushes the controls apart). The InfoTip is a sibling of the `<label>`, never inside it,
 * so tapping ⓘ cannot also toggle the checkbox.
 *
 * The checkbox's own `aria-describedby` points at the tip's hidden text, so a screen reader still
 * hears the explainer with the control, as it did when the paragraph was inline.
 */
export interface AssistantToggleRowProps {
  label: string;
  info: string;
  checked: boolean;
  disabled?: boolean | undefined;
  onChange: (checked: boolean) => void;
  t: (key: string) => string;
  /** Extra ids for `aria-describedby` (an owner-only note rendered by the caller). */
  describedBy?: string | undefined;
  /** `role="switch"` styling for the one control a tab is about (the visitor enable switch). */
  variant?: "checkbox" | "switch" | undefined;
  /** Agent handle spread, attributes only. */
  inputProps?: (InputHTMLAttributes<HTMLInputElement> & Partial<AgentHandleProps>) | undefined;
  infoHandle?: string | undefined;
  /** Status, errors or a nested checklist, rendered under the row. */
  children?: ReactNode;
  className?: string | undefined;
}

export function AssistantToggleRow(props: AssistantToggleRowProps) {
  const infoId = useId();
  const inputId = useId();
  const describedBy = [infoId, props.describedBy].filter(Boolean).join(" ");
  const isSwitch = props.variant === "switch";
  return (
    <div className={["assistant-toggle", isSwitch ? "assistant-toggle--switch" : "", props.className ?? ""].filter(Boolean).join(" ")}>
      <div className="assistant-toggle-head">
        <input type="checkbox" {...props.inputProps} id={inputId} {...(isSwitch ? { role: "switch" } : {})}
          checked={props.checked} disabled={props.disabled} aria-describedby={describedBy}
          onChange={(event) => props.onChange(event.target.checked)} />
        <div className="assistant-toggle-copy">
          <label htmlFor={inputId}>{props.label}</label>
          {"\u00a0"}
          <InfoTip label={props.info} triggerLabel={props.t("More info: {name}").replace("{name}", props.label)}
            descriptionId={infoId} agentHandle={props.infoHandle} />
        </div>
      </div>
      {props.children}
    </div>
  );
}

import { useId } from "react";
import { agentHandle } from "@jini-ai/agentic";
import { ChatSettingsSegmented } from "@jini-ai/chat/react";
import { InfoTip } from "@jini-ai/ui/admin-widgets";

import type { VisitorToolMode, VisitorToolView } from "@/lib/visitor-tools";
import {
  groupVisitorTools, modeDisabled, useVisitorToolLimitsDraft, useWiredVisitorTools,
  type VisitorToolsController,
} from "./hooks/use-visitor-tools.hooks";
// The segmented pill's look lives with the chat settings it was built for; imported here too so this
// tab never depends on the dock having loaded it first.
import "../../styles/assistant.css";

/**
 * "Visitor tools" tab (owner, 2026-10-22): the tool calls the visitor's assistant may make on a
 * visitor's behalf, each Auto | Ask first | Off — the same segmented control as the chat gear's
 * "Agent plugins". It reads and writes the same service as the chat's visitor-tool tools.
 *
 * Security review F2 (binding): modes change on a click of the segmented radios (no `<select>`),
 * limits persist only from an explicit Save click, and none of this tab's handles may be added to
 * `DIRECT_PAGE_HANDLES` — the admin chat's page clicks here must keep their approval card.
 */
const MODES: readonly { mode: VisitorToolMode; label: string }[] = [
  { mode: "auto", label: "Auto" }, { mode: "ask", label: "Ask first" }, { mode: "off", label: "Off" },
];
/** Agent handles are lowercase hyphenated words; tool ids are server data (`list_posts`, plugin ids). */
function toolHandle(id: string, part: string): string {
  const slug = id.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 40).replace(/-+$/, "") || "tool";
  return `ai-assistant-visitor-tool-${slug}-${part}`;
}
const GROUP_LABELS: Record<VisitorToolView["source"], string> = {
  builtin: "Built-in", plugin: "From plugins", created: "Created", unavailable: "Unavailable",
};

export interface VisitorToolsPanelProps {
  t: (key: string) => string;
  /** Test seam, defaulted to the real hook. */
  useVisitorToolsHook?: typeof useWiredVisitorTools;
}

export function VisitorToolsPanel({ t, useVisitorToolsHook = useWiredVisitorTools }: VisitorToolsPanelProps) {
  const controller = useVisitorToolsHook({ t });
  if (controller.loadError && !controller.view) {
    return <div className="visitor-tools-message" role="alert">
      <span>{controller.loadError}</span>
      <button type="button" className="btn-secondary" onClick={() => controller.retry()}>{t("Retry")}</button>
    </div>;
  }
  if (!controller.view) return <p role="status">{t("Loading visitor tools…")}</p>;
  const groups = groupVisitorTools({ tools: controller.view.tools });
  return (
    <div className="visitor-tools">
      <p className="visitor-tools-intro">
        {t("What the assistant can do for visitors.")}
        <InfoTip label={t("Auto runs it. Ask first waits for the visitor to click Allow in chat before running. Off hides it.")}
          triggerLabel={t("About visitor tools")} agentHandle="ai-assistant-visitor-tools-info" />
      </p>
      <Notices controller={controller} t={t} />
      {groups.length === 0 ? <p className="visitor-tools-empty">{t("No visitor tools yet.")}</p> : null}
      {groups.map(group => (
        <section key={group.source} className="visitor-tools-group" aria-label={t(GROUP_LABELS[group.source])}>
          {groups.length > 1 ? <h3 className="visitor-tools-group-title">{t(GROUP_LABELS[group.source])}</h3> : null}
          <ul className="visitor-tools-list">
            {group.tools.map(tool => <VisitorToolRow key={tool.id} tool={tool} controller={controller} t={t} />)}
          </ul>
        </section>
      ))}
    </div>
  );
}

function Notices({ controller, t }: { controller: VisitorToolsController; t: (key: string) => string }) {
  return <>
    {controller.invalid ? (
      <div className="visitor-tools-message is-warning" role="alert">
        <span>{t("Saved tool settings can't be read, so every tool is Off.")}</span>
        <button type="button" className="btn-secondary" disabled={controller.busyToolId !== null}
          onClick={() => void controller.repair()}
          {...agentHandle({ handle: "ai-assistant-visitor-tools-reset" }, { role: "button", label: "Turn all visitor tools Off to reset" })}>
          {t("Turn all tools Off to reset")}
        </button>
      </div>
    ) : null}
    {controller.notice ? (
      <p className={`visitor-tools-message is-${controller.notice.kind}`} role={controller.notice.kind === "error" ? "alert" : "status"}>
        {controller.notice.message}
      </p>
    ) : null}
  </>;
}

function VisitorToolRow({ tool, controller, t }: { tool: VisitorToolView; controller: VisitorToolsController; t: (key: string) => string }) {
  const nameId = useId();
  const title = t(tool.displayTitle ?? tool.title);
  const description = t(tool.displayDescription ?? tool.description);
  const busy = controller.busyToolId !== null;
  // An unreadable policy is enforced as all-Off server side; show exactly that, not the stale choice.
  const mode = controller.invalid ? "off" : tool.mode;
  return (
    <li className="visitor-tool" aria-labelledby={nameId} aria-busy={controller.busyToolId === tool.id || undefined}>
      <div className="visitor-tool-head">
        <div className="visitor-tool-text">
          <span id={nameId} className="visitor-tool-title">{title}</span>
          <span className="visitor-tool-description">{description}</span>
          {!tool.availability.available ? (
            <span className="visitor-tool-unavailable">{tool.availability.reason ?? t("Not available right now.")}</span>
          ) : null}
        </div>
        <div className="visitor-tool-mode" role="radiogroup" aria-labelledby={nameId}>
          <ChatSettingsSegmented name={`visitor-tool-mode-${tool.id}`}
            items={MODES.map(item => ({
              key: item.mode, label: t(item.label), checked: mode === item.mode,
              disabled: modeDisabled({ tool, mode: item.mode, invalid: controller.invalid, busy }),
              change: () => { if (item.mode !== mode) void controller.configure({ toolId: tool.id, mode: item.mode }); },
            }))} />
        </div>
      </div>
      <VisitorToolLimits tool={tool} title={title} controller={controller} t={t} />
    </li>
  );
}

function VisitorToolLimits({ tool, title, controller, t }: { tool: VisitorToolView; title: string; controller: VisitorToolsController; t: (key: string) => string }) {
  const limits = useVisitorToolLimitsDraft({ tool, configure: controller.configure });
  const ipId = useId();
  const siteId = useId();
  const errorId = useId();
  const locked = controller.invalid || !tool.availability.available;
  const fields = [
    { id: ipId, key: "perIpPerHour" as const, label: t("Per visitor, per hour") },
    { id: siteId, key: "perSitePerDay" as const, label: t("Whole site, per day") },
  ];
  return (
    <details className="visitor-tool-limits">
      <summary>{t("Limits")}</summary>
      {/* No <form>: Enter in a field must not submit — only the Save click persists (F2). */}
      <div className="visitor-tool-limits-body">
        {fields.map(field => (
          <label key={field.key} htmlFor={field.id} className="visitor-tool-limit">
            <span>{field.label}</span>
            <input id={field.id} className="jini-input" type="number" inputMode="numeric" min={1} step={1}
              value={limits.draft[field.key]} disabled={locked}
              aria-invalid={limits.invalid || undefined} aria-describedby={limits.invalid ? errorId : undefined}
              onChange={(event) => limits.edit(field.key, event.target.value)}
              {...agentHandle({ handle: toolHandle(tool.id, field.key === "perIpPerHour" ? "per-visitor-limit" : "per-site-limit") }, { role: "field", label: `${title}: ${field.label}` })} />
          </label>
        ))}
        <button type="button" className="btn-primary" disabled={locked || !limits.dirty || controller.busyToolId !== null}
          onClick={() => void limits.save()}
          {...agentHandle({ handle: toolHandle(tool.id, "limits-save") }, { role: "button", label: `Save ${title} limits` })}>
          {controller.busyToolId === tool.id ? t("Saving…") : t("Save")}
        </button>
        {limits.invalid ? <span id={errorId} className="visitor-tool-limit-error" role="alert">{t("Use a whole number, 1 or more.")}</span> : null}
        {!limits.invalid ? (
          <span className="visitor-tool-limit-hint">
            {visitorToolDefaultLimitsText({ defaults: controller.view?.defaults, t })}
          </span>
        ) : null}
      </div>
    </details>
  );
}

/** Format the default budget hint independently of the interactive limits editor. */
export function visitorToolDefaultLimitsText({ defaults, t }: { defaults?: VisitorToolView["limits"]; t: (key: string) => string }, _options = {}): string {
  return t("Default: {ip} per visitor/hour, {site} per site/day.")
    .replace("{ip}", String(defaults?.perIpPerHour ?? ""))
    .replace("{site}", String(defaults?.perSitePerDay ?? ""));
}

import type { useConfirmRequest } from "@jini-ai/admin/react";
import { assistantSubagentsPort, SUBAGENTS_NAMESPACE, SUBAGENT_DANGERS, type AssistantSubagentsPort, type AssistantSubagentsSettings } from "@/lib/assistant-subagents";
import { useAssistantOwnerGrant, useAssistantOwnerGrantSettings } from "./use-assistant-owner-grant.hooks";
import { ASSISTANT_CLI_CAPABILITIES, assistantCliPermissions, type AssistantCliCapability } from "@tovu/headless";
const settingsKey = ["admin-assistant", "subagents"] as const;
/** The panel and dock share the site-owner grant query. */
export function useAssistantSubagentsSettings(required: { port: AssistantSubagentsPort; mode: string; agentId: string | null }, _optional = {}) {
  const state = useAssistantOwnerGrantSettings({ ...required, namespace: SUBAGENTS_NAMESPACE, key: settingsKey });
  // A stale cached ON value cannot establish the current grant after a failed refresh.
  const tooltipKey = !state.loadError && required.mode === "local-cli" && required.agentId !== null &&
    (state.settings?.capabilities?.subagents ?? state.settings?.enabled)
    ? "This chat can use subagents" : null;
  return { ...state, tooltipKey };
}
/** Subagent-specific copy and boolean payload; the shared hook owns locking and errors. */
export function useAdminSubagents(required: { port: AssistantSubagentsPort; t?: (key: string) => string }, optional: { useConfirmation?: typeof useConfirmRequest } = {}) {
  const state = useAssistantOwnerGrant({ ...required, namespace: SUBAGENTS_NAMESPACE, key: settingsKey,
    title: "Enable Full CLI access?", dangers: SUBAGENT_DANGERS,
    confirmLabel: "Enable Full CLI access", failure: required.t?.("failed to save subagent access") ?? "failed to save subagent access",
  }, { ...optional, confirmEnable: false });
  return { ...state, setEnabled: async ({ enabled }: { enabled: boolean }, _options = {}) => {
    await state.save({ settings: assistantCliPermissions({ enabled }) });
  }, setCapability: async ({ key, enabled }: { key: AssistantCliCapability; enabled: boolean }, _options = {}) => {
    if (!state.settings) return;
    const current = assistantCliPermissions(state.settings);
    await state.save({ settings: { enabled: current.enabled, capabilities: { ...current.capabilities, [key]: enabled } } });
  } };
}

type DockGrantState = { settings: AssistantSubagentsSettings | null; loadError: string | null };
/** Pure owner/lock split for the dock: who may open the advanced entry vs who may flip switches.
 * @param required - Server grant (null until loaded) and the last refresh error.
 * @returns `owner` (server-confirmed local owner, fresh read) and `canEdit` (owner without an env lock).
 * @complexity O(1). */
function dockGrantAccess(required: DockGrantState, _optional = {}) {
  const owner = !!required.settings?.canEdit && !required.loadError;
  // unavailableReason with canEdit = a local env lock: the server reads every switch OFF, so a
  // clickable switch would save and snap straight back. Lock it and show the reason instead.
  return { owner, canEdit: owner && !required.settings?.unavailableReason };
}
/** Pure capability rows for the dock dialog; the master reads ON only when every capability is ON.
 * @param required - Server grant (null until loaded: everything OFF) and the translation port.
 * @returns The derived master value and one translated row per CLI capability.
 * @complexity O(c) for the fixed capability list. */
function dockCapabilities(required: { settings: AssistantSubagentsSettings | null; t: (key: string) => string }, _optional = {}) {
  const permissions = assistantCliPermissions({ enabled: required.settings?.enabled ?? false, capabilities: required.settings?.capabilities });
  return { enabled: ASSISTANT_CLI_CAPABILITIES.every(({ key }) => permissions.capabilities[key]),
    capabilities: ASSISTANT_CLI_CAPABILITIES.map(item => ({ ...item, label: required.t(item.label), description: required.t(item.description), enabled: permissions.capabilities[item.key] })) };
}
/** Narrows the dialog's free-form key; unknown keys must never reach the grant write. */
function isCliCapability(key: string): key is AssistantCliCapability {
  return ASSISTANT_CLI_CAPABILITIES.some(item => item.key === key);
}
/** Thin host port for Jini's advanced settings dialog; panel and dock share the grant query. */
export function useDockAgentPermissions(required: { t: (key: string) => string; port?: AssistantSubagentsPort; openSettings?: () => void }, _optional = {}) {
  const state = useAdminSubagents({ ...required, port: required.port ?? assistantSubagentsPort });
  const access = dockGrantAccess(state);
  const view = dockCapabilities({ settings: state.settings, t: required.t });
  return { enabled: view.enabled,
    // Hide the advanced entry until the server confirms the local-owner capability. Hosted and
    // non-owner chats retain the quick display menu without advertising unavailable permissions.
    onMoreSettings: access.owner ? required.openSettings : undefined,
    canEdit: access.canEdit, busy: state.busy,
    error: state.loadError ?? state.saveError,
    unavailableReason: state.settings?.unavailableReason,
    capabilities: view.capabilities,
    onChange: ({ key, enabled }: { key?: string; enabled: boolean }) => {
      if (key === undefined) void state.setEnabled({ enabled });
      else if (isCliCapability(key)) void state.setCapability({ key, enabled });
    },
  };
}
/** Production binding stays outside the injected policy hook. */
export function useWiredAdminSubagents(required: { t?: (key: string) => string }, _optional = {}) {
  return useAdminSubagents({ ...required, port: assistantSubagentsPort });
}
export function useWiredAssistantSubagentsSettings(required: { mode: string; agentId: string | null }, _optional = {}) {
  return useAssistantSubagentsSettings({ ...required, port: assistantSubagentsPort });
}

import { useFetchQuery, useFetchMutation, useCachedLoader } from "@jini-ai/ui/fetch-query";
import { useCallback, useEffect, useMemo, useState } from "react";

import type { PublicAssistantSettings } from "@/lib/api";
import { navigate } from "@/lib/router";
import { describeApiError } from "../rules";
import { defaultAiAssistantPort } from "./ai-assistant-dependencies.hooks";
import type { AiAssistantPort } from "./ai-assistant-port.hooks";

/**
 * @file The `AiAssistant` screen's own top-level state: the visitor-facing public on/off switch.
 *
 * Extracted verbatim — same state, same order, same effect, same error strings. This is
 * deliberately narrower than the whole screen: `AdminAssistantSwitch`, `AdminExecutionMode`, and
 * `VisitorCredentialForm` each own their own state and get their own hook file, per this feature's
 * "one hook file per component" convention (see `features/integrations/hooks/` for the same split
 * applied to a smaller feature).
 *
 * `deps.port` is injected (see `ai-assistant-port.hooks.ts`) rather than reaching for `lib/api`'s
 * `api` directly — the same `useX(dependencies)` / `useWiredX()` split `redirects`/`widgets`/
 * `plugins`/`members`/`workspace` use. `use-visitor-credential-form.hooks.ts` — the other hook this
 * screen composes — is NOT part of this conversion: it reaches a much larger `api` surface of its
 * own and is deliberately out of scope here.
 */

export interface AiAssistantDependencies {
  port: AiAssistantPort;
}

export interface AiAssistantController {
  settings: PublicAssistantSettings | null;
  loadError: string | null;
  saveError: string | null;
  saving: boolean;
  setPublicEnabled: (publicEnabled: boolean) => Promise<void>;
  setWidget: (input: { widget: "react" | "vanilla" }, options?: Record<string, never>) => Promise<void>;
}

export function useAiAssistant({ port }: AiAssistantDependencies, _options: Record<string, never> = {}): AiAssistantController {
  const key = useMemo(() => ["ai-assistant", "settings"] as const, []);
  const fetchSettings = useCallback(async () => {
    try { return (await port.getAssistantSettings()).data; }
    catch (error) { throw new Error(describeApiError(error, "failed to load AI assistant settings")); }
  }, [port]);
  const query = useFetchQuery({ key, fetch: fetchSettings }, { staleTime: 0 });
  const loader = useCachedLoader({ key, fetch: fetchSettings }, { staleTime: 0 });
  const settings = query.data ?? null;
  const loadError = query.error?.message ?? null;
  const update = useFetchMutation({ run: ({ input }: { input: Partial<PublicAssistantSettings> }) => port.setAssistantSettings(input) }, { invalidates: [key] });
  const [saveError, setSaveError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  async function saveSettings(input: Partial<PublicAssistantSettings>, _options = {}) {
    setSaving(true);
    setSaveError(null);
    try {
      // The response, not `publicEnabled` — the server is the authority on what is now true, and a
      // rejected or partially-applied write must not leave this screen lying about it.
      const { data } = await update.mutate({ input });
      loader.replace({ value: data });
    } catch (e) {
      setSaveError(describeApiError(e, "failed to save AI assistant settings"));
    } finally {
      setSaving(false);
    }
  }

  const setPublicEnabled = (publicEnabled: boolean) => saveSettings({ publicEnabled });
  const setWidget = (input: { widget: "react" | "vanilla" }, options = {}) => saveSettings(input, options);
  return { settings, loadError, saveError, saving, setPublicEnabled, setWidget };
}

/**
 * Binds the real `/api/.../assistant/settings` client — see `ai-assistant-dependencies.hooks.ts`.
 *
 * The zero-argument-dependencies half of the `useX(dependencies)` / `useWiredX()` pair, so
 * `AiAssistant.tsx` composes this and a test composes {@link useAiAssistant} with
 * `createFakeAiAssistantPort`.
 */
export function useWiredAiAssistant(): AiAssistantController {
  return useAiAssistant({ port: defaultAiAssistantPort });
}

/** The three tab ids `AiAssistant.tsx`'s own `tabs` array declares — kept here as the single source
 *  {@link resolveAiAssistantRequestedTabId} checks a `?tab=` value against, so a stray typo in a
 *  link can never look like a valid tab. */
export const AI_ASSISTANT_TAB_IDS = ["visitor", "admin", "roadmap"] as const;

/**
 * The tab the inline shell should actually open on, or `undefined` to leave it uncontrolled — same
 * computation, and same reason, as `SettingsUi.tsx`'s own `requestedTabId`: `tabId` can be `null` (no
 * `?tab=` at all, the common case) or an id that matches none of the three tabs (typo, stale link),
 * and either one must fall back to the shell's own default rather than being passed straight through
 * as `activeTabId`, whose controlled/uncontrolled switch is `!== undefined`, not truthiness.
 */
export function resolveAiAssistantRequestedTabId(tabId: string | null | undefined): string | undefined {
  return tabId && (AI_ASSISTANT_TAB_IDS as readonly string[]).includes(tabId) ? tabId : undefined;
}

/** Keeps the page subtitle and shell on the same tab, including standalone mounts.
 * URL changes remain owned by the existing navigation function. No I/O beyond navigation.
 * @complexity Time/space: O(1), with a fixed three-tab set.
 */
export function useAiAssistantTab({ tabId }: { tabId: string | null | undefined }, _options = {}) {
  const [activeTabId, setActiveTabId] = useState(() => resolveAiAssistantRequestedTabId(tabId) ?? "visitor");
  useEffect(() => { setActiveTabId(resolveAiAssistantRequestedTabId(tabId) ?? "visitor"); }, [tabId]);
  const onTabChange = (nextTabId: string) => {
    setActiveTabId(nextTabId);
    navigateToAiAssistantTab(nextTabId);
  };
  return { activeTabId, onTabChange };
}

/** Reuses the selected tab's translated copy; unknown ids use the first tab.
 * @complexity Time: O(n) tabs; space: O(1).
 */
export function resolveAiAssistantTabSubtitle({ tabs, activeTabId }: {
  tabs: readonly { id: string; subtitle?: string | undefined }[]; activeTabId: string;
}, _options = {}): string | undefined {
  return (tabs.find(tab => tab.id === activeTabId) ?? tabs[0])?.subtitle;
}

/**
 * Keeps `?tab=` in sync as the operator switches tabs — same `replace`-not-push shape and same
 * "fires even before any `?tab=` is present" behaviour as `SettingsUi.tsx`'s own `handleTabChange`.
 */
export function navigateToAiAssistantTab(nextTabId: string): void {
  navigate(`/ai-assistant?tab=${nextTabId}`, { replace: true });
}

import { useEffect, useMemo, useRef, useState } from "react";
import { DEFAULT_PROVIDER_PRESETS } from "@jini-ai/integrations/media-providers/catalog";
import {
  nextConfigForPresetSelect,
  resolveSelectedPreset,
  type ByokConfig,
  type ConnectionTestState,
  type ExecutionPort,
  type ModelDiscoveryState,
  type ProviderPreset,
} from "@jini-ai/ui";

import { useSerialWrites, type Translate } from "@jini-ai/ui/panel-kit";
import type { SiteAssistantCredential, SiteAssistantCredentialPatch } from "@/lib/api";
import { createExecutionPort } from "@/lib/execution-settings";
import {
  STORED_KEY_OTHER_PROVIDER_COPY,
  describeProbeError,
  hasUsableKey,
  storedKeyBlocksProbe,
  storedKeyIsForOtherEndpoint as storedKeyIsForOtherEndpointRule,
} from "@/lib/stored-credential-endpoint";
import {
  configuredPresetIds as configuredPresetIdsRule,
  describeApiError,
  hasStoredCredential,
  defaultVisitorCredentialConfig,
  hydrateVisitorCredentialConfig,
  isPresetSuppliedEndpoint,
  visitorProviderGroups,
  type VisitorProviderGroup,
} from "../rules";
import { defaultVisitorCredentialFormPort } from "./visitor-credential-form-dependencies.hooks";
import type { VisitorCredentialFormPort } from "./visitor-credential-form-port.hooks";

/**
 * @file Everything `VisitorCredentialForm` does, so the component in `AiAssistant.tsx` is only
 * markup. Extracted verbatim — same state, same order, same effects, same error strings.
 *
 * See `VisitorCredentialForm`'s own doc comment in `AiAssistant.tsx` for what this form is (the
 * SITE's provider credential, distinct from the admin's own BYOK key in Settings → Execution mode)
 * and for the ADR-058 write-only server-side store it saves to.
 */

/** How long the key field must be quiet before discovery fires. Long enough that typing or pasting a
 *  key is one request rather than one per keystroke — the concern `ExecutionTab`'s own discovery
 *  effect documents ("refetching on every keystroke would spam the provider") — and short enough
 *  that a paste feels immediate. */
const MODEL_DISCOVERY_DEBOUNCE_MS = 700;

/** Save's user-visible state. `saved` carries the server's own view back so the line under the key
 *  field can report what is actually stored rather than what was sent. */
export type SaveState =
  | { status: "idle" }
  | { status: "saving" }
  | { status: "saved"; at: string | null }
  | { status: "error"; message: string };

/** The writers {@link saveVisitorKey} needs, grouped rather than passed as loose setters beside
 *  loose values. A save either advances all of them or none.
 *
 *  `setDirty` is deliberately absent: `dirty` tracks unsaved SETTINGS, and a key write does not save
 *  them — see {@link saveVisitorSettings}, which is the only thing that clears it. */
export interface VisitorCredentialSaveWriters {
  setSaveState: (state: SaveState) => void;
  setStored: (stored: SiteAssistantCredential) => void;
  setConfig: (updater: (current: ByokConfig) => ByokConfig) => void;
}

/** {@link saveVisitorSettings}'s own writers — its own save state, the server's returned view, and
 *  the `dirty` flag it is the sole clearer of. */
export interface VisitorCredentialSettingsSaveWriters {
  setSettingsSaveState: (state: SaveState) => void;
  setStored: (stored: SiteAssistantCredential) => void;
  setDirty: (dirty: boolean) => void;
}

export interface VisitorCredentialFormController {
  /** Defaults are not server truth until the initial read succeeds. */
  loadState: { status: "loading" } | { status: "ready" } | { status: "error"; message: string };
  config: ByokConfig;
  /** Every edit that originates from a CONTROL goes through here, so `dirty` reflects the operator
   *  and never hydration or discovery. */
  editConfig: (next: ByokConfig) => void;
  preset: ProviderPreset | null;
  discovery: ModelDiscoveryState;
  connectionTest: ConnectionTestState;
  /** The server's write-only view of what is currently stored (`isSet` + `masked`), never the key. */
  stored: SiteAssistantCredential | null;
  /** The "Save key" button's own save state. Never advanced by {@link saveSettings}. */
  saveState: SaveState;
  /** The "Save settings" button's own save state, deliberately separate from {@link saveState}: two
   *  buttons writing two disjoint patches need two answers, and one shared state is exactly what let
   *  a settings-only press report that a key had been stored. */
  settingsSaveState: SaveState;
  /**
   * True once the operator has actually changed something — what "Save settings" is enabled by.
   *
   * State rather than a ref because a button's disabled-ness has to re-render on it. Set ONLY from
   * `editConfig`, so neither hydration nor discovery seeding a model counts as an edit; without
   * that separation the button would light up on load offering to write back the values the server
   * just sent, and — if the initial GET had failed — to write this form's hardcoded defaults over a
   * perfectly good stored credential.
   */
  dirty: boolean;
  /** A key a probe can use here — just typed, or stored on the server FOR THIS ENDPOINT. That is what
   *  makes the two probe controls meaningful, which is the only thing they need to decide. */
  hasUsableKey: boolean;
  hasStoredKey: boolean;
  /** A key is stored, but the server saved it for another endpoint than the form's (a provider
   *  switch). With nothing typed, no probe sends it and the key line asks for this provider's key.
   *  See `rules.ts`'s `storedKeyIsForOtherEndpoint`. */
  storedKeyIsForOtherEndpoint: boolean;
  /** Which provider presets the current credentials already satisfy — feeds each `ProviderChipGroup`'s
   *  filled/unfilled dot. */
  configuredPresetIds: Set<string>;
  selectPreset: (next: ProviderPreset) => void;
  /** The Provider `<select>`'s two optgroups (protocols, gateways), each option flagged when
   *  {@link configuredPresetIds} has it — the old chips' filled dot, now an option suffix. */
  providerGroups: VisitorProviderGroup[];
  /** The `<select>`'s change handler: looks the preset up by id and runs {@link selectPreset}, so
   *  autosave and field population are identical to the chips it replaced. Unknown ids are ignored. */
  selectPresetById: (presetId: string) => void;
  /** Writes the KEY only — see {@link saveVisitorKey}. */
  saveKey: () => Promise<void>;
  /** Writes provider/baseUrl/model only, never a key — see {@link saveVisitorSettings}. */
  saveSettings: () => Promise<void>;
  runKeyTest: () => Promise<void>;
  runTestConnection: () => Promise<void>;
}

/**
 * The "Save key" press — writes the KEY and nothing else.
 *
 * ## Why this is half of what it used to be (owner ruling, 2026-09-02)
 *
 * One control used to write the key AND provider/baseUrl/model together, mirroring the admin BYOK
 * panel's identical overload. A button with two jobs cannot honestly report which one it just did:
 * pressing it with an empty field sent a patch carrying no `apiKey` at all and still answered "Saved
 * to the server, encrypted." The fix is not a better message, it is one job per button —
 * {@link saveVisitorSettings} took the other half.
 *
 * A blank or whitespace-only field is a no-op, not a partial write. That is a real narrowing: the
 * old guard let a blank field through whenever a key was already stored, on the strength of the
 * OTHER fields being worth writing. Those fields have their own button now, so the only thing left
 * to check is whether there is a key to send.
 *
 * Extracted as a top-level function, not a nested closure, per the complexity-pass extraction rule —
 * see `VisitorCredentialForm`'s own doc comment in `AiAssistant.tsx` for the "why an explicit press,
 * not a debounce" reasoning both halves implement.
 */
export async function saveVisitorKey(deps: {
  /** Injected, not imported — see {@link VisitorCredentialFormPort}. */
  api: VisitorCredentialFormPort;
  /** The whole draft, rather than the one field picked out of it, for symmetry with
   *  {@link saveVisitorSettings} and so a future field cannot be forgotten at one call site. */
  config: ByokConfig;
  writers: VisitorCredentialSaveWriters;
}): Promise<void> {
  const { setSaveState, setStored, setConfig } = deps.writers;
  const apiKey = deps.config.apiKey.trim();
  if (!apiKey) return; // nothing typed — there is no key to write

  // The key ALONE, built from one literal so no branch here can let another field through.
  const patch: SiteAssistantCredentialPatch = { apiKey };

  setSaveState({ status: "saving" });
  try {
    const { data } = await deps.api.setAssistantSiteCredential(patch);
    // The SERVER's view, not the patch that was sent — same reasoning as `setPublicEnabled` in
    // `use-ai-assistant.hooks.ts`. A partially-applied or rejected write must not leave this screen
    // claiming a key is stored when it is not.
    setStored(data);
    setSaveState({ status: "saved", at: data.updatedAt });
    // Clear the field once the key is safely stored. Leaving the plaintext sitting in a React
    // state tree after it has been persisted keeps it readable in devtools for no benefit, and the
    // masked placeholder now carries the "which key" answer the field would otherwise be giving.
    setConfig((current) => ({ ...current, apiKey: "" }));
  } catch (e) {
    setSaveState({ status: "error", message: describeApiError(e, "failed to save the key") });
  }
}

/**
 * The "Save settings" press — writes provider/baseUrl/model and NEVER an `apiKey` property.
 *
 * Not even an empty string: `put-site-credential.ts` rejects that with a 400, and it is precisely
 * the write the old overloaded control could make. The field's contents are not read here at all, so
 * there is no state of the form in which this patch can grow a key.
 *
 * `dirty` is cleared here and only here — it means "settings changed since they were last written",
 * which is exactly the question this button answers. {@link saveVisitorKey} leaves it alone.
 */
export async function saveVisitorSettings(deps: {
  api: VisitorCredentialFormPort;
  config: ByokConfig;
  writers: VisitorCredentialSettingsSaveWriters;
}): Promise<void> {
  const { config } = deps;
  const { setSettingsSaveState, setStored, setDirty } = deps.writers;

  const patch: SiteAssistantCredentialPatch = {
    provider: config.protocol,
    baseUrl: config.baseUrl,
    model: config.model,
  };

  setSettingsSaveState({ status: "saving" });
  try {
    const { data } = await deps.api.setAssistantSiteCredential(patch);
    setStored(data);
    setSettingsSaveState({ status: "saved", at: data.updatedAt });
    setDirty(false);
  } catch (e) {
    setSettingsSaveState({ status: "error", message: describeApiError(e, "failed to save the settings") });
  }
}

/**
 * Save key's status line — whether the KEY reached the server, and nothing else. One of four
 * mutually exclusive messages keyed on `saveState.status` (plus `stored` for the two "idle"
 * variants), pulled to a top-level pure function for the same reason as `AiAssistant.tsx`'s
 * `visitorCredentialKeyStatusMessage`.
 *
 * `dirty` is deliberately NOT read here any more (two-button split, 2026-09-02). It means "settings
 * changed since they were last written", which is {@link visitorCredentialSettingsStatusMessage}'s
 * question — under the KEY field it would have announced an unsaved model change as though the key
 * were the thing left unsaved.
 *
 * The "WHICH key is stored" question lives in the field's own masked placeholder
 * (`visitorCredentialApiKeyPlaceholder`, `AiAssistant.tsx`), which is where an operator looks for it.
 * That mask went through a full round trip of being removed and restored during design, so the
 * conclusion is worth recording here too: it is a deliberate, bounded disclosure — without it the
 * field is blank and cannot distinguish "nothing was ever saved" from "a key is saved and working",
 * an ambiguity worse than four characters.
 *
 * @param t - Defaults to English passthrough for `VisitorCredentialForm.unit.test.tsx`'s direct,
 *   locale-unaware calls, which keep asserting the exact English strings they always have.
 * @param storedKeyIsForOtherEndpoint - The controller's flag of the same name. When set, the idle line
 *   asks for this provider's key instead of reporting a stored key this provider cannot use.
 */
export function visitorCredentialSaveStatusMessage(
  saveState: VisitorCredentialFormController["saveState"],
  stored: VisitorCredentialFormController["stored"],
  t: Translate = (key) => key,
  storedKeyIsForOtherEndpoint = false,
): string | null {
  if (saveState.status === "saving") return t("Saving…");
  if (saveState.status === "saved") return t("Saved to the server, encrypted.");
  if (saveState.status !== "idle") return null;
  return visitorCredentialSaveIdleMessage({ stored, t, storedKeyIsForOtherEndpoint });
}

/** {@link visitorCredentialSaveStatusMessage}'s idle line on its own: always a string, so the Save
 *  key ⓘ (`VisitorCredentialKeyActions`) reads it without a null fallback that could never apply. */
export function visitorCredentialSaveIdleMessage(
  { stored, t, storedKeyIsForOtherEndpoint }: {
    stored: VisitorCredentialFormController["stored"];
    t: Translate;
    storedKeyIsForOtherEndpoint: boolean;
  },
  _optional: Record<string, never> = {},
): string {
  if (storedKeyIsForOtherEndpoint) return t(STORED_KEY_OTHER_PROVIDER_COPY);
  if (stored?.isSet) return t("Stored on the server, encrypted. Paste a new key to replace it.");
  return t("Paste your key, check it with Show, then press Save key.");
}

/**
 * Save settings' own status line.
 *
 * Says "Settings saved." and never anything about encryption or the server holding a key: this
 * button sends no `apiKey`, so borrowing {@link visitorCredentialSaveStatusMessage}'s "Saved to the
 * server, encrypted." would recreate — under a new button — the exact false confirmation the split
 * exists to remove.
 *
 * @param t - Same seam as its sibling above.
 */
export function visitorCredentialSettingsStatusMessage(
  settingsSaveState: VisitorCredentialFormController["settingsSaveState"],
  t: Translate = (key) => key,
): string | null {
  if (settingsSaveState.status === "saving") return t("Saving…");
  if (settingsSaveState.status === "saved") return t("Settings saved.");
  return null;
}

/**
 * The explicit "Test Key" press — extracted for the same reason as {@link saveVisitorCredential}.
 * Runs against WHATEVER endpoint is in `config`, preset or not, unlike the debounced automatic
 * discovery effect: an operator pressing a button labelled "Test Key" has deliberately chosen to
 * send this credential to the host they typed.
 */
async function runVisitorKeyTest(deps: {
  port: ExecutionPort;
  config: ByokConfig;
  setDiscovery: (state: ModelDiscoveryState) => void;
  setConfig: (updater: (current: ByokConfig) => ByokConfig) => void;
}): Promise<void> {
  const { port, config, setDiscovery, setConfig } = deps;
  setDiscovery({ status: "loading" });
  try {
    const models = (await port.listModels?.(config)) ?? [];
    setDiscovery({ status: "ok", models });
    setConfig((current) =>
      current.model.trim() || models.length === 0
        ? current
        : { ...current, model: models.find((m) => m === "gemini-flash-latest") ?? (models[0] as string) },
    );
  } catch (e) {
    setDiscovery({ status: "error", message: describeProbeError(e, "Could not reach the provider with that key") });
  }
}

/**
 * Refreshes discovery after an explicit connection test — extracted for the same reason as
 * {@link saveVisitorCredential}. The debounced effect can't recover from a transient discovery
 * failure on its own (nothing about the credential changed afterwards), so without this the
 * operator would be stuck looking at a stale error next to a connection that just went green. Only
 * called by {@link runVisitorTestConnection} below, on a successful test. A failed refresh reports
 * its reason through discovery's existing error state while preserving the successful connection
 * result; the provider can accept a connection but refuse its model-list endpoint.
 */
async function refreshVisitorDiscoveryAfterTest(deps: {
  port: ExecutionPort;
  config: ByokConfig;
  setDiscovery: (state: ModelDiscoveryState) => void;
}): Promise<void> {
  const { port, config, setDiscovery } = deps;
  if (!config.apiKey.trim()) return;
  try {
    const models = await port.listModels?.(config);
    if (models) setDiscovery({ status: "ok", models });
  } catch (error) {
    // The connection result is the answer the operator asked for, so keep it. The separate
    // discovery state must still explain why the model list could not be refreshed.
    setDiscovery({ status: "error", message: describeProbeError(error, "Model discovery failed") });
  }
}

/** Turns the port's raw `testConnection` result into the screen's `ConnectionTestState` — pulled
 *  out of {@link runVisitorTestConnection} per the complexity-pass extraction rule. This was an
 *  inline optional-chain/`||`/ternary cluster that put the parent at 10/5 — over the ceiling on
 *  cyclomatic alone once it tightened to ≤9/≤9 mid-pass. Same treatment as `AiAssistant.tsx`'s
 *  `visitorCredentialSaveStatusMessage` sibling. */
function connectionTestStateFromResult(result: { ok: boolean; message?: string } | undefined): ConnectionTestState {
  if (!result) return { status: "error", message: "Connection test failed" };
  if (result.ok) return { status: "ok", message: result.message };
  return { status: "error", message: result.message || "Connection test failed" };
}

/** The explicit "Test connection" press — extracted for the same reason as
 *  {@link saveVisitorCredential}. */
async function runVisitorTestConnection(deps: {
  port: ExecutionPort;
  config: ByokConfig;
  setConnectionTest: (state: ConnectionTestState) => void;
  setDiscovery: (state: ModelDiscoveryState) => void;
}): Promise<void> {
  const { port, config, setConnectionTest, setDiscovery } = deps;
  setConnectionTest({ status: "testing" });
  try {
    const result = await port.testConnection?.(config);
    setConnectionTest(connectionTestStateFromResult(result));
    if (result?.ok) await refreshVisitorDiscoveryAfterTest({ port, config, setDiscovery });
  } catch (e) {
    setConnectionTest({ status: "error", message: describeProbeError(e, "Connection test failed") });
  }
}

export interface VisitorCredentialFormDependencies {
  /** Follows `useAiAssistant`'s `{ port }` dependencies shape — required here
   *  (not defaulted internally), so the real client is supplied exactly once, by
   *  {@link useWiredVisitorCredentialForm} below, rather than by every caller re-stating the
   *  fallback. */
  port: VisitorCredentialFormPort;
}

/**
 * Everything `VisitorCredentialForm` does: config state, hydration from the server, the two debounced
 * and on-demand model-discovery paths, connection testing, and the explicit save. See this file's own
 * header for what this form is and `VisitorCredentialForm`'s doc comment in `AiAssistant.tsx` for the
 * screen it backs.
 *
 * `port` is injected — see `visitor-credential-form-port.hooks.ts` — rather than importing `lib/api`
 * directly, so a test can describe hydration/save against `createFakeVisitorCredentialFormPort`
 * instead of stubbing global `fetch` or spying on the module singleton.
 * {@link useWiredVisitorCredentialForm} below is the zero-argument pair `AiAssistant.tsx` actually
 * mounts.
 *
 * @param deps - `{ port }` — the site-credential client this form reads and writes through.
 * @returns The full form controller: config, discovery/connection-test state, and the save/test
 *   handlers `VisitorCredentialForm` renders.
 * @complexity Time: O(1) per call across every handler — one request per save/test/discovery pass,
 *   no caller-controlled collections. Space: O(1).
 */
export function useVisitorCredentialForm({
  // Renamed from the destructured `port` at the binding site — this function ALSO declares its own
  // local `port` below (the unrelated `ExecutionPort` used for model discovery/connection tests), and
  // the two would otherwise collide in the same scope. Same "rename the local binding, not the prop"
  // rule `INFO.md`'s components section documents for an identical name clash.
  port: credentialPort,
}: VisitorCredentialFormDependencies, { executionPort }: { executionPort?: ExecutionPort } = {}): VisitorCredentialFormController {
  // A ref so the hydration effect can read it without listing it as a dependency, and so swapping
  // the prop mid-life cannot re-run that one-shot effect. Same lifetime rule as `port` below (the
  // OTHER port — `ExecutionPort`, for model discovery/connection tests — not this credential one).
  const apiRef = useRef<VisitorCredentialFormPort>(credentialPort);

  // Anthropic until hydration says otherwise (owner, 2026-10-09; it was Google Gemini). The model
  // stays empty: an earlier revision hardcoded `gemini-flash-latest` purely to avoid a required-field
  // marker, which invited the operator to keep a value this form had invented. The model list is a
  // property OF THE KEY, so it stays empty until a key produces one. See `discovery` below, and
  // `rules.ts`'s `defaultVisitorCredentialConfig` / `hasSavedVisitorCredential`.
  const [config, setConfig] = useState<ByokConfig>(defaultVisitorCredentialConfig);

  const preset = useMemo(() => resolveSelectedPreset(DEFAULT_PROVIDER_PRESETS, config), [config]);
  // One port instance for this component's lifetime, matching `SettingsUi.tsx`'s `useRef` usage —
  // these are the SAME admin routes the Settings screen probes with, and they take the credential in
  // the request body rather than reading a stored one. That is what makes both controls below work
  // today, before this tab's own server-side store exists: they probe the key the operator just
  // typed, which is exactly the question being asked ("is this key any good, and what can it run?").
  // `useStoredCredential` is what makes both probes work against a key this browser does not have.
  // Without it, an operator returning to a screen with a saved key faces an empty field, so
  // "Test Key" and "Test connection" had nothing to send and sat disabled beside a working
  // credential. Settings → Execution mode deliberately does NOT opt in — different key, and an
  // implicit fallback there would probe the visitor credential instead of the admin's own.
  // The host probe transport can be injected without replacing the credential store or Jini policy.
  const port = useRef(executionPort ?? createExecutionPort({ useStoredCredential: true }));

  const [discovery, setDiscovery] = useState<ModelDiscoveryState>({ status: "idle" });
  const [connectionTest, setConnectionTest] = useState<ConnectionTestState>({ status: "idle" });

  /** The server's write-only view of what is currently stored (`isSet` + `masked`), never the key. */
  const [stored, setStored] = useState<SiteAssistantCredential | null>(null);
  const [loadState, setLoadState] = useState<VisitorCredentialFormController["loadState"]>({ status: "loading" });
  const [saveState, setSaveState] = useState<SaveState>({ status: "idle" });
  const [settingsSaveState, setSettingsSaveState] = useState<SaveState>({ status: "idle" });

  /**
   * True once the operator has actually changed something — what Save is enabled by.
   *
   * State rather than a ref because a button's disabled-ness has to re-render on it. Set ONLY from
   * {@link editConfig}, so neither hydration nor discovery seeding a model counts as an edit; without
   * that separation Save would light up on load offering to write back the values the server just
   * sent, and — if the initial GET had failed — to write this form's hardcoded defaults over a
   * perfectly good stored credential.
   */
  const [dirty, setDirty] = useState(false);

  /** Every edit that originates from a CONTROL goes through here, so `dirty` reflects the operator
   *  and never hydration or discovery. */
  function editConfig(next: ByokConfig) {
    setDirty(true);
    setConfig(next);
  }

  // Hydrate from the server once. This is what makes the screen honest across sessions: without it
  // an operator who saved a key last week reopens the tab, sees an empty key field, and reasonably
  // concludes nothing was ever stored. The KEY cannot come back (the route is write-only by design),
  // so what hydrates is everything else — provider, base URL, model (`rules.ts`'s
  // `hydrateVisitorCredentialConfig`) — plus `isSet`/`masked`, which is what the "A key is stored"
  // line under the field reports.
  useEffect(() => {
    let cancelled = false;
    apiRef.current
      .getAssistantSiteCredential()
      .then(({ data }) => {
        if (cancelled) return;
        setStored(data);
        setConfig((current) => hydrateVisitorCredentialConfig(current, data));
        setLoadState({ status: "ready" });
      })
      .catch((error: unknown) => {
        if (cancelled) return;
        setLoadState({ status: "error", message: describeApiError(error, "Could not load saved settings.") });
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const { apiKey, baseUrl, protocol } = config;
  const storedKeyIsForOtherEndpoint = storedKeyIsForOtherEndpointRule(stored, baseUrl);
  const usableKey = hasUsableKey(apiKey, stored, baseUrl);

  /**
   * Discovery on load, for a key this browser does not have.
   *
   * The debounced effect below only fires on TYPING, which is right for a key being entered for the
   * first time and useless for one already stored: the field is empty, nothing is typed, and the
   * operator sees no models at all for a credential the server can use perfectly well. So a stored
   * key gets one discovery pass when the screen opens.
   *
   * Runs off `stored?.isSet` rather than the mount, so it fires once hydration has confirmed a key
   * exists — and only when the field is empty, so it can never race or duplicate the typed path.
   *
   * Skipped when the stored key belongs to another endpoint (a provider switch): the server refuses
   * that probe, and the key line asks for this provider's key instead. Deliberately NOT keyed on that
   * flag: it also flips when "Save settings" re-points the stored row at the form's endpoint, and an
   * automatic probe at that moment would send the previous provider's key to the new one unasked.
   */
  // biome-ignore lint/correctness/useExhaustiveDependencies: keyed on stored flag + endpoint only — see doc comment above; `config` as a whole would re-run on every model/max-tokens edit.
  useEffect(() => {
    // Missing optional discovery must not leave the form waiting for work it cannot start.
    const listModels = port.current.listModels?.bind(port.current);
    if (!stored?.isSet || apiKey.trim() || storedKeyIsForOtherEndpoint || !listModels) return;
    let cancelled = false;
    setDiscovery({ status: "loading" });
    listModels({ ...config, apiKey: "" })
      .then((models) => {
        if (cancelled) return;
        setDiscovery({ status: "ok", models });
        setConfig((current) =>
          current.model.trim() || models.length === 0
            ? current
            : { ...current, model: models.find((m) => m === "gemini-flash-latest") ?? (models[0] as string) },
        );
      })
      .catch((e: unknown) => {
        if (cancelled) return;
        setDiscovery({ status: "error", message: describeProbeError(e, "Model discovery failed") });
      });
    return () => {
      cancelled = true;
    };
  }, [stored?.isSet, baseUrl, protocol]);

  // Nothing on this screen writes a credential except these two functions, called from the two Save
  // buttons. Why an explicit press rather than the debounce this used to be, and why each patch
  // carries what it carries — see `saveVisitorKey`/`saveVisitorSettings`'s own doc comments above
  // (moved WITH the functions in the complexity-pass extraction, not summarised here).
  const hasStoredKey = hasStoredCredential(stored);

  // One lane for both Save buttons, which can be enabled at the same time. The server builds every
  // write from the row it reads first (`site-credential-store.ts`'s `setSiteAssistantCredential`:
  // read → seal → upsert the whole merged record), so a key PUT and a settings PUT in flight together
  // each merge over the same old row and the later upsert reverts the other's field. Queued through
  // the shared lane, the second PUT reads what the first wrote. Tab-local — two tabs still race;
  // closing that needs a server-side check. Same shared primitive as
  // `use-other-credentials.hooks.ts`'s `writes`.
  const writes = useSerialWrites();

  function saveKey() {
    return writes.run({ task: () => saveVisitorKey({ api: apiRef.current, config, writers: { setSaveState, setStored, setConfig } }) });
  }

  function saveSettings() {
    return writes.run({ task: () =>
      saveVisitorSettings({
        api: apiRef.current,
        config,
        writers: { setSettingsSaveState, setStored, setDirty },
      }) },
    );
  }

  // `isPresetSuppliedEndpoint` (in `../rules.ts`) is the SECURITY GATE for the debounced discovery
  // effect below — read its doc comment there before touching either. Memoised on `baseUrl` alone,
  // matching the effect's own dependency list.
  const presetSuppliedEndpoint = useMemo(() => isPresetSuppliedEndpoint(baseUrl), [baseUrl]);

  /**
   * Debounced, key-driven model discovery.
   *
   * Keyed on the credential itself (key + endpoint), unlike `ExecutionTab`'s own effect which is
   * deliberately keyed only on the endpoint. That difference is the point of this screen: there, the
   * key is already saved and the operator is switching providers; here, the operator is entering a
   * key for the first time and the only useful moment to look up its models is right after they
   * finish typing it. The debounce is what makes keying on the key affordable.
   */
  // biome-ignore lint/correctness/useExhaustiveDependencies: keyed on the credential itself (key+endpoint); `config` intentionally excluded so editing model/max-tokens doesn't re-trigger discovery.
  useEffect(() => {
    // The endpoint condition is the security gate above — NOT an optimization. Removing it
    // reintroduces the prefix-walk credential leak; read that comment before touching this line.
    // A transport without optional model discovery has no automatic work to start.
    const listModels = port.current.listModels?.bind(port.current);
    if (!apiKey.trim() || !presetSuppliedEndpoint || !listModels) {
      setDiscovery({ status: "idle" });
      return;
    }
    let cancelled = false;
    setDiscovery({ status: "loading" });
    const timer = setTimeout(() => {
      listModels({ ...config, apiKey, baseUrl, protocol })
        // `cancelled` guards the classic out-of-order finish: a slow request for an earlier,
        // half-typed key must never overwrite the result for the key currently in the field.
        .then((models) => {
          if (cancelled) return;
          setDiscovery({ status: "ok", models });
          // Seed the model field from the DISCOVERED list when it is still empty — never from a
          // hardcoded constant, which is what an earlier revision did and what made the field state
          // something this form had invented rather than something the key actually offers.
          // Preferring the server's real default when the account has it keeps the UI agreeing with
          // `site-assistant.ts`'s own `DEFAULT_MODEL`; otherwise the first entry is simply a valid
          // starting point the operator can change. Without this the operator is stuck: `model` is a
          // required field, so `Test connection` stays disabled until something fills it.
          setConfig((current) => {
            if (current.model.trim() || models.length === 0) return current;
            return { ...current, model: models.find((m) => m === "gemini-flash-latest") ?? (models[0] as string) };
          });
        })
        .catch((e: unknown) =>
          !cancelled && setDiscovery({ status: "error", message: e instanceof Error ? e.message : "Model discovery failed" }),
        );
    }, MODEL_DISCOVERY_DEBOUNCE_MS);
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [apiKey, baseUrl, protocol, presetSuppliedEndpoint]);

  // The explicit "Test Key" / "Test connection" presses — see `runVisitorKeyTest` and
  // `runVisitorTestConnection`'s own doc comments above for why these run against WHATEVER endpoint
  // is in the field (unlike the debounced automatic effect above) and how the post-test discovery
  // refresh works.
  //
  // With nothing typed and the stored key saved for another endpoint, neither press sends anything:
  // the server would refuse, and the key line already asks for this provider's key. The buttons are
  // disabled in that state too; this keeps the hook honest for any other caller.
  function runKeyTest() {
    if (storedKeyBlocksProbe(apiKey, stored, baseUrl)) return Promise.resolve();
    return runVisitorKeyTest({ port: port.current, config, setDiscovery, setConfig });
  }

  function runTestConnection() {
    if (storedKeyBlocksProbe(apiKey, stored, baseUrl)) return Promise.resolve();
    return runVisitorTestConnection({ port: port.current, config, setConnectionTest, setDiscovery });
  }

  /**
   * The provider picker's selection handler — backs the two chip rows ("Protocols" / "Gateways")
   * that let an operator choose Anthropic, OpenAI, Azure OpenAI, Google Gemini, OpenRouter, or
   * Ollama, rendered by the view from `@jini-ai/ui`'s `groupPresets`/`ProviderChipGroup` (structure
   * and wiring lifted verbatim from `ExecutionTab`'s own BYOK section, the same one the Settings →
   * Execution mode screen renders).
   *
   * `nextConfigForPresetSelect` is where the non-obvious behaviour lives — it snapshots the OUTGOING
   * provider's credentials into `savedByProviderId` before loading the incoming preset's own saved
   * draft, which is what stops one provider's key from making an unrelated provider's chip read as
   * "configured". Hand-rolling `setConfig({protocol, baseUrl})` here would look correct and quietly
   * lose that.
   *
   * `../rules.ts`'s `configuredPresetIds` reads the same per-provider drafts for the chip dots, so a
   * chip's filled dot means "this provider has complete credentials in this form", not "this one is
   * saved on the server". Those are different claims and only the save line under the key field makes
   * the second one.
   */
  const selectPreset = (next: ProviderPreset) => {
    editConfig(nextConfigForPresetSelect(config, next));
    // Both are properties OF THE OUTGOING PROVIDER and neither survives the switch. Left in place,
    // the previous provider's "42 models available" and green connection result would sit under a
    // different provider's empty key field, describing a credential that is no longer in the form.
    setDiscovery({ status: "idle" });
    setConnectionTest({ status: "idle" });
  };
  const selectPresetById = (presetId: string) => {
    const next = DEFAULT_PROVIDER_PRESETS.find((p) => p.id === presetId);
    if (next) selectPreset(next);
  };
  const configuredIds = configuredPresetIdsRule(config);

  return {
    loadState,
    config,
    editConfig,
    preset,
    discovery,
    connectionTest,
    stored,
    saveState,
    settingsSaveState,
    dirty,
    hasUsableKey: usableKey,
    hasStoredKey,
    storedKeyIsForOtherEndpoint,
    configuredPresetIds: configuredIds,
    selectPreset,
    providerGroups: visitorProviderGroups(configuredIds),
    selectPresetById,
    saveKey,
    saveSettings,
    runKeyTest,
    runTestConnection,
  };
}

/**
 * Binds the real `/api/.../assistant/site-credential` client — see
 * `visitor-credential-form-dependencies.hooks.ts`.
 *
 * The zero-argument-dependencies half of the `useX(dependencies)` / `useWiredX()` pair, so
 * `AiAssistant.tsx` composes this and a test composes {@link useVisitorCredentialForm} with
 * `createFakeVisitorCredentialFormPort` (or, as `use-visitor-credential-form.unit.test.ts`'s own
 * pre-existing "F05 coupling fix" tests do, a hand-rolled fake satisfying
 * {@link VisitorCredentialFormPort}).
 *
 * @returns The full form controller, wired to the real site-credential client.
 */
export function useWiredVisitorCredentialForm(): VisitorCredentialFormController {
  return useVisitorCredentialForm({ port: defaultVisitorCredentialFormPort });
}

import { DEFAULT_PROVIDER_PRESETS } from "@jini-ai/integrations/media-providers/catalog";
import { groupPresets, isProviderConfigured, type ApiProtocol, type ByokConfig, type ProviderPreset } from "@jini-ai/ui/core";

import { ApiError, describeApiError as describeApiErrorDefault, type SiteAssistantCredential } from "../../lib/api";
import { storedCredentialHint } from "../../lib/credential-copy";

/**
 * @file Pure logic for the `ai-assistant` feature — everything that computes a value rather than
 * rendering one.
 *
 * Follows the same convention `features/posts/rules.ts` establishes for this app: the bar for
 * landing here is "does it compute something", not "is it rendered". Several of these were plain
 * `const`s or inline expressions inside `VisitorCredentialForm`'s body — reachable only by
 * rendering the whole tab and driving state through it — and are exported here so each can be
 * asserted directly.
 */

/** Overrides layered on the shared default (`lib/api.ts`'s `describeApiError`) — this screen's
 *  `FORBIDDEN` copy names the specific setting, unlike the generic "You do not have permission to
 *  do that." most other screens use for the same code (audit cross-cutting finding #2).
 *
 * @complexity Time/space: O(1) — a fixed number of code checks, no iteration.
 * @overallScore 100
 */
export function describeApiError(e: unknown, fallback: string): string {
  if (e instanceof ApiError) {
    if (e.code === "FORBIDDEN") return "You do not have permission to change the AI assistant's settings.";
    if (e.code === "ASSISTANT_SETTINGS_VALIDATION_ERROR") return e.message || "That value was rejected.";
    // ADR-058's fail-closed branch, translated rather than shown raw. The server's own message names
    // the variable, but it names it in server-operator language ("set TOVU_SITE_KEY (a
    // hex-encoded site key) in the server environment") arriving in a UI where the reader has just
    // pasted a key and been told it did not save. The distinction that matters to them is that
    // NOTHING IS WRONG WITH THEIR KEY — the server has no site key to encrypt it under.
    if (e.code === "SECRET_STORE_UNCONFIGURED")
      return "The server can't store keys yet: it has no site key. Set TOVU_SITE_KEY (hex) and restart. Your key was not saved.";
    if (e.code === "SITE_CREDENTIAL_VALIDATION_ERROR") return e.message || "That value was rejected.";
  }
  return describeApiErrorDefault(e, fallback);
}

// The stored-key endpoint rules (`storedKeyIsForOtherEndpoint`, `hasUsableKey`, `storedKeyBlocksProbe`,
// `describeProbeError` and their two copy constants) live in `lib/stored-credential-endpoint.ts`, shared
// with the admin's own key screen.

/** Whether the server currently has a credential stored for this site — the "leave the stored key
 *  alone" case `saveVisitorSettings` relies on when it writes a patch with no `apiKey`.
 *
 * @complexity Time/space: O(1).
 * @overallScore 100
 */
export function hasStoredCredential(stored: SiteAssistantCredential | null): boolean {
  return stored?.isSet === true;
}

/**
 * SECURITY GATE on automatic discovery — `true` only when the endpoint is one a PRESET supplied,
 * never one the operator typed.
 *
 * This closes a confirmed credential-transmission bug rather than avoiding a hypothetical one. See
 * `ADS-memory/reports/findings/2026-08-04-byok-discovery-keystroke-key-leak.md`: Jini's
 * `ExecutionTab` lists `config.byok.baseUrl` as a discovery dependency and passes the whole
 * `ByokConfig` — which carries `apiKey` — with no debounce. Consequence, measured live by another
 * session: with a key already present, typing an endpoint transmits that live key to every
 * intermediate prefix of the hostname. `https://api.example.com` sends it to `https://a`,
 * `https://ap`, `https://api`, and so on — each prefix that resolves is a third party receiving a
 * credential the operator never meant to give it. It composes badly with the SSRF guard's
 * deliberate allowance of loopback on any port, which turns a typed `http://localhost:NNNN` into a
 * key-bearing walk of local ports.
 *
 * A debounce alone does NOT fix this, which is why this gate exists in addition to one: debouncing
 * cuts ~30 requests to a handful, but any pause mid-typing still fires, and a pause mid-typing is
 * exactly when the URL is a partial hostname. The number of unintended recipients goes down; it
 * does not go to zero.
 *
 * So the rule here is about the DESTINATION, not the timing: auto-discovery may only ever send the
 * key somewhere a preset already vouched for. A custom or hand-typed endpoint still works — it just
 * requires the operator to press "Test connection", which is an explicit, deliberate act of
 * pointing a credential at a host they chose. That is the "gate the effect on a committed baseUrl"
 * option the finding lists, tightened to "committed by an explicit action".
 *
 * @complexity Time: O(p) in the number of provider presets (a small, fixed constant); space: O(1).
 * @overallScore 100
 */
export function isPresetSuppliedEndpoint(baseUrl: string): boolean {
  const trimmed = baseUrl.trim();
  // Azure OpenAI's preset ships `baseUrl: ''` as a placeholder, so without this guard a cleared
  // field "matches" it and authorizes key-bearing discovery with no destination at all (F4.4/F6.2).
  if (trimmed === "") return false;
  return DEFAULT_PROVIDER_PRESETS.some((p) => !p.custom && p.baseUrl === trimmed);
}

/** Which provider presets this form's current credentials already satisfy — the filled/unfilled
 *  dot each `ProviderChipGroup` chip renders. Reads the per-provider drafts, so a chip's filled dot
 *  means "this provider has complete credentials in this form", not "this one is saved on the
 *  server"; only the save line under the key field makes the second claim.
 *
 * @complexity Time: O(p) in the number of provider presets; space: O(k) for the k configured ids.
 * @overallScore 100
 */
export function configuredPresetIds(config: ByokConfig): Set<string> {
  return new Set(DEFAULT_PROVIDER_PRESETS.filter((p) => isProviderConfigured(config, p)).map((p) => p.id));
}

/**
 * The form's config after hydration from the server's stored view — `protocol`/`providerId` as well as
 * `baseUrl`/`model`.
 *
 * `saveVisitorSettings` writes `provider: config.protocol`, so a hydration that skipped the provider
 * left an Anthropic (or any non-Google) credential under the form's Google default, and the next
 * model-only "Save settings" relabelled the stored row Google. The server keeps no preset id, so
 * `providerId` is recovered from the endpoint: the preset whose protocol and base URL both match, else
 * the preset of that protocol whose URL the operator supplies (Azure), else `null` — the custom
 * endpoint, which is what an endpoint no preset owns is. A `provider` string that is not a protocol
 * this form knows leaves protocol and preset as they were rather than guessing.
 *
 * @complexity Time: O(p) in the number of provider presets; space: O(1).
 */
export function hydrateVisitorCredentialConfig(current: ByokConfig, stored: SiteAssistantCredential): ByokConfig {
  // Nothing saved yet: the server still answers with its own default `provider`, which would
  // override the form's Anthropic default with a provider the operator never chose (2026-10-09).
  if (!hasSavedVisitorCredential(stored)) return current;
  const baseUrl = stored.baseUrl ?? current.baseUrl;
  const model = stored.model ?? current.model;
  const protocol = knownProtocol(stored.provider);
  if (protocol === null) return { ...current, baseUrl, model };
  const presets = DEFAULT_PROVIDER_PRESETS.filter((p) => !p.custom && p.protocol === protocol);
  const preset = presets.find((p) => p.baseUrl === baseUrl) ?? presets.find((p) => p.baseUrl === "");
  return { ...current, protocol, providerId: preset?.id ?? null, baseUrl, model };
}

/** `provider` as an {@link ApiProtocol} when some preset speaks it, else `null`.
 *  @complexity Time: O(p) in the number of provider presets; space: O(1). */
function knownProtocol(provider: string): ApiProtocol | null {
  return DEFAULT_PROVIDER_PRESETS.find((p) => p.protocol === provider)?.protocol ?? null;
}

/** The server's `••••<last 4>` shown IN the key field — which key is stored, answered where the
 *  operator is already looking, instead of in a sentence underneath. `undefined` (no placeholder)
 *  whenever nothing is stored or the server didn't send a mask.
 *
 *  Safe precisely BECAUSE it is a placeholder: `config.apiKey` stays empty, so `saveKey`
 *  sends nothing at all and the stored key is left alone. A pre-filled value here would be a
 *  real value the save path would persist AS the key. Pulled to a top-level pure function per the
 *  complexity-pass extraction rule — one of the few remaining branch points in
 *  `VisitorCredentialForm` itself once {@link VisitorCredentialKeyFooter} moved out.
 *
 *  Also `undefined` when the stored key belongs to another endpoint: after a provider switch the mask
 *  would read as a key saved for the provider now selected. */
export function visitorCredentialApiKeyPlaceholder(
  stored: SiteAssistantCredential | null,
  storedKeyIsForOtherEndpoint = false,
): string | undefined {
  return storedCredentialHint({ stored, storedKeyIsForOtherEndpoint });
}

/** The Visitor tab's status pill: what visitors get right now. */
export type VisitorAssistantStatus = "on" | "off" | "needs-key";

/**
 * The Visitor tab's status pill and enable-switch gate (2026-10-09 redesign).
 *
 * "Needs a key" wins over the switch's own value: an enabled assistant with no stored key is
 * mounted but cannot answer, which is exactly the silent failure this tab exists to surface.
 * The switch can always be turned OFF; it can only be turned ON once a key is saved.
 *
 * @complexity Time/space: O(1).
 */
export function visitorAssistantStatus(required: { publicEnabled: boolean; hasStoredKey: boolean }, _optional = {}): {
  status: VisitorAssistantStatus; canEnable: boolean;
} {
  const status: VisitorAssistantStatus = !required.hasStoredKey ? "needs-key" : required.publicEnabled ? "on" : "off";
  return { status, canEnable: required.hasStoredKey || required.publicEnabled };
}

/** The pill's label and its one short hint line, per status (English keys; the view runs `t`). */
export const VISITOR_STATUS_COPY: Record<VisitorAssistantStatus, { label: string; hint: string }> = {
  on: { label: "On", hint: "Visitors can chat with it on every public page." },
  off: { label: "Off", hint: "Visitors see no assistant." },
  "needs-key": { label: "Needs a key", hint: "Save a key in step 1 first." },
};

/**
 * Which status lines show under the visitor key field (2026-10-09 redesign). The two IDLE lines are
 * instructions, not results ("Checks the key against the provider…", "Paste your key…"), so they
 * live in the ⓘ tips beside Test key / Save key; a line shows only once there is something to report.
 * The other-provider warning is the exception: it is idle, but it is a fact the operator must see.
 *
 * @complexity Time/space: O(1).
 */
export function visitorKeyFooterLines(required: {
  discoveryStatus: string; saveStatus: string; storedKeyIsForOtherEndpoint: boolean;
}, _optional = {}): { keyStatus: boolean; saveLine: boolean } {
  return {
    keyStatus: required.discoveryStatus !== "idle",
    saveLine: required.saveStatus !== "idle" || required.storedKeyIsForOtherEndpoint,
  };
}

/** The preset the Visitor tab starts on when nothing is saved: Anthropic (owner, 2026-10-09). */
export const DEFAULT_VISITOR_PRESET_ID = "anthropic";

/**
 * The form's starting config: the default preset's protocol and endpoint, an empty key and an empty
 * model. The model stays empty on purpose: the model list is a property of the key, so it waits
 * for one (see the hook's `discovery`). Hydration replaces this when something is saved.
 *
 * @complexity Time: O(p) in the number of provider presets; space: O(1).
 */
export function defaultVisitorCredentialConfig(
  _required: Record<string, never> = {},
  { presets = DEFAULT_PROVIDER_PRESETS }: { presets?: typeof DEFAULT_PROVIDER_PRESETS } = {},
): ByokConfig {
  const preset = presets.find((p) => p.id === DEFAULT_VISITOR_PRESET_ID) ?? presets[0];
  return { protocol: preset.protocol, providerId: preset.id, apiKey: "", baseUrl: preset.baseUrl, model: "" };
}

/** True once the server holds anything for this site: a key, or saved provider settings. A row with
 *  none of these is the server's empty default, not the operator's choice.
 *  @complexity Time/space: O(1). */
export function hasSavedVisitorCredential(stored: SiteAssistantCredential): boolean {
  return stored.isSet === true || stored.baseUrl !== null || stored.model !== null || stored.updatedAt !== null;
}

/** One `<optgroup>` of the Visitor tab's Provider select. */
export interface VisitorProviderGroup {
  label: "Protocols" | "Gateways";
  options: { preset: ProviderPreset; configured: boolean }[];
}

/**
 * The Provider select's two optgroups, protocols then gateways (`groupPresets`' order), each option
 * flagged when this form already holds complete credentials for it (the old chips' filled dot).
 *
 * @complexity Time: O(p) in the number of provider presets; space: O(p).
 */
export function visitorProviderGroups(configuredIds: ReadonlySet<string>): VisitorProviderGroup[] {
  const { protocols, gateways } = groupPresets(DEFAULT_PROVIDER_PRESETS);
  const toOptions = (presets: readonly ProviderPreset[]) => presets.map((preset) => ({ preset, configured: configuredIds.has(preset.id) }));
  return [
    { label: "Protocols", options: toOptions(protocols) },
    { label: "Gateways", options: toOptions(gateways) },
  ];
}

import { api, type AdminContentType } from "@/lib/api";
import type { CollectionsPort } from "./collections-port.hooks";

/**
 * @file The only place `use-collections.hooks.ts` reaches `lib/api` — see `collections-
 * port.hooks.ts` for why the split exists.
 */

/** The live implementation, as a module-level singleton. */
export const defaultCollectionsPort: CollectionsPort = {
  listContentTypes: () => api.listContentTypes(),
  contentTypeLifecycle: (input) => api.contentTypeLifecycle(input),
};

/** Seed state for {@link createFakeCollectionsPort}. */
export interface FakeCollectionsPortOptions {
  types?: AdminContentType[];
  /** When set, `contentTypeLifecycle()` rejects with this instead of resolving — for
   *  action-failure tests. */
  lifecycleError?: Error;
}

/**
 * An in-memory {@link CollectionsPort} for tests — "every port gets a fake" (see
 * `assistant-chats-dependencies.hooks.ts`). `contentTypeLifecycle` mutates the fake's own store in
 * place, matching the real route's read-your-writes shape (a subsequent `listContentTypes()` sees
 * the update) so a test can drive `load()`'s re-fetch the same way `runLifecycle` does in
 * production.
 */
export function createFakeCollectionsPort(options: FakeCollectionsPortOptions = {}): CollectionsPort & {
  /** Every content type currently in the fake's store, in list order. */
  readonly types: AdminContentType[];
} {
  const types = [...(options.types ?? [])];

  return {
    types,
    async listContentTypes() {
      return { items: [...types] };
    },
    async contentTypeLifecycle({ key, op, expectedVersion }) {
      if (options.lifecycleError) throw options.lifecycleError;
      const index = types.findIndex((t) => t.key === key);
      if (index < 0) throw new Error(`fake content type not found: ${key}`);
      const nextStatus = op === "reactivate" ? "active" : op === "deprecate" ? "deprecated" : "tombstone";
      const updated: AdminContentType = { ...types[index]!, status: nextStatus, version: expectedVersion + 1 };
      types[index] = updated;
      return { contentType: updated };
    },
  };
}

import { useState } from "react";

import { describeApiError, type AdminContentType } from "@/lib/api";
import { useFetchMutation, useFetchQuery } from "@jini-ai/ui/fetch-query";
import { collectionEmbedSnippet, isUserCollection, KEYS, type LifecycleConfirmOp } from "../rules";
import { useAdminLocale } from "@/hooks/use-admin-locale.hooks";
import { lifecycleFailureMessage, t as translate } from "../collections-i18n";
import { defaultCollectionsPort } from "./collections-dependencies.hooks";
import type { CollectionsPort } from "./collections-port.hooks";

/**
 * @file Everything the Collections LIST screen (content-type registry + the three dialogs' open/
 * close state) does, so `Collections`'s exported component in `Collections.tsx` is only markup.
 *
 * Extracted verbatim — same state, same load, same lifecycle-action error handling. Each dialog's
 * OWN state (`NewContentTypeDialog`, `EditFieldsDialog`, `LifecycleConfirmDialog`) lives in its own
 * hook file — this hook only owns which dialog is open and the shared `runLifecycle` action all
 * three lifecycle row-menu items and the confirm dialog ultimately call.
 *
 * Naming follows `hooks/use-settings-slice.hooks.ts`: `use-<thing>.hooks.ts`. Feature-local because
 * nothing outside `features/collections` needs it.
 *
 * `port`/`locale` are injected — see `collections-port.hooks.ts` — rather than reaching `lib/api`/
 * `useAdminLocale()` directly, so a test can describe load/lifecycle outcomes against
 * `createFakeCollectionsPort` instead of stubbing global `fetch`. `useWiredCollections` below is
 * the pair `Collections.tsx` actually mounts.
 *
 * `t` (standing i18n rule, 2026-08-11 — a component with a hook gets a BOUND `t` from that hook,
 * not its own `useAdminLocale()`/dictionary import, same shape `use-pages.hooks.ts` established):
 * injected alongside `port`/`locale` because `Collections.tsx` and its three dialogs need translated
 * UI copy. `collections-i18n.ts`'s own `t(locale, key)` — aliased `translate` here to avoid
 * colliding with this file's own bound `(key) => string` closure — stays a direct, uninjected
 * import: it's a pure `COLLECTIONS_DICT[locale]?.[key] ?? key` lookup that already takes `locale`
 * as an explicit argument, not a host reach (see wired-hooks-convention.md's "pure, no-I/O rules"
 * carve-out). `useAdminLocale()` and `COLLECTIONS_DICT` are read only inside
 * {@link useWiredCollections}.
 *
 * `@jini-ai/ui/fetch-query` migration (2026-08-12): the content-type list read is now `useFetchQuery({ key:
 * KEYS.list, ... })`; `runLifecycle` is a `useFetchMutation` that `invalidates: [KEYS.list]` — which
 * cascades to every entries list and open entry editor too, per `rules.ts`'s `KEYS` doc, since a
 * lifecycle change (or a field-schema edit via `EditFieldsDialog`) can change what those screens show.
 */

export interface CollectionsController {
  /** `null` until the initial load settles — the caller renders a loading state. */
  types: AdminContentType[] | null;
  error: string | null;
  showNewDialog: boolean;
  setShowNewDialog: (show: boolean) => void;
  /** The lifecycle op a row-menu selection is asking to confirm, and which content type it targets
   *  — `null` when `LifecycleConfirmDialog` is closed. Reactivate skips this entirely (see
   *  `runLifecycle`'s call sites): only Deprecate/Tombstone are confirm-gated. */
  pendingLifecycle: { op: LifecycleConfirmOp; contentType: AdminContentType } | null;
  setPendingLifecycle: (value: { op: LifecycleConfirmOp; contentType: AdminContentType } | null) => void;
  /** The content type `EditFieldsDialog` is open for — `null` when it is closed. */
  editingFieldsFor: AdminContentType | null;
  setEditingFieldsFor: (value: AdminContentType | null) => void;
  actionError: string | null;
  load: () => void;
  runLifecycle: (contentType: AdminContentType, op: "deprecate" | "reactivate" | "tombstone") => Promise<void>;
  /** The content-type key whose "Copy embed code" button most recently wrote to the clipboard —
   *  `null` once the transient window elapses. Keyed by `key`, not a single boolean, so only the
   *  row that was actually clicked shows "Copied". */
  copiedKey: string | null;
  /** Set when the most recent copy attempt could not reach the clipboard (denied permission, or no
   *  Clipboard API in an insecure context): the row it names shows `snippet` as selectable text so
   *  the operator can copy it by hand instead of getting a silent dead click. `null` otherwise; a
   *  later successful copy clears it. */
  copyFallback: { key: string; snippet: string } | null;
  /** Writes `collectionEmbedSnippet(contentType.key)` to the clipboard and flips `copiedKey` for
   *  1.5s, mirroring `use-edit-media-panel.hooks.ts`'s `copyHash`/`copyUrl` precedent. A failed
   *  write sets {@link copyFallback} instead — this row has no visible snippet text of its own. */
  copyEmbedCode: (contentType: AdminContentType) => Promise<void>;
  /** Bound translator — `Collections.tsx`'s and its three dialogs' only source of UI copy; see this
   *  file's own header for why it arrives via the hook rather than direct `useAdminLocale()`. */
  t: (key: string) => string;
  /** The raw resolved locale — exposed only because `contentTypeMenuItems` (`../rules.ts`)
   *  genuinely needs it, not `t`, same "row-menu builder is a different, out-of-scope thing"
   *  precedent `use-pages.hooks.ts` cites for `pageRowMenuItems`. */
  locale: string;
}

export interface CollectionsDependencies {
  port: CollectionsPort;
  locale: string;
  t: (key: string) => string;
}

export function useCollections(deps: CollectionsDependencies): CollectionsController {
  const { port, locale, t } = deps;
  const list = useFetchQuery({ key: KEYS.list, fetch: () => port.listContentTypes() });
  // System types (`widget`/`widget_area`/`menu`) back platform mechanics, not a collection an
  // operator manages here — never shown on this screen.
  const types = list.data?.items ? list.data.items.filter((ct) => isUserCollection(ct.key)) : null;

  const [showNewDialog, setShowNewDialog] = useState(false);
  const [pendingLifecycle, setPendingLifecycle] = useState<{ op: LifecycleConfirmOp; contentType: AdminContentType } | null>(null);
  const [editingFieldsFor, setEditingFieldsFor] = useState<AdminContentType | null>(null);
  // The op/label the CURRENTLY (or most recently) in-flight `runLifecycle` call was for — needed
  // because `lifecycleFailureMessage` names both, but `pendingLifecycle` is the CONFIRM DIALOG's own
  // state and is `null` for Reactivate (never confirm-gated — see `runLifecycle`'s call sites), so it
  // cannot be reused here without misattributing a failed Reactivate's message to "deprecate".
  const [lastAttempt, setLastAttempt] = useState<{
    op: "deprecate" | "reactivate" | "tombstone";
    contentType: AdminContentType;
  } | null>(null);
  const [copiedKey, setCopiedKey] = useState<string | null>(null);
  const [copyFallback, setCopyFallback] = useState<{ key: string; snippet: string } | null>(null);

  const lifecycleMutation = useFetchMutation({
    run: ({ input }: { input: { key: string; op: "deprecate" | "reactivate" | "tombstone"; expectedVersion: number } }) =>
      port.contentTypeLifecycle(input),
  }, {
    invalidates: [KEYS.list],
  });

  async function runLifecycle(contentType: AdminContentType, op: "deprecate" | "reactivate" | "tombstone") {
    setLastAttempt({ op, contentType });
    try {
      await lifecycleMutation.mutate({ input: { key: contentType.key, op, expectedVersion: contentType.version } });
    } catch {
      // already surfaced through lifecycleMutation.error -> actionError below
    }
  }

  async function copyEmbedCode(contentType: AdminContentType): Promise<void> {
    const snippet = collectionEmbedSnippet(contentType.key);
    try {
      await navigator.clipboard.writeText(snippet);
      setCopyFallback(null);
      setCopiedKey(contentType.key);
      setTimeout(() => setCopiedKey(null), 1500);
    } catch {
      // Clipboard access denied, or `navigator.clipboard` absent (insecure context) — show the
      // snippet for manual selection; see `CollectionsController.copyFallback`.
      setCopyFallback({ key: contentType.key, snippet });
    }
  }

  const error = list.error ? describeApiError(list.error, translate({ locale: locale, key: "failed to load content types" })) : null;
  const actionError =
    lifecycleMutation.error && lastAttempt
      ? describeApiError(lifecycleMutation.error, lifecycleFailureMessage(locale, lastAttempt.op, lastAttempt.contentType.label))
      : null;

  return {
    types,
    error,
    showNewDialog,
    setShowNewDialog,
    pendingLifecycle,
    setPendingLifecycle,
    editingFieldsFor,
    setEditingFieldsFor,
    actionError,
    load: list.refetch,
    runLifecycle,
    copiedKey,
    copyFallback,
    copyEmbedCode,
    t,
    locale,
  };
}

/**
 * Binds the real `/api/.../content-types` client, the resolved `useAdminLocale()` value, and a
 * `COLLECTIONS_DICT`-bound translator — see
 * `collections-dependencies.hooks.ts`. The zero-argument-deps half of the `useX(dependencies)` /
 * `useWiredX()` pair, so `Collections.tsx` composes this and a test composes {@link useCollections}
 * with `createFakeCollectionsPort`.
 */
export function useWiredCollections(): CollectionsController {
  const locale = useAdminLocale();
  const t = (key: string): string => translate({ locale: locale, key: key });
  return useCollections({ port: defaultCollectionsPort, locale, t });
}

import type { RowMenuItem } from "@jini-ai/admin/react";
import { embedMarkerSnippet } from "@jini-ai/cms/widgets/markers";

import { ApiError, describeApiError, type AdminContentType, type ContentTypeFieldDef } from "../../lib/api";
import type { Translate } from "@jini-ai/ui/panel-kit";
import type { QueryKey } from "@jini-ai/core/fetch";
import { isVersionConflict } from "../../lib/version-conflict";
import { t as translate } from "./collections-i18n";

/**
 * @file Pure logic for the `collections` feature (top-level Collections screen only — see
 * `CollectionEntries.tsx`/`CollectionEntryEditor.tsx` for the entry-level screens' own extraction)
 * — everything that computes a value rather than rendering one. Follows the convention
 * `features/posts/rules.ts` establishes: no React, no hooks, importable and directly testable.
 *
 * One deliberate exception to "pure": {@link emptyField} and {@link draftFieldsFromContentType}
 * both advance a shared, module-level `nextRowId` counter. It has to be ONE shared counter rather
 * than one per hook file — `NewContentTypeDialog` and `EditFieldsDialog` are mutually exclusive in
 * the UI, but the pre-extraction code already shared a single counter across both (open New,
 * cancel, then open Edit continues the same sequence rather than resetting), and splitting it into
 * two independent counters per hook file would be an observable behaviour change, not a neutral
 * refactor. Keeping it here, imported by both hook files, is what preserves the single instance —
 * ES modules are singletons, so both hooks see the same counter.
 *
 * `KEYS` (fetch-query migration, 2026-08-12): `entries(key)` is a real child of `list` — a content
 * type's fields/lifecycle changing SHOULD refresh its entries list, matching
 * `@jini-ai/ui/fetch-query`'s `QueryKey` prefix-invalidation contract.
 *
 * `entry(key, id)` is deliberately a SIBLING of `entries(key)`, not a child of it — both nest under
 * `list` (so a content-type field/lifecycle change still refreshes an open editor's own read, which
 * IS wanted), but `entry` does NOT share `entries`' own prefix. It first shared it, on the reasoning
 * that saving one entry should refresh that type's list; it does, `save()`/`toggleLifecycle()` in
 * `use-collection-entry-editor.hooks.ts` still `invalidates: [KEYS.entries(key)]` for exactly that.
 * The bug that reasoning missed: nesting the other way ALSO means invalidating `entries(key)`
 * refetches the editor's OWN currently-open `entry(key, id)` read — so every save silently fired 3
 * extra background requests (content-types/entries/taxonomies) immediately after the save's own
 * request, which several `use-collection-entry-editor.unit.test.tsx` assertions on "the last fetch
 * call" caught as a real, observable regression, not just a test-harness inconvenience.
 */
export const KEYS = {
  list: ["content-types"] as QueryKey,
  entries: (contentTypeKey: string): QueryKey => ["content-types", contentTypeKey, "entries"],
  entry: (contentTypeKey: string, entryId: string | null): QueryKey => [
    "content-types",
    contentTypeKey,
    "entry",
    entryId ?? "new",
  ],
};

/**
 * Content types this screen never lists as a user-manageable collection: `widget`/`widget_area`
 * back the widget-placement system, and `menu` is `NAV_MENU_CONTENT_TYPE`
 * (`node_modules/@jini-ai/cms/dist/navigation/types.js:10`). This is the admin-side copy of the
 * server's own system-type list — admin cannot import website code, the same accepted
 * duplication the media accept-lists already carry.
 */
export const ADMIN_SYSTEM_CONTENT_TYPES = ["widget", "widget_area", "menu"];

/**
 * @complexity Time/space: O(1) — one `Array.includes` over a fixed 3-item list.
 */
export function isUserCollection(key: string): boolean {
  return !ADMIN_SYSTEM_CONTENT_TYPES.includes(key);
}

/**
 * The embeddable marker for "list this content type's entries here" — `id` carries the content
 * type's own key, never a row's UUID (the collection marker reads `id` first, `typeKey` as a
 * fallback, per the fix landed in `a9ab19c4f`). Keeps the wrapper `<div data-embed-config='...'>`
 * shape every other embeddable type already uses.
 *
 * A thin wrapper over `@jini-ai/cms/widgets/markers`'s generalised `embedMarkerSnippet` (readable-slugs S5b,
 * 2026-09-23) — this was the one admin-generated marker that existed before that generalisation, so
 * it moved onto the shared builder rather than keeping its own copy of the template. Byte-for-byte
 * unchanged output.
 *
 * @complexity Time/space: O(1) — one template string.
 */
export function collectionEmbedSnippet(key: string): string {
  return embedMarkerSnippet({ type: "collection", key: "id", value: key });
}

/**
 * `useCollectionEntryEditor`'s `error` banner, extracted out of that hook (`refactor/fetch-query`
 * complexity pass, 2026-08-12 — the hook's own precedence chain over three independent mutations
 * pushed it to complexity 12 against a ceiling of 9). `update`/`create` share ONE fallback string,
 * matching the pre-migration `save()`'s single `translate(locale, "save failed")` for both branches;
 * `lifecycleFallback` is `null` whenever there is no `lastLifecycleOp` to describe the failure with
 * (nothing has been attempted yet), which this treats as "no lifecycle error to show" even if
 * `lifecycleError` is somehow set.
 *
 * A write that lost the compare-and-set (`409 VERSION_CONFLICT`, real since entry saves became
 * compare-and-set, wm S3) shows `versionConflictMessage` instead of the server's
 * "expected version N for entry '<id>'…" text, which named a UUID and no next step.
 *
 * @complexity Time/space: O(1) — three fixed checks, no iteration.
 */
export function visibleEntryEditorError(params: {
  updateError: Error | null;
  createError: Error | null;
  lifecycleError: Error | null;
  saveFallback: string;
  lifecycleFallback: string | null;
  /** Translated `VERSION_CONFLICT_MESSAGE` (`lib/version-conflict.ts`). */
  versionConflictMessage: string;
}): string | null {
  const describe = (error: Error, fallback: string) =>
    isVersionConflict(error) ? params.versionConflictMessage : describeApiError(error, fallback);
  if (params.updateError) return describe(params.updateError, params.saveFallback);
  if (params.createError) return describe(params.createError, params.saveFallback);
  if (params.lifecycleError && params.lifecycleFallback) {
    return describe(params.lifecycleError, params.lifecycleFallback);
  }
  return null;
}

const KEY_GRAMMAR = /^[a-z][a-z0-9_]{0,63}$/;
const RESERVED_KEYS = new Set(["post", "page"]);

type LocaleOrTranslate = string | Translate;

function localize(localeOrTranslate: LocaleOrTranslate, key: string): string {
  return typeof localeOrTranslate === "function" ? localeOrTranslate(key) : translate({ locale: localeOrTranslate, key: key });
}

/**
 * @complexity Time/space: O(1) — one regex test, one `Set` lookup.
 */
export function validateKey(key: string, locale = "en"): string | null {
  if (!KEY_GRAMMAR.test(key)) {
    return translate({ locale: locale, key: "Key must start with a lowercase letter and contain only lowercase letters, digits, and underscores (max 64 chars)." });
  }
  if (RESERVED_KEYS.has(key)) {
    return `"${key}" is a reserved key (built-in content already uses it).`;
  }
  return null;
}

/**
 * @complexity Time/space: O(1) — one regex test.
 */
export function validateFieldName(name: string, localeOrTranslate: LocaleOrTranslate = "en"): string | null {
  if (!KEY_GRAMMAR.test(name)) {
    return localize(localeOrTranslate, "Field name must start with a lowercase letter and contain only lowercase letters, digits, and underscores.");
  }
  return null;
}

// ---------------------------------------------------------------------------
// Draft field list — shared shape/helpers behind both New/Edit dialogs' field editors
// ---------------------------------------------------------------------------

export interface DraftField extends ContentTypeFieldDef {
  /** Local-only row key so React can key rows before they have a stable identity. */
  _rowId: number;
}

let nextRowId = 1;

export function emptyField(): DraftField {
  return { _rowId: nextRowId++, name: "", kind: "text", required: false, queryable: false };
}

/** Seeds `EditFieldsDialog`'s draft list from a saved content type's fields, assigning each a
 *  fresh local row id off the same shared counter {@link emptyField} uses. */
export function draftFieldsFromContentType(fields: ContentTypeFieldDef[]): DraftField[] {
  return fields.map((f) => ({ ...f, _rowId: nextRowId++ }));
}

/** @complexity Time/space: O(n) in `fields.length`. */
export function updateDraftField(fields: DraftField[], rowId: number, patch: Partial<DraftField>): DraftField[] {
  return fields.map((f) => (f._rowId === rowId ? { ...f, ...patch } : f));
}

/** @complexity Time/space: O(n) in `fields.length`. */
export function removeDraftField(fields: DraftField[], rowId: number): DraftField[] {
  return fields.filter((f) => f._rowId !== rowId);
}

/** @complexity Time/space: O(n) in `fields.length`. */
export function addDraftField(fields: DraftField[]): DraftField[] {
  return [...fields, emptyField()];
}

/** Drops the local-only `_rowId` before a draft list is sent as an `api.*` payload.
 *  @complexity Time/space: O(n) in `fields.length`. */
export function stripDraftFieldRowIds(fields: DraftField[]): ContentTypeFieldDef[] {
  return fields.map(({ _rowId: _unused, ...f }) => f);
}

/**
 * The first field-name validation failure in a draft list, formatted the way both dialogs' submit
 * handlers show it — or `null` if every field's name is valid.
 *
 * @complexity Time/space: O(n) in `fields.length`, short-circuiting on the first failure.
 */
export function firstDraftFieldError(fields: DraftField[], localeOrTranslate: LocaleOrTranslate = "en"): string | null {
  for (const f of fields) {
    const fieldError = validateFieldName(f.name.trim(), localeOrTranslate);
    if (fieldError) return `Field "${f.name || "(unnamed)"}": ${fieldError}`;
  }
  return null;
}

/**
 * Full validation pipeline for `NewContentTypeDialog`'s submit: key, then label, then every
 * field's name, in that order — the order the operator sees the errors matters (key/label are
 * checked before ever looking at the field rows).
 *
 * @complexity Time/space: O(n) in `fields.length`.
 */
export function validateNewContentTypeDraft(
  draft: { key: string; label: string; fields: DraftField[] },
  locale = "en",
): string | null {
  const keyError = validateKey(draft.key.trim(), locale);
  if (keyError) return keyError;
  if (!draft.label.trim()) return translate({ locale: locale, key: "Label is required." });
  return firstDraftFieldError(draft.fields, locale);
}

/**
 * Full validation pipeline for `EditFieldsDialog`'s submit: at least one field must remain (a
 * content type cannot be edited down to zero fields), then every remaining field's name.
 *
 * @complexity Time/space: O(n) in `fields.length`.
 */
export function validateEditFieldsDraft(fields: DraftField[], localeOrTranslate: LocaleOrTranslate = "en"): string | null {
  if (fields.length === 0) return localize(localeOrTranslate, "At least one field is required.");
  return firstDraftFieldError(fields, localeOrTranslate);
}

// ---------------------------------------------------------------------------
// Edit fields dialog (REQ-05) — error formatting
// ---------------------------------------------------------------------------

/** `409 VERSION_CONFLICT` copy — reuses the same "refresh and try again" shape SPEC-036's
 * comment-moderation 409 handling established for stale-`expectedVersion` writes, rather than
 * inventing a new wording for this screen. */
export const STALE_VERSION_MESSAGE = "This content type changed since you loaded it, refresh and try again.";

/**
 * Translates a failed `api.updateContentTypeFields` call to operator-facing copy: a `409`
 * (another edit landed since this dialog loaded its `expectedVersion`) gets the dedicated
 * "refresh and try again" message rather than the generic request-failed fallback.
 *
 * @complexity Time/space: O(1) — one `instanceof` check.
 */
export function describeEditFieldsError(e: unknown, localeOrTranslate: LocaleOrTranslate = "en"): string {
  if (e instanceof ApiError && e.status === 409) return STALE_VERSION_MESSAGE;
  return describeApiError(e, localize(localeOrTranslate, "Failed to update fields"));
}

// ---------------------------------------------------------------------------
// Lifecycle confirm dialog (Deprecate / Reactivate / Tombstone)
// ---------------------------------------------------------------------------

export type LifecycleConfirmOp = "deprecate" | "tombstone";

export const LIFECYCLE_COPY: Record<LifecycleConfirmOp, { title: string; body: string }> = {
  deprecate: {
    title: "Deprecate content type",
    body: "Existing entries stay readable; no new entries can be created.",
  },
  tombstone: {
    title: "Delete content type",
    body: "Entries stop being served publicly. This is not reversible from this screen.",
  },
};

export function lifecycleCopy(op: LifecycleConfirmOp, locale = "en"): { title: string; body: string } {
  const copy = LIFECYCLE_COPY[op];
  return { ...copy, title: translate({ locale: locale, key: copy.title }) };
}

/**
 * Tombstone is heavier/less-reversible than an ordinary reset, so — unlike
 * `ResetNamespaceDialog`'s "autoFocus the confirm button" default — focus starts on Cancel
 * (design-spec.md §1.8's deliberate deviation).
 *
 * @complexity Time/space: O(1).
 */
export function autoFocusCancelForLifecycleOp(op: LifecycleConfirmOp): boolean {
  return op === "tombstone";
}

// ---------------------------------------------------------------------------
// Collections — content-type list row menu
// ---------------------------------------------------------------------------

/** The callbacks a content-type row menu needs. Passed in rather than imported so this module
 *  stays free of state, mirroring `posts/rules.ts`'s `PostRowMenuHandlers`. */
export interface ContentTypeRowMenuHandlers {
  onEditFields: (contentType: AdminContentType) => void;
  onDeprecate: (contentType: AdminContentType) => void;
  onReactivate: (contentType: AdminContentType) => void;
  onTombstone: (contentType: AdminContentType) => void;
}

/**
 * At-rest row actions — every row-level trigger here was already a plain, unclassed button (the
 * warning-vs-danger distinction lives entirely in `LifecycleConfirmDialog`, left untouched below),
 * so this builder drops nothing. Tombstone is marked `destructive` here even though its row
 * trigger never carried `.btn-danger` — its own dialog copy already says "not reversible from this
 * screen", the exact case `RowMenuItem.destructive` exists for; Deprecate stays plain, since it is
 * reversible (Reactivate undoes it).
 *
 * The branch this makes testable: which of Deprecate/Reactivate/Tombstone appear is entirely
 * driven by `contentType.status`, and was previously reachable only by rendering the table and
 * opening a popover.
 *
 * @complexity Time/space: O(1) — at most three entries, no iteration.
 */
export function contentTypeMenuItems(
  contentType: AdminContentType,
  handlers: ContentTypeRowMenuHandlers,
  locale: string,
): RowMenuItem[] {
  const t = (key: string): string => translate({ locale: locale, key: key });
  const items: RowMenuItem[] = [
    { key: "edit-fields", label: t("Edit fields"), onSelect: () => handlers.onEditFields(contentType) },
  ];
  if (contentType.status === "active") {
    items.push({ key: "deprecate", label: t("Deprecate"), onSelect: () => handlers.onDeprecate(contentType) });
  }
  if (contentType.status === "deprecated") {
    items.push({ key: "reactivate", label: t("Reactivate"), onSelect: () => handlers.onReactivate(contentType) });
  }
  if (contentType.status !== "tombstone") {
    items.push({
      key: "tombstone",
      label: t("Delete"),
      destructive: true,
      onSelect: () => handlers.onTombstone(contentType),
    });
  }
  return items;
}

import type { ConsentFieldProblem } from '@jini-ai/admin/consent/react';
import { resolveActiveTabId } from '@jini-ai/ui/panel-kit';
import { ApiError } from '@/lib/api';
import type { ConsentDetectedItem } from './settings.hooks';

/** @file Pure decisions for the Cookie Consent page: tabs, problem routing, status copy, publish gate. */

export const CONSENT_TAB_IDS = ['overview', 'banner', 'look', 'rules'] as const;
export type ConsentTabId = typeof CONSENT_TAB_IDS[number];

/** An absent or unknown `?tab=` opens Overview, like every other tabbed admin screen. */
export function resolveConsentTabId({ tabId }: { tabId: string | null | undefined }, _optional = {}): ConsentTabId {
  return resolveActiveTabId({ tabId, validIds: CONSENT_TAB_IDS, defaultId: 'overview' });
}

/** A stale draft/published revision (HTTP 409): reload and review, never retry over it. */
export function isConsentConflict({ error }: { error: unknown }, _optional = {}): boolean {
  return error instanceof ApiError && error.status === 409;
}

const FIELD_TABS: Readonly<Record<string, ConsentTabId>> = {
  title: 'banner', message: 'banner', acceptLabel: 'banner', rejectLabel: 'banner', preferencesLabel: 'banner',
  privacyPolicyUrl: 'banner', secondaryLinkLabel: 'banner', secondaryLinkUrl: 'banner',
  placement: 'look', appearance: 'look', customCss: 'look', regionMode: 'rules', policyVersion: 'rules',
};

/** The tab whose field a problem names, so Overview can link straight to the fix; null when the
 * fix is not a setting on this page (storage, rendering). */
export function consentProblemTab({ problem }: { problem: ConsentFieldProblem }, _optional = {}): ConsentTabId | null {
  return problem.field === undefined ? null : FIELD_TABS[problem.field] ?? null;
}

const CATEGORY_ORDER = ['necessary', 'functional', 'analytics', 'marketing'];

/** What waits for a visitor's choice, counted per category in the engine's order, then any others.
 * @complexity O(n log k), n <= 200 detected items, k categories. */
export function pausedByCategory({ detected }: { detected: readonly ConsentDetectedItem[] }, _optional = {}): { category: string; count: number }[] {
  const counts = new Map<string, number>();
  for (const item of detected) counts.set(item.category, (counts.get(item.category) ?? 0) + 1);
  const rank = (category: string) => { const index = CATEGORY_ORDER.indexOf(category); return index === -1 ? CATEGORY_ORDER.length : index; };
  return [...counts].map(([category, count]) => ({ category, count })).sort((a, b) => rank(a.category) - rank(b.category) || a.category.localeCompare(b.category));
}

export type ConsentSaveState = 'idle' | 'saving' | 'saved' | 'error' | 'conflict';

/** The header's one-line status (an English key; the page translates it). */
export function consentStatusKey({ saveState, hasUnpublished, everPublished }: { saveState: ConsentSaveState; hasUnpublished: boolean; everPublished: boolean }, _optional = {}): string {
  if (saveState === 'conflict') return 'Someone else changed this. Reload to see it.';
  if (saveState === 'saving') return 'Saving…';
  if (saveState === 'error') return "Couldn't save. Your edits are still here.";
  if (hasUnpublished) return 'Draft saved. Not live yet.';
  return everPublished ? 'Live.' : 'Not published yet.';
}

/** Publish only a settled, problem-free draft that differs from what is live. The server re-checks. */
export function canPublishConsent(
  { saveState, settled, hasUnpublished, problems, publishing }: { saveState: ConsentSaveState; settled: boolean; hasUnpublished: boolean; problems: readonly ConsentFieldProblem[]; publishing: boolean },
  _optional = {},
): boolean {
  return settled && hasUnpublished && !publishing && problems.length === 0 && (saveState === 'saved' || saveState === 'idle');
}

/** "Reset to default" is offered only while the field differs from the site's default banner style
 * (which the server pre-fills into an empty field and delivers when the field is empty). */
export function canResetConsentCss({ customCss, defaultCss }: { customCss: string | undefined; defaultCss: string | undefined }, _optional = {}): boolean {
  return Boolean(defaultCss) && (customCss ?? '') !== defaultCss;
}

/** The page width the Desktop preview lays out at. The engine's banner switches to its phone layout
 * (a full-width sheet) at 480px and below, so a preview drawn at the pane's own ~400px width showed
 * that phone sheet under the "Desktop" label instead of the corner card visitors see. */
export const CONSENT_PREVIEW_DESKTOP_WIDTH = 1024;

/** How far the desktop-width page is scaled down to fit the preview pane; never enlarged.
 * An unmeasured (0) pane keeps 1. @complexity O(1). */
export function consentPreviewScale({ paneWidth }: { paneWidth: number }, _optional = {}): number {
  return paneWidth > 0 ? Math.min(1, paneWidth / CONSENT_PREVIEW_DESKTOP_WIDTH) : 1;
}

import type { ConsentFieldProblem, ConsentSettingsView } from '@jini-ai/admin/consent/react';
import { WORKSPACE_ID, authenticatedAdminRequest } from '@/lib/api';

/**
 * @file The Cookie Consent page's port onto the revisions API
 * (`apps/website/src/server/inbound/admin-http/routes/consent/routes.ts`, contract in
 * `apps/website/src/features/consent/README.md`). It replaces the legacy `core.consent` ledger
 * adapter: the page edits immutable draft revisions and publishes one atomically, so it reads the
 * published revision rather than ledger values.
 */

export interface ConsentRevision {
  id: string;
  config: ConsentSettingsView;
  actorId: string;
  createdAt: string;
}

/** What GET /settings says the editor may offer. Categories and GPC are fixed by the engine. */
export interface ConsentEditorLimits {
  /** Field defaults; `customCss` is the default banner style that "Reset to default" restores. */
  defaults?: { customCss?: string };
  placements: string[];
  textLimits: Partial<Record<'title' | 'message' | 'acceptLabel' | 'rejectLabel' | 'preferencesLabel' | 'secondaryLinkLabel', number>>;
  maxCssLength: number;
  regionModes: ConsentSettingsView['regionMode'][];
  /** Only supplied by the cookie-consent engine. */
  bannerModes?: NonNullable<ConsentSettingsView['bannerMode']>[];
  rules: { gpc: string; preferenceMaxAgeMs: number; staticReceipts: boolean };
}

export interface ConsentSettingsSnapshot {
  draft: ConsentRevision | null;
  published: ConsentRevision | null;
  /** The published revision, or the legacy ledger values before the first publication. */
  effective: ConsentSettingsView;
  editor: ConsentEditorLimits;
}

export interface ConsentDetectedItem {
  tag: string;
  category: string;
  source: string | null;
}

export interface ConsentReadiness {
  ready: boolean;
  enabled: boolean;
  blockingProblems: ConsentFieldProblem[];
  detected: ConsentDetectedItem[];
  truncated: boolean;
  limitations: string[];
}

export interface ConsentPreview {
  html: string;
  blockingProblems: ConsentFieldProblem[];
  /** Dropped CSS rules/tokens from the cookie-consent renderer; never publish blockers. */
  warnings?: ConsentFieldProblem[];
  revisionId: string | null;
}

export interface ConsentDraftSaved {
  revision: ConsentRevision;
  blockingProblems: ConsentFieldProblem[];
}

/** The adapter is only HTTP; it has no competing save/debounce state. Autosave ordering lives in
 * `consent-autosave.ts`, so this stays a 1:1 map of the six routes. */
export interface ConsentRevisionsPort {
  get(required?: Record<string, never>, optional?: Record<string, never>): Promise<ConsentSettingsSnapshot>;
  readiness(required?: { path?: string }, optional?: Record<string, never>): Promise<ConsentReadiness>;
  dryRun(required: { config: ConsentSettingsView; path?: string }, optional?: Record<string, never>): Promise<ConsentReadiness>;
  preview(required: { config: ConsentSettingsView; path?: string }, optional?: Record<string, never>): Promise<ConsentPreview>;
  saveDraft(required: { config: ConsentSettingsView; expectedDraftId: string | null }, optional?: Record<string, never>): Promise<ConsentDraftSaved>;
  publish(required: { draftId: string; expectedPublishedId: string | null }, optional?: Record<string, never>): Promise<{ published: true; revisionId: string }>;
}

/** `authenticatedAdminRequest`'s shape: resolves the JSON body, rejects with `ApiError` on non-2xx. */
export type ConsentRequest = <T>(required: { method: string; path: string; body?: unknown }) => Promise<T>;

/** Builds the port over any request function, so tests drive it with a fake per status code.
 * @complexity O(1) per call; one request each. */
export function createConsentRevisionsPort({ request }: { request: ConsentRequest }, { workspaceId = WORKSPACE_ID }: { workspaceId?: string } = {}): ConsentRevisionsPort {
  const base = `/workspaces/${encodeURIComponent(workspaceId)}/consent`;
  return {
    get: () => request({ method: 'GET', path: `${base}/settings` }),
    readiness: ({ path } = {}) => request({ method: 'GET', path: `${base}/readiness${path === undefined ? '' : `?path=${encodeURIComponent(path)}`}` }),
    dryRun: body => request({ method: 'POST', path: `${base}/dry-run`, body }),
    preview: body => request({ method: 'POST', path: `${base}/preview`, body }),
    saveDraft: body => request({ method: 'PUT', path: `${base}/settings`, body }),
    publish: body => request({ method: 'POST', path: `${base}/publish`, body }),
  };
}

export const defaultConsentRevisionsPort = createConsentRevisionsPort({ request: required => authenticatedAdminRequest(required) });

import { useCallback, useEffect, useRef, useState } from 'react';
import type { ConsentFieldProblem, ConsentSettingsView } from '@jini-ai/admin/consent/react';
import type { Translate } from '@jini-ai/ui/panel-kit';
import { describeApiError } from '@/lib/api';
import { createConsentAutosave, type ConsentAutosave, type ConsentTimers } from './consent-autosave';
import { canPublishConsent, consentPreviewScale, isConsentConflict, type ConsentSaveState } from './rules';
import type { ConsentEditorLimits, ConsentReadiness, ConsentRevisionsPort, ConsentSettingsSnapshot } from './settings.hooks';

/**
 * @file State for the Cookie Consent page. The page edits one draft revision (autosaved, see
 * `consent-autosave.ts`) and publishes it explicitly; the live site changes only on Publish. All
 * I/O goes through {@link ConsentRevisionsPort}; the page and its tabs are markup only.
 */

export interface ConsentPageController {
  loadError: string | null;
  editor: ConsentEditorLimits | null;
  /** `null` until the first load. Draft first, else the live (published or legacy) settings. */
  value: ConsentSettingsView | null;
  onChange(required: { patch: Partial<ConsentSettingsView> }, optional?: Record<string, never>): void;
  /** The saved draft's blocking problems; Publish stays off while there are any. */
  problems: ConsentFieldProblem[];
  saveState: ConsentSaveState;
  saveError: string | null;
  /** The newest saved draft revision, or null before the first save. */
  draftId: string | null;
  hasUnpublished: boolean;
  everPublished: boolean;
  /** Whether the banner is on for visitors right now. */
  liveEnabled: boolean;
  canPublish: boolean;
  publishing: boolean;
  publishError: string | null;
  /** Bumps after each publication so readiness can refresh. */
  publishedCount: number;
  publish(): Promise<void>;
  reload(): void;
}

interface Heads { draftId: string | null; publishedId: string | null }

/** Loads the revisions, autosaves edits as a draft and publishes it on request.
 * @complexity O(1) per edit; one request in flight at a time. */
export function useConsentPage({ port, t }: { port: ConsentRevisionsPort; t: Translate }, { delayMs, timers }: { delayMs?: number; timers?: ConsentTimers } = {}): ConsentPageController {
  const [loadNonce, setLoadNonce] = useState(0);
  const [snapshot, setSnapshot] = useState<ConsentSettingsSnapshot | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [value, setValue] = useState<ConsentSettingsView | null>(null);
  const [heads, setHeads] = useState<Heads>({ draftId: null, publishedId: null });
  const [problems, setProblems] = useState<ConsentFieldProblem[]>([]);
  const [saveState, setSaveState] = useState<ConsentSaveState>('idle');
  const [settled, setSettled] = useState(true);
  const [saveError, setSaveError] = useState<string | null>(null);
  const [publishing, setPublishing] = useState(false);
  const [publishError, setPublishError] = useState<string | null>(null);
  const [liveEnabled, setLiveEnabled] = useState(false);
  const [publishedCount, setPublishedCount] = useState(0);
  const valueRef = useRef<ConsentSettingsView | null>(null);
  const autosave = useRef<ConsentAutosave | null>(null);

  useEffect(() => {
    let alive = true;
    setLoadError(null);
    port.get().then(loaded => {
      if (!alive) return;
      const draftId = loaded.draft?.id ?? null;
      valueRef.current = loaded.draft?.config ?? loaded.effective;
      setSnapshot(loaded);
      setValue(valueRef.current);
      setHeads({ draftId, publishedId: loaded.published?.id ?? null });
      setLiveEnabled(loaded.effective.enabled);
      setProblems([]); setSaveState('idle'); setSettled(true); setSaveError(null); setPublishError(null);
      autosave.current = createConsentAutosave({ port, draftId, events: {
        onSaving: () => setSaveState('saving'),
        onSaved: ({ result, settled: done }) => {
          setHeads(current => ({ ...current, draftId: result.revision.id }));
          setProblems(result.blockingProblems);
          if (done) { setSaveState('saved'); setSettled(true); }
        },
        onConflict: () => setSaveState('conflict'),
        onError: ({ error }) => { setSaveState('error'); setSaveError(describeApiError(error, t("Couldn't save."))); },
      } }, { ...(delayMs === undefined ? {} : { delayMs }), ...(timers ? { timers } : {}) });
    }, error => { if (alive) setLoadError(describeApiError(error, t("Couldn't load cookie consent."))); });
    return () => { alive = false; autosave.current?.stop(); };
  }, [port, loadNonce]); // eslint-disable-line react-hooks/exhaustive-deps -- t/delay/timers are fixed per mount

  const hasUnpublished = heads.draftId !== null && heads.draftId !== heads.publishedId;

  function onChange({ patch }: { patch: Partial<ConsentSettingsView> }) {
    if (!valueRef.current || saveState === 'conflict') return;
    valueRef.current = { ...valueRef.current, ...patch };
    setValue(valueRef.current);
    setSettled(false);
    setPublishError(null);
    autosave.current!.change({ config: valueRef.current });
  }

  const canPublish = canPublishConsent({ saveState, settled, hasUnpublished, problems, publishing });

  async function publish() {
    if (!canPublish) return;
    // canPublish implies a saved, loaded draft: draftId, the value and autosave all exist.
    const draftId = heads.draftId!;
    setPublishing(true);
    setPublishError(null);
    try {
      await port.publish({ draftId, expectedPublishedId: heads.publishedId });
      setHeads({ draftId, publishedId: draftId });
      setLiveEnabled(valueRef.current!.enabled);
      setPublishedCount(count => count + 1);
    } catch (error) {
      if (isConsentConflict({ error })) { autosave.current!.stop(); setSaveState('conflict'); }
      else setPublishError(describeApiError(error, t("Couldn't publish.")));
    } finally {
      setPublishing(false);
    }
  }

  return {
    loadError, editor: snapshot?.editor ?? null, value, onChange, problems, saveState, saveError,
    draftId: heads.draftId, hasUnpublished, everPublished: heads.publishedId !== null, liveEnabled, canPublish, publishing, publishError, publishedCount,
    publish, reload: () => setLoadNonce(nonce => nonce + 1),
  };
}

export interface ConsentPreviewState {
  html: string | null;
  problems: ConsentFieldProblem[];
  warnings: ConsentFieldProblem[];
  error: string | null;
}

/** The real renderer's gated page for the current (unsaved) settings, debounced; a response that
 * arrives after a newer request was sent is dropped. CSS warnings travel with the preview, never
 * into the saved draft's publish blockers. @complexity O(1) requests per settle. */
export function useConsentPreview({ port, config, t }: { port: ConsentRevisionsPort; config: ConsentSettingsView | null; t: Translate }, { delayMs = 500 }: { delayMs?: number } = {}): ConsentPreviewState {
  const [state, setState] = useState<ConsentPreviewState>({ html: null, problems: [], warnings: [], error: null });
  const sequence = useRef(0);
  useEffect(() => {
    if (!config) return undefined;
    const ticket = ++sequence.current;
    const timer = setTimeout(() => {
      port.preview({ config }).then(
        result => { if (ticket === sequence.current) setState({ html: result.html, problems: result.blockingProblems, warnings: result.warnings ?? [], error: null }); },
        error => { if (ticket === sequence.current) setState(current => ({ ...current, error: describeApiError(error, t("Couldn't render the preview.")) })); },
      );
    }, delayMs);
    return () => clearTimeout(timer);
  }, [port, config, delayMs]); // eslint-disable-line react-hooks/exhaustive-deps -- t is fixed per mount
  return state;
}

/** Tracks the preview pane's width as the scale that fits a desktop-width page into it, so the
 * Desktop preview shows the banner's desktop layout. Without ResizeObserver (tests) it stays 1.
 * @complexity O(1) per resize. */
export function useConsentPreviewScale(_required: Record<string, never> = {}, _optional = {}): { ref: (node: HTMLElement | null) => void; scale: number } {
  const [scale, setScale] = useState(1);
  const observer = useRef<ResizeObserver | null>(null);
  const ref = useCallback((node: HTMLElement | null) => {
    observer.current?.disconnect();
    observer.current = null;
    if (!node || typeof ResizeObserver === 'undefined') return;
    observer.current = new ResizeObserver(entries => setScale(consentPreviewScale({ paneWidth: entries[0]?.contentRect.width ?? 0 })));
    observer.current.observe(node);
  }, []);
  return { ref, scale };
}

/** Readiness for Overview: the server checks the draft (else the live settings) as if it were on.
 * Reloads whenever `refresh` changes. */
export function useConsentReadiness({ port, refresh, t }: { port: ConsentRevisionsPort; refresh: string; t: Translate }, _optional = {}): { readiness: ConsentReadiness | null; error: string | null } {
  const [state, setState] = useState<{ readiness: ConsentReadiness | null; error: string | null }>({ readiness: null, error: null });
  useEffect(() => {
    let alive = true;
    port.readiness({}).then(
      readiness => { if (alive) setState({ readiness, error: null }); },
      error => { if (alive) setState({ readiness: null, error: describeApiError(error, t("Couldn't check readiness.")) }); },
    );
    return () => { alive = false; };
  }, [port, refresh]); // eslint-disable-line react-hooks/exhaustive-deps -- t is fixed per mount
  return state;
}

import { ApiError, describeApiError } from "@/lib/api";
import type { Translate } from "@jini-ai/ui/panel-kit";
import { interpolate } from "@jini-ai/ui/panel-kit";

/**
 * @file The Content analysis card's pure half — everything `ContentAnalysisCard.tsx` shows, decided
 * here so the component is only markup and the hook only fetches and holds state.
 *
 * The card is the admin surface of the `content-analyzer` built-in plugin (AW-7 Tier 2). That plugin
 * writes its analysis into the post's `ext["content-analyzer"]` bag on every save, and the generic
 * `POST /plugins/:pluginId/preview` route runs the same filter over an UNSAVED draft and returns the
 * plugin's patch without saving it. Both carry the full analysis as `report`, a JSON STRING —
 * `ExtPatch` values are scalars only, which is why it is not an object.
 *
 * The report types below MIRROR the plugin's `ContentAnalysisReport` (v1, fixed in
 * `ADS-memory/.local-artifacts/aw7-tier2/BRIEF.md`) rather than importing it: a browser bundle cannot
 * import `apps/website` internals — same decoupling every wire type in `lib/api.ts` follows. The
 * parse is defensive for the same reason: whatever arrives (absent, unparseable, a future `v`, a
 * malformed field) becomes an "analysis unavailable" state, never a crash in the post editor.
 */

export const CONTENT_ANALYZER_PLUGIN_ID = "content-analyzer";

const READABILITY_BANDS = ["very-easy", "easy", "fairly-easy", "standard", "fairly-difficult", "difficult", "very-difficult"] as const;
const CHECK_STATUSES = ["pass", "warn", "fail", "skip"] as const;

export type ReadabilityBand = (typeof READABILITY_BANDS)[number];
export type CheckStatus = (typeof CHECK_STATUSES)[number];

export interface ContentCheck {
  /** One of the plugin's seven ids today; kept as `string` so a newer plugin's extra check still
   *  renders (under its raw id) instead of failing the whole report. */
  id: string;
  status: CheckStatus;
  params: Record<string, number | string>;
}

export interface TocEntry {
  level: 1 | 2 | 3 | 4 | 5 | 6;
  text: string;
  anchor: string;
}

export interface ContentAnalysisReport {
  v: 1;
  score: number;
  wordCount: number;
  sentenceCount: number;
  readingTimeMinutes: number;
  readability: { fleschReadingEase: number; gradeLevel: number; band: ReadabilityBand };
  toc: TocEntry[];
  checks: ContentCheck[];
}

/** What the card has to show: a report (from the last save, or from an Analyze-now run over the
 *  unsaved draft), nothing yet, or something it could not read. */
export type AnalysisState =
  | { kind: "report"; source: "stored" | "fresh"; report: ContentAnalysisReport }
  | { kind: "missing" }
  | { kind: "invalid" };

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isFiniteNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

function isReadability(value: unknown): value is ContentAnalysisReport["readability"] {
  return (
    isRecord(value) &&
    isFiniteNumber(value.fleschReadingEase) &&
    isFiniteNumber(value.gradeLevel) &&
    (READABILITY_BANDS as readonly unknown[]).includes(value.band)
  );
}

function isTocEntry(value: unknown): value is TocEntry {
  return (
    isRecord(value) &&
    Number.isInteger(value.level) &&
    (value.level as number) >= 1 &&
    (value.level as number) <= 6 &&
    typeof value.text === "string" &&
    typeof value.anchor === "string"
  );
}

function isCheckParams(value: unknown): value is ContentCheck["params"] {
  return isRecord(value) && Object.values(value).every((param) => typeof param === "string" || isFiniteNumber(param));
}

function isCheck(value: unknown): value is ContentCheck {
  return (
    isRecord(value) &&
    typeof value.id === "string" &&
    (CHECK_STATUSES as readonly unknown[]).includes(value.status) &&
    isCheckParams(value.params)
  );
}

function hasReportMetrics(
  { value }: { value: Record<string, unknown> },
  _options: Record<string, never> = {},
): boolean {
  return (
    isFiniteNumber(value.score) &&
    isFiniteNumber(value.wordCount) &&
    isFiniteNumber(value.sentenceCount) &&
    isFiniteNumber(value.readingTimeMinutes)
  );
}

function isReport(value: unknown): value is ContentAnalysisReport {
  return (
    isRecord(value) &&
    value.v === 1 &&
    hasReportMetrics({ value }) &&
    isReadability(value.readability) &&
    Array.isArray(value.toc) &&
    value.toc.every(isTocEntry) &&
    Array.isArray(value.checks) &&
    value.checks.every(isCheck)
  );
}

/** The `report` field's JSON string as a v1 report, or `null` for anything else. */
export function parseContentAnalysisReport(raw: unknown): ContentAnalysisReport | null {
  if (typeof raw !== "string") return null;
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return null;
  }
  return isReport(parsed) ? parsed : null;
}

/** The analysis stored on the post by its last save. No `report` field at all is "not analyzed
 *  yet" (a post saved before the plugin was enabled), distinct from one that will not parse. */
export function storedAnalysis(ext: Record<string, Record<string, unknown>> | undefined): AnalysisState {
  const raw = ext?.[CONTENT_ANALYZER_PLUGIN_ID]?.report;
  if (raw === undefined) return { kind: "missing" };
  const report = parseContentAnalysisReport(raw);
  return report ? { kind: "report", source: "stored", report } : { kind: "invalid" };
}

/** The analysis an Analyze-now preview returned. The plugin ran, so a missing report is a broken
 *  reply ("unavailable"), not "not analyzed yet". */
export function previewAnalysis(fields: Record<string, unknown>): AnalysisState {
  const report = parseContentAnalysisReport(fields.report);
  return report ? { kind: "report", source: "fresh", report } : { kind: "invalid" };
}

/** An Analyze-now result, tagged with the post id and version it was run against. */
export interface FreshAnalysis {
  postId: string;
  version: number;
  state: AnalysisState;
}

/** Which analysis the card shows: an Analyze-now result while it still belongs to the post as
 *  loaded, else the stored one. A save bumps `version` and brings back the plugin's freshly stored
 *  `ext`, so the stored analysis wins again from that moment — including over a preview that was
 *  still in flight when the save landed (it is tagged with the older version). */
export function currentAnalysis(
  post: { id: string; version: number; ext?: Record<string, Record<string, unknown>> },
  fresh: FreshAnalysis | null,
): AnalysisState {
  if (fresh && fresh.postId === post.id && fresh.version === post.version) return fresh.state;
  return storedAnalysis(post.ext);
}

/** Whether the card hides, from the plugin's preview-status read — the card's only gate. Hidden
 *  while loading, when the plugin is off, and when it is not installed (`PLUGIN_NOT_FOUND`). Any
 *  other failed read (refused, offline) SHOWS the card so it can carry the error: hiding it would
 *  look exactly like "plugin disabled". @complexity O(1). */
export function isContentAnalysisHidden(status: { data: { enabled: boolean } | undefined; error: unknown }): boolean {
  if (status.data) return !status.data.enabled;
  if (!status.error) return true;
  return status.error instanceof ApiError && status.error.code === "PLUGIN_NOT_FOUND";
}

export interface PluginPreviewRequest {
  postId?: string;
  title: string;
  slug?: string;
  bodyJson: Record<string, unknown>;
  metaDescription?: string;
}

const EMPTY_DOC: Record<string, unknown> = { type: "doc", content: [] };

/** The preview route's body for the editor's current, unsaved title and body. `bodyJson` is `null`
 *  until TipTap mounts; the route requires an object, so an empty doc stands in. */
export function previewRequestBody(input: { postId: string; title: string; bodyJson: unknown }): PluginPreviewRequest {
  return { postId: input.postId, title: input.title, bodyJson: isRecord(input.bodyJson) ? input.bodyJson : EMPTY_DOC };
}

// ---- copy ---------------------------------------------------------------------------------------
// Every string below is an English dictionary key (`content-analysis-i18n.ts`), translated through
// the injected `t` and only then interpolated, so each locale owns its own word order.

const LEADS = {
  stored: "From the last save.",
  fresh: "From your current draft, including unsaved changes.",
  missing: "Not analyzed yet. Save, or click Analyze now.",
  invalid: "Analysis unavailable.",
} as const;

const BAND_LABELS: Record<ReadabilityBand, string> = {
  "very-easy": "Very easy",
  easy: "Easy",
  "fairly-easy": "Fairly easy",
  standard: "Standard",
  "fairly-difficult": "Fairly difficult",
  difficult: "Difficult",
  "very-difficult": "Very difficult",
};

/** Status is always shown as text plus an icon, never by colour alone; `tone` reuses the app's
 *  existing `.status-*` pill classes (`styles.css`). */
const STATUS_META: Record<CheckStatus, { label: string; tone: string; icon: string }> = {
  pass: { label: "Pass", tone: "status-ok", icon: "✓" },
  warn: { label: "Warning", tone: "status-warning", icon: "!" },
  fail: { label: "Fail", tone: "status-error", icon: "✕" },
  skip: { label: "Skipped", tone: "status-neutral", icon: "–" },
};

const CHECK_TITLES: Record<string, string> = {
  "title-length": "Title length",
  "meta-description-length": "Meta description",
  "image-alt": "Image alt text",
  "heading-order": "Heading order",
  "single-h1": "Single H1",
  "content-length": "Content length",
  subheadings: "Subheadings",
};

const TITLE_OUT_OF_RANGE = "Title is {length} characters; aim for {min}–{max}.";
const CONTENT_SHORT = "{words} words; aim for at least {min}.";

/** Per check id and status, the sentence that explains it. A combination with no entry (a newer
 *  plugin's check, or a status the plugin never gives that check) shows the status label only. */
const CHECK_MESSAGES: Record<string, Partial<Record<CheckStatus, string>>> = {
  "title-length": { pass: "Title length is good: {length} characters.", warn: TITLE_OUT_OF_RANGE, fail: TITLE_OUT_OF_RANGE },
  "meta-description-length": {
    pass: "Meta description length is good: {length} characters.",
    warn: "Meta description is {length} characters; aim for {min}–{max}.",
    skip: "No meta description is set.",
  },
  "image-alt": { pass: "All {images} images have alt text.", fail: "{missing} of {images} images are missing alt text." },
  "heading-order": { pass: "Headings follow a logical order.", warn: "Heading “{heading}” jumps from H{from} to H{to}." },
  "single-h1": {
    pass: "The body has no extra H1; the title is the page’s H1.",
    warn: "The body has {h1} H1 headings; the title is already the H1, so use H2 instead.",
  },
  "content-length": { pass: "{words} words — a solid length.", warn: CONTENT_SHORT, fail: "The content is empty." },
  subheadings: { pass: "Subheadings break up the content.", warn: "{words} words with no subheadings; add H2–H6 headings." },
};

const NO_IMAGES = "No images to check.";

const STATS_COPY = {
  score: "Score",
  outOf100: "out of 100",
  words: "Words",
  sentences: "Sentences: {count}",
  readingTime: "Reading time",
  minutes: "{minutes} min",
  estimated: "Estimated",
  readability: "Readability",
  bandGrade: "{band} · grade {grade}",
} as const;

const ERROR_COPY = {
  notEnabled: "The Content Analyzer plugin is not enabled.",
  notFound: "The Content Analyzer plugin is not installed.",
  hookFailed: "The analyzer could not process this content.",
  fallback: "Analysis failed.",
} as const;

/** Strings `ContentAnalysisCard.tsx` passes to `t` directly (the rest come from the tables above). */
export const CARD_COPY = ["Content analysis", "Analyze now", "Analyzing…", "Table of contents", "No headings yet.", "Checks"] as const;

/** Every English key this feature can look up — what the i18n suite holds each locale to. */
export function contentAnalysisCopyKeys(): string[] {
  const messages = Object.values(CHECK_MESSAGES).flatMap((byStatus) => Object.values(byStatus));
  return [
    ...new Set([
      ...Object.values(LEADS),
      ...Object.values(BAND_LABELS),
      ...Object.values(STATUS_META).map((meta) => meta.label),
      ...Object.values(CHECK_TITLES),
      ...messages,
      NO_IMAGES,
      ...Object.values(STATS_COPY),
      ...Object.values(ERROR_COPY),
      ...CARD_COPY,
    ]),
  ];
}

export interface AnalysisStat {
  key: string;
  label: string;
  value: string;
  meta: string;
}

export interface AnalysisTocItem {
  key: string;
  text: string;
  levelLabel: string;
  /** Indent relative to the shallowest heading in the list, so an H2-only post is not pushed in. */
  indentRem: number;
}

export interface AnalysisCheckItem {
  key: string;
  title: string;
  status: CheckStatus;
  statusLabel: string;
  tone: string;
  icon: string;
  message: string;
}

export interface ContentAnalysisView {
  lead: string;
  report: { stats: AnalysisStat[]; toc: AnalysisTocItem[]; checks: AnalysisCheckItem[] } | null;
}

function checkMessage(check: ContentCheck, t: Translate): string {
  const template = check.id === "image-alt" && check.status === "pass" && check.params.images === 0 ? NO_IMAGES : CHECK_MESSAGES[check.id]?.[check.status];
  return template ? interpolate({ template: t(template), vars: check.params }) : "";
}

function buildStats(report: ContentAnalysisReport, t: Translate): AnalysisStat[] {
  const { fleschReadingEase, gradeLevel, band } = report.readability;
  return [
    { key: "score", label: t(STATS_COPY.score), value: String(report.score), meta: t(STATS_COPY.outOf100) },
    { key: "words", label: t(STATS_COPY.words), value: String(report.wordCount), meta: interpolate({ template: t(STATS_COPY.sentences), vars: { count: report.sentenceCount } }) },
    {
      key: "reading-time",
      label: t(STATS_COPY.readingTime),
      value: interpolate({ template: t(STATS_COPY.minutes), vars: { minutes: report.readingTimeMinutes } }),
      meta: t(STATS_COPY.estimated),
    },
    {
      key: "readability",
      label: t(STATS_COPY.readability),
      value: String(fleschReadingEase),
      meta: interpolate({ template: t(STATS_COPY.bandGrade), vars: { band: t(BAND_LABELS[band]), grade: gradeLevel } }),
    },
  ];
}

function buildToc(toc: TocEntry[]): AnalysisTocItem[] {
  const shallowest = Math.min(...toc.map((entry) => entry.level));
  return toc.map((entry, index) => ({
    key: `${index}-${entry.anchor}`,
    text: entry.text,
    levelLabel: `H${entry.level}`,
    indentRem: entry.level - shallowest,
  }));
}

function buildChecks(checks: ContentCheck[], t: Translate): AnalysisCheckItem[] {
  return checks.map((check, index) => {
    const meta = STATUS_META[check.status];
    const title = CHECK_TITLES[check.id];
    return {
      key: `${index}-${check.id}`,
      title: title ? t(title) : check.id,
      status: check.status,
      statusLabel: t(meta.label),
      tone: meta.tone,
      icon: meta.icon,
      message: checkMessage(check, t),
    };
  });
}

/** Everything the card renders for one analysis state, already translated. */
export function buildContentAnalysisView(state: AnalysisState, t: Translate): ContentAnalysisView {
  if (state.kind !== "report") return { lead: t(LEADS[state.kind]), report: null };
  const { report } = state;
  return {
    lead: t(LEADS[state.source]),
    report: { stats: buildStats(report, t), toc: buildToc(report.toc), checks: buildChecks(report.checks, t) },
  };
}

/** Operator copy for a failed Analyze-now — the preview route's own refusal codes first, then the
 *  app's shared fallback chain. */
export function describeAnalysisError(error: unknown, t: Translate): string {
  if (error instanceof ApiError) {
    if (error.code === "PLUGIN_NOT_ENABLED") return t(ERROR_COPY.notEnabled);
    if (error.code === "PLUGIN_NOT_FOUND") return t(ERROR_COPY.notFound);
    if (error.code === "PLUGIN_HOOK_FAILED") return t(ERROR_COPY.hookFailed);
  }
  return describeApiError(error, t(ERROR_COPY.fallback));
}

import { useCallback, useState } from "react";
import { useFetchQuery, type QueryResult } from "@jini-ai/ui/fetch-query";

import { describeApiError, type AdminPost } from "@/lib/api";
import { activeThemeName, mergeRecent, shouldShowDefaultPasswordBanner, shouldShowSiteKeyBanner, siteKeyBannerCopy } from "../rules";
import { useWiredAdminLocale } from "@/hooks/use-admin-locale.hooks";
import { t as translate } from "../dashboard-i18n";
import type { Translate } from "@jini-ai/ui/panel-kit";
import { defaultDashboardPort } from "./dashboard-dependencies.hooks";
import type { DashboardPort } from "./dashboard-port.hooks";
import { useAdminBootScope } from "@/lib/admin-boot-scope";

/** Password-banner plan (2026-09-24), Slice 3 — per-browser dismiss for the default-password nag.
 *  Namespaced under `tovu.admin.` like `standing-draft-local-backup.ts`'s own keys, so it can never
 *  collide with an unrelated app key. The stored value is the principal id that dismissed it, so a
 *  different user signing in on the same browser still sees their own nag. */
const DEFAULT_PASSWORD_BANNER_DISMISSED_KEY = "tovu.admin.default-password-banner.dismissed";

/** Best-effort read — `localStorage` throws outright in some privacy modes (same caveat
 *  `standing-draft-local-backup.ts`'s header documents at length). A read that fails just shows the
 *  banner again, which is harmless: it is advisory and its truth is recomputed from the server on
 *  every load (see `rules.ts`'s `shouldShowDefaultPasswordBanner`).
 *  @complexity Time/space: O(1). */
function readDefaultPasswordBannerDismissedBy(): string | null {
  try {
    return localStorage.getItem(DEFAULT_PASSWORD_BANNER_DISMISSED_KEY);
  } catch {
    return null;
  }
}

/** Best-effort write — silent no-op on any storage failure, for the same reason the read above is.
 *  @complexity Time/space: O(1). */
function writeDefaultPasswordBannerDismissedBy(principalId: string): void {
  try {
    localStorage.setItem(DEFAULT_PASSWORD_BANNER_DISMISSED_KEY, principalId);
  } catch {
    // best-effort; see this file's header note on the Dismiss control.
  }
}

/**
 * @file Everything the Dashboard screen loads, so `Dashboard.tsx` is only markup.
 *
 * Extracted verbatim — same state, same order, same effect, same error strings.
 *
 * Error handling: every fetch owns its own error slot rather than sharing one, because these are
 * independent data sources and a failed comment count should not blank a post count that loaded
 * fine (audit finding, `ADS-memory/reports/audits/20260801-admin-adversarial-ux-audit.md`, exec
 * summary #5 — the original had no `.catch()` at all, so any rejection left the cards showing "…"
 * forever with no indication anything was wrong). A failed stat renders an em-dash plus the reason
 * in its own card, at the same size the healthy card occupies; see `.dash-stat-*.is-error`.
 *
 * @tradeoffs Five GETs on the landing screen instead of the previous two. Accepted because each is
 * a list this admin already serves elsewhere, they run concurrently, and none blocks render — the
 * screen paints its full layout immediately and each value fills in independently. The alternative
 * (a single aggregate `/dashboard` endpoint) would be one round trip but needs a new server route
 * and a new response contract to maintain; that is worth doing if this screen grows, and is not
 * worth it for five reads that already exist.
 *
 * Counts are `list().length`, not a server-side count, so they are bounded by whatever page size
 * those endpoints return. Correct for the scale this admin targets today; if any list grows past a
 * single page the count silently becomes "items on the first page" and would need a real count
 * endpoint. Flagged rather than pre-solved.
 *
 * `deps.port` is injected (see `dashboard-port.hooks.ts`) rather than reaching for `lib/api`'s
 * `api` directly, so a test can describe each of the five reads against `createFakeDashboardPort`
 * instead of stubbing global `fetch`. `useWiredDashboard` below is the zero-argument-dependencies
 * pair `Dashboard.tsx` actually mounts.
 *
 * `deps.t`/`deps.locale` (2026-08-11, standing i18n rule — a component with a hook gets a BOUND
 * `t` from that hook, not its own `useAdminLocale()`/dictionary import) are ALSO now injected
 * dependencies rather than values this hook resolved for itself: `Dashboard.tsx` needs a bound
 * translator, and `deps.locale` is what THIS hook's own error strings resolve against via the
 * `translate(locale, key)` two-arg import (aliased to avoid colliding with the injected one-arg
 * `t`) — same split `media-dependencies.hooks.ts` documents for its identical `translate`
 * alias/`t` pass-through pair. `useWiredDashboard` resolves both from the real `useWiredAdminLocale()`.
 *
 * 2026-08-14: this closes the port-conversion gap an earlier pass in this file's history left
 * disclosed ("NOT converted to the full port pattern... scoped as i18n-only... left as a disclosed
 * gap, not silently expanded") — the dispatch that added `deps.t` deliberately deferred the
 * 5-endpoint port because it was a materially larger diff than that pass's own scope; this pass's
 * scope is exactly "convert the admin DI seams still missing one," so the deferred half lands now.
 */

export interface StatState {
  value: number | null;
  error: string | null;
}

const PENDING: StatState = { value: null, error: null };

export interface DashboardController {
  posts: StatState;
  published: number | null;
  pages: StatState;
  drafts: number | null;
  media: StatState;
  comments: StatState;
  themeId: string | null;
  /** The active theme's `theme.json` display name, or its id when it has none — what the
   *  Appearance card shows. `null` until the presentation read settles. */
  themeName: string | null;
  themeError: string | null;
  /** `null` until at least one of `listPosts`/`listPages` settles — the caller renders a loading
   *  state for the "Recently updated" panel. */
  recent: AdminPost[] | null;
  /** Bound translator — `key` already resolved against the caller's locale, so `Dashboard.tsx`
   *  never imports `useAdminLocale`/`DASHBOARD_DICT` itself. See this file's header. */
  t: Translate;

  /** Password-banner plan (2026-09-24), Slice 3 — whether the default-password nag should render.
   *  `rules.ts`'s `shouldShowDefaultPasswordBanner`, applied to this hook's own fetched status and
   *  dismissed flag. */
  showDefaultPasswordBanner: boolean;
  /** Hides the banner for this browser and persists that choice (best-effort). */
  dismissDefaultPasswordBanner: () => void;

  /** Site-key plan (2026-09-24) §A.6 — whether the site-key warning banner should render.
   *  `rules.ts`'s `shouldShowSiteKeyBanner`, applied to this hook's own fetched state. */
  showSiteKeyBanner: boolean;
  /** The banner's own copy for the current state (`rules.ts`'s `siteKeyBannerCopy`) — `""` whenever
   *  {@link showSiteKeyBanner} is `false`. */
  siteKeyBannerMessage: string;
}

export interface DashboardDependencies {
  port: DashboardPort;
  /** Resolves this hook's OWN `describeApiError` fallback strings via the direct `translate`
   *  import above — see this file's header for why that's a separate concern from `t`. */
  locale: string;
  /** Bound translator, passed straight through to {@link DashboardController.t} — see this file's
   *  header for why it arrives as a dependency rather than this hook calling `useAdminLocale()`
   *  itself. */
  t: Translate;
}

/** Runs one stat read and, on rejection, rethrows it as this hook's own message: the rejection's
 *  own text when it has one, else `key` translated against `locale` (`describeApiError`).
 *  @complexity Time/space: O(1) beyond the read itself. */
async function readOrDescribe<T>({ read, locale, key }: { read: () => Promise<T>; locale: string; key: string }): Promise<T> {
  try { return await read(); }
  catch (error) { throw new Error(describeApiError(error, translate({ locale, key }))); }
}

/** The five stat reads, each owning its own query and error slot (see this file's header).
 *  @complexity Time/space: O(n) per settled list read for the `entry.post` unwrap. */
function useStatQueries({ port, locale }: { port: DashboardPort; locale: string }) {
  const postsQueryFetch = useCallback(() => readOrDescribe({
    read: async () => (await port.listPosts()).posts.map(entry => entry.post), locale, key: "failed to load posts",
  }), [port, locale]);
  // Posts and pages each feed a stat card and the merged activity list from one shared read.
  const postsQuery = useFetchQuery({ key: ["posts", "list"], fetch: postsQueryFetch }, { staleTime: 0 });
  const pagesQueryFetch = useCallback(() => readOrDescribe({
    read: async () => (await port.listPages()).posts.map(entry => entry.post), locale, key: "failed to load pages",
  }), [port, locale]);
  const pagesQuery = useFetchQuery({ key: ["pages", "list"], fetch: pagesQueryFetch }, { staleTime: 0 });
  const mediaQueryFetch = useCallback(() => readOrDescribe({ read: () => port.listMedia(), locale, key: "failed to load media" }), [port, locale]);
  const mediaQuery = useFetchQuery({ key: ["media"], fetch: mediaQueryFetch }, { staleTime: 0 });
  const commentsQueryFetch = useCallback(() => readOrDescribe({
    read: () => port.listCommentsQueue({ status: "pending" }), locale, key: "failed to load comments",
  }), [port, locale]);
  const commentsQuery = useFetchQuery({ key: ["dashboard", "pending-comments"], fetch: commentsQueryFetch }, { staleTime: 0 });
  const themeQueryFetch = useCallback(() => readOrDescribe({
    read: () => port.getPresentation(), locale, key: "failed to load the active theme",
  }), [port, locale]);
  const themeQuery = useFetchQuery({ key: ["themes", "presentation"], fetch: themeQueryFetch }, { staleTime: 0 });
  return { postsQuery, pagesQuery, mediaQuery, commentsQuery, themeQuery };
}

/** One stat card's state: `count(data)` once the read settles, `null` while pending or failed.
 *  @complexity Time/space: whatever `count` costs. */
function statState<T>({ query, count }: { query: QueryResult<T>; count: (data: T) => number }): StatState {
  return { value: query.data === undefined ? null : count(query.data), error: query.error?.message ?? null };
}

/** How many `rows` carry `status`, or `null` while the rows are still pending.
 *  @complexity Time: O(n); space: O(n) for the filtered copy. */
function countWithStatus({ rows, status }: { rows: ReadonlyArray<{ status: string }> | undefined; status: string }): number | null {
  return rows?.filter(row => row.status === status).length ?? null;
}

/** Posts and pages feed both counts and activity without another request — `null` until at least
 *  one of the two settles.
 *  @complexity Time: O(n log n) via `mergeRecent`. */
function recentActivity({ posts, pages }: { posts: AdminPost[] | undefined; pages: AdminPost[] | undefined }): AdminPost[] | null {
  return posts || pages ? mergeRecent(posts ?? null, pages ?? []) : null;
}

type DashboardStats = Pick<DashboardController,
  "posts" | "published" | "pages" | "drafts" | "media" | "comments" | "themeId" | "themeName" | "themeError" | "recent">;

/** Every stat field the controller carries, derived from the five settled-or-pending reads.
 *  @complexity Time: O(n log n) in the combined post/page row count (the `recent` merge). */
function deriveStats(queries: ReturnType<typeof useStatQueries>): DashboardStats {
  const { postsQuery, pagesQuery, mediaQuery, commentsQuery, themeQuery } = queries;
  return {
    posts: statState({ query: postsQuery, count: rows => rows.length }),
    published: countWithStatus({ rows: postsQuery.data, status: "published" }),
    pages: statState({ query: pagesQuery, count: rows => rows.length }),
    drafts: countWithStatus({ rows: pagesQuery.data, status: "draft" }),
    media: statState({ query: mediaQuery, count: data => data.media.filter(item => item.status === "active").length }),
    comments: statState({ query: commentsQuery, count: data => data.items.length }),
    themeId: themeQuery.data?.settings.activeThemeId ?? null,
    themeName: themeQuery.data ? activeThemeName(themeQuery.data) : null,
    themeError: themeQuery.error?.message ?? null,
    recent: recentActivity({ posts: postsQuery.data, pages: pagesQuery.data }),
  };
}

/** The default-password nag: its advisory status read plus the per-browser dismiss.
 *  @complexity Time/space: O(1) per render. */
function useDefaultPasswordBanner({ port }: { port: DashboardPort }): Pick<DashboardController, "showDefaultPasswordBanner" | "dismissDefaultPasswordBanner"> {
  // Failed advisory status reads mean no banner, not a stat error or evidence of a safe state.
  const { principalId, queryScope } = useAdminBootScope();
  const passwordQueryFetch = useCallback(() => port.getPasswordStatus({ principalId }), [port, principalId]);
  const passwordQuery = useFetchQuery({ key: ["identity", "password-status", queryScope], fetch: passwordQueryFetch });
  // null until the status fetch settles (or forever if it fails): the banner is advisory,
  // so shouldShowDefaultPasswordBanner treats unknown status as "don't show".
  const passwordStatus = passwordQuery.data ?? null;
  // Lazy initializer: read once, at mount, not on every render.
  const [dismissedBy, setDismissedBy] = useState<string | null>(readDefaultPasswordBannerDismissedBy);
  return {
    showDefaultPasswordBanner: shouldShowDefaultPasswordBanner(
      passwordStatus?.usesDefaultPassword ?? null,
      passwordStatus !== null && dismissedBy === passwordStatus.principalId,
    ),
    dismissDefaultPasswordBanner: () => {
      if (passwordStatus === null) return;
      writeDefaultPasswordBannerDismissedBy(passwordStatus.principalId);
      setDismissedBy(passwordStatus.principalId);
    },
  };
}

/** The site-key warning: its advisory status read plus the banner's copy.
 *  @complexity Time/space: O(1) per render. */
function useSiteKeyBanner({ port, t }: { port: DashboardPort; t: Translate }): Pick<DashboardController, "showSiteKeyBanner" | "siteKeyBannerMessage"> {
  // Site-key plan §A.6 — same advisory shape as the password status read:
  // a failed fetch means no banner, not an error card.
  const siteKeyQueryFetch = useCallback(() => port.getSiteKeyState(), [port]);
  const siteKeyQuery = useFetchQuery({ key: ["site-key", "state"], fetch: siteKeyQueryFetch }, { staleTime: 0 });
  // undefined until the site-key status fetch settles (or forever if it fails).
  // shouldShowSiteKeyBanner treats undefined as "don't show".
  const siteKeyState = siteKeyQuery.data?.state;
  return { showSiteKeyBanner: shouldShowSiteKeyBanner(siteKeyState), siteKeyBannerMessage: siteKeyBannerCopy(siteKeyState, t) };
}

/**
 * @param deps `port`/`locale`/`t` — see {@link DashboardDependencies}.
 * @returns The dashboard screen's full controller — see {@link DashboardController}.
 * @complexity Time/space: O(1) per call — five independent, concurrent round trips on mount.
 */
export function useDashboard({ port, locale, t }: DashboardDependencies): DashboardController {
  const stats = deriveStats(useStatQueries({ port, locale }));
  return { ...stats, t, ...useDefaultPasswordBanner({ port }), ...useSiteKeyBanner({ port, t }) };
}

/**
 * Binds the real `/api` client, the real `useWiredAdminLocale()`, and a `DASHBOARD_DICT`-bound
 * translator — see `dashboard-dependencies.hooks.ts`.
 *
 * The zero-argument-dependencies half of the `useX(dependencies)` / `useWiredX()` pair, so
 * `Dashboard.tsx` composes this and a test composes {@link useDashboard} with
 * `createFakeDashboardPort`.
 *
 * @returns The dashboard screen's full controller — see {@link DashboardController}.
 */
export function useWiredDashboard(): DashboardController {
  const locale = useWiredAdminLocale();
  const t = (key: string): string => translate({ locale: locale, key: key });
  return useDashboard({ port: defaultDashboardPort, locale, t });
}

import { useState } from "react";
import { describeApiError } from "@/lib/api";
import { useFetchMutation, useInvalidate } from "@jini-ai/ui/fetch-query";
import type { QueryKey } from "@jini-ai/core/fetch";
import { useWiredAdminLocale } from "@/hooks/use-admin-locale.hooks";
import { KEYS } from "../rules";
import { t } from "../database-i18n";
import { defaultMigrateForwardSectionPort } from "./migrate-forward-section-dependencies.hooks";
import type { MigrateForwardSectionPort } from "./migrate-forward-section-port.hooks";

/**
 * @file Everything `MigrateForwardSection` (the Database screen's plan/confirm/execute
 * migrate-forward ceremony) does, so `Database.tsx` is only markup.
 *
 * Extracted verbatim — same declaration order, same handlers, same error strings.
 *
 * `t`/`locale` (2026-08-11, standing i18n rule — see `use-timeline-section.hooks.ts`'s own file
 * header for the full rationale): this hook already called `useWiredAdminLocale()` for its own
 * error-string translations, so exposing that same already-resolved `locale` as a bound `t` (plus
 * the raw value, still needed for this section's own local step subcomponents and
 * `planReadyMessage`) on the return value adds no new fetch.
 *
 * `@jini-ai/ui/fetch-query` migration (2026-08-12): `startPlan`/`doConfirm`/`doExecute` are three
 * `useFetchMutation`s. `startPlan`/`doConfirm` declare no `invalidates` — they write nothing another
 * screen reads (`step`/`plan`/`confirmationToken`/`done` are pure client-side workflow state, not a
 * server resource another screen could invalidate into). `useFetchMutation` is still the right seam
 * here purely for its consistent pending/error tracking (`mutation.status`/`.error`), replacing the
 * hand-rolled `setBusy`/`setError` pairs each handler used to open and close by hand. `step`/`plan`/
 * `confirmationToken`/`done` stay local `useState` — they encode the ceremony's own sequence, which
 * no mutation object carries on its own. `error` is a simple precedence chain (not
 * `clearOtherWriteErrors`): the three mutations are mutually exclusive by construction
 * (`doConfirm`/`doExecute` both no-op without their predecessor's output), so at most one ever holds
 * a non-null `.error` at a time. `reset()` now also resets all three mutations, so a stale failure
 * from an earlier attempt at the current step doesn't survive a full ceremony reset.
 *
 * `doExecute` invalidates `KEYS.schemaState` and `KEYS.timelineAll` (2026-09-20 platform-review fix):
 * unlike `startPlan`/`doConfirm`, `execute` performs the ceremony's one real server write — it saves
 * a `restore_points` row and appends a `core.migration` `database_ledger` row
 * (`gated-hooks.ts`'s `executeMigrateForward`) — and those are exactly what the drift banner
 * (`use-schema-state-section.hooks.ts`) and the Timeline (`use-timeline-section.hooks.ts`) read.
 * Neither of those reads has any polling or `refetchOnWindowFocus`, and `SchemaStateWarningBanner`
 * stays mounted across the Migrate forward tab (`Database.tsx`), so without this the banner and
 * Timeline went stale until a manual page reload. `startPlan`/`doConfirm` still declare no
 * `invalidates` — plan and confirm write nothing the screen lists. A REJECTED execute also
 * re-invalidates both keys (via `useInvalidate()` in `doExecute`'s `catch`, not `FetchMutationOptions.
 * invalidates`, which only fires `onSuccess`): a rejection can be a lost response after the server
 * already committed (a timeout or a dropped connection after the write lands), and a re-read can only
 * make the screen more truthful. This is a deliberate, one-write-only departure from
 * `FetchMutationOptions.invalidates`'s "a rejected write changed nothing" assumption.
 *
 * DI seam (2026-08-14, Orc-BASH pass): `port` is now injected — see `migrate-forward-section-
 * port.hooks.ts` — rather than reaching `lib/api` directly, so a test can describe the
 * plan/confirm/execute ceremony against `createFakeMigrateForwardSectionPort` instead of stubbing
 * global `fetch`. `useWiredMigrateForwardSection` below is the zero-argument pair `Database.tsx`
 * actually mounts.
 */

export type CeremonyStep = "idle" | "planned" | "confirmed" | "done";

/** The reads a successful (or possibly-committed-but-rejected) `doExecute` changes — see this
 *  file's header. Shared between `executeMutation`'s `invalidates` and `doExecute`'s own rejected-path
 *  re-read so the two lists cannot drift apart. */
const MIGRATION_CHANGES_READS: readonly QueryKey[] = [KEYS.schemaState, KEYS.timelineAll];

export interface MigrateForwardSectionController {
  step: CeremonyStep;
  busy: boolean;
  error: string | null;
  plan: { planId: string; planHash: string } | null;
  confirmationToken: string | null;
  done: boolean;
  reset: () => void;
  startPlan: () => Promise<void>;
  doConfirm: () => Promise<void>;
  doExecute: () => Promise<void>;
  /** Bound translator — `key` already resolved against the caller's locale, so `Database.tsx`
   *  never imports `useAdminLocale`/`database-i18n` for this section. See this file's header. */
  t: (key: string) => string;
  /** Raw resolved locale — this section's own local step subcomponents (`PlanMigrationStep`,
   *  `PlannedStep`, …) and `planReadyMessage` take `locale` directly rather than a bound
   *  translator. See this file's header. */
  locale: string;
}

export interface MigrateForwardSectionDependencies {
  port: MigrateForwardSectionPort;
}

/**
 * @param deps Injected dependencies — the `MigrateForwardSectionPort` to run the ceremony through.
 * @returns The ceremony's step/plan/token/done state plus `startPlan`/`doConfirm`/`doExecute`/
 * `reset`, and a bound `t`/`locale` — see this file's header for the full rationale.
 */
export function useMigrateForwardSection(deps: MigrateForwardSectionDependencies): MigrateForwardSectionController {
  const { port } = deps;
  const locale = useWiredAdminLocale();
  const boundT = (key: string): string => t({ locale: locale, key: key });
  const invalidate = useInvalidate();
  const [step, setStep] = useState<CeremonyStep>("idle");
  const [plan, setPlan] = useState<{ planId: string; planHash: string } | null>(null);
  const [confirmationToken, setConfirmationToken] = useState<string | null>(null);
  const [done, setDone] = useState(false);

  const startPlanMutation = useFetchMutation({ run: ({ input: _ }: { input: undefined }) => port.planMigrateForward() });
  const confirmMutation = useFetchMutation({
    run: ({ input }: { input: { planId: string; planHash: string } }) => port.confirmMigrateForward(input),
  });
  const executeMutation = useFetchMutation({
    run: ({ input: confirmationTokenInput }: { input: string }) => port.executeMigrateForward(confirmationTokenInput),
  }, {
    invalidates: MIGRATION_CHANGES_READS,
  });

  function reset() {
    setStep("idle");
    setPlan(null);
    setConfirmationToken(null);
    setDone(false);
    startPlanMutation.reset();
    confirmMutation.reset();
    executeMutation.reset();
  }

  async function startPlan() {
    try {
      const r = await startPlanMutation.mutate({ input: undefined });
      setPlan({ planId: r.planId, planHash: r.planHash });
      setStep("planned");
    } catch {
      // already surfaced through startPlanMutation.error -> error below
    }
  }

  async function doConfirm() {
    if (!plan) return;
    try {
      const r = await confirmMutation.mutate({ input: { planId: plan.planId, planHash: plan.planHash } });
      setConfirmationToken(r.confirmationToken);
      setStep("confirmed");
    } catch {
      // already surfaced through confirmMutation.error -> error below
    }
  }

  async function doExecute() {
    if (!confirmationToken) return;
    try {
      await executeMutation.mutate({ input: confirmationToken });
      setDone(true);
      setStep("done");
    } catch {
      // already surfaced through executeMutation.error -> error below.
      // Re-read the schema state and Timeline anyway: a rejection here can be a lost response after
      // the server already committed the write (a timeout or a dropped connection), so a stale
      // "in-sync"/old-Timeline read is a worse failure mode than one extra fetch. See this file's
      // header.
      for (const key of MIGRATION_CHANGES_READS) invalidate({ key: key });
    }
  }

  const busy = startPlanMutation.status === "pending" || confirmMutation.status === "pending" || executeMutation.status === "pending";
  // Mutually exclusive by construction (`doConfirm`/`doExecute` both no-op without their
  // predecessor's output — see this file's own header), so at most one of these three is ever
  // non-null at a time; a plain precedence chain is enough, no `clearOtherWriteErrors` needed.
  const rawError = startPlanMutation.error ?? confirmMutation.error ?? executeMutation.error;
  let error: string | null = null;
  if (startPlanMutation.error) {
    error = describeApiError(rawError, t({ locale: locale, key: "Failed to plan the forward migration" }));
  } else if (confirmMutation.error) {
    error = describeApiError(rawError, t({ locale: locale, key: "Failed to confirm the forward migration" }));
  } else if (executeMutation.error) {
    error = describeApiError(rawError, t({ locale: locale, key: "Failed to execute the forward migration" }));
  }

  return { step, busy, error, plan, confirmationToken, done, reset, startPlan, doConfirm, doExecute, t: boundT, locale };
}

/**
 * Binds the real `/api/.../database/migrate-forward` client — see `migrate-forward-section-
 * dependencies.hooks.ts`. The zero-argument half of the `useX(dependencies)` / `useWiredX()` pair,
 * so `Database.tsx` composes this and a test composes {@link useMigrateForwardSection} with
 * `createFakeMigrateForwardSectionPort`.
 *
 * @returns Same controller shape as {@link useMigrateForwardSection}, bound to the real port.
 */
export function useWiredMigrateForwardSection(): MigrateForwardSectionController {
  return useMigrateForwardSection({ port: defaultMigrateForwardSectionPort });
}

import type { ReactNode } from "react";
import { agentHandle } from "@jini-ai/agentic";
import type { AdminDeploymentEnvVarStatus, AdminDeploymentOverview } from "../../lib/api";
import type { Translate } from "@jini-ai/ui/panel-kit";
import {
  daemonStatusLabelKey,
  deploymentEnvVarNoteKey,
  envVarStatusLabelKey,
  isEnvVarRowUnsafe,
  ownerPasswordLabelKey,
  productionGateLabelKey,
  runtimeModeLabelKey,
  FULL_SITE_CAPABILITIES,
  STATIC_SITE_CAPABILITIES,
  type DeploymentCapability,
} from "./rules";
import { CapabilityList, FullSiteIcon, StaticSiteIcon } from "./deployment-visuals";
import { useWiredDeploymentOverview } from "./hooks/use-deployment-overview.hooks";

/**
 * @file Overview tab — the screen's actual "which path" moment, above how THIS instance happens to
 * be running right now. Every diagnostic value here is either `AdminDeploymentOverview` (read live
 * from `GET .../system/deployment-overview`, see `src/server/routes/admin/system/deployment-
 * overview.ts`) or a translated label derived from it by `rules.ts`'s pure helpers — nothing on
 * this tab is invented.
 *
 * ## Second pass (2026-08-15) — what changed and why
 *
 * The first pass put the two paths side by side, which was the right call and stays. What it did
 * not do was make them COMPARABLE: two cards, one sentence each, in prose. A reader still had to
 * hold "no checkout, no admin online, no assistant" in their head and diff it against "admin,
 * assistant, checkout, everything works" to see what they were choosing between. {@link
 * CapabilityList} turns that into four aligned rows with a ✓/✗ per path, so the difference is a
 * shape rather than a reading-comprehension exercise. No new claim is made — `rules.ts`'s
 * `STATIC_SITE_CAPABILITIES` is that same warning sentence, itemized, and its own doc comment
 * records the source for each row.
 *
 * Headings are `.card-title`, not bare `<h2>`. That primitive exists in `styles.css` (~L744) for
 * exactly this, and its own comment measured the defect this tab shipped: a bare `<h2>` in a
 * `.card` renders at the UA default 24px against a 26.4px `.page-title` — "not a hierarchy step,
 * it is a near-tie" — plus a stray 19.92px UA margin. Six such headings across five tabs is most of
 * why the panel read as a stack of equally loud boxes.
 *
 * The diagnostics no longer use `.field`/`.field-row`. `.field` is `display: flex; flex-direction:
 * column`, so a `.status` pill placed directly inside one stretches to the full column width — the
 * "Local" pill measured ~400px wide at a 1440px viewport, which is what made this section look
 * unfinished. `.deployment-fact` is the same label-over-value shape with the pill hugging its text.
 *
 * Links to the sibling tabs stay plain `<a href="/admin/deployment?tab=...">` — the established
 * internal-link idiom (`installInternalLinkInterceptor`, `@jini-ai/admin/browser`), so cmd-click,
 * middle-click and copy-link all keep working.
 */
export interface OverviewTabProps {
  /** DI seam for tests — same convention as every other wired-hook prop in this app. */
  useDeploymentOverviewHook?: typeof useWiredDeploymentOverview;
}

/** One path-choice card: identifying icon, name, an honest one-word availability pill, the promise,
 *  the capability comparison, and a footer holding the caveat above the link to that path's own tab.
 *  The footer is pushed to the card's bottom edge by CSS so both cards' links land on the same
 *  baseline even when one capability list runs longer. */
function OverviewPathCard({
  icon,
  heading,
  statusLabel,
  getLine,
  capabilities,
  costLine,
  detailsHref,
  detailsLabel,
  cardHandleId,
  detailsHandleId,
  t,
}: {
  icon: ReactNode;
  heading: string;
  statusLabel: string;
  getLine: string;
  capabilities: readonly DeploymentCapability[];
  costLine: string;
  detailsHref: string;
  detailsLabel: string;
  /** Distinguishes the Static Site vs. Full Site card — see the two `OverviewPathChoice` call
   *  sites, the only two instances this shared component ever renders. */
  cardHandleId: string;
  detailsHandleId: string;
  t: Translate;
}) {
  return (
    <div
      className="card deployment-path-card"
      {...agentHandle({ handle: cardHandleId }, {
        role: "region",
        label: `${heading} path card — availability, what it gives you, capability comparison, and a link to its own tab`,
      })}
    >
      <div className="deployment-path-head">
        <span className="deployment-path-icon">{icon}</span>
        <h2 className="card-title">{heading}</h2>
        <span className="status status-neutral">{statusLabel}</span>
      </div>
      <p className="card-lead">{getLine}</p>
      <CapabilityList rows={capabilities} t={t} />
      <div className="deployment-path-foot">
        <p className="deployment-action-reason">{costLine}</p>
        <a
          className="btn-secondary"
          href={detailsHref}
          {...agentHandle({ handle: detailsHandleId }, { role: "link", label: `Open details for ${heading}` })}
        >
          {detailsLabel}
        </a>
      </div>
    </div>
  );
}

/** The two-path comparison — see this file's header for why it leads the tab.
 *
 *  Both availability pills are `status-neutral`, deliberately. "Available here" is not a success
 *  state and "Not wired up yet" is not a failure, so neither earns `status-ok`/`status-warning`;
 *  the words carry the difference, which is also what keeps the distinction legible without color
 *  perception. "Available here" (was "Available from a terminal") because the Static Site tab's
 *  Build static export button runs the export from this admin; the terminal is no longer the only way. */
function OverviewPathChoice({ t }: { t: Translate }) {
  // Full Site tab retired; Dockerfile remains the live server packaging surface.
  return (
    <div className="deployment-path-grid">
      <OverviewPathCard
        icon={<StaticSiteIcon />}
        heading={t("Static Site")}
        statusLabel={t("Available here")}
        getLine={t("A fast, read-only copy of this site's published pages — no server behind it.")}
        capabilities={STATIC_SITE_CAPABILITIES}
        costLine={t("Runs on any static host, including free ones. Nothing dynamic survives the export.")}
        detailsHref="/admin/deployment?tab=static-site"
        detailsLabel={t("View Static Site details")}
        cardHandleId="deployment-overview-static-path-card"
        detailsHandleId="deployment-overview-static-details-link"
        t={t}
      />
      <OverviewPathCard
        icon={<FullSiteIcon />}
        heading={t("Full Site")}
        statusLabel={t("Not wired up yet")}
        getLine={t("The complete Tovu server — admin, assistant, checkout, everything works.")}
        capabilities={FULL_SITE_CAPABILITIES}
        costLine={t("Needs a host to run on — provider setup is planned, not wired up yet.")}
        detailsHref="/admin/deployment?tab=dockerfile"
        detailsLabel={t("View the Dockerfile")}
        cardHandleId="deployment-overview-full-path-card"
        detailsHandleId="deployment-overview-full-details-link"
        t={t}
      />
    </div>
  );
}

/** One label-over-value diagnostic cell. `children` rather than a `value` string so the same cell
 *  shape holds either a status pill or a verbatim `<code>` path — two different renderings of the
 *  same "here is one fact about this instance" row, which is why they share a component instead of
 *  each having their own. */
function OverviewFact({ label, children }: { label: string; children: ReactNode }) {
  return (
    <div className="deployment-fact">
      <span className="deployment-fact-label">{label}</span>
      <span className="deployment-fact-value">{children}</span>
    </div>
  );
}

/** A filesystem path, shown verbatim. `translate="no"` so a machine translator leaves it alone — a
 *  path is an identifier, not prose (Web Interface Guidelines: "brand names, code tokens,
 *  identifiers: wrap with `translate=\"no\"`"). Wrapping is `overflow-wrap: anywhere` in CSS
 *  because an absolute path has no spaces to break at, and at 390px an unbreakable one is what
 *  pushes the whole page into horizontal scroll. */
function OverviewPathValue({ path }: { path: string }) {
  return <code translate="no">{path}</code>;
}

/** One environment-variable row: name, Set/Not set pill, and the one-line note explaining what
 *  happens when it's absent (`deploymentEnvVarNoteKey`, `rules.ts`). */
function OverviewEnvVarRow({ varStatus, t }: { varStatus: AdminDeploymentEnvVarStatus; t: Translate }) {
  const unsafe = isEnvVarRowUnsafe(varStatus);
  const tone: "ok" | "warning" | "neutral" = unsafe ? "warning" : varStatus.set ? "ok" : "neutral";
  return (
    <li className="deployment-env-row">
      <div className="deployment-env-head">
        <span className="deployment-env-name" translate="no">
          {varStatus.name}
        </span>
        <span className={`status status-${tone}`}>{t(envVarStatusLabelKey(varStatus))}</span>
      </div>
      <p className="deployment-env-note">{t(deploymentEnvVarNoteKey(varStatus.name))}</p>
    </li>
  );
}

/** The loaded snapshot's body — split from `OverviewTab` so the loading/error early returns there
 *  stay flat guard clauses, same shape `Database.tsx`'s section components use. */
function OverviewSnapshotBody({ snapshot, t }: { snapshot: AdminDeploymentOverview; t: Translate }) {
  return (
    <>
      <div
        className="card"
        {...agentHandle({ handle: "deployment-overview-instance-facts" }, {
          role: "region",
          label: "How this instance is running — runtime mode, readiness gate, owner password, agent daemon, and file paths",
        })}
      >
        <div className="card-head">
          <h2 className="card-title">{t("How this instance is running")}</h2>
        </div>
        <div className="deployment-facts">
          <OverviewFact label={t("Runtime mode")}>
            <span className="status status-neutral">{t(runtimeModeLabelKey(snapshot.mode))}</span>
          </OverviewFact>
          <OverviewFact label={t("Production readiness gate")}>
            <span className={`status status-${snapshot.productionReadinessGate.applicable ? "ok" : "neutral"}`}>
              {t(productionGateLabelKey(snapshot.productionReadinessGate))}
            </span>
          </OverviewFact>
          <OverviewFact label={t("Owner password")}>
            <span className={`status status-${snapshot.defaultOwnerPasswordUnsafe ? "warning" : "ok"}`}>
              {t(ownerPasswordLabelKey(snapshot.defaultOwnerPasswordUnsafe))}
            </span>
          </OverviewFact>
          <OverviewFact label={t("Agent daemon")}>
            <span className={`status status-${snapshot.daemonKnownFailed ? "warning" : "ok"}`}>
              {t(daemonStatusLabelKey(snapshot.daemonKnownFailed))}
            </span>
          </OverviewFact>
          <OverviewFact label={t("Database file")}>
            <OverviewPathValue path={snapshot.dbPath} />
          </OverviewFact>
          <OverviewFact label={t("Uploads folder")}>
            <OverviewPathValue path={snapshot.uploadsDir} />
          </OverviewFact>
        </div>
      </div>

      <div
        className="card"
        {...agentHandle({ handle: "deployment-overview-env-vars" }, {
          role: "region",
          label: "Environment variables this instance reads, with each one's Set/Not set state and what happens when it's absent",
        })}
      >
        <div className="card-head">
          <h2 className="card-title">{t("Environment variables")}</h2>
        </div>
        <ul className="deployment-env-list">
          {snapshot.envVars.map((varStatus) => (
            <OverviewEnvVarRow key={varStatus.name} varStatus={varStatus} t={t} />
          ))}
        </ul>
      </div>
    </>
  );
}

/** Resolves {@link OverviewTabProps.useDeploymentOverviewHook} to the real hook when a caller
 *  passes none — a call out to a separately-scoped resolver, rather than a destructuring default
 *  plus a `= {}` parameter default on `OverviewTab` itself, keeps this function's own ESLint
 *  cyclomatic-complexity count from counting a second branch for the empty-props case (same
 *  reasoning `SettingsUi.tsx`'s `resolveSettingsUiHook` documents for its own props). */
function resolveDeploymentOverviewHook(
  override: typeof useWiredDeploymentOverview | undefined
): typeof useWiredDeploymentOverview {
  return override ?? useWiredDeploymentOverview;
}

/** The current-instance diagnostics half of the tab — same guard-clause shape this function always
 *  had, just pulled out of `OverviewTab` so `OverviewPathChoice` above it can render unconditionally
 *  (this dispatcher's own early returns would otherwise skip it during loading/error too). */
function OverviewDiagnostics({
  snapshot,
  error,
  t,
}: {
  snapshot: AdminDeploymentOverview | undefined;
  error: string | null;
  t: Translate;
}) {
  if (error && !snapshot) return <div className="notice error">{error}</div>;
  if (!snapshot) return <div className="notice">{t("Loading deployment status…")}</div>;

  return (
    <>
      {error ? <div className="notice error">{error}</div> : null}
      <OverviewSnapshotBody snapshot={snapshot} t={t} />
    </>
  );
}

export function OverviewTab(props: OverviewTabProps) {
  const useDeploymentOverviewHook = resolveDeploymentOverviewHook(props.useDeploymentOverviewHook);
  const { snapshot, error, t } = useDeploymentOverviewHook();

  return (
    <div className="deployment-tab">
      <OverviewPathChoice t={t} />
      <OverviewDiagnostics snapshot={snapshot} error={error} t={t} />
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";

import {
  describeApiError,
  type AdminPublishRunSnapshot,
  type AdminPublishTargetDescriptor,
  type AdminStaticPublishConfig,
  type AdminStaticPublishPreview,
  type AdminStaticPublishTargetId,
} from "@/lib/api";
import { localizePublishTargets } from "@/lib/descriptor-i18n";
import { useFetchQuery } from "@jini-ai/ui/fetch-query";
import { useAdminLocale } from "@/hooks/use-admin-locale.hooks";
import {
  t as defaultT,
  publishLoadErrorMessage,
  publishPollErrorMessage,
  publishPreviewErrorMessage,
  publishTriggerErrorMessage,
} from "../deployment-i18n";
import type { Translate } from "@jini-ai/ui/panel-kit";
import {
  buildStaticPublishConfig,
  publishTargetById,
  staticPublishFormReadyForPreview,
  staticPublishFormReadyToPublish,
  staticPublishProjectNameCopy,
  staticPublishProjectNameToSend,
  type StaticPublishProjectNameCopy,
} from "../rules";
import { defaultStaticPublishPort } from "./static-publish-dependencies.hooks";
import type { StaticPublishPort } from "./static-publish-port.hooks";

/**
 * @file Everything the Static Site tab's "Getting it online" provider form does — target selection,
 * the host's config fields and projectName, the preview action, and the publish
 * trigger+poll — so `StaticSiteTab.tsx` is only markup. Wired 2026-08-15 against
 * `src/server/routes/admin/system/publish-site.ts`'s three routes (preview, trigger, status).
 *
 * ## One form, fields from the host's descriptor
 *
 * The hosts, and each host's config fields, come from `GET .../system/publish-targets` (the deploy
 * plugin's descriptors) — this hook names no host. Config values are kept per target id, so
 * switching hosts never discards another host's half-filled fields, and `buildStaticPublishConfig`
 * (`rules.ts`) sends only the fields the selected host declares.
 *
 * ## `basePath` is never a field here
 *
 * There is no `setBasePath` anywhere in this file, on purpose — `AdminStaticPublishConfig` (the
 * wire type) has no such field either. The base path is always what `preview.basePath`/
 * `run.result.basePath` REPORT the server already computed, never something this form could send
 * back. See `static-publish/adapter.ts`'s `computeBasePath` for why that is structural, not a
 * missing feature.
 *
 * ## `preview` is invalidated by every field edit
 *
 * A stale preview computed against a DIFFERENT owner/repo would show the wrong base path next to a
 * form the operator has since changed — worse than showing nothing, since it looks current. Every
 * setter below clears `preview`/`previewError` as a side effect, so the "Preview" affordance always
 * either reflects the fields currently on screen or is honestly empty.
 */
export interface StaticPublishController {
  /** The deploy registry's targets, in its order — `undefined` until the first load resolves. */
  targets: readonly AdminPublishTargetDescriptor[] | undefined;
  /** Translated error from loading {@link targets}, `null` otherwise. */
  targetsError: string | null;
  /** The selected target's id — the operator's pick, else the first listed target; `""` while the
   *  list loads. */
  target: AdminStaticPublishTargetId;
  /** {@link target}'s descriptor, `undefined` while the list loads. */
  selectedTarget: AdminPublishTargetDescriptor | undefined;
  setTarget: (target: AdminStaticPublishTargetId) => void;
  /** The selected target's config values, keyed by descriptor field name. */
  configValues: Readonly<Record<string, string>>;
  setConfigField: (name: string, value: string) => void;
  /** Whether Preview / Publish may be asked for with the current values (`rules.ts`). */
  canPreview: boolean;
  canPublish: boolean;
  /** The selected host's label and help for {@link projectName}; `null` when the host takes no
   *  project name, so the tab shows no such field. */
  projectNameCopy: StaticPublishProjectNameCopy | null;
  projectName: string;
  setProjectName: (value: string) => void;

  /** The most recent preview result — `undefined` until {@link checkPreview} has resolved at least
   *  once since the fields were last edited (see this file's header). */
  preview: AdminStaticPublishPreview | undefined;
  previewLoading: boolean;
  previewError: string | null;
  /** Runs a preview against the CURRENT field values for the CURRENT target. Resolves either way — a
   *  failure is surfaced through {@link previewError}. */
  checkPreview: () => Promise<void>;

  /** The current/most recent publish run — `undefined` until the first status read resolves. */
  run: AdminPublishRunSnapshot | undefined;
  /** True whenever `run.status === "running"` AND polling can still reach the status endpoint — see
   *  {@link pollError}'s own doc for why the second half matters (same shape
   *  `StaticExportController.isRunning` documents). */
  isPublishing: boolean;
  /** Already-formatted, translated error from the INITIAL status read — `null` while loading or once
   *  loaded successfully. Distinct from {@link publishError}: same split
   *  `StaticExportController.loadError`/`triggerError` draws. */
  loadError: string | null;
  /** Already-formatted, translated error from the poll loop giving up after a bounded number of
   *  consecutive failures — `null` while healthy, reset at the start of every new {@link publish}.
   *  Same shape and same reason `StaticExportController.pollError` exists: an unbounded retry here
   *  would strand the operator on a stuck "Publishing…" spinner with the button disabled forever. */
  pollError: string | null;
  publishError: string | null;
  /** True while a {@link publish} POST is in flight — briefer than {@link isPublishing}, which stays
   *  true for the whole publish, not just the initial request. Exposed (unlike an internal-only flag)
   *  so the caller can disable the Publish button on this alone, before any run comes back — without
   *  it, a double-click could send two POSTs before the first one's response ever arrives. */
  publishing: boolean;
  /** Starts a real publish with the current field values. Resolves either way — a failure is
   *  surfaced through {@link publishError}, never a thrown rejection. A call while {@link publishing}
   *  is already true is a duplicate submit and is ignored outright, not just discouraged by the
   *  disabled button — see this function's own implementation note.
   *
   *  `options.credentialId` names the saved connection the publish must use (terra review
   *  2026-09-20, finding 1). This hook never picks one itself: it has no credentials controller, and
   *  the caller (`StaticSiteTab`) is the one screen that knows which connection the operator is
   *  actually looking at. Omitted when this provider has no saved connection.
   *
   *  `options.destination` replays a saved destination (the Sites Export tab's Publish list) instead
   *  of this form's fields: the server already validated that target, project and config once. */
  publish: (options?: StaticPublishOptions) => Promise<void>;

  t: Translate;
}

/** What one {@link StaticPublishController.publish} call may name. */
export interface StaticPublishOptions {
  credentialId?: string;
  destination?: { config: AdminStaticPublishConfig; projectName: string };
}

/** Same interval `use-static-export.hooks.ts` polls its own run at — see that constant's doc for
 *  why this width. Publishing additionally blocks on an external provider's own build (up to
 *  roughly a minute per `publish-site.ts`'s header), so this loop simply runs for longer, not
 *  faster or slower. */
const PUBLISH_POLL_INTERVAL_MS = 1500;

/** Same bound and same rationale as `use-static-export.hooks.ts`'s own `POLL_FAILURE_LIMIT` — how
 *  many CONSECUTIVE poll failures the loop below tolerates before giving up and surfacing
 *  {@link StaticPublishController.pollError} instead of retrying forever. */
const PUBLISH_POLL_FAILURE_LIMIT = 3;

export function useStaticPublish(port: StaticPublishPort, t: Translate, locale: string): StaticPublishController {
  const targetsQuery = useFetchQuery({ key: ["deployment", "publish-targets"], fetch: () => port.listPublishTargets() });
  // The host's own text in the viewer's locale, once, so every consumer (this form, the credential
  // rows built from these targets) renders it translated.
  const targets = useMemo(() => localizePublishTargets(targetsQuery.data, locale), [targetsQuery.data, locale]);
  const targetsError = targetsQuery.error ? publishLoadErrorMessage(locale, describeApiError(targetsQuery.error, "unknown error")) : null;
  const [chosenTarget, setChosenTarget] = useState<AdminStaticPublishTargetId | null>(null);
  const target = chosenTarget ?? targets?.[0]?.id ?? "";
  const selectedTarget = publishTargetById(targets, target);
  const [valuesByTarget, setValuesByTarget] = useState<Record<AdminStaticPublishTargetId, Record<string, string>>>({});
  const configValues = valuesByTarget[target] ?? {};
  const [projectName, setProjectName] = useState("");

  const [preview, setPreview] = useState<AdminStaticPublishPreview | undefined>(undefined);
  const [previewLoading, setPreviewLoading] = useState(false);
  const [previewError, setPreviewError] = useState<string | null>(null);

  // Bumped by every field edit (via `invalidatePreview` below) so `checkPreview` can tell whether
  // the fields it was called against are still the CURRENT fields once its request resolves — see
  // that function's own note (C3 fix).
  const previewGenerationRef = useRef(0);

  // Synchronous duplicate-submit guard for `checkPreview()` (2026-09-05 stale-settlement sweep, C5
  // fix) — same reasoning `publishingRef` documents for `publish()` below, PLUS a second failure mode
  // specific to `checkPreview`: with no guard, two overlapping calls share the one `previewLoading`
  // flag, so whichever call's own `finally` fires FIRST clears it while the OTHER is still in flight —
  // the Preview button (and any caller depending on `previewLoading`) would read "not loading" with a
  // request still outstanding. A ref, not `previewLoading` (state) itself: a same-tick double call
  // (or any caller reaching `checkPreview()` directly, not just through the disabled button) must see
  // the other call's claim synchronously, before either has re-rendered.
  const previewCallRef = useRef(false);

  // Every setter below clears the (now stale) preview as a side effect — see this file's header.
  function invalidatePreview() {
    previewGenerationRef.current += 1;
    setPreview(undefined);
    setPreviewError(null);
  }
  function setTarget(value: AdminStaticPublishTargetId) {
    if (publishTargetById(targets, value) === undefined) return;
    setChosenTarget(value);
    invalidatePreview();
  }
  function setConfigField(name: string, value: string) {
    setValuesByTarget((prev) => ({ ...prev, [target]: { ...prev[target], [name]: value } }));
    invalidatePreview();
  }

  async function checkPreview() {
    // A second call while the first is still in flight is a duplicate submit — ignore it here too,
    // not just via the UI's `previewLoading`-gated disabled state, so the race can't still send two
    // requests or tear down `previewLoading` out from under the call that's still running (C5 fix,
    // same "ignored outright" idiom `publish()`'s `publishingRef` uses below). Safe against a
    // same-tick double call specifically because it is synchronous: nothing yields between the read
    // and the write, so a second synchronous call always observes this call's claim.
    if (previewCallRef.current || selectedTarget === undefined) return;
    previewCallRef.current = true;
    // Captured BEFORE the request starts — if a field edit bumps `previewGenerationRef` while this
    // request is in flight, the comparison below after `await` tells us this result is now stale
    // (C3 fix: without it, a slow preview response for `acme/old` could resolve AFTER the operator
    // had already changed the field to `acme/new` and repopulate the form with the wrong target).
    const requestGeneration = previewGenerationRef.current;
    setPreviewError(null);
    setPreviewLoading(true);
    try {
      const result = await port.getPublishPreview(buildStaticPublishConfig(selectedTarget, configValues));
      // A field edited after this request started already invalidated the preview and moved the
      // generation forward — applying this now-stale result would repopulate the OLD fields over a
      // form the operator has since changed. Discard it silently; the edit's own `invalidatePreview()`
      // already left `preview`/`previewError` in the right (empty) state.
      if (previewGenerationRef.current !== requestGeneration) return;
      setPreview(result);
    } catch (err) {
      if (previewGenerationRef.current !== requestGeneration) return;
      setPreviewError(publishPreviewErrorMessage(locale, describeApiError(err, "unknown error")));
    } finally {
      // Unconditional, unlike the two branches above: this request's own spinner must stop once ITS
      // OWN network call settles regardless of generation, or a discarded stale response would leave
      // `previewLoading` stuck true forever with nothing left in flight to ever clear it. Safe to
      // always release `previewCallRef` here too now that duplicates are refused at entry, above —
      // there is never a second, still-running call left whose own flag this could clobber.
      previewCallRef.current = false;
      setPreviewLoading(false);
    }
  }

  const query = useFetchQuery({ key: ["deployment", "publish"], fetch: () => port.getPublishStatus() });
  const [run, setRun] = useState<AdminPublishRunSnapshot | undefined>(undefined);
  const [publishing, setPublishing] = useState(false);
  const [publishError, setPublishError] = useState<string | null>(null);
  const [pollError, setPollError] = useState<string | null>(null);

  // Seeds `run` from the query's first successful load, exactly once — same shape
  // `use-static-export.hooks.ts`'s own `seededRef` uses, and for the same reason (a reload mid-
  // publish, or a second tab, should show the real state rather than a blank "not started").
  const seededRef = useRef(false);
  useEffect(() => {
    if (seededRef.current || query.status === "loading" || !query.data) return;
    seededRef.current = true;
    setRun(query.data);
  }, [query.status, query.data]);

  const loadError = query.error ? publishLoadErrorMessage(locale, describeApiError(query.error, "unknown error")) : null;

  // Counts CONSECUTIVE poll failures for the `PUBLISH_POLL_FAILURE_LIMIT` bound below — same ref-not-
  // state reasoning `use-static-export.hooks.ts`'s own `pollFailuresRef` documents.
  const pollFailuresRef = useRef(0);
  // Synchronous duplicate-submit guard for `publish()` — a ref, not the `publishing` state, because a
  // true double-click can fire two calls in the same synchronous tick, before React has re-rendered
  // with `publishing: true`; `publishing` (state) still exists to let the UI disable the button, but
  // the guard that actually stops a second POST from ever being sent has to be synchronous (C4 fix).
  const publishingRef = useRef(false);

  const isPublishing = run?.status === "running" && pollError === null;

  // Self-scheduling poll loop, re-armed only when `isPublishing` flips true — identical shape and
  // identical reasoning to `use-static-export.hooks.ts`'s own poll effect; see that file's comment
  // for why `run`/`port` are deliberately excluded from the dependency list.
  // biome-ignore lint/correctness/useExhaustiveDependencies: re-armed only when `isPublishing` flips true; `run`/`port` deliberately excluded — see comment above.
  useEffect(() => {
    if (!isPublishing) return undefined;
    let cancelled = false;
    let timer: ReturnType<typeof setTimeout>;

    function scheduleNext() {
      timer = setTimeout(poll, PUBLISH_POLL_INTERVAL_MS);
    }
    async function poll() {
      try {
        const status = await port.getPublishStatus();
        if (cancelled) return;
        pollFailuresRef.current = 0;
        setRun(status);
        if (status.status === "running") scheduleNext();
      } catch (err) {
        if (cancelled) return;
        pollFailuresRef.current += 1;
        if (pollFailuresRef.current >= PUBLISH_POLL_FAILURE_LIMIT) {
          // Bounded (C2, same shape as use-static-export.hooks.ts's own fix): give up rather than
          // retry forever. Setting `pollError` also flips `isPublishing` false on the next render,
          // which re-arms this effect's own cleanup — but `return` here (no `scheduleNext()`) is
          // what actually stops the loop; it must not depend on that later render having happened.
          setPollError(publishPollErrorMessage(locale, describeApiError(err, "unknown error")));
          return;
        }
        scheduleNext();
      }
    }
    scheduleNext();

    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [isPublishing]);

  async function publish(options: StaticPublishOptions = {}) {
    // A second call while the first is still in flight is a duplicate submit (e.g. a double-click
    // landing before React re-renders with the button disabled) — ignore it here too, not just via
    // the UI's `publishing`-gated disabled state, so the race can't still send two POSTs (C4 fix).
    // This check-then-set is safe against a same-tick double call specifically BECAUSE it is
    // synchronous: nothing yields between the read and the write below, so a second synchronous call
    // always observes this call's write.
    const request = publishRequestFor({ options, selectedTarget, configValues, projectName });
    if (publishingRef.current || request === undefined) return;
    publishingRef.current = true;
    // Local action supersedes any still-pending bootstrap read — same C1 fix and same reasoning
    // `use-static-export.hooks.ts`'s own `trigger()` documents: this write is synchronous and
    // happens-before the `await` below, so it wins the race regardless of how late the bootstrap
    // read resolves.
    seededRef.current = true;
    // A fresh publish also clears any earlier poll-failure standoff (C2) — the operator retrying via
    // this same button is exactly the recovery path a stalled `pollError` is meant to unblock.
    pollFailuresRef.current = 0;
    setPollError(null);
    setPublishError(null);
    setPublishing(true);
    try {
      const started = await port.triggerPublish({
        ...request,
        // Conditional spread, never `credentialId: options.credentialId` — an absent choice must not
        // reach the wire as an explicit `undefined` key.
        ...(options.credentialId !== undefined ? { credentialId: options.credentialId } : {}),
      });
      setRun(started);
    } catch (err) {
      setPublishError(publishTriggerErrorMessage(locale, describeApiError(err, "unknown error")));
    } finally {
      publishingRef.current = false;
      setPublishing(false);
    }
  }

  return {
    targets,
    targetsError,
    target,
    selectedTarget,
    setTarget,
    configValues,
    setConfigField,
    canPreview: staticPublishFormReadyForPreview(selectedTarget, configValues),
    canPublish: staticPublishFormReadyToPublish(selectedTarget, configValues, projectName),
    projectNameCopy: staticPublishProjectNameCopy(selectedTarget),
    projectName,
    setProjectName,
    preview,
    previewLoading,
    previewError,
    checkPreview,
    run,
    isPublishing,
    loadError,
    pollError,
    publishError,
    publishing,
    publish,
    t,
  };
}

/** The target config and project name a publish sends: a replayed destination as saved, else the
 *  form's current fields. `undefined` while the form has no target loaded yet. @complexity O(f). */
function publishRequestFor(input: {
  options: StaticPublishOptions;
  selectedTarget: AdminPublishTargetDescriptor | undefined;
  configValues: Readonly<Record<string, string>>;
  projectName: string;
}): { config: AdminStaticPublishConfig; projectName: string } | undefined {
  if (input.options.destination) return input.options.destination;
  if (input.selectedTarget === undefined) return undefined;
  return {
    config: buildStaticPublishConfig(input.selectedTarget, input.configValues),
    projectName: staticPublishProjectNameToSend(input.selectedTarget, input.projectName),
  };
}

/**
 * Binds the real `/api/.../system/publish*` client, and a `t` bound to the real resolved locale —
 * the zero-argument half of the `useX(dependencies)` / `useWiredX()` pair, same shape
 * `use-static-export.hooks.ts`'s `useWiredStaticExport` documents.
 */
export function useWiredStaticPublish(): StaticPublishController {
  const locale = useAdminLocale();
  const t = (key: string): string => defaultT({ locale: locale, key: key });
  return useStaticPublish(defaultStaticPublishPort, t, locale);
}

import {
  ApiError,
  type AdminDeploymentEnvVarStatus,
  type AdminDeploymentOverview,
  type AdminExportRunSnapshot,
  type AdminPublishConnectionInput,
  type AdminPublishCredentialProviderId,
  type AdminPublishCredentialSummary,
  type AdminPublishCredentialVerification,
  type AdminPublishExecutionMode,
  type AdminPublishRunSnapshot,
  type AdminPublishTargetCredentialSpec,
  type AdminPublishTargetDescriptor,
  type AdminPublishTargetField,
  type AdminStaticPublishConfig,
  type AdminStaticPublishTargetId,
} from "../../lib/api";

/**
 * @file Pure data and computation for the Deployment panel — no React, no fetch, no `t()` calls
 * (every function here returns a DICTIONARY KEY for a caller to translate, same convention
 * `use-page-editor.hooks.ts`'s `themeExploreSaveLabel`-style helpers follow elsewhere in this app).
 * Kept separate from the five tab components per this app's `rules.ts`-holds-the-logic convention
 * (see `integrations/rules.ts`, `recovery/rules.ts`).
 */

/** The Static Site tab's export-status name on `lib/content-refresh-bus.ts` — see
 *  `taxonomy/rules.ts`'s `TAXONOMY_RESOURCE` for why this is a plain colocated constant rather than
 *  a shared registry. Agent-writable via `deployment_trigger_export`
 *  (`apps/website/src/features/deployments/agent-tools.ts`), which starts a run this tab polls.
 *  `use-static-export.hooks.ts`'s own header explains why the refresh is a bespoke re-fetch rather
 *  than the usual `useInvalidate()` one-liner — `run` seeds once and is never re-derived from the
 *  query afterward. There is deliberately NO sibling constant for `use-dockerfile-source.hooks.ts`:
 *  that tab holds a live, editable `draft` protected by its own etag/412-conflict machinery
 *  (`deployment_set_dockerfile` is the exact write that machinery exists to detect), and a
 *  bus-driven reload would either be inert against its one-shot seed guard or reintroduce the
 *  draft-clobber risk that guard prevents — see that hook's own file header. */
export const DEPLOYMENT_EXPORT_RESOURCE = "deployment-export";


/**
 * The single fixed label every connection saved through the flat per-provider credential list uses
 * (2026-08-15 redesign) — the server's `publish_credential_sets` table still enforces a UNIQUE
 * `(workspace_id, provider_id, label)`, so a label is still written on every create, it is just never
 * shown or typed by an operator anymore. Because the deploy registry names each target at most once, `(provider_id, "default")` can
 * never collide with itself within one workspace — see `use-publish-credentials.hooks.ts`'s header for
 * why a save only ever CREATES with this label when the provider has no saved connection yet, and
 * UPDATEs the existing one (by id, keeping whatever label it already has) otherwise.
 */
export const PUBLISH_CREDENTIAL_ROW_LABEL = "default";

/**
 * Every saved credential for one provider, in the order the server returned them.
 * @complexity O(n) in this workspace's total saved-credential count (small — see
 *   `VendorCredentialSetRepoPort.listByWorkspace`'s own doc for why no cap is needed).
 */
export function credentialsForProvider(
  credentials: readonly AdminPublishCredentialSummary[],
  providerId: AdminPublishCredentialProviderId
): AdminPublishCredentialSummary[] {
  return credentials.filter((credential) => credential.providerId === providerId);
}

/**
 * Which saved connection (if any) a provider's flat credential row should treat as "connected" — the
 * group's DEFAULT row, which is also the exact row `resolveDefaultForPublish`/
 * `composePublishCredentialSource` (server-side `static-publish/credentials.ts`) actually publishes
 * with, so the row's own status can never claim "connected" for a saved credential a real publish
 * would not use. Falls back to the first saved row only as a defensive read for data saved before
 * this UI existed — the store's own write-path invariant (`decideCreateDefault`) guarantees at most
 * one row is ever marked default once any exist for a provider, so this fallback is unreachable
 * against data this UI itself ever wrote.
 * @complexity O(n) in this provider's own (small) saved-connection count.
 */
export function defaultCredentialForProvider(
  credentials: readonly AdminPublishCredentialSummary[],
  providerId: AdminPublishCredentialProviderId
): AdminPublishCredentialSummary | undefined {
  const forProvider = credentialsForProvider(credentials, providerId);
  return forProvider.find((credential) => credential.isDefault) ?? forProvider[0];
}

/**
 * The saved-credential list as it stands once the server has confirmed `promoted` as its provider's
 * default: that row replaced by the server's own summary, every OTHER row for the same provider
 * un-defaulted (the store's "`isDefault: true` always wins" rule), other providers untouched. Applied
 * only after the write has resolved — never optimistically — so it restates what the server did
 * rather than guessing ahead of it.
 *
 * Generic over any credential-summary shape carrying `id`/`providerId`/`isDefault` — both
 * `AdminPublishCredentialSummary` and `AdminSourceControlCredentialSummary` satisfy it field-for-
 * field, so the Security page's Access Tokens tab (`security/hooks/use-access-tokens.hooks.ts`'s
 * `makeDefault`) reuses this verbatim rather than reimplementing the same "promotion confirmed, list
 * stays honest even if the follow-up reconcile refetch fails" fix this hook already needed (terra
 * review 2026-09-20).
 * @complexity O(n) in the credential list's own length.
 */
export function withPromotedDefault<T extends { id: string; providerId: string; isDefault: boolean }>(
  credentials: readonly T[],
  promoted: T
): T[] {
  return credentials.map((credential) => {
    if (credential.id === promoted.id) return promoted;
    if (credential.providerId !== promoted.providerId) return credential;
    return { ...credential, isDefault: false };
  });
}


/** What a rejected credential create/update means for the FORM — a dictionary-key-shaped result
 *  for `use-publish-credentials.hooks.ts` to translate and apply, same "return a fact, never call
 *  `t()`" convention this file's own header states. `"generic"` is the catch-all every other kind
 *  falls back to (an unreachable server, an unexpected 500, …), handled by the caller's own
 *  `describeApiError`-wrapped template rather than by this function. */
export type PublishCredentialSubmitFailure = { kind: "duplicate-label" } | { kind: "validation"; detail: string } | { kind: "generic" };

/**
 * Classifies a rejected `createCredential`/`updateCredential` call. Checks BOTH `e.code` and
 * `e.message` for the two known markers (`DUPLICATE_LABEL`, `VALIDATION`) rather than only one:
 * this app's usual server shape is `{ error: <human message>, code: <MACHINE_CODE> }` (see
 * `workspace/rules.ts`'s own `describeApiError` override for the precedent), but the dispatched API
 * contract for this route writes `409 -> { error: "DUPLICATE_LABEL" }` and
 * `400 -> { error: "VALIDATION", detail }` with no separate `code` field at all — `request()`
 * (`lib/api.ts`) puts `body.error` into `e.message` and `body.code` into `e.code`, so whichever
 * shape the concurrently-built backend actually sends, one of the two carries the marker.
 * @complexity O(1).
 */
export function classifyPublishCredentialSubmitError(e: unknown): PublishCredentialSubmitFailure {
  if (!(e instanceof ApiError)) return { kind: "generic" };
  const marker = e.code ?? e.message;
  if (marker === "DUPLICATE_LABEL") return { kind: "duplicate-label" };
  if (marker === "VALIDATION") {
    const detail = typeof e.body?.detail === "string" ? e.body.detail : e.message;
    return { kind: "validation", detail };
  }
  return { kind: "generic" };
}

/** The descriptor for `id`, or `undefined` while the list loads or when the id is not listed.
 *  @complexity O(t) in the (small) target count. */
export function publishTargetById(
  targets: readonly AdminPublishTargetDescriptor[] | undefined,
  id: AdminStaticPublishTargetId
): AdminPublishTargetDescriptor | undefined {
  return targets?.find((target) => target.id === id);
}

/** Whether every field `fields` marks required has a non-blank value in `values` — the one
 *  readiness rule both the publish form (config fields) and the credential form (credential fields)
 *  use, mirroring the server's own descriptor validation so a button never enables for a request
 *  the server would refuse on shape alone. @complexity O(f). */
export function requiredFieldsFilled(
  fields: readonly AdminPublishTargetField[],
  values: Readonly<Record<string, string>>
): boolean {
  return fields.every((field) => !field.required || (values[field.name] ?? "").trim() !== "");
}

/** The declared fields' values, trimmed, with blank ones dropped — so a blank optional field (a
 *  branch, a team) gets the server's own default instead of an explicit empty string, and
 *  undeclared keys never reach the wire. @complexity O(f). */
export function declaredFieldValues(
  fields: readonly AdminPublishTargetField[],
  values: Readonly<Record<string, string>>
): Record<string, string> {
  const out: Record<string, string> = {};
  for (const field of fields) {
    // Secrets reach the store unchanged; ordinary config values retain their existing trimming.
    const raw = values[field.name] ?? "";
    const value = field.secret ? raw : raw.trim();
    if (value !== "") out[field.name] = value;
  }
  return out;
}

/** The wire config for one publish/preview: the target plus its declared config values.
 *  @complexity O(f). */
export function buildStaticPublishConfig(
  target: AdminPublishTargetDescriptor,
  values: Readonly<Record<string, string>>
): AdminStaticPublishConfig {
  return { target: target.id, fields: declaredFieldValues(target.configFields, values) };
}

/** Whether the publish form can ask for a PREVIEW: a known target with its required config
 *  fields filled. @complexity O(f). */
export function staticPublishFormReadyForPreview(
  target: AdminPublishTargetDescriptor | undefined,
  values: Readonly<Record<string, string>>
): boolean {
  return target !== undefined && requiredFieldsFilled(target.configFields, values);
}

/** Whether the form can ask for a real PUBLISH — everything a preview needs plus a non-blank
 *  `projectName` when the host declares one (the preview has no such field). @complexity O(f). */
export function staticPublishFormReadyToPublish(
  target: AdminPublishTargetDescriptor | undefined,
  values: Readonly<Record<string, string>>,
  projectName: string
): boolean {
  const projectNameReady = target?.projectName === undefined || projectName.trim() !== "";
  return projectNameReady && staticPublishFormReadyForPreview(target, values);
}

/** The `projectName` the publish request carries. The server requires a non-blank one on every
 *  publish, but a host that declares no project name (e.g. object storage) ignores it, so the
 *  admin hides the field and sends the host's id instead. @complexity O(1). */
export function staticPublishProjectNameToSend(target: AdminPublishTargetDescriptor, projectName: string): string {
  return target.projectName === undefined ? target.id : projectName;
}

/** Whether a credential form has enough typed to save: a non-blank token (a blank one on a
 *  connected row means "keep the stored secret", so there is nothing to send) plus every required
 *  field the host's descriptor declares. @complexity O(f). */
export function credentialFormReadyToSave(
  spec: AdminPublishTargetCredentialSpec,
  values: Readonly<Record<string, string>>
): boolean {
  return (values[spec.tokenField] ?? "").trim() !== "" && requiredFieldsFilled(spec.fields, values);
}

/** The wire connection for one host's credential form: its id plus the declared fields' trimmed,
 *  non-blank values. @complexity O(f). */
export function buildCredentialConnectionInput(
  providerId: AdminPublishCredentialProviderId,
  spec: AdminPublishTargetCredentialSpec,
  values: Readonly<Record<string, string>>
): AdminPublishConnectionInput {
  const fields = declaredFieldValues(spec.fields, values);
  // tokenField is authoritative even for a descriptor that omitted its secret flag.
  const token = values[spec.tokenField] ?? "";
  if (token === "") delete fields[spec.tokenField];
  else fields[spec.tokenField] = token;
  return { ...fields, providerId };
}

/** The project-name field's label and help. The same wire field means a different thing per host
 *  (a commit message, a site, a project), so each host's descriptor names it; a host that declares
 *  none takes no project name and gets no field (`null`). Both strings are already in the viewer's
 *  locale (`localizePublishTargets`); the translator passes them through. @complexity O(1). */
export interface StaticPublishProjectNameCopy {
  readonly labelKey: string;
  readonly helpKey: string | undefined;
}

export function staticPublishProjectNameCopy(target: AdminPublishTargetDescriptor | undefined): StaticPublishProjectNameCopy | null {
  const copy = target?.projectName;
  if (copy === undefined) return null;
  return { labelKey: copy.label, helpKey: copy.help };
}

/** A descriptor field name as an `agentHandle` segment: `agentHandle()` throws on anything but
 *  lowercase words joined by single hyphens, and one throw blanks the whole admin, so a camelCase
 *  name (`accessKeyId`) becomes `access-key-id`. @complexity O(n) in the name's length. */
export function fieldNameHandleSegment(fieldName: string): string {
  return fieldName
    .replace(/([a-z0-9])([A-Z])/g, "$1-$2")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

/** The `agentHandle` id of one publish-config input. Ids predate the descriptors and are pinned by
 *  agent tooling, so `teamId` keeps its old `team` id; every other field uses its own name.
 *  @complexity O(n) in the name's length. */
export function publishConfigFieldHandleId(fieldName: string): string {
  return `deployment-static-site-publish-${fieldName === "teamId" ? "team" : fieldNameHandleSegment(fieldName)}`;
}

/** The `agentHandle`/DOM id of one credential input. The token field keeps its old `token` id and
 *  `accountId` its old `account` id (both pinned by agent tooling); every other field uses its own
 *  name. @complexity O(n) in the name's length. */
export function credentialFieldHandleId(providerId: string, fieldName: string, tokenField: string): string {
  if (fieldName === tokenField) return `deployment-static-site-credentials-token-${providerId}`;
  return `deployment-static-site-credentials-${fieldName === "accountId" ? "account" : fieldNameHandleSegment(fieldName)}-${providerId}`;
}

/** How a host's credential is named mid-sentence: its token field's own label ("API token",
 *  "Secret access key"), lower-cased unless it starts with an acronym; "access token" when the
 *  descriptor has no such field. @complexity O(f) in the credential's field count. */
export function credentialNoun(credential: AdminPublishTargetCredentialSpec): string {
  const label = credential.fields.find((field) => field.name === credential.tokenField)?.label ?? "access token";
  return /^[A-Z]{2}/.test(label) ? label : label.charAt(0).toLowerCase() + label.slice(1);
}

/** Step 1's subtitle — why connecting here is necessary, which depends on `executionMode` (the
 *  server's own fact about whether this WORKSPACE can reach the operator's terminal at all — see
 *  `AdminPublishExecutionMode`'s doc in `lib/api.ts`), not on whether the selected PROVIDER has a
 *  CLI route. Otherwise it names the host's own credential ({@link credentialNoun}), never a
 *  "personal access token" a host that issues only API tokens or access key pairs does not have. @complexity O(f). */
export function credentialStepSubtitle(executionMode: AdminPublishExecutionMode, credential: AdminPublishTargetCredentialSpec, translate: (key: string) => string): string {
  if (executionMode === "hosted-api-only") {
    return translate("This workspace can't use your computer's terminal — connecting here is the only way to publish.");
  }
  return translate("Save your {credential} so Tovu can publish on your behalf.").replace("{credential}", credentialNoun(credential));
}

/** The help a config field, credential field or credential form shows: the descriptor's
 *  person-facing `userHelp`, else its `help` (written for the agent); `undefined` when it has
 *  neither. @complexity O(1). */
export function fieldHelpText(field: AdminPublishTargetField | AdminPublishTargetCredentialSpec): string | undefined {
  return field.userHelp ?? field.help;
}

/** The label a config or credential field shows: the descriptor's label, with the generic
 *  "(optional)" suffix key when the field is optional. The caller translates `suffixKey`.
 *  @complexity O(1). */
export function fieldLabelParts(field: AdminPublishTargetField): { label: string; suffixKey: string | null } {
  return { label: field.label, suffixKey: field.required ? null : "(optional)" };
}

/** One row of the two paths' capability comparison. `supported` is a fact about the PATH, not about
 *  whether Tovu can currently deploy to it — see {@link STATIC_SITE_CAPABILITIES}. */
export interface DeploymentCapability {
  readonly id: string;
  readonly labelKey: string;
  readonly supported: boolean;
}

/**
 * What a static export can and cannot serve.
 *
 * Every row restates something this panel already asserted in prose, so the list adds legibility
 * and no new claims: the three `false` rows are the three items in the tab's own existing warning
 * ("No checkout, no admin online, no assistant, no dynamic anything"), and the one `true` row is
 * what `src/platform/export/route-manifest.ts` actually resolves — home, products and theme pages plus every
 * published post, which is also exactly what the Static Site tab's own build copy says the exporter
 * writes.
 *
 * This describes the OUTPUT of an export, which exists and works today from the CLI. It is not a
 * claim that this screen can trigger one — that is the disabled action's own separate, stated
 * reason.
 */
export const STATIC_SITE_CAPABILITIES: readonly DeploymentCapability[] = [
  { id: "content", labelKey: "Pages, posts & products", supported: true },
  { id: "checkout", labelKey: "Checkout & orders", supported: false },
  { id: "admin", labelKey: "Admin panel, online", supported: false },
  { id: "assistant", labelKey: "AI assistant", supported: false },
] as const;

/**
 * What the full server serves — the same four rows, all supported, which is the whole point of
 * showing them side by side: the difference between the two paths becomes a shape you can see
 * rather than two sentences you have to hold in your head and diff.
 *
 * This describes the full server's capabilities for the Overview comparison. Deployment
 * provisioning is handled by the deploy plugin; the old Full Site provider list was retired.
 */
export const FULL_SITE_CAPABILITIES: readonly DeploymentCapability[] = STATIC_SITE_CAPABILITIES.map((row) => ({
  ...row,
  supported: true,
}));

/**
 * The Overview tab's per-env-var explanatory note, as a dictionary key. `TOVU_SITE_KEY`
 * is boot-blocking in production (`REQUIRED_SECRETS` above; `boot-readiness-gate.ts`'s
 * the production readiness gate calls `process.exit(1)` when neither the env var nor a valid key
 * file resolves) but NOT in local/dev mode, where an unset value instead surfaces later as a 503 on
 * the AI Assistant screen — worded here so the note itself states that split, rather than the UI
 * inventing a severity color the underlying fact doesn't support.
 *
 * 2026-09-14: corrected from "Not required to boot" — that was true only for local/dev mode and
 * read as a blanket claim; the production boot gate has required it since `boot-readiness-gate.ts`'s
 * 2026-09-09 durability fix.
 *
 * @complexity O(1) — one map lookup.
 */
export function deploymentEnvVarNoteKey(name: string): string {
  const notes: Record<string, string> = {
    TOVU_ADMIN_PASSWORD: "Falls back to a public default.",
    TOVU_ADMIN_USER: 'Falls back to "admin".',
    TOVU_SITE_KEY: "Required to boot in production. Missing locally shows as a 503 on the AI Assistant screen instead.",
    JINI_AGENT_DAEMON_PORT: "Falls back to port 4319.",
  };
  return notes[name] ?? "";
}

/**
 * Whether an env var's row should read as a warning rather than neutral "not set" — malformed root
 * key material, and the owner-password var, since an unset/default password is the one env-var state with a real
 * safety consequence at production boot (`production-readiness-gate.ts`'s `PRODUCTION_BOOT_UNSAFE_DEFAULT`).
 * The other three vars degrade gracefully (a daemon port default, an admin username default, a
 * later 503 on one specific screen) and do not warrant the same visual weight.
 *
 * @complexity O(1).
 */
export function isEnvVarRowUnsafe(varStatus: AdminDeploymentEnvVarStatus): boolean {
  return varStatus.invalid === true || (varStatus.name === "TOVU_ADMIN_PASSWORD" && !varStatus.set);
}

/**
 * The Overview env-var row's status label key. The site key row names a generated key file as its
 * source (the keyring reads the env var OR that file) and calls malformed material invalid rather
 * than "Not set", since something IS configured there and it is broken.
 * @complexity O(1).
 */
export function envVarStatusLabelKey(varStatus: AdminDeploymentEnvVarStatus): string {
  if (varStatus.invalid) return "Invalid — the keyring rejects it";
  if (!varStatus.set) return "Not set";
  return varStatus.source === "file" ? "Set (generated key file)" : "Set";
}

/**
 * The Static Site Verify status line's class. `"unreachable"` means the token was NOT checked, so it
 * reads as a warning — styling it like `"valid"` told an operator an unverified token had passed.
 * @complexity O(1).
 */
export function credentialVerifyStatusClass(row: {
  verifyError: string | null;
  verification: AdminPublishCredentialVerification | undefined;
}): "save-ok" | "save-warning" | "save-error" {
  if (row.verifyError || row.verification?.status === "invalid") return "save-error";
  return row.verification?.status === "unreachable" ? "save-warning" : "save-ok";
}

/** The Overview tab's runtime-mode label key. @complexity O(1). */
export function runtimeModeLabelKey(mode: AdminDeploymentOverview["mode"]): string {
  return mode === "production" ? "Production" : "Local";
}

/** The Overview tab's production-readiness-gate label key. `applicable: false` means the gate never
 *  ran (local mode) — see `DeploymentOverviewSnapshot.productionReadinessGate`'s own doc comment for
 *  why a request reaching this route in production mode already proves the gate passed.
 *  @complexity O(1). */
export function productionGateLabelKey(gate: AdminDeploymentOverview["productionReadinessGate"]): string {
  return gate.applicable ? "Passed" : "Not applicable (local mode)";
}

/** The Overview tab's agent-daemon status label key. @complexity O(1). */
export function daemonStatusLabelKey(daemonKnownFailed: boolean): string {
  return daemonKnownFailed ? "Known failure — check server logs." : "No known failure";
}

/** The Overview tab's owner-password status label key. @complexity O(1). */
export function ownerPasswordLabelKey(defaultOwnerPasswordUnsafe: boolean): string {
  return defaultOwnerPasswordUnsafe ? "Still the default — set TOVU_ADMIN_PASSWORD." : "Changed from the default.";
}

/** The `.status` tone a run's pill should use, shared between the export and publish run slots —
 *  both are `"idle"|"running"|"completed"|"errored"`, and only the "completed" case needs a second
 *  input (`ok`) to tell a real success apart from a completed-but-failed outcome (an export whose
 *  routes failed, or a publish `StaticPublishOutcome` with `ok: false`). @complexity O(1). */
export function runStatusTone(
  status: "idle" | "running" | "completed" | "errored",
  ok: boolean | undefined
): "neutral" | "warning" | "ok" | "error" {
  if (status === "idle") return "neutral";
  if (status === "running") return "warning";
  if (status === "errored") return "error";
  return ok === false ? "error" : "ok";
}

/** The Static Site tab's export-run status label key — `run` is `undefined` before the first poll
 *  has resolved, which reads the same as `"idle"` (nothing has ever run in THIS browser session's
 *  view of it either). @complexity O(1). */
export function exportRunStatusLabelKey(run: Pick<AdminExportRunSnapshot, "status" | "ok"> | undefined): string {
  const status = run?.status ?? "idle";
  if (status === "idle") return "Not started";
  if (status === "running") return "Exporting…";
  if (status === "errored") return "Export failed";
  return run?.ok === false ? "Finished with failures" : "Export finished";
}

/** The Static Site tab's publish-run status label key — same `undefined`-reads-as-idle convention
 *  {@link exportRunStatusLabelKey} documents, and the same `result.ok` distinction for a completed
 *  run that nonetheless failed (bad config, no credential, a rejected provider call — see
 *  `StaticPublishOutcome`'s own `code` union). @complexity O(1). */
export function publishRunStatusLabelKey(run: Pick<AdminPublishRunSnapshot, "status" | "result"> | undefined): string {
  const status = run?.status ?? "idle";
  if (status === "idle") return "Not started";
  if (status === "running") return "Publishing…";
  if (status === "errored") return "Publish failed";
  return run?.result?.ok === false ? "Publish failed" : "Published";
}

import { ConfirmDialog } from "@jini-ai/admin/react";
import { agentHandle } from "@jini-ai/agentic";

import { t } from "./email-i18n";
import type { MailActivityItem, MailFeedbackProviderSetup, MailSuppressionEntry } from "./email-api";
import { Chip, CopyButton, Loaded, Section, when, type Tone } from "./EmailParts";
import type { EmailActivityController, PagedList } from "./hooks/use-email-activity.hooks";

/**
 * @file The Activity tab: recent sends (filters, Load more, one send's feedback), blocked
 * addresses (search; Remove asks for a reason, then shows what removal means before the final
 * confirm — the server records the reason and only lets the owner do it), and whether provider
 * feedback (bounces, complaints) reaches this site. The page shows one section at a time (`part`,
 * from its segmented pill); with no `part` all three render.
 */

const OUTCOMES = ["accepted", "delivered", "bounced", "complained", "suppressed", "deferred", "failed", "unknown", "captured"] as const;

const OUTCOME: Record<string, { tone: Tone; label: string }> = {
  accepted: { tone: "ok", label: "Accepted" },
  delivered: { tone: "ok", label: "Delivered" },
  bounced: { tone: "error", label: "Bounced" },
  complained: { tone: "error", label: "Marked as spam" },
  suppressed: { tone: "warning", label: "Blocked" },
  deferred: { tone: "warning", label: "Delayed" },
  failed: { tone: "error", label: "Failed" },
  unknown: { tone: "neutral", label: "Unknown" },
  captured: { tone: "neutral", label: "Kept locally" },
};

const USE: Record<string, string> = {
  sign_in: "Sign-in link",
  newsletter_confirmation: "Newsletter confirmation",
  form_notification: "Form notification",
  newsletter: "Newsletter",
  test: "Test",
  unknown: "Other",
};

const SUPPRESSION_REASON: Record<MailSuppressionEntry["reason"], string> = {
  bounced: "Bounced",
  complained: "Marked as spam",
  manual: "Added by hand",
};

const FEEDBACK_STATE: Record<MailFeedbackProviderSetup["state"], { tone: Tone; label: string }> = {
  receiving: { tone: "ok", label: "Receiving" },
  no_events_yet: { tone: "neutral", label: "No events yet" },
  secret_missing: { tone: "warning", label: "Signing secret not saved" },
  unsupported: { tone: "neutral", label: "Not supported by this provider" },
};

function LoadMore<T>(props: { list: PagedList<T>; locale: string; handle: string }) {
  const { list, locale } = props;
  if (list.view.kind !== "loaded" || !list.view.data.nextCursor) return list.moreError ? <p className="jini-field-error">{t({ locale, key: list.moreError })}</p> : null;
  return (
    <div className="email-row">
      <button type="button" className="btn-secondary" disabled={list.loadingMore} onClick={() => void list.loadMore()} {...agentHandle({ handle: props.handle }, { role: "button", label: "Load more rows" })}>
        {list.loadingMore ? t({ locale, key: "Loading…" }) : t({ locale, key: "Load more" })}
      </button>
      {list.moreError ? <span className="jini-field-error">{t({ locale, key: list.moreError })}</span> : null}
    </div>
  );
}

function ActivityRow(props: { item: MailActivityItem; controller: EmailActivityController; locale: string; index: number }) {
  const { item, controller, locale } = props;
  const outcome = OUTCOME[item.outcome] ?? { tone: "neutral" as const, label: item.outcome };
  const open = item.id !== undefined && controller.openId === item.id;
  const detail = open ? controller.detail : null;
  return (
    <li className="email-activity">
      <div className="email-row email-activity-row">
        <Chip tone={outcome.tone}>{t({ locale, key: outcome.label })}</Chip>
        <span className="email-activity-what">
          <span className="email-activity-recipient">{item.recipient}</span>
          <span className="jini-field-hint">{t({ locale, key: USE[item.use] ?? item.use })} · {when(item.createdAt, locale)}</span>
        </span>
        {item.id ? (
          <button type="button" className="btn-secondary email-push-end" aria-expanded={open} onClick={() => controller.toggleDetail(item.id!)}
            {...agentHandle({ handle: `email-activity-${props.index}-details` }, { role: "button", label: "Show this send's details" })}>
            {open ? t({ locale, key: "Hide details" }) : t({ locale, key: "Details" })}
          </button>
        ) : null}
      </div>
      {detail ? (
        <div className="email-activity-detail">
          <Loaded view={detail} locale={locale}>
            {(data) => (
              <dl className="email-facts">
                <div className="email-fact"><dt className="jini-field-label">{t({ locale, key: "Provider" })}</dt><dd>{data.activity.providerId}</dd></div>
                {data.activity.originalRecipient ? (
                  <div className="email-fact"><dt className="jini-field-label">{t({ locale, key: "Meant for" })}</dt><dd>{data.activity.originalRecipient}</dd></div>
                ) : null}
                {data.activity.errorCode ? <div className="email-fact"><dt className="jini-field-label">{t({ locale, key: "Error" })}</dt><dd><code>{data.activity.errorCode}</code>{data.activity.message ? <p>{data.activity.message}</p> : null}</dd></div> : null}
                {data.activity.providerMessageId ? <div className="email-fact"><dt className="jini-field-label">{t({ locale, key: "Message ID" })}</dt><dd><code>{data.activity.providerMessageId}</code></dd></div> : null}
                <div className="email-fact">
                  <dt className="jini-field-label">{t({ locale, key: "Feedback" })}</dt>
                  <dd>
                    {data.feedback.length === 0
                      ? <span className="jini-field-hint">{t({ locale, key: "None received yet" })}</span>
                      : data.feedback.map((event, i) => <span key={i} className="jini-field-hint">{t({ locale, key: OUTCOME[event.kind]?.label ?? event.kind })} · {when(event.receivedAt, locale)}</span>)}
                  </dd>
                </div>
              </dl>
            )}
          </Loaded>
        </div>
      ) : null}
    </li>
  );
}

function RecentSends(props: { controller: EmailActivityController; locale: string; hideTitle: boolean }) {
  const { controller, locale } = props;
  return (
    <Section id="activity" title={t({ locale, key: "Recent sends" })} hideTitle={props.hideTitle}>
      <div className="email-filters">
        <select className="jini-input" aria-label={t({ locale, key: "Outcome" })} value={controller.filter.outcome ?? ""}
          onChange={(e) => controller.setFilter({ ...controller.filter, outcome: e.target.value || undefined })}
          {...agentHandle({ handle: "email-activity-outcome" }, { role: "field", label: "Filter sends by outcome" })}>
          <option value="">{t({ locale, key: "All outcomes" })}</option>
          {OUTCOMES.map((value) => <option key={value} value={value}>{t({ locale, key: OUTCOME[value]!.label })}</option>)}
        </select>
        <input className="jini-input" type="search" aria-label={t({ locale, key: "Recipient" })} placeholder={t({ locale, key: "Search by recipient" })}
          value={controller.filter.recipient ?? ""} onChange={(e) => controller.setFilter({ ...controller.filter, recipient: e.target.value })}
          {...agentHandle({ handle: "email-activity-recipient" }, { role: "field", label: "Filter sends by recipient address" })} />
      </div>
      <Loaded view={controller.activity.view} locale={locale} retry={controller.activity.reload}>
        {(page) => (
          <>
            {page.access === "masked" ? <p className="jini-field-hint">{t({ locale, key: "Addresses are partly hidden for your role." })}</p> : null}
            {page.items.length === 0 ? (
              <p className="jini-field-hint">{t({ locale, key: page.empty === "no_matches" ? "No sends match." : "No sends recorded yet." })}</p>
            ) : (
              <ul className="email-list">{page.items.map((item, i) => <ActivityRow key={item.id ?? `${item.createdAt}-${i}`} item={item} controller={controller} locale={locale} index={i} />)}</ul>
            )}
          </>
        )}
      </Loaded>
      <LoadMore list={controller.activity} locale={locale} handle="email-activity-more" />
    </Section>
  );
}

function RemovalBody(props: { controller: EmailActivityController; locale: string }) {
  const { controller, locale } = props;
  const step = controller.removal;
  if (!step) return null;
  if (step.kind === "reason") {
    return (
      <div className="email-removal">
        <p>{t({ locale, key: "{address} won't be blocked anymore. Why?" }).replace("{address}", step.entry.address)}</p>
        <label className="jini-field-label" htmlFor="email-removal-reason">{t({ locale, key: "Reason (kept in the record)" })}</label>
        <textarea id="email-removal-reason" className="jini-input" rows={3} value={step.reason} onChange={(e) => controller.setRemovalReason(e.target.value)}
          {...agentHandle({ handle: "email-removal-reason" }, { role: "field", label: "Why this address may get email again" })} />
        {step.error ? <p className="jini-field-error" role="alert">{t({ locale, key: step.error })}</p> : null}
      </div>
    );
  }
  return (
    <div className="email-removal">
      <p>
        {t({ locale, key: "Blocked since {when} ({why})." }).replace("{when}", when(step.plan.suppressedAt, locale)).replace("{why}", t({ locale, key: SUPPRESSION_REASON[step.plan.suppressionReason] }))}
      </p>
      <ul className="email-reasons">{step.plan.warnings.map((warning) => <li key={warning}>{warning}</li>)}</ul>
      <p className="jini-field-hint">{t({ locale, key: "Reason: {reason}" }).replace("{reason}", step.plan.reason)}</p>
      {step.error ? <p className="jini-field-error" role="alert">{t({ locale, key: step.error })}</p> : null}
    </div>
  );
}

function BlockedAddresses(props: { controller: EmailActivityController; locale: string; hideTitle: boolean }) {
  const { controller, locale } = props;
  const step = controller.removal;
  return (
    <Section id="blocked" title={t({ locale, key: "Blocked addresses" })} hideTitle={props.hideTitle}>
      <p className="jini-field-hint">{t({ locale, key: "Addresses that bounced, marked mail as spam, or were blocked by hand. Nothing is sent to them." })}</p>
      <input className="jini-input" type="search" aria-label={t({ locale, key: "Search blocked addresses" })} placeholder={t({ locale, key: "Search blocked addresses" })}
        value={controller.search} onChange={(e) => controller.setSearch(e.target.value)}
        {...agentHandle({ handle: "email-blocked-search" }, { role: "field", label: "Search blocked addresses" })} />
      {controller.removedNotice ? <p className="jini-field-hint" role="status">{t({ locale, key: "{address} can get email again." }).replace("{address}", controller.removedNotice)}</p> : null}
      <Loaded view={controller.suppressions.view} locale={locale} retry={controller.suppressions.reload}>
        {(page) => (page.items.length === 0 ? (
          <p className="jini-field-hint">{t({ locale, key: page.empty === "no_matches" ? "No blocked addresses match." : "No blocked addresses." })}</p>
        ) : (
          <ul className="email-list">
            {page.items.map((entry, i) => (
              <li key={`${entry.address}-${entry.scope}`} className="email-row email-blocked">
                <span className="email-activity-recipient">{entry.address}</span>
                <Chip tone={entry.reason === "manual" ? "neutral" : "warning"}>{t({ locale, key: SUPPRESSION_REASON[entry.reason] })}</Chip>
                <span className="jini-field-hint">{t({ locale, key: entry.scope === "bulk" ? "Newsletters only" : "All email" })} · {when(entry.createdAt, locale)}</span>
                <button type="button" className="btn-secondary email-push-end" onClick={() => controller.startRemoval(entry)}
                  {...agentHandle({ handle: `email-blocked-${i}-remove` }, { role: "button", label: `Unblock ${entry.address}` })}>
                  {t({ locale, key: "Unblock" })}
                </button>
              </li>
            ))}
          </ul>
        ))}
      </Loaded>
      <LoadMore list={controller.suppressions} locale={locale} handle="email-blocked-more" />
      <ConfirmDialog
        open={step !== null}
        agentHandle="email-blocked-remove"
        title={t({ locale, key: step?.kind === "confirm" ? "Unblock this address?" : "Unblock an address" })}
        body={<RemovalBody controller={controller} locale={locale} />}
        confirmLabel={t({ locale, key: step?.kind === "confirm" ? "Unblock" : "Continue" })}
        destructive={step?.kind === "confirm"}
        pending={step?.pending ?? false}
        onConfirm={() => void controller.continueRemoval()}
        onCancel={controller.cancelRemoval}
      />
    </Section>
  );
}

function FeedbackSetup(props: { controller: EmailActivityController; locale: string; hideTitle: boolean }) {
  const { controller, locale } = props;
  return (
    <Section id="feedback" title={t({ locale, key: "Bounce and spam reports" })} hideTitle={props.hideTitle}>
      <Loaded view={controller.feedback} locale={locale}>
        {(report) => (!report.available || report.providers.length === 0 ? (
          <p className="jini-field-hint">{t({ locale, key: "No active provider reports bounces here." })}</p>
        ) : (
          <ul className="email-list">
            {report.providers.map((provider) => {
              const state = FEEDBACK_STATE[provider.state];
              return (
                <li key={provider.providerId} className="email-provider">
                  <div className="email-row">
                    <strong className="email-provider-name">{provider.label}</strong>
                    <Chip tone={state.tone}>{t({ locale, key: state.label })}</Chip>
                  </div>
                  {provider.supported ? (
                    provider.webhookUrl ? (
                      <div className="email-row">
                        <span className="jini-field-label">{t({ locale, key: "Webhook URL" })}</span>
                        <code className="email-break">{provider.webhookUrl}</code>
                        <CopyButton text={provider.webhookUrl} label={t({ locale, key: "{provider} webhook URL" }).replace("{provider}", provider.label)} locale={locale} handle={`email-feedback-${provider.providerId}-copy`} />
                      </div>
                    ) : <span className="jini-field-hint">{t({ locale, key: "Verify the site's address first; the webhook URL needs it." })}</span>
                  ) : null}
                  {provider.lastVerifiedEvent ? (
                    <span className="jini-field-hint">{t({ locale, key: "Last report: {when}" }).replace("{when}", when(provider.lastVerifiedEvent.receivedAt, locale))}</span>
                  ) : null}
                </li>
              );
            })}
          </ul>
        ))}
      </Loaded>
    </Section>
  );
}

export function EmailActivityTab(props: { controller: EmailActivityController; locale: string; part?: "sends" | "blocked" | "reports" | undefined }) {
  const { controller, locale, part } = props;
  return (
    <>
      {part === undefined || part === "sends" ? <RecentSends controller={controller} locale={locale} hideTitle={part !== undefined} /> : null}
      {part === undefined || part === "blocked" ? <BlockedAddresses controller={controller} locale={locale} hideTitle={part !== undefined} /> : null}
      {part === undefined || part === "reports" ? <FeedbackSetup controller={controller} locale={locale} hideTitle={part !== undefined} /> : null}
    </>
  );
}

import { agentHandle } from "@jini-ai/agentic";

import { t } from "./email-i18n";
import type { MailTestSendResult, MailUseRow, MailUseState } from "./email-api";
import { Chip, Loaded, Section, when, type Tone } from "./EmailParts";
import type { EmailOverviewController } from "./hooks/use-email-overview.hooks";

/**
 * @file Overview's **What uses email** and **Send test email** sections (Status stays in
 * `Email.tsx`). The page shows one at a time (`part`, from its segmented pill); with no `part`
 * both render, as a standalone mount would want. A test result says exactly what happened — accepted by the provider, kept
 * locally, redirected, or failed — never "delivered".
 */

const USE_STATE: Record<MailUseState, { tone: Tone; label: string }> = {
  ready: { tone: "ok", label: "Ready" },
  blocked: { tone: "warning", label: "Blocked" },
  disabled: { tone: "neutral", label: "Off" },
  not_configured: { tone: "neutral", label: "Not configured" },
  unknown: { tone: "neutral", label: "Unknown" },
};

const USE_LABEL: Record<MailUseRow["use"], string> = {
  sign_in: "Sign-in links",
  newsletter_confirmation: "Newsletter confirmations",
  form_notifications: "Form notifications",
  newsletter: "Newsletter",
};

/** Plain words for the readiness codes the server reports; an unknown code shows as itself. */
const REASON: Record<string, string> = {
  sender_not_configured: "No From address is set.",
  durable_outbox_not_ready: "Background sending isn't available on this server yet.",
  mail_delivery_unavailable: "No provider can send yet.",
  no_form_notifications: "No form sends email notifications.",
  sending_enabled_false: "Newsletter sending is off.",
  consent_capability_unbound: "Newsletter consent isn't set up.",
  origin_not_verified: "The site's address isn't verified yet.",
  check_failed: "This check failed. Try again later.",
};

function UseRow(props: { row: MailUseRow; locale: string }) {
  const { row, locale } = props;
  const state = USE_STATE[row.state];
  return (
    <li className="email-use">
      <div className="email-row">
        <strong className="email-use-name">{t({ locale, key: USE_LABEL[row.use] ?? row.label })}</strong>
        <Chip tone={state.tone}>{t({ locale, key: state.label })}</Chip>
      </div>
      {row.reasons.length > 0 ? (
        <ul className="email-reasons">
          {row.reasons.map((code) => <li key={code} className="jini-field-hint">{REASON[code] ? t({ locale, key: REASON[code] }) : code}</li>)}
        </ul>
      ) : null}
      <span className="jini-field-hint">
        {row.evidence
          ? t({ locale, key: "Last send: {outcome}, {when}" }).replace("{outcome}", row.evidence.outcome).replace("{when}", when(row.evidence.at, locale))
          : t({ locale, key: "No sends yet" })}
      </span>
    </li>
  );
}

/** The one-line truth about a test send. Pure apart from translation. */
export function testResultLine(result: MailTestSendResult, locale: string): { tone: Tone; text: string } {
  switch (result.outcome) {
    case "accepted":
      return { tone: "ok", text: t({ locale, key: "Accepted by the provider for {to}." }).replace("{to}", result.to) };
    case "captured":
      return { tone: "neutral", text: t({ locale, key: "Kept on this machine — nothing was sent." }) };
    case "redirected":
      return { tone: "neutral", text: t({ locale, key: "Test mode sent it to {to} instead." }).replace("{to}", result.redirectedTo) };
    default:
      return { tone: "error", text: `${t({ locale, key: "Not sent." })} ${result.message}` };
  }
}

export function EmailOverviewTab(props: { controller: EmailOverviewController; locale: string; part?: "uses" | "test" | undefined }) {
  const { controller, locale, part } = props;
  return (
    <>
      {part === "test" ? null : <UsesSection controller={controller} locale={locale} hideTitle={part !== undefined} />}
      {part === "uses" ? null : <TestSection controller={controller} locale={locale} hideTitle={part !== undefined} />}
    </>
  );
}

function UsesSection(props: { controller: EmailOverviewController; locale: string; hideTitle: boolean }) {
  const { controller, locale } = props;
  return (
    <Section id="uses" title={t({ locale, key: "What uses email" })} hideTitle={props.hideTitle}>
      <Loaded view={controller.uses} locale={locale} retry={controller.reloadUses}>
        {(report) => (report.uses.length === 0
          ? <p className="jini-field-hint">{t({ locale, key: "Nothing on this site sends email yet." })}</p>
          : <ul className="email-list">{report.uses.map((row) => <UseRow key={row.use} row={row} locale={locale} />)}</ul>)}
      </Loaded>
    </Section>
  );
}

function TestSection(props: { controller: EmailOverviewController; locale: string; hideTitle: boolean }) {
  const { controller, locale } = props;
  const test = controller.test;
  const line = test.kind === "done" ? testResultLine(test.result, locale) : null;
  return (
    <Section id="test" title={t({ locale, key: "Send test email" })} hideTitle={props.hideTitle}>
      <form className="email-test-form" onSubmit={(event) => { event.preventDefault(); void controller.sendTest(); }}>
        <div className="jini-field email-field">
          <label className="jini-field-label" htmlFor="email-test-to">{t({ locale, key: "To" })}</label>
          <input id="email-test-to" className="jini-input" type="email" value={controller.to} onChange={(e) => controller.setTo(e.target.value)}
            placeholder={t({ locale, key: "Your account address" })} {...agentHandle({ handle: "email-test-to" }, { role: "field", label: "Test email recipient" })} />
        </div>
        <div className="email-row">
          <button type="submit" disabled={test.kind === "sending"} {...agentHandle({ handle: "email-test-send" }, { role: "button", label: "Send a test email" })}>
            {test.kind === "sending" ? t({ locale, key: "Sending…" }) : t({ locale, key: "Send test" })}
          </button>
        </div>
      </form>
      {line && test.kind === "done" ? (
        <div className="email-row" role="status">
          <Chip tone={line.tone}>{when(test.result.at, locale)}</Chip>
          <span className="jini-field-hint">{line.text}</span>
        </div>
      ) : null}
      {test.kind === "error" ? <p className="jini-field-error" role="alert">{t({ locale, key: test.message })}</p> : null}
      <p className="jini-field-hint">{t({ locale, key: "A test proves the provider accepts mail. It doesn't prove it arrives." })}</p>
    </Section>
  );
}

import type { ChangeEvent } from "react";
import { ConfirmDialog } from "@jini-ai/admin/react";
import { SecretInput } from "@/components/SecretInput/SecretInput";
import { agentHandle, agentHandleSegment } from "@jini-ai/agentic";

import type { AdminMailStatus } from "../../lib/api";
import { agentPluginDisplayName } from "../plugins/rules";
import { t } from "./email-i18n";
import type { MailProviderConfiguration, MailProviderField } from "./email-api";
import { Chip, Loaded, Section, Segments, when, type Tone } from "./EmailParts";
import { isFullyActive, type EmailProviderController } from "./hooks/use-email-provider.hooks";

/**
 * @file One provider card at a time (owner, 2026-10-22: every card stacked was too much).
 * Drafts survive URL segment changes. Save key does not switch delivery; Use this provider
 * switches both lanes after confirmation. No vendor branches: labels, fields and help links
 * all come from the provider's data. Unknown links fall back to the active, then first provider.
 * `_add-provider` lists disabled email plugins and enables through the Plugins API.
 * `_capabilities` is the final segment and shows the existing lane readiness rows.
 */

const LANE_STATE: Record<string, { tone: Tone; label: string }> = {
  ready: { tone: "ok", label: "Ready" },
  unconfigured: { tone: "warning", label: "Not set" },
  unknown_provider: { tone: "warning", label: "Not set" },
  missing_credential: { tone: "warning", label: "Key not saved" },
  local_only: { tone: "neutral", label: "No external delivery" },
};

const LANE_LABEL = { transactional: "Transactional mail", bulk: "Bulk mail" } as const;

function Lanes(props: { status: AdminMailStatus | null; providers: readonly MailProviderConfiguration[]; locale: string }) {
  const { status, locale } = props;
  const lanes = status?.lanes ?? [];
  if (lanes.length === 0) return null;
  const label = (id: string | null) => (id === null ? t({ locale, key: "None" }) : props.providers.find((p) => p.id === id)?.label ?? id);
  return (
    <dl className="email-facts">
      {lanes.map((lane) => {
        const state = LANE_STATE[lane.state] ?? { tone: "neutral" as const, label: lane.state };
        return (
          <div key={lane.lane} className="email-fact">
            <dt className="jini-field-label">{t({ locale, key: LANE_LABEL[lane.lane] })}</dt>
            <dd>
              <span className="jini-field-hint">{label(lane.providerId)}</span>
              <Chip tone={state.tone}>{t({ locale, key: state.label })}</Chip>
            </dd>
          </div>
        );
      })}
    </dl>
  );
}

/** The input type for a declared non-secret field. Pure. */
function inputType(field: MailProviderField): string {
  return field.type === "text" ? "text" : field.type;
}

function KeyField(props: { provider: MailProviderConfiguration; field: MailProviderField; controller: EmailProviderController; locale: string }) {
  const { provider, field, controller, locale } = props;
  const key = field.key as "token" | "username" | "baseUrl";
  const id = `email-provider-${provider.id}-${field.key}`;
  const secret = field.type === "secret";
  const replacing = secret && provider.credential.saved;
  const placeholder = replacing ? t({ locale, key: "Saved — enter a new key to replace it" }) : field.placeholder ?? field.defaultValue;
  const inputProps = {
    id,
    className: "jini-input",
    spellCheck: false,
    value: controller.drafts[provider.id]?.[key] ?? "",
    placeholder,
    onChange: (event: ChangeEvent<HTMLInputElement>) => controller.setDraftField(provider.id, key, event.target.value),
    ...agentHandle({ handle: `email-provider-${provider.id}-${agentHandleSegment({ value: field.key })}` }, { role: "field", label: `${provider.label} ${field.label}` }),
  };
  return (
    <div className="jini-field email-field">
      <label className="jini-field-label" htmlFor={id}>{field.label}</label>
      <div className="email-input-row">
        {secret ? (
          // `new-password`, not `off`, on the key: Chrome ignores `off` and silently filled the admin
          // sign-in into these fields (see `security/AccessTokensTab.tsx`'s token input).
          <SecretInput label={field.label} autoComplete="new-password" {...inputProps} />
        ) : (
          <input type={inputType(field)} autoComplete="off" {...inputProps} />
        )}
      </div>
      {field.help ? <span className="jini-field-hint">{field.help}</span> : null}
    </div>
  );
}

type CardProps = { provider: MailProviderConfiguration; controller: EmailProviderController; locale: string };

function ProviderChips({ provider, locale }: CardProps) {
  const active = provider.lanes.length > 0;
  const saved = provider.credential.saved;
  return (
    <div className="email-row">
      <strong className="email-provider-name">{provider.label}</strong>
      {active ? <Chip tone="ok">{t({ locale, key: isFullyActive(provider) ? "Active" : "Active for one lane" })}</Chip> : null}
      {provider.credential.required ? <Chip tone={saved ? "ok" : "warning"}>{t({ locale, key: saved ? "Key saved" : "Key not saved" })}</Chip> : null}
      {provider.hosted ? null : <Chip tone="neutral">{t({ locale, key: "Local only" })}</Chip>}
    </div>
  );
}

function ProviderKeyForm({ provider, controller, locale }: CardProps) {
  const fields = provider.credential.required ? provider.setup.fields : [];
  if (fields.length === 0) return null;
  const updatedAt = provider.credential.saved ? provider.credential.updatedAt : undefined;
  return (
    <form className="email-provider-form" onSubmit={(event) => { event.preventDefault(); void controller.saveKey(provider); }}>
      {updatedAt ? <span className="jini-field-hint">{t({ locale, key: "Key updated {when}" }).replace("{when}", when(updatedAt, locale))}</span> : null}
      {fields.map((field) => <KeyField key={field.key} provider={provider} field={field} controller={controller} locale={locale} />)}
      <div className="email-row">
        <button type="submit" className="btn-secondary" disabled={controller.busyId === provider.id}
          {...agentHandle({ handle: `email-provider-${provider.id}-save` }, { role: "button", label: `Save the ${provider.label} key` })}>
          {t({ locale, key: provider.credential.saved ? "Replace key" : "Save key" })}
        </button>
        {provider.setup.helpUrl ? <a href={provider.setup.helpUrl} target="_blank" rel="noreferrer">{t({ locale, key: "Where do I get a key?" })}</a> : null}
      </div>
    </form>
  );
}

function ProviderSwitch({ provider, controller, locale }: CardProps) {
  if (isFullyActive(provider)) return null;
  return (
    <>
      {/* MOVE: Credential presence is structured state; refusal text contains server internals. */}
      {provider.selectable || !provider.refusal ? null : <span className="jini-field-hint">{t({ locale, key: provider.credential.required && !provider.credential.saved ? "Add this provider's key first." : "Not set up" })}</span>}
      <div className="email-row">
        <button type="button" disabled={controller.busyId === provider.id || !provider.selectable} onClick={() => controller.askSwitch(provider)}
          {...agentHandle({ handle: `email-provider-${provider.id}-use` }, { role: "button", label: `Send all mail with ${provider.label}` })}>
          {t({ locale, key: "Use this provider" })}
        </button>
      </div>
    </>
  );
}

function ProviderNoticeLine({ provider, controller, locale }: CardProps) {
  const notice = controller.notice;
  if (notice?.providerId !== provider.id) return null;
  const error = notice.tone === "error";
  return <p className={error ? "jini-field-error" : "jini-field-hint"} role={error ? "alert" : "status"}>{t({ locale, key: notice.text })}</p>;
}

function ProviderCard(props: CardProps) {
  return (
    <li className="email-provider" {...agentHandle({ handle: `email-provider-${props.provider.id}` }, { role: "region", label: `Mail provider ${props.provider.label}` })}>
      <ProviderChips {...props} />
      <ProviderKeyForm {...props} />
      <ProviderSwitch {...props} />
      <ProviderNoticeLine {...props} />
    </li>
  );
}

/**
 * The card to show: `selectedId` when installed, else the provider sending all mail, else one
 * sending some, else the first. Pure.
 */
export function shownProviderId(providers: readonly MailProviderConfiguration[], selectedId: string | null | undefined): string | undefined {
  const pick = providers.find((p) => p.id === selectedId) ?? providers.find(isFullyActive) ?? providers.find((p) => p.lanes.length > 0) ?? providers[0];
  return pick?.id;
}

/**
 * A segment's name: the provider's label without a trailing "(…)" aside — "Console (local
 * development, sends nothing)" reads as "Console"; the card keeps the full label. Pure.
 */
export function segmentLabel(label: string): string {
  return label.replace(/\s*\([^()]*\)\s*$/, "") || label;
}

export const ADD_PROVIDER_PART = "_add-provider";
export const CAPABILITIES_PART = "_capabilities";

function AddProvider(props: { controller: EmailProviderController; locale: string; onSelect?: ((id: string) => void) | undefined }) {
  const { controller, locale } = props;
  const select = (id: string | undefined) => { if (id) props.onSelect?.(id); };
  return (
    <>
      {controller.addError ? <div className="email-row" role="alert">
        <span className="jini-field-error">{t({ locale, key: controller.addError })}</span>
        <button type="button" className="btn-secondary" disabled={controller.adding !== null} onClick={() => void controller.retryAdd().then(select)}
          {...agentHandle({ handle: "email-add-provider-retry" }, { role: "button", label: "Retry adding an email provider" })}>{t({ locale, key: "Retry" })}</button>
      </div> : null}
      {controller.choices === null && !controller.addError ? <p className="jini-field-hint" role="status">{t({ locale, key: "Loading…" })}</p> : (
        <ul className="email-list">
          {controller.choices?.map((plugin) => <li key={plugin.pluginId} className="email-row">
            <span className="email-provider-name">{agentPluginDisplayName(plugin)}</span>
            <span className="jini-field-hint">{plugin.summary ?? plugin.description}</span>
            <button type="button" disabled={controller.adding !== null} onClick={() => void controller.addProvider({ pluginId: plugin.pluginId }).then(select)}
              {...agentHandle({ handle: `email-add-provider-${plugin.pluginId}` }, { role: "button", label: `Add ${agentPluginDisplayName(plugin)} as an email provider` })}>
              {t({ locale, key: controller.adding === plugin.pluginId ? "Adding…" : "Add" })}
            </button>
          </li>)}
          {controller.choices?.length === 0 && !controller.addError ? <li className="jini-field-hint">{t({ locale, key: "No more email providers to add." })}</li> : null}
        </ul>
      )}
    </>
  );
}

function ProviderCards(props: { providers: readonly MailProviderConfiguration[]; controller: EmailProviderController; status: AdminMailStatus | null; locale: string; selectedId?: string | null | undefined; onSelect?: ((id: string) => void) | undefined }) {
  const { providers, controller, locale } = props;
  const shownId = props.selectedId === ADD_PROVIDER_PART || props.selectedId === CAPABILITIES_PART ? props.selectedId : shownProviderId(providers, props.selectedId) ?? ADD_PROVIDER_PART;
  const items = [...providers.map((p) => ({ key: p.id, label: segmentLabel(p.label) })),
    { key: ADD_PROVIDER_PART, label: t({ locale, key: "+ Add provider" }) }, { key: CAPABILITIES_PART, label: t({ locale, key: "Capabilities" }) }];
  return (
    <>
      <Segments name="email-provider-pick" label={t({ locale, key: "Provider" })} active={shownId} onSelect={(id) => props.onSelect?.(id)} items={items} />
      {shownId === CAPABILITIES_PART ? <Lanes status={props.status} providers={providers} locale={locale} /> : null}
      {shownId === ADD_PROVIDER_PART ? <AddProvider controller={controller} locale={locale} onSelect={props.onSelect} /> : null}
      <ul className="email-list email-providers">
        {providers.filter((p) => p.id === shownId).map((provider) => <ProviderCard key={provider.id} provider={provider} controller={controller} locale={locale} />)}
      </ul>
    </>
  );
}

export function EmailProviderTab(props: { controller: EmailProviderController; status: AdminMailStatus | null; locale: string; selectedId?: string | null | undefined; onSelect?: ((id: string) => void) | undefined }) {
  const { controller, locale } = props;
  const pending = controller.pendingSwitch;
  return (
    <Section id="provider" title={t({ locale, key: "Provider" })} hideTitle>
      {controller.addWarning ? <p className="jini-field-hint" role="status">{controller.addWarning}</p> : null}
      <Loaded view={controller.view} locale={locale} retry={controller.reload}>
        {(report) => (
          <>
            <ProviderCards providers={report.providers} controller={controller} status={props.status} locale={locale} selectedId={props.selectedId} onSelect={props.onSelect} />
            {report.refusals.length > 0 ? (
              <>
                <h3 className="jini-field-label email-subhead">{t({ locale, key: "Not loaded" })}</h3>
                <ul className="email-list">
                  {report.refusals.map((reason) => <li key={reason} className="jini-field-hint">{reason}</li>)}
                </ul>
              </>
            ) : null}
          </>
        )}
      </Loaded>
      <ConfirmDialog
        open={pending !== null}
        agentHandle="email-provider-switch"
        title={t({ locale, key: "Switch email provider?" })}
        body={<p>{t({ locale, key: "All email — sign-in links, confirmations, notifications and newsletters — will send with {provider}." }).replace("{provider}", pending?.label ?? "")}</p>}
        confirmLabel={t({ locale, key: "Switch" })}
        pending={pending !== null && controller.busyId === pending.id}
        onConfirm={() => void controller.confirmSwitch()}
        onCancel={() => controller.askSwitch(null)}
      />
    </Section>
  );
}

import { agentHandle } from "@jini-ai/agentic";

import { t } from "./email-i18n";
import type { MailDnsRecordStatus, MailDnsStatus } from "./email-api";
import { Chip, CopyButton, Loaded, Section, when, type Tone } from "./EmailParts";
import type { EmailSenderController } from "./hooks/use-email-sender.hooks";

/**
 * @file The Sender & DNS tab: the From name and address (saved settings; the next email uses
 * them), then the sender domain's DNS records with copy buttons and **Check again**. "Unknown" is
 * never shown as a failure; the provider's own verdict is shown apart from the DNS answers. The page
 * shows one card at a time (`part`, from its segmented pill); with no `part` both render.
 */

const RECORD_STATUS: Record<MailDnsRecordStatus, { tone: Tone; label: string }> = {
  Matches: { tone: "ok", label: "Matches" },
  Missing: { tone: "error", label: "Missing" },
  Mismatch: { tone: "error", label: "Mismatch" },
  Pending: { tone: "warning", label: "Pending" },
  Checking: { tone: "neutral", label: "Checking" },
  Unknown: { tone: "neutral", label: "Unknown" },
  TimedOut: { tone: "neutral", label: "Timed out" },
};

const PROVIDER_VERDICT: Record<string, { tone: Tone; label: string }> = {
  verified: { tone: "ok", label: "Verified by the provider" },
  pending: { tone: "warning", label: "The provider is still verifying" },
  failed: { tone: "error", label: "The provider could not verify it" },
  not_found: { tone: "warning", label: "Not added at the provider yet" },
};

/** Why there is no record table, in plain words. */
const STATE_LINE: Record<MailDnsStatus["state"], string> = {
  checked: "",
  no_sender: "Set a From address first.",
  no_provider: "Choose a provider first.",
  verification_unavailable: "DNS verification is unavailable for this provider.",
  requirements_unavailable: "The provider can't be asked for its records right now.",
  requirements_failed: "The provider answered with an error.",
  check_failed: "The records are known, but the check couldn't run.",
};

/** States whose line already says what the server's `message` says — showing both repeated it. */
const LINE_SAYS_IT_ALL: ReadonlySet<MailDnsStatus["state"]> = new Set(["no_sender", "no_provider", "verification_unavailable"]);

function SenderForm(props: { controller: EmailSenderController; locale: string }) {
  const { controller, locale } = props;
  const state = controller.saveState;
  return (
    <form className="email-provider-form" onSubmit={(event) => { event.preventDefault(); void controller.save(); }}>
      <div className="jini-field email-field">
        <label className="jini-field-label" htmlFor="email-sender-name">{t({ locale, key: "Name" })}</label>
        <input id="email-sender-name" className="jini-input" value={controller.draft.name} onChange={(e) => controller.setDraft({ name: e.target.value })}
          placeholder={t({ locale, key: "Your site's name" })} {...agentHandle({ handle: "email-sender-name" }, { role: "field", label: "Sender display name" })} />
      </div>
      <div className="jini-field email-field">
        <label className="jini-field-label" htmlFor="email-sender-email">{t({ locale, key: "From address" })}</label>
        <input id="email-sender-email" className="jini-input" type="email" value={controller.draft.email} onChange={(e) => controller.setDraft({ email: e.target.value })}
          placeholder="hello@example.com" aria-invalid={typeof state === "object"} {...agentHandle({ handle: "email-sender-email" }, { role: "field", label: "Sender From address" })} />
      </div>
      <div className="email-row">
        <button type="submit" disabled={!controller.dirty || state === "saving"} {...agentHandle({ handle: "email-sender-save" }, { role: "button", label: "Save the sender" })}>
          {state === "saving" ? t({ locale, key: "Saving…" }) : t({ locale, key: "Save" })}
        </button>
        {state === "saved" ? <span className="jini-field-hint" role="status">{t({ locale, key: "Saved" })}</span> : null}
        {typeof state === "object" ? <span className="jini-field-error" role="alert">{t({ locale, key: state.error })}</span> : null}
      </div>
    </form>
  );
}

function Records(props: { dns: NonNullable<MailDnsStatus["dns"]>; locale: string }) {
  const { dns, locale } = props;
  if (dns.records.length === 0) return <p className="jini-field-hint">{t({ locale, key: "This provider needs no DNS records." })}</p>;
  return (
    <ul className="email-list email-dns">
      {dns.records.map((record, index) => {
        const status = RECORD_STATUS[record.status] ?? { tone: "neutral" as const, label: record.status };
        const key = `${record.type}-${record.host}-${index}`;
        return (
          <li key={key} className="email-dns-record">
            <div className="email-row">
              <Chip tone={status.tone}>{t({ locale, key: status.label })}</Chip>
              <strong>{record.type}</strong>
              {record.priority !== undefined ? <span className="jini-field-hint">{t({ locale, key: "Priority" })} {record.priority}</span> : null}
            </div>
            <dl className="email-dns-values">
              <div className="email-dns-value">
                <dt className="jini-field-label">{t({ locale, key: "Host" })}</dt>
                <dd><code>{record.host}</code><CopyButton text={record.host} label={t({ locale, key: "{type} host" }).replace("{type}", record.type)} locale={locale} handle={`email-dns-${index}-copy-host`} /></dd>
              </div>
              <div className="email-dns-value">
                <dt className="jini-field-label">{t({ locale, key: "Value" })}</dt>
                <dd><code>{record.expected}</code><CopyButton text={record.expected} label={t({ locale, key: "{type} value" }).replace("{type}", record.type)} locale={locale} handle={`email-dns-${index}-copy-value`} /></dd>
              </div>
              {record.status === "Mismatch" && record.observed.length > 0 ? (
