            )}
          </>
        )}
      </Loaded>
    </div>
  );
}

import { useCallback, useMemo, useState } from "react";

import { ApiError } from "@/lib/api";
import { emailApi, type EmailApi, type MailTestSendResult, type MailUseRow } from "../email-api";
import { errorMessage, useLoad, type LoadView } from "./email-load.hooks";

/**
 * @file Overview tab state beyond the status read: **What uses email** (`GET …/mail-uses`) and
 * **Send test email** (`POST …/mail-test-send`). The click is the confirmation; one request id per
 * click makes a retried request replay instead of sending twice. A blank recipient means the
 * signed-in operator's own address (the server's default).
 */

export type TestSendState =
  | { kind: "idle" }
  | { kind: "sending" }
  | { kind: "done"; result: MailTestSendResult }
  | { kind: "error"; message: string };

export interface EmailOverviewController {
  uses: LoadView<{ checkedAt: string; uses: MailUseRow[] }>;
  reloadUses: () => void;
  to: string;
  setTo: (value: string) => void;
  test: TestSendState;
  sendTest: () => Promise<void>;
}

/** A fresh idempotency key for one click (8-64 of `[A-Za-z0-9_-]`). */
export function newRequestId(): string {
  const random = typeof crypto !== "undefined" && "randomUUID" in crypto ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return random.replace(/[^A-Za-z0-9_-]/g, "").slice(0, 64).padEnd(8, "0");
}

/**
 * @param required.api - the Email API port; a fake in tests.
 * @param optional.requestId - the id factory; fixed in tests.
 */
export function useEmailOverview(required: { api: Pick<EmailApi, "readUses" | "sendTest"> }, optional: { requestId?: () => string } = {}): EmailOverviewController {
  const { api } = required;
  const makeId = optional.requestId ?? newRequestId;
  const load = useCallback(() => api.readUses(), [api]);
  const { view: uses, reload: reloadUses } = useLoad({ load });
  const [to, setTo] = useState("");
  const [test, setTest] = useState<TestSendState>({ kind: "idle" });

  const sendTest = useCallback(async () => {
    setTest({ kind: "sending" });
    try {
      const answer = await api.sendTest({ to: to.trim() || undefined, requestId: makeId() });
      setTest({ kind: "done", result: answer.result });
      reloadUses();
    } catch (error) {
      // 429 still carries the truthful result (duplicate or rate limited): show it, not a bare error.
      const result = error instanceof ApiError ? (error.body?.result as MailTestSendResult | undefined) : undefined;
      setTest(result ? { kind: "done", result } : { kind: "error", message: errorMessage(error) });
    }
  }, [api, to, makeId, reloadUses]);

  return useMemo(() => ({ uses, reloadUses, to, setTo, test, sendTest }), [uses, reloadUses, to, test, sendTest]);
}

/** The real API port. */
export function useWiredEmailOverview(): EmailOverviewController {
  return useEmailOverview({ api: emailApi });
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";

import { api as pluginsApi, type AdminAgentPlugin } from "../../../lib/api";

import { emailApi, type EmailApi, type MailProviderConfiguration, type MailProviderConfigurationReport, type MailProviderCredentialInput } from "../email-api";
import { errorMessage, useLoad, type LoadView } from "./email-load.hooks";

/**
 * @file Provider tab state: the installed providers (`GET …/mail-providers`), a key form per
 * provider (`PUT …/:id/credential` — saves or rotates WITHOUT switching), and the switch
 * (`POST …/:id/activate`, which moves both lanes). Everything shown comes from the providers'
 * own declared setup fields; nothing here names a vendor.
 */

export type ProviderNotice = { providerId: string; tone: "ok" | "error"; text: string } | null;

export interface EmailProviderController {
  choices: AdminAgentPlugin[] | null;
  adding: string | null;
  addError: string | null;
  addWarning: string | null;
  retryAdd: () => Promise<string | undefined>;
  addProvider: (required: { pluginId: string }) => Promise<string | undefined>;
  view: LoadView<MailProviderConfigurationReport>;
  reload: () => void;
  drafts: Record<string, MailProviderCredentialInput>;
  setDraftField: (providerId: string, key: keyof MailProviderCredentialInput, value: string) => void;
  busyId: string | null;
  notice: ProviderNotice;
  saveKey: (provider: MailProviderConfiguration) => Promise<void>;
  /** The provider waiting for the switch confirmation, or null. */
  pendingSwitch: MailProviderConfiguration | null;
  askSwitch: (provider: MailProviderConfiguration | null) => void;
  confirmSwitch: () => Promise<void>;
}

/** Email orchestration only; the Plugins API owns activation and trust checks. */
type PluginApi = Pick<typeof pluginsApi, "listAgentPlugins" | "setAgentPluginEnabled">;
function useProviderChoices(required: { pluginApi: PluginApi; refresh: () => Promise<MailProviderConfigurationReport> }, _optional = {}) {
  const { pluginApi, refresh } = required;
  const [choices, setChoices] = useState<AdminAgentPlugin[] | null>(null);
  const [addError, setAddError] = useState<string | null>(null);
  const [addWarning, setAddWarning] = useState<string | null>(null);
  const [adding, setAdding] = useState<string | null>(null);
  const [attempt, setAttempt] = useState(0);
  const locked = useRef(false);
  const lastPlugin = useRef<string | null>(null);
  useEffect(() => {
    let live = true;
    pluginApi.listAgentPlugins().then(({ agentPlugins }) => {
      if (live) setChoices(agentPlugins.filter((p) => !p.enabled && p.provides?.includes("outbound-mail")));
    }, (error: unknown) => { if (live) setAddError(errorMessage(error)); });
    return () => { live = false; };
  }, [pluginApi, attempt]);
  const addProvider = useCallback(async ({ pluginId }: { pluginId: string }, _optional = {}) => {
    if (locked.current) return;
    locked.current = true;
    lastPlugin.current = pluginId;
    setAdding(pluginId);
    setAddError(null);
    setAddWarning(null);
    try {
      const { warnings } = await pluginApi.setAgentPluginEnabled(pluginId, { enabled: true });
      setAddWarning(warnings?.join(" ") || null);
      const report = await refresh();
      const provider = report.providers.find((p) => p.pluginId === pluginId);
      if (!provider) throw new Error(report.refusals.filter((reason) => reason.includes(`from '${pluginId}'`)).join("; ") || "The plugin did not load an email provider.");
      setChoices((rows) => rows?.filter((p) => p.pluginId !== pluginId) ?? null);
      return provider.id;
    } catch (error) {
      setAddError(error instanceof Error ? error.message : errorMessage(error));
    } finally {
      locked.current = false;
      setAdding(null);
    }
  }, [pluginApi, refresh]);
  const retryAdd = useCallback(async () => {
    if (lastPlugin.current) return addProvider({ pluginId: lastPlugin.current });
    setAddError(null); setAttempt((n) => n + 1);
  }, [addProvider]);
  return useMemo(() => ({ choices, adding, addError, addWarning, retryAdd, addProvider }), [choices, adding, addError, addWarning, retryAdd, addProvider]);
}

/** Whether a provider already sends both lanes (nothing left to switch). Pure. */
export function isFullyActive(provider: MailProviderConfiguration): boolean {
  return provider.lanes.includes("transactional") && provider.lanes.includes("bulk");
}

/** The body a key save sends: trimmed, blank parts left out (a rotation may change just one). Pure. */
export function credentialBody(draft: MailProviderCredentialInput | undefined): MailProviderCredentialInput {
  const out: MailProviderCredentialInput = {};
  for (const key of ["token", "username", "baseUrl"] as const) {
    const value = draft?.[key]?.trim();
    if (value) out[key] = value;
  }
  return out;
}

/**
 * @param required.api - the Email API port; a fake in tests.
 * @param optional.onChanged - called after a save or switch so the page's status re-reads.
 */
export function useEmailProvider(required: { api: Pick<EmailApi, "listProviders" | "saveProviderKey" | "activateProvider">; pluginApi: PluginApi }, optional: { onChanged?: () => void } = {}): EmailProviderController {
  const { api } = required;
  const { onChanged } = optional;
  const load = useCallback(() => api.listProviders(), [api]);
  const { view, reload, setData } = useLoad({ load });
  const refresh = useCallback(async () => { const report = await api.listProviders(); setData(report); return report; }, [api, setData]);
  const additions = useProviderChoices({ pluginApi: required.pluginApi, refresh });
  const [drafts, setDrafts] = useState<Record<string, MailProviderCredentialInput>>({});
  const [busyId, setBusyId] = useState<string | null>(null);
  const [notice, setNotice] = useState<ProviderNotice>(null);
  const [pendingSwitch, setPendingSwitch] = useState<MailProviderConfiguration | null>(null);

  const setDraftField = useCallback((providerId: string, key: keyof MailProviderCredentialInput, value: string) => {
    setDrafts((all) => ({ ...all, [providerId]: { ...all[providerId], [key]: value } }));
    // Typing answers "Enter the key first." — drop that hint so it doesn't linger next to a filled field.
    setNotice((current) => (current?.providerId === providerId && current.text === "Enter the key first." ? null : current));
  }, []);

  const saveKey = useCallback(async (provider: MailProviderConfiguration) => {
    const body = credentialBody(drafts[provider.id]);
    if (!provider.credential.saved && !body.token) {
      setNotice({ providerId: provider.id, tone: "error", text: "Enter the key first." });
      return;
    }
    setBusyId(provider.id);
    setNotice(null);
    try {
      await api.saveProviderKey({ providerId: provider.id, input: body });
      setDrafts((all) => ({ ...all, [provider.id]: {} }));
      setNotice({ providerId: provider.id, tone: "ok", text: "Key saved." });
      reload();
      onChanged?.();
    } catch (error) {
      setNotice({ providerId: provider.id, tone: "error", text: errorMessage(error) });
    } finally {
      setBusyId(null);
    }
  }, [api, drafts, reload, onChanged]);

  const confirmSwitch = useCallback(async () => {
    const provider = pendingSwitch;
    if (!provider) return;
    setBusyId(provider.id);
    setNotice(null);
    try {
      await api.activateProvider({ providerId: provider.id });
      setNotice({ providerId: provider.id, tone: "ok", text: "Now sending with this provider." });
      reload();
      onChanged?.();
    } catch (error) {
      setNotice({ providerId: provider.id, tone: "error", text: errorMessage(error) });
    } finally {
      setBusyId(null);
      setPendingSwitch(null);
    }
  }, [api, pendingSwitch, reload, onChanged]);

  return useMemo(() => ({
    ...additions, view, reload, drafts, setDraftField, busyId, notice, saveKey, pendingSwitch, askSwitch: setPendingSwitch, confirmSwitch,
  }), [additions, view, reload, drafts, setDraftField, busyId, notice, saveKey, pendingSwitch, confirmSwitch]);
}

/** The real API port. */
export function useWiredEmailProvider(optional: { onChanged?: () => void } = {}): EmailProviderController {
  return useEmailProvider({ api: emailApi, pluginApi: pluginsApi }, optional);
}

import { useCallback, useEffect, useMemo, useState } from "react";

import { emailApi, type EmailApi, type MailDnsStatus } from "../email-api";
import { errorMessage, useLoad, type LoadView } from "./email-load.hooks";

/**
 * @file Sender & DNS tab state. The sender is two ordinary settings (`core.mail.senderName`,
 * `core.mail.senderEmail`, `features/settings/mail-sender.ts`) saved with the settings API; the
 * next email uses them. DNS is `GET …/mail-dns` on open and `POST …/mail-dns/verify` for
 * **Check again** — neither changes DNS.
 */

export interface SenderValues {
  name: string;
  email: string;
}

export type SaveState = "idle" | "saving" | "saved" | { error: string };

export interface EmailSenderController {
  sender: LoadView<SenderValues>;
  draft: SenderValues;
  setDraft: (next: Partial<SenderValues>) => void;
  dirty: boolean;
  save: () => Promise<void>;
  saveState: SaveState;
  dns: LoadView<MailDnsStatus>;
  checking: boolean;
  checkError: string | null;
  checkAgain: () => Promise<void>;
}

const ADDRESS = /^[^\s@<>()[\]",;:\\]+@[^\s@<>()[\]",;:\\]+\.[^\s@<>()[\]",;:\\]+$/;

/** A plain address or blank (blank = not configured). Pure. */
export function isValidSenderEmail(value: string): boolean {
  const trimmed = value.trim();
  return trimmed === "" || ADDRESS.test(trimmed);
}

/** The sender from the effective-settings rows; anything non-string reads as blank. Pure. */
export function readSenderRows(rows: readonly { key: string; value: unknown }[]): SenderValues {
  const value = (key: string) => {
    const found = rows.find((row) => row.key === key)?.value;
    return typeof found === "string" ? found : "";
  };
  return { name: value("senderName"), email: value("senderEmail") };
}

/**
 * @param required.api - the Email API port; a fake in tests.
 * @param optional.onChanged - called after a save so the page's status re-reads.
 */
export function useEmailSender(required: { api: Pick<EmailApi, "readSender" | "saveSender" | "readDns" | "verifyDns"> }, optional: { onChanged?: () => void } = {}): EmailSenderController {
  const { api } = required;
  const { onChanged } = optional;
  const loadSender = useCallback(async () => readSenderRows((await api.readSender()).data), [api]);
  const { view: sender, setData: setSender } = useLoad({ load: loadSender });
  const loadDns = useCallback(() => api.readDns(), [api]);
  const { view: dns, setData: setDns, reload: reloadDns } = useLoad({ load: loadDns });
  const [draft, setDraftState] = useState<SenderValues>({ name: "", email: "" });
  const [saveState, setSaveState] = useState<SaveState>("idle");
  const [checking, setChecking] = useState(false);
  const [checkError, setCheckError] = useState<string | null>(null);

  const saved = sender.kind === "loaded" ? sender.data : null;
  useEffect(() => { if (saved) setDraftState(saved); }, [saved]);
  const dirty = saved !== null && (draft.name.trim() !== saved.name || draft.email.trim() !== saved.email);

  const setDraft = useCallback((next: Partial<SenderValues>) => {
    setDraftState((current) => ({ ...current, ...next }));
    setSaveState("idle");
  }, []);

  const save = useCallback(async () => {
    if (!saved) return;
    if (!isValidSenderEmail(draft.email)) {
      setSaveState({ error: "Enter one email address, like hello@example.com." });
      return;
    }
    setSaveState("saving");
    const next = { name: draft.name.trim(), email: draft.email.trim() };
    try {
      if (next.name !== saved.name) await api.saveSender({ key: "senderName", value: next.name });
      if (next.email !== saved.email) await api.saveSender({ key: "senderEmail", value: next.email });
      setSender(next);
      setSaveState("saved");
      reloadDns();
      onChanged?.();
    } catch (error) {
      setSaveState({ error: errorMessage(error) });
    }
  }, [api, draft, saved, setSender, reloadDns, onChanged]);

  const checkAgain = useCallback(async () => {
    setChecking(true);
    setCheckError(null);
    try {
      setDns(await api.verifyDns());
    } catch (error) {
      setCheckError(errorMessage(error));
    } finally {
      setChecking(false);
    }
  }, [api, setDns]);

  return useMemo(() => ({ sender, draft, setDraft, dirty, save, saveState, dns, checking, checkError, checkAgain }),
    [sender, draft, setDraft, dirty, save, saveState, dns, checking, checkError, checkAgain]);
}

/** The real API port. */
export function useWiredEmailSender(optional: { onChanged?: () => void } = {}): EmailSenderController {
  return useEmailSender({ api: emailApi }, optional);
}

import { useCallback, useEffect, useMemo, useState } from "react";

import { ApiError } from "@/lib/api";
import { emailApi, type EmailApi, type EmailTemplateDetail, type EmailTemplatePreview } from "../email-api";
import { errorMessage, useLoad, type LoadView } from "./email-load.hooks";

/**
 * @file One email template's editor page state: the raw HTML working copy, `{{field}}` fill-in
 * values (seeded from the template's declared samples), a debounced live preview of the UNSAVED
 * HTML (`POST …/email-templates/preview`), Save (`PUT …/:id/html`, conditioned on the version that
 * was loaded) and Rename (`PATCH …/:id`).
 *
 * Preview modes: `admin` keeps scripts (shown only inside the sandboxed preview iframe, the Pages
 * preview's sandbox); `sent` is exactly what a mail client gets — static HTML, scripts stripped.
 */

export type PreviewMode = "admin" | "sent";

export interface EmailTemplateEditorController {
  view: LoadView<EmailTemplateDetail>;
  html: string;
  setHtml: (html: string) => void;
  dirty: boolean;
  values: Record<string, string>;
  setValue: (field: string, value: string) => void;
  /** Field names to show: declared ones first, then any the HTML uses without declaring. */
  fieldNames: string[];
  mode: PreviewMode;
  setMode: (mode: PreviewMode) => void;
  preview: { data: EmailTemplatePreview | null; error: string | null; pending: boolean };
  saving: boolean;
  saveError: string | null;
  savedAt: string | null;
  save: () => Promise<void>;
  name: string;
  setName: (name: string) => void;
  commitName: () => Promise<void>;
  renameError: string | null;
}

/** Declared fields, then undeclared ones the HTML uses, without repeats. Pure. */
export function templateFieldNames(required: { declared: readonly { name: string }[]; undeclared: readonly string[] }): string[] {
  return [...new Set([...required.declared.map((field) => field.name), ...required.undeclared])];
}

/** The friendly line for a save failure; a 409 means someone else saved first. Pure. */
export function saveFailureText(error: unknown): string {
  if (error instanceof ApiError && error.status === 409) return "Someone else changed this template. Reload to get their version; copy your edits first.";
  return errorMessage(error);
}

/**
 * @param required.api - the Email API port; a fake in tests.
 * @param required.id - the template id from the route.
 * @param optional.debounceMs - preview settle time; 0 in tests.
 */
export function useEmailTemplateEditor(
  required: { api: Pick<EmailApi, "getTemplate" | "saveTemplateHtml" | "renameTemplate" | "previewTemplate">; id: string },
  optional: { debounceMs?: number } = {},
): EmailTemplateEditorController {
  const { api, id } = required;
  const debounceMs = optional.debounceMs ?? 400;
  const { view, setData } = useLoad({ load: useCallback(() => api.getTemplate({ id }), [api, id]) });
  const detail = view.kind === "loaded" ? view.data : null;
  const [html, setHtml] = useState("");
  const [values, setValues] = useState<Record<string, string>>({});
  const [mode, setMode] = useState<PreviewMode>("admin");
  const [preview, setPreview] = useState<EmailTemplateEditorController["preview"]>({ data: null, error: null, pending: true });
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);
  const [savedAt, setSavedAt] = useState<string | null>(null);
  const [name, setName] = useState("");
  const [renameError, setRenameError] = useState<string | null>(null);

  // Seed the working copy once per loaded template (not on every save's fresh detail).
  const loadedId = detail?.id ?? null;
  useEffect(() => {
    if (!detail) return;
    setHtml(detail.html);
    setName(detail.name);
    setValues(Object.fromEntries(detail.fields.map((field) => [field.name, field.sample ?? ""])));
    // eslint-disable-next-line react-hooks/exhaustive-deps -- keyed on the id on purpose (see above).
  }, [loadedId]);

  useEffect(() => {
    if (!loadedId) return;
    if (!html.trim()) {
      setPreview({ data: null, error: null, pending: false });
      return;
    }
    let live = true;
    setPreview((current) => ({ ...current, pending: true }));
    const timer = setTimeout(() => {
      api.previewTemplate({ html, values, mode }).then(
        (data) => { if (live) setPreview({ data, error: null, pending: false }); },
        (error: unknown) => { if (live) setPreview((current) => ({ data: current.data, error: errorMessage(error), pending: false })); },
      );
    }, debounceMs);
    return () => { live = false; clearTimeout(timer); };
  }, [api, loadedId, html, values, mode, debounceMs]);

  const dirty = detail !== null && html !== detail.html;
  const setValue = useCallback((field: string, value: string) => setValues((all) => ({ ...all, [field]: value })), []);
  const fieldNames = useMemo(() => templateFieldNames({
    declared: detail?.fields ?? [],
    undeclared: preview.data?.undeclaredFields ?? detail?.undeclaredFields ?? [],
  }), [detail, preview.data]);

  const save = useCallback(async () => {
    if (!detail || saving || !dirty) return;
    setSaving(true);
    setSaveError(null);
    try {
      const saved = await api.saveTemplateHtml({ id: detail.id, html, expectedVersion: detail.version });
      setData(saved);
      // The server stores its normalized copy (it trims the trailing newline), so adopt it unless the
      // owner typed more while saving; otherwise `dirty` stayed true after every save.
      setHtml((current) => (current === html ? saved.html : current));
      setSavedAt(saved.updatedAt);
    } catch (error) {
      setSaveError(saveFailureText(error));
    } finally {
      setSaving(false);
    }
  }, [api, detail, saving, dirty, html, setData]);

  const commitName = useCallback(async () => {
    if (!detail) return;
    const next = name.trim();
    if (!next || next === detail.name) {
      setName(detail.name);
      return;
    }
    setRenameError(null);
    try {
      const renamed = await api.renameTemplate({ id: detail.id, name: next, expectedVersion: detail.version });
      // Keep the working copy: a rename only changes the title and the version the next save states.
      setData({ ...detail, name: renamed.name, version: renamed.version, updatedAt: renamed.updatedAt });
    } catch (error) {
      setRenameError(saveFailureText(error));
      setName(detail.name);
    }
  }, [api, detail, name, setData]);

  return {
    view, html, setHtml, dirty, values, setValue, fieldNames, mode, setMode, preview, saving, saveError, savedAt, save, name, setName, commitName, renameError,
  };
}

/** The real API port. */
export function useWiredEmailTemplateEditor(required: { id: string }): EmailTemplateEditorController {
  return useEmailTemplateEditor({ api: emailApi, id: required.id });
}

import { useLayoutEffect, useRef, useState, type KeyboardEvent } from "react";
import { DataTable, RowMenu, type RowMenuItem } from "@jini-ai/admin/react";
import { agentHandle } from "@jini-ai/agentic";
import { FileDropzone, Toast } from "@jini-ai/ui";
import { formatTimestamp } from "@jini-ai/ui/panel-kit";
import { TabBar } from "@jini-ai/ui/tab-strip";
import type { AdminMedia } from "@/lib/api";
import { navigate } from "@/lib/router";
import { UploadIcon, goToLibraryTab, resolveLibraryTabId, resolveLibraryTabs } from "./Library.hooks";
import { useWiredLibrary, type LibraryController, type LibraryPreviewState, type LibraryUploadRow } from "./hooks/use-library.hooks";
import {
  LIBRARY_ACCEPT,
  documentExtensionSuffix,
  documentName,
  documentPreviewKind,
  documentTypeLabel,
  documentUploaderLabel,
  formatLibraryBytes,
} from "./rules";

/**
 * @file The Library screen (`/admin/library`) — markup only; state lives in
 * `hooks/use-library.hooks.ts`. Private documents for this site that the assistant can read
 * (`library_list` / `library_read`) and visitors never see. Two `?tab=` tabs: Upload and
 * Documents (owner, 2026-10-18). The Upload tab leads with an "Upload documents" button that opens
 * the drop zone's own file picker; Documents is only the list (owner, 2026-10-18).
 *
 * A thin Tovu page rather than a Jini `@jini-ai/admin/media` page: the Jini media page is parked
 * (`media-panel.ts`) and the legacy Media screen this sits beside is a Tovu feature too, so a Jini
 * version would need the parked module's ports wired first.
 *
 * Previews never run document content: Markdown renders with raw HTML off inside a scriptless,
 * network-blocked frame; text is React-escaped; PDF opens in the browser's PDF viewer from a blob
 * typed `application/pdf`; Office/iWork/RTF documents download.
 */
export interface LibraryProps {
  /** The `?tab=` query value; guarded by `resolveLibraryTabId`. */
  tabId?: string | null;
  /** Test seam; production passes nothing. */
  useLibraryHook?: () => LibraryController;
}

export function Library({ tabId, useLibraryHook = useWiredLibrary }: LibraryProps = {}) {
  const controller = useLibraryHook();
  const { t, documents, rowError, notice } = controller;
  const activeTabId = resolveLibraryTabId(tabId);
  return (
    <div className="page library-page">
      <div className="page-header">
        <div className="page-header-text">
          <p className="page-kicker">{t("Content")}</p>
          <h1 className="page-title">{t("Library")}</h1>
          <p className="page-description">{t("Private documents the assistant can read. Visitors never see them.")}</p>
        </div>
      </div>
      {rowError ? <div className="notice error" role="alert">{rowError}</div> : null}
      <TabBar
        ariaLabel={t("Library")}
        tabs={resolveLibraryTabs(t, { documentCount: documents?.length })}
        activeId={activeTabId}
        onChange={goToLibraryTab}
        containerHandle="library-tab-bar"
      />
      {activeTabId === "upload" ? <UploadTab controller={controller} /> : <DocumentsTab controller={controller} />}
      {controller.preview ? <PreviewDialog controller={controller} preview={controller.preview} /> : null}
      {/* A toast, not a banner above the tabs (owner, 2026-10-18): it confirms something the owner just
          did, so it clears itself, like the Themes trash toast. Open Trash stays inside it for restore. */}
      {notice ? (
        <Toast
          message={notice}
          role="status"
          tone="success"
          ttlMs={6000}
          actionLabel={t("Open Trash")}
          onAction={() => navigate("/trash")}
          onDismiss={controller.dismissNotice}
        />
      ) : null}
    </div>
  );
}

function uploadStatusLabel(row: LibraryUploadRow, t: (key: string) => string): string {
  switch (row.status) {
    case "waiting":
      return t("Waiting…");
    case "uploading":
      return t("Uploading…");
    case "done":
      return t("Uploaded");
    default:
      return row.error ?? t("Upload failed.");
  }
}

export function UploadTab({ controller }: { controller: LibraryController }) {
  const { t, permissions, uploads, uploadedCount, addFiles, clearUploads } = controller;
  const zoneRef = useRef<HTMLDivElement>(null);
  if (permissions.known && !permissions.canUpload) {
    return <div className="notice">{t("You don't have permission to upload documents.")}</div>;
  }
  const finished = uploads.some((row) => row.status === "done" || row.status === "failed");
  return (
    <section className="library-upload" aria-label={t("Upload")}>
      {/* Opens the drop zone's own file input, so both paths share its accept list and upload path. */}
      <button
        type="button"
        className="btn-primary library-upload-button"
        onClick={() => zoneRef.current?.querySelector<HTMLInputElement>('input[type="file"]')?.click()}
        {...agentHandle({ handle: "library-upload-documents" }, { role: "button", label: "Open the file picker to upload documents to the Library" })}
      >
        <UploadIcon />
        {t("Upload documents")}
      </button>
      <div ref={zoneRef} onDropCapture={(event) => {
        const items = Array.from(event.dataTransfer.items ?? []);
        const packages = items.map(item => item.webkitGetAsEntry?.()).filter(entry =>
          entry?.isDirectory && /\.(pages|key)$/i.test(entry.name));
        if (!packages.length) return;
        // A macOS package is a directory. Stop expansion so its internals cannot become uploads.
        event.preventDefault();
        event.stopPropagation();
        addFiles([...packages.map(entry => new File([], entry!.name)),
          ...items.map(item => item.getAsFile()).filter((file): file is File => !!file && !packages.some(entry => entry!.name === file.name))]);
      }}>
        <FileDropzone
          accept={LIBRARY_ACCEPT}
          prompt={t("Drop documents here, or click to browse")}
          helper={t("Documents: Markdown, text, PDF, Word, Excel, PowerPoint, Pages, Keynote, RTF, CSV, JSON · up to 10 MiB each")}
          onFiles={addFiles}
        />
        <p className="library-upload-warning">{t("Do not load any sensitive keys, tokens, or secrets here.")}</p>
      </div>
      {uploads.length > 0 ? (
        <ul className="library-upload-list" aria-label={t("Uploads")}>
          {uploads.map((row) => (
            <li key={row.key} className={`library-upload-row is-${row.status}`}>
              <span className="library-upload-name">{row.name}</span>
              <span className="library-upload-size">{formatLibraryBytes(row.size)}</span>
              <span className="library-upload-status" role={row.status === "failed" ? "alert" : undefined}>
                {row.status === "uploading" ? <span className="library-spinner" aria-hidden="true" /> : null}
                {uploadStatusLabel(row, t)}
              </span>
            </li>
          ))}
        </ul>
      ) : null}
      {finished ? (
        <div className="library-upload-actions">
          {uploadedCount > 0 ? (
            <button
              type="button"
              onClick={() => goToLibraryTab("documents")}
              {...agentHandle({ handle: "library-view-documents" }, { role: "button", label: "Open the Documents tab to see the uploaded documents" })}
            >
              {t("View in Documents")}
            </button>
          ) : null}
          <button type="button" className="btn-secondary" onClick={clearUploads}>
            {t("Clear list")}
          </button>
        </div>
      ) : null}
    </section>
  );
}

function downloadDocument(url: string) {
  // The original route answers `Content-Disposition: attachment`, so this saves the file and the
  // admin page stays where it is.
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.rel = "noopener";
  anchor.download = "";
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
}

export function documentMenuItems(item: AdminMedia, controller: LibraryController): RowMenuItem[] {
  const { t, permissions } = controller;
  // Download-only documents have no preview in v1, so their menu leads with Download (the name still opens the details).
  const items: RowMenuItem[] = documentPreviewKind(item) === "download"
    ? []
    : [{ key: "preview", label: t("Preview"), onSelect: () => controller.openPreview(item) }];
  items.push({ key: "download", label: t("Download"), onSelect: () => downloadDocument(controller.downloadUrl(item)) });
  if (permissions.canRename) items.push({ key: "rename", label: t("Rename"), onSelect: () => controller.rename.start(item) });
  if (permissions.canTrash) items.push({ key: "trash", label: t("Move to Trash"), tone: "warning", onSelect: () => void controller.trash(item) });
  return items;
}

function RenameField({ item, controller }: { item: AdminMedia; controller: LibraryController }) {
  const { t, rename } = controller;
  function onKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    if (event.key === "Enter") {
      event.preventDefault();
      void rename.save();
    } else if (event.key === "Escape") {
      event.preventDefault();
      rename.cancel();
    }
  }
  return (
    <span className="library-rename">
      <span className="library-rename-field">
        <input
          type="text"
          value={rename.draft}
          onChange={(event) => rename.setDraft(event.currentTarget.value)}
          onKeyDown={onKeyDown}
          aria-label={t("New name")}
          aria-invalid={rename.invalid || undefined}
          maxLength={240}
          autoFocus
        />
        <span className="library-rename-ext">{documentExtensionSuffix(item)}</span>
      </span>
      <button type="button" className="btn-primary" onClick={() => void rename.save()} disabled={rename.saving || rename.invalid}>
        {rename.saving ? t("Saving…") : t("Save")}
      </button>
      <button type="button" className="btn-secondary" onClick={rename.cancel} disabled={rename.saving}>
        {t("Cancel")}
      </button>
    </span>
  );
}

export function DocumentsTab({ controller }: { controller: LibraryController }) {
  const { t, documents, listError, userNames, trashingId } = controller;
  if (listError) return <div className="notice error">{listError}</div>;
  if (!documents) return <div className="notice">{t("Loading documents…")}</div>;
  return (
    <section className="library-documents" aria-label={t("Documents")}>
      <DataTable
        rows={documents}
        rowKey={(item) => item.id}
        label={t("Documents")}
        empty={<p className="library-documents-empty">{t("No documents yet.")}</p>}
        columns={[
          {
            key: "name",
            header: t("Name"),
            // Agent handles use the row position: ids are not handle-safe words.
            cell: (item, index) =>
              controller.rename.editingId === item.id ? (
                <RenameField item={item} controller={controller} />
              ) : (
                <button
                  type="button"
                  className="link-button library-name-button"
                  onClick={() => controller.openPreview(item)}
                  {...agentHandle({ handle: `library-doc-${index + 1}-preview` }, { role: "button", label: "Preview this document" })}
                >
                  {documentName(item)}
                </button>
              ),
          },
          { key: "type", header: t("Type"), cell: (item) => <span className="library-type">{documentTypeLabel(item)}</span> },
          { key: "size", header: t("Size"), cellClassName: "library-num", cell: (item) => formatLibraryBytes(item.byteSize) },
          { key: "uploaded", header: t("Upload date"), cellClassName: "library-num", cell: (item) => formatTimestamp({ iso: item.createdAt }, { timeZone: "local" }) },
          {
            key: "by",
            header: t("Uploaded by"),
            cell: (item) => documentUploaderLabel({ item, unknownLabel: t("Unknown") }, { userNames }),
          },
          {
            key: "actions",
            header: t("More"),
            cell: (item, index) =>
              trashingId === item.id ? (
                <span className="muted-cell">{t("Moving…")}</span>
              ) : (
                <RowMenu
                  triggerLabel={t('Actions for "{title}"').replace("{title}", documentName(item))}
                  agentHandle={`library-doc-${index + 1}-menu`}
                  items={documentMenuItems(item, controller)}
                />
              ),
          },
        ]}
      />
    </section>
  );
}

/** Builds the scriptless, network-blocked document a Markdown preview renders in. Colours come
 *  from the admin theme around the frame so light and dark both read. */
export function markdownFrameDocument(html: string, colors: { text: string; link: string; border: string }): string {
  const style = `:root{color-scheme:light dark}body{margin:0;padding:16px 20px;font:14px/1.6 system-ui,-apple-system,"Segoe UI",sans-serif;color:${colors.text};background:transparent;overflow-wrap:anywhere}a{color:${colors.link}}pre,code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:13px}pre{padding:10px 12px;border:1px solid ${colors.border};border-radius:6px;overflow:auto}table{border-collapse:collapse}th,td{border:1px solid ${colors.border};padding:4px 8px}img{max-width:100%}h1,h2,h3{line-height:1.25}blockquote{margin:0;padding-left:12px;border-left:3px solid ${colors.border}}`;
  return `<!doctype html><html><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'"><style>${style}</style></head><body>${html}</body></html>`;
}

function MarkdownFrame({ html, title }: { html: string; title: string }) {
  const hostRef = useRef<HTMLDivElement>(null);
  const [colors, setColors] = useState<{ text: string; link: string; border: string } | null>(null);
  useLayoutEffect(() => {
    // The host div always renders, and React attaches its ref before layout effects run, so the
    // ref is set here (the old `if (!host) return` guard could never fire).
    const host = hostRef.current!;
    const computed = getComputedStyle(host);
    setColors({
      text: computed.color || "CanvasText",
      link: computed.getPropertyValue("--link").trim() || computed.color || "LinkText",
      border: computed.getPropertyValue("--border").trim() || "GrayText",
    });
  }, []);
  return (
    <div ref={hostRef} className="library-preview-frame-host">
      {colors ? (
        <iframe className="library-preview-frame" title={title} sandbox="" referrerPolicy="no-referrer" srcDoc={markdownFrameDocument(html, colors)} />
      ) : null}
    </div>
  );
}

function PreviewBody({ preview, controller }: { preview: LibraryPreviewState; controller: LibraryController }) {
  const { t } = controller;
  const name = documentName(preview.item);
  if (preview.loading) return <p className="muted-cell">{t("Loading preview…")}</p>;
  if (preview.error) return <div className="notice error">{preview.error}</div>;
  if (preview.kind === "markdown" && preview.html !== null) return <MarkdownFrame html={preview.html} title={name} />;
  if (preview.kind === "text" && preview.text !== null) return <pre className="library-preview-text">{preview.text}</pre>;
  if (preview.kind === "pdf" && preview.pdfUrl) {
    // Not a sandboxed iframe: Chrome shows "This page has been blocked" for a PDF inside
    // `sandbox=""` (seen 2026-10-18). `<object>` hands the bytes to the browser's own PDF viewer;
    // the hook re-types the blob as `application/pdf`, so it can never load as an HTML page. The
    // fallback shows when the browser has no inline PDF viewer.
    return (
      <object className="library-preview-frame library-preview-pdf" title={name} type="application/pdf" data={preview.pdfUrl}>
        <p className="library-preview-none">{t("No preview for this file type. Download it to open it.")}</p>
      </object>
    );
  }
  return <p className="library-preview-none">{t("No preview for this file type. Download it to open it.")}</p>;
}

function PreviewDialog({ controller, preview }: { controller: LibraryController; preview: LibraryPreviewState }) {
  const { t, closePreview } = controller;
  const name = documentName(preview.item);
  const titleId = "library-preview-title";
  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key === "Escape") closePreview();
  }
  return (
    <div className="settings-dialog-backdrop" onClick={closePreview}>
      <div
        className="settings-dialog library-preview-dialog"
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        onClick={(event) => event.stopPropagation()}
        onKeyDown={onKeyDown}
      >
        <div className="library-preview-head">
          <div className="library-preview-heading">
            <h2 id={titleId}>{name}</h2>
            <p className="library-preview-meta">
              {documentTypeLabel(preview.item)} · {formatLibraryBytes(preview.item.byteSize)}
            </p>
          </div>
          <a className="btn-secondary library-preview-download" href={controller.downloadUrl(preview.item)} download>
            {t("Download")}
          </a>
          <button type="button" className="btn-ghost library-preview-close" aria-label={t("Close")} onClick={closePreview} autoFocus>
            <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
              <path d="M4 4l8 8M12 4l-8 8" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
            </svg>
          </button>
        </div>
        <div className="library-preview-body">
          <PreviewBody preview={preview} controller={controller} />
          {preview.truncated ? <p className="muted-cell library-preview-truncated">{t("Showing the first 64 KB. Download the file to see all of it.")}</p> : null}
        </div>
      </div>
    </div>
  );
}

import { api, type AdminMedia } from "@/lib/api";
import type { MediaPort } from "./media-port.hooks";

/**
 * @file The only place under `features/media` that reaches `lib/api` for the five `MediaPort`
 * routes — see `media-port.hooks.ts` for why the split exists.
 */

/** The live implementation, as a module-level singleton — matches `integrations/jini-admin/redirects-ports.ts`'s `redirectsHostPorts`. Each method wraps its `api` counterpart explicitly rather
 *  than pointing at it directly, so a route's default-parameter shape (`uploadMedia`'s
 *  `options = {}`, `updateMedia`'s `options = {}`) stays `lib/api.ts`'s to own. */
export const defaultMediaPort: MediaPort = {
  listMedia: () => api.listMedia(),
  uploadMedia: (input, options) => api.uploadMedia(input, options),
  updateMedia: (target, options) => api.updateMedia(target, options),
  trashMedia: (id) => api.trashMedia(id),
  deleteMedia: (id) => api.deleteMedia(id),
  // No media-specific restore route: the shared Trash restore already handles media rows.
  restoreMedia: async (id) => {
    const report = await api.restoreTrashItems({ items: [{ entityType: "media", entityId: id }] });
    return { restored: report.restored === 1 };
  },
  mediaOriginalUrl: (id) => api.mediaOriginalUrl(id),
  listUsers: () => api.listUsers(),
};

/** Seed state for {@link createFakeMediaPort}. */
export interface FakeMediaPortOptions {
  media?: AdminMedia[];
}

/**
 * An in-memory {@link MediaPort} for tests — lets a test describe "the library has these two
 * items" or "an upload with this alt text" directly, instead of hand-building `Response` objects
 * and stubbing global `fetch`. Shipped alongside the real binding per the pattern's "every port
 * gets a fake" rule.
 */
export function createFakeMediaPort(options: FakeMediaPortOptions = {}): MediaPort & {
  /** Every item currently in the fake's store, in list order. */
  readonly items: AdminMedia[];
} {
  const items = [...(options.media ?? [])];

  function newItem(input: { filename: string; contentType: string; dataBase64: string }, opts: { alt?: string; caption?: string; credit?: string }): AdminMedia {
    return {
      id: `fake-${items.length + 1}`,
      workspaceId: "fake-ws",
      status: "active",
      sha256: `fake-sha-${items.length + 1}`,
      title: input.filename,
      // Rough approximation of the real server's `slugifyMediaTitle` (`@jini-ai/cms/media`) — good
      // enough for a fake store's own uniqueness-free happy path; a test needing a REAL collision or
      // conflict must seed `options.media` directly with an explicit `slug`, same as `contentType`'s
      // own disclosed limit above.
      slug: input.filename.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "untitled",
      alt: opts.alt ?? "",
      caption: opts.caption ?? "",
      credit: opts.credit ?? "",
      width: null,
      height: null,
      cssClass: null,
      htmlAttributes: null,
      // The REAL server ignores this declared string and stores `sniffContentType(bytes)` instead
      // (see `server/routes/admin/media/upload.ts`). This fake has no bytes to sniff — its input is
      // an opaque base64 string a test made up — so it echoes what the caller declared. A test that
      // needs the two to disagree (uploading bytes whose real type differs from the declared one)
      // must seed `options.media` directly rather than rely on this path.
      contentType: input.contentType,
      publicUrl: null,
      createdAt: new Date(0).toISOString(),
      updatedAt: new Date(0).toISOString(),
      version: 1,
    };
  }

  return {
    items,

    async listMedia() {
      return { media: [...items] };
    },

    async uploadMedia(input, options = {}) {
      const created = newItem(input, options);
      items.push(created);
      return { media: created };
    },

    async updateMedia({ id }, options = {}) {
      const index = items.findIndex((item) => item.id === id);
      if (index < 0) throw new Error(`fake media not found: ${id}`);
      const updated = { ...items[index]!, ...options };
      items[index] = updated;
      return { media: updated };
    },

    async trashMedia(id) {
      const index = items.findIndex((item) => item.id === id);
      if (index < 0) throw new Error(`fake media not found: ${id}`);
      const trashed: AdminMedia = { ...items[index]!, status: "trashed" };
      items[index] = trashed;
      return { media: trashed };
    },

    async restoreMedia(id) {
      const index = items.findIndex((item) => item.id === id);
      if (index < 0) throw new Error(`fake media not found: ${id}`);
      items[index] = { ...items[index]!, status: "active" };
      return { restored: true };
    },

    async deleteMedia(id) {
      const index = items.findIndex((item) => item.id === id);
      if (index < 0) throw new Error(`fake media not found: ${id}`);
      items.splice(index, 1);
      return { purged: true };
    },

    // A distinct `fake://` scheme, not `api.mediaOriginalUrl`'s real
    // `/workspaces/.../media/.../original` shape — so a test asserting a resolved URL came from
    // THIS fake fails if a consumer ever goes back to calling the real `api` directly.
    mediaOriginalUrl(id) {
      return `fake://media-original/${id}`;
    },
  };
}

import { useEffect, useState } from "react";
import type { AdminMedia } from "@/lib/api";

const PHONE_QUERY = "(max-width: 640px)";
const matchViewport = (query: string) =>
  typeof window === "undefined" ? undefined : window.matchMedia?.(query);

/** Phone card bodies share the existing metadata action. Preview/play and row-menu controls
 * remain independent; a real title button supplies keyboard access and the CSS stretches its hit area.
 */
export function useMediaCardDetails(
  { onToggleEdit }: { onToggleEdit: (item: AdminMedia) => void },
  { matchMedia = matchViewport }: { matchMedia?: (query: string) => MediaQueryList | undefined } = {},
) {
  // Viewport detection enhances the desktop card; an unavailable query must not block the grid.
  const [isPhone, setIsPhone] = useState(() => matchMedia(PHONE_QUERY)?.matches ?? false);
  useEffect(() => {
    const query = matchMedia(PHONE_QUERY);
    const update = () => setIsPhone(query?.matches ?? false);
    update();
    if (!query) return;
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, [matchMedia]);
  return { isPhone, openDetails: onToggleEdit };
}

import { agentHandle } from "@jini-ai/agentic";
import { resolveTabBarTabIndex, useTabBarKeyboard } from "@jini-ai/ui/tab-strip";

import type { AdminMenuItem, AdminMenuItemAttrs, AdminMenuMode } from "../../lib/api";
import type { Translate } from "@jini-ai/ui/panel-kit";
import { useWiredMenuEditor, type MenuEditorController } from "./hooks/use-menu-editor.hooks";
import { useMenuItemRemove } from "./MenuEditor.hooks";
import { MenuPageLinkFields } from "./MenuPageLinkFields";
import type { MenuPageChoice } from "./page-link-rules";
import { useMenuTargetEditor } from "./MenuPageLinkFields.hooks";
export { targetForKind } from "./page-link-rules";

/**
 * @file Per-menu tree editor (ADR-029 whole-tree replace) — markup only.
 *
 * v1 scope: a simple recursive nested-list UI — each item shows its
 * label/target-kind/target-value with add-child/remove/reorder controls.
 * No drag-and-drop.
 *
 * Every piece of state and every API call lives in `hooks/use-menu-editor.hooks.ts`; see that
 * file's header for why. What stays here is `ItemRow` plus
 * `MenuItemTargetFields`/`MenuItemAttrsFields` — presentation concerns invoked directly from
 * `ItemRow`'s own markup, not part of the hook's state transitions. Target reshaping now lives in
 * `page-link-rules.ts` and `MenuPageLinkFields.hooks.ts`. `ItemRow`'s Remove-button
 * confirmation logic (`countDescendants` included) lives in the colocated `MenuEditor.hooks.tsx`
 * instead — see that file's header for why.
 *
 * `MenuItemAttrsFields` exposes `NavItemAttrs`'s five presentational fields (Jini
 * `packages/cms/src/navigation/types.ts:104-115` — `cssClass`/`description`/`icon`/`openInNewTab`/
 * `rel`) behind a per-item `<details>` disclosure. These already round-trip through storage
 * untouched (`validateAndCloneTree` in Jini's `menu-service.ts` clones each node with `{ ...node,
 * children }`, never touching `attrs`) and the static-tier theme renderer already consumed
 * `cssClass`/`icon`/`description` — this screen was simply the one gap in an otherwise-working
 * pipeline. `rel`/`openInNewTab` were not consumed by ANY render path before this change; both the
 * static-tier tree-variant renderer (`features/theme/static-render.ts`) and the widget-IR menu
 * renderer (`server/inbound/public-http/http/site/render.ts`) now honor all five fields.
 */

/**
 * `?? ""` as a named function rather than inline. ESLint's cyclomatic-complexity rule counts each
 * `??` as its own branch — six of them across {@link targetForKind} and {@link MenuItemTargetFields}
 * below (2026-08-06, complexity pass, fourth pass) inflated each function's flat 4-case switch from
 * a base of ~5 to 10, even though cognitive complexity for both is 1: no nesting, four sibling cases,
 * each a single fallback. Naming the fallback removes the count from each switch's own scope without
 * changing what either function produces — every call site still falls back to `""` for exactly the
 * same absent values it did before.
 */
function orEmpty(value: string | undefined): string {
  return value ?? "";
}

/** Boolean counterpart to {@link orEmpty}, same rationale — see {@link attrsOrDefaults}. */
function orFalse(value: boolean | undefined): boolean {
  return value ?? false;
}

/**
 * Same rationale as {@link orEmpty} above: five `attrs?.field ?? default` fallbacks inlined
 * directly in {@link MenuItemAttrsFields}'s JSX pushed its cyclomatic complexity from a base of
 * ~6 (five sibling fields + the disclosure) to 11 — each `?.` and `??` is its own branch. Naming
 * the defaulting removes that count from the component's own scope without changing what any
 * field renders; every caller still sees the same fallback for the same absent value.
 */
function attrsOrDefaults(attrs: AdminMenuItemAttrs | undefined): Required<AdminMenuItemAttrs> {
  const a = attrs ?? {};
  return {
    cssClass: orEmpty(a.cssClass),
    icon: orEmpty(a.icon),
    description: orEmpty(a.description),
    rel: orEmpty(a.rel),
    openInNewTab: orFalse(a.openInNewTab),
  };
}

/**
 * The target-kind-specific field(s) — URL/Route/Entry each show one input, Term shows two.
 * Extracted out of `ItemRow`'s four `item.target.kind === "…" ? (...) : null` blocks (its entire
 * branch count beyond the label field and the children map) into a `switch` over the same
 * target-kind union `targetForKind` (now re-exported from rules) switches on — same convention, and
 * unlike an if/else-if chain a `switch`'s cases don't nest, which is what keeps this low under
 * cognitive complexity too. Uses {@link orEmpty} for the same reason `targetForKind` above does —
 * see that function's doc.
 */
export function MenuItemTargetFields({
  item,
  path,
  onChange,
  t,
}: {
  item: AdminMenuItem;
  path: number[];
  onChange: (path: number[], fn: (item: AdminMenuItem) => AdminMenuItem) => void;
  t: Translate;
}) {
  switch (item.target.kind) {
    case "url":
      return (
        <label className="a11y-label-wrap">
          <span className="visually-hidden">URL</span>
          <input
            value={orEmpty(item.target.href)}
            placeholder="https://…"
            onChange={(e) => onChange(path, (it) => ({ ...it, target: { ...it.target, href: e.target.value } }))}
          />
        </label>
      );
    case "route":
      return (
        <label className="a11y-label-wrap">
          <span className="visually-hidden">{t("Route name")}</span>
          <input
            value={orEmpty(item.target.route)}
            placeholder={t("route name")}
            onChange={(e) => onChange(path, (it) => ({ ...it, target: { ...it.target, route: e.target.value } }))}
          />
        </label>
      );
    case "entryRef":
      return (
        <label className="a11y-label-wrap">
          <span className="visually-hidden">{t("Entry ID")}</span>
          <input
            value={orEmpty(item.target.entryId)}
            placeholder={t("entry id")}
            onChange={(e) => onChange(path, (it) => ({ ...it, target: { ...it.target, entryId: e.target.value } }))}
          />
        </label>
      );
    case "termRef":
      return (
        <>
          <label className="a11y-label-wrap">
            <span className="visually-hidden">{t("Term ID")}</span>
            <input
              value={orEmpty(item.target.termId)}
              placeholder={t("term id")}
              onChange={(e) => onChange(path, (it) => ({ ...it, target: { ...it.target, termId: e.target.value } }))}
            />
          </label>
          <label className="a11y-label-wrap">
            <span className="visually-hidden">{t("Taxonomy")}</span>
            <input
              value={orEmpty(item.target.taxonomy)}
              placeholder={t("taxonomy")}
              onChange={(e) => onChange(path, (it) => ({ ...it, target: { ...it.target, taxonomy: e.target.value } }))}
            />
          </label>
        </>
      );
  }
}

/**
 * `NavItemAttrs`'s five presentational fields, collapsed behind a `<details>` disclosure rather
 * than five more always-visible inputs on an already-dense row (label/kind/target-value/move/
 * child/remove) — see this file's own header for why they're safe to expose now. Applies
 * identically to every target kind, unlike {@link MenuItemTargetFields}'s kind-specific fields, so
 * it renders once per row rather than switching on `item.target.kind`. Native `<details>` needs no
 * open/closed state of its own (browser-managed), so this stays presentation-only, same as
 * {@link MenuItemTargetFields} above.
 */
export function MenuItemAttrsFields({
  item,
  path,
  onChange,
  t,
}: {
  item: AdminMenuItem;
  path: number[];
  onChange: (path: number[], fn: (item: AdminMenuItem) => AdminMenuItem) => void;
  t: Translate;
}) {
  const attrs = attrsOrDefaults(item.attrs);

  return (
    <details className="menu-item-advanced">
      <summary>{t("Advanced")}</summary>
      <div className="menu-item-advanced-fields">
        <label className="a11y-label-wrap">
          <span className="visually-hidden">{t("CSS class")}</span>
          <input
            value={attrs.cssClass}
            placeholder={t("CSS class")}
            onChange={(e) => onChange(path, (it) => ({ ...it, attrs: { ...it.attrs, cssClass: e.target.value } }))}
          />
        </label>
        <label className="a11y-label-wrap">
          <span className="visually-hidden">{t("Icon")}</span>
          <input
            value={attrs.icon}
            placeholder={t("Icon")}
            onChange={(e) => onChange(path, (it) => ({ ...it, attrs: { ...it.attrs, icon: e.target.value } }))}
          />
        </label>
        <label className="a11y-label-wrap">
          <span className="visually-hidden">{t("Description")}</span>
          <input
            value={attrs.description}
            placeholder={t("Description")}
            onChange={(e) => onChange(path, (it) => ({ ...it, attrs: { ...it.attrs, description: e.target.value } }))}
          />
        </label>
        <label className="a11y-label-wrap">
          <span className="visually-hidden">{t("Link rel")}</span>
          <input
            value={attrs.rel}
            placeholder={t("Link rel")}
            onChange={(e) => onChange(path, (it) => ({ ...it, attrs: { ...it.attrs, rel: e.target.value } }))}
          />
        </label>
        <label className="menu-item-advanced-checkbox">
          <input
            type="checkbox"
            checked={attrs.openInNewTab}
            onChange={(e) => onChange(path, (it) => ({ ...it, attrs: { ...it.attrs, openInNewTab: e.target.checked } }))}
          />
          {t("Open in new tab")}
        </label>
      </div>
    </details>
  );
}

function ItemRow(props: {
  pages?: readonly MenuPageChoice[];
  item: AdminMenuItem;
  path: number[];
  onChange: (path: number[], fn: (item: AdminMenuItem) => AdminMenuItem) => void;
  onRemove: (path: number[]) => void;
  onAddChild: (path: number[]) => void;
  onMove: (path: number[], direction: -1 | 1) => void;
  t: Translate;
}) {
  const { item, path, onChange, onRemove, onAddChild, onMove, t, pages } = props;
  const { handleRemoveClick } = useMenuItemRemove(item, path, onRemove);
  const targetController = useMenuTargetEditor({ item, path, onChange, pages });

  return (
    <div className="menu-item-row" style={{ marginLeft: path.length * 20 }}>
      <div className="menu-item-fields">
        {/* Audit finding: every control below was placeholder-only (or, for the `<select>`, had no
            accessible name at all — no placeholder, no label, nothing). Each now wraps in a real
            `<label>` with a `.visually-hidden` name, same fix and same reasoning as the title/slug
            fields above — see `styles/editor.css`'s `.a11y-label-wrap` comment for why the wrap
            costs no layout in this dense flex row. */}
        <label className="a11y-label-wrap">
          <span className="visually-hidden">{t("Item label")}</span>
          <input
            value={item.label ?? ""}
            placeholder={t("Label")}
            onChange={(e) => onChange(path, (it) => ({ ...it, label: e.target.value }))}
          />
        </label>
        <label className="a11y-label-wrap">
          <span className="visually-hidden">{t("Link type")}</span>
          <select
            value={targetController.kind}
            onChange={targetController.selectType}
          >
            <option value="url">{t("URL")}</option>
            <option value="route">{t("Route")}</option>
            <option value="page">{t("Page")}</option>
            <option value="entryRef">{t("Entry")}</option>
            <option value="termRef">{t("Term")}</option>
          </select>
        </label>
        {targetController.isPage
          ? <MenuPageLinkFields item={item} path={path} pages={pages} onChange={onChange} t={t} />
          : <MenuItemTargetFields item={item} path={path} onChange={onChange} t={t} />}
        {/* `aria-label` alongside `title`: `title` alone isn't reliably exposed to assistive tech
            and isn't keyboard-discoverable without a mouse hover (audit Minor finding). */}
        <button className="tb-btn" onClick={() => onMove(path, -1)} title={t("Move up")} aria-label={t("Move item up")}>
          ↑
        </button>
        <button className="tb-btn" onClick={() => onMove(path, 1)} title={t("Move down")} aria-label={t("Move item down")}>
          ↓
        </button>
        <button className="tb-btn" onClick={() => onAddChild(path)} title={t("Add child item")}>
          {t("+ child")}
        </button>
        <button
          className="tb-btn"
          // Audit Major finding: Remove previously deleted the clicked item's entire subtree in
          // one click, no confirmation, no indication children existed — hits hardest for a
          // screen-reader user, since the same indentation a sighted operator reads "this has
          // children" from (`marginLeft: path.length * 20` below) carries no structural signal
          // for them either. A leaf item (no children) stays a bare click, matching this screen's
          // own `FormFieldsEditor`-sibling "Remove" convention for low-stakes removals — see
          // `MenuEditor.hooks.tsx`'s `useMenuItemRemove` for the confirmation logic itself.
          onClick={handleRemoveClick}
          title={t("Remove item")}
          // `✕` is this button's only text content, so — unlike Move up/down above, whose glyphs
          // are at least paired with a real word via `title` alone being insufficient too — its
          // accessible name would otherwise compute to the glyph itself ("✕"/"multiplication
          // sign"), not "Remove item". Found empirically while adding this button's test:
          // `title` is never part of the accessible-name computation when text content exists.
          aria-label={t("Remove item")}
        >
          ✕
        </button>
      </div>
      <MenuItemAttrsFields item={item} path={path} onChange={onChange} t={t} />
      {(item.children ?? []).map((child, i) => (
        <ItemRow
          key={child.id}
          item={child}
          path={[...path, i]}
          onChange={onChange}
          onRemove={onRemove}
          onAddChild={onAddChild}
          onMove={onMove}
          t={t}
          pages={pages}
        />
      ))}
    </div>
  );
}

/** The "Options" | "HTML" tabs, keyed by the {@link AdminMenuMode} each one saves. `id` is what the
 *  `@jini-ai/ui/tab-strip` keyboard helpers key on — the same `.segmented` tablist PageEditor uses. */
const MODE_TABS: ReadonlyArray<{ id: AdminMenuMode; label: string }> = [{ id: "items", label: "Options" }, { id: "html", label: "HTML" }];

/**
 * The authoring-mode tablist — PageEditor's `.page-editor-toolbar` > `.segmented role=tablist` row,
 * with the shared arrow/Home/End keys and roving tab stop from `useTabBarKeyboard`.
 */
function MenuModeTabs({ mode, onChange, t }: { mode: AdminMenuMode; onChange: (mode: AdminMenuMode) => void; t: Translate }) {
  const { onKeyDown } = useTabBarKeyboard({ tabs: MODE_TABS, activeId: mode, onChange: (id) => onChange(id as AdminMenuMode) });
  return (
    <div className="page-editor-toolbar">
      <div className="segmented" role="tablist" aria-label={t("Menu editor mode")} onKeyDown={onKeyDown}>
        {MODE_TABS.map((tab) => (
          <button
            key={tab.id}
            type="button"
            role="tab"
            aria-selected={mode === tab.id}
            className={mode === tab.id ? "is-active" : undefined}
            tabIndex={resolveTabBarTabIndex({ tabs: MODE_TABS, activeId: mode, tab })}
            onClick={() => onChange(tab.id)}
            {...agentHandle({ handle: `menu-mode-${tab.id}` }, { role: "button", label: `Switch to the ${tab.label} tab` })}
          >
            {/* Literal keys, not `t(tab.label)`: the i18n parity test resolves every key statically. */}
            {t(tab.id === "html" ? "HTML" : "Options")}
          </button>
        ))}
      </div>
    </div>
  );
}

export interface MenuEditorProps {
  menuId: string | null;
  /** Dependency injection seam for tests — the same convention `@jini-ai/ui`'s `CustomSelect` uses
