/**
 * @file Everything the per-menu tree editor does, so `MenuEditor.tsx` is only markup.
 *
 * Extracted verbatim — same state, same order, same effect, same error strings. `props.menuId ===
 * null` is create mode (unsaved menu, empty tree to start); a non-null id loads and edits an
 * existing menu.
 *
 * The immutable tree operations below (`mapAtPath` … `moveAtPath`) and the `newItem` factory move
 * with the state actions they implement (`changeAt`/`removeAt`/`addChildAt`/`moveAt`/`addRootItem`).
 * `countDescendants` and `targetForKind` stay in `MenuEditor.tsx` — they're only ever called from
 * inside `ItemRow`'s own markup (confirm copy, select-driven target reshaping), not from this
 * hook's state transitions.
 *
 * Naming follows `hooks/use-settings-slice.hooks.ts` and `hooks/use-dirty-guard.hooks.ts`:
 * `use-<thing>.hooks.ts`. Feature-local because nothing outside `features/menus` needs it; promote
 * to `src/hooks/` only when a second feature actually does.
 *
 * `deps.port`/`deps.navigate` are injected (see `menus-port.hooks.ts`) rather than reaching for
 * `lib/api`'s `api` and `lib/router`'s `navigate` directly, sharing the `MenusPort`
 * `use-menus.hooks.ts` also injects.
 *
 * `deps.t` (standing i18n rule, 2026-08-11 — see `use-menus.hooks.ts`'s identical note): injected
 * so `MenuEditor.tsx` (and `ItemRow`, which it threads `t` into as a prop) source their UI copy
 * from this hook instead of their own `useAdminLocale()`/`MENUS_DICT` import. This hook's OWN error
 * strings stay hardcoded English (unchanged) — `useAdminLocale()`/`MENUS_DICT` are read only inside
 * {@link useWiredMenuEditor}.
 */

export interface MenuEditorDependencies {
  port: MenusPort;
  navigate: (path: string, options?: { replace?: boolean }) => void;
  t: Translate;
  clipboard?: { writeText: (text: string) => Promise<void> };
  /** Draft item IDs retain their browser UUID / timestamp fallback with controllable entropy. */
  itemIdSource?: {
    crypto?: Partial<Pick<Crypto, "randomUUID">>;
    nowMs: () => number;
    random: () => number;
  };
}

function newItemId({ source }: { source: NonNullable<MenuEditorDependencies["itemIdSource"]> }): string {
  return source.crypto?.randomUUID?.() ?? `item-${source.nowMs()}-${source.random().toString(36).slice(2)}`;
}

function newItem({ source }: { source: NonNullable<MenuEditorDependencies["itemIdSource"]> }): AdminMenuItem {
  return { id: newItemId({ source }), label: "", target: { kind: "url", href: "" } };
}

// ---------------------------------------------------------------------------
// Immutable tree operations over a `path` (array of sibling indices from the
// root down to the target node). The tree is bounded (menu-service.ts caps
// depth at 5, item count at 500), so plain recursive rebuilds are fine —
// no need for an index/map structure at this scale.
// ---------------------------------------------------------------------------

function mapAtPath(
  items: AdminMenuItem[],
  path: number[],
  fn: (item: AdminMenuItem) => AdminMenuItem
): AdminMenuItem[] {
  if (path.length === 0) return items;
  const [index, ...rest] = path;
  return items.map((item, i) => {
    if (i !== index) return item;
    if (rest.length === 0) return fn(item);
    return { ...item, children: mapAtPath(item.children ?? [], rest, fn) };
  });
}

function removeAtPath(items: AdminMenuItem[], path: number[]): AdminMenuItem[] {
  if (path.length === 0) return items;
  const [index, ...rest] = path;
  if (rest.length === 0) return items.filter((_, i) => i !== index);
  return items.map((item, i) =>
    i === index ? { ...item, children: removeAtPath(item.children ?? [], rest) } : item
  );
}

function addChildAtPath(items: AdminMenuItem[], path: number[], createItem: () => AdminMenuItem): AdminMenuItem[] {
  if (path.length === 0) return [...items, createItem()];
  const [index, ...rest] = path;
  return items.map((item, i) => {
    if (i !== index) return item;
    if (rest.length === 0) return { ...item, children: [...(item.children ?? []), createItem()] };
    return { ...item, children: addChildAtPath(item.children ?? [], rest, createItem) };
  });
}

function getChildrenAtPath(items: AdminMenuItem[], path: number[]): AdminMenuItem[] {
  if (path.length === 0) return items;
  const [index, ...rest] = path;
  return getChildrenAtPath(items[index]?.children ?? [], rest);
}

function moveAtPath(items: AdminMenuItem[], path: number[], direction: -1 | 1): AdminMenuItem[] {
  const parentPath = path.slice(0, -1);
  const index = path[path.length - 1];
  const siblings = getChildrenAtPath(items, parentPath);
  const target = index + direction;
  if (target < 0 || target >= siblings.length) return items;
  const reordered = [...siblings];
  [reordered[index], reordered[target]] = [reordered[target], reordered[index]];
  // Root moves replace the list itself; nested moves replace one parent's children through
  // `mapAtPath`. (A dedicated `setChildrenAtPath` walker used to do this with its own
  // `item.children ?? []` fallback, which could never run: reaching here means `siblings` had
  // `target` in range, so every ancestor on `parentPath` already has a children array.)
  if (parentPath.length === 0) return reordered;
  return mapAtPath(items, parentPath, (parent) => ({ ...parent, children: reordered }));
}

/** What `useDirtyGuard` compares — everything an operator can actually edit on this screen. */
interface MenuFormState {
  title: string;
  slug: string;
  items: AdminMenuItem[];
  mode: AdminMenuMode;
  html: string;
}

export interface MenuEditorController {
  pageChoices?: MenuPageChoice[];
  copyHtmlEmbed: () => Promise<void>;
  copyFeedback: string | null;
  isNew: boolean;
  menu: AdminMenu | null;
  title: string;
  setTitle: (title: string) => void;
  slug: string;
  setSlug: (slug: string) => void;
  items: AdminMenuItem[];
  /** The active tab: `"items"` ("Options", the tree editor) or `"html"` (raw menu markup). Save
   *  saves this mode; a menu stored in HTML mode opens on the HTML tab. */
  mode: AdminMenuMode;
  /** Switches tabs. The first switch to HTML with no markup yet seeds {@link menuHtmlStarter} from
   *  the current items (forms' `changeMode` rule); the other mode's data is never cleared. */
  changeMode: (mode: AdminMenuMode) => void;
  html: string;
  setHtml: (html: string) => void;
  message: string | null;
  error: string | null;
  loading: boolean;
  confirmLeave: () => boolean;
  changeAt: (path: number[], fn: (item: AdminMenuItem) => AdminMenuItem) => void;
  removeAt: (path: number[]) => void;
  addChildAt: (path: number[]) => void;
  moveAt: (path: number[], direction: -1 | 1) => void;
  addRootItem: () => void;
  save: () => Promise<void>;
  /**
   * Whether a Save request is currently in flight (S4a, 2026-09-20) — the button had no `disabled`
   * at all, unlike Pages/Posts' twin `saving` field (`PageEditorController.saving`,
   * `PostEditorController.saving` from the same pass, `use-post-editor.hooks.ts` M4). A double click
   * sent two `updateMenuTree` calls carrying the same `expectedVersion`; the first landed, the
   * second's basis was already stale, so the operator saw an error line next to "Saved". Unlike
   * Pages/Posts, this screen has no "later click wins" intent to preserve (Menus has one action, not
   * a Save-vs-Publish race), so `save()` itself drops a same-tick re-entry via a synchronous
   * `useRef` guard rather than letting a second write reach the port at all — see `save()`'s own
   * comment.
   */
  saving: boolean;
  /** Bound translator — `MenuEditor.tsx`'s only source of UI copy; see this file's own header. */
  t: Translate;
}

function menuSaveError({ error, t }: { error: unknown; t: Translate }, _optional = {}): string {
  // A lost compare-and-set (`409 VERSION_CONFLICT`, real since menu saves became
  // compare-and-set, wm S4) gets translated "someone else changed this" copy instead of the
  // server's "menu '<id>' was modified concurrently…" text. Other errors (a slug already taken
  // is also a 409, without the code) keep the server message.
  if (isVersionConflict(error)) return t(VERSION_CONFLICT_MESSAGE);
  return error instanceof Error ? error.message : "save failed";
}

export function useMenuEditor(menuId: string | null, { port, navigate, t, clipboard,
  itemIdSource = { crypto: globalThis.crypto, nowMs: Date.now, random: Math.random },
}: MenuEditorDependencies): MenuEditorController {
  const isNew = menuId === null;
  const fetchMenu = useCallback(async () => {
    try { return await port.getMenu(menuId!); }
    catch (error) { throw new Error(error instanceof Error ? error.message : t("failed to load menu")); }
  }, [menuId, port, t]);
  const menuKey = useMemo(() => ["menus", "detail", menuId ?? "new"] as const, [menuId]);
  const loader = useCachedLoader({ key: menuKey, fetch: fetchMenu }, { staleTime: 0 });
  const hydratedRoute = useRef<string | null | undefined>(undefined);
  const write = useFetchMutation({ run: ({ input }: { input: () => Promise<unknown> }) => input() }, { invalidates: [["menus"]] });
  const [copyFeedback, setCopyFeedback] = useState<string | null>(null);
  const [menu, setMenu] = useState<AdminMenu | null>(null);
  const [title, setTitle] = useState("");
  const [slug, setSlug] = useState("");
  // A cleared slug is still an explicit edit. Track intent rather than testing whether it is empty.
  const slugEdited = useRef(false);
  const [items, setItems] = useState<AdminMenuItem[]>([]);
  const [mode, setMode] = useState<AdminMenuMode>("items");
  const [html, setHtml] = useState("");
  const needsPages = hasPageLinks({ items });
  const pageQueryFetch = useQueryFetchCallback(async () => (await port.listPages!({})).pages, [port]);
  const pageQuery = useFetchQuery({ key: ["menus", "page-options"], fetch: pageQueryFetch }, { enabled: needsPages && !!port.listPages, staleTime: 0 });
  const pageChoices = needsPages ? pageQuery.data : undefined;
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(!isNew);
  // Snapshot of the last loaded-or-saved state (audit finding: no editor screen tracks this at
  // all today, so there is nothing for a dirty check to compare against). `null` only while a load
  // is still in flight — set immediately for `isNew` (an empty menu IS the loaded state to diff
  // against), and refreshed after every successful save so a saved edit stops reading as dirty.
  const [original, setOriginal] = useState<MenuFormState | null>(null);

  // Stale-response guard (2026-08-12 audit finding): this is a route-param loader — the panel
  // router reuses this same component/hook across `/new` and every `/:id`, so navigating from one
  // menu to another (or from an existing menu to `/new`) can let an OLDER `getMenu` response land
  // after a NEWER one, overwriting the currently-viewed menu with a previous one's data (or, for
  // `/new`, populating a blank editor with a stale record — the operator would then be editing and
  // saving over the wrong menu). `cancelled` is flipped by this same effect's own cleanup the
  // instant `menuId`/`isNew` changes again, before the new run starts — guarded on every completion
  // path (`then`/`catch`/`finally`), not just the success path, since an unguarded `finally`
  // clearing `loading` is the one most likely to leave stale data on screen with no spinner to flag
  // it.
  // biome-ignore lint/correctness/useExhaustiveDependencies: the loader captures the port; an already hydrated route retains its draft.
  useEffect(() => {
    if (hydratedRoute.current === menuId) return;
    let cancelled = false;
    setCopyFeedback(null);
    slugEdited.current = false;
    if (isNew) {
      setMenu(null);
      setTitle("");
      setSlug("");
      setItems([]);
      setMode("items");
      setHtml("");
      setOriginal({ title: "", slug: "", items: [], mode: "items", html: "" });
      setLoading(false);
      hydratedRoute.current = menuId;
      return;
    }
    setLoading(true);
    setError(null);
    // Await a fresh version on every route entry; a retained cache value is only display data.
    loader.load()
      .then(({ menu }) => {
        if (cancelled) return;
        hydratedRoute.current = menuId;
        setMenu(menu);
        setTitle(menu.title);
        setSlug(menu.slug);
        setItems(menu.items);
        setMode(menu.mode ?? "items");
        setHtml(menu.html ?? "");
        setOriginal({ title: menu.title, slug: menu.slug, items: menu.items, mode: menu.mode ?? "items", html: menu.html ?? "" });
        // readable-slugs S6b: an old id-based bookmark quietly catches up to the slug URL, same
        // `slugRedirectPath` (`lib/slug-redirect-path.ts`) rule posts/pages/widgets already apply.
        const redirectPath = slugRedirectPath("/menus", menuId as string, menu);
        if (redirectPath) navigate(redirectPath, { replace: true });
      })
      .catch((e) => {
        if (cancelled) return;
        // Always an `Error`: `fetchMenu` above rethrows every failure as one (with the translated
        // "failed to load menu" fallback for a non-Error rejection), so no second fallback here.
        setError((e as Error).message);
      })
      .finally(() => {
        if (cancelled) return;
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [menuId, isNew, loader]);

  const { confirmLeave } = useDirtyGuard<MenuFormState>({ current: { title, slug, items, mode, html }, original }, { host: window, translate: (key) => key });

  // Stale-response guard, save() half (2026-08-12 audit finding): the load effect's `cancelled`
  // flag above is scoped to a single effect run and flipped by that SAME effect's own cleanup — but
  // save() isn't an effect, so a route change mid-save never flips it. `activeMenuIdRef` always
  // holds the latest `menuId` this hook was RENDERED with (updated every render, not just on effect
  // re-run), so save()'s completion handlers can tell whether the operator has already navigated to
  // a different menu by the time create/update resolves, and skip committing state that belongs to
  // a menu no longer on screen. The `isNew` branch's own `navigate()` + early `return` stays
  // unguarded on purpose: it must always fire to land the operator on the menu they just created.
  const activeMenuIdRef = useRef(menuId);
  activeMenuIdRef.current = menuId;

  // Same-tick re-entry guard for `save()` (S4a, 2026-09-20) — see `MenuEditorController.saving`'s
  // own doc for the double-write bug this closes. A plain `useRef`, not `useSettlementGeneration`
  // (Pages/Posts' primitive): this screen has only one write action, so there is no "later click
  // wins" outcome to preserve — the second same-tick call should simply not happen at all. Checked
  // synchronously at the top of `save()`, before anything else runs, so two calls issued in the same
  // tick (a double click) both observe the first one's claim.
  const savingRef = useRef(false);
  const [saving, setSaving] = useState(false);

  /** New-menu titles derive through the same browser-safe slug owner as pages/forms; persisted URLs stay stable. */
  function changeTitle(next: string): void {
    setTitle(next);
    if (isNew && !slugEdited.current) setSlug(toSlug(next));
  }

  /** Any explicit slug edit ends automatic derivation for this menu, including an intentionally empty value. */
  function changeSlug(next: string): void {
    slugEdited.current = true;
    setSlug(next);
  }

  function changeAt(path: number[], fn: (item: AdminMenuItem) => AdminMenuItem) {
    setItems((prev) => mapAtPath(prev, path, fn));
  }
  function removeAt(path: number[]) {
    setItems((prev) => removeAtPath(prev, path));
  }
  function addChildAt(path: number[]) {
    setItems((prev) => addChildAtPath(prev, path, () => newItem({ source: itemIdSource })));
  }
  function moveAt(path: number[], direction: -1 | 1) {
    setItems((prev) => moveAtPath(prev, path, direction));
  }
  function addRootItem() {
    setItems((prev) => [...prev, newItem({ source: itemIdSource })]);
  }
  function changeMode(next: AdminMenuMode) {
    // `pageItemsForSave` fills each page link's public path from the catalogue, so the starter
    // links to real URLs rather than `#`.
    if (next === "html" && html === "") setHtml(menuHtmlStarter({ items: pageItemsForSave({ items, pages: pageChoices }) }));
    setMode(next);
  }

  async function copyHtmlEmbed() {
    if (!menu) return;
    const copyingForMenuId = menuId;
    try {
      await (clipboard ?? navigator.clipboard).writeText(menuHtmlEmbed({ slug: menu.slug }));
      if (activeMenuIdRef.current === copyingForMenuId) setCopyFeedback(t("Copied!"));
    } catch {
      if (activeMenuIdRef.current === copyingForMenuId) setCopyFeedback(t("Could not copy embed"));
    }
  }

  async function save() {
    // Drop a same-tick duplicate outright — see `savingRef`'s own comment above and
    // `MenuEditorController.saving`'s doc for why this screen prefers "the second click never
    // happens" over Pages/Posts' "let the later one win".
    if (savingRef.current) return;
    savingRef.current = true;
    setSaving(true);
    const savingForMenuId = menuId;
    setMessage(null);
    setError(null);
    try {
      const saveItems = pageItemsForSave({ items, pages: pageChoices });
      const authoring = menuAuthoringForSave({ mode, html, storedMode: menu?.mode });
      if (isNew) {
        const { menu: created } = await write.mutate({ input: () => port.createMenu({ title, slug }, { items: saveItems, ...authoring }) }) as Awaited<ReturnType<typeof port.createMenu>>;
        navigate(`/menus/${created.slug}`);
        return;
      }
      if (!menu) return;
      const { menu: saved } = await write.mutate({ input: () => port.updateMenuTree(
        { id: menu.id, expectedVersion: menu.version, items: saveItems },
        { title, slug, ...authoring }
      ) }) as Awaited<ReturnType<typeof port.updateMenuTree>>;
      if (activeMenuIdRef.current !== savingForMenuId) return;
      setMenu(saved);
      setItems(saved.items);
      // The server stores HTML parse5-balanced, so show (and baseline on) what it actually kept.
      const savedHtml = saved.html ?? html;
      setHtml(savedHtml);
      // A saved edit is no longer "unsaved" — re-baseline what the dirty check compares against,
      // or the guard would keep firing for a change the operator just persisted.
      setOriginal({ title, slug, items: saved.items, mode, html: savedHtml });
      setMessage(`Saved · version ${saved.version}`);
    } catch (e) {
      if (activeMenuIdRef.current !== savingForMenuId) return;
      setError(menuSaveError({ error: e, t }));
    } finally {
      // Unconditional, unlike the `activeMenuIdRef` checks above: this flag tracks whether THIS
      // save cycle is still on the wire, not whether its result still belongs to the menu on
      // screen, so it always clears when the request settles, whichever menu that request was for.
      savingRef.current = false;
      setSaving(false);
    }
  }

  return {
    pageChoices,
    copyHtmlEmbed,
    copyFeedback,
    isNew,
    menu,
    title,
    setTitle: changeTitle,
    slug,
    setSlug: changeSlug,
    items,
    mode,
    changeMode,
    html,
    setHtml,
    message,
    error,
    loading,
    confirmLeave,
    changeAt,
    removeAt,
    addChildAt,
    moveAt,
    addRootItem,
    save,
    saving,
    t,
  };
}

/**
 * Binds the real `/api/.../menus` client, the real `lib/router` `navigate`, and a
 * `MENUS_DICT`-bound translator — see `menus-dependencies.hooks.ts`.
 *
 * The zero-argument-dependencies half of the `useX(dependencies)` / `useWiredX()` pair, so
 * `MenuEditor.tsx` composes this and a test composes {@link useMenuEditor} with
 * `createFakeMenusPort`.
 */
export function useWiredMenuEditor(menuId: string | null): MenuEditorController {
  const locale = useAdminLocale();
  const t = (key: string): string => translate({ locale: locale, key: key });
  return useMenuEditor(menuId, { port: defaultMenusPort, navigate: realNavigate, t });
}

import type { AdminMenuItem, AdminMenuTarget } from "@/lib/api";
export interface MenuPageChoice { id: string; title: string; status: "draft" | "published"; publicPath?: string; }
/** Release compatibility: installed DTO types predate the optional JSON content-type hint. */
export type PageMenuTarget = AdminMenuTarget & { entryType?: string; lastKnownHref?: string };
export type MenuTargetEditorKind = AdminMenuTarget["kind"] | "page";

export function menuTargetEditorKind({ target, pages }: { target: PageMenuTarget; pages?: readonly MenuPageChoice[] }, _optional = {}): MenuTargetEditorKind {
  return target.kind === "entryRef" && (target.entryType === "page" ||
    (target.entryType === undefined && pages?.some((page) => page.id === target.entryId))) ? "page" : target.kind;
}

export function hasPageLinks({ items }: { items: readonly AdminMenuItem[] }, _optional = {}): boolean {
  // Legacy refs need the catalogue before their editor kind is known; waiting for the hint
  // first prevented the Page picker from ever recovering a migrated unhinted reference.
  return items.some((item) => {
    const target: PageMenuTarget = item.target;
    return (target.kind === "entryRef" && (target.entryType === undefined || target.entryType === "page")) ||
      hasPageLinks({ items: item.children ?? [] });
  });
}

export function pageTargetForChoice(
  { entryId, pages, previous }: { entryId: string; pages?: readonly MenuPageChoice[]; previous?: PageMenuTarget },
  _optional = {},
): PageMenuTarget {
  const lastKnownHref = pages?.find((page) => page.id === entryId)?.publicPath ??
    (previous?.entryId === entryId ? previous.lastKnownHref : undefined);
  return { kind: "entryRef", entryId, entryType: "page", ...(lastKnownHref ? { lastKnownHref } : {}) };
}

/** Refresh the URL snapshot on every save, including unchanged/nested legacy page refs.
 * A failed catalogue read retains existing metadata; it never guesses a path from a label/id. */
export function pageItemsForSave(
  { items, pages }: { items: readonly AdminMenuItem[]; pages?: readonly MenuPageChoice[] },
  _optional = {},
): AdminMenuItem[] {
  return items.map((item) => ({ ...item,
    target: menuTargetEditorKind({ target: item.target, pages }) === "page"
      ? pageTargetForChoice({ entryId: item.target.entryId ?? "", pages, previous: item.target }) : item.target,
    ...(item.children ? { children: pageItemsForSave({ items: item.children, pages }) } : {}),
  }));
}

/** The scalar fallbacks are named for the same cyclomatic-complexity reason as MenuEditor's
 * orEmpty helper. Target reshaping belongs in rules, outside the editor's markup. */
function orEmpty(value: string | undefined): string { return value ?? ""; }

export function targetForKind(
  { kind, prev }: { kind: MenuTargetEditorKind; prev: PageMenuTarget },
  _optional = {},
): PageMenuTarget {
  switch (kind) {
    case "page": {
      const lastKnownHref = prev.lastKnownHref || prev.href;
      return { kind: "entryRef", entryId: orEmpty(prev.entryId), entryType: "page",
        ...(lastKnownHref ? { lastKnownHref } : {}) };
    }
    case "url": return { kind, href: orEmpty(prev.href) };
    case "route": return { kind, route: orEmpty(prev.route) };
    case "entryRef": return { kind, entryId: orEmpty(prev.entryId) };
    case "termRef": return { kind, termId: orEmpty(prev.termId), taxonomy: orEmpty(prev.taxonomy) };
  }
}

function isUnavailablePageSelection(
  { entryId, pages, selected }: { entryId?: string; pages?: readonly MenuPageChoice[]; selected?: MenuPageChoice },
  _optional = {},
): boolean {
  return Boolean(entryId && pages && (!selected || selected.status !== "published"));
}

export function pageLinkState(
  { entryId, label, pages, t }: { entryId?: string; label?: string; pages?: readonly MenuPageChoice[]; t: (key: string) => string },
  _optional = {},
) {
  const selected = pages?.find((page) => page.id === entryId);
  const unavailable = isUnavailablePageSelection({ entryId, pages, selected });
  return {
    value: entryId ?? "",
    unavailable,
    choices: [
      { id: "", title: t("Choose a page…") },
      ...(entryId && !selected ? [{ id: entryId, title: label || t("Page not published") }] : []),
      ...(pages ?? []),
    ],
  };
}

import { useAdminThemeBoundary } from "../../admin-themes/use-admin-theme.hooks";
