/**
 * @file Everything the Pages EDITOR does, so `PageEditor.tsx` is only markup.
 *
 * Same `use-<thing>.hooks.ts` convention as `use-pages.hooks.ts` beside it. Deliberately NOT shared
 * with `features/posts`' `usePostEditor`: a Post is a Tiptap document and a Page is a bespoke HTML
 * one, they are edited through different endpoints with different concurrency semantics, and the
 * only thing the two screens have in common is the header chrome.
 *
 * `port`/`navigate`/`t`/`locale` are injected — see `page-editor-port.hooks.ts` — rather than
 * reaching `lib/api`/`lib/router`/`page-editor-i18n`/`useAdminLocale()` directly, so a test can
 * describe load/save/delete outcomes against `createFakePageEditorPort` instead of stubbing global
 * `fetch`. `useWiredPageEditor` below is the zero-argument pair `PageEditor.tsx` actually mounts.
 * `useAdminLocale()` itself is called only inside `useWiredPageEditor` — its resolved `locale`
 * string is what gets injected, not the hook reference; see that function's own doc.
 */

/** The three things the editor's main pane can show. Preview is the default — the HTML source is
 *  for when the operator wants to see or hand-edit what the assistant produced, and Interactive is
 *  a GrapesJS-backed surface for clicking into rendered text and editing it in place (text editing
 *  and basic formatting only — see `@jini-ai/ui/html-editor`'s generic `InteractiveHtmlEditor`,
 *  mounted directly by `PageEditor.tsx` since 2026-09-23 with this feature's own
 *  `embedPlaceholderDescriber` supplied above, rather than through `@jini-ai/admin/react`'s
 *  Tovu-specific adapter). */
export type PageEditorView = "preview" | "html" | "interactive";

export interface PageEditorController {
  /** `null` until the initial load settles. */
  page: AdminPost | null;
  error: string | null;
  message: string | null;
  title: string;
  setTitle: (value: string) => void;
  slug: string;
  setSlug: (value: string) => void;
  status: "draft" | "published";
  setStatus: (value: "draft" | "published") => void;
  /** Pages template picker (Task 4, 2026-08-11). Tri-state, but `null` and `""` now diverge
   *  (bare-page ruling, 2026-09-23, S6 — see `rules.ts`'s `pagePickerValue`): `null` is "never chosen",
   *  which renders through the theme's own page shell ("Theme default" in the picker); `""` is an
   *  explicit "No template", which renders bare — only this Page's own HTML, no theme styles, scripts,
   *  header or footer; or a real filename, which renders that template. */
  templateChoice: string | null;
  setTemplateChoice: (value: string | null) => void;
  /** The active theme's declared `templates` list (`theme.json`) — `[]` when the theme doesn't
   *  support templates, in which case the caller should not render the picker at all. The SAME field
   *  `usePostEditor`'s `availableTemplates` reads (unified 2026-08-11 — was a separate `pageTemplate`
   *  array before the `content` marker removed the reason Posts and Pages needed different lists). */
  availableTemplates: string[];
  /** The workspace's currently active theme id (`PresentationSettings.activeThemeId`) — feeds the
   *  Interactive tab's canvas stylesheet/token fetches and `TemplateSourceModal`'s fetch URL. `null`
   *  until the presentation-settings load settles. Mirrors `usePostEditor`'s identical field. */
  activeThemeId: string | null;
  /** The active theme's capability tier (looked up on `availableThemes` by `activeThemeId`) — gates
   *  whether "View Template" (`TemplateSourceModal`) attempts a fetch at all. `null` when the id has
   *  not loaded yet OR when it is absent from `availableThemes`. Mirrors `usePostEditor`'s identical
   *  field ("View Template" parity, 2026-09-24). */
  activeThemeTier: ThemeTier | null;
  /** The active theme's manifest `apiVersion` (`2`, or `undefined` for v1) — same
   *  `render/pages/`-vs-`pages/` fetch-URL decision `usePostEditor`'s identical field documents. */
  activeThemeApiVersion: 2 | undefined;
  /** Whether the "View Template" modal (`TemplateSourceModal`) is open — Pages' own instance of the
   *  affordance `usePostEditor`'s identical field has carried since 2026-08-10 (2026-09-24, "View
   *  Template" parity: Pages had a template picker but no way to inspect the chosen template's
   *  source, unlike Posts). Ephemeral view state; not persisted. */
  showTemplateModal: boolean;
  /** The template picker's "View Template" button — opens {@link showTemplateModal}. A no-op when
   *  nothing is chosen ({@link templateChoice} falsy); `PageEditor.tsx`'s own button additionally
   *  disables itself in that case, this is belt-and-suspenders against a direct call. */
  onViewTemplateClick: () => void;
  /** `TemplateSourceModal`'s own close action. */
  onCloseTemplateModal: () => void;
  /** The working copy of the page's HTML — what the preview renders and what Save persists. */
  html: string;
  setHtml: (value: string) => void;
  /**
   * HTML tab's local, display-only pretty-printed copy of `html` (moved here from `PageEditor.tsx`,
   * 2026-08-11 complexity-ceiling pass — see the reformat effect below for the full "why" this used
   * to carry in that component). Reformats only on the transition INTO the HTML tab (never mid-edit,
   * never on every keystroke) so the formatter can't fight the operator's cursor, and typing here
   * writes straight through to `setHtml` too, so this is purely a display concern layered on top of
   * `html` — it can never by itself affect `dirty`.
   */
  draftHtml: string;
  setDraftHtml: (value: string) => void;
  view: PageEditorView;
  setView: (value: PageEditorView) => void;
  device: DevicePreviewDevice;
  setDevice: (value: DevicePreviewDevice) => void;
  /**
   * Preview fullscreen (2026-09-16) — whether the Preview tab's own pane is expanded to fill
   * `.admin-main-col` (see `PageEditor.tsx`'s `.page-preview-expanded` wrapper). The Pages-side
   * twin of `PostEditorController.previewExpanded`; see that field's own doc for the full
   * lifetime/containment reasoning this deliberately copies rather than lifts to `App.tsx` or a
   * module-level bus — a route change unmounts `PageEditor`, which unmounts this hook, which
   * discards this for free. Never persisted.
   *
   * Deliberately independent of {@link device}: expanding does NOT override the operator's chosen
   * preview width. See `PagePreview`'s own doc for why widening the pane (not widening the page)
   * is what fullscreen means here.
   */
  previewExpanded: boolean;
  /** Flips {@link previewExpanded}. A separate action rather than a setter, matching `setView`'s
   *  own shape above — the caller never needs to set it to a specific value directly. */
  togglePreviewExpanded: () => void;
  /**
   * `PagePreview`'s own frame element and its live-measured width (moved here from `PagePreview`,
   * 2026-08-11 complexity-ceiling pass — see `usePreviewPaneWidth` (`components/DevicePreview`) for the full "why ResizeObserver
   * instead of a guessed constant" reasoning this used to carry in that component). `PageEditor.tsx`
   * passes both straight through as props; `PagePreview` attaches `frameRef` to the element it wants
   * measured (`<div ref={frameRef}>` — React accepts a callback ref directly, same call site a
   * `RefObject` would use) and reads `paneWidth` back to compute its scale. A CALLBACK ref, not a
   * `RefObject` — see `usePreviewPaneWidth` for why that distinction is load-bearing here.
   */
  frameRef: (node: HTMLDivElement | null) => void;
  paneWidth: number;
  saving: boolean;
  /** Bound page-editor translator for the markup surface. */
  t: Translate;
  /**
   * Bug A (2026-09-23 interactive-bugs plan, Slice A3) — the Interactive tab's placeholder-card
   * describer, built once here (see this hook's own `embedPlaceholderDescriber` local for why) and
   * handed to `@jini-ai/ui/html-editor`'s `InteractiveHtmlEditor` as `describeEmbedPlaceholder` by
   * `PageEditorPane`. Recognizes a `data-embed-config` marker and labels it from the shared
   * `@tovu/embed-marker` target rule, instead of the id-only label Jini's own adapter produced.
   */
  embedPlaceholderDescriber: (el: Element) => CanvasEmbedPlaceholderDescriptor | undefined;
  onRequestEditHtml: RequestEditHtml;
  onInteractiveSourceError: (error: Error) => void;
  /**
   * Interactive flush (2026-09-23 plan) — `PageEditorPane` attaches this to
   * `<InteractiveHtmlEditor ref={...}>`. GrapesJS only syncs an open RTE session's text into its
   * component model when that session closes, never on every keystroke, so `save`,
   * `saveOverwritingConflict`, `setView`, and `setTemplateChoice` all flush through it (via
   * `flushInteractiveEdits`, `use-interactive-flush.hooks.ts`) before reading or changing `html` —
   * otherwise a still-open edit is silently lost. `null` until `<InteractiveHtmlEditor>` mounts (not
   * on the Interactive tab, or not yet rendered).
   */
  interactiveEditorRef: RefObject<InteractiveHtmlEditorHandle | null>;
  /** `<InteractiveHtmlEditor onChange>`: `setHtml` with the canvas's `&quot;`-encoded embed markers
   *  put back in their readable single-quoted form (`use-interactive-flush.hooks.ts`). */
  setHtmlFromCanvas: (value: string) => void;
  /**
   * Whether the working copy differs from what was last loaded or saved.
   *
   * Read by more than the Save button: this is the "in the middle of a task" signal the agent's
   * `pages.open_editor` capability is meant to gate navigation on, so that being pulled to another
   * page mid-edit asks first instead of discarding work.
   */
  dirty: boolean;
  /**
   * Template-preview fix (2026-08-11) — `dirty` MINUS the `templateChoice` comparison: whether
   * title/slug/status/body differ from what's saved. A page can be `dirty` (Save button lit) while
   * `contentDirty` is `false` — that's exactly "only the template picker moved" — which is what lets
   * `PagePreview` show a real template-applied render for the pending choice instead of falling all
   * the way back to the raw, unstyled body. See `ADS-memory/reports/implementation/
   * 2026-08-11-template-preview-render-bug.md` for the bug this fixes.
   */
  contentDirty: boolean;
  /**
   * The admin-only template-preview iframe's `src`, pre-built from `port.templatePreviewUrl` (a
   * synchronous URL builder, not a fetch) so `PageEditor.tsx` never imports `lib/api` just to call
   * it. `""` before `page` loads — never rendered that early, since `PageEditor.tsx` shows a loading
   * notice and mounts no preview until `page` is set, same "inert default before load" shape
   * `availableTemplates` already uses. Recomputed on every render off `page`/`templateChoice` — cheap
   * string building, not worth a `useMemo`.
   */
  templatePreviewUrl: string;
  /** DOM ref for the pending-html-preview's hidden `<form>` — owned here, not local to
   *  `PagePreview`, so the debounced auto-submit effect below can reach it. Same "hook owns the ref,
   *  view attaches it" shape `frameRef` above already uses, and the same shape
   *  `use-post-editor.hooks.ts`'s own `previewFormRef` uses for Posts — see that field's own doc for
   *  the "why here, not the view" reasoning this mirrors.
   *
   *  A CALLBACK ref, not a `RefObject` (2026-10-05 owner bug: a draft's preview went blank after a
   *  full-screen toggle). The form is a hidden POST into a named iframe, so a freshly mounted pair is
   *  an EMPTY `about:blank` frame until something submits into it. With a `RefObject` the debounced
   *  effect only re-armed on editor-state changes, so any remount that changed no state (the
   *  expand/collapse tree swap did exactly that) left the new iframe empty for good. Holding the node
   *  in state puts the form itself in the effect's dependency list: every mount re-submits. */
  previewFormRef: (node: HTMLFormElement | null) => void;
  /** Stable name shared by the hidden form's `target` and the iframe it submits into. `""` before
   *  `page` loads — `PagePreview` never renders that early. */
  previewFormTarget: string;
  /**
   * What the Interactive tab's GrapesJS canvas renders the page against — the active theme's own
   * stylesheet plus its design tokens, so a page is edited looking roughly the way it publishes
   * rather than as browser-default text on white. `pending` until the theme's token files settle;
   * `PageEditor.tsx` must not mount the editor before then, because `InteractiveHtmlEditor` reads
   * its canvas styling once at mount and never reacts to a later value. See
   * `use-theme-canvas-styling.hooks.ts`.
   */
  canvasStyling: ThemeCanvasStylingState;
  save: (nextStatus?: "draft" | "published") => Promise<void>;
  /**
   * Non-null once the server has REFUSED an explicit Save/Publish because another operator's save
   * moved the row's `version` out from under this editor (2026-09-07). The caller renders it as a
   * banner offering the two things an operator can actually do — {@link saveOverwritingConflict} or
   * {@link dismissSaveConflict} — with the wording in `rules.ts`'s `pageVersionConflictMessage`.
   *
   * Distinct from {@link autosaveStaleBasis} below, which is the BACKGROUND autosave hitting the
   * same wall: this one is a save the operator pressed and watched fail.
   */
  saveConflict: PageSaveConflict | null;
  /** Re-reads the current row and re-runs the rejected save against it, replaying the original
   *  draft/publish intent. The only way past a {@link saveConflict}, and deliberately explicit: the
   *  plain Save button keeps failing until the operator chooses to replace the other version. */
  saveOverwritingConflict: () => Promise<void>;
  /** Hides the {@link saveConflict} banner without writing anything. */
  dismissSaveConflict: () => void;
  remove: () => Promise<void>;
  confirmingDelete: boolean;
  setConfirmingDelete: (value: boolean) => void;
  /** The Save button. With changes it saves; with none it opens the "Nothing changed. Save anyway?"
   *  warning (owner, 2026-10-10) — see `unchangedSaveHandlers`. Never disabled for "no changes". */
  onSave: () => void;
  /** The "Nothing changed. Save anyway?" warning is open. */
  confirmingUnchangedSave: boolean;
  /** The warning's "Save anyway": closes it and saves; the server skips the write if nothing differs. */
  onUnchangedSaveConfirm: () => void;
  onUnchangedSaveCancel: () => void;
  deleting: boolean;
  /** Call before an in-app navigation the operator triggered (the back link). `true` means it's
   *  safe to proceed. `beforeunload` is wired automatically by the same `useDirtyGuard` call this
   *  reads off — see `use-dirty-guard.hooks.ts`. Audit finding (2026-08-01): unlike `PostEditor`,
   *  this screen had NO unsaved-work guard of any kind until now — fixed alongside standing-draft
   *  autosave since both exist to protect the same at-risk work. */
  confirmLeave: () => boolean;
  /**
   * The back link's `onClick`. With no Interactive editor mounted this is exactly
   * {@link confirmLeave}: cancel means `preventDefault()`, otherwise the link's own navigation runs.
   * With one mounted, an edit still open in an RTE session is not in `html` yet, so `dirty` cannot
   * see it (GrapesJS syncs it only when the session closes). Then this always takes over the
   * navigation: it flushes the editor, asks if the flush produced unsaved HTML, and navigates to
   * the list itself only if the operator agrees.
   */
  onBackLinkClick: (event: { preventDefault: () => void }) => Promise<void>;
  /**
   * Standing-draft autosave (2026-09-06) — non-null once the mount-time recovery check finds a
   * draft parked from a previous session. Never auto-applied; `PageEditor.tsx` renders an explicit
   * "restore or discard" banner and calls {@link restoreRecoveredDraft}/{@link discardRecoveredDraft}
   * on the operator's own action.
   */
  recoverableDraft: StandingDraftAutosaveSnapshot | null;
  /** Applies the recovered draft into the working copy (title/slug/html) and dismisses the banner.
   *  Does NOT itself tell the server anything — the restored edit re-enters the normal autosave/Save
   *  flow from here, the same as any other in-progress edit. */
  restoreRecoveredDraft: () => void;
  /** Discards the recovered draft server-side and dismisses the banner, without applying it. */
  discardRecoveredDraft: () => Promise<void>;
  /**
   * Standing-draft autosave — non-null once the server has REFUSED a background write for this page
   * because another operator's save moved the row's `version` out from under this editor. Distinct
   * from {@link recoverableDraft}, which is work found parked from a previous session: this is the
   * session happening right now, and while it is set nothing the operator types is being persisted
   * anywhere the server can see.
   *
   * Surfaced so `PageEditor.tsx` can say so on screen. That is the whole point of passing it
   * through: `useStandingDraftAutosave` has recorded this since commit `a60e07e8`, and with no
   * editor consuming it the operator could type for an hour into a screen that looked completely
   * normal and be told nothing until they reloaded.
   *
   * Reporting it never costs the operator their text — the working copy (`title`/`slug`/`html`) is
   * not touched on this path, by this hook or by the shared one.
   */
  autosaveStaleBasis: StandingDraftStaleBasis | null;
  /**
   * Content refresh (2026-09-16) — non-null only while an assistant tool (`pages_write_html` /
   * `pages_write_region`) has written a newer version of this page AND the editor may have unsaved
   * edits the operator hasn't resolved yet (on the Interactive tab that is always assumed — see
   * `pageRefreshMayHaveUnsavedEdits`). `null` means either nothing changed, or the editor was clean
   * and already applied the change silently. See `use-external-entry-refresh.hooks.ts` for the
   * clean/dirty decision this is the dirty half of.
   */
  pendingExternalVersion: number | null;
  /** Discards the standing draft, re-reads the row, and applies it — the operator's explicit choice
   *  to throw away their unsaved edits in favor of the newer version. */
  loadExternalChange: () => Promise<void>;
  /** Hides {@link pendingExternalVersion}'s notice and silences further ones until this editor's own
   *  loaded basis version moves (a Save, Save anyway, or Load latest). */
  dismissExternalChange: () => void;
  /**
   * Bumped only when an EXTERNAL write is applied — silently, or through Load latest — never by this
   * editor's own save. The Interactive tab's remount key, so GrapesJS picks up an assistant-written
   * body without losing its canvas state on every own Save. On that tab only Load latest bumps it
   * (see `pageRefreshMayHaveUnsavedEdits`). See `PageEditorPane`'s `key={contentRevision}`.
   */
  contentRevision: number;
  /**
   * Per-tab scroll memory (2026-09-16, owner report: "when i click on HTML and Preview for the html
   * it goes back to the top. anyway not to lose position?"). `PageEditorPane` renders each surface as
   * its own root element keyed on `view` (`PageEditor.tsx`'s three-way branch), so React unmounts one
   * surface and mounts a fresh one on every tab switch — a brand-new `<textarea>`/`<iframe>` always
   * starts at `scrollTop`/`scrollY` `0`, independent of anything CSS or React state can fix on its
   * own. These three fields are that fix: the position is kept in a ref here (session-only, discarded
   * with the rest of this hook's state on navigating away — no persistence was asked for), restored
   * the instant the new DOM node mounts, and captured continuously while scrolling so the LAST
   * position before the node unmounts is always the one on file. HTML and Preview each get their own
   * ref, so switching tabs never mixes the two — syncing position BETWEEN tabs was explicitly not
   * wanted (owner, same report).
   *
   * `htmlTextareaRef` attaches to `PageEditorPane`'s `<textarea>` (`ref={htmlTextareaRef}`) and
   * restores its `scrollTop` the moment React commits the node; {@link onHtmlScroll} is wired to that
   * same textarea's native `onScroll` and keeps the ref current after that. A content refresh
   * (`contentRevision` bump) never unmounts this node — same tab, same element, `value` prop just
   * changes — so nothing here needs to re-restore for that case; the browser clamps `scrollTop` to the
   * new (possibly shorter) content on its own.
   */
  htmlTextareaRef: (node: HTMLTextAreaElement | null) => void;
  /** See {@link htmlTextareaRef}'s own doc. Wired to the HTML textarea's `onScroll`. */
  onHtmlScroll: (scrollTop: number) => void;
  /**
   * See {@link htmlTextareaRef}'s own doc — the Preview tab's counterpart. Wired to BOTH
   * `PagePreviewFrame` branches' `<iframe onLoad>`: the live-site iframe (`canShowLiveSite`) and the
   * template-preview iframe (the hidden-form POST target) each fire a fresh `load` on every mount AND
   * on every re-navigation (a content refresh re-submits the same iframe without unmounting it), which
   * is exactly the hook this needs — restoring and re-attaching a scroll listener on whichever `Window`
   * the iframe holds right now.
   *
   * The live-site iframe is cross-origin in dev (`siteUrl`'s own origin, `:3000` vs. the admin's
   * `:5173` — see `PagePreview`'s own doc). Reading or driving scroll on a foreign `Window` is a
   * browser security restriction this code cannot route around without the site itself cooperating
   * (out of scope — another agent owns `apps/website`), so that branch's position is NOT remembered.
   * Since 2026-10-05 the template-preview branch is in the same position: `PAGE_PREVIEW_IFRAME_SANDBOX`
   * dropped `allow-same-origin`, so every preview document has an opaque origin and this handler's
   * `try` swallows the `SecurityError` on both branches. Restoring it needs the preview document to
   * report its own scroll by `postMessage`. See this function's own implementation comment for the
   * try/catch this relies on.
   */
  onPreviewFrameLoad: (iframe: HTMLIFrameElement) => void;
}

/**
 * Applies a loaded row into the working copy AND the saved baseline — the mount effect's own
 * initialization, named out so `applyExternalPage` (an assistant write landing while the editor is
 * open, 2026-09-16) can seed the SAME fields from the SAME row shape rather than a second,
 * independently-maintained copy of this list drifting from it over time.
 *
 * UNLIKE `usePostEditor`'s equivalent, no "default to the theme's first template" here — `null` is a
 * Page's normal, fully-working state (render its own body), not an absence-of-decision that needs
 * papering over. `pageEditableHtml` (`rules.ts`) is the single place that decides whether `bodyHtml`
 * is real editable content for this row.
 *
 * @complexity Time/space: O(1).
 */
function applyLoadedPage(
  post: AdminPost,
  setters: {
    setPage: (page: AdminPost) => void;
    setTitle: (value: string) => void;
    setSlug: (value: string) => void;
    setStatus: (value: "draft" | "published") => void;
    setTemplateChoice: (value: string | null) => void;
    setSavedTemplateChoice: (value: string | null) => void;
    setHtml: (value: string) => void;
    setSavedHtml: (value: string) => void;
  },
): void {
  setters.setPage(post);
  setters.setTitle(post.title);
  setters.setSlug(post.slug);
  setters.setStatus(post.status);
  setters.setTemplateChoice(post.templateChoice ?? null);
  setters.setSavedTemplateChoice(post.templateChoice ?? null);
  const body = pageEditableHtml(post);
  setters.setHtml(body);
  setters.setSavedHtml(body);
}

/** `contentDirty`'s own computation, named out of `usePageEditor`'s body purely to keep that
 *  hook's own cyclomatic complexity under the gate — every `&&`/`||` in a boolean expression is
 *  its own branch. Same title/slug/status/body comparison, same behavior.
 *  See `PageEditorController.contentDirty`'s own doc for what this decides.
 *
 *  The body arm asks `pageAcceptsHtmlBody` rather than testing `bodyFormat` itself, so this agrees
 *  with `save` by construction: HTML typed into a brand-new (`doc`-format, empty-document) Page IS
 *  savable, and therefore has to count as dirty — otherwise the Save button never shows its pending
 *  dot, `useDirtyGuard` lets a navigate-away discard the work without asking, and the standing-draft
 *  autosave below never fires at all. */
function computeContentDirty(
  page: AdminPost | null,
  draft: { title: string; slug: string; status: "draft" | "published"; html: string; savedHtml: string },
): boolean {
  if (page === null) return false;
  return (
    draft.title !== page.title ||
    draft.slug !== page.slug ||
    draft.status !== page.status ||
    (pageAcceptsHtmlBody(page, draft.html) && draft.html !== draft.savedHtml)
  );
}

/**
 * Pending-html preview's debounced auto-submit (2026-09-09) — Pages' own version of
 * `use-post-editor.hooks.ts`'s `schedulePendingContentPreviewSubmit` (same file, same "hook owns
 * the effect, not the view" reasoning that function's own doc explains). A form submit is a full
 * iframe navigation, so firing one per keystroke would thrash the iframe; trailing-only, 500ms.
 * `clearTimeout` on cleanup is the complete cancellation, same as that function's.
 *
 * No `=== null`/`bodyJson`-shaped guard is needed here unlike the Posts version: `html` is a plain
 * string, always defined once `page` has loaded — the only state `PagePreview` ever mounts in (see
 * `PageEditor.tsx`'s own `if (!page) return <div className="notice">...` guard) — so `active` and
 * whether a form is mounted at all (2026-10-05, see `PageEditorController.previewFormRef`) decide
 * whether to schedule.
 *
 * @complexity Time/space: O(1) — one timer, no data copying.
 */
function schedulePendingHtmlPreviewSubmit(input: { active: boolean; form: HTMLFormElement | null }): () => void {
  const { form } = input;
  if (!input.active || form === null) return () => {};
  const timer = setTimeout(() => {
    form.submit();
  }, 500);
  return () => clearTimeout(timer);
}

/** `save`'s own "apply a successful write" step, named out of `save`'s body for the same
 *  complexity-ceiling reason {@link computeContentDirty} above documents (2026-09-05
 *  stale-settlement sweep: adding the generation guard pushed `save` over the gate). Called only
 *  once `save` has confirmed this call's generation is still current — see `save`'s own
 *  `settlement` doc — so every branch here runs unconditionally once reached. */
function applySavedPage(
  updated: AdminPost,
  form: { templateChoice: string | null; html: string; nextStatus?: "draft" | "published"; basisVersion: number },
  canSaveHtml: boolean,
  setters: {
    setPage: (page: AdminPost) => void;
    setSlug: (slug: string) => void;
    setStatus: (status: "draft" | "published") => void;
    setSavedTemplateChoice: (value: string | null) => void;
    setSavedHtml: (value: string) => void;
    setMessage: (value: string) => void;
  },
  t: (locale: string, key: string) => string,
  locale: string,
): void {
  setters.setPage(updated);
  setters.setSlug(updated.slug);
  setters.setStatus(updated.status);
  setters.setSavedTemplateChoice(form.templateChoice);
  if (canSaveHtml) setters.setSavedHtml(form.html);
  if (form.nextStatus) setters.setStatus(form.nextStatus);
  // The server skips a save whose content matches what's stored and answers with the SAME version
  // (2026-10-10, no-op save guard), so an unchanged version means nothing new was written.
  const unchanged = form.nextStatus === undefined && updated.version === form.basisVersion;
  setters.setMessage(unchanged ? pageUnchangedSaveMessage(t, locale, updated.version) : pageSaveSuccessMessage(t, locale, canSaveHtml));
}

/**
 * The two writes a Page save makes, in the order that makes the version guard real.
 *
 * **Metadata first, body second — reversed 2026-09-07, deliberately.** It used to be body first,
 * on the reasoning that "if the metadata write fails on a slug conflict, the operator's actual
 * content is already safe". That ordering is exactly what made a concurrency guard impossible:
 * `PUT /pages/:id/html` (`routes/admin/pages/update-html.ts`) reads the row and writes it back
 * inside ONE request, so the version its compare-and-set conditions on is one it captured
 * microseconds earlier — never the version this editor loaded — and it bumps `version` on the way
 * through. Writing it first therefore both clobbered the other operator's body AND invalidated the
 * basis the metadata write was about to claim. `updatePost` is the only one of the two that accepts
 * a client-supplied `expectedVersion`, so it has to go first for its 409 to mean anything.
 *
 * What the old ordering bought is not lost: the working copy is still in the editor either way, and
 * since 2026-09-06 a standing draft is parked server-side (`useStandingDraftAutosave`) — neither of
 * which existed when "body first" was chosen.
 *
 * @returns The final stored row: the body write's response when it fired, the metadata write's
 *   otherwise. Reading the earlier one would hand the caller a `version` already one behind.
 * @complexity Time O(1) plus one or two requests; space O(1).
 */
async function writePage(
  port: PageEditorPort,
  pageId: string,
  plan: PageSavePlan,
  html: string,
): Promise<AdminPost> {
  const { post: updated } = await port.updatePost({ id: pageId }, plan.updatePostPayload);
  if (!plan.canSaveHtml) return updated;
  try {
    const { post: withBody } = await port.updatePageHtml(pageId, html);
    return withBody;
  } catch (e) {
    // The metadata write above already landed — losing that fact here is exactly the partial-success
    // bug this wraps against (H1, 2026-09-20). See `PageBodyWriteError`'s own doc and
    // `applySaveFailure`'s handling of it.
    throw new PageBodyWriteError(updated, e);
  }
}

/** Thrown by {@link writePage} when the metadata write landed but the body write then failed. Carries
 *  `savedRow` — the metadata write's own response, the only successful outcome to have happened by
 *  the time this is thrown — so `applySaveFailure` can apply it without a second round-trip, and
 *  `reason`, whatever the body write itself threw, for the message shown to the operator. */
class PageBodyWriteError extends Error {
  constructor(
    readonly savedRow: AdminPost,
    readonly reason: unknown,
  ) {
    super("page body write failed after its metadata write already landed");
  }
}

/** `applySaveFailure`'s own "apply what already succeeded" step for a {@link PageBodyWriteError} —
 *  the metadata write's response, applied EXCEPT `setSavedHtml`, so the body stays dirty and the next
 *  Save (or the operator noticing the banner) retries writing it rather than the editor quietly
 *  treating an unsaved body as saved. Deliberately narrower than {@link applySavedPage}: no
 *  `setMessage` (the caller shows the partial-failure text instead, via `pagePartialSaveMessage`) and
 *  no `nextStatus` override (the metadata write already wrote whatever status this attempt asked
 *  for, since it is what succeeded). */
function applyPartialSave(
  updated: AdminPost,
  form: { templateChoice: string | null },
  setters: {
    setPage: (page: AdminPost) => void;
    setSlug: (slug: string) => void;
    setStatus: (status: "draft" | "published") => void;
    setSavedTemplateChoice: (value: string | null) => void;
  },
): void {
  setters.setPage(updated);
  setters.setSlug(updated.slug);
  setters.setStatus(updated.status);
  setters.setSavedTemplateChoice(form.templateChoice);
}

/** `runSave`'s own catch arm, named out of its body for the same complexity-ceiling reason
 *  {@link applySavedPage} above documents.
 *
 *  A {@link PageBodyWriteError} is handled FIRST and separately from the version conflict below: it
 *  is not a rejected save at all but a partial one, so it gets `applyPartialSave` plus
 *  `pagePartialSaveMessage` rather than either the conflict banner or the generic error line — see
 *  H1's own writeup (`ADS-memory/.local-artifacts/terra-admin-review-2026-09-20/plan-content.md`).
 *
 *  The version conflict is NOT folded into the generic error line either. The two need opposite
 *  reactions from the operator (a slug collision or a network blip: fix it and press Save again;
 *  this: pressing Save again replaces somebody's page), and the whole point of the route's distinct
 *  `code` is that the client no longer has to guess which it got — see `readPageVersionConflict`. */
function applySaveFailure(
  e: unknown,
  attemptedStatus: "draft" | "published" | undefined,
  form: { templateChoice: string | null },
  setters: {
    setPage: (page: AdminPost) => void;
    setSlug: (slug: string) => void;
    setStatus: (status: "draft" | "published") => void;
    setSavedTemplateChoice: (value: string | null) => void;
    setSaveConflict: (value: PageSaveConflict) => void;
    setError: (value: string) => void;
  },
  t: (locale: string, key: string) => string,
  locale: string,
): void {
  if (e instanceof PageBodyWriteError) {
    applyPartialSave(e.savedRow, form, setters);
    setters.setError(pagePartialSaveMessage(t, locale, e.reason));
    return;
  }
  const conflict = readPageVersionConflict(e, attemptedStatus);
  if (conflict) {
    setters.setSaveConflict(conflict);
    return;
  }
  setters.setError(e instanceof Error ? e.message : t(locale, "failed to save page"));
}

export interface PageEditorDependencies {
  port: PageEditorPort;
  /** Separate from `port` because it reaches a different surface entirely — a theme's static asset
   *  files, not the JSON admin API. See `theme-canvas-port.hooks.ts`. */
  themeCanvasPort: ThemeCanvasPort;
  /** `options.replace` (readable-slugs S6a, 2026-09-23): the load effect below replace-navigates a
   *  URL that resolved by raw id to that same page's slug — same shape
   *  `use-widget-instance-editor.hooks.ts`'s own `navigate` dependency already documents. */
  navigate: (path: string, options?: { replace?: boolean }) => void;
  t: (locale: string, key: string) => string;
  locale: string;
}

/**
 * `routeSlug` names what the URL actually carries: the page's slug for an ordinary page, as read
 * from the route (see `panels.tsx`'s `/:slug` pattern), `home` for the root page, or the id of a
 * page whose real slug is `home` (`pageAdminPath`, `rules.ts`). The alias maps to `/` for reads;
 * all other handles pass through unchanged. An id also works as a legacy
 * id-based bookmark too: the server-side lookup this feeds (`getAdminPostByIdOrSlug`) tries the
 * slug FIRST and falls back to an exact id match, so an old id-based bookmark still resolves —
 * corrected 2026-09-03, this comment previously stated the two checks in the opposite order. Every
 * write below uses `page.id` (the real id from the loaded record), never `routeSlug` directly — the
 * slug in the URL can go stale if the page is renamed elsewhere, but the id it resolved to at load
 * time cannot.
 *
 * `port`/`navigate`/`t` are destructured out of `deps` once, rather than threaded as `deps.port`
 * everywhere below — they are stable references in production (`useWiredPageEditor` always passes
 * the same module-level singletons; only `locale` actually varies across renders), so `useCallback`
 * dependency arrays can name them directly without an unstable-identity hazard, matching
 * `Jini redirects/SOURCE-RATIONALE.md`'s "confirmed safe to leave port unmemoized" precedent.
 */
export function usePageEditor(routeSlug: string, deps: PageEditorDependencies): PageEditorController {
  const { port, themeCanvasPort, navigate, t, locale } = deps;
  // Memoized (not a plain `const` closure) so `embedPlaceholderDescriber` below has a stable
  // dependency to key its own `useMemo` off: `deps.t` is a stable module-level singleton in
  // production (see this function's own doc), so this identity only changes when `locale` does.
  const boundT: Translate = useMemo(() => (key: string) => t(locale, key), [t, locale]);
  /**
   * Bug A (2026-09-23 interactive-bugs plan, Slice A3): built once here, not in `PageEditor.tsx`, so
   * the `.tsx` stays markup-only (this feature's own "no logic in `.tsx`" rule — see
   * `lib/embed-placeholder.ts`'s own file header). `InteractiveHtmlEditor` (`@jini-ai/ui/html-editor`)
   * reads `describeEmbedPlaceholder` once, at mount, and never reacts to a later prop change (same
   * mount-once contract as `html`/`canvasStyling`), so this identity changing on a locale switch is
   * harmless — the NEXT mount (a fresh Interactive-tab visit) picks up the new translator.
   */
  // The canvas captures its describer at mount; a ref supplies the latest server readiness.
  const pluginEmbeds = useRef<readonly AdminPagePluginEmbed[]>([]);
  const embedPlaceholderDescriber = useMemo(() => createEmbedPlaceholderDescriber({ t: boundT }, { pluginEmbeds: () => pluginEmbeds.current }), [boundT]);
  const pageKey = useMemo(() => ["pages", "detail", routeSlug] as const, [routeSlug]);
  const fetchPage = useCallback(async () => {
    const result = await port.getPage(routeSlug === HOME_PAGE_HANDLE ? "/" : routeSlug);
    pluginEmbeds.current = result.pluginEmbeds ?? [];
    return result;
  }, [port, routeSlug]);
  const pageLoader = useCachedLoader({ key: pageKey, fetch: fetchPage }, { staleTime: 0 });
  const readPage = useCallback((id: string) => pageLoader.load({ key: ["pages", "detail", id], fetch: async () => {
    const result = await port.getPage(id);
    pluginEmbeds.current = result.pluginEmbeds ?? [];
    return result;
  } }), [port, pageLoader]);
  const invalidate = useInvalidate();
  const fetchInitial = useCallback(async () => {
    // Loaded together: an empty template picker must not flash while presentation lags the page.
    try { return await Promise.all([pageLoader.load(), port.getPresentation()]); }
    catch (error) { throw new Error(error instanceof Error ? error.message : t(locale, "failed to load page")); }
  }, [port, pageLoader, routeSlug, locale]);
  const initialKey = useMemo(() => ["pages", "editor", routeSlug] as const, [routeSlug]);
  const initial = useCachedLoader({ key: initialKey, fetch: fetchInitial }, { staleTime: 0 });
  const hydratedRoute = useRef<string | null>(null);
  const write = useFetchMutation({ run: async ({ input }: { input: () => Promise<unknown> }) => {
    try { return await input(); }
    catch (error) {
      // Metadata already landed even though the body write failed; dependent lists must learn
      // that accepted version while the editor retains its existing partial-success recovery.
      if (error instanceof PageBodyWriteError) invalidate({ key: ["pages"] });
      throw error;
    }
  } }, { invalidates: [["pages"]] });
  const [page, setPage] = useState<AdminPost | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [title, setTitle] = useState("");
  const [slug, setSlug] = useState("");
  const [status, setStatus] = useState<"draft" | "published">("draft");
  // Pages template picker (Task 4, 2026-08-11) — `savedTemplateChoice` is `templateChoice`'s own
  // baseline for the manual dirty comparison below, same "captured on load/save" shape `savedHtml`
  // already uses for `html`.
  const [templateChoice, setTemplateChoice] = useState<string | null>(null);
  const [savedTemplateChoice, setSavedTemplateChoice] = useState<string | null>(null);
  const [availableTemplates, setAvailableTemplates] = useState<string[]>([]);
  // The active theme, captured off the same presentation-settings load the picker already does — the
  // Interactive tab's canvas needs both to find that theme's stylesheet and token files. `null`
  // until then, which `useThemeCanvasStyling` reads as "keep waiting", never as "no theme".
  const [activeThemeId, setActiveThemeId] = useState<string | null>(null);
  const [activeThemeApiVersion, setActiveThemeApiVersion] = useState<2 | undefined>(undefined);
  // "View Template" parity with `usePostEditor` (2026-09-24) — same `activeThemeTier` shape, same
  // load-effect source (the presentation-settings response).
  const [activeThemeTier, setActiveThemeTier] = useState<ThemeTier | null>(null);
  // View Template (2026-09-24, Pages' own instance of `usePostEditor`'s identical state) — whether
  // the read-only `TemplateSourceModal` is open.
  const [showTemplateModal, setShowTemplateModal] = useState(false);
  const [html, setHtml] = useState("");
  const [savedHtml, setSavedHtml] = useState("");
  const [view, setView] = useState<PageEditorView>("preview");
  // Interactive flush (2026-09-23 plan) — see `PageEditorController.interactiveEditorRef`'s own doc.
  const { interactiveEditorRef, flushInteractiveEdits, setHtmlFromCanvas } = useInteractiveEditorFlush(setHtml);
  const { device, setDevice } = useDevicePreviewDevice();
  // Preview fullscreen (2026-09-16) — see `PageEditorController.previewExpanded`'s own doc for why
  // this lives here instead of `App.tsx` or a bus. `false` by default: opening a Page must never
  // itself land on the expanded surface, even though `view` DOES default to "preview" here (unlike
  // Posts, which open on "edit").
  const [previewExpanded, setPreviewExpanded] = useState(false);
  const [saving, setSaving] = useState(false);
  const [confirmingDelete, setConfirmingDelete] = useState(false);
  // The "Nothing changed. Save anyway?" warning (owner, 2026-10-10) — see `unchangedSaveHandlers`.
  const [confirmingUnchangedSave, setConfirmingUnchangedSave] = useState(false);
  const [deleting, setDeleting] = useState(false);
  // A save the server refused because this editor's basis version had already been superseded
  // (2026-09-07). Distinct from `error`: `error` means "try again", this means "trying again
  // replaces somebody else's page" — see `applySaveFailure`.
  const [saveConflict, setSaveConflict] = useState<PageSaveConflict | null>(null);
  // Stale-settlement guard for `save()` (2026-09-05 sweep, extracted into `useSettlementGeneration`
  // 2026-09-06) — `saving` (state) already disables both the Save and Publish buttons, but that
  // alone cannot stop an overlapping second call (a same-tick double-invocation, or any caller
  // reaching `save()` directly rather than through those buttons) from applying a now-stale
  // response after a more-recent call already settled: whichever `port.updatePost()` call settled
  // last would win, regardless of which one was issued last. Mirrors `use-post-editor.hooks.ts`'s
  // own `settlement` (commit `42c6a534`), the reference this pattern was modelled on.
  const settlement = useSettlementGeneration();

  // Standing-draft autosave (2026-09-06) — see `use-standing-draft-autosave.hooks.ts`'s own header
  // for the ordering guarantee `clearStandingDraft` relies on. `entryId`/`enabled` both key off
  // `page` rather than `routeSlug`: the recovery check needs the row's REAL id (routeSlug can be a
  // stale/legacy bookmark), and must not run at all before the id is known.
  const autosave = useStandingDraftAutosave({ port, entryId: page?.id ?? null, enabled: page !== null, serverUpdatedAt: page?.updatedAt });

  // The previous load effect ran only for the route, even when locale changed. Keep the draft
  // captured once per route; locale changes may refresh the loader without replacing typed text.
  // `port` is stable in production (`useWiredPageEditor` uses a module-level singleton).
  // biome-ignore lint/correctness/useExhaustiveDependencies: initial captures locale; a hydrated route retains its draft.
  useEffect(() => {
    let cancelled = false;
    // Loaded together, same reasoning as `usePostEditor`'s identical `Promise.all` — the picker
    // needs `activeThemeTemplates` in hand before it can render anything meaningful, and a fast
    // page-load racing a slow presentation-settings load would otherwise flash an empty picker.
    if (hydratedRoute.current === routeSlug) return;
    // Reopening must hydrate from this mount's settled read, never the retained cache snapshot.
    // Once hydrated, background invalidations must not replace the operator's local draft.
    initial.load()
      .then(([{ post }, { activeThemeTemplates, activeThemeId: themeId, activeThemeApiVersion: themeApiVersion, activeThemeTier: themeTier }]) => {
        if (cancelled) return;
        hydratedRoute.current = routeSlug;
        setAvailableTemplates(editorTemplateOptions({ templates: activeThemeTemplates, savedTemplate: post.templateChoice }));
        setActiveThemeId(themeId);
        setActiveThemeApiVersion(themeApiVersion);
        setActiveThemeTier(themeTier);
        applyLoadedPage(post, { setPage, setTitle, setSlug, setStatus, setTemplateChoice, setSavedTemplateChoice, setHtml, setSavedHtml });
        // Old id bookmarks catch up to the canonical URL. Keep the root page out of the generic
        // slug redirect (`/pages//` cannot match), and keep a real `home` page on its id so it
        // cannot redirect into the root alias.
        if (post.slug === "/") {
          if (routeSlug === post.id) navigate(pageAdminPath(post), { replace: true });
        } else if (post.slug !== HOME_PAGE_HANDLE) {
          const redirectPath = slugRedirectPath("/pages", routeSlug, post);
          if (redirectPath) navigate(redirectPath, { replace: true });
        }
      })
      .catch((e) => {
        if (!cancelled) setError(e instanceof Error ? e.message : t(locale, "failed to load page"));
      });
    return () => {
      cancelled = true;
    };
  }, [routeSlug, port, initial]);

  // HTML tab pretty-printing (owner-reported regression, 2026-08-11 — verified nothing formatted this
  // view before either; see `lib/prettify-html.ts`'s file header). `draftHtml` is a LOCAL, display-only
  // copy of `html`: merely switching to the HTML tab reformats and shows it here, but never calls
  // `setHtml` itself, so `dirty` (computed above from `html !== savedHtml`) stays exactly what it was
  // before the operator looked at this tab — a display concern must never by itself mark the page as
  // having unsaved changes. `PageEditor.tsx`'s textarea writes straight through to BOTH `draftHtml` and
  // the real `setHtml` on every keystroke, unchanged from how the textarea always worked, so the only
  // way the prettified whitespace becomes part of the saved page is if the operator actually edits on
  // top of it. `prevViewRef` is what makes this fire only on the TRANSITION into the HTML tab, never on
  // every render while already on it — reformatting mid-edit would fight the operator's cursor position.
  const [draftHtml, setDraftHtml] = useState(() => prettifyHtml(html));

  // Per-tab scroll memory (2026-09-16) — see `PageEditorController.htmlTextareaRef`'s own doc for the
  // full "why a ref, why here" reasoning. A `useRef`, not `useState`: a scroll position changing must
  // never itself trigger a re-render, only be there the next time the tab mounts.
  const htmlScrollTopRef = useRef(0);
  const onHtmlScroll = useCallback((scrollTop: number) => {
    htmlScrollTopRef.current = scrollTop;
  }, []);

  // Content refresh (2026-09-16) — bumped only when an assistant write is applied (silently, or via
  // Load latest; never by this editor's own save), so the Interactive tab can remount and pick up the new body without
  // losing GrapesJS's canvas state on every own Save (a `page.version` key would do that too, since
  // an own save bumps it exactly the same way). See `PageEditorController.contentRevision`.
  const [contentRevision, setContentRevision] = useState(0);
  const onInteractiveSourceError = useCallback((_error?: Error) => {
    setError(boundT("Can't edit this source visually. Use HTML."));
  }, [boundT]);
  const flushInteractiveSafely = useCallback(async () => {
    try { return { ok: true as const, html: await flushInteractiveEdits() }; }
    catch { onInteractiveSourceError(); return { ok: false as const }; }
  }, [flushInteractiveEdits, onInteractiveSourceError]);
  // Save with no visible change still checks an open Interactive text session first — see
  // `unchangedSaveHandlers`' `flushPendingEdits`.
  const flushPendingEdits = useCallback(async () => {
    const flushed = await flushInteractiveSafely();
    if (!flushed.ok) return "failed" as const;
    return flushed.html !== undefined && flushed.html !== savedHtml ? "changed" as const : "unchanged" as const;
  }, [flushInteractiveSafely, savedHtml]);
  const { requestEditHtml: onRequestEditHtml, htmlTextareaRef, consumeJumpFormatting } = useEditorHtmlJump({
    html, contentRevision, flush: flushInteractiveEdits, setView, setDraftHtml, scrollTop: htmlScrollTopRef,
  }, { onError: onInteractiveSourceError });

  /**
   * The shared refresh hook's `applyLatest` — replaces the working copy AND the saved baseline with
   * an externally-written row, the CLEAN-editor half of `use-external-entry-refresh.hooks.ts`'s
   * decision (the dirty half surfaces `pendingExternalVersion` instead and touches nothing here).
   * Reuses {@link applyLoadedPage} so this seeds the exact same fields the mount effect does, then
   * layers on the two things unique to a live re-apply: the HTML tab's `draftHtml` (only re-seeded
   * on tab-switch otherwise — see that effect's own doc) and clearing any stale `saveConflict`,
   * since the version it was raised against is no longer the one loaded.
   *
   * All setters passed in are `useState` setters — referentially stable across renders — so this can
   * safely close over them with an empty dependency array.
   */
  const applyExternalPage = useCallback((fresh: AdminPost) => {
    applyLoadedPage(fresh, { setPage, setTitle, setSlug, setStatus, setTemplateChoice, setSavedTemplateChoice, setHtml, setSavedHtml });
    setDraftHtml(prettifyHtml(pageEditableHtml(fresh)));
    setSaveConflict(null);
    // Bug B, Slice B3 (dev-only instrumentation, pages-redo plan): this bump remounts the Interactive
    // surface (`PageEditorPane`'s `key={contentRevision}`) with no loading state of its own — logged so
    // a future "renders wrong"/"flashes" report can be tied back to an external write instead of
    // guessed at. Removed once Bug B is closed; not covered by a test for that reason (logging only).
    if (import.meta.env.DEV) {
      console.debug("[page-editor] interactive", { phase: "contentRevision:increment", ms: Math.round(performance.now()) });
    }
    setContentRevision((n) => n + 1);
  }, []);

  const prevViewRef = useRef(view);
  useEffect(() => {
    if (view === "html" && prevViewRef.current !== "html") {
      if (!consumeJumpFormatting()) setDraftHtml(prettifyHtml(html));
    }
    prevViewRef.current = view;
  }, [view, html, consumeJumpFormatting]);

  // Leaving the Preview tab collapses (2026-09-16) — the expanded surface only ever shows the
  // preview, so any other view being selected means the operator is done with it. Returning to
  // Preview later therefore always starts collapsed rather than resuming a state they did not ask
  // for this time. Mirrors `use-post-editor.hooks.ts`'s identical effect.
  useEffect(() => {
    if (view !== "preview") setPreviewExpanded(false);
  }, [view]);

  // Escape collapses (2026-09-16) — a raw `document.addEventListener`, not a synthetic React
  // handler, for the reasons `use-post-editor.hooks.ts`'s twin records: nothing here needs to
  // intercept a keystroke the editor itself is using, and a real listener is what a test can
  // dispatch a genuine `KeyboardEvent` against. Deliberately no `preventDefault()`/
  // `stopPropagation()` — nothing on this surface traps focus, and swallowing the event only risks
  // this repo's documented jsdom/React-delegation false-RED trap. The `.page-preview-fab` rendered
  // inside the expanded surface is the exit that always works; this is a convenience on top of it,
  // gated on `previewExpanded` so no listener is registered at all while collapsed.
  useEffect(() => {
    if (!previewExpanded) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") setPreviewExpanded(false);
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [previewExpanded]);

  function togglePreviewExpanded(): void {
    setPreviewExpanded((on) => !on);
  }

  // `PagePreview`'s frame element and its live-measured width — see `usePreviewPaneWidth`'s own doc
  // for why this is a callback ref keyed off the node (the late-mount bug it fixed was found here).
  const { frameRef, paneWidth } = usePreviewPaneWidth();

  /**
   * Persists the working copy against a specific basis row — the version-guarded core both
   * {@link save} and `saveOverwritingConflict` run through.
   *
   * `basis` is the row whose `version` this write claims AND whose `bodyFormat`/`bodyJson`
   * `buildPageSavePlan` reads. Threading it as a parameter rather than closing over `page` is what
   * lets the explicit-overwrite path re-run against a freshly re-read row without waiting for a
   * `setPage` to commit — the same shape `usePostEditor`'s `runSave(statusOverride, expectedVersion)`
   * uses, one step wider because a Page's save plan needs the whole row, not just its version.
   *
   * `htmlOverride` (Interactive flush, 2026-09-23 plan): the just-flushed HTML from
   * `flushInteractiveEdits`, when its caller has one. Threaded explicitly rather than read off the
   * `html` state closed over here — `save`/`saveOverwritingConflict` await the flush BEFORE calling
   * this, but this callback's own `html` closure was captured at render time and can still be one
   * render behind that state update, the same stale-closure trap `usePostEditor`'s equivalent avoids
   * by never needing an async step in between. Falls back to `html` when omitted (undefined — nothing
   * was flushed, or there was nothing to flush).
   *
   * @complexity Time O(1) plus one or two requests; space O(1).
   */
  const runSave = useCallback(
    async (nextStatus: "draft" | "published" | undefined, basis: AdminPost, htmlOverride?: string) => {
      // Claim this call's generation BEFORE the first `await` — see `useSettlementGeneration`'s own
      // doc for why a synchronous ref bump, not `useState`, is what makes two overlapping calls each
      // see the other's claim.
      const generation = settlement.next();
      const bodyHtml = htmlOverride ?? html;
      setSaving(true);
      setError(null);
      setMessage(null);
      setSaveConflict(null);
      // What to send each route, and whether `updatePageHtml` fires at all, is `buildPageSavePlan`'s
      // decision (`../rules.ts`) — see that function's own doc, and `pageAcceptsHtmlBody`'s, for the
      // full reasoning (moved there verbatim under the 2026-08-12 complexity-ceiling pass, widened
      // 2026-09-06 so a brand-new Page's hand-authored HTML is savable at all, and given the
      // optimistic-concurrency basis 2026-09-07).
      //
      // `updatePost` needs a round-tripped `bodyJson` for every Page still in doc format
      // when metadata is written, including one the subsequent HTML route will convert:
      // `features/post/post.ts`'s `updatePost` requires it to be a JSON object for any Page
      // not already in `html` format. It is meaningless for an html-format row (no Tiptap document
      // exists) so the server skips the check there, but a doc-format row's `bodyJson` IS its real
      // content. This editor has no way to EDIT that document, so round-tripping the loaded value
      // unchanged satisfies the requirement without touching it — the alternative (omitting it)
      // throws "bodyJson must be a JSON object" and leaves title/slug/status stuck un-editable for
      // every doc-format Page.
      const plan = buildPageSavePlan(basis, { title, slug, status, templateChoice, html: bodyHtml }, nextStatus);
      try {
        const updated = await write.mutate({ input: () => writePage(port, basis.id, plan, bodyHtml) }) as AdminPost;
        // A newer save/publish claimed a later generation while this call was awaiting — that call
        // owns the outcome now, so this stale response must not paint over it (2026-09-05
        // stale-settlement sweep: "last-to-settle wins" rather than "last-clicked wins").
        if (!settlement.isCurrent({ generation })) return;
        applySavedPage(
          updated,
          { templateChoice, html: bodyHtml, nextStatus, basisVersion: basis.version },
          plan.canSaveHtml,
          { setPage, setSlug, setStatus, setSavedTemplateChoice, setSavedHtml, setMessage },
          t,
          locale,
        );
        // The real content just landed — any parked standing draft is now obsolete. Not awaited:
        // this is best-effort background bookkeeping (errors are already caught inside the hook),
        // not part of what "Save succeeded" means to the operator.
        void autosave.clearStandingDraft();
        // A successful rename retires the old slug; reloads and shared links must use the new one.
        if (updated.slug !== basis.slug) navigate(pageAdminPath(updated), { replace: true });
      } catch (e) {
        if (!settlement.isCurrent({ generation })) return;
        autosave.preserveFailedSave({ error: e, draft: buildPageAutosaveDraft(basis, { title, slug, html: bodyHtml }) });
        applySaveFailure(
          e,
          nextStatus,
          { templateChoice },
          { setPage, setSlug, setStatus, setSavedTemplateChoice, setSaveConflict, setError },
          t,
          locale,
        );
      } finally {
        // Same generation check as the two branches above: only the call that is still current
        // should flip the shared `saving` flag back off, or an older call's own settlement could
        // briefly re-enable Save/Publish while a newer call is still in flight.
        if (settlement.isCurrent({ generation })) setSaving(false);
      }
    },
    [html, title, slug, status, templateChoice, locale, port, navigate, t, settlement, autosave.clearStandingDraft, autosave.preserveFailedSave]
  );

  /**
   * Persists the working copy against the version this editor loaded — see {@link runSave}.
   *
   * Save is only reachable once `page` has loaded — `PageEditor.tsx` shows a loading notice and
   * renders no Save/Publish button until then — but the guard keeps `page.id` sound without a
   * non-null assertion, and mirrors `usePostEditor`'s identical `remove` guard.
   */
  const save = useCallback(
    async (nextStatus?: "draft" | "published") => {
      if (!page) return;
      // Interactive flush (2026-09-23 plan) — closes any RTE session still open on the Interactive
      // tab so its pending edit is part of this save, not lost. See `runSave`'s `htmlOverride` doc for
      // why the result is threaded through explicitly rather than left to `runSave`'s own `html`
      // closure.
      const flushed = await flushInteractiveSafely();
      if (!flushed.ok) return;
      await runSave(nextStatus, page, flushed.html);
    },
    [page, runSave, flushInteractiveSafely]
  );

  /**
   * The operator's explicit overwrite after a conflict — see
   * {@link PageEditorController.saveOverwritingConflict}.
   *
   * Re-reads the row purely for its current `version` and body format: the response's title/slug/
   * body are deliberately NOT applied to the working copy, because doing so is exactly the "your
   * typed work disappeared" outcome this whole path exists to avoid. `attemptedStatus` replays the
   * ORIGINAL intent, so a rejected Publish retries as a publish rather than quietly downgrading to
   * a draft. Mirrors `usePostEditor`'s `saveOverwritingConflict` verbatim.
   */
  const saveOverwritingConflict = useCallback(async () => {
    if (!page) return;
    const attemptedStatus = saveConflict?.attemptedStatus;
    const fresh = await readPage(page.id).then(({ post }) => post, () => null);
    if (!fresh) {
      setError(t(locale, "could not re-read the current version — your changes are still here, try again"));
      return;
    }
    setPage(fresh);
    // Interactive flush (2026-09-23 plan) — same reasoning as `save`'s own call.
    const flushed = await flushInteractiveSafely();
    if (!flushed.ok) return;
    await runSave(attemptedStatus, fresh, flushed.html);
  }, [page, port, runSave, saveConflict, t, locale, flushInteractiveSafely]);

  /** Hides the conflict banner without saving — see
   *  {@link PageEditorController.dismissSaveConflict}. */
  const dismissSaveConflict = useCallback(() => setSaveConflict(null), []);

  const remove = useCallback(async () => {
    if (!page) return;
    setDeleting(true);
    setError(null);
    try {
      await write.mutate({ input: () => port.deletePage(page.id) }) as Awaited<ReturnType<typeof port.deletePage>>;
      navigate("/pages");
    } catch (e) {
      setError(e instanceof Error ? e.message : t(locale, "failed to delete page"));
      setDeleting(false);
      setConfirmingDelete(false);
    }
  }, [page, locale, port, navigate, t]);

  // Pending-html preview (2026-09-09) — see `PageEditorController.previewFormRef`'s own doc. The
  // hidden form's DOM node; `PagePreview` attaches it via `ref`. `previewFormTarget` is `""` before
  // `page` loads for the same reason `templatePreviewUrl` below is — `PagePreview` never renders
  // that early.
  // Node in state, not a `RefObject` — see `PageEditorController.previewFormRef`'s own doc.
  const [previewForm, previewFormRef] = useState<HTMLFormElement | null>(null);
  const previewFormTarget = pagePreviewFormTarget(page);

  // Per-tab scroll memory, Preview half — see `PageEditorController.onPreviewFrameLoad`'s own doc.
  const previewScrollYRef = useRef(0);
  const onPreviewFrameLoad = useCallback((iframe: HTMLIFrameElement) => {
    try {
      // Cross-origin (the live-site branch): reading `.scrollY` or calling `.scrollTo()` on a foreign
      // `Window` throws a `SecurityError` — caught below, so that branch's position is simply never
      // remembered rather than crashing the load handler. The template-preview branch is opaque-origin
      // too since 2026-10-05 (`PAGE_PREVIEW_IFRAME_SANDBOX` has no `allow-same-origin`).
      const win = iframe.contentWindow;
      if (!win) return;
      win.scrollTo(0, previewScrollYRef.current);
      win.addEventListener("scroll", () => {
        previewScrollYRef.current = win.scrollY;
      });
    } catch {
      // See this function's own doc on `PageEditorController` — cross-origin, nothing to do here.
    }
  }, []);

  // Tells the assistant which page "this page" is (`lib/agent-screen-context.ts`) — the saved row,
  // so the id/slug it is given are ones its tools can actually look up.
  useAgentScreenEntry(page === null ? null : { kind: page.kind, id: page.id, title: page.title, slug: page.slug, status: page.status });

  // Template-preview fix (2026-08-11) — see `contentDirty`'s doc on `PageEditorController`.
  const contentDirty = computeContentDirty(page, { title, slug, status, html, savedHtml });
  // The Save button's own "is there anything unsaved" signal — split out to a named variable (was
  // previously inlined at the return statement) so `useExternalEntryRefresh`'s `isDirty` below reads
  // the SAME value `dirty` reports, rather than a second copy of this expression that could drift.
  const dirty = contentDirty || templateChoice !== savedTemplateChoice;

  // Content refresh (2026-09-16) — see `use-external-entry-refresh.hooks.ts`'s file header for the
  // clean/dirty/saving decision this wraps, and `PAGES_RESOURCE`'s own doc (`rules.ts`) for the bug
  // this closes: `pages_write_html`/`pages_write_region` are agent-callable, and this editor never
  // re-read its row after one fired. `loaded`/`isDirty`/`isSaving` are read through the hook's own
  // ref on every check, so listing `dirty`/`saving`/`page` in a dependency array here is unnecessary.
  // `isDirty` is wider than `dirty` on the Interactive tab — see `pageRefreshMayHaveUnsavedEdits`.
  const externalRefresh = useExternalEntryRefresh<AdminPost>({
    loaded: page,
    fetchLatest: (id) => readPage(id).then(({ post }) => post),
    isDirty: () => pageRefreshMayHaveUnsavedEdits({ dirty, view }),
    isSaving: () => saving,
    applyLatest: applyExternalPage,
    discardStandingDraft: autosave.clearStandingDraft,
    supersedeStandingDraftBasis: autosave.supersedeBasis,
    onLoadLatestFailed: () => setError(t(locale, "could not re-read the current version — your changes are still here, try again")),
  });
  useContentRefreshSubscription(PAGES_RESOURCE, externalRefresh.checkForExternalChange);

  // Unsaved-work guard (2026-09-06, alongside standing-draft autosave — audit finding: this screen
  // had none at all, unlike `usePostEditor`'s own `useDirtyGuard` call). Same five-field comparison
  // `dirty` above already makes (title/slug/status/body/templateChoice), just handed to the guard
  // instead of computed inline, so `confirmLeave`/the automatic `beforeunload` listener agree with
  // what the Save button itself considers dirty.
  const { confirmLeave } = useDirtyGuard(
    {
      current: { title, slug, status, html, templateChoice },
      original: pageDirtyGuardBaseline(page, savedHtml, savedTemplateChoice),
    },
    { host: window, translate: (key) => key },
  );

  const onBackLinkClick = useCallback(
    async (event: { preventDefault: () => void }) => {
      if (!interactiveEditorRef.current) {
        if (!confirmLeave()) event.preventDefault();
        return;
      }
      event.preventDefault();
      const flushed = await flushInteractiveSafely();
      if (!flushed.ok) return;
      if (confirmLeave({}, { unsavedBeyondTracked: flushed.html !== undefined && flushed.html !== savedHtml })) navigate("/pages");
    },
    [confirmLeave, flushInteractiveSafely, savedHtml, navigate]
  );

  // Standing-draft autosave scheduling — fires a debounced write whenever the working copy actually
  // differs from what's saved. Deliberately does NOT clear the draft when `contentDirty` goes back
  // to `false` on its own (e.g. the operator edits back to the original value): only a real
  // Save/Publish or an explicit Discard ever clears a parked draft (see `save`'s own
  // `clearStandingDraft` call, and `discardRecoveredDraft` below) — auto-clearing here on a merely
  // quiet moment is not one of those two things.
  useEffect(() => {
    if (!page || !contentDirty) return;
    autosave.scheduleAutosave(buildPageAutosaveDraft(page, { title, slug, html }));
  }, [page, contentDirty, title, slug, html, autosave.scheduleAutosave]);

  // Pending-html preview's debounced auto-submit (2026-09-09) — see `PageEditorController
  // .previewFormRef`'s own doc. `active` mirrors the negation of `PagePreview`'s own
  // `canShowLiveSite` (see that function's doc): true whenever the operator isn't looking at the
  // live site, regardless of
  // `status` or `contentDirty` — a draft, or a published-but-dirty Page, both need their pending
  // `html` POSTed into the preview iframe the same way. Computed inline here (not read off a
  // `dirty`/`canShowLiveSite` controller field) because none exists — `PagePreview` recomputes the
  // identical condition itself from `status`/`dirty`, the same duplication
  // `use-post-editor.hooks.ts`'s own `canShowPendingContentPreview` already accepts between the hook
  // and its view for the same reason (cheap, O(1), and keeps the controller's own field surface
  // unchanged).
  useEffect(
    () =>
      schedulePendingHtmlPreviewSubmit({
        active: view === "preview" && page !== null && !(status === "published" && !contentDirty && templateChoice === savedTemplateChoice),
        form: previewForm,
      }),
    // `page?.id`, not `page` — same reasoning `use-post-editor.hooks.ts`'s identical effect gives:
    // a `setPage(updated)` after a successful save (a new object reference, same id) must not by
    // itself restart the debounce timer. `contentRevision` IS added (2026-09-16): a clean editor's
    // silent external apply changes `html`/`title`/etc. without ever changing `view`/`status`/
    // `templateChoice`, so without this the pending preview would sit on the pre-write body until
    // some unrelated field also happened to change.
    // `previewForm` (2026-10-05): a newly mounted form + iframe pair is empty until submitted into,
    // so a remount alone must re-arm — see `PageEditorController.previewFormRef`'s own doc.
    [view, page?.id, status, contentDirty, templateChoice, savedTemplateChoice, html, contentRevision, previewForm]
  );

  const restoreRecoveredDraft = useCallback(() => {
    const draft = autosave.recoverableDraft;
    if (!draft) return;
    setTitle(draft.title);
    setSlug(draft.slug);
    if (draft.bodyFormat === "html" && draft.bodyHtml !== undefined) {
      setHtml(draft.bodyHtml);
      // Same two re-seeds `applyExternalPage` makes: the HTML tab shows `draftHtml`, not `html`, and
      // the Interactive canvas reads `html` only at mount. Without them, restoring on either tab
      // left the old body on screen and the next edit wrote it back over the restored draft.
      setDraftHtml(prettifyHtml(draft.bodyHtml));
      setContentRevision((n) => n + 1);
    }
    autosave.dismissRecoverable();
  }, [autosave.recoverableDraft, autosave.dismissRecoverable]);

  const discardRecoveredDraft = useCallback(async () => {
    await autosave.clearStandingDraft();
  }, [autosave.clearStandingDraft]);

  // Interactive flush (2026-09-23 plan) — "flush, then set" wrappers around the raw `setView`/
  // `setTemplateChoice` state setters (declared above, at `useState`). Leaving Interactive without
  // flushing first is exactly the same edit-loss bug a save without flushing is: switching tabs or
  // templates remounts/restyles the canvas, and GrapesJS never got the chance to sync a still-open
  // RTE session first. `PageEditorController` exposes THESE, not the raw setters, so every caller
  // (`PageEditor.tsx`'s tab bar and template picker) gets the flush for free; the raw setters stay
  // internal (`applyLoadedPage`'s callers below still use them directly — loading a row is not an
  // edit to flush anything against).
  //
  // `interactiveEditorRef.current` is checked SYNCHRONOUSLY first: with nothing mounted (not on the
  // Interactive tab, or the tab never visited this session — the overwhelmingly common case for
  // every OTHER tab's own setView/setTemplateChoice call), there is nothing to flush, so this applies
  // immediately rather than forcing every caller through an async microtask for no reason.
  const setViewAfterFlush = useCallback(
    (next: PageEditorView) => {
      if (!interactiveEditorRef.current) {
        setView(next);
        return;
      }
      void flushInteractiveSafely().then(result => {
        // HTML remains available on an integrity failure, showing the last intact working copy.
        if (result.ok || next === "html") setView(next);
      });
    },
    [flushInteractiveSafely]
  );
  const setTemplateChoiceAfterFlush = useCallback(
    (next: string | null) => {
      if (!interactiveEditorRef.current) {
        setTemplateChoice(next);
        return;
      }
      void flushInteractiveSafely().then(result => { if (result.ok) setTemplateChoice(next); });
    },
    [flushInteractiveSafely]
  );

  // See `templatePreviewUrl`'s own doc on `PageEditorController` for why this is a plain per-render
  // expression rather than state or a `useMemo`.
  const templatePreviewUrl = page ? port.templatePreviewUrl(page.id, templateChoice) : "";

  // `templateChoice` (not `savedTemplateChoice`): the Interactive canvas must mirror the template the
  // operator is CURRENTLY looking at in the picker, the same one `templatePreviewUrl` above resolves —
  // switching templates should restyle the canvas immediately, without a save round-trip. The 4th
  // argument is what supplies the canvas its content wrapper: the theme template's own ancestor chain
  // around the `{"type":"content"}` marker (`<main><article class="post-detail wrap">` in `basic`'s
  // `posts-default.html`, `blog-post.html` before the 2026-09-03 posts-*/pages-* rename). Without it
  // the canvas renders the page body naked at full bleed while the published page centres it in a
  // 720px column — same CSS, same tokens, no container.
  //
  // Run through `resolveCanvasTemplateChoice` rather than passed straight through: only a `null`
  // (never-chosen) `html`-format Page is the case a `static`-tier theme's real render mirrors through
  // its own page shell (`pages-default.html`, or legacy `page-shell.html`) — see that function's own
  // doc. Since the bare-page ruling (2026-09-23, S6), `""` is a DIFFERENT case — an explicit "No
  // template" that renders with no wrapper at all — and `resolveCanvasTemplateChoice` no longer routes
  // it into the shell; `useThemeCanvasStyling` short-circuits it to `NO_CANVAS_STYLING` instead.
  // `page?.bodyFormat ?? "doc"` is the same "nothing risky before load" default `templatePreviewUrl`
  // above and `contentDirty` below already use for a not-yet-loaded page.
  const canvasStyling = useThemeCanvasStyling(
    activeThemeId,
    activeThemeApiVersion,
    themeCanvasPort,
    resolveCanvasTemplateChoice(templateChoice, page?.bodyFormat ?? "doc"),
  );

  return {
    page,
    error,
    message,
    title,
    setTitle,
    slug,
    setSlug,
    status,
    setStatus,
    templateChoice,
    setTemplateChoice: setTemplateChoiceAfterFlush,
    availableTemplates,
    activeThemeId,
    activeThemeTier,
    activeThemeApiVersion,
    showTemplateModal,
    // Thin wiring closures, same "one-line handler named and moved out of JSX" shape
    // `usePostEditorUi`'s identical pair documents — kept inline here rather than a separate
    // `use-page-editor-ui.hooks.ts` since Pages has only these two UI-only handlers today, not the
    // half-dozen `usePostEditorUi` composes.
    onViewTemplateClick: () => setShowTemplateModal(true),
    onCloseTemplateModal: () => setShowTemplateModal(false),
    html,
    setHtml,
    draftHtml,
    setDraftHtml,
    htmlTextareaRef,
    onHtmlScroll,
    onPreviewFrameLoad,
    view,
    setView: setViewAfterFlush,
    device,
    setDevice,
    previewExpanded,
    togglePreviewExpanded,
    frameRef,
    paneWidth,
    saving,
    t: boundT,
    embedPlaceholderDescriber,
    onRequestEditHtml,
    onInteractiveSourceError,
    interactiveEditorRef,
    setHtmlFromCanvas,
    // HTML changes only count when they're actually savable (see `save()`'s `canSaveHtml`) — for a
    // doc-format Page, `html` never reflects real persisted content, so comparing it to `savedHtml`
    // would report edits as dirty (or, worse, as clean) independent of anything actually saveable.
    //
    // Split into `contentDirty` (title/slug/status/body) plus the `templateChoice` comparison, rather
    // than one combined expression, so `PagePreview` can tell "only the template picker moved" apart
    // from "the operator actually edited something" — see `contentDirty`'s own doc on
    // `PageEditorController` for why that distinction exists.
    contentDirty,
    dirty,
    templatePreviewUrl,
    previewFormRef,
    previewFormTarget,
    canvasStyling,
    save,
    saveConflict,
    saveOverwritingConflict,
    dismissSaveConflict,
    remove,
    confirmingDelete,
    setConfirmingDelete,
    confirmingUnchangedSave,
    ...unchangedSaveHandlers({ dirty, save: () => save(), setConfirmingUnchangedSave }, { flushPendingEdits }),
    deleting,
    confirmLeave,
    onBackLinkClick,
    recoverableDraft: autosave.recoverableDraft,
    restoreRecoveredDraft,
    discardRecoveredDraft,
    autosaveStaleBasis: autosave.staleBasis,
    pendingExternalVersion: externalRefresh.pendingExternalVersion,
    loadExternalChange: externalRefresh.loadExternalChange,
    dismissExternalChange: externalRefresh.dismissExternalChange,
    contentRevision,
  };
}

/**
 * Binds the real `/api/.../pages` client, `lib/router`'s `navigate`, and `page-editor-i18n`'s `t` —
 * see `page-editor-dependencies.hooks.ts`.
 *
 * The zero-argument half of the `useX(dependencies)` / `useWiredX()` pair, so `PageEditor.tsx`
 * composes this and a test composes {@link usePageEditor} with `createFakePageEditorPort`.
 * `useAdminLocale()` is called here, not injected as a hook reference — its resolved `locale` value
 * is what `usePageEditor` actually consumes (every internal use is `t(locale, ...)`), and there is no
 * precedent in this codebase for injecting a hook reference instead of the value it resolves to.
 */
export function useWiredPageEditor(routeSlug: string): PageEditorController {
  const locale = useAdminLocale();
  return usePageEditor(routeSlug, {
    port: defaultPageEditorPort,
    themeCanvasPort: defaultThemeCanvasPort,
    navigate: defaultNavigate,
    t: defaultT,
    locale,
  });
}

import { useFetchQuery, useFetchMutation, useCachedLoader, useInvalidate } from "@jini-ai/ui/fetch-query";
import { useCallback, useMemo, useState } from "react";

import { type AdminPost } from "@/lib/api";
import { navigate as defaultNavigate } from "@/lib/router";
import { useAdminLocale } from "@/hooks/use-admin-locale.hooks";
import { useContentRefreshSubscription } from "@/hooks/use-content-refresh-subscription.hooks";
import { type Translate } from "@jini-ai/ui/panel-kit";
import { t as translate } from "../pages-i18n";
import { buildPageRowMenuHandleMap, pageAdminPath, PAGES_RESOURCE } from "../rules";
import { defaultPagesPort } from "./pages-dependencies.hooks";
import type { PagesPort } from "./pages-port.hooks";

/**
 * @file Everything the Pages LIST does, so `Pages.tsx` is only markup.
 *
 * Extracted verbatim — same state, same order, same effect, same error strings. Mirrors
 * `features/posts/hooks/use-posts.hooks.ts` exactly, since `Pages.tsx` is `Posts.tsx`'s twin,
 * backed by the pages-filtered endpoints (`GET/POST .../pages`). A page is a `post` row with
 * `kind: "page"` (see `features/post/post.ts`), so it's edited through the same `PostEditor`
 * reached via `/admin/posts/{id}`.
 *
 * The doc comments below moved WITH the functions they describe. `removePage`'s is a decision
 * record — why the delete copy says what it says — that `posts/hooks/use-posts.hooks.ts`'s
 * `removePost` points at as its source; a comment separated from its code stops being read.
 *
 * Naming follows `hooks/use-settings-slice.hooks.ts` and `hooks/use-dirty-guard.hooks.ts`:
 * `use-<thing>.hooks.ts`. Feature-local because nothing outside `features/pages` needs it.
 *
 * `port`/`navigate` are injected — see `pages-port.hooks.ts` — rather than reaching `lib/api`/
 * `lib/router` directly, so a test can describe load/create/publish-toggle/delete outcomes against
 * `createFakePagesPort` instead of stubbing global `fetch`. `useWiredPages` below is the
 * zero-argument pair `Pages.tsx` actually mounts. This hook's OWN error strings stay hardcoded
 * English, unlike `use-collections.hooks.ts`'s locale-aware fallbacks — but `t`/`locale` are still
 * injected (2026-08-11, standing i18n rule — a component with a hook gets a BOUND `t` from that
 * hook, not its own `useAdminLocale()`/dictionary import, same shape `use-post-editor.hooks.ts`
 * established) purely so `Pages.tsx` has somewhere to source the UI copy it renders. `locale`
 * itself is also exposed, not just `t`: `Pages.tsx` passes the raw string on to
 * `pageRowMenuItems` (`../rules.ts`), which keeps its own independent `PAGES_DICT[locale]?.[key]
 * ?? key` closure unchanged — same "row-menu builder is a different, out-of-scope thing" precedent
 * `use-post-editor.hooks.ts`'s own header cites for `postRowMenuItems`.
 */

export interface PagesController {
  /** `null` until the initial load settles — the caller renders a loading state. */
  pages: AdminPost[] | null;
  error: string | null;
  creating: boolean;
  /** In-flight row action (Publish/Unpublish, or the confirmed Delete) — one at a time. */
  rowSavingId: string | null;
  /** The page a `RowMenu` "Delete" selection is asking to confirm; `null` when the dialog is shut. */
  pendingDelete: AdminPost | null;
  setPendingDelete: (page: AdminPost | null) => void;
  createPage: () => Promise<void>;
  togglePagePublish: (page: AdminPost) => Promise<void>;
  removePage: () => Promise<void>;
  /** Bound translator — `Pages.tsx`'s only source of UI copy; see this file's own header. */
  t: Translate;
  /** The raw resolved locale — exposed only because `pageRowMenuItems` (`../rules.ts`) genuinely
   *  needs it, not `t`. */
  locale: string;
  /** Each page's row-menu agent handle, keyed by page id — looked up by ID, never by render
   *  position. See {@link usePageRowMenuHandleMap}'s own doc for why. */
  rowMenuHandleById: Map<string, string>;
}

/**
 * `DataTable` sorts internally from `sort` + each column's own comparator — `pages` is passed
 * through unsorted, and only `DataTable`'s own render order changes as `sort` changes. Handles are
 * built once from `pages`' own stable order and looked up BY ID in each cell, rather than by render
 * position: `buildPageRowMenuHandleMap`'s own contract derives a handle from each id, not its
 * position, specifically so a control keeps the same handle even after the table reorders — which
 * is exactly what re-sorting does. Memoized on `pages` alone so re-sorting or any other unrelated
 * re-render (`sort`, `locale`) does not rebuild this map and hand `RowMenu` a new handle-string
 * identity every time. Mirrors `use-posts.hooks.ts`'s `usePostRowMenuHandleMap` verbatim.
 */
export function usePageRowMenuHandleMap(pages: AdminPost[] | null): Map<string, string> {
  return useMemo(() => buildPageRowMenuHandleMap(pages), [pages]);
}

export interface PagesDependencies {
  port: PagesPort;
  navigate: (path: string) => void;
  t: Translate;
  locale: string;
}

/**
 * The content-refresh subscription invalidates the shared list whenever pages_write_html
 * (apps/website/src/features/pages/agent-tools.ts) writes a page from an assistant run this
 * screen otherwise has no way to learn about. Like the Posts twin, retained query data keeps
 * the table rendered across background refreshes instead of flashing a first-load skeleton.
 *
 * The 2026-09-07 settlement fix (formerly useSettlementGeneration) remains necessary:
 * the content-refresh subscription means two listPages calls can be
 * in flight at once with no ordering guarantee on their responses — two assistant writes landing
 * back to back each publish their own refresh notification. Without this guard, whichever request
 * happened to resolve LAST won regardless of which one was issued last, so a slower, earlier
 * (now-stale) response could overwrite the newer list an operator is already looking at.
 * Cache invalidation now revokes the older request's ownership synchronously before the new
 * read starts, so both superseded successes and failures follow the latest request.
 */
export function usePages(deps: PagesDependencies): PagesController {
  const { port, navigate, t, locale } = deps;
  const key = useMemo(() => ["pages", "list"] as const, []);
  const fetchList = useCallback(async () => {
    try { return (await port.listPages()).posts.map(entry => entry.post); }
    catch (error) { throw new Error(error instanceof Error ? error.message : "failed to load pages"); }
  }, [port]);
  // Mount reads and content-refresh invalidations can overlap. The shared cache revokes the
  // older request's ownership before starting the newer read, so a late success or failure
  // cannot replace the latest list. Background reads retain the rendered table.
  const query = useFetchQuery({ key, fetch: fetchList }, { staleTime: 0 });
  const loader = useCachedLoader({ key, fetch: fetchList }, { staleTime: 0 });
  const pages = query.data ?? null;
  function setPages(update: (current: AdminPost[] | null) => AdminPost[] | null) {
    const next = update(loader.peek() ?? null);
    if (next !== null) loader.replace({ value: next });
  }
  const invalidate = useInvalidate();
  const write = useFetchMutation({ run: ({ input }: { input: () => Promise<unknown> }) => input() }, { invalidates: [["pages"]] });
  const [actionError, setError] = useState<string | null>(null);
  const error = actionError ?? query.error?.message ?? null;
  const [creating, setCreating] = useState(false);
  // In-flight row action (Publish/Unpublish or the confirmed Delete) — one at a time, same `rowSavingId`
  // convention `Roles.tsx`'s `onDeleteRole` already uses, per `ConfirmButton`'s own doc comment.
  const [rowSavingId, setRowSavingId] = useState<string | null>(null);
  // The page a `RowMenu` "Delete" selection is asking to confirm — `null` when the dialog is
  // closed. `ConfirmDialog` stays mounted unconditionally in the view (see its own doc comment on
  // why); this is what drives its `open` prop.
  const [pendingDelete, setPendingDelete] = useState<AdminPost | null>(null);

  // Query ownership replaces the latest-wins read guard described above; background
  // refreshes keep the table and cache replacements protect newer mutation responses.
  const load = useCallback(() => invalidate({ key: ["pages"] }), [invalidate]);
  useContentRefreshSubscription(PAGES_RESOURCE, load);

  const rowMenuHandleById = usePageRowMenuHandleMap(pages);

  async function createPage() {
    setCreating(true);
    setError(null);
    try {
      const { post } = await write.mutate({ input: () => port.createPage("Untitled") }) as Awaited<ReturnType<typeof port.createPage>>;
      // The Pages editor, not the Posts one. "New Page" and "ask the assistant to build me a page"
      // are two doors to the same destination — neither of them is a Tiptap screen.
      // `pageAdminPath` (`rules.ts`) — same slug-vs-id-vs-root-slug rule `Pages.tsx`'s own row
      // navigation already uses for an existing page (readable-slugs S6a).
      navigate(pageAdminPath(post));
    } catch (e) {
      setError(e instanceof Error ? e.message : "failed to create page");
      setCreating(false);
    }
  }

  /** Flips a row's publish status — Unpublish (-> draft) for a published row, Publish (-> published)
   *  for a draft, matching `pageRowMenuItems`'s own label for whichever direction applies. A
   *  reversible, access-affecting action (not destructive: no `ConfirmDialog`, matching
   *  `ConfirmButton`'s own warning-vs-destructive distinction).
   *
   * Owner rename (2026-09-22) from the old `disablePage`, which only ever flipped published -> draft
   * (`RowMenu`'s item list omitted "Disable" entirely for an already-draft row, rather than
   * rendering it disabled) — a draft page had no way to publish from this list at all, only from the
   * full editor.
   *
   * Sends the row's own `title`/`slug`/`bodyJson` alongside the flipped `status` and
   * `expectedVersion` — `PUT /posts/:id`'s `validateUpdatePostInput` (`features/post/post.ts`)
   * treats a missing `title`/`slug` as `""` and rejects the request with "title is required" before
   * ever reaching the version check, and requires `bodyJson` to be a JSON object for any row whose
   * `bodyFormat` isn't `"html"` — which is exactly what the OLD `{ status, expectedVersion }`-only
   * payload hit (owner screenshot, 2026-09-22): every click 500'd on that validation, regardless of
   * the row's status, and never reached the version guard at all. Round-tripping the row's own
   * already-loaded fields here is safe specifically because they are read from the SAME `page` this
   * call's `expectedVersion` is about to check — a stale basis fails that compare-and-set before any
   * of these fields would actually be written back, so this can never silently overwrite a
   * concurrent edit to title/slug/body.
   *
   * `expectedVersion: page.version` (2026-09-18, multi-author hardening, Task 14a) — mirrors
   * `use-posts.hooks.ts`'s identical `togglePostPublish` fix exactly; see its doc for the full
   * rationale. */
  async function togglePagePublish(page: AdminPost) {
    const nextStatus: AdminPost["status"] = page.status === "published" ? "draft" : "published";
    setRowSavingId(page.id);
    setError(null);
    try {
      const { post: updated } = await write.mutate({ input: () => port.updatePost(
        { id: page.id },
        { title: page.title, slug: page.slug, bodyJson: page.bodyJson, status: nextStatus, expectedVersion: page.version }
      ) }) as Awaited<ReturnType<typeof port.updatePost>>;
      setPages((prev) => (prev ? prev.map((p) => (p.id === updated.id ? updated : p)) : prev));
    } catch (e) {
      setError(e instanceof Error ? e.message : `failed to ${nextStatus === "published" ? "publish" : "unpublish"} page`);
    } finally {
      // Only clear THIS row's lock — `rowSavingId` is shared with `removePage`'s delete-in-flight
      // lock (2026-09-20, S4b hardening; mirrors `use-posts.hooks.ts`'s identical fix). An
      // unconditional `setRowSavingId(null)` here would wipe a DIFFERENT row's delete lock if that
      // row's confirm landed while this toggle was still in flight, making the dialog read as
      // settled (dismissable, re-confirmable) while the delete is still on the wire.
      setRowSavingId((cur) => (cur === page.id ? null : cur));
    }
  }

  /** Soft delete: `api.deletePage` does hit a soft-delete route that is genuinely revertible
   * server-side (see api.ts's own doc on deletePage) — but the confirm copy below states only the
   * observable consequence and does NOT claim recoverability. There is no restore path an
   * operator can reach from this product today (no change-set-revert UI, no api.ts method for it;
   * `Recovery.tsx` is a different, much heavier whole-database snapshot restore, not a per-row
   * undo). Promising an undo the operator cannot actually perform would be worse than promising
   * nothing. Equally, do not swap it for "permanently delete" / "cannot be undone" — that
   * overcorrects into the opposite lie, since the row genuinely is recoverable server-side, just
   * not from here. On success the row is dropped from local state rather than a full reload,
   * matching this screen's existing preference for optimistic-from-response local updates.
   *
   * Confirmation now gates via a `ConfirmDialog` modal, reached through `RowMenu`'s "Delete" item,
   * rather than `ConfirmButton`'s in-place two-click control or `window.confirm` — a further
   * upgrade over MSG-03's `ConfirmButton` pass on this same screen's twin (`Posts.tsx`): that
   * component was itself chosen at the time because `styles.css` was locked to a concurrently-
   * editing agent and a modal needed new markup/CSS this pass could not add (see
   * `ConfirmButton.tsx`'s own file header). Neither constraint holds for this dispatch, and a
   * modal disclosure ("Move "X" to trash? It will disappear from the site and from this list.")
   * reads as a deliberate decision point rather than a label change on a button already sitting in
   * a menu the operator just opened. */
  async function removePage() {
    if (!pendingDelete) return;
    const page = pendingDelete;
    setRowSavingId(page.id);
    setError(null);
    try {
      await write.mutate({ input: () => port.deletePage(page.id) });
      setPages((prev) => (prev ? prev.filter((p) => p.id !== page.id) : prev));
    } catch (e) {
      setError(e instanceof Error ? e.message : "failed to delete page");
    } finally {
      // Symmetric guard to `togglePagePublish`'s — see its comment. Keeps this correct regardless of
      // which of the two in-flight actions settles first.
      setRowSavingId((cur) => (cur === page.id ? null : cur));
      setPendingDelete(null);
    }
  }

  return {
    pages,
    error,
    creating,
    rowSavingId,
    pendingDelete,
    setPendingDelete,
    createPage,
    togglePagePublish,
    removePage,
    t,
    locale,
    rowMenuHandleById,
  };
}

/**
 * Binds the real `/api/.../pages` client, `lib/router`'s `navigate`, and a `t` bound to the real
 * resolved locale (`useAdminLocale()`, called here and ONLY here — see this file's header) — see
 * `pages-dependencies.hooks.ts`. The zero-argument half of the `useX(dependencies)` /
 * `useWiredX()` pair, so `Pages.tsx` composes this and a test composes {@link usePages} with
 * `createFakePagesPort` and a fake `navigate`/`t`.
 */
export function useWiredPages(): PagesController {
  const locale = useAdminLocale();
  const t = (key: string): string => translate({ locale: locale, key: key });
  return usePages({ port: defaultPagesPort, navigate: defaultNavigate, t, locale });
}

import { useEffect, useState } from "react";

import type { CanvasStyling } from "@jini-ai/ui/html-editor";
import { resolveThemeLayout } from "@tovu/theme-layout";

import type { ThemeCanvasPort, ThemeTokens } from "./theme-canvas-port.hooks";
import { deriveContentWrapperChain } from "./theme-canvas-wrapper";

/**
 * @file Resolves the CSS the Pages editor's Interactive tab renders its canvas against, so the
 * operator edits a page looking roughly like the published one instead of against browser defaults
 * (Times on white, which is what that tab showed for every page before this existed).
 *
 * The published page's appearance comes from two things, not one — `src/server/http/site/render.ts`
 * and `features/theme/static-render.ts` emit both into every rendered document:
 *
 * 1. `<link rel="stylesheet" href="/theme-assets/{themeId}/css/theme.css">` — the theme's own rules.
 * 2. An inline `:root { --bg: …; --fg: … }` block built from the theme's `tokens.json`.
 *
 * Only (1) is a fetchable stylesheet; (2) is generated per render and has no URL. Loading (1) alone
 * is not a partial improvement but a visual no-op — a v2 theme's `css/theme.css` reads `var(--x)`
 * exclusively and defines no token itself (that file's own header says so), so without (2) every
 * color, font, and spacing value resolves to nothing. That is why this hook fetches the token files
 * rather than just handing the editor a stylesheet URL, and why a failed token fetch falls all the
 * way back to no canvas styling at all instead of shipping the stylesheet on its own.
 */

/** `/theme-assets/{themeId}/{relativePath}` — `theme-static-assets.ts`'s `express.static` mount,
 *  reached from the admin origin in dev through `apps/admin/vite.config.ts`'s `/theme-assets` proxy
 *  rule. `encodeURIComponent` on the theme id only: a theme id containing a space or `?` would
 *  otherwise 404 or be parsed as a query string, while `relativePath`'s own `/` separators are real
 *  path segments and must stay unencoded. */
function themeAssetUrl(themeId: string, relativePath: string): string {
  return `/theme-assets/${encodeURIComponent(themeId)}/${relativePath}`;
}

/** The active theme's one required stylesheet, at the path its own `apiVersion` puts it
 *  (`css/theme.css` for v2, `css/styles.css` for v1) — resolved through `@tovu/theme-layout`, the
 *  same resolver the server render uses, rather than a second independently-spelled literal. */
export function themeStylesheetUrl(themeId: string, apiVersion: 2 | undefined): string {
  return themeAssetUrl(themeId, resolveThemeLayout(apiVersion).stylesheetPath);
}

/** The theme's default-mode token file. Required — `theme.ts` treats its absence as a load failure
 *  that invalidates the whole theme. */
export function themeTokensUrl(themeId: string): string {
  return themeAssetUrl(themeId, "tokens.json");
}

/** The theme's light-mode token file. Optional by contract (`theme.ts`: "absent is not an error, it
 *  just means the theme ships no light variant"), so a rejected fetch for this one is expected, not
 *  a failure. */
export function themeLightTokensUrl(themeId: string): string {
  return themeAssetUrl(themeId, "tokens.light.json");
}

/** A theme template's own raw markup — same `render/pages`(v2)/`pages`(v1) folder
 *  `resolveThemeLayout` already gives `themeStylesheetUrl`, just a template filename instead of the
 *  stylesheet. Marker still present, unresolved — see `theme-canvas-wrapper.ts`'s file header for what
 *  this is fed into. `templateChoice` is encoded (unlike `pagesDir`'s own `/`, a real path segment):
 *  it is one filename, never a path, so `encodeURIComponent` cannot legitimately need to leave
 *  anything in it unencoded the way `themeAssetUrl`'s `relativePath` sometimes does. */
export function templateMarkupUrl(themeId: string, apiVersion: 2 | undefined, templateChoice: string): string {
  return themeAssetUrl(themeId, `${resolveThemeLayout(apiVersion).pagesDir}/${encodeURIComponent(templateChoice)}`);
}

/** The Tovu-owned canonical document-shell filename(s) a `static`-tier theme ships for a
 *  `kind: "page"`, `bodyFormat: "html"` row with no explicit template choice — the browser-side twin
 *  of `STATIC_TIER_PAGE_SHELL_IDS` in `apps/website/src/features/theme/static-render.ts` (see
 *  `resolveStaticTierPageShellFallback` there), which the live render path consults for exactly this
 *  case. That module is server/Node-only (its theme discovery reads real files off disk) and is not
 *  exposed through `@tovu/theme-layout`, the one deliberately-pure cross-runtime module this file
 *  already imports from (see this file's own header) — so its constant cannot be imported here the
 *  way `resolveThemeLayout` is. This is the one fact of theirs {@link resolveCanvasTemplateChoice}
 *  actually needs, kept in sync by hand: if the canonical filename(s) ever change, update both.
 *
 *  ORDERED, new name first, same reason and same removal condition as the website-side list: `basic`
 *  ships `pages-default.html` since its 2026-09-03 posts-* / pages-* rename, but `basic-2` — the only
 *  other installed static theme with a page shell at all — still ships the legacy `page-shell.html`.
 *  {@link useThemeCanvasStyling}'s template-markup fetch tries each entry in order (see that
 *  function's own doc) so either theme's real filename is found. */
export const STATIC_TIER_PAGE_SHELL_TEMPLATES: readonly string[] = ["pages-default.html", "page-shell.html"];

/**
 * What {@link useThemeCanvasStyling}'s `templateChoice` argument should actually be, given the page's
 * own `bodyFormat` — ordinarily `templateChoice` unchanged, except for an untemplated (`null`/`""`)
 * `html`-format Page, which the live render path (`resolveStaticTierPageShellFallback`, consulted by
 * `renderTemplateBranchIfEligible` in
 * `apps/website/src/server/inbound/public-http/routes/site/pages.ts`) renders through the active
 * theme's own page shell — the first entry of {@link STATIC_TIER_PAGE_SHELL_TEMPLATES} it actually
 * ships — instead of Tovu's generic built-in chrome — see that function's own doc for the full "why".
 * Before this existed, the
 * Interactive canvas asked for no template markup at all in this case, so it never derived a wrapper
 * and rendered the page full-bleed while the published page (the SAME row, through the SAME theme)
 * rendered inside the theme's real container.
 *
 * A `doc`-format Page is untouched — `bodyFormat !== "html"` short-circuits straight to
 * `templateChoice` unchanged. That shape already has its own, unaffected "never chosen" handling
 * (`isPageTemplateChoiceEligible` in `static-render.ts`), and this function must not reopen the
 * `terms-of-service`/blog-post-title regression that gate exists to prevent (see that function's own
 * doc). A real `templateChoice` — the operator picked one — always wins over the fallback.
 *
 * Fetching {@link STATIC_TIER_PAGE_SHELL_TEMPLATES}`[0]` against a theme that ships neither candidate
 * (every non-`static` tier, and a `static` theme with no page shell at all) fails harmlessly:
 * {@link useThemeCanvasStyling}'s own candidate-fallback fetch already degrades a full miss to "no
 * wrapper" — the exact pre-existing behavior for this case. No theme-tier check is needed here for
 * that reason; the failed fetch(es) ARE the tier check.
 *
 * @param templateChoice - The page's own live template choice, same tri-state contract as
 *   {@link useThemeCanvasStyling}'s own parameter.
 * @param bodyFormat - The page's `bodyFormat`. `"doc"` — including "page not loaded yet", the
 *   caller's own conservative default — never triggers the fallback.
 * @returns The `templateChoice` to actually pass to {@link useThemeCanvasStyling}.
 * @complexity O(1) — one truthiness check, no I/O.
 */
export function resolveCanvasTemplateChoice(templateChoice: string | null, bodyFormat: "doc" | "html"): string | null {
  // `""` (bare page, owner ruling 2026-09-23) is deliberately excluded from the `if (templateChoice)`
  // falsy check below: unlike `null`, it must NOT resolve to the page-shell fallback any more — it
  // renders NO theme chrome at all, and `useThemeCanvasStyling`'s own bare short-circuit (above)
  // reads this exact `""` to mean "no canvas styling, don't fetch". Passed straight through here.
  if (templateChoice === "") return templateChoice;
  if (templateChoice) return templateChoice;
  return bodyFormat === "html" ? STATIC_TIER_PAGE_SHELL_TEMPLATES[0] : templateChoice;
}

/** A token name must be a plain CSS custom property; a value must not contain any character that
 *  could terminate the declaration, the rule, or — the one that actually escalates — the `<style>`
 *  element itself. GrapesJS injects this CSS by string-concatenating it into `<style>…</style>` and
 *  parsing that as HTML (`FrameView.renderBody`), so a `</style>` inside a token value would escape
 *  into markup. Themes may come from third parties, so their token files are not fully
 *  trusted input; an offending token is dropped rather than escaped, since no legitimate token value
 *  contains these at all. */
const SAFE_TOKEN_NAME = /^--[A-Za-z0-9_-]+$/;
const UNSAFE_TOKEN_VALUE = /[<>{};]/;

function isSafeToken([name, value]: [string, string]): boolean {
  return SAFE_TOKEN_NAME.test(name) && typeof value === "string" && !UNSAFE_TOKEN_VALUE.test(value);
}

/**
 * Builds the `:root` custom-property block the canvas needs, mirroring what
 * `features/theme/static-render.ts`'s `tokensToRootCss` emits into every real rendered page —
 * default-mode tokens on bare `:root`, light-mode tokens behind `[data-theme="light"]`. The canvas
 * document sets no `data-theme`, so it renders in the theme's default mode, exactly as an
 * un-toggled first visit to the live site does.
 *
 * @param tokens - The theme's default-mode tokens (`tokens.json`).
 * @param lightTokens - The theme's light-mode tokens, or `undefined` when it ships none.
 * @returns One CSS string. Empty when `tokens` holds nothing usable, which the caller treats as
 *   "this theme cannot style the canvas" rather than emitting an empty rule.
 * @complexity O(n) in the total number of tokens.
 */
export function tokensToCanvasCss(tokens: ThemeTokens, lightTokens: ThemeTokens | undefined): string {
  const block = (selector: string, entries: [string, string][]) =>
    entries.length === 0 ? "" : `${selector}{${entries.map(([k, v]) => `${k}:${v};`).join("")}}`;
  const defaultBlock = block(":root", Object.entries(tokens).filter(isSafeToken));
  if (!defaultBlock) return "";
  return defaultBlock + block(':root[data-theme="light"]', Object.entries(lightTokens ?? {}).filter(isSafeToken));
}

/** Pending until the token fetch settles, because `InteractiveHtmlEditor` reads its canvas styling
 *  once at mount and never again — a caller that mounted the editor while this was still resolving
 *  would get an unstyled canvas permanently. `ready` covers success AND every failure: on failure
 *  `styling` is `{}`, which reproduces the pre-existing unstyled canvas rather than blocking the
 *  tab on a theme asset the operator cannot do anything about. */
export type ThemeCanvasStylingState = { status: "pending" } | { status: "ready"; styling: CanvasStyling };

/** What a theme with no usable tokens resolves to — the exact behavior every caller had before this
 *  hook existed. */
const NO_CANVAS_STYLING: ThemeCanvasStylingState = { status: "ready", styling: {} };

/** Bug B, Slice B2 (pages-redo plan, repro 2): upper bound on how long the Interactive tab can sit on
 *  "Loading the theme's styles…" before it gives up and renders unstyled. Without this, a hung
 *  `/theme-assets/*\/tokens.json` fetch (API restarting behind the Vite dev proxy) left `state` at
 *  `pending` forever — the editor never rendered at all. A timeout is the same "can't style this
 *  canvas" outcome a fetch REJECTION already produces (`NO_CANVAS_STYLING`), just reached by a clock
 *  instead of an error. */
const CANVAS_STYLING_TIMEOUT_MS = 8000;

/** Bug B, Slice B3 (pages-redo plan): dev-only, temporary instrumentation for the "sometimes doesn't
 *  render, or renders late" reports that were not reproducible under a healthy API — logs every time
 *  {@link useThemeCanvasStyling}'s state settles (empty theme, timeout, resolved styling, or a fetch
 *  failure), so the next occurrence is diagnosable from the console instead of guessed at. Removed
 *  once Bug B is closed; not covered by a test for that reason — it is logging only, with no behavior
 *  for a test to assert. */
function logCanvasStylingSettle(phase: string): void {
  if (import.meta.env.DEV) {
    console.debug("[page-editor] interactive", { phase, ms: Math.round(performance.now()) });
  }
}

/**
 * Fetches the active theme's tokens and pairs them with its stylesheet URL, as the `canvasStyling`
 * `@jini-ai/ui`'s `InteractiveHtmlEditor` accepts.
 *
 * @param themeId - The active theme's id, or `null` before presentation settings have loaded (stays
 *   `pending` until it arrives — the editor must not mount unstyled and then learn the theme). `""`
 *   (settings loaded, no theme configured) resolves to {@link NO_CANVAS_STYLING} immediately — there is
 *   nothing to fetch, so it does not wait out the Slice B2 timeout below.
 * @param apiVersion - The active theme's manifest `apiVersion`, used only to locate its stylesheet.
 *   Unknown is treated as v1, matching `resolveThemeLayout`'s own default.
 * @param port - Injected {@link ThemeCanvasPort} — see `theme-canvas-port.hooks.ts`.
 * @param templateChoice - The page's own selected template (same tri-state contract as
 *   `PageEditorController.templateChoice`: `null`/`""` both mean "no template", a filename fetches
 *   that template's markup) — appended as a 4th, DEFAULTED parameter rather than inserted earlier, so
 *   `use-page-editor.hooks.ts`'s existing 3-argument call site keeps compiling and behaving exactly as
 *   before (no wrapper) until it is deliberately updated to pass one. When given, this hook derives
 *   the real ancestor chain the template wraps `{"type":"content"}` in
 *   (`theme-canvas-wrapper.ts`'s `deriveContentWrapperChain`) and includes it as the returned
 *   styling's `contentWrapper` — see that module's own file header for what it does and why. Any
 *   failure along this path (fetch rejects, no marker found, markup unparseable) degrades to no
 *   wrapper rather than failing the whole canvas: `contentWrapper` is optional on `CanvasStyling`, and
 *   its absence reproduces the exact pre-existing "no wrapper" canvas.
 * @returns The current {@link ThemeCanvasStylingState}.
 * @complexity Three-or-four requests per theme (token, light-token, and stylesheet-warm always; plus
 *   template markup when `templateChoice` is set, up to two when it is the page-shell shim's primary
 *   candidate and the active theme only ships the legacy one), no unbounded retry; O(n) in the token
 *   count to build the CSS, O(m) in the template markup's size to derive the wrapper. The stylesheet
 *   warm (Bug B, Slice B1) is fire-and-forget and never affects this count's success/failure outcome.
 *   Bug B, Slice B2: bounded by {@link CANVAS_STYLING_TIMEOUT_MS} — a fetch that never settles resolves
 *   to {@link NO_CANVAS_STYLING} once the timer fires, so `pending` can never last forever, and the
 *   timer is cleared on both a normal settle and unmount so it never fires or leaks after either.
 */
/**
 * Fetches `templateChoice`'s markup, same single request as before, UNLESS `templateChoice` is
 * exactly {@link STATIC_TIER_PAGE_SHELL_TEMPLATES}`[0]` — the synthetic value
 * {@link resolveCanvasTemplateChoice} returns for an untemplated `html` Page, never an operator's own
 * explicit pick (`activeThemeTemplates` always reflects the CURRENTLY active theme's real filenames,
 * so an explicit choice never needs this). In that one case, a failed fetch retries the REMAINING
 * ordered candidates before giving up — the browser-side twin of
 * `resolveStaticTierPageShellFallback`'s own ordered-candidate loop
 * (`apps/website/src/features/theme/static-render.ts`), needed because only `basic` ships the new
 * `pages-default.html` name; `basic-2` still ships only the legacy `page-shell.html`.
 *
 * @returns The first candidate's markup that resolves, or `null` once every candidate has rejected —
 *   folded into the SAME "no wrapper" degrade {@link useThemeCanvasStyling} already applies to a
 *   single fetch failure, not a new outcome.
 * @complexity O(1) network round trips in the common case (one), bounded by
 *   `STATIC_TIER_PAGE_SHELL_TEMPLATES.length` in the worst case — never unbounded.
 */
async function fetchTemplateMarkupWithPageShellFallback(
  port: ThemeCanvasPort,
  themeId: string,
  apiVersion: 2 | undefined,
  templateChoice: string,
): Promise<string | null> {
  const candidates = templateChoice === STATIC_TIER_PAGE_SHELL_TEMPLATES[0] ? STATIC_TIER_PAGE_SHELL_TEMPLATES : [templateChoice];
  for (const candidate of candidates) {
    try {
      return await port.fetchTemplateMarkup(templateMarkupUrl(themeId, apiVersion, candidate));
    } catch {
      // Try the next ordered candidate; the loop's own fall-through to `null` below is the "every
      // candidate failed" outcome, matching the pre-existing single-fetch `.catch(() => null)`.
    }
  }
  return null;
}

export function useThemeCanvasStyling(
  themeId: string | null,
  apiVersion: 2 | undefined,
  port: ThemeCanvasPort,
  templateChoice: string | null = null,
): ThemeCanvasStylingState {
  const [state, setState] = useState<ThemeCanvasStylingState>({ status: "pending" });

  useEffect(() => {
    if (themeId === null) return; // Still `pending` — presentation settings have not landed yet.
    if (!themeId) {
      // Presentation settings have landed but no theme is configured (`themeId === ""`) — there is
      // nothing to fetch, so this resolves immediately instead of sitting `pending` until the Slice B2
      // timeout below, which exists to bound a real in-flight fetch, not an empty theme id.
      logCanvasStylingSettle("styling:empty-theme");
      setState(NO_CANVAS_STYLING);
      return;
    }
    if (templateChoice === "") {
      // Bare page (owner ruling 2026-09-23, S6): no theme chrome at all, so there is nothing for the
      // canvas to style — resolved immediately, same as the `!themeId` branch above, rather than
      // fetching this theme's tokens/stylesheet/template markup only to discard them. Deliberately
      // NOT reached via `themeId = null` (that means "still pending", per this function's own doc) —
      // a real, loaded theme with a bare Page selected is a settled state, not a waiting one.
      logCanvasStylingSettle("styling:bare-page");
      setState(NO_CANVAS_STYLING);
      return;
    }
    // Declared fresh inside the effect body on every run (not a ref/module-level flag) so it is
    // naturally reset on each mount, including StrictMode's dev-mode mount->unmount->mount — see
    // apps/admin/INFO.md's "disposed flag" trap.
    let cancelled = false;
    // Bug B, Slice B2: `cancelled` means "this effect run was torn down" (unmount or a dependency
    // change re-ran it); `settled` means "this mount already produced its one final state". The
    // timeout below and the `Promise.all` chain race each other, and whichever lands first must stop
    // the other from overwriting it — see the plan's "a timed-out styling is final for that mount".
    let settled = false;
    setState({ status: "pending" });
    const timeoutId = setTimeout(() => {
      // No `cancelled || settled` early return here: both settle paths below and the effect's
      // cleanup `clearTimeout(timeoutId)` before setting those flags, so this callback only ever
      // runs while neither is set.
      settled = true;
      // Same outcome a fetch REJECTION already produces — see `CANVAS_STYLING_TIMEOUT_MS`'s own doc.
      logCanvasStylingSettle("styling:timeout");
      setState(NO_CANVAS_STYLING);
    }, CANVAS_STYLING_TIMEOUT_MS);
    // `null` (no fetch at all) for "no template chosen" — resolved immediately rather than left out of
    // the `Promise.all` below, so readiness always waits on exactly one settle shape regardless of
    // whether a template is selected.
    const templateMarkup: Promise<string | null> = templateChoice
      ? fetchTemplateMarkupWithPageShellFallback(port, themeId, apiVersion, templateChoice)
      : Promise.resolve(null);
    Promise.all([
      port.fetchThemeTokens(themeTokensUrl(themeId)),
      // A theme with no light variant is normal, not an error — see `themeLightTokensUrl`.
      port.fetchThemeTokens(themeLightTokensUrl(themeId)).catch(() => undefined),
      templateMarkup,
      // Fire-and-forget (Bug B, Slice B1): warms the browser's HTTP cache for the SAME stylesheet URL
      // `InteractiveHtmlEditor` is about to link into its canvas, so that request has a better chance
      // of resolving fast instead of the canvas showing browser-default styling until it does. Belt-
      // and-braces `.catch` alongside the real port's own internal swallow (`ThemeCanvasPort.
      // warmStylesheet`'s doc) — a rejection here must never turn a perfectly good token+CSS resolution
      // into "no canvas styling at all".
      port.warmStylesheet(themeStylesheetUrl(themeId, apiVersion)).catch(() => undefined),
    ])
      .then(([tokens, lightTokens, markup]) => {
        if (cancelled || settled) return;
        settled = true;
        clearTimeout(timeoutId);
        const css = tokensToCanvasCss(tokens, lightTokens);
        if (!css) {
          logCanvasStylingSettle("styling:no-usable-tokens");
          setState(NO_CANVAS_STYLING);
          return;
        }
        // `null` covers both "no template chosen" and "the fetch/derivation above found nothing
        // usable" — both fall back to no wrapper identically, per this function's own doc.
        const contentWrapper = markup ? (deriveContentWrapperChain(markup) ?? undefined) : undefined;
        logCanvasStylingSettle("styling:ready");
        setState({
          status: "ready",
          styling: { stylesheets: [themeStylesheetUrl(themeId, apiVersion)], css, contentWrapper },
        });
      })
      .catch(() => {
        if (cancelled || settled) return;
        settled = true;
        clearTimeout(timeoutId);
        logCanvasStylingSettle("styling:fetch-error");
        setState(NO_CANVAS_STYLING);
      });
    return () => {
      cancelled = true;
      clearTimeout(timeoutId);
    };
  }, [themeId, apiVersion, port, templateChoice]);

  return state;
}

/**
 * @file A small, dependency-free HTML pretty-printer for the Pages editor's "HTML" tab.
 *
 * The owner reported the HTML view had "regressed" from a formatted tree back to a wall of text.
 * Checked first (`git log`/repo-wide grep for `prettier`/`js-beautify`/`html-format`/`CodeMirror`,
 * across both Tovu and Jini): no HTML formatter has EVER existed anywhere in this codebase — the
 * only precedent is `packages/ui/src/features/html-editor/css.ts`'s `prettifyCss` in the Jini repo,
 * which formats the CSS half of GrapesJS's export and explicitly argues for a small hand-rolled
 * tokenizer over a real parser or a bundled `prettier` build for exactly this reason: the added
 * weight isn't warranted for a formatting-only pass, and no such dependency exists in either
 * `package.json` in this repo already. This function is that same argument applied to HTML instead
 * of CSS, built fresh in Tovu (not Jini) since the Pages screen is Tovu-only. So the report the
 * owner is remembering is not this codebase — build it anyway, since the request stands regardless.
 *
 * **Why the "wall of text" happens now specifically**: `development/scripts/
 * convert-legacy-doc-pages-to-html.ts` converted several Pages from Tiptap `doc` JSON to raw HTML
 * earlier the same session, and the renderer that produced that HTML emits zero inter-element
 * whitespace (`</h2><h2 id="...">`, `<p>...</p><p>...</p>`, directly concatenated). Hand-authored
 * page bodies with their own existing line breaks were never touched by this gap; only the
 * machine-generated ones show it.
 *
 * **The save-corruption risk, and how this function is constrained to avoid it**: `PageEditor.tsx`
 * wires this into a live, editable textarea, not a read-only viewer, so the formatted text an
 * operator sees IS what can end up saved once they start typing (see that file's own comment on the
 * `draftHtml`/`prevViewRef` wiring for the "view alone never dirties the page" half of that
 * decision). Whitespace injected purely for readability must therefore never change what a visitor
 * sees when the result is saved. This function is deliberately narrow to guarantee that:
 *
 * - It ONLY inserts a newline+indent at a boundary between two tags that were textually adjacent in
 *   the source (zero existing characters between them) AND are both members of {@link BLOCK_ELEMENTS}
 *   — ordinary block-level HTML tags (`div`, `p`, `h1`-`h6`, `li`, …). A whitespace-only text node
 *   between two such elements is not rendered by any browser (block/flex/grid layout all discard
 *   it), so this specific class of insertion is provably invisible once rendered, independent of
 *   which theme or CSS is applied — UNLESS a stylesheet overrides one of those tags to
 *   `display: inline` (rare for a structural tag; disclosed as a residual risk, not fixed here).
 * - It NEVER touches a text run, an inline element's boundary, or the inside of `<pre>`, `<script>`,
 *   `<style>`, or `<textarea>` (see {@link RAW_TEXT_ELEMENTS}) — those are copied through byte for
 *   byte. This is why `<p>Tovu is a content platform <strong>vibecoded</strong> alongside…</p>`
 *   comes out exactly as authored: nothing inside a paragraph's mixed text/inline content is ever a
 *   zero-gap tag-to-tag boundary, so the rule never fires there.
 * - Existing whitespace between two tags (hand-authored formatting) is left completely alone — the
 *   rule only fires on a literal zero-character gap, so already-readable markup is a no-op through
 *   this function.
 *
 * @complexity O(n) two passes over the input length (tokenize, then print) — no backtracking, no
 * recursive descent, no DOM construction.
 */

/** Tags whose content the browser (and this formatter) treats as opaque: reformatting inside one of
 *  these could change literal, meaningful whitespace (`<pre>`/`<textarea>`) or corrupt embedded
 *  code (`<script>`/`<style>`) that happens to contain characters this tokenizer would otherwise
 *  read as markup. Content between an opening and closing tag of these names is copied verbatim. */
const RAW_TEXT_ELEMENTS = new Set(["script", "style", "pre", "textarea"]);

/** Void elements never have a closing tag or children — excluded from the open/close depth stack
 *  below (there is nothing to later pop). */
const VOID_ELEMENTS = new Set([
  "area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source", "track", "wbr",
]);

/**
 * Ordinary block-level HTML tags. Whitespace-only text between two elements from this list is not
 * rendered by any layout mode (block, flex, grid) in a normal (non-overridden) stylesheet — see the
 * file header for why that specific property is what makes the insertion rule below safe.
 * Deliberately excludes inline-level and inline-with-fallback tags (`span`, `a`, `strong`, `em`,
 * `img`, `br`, `label`, `button`, …) — inserting whitespace next to one of those CAN become a
 * visible space once rendered, so this formatter never reformats around them at all.
 */
const BLOCK_ELEMENTS = new Set([
  "html", "head", "body", "header", "footer", "nav", "main", "section", "article", "aside",
  "div", "p", "h1", "h2", "h3", "h4", "h5", "h6",
  "ul", "ol", "li", "dl", "dt", "dd",
  "table", "thead", "tbody", "tfoot", "tr", "td", "th", "caption", "colgroup",
  "form", "fieldset", "legend", "blockquote", "figure", "figcaption", "hr",
  "details", "summary", "address", "pre",
]);

const INDENT = "  ";

/** One tag boundary (open/close/self-close) or an opaque run of everything else (text, comments,
 *  doctype, and raw-text-element content) between tag boundaries. */
type Token =
  | { kind: "tag"; text: string; tagKind: "open" | "close" | "self-close"; name: string }
  | { kind: "other"; text: string };

/** Matches one complete HTML tag, attributes included, with attribute values allowed to contain
 *  `>` when quoted (`data-x="a > b"`) so such a value is never mistaken for the tag's own end. */
const TAG_PATTERN =
  /<\/?([a-zA-Z][a-zA-Z0-9:-]*)(?:\s+[^\s"'=<>]+(?:\s*=\s*(?:"[^"]*"|'[^']*'|[^\s"'=<>]+))?)*\s*\/?>/y;

/**
 * Consumes an HTML comment (`<!-- ... -->`) starting at `i`, if there is one — one of four token
 * shapes {@link tokenizeHtml} recognizes at each position, split out to a top-level function (each
 * scored on its own, independent of `tokenizeHtml`'s) so the tokenizer's own loop reads as a flat
 * dispatch instead of a wall of nested `if`s. Pushes directly onto `tokens` (rather than returning a
 * token to push) so a raw-text element's second, content token — see {@link consumeTag} — can use the
 * exact same shape without the caller needing to know a helper produced one token or two.
 *
 * @returns The index to resume tokenizing from, or `null` if `i` isn't the start of a comment.
 */
function consumeComment(html: string, i: number, length: number, tokens: Token[]): number | null {
  if (!html.startsWith("<!--", i)) return null;
  const end = html.indexOf("-->", i + 4);
  const stop = end === -1 ? length : end + 3;
  tokens.push({ kind: "other", text: html.slice(i, stop) });
  return stop;
}

/** Consumes a `<!doctype ...>` declaration starting at `i`, if there is one — see {@link consumeComment}. */
function consumeDoctype(html: string, i: number, length: number, tokens: Token[]): number | null {
  if (html.slice(i, i + 9).toLowerCase() !== "<!doctype") return null;
  const end = html.indexOf(">", i);
  const stop = end === -1 ? length : end + 1;
  tokens.push({ kind: "other", text: html.slice(i, stop) });
  return stop;
}

/** Tag metadata derived from one matched `<tag ...>` string — split out of {@link consumeTag} so its
 *  own ternary chain scores independently. `tagName` is {@link TAG_PATTERN}'s own capture group: the
 *  pattern only matches when a name is present, so (unlike the earlier re-match of `raw` with an
 *  `?.[1] ?? ""` fallback) there is no "no name" case to handle. */
function parseTagMeta(raw: string, tagName: string): {
  name: string;
  tagKind: "open" | "close" | "self-close";
} {
  const isClose = raw.startsWith("</");
  const isSelfClose = !isClose && raw.endsWith("/>");
  const name = tagName.toLowerCase();
  const tagKind: "open" | "close" | "self-close" = isClose ? "close" : isSelfClose ? "self-close" : "open";
  return { name, tagKind };
}

/** Consumes a {@link RAW_TEXT_ELEMENTS} element's entire opaque body as a second token, immediately
 *  after its opening tag — split out of {@link consumeTag}, called only when that tag just opened one,
 *  so its content is never re-tokenized as markup (see the file header). */
function consumeRawTextBody(html: string, next: number, length: number, name: string, tokens: Token[]): number {
  const closeMatch = new RegExp(`</${name}\\s*>`, "i").exec(html.slice(next));
  const rawEnd = closeMatch ? next + closeMatch.index + closeMatch[0].length : length;
  tokens.push({ kind: "other", text: html.slice(next, rawEnd) });
  return rawEnd;
}

/**
 * Consumes one HTML tag starting at `i`, if there is one — see {@link consumeComment}. When the tag
 * just opened a {@link RAW_TEXT_ELEMENTS} member, delegates to {@link consumeRawTextBody} to also
 * consume that element's entire body as a second token in the same call, so the resume index this
 * returns already skips past both.
 */
function consumeTag(html: string, i: number, length: number, tokens: Token[]): number | null {
  if (html[i] !== "<") return null;
  TAG_PATTERN.lastIndex = i;
  const match = TAG_PATTERN.exec(html);
  if (!match) return null;

  const raw = match[0];
  const { name, tagKind } = parseTagMeta(raw, match[1]);
  tokens.push({ kind: "tag", text: raw, tagKind, name });
  const next = i + raw.length;

  if (tagKind === "open" && RAW_TEXT_ELEMENTS.has(name)) {
    return consumeRawTextBody(html, next, length, name, tokens);
  }
  return next;
}

/** Consumes plain text (or an unmatched stray `<`, folded into the same run rather than looping
 *  forever on it) up to the next `<` — the fallback {@link tokenizeHtml} reaches when none of
 *  {@link consumeComment}/{@link consumeDoctype}/{@link consumeTag} claimed the current position, so
 *  unlike them this always succeeds and returns a plain index rather than `number | null`. */
function consumeText(html: string, i: number, length: number, tokens: Token[]): number {
  const next = html.indexOf("<", i + 1);
  const stop = next === -1 ? length : next;
  tokens.push({ kind: "other", text: html.slice(i, stop) });
  return stop;
}

/**
 * Splits raw HTML into a flat sequence of tag boundaries and opaque runs (text, comments, doctype,
 * and raw-text-element bodies). Not a real parser — no tree is built, no nesting is validated beyond
 * the simple open/close name stack {@link prettifyHtml} keeps for indentation — which is what keeps
 * this a single linear pass instead of a recursive-descent HTML parser.
 *
 * The loop itself is a flat dispatch across the four `consume*` helpers above, tried in order — each
 * returns the resume index on a match or `null` to fall through to the next. `consumeText` always
 * matches, so the chain always terminates.
 *
 * @param html Raw HTML, a full document or a fragment. Malformed input (an unmatched `<`, an
 * unclosed tag) degrades to treating the offending character as literal text rather than throwing —
 * this function must never fail on already-broken content.
 */
function tokenizeHtml(html: string): Token[] {
  const tokens: Token[] = [];
  const length = html.length;
  let i = 0;

  while (i < length) {
    i =
      consumeComment(html, i, length, tokens) ??
      consumeDoctype(html, i, length, tokens) ??
      consumeTag(html, i, length, tokens) ??
      consumeText(html, i, length, tokens);
  }

  return tokens;
}

/** Whether `token` is a CLOSING tag for a block element — {@link prettifyHtml}'s own stack-pop
 *  trigger, split out (with {@link isOpeningBlockTag} and {@link isZeroGapBlockBoundary} below) so
 *  their `&&` chains score against these small top-level predicates instead of `prettifyHtml` itself.
 *  A type predicate (not a plain `boolean`) so callers that check this before reading `token.name`
 *  (there's no `name` on the `"other"` branch of {@link Token}) keep that narrowing. */
function isClosingBlockTag(token: Token): token is Extract<Token, { kind: "tag" }> {
  return token.kind === "tag" && token.tagKind === "close" && BLOCK_ELEMENTS.has(token.name);
}

/** Whether `token` is an OPENING tag for a block element that isn't void — {@link prettifyHtml}'s own
 *  stack-push trigger (a void element has no children to indent, so it never opens a new depth). */
function isOpeningBlockTag(token: Token): token is Extract<Token, { kind: "tag" }> {
  return (
    token.kind === "tag" &&
    token.tagKind === "open" &&
    BLOCK_ELEMENTS.has(token.name) &&
    !VOID_ELEMENTS.has(token.name)
  );
}

/** The one place {@link prettifyHtml} inserts whitespace: two block-element tags with zero characters
 *  between them in the source — see the file header for why this specific boundary is safe to fill.
 *  `prev === undefined` (the very first token) replaces the original `idx > 0` guard: `tokens[-1]` is
 *  already `undefined` in JS, so the caller can pass `tokens[idx - 1]` directly without computing `idx > 0`. */
function isZeroGapBlockBoundary(prev: Token | undefined, token: Token): boolean {
  return (
    prev !== undefined &&
    prev.kind === "tag" &&
    BLOCK_ELEMENTS.has(prev.name) &&
    token.kind === "tag" &&
    BLOCK_ELEMENTS.has(token.name)
  );
}

/**
 * Pretty-prints HTML for display/editing in the Pages editor's HTML tab: indents nested block
 * elements onto their own lines, tree-style, without touching any text content, inline markup, or
 * `<pre>`/`<script>`/`<style>`/`<textarea>` bodies. See the file header for the exact safety rule
 * (zero-gap, both-sides-block boundaries only) and why it is safe to apply even though the result
 * can be saved as the page's real stored HTML.
 *
 * Idempotent: running it twice produces the same output as running it once (no zero-gap boundaries
 * remain after the first pass, since every insertion point it would touch is filled).
 *
 * @param html Raw HTML, a full document or a fragment. `""` returns `""`.
 * @returns The same markup with added structural whitespace only.
 */
export function prettifyHtml(html: string): string {
  if (html === "") return html;

  const tokens = tokenizeHtml(html);
  const stack: string[] = [];
  let depth = 0;
  let out = "";

  for (let idx = 0; idx < tokens.length; idx++) {
    const token = tokens[idx];

    // Mirrors `prettifyCss`'s `}` handling: a closing tag renders at its PARENT's depth, so the
    // stack pops (and depth drops) before this token's own indent is computed below.
    if (isClosingBlockTag(token) && stack[stack.length - 1] === token.name) {
      stack.pop();
      depth = Math.max(0, depth - 1);
    }

    if (isZeroGapBlockBoundary(tokens[idx - 1], token)) {
      out += "\n" + INDENT.repeat(depth);
    }

    out += token.text;

    if (isOpeningBlockTag(token)) {
      stack.push(token.name);
      depth++;
    }
  }

  return out;
}

import { RemixIcon } from "@jini-ai/ui";
import { PreviewModalShell } from "@jini-ai/ui/preview-modal-shell";
import { agentHandle } from "@jini-ai/agentic";
import { useId, type ReactNode } from "react";

import { buildAgentListHandles } from "@jini-ai/agentic";
import type { Translate } from "@jini-ai/ui/panel-kit";
import type { PackageFilesStatus, PackageFileView } from "./rules";
import { packageFileIconKind, type PackageFileIconKind } from "./package-file-tree";
import { usePackageFileTree } from "./hooks/use-package-file-tree.hooks";
import { useCodeWrap } from "@/components/CodeView/use-code-wrap.hooks";
import { CodeView, CodeWrapToggle } from "@/components/CodeView/CodeView";
import { CODE_PREVIEW_MODAL_ICONS } from "@/components/CodeView/preview-modal-icons";

/**
 * @file The read-only package-files browser BOTH plugin screens open — a VS Code-style file tree
 * (files first, chevrons, indent guides, file-type icons; since 2026-09-29) on the left, the
 * selected file's source on the right with a Wrap toggle, inside Jini's `PreviewModalShell` (which
 * supplies the expand and close controls). Extracted 2026-09-13 out of `AgentPluginDetailsModal.tsx`
 * so Agent Plugins and Plugins render through one component and cannot drift apart.
 *
 * Presentational only: it loads nothing and holds no data. Each caller owns its source and passes
 * files in — Agent Plugins and Plugins both read the installed package live from the server via
 * `AGENT_PLUGIN_FILES` / `PLUGIN_FILES` (see `hooks/use-agent-plugin-details-modal.hooks.ts` and
 * `hooks/use-plugin-package-files.hooks.ts`).
 *
 * Class names keep the `agent-plugin-source-*` prefix they had before the extraction, so
 * `styles.css` needed no change.
 */

export interface PackageFilesModalProps {
  readonly title: string;
  readonly headerExtras?: ReactNode;
  readonly subtitle?: string | undefined;
  readonly files: readonly PackageFileView[];
  readonly selectedFile: PackageFileView | null;
  readonly onSelectFile: (relativePath: string) => void;
  /** Shown in the content pane while no file is selected: loading, a load failure, or no files. */
  readonly status: PackageFilesStatus | null;
  /** One line above the file list, e.g. that the viewer's caps left some files out. */
  readonly listNotice?: string | null;
  /** Prefix for each file row's agent handle (`agent-plugin-file`, `plugin-file`). */
  readonly handlePrefix: string;
  readonly t: Translate;
  readonly onClose: () => void;
  readonly additionalViews?: readonly { id: string; label: string; custom: ReactNode }[];
  /** Forward the shared shell's selected-view notification so the host can update its header. */
  readonly onView?: (viewId: string) => void;
  /** The view to open on (an additional view's id); the package files otherwise. */
  readonly initialViewId?: string | undefined;
}

/** A package-relative path with a `<wbr>` after every `/` (visual QA, 2026-08-31). Used by the
 *  content pane's heading since the file list became a tree (2026-09-29). Paths run
 *  long (`skills/interface-design/references/commands/critique.md`) — without a preferred break point
 *  `overflow-wrap: anywhere` (styles.css) was free to split mid-filename, e.g. leaving a lone `d`
 *  orphaned on its own line after "critique.m". `<wbr>` only offers the browser a *preferred* spot
 *  to break, so `overflow-wrap: anywhere` still catches the rare segment too long for the pane on
 *  its own — this only makes the common case break at a path boundary instead of a word. */
function PackageFilePath({ path }: { path: string }) {
  const segments = path.split("/");
  return (
    <>
      {segments.map((segment, i) => (
        <span key={i}>
          {segment}
          {i < segments.length - 1 ? "/" : null}
          {i < segments.length - 1 ? <wbr /> : null}
        </span>
      ))}
    </>
  );
}

/** RemixIcon glyph per file family (`package-file-tree.ts`'s {@link packageFileIconKind}). The
 *  `is-<kind>` class on the icon carries its tint (styles.css). */
const FILE_ICON_GLYPH: Readonly<Record<PackageFileIconKind, string>> = {
  json: "braces-line",
  markdown: "markdown-line",
  javascript: "javascript-line",
  typescript: "code-s-slash-line",
  config: "settings-3-line",
  html: "html5-line",
  css: "css3-line",
  image: "image-line",
  shell: "terminal-box-line",
  text: "file-text-line",
  file: "file-line",
};

/**
 * The file list as a WAI-ARIA tree, one flat row per visible node (`aria-level` carries the
 * nesting), so the selected row's highlight spans the pane's full width the way VS Code's does.
 * Expansion, focus and keys are `usePackageFileTree`; a row's full path is its tooltip, since long
 * names truncate rather than wrap. File rows keep the `…-select` agent handles the flat list had.
 */
function PackageFileTree({
  files,
  selectedPath,
  onSelectFile,
  fileHandleByPath,
  handlePrefix,
  label,
}: {
  files: readonly PackageFileView[];
  selectedPath: string | null;
  onSelectFile: (relativePath: string) => void;
  fileHandleByPath: ReadonlyMap<string, string>;
  handlePrefix: string;
  label: string;
}) {
  const tree = usePackageFileTree({ paths: files.map((file) => file.relativePath), selectedPath, onOpenFile: onSelectFile });
  const folderPaths = tree.rows.filter((row) => row.node.kind === "folder").map((row) => row.node.path);
  const folderHandles = buildAgentListHandles({ prefix: `${handlePrefix}-folder`, ids: folderPaths });
  const folderHandleByPath = new Map(folderPaths.map((path, index) => [path, folderHandles[index]!]));

  return (
    <div ref={tree.treeRef} role="tree" aria-label={label} className="agent-plugin-source-tree" onKeyDown={tree.onKeyDown}>
      {tree.rows.map((row) => {
        const { node } = row;
        const folder = node.kind === "folder";
        const expanded = folder && tree.isExpanded(node.path);
        const handle = folder
          ? agentHandle({ handle: `${folderHandleByPath.get(node.path)}-toggle` }, { role: "button", label: `Expand or collapse the "${node.path}" folder` })
          : agentHandle({ handle: `${fileHandleByPath.get(node.path)}-select` }, { role: "button", label: `Select the "${node.path}" file` });
        return (
          <div
            key={`${node.kind}:${node.path}`}
            role="treeitem"
            aria-label={node.name}
            aria-level={row.depth + 1}
            aria-setsize={row.setSize}
            aria-posinset={row.posInSet}
            aria-expanded={folder ? expanded : undefined}
            aria-selected={folder ? undefined : node.path === selectedPath}
            tabIndex={node.path === tree.activePath ? 0 : -1}
            title={node.path}
            data-tree-path={node.path}
            className="agent-plugin-source-tree-row"
            onClick={() => tree.onRowClick(row)}
            onFocus={() => tree.onRowFocus(node.path)}
            {...handle}
          >
            <span className="agent-plugin-source-tree-indent" style={{ width: `calc(${row.depth} * var(--tree-indent))` }} aria-hidden />
            {folder ? (
              <>
                <RemixIcon name={expanded ? "arrow-down-s-line" : "arrow-right-s-line"} size={16} className="agent-plugin-source-tree-twistie" />
                <RemixIcon name={expanded ? "folder-open-line" : "folder-line"} className="agent-plugin-source-tree-icon is-folder" />
              </>
            ) : (
              <>
                <span className="agent-plugin-source-tree-twistie" aria-hidden />
                <RemixIcon
                  name={FILE_ICON_GLYPH[packageFileIconKind(node.name)]}
                  className={`agent-plugin-source-tree-icon is-${packageFileIconKind(node.name)}`}
                />
              </>
            )}
            <span className="agent-plugin-source-tree-label">{node.name}</span>
          </div>
        );
      })}
    </div>
  );
}

/**
 * Keyed by `file.relativePath` in the parent, so switching the selected file remounts this and
 * resets `wrap` to its default rather than carrying a manual toggle across files.
 *
 * Defaults to wrapped for every file. Previously unwrapped for `plugin.json`/`.ts` sources on the
 * theory that structure reads better with no wrap; in practice the most likely first click in this
 * modal (`plugin.json`) ran a long line off the pane indefinitely, and the owner had to scroll
 * horizontally just to read it (owner correction, 2026-09-10). The toggle keeps unwrapped one click
 * away for whoever genuinely wants raw structure.
 *
 * A file listed without content (binary, too large, a symlink) shows its reason instead, and has no
 * Wrap toggle — there is nothing to wrap.
 */
function PackageFileContent({
  file,
  headingId,
  agentHandleBase,
  t,
}: {
  file: PackageFileView;
  headingId: string;
  agentHandleBase: string;
  t: Translate;
}) {
  const { wrap, toggleWrap } = useCodeWrap();
  const hasContent = file.content !== null;

  return (
    <section className="agent-plugin-source-content" aria-labelledby={headingId}>
      <div className="agent-plugin-source-content-header">
        <h3 id={headingId}>
          <PackageFilePath path={file.relativePath} />
        </h3>
        {hasContent ? (
          <CodeWrapToggle wrap={wrap} onToggle={toggleWrap} t={t} agentHandleId={`${agentHandleBase}-wrap-toggle`} />
        ) : null}
      </div>
      <PackageFileBody file={file} wrap={wrap} />
    </section>
  );
}

function PackageFileBody({ file, wrap }: { file: PackageFileView; wrap: boolean }) {
  if (file.content === null) {
    return (
      <p className="notice" role="status">
        {file.unavailableReason}
      </p>
    );
  }
  return <CodeView text={file.content} wrap={wrap} />;
}

export function PackageFilesModal({
  title,
  headerExtras,
  subtitle,
  files,
  selectedFile,
  onSelectFile,
  status,
  listNotice,
  handlePrefix,
  t,
  onClose,
  additionalViews = [],
  onView,
  initialViewId,
}: PackageFilesModalProps) {
  const selectedFileHeadingId = useId();
  // File paths are stable and unique within one package, same per-row-handle derivation every
  // other list on this workstream uses (`buildAgentListHandles`).
  const fileHandles = buildAgentListHandles({ prefix: handlePrefix, ids: files.map((file) => file.relativePath) }
  );
  const fileHandleByPath = new Map(files.map((file, index) => [file.relativePath, fileHandles[index]!]));

  return (
    <PreviewModalShell
      className="agent-plugin-source-modal"
      icons={CODE_PREVIEW_MODAL_ICONS}
      title={title}
      headerExtras={headerExtras}
      subtitle={subtitle}
      onView={onView}
      initialViewId={initialViewId}
      views={[
        {
          id: "package-source",
          label: t("Package files"),
          custom: (
            <div className="agent-plugin-source-browser">
              <nav className="agent-plugin-source-files" aria-label={t("Package files")}>
                {listNotice ? (
                  <p className="page-description" role="note">
                    {listNotice}
                  </p>
                ) : null}
                <PackageFileTree
                  files={files}
                  selectedPath={selectedFile?.relativePath ?? null}
                  onSelectFile={onSelectFile}
                  fileHandleByPath={fileHandleByPath}
                  handlePrefix={handlePrefix}
                  label={t("Package files")}
                />
              </nav>
              {selectedFile ? (
                <PackageFileContent
                  file={selectedFile}
                  headingId={selectedFileHeadingId}
                  key={selectedFile.relativePath}
                  agentHandleBase={fileHandleByPath.get(selectedFile.relativePath)!}
                  t={t}
                />
              ) : status ? (
                <p role={status.role}>{status.text}</p>
              ) : null}
            </div>
          ),
        },
        ...additionalViews,
      ]}
      onClose={onClose}
    />
  );
}

import { agentHandle } from "@jini-ai/agentic";
import { Button, Dialog } from "@jini-ai/ui-kit/react";
import { interpolate } from "@jini-ai/ui/panel-kit";
import { useEffect, useId } from "react";

import type { AdminPlugin, AdminPluginProviderSettings } from "@/lib/api";
import { useWiredPluginProviderSettings } from "./hooks/use-plugin-provider-settings.hooks";
import { ProviderSettingField } from "./PluginProviderSettingField";
import { providerSettingRequiredHere } from "./rules";
import "../../styles/native-domain-dialogs.css";
import "./provider-settings-dialog.css";

/**
 * @file A provider plugin's secure settings card (2026-10-26): Plugins → Installed (or Downloaded) →
 * the plugin's Settings button. Every field comes from the plugin's manifest; secret fields are
 * password inputs that never show a saved value ("Saved — leave blank to keep"). Saved values are
 * sealed on the server (the project store visible to attached sites, or this site's vault) and
 * apply now.
 *
 * 2026-10-25 redesign (owner: "looks awful"): the admin's native domain dialog (`PostUrlDialog`'s
 * Jini `Dialog` + `.jini-dialog-body`/`.jini-dialog-footer`) with the `.field` primitives — label
 * above a full-width control, hint below — instead of bare inline labels. Titled "<Name> settings";
 * a successful Save hands off to `onSaved` (the screen closes the card and shows a toast), so the
 * outcome is never a small line inside a card the owner is about to dismiss.
 */

export interface PluginProviderSettingsDialogProps {
  readonly plugin: Pick<AdminPlugin, "id" | "name">;
  readonly agentHandleBase: string;
  readonly onClose: () => void;
  /** After the server accepted the values; the screen closes the card and confirms with a notice. */
  readonly onSaved: () => void;
  /** Injectable seam for tests. Defaults to the real {@link useWiredPluginProviderSettings}. */
  readonly useSettings?: typeof useWiredPluginProviderSettings;
}

/** Field names are manifest keys (`apiKey`); agent handles allow only lowercase words joined by hyphens. */
function handleWords(name: string): string {
  return name.replace(/([a-z0-9])([A-Z])/g, "$1-$2").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

/** The card's re-entry notices (a key saved the retired way, or saved keys this machine can't open). */
function ReentryNotices({ card, t }: { card: AdminPluginProviderSettings | null; t: (key: string) => string }) {
  return (
    <>
      {card?.unreadable ? <p className="provider-settings-notice" role="note">{t("Saved keys for this plugin can't be read on this machine. Enter them again here and save.")}</p> : null}
      {card?.legacyCredential ? <p className="provider-settings-notice" role="note">{t("A key for this plugin was saved in an older format that Tovu no longer reads. Enter it again here and save.")}</p> : null}
    </>
  );
}

/** Cancel and Save; disabled with a spinner while saving. */
function SettingsFooter({ shown, saving, pluginName, agentHandleBase, onClose, t }: { shown: boolean; saving: boolean; pluginName: string; agentHandleBase: string; onClose: () => void; t: (key: string) => string }) {
  return (
    <div className="jini-dialog-footer">
      <Button variant="secondary" className="btn-secondary" disabled={saving} onPress={() => onClose()}
        attrs={agentHandle({ handle: `${agentHandleBase}-settings-close` }, { role: "button", label: `Close ${pluginName} settings` })}>
        {t("Cancel")}
      </Button>
      <Button type="submit" variant="primary" className="provider-settings-save" disabled={!shown} pending={saving}
        attrs={agentHandle({ handle: `${agentHandleBase}-settings-save` }, { role: "button", label: `Save ${pluginName} settings` })}>
        {saving ? <><span className="provider-settings-spinner" aria-hidden="true" />{t("Saving…")}</> : t("Save")}
      </Button>
    </div>
  );
}

function SettingsSubtitle({ card, t }: { card: AdminPluginProviderSettings | null; t: (key: string) => string }) {
  if (!card) return null;
  return <p className="provider-settings-subtitle">{card.store === "project" ? card.usedBy.length ? interpolate({ template: t("Used by {sites}"), vars: { sites: card.usedBy.join(", ") } }) : t("Saved to your project — not used by any site yet") : t(card.projectAvailable ? "Saved for this site only" : "Saved for this site")}</p>;
}

function useProviderSettingsFocus({ card, fieldId }: { card: AdminPluginProviderSettings | null; fieldId: string }, _options = {}) {
  // The native dialog focuses on open, before the card has loaded; once it has, start in its first field.
  const firstField = card?.fields[0]?.name;
  useEffect(() => { if (firstField) document.getElementById(`${fieldId}-${firstField}`)?.focus(); }, [fieldId, firstField]);
}

export function PluginProviderSettingsDialog({ plugin, agentHandleBase, onClose, onSaved, useSettings = useWiredPluginProviderSettings }: PluginProviderSettingsDialogProps) {
  const { card, values, setValue, save, useSavedKey, saving, error, t } = useSettings(plugin.id);
  const fieldId = useId();
  const fields = card?.fields ?? [];
  // Presence only: a saved alternate secret satisfies the same manifest rule as an entered value.
  const effectiveValues = Object.fromEntries(fields.map(field => [field.name,
    values[field.name]?.trim() || (field.secret && field.saved ? "saved" : field.default ?? "")]));
  useProviderSettingsFocus({ card, fieldId });
  return (
    <Dialog open title={interpolate({ template: t("{name} settings"), vars: { name: plugin.name } })} pending={saving} onClose={() => onClose()} className="settings-dialog jini-domain-dialog provider-settings-dialog">
      <SettingsSubtitle card={card} t={t} />
      <form onSubmit={(event) => { event.preventDefault(); void save().then((accepted) => { if (accepted) onSaved(); }); }} noValidate>
        <div className="jini-dialog-body">
          <ReentryNotices card={card} t={t} />
          {card?.store === "project" && card.keyId && !card.usedByThisSite ? <Button variant="secondary" disabled={saving}
            onPress={() => { void useSavedKey().then(accepted => { if (accepted) onSaved(); }); }}>
            {t("Use the saved key for this site")}
          </Button> : null}
          {fields.map((field) => (
            <ProviderSettingField key={field.name} field={{ ...field, required: providerSettingRequiredHere({ field, fields, entered: values, values: effectiveValues }) }} id={`${fieldId}-${field.name}`} value={values[field.name] ?? ""}
              onChange={(value) => setValue(field.name, value)} handle={`${agentHandleBase}-setting-${handleWords(field.name)}`} pluginName={plugin.name} t={t} />
          ))}
        </div>
        {error ? <p className="save-error" role="alert">{error}</p> : null}
        <SettingsFooter shown={card !== null} saving={saving} pluginName={plugin.name} agentHandleBase={agentHandleBase} onClose={onClose} t={t} />
      </form>
    </Dialog>
  );
}

import type { ComponentType } from "react";

import type { AdminPlugin } from "@/lib/api";
import { buildAgentListHandles } from "@jini-ai/agentic";
import { Toast } from "@jini-ai/ui";
import { TabBar, type TabBarTab } from "@jini-ai/ui/tab-strip";
import { resolveActiveTabId } from "@jini-ai/ui/panel-kit";
import { navigate } from "../../lib/router";
import { PluginRow } from "./PluginRow";
import { PluginPackageFilesModal } from "./PluginPackageFilesModal";
import { PluginProviderSettingsDialog } from "./PluginProviderSettingsDialog";
import { PluginRemoveConfirmDialog } from "./PluginRemoveConfirmDialog";
import { AddPluginPanel } from "./AddPluginPanel";
import { UploadIcon } from "./agent-plugins-visuals";
import { addPluginTabSoonTag, marketplaceTabSoonTag } from "./add-plugin-tab-soon";
import { DownloadedTabIcon, InstalledTabIcon, MarketplaceTabIcon, PluginTrashIcon } from "./plugins-visuals";
import { pluginRemoveAriaLabel, pluginRemoveBlocker, pluginToggleAriaLabel, pluginToggleControl } from "./rules";
import { useWiredPlugins, type PluginsController } from "./hooks/use-plugins.hooks";

/**
 * @file `Plugins` — the admin `.tovu-plugin` list screen (SPEC-005 REQ-12..18, ui.spec.md), rebuilt
 * from a single flat `DataTable` into the row-based, tabbed shape `AgentPlugins.tsx` (a sibling
 * screen for the unrelated agent-plugins.org standard — see `panels.tsx`'s own "Integrations" group
 * comment for why these two are deliberately not the same system) already has, but independent of
 * it: nothing here imports from `AgentPlugins.tsx`/`AgentPluginRow.tsx`, and neither can this file's
 * behavior change by editing those.
 *
 * State and API calls live in `hooks/use-plugins.hooks.ts`; the server-error-message override,
 * toggle-cell decision, subline, and remove-confirm copy live in `rules.ts`. Route `/addons/plugins`;
 * consumes `PLUGINS_LIST`/`PLUGIN_SET_ENABLED`/`PLUGIN_UNINSTALL` (`api.listPlugins()`/
 * `api.setPluginEnabled()`/`api.uninstallPlugin()`) as a black box. Every Installed and Downloaded
 * row also has an eye button opening `PluginPackageFilesModal` (`PLUGIN_FILES`, 2026-09-13) — the
 * same read-only package-files viewer Agent Plugins uses.
 *
 * Four tabs, Installed first (owner correction, applied identically to the sibling screen the same
 * night — Installed before Downloaded, not the other way round):
 *  - **Installed** — every installed plugin, on or off (owner 2026-10-25, the same call Agent
 *    Plugins' Installed got on 2026-09-13: a provider plugin that is installed but off was listed
 *    only under Downloaded). Carries the Enable/Disable toggle unchanged from the pre-split table
 *    (`pluginToggleControl`/`onToggleEnabled`). `?plugin=<id>` scrolls to, focuses and highlights
 *    that row (`usePluginRowFocus`) — a linked agent plugin's padlock on Agent Plugins links here.
 *  - **Downloaded** — every plugin `PLUGINS_LIST` returns, unfiltered (this workspace's on-disk
 *    set). Every row carries Remove, which drives the REAL `PLUGIN_UNINSTALL` route: it deletes the
 *    plugin's on-disk artifact, gated behind `PluginRemoveConfirmDialog`. Remove is usable only
 *    where that route can succeed — a switched-off site plugin. On a built-in row, or a row that is
 *    still on, it is honestly disabled and points at a section note saying why
 *    (`pluginRemoveBlocker`; 2026-09-13 fix — before it, Remove showed ONLY on enabled rows, which
 *    the route always refuses). A disabled row also carries a direct, unconfirmed Enable (written
 *    when Installed listed only enabled rows; Installed's toggle now does the same).
 *  - **Add a plugin** — the shared `InstallTabCard` (`AddPluginPanel.tsx`): a server folder or one
 *    `.zip`, previewed before install. Replaced the header "Install plugin" popup (owner, 2026-10-06),
 *    so all three install screens (Skills, Agent Plugins, Plugins) share one tab and card. On a
 *    server that refuses local installs (`installSources` without "folder", e.g. tovu.dev) the tab is
 *    greyed out and tagged "Soon" instead (owner, 2026-10-17): it has no destination there, so it is
 *    disabled and `?tab=add` falls back to Installed.
 *  - **Marketplace** — a designed empty state; nothing is fetched, listed, or installable (REQ-02:
 *    install is a filesystem operation, placing files under this site's plugin install directory,
 *    not an HTTP one — `api.spec.md` §1 lists no install/marketplace route for this family either).
 *
 * `?tab=` is URL-deep-linked through the shared `resolveActiveTabId` guard, the same idiom
 * `Security.tsx`/`Database.tsx`/`SourceControl.tsx`/`Deployment.tsx` all use — `panels.tsx`'s
 * `plugins` entry passes `ctx.query.get("tab")` through as `tabId`.
 */
export interface PluginsProps {
  /** The `?tab=` query value from `panels.tsx`'s `plugins` route. See {@link resolvePluginsTabId}. */
  tabId?: string | null;
  /** The `?plugin=` query value: the row Installed scrolls to and highlights. */
  focusPluginId?: string | null;
  /**
   * Dependency injection seam for tests — the same convention `@jini-ai/ui`'s `CustomSelect` uses
   * for `useCustomSelect`. Defaulted to the real hook, so production callers (`panels.tsx`) pass
   * nothing and behave exactly as before.
   */
  usePluginsHook?: typeof useWiredPlugins;
}

const PLUGINS_TAB_IDS = ["installed", "downloaded", "add", "marketplace"] as const;
type PluginsTabId = (typeof PLUGINS_TAB_IDS)[number];

/** Falls back to the Installed tab for an absent or unrecognized `?tab=` value, and for `add` when
 *  this server refuses local installs (that tab is disabled). Delegates to the shared
 *  `../../lib/resolve-active-tab-id` guard every other URL-deep-linked tabbed admin screen uses. */
function resolvePluginsTabId(tabId: string | null | undefined, canInstall: boolean): PluginsTabId {
  const validIds = canInstall ? PLUGINS_TAB_IDS : PLUGINS_TAB_IDS.filter((id) => id !== "add");
  return resolveActiveTabId({ tabId: tabId, validIds: validIds, defaultId: "installed" });
}

/** The Installed tab's own row list — the Enable/Disable toggle unchanged from the pre-split table,
 *  now living in the row's action slot instead of a `DataTable` cell. */
function InstalledPluginRows({
  plugins,
  controller,
  expandedIds,
  onToggleExpanded,
  rowHandleById,
  focusPluginId,
}: {
  plugins: AdminPlugin[];
  controller: PluginsController;
  expandedIds: ReadonlySet<string>;
  onToggleExpanded: (id: string) => void;
  rowHandleById: Map<string, string>;
  focusPluginId?: string | null | undefined;
}) {
  const { t, locale, rowSavingId, onToggleEnabled } = controller;
  return (
    <ul className="plugin-rows">
      {plugins.map((plugin) => {
        const control = pluginToggleControl(plugin, rowSavingId, locale);
        return (
          <PluginRow
            key={plugin.id}
            plugin={plugin}
            t={t}
            expanded={expandedIds.has(plugin.id)}
            onToggleExpanded={() => onToggleExpanded(plugin.id)}
            agentHandleBase={rowHandleById.get(plugin.id)!}
            onInspect={() => controller.onInspectPlugin(plugin.id)}
            {...(plugin.providerSettings ? { onSettings: () => controller.onOpenSettings(plugin.id) } : {})}
            focused={plugin.id === focusPluginId}
            action={
              <button
                type="button"
                disabled={control.disabled}
                onClick={() => onToggleEnabled(plugin)}
                aria-label={pluginToggleAriaLabel(plugin, locale)}
              >
                {control.label}
              </button>
            }
          />
        );
      })}
    </ul>
  );
}

/** The Downloaded tab's own row list. Every row carries Remove (confirm-gated, see this file's own
 *  header), usable only when {@link pluginRemoveBlocker} finds no reason `PLUGIN_UNINSTALL` would
 *  refuse; otherwise it is disabled and described by the matching section note. A disabled row
 *  also gets a direct, unconfirmed Enable. Before the 2026-09-10 fix there was no control anywhere
 *  on this screen to re-enable a plugin once disabled — including a quarantined one — short of
 *  removing and reinstalling it.
 *
 *  Enable is offered regardless of `source`: unlike Remove (irreversibly destructive for a real
 *  on-disk artifact, so a built-in row's Remove stays honestly disabled), turning a plugin back on
 *  has no comparable cost, so a built-in row gets the same direct control a site-sourced one does. */
function DownloadedPluginRows({
  plugins,
  controller,
  expandedIds,
  onToggleExpanded,
  rowHandleById,
  onRequestRemove,
}: {
  plugins: AdminPlugin[];
  controller: PluginsController;
  expandedIds: ReadonlySet<string>;
  onToggleExpanded: (id: string) => void;
  rowHandleById: Map<string, string>;
  onRequestRemove: (plugin: AdminPlugin) => void;
}) {
  const { t, locale, rowSavingId, onToggleEnabled } = controller;
  return (
    <ul className="plugin-rows">
      {plugins.map((plugin) => {
        const removeBlocker = pluginRemoveBlocker(plugin);
        const busy = rowSavingId === plugin.id;
        const action = (
          <>
            {plugin.enabled ? null : (
              <button type="button" disabled={busy} onClick={() => onToggleEnabled(plugin)} aria-label={pluginToggleAriaLabel(plugin, locale)}>
                {t("Enable")}
              </button>
            )}
            <button
              type="button"
              className="plugin-icon-btn"
              disabled={removeBlocker !== null || busy}
              onClick={() => onRequestRemove(plugin)}
              aria-label={pluginRemoveAriaLabel(plugin, locale)}
              aria-describedby={removeBlocker ? PLUGINS_REMOVE_NOTE_IDS[removeBlocker] : undefined}
            >
              <PluginTrashIcon />
            </button>
          </>
        );
        return (
          <PluginRow
            key={plugin.id}
            plugin={plugin}
            t={t}
            expanded={expandedIds.has(plugin.id)}
            onToggleExpanded={() => onToggleExpanded(plugin.id)}
            agentHandleBase={rowHandleById.get(plugin.id)!}
            onInspect={() => controller.onInspectPlugin(plugin.id)}
            {...(plugin.providerSettings ? { onSettings: () => controller.onOpenSettings(plugin.id) } : {})}
            action={action}
          />
        );
      })}
    </ul>
  );
}

/** Every tab panel's inputs — one shape, so {@link PLUGINS_TAB_PANELS} can pick a panel by tab id. */
interface PluginsTabPanelProps {
  plugins: AdminPlugin[];
  controller: PluginsController;
  rowHandleById: Map<string, string>;
  focusPluginId?: string | null | undefined;
}

/** The Downloaded tab's two Remove notes, by {@link pluginRemoveBlocker} reason — a disabled Remove
 *  points at the one that explains it. */
const PLUGINS_REMOVE_NOTE_IDS = {
  "built-in": "plugins-remove-unavailable-note",
  enabled: "plugins-remove-enabled-note",
} as const;

/** Installed: every installed plugin, on or off, or an honest empty note when there are none. */
function InstalledPanel({ plugins, controller, rowHandleById, focusPluginId }: PluginsTabPanelProps) {
  const { t } = controller;
  if (plugins.length === 0) {
    return (
      <div className="card">
        <div className="empty-state">
          <p>{t("No plugins installed.")}</p>
          <p className="page-description">{t("Enabled plugins extend what this site can do.")}</p>
        </div>
      </div>
    );
  }
  return (
    <InstalledPluginRows
      plugins={plugins}
      controller={controller}
      expandedIds={controller.expandedIds}
      onToggleExpanded={controller.onToggleExpanded}
      rowHandleById={rowHandleById}
      focusPluginId={focusPluginId}
    />
  );
}

/** Downloaded: the two remove notes as compact helper text under the tabs, then every plugin — or
 *  its own empty state. The notes sat under the list until the owner moved them up (2026-10-07). */
function DownloadedPanel({ plugins, controller, rowHandleById }: PluginsTabPanelProps) {
  const { t } = controller;
  if (plugins.length === 0) {
    return (
      <div className="card">
        <div className="empty-state">
          <p>{t("No plugins installed.")}</p>
          <p className="page-description">
            {t(
              "A new one appears here on the next load, once it's unpacked into the site's plugin install directory.",
            )}
          </p>
        </div>
      </div>
    );
  }
  return (
    <>
      <div className="plugins-remove-notes">
        <p id={PLUGINS_REMOVE_NOTE_IDS["built-in"]} className="page-description">
          {t("Built-in plugins ship with Tovu itself and have no on-disk files to remove.")}
        </p>
        <p id={PLUGINS_REMOVE_NOTE_IDS.enabled} className="page-description">
          {t("Turn a plugin off on Installed before removing it.")}
        </p>
      </div>
      <DownloadedPluginRows
        plugins={plugins}
        controller={controller}
        expandedIds={controller.expandedIds}
        onToggleExpanded={controller.onToggleExpanded}
        rowHandleById={rowHandleById}
        onRequestRemove={controller.onRequestRemove}
      />
    </>
  );
}

/** Marketplace: a designed empty state — see this file's header for why nothing is listed. Same
 *  capped, centered card as Agent Plugins' Marketplace (owner, 2026-10-17: it ran the full column),
 *  so it reuses that screen's `agent-plugins-marketplace-*` classes rather than a second copy. */
function MarketplacePanel({ controller }: PluginsTabPanelProps) {
  const { t } = controller;
  return (
    <div className="agent-plugins-marketplace-empty" role="note">
      <span className="agent-plugins-marketplace-glyph">
        <MarketplaceTabIcon size={28} />
      </span>
      <h3>{t("Nothing to browse yet")}</h3>
      <p>{t("Marketplace is planned for a future release. Tovu does not fetch, list, or install plugins from a marketplace yet.")}</p>
      {controller.canInstallFolder ? null : (
        <p>{t("Install a plugin by placing its files in this site's plugin install directory.")}</p>
      )}
    </div>
  );
}

/** Add a plugin: the shared install card. Without an install controller (a test hook that omits
 *  it) the tab is empty; on a server that refuses local installs the tab is disabled and never
 *  resolves here. */
function AddPanel({ controller }: PluginsTabPanelProps) {
  return controller.install ? <AddPluginPanel controller={controller.install} /> : null;
}

const PLUGINS_TAB_PANELS: Record<PluginsTabId, ComponentType<PluginsTabPanelProps>> = {
  installed: InstalledPanel,
  downloaded: DownloadedPanel,
  add: AddPanel,
  marketplace: MarketplacePanel,
};

/** `TabBar`'s `onChange`: the active tab lives in the URL (`?tab=`), so switching is a navigation. */
function navigateToPluginsTab(nextTabId: string) {
  navigate(`/addons/plugins?tab=${nextTabId}`, { replace: true });
}

export function Plugins({ tabId, focusPluginId, usePluginsHook = useWiredPlugins }: PluginsProps = {}) {
  const controller = usePluginsHook();
  const { plugins, error, t } = controller;

  // `error && !plugins`, not `error` alone (2026-09-20 platform review, X1): a NEVER-loaded fetch
  // (no `plugins` yet) is still fatal — there is nothing else to show. But once the list has loaded
  // once, a later reload failure (a toggle's post-write re-fetch) must not blank the whole screen —
  // see `LoadedPlugins`'s own error notice below, and `use-plugins.hooks.ts`'s `reload()` header.
  if (error && !plugins) return <div className="notice error">{error}</div>;
  if (!plugins) return <div className="notice">{t("Loading plugins…")}</div>;
  return <LoadedPlugins plugins={plugins} controller={controller} activeTabId={resolvePluginsTabId(tabId, controller.canInstallFolder === true)} focusPluginId={focusPluginId} />;
}

/** The screen once `PLUGINS_LIST` has settled: header, row error, tab bar, the active tab's panel,
 *  and the package-files viewer and Remove confirm dialog (both opened through the controller). */
function LoadedPlugins({ plugins, controller, activeTabId, focusPluginId }: { plugins: AdminPlugin[]; controller: PluginsController; activeTabId: PluginsTabId; focusPluginId?: string | null | undefined }) {
  const { error, rowError, t, locale, inspectedPlugin, pendingRemovePlugin, settingsPlugin } = controller;

  // Plugin ids are stable and unique, same per-row-handle derivation every other list on this
  // workstream uses (`buildAgentListHandles`), computed once from the FULL unfiltered list so a
  // plugin's handle is identical whichever tab currently lists it (mirrors `AgentPluginRow`'s own
  // reasoning for deriving from the id alone, not list position).
  const rowHandles = buildAgentListHandles({ prefix: "plugins-row", ids: plugins.map((plugin) => plugin.id) }
  );
  const rowHandleById = new Map(plugins.map((plugin, index) => [plugin.id, rowHandles[index]!]));
  const ActivePanel = PLUGINS_TAB_PANELS[activeTabId];
  const canInstall = controller.canInstallFolder === true;

  const tabs: TabBarTab[] = [
    { id: "installed", label: t("Installed"), icon: <InstalledTabIcon />, handle: "plugins-tab-installed", handleLabel: "Switch to the Installed tab — every plugin installed for this site, on or off" },
    { id: "downloaded", label: t("Downloaded"), icon: <DownloadedTabIcon />, handle: "plugins-tab-downloaded", handleLabel: "Switch to the Downloaded tab — every plugin on disk for this site, regardless of whether it's turned on" },
    { id: "add", label: t("Add a plugin"), tag: addPluginTabSoonTag(locale, canInstall ? undefined : true), disabled: !canInstall, icon: <UploadIcon />, handle: "plugins-tab-add", handleLabel: "Switch to the Add a plugin tab — install a plugin from a folder on this server or a .zip" },
    { id: "marketplace", label: t("Marketplace"), tag: marketplaceTabSoonTag(locale), icon: <MarketplaceTabIcon />, handle: "plugins-tab-marketplace", handleLabel: "Switch to the Marketplace tab — a future place to discover plugins" },
  ];

  return (
    <div className="page plugins-page">
      <div className="page-header">
        <div className="page-header-text">
          <p className="page-kicker">{t("Integrations")}</p>
          <h1 className="page-title">{t("Plugins")}</h1>
          <p className="page-description">
            {t("Enable or disable plugins discovered in this site's plugin install directory.")}
          </p>
        </div>
      </div>
      {rowError ? (
        <div className="notice error">
          <span role="alert">{rowError}</span>
        </div>
      ) : null}
      {/* A reload failure AFTER the list has loaded once (X1) — the list, tabs and dialogs below
       *  stay on screen; only `error && !plugins` in `Plugins` itself is fatal. Same markup as
       *  `rowError` above. */}
      {error ? (
        <div className="notice error">
          <span role="alert">{error}</span>
        </div>
      ) : null}

      <TabBar ariaLabel={t("Plugins")} tabs={tabs} activeId={activeTabId} onChange={navigateToPluginsTab} containerHandle="plugins-tab-bar" />

      <ActivePanel plugins={plugins} controller={controller} rowHandleById={rowHandleById} focusPluginId={focusPluginId} />

      {inspectedPlugin ? <PluginPackageFilesModal plugin={inspectedPlugin} onClose={controller.onCloseInspector} /> : null}

      {settingsPlugin ? (
        <PluginProviderSettingsDialog plugin={settingsPlugin} agentHandleBase={rowHandleById.get(settingsPlugin.id)!} onClose={controller.onCloseSettings} onSaved={controller.onSettingsSaved} />
      ) : null}
      {/* A toast, like Themes' and Library's: it confirms what the owner just did and clears itself. */}
      {controller.settingsNotice ? <Toast message={controller.settingsNotice} role="status" tone="success" ttlMs={6000} onDismiss={controller.dismissSettingsNotice} /> : null}

      {pendingRemovePlugin ? (
        <PluginRemoveConfirmDialog
          name={pendingRemovePlugin.name}
          agentHandleBase={rowHandleById.get(pendingRemovePlugin.id)!}
          onConfirm={() => controller.onConfirmRemove(pendingRemovePlugin)}
          onCancel={controller.onCancelRemove}
          t={t}
        />
      ) : null}
    </div>
  );
}

import { ApiError, authenticatedAdminRequest, WORKSPACE_ID, type AdminAgentPlugin } from "@/lib/api";
import type { AgentPluginInstallPort, AgentPluginInstallResult } from "./agent-plugin-install-port.hooks";

/** The live upload, through the shared authenticated request seam (session expiry, API prefix). */
export const defaultAgentPluginInstallPort: AgentPluginInstallPort = {
  installZip: ({ file, sha256, replace = false, update }) =>
    authenticatedAdminRequest<AgentPluginInstallResult>({
      path: `/workspaces/${WORKSPACE_ID}/agent-plugins/${update ? `${encodeURIComponent(update.pluginId)}/update/zip` : "install/zip"}?${new URLSearchParams({ expectedSha256: sha256, replace: String(replace), ...(update ? { expectedOldDigest: update.expectedOldDigest } : {}) })}`,
      method: "POST",
      body: file.slice(0, file.size, "application/zip"),
    }),
  sha256: async ({ file }) => {
    const digest = await crypto.subtle.digest("SHA-256", await file.arrayBuffer());
    return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("");
  },
};

/** An in-memory {@link AgentPluginInstallPort}: answers with `row` (and `warnings`), or rejects
 *  with `failWith`. An update's target is recorded with its upload. */
export function createFakeAgentPluginInstallPort(
  required: { row: AdminAgentPlugin },
  optional: { failWith?: ApiError; alreadyInstalled?: boolean; warnings?: string[] } = {},
): AgentPluginInstallPort & { uploads: Array<{ name: string; sha256: string; update?: { pluginId: string; expectedOldDigest: string } }> } {
  const uploads: Array<{ name: string; sha256: string; update?: { pluginId: string; expectedOldDigest: string } }> = [];
  return {
    uploads,
    installZip: async ({ file, sha256, update }) => {
      uploads.push({ name: file.name, sha256, ...(update ? { update } : {}) });
      if (optional.failWith) throw optional.failWith;
      return { alreadyInstalled: optional.alreadyInstalled === true, agentPlugin: required.row, ...(optional.warnings ? { warnings: optional.warnings } : {}) };
    },
    sha256: async ({ file }) => `sha-of-${file.name}`,
  };
}

import { ApiError, api, authenticatedAdminRequest, WORKSPACE_ID, type AdminPlugin, type AdminPluginFiles, type AdminPluginProviderSettings } from "@/lib/api";
import { providerSettingRequiredHere } from "../rules";
import type { PluginsPort } from "./plugins-port.hooks";

/**
 * @file The only place under `features/plugins`'s screen hook that reaches `lib/api` — see
 * `plugins-port.hooks.ts` for why the split exists. (`AgentPlugins.tsx` is a separate screen, with
 * its own port at `agent-plugins-dependencies.hooks.ts` — out of scope here.)
 */

/** The live implementation, as a module-level singleton — matches `integrations/jini-admin/redirects-ports.ts`'s `redirectsHostPorts`. */
export const defaultPluginsPort: PluginsPort = {
  useProjectKey: input => api.useProjectKey(input),
  listPlugins: () => authenticatedAdminRequest({ path: `/workspaces/${WORKSPACE_ID}/plugins`, method: "GET" }),
  setPluginEnabled: (id, patch) => api.setPluginEnabled(id, patch),
  uninstallPlugin: (id) => api.uninstallPlugin(id),
  getPluginFiles: (id) => api.getPluginFiles(id),
  getProviderSettings: (id) => api.getPluginProviderSettings(id),
  saveProviderSettings: (id, values) => api.savePluginProviderSettings(id, values),
};

/** Seed state for {@link createFakePluginsPort}. */
export interface FakePluginsPortOptions {
  installSources?: string[];
  plugins?: AdminPlugin[];
  /** `PLUGIN_FILES` responses by plugin id; an id with no entry rejects like the real route's 404. */
  packageFiles?: Record<string, AdminPluginFiles>;
  /** Provider settings cards by plugin id; saves follow the real route's rules (blank secret = keep). */
  providerSettings?: Record<string, AdminPluginProviderSettings>;
}

/**
 * An in-memory {@link PluginsPort} for tests — the fake that lets a test describe "the list has
 * these two plugins" directly, instead of hand-building `Response` objects and stubbing global
 * `fetch`. Shipped alongside the real binding per the pattern's "every port gets a fake" rule.
 *
 * `uninstallPlugin` re-implements the real route's own two preconditions (`uninstallPlugin()`,
 * `features/plugin-runtime/uninstall.ts`) rather than always succeeding: a fake that skipped them
 * would let a component test "confirm the built-in refusal" only by asserting against a mocked
 * rejection, never against the same rule the real server enforces. Thrown as `ApiError` with the
 * real route's own `code`s, so `rules.ts`'s `describeApiError` maps them exactly as it would the
 * live response.
 */
export function createFakePluginsPort(options: FakePluginsPortOptions = {}): PluginsPort & {
  /** Every plugin currently in the fake's store, in list order. */
  readonly plugins: AdminPlugin[];
} {
  const plugins = [...(options.plugins ?? [])];
  const trashedPluginIds = new Set<string>();

  return {
    plugins,
    async useProjectKey({ keyId, use }) {
      const card = Object.values(options.providerSettings ?? {}).find(card => card.keyId === keyId);
      if (!card) throw new ApiError("project key not found", 404, "KEY_NOT_FOUND");
      card.usedByThisSite = use;
      card.usedBy = use ? ["this-site"] : [];
      return { keyId, usedByThisSite: use, usedBy: card.usedBy, appliesAt: "now" };
    },

    async listPlugins() {
      return { plugins: [...plugins], ...(options.installSources ? { installSources: options.installSources } : {}) };
    },

    async setPluginEnabled(id, patch) {
      const index = plugins.findIndex((p) => p.id === id);
      if (index < 0) throw new Error(`fake plugin not found: ${id}`);
      // The real enable gate (`onPluginEnabled`, 2026-10-04): a plugin whose row lists conflicts is
      // refused with 409 PLUGIN_CONFLICT and stays off. Turning a plugin OFF is never refused.
      if (patch.enabled && (plugins[index]!.conflicts ?? []).length > 0) {
        throw new ApiError(`Plugin '${id}' was not turned on because it claims things already in use.`, 409, "PLUGIN_CONFLICT");
      }
      const updated = { ...plugins[index]!, enabled: patch.enabled };
      plugins[index] = updated;
      // Matches the real route's own narrow echo shape — see `PluginsPort.setPluginEnabled`'s doc.
      return { plugin: { id: updated.id, version: "1", enabled: updated.enabled, updatedAt: new Date(0).toISOString() }, changeSetId: "fake-cs-1" };
    },

    async uninstallPlugin(id) {
      if (trashedPluginIds.has(id)) {
        throw new ApiError("plugin is already in Trash", 409, "PLUGIN_IN_TRASH");
      }
      const index = plugins.findIndex((p) => p.id === id);
      if (index < 0) throw new ApiError("plugin not found", 404, "PLUGIN_NOT_FOUND");
      const plugin = plugins[index]!;
      if (plugin.source === "built-in") {
        throw new ApiError(`plugin '${id}' is a built-in plugin and cannot be uninstalled`, 422, "PLUGIN_NOT_UNINSTALLABLE");
      }
      if (plugin.enabled) {
        throw new ApiError(`plugin '${id}' is enabled and must be disabled everywhere before it can be uninstalled`, 409, "PLUGIN_ENABLED");
      }
      trashedPluginIds.add(id);
      plugins.splice(index, 1);
      return { pluginId: id, trashed: true };
    },

    async getPluginFiles(id) {
      const listing = options.packageFiles?.[id];
      if (!listing) throw new ApiError("plugin was not found", 404, "PLUGIN_NOT_FOUND");
      return listing;
    },

    async getProviderSettings(id) {
      const card = options.providerSettings?.[id];
      if (!card) throw new ApiError("this plugin declares no provider settings", 404, "PLUGIN_NOT_FOUND");
      return card;
    },

    async saveProviderSettings(id, values) {
      const card = await this.getProviderSettings(id);
      if (Object.entries(values).some(([name]) => !card.fields.some((field) => field.name === name))) {
        throw new ApiError("values must map declared setting names to text", 400, "PROVIDER_SETTINGS_INVALID");
      }
      // Like the server: a blank secret is kept only while every public field is unchanged (a blank
      // public field means its declared default, so filling in that default is no change).
      const effective = (field: (typeof card.fields)[number], value: string | undefined) => value || field.default || "";
      const changed = card.fields.filter((field) => !field.secret && values[field.name] !== undefined && effective(field, values[field.name]!.trim()) !== effective(field, field.value));
      const kept = card.fields.filter((field) => field.secret && field.saved && !values[field.name]?.trim());
      if (changed.length > 0 && kept.length > 0) {
        const labels = (list: typeof kept) => list.map((field) => field.label).join(", ");
        throw new ApiError(`Changing ${labels(changed)} needs ${labels(kept)} entered again.`, 400, "PROVIDER_SETTINGS_SECRET_REENTRY");
      }
      const effectiveValues = Object.fromEntries(card.fields.map((field) => [field.name, field.secret
        ? values[field.name]?.trim() || (field.saved ? "saved" : "") : effective(field, values[field.name]?.trim() ?? field.value)]));
      const missing = card.fields.find((field) => providerSettingRequiredHere({ field, fields: card.fields, entered: values, values: effectiveValues }) && !effectiveValues[field.name]);
      if (missing) throw new ApiError(`${missing.label} is required.${missing.hint ? ` ${missing.hint}` : ""}`, 400, "PROVIDER_SETTINGS_REQUIRED");
      const fields = card.fields.map((field) => {
        const value = values[field.name]?.trim();
        if (value === undefined) return field;
        if (field.secret) return { ...field, saved: field.saved || value !== "" };
        return { ...field, value, saved: value !== "" };
      });
      // Like the server: once settings are saved, the retired-key and can't-read notices are gone.
      const { legacyCredential: _retired, unreadable: _unreadable, ...current } = card;
      options.providerSettings![id] = { ...current, fields };
      return options.providerSettings![id]!;
    },
  };
}

import { useCallback, useEffect, useMemo, useRef, useState, type RefObject } from "react";
import {
  adminSurfaceActionResponse,
  adminSurfaceInitMessage,
  adminSurfaceThemeMessage,
  createAdminSurfaceMount,
  openAdminSurfaceLink,
  readAdminSurfaceResize,
  validateAdminSurfaceMessage,
  type AdminSurfaceActionOutcome,
  type AdminSurfaceOpenLinkPort,
} from "@jini-ai/agent-plugins/admin-surfaces";
import { readAdminTheme, watchAdminTheme } from "../admin-surface-theme";
import type { AgentPluginSurfaceActionAnswer, AgentPluginSurfacesPort, AgentPluginSurfaceSummary, HostSignInLink } from "./agent-plugin-surfaces-port.hooks";

/**
 * @file The host page's half of one mounted plugin admin surface (Jini's admin-surface protocol):
 * the per-mount nonce, the single `init` (with the server's bootstrap) after the frame's first
 * load (with the admin's design tokens, re-sent on every theme change), and the message gate that forwards valid action requests to the server and posts each
 * answer back.
 *
 * Why the "first load only" checks are repeated at post time: the bootstrap and every action
 * answer arrive asynchronously, and if the frame navigated in the meantime its window now holds a
 * different document. Posting there (target `'*'`, the only target an opaque origin allows) would
 * hand that document the bootstrap's short-lived token or an answer meant for the original surface.
 *
 * Sign-in links: the frame is sandboxed without `allow-popups`, so the host page opens a sign-in for
 * it. The only links it ever offers are the ones the server says IT issued while answering this
 * mount's actions (`hostSignIns`), kept per mount, https only, until opened or expired; a URL in the
 * plugin's own result is never opened. The page opens them as a new tab with no opener, which the
 * desktop shell's window policy hands to the system browser (as for every external link).
 *
 * Other external links: a surface may ask to open a link (`open-link`); Jini's gate opens only an
 * https URL whose origin the surface DECLARED (`linkOrigins`, from the digest-checked surfaces file),
 * and only for this mount's frame. The page opens it the same way as a sign-in: a new tab with no
 * opener or referrer on the web, which the desktop shell hands to the system browser.
 */

export type AdminSurfaceFrameStatus = "open" | "navigated" | "failed";

/** Returned to the surface when the host page could not reach the server; never server text. */
const HOST_UNAVAILABLE: AdminSurfaceActionOutcome = {
  ok: false,
  error: { code: "host-unavailable", message: "The admin page could not reach the server. Try again.", retryable: true },
};

export interface AdminSurfaceFrameController {
  readonly frameRef: RefObject<HTMLIFrameElement | null>;
  readonly status: AdminSurfaceFrameStatus;
  readonly onLoad: () => void;
  /** The surface's reported content height in CSS px (clamped by Jini), or null until it reports one. */
  readonly height: number | null;
  /** Host-issued sign-in links for this mount, not yet opened or expired. */
  readonly signIns: readonly HostSignInLink[];
  /** Forgets a link once the person opened it (each attempt is single use). */
  readonly onSignInOpened: (link: HostSignInLink) => void;
}

/** The server's https links only. @complexity O(l). */
function hostLinks(answer: AgentPluginSurfaceActionAnswer): readonly HostSignInLink[] {
  return (answer.hostSignIns ?? []).filter((link) => URL.parse(link.authorizationUrl)?.protocol === "https:");
}

/** The one opener for checked links, hosted and desktop alike (the desktop shell's window policy routes it). */
const openInNewTab: AdminSurfaceOpenLinkPort = ({ url }) => { window.open(url, "_blank", "noopener,noreferrer"); };

/** What the frame receives: the plugin's outcome alone, never the host's links. */
function frameOutcome(answer: AgentPluginSurfaceActionAnswer): AdminSurfaceActionOutcome {
  return answer.ok ? { ok: true, result: answer.result } : { ok: false, error: answer.error };
}

/**
 * @param required.surface - The listing entry: its `actions` are the client-side early refusal.
 * @complexity O(p) per message in the payload size (Jini's validator), plus one request.
 */
export function useAdminSurfaceFrame(
  required: { readonly pluginId: string; readonly surface: AgentPluginSurfaceSummary; readonly port: AgentPluginSurfacesPort },
  _optional: Record<string, never> = {},
): AdminSurfaceFrameController {
  const { pluginId, surface, port } = required;
  const frameRef = useRef<HTMLIFrameElement | null>(null);
  const loads = useRef(0);
  const mount = useMemo(() => createAdminSurfaceMount({ surfaceId: surface.id }), [surface.id]);
  const [status, setStatus] = useState<AdminSurfaceFrameStatus>("open");
  const [issued, setIssued] = useState<readonly HostSignInLink[]>([]);
  const [initialized, setInitialized] = useState(false);
  const [height, setHeight] = useState<number | null>(null);
  /** The frame's window while it still shows the document this mount initialized, else null. */
  const liveFrame = useCallback(() => (loads.current === 1 ? frameRef.current?.contentWindow ?? null : null), []);

  const onLoad = useCallback(() => {
    loads.current += 1;
    // A second load means the frame navigated away from the surface: unmount, never re-init.
    if (loads.current > 1) return setStatus("navigated");
    void port.bootstrap({ pluginId, surfaceId: surface.id }).then(
      (bootstrap) => {
        liveFrame()?.postMessage(adminSurfaceInitMessage({ mountId: mount.mountId }, { bootstrap, theme: readAdminTheme() }), "*");
        setInitialized(true);
      },
      () => setStatus("failed"),
    );
  }, [port, pluginId, surface.id, mount.mountId, liveFrame]);

  // The surface follows the admin's look: every theme or light/dark change after init is re-sent.
  useEffect(() => {
    if (!initialized || status !== "open") return undefined;
    return watchAdminTheme({ onChange: (theme) => liveFrame()?.postMessage(adminSurfaceThemeMessage({ mountId: mount.mountId, theme }), "*") });
  }, [initialized, status, mount.mountId, liveFrame]);

  useEffect(() => {
    if (status !== "open") return undefined;
    const onMessage = (event: MessageEvent) => {
      const frame = liveFrame();
      // No live frame: nothing may match (a null `source` must never equal a missing frame).
      if (frame === null) return;
      // The frame fits its content (no inner scrollbar); a height is cosmetic, so it is never answered.
      const reported = readAdminSurfaceResize({ event, mount: { mountId: mount.mountId, frame } });
      if (reported !== null) return setHeight(reported);
      const record = { mountId: mount.mountId, frame, descriptor: { actions: surface.actions, linkOrigins: surface.linkOrigins ?? [] } };
      // Each gate ignores the other's messages; a link verdict with a response is this mount's open-link.
      void openAdminSurfaceLink({ event, mount: record, openLink: openInNewTab }).then((link) => { if ("response" in link) liveFrame()?.postMessage(link.response, "*"); });
      const verdict = validateAdminSurfaceMessage({ event, mount: record });
      if (!verdict.ok) {
        if ("response" in verdict) frame.postMessage(verdict.response, "*");
        return;
      }
      const { request } = verdict;
      void port.action({ pluginId, surfaceId: surface.id, action: request.action, payload: request.payload })
        .catch((): AgentPluginSurfaceActionAnswer => HOST_UNAVAILABLE)
        .then((answer) => {
          const links = hostLinks(answer);
          if (links.length > 0) setIssued((current) => [...current, ...links]);
          liveFrame()?.postMessage(adminSurfaceActionResponse({ request, outcome: frameOutcome(answer) }), "*");
        });
    };
    window.addEventListener("message", onMessage);
    return () => window.removeEventListener("message", onMessage);
  }, [status, port, pluginId, surface.id, surface.actions, surface.linkOrigins, mount.mountId, liveFrame]);

  const onSignInOpened = useCallback((link: HostSignInLink) => setIssued((current) => current.filter((entry) => entry !== link)), []);
  const signIns = issued.filter((link) => Date.parse(link.expiresAt) > Date.now());
  return { frameRef, status, onLoad, height, signIns, onSignInOpened };
}

import { useInfoTip } from "@jini-ai/ui/admin-widgets";
import { useEffect, useRef, type KeyboardEvent } from "react";

/**
 * @file The tip controller behind a linked agent plugin's padlock (`AgentPluginLinkedLock`, owner
 * 2026-10-25). It is the shared `InfoTip`'s own `useInfoTip`, with one change: pressing the padlock
 * follows it to the Plugins page instead of pinning the tip. Hover and focus still explain.
 *
 * Touch has no hover, so a tap on a closed tip opens and pins it first, and the next tap follows.
 * Whether the tip was open is read at `pointerdown`: mobile browsers fire their emulated
 * `mouseenter` (which opens the tip) between that and the `click`, and iOS swallows the first
 * tap's `click` altogether once that hover opened something — so either way one tap explains and
 * the next one follows.
 */
export function linkedLockTip({ onFollow }: { onFollow: () => void }): typeof useInfoTip {
  return function useLinkedLockTip(input, options) {
    const tip = useInfoTip(input, options);
    const openRef = useRef(tip.open);
    // Whether the tip was open when the last touch landed; `null` after a mouse/pen press (or none yet).
    const openAtTouch = useRef<boolean | null>(null);
    const { iconRef } = tip;
    useEffect(() => {
      openRef.current = tip.open;
    });
    useEffect(() => {
      const icon = iconRef.current;
      const note = (event: PointerEvent) => {
        openAtTouch.current = event.pointerType === "touch" ? openRef.current : null;
      };
      icon?.addEventListener("pointerdown", note);
      return () => icon?.removeEventListener("pointerdown", note);
    }, [iconRef]);
    const press = () => {
      if (openAtTouch.current === false) {
        openAtTouch.current = null;
        tip.toggle();
        return;
      }
      onFollow();
    };
    const handleIconKeyDown = (event: KeyboardEvent<HTMLSpanElement>) => {
      if (event.key !== "Enter" && event.key !== " ") return tip.handleIconKeyDown(event);
      event.preventDefault();
      onFollow();
    };
    return { ...tip, toggle: press, handleIconKeyDown };
  };
}

import { useEffect, useMemo, useRef, useState, type KeyboardEvent, type RefObject } from "react";

import {
  ancestorFolderPaths,
  buildPackageFileTree,
  packageFileTreeKeyAction,
  visiblePackageFileRows,
  type PackageFileTreeRow,
} from "../package-file-tree";

/**
 * @file `PackageFilesModal`'s file-tree state (2026-09-29): which folders are open, which row holds
 * keyboard focus, and what a click or key press does. The tree shape, visible rows and key mapping
 * are the pure helpers in `package-file-tree.ts`; this hook only stores state and moves DOM focus.
 *
 * Expansion is derived, not synced: a folder is open when the viewer toggled it open, or — until
 * they toggle it — when it contains the selected file. So the folders around the first selected file
 * open on their own once the listing loads, with no effect copying selection into state.
 */

export interface PackageFileTreeDependencies {
  /** Every listed file's `relativePath`. */
  readonly paths: readonly string[];
  readonly selectedPath: string | null;
  readonly onOpenFile: (relativePath: string) => void;
}

export interface PackageFileTreeController {
  /** Attach to the `role="tree"` element; keyboard moves focus to rows inside it. */
  readonly treeRef: RefObject<HTMLDivElement | null>;
  readonly rows: readonly PackageFileTreeRow[];
  /** The one row with `tabIndex=0` (roving tabindex); `null` only while there are no rows. */
  readonly activePath: string | null;
  readonly isExpanded: (folderPath: string) => boolean;
  readonly onKeyDown: (event: KeyboardEvent<HTMLElement>) => void;
  /** A folder row toggles; a file row opens. */
  readonly onRowClick: (row: PackageFileTreeRow) => void;
  /** Keeps the roving tabindex on whichever row focus landed on (a click, or a Tab back in). */
  readonly onRowFocus: (path: string) => void;
}

/** What one key action can do to the tree; {@link applyPackageFileTreeKeyAction}'s effects port. */
export interface PackageFileTreeKeyEffects {
  readonly setExpanded: (path: string, expanded: boolean) => void;
  readonly openFile: (relativePath: string) => void;
  readonly focus: (path: string) => void;
}

/**
 * Carries out one key action's effects (expand/collapse, open, then focus). Every field of the action
 * is optional by contract — the current key map always moves focus, but an action that only opens or
 * only toggles still does exactly that and nothing more.
 *
 * @returns Whether the key was the tree's (so the caller suppresses the browser's default).
 * @complexity O(1).
 */
export function applyPackageFileTreeKeyAction(action: ReturnType<typeof packageFileTreeKeyAction>, effects: PackageFileTreeKeyEffects): boolean {
  if (!action.focus && !action.setExpanded && !action.open) return false;
  if (action.setExpanded) effects.setExpanded(action.setExpanded.path, action.setExpanded.expanded);
  if (action.open) effects.openFile(action.open);
  if (action.focus) effects.focus(action.focus);
  return true;
}

/**
 * @returns The rows to render and the handlers for the tree.
 * @complexity O(files) per render to rebuild visible rows; the tree itself is memoized on the paths.
 */
export function usePackageFileTree({ paths, selectedPath, onOpenFile }: PackageFileTreeDependencies): PackageFileTreeController {
  const pathsKey = paths.join("\n");
  const tree = useMemo(() => buildPackageFileTree(paths), [pathsKey]);
  const [toggled, setToggled] = useState<ReadonlyMap<string, boolean>>(() => new Map());
  const [focusedPath, setFocusedPath] = useState<string | null>(null);
  const treeRef = useRef<HTMLDivElement | null>(null);
  const moveDomFocus = useRef(false);

  const selectedAncestors = new Set(selectedPath ? ancestorFolderPaths(selectedPath) : []);
  const isExpanded = (folderPath: string) => toggled.get(folderPath) ?? selectedAncestors.has(folderPath);
  const rows = visiblePackageFileRows(tree, isExpanded);
  const visible = (path: string | null) => path !== null && rows.some((row) => row.node.path === path);
  const activePath = visible(focusedPath) ? focusedPath : visible(selectedPath) ? selectedPath : (rows[0]?.node.path ?? null);

  // Only after a key press: DOM focus follows the roving tabindex. Never on mount or on a
  // selection that came from outside, so opening the dialog doesn't pull focus into the tree.
  useEffect(() => {
    if (!moveDomFocus.current) return;
    moveDomFocus.current = false;
    const target = Array.from(treeRef.current?.querySelectorAll<HTMLElement>("[data-tree-path]") ?? []).find(
      (element) => element.dataset.treePath === activePath,
    );
    target?.focus();
  });

  const setExpanded = (path: string, expanded: boolean) =>
    setToggled((previous) => new Map(previous).set(path, expanded));

  const onKeyDown = (event: KeyboardEvent<HTMLElement>) => {
    if (activePath === null) return;
    const action = packageFileTreeKeyAction(rows, activePath, event.key, isExpanded);
    const handled = applyPackageFileTreeKeyAction(action, {
      setExpanded,
      openFile: onOpenFile,
      focus: (path) => {
        setFocusedPath(path);
        moveDomFocus.current = true;
      },
    });
    if (handled) event.preventDefault();
  };

  const onRowClick = (row: PackageFileTreeRow) => {
    setFocusedPath(row.node.path);
    if (row.node.kind === "folder") setExpanded(row.node.path, !isExpanded(row.node.path));
    else onOpenFile(row.node.path);
  };

  return { treeRef, rows, activePath, isExpanded, onKeyDown, onRowClick, onRowFocus: setFocusedPath };
}

import { useEffect, useRef, useState, type ChangeEvent, type FormEvent } from "react";
import { ApiError } from "@/lib/api";
import type { Translate } from "@jini-ai/ui/panel-kit";
import type { PluginInstallPort, PluginInstallPreview, PluginInstallSource } from "./plugin-install-port.hooks";
import { pluginInstallPreviewDisplay } from "../rules";
import { useZipDrop } from "../../../components/InstallTabCard/use-zip-drop.hooks";
import { useFolderUpload } from "../../../components/InstallTabCard/use-folder-upload.hooks";
import { installArchiveSize } from "../../../components/InstallTabCard/install-archive-size";

const ZIP_MAX_BYTES = 32 * 1024 * 1024;
const TOO_LARGE = "ZIP exceeds the upload or expanded package size limit.";

/** Server refusal code → dictionary key. */
const ERROR_CODE_KEYS: Readonly<Record<string, string>> = {
  PLUGIN_CHANGED_SINCE_PREVIEW: "Package changed. Review it again before installing.",
  PLUGIN_LOCAL_INSTALL_DISABLED: "Local folder installs are disabled on this server.",
  PLUGIN_IN_TRASH: "This plugin is already in the Trash. Restore or delete it there first.",
  PLUGIN_ENABLED: "Turn this plugin off in every workspace before installing.",
  PLUGIN_PACKAGE_TOO_LARGE: TOO_LARGE,
};
/** HTTP status → dictionary key, for a refusal without a known code. */
const ERROR_STATUS_KEYS: Readonly<Record<number, string>> = {
  413: TOO_LARGE,
  409: "Installation conflicts with an existing plugin. Check its version and replacement option.",
  400: "Invalid plugin package. Check its manifest, integrity and folder.",
};

function errorKey(error: unknown, fallback: string): string {
  if (!(error instanceof ApiError)) return fallback;
  return (error.code ? ERROR_CODE_KEYS[error.code] : undefined) ?? ERROR_STATUS_KEYS[error.status] ?? fallback;
}

/**
 * The Plugins "Add a plugin" tab's state: a server folder or one uploaded `.zip` (picker, drop, or a
 * picked folder zipped in the browser), the replace option, the preview (trust review) and the
 * install it unlocks. Changing any input invalidates the preview, so an install always matches what
 * was reviewed.
 */
export function usePluginInstall(required: { port: PluginInstallPort; t: Translate; onInstalled: () => Promise<void> }, _optional = {}) {
  const [folder, setFolder] = useState("");
  const [zipFile, setZipFile] = useState<File | null>(null);
  const zipInputRef = useRef<HTMLInputElement | null>(null);
  const [replace, setReplace] = useState(false);
  const [preview, setPreview] = useState<PluginInstallPreview | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [installedName, setInstalledName] = useState<string | null>(null);
  const sequence = useRef(0);
  const locked = useRef(false);
  useEffect(() => () => { sequence.current++; }, []);
  function invalidate() { sequence.current++; setPreview(null); setError(null); setInstalledName(null); }
  function clearZipInput() { if (zipInputRef.current) zipInputRef.current.value = ""; }
  function chooseZip(file: File | null) {
    invalidate(); setFolder(""); clearZipInput();
    if (file && file.size > ZIP_MAX_BYTES) { setZipFile(null); setError(required.t(TOO_LARGE)); }
    else setZipFile(file);
  }
  function chooseFolder(value: string) { invalidate(); setFolder(value); setZipFile(null); clearZipInput(); }
  function chooseReplace(value: boolean) { invalidate(); setReplace(value); }
  function hasSource() { return folder.trim() !== "" || zipFile !== null; }
  function canRun(install: boolean) { return !locked.current && hasSource() && (!install || preview !== null); }
  function currentSource(): PluginInstallSource {
    return { source: zipFile ? { kind: "zip", file: zipFile } : { kind: "folder", path: folder.trim() }, replace };
  }
  /** Runs one preview or install under the lock; a result is dropped if the inputs changed meanwhile. */
  async function perform(install: boolean) {
    if (!canRun(install)) return;
    locked.current = true; setBusy(true); setError(null); setInstalledName(null);
    const generation = ++sequence.current;
    const source = currentSource();
    try {
      await (install ? installReviewed(source, preview!, generation) : reviewSource(source, generation));
    } catch (e) {
      if (generation === sequence.current) {
        setPreview(null);
        setError(required.t(errorKey(e, install ? "Failed to install plugin." : "Failed to preview plugin.")));
      }
    } finally { locked.current = false; setBusy(false); }
  }
  async function reviewSource(source: PluginInstallSource, generation: number) {
    const result = await required.port.preview(source);
    if (generation === sequence.current) setPreview(result.plugin);
  }
  async function installReviewed(source: PluginInstallSource, reviewed: PluginInstallPreview, generation: number) {
    await required.port.install({ ...source, expectedDigest: reviewed.digest });
    if (generation !== sequence.current) return;
    await required.onInstalled();
    if (generation !== sequence.current) return;
    setInstalledName(reviewed.name); setPreview(null); setFolder(""); setZipFile(null); setReplace(false); clearZipInput();
  }
  const drop = useZipDrop({ isLocked: () => locked.current, onDropFiles: (files) => chooseZip(files[0] ?? null) });
  // A picked folder becomes `<folder>.zip` and then IS the chosen zip: same limit, preview, install.
  const folderUpload = useFolderUpload({
    maxBytes: ZIP_MAX_BYTES, tooLarge: TOO_LARGE, isLocked: () => locked.current, onZipped: chooseZip,
    onError: (key) => { invalidate(); setZipFile(null); setError(required.t(key)); },
  });
  return {
    folder, zipFile, zipInputRef, replace, preview, error, drop, folderUpload, t: required.t,
    busy: busy || folderUpload.zipping,
    zipSizeLabel: zipFile ? installArchiveSize({ bytes: zipFile.size }) : "",
    reviewDisabled: busy || folderUpload.zipping || !hasSource(),
    previewDisplay: preview ? pluginInstallPreviewDisplay(preview, required.t) : null,
    installedMessage: installedName ? required.t("{name} is installed and switched off. Turn it on in Downloaded.").replace("{name}", installedName) : null,
    setFolder: chooseFolder,
    onFolderChange: (event: ChangeEvent<HTMLInputElement>) => chooseFolder(event.target.value),
    onSubmitFolder: (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); void perform(false); },
    setZipFile: chooseZip,
    onChooseZip: () => zipInputRef.current?.click(),
    onZipChange: (event: ChangeEvent<HTMLInputElement>) => chooseZip(event.target.files?.[0] ?? null),
    setReplace: chooseReplace,
    onReplaceChange: (event: ChangeEvent<HTMLInputElement>) => chooseReplace(event.target.checked),
    cancelReview: () => { if (!locked.current) invalidate(); },
    review: () => perform(false), install: () => perform(true),
  };
}
export type PluginInstallController = ReturnType<typeof usePluginInstall>;

import { useCallback as useQueryFetchCallback } from "react";
import { useFetchQuery } from "@jini-ai/ui/fetch-query";
import { useState } from "react";

import { useAdminLocale } from "@/hooks/use-admin-locale.hooks";
import type { Translate } from "@jini-ai/ui/panel-kit";
import { t as translate } from "../plugins-i18n";
import {
  describeApiError,
  packageFilesViewState,
  type PackageFilesListing,
  type PackageFilesRead,
  type PackageFilesStatus,
  type PackageFileView,
} from "../rules";
import { defaultPluginsPort } from "./plugins-dependencies.hooks";

/**
 * @file `PluginPackageFilesModal`'s data: one `PLUGIN_FILES` read for the inspected plugin, mapped
 * onto the shared `PackageFilesModal`'s row shape, plus which file is selected. The Agent Plugins
 * viewer (`use-agent-plugin-details-modal.hooks.ts`) reuses this same hook over `AGENT_PLUGIN_FILES`
 * (2026-09-13), so both screens share one stale-read and selection implementation.
 *
 * `useX(dependencies)` / `useWiredX()` pair, same as `use-plugins.hooks.ts`: a test composes
 * {@link usePluginPackageFiles} with `createFakePluginsPort`.
 */

export interface PluginPackageFilesDependencies {
  readonly pluginId: string;
  /** CMS and agent packages have different endpoints even when their identifiers match. */
  readonly queryRoot?: "plugins" | "agent-plugins";
  /** Any read that yields a listing — `PluginsPort.getPluginFiles`, or an adapter over
   *  `AgentPluginsPort.getAgentPluginFiles`. */
  readonly port: { getPluginFiles(pluginId: string): Promise<PackageFilesListing> };
  readonly t: Translate;
}

export interface PluginPackageFilesController {
  /** `[]` until the listing settles, and after a failed load. */
  files: readonly PackageFileView[];
  /** The selected file, else the first listed one; `null` only while `files` is empty. */
  selectedFile: PackageFileView | null;
  /** Selects by `relativePath`. An unknown path falls back to the tree's top file rather than clearing. */
  selectFile: (relativePath: string) => void;
  /** Loading, failure (`role: "alert"`), or an empty package — `null` once there are files. */
  status: PackageFilesStatus | null;
  /** Set when the server's caps left some files out. */
  listNotice: string | null;
  /** Bound translator — the modal's only source of copy. */
  t: Translate;
}

/** The last settled read, tagged with the plugin it was for. */
interface SettledRead extends PackageFilesRead {
  readonly pluginId: string;
}

/**
 * Loads one plugin's package files once per `pluginId`.
 *
 * A read that settles after `pluginId` changed (or after unmount) is dropped by the effect's cleanup
 * flag, and a stored read for a different id is never rendered — so a slow response for the
 * previously inspected plugin can never show under the current one's title. Mapping the read onto
 * rows, selection, and status is `rules.ts`'s {@link packageFilesViewState}.
 *
 * @complexity One GET per `pluginId`; O(files) per render to map rows (capped server-side at 200).
 */
export function usePluginPackageFiles({ pluginId, port, t, queryRoot = "plugins" }: PluginPackageFilesDependencies): PluginPackageFilesController {
  const [selectedPath, setSelectedPath] = useState("");
  const queryFetch = useQueryFetchCallback(async () => {
    try { return await port.getPluginFiles(pluginId); }
    catch (error) { throw new Error(describeApiError(error, t("failed to load package files"))); }
  }, [port, pluginId]);
  const query = useFetchQuery({ key: [queryRoot, "files", pluginId], fetch: queryFetch }, { staleTime: 0 });
  const read: PackageFilesRead | null = query.data ? { listing: query.data, error: null }
    : query.error ? { listing: null, error: query.error.message } : null;
  return { ...packageFilesViewState(read, selectedPath, t), selectFile: setSelectedPath, t };
}

/** Binds the real `/api/.../plugins/:id/files` client and a `plugins-i18n.ts` translator for the
 *  current admin locale. */
export function useWiredPluginPackageFiles(pluginId: string): PluginPackageFilesController {
  const locale = useAdminLocale();
  const t = (key: string): string => translate({ locale: locale, key: key });
  return usePluginPackageFiles({ pluginId, port: defaultPluginsPort, t });
}

import { ApiError, authenticatedAdminRequest, WORKSPACE_ID } from "../../lib/api";
import { isAbortError } from "@jini-ai/ui/panel-kit";
import type { ComposerCapabilitySource, TovuComposerCapability } from "./composer-capabilities";

/** Installed standalone skills use a conditional snapshot scoped to this source's lifetime.
 * Selection pins guidance behind a removable composer chip; dispatch adds it to the run prompt. */

/** The three wire fields C-002 (`server/http/admin/skills.ts`) projects — never `markdown` or
 *  `bundledFiles` (INV-002); this type only needs to describe what actually crosses the wire. */
interface InstalledSkillSummary {
  readonly enabled?: boolean;
  readonly toolId: string;
  readonly name: string;
  readonly description: string;
}

interface InstalledSkillsResponse {
  readonly skills?: unknown;
}

const INSTALLED_SKILLS_PATH = `/workspaces/${WORKSPACE_ID}/skills`;
const INSTALLED_SKILLS_GROUP_ID = "installed-skills";
const INSTALLED_SKILLS_GROUP_LABEL = "Installed Skills";

/** See this file's own module doc: the one prefix guaranteed not to collide with the bundled
 *  catalog's `skill:` entries. */
const INSTALLED_SKILL_ID_PREFIX = "installed-skill:";

type SkillsSnapshot = { etag: string | undefined; capabilities: readonly TovuComposerCapability[] };

function skillsSnapshotFromBody({ body, cached, etag }: {
  body: InstalledSkillsResponse;
  cached: SkillsSnapshot | undefined;
  etag: string | undefined;
}, _options = {}): SkillsSnapshot {
  if (!Array.isArray(body.skills)) throw new TypeError("Installed skills response must contain a skills array");
  if (cached?.etag && etag === cached.etag) return cached;
  return { etag, capabilities: body.skills.filter(isInstalledSkillSummary).filter(s => s.enabled !== false).map(toCapability) };
}

/** Reuse authenticated transport and translate only its 304 error into the exact cached snapshot.
 * Invalid bodies and failures throw, so they never become successful cache entries.
 * @complexity O(n) time/space for n summaries; one request, no guidance bodies cached.
 */
async function readSkillsSnapshot(
  { request, cached }: { request: typeof authenticatedAdminRequest; cached: SkillsSnapshot | undefined },
  _options = {},
): Promise<SkillsSnapshot> {
  let etag: string | undefined;
  try {
    const body = await request<InstalledSkillsResponse>({ path: INSTALLED_SKILLS_PATH, method: "GET" }, {
      headers: cached?.etag ? { "If-None-Match": cached.etag } : {},
      onOk: response => { etag = response.headers?.get("ETag") ?? undefined; },
    });
    return skillsSnapshotFromBody({ body, cached, etag });
  } catch (error) {
    if (error instanceof ApiError && error.status === 304 && cached) return cached;
    throw error;
  }
}

function isInstalledSkillSummary(value: unknown): value is InstalledSkillSummary {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as { toolId?: unknown }).toolId === "string" &&
    typeof (value as { name?: unknown }).name === "string" &&
    typeof (value as { description?: unknown }).description === "string"
  );
}

/**
 * Turns one wire summary into a discoverable, actionable composer row.
 *
 * `insertText: ""`, not omitted: an absent `insertText` on the slash-trigger path falls back to
 * `label`, typing the skill's bare name into the draft with no instruction to act on it — the
 * exact trap `composer-capabilities.ts` documents fixing on 2026-08-21. The `resolve` binding
 * below loads the agent guidance behind the chip.
 */
function toCapability(summary: InstalledSkillSummary): TovuComposerCapability {
  return {
    groupId: INSTALLED_SKILLS_GROUP_ID,
    groupLabel: INSTALLED_SKILLS_GROUP_LABEL,
    item: {
      id: `${INSTALLED_SKILL_ID_PREFIX}${summary.toolId}`,
      label: summary.name,
      description: summary.description,
      kind: "skill",
      keywords: ["skill", summary.name],
      insertText: "",
    },
    resolve: () => ({ kind: "installed-skill", toolId: summary.toolId }),
  };
}

/**
 * Builds a {@link ComposerCapabilitySource} backed by the installed-Skills route.
 *
 * Degrades to an empty list on ANY failure — non-2xx, network error, or a body that isn't the
 * expected `{skills: [...]}` shape — rather than throwing. Load-bearing, not defensive polish
 * (INV-001): `projectComposerCapabilities` awaits every source's `list()` through one
 * `Promise.all`, so a single REJECTING source takes the WHOLE projection down with it, including
 * the bundled catalog's always-available `/search` and `/mcp` rows. A workspace with zero
 * installed skills, an unauthorized session, or a route that 500s on a duplicate-frontmatter-name
 * conflict must cost this one capability — never the rest of the composer.
 *
 * @param _input - No required inputs; defaults preserve the existing no-argument callers.
 * @param options.request - Authenticated request port, replaceable for direct failure-path tests.
 * @returns A source whose list uses its cache; reload conditionally revalidates. Force supersedes
 * pending work but still sends the validator. Failures resolve to the last good list (else empty); aborts are silent.
 * @example createInstalledSkillsComposerCapabilitySource().list();
 * @complexity Cached reads O(1); revalidation O(n) time/space for n installed skills, one request.
 */
export function createInstalledSkillsComposerCapabilitySource(
  _input: Record<string, never> = {},
  { request = authenticatedAdminRequest }: { request?: typeof authenticatedAdminRequest } = {},
): ComposerCapabilitySource & { reload: (_input?: Record<string, never>, options?: { force?: boolean }) => Promise<readonly TovuComposerCapability[]> } {
  let cached: SkillsSnapshot | undefined;
  let pending: Promise<readonly TovuComposerCapability[]> | undefined;
  let generation = 0;
  /** Revalidate once per pending request; force prevents pre-event work from publishing a cache. */
  const reload = (_required: Record<string, never> = {}, { force = false } = {}) => {
    if (pending && !force) return pending;
    const current = ++generation;
    pending = readSkillsSnapshot({ request, cached }).then(snapshot => {
      if (current === generation) cached = snapshot;
      return snapshot.capabilities;
    }).catch(error => {
      // Leaving the page cancels the shared transport; it does not mean skill enumeration failed.
      // Every failure costs this capability alone: Promise.all must retain the bundled catalog.
      // A failed 60 s revalidation keeps the last good list rather than blanking typed skills.
      if (!isAbortError({ error })) console.error(
        "[installed-skills-composer-source] installed-skills enumeration failed; falling back to the bundled catalog only",
        error,
      );
      return cached?.capabilities ?? [];
    }).finally(() => { if (current === generation) pending = undefined; });
    return pending;
  };
  return {
    id: "installed-skills",
    list: () => cached ? Promise.resolve(cached.capabilities) : reload(),
    reload,
  };
}

import { ApiError, describeApiError as describeApiErrorDefault, type AdminAgentPlugin, type AdminPlugin, type AdminPluginConflict, type AdminPluginFiles, type AdminPluginPackageFile, type AdminPluginProviderSettingField } from "../../lib/api";
import { isProviderSettingRequired } from "@jini-ai/plugins/host";
import { t } from "./plugins-i18n";
import type { Translate } from "@jini-ai/ui/panel-kit";
import type { AgentPluginGlyphKind } from "./agent-plugins-visuals";
import { buildPackageFileTree, firstPackageFilePath } from "./package-file-tree";
import type { PluginInstallPreview } from "./hooks/plugin-install-port.hooks";

/** Resource names on the existing assistant content-refresh bus. Unknown scope refreshes both. */
export const PLUGINS_RESOURCE = "plugins";
export const AGENT_PLUGINS_RESOURCE = "agent-plugins";

/**
 * @file Pure logic for the `plugins` feature — everything that computes a value rather than
 * rendering one. Follows the `posts/rules.ts` convention: no React import, no hooks, directly
 * testable.
 *
 * Moved here from `Plugins.tsx`: the screen's own `describeApiError` override, and the toggle
 * cell's visibility/label decision (`pluginToggleControl`) — previously an inline double ternary
 * inside a `DataTable` cell closure, reachable only by rendering the table.
 */

/** Overrides layered on the shared default (`lib/api.ts`'s `describeApiError`). Covers both this
 *  screen's routes: `PLUGIN_SET_ENABLED`'s three codes (unchanged) plus `PLUGIN_UNINSTALL`'s four
 *  (`PLUGIN_NOT_FOUND` is shared verbatim between both routes' error envelopes, so it needed no
 *  second entry) — see `server/inbound/admin-http/routes/plugins/uninstall.ts`'s own
 *  `sendPluginUninstallError` for the source of truth these four messages translate.
 *
 *  A `Map`, not an object literal: a server code that happens to name an `Object.prototype` member
 *  (`"toString"`) must fall through to the default, not resolve to a function. */
const PLUGIN_ERROR_MESSAGES: ReadonlyMap<string, string> = new Map([
  ["PLUGIN_NOT_FOUND", "No plugin with that id is installed."],
  ["PLUGIN_INVALID", "This plugin failed validation and cannot be enabled."],
  ["PLUGIN_INCOMPATIBLE", "This plugin requires a different SDK version."],
  ["PLUGIN_NOT_UNINSTALLABLE", "This plugin ships with Tovu and cannot be removed."],
  ["PLUGIN_ENABLED", "This plugin is enabled and must be disabled everywhere before it can be removed."],
  ["PLUGIN_IN_TRASH", "This plugin is already in the Trash. Restore or delete it there first."],
  ["PLUGIN_ID_INVALID", "This plugin's id is invalid."],
  // 2026-10-04: `PLUGIN_SET_ENABLED`'s 409 when the plugin claims a name core or an earlier-enabled
  // plugin holds. The server's own message names each clash in English; the row's detail panel
  // already lists them translated (`pluginConflictLines`), so this points there instead.
  ["PLUGIN_CONFLICT", "This plugin uses names that core or another plugin already has. Open its details to see which, and turn the other plugin off first."],
]);

/** Maps this screen's two calls' error codes to `errors.spec.md`'s operator-facing guidance text
 * (ui.spec.md §8), falling back to the server's own message. `optional.translate` translates an
 * override (the English text is the dictionary key); the server's own message is never translated.
 *
 * @complexity O(1).
 * @overallScore 100
 */
export function describeApiError(e: unknown, fallback: string, optional: { translate?: Translate } = {}): string {
  if (e instanceof ApiError && e.code !== undefined) {
    const override = PLUGIN_ERROR_MESSAGES.get(e.code);
    if (override !== undefined) return optional.translate ? optional.translate(override) : override;
  }
  return describeApiErrorDefault(e, fallback);
}

/** Replaces each `{name}` in `template` with its value, literally — a function replacer, so a `$&`
 *  or `$'` inside a plugin name or key is not read as a replacement pattern. */
function fillTemplate(template: string, values: Readonly<Record<string, string>>): string {
  return Object.entries(values).reduce((text, [name, value]) => text.replace(`{${name}}`, () => value), template);
}

/** Display label (an i18n key) per conflict `kind` the server sends — `plugin-claims.ts`'s six
 *  `contributes` kinds, `hook`, and `content-type` (AW-7 Tier 1's declared types). A `Map` for the same prototype-key reason as
 *  {@link PLUGIN_ERROR_MESSAGES}; a kind not listed is shown verbatim (the server's `kind` is free
 *  text by design, so a new one must still render). */
const CONFLICT_KIND_LABELS: ReadonlyMap<string, string> = new Map([
  ["route", "Route"],
  ["tool", "Tool"],
  ["table", "Table"],
  ["setting", "Setting"],
  ["widget", "Widget"],
  ["permission", "Permission"],
  ["hook", "Hook"],
  ["content-type", "Content type"],
]);

/** The owner id `plugin-claims.ts` files core's own claims under (`CORE_OWNER_ID`). */
const CORE_CONFLICT_HOLDER = "core";

/**
 * One sentence per name this plugin claims that core or an earlier-enabled plugin already holds
 * (`PLUGINS_LIST`'s `conflicts[]`, 2026-10-04): for a plugin that is off, what turning it on would
 * hit; for a quarantined one, why boot turned it off. A core holder shows its reserved pattern only
 * when it differs from the claimed key (a `/api/*` prefix matched `/api/seo`). Duplicate lines are
 * dropped — a manifest that names the same thing twice reports it twice.
 *
 * @complexity O(c) in the row's conflict count.
 */
export function pluginConflictLines(plugin: { readonly conflicts?: readonly AdminPluginConflict[] }, translate: Translate): string[] {
  const lines = (plugin.conflicts ?? []).map((conflict) => {
    const kindLabel = CONFLICT_KIND_LABELS.get(conflict.kind);
    const values = { kind: kindLabel === undefined ? conflict.kind : translate(kindLabel), key: conflict.key };
    if (conflict.heldBy !== CORE_CONFLICT_HOLDER) {
      return fillTemplate(translate('{kind} "{key}" is already used by {plugin}.'), { ...values, plugin: conflict.heldByName });
    }
    return conflict.heldKey === conflict.key
      ? fillTemplate(translate('{kind} "{key}" is reserved by Tovu.'), values)
      : fillTemplate(translate('{kind} "{key}" is reserved by Tovu ("{reserved}").'), { ...values, reserved: conflict.heldKey });
  });
  return [...new Set(lines)];
}

/**
 * The quarantine headline. Boot's conflict pass quarantines with `consecutiveFailures: 0` (no hook
 * ever failed), where "Quarantined after 0 consecutive failures" would read as a bug; that case says
 * what happened instead, and the reason below it says why.
 *
 * @complexity O(1).
 */
export function pluginQuarantineHeadline(quarantine: NonNullable<AdminPlugin["quarantine"]>, translate: Translate): string {
  if (quarantine.consecutiveFailures === 0) return translate("Turned off automatically");
  return fillTemplate(translate("Quarantined after {count} consecutive failures"), { count: String(quarantine.consecutiveFailures) });
}

/** What the row's detail panel shows — see {@link pluginRowDetailView}. */
export interface PluginRowDetailView {
  readonly quarantine: { readonly headline: string; readonly reason: string } | null;
  readonly conflicts: { readonly heading: string; readonly lines: readonly string[] } | null;
  readonly errors: AdminPlugin["errors"];
}

/**
 * The row's detail panel: quarantine, name conflicts, validation errors — each `null`/empty when
 * absent, and the whole view `null` when all three are, so the panel never asserts a question was
 * asked and answered none (`AgentPluginRow`'s `DetailChips` rule).
 *
 * @complexity O(c) in the row's conflict count.
 */
export function pluginRowDetailView(plugin: AdminPlugin, translate: Translate): PluginRowDetailView | null {
  const lines = pluginConflictLines(plugin, translate);
  if (!plugin.quarantine && lines.length === 0 && plugin.errors.length === 0) return null;
  return {
    quarantine: plugin.quarantine
      ? { headline: pluginQuarantineHeadline(plugin.quarantine, translate), reason: plugin.quarantine.reason }
      : null,
    conflicts: lines.length > 0 ? { heading: translate("Names already in use — turn the other plugin off first:"), lines } : null,
    errors: plugin.errors,
  };
}

/** One labelled fact in the row's detail panel — see {@link pluginRowFacts}. */
export interface PluginRowFact {
  readonly label: string;
  readonly value: string;
}

const PLUGIN_SOURCE_COPY: Record<AdminPlugin["source"], string> = {
  "built-in": "Built in — ships with Tovu",
  site: "Installed on this site",
};

/** tier-1/tier-3 reuse the install preview's trust sentences; tier-2 (built-ins only — a sideloaded
 *  package cannot claim it) runs in a separate worker over the capability-scoped SDK
 *  (`plugin-runtime/tier2/run-call.ts`). */
const PLUGIN_TIER_COPY: Record<AdminPlugin["tier"], string> = {
  "tier-1": "This plugin has no code; nothing in it runs on this computer. Turning it on only adds what it declares.",
  "tier-2": "This plugin runs code in a separate worker, limited to the capabilities it declares.",
  "tier-3": "This plugin runs code with full access to this computer and every site on it.",
};

const PLUGIN_STATUS_COPY: Record<AdminPlugin["status"], string> = {
  valid: "No problems found",
  invalid: "Invalid — see the errors below",
  incompatible: "Not compatible with this version of Tovu",
};

/**
 * The detail panel's always-present facts (mobile catalog PL-2, 2026-10-06). Before this, the
 * panel held only {@link pluginRowDetailView}'s problems, so expanding a HEALTHY plugin — most of
 * them — rotated the chevron over an empty box. `AdminPlugin` still carries no description (the
 * server envelope has none), so these are the facts the row already has, spelled out: id, where it
 * came from, what it can touch (the same trust sentences the install preview uses), health, and
 * this workspace's on/off state.
 *
 * @complexity O(1).
 */
export function pluginRowFacts(plugin: AdminPlugin, translate: Translate): PluginRowFact[] {
  return [
    { label: translate("ID"), value: plugin.id },
    { label: translate("Source"), value: translate(PLUGIN_SOURCE_COPY[plugin.source]) },
    { label: translate("Access"), value: translate(PLUGIN_TIER_COPY[plugin.tier]) },
    { label: translate("Status"), value: translate(PLUGIN_STATUS_COPY[plugin.status]) },
    { label: translate("State"), value: translate(plugin.enabled ? "On in this workspace" : "Off in this workspace") },
  ];
}

/** What the install dialog shows for a reviewed package — see {@link pluginInstallPreviewDisplay}. */
export interface PluginInstallPreviewDisplay {
  readonly title: string;
  readonly version: string;
  readonly tier: string;
  readonly capabilities: string;
  readonly hooks: string;
  readonly contentTypes: string;
  /** The trust sentence: full access for a package with code, "no code" for a tier-1 one. */
  readonly codeNotice: string;
  readonly conflicts: { readonly heading: string; readonly lines: readonly string[] } | null;
}

/**
 * The install dialog's preview. A manifest-only (tier-1) package has nothing to run — the server
 * refuses one that ships a code file — so the full-access warning would be false for it (AW-7
 * Tier 1). Conflicts are the CURRENT workspace's: install is site-wide but turning a plugin on is per
 * workspace, so the heading says so (owner question open: whether to check every workspace).
 *
 * @complexity O(c + n) in the conflict count and the listed names.
 */
export function pluginInstallPreviewDisplay(preview: PluginInstallPreview, translate: Translate): PluginInstallPreviewDisplay {
  const lines = pluginConflictLines(preview, translate);
  return {
    title: `${preview.name} (${preview.id})`,
    version: preview.upgradeFrom ? `${preview.upgradeFrom} → ${preview.version}` : preview.version,
    tier: preview.tier,
    capabilities: preview.capabilities.join(", ") || "—",
    hooks: preview.hooks.join(", ") || "—",
    contentTypes: preview.contentTypes.join(", ") || "—",
    codeNotice: translate(preview.hasCode
      ? "This plugin runs code with full access to this computer and every site on it."
      : "This plugin has no code; nothing in it runs on this computer. Turning it on only adds what it declares."),
    conflicts: lines.length > 0 ? { heading: translate("Already in use in this workspace (other workspaces are checked when you turn it on there):"), lines } : null,
  };
}

/** What the "Enabled" cell should show for one row — `visible: false` for AC-21 (enabling this row
 *  is already known to 422, so no enable-capable control is offered at all; `Roles.tsx`'s
 *  built-in-row `—` idiom). The caller renders `visible` as a plain ternary (button vs. the muted
 *  `—` fallback) on this already-computed result.
 *
 * @complexity O(1).
 */
export interface PluginToggleControl {
  visible: boolean;
  disabled: boolean;
  label: string;
}

export function pluginToggleControl(plugin: AdminPlugin, rowSavingId: string | null, locale: string): PluginToggleControl {
  if (!(plugin.enabled || plugin.status === "valid")) {
    return { visible: false, disabled: false, label: "" };
  }
  const savingThisRow = rowSavingId === plugin.id;
  return {
    visible: true,
    disabled: savingThisRow,
    // The busy-state "…" is locale-neutral (no established translated bare-ellipsis precedent
    // elsewhere in this app — every other busy label pairs it with a word, e.g. posts-i18n.ts's
    // "Creating…") and stays untranslated here on purpose.
    label: savingThisRow ? "…" : plugin.enabled ? t({ locale: locale, key: "Disable" }) : t({ locale: locale, key: "Enable" }),
  };
}

/**
 * The toggle button's `aria-label` — every row's button reads "Enable"/"Disable"/"…" on its own,
 * identical across every plugin, so a screen reader or a generic browser agent reading the
 * accessibility tree (roles + accessible names — not this repo's own `agentHandle()`, whose
 * `label` option is a private `data-agent-label` attribute neither one can see) has no way to tell
 * one row's control from another's without the plugin's own name in the accessible name.
 *
 * Names the target action (Enable/Disable), not the transient "…" busy word — the visible "…" plus
 * `disabled` already signal in-flight to a sighted operator, and an accessible name that kept
 * switching between "…" and a real verb mid-interaction would be a worse read than one that stays
 * "Enable {name}"/"Disable {name}" throughout.
 *
 * @complexity O(1).
 */
export function pluginToggleAriaLabel(plugin: AdminPlugin, locale: string): string {
  return `${plugin.enabled ? t({ locale: locale, key: "Disable" }) : t({ locale: locale, key: "Enable" })} ${plugin.name}`;
}

/**
 * The row's one-line subline, shown under its name/version heading and repeated inside its
 * expander's own quarantine/errors context: `source · tier · status` (e.g. `"site · tier-3 ·
 * valid"`). `AdminPlugin` has no free-text description field (unlike `AdminAgentPlugin`), so this
 * is built from the trust/health signal the type already carries rather than inventing prose.
 * Values are rendered verbatim, not translated — `plugin.source`/`tier`/`status` are domain
 * enum values, not copy, matching how the pre-split table rendered them (no `t()` wrapping there
 * either).
 *
 * @complexity O(1).
 */
export function pluginSubline(plugin: AdminPlugin): string {
  return `${plugin.source} · ${plugin.tier} · ${plugin.status}`;
}

/**
 * Why the Downloaded tab's Remove cannot succeed for `plugin`, or `null` when it can — the two
 * refusals `PLUGIN_UNINSTALL` itself makes (`features/plugin-runtime/uninstall.ts`), built-in first:
 * a built-in has nothing on disk to remove whether or not it is on, while an enabled site plugin
 * only needs turning off (`PLUGIN_ENABLED`). The screen shows Remove disabled and pointing at the
 * matching note, instead of offering a click the server always refuses (2026-09-13 fix).
 *
 * `enabled` is this workspace's activation; the server also refuses a plugin still enabled in
 * ANOTHER workspace, which this row cannot see — that rare refusal still reaches `rowError`.
 *
 * @complexity O(1).
 */
export function pluginRemoveBlocker(plugin: AdminPlugin): "built-in" | "enabled" | null {
  if (plugin.source === "built-in") return "built-in";
  return plugin.enabled ? "enabled" : null;
}

/**
 * The Downloaded tab's Remove button `aria-label` — every row's button reads "Remove" identically,
 * so the plugin's own name has to be in the accessible name for anything reading the accessibility
 * tree to tell rows apart (same reasoning {@link pluginToggleAriaLabel} gives for the Installed
 * tab's switch). Reads "unavailable" whenever {@link pluginRemoveBlocker} names a reason instead of
 * naming an action nobody can take — the reason itself lives in the section note the disabled
 * button's `aria-describedby` points at (`AgentPluginRow`'s own honest-disabled idiom).
 *
 * @complexity O(1).
 */
export function pluginRemoveAriaLabel(plugin: AdminPlugin, locale: string): string {
  return pluginRemoveBlocker(plugin) === null
    ? `${t({ locale: locale, key: "Remove" })} ${plugin.name}`
    : `${t({ locale: locale, key: "Remove" })} ${plugin.name} — ${t({ locale: locale, key: "unavailable" })}`;
}

/** {@link buildPluginRemoveConfirmCopy}'s two pieces of copy — same `{ title, body }` shape as
 *  `features/settings/rules.ts`'s `RemoveConfirmCopy`, the precedent this dialog mirrors. */
export interface PluginRemoveConfirmCopy {
  title: string;
  body: string;
}

/** Names the plugin, the site-wide effect, and the 60-day restore window. @complexity O(1). */
export function buildPluginRemoveConfirmCopy(
  params: { name: string },
  translate: Translate = (key) => key,
): PluginRemoveConfirmCopy {
  return {
    title: `Move "${params.name}" to trash?`,
    body: translate("This removes it for all workspaces on this site. You can restore it from the Trash for 60 days."),
  };
}

/**
 * Title-cases a kebab-case Agent Plugin id into a human display name (`"site-compliance"` ->
 * `"Site Compliance"`) — `AGENT_PLUGINS_LIST` (`server/inbound/admin-http/routes/agent-plugins/
 * list.ts`) reports only `pluginId`, never a separate hand-curated `displayName` the way the old,
 * now-deleted `TOVU_BUNDLED_AGENT_PLUGINS` catalog did, so `AgentPlugins.tsx` needs a pure
 * formatting step rather than a stored field. Mirrors `tool-registrations.ts`'s server-side
 * `humanize()` (same transform, independently kept per that file's own "private formatting helper
 * of a sibling module" precedent — see its header) — that copy has no override map of its own; it
 * feeds an LLM-facing tool description, a different surface this pass did not touch.
 *
 * @complexity O(n) in `pluginId`'s length.
 */
/**
 * Segments that are acronyms, not words. Title-casing these produced "Ui Ux Design" for the
 * installed `ui-ux-design` package (2026-09-09, seen rendered) — a name an operator has to decode
 * rather than recognize, on the one screen whose whole job is recognizing a package at a glance.
 *
 * A closed list, not a heuristic: no rule distinguishes the acronym "ui" from a hypothetical word
 * segment, and inventing one would eventually shout a real word in capitals.
 */
const AGENT_PLUGIN_ID_ACRONYMS = new Set([
  "ai", "api", "cli", "css", "html", "http", "id", "io", "json", "mcp", "rss", "sdk", "seo", "sql", "ui", "url", "ux", "yaml",
]);

export function humanizeAgentPluginId(pluginId: string): string {
  return pluginId
    .split("-")
    .filter((part) => part.length > 0)
    .map((part) =>
      AGENT_PLUGIN_ID_ACRONYMS.has(part.toLowerCase())
        ? part.toUpperCase()
        : part.charAt(0).toUpperCase() + part.slice(1),
    )
    .join(" ");
}

/**
 * The name a row shows: the package's own `displayName` (`plugin.json` `extensions.tovu.displayName`)
 * when it set one, else {@link humanizeAgentPluginId}. The id stays the stable key; only the title
 * can differ ("deploy" shows as "Server Deploy").
 *
 * @complexity O(n) in `pluginId`'s length.
 */
export function agentPluginDisplayName(plugin: { pluginId: string; displayName?: string | null }): string {
  return plugin.displayName?.trim() || humanizeAgentPluginId(plugin.pluginId);
}

/**
 * Vocabulary -> glyph family, in evaluation order. Ordered rather than a flat map because a package
 * can legitimately match two families, and a stable first-match beats whichever key an object
 * happened to iterate first.
 *
 * Matching is on whole words only. A substring match would classify any id containing "ui" —
 * `build-ui`, but also `guide-something` — as a design package.
 */
const AGENT_PLUGIN_GLYPH_VOCABULARY: ReadonlyArray<readonly [AgentPluginGlyphKind, readonly string[]]> = [
  ["compliance", ["compliance", "privacy", "gdpr", "ccpa", "cpra", "consent", "security", "audit", "wcag", "accessibility"]],
  ["deploy", ["deploy", "deployment", "hosting", "release", "ship", "production", "ci"]],
  ["design", ["design", "ui", "ux", "uiux", "theme", "brand", "visual"]],
  ["integration", ["mcp", "integration", "connector", "webhook", "api"]],
  ["content", ["docs", "documentation", "content", "writing", "copy", "blog"]],
];

/** Lowercase whole-word tokens of one string. */
function glyphTokens(value: string): string[] {
  return value.toLowerCase().split(/[^a-z0-9]+/).filter((token) => token.length > 0);
}

/** First vocabulary family any of `tokens` matches, or `undefined`. */
function matchGlyphKind(tokens: ReadonlySet<string>): AgentPluginGlyphKind | undefined {
  for (const [kind, vocabulary] of AGENT_PLUGIN_GLYPH_VOCABULARY) {
    if (vocabulary.some((word) => tokens.has(word))) return kind;
  }
  return undefined;
}

/**
 * Which glyph identifies one Agent Plugin in the installed list.
 *
 * Derived from the package's OWN vocabulary rather than from an allowlist of known plugin ids. An
 * id allowlist is exactly what `AGENT_PLUGINS_LIST` just replaced (the hardcoded
 * `TOVU_BUNDLED_AGENT_PLUGINS` catalog), and reintroducing one here would mean a future installed
 * plugin renders with no glyph until someone remembers to add it.
 *
 * The three sources are consulted in TIERS — id, then keywords, then skill names — not merged into
 * one bag. Merging is what the first attempt did, and it put the same shield on `site-compliance`
 * and `ui-ux-design`: the latter's `frontend-accessibility` skill matched the compliance family
 * before anything in its own id was considered, so the two packages this list most needs to tell
 * apart rendered identically. A package's own NAME is the strongest statement of what it is; a
 * skill it happens to bundle is the weakest.
 *
 * Falls back to `"package"` — a deliberately generic glyph — when nothing matches. Guessing a
 * themed icon for an unrecognized package would assert a category Tovu has no evidence for.
 *
 * @complexity O(k * w) over the package's own token count and the vocabulary size — both small,
 * and computed once per row render.
 */
export function agentPluginGlyphKind(plugin: {
  pluginId: string;
  keywords: readonly string[];
  skills: ReadonlyArray<{ name: string }>;
}): AgentPluginGlyphKind {
  const tiers: ReadonlyArray<readonly string[]> = [
    glyphTokens(plugin.pluginId),
    plugin.keywords.flatMap(glyphTokens),
    plugin.skills.flatMap((skill) => glyphTokens(skill.name)),
  ];

  for (const tier of tiers) {
    const kind = matchGlyphKind(new Set(tier));
    if (kind !== undefined) return kind;
  }
  return "package";
}

/**
 * The enable/disable switch's `aria-label`. Same reasoning as {@link pluginToggleAriaLabel} for the
 * sibling screen: every row's switch reads "Enable"/"Disable" identically, so without the plugin's
 * own name in the accessible name, nothing reading the accessibility tree can tell one row's
 * control from another's.
 *
 * Names the target action, not the current state, and never the transient busy state — a `role`
 * of `switch` already publishes the current position through `aria-checked`, and an accessible name
 * that flipped mid-interaction would read worse than one that stays put.
 *
 * @complexity O(1).
 */
export function agentPluginToggleAriaLabel(plugin: { pluginId: string; enabled: boolean; displayName?: string | null }, locale: string): string {
  const verb = plugin.enabled ? t({ locale: locale, key: "Disable" }) : t({ locale: locale, key: "Enable" });
  return `${verb} ${agentPluginDisplayName(plugin)}`;
}

/** {@link buildAgentPluginDisableConfirmCopy}'s two pieces of copy — same `{ title, body }` shape as
 *  `features/settings/rules.ts`'s `RemoveConfirmCopy`, the precedent this dialog mirrors. */
export interface AgentPluginDisableConfirmCopy {
  title: string;
  body: string;
  /** Present only when other enabled plugins would lose a capability this one provides. */
  dependents?: string;
}

/**
 * Names the exact plugin in the title (an operator with several installed must see WHICH one is
 * about to stop reaching the assistant), and states in the body what disabling actually does and
 * does not do: it is reversible (the package stays on disk and can be re-enabled), unlike
 * `features/settings/rules.ts`'s `buildExternalMcpRemoveConfirmCopy` counterpart, whose "Remove"
 * discards a sealed credential for good.
 *
 * `variant` is the SAME underlying operation (`AGENT_PLUGIN_SET_ENABLED` with `enabled: false`)
 * asked for from two different controls, added when Downloaded's row lost its Enable/Disable switch
 * in favor of a single Turn off/Enable action (2026-09-09 — see `AgentPlugins.tsx`'s own header):
 *   - `"disable"` — Installed tab's switch. Confirm reads "Disable"; the row it guards already says
 *     "Enabled"/"Disabled", so naming the same verb keeps the dialog consistent with the control.
 *   - `"remove"` — Downloaded tab's action button. Confirm reads "Turn off" to match that button, but
 *     the body's bundled-package sentence is reused VERBATIM across both — the fact that this can't
 *     actually delete anything doesn't change based on which control asked.
 *
 * The provenance sentence follows the row's `origin` (2026-10-21: `AGENT_PLUGINS_LIST` now sends
 * it, so the earlier "every row is bundled" assumption tracked here is retired). An
 * `operator-installed` package was added by an operator (an upload or the assistant's install
 * tool): turning it off keeps its files and memory. A bundled one ships with Tovu and can only be
 * turned off. A row without `origin` comes from a server that predates the field, when every
 * installed package was bundled, so it keeps the bundled sentence.
 *
 * @complexity Time/space: O(1) — one ternary, no iteration.
 */
export function buildAgentPluginDisableConfirmCopy(
  params: { name: string; variant: "disable" | "remove"; origin?: "bundled" | "operator-installed"; requiredBy?: readonly string[] },
  translate: Translate = (key) => key,
): AgentPluginDisableConfirmCopy {
  const copy = disableConfirmCopy(params, translate);
  // Advisory, like the server's own warning: turning it off still goes ahead if confirmed.
  if (!params.requiredBy?.length) return copy;
  return { ...copy, dependents: `${translate("Other enabled plugins rely on it:")} ${params.requiredBy.map((warning) => agentPluginWarningText({ warning, translate })).join("; ")}` };
}

/** The title and body of {@link buildAgentPluginDisableConfirmCopy}. @complexity O(1). */
function disableConfirmCopy(
  params: { name: string; variant: "disable" | "remove"; origin?: "bundled" | "operator-installed" },
  translate: Translate,
): AgentPluginDisableConfirmCopy {
  const bundledFact = params.origin === "operator-installed" ? "You added this package. Turning it off keeps its files and memory." : "This package ships with Tovu — it can't be deleted outright, only turned off.";
  if (params.variant === "remove") {
    return {
      title: `Turn off ${params.name}?`,
      body:
        translate("This turns it off: its skills stop reaching the assistant on the next run, and it drops off the Installed tab. ") +
        `${translate("It stays right here on Downloaded and can be enabled again any time.")} ${translate(bundledFact)}`,
    };
  }
  return {
    title: `Disable ${params.name} for this site?`,
    body: `${translate("Its skills stop reaching the assistant on the next run. The package stays on disk and can be enabled again.")} ${translate(bundledFact)}`,
  };
}

/** Server lifecycle warning texts this screen knows, matched in order; anything else shows as sent. */
const AGENT_PLUGIN_WARNING_PATTERNS: readonly { readonly pattern: RegExp; readonly render: (match: RegExpMatchArray, translate: Translate) => string }[] = [
  { pattern: /^Needs (\S+)$/, render: (m, translate) => translate("Needs {capabilities}").replace("{capabilities}", m[1]!) },
  { pattern: /^(\S+) needs (\S+)$/, render: (m, translate) => translate("{plugin} needs {capability}").replace("{plugin}", m[1]!).replace("{capability}", m[2]!) },
  { pattern: /^Unknown release version;/, render: (_m, translate) => translate("This package has no release version to compare.") },
  { pattern: /^Same version with different bytes;/, render: (_m, translate) => translate("Same version number as the installed one, with different contents.") },
];

/**
 * One Agent Plugin lifecycle warning in the operator's language. The server (Jini's lifecycle owner)
 * words them in English with plugin and capability ids inside: `Needs x:y` (an unmet requirement),
 * `<plugin> needs <capability>` (a dependent that would lose it) and the two update-plan notes.
 * Ids stay as sent; an unknown warning is shown verbatim rather than dropped.
 * @complexity O(1): four fixed patterns.
 */
export function agentPluginWarningText(required: { warning: string; translate: Translate }, _optional: Record<string, never> = {}): string {
  const { warning, translate } = required;
  for (const { pattern, render } of AGENT_PLUGIN_WARNING_PATTERNS) {
    const match = warning.match(pattern);
    if (match) return render(match, translate);
  }
  return warning;
}

/**
 * The row's compatibility lines, shown under its name: refused by this Tovu version (the switch
 * then answers `PLUGIN_HOST_INCOMPATIBLE`), and capabilities no other enabled plugin provides
 * (advisory: the plugin still turns on). Absent fields, from an older server, show nothing.
 * @complexity O(r) in missing requirements.
 */
export function agentPluginCompatibilityLines(required: { plugin: Pick<AdminAgentPlugin, "hostOk" | "missingRequires">; translate: Translate }, _optional: Record<string, never> = {}): string[] {
  const { plugin, translate } = required;
  const lines: string[] = [];
  if (plugin.hostOk === false) lines.push(translate("Not for this Tovu version"));
  if (plugin.missingRequires?.length) lines.push(translate("Needs {capabilities}").replace("{capabilities}", plugin.missingRequires.join(", ")));
  return lines;
}

/**
 * Only a package an operator added can be updated from this screen, and only when the server named
 * the installed revision (`archiveDigest`) the update must replace. Bundled packages update with
 * Tovu itself, so their rows never offer it.
 * @returns The installed revision the update must replace, or `undefined` when the row offers no Update.
 * @complexity O(1).
 */
export function updatableAgentPluginDigest(required: { plugin: Pick<AdminAgentPlugin, "origin" | "archiveDigest"> }, _optional: Record<string, never> = {}): string | undefined {
  const { origin, archiveDigest } = required.plugin;
  return origin === "operator-installed" && typeof archiveDigest === "string" && archiveDigest.length > 0 ? archiveDigest : undefined;
}

/**
 * Whether the settings card marks a provider field required. Like the chat form, a kept `orPresent`
 * secret (saved, left blank) satisfies the field's `requiredUnless`: the card only knows it is
 * saved, never its value, so it cannot run a `headerNames` check and the server decides on save
 * (2026-10-26 O1: a legacy OTel row authenticated by a saved Authorization header).
 * `values` are the effective values, with the `"saved"` sentinel for kept secrets.
 * @complexity O(f + b) in field count and alternative text.
 */
export function providerSettingRequiredHere(required: { field: AdminPluginProviderSettingField; fields: readonly AdminPluginProviderSettingField[]; entered: Readonly<Record<string, string | undefined>>; values: Readonly<Record<string, string>> }, _optional: Record<string, never> = {}): boolean {
  const { field, fields, entered, values } = required;
  const name = field.requiredUnless?.orPresent;
  const alternative = fields.find((other) => other.name === name);
  if (alternative?.secret && alternative.saved && !entered[alternative.name]?.trim()) return false;
  return isProviderSettingRequired({ field, values });
}

/**
 * The Downloaded tab's own remove/enable action button `aria-label` — same reasoning as
 * {@link agentPluginToggleAriaLabel} for the Installed tab's switch: every row's button reads
 * "Turn off"/"Enable" identically, so the plugin's own name has to be in the accessible name for
 * anything reading the accessibility tree to tell rows apart.
 *
 * Reads "Turn off" for a currently-enabled row (Downloaded's stand-in for the switch's "on" state —
 * see `AgentPlugins.tsx`'s own header for why Downloaded dropped the switch) and "Enable" for a
 * currently-disabled one, mirroring {@link agentPluginToggleAriaLabel}'s own verb choice exactly so
 * the two tabs describe the same underlying states in the same words.
 *
 * @complexity O(1).
 */
export function agentPluginRemoveOrEnableAriaLabel(plugin: { pluginId: string; enabled: boolean; displayName?: string | null }, locale: string): string {
  const verb = plugin.enabled ? t({ locale: locale, key: "Turn off" }) : t({ locale: locale, key: "Enable" });
  return `${verb} ${agentPluginDisplayName(plugin)}`;
}

/**
 * One row of the shared package-files viewer (`PackageFilesModal.tsx`), whichever screen fed it:
 * Agent Plugins' catalog entries fit as they are; `PLUGIN_FILES` entries go through
 * {@link toPackageFileView}.
 */
export interface PackageFileView {
  readonly relativePath: string;
  /** `null` when the file is listed but its content is not shown. */
  readonly content: string | null;
  /** Why `content` is `null`, shown in its place. */
  readonly unavailableReason?: string | null;
}

/** What the viewer's content pane says while no file is selected. */
export interface PackageFilesStatus {
  readonly text: string;
  /** `alert` for a load failure; `status` for loading or an empty package. */
  readonly role: "status" | "alert";
}

/** English source strings (the i18n keys) for each `PLUGIN_FILES` omission reason. */
const PACKAGE_FILE_OMISSION_NOTICES: Record<NonNullable<AdminPluginPackageFile["omitted"]>, string> = {
  binary: "Binary file — not shown.",
  "too-large": "Too large to show here.",
  symlink: "Symbolic link — not followed.",
  unreadable: "This file could not be read.",
};

/**
 * Maps one `PLUGIN_FILES` entry onto a viewer row. An omitted file keeps its place in the list and
 * says why it has no content; a reason this client does not know yet (or a contract-breaking
 * `null` content) reads as unreadable instead of rendering blank.
 * @complexity O(1).
 */
export function toPackageFileView(file: AdminPluginPackageFile, translate: Translate): PackageFileView {
  if (file.omitted === null && file.content !== null) return { relativePath: file.relativePath, content: file.content };
  const notice = (file.omitted && PACKAGE_FILE_OMISSION_NOTICES[file.omitted]) || PACKAGE_FILE_OMISSION_NOTICES.unreadable;
  return { relativePath: file.relativePath, content: null, unavailableReason: translate(notice) };
}

/**
 * The content pane's message before a file can be selected: a failure wins, then loading, then an
 * empty package.
 * @complexity O(1).
 */
export function packageFilesStatus(
  input: { loading: boolean; error: string | null; fileCount: number },
  translate: Translate,
): PackageFilesStatus | null {
  if (input.error !== null) return { text: input.error, role: "alert" };
  if (input.loading) return { text: translate("Loading package files…"), role: "status" };
  if (input.fileCount === 0) return { text: translate("No files to show for this plugin."), role: "status" };
  return null;
}

/** Set only when `PLUGIN_FILES` reports its caps cut the listing short.
 *  @complexity O(1). */
export function packageFilesListNotice(listing: Pick<AdminPluginFiles, "truncated"> | null, translate: Translate): string | null {
  return listing?.truncated ? translate("Some files are not listed: this package is larger than the viewer's limits.") : null;
}

/** The part of a files listing the viewer reads — shared by `PLUGIN_FILES` and
 *  `AGENT_PLUGIN_FILES`, whose responses differ only outside it. */
export type PackageFilesListing = Pick<AdminPluginFiles, "files" | "truncated">;

/** One settled package-files read: the listing, or the failure text in its place. */
export interface PackageFilesRead {
  readonly listing: PackageFilesListing | null;
  readonly error: string | null;
}

/** What the package-files viewer renders from one read — see {@link packageFilesViewState}. */
export interface PackageFilesViewState {
  readonly files: readonly PackageFileView[];
  readonly selectedFile: PackageFileView | null;
  readonly status: PackageFilesStatus | null;
  readonly listNotice: string | null;
}

/**
 * The file whose `relativePath` is `selectedPath`, else the tree's top file row (what the user sees
 * first, not the listing's first entry); `null` only for an empty list. An unknown path falls back
 * the same way rather than clearing the selection.
 * @complexity O(files log files) on the fallback, O(files) otherwise.
 */
export function selectPackageFile(files: readonly PackageFileView[], selectedPath: string): PackageFileView | null {
  const selected = files.find((file) => file.relativePath === selectedPath);
  if (selected) return selected;
  const topPath = firstPackageFilePath(buildPackageFileTree(files.map((file) => file.relativePath)));
  return files.find((file) => file.relativePath === topPath) ?? files[0] ?? null;
}

/**
 * Maps one read onto the viewer's rows, selection, status, and caps notice. `read` is `null` while
 * the listing is still loading.
 * @complexity O(files) — capped server-side at 200.
 */
export function packageFilesViewState(read: PackageFilesRead | null, selectedPath: string, translate: Translate): PackageFilesViewState {
  const listing = read?.listing ?? null;
  const files = (listing?.files ?? []).map((file) => toPackageFileView(file, translate));
  return {
    files,
    selectedFile: selectPackageFile(files, selectedPath),
    status: packageFilesStatus({ loading: read === null, error: read?.error ?? null, fileCount: files.length }, translate),
    listNotice: packageFilesListNotice(listing, translate),
  };
}

/** Guidance stays host context until dispatch; transcript and title inputs stay user-authored. */
export interface SelectedComposerSkill {
  readonly toolId: string;
  readonly name: string;
  /** Verbatim loadSkillDraft result, including fs_read_file reference descriptors and Task suffix. */
  readonly guidance: string;
}

export function selectedSkillsFromContext(context: Record<string, unknown> | undefined): readonly SelectedComposerSkill[] {
  const skills = context?.selectedSkills;
  if (!Array.isArray(skills)) return [];
  return skills.filter((skill): skill is SelectedComposerSkill => skill !== null && typeof skill === "object" && typeof skill.toolId === "string" && typeof skill.name === "string" && typeof skill.guidance === "string");
}

export function promptWithSelectedSkills(prompt: string, context: Record<string, unknown> | undefined): string {
  const skills = selectedSkillsFromContext(context);
  return skills.length === 0 ? prompt : `${skills.map(skill => skill.guidance).join("\n\n")}${prompt}`;
}

/** Plus selections keep the entire draft; slash selections remove only the active /query. */
export function draftAfterSkillSelection(draft: string, source: "plus" | "slash"): string {
  return source === "slash" ? draft.replace(/^\/[^\s/]*\s*/, "") : draft;
}

