// ---------------------------------------------------------------------------
// Column sort (2026-08-10, Updated only; generalized to Title/Slug/Status 2026-09-02; migrated onto
// `DataTable`'s own shared sort mechanism 2026-09-02) — `Posts.tsx` used to hand-roll its own sort
// dispatcher, header-click transition, caret glyph, and accessible-name plumbing because `DataTable`
// had nowhere to put any of that (see that component's own file header, `@jini-ai/admin`). Now that
// `DataTable` owns all of it generically via `DataTableColumn.sort`/`DataTableProps.sort`/
// `onSortChange`, only the genuinely domain-specific pieces stay here: each column's ascending
// comparator, the Updated column's non-default starting direction, and every column's
// accessible-name phrasing. One active column at a time — the owner did not ask for multi-column
// sort, and `DataTable` itself enforces that.
// ---------------------------------------------------------------------------

/** The Posts list's default sort on first load — unchanged from the pre-existing Updated-only
 *  behavior (newest first) now that Title/Slug/Status are sortable too, so adding them does not
 *  itself change what an operator sees before ever clicking a header. */
export const DEFAULT_POST_SORT: DataTableSortState = { column: "updated", direction: "desc" };

/** `status` is exactly `"draft" | "published"` (`post.ts`), so plain alphabetical order already
 *  equals domain order — no custom rank table needed. Ascending-only, matching
 *  `DataTableColumnSort.compare`'s own contract: `DataTable` negates this for `"desc"` rather than
 *  this module taking a direction parameter itself. */
export function comparePostsByTitle(a: AdminPost, b: AdminPost): number {
  return a.title.localeCompare(b.title);
}

/** @see comparePostsByTitle — same contract, compared on `slug` instead of `title`. */
export function comparePostsBySlug(a: AdminPost, b: AdminPost): number {
  return a.slug.localeCompare(b.slug);
}

/** @see comparePostsByTitle — same contract, compared on `status` instead of `title`. */
export function comparePostsByStatus(a: AdminPost, b: AdminPost): number {
  return a.status.localeCompare(b.status);
}

/**
 * Ascending order = oldest-first; `DataTable` negates it for `"desc"` (newest-first), which is also
 * this column's own starting direction (its `defaultDirection` in `Posts.tsx`'s column definition) —
 * an operator's first click on "Updated" has always meant "show me the newest," unlike the other
 * three columns' natural A-to-Z first read.
 *
 * Note for callers: the server's `listPosts` has no `ORDER BY` today (confirmed against
 * `PostSqliteRepo.list` — a plain `select().from(posts).where(...)`), so rows arrive in table scan
 * order, not `updatedAt` order. This comparator is what actually produces "most recent first" rather
 * than that already being true of the input. `Date.parse`, not a string compare — `updatedAt` is
 * ISO-8601 **text** with no schema guarantee against a future non-`Z` UTC-offset value, which
 * string-sorts wrong against `Z`-form values.
 */
export function comparePostsByUpdated(a: AdminPost, b: AdminPost): number {
  return Date.parse(a.updatedAt) - Date.parse(b.updatedAt);
}

/**
 * The accessible name for a lexicographic column's (Title/Slug/Status) sort control, in every state
 * `DataTable` can ask for — states the CURRENT state and what activating the control does next,
 * rather than relying on the visual caret alone (`DataTable` marks that `aria-hidden`). `direction`
 * is `null` when a different column is currently active — `DataTable` resolves that itself, so
 * unlike the pre-existing hand-rolled version this needs no `PostSortState`/column comparison here.
 *
 * `columnName` is supplied by the caller (`Posts.tsx`), translated the same way that screen
 * translates the header text — mirrors `pages/rules.ts`'s `pageColumnSortLabel` exactly (a browser
 * sweep, 2026-09-22, found this function returning a plain untranslated template while its `pages`
 * twin already called `t()`).
 *
 * @complexity Time/space: O(1).
 */
export function postColumnSortLabel(t: Translate, columnName: string, direction: DataTableSortDirection | null): string {
  if (direction === null) return t("Not sorted by {columnName}. Activate to sort ascending.").replace("{columnName}", columnName);
  return direction === "asc"
    ? t("Sorted by {columnName}, ascending. Activate to sort descending.").replace("{columnName}", columnName)
    : t("Sorted by {columnName}, descending. Activate to sort ascending.").replace("{columnName}", columnName);
}

/** Same contract as {@link postColumnSortLabel}, phrased in the Updated column's own "newest"/
 *  "oldest" vocabulary rather than generic "ascending"/"descending" — mirrors `pages/rules.ts`'s
 *  `updatedPageColumnSortLabel` verbatim. */
export function updatedColumnSortLabel(t: Translate, direction: DataTableSortDirection | null): string {
  if (direction === null) return t("Not sorted by updated date. Activate to sort newest first.");
  return direction === "desc"
    ? t("Sorted by updated date, newest first. Activate to sort oldest first.")
    : t("Sorted by updated date, oldest first. Activate to sort newest first.");
}

/**
 * Drag-and-drop image support for a URL dragged in from elsewhere (e.g. an image dragged out of
 * another browser tab) — the dropped resource's own URI is inserted as a legacy `src`-only image
 * node, unchanged; `render.ts`'s `"image"` case still degrades an untrusted `src` to the public-safe
 * placeholder, same as it always has for this shape.
 *
 * A dropped LOCAL FILE is deliberately NOT handled here (2026-08-12, B1 — file-handler drag/paste
 * upload). It used to be inlined as a `data:` URL straight into `bodyJson` (a real memory cost —
 * `readFileAsDataUrl`'s own doc), which `@tiptap/extension-file-handler`'s `onDrop` now supersedes:
 * it uploads through the real media-library path and inserts the SAME ref-based
 * `{assetId, transformName}` node the Media picker produces (`use-post-editor.hooks.ts`'s
 * `handleFileDrop`). This function returning `false` for a file drop is load-bearing, not a gap —
 * `handleDrop` set directly on `useEditor`'s `editorProps` (this function) runs BEFORE any
 * extension-registered ProseMirror plugin's own `handleDrop` (confirmed against `prosemirror-view`'s
 * `EditorView.someProp`: direct view props are tried first, plugin props only if every direct prop
 * returns nothing), so this function returning `true` for a file drop would make FileHandler's own
 * `onDrop` permanently unreachable for local files — a silent regression of the exact "editor works,
 * public site doesn't" shape this whole file's own render-contract discipline exists to catch,
 * except this one would have broken in the OTHER direction (a feature that never fires at all).
 *
 * Returns `true` when it consumed the drop, which is what tells ProseMirror not to apply its own
 * default handling — the return value is the contract, and it is why this is worth having out here
 * where a test can drive it with a fake `EditorView` instead of a real editor and a real drag.
 *
 * @complexity Time/space: O(1) — a single `DataTransfer` read, no iteration.
 */
export function handleImageDrop(view: EditorView, event: DragEvent, moved: boolean): boolean {
  if (moved) return false; // internal content reorder, not an external drop

  const uri = droppedUri(event.dataTransfer ?? null);
  if (/^https?:\/\//i.test(uri)) {
    event.preventDefault();
    const pos = view.posAtCoords({ left: event.clientX, top: event.clientY })?.pos ?? view.state.selection.to;
    const node = view.state.schema.nodes.image.create({ src: uri });
    view.dispatch(view.state.tr.insert(pos, node));
    return true;
  }

  return false;
}

// ---------------------------------------------------------------------------
// Post-title-in-document (2026-08-11) — see `lib/post-title-extension.ts`'s file header for the
// feature this pair of pure functions belongs to and why the title lives in `bodyJson` at all.
// ---------------------------------------------------------------------------

/** Loose TipTap JSON node shape — same "typed loosely, never TipTap's `JSONContent`" convention
 *  `PostFormState.bodyJson`'s own doc states, since these two functions only ever read/build a few
 *  known keys, never the full node vocabulary. */
type LooseNode = { type?: unknown; content?: unknown; attrs?: unknown; text?: unknown };

function isLooseNode(value: unknown): value is LooseNode {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** A `title`-type node carrying `text` as its sole content — `[]` (no text child) when `text` is
 *  empty, matching how TipTap represents an empty node (an empty `content` array, never a text node
 *  with `text: ""`, which ProseMirror's own schema rejects). */
function titleNode(text: string): LooseNode {
  return { type: "title", content: text ? [{ type: "text", text }] : [] };
}

/**
 * Ensures `bodyJson` starts with a `title` node — the post-title-in-document feature's back-compat
 * seam. Every post saved before this feature has a `bodyJson` with no `title` node at all (the
 * editor's custom `doc` schema, `content: "title block+"`, would reject loading it as-is), so the
 * editor's load effect (`use-post-editor.hooks.ts`) runs every `bodyJson` through this FIRST:
 *
 *  - Already migrated (first content node is already `type: "title"`): passed through unchanged.
 *  - Anything else: a title node synthesized from the post's own (pre-existing) `title` field is
 *    prepended, with a single empty paragraph appended when the source had no block content at all
 *    (a brand-new post's empty `bodyJson`, or any other doc with no blocks) — `"title block+"`
 *    requires at least one block, and a post can otherwise be entirely blank.
 *
 * Idempotent and side-effect-free — safe to call on every load regardless of whether migration is
 * actually needed, so the caller never has to detect that itself.
 *
 * @complexity O(n) in `bodyJson`'s own top-level content length (one array copy/prepend, no
 * recursion into nested content).
 */
export function withTitleNode(bodyJson: unknown, title: string): LooseNode {
  const doc = isLooseNode(bodyJson) ? bodyJson : null;
  const content = doc && Array.isArray(doc.content) ? doc.content : [];
  const first = content[0];
  if (isLooseNode(first) && first.type === "title") return doc as LooseNode;

  const blocks = content.length > 0 ? content : [{ type: "paragraph" }];
  return { type: "doc", content: [titleNode(title), ...blocks] };
}

/**
 * The current title node's plain text, read out of a live `editor.getJSON()` snapshot — the
 * in-canvas-edit half of the title's two-way sync with the standalone title `<input>` (see
 * `use-post-editor.hooks.ts`'s `onUpdate`). `""` when the doc's first child isn't a `title` node —
 * not expected once `withTitleNode` has run once, but kept total rather than throwing on a malformed
 * snapshot, same defensive posture every other reader in this module takes on `bodyJson`.
 *
 * @complexity O(t) in the title node's own inline content length.
 */
export function titleNodeText(bodyJson: unknown): string {
  const doc = isLooseNode(bodyJson) ? bodyJson : null;
  const content = doc && Array.isArray(doc.content) ? doc.content : [];
  const first = content[0];
  if (!isLooseNode(first) || first.type !== "title") return "";
  const inner = Array.isArray(first.content) ? first.content : [];
  return inner.map((n) => (isLooseNode(n) && typeof n.text === "string" ? n.text : "")).join("");
}

/** The Preview tab's three mutually exclusive surfaces — see {@link resolvePostPreviewBranches}. */
export interface PostPreviewBranches {
  canShowLiveSite: boolean;
  canShowTemplatePreview: boolean;
  canShowPendingContentPreview: boolean;
}

/**
 * Which Preview-tab surface a post gets (`PostEditor.tsx`'s `PostPreview` doc describes all three).
 * The one shared copy of this decision: `PostPreview` reads it to pick what to draw, and
 * `usePostEditor` reads it to decide whether the pending-content form auto-submits. Those two used
 * to hold hand-copied conditions that drifted on 2026-09-11 — the component drew the pending-content
 * iframe for a clean draft while the hook never submitted into it, so it sat at `about:blank`.
 *
 * The pending-content preview is the plain negation of the other two, so every draft, clean or
 * dirty, previews through the real template — there is no raw editor-buffer fallback any more.
 *
 * @param input.status - The post's saved status.
 * @param input.scheduled - A published row still waiting for its go-live time
 *   ({@link isScheduledPost}). It has no public URL yet (it 404s until then), so it previews exactly
 *   like a draft.
 * @param input.dirty - Any unsaved change, a pending template choice included.
 * @param input.contentDirty - An unsaved change to what renders (a strict subset of `dirty`).
 * @returns Exactly one `true` flag, for every combination of inputs.
 * @complexity O(1).
 */
export function resolvePostPreviewBranches(input: {
  status: "draft" | "published";
  scheduled?: boolean;
  dirty: boolean;
  contentDirty: boolean;
}): PostPreviewBranches {
  const live = input.status === "published" && !input.scheduled;
  const canShowLiveSite = live && !input.dirty;
  const canShowTemplatePreview = live && !input.contentDirty && !canShowLiveSite;
  return { canShowLiveSite, canShowTemplatePreview, canShowPendingContentPreview: !canShowLiveSite && !canShowTemplatePreview };
}

/**
 * Scheduled publishing (2026-10-05) — the stored `publishAt` (ISO UTC, `AdminPost.publishAt`) as the
 * `YYYY-MM-DDTHH:mm` value a `<input type="datetime-local">` shows, in the BROWSER's timezone (the
 * operator thinks in their own clock; the server only ever sees UTC). `""` for none or unparseable.
 *
 * @complexity O(1).
 */
export function isoToLocalDateTimeInput(iso: string | null | undefined): string {
  if (!iso) return "";
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return "";
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

/**
 * The inverse of {@link isoToLocalDateTimeInput}: a `datetime-local` value (no offset, browser-local
 * by definition) to the offset-qualified ISO string the server's `normalizePublishAt` requires, or
 * `null` ("no schedule") for an empty or unparseable value.
 *
 * @complexity O(1).
 */
export function localDateTimeInputToIso(value: string): string | null {
  if (value.trim() === "") return null;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}

/** Whether a published row is still waiting for its go-live time — the admin mirror of the server's
 *  `isScheduledAt` (`contracts/core/scheduled-publish.ts`). @complexity O(1). */
export function isScheduledPost(input: { status: "draft" | "published"; publishAt: string | null }, nowMs: number): boolean {
  return input.status === "published" && input.publishAt !== null && Date.parse(input.publishAt) > nowMs;
}

/** Whether the editor shows the cover-image slot above the title node: only for a TipTap body
 *  (`bodyFormat` "doc", the default when absent), never an html page. @complexity O(1). */
export function showsCoverImageSlot(bodyFormat: "doc" | "html" | undefined): boolean {
  return (bodyFormat ?? "doc") === "doc";
}

/** Whether the cover slot carries the "Hide the cover image in the body" toggle (owner, 2026-10-11,
 *  moved there from the settings modal's Image tab): posts only, as it was in that tab.
 *  @complexity O(1). */
export function showsHideCoverInBodyToggle(kind: "post" | "page"): boolean {
  return kind === "post";
}

/** A persisted manual slug or any publication history freezes title following. */
export function postSlugFollowsTitle(
  { post, manuallyEdited = false }: { post: Pick<AdminPost, "kind" | "status" | "title" | "slug" | "everPublished">; manuallyEdited?: boolean },
  _optional: Record<string, never> = {},
): boolean {
  return post.kind === "post" && post.status !== "published" && !post.everPublished && !manuallyEdited && isAutomaticPostSlug(post);
}

/** Preview the same bounded base the server derives; the server chooses the available suffix. */
export function postSlugForTitle({ title }: { title: string }, _optional: Record<string, never> = {}): string {
  return derivePostSlugBase({ title });
}

import { agentHandle } from "@jini-ai/agentic";
import { Dialog } from "@jini-ai/ui-kit/react";
import "../../styles/native-domain-dialogs.css";

import type { PublishCriteria, PublishReportRow, PublishRequestResult, PublishScope } from "@tovu/publish-content-ui";

import type { Translate } from "@jini-ai/ui/panel-kit";
import {
  overwriteTooltipFor,
  reportRowNote,
  reportRowPillClass,
  usePublishContentConfirm,
} from "./hooks/use-publish-content-confirm.hooks";
import type { PublishContentConfirmView } from "./hooks/use-publish-content-confirm.hooks";
import type { PublishContentPort } from "./hooks/publish-content-port.hooks";

/**
 * @file The publish-content slice's dialog, opened from the Dashboard's header button, and the whole
 * plan -> report -> confirm -> execute ceremony behind it
 * (`ADS-memory/reports/2026-09-18-publish-feature-implementation-plan.md` §4 task 11).
 *
 * Its job is educational, not just a yes/no gate: the owner's stated worry is operators deploying
 * the site, seeing no change, and not understanding that a deploy ships CODE while this dialog's
 * action ships CONTENT — two different things this app has never distinguished for anyone before.
 * The body copy says that explicitly rather than assuming it's obvious.
 *
 * ## The report table is the safety feature, not a progress indicator
 *
 * A publish never overwrites something edited on the far side; it reports it and moves on
 * (`features/publish-content/planner.ts`'s seven outcomes). That promise is only worth anything if
 * the operator can SEE which entities were skipped and why before committing — so the plan step runs
 * first, renders one row per entity with its reason, and only then offers a button that writes. A
 * skipped row carries no control that could publish it — not even a disabled checkbox: exclusion is
 * by construction, not by an unchecked box.
 *
 * Rows the run WOULD write are checked by default and can be unchecked (owner-directed, 2026-09-19).
 * That stays consistent with the paragraph above rather than contradicting it: unchecking is how an
 * operator publishes LESS, never more, and it is honoured by re-planning against a bundle narrowed to
 * the checked rows (see `hooks/use-publish-content-confirm.hooks.ts`'s `confirmPlan`), so a
 * deselected entity never reaches the live site at all. `@tovu/publish-content-ui`'s `report-rows.ts`
 * owns which rows may carry a checkbox; this file only renders the answer.
 *
 * Every decision this file renders comes from `hooks/use-publish-content-confirm.hooks.ts`, and
 * every rule the hook applies comes from `@tovu/publish-content-ui` — the same module the server's
 * own planner semantics are pinned against. This component contains no publish logic at all.
 *
 * Domain markup and actions retain the `settings-dialog`/`btn-secondary`/`btn-primary` styling.
 * Jini owns native cancellation and initial Cancel focus; the original action hierarchy followed
 * `features/plugins/AgentPluginDisableConfirmDialog.tsx` as the then-current precedent. Confirm is `.btn-primary` here, not `.btn-danger`: publishing isn't
 * destructive the way removing a plugin or an OAuth connection is, it's the app's one deliberate
 * primary action, so it gets the same burnt-orange fill `.btn-primary` already renders everywhere
 * else. Cancel stays the default-focused control anyway: publishing touches the live site and can
 * skip content without the operator noticing, so the interrupting action is still never the one
 * Enter fires by accident, matching every other confirm dialog's own reasoning even though this one
 * isn't destructive.
 *
 * ## "Overwrite on live" (publish-overwrite-live-plan-2026-09-24.md §4/S9)
 *
 * A skipped row whose planner said it COULD be resolved by overwriting live (`row.overwritable`,
 * `@tovu/publish-content-ui`'s `report-rows.ts`) gets its own checkbox in a column this file adds
 * only while there is at least one such row AND the peer this plan targets can actually honour it
 * (`view.liveCanOverwrite`). Ticking one is not itself what overwrites anything — it re-plans through
 * `hooks/use-publish-content-confirm.hooks.ts`'s `onToggleOverwrite`, and the row only leaves
 * `skipped` once that re-plan comes back `forced`. An older live gets one sentence under the table
 * instead of any checkbox at all (`view.overwriteUnavailable`); a live that moved between the first
 * plan and a later tick gets `view.overwriteMismatch` alongside the freshly re-planned rows, never a
 * silently stale table.
 *
 * ## The empty state is the connect action, not a dead end
 *
 * When `view.connectOffer` is set (no peer configured yet), the SAME primary button below becomes
 * the connect action rather than a second button appearing next to a disabled "Publish" — one
 * visible control, whatever the dialog's current job is. `view.connectOffer.message` is the
 * server's own sentence (`routes/publish-content/destination.ts`), rendered verbatim: it already
 * names the pre-filled candidate site, so this file adds no copy of its own about what connecting
 * means. See that route's header for why this dialog is where the action lives at all.
 */

export interface PublishContentDialogProps {
  onCancel: () => void;
  /** The screen's own bound translator, threaded down rather than resolved again here — same
   *  convention `AgentPluginDisableConfirmDialog` uses for its own `t`. */
  t: Translate;
  /** Dependency injection seam for tests — see `hooks/publish-content-port.hooks.ts`. */
  port?: PublishContentPort;
  /** `publish-criteria-tool-webmcp-plan-2026-09-24.md` §4 S2 — threaded straight through to
   *  `usePublishContentConfirm`; see that hook's own `props.criteria` doc for what it does. */
  criteria?: PublishCriteria;
  /** `plan-publish-sections-2026-09-25.md` §2 S2 — threaded straight through to
   *  `usePublishContentConfirm`; see that hook's own `props.scope` doc for what it does. */
  scope?: PublishScope;
  /** Threaded straight through to `usePublishContentConfirm`; see that hook's own `props.onPlanned`
   *  doc for when it fires. */
  onPlanned?: (result: PublishRequestResult) => void;
  /** Threaded straight through to `usePublishContentConfirm` — tests pass 0 to skip the arming delay. */
  confirmArmDelayMs?: number;
}

export function PublishContentDialog({
  onCancel,
  t,
  port,
  criteria,
  scope,
  onPlanned,
  confirmArmDelayMs,
}: PublishContentDialogProps) {
  const view = usePublishContentConfirm({ onCancel, t, port, criteria, scope, onPlanned, confirmArmDelayMs });

  return (
    <Dialog
      open
      title={t(view.title)}
      onClose={() => view.onDismiss()}
      pending={!view.dismissible}
      className={`settings-dialog jini-domain-dialog${view.rows.length > 0 ? " publish-content-dialog" : ""}`}
    >
      <p>{t(view.description)}</p>
      <p>{t("Anything edited on the live site is skipped unless you tick Overwrite on live.")}</p>

      {view.peers.length > 1 && (
        <label className="field">
          <span>{t("Publish to")}</span>
          <select
            value={view.selectedPeerId ?? ""}
            disabled={!view.peerSelectionEnabled}
            onChange={(e) => view.onSelectPeer(e.target.value)}
            {...agentHandle(
              { handle: "dashboard-publish-content-peer" },
              {
                // `AgentElementRole` has no `select` member — a `<select>` is a `field` in that
                // vocabulary, same as every other value-carrying control.
                role: "field",
                label: "Which site to publish this content to",
              }
            )}
          >
            <option value="">{t("Choose a site…")}</option>
            {view.peers.map((peer) => (
              <option key={peer.id} value={peer.id}>
                {peer.label}
              </option>
            ))}
          </select>
        </label>
      )}
      {view.peers.length === 1 && (
        <p className="muted publish-content-target">
          {t("Publishing to")} <strong>{view.peers[0].label}</strong>
        </p>
      )}

      <PublishContentNotices view={view} t={t} />

      <PublishContentReport view={view} t={t} />

      <span className="editor-actions">
        {/* Cancel is the default-focused control — see this file's header for why, even though
              this dialog isn't destructive. */}
        <button
          type="button"
          className="btn-secondary"
          data-jini-autofocus=""
          disabled={!view.dismissible}
          onClick={view.onDismiss}
          {...agentHandle(
            { handle: "dashboard-publish-content-cancel" },
            {
              role: "button",
              label: "Close this dialog without publishing",
            }
          )}
        >
          {t("Cancel")}
        </button>
        {/* Two different buttons, keyed apart so the confirm is a new element rather than the plan
              button relabelled in place — a click waiting on "Planning…" must never land on
              "Publish N items" (owner report 2026-09-26; see `CONFIRM_ARM_DELAY_MS`). */}
        {view.primaryKind === "start" ? (
          <button
            key="start"
            type="button"
            className="btn-primary"
            disabled={view.primaryDisabled}
            onClick={view.onPrimary}
            {...agentHandle(
              { handle: "dashboard-publish-content-plan" },
              {
                role: "button",
                // While `connectOffer` is set this button connects the pre-filled site instead of
                // planning — see this file's header.
                label: view.connectOffer
                  ? "Connect this site so it can publish, using the pre-filled site address"
                  : "Work out what would be published, without publishing anything",
              }
            )}
          >
            {view.primaryLabel}
          </button>
        ) : (
          <button
            key="confirm"
            type="button"
            className="btn-primary"
            disabled={view.primaryDisabled}
            onClick={view.onPrimary}
            {...agentHandle(
              { handle: "dashboard-publish-content-confirm" },
              {
                role: "button",
                label: "Publish the checked items to the live site",
              }
            )}
          >
            {view.primaryLabel}
          </button>
        )}
      </span>
    </Dialog>
  );
}

interface PublishContentSectionProps {
  view: PublishContentConfirmView;
  t: Translate;
}

function PublishContentNotices({ view, t }: PublishContentSectionProps) {
  return (
    <>
      {view.connectOffer && <p className="notice">{view.connectOffer.message}</p>}
      {view.refusalReason && (
        <p className="notice error" role="alert">
          {view.refusalReason}
        </p>
      )}
      {view.errorMessage && (
        <p className="notice error" role="alert">
          {view.errorMessage}
        </p>
      )}
      {view.doneMessage && (
        <p className="notice" role="status">
          {view.doneMessage}
        </p>
      )}
      {view.doneNotices.map((line) => (
        <p key={line} className="notice">
          {line}
        </p>
      ))}
      {view.doneProblems.length > 0 && (
        <div className="notice error" role="alert">
          <p>{t("Published, but these won't show correctly on the live site:")}</p>
          <ul>
            {view.doneProblems.map((line) => (
              <li key={line}>{line}</li>
            ))}
          </ul>
        </div>
      )}
      {view.liveGapNotices.map((line) => (
        <p key={line} className="notice publish-content-live-gap" role="status">
          {line}
        </p>
      ))}
    </>
  );
}

function PublishContentReport({ view, t }: PublishContentSectionProps) {
  // publish-overwrite-live-plan §4/S9. The column exists only while the peer this plan targets can
  // honour a forced overwrite AND at least one row is offering one — decided in the hook.
  const { showOverwriteColumn } = view;

  // One report row. Up-to-date rows fold behind one "N already up to date" row (owner 2026-09-26),
  // so this renders both halves of the list the hook splits.
  const renderRow = (row: PublishReportRow) => (
    <tr key={row.key} data-entity-id={row.entityId} data-publish-disposition={row.disposition}>
      <td className="publish-content-select">
        {/* A row the run would not write carries NO control at all, not a disabled
            one: plan §4 task 11's property is that nothing in this dialog can move a
            skipped row into the set that gets published. */}
        {row.selectable && (
          <input
            type="checkbox"
            checked={view.selectedKeys.has(row.key)}
            disabled={!view.selectionEnabled}
            onChange={() => view.onToggleRow(row.key)}
            // No `agentHandle` here: a handle must be lowercase words joined by
            // hyphens, and a row key is an entity id. The row's own
            // `data-entity-id` is the stable address instead — an agent (or a test)
            // finds the row, then the one checkbox inside it.
            data-publish-row-select=""
            aria-label={`${t("Publish")} ${row.entityType} ${row.entityLabel}`}
          />
        )}
        {/* Owner decision 2026-09-25 — media carried along with the pages/posts
            that use it: shown ticked while one of them is, and never clickable
            itself (it follows those rows, not the operator). */}
        {row.includedFor.length > 0 && (
          <input
            type="checkbox"
            checked={view.carriedAlongKeys.has(row.key)}
            disabled
            readOnly
            data-publish-row-carried=""
            aria-label={`${t("Publish")} ${row.entityType} ${row.entityLabel}`}
          />
        )}
      </td>
      <td>{t(row.entityTypeLabel)}</td>
      {/* A long label is cut off with an ellipsis (publish-content.css), so the
          hover shows the same label in full. The id stays on the row's
          `data-entity-id`, never in the tooltip (owner report 2026-09-26). */}
      <td title={row.entityLabel}>{row.entityLabel}</td>
      <td>
        <span className={reportRowPillClass(row)}>{t(row.dispositionLabel)}</span>
        {/* The reason sits under the status it explains — most rows have none, so a
            column of its own was mostly empty (owner 2026-09-26). */}
        {reportRowNote(row, t) && <span className="publish-content-reason">{reportRowNote(row, t)}</span>}
      </td>
      {showOverwriteColumn && (
        <td className="publish-content-overwrite">
          {/* Only an offered row (overwritable, or already ticked) carries this
              control — same "no affordance at all on a row it doesn't apply to" rule
              the select column follows above. */}
          {view.overwriteOfferKeys.has(row.key) && (
            <input
              type="checkbox"
              checked={view.overwriteKeys.has(row.key)}
              disabled={!view.selectionEnabled}
              onChange={() => view.onToggleOverwrite(row.key)}
              data-publish-row-overwrite=""
              aria-label={row.retiresLabel ? `${t("Overwrite on live")}: ${row.retiresLabel}` : t("Overwrite on live")}
              // R6 (`plan-publish-repoint-menus-2026-09-24.md` §2.7) — when the
              // retired holder still feeds a live menu, the tooltip names it too, so
              // an operator ticking "overwrite" can see what else moves with it. The
              // copy itself is built in the hooks file, not here — see
              // `overwriteTooltipFor`'s own doc.
              title={overwriteTooltipFor(row, t)}
            />
          )}
        </td>
      )}
    </tr>
  );

  return view.rows.length > 0 ? (
    <>
      <div className="table-scroll publish-content-report">
        <table className="list-table">
          <thead>
            <tr>
              <th className="publish-content-select">
                <input
                  type="checkbox"
                  checked={view.allSelected}
                  // React has no `indeterminate` prop — the partial state is a DOM property
                  // only, so it is set on the node itself every render.
                  ref={(node) => {
                    if (node) node.indeterminate = view.someSelected;
                  }}
                  disabled={!view.selectionEnabled || view.rows.every((row) => !row.selectable)}
                  onChange={view.onToggleAll}
                  aria-label={t("Publish every item that can be published")}
                  {...agentHandle(
                    { handle: "dashboard-publish-content-select-all" },
                    {
                      role: "field",
                      label: "Check or uncheck every publishable row at once",
                    }
                  )}
                />
              </th>
              <th>{t("Type")}</th>
              <th>{t("Item")}</th>
              <th>{t("What happens")}</th>
              {showOverwriteColumn && (
                <th className="publish-content-overwrite">
                  <input
                    type="checkbox"
                    checked={view.allOverwriteTicked}
                    // Same DOM-only indeterminate handling as the select-all box above — React
                    // has no prop for it.
                    ref={(node) => {
                      if (node) node.indeterminate = view.someOverwriteTicked;
                    }}
                    disabled={!view.selectionEnabled}
                    onChange={view.onToggleAllOverwrite}
                    aria-label={t("Overwrite every item that can replace something on live")}
                    {...agentHandle(
                      { handle: "dashboard-publish-content-overwrite-all" },
                      {
                        role: "field",
                        label: "Check or uncheck every 'Overwrite on live' row at once",
                      }
                    )}
                  />{" "}
                  {t("Overwrite on live")}
                </th>
              )}
            </tr>
          </thead>
          <tbody>
            {view.listedRows.map(renderRow)}
            {view.upToDateLabel && (
              <tr className="publish-content-up-to-date">
                <td colSpan={view.columnCount}>
                  <button
                    type="button"
                    className="link-button"
                    aria-expanded={view.upToDateExpanded}
                    onClick={view.onToggleUpToDate}
                    data-publish-up-to-date-toggle=""
                    {...agentHandle(
                      { handle: "dashboard-publish-content-up-to-date" },
                      {
                        role: "button",
                        label: "Show or hide the items that are already up to date",
                      }
                    )}
                  >
                    {view.upToDateLabel}
                  </button>
                </td>
              </tr>
            )}
            {view.upToDateExpanded && view.upToDateRows.map(renderRow)}
          </tbody>
        </table>
      </div>
      {view.summary && (
        <p className="muted publish-content-summary">
          {view.summary.publishing} {t("to publish")} · {view.summary.unchanged} {t("unchanged")} ·{" "}
          {view.summary.skipped} {t("skipped")}
        </p>
      )}
      {view.overwriteWarning && (
        <p className="notice publish-content-overwrite-warning" role="status">
          {view.overwriteWarning}
        </p>
      )}
      {view.overwriteMismatch && (
        <p className="notice error" role="alert">
          {view.overwriteMismatch}
        </p>
      )}
      {view.overwriteUnavailable && (
        <p className="notice publish-content-overwrite-unavailable">{view.overwriteUnavailable}</p>
      )}
    </>
  ) : null;
}

