interface PermissionRemoveDialogProps {
  pendingPermissionRemove: PendingPermissionRemove | null;
  setPendingPermissionRemove: (target: PendingPermissionRemove | null) => void;
  removingPermissionId: string | null;
  onConfirmRemovePermission: () => Promise<void>;
  t: (key: string) => string;
  locale: string;
}

/** The permission-remove confirm dialog (C1) — same "own the whole sentence per locale" shape as
 *  {@link RoleDeleteDialog}/{@link PolicyDeleteDialog}, `tone="warning"` rather than `destructive`
 *  because the action is reversible (an owner can re-add the permission), matching Users' Disable.
 *  See `use-roles.hooks.ts`'s `pendingPermissionRemove` doc comment for the lockout analysis this
 *  dialog exists to cover. */
function PermissionRemoveDialog({
  pendingPermissionRemove,
  setPendingPermissionRemove,
  removingPermissionId,
  onConfirmRemovePermission,
  t,
  locale,
}: PermissionRemoveDialogProps) {
  const { prefix, suffix } = permissionRemoveBodyParts(locale);
  const pending = pendingPermissionRemove;
  return (
    <ConfirmDialog
      open={pending !== null}
      agentHandle="roles-remove-permission"
      title={t("Remove permission?")}
      body={
        pending ? (
          <p>
            {prefix}
            <code>{pending.row.permission}</code>
            {pending.row.resourceType ? ` (${pending.row.resourceType})` : ""}
            {suffix}
          </p>
        ) : null
      }
      confirmLabel={t("Remove")}
      tone="warning"
      pending={pending !== null && removingPermissionId === pending.row.id}
      onConfirm={onConfirmRemovePermission}
      onCancel={() => setPendingPermissionRemove(null)}
    />
  );
}

/**
 * The "Roles" tab panel — `RolesSection` with the five controller fields it needs, assembled here
 * rather than in `Roles`'s own JSX.
 *
 * The assembly is a straight relocation of what `Roles` used to write inline; nothing about the
 * props changed. It lives in its own component so the two panels can be selected by a flat
 * dispatcher below without `Roles` carrying either branch, which is what the ESLint gate scores.
 * `roles` is non-null by the time this renders — `Roles` returns its loading notice above — so
 * it arrives as its own, already-narrowed prop.
 */
function RolesTab({ controller, roles }: { controller: RolesController; roles: AdminRole[] }) {
  const c = controller;
  return (
    <RolesSection
      roles={roles}
      create={{
        name: c.roleName,
        setName: c.setRoleName,
        saving: c.roleSaving,
        error: c.roleError,
        submit: c.onCreateRole,
      }}
      row={{
        editingId: c.editingRoleId,
        setEditingId: c.setEditingRoleId,
        draftName: c.editingRoleName,
        setDraftName: c.setEditingRoleName,
        startRename: c.startEditRole,
        saveRename: c.onSaveRole,
        savingId: c.rowSavingId,
        requestDelete: c.setPendingRoleDelete,
      }}
      t={c.t}
      locale={c.locale}
    />
  );
}

/** The "Policies" tab panel — `PoliciesSection` with its three controller groups, relocated
 *  verbatim from `Roles`'s own JSX for the same reason {@link RolesTab} documents. */
function PoliciesTab({ controller, policies }: { controller: RolesController; policies: AdminPolicy[] }) {
  const c = controller;
  return (
    <PoliciesSection
      policies={policies}
