/**
 * @file The Access Tokens tab — `Security.tsx`'s one tab and this feature's actual content. One
 * flat, searchable, category-filtered list of every credential this install holds across all eight
 * stores `development/todos.md:1208` names — the 2026-08-16 owner ruling that replaced this page's
 * original two-surface shape (seven Tier 1 providers here, a banner naming six unread Tier 2 stores)
 * with a single list: "from a person's point of view a Cloudinary key and a GitHub token are the
 * same kind of thing — a secret this install holds." See `ADS-memory/reports/design/
 * 2026-08-16-access-tokens-visual-spec.md`'s "OWNER RULING" section for the ruling in full.
 *
 * Tier 1 (`ACCESS_TOKEN_PROVIDERS`, `rules.ts`: the hosting and source-control providers) still gets `[+ Add]` and multiple operator-named rows per provider — the
 * genuinely new capability this page adds (see `Security.tsx`'s own header for why "Create" living
 * here is not a repeat of what Static Site/Source Control already do). Tier 2
 * (`OTHER_CREDENTIAL_STORES`, `rules.ts`, rendered by `OtherCredentialsSection.tsx`) gets Replace/
 * Remove and a deep link to wherever Create actually lives, never a second Create — the tier split
 * survives only as that per-row CAPABILITY difference now, not as two separate surfaces. The
 * "showing 7 of 8" partial-inventory banner this page used to render is deleted; there is nothing
 * left to disclose once every store is read.
 *
 * ## Search
 *
 * Matches a provider's/store's brand label, its purpose subtitle ("Hosting"/"Source control"/
 * "AI"/… — the disambiguation `rules.ts`'s header calls "the two-store GitHub trap" for Tier 1, and
 * the same subtitle Tier 2 rows carry next to their own name), and a saved item's own name. A group
 * renders when EITHER its own info matches the query OR it has at least one matching saved row — so
 * typing "GitHub" surfaces both the GitHub Pages group (provider match) and the GitHub · Source
 * Control group (provider match), each rendering its own real rows, never merged into one card.
 *
 * ## Category filter
 *
 * `All / Source control / Hosting / Media / AI / Ops` (`rules.ts`'s `ACCESS_TOKEN_CATEGORIES`),
 * `All` default, borrowing Settings' wrapped icon-tab-row LOOK without adopting `SettingsDialogShell`
 * itself — that component bundles its own vertical sidebar plus a kicker/title/subtitle header that
 * fights this page's own `.page-header` (`Deployment.tsx`'s header documents the same rejection for
 * the identical reason). `.access-tokens-category-filter` is its own class, not an overload of
 * `.tab-bar` — a filter control, not a tab bar, and `.tab-bar` is shared by five other screens that
 * must not be affected by this page's own styling needs.
 *
 * ## Component split
 *
 * Per-scope ESLint complexity gate (hard 9/9 cyclomatic/cognitive) — same "extract, don't inline"
 * discipline `ProvidersTab.tsx`/`StaticSiteTab.tsx` already use for the identical reason.
 */

export interface AccessTokensTabProps {
  /** DI seams for tests — same convention as every other wired-hook prop in this app. */
  useAccessTokensHook?: typeof useWiredAccessTokens;
  useOtherCredentialsHook?: typeof useWiredOtherCredentials;
  useCopyKeysHook?: typeof useWiredCopyKeys;
  /** Whether the "Copy keys from another project…" entry renders; defaults to
   *  {@link SHOW_COPY_KEYS_ENTRY} (hidden per owner 2026-10-11). */
  showCopyKeysEntry?: boolean;
}

function resolveAccessTokensHook(override: typeof useWiredAccessTokens | undefined): typeof useWiredAccessTokens {
  return override ?? useWiredAccessTokens;
}
function resolveOtherCredentialsHook(override: typeof useWiredOtherCredentials | undefined): typeof useWiredOtherCredentials {
  return override ?? useWiredOtherCredentials;
}

/** Whether the "Copy keys from another project…" entry renders above the list (see its render site). */
const SHOW_COPY_KEYS_ENTRY = false;

export function AccessTokensTab(props: AccessTokensTabProps) {
  useAdminLocale();
  const useAccessTokensHook = resolveAccessTokensHook(props.useAccessTokensHook);
  const useOtherCredentialsHook = resolveOtherCredentialsHook(props.useOtherCredentialsHook);
  const controller = useAccessTokensHook();
  // Tier 2 reads `query`/`category` FROM Tier 1's own controller rather than owning either — one
  // search box, one category filter, across both tiers (this file's own header). See
  // `use-other-credentials.hooks.ts`'s header for why that state isn't duplicated here instead.
  const otherController = useOtherCredentialsHook({ query: controller.query, category: controller.category });
  const useCopyKeysHook = props.useCopyKeysHook ?? useWiredCopyKeys;
  const copyDialog = useCopyKeysHook({ t: controller.t });

  return (
    <div
      className="access-tokens-tab"
      {...agentHandle({ handle: "security-access-tokens" }, {
        role: "region",
        label: "Every access token and other saved credential this install holds, across all eight stores, searchable and filterable by category",
      })}
    >
      {/* Hidden per owner 2026-10-11 ("get rid of this button for now"). The dialog, hook and route
          stay wired, and the chat's copy-keys card is unaffected — flip `SHOW_COPY_KEYS_ENTRY` to
          restore the entry. */}
      {(props.showCopyKeysEntry ?? SHOW_COPY_KEYS_ENTRY) ? (
        <>
          <button type="button" className="btn-secondary" onClick={copyDialog.show}>{controller.t("Copy keys from another project…")}</button>
          <CopyKeysDialog dialog={copyDialog} t={controller.t} />
        </>
      ) : null}
      <AccessTokensBody controller={controller} otherController={otherController} />
    </div>
  );
}

/** Loading/error/populated split — pulled out of {@link AccessTokensTab} purely for the complexity
 *  gate, same reasoning `SourceControlCredentialsList` documents in `ProvidersTab.tsx`. Waits for
 *  BOTH tiers' first load: rendering Tier 1's list before Tier 2 has resolved would put the category
 *  filter and the row list on screen a beat before Tier 2's own rows could ever appear under it,
 *  which reads as those rows being silently absent rather than still loading.
 *
 * `useMergedSecretsOrder` (a hook) is called unconditionally, ahead of every early return below —
 * Rules of Hooks — even though its result is only rendered once the loading/error gates pass; it
 * tolerates either controller's `groups` still being `undefined` internally (`AccessTokensTab.hooks.tsx`'s
 * own doc), so calling it early costs nothing. */
function AccessTokensBody({ controller, otherController }: { controller: AccessTokensController; otherController: OtherCredentialsController }) {
  const addCustomDialogRef = useRef<HTMLDialogElement>(null);
  const merged = useMergedSecretsOrder(controller, otherController, controller.query);
  if (controller.loadError) {
    return (
      <p className="notice error" role="status" {...agentHandle({ handle: "security-access-tokens-load-error" }, { role: "status", label: "Shows the error when saved access tokens could not be loaded" })}>
        {controller.loadError}
      </p>
    );
  }
  if (otherController.loadError) {
    return (
      <p className="notice error" role="status" {...agentHandle({ handle: "security-other-credentials-load-error" }, { role: "status", label: "Shows the error when other saved credentials could not be loaded" })}>
        {otherController.loadError}
      </p>
    );
  }
  if (controller.groups === undefined || otherController.groups === undefined) {
    return <p className="access-tokens-loading">{controller.t("Loading access tokens…")}</p>;
  }
  return (
    <>
      <AccessTokensSearch controller={controller} otherController={otherController} />
      <AccessTokensCategoryFilter controller={controller} onAddCustomProvider={() => addCustomDialogRef.current?.showModal()} />
      <HostingPluginsHint controller={controller} />
      <div className="access-tokens-tier">
        {merged.length === 0 && !controller.query ? <div className="empty-state"><p>{controller.t("Not connected")}</p></div> : null}
        {merged.map((entry) =>
          entry.kind === "provider" ? (
            <ProviderGroup key={entry.key} group={entry.group} controller={controller} />
          ) : (
            <OtherCredentialEntry key={entry.key} store={entry.store} row={entry.row} controller={otherController} />
          )
        )}
      </div>
      <AddCustomCredentialDialog ref={addCustomDialogRef} controller={controller} t={controller.t} />
    </>
  );
}

/** The hosting filter can be empty while source-control groups still exist. */
function HostingPluginsHint({ controller }: { controller: AccessTokensController }) {
  if (controller.query || !["all", "hosting"].includes(controller.category) || controller.groups?.some((group) => group.info.category === "hosting")) return null;
  return <div className="empty-state">
    <p>{controller.t("Enable a hosting plugin to manage its access tokens.")}</p>
    <a href={adminHref("/addons/agent-plugins")}>{controller.t("Plugins")}</a>
  </div>;
}

/** The `All / Source control / Hosting / Media / AI / Ops` filter row, PLUS the "Add custom
 *  provider" button — see this file's header for why the filter row borrows Settings' wrapped
 *  icon-tab-row LOOK rather than the component itself. The button is a deliberately SEPARATE
 *  control after the mapped category pills (`margin-left: auto` in `access-tokens.css` pushes it to
 *  the far right of the row), not a pill itself — it opens a create form, it does not filter
 *  anything, so it must never read as an eighth category to a search/scan of this row. Pulled out
 *  of {@link AccessTokensBody} for the complexity gate; its own branching is a single `.map()` plus
 *  one static button, so this split is about readability/reuse rather than a budget this one
 *  function would otherwise exceed. */
function AccessTokensCategoryFilter({ controller, onAddCustomProvider }: { controller: AccessTokensController; onAddCustomProvider: () => void }) {
  const translate = controller.t;
  // Reuses `TabBar.hooks.tsx`'s WAI-ARIA tabs keyboard helpers rather than reimplementing them —
  // `ACCESS_TOKEN_CATEGORIES`'s `{ id, label }` shape structurally satisfies `TabBarTab`, and none
  // of these categories are ever disabled. `[role="tab"]` scoping already skips the non-tab
  // "+ Add custom provider" button below (this file's own header on why that button stays out of
  // the tablist's tab order).
  const { onKeyDown } = useTabBarKeyboard({ tabs: ACCESS_TOKEN_CATEGORIES, activeId: controller.category, onChange: (id) => controller.setCategory(id as AccessTokenCategoryId) });
  return (
    <div
      className="access-tokens-category-filter"
      role="tablist"
      aria-label={translate("Filter by category")}
      onKeyDown={onKeyDown}
      {...agentHandle({ handle: "security-access-tokens-category-filter" }, { role: "region", label: "Filter the credential list by category" })}
    >
      {ACCESS_TOKEN_CATEGORIES.map((c) => (
        <button
          key={c.id}
          type="button"
          role="tab"
          className="access-tokens-category-filter-item"
          aria-selected={controller.category === c.id}
          tabIndex={resolveTabBarTabIndex({ tabs: ACCESS_TOKEN_CATEGORIES, activeId: controller.category, tab: c })}
          onClick={() => controller.setCategory(c.id as AccessTokenCategoryId)}
          {...agentHandle({ handle: `security-access-tokens-category-${c.id}` }, { role: "button", label: `Filter the credential list to ${c.label}` })}
        >
          {translate(c.label)}
        </button>
      ))}
      <button
        type="button"
        className="access-tokens-add-custom-button"
        onClick={onAddCustomProvider}
        {...agentHandle({ handle: "security-access-tokens-add-custom-provider" }, { role: "button", label: "Add a custom provider not in the built-in list" })}
      >
        {translate("+ Add custom provider")}
      </button>
    </div>
  );
}

/** The search box and its own match-count line — counts are the SUM of both tiers'
 *  `totalCount`/`matchCount` (this file's header on why the combined count stays a GLOBAL fact,
 *  unaffected by the category filter below it). "token(s)" stays the noun even though the count now
 *  spans Tier 2's keys/credentials too — the existing e2e suite pins the exact string
 *  (`development/e2e/access-tokens.spec.ts`'s `/^0 tokens saved$/`), and nothing in this pass asked
 *  for new copy here; a person calling an API key a "token" loosely is the same shorthand this
 *  page's own tab name already uses for the whole install. The line itself is `rules.ts`'s
 *  `accessTokensCountText` — a whole translated sentence per plural form, not fragments glued in
 *  English word order (see that function's own doc for why). */
function AccessTokensSearch({ controller, otherController }: { controller: AccessTokensController; otherController: OtherCredentialsController }) {
  const translate = controller.t;
  const totalCount = controller.totalCount + otherController.totalCount;
  const matchCount = controller.matchCount + otherController.matchCount;
  const countText = accessTokensCountText(totalCount, matchCount, controller.query, translate);
  return (
    <div className="access-tokens-search">
      <label className="visually-hidden" htmlFor="access-tokens-search">
        {translate("Search access tokens")}
      </label>
      <span className="access-tokens-search-icon">
        <SearchIcon />
      </span>
      <input
        id="access-tokens-search"
        className="access-tokens-search-input"
        type="search"
        autoComplete="off"
        value={controller.query}
        onChange={(e) => controller.setQuery(e.target.value)}
        placeholder={translate("Search by provider, name, or purpose")}
        {...agentHandle({ handle: "security-access-tokens-search" }, { role: "field", label: "Search saved access tokens by provider, name, or purpose" })}
      />
      <p className="access-tokens-search-count" role="status" aria-live="polite">
        {countText}
      </p>
    </div>
  );
}

function ProviderGroup({ group, controller }: { group: AccessTokenProviderGroupState; controller: AccessTokensController }) {
  const ref: AccessTokenProviderRef = { kind: group.info.kind, providerId: group.info.providerId };
  const hasRows = group.rows.length > 0;
  return (
    <section
      className="access-tokens-provider-group"
      {...agentHandle({ handle: `security-access-tokens-group-${group.info.kind}-${agentHandleSegment({ value: group.info.providerId })}` }, {
        role: "region",
        label: providerGroupHandleLabel(group.info, group.rows.length),
      })}
    >
      <h3 className="access-tokens-provider-heading">
        <span translate="no">{group.info.label}</span>
        <span className="access-tokens-provider-purpose"> · {providerGroupSubtitleKeys(group.info).map(controller.t).join(" · ")}</span>
      </h3>
      {group.info.unlisted ? <p className="field-hint">{controller.t("Its plugin is off or missing. You can still remove saved tokens.")}</p> : null}
      {group.rows.map((row) => (
        <TokenRow key={row.row.id} state={row} info={group.info} controller={controller} groupRowCount={group.rows.length} t={controller.t} />
      ))}
      {!hasRows && !group.addForm.visible ? <NotConnectedRow ref={ref} label={group.info.label} onConnect={() => controller.openAddForm(ref)} t={controller.t} /> : null}
      {group.addForm.visible ? <AddTokenForm info={group.info} state={group.addForm} controller={controller} t={controller.t} /> : null}
      {/* No `[+ Add another]` for a `"custom"` group — it has no shared provider identity a second
          saved row could join; a second custom credential is a wholly new one, created through the
          standalone "Add custom provider" dialog, not this per-provider affordance. */}
      {/* Nor for an unlisted provider (plugin off or missing): it takes no new token. */}
      {hasRows && !group.addForm.visible && group.info.kind !== "custom" && !group.info.unlisted ? <AddAnotherButton ref={ref} label={group.info.label} controller={controller} t={controller.t} /> : null}
    </section>
  );
}

function AddAnotherButton({ ref, label, controller, t: translate }: { ref: AccessTokenProviderRef; label: string; controller: AccessTokensController; t: Translate }) {
  return (
    <button
      type="button"
      className="link-button access-tokens-add-another"
      onClick={() => controller.openAddForm(ref)}
      {...agentHandle({ handle: `security-access-tokens-add-${ref.kind}-${agentHandleSegment({ value: ref.providerId })}` }, { role: "button", label: `Add another ${label} token` })}
    >
      {translate("Add another")} <span translate="no">{label}</span> {translate("token")}
    </button>
  );
}

function NotConnectedRow({ ref, label, onConnect, t: translate }: { ref: AccessTokenProviderRef; label: string; onConnect: () => void; t: Translate }) {
  return (
    <div className="access-tokens-row">
      <div className="access-tokens-row-summary">
        <span className="access-tokens-row-marker" aria-hidden="true" />
        <span className="access-tokens-row-name">{translate("Not connected")}</span>
        <button
          type="button"
          className="access-tokens-row-summary-expand"
          onClick={onConnect}
          // `aria-label`, not just the visible "Connect" text: every not-yet-connected provider on
          // this page renders this exact same bare word, so with two or more not-connected rows on
          // screen at once (the common case — most installs have not connected every one of the
          // seven providers), `getByRole("button", { name: "Connect" })` — or an agent resolving by
          // accessible name — cannot tell GitHub's row from GitLab's. `label` here is already the
          // provider's own display label (e.g. "GitHub Pages"), so this starts with the exact
          // visible word (WCAG 2.5.3 Label in Name).
          aria-label={`${translate("Connect")} ${label}`}
          // Handle built from `ref.kind`/`ref.providerId` (already lowercase, hyphen-safe — every
          // `AccessTokenProviderRef` in this app comes straight off `ACCESS_TOKEN_PROVIDERS`), never
          // from `label` — `agentHandle()` rejects any handle that isn't lowercase words joined by
          // single hyphens, and a proper-noun label like "GitHub Pages" (capitals, a space) throws
          // at render time. Caught live: an uncaught throw here unmounted this whole row with no
          // error boundary above it, which is worse than a defensive check — a crash, not a fallback.
          {...agentHandle({ handle: `security-access-tokens-connect-${ref.kind}-${agentHandleSegment({ value: ref.providerId })}` }, { role: "button", label: `Connect ${label}` })}
        >
          {translate("Connect")}
          <DisclosureChevronIcon />
        </button>
      </div>
    </div>
  );
}

function TokenRow({
  state,
  info,
  controller,
  groupRowCount,
  t: translate,
}: {
  state: AccessTokenExistingRowState;
  info: AccessTokenProviderInfo;
  controller: AccessTokensController;
  groupRowCount: number;
  t: Translate;
}) {
  const dialogRef = useRef<HTMLDialogElement>(null);
  const showDefaultUi = groupRowCount >= 2;
  return (
    <details
      className="access-tokens-row access-tokens-row-done"
      {...agentHandle({ handle: `security-access-tokens-row-${state.row.kind}-${agentHandleSegment({ value: state.row.providerId })}-${agentHandleSegment({ value: state.row.id })}` }, {
        role: "region",
        label: tokenRowHandleLabel(state.name, info.label),
      })}
    >
      <summary className="access-tokens-row-summary">
        <span className="access-tokens-row-marker access-tokens-row-marker-done" aria-hidden="true">
          <ConnectedMarkIcon />
        </span>
        <span className="access-tokens-row-name">{state.name}</span>
        <CustomKeyUsage state={state} controller={controller} />
        <TokenRowDefaultIndicator state={state} showDefaultUi={showDefaultUi} controller={controller} t={translate} />
        <span className="access-tokens-row-summary-meta">
          {state.row.worksFor?.length ? <span>{translate("Works for")}: {state.row.worksFor.join(", ")} · </span> : null}
          {translate("saved")} {formatTimestamp({ iso: state.row.updatedAt }, { timeZone: "local" })} <CredentialHint hint={state.row.tokenHint} />
        </span>
        <span className="access-tokens-row-summary-expand">
          {translate(state.row.scope === "project" && !state.row.usedByThisSite ? "Details" : "Replace token")}
          <DisclosureChevronIcon />
        </span>
      </summary>
      {state.row.scope === "project" && !state.row.usedByThisSite ? (
        <div className="access-tokens-row-actions">
          <p className="field-hint">{translate("Use on this site to replace this key.")}</p>
          <button type="button" className="btn-danger" onClick={() => dialogRef.current?.showModal()} aria-label={`${translate("Remove from Tovu")} — ${state.name}`}>
            {translate("Remove from Tovu")}
          </button>
        </div>
      ) : <ExistingTokenFields state={state} controller={controller} info={info} onRemoveClick={() => dialogRef.current?.showModal()} t={translate} />}
      <RemoveConfirmDialog ref={dialogRef} row={state.row} info={info} controller={controller} isLastForProvider={groupRowCount === 1} t={translate} />
    </details>
  );
}

/** Storage and attachment facts for custom keys. Summary actions preserve the disclosure state,
 * matching the existing default-token action; the controller owns all I/O and failures.
 */
function CustomKeyUsage({ state, controller }: { state: AccessTokenExistingRowState; controller: AccessTokensController }) {
  if (state.row.kind !== "custom") return null;
  const translate = controller.t;
  if (state.row.scope !== "project") return <span className="status status-neutral">{translate("This site only")}</span>;
  const sites = state.row.usedBy ?? [];
  const action = state.row.usedByThisSite ? "Stop using on this site" : "Use on this site";
  return <>
    <span className="status status-neutral">
      {sites.length ? <>{translate("Project — used by:")} <span translate="no">{sites.join(", ")}</span></> : translate("Project — not used by any site yet")}
    </span>
    <button type="button" className="link-button" disabled={controller.customKeyBusy[state.row.id]?.saving}
      aria-label={`${translate(action)} — ${state.name}`}
      onClick={event => {
        event.preventDefault();
        event.stopPropagation();
        void controller.setCustomKeyUse({ row: state.row, use: !state.row.usedByThisSite });
      }}
      {...agentHandle({ handle: `security-access-tokens-use-${agentHandleSegment({ value: state.row.id })}` }, { role: "button", label: `${action} — ${state.name}` })}
    >{translate(action)}</button>
    {controller.customKeyBusy[state.row.id]?.error ? <span className="save-error" role="alert">{controller.customKeyBusy[state.row.id].error}</span> : null}
  </>;
}

/** The `isDefault` indicator + `Make default` link — only shown once a provider has 2+ saved
 *  tokens (`rules.ts`'s own doc on why a lone row has nothing to choose between). Split out purely
 *  for the complexity gate.
 *
 * This button lives inside `TokenRow`'s own `<summary>`, a descendant of the native disclosure
 * toggle, so its click would otherwise ALSO open/close the enclosing `<details>` (the browser runs
 * `<summary>`'s toggle as the click event's default action regardless of which descendant was
 * actually clicked, unless that default action is cancelled) — `preventDefault`/`stopPropagation`
 * in the handler below is what keeps a "Make default" click from also expanding the row, same
 * pattern as `deployment/StaticSiteTab.tsx`'s `CredentialVerifyAction`. */
function TokenRowDefaultIndicator({ state, showDefaultUi, controller, t: translate }: { state: AccessTokenExistingRowState; showDefaultUi: boolean; controller: AccessTokensController; t: Translate }) {
  if (!showDefaultUi) return null;
  if (state.row.isDefault) return <span className="status status-neutral">{translate("Default")}</span>;
  return (
    <button
      type="button"
      className="link-button"
      onClick={(e) => {
        e.preventDefault();
        e.stopPropagation();
        void controller.makeDefault(state.row);
      }}
      // `aria-label`, not just the visible "Make default" text: this button renders once per
      // non-default row in a provider group that has 2+ saved tokens (the ONLY case it renders at
      // all — this function's own guard above), so with 3+ saved tokens for one provider, multiple
      // identically-labeled "Make default" buttons are on screen simultaneously. `state.name` is
      // this row's own operator-chosen display name, already unique enough to pick one out.
      aria-label={`${translate("Make default")} — ${state.name}`}
      {...agentHandle({ handle: `security-access-tokens-default-${agentHandleSegment({ value: state.row.id })}` }, { role: "button", label: `Make ${state.name} the default token` })}
    >
      {translate("Make default")}
    </button>
  );
}

/** Shared input markup for BOTH the "add a new token" form and an existing row's "replace" fields —
 *  same split `PublishCredentialFields`/`SourceControlCredentialFields` use for the identical
 *  connected/not-connected duality. Every hint renders below its input as `.field-hint`, never as
 *  placeholder text — same "placeholder-as-label reads as a saved value" defect this app has already
 *  fixed twice (`ProvidersTab.tsx`'s own header). */
function TokenInputFields({
  idPrefix,
  info,
  name,
  token,
  values,
  username,
  onNameChange,
  onTokenChange,
  onFieldChange,
  onUsernameChange,
  connected,
  t: translate,
}: {
  idPrefix: string;
  info: AccessTokenProviderInfo;
  name: string;
  token: string;
  values: Readonly<Record<string, string>>;
  username: string;
  onNameChange: (value: string) => void;
  onTokenChange: (value: string) => void;
  onFieldChange: (name: string, value: string) => void;
  onUsernameChange: (value: string) => void;
  connected: boolean;
  t: Translate;
}) {
  // Only a custom row shows Username, always optional (`rules.ts`'s `AccessTokenProviderInfo` doc).
  const needsUsername = info.username !== undefined;
  const extraFields = extraFieldsAroundToken(info);
  return (
    <div className="access-tokens-row-fields">
      <div className="field">
        <label className="field-label" htmlFor={`${idPrefix}-name`}>
          {translate("Name")}
        </label>
        <input
          id={`${idPrefix}-name`}
          type="text"
          value={name}
          onChange={(e) => onNameChange(e.target.value)}
          {...agentHandle({ handle: `${idPrefix}-name` }, { role: "field", label: "This token's display name" })}
        />
        <p className="field-hint">{translate("A short label so you can tell this token apart from others for the same provider.")}</p>
      </div>
      <ExtraFieldInputs fields={extraFields.before} idPrefix={idPrefix} values={values} onFieldChange={onFieldChange} t={translate} />
      <div className="field">
        <label className="field-label" htmlFor={`${idPrefix}-token`}>
          {info.tokenLabel ?? translate("Access token")}
        </label>
        {/* `autoComplete="new-password"`, NOT `"off"` — Chrome deliberately ignores `off` on
            credential-shaped fields (a long-standing intentional decision, not a bug), and `off`
            here is what let the reported autofill through. `new-password` is the documented signal
            for "this field is not a saved-login field", which suppresses both the saved-credential
            dropdown and the silent fill.

            This input is why the SEARCH BOX at the top of the page was being filled with "admin":
            `TokenRow`'s `<details>` renders `ExistingTokenFields` unconditionally, so every saved
            token leaves a live password input in the DOM even while its row is collapsed. Chrome's
            formless credential heuristic groups a page's text-like fields with any password field
            by DOM proximity — no `<form>` required, and there is none in this feature — so the page
            read as a login surface and the first text-like field (the search box) got the site's
            saved username. Fixing the search box's own attribute could not work: the search box was
            the symptom, these fields are the trigger. */}
        <SecretInput
          label={info.tokenLabel ?? translate("Access token")}
          id={`${idPrefix}-token`}
          autoComplete="new-password"
          value={token}
          onChange={(e) => onTokenChange(e.target.value)}
          {...agentHandle({ handle: `${idPrefix}-token` }, { role: "field", label: "This token's secret value — stored encrypted, never shown again once saved" })}
        />
        <p className="field-hint">
          {connected ? translate("Leave blank to keep the current token.") : translate("Stored encrypted on the server. Once saved, Tovu never displays it again.")}
        </p>
        {info.scopeGuidanceKey !== "" || info.tokenPageUrl !== "" ? (
          <details className="access-tokens-scope-guidance">
            <summary className="access-tokens-scope-guidance-summary">
              {translate("Which token do I need?")}
              <DisclosureChevronIcon size={10} />
            </summary>
            <p className="field-hint">
              {info.scopeGuidanceKey !== "" ? <>{translate(info.scopeGuidanceKey)} </> : null}
              {info.tokenPageUrl !== "" ? (
                <a
                  href={info.tokenPageUrl}
                  target="_blank"
                  rel="noreferrer"
                  {...agentHandle({ handle: `${idPrefix}-token-page` }, { role: "link", label: `Open ${info.label}'s own page for creating a personal access token` })}
                >
                  {translate("Create a token")}
                </a>
              ) : null}
            </p>
          </details>
        ) : null}
      </div>
      <ExtraFieldInputs fields={extraFields.after} idPrefix={idPrefix} values={values} onFieldChange={onFieldChange} t={translate} />
      {needsUsername ? (
        <div className="field">
          <label className="field-label" htmlFor={`${idPrefix}-username`}>
            {translate("Username")}
          </label>
          <input
            id={`${idPrefix}-username`}
            type="text"
            value={username}
            onChange={(e) => onUsernameChange(e.target.value)}
            {...agentHandle({ handle: `${idPrefix}-username` }, { role: "field", label: "The username this token authenticates against, when this provider needs one" })}
          />
          <p className="field-hint">{translate("Optional — only needed if this provider authenticates a token against a username.")}</p>
        </div>
      ) : null}
    </div>
  );
}

/** A run of {@link ExtraFieldInput}s, in the order given. */
function ExtraFieldInputs({
  fields,
  idPrefix,
  values,
  onFieldChange,
  t: translate,
}: {
  fields: readonly AdminPublishTargetField[];
  idPrefix: string;
  values: Readonly<Record<string, string>>;
  onFieldChange: (name: string, value: string) => void;
  t: Translate;
}) {
  return (
    <>
      {fields.map((field) => (
        <ExtraFieldInput
          key={field.name}
          id={`${idPrefix}-${accessTokenExtraFieldIdSuffix(field.name)}`}
          field={field}
          value={values[field.name] ?? ""}
          onChange={(value) => onFieldChange(field.name, value)}
          t={translate}
        />
      ))}
    </>
  );
}

/** One of a provider's descriptor fields (a host's account ID, bucket, region…): the descriptor's
 *  label (a host term, verbatim) plus the translated "(optional)" suffix, and its help below. */
function ExtraFieldInput({
  id,
  field,
  value,
  onChange,
  t: translate,
}: {
  id: string;
  field: AdminPublishTargetField;
  value: string;
  onChange: (value: string) => void;
  t: Translate;
}) {
  return (
    <div className="field">
      <label className="field-label" htmlFor={id}>
        {field.label}
        {field.required ? null : ` ${translate("(optional)")}`}
      </label>
      <SecretInput
        label={field.label}
        secret={field.secret === true}
        id={id}
        autoComplete="new-password"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        {...agentHandle({ handle: id }, { role: "field", label: `This provider's ${field.label}` })}
      />
      {fieldHelpText(field) ? <p className="field-hint">{fieldHelpText(field)}</p> : null}
    </div>
  );
}

/** Reuse Jini's multiple-choice field, retaining disabled-plugin ids as removable raw chips.
 * Rendering costs O(options + selected) space and time; selection stays in the controller.
 */
function WorksForField({ value = [], options = [], onChange, t }: {
  value: string[];
  options: { value: string; label: string }[];
  onChange: (value: string[]) => void;
  t: Translate;
}, _options = {}) {
  const choices = new Map(options.map(option => [option.value, option]));
  for (const id of value) if (!choices.has(id)) choices.set(id, { value: id, label: id });
  return <div className="field" role="group" aria-label={t("Works for")}>
    <OnboardingChipField multiple label={t("Works for")} options={[...choices.values()]} value={value} onChange={onChange} />
  </div>;
}

function ExistingTokenFields({
  state,
  controller,
  info,
  onRemoveClick,
  t: translate,
}: {
  state: AccessTokenExistingRowState;
  controller: AccessTokensController;
  info: AccessTokenProviderInfo;
  onRemoveClick: () => void;
  t: Translate;
}) {
  const readyToSave = state.readyToSave;
  return (
    <>
      <TokenInputFields
        idPrefix={`security-existing-${agentHandleSegment({ value: state.row.id })}`}
        info={info}
        name={state.name}
        token={state.token}
        values={state.values}
        username={state.username}
        onNameChange={(v) => controller.setExistingField(state.row.id, { name: v })}
        onTokenChange={(v) => controller.setExistingField(state.row.id, { token: v })}
        onFieldChange={(name, v) => controller.setExistingField(state.row.id, { values: { ...state.values, [name]: v } })}
        onUsernameChange={(v) => controller.setExistingField(state.row.id, { username: v })}
        connected
        t={translate}
      />
      {info.kind !== "source-control" ? <WorksForField value={state.worksFor} options={controller.worksForOptions} onChange={worksFor => controller.setExistingField(state.row.id, { worksFor })} t={translate} /> : null}
      <SharedKeyReplaceNote row={state.row} t={translate} />
      <div className="access-tokens-row-actions">
        <button
          type="button"
          disabled={!readyToSave || state.saving}
          onClick={() => void controller.replaceToken(state.row)}
          // `aria-label`, not just the visible "Save"/"Saving…" text: a provider group can hold
          // several saved tokens (`AddAnotherButton` above), each opened via its own `<details>`
          // (unlike `RowMenu`'s exclusive-open items, more than one can be expanded at once) — with
          // two rows open, both show an identical bare "Save" button. `state.name` is this row's own
          // display name, already visible in its `<summary>` heading, so it disambiguates the same
          // way a sighted reader already can. Mirrors the visible text's own saving/idle split so the
          // accessible name never says "Save" while the button reads "Saving…" (WCAG 2.5.3).
          aria-label={`${state.saving ? translate("Saving…") : translate("Save")} — ${state.name}`}
          {...agentHandle({ handle: `security-access-tokens-save-${agentHandleSegment({ value: state.row.id })}` }, { role: "button", label: `Save this ${info.label} token` })}
        >
          {state.saving ? translate("Saving…") : translate("Save")}
        </button>
        <button
          type="button"
          className="btn-danger"
          onClick={onRemoveClick}
          // Same multi-row-open ambiguity as Save above, on this page's one destructive action —
          // see `rules.ts`'s `restoreButtonAccessibleName` (`recovery/rules.ts`) for the identical
          // reasoning applied to a different screen's own always-visible destructive control.
          aria-label={`${translate("Remove from Tovu")} — ${state.name}`}
          {...agentHandle({ handle: `security-access-tokens-remove-${agentHandleSegment({ value: state.row.id })}` }, { role: "button", label: `Open the confirm dialog to remove this ${info.label} token from Tovu` })}
        >
          {translate("Remove from Tovu")}
        </button>
        {state.error ? (
          <p className="save-error" role="alert">
            {state.error}
          </p>
        ) : null}
      </div>
    </>
  );
}

/** Warns, before Save, that a shared project key's other sites switch to the new token too. */
function SharedKeyReplaceNote({ row, t: translate }: { row: AccessTokenExistingRowState["row"]; t: Translate }) {
  const warning = row.scope === "project" ? sharedKeyReplaceWarning({ usedBy: row.usedBy, usedByThisSite: row.usedByThisSite, t: translate }) : null;
  return warning ? <p className="save-warning">{warning}</p> : null;
}

function AddTokenForm({ info, state, controller, t: translate }: { info: AccessTokenProviderInfo; state: AccessTokenAddFormState; controller: AccessTokensController; t: Translate }) {
  const ref: AccessTokenProviderRef = { kind: info.kind, providerId: info.providerId };
  const readyToSave = state.readyToSave;
  return (
    <div className="access-tokens-row">
      <TokenInputFields
        idPrefix={`security-add-${info.kind}-${agentHandleSegment({ value: info.providerId })}`}
        info={info}
        name={state.name}
        token={state.token}
        values={state.values}
        username={state.username}
        onNameChange={(v) => controller.setAddField(ref, { name: v })}
        onTokenChange={(v) => controller.setAddField(ref, { token: v })}
        onFieldChange={(name, v) => controller.setAddField(ref, { values: { ...state.values, [name]: v } })}
        onUsernameChange={(v) => controller.setAddField(ref, { username: v })}
        connected={false}
        t={translate}
      />
      {info.kind === "publish" ? <WorksForField value={state.worksFor} options={controller.worksForOptions} onChange={worksFor => controller.setAddField(ref, { worksFor })} t={translate} /> : null}
      <div className="access-tokens-row-actions">
        <button
          type="button"
          disabled={!readyToSave || state.saving}
          onClick={() => void controller.createToken(ref)}
          // `aria-label`: more than one provider's "Add" form can be open at once (each provider
          // group owns its own independent `addForm.visible`), and every one of them renders this
          // same bare "Save"/"Saving…" text — `info.label` is the one thing that tells them apart
          // here (there is no operator-chosen name yet to use, unlike `ExistingTokenFields`' own
          // fix above, since this token has not been saved).
          aria-label={`${state.saving ? translate("Saving…") : translate("Save")} — ${info.label}`}
          {...agentHandle({ handle: `security-access-tokens-create-${info.kind}-${agentHandleSegment({ value: info.providerId })}` }, { role: "button", label: `Save this ${info.label} token` })}
        >
          {state.saving ? translate("Saving…") : translate("Save")}
        </button>
        <button
          type="button"
          className="link-button"
          onClick={() => controller.closeAddForm(ref)}
          aria-label={`${translate("Cancel")} adding this ${info.label} token`}
          {...agentHandle({ handle: `security-access-tokens-cancel-${info.kind}-${agentHandleSegment({ value: info.providerId })}` }, { role: "button", label: "Close this add-token form without saving" })}
        >
          {translate("Cancel")}
        </button>
        {state.error ? (
          <p className="save-error" role="alert">
            {state.error}
          </p>
        ) : null}
      </div>
    </div>
  );
}

/**
 * Native `<dialog>` confirm — same `.confirm-dialog` foundation `styles.css:2880` documents (`[open]`-
 * scoped `display`, never a bare-class rule — that comment's own header records the live bug an
 * unscoped rule caused). "Remove from Tovu," never "Revoke" — `rules.ts`'s own header, this page's
 * one load-bearing copy constraint: deleting Tovu's row does not revoke the credential at the
 * provider, and this dialog is the one place that fact has to be stated in words, not implied by a
 * button label.
 *
 * Confirm button carries no `agentHandle` — destructive, same boundary
 * `StaticSiteTab.tsx`'s own credential-entry fields already draw (no agent read/act surface over a
 * credential action); the row's own SUMMARY stays tagged (`TokenRow`'s `agentHandle`), only this
 * dialog's destructive action does not.
 */
const RemoveConfirmDialog = forwardRef<HTMLDialogElement, { row: AccessTokenRow; info: AccessTokenProviderInfo; controller: AccessTokensController; isLastForProvider: boolean; t: Translate }>(
  function RemoveConfirmDialog({ row, info, controller, isLastForProvider, t: translate }, ref) {
    const locale = useAdminLocale();
    const { close, confirm } = useRemoveConfirmDialog(ref, row, controller);
    // `aria-labelledby`, not left implicit: a native `<dialog>` has no accessible name of its own
    // from an `<h2>` sitting inside it — that link has to be stated, the same way the shared
    // `ConfirmDialog` (`@jini-ai/admin/react`) already does via its own `titleId`. Without it, every
    // one of this page's per-row remove dialogs reads to an accessibility tree as an unnamed
    // "dialog", indistinguishable from any other open dialog on the page. Scoped by `row.id` (not a
    // static id) because one `RemoveConfirmDialog` is mounted per token row, all in the DOM at once.
    const titleId = `security-access-tokens-remove-title-${agentHandleSegment({ value: row.id })}`;
    return (
      <dialog ref={ref} className="confirm-dialog" aria-labelledby={titleId}>
        <h2 id={titleId}>{removeDialogTitle(locale, row.name)}</h2>
        <p className="confirm-dialog-body">{removeDialogBody(locale, info.label, info.vendorLabel)}</p>
        {info.tokenPageUrl === "" ? null : <p>
          {/* `info.vendorLabel`, NOT `info.label` — this line says WHERE to revoke, and "GitHub
              Pages"/"Cloudflare Pages" are destinations with no revoke console of their own. See
              `rules.ts`'s `AccessTokenProviderInfo.vendorLabel` doc for the full reasoning; every
              other `info.label` on this page still names the destination on purpose. */}
          <a
            href={info.tokenPageUrl}
            target="_blank"
            rel="noreferrer"
            {...agentHandle({ handle: `security-access-tokens-revoke-page-${agentHandleSegment({ value: row.id })}` }, { role: "link", label: `Open ${info.vendorLabel} to revoke this token at the source` })}
          >
            {translate("Revoke it on")} <span translate="no">{info.vendorLabel}</span> ↗
          </a>
        </p>}
        {isLastForProvider ? <p className="confirm-dialog-body">{removeDialogLastRowNote(locale, info.label)}</p> : null}
        <div className="confirm-dialog-actions">
          <button
            type="button"
            onClick={close}
            {...agentHandle({ handle: `security-access-tokens-remove-cancel-${agentHandleSegment({ value: row.id })}` }, { role: "button", label: "Close this dialog without removing the token" })}
          >
            {translate("Cancel")}
          </button>
          <button type="button" className="btn-danger" onClick={confirm}>
            {translate("Remove from Tovu")}
          </button>
        </div>
      </dialog>
    );
  }
);

/** The red-star marker on a required field's label — Name/API base URL/Access token in the form
 *  below (Username stays unmarked, Category always carries a value so it's never actually blank).
 *  `aria-label`, not `aria-hidden`, so a screen reader announces "required" — same convention
 *  `Authentication.tsx`'s own `source-config-field-required` marker uses. */
function RequiredFieldMarker() {
  return (
    <span className="access-tokens-field-required" aria-label="required">
      {" "}
      *
    </span>
  );
}

/** The "Additional hosts" field — split out of {@link AddCustomCredentialDialog} purely so that
 *  function's own complexity stays under this repo's gate; the inline-error branch below adds one
 *  more decision point to whichever function renders it, and `AddCustomCredentialDialog` already
 *  carries a full field set's worth. */
function AdditionalHostsField({ value, onChange, translate }: { value: string; onChange: (value: string) => void; translate: Translate }) {
  const invalid = invalidAdditionalHostsEntries(value);
  return (
    <div className="field">
      <label className="field-label" htmlFor="security-add-custom-additional-hosts">
        {translate("Additional hosts")}
      </label>
      <textarea
        id="security-add-custom-additional-hosts"
        rows={2}
        value={value}
        placeholder="https://secondary-api.example.test"
        onChange={(e) => onChange(e.target.value)}
        {...agentHandle({ handle: "security-access-tokens-add-custom-additional-hosts" }, {
          role: "field",
          label: "Extra API hosts this same credential is also allowed to call, beyond the base URL",
        })}
      />
      <p className="field-hint">
        {translate("Optional — some providers use more than one API host for the same account (e.g. api.example.test and secondary-api.example.test). One per line, or comma-separated.")}
      </p>
      {invalid.length > 0 ? <p className="field-error">{translate("Each additional host must be a valid http:// or https:// URL.")}</p> : null}
    </div>
  );
}

/** Explicit storage choice; hosts without a project store can truthfully offer site-only saving. */
function CustomKeyStorageChoice({ controller }: { controller: AccessTokensController }) {
  const translate = controller.t;
  if (!controller.projectKeysAvailable) return <p className="field-hint">{translate("This site only")}</p>;
  return (
    <fieldset className="access-tokens-key-scope" disabled={controller.customAddForm.saving}>
      <legend className="field-label">{translate("Save key to")}</legend>
      <label><input type="radio" name="custom-key-scope" value="project" checked={(controller.customAddForm.scope ?? "project") === "project"}
        onChange={() => controller.setCustomAddField({ scope: "project" })} /> {translate("Save to project and use on this site")}</label>
      <label><input type="radio" name="custom-key-scope" value="site" checked={controller.customAddForm.scope === "site"}
        onChange={() => controller.setCustomAddField({ scope: "site" })} /> {translate("This site only")}</label>
    </fieldset>
  );
}

/**
 * The "Add custom provider" form (`AccessTokensCategoryFilter`'s own button opens it) — a
 * standalone native `<dialog>`, not a per-provider `AddTokenForm` (this file's own header on why a
 * custom row has no shared provider group to attach an inline add-form to). Collects the four
 * fields the brief specifies (API base URL, Access token with a show/hide toggle, optional
 * Username, Category) plus a Name field every other row on this page already requires (the display
 * name the list/search will show — `TokenInputFields`' own "Name" field doc gives the identical
 * reasoning). Deliberately does NOT reuse `TokenInputFields`: that shared component's field set
 * (Name/Token/AccountId/Username) has no Base URL or Category concept, and both of those are
 * create-only here (see `rules.ts`'s `accessTokenRowProviderInfo` doc for why Replace on an
 * existing custom row does not re-collect them) — bolting a fifth, create-only field onto a
 * component shared with the seven catalog providers' Replace flow would risk it leaking there too.
 */
const AddCustomCredentialDialog = forwardRef<HTMLDialogElement, { controller: AccessTokensController; t: Translate }>(
  function AddCustomCredentialDialog({ controller, t: translate }, ref) {
    const { readyToSave, baseUrlInvalid, close, save } = useAddCustomCredentialDialog(ref, controller);
    const form = controller.customAddForm;
    // Same `aria-labelledby` fix as `RemoveConfirmDialog` above — one instance of this dialog per
    // page, so a static id is fine (contrast the per-row `row.id`-scoped id there).
    const titleId = "security-access-tokens-add-custom-title";

    return (
      <dialog
        ref={ref}
        className="confirm-dialog access-tokens-add-custom-dialog"
        aria-labelledby={titleId}
        {...agentHandle({ handle: "security-access-tokens-add-custom-dialog" }, { role: "region", label: "Add a custom provider not in the built-in list" })}
      >
        <h2 id={titleId}>{translate("Add custom provider")}</h2>
        <div className="field">
          <label className="field-label" htmlFor="security-add-custom-name">
            {translate("Name")}
            <RequiredFieldMarker />
          </label>
          <input
            id="security-add-custom-name"
            type="text"
            value={form.name}
            onChange={(e) => controller.setCustomAddField({ name: e.target.value })}
            {...agentHandle({ handle: "security-access-tokens-add-custom-name" }, { role: "field", label: "This custom provider's display name, e.g. a registrar" })}
          />
          <p className="field-hint">{translate("A short label so you can tell this apart from your other saved credentials.")}</p>
        </div>
        <div className="field">
          <label className="field-label" htmlFor="security-add-custom-base-url">
            {translate("API base URL")}
            <RequiredFieldMarker />
          </label>
          <input
            id="security-add-custom-base-url"
            type="url"
            value={form.baseUrl}
            placeholder="https://api.example.com"
            onChange={(e) => controller.setCustomAddField({ baseUrl: e.target.value })}
            {...agentHandle({ handle: "security-access-tokens-add-custom-base-url" }, { role: "field", label: "This provider's API base URL" })}
          />
          {baseUrlInvalid ? <p className="field-error">{translate("Enter a valid http:// or https:// URL.")}</p> : null}
        </div>
        <AdditionalHostsField
          value={form.additionalHosts}
          onChange={(value) => controller.setCustomAddField({ additionalHosts: value })}
          translate={translate}
        />
        <div className="field">
          <label className="field-label" htmlFor="security-add-custom-token">
            {translate("Access token")}
            <RequiredFieldMarker />
          </label>
          <SecretInput
            label={translate("Access token")}
            id="security-add-custom-token"
            autoComplete="new-password"
            value={form.token}
            onChange={(e) => controller.setCustomAddField({ token: e.target.value })}
            {...agentHandle({ handle: "security-access-tokens-add-custom-token" }, { role: "field", label: "This provider's access token" })}
            toggleAttrs={agentHandle({ handle: "security-access-tokens-add-custom-token-toggle" }, { role: "button", label: "Show or hide the access token" })}
          />
          <p className="field-hint">{translate("This will not be shown again for security purposes.")}</p>
        </div>
        <div className="field">
          <label className="field-label" htmlFor="security-add-custom-username">
            {translate("Username")}
          </label>
          <input
            id="security-add-custom-username"
            type="text"
            value={form.username}
            onChange={(e) => controller.setCustomAddField({ username: e.target.value })}
            {...agentHandle({ handle: "security-access-tokens-add-custom-username" }, { role: "field", label: "This provider's username, if it authenticates a token against one" })}
          />
          <p className="field-hint">{translate("Optional — only needed if this provider authenticates a token against a username.")}</p>
        </div>
        <div className="field">
          <label className="field-label" htmlFor="security-add-custom-category">
            {translate("Category")}
          </label>
          <select
            id="security-add-custom-category"
            value={form.category}
            onChange={(e) => controller.setCustomAddField({ category: e.target.value as AccessTokenRowCategoryId })}
            {...agentHandle({ handle: "security-access-tokens-add-custom-category" }, { role: "field", label: "Which category this credential is filed under" })}
          >
            {ACCESS_TOKEN_CATEGORIES.filter((c) => c.id !== "all").map((c) => (
              <option key={c.id} value={c.id}>
                {translate(c.label)}
              </option>
            ))}
          </select>
        </div>
        <CustomKeyStorageChoice controller={controller} />
        <WorksForField value={form.worksFor} options={controller.worksForOptions} onChange={worksFor => controller.setCustomAddField({ worksFor })} t={translate} />
        {form.error ? (
          <p className="save-error" role="alert">
            {form.error}
          </p>
        ) : null}
        <div className="confirm-dialog-actions">
          <button
            type="button"
            onClick={close}
            {...agentHandle({ handle: "security-access-tokens-add-custom-cancel" }, { role: "button", label: "Close this dialog without saving a custom provider" })}
          >
            {translate("Cancel")}
          </button>
          <button
            type="button"
            disabled={!readyToSave || form.saving}
            onClick={() => void save()}
            {...agentHandle({ handle: "security-access-tokens-add-custom-save" }, { role: "button", label: "Save this custom provider credential" })}
          >
            {form.saving ? translate("Saving…") : translate("Save")}
          </button>
        </div>
      </dialog>
    );
  }
);

import { forwardRef, useRef } from "react";
import { agentHandle, agentHandleSegment } from "@jini-ai/agentic";

import { useAdminLocale } from "../../hooks/use-admin-locale.hooks";
import { formatTimestamp } from "@jini-ai/ui/panel-kit";
import type { Translate } from "@jini-ai/ui/panel-kit";
import type { OtherCredentialStoreInfo } from "./rules";
import { otherCredentialRemoveDialogBody, removeDialogTitle } from "./security-i18n";
import type { OtherCredentialRowState, OtherCredentialsController } from "./hooks/use-other-credentials.hooks";
import { rowHandleBase, useOtherCredentialRemoveDialog } from "./OtherCredentialsSection.hooks";

/**
 * @file Tier 2 of the Access Tokens list — {@link OtherCredentialEntry}, the one top-level entry
 * component for the six single-row/per-item credential stores (`rules.ts`'s
 * `OTHER_CREDENTIAL_STORES`), rendered inline in the SAME merged, sorted list Tier 1's provider
 * groups render in, per the 2026-08-16 owner ruling ("one list, not two surfaces") and the
 * 2026-09-21 round-2 ruling that made it one TRUE ordered list rather than "Tier 1 sorted, Tier 2
 * always appended after". `AccessTokensTab.hooks.tsx`'s `useMergedSecretsOrder` owns the visibility
 * check and the per-store explosion into individual entries that this file used to own itself
 * (`OtherCredentialsSection`/`MaybeOtherCredentialGroup`/`OtherCredentialGroup`, deleted this pass —
 * see that hook's own doc for where the identical logic now lives); `AccessTokensTab.tsx` renders
 * this component directly, one call per merged entry.
 *
 * ## Why a Tier-2 "entry" has no separate parent heading the way a Tier-1 provider group does
 *
 * Tier 1's `ProviderGroup` shows one `<h3>` (the PROVIDER's name, e.g. "GitHub") with multiple named
 * `TokenRow`s underneath it, because one provider can hold several operator-named tokens. Nothing on
 * Tier 2 is named that way — `media-provider`/`external-mcp` can each hold more
 * than one ITEM (a provider, a server), but never more than one CREDENTIAL per item, so
 * there is nothing to nest. The owner's own mock reflects this directly: "Cloudinary (media)" reads
 * at the SAME indentation as the hosting/source-control providers, not nested under a "Media provider keys" parent —
 * each configured item (or, when a store has none configured, the store itself) gets its own
 * top-level entry, heading and all. {@link OtherCredentialEntry} is that entry; it structurally
 * mirrors `ProviderGroup` (one heading, one row) with exactly zero or one row inside, never more.
 */

function entryHandleLabel(name: string, purposeLabel: string, configured: boolean): string {
  return configured ? `${name} — ${purposeLabel}, configured` : `${name} — ${purposeLabel}, not configured`;
}

/** One top-level Tier-2 entry — see this file's header for why this has no separate parent heading
 *  the way a Tier-1 `ProviderGroup` does. `row` is `undefined` for the not-configured placeholder.
 *  Exported (2026-09-21 round 2): `AccessTokensTab.tsx` now mounts this directly, one call per
 *  `useMergedSecretsOrder` entry, in place of the deleted `OtherCredentialsSection` wrapper. */
export function OtherCredentialEntry({ store, row, controller }: { store: OtherCredentialStoreInfo; row: OtherCredentialRowState | undefined; controller: OtherCredentialsController }) {
  const translate = controller.t;
  const name = row?.name ?? translate(store.label);
  return (
    <section
      className="access-tokens-provider-group"
      {...agentHandle({ handle: `security-other-credentials-${store.id}-${agentHandleSegment({ value: row?.itemId ?? "none" })}` }, {
        role: "region",
        label: entryHandleLabel(name, store.purposeLabel, row !== undefined),
      })}
    >
      <h3 className="access-tokens-provider-heading">
        <span translate="no">{name}</span>
        <span className="access-tokens-provider-purpose"> · {translate(store.purposeLabel)}</span>
      </h3>
      <OtherCredentialEntryBody store={store} row={row} controller={controller} />
    </section>
  );
}

/** The entry's body — placeholder / static-configured / replaceable-configured, split out purely for
 *  the complexity gate (this repo's hard 9/9 cyclomatic/cognitive ceiling — `eslint.config.mjs`'s
 *  `F06 option B`). */
function OtherCredentialEntryBody({ store, row, controller }: { store: OtherCredentialStoreInfo; row: OtherCredentialRowState | undefined; controller: OtherCredentialsController }) {
  if (row === undefined) return <OtherCredentialPlaceholderRow store={store} t={controller.t} />;
  if (store.supportsReplace) return <OtherCredentialReplaceableRow row={row} controller={controller} />;
  return <OtherCredentialStaticRow row={row} controller={controller} />;
}

/** @param handleSuffix - Distinguishes this deep link from every other row's — a bare store id for
 *  the unconfigured placeholder (only one ever renders per store) or {@link rowHandleBase} for a
 *  real row, since a store like `media-provider` can hold more than one configured item. */
function DeepLink({ store, handleSuffix, t: translate }: { store: OtherCredentialStoreInfo; handleSuffix: string; t: Translate }) {
  return (
    <a
      className="btn-secondary"
      href={`/admin${store.screenPath}`}
      {...agentHandle({ handle: `security-other-credentials-manage-${handleSuffix}` }, {
        role: "link",
        label: `Open ${store.screenLabel} to manage this credential`,
      })}
    >
      {translate("Manage on")} {translate(store.screenLabel)} ↗
    </a>
  );
}

/** Nothing configured yet — same "always show it, invite the reader to go set it up" role Tier 1's
 *  `NotConnectedRow` plays, minus a `[Connect]` affordance: Tier 2 owns no Create flow (`rules.ts`'s
 *  own header on why), so the deep link IS this row's only action. */
function OtherCredentialPlaceholderRow({ store, t: translate }: { store: OtherCredentialStoreInfo; t: Translate }) {
  return (
    <div className="access-tokens-row">
      <div className="access-tokens-row-summary">
        <span className="access-tokens-row-marker" aria-hidden="true" />
        <span className="access-tokens-row-name">{translate("Not configured")}</span>
      </div>
      <div className="access-tokens-row-actions">
        <DeepLink store={store} handleSuffix={store.id} t={translate} />
      </div>
    </div>
  );
}

/** Configured, but this store does not support inline Replace (`external-mcp`
 *  — see `rules.ts`'s `OtherCredentialStoreInfo.supportsReplace` doc for why) — just the value fact,
 *  Remove, and the deep link, no disclosure to expand. Remove asks first, through the same
 *  {@link OtherCredentialRemoveDialog} the replaceable row uses: this store is the most
 *  destructive on the page (an External MCP delete loses a sealed OAuth secret for good), and this button used to fire on the first click. */
function OtherCredentialStaticRow({ row, controller }: { row: OtherCredentialRowState; controller: OtherCredentialsController }) {
  const translate = controller.t;
  const dialogRef = useRef<HTMLDialogElement>(null);
  return (
    <div className="access-tokens-row access-tokens-row-done access-tokens-row-static">
      <div className="access-tokens-row-summary">
        <span className="access-tokens-row-marker access-tokens-row-marker-done" aria-hidden="true">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="m5 12 4 4L19 6" /></svg>
        </span>
        <span className="access-tokens-row-fact">{row.valueFact}</span>
        {row.updatedAt ? (
          <span className="access-tokens-row-summary-meta">
            {translate("saved")} {formatTimestamp({ iso: row.updatedAt }, { timeZone: "local" })}
          </span>
        ) : null}
      </div>
      <div className="access-tokens-row-actions">
        <DeepLink store={row.store} handleSuffix={rowHandleBase({ row })} t={translate} />
        <button
          type="button"
          className="btn-danger"
          onClick={() => dialogRef.current?.showModal()}
          // `aria-label`: a store can hold more than one configured item (this file's own
          // `handleSuffix` doc comment above names `media-provider` as an example), and every row
          // renders unconditionally — no accordion, no menu — so two configured items under the
          // same store put two identically-labeled "Remove from Tovu" buttons on screen at once.
          // `row.name` is this row's own display name, already visible in its heading.
          aria-label={`${translate("Remove from Tovu")} — ${row.name}`}
          {...agentHandle({ handle: `security-other-credentials-remove-${rowHandleBase({ row })}` }, { role: "button", label: `Remove ${row.name} from Tovu` })}
        >
          {translate("Remove from Tovu")}
        </button>
        {row.error ? (
          <p className="save-error" role="alert">
            {row.error}
          </p>
        ) : null}
      </div>
      <OtherCredentialRemoveDialog ref={dialogRef} row={row} controller={controller} t={translate} />
    </div>
  );
}

/** Configured, and this store supports retyping the key on its own dedicated screen (`DeepLink`) —
 *  always rendered open, no accordion: unlike Tier 1's `TokenRow`, there is no inline form here worth
 *  hiding behind a click. The Access token field shown below is the same masked `row.valueFact` the
 *  summary line already carries, rendered `disabled` — a natural, familiar "this is set, go elsewhere
 *  to change it" cue, not an editable draft. Deliberately carries no `agentHandle()` — a disabled
 *  field tagged as fillable would have an assistant try to type into it, find it inert, and get stuck;
 *  the `DeepLink` below is the one actionable path to actually change this value, same as a person
 *  reading this row would use. */
function OtherCredentialReplaceableRow({ row, controller }: { row: OtherCredentialRowState; controller: OtherCredentialsController }) {
  const translate = controller.t;
  const dialogRef = useRef<HTMLDialogElement>(null);
  return (
    <div className="access-tokens-row">
      {/* One shared block, not two independent rows — `align-items: stretch` in a column-direction
          inline-flex makes the (naturally narrow) token field stretch to match the actions row's own
          content width below it, so both edges line up instead of the field looking arbitrarily
          short next to a wider button group. */}
      <div className="access-tokens-row-block">
        <div className="access-tokens-row-fields access-tokens-row-fields-top">
          <div className="field">
            <label className="field-label" htmlFor={`security-other-credential-${rowHandleBase({ row })}`}>
              {translate("Access token")}
              {row.updatedAt ? (
                <span className="access-tokens-row-summary-meta access-tokens-field-label-meta">
                  {translate("saved")} {formatTimestamp({ iso: row.updatedAt }, { timeZone: "local" })}
                </span>
              ) : null}
            </label>
            {/* `type="text"`, not `"password"` — `row.valueFact` is already a pre-masked display
                string (leading dots + last 4 real characters); a password-type input would mask the
                last 4 a second time, hiding the one part of this value that's meant to stay visible. */}
            <input
              id={`security-other-credential-${rowHandleBase({ row })}`}
              className="access-tokens-row-field-disabled"
              type="text"
              autoComplete="off"
              value={row.valueFact}
              disabled
            />
          </div>
        </div>
        <div className="access-tokens-row-actions access-tokens-row-actions-top">
          <DeepLink store={row.store} handleSuffix={rowHandleBase({ row })} t={translate} />
          <button
            type="button"
            className="btn-danger"
            onClick={() => dialogRef.current?.showModal()}
            // Same multi-item-per-store ambiguity as `OtherCredentialStaticRow`'s identical button
            // above.
            aria-label={`${translate("Remove from Tovu")} — ${row.name}`}
            {...agentHandle({ handle: `security-other-credentials-remove-${rowHandleBase({ row })}` }, { role: "button", label: `Remove ${row.name} from Tovu` })}
          >
            {translate("Remove from Tovu")}
          </button>
          {row.error ? (
            <p className="save-error" role="alert">
              {row.error}
            </p>
          ) : null}
        </div>
      </div>
      <OtherCredentialRemoveDialog ref={dialogRef} row={row} controller={controller} t={translate} />
    </div>
  );
}

/**
 * Native `<dialog>` confirm, mirroring Tier 1's `RemoveConfirmDialog` — same "Remove from Tovu,
 * never Revoke" load-bearing copy constraint (`rules.ts`'s own header) for the four replaceable
 * stores: deleting Tovu's row does not revoke the credential at the provider, and this dialog is the
 * one place that fact gets stated in words. The two static-row stores state their own, different
 * fact instead (`otherCredentialRemoveDialogBody`). No equivalent "this is the last row for this provider" note: every Tier-2 store
 * already caps at one row per item, so removing it is always the only-row case — the sentence would
 * be true on every single Remove and therefore say nothing new.
 *
 * Confirm button carries no `agentHandle`, same destructive-action boundary Tier 1's own confirm
 * dialog draws.
 */
const OtherCredentialRemoveDialog = forwardRef<HTMLDialogElement, { row: OtherCredentialRowState; controller: OtherCredentialsController; t: Translate }>(
  function OtherCredentialRemoveDialog({ row, controller, t: translate }, ref) {
    const locale = useAdminLocale();
    const { close, confirm } = useOtherCredentialRemoveDialog(ref, row, controller);
    // `aria-labelledby`, not left implicit — same fix, same reasoning, as Tier 1's own
    // `RemoveConfirmDialog` (`AccessTokensTab.tsx`): a native `<dialog>` gets no accessible name
    // for free from an `<h2>` inside it, and this doc comment's own header already promises this
    // dialog "mirrors Tier 1's `RemoveConfirmDialog` exactly" — this brings that true for the title
    // link too. `rowHandleBase({ row })` (already this row's DOM-id-safe base, used below by its own
    // input/deep-link ids) keeps this id unique across every Tier-2 row's own dialog.
    const titleId = `security-other-credentials-remove-title-${rowHandleBase({ row })}`;
    return (
      <dialog ref={ref} className="confirm-dialog" aria-labelledby={titleId}>
        <h2 id={titleId}>{removeDialogTitle(locale, row.name)}</h2>
        {/* Per-store body — `otherCredentialRemoveDialogBody`'s own doc: the shared "does NOT
            revoke" sentence is kept for the replaceable stores; External MCP gets its own. */}
        <p className="confirm-dialog-body">{otherCredentialRemoveDialogBody(locale, row.store)}</p>
        <div className="confirm-dialog-actions">
          <button
            type="button"
            onClick={close}
            {...agentHandle({ handle: `security-other-credentials-remove-cancel-${rowHandleBase({ row })}` }, { role: "button", label: "Close this dialog without removing the credential" })}
          >
            {translate("Cancel")}
          </button>
          <button type="button" className="btn-danger" onClick={confirm}>
            {translate("Remove from Tovu")}
          </button>
        </div>
      </dialog>
    );
  }
);

import { agentHandle } from "@jini-ai/agentic";

import { useAdminLocale } from "../../hooks/use-admin-locale.hooks";
import { navigate } from "../../lib/router";
import { resolveActiveTabId } from "@jini-ai/ui/panel-kit";
import { TabBar, type TabBarTab } from "@jini-ai/ui/tab-strip";
import { t } from "./security-i18n";
import { AccessTokensTab } from "./AccessTokensTab";
import { SiteKeyTab } from "./SiteKeyTab";
import { AccessTokensIcon, SiteKeyIcon } from "./security-visuals";
import { useWiredAccessTokens } from "./hooks/use-access-tokens.hooks";
import { useWiredSiteKey } from "./hooks/use-site-key.hooks";
import { useWiredSecurityPermissions } from "./hooks/use-security-permissions.hooks";

/**
 * @file The Security page (`/admin/access-tokens`) — a consolidation, not a new store: every token
 * here already lives in `publish_credential_sets` (Static Site tab) or
 * `source_control_credential_sets` (Source Control page); this page is one central place to see,
 * name, replace, and remove them, per `development/todos.md:1208`'s original spec and its
 * 2026-08-16 supersession recorded in `ADS-memory/reports/continuity/2026-08-16-session-6-handoff.md`.
 *
 * ## Create lives HERE too — the third and final word on a decision that moved twice
 *
 * The 2026-08-15 spec: Security is READ + REMOVE only, Create stays on the feature flow. The
 * 2026-08-16 session-6 handoff superseded that once: Replace/rotate joins Security too (the owner's
 * rotation argument — a revoked token needs ONE place to put the new one). The owner then superseded
 * it a SECOND time, same session: Create belongs here as well, in their own words, "you have to
 * create the access token and paste it and then save it, or you can replace it, or you can just
 * remove it so other people who are logging in don't have it."
 *
 * This is NOT a contradiction of the original "two entry points is the which-row-is-authoritative
 * bug" objection, once what "Create" means on each screen is made precise (`AccessTokensTab.tsx`'s
 * own header works through this in full): Static Site/Source Control each create exactly ONE thing
 * per provider — the DEFAULT connection, via a flat always-visible row with no label picker. This
 * page's own Create is a DIFFERENT capability neither of those forms exposes at all: a SECOND,
 * THIRD, differently-named token for a provider that already has one (a 30-day test token alongside
 * a production token — the owner's own example). There is exactly one place that capability can live
 * — it does not duplicate what Static Site/Source Control already do, it is the thing neither of
 * them does. Static Site and Source Control are UNCHANGED by this page's existence: same one-row
 * accordion, same `isDefault` row they always wrote and still write, still reachable and functional
 * throughout — this page's writes go through the exact same two HTTP endpoints those pages already
 * use (`hooks/access-tokens-dependencies.hooks.ts`), never a new one.
 *
 * ## Scope: all eight credential stores, one list — the 2026-08-16 owner ruling
 *
 * `rules.ts`'s `ACCESS_TOKEN_PROVIDERS` (Tier 1: `publish_credential_sets`, `source_control_
 * credential_sets` — both label + `isDefault`, both full CRUD, multi-row per provider) and
 * `OTHER_CREDENTIAL_STORES` (Tier 2: the four single-row/per-item sealed-credential stores — BYOK x2,
 * media providers, external MCP) are ALL read and
 * rendered in one flat list, filtered by one search box and one category row
 * (`AccessTokensTab.tsx`'s own header has the ruling in full: "a Cloudinary key and a GitHub token
 * are the same kind of thing"). The tier split survives only as a per-row capability difference —
 * Tier 1 keeps `[+ Add]` and multiple named rows; Tier 2 gets Replace/Remove and a deep link, never a
 * second Create — not as two separate surfaces, and there is no partial-inventory disclosure left to
 * show once every store is read.
 *
 * Page shell mirrors `SourceControl.tsx`/`Deployment.tsx` exactly: `page-header` + `TabBar`. Two
 * real tabs as of 2026-09-09 — "Access Tokens" (above) and "site key" (`SiteKeyTab.tsx`) — not
 * padded with a disabled placeholder for a THIRD tab nothing here asks for yet (Activity Log and
 * Roles & Permissions already have their own top-level Operations/People nav entries, not sibling
 * tabs of this page).
 *
 * Page renamed "Security" -> "Secrets" the same day (owner naming decision, not this agent's
 * call): the most accurate label for what's actually here — access tokens, the site key,
 * credentials — matching what hosting and git providers already call the same thing. The rename is cosmetic
 * (nav label + `<h1>` only, per `translateAdminNavLabel`'s "copy string is its own i18n key"
 * convention — `panels.tsx`'s nav entry and this file's own `t(locale, "Secrets")` calls are the
 * only two places the old "Security" literal lived); the module/file names, the route id
 * (`/admin/access-tokens`, independent of the label — see `panels.tsx`'s own comment), and every
 * internal identifier below (`SECURITY_TAB_IDS`, `security-i18n.ts`, `SecurityProps`, …) are
 * UNCHANGED — renaming those is a bigger, separate move this pass does not make.
 *
 * "site key" joined the same day: not another saved credential this page reads, but the ONE key
 * that (partially — see `SiteKeyTab.tsx`'s own header) protects every credential Access Tokens
 * lists. `admin.security.site-key.manage`-gated separately from every verb above (`features/
 * identity/site-key-permission.ts`) — a narrower trust boundary than ordinary content admin,
 * deliberately not reusing this page's existing permission checks.
 *
 * ## The site key tab is affordance-hidden, not just protected server-side (2026-09-10)
 *
 * Every site-key route already re-checks `admin.security.site-key.manage` server-side
 * (`site-key-permission.ts`'s own header) — that gate was never the gap. Until this pass, the
 * TAB itself rendered for every logged-in admin-panel user regardless of role, so an editor/viewer
 * saw a tab that would 403 on every action inside it. `useWiredSecurityPermissions` (`hooks/
 * use-security-permissions.hooks.ts`) reads the same permission client-side, UX-only
 * (`lib/permissions.ts`'s `hasPermission` — its own header states plainly this is not the security
 * boundary): the tab entry, the rendered `<SiteKeyTab />`, and a direct `?tab=site-key` link all
 * fall back to Access Tokens for a principal who does not hold it. `resolveSecurityTabId` treats a
 * still-loading permission read as "not permitted" (`hasPermission` naturally returns `false` for
 * empty/absent permissions), so the tab never flashes into view before disappearing.
 */

const SECURITY_TAB_IDS = ["access-tokens", "site-key"] as const;
type SecurityTabId = (typeof SECURITY_TAB_IDS)[number];

/** The tab-id list for a principal WITHOUT `admin.security.site-key.manage` — see this file's header
 *  ("The site key tab is affordance-hidden") for why {@link resolveSecurityTabId} needs a second,
 *  narrower list rather than only ever validating against {@link SECURITY_TAB_IDS}. */
const ACCESS_TOKENS_ONLY_TAB_IDS: readonly SecurityTabId[] = ["access-tokens"];

/** Falls back to the Access Tokens tab for an absent or unrecognized `?tab=` value, delegating to
 *  the shared `../../lib/resolve-active-tab-id` guard `Deployment.tsx`/`SourceControl.tsx`/
 *  `Database.tsx`/`Themes.tsx` all use — AND, since 2026-09-10, for a `?tab=site-key` link
 *  followed by a principal who does not hold `admin.security.site-key.manage`: `validIds` narrows to
 *  {@link ACCESS_TOKENS_ONLY_TAB_IDS} for them, so `site-key` reads as just as "unrecognized" as a
 *  typo would, and they land on Access Tokens instead of an empty panel. */
function resolveSecurityTabId(tabId: string | null | undefined, canManageSiteKey: boolean): SecurityTabId {
  const validIds: readonly SecurityTabId[] = canManageSiteKey ? SECURITY_TAB_IDS : ACCESS_TOKENS_ONLY_TAB_IDS;
  return resolveActiveTabId({ tabId: tabId, validIds: validIds, defaultId: "access-tokens" });
}

export interface SecurityProps {
  /** The `?tab=` query value from `panels.tsx`'s `security` route. See {@link resolveSecurityTabId}. */
  tabId?: string | null;
  /** DI seam for tests, threaded through to {@link AccessTokensTab} — same convention
   *  `SourceControlProps.useSourceControlCredentialsHook` follows. */
  useAccessTokensHook?: typeof useWiredAccessTokens;
  /** DI seam for tests, threaded through to {@link SiteKeyTab} — same convention. */
  useSiteKeyHook?: typeof useWiredSiteKey;
  /** DI seam for tests — decides whether the site key tab is even offered. See this file's
   *  header ("The site key tab is affordance-hidden"). */
  useSecurityPermissionsHook?: typeof useWiredSecurityPermissions;
}

function resolveSecurityPermissionsHook(
  override: typeof useWiredSecurityPermissions | undefined
): typeof useWiredSecurityPermissions {
  return override ?? useWiredSecurityPermissions;
}

export function Security(props: SecurityProps) {
  const locale = useAdminLocale();
  const useSecurityPermissionsHook = resolveSecurityPermissionsHook(props.useSecurityPermissionsHook);
  const { canManageSiteKey } = useSecurityPermissionsHook();
  const activeTabId = resolveSecurityTabId(props.tabId, canManageSiteKey);

  const tabs: TabBarTab[] = [
    {
      id: "access-tokens",
      label: t({ locale: locale, key: "Access Tokens" }),
      icon: <AccessTokensIcon size={16} />,
      handle: "security-tab-access-tokens",
      handleLabel: "Switch to the Access Tokens tab — every access token and other saved credential this install holds, in one place",
    },
    ...(canManageSiteKey
      ? [
          {
            id: "site-key",
            label: t({ locale: locale, key: "Site key" }),
            icon: <SiteKeyIcon size={16} />,
            handle: "security-tab-site-key",
            handleLabel: t({ locale: locale, key: "Switch to the site key tab" }),
          } satisfies TabBarTab,
        ]
      : []),
  ];

  function handleTabChange(nextTabId: string) {
    navigate(`/access-tokens?tab=${nextTabId}`, { replace: true });
  }

  return (
    <div className="page">
      <div
        className="page-header"
        {...agentHandle({ handle: "security-header" }, {
          role: "region",
          label: "Secrets panel header — every saved access token and the site key that protects them, in one place",
        })}
      >
        <div className="page-header-text">
          <p className="page-kicker">{t({ locale: locale, key: "Operations" })}</p>
          <h1 className="page-title">{t({ locale: locale, key: "Secrets" })}</h1>
          <p className="page-description">
            {t({ locale: locale, key: "One place to see every access token this install holds, and create, rotate, or remove one without hunting across the screens that created it." }
            )}
          </p>
        </div>
      </div>
      <TabBar
        ariaLabel={t({ locale: locale, key: "Secrets" })}
        tabs={tabs}
        activeId={activeTabId}
        onChange={handleTabChange}
        containerHandle="security-tab-bar"
      />
      {activeTabId === "access-tokens" ? <AccessTokensTab useAccessTokensHook={props.useAccessTokensHook} /> : null}
      {activeTabId === "site-key" ? <SiteKeyTab useSiteKeyHook={props.useSiteKeyHook} /> : null}
    </div>
  );
}

import { siteKeyStatusBadgeLabel } from "./hooks/site-key-status.rules";
import { AGENT_PRIVATE_ATTRIBUTE, agentHandle } from "@jini-ai/agentic";

import { useAdminLocale } from "../../hooks/use-admin-locale.hooks";
import { siteKeyGenerateErrorMessage } from "./security-i18n";
import { useWiredSiteKey } from "./hooks/use-site-key.hooks";
import type { SiteKeyController, SiteKeyGenerateFailure } from "./hooks/use-site-key.hooks";
import { useRevealedKeyCopy } from "./SiteKeyTab.hooks";
import { isSiteKeyLocked, siteKeyLockedNote, useWiredSiteKeyRecovery, type SiteKeyRecoveryController } from "./hooks/use-site-key-recovery.hooks";
import { SiteKeyRecoveryCard } from "./SiteKeyRecoveryCard";
import type { Translate } from "@jini-ai/ui/panel-kit";

/**
 * @file The Secrets page's Site key tab — view/reveal/generate the file half of
 * `TOVU_SITE_KEY`'s resolution (`features/webhooks/keyring.env.ts`, server-side).
 *
 * ## What this tab covers, as of the 2026-09-09 durability fix
 *
 * A generated key file now genuinely protects production too: it lives on the durable data volume
 * (not the container's ephemeral rootfs), the production boot gate accepts it, and the keyring
 * that seals every real stored credential (BYOK, publish/source-control/custom creds,
 * media-provider secrets) can now read one. {@link SiteKeyScopeNotice} still discloses the one
 * remaining gap: webhook signing / newsletter tokens still require the env var in production —
 * that keyring's own construction is deliberately unchanged this pass (a committed regression
 * test pins it). See `server/inbound/admin-http/routes/system/site-key.ts`'s header for the
 * full account, including the accepted tradeoff (a key file now lives beside the database it
 * protects — a volume backup carries both).
 *
 * ## No rotate/replace
 *
 * `POST .../generate` only ever creates. Replacing an existing key would orphan every secret
 * already sealed under the old one, and a confirmation strong enough for that (not a generic "are
 * you sure") is a separate, NOT-built feature — reported as out of scope rather than half-built.
 * Once a key is active (`status.active`), {@link SiteKeyGenerateAction} shows no control that
 * could be mistaken for one.
 *
 * ## Reveal — one mechanism, available any time a key is active
 *
 * An earlier brief had generate show its new value once, at creation, fingerprint-only after
 * that. The owner superseded it: "i want that token to be visible to admins or else when it
 * breaks they have no idea whats going on." {@link SiteKeyRevealAction} is the ONE place this
 * tab ever renders a key VALUE — never on page load, only behind its own explicit click, and
 * usable at any time afterward (not just right after a generate), for exactly the diagnostic
 * reason the owner gave: confirming the value here matches what's set in the host's secrets, or
 * figuring out why credentials stopped decrypting. No audit trail on reveal — this codebase has
 * no general-purpose sensitive-read audit mechanism to hook into (checked, not built here).
 */

export interface SiteKeyTabProps {
  /** DI seam for tests — same convention as every other wired-hook prop in this app. */
  useSiteKeyHook?: typeof useWiredSiteKey;
  /** DI seam for the locked site's recovery card. */
  useSiteKeyRecoveryHook?: typeof useWiredSiteKeyRecovery;
}

function resolveSiteKeyHook(override: typeof useWiredSiteKey | undefined): typeof useWiredSiteKey {
  return override ?? useWiredSiteKey;
}

export function SiteKeyTab(props: SiteKeyTabProps) {
  const useSiteKeyHook = resolveSiteKeyHook(props.useSiteKeyHook);
  const useRecoveryHook = props.useSiteKeyRecoveryHook ?? useWiredSiteKeyRecovery;
  const controller = useSiteKeyHook();
  const recovery = useRecoveryHook(controller.refresh);
  return (
    <div
      className="site-key-tab"
      {...agentHandle({ handle: "security-site-key" }, {
        role: "region",
        label: controller.t("View and reveal the site key"),
      })}
    >
      <SiteKeyBody controller={controller} recovery={recovery} />
    </div>
  );
}

/** Loading/error/loaded split — pulled out purely for the complexity gate, same reasoning
 *  `AccessTokensBody` documents in `AccessTokensTab.tsx`. */
function SiteKeyBody({ controller, recovery }: { controller: SiteKeyController; recovery: SiteKeyRecoveryController }) {
  const translate = controller.t;
  if (controller.loadError) {
    return (
      <p className="notice error" role="status" {...agentHandle({ handle: "security-site-key-load-error" }, { role: "status", label: "Shows the error when the site key's status could not be loaded" })}>
        {controller.loadError}
      </p>
    );
  }
  if (controller.status === undefined) {
    return <p className="site-key-loading">{translate("Loading…")}</p>;
  }
  return (
    <>
      <SiteKeyScopeNotice runtimeMode={controller.status.runtimeMode} t={translate} />
      {isSiteKeyLocked(controller.status, controller.generateError) || recovery.resultMessage ? <SiteKeyRecoveryCard recovery={recovery} /> : null}
      <SiteKeyStatusCard controller={controller} status={controller.status} />
    </>
  );
}

/** The always-visible "what this covers" disclosure — see this file's header. Rendered
 *  unconditionally, not just on failure: the fact it states is true whether or not anything has
 *  gone wrong, and the owner's own "self-contained" framing is exactly what this exists to make
 *  precise before anyone clicks anything.
 *
 *  Rewritten 2026-09-09 per the owner's live review ("the site key content needs to be simpler
 *  ... users are not gonna know what this even is"): leads with one plain sentence any operator
 *  can act on, keeps the production-only storage tradeoff visible (it changes what someone should
 *  do, not just background trivia), and demotes the webhook/newsletter exception to a de-emphasized
 *  note — same `.jini-field-hint` convention `AgentPlugins.tsx`'s section footnotes use — since it's
 *  a real but secondary caveat, not something a first-time reader needs to parse up front. */
function SiteKeyScopeNotice({ runtimeMode, t: translate }: { runtimeMode: "production" | "local"; t: Translate }) {
  return (
    <div className="notice warning site-key-scope-notice" {...agentHandle({ handle: "security-site-key-scope-notice" }, { role: "status", label: "What this site key does and does not cover" })}>
      <p>{translate("This key protects the passwords, API keys, and other credentials you've saved in Tovu — including on your live site.")}</p>
      {runtimeMode === "production" ? (
        <p>{translate("On a live site, this key is stored right next to your database. Anyone who gets a full backup of your server would get both your data and the key that unlocks it.")}</p>
      ) : null}
      <p className="jini-field-hint site-key-scope-detail">
        {translate("One exception: webhook signing and newsletter unsubscribe links use a separate key on your live site.")}
      </p>
    </div>
  );
}

/** The status card — badge + fingerprint + source-specific note + Reveal + Generate. Split out
 *  purely for the complexity gate. Only rendered once the status has loaded, so `status` is the
 *  controller's own, already-narrowed value. */
function SiteKeyStatusCard({ controller, status }: { controller: SiteKeyController; status: NonNullable<SiteKeyController["status"]> }) {
  const translate = controller.t;
  return (
    <section className="card site-key-status-card" {...agentHandle({ handle: "security-site-key-status" }, { role: "region", label: "The active site key's source, fingerprint, and reveal control" })}>
      <h3 className="site-key-status-heading">{translate("Site key")}</h3>
      <p className="site-key-status-badge-row">
        <span className={`status ${siteKeyStatusBadgeClass(status.active, status.invalid)}`}>{siteKeyStatusBadgeLabel({ status, t: translate })}</span>
        {status.fingerprint ? (
          <span className="site-key-fingerprint-group" title={translate("A short ID for this key. It changes if the key changes.")}>
            <span className="site-key-fingerprint-label">{translate("Fingerprint")}</span>
            <code className="site-key-fingerprint">{status.fingerprint}</code>
          </span>
        ) : null}
      </p>
      <p className="site-key-status-note">{siteKeyLockedNote(status, controller.generateError, translate) ?? siteKeyStatusNote(status, translate)}</p>
      <SiteKeyRevealAction controller={controller} />
      {/* Site-key plan (2026-09-24) §A.6: Generate is hidden by default, not deleted — the
          server route, `useSiteKey`'s `generate()`, and this tab's own `SiteKeyGenerateAction`
          all stay wired (see that component's own header) so a later slice can re-expose it (e.g.
          behind an "advanced" disclosure) without rebuilding the plumbing. There is no existing
          "advanced" disclosure pattern on this tab to tuck it into, so this pass just hides it. */}
    </section>
  );
}

function siteKeyStatusBadgeClass(active: boolean, invalid: boolean | undefined): string {
  if (invalid) return "status-warning";
  return active ? "status-ok" : "status-neutral";
}


/** The source-specific explanatory line under the badge — one sentence per case, no `{path}`
 *  template needed (the path is rendered as its own `<code>`, not interpolated into translated
 *  prose). Reworded 2026-09-09 alongside {@link SiteKeyScopeNotice} so the badge's
 *  "environment variable" vs. "key file" distinction is explained in plain terms here rather than
 *  assumed — the badge itself stays terse, this line carries the plain-language context. The
 *  `TOVU_SITE_KEY` variable name stays in the invalid-env case since fixing it requires
 *  that exact name. The `"none"` case was reworded again for the site-key plan (2026-09-24) item 3:
 *  it used to promise that clicking Generate would save a key to `status.keyFilePath` — stale ever
 *  since Generate was hidden by default (§A.6) in favor of `ensureSiteKeyForBoot` minting one
 *  automatically at boot, and doubly so once no fixed path is even guaranteed to be the one that
 *  ends up used (per-site keys, §A.1). @complexity O(1). */
function siteKeyStatusNote(status: { active: boolean; source: "env" | "file" | "none"; invalid?: boolean; keyFilePath: string }, translate: Translate) {
  if (status.invalid) {
    return status.source === "env" ? (
      <>{translate("A key is set up for this install, but it's not in a usable format, so Tovu can't use it. Fix the value stored in the TOVU_SITE_KEY environment variable to resolve this.")}</>
    ) : (
      <>
        {translate("The key file at")} <code>{status.keyFilePath}</code> {translate("isn't in a usable format, so Tovu can't use it. It will need to be replaced by hand on the server — this tab can't do that yet.")}
      </>
    );
  }
  if (status.source === "env") {
    return <>{translate("This key was set up directly on the server rather than as a file, and it's already active — there's nothing to do here. Changing it means updating it on the server and restarting.")}</>;
  }
  if (status.source === "file") {
    return (
      <>
        {translate("Stored in a file on this server, at")} <code>{status.keyFilePath}</code>
      </>
    );
  }
  return <>{translate("A key is created automatically when this site starts.")}</>;
}

/** Reveal — never shown on page load; the button is present whenever a key is active, and clicking
 *  it fetches (and displays, with a copy control) the raw value. Human-only: Reveal carries no agent
 *  handle, so the assistant's page driver cannot click it. {@link SiteKeyRevealedValue}'s
 *  own Hide button toggles it back off, client-side only (no server call). @complexity O(1). */
function SiteKeyRevealAction({ controller }: { controller: SiteKeyController }) {
  const translate = controller.t;
  const status = controller.status;
  if (!status?.active) return null;
  if (controller.revealedHex) {
    return <SiteKeyRevealedValue hex={controller.revealedHex} onHide={controller.hideRevealed} t={translate} />;
  }
  return (
    <div className="site-key-reveal-action">
      <button
        type="button"
        className="btn-secondary"
        disabled={controller.revealing}
        onClick={() => void controller.reveal()}
      >
        {controller.revealing ? translate("Revealing…") : translate("Reveal")}
      </button>
      {controller.revealError ? (
        <p className="notice error" role="status" {...agentHandle({ handle: "security-site-key-reveal-error" }, { role: "status", label: "Shows the error when revealing the site key failed" })}>
          {controller.revealError}
        </p>
      ) : null}
    </div>
  );
}

/** The revealed value itself, plus Copy/Hide — the ONLY place in this tab that ever renders a key
 *  VALUE rather than a fingerprint. The value is `data-agent-private`, so no published ancestor's
 *  text carries it to the agent, and neither it nor Copy has a handle. @complexity O(1). */
function SiteKeyRevealedValue({ hex, onHide, t: translate }: { hex: string; onHide: () => void; t: Translate }) {
  const { copied, copy } = useRevealedKeyCopy(hex);
  return (
    <div className="site-key-revealed-value">
      <code {...{ [AGENT_PRIVATE_ATTRIBUTE]: "" }}>{hex}</code>
      <div className="site-key-revealed-actions">
        <button type="button" className="btn-secondary" onClick={() => void copy()}>
          {copied ? translate("Copied!") : translate("Copy")}
        </button>
        <button type="button" className="btn-ghost" onClick={onHide} {...agentHandle({ handle: "security-site-key-hide" }, { role: "button", label: "Hide the revealed site key" })}>
          {translate("Hide")}
        </button>
      </div>
    </div>
  );
}

/** The Generate button + its own error banner. Shown only for the genuinely decidable case — no
 *  key at all (`status.source === "none"`) — never once a key is active, and never for an
 *  existing-but-invalid file or env var either (sol packet-3 finding 3-1, 2026-09-16): the server
 *  route only ever CREATES a key file, so offering Generate against a file that already exists
 *  (valid or not) is a guaranteed 409 with no path to success. A confirmed replace/rotate flow for
 *  that state is a separate, deliberately NOT-built feature (this file's own header). Works in
 *  every runtime mode now (2026-09-09 durability fix) — no longer disabled in production.
 *  @complexity O(1). */
export function SiteKeyGenerateAction({ controller }: { controller: SiteKeyController }) {
  const translate = controller.t;
  const status = controller.status;
  if (!status || status.source !== "none") return null;
  return (
    <div className="site-key-generate-action">
      <button
        type="button"
        className="btn-primary"
        disabled={controller.generating}
        onClick={() => void controller.generate()}
        {...agentHandle({ handle: "security-site-key-generate" }, { role: "button", label: "Generate a site key file for this install" })}
      >
        {controller.generating ? translate("Generating…") : translate("Generate a key")}
      </button>
      {controller.generateError ? <SiteKeyGenerateErrorNote failure={controller.generateError} t={translate} /> : null}
    </div>
  );
}

function SiteKeyGenerateErrorNote({ failure, t: translate }: { failure: SiteKeyGenerateFailure; t: Translate }) {
  const locale = useAdminLocale();
  const text =
    failure.kind === "already-exists"
      ? translate("A key file already exists. This tab only creates a new key — it never overwrites one.")
      : failure.kind === "generic"
        ? siteKeyGenerateErrorMessage(locale, failure.detail)
        : failure.detail;
  return (
    <p className="notice error" role="status" {...agentHandle({ handle: "security-site-key-generate-error" }, { role: "status", label: "Shows the error when generating a site key file failed" })}>
      {text}
    </p>
  );
}

