import { t } from './settings-execution-i18n';

/** Detection runs on the server; preload bridge presence identifies when that server is local.
 * Do not infer desktop from screen size, localhost URLs, or the site-switcher flag. */
export function localCliScopeCopy(
  { desktop }: { desktop: boolean }, _optional = {},
): string {
  return desktop ? 'Detected on this computer.' : 'Detected on the Tovu server, not on your own computer.';
}

export function isDesktopAdmin(
  {}: Record<string, never>, { targetWindow }: { targetWindow?: Window } = {},
): boolean {
  return getFolderDropPort(targetWindow) !== null || getVoiceInputPort(targetWindow) !== null;
}

/** Unknown authentication is not a refusal. Warn only about a confirmed missing sign-in. */
export function selectedAgentWarning(
  { mode, agentId, agents, locale }: {
    mode: string; agentId: string | null; agents: readonly DetectedAgent[]; locale: string;
  }, _optional = {},
): string | null {
  const agent = agents.find((candidate) => candidate.id === agentId);
  return mode === 'local-cli' && agent?.installed && agent.authStatus === 'missing'
    ? `${agent.label}: ${t({ locale: locale, key: 'Authentication required. Sign in before sending.' })}` : null;
}

/** Empty strings suppress the shared card's divider; trim whitespace without inventing vendor copy.
 * Undefined preserves Jini's existing vendor-description fallback. */
export function normalizeAgentDescription(
  { agent }: { agent: DetectedAgent }, _optional = {},
): DetectedAgent {
  return agent.description === undefined ? agent : { ...agent, description: agent.description.trim() };
}

/** Share the component's scan with the warning instead of spawning another inventory sweep.
 * Rescan results replace previous auth status; rejected scans remain failures, never empty lists. */
export function createAgentPresentationPort(
  { port, onAgents }: { port: ExecutionPort; onAgents: (agents: readonly DetectedAgent[]) => void },
  _optional = {},
): ExecutionPort {
  let latestScan = 0;
  const project = async (request: () => Promise<readonly DetectedAgent[]>) => {
    const scan = ++latestScan;
    const agents = (await request()).map((agent) => normalizeAgentDescription({ agent }));
    // A slow initial scan must not overwrite a newer rescan's authentication result.
    if (scan === latestScan) onAgents(agents);
    return agents;
  };
  return {
    ...port,
    detectLocalAgents: () => project(() => port.detectLocalAgents()),
    ...(port.rescanLocalAgents ? { rescanLocalAgents: () => project(() => port.rescanLocalAgents!()) } : {}),
  };
}

import { useCallback, useEffect, useRef, useState } from "react";

import { api, describeApiError } from "@/lib/api";

/**
 * @file The row-level "Connect" button behind Settings → External MCP (2026-10-23): starts the
 * OAuth sign-in for one saved server and tells the panel when to re-read the roster.
 *
 * `POST .../oauth/connect` answers one of two ways. `redirect_required`: the provider URL opens in
 * a popup, and the public callback page posts `tovu:external-mcp-connected` back to this tab
 * (`routes/oauth/callback-page.ts`). That message can be lost (no opener, a system browser), so
 * regaining focus also counts as "go look" — the same fallback that page's header asks every
 * bridge for. `device_code`: the operator types `userCode` at the provider; this hook polls
 * `.../oauth/device/poll` on the server's own interval until it says `connected`.
 *
 * The popup is opened BEFORE the connect request resolves (as `about:blank`, then pointed at the
 * provider), because a window opened after an `await` has lost the click's user activation and a
 * popup blocker may eat it. A device-code grant never needs it, so the panel says which grant the
 * row uses and the blank window is skipped for that one.
 */

/** Must match `EXTERNAL_MCP_CALLBACK_MESSAGE_TYPE` in the website's `routes/oauth/callback-page.ts`. */
export const EXTERNAL_MCP_CALLBACK_MESSAGE_TYPE = "tovu:external-mcp-connected";

export type ExternalMcpOAuthConnectPort = Pick<typeof api, "connectExternalMcpOAuth" | "pollExternalMcpOAuthDevice">;

export type ExternalMcpOAuthConnectState =
  | { phase: "idle"; error?: string }
  | { phase: "starting" }
  | { phase: "waiting" }
  | { phase: "device"; userCode: string; verificationUri: string };

/** Browser seams, so a test drives the flow without a real window. */
export interface ExternalMcpOAuthConnectWindow {
  open: (url: string) => { location: { href: string }; close: () => void } | null;
  addEventListener: Window["addEventListener"];
  removeEventListener: Window["removeEventListener"];
  origin: string;
}

const browserWindow = (): ExternalMcpOAuthConnectWindow => ({
  open: (url) => window.open(url, "_blank", "popup,width=520,height=720"),
  addEventListener: window.addEventListener.bind(window),
  removeEventListener: window.removeEventListener.bind(window),
  origin: window.location.origin,
});

/**
 * Drives one server's sign-in.
 *
 * @param input.serverId - The saved row to sign in.
 * @param input.grant - The row's saved grant; `device_code` skips the up-front popup.
 * @param input.onConnected - Re-reads the roster; called once sign-in lands, and on focus/close.
 * @returns The current state plus `connect()` and `cancel()`.
 * @complexity O(1) per call; device polling is one request per server-given interval.
 */
export function useExternalMcpOAuthConnect(
  { serverId, grant, onConnected }: { serverId: string; grant: string; onConnected: () => void },
  { port = api, win = browserWindow, fallbackError = "Sign-in could not start." }: { port?: ExternalMcpOAuthConnectPort; win?: () => ExternalMcpOAuthConnectWindow; fallbackError?: string } = {},
) {
  const [state, setState] = useState<ExternalMcpOAuthConnectState>({ phase: "idle" });
  // Everything that must stop on cancel/unmount: a poll timer, the message/focus listeners.
  const cleanup = useRef<(() => void) | null>(null);
  const onConnectedRef = useRef(onConnected);
  useEffect(() => { onConnectedRef.current = onConnected; }, [onConnected]);

  const stop = useCallback(() => {
    cleanup.current?.();
    cleanup.current = null;
  }, []);
  useEffect(() => stop, [stop]);

  const finish = useCallback((error?: string) => {
    stop();
    setState(error ? { phase: "idle", error } : { phase: "idle" });
    onConnectedRef.current();
  }, [stop]);

  const awaitRedirect = useCallback((w: ExternalMcpOAuthConnectWindow) => {
    const onMessage = (event: MessageEvent) => {
      if (event.origin !== w.origin || event.data?.type !== EXTERNAL_MCP_CALLBACK_MESSAGE_TYPE) return;
      finish(event.data.reason ? fallbackError : undefined);
    };
    const onFocus = () => finish();
    w.addEventListener("message", onMessage as EventListener);
    w.addEventListener("focus", onFocus);
    cleanup.current = () => {
      w.removeEventListener("message", onMessage as EventListener);
      w.removeEventListener("focus", onFocus);
    };
    setState({ phase: "waiting" });
  }, [finish, fallbackError]);

  const pollDevice = useCallback((intervalSeconds: number) => {
    let timer: ReturnType<typeof setTimeout> | undefined;
    let stopped = false;
    const tick = async () => {
      try {
        const result = await port.pollExternalMcpOAuthDevice(serverId);
        if (stopped) return;
        if (result.status === "connected") return finish();
        timer = setTimeout(() => void tick(), result.retryAfterSeconds * 1000);
      } catch (error) {
        if (!stopped) finish(describeApiError(error, fallbackError));
      }
    };
    timer = setTimeout(() => void tick(), intervalSeconds * 1000);
    cleanup.current = () => { stopped = true; clearTimeout(timer); };
  }, [port, serverId, finish, fallbackError]);

  const connect = useCallback(async () => {
    stop();
    const w = win();
    const popup = grant === "device_code" ? null : w.open("about:blank");
    setState({ phase: "starting" });
    try {
      const { auth } = await port.connectExternalMcpOAuth(serverId);
      if (auth.kind === "redirect_required") {
        if (popup) popup.location.href = auth.authorizationUrl;
        else w.open(auth.authorizationUrl);
        awaitRedirect(w);
        return;
      }
      popup?.close();
      const verificationUri = auth.verificationUriComplete ?? auth.verificationUri;
      w.open(verificationUri);
      setState({ phase: "device", userCode: auth.userCode, verificationUri });
      pollDevice(auth.intervalSeconds);
    } catch (error) {
      popup?.close();
      setState({ phase: "idle", error: describeApiError(error, fallbackError) });
    }
  }, [stop, win, grant, port, serverId, awaitRedirect, pollDevice, fallbackError]);

  const cancel = useCallback(() => {
    stop();
    setState({ phase: "idle" });
  }, [stop]);

  return { state, connect, cancel };
}

import { credentialText, formatCredentialHint, formatCredentialHints, translateCredentialMessage, credentialDraftError } from "@/lib/credential-copy";
import { useAdminLocale } from "@/hooks/use-admin-locale.hooks";
import { useCallback, useMemo, useRef, useState } from "react";

import type {
  AddSourceInput,
  AddSourceResult,
  SourceConfigDependencies,
  SourceConfigItem,
  SourceTestResult,
} from "@jini-ai/ui";

/**
 * `SourceUpdateInput` is declared in `@jini-ai/ui`'s `source-config-list/types.ts` but is not
 * re-exported from that feature's barrel, unlike every one of its siblings — an upstream oversight,
 * since `updateSource` is part of the public port contract. Derived from the port itself rather
 * than restated, so it tracks upstream automatically if the export is ever added or the shape
 * changes.
 */
type SourceUpdateInput = Parameters<
  NonNullable<SourceConfigDependencies<SourceConfigItem>["port"]["updateSource"]>
>[1];

import {
  api,
  describeApiError,
  type AdminExternalMcpOAuthInput,
  type AdminExternalMcpServer,
  type AdminExternalMcpServerInput,
} from "@/lib/api";
import { useSerialWrites } from "@jini-ai/ui/panel-kit";
import { t as tExternalMcp } from "../external-mcp-i18n";
import { mergeSourceUpdate, resolveExternalMcpEffectiveAuthMode, resolveExternalMcpEffectiveTransport, validateExternalMcpOAuthIdentity } from "../rules";

/**
 * @file The real transport behind Settings → External MCP, replacing the empty in-memory fake that
 * tab mounted while Tovu had no config store.
 *
 * ## Why field rendering is NOT driven by a fixed `SourceFieldSpec[]` here anymore
 *
 * Earlier versions of this file exported a single static `TOVU_MCP_FIELD_SPECS` array and Tovu
 * mounted `@jini-ai/ui`'s assembled `ExternalMcpTab` directly against it. That stopped being viable
 * once a server could be `stdio` OR `streamable_http`, with credentials `none`/`static_env`/`oauth`:
 * a static spec list has no way to hide `url`/`command` or the OAuth block depending on what the
 * operator is currently choosing, and showing every field for every combination unconditionally is
 * exactly the "here are all the fields, figure out which apply" experience this tab exists to avoid.
 * `../rules.ts`'s `buildExternalMcpFieldSpecs(values)` now computes the visible/required field set
 * from the draft's current values, and `../components/ExternalMcpSettingsPanel.tsx` — Tovu's own
 * replacement for `ExternalMcpTab` — recomputes it live as the operator types. This hook stays
 * unchanged in shape (still a `SourceConfigDependencies` port), it just no longer also hands back one
 * frozen spec list.
 *
 * ## The env field never round-trips a value
 *
 * `fetchSources` cannot populate `env`: no route returns a stored env value, deliberately. So the
 * field always arrives blank, and {@link toWriteBody} omits `env` entirely when it is still blank.
 *
 * That asymmetry is the safe direction and is chosen on purpose. If blank meant "clear", then every
 * enable/disable toggle and every label edit would silently wipe the operator's credentials —
 * exactly the failure the store's `undefined`-vs-`""` distinction exists to prevent. The cost is
 * that clearing credentials from the card alone is not expressible; removing and re-adding the
 * server is. Losing a token by accident is much worse than needing two steps to discard one.
 * `oauthClientSecret` follows the identical rule, for the identical reason — no read model ever
 * returns a stored client secret either.
 */

/** Joins stored argv back into the one-line field the operator edits, double-quoting any argument
 *  that contains whitespace — the one quoting form the server's `parseArgs` reads — so a re-save
 *  (e.g. toggling `enabled`) splits it back into the same arguments instead of breaking a path like
 *  `C:\\Users\\John Smith\\...` in two. @complexity O(n) in the total arg length. */
function joinArgs(args: readonly string[]): string {
  return args.map((arg) => (/\s/.test(arg) ? `"${arg}"` : arg)).join(" ");
}

function toItem(server: AdminExternalMcpServer, locale: string = "en"): SourceConfigItem {
  return {
    id: server.serverId,
    label: server.label,
    enabled: server.enabled,
    fields: {
      builtIn: server.builtIn ? "true" : "false",
      id: server.serverId,
      transport: server.transport,
      command: server.command,
      url: server.url ?? "",
      args: joinArgs(server.args),
      allowedToolNames: server.allowedToolNames.join(", "),
      // The operator's second, write-authorization list — same join convention as
      // `allowedToolNames` immediately above, and round-tripped the same way (never blanked, unlike
      // `env`/`oauthClientSecret`: the store returns this list in the clear, so there is nothing to
      // protect by omitting it).
      writeAllowedToolNames: server.writeAllowedToolNames.join(", "),
      authMode: server.authMode,
      // Never populated — see this file's header. The names are surfaced in `statusMessage` instead,
      // so an operator can still see which variables are set.
      env: "",
      // The rest of the OAuth block is NOT secret (a client id travels in the authorization URL by
      // design, same as the store's own doc comment on this), so it round-trips the real stored
      // value — only `oauthClientSecret` stays blank, matching `env`.
      oauthProviderId: server.oauth.providerId ?? "",
      oauthGrant: server.oauth.grant ?? "",
      oauthClientId: server.oauth.clientId ?? "",
      oauthClientSecret: "",
      oauthScopes: server.oauth.scopes.join(" "),
      oauthTokenEnvName: server.oauth.tokenEnvName ?? "",
      // Read-only: drives the row's Connect button. `toWriteBody` never sends it.
      oauthStatus: server.oauth.status,
      // The store's `ExternalMcpOAuthView` does not carry a connection's own endpoints back —
      // `providerId` is enough to identify a registered one, and a connection with its own
      // endpoints has no other read model for them today. Left blank rather than guessed; an
      // operator editing a custom-endpoint connection re-enters them, the same disclosed gap
      // `env`/`oauthClientSecret` already accept for secret-shaped fields (this one isn't secret,
      // it just isn't surfaced yet — a future `oauthEndpoints` field on the view would close it).
      oauthAuthorizationEndpoint: "",
      oauthTokenEndpoint: "",
      oauthDeviceAuthorizationEndpoint: "",
      // Write-only, exactly like `oauthClientSecret`: the store seals it and no read model returns it,
      // so it always arrives blank and {@link toAccessTokenWriteBody} treats blank as "keep".
      accessToken: "",
      // A NAME, not a secret — round-trips the real stored value like `oauthTokenEnvName` does.
      accessTokenEnvName: server.accessTokenEnvName ?? "",
    },
    ...includeIfDefined("statusMessage", describeStoredCredentials({ server }, { locale })),
  };
}

/** The card's "what is stored" line: env variable NAMES and whether an access token is held — never
 *  a value. `undefined` when neither is stored, so the card shows no status line at all.
 *  @complexity O(n) in the env variable count. */
export function describeStoredCredentials({ server }: { server: AdminExternalMcpServer }, { locale = "en" }: { locale?: string } = {}): string | undefined {
  const parts = [
    ...(server.envNames.length > 0 ? [formatCredentialHints({ hints: server.envTokenHints, locale }) || `Credentials set: ${server.envNames.join(", ")}`] : []),
    ...(server.hasAccessToken ? [`${credentialText({ id: 'set', locale })}${server.accessTokenHint ? ` (${formatCredentialHint({ hint: server.accessTokenHint, locale })})` : ""}`] : []),
  ];
  return parts.length > 0 ? parts.join(" · ") : undefined;
}

/** The `static_env` access-token half of a save, or nothing for any other auth mode — the store only
 *  reads these for a `static_env` row. Both are omit-when-blank: a blank token means "keep the sealed
 *  one" (the `env` rule), and a blank variable name resolves to the stored name server-side either way,
 *  so omitting it keeps every other mode's write body byte-identical to before this field existed.
 *  @complexity O(1). */
export function toAccessTokenWriteBody(fields: Record<string, string>, _optional = {}): Pick<AdminExternalMcpServerInput, "accessToken" | "accessTokenEnvName"> {
  if (resolveExternalMcpEffectiveAuthMode(fields) !== "static_env") return {};
  return {
    ...(fieldOrEmpty(fields, "accessToken") === "" ? {} : { accessToken: fieldOrEmpty(fields, "accessToken") }),
    ...omitIfBlank("accessTokenEnvName", fieldOrEmpty(fields, "accessTokenEnvName")),
  };
}

/** `fields[key] ?? ""` as a named helper — same rationale as `MenuEditor.tsx`'s `orEmpty`:
 *  ESLint's cyclomatic-complexity rule counts each `??` as its own branch, and
 *  {@link toOAuthWriteBody}/{@link toWriteBody} each default many fields this way. Naming it moves
 *  the count out of both functions' own scope without changing what either produces — every field
 *  still falls back to the same `""` for the same absent value it did before. */
function fieldOrEmpty(fields: Record<string, string>, key: string): string {
  return fields[key] ?? "";
}

/** `value.trim() === "" ? {} : { [key]: value }` as a named helper. The store reads the PRESENCE
 *  of these keys (not just their value) to decide whether a save touched OAuth identity or a
 *  tri-state field like `env` — see {@link toOAuthWriteBody}'s own doc — so the omit-when-blank
 *  convention must stay byte-for-byte the same; this only moves each call site's ternary branch
 *  out of the caller's own complexity count. */
function omitIfBlank<K extends string>(key: K, value: string): { [P in K]?: string } {
  return (value.trim() === "" ? {} : { [key]: value }) as { [P in K]?: string };
}

/** `value === undefined ? {} : { [key]: value }` as a named helper — same rationale as
 *  {@link omitIfBlank}, for the two fields (`label`, `oauth`) whose tri-state is "was this
 *  argument passed at all", not "is this string blank". */
function includeIfDefined<K extends string, V>(key: K, value: V | undefined): { [P in K]?: V } {
  return (value === undefined ? {} : { [key]: value }) as { [P in K]?: V };
}

/** Builds the OAuth block for a save, or `undefined` when the draft's effective auth mode isn't
 *  `oauth` — matching the store's own `resolveOAuthFields`, which ignores the whole block outside
 *  that mode. `grant`/`clientId`/`scopes`/`tokenEnvName` are sent as-is: {@link toItem} round-trips
 *  their real stored value, so the store's own `firstTrimmed` precedence resolves them correctly
 *  whether or not the operator touched them. `providerId` and the three endpoint fields are
 *  omit-when-blank instead — the same convention `clientSecret` already uses — because the store
 *  reads their PRESENCE, not their value, to decide whether this save touched the connection's OAuth
 *  identity (`resolveOAuthEndpoints`). Endpoints are never round-tripped by {@link toItem} today, so
 *  sending them as an always-present blank string made every save look like an identity change and
 *  silently destroyed the stored token, refresh token, and DCR-minted client secret.
 *  @complexity O(1). */
function toOAuthWriteBody(fields: Record<string, string>): AdminExternalMcpOAuthInput | undefined {
  if (resolveExternalMcpEffectiveAuthMode(fields) !== "oauth") return undefined;
  return {
    ...omitIfBlank("providerId", fieldOrEmpty(fields, "oauthProviderId")),
    grant: fieldOrEmpty(fields, "oauthGrant"),
    clientId: fieldOrEmpty(fields, "oauthClientId"),
    scopes: fieldOrEmpty(fields, "oauthScopes"),
    tokenEnvName: fieldOrEmpty(fields, "oauthTokenEnvName"),
    ...omitIfBlank("authorizationEndpoint", fieldOrEmpty(fields, "oauthAuthorizationEndpoint")),
    ...omitIfBlank("tokenEndpoint", fieldOrEmpty(fields, "oauthTokenEndpoint")),
    ...omitIfBlank("deviceAuthorizationEndpoint", fieldOrEmpty(fields, "oauthDeviceAuthorizationEndpoint")),
    ...omitIfBlank("clientSecret", fieldOrEmpty(fields, "oauthClientSecret")),
  };
}

/**
 * Builds the write body from a field map, omitting `env`/`oauth.clientSecret` when blank.
 *
 * `command`/`url` are both always sent regardless of transport — harmless, since the store's own
 * `resolveTransportTarget` reads only the one that matches `transport` and ignores the other, and
 * sending both unconditionally is simpler than a transport-keyed omission that would buy nothing.
 *
 * @complexity O(1).
 * @overallScore 100
 */
function toWriteBody(fields: Record<string, string>, enabled: boolean, label?: string): AdminExternalMcpServerInput {
  const oauth = toOAuthWriteBody(fields);
  return {
    ...includeIfDefined("label", label),
    transport: fields.transport || "stdio",
    enabled,
    command: fieldOrEmpty(fields, "command"),
    url: fieldOrEmpty(fields, "url"),
    args: fieldOrEmpty(fields, "args"),
    allowedToolNames: fieldOrEmpty(fields, "allowedToolNames"),
    // Resent in full on every save, same as `allowedToolNames` just above — NOT tri-state like
    // `env` below, because the store always returns this list in the clear and the tab can always
    // resend it. The server's own C-006 check rejects a name here absent from `allowedToolNames`.
    writeAllowedToolNames: fieldOrEmpty(fields, "writeAllowedToolNames"),
    authMode: resolveExternalMcpEffectiveAuthMode(fields),
    // Blank means "untouched", never "clear" — see this file's header.
    ...omitIfBlank("env", fieldOrEmpty(fields, "env")),
    ...toAccessTokenWriteBody(fields),
    ...includeIfDefined("oauth", oauth),
  };
}

export interface ExternalMcpController {
  dependencies: SourceConfigDependencies<SourceConfigItem>;
  /** Set once any write succeeds — federation only re-reads the roster at daemon boot. */
  restartRequired: boolean;
}

/**
 * Wires `ExternalMcpTab` to Tovu's real `/mcp-servers` routes.
 *
 * The port is memoized behind a ref so the tab's own hooks see one stable object across renders;
 * `useWiredSourceConfigList` treats a new `dependencies` identity as a reason to refetch.
 *
 * @complexity O(n) per fetch in the configured server count.
 * @overallScore 100
 */
async function checkSavedServer({ item, server, locale, port }: { item: SourceConfigItem; server: AdminExternalMcpServer; locale: string; port: ExternalMcpPort }): Promise<SourceConfigItem> {
  let message = credentialText({ id: 'saved', locale });
  if (server.transport !== 'stdio' && server.enabled) {
    try { await port.probeExternalMcpServer(server.serverId); message = credentialText({ id: 'connected', locale }); }
    catch (err) { message = translateCredentialMessage({ message: describeApiError(err, credentialText({ id: 'unreachable', locale })), locale }); }
  }
  return { ...item, statusMessage: [item.statusMessage, message].filter(Boolean).join(' · ') };
}

/** Existing API contracts remain the owner; injection lets tests use fakes without module mocks. */
export type ExternalMcpPort = Pick<typeof api, "listExternalMcpServers" | "saveExternalMcpServer" | "deleteExternalMcpServer" | "probeExternalMcpServer">;

export function useExternalMcp(
  { port = api, useAdminLocaleHook = useAdminLocale }: { port?: ExternalMcpPort; useAdminLocaleHook?: () => string } = {},
  _optional: Record<string, never> = {},
): ExternalMcpController {
  const [restartRequired, setRestartRequired] = useState(false);
  // `updateSource` receives a PARTIAL patch, but the write route replaces the whole row, so the
  // last-known field values are kept here to merge against. Without this, toggling `enabled` would
  // blank out `command` and the allowlist.
  const lastKnown = useRef(new Map<string, SourceConfigItem>());
  // Serializes `updateSource` writes per id, through `useSerialWrites`' keyed lanes — see that
  // method's own doc for the race this closes.
  const writes = useSerialWrites();
  // Same bound translator `ExternalMcpToolPicker.tsx` uses for this dictionary (Phase 2C) — reused
  // here rather than re-resolving the locale a second way, so `testSource`'s unreachable-server
  // fallback below stays word-for-word identical to the picker's own copy in every locale, not just
  // English.
  // The credential-safety contract now owns probe fallback copy; other tab copy still uses
  // the same dictionary translator as the picker, with the injected locale resolved once.
  const locale = useAdminLocaleHook();
  const t = useCallback((key: string) => tExternalMcp({ locale: locale, key: key }), [locale]);

  const dependencies = useMemo<SourceConfigDependencies<SourceConfigItem>>(
    () => ({
      port: {
        async fetchSources() {
          const { servers } = await port.listExternalMcpServers();
          const items = servers.map(server => toItem(server, locale));
          lastKnown.current = new Map(items.map((item) => [item.id, item]));
          return items;
        },

        async addSource(input: AddSourceInput): Promise<AddSourceResult<SourceConfigItem>> {
          const serverId = (input.fields.id ?? "").trim();
          if (serverId === "") return { ok: false, message: t("An ID is required.") };
          // The write is a create-OR-replace PUT, so an id already on the list would silently
          // replace that server's command, tool allowlists and auth instead of adding a new one.
          if (lastKnown.current.has(serverId)) {
            return { ok: false, message: t("A server with this ID already exists. Edit that server instead.") };
          }
          // An untouched transport saves as STDIO; require a header token only for hosted rows.
          if (resolveExternalMcpEffectiveAuthMode(input.fields) === 'static_env' && resolveExternalMcpEffectiveTransport(input.fields) !== 'stdio') {
            const tokenIssue = credentialDraftError({ value: fieldOrEmpty(input.fields, 'accessToken') }, { locale, required: true });
            if (tokenIssue) return { ok: false, message: tokenIssue };
          }
          const oauthIdentityIssue = validateExternalMcpOAuthIdentity(input.fields, t);
          if (oauthIdentityIssue) return { ok: false, message: oauthIdentityIssue };
          try {
            const { server } = await port.saveExternalMcpServer(
              serverId,
              toWriteBody(input.fields, true, input.fields.label)
            );
            setRestartRequired(true);
            const item = toItem(server, locale);
            const checked = await checkSavedServer({ item, server, locale, port });
            lastKnown.current.set(item.id, checked);
            return { ok: true, source: checked };
          } catch (e) {
            return { ok: false, message: translateCredentialMessage({ message: describeApiError(e, t("That server could not be saved.")), locale }) };
          }
        },

        async removeSource(id: string) {
          try {
            await port.deleteExternalMcpServer(id);
            setRestartRequired(true);
            lastKnown.current.delete(id);
            return true;
          } catch {
            return false;
          }
        },

        /**
         * Runs the write behind whatever `updateSource` write for THIS SAME id is already in
         * flight (`writes.run(..., { key: id })`), so a second concurrent edit never reads
         * `lastKnown` until the first one has actually committed its own result there.
         *
         * The merge below is a read-then-write over `lastKnown` (see that ref's own doc), and
         * nothing else serializes two calls for the same id: `SourceConfigList` can fire a toggle
         * and a field-save close together (e.g. flipping "enabled" while a command edit is still
         * saving), and without this both reads see the SAME pre-write snapshot. Whichever write
         * then lands second wins outright — not merges — because it built its own full-row body
         * from a `previous` that never saw the first write's change, so the field the first write
         * touched (and the second's own patch never named) silently reverts the moment the second
         * write's response arrives. Keying the lane on `id` closes that: the second call's
         * `previous` read is delayed until the first call's `lastKnown.set` has actually run, so it
         * merges against the true current state instead of a stale one. Different ids are NOT
         * serialized against each other — they are independent rows with no shared merge base, and
         * each gets its own lane.
         */
        async updateSource(id: string, patch: SourceUpdateInput) {
          return writes.run({ task: async () => {
            const previous = lastKnown.current.get(id);
            const merged = mergeSourceUpdate(previous, patch);
            try {
              const { server } = await port.saveExternalMcpServer(id, toWriteBody(merged.fields, merged.enabled, merged.label));
              setRestartRequired(true);
              const item = toItem(server, locale);
              const changedToken = (merged.fields.accessToken ?? '') !== '';
              const checked = changedToken ? await checkSavedServer({ item, server, locale, port }) : item;
              lastKnown.current.set(item.id, checked);
              return checked;
            } catch (err) {
              if (!previous) return null;
              return { ...previous, statusMessage: translateCredentialMessage({ message: describeApiError(err, t('That server could not be saved.')), locale }) };
            }
          } }, { key: id });
        },

        /**
         * Wired to `probeExternalMcpServer` (C-007, outline §3.1 Source A / §3.5's D-5). Its only
         * effect is lighting up Jini's existing "Test" button — `useSourceConfigList.ts` derives
         * `capabilities.canTest` from `Boolean(port.testSource)`, so implementing this method is
         * what makes the button appear at all.
         *
         * `id` is `undefined` for the add-form's still-unsaved draft (Jini's generic "test before
         * save" case). The probe route addresses an already-persisted server by id, so there is
         * nothing to probe yet — this returns a failure rather than guessing at a URL/command the
         * operator has not saved.
         *
         * `SourceTestResult` cannot carry a tool list (`{ ok, message?, latencyMs? }`), so this is
         * a reachability check ONLY — it complements, and does not replace, the dedicated
         * `ExternalMcpToolPicker` (Phase 4), which reads `probeExternalMcpServer`'s full
         * `AdminRemoteToolSurfaceEntry[]` directly.
         *
         * The port's `draft` second parameter (unsaved field edits to test against, for an
         * already-persisted item) is deliberately not accepted: `probeExternalMcpServer` (C-007)
         * takes only a `serverId` path param and always connects using the server's LAST SAVED
         * `url`/`command`, so there is nothing here that could honor an edited-but-unsaved value —
         * testing an in-progress edit would require the probe route to accept a draft connection
         * target, which is out of this slice's scope.
         */
        async testSource(id: string | undefined): Promise<SourceTestResult> {
          if (id === undefined) {
            return { ok: false, message: t("Save this server before you can test it.") };
          }
          const startedAt = Date.now();
          try {
            const { tools } = await port.probeExternalMcpServer(id);
            return {
              ok: true,
              message: `${tools.length} tool${tools.length === 1 ? "" : "s"} advertised.`,
              latencyMs: Date.now() - startedAt,
            };
          } catch (e) {
            return { ok: false, message: translateCredentialMessage({ message: describeApiError(e, credentialText({ id: "unreachable", locale })), locale }) };
          }
        },
      },
    }),
    [t, writes, locale, port]
  );

  return { dependencies, restartRequired };
}

import { useEffect, useRef } from "react";

const phoneViewport = () => window.matchMedia("(max-width: 640px)").matches;

/** Host adapter for Jini's inline settings sidebar, rendered as a swipeable strip on phones.
 * Watch the shell's pressed state too: it can own the active tab before the URL is controlled.
 * Keep this in hooks so SettingsUi remains markup; upstream extraction is recorded in SURVEY.md.
 * `inline: "center"` (owner, 2026-10-07), not `"nearest"`: nearest stopped as soon as the active
 * tab touched the strip's edge, so its neighbour on that side sat cut mid-word ("nguage") and the
 * active tab itself hugged the edge. Centred, both neighbours show, and the strip still clamps at
 * its ends for the first and last tabs.
 */
export function useSettingsActiveTabScroll(
  { ready, tabId }: { ready: boolean; tabId: string | null },
  { isPhone = phoneViewport }: { isPhone?: () => boolean } = {},
) {
  const rootRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const strip = rootRef.current?.querySelector(".jini-tabbed-dialog-sidebar");
    if (!ready || !strip) return;
    const scrollActiveTab = () => {
      if (!isPhone()) return;
      strip.querySelector<HTMLElement>('.jini-tabbed-dialog-nav-item[aria-pressed="true"]')
        ?.scrollIntoView?.({ block: "nearest", inline: "center", behavior: "instant" });
    };
    scrollActiveTab();
    const observer = new MutationObserver(scrollActiveTab);
    observer.observe(strip, { subtree: true, attributes: true, attributeFilter: ["aria-pressed"] });
    window.addEventListener("resize", scrollActiveTab);
    return () => {
      observer.disconnect();
      window.removeEventListener("resize", scrollActiveTab);
    };
  }, [ready, tabId, isPhone]);

  return rootRef;
}

/** Local lifecycle writes and confirmation live in the controller, never in card markup. */
import { useCallback, useEffect, useRef, useState } from "react";
import { useInvalidate } from "@jini-ai/ui/fetch-query";
import { startVisibleInterval, type VisibilitySource, type IntervalTimers } from "@/lib/visible-interval";
import { describeApiError, type AdminLocalSiteAction, type AdminSitesSnapshot } from "@/lib/api";
import type { Translate } from "@jini-ai/ui/panel-kit";
import { KEYS, siteWriteErrorKey } from "../rules";
import type { SitesPort } from "./sites-port.hooks";

const nativeConfirm = (message: string) => window.confirm(message);
export const LOCAL_SITE_CONFIRM_KEYS = {
  trash: "Move this site to Trash? You can restore it later.",
  delete: "Permanently delete this site and all its data? This cannot be undone.",
  switch: "Switch now? Unsaved changes will be lost.",
};
type ConfirmableAction = keyof typeof LOCAL_SITE_CONFIRM_KEYS;

/** Whether an action asks the operator first (Trash, permanent delete, Switch now). */
function isConfirmable(action: AdminLocalSiteAction): action is ConfirmableAction {
  return action in LOCAL_SITE_CONFIRM_KEYS;
}

/** Whether the snapshot's capabilities let `action` run at all: Switch now needs `canSwitchNow`,
 *  every other action needs local management, and a permanent delete also needs its checkbox. */
function localActionAllowed(
  { action, canSwitchNow, enabled, deleteChecked }: { action: AdminLocalSiteAction; canSwitchNow: boolean; enabled: boolean; deleteChecked: boolean },
): boolean {
  if (action === "switch" ? !canSwitchNow : !enabled) return false;
  return action !== "delete" || deleteChecked;
}

/** Whether the host accepted Switch now and is restarting, rather than only saving the default. */
function restartAccepted(result: unknown): boolean {
  return (result as { restarting?: boolean } | undefined)?.restarting === true;
}

/** The operator-facing message for a failed lifecycle write: this feature's own copy for its codes,
 *  otherwise the shared `describeApiError` fallback. */
function localActionErrorMessage(failure: unknown, t: Translate): string {
  const key = siteWriteErrorKey(failure);
  if (key) return t(key);
  return describeApiError(failure instanceof Error ? failure : new Error("Request failed"), t("That request failed."));
}

/** DI confirms allow cancellation and double-click tests without mocking browser modules.
 * Restart refreshes use the live binding, stop after 60 seconds, and release on unmount.
 * @complexity O(1) state and work per tick; invalidation reuses the cached Sites read.
 */
export function useLocalSites(
  { port, snapshot, t }: { port: SitesPort; snapshot: AdminSitesSnapshot | undefined; t: Translate },
  { confirm = nativeConfirm, visibility = document, timers }: {
    /** Receives the translated message plus the action, so a modal can title and tone itself. */
    confirm?: (message: string, context: { action: ConfirmableAction }) => boolean | Promise<boolean>;
    /** Visibility and timer ports keep lifecycle polling testable without replacing modules. */
    visibility?: VisibilitySource;
    timers?: IntervalTimers;
  } = {},
) {
  const invalidate = useInvalidate();
  const [busyName, setBusyName] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [checked, setChecked] = useState<Record<string, boolean>>({});
  const [switchTarget, setSwitchTarget] = useState<{ name: string; deadline: number } | null>(null);
  const busy = useRef(false);
  const enabled = snapshot?.localManagementEnabled === true;
  const canSwitchNow = snapshot?.canSwitchNow === true;
  const activeSiteName = snapshot?.currentSite.name;
  const refresh = useCallback(() => invalidate({ key: KEYS.list }), [invalidate]);
  const starting = enabled && snapshot?.localSites?.some((site) => site.status === "starting") === true;
  // Idle hosts need no timer. Refresh only an unfinished start or accepted restart; broad
  // idle invalidation used to refetch shares and publish permissions every three seconds.
  useEffect(() => {
    if (switchTarget && activeSiteName === switchTarget.name) {
      setSwitchTarget(null);
      return;
    }
    if (!starting && !switchTarget) return;
    // Replace the slow poll while a restart is pending; a saved default alone is not completion.
    return startVisibleInterval(() => {
      if (switchTarget && Date.now() >= switchTarget.deadline) setSwitchTarget(null);
      refresh();
    }, switchTarget ? 300 : 3000, visibility, timers);
  }, [starting, switchTarget, activeSiteName, refresh, visibility, timers]);
  const run = useCallback(async (name: string, action: AdminLocalSiteAction) => {
    if (busy.current || !port.manageLocalSite) return;
    if (!localActionAllowed({ action, canSwitchNow, enabled, deleteChecked: checked[name] === true })) return;
    busy.current = true;
    setBusyName(name); setError(null);
    try {
      if (isConfirmable(action) && !(await confirm(t(LOCAL_SITE_CONFIRM_KEYS[action]), { action }))) return;
      const result = await port.manageLocalSite({ name, action, confirmed: true, checked: checked[name] === true });
      if (action === "switch" && restartAccepted(result)) setSwitchTarget({ name, deadline: Date.now() + 60_000 });
      else if (action === "switch") setError(t("This host could not switch now. The default is saved for the next launch."));
      refresh();
    } catch (failure) {
      setError(localActionErrorMessage(failure, t));
    }
    finally { busy.current = false; setBusyName(null); }
  }, [port, canSwitchNow, enabled, checked, confirm, t, refresh]);
  const toggleChecked = useCallback((id: string, value: boolean) => setChecked((current) => ({ ...current, [id]: value })), []);
  return { busyName, error, checked, toggleChecked, run };
}
export type LocalSitesController = ReturnType<typeof useLocalSites>;

import { useCallback, useEffect, useState } from "react";
import { useAsyncAction } from "@jini-ai/ui/panel-kit";
import { useInvalidate } from "@jini-ai/ui/fetch-query";
import { api, type SitesUserConfig, type SitesUserConfigPatch } from "@/lib/api";
import { KEYS } from "../rules";

/** Shared local settings effects stay here, including explicit sync-warning remedies. Saving
 * placement affects new DBs; the manual stopped-site mover applies it to existing databases.
 * Extra folders are a row list (add/remove per row, 2026-10-09 settings redesign); `roots`/`setRoots`
 * keep the one-per-line text view of the same list, and blank rows are dropped on save.
 * @complexity O(n) root strings; one API operation per action.
 */
export function useSitesConfig(_required = {}, { port = api }: { port?: Pick<typeof api, "getSitesConfig" | "setSitesConfig"> } = {}) {
  const [open, setOpen] = useState(false);
  const [config, setConfig] = useState<SitesUserConfig | null>(null);
  const [home, setHome] = useState("");
  const [rootList, setRootList] = useState<string[]>([]);
  // The row a click on "Add folder" just made, so the dialog can focus it; null otherwise.
  const [addedIndex, setAddedIndex] = useState<number | null>(null);
  const [databases, setDatabases] = useState<"inSite" | "appData">("inSite");
  const [loadError, setLoadError] = useState<string | null>(null);
  const invalidate = useInvalidate();
  const { saving, error, run } = useAsyncAction();
  const accept = useCallback((next: SitesUserConfig) => {
    setConfig(next); setHome(next.sitesHome); setRootList(next.siteRoots); setAddedIndex(null); setDatabases(next.databases);
  }, []);
  useEffect(() => {
    let active = true;
    void port.getSitesConfig().then((next) => { if (active) accept(next); }).catch((failure: unknown) => {
      if (active) setLoadError(failure instanceof Error ? failure.message : String(failure));
    });
    return () => { active = false; };
  }, [accept, port]);
  const change = useCallback((patch: SitesUserConfigPatch) => run({ action: async () => {
    accept(await port.setSitesConfig(patch)); setLoadError(null); invalidate({ key: KEYS.list });
  }, describeError: (failure) => failure instanceof Error ? failure.message : String(failure) }), [accept, port, run, invalidate]);
  const save = useCallback(() => change({ databases,
    ...(!config?.overrides.sitesHome ? { sitesHome: home } : {}),
    ...(!config?.overrides.siteRoots ? { siteRoots: rootList.map((root) => root.trim()).filter(Boolean) } : {}),
  }), [change, config, home, rootList, databases]);
  return { open, show: () => setOpen(true), close: () => setOpen(false), config, home, setHome,
    roots: rootList.join("\n"), setRoots: (text: string) => setRootList(text.split("\n")),
    rootList, addedIndex,
    setRootAt: (index: number, value: string) => setRootList((list) => list.map((root, at) => at === index ? value : root)),
    addRoot: () => { setAddedIndex(rootList.length); setRootList((list) => [...list, ""]); },
    removeRoot: (index: number) => { setAddedIndex(null); setRootList((list) => list.filter((_, at) => at !== index)); },
    databases, setDatabases, save, saving, error: error ?? loadError,
    useAppData: () => change({ databases: "appData" }),
    useLocalHome: () => { if (!config?.warning) return Promise.resolve(); return change({ sitesHome: config.warning.localHome }); },
  };
}

import type { DragEvent } from "react";

interface DropEntry {
  name: string; fullPath: string; isFile: boolean; isDirectory: boolean;
  file?(resolve: (file: File) => void, reject: (error: Error) => void): void;
  createReader?(): { readEntries(resolve: (entries: DropEntry[]) => void, reject: (error: Error) => void): void };
}
/** Thrown when a walk limit is hit before any SKILL.md showed up: the folder is not a skill, so it keeps the host's folder action. */
const NOT_A_SKILL = Symbol("not-a-skill");

/** Bounded browser directory walk; no host paths or desktop filesystem read permissions needed. */
async function collect(entries: readonly DropEntry[]) {
  const files: File[] = [], paths: string[] = [];
  let total = 0, visited = 0, sawSkill = false;
  const limit = (message: string) => sawSkill ? new Error(message) : NOT_A_SKILL;
  async function collectFile({ entry }: { entry: DropEntry }, _options = {}): Promise<void> {
    if (entry.name === "SKILL.md") sawSkill = true;
    const file = await new Promise<File>((resolve, reject) => entry.file!(resolve, reject));
    total += file.size;
    if (files.length >= 256 || total > 8 * 1024 * 1024) throw limit("Choose up to 256 files, 8 MiB total.");
    files.push(file); paths.push(entry.fullPath.replace(/^\/+/, ""));
  }
  async function walk(entry: DropEntry, depth: number): Promise<void> {
    if (++visited > 512 || depth > 16) throw limit("Skill folder has too many entries or is too deep.");
    if (entry.isFile) {
      await collectFile({ entry });
      return;
    }
    if (!entry.isDirectory) return;
    const reader = entry.createReader!();
    for (;;) {
      const batch = await new Promise<DropEntry[]>((resolve, reject) => reader.readEntries(resolve, reject));
      if (!batch.length) break;
      for (const child of batch) await walk(child, depth + 1);
    }
  }
  for (const entry of entries) await walk(entry, 0);
  return { files, paths };
}

/** Capture before ordinary attachment expansion. Non-skill folders retain the host's folder action. */
export function captureSkillDrop(
  { event, proposeFiles, fallback }: {
    event: DragEvent<HTMLElement>;
    proposeFiles: (files: readonly File[], paths?: readonly string[]) => Promise<void>;
    fallback: (event: DragEvent<HTMLElement>) => void;
  },
  { onError = () => {} }: { onError?: (message: string) => void } = {},
): boolean {
  // Snapshot native items synchronously: browsers protect DataTransfer after the event returns.
  const items = Array.from(event.dataTransfer.items ?? []).filter(item => item.kind === "file").map(item => ({ file: item.getAsFile(), entry: item.webkitGetAsEntry?.() as DropEntry | null }));
  const entries = items.flatMap(item => item.entry ? [item.entry] : []);
  const files = Array.from(event.dataTransfer.files ?? []);
  const hasFolder = entries.some(entry => entry.isDirectory);
  // Folders are captured in browsers too: left to Jini, a folder expands into an attachment upload
  // (owner 2026-10-27: "You can attach at most 10 files"). A skill folder is proposed for install;
  // any other folder goes to the host's folder action (path text, or the paste hint).
  // Every file-only drop must reach the same content-aware uploader as the picker. Capturing ZIPs
  // by suffix here bypasses that classifier and hijacks plugin and ordinary chat attachments.
  if (!hasFolder) return false;
  event.preventDefault(); event.stopPropagation();
  const saved = { ...event, preventDefault: () => {}, stopPropagation: () => {}, dataTransfer: { ...event.dataTransfer, files, types: Array.from(event.dataTransfer.types ?? []), items: items.map(item => ({ kind: "file", getAsFile: () => item.file, webkitGetAsEntry: () => item.entry })) } } as unknown as DragEvent<HTMLElement>;
  void collect(entries).then(({ files: leaves, paths }) => {
    if (leaves.some(file => file.name === "SKILL.md")) return proposeFiles(leaves, paths);
    fallback(saved);
  }).catch(error => error === NOT_A_SKILL ? fallback(saved) : onError(error instanceof Error ? error.message : "Could not read skill folder."));
  return true;
}

import { useEffect, useRef, type MouseEvent } from "react";
import { useFocusTrap } from "../../hooks/use-focus-trap.hooks";
import type { useSkillInstall } from "./use-skill-install.hooks";

/** Sibling dialog behavior: Escape, contained Tab navigation and focus return. */
export function useSkillConfirmation(active: boolean, onCancel: () => void) {
  const dialogRef = useRef<HTMLDivElement>(null);
  useFocusTrap(dialogRef, active);
  useEffect(() => {
    if (!active) return;
    const previous = document.activeElement as HTMLElement | null;
    dialogRef.current?.querySelector<HTMLButtonElement>("button")?.focus();
    return () => { previous?.focus(); };
  }, [active]);
  useEffect(() => {
    if (!active) return;
    function onKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") { event.preventDefault(); onCancel(); }
    }
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [active, onCancel]);
  function onDialogClick(event: MouseEvent<HTMLDivElement>) { event.stopPropagation(); }
  return { dialogRef, onDialogClick };
}

export function useSkillInstallConfirmation(install: ReturnType<typeof useSkillInstall>) {
  const confirmation = useSkillConfirmation(install.pending !== null, install.cancel);
  return {
    ...confirmation,
    source: install.pending && "githubUrl" in install.pending ? install.pending.githubUrl : "Uploaded skill files",
    onConfirm: () => { void install.confirm(); },
  };
}

import { useCallback as useQueryFetchCallback } from "react";
import { useFetchQuery } from "@jini-ai/ui/fetch-query";
import { useState } from "react";
import type { Translate } from "@jini-ai/ui/panel-kit";
import type { PackageFilesModalProps } from "../plugins/PackageFilesModal";
import { packageFilesViewState, type PackageFilesRead } from "../plugins/rules";
import { listSkillFiles, type InstalledSkill, type SkillFiles } from "./api";

interface SkillFilesDependencies {
  readonly toolId: string | null;
  readonly read: (toolId: string) => Promise<SkillFiles>;
  readonly t: Translate;
}

const identity: Translate = key => key;

/** Mirrors the plugin files hook's stale-read guard; defaults to the skill's instructions. */
export function useSkillFiles({ toolId, read, t }: SkillFilesDependencies) {
  const [selection, setSelection] = useState<{ toolId: string | null; path: string } | null>(null);
  const queryFetch = useQueryFetchCallback(async () => {
    try { return await read(toolId!); }
    catch (error) { throw new Error(error instanceof Error ? error.message : "Could not load skill files."); }
  }, [read, toolId]);
  const query = useFetchQuery({ key: ["skills", "files", toolId ?? ""], fetch: queryFetch }, { enabled: toolId !== null, staleTime: 0 });
  const skillCopy: Translate = key => {
    if (key === "Loading package files…") return "Loading skill files…";
    if (key === "No files to show for this plugin.") return "No files to show for this skill.";
    return t(key);
  };
  const loaded: PackageFilesRead | null = query.data ? { listing: query.data, error: null } : query.error ? { listing: null, error: query.error.message } : null;
  const selectedPath = selection?.toolId === toolId ? selection.path : "SKILL.md";
  const validPath = loaded?.listing?.files.some(file => file.relativePath === selectedPath) ? selectedPath : "SKILL.md";
  return {
    ...packageFilesViewState(loaded, validPath, skillCopy),
    selectFile: (path: string) => setSelection({ toolId, path }),
    t: skillCopy,
  };
}

/** The shared modal accepts these props directly; no Skills-specific modal component needed. */
export function useSkillFilesModal(skill: InstalledSkill | null, onClose: () => void): PackageFilesModalProps | null {
  const files = useSkillFiles({ toolId: skill?.toolId ?? null, read: listSkillFiles, t: identity });
  if (!skill) return null;
  return {
    title: `${skill.name} skill files`,
    subtitle: "Read-only view of this skill's files; nothing runs from this screen.",
    files: files.files, selectedFile: files.selectedFile, onSelectFile: files.selectFile,
    status: files.status, listNotice: files.listNotice,
    handlePrefix: "skill-file", t: files.t, onClose,
  };
}

import { useCallback, useRef, useState } from "react";
import { installSkill, type SkillInstallPayload } from "./api";
import { prepareSkillUpload } from "./skill-upload";

/** Holds an upload until the user confirms. A superseded read cannot install an older drop. */
export function useSkillInstall(onInstalled?: () => void | Promise<void>) {
  const [pending, setPending] = useState<SkillInstallPayload | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const generation = useRef(0);
  const confirmLock = useRef(false);
  const propose = useCallback((payload: SkillInstallPayload) => { ++generation.current; setError(null); setPending(payload); }, []);
  const proposeFiles = useCallback(async (files: readonly File[], paths?: readonly string[]) => {
    const current = ++generation.current;
    setError(null);
    try { const payload = await prepareSkillUpload({ files }, { paths }); if (current === generation.current) setPending(payload); }
    catch (e) { if (current === generation.current) setError(e instanceof Error ? e.message : "Could not read skill."); }
  }, []);
  const cancel = useCallback(() => { if (!confirmLock.current) { ++generation.current; setPending(null); setError(null); } }, []);
  const confirm = useCallback(async () => {
    if (!pending || confirmLock.current) return;
    confirmLock.current = true;
    const current = generation.current;
    setBusy(true); setError(null);
    try { await installSkill(pending); if (current === generation.current) setPending(null); await onInstalled?.(); }
    catch (e) { setError(e instanceof Error ? e.message : "Could not install skill."); }
    finally { confirmLock.current = false; setBusy(false); }
  }, [pending, onInstalled]);
  const fail = useCallback((message: string) => setError(message), []);
  return { pending, busy, error, propose, proposeFiles, cancel, confirm, fail };
}

import { useEffect, useLayoutEffect, useRef, useState, type KeyboardEvent } from "react";
import type { RowMenuProps } from "@jini-ai/admin/react";

type MenuState = ReturnType<NonNullable<RowMenuProps["useRowMenu"]>>;

/**
 * Host-owned menu behavior for published admin versions whose popup destination is fixed.
 * Matches RowMenu's public hook seam, including viewport positioning and roving focus.
 * @param itemCount - Number of actions rendered by the menu.
 * @returns Menu state, DOM refs and keyboard/pointer actions; listeners exist only while open.
 */
export function useTaxonomyRowMenu({ itemCount }: { itemCount: number }): MenuState {
  const [open, setOpen] = useState(false);
  const [position, setPosition] = useState<MenuState["position"]>(null);
  const [activeIndex, setActiveIndex] = useState(0);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const itemRefs = useRef<(HTMLButtonElement | null)[]>([]);
  itemRefs.current = itemRefs.current.slice(0, itemCount);

  /** Close explicitly; Escape and selection return focus, outside clicks and Tab leave it. */
  function close(focus: "trigger" | "leave") {
    setOpen(false);
    setPosition(null);
    if (focus === "trigger") triggerRef.current?.focus();
  }

  /** Open with the first or last action selected, according to the trigger key. */
  function openAt(index: number) {
    setActiveIndex(index);
    setOpen(true);
  }

  useLayoutEffect(() => {
    if (!open) return;
    /** Measure the portal after layout and follow anchor movement on scroll/resize. */
    function reposition() {
      const trigger = triggerRef.current;
      if (!trigger) return;
      const rect = trigger.getBoundingClientRect();
      const height = menuRef.current?.offsetHeight ?? 0;
      const width = menuRef.current?.offsetWidth ?? 0;
      const fitsBelow = window.innerHeight - rect.bottom >= height + 8;
      const placement = fitsBelow || rect.top < height + 8 ? "below" : "above";
      setPosition({
        top: placement === "below" ? rect.bottom + 4 : rect.top - 4,
        left: Math.min(Math.max(8, rect.right - width), window.innerWidth - width - 8),
        placement,
      });
    }
    reposition();
    window.addEventListener("scroll", reposition, true);
    window.addEventListener("resize", reposition);
    return () => {
      window.removeEventListener("scroll", reposition, true);
      window.removeEventListener("resize", reposition);
    };
  }, [open]);

  useEffect(() => {
    if (!open) return;
    /** Treat both the portal and its trigger as inside, regardless of their DOM ancestry. */
    function onMouseDown(event: MouseEvent) {
      const target = event.target as Node;
      if (menuRef.current?.contains(target) || triggerRef.current?.contains(target)) return;
      close("leave");
    }
    document.addEventListener("mousedown", onMouseDown);
    return () => document.removeEventListener("mousedown", onMouseDown);
  }, [open]);

  useEffect(() => {
    if (open) itemRefs.current[activeIndex]?.focus();
  }, [open, activeIndex]);

  /** Toggle by pointer without stealing focus back when closing the same trigger. */
  function onTriggerClick() {
    if (open) close("leave");
    else openAt(0);
  }

  /** Arrow keys open with a predictable initial focused action. */
  function onTriggerKeyDown(event: KeyboardEvent<HTMLButtonElement>) {
    if (event.key !== "ArrowDown" && event.key !== "ArrowUp") return;
    event.preventDefault();
    openAt(event.key === "ArrowDown" ? 0 : itemCount - 1);
  }

  /** Keep menu navigation local; Tab follows the browser's ordinary focus order. */
  function onMenuKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    // A pointer can focus another setting while the popup stays open. Navigate from that
    // actual row, and focus explicitly even if the next index matches the last keyboard index.
    const focusedIndex = itemRefs.current.indexOf(menuRef.current?.ownerDocument.activeElement as HTMLButtonElement);
    const index = focusedIndex === -1 ? activeIndex : focusedIndex;
    function focusItem(nextIndex: number) {
      setActiveIndex(nextIndex);
      itemRefs.current[nextIndex]?.focus();
    }
    switch (event.key) {
      case "ArrowDown":
        event.preventDefault();
        focusItem((index + 1) % itemCount);
        break;
      case "ArrowUp":
        event.preventDefault();
        focusItem((index - 1 + itemCount) % itemCount);
        break;
      case "Home":
        event.preventDefault();
        focusItem(0);
        break;
      case "End":
        event.preventDefault();
        focusItem(itemCount - 1);
        break;
      case "Escape":
        event.preventDefault();
        close("trigger");
        break;
      case "Tab":
        close("leave");
        break;
    }
  }

  /** Close before handing the selected action back to its owner. */
  function selectItem({ onSelect }: { onSelect: () => void }) {
    close("trigger");
    onSelect();
  }

  return { open, position, triggerRef, menuRef, itemRefs, onTriggerClick, onTriggerKeyDown, onMenuKeyDown, selectItem };
}

import { agentHandle } from "@jini-ai/agentic";
import { buildAgentListHandles } from "@jini-ai/agentic";
import { SuggestInput } from "@jini-ai/ui/admin-widgets";
import { useId } from "react";
import type { AdminTaxonomyWithTerms } from "@/lib/api";
import { useWiredTermPicker, type TermPickerController } from "./hooks/use-term-picker.hooks";
import { useTermListReveal } from "./hooks/use-term-list-reveal.hooks";

/**
 * @file The Categories & Tags box the post, page and collection-entry editors mount (design-spec.md
 * §1.6) — markup only. The boxes start ticked for the terms the content holds, and Save makes it hold
 * exactly the ticked ones; state, loads and the save live in `hooks/use-term-picker.hooks.ts`.
 *
 * Each row also takes a typed name — ticks the matching term or creates it — when the admin may
 * create terms (see the hook's header).
 *
 * A long row folds: it shows a few terms (ticked first) with a "See more" that reveals up to 100,
 * plus a search box past 100 — see `TermChecklist` below (owner, 2026-10-22).
 *
 * Mount it only for content that exists (a saved post/page/entry has an id to tag).
 */
export function TermPicker(props: {
  /** `post`, `page`, or a collection's content-type key. */
  contentType: string;
  contentId: string;
  /** Dependency injection seam for tests — the same convention `@jini-ai/ui`'s `CustomSelect` uses
   *  for `useCustomSelect`. Defaulted to the real hook, so production callers pass nothing. */
  useTermPickerHook?: typeof useWiredTermPicker;
}) {
  const useTermPickerHook = props.useTermPickerHook ?? useWiredTermPicker;
  const picker = useTermPickerHook({
    contentType: props.contentType,
    contentId: props.contentId,
  });
  const { taxonomies, hidden, subject, selected, toggle, loading, dirty, saving, message, error, save, t } = picker;

  if (hidden) return null;

  // Term ids are database row ids — globally unique across every taxonomy, not just within one —
  // so one flat handle list across all taxonomies is correct.
  // Keyed by id, not render position: a row shows only some of its terms ("See more"), and a
  // term's handle must not change with what else is on screen.
  const termIds = taxonomies.flatMap(({ terms }) => terms.map((term) => term.id));
  const termHandles = buildAgentListHandles({ prefix: "term-picker-term", ids: termIds });
  const termHandleById = new Map(termIds.map((termId, index) => [termId, termHandles[index]!]));
  const taxonomyIds = taxonomies.map(({ taxonomy }) => taxonomy.id);
  const addInputHandles = buildAgentListHandles({ prefix: "term-picker-new-term", ids: taxonomyIds });
  const addTriggerHandles = buildAgentListHandles({ prefix: "term-picker-open-new-term", ids: taxonomyIds });
  const addButtonHandles = buildAgentListHandles({ prefix: "term-picker-add-term", ids: taxonomyIds });
  const moreHandles = buildAgentListHandles({ prefix: "term-picker-more", ids: taxonomyIds });
  const searchHandles = buildAgentListHandles({ prefix: "term-picker-search", ids: taxonomyIds });

  return (
    <section className="card term-picker">
      <h3 className="card-title">{t("Categories & Tags")}</h3>
      <p className="card-lead">
        {loading ? t("Loading categories & tags…") : t("Tick the categories and tags that apply, then save.")}
      </p>
      {/* One row per taxonomy: its name on the left, its terms on the right. The `<fieldset>` is
          kept for the group's accessible name (its `<legend>`); `styles.css`'s `.term-picker-group`
          strips its browser border and floats the legend so it sits in the row like any label. */}
      <div className="term-picker-groups">
        {taxonomies.map(({ taxonomy, terms }, groupIndex) => {
          const id = taxonomy.id;
          const showInput = picker.showAddInput(id);
          const suggestions = picker.suggestions(id);
          const createError = picker.createError(id);
          return (
            <fieldset key={id} className="term-picker-group">
              <legend className="field-label">{taxonomy.name}</legend>
              <div className="term-picker-body">
                {terms.length === 0 && !showInput ? <p className="field-hint">{t("No terms yet.")}</p> : null}
                {terms.length > 0 ? (
                  <TermChecklist
                    taxonomy={taxonomy}
                    terms={terms}
                    picker={picker}
                    handles={{
                      term: (termId) => termHandleById.get(termId)!,
                      more: moreHandles[groupIndex]!,
                      search: searchHandles[groupIndex]!,
                    }}
                  />
                ) : null}
                {picker.showAddTrigger(id) ? (
                  <button
                    type="button"
                    className="btn-ghost term-picker-add-trigger"
                    onClick={() => picker.setAddOpen(id, true)}
                    {...agentHandle({ handle: addTriggerHandles[groupIndex]! }, {
                      role: "button",
                      label: `Open the box for adding a new "${taxonomy.name}" term to this ${subject}`,
                    })}
                  >
                    {t("+ Add term")}
                  </button>
                ) : null}
                {showInput ? (
                  // Not a `<form>`: the box can sit inside an editor's own form; the hook's key
                  // handler stops Enter from submitting it.
                  <span className="term-picker-add">
                    {/* Our own suggestion list, not a native `<datalist>`: Chrome on macOS draws that
                        as a dark bubble and adds a large ▼ to the box, unstyleable (owner,
                        2026-10-10: "why does the dropdown look so funny?"). Picking a suggestion
                        ticks that term right away. */}
                    <SuggestInput
                      aria-label={t("Term name")}
                      placeholder={t("Type a name, then press Enter")}
                      value={picker.newTermName(id)}
                      suggestions={suggestions}
                      onPick={(name) => picker.pickSuggestion(id, name)}
                      disabled={loading}
                      onValueChange={(value) => picker.setNewTermName(id, value)}
                      onKeyDown={(e) => picker.onNewTermKeyDown(id, e)}
                      agentHandle={addInputHandles[groupIndex]!}
                      agentLabel={`A "${taxonomy.name}" term name to tag this ${subject} with — an existing one is ticked, a new one is created then ticked; press Enter`}
                    />
                    <button
                      type="button"
                      className="btn-secondary"
                      onClick={() => void picker.addTerm(id)}
                      disabled={loading || picker.creating(id) || !picker.newTermName(id).trim()}
                      {...agentHandle({ handle: addButtonHandles[groupIndex]! }, {
                        role: "button",
                        label: `Tick the typed "${taxonomy.name}" term, creating it if it does not exist yet`,
                      })}
                    >
                      {picker.creating(id) ? t("Saving…") : t("Add term")}
                    </button>
                  </span>
                ) : null}
                {createError ? (
                  <span className="save-error" role="alert">
                    {createError}
                  </span>
                ) : null}
              </div>
            </fieldset>
          );
        })}
      </div>
      {/* `term-picker-actions` is a spacing-only hook layered on `.editor-actions`, same pattern
          as `FormEditor.tsx`'s `.form-actions`: `.editor-actions` sets direction/gap/alignment but
          deliberately no outer margin, and this row follows the taxonomy rows with nothing else
          separating them. Scoped here rather than added to `.editor-actions` itself, which is
          shared with screens where a blanket top margin would be wrong. */}
      <span className="editor-actions term-picker-actions">
        <button
          type="button"
          className="btn-primary"
          onClick={save}
          disabled={saving || !dirty}
          {...agentHandle({ handle: "term-picker-save" }, {
            role: "button",
            label: `Save this ${subject}'s categories and tags as checked above`,
          })}
        >
          {saving ? t("Saving…") : t("Save categories & tags")}
        </button>
        {message ? <span className="save-ok">{message}</span> : null}
        {error ? <span className="save-error">{error}</span> : null}
      </span>
    </section>
  );
}

/**
 * One taxonomy row's checkboxes. Shows the first few, with ticked terms first; "See more" reveals
 * up to 100 and "Show less" folds them back; past 100 a search box finds any term (owner,
 * 2026-10-22: "looking at all this up front is a lot"). What shows is `rules.ts`'s `termListView`.
 */
function TermChecklist(props: {
  taxonomy: AdminTaxonomyWithTerms["taxonomy"];
  terms: AdminTaxonomyWithTerms["terms"];
  picker: TermPickerController;
  handles: { term: (termId: string) => string; more: string; search: string };
}) {
  const { taxonomy, terms, picker, handles } = props;
  const { selected, toggle, loading, subject, t } = picker;
  const reveal = useTermListReveal({ terms, selected, loading });
  const listId = useId();
  return (
    <>
      {reveal.searchable ? (
        <input
          type="search"
          className="term-picker-search"
          aria-label={t("Search terms")}
          aria-controls={listId}
          placeholder={t("Search terms")}
          autoComplete="off"
          value={reveal.query}
          onChange={(event) => reveal.setQuery(event.target.value)}
          {...agentHandle({ handle: handles.search }, {
            role: "field",
            label: `Filter the "${taxonomy.name}" terms shown for this ${subject} by name`,
          })}
        />
      ) : null}
      <div id={listId} className="term-picker-terms">
        {reveal.shown.map((term) => (
          <label key={term.id} className="form-checkbox-field">
            <input
              type="checkbox"
              checked={selected.has(term.id)}
              disabled={loading}
              onChange={() => toggle(term.id)}
              {...agentHandle({ handle: handles.term(term.id) }, {
                role: "checkbox",
                label: `Tag this ${subject} with the "${taxonomy.name}" term "${term.name}"`,
              })}
            />
            {term.name}
          </label>
        ))}
      </div>
      {reveal.canToggle ? (
        <button
          type="button"
          className="link-button term-picker-more"
          aria-expanded={reveal.expanded}
          aria-controls={listId}
          onClick={reveal.toggleExpanded}
          {...agentHandle({ handle: handles.more }, {
            role: "button",
            label: `Show more or fewer of the "${taxonomy.name}" terms`,
          })}
        >
          {reveal.expanded ? t("Show less") : t("See more")}
        </button>
      ) : null}
    </>
  );
}

import { themeExplorePreviewMode, useThemeExplorePreview, type ThemeExplorePreviewMode } from "./hooks/use-theme-explore-preview.hooks";
import { WiredThemePreviewReloadButton } from "./ThemePreviewReloadButton";
import { CodeView, CodeWrapToggle } from "../../components/CodeView/CodeView";
import { useCodeWrap } from "../../components/CodeView/use-code-wrap.hooks";
import { type KeyboardEvent, type MouseEvent, type RefObject, type SyntheticEvent } from "react";
import { ConfirmDialog, RowMenu } from "@jini-ai/admin/react";
import { agentHandle } from "@jini-ai/agentic";
import { Icon, Toast } from "@jini-ai/ui";

import { InfoTip } from "@jini-ai/ui/admin-widgets";
import { resolveTabBarTabIndex, useTabBarKeyboard } from "@jini-ai/ui/tab-strip";
import { useDevicePreviewDevice, usePreviewPaneWidth, type DevicePreviewDevice } from "../../components/DevicePreview/DevicePreview.hooks";
import { DevicePreviewFrame } from "../../components/DevicePreview/DevicePreviewFrame";
import { DevicePreviewToggle } from "../../components/DevicePreview/DevicePreviewToggle";
import { siteUrl } from "../../lib/site-url";
import { navigate } from "../../lib/router";
import type { Translate } from "@jini-ai/ui/panel-kit";
import { splitOnPlaceholders } from "@jini-ai/ui/panel-kit";
import { buildAgentListHandles } from "@jini-ai/agentic";
import {
  canResetThemeFile,
  dispatchPublishToggle,
  isThemeFileModified,
  publishToggleTipLabel,
  readOnlyReason,
  selectedFileLabel,
  selectedFilePublishState,
  themeExploreHtmlMode,
  useWiredThemeExplore,
  type ThemeExploreDetail,
  type ThemeExploreFile,
  type ThemeFileGroup,
  type ThemeExplorePublishState,
  type ThemeExploreView,
} from "./hooks/use-theme-explore.hooks";
import { useThemeExploreFullscreen } from "./ThemeExplore.hooks";
import { useWiredThemeExploreTheme } from "./hooks/use-theme-explore-theme.hooks";
import { useThemeExploreFileGroups, type ThemeExploreFileGroupsController } from "./hooks/use-theme-explore-file-groups.hooks";

/**
 * @file Explore — edit any theme, active or not, and see it rendered.
 *
 * The screen the copy-not-inherit model needed. Every installed theme is a COPY of an original that
 * still exists untouched in the catalog, so editing here is always safe in the one way that matters:
 * the thing you forked from is still on disk, byte-identical, to reset back to. That is what the
 * banner says, and it is why ordinary editing here needs no confirmation at all.
 *
 * Reset and Delete are the exceptions, and both confirm: restoring a file to its original overwrites
 * the working copy with no backup, and removing a file outright is even more final — this repo keeps
 * no theme-file revision history, so a delete cannot be recovered from at all, not even by re-copying
 * a catalog original the way Reset does. These are the only two actions on this screen that can
 * destroy work (2026-08-29: Delete added to Copy/Rename's ⋮ menu, owner ask).
 *
 * The preview is an `<iframe src>` pointed at the SITE server, not `srcDoc`. A rendered theme page
 * references `/theme-assets/<id>/css/...`, which only the site server serves — a `srcDoc` iframe
 * resolves those relative URLs against the admin's own origin and every stylesheet 404s. Pointing
 * `src` at the site origin makes the preview load exactly the bytes a visitor would get, which is
 * the entire claim this screen makes. Both pages AND partials render this way now — a partial's own
 * route (`/theme-explore/{id}/partial/{partialId}`, `theme-page-preview.ts`) wraps it in a minimal
 * host document that pulls in the same tokens/stylesheet a full page does (2026-08-11: partials used
 * to have no preview at all — "why wouldn't partials show up? They should ... as long as you have the
 * CSS" was correct, so now they do).
 *
 * The device-width control and scaled frame are the shared `components/DevicePreview` pieces
 * `PageEditor.tsx` and `PostEditor.tsx` also render — same widths, same scale-to-fit mechanism, just
 * pointed at a real `src` URL instead of `SrcDocSandbox`'s `srcDoc`.
 *
 * This component's own render body is deliberately thin. Every conditional block that does not need
 * a value straight out of `useThemeExploreHook`'s controller has been pulled out to a top-level
 * function or component below (`ThemeExploreDirectionsNotice`, `ThemeExploreFileList`,
 * `ThemeExploreToolbarButtons`, `ThemeExplorePreviewControls`, `ThemeExplorePublishToggle`,
 * `ThemeExploreMainPane`, `ThemeExploreFullscreenDialog`) — `apps/admin`'s complexity-drift check (`npm run
 * check:admin-complexity-drift`) scores a component's OWN cyclomatic/cognitive complexity from every
 * ternary/`&&`/`.map()`-with-branching directly inside its JSX, and this component's markup used to
 * carry roughly a dozen of those inline, landing at 27/29 against a 9/9 ceiling. Each extraction below
 * is a genuinely TOP-LEVEL function, not a `useCallback` or nested closure — a nested closure is still
 * scored as its own unit by ESLint's `complexity`/`sonarjs/cognitive-complexity` rules, but the
 * separate drift tool this repo also gates on aggregates a closure DECLARED INSIDE a component back
 * into that component's own count, so only moving the code to actual module scope lowers both.
 *
 * The `device`/`fullscreen` state below and the preview pane's own width measurement
 * (`usePreviewPaneWidth`, `components/DevicePreview`) deliberately stay OUTSIDE `useThemeExploreHook`'s
 * controller, unlike everything else this screen reads — see each one's own comment for why. Both
 * are pure view chrome with nothing to inject (constraint: a hook with no I/O gets no port), same as
 * `Posts.tsx`'s own local `updatedSort` state. `device`/`fullscreen` additionally CANNOT move into
 * the injected controller without breaking real interactivity: `ThemeExplore.unit.test.tsx` swaps in
 * a fully static controller fake (spies for every setter, no re-render), which is exactly right for
 * data/mutation state asserted by "was the setter called with X" — but the device-width and
 * fullscreen-dialog tests assert REAL DOM behavior (`aria-pressed` flipping, the dialog's `open`
 * attribute, focus returning to the trigger) that only a live `useState` can drive under that fake.
 */
export interface ThemeExploreProps {
  /** Theme id from `?theme=`. */
  themeId: string;
  /**
   * Page id from `?page=`, when the caller named one — the page to open ON, instead of the theme's
   * index. `features/pages/Pages.tsx`'s "Theme Pages" tab is the only thing that sets it today: its
   * rows link straight into this screen, focused on the row's own page.
   *
   * Optional, and a value naming no page of this theme is not an error — see
   * `use-theme-explore.hooks.ts`'s `initialSelectedPath` for the fallback.
   */
  pageId?: string;
  /**
   * File to open on, from `?file=` — the file's own full relative path (e.g.
   * `render/pages/404.html`), not a bare id. Takes priority over `pageId`; see
   * `use-theme-explore.hooks.ts`'s `ThemeExploreOptions.fileId` for the full contract, including why
   * this screen writes it back into the address bar on every selection.
   */
  fileId?: string;
  /** DI seam for tests — same convention as `Themes.tsx`'s `useThemesHook`. */
  useThemeExploreHook?: typeof useWiredThemeExplore;
  useThemeExplorePreviewHook?: typeof useThemeExplorePreview;
}

/**
 * Whether to label the save chord ⌘ or Ctrl.
 *
 * Reads `navigator.platform` despite it being deprecated, because the replacement
 * (`navigator.userAgentData.platform`) is not in Safari or Firefox — the exact browsers where
 * getting this wrong is most likely. Wrong answer costs a slightly off tooltip, so the deprecated
 * property with a guard beats a feature-detection ladder. Guarded for jsdom/SSR, where `navigator`
 * may be absent entirely.
 */
function isApplePlatform(): boolean {
  if (typeof navigator === "undefined") return false;
  return /mac|iphone|ipad|ipod/i.test(navigator.platform ?? "");
}

const VIEWS: ReadonlyArray<{ key: ThemeExploreView; label: string }> = [
  { key: "preview", label: "Preview" },
  { key: "html", label: "HTML" },
];

/** {@link VIEWS} carrying the `id` that `TabBar.hooks.tsx`'s WAI-ARIA tabs helpers key on, so this
 *  hand-rolled `role="tablist"` row gets the same arrow/Home/End keys and roving tab stop `TabBar`
 *  has (a35ce9f12) without becoming a `<TabBar>` — same treatment `PageEditor.tsx`'s identical
 *  `.segmented` view row takes. `label` is the untranslated key; only `id` is read here. */
const VIEW_TABS = VIEWS.map((entry) => ({ ...entry, id: entry.key }));

/**
 * The Preview tab's "nothing to show" message when no file is selected.
 *
 * 2026-08-17: `previewSrcFor` now returns a real URL for every file kind (page/partial/template
 * through their own routes, everything else — CSS/JS/JSON/`other`/assets, readable or not — via the
 * raw `/theme-assets/` URL), so `previewSrc === null` only happens for the `!file` case: nothing
 * selected yet. This message is purely the empty-selection state now, not a "nothing to render for
 * this file type" state.
 *
 * @complexity O(1).
 */
function themeExplorePreviewNotice(t: Translate): string {
  return t("Select a file to preview.");
}

/**
 * Whether the Save button should be offered at all for the selected file — `undefined` (nothing
 * selected yet) defaults to showing it, matching the pre-existing behavior before per-file
 * editability existed.
 *
 * @complexity O(1).
 */
function canSaveSelectedFile(file: ThemeExploreFile | undefined): boolean {
  return file === undefined || file.editable;
}

/**
 * The HTML tab's body for the selected file — binary (no source, Preview tab instead), unloaded (the
 * file's text is not in the buffer), read-only (script/`other`, visible but not saveable), or a normal
 * editable textarea. `themeExploreHtmlMode` (`use-theme-explore.hooks.ts`) picks which.
 *
 * @complexity O(1) — renders exactly one of four fixed shapes.
 */
function ThemeExploreHtmlPane({
  file,
  source,
  sourceLoaded,
  setSource,
  t,
}: {
  file: ThemeExploreFile | undefined;
  source: string;
  sourceLoaded: boolean;
  setSource: (value: string) => void;
  t: Translate;
}) {
  const mode = themeExploreHtmlMode(file, sourceLoaded);

  if (mode === "binary") {
    // Never rendered into a textarea: reading a PNG as UTF-8 gives mojibake, and saving that back
    // would truly corrupt it. The Preview tab shows the real bytes.
    return (
      <div className="notice">
        {t("This is a binary file, so it has no editable source. Use the Preview tab to view it.")}
      </div>
    );
  }

  if (mode === "unloaded") {
    // The open file's text is not in the buffer: its read is in flight or failed (a file past the
    // 1 MB text-read limit), or a reset returned no text. Whatever the buffer holds is not this file,
    // so it is neither shown nor editable. The error toast carries the reason.
    return (
      <textarea
        className="page-html-source"
        value=""
        readOnly
        spellCheck={false}
        aria-label={t("Theme file source (read-only)")}
      />
    );
  }

  if (mode === "readonly") {
    // Readable but not editable — an `other`-group file (2026-08-29: `script` moved to the editable
    // branch below, see `readOnlyReason`'s own doc). Shown as source (unlike the binary case above),
    // but `readOnly` and paired with a visible reason: an editable-looking textarea next to a Save
    // button that can never fire would be worse than either showing nothing or being honest about
    // why.
    return (
      <>
        <div className="notice">{t(readOnlyReason())}</div>
        <textarea
          className="page-html-source"
          value={source}
          readOnly
          spellCheck={false}
          aria-label={t("Theme file source (read-only)")}
        />
      </>
    );
  }

  return (
    <textarea
      className="page-html-source"
      value={source}
      spellCheck={false}
      onChange={(e) => setSource(e.target.value)}
      aria-label={t("Theme file source")}
    />
  );
}

/**
 * Enter commits the inline rename, Escape abandons it. Blur (clicking away) also abandons it rather
 * than committing — unlike Finder/Explorer's commit-on-blur, this sidesteps the whole double-fire
 * class of bug a commit-on-blur design has to guard against (Enter firing the rename, then the
 * input's own removal from the DOM firing a second blur-triggered attempt): a deliberate Enter, or
 * the ⋮ menu's Rename item, are the two ways to actually commit, and both are equally fast for this
 * screen's stated use case (typing a new name and pressing Enter).
 *
 * @complexity O(1).
 */
function handleFileRowRenameKeyDown(
  e: KeyboardEvent<HTMLInputElement>,
  actions: { commitRename: () => void; cancelRename: () => void }
): void {
  if (e.key === "Enter") {
    e.preventDefault();
    actions.commitRename();
  } else if (e.key === "Escape") {
    e.preventDefault();
    actions.cancelRename();
  }
}

/**
 * The file list's modified marker: a dot beside a file whose bytes differ from its catalog original
 * ({@link isThemeFileModified}), nothing for any other file. `role="img"` with an `aria-label` gives
 * the dot an accessible name, so the signal is not colour alone; `title` shows sighted users the same
 * meaning on hover. Rendered as a sibling of the filename button, not inside it, so the button's
 * ellipsis truncation cannot clip it.
 *
 * @complexity O(1).
 */
function ThemeExploreModifiedMarker({ file, t }: { file: ThemeExploreFile; t: Translate }) {
  if (!isThemeFileModified(file)) return null;
  return (
    <span
      className="theme-explore-file-modified"
      role="img"
      aria-label={t("Modified")}
      title={t("Modified from the original")}
    />
  );
}

/**
 * One file chip in the picker tray (a sidebar row until 2026-10-11): the filename control (or its
 * inline-rename replacement) plus the ⋮ overflow menu — 2026-08-11 owner ask (Copy/Rename).
 *
 * `title={file.path}` is the FULL relative path (e.g. `pages/blog-post.html`), not just `file.label`
 * — two files that render the same LABEL under different groups (or, before now, before an ellipsis
 * fix landed, two long names that both got clipped to the same visible prefix) had no way to tell
 * which was which without this. CSS-only per the owner's own instruction ("if CSS can handle that
 * without us having to do tooltips and all that, do it") — this `title` attribute plus
 * `.theme-explore-file-row button:not(.row-menu-trigger) { overflow: hidden; text-overflow: ellipsis;
 * white-space: nowrap; }` (`styles.css`) is the entire truncation implementation, deliberately with
 * no character cap in code: the chip's own `max-width` (CSS) decides where the ellipsis falls.
 *
 * @complexity O(1) per row — the list's own O(n) iteration lives in the caller's `.map()`.
 */
function ThemeExploreFileRow({
  file,
  selected,
  select,
  renamingPath,
  renameDraft,
  setRenameDraft,
  startRename,
  cancelRename,
  commitRename,
  copyingPath,
  copyFile,
  openDeleteConfirm,
  agentBase,
  t,
}: {
  file: ThemeExploreFile;
  selected: string | null;
  select: (path: string) => void;
  renamingPath: string | null;
  renameDraft: string;
  setRenameDraft: (value: string) => void;
  startRename: (path: string) => void;
  cancelRename: () => void;
  commitRename: () => void;
  copyingPath: string | null;
  copyFile: (path: string) => Promise<void>;
  /** Opens the delete confirmation for this row — see `ThemeExplore`'s own `deleteTarget`/
   *  `ConfirmDialog` for the confirmation this defers to, and `use-theme-explore.hooks.ts`'s
   *  `openDeleteConfirm` for the client-side pre-check (a locked file surfaces a toast instead of
   *  opening the dialog, same shape `startRename` already uses). */
  openDeleteConfirm: (path: string) => void;
  /** This row's own distinct handle base — computed once, across every file in every group, by
   *  `ThemeExploreFileList` (via `buildAgentListHandles`); see `Users.tsx`'s
   *  `UserRowProps.agentBase` for why a per-instance uniqueness search does not work here. Paths
   *  are globally unique across groups, same reasoning `Taxonomy.tsx`'s `termHandles` documents for
   *  its own flat, cross-group id list. */
  agentBase: string;
  t: Translate;
}) {
  const isSelected = selected === file.path;

  return (
    <li className={isSelected ? "theme-explore-file-row is-active" : "theme-explore-file-row"}>
      {renamingPath === file.path ? (
        <input
          className="theme-explore-rename-input"
          value={renameDraft}
          autoFocus
          onChange={(e) => setRenameDraft(e.target.value)}
          onKeyDown={(e) => handleFileRowRenameKeyDown(e, { commitRename, cancelRename })}
          onBlur={cancelRename}
          aria-label={t("New name for {file}").replace("{file}", file.label)}
        />
      ) : (
        <button
          type="button"
          className={isSelected ? "is-active" : undefined}
          aria-current={isSelected ? "true" : undefined}
          onClick={() => select(file.path)}
          onDoubleClick={() => startRename(file.path)}
          title={file.path}
        >
          {file.label}
        </button>
      )}
      <ThemeExploreModifiedMarker file={file} t={t} />
      {/* Copy is unconditional — see the hook's own `copyFile` doc comment for why duplicating bytes
          carries none of the risk editing does. Rename and Delete are always offered too: a LOCKED
          file (pages/index.html, theme.json, tokens.json, or any script/`other`-group file — see
          `IDENTITY_LOCKED_GROUPS`) still shows both items, but selecting one surfaces the refusal as
          a toast (`ThemeExplore`'s own `error` Toast below) instead of opening the inline editor or
          the delete confirmation — `RowMenu` has no built-in disabled-item affordance to hang a
          reason off, and a greyed-out item would explain nothing anyway (owner, 2026-08-11: "I like
          the fact that we got the error ... it should be a toast"). Delete additionally opens a
          confirmation dialog rather than acting immediately (2026-08-29 ask) — see `ThemeExplore`'s
          own delete `ConfirmDialog` for why that pause, unlike Rename's, is unconditional whenever
          the file IS eligible: deleting is the one operation here with no undo at all. */}
      <RowMenu
        triggerLabel={t("More actions for {file}").replace("{file}", file.label)}
        agentHandle={`${agentBase}-menu`}
        items={[
          {
            key: "copy",
            label: copyingPath === file.path ? t("Copying…") : t("Copy"),
            onSelect: () => void copyFile(file.path),
          },
          {
            key: "rename",
            label: t("Rename"),
            onSelect: () => startRename(file.path),
          },
          {
            key: "delete",
            label: t("Delete"),
            tone: "danger",
            onSelect: () => openDeleteConfirm(file.path),
          },
        ]}
      />
    </li>
  );
}

/**
 * The picker's group tabs (Pages, Partials, Styles, ...), one per non-empty group, each with its file
 * count and a dot when any file in it is modified — the per-file dots are only on screen for the
 * group that is showing, so the tab carries the signal for the others. A real ARIA tablist with the
 * same arrow-key handling as the Preview/HTML tabs below it (`useTabBarKeyboard`).
 *
 * @complexity O(g) for the fixed group count.
 */
function ThemeExploreFileGroupTabs({ groups, t }: { groups: ThemeExploreFileGroupsController; t: Translate }) {
  const { tabs, activeGroup, chooseGroup } = groups;
  const activeId = activeGroup ?? "";
  const { onKeyDown } = useTabBarKeyboard({ tabs, activeId, onChange: (id) => chooseGroup(id as ThemeFileGroup) });
  return (
    <div className="theme-explore-groups" role="tablist" aria-label={t("File groups")} onKeyDown={onKeyDown}>
      {tabs.map((tab) => (
        <button
          key={tab.key}
          type="button"
          role="tab"
          id={`theme-explore-group-${tab.key}`}
          aria-selected={tab.key === activeGroup}
          aria-controls="theme-explore-files-panel"
          className={tab.key === activeGroup ? "theme-explore-group is-active" : "theme-explore-group"}
          tabIndex={resolveTabBarTabIndex({ tabs, activeId, tab })}
          onClick={() => chooseGroup(tab.key)}
          {...agentHandle({ handle: `theme-explore-group-${tab.key}` }, { role: "button", label: `Show this theme's ${tab.label} files` })}
        >
          {t(tab.label)}
          <span className="theme-explore-group-count">{tab.count}</span>
          {tab.modified ? <span className="theme-explore-group-modified" aria-hidden="true" /> : null}
        </button>
      ))}
    </div>
  );
}

/**
 * "Show all (N)" / "Show fewer" under a group longer than the collapsed chip limit (assets, mostly);
 * nothing for a short group.
 *
 * @complexity O(1).
 */
function ThemeExploreShowAllToggle({ groups, t }: { groups: ThemeExploreFileGroupsController; t: Translate }) {
  if (!groups.collapsible) return null;
  return (
    <button
      type="button"
      className="theme-explore-files-more"
      aria-expanded={groups.expanded}
      aria-controls="theme-explore-files-panel"
      onClick={groups.toggleExpanded}
    >
      {groups.expanded ? t("Show fewer") : t("Show all ({count})").replace("{count}", String(groups.groupCount))}
    </button>
  );
}

/**
 * The file picker tray above the preview (owner, 2026-10-11: "the file list that's on the left, make
 * that up top ... it's way too small right now when the assistant chat is open"). Group tabs on top,
 * the active group's files as wrapping chips below; which group shows and whether a long one is
 * collapsed is `useThemeExploreFileGroups`'s job. Groups keep their old order, most-edited first
 * (assets last: there are many of them and they are the ones an author is least likely to be
 * looking for). A real nested file tree is a separate component a theme's editable surface (~20
 * entries, two folders deep) does not need.
 *
 * It used to be a 190px sidebar whose `<nav>` was absolutely positioned inside an empty grid cell so
 * it could borrow the preview column's height and scroll internally. That trick is gone with the
 * column: the tray is in normal flow with its own height, so it has no scroller of its own and the
 * page scrolls past it (the old inner scroller trapped the wheel at its bottom edge).
 *
 * Extracted to top level, not inline in `ThemeExplore`'s own JSX, for the complexity-drift reason this
 * file's own header comment documents; each chip's own rendering is `ThemeExploreFileRow`.
 *
 * @complexity O(n) for `n` files: handle building, the group filter and the chip render are each one pass.
 */
function ThemeExploreFileList({
  files,
  selected,
  select,
  renamingPath,
  renameDraft,
  setRenameDraft,
  startRename,
  cancelRename,
  commitRename,
  copyingPath,
  copyFile,
  openDeleteConfirm,
  t,
}: {
  files: ThemeExploreFile[];
  selected: string | null;
  select: (path: string) => void;
  renamingPath: string | null;
  renameDraft: string;
  setRenameDraft: (value: string) => void;
  startRename: (path: string) => void;
  cancelRename: () => void;
  commitRename: () => void;
  copyingPath: string | null;
  copyFile: (path: string) => Promise<void>;
  openDeleteConfirm: (path: string) => void;
  t: Translate;
}) {
  // File paths are globally unique across every group (a theme's editable surface is a flat set of
  // relative paths, just displayed grouped by kind), so they disambiguate one row's menu from
  // another's regardless of which group renders it — same reasoning `Taxonomy.tsx`'s `termHandles`
  // documents for its own flat, cross-group id list. Computed once here, over ALL files before the
  // group filter, so a path's handle never depends on which group tab is showing.
  const fileMenuHandles = buildAgentListHandles({ prefix: "theme-explore-file", ids: files.map((file) => file.path) }
  );
  const fileMenuHandleByPath = new Map(files.map((file, index) => [file.path, fileMenuHandles[index]!]));
  const groups = useThemeExploreFileGroups({ files, highlightedPath: selected });
  return (
    <nav className="theme-explore-files" aria-label={t("Theme files")}>
      <ThemeExploreFileGroupTabs groups={groups} t={t} />
      <div
        id="theme-explore-files-panel"
        role="tabpanel"
        aria-labelledby={groups.activeGroup ? `theme-explore-group-${groups.activeGroup}` : undefined}
        className="theme-explore-files-panel"
      >
        <ul className="theme-explore-file-chips">
          {groups.visibleFiles.map((file) => (
            <ThemeExploreFileRow
              key={file.path}
              file={file}
              selected={selected}
              select={select}
              renamingPath={renamingPath}
              renameDraft={renameDraft}
              setRenameDraft={setRenameDraft}
              startRename={startRename}
              cancelRename={cancelRename}
              commitRename={commitRename}
              copyingPath={copyingPath}
              copyFile={copyFile}
              openDeleteConfirm={openDeleteConfirm}
              agentBase={fileMenuHandleByPath.get(file.path)!}
              t={t}
            />
          ))}
        </ul>
        <ThemeExploreShowAllToggle groups={groups} t={t} />
      </div>
    </nav>
  );
}

/**
 * The no-original warning — the only case with nothing to fall back to if an edit goes wrong.
 * Deliberately NOT folded into `ThemeExploreCopyTip` below even though both start from the same
 * `hasOriginal` check: this is an actionable limitation ("edits here cannot be reset"), not
 * reassurance, so it stays a full, un-collapsed `.notice` rather than being tucked into a tooltip
 * an operator might not open before they start editing.
 *
 * @complexity O(1).
 */
function ThemeExploreDirectionsNotice({
  detail,
  savingOriginal,
  saveOriginal,
  t,
}: {
  detail: ThemeExploreDetail;
  savingOriginal: boolean;
  saveOriginal: () => Promise<void>;
  t: Translate;
}) {
  if (detail.hasOriginal) return null;
  // The action saves the theme's CURRENT files as its hidden original (owner 2026-10-08: "hidden away
  // somewhere where it can't be touched ... then you can just reload each template page from the
  // original") — not a visible copy. No confirm: it overwrites nothing.
  return (
    <div className="notice warning theme-explore-no-original">
      <span>{t("This theme has no stored original, so nothing can be reset.")}</span>
      <span className="theme-explore-no-original-action">
        <button
          type="button"
          className="btn-secondary"
          disabled={savingOriginal}
          aria-busy={savingOriginal}
          onClick={() => void saveOriginal()}
          {...agentHandle(
            { handle: "theme-explore-save-original" },
            { role: "button", label: "Save this theme's current files as its stored original, so Reset can restore from it" }
          )}
        >
          {savingOriginal ? t("Saving…") : t("Save as original")}
        </button>
      </span>
    </div>
  );
}

/**
 * The "you're editing your own copy" reassurance, collapsed to a single line with an `InfoTip`
 * carrying the explanation (owner feedback, 2026-08-11 — see the JSX comment above this screen's
 * `.page-header` for the full quote and the space-reclaiming reason it now renders in the header's
 * actions column instead of as its own full-width block). Deliberately NOT the words "child theme"
 * in either the visible line or the tooltip — there is no runtime relationship between this theme
 * and the one it came from, and calling it a child would teach that changing the original still
 * feeds into this one, which it does not.
 *
 * Reuses `InfoTip` (`@jini-ai/ui/admin-widgets`) rather than a second bespoke tooltip — it already
 * opens on hover AND focus and is keyboard-reachable (`tabIndex={0}` + `aria-label`), which is the
 * actual accessibility bar here: the native `title` attribute was rejected for this exact component
 * already (see `InfoTip`'s own doc), and touch devices can't hover at all.
 *
 * (The tooltip used to append a "Copied from X vY." lineage sentence; that metadata only ever came
 * from the theme marketplace, deleted 2026-10-04.)
 *
 * @complexity O(1).
 */
function ThemeExploreCopyTip({
  detail,
  t,
}: {
  detail: ThemeExploreDetail;
  t: Translate;
}) {
  if (!detail.hasOriginal) return null;
  return (
    <p className="theme-explore-copy-tip">
      {t("You're editing your own copy.")}
      <InfoTip
        label={t(
          "An untouched original is kept separately, so you can change anything here without losing what you started from."
        )}
      />
    </p>
  );
}

/**
 * The "this theme is not loading" error banner — `null` when the theme's own `status` is `"valid"`.
 * Extracted to top level for the complexity-drift reason this file's own header comment documents;
 * one guard clause here is one fewer ternary scored against `ThemeExplore` itself.
 *
 * @complexity O(1).
 */
function ThemeExploreStatusNotice({
  detail,
  t,
}: {
  detail: ThemeExploreDetail;
  t: Translate;
}) {
  if (detail.status === "valid") return null;
  return (
    <div className="notice error">
      {t("This theme is not loading:")} {detail.errors.join("; ")}
    </div>
  );
}

/**
 * The page-URL-change warning `ConfirmDialog`'s body — pulled out mainly so the two optional-chain
 * reads of `pageRenameWarning` (only ever non-null while this dialog is open) are scored against a
 * function of their own rather than `ThemeExplore`'s, per this file's own header comment.
 *
 * @complexity O(1).
 */
function PageRenameWarningBody({
  pageRenameWarning,
  t,
}: {
  pageRenameWarning: { path: string; name: string } | null;
  t: Translate;
}) {
  // One sentence, not three concatenated fragments (`t("Renaming")` + a `<code>` + `t("to")`
  // + …): each fragment word DID have a per-locale translation, but the fixed English word order
  // around the two `<code>` boundaries can't be reordered for a verb-final language — Japanese's
  // own "に" (to) is a postposition that belongs AFTER the target name, not between "Renaming" and
  // it, so the old fragment order was ungrammatical there regardless of the words being correct.
  // `splitOnPlaceholders` keeps the `<code>` elements as real React nodes while the key itself
  // carries a full, reorderable sentence per locale.
  const [before, between, after] = splitOnPlaceholders({ template: t(
      "Renaming {file} to {name} changes its public URL. Anything already linking to it directly will need updating.",
    ), tokens: ["{file}", "{name}"] }
  );
  return (
    <p>
      {before}
      <code>{pageRenameWarning?.path}</code>
      {between}
      <code>{pageRenameWarning?.name}</code>
      {after}
    </p>
  );
}

/**
 * The delete confirmation `ConfirmDialog`'s body — same "name the exact target" shape
 * {@link PageRenameWarningBody} and the Reset dialog's own body use, for the same reason: a
 * destructive prompt should never be ambiguous about what it acts on. Pulled out to a top level
 * function for the same complexity-drift reason this file's own header comment documents.
 *
 * @complexity O(1).
 */
function DeleteFileWarningBody({ deleteTarget, t }: { deleteTarget: string | null; t: Translate }) {
  // One whole sentence with a `{file}` placeholder — see `PageRenameWarningBody`'s comment for why
  // this replaced two fragments split around the `<code>` element.
  const [before, after] = splitOnPlaceholders({ template: t("Are you sure you want to delete {file}? This permanently removes the file. There is no way to get it back."), tokens: ["{file}"] }
  );
  return (
    <p>
      {before}
      <code>{deleteTarget}</code>
      {/* Deliberately NOT the literal phrase "cannot be undone" — the Reset dialog above already
          owns that exact wording, and both dialogs' body markup renders unconditionally regardless
          of `open` (`ConfirmDialog`'s own behavior), so identical phrasing across two simultaneously-
          mounted dialogs would make `getByText` ambiguous for either one. Same meaning, distinct
          wording — see `ThemeExplore.unit.test.tsx`'s "delete confirmation" describe block. */}
      {after}
    </p>
  );
}

/**
 * The Reset-file `ConfirmDialog`'s body — same "name the exact target" shape as
 * {@link PageRenameWarningBody} and {@link DeleteFileWarningBody}, pulled out to a top-level
 * function to match them (this one used to stay inline, since it only had one `<code>` node, but
 * the `splitOnPlaceholders` call reads better named than nested in JSX).
 *
 * @complexity O(1).
 */
function ResetFileWarningBody({ selected, t }: { selected: string | null; t: Translate }) {
  const [before, after] = splitOnPlaceholders({ template: t(
      "This replaces {file} with the version from the original theme. Any changes you have made to this file will be lost, and this cannot be undone.",
    ), tokens: ["{file}"] }
  );
  return (
    <p>
      {before}
      <code>{selected}</code>
      {after}
    </p>
  );
}

/**
 * Save button label: filename-qualified whenever a file is selected ("Save about.html"), plain
 * ("Save") when nothing is (matches {@link canSaveSelectedFile}'s own `undefined`-defaults-to-shown
 * behavior). See {@link ThemeExploreToolbarButtons}'s own doc comment for why the label carries the
 * filename at all. A top-level if-chain rather than the nested nested-ternary this replaced
 * (`saving ? … : dirty ? … : …`) — both for the complexity-drift reason this file's own header
 * comment documents, and because sonarjs' cognitive-complexity scoring penalizes NESTED ternaries
 * more heavily than sequential early returns at the same depth.
 *
 * @complexity O(1).
 */
function themeExploreSaveLabel(
  state: { saving: boolean; dirty: boolean; file: ThemeExploreFile | undefined },
  t: Translate
): string {
  if (state.saving) return t("Saving…");
  if (!state.dirty) return t("Saved");
  return state.file ? `${t("Save")} ${state.file.label}` : t("Save");
}

/** Reset button label — same filename-qualified shape as {@link themeExploreSaveLabel}, for the same
 *  reason. @complexity O(1). */
function themeExploreResetLabel(
  state: { resetting: boolean; file: ThemeExploreFile },
  t: Translate
): string {
  // Reset only renders for a file `canResetThemeFile` accepted, so there is always a file to name.
  if (state.resetting) return t("Resetting…");
  return `${t("Reset")} ${state.file.label}`;
}

/**
 * The outer toolbar's Save/Reset pair — 2026-08-11 toolbar restructure (owner-approved), matching
 * `PageEditor.tsx`'s `[← Pages] [Published ▾] [Save] [Delete]` shape: `← All themes` outline/secondary
 * (a plain back arrow at the header's far left since 2026-10-11),
 * Save filled, Reset red-outline-destructive, all in one row above the file list/editor instead of
 * docked to the Preview/HTML tab row below (`.theme-explore-toolbar-actions`, further down this file).
 *
 * Both buttons are labelled with the FILE's own name ("Save about.html", "Reset about.html"), not left
 * bare — the one thing that keeps this move honest. On Pages, Save saves THE PAGE and Delete deletes
 * THE PAGE, so a page-level toolbar reads correctly by itself; here Save saves the SELECTED FILE and
 * Reset resets the SELECTED FILE, and a bare "Save"/"Reset" sitting in the page-level row could read
 * as acting on the whole theme — an operator with edits open in `about.html` who sees an unqualified
 * "Save" in the header could reasonably believe everything they have touched just landed. Naming the
 * file in the label is the chosen fix over the alternative the brief also allowed (visually binding
 * the pair to the editor pane instead) — a label reads correctly from a screenshot, a screen reader's
 * accessible-name announcement, or a glance from across the room, none of which a purely spatial
 * grouping communicates on its own.
 *
 * Extracted to top level for the complexity-drift reason this file's own header comment documents;
 * the label text itself is further delegated to {@link themeExploreSaveLabel}/
 * {@link themeExploreResetLabel} so this component's own body is just two guarded buttons.
 *
 * @complexity O(1).
 */
function ThemeExploreToolbarButtons({
  selectedFile,
  resetting,
  openResetConfirm,
  dirty,
  saving,
  save,
  t,
}: {
  selectedFile: ThemeExploreFile | undefined;
  resetting: boolean;
  openResetConfirm: () => void;
  dirty: boolean;
  saving: boolean;
  save: () => Promise<void>;
  t: Translate;
}) {
  return (
    <>
      {/* Absent, not disabled, for a read-only file — a greyed-out button invites "why can't I?",
          where absence just means the option does not apply to this file. `dirty` can never become
          true for a read-only file (its textarea has no `onChange`), so this is belt-and-suspenders. */}
      {canSaveSelectedFile(selectedFile) ? (
        <button
          className="btn-primary"
          disabled={!dirty || saving}
          onClick={() => void save()}
          title={isApplePlatform() ? t("Save (⌘S)") : t("Save (Ctrl+S)")}
        >
          {themeExploreSaveLabel({ saving, dirty, file: selectedFile }, t)}
        </button>
      ) : null}
      {/* Hidden entirely, not disabled, when the file has no original to restore from, or when its
          bytes still match that original (2026-09-12 owner decision: a reset would change nothing) —
          same reasoning as Save's own absence above. See `canResetThemeFile`. Reset stays reachable
          for a read-only file, though: it can only ever write back the file's ORIGINAL bytes, never
          operator-authored content, so "read-only" here means "cannot be AUTHORED from this screen,"
          not "cannot be restored" — the restriction Save enforces has no bearing on what Reset does. */}
      {canResetThemeFile(selectedFile) ? (
        <button
          type="button"
          className="btn-danger"
          disabled={resetting}
          onClick={openResetConfirm}
          title={t("Restore this file to the original theme's version")}
        >
          {themeExploreResetLabel({ resetting, file: selectedFile }, t)}
        </button>
      ) : null}
    </>
  );
}

/**
 * The device-width segmented control plus the fullscreen trigger — only ever rendered while the
 * Preview tab is active. Extracted to top level for the complexity-drift reason this file's own
 * header comment documents: `ThemeExplore`'s own JSX now only decides WHETHER to show this
 * (`view === "preview"`), not what is inside it.
 *
 * @complexity O(1).
 */
function ThemeExplorePreviewControls({
  device,
  setDevice,
  previewSrc,
  fullscreenTriggerRef,
  setFullscreen,
  t,
}: {
  device: DevicePreviewDevice;
  setDevice: (value: DevicePreviewDevice) => void;
  previewSrc: string | null;
  fullscreenTriggerRef: RefObject<HTMLButtonElement | null>;
  setFullscreen: (value: boolean) => void;
  t: Translate;
}) {
  return (
    <>
      <DevicePreviewToggle device={device} setDevice={setDevice} t={t} />
      <WiredThemePreviewReloadButton disabled={previewSrc === null} />
      <button
        type="button"
        ref={fullscreenTriggerRef}
        className="theme-explore-fullscreen-trigger"
        onClick={() => setFullscreen(true)}
        disabled={previewSrc === null}
        aria-label={t("View preview fullscreen")}
      >
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true">
          <path d="M9 4H4v5M15 4h5v5M9 20H4v-5M15 20h5v-5" />
        </svg>
      </button>
    </>
  );
}

/**
 * The toolbar's right-hand controls for the active tab: the device/reload/fullscreen group while
 * Preview renders a page, the Wrap toggle while Preview shows a data/style/script file as code
 * (2026-10-10 — a device width means nothing for JSON, see `themeExplorePreviewMode`), and nothing on
 * the HTML tab. Top level for the complexity-drift reason this file's header comment documents.
 *
 * @complexity O(1).
 */
function ThemeExploreToolbarActions({
  view,
  previewMode,
  wrap,
  toggleWrap,
  controls,
  t,
}: {
  view: ThemeExploreView;
  previewMode: ThemeExplorePreviewMode;
  wrap: boolean;
  toggleWrap: () => void;
  controls: Omit<Parameters<typeof ThemeExplorePreviewControls>[0], "t">;
  t: Translate;
}) {
  if (view !== "preview") return null;
  if (previewMode === "code") {
    return <CodeWrapToggle wrap={wrap} onToggle={toggleWrap} t={t} agentHandleId="theme-explore-wrap-toggle" className="btn-secondary" />;
  }
  return <ThemeExplorePreviewControls {...controls} t={t} />;
}

/**
 * The publish toggle for the currently SELECTED page — 2026-08-30 owner ask: a static theme's public
 * routing used to be pure file presence (`isStandaloneThemePage`, `theme.ts`), with no way to take a
 * page down short of moving its file out of `render/pages/` entirely (the `_unpublished/` folder hack
 * this feature replaces). Sits on the toolbar's FIRST row, immediately right of the Preview/HTML tabs
 * (`ThemeExplore`'s own `.theme-explore-toolbar-start` wrapper) — a same-day restyle of what first
 * shipped as its own second row below the toolbar with a two-button Off/Published segmented control:
 * "Can the publish just be a toggle rather than the tab. Toggle is just way smaller... it will be a
 * toggle, a green toggle, Apple style" (owner, verbatim).
 *
 * Renders for every file {@link selectedFilePublishState} returns non-`null` for, in one of two
 * shapes:
 * - `"toggle"` — a real candidate page: an ENABLED switch; `published` both reflects and (via
 *   `setPagePublished`) controls the live publish state.
 * - `"locked"` — a page that exists but can never be independently toggled (`index`/`404`/a declared
 *   template shell, see {@link lockedPublishReason}): a DISABLED switch fixed to whichever position
 *   is actually true, with its reason in the ⓘ tooltip (owner, 2026-10-11: it used to be visible
 *   text beside the switch; the row is now just "Publish [switch] ⓘ"). PRESENT, not absent — the previous "no publish
 *   state, so show nothing" behavior made the control silently vanish for these pages exactly the
 *   same way it correctly vanishes for a stylesheet, and cost real operator confusion (see
 *   {@link selectedFilePublishState}'s own doc).
 *
 * `role="switch"`/`aria-checked`, not the old segmented control's `role="group"` of two
 * `aria-pressed` buttons — one control now represents one boolean, matching the shape the WAI-ARIA
 * switch pattern is actually for. State is never color-only: the knob's own POSITION (left/right) is
 * an independent, shape-based signal a colour-blind reader still sees without needing to resolve the
 * track's hue, the same "distinct shapes, not one shape recolored" reasoning
 * `.deployment-step-marker-done`'s own CSS comment gives for pairing its green fill with a checkmark
 * glyph rather than relying on the fill alone.
 *
 * An `InfoTip` (reused the same way {@link ThemeExploreCopyTip} does — see that component's own doc
 * for why the native `title` attribute was rejected here too) sits right after the switch. A locked
 * switch's tip is its reason; a live switch's tip (`publishToggleTipLabel`) explains what determines
 * whether a page is reachable at its own URL, and that a page is published BY DEFAULT until the
 * first page on a theme is toggled off (owner ask, 2026-08-30) — not the reverse.
 * Getting that direction backwards in the tooltip copy would be worse than shipping no tooltip at all,
 * so its wording was checked against `theme.ts`'s `ThemeManifest.publishedPages` doc and
 * `theme-page-publish.test.ts` rather than assumed. Deliberately silent on the separate Post-vs-page
 * slug-collision override (`resolveMarketingPageOrOverride`, `pages.ts`) — that is a different
 * mechanism (which RECORD wins a shared slug) from this one (whether a theme page has a route at
 * all), and folding both into one bubble would confuse the exact thing this tooltip exists to clarify.
 *
 * @complexity O(1) — one fixed control, no iteration.
 */
function ThemeExplorePublishToggle({
  state,
  publishing,
  setPagePublished,
  fileLabel,
  t,
}: {
  state: ThemeExplorePublishState;
  publishing: boolean;
  setPagePublished: (published: boolean) => Promise<void>;
  fileLabel: string;
  t: Translate;
}) {
  const on = state.kind === "toggle" ? state.published : state.on;
  // Locked forever; a live toggle is additionally disabled for the duration of its own round trip —
  // same "can't act while the very action it's for is in flight" shape `save`/`reset`'s own disabled
  // conditions use elsewhere on this screen.
  const disabled = state.kind === "locked" || publishing;
  const reasonId = state.kind === "locked" ? "theme-explore-publish-reason" : undefined;

  // Guarded on `state.kind` (inside `dispatchPublishToggle`) rather than relying solely on the DOM's
  // own "disabled buttons don't fire click" behavior — so a locked switch can never dispatch a
  // publish call no matter what wraps or simulates the click.
  function handleClick() {
    dispatchPublishToggle(state, setPagePublished);
  }

  return (
    <div className="theme-explore-publish-toggle">
      <span className="theme-explore-publish-label">{t("Publish")}</span>
      <button
        type="button"
        role="switch"
        aria-checked={on}
        aria-label={`${t("Publish")} ${fileLabel}`}
        aria-describedby={reasonId}
        className={on ? "theme-explore-switch is-on" : "theme-explore-switch"}
        disabled={disabled}
        onClick={handleClick}
      >
        <span className="theme-explore-switch-knob" aria-hidden="true" />
      </button>
      {/* `descriptionId` keeps the locked reason as the switch's `aria-describedby` text: InfoTip
          renders the label in a hidden span with that id, so screen readers still hear why. */}
      <InfoTip label={publishToggleTipLabel(state, t)} descriptionId={reasonId} />
    </div>
  );
}

/**
 * The main pane's body: the HTML source view, or the live preview (itself either the rendered iframe
 * or a "select a file" notice, depending on whether the selected file has anything to preview).
 *
 * A flat if-chain rather than a nested ternary directly in `ThemeExplore`'s own return — extracted
 * for the complexity-drift reason this file's own header comment documents, and flattened rather than
 * merely relocated because sonarjs' cognitive-complexity scoring penalizes NESTED conditionals more
 * heavily than sequential ones at the same depth.
 *
 * 2026-10-10: a data/style/script file (`previewMode === "code"`) shows its text in the shared
 * read-only `CodeView` at normal size instead of the device-scaled iframe. An unloaded buffer shows
 * as empty, same as the HTML tab's `"unloaded"` case: whatever it holds is not this file.
 *
 * @complexity O(n) for n characters of source in the code branch; O(1) otherwise.
 */
function ThemeExploreMainPane({
  view,
  previewMode,
  wrap,
  previewSrc,
  previewWidth,
  selectedFile,
  source,
  sourceLoaded,
  setSource,
  t,
}: {
  view: ThemeExploreView;
  previewMode: ThemeExplorePreviewMode;
  wrap: boolean;
  previewSrc: string | null;
  previewWidth: number;
  selectedFile: ThemeExploreFile | undefined;
  source: string;
  sourceLoaded: boolean;
  setSource: (value: string) => void;
  t: Translate;
}) {
  if (view === "html") {
    return (
      <ThemeExploreHtmlPane file={selectedFile} source={source} sourceLoaded={sourceLoaded} setSource={setSource} t={t} />
    );
  }
  if (previewMode === "code") {
    return (
      <div className="theme-explore-code-view" role="region" aria-label={t("Theme file source (read-only)")}>
        <CodeView text={sourceLoaded ? source : ""} wrap={wrap} />
      </div>
    );
  }
  if (previewSrc === null) {
    return <div className="notice">{themeExplorePreviewNotice(t)}</div>;
  }
  return <ThemeExplorePreview src={previewSrc} width={previewWidth} title={t("Theme preview")} />;
}

/**
 * The fullscreen preview `<dialog>` — extracted to top level for the complexity-drift reason this
 * file's own header comment documents: `fullscreen && previewSrc` conditionally mounting the iframe
 * was one more branch scored against `ThemeExplore` itself.
 *
 * No device-width control duplicated in here — the docked toolbar's Desktop/Tablet/Mobile group
 * already owns that choice (`device` is shared state, so fullscreen just renders at whatever was last
 * selected), and a second set of identically-labelled buttons would be a real duplicate-tab-target for
 * keyboard/screen-reader users, not just visual clutter. The iframe is only mounted while `fullscreen`
 * is true — an always-mounted iframe here would fire a second, hidden request to the site server on
 * every render alongside the docked preview's own.
 *
 * @complexity O(1).
 */
function ThemeExploreFullscreenDialog({
  dialogRef,
  fullscreen,
  previewSrc,
  previewWidth,
  onClose,
  onCancel,
  onBackdropClick,
  t,
}: {
  dialogRef: RefObject<HTMLDialogElement | null>;
  fullscreen: boolean;
  previewSrc: string | null;
  previewWidth: number;
  onClose: () => void;
  onCancel: (e: SyntheticEvent<HTMLDialogElement>) => void;
  onBackdropClick: (e: MouseEvent<HTMLDialogElement>) => void;
  t: Translate;
}) {
  return (
    <dialog
      ref={dialogRef}
      className="theme-explore-preview-dialog"
      aria-label={t("Theme preview, fullscreen")}
      onCancel={onCancel}
      onClick={onBackdropClick}
    >
      <button
        type="button"
        className="theme-explore-preview-dialog-close"
        onClick={onClose}
        aria-label={t("Close fullscreen preview")}
      >
        ×
      </button>
      {fullscreen && previewSrc ? (
        <iframe
          key={previewSrc}
          className="theme-explore-preview-dialog-iframe"
          title={t("Theme preview, fullscreen")}
          src={previewSrc}
          sandbox="allow-scripts"
          style={{ width: `${previewWidth}px` }}
        />
      ) : null}
    </dialog>
  );
}

export function ThemeExplore(props: ThemeExploreProps) {
  const resolved = useWiredThemeExploreTheme({ themeId: props.themeId });
  if (resolved.loading) return <div className="notice">{resolved.t("Loading theme…")}</div>;
  if (!resolved.themeId) return (
    <div className={`notice${resolved.error ? " error" : ""}`}>
      <p>{resolved.error ?? resolved.t("No theme is active. Your site renders unstyled so you can supply your own CSS; posts, pages and products still publish normally. Activate a theme below to switch back at any time — nothing was deleted.")}</p>
      <a href={siteUrl("/admin/themes")}>{resolved.t("Themes")}</a>
    </div>
  );
  return <ThemeExploreContent {...props} themeId={resolved.themeId} />;
}

function ThemeExploreContent({
  themeId,
  pageId,
  fileId,
  useThemeExploreHook = useWiredThemeExplore,
  useThemeExplorePreviewHook = useThemeExplorePreview,
}: ThemeExploreProps) {
  const {
    detail,
    files,
    selected,
    select,
    highlightedPath,
    view,
    setView,
    source,
    setSource,
    dirty,
    confirmLeave,
    sourceLoaded,
    saving,
    error,
    dismissError,
    notice,
    dismissNotice,
    save,
    resetting,
    resetConfirmOpen,
    openResetConfirm,
    closeResetConfirm,
    reset,
    savingOriginal,
    saveOriginal,
    previewNonce,
    renamingPath,
    renameDraft,
    setRenameDraft,
    startRename,
    cancelRename,
    commitRename,
    renaming,
    pageRenameWarning,
    confirmPageRename,
    cancelPageRenameWarning,
    copyingPath,
    copyFile,
    deleteTarget,
    openDeleteConfirm,
    closeDeleteConfirm,
    deleting,
    confirmDelete,
    publishing,
    setPagePublished,
    t,
  } = useThemeExploreHook(themeId, { pageId, fileId });

  // STAYS LOCAL — deliberately not moved into `useThemeExploreHook`'s controller (owner-ratified,
  // 2026-08-14 DI migration sweep). This is interactive DOM chrome, not async/API state: nothing
  // here does I/O, and `ThemeExplore.unit.test.tsx` asserts it through REAL DOM behavior driven by
  // real clicks — `aria-pressed` toggling on Tablet/Mobile, the `<dialog>`'s `open` attribute,
  // focus returning to the trigger on close. Every `useThemeExploreHook` fake in that file is a
  // static object (`() => ctrl`), so a setter moved into the controller would become a `vi.fn()`
  // that changes nothing on screen — proved by making the move and watching those tests fail with
  // "setFullscreen is not a function" before reverting here. Same precedent as `Posts.tsx:64`'s own
  // local `updatedSort`: pure view state with no I/O is allowed to live outside the injected hook.
  // Async/API state (the rest of this controller) is NOT exempt — this carve-out is for DOM-chrome
  // state asserted through real interaction only.
  const { device, setDevice, width: previewWidth } = useDevicePreviewDevice();
  const {
    fullscreen,
    setFullscreen,
    fullscreenTriggerRef,
    dialogRef,
    closeFullscreen,
    handleFullscreenCancel,
    handleFullscreenBackdropClick,
  } = useThemeExploreFullscreen();
  // Above the early returns below: `use*` has to be called unconditionally for the rules-of-hooks
  // lint even though this one holds no state of its own.
  const { onKeyDown: onViewTabsKeyDown } = useTabBarKeyboard({ tabs: VIEW_TABS, activeId: view, onChange: (id) => setView(id as ThemeExploreView) });

  const previewSrc = useThemeExplorePreviewHook({ themeId, detail, files, selected, previewNonce });
  // Shared by the toolbar's Wrap toggle and the Preview tab's code view; only read for "code" files.
  const { wrap, toggleWrap } = useCodeWrap();

  if (error && !detail) return <div className="notice error">{error}</div>;
  if (!detail) return <div className="notice">{t("Loading theme…")}</div>;

  const selectedFile = files.find((f) => f.path === selected);
  const publishState = selectedFilePublishState(selectedFile, t);
  const previewMode = themeExplorePreviewMode(selectedFile);

  return (
    <div className="page">
      {/* 2026-08-11: header row matches `PageEditor.tsx`'s own header exactly — `.page-header-text`
          (kicker/title/description) and the actions column as SIBLINGS inside the same
          `.page-header`, not stacked as two separate blocks. `.page-header`'s own `display: flex;
          justify-content: space-between` (shared, styles.css) is what puts the title on the left
          and the actions column on the right of the SAME line — that rule already does the work for
          Pages, so this screen only needed to adopt the same DOM shape, not new CSS.

          The actions column (`.theme-explore-header-actions`) wraps TWO stacked rows now, not one:
          the Save / Reset button row (`.page-actions`; ← All themes left it 2026-10-11), and below it the
          collapsed "You're editing your own copy" line. That line used to be its own full-width
          `.notice` block between the header and the file list, up to half the page wide (owner
          feedback, 2026-08-11: "it's taking up too much space... just show 'You're editing your own
          copy' and then a tooltip icon ... put that on the right hand side under the All themes").
          Moving it into the header's own actions column, rather than leaving it as a sibling of
          `.page-header` styled to float right, means the file list below gets ALL of the reclaimed
          vertical space for free — one fewer full-width block in `.page`'s flex column, no
          compensating negative margin needed.

          2026-10-11 (owner: "center the title section ... just make it a back arrow to the left,
          and leave the Saved and Reset buttons where they are"): "← All themes" left the actions
          row and is now a plain back arrow alone at the header's left, the same arrow the Edit
          post/page headers use (`.content-editor-back`). The title block sits centred between it
          and the actions column; the grid that does that is `.theme-explore-header` in styles.css. */}
      <div className="page-header theme-explore-header">
        {/* A plain `<button>`, not a `<button>` nested inside an `<a href>` — that nesting
            (interactive content inside interactive content) is invalid HTML, and a browser
            agent's accessibility-tree read (or a screen reader) sees either a link wrapping a
            button or an ambiguous merge of the two roles, depending on the engine. The 2026-08-11
            toolbar restructure (`ThemeExplore.unit.test.tsx`'s "toolbar restructure" describe
            block) deliberately settled this control as a BUTTON, so the fix here is to drop the
            redundant wrapping anchor rather than the button; `navigate()` is a real client-side
            route change, same as `ThemeGrid`'s own "Explore" button in `Themes.tsx` right above
            this file. Icon-only since 2026-10-11: `aria-label` names it, `title` is the hover tip
            (same pair `ThemePreviewReloadButton` uses). */}
        <button
          type="button"
          className="theme-explore-back"
          aria-label={t("All themes")}
          title={t("All themes")}
          onClick={() => {
            if (confirmLeave()) navigate("/themes");
          }}
        >
          <Icon name="arrow-left" size={22} aria-hidden="true" />
        </button>
        <div className="page-header-text">
          <p className="page-kicker">{t("Studio")}</p>
          <h1 className="page-title">{detail.name}</h1>
          <p className="page-description">
            {t("Edit this theme and see it rendered. Nothing here changes your live site until you activate it.")}
          </p>
        </div>
        <div className="theme-explore-header-actions">
          <div className="page-actions">
            <ThemeExploreToolbarButtons
              selectedFile={selectedFile}
              resetting={resetting}
              openResetConfirm={openResetConfirm}
              dirty={dirty}
              saving={saving}
              save={save}
              t={t}
            />
          </div>
          <ThemeExploreCopyTip detail={detail} t={t} />
        </div>
      </div>

      <ThemeExploreDirectionsNotice detail={detail} savingOriginal={savingOriginal} saveOriginal={saveOriginal} t={t} />
      <ThemeExploreStatusNotice detail={detail} t={t} />
      {/* Every error on this screen shares one presentation now — a rename refusal, a name
          collision, a containment rejection, a save/reset failure — rather than the full-width pink
          inline banner this used to be. `placement="top"` + centered (the `Toast` component's own
          styling, `styles.css`) rather than the default bottom placement `notice`/success toasts
          below use, per the owner's own ask: a mid-screen overlay would cover the file list and the
          editor, which is where the operator is looking when an error fires. `ttlMs={0}` pins it open
          (no auto-dismiss timer) — an operator who looked away has no way to recover text that
          vanished on a clock, so the close button is the only way this goes away. `role="alert"` so
          screen readers announce it immediately, matching the "the error is the feature" reasoning
          the owner gave for keeping Rename attemptable everywhere instead of disabling it. */}
      {error ? (
        <Toast message={error} tone="error" role="alert" placement="top" ttlMs={0} onDismiss={dismissError} />
      ) : null}
      {notice ? <Toast message={notice} tone="success" ttlMs={5000} onDismiss={dismissNotice} /> : null}

      {/* File picker on top, then the toolbar and preview at full width (owner, 2026-10-11). This
          wrapper is the screen's size container (`container-type` in styles.css), so its layout
          follows the width it actually gets with the side nav and chat dock open, not the
          viewport. The toasts above stay outside it on purpose: containment would make this box
          their containing block instead of the window. */}
      <div className="theme-explore">
        <ThemeExploreFileList
          files={files}
          selected={highlightedPath}
          select={select}
          renamingPath={renamingPath}
          renameDraft={renameDraft}
          setRenameDraft={setRenameDraft}
          startRename={startRename}
          cancelRename={cancelRename}
          commitRename={commitRename}
          copyingPath={copyingPath}
          copyFile={copyFile}
          openDeleteConfirm={openDeleteConfirm}
          t={t}
        />

        <div className="theme-explore-main">
          <div className="page-editor-toolbar">
            <div className="theme-explore-toolbar-start">
              <div className="segmented" role="tablist" aria-label={t("Editor view")} onKeyDown={onViewTabsKeyDown}>
                {VIEW_TABS.map((entry) => (
                  <button
                    key={entry.key}
                    type="button"
                    role="tab"
                    aria-selected={view === entry.key}
                    className={view === entry.key ? "is-active" : undefined}
                    tabIndex={resolveTabBarTabIndex({ tabs: VIEW_TABS, activeId: view, tab: entry })}
                    onClick={() => setView(entry.key)}
                  >
                    {t(entry.label)}
                  </button>
                ))}
              </div>
              {publishState !== null ? (
                <ThemeExplorePublishToggle
                  state={publishState}
                  publishing={publishing}
                  setPagePublished={setPagePublished}
                  fileLabel={selectedFileLabel(selectedFile)}
                  t={t}
                />
              ) : null}
            </div>
            <div className="theme-explore-toolbar-actions">
              <ThemeExploreToolbarActions
                view={view}
                previewMode={previewMode}
                wrap={wrap}
                toggleWrap={toggleWrap}
                controls={{ device, setDevice, previewSrc, fullscreenTriggerRef, setFullscreen }}
                t={t}
              />
            </div>
          </div>

          <ThemeExploreMainPane
            view={view}
            previewMode={previewMode}
            wrap={wrap}
            previewSrc={previewSrc}
            previewWidth={previewWidth}
            selectedFile={selectedFile}
            source={source}
            sourceLoaded={sourceLoaded}
            setSource={setSource}
            t={t}
          />
        </div>
      </div>

      <ThemeExploreFullscreenDialog
        dialogRef={dialogRef}
        fullscreen={fullscreen}
        previewSrc={previewSrc}
        previewWidth={previewWidth}
        onClose={closeFullscreen}
        onCancel={handleFullscreenCancel}
        onBackdropClick={handleFullscreenBackdropClick}
        t={t}
      />

      {/* The only DESTRUCTIVE confirmation on this screen — Reset is the only thing here that can
          lose work. Names the file explicitly rather than saying "this file": a destructive prompt
          should never be ambiguous about its target. */}
      <ConfirmDialog
        open={resetConfirmOpen}
        agentHandle="theme-explore-reset-file"
        title={t("Reset this file to the original?")}
        body={<ResetFileWarningBody selected={selected} t={t} />}
        confirmLabel={t("Reset file")}
        destructive
        pending={resetting}
        onConfirm={() => void reset()}
        onCancel={closeResetConfirm}
      />

      {/* NOT `destructive` — renaming a page loses no data and can be undone by renaming it back.
          It still warrants a pause because it changes something outside this screen's own state: the
          page's public URL, which anything already linking to it will silently stop reaching. */}
      <ConfirmDialog
        open={pageRenameWarning !== null}
        agentHandle="theme-explore-rename-page"
        title={t("Rename this page?")}
        body={<PageRenameWarningBody pageRenameWarning={pageRenameWarning} t={t} />}
        confirmLabel={t("Rename page")}
        tone="warning"
        pending={renaming}
        onConfirm={() => void confirmPageRename()}
        onCancel={cancelPageRenameWarning}
      />

      {/* Delete (2026-08-29 owner ask). `destructive`, same as Reset above — unlike Rename or Copy,
          a delete has no undo of any kind once it succeeds (this repo keeps no theme-file revision
          history), so every eligible file gets this pause unconditionally, not only the ones with a
          side effect elsewhere (compare Rename's page-URL warning, which only fires for pages). Names
          the exact file rather than "this file", same reasoning as Reset's own dialog. */}
      <ConfirmDialog
        open={deleteTarget !== null}
        agentHandle="theme-explore-delete-file"
        title={t("Delete this file?")}
        body={<DeleteFileWarningBody deleteTarget={deleteTarget} t={t} />}
        confirmLabel={t("Delete file")}
        destructive
        pending={deleting}
        onConfirm={() => void confirmDelete()}
        onCancel={closeDeleteConfirm}
      />
    </div>
  );
}

/**
 * Renders the live theme-explore iframe at a fixed device width and scales the whole thing down to
 * fit the docked pane — the shared `DevicePreviewFrame` `PageEditor.tsx`'s `PagePreview` also uses (its
 * `.page-preview-frame`/`.page-preview-scaler`/`.page-preview-iframe` classes rather than a parallel
 * set), adapted for a real `src` URL instead of `SrcDocSandbox`'s `srcDoc` — see this file's header
 * comment for why the preview has to be a real URL at all.
 */
function ThemeExplorePreview({ src, width, title }: { src: string; width: number; title: string }) {
  // The frame's REAL rendered width, not a guessed constant — see `usePreviewPaneWidth`'s own doc.
  const { frameRef, paneWidth } = usePreviewPaneWidth();

  return (
    <DevicePreviewFrame width={width} frameRef={frameRef} paneWidth={paneWidth}>
      {/* `key={src}` forces a remount on every durable theme revision or file/device
          change — an iframe does not reliably refetch when only its `src` attribute changes. */}
      <iframe key={src} className="page-preview-iframe" title={title} src={src} sandbox="allow-scripts" />
    </DevicePreviewFrame>
  );
}

import { api, type PresentationSettings, type ThemeTier } from "@/lib/api";
import type { ThemesPort } from "./themes-port.hooks";

/**
 * @file The only place under `features/themes` that reaches `lib/api` for the three `ThemesPort`
 * routes — see `themes-port.hooks.ts` for why the split exists.
 */

/** The live implementation, as a module-level singleton — matches `integrations/jini-admin/redirects-ports.ts`'s `redirectsHostPorts`. */
export const defaultThemesPort: ThemesPort = {
  getPresentation: () => api.getPresentation(),
  rescanThemes: () => api.rescanThemes(),
  setActiveTheme: (activeThemeId) => api.setActiveTheme(activeThemeId),
  duplicateTheme: (themeId, newName) => api.duplicateTheme(themeId, newName),
  trashTheme: async ({ themeId }) => {
    await api.trash({ type: "theme", id: themeId });
  },
};

/** Seed state for {@link createFakeThemesPort}. */
export interface FakeThemesPortOptions {
  settings?: PresentationSettings;
  availableThemeIds?: string[];
  availableThemes?: Array<{ id: string; name?: string; tier: ThemeTier; previewImageUrl?: string | null; builtIn?: boolean }>;
  /** Lets a test script what a rescan reports without the fake reimplementing the
   *  server's own theme-directory scan. */
  onRescan?: () => { added: string[]; removed: string[]; total: number; availableThemeIds: string[]; duplicateIds: string[] };
}

/**
 * An in-memory {@link ThemesPort} for tests — lets a test describe "these themes are installed,
 * this one is active" directly, instead of hand-building `Response` objects and stubbing global
 * `fetch`. Shipped alongside the real binding per the pattern's "every port gets a fake" rule.
 */
export function createFakeThemesPort(options: FakeThemesPortOptions = {}): ThemesPort {
  let settings: PresentationSettings = options.settings ?? { workspaceId: "fake-ws", activeThemeId: "basic", updatedAt: new Date(0).toISOString() };
  const availableThemeIds = [...(options.availableThemeIds ?? ["basic"])];
  const availableThemes = [...(options.availableThemes ?? [{ id: "basic", tier: "declarative" as ThemeTier }])];

  return {
    async getPresentation() {
      return { settings, availableThemeIds: [...availableThemeIds], availableThemes: [...availableThemes] };
    },

    async rescanThemes() {
      if (options.onRescan) return options.onRescan();
      return { added: [], removed: [], total: availableThemeIds.length, availableThemeIds: [...availableThemeIds], duplicateIds: [] };
    },

    async setActiveTheme(activeThemeId) {
      settings = { ...settings, activeThemeId };
      return { settings, availableThemeIds: [...availableThemeIds] };
    },

    /** Adds the copy to the installed list under a name-derived id, the way the server would —
     *  minus the server's collision suffixing, which a test scripts with distinct names. */
    async duplicateTheme(themeId, newName) {
      const source = availableThemes.find((theme) => theme.id === themeId);
      if (!source) throw new Error(`theme '${themeId}' was not found`);
      const id = newName.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
      availableThemeIds.push(id);
      availableThemes.push({ id, name: newName, tier: source.tier });
      return { theme: { id, name: newName } };
    },

    /** Drops the theme from the installed list and refuses the active one, the way the server's
     *  `theme` Trash mover does. */
    async trashTheme({ themeId }) {
      if (settings.activeThemeId === themeId) throw new Error(`theme '${themeId}' is the active theme`);
      const index = availableThemes.findIndex((theme) => theme.id === themeId);
      if (index === -1) throw new Error(`theme '${themeId}' was not found`);
      availableThemes.splice(index, 1);
      availableThemeIds.splice(availableThemeIds.indexOf(themeId), 1);
    },
  };
}

import { useEffect, useState } from "react";
import { useAdminLocale } from "@/hooks/use-admin-locale.hooks";
import { t as translateThemes } from "../themes-i18n";
import { defaultThemesPort } from "./themes-dependencies.hooks";
import type { ThemesPort } from "./themes-port.hooks";

/** Resolve a bare /themes/explore before mounting the file editor. An empty detail ID would
 * request the registry route (/themes/), whose response has no files array to map.
 */
export function useThemeExploreTheme(
  { themeId }: { themeId: string },
  { port = defaultThemesPort }: { port?: Pick<ThemesPort, "getPresentation"> } = {},
) {
  const [fallback, setFallback] = useState<{ themeId: string | null; error: string | null } | null>(null);
  useEffect(() => {
    if (themeId) {
      setFallback(null);
      return;
    }
    let cancelled = false;
    setFallback(null);
    port.getPresentation().then(({ settings }) => {
      if (!cancelled) setFallback({ themeId: settings.activeThemeId || null, error: null });
    }).catch((error: unknown) => {
      if (!cancelled) setFallback({ themeId: null, error: error instanceof Error ? error.message : "failed to load themes" });
    });
    return () => { cancelled = true; };
  }, [themeId, port]);

  return {
    themeId: themeId || fallback?.themeId || null,
    loading: !themeId && fallback === null,
    error: themeId ? null : fallback?.error ?? null,
  };
}

export function useWiredThemeExploreTheme(
  required: { themeId: string },
  optional: { port?: Pick<ThemesPort, "getPresentation"> } = {},
) {
  const locale = useAdminLocale();
  return { ...useThemeExploreTheme(required, optional), t: (key: string) => translateThemes({ locale: locale, key: key }) };
}

