/**
 * @file State for the Explore screen, so `ThemeExplore.tsx` is only markup — same split as
 * `use-themes.hooks.ts` / `Themes.tsx`.
 *
 * `deps.port` is injected (see `theme-explore-port.hooks.ts`) rather than reaching for `lib/api`'s
 * `api` directly. `ApiError` stays a direct import — pure error-classification, no I/O, same
 * reasoning as `Jini redirects/SOURCE-RATIONALE.md`'s own exclusion of `describeApiError`.
 *
 * `deps.t` (standing i18n rule, 2026-08-11 — a component with a hook gets a BOUND `t` from that
 * hook, not its own `useAdminLocale()`/dictionary import, same shape `use-themes.hooks.ts`
 * established): injected so `ThemeExplore.tsx` sources its UI copy from this hook instead of
 * building its own `(key) => translateThemes(locale, key)` closure. `useAdminLocale()`/`themes-i18n.ts`'s
 * `t` (aliased `translateThemes`) are read only inside {@link useWiredThemeExplore}. Every toast this hook
 * sets, notice or error, goes through `t` as well (2026-09-14, o24 review F4). Only a server's own error
 * message passes through untranslated, apart from the reset refusals {@link resetErrorMessage} has copy for.
 *
 * Content refresh bus (2026-09-14, o24 review F2): an assistant run can write theme files while this
 * screen is open. Both the finished run's `publishContentRefresh()` and the theme preview feed
 * refresh the file list and, when nothing is unsaved, the open file's text. The list follows added,
 * removed and renamed files; a dirty buffer survives even if its file was removed externally.
 */

export type ThemeExploreView = "preview" | "html";

export type { ThemeFileGroup, ThemeExploreSlugCollision };

/** One entry in the Explore file list. */
export interface ThemeExploreFile {
  /** Path relative to the theme root, e.g. `pages/about.html` or `css/styles.css`. */
  path: string;
  /** What to show in the list. */
  label: string;
  kind: ThemeFileGroup;
  /** Whether the raw source can be fetched/displayed as text at all. False only for binary assets
   *  (images, fonts) — `readFileSync(…, "utf8")` on those returns mojibake. Independent of
   *  `editable`: a script is readable (you can look at it) but not editable (you can't save it). */
  readable: boolean;
  /** Whether the file can be SAVED — false for binaries (which are also not `readable`) and for
   *  read-only groups (`script`, `other`) even though those stay `readable`. 2026-08-11: this used
   *  to be the same flag as `readable` (`editable`), which meant "make scripts read-only" had no way
   *  to also keep them viewable without a bigger change than the ask called for — splitting the two
   *  concepts is what unblocks that. */
  editable: boolean;
  /** False for files the author added, which have no original to restore from. */
  resettable: boolean;
  /**
   * Whether the file's bytes differ from its catalog original — `null` exactly when `resettable` is
   * false, since with no original there is nothing to be modified FROM. Straight from the server's
   * byte comparison (`explore.ts`'s `describeThemeFile`), so a CRLF-only difference counts. Decides
   * whether Reset is offered ({@link canResetThemeFile}) and whether the file list marks the file
   * ({@link isThemeFileModified}).
   */
  modified: boolean | null;
  /**
   * Whether this file is currently a publicly reachable page — `null` for every file the question
   * does not apply to at all (every non-page file, plus a page that is `index`/`404` or a declared
   * Post/Page template shell), so the publish-row control (`ThemeExplore.tsx`) can tell "no publish
   * state for this file" apart from an actual off state, the same `readable`/`editable` split
   * pattern this file already uses for a different pair of questions. `true`/`false` for a real
   * standalone page, straight from the server's own `isStandaloneThemePage` — this can never drift
   * from what public routing actually does.
   */
  published: boolean | null;
  /**
   * The live content record occupying this page's own slug, or `null` for every file `published`
   * is also `null` for (same candidate-page gate) plus a real candidate page with no such record.
   *
   * A page can read `published: true` here and STILL not be what a visitor gets — or read
   * `published: false` and still resolve to someone ELSE's content — because
   * `resolveMarketingPageOrOverride` (`server/inbound/public-http/routes/site/pages.ts`) lets a live
   * Post/Page row at the same slug win independent of this toggle. `ThemeExplorePublishToggle`
   * surfaces this as its own warning precisely BECAUSE toggling this switch does not, by itself,
   * determine what a visitor sees at this URL.
   */
  collidingContent: ThemeExploreSlugCollision | null;
}

/** Heading order for the file list — most-edited first, generated/vendored/catch-all last. */
export const THEME_FILE_GROUPS: ReadonlyArray<{ key: ThemeFileGroup; label: string }> = [
  { key: "page", label: "Pages" },
  { key: "partial", label: "Partials" },
  { key: "style", label: "Styles" },
  { key: "script", label: "Scripts" },
  { key: "config", label: "Config" },
  { key: "asset", label: "Assets" },
  { key: "other", label: "Other" },
];

export interface ThemeExploreDetail {
  id: string;
  name: string;
  tier: string;
  /** Manifest schema version (`2`, or `undefined` for v1) — feeds {@link lockedRenamePaths} below,
   *  so the rename-lock pre-check resolves the same layout the server used to classify `files`. */
  apiVersion: 2 | undefined;
  status: string;
  errors: string[];
  hasOriginal: boolean;
}

/**
 * Mirrors the server's `requiredThemeFiles` (`explore.ts`) — `loadTheme` fails without any of
 * these (a missing index page, or a `theme.json`/`tokens.json` that no longer parses), so renaming
 * one away reproduces that same breakage. The SERVER is the actual enforcement point (it refuses the
 * rename with `code: "REQUIRED_FILE_LOCKED"` regardless of what the client does); this client-side
 * copy only avoids a pointless round trip for the common case of double-clicking one of these files
 * directly.
 *
 * 2026-08-19 architecture audit findings 1 & 2: this used to be a fixed `Set` naming v1's
 * `pages/index.html` unconditionally, so a v2 theme's `render/pages/index.html` (every real static
 * theme on disk today) was never actually locked client-side — the operator's rename would start
 * inline, then fail with a round trip instead of an immediate inline refusal. Derived from
 * `resolveThemeLayout` (`@tovu/theme-layout` — the SAME resolver `explore.ts`'s server route uses)
 * so the two cannot drift apart again.
 */
function lockedIdentityPaths(apiVersion: 2 | undefined): readonly string[] {
  return resolveThemeLayout(apiVersion).requiredFiles;
}

/**
 * Groups whose files' NAME or EXISTENCE can never change — mirrors the server's own
 * `IDENTITY_LOCKED_GROUPS` rename/delete block in `explore.ts` (see that constant's doc comment for
 * the full reasoning). 2026-08-11 judgment call, still true after `script`'s CONTENT became editable
 * (2026-08-29 — see `explore.ts`'s `CONTENT_EDIT_LOCKED_GROUPS`): a silent rename or delete would
 * reopen the "nobody breaks the page from this screen" hole through a `<script src>` or similar
 * reference this screen has no way to find and fix (unlike a page rename, which gets a URL-change
 * warning because the renderer tracks page routes — nothing tracks arbitrary cross-file references the
 * same way). This client-side copy only avoids a pointless round trip; the server is the real
 * enforcement point. Shared by {@link startRename} and `openDeleteConfirm` (2026-08-29) — one set, not
 * two that could drift apart.
 */
const IDENTITY_LOCKED_GROUPS: ReadonlySet<ThemeFileGroup> = new Set(["script", "other"]);

/**
 * `t(key)` with its one `{token}` placeholder filled by `value`. The replacement is a function, so a
 * `$&` or `$1` in a file name is inserted as written rather than read as a replacement pattern.
 *
 * @complexity O(k) in the translated string's length.
 */
function translateWith(t: Translate, key: string, token: string, value: string): string {
  return t(key).replace(`{${token}}`, () => value);
}

/** The refusal copy per `action`: one whole sentence per case, so each locale can word it freely. */
const LOCKED_IDENTITY_COPY = {
  renamed: {
    page: "{file} can't be renamed — every theme requires this exact page to load at all.",
    file: "{file} can't be renamed — every theme requires this exact file to load at all.",
    group:
      "{file} can't be renamed — this file type is read-only in Explore, and renaming it could break a page or script that still refers to it by this name.",
  },
  deleted: {
    page: "{file} can't be deleted — every theme requires this exact page to load at all.",
    file: "{file} can't be deleted — every theme requires this exact file to load at all.",
    group:
      "{file} can't be deleted — this file type is read-only in Explore, and deleting it could break a page or script that still refers to it by this name.",
  },
} as const;

/** `action`-qualified refusal reason shared by {@link startRename} and `openDeleteConfirm` — same
 *  three checks {@link lockedIdentityPaths}/{@link IDENTITY_LOCKED_GROUPS} answer server-side via
 *  `explore.ts`'s `validateFileIdentityChange`. Translated through `t`. */
function lockedIdentityChangeReason(
  path: string,
  apiVersion: 2 | undefined,
  action: "renamed" | "deleted",
  t: Translate
): string {
  const copy = LOCKED_IDENTITY_COPY[action];
  if (path === resolveThemeLayout(apiVersion).indexPagePath) return translateWith(t, copy.page, "file", path);
  if (lockedIdentityPaths(apiVersion).includes(path)) return translateWith(t, copy.file, "file", path);
  return translateWith(t, copy.group, "file", path);
}

export interface ThemeExploreController {
  detail: ThemeExploreDetail | null;
  files: ThemeExploreFile[];
  /** Currently open file's path, or `null` before the first load settles. */
  selected: string | null;
  select: (path: string) => void;
  /**
   * The path the file list marks as open: a clicked file whose text {@link select} is still holding
   * for (HTML view only, see `shouldAwaitFileText`), else {@link selected}. The editor, toolbar,
   * preview and every file action keep following `selected` until that text lands.
   */
  highlightedPath: string | null;
  view: ThemeExploreView;
  setView: (value: ThemeExploreView) => void;
  /** Working copy of the open file — what the HTML tab edits. */
  source: string;
  setSource: (value: string) => void;
  /** True when the source is loaded ({@link sourceLoaded}) and `source` differs from what was last
   *  loaded or saved. */
  dirty: boolean;
  /** `useDirtyGuard`'s `confirmLeave` for `dirty` above — `select` already calls it before switching
   *  files; `ThemeExplore.tsx` calls it itself for its own in-app navigations away from this screen
   *  entirely (the "← All themes" back link) that `select` never sees. */
  confirmLeave: DirtyGuard["confirmLeave"];
  /**
   * True only while `source` holds the open file's text as last read, saved, or reset on the server.
   * False while that read is in flight, after it failed (a file past the 1 MB text-read limit), for a
   * file that is not readable — including one that WAS readable and lost that status while it stayed
   * selected (2026-09-12 fix: the file-read effect's `selectedReadable === false` branch below now
   * clears `loadedFile`, not just `source`/`savedSource`, so a stale marker from before the flip can't
   * outlive it) — and after a reset that returned no text. `dirty` and `save` both require it, so a
   * buffer that is not the file on disk can never be written over it.
   */
  sourceLoaded: boolean;
  saving: boolean;
  error: string | null;
  /** Manually clear `error` — the toast's own close button, so a dismissed message cannot resurface
   *  on the next unrelated render (the same reason {@link dismissNotice} exists for `notice`). Every
   *  action that CAN fail also clears `error` itself at the start of its own attempt, so this only
   *  matters for the "operator dismissed it and did nothing else yet" path. */
  dismissError: () => void;
  notice: string | null;
  dismissNotice: () => void;
  save: () => Promise<void>;
  /** True while a reset round trip is in flight. */
  resetting: boolean;
  /**
   * Whether the destructive-action confirmation is showing.
   *
   * Held in the controller rather than local component state so the confirmation and the action it
   * guards cannot drift apart — a dialog that closes without the reset running, or a reset that
   * runs with the dialog still open, are both states this makes unrepresentable.
   */
  resetConfirmOpen: boolean;
  openResetConfirm: () => void;
  closeResetConfirm: () => void;
  reset: () => Promise<void>;
  /** True while {@link ThemeExploreController.saveOriginal} is in flight. */
  savingOriginal: boolean;
  /**
   * Save the theme's current files as its stored original — the no-stored-original banner's button
   * (owner 2026-10-08). The original lives in the server's hidden catalog, never as a visible theme;
   * afterwards the detail is re-read, so the banner goes and Reset works on every file.
   */
  saveOriginal: () => Promise<void>;
  /**
   * Bumped after every successful save. The preview iframe keys off this to force a reload — the
   * rendered page lives on the site server, not in this app's state, so re-rendering the component
   * would otherwise show the pre-save HTML from the browser's cache.
   */
  previewNonce: number;
  /** Path of the file currently in inline-rename edit mode (double-click, or the ⋮ menu's Rename),
   *  or `null` when nothing is being renamed. */
  renamingPath: string | null;
  /** The inline rename input's current text. */
  renameDraft: string;
  setRenameDraft: (value: string) => void;
  /** Begin renaming `path` — refused inline (with `error` set to why) for one of
   *  {@link lockedRenamePaths}. */
  startRename: (path: string) => void;
  /** Abandon the in-progress rename with no server call. */
  cancelRename: () => void;
  /** Commit the current `renameDraft`. A same-name draft is a silent no-op close; a PAGE (other than
   *  the locked index) is diverted into `pageRenameWarning` instead of renaming immediately, since
   *  that changes the page's public URL. */
  commitRename: () => void;
  /** True while a rename round trip is in flight. */
  renaming: boolean;
  /** Set when `commitRename` targets a non-index PAGE — holds enough to actually perform the rename
   *  once the operator confirms past the URL-change warning. */
  pageRenameWarning: { path: string; name: string } | null;
  confirmPageRename: () => Promise<void>;
  cancelPageRenameWarning: () => void;
  /** Path of the file currently being duplicated, or `null`. Copy has no confirmation step — "it'll
   *  just copy it right in the sidebar" — so this only exists to keep a rapid double-select from
   *  firing the request twice. */
  copyingPath: string | null;
  copyFile: (path: string) => Promise<void>;
  /**
   * Path of the file pending delete confirmation, or `null` — held in the controller for the same
   * reason {@link resetConfirmOpen} is: the confirmation and the destructive action it guards cannot
   * drift apart. Unlike Reset (which only ever targets `selected`), Delete is offered from the ⋮ menu
   * on ANY row, so the target has to be its own path rather than a boolean, the same shape
   * {@link pageRenameWarning} uses for the same reason.
   */
  deleteTarget: string | null;
  /** Begin deleting `path` — refused inline (with `error` set to why) for a required file or an
   *  {@link IDENTITY_LOCKED_GROUPS} member, same client-side pre-check shape as {@link startRename}. */
  openDeleteConfirm: (path: string) => void;
  /** Abandon the pending delete with no server call. */
  closeDeleteConfirm: () => void;
  /** True while a delete round trip is in flight. */
  deleting: boolean;
  /** Commit the delete of {@link deleteTarget}. DESTRUCTIVE and, unlike Reset, not recoverable from
   *  this screen at all — see this hook's own `confirmDelete` doc comment. */
  confirmDelete: () => Promise<void>;
  /** True while a publish/unpublish round trip for the selected file is in flight. */
  publishing: boolean;
  /**
   * Publish or unpublish the SELECTED file's page — a no-op if `selected` has no publish state at all
   * (`files.find(...).published` is `null`), matching {@link save}/{@link reset}'s own "acts on
   * `selected` implicitly" shape rather than taking a path argument.
   */
  setPagePublished: (published: boolean) => Promise<void>;
  /** Bound translator — `ThemeExplore.tsx`'s only source of UI copy; see this file's own header. */
  t: Translate;
}

/**
 * `pages/about.html` → `about`; `css/styles.css` → `styles.css`.
 *
 * Pages and partials drop their `.html` because within those groups the extension is redundant —
 * every entry has it. Everything else KEEPS its extension, because `styles` vs `styles.css` vs
 * `styles.min.css` is exactly the distinction an author needs to see in a Styles or Assets list.
 */
function fileLabel(path: string, kind: ThemeFileGroup): string {
  const base = path.slice(path.lastIndexOf("/") + 1);
  return kind === "page" || kind === "partial" ? base.replace(/\.html$/, "") : base;
}

/** The path's own filename segment, extension included — what an inline rename edits. */
function basenameOf(path: string): string {
  return path.slice(path.lastIndexOf("/") + 1);
}

/**
 * Why the HTML tab shows a read-only viewer instead of a textarea, for a file that IS readable but
 * not editable — see `ThemeExploreFile.editable`'s doc comment for the readable/editable split this
 * answers. A single generic message now: scripts had their own wording here until 2026-08-29 (owner
 * ask — "we need the ability to edit CSS and JS for the themes"), when `script` stopped being a
 * content-read-only group server-side (`explore.ts`'s `CONTENT_EDIT_LOCKED_GROUPS`), leaving `other`
 * the one remaining case this branch can actually render for.
 */
export function readOnlyReason(): string {
  return "This file type is read-only in Explore.";
}

/**
 * One of the two states `ThemeExplorePublishToggle` (`ThemeExplore.tsx`) can render — see that
 * component's own doc for what each one looks like.
 */
export type ThemeExplorePublishState =
  | { kind: "toggle"; published: boolean }
  | { kind: "locked"; on: boolean; reason: string };

/**
 * What a click on the publish switch does: a live toggle asks for the opposite of its published
 * state; a locked switch dispatches nothing. Checked on `state.kind` rather than trusting the DOM's
 * "a disabled button doesn't fire click", so no wrapper or simulated click can publish a locked page.
 *
 * @complexity O(1).
 */
export function dispatchPublishToggle(
  state: ThemeExplorePublishState,
  setPagePublished: (published: boolean) => Promise<void>,
): void {
  if (state.kind === "toggle") void setPagePublished(!state.published);
}

/**
 * The reason — and the fixed switch position that goes with it — for a page that EXISTS but can
 * never be independently toggled. `theme.ts`'s `isPublishableThemePageCandidate` returns false for
 * exactly three shapes: `index`/`404` (`NON_ROUTABLE_THEME_PAGE_IDS`) or a declared Post/Page
 * template shell (`ThemeManifest.templates`) — keyed here off the page's own `label` (its id) rather
 * than a server-sent reason string, so this can never drift from that set without both files
 * changing together; `index`/`404` are the only two ids that constant names, so any OTHER label
 * reaching this function is, by construction, the remaining case.
 *
 * `index`/`404` show ON: both are genuinely live and rendered whenever a visitor reaches them (via
 * `/` and the 404 document respectively) regardless of any publish decision — except `index` once a
 * content Page is the home page, which {@link selectedFilePublishState} shows OFF (see
 * `homeFallbackPublishReason`, `features/pages/lib/theme-page-publish-state.ts`) — the switch's fixed
 * position reflects a true fact, same as everywhere else it appears. A declared template shell shows
 * OFF instead, for the opposite reason: it has NO independent public route of its own at all (nobody
 * ever reaches `/blog-post` directly), so showing it "on" would claim a reachability it never has —
 * see `theme.ts`'s own `isStandaloneThemePage` doc for the full three-way split this mirrors.
 *
 * @complexity O(1).
 */
export function lockedPublishReason(pageLabel: string, t: Translate): { on: boolean; reason: string } {
  if (pageLabel === "index") return homeFallbackPublishReason(null, t);
  if (pageLabel === "404") return { on: true, reason: t("Always published — error page") };
  return { on: false, reason: t("Not a standalone page — used as a content template") };
}

/**
 * The selected file's publish-control state, or `null` when no control should render at all.
 *
 * 2026-08-30: this used to collapse straight to `file.published` (`boolean | null`) and treat every
 * `null` as "no control at all" — which hid the control for `index`/`404`/a declared template shell
 * exactly as silently as it correctly hid it for a genuinely unrelated file (a stylesheet, an image),
 * and cost real operator confusion: the owner selected `404`, saw nothing, and concluded the publish
 * feature hadn't shipped at all. The two `null` cases are told apart here using data this screen
 * ALREADY has — `file.kind` — with NO backend change: `describeThemeFile` (`explore.ts`) can only
 * produce a non-null `published` for a `"page"`-kind file (see that function's own doc), so a `null`
 * value on a `"page"` file is, by construction, one of `theme.ts`'s three non-candidate cases
 * ({@link lockedPublishReason}), and a `null` value on any OTHER kind is a file the publish question
 * never applied to in the first place.
 *
 * @complexity O(1).
 */
export function selectedFilePublishState(
  file: ThemeExploreFile | undefined,
  t: Translate
): ThemeExplorePublishState | null {
  if (!file) return null;
  if (file.published !== null) return { kind: "toggle", published: file.published };
  if (file.kind !== "page") return null;
  // `index` is the home fallback: OFF once a content Page is the home page — see
  // `homeFallbackPublishReason` (`features/pages/lib/theme-page-publish-state.ts`).
  if (file.label === "index") return { kind: "locked", ...homeFallbackPublishReason(file.collidingContent, t) };
  return { kind: "locked", ...lockedPublishReason(file.label, t) };
}

/**
 * The text of the one ⓘ beside the publish switch. A locked switch shows its own reason ("Not shown
 * — Home is your home page", "Always published — error page"); a live switch shows the general
 * "what publishing does" explanation. Owner, 2026-10-11: the locked reason used to be visible text
 * next to the switch and made the row long; the row is now just "Publish [switch] ⓘ", with the
 * reason only in the tooltip. The general text is not shown for a locked page: it is about turning a
 * page on, which a locked page can't do.
 *
 * @complexity O(1).
 */
export function publishToggleTipLabel(state: ThemeExplorePublishState, t: Translate): string {
  if (state.kind === "locked") return state.reason;
  return t(
    "Whether this page has its own live URL on your site. Theme pages start off, because a theme ships generic placeholder content rather than yours. Turn one on once you've made it your own."
  );
}

/**
 * The currently selected file's label, or `""` before a file is selected. Pulled out to a top-level
 * function rather than an inline `selectedFile?.label ?? ""` — the optional-chain plus
 * nullish-coalescing pair scores two points against a cyclomatic-complexity budget. The `""`
 * fallback only ever matters transiently in practice: {@link selectedFilePublishState} already
 * returns `null` whenever there is no selected file, so `ThemeExplorePublishToggle` never actually
 * renders with an empty label.
 *
 * @complexity O(1).
 */
export function selectedFileLabel(file: ThemeExploreFile | undefined): string {
  return file?.label ?? "";
}

/**
 * Whether the toolbar offers Reset for `file`: only when it has a catalog original to restore
 * (`resettable`) AND its bytes actually differ from that original (`modified`). Resetting an
 * unmodified file would change nothing, so offering it would only lead to a confirmation dialog for
 * a no-op. `undefined` (nothing selected yet) is `false`.
 *
 * @complexity O(1).
 */
export function canResetThemeFile(file: ThemeExploreFile | undefined): file is ThemeExploreFile {
  return file?.resettable === true && file.modified === true;
}

/**
 * Whether the file list marks `file` as modified from its catalog original. `null` (no original)
 * is not modified: there is nothing for it to differ from.
 *
 * @complexity O(1).
 */
export function isThemeFileModified(file: ThemeExploreFile): boolean {
  return file.modified === true;
}

/**
 * Which rendering the HTML tab uses for `file`. `undefined` (nothing selected yet) is `"editable"`,
 * an empty textarea. A file that is not readable is `"binary"` whether or not anything loaded. A
 * readable file whose source is not loaded ({@link ThemeExploreController.sourceLoaded}) is
 * `"unloaded"`: an empty read-only source, so a buffer that is not the file on disk is neither shown
 * nor typed into.
 *
 * @complexity O(1).
 */
export function themeExploreHtmlMode(
  file: ThemeExploreFile | undefined,
  sourceLoaded: boolean
): "binary" | "unloaded" | "readonly" | "editable" {
  if (!file) return "editable";
  if (!file.readable) return "binary";
  if (!sourceLoaded) return "unloaded";
  if (!file.editable) return "readonly";
  return "editable";
}

/** The editor state a content-refresh read of the open file is checked against (see
 *  {@link shouldAdoptRefreshedText}). */
export interface OpenFileSnapshot {
  themeId: string;
  selected: string | null;
  source: string;
  savedSource: string;
  loadedFile: { themeId: string; path: string } | null;
}

/**
 * Whether `a` and `b` have the same theme and file open.
 *
 * @complexity O(1).
 */
function isSameOpenFile(a: OpenFileSnapshot, b: OpenFileSnapshot): boolean {
  return a.themeId === b.themeId && a.selected === b.selected;
}

/**
 * The open file's path when a content refresh may re-read its text: the file is loaded and has no
 * unsaved edits. `null` otherwise, so unsaved edits are never read over, and a file that is not loaded
 * stays with the file-read effect.
 *
 * @complexity O(s) in the text length, for the buffer comparison.
 */
function refreshableOpenFilePath(open: OpenFileSnapshot): string | null {
  if (!isOpenFileLoaded(open.loadedFile, open.themeId, open.selected)) return null;
  return open.source === open.savedSource ? open.selected : null;
}

/**
 * Whether a content-refresh read of the open file, started at `started`, may put `content` in the
 * editor now that the editor is at `current`. Only when the same file is still open and loaded, it has
 * no unsaved edits, no Save, Reset or read has changed its saved text since the read started (that text
 * is newer than the read), and `content` differs from it.
 *
 * @complexity O(s) in the text length, for the string comparisons.
 */
export function shouldAdoptRefreshedText({
  started,
  current,
  content,
}: {
  started: OpenFileSnapshot;
  current: OpenFileSnapshot;
  content: string;
}): boolean {
  if (!isSameOpenFile(current, started) || !isOpenFileLoaded(current.loadedFile, started.themeId, started.selected)) {
    return false;
  }
  return (
    current.source === current.savedSource &&
    current.savedSource === started.savedSource &&
    content !== current.savedSource
  );
}

/**
 * Whether `select` holds a click on `path` until that file's text is read, instead of opening it at
 * once. Only in the HTML view, only for a readable file other than the open one, and only while the
 * open file's text is loaded: that text stays on screen, editable and saveable as itself, until the
 * clicked file's text lands and both swap in one render. Opening at once shows the empty read-only
 * unloaded source for the whole read (2026-09-14 owner bug: "Theme editor goes blank and read-only
 * briefly on every file load"). With nothing loaded there is nothing better to show, and the Preview
 * view shows no source, so those still open at once.
 *
 * Also decides a `?file=`/`?page=` reselect, through {@link requestedSelectionMove}.
 *
 * @complexity O(1).
 */
export function shouldAwaitFileText({
  view,
  file,
  path,
  selected,
  sourceLoaded,
}: {
  view: ThemeExploreView;
  file: ThemeExploreFile | undefined;
  path: string;
  selected: string | null;
  sourceLoaded: boolean;
}): boolean {
  return view === "html" && file?.readable === true && path !== selected && sourceLoaded;
}

/**
 * The file the file-read effect is for: a click `select` is holding in `themeId`, else `selected`. A
 * hold from another theme is ignored, so a theme switch never reads the old theme's click against the
 * new one.
 *
 * @complexity O(1).
 */
function readPathFor(
  pending: { themeId: string; path: string } | null,
  themeId: string,
  selected: string | null
): string | null {
  return pending !== null && pending.themeId === themeId ? pending.path : selected;
}

/** `OpenFileSnapshot` plus the view: what a `?file=`/`?page=` reselect decides against (see {@link requestedSelectionMove}). */
export interface SelectionHoldSnapshot extends OpenFileSnapshot {
  view: ThemeExploreView;
}

/** Whether `files` lists `path` as a readable file. `null` never is.
 *
 * @complexity O(n) in `files.length`.
 */
function isListedReadable(files: ThemeExploreFile[], path: string | null): boolean {
  return path !== null && files.find((f) => f.path === path)?.readable === true;
}

export type RequestedSelectionMove = { kind: "skip" } | { kind: "hold"; path: string } | { kind: "open"; path: string | null };

/**
 * What the initial-load effect does with the path `?file=`/`?page=` (or the default) resolved to, once `files` (the new
 * listing) has landed. `skip` when a click landed after the load started on this same theme's listing: the click is newer
 * and owns the selection. `hold` exactly when `select` would hold a click (see {@link shouldAwaitFileText}), and only while
 * the open file is still listed as readable, so the text kept on screen still has an entry to save to. `open` otherwise.
 * `open` is also the answer for a first load and a theme switch.
 *
 * @complexity O(n) in `files.length`.
 */
export function requestedSelectionMove({
  themeId,
  path,
  files,
  open,
  clickedSinceLoad,
  listedThemeId,
}: {
  themeId: string;
  path: string | null;
  files: ThemeExploreFile[];
  open: SelectionHoldSnapshot;
  clickedSinceLoad: boolean;
  listedThemeId: string | null;
}): RequestedSelectionMove {
  if (clickedSinceLoad && listedThemeId === themeId) return { kind: "skip" };
  if (path === null || !isListedReadable(files, open.selected)) return { kind: "open", path };
  const hold = shouldAwaitFileText({
    view: open.view,
    file: files.find((f) => f.path === path),
    path,
    selected: open.selected,
    sourceLoaded: isOpenFileLoaded(open.loadedFile, themeId, open.selected),
  });
  return hold ? { kind: "hold", path } : { kind: "open", path };
}

/** `path` after the file at `from` was renamed to `to`.
 *
 * @complexity O(1).
 */
function renamedPath(path: string | null, from: string, to: string): string | null {
  return path === from ? to : path;
}

/**
 * The loaded-file marker after the file at `from` in `themeId` was renamed to `to`. The server moves a file's bytes
 * unchanged, in the same folder and with the same extension (`theme-files.ts`'s `renameThemeFile`, `explore.ts`'s
 * `renameThemeFileIfChanged`). So a buffer read from `from` IS that file's text under `to`. The marker moves with it,
 * and the editor stays loaded: no re-read, no unloaded render, and unsaved edits kept. Returned unchanged when the buffer
 * is another file's or nothing's, or when `renamed` (the new listing's entry) is not a readable, editable file. The
 * file-read effect then reads or clears it like any other open file.
 *
 * @complexity O(1).
 */
export function loadedFileAfterRename(
  loaded: { themeId: string; path: string } | null,
  { themeId, from, to, renamed }: { themeId: string; from: string; to: string; renamed: ThemeExploreFile | undefined }
): { themeId: string; path: string } | null {
  if (!isOpenFileLoaded(loaded, themeId, from) || renamed?.readable !== true || renamed?.editable !== true) return loaded;
  return { themeId, path: to };
}

/**
 * `files` with each entry's `resettable` and `modified` taken from the entry at the same path in
 * `serverFiles`, a fresh detail read. Entries `serverFiles` lacks keep their own object, and nothing
 * is added or removed: a rename, copy or delete that settled while the read was in flight owns the
 * list's shape, and a slower read must not undo it.
 *
 * @complexity O(n + m) in `files.length` and `serverFiles.length` — one Map build, one pass.
 */
export function withServerModifiedState(files: ThemeExploreFile[], serverFiles: ThemeExploreFile[]): ThemeExploreFile[] {
  const serverByPath = new Map(serverFiles.map((f) => [f.path, f]));
  return files.map((f) => {
    const server = serverByPath.get(f.path);
    return server ? { ...f, resettable: server.resettable, modified: server.modified } : f;
  });
}

/**
 * Owner-reported bug (2026-08-12): clicking a `.liquid` template in Explore downloaded it instead of
 * previewing it. Originally patched HERE, client-side (overriding `readable` to `true` for any
 * `.liquid` path regardless of what the listing route reported), because the GET-file route
 * (`readThemeFile`, `theme-files.ts`) already returned ANY file's content as UTF-8 text
 * unconditionally — only the LISTING route's classification (`explore.ts`'s
 * `TEXT_READABLE_EXTENSIONS`) was stale.
 *
 * Moved server-side (2026-08-12, follow-up): `.liquid` is now IN `TEXT_READABLE_EXTENSIONS`, so the
 * listing route itself reports `readable: true` and this function goes back to a plain passthrough —
 * see that constant's own doc for why server-side is the more correct home (every consumer of the
 * listing route agrees, not just this hook). `editable` was never touched by either version of the
 * fix: the server's PUT route still refuses to write a `.liquid` file (`isThemeFileWritable`'s
 * `other`-group gate), so this stays a read-only SOURCE preview, not a new edit surface — matching
 * how `script`/`other`-group files are already readable-but-not-editable.
 *
 * @complexity O(n) in `entries.length` — one pass, each file mapped independently.
 */
function mapDetailFiles(entries: ThemeExploreFileEntry[]): ThemeExploreFile[] {
  return entries.map((f) => ({
    path: f.path,
    label: fileLabel(f.path, f.group),
    kind: f.group,
    readable: f.readable,
    editable: f.editable,
    resettable: f.resettable,
    // Same absent/undefined normalization as `published` just below, same reason.
    modified: f.modified ?? null,
    // `?? null` normalizes an absent/undefined wire value (an older cached response, or a fixture
    // that predates this field) into the same "no publish state" meaning `null` already carries —
    // `ThemeExploreFile.published` is never `undefined`, so every reader gets one two-valued-plus-null
    // contract to check instead of also handling a third, functionally-identical absent case.
    published: f.published ?? null,
    // Same absent/undefined normalization as `published` just above, same reason.
    collidingContent: f.collidingContent ?? null,
  }));
}

/**
 * Fetch one theme's detail and map it into this hook's shapes in one place, so the initial load
 * effect and the post-copy/post-rename refresh (which must NOT also re-run the initial effect's
 * default-selection logic) share one definition of "what does the server say about this theme"
 * instead of two `.map()`s drifting apart.
 */
async function fetchThemeExploreState(
  themeId: string,
  port: ThemeExplorePort
): Promise<{ detail: ThemeExploreDetail; files: ThemeExploreFile[] }> {
  const r = await port.getThemeDetail(themeId);
  return {
    detail: {
      id: r.id,
      name: r.name,
      tier: r.tier,
      apiVersion: r.apiVersion,
      status: r.status,
      errors: r.errors,
      hasOriginal: r.hasOriginal,
    },
    files: mapDetailFiles(r.files),
  };
}

/**
 * {@link fetchThemeExploreState} for the re-read after a mutation that already SUCCEEDED (Delete, Copy,
 * Rename). A failed read comes back as its own message instead of throwing into the mutation's own
 * catch: the file is already deleted, copied or renamed, and a screen that called that a failure
 * invited a retry that deletes a missing file, makes a second copy, or renames a path that no longer
 * exists. Same contract `refreshModifiedState` gives Save and Reset.
 *
 * @complexity Time/space: O(f) in the theme's file count (the one detail read it wraps).
 */
async function refetchAfterMutation(
  themeId: string,
  port: ThemeExplorePort,
  t: Translate
): Promise<({ ok: true } & Awaited<ReturnType<typeof fetchThemeExploreState>>) | { ok: false; message: string }> {
  try {
    return { ok: true, ...(await fetchThemeExploreState(themeId, port)) };
  } catch (e) {
    return { ok: false, message: e instanceof Error ? e.message : t("failed to refresh file list") };
  }
}

export interface ThemeExploreDependencies {
  port: ThemeExplorePort;
  t: Translate;
}

/** Route-supplied inputs that only steer the FIRST render — everything here is read once, by the
 *  initial-load effect, and never again. Kept out of {@link ThemeExploreDependencies} because these
 *  are not injected collaborators; they are values off the URL. */
export interface ThemeExploreOptions {
  /**
   * Page to open on, from `?page=` — a page id (`about`), its filename (`about.html`), or any other
   * value {@link resolveThemeExploreSelectionValue} (`theme-explore-url.hooks.ts`) accepts.
   *
   * Set by the Pages screen's "Theme Pages" tab, whose rows link straight here (see
   * `features/pages/Pages.tsx`'s `themeStudioHref`), and by this screen's own write-back
   * ({@link writeThemeExploreSelectionToUrl}) whenever the open file is an ordinary page. Absent,
   * unknown, or naming nothing this theme has all degrade to the same default selection an
   * unparameterized visit gets, plus a "not found" toast when something WAS asked for and neither
   * this nor {@link fileId} resolved (see {@link initialSelectedPath}) — a bad `?page=` must never
   * be able to open Explore on nothing, nor silently open a DIFFERENT file with no indication
   * anything was wrong.
   */
  pageId?: string;
  /**
   * File to open on, from `?file=` — the file's own full relative path, extension included (e.g.
   * `render/pages/404.html`, `theme.json`), or any other value the same shared resolver accepts.
   * Takes priority over {@link pageId} when both are present (see {@link initialSelectedPath}):
   * this is the write-back target for a non-page file ({@link writeThemeExploreSelectionToUrl}),
   * so the URL a user is currently looking at wins over an older `?page=` link. Absent, unknown, or
   * naming a file this theme doesn't have all degrade the same way `pageId`'s own doc describes.
   */
  fileId?: string;
}

/**
 * What to open when nothing was asked for (or nothing that WAS asked for could be resolved): the
 * theme's own index page, else the first page, else the first file, else nothing.
 *
 * `apiVersion`-aware via {@link resolveThemeLayout} (2026-08-31, verified live) — this used to
 * hardcode v1's `pages/index.html` unconditionally, the same bug class the 2026-08-19 architecture
 * audit already found and fixed for {@link lockedIdentityPaths} above. A v2 theme's real index page
 * (`render/pages/index.html`) never matched that literal, so this silently fell through to "the
 * first PAGE in server order" instead of the index — and `listThemeFiles` (`theme-files.ts`)
 * returns that order alphabetically sorted, with `"404.html"` sorting before every other page.
 * Confirmed live: `http://localhost:5173/admin/themes/explore?theme=basic` — a real, schema-v2
 * theme — opened on `render/pages/404.html` with NO page/file param at all, before this fix.
 *
 * @complexity Time O(n) in `files.length` — at most three independent scans, no nesting.
 */
function defaultSelectedPath(files: ThemeExploreFile[], apiVersion: 2 | undefined): string | null {
  const indexPagePath = resolveThemeLayout(apiVersion).indexPagePath;
  return (
    files.find((f) => f.path === indexPagePath)?.path ??
    files.find((f) => f.kind === "page")?.path ??
    files[0]?.path ??
    null
  );
}

/**
 * The file to open when the theme's listing first lands, plus whether anything that WAS asked for
 * failed to resolve: `?file=`/`?page=`, tried through the shared
 * {@link resolveRequestedThemeExploreSelection} resolver (`theme-explore-url.hooks.ts` — split out
 * there for the same complexity-drift reason this used to be spread across small helpers here),
 * else the ordinary default. `missed` lets the initial-load effect surface an explicit "not found"
 * toast instead of landing on the default in total silence — the fix for the owner's own
 * `?page=about.html`-opens-a-different-page report (see `theme-explore-url.hooks.ts`'s file header
 * for the full trace).
 *
 * @complexity Time O(n) in `files.length`.
 */
function initialSelectedPath(
  files: ThemeExploreFile[],
  {
    fileId,
    pageId,
    apiVersion,
  }: { fileId: string | undefined; pageId: string | undefined; apiVersion: 2 | undefined }
): { path: string | null; missed: string | null } {
  const requested = resolveRequestedThemeExploreSelection(files, { fileId, pageId });
  if (requested.path !== null) return requested;
  return { path: defaultSelectedPath(files, apiVersion), missed: requested.missed };
}

/**
 * The error a failed rename reports: a `NAME_TAKEN` conflict names the taken `name`, any other
 * `Error` its own message, and anything else a generic fallback. Pulled out of `performRename`'s
 * `catch` under the complexity ceiling.
 */
function renameErrorMessage(e: unknown, name: string, t: Translate): string {
  if (e instanceof ApiError && e.code === "NAME_TAKEN") {
    return translateWith(t, "'{name}' already exists in this theme", "name", name);
  }
  return e instanceof Error ? e.message : t("failed to rename file");
}

/** Copy for the reset route's 409 codes, keyed by `ApiError.code`. `{file}` is the file being reset. */
const RESET_REFUSAL_COPY: ReadonlyMap<string, string> = new Map([
  ["ORIGINAL_LAYOUT_MISMATCH", "This theme's saved original doesn't match its current layout, so its files can't be reset."],
  ["NOT_IN_ORIGINAL", "{file} isn't in this theme's original, so there's nothing to reset it to."],
  ["NO_ORIGINAL", "This theme has no stored original, so nothing can be reset."],
]);

/**
 * The error a failed reset of `path` reports: the translated copy for a refusal code in
 * {@link RESET_REFUSAL_COPY}, else any `Error`'s own message (a server refusal with no copy here keeps the
 * server's English), else a translated generic fallback. Pulled out of `reset`'s `catch` under the
 * complexity ceiling, like {@link renameErrorMessage}.
 *
 * @complexity O(k) in the message length.
 */
function resetErrorMessage(e: unknown, path: string, t: Translate): string {
  const copy = e instanceof ApiError && e.code !== undefined ? RESET_REFUSAL_COPY.get(e.code) : undefined;
  if (copy !== undefined) return translateWith(t, copy, "file", path);
  return e instanceof Error ? e.message : t("failed to reset file");
}

export function useThemeExplore(
  themeId: string,
  { port, t }: ThemeExploreDependencies,
  { pageId, fileId }: ThemeExploreOptions = {}
): ThemeExploreController {
  const detailKey = useMemo(() => ["themes", "detail", themeId] as const, [themeId]);
  // One definition of "read this theme's detail", used both as the loader's own default fetch and by
  // `cachedReads.getThemeDetail` below for any id.
  const detailFetchFor = useCallback((id: string) => () => port.getThemeDetail(id), [port]);
  const fetchDetail = useMemo(() => detailFetchFor(themeId), [detailFetchFor, themeId]);
  const detailLoader = useCachedLoader({ key: detailKey, fetch: fetchDetail }, { staleTime: 0 });
  const sourceKey = useMemo(() => ["themes", "source", themeId] as const, [themeId]);
  // No default fetch: every file read names its own `["themes", "file", id, path]` key and fetch (see
  // `cachedReads.getThemeFile`), so an argument-less `load()` here would be a bug — the loader rejects it.
  const sourceLoader = useCachedLoader<Awaited<ReturnType<ThemeExplorePort["getThemeFile"]>>>({ key: sourceKey }, { staleTime: 0 });
  const cachedReads = useMemo<ThemeExplorePort>(() => ({ ...port,
    getThemeDetail: id => detailLoader.load({ key: ["themes", "detail", id], fetch: detailFetchFor(id) }),
    getThemeFile: (id, path) => sourceLoader.load({ key: ["themes", "file", id, path], fetch: () => port.getThemeFile(id, path) }),
  }), [port, detailLoader, sourceLoader, detailFetchFor]);
  const listingKey = useMemo(() => ["themes", "explore", themeId] as const, [themeId]);
  const fetchListing = useCallback(() => fetchThemeExploreState(themeId, cachedReads), [themeId, cachedReads]);
  const listingQuery = useFetchQuery({ key: listingKey, fetch: fetchListing }, { staleTime: 0 });
  const listingLoader = useCachedLoader({ key: listingKey, fetch: fetchListing }, { staleTime: 0 });
  const write = useFetchMutation({ run: ({ input }: { input: () => Promise<unknown> }) => input() }, { invalidates: [["themes"]] });
  const [detail, setDetail] = useState<ThemeExploreDetail | null>(null);
  const [files, setFiles] = useState<ThemeExploreFile[]>([]);
  const [selected, setSelected] = useState<string | null>(null);
  const [view, setView] = useState<ThemeExploreView>("preview");
  const [source, setSource] = useState("");
  const [savedSource, setSavedSource] = useState("");
  // The theme and path `source`/`savedSource` were last set from by a read, save or text-returning
  // reset (see `sourceLoaded`). Keyed by theme too, so opening another theme at the same path does not
  // count as loaded before that theme's own read lands. A rename of that file moves it along (see
  // `loadedFileAfterRename`).
  const [loadedFile, setLoadedFile] = useState<{ themeId: string; path: string } | null>(null);
  // A click, or a `?file=`/`?page=` change, that `select` or the initial-load effect is holding
  // (see `shouldAwaitFileText`), keyed by theme. Cleared when that read settles, or when another
  // action sets the selection itself (a load, copy, rename or delete).
  const [pendingSelection, setPendingSelection] = useState<{ themeId: string; path: string } | null>(null);
  // Bumped by every `select` and by every start of the initial-load effect, so that effect can tell a
  // click landed after it started and must not be overridden (see `requestedSelectionMove`).
  const selectionGeneration = useSettlementGeneration();
  // The theme whose listing `files` holds, as last set by the initial-load effect. A later click only
  // outranks a reselect of that same listing. During a theme switch, the click was on the old theme's
  // list.
  const listedThemeRef = useRef<string | null>(null);
  // Bumped to read the open file again without changing the selection: only after a reset that
  // returned no text.
  const [fileReadNonce, setFileReadNonce] = useState(0);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [previewNonce, setPreviewNonce] = useState(0);
  const [resetting, setResetting] = useState(false);
  const [resetConfirmOpen, setResetConfirmOpen] = useState(false);
  const [savingOriginal, setSavingOriginal] = useState(false);
  // A ref, not `savingOriginal`: two clicks in the same tick both read the stale `false` from state.
  const savingOriginalRef = useRef(false);
  const [renamingPath, setRenamingPath] = useState<string | null>(null);
  const [renameDraft, setRenameDraft] = useState("");
  const [renaming, setRenaming] = useState(false);
  const [pageRenameWarning, setPageRenameWarning] = useState<{ path: string; name: string } | null>(null);
  // Monotonic per-call id (extracted into `useSettlementGeneration` 2026-09-06, same shape as
  // `use-themes.hooks.ts`'s own `activateSettlement`/`downloadSettlement`): `commitRename`/
  // `confirmPageRename` both funnel into `performRename` with no guard against a SECOND rename
  // starting (on a different file) before the first settles, and network completion order does not
  // have to match click order. A stale settlement (checked before every state write below, not just
  // the success path, since an out-of-order FAILURE would otherwise resurrect a stale error over a
  // newer rename's real outcome — `error` here is one shared field across every action in this hook)
  // is dropped instead of overwriting whatever the latest rename already produced.
  const renameSettlement = useSettlementGeneration();
  const [copyingPath, setCopyingPath] = useState<string | null>(null);
  // Check-then-set in-flight guard for `copyFile` (2026-09-05 fix, same shape and same reason
  // `use-static-publish.hooks.ts`'s `publishingRef`/`use-sites.hooks.ts`'s `creatingRef` document):
  // the OLD `copyingPath !== null` check alone was state-based, so a genuine same-tick double-fire
  // (two calls landing in the same synchronous tick, before React re-renders with `copyingPath`
  // reflecting the first call) could still slip both calls past it — proven with a probe test
  // calling `copyFile` twice inside one `act()` callback, which reached the port twice. This is a
  // plain `useRef`, not `copyingPath`, because the read-then-write has to be synchronous to be safe
  // against exactly that same-tick case.
  const copyingRef = useRef(false);
  const [deleteTarget, setDeleteTarget] = useState<string | null>(null);
  const [deleting, setDeleting] = useState(false);
  const [publishing, setPublishing] = useState(false);
  // `t` as of the last commit, for every toast below. Effects and settlements read it here rather than
  // listing `t` as a dependency: a caller may pass a new translator each render, and that must neither
  // re-run the initial load nor change the actions' identities.
  const tRef = useRef(t);
  useLayoutEffect(() => {
    tRef.current = t;
  });

  // The editor state as of the last commit. A refresh read settles after renders its own closure never
  // saw, so it checks this instead (see `shouldAdoptRefreshedText`). A layout effect writes it during
  // the commit itself, so no settlement can land between a commit and the snapshot catching up. The
  // initial-load effect's reselect reads it too, for the same reason.
  const openFileRef = useRef<SelectionHoldSnapshot>({ themeId, selected, source, savedSource, loadedFile, view });
  useLayoutEffect(() => {
    openFileRef.current = { themeId, selected, source, savedSource, loadedFile, view };
  });

  useEffect(() => {
    let cancelled = false;
    const generation = selectionGeneration.next();
    listingLoader.load()
      .then(({ detail: nextDetail, files: nextFiles }) => {
        if (cancelled) return;
        // `?file=`/`?page=` when the caller named one (through the shared resolver), else the
        // theme's own index page — `loadTheme` requires it, so a valid theme always has one. See
        // {@link initialSelectedPath}. Deliberately does NOT write back to the address bar itself —
        // loading `?theme=basic` bare should not rewrite the URL the instant the default page
        // resolves, the same "only a real user action moves the URL" restraint
        // `use-media-tabs.hooks.ts`'s own `setActiveTab` follows; only {@link select} below does.
        const { path, missed } = initialSelectedPath(nextFiles, {
          fileId,
          pageId,
          apiVersion: nextDetail.apiVersion,
        });
        // Decided from the commit-time snapshot, not this closure: the view, the open file and a click
        // can all have moved while the listing was in flight. MUST be computed before `listedThemeRef`
        // is updated below.
        const move = requestedSelectionMove({
          themeId,
          path,
          files: nextFiles,
          open: openFileRef.current,
          clickedSinceLoad: !selectionGeneration.isCurrent({ generation }),
          listedThemeId: listedThemeRef.current,
        });
        setDetail(nextDetail);
        setFiles(nextFiles);
        listedThemeRef.current = themeId;
        if (move.kind === "skip") return;
        if (move.kind === "hold") {
          // Same hold as a click (see `select`): the open file stays on screen until the requested
          // file's text lands.
          setPendingSelection({ themeId, path: move.path });
        } else {
          setSelected(move.path);
          setPendingSelection(null);
        }
        // Only when something was actually asked for and NEITHER param resolved to a file this
        // theme has — an intentional layered fallback (`fileId` failing over to a valid `pageId`)
        // is not a miss. This is the fix for the owner-reported bug: a stale/mistyped link must
        // never look like it silently opened a different, valid file with nothing amiss.
        if (missed !== null) setError(translateWith(tRef.current, "\"{name}\" isn't a page or file in this theme.", "name", missed));
      })
      .catch((e) => {
        if (!cancelled) setError(e instanceof Error ? e.message : tRef.current("failed to load theme"));
      });
    return () => {
      cancelled = true;
    };
    // `fileId`/`pageId` are deps so that changing `?file=`/`?page=` in the address bar reselects, the
    // same way changing `?theme=` reloads. Neither one moves on an ordinary re-render — `pageId` only
    // ever moves on a genuine cross-screen navigation (`Pages.tsx`'s "Theme Pages" links), and `fileId`
    // only via the SAME kind of navigation or a real page load, never as a side effect of this screen's
    // own `select` (see `writeThemeExploreSelectionToUrl`'s own doc, `theme-explore-url.hooks.ts`,
    // for why that write deliberately does not notify this effect) — so this does not refetch on an
    // ordinary click, and re-running the INITIAL-load effect is exactly right on the navigations
    // where it does move. `selectionGeneration` has a stable identity, so listing it here never re-runs
    // this effect on its own — it only lets `.then` tell a click landed after this run started. A
    // reselect in the HTML view holds like a click, and a click after the reselect started wins (see
    // `requestedSelectionMove`).
  }, [themeId, port, pageId, fileId, selectionGeneration]);

  useEffect(() => {
    const listing = listingQuery.data;
    if (!listing || listedThemeRef.current !== themeId) return;
    setDetail(listing.detail);
    setFiles(previous => withServerModifiedState(previous, listing.files));
  }, [listingQuery.data, themeId]);

  // The effect below keys off the open file's `readable` flag, not the whole `files` array. A list
  // update that leaves that flag alone (the modified-state refresh after a save or reset, a publish
  // toggle, a rename or delete of another file) must not re-read the open file: that would overwrite
  // `source` and discard edits typed since.
  const selectedReadable = files.find((f) => f.path === selected)?.readable;
  const sourceLoaded = isOpenFileLoaded(loadedFile, themeId, selected);
  // The read below is for a click `select` is holding, else the open file. It keys off that file's own
  // `readable` flag and loaded state, for the same reason given for `selectedReadable` above.
  const readPath = readPathFor(pendingSelection, themeId, selected);
  const readPathReadable = files.find((f) => f.path === readPath)?.readable;
  const readPathLoaded = isOpenFileLoaded(loadedFile, themeId, readPath);

  const textKey = useMemo(() => ["themes", "file", themeId, readPath ?? "", fileReadNonce] as const, [themeId, readPath, fileReadNonce]);
  const fetchText = useCallback(() => cachedReads.getThemeFile(themeId, readPath!), [themeId, readPath, cachedReads]);
  useFetchQuery({ key: textKey, fetch: fetchText }, { enabled: readPath !== null && readPathReadable !== false && !readPathLoaded, staleTime: 0 });
  const textLoader = useCachedLoader({ key: textKey, fetch: fetchText }, { staleTime: 0 });
  // `fileReadNonce` is a dependency only so a reset that returned no text can re-run this read. Every
  // outcome opens `readPath` (a no-op when it is already `selected`) and drops a held click in the same
  // render its buffer lands in, so the HTML tab never shows a file as open before its text is there.
  useEffect(() => {
    if (readPath === null) return;
    // Non-text files are never fetched as text. `readFileSync(…, "utf8")` on a PNG returns mojibake,
    // and saving that back would genuinely corrupt the file — so the request is not made at all
    // rather than made and then guarded against in the UI. Gated on `readable`, NOT `editable`: a
    // script is not editable but IS readable, and still needs its source fetched to be viewed.
    if (readPathReadable === false) {
      setSelected(readPath);
      setPendingSelection(null);
      setSource("");
      setSavedSource("");
      // Also drop the loaded-file marker, not just the buffer: `loadedFile` otherwise still names
      // this exact theme/path from BEFORE the flip (a full `files` refetch — rename/copy/delete of
      // some other file — can bring the same selected path back reporting `readable: false`, with
      // `selected` never asked to change), so `sourceLoaded` stayed wrongly true straight through the
      // transition and `save`'s guard never caught it.
      setLoadedFile(null);
      return;
    }
    // Already open with its text. Clicking the open file again while another file's text is held
    // cancels that switch, and must not read the open file again over edits typed since.
    if (readPathLoaded) return;
    let cancelled = false;
    textLoader.load()
      .then((r) => {
        if (cancelled) return;
        setSelected(readPath);
        setPendingSelection(null);
        setSource(r.content);
        setSavedSource(r.content);
        setLoadedFile({ themeId, path: readPath });
      })
      .catch((e) => {
        if (cancelled) return;
        // A failed read still opens the file, unloaded: the error toast says why, and Save refuses.
        setSelected(readPath);
        setPendingSelection(null);
        setError(e instanceof Error ? e.message : tRef.current("failed to read file"));
      });
    return () => {
      cancelled = true;
    };
  }, [themeId, readPath, readPathReadable, readPathLoaded, port, fileReadNonce]);

  // Same stale-settlement guard as `renameSettlement` above: two saves, or a save then a reset, can
  // have their detail reads land out of order, and the older read must not overwrite the newer one.
  // Dropping it loses nothing, since the newer read carries every file's state.
  const modifiedRefreshSettlement = useSettlementGeneration();
  // Successful file-list mutations invalidate older notification reads before their own refetch.
  // Failed mutations leave those reads valid: an external change still needs to reach the editor.

  /**
   * Re-read every file's `modified`/`resettable` after a Save or Reset changed a file's bytes, or a
   * content refresh said an assistant run may have. Neither mutation's response can answer it: PUT
   * returns only `path`/`bytes`, and reset's `wasModified` is the state BEFORE the reset. The client
   * never infers it either, because saving a file's original bytes back makes it unmodified. Merged
   * through {@link withServerModifiedState}. A failed read is its own error: the save or reset already
   * succeeded and stays reported as done. A read for a theme that is no longer open is dropped, or its
   * flags would merge into the new theme's files wherever the two share a path (`theme.json`).
   * Notifications also reconcile the list's shape. A removed clean file opens the ordinary default;
   * a removed dirty file keeps its buffer and leave guard, but Save cannot recreate it by accident.
   * @complexity O(f) in listed files after one detail request; buffer comparisons are O(s) in text.
   */
  const refreshModifiedState = useCallback(async (
    { reconcileFiles }: { reconcileFiles?: boolean } = {},
  ): Promise<ThemeExploreFile[] | null> => {
    const generation = modifiedRefreshSettlement.next();
    const stillCurrent = () => modifiedRefreshSettlement.isCurrent({ generation }) && openFileRef.current.themeId === themeId;
    try {
      const { detail: nextDetail, files: serverFiles } = await listingLoader.load();
      if (!stillCurrent()) return null;
      if (!reconcileFiles) {
        setFiles((prev) => withServerModifiedState(prev, serverFiles));
        return serverFiles;
      }
      setDetail(nextDetail);
      setFiles(serverFiles);
      if (keepsOpenFileSelected({ serverFiles, open: openFileRef.current, themeId })) return serverFiles;
      const path = defaultSelectedPath(serverFiles, nextDetail.apiVersion);
      setPendingSelection(null);
      setSelected(path);
      setLoadedFile(null);
      setSource("");
      setSavedSource("");
      const file = serverFiles.find((entry) => entry.path === path);
      if (file) writeThemeExploreSelectionToUrl(file);
      return serverFiles;
    } catch (e) {
      if (!stillCurrent()) return null;
      setError(e instanceof Error ? e.message : tRef.current("failed to refresh file list"));
      return null;
    }
  }, [themeId, port, modifiedRefreshSettlement]);

  // Its own generation rather than `modifiedRefreshSettlement`, so a Save's or Reset's detail read never
  // cancels a text read. `shouldAdoptRefreshedText` already drops a read one of those overtook.
  const openFileTextSettlement = useSettlementGeneration();
  useEffect(() => () => {
    modifiedRefreshSettlement.next();
    openFileTextSettlement.next();
  }, [modifiedRefreshSettlement, openFileTextSettlement]);

  /**
   * After a content refresh, re-read the open file and adopt its text when an assistant run changed it.
   * Only a loaded file with no unsaved edits is read ({@link refreshableOpenFilePath}), and
   * {@link shouldAdoptRefreshedText} drops the result unless the editor is still in that state on the
   * same file. `loadedFile` is left alone, so the editor never renders unloaded (the blank flash
   * `c14a6b63` fixed). A failed read keeps the text on screen and is reported while that file is open.
   */
  const refreshOpenFileText = useCallback(async () => {
    const started = openFileRef.current;
    const path = refreshableOpenFilePath(started);
    if (path === null) return;
    const generation = openFileTextSettlement.next();
    try {
      const { content } = await cachedReads.getThemeFile(started.themeId, path);
      if (!openFileTextSettlement.isCurrent({ generation })) return;
      if (!shouldAdoptRefreshedText({ started, current: openFileRef.current, content })) return;
      setSource(content);
      setSavedSource(content);
      setPreviewNonce((n) => n + 1);
    } catch (e) {
      if (!openFileTextSettlement.isCurrent({ generation }) || !isSameOpenFile(openFileRef.current, started)) return;
      setError(e instanceof Error ? e.message : tRef.current("failed to read file"));
    }
  }, [port, openFileTextSettlement]);

  /** List first: never request text for a file the external writer just removed. */
  const refreshFromContentBus = useCallback(() => {
    void refreshModifiedState({ reconcileFiles: true }).then((serverFiles) => {
      if (serverFiles?.some((file) => file.path === openFileRef.current.selected)) void refreshOpenFileText();
    });
  }, [refreshModifiedState, refreshOpenFileText]);
  useContentRefreshSubscription(THEME_FILES_RESOURCE, refreshFromContentBus);
  useEffect(() => subscribeThemePreviewRefresh({ listener: refreshFromContentBus }), [refreshFromContentBus]);

  const save = useCallback(async () => {
    // Nothing is written unless `source` is the open file's own text. A read that is in flight or
    // failed, or a reset that returned no text, leaves some other buffer there (see `sourceLoaded`).
    // A listed, readable file is required too, as defence in depth: it is the same condition
    // `sourceLoaded` is supposed to already rule out, but a save must never depend on the file-read
    // effect's `loadedFile` clear being the only thing standing between a stale buffer and the server.
    // An externally deleted file may deliberately still have an unsaved buffer open.
    if (selected === null || !sourceLoaded || selectedReadable !== true) return;
    setSaving(true);
    setError(null);
    try {
      await write.mutate({ input: () => port.putThemeFile(themeId, selected, source) }) as Awaited<ReturnType<typeof port.putThemeFile>>;
      setSavedSource(source);
      setNotice(translateWith(tRef.current, "Saved {file}", "file", selected));
      setPreviewNonce((n) => n + 1);
    } catch (e) {
      setError(e instanceof Error ? e.message : tRef.current("failed to save file"));
      return;
    } finally {
      setSaving(false);
    }
    await refreshModifiedState();
  }, [themeId, selected, sourceLoaded, selectedReadable, source, port, refreshModifiedState]);

  /**
   * Restore the open file to its catalog original.
   *
   * Overwrites the working copy with no backup, so the caller is expected to have confirmed with the
   * operator first — `resetConfirmOpen` below is that gate. Deliberately NOT wired to the ⌘S-style
   * convenience path for the same reason.
   */
  const reset = useCallback(async () => {
    if (selected === null) return;
    setResetting(true);
    setError(null);
    try {
      const r = await write.mutate({ input: () => port.resetThemeFile(themeId, selected) }) as Awaited<ReturnType<typeof port.resetThemeFile>>;
      // Adopt the server's returned content rather than re-fetching: it is the text of the bytes just
      // restored, so the editor cannot briefly show the pre-reset source. `null` means the file is
      // past the server's text-read limit. Its bytes are restored, but there is no text to edit, so
      // the editor is emptied and left unloaded, and the file is read again: GET `/file` refuses it,
      // which lands on the same error and the same unsaveable state as opening that file directly.
      if (r.content === null) {
        setSource("");
        setSavedSource("");
        setLoadedFile(null);
        setFileReadNonce((n) => n + 1);
      } else {
        setSource(r.content);
        setSavedSource(r.content);
        setLoadedFile({ themeId, path: selected });
      }
      setNotice(translateWith(tRef.current, "Reset {file} to the original", "file", selected));
      setPreviewNonce((n) => n + 1);
      setResetConfirmOpen(false);
    } catch (e) {
      setError(resetErrorMessage(e, selected, tRef.current));
      return;
    } finally {
      setResetting(false);
    }
    await refreshModifiedState();
  }, [themeId, selected, port, refreshModifiedState]);

  /**
   * Save the theme's current files as its stored original, then re-read the detail (same contract as
   * {@link copyFile}: the save is done whatever the re-read says — see `refetchAfterMutation`). No
   * confirmation: it overwrites nothing, and the server refuses a theme that already has an original.
   */
  const saveOriginal = useCallback(async () => {
    if (savingOriginalRef.current) return;
    savingOriginalRef.current = true;
    setSavingOriginal(true);
    setError(null);
    try {
      await write.mutate({ input: () => port.saveThemeOriginal(themeId) }) as Awaited<ReturnType<typeof port.saveThemeOriginal>>;
      modifiedRefreshSettlement.next();
      setNotice(tRef.current("Saved as this theme's original"));
      const refetched = await refetchAfterMutation(themeId, cachedReads, tRef.current);
      if (!refetched.ok) {
        setError(refetched.message);
        return;
      }
      setDetail(refetched.detail);
      setFiles(refetched.files);
    } catch (e) {
      setError(e instanceof Error ? e.message : tRef.current("failed to save the original"));
    } finally {
      setSavingOriginal(false);
      savingOriginalRef.current = false;
    }
  }, [themeId, port, modifiedRefreshSettlement]);

  /**
   * Actually perform a rename against the server and reconcile local state — the one place both the
   * inline-edit fast path and the page-URL-change confirm dialog end up, so the two entry points
   * cannot land on two different post-rename behaviors.
   *
   * Refetches the whole theme detail rather than patching `files` in place: the server is
   * authoritative for the renamed entry's `resettable`/`modified`/`published` (a file moved off its
   * catalog original's path has no original to reset to there, and a renamed page has a new page
   * id), and a targeted patch would have to reproduce that logic a second time to stay correct. The
   * extension never changes: the rename route refuses that (`EXTENSION_CHANGE_NOT_ALLOWED`).
   *
   * The open file keeps its text through a rename: see `loadedFileAfterRename`.
   */
  const performRename = useCallback(
    async (sourcePath: string, name: string) => {
      const generation = renameSettlement.next();
      setRenaming(true);
      setError(null);
      try {
        const r = await write.mutate({ input: () => port.renameThemeFile(themeId, sourcePath, name) }) as Awaited<ReturnType<typeof port.renameThemeFile>>;
        modifiedRefreshSettlement.next();
        const refetched = await refetchAfterMutation(themeId, cachedReads, tRef.current);
        // Superseded by a newer rename call started after this one — that later call owns
        // `detail`/`files`/`selected`/`notice` now, and applying this stale result would let
        // whichever rename happens to settle LAST win regardless of which file was actually
        // renamed last. See `renameSettlement`'s doc comment above.
        if (!renameSettlement.isCurrent({ generation })) return;
        // The rename is done whatever the re-read says — see `refetchAfterMutation`.
        setNotice(translateWith(tRef.current, "Renamed to {file}", "file", r.path));
        setPreviewNonce((n) => n + 1);
        if (!refetched.ok) {
          setError(refetched.message);
          return;
        }
        const { detail: nextDetail, files: nextFiles } = refetched;
        setDetail(nextDetail);
        setFiles(nextFiles);
        // Functional: the operator may have opened another file while this rename was in flight, and
        // the selection and the loaded-file marker must follow the same current state. A rename of the
        // open file keeps its text loaded (see `loadedFileAfterRename`), so the editor never renders
        // unloaded and no re-read discards unsaved edits.
        const renamed = nextFiles.find((f) => f.path === r.path);
        setSelected((current) => renamedPath(current, sourcePath, r.path));
        setLoadedFile((current) => loadedFileAfterRename(current, { themeId, from: sourcePath, to: r.path, renamed }));
        setPendingSelection(null);
      } catch (e) {
        if (!renameSettlement.isCurrent({ generation })) return;
        setError(renameErrorMessage(e, name, tRef.current));
      } finally {
        if (!renameSettlement.isCurrent({ generation })) return;
        setRenaming(false);
        setRenamingPath(null);
        setRenameDraft("");
      }
    },
    [themeId, port, renameSettlement, modifiedRefreshSettlement]
  );

  const startRename = useCallback(
    (path: string) => {
      const kind = files.find((f) => f.path === path)?.kind;
      const apiVersion = detail?.apiVersion;
      if (lockedIdentityPaths(apiVersion).includes(path) || (kind !== undefined && IDENTITY_LOCKED_GROUPS.has(kind))) {
        setError(lockedIdentityChangeReason(path, apiVersion, "renamed", tRef.current));
        return;
      }
      setError(null);
      setRenamingPath(path);
      setRenameDraft(basenameOf(path));
    },
    [files, detail]
  );

  const cancelRename = useCallback(() => {
    setRenamingPath(null);
    setRenameDraft("");
  }, []);

  /**
   * Validate and dispatch the current `renameDraft`. A page (other than the locked index, which
   * never reaches here) is diverted to `pageRenameWarning` instead of renaming immediately — renaming
   * it changes its public URL, and that is worth a pause the way Reset's confirm dialog is, even
   * though a rename is not itself destructive to file contents the way Reset is.
   */
  const commitRename = useCallback(() => {
    if (renamingPath === null) return;
    const sourcePath = renamingPath;
    const name = renameDraft.trim();
    const currentBase = basenameOf(sourcePath);

    if (name.length === 0) {
      setError(tRef.current("Name cannot be empty"));
      return;
    }
    if (name.includes("/") || name.includes("\\")) {
      setError(tRef.current("Name cannot contain a path separator"));
      return;
    }
    if (name === currentBase) {
      cancelRename();
      return;
    }

    const file = files.find((f) => f.path === sourcePath);
    if (file?.kind === "page") {
      setRenamingPath(null);
      setPageRenameWarning({ path: sourcePath, name });
      return;
    }

    setRenamingPath(null);
    void performRename(sourcePath, name);
  }, [renamingPath, renameDraft, files, performRename, cancelRename]);

  const confirmPageRename = useCallback(async () => {
    if (!pageRenameWarning) return;
    const { path, name } = pageRenameWarning;
    setPageRenameWarning(null);
    await performRename(path, name);
  }, [pageRenameWarning, performRename]);

  const cancelPageRenameWarning = useCallback(() => setPageRenameWarning(null), []);

  /**
   * Duplicate a file. No confirmation step by design ("it'll just copy it right in the sidebar" —
   * the owner's own framing) — offered for every group, including read-only-to-edit ones, since
   * copying bytes changes nothing about the source and nothing any existing reference points at.
   */
  const copyFile = useCallback(
    async (path: string) => {
      if (copyingRef.current) return;
      copyingRef.current = true;
      setCopyingPath(path);
      setError(null);
      try {
        const r = await write.mutate({ input: () => port.copyThemeFile(themeId, path) }) as Awaited<ReturnType<typeof port.copyThemeFile>>;
        modifiedRefreshSettlement.next();
        // The copy is done whatever the re-read says — see `refetchAfterMutation`. Selecting the new
        // file waits for a list that has it.
        setNotice(translateWith(tRef.current, "Copied to {file}", "file", r.path));
        const refetched = await refetchAfterMutation(themeId, cachedReads, tRef.current);
        if (!refetched.ok) {
          setError(refetched.message);
          return;
        }
        setDetail(refetched.detail);
        setFiles(refetched.files);
        setSelected(r.path);
        setPendingSelection(null);
      } catch (e) {
        setError(e instanceof Error ? e.message : tRef.current("failed to copy file"));
      } finally {
        setCopyingPath(null);
        copyingRef.current = false;
      }
    },
    [themeId, port, modifiedRefreshSettlement]
  );

  /**
   * Begin deleting `path` — same client-side pre-check shape {@link startRename} uses: a required
   * file or an {@link IDENTITY_LOCKED_GROUPS} member is refused immediately (with `error` set to why)
   * rather than opening the confirmation, avoiding a pointless round trip for the common case. The
   * server (`explore.ts`'s `validateFileIdentityChange`) is the real enforcement point regardless.
   */
  const openDeleteConfirm = useCallback(
    (path: string) => {
      const kind = files.find((f) => f.path === path)?.kind;
      const apiVersion = detail?.apiVersion;
      if (lockedIdentityPaths(apiVersion).includes(path) || (kind !== undefined && IDENTITY_LOCKED_GROUPS.has(kind))) {
        setError(lockedIdentityChangeReason(path, apiVersion, "deleted", tRef.current));
        return;
      }
      setError(null);
      setDeleteTarget(path);
    },
    [files, detail]
  );

  const closeDeleteConfirm = useCallback(() => setDeleteTarget(null), []);

  /**
   * Commit the delete of `deleteTarget`. DESTRUCTIVE and, unlike Reset, not recoverable from this
   * screen at all — there is no backup and no "restore from original" once the file itself is gone.
   * `openDeleteConfirm`'s own confirmation dialog is the only thing standing between a click and this.
   *
   * Refetches the whole theme detail rather than patching `files` in place, matching
   * {@link performRename}/{@link copyFile}'s own reasoning: the server is authoritative for what the
   * theme's file list looks like after the change. If the deleted file was the one open, selection
   * falls back to the theme's default page — the same fallback the initial load effect uses when
   * nothing in particular was requested — rather than pointing at a path that no longer exists.
   */
  const confirmDelete = useCallback(async () => {
    if (deleteTarget === null) return;
    const path = deleteTarget;
    setDeleting(true);
    setError(null);
    try {
      await write.mutate({ input: () => port.deleteThemeFile(themeId, path) }) as Awaited<ReturnType<typeof port.deleteThemeFile>>;
      modifiedRefreshSettlement.next();
      // The file is gone from here on, whatever the re-read says — see `refetchAfterMutation`. The
      // dialog closes and the notice says so; a failed re-read drops the file from the list locally
      // (the one change a delete makes to it) and is reported as its own error.
      setDeleteTarget(null);
      setPendingSelection(null);
      setNotice(translateWith(tRef.current, "Deleted {file}", "file", path));
      const refetched = await refetchAfterMutation(themeId, cachedReads, tRef.current);
      const next = refetched.ok ? refetched : { detail, files: files.filter((f) => f.path !== path) };
      if (refetched.ok) setDetail(refetched.detail);
      else setError(refetched.message);
      setFiles(next.files);
      setSelected((current) => (current === path ? defaultSelectedPath(next.files, next.detail?.apiVersion) : current));
    } catch (e) {
      setError(e instanceof Error ? e.message : tRef.current("failed to delete file"));
    } finally {
      setDeleting(false);
    }
  }, [themeId, deleteTarget, port, detail, files, modifiedRefreshSettlement]);

  // Unsaved-changes guard for the open file's buffer — `current` is `source`, `original` is
  // `savedSource` while it is actually the loaded file's own text (`null` otherwise, matching the
  // old inline `sourceLoaded && source !== savedSource` this replaces). Declared here, ABOVE
  // `select`, because `select` calls `confirmLeave` before switching files; `dirty`/`confirmLeave`
  // are returned to the controller below under their original names. `useDirtyGuard`'s own
  // `beforeunload` listener also closes this screen's other gap from the same review finding: there
  // was no warning at all for leaving the TAB with unsaved theme-file edits.
  const { isDirty: dirty, confirmLeave } = useDirtyGuard({ current: source, original: sourceLoaded ? savedSource : null }, { host: window, translate: (key) => key });

  /**
   * Select a file, and mirror it into the address bar for shareability — `?page=<label>` for an
   * ordinary page, `?file=<path>` for anything else. See
   * {@link writeThemeExploreSelectionToUrl}'s own doc (`theme-explore-url.hooks.ts`) for why the
   * two forms differ and why that write is a plain `history.replaceState` rather than a round trip
   * through this app's `navigate()`.
   *
   * Switching away from a dirty buffer is confirmed first ({@link confirmLeave} — Opus themes+widgets
   * review, OPEN item 1: this used to discard unsaved edits with no prompt at all, the moment another
   * file was clicked). Reselecting the same path is not gated — there is nothing to leave.
   *
   * In the HTML view a readable file is not opened here: the click is held until its text is read (see
   * {@link shouldAwaitFileText}) and the file-read effect opens it. The address bar and
   * `highlightedPath` still follow the click at once.
   *
   * Every click also bumps `selectionGeneration`, so a `?file=`/`?page=` reselect that started earlier
   * cannot override it.
   */
  const select = useCallback(
    (path: string) => {
      if (path !== selected && !confirmLeave()) return;
      selectionGeneration.next();
      const file = files.find((f) => f.path === path);
      if (file) writeThemeExploreSelectionToUrl(file);
      if (shouldAwaitFileText({ view, file, path, selected, sourceLoaded })) {
        setPendingSelection({ themeId, path });
        return;
      }
      setPendingSelection(null);
      setSelected(path);
    },
    [files, view, selected, sourceLoaded, themeId, selectionGeneration, confirmLeave]
  );

  /**
   * Publish or unpublish the currently SELECTED file's page — a no-op if it has no publish state at
   * all (not a page, or `index`/`404`/a declared template shell), matching {@link save}/{@link reset}'s
   * own "acts on `selected` implicitly" shape.
   *
   * Patches `files` locally rather than refetching the whole theme detail the way rename/copy/delete
   * do: the response already names the exact page and its new state, and — even on a theme's FIRST
   * toggle, when the server backfills every other already-published page into `publishedPages` — every
   * OTHER page's own `isStandaloneThemePage` result is unchanged by that backfill (it only ever
   * records what was already true), so there is nothing a refetch would learn that this response does
   * not already say.
   */
  const setPagePublished = useCallback(
    async (published: boolean) => {
      const file = files.find((f) => f.path === selected);
      if (!file || file.published === null) return;
      const pageId = file.label; // page files' label is already the basename minus `.html` — the page id.
      setPublishing(true);
      setError(null);
      try {
        const r = await write.mutate({ input: () => port.setPagePublished(themeId, pageId, published) }) as Awaited<ReturnType<typeof port.setPagePublished>>;
        setFiles((prev) => prev.map((f) => (f.path === file.path ? { ...f, published: r.published } : f)));
        setNotice(translateWith(tRef.current, r.published ? "Published {page}" : "Unpublished {page}", "page", pageId));
      } catch (e) {
        setError(e instanceof Error ? e.message : tRef.current("failed to update publish state"));
      } finally {
        setPublishing(false);
      }
    },
    [themeId, selected, files, port]
  );

  /**
   * ⌘S / Ctrl+S saves the open file.
   *
   * `preventDefault` is the load-bearing half, and it runs even when there is nothing to save: the
   * browser's own "Save Page As…" dialog is what ⌘S does otherwise, and a text editor that opens a
   * file-download dialog on the universal save chord is worse than one with no shortcut at all. So
   * the key is always swallowed on this screen, and only the SAVE is conditional.
   *
   * Bound to `window` in a capture-phase-free listener rather than to the textarea, because the
   * chord should work from anywhere on the screen — after clicking a file in the sidebar, or with
   * focus in the preview toolbar — not only while the caret happens to be in the editor.
   */
  useEffect(() => {
    function onKeyDown(event: KeyboardEvent) {
      if (!(event.metaKey || event.ctrlKey) || event.key.toLowerCase() !== "s") return;
      event.preventDefault();
      if (!dirty || saving || selected === null) return;
      void save();
    }
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [dirty, saving, selected, save]);

  return {
    detail,
    files,
    selected,
    select,
    highlightedPath: readPath,
    view,
    setView,
    source,
    setSource,
    dirty,
    confirmLeave,
    sourceLoaded,
    saving,
    error,
    dismissError: () => setError(null),
    notice,
    dismissNotice: () => setNotice(null),
    save,
    resetting,
    resetConfirmOpen,
    openResetConfirm: () => setResetConfirmOpen(true),
    closeResetConfirm: () => setResetConfirmOpen(false),
    reset,
    savingOriginal,
    saveOriginal,
    previewNonce,
    renamingPath,
    renameDraft,
    setRenameDraft,
    startRename,
    cancelRename,
    commitRename,
    renaming,
    pageRenameWarning,
    confirmPageRename,
    cancelPageRenameWarning,
    copyingPath,
    copyFile,
    deleteTarget,
    openDeleteConfirm,
    closeDeleteConfirm,
    deleting,
    confirmDelete,
    publishing,
    setPagePublished,
    t,
  };
}

/**
 * Binds the real `/api/.../themes/:id` file-editing client and a `themes-i18n.ts`-bound
 * translator — see `theme-explore-dependencies.hooks.ts`.
 *
 * The zero-argument-dependencies half of the `useX(dependencies)` / `useWiredX()` pair, so
 * `ThemeExplore.tsx` composes this and a test composes {@link useThemeExplore} with
 * `createFakeThemeExplorePort`.
 */
export function useWiredThemeExplore(themeId: string, options: ThemeExploreOptions = {}): ThemeExploreController {
  const locale = useAdminLocale();
  const t = (key: string): string => translateThemes({ locale: locale, key: key });
  return useThemeExplore(themeId, { port: defaultThemeExplorePort, t }, options);
}

/**
 * @file The push-to-talk state machine — pure, no DOM/Electron/audio APIs — so every transition
 * and every indicator label is directly testable without mocking a microphone.
 *
 * Trigger decision (owner-facing, see this feature's handoff notes for the full reasoning): this
 * is a HOLD gesture on the mic button itself (`pointerdown` starts, `pointerup`/`pointerleave`
 * stops) — never a keybinding on the composer's own textarea. Space is an ordinary character in a
 * text box; scoping the gesture to a button element outside the textarea means normal typing is
 * never at risk of being hijacked, regardless of composer focus or content.
 */

/** `"cancelling"`: the hold ended (key released, or the button lost the pointer) while still
 *  waiting on the permission prompt (`"requesting-mic"`). There is no capture to stop yet at that
 *  point — `usePushToTalk`'s own `startHold().then()` is what actually releases the microphone,
 *  once permission resolves, by checking whether the machine landed here instead of `"recording"`. */
export type PushToTalkStatus = "idle" | "requesting-mic" | "recording" | "transcribing" | "error" | "cancelling";

export interface PushToTalkState {
  status: PushToTalkStatus;
  /** Present only when `status === "error"` — the reason to show the user. */
  errorReason?: string;
}

export type PushToTalkEvent =
  | { type: "start" }
  | { type: "mic-granted" }
  | { type: "mic-denied"; reason: string }
  | { type: "stop" }
  | { type: "transcript-ready" }
  | { type: "transcribe-failed"; reason: string }
  | { type: "dismiss-error" };

export const INITIAL_PUSH_TO_TALK_STATE: PushToTalkState = { status: "idle" };

type TransitionKey = `${PushToTalkStatus}:${PushToTalkEvent["type"]}`;

/**
 * One entry per legal transition, keyed by `"<currentStatus>:<eventType>"`. Any key not present
 * here means "ignore this event in this state" (e.g. a stray `stop` while idle, or a second
 * `start` while already recording) — {@link nextPushToTalkState} falls back to the unchanged
 * state rather than throwing, since a race between a fast double-press and an in-flight async step
 * is a real possibility, not a bug to crash on.
 *
 * The `as` casts below are safe: each key already pins down exactly which event shape reaches its
 * handler (e.g. only `"requesting-mic:mic-denied"` maps to the handler reading `.reason`), which
 * TypeScript cannot see through a plain string-keyed record but {@link nextPushToTalkState}'s own
 * lookup guarantees.
 */
/** Builds the `"error"` state, shared by both failure transitions below. */
function errorState(event: PushToTalkEvent): PushToTalkState {
  return { status: "error", errorReason: (event as { reason: string }).reason };
}

const TRANSITIONS: Partial<Record<TransitionKey, (event: PushToTalkEvent) => PushToTalkState>> = {
  "idle:start": () => ({ status: "requesting-mic" }),
  "requesting-mic:mic-granted": () => ({ status: "recording" }),
  "requesting-mic:mic-denied": errorState,
  // The hold ended before the permission prompt resolved — see `PushToTalkStatus`'s own doc on
  // `"cancelling"` for why this can't go straight to `"idle"`: `mic-granted`/`mic-denied` are
  // still coming, asynchronously, and the machine has to be somewhere that tells `usePushToTalk`
  // to release the mic instead of starting to record it.
  "requesting-mic:stop": () => ({ status: "cancelling" }),
  "recording:stop": () => ({ status: "transcribing" }),
  "transcribing:transcript-ready": () => ({ status: "idle" }),
  "transcribing:transcribe-failed": errorState,
  "error:dismiss-error": () => ({ status: "idle" }),
  "error:start": () => ({ status: "requesting-mic" }),
  // Permission finally settled after the hold already ended. Neither outcome starts a recording
  // nor shows an error — nobody is watching this prompt anymore.
  "cancelling:mic-granted": () => ({ status: "idle" }),
  "cancelling:mic-denied": () => ({ status: "idle" }),
};

/**
 * Advances the state machine by one event. Table-driven rather than a nested switch, so adding a
 * transition never raises this function's own branching — it stays a single lookup regardless of
 * how many states/events exist.
 *
 * @complexity Time/space: O(1).
 */
export function nextPushToTalkState(state: PushToTalkState, event: PushToTalkEvent): PushToTalkState {
  const transition = TRANSITIONS[`${state.status}:${event.type}`];
  return transition ? transition(event) : state;
}

export interface PushToTalkIndicator {
  /** English copy, doubling as its own i18n key per this repo's convention — the caller passes it
   *  through `t()`. */
  label: string;
  /** `"assertive"` only while recording or on failure — states the user must not miss even if
   *  looking elsewhere; `"polite"` for the rest. */
  ariaLive: "polite" | "assertive";
  /** Drives the unmistakable recording indicator (pulsing dot, red state) — `true` in exactly one
   *  state, `"recording"`, never inferred from any other field. */
  isRecording: boolean;
}

/**
 * Maps a state to what the user should see and hear (via `aria-live`) — the single source of truth
 * for "is the mic live right now," so the indicator can never drift from the state machine that
 * actually owns the microphone.
 *
 * @complexity Time/space: O(1).
 */
export function describePushToTalkIndicator(state: PushToTalkState): PushToTalkIndicator {
  switch (state.status) {
    case "idle":
      return { label: "Hold to talk", ariaLive: "polite", isRecording: false };
    case "requesting-mic":
      return { label: "Requesting microphone…", ariaLive: "polite", isRecording: false };
    case "recording":
      return { label: "Recording — release to send", ariaLive: "assertive", isRecording: true };
    case "transcribing":
      return { label: "Transcribing…", ariaLive: "polite", isRecording: false };
    case "error":
      return { label: state.errorReason ?? "Voice input failed", ariaLive: "assertive", isRecording: false };
    case "cancelling":
      // The hold is already over from the user's own point of view (they released the button) —
      // same resting copy as `"idle"`, not a distinct "cancelling…" message nobody would be
      // holding still long enough to read.
      return { label: "Hold to talk", ariaLive: "polite", isRecording: false };
  }
}

import { useCallback, useEffect, useRef, useState } from "react";

import { getVoiceInputPort, type VoiceInputAvailability, type VoiceInputPort } from "../voice-input-port";
import { NO_DESKTOP_SHELL_REASON, describeVoiceUnavailability } from "../voice-unavailability";
import { createMicPushToTalkCapture, type PushToTalkCapture } from "./mic-capture";
import {
  INITIAL_PUSH_TO_TALK_STATE,
  describePushToTalkIndicator,
  nextPushToTalkState,
  type PushToTalkIndicator,
  type PushToTalkState,
} from "./push-to-talk-state.hooks";

/**
 * @file Orchestrates the push-to-talk gesture: resolves the voice port, probes availability once,
 * and drives {@link nextPushToTalkState} from whichever input started the hold — the mic button's
 * pointer events, or the hold-space gesture in `use-space-hold-to-talk.hooks.ts`. All decision
 * logic (which transitions are legal, what the indicator says) lives in
 * `push-to-talk-state.hooks.ts` and is tested there directly; this hook's own job is wiring that
 * pure machine to real input events and the injectable {@link PushToTalkCapture} side effect —
 * tested here against a FAKE capture (see `__tests__/use-push-to-talk.hooks.unit.test.ts`), not a
 * real microphone.
 */

/** A capture failure's `Error#message`, or a fixed fallback for a non-`Error` rejection (the DOM's
 *  own `getUserMedia` rejections are always real `Error`s, but a fake in a test might not be).
 *  @complexity Time/space: O(1). */
export function describeCaptureError(error: unknown): string {
  return error instanceof Error ? error.message : "Unknown error";
}

export interface UsePushToTalkOptions {
  /** Called with the transcribed text once a recording finishes with non-empty content. Wire this
   *  to the composer's own text setter. */
  onTranscript: (text: string) => void;
}

export interface UsePushToTalkOverrides {
  /** Defaults to `getVoiceInputPort(undefined)`. Pass `null` in a test to simulate a plain browser
   *  tab (no desktop shell). */
  voicePort?: VoiceInputPort | null;
  /** Defaults to {@link createMicPushToTalkCapture}. A test passes a fake that never touches
   *  `getUserMedia`/`AudioContext`. */
  createCapture?: (port: VoiceInputPort) => PushToTalkCapture;
}

export interface PushToTalkController {
  /** `null` while the one-time availability probe is in flight — the affordance renders nothing at
   *  all in that window rather than flashing an "unavailable" state that corrects itself a tick
   *  later. `false` once confirmed unavailable (no desktop shell, or on-device recognition not
   *  installed), with {@link PushToTalkController.unavailableReason} saying why. */
  available: boolean | null;
  /** Operator-facing copy for the `available === false` case; `undefined` in every other state.
   *  Already mapped out of the port's machine-readable code by `describeVoiceUnavailability`. */
  unavailableReason: string | undefined;
  indicator: PushToTalkIndicator;
  /** Opens the microphone. Driven by the mic button's `onPointerDown` AND by the hold-space
   *  gesture (`use-space-hold-to-talk.hooks.ts`) — hence the input-neutral name. */
  startHold: () => void;
  /** Stops recording and transcribes. The button wires this to BOTH `onPointerUp` and
   *  `onPointerLeave` — dragging off the button before releasing must still stop the recording;
   *  the microphone must never stay live with nothing pointing at it. */
  endHold: () => void;
}

/**
 * Splits the probe's raw availability record into the two values the UI actually consumes.
 *
 * Extracted rather than inlined so `usePushToTalk` itself stays inside this repo's complexity
 * ceiling, and so the "no reason while probing, no reason once available" invariant is assertable
 * on its own.
 *
 * @param availability - `null` while the probe is still in flight.
 * @complexity Time/space: O(1).
 */
export function describeAvailability(availability: VoiceInputAvailability | null): {
  available: boolean | null;
  unavailableReason: string | undefined;
} {
  if (availability === null) return { available: null, unavailableReason: undefined };
  if (availability.available) return { available: true, unavailableReason: undefined };
  return { available: false, unavailableReason: describeVoiceUnavailability(availability.reason) };
}

/**
 * Resolves the capture backend to use for a start attempt — the injected override if the caller
 * supplied one, else the real microphone-backed implementation.
 * @complexity Time/space: O(1).
 */
function resolveCreateCapture(overrideCreateCapture: ((port: VoiceInputPort) => PushToTalkCapture) | undefined) {
  return overrideCreateCapture ?? createMicPushToTalkCapture;
}

/**
 * Drives the push-to-talk gesture end to end for one composer mic button.
 *
 * @param options.onTranscript - See {@link UsePushToTalkOptions}.
 * @param overrides - Injectable seams for testing; a real caller omits this entirely.
 * @complexity Time/space: O(1) per call; recording length determines the real capture/transcribe
 *   cost, which this hook does not itself scale with.
 */
export function usePushToTalk(options: UsePushToTalkOptions, overrides: UsePushToTalkOverrides | undefined): PushToTalkController {
  const { onTranscript } = options;
  const voicePort = overrides && "voicePort" in overrides ? overrides.voicePort ?? null : getVoiceInputPort(undefined);
  const createCapture = resolveCreateCapture(overrides?.createCapture);

  const [state, setState] = useState<PushToTalkState>(INITIAL_PUSH_TO_TALK_STATE);
  /** `null` until the probe settles. The whole availability record is held (not just its boolean)
   *  so the port's `reason` reaches the UI: an affordance that says WHY voice input is off is very
   *  different from one that silently vanishes, which just reads as a missing feature. */
  const [availability, setAvailability] = useState<VoiceInputAvailability | null>(null);
  const captureRef = useRef<PushToTalkCapture | null>(null);
  /** The capture whose microphone is open right now — set once permission is granted into a
   *  recording, cleared when a hold stops it. What unmount has to release. */
  const liveCaptureRef = useRef<PushToTalkCapture | null>(null);
  const unmountedRef = useRef(false);

  // Unmounting (closing the assistant, navigating away) runs no pointer handler, so the microphone
  // is released here: a recording capture is stopped now, and a capture still waiting on the
  // permission prompt is stopped by `startHold`'s own `.then` once it resolves (its `setState`
  // updater never runs after unmount, so the release inside it never would).
  useEffect(
    () => () => {
      unmountedRef.current = true;
      const live = liveCaptureRef.current;
      liveCaptureRef.current = null;
      if (live) void live.stopAndTranscribe().catch(() => {});
    },
    [],
  );

  useEffect(() => {
    if (!voicePort) {
      setAvailability({ available: false, reason: NO_DESKTOP_SHELL_REASON });
      return undefined;
    }
    let cancelled = false;
    voicePort
      .isAvailable()
      .then((result) => {
        if (!cancelled) setAvailability(result);
      })
      .catch((error: unknown) => {
        if (!cancelled) setAvailability({ available: false, reason: describeCaptureError(error) });
      });
    return () => {
      cancelled = true;
    };
  }, [voicePort]);

  const { available, unavailableReason } = describeAvailability(availability);
  const canStart = Boolean(voicePort) && available === true && (state.status === "idle" || state.status === "error");

  const startHold = useCallback(() => {
    if (!canStart || !voicePort) return;
    setState((previous) => nextPushToTalkState(previous, { type: "start" }));
    const capture = createCapture(voicePort);
    captureRef.current = capture;
    capture
      .start()
      .then(() => {
        if (unmountedRef.current) {
          void capture.stopAndTranscribe().catch(() => {});
          return;
        }
        liveCaptureRef.current = capture;
        setState((previous) => {
          const next = nextPushToTalkState(previous, { type: "mic-granted" });
          // The hold already ended while this was in flight (`endHold` moved `previous` to
          // `"cancelling"` — see that function and `PushToTalkStatus`'s own doc), so `next` comes
          // back `"idle"`, not `"recording"`. Release the microphone right now instead of leaving
          // it live with nothing pointing at it; the result is discarded; there is no hold to
          // transcribe.
          if (next.status !== "recording") {
            liveCaptureRef.current = null;
            void capture.stopAndTranscribe().catch(() => {});
          }
          return next;
        });
      })
      .catch((error) => setState((previous) => nextPushToTalkState(previous, { type: "mic-denied", reason: describeCaptureError(error) })));
    // `voicePort`/`createCapture` are resolved once per mount, not per render, so listing exactly
    // these three dependencies (not `state` itself) does not risk a stale closure — `canStart`
    // already reads the latest `state.status` on every render this callback is recreated for.
  }, [canStart, voicePort, createCapture]);

  const endHold = useCallback(() => {
    if (state.status === "recording") {
      setState((previous) => nextPushToTalkState(previous, { type: "stop" }));
      // `"recording"` is only reached via `startHold`'s `mic-granted`, which runs after it stored
      // the capture here; nothing clears `captureRef`, so it is always set at this point.
      const capture = captureRef.current!;
      liveCaptureRef.current = null;
      capture
        .stopAndTranscribe()
        .then((text) => {
          setState((previous) => nextPushToTalkState(previous, { type: "transcript-ready" }));
          if (text.trim().length > 0) onTranscript(text);
        })
        .catch((error) => setState((previous) => nextPushToTalkState(previous, { type: "transcribe-failed", reason: describeCaptureError(error) })));
      return;
    }
    // Released while still `"requesting-mic"` (the permission prompt has not resolved yet): there
    // is no capture to stop here — `startHold`'s own `.then()` above holds the only live reference
    // to it, and is what actually releases the microphone once permission settles. Moving to
    // `"cancelling"` is what tells it to do that instead of entering `"recording"`. Every other
    // status (`"idle"`, `"transcribing"`, `"error"`, `"cancelling"` itself) has nothing live to
    // stop, so a stray release there is a no-op, same as before this fix.
    if (state.status === "requesting-mic") {
      setState((previous) => nextPushToTalkState(previous, { type: "stop" }));
    }
  }, [state.status, onTranscript]);

  return { available, unavailableReason, indicator: describePushToTalkIndicator(state), startHold, endHold };
}

import { useEffect } from "react";

/** The shared sidebar has rail tooltips only; expanded CMS labels keep their full translated text. */
export function useCmsSidebarLabelTooltips(
  { navId = "admin-sidebar" }: { navId?: string },
  { doc = document }: { doc?: Document } = {},
): void {
  useEffect(() => {
    const nav = doc.getElementById(navId);
    if (!nav) return;
    const original = new Map<Element, string | null>();
    const update = () => {
      for (const link of nav.querySelectorAll("a.cms-item")) {
        // Sites owns a measured name-only tooltip; Jini still supplies its full rail tooltip.
        if (link.getAttribute("href")?.endsWith("/sites")) { link.removeAttribute("title"); continue; }
        const text = link.querySelector("span")?.textContent;
        if (!text) continue;
        if (!original.has(link)) original.set(link, link.getAttribute("title"));
        link.setAttribute("title", text);
      }
    };
    update();
    // Locale and permission changes can replace labels/rows without remounting the sidebar.
    const observer = new MutationObserver(update);
    observer.observe(nav, { childList: true, characterData: true, subtree: true });
    return () => {
      observer.disconnect();
      for (const [link, title] of original) {
        if (title === null) link.removeAttribute("title");
        else link.setAttribute("title", title);
      }
    };
  }, [doc, navId]);
}

import { useCallback, useEffect, useRef, useState } from "react";

/**
 * @file Auto-collapse the side nav to its icon rail while the assistant dock is open on a window too
 * narrow for both (owner, 2026-10-11: "horrendous" — nav expanded + dock open left the page a
 * phone-width column whose centred rows clipped at the left edge).
 *
 * The rule, chosen as the least surprising of the options: at desktop widths the nav always PUSHES
 * the page (it is a flex sibling, never an overlay); only when the expanded nav (232px) + the dock
 * (380px) + the page's padding would leave the page under {@link MIN_PAGE_WIDTH_PX} does opening the
 * dock fold the nav to its 60px rail. Closing the dock (or widening the window out of that band)
 * puts back whatever the operator's stored preference is. It never persists anything itself, never
 * fights the operator: expanding the nav by hand while the dock is open sticks until the next
 * dock-open or band crossing. Phones/tablets (≤900px) are untouched — there the nav is already the
 * off-canvas drawer with a backdrop (`styles.css`'s RESPONSIVE SHELL), which has no rail.
 *
 * Mechanism: Jini's Sidebar owns the saved preference and accepts a temporary `railOverride`.
 * This hook supplies only the dock/viewport rule and controlled toggle requests: no storage reads,
 * writes or synthetic events. A manual toggle changes the override until the next forcing transition;
 * releasing it reveals the package's current stored preference (including real cross-tab updates).
 */

/** Smallest page width (px, inside `.admin-content`'s padding) the dock + expanded nav may leave. */
export const MIN_PAGE_WIDTH_PX = 480;

/**
 * The viewport band where the auto-rail applies: from the rail's own 901px floor (below it the nav
 * is the mobile drawer) up to expanded nav 232 + dock 380 + page padding 2 × 40 + 480 = 1172px.
 * `1171.98px` rather than `1171px` so a fractional-zoom width just under 1172 still matches.
 */
export const DOCK_AUTO_RAIL_QUERY = "(min-width: 901px) and (max-width: 1171.98px)";

/** The slice of a `MediaQueryList` this hook reads. */
export interface AutoRailMediaQuery {
  readonly matches: boolean;
  addEventListener(type: "change", listener: () => void): void;
  removeEventListener(type: "change", listener: () => void): void;
}

/**
 * Whether the rail should be forced right now: the dock is open AND the window is in the band.
 *
 * @param state.dockOpen - The assistant dock is open (docked, not the phone sheet).
 * @param state.narrow - The viewport matches {@link DOCK_AUTO_RAIL_QUERY}.
 * @complexity O(1)
 */
export function shouldAutoRail(
  { dockOpen, narrow }: { readonly dockOpen: boolean; readonly narrow: boolean },
  _options: Record<string, never> = {},
): boolean {
  return dockOpen && narrow;
}

function defaultMatchMedia(query: string): AutoRailMediaQuery | null {
  return typeof window.matchMedia === "function" ? window.matchMedia(query) : null;
}

/** Props passed directly to Jini's Sidebar; a null override restores its own saved preference. */
export interface DockAutoRail {
  readonly railOverride: boolean | null;
  readonly onRailCollapsedChange: (collapsed: boolean) => void;
}

/**
 * Folds the nav to its rail while the dock is open in a narrow window; releases the override when
 * either stops being true. Jini remains the sole owner of persistence and real cross-tab sync.
 *
 * @param required.dockOpen - `useChatDockLayout().chatOpen`.
 * @param optional.matchMedia - Viewport query port. @default window.matchMedia (null → never folds)
 * @returns Sidebar override props; manual toggles stick until the next dock-open/band transition.
 * @sideeffects One `change` listener on the band's MediaQueryList while mounted; state changes only
 *   on forcing transitions or a controlled toggle request, never on unrelated re-renders.
 * @complexity O(1) per transition.
 */
export function useDockAutoRail(
  { dockOpen }: { readonly dockOpen: boolean },
  {
    matchMedia = defaultMatchMedia,
  }: {
    readonly matchMedia?: (query: string) => AutoRailMediaQuery | null;
  } = {},
): DockAutoRail {
  // Survives the effect re-running on every `dockOpen` change, which is exactly when it is read: a
  // close must know whether the open before it folded the rail (restore) or not (leave it alone).
  const forced = useRef(false);
  const [railOverride, setRailOverride] = useState<boolean | null>(null);

  // Jini requests changes only while controlled. Keep a hand-expanded nav expanded until the next
  // dock-open/band crossing, without changing the operator's saved preference during this override.
  const onRailCollapsedChange = useCallback((collapsed: boolean) => {
    if (forced.current) setRailOverride(collapsed);
  }, []);

  useEffect(() => {
    const band = matchMedia(DOCK_AUTO_RAIL_QUERY);
    if (!band) return;
    const apply = () => {
      const want = shouldAutoRail({ dockOpen, narrow: band.matches });
      if (want === forced.current) return;
      forced.current = want;
      setRailOverride(want ? true : null);
    };
    apply();
    band.addEventListener("change", apply);
    return () => band.removeEventListener("change", apply);
  }, [dockOpen, matchMedia]);

  return { railOverride, onRailCollapsedChange };
}

import { useEffect } from "react";

/**
 * @file Column labels for `.list-table` body cells, so the phone card layout can name each value
 * (mobile catalog P-4, 2026-10-06). On narrow screens `styles.css` turns every `.list-table` row
 * into a stacked card and hides the header row, which leaves bare values like "3" or "0" with
 * nothing saying they are "Fields" or "Hits". About fifteen screens render `.list-table` by hand
 * (there is no shared table component), so instead of threading a `data-label` through each one,
 * the admin shell copies every header cell's text onto its column's body cells as `data-label`,
 * and the card CSS prints it with `attr(data-label)`. Desktop ignores the attribute entirely.
 */

/** Sort glyphs the sortable headers append to their text — not part of the column's name. */
const SORT_GLYPHS = /[⇅▲▼↑↓]/g;

function headerLabels(table: HTMLTableElement): string[] {
  const row = table.tHead?.rows[0];
  if (!row) return [];
  const labels: string[] = [];
  for (const th of Array.from(row.cells)) {
    // Tooltip descriptions and icons are help, not the column title printed on cards.
    const title = th.cloneNode(true) as HTMLTableCellElement;
    title.querySelectorAll('.info-tip, [role="tooltip"], [hidden], [aria-hidden="true"]')
      .forEach((help) => help.remove());
    // An element's `textContent` is never null (only a document's or doctype's is), so no "" fallback.
    const text = (th.getAttribute("data-label") ?? title.textContent).replace(SORT_GLYPHS, "").trim();
    for (let i = 0; i < th.colSpan; i += 1) labels.push(text);
  }
  return labels;
}

function labelRow(row: HTMLTableRowElement, labels: readonly string[]): void {
  let column = 0;
  for (const cell of Array.from(row.cells)) {
    // A spanning cell (an empty-state or inline detail row) belongs to no single column.
    const label = cell.colSpan === 1 ? (labels[column] ?? "") : "";
    if (label && cell.getAttribute("data-label") !== label) cell.setAttribute("data-label", label);
    if (!label && cell.hasAttribute("data-label")) cell.removeAttribute("data-label");
    column += cell.colSpan;
  }
}

/**
 * Labels every `.list-table` body cell under `root` with its column header's text.
 *
 * @complexity O(cells) under `root`.
 */
export function labelListTableCells(root: ParentNode): void {
  for (const table of Array.from(root.querySelectorAll<HTMLTableElement>("table.list-table"))) {
    const labels = headerLabels(table);
    if (labels.length === 0) continue;
    for (const body of Array.from(table.tBodies)) {
      for (const row of Array.from(body.rows)) labelRow(row, labels);
    }
  }
}

/**
 * Keeps {@link labelListTableCells} current for everything rendered inside `root` (the admin's
 * `<main>`). Watches child-list/text changes only — the attribute writes it makes itself are not
 * observed, so it cannot loop. MutationObserver already delivers one batched callback per
 * microtask checkpoint, so a burst (typing in an editor) costs one pass, not one per node; no
 * `requestAnimationFrame` on top, because rAF never fires in a background tab and the labels
 * would silently stop updating there.
 */
export function useListTableCellLabels(root: HTMLElement | null): void {
  useEffect(() => {
    if (!root) return undefined;
    labelListTableCells(root);
    const observer = new MutationObserver(() => labelListTableCells(root));
    observer.observe(root, { childList: true, subtree: true, characterData: true });
    return () => observer.disconnect();
  }, [root]);
}

import { useEffect } from "react";

/**
 * @file Click on EMPTY sidebar space toggles the desktop rail (owner request, 2026-10-05). The
 * rail toggle button is a small target under "AI Assistant"; the whole rail's blank area is a much
 * easier one. It calls the same `toggleRail` `<Sidebar.RailToggle>` calls, so the persisted
 * preference, cross-tab sync and `aria-expanded` on the real button all stay on one path.
 *
 * A native listener on the `<nav>` rather than a React `onClick`: `@jini-ai/admin/react`'s
 * `Sidebar` root takes no event props, and changing that is a package rebuild for one host's
 * layout choice. Pointer-only by construction — keyboard users keep the real toggle button, whose
 * Enter/Space click lands on a `<button>` and is therefore skipped below.
 */

/** Nav rows, including inert Soon items, are never blank space. `[tabindex]` covers custom
 *  focusable widgets; `label` covers form labels that forward clicks to an input. */
export const SIDEBAR_CONTROL_SELECTOR =
  '.cms-item, a, button, input, select, textarea, summary, label, [role="button"], [role="link"], [tabindex]';

/** Same breakpoint as `styles.css`'s `.cms-nav.is-rail` block: below it the nav is the mobile
 *  drawer, which has no rail, so a toggle there would only flip a preference nobody can see. */
const DESKTOP_RAIL_QUERY = "(min-width: 901px)";

/** How far (CSS px, either axis) the pointer may travel between press and release and still count
 *  as a click. The browser fires `click` after a drag that starts and ends on the same element — a
 *  drag across blank rail space did exactly that in a live check and toggled the rail. */
const DRAG_THRESHOLD_PX = 4;

function matchesDesktopRail(): boolean {
  return window.matchMedia(DESKTOP_RAIL_QUERY).matches;
}

export interface SidebarClick {
  readonly target: EventTarget | null;
  readonly button: number;
  readonly defaultPrevented: boolean;
}

/**
 * Whether `event` landed on blank sidebar space: a plain primary click inside `nav`, not on (or
 * inside) any control, and not the end of a drag or a text selection inside the nav.
 *
 * @param event - The click (only `target`, `button`, `defaultPrevented` are read).
 * @param context.nav - The sidebar `<nav>`.
 * @param context.selectingText - True when a non-collapsed selection starts inside `nav`.
 * @param context.dragged - True when the pointer moved past the drag threshold since press.
 */
export function isEmptySidebarClick(
  event: SidebarClick,
  { nav, selectingText, dragged }: { readonly nav: Element; readonly selectingText: boolean; readonly dragged: boolean },
): boolean {
  if (event.button !== 0 || event.defaultPrevented || selectingText || dragged) return false;
  const target = event.target;
  if (!(target instanceof Element) || !nav.contains(target)) return false;
  const control = target.closest(SIDEBAR_CONTROL_SELECTOR);
  return control === null || !nav.contains(control);
}

function movedPastThreshold(from: { x: number; y: number } | null, event: MouseEvent): boolean {
  if (!from) return false;
  return Math.abs(event.clientX - from.x) > DRAG_THRESHOLD_PX || Math.abs(event.clientY - from.y) > DRAG_THRESHOLD_PX;
}

function selectionStartsIn(nav: Element, doc: Document): boolean {
  const selection = doc.getSelection();
  return !!selection && !selection.isCollapsed && nav.contains(selection.anchorNode);
}

/**
 * Wires {@link isEmptySidebarClick} to `toggleRail` on the sidebar `<nav>` found by id.
 *
 * @param required.toggleRail - `useSidebar().toggleRail` — the rail toggle button's own handler.
 * @param optional.navId - The `<nav>`'s id. @default "admin-sidebar" (`Sidebar`'s own default)
 * @param optional.doc - Where to look the nav up and read the selection. @default document
 * @param optional.isDesktop - Whether the rail exists at the current width. @default matchMedia
 * @sideeffects One `pointerdown` and one `click` listener on the nav while mounted.
 */
export function useSidebarEmptyClickToggle(
  { toggleRail }: { readonly toggleRail: () => void },
  {
    navId = "admin-sidebar",
    doc = document,
    isDesktop = matchesDesktopRail,
  }: { readonly navId?: string; readonly doc?: Document; readonly isDesktop?: () => boolean } = {},
): void {
  useEffect(() => {
    const nav = doc.getElementById(navId);
    if (!nav) return;
    let pressedAt: { x: number; y: number } | null = null;
    function onPointerDown(event: PointerEvent) {
      pressedAt = { x: event.clientX, y: event.clientY };
    }
    function onClick(event: MouseEvent) {
      if (!isDesktop() || !nav) return;
      const context = { nav, selectingText: selectionStartsIn(nav, doc), dragged: movedPastThreshold(pressedAt, event) };
      pressedAt = null;
      if (isEmptySidebarClick(event, context)) toggleRail();
    }
    nav.addEventListener("pointerdown", onPointerDown);
    nav.addEventListener("click", onClick);
    return () => {
      nav.removeEventListener("pointerdown", onPointerDown);
      nav.removeEventListener("click", onClick);
    };
  }, [toggleRail, navId, doc, isDesktop]);
}

import { useEffect, useLayoutEffect, useRef, useState, type RefObject } from "react";
import { useSidebar } from "@jini-ai/admin/react";
import type { AdminNavGroup } from "@/nav";
import { translateAdminNavLabel } from "@/lib/admin-nav-i18n";
import { defaultSitesPort } from "@/features/sites/hooks/sites-dependencies.hooks";
import type { SitesPort } from "@/features/sites/hooks/sites-port.hooks";
import { useSitesSnapshot } from "@/features/sites/hooks/use-sites-snapshot.hooks";

export interface SitesSidebarNavOptions {
  port?: Pick<SitesPort, "listSites">;
  doc?: Document;
  /** Read browser layout by default; tests inject exact dimensions without module mocks. */
  measure?: (element: HTMLElement) => { scrollWidth: number; clientWidth: number };
}

function measureSiteName(element: HTMLElement) {
  return { scrollWidth: element.scrollWidth, clientWidth: element.clientWidth };
}

export interface SitesSidebarNavView {
  groups: readonly AdminNavGroup[];
  siteName: string;
  prefix: string;
  suffix: string;
  target: HTMLElement | null;
  nameRef: RefObject<HTMLSpanElement | null>;
  title: string | undefined;
}

function formatSitesSidebarLabel(
  { siteName, locale }: { siteName: string; locale: string },
  _optional: object,
) {
  const plain = translateAdminNavLabel({ locale, key: "Sites" });
  const pattern = translateAdminNavLabel({ locale, key: "Sites ({siteName})" });
  const [prefix, suffix = ""] = pattern.split("{siteName}");
  const label = siteName ? `${prefix}${siteName}${suffix}` : plain;
  return { prefix, suffix, label };
}

/**
 * CMS Sites label adapter over Jini's sidebar and the Sites screen's shared query cache.
 * The shared row still owns its icon, route, accessible name and rail tooltip. A portal supplies
 * only the split visual label because this installed Sidebar has no label-only rendering slot.
 * @returns Markup-ready label parts, portal target, and a native tooltip only for measured overflow.
 * @complexity O(n) in the supplied nav items; one cached Sites read, no per-item requests.
 */
export function useSitesSidebarNav(
  { groups, locale }: { groups: readonly AdminNavGroup[]; locale: string },
  { port = defaultSitesPort, doc = document, measure = measureSiteName }: SitesSidebarNavOptions = {},
): SitesSidebarNavView {
  const { collapsed } = useSidebar();
  const enabled = groups.some((group) => group.items.some((item) => item.id === "sites"));
  const list = useSitesSnapshot({ port }, { enabled });
  // currentSite is the live binding, even for an unlisted site; persistedSiteName awaits restart.
  const siteName = enabled ? list.data?.currentSite.name ?? "" : "";
  const { prefix, suffix, label } = formatSitesSidebarLabel({ siteName, locale }, {});
  const labelledGroups = groups.map((group) => ({ ...group, items: group.items.map((item) => item.id === "sites" ? { ...item, label } : item) }));
  const [target, setTarget] = useState<HTMLElement | null>(null);
  const nameRef = useRef<HTMLSpanElement>(null);
  const [truncated, setTruncated] = useState(false);
  const hasName = Boolean(siteName);

  useEffect(() => {
    const nav = doc.getElementById("admin-sidebar");
    if (!nav || !hasName) { setTarget(null); return; }
    // No row class is added here: React rewrites the shared row's className on every active change.
    // The effect below marks the portal target with an unmanaged attribute React leaves alone.
    const discover = () => setTarget(nav.querySelector<HTMLElement>('a.cms-item[href$="/sites"]'));
    discover();
    // Permission/locale changes can replace the shared row without remounting this adapter.
    const observer = new MutationObserver(discover);
    observer.observe(nav, { childList: true, subtree: true });
    return () => observer.disconnect();
  }, [doc, hasName]);

  // Mark before measuring/painting the split label; cleanup restores the shared label on removal.
  useLayoutEffect(() => {
    if (!target) return;
    target.setAttribute("data-cms-sites-split", "");
    return () => target.removeAttribute("data-cms-sites-split");
  }, [target]);

  useLayoutEffect(() => {
    const element = nameRef.current;
    if (!element) { setTruncated(false); return; }
    const update = () => {
      const { scrollWidth, clientWidth } = measure(element);
      setTruncated(scrollWidth > clientWidth);
    };
    update();
    const observer = typeof ResizeObserver === "undefined" ? undefined : new ResizeObserver(update);
    observer?.observe(element);
    doc.defaultView?.addEventListener("resize", update);
    return () => {
      observer?.disconnect();
      doc.defaultView?.removeEventListener("resize", update);
    };
  }, [target, siteName, collapsed, doc, measure]);

  return { groups: labelledGroups, siteName, prefix, suffix, target, nameRef, title: truncated ? siteName : undefined };
}

import { useEffect, useRef, useState } from 'react';
import type { ExecutionConfig } from '@jini-ai/ui';
import { api, type AdminDeploymentOverview } from '@/lib/api';
import { effectiveExecutionConfig, localCliAllowed, preserveSavedExecutionMode, DEPLOYED_LOCAL_CLI_NOTE } from '@/lib/tovu-execution-policy';
import { isDesktopAdmin } from '@/features/settings/ai-agent-presentation';
import { t } from '@/features/settings/settings-execution-i18n';
import '@/styles/local-cli-policy.css';

type RuntimeSnapshot = Pick<AdminDeploymentOverview, 'mode'>;

/** Tovu's deployment policy shared by every execution entry point; all host IO is injectable.
 * A failed read leaves the gate closed. Cleanup prevents a late response changing another mount.
 * No execution-setting write occurs here: the displayed fallback is not a preference migration. */
export function useTovuExecutionPolicy(
  { config, locale }: { config: ExecutionConfig; locale: string },
  { desktop = isDesktopAdmin({}), loadRuntime = api.getDeploymentOverview }: {
    desktop?: boolean; loadRuntime?: () => Promise<RuntimeSnapshot>;
  } = {},
) {
  const [mode, setMode] = useState<RuntimeSnapshot['mode']>();
  const loader = useRef(loadRuntime);
  const pending = useRef<Promise<RuntimeSnapshot | undefined> | null>(null);
  useEffect(() => {
    if (desktop) return;
    let live = true;
    pending.current = loader.current().then(
      (snapshot) => { if (live) setMode(snapshot.mode); return snapshot; },
      () => undefined, // Unknown capability stays hidden; a reload can retry discovery.
    );
    return () => { live = false; };
  }, [desktop]);
  const allowed = localCliAllowed({ mode, desktop });
  const effective = effectiveExecutionConfig({ config, allowed });
  return {
    allowed,
    config: effective,
    readAllowedForSend: async () => {
      const snapshot = await pending.current;
      return localCliAllowed({ mode: snapshot?.mode ?? mode, desktop });
    },
    visibility: allowed ? 'available' : 'hidden',
    note: !allowed && mode === 'production' && config.mode === 'local-cli' ? t({ locale: locale, key: DEPLOYED_LOCAL_CLI_NOTE }) : null,
    // The shared tab reports its entire projected config on every field edit. Restore only mode.
    preserveChange: (next: ExecutionConfig) => preserveSavedExecutionMode({ saved: config, next, allowed }),
    subtitleKey: allowed ? 'Choose Local CLI or BYOK.' : 'Use your own API credentials',
  };
}

/**
 * @file Tovu's Add-ons URL migration (owner decision, 2026-10-13).
 * Jini still matches stable panel IDs; this adapter translates only Tovu's moved URLs.
 * Legacy redirects are resolved here and executed by the existing IntegrationsRedirect.
 */
export const ADDONS_PANEL_PATHS: Readonly<Record<string, string>> = {
  plugins: "/addons/plugins",
  "agent-plugins": "/addons/agent-plugins",
  skills: "/addons/skills",
  providers: "/addons/integrations",
  integrations: "/addons/integrations?tab=webhooks",
};

export interface AddonsRouteResolution {
  /** Stable-ID path for Jini's matcher; never written to browser history. */
  readonly matchPath: string;
  /** Canonical destination for a legacy URL, absent on current or unrelated routes. */
  readonly redirectPath?: string;
}

/**
 * Resolves moved Add-ons URLs without changing unrelated sections or query bytes.
 * Bare legacy Integrations links keep their former Webhooks default; explicit tabs survive.
 * @param input Base-agnostic route path, including its query string.
 * @returns Matcher path and, for a legacy URL, replacement destination. No side effects/errors.
 * @example resolveAddonsRoute({ routePath: "/providers?tab=webhooks" })
 * @complexity O(n) time and space in URL length; the Add-ons table has five fixed entries.
 */
export function resolveAddonsRoute({ routePath }: { readonly routePath: string }): AddonsRouteResolution {
  const pathname = routePath.replace(/\?.*$/s, "");
  const parts = pathname.split("/").filter(Boolean);
  const route = { parts, query: routePath.slice(pathname.length) };

  if (parts[0] === "addons") return { matchPath: stablePanelPath(route) ?? routePath };
  const redirectPath = legacyRedirectPath(route);
  return redirectPath ? { matchPath: routePath, redirectPath } : { matchPath: routePath };
}

interface SplitRoute {
  /** Non-empty pathname segments, so trailing and doubled slashes do not matter. */
  readonly parts: readonly string[];
  /** Raw query bytes including the leading `?`, or "" when the URL has none. */
  readonly query: string;
}

/**
 * Maps a current `/addons/...` URL back to the stable panel path Jini's matcher knows.
 * @param route Split `/addons/...` route.
 * @returns Stable-ID matcher path, or undefined for an unknown Add-ons URL.
 * @complexity O(n) in URL length; the Add-ons table has five fixed entries.
 */
function stablePanelPath({ parts, query }: SplitRoute): string | undefined {
  if (parts.length === 3 && parts[1] === "integrations") return `/integrations/${parts[2]}${query}`;
  const path = `/${parts.join("/")}`;
  const panel = Object.entries(ADDONS_PANEL_PATHS).find(([, destination]) => destination === path);
  return panel && `/${panel[0]}${query}`;
}

/**
 * Resolves the canonical Add-ons destination for a legacy (pre-move) URL.
 * @param route Split non-Add-ons route.
 * @returns Replacement destination, or undefined for current or unrelated routes.
 * @complexity O(n) in URL length.
 */
function legacyRedirectPath({ parts, query }: SplitRoute): string | undefined {
  const [section = ""] = parts;
  if (parts.length === 2 && section === "integrations") return `${ADDONS_PANEL_PATHS.providers}/${parts[1]}${query}`;
  // `hasOwn` keeps prototype names such as `/constructor` from resolving to a destination.
  if (parts.length !== 1 || !Object.hasOwn(ADDONS_PANEL_PATHS, section)) return undefined;
  if (section === "integrations") return `${ADDONS_PANEL_PATHS.providers}${withDefaultWebhooksTab(query)}`;
  return `${ADDONS_PANEL_PATHS[section]}${query}`;
}

/** Bare legacy Integrations links keep their former Webhooks default; explicit tabs survive. */
function withDefaultWebhooksTab(query: string): string {
  if (new URLSearchParams(query).has("tab")) return query;
  return `${query}${query ? "&" : "?"}tab=webhooks`;
}

/**
 * @file The `admin.capture_screenshot` executor — the assistant's only way to see the admin's actual
 * rendered pixels rather than DOM structure (`page.find_elements`).
 *
 * ## Wiring
 *
 * `App.hooks.tsx`'s `useAgentPageBridge` registers {@link renderAdminScreenshotCanvas} (indirectly,
 * through {@link captureAdminScreenshotToolResult}) under `createFrontendSessionBridge`'s
 * `executors: {"admin.": ...}` prefix map — the same host-extension seam that file's own module doc
 * describes `chat.*`/`page.*` claiming, just exercised here by a Tovu-native verb instead of a Jini
 * one. The capability id and description live server-side in
 * `apps/website/src/assistant/frontend-control-capabilities.ts`; {@link ADMIN_CAPTURE_SCREENSHOT_CAPABILITY_ID}
 * is duplicated here because apps/admin and apps/website are separate builds with no shared-types
 * package for this — the same cross-boundary-string discipline `assistant-transport.ts`'s
 * `frontendBindToken` envelope key already relies on. `agent-screenshot.unit.test.ts` pins the two
 * strings equal so they cannot silently drift.
 *
 * The tool result shape (`{content: [{type:'text', ...}, {type:'image', mimeType, data}]}`) is
 * `assistant_demo_image`'s already-proven typed-media envelope
 * (`apps/website/src/assistant/demo-image-tool.ts`), reused verbatim rather than inventing a second
 * one: the daemon's `extractResultMedia` (`@jini-ai/daemon`) recognizes this shape generically, on
 * ANY tool's raw output, and lifts its `image` blocks into the `tool_result.media` wire field that
 * `ToolCard` renders inline — regardless of which registration mechanism produced the result. This
 * capability's registration mechanism (`createFrontendCapabilityRegistrations`, projected from
 * `FrontendCapabilitySpec`) is different from `assistant_demo_image`'s
 * (`buildDomainRegistrations`), but both ultimately hand the SAME shape to the SAME generic
 * extraction step, which is what makes reusing the shape (rather than the registration mechanism)
 * the correct thing to reuse.
 *
 * ## Capture mechanism — why in-page rasterization, not a screen-share prompt or headless Chromium
 *
 * Three ways to get pixels out of a browser were considered:
 *
 * 1. **In-page DOM rasterization (`html2canvas-pro`) — chosen.** Runs over the SAME frontend-control
 *    channel already proven live, needs no OS-level permission prompt, and captures the operator's
 *    ACTUAL current view: scroll position, open panels, in-progress form edits. This is exactly the
 *    state a "does this look cramped/broken" question is about.
 *
 *    **Why the `-pro` fork, not plain `html2canvas`.** Confirmed live (Playwright, 2026-08-30) against
 *    the real admin dashboard: upstream `html2canvas@1.4.1` (unmaintained since ~2022) throws
 *    `Error: Attempting to parse an unsupported color function "oklch"` and aborts the ENTIRE capture
 *    the instant it walks any element using an `oklch()` color — which `apps/admin/src/styles.css`
 *    and several feature stylesheets (`source-control.css`, `media.css`, `select.css`,
 *    `access-tokens.css`) already do. This is not a fidelity gap like the ones below; it is a hard
 *    failure that would make every real capture throw on this app specifically. `html2canvas-pro`
 *    (actively maintained, API-compatible fork adding `oklch`/`lab`/`lch`/`color-mix` support) was
 *    verified against the same real DOM with the identical call and produced a valid
 *    996x804 JPEG (~41KB) with no errors — see this file's handoff notes for the full before/after.
 * 2. **`navigator.mediaDevices.getDisplayMedia()`.** True pixels, but the browser prompts for
 *    permission on EVERY capture (no way to pre-authorize a screen-share session for a chat tool
 *    call) and, worse, would let the assistant capture the whole screen or another window/tab, not
 *    just this one admin tab — a strictly larger blast radius than option 1 for no fidelity gain on
 *    the actual use case. Disqualified: the owner's own ask was to REMOVE a manual step, and a
 *    permission dialog on every screenshot reintroduces exactly that friction.
 * 3. **Server-side headless Chromium against an authenticated URL.** True pixels and high fidelity,
 *    but it renders a FRESH page load — wrong scroll position, no open dialog, no in-progress edit,
 *    none of the state that made the operator ask in the first place. `site-evidence/browser-port.ts`
 *    (Tovu's own existing headless-browser adapter) already documents that Chromium may be entirely
 *    ABSENT from a self-hosted Tovu image, which would make this capability silently unavailable in
 *    exactly the deployments most likely to need it (an operator with no screenshot tool of their
 *    own). Reproducing the admin's authenticated, mid-edit tab state in a second browser process
 *    would also require re-deriving session/auth/route state server-side — a much larger and more
 *    fragile undertaking than option 1.
 *
 * ## What this capture CANNOT see — read before trusting an empty region
 *
 * - **Cross-origin iframes render BLANK.** This is the loud one: every MCP-UI surface the assistant
 *   itself has rendered is a sandboxed iframe (see `reference_mcp_ui_surface_agent_driveability`),
 *   so a rendered MCP-UI card is invisible in this capture. A blank rectangle where a card should be
 *   is NOT evidence that nothing rendered.
 * - Cross-origin `<img>` elements without permissive CORS headers taint the canvas and render blank.
 * - `<canvas>`/WebGL content and `<video>` frames frequently do not rasterize correctly.
 * - Only the `<main>` content area is captured (never the assistant's own chat dock, which sits
 *   outside it — see `App.hooks.tsx`'s `useAgentPageBridge` doc for why that boundary already
 *   exists), and only what is clipped to the CURRENT viewport — content scrolled out of view is not
 *   included, by design (see {@link renderAdminScreenshotCanvas}).
 * - Complex CSS (filters, some blend modes, a custom font not yet loaded) can visually drift from
 *   what a person actually sees, since `html2canvas-pro` approximates computed styles via a cloned
 *   DOM rather than reading real compositor output.
 *
 * ## Privacy — see `agent-screenshot-bus.ts`'s module doc for the consent decision
 *
 * Every successful capture publishes {@link publishScreenshotCaptured} so the admin sees an
 * announcement, never a silent capture. This module does not call that bus directly — see this
 * file's own wiring note in `App.hooks.tsx` for why that stays the caller's responsibility.
 */

/** Mirrors `@jini-ai/daemon`'s `ToolResultTextBlock`/`ToolResultImageBlock` field names exactly
 *  (`tool-result-media.ts`) — this is the wire shape `extractResultMedia` recognizes, not a new one.
 *  Redeclared locally rather than imported: apps/admin has no dependency on `@jini-ai/daemon`, and
 *  taking one solely for two structural field names would be a heavier coupling than restating them. */
export type ScreenshotContentBlock = { readonly type: "text"; readonly text: string } | { readonly type: "image"; readonly mimeType: string; readonly data: string };

export interface ScreenshotToolResult {
  readonly content: readonly ScreenshotContentBlock[];
}

/** Must equal the `id` of the `CapabilityDef` this capability is registered under in
 *  `apps/website/src/assistant/frontend-control-capabilities.ts` — see this module's own doc for why
 *  the string is duplicated rather than imported, and `agent-screenshot.unit.test.ts` for the pin. */
export const ADMIN_CAPTURE_SCREENSHOT_CAPABILITY_ID = "admin.capture_screenshot";

/**
 * Raw (pre-base64) byte budget for one capture. Chosen to comfortably clear
 * `agent-daemon-server.ts`'s `express.json({limit: "6mb"})` after base64's ~4/3 inflation
 * (1.5MB * 4/3 ≈ 2MB, well under 6MB with room for the surrounding JSON envelope) while still
 * bounding how many image tokens one tool call can cost the model's context — the same
 * "bound what one call can return" reasoning `site_collect_page_evidence`'s `maxOutputBytes` gives,
 * applied here to an image instead of text.
 */
export const MAX_SCREENSHOT_BYTES = 1_500_000;

/** Encode attempts, in order: a good-looking first try, then a materially smaller fallback. Only
 *  two — a longer ladder would mean more silent quality loss for a shrinking chance of still fitting
 *  an already-oversized capture; past this point the honest answer is the failure result below, not
 *  a third guess. */
const JPEG_QUALITIES = [0.7, 0.4] as const;

/** Read once per successful capture, alongside the image — see this module's own "what this capture
 *  cannot see" section above for the full reasoning; this is the compressed reminder the model
 *  actually reads next to the pixels it just received. */
const FIDELITY_NOTE =
  "Screenshot captured (JPEG, current viewport, admin main content area only). Cross-origin iframes " +
  "(including any MCP-UI surface), cross-origin images without CORS, and canvas/video content may " +
  "render as blank space here — a blank area is not evidence that nothing is there.";

/** A canvas-shaped capture result — exactly the subset of `HTMLCanvasElement` this module calls.
 *  Structural rather than the DOM type itself, so a test fake needs no real `<canvas>`. */
export interface CapturedCanvas {
  toDataURL(type: string, quality: number): string;
}

/** Renders `element` to a canvas. Real implementation: {@link renderAdminScreenshotCanvas}. Injected
 *  so `captureAdminScreenshotToolResult`'s retry/budget logic is testable with no real DOM painting. */
export type RenderElementToCanvas = (element: HTMLElement) => Promise<CapturedCanvas>;

export interface CaptureAdminScreenshotOptions {
  /** `App.hooks.tsx`'s `contentEl` — `null` before it mounts, or if the effect tore the bridge down. */
  readonly element: HTMLElement | null;
  readonly renderElementToCanvas: RenderElementToCanvas;
}

function buildTextBlock(text: string): ScreenshotContentBlock {
  return { type: "text", text };
}

function buildImageBlock(mimeType: string, data: string): ScreenshotContentBlock {
  return { type: "image", mimeType, data };
}

/**
 * Builds a text-only failure result. Exported so a caller integration-testing the full executor path
 * (not exercised by this module's own tests, which assert through {@link captureAdminScreenshotToolResult}
 * instead) can recognize the shape without re-deriving it.
 *
 * @complexity O(1).
 */
export function buildScreenshotFailureResult(reason: string): ScreenshotToolResult {
  return { content: [buildTextBlock(reason)] };
}

/**
 * Splits a `data:<mimeType>;base64,<data>` URL into its two parts.
 *
 * @returns `undefined` for anything not shaped like a base64 data URL — `HTMLCanvasElement.toDataURL`
 * never produces that in practice, but a hand-authored test double could, and silently mis-parsing it
 * into a bogus image block would be worse than treating it as "nothing usable came back."
 * @complexity O(1) (a single bounded regex match; does not scan the base64 payload).
 */
function parseDataUrl(dataUrl: string): { readonly mimeType: string; readonly data: string } | undefined {
  const match = /^data:([^;,]+);base64,(.+)$/s.exec(dataUrl);
  if (!match) return undefined;
  // Both capture groups use a `+` quantifier, so a successful match always carries a non-empty
  // mime type and payload; the non-null assertions restate that regex guarantee for the type system.
  return { mimeType: match[1]!, data: match[2]! };
}

/**
 * Estimates the RAW (decoded) byte size a base64 string represents, without decoding it — decoding a
 * multi-megabyte string just to measure it would be wasted work on every attempt, including the ones
 * this function exists to reject before ever building an image block from them.
 *
 * @complexity O(1) — reads `.length` and up to 2 trailing characters, never the whole string content.
 */
function estimateBase64ByteLength(base64: string): number {
  const padding = base64.endsWith("==") ? 2 : base64.endsWith("=") ? 1 : 0;
  return Math.floor((base64.length * 3) / 4) - padding;
}

/**
 * Encodes `canvas` at each quality in {@link JPEG_QUALITIES}, in order, returning the first attempt
 * that fits {@link MAX_SCREENSHOT_BYTES}. Encodes the SAME already-rendered canvas each time — no
 * re-rasterization — so the retry costs only the cheap `toDataURL` call, not another full render.
 *
 * @returns The fitting result's content blocks, or `undefined` if every quality attempt still
 * exceeds the budget.
 * @complexity O(q) in `JPEG_QUALITIES.length` (a fixed constant, 2 today); each iteration's own cost
 * is `toDataURL`'s (canvas-size-dependent, not this function's to bound) plus O(1) size estimation.
 */
function encodeWithinBudget(canvas: CapturedCanvas): readonly ScreenshotContentBlock[] | undefined {
  for (const quality of JPEG_QUALITIES) {
    const dataUrl = canvas.toDataURL("image/jpeg", quality);
    const parsed = parseDataUrl(dataUrl);
    if (!parsed) continue;
    if (estimateBase64ByteLength(parsed.data) > MAX_SCREENSHOT_BYTES) continue;
    return [buildTextBlock(FIDELITY_NOTE), buildImageBlock(parsed.mimeType, parsed.data)];
  }
  return undefined;
}

/**
 * Answers one `admin.capture_screenshot` invocation: renders `element` (if attached) to a canvas,
 * encodes it within budget, and reports the outcome as model-facing data rather than throwing — the
 * same "evidence, not an exception" posture `site_collect_page_evidence`'s `OriginNotVerifiedError`
 * handling uses, so a capture that cannot happen right now reads as an answer the agent can act on
 * ("ask the operator to reopen the tab") instead of a tool-call error with no actionable content.
 *
 * @complexity O(1) plus `renderElementToCanvas`'s own cost (real-adapter-dependent) and
 * {@link encodeWithinBudget}'s O(q) retry loop.
 */
export async function captureAdminScreenshotToolResult(options: CaptureAdminScreenshotOptions): Promise<ScreenshotToolResult> {
  const { element, renderElementToCanvas } = options;
  if (!element || !element.isConnected) {
    return buildScreenshotFailureResult(
      "no admin content area is currently attached to capture — the admin tab may have navigated away or the page bridge has not finished attaching yet",
    );
  }

  let canvas: CapturedCanvas;
  try {
    canvas = await renderElementToCanvas(element);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return buildScreenshotFailureResult(`screenshot capture failed: ${message}`);
  }

  const content = encodeWithinBudget(canvas);
  if (!content) {
    return buildScreenshotFailureResult(
      "the rendered view was too large to encode within this tool's size budget even after quality reduction — try narrowing the visible area (e.g. collapsing a panel) first",
    );
  }
  return { content };
}

/**
 * The real capture adapter — dynamically imports `html2canvas-pro` so its ~230KB parses only when
 * this capability is actually invoked, not on every admin page load. Not exercised by this module's
 * own unit tests (see this file's module doc): jsdom does not lay out or paint, so a test importing
 * the real library here would assert nothing about real rendering while paying real cost to run it.
 * Real verification is manual/browser (see the handoff's Self-Validation section) — which is what
 * caught the plain-`html2canvas` `oklch()` failure this module doc's "why the -pro fork" note
 * records; a jsdom-based unit test would never have exercised real color parsing and would have
 * shipped that failure silently.
 *
 * Clipped to the CURRENT viewport (`window.innerWidth/innerHeight` at the current scroll offset)
 * rather than `element`'s full scrollable height: a "does this look cramped/clipped" question is
 * almost always about what the operator can see RIGHT NOW at their current window size, and a
 * full-scrollable-height capture would both miss viewport-relative clipping bugs and produce a much
 * larger image for no benefit to that question. `scale: 1` deliberately ignores `devicePixelRatio`
 * (which a `scale` left at its default would otherwise multiply into) — a retina display would triple
 * the pixel count, and therefore the encoded size, for no fidelity the JPEG encode step would
 * preserve anyway at the quality levels {@link JPEG_QUALITIES} uses. `useCORS: true` is best-effort
 * only: an image whose host does not opt in still taints the canvas and renders blank — see this
 * module's own "what this capture cannot see" section.
 *
 * @complexity Not this module's to bound — the library's own DOM-clone-and-paint cost, proportional
 * to the viewport's rendered subtree size.
 */
export async function renderAdminScreenshotCanvas(element: HTMLElement): Promise<CapturedCanvas> {
  const { default: html2canvas } = await import("html2canvas-pro");
  return html2canvas(element, {
    scale: 1,
    useCORS: true,
    x: window.scrollX,
    y: window.scrollY,
    width: window.innerWidth,
    height: window.innerHeight,
    windowWidth: document.documentElement.clientWidth,
    windowHeight: document.documentElement.clientHeight,
  });
}

import { decodeApiError } from "@jini-ai/protocol";
