  // Widgets (SPEC-043, ADR-047) — mirrors the Menus client functions' exact shape
  // -------------------------------------------------------------------------
  listWidgets: (options: { widgetType?: string; includeInactive?: boolean } = {}) => {
    const params = new URLSearchParams();
    if (options.widgetType) params.set("widgetType", options.widgetType);
    if (options.includeInactive) params.set("includeInactive", "true");
    const qs = params.toString();
    // `skippedCount`/`skippedIds` (dossier C5 follow-up, 2026-08-03) are additive and optional —
    // present only when the server dropped one or more malformed records. Absent in the common case.
    return authenticatedAdminRequest<{ widgets: AdminWidget[]; skippedCount?: number; skippedIds?: string[] }>({ method: "GET", path: `/workspaces/${WORKSPACE_ID}/widgets${qs ? `?${qs}` : ""}` });
  },
  getWidget: (id: string) =>
    authenticatedAdminRequest<{ widget: AdminWidget; whereUsed: AdminWidgetWhereUsed }>({ method: "GET", path: `/workspaces/${WORKSPACE_ID}/widgets/${encodeURIComponent(id)}` }),
  createWidget: (
    input: { widgetType: AdminWidgetType; title: string; config: Record<string, unknown> },
    options: { slug?: string } = {}
  ) =>
    authenticatedAdminRequest<{ widget: AdminWidget }>({ method: "POST", path: `/workspaces/${WORKSPACE_ID}/widgets`, body: { ...input, ...options } }),

  // SPEC-005 REQ-12..17 (1.1.0 UI amendment) — consumes REQ-10's PLUGINS_LIST/PLUGIN_SET_ENABLED
  // HTTP contract as a black box (ui.spec.md §3.1/§4.2).
  listPlugins: () => request<{ plugins: AdminPlugin[] }>(`/workspaces/${WORKSPACE_ID}/plugins`),
  /** PLUGIN_PROVIDER_SETTINGS (2026-10-26) — a provider plugin's declared settings card. */
  getPluginProviderSettings: (pluginId: string) =>
    request<AdminPluginProviderSettings>(`/workspaces/${WORKSPACE_ID}/plugins/${encodeURIComponent(pluginId)}/provider-settings`),
  /** Saves and reapplies card values; a blank secret keeps the saved one. */
  savePluginProviderSettings: (pluginId: string, values: Record<string, string>) =>
    request<AdminPluginProviderSettings>(`/workspaces/${WORKSPACE_ID}/plugins/${encodeURIComponent(pluginId)}/provider-settings`, {
      method: "PUT", body: JSON.stringify({ values }),
    }),
  useProjectKey: ({ keyId, use }: { keyId: string; use: boolean }, _optional = {}) =>
    request<{ keyId: string; usedByThisSite: boolean; usedBy: string[]; appliesAt: "now" | "restart" | "failed"; message?: string }>(`/workspaces/${WORKSPACE_ID}/project-keys/${encodeURIComponent(keyId)}/use`, { method: "PUT", body: JSON.stringify({ use }) }),
  setPluginEnabled: (pluginId: string, { enabled }: { enabled: boolean }) =>
    request<{ plugin: { id: string; version: string; enabled: boolean; updatedAt: string }; changeSetId: string }>(
      `/workspaces/${WORKSPACE_ID}/plugins/${encodeURIComponent(pluginId)}`,
      { method: "PATCH", body: JSON.stringify({ enabled }) }
    ),
  /** Moves a site plugin to the 60-day Trash. `PLUGIN_IN_TRASH` reports an existing parked copy. */
  uninstallPlugin: (pluginId: string) =>
    request<{ pluginId: string; trashed: true }>(
      `/workspaces/${WORKSPACE_ID}/plugins/${encodeURIComponent(pluginId)}`,
      { method: "DELETE" }
    ),
  /** PLUGIN_FILES (2026-09-13) — `GET /workspaces/:id/plugins/:pluginId/files`: the read-only,
   *  server-capped listing of one plugin's own files behind the Plugins screen's package-files
   *  viewer. Refuses `PLUGIN_NOT_FOUND` (404) and `PLUGIN_ID_INVALID` (400). */
  getPluginFiles: (pluginId: string) =>
    request<AdminPluginFiles>(`/workspaces/${WORKSPACE_ID}/plugins/${encodeURIComponent(pluginId)}/files`),

  // 2026-09-09 — AGENT_PLUGINS_LIST: the `agent-plugins` screen's read of real installed Agent
  // Plugins (a separate family from listPlugins/setPluginEnabled above — see AdminAgentPlugin's doc).
  listAgentPlugins: () => request<{ agentPlugins: AdminAgentPlugin[] }>(`/workspaces/${WORKSPACE_ID}/agent-plugins`),
  /** AGENT_PLUGIN_FILES (2026-09-13) — `GET /workspaces/:id/agent-plugins/:pluginId/files`: one
   *  installed Agent Plugin's files, switched on or off, behind the Agent Plugins eye button.
   *  Refuses `AGENT_PLUGIN_NOT_FOUND` (404). */
  getAgentPluginFiles: (pluginId: string) =>
    request<AdminAgentPluginFiles>(`/workspaces/${WORKSPACE_ID}/agent-plugins/${encodeURIComponent(pluginId)}/files`),
  /**
   * AGENT_PLUGIN_SET_ENABLED — turns one installed Agent Plugin on or off for this workspace.
   *
   * Returns the SINGLE updated row rather than a `changeSetId`, deliberately unlike
   * `setPluginEnabled` above: that family's route is `executeCommand`-wrapped and its client
   * re-fetches the whole list afterwards, while this one writes one JSON activation record and
   * hands back the row in `listAgentPlugins`' own shape, so the caller replaces it in place with no
   * second GET. See the route's own header for what skipping the gateway costs.
   *
   * `enabled` is validated server-side, not coerced — an omitted or non-boolean value is 400
   * `VALIDATION_ERROR` instead of a silent disable.
   */
  setAgentPluginEnabled: (pluginId: string, { enabled }: { enabled: boolean }) =>
    request<{ agentPlugin: AdminAgentPlugin; warnings?: string[] }>(`/workspaces/${WORKSPACE_ID}/agent-plugins/${encodeURIComponent(pluginId)}`, {
      method: "PATCH",
      body: JSON.stringify({ enabled }),
    }),

  // Deployment panel (`src/server/routes/admin/system/deployment-overview.ts` /
  // `dockerfile-source.ts`) — `system.read`-gated, same shape as `getModuleStatus` just above.
  /** Runtime mode, boot-gate/default-password status, agent-daemon known-failure state, db/uploads
   *  paths, and required-env-var presence (never values) — the Deployment panel's Overview tab. */
  getDeploymentOverview: () =>
    request<AdminDeploymentOverview>(`/workspaces/${WORKSPACE_ID}/system/deployment-overview`),

  // Observability panel, Overview tab (`apps/website/src/server/inbound/admin-http/routes/system/
  // observability-status.ts`) — `system.read`-gated, same shape as `getDeploymentOverview` above.
  /** Whether `platform/observability`'s real OTel adapter is on right now, and under what service
   *  name — never the OTLP endpoint value itself. See {@link AdminObservabilityStatus}. */
  getObservabilityStatus: () =>
    request<AdminObservabilityStatus>(`/workspaces/${WORKSPACE_ID}/system/observability-status`),
  sendObservabilityTestError: () => request<AdminTelemetryTestResult>(`/workspaces/${WORKSPACE_ID}/system/observability/test-error`, { method: "POST" }),
  /** Owner-only filter over native CLI fallback entries in the existing audit store. */
  getToolGaps: () => request<{ entries: import('@jini-ai/daemon/tool-audit').ToolGapEntry[] }>(`/workspaces/${WORKSPACE_ID}/system/tool-gaps`),
  /** Recent captured server log lines (`routes/system/server-logs.ts`, `system.read`-gated) — the
   *  Observability "Recent errors" tab. */
  getServerLogs: (query: AdminServerLogsQuery = {}) => {
    const params = new URLSearchParams(Object.entries(query).filter(([, value]) => value !== undefined).map(([key, value]) => [key, String(value)]));
    const qs = params.toString();
    return request<AdminServerLogs>(`/workspaces/${WORKSPACE_ID}/system/server-logs${qs ? `?${qs}` : ""}`);
  },
  /** Whether outbound email really sends — the form editor greys out its notify settings when not. */
  getMailStatus: () => request<AdminMailStatus>(`/workspaces/${WORKSPACE_ID}/system/mail-status`),

  // Sites panel (`apps/website/src/server/inbound/admin-http/routes/system/sites.ts`) — list is
  // `system.read`, create/activate are `system.write` AND additionally refused with
  // `SITE_SWITCHING_DISABLED` when the deployment capability flag is off. Same `system.*` split as
  // `getDockerfileSource`/`setDockerfileSource` immediately above.
  /** Every site under `sites/`, plus what this server process is ACTUALLY bound to right now and
   *  any pending activate choice — see {@link AdminSitesSnapshot}. */
  getSitesConfig: () => request<SitesUserConfig>(`/workspaces/${WORKSPACE_ID}/system/sites/config`),
  setSitesConfig: (input: SitesUserConfigPatch) => request<SitesUserConfig>(`/workspaces/${WORKSPACE_ID}/system/sites/config`, { method: "PUT", body: JSON.stringify(input) }),
  setSitesHome: (input: { path: string }) => request<{ home: string }>(`/workspaces/${WORKSPACE_ID}/system/sites/home`, { method: "PUT", body: JSON.stringify(input) }),
  listSites: () => request<AdminSitesSnapshot>(`/workspaces/${WORKSPACE_ID}/system/sites`),
  /** Create `sites/<name>/` through the same `initSite` path `tovu init` uses. `409`
   *  `SITE_ALREADY_EXISTS` when the directory is occupied, `400` `VALIDATION_ERROR` for a name
   *  outside `[a-z0-9-]{1,100}`. */
  createSite: (input: { name: string; adminPassword?: string; agentPluginTokens?: Record<string, string> }) =>
    request<{ site: AdminCreatedSite; agentPluginTokens?: AdminCreatedSiteAgentPluginTokens }>(`/workspaces/${WORKSPACE_ID}/system/sites`, {
      method: "POST",
      body: JSON.stringify(input),
    }),
  /** Installed Agent Plugins that take a pasted access token — the create form's optional
   *  "connect now" fields. A given token is checked, then applied on the new site's first start. */
  listTokenSignInPlugins: () =>
    request<{ plugins: AdminTokenSignInPlugin[] }>(`/workspaces/${WORKSPACE_ID}/system/sites/token-sign-in-plugins`),
  /** Persist `name` as the site the NEXT boot serves. Writes `TOVU_SITE=<name>` to the repo-root
   *  `.env` and returns restart instructions — it does not kill, signal, or re-exec anything, and
   *  this process keeps serving whatever it booted with. See {@link AdminSiteActivation}. */
  activateSite: (name: string) =>
    request<AdminSiteActivation>(
      `/workspaces/${WORKSPACE_ID}/system/sites/${encodeURIComponent(name)}/activate`,
      { method: "POST" }
    ),
  manageLocalSite: (input: { name: string; action: AdminLocalSiteAction; confirmed?: boolean; checked?: boolean }) => {
    const name = encodeURIComponent(input.name);
    if (input.action === "switch") return request<AdminSiteActivation>(
      `/workspaces/${WORKSPACE_ID}/system/sites/${name}/activate`, { method: "POST", body: JSON.stringify({ restartNow: true }) });
    const path = input.action === "restore" || input.action === "delete"
      ? `trash/${name}/${input.action}` : `${name}/${input.action}`;
    return request<unknown>(`/workspaces/${WORKSPACE_ID}/system/sites/${path}`, {
      method: "POST", body: JSON.stringify({ confirmed: input.confirmed, checked: input.checked }),
    });
  },
  /** The repo-root `Dockerfile`'s current contents, or `{ exists: false }` when none has been
   *  generated yet, plus its `etag` merged in from the response's own `ETag` header (never the JSON
   *  body — see {@link AdminDockerfileSource.etag}'s own doc). */
  getDockerfileSource: (): Promise<AdminDockerfileSource> => {
    let etag = "";
    return authenticatedAdminRequest<{ exists: boolean; contents: string | null }>(
      { method: "GET", path: `/workspaces/${WORKSPACE_ID}/system/dockerfile` },
      { onOk: (res) => {
        etag = res.headers.get("ETag") ?? "";
      } }
    ).then((body) => ({ ...body, etag }));
  },
  /** 2026-08-15 — `PUT` half of the Dockerfile tab, `system.write`-gated (distinct from the `GET`
   *  above's `system.read`, mirroring `triggerSiteExport`'s own `system.export` vs `system.read`
   *  split below). Overwrites the repo-root Dockerfile with `contents` and returns the snapshot it
   *  now has — this only writes bytes to disk, it never builds or deploys anything.
   *
   *  `ifMatch` (the etag from the last `getDockerfileSource`/`setDockerfileSource` response) is sent
   *  as the `If-Match` request header and REQUIRED by the server — a stale value rejects with a
   *  `412` `ApiError` whose `.body.current` carries the real `{exists, contents}` currently on disk,
   *  a missing/empty one with `400`; see {@link AdminDockerfileSource.etag}'s own doc for why. */
  setDockerfileSource: (contents: string, ifMatch: string): Promise<AdminDockerfileSource> => {
    let etag = "";
    return authenticatedAdminRequest<{ exists: boolean; contents: string | null }>(
      { method: "PUT", path: `/workspaces/${WORKSPACE_ID}/system/dockerfile`, body: { contents } },
      { headers: { "If-Match": ifMatch }, onOk: (res) => {
        etag = res.headers.get("ETag") ?? "";
      } }
    ).then((body) => ({ ...body, etag }));
  },

  // Static Site tab (`src/server/routes/admin/system/export-site.ts`) — trigger + poll, not a
  // single synchronous call: a real export can take seconds to minutes, so `triggerSiteExport`
  // returns the moment the run STARTS (202) and a caller polls `getSiteExportStatus` for the
  // outcome. `system.export`-gated on trigger (writes to disk), `system.read` on the poll.
  /** Starts a new static-site export. `409` (surfaced as a thrown error by `request`, same as any
   *  non-2xx) if one is already running — this instance runs at most one export at a time. */
  triggerSiteExport: (options?: { clean?: boolean; basePath?: string }) =>
    request<AdminExportRunSnapshot>(`/workspaces/${WORKSPACE_ID}/system/export`, {
      method: "POST",
      body: JSON.stringify(options ?? {}),
    }),
  /** The current/most recent export run's status — poll this after `triggerSiteExport` until
   *  `status` is no longer `"running"`. */
  getSiteExportStatus: () => request<AdminExportRunSnapshot>(`/workspaces/${WORKSPACE_ID}/system/export`),

  // Static Site tab "Getting it online" card (`src/server/routes/admin/system/publish-site.ts`) —
  // publishing the current export straight to an installed static host plugin's target.
  // Same trigger+poll shape as
  // the export pair just above, plus a third pure-read preview route with no run of its own.
  /** Read-only: validates `config`, reports the base path a real publish would use (always
   *  SERVER-derived — see {@link AdminStaticPublishConfig}'s own doc), and whether a credential is
   *  configured for the target (a boolean only, never the credential itself). Never starts a run. */
  getPublishPreview: (config: AdminStaticPublishConfig) => {
    const query = new URLSearchParams({ ...config.fields, target: config.target });
    return request<AdminStaticPublishPreview>(`/workspaces/${WORKSPACE_ID}/system/publish/preview?${query.toString()}`);
  },
  /** The deploy targets the installed hosting plugins provide, with their publish and credential
   *  form fields — the publish card renders from this. */
  getPublishTargets: () =>
    request<{ targets: AdminPublishTargetDescriptor[] }>(`/workspaces/${WORKSPACE_ID}/system/publish-targets`).then((res) => res.targets),
  /** Starts a new publish to `config.target`. `409` (surfaced as a thrown error) if one is already
   *  running — this instance runs at most one publish at a time, independent of a plain export.
   *
   *  `credentialId` names the saved connection the operator chose, and BINDS the publish to it
   *  (terra review 2026-09-20, finding 1 — Critical): without it the server resolved whichever row
   *  was `is_default` when the POST landed, so picking connection B and clicking Publish while B's
   *  promotion was still in flight published the site to A's account. The server validates the id
   *  against this workspace and this target and REFUSES on a mismatch — it never falls back to the
   *  default (`static-publish/credentials.ts`). Omitted entirely (never sent as an explicit
   *  `undefined`) when this provider has no saved connection — an install publishing from server
   *  env vars has no connection ids at all, and that caller keeps the default lookup. */
  triggerPublish: (input: { config: AdminStaticPublishConfig; projectName: string; credentialId?: string }) =>
    request<AdminPublishRunSnapshot>(`/workspaces/${WORKSPACE_ID}/system/publish`, {
      method: "POST",
      body: JSON.stringify({
        ...input.config.fields,
        target: input.config.target,
        projectName: input.projectName,
        ...(input.credentialId !== undefined ? { credentialId: input.credentialId } : {}),
      }),
    }),
  /** The current/most recent publish run's status — poll this after `triggerPublish` until `status`
   *  is no longer `"running"`. */
  getPublishStatus: () => request<AdminPublishRunSnapshot>(`/workspaces/${WORKSPACE_ID}/system/publish`),
  /** Past static publishes, Tovu peers pushed to, and deploys of this site, newest first. Read-only:
   *  publishing again still goes through `triggerPublish` or the publish-content push. */
  listPublishDestinations: () =>
    request<AdminPublishDestination[]>(`/workspaces/${WORKSPACE_ID}/system/publish/destinations`),

  // Static Site tab "Getting it online" card → credential management (`src/server/routes/admin/
  // system/publish-credentials.ts`) — named provider connections for `triggerPublish`, stored
  // encrypted server-side and never read back. See `AdminPublishCredentialSummary`'s own doc for
  // exactly what a saved row can and cannot reveal.
  /** Every configured credential for this workspace, plus the server's own `executionMode` — the
   *  ONLY source of truth for whether this instance can drive a CLI locally or needs a stored
   *  credential to publish at all. Never sniffed client-side; see `AdminPublishExecutionMode`'s doc. */
  listPublishCredentials: () =>
    request<AdminPublishCredentialsSnapshot>(`/workspaces/${WORKSPACE_ID}/system/publish/credentials`),
  /** Creates one named connection. `409 DUPLICATE_LABEL` (surfaced as a thrown `ApiError` with that
   *  `code`) if this workspace already has a credential with the same label — labels are the only
   *  human-facing identifier a reader has for telling two connections apart, so silently allowing a
   *  second row with the same one would make the list ambiguous. `isDefault` is optional — omitted
   *  entirely (not `false`) lets the server apply its own default-assignment rule (e.g. a provider's
   *  first-ever saved connection), rather than this admin guessing at it. */
  createPublishCredential: (input: { label: string; connection: AdminPublishConnectionInput; isDefault?: boolean; worksFor?: string[] }) =>
    request<{ credential: AdminPublishCredentialSummary; verification?: AdminPublishCredentialVerification }>(`/workspaces/${WORKSPACE_ID}/system/publish/credentials`, {
      method: "POST",
      body: JSON.stringify(input),
    }),
  /** Updates a credential's label, connection, and/or default status. Omitting `connection` entirely
   *  — never sending it as an empty object or blank fields — is what keeps the stored secret
   *  untouched; see `use-publish-credentials.hooks.ts`'s header for why the form can never send a
   *  half-blank one. `isDefault: true` makes this the default connection for its provider (the server
   *  owns clearing any previous default for that same provider); omitted leaves default status
   *  unchanged. `worksFor` omitted preserves compatibility; [] clears it without a connection. */
  updatePublishCredential: (id: string, input: { label?: string; connection?: AdminPublishConnectionInput; isDefault?: boolean; worksFor?: string[] }) =>
    request<{ credential: AdminPublishCredentialSummary; verification?: AdminPublishCredentialVerification }>(`/workspaces/${WORKSPACE_ID}/system/publish/credentials/${encodeURIComponent(id)}`, {
      method: "PUT",
      body: JSON.stringify(input),
    }),
  /** `204`, idempotent — deleting an id that is already gone (a stale list, a double click) still
   *  resolves rather than throwing. */
  deletePublishCredential: (id: string) =>
    request<void>(`/workspaces/${WORKSPACE_ID}/system/publish/credentials/${encodeURIComponent(id)}`, { method: "DELETE" }),
  /** Re-checks one already-saved credential against its real provider right now — the human-facing
   *  counterpart to the best-effort verify a create/update already runs automatically, for when that
   *  cached result has gone stale (a rotated token) or was lost (a server restart clears the
   *  in-memory verification cache; see `AdminPublishCredentialSummary.accountLabel`'s doc for why the
   *  DB-persisted half of this survives that even though this specific response does not). Never
   *  4xxs for an unreachable or rejected provider — a failed verification is still a `200` carrying
   *  `status: "invalid" | "unreachable"`, only a genuinely missing credential id 404s. */
  verifyPublishCredential: (id: string) =>
    request<{ verification: AdminPublishCredentialVerification }>(`/workspaces/${WORKSPACE_ID}/system/publish/credentials/${encodeURIComponent(id)}/verify`, {
      method: "POST",
    }),

  // Secrets panel → site key tab (`src/server/inbound/admin-http/routes/system/site-key.ts`)
  // — status of the TOVU_SITE_KEY site key's generated-file fallback, an explicit
  // reveal action, and a create-only generate action. `admin.security.site-key.manage`-gated
  // server-side on every one of the three calls below. See that route file's own header for the
  // 2026-09-09 durability fix (a generated key file now genuinely protects every stored credential
  // in production too, with one disclosed gap: webhook signing/newsletter tokens still need the
  // env var there) and for the accepted security tradeoff of a key file living beside the
  // database it protects.
  /** Never throws for "no key active" — that is `{active: false, source: "none"}`, a normal 200,
   *  not an error. Never carries the key value — see `revealSiteKey` for that. */
  getSiteKeyStatus: () => request<AdminSiteKeyStatus>(`/workspaces/${WORKSPACE_ID}/system/site-key`),
  /** Returns the raw key value (whichever source is active) when one is set — a deliberate,
   *  explicit, separately-clickable action, never fired on page load. Superseded an earlier
   *  fingerprint-only brief (owner: "i want that token to be visible to admins or else when it
   *  breaks they have no idea whats going on"). No audit trail — this codebase has no
   *  general-purpose sensitive-read audit mechanism to hook into (checked; not built here). */
  revealSiteKey: () =>
    request<AdminRevealedSiteKey>(`/workspaces/${WORKSPACE_ID}/system/site-key/reveal`, { method: "POST" }),
  /** Makes sure this site has the RIGHT key, never a second one (2026-09-29): resolves `200`
   *  `already-active`/`recovered` or `201` `created` ({@link AdminSiteKeyGenerateOutcome}).
   *  Refusals are `409 {error, detail}`, nothing written, thrown as an `ApiError` whose `.message`
   *  is the code and whose `.body.detail` is a plain-words sentence: `KEY_DEPENDENT_DATA` (saved
   *  credentials need a key that is not here), `KEY_MISMATCH` (the key here is not the one they
   *  were locked with), `KEY_INVALID` (a key is set but malformed), `SITE_META_UNREADABLE`, and in
   *  production `ALREADY_EXISTS` (a key file appeared mid-request). See `use-site-key.hooks.ts`'s
   *  `classifySiteKeyGenerateError`. Never overwrites or rotates a key. */
  generateSiteKey: () =>
    request<AdminGeneratedSiteKey>(`/workspaces/${WORKSPACE_ID}/system/site-key/generate`, { method: "POST" }),
  /** "Paste your old token": installs `token` only once it opens this site's saved credentials,
   *  moving anything saved under the key in place onto it first. Refusals throw an `ApiError` with
   *  a plain `.body.detail`: `TOKEN_INVALID` (400), `TOKEN_DOES_NOT_OPEN`, `ENV_KEY_SET`,
   *  `RESTORE_POINT_UNAVAILABLE`, `SITE_META_UNREADABLE` (409). */
  importSiteKey: (input: { siteKey: string }, _optional = {}) =>
    request<AdminImportedSiteKey>(`/workspaces/${WORKSPACE_ID}/system/site-key/import`, { method: "POST", body: JSON.stringify(input) }),
  /** What "Start fresh" would remove and which webhooks get a new signing secret. Changes nothing. */
  previewSiteKeyStartFresh: () =>
    request<AdminSiteKeyStartFreshPreview>(`/workspaces/${WORKSPACE_ID}/system/site-key/start-fresh`),
  /** "Start fresh": restore point, remove what can't be unlocked, install the key. `confirm` must be
   *  `START FRESH` (else 400 `CONFIRMATION_REQUIRED`); other refusals as {@link importSiteKey}'s
   *  plus `STORAGE_SECRET_LOCKED`. */
  startFreshSiteKey: (confirm: string) =>
    request<AdminStartedFreshSiteKey>(`/workspaces/${WORKSPACE_ID}/system/site-key/start-fresh`, { method: "POST", body: JSON.stringify({ confirm }) }),

  // Source Control page → credential management (`src/server/routes/admin/system/
  // source-control-credentials.ts`) — one saved GitHub/GitLab/Bitbucket identity connection per
  // provider, stored encrypted server-side and never read back. Structurally mirrors the
  // publish-credentials block above; see `AdminSourceControlCredentialSummary`'s own doc for
  // exactly what a saved row can and cannot reveal. `source-control.credentials.write`-gated on
  // every verb server-side — NOT the same permission as the publish-credentials calls above (see
  // that route's own header for why connecting a source-control identity is not a publish
  // trigger).
  /** The source-control hosts switched-on plugins declare, with their credential forms. */
  listSourceControlProviders: () => request<AdminSourceControlProvidersSnapshot>(`/workspaces/${WORKSPACE_ID}/system/source-control/providers`),
  /** Every configured source-control credential for this workspace. */
  listSourceControlCredentials: () =>
    request<AdminSourceControlCredentialsSnapshot>(`/workspaces/${WORKSPACE_ID}/system/source-control/credentials`),
  /** Creates one named connection. `409 DUPLICATE_LABEL` (surfaced as a thrown `ApiError` with that
   *  `code`) if this workspace already has a credential with the same `(providerId, label)`.
   *  `isDefault` is optional — omitted entirely (not `false`) lets the server apply its own
   *  default-assignment rule (a provider's first-ever saved connection), rather than this admin
   *  guessing at it. */
  createSourceControlCredential: (input: { label: string; connection: AdminSourceControlConnectionInput; isDefault?: boolean }) =>
    request<{ credential: AdminSourceControlCredentialSummary }>(`/workspaces/${WORKSPACE_ID}/system/source-control/credentials`, {
      method: "POST",
      body: JSON.stringify(input),
    }),
  /** Updates a credential's label, connection, and/or default status. Omitting `connection`
   *  entirely — never sending it as an empty object or blank fields — is what keeps the stored
   *  secret untouched; see `use-source-control-credentials.hooks.ts`'s header for why the form can
   *  never send a half-blank one. */
  updateSourceControlCredential: (id: string, input: { label?: string; connection?: AdminSourceControlConnectionInput; isDefault?: boolean }) =>
    request<{ credential: AdminSourceControlCredentialSummary }>(`/workspaces/${WORKSPACE_ID}/system/source-control/credentials/${encodeURIComponent(id)}`, {
      method: "PUT",
      body: JSON.stringify(input),
    }),
  /** `204`, idempotent — deleting an id that is already gone (a stale list, a double click) still
   *  resolves rather than throwing. Not called anywhere on this page today (there is no delete
   *  affordance in the UI — replacing a token PUTs over the existing row), kept for parity with
   *  the publish-credentials block above. */
  deleteSourceControlCredential: (id: string) =>
    request<void>(`/workspaces/${WORKSPACE_ID}/system/source-control/credentials/${encodeURIComponent(id)}`, { method: "DELETE" }),

  /** Safe local project choices and eligible key summaries; no credential values. */
  listCredentialCopySources: (_required: Record<string, never>, options: AuthenticatedAdminRequestOptions = {}) =>
    authenticatedAdminRequest<{ sources: AdminCredentialCopySource[] }>({
      path: `/workspaces/${WORKSPACE_ID}/system/credential-copy`, method: "GET",
    }, options),
  /** Copy selected source IDs through the owner-only route; overwrite is explicit. */
  copyCredentials: (input: { sourceSiteId: string; ids: string[]; overwrite: boolean }, options: AuthenticatedAdminRequestOptions = {}) =>
    authenticatedAdminRequest<{ results: AdminCredentialCopyResult[] }>({
      path: `/workspaces/${WORKSPACE_ID}/system/credential-copy`, method: "POST", body: input,
    }, options),

  // Access Tokens page → "Add custom provider" (`src/server/routes/admin/system/
  // custom-credentials.ts`) — a user-defined provider (name, base URL, token, optional username,
  // category), stored encrypted server-side and never read back. Structurally mirrors the
  // source-control-credentials block above. `custom-credentials.write`-gated on every verb
  // server-side.
  /** Every configured custom-provider credential for this workspace. */
  listCustomCredentials: () => request<AdminCustomCredentialsSnapshot>(`/workspaces/${WORKSPACE_ID}/system/custom/credentials`),
  /** Creates one custom-provider credential. `409 DUPLICATE_LABEL` (surfaced as a thrown `ApiError`
   *  with that `code`) if this workspace already has one with the same `label`. */
  createCustomCredential: (input: {
    scope?: "project" | "site";
    worksFor?: string[];
    label: string;
    category: AdminCustomCredentialCategoryId;
    baseUrl: string;
    /** Omitted = no extra hosts beyond `baseUrl` (server-side default — see
     *  `validateAdditionalHosts`'s own doc). */
    additionalHosts?: readonly string[];
    connection: AdminCustomConnectionInput;
  }) =>
    request<{ credential: AdminCustomCredentialSummary }>(`/workspaces/${WORKSPACE_ID}/system/custom/credentials`, {
      method: "POST",
      body: JSON.stringify(input),
    }),
  /** Updates a credential's label, category, base URL, additional hosts, username, and/or
   *  connection. Omitting `connection` entirely — never sending it as an empty object or blank
   *  fields — is what keeps the stored secret untouched, same contract every sibling credential
   *  update call documents. Omitting `additionalHosts` leaves it unchanged; supplying it REPLACES
   *  the whole list (never merges), matching `updateCustomCredential`'s own server-side contract.
   *  `username` is independent of `connection` (2026-09-01, `store.ts`'s own precedence doc): omit
   *  it to leave the saved username exactly as `connection` (if sent) would otherwise set it, send
   *  `null` to clear it, or a non-empty string to set it — with NO token retype required either
   *  way. When both `username` and `connection` are sent in the same call, `username` wins for what
   *  gets stored in the plaintext column (server-side precedence, not a client-side rule).
   *  `worksFor` omitted preserves compatibility; [] clears it without a connection. */
  updateCustomCredential: (
    id: string,
    input: {
      worksFor?: string[];
      label?: string;
      category?: AdminCustomCredentialCategoryId;
      baseUrl?: string;
      additionalHosts?: readonly string[];
      username?: string | null;
      connection?: AdminCustomConnectionInput;
    }
  ) =>
    request<{ credential: AdminCustomCredentialSummary }>(`/workspaces/${WORKSPACE_ID}/system/custom/credentials/${encodeURIComponent(id)}`, {
      method: "PUT",
      body: JSON.stringify(input),
    }),
  /** `204`, idempotent. */
  deleteCustomCredential: (id: string) => request<void>(`/workspaces/${WORKSPACE_ID}/system/custom/credentials/${encodeURIComponent(id)}`, { method: "DELETE" }),


  // Publish Content — the peer push ceremony behind the Dashboard's "Publish Content"
  // button (`ADS-memory/reports/2026-09-18-publish-feature-implementation-plan.md` §4 task 11).
  // Same 3-endpoint gated-mutation shape as `planMergeTerm`/`planRestore` above; the result types
  // come from `@tovu/publish-content-ui` so this client and the server's own planner cannot hold
  // two drifting copies of the report shape.
  //
  // Every call names a PEER by id. A raw peer URL or credential is never sent from the browser and
  // never returned to it — `PublishContentPeerSummary` carries `masked`/`hasCredential` and nothing
  // else credential-shaped (Task 10 owns the sealing).
  listPublishContentPeers: () =>
    request<{ peers: PublishContentPeerSummary[] }>(`/workspaces/${WORKSPACE_ID}/publish-content/peers`),
  /** Zero-setup connect — reads whether this install already publishes somewhere, and if not, the
   *  candidate pre-filled from the repo's own deploy config
   *  (`routes/publish-content/destination.ts`). Nothing credential-shaped is ever in this response:
   *  see that route's own header for why. */
  getPublishDestination: () => request<AdminPublishDestinationView>(publishContentDestinationPath()),
  /** The one action that turns a fresh install into a connected one — no key is minted, displayed
   *  or copied. `siteUrl` is optional; omitted, the server falls back to its own candidate, which is
   *  the only path the Dashboard's empty-state offer uses. */
  connectPublishDestination: (input: { siteUrl?: string } = {}) =>
    request<AdminPublishDestinationView>(`${publishContentDestinationPath()}/connect`, {
      method: "POST",
      body: JSON.stringify(input),
    }),
  /** `selectedEntityKeys` (the report rows' own `entityType:entityId` keys) narrows the bundle this
   *  push stages on the peer BEFORE it plans — omitted means "everything", which is what an
   *  untouched dialog sends. See `features/publish-content/export-bundle.ts`'s `selectBundleEntities`
   *  for why a selection is applied at stage time rather than carried into execute.
   *
   *  `overwriteEntityKeys` (publish-overwrite-live-plan §4/S9) is the operator's ticked "Overwrite on
   *  live" rows — sent alongside `selectedEntityKeys`, never in place of it, so re-planning against a
   *  narrower selection never silently drops what was ticked. Omitted means nothing was ticked.
   *
   *  `scope` (`plan-publish-sections-2026-09-25.md` §2 S2) narrows the bundle on the SERVER before
   *  `selectedEntityKeys` does, same "absent means everything" contract. Sent unchanged on every call
   *  the dialog was opened with a scope for. */
  planPublishContent: ({
    peerId,
    selectedEntityKeys,
    overwriteEntityKeys,
    scope,
  }: {
    peerId: string;
    selectedEntityKeys?: readonly string[];
    overwriteEntityKeys?: readonly string[];
    scope?: PublishScope;
  }) =>
    request<PublishContentPlanResult>(`${publishContentPeerPath(peerId)}/push/plan`, {
      method: "POST",
      ...(selectedEntityKeys === undefined && overwriteEntityKeys === undefined && scope === undefined
        ? {}
        : {
            body: JSON.stringify({
              ...(selectedEntityKeys === undefined ? {} : { selectedEntityKeys }),
              ...(overwriteEntityKeys === undefined ? {} : { overwriteEntityKeys }),
              ...(scope === undefined ? {} : { scope }),
            }),
          }),
    }),
  confirmPublishContent: (
    { peerId, planId, planHash }: { peerId: string; planId: string; planHash: string },
    _options: Record<string, never> = {}
  ) =>
    request<PublishContentConfirmResult>(`${publishContentPeerPath(peerId)}/push/confirm`, {
      method: "POST",
      body: JSON.stringify({ planId, planHash }),
    }),
  /** `bundleId` comes from `planPublishContent`'s own response and is required: the peer's
   *  `/import/execute` refuses a confirmation token against any bundle but the one it planned.
   *  `overwriteEntityKeys` (publish-overwrite-live-plan §4/S9) is echoed straight from the confirmed
   *  plan's own `overwriteEntityKeys` — never re-derived here — so execute can only force the exact
   *  set the operator's plan was already confirmed against. */
  executePublishContent: (
    {
      peerId,
      bundleId,
      confirmationToken,
      overwriteEntityKeys,
    }: { peerId: string; bundleId: string; confirmationToken: string; overwriteEntityKeys?: readonly string[] },
    _options: Record<string, never> = {}
  ) =>
    request<PublishContentExecuteResult>(`${publishContentPeerPath(peerId)}/push/execute`, {
      method: "POST",
      body: JSON.stringify({ bundleId, confirmationToken, ...(overwriteEntityKeys === undefined ? {} : { overwriteEntityKeys }) }),
    }),
};

import { useEffect, type RefObject } from "react";
import type { ChatPaneComposerHandle } from "@jini-ai/chat/react";
import { requestAssistantDock } from "./assistant-dock-bus";

/**
 * @file Lets a screen hand the assistant a drafted request: it opens the dock and writes the text
 * into the composer through `ChatPaneComposerHandle.insertText` (the seam voice input and folder
 * drop already use). The text is a DRAFT; the owner reads it and presses Send. Sites' Import Site
 * tab uses it to start the existing `site-import` agent plugin on a live website (2026-10-18).
 *
 * The request is held until a mounted dock takes it, because the dock may be closed (unmounted)
 * when the screen asks, and the pane's handle is only published after its first render.
 */

let pending: string | null = null;
const listeners = new Set<() => void>();

/** Opens the dock and queues `text` for its composer. A newer request replaces an unsent one. */
export function requestAssistantPrompt(text: string): void {
  pending = text;
  requestAssistantDock(true);
  for (const listener of [...listeners]) listener();
}

/** Test seam: drops the queued text and every listener. */
export function resetAssistantPromptBus(): void {
  pending = null;
  listeners.clear();
}

const RETRY_MS = 100;
const MAX_ATTEMPTS = 50;

/**
 * The dock's half: delivers a queued request into the composer as soon as the pane's handle exists,
 * retrying briefly while the pane mounts (at most 5 s). A request still undelivered after that stays
 * queued for the next mount.
 * @complexity O(1) per attempt.
 */
export function useAssistantPromptRequests(composerHandle: RefObject<ChatPaneComposerHandle | null>): void {
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout> | undefined;
    const deliver = (attempt = 0) => {
      clearTimeout(timer);
      if (pending === null) return;
      const handle = composerHandle.current;
      if (handle) {
        const text = pending;
        pending = null;
        handle.insertText(text);
      } else if (attempt < MAX_ATTEMPTS) {
        timer = setTimeout(() => deliver(attempt + 1), RETRY_MS);
      }
    };
    const listener = () => deliver();
    listeners.add(listener);
    deliver();
    return () => {
      listeners.delete(listener);
      clearTimeout(timer);
    };
  }, [composerHandle]);
}

/**
 * @module assistant-transport-ag-ui
 *
 * ADR-059 — the AG-UI canary transport path `assistant-transport.ts` delegates to when its
 * Tovu-local `getAgUiEnabled` toggle is on. A third path alongside that file's existing Local CLI
 * and BYOK branches, talking to a genuinely different server surface:
 * `src/server/modules/assistant-ag-ui.ts`'s `AG_UI_RUN_PATH`, which streams real AG-UI wire events
 * — a translation layer in front of the SAME daemon-backed run lifecycle the Local CLI path uses.
 *
 * ADR-059 Decision 3 (AMENDED 2026-08-18): built on the real `@ag-ui/client`'s `HttpAgent`, which
 * owns the whole HTTP request + SSE parsing + per-event zod validation lifecycle — replacing this
 * file's own hand-rolled `fetch`/SSE-frame-parsing loop entirely. `AgUiEvent` mirrors (does not
 * import) `assistant-ag-ui.ts`'s own type of the same name, both now typed against the real
 * `@ag-ui/core` `AGUIEvent` union — `apps/admin/` and `src/server/` are separate deployable apps, so
 * there is no shared module either side can import the other's local types from.
 *
 * Two real-package behaviors that are NOT visible from its type signatures alone (found by reading
 * its compiled source, not guessed):
 *
 * 1. `HttpAgent.run(input)` returns a COLD `Observable<BaseEvent>` — nothing happens until
 *    subscribed, and it never resolves to a Promise. The existing `startRun` contract is "resolve
 *    once the run has STARTED" (matching `startByokRun`'s contract), so `agUiRunClient.startAgUiRun` races
 *    the Observable's first `next`/`error` notification against the returned Promise rather than
 *    trying to `await` the Observable directly.
 * 2. Aborting mid-stream (after headers arrive) does NOT error the Observable — it surfaces as a
 *    synthetic `RUN_ERROR` event carrying `code: "abort"` (the package's own convention), delivered
 *    through the NORMAL event path. `agUiRunClient.handleAgUiEvent` checks for that code and calls
 *    `finish()` instead of `onError`, so an intentional stop never reads as a user-facing error.
 *    Aborting BEFORE headers arrive still rejects the underlying `fetch()` itself, which DOES
 *    surface as a genuine Observable `error()` — the top-level subscription in `agUiRunClient.startAgUiRun`
 *    checks `agent.abortController.signal.aborted` for that earlier-timing case.
 */
import { HttpAgent } from "@ag-ui/client";
import { createAgUiRunClient } from "@jini-ai/chat/transports/ag-ui";
export type { AgUiEvent, AgUiToAgentTranslationState } from "@jini-ai/chat/core/ag-ui";
/** Must match `src/server/modules/assistant-ag-ui.ts`'s `AG_UI_RUN_PATH` exactly. */
export const AG_UI_RUN_PATH = "/api/admin/v1/assistant/ag-ui-run";
const CUSTOM_EVENT_NAMES = { usage: "tovu.usage", status: "tovu.status", extensionPrefix: "tovu.ext." };
/** `localStorage` key for the AG-UI canary toggle — a dev-facing flip, not an admin-settings row:
 *  this is experimental scaffolding (ADR-059), not a product setting, so it lives per-browser-tab
 *  rather than in `core.execution.*`'s settings ledger the "Execution mode" tab reads/writes. */
const AG_UI_TOGGLE_STORAGE_KEY = "tovu:assistant-ag-ui";

/**
 * Reads the AG-UI canary toggle fresh, for `AssistantDock.tsx`'s `getAgUiEnabled` callback (see
 * `CreateTovuAssistantTransportOptions.getAgUiEnabled`'s own doc for why this must be read live,
 * not captured once). `localStorage` over a build-time env var so it can be flipped per-tab from
 * devtools without a rebuild — flip it on with
 * `localStorage.setItem('tovu:assistant-ag-ui', '1')`.
 */
export function isAgUiTransportEnabled(): boolean {
  if (typeof localStorage === "undefined") return false;
  return localStorage.getItem(AG_UI_TOGGLE_STORAGE_KEY) === "1";
}

/** Same fallback as `mintByokRunId` (`assistant-transport.ts`) for a browser without
 *  `crypto.randomUUID`. Kept as its own copy rather than imported, to avoid the same import-cycle
 *  concern `sse-frames.ts`'s extraction was made to avoid (`assistant-transport.ts` imports FROM
 *  this module). */
function mintAgUiId(): string {
  return typeof crypto !== "undefined" && typeof crypto.randomUUID === "function"
    ? crypto.randomUUID()
    : `${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

/** Distinguishes an AG-UI-run id (client-minted, no server-side run record reachable through THIS
 *  path — see module doc) from a daemon-run id or a `byok:`-prefixed id wherever a bare `runId`
 *  string is all a `ChatTransport` method receives. Mirrors `BYOK_RUN_ID_PREFIX`'s exact role. */
const AG_UI_RUN_ID_PREFIX = "agui:";

const client = createAgUiRunClient({ ports: { endpoint: AG_UI_RUN_PATH, runIdPrefix: AG_UI_RUN_ID_PREFIX, customEventNames: CUSTOM_EVENT_NAMES,
 mintId: () => mintAgUiId(),
 createAgent: ({ url, threadId }) => new HttpAgent({ url, threadId, fetch: (url, init) => fetch(url, { ...init, credentials: "same-origin" }) }),
} }, {});

/** Share the same client with the main transport so stop reaches its in-flight run. */
export const agUiRunClient = client;

import { createAssistantTransportClient } from "@jini-ai/chat/transports/http";
import type { ChatMessage, StartRunInput } from "@jini-ai/chat/core";
import type { ExecutionConfig } from "@jini-ai/ui";
import { promptWithSelectedSkills } from "@/features/plugins/selected-skills";
import { browserQueuedStartPorts, startQueuedDaemonRun } from "./queued-daemon-start";
import { withAcceptanceCancellation } from "./acceptance-cancellation";
import { browserDurableSubscriptionPorts, durableRunBindings, followDurableRun } from "./durable-run-subscription";
import { agUiRunClient } from "./assistant-transport-ag-ui";
import { RUN_NOTICES } from "@tovu/assistant-run-events";
import { adminStreamActivity, trackTransportActivity, type StreamActivity } from "./stream-activity";
export { parseUsageEvent, terminalFailureError, terminalOutcomeNotice, terminalReasonNotice, translateRunAgentPayload } from "@tovu/assistant-run-events";
export { parseFrame } from "./sse-frames";

/** Product endpoints and projections; Jini owns the chat transport lifecycle. */
const RUNS_URL = "/api/runs";
const client = createAssistantTransportClient({ ports: {
 runsUrl: RUNS_URL, byokTurnUrl: "/api/admin/v1/assistant/byok-turn", byokRunIdPrefix: "byok:", notices: RUN_NOTICES,
 fetch: (url, init) => fetch(url, init),
 mintId: () => typeof crypto !== "undefined" && typeof crypto.randomUUID === "function" ? crypto.randomUUID() : String(Date.now()) + "-" + Math.random().toString(36).slice(2),
 projectPrompt: ({ prompt, context }) => promptWithSelectedSkills(prompt, context),
 projectInput: ({ input }) => withSelectedSkillGuidance(input),
 bindRun: ({ runId, binding }) => { durableRunBindings.set(runId, binding); },
 runBinding: ({ runId }) => durableRunBindings.get(runId),
 followRun: ({ runId, handlers, signal }) => { followDurableRun({ runId, handlers, signal, binding: durableRunBindings.get(runId), ports: browserDurableSubscriptionPorts({}, {}) }, {}); },
 acceptRun: ({ body, signal, requestSignal, messageId, conversationId }) => withAcceptanceCancellation({ signal,
  start: () => startQueuedDaemonRun({ body, signal: requestSignal, ports: browserQueuedStartPorts({}, {}) }, {}),
  cancel: async () => { await fetch(RUNS_URL + "/pending/cancel", { method: "POST", credentials: "same-origin", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ messageId, conversationId }) }); },
 }, {}),
 agUi: agUiRunClient,
} }, {});

export interface CreateTovuAssistantTransportOptions {
  /**
   * Read fresh on every `startRun` call, never captured once — matching `AssistantDock.tsx`'s own
   * `runContext` convention (see that file's doc on why `frontendBindToken` is read the same way):
   * the operator can flip the runtime picker's mode mid-session, and a captured value would keep
   * routing every later turn through whichever mode was selected when the transport was first
   * built (`AssistantDock.tsx` memoizes the transport once, for the reason its own comment gives —
   * rebuilding it would drop in-flight runs).
   */
  getExecutionConfig?: () => ExecutionConfig;
  /**
   * ADR-059's AG-UI canary toggle — deliberately NOT a value on {@link ExecutionConfig}: that type
   * is `@jini-ai/ui`'s own closed `'local-cli' | 'byok'` union, a separate repo/package, and
   * extending it would mean a cross-repo edit this ADR explicitly avoids (Decision 1: "a zero-touch
   * addition to Jini"). Read fresh on every `startRun` call, same "never captured" convention
   * {@link getExecutionConfig} already establishes, for the same reason: an operator can flip this
   * mid-session without rebuilding the memoized transport.
   */
  getAgUiEnabled?: () => boolean;
  /**
   * Agent ids whose own CLI/ACP session already carries multi-turn conversation memory across
   * spawns — `@jini-ai/agent-runtime`'s `resumesSessionViaCli`/`resumesSessionViaAcpLoad`, projected
   * client-safe as `AssistantAgentSummary.carriesOwnMemory` (`assistant/agents.ts`, Tovu server-side).
   * {@link runPrompt}'s own doc has the full "used to send only the newest message" background; this
   * option is the inverse regression it introduced for exactly these agents — see `startRun`'s Local
   * CLI branch below, which resends the doc's own contract instead of the full transcript ONLY for an
   * agentId this set contains: "the caller trusts this adapter's CLI to carry its own multi-turn
   * conversation memory... and should skip resending the rendered transcript on follow-up turns"
   * (`types.ts`). Resending it anyway would duplicate everything the daemon's own `--resume`/
   * `session/load` already restores (`agent-session-resume.ts`).
   *
   * Read fresh on every `startRun` call, same "never captured" convention {@link getExecutionConfig}/
   * {@link getAgUiEnabled} already establish: the admin's own `/api/agents` probe resolves
   * asynchronously and can still be in flight when this transport is first built, and an operator can
   * switch the Local CLI agent pick mid-session.
   *
   * Omitted, or an agentId absent from the returned set, keeps today's behavior — the full transcript
   * is sent. That is the SAFE default for a def this option's source has not resolved as resume-capable
   * yet: sending redundant history to a resume-capable def costs extra tokens, but withholding history
   * from a stateless def would silently erase its memory — the two failure directions are not
   * symmetric, so "unknown" must resolve to "send everything," not to "send only the latest message."
   */
  getResumeCapableAgentIds?: () => ReadonlySet<string>;
  /**
   * This pane's conversation id, adopting one if none is active yet —
   * `useAssistantChats.ensureConversationId` (`hooks/use-assistant-chats.hooks.ts`), wired through
   * `AssistantDock`'s `useAssistantTransport`. Awaited by `startRun` ONLY when `input.context` names
   * no conversation, which in practice means the first turn of a chat.
   *
   * Why the transport has to be the one to ask: the admin adopts a conversation lazily, from the
   * first message delta — and `@jini-ai/chat`'s `useChatPane.sendPrompt` freezes `runContext(...)`
   * into `input.context` BEFORE calling `conversation.sendMessage(...)`, the very call that produces
   * that delta. So on turn 1 there is no id to capture yet, and `runContext` (synchronous by
   * contract) has no way to wait for one. `startRun` is the last point in the chain that can still
   * `await`, which makes it the only place the run can acquire the identity its agent-CLI session id
   * gets filed under. Without it, `agent-daemon-server.ts`'s `onStarted` skipped its entire
   * session-capture subscription for turn 1, and turn 2 — sent only the bare latest user message,
   * trusting a resume that had nothing stored — answered with none of the conversation.
   *
   * Contract: resolves `null` rather than rejecting when creation fails. `startRun` treats that as
   * "send the turn anyway, with no conversationId" — one run with no resumable session is a far
   * smaller loss than a run that never happens.
   */
  ensureConversationId?: () => Promise<string | null>;
  /**
   * Writes one user message to durable storage — `useAssistantChats.persistUserTurn`
   * (`hooks/use-assistant-chats.hooks.ts`), wired through `AssistantDock`'s `useAssistantTransport`.
   * Awaited by `startRun` on the Local CLI path before `POST /api/runs`, including a delta's pending
   * PUT. Acceptance persists the same message with its stub if the browser write fails. See
   * {@link persistUserTurnBeforeDispatch} for the defect and the idempotency contract.
   *
   * Optional for transports without the dock's persistence hook; acceptance still receives the
   * exact user message, and the delta-driven `flush` can write the same ID afterward.
   * Its rejection is swallowed at the call site rather than failing the turn.
   */
  persistUserTurn?: (conversationId: string, message: ChatMessage) => Promise<void>;
}

/** Track all execution modes through one host activity owner; dispatch behavior stays in Jini.
 * The first options object is retained for existing dock callers; the second injects adapter ports.
 */
export function createTovuAssistantTransport(options: CreateTovuAssistantTransportOptions = {}, {
 createTransport = client.createAssistantTransport, activity = adminStreamActivity,
}: { createTransport?: typeof client.createAssistantTransport; activity?: StreamActivity } = {}) {
 return trackTransportActivity({ activity, transport: createTransport({ options: jiniHostOptions(options) }, {}) }, {});
}

type JiniHostOptions = NonNullable<Parameters<typeof client.createAssistantTransport>[0]["options"]>;

/**
 * Adapts the dock's host callbacks to Jini's port shape. Jini calls each port as `port({}, {})`;
 * every wrapper re-reads the option on each call and invokes it with exactly the arguments its own
 * signature declares, so a callback with optional parameters never receives Jini's port objects.
 * @param options The dock's callbacks; absent ones stay `undefined` so Jini keeps its defaults.
 * @returns Jini host options. No side effects.
 */
function jiniHostOptions(options: CreateTovuAssistantTransportOptions): JiniHostOptions {
 return {
  getExecutionConfig: options.getExecutionConfig && (() => options.getExecutionConfig!()),
  getAgUiEnabled: options.getAgUiEnabled && (() => options.getAgUiEnabled!()),
  getResumeCapableAgentIds: options.getResumeCapableAgentIds && (() => options.getResumeCapableAgentIds!()),
  ensureConversationId: options.ensureConversationId && (() => options.ensureConversationId!()),
  persistUserTurn: options.persistUserTurn && (({ conversationId, message }) => options.persistUserTurn!(conversationId, message)),
 };
}

/** Provider dispatch receives an augmented copy; persistence/title derivation sees the original. */
function withSelectedSkillGuidance(input: StartRunInput): StartRunInput {
  // Jini refuses a turn with no user message before projecting, so the newest user message exists.
  const userIndex = input.history.map((message) => message.role).lastIndexOf("user");
  return { ...input, history: input.history.map((message, index) => index === userIndex ? { ...message, content: promptWithSelectedSkills(message.content, input.context) } : message) };
}

/**
 * @file The one-time `#boot=<token>` fragment a zip-launched Tovu opens the admin with (run-from-zip
 * plan, Q2/S2, `ADS-memory/.local-artifacts/run-from-zip-plan-2026-09-23.md:46,112-117`). The
 * launcher opens `http://127.0.0.1:<port>/admin/#boot=<token>`; `App.hooks.tsx`'s boot effect calls
 * {@link takeBootToken} once, on mount, to read the token and scrub it from the URL bar in the same
 * synchronous pass — before anything else in that effect runs, including the network call that
 * redeems it. No logic belongs in `App.hooks.tsx`'s `.tsx` sibling (memory
 * `component_logic_belongs_hooks`), so this pure helper is the one place that parses or mutates the
 * fragment.
 *
 * Security properties, each one load-bearing (plan's own "Warnings for writers" / Sign-in row):
 * - The token is read from `location.hash`, which the browser never sends to the server and never
 *   puts in a `Referer` header — unlike a query string, which both do.
 * - `history.replaceState` runs before this function returns, so the token spends at most one
 *   paint in the URL bar and is never pushed as its own history entry (a `pushState` or a real
 *   navigation would leave it in Back history forever).
 * - This module never logs the token and never returns it to anything but its one caller.
 */

/** The subset of `Location` this module reads. Narrowed (not the whole DOM `Location`) so a test
 *  can pass a plain object instead of a real `window.location`. */
type BootTokenLocation = Pick<Location, "hash" | "pathname" | "search">;

/** The subset of `History` this module writes through. Narrowed to the one method used, for the
 *  same testability reason as {@link BootTokenLocation}. */
type BootTokenHistory = Pick<History, "replaceState">;

/**
 * Reads and consumes a `#boot=<token>` fragment.
 *
 * @param location - `window.location` (or an equivalent) — read only, never written.
 * @param history - `window.history` (or an equivalent) — `replaceState` is called at most once,
 *   only when a non-empty `boot` param was actually found.
 * @returns the raw token, or `null` when the hash has no non-empty `boot` param. A `null` result
 *   never calls `replaceState` — there is nothing to remove, so the URL is left exactly as it was.
 * @complexity O(n) in the number of `&`-separated hash params; one `URLSearchParams` pass, no
 *   nested iteration.
 */
export function takeBootToken(location: BootTokenLocation, history: BootTokenHistory): string | null {
  const rawHash = location.hash.startsWith("#") ? location.hash.slice(1) : location.hash;
  const params = new URLSearchParams(rawHash);
  const token = params.get("boot");
  if (!token) return null;

  // Every OTHER hash param is kept, in place, next to the ones present before this ran — only
  // `boot` itself is removed. An empty remainder collapses to no hash at all, rather than a bare
  // trailing `#`.
  params.delete("boot");
  const rest = params.toString();
  const nextUrl = `${location.pathname}${location.search}${rest ? `#${rest}` : ""}`;
  history.replaceState(null, "", nextUrl);

  return token;
}

import { authenticatedAdminRequest } from "./api";
import { ADMIN_BASE } from "./router";

/**
 * @file The admin's own errors and page views, sent to `POST /api/admin/v1/telemetry` through the
 * admin's API client. The server relays them to whichever observability / product-analytics
 * provider plugins are configured (or drops them), so no vendor SDK or third-party script loads
 * here and nothing changes when no provider is set up.
 *
 * What leaves the browser: an error's message, stack and React component stack, and the route
 * TEMPLATE (`/admin/posts/:postId`) — never a raw URL, query, form field value or DOM text. Errors
 * are deduped by message + top frame, capped per minute, and only sent while signed in. Nothing
 * here ever throws into the caller: telemetry must not become the next error.
 */

import { createBrowserTelemetry as createCollector, type BrowserTelemetryDeps } from "@jini-ai/admin/browser";
import type { BrowserTelemetry } from "@jini-ai/admin/browser";
export { installBrowserErrorListeners } from "@jini-ai/admin/browser";
export type { BrowserTelemetry, BrowserTelemetryDeps, BrowserTelemetryPayload } from "@jini-ai/admin/browser";

/** Bind the host's initial route; Jini owns collection, dedupe, caps and debounce. */
export function createBrowserTelemetry(deps: BrowserTelemetryDeps, options: { maxErrorsPerMinute?: number; pageviewDelayMs?: number } = {}): BrowserTelemetry {
  return createCollector(deps, { ...options, initialRoute: ADMIN_BASE });
}

/**
 * Route path (base already stripped) + the matched params → `/admin/posts/:postId`. Segments that
 * equal a captured param become its name; the query is dropped. The server also turns any leftover
 * id-like segment into `:id`, so an unmatched path still never leaks a record id.
 * @complexity O(s·p) for s segments and p params.
 */
export function toAdminRouteTemplate({ routePath, params }: { routePath: string; params: Readonly<Record<string, string>> }): string {
  const path = routePath.replace(/[?#][\s\S]*$/, "");
  const names = new Map(Object.entries(params).map(([name, value]) => [value, name]));
  const segments = path.split("/").filter(Boolean).map((segment) => {
    let decoded = segment;
    try { decoded = decodeURIComponent(segment); } catch { /* keep raw */ }
    const name = names.get(decoded);
    return name ? `:${name}` : segment;
  });
  return [ADMIN_BASE, ...segments].join("/");
}

/** The admin's one telemetry instance, posting through the shared API client. Under Vitest it
 * sends nothing: every screen test renders `App`, and an extra POST would land in their fetch fakes. */
export const adminTelemetry = createBrowserTelemetry({
  send: import.meta.env.MODE === "test"
    ? async () => undefined
    : (payload) => authenticatedAdminRequest({ path: "/telemetry", method: "POST", body: payload }, { keepalive: true }),
  nowMs: () => Date.now(),
  setTimer: (fn, ms) => setTimeout(fn, ms),
  clearTimer: (handle) => clearTimeout(handle as ReturnType<typeof setTimeout>),
});

/** `createRoot` options: every error a React boundary caught, and every one none did, with its component stack.
 * Overriding React's defaults drops their console logging, so this keeps it. */
export function reactRootErrorOptions({ telemetry }: { telemetry: Pick<BrowserTelemetry, "reportError"> }) {
  const handle = (error: unknown, info: { componentStack?: string }): void => {
    console.error(error);
    telemetry.reportError({ error, componentStack: info.componentStack });
  };
  return { onCaughtError: handle, onUncaughtError: handle };
}

/** Tovu credential copy is shared with the server cards; every offered locale has translations. */
export { credentialText, formatCredentialHint, formatCredentialHints, translateCredentialMessage } from '../../../website/src/contracts/core/credential-copy.js';
export { assertCredentialToken, CredentialInputError, CREDENTIAL_MESSAGES } from '../../../website/src/contracts/core/credential-token.js';
export type { CredentialTokenHint } from '../../../website/src/contracts/core/credential-token.js';

import { assertCredentialToken, CredentialInputError, type CredentialTokenHint } from '../../../website/src/contracts/core/credential-token.js';
import { translateCredentialMessage, formatCredentialHint } from '../../../website/src/contracts/core/credential-copy.js';

/** Only server-derived metadata describes a stored key. A legacy server may still send a mask. */
export function storedCredentialHint(
  { stored, storedKeyIsForOtherEndpoint = false }: { stored: { isSet: boolean; masked: string | null; tokenHint?: CredentialTokenHint | null } | null; storedKeyIsForOtherEndpoint?: boolean },
  { locale = 'en' }: { locale?: string } = {},
): string | undefined {
  if (storedKeyIsForOtherEndpoint || !stored?.isSet) return undefined;
  return formatCredentialHint({ hint: stored.tokenHint, locale }) || stored.masked || undefined;
}

/** Preserve the draft bytes; an exact blank update keeps the saved secret. Only the token
 *  validator's own `CredentialInputError` becomes display copy; any other failure is rethrown so an
 *  unknown exception never gains display permission. `assertToken` defaults to the shared validator. */
export function credentialDraftError(
  { value }: { value: string },
  { locale = 'en', required = false, assertToken = assertCredentialToken }: { locale?: string; required?: boolean; assertToken?: (required: { value: string }) => void } = {},
): string | null {
  if (value === '' && !required) return null;
  try { assertToken({ value }); return null; }
  catch (error) { if (error instanceof CredentialInputError) return translateCredentialMessage({ message: error.message, locale }); throw error; }
}

import type { ChatMessage } from "@jini-ai/chat/core";
import { followDurableRun as follow } from "@jini-ai/chat/transports/http";
import type { DurableRunBinding, DurableSubscriptionPorts } from "@jini-ai/chat/transports/http";
import { RUN_NOTICES } from "@tovu/assistant-run-events";
import { subscriptionEnded, type TrackedRunHandlers } from "./stream-activity";
export type { DurableRunBinding, DurableSubscriptionPorts } from "@jini-ai/chat/transports/http";
export const durableRunBindings = new Map<string, DurableRunBinding>();
/** Jini owns recovery, continuation, polling and terminal disposal. A missing durable row ends
 * this browser subscription without onDone, so release the host's page-stream retain as well.
 */
export function followDurableRun(required: Omit<Parameters<typeof follow>[0], "notices" | "bindings">, optional = {}): () => void {
  const endActivity = () => (required.handlers as TrackedRunHandlers)[subscriptionEnded]?.();
  const stop = follow({ ...required, notices: RUN_NOTICES, bindings: durableRunBindings, ports: {
    ...required.ports,
    read: async (input, options) => {
      const message = await required.ports.read(input, options);
      if (message === "gone") endActivity();
      return message;
    },
  } }, optional);
  return () => { stop(); endActivity(); };
}

/** Browser adapters only: active run streams are never visibility-paused. Ports permit DI fakes
 * without replacing modules; native disconnects retain Jini's existing recovery/backoff behavior.
 */
export function browserDurableSubscriptionPorts(_required = {}, {
  request = fetch, open = (url: string) => new EventSource(url),
  schedule = ({ work, delayMs }: { work: () => void; delayMs: number }) => {
    const timer = setTimeout(work, delayMs); return () => clearTimeout(timer);
  },
}: {
  request?: typeof fetch;
  open?: (url: string) => Pick<EventSource, "addEventListener" | "close" | "readyState">;
  schedule?: (required: { work: () => void; delayMs: number }) => () => void;
} = {}): DurableSubscriptionPorts {
  return {
    async read({ runId, messageId }, { recover = true }: { recover?: boolean } = {}) {
      const path = `/api/runs/${encodeURIComponent(runId)}`;
      const response = recover ? await request(`${path}/recover`, {
        method: "POST", credentials: "same-origin", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ messageId }),
      }) : await request(`${path}/checkpoint${messageId ? `?messageId=${encodeURIComponent(messageId)}` : ""}`, {
        method: "GET", credentials: "same-origin",
      });
      if (response.status === 404) return "gone";
      if (!response.ok) return null;
      const payload = await response.json() as { message: ChatMessage };
      return payload.message;
    },
    stream({ runId, cursor, frame, dropped }, _options) {
      const source = open(`/api/runs/${encodeURIComponent(runId)}/events${cursor ? `?afterCursor=${encodeURIComponent(cursor)}` : ""}`);
      for (const kind of ["agent", "stdout", "stderr", "end", "error"]) {
        source.addEventListener(kind, (event) => {
          const message = event as MessageEvent<string>;
          if (kind === "error" && !message.data) { source.close(); dropped(); return; }
          frame(kind, message.data, message.lastEventId);
        });
      }
      return () => source.close();
    },
    schedule(required, _options) { return schedule(required); },
  };
}

/**
 * @file Tovu adapter for `@jini-ai/ui`'s `ExecutionTab` — the Open Design
 * settings-dialog port, now wired to a real backend end to end.
 *
 * THREE responsibilities, deliberately kept apart:
 *
 * 1. **Non-secret persistence.** Everything except the BYOK API key — mode,
 *    protocol, providerId, baseUrl, model, maxTokens for the ACTIVE selection
 *    — is stored as SPEC-007 `setting_definitions` values in the
 *    `core.execution` namespace, written through `api.setSetting` (the
 *    ADR-028 single write chokepoint). `src/assistant/execution-mode-
 *    settings.ts` registers these definitions at server boot.
 *
 * 2. **Credential storage — now server-side, write-only (2026-08-05).**
 *    Superseded design note, kept because the reasoning still explains why
 *    the key is NOT a `core.execution` ledger field: ADR-028 §6 rejects any
 *    `secret:true` definition, and a plain-string definition would sit in
 *    the ledger's append-only `setting_revisions` table in plaintext
 *    forever. That gap is why the key used to live in this browser's own
 *    `localStorage`. It no longer does — `admin_execution_credentials`
 *    (design: `ADS-memory/reports/analysis/2026-08-05-admin-byok-keystore-
 *    design.md`, owner-approved) is a real, encrypted, write-only
 *    server-side store, one row per `(workspace, this admin)`, reusing
 *    ADR-058's sealer. `apps/admin/src/lib/api.ts`'s `getAdminExecutionCredential`/
 *    `setAdminExecutionCredential` are the routes; {@link loadAdminExecutionCredential}/
 *    {@link saveAdminExecutionCredential} below are the wrappers.
 *
 *    The move changes two things this file has to account for:
 *    - **Write-only means no read-back.** `loadExecutionConfig`'s `byok.apiKey`
 *      is now ALWAYS `""` — the server never returns key material, so there is
 *      nothing to hydrate it with. A caller that needs to know "is a key
 *      already stored" reads {@link loadAdminExecutionCredential}'s `isSet`
 *      separately; it is not merged into `ExecutionConfig`.
 *    - **The key must not ride the debounced ledger auto-save.** `saveExecutionConfig`
 *      below no longer persists `apiKey` anywhere — see that function's own
 *      doc for why. A destructive incident already happened once from
 *      exactly this shape (a 900ms-debounced auto-save on the VISITOR key
 *      screen encrypted a half-typed stub over a live production key,
 *      `ADS-memory/reports/refactors/2026-08-04-handoff-admin-byok-and-
 *      visitor-key-ui.md`'s "Two mistakes I made" §1). The fix there was an
 *      explicit Save button; the fix here is structural — this file's
 *      generic save path physically cannot write the key, so there is
 *      nothing for a debounce to accidentally trigger. Only an explicit
 *      caller of {@link saveAdminExecutionCredential} (the "Save key" control
 *      both `SettingsUi.tsx` and `AiAssistant.tsx`'s `AdminExecutionMode`
 *      render) can persist it.
 *    - **The key must survive a RELOAD, not just avoid being sent by one.** Excluding `apiKey`
 *      from the debounced write is not sufficient on its own: `useSettingsSlice`'s `refresh()` — an
 *      out-of-band re-read triggered by the settings-changed SSE feed, including a same-tab echo of
 *      this slice's OWN write — replaces the WHOLE in-memory value with whatever `loadExecutionConfig`
 *      returns, and that is always `apiKey: ""`. {@link reconcileExecutionConfigRefresh} closes that
 *      second hole; see its own doc for the exact sequence that used to wipe a typed key out from
 *      under the operator mid-edit.
 *
 *    `readLegacyLocalCredential`/`clearLegacyLocalCredential` below exist
 *    ONLY for the one-time rollout prompt migrating an admin's pre-existing
 *    `localStorage` key to the server — see their own docs.
 *
 * 3. **The port.** `ExecutionPort` is the tab's async edge (agent detection,
 *    connection test, model discovery). All three methods now call real
 *    Tovu server routes backed by `@jini-ai/agent-runtime` — see
 *    `createExecutionPort` below.
 */

import {
  api,
  ApiError,
  type AdminExecutionCredential,
  type AdminExecutionCredentialPatch,
  type SettingResolvedValue,
  type SettingScope,
} from "./api";
import { createExecutionHttpAdapter, requireExecutionResponseData, type CreateExecutionPortOptions, type ByokConfig, type ExecutionConfig, type ExecutionPort } from "@jini-ai/ui";

/** SPEC-007 namespace holding every NON-SECRET execution-mode key. No
 *  `byok.apiKey` here — see this file's header, item 2. */
export const EXECUTION_NAMESPACE = "core.execution";

/** One ledger key per field rather than a single blob: the ledger's whole
 *  point is per-key layering and per-key revisions, and a JSON blob would
 *  collapse that back into one opaque value. */
const KEYS = {
  mode: "mode",
  protocol: "byok.protocol",
  providerId: "byok.providerId",
  baseUrl: "byok.baseUrl",
  model: "byok.model",
  maxTokens: "byok.maxTokens",
  localCliAgentId: "localCli.agentId",
  localCliModel: "localCli.model",
  localCliReasoning: "localCli.reasoning",
} as const;

/** Mirrors `assistant/execution-mode-settings.ts`'s identical sentinel —
 *  the ledger's `byok.maxTokens` definition cannot default to `null`
 *  (ADR-028 totality rejects a null default for every non-secret
 *  definition), so `0` round-trips as "unset" in both directions. `0` can
 *  never collide with a real cap: `@jini-ai/ui`'s `parseMaxTokens` already
 *  treats 0 as meaningless. */
const MAX_TOKENS_UNSET_SENTINEL = 0;

/** Scope for the ledger values. Workspace-scoped so one operator's endpoint
 *  choice doesn't silently become every workspace's. */
const SCOPE: SettingScope = "workspace";

/** Composer selections belong to the person; the workspace value remains their inherited default. */
function executionSettingScope(key: string): SettingScope {
  return key.startsWith("localCli.") ? "user" : SCOPE;
}

/** The PRE-server-store `localStorage` key this admin's browser may still hold — read-only from
 *  here on. Same literal key `readStoredCredentials`/`writeStoredCredentials` used before the
 *  server-side store shipped, kept unchanged so an admin's existing browser data is still found.
 *  Never written to again by this file; see {@link readLegacyLocalCredential}. */
const LEGACY_CREDENTIALS_STORAGE_KEY = "tovu:execution-credentials:v1";

/**
 * One-time migration read: does this browser still hold a pre-server-store API key?
 *
 * Read-only and side-effect-free — callers use this ONLY to decide whether to show the "we found a
 * saved key in this browser — save it to your account?" prompt (owner-approved rollout, design
 * doc §6). Deliberately does NOT clear or upload anything itself: the two failure modes the design
 * explicitly rules out are auto-upload (sending a secret the admin never took an in-the-moment
 * action to send) and auto-clear (silently breaking BYOK for an admin who hasn't opened the
 * screen). Both are avoided by construction here — this function only ever reads.
 *
 * `savedByProviderId` (other providers' drafts) is deliberately not read or migrated — scoped out
 * of v1 per the design doc's owner-flagged item; only the ACTIVE key is worth a migration prompt.
 *
 * @returns The stored `apiKey`, trimmed, or `null` when there is nothing to migrate (absent,
 *   malformed, or blank). `null` is also what a browser that has already migrated (or never had a
 *   local key) returns — the caller cannot and does not need to distinguish those cases.
 * @complexity O(1) — one `localStorage` read plus a JSON parse.
 * @overallScore 100
 */
export function readLegacyLocalCredential(): string | null {
  try {
    const raw = window.localStorage.getItem(LEGACY_CREDENTIALS_STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as { apiKey?: unknown };
    const apiKey = typeof parsed.apiKey === "string" ? parsed.apiKey.trim() : "";
    return apiKey.length > 0 ? apiKey : null;
  } catch {
    // Malformed/inaccessible localStorage (private-browsing quota errors, a hand-edited value)
    // reads as "nothing to migrate" rather than throwing — the prompt is a convenience, not a
    // guarantee, and a parse failure here must not block the rest of the screen from rendering.
    return null;
  }
}

/**
 * Clears the pre-server-store `localStorage` entry.
 *
 * Callers MUST only invoke this after a confirmed successful {@link saveAdminExecutionCredential}
 * call for the SAME key — never speculatively, never on a failed save (design doc §6: "only after
 * that PUT succeeds does the code clear the localStorage entry"). This function itself has no way
 * to enforce that ordering; it is a plain, unconditional clear, and the caller's sequencing is what
 * makes it safe. See the migration-prompt component for the enforced order.
 *
 * @complexity O(1).
 * @overallScore 100
 */
export function clearLegacyLocalCredential(): void {
  try {
    window.localStorage.removeItem(LEGACY_CREDENTIALS_STORAGE_KEY);
  } catch {
    // Best-effort. A browser that cannot clear localStorage could not have written it moments ago
    // either — this is not a new failure mode, and swallowing it here matches
    // `readLegacyLocalCredential`'s own defensive posture rather than surfacing a confusing error
    // after the part the admin actually cares about (the server save) already succeeded.
  }
}

/** Compatibility wrapper for config/credential reads; the package owns the shape guard. */
function requireData<T>(response: { data?: T | null } | null | undefined, callSite: string): T {
  return requireExecutionResponseData({ response, callSite }, {});
}

/**
 * Reads the calling admin's OWN stored BYOK credential view — `isSet`/`masked`/the non-secret
 * fields, never the key. Thin wrapper so callers do not reach into `api.ts` directly; mirrors
 * `loadExecutionConfig`'s role for the ledger half.
 *
 * Deliberately NOT merged into `ExecutionConfig`/`loadExecutionConfig`: the ledger's
 * `byok.protocol`/`baseUrl`/`model`/`maxTokens` are the live, currently-selected values an
 * operator sees and edits every time they open Execution mode, while this store's copy of those
 * same fields is a snapshot from whenever the key was last explicitly saved — used server-side
 * only as the turn-execution fallback for a browser with an empty key field. Merging the two would
 * let a stale snapshot silently overwrite a live ledger value the admin has not saved yet.
 *
 * @complexity O(1) — one GET.
 * @overallScore 100
 */
export async function loadAdminExecutionCredential(): Promise<AdminExecutionCredential> {
  return requireData(await api.getAdminExecutionCredential(), "getAdminExecutionCredential");
}

/**
 * Explicit-only save for the admin's own BYOK credential. NEVER called from
 * {@link saveExecutionConfig}'s debounced ledger path — see this file's header, item 2, for why
 * that separation exists. Every caller of this function must be a deliberate operator action (a
 * "Save key" button press), not a side effect of editing an unrelated field.
 *
 * `apiKey` omitted leaves the stored key untouched (the server's own contract); an empty string is
 * rejected server-side (400) rather than silently ignored, matching `SiteAssistantCredentialPatch`.
 *
 * @complexity O(1) — one PUT.
 * @overallScore 100
 */
export async function saveAdminExecutionCredential(
  patch: AdminExecutionCredentialPatch,
): Promise<AdminExecutionCredential> {
  return requireData(await api.setAdminExecutionCredential(patch), "setAdminExecutionCredential");
}

/** A key exists — either just typed in this form, or already stored on the server. Both make the
 *  BYOK runtime picker and the probe controls meaningful, which is the only thing they need to
 *  decide. Mirrors `features/ai-assistant/rules.ts`'s identical `hasUsableKey`, generalized over
 *  just the one field every caller here actually has (`isSet`) since `AdminExecutionCredential`
 *  and `SiteAssistantCredential` are otherwise differently shaped.
 *
 * @complexity O(1).
 * @overallScore 100
 */
export function hasUsableAdminKey(apiKey: string, stored: { isSet: boolean } | null): boolean {
  return Boolean(apiKey.trim()) || stored?.isSet === true;
}

/**
 * Whether there is a key to WRITE right now — a deliberately narrower question than
 * {@link hasUsableAdminKey}, and the two must not be collapsed.
 *
 * `hasUsableAdminKey` answers "can this admin run against a key at all", where an already-stored key
 * counts: `AssistantDock`'s `apiModeAvailable` is right to say yes on the strength of a stored
 * credential the browser cannot read back. This one answers "does pressing Save key have anything to
 * send", and there a stored key is irrelevant — the only thing that can be written is what is in the
 * field.
 *
 * The distinction is what fixes the reported bug. Someone starts typing a key, changes their mind
 * and clears the field: with a key already stored, `hasUsableAdminKey`'s stored arm kept Save key
 * enabled over an empty field, offering to write nothing. Derived synchronously from the trimmed
 * value on every render — never debounced, so it can never lag a keystroke and re-open that window.
 *
 * @param apiKey - The raw field value; trimmed here, so whitespace-only reads as blank.
 * @returns `true` only when the field holds a non-whitespace value.
 * @complexity O(n) in the field length, for the trim.
 */
export function hasTypedAdminKey(apiKey: string): boolean {
  return Boolean(apiKey.trim());
}

export const DEFAULT_EXECUTION_CONFIG: ExecutionConfig = {
  mode: "local-cli",
  byok: {
    protocol: "anthropic",
    providerId: "anthropic",
    apiKey: "",
    baseUrl: "https://api.anthropic.com",
    model: "",
  },
  localCli: { agentId: null },
};

function asString(value: unknown, fallback: string): string {
  return typeof value === "string" ? value : fallback;
}

/** Ledger `mode` value -> `ExecutionConfig["mode"]`, falling back to `fallback` for anything else
 *  (unset, or a value this admin build no longer recognizes). Pulled out of `loadExecutionConfig`
 *  (2026-08-06, complexity pass) as its own named step — see {@link buildByokConfigFromLedger}'s doc
 *  for why the whole function was split this way. */
export function readExecutionMode(raw: unknown, fallback: ExecutionConfig["mode"]): ExecutionConfig["mode"] {
  return raw === "local-cli" || raw === "byok" ? raw : fallback;
}

/** Ledger `byok.protocol` value -> `ByokConfig["protocol"]`, same fallback contract as
 *  {@link readExecutionMode}. */
export function readByokProtocol(raw: unknown, fallback: ByokConfig["protocol"]): ByokConfig["protocol"] {
  return raw === "anthropic" || raw === "openai" || raw === "azure" || raw === "google" ? raw : fallback;
}

/** `null` is a real, distinct value here (it selects the custom endpoint), so only `undefined`
 *  (unset) falls back to `fallback` — a plain `??` would treat both the same. */
export function readByokProviderId(raw: unknown, fallback: string | null): string | null {
  if (raw === null) return null;
  return typeof raw === "string" ? raw : fallback;
}

/**
 * Builds the `byok` half of `loadExecutionConfig`'s result from the ledger rows.
 *
 * Pulled out of `loadExecutionConfig` (2026-08-06, complexity pass) along with
 * {@link buildLocalCliConfigFromLedger} and the `read*` helpers above: the function was one object
 * literal with six inline fallback ternaries stacked inside it, which is exactly what pushed its
 * cyclomatic/cognitive score over this pass's ceiling. Naming each fallback decision does not change
 * what gets computed, only makes each one independently readable (and, for the `read*` functions,
 * independently testable) instead of one undifferentiated expression.
 */
export function buildByokConfigFromLedger(byKey: Map<string, unknown>, defaults: ExecutionConfig): ByokConfig {
  const rawMaxTokens = byKey.get(KEYS.maxTokens);
  return {
    protocol: readByokProtocol(byKey.get(KEYS.protocol), defaults.byok.protocol),
    providerId: readByokProviderId(byKey.get(KEYS.providerId), defaults.byok.providerId),
    // Write-only — see this file's own doc. Never anything but "", regardless of whether a
    // credential is stored server-side.
    apiKey: "",
    baseUrl: asString(byKey.get(KEYS.baseUrl), defaults.byok.baseUrl),
    model: asString(byKey.get(KEYS.model), defaults.byok.model),
    ...(typeof rawMaxTokens === "number" && rawMaxTokens !== MAX_TOKENS_UNSET_SENTINEL
      ? { maxTokens: rawMaxTokens }
      : {}),
    // `savedByProviderId` (other providers' drafts) is scoped out of v1 — see this file's
    // header. Never populated; a host storing it would need its own per-provider server rows.
  };
}

/** Builds the `localCli` half of `loadExecutionConfig`'s result from the ledger rows — see
 *  {@link buildByokConfigFromLedger}'s doc for why this is split out the same way. */
export function buildLocalCliConfigFromLedger(byKey: Map<string, unknown>): ExecutionConfig["localCli"] {
  const agentId = asString(byKey.get(KEYS.localCliAgentId), "").trim();
  const model = asString(byKey.get(KEYS.localCliModel), "").trim();
  const reasoning = asString(byKey.get(KEYS.localCliReasoning), "").trim();
  return {
    // `""` is the ledger's "nothing picked yet" (a non-null default is
    // required — see `execution-mode-settings.ts`), which `@jini-ai/ui`
    // spells as `null`.
    agentId: agentId ? agentId : null,
    // Only the SELECTED agent's model round-trips through the ledger; see
    // the `localCli.model` definition for why the per-agent map does not.
    ...(agentId && model ? { modelByAgentId: { [agentId]: model } } : {}),
    // The reasoning-effort pick mirrors the model pick exactly — same
    // one-scalar-for-the-selected-agent shape, same per-agent map on the
    // `@jini-ai/ui` side, and the same consequence spelled out in the
    // `localCli.model` definition (a reload restores the selected agent's
    // effort, not every agent's). Both are gated on `agentId` for the same
    // reason: a value with no agent to key it under would otherwise attach
    // to whichever agent is picked next.
    ...(agentId && reasoning ? { reasoningByAgentId: { [agentId]: reasoning } } : {}),
  };
}

/**
 * Reads the non-secret ledger namespace and returns it as an `ExecutionConfig`. Unknown/missing
 * ledger keys fall back to `DEFAULT_EXECUTION_CONFIG` field by field, so a partially written
 * namespace still yields a usable config instead of throwing.
 *
 * `byok.apiKey` is ALWAYS `""` — the key is write-only server-side (this file's header, item 2),
 * so there is nothing to hydrate it with. A caller that needs to know whether a credential is
 * already stored must call {@link loadAdminExecutionCredential} separately and read its `isSet`.
 */
export async function loadExecutionConfig(): Promise<ExecutionConfig> {
  let rows: SettingResolvedValue[];
  try {
    rows = requireData(await api.getSettingsEffective({ namespace: EXECUTION_NAMESPACE }), "getSettingsEffective");
  } catch (error) {
    // A namespace with no registered definitions is the expected cold-start
    // state, not an error worth surfacing — fall back to defaults.
    if (error instanceof ApiError && error.status === 404) return DEFAULT_EXECUTION_CONFIG;
    throw error;
  }

  const byKey = new Map<string, unknown>(rows.map((row) => [row.key, row.value]));
  const defaults = DEFAULT_EXECUTION_CONFIG;
  return {
    mode: readExecutionMode(byKey.get(KEYS.mode), defaults.mode),
    byok: buildByokConfigFromLedger(byKey, defaults),
    localCli: buildLocalCliConfigFromLedger(byKey),
  };
}

/** The model of whichever agent is currently selected — the one value the
 *  ledger persists out of `LocalCliConfig.modelByAgentId`. Returns `""` when
 *  no agent is picked or that agent has no explicit model, which is exactly
 *  the registered default.
 *
 *  Exported (2026-08-05) so `AssistantDock.tsx`'s `useLocalCliSelection` can
 *  derive the SAME value when hydrating the picker's initial selection from
 *  this ledger — re-deriving the per-agent lookup a second time in the
 *  component would be a second copy of `LocalCliConfig.modelByAgentId`'s
 *  "keyed by the selected agent" contract to keep in sync with this one. */
export function selectedLocalCliModel(config: ExecutionConfig): string {
  const agentId = config.localCli.agentId;
  if (!agentId) return "";
  return config.localCli.modelByAgentId?.[agentId] ?? "";
}

/** The reasoning effort of whichever agent is currently selected — the mirror of
 *  {@link selectedLocalCliModel}, and the one value the ledger persists out of
 *  `LocalCliConfig.reasoningByAgentId`. Returns `""` when no agent is picked or that agent has no
 *  explicit effort, which is exactly the registered default.
 *
 *  Only meaningful for a runtime whose CLI takes effort as its OWN flag (`claude --effort`,
 *  codex's `-c model_reasoning_effort=`). A runtime that encodes effort inside the model id
 *  (`reasoningInModelId`; antigravity) never writes here at all — its effort is already part of
 *  `localCli.model`, and storing it twice would create two places to disagree. */
export function selectedLocalCliReasoning(config: ExecutionConfig): string {
  const agentId = config.localCli.agentId;
  if (!agentId) return "";
  return config.localCli.reasoningByAgentId?.[agentId] ?? "";
}

/** Field-level diff so a keystroke in one input writes one revision, not six
 *  — and so the API key never appears in this list at all (see this file's
 *  header, item 2). */
function changedLedgerEntries(
  next: ExecutionConfig,
  previous: ExecutionConfig,
): Array<{ key: string; valueJson: unknown }> {
  const pairs: Array<{ key: string; valueJson: unknown; changed: boolean }> = [
    { key: KEYS.mode, valueJson: next.mode, changed: next.mode !== previous.mode },
    { key: KEYS.protocol, valueJson: next.byok.protocol, changed: next.byok.protocol !== previous.byok.protocol },
    {
      key: KEYS.providerId,
      valueJson: next.byok.providerId,
      changed: next.byok.providerId !== previous.byok.providerId,
    },
    { key: KEYS.baseUrl, valueJson: next.byok.baseUrl, changed: next.byok.baseUrl !== previous.byok.baseUrl },
    { key: KEYS.model, valueJson: next.byok.model, changed: next.byok.model !== previous.byok.model },
    {
      key: KEYS.maxTokens,
      valueJson: next.byok.maxTokens ?? MAX_TOKENS_UNSET_SENTINEL,
      changed: (next.byok.maxTokens ?? MAX_TOKENS_UNSET_SENTINEL) !== (previous.byok.maxTokens ?? MAX_TOKENS_UNSET_SENTINEL),
    },
    {
      key: KEYS.localCliAgentId,
      valueJson: next.localCli.agentId ?? "",
      changed: (next.localCli.agentId ?? "") !== (previous.localCli.agentId ?? ""),
    },
    {
      key: KEYS.localCliModel,
      valueJson: selectedLocalCliModel(next),
      changed: selectedLocalCliModel(next) !== selectedLocalCliModel(previous),
    },
    {
      key: KEYS.localCliReasoning,
      valueJson: selectedLocalCliReasoning(next),
      changed: selectedLocalCliReasoning(next) !== selectedLocalCliReasoning(previous),
    },
  ];
  return pairs.filter((pair) => pair.changed).map(({ key, valueJson }) => ({ key, valueJson }));
}

/**
 * Writes only the non-secret ledger fields that actually changed. Returns the ledger keys written,
 * for "saved" UI feedback.
 *
 * Deliberately does NOT touch `next.byok.apiKey` at all, in either direction — no read, no write,
 * no comparison against `previous`. This is the function `useSettingsSlice`'s 600ms debounce calls
 * on every settled edit (`use-settings-slice.hooks.ts`), including a keystroke in the API-key
 * field that changed nothing else — see this file's header, item 2, for why the key must never be
 * reachable from that path. The practical effect: typing into the key field alone produces an
 * empty `changed` list here and writes nothing, which is the SAFE no-op this function's silence on
 * `apiKey` is meant to guarantee, not an oversight. Persisting the key is
 * {@link saveAdminExecutionCredential}'s job, called only from an explicit "Save key" action.
 *
 * All-or-nothing on failure. Each key is its own ledger row and there is no multi-key write, so a
 * rejection part-way through would otherwise leave the rows it already wrote in place — a Local CLI
 * switch writes `localCli.agentId` then `localCli.model`, and a failure between them persists the
 * new agent with the old agent's model. On a rejection this writes each already-written key back to
 * its `previous` value (newest first), then rethrows the ORIGINAL error. The rollback is best-effort:
 * a rollback write that also fails is not reported over the error that caused it.
 *
 * @throws Whatever `api.setSetting` rejected with first.
 * @complexity O(k) sequential writes for k changed keys, plus at most k-1 rollback writes.
 */
export async function saveExecutionConfig(
  next: ExecutionConfig,
  previous: ExecutionConfig,
): Promise<readonly string[]> {
  const changed = changedLedgerEntries(next, previous);
  const written: string[] = [];
  try {
    for (const { key, valueJson } of changed) {
      await api.setSetting({ namespace: EXECUTION_NAMESPACE, key, scope: executionSettingScope(key), valueJson });
      written.push(key);
    }
  } catch (error) {
    const previousValues = new Map(changedLedgerEntries(previous, next).map((entry) => [entry.key, entry.valueJson]));
    await restoreLedgerKeys(written, previousValues);
    throw error;
  }
  return changed.map((entry) => entry.key);
}

/** {@link saveExecutionConfig}'s rollback: rewrites `keys`, newest first, with their values in
 *  `previousValues` (built from the reverse diff, which has the same key set as the forward one).
 *  Never rejects. */
async function restoreLedgerKeys(keys: readonly string[], previousValues: ReadonlyMap<string, unknown>): Promise<void> {
  for (const key of [...keys].reverse()) {
    await api
      .setSetting({ namespace: EXECUTION_NAMESPACE, key, scope: executionSettingScope(key), valueJson: previousValues.get(key) })
      .catch(() => undefined);
  }
}

/**
 * `useSettingsSlice`'s `reconcileRefresh` option for the Execution slice — preserves the operator's
 * in-memory, typed-but-not-yet-explicitly-saved `byok.apiKey` across a `refresh()`-triggered reload.
 *
 * `loadExecutionConfig` always returns `byok.apiKey: ""` (this file's header, item 2 — the server
 * never returns key material), and `refresh()` fires on ANY out-of-band notification — including a
 * same-tab echo of THIS SLICE'S OWN debounced write arriving back over the settings-changed SSE feed
 * (`settings-events.ts`; `src/server/routes/admin/settings/events.ts` broadcasts to every open
 * connection for the workspace on a ~1s poll, the writer's own tab included, with no self-exclusion).
 *
 * The failure this prevents: an operator types a key, then edits a ledger field (baseUrl, model,
 * ...) in the same 600ms window. The settled debounce calls {@link saveExecutionConfig}, which
 * persists the ledger field and correctly ignores `apiKey`. `refresh()`'s own guards
 * (`use-settings-slice.hooks.ts`) see no pending timer and no unsaved edit once that save resolves —
 * by design, since the edit WAS saved, just not the key half of it — so when the SSE echo of that
 * same write arrives moments later, `refresh()` proceeds and would otherwise overwrite `value` with
 * the reload's `apiKey: ""`, silently discarding the typed key before the operator can reach the
 * explicit "Save key" control. Measured as: type a key, wait ~600ms, and the field goes empty and
 * "Save key" disables itself with no operator action in between.
 *
 * Preserving the in-memory key across every reload is correct precisely because
 * {@link saveExecutionConfig} never persists it in the first place (this file's header, item 2) — a
 * reload can never be "more current" about a field it never wrote or read, so `loaded`'s empty value
 * carries no information worth keeping. Every OTHER `byok`/`localCli`/`mode` field still takes the
 * reload's value unconditionally, same as a slice with no reconciler at all.
 *
 * @complexity O(1).
 * @overallScore 100
 */
export function reconcileExecutionConfigRefresh(current: ExecutionConfig, loaded: ExecutionConfig): ExecutionConfig {
  return { ...loaded, byok: { ...loaded.byok, apiKey: current.byok.apiKey } };
}

/** Routes and authenticated HTTP remain host-owned; one adapter shares detection across mounts. */
const executionHttpAdapter = createExecutionHttpAdapter({ transport: {
  detectExecutionAgents: (input, options) => api.detectExecutionAgents(input, options),
  testExecutionConnection: (input) => api.testExecutionConnection(input),
  testExecutionAgent: (input) => api.testExecutionAgent(input),
  listExecutionModels: (input) => api.listExecutionModels(input),
} }, {});
export type { CreateExecutionPortOptions } from "@jini-ai/ui";
/** Existing screens retain their flags; the package boundary receives two objects. */
export function createExecutionPort(input: CreateExecutionPortOptions = {}, _options = {}): ExecutionPort {
  return executionHttpAdapter.createPort({}, input);
}
/** Test seam resets only this host transport's shared cache. */
export function resetLocalAgentDetectionCache(_input = {}, _options = {}): void {
  executionHttpAdapter.resetDetectionCache({}, {});
}

import { useEffect, useState } from "react";
import type { NodeViewProps } from "@tiptap/react";

import { api } from "./api";
import { t as mediaT } from "../features/media/media-i18n";
import { useAdminLocale } from "../hooks/use-admin-locale.hooks";
import type { MediaEditDialogValue } from "../components/MediaEditDialog/MediaEditDialog.hooks";

/**
 * @file State, attr reads and handlers for `MediaEmbedNodeView` (`media-embed-extension.tsx`), so
 * the component itself stays markup only. Same `useX(input, deps)` / `useWiredX(input)` split
 * `components/MediaEditDialog/MediaEditDialog.hooks.tsx` uses: tests drive
 * {@link useMediaEmbedNodeView} with a fixed locale, the node view composes
 * {@link useWiredMediaEmbedNodeView}.
 */

/** A `media` node's attrs as the node view reads them. The ref fields and `alt` read as `""` when
 *  unset; `cssClass`/`htmlAttributes` read as `null`, the "inherit the asset's own value" state
 *  `MediaEditDialog` edits. */
export interface MediaEmbedAttrs {
  assetId: string;
  transformName: string;
  alt: string;
  cssClass: string | null;
  htmlAttributes: string | null;
}

function stringOr<T>(value: unknown, fallback: T): string | T {
  return typeof value === "string" ? value : fallback;
}

/**
 * Reads a `media` node's attrs defensively — `bodyJson` is stored JSON that an agent tool or an
 * import may have written, so a non-string value degrades to "unset" instead of reaching the DOM.
 *
 * @param attrs - `props.node.attrs` as ProseMirror hands it over.
 * @returns The five attrs, normalized — see {@link MediaEmbedAttrs}.
 * @complexity O(1).
 */
export function readMediaEmbedAttrs(attrs: Record<string, unknown>): MediaEmbedAttrs {
  return {
    assetId: stringOr(attrs.assetId, ""),
    transformName: stringOr(attrs.transformName, ""),
    alt: stringOr(attrs.alt, ""),
    cssClass: stringOr(attrs.cssClass, null),
    htmlAttributes: stringOr(attrs.htmlAttributes, null),
  };
}

export type MediaPreviewKind = "pending" | "image" | "video";

/**
 * Maps an asset's `Content-Type` to the element that previews it — `video/*` is a video, anything
 * else (including `""` from a failed lookup) is an `<img>`, matching `renderDocMedia`'s own rule.
 *
 * @param contentType - The asset's `Content-Type` header value, possibly with parameters.
 * @returns `"video"` or `"image"`.
 * @complexity O(1).
 */
export function mediaPreviewKind(contentType: string): "image" | "video" {
  return contentType.trim().toLowerCase().startsWith("video/") ? "video" : "image";
}

/**
 * Resolves the preview kind for `assetId` from its real `Content-Type`; `"pending"` while the lookup
 * is in flight, and again whenever `assetId` changes (a Replace), so one asset's verdict never
 * carries over to the next. A failed lookup previews as an image.
 */
function usePreviewKind(assetId: string, contentTypeOf: (assetId: string) => Promise<string>): MediaPreviewKind {
  const [resolved, setResolved] = useState<{ assetId: string; kind: "image" | "video" } | null>(null);
  useEffect(() => {
    if (!assetId) return;
    let live = true;
    contentTypeOf(assetId).then(
      (contentType) => live && setResolved({ assetId, kind: mediaPreviewKind(contentType) }),
      () => live && setResolved({ assetId, kind: "image" })
    );
    return () => {
      live = false;
    };
  }, [assetId, contentTypeOf]);
  return resolved?.assetId === assetId ? resolved.kind : "pending";
}

/** Everything `MediaEmbedNodeView` renders from. */
export interface MediaEmbedNodeViewController {
  assetId: string;
  alt: string;
  /** `api.mediaOriginalUrl(assetId)` for a complete ref (`assetId` AND `transformName`), else `""` —
   *  the node view shows its broken-reference label for `""`. */
  previewSrc: string;
  /** Seeds `MediaEditDialog` from the node's current per-instance attrs. */
  editInitial: MediaEditDialogValue;
  /** Which element previews the asset: `"pending"` until its real `Content-Type` is known, then
   *  `"video"` for `video/*` and `"image"` for anything else — the same rule the public renderer's
   *  `renderDocMedia` applies. See `media-embed-extension.tsx`'s header. */
  previewKind: MediaPreviewKind;
  /** Replace's `MediaPickerDialog` is open. Separate from {@link editing}: each button only flips
   *  its own flag, so the two dialogs can never be open together. */
  picking: boolean;
  openPicker: () => void;
  closePicker: () => void;
  /** Points the node at the picked asset and closes the picker. */
  replaceWith: (item: { id: string; alt: string; title: string }) => void;
  editing: boolean;
  openEdit: () => void;
  closeEdit: () => void;
  /** Writes the dialog's `alt`/`cssClass`/`htmlAttributes` onto the node and closes the dialog. */
  saveEdit: (value: MediaEditDialogValue) => void;
  remove: () => void;
  /** Translates the node view's copy (`media-i18n.ts`, keyed by the English string). */
  t: (key: string) => string;
}

/**
 * Owns `MediaEmbedNodeView`'s two dialog toggles, the asset's preview kind, and the handlers that
 * write back into the node through `props.updateAttributes`/`props.deleteNode`.
 *
 * @param props - The TipTap node-view props for one `media` node.
 * @param deps - `deps.locale` drives the returned `t`; `deps.contentTypeOf` looks up an asset's real
 *   `Content-Type` (`api.mediaContentType` when wired). Pass a stable function.
 * @returns See {@link MediaEmbedNodeViewController}.
 * @complexity O(1) per render.
 */
export function useMediaEmbedNodeView(
  props: NodeViewProps,
  deps: { locale: string; contentTypeOf: (assetId: string) => Promise<string> }
): MediaEmbedNodeViewController {
  const { assetId, transformName, alt, cssClass, htmlAttributes } = readMediaEmbedAttrs(props.node.attrs);
  const [picking, setPicking] = useState(false);
  const [editing, setEditing] = useState(false);
  const isRef = assetId.length > 0 && transformName.length > 0;
  const previewKind = usePreviewKind(isRef ? assetId : "", deps.contentTypeOf);

  return {
    assetId,
    alt,
    previewSrc: isRef ? api.mediaOriginalUrl(assetId) : "",
    editInitial: { alt, cssClass, htmlAttributes },
    previewKind,
    picking,
    openPicker: () => setPicking(true),
    closePicker: () => setPicking(false),
    replaceWith: (item) => {
      props.updateAttributes({ assetId: item.id, transformName: "public", alt: item.alt || item.title });
      setPicking(false);
    },
    editing,
    openEdit: () => setEditing(true),
    closeEdit: () => setEditing(false),
    saveEdit: (value) => {
      props.updateAttributes({ alt: value.alt, cssClass: value.cssClass, htmlAttributes: value.htmlAttributes });
      setEditing(false);
    },
    remove: () => props.deleteNode(),
    t: (key) => mediaT({ locale: deps.locale, key: key }),
  };
}

/** Binds the real `useAdminLocale()` and `api.mediaContentType` — what `MediaEmbedNodeView` composes. */
export function useWiredMediaEmbedNodeView(props: NodeViewProps): MediaEmbedNodeViewController {
  const locale = useAdminLocale();
  return useMediaEmbedNodeView(props, { locale, contentTypeOf: api.mediaContentType });
}

import { decodePublishCriteriaFromQuery, PUBLISH_CRITERIA_QUERY_PARAM, type PublishCriteria } from "@tovu/publish-content-ui";

/**
 * @file `publish-criteria-tool-webmcp-plan-2026-09-24.md` §4 S2, the owner's own "PLUS" instruction
 * (not in the written plan file) — a chat conversation with no admin tab open can't call
 * `requestPublish` itself, so it hands back a link instead: `/admin/?publish=<encoded criteria>`.
 * {@link takePublishCriteriaFromQuery} is the one-time read/strip step for that query param, the
 * same shape `boot-token-fragment.ts`'s `takeBootToken` already established for the zip launcher's
 * `#boot=<token>` fragment — narrowed `Location`/`History` types, pure, unit-tested directly. No
 * logic belongs in `App.hooks.tsx`'s `.tsx` sibling (memory `component_logic_belongs_hooks`), so
 * this pure helper is the one place that parses or mutates the query string.
 *
 * Unlike `takeBootToken`, an invalid payload still gets stripped — `decodePublishCriteriaFromQuery`
 * already never throws and returns `null` for anything malformed (see that function's own doc), and
 * leaving a dead `?publish=` param sitting in the address bar after a bad link was followed would
 * only confuse whoever looks at it next.
 */

/** The subset of `Location` this module reads. Narrowed (not the whole DOM `Location`) so a test
 *  can pass a plain object instead of a real `window.location` — same reasoning as
 *  `boot-token-fragment.ts`'s own `BootTokenLocation`. */
type PublishCriteriaLocation = Pick<Location, "search" | "pathname" | "hash">;

/** The subset of `History` this module writes through. Narrowed to the one method used, for the
 *  same testability reason as {@link PublishCriteriaLocation}. */
type PublishCriteriaHistory = Pick<History, "replaceState">;

/**
 * Reads and consumes a `?publish=<encoded PublishCriteria>` query param.
 *
 * @param location - `window.location` (or an equivalent) — read only, never written.
 * @param history - `window.history` (or an equivalent) — `replaceState` is called at most once,
 *   only when the param was actually present (whether or not it decoded to something valid).
 * @returns the decoded `PublishCriteria`, or `null` when the param is absent OR present but
 *   malformed — either way it is stripped, so a bad link never leaves a dead param behind.
 * @complexity O(n) in the query string's own param count; one `URLSearchParams` pass, no nested
 *   iteration.
 */
export function takePublishCriteriaFromQuery(
  location: PublishCriteriaLocation,
  history: PublishCriteriaHistory
): PublishCriteria | null {
  const params = new URLSearchParams(location.search);
  const raw = params.get(PUBLISH_CRITERIA_QUERY_PARAM);
  if (raw === null) return null;

  // Every OTHER query param is kept, in place — only this one is removed. An empty remainder
  // collapses to no `?` at all, rather than a bare trailing one; `location.hash` is carried through
  // unmodified, same as `boot-token-fragment.ts`'s own pathname/search preservation.
  params.delete(PUBLISH_CRITERIA_QUERY_PARAM);
  const rest = params.toString();
  const nextUrl = `${location.pathname}${rest ? `?${rest}` : ""}${location.hash}`;
  history.replaceState(null, "", nextUrl);

  return decodePublishCriteriaFromQuery(raw);
}

import { useSyncExternalStore } from "react";
import { DEFAULT_ADMIN_BASE, adminHref as adminHrefCore, currentRoutePath as currentRoutePathCore } from "@jini-ai/admin/core";
import { createAdminShellNavigation } from "@jini-ai/admin/browser/shell-navigation";

/**
 * @file Path-based routing for the admin SPA — `/admin/settings`, not `/admin/#/section/settings`.
 *
 * **This file is now a thin adapter over `@jini-ai/admin`.** The route model
 * (`adminHref`/`currentRoutePath`) lives in `@jini-ai/admin/core` and the `window`-bound half
 * (`navigate`, the link interceptor, route subscription) in `@jini-ai/admin/browser`. What stays
 * here is only what is genuinely Tovu-specific: the legacy `#/section/...` URL migration, and the
 * React hook. The full rationale for every rule below now lives in those modules' headers — this
 * file keeps the export surface its ~14 call sites already use so none of them had to change.
 *
 * Why paths at all: the hash was never load-bearing. Both places that serve this app already fall
 * back to `index.html` for any `/admin/*` depth — `src/server/middleware/admin-static.ts` does it
 * explicitly (SEA and static-build branches), and Vite dev does it by default under
 * `base: "/admin/"`. So a real URL survives a refresh, and the hash was only costing us shareable
 * links.
 *
 * ## The base is fixed at `/admin`
 *
 * Not configurable here, and deliberately so — it is already hard-coded in `vite.config.ts`
 * (`base: "/admin/"`) and in the server's route patterns. Changing it means changing all three.
 * `@jini-ai/admin` takes a base parameter so another product can mount elsewhere; Tovu does not
 * use that, and `ADMIN_BASE` below stays the one place this app names it.
 *
 * ## Route paths vs URLs
 *
 * The distinction this module exists to keep straight, because collapsing it is what produced
 * `/admin/#/section/settings` in the first place:
 *   - a **route path** is base-agnostic and is what `App.tsx`'s parser consumes: `/`, `/settings`,
 *     `/posts/abc`.
 *   - a **URL** is what goes in an `href` or the address bar: `/admin/`, `/admin/settings`.
 * `adminHref` converts the first into the second; `currentRoutePath` recovers the first from the
 * address bar. Nothing else should be doing string surgery on `location`.
 */

export const ADMIN_BASE = DEFAULT_ADMIN_BASE;

/** `/settings` → `/admin/settings`; `/` → `/admin/`. */
export function adminHref(routePath: string): string {
  return adminHrefCore({ routePath }, { base: ADMIN_BASE });
}

/**
 * The current route path, base stripped. Always starts with `/`.
 *
 * Keeps the `window.location.pathname` default this app's call sites rely on. The package
 * deliberately requires the argument — that default is what made the original untestable without
 * a DOM — so the default is reapplied here, at the edge that already assumes a browser.
 */
export function currentRoutePath(pathname: string = window.location.pathname): string {
  return currentRoutePathCore({ pathname }, { base: ADMIN_BASE });
}

/** Bind the shared browser ports to this SPA's window and fixed admin base. */
export function navigate(routePath: string, options: { replace?: boolean } = {}): void {
  createAdminShellNavigation({ location: window.location, window, document }).navigate({ routePath, base: ADMIN_BASE }, options);
}

/** Install the shared interceptor with this SPA's browser and fixed admin base. */
export function installInternalLinkInterceptor(): () => void {
  return createAdminShellNavigation({ location: window.location, window, document }).installLinkInterceptor({ base: ADMIN_BASE });
}

/** React's subscribe ABI is positional; the Jini boundary receives explicit browser ports. */
function subscribeToRoute(onChange: () => void): () => void {
  return createAdminShellNavigation({ location: window.location, window, document }).subscribe({ base: ADMIN_BASE, onChange });
}

/**
 * Translates a legacy hash URL to its path equivalent, in place, and reports whether it did.
 *
 * Stays in Tovu rather than moving to `@jini-ai/admin`: it migrates URLs from *this app's* former
 * hash router, and no other product has that history to carry.
 *
 * Bookmarks, anything the assistant wrote down, and muscle memory all still point at
 * `#/section/settings`. Without this they would land on the dashboard — the parser's fallback for
 * an unrecognized route — which looks like the link rotted rather than moved.
 *
 * `replaceState`, not `pushState`: the hash URL should not become a Back-button stop, or Back from
 * the redirected page would land on the hash URL and redirect forward again.
 */
export function redirectLegacyHashUrl(): boolean {
  const { hash } = window.location;
  if (!hash.startsWith("#/")) return false;
  /*
   * Only when the PATH carries no route of its own.
   *
   * A genuine legacy URL is always `/admin/#/section/seo`: the path is the bare base and the entire
   * route lives in the hash. If the path already names a route, then a `#/…` is an ordinary document
   * fragment that merely looks route-shaped, and rewriting on it throws the real route away —
   * `/admin/posts/abc#/section/seo` reloaded as `/admin/seo`, losing `/posts/abc` entirely.
   */
  if (currentRoutePath() !== "/") return false;
  const [rawPath, rawQuery] = hash.replace(/^#\/?/, "").split("?");
  /*
   * `section/` was an artifact of the hash router's own dispatch, never meaningful in a URL — but it
   * is only safe to strip when what remains is a single segment, which is the only shape the
   * parser's bare-section branch accepts.
   *
   * The case that forced the guard: `#/section/settings/foo` used to render Settings, because the old
   * parser matched on `section` + `settings` and ignored the trailing segment. Stripping
   * unconditionally turned it into `/admin/settings/foo`, which is multi-segment and falls through to
   * the dashboard — a silent behaviour change for a stored URL. Keeping the prefix in that case hands
   * it to the legacy `section/:id` branch, which still ignores extra segments as before.
   *
   * Known and accepted divergence: the segment count is taken on the RAW path, so an encoded slash
   * slips past it — `#/section/settings%2Ffoo` counts as one segment and gets stripped to
   * `/admin/settings%2Ffoo`, which resolves to the dashboard, where the old parser produced the
   * unknown-section placeholder. Decoding first would need a `try`/`catch` for malformed escapes, and
   * both outcomes are equally "you did not get a real screen" for a URL nobody has.
   */
  // `String#split` always yields at least one element, so the path part is always a string.
  const path = rawPath!;
  const stripped = path.replace(/^section\//, "");
  const canStrip = stripped.split("/").filter(Boolean).length === 1;
  const query = rawQuery ? `?${rawQuery}` : "";
  window.history.replaceState(null, "", `${adminHref(`/${canStrip ? stripped : path}`)}${query}`);
  return true;
}

/**
 * `useSyncExternalStore`'s required `getServerSnapshot` for {@link useRouteLocation} — named and
 * exported, rather than left as an inline arrow, so its contractually-required return value is
 * directly assertable. React only calls this during SSR/hydration; this admin is a pure-CSR Vite
 * SPA with no SSR entry point, so it never runs in production, but `useSyncExternalStore` still
 * requires the argument. `"/"` (route paths, not URLs — see this file's own doc) is the same safe,
 * unauthenticated-looking default `currentRoutePath` falls back to when nothing more specific is
 * knowable yet.
 */
export function getServerRouteSnapshot(): string {
  return "/";
}

/**
 * The address bar as an external store.
 *
 * `useSyncExternalStore` rather than `useState` + an effect: the URL is genuinely external state,
 * and reading it during render is what keeps the first paint from briefly showing the wrong route.
 * The snapshot is a string so React's identity check works without memoization — returning an
 * object here would re-render on every subscriber notification.
 *
 * Stays here rather than in `@jini-ai/admin/browser` because it imports React; it belongs in that
 * package's `/react` layer once that exists.
 */
export function useRouteLocation(): string {
  return useSyncExternalStore(
    subscribeToRoute,
    () => `${currentRoutePath()}${window.location.search}`,
    getServerRouteSnapshot,
  );
}

/**
 * @file Subscribes to the server's settings change feed and republishes onto
 * `settings-refresh-bus.ts`, so a change made anywhere — another tab, another operator, a
 * background job, an agent run in a different window — reaches this tab's mounted settings tabs
 * without a page reload.
 *
 * ## How this differs from the run-completion trigger
 *
 * `components/AssistantDock/AssistantDock.tsx` already refreshes when an assistant run finishes in THIS tab.
 * That covers the common case immediately and needs no server support, but it is blind by
 * construction: it only knows about runs it hosted. This feed covers everything else, and the two
 * are deliberately independent — the dock keeps working if the feed is unavailable, and the feed
 * keeps working with the dock closed. Both land on the same bus, and a duplicate refresh is a
 * no-op read, so overlap costs nothing worth preventing.
 *
 * ## Reconnection is the browser's job, not ours
 *
 * `EventSource` reconnects on its own and replays `Last-Event-ID`, which the server honors as a
 * ledger cursor — so a dropped connection resumes at the revision it left off rather than silently
 * skipping the writes that happened in the gap. Hand-rolling that would mean reimplementing
 * backoff and resume for no gain, which is the reason this uses `EventSource` rather than `fetch`
 * streaming. Explicit ownership handoff preserves the last received id via `afterRevision`;
 * ordinary network retries still belong to the same native EventSource.
 */
import { publishThemePreviewRefresh, type ThemePreviewRefresh } from "@/features/themes/theme-preview-refresh";
import { publishSettingsRefresh } from "./settings-refresh-bus";
import { startBrowserStream, type BrowserStreamPorts } from "./browser-stream";
import { adminStreamActivity, type StreamActivity } from "./stream-activity";

/** Frame payload. Namespace names only — the server never sends values (see `change-feed.ts`). */
interface SettingsChangedFrame {
  namespaces?: readonly string[];
}

function eventsUrl(workspaceId: string): string {
  return `/api/admin/v1/workspaces/${encodeURIComponent(workspaceId)}/settings/events?themePreview=1`;
}

/**
 * Shares the change feed for this workspace/principal across tabs and returns a disposer.
 * The positional workspace argument is retained for existing hook consumers.
 *
 * Never throws and never rejects. A workspace whose server predates this endpoint, a proxy that
 * refuses `text/event-stream`, a revoked `settings.read` grant — every one surfaces as
 * `EventSource`'s opaque `error`, and none of them should break the admin. The tab simply keeps the
 * behavior it had before this feed existed: values refresh on run completion and on reload.
 *
 * @returns A disposer that closes the connection. Call it from the owner's effect cleanup —
 * `EventSource` retries forever otherwise, including after the component that opened it is gone.
 * @complexity O(1).
 */
export function subscribeToSettingsChanges(workspaceId: string, {
  open = (url: string) => new EventSource(url, { withCredentials: true }),
  principalId = "session", ports, activity = adminStreamActivity,
  publishSettings = publishSettingsRefresh, publishPreview = publishThemePreviewRefresh,
}: {
  open?: (url: string) => Pick<EventSource, "addEventListener" | "close" | "readyState">;
  principalId?: string; ports?: BrowserStreamPorts; activity?: StreamActivity;
  publishSettings?: typeof publishSettingsRefresh; publishPreview?: typeof publishThemePreviewRefresh;
} = {}): () => void {
  let cursor = "";
  let themeRevision = "";
  let opened = false;
  type Frame = { kind: "settings-changed" | "theme-preview-refresh" | "open"; data: string; id: string };
  return startBrowserStream<Frame>({
    // Workspace and principal are both disclosure boundaries; never share across identities.
    key: `settings/${encodeURIComponent(workspaceId)}/${encodeURIComponent(principalId)}`,
    connect: ({ emit }) => {
      let source: Pick<EventSource, "addEventListener" | "close" | "readyState">;
      const resume = `${cursor ? `&afterRevision=${encodeURIComponent(cursor)}` : ""}${themeRevision ? `&themeRevision=${encodeURIComponent(themeRevision)}` : ""}`;
      try { source = open(eventsUrl(workspaceId) + resume); }
      catch (error) {
        console.warn("[admin] settings change feed unavailable", error);
        return () => {};
      }
      for (const kind of ["theme-preview-refresh", "settings-changed", "open"] as const) {
        source.addEventListener(kind, (event) => {
          const message = event as MessageEvent<string>;
          emit({ kind, data: message.data ?? "", id: message.lastEventId ?? "" });
        });
      }
      // Deliberately not closed here: EventSource reconnects with backoff on its own, and a
      // transient blip must not permanently silence the feed for the tab's remaining lifetime.
      // Logged at debug volume because a reconnect is ordinary, not an incident.
      source.addEventListener("error", () => {
        if (source.readyState === 2) console.warn("[admin] settings change feed closed by the server; no further updates on this connection");
      });
      return () => source.close();
    },
    receive: ({ frame }) => {
      if (frame.id) cursor = frame.id;
      if (frame.kind === "open") {
        // A new leader/follower connection may have no cursor yet. Re-read after boot so a
        // handoff cannot leave stale values even when no settings frame preceded it.
        // Theme's durable marker replays independently.
        // The FIRST attach belongs to boot's fresh reads, not a change. Later opens still cover
        // reconnects/leadership handoffs, including those for which no cursor was received.
        // A prior frame can supply the resume cursor even if that source never emitted open.
        if (opened || cursor) publishSettings();
        opened = true;
        return;
      }
      if (frame.kind === "theme-preview-refresh") {
        try {
          const preview = JSON.parse(frame.data) as ThemePreviewRefresh;
          publishPreview(preview);
          themeRevision = preview.revision;
        } catch { /* A malformed theme frame must not break the independent settings feed. */ }
        return;
      }
      try {
        const changed = JSON.parse(frame.data) as SettingsChangedFrame;
        // A frame with no usable namespace list still means "something changed" — refresh everything
        // rather than dropping a notification because its payload shape was unexpected.
        publishSettings(Array.isArray(changed.namespaces) ? changed.namespaces : undefined);
      } catch { publishSettings(); }
    },
  }, { ports, activity });
}

import { ApiError } from "./api";
import type { Translate } from "@jini-ai/ui/panel-kit";

/**
 * @file Rules for a BYOK key the server holds write-only and will only send to the endpoint it was saved
 * for — the endpoint pin in the server's `stored-credential-probe.ts`.
 *
 * Shared by the admin's two key screens so both answer "can this stored key be probed here?" the same
 * way: the visitor key (`features/ai-assistant/hooks/use-visitor-credential-form.hooks.ts`) and the
 * admin's own key (`hooks/use-admin-execution-credential.hooks.ts`). Moved here from
 * `features/ai-assistant/rules.ts` when the second screen needed them (owner repro 2026-09-13).
 */

/** The two fields of a stored-credential view these rules read. `SiteAssistantCredential` and
 *  `AdminExecutionCredential` both carry them. */
export interface StoredCredentialEndpoint {
  isSet: boolean;
  baseUrl: string | null;
}

/** The ask shown when the stored key belongs to another endpoint: the key line's status and, through
 *  {@link describeProbeError}, a probe the server refused for that reason. One constant so the two
 *  cannot drift. Also a dictionary key in `features/ai-assistant/ai-assistant-i18n.ts`. */
export const STORED_KEY_OTHER_PROVIDER_COPY = "Your saved key is for a different provider. Paste a key for this one.";

/** {@link describeProbeError}'s copy for a stored key with no saved endpoint. Also a dictionary key. */
export const STORED_KEY_NO_ENDPOINT_COPY = "Your saved key has no provider saved with it. Paste the key again to test it.";

/** Mirrors `normalizeEndpoint` in the server's `stored-credential-probe.ts` (trim, strip trailing
 *  slashes, no case folding). The two must agree, or a screen and the server disagree about which
 *  endpoint a stored key belongs to. */
function normalizeEndpoint(baseUrl: string): string {
  return baseUrl.trim().replace(/\/+$/, "");
}

/**
 * True when a key is stored and the server recorded a DIFFERENT endpoint for it than the form's —
 * the provider-switch case. The server only lets a key it holds go to the endpoint it was saved for,
 * so a stored-key probe against the form's endpoint can only be refused.
 *
 * An unknown stored endpoint (`null` or blank) is `false`: it is not provably another endpoint, so the
 * server's own answer stands, translated by {@link describeProbeError}. So is a view that has not
 * loaded yet (`null`).
 *
 * @complexity Time/space: O(n) in the two URL lengths.
 */
export function storedKeyIsForOtherEndpoint(stored: StoredCredentialEndpoint | null, baseUrl: string): boolean {
  const storedBaseUrl = stored?.isSet ? stored.baseUrl?.trim() : "";
  if (!storedBaseUrl) return false;
  return normalizeEndpoint(storedBaseUrl) !== normalizeEndpoint(baseUrl);
}

/** A key a probe can use HERE — typed into the field, or stored on the server for this endpoint. A
 *  key stored for another endpoint does not count; see {@link storedKeyIsForOtherEndpoint}.
 *
 * @complexity Time/space: O(n) in the two URL lengths.
 */
export function hasUsableKey(apiKey: string, stored: StoredCredentialEndpoint | null, baseUrl: string): boolean {
  if (apiKey.trim()) return true;
  return stored?.isSet === true && !storedKeyIsForOtherEndpoint(stored, baseUrl);
}

/**
 * True when a probe from this form could only offer the stored key to an endpoint the server did not
 * save it for: nothing is typed, and the stored key belongs to another endpoint. The server refuses
 * that probe, so a screen sends nothing and its key line asks for this provider's key instead.
 *
 * @complexity Time/space: O(n) in the key and URL lengths.
 */
export function storedKeyBlocksProbe(apiKey: string, stored: StoredCredentialEndpoint | null, baseUrl: string): boolean {
  return !apiKey.trim() && storedKeyIsForOtherEndpoint(stored, baseUrl);
}

/**
 * The message a failed probe (model list, Test Key, Test connection) shows. The server's two
 * endpoint-pin refusals are written for API callers ("supply an apiKey in this request"), so they are
 * replaced with plain language. Anything else keeps the thrown message, usually the provider's own.
 *
 * @complexity Time/space: O(1).
 */
export function describeProbeError(e: unknown, fallback: string): string {
  if (e instanceof ApiError && e.code === "STORED_CREDENTIAL_ENDPOINT_MISMATCH") return STORED_KEY_OTHER_PROVIDER_COPY;
  if (e instanceof ApiError && e.code === "STORED_CREDENTIAL_ENDPOINT_UNSET") return STORED_KEY_NO_ENDPOINT_COPY;
  return e instanceof Error ? e.message : fallback;
}

/**
 * `@jini-ai/ui` `ExecutionTab`'s `describeProbeError` prop for a screen whose translator is `t`:
 * {@link describeProbeError}'s wording, translated. A provider's own message misses the dictionary and
 * stays as sent; a non-`Error` throw is worded by its string form. Both admin mounts of `ExecutionTab`
 * (Settings -> Execution mode, AI Assistant -> Admin AI Assistant) pass this, so the two cannot word a
 * refused model discovery or Test connection differently.
 *
 * @complexity Time/space: O(1) per call.
 */
export function createProbeErrorDescriber(t: Translate): (error: unknown) => string {
  return (error) => t(describeProbeError(error, String(error)));
}

/** Reference-counted chat activity for this document, including concurrent panes. */
import type { ChatTransport, RunHandlers } from "@jini-ai/chat/core";

export interface StreamActivity {
  active(required: Record<string, never>, optional?: Record<string, never>): boolean;
  retain(required: Record<string, never>, optional?: Record<string, never>): () => void;
  subscribe(required: { listener: () => void }, optional?: Record<string, never>): () => void;
}

/** Each retain has an idempotent release; the last release notifies idle stream owners.
 * @complexity O(listeners) per transition, O(active runs + listeners) space.
 */
export function createStreamActivity(_required = {}, _optional = {}): StreamActivity {
  let count = 0;
  const listeners = new Set<() => void>();
  const notify = () => { for (const listener of [...listeners]) listener(); };
  return {
    active: () => count > 0,
    retain: () => {
      count++;
      notify();
      let released = false;
      return () => { if (released) return; released = true; count--; notify(); };
    },
    subscribe: ({ listener }) => { listeners.add(listener); return () => { listeners.delete(listener); }; },
  };
}

/** Composition-root document instance; transports and page-control share this exact owner. */
export const adminStreamActivity = createStreamActivity({});

/** Private host lifecycle carried through Jini's unchanged RunHandlers contract. */
export const subscriptionEnded = Symbol("subscription-ended");
export type TrackedRunHandlers = RunHandlers & { [subscriptionEnded]?: () => void };

/** Keep page-control available from dispatch through terminal completion, across all transports.
 * Transient onError notifications do not end a durable run; onDone, detach, or dispatch rejection do.
 * @returns The same transport API with tracked start/reattach lifetimes.
 * @complexity O(1) per run plus activity listeners; no additional network requests.
 */
export function trackTransportActivity(
  { transport, activity }: { transport: ChatTransport; activity: StreamActivity }, _optional = {},
): ChatTransport {
  async function track<Result>(handlers: RunHandlers, signal: AbortSignal | undefined, work: (tracked: RunHandlers) => Promise<Result>): Promise<Result> {
    const release = activity.retain({});
    const finish = () => { signal?.removeEventListener("abort", finish); release(); };
    if (signal?.aborted) finish();
    else signal?.addEventListener("abort", finish, { once: true });
    try {
      const tracked: TrackedRunHandlers = { ...handlers, [subscriptionEnded]: finish,
        onDone: (events) => { finish(); handlers.onDone(events); } };
      return await work(tracked);
    } catch (error) { finish(); throw error; }
  }
  return {
    ...transport,
    startRun: (input, handlers) => track(handlers, input.signal, (tracked) => transport.startRun(input, tracked)),
    reattachRun: (runId, handlers, options) => track(handlers, options?.signal, (tracked) => transport.reattachRun(runId, tracked, options)),
  };
}

/** EventSource-compatible page transport, with ownership delegated to browser-stream. */
import { startBrowserStream, type BrowserStreamPorts } from "./browser-stream";
import { adminStreamActivity, type StreamActivity } from "./stream-activity";

type Source = Pick<EventSource, "addEventListener" | "close" | "readyState">;

/**
 * Preserve the bridge's EventSource contract across idle close/reopen, including native errors.
 * Pausing emits an error so the bridge clears its now-invalid bind token; reconnect attaches anew.
 * Message/command frames remain local: rebroadcasting them could click another tab's page.
 * @returns A disposable EventSource facade; native sources retain their own reconnect/backoff.
 * @complexity O(1) state and three listeners per live source.
 */
export function openTabEventSource(
  { url }: { url: string },
  { open = (url: string): Source => new EventSource(url), ports, activity = adminStreamActivity }: {
    open?: (url: string) => Source; ports?: BrowserStreamPorts; activity?: StreamActivity;
  } = {},
): EventSource {
  let source: Source | undefined;
  let disposed = false;
  class ManagedSource extends EventTarget implements EventSource {
    // EventTarget already supports these listeners; expose EventSource's typed event overloads.
    readonly addEventListener = super.addEventListener.bind(this) as EventSource["addEventListener"];
    readonly removeEventListener = super.removeEventListener.bind(this) as EventSource["removeEventListener"];
    readonly CONNECTING = 0;
    readonly OPEN = 1;
    readonly CLOSED = 2;
    readonly url = url;
    readonly withCredentials = false;
    onerror: EventSource["onerror"] = null;
    onmessage: EventSource["onmessage"] = null;
    onopen: EventSource["onopen"] = null;
    get readyState(): number { return disposed ? 2 : source?.readyState ?? 0; }
    close(): void { if (disposed) return; disposed = true; stop(); }
  }
  const managed = new ManagedSource();
  // Assigned before `managed` is returned, so no caller can reach `close()` while it is unset.
  const stop = startBrowserStream({ key: url, connect: () => {
    const current = open(url);
    source = current;
    for (const kind of ["message", "error", "open"] as const) {
      current.addEventListener(kind, (event) => {
        if (source !== current || disposed) return;
        const message = event as MessageEvent<string>;
        const forwarded = kind === "message"
          ? new MessageEvent("message", { data: message.data, lastEventId: message.lastEventId, origin: message.origin })
          : new Event(kind);
        managed.dispatchEvent(forwarded);
        if (kind === "message") managed.onmessage?.call(managed, forwarded as MessageEvent);
        else if (kind === "error") managed.onerror?.call(managed, forwarded);
        else managed.onopen?.call(managed, forwarded);
      });
    }
    return () => {
      source = undefined;
      current.close();
      // The daemon revokes its token on close. Clear the bridge's copy before another run starts.
      if (!disposed) {
        const event = new Event("error");
        managed.dispatchEvent(event);
        managed.onerror?.call(managed, event);
      }
    };
  } }, { ports, scope: "tab", activity });
  return managed;
}

/**
 * The post and page editors' Save button when nothing changed (owner, 2026-10-10): Save is never
 * disabled, in case a real change wasn't picked up. With changes it saves; with none it opens the
 * "Nothing changed. Save anyway?" warning, whose "Save anyway" closes it and saves anyway. The server
 * skips the write when the content really is identical and answers with the same version.
 *
 * @complexity O(1) — three closures, one branch (plus the optional flush).
 */
export function unchangedSaveHandlers(
  required: { dirty: boolean; save: () => Promise<void>; setConfirmingUnchangedSave: (open: boolean) => void },
  optional: {
    /** Folds an edit the editor hasn't reported yet (an open Interactive text session) into the
     *  working copy and says whether it differs from the saved body. Without it, typing in the
     *  Interactive tab and pressing Save showed "Nothing changed": the RTE only reports on close.
     *  "failed" means the flush already showed its own error, so neither save nor warn. */
    flushPendingEdits?: () => Promise<"changed" | "unchanged" | "failed">;
  } = {}
): { onSave: () => void; onUnchangedSaveConfirm: () => void; onUnchangedSaveCancel: () => void } {
  const { dirty, save, setConfirmingUnchangedSave } = required;
  const { flushPendingEdits } = optional;
  const saveOrWarn = async () => {
    const pending = flushPendingEdits ? await flushPendingEdits() : "unchanged";
    if (pending === "changed") await save();
    else if (pending === "unchanged") setConfirmingUnchangedSave(true);
  };
  return {
    onSave: () => void (dirty ? save() : saveOrWarn()),
    onUnchangedSaveConfirm: () => {
      setConfirmingUnchangedSave(false);
      void save();
    },
    onUnchangedSaveCancel: () => setConfirmingUnchangedSave(false),
  };
}

/**
 * @file A repeating timer that only runs while the window is visible.
 *
 * An idle app must not keep working for nobody: a poll that keeps firing while the window is
 * minimized, on another Space, or fully covered wakes the renderer and main (and whatever main does
 * per tick) for a screen no one can see. This stops the timer on `visibilitychange` → hidden and,
 * on → visible, ticks once at once (so a shown window is never a whole period stale) and restarts it.
 *
 * Plain function, not a hook, so it is testable without a DOM; `useComposerCapabilities` is its caller.
 * The admin's copy of `apps/desktop/src/renderer/visible-interval.ts` (separate apps, no shared
 * package between them yet), kept identical so `development/scripts/check-idle-motion.ts` can allow
 * both helpers for the same reason.
 */

/** The slice of `document` this reads. */
export interface VisibilitySource {
  readonly visibilityState: DocumentVisibilityState;
  addEventListener(type: "visibilitychange", listener: () => void): void;
  removeEventListener(type: "visibilitychange", listener: () => void): void;
}

/** The two timer functions this uses, injectable for tests. */
export interface IntervalTimers {
  setInterval(callback: () => void, ms: number): unknown;
  clearInterval(handle: unknown): void;
}

const WINDOW_TIMERS: IntervalTimers = {
  setInterval: (callback, ms) => globalThis.setInterval(callback, ms),
  clearInterval: (handle) => globalThis.clearInterval(handle as ReturnType<typeof globalThis.setInterval>),
};

/**
 * Call `tick` every `periodMs` while `doc` is visible. Does not tick at start — the caller does its
 * own first load.
 *
 * @returns a stop function that clears the timer and the listener.
 * @complexity O(1) per visibility change.
 */
export function startVisibleInterval(
  tick: () => void,
  periodMs: number,
  doc: VisibilitySource = document,
  timers: IntervalTimers = WINDOW_TIMERS,
): () => void {
  let handle: unknown = null;
  // Only ever called with no timer running: at start (nothing scheduled yet) and from
  // `onVisibility` after its own `handle !== null` early return, so no second timer can stack.
  const run = () => {
    handle = timers.setInterval(tick, periodMs);
  };
  const halt = () => {
    if (handle !== null) timers.clearInterval(handle);
    handle = null;
  };
  const onVisibility = () => {
    if (doc.visibilityState === "hidden") return halt();
    if (handle !== null) return;
    tick();
    run();
  };

  if (doc.visibilityState !== "hidden") run();
  doc.addEventListener("visibilitychange", onVisibility);
  return () => {
    halt();
    doc.removeEventListener("visibilitychange", onVisibility);
  };
}

