/**
 * @file "+ Create website"'s optional "Connect services" step (2026-09-29): the same access-token
 * fields the admin's create form offers, delivered through Tovu's own CLI like everything else this
 * shell does to a site.
 *
 * - Which services are offered: `tovu agent-plugins token-sign-in --json` — the bundled Agent Plugins
 *   that declare token sign-in. Nothing here names a vendor.
 * - The tokens themselves go to `tovu init --agent-plugin-tokens-stdin` (`site-dir-store.ts`), which
 *   checks each before creating the site and seals them for its first boot. This file only reads
 *   back the one `agent-plugin-tokens: saved|failed <ids>` line that command prints.
 *
 * No token is ever put on argv, in env, in a log line, or in an error message.
 */
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawn as nodeSpawn } from "node:child_process";
import type { SpawnOptions } from "node:child_process";
import type { Readable } from "node:stream";

import { buildCliSpawnPlan, buildCliEnv, parseCliErrorLine } from "./tovu-server.ts";

/** One service the create form can offer a token field for — mirrors `contracts/project.ts`. */
interface TokenSignInPlugin {
  pluginId: string;
  displayName: string;
  helpUrl: string;
}

/** What `tovu init` reported for the tokens it was given — mirrors `contracts/project.ts`. */
interface CreatedAgentPluginTokens {
  status: "saved" | "failed";
  pluginIds: string[];
}

interface ListChildLike {
  stdout: Readable;
  stderr: Readable;
  once(event: "exit", listener: (code: number | null) => void): void;
  once(event: "error", listener: (error: Error) => void): void;
}

type ListSpawnFn = (command: string, args: string[], options: SpawnOptions) => ListChildLike;

const PLUGIN_ID_PATTERN = /^[a-z0-9][a-z0-9-]{0,63}$/;
const MAX_TOKENS = 8;
const MAX_TOKEN_LENGTH = 4096;

/**
 * The create input's `agentPluginTokens`, trimmed, blanks dropped — `{}` when none. The renderer is
 * not trusted: anything that is not a small map of plugin ids to strings is refused, the same shape
 * `tovu init` re-checks.
 *
 * @throws {Error} a malformed map. The message names no token.
 * @complexity O(n) in the entry count (bounded).
 */
function cleanCreateTokens(raw: unknown): Record<string, string> {
  if (raw === undefined || raw === null) return {};
  if (!isSmallMap(raw) || !Object.entries(raw).every(([pluginId, value]) => isTokenEntry(pluginId, value))) {
    throw new Error("The access tokens for the new site were not in the expected shape. Nothing was created.");
  }
  const out: Record<string, string> = {};
  for (const [pluginId, value] of Object.entries(raw as Record<string, string>)) {
    if (value.trim() !== "") out[pluginId] = value.trim();
  }
  return out;
}

/** A plain object with at most {@link MAX_TOKENS} entries. */
function isSmallMap(raw: unknown): raw is Record<string, unknown> {
  return typeof raw === "object" && raw !== null && !Array.isArray(raw) && Object.keys(raw).length <= MAX_TOKENS;
}

/** A plugin id `tovu init` accepts, mapped to a string it accepts. */
function isTokenEntry(pluginId: string, value: unknown): boolean {
  return PLUGIN_ID_PATTERN.test(pluginId) && typeof value === "string" && value.length <= MAX_TOKEN_LENGTH;
}

/**
 * Tokens reach a site only through `tovu init`, which runs only for an EMPTY folder; adopting an
 * existing site would drop them silently, so that combination is refused.
 * @throws {Error} tokens were given and the picked folder already holds a site.
 */
function assertTokensCanReachFolder(tokens: Readonly<Record<string, string>>, folderWasEmpty: boolean): void {
  if (Object.keys(tokens).length > 0 && !folderWasEmpty) {
    throw new Error("That folder already holds a website, so the access tokens could not be added to it. Choose an empty folder, or leave the tokens empty and ask the site's assistant to connect the service.");
  }
}

/**
 * The `adoptSiteDir` options that hand `tokens` to `tovu init` and capture its output into `sink`,
 * or `{}` when there are none — so a create with no token runs exactly the command it always did.
 */
function initTokenOptions(
  tokens: Readonly<Record<string, string>>,
  sink: { output: string },
): { agentPluginTokens?: Readonly<Record<string, string>>; onInitOutput?: (output: string) => void } {
  if (Object.keys(tokens).length === 0) return {};
  return { agentPluginTokens: tokens, onInitOutput: (output) => void (sink.output = output) };
}

/** `record`, plus the token outcome `tovu init` printed when there was one. */
function withCreatedTokens<T extends object>(record: T, initOutput: string): T & { agentPluginTokens?: CreatedAgentPluginTokens } {
  const tokens = parseCreatedTokensLine(initOutput);
  return tokens === null ? record : { ...record, agentPluginTokens: tokens };
}

/**
 * `tovu init`'s `agent-plugin-tokens: saved|failed <ids>` line, or `null` when it printed none (no
 * tokens were given).
 * @complexity O(n) in the output length.
 */
function parseCreatedTokensLine(output: string): CreatedAgentPluginTokens | null {
  const match = /^agent-plugin-tokens: (saved|failed) ([a-z0-9,-]+)$/m.exec(output);
  if (!match) return null;
  return { status: match[1] as CreatedAgentPluginTokens["status"], pluginIds: match[2]!.split(",").filter(Boolean) };
}

/** Only well-formed entries survive: this list is rendered as links. */
function parsePluginList(stdout: string): TokenSignInPlugin[] {
  const line = stdout.split(/\r?\n/).reverse().find((candidate) => candidate.trim().startsWith("{"));
  const parsed = JSON.parse(line ?? "{}") as { plugins?: unknown };
  const plugins = Array.isArray(parsed.plugins) ? parsed.plugins : [];
  return plugins.flatMap((entry): TokenSignInPlugin[] => {
    const { pluginId, displayName, helpUrl } = (entry ?? {}) as Record<string, unknown>;
    if (typeof pluginId !== "string" || !PLUGIN_ID_PATTERN.test(pluginId) || typeof displayName !== "string" || typeof helpUrl !== "string") return [];
    return /^https:\/\//.test(helpUrl) ? [{ pluginId, displayName, helpUrl }] : [];
  });
}

/**
 * Runs `tovu agent-plugins token-sign-in --json`. The CLI's import chain needs a site dir in its env
 * even for a command that touches none (`site-dir-store.ts`'s `initSiteDir` doc), so it is given a
 * fresh empty temp dir, removed afterwards.
 *
 * @throws {Error} the CLI failed; the create form then simply offers no services.
 * @complexity One CLI spawn.
 */
async function listTokenSignInPlugins(input: {
  repoRoot: string;
  cliMode?: "source" | "compiled";
  baseEnv?: NodeJS.ProcessEnv;
  spawnFn?: ListSpawnFn;
}): Promise<TokenSignInPlugin[]> {
  const spawnFn = input.spawnFn ?? (nodeSpawn as ListSpawnFn);
  const scratch = fs.mkdtempSync(path.join(os.tmpdir(), "tovu-token-sign-in-"));
  try {
    const plan = buildCliSpawnPlan({ repoRoot: input.repoRoot, cliMode: input.cliMode, cliArgs: ["agent-plugins", "token-sign-in", "--json"] });
    const child = spawnFn(plan.command, plan.args, { env: buildCliEnv({ baseEnv: input.baseEnv, siteDir: scratch }), stdio: ["ignore", "pipe", "pipe"] });
    const { code, stdout, stderr } = await new Promise<{ code: number | null; stdout: string; stderr: string }>((resolve, reject) => {
      let out = "";
      let err = "";
      child.stdout.setEncoding("utf8");
      child.stderr.setEncoding("utf8");
      child.stdout.on("data", (chunk) => (out += chunk));
      child.stderr.on("data", (chunk) => (err += chunk));
      child.once("error", reject);
      child.once("exit", (exitCode) => resolve({ code: exitCode, stdout: out, stderr: err }));
    });
    if (code !== 0) {
      const cliError = parseCliErrorLine(stderr);
      throw new Error(`tovu agent-plugins token-sign-in failed: ${cliError === null ? stderr.trim() : `${cliError.code}: ${cliError.message}`}`);
    }
    return parsePluginList(stdout);
  } finally {
    fs.rmSync(scratch, { recursive: true, force: true });
  }
}

export { cleanCreateTokens, assertTokensCanReachFolder, initTokenOptions, withCreatedTokens, parseCreatedTokensLine, listTokenSignInPlugins };
export type { TokenSignInPlugin, CreatedAgentPluginTokens, ListSpawnFn };

/** Thin Tovu adapter: Electron owns the version; this channel exposes only its string value. */
import { execFile } from 'node:child_process';
import { RUNNER_APP_VERSION_CHANNEL } from './contracts/app-version.ts';

/** Resolves the nearest `desktop-v*` tag name, e.g. `desktop-v0.1.24`, or rejects. */
export type DescribeDesktopTag = (input: { cwd: string }) => Promise<string>;

/** Real git port. Async so a slow or missing git never holds up the window opening. */
export const describeDesktopTag: DescribeDesktopTag = ({ cwd }) => new Promise((resolve, reject) => {
  execFile('git', ['describe', '--tags', '--match', 'desktop-v*', '--abbrev=0'],
    { cwd, timeout: 5_000, windowsHide: true },
    (error, stdout) => (error ? reject(error) : resolve(String(stdout))));
});

/**
 * Release tags bump package.json only on the tag commit, so a dev launch from any branch showed
 * the last bumped version and passed for an older release (owner 2026-10-26). Dev therefore shows
 * the nearest `desktop-v*` tag plus `-dev`, or package.json's version plus `-dev` without git.
 * Never rejects. @complexity O(1) besides one git process.
 */
export async function devAppVersion(
  { repoRoot, packageVersion }: { repoRoot: string; packageVersion: string },
  { describeTag = describeDesktopTag }: { describeTag?: DescribeDesktopTag } = {},
): Promise<string> {
  try {
    const tag = (await describeTag({ cwd: repoRoot })).trim();
    if (tag.startsWith('desktop-v') && tag.length > 'desktop-v'.length) return `${tag.slice('desktop-v'.length)}-dev`;
  } catch { /* no git, not a checkout, or no tag: the package fallback below is still marked dev */ }
  return `${packageVersion}-dev`;
}

/**
 * Register once before the sites home window opens. Native IPC/getVersion errors propagate.
 * Packaged builds read app.getVersion() on each request; a dev launch starts one git read here.
 * @param required The native IPC registration and Electron app ports.
 * @param optional The repo root git runs in, and the git port for tests.
 * @returns Nothing; registers one read-only handler.
 * @complexity O(1) time and space per registration and request.
 */
export function registerAppVersionIpc(
  { ipcMain, app }: {
    ipcMain: { handle: (channel: string, listener: () => string | Promise<string>) => void };
    app: { getVersion: () => string; isPackaged: boolean };
  },
  { repoRoot = process.cwd(), describeTag }: { repoRoot?: string; describeTag?: DescribeDesktopTag } = {},
): void {
  if (app.isPackaged) {
    ipcMain.handle(RUNNER_APP_VERSION_CHANNEL, () => app.getVersion());
    return;
  }
  const dev = devAppVersion({ repoRoot, packageVersion: app.getVersion() }, { describeTag });
  ipcMain.handle(RUNNER_APP_VERSION_CHANNEL, () => dev);
}

/**
 * The Runner top nav's sections, and the `desktop.*` tool surface the left-hand chat
 * drives them with.
 *
 * Two chats exist in this app and they must never blur:
 *
 *   - The LEFT chat is Runner's operator agent. It owns the fleet. Its tools are
 *     the `desktop.*` verbs declared here.
 *   - The RIGHT chat is Tovu's own site assistant, which arrives with the Tovu
 *     admin mounted into the main content area. It owns one site's content.
 *
 * ADR-014 fixes the direction: Runner composes site tools plus its own; Tovu never
 * imports Runner tools. Keeping every verb below under a `desktop.` prefix is what
 * makes that boundary mechanical instead of a convention — a site tool can never
 * collide with a fleet tool, so the left chat cannot accidentally edit a post.
 *
 * The converse half of that sentence used to read "and the right chat cannot stop a
 * process", with the prefix as the reason, then (ADR-061) a second, narrower allowlist
 * kept it away from the rest. Both claims were stale as of
 * 2026-08: the operator decided the two chats should carry identical capability (single
 * developer, single-user desktop app, no second party on either side of the Runner↔Tovu
 * line), accepting the residual exposure that user-supplied site content could prompt an
 * assistant to act on another project. The historical mirror represented that trust decision;
 * this checkout never imported it or supplied its advertised enforcement gates.
 * site-assistant-tools.ts (contracts/site-assistant-tools.ts) was deleted 2026-10-03: unused; see development/DELETED-CODE.md.
 * The prefix still does its own job (no
 * collisions, no unprefixed verb, Tovu never importing a Runner tool by accident); it
 * was just never what separated the two chats' capability, in either era.
 *
 * `RunnerSectionId` values are a public contract. They appear in agent tool schemas
 * and in URLs, so renaming one silently breaks saved conversations and deep links.
 * Add, deprecate, alias — but do not rename in place.
 */

export type RunnerSectionGroupId = 'workspace' | 'work' | 'operations' | 'access';

export type RunnerSectionId =
  | 'home'
  | 'projects'
  | 'templates'
  | 'marketplace'
  | 'tasks'
  | 'generation'
  | 'activity'
  | 'updates'
  | 'deploy'
  | 'diagnostics'
  | 'api-keys'
  | 'settings'
  | 'account';

export interface RunnerSectionGroup {
  id: RunnerSectionGroupId;
  label: string;
}

export interface RunnerSection {
  id: RunnerSectionId;
  group: RunnerSectionGroupId;
  label: string;
  /**
   * Hidden from the nav, but still registered. Seven sections are parked this way
   * (see TODO.md): six because twelve entries was more than the app can currently
   * justify and their shape isn't settled yet, plus `tasks` (owner request, 2026-09-12
   * — remove the icon from the nav without breaking the public `RunnerSectionId`
   * contract or dropping its verbs). Kept in the registry rather than deleted or
   * commented out: a literal comment would break the `RunnerSectionId` union and
   * silently drop their verbs from `runnerToolNames()`, which is a worse outcome than
   * one boolean. Flip to `false` — or delete the line — to bring one back.
   */
  hidden?: boolean;
  /**
   * Written for the model, not for the user. This is what the left chat reads to
   * decide whether a request belongs to this section, so it states what the section
   * governs rather than describing the screen.
   */
  agentDescription: string;
  /** The `desktop.*` verbs this section owns. Empty means read-only/navigation-only. */
  tools: readonly string[];
}

