/**
 * The locale the renderer runs in: the browser's `navigator.language`, or `en` where there is no
 * navigator at all (a non-browser host). Pure given its port; no errors.
 * @complexity O(1).
 */
export function runtimeLocale(
  _input: Record<string, never> = {},
  { navigator: nav = globalThis.navigator }: { navigator?: Pick<Navigator, 'language'> | null } = {},
): string {
  return nav == null ? 'en' : nav.language;
}

export function desktopCopy({ locale }: { locale: string }, _optionalArgs = {}): DesktopCopy {
  const normalized = locale.replace(/_/g, '-');
  const key = Object.keys(COPY).find(key => key.toLowerCase() === normalized.toLowerCase())
    ?? (normalized.toLowerCase().startsWith('zh') ? (/tw|hk|hant/i.test(normalized) ? 'zh-TW' : 'zh-CN') : normalized.split('-')[0] ?? 'en');
  const row = COPY[key] ?? COPY.en!;
  const [settings, automaticUpdates, saveUpdateError, restart, restarting] = row;
  const [invalid, empty, incomplete, unreadable, add, start] = SITE_ERROR_COPY[key] ?? SITE_ERROR_COPY.en!;
  const [title, devBody, otherBody, confirm, confirming] = STOP_CONFIRM_COPY[key] ?? STOP_CONFIRM_COPY.en!;
  return { settings, automaticUpdates, saveUpdateError, restart, restarting, siteErrors: { invalid, empty, incomplete, unreadable, add, start },
    stopConfirm: { title, devBody, otherBody, confirm, confirming } };
}

/**
 * @file Stop a site that another process serves — the card's Stop for a site this app only attached
 * to through the shared running-site lease (owner 2026-10-13).
 *
 * The case it exists for is `npm run dev`: `development/scripts/dev.mjs` runs `tsx watch
 * apps/website/src/index.ts`, and the server that `tsx watch` spawns is what claims the lease, so
 * the lease's pid is that server — four processes below the terminal's `npm run dev`:
 *
 *     npm run dev → node dev.mjs → npm exec tsx watch → node tsx watch → node index.ts (lease pid)
 *
 * **It signals the LAUNCHER, never the lease pid, when there is one.** SIGTERM to the server alone
 * leaves `tsx watch` alive and waiting for a file change, which then starts a second server that
 * fights the one Start launches in this app; and admin Vite keeps running. dev.mjs's own
 * SIGTERM handler is the clean exit — the same `shutdown(0)` as Ctrl-C in its terminal: it
 * SIGTERMs every child's process group, then SIGKILLs what is left after 1.5 s and exits. With no
 * dev.mjs above the server (a bare `tovu serve`, a sibling desktop instance's child) the lease pid
 * itself is signalled, and its own BR-07 shutdown drains it.
 *
 * **Identity before every signal.** The lease records only `{pid, started, token}`, and the OS may
 * hand a dead server's pid to anything. `site-process-registry.ts`'s `isLiveServeRow` proves
 * identity by `--port`/site dir in argv, which an `npm run dev` server does not carry (its site
 * comes from env), so the proof here is start time instead: the process must have existed BEFORE
 * the lease was claimed. A recycled pid started later and fails it; so does a launcher that was not
 * this server's. Re-proved immediately before SIGTERM, against the same lease token. Anything that
 * cannot be proved (no `ps`, win32, a vanished parent) fails closed: no Stop is offered, and a
 * stop already asked for refuses instead of signalling.
 *
 * Never escalates to SIGKILL itself: a stack that does not exit inside the timeout is reported,
 * and left for the operator, rather than killed on a guess.
 */
import { execFileSync } from "node:child_process";
import { readProcessCommand, readProcessParentPid } from "./site-process-registry.ts";

/** Who started an externally served site, as far as the card's confirm needs to say. */
export type ExternalLauncher = "npm-run-dev" | "other";

/** The lease fields this module reads — a structural subset of Jini's `DirectoryRunningRecord`. */
export interface ExternalLease {
  pid: number;
  token: string;
  started: string;
}

/** OS reads and effects, injected so tests never touch a real process. */
export interface ExternalStopPorts {
  readCommand: (pid: number) => string | null;
  readParentPid: (pid: number) => number | null;
  /** Process start time in epoch ms, or `null` when the pid is gone or cannot be read. */
  readStartMs: (pid: number) => number | null;
  kill: (pid: number, signal: NodeJS.Signals) => void;
  sleep: (ms: number) => Promise<void>;
  nowMs: () => number;
}

/** What to signal for one lease. */
export interface ExternalStopTarget {
  pid: number;
  launcher: ExternalLauncher;
  /** The argv read when the target was resolved; re-read and compared before signalling. */
  command: string;
}

export const EXTERNAL_STOP_UNCONFIRMED = "Could not confirm which process runs this site, so nothing was stopped. Stop it where it was started.";

/** dev.mjs's own argv, however it was launched (`node development/scripts/dev.mjs`, or absolute). */
const DEV_LAUNCHER = /(?:^|[\s/])development\/scripts\/dev\.mjs(?:\s|$)/;
/** Lease pid → dev.mjs is 3 hops today; a cap keeps a cycle in `ps` output from looping. */
const MAX_ANCESTORS = 6;
const STOP_TIMEOUT_MS = 15_000;
const STOP_POLL_MS = 200;

/**
 * Whether `pid` is a live process that existed before `lease` was claimed — the PID-reuse proof.
 * `ps`'s start time is whole seconds, truncated, so a genuine process can only read earlier, never later.
 * @complexity O(1) beyond one `ps` call.
 */
function predatesLease(pid: number, lease: ExternalLease, ports: Pick<ExternalStopPorts, "readStartMs">): boolean {
  const startMs = ports.readStartMs(pid);
  const claimedMs = Date.parse(lease.started);
  return startMs !== null && Number.isFinite(claimedMs) && startMs <= claimedMs;
}

/**
 * The process a Stop should SIGTERM for `lease`: the dev.mjs ancestor of the lease pid when there is
 * one, else the lease pid itself — or `null` when identity cannot be proved.
 * @returns `null` when the lease pid fails {@link predatesLease}, its argv is unreadable, or a dev.mjs
 *   ancestor fails {@link predatesLease}.
 * @complexity O(MAX_ANCESTORS) `ps` calls.
 */
export function resolveExternalStopTarget(
  { lease }: { lease: ExternalLease },
  { ports }: { ports: Pick<ExternalStopPorts, "readCommand" | "readParentPid" | "readStartMs"> },
): ExternalStopTarget | null {
  const serverCommand = ports.readCommand(lease.pid);
  if (serverCommand === null || !predatesLease(lease.pid, lease, ports)) return null;
  let pid = ports.readParentPid(lease.pid);
  for (let depth = 0; pid !== null && pid > 1 && depth < MAX_ANCESTORS; depth++) {
    const command = ports.readCommand(pid);
    if (command !== null && DEV_LAUNCHER.test(command)) {
      return predatesLease(pid, lease, ports) ? { pid, launcher: "npm-run-dev", command } : null;
    }
    pid = ports.readParentPid(pid);
  }
  return { pid: lease.pid, launcher: "other", command: serverCommand };
}

/**
 * SIGTERM the process behind `lease` and wait until both the lease is released and that process is gone.
 *
 * Waits on the target's exit as well as the lease because, for dev.mjs, the server (and its lease)
 * goes first while admin Vite may still hold its port; a Start that raced that would probe a dying
 * Vite. A lease that changed hands before the signal (already stopped, or dev.mjs restarted its API
 * child) is a no-op: the caller's fresh record then says what is actually running.
 *
 * @throws {Error} {@link EXTERNAL_STOP_UNCONFIRMED} when identity fails, or a timeout message.
 * @complexity O(timeoutMs / pollMs) polls, each one lease read plus one `ps` call.
 */
export async function stopExternalSite(
  { lease, readLease }: { lease: ExternalLease; readLease: () => Pick<ExternalLease, "token"> | null | undefined },
  { ports, timeoutMs = STOP_TIMEOUT_MS, pollMs = STOP_POLL_MS }: { ports: ExternalStopPorts; timeoutMs?: number; pollMs?: number },
): Promise<void> {
  const target = resolveExternalStopTarget({ lease }, { ports });
  if (target === null) throw new Error(EXTERNAL_STOP_UNCONFIRMED);
  if (readLease()?.token !== lease.token) return;
  if (ports.readCommand(target.pid) !== target.command || !predatesLease(target.pid, lease, ports)) throw new Error(EXTERNAL_STOP_UNCONFIRMED);
  ports.kill(target.pid, "SIGTERM");
  await waitForExternalSiteStop({ lease, target, readLease, ports }, { timeoutMs, pollMs });
}

/** Wait for both the lease and launcher to drain; the launcher may outlive the server's lease.
 * @returns When neither still belongs to this stop request.
 * @throws The existing timeout refusal; never escalates to SIGKILL.
 * @complexity O(timeoutMs / pollMs) lease/process probes.
 */
export async function waitForExternalSiteStop(
  { lease, target, readLease, ports }: { lease: ExternalLease; target: ExternalStopTarget; readLease: () => Pick<ExternalLease, "token"> | null | undefined; ports: ExternalStopPorts },
  { timeoutMs = STOP_TIMEOUT_MS, pollMs = STOP_POLL_MS }: { timeoutMs?: number; pollMs?: number } = {},
): Promise<void> {
  const deadline = ports.nowMs() + timeoutMs;
  while (readLease()?.token === lease.token || predatesLease(target.pid, lease, ports)) {
    if (ports.nowMs() >= deadline) throw new Error(`The site did not stop within ${Math.round(timeoutMs / 1000)} s. Stop it where it was started.`);
    await ports.sleep(pollMs);
  }
}

/** `ps` with `args`, in the C locale so its dates parse; throws when `ps` exits non-zero (a gone pid). */
function runPsInCLocale(args: string[]): string {
  return execFileSync("ps", args, { encoding: "utf8", env: { ...process.env, LC_ALL: "C" } });
}

/**
 * Process start time via `ps -o lstart=` (argv-free, like `readProcessCommand`), in the C locale so
 * the date parses. `null` on win32, for a gone pid, or for output that does not parse.
 * @param options.runPs runs `ps` and returns its stdout (test seam); defaults to the real `ps`.
 * @complexity O(1); one subprocess call.
 */
export function readProcessStartMs(
  pid: number,
  platform: NodeJS.Platform = process.platform,
  { runPs = runPsInCLocale }: { runPs?: (args: string[]) => string } = {},
): number | null {
  if (platform === "win32") return null;
  try {
    const parsed = Date.parse(runPs(["-o", "lstart=", "-p", String(pid)]).trim());
    return Number.isFinite(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

export const NODE_PORTS: ExternalStopPorts = {
  readCommand: (pid) => readProcessCommand(pid),
  readParentPid: (pid) => readProcessParentPid(pid),
  readStartMs: (pid) => readProcessStartMs(pid),
  kill: (pid, signal) => { process.kill(pid, signal); },
  sleep: (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
  nowMs: () => Date.now(),
};

/** Leases remembered by {@link createExternalSiteStopper}; one per externally served site in practice. */
const LAUNCHER_CACHE_LIMIT = 64;

/**
 * The `ProjectIpcDeps.externalSites` port: `launcherOf` for the card record (polled every 4 s, so
 * cached per lease token — a lease's launcher cannot change), `stop` for the card's Stop. Only proved
 * answers are cached, so a transient `ps` failure hides Stop for one poll, not for the lease's life.
 * @complexity `launcherOf` O(1) on a cache hit, else {@link resolveExternalStopTarget}'s cost.
 */
export function createExternalSiteStopper(_required: Record<string, never> = {}, { ports = NODE_PORTS }: { ports?: ExternalStopPorts } = {}) {
  const launchers = new Map<string, ExternalLauncher>();
  return {
    launcherOf({ lease }: { lease: ExternalLease }, _options = {}): ExternalLauncher | null {
      const cached = launchers.get(lease.token);
      if (cached !== undefined) return cached;
      const launcher = resolveExternalStopTarget({ lease }, { ports })?.launcher ?? null;
      if (launcher === null) return null;
      if (launchers.size >= LAUNCHER_CACHE_LIMIT) launchers.delete(launchers.keys().next().value!);
      launchers.set(lease.token, launcher);
      return launcher;
    },
    stop: ({ lease, readLease }: { lease: ExternalLease; readLease: () => Pick<ExternalLease, "token"> | null | undefined }, _options = {}) =>
      stopExternalSite({ lease, readLease }, { ports }),
  };
}
export type ExternalSiteStopper = ReturnType<typeof createExternalSiteStopper>;

/** S3 trusted sites-home bridge. The CLI owns persistence; main owns dialogs, files and scheduling.
 * Shared keys are project references: nothing here copies a key into a site or opens an owner store.
 */
import { createKeyedSerializer } from './keyed-serializer.ts';
import { ownerStoreFailure } from './owner-store-cli.ts';
import { OWNER_STORE_CHANNELS, type LegacyImportReport, type LegacyImportSource, type OwnerStoreAction,
  type OwnerStoreCliFields, type OwnerStoreReply } from './contracts/owner-store.ts';

type OwnerStoreRun = <A extends OwnerStoreAction>(input: {
  action: A; fields: OwnerStoreCliFields[A];
}, options?: {}) => Promise<OwnerStoreReply<A>>;
interface OwnerStorePorts {
  run: OwnerStoreRun;
  /** Native open dialog for a legacy backup; never a renderer-supplied path. */
  pickBackup: () => Promise<string | null>;
  /** Native confirmation listing the dry run; true imports. */
  confirmImport: (input: { report: LegacyImportReport }) => Promise<boolean>;
}
interface OwnerStoreEvent { senderFrame: { url: string; parent: unknown } | null }
type Serialize = <T>(work: () => Promise<T>) => Promise<T>;
export interface OwnerStoreController {
  execute: (input: { action: OwnerStoreAction; input: unknown }, options?: {}) => Promise<OwnerStoreReply>;
}

/** Small strict outer request: destination paths/profile/unknown fields cannot become CLI options.
 * @throws A fixed error for invalid input; no submitted values are interpolated.
 * @complexity O(request bytes), capped at 64 KiB before spawning.
 */
function requestInput({ action, input }: { action: OwnerStoreAction; input: unknown }, _options = {}): Record<string, unknown> {
  if (!input || typeof input !== 'object' || Array.isArray(input)) throw new Error('Invalid shared-key request.');
  const fields: Record<OwnerStoreAction, readonly string[]> = { status: [], list: ['store'], put: ['entry', 'store'],
    import: ['source', 'passphrase'] };
  if (Object.keys(input).some(field => !fields[action].includes(field))) throw new Error('Invalid shared-key request.');
  if ('store' in input && input.store !== 'project') throw new Error('Invalid shared-key request.');
  if (Buffer.byteLength(JSON.stringify(input)) > 64 * 1024) throw new Error('Invalid shared-key request.');
  return input as Record<string, unknown>;
}

/** Validate required string fields without exposing content in thrown errors. */
function requiredString({ value }: { value: unknown }, _options = {}): string {
  if (typeof value !== 'string' || !value.trim() || value.includes('\0')) throw new Error('Invalid shared-key request.');
  return value;
}

/** The import's fixed source fields: a backup needs a passphrase and a main-picked file. */
async function importFields({ request, ports }: { request: Record<string, unknown>; ports: OwnerStorePorts }, _options = {}): Promise<Omit<OwnerStoreCliFields['import'], 'apply'> | null> {
  const source = request.source as LegacyImportSource;
  if (source === 'owner-store') {
    if (request.passphrase !== undefined) throw new Error('Invalid shared-key request.');
    return { source };
  }
  if (source !== 'backup') throw new Error('Invalid shared-key request.');
  const passphrase = requiredString({ value: request.passphrase });
  const filePath = await ports.pickBackup();
  return filePath === null ? null : { source, filePath, passphrase };
}

/** Dry run first, always; the native confirmation lists it; only a confirmed run writes.
 * The dialogs can stay open indefinitely, so only the CLI calls join the queue: an open picker or
 * confirmation must not stall other shared-key operations. The passphrase lives only in this call.
 * @complexity Two bounded CLI calls at most; cancelling either dialog never writes.
 */
async function importRequest({ request, ports, serialize }: {
  request: Record<string, unknown>; ports: OwnerStorePorts; serialize: Serialize;
}, _options = {}): Promise<OwnerStoreReply<'import'>> {
  const fields = await importFields({ request, ports });
  if (fields === null) return ownerStoreFailure({ action: 'import', code: 'cancelled' });
  const dryRun = await serialize(() => ports.run({ action: 'import', fields: { ...fields, apply: false } }));
  if (!dryRun.ok || !dryRun.data.items.some(item => item.status === 'new')) return dryRun;
  if (!await ports.confirmImport({ report: dryRun.data })) return ownerStoreFailure({ action: 'import', code: 'cancelled' });
  // The CLI rereads the source; naming the confirmed dry run's digest refuses a source replaced meanwhile.
  const expectedDigest = dryRun.data.sourceDigest;
  return serialize(() => ports.run({ action: 'import', fields: { ...fields, apply: true, ...(expectedDigest === undefined ? {} : { expectedDigest }) } }));
}

/** Only main binds the apply to the source digest; the renderer's reply never carries it. */
function withoutSourceDigest(reply: OwnerStoreReply<'import'>): OwnerStoreReply<'import'> {
  if (!reply.ok) return reply;
  const { sourceDigest: _mainOnly, ...data } = reply.data;
  return { ...reply, data };
}

/** Fixed-action dispatch; vault payload/revision validation stays with the CLI's existing owner.
 * @complexity O(request bytes) plus delegated work. Unknown actions fail before a spawn.
 */
async function executeRequest({ action, input, ports, serialize }: {
  action: OwnerStoreAction; input: unknown; ports: OwnerStorePorts; serialize: Serialize;
}): Promise<OwnerStoreReply> {
  const request = requestInput({ action, input });
  // A total Record keeps the exhaustiveness check without a switch.
  const handlers: Record<OwnerStoreAction, () => Promise<OwnerStoreReply>> = {
    status: () => serialize(() => ports.run({ action: 'status', fields: {} })),
    list: () => serialize(() => ports.run({ action: 'list', fields: request.store === 'project' ? { store: 'project' } : {} })),
    // Project attachments reference the original row; a save never creates a site copy.
    put: () => serialize(() => ports.run({ action: 'put', fields: { store: 'project', entry: request.entry as OwnerStoreCliFields['put']['entry'] } })),
    import: async () => withoutSourceDigest(await importRequest({ request, ports, serialize })),
  };
  return handlers[action]();
}

/** Serialize CLI work using the shell's existing keyed queue.
 * @param ports CLI, native backup picker and import confirmation; all effects are injected.
 * @returns The execute port. Opaque I/O errors become fixed wire failures.
 * @complexity One bounded CLI call per operation (two for a confirmed import).
 * @example const store = createOwnerStoreController({ run, pickBackup, confirmImport });
 */
export function createOwnerStoreController(ports: OwnerStorePorts, _options = {}): OwnerStoreController {
  const queue = createKeyedSerializer();
  const serialize: Serialize = work => queue.run('owner-store', work);
  return {
    execute: async ({ action, input }, _options = {}) => {
      try { return await executeRequest({ action, input, ports, serialize }); }
      catch { return ownerStoreFailure({ action, code: 'operation-failed' }); }
    },
  };
}

const SKIPPED: Record<NonNullable<LegacyImportReport['items'][number]['reason']>, string> = {
  'different-secret': 'a different key already uses its id',
  'label-taken': 'another project key already uses its name',
  kind: 'this kind of key cannot be a project key yet',
  owner: 'it belongs to another app',
};

/** The native confirmation's text for a dry run: what imports, what does not and why, which sites
 * keep their own copies. Labels/providers/site folders are metadata; no secret is in the report.
 * @complexity O(items + pending); pure.
 * @example const { message, detail } = importConfirmation({ report });
 */
export function importConfirmation({ report }: { report: LegacyImportReport }, _options = {}): { message: string; detail: string } {
  const name = (item: LegacyImportReport['items'][number]) => item.provider ? `${item.label} (${item.provider})` : item.label;
  const fresh = report.items.filter(item => item.status === 'new');
  const skipped = report.items.filter(item => item.reason !== undefined);
  const same = report.items.filter(item => item.status === 'already-imported').length;
  const lines = [`Imports into your project:`, ...fresh.map(item => `• ${name(item)}`)];
  if (skipped.length) lines.push('', 'Not imported:', ...skipped.map(item => `• ${name(item)}: ${SKIPPED[item.reason!]}`));
  if (same) lines.push('', `Already in your project: ${same}`);
  if (report.pending.length) {
    lines.push('', 'These sites keep their own copies. To use the project key there, attach it on that site\'s Keys screen:',
      ...[...new Set(report.pending.map(row => row.site))].map(site => `• ${site}`));
  }
  lines.push('', 'No site is changed, no default key changes, and the source is never modified.');
  return { message: `Import ${fresh.length} key${fresh.length === 1 ? '' : 's'} into your project?`, detail: lines.join('\n') };
}

/** Desktop start: delete a legacy owner store only when a read-only check finds it empty (0 entries
 * AND 0 grants); keep one that holds anything and say an import is available. Nothing creates an
 * owner store any more, so an empty one is only a leftover of an older start.
 * @param required The status CLI call, the four-file removal and the existing native notice.
 * @returns What it found; failures keep every file and stay silent beyond the log.
 * @complexity One bounded CLI call; at most four file removals.
 * @example await settleLegacyOwnerStore({ run, removeFiles, notify, log });
 */
export async function settleLegacyOwnerStore({ run, removeFiles, notify, log }: {
  run: OwnerStoreRun; removeFiles: () => void; notify: () => void; log: (message: string) => void;
}, _options = {}): Promise<'none' | 'removed' | 'available' | 'settled' | 'failed'> {
  try {
    const reply = await run({ action: 'status', fields: {} });
    if (!reply.ok) { log('tovu desktop: the older shared-key store could not be checked; it was left in place.'); return 'failed'; }
    if (reply.data.legacy === 'empty') { removeFiles(); return 'removed'; }
    if (reply.data.legacy === 'available') notify();
    return reply.data.legacy;
  } catch {
    log('tovu desktop: the older shared-key store could not be checked; it was left in place.');
    return 'failed';
  }
}

/** Register the fixed channels before opening sites home; refuse subframes and navigated pages.
 * @param required Main IPC registration, exact trusted URL predicate, controller execution port.
 * @returns Nothing; untrusted senders throw before parsing, dialogs or CLI work.
 * @complexity O(1) registration and frame check; request processing is delegated.
 * @example registerOwnerStoreIpc({ ipcMain, allowed, controller });
 */
export function registerOwnerStoreIpc({ ipcMain, allowed, controller }: {
  ipcMain: { handle: (channel: string, listener: (event: OwnerStoreEvent, input: unknown) => Promise<OwnerStoreReply>) => void };
  allowed: (url: string) => boolean; controller: Pick<OwnerStoreController, 'execute'>;
}, _options = {}): void {
  for (const action of Object.keys(OWNER_STORE_CHANNELS) as OwnerStoreAction[]) {
    ipcMain.handle(OWNER_STORE_CHANNELS[action], (event, input) => {
      // Same S2 boundary: sharing the file URL does not make an embedded subframe sites home.
      if (!event.senderFrame || event.senderFrame.parent !== null || !allowed(event.senderFrame.url)) {
        throw new Error('Shared keys are only available in the sites home window.');
      }
      return controller.execute({ action, input });
    });
  }
}

/**
 * Packaged release gates run a COPY of the app in a fresh OS temp dir. Launched inside the checkout,
 * a packaged app resolves a missing dependency from the checkout's node_modules (Node walks up the
 * directory tree), which hid the 0.1.13–0.1.17 missing-peer bug from every gate.
 */
import { cpSync, existsSync, mkdtempSync, realpathSync, rmSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { tmpdir } from "node:os";
import path from "node:path";

/** A fixed, path-only diagnostic safe for the packaged chat gate to print. */
export class PackagedGateIsolationError extends Error {}

/** Throws when `directory` or any real (symlink-resolved) ancestor has a node_modules. */
export function assertPackagedGateIsolation({ directory }: { directory: string }): void {
  // Walks up until `dirname` stops changing (the filesystem root, which is checked too). The loop
  // ends on its own condition rather than an inner `return`, so it has no unreachable exit path.
  for (let dir = realpathSync(directory), previous = ""; dir !== previous; previous = dir, dir = path.dirname(dir)) {
    const modules = path.join(dir, "node_modules");
    if (existsSync(modules)) throw new PackagedGateIsolationError(`Packaged gate isolation refused: ${modules} exists above ${directory}`);
  }
}

type SmokeTargets = { executablePath: string; nodeModulesDir: string };

/**
 * Copies the whole Tovu.app (or win-unpacked) into a fresh temp dir, runs the gate against the copy
 * with that dir as a safe cwd, and always removes the copy.
 * @param options.platform selects the copier (`cpSync` on win32, `cp -R` elsewhere); `process.platform` by default.
 */
export async function withIsolatedSmokeTargets(
  { targets, run }: { targets: SmokeTargets; run: (targets: SmokeTargets, directory: string) => void | Promise<void> },
  { tempRoot = tmpdir(), platform = process.platform }: { tempRoot?: string; platform?: NodeJS.Platform } = {},
): Promise<void> {
  // Real path: macOS tmpdir is /var -> /private/var, and an entry like bin/mcp-bridge.ts runs only
  // when argv[1] equals its own resolved URL, so a symlinked path makes it exit 0 without serving.
  const directory = realpathSync(mkdtempSync(path.join(tempRoot, "tovu-gate-")));
  try {
    assertPackagedGateIsolation({ directory });
    const executableDir = path.dirname(targets.executablePath);
    const appRoot = path.basename(executableDir) === "MacOS" ? path.resolve(executableDir, "../..") : executableDir;
    const copiedRoot = path.join(directory, path.basename(appRoot));
    // Keep framework-relative symlinks as-is. Never ditto: ditto-copied apps have hung before dyld.
    if (platform === "win32") cpSync(appRoot, copiedRoot, { recursive: true, verbatimSymlinks: true });
    else execFileSync("cp", ["-R", appRoot, copiedRoot], { stdio: "pipe" });
    await run({
      executablePath: path.join(copiedRoot, path.relative(appRoot, targets.executablePath)),
      nodeModulesDir: path.join(copiedRoot, path.relative(appRoot, targets.nodeModulesDir)),
    }, directory);
  } finally {
    rmSync(directory, { recursive: true, force: true });
  }
}

/** Tovu labels and consent policy over the existing Resources monitor and Jini growth owner. */
import { aggregateProcessMemory, createMemoryGrowthDetector, type ProcessMemoryReading } from '@jini-ai/diagnostics';
import type { Tracker } from '@jini-ai/diagnostics/observability';
import type { ProductConsent } from '../../website/src/server/runtime/composition/product-telemetry.ts';
import type { ResourcesSnapshot, ResourceProcess } from './contracts/resources.ts';

type Kind = 'main' | 'renderer' | 'server' | 'daemon' | 'other';
interface ProductMemoryTelemetry { tick(): Promise<void>; dispose(): void }
/** Fixed labels only: executable names, site IDs, paths and local PIDs never enter telemetry. */
function processKind({ row, desktopPid, rendererPids }: { row: ResourceProcess; desktopPid: number; rendererPids: ReadonlySet<number> }, _options = {}): Kind {
  if (row.pid === desktopPid) return 'main';
  if (row.role === 'site-server') return 'server';
  if (row.role === 'daemon') return 'daemon';
  return rendererPids.has(row.pid) ? 'renderer' : 'other';
}

/** Project monitor rows without any native resampling; main heap is available in this process.
 * @returns Local-only identities for growth tracking. @complexity O(p) monitor processes.
 */
export function projectMemoryProcesses({ snapshot, desktopPid, rendererPids, heapUsedBytes }: {
  snapshot: ResourcesSnapshot; desktopPid: number; rendererPids: ReadonlySet<number>; heapUsedBytes: number;
}, _options = {}): ProcessMemoryReading[] {
  return [snapshot.app, ...snapshot.sites].flatMap(group => group.processes).map(row => ({
    id: row.pid, kind: processKind({ row, desktopPid, rendererPids }), rssBytes: row.rssBytes,
    ...(row.pid === desktopPid ? { heapUsedBytes } : {}),
  }));
}

/** Jini owns grouping/deduplication and MB rounding; convert its summaries to byte gauges.
 * Counts and uptime retain their own units. Only fixed process kinds leave the monitor.
 * @returns Nothing; hands measurements to the tracker. @complexity O(p) monitored processes.
 */
function reportMemoryMetrics({ tracker, processes, uptimeSeconds }: { tracker: Tracker; processes: readonly ProcessMemoryReading[]; uptimeSeconds: number }, _options = {}): void {
  for (const group of aggregateProcessMemory({ processes })) {
    const attributes = { process: group.kind };
    tracker.metric({ name: 'process.memory.rss', value: group.rssMb * 1_000_000 }, { kind: 'gauge', unit: 'By', attributes });
    tracker.metric({ name: 'process.count', value: group.count }, { kind: 'gauge', unit: '{process}', attributes });
    if (group.heapUsedMb !== undefined) tracker.metric({ name: 'process.memory.heap_used', value: group.heapUsedMb * 1_000_000 }, { kind: 'gauge', unit: 'By', attributes });
  }
  tracker.metric({ name: 'process.uptime', value: Math.round(uptimeSeconds) }, { kind: 'gauge', unit: 's', attributes: { process: 'main' } });
}

/** Reuses the exact monitor instance read by Resources IPC. Hidden windows still get a five-minute
 * observation; no sampler/timer exists per window or site. In-flight ticks coalesce and disposal
 * blocks late sends. Consent is checked again after the asynchronous monitor read.
 * @param required Existing monitor, tracker, consent and Electron process-metadata ports.
 * @param options Cadence, clock and scheduling ports; defaults are five minutes and native timers.
 * @returns tick for deterministic tests and dispose for the desktop drain.
 * @complexity O(p*w) bounded by the existing monitor and Jini detector; at most 64 points/process.
 */
export function startProductMemoryTelemetry({ monitor, tracker, readConsent, desktopPid, rendererPids, heapUsedBytes, uptime }: {
  monitor: { get(input: { panelOpen: boolean }): Promise<ResourcesSnapshot> }; tracker: Tracker;
  readConsent: () => ProductConsent; desktopPid: number; rendererPids: () => ReadonlySet<number>;
  heapUsedBytes: () => number; uptime: () => number;
}, { intervalMs = 5 * 60_000, now = Date.now, schedule = (tick, ms) => {
  const timer = setInterval(tick, ms); timer.unref(); return () => clearInterval(timer);
} }: { intervalMs?: number; now?: () => number; schedule?: (tick: () => void, ms: number) => () => void } = {}): ProductMemoryTelemetry {
  const cadenceMs = Math.max(60_000, intervalMs);
  const growth = createMemoryGrowthDetector({ now }, { maxSamples: Math.min(64, Math.ceil(60 * 60_000 / cadenceMs) + 2), maxGapMs: cadenceMs * 2 });
  let disposed = false;
  let pending: Promise<void> | undefined;
  async function sample(): Promise<void> {
    const before = readConsent();
    if (!before.crashes && !before.usage) { growth.reset({}, { keepRateLimits: true }); return; }
    const snapshot = await monitor.get({ panelOpen: false });
    if (disposed || snapshot.status !== 'available') return;
    const processes = projectMemoryProcesses({ snapshot, desktopPid, rendererPids: rendererPids(), heapUsedBytes: heapUsedBytes() });
    const consent = readConsent();
    if (consent.usage) reportMemoryMetrics({ tracker, processes, uptimeSeconds: uptime() });
    if (disposed) return;
    if (!readConsent().crashes) { growth.reset({}, { keepRateLimits: true }); return; }
    for (const warning of growth.observe({ processes })) {
      tracker.error({ error: new Error('process memory growth') }, { context: { operation: 'desktop.memory_growth', level: 'warning', attributes: { process: warning.kind, code: warning.reason } } });
    }
  }
  function tick(): Promise<void> {
    if (disposed) return Promise.resolve();
    // Measurement failures are advisory; no rejected background task may become a product error.
    pending ??= sample().catch(() => {}).finally(() => { pending = undefined; });
    return pending;
  }
  const cancel = schedule(() => { void tick(); }, cadenceMs);
  return { tick, dispose() { if (disposed) return; disposed = true; cancel(); growth.reset(); } };
}

