/**
 * Why this site's server is not running, when it stopped on its own — `null` when it was never
 * started, was stopped deliberately, or when `openSites` is a store that cannot say (a plain `Map`
 * in a test that is not exercising liveness).
 *
 * Operator-facing prose, not a raw exit record: this string is rendered on the card. `code` and
 * `signal` are mutually exclusive in Node's `exit` event — whichever is non-null is the reason.
 *
 * @complexity O(1).
 */
function describeLastExit(openSites: OpenSites, siteDir: string): string | null {
  const exit = typeof openSites.lastExitOf === "function" ? openSites.lastExitOf(siteDir) : null;
  if (exit === null) return null;
  if (exit.signal !== null && exit.signal !== undefined) return `The site's server was stopped by ${exit.signal}.`;
  return `The site's server exited (code ${exit.code}).`;
}

/**
 * What to report as a site's `status` and `desiredState`, from the two facts that decide them: is
 * its `tovu serve` alive right now, and is a start or a stop in flight on it.
 *
 * Its own function because those two facts do not compose by precedence alone — a `stopping` site
 * IS still alive, and a `starting` one is NOT yet, so the transition has to win over `running` in
 * one direction and over `stopped` in the other. Inlined in {@link buildSiteRecord} that reads as
 * three nested ternaries whose ordering is load-bearing and invisible.
 *
 * `desiredState` follows the transition's INTENT rather than its current liveness: an operator
 * mid-stop wants this site down, which is the honest thing for a card to say while the drain runs.
 *
 * @complexity O(1).
 */
function siteLifecycle(running: boolean, transition: "starting" | "stopping" | null) {
  if (transition === "starting") return { status: "starting" as const, desiredState: "running" as const };
  if (transition === "stopping") return { status: "stopping" as const, desiredState: "stopped" as const };
  if (running) return { status: "running" as const, desiredState: "running" as const };
  return { status: "stopped" as const, desiredState: "stopped" as const };
}

/**
 * One tracked row plus `openSites` (ground truth for "running") joined into the `SiteRecord`
 * shape `contracts/project.ts` declares. Every field this shell cannot really know — `templateId`,
 * `templateVersion`, `database` — gets a stated, honest default rather than a fabricated value:
 * every project a JSON-file-tracked site can describe today was created outside a provisioner this
 * shell drives, so there is no template or vendor-database fact to report.
 *
 * @complexity O(1).
 */
type SiteRecordDeps = Pick<ProjectIpcDeps, "openSites" | "readSiteName" | "repoRoot" | "readPreviewVersion" | "transitions" | "sharedSites"> & Partial<Pick<ProjectIpcDeps, "classifySiteDir" | "externalSites">>;
type SharedRunning = ReturnType<ReturnType<SitesWorkspace["running"]>["read"]> | undefined;

/** The admin URL of a server this window does not own: an external one it attached to, or the other app's. */
function siteExternalUrl(openEntry: OpenSiteEntry | undefined, sharedRunning: SharedRunning, status: string): string | undefined {
  // The lease stays live during drain. Advertising it here makes a mounted tab queue Start
  // behind this Stop through its external-workspace attachment effect.
  if (status === "stopping") return undefined;
  if (openEntry) return openEntry.server.external ? `${openEntry.server.origin}/admin/` : undefined;
  return sharedRunning && sharedRunning.port > 0 ? `${sharedRunning.scheme}://localhost:${sharedRunning.port}/admin/` : undefined;
}

/** Which app runs the site, or the last exit of a settled stop; see the `statusDetail` field below. */
function siteStatusDetail(sharedRunning: SharedRunning, status: string, openSites: OpenSites, siteDir: string): string | null {
  if (sharedRunning) return `Running in ${sharedRunning.app} (${sharedRunning.port > 0 ? `port ${sharedRunning.port}` : "starting"})`;
  return status === "stopped" ? describeLastExit(openSites, siteDir) : null;
}

/**
 * Only for a site this window can stop although another process serves it; absent, the card
 * offers no Stop for it at all. See `external-site-stop.ts`.
 */
function siteExternalLauncher(externalUrl: string | undefined, sharedRunning: SharedRunning, externalSites: SiteRecordDeps["externalSites"]) {
  return externalUrl && sharedRunning ? externalSites?.launcherOf({ lease: sharedRunning }) ?? undefined : undefined;
}

/** The card name: an alias, the config's name, or (config gone) the last known name. */
function siteDisplayName(row: SiteRow, validSite: boolean, readSiteName: (siteDir: string) => string): string {
  return row.displayNameAlias ?? (validSite ? readSiteName(row.siteDir) : row.displayName ?? path.basename(row.siteDir));
}

/** Join local liveness and shared-lease startup with the explicit transition's intent. O(1). */
export function siteRecordLifecycle(
  { siteDir, openEntry, sharedRunning, transitions }: { siteDir: string; openEntry: OpenSiteEntry | undefined; sharedRunning: SharedRunning; transitions: SiteRecordDeps["transitions"] }, _options = {},
): { sharedPort: number; lifecycle: ReturnType<typeof siteLifecycle> } {
  const sharedPort = sharedRunning?.port ?? 0;
  const running = openEntry !== undefined || sharedPort > 0;
  // `openSites` answers "is it alive", which is a two-valued answer to a four-valued question:
  // both transitions take real wall-clock time, and during either one the two-valued answer is
  // wrong in the direction the operator can SEE — a Start they just pressed reads `stopped` for the
  // whole boot, a Stop reads `running` until the child is gone, and both look like a dead button.
  // `site-transitions.ts` is what makes the other two answers producible; absent (every test that
  // is not exercising them) it reads `null` and nothing here changes.
  const sharedStarting = sharedRunning && !sharedPort ? "starting" : null;
  const lifecycle = siteLifecycle(running, transitions?.get(siteDir) ?? sharedStarting);
  return { sharedPort, lifecycle };
}

function buildSiteRecord(row: SiteRow, deps: SiteRecordDeps) {
  const validSite = (deps.classifySiteDir ?? classifySiteDirSafely)(row.siteDir) === "site";
  const openEntry = deps.openSites.get(row.siteDir);
  const sharedRunning: SharedRunning = deps.sharedSites?.running({ path: row.siteDir }).read({});
  const { sharedPort, lifecycle } = siteRecordLifecycle({ siteDir: row.siteDir, openEntry, sharedRunning, transitions: deps.transitions });
  const externalUrl = siteExternalUrl(openEntry, sharedRunning, lifecycle.status);
  return {
    id: row.siteDir,
    slug: path.basename(row.siteDir),
    // The config may be gone even when a themes-only folder remains; keep the last known name.
    displayName: siteDisplayName(row, validSite, deps.readSiteName),
    installDir: row.siteDir,
    port: openEntry?.server.port ?? sharedPort,
    runningApp: sharedRunning?.app,
    externalUrl,
    externalLauncher: siteExternalLauncher(externalUrl, sharedRunning, deps.externalSites),
    // Independent of `running` — a project's partition is a pure function of its own directory
    // (`desktop-auth.ts`'s `sitePartition`), not of whether a server currently answers on it. The
    // embedded-tab renderer needs it either way: `SiteWorkspace`'s `<webview>` sets it up front,
    // before the tab knows whether the site is up yet.
    partition: sitePartition(row.siteDir),
    templateId: "tovu",
    templateVersion: null,
    database: { kind: "sqlite" as const },
    desiredState: lifecycle.desiredState,
    status: lifecycle.status,
    // Not always `null` any more: a site that DIED is `stopped` exactly like one that was never
    // started, and before `site-supervisor.ts` owned that transition the two were indistinguishable
    // to the renderer (D-06). This is the one place the difference can be told.
    //
    // Only for a settled `stopped`. Mid-transition the prior crash is not what the operator is
    // looking at — a card that says "Starting" and "the server exited (code 1)" in the same breath
    // is reporting two different moments as one.
    statusDetail: siteStatusDetail(sharedRunning, lifecycle.status, deps.openSites, row.siteDir),
    createdAt: row.createdAt,
    updatedAt: row.createdAt,
    // Computed by the SAME function `handleDelete` obeys, never re-derived from `origin` in the
    // renderer — a UI that decided this for itself could drift from the rule main actually enforces
    // and label a button with a consequence that will not happen. See `project-delete-guard.ts`.
    deleteErasesFiles: mayEraseSiteDirectory(row as unknown as MayEraseRowLike, { repoRoot: deps.repoRoot }),
    // A version token, never the image — see `SiteRecord.previewVersion`'s own doc on why this
    // record (polled every 4s) must never carry a payload. `null` for a site with no capture yet,
    // which is every site's ordinary state until it has been opened once.
    previewVersion: deps.readPreviewVersion(row.siteDir),
    // Asked of the disk on every poll, never stored: a folder renamed or deleted behind the app's
    // back is exactly the case a stored flag would get wrong. Admission also rejects a leftover
    // themes-only/corrupt directory — the same Locate / Remove recovery applies to it.
    folderMissing: !validSite,
  };
}

/** Import catalog discovery without transferring local origin or deletion authority. O(n) rows. */
export function importSharedSiteDiscovery(
  { projectsPath, sharedSites, readSiteName }: Pick<ProjectIpcDeps, "projectsPath" | "sharedSites" | "readSiteName">, _options = {},
): void {
  if (!sharedSites) return;
  try {
    // The shared catalog supplies discovery, never the local origin/deletion authority.
    const rows = readTrackedSites(projectsPath);
    if (rows.length) shareSiteDirectories({ workspace: sharedSites, dirs: rows.map((row) => row.siteDir), createdBy: "desktop-legacy", migration: `projects:${projectsPath}` });
    adoptWithUniqueNames({ deps: { projectsPath, readSiteName }, siteDirs: sharedSites.registry({}).list({}).map((entry) => entry.path) });
  } catch { console.warn("tovu desktop: shared discovery is unavailable; showing local website cards."); }
}

/**
 * Every tracked project's record, after healing any whose folder was renamed or moved
 * (`site-relocation.ts`). The heal is best-effort: a list that cannot be SAVED still has to render,
 * so a failed write is logged and the rows are shown as they stand.
 *
 * With `relocationGate` (production: {@link registerSiteIpcHandlers}), the heal runs only when the
 * gate says something could have moved, so a 4 s poll over a missing folder does not rescan its
 * siblings every time. Without one, it runs on every call.
 *
 * @complexity O(n) in the tracked-project count, plus `relocateMovedSites`' scan for a missing row.
 */
function handleList(
  deps: Pick<ProjectIpcDeps, "projectsPath" | "openSites" | "readSiteName" | "repoRoot" | "readPreviewVersion" | "transitions" | "sharedSites"> &
    Partial<Pick<ProjectIpcDeps, "siteScanRoots" | "siteFolders" | "classifySiteDir" | "externalSites">> & { relocationGate?: RelocationGate },
) {
  importSharedSiteDiscovery({ projectsPath: deps.projectsPath, sharedSites: deps.sharedSites, readSiteName: deps.readSiteName });
  const file = readProjectsFile(deps.projectsPath);
  if (deps.relocationGate && !deps.relocationGate.shouldRun(file)) return recordsWithRememberedNames({ rows: file.rows, deps });
  try {
    relocateMovedSites({ projectsPath: deps.projectsPath }, { searchRoots: deps.siteFolders?.read({}).roots ?? deps.siteScanRoots ?? [], classifySiteDir: deps.classifySiteDir });
  } catch (error) {
    console.warn(`tovu desktop: could not save moved site folders — ${(error as Error).message}`);
  }
  const rows = readTrackedSites(deps.projectsPath);
  if (deps.sharedSites) shareSiteDirectories({ workspace: deps.sharedSites, dirs: rows.map((row) => row.siteDir), createdBy: "desktop-legacy" });
  return recordsWithRememberedNames({ rows, deps });
}

/**
 * Ask main for a preview of every listed site that is running and has none yet. A site another app
 * runs (`npm run dev`, a sibling desktop) is never opened by this window, so without this its card
 * kept showing a bare port forever — owner 2026-10-13. Main dedupes and debounces; see
 * `requestPreviewCapture`. Returns `records` unchanged so the list handler stays one expression.
 *
 * @complexity O(n) in listed sites.
 */
function requestMissingPreviews<T extends { id: string; status: string; port: number; previewVersion: number | null }>(
  records: T[], deps: Pick<ProjectIpcDeps, "requestPreviewCapture">,
): T[] {
  for (const record of records) {
    if (record.status === "running" && record.port > 0 && record.previewVersion === null) {
      deps.requestPreviewCapture?.({ siteDir: record.id, port: record.port }, {});
    }
  }
  return records;
}

/** Store only the name, never lifecycle status or deletion authority. */
function rememberSiteName(
  { projectsPath, siteDir, displayName }: { projectsPath: string; siteDir: string; displayName: string }, _optional = {},
): void {
  try {
    updateProjectsFile(projectsPath, (current) => ({
      rows: current.rows.map((row) => row.siteDir === siteDir ? { ...row, displayName } : row),
      dismissed: current.dismissed,
    }));
  } catch (error) {
    // A metadata cache failure must not report a completed Create/Add/Rename as a failed action.
    console.warn('tovu desktop: could not remember website name', error);
  }
}
function recordsWithRememberedNames(
  { rows, deps }: { rows: SiteRow[]; deps: Pick<ProjectIpcDeps, "projectsPath" | "openSites" | "readSiteName" | "repoRoot" | "readPreviewVersion" | "transitions" | "sharedSites"> }, _optional = {},
) {
  const records = rows.map((row) => buildSiteRecord(row, deps));
  const names = new Map(records.filter((record) => !record.folderMissing).map((record) => [record.id, record.displayName]));
  if (rows.some((row) => names.has(row.siteDir) && names.get(row.siteDir) !== row.displayName)) {
    try {
      updateProjectsFile(deps.projectsPath, (current) => ({
        rows: current.rows.map((row) => names.has(row.siteDir) ? { ...row, displayName: names.get(row.siteDir)! } : row),
        dismissed: current.dismissed,
      }));
    } catch (error) { console.warn('tovu desktop: could not remember website names', error); }
  }
  return records;
}

/**
 * A missing card's Locate: the operator picks where the site's folder is now, and the card is
 * pointed there — keeping its place in the grid, and merging into the existing card when that
 * folder is already tracked. Main owns the dialog, as with `handleAddSite`, so the renderer never
 * names a path.
 *
 * @returns the record at its new folder.
 * @throws {Error} operator-facing, when the dialog is cancelled, the picked folder is not a complete
 *   Tovu site, or `id` is not tracked.
 * @complexity O(n) in the tracked-project count, plus one classification.
 */
async function handleLocate(id: string, deps: Pick<ProjectIpcDeps, "dialog" | "classifySiteDir" | "projectsPath" | "openSites" | "readSiteName" | "repoRoot" | "readPreviewVersion" | "transitions" | "sharedSites">) {
  const picked = await deps.dialog.showOpenDialog({
    title: "Locate your Tovu website's folder",
    message: `Pick the folder that now holds the website that was at ${id}. Nothing in it will be changed.`,
    buttonLabel: "Use this folder",
    properties: ["openDirectory"],
  });
  if (picked.canceled || picked.filePaths.length === 0) {
    throw new Error("No folder was chosen.");
  }
  const siteDir = picked.filePaths[0]!; // just checked `filePaths.length === 0` above, so index 0 exists
  const kind = deps.classifySiteDir(siteDir);
  if (kind !== "site") {
    throw new Error(`${siteDir} is not a complete Tovu site (${kind}). Pick the folder that holds this website.`);
  }
  const row = repointTrackedSite(deps.projectsPath, id, siteDir).find((entry) => entry.siteDir === siteDir)!; // repointed onto, or merged into, this exact siteDir above
  if (deps.sharedSites) shareSiteDirectories({ workspace: deps.sharedSites, dirs: [siteDir], createdBy: "Desktop", allowRelocation: true });
  return buildSiteRecord(row, deps);
}

/** Live names include registry aliases and cached names for missing folders. Excluding the target
 * keeps re-adding a tracked folder and renaming a site to its own name idempotent. */
function otherSiteNames({ deps, siteDir }: {
  deps: Pick<ProjectIpcDeps, "projectsPath" | "readSiteName">; siteDir: string;
}, _optional = {}): string[] {
  return readTrackedSites(deps.projectsPath).filter((row) => row.siteDir !== siteDir).map((row) =>
    row.displayNameAlias ?? (!fs.existsSync(row.siteDir) && row.displayName ? row.displayName : deps.readSiteName(row.siteDir)));
}

/** Adding a website must not rewrite its config. Persist a shell alias only when disambiguating. */
function rememberSiteAlias({ projectsPath, siteDir, displayNameAlias }: {
  projectsPath: string; siteDir: string; displayNameAlias?: string;
}, _optional = {}): void {
  updateProjectsFile(projectsPath, (current) => ({
    rows: current.rows.map((row) => row.siteDir === siteDir ? { ...row, displayNameAlias } : row),
    dismissed: current.dismissed,
  }));
}

/**
 * Track discovered sites the way Add existing tracks a picked one: each NEWLY adopted card whose
 * name collides gets a shell alias ("Name 2"), never a config rewrite. Rows already tracked keep
 * their names — only this call's adoptions are named, one at a time so they also differ from each
 * other. O(a·n) for a adoptions over n tracked rows.
 */
function adoptWithUniqueNames({ deps, siteDirs }: {
  deps: Pick<ProjectIpcDeps, "projectsPath" | "readSiteName">; siteDirs: string[];
}, _optional = {}): void {
  for (const siteDir of adoptDiscoveredSites(deps.projectsPath, siteDirs)) {
    const originalName = deps.readSiteName(siteDir);
    const displayName = uniqueSiteName({ name: originalName, names: otherSiteNames({ deps, siteDir }) });
    if (displayName !== originalName) rememberSiteAlias({ projectsPath: deps.projectsPath, siteDir, displayNameAlias: displayName });
  }
}

/** Plan a new Tovu site without creating folders or reserving the destination.
 * The workspace owns home resolution and volume admission for both Create and its preview.
 * @throws {Error} if the name is not a string or the home volume is unavailable.
 * @complexity O(n + k) for n name characters and k conflicting folders; O(n) space.
 */
export function planNewSiteDir({ name }: { name: string }, {
  workspace = createSitesWorkspace({}),
}: { workspace?: Pick<SitesWorkspace, "home" | "homeAvailable"> } = {}): string {
  if (typeof name !== "string") throw new Error("Website name must be a string.");
  const home = workspace.home({});
  if (!workspace.homeAvailable({})) throw new Error(`Sites home volume is unavailable: ${home}. Mount it or choose a local folder in Sites settings.`);
  const folder = name.trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "website";
  let target = path.join(home, folder), suffix = 2;
  while (fs.existsSync(target)) target = path.join(home, `${folder}-${suffix++}`);
  return target;
}

/**
 * "+ Create website" has no folder in its input — `CreateSiteInput` is a display name plus a
 * database choice, ported from Tovu-Runner's own provisioner-backed form. This shell has no such
 * provisioner, so each new project gets a free directory under the configured sites home;
 * `input.displayName` becomes `tovu init`'s `--name`.
 *
 * **The database choice is REFUSED rather than ignored (D-02).** Knowing the field was dead and
 * narrowing it silently was the defect: `buildSiteRecord` hard-codes `{kind: "sqlite"}`, so an
 * operator who chose Supabase — and whom `computeCanCreate` then FORCED to type a project URL and
 * an API key before the button would enable — got a local SQLite site reported back as a success,
 * with their credential discarded. A contract this process does not honour must fail loudly at its
 * boundary; the renderer's own fix (disabling the options it cannot deliver) is the first line,
 * and this is the one that holds whoever calls the channel next.
 *
 * Refused BEFORE planning the destination, deliberately: nobody should prepare a site that was
 * never going to be made. An absent `database` is the same as `sqlite` — every existing caller
 * omits it, and omitting it is not a claim about a provider.
 *
 * @returns the new site record.
 * @throws {Error} for invalid input, an unavailable sites home, or a creation race.
 * @complexity O(k) destination probes for k conflicting folders, plus initialization.
 */
async function handleCreate(
  input: CreateSiteInput,
  deps: Pick<ProjectIpcDeps, "classifySiteDir" | "adoptSiteDir" | "repoRoot" | "statePath" | "cliMode" | "projectsPath" | "openSites" | "readSiteName" | "readPreviewVersion" | "transitions" | "siteFolders" | "sharedSites">
) {
  const agentPluginTokens = validateCreateInput({ input });

  const target = planNewSiteDir({ name: input.displayName }, { workspace: deps.sharedSites });
  fs.mkdirSync(path.dirname(target), { recursive: true });
  // BEFORE `adoptSiteDir`, because afterwards the answer is gone: it returns the same path whether
  // it ran `tovu init` into an empty folder or simply recognized a site that was already there. Only
  // the first of those is a directory this app made, and only that one may ever be erased again —
  // see `project-delete-guard.ts`. Create must refuse a folder another app took before either
  // classification, rather than recording its existing site as one this app made.
  const wasEmpty = deps.classifySiteDir(target) === "empty";
  assertTokensCanReachFolder(agentPluginTokens, wasEmpty);
  if (!wasEmpty && input.adminPassword !== undefined) throw new Error("An admin password can only be set while creating a new site. Change an existing site's password under Users.");
  if (!wasEmpty) throw new Error("The new website folder was created by another app. Try creating this website again.");
  const names = otherSiteNames({ deps, siteDir: target });
  const displayName = uniqueSiteName({ name: input.displayName, names });
  const init = { output: "" };
  const adopt = async () => {
    if (deps.classifySiteDir(target) !== "empty") throw new Error("The new website folder was created by another app. Try creating this website again.");
    return deps.adoptSiteDir({
    dir: target,
    repoRoot: deps.repoRoot,
    statePath: deps.statePath,
    name: displayName,
    adminPassword: input.adminPassword,
    cliMode: deps.cliMode,
    ...initTokenOptions(agentPluginTokens, init),
    });
  };
  const siteDir = await withDirectoryFileLock({ lockPath: `${target}.creation.lock`, run: adopt }, { staleMs: Infinity });
  // Read AFTER `adoptSiteDir`, because before it there is no site there to have an identity: this is
  // the id `tovu init` just stamped into `.site-meta.json`. Recording it here is the only moment
  // this app can honestly say "the site at this path is one I made" — every later reader is looking
  // at a path, and a path is not an identity. See `project-delete-guard.ts`'s test 3.
  // `null` when the folder has no readable identity: the row is then recorded without one, the fail-closed direction.
  const siteId = readSiteIdentity(siteDir);
  trackSite(deps.projectsPath, siteDir, SITE_ORIGIN.created, { siteId });
  if (deps.sharedSites) shareSiteDirectories({ workspace: deps.sharedSites, dirs: [siteDir], createdBy: "Desktop" });
  // Remember the created site's parent beyond MRU eviction/card
  // removal, so a site created beside it by the CLI or web admin can appear on the next scan.
  try { deps.siteFolders?.rememberCreated({ siteDir }); }
  catch { console.warn("tovu desktop: could not remember the created website folder; the website was created successfully."); }
  rememberSiteName({ projectsPath: deps.projectsPath, siteDir, displayName });
  const displayNameAlias = displayName !== deps.readSiteName(siteDir) ? displayName : undefined;
  rememberSiteAlias({ projectsPath: deps.projectsPath, siteDir, displayNameAlias });
  const tracked = readTrackedSites(deps.projectsPath).find((row) => row.siteDir === siteDir);
  if (!tracked) throw new Error("The website was created, but its desktop catalog entry is missing. Use Add Tovu Website to add the folder again.");
  return withCreatedTokens(buildSiteRecord({ ...tracked, displayNameAlias }, deps), init.output);
}

/** Validate creation before planning the destination; return the existing cleaned token contract.
 * @throws {Error} for unsupported providers, names, tokens or passwords.
 * @complexity O(n) in token count, delegated to cleanCreateTokens.
 */
function validateCreateInput({ input }: { input: CreateSiteInput }, _options = {}) {
  const nameError = siteNameError({ name: input.displayName });
  if (nameError) throw new Error(nameError);
  const kind = input.database?.kind;
  if (kind !== undefined && kind !== "sqlite") {
    throw new Error(`This app only creates SQLite sites, which live in the folder you choose. "${kind}" needs a hosted-database provisioner this app does not have.`);
  }
  // Checked before the dialog for the same reason as the database choice: a malformed map is refused
  // before anyone picks a folder.
  const agentPluginTokens = cleanCreateTokens(input.agentPluginTokens);
  if (input.adminPassword !== undefined && (typeof input.adminPassword !== "string" || input.adminPassword.length === 0)) {
    throw new Error("Admin password must be a nonempty string.");
  }
  return agentPluginTokens;
}

/**
 * The services "+ Create website" can offer a token field for (`agent-plugin-tokens.ts`). A failure
 * is an empty list, never an error: the form then offers no services and creates the site as before.
 *
 * @complexity One CLI spawn.
 */
async function handleTokenSignInPlugins(deps: Pick<ProjectIpcDeps, "repoRoot" | "cliMode" | "listTokenSignInPlugins">): Promise<TokenSignInPlugin[]> {
  try {
    return await (deps.listTokenSignInPlugins ?? listTokenSignInPluginsReal)({ repoRoot: deps.repoRoot, cliMode: deps.cliMode });
  } catch (error) {
    console.warn(`[desktop] could not list the services a new site can connect: ${error instanceof Error ? error.message : String(error)}`);
    return [];
  }
}

/**
 * "Add Tovu Website" — track a folder that ALREADY holds a Tovu site.
 *
 * The sibling of {@link handleCreate}, and the difference is the entire point: `create` takes an
 * EMPTY folder and runs `tovu init` into it, while this one takes a folder that is already a site
 * and writes nothing but a registry row. `adoptSiteDir` cannot be reused here for exactly that
 * reason — it is `resolveOrInitSiteDir({onMissingSite: "init"})`, so handing it an empty folder
 * creates a site there, which for this verb is the operator's mistake being silently acted on
 * rather than reported.
 *
 * It also closes the old confusion where "Create website" adopted a picked existing site.
 * Create now chooses a free directory under sites home; Add owns the existing-folder choice.
 *
 * Main owns the existing-folder dialog, so the renderer never names a path.
 *
 * The row is recorded `adopted` by `addSitePointer` itself, never `created`, so
 * `project-delete-guard.ts` can never let a later delete erase a folder this app did not make.
 *
 * @returns null when the folder picker is cancelled.
 * @throws {AddSitePointerError} when the folder is not a
 *   complete Tovu site — either way an operator-facing message that names the fix.
 * @complexity O(n) in the tracked-project count, plus one classification.
 */
async function handleAddSite(deps: Pick<ProjectIpcDeps, "dialog" | "addSitePointer" | "projectsPath" | "openSites" | "readSiteName" | "repoRoot" | "readPreviewVersion" | "transitions" | "sharedSites">) {
  const picked = await deps.dialog.showOpenDialog({
    title: "Choose your Tovu website's folder",
    message: "Pick a folder that already contains a Tovu website. Nothing in it will be changed.",
    buttonLabel: "Add website",
    // No `createDirectory`: a folder the operator makes in this dialog is
    // empty by definition, and an empty folder is precisely what this verb refuses. Offering the
    // button would invite the one mistake the refusal then has to explain.
    properties: ["openDirectory"],
  });
  if (picked.canceled || picked.filePaths.length === 0) {
    // Cancelling is a completed choice, not an IPC failure to log or display.
    return null;
  }

  const { siteDir, alreadyTracked } = deps.addSitePointer({ siteDir: picked.filePaths[0]!, projectsPath: deps.projectsPath });
  if (deps.sharedSites) shareSiteDirectories({ workspace: deps.sharedSites, dirs: [siteDir], createdBy: "Desktop" }); // just checked `filePaths.length === 0` above, so index 0 exists
  const row = readTrackedSites(deps.projectsPath).find((entry) => entry.siteDir === siteDir)!; // addSitePointer just tracked this exact siteDir above, so a row for it always exists
  // Read back rather than synthesized: an already-tracked folder keeps its ORIGINAL `createdAt` and
  // origin, and a fabricated row would report today's date and reorder the operator's grid.
  if (!alreadyTracked) {
    const originalName = deps.readSiteName(siteDir);
    const displayName = uniqueSiteName({ name: originalName, names: otherSiteNames({ deps, siteDir }) });
    row.displayNameAlias = displayName !== originalName ? displayName : undefined;
    rememberSiteAlias({ projectsPath: deps.projectsPath, siteDir, displayNameAlias: row.displayNameAlias });
  }
  const record = buildSiteRecord(row, deps);
  rememberSiteName({ projectsPath: deps.projectsPath, siteDir, displayName: record.displayName });
  return { ...record, alreadyTracked };
}

/**
 * The exact operator-facing refusal when a SECOND copy of this app still has this site open.
 * Exported so tests assert on the real string rather than a paraphrase of it.
 *
 * @complexity O(n) in foreign row count.
 */
function foreignServerMessage(siteDir: string, foreign: Array<{ pid: number }>): string {
  const pids = foreign.map((row) => row.pid).join(", ");
  return (
    `Another copy of Tovu still has this site open (process ${pids}). Close that window first. ` +
    `Deleting now would erase ${siteDir} out from under a server that is still writing to its database.`
  );
}

/**
 * The exact operator-facing refusal when a crash-safety registry file cannot be read, so whether a
 * second copy of this app has the site open is unknown.
 *
 * @complexity O(n) in unreadable path count.
 */
function unreadableRegistryMessage(unreadable: string[]): string {
  return `Could not read ${unreadable.join(", ")}, so Tovu cannot tell whether another copy of Tovu still has this site open. Nothing was deleted. Restart Tovu and try again.`;
}

/**
 * Crash-safety rows naming a LIVE `tovu serve` for `siteDir` that belongs to some process OTHER
 * than the one this instance is holding — i.e. a second copy of this app with the same site open.
 *
 * `openSites` cannot answer this: it is this process's own in-memory map, so a sibling instance's
 * child is invisible to it. The on-disk registry is the only thing that sees both, and it is
 * already written to see them — each instance records only into its own file there, so a sibling's
 * row survives this instance opening the same site.
 *
 * `isLiveServeRow` is the registry's own identity proof (pid alive AND its live argv still names
 * this site dir and port), so a pid the OS recycled to something unrelated can never make this
 * refuse. Stale rows therefore cannot wedge a delete.
 *
 * An UNREADABLE registry file throws instead: its rows are unknown, and reading it as "no rows" is
 * exactly how this guard used to wave an erase through a torn sibling file. It does not wedge for
 * long — the next boot moves a dead instance's unreadable file aside, and a live one's own next
 * write does the same (`site-process-registry.ts`'s `quarantineUnreadableFile`).
 *
 * @param ownPid this instance's own child's pid, excluded — its row is not foreign.
 * @complexity O(n) in registry rows, times one `ps` call per row matching `siteDir` (in practice
 *   zero or one).
 */
function liveForeignServers(deps: Pick<ProjectIpcDeps, "readRegistry" | "registryPath" | "isLiveServeRow">, siteDir: string, ownPid: number | undefined): RegistryRow[] {
  const registry = deps.readRegistry(deps.registryPath);
  if (registry.unreadable.length > 0) throw new Error(unreadableRegistryMessage(registry.unreadable));
  return registry.sites.filter((row) => row.siteDir === siteDir && row.pid !== ownPid && deps.isLiveServeRow(row));
}

/**
 * Stops the project if it is running, erases its directory ONLY when this app created it,
 * then untracks it. Failed removal retains the row as the operator's recovery handle.
 *
 * That last word is load-bearing and is the whole reason this function consults
 * `project-delete-guard.ts` rather than calling `fs.rm` on whatever id arrives. A tracked row can
 * point at a folder the app merely adopted (`seedDevFallbackSite` seeds exactly one such row,
 * `<repo>/sites/tovu-dev`, someone's real 44 MB site), and for those the delete means "take this
 * card off my Projects screen" — the row goes, every byte stays. The renderer says which of the two
 * a given card will do, from the same guard's answer carried on `SiteRecord.deleteErasesFiles`,
 * so the confirm overlay never promises a consequence this function will not deliver.
 *
 * Idempotent on an id that is not tracked (already gone) rather than throwing — the
 * operator's confirm dialog already happened in the renderer, so a second delete of the same
 * project (a slow poll racing a fast double-click) should not surface a scary error for something
 * that already succeeded.
 *
 * The server is stopped and the in-memory `openSites`/on-disk crash-safety row are cleared BEFORE
 * the directory is removed, so `content.db` is never unlinked out from under a live handle. The
 * window's own `closed` listener (`main.ts`) still fires afterward and repeats the same two
 * cleanup calls — both are idempotent (`stopChild` checks `exitCode`/`signalCode` first;
 * `openSites.delete` and `recordSiteClosed` are no-ops on an absent entry), so the double call is
 * harmless rather than a race.
 *
 * **Runs through the SAME `serializer` key `handleStart` uses, and that is what makes the paragraph
 * above true** (D-05/SEC-02). It used to be false for one interleaving: `openSiteServer` publishes
 * into `openSites` only AFTER `startSiteBackend` resolves, and that can take the full
 * `DEFAULT_READY_TIMEOUT_MS` (180s) while `tovu serve` boots. Start a site, go back to All, delete
 * it, and the delete saw no entry, skipped the stop, and recursively erased the directory the child
 * was booting in — then the start completed and published a running entry for a project that no
 * longer existed. Serializing the two verbs against each other is the whole fix: the delete now
 * queues behind the in-flight start and finds the entry it must stop.
 *
 * @complexity O(1) beyond `fs.rm`'s own cost over the site directory's contents, plus however long
 *   an already-queued operation on the same site takes to settle.
 */
async function handleDelete(id: string, deps: Pick<ProjectIpcDeps, "serializer" | "projectsPath" | "openSites" | "cancelPreviewCapture" | "repoRoot" | "readRegistry" | "registryPath" | "isLiveServeRow" | "recordSiteClosed" | "deletePreview" | "removeSiteTree" | "sharedSites">): Promise<void> {
  await deps.serializer.run(id, () => deleteProject(id, deps));
}

/**
 * {@link handleDelete}'s body, separated only so the serialized region is one named thing rather
 * than an inline closure — everything here assumes it holds this site's serializer key.
 *
 * @complexity see {@link handleDelete}.
 */
async function deleteProject(id: string, deps: Pick<ProjectIpcDeps, "projectsPath" | "openSites" | "cancelPreviewCapture" | "repoRoot" | "readRegistry" | "registryPath" | "isLiveServeRow" | "recordSiteClosed" | "deletePreview" | "removeSiteTree" | "sharedSites">): Promise<void> {
  const row = readTrackedSites(deps.projectsPath).find((entry) => entry.siteDir === id);
  if (row === undefined) return;

  const openEntry = deps.openSites.get(id);
  const erasesFiles = mayEraseSiteDirectory(row as unknown as MayEraseRowLike, { repoRoot: deps.repoRoot });

  // BEFORE any side effect, and only for the arm that erases (D-08). The serializer above makes the
  // stop-then-erase sequence safe against THIS process; nothing made it safe against a second copy
  // of the app, and nothing prevents one — `main.ts` calls no `requestSingleInstanceLock`, and
  // `site-process-registry.ts` is written throughout on the premise that two instances can run at once.
  // Instance A deleting a site instance B has open recursively erased the directory out from under
  // B's live `tovu serve`, which went on writing into unlinked files.
  //
  // Refusing the whole operation rather than untracking-without-erasing: `deleteErasesFiles` is what
  // the confirm overlay showed the operator, and this function's own contract is that the overlay
  // never promises a consequence it will not deliver. A quiet downgrade to "card removed, folder
  // kept" would break that in the direction they cannot see.
  //
  // The non-erasing arm is deliberately NOT gated. There it means "take this card off my Projects
  // screen"; a sibling instance keeping its own copy running is not endangered by that.
  if (erasesFiles) assertNoOtherServer({ id, openEntry, deps });

  deps.cancelPreviewCapture?.({ siteDir: id }, {});
  if (openEntry !== undefined) {
    await openEntry.server.stop!(); // an entry with no `.stop` never reaches this line in practice — `OpenSiteEntry.server.stop` is optional only because other, non-delete tests build entries that omit it
    closeStoppedProject({ id, openEntry, deps });
  }
  // The row is the recovery handle for a partial erase: keep it until removal succeeds.
  if (erasesFiles) await eraseProjectDirectory({ id, deps });
  untrackSite(deps.projectsPath, id);
  if (erasesFiles) removeFromSharedCatalog({ id, sharedSites: deps.sharedSites });
  // Unconditional — independent of `erasesFiles` below. A preview is this shell's own decoration,
  // not the operator's data, so a row that is merely REMOVED (adopted, files kept) still drops its
  // cached thumbnail: once the row is gone `buildSiteRecord` can never ask for it again
  // (`site-preview-store.ts`'s own doc on why an orphan is otherwise unreachable, not merely
  // unlikely), so leaving the file behind would only be litter for the boot sweep to find later.
  deps.deletePreview(id);

}

/** {@link deleteProject}'s erase gate (D-08): refuse while another app or instance serves the site.
 * @complexity O(r) registry rows.
 */
function assertNoOtherServer(
  { id, openEntry, deps }: { id: string; openEntry: OpenSiteEntry | undefined; deps: Pick<ProjectIpcDeps, "readRegistry" | "registryPath" | "isLiveServeRow" | "sharedSites"> }, _options = {},
): void {
  const ownPid = openEntry?.server.pid;
  const shared = deps.sharedSites?.running({ path: id }).read({});
  if (shared && (shared.pid !== ownPid || openEntry?.server.external)) throw new Error(`Running in ${shared.app} (port ${shared.port}). Stop it in that app before deleting.`);
  const foreign = liveForeignServers(deps, id, ownPid);
  if (foreign.length > 0) throw new Error(foreignServerMessage(id, foreign));
}

/** Drop an erased site from the shared catalog; a failure only warns, the folder is already gone.
 * @complexity O(1).
 */
function removeFromSharedCatalog({ id, sharedSites }: { id: string; sharedSites: SitesWorkspace | undefined }, _options = {}): void {
  try { sharedSites?.registry({}).remove({ path: id }); }
  catch { console.warn("tovu desktop: could not remove the erased website from the shared catalog."); }
}

/** Remove this process's stopped handle and close its window before folder deletion.
 * @complexity O(1) time and space.
 */
function closeStoppedProject(
  { id, openEntry, deps }: { id: string; openEntry: OpenSiteEntry; deps: Pick<ProjectIpcDeps, "openSites" | "recordSiteClosed" | "registryPath"> }, _options = {},
): void {
  deps.openSites.delete(id);
  // By pid: `recordSiteOpened` can leave a still-draining earlier child's row for this same site dir,
  // and a close by site dir alone would drop that one too (D-07).
  deps.recordSiteClosed(deps.registryPath, id, { pid: openEntry.server.pid });
  // A sites-home-opened (embedded-tab) entry has no `window` at all — see `openSiteServer` in
  // `main.ts` — so this is optional, not a missing null check.
  if (openEntry.window && !openEntry.window.isDestroyed!()) openEntry.window.destroy!(); // present whenever `window` is (see `OpenSiteEntry.window`'s own doc: optional only for tests that never invoke it)
}

/** Erase the folder; translate failures while leaving untracking to the caller.
 * @throws {Error} with the existing retry instruction on a partial erase.
 * @complexity O(n) in filesystem entries, delegated to removeSiteTree.
 */
async function eraseProjectDirectory(
  { id, deps }: { id: string; deps: Pick<ProjectIpcDeps, "removeSiteTree"> }, _options = {},
): Promise<void> {
  // The row is the recovery handle for a partial erase: keep it until removal succeeds.
  try { await (deps.removeSiteTree ?? removeSiteTree)({ root: id }, {}); }
  catch (error) {
    const reason = (error as NodeJS.ErrnoException).code === 'EACCES'
      ? 'Permission was denied.' : 'The folder could not be removed.';
    throw new Error(`Could not delete this website. ${reason} Its card has been kept so you can try again.`);
  }
}

/**
 * Whether this row recorded an identity that the directory no longer has.
 *
 * `false` for a row that recorded none — which is every ADOPTED row, since `buildTrackedRow`
 * (`tracked-sites.ts`) stamps `siteId` only on a `created` one. That is the deliberate fail-OPEN
 * half of {@link handleRename}'s guard, argued in its own doc: a check that cannot run is not the
 * same as a check that failed, and treating it as failure would make rename impossible on every
 * site the operator adopted.
 *
 * Its own function so the three clauses read as one question at the call site, and so the
 * "recorded nothing" and "recorded something that changed" cases are visibly different answers.
 *
 * @complexity O(1) beyond `readSiteIdentity`'s single file read.
 */
function identityHasChanged(row: SiteRow): boolean {
  if (typeof row.siteId !== "string" || row.siteId === "") return false;
  return readSiteIdentity(row.siteDir) !== row.siteId;
}

/**
 * Change a site's display name — `config.json`'s `name`, the one `readSiteName` reads for every
 * card's `displayName`.
 *
 * **WHY THE GUARD IS NOT `isStillTheRecordedSite`.** That predicate (`project-delete-guard.ts`) is
 * the right identity test for DELETE and the wrong one here, and the difference is not a judgement
 * call — it returns `false` immediately unless `row.siteId` is a non-empty string, and
 * `buildTrackedRow` (`tracked-sites.ts`) stamps `siteId` ONLY on a `created` row. Every site the
 * operator adopted — "Add Tovu Website", a rescan, "Open Site…" — has no `siteId` and never will,
 * so gating rename on it would refuse rename on essentially every real site: a feature that fails
 * closed into uselessness.
 *
 * The asymmetry is in what each direction costs, which is exactly how `project-delete-guard.ts`'s
 * own header argues its case. Delete's fail-closed direction costs the operator a leftover folder
 * they can remove in Finder, while its wrong direction costs them their content — so it refuses
 * whatever it cannot positively prove. Rename's fail-closed direction costs the whole feature on
 * every site, while its wrong direction writes a display name into a site whose name that card is
 * ALREADY showing (`readSiteName` reads whatever `config.json` sits at that path). Non-destructive,
 * reversible, and the operator is renaming what they can see.
 *
 * So this checks what is actually checkable, and reuses the delete guard's own primitive
 * (`readSiteIdentity`) rather than inventing a second notion of site identity:
 *
 * 1. The row is tracked. An id this shell does not know is not a site it may write to.
 * 2. The directory still classifies as a complete Tovu site. This is the check that catches the
 *    moved-, emptied-, or deleted-folder cases, and it is the one that matters most often.
 * 3. When the row DOES carry a `siteId`, the directory's own identity must still match it.
 *    Best-effort by necessity rather than by choice — applied whenever it can be proven at all.
 *
 * **Residual risk, stated rather than hidden:** on an adopted row whose directory was swapped for
 * a different Tovu site, step 3 cannot fire and this renames the site that is there now. That is
 * the same directory whose name the card is already displaying, so the operator is not misled about
 * WHICH name they are changing — and the write is one reversible string, not a deletion.
 *
 * @returns the refreshed `SiteRecord`, so the card re-renders without a second `list` round trip.
 * @throws {Error} operator-facing, for every refusal above and for an invalid name
 *   (`site-config.ts`'s own 1..200-after-trim check, which mirrors what `tovu serve` re-applies at
 *   every boot).
 * @complexity O(n) in the tracked-site count, for the row lookup.
 */
function handleRename(input: RenameSiteInput, deps: Pick<ProjectIpcDeps, "projectsPath" | "classifySiteDir" | "writeSiteName" | "openSites" | "readSiteName" | "repoRoot" | "readPreviewVersion" | "transitions" | "sharedSites">) {
  const id = input?.id;
  const row = readTrackedSites(deps.projectsPath).find((tracked) => tracked.siteDir === id);
  if (row === undefined) {
    throw new Error(`This app is not tracking a site at ${id}, so there is nothing to rename.`);
  }

  // The SAFE classifier (`deps.classifySiteDir` is `classifySiteDirSafely` — see `main.ts`), so an
  // unreadable directory becomes a refusal with a reason rather than a throw from inside the guard.
  const kind = deps.classifySiteDir(row.siteDir);
  if (kind !== "site") {
    throw new Error(
      `${row.siteDir} is no longer a complete Tovu site (${kind}), so its name cannot be changed. ` +
        `If you moved the site, remove this card and add it again from its new location.`,
    );
  }

  if (identityHasChanged(row)) {
    throw new Error(
      `The site now at ${row.siteDir} is not the one this card was made for, so it was not renamed. ` +
        `Remove this card and add the site again from its current location.`,
    );
  }

  const nameError = siteNameError({ name: input?.name });
  if (nameError) throw new Error(nameError);
  const duplicateError = duplicateSiteNameError({ name: input.name!, names: otherSiteNames({ deps, siteDir: row.siteDir }) });
  if (duplicateError) throw new Error(duplicateError);
  const name = deps.writeSiteName(row.siteDir, input?.name);
  // An explicit successful rename replaces any Add alias; otherwise the card would keep its old name.
  row.displayNameAlias = undefined;
  rememberSiteAlias({ projectsPath: deps.projectsPath, siteDir: row.siteDir });
  rememberSiteName({ projectsPath: deps.projectsPath, siteDir: row.siteDir, displayName: name });

  retitleOpenSite({ siteDir: row.siteDir, name, openSites: deps.openSites });

  return buildSiteRecord(row, deps);
}

/** Refresh the native Window menu's name after a successful site rename.
 * @complexity O(1) time and space.
 */
function retitleOpenSite(
  { siteDir, name, openSites }: { siteDir: string; name: string; openSites: ProjectIpcDeps["openSites"] }, _options = {},
): void {
  // The open window's title, when there is one. There usually is NOT: a card opens its site as a
  // `<webview>` tab inside the sites home window (whose own title is pinned to "Tovu"), and
  // `openSiteServer` is spawn-only. Only "Open Site…"/"Open Recent" produce a titled window
  // (`main.ts`'s `openSiteWindow`). Worth the line anyway — `readSiteName`'s own doc says that
  // title is "what makes Electron's native Window menu double as a site switcher (distinct titles,
  // distinct entries)", so a stale one is a stale CONTROL, not a stale label.
  //
  // "Open Recent" itself needs no refresh: `main.ts` builds those items with the directory path as
  // the label, not the site name, so a rename cannot stale them.
  const openWindow = openSites.get(siteDir)?.window;
  if (openWindow && !openWindow.isDestroyed!()) openWindow.setTitle!(name); // present whenever `window` is (see `OpenSiteEntry.window`'s own doc)
}

/**
 * Hands one of a running project's surfaces to the operator's default browser. Refuses a project
 * that is not currently open rather than guessing a port — nothing durable records a stopped
 * project's last-known port today (see `tracked-sites.ts`'s header on why status is derived,
 * not stored), so "not running" and "never had a port to report" are the same state here.
 *
 * @throws {Error} when the project is not open.
 * @complexity O(1).
 */
async function handleOpenExternal(input: OpenSiteSurfaceInput, deps: Pick<ProjectIpcDeps, "openSites" | "shell">): Promise<void> {
  const openEntry = deps.openSites.get(input.siteId);
  if (openEntry === undefined) {
    throw new Error("That project is not open. Open it first, then try again.");
  }
  const url = `${openEntry.server.origin}${input.view === "site" ? "/" : "/admin/"}`;
  await deps.shell.openExternal(url);
}

/**
 * One site's cached preview as a `data:` URL, fetched ON DEMAND rather than riding along on
 * `buildSiteRecord`'s `previewVersion` field — see that field's own doc, and `site-preview-store.ts`'s
 * header, on why the polled record and the actual bytes are deliberately two different round trips.
 *
 * No tracked-row check, unlike every other handler here: `id` only ever reaches this as an input to
 * a digest (`site-preview-store.ts`'s `previewPath`), never as a filesystem path this function opens
 * directly, and reading is the only thing it does — there is no write or delete for a stale or
 * foreign id to cause.
 *
 * @returns the URL, or `null` when no capture exists yet — the ordinary state for a site that has
 *   never been opened, not an error to surface.
 * @complexity O(1) beyond `readPreviewDataUrl`'s own cost.
 */
function handleGetPreview(id: string, deps: Pick<ProjectIpcDeps, "readPreviewDataUrl">) {
  return deps.readPreviewDataUrl(id);
}

/**
 * A project tab's "not running yet" answer: ensure the site's `tovu serve` is up, spawning it if it
 * is not already running, or reusing it if another tab already has it open — never a `BrowserWindow`.
 * Reuses `openSiteServer` — `main.ts`'s spawn-only counterpart to the `openSiteWindow` "Open
 * Site…"/"Open Recent"/startup already use — through `serializer.run`, so opening the same tab twice
 * fast cannot double-spawn its server (see `main.ts`'s own doc on `openSiteServer`/
 * `keyed-serializer.ts`).
 *
 * Returns the project's fresh record rather than nothing: the renderer's `<webview>` needs the
 * `port` this call just produced, and re-deriving it would mean a second `list` round trip for
 * every tab open.
 *
 * The tracked-row check happens INSIDE the serialized region, not before it (D-05/SEC-02). Read
 * outside, it answered a question about a moment that had already passed: a delete queued on the
 * same key could untrack the row and erase the directory between the check and the spawn, and this
 * would then start a `tovu serve` on a path that no longer exists. Inside, "is this project still
 * tracked" is asked at the only instant its answer is still true when acted on.
 *
 * The boot is marked `starting` for its whole duration (`site-transitions.ts`) — seconds, during
 * which `openSites` still says "not running" and a card left to that alone shows the operator a
 * Start button that appears to have done nothing. The mark is released before the record below is
 * built, so what this RESOLVES with is the settled answer, never `starting`.
 *
 * @throws {Error} when `id` names a project this shell is not tracking — a stale id from a renderer
 *   that has not yet re-polled past a delete, refused rather than opening an arbitrary path.
 * @complexity O(1) beyond `openSiteServer`'s own cost, plus however long an already-queued
 *   operation on the same site takes to settle.
 */
async function handleStart<TCtx>(id: string, deps: Pick<ProjectIpcDeps<TCtx>, "serializer" | "projectsPath" | "openSiteServer" | "ctx" | "openSites" | "readSiteName" | "repoRoot" | "readPreviewVersion" | "transitions" | "sharedSites"> & Partial<Pick<ProjectIpcDeps, "classifySiteDir">>) {
  return await deps.serializer.run(id, async () => {
    const row = readTrackedSites(deps.projectsPath).find((entry) => entry.siteDir === id);
    if (row === undefined) {
      throw new Error(`Unknown project: ${id}`);
    }
    if ((deps.classifySiteDir ?? classifySiteDirSafely)(row.siteDir) !== "site") throw new Error("Folder moved or not a site. Locate the website folder or remove this card.");
    await markTransition(deps.transitions, id, "starting", () => explainMissingSiteDir(id, deps.openSiteServer(id, deps.ctx)));
    return buildSiteRecord(row, deps);
  });
}

/**
 * Rewrites `tovu serve`'s `SITE_DIR_INVALID` into "folder not found" when the tracked folder itself
 * is gone. A folder renamed or moved on disk (`sites/tovu-com` → `sites/tovu-dev`, 2026-09-28) is
 * still tracked by its old path, and serve's own "config.json is missing at …" sent the operator
 * looking for a config file rather than for the folder. Checked only after serve has refused, so a
 * start that succeeds pays nothing, and every other failure passes through untouched.
 */
async function explainMissingSiteDir(siteDir: string, starting: Promise<unknown>): Promise<void> {
  try {
    await starting;
  } catch (error) {
    if (!(error instanceof Error) || !error.message.includes("SITE_DIR_INVALID")) throw error;
    const folderExists = await fsp.stat(siteDir).then(() => true, () => false);
    if (folderExists) throw error;
    throw new Error(`Site folder not found: ${siteDir}. It was moved, renamed or deleted — remove this site from the list, then use Add Site on its new location.`);
  }
}

/**
 * Take one site's `tovu serve` down — the card's Stop, and the first way this app has ever had to
 * stop a single site from inside itself. Before it, `before-quit` (every site at once) and
 * `handleDelete` (the project is going away) were the only two, so an operator who wanted one site
 * down had to kill its process from a terminal.
 *
 * **Drains rather than kills.** `server.stop()` is `tovu-server.ts`'s `stopChild`: SIGTERM to the
 * child, which runs `serve.ts`'s own BR-07 shutdown — stop accepting, finish in-flight requests,
 * stop the agent daemon, close the sqlite handle — with a SIGKILL of the process GROUP only as the
 * 5 s escalation. That is the same call `before-quit` and `handleDelete` make; nothing here is a
 * shortcut past it, and nothing is left orphaned: `stopChild` resolves only once the child is
 * really gone.
 *
 * **The entry is dropped BEFORE the stop is awaited, deliberately** — the window-`closed` path in
 * `main.ts` does the identical thing for the identical reason. `site-supervisor.ts` watches each
 * entry's child and reports an exit it did not expect through `onUnexpectedExit`, which logs a
 * crash and records a `lastExitOf` the card then shows as "the site's server was stopped by
 * SIGTERM". For a stop the operator ASKED for, that is a lie in the one place they can read it.
 * Removing the entry first is what makes the supervisor's own identity check see this exit as no
 * longer its business. The teardown remains visible to Quit through the injected Jini shutdown
 * tracker; if exit cannot be confirmed, Stop rejects and retains the crash-safety row.
 *
 * The crash-safety row is dropped only AFTER the stop, never before: it exists so the NEXT launch
 * can reap a child this process left running, so it has to outlive the child. Dropping it up front
 * would mean a hard kill of the app mid-drain left a `tovu serve` that `reconcileOrphans` could
 * never find — the exact bug the window-`closed` path's own comment records.
 *
 * Stopping a site nobody started is a no-op that still returns its record, not an error: the
 * renderer polls every 4 s, so a card can be a click behind main's truth through no fault of the
 * operator's, and refusing would surface an error for a state they already wanted.
 *
 * **A site another process serves** (the shared lease names someone else — `npm run dev`, a sibling
 * instance) is stopped through `deps.externalSites` (owner 2026-10-13; the renderer confirms first).
 * Without that port wired, it is refused as before: "Stop it in that app."
 *
 * @returns the project's fresh record, so the card settles on `stopped` without waiting for a poll.
 * @throws {Error} when `id` names a project this shell is not tracking — same refusal, and same
 *   reason, as {@link handleStart}'s — or the child fails to exit after forced shutdown, or an
 *   external server's identity cannot be proved or it does not exit in time.
 * @complexity O(1) beyond `server.stop()`'s own drain (bounded by grace plus exit wait), plus however long
 *   an already-queued operation on the same site takes to settle.
 */
async function handleStop(id: string, deps: Pick<ProjectIpcDeps, "serializer" | "projectsPath" | "openSites" | "cancelPreviewCapture" | "readSiteName" | "repoRoot" | "readPreviewVersion" | "registryPath" | "recordSiteClosed" | "transitions" | "sharedSites" | "pendingTeardowns" | "externalSites">) {
  return await deps.serializer.run(id, async () => {
    const row = readTrackedSites(deps.projectsPath).find((entry) => entry.siteDir === id);
    if (row === undefined) {
      throw new Error(`Unknown project: ${id}`);
    }
    const running = deps.sharedSites?.running({ path: id }).read({});
    const openEntry = deps.openSites.get(id);
    const externalSites = deps.externalSites;
    if (running && (!openEntry || openEntry.server.external) && externalSites) {
      await markTransition(deps.transitions, id, "stopping", () => stopExternalServer({ id, lease: running, externalSites, deps }));
      return buildSiteRecord(row, deps);
    }
    if (running && !openEntry) throw new Error(`Running in ${running.app} (port ${running.port}). Stop it in that app.`);
    await markTransition(deps.transitions, id, "stopping", () => stopSiteServer(id, deps));
    return buildSiteRecord(row, deps);
  });
}

/**
 * {@link handleStop} for a site another process serves. This window's own attachment (if any) is
 * withdrawn FIRST, for the reason {@link stopSiteServer} drops its entry before stopping: the
 * attachment's lease watcher would otherwise report the exit the operator asked for as a crash.
 * Assumes it holds this site's serializer key.
 * @complexity see `external-site-stop.ts`'s `stopExternalSite`.
 */
async function stopExternalServer(
  { id, lease, externalSites, deps }: {
    id: string; lease: NonNullable<SharedRunning>; externalSites: NonNullable<ProjectIpcDeps["externalSites"]>;
    deps: Pick<ProjectIpcDeps, "openSites" | "cancelPreviewCapture" | "registryPath" | "recordSiteClosed" | "pendingTeardowns" | "sharedSites">;
  },
  _options = {},
): Promise<void> {
  await stopSiteServer(id, deps);
  await externalSites.stop({ lease, readLease: () => deps.sharedSites?.running({ path: id }).read({}) });
}

/**
 * {@link handleStop}'s side effect, split out so the handler above reads as its three steps — find
 * the row, stop the server, report the result — rather than interleaving the drain's own ordering
 * rules with them. Assumes it holds this site's serializer key.
 *
 * @complexity see {@link handleStop}.
 */
async function stopSiteServer(id: string, deps: Pick<ProjectIpcDeps, "openSites" | "cancelPreviewCapture" | "registryPath" | "recordSiteClosed" | "pendingTeardowns">): Promise<void> {
  deps.cancelPreviewCapture?.({ siteDir: id }, {});
  const openEntry = deps.openSites.get(id);
  if (openEntry === undefined) return;
  deps.openSites.delete(id);
  const teardown = openEntry.server.stop!().then(() => {
    // By pid, never by site dir alone: a live SIBLING app instance can hold its own row for this same
    // site, and a close by site dir would take that one too (D-07). A failed Stop keeps this row.
    deps.recordSiteClosed(deps.registryPath, id, { pid: openEntry.server.pid });
  });
  // openSites no longer exposes this child, so Quit must find its drain in the existing tracker.
  deps.pendingTeardowns?.track({ promise: teardown });
  await teardown;
}

/**
 * Run `body` with `siteDir` marked as mid-`transition`, when a transitions store was wired in.
 *
 * The optional half is what the two handlers would otherwise each repeat: `deps.transitions` is
 * absent in every test that is not exercising transition status, and a handler that had to
 * null-check it inline would state the boot/drain's own logic twice.
 *
 * @complexity O(1) beyond `body`'s own cost.
 */
function markTransition<T>(
  transitions: SiteTransitionsLike | undefined,
  siteDir: string,
  transition: "starting" | "stopping",
  body: () => Promise<T>,
): Promise<T> {
  return transitions === undefined ? body() : transitions.during(siteDir, transition, body);
}

/**
 * Find every Tovu site on disk the operator has no stored answer about, track it, and return the
 * whole refreshed list.
 *
 * This is the fix for the Projects screen having no discovery at all: {@link handleList} renders
 * `desktop-projects.json` and nothing else — no scan, no rescan, no fallback — so a site created by
 * `tovu init` outside the shell, or restored from a backup, was invisible forever no matter how
 * plainly it sat on disk. Runs once at boot (`main.ts`) and again whenever the operator asks.
 *
 * **A directory the operator removed on purpose is never brought back**, however many times this
 * runs. That is `adoptDiscoveredSites`' rule, not this function's, and the reason it lives down
 * there is that the boot pass and the operator's button must not be able to disagree about it: a
 * rescan that resurrected deleted cards would be the same bug the seed guard exists to prevent,
 * and worse here, since a button can be pressed again. Their way back is the folder dialog, which
 * reaches `trackSite` directly — see that function's own comment on why only the explicit adder
 * clears a dismissal.
 *
 * @param deps.siteScanRoots directories whose immediate children are candidate sites.
 * @param deps.siteFolders Profile settings read on every scan: built-in roots, remembered
 *   creation parents and extra roots. Supersedes the static roots when supplied.
 * @param deps.recentSiteDirs `site-dir-store.ts`'s recently-opened list, as a thunk — the sites
 *   own-server mode has been recording all along, which are the operator's by definition and
 *   generally do not live under any scan root.
 * @param deps.discoverSites Production's bounded, cancellable worker; reads roots/MRU off-thread.
 * @returns A promise for the same records {@link handleList} would return, after the pass.
 * @throws Discovery limit, timeout or cancellation errors before any candidate is adopted.
 * @complexity O(n log n) discovery plus O(n + m) adoption for n candidates and m stored rows.
 */
async function rescanSites(deps: Pick<ProjectIpcDeps, "siteScanRoots" | "recentSiteDirs" | "classifySiteDir" | "projectsPath" | "openSites" | "readSiteName" | "repoRoot" | "readPreviewVersion" | "transitions" | "siteFolders" | "sharedSites" | "discoverSites">) {
  // Production injects the read-only worker. Legacy hosts/tests retain the same discovery owner.
  const found = deps.discoverSites ? await deps.discoverSites({}) : discoverSiteDirs({
    scanRoots: deps.siteFolders?.read({}).roots ?? deps.siteScanRoots,
    knownDirs: deps.recentSiteDirs(),
    classifySiteDir: deps.classifySiteDir,
  }, { homeDir: deps.sharedSites?.homeDir, sitesHome: deps.sharedSites?.home({}) });
  adoptWithUniqueNames({ deps, siteDirs: found });
  return handleList(deps);
}

/** Main owns the picker; adding a root only changes future discovery, never site files/processes.
 * @returns Fresh settings, or null on cancellation.
 * @throws Native picker or persistence errors, preserving their actual message.
 * @complexity O(n log n) bounded discovery in the worker, then O(r) settings for r roots.
 */
async function handleAddSiteFolder({ deps }: { deps: Pick<ProjectIpcDeps, "dialog" | "siteFolders" | "discoverSites" | "classifySiteDir" | "recentSiteDirs" | "sharedSites"> }, _options = {}) {
  if (!deps.siteFolders) throw new Error("Sites folders settings are unavailable in this desktop version.");
  const picked = await deps.dialog.showOpenDialog({
    title: "Add sites folder", message: "Choose a folder containing Tovu website folders. Use Rescan to discover them.",
    buttonLabel: "Add folder", properties: ["openDirectory"],
  });
  if (picked.canceled || picked.filePaths.length === 0) return null;
  const root = fs.realpathSync(picked.filePaths[0]!);
  const scanRoots = [...new Set([...deps.siteFolders.read({}).roots, root])];
  // Use the discovery owner before committing settings, including aggregate entry/root limits.
  // A failed scan leaves both shared config and legacy profile settings byte-for-byte unchanged.
  if (deps.discoverSites) await deps.discoverSites({ scanRoots });
  else discoverSiteDirs({ scanRoots, knownDirs: deps.recentSiteDirs(), classifySiteDir: deps.classifySiteDir }, { homeDir: deps.sharedSites?.homeDir, sitesHome: deps.sharedSites?.home({}) });
  return deps.siteFolders.add({ root });
}

/**
 * Registers the real `runner:sites:*` handlers, including discovery-folder settings.
 *
 * @param deps
 * @param deps.openSites live open sites, keyed by site dir — `main.ts`'s own module-level
 *   store, passed in rather than imported. `Map`-compatible; in production it is
 *   `site-supervisor.ts`'s supervisor, which additionally drops an entry whose child has died and
 *   answers `lastExitOf` about it. A sites-home-opened (embedded-tab) entry carries no `window`; only
 *   own-server-mode entries do.
 * @param deps.serializer per-site-dir operation serializer (`keyed-serializer.ts`).
 * @param deps.projectsPath `tracked-sites.ts`'s tracked-project JSON file.
 * @param deps.registryPath crash-safety registry directory (`site-process-registry.ts`), for
 *   `recordSiteClosed` on a delete of a running project and `readRegistry` in its guard.
 * @param deps.repoRoot Tovu repo root.
 * @param deps.statePath `site-dir-store.ts`'s MRU file, for `adoptSiteDir`.
 * @param deps.cliMode `"source"` or `"compiled"` — see `tovu-server.ts`.
 * @param deps.readSiteName `main.ts`'s site-display-name reader.
 * @param deps.writeSiteName `site-config.ts`'s validating, atomic `config.json` name
 *   writer, used by {@link handleRename}. Injected rather than imported for the same reason
 *   `adoptSiteDir` is — every handler in this file stays callable from plain `node --test` against
 *   fakes, and a rename test must never write into a real site directory.
 * @param deps.readPreviewVersion `site-preview-store.ts`'s reader, bound to this launch's
 *   userData at the same call site every other consumer resolves it from — feeds
 *   `buildSiteRecord`'s `previewVersion` field.
 * @param deps.readPreviewDataUrl `site-preview-store.ts`'s reader, bound the same way —
 *   {@link handleGetPreview}'s on-demand fetch.
 * @param deps.deletePreview `site-preview-store.ts`'s remover, bound the same way —
 *   called beside `untrackSite` in {@link deleteProject}.
 * @param deps.adoptSiteDir `site-dir-store.ts`'s folder-to-site-dir classifier/initializer.
 * @param deps.addSitePointer `add-site-pointer.ts`'s pointer-only adder, used by
 *   {@link handleAddSite}. Injected rather than imported for the same reason `adoptSiteDir` is —
 *   every handler in this file stays callable from plain `node --test` against fakes.
 * @param deps.classifySiteDir `site-dir-store.ts`'s classifier, called by `handleCreate`
 *   BEFORE `adoptSiteDir` to record whether this app is about to create the directory or is adopting
 *   one that already exists — see `handleCreate`'s own comment and `project-delete-guard.ts`.
 * @param deps.openSiteServer `main.ts`'s spawn-or-reuse-a-site's-backend function
 *   (no `BrowserWindow` — see that function's own doc).
 * @param deps.recordSiteClosed `site-process-registry.ts`'s crash-safety row remover.
 * @param deps.readRegistry `site-process-registry.ts`'s crash-safety registry reader, used by
 *   {@link liveForeignServers} to see a SIBLING app instance's open sites — which `openSites`, being
 *   this process's own memory, cannot.
 * @param deps.isLiveServeRow `site-process-registry.ts`'s "is this row's pid still its own live
 *   `tovu serve`" identity proof, so a stale or recycled pid can never block a delete.
 * @param deps.ctx `{cliMode, registryPath}` — `openSiteServer`'s own second argument.
 * @complexity O(1) — a fixed set of channel registrations.
 */
function registerSiteIpcHandlers<TCtx>(deps: ProjectIpcDeps<TCtx>): void {
  const relocationGate = createRelocationGate({}, { classifySiteDir: deps.classifySiteDir });
  deps.ipcMain.handle(SITE_IPC_CHANNELS.list, () => requestMissingPreviews(handleList({ ...deps, relocationGate }), deps));
  deps.ipcMain.handle(SITE_IPC_CHANNELS.planNewDir, (_event, input) => ({
    path: planNewSiteDir({ name: input?.name }, { workspace: deps.sharedSites }), homeDir: os.homedir(),
  }));
  deps.ipcMain.handle(SITE_IPC_CHANNELS.create, (_event, input) => handleCreate(input, deps));
  deps.ipcMain.handle(SITE_IPC_CHANNELS.delete, (_event, id) => handleDelete(id, deps));
  deps.ipcMain.handle(SITE_IPC_CHANNELS.openExternal, (_event, input) => handleOpenExternal(input, deps));
  deps.ipcMain.handle(SITE_IPC_CHANNELS.start, (_event, id) => handleStart(id, deps));
  deps.ipcMain.handle(SITE_IPC_CHANNELS.stop, (_event, id) => handleStop(id, deps));
  deps.ipcMain.handle(SITE_IPC_CHANNELS.rescan, () => rescanSites(deps));
  deps.ipcMain.handle(SITE_IPC_CHANNELS.setHome, async () => {
    if (!deps.sharedSites) throw new Error("Sites home settings are unavailable in this desktop version.");
    const picked = await deps.dialog.showOpenDialog({ title: "Choose Tovu Sites home", buttonLabel: "Use this folder", properties: ["openDirectory", "createDirectory"] });
    if (picked.canceled || !picked.filePaths[0]) return null;
    const selected = picked.filePaths[0];
    if (!path.isAbsolute(selected) || !fs.statSync(selected).isDirectory()) throw new Error("Choose an existing absolute sites folder.");
    deps.sharedSites.setHome({ path: selected });
    return { ...(deps.siteFolders?.read({}) ?? { roots: [], extraRoots: [] }), home: deps.sharedSites.home({}) };
  });
  deps.ipcMain.handle(SITE_IPC_CHANNELS.saveSettings, (_event, input: import("./contracts/project.ts").SiteSettingsPatch) => {
    if (!deps.sharedSites || !deps.siteFolders) throw new Error("Sites settings are unavailable in this desktop version.");
    if (!input || typeof input !== "object" || Array.isArray(input) || Object.keys(input).some((key) => key !== "databases") ||
      (input.databases !== "inSite" && input.databases !== "appData")) throw new Error('Sites settings accept only databases: "inSite" or "appData". Choose folders with the native picker.');
    deps.sharedSites.updateConfig({ patch: { databases: input.databases } });
    return deps.siteFolders.read({});
  });
  deps.ipcMain.handle(SITE_IPC_CHANNELS.listFolders, () => deps.siteFolders?.read({}) ?? { roots: deps.siteScanRoots, extraRoots: [] });
  deps.ipcMain.handle(SITE_IPC_CHANNELS.addFolder, () => handleAddSiteFolder({ deps }));
  deps.ipcMain.handle(SITE_IPC_CHANNELS.removeFolder, (_event, input: { root: string }) => {
    if (typeof input?.root !== "string" || !path.isAbsolute(input.root)) throw new Error("Choose an absolute sites folder path to remove.");
    if (!deps.siteFolders) throw new Error("Sites folders settings are unavailable in this desktop version.");
    return deps.siteFolders.remove({ root: input.root });
  });
  deps.ipcMain.handle(SITE_IPC_CHANNELS.rename, (_event, input) => handleRename(input, deps));
  deps.ipcMain.handle(SITE_IPC_CHANNELS.addSite, () => handleAddSite(deps));
  deps.ipcMain.handle(SITE_IPC_CHANNELS.preview, (_event, id) => handleGetPreview(id, deps));
  deps.ipcMain.handle(SITE_IPC_CHANNELS.locate, (_event, id) => handleLocate(id, deps));
  deps.ipcMain.handle(SITE_IPC_CHANNELS.tokenSignInPlugins, () => handleTokenSignInPlugins(deps));
}

/**
 * The full `deps` bag {@link registerSiteIpcHandlers} needs — every individual handler above takes
 * only the `Pick` of this it actually reads, so a caller wiring one handler in isolation (as this
 * file's own tests do) never has to fabricate the fields it does not touch.
 */
interface ProjectIpcDeps<TCtx = unknown> {
  ipcMain: IpcMainLike;
  dialog: DialogLike;
  shell: ShellLike;
  openSites: OpenSites;
  serializer: Serializer;
  projectsPath: string;
  registryPath: string;
  repoRoot: string;
  statePath: string;
  cliMode: "source" | "compiled";
  readSiteName: (siteDir: string) => string;
  writeSiteName: (siteDir: string, rawName: unknown) => string;
  readPreviewVersion: (siteDir: string) => number | null;
  readPreviewDataUrl: (id: string) => string | null;
  deletePreview: (id: string) => void;
  removeSiteTree?: typeof removeSiteTree;
  /** Capture a running site's preview when its card has none — main's dedupe, never per-poll work. */
  requestPreviewCapture?: (required: { siteDir: string; port: number }, optional: {}) => void;
  /** Stop/Restart must withdraw pending hidden-window work before the server drains. */
  cancelPreviewCapture?: (required: { siteDir: string }, optional: {}) => void;
  /** Jini's existing shutdown tracker: Quit must also await Stops removed from openSites. */
  pendingTeardowns?: { track(required: { promise: PromiseLike<unknown> }): Promise<void> };
  adoptSiteDir: (input: AdoptSiteDirInput) => Promise<string>;
  addSitePointer: AddSitePointerLike;
  /** Injected for tests; defaults to `agent-plugin-tokens.ts`'s CLI-backed lister. */
  listTokenSignInPlugins?: (input: { repoRoot: string; cliMode?: "source" | "compiled" }) => Promise<TokenSignInPlugin[]>;
  // `classifySiteDirSafely`'s verdicts, spelled out because `site-dir-store.ts` does not export its
  // `SiteClassification`. The throwing `classifySiteDir` and the tests' fakes return a subset.
  classifySiteDir: (dir: string) => "site" | "incomplete" | "empty" | "occupied" | "unreadable";
  openSiteServer: (siteDir: string, ctx: TCtx) => Promise<unknown>;
  /**
   * `site-transitions.ts`'s store — which sites are mid-start or mid-stop right now, the fact
   * `openSites` cannot express. `main.ts` wires the real one (`main-project-wiring.test.ts` holds
   * it there); `buildSiteRecord` and the two lifecycle handlers are its only readers.
   *
   * Optional so every existing test bag stays valid: a handler asked to build a record without one
   * reports the same two-valued `running`/`stopped` it always did, which is exactly right for a
   * test that is not exercising a transition.
   */
  transitions?: SiteTransitionsLike;
  recordSiteClosed: (registryPath: string, siteDir: string, options?: { pid?: number }) => void;
  readRegistry: (registryPath: string) => { sites: RegistryRow[]; unreadable: string[] };
  isLiveServeRow: (row: RegistryRow) => boolean;
  siteScanRoots: string[];
  /** Profile-bound, read fresh at boot and Rescan; optional for older hosts and handler fakes. */
  siteFolders?: SiteFoldersPort;
  /** Production discovery runs filesystem probes off-thread; results grant no deletion authority. */
  discoverSites?: (required: { scanRoots?: string[] }, options?: {}) => Promise<string[]>;
  recentSiteDirs: () => string[];
  sharedSites?: SitesWorkspace;
  /** Stops a site another process serves (`external-site-stop.ts`). Absent: such a Stop is refused. */
  externalSites?: Pick<ExternalSiteStopper, "launcherOf" | "stop">;
  ctx: TCtx;
}

export {
  SITE_IPC_CHANNELS,
  foreignServerMessage,
  unreadableRegistryMessage,
  buildSiteRecord,
  handleList,
  handleAddSite,
  handleCreate,
  handleDelete,
  handleOpenExternal,
  handleStart,
  handleStop,
  handleRename,
  handleGetPreview,
  handleLocate,
  handleTokenSignInPlugins,
  rescanSites,
  registerSiteIpcHandlers,
};
export type { ProjectIpcDeps, SiteRow, OpenSiteEntry, OpenSites, RegistryRow, SiteTransitionsLike };

/**
 * @file The rules that keep `apps/desktop`'s quality gates from going quiet. Pure functions only —
 * no spawning, no filesystem — so the whole policy is testable under plain `node --test`. The CLI
 * that actually runs the gates is `scripts/check-gates.ts`.
 *
 * **The defect this exists for.** A 2026-09-12 survey of this repo's existing harness found 11 of
 * 22 `check:*` npm scripts invoked from nowhere at all, and one gate
 * (`development/scripts/check-area-coverage-floor.ts`) fully written, documented, and shipped with
 * its required config file never created — so it had never run once and nothing said so. The
 * `apps/admin` complexity ratchet was 11 violations behind for the same reason: it exists, it is
 * correct, and no CI step or local runner calls it.
 *
 * None of that was a decision anybody made. It is what happens when "this gate is off" is
 * representable as *absence* — a line nobody added, a file nobody created, a script nobody calls.
 * The whole design here is to make "off" a positive, loud, dated assertion instead:
 *
 * 1. {@link formatSummary} prints EVERY gate on every run, including the disabled ones. "Off"
 *    appears in the output of every run rather than in a diff nobody reads.
 * 2. {@link validateManifest} makes `enabled: false` without a reason and a date a hard failure OF
 *    THE RUNNER. Turning a gate off costs a sentence; turning it off invisibly is impossible.
 * 3. {@link detectGateDrift} fails when a gate script exists on disk that the manifest does not
 *    list. This is the one that `check-area-coverage-floor.ts` could not have survived.
 * 4. {@link validateManifest} also ages disablements out: a gate off longer than `maxDisabledDays`
 *    fails until someone re-confirms the date. Debt is allowed; INVISIBLE debt is not.
 *
 * Note the asymmetry in what counts as failure here: a *disabled* gate never fails the run (that is
 * the point of being able to turn one off), but a disabled gate that is undocumented, undated, or
 * stale DOES. The thing being enforced is not "all gates are on" — it is "no gate is off by
 * accident".
 */

/** One entry of `quality-gates.json`'s `gates`, as parsed and NOT yet validated: every field is
 *  optional because {@link validateManifest} is what reports a missing one. */
export interface GateEntry {
  id?: string;
  run?: string;
  enabled?: boolean;
  disabledReason?: string;
  disabledOn?: string;
}

/** The parsed `quality-gates.json`. `gates` is `unknown` until {@link validateManifest} has checked
 *  that it is an array at all. */
export interface GateManifest {
  gates?: unknown;
  maxDisabledDays?: number;
}

/** A gate command's exit status: `null` when it was killed by a signal or never spawned. */
export type GateExitCode = number | null;

/**
 * Narrows `value` into `GateEntry[]`, replacing the blind `gates as GateEntry[]` cast this file and
 * `scripts/check-gates.ts` used to do at their JSON-parsing boundary. Non-array input is left to each
 * caller's own "no gates array" problem reporting (returns `[]`, same as the old cast's `?? []`
 * fallback) — but a `null` or non-object array ELEMENT is valid JSON that used to pass that cast
 * silently and then crash deep inside property access ({@link gateProblems}'s `gate.id`,
 * {@link detectGateDrift}'s `gate.run`) as an unhelpful "Cannot read properties of null". That is a
 * genuinely malformed gate entry, so it throws a clear error naming the index and value instead.
 *
 * @param value typically `manifest.gates`, fresh out of `JSON.parse` and not yet trustworthy.
 * @returns `value` narrowed to `GateEntry[]`, or `[]` when `value` is not an array at all.
 * @throws {Error} naming the array index and JSON value of the first `null`/non-object element.
 * @complexity O(n) in entries.
 */
export function asGateEntryArray(value: unknown): GateEntry[] {
  if (!Array.isArray(value)) return [];
  value.forEach((entry, index) => {
    if (entry === null || typeof entry !== "object") {
      throw new Error(`quality-gates.json: gates[${index}] must be an object; found ${JSON.stringify(entry)}.`);
    }
  });
  return value as GateEntry[];
}

/** How long a gate may stay disabled before the runner demands the date be re-confirmed. */
const DEFAULT_MAX_DISABLED_DAYS = 30;

const MS_PER_DAY = 86_400_000;

/**
 * Whole days between two ISO `YYYY-MM-DD` dates. Deliberately date-only arithmetic rather than
 * `Date.now()` deltas: a disablement recorded "today" must read as 0 days regardless of the clock
 * time either side, or a gate disabled at 23:00 would age a day at midnight.
 *
 * @param fromIso the `disabledOn` date.
 * @param toIso today, as `YYYY-MM-DD`.
 * @returns whole days elapsed, or `null` if either date is unparseable.
 * @complexity O(1).
 */
function daysBetween(fromIso: string, toIso: string): number | null {
  const from = Date.parse(`${fromIso}T00:00:00Z`);
  const to = Date.parse(`${toIso}T00:00:00Z`);
  if (Number.isNaN(from) || Number.isNaN(to)) return null;
  return Math.round((to - from) / MS_PER_DAY);
}

/**
 * Problems with ONE disabled gate's paperwork. Split out of {@link validateManifest} so that
 * function stays under this repo's own complexity ceiling of 9 — the same ceiling this harness
 * enforces on everything else, which it would be absurd to exempt itself from.
 *
 * @complexity O(1).
 */
function disabledGateProblems(gate: GateEntry, today: string, maxDisabledDays: number): string[] {
  const problems: string[] = [];
  const where = `gate "${gate.id}"`;
  if (!gate.disabledReason) {
    problems.push(`${where} is disabled with no "disabledReason". A gate may be turned off, but not silently.`);
  }
  if (!gate.disabledOn) {
    problems.push(`${where} is disabled with no "disabledOn" date, so nothing can tell how long it has been off.`);
    return problems;
  }
  const age = daysBetween(gate.disabledOn, today);
  if (age === null) {
    problems.push(`${where} has an unparseable "disabledOn" (${gate.disabledOn}); expected YYYY-MM-DD.`);
  } else if (age > maxDisabledDays) {
    problems.push(
      `${where} has been disabled ${age} days (since ${gate.disabledOn}, limit ${maxDisabledDays}). ` +
        `Re-enable it, or re-confirm the decision by updating "disabledOn" and "disabledReason".`
    );
  }
  return problems;
}

/** Problems with ONE gate entry: shape, uniqueness, and (when off) its paperwork. Split out so
 *  {@link validateManifest} stays under the 9/9 ceiling this harness enforces on everything else —
 *  which it would be absurd to exempt itself from.
 *  @complexity O(1). */
function gateProblems(gate: GateEntry, seen: Set<string>, today: string, maxDisabledDays: number): string[] {
  if (!gate.id || !gate.run) {
    return [`every gate needs an "id" and a "run"; found ${JSON.stringify(gate)}.`];
  }
  const problems = seen.has(gate.id) ? [`duplicate gate id "${gate.id}".`] : [];
  seen.add(gate.id);
  if (gate.enabled === false) problems.push(...disabledGateProblems(gate, today, maxDisabledDays));
  return problems;
}

/**
 * Every reason this manifest is not a legitimate description of the harness. An empty array means
 * the manifest itself is sound — it says nothing about whether the gates pass.
 *
 * @param manifest the parsed `quality-gates.json`.
 * @param today `YYYY-MM-DD`, injected rather than read from the clock so the ratchet is testable.
 * @returns human-readable problems, one per line, ready to print.
 * @complexity O(n) in gates.
 */
export function validateManifest(manifest: GateManifest | null | undefined, today: string): string[] {
  const gates = manifest?.gates;
  if (!Array.isArray(gates)) return ['quality-gates.json has no "gates" array.'];
  if (gates.length === 0) return ['quality-gates.json lists zero gates — the harness would pass by measuring nothing.'];

  // `!`: `gates` is an array, so `manifest` was not null or undefined.
  const maxDisabledDays = manifest!.maxDisabledDays ?? DEFAULT_MAX_DISABLED_DAYS;
  const problems: string[] = [];
  const seen = new Set<string>();

  for (const gate of asGateEntryArray(gates)) problems.push(...gateProblems(gate, seen, today, maxDisabledDays));
  return problems;
}

/**
 * Gate scripts present on disk that no manifest entry runs — the check that makes a written-but-
 * unwired gate impossible to leave lying around. Matching is by substring of the `run` command
 * rather than by exact path, because a `run` legitimately carries flags and a wrapper
 * (`node scripts/check-coverage.ts --areas ...`).
 *
 * @param gates the manifest's gate list (disabled ones count as registered — being off is a
 *   decision, being absent is not).
 * @param scriptNames basenames of the gate scripts found on disk, e.g. `["check-coverage.ts"]`.
 * @returns the basenames nothing references.
 * @complexity O(gates x scripts); both are single digits here.
 */
export function detectGateDrift(gates: readonly GateEntry[] | null | undefined, scriptNames: readonly string[]): string[] {
  const commands = asGateEntryArray(gates).map((gate) => String(gate.run ?? ""));
  return scriptNames.filter((name) => !commands.some((command) => command.includes(name)));
}

/** One line per gate, in manifest order. `PASS`/`FAIL` for what ran, `DISABLED` for what did not —
 *  the disabled ones carry their reason and date so the summary is self-explaining.
 *  @complexity O(1). */
function summaryLine(gate: GateEntry, outcome: GateExitCode | undefined): string {
  if (gate.enabled === false) {
    return `  DISABLED  ${gate.id}  — ${gate.disabledReason ?? "(no reason given)"} [since ${gate.disabledOn ?? "?"}]`;
  }
  return `  ${outcome === 0 ? "PASS    " : "FAIL    "}  ${gate.id}`;
}

/**
 * The whole run, rendered. Every gate appears — that is property 1 and the reason this function
 * takes the full manifest rather than only the results.
 *
 * @param gates the manifest's gate list.
 * @param outcomes `Map<gateId, exitCode>` for the gates that actually ran. Keyed by `string |
 *   undefined` because `gates` is unvalidated: a gate with no `id` looks up `undefined`, finds no
 *   outcome, and counts as a failure.
 * @returns the printable summary block.
 * @complexity O(n) in gates.
 */
export function formatSummary(gates: readonly GateEntry[], outcomes: ReadonlyMap<string | undefined, GateExitCode>): string {
  const lines = ["", "=".repeat(66), "DESKTOP GATE SUMMARY", "=".repeat(66)];
  let passed = 0;
  let failed = 0;
  let disabled = 0;

  for (const gate of gates) {
    if (gate.enabled === false) {
      disabled += 1;
    } else if (outcomes.get(gate.id) === 0) {
      passed += 1;
    } else {
      failed += 1;
    }
    lines.push(summaryLine(gate, outcomes.get(gate.id)));
  }

  lines.push("-".repeat(66));
  lines.push(`  ${gates.length} gates: ${passed} pass, ${failed} fail, ${disabled} DISABLED`);
  return lines.join("\n");
}

/**
 * True when a gate's result should fail the run. A gate that never produced a numeric exit code —
 * killed by a signal, or a command that could not be spawned at all — is a FAILURE, never a pass.
 * That asymmetry is deliberate: this repo has already shipped a packaged app off a step that
 * "succeeded" without doing anything, and an absent exit code is the same shape of evidence.
 *
 * @complexity O(1).
 */
export function isFailure(exitCode: GateExitCode | undefined): boolean {
  return exitCode !== 0;
}

export { DEFAULT_MAX_DISABLED_DAYS, daysBetween };

import { SITE_NAME_ERROR, siteNameError } from "../contracts/site-name.js";
import { humanSiteError, siteOperationError, tabAfterClose, readyNoticeStillTrue, dismissOnEscape } from "./site-shell-policy.js";
/**
 * Custom hooks pulled out of `App.tsx`.
 *
 * Most of this is stateful/effectful logic that used to live inline inside `App()` or one of its
 * child components — polling, subscriptions, and view state. Splitting it out of the components is
 * what let `App()` and `SiteGrid` drop back under the complexity ceiling without changing what
 * either one does; see the header comment in `eslint.config.mjs` for why that ceiling exists. This
 * file carries no JSX and no rendering decisions of its own — those stay in `App.tsx`, unchanged
 * in shape.
 *
 * The plain functions mixed in here (`deriveSitesHomeView`, `computeCanCreate`,
 * `buildCreateProjectInput`, `siteSlug`) are deliberately NOT hooks. Each is a rule that used to
 * be inlined into a hook body, pulled out to where it can be called with an object and asserted
 * against directly — no React, no component, no hook harness. `countRunningSites`, `navLinkClick`,
 * `settingsControlHandlers` and `startThenNotify` are the same kind of thing pulled out of
 * `App.tsx`'s component bodies instead, so those components define no functions of their own. When something in this file can be
 * a pure function, it should be one; the hooks around them exist for the state and the effects
 * they genuinely need.
 *
 * Components take these hooks as props with the real hook as the default (see `App`,
 * `SiteGrid`, `CreateWebsiteOnboarding`), so a test can substitute a stub without the component
 * reaching for IPC, timers, or window listeners. The prop is always the hook FUNCTION, never its
 * result — a default of `useFoo()` would only run when the caller omits the prop, which makes hook
 * order depend on the call site. Biome's `correctness/useHookAtTopLevel` runs at error severity in
 * `npm run lint` and catches exactly that mistake.
 */
import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type Dispatch,
  type FormEvent,
  type KeyboardEvent as ReactKeyboardEvent,
  type RefObject,
  type SetStateAction,
} from 'react';
import type {
  ChatPaneProps,
  ChatPaneRuntimeAccess,
  ChatPaneWorkingDirectoryAccess,
} from '@jini-ai/chat/react/chat-pane';
import type { ChatMessage } from '@jini-ai/chat/core';
import type { ConversationListItem } from '@jini-ai/chat/react';
import { runnerInventoryBridge, type RunnerInventoryBridge } from './runner-api.js';
import { createWorkspaceChatTransport, type WorkspaceChatTransport } from './workspace-chat-transport.js';
import { createLocalAttachmentUploader } from './chat-attachments.js';
import { persistableMessages } from './persistable-messages.js';
import { startVisibleInterval } from './visible-interval.js';
import {
  expandedAfterKeyDown,
  expandedAfterWorkspaceChange,
  nextExpanded,
} from './expanded-mode.js';
import type { RunnerSectionId } from '../contracts/sections.js';
import type { ThemePreference } from './theme.js';
import type { SiteAdminPage } from './import-site-entry.js';
import type { CreateSiteInput, CreatedSiteRecord, DatabaseProviderKind, SiteRecord } from '../contracts/project.js';
import type { WorkspaceConversationSummary } from '../contracts/workspace-conversations.js';

/**
 * The desktop-bridge lookup every bridge-reading hook below takes as an optional port, defaulted to
 * `runnerInventoryBridge` (`window.tovuRunner`). A LOOKUP rather than the bridge itself so each hook
 * still reads the bridge exactly when it did before — inside the effect, the callback, or the
 * once-per-lifetime memo — and a test hands in a fake without touching `window`. Each hook narrows
 * it to the slice of the bridge it actually calls.
 */
export type BridgeLookup<K extends keyof RunnerInventoryBridge> = () => Pick<RunnerInventoryBridge, K> | undefined;

/**
 * Polls Runner's project inventory on a 4s interval.
 *
 * Runner supervises OS processes that change state on their own — a site can crash, or finish
 * booting, with no user action in this window. A mount-only fetch would leave the grid showing a
 * state that stopped being true minutes ago, so re-poll on an interval — only while the window is
 * visible (`startVisibleInterval`): a hidden window does not poll, and polls once the moment it is
 * shown again.
 */
export function useSitesPolling(
  _required: Record<string, never> = {},
  {
    getBridge = runnerInventoryBridge,
    startInterval = startVisibleInterval,
  }: { getBridge?: BridgeLookup<'listSites'>; startInterval?: (tick: () => void, periodMs: number) => () => void } = {},
): {
  projects: readonly SiteRecord[];
  setProjects: Dispatch<SetStateAction<readonly SiteRecord[]>>;
  projectsLoading: boolean;
  loadError: string | null;
} {
  const [projects, setProjectsState] = useState<readonly SiteRecord[]>([]);
  const [projectsLoading, setProjectsLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  // Bumped by every local write (create, delete, rename). A poll that started before one is an
  // older snapshot: applying it would erase that write, and the one-time create notice with it.
  const mutationEpoch = useRef(0);
  const setProjects = useCallback<Dispatch<SetStateAction<readonly SiteRecord[]>>>((next) => {
    mutationEpoch.current++;
    setProjectsState(next);
  }, []);

  useEffect(() => {
    const bridge = getBridge();
    if (bridge === undefined) {
      setProjectsLoading(false);
      return;
    }
    let cancelled = false;

    const load = () => {
      const startedAt = mutationEpoch.current;
      return bridge
        .listSites()
        .then((result) => {
          if (cancelled || startedAt !== mutationEpoch.current) return;
          setProjectsState(result);
          setLoadError(null);
        })
        .catch(() => {
          if (!cancelled) setLoadError("Couldn't load projects.");
        })
        .finally(() => {
          if (!cancelled) setProjectsLoading(false);
        });
    };

    void load();
    const stop = startInterval(() => void load(), 4000);
    return () => {
      cancelled = true;
      stop();
    };
  }, [getBridge, startInterval]);

  return { projects, setProjects, projectsLoading, loadError };
}

/**
 * The operator-triggered discovery pass behind the Projects header's "Rescan" control.
 *
 * A button and not only the boot pass, because the reasons a site appears on disk mid-session are
 * ordinary: `tovu init` in a terminal, a folder restored from a backup, a checkout pulled down
 * next to this one. Without it the answer to "my site is right there and Tovu cannot see it" is
 * "quit and relaunch".
 *
 * Takes `setProjects` — `useSitesPolling`'s own setter — and applies main's returned list
 * immediately rather than leaving the grid to the next 4s poll. To the operator those are not the
 * same thing: a rescan that has already found their site but shows nothing for four seconds reads
 * as a button that does not work.
 *
 * `rescanning` is deliberately not derived from the polling hook's `projectsLoading`: that one is
 * true only until the first list arrives, so it would report nothing at all here.
 */
export function useSiteRescan(
  setProjects: Dispatch<SetStateAction<readonly SiteRecord[]>>,
  { getBridge = runnerInventoryBridge }: { getBridge?: BridgeLookup<'rescanSites'> } = {},
): {
  rescanning: boolean;
  rescanError: string | null;
  rescan: () => Promise<void>;
} {
  const [rescanning, setRescanning] = useState(false);
  const [rescanError, setRescanError] = useState<string | null>(null);

  const rescan = useCallback(async () => {
    const bridge = getBridge();
    if (bridge === undefined) return;
    setRescanning(true);
    setRescanError(null);
    try {
      setProjects(await bridge.rescanSites());
    } catch (failure) {
      setRescanError(failure instanceof Error ? failure.message : String(failure));
    } finally {
      setRescanning(false);
    }
  }, [setProjects, getBridge]);

  return { rescanning, rescanError, rescan };
}

/**
 * `desktop.navigate` is a tool the fleet chat can actually call, so the nav is agent-movable and
 * not only user-movable. Nothing else in main pushes on this channel. It also pulls focus back
 * to the sites home tab — navigating to a Runner section while a site's admin fills the screen would
 * otherwise change something the operator cannot see.
 *
 * Takes the RAW `setActiveId`, deliberately not `useSectionNav`'s `selectSection`. Agent
 * navigation therefore does not close the Appearance page or cancel a half-filled create form the
 * way a click on the nav does. That asymmetry is pre-existing and preserved here unchanged, but it
 * is worth knowing about: with Appearance open, a `desktop.navigate` call moves `activeId` and the
 * operator sees nothing happen, because `MainArea` renders Appearance ahead of the section. Fixing
 * it means deciding what the agent is allowed to dismiss on the operator's behalf, which is a
 * product question, not a refactor.
 */
export function useRunnerNavigation(
  setActiveId: Dispatch<SetStateAction<RunnerSectionId>>,
  setActiveTab: Dispatch<SetStateAction<string | null>>,
  { getBridge = runnerInventoryBridge }: { getBridge?: BridgeLookup<'onNavigate'> } = {},
): void {
  useEffect(() => {
    const bridge = getBridge();
    return bridge?.onNavigate((section) => {
      setActiveId(section);
      setActiveTab(null);
    });
  }, [setActiveId, setActiveTab, getBridge]);
}

export interface SectionNavState {
  activeId: RunnerSectionId;
  /**
   * The raw setter, exposed only for `useRunnerNavigation`. Agent navigation deliberately moves
   * `activeId` WITHOUT running `selectSection`'s other three resets — see the note on that hook.
   */
  setActiveId: Dispatch<SetStateAction<RunnerSectionId>>;
  appearanceOpen: boolean;
  isCreating: boolean;
  selectSection: (id: RunnerSectionId) => void;
  openAppearance: () => void;
  closeAppearance: () => void;
  startCreating: () => void;
  stopCreating: () => void;
}

/**
 * Which Runner screen is showing: the current section, whether the Appearance page is layered over
 * it, and whether the create-website form has replaced the sites grid.
 *
 * These three used to be raw `useState` calls in `App`, kept there on the argument that they cross
 * sibling subtrees and are written together by coordinated callbacks. That argument is about
 * architecture and answers the wrong question — `selectSection` writes four pieces of state at
 * once, and "does moving section also cancel a half-filled create form" is exactly the kind of
 * thing worth pinning down without standing up a component tree. Owning them here makes that one
 * function the unit under test; `App` still does the wiring, it just no longer holds the setters.
 *
 * `setActiveTab` arrives as an argument rather than being owned here because tabs are a separate
 * concern with a separate hook (`useProjectTabs`) — but dropping to the sites home tab is genuinely part
 * of every section-level move, so the call belongs inside these callbacks rather than duplicated at
 * each `App` call site. That ordering constraint (tabs hook first, this one second) is why the
 * `activeId`/`appearanceOpen` half of the old `useProjectTabs` became `deriveSitesHomeView` below.
 */
export function useSectionNav(
  setActiveTab: Dispatch<SetStateAction<string | null>>,
): SectionNavState {
  const [activeId, setActiveId] = useState<RunnerSectionId>('projects');
  // TEMPORARY SCAFFOLD — this is not a real `RunnerSectionId` page, just enough state to judge
  // whether "Settings dropdown → its own page" feels right before building a real
  // Appearance/Settings screen against the contract. See `AppearancePage` in `App.tsx`.
  const [appearanceOpen, setAppearanceOpen] = useState(false);
  const [isCreating, setIsCreating] = useState(false);

  // Moving section is a full reset of everything layered over the section's own screen: an
  // in-progress create form, the Appearance page, and any project tab all belong to where you
  // were, not where you are going.
  const selectSection = (id: RunnerSectionId) => {
    setActiveId(id);
    setIsCreating(false);
    setActiveTab(null);
    setAppearanceOpen(false);
  };

  // Appearance covers the whole content area. Dropping the active tab means closing Appearance
  // returns to the sites grid rather than to a workspace the operator has not seen for a while.
  const openAppearance = () => {
    setAppearanceOpen(true);
    setActiveTab(null);
  };

  const closeAppearance = () => setAppearanceOpen(false);
  const startCreating = () => setIsCreating(true);
  const stopCreating = () => setIsCreating(false);

  return {
    activeId,
    setActiveId,
    appearanceOpen,
    isCreating,
    selectSection,
    openAppearance,
    closeAppearance,
    startCreating,
    stopCreating,
  };
}

export interface ProjectTabsState {
  // Project ids with an open tab, in the order they were opened.
  openTabs: readonly string[];
  activeTab: string | null;
  setActiveTab: Dispatch<SetStateAction<string | null>>;
  /** `adminPage` sends the tab's admin to that page (the "Import site" entry); without it an
   *  already-open tab stays wherever it is. */
  openProjectTab: (id: string, options?: { adminPage?: SiteAdminPage }) => void;
  closeProjectTab: (id: string) => void;
  /** The admin page each tab was opened on, by project id. Absent = the admin's root. */
  adminPages: Readonly<Record<string, SiteAdminPage>>;
}

/**
 * Owns which project tabs are open and which one is selected — the state, and nothing derived
 * from it. Everything that was derived here now lives in `deriveSitesHomeView`, which needs section
 * state this hook does not have.
 *
 * `openProjectTab` only ever adds a tab and selects it — it does not itself ask main to start
 * anything. `SiteWorkspace` (`App.tsx`) is what shows a "not running" panel for a freshly opened
 * tab and lets the operator start it from there (`useSiteStart`), the same split Tovu-Runner's
 * own `App.hooks.ts` makes: opening a tab and starting a site are two different actions, one
 * instant and local, the other async and IPC-backed.
 */
export function useProjectTabs(): ProjectTabsState {
  // `null` active tab means the sites home tab (Runner's own sections); a string means that project's
  // embedded admin.
  const [openTabs, setOpenTabs] = useState<readonly string[]>([]);
  const [activeTab, setActiveTab] = useState<string | null>(null);
  const [adminPages, setAdminPages] = useState<Readonly<Record<string, SiteAdminPage>>>({});

  const openProjectTab = (id: string, options: { adminPage?: SiteAdminPage } = {}) => {
    setOpenTabs((current) => (current.includes(id) ? current : [...current, id]));
    setActiveTab(id);
    const { adminPage } = options;
    if (adminPage) setAdminPages((current) => (current[id] === adminPage ? current : { ...current, [id]: adminPage }));
  };

  const closeProjectTab = (id: string) => {
    // Resolve from the current tab order before removing the closed tab.
    setActiveTab((current) => tabAfterClose({ tabs: openTabs, active: current, closing: id }));
    setOpenTabs((current) => current.filter((tabId) => tabId !== id));
    setAdminPages((current) => {
      if (!(id in current)) return current;
      const { [id]: _closed, ...rest } = current;
      return rest;
    });
  };

  return { openTabs, activeTab, setActiveTab, openProjectTab, closeProjectTab, adminPages };
}

export interface SiteMutationsState {
  /**
   * The created record, not just its name: the notice reports the port and template version the
   * provisioner actually produced, which is the only place those are known to be true.
   */
  lastCreated: CreatedSiteRecord | null;
  openCreateWebsite: () => void;
  handleCreate: (input: CreateSiteInput) => Promise<void>;
  handleDelete: (id: string) => Promise<void>;
  /** Cancel's handler, not `stopCreating` directly — see `cancelCreate` below for why the two
   *  differ. */
  cancelCreate: () => void;
  /** Bumped on every deliberate exit from the create form. `App` passes it as the form's `key`,
   *  so the ONLY thing that resets the form's typed fields is this counter changing — ordinary
   *  navigation away and back must not. */
  createFormKey: number;
}

/**
 * The sites-home mutations `App` offers — open the create form, create, delete, cancel a create — plus
 * the record the last successful create produced and the counter that clears the create form.
 *
 * These lived inline in `App` on the argument that `handleCreate` needs `setProjects` from the
 * polling hook and `stopCreating` from the nav hook in the same function, so it is composition and
 * composition is what the component is for. That reasoning does not hold: needing two values from
 * two places is a reason to take them as ARGUMENTS, which is what this hook does. What it actually
 * bought was async handlers, each with a bridge-missing branch and an ordering rule, that could
 * not be exercised without mounting `App` and stubbing `window.tovuRunner`.
 *
 * `createFormKey` lives here rather than in `useSectionNav` alongside `isCreating`, for the same
 * reason `lastCreated` does: its writers are `handleCreate` and `cancelCreate`, both defined here,
 * and both need to distinguish a deliberate exit (clear the form) from `isCreating` simply going
 * false as a side effect of navigating elsewhere (do not clear it) — a distinction `useSectionNav`
 * has no way to make, since it does not know why `stopCreating` was called.
 *
 * `lastCreated` moves here with them rather than staying behind, because `handleCreate` and
 * `openCreateWebsite` are its only writers — state separated from its only writers is the split
 * this extraction exists to undo, not one to introduce.
 *
 * Every dependency arrives as an argument and nothing is closed over, so a test calls this with
 * four spies and asserts the orderings that matter: that a missing bridge throws BEFORE any state
 * is touched, that delete drops the row locally AND closes its tab, and that `openCreateWebsite`
 * clears a stale notice before the form opens rather than after.
 */
/**
 * Replace one project's row with the refreshed `SiteRecord` main just resolved with, leaving every
 * other row untouched.
 *
 * The alternative is waiting for `useSitesPolling`'s 4 s tick, and for a start or a stop those four
 * seconds are the whole problem: the card would go on saying `Running` after the operator watched
 * their stop succeed. A record NOT in the list is dropped rather than appended — this applies a
 * change to a project the grid is already showing, and a row that arrives here for an unknown id is
 * a stale id, not a new site (`rescan`/`create`/`add` are what add rows).
 *
 * `previousId` is for a missing-folder card's Locate, whose record comes back under its NEW folder
 * (a record's id is its folder): the card at `previousId` is replaced, and when the found folder
 * already had a card of its own, that one is dropped so the merged site shows once.
 *
 * @complexity O(n) in the project count, once per applied record.
 */
export function useApplySiteRecord(
  setProjects: Dispatch<SetStateAction<readonly SiteRecord[]>>,
): (record: SiteRecord, previousId?: string) => void {
  return useCallback(
    (record: SiteRecord, previousId: string = record.id) => {
      setProjects((current) =>
        current.flatMap((project) => {
          if (project.id === previousId) return [record];
          return project.id === record.id ? [] : [project];
        }),
      );
    },
    [setProjects],
  );
}

export function useProjectMutations(deps: {
  setProjects: Dispatch<SetStateAction<readonly SiteRecord[]>>;
  closeProjectTab: (id: string) => void;
  stopCreating: () => void;
  startCreating: () => void;
  projects?: readonly SiteRecord[];
}, { getBridge = runnerInventoryBridge }: { getBridge?: BridgeLookup<'createSite' | 'deleteSite'> } = {}): SiteMutationsState {
  const [lastCreated, setLastCreated] = useState<CreatedSiteRecord | null>(null);
  useEffect(() => {
    if (deps.projects && lastCreated && !readyNoticeStillTrue({ created: lastCreated, projects: deps.projects })) setLastCreated(null);
  }, [deps.projects, lastCreated]);
  // See `createFormKey` on `SiteMutationsState`. Starts at 0 and only ever goes up; the actual
  // number carries no meaning beyond "changed since the form last mounted".
  const [createFormKey, setCreateFormKey] = useState(0);

  // Clear first, open second. The notice names a specific site on a specific port; carrying the
  // previous one into a fresh form would caption the new site with the old site's facts.
  //
  // Bumping `createFormKey` here is what makes "+ Create website" mean what it says. The form
  // survives being HIDDEN — Appearance, a project tab, `desktop.navigate` — because those leave
  // `isCreating` true and the operator returns to the same instance with their typing intact.
  // But a path that ends the creation outright (`selectSection` resets `isCreating` on a TopNav
  // click) makes this button the only way back, and it should open an empty form: the operator
  // asked to create a website, not to resume one. Without this, that route would re-present a
  // stale half-filled form — including whatever was typed into the credential inputs, which no
  // longer has an owner on screen.
  const openCreateWebsite = () => {
    setLastCreated(null);
    setCreateFormKey((key) => key + 1);
    deps.startCreating();
  };

  const handleCreate = async (input: CreateSiteInput) => {
    const bridge = getBridge();
    if (bridge === undefined) {
      throw new Error('Runner desktop connection required to create a website.');
    }
    const result = await bridge.createSite(input);
    if (result === null) return; // Cancelling the picker keeps the form and its name intact.
    // The token outcome is for the notice only; the grid keeps plain records.
    const { agentPluginTokens: _tokens, ...record } = result;
    deps.setProjects((current) => [...current, record]);
    setLastCreated(result);
    deps.stopCreating();
    // A successful create is a deliberate exit exactly like Cancel: bumping the key here is what
    // remounts the form empty rather than leaving the just-submitted site's name and credential
    // sitting in fields the operator is about to open again for a second site.
    setCreateFormKey((key) => key + 1);
  };

  // Distinct from `deps.stopCreating` rather than a second name for it: Cancel is the ONE exit
  // that must also clear typed state (see `createFormKey`). Every other way the form stops being
  // visible — a project tab, Appearance, a different section — is incidental and must NOT clear
  // it, which is the entire point of keeping the form mounted instead of unmounting it on those.
  const cancelCreate = () => {
    deps.stopCreating();
    setCreateFormKey((key) => key + 1);
  };

  const handleDelete = async (id: string) => {
    const bridge = getBridge();
    if (bridge === undefined) {
      throw new Error('Runner desktop connection required to delete a website.');
    }
    await bridge.deleteSite(id);
    // Dropped locally rather than left to the 4s poll: the card the operator just confirmed
    // against would otherwise sit there looking untouched for up to four seconds. Its tab goes
    // too — a tab pointing at a deleted project has nothing left to render.
    deps.setProjects((current) => current.filter((project) => project.id !== id));
    deps.closeProjectTab(id);
  };

  return { lastCreated, openCreateWebsite, handleCreate, handleDelete, cancelCreate, createFormKey };
}

export interface SitesHomeView {
  openSites: readonly SiteRecord[];
  // Tabs are a Projects mechanic. Every other section is a single Runner screen, so a strip above
  // one would advertise routes that section cannot take.
  inSites: boolean;
  activeSite: SiteRecord | undefined;
  showSiteTab: boolean;
  showSitesHome: boolean;
  visibleWorkspaceId: string | null;
  // Whether the (permanently mounted, see `CreateWebsiteHost` in `App.tsx`) create form should be
  // the thing on screen right now, as opposed to hidden behind Appearance, a project's workspace,
  // or a non-Projects section.
  showCreateForm: boolean;
}

/**
 * Everything `App` renders from that is a pure function of section state + tab state + the polled
 * project list: whether the sites grid, a project's workspace, or the create form is on screen,
 * and which one.
 *
 * A plain function, not a hook, and that is the point. It holds no state and calls nothing from
 * React, so the whole "which surface should be showing" rule set is exercisable by calling it with
 * an object — no renderer, no component, no hook harness.
 */
export function deriveSitesHomeView(input: {
  activeId: RunnerSectionId;
  appearanceOpen: boolean;
  activeTab: string | null;
  openTabs: readonly string[];
  projects: readonly SiteRecord[];
  isCreating: boolean;
}): SitesHomeView {
  const openSites = input.openTabs
    .map((id) => input.projects.find((project) => project.id === id))
    .filter((project): project is SiteRecord => project !== undefined);

  // Gating on `activeId` hides the strip without touching `openTabs`/`activeTab`, so navigating
  // away and back leaves the same tabs open.
  const inSites = input.activeId === 'projects';

  // A project deleted or lost between polls must not strand its tab pointing at nothing.
  const activeSite =
    input.activeTab === null ? undefined : openSites.find((p) => p.id === input.activeTab);
  // Deriving this from `inSites` as well — not from `activeTab` alone — is what makes a
  // project's workspace unreachable outside Projects rather than merely unlikely to be reached.
  const showSiteTab = inSites && activeSite !== undefined;
  const showSitesHome = !showSiteTab;
  // Every open project's workspace stays mounted (see `App`'s `<main>` body); this is the one that
  // is not hidden. Appearance layers over the whole content area, so it hides the workspace too.
  const visibleWorkspaceId = !input.appearanceOpen && showSiteTab ? input.activeTab : null;
  // The create form is a fourth layer competing for the same space as Appearance and a project's
  // workspace, so it is visible only when none of those are: not over Appearance, not over a
  // project tab, not over a non-Projects section.
  const showCreateForm = input.isCreating && !input.appearanceOpen && showSitesHome && inSites;

  return {
    openSites,
    inSites,
    activeSite,
    showSiteTab,
    showSitesHome,
    visibleWorkspaceId,
    showCreateForm,
  };
}

/**
 * Immersive mode: the active project's admin takes the whole window and Tovu's own chrome (top
 * nav, tab strip, fleet chat) gets out of the way. Owns both the state and the two rules that keep
 * it honest — it must never outlive the workspace it is immersing, and Escape must collapse it.
 */
export function useExpandedMode(showSiteTab: boolean): {
  expanded: boolean;
  toggleExpanded: () => void;
} {
  const [expanded, setExpanded] = useState(false);

  // Expanded hides the only navigation there is, so it must never outlive the thing it was
  // expanding. Closing the tab, deleting the project, or a `desktop.navigate` call moving the nav
  // would otherwise leave the chrome hidden with nothing to be immersed in and no way back.
  useEffect(() => {
    setExpanded((on) => expandedAfterWorkspaceChange(on, showSiteTab));
  }, [showSiteTab]);

  // Escape collapses. This listener only sees keys pressed in Tovu's own chrome — a <webview>
  // is a separate browsing context and does not bubble its keydowns out to this document — so it
  // is a convenience, never the only exit. The bar's collapse button is the one that always works.
  // `expandedAfterKeyDown` returns the SAME value for every key that is not Escape, so the updater
  // form costs nothing for the other keys: React bails out of the re-render when state is unchanged.
  useEffect(() => {
    if (!expanded) return;
    const onKeyDown = (event: KeyboardEvent) => {
      setExpanded((on) => expandedAfterKeyDown(on, event.key));
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [expanded]);

  const toggleExpanded = () => setExpanded(nextExpanded);

  return { expanded, toggleExpanded };
}

/**
 * A dropdown's open state plus the "click/tap outside closes it" behaviour every dropdown in the
 * top nav wants (`SettingsControl`'s appearance menu, `SiteGrid`'s per-card `SiteCardMenu`). `NavLink`
 * has no dropdown of its own — it is a plain section link — so it is not a caller here. Was
 * duplicated inline in both call sites before this extraction.
 */
export function useDismissibleDropdown<T extends HTMLElement = HTMLDivElement>(): {
  open: boolean;
  setOpen: Dispatch<SetStateAction<boolean>>;
  containerRef: RefObject<T | null>;
} {
  const [open, setOpen] = useState(false);
  const containerRef = useRef<T>(null);

  useEffect(() => {
    if (!open) return;
    const onPointerDown = (event: PointerEvent) => {
      if (!containerRef.current?.contains(event.target as Node)) setOpen(false);
    };
    const onEscape = (event: KeyboardEvent) => dismissOnEscape({ event, dismiss: () => setOpen(false) });
    document.addEventListener('keydown', onEscape, true);
    document.addEventListener('pointerdown', onPointerDown);
    return () => {
      document.removeEventListener('pointerdown', onPointerDown);
      document.removeEventListener('keydown', onEscape, true);
    };
  }, [open]);

  return { open, setOpen, containerRef };
}

/**
 * Which menu entry a key moves focus to, or `null` when the key is not a menu-navigation key.
 * Wraps at both ends, as native menus do. `current` is `-1` when focus is not on an entry yet.
 *
 * @complexity O(1).
 */
export function menuFocusIndex(
  { key, current, count }: { key: string; current: number; count: number }, _optional = {},
): number | null {
  if (count === 0) return null;
  if (key === 'ArrowDown') return (current + 1) % count;
  if (key === 'ArrowUp') return current <= 0 ? count - 1 : current - 1;
  if (key === 'Home') return 0;
  if (key === 'End') return count - 1;
  return null;
}

const MENU_ENTRIES = '[role="menuitem"], [role="menuitemradio"]';

/**
 * The keyboard half of a `role="menu"` dropdown: on open, focus lands on the first entry (the
 * selected one for a radio group is reached with the arrows like any other); Up/Down/Home/End move
 * between entries; and when the menu closes with focus still inside it — an entry was chosen, or
 * Escape — focus goes back to the trigger instead of falling to `<body>`. Escape itself stays
 * `useDismissibleDropdown`'s job. A click elsewhere moved focus on purpose, so that is left alone.
 *
 * @complexity O(n) per key in the number of entries.
 */
export function useMenuKeyboard<T extends HTMLElement = HTMLDivElement, B extends HTMLElement = HTMLButtonElement>(
  { open }: { open: boolean },
  _optional = {},
): { menuRef: RefObject<T | null>; triggerRef: RefObject<B | null>; onMenuKeyDown: (event: ReactKeyboardEvent<T>) => void } {
  const menuRef = useRef<T>(null);
  const triggerRef = useRef<B>(null);
  useEffect(() => {
    if (!open) return;
    menuRef.current?.querySelector<HTMLElement>(MENU_ENTRIES)?.focus();
    return () => {
      const active = document.activeElement;
      if (!active || active === document.body || menuRef.current?.contains(active)) triggerRef.current?.focus();
    };
  }, [open]);

  const onMenuKeyDown = (event: ReactKeyboardEvent<T>) => {
    const entries = [...(menuRef.current?.querySelectorAll<HTMLElement>(MENU_ENTRIES) ?? [])];
    const next = menuFocusIndex({ key: event.key, current: entries.indexOf(document.activeElement as HTMLElement), count: entries.length });
    if (next === null) return;
    event.preventDefault();
    entries[next]?.focus();
  };

  return { menuRef, triggerRef, onMenuKeyDown };
}

/**
 * How many tracked sites are running right now — the count `NavLink` badges on the Projects entry.
 *
 * @complexity O(n) in the number of sites.
 */
export function countRunningSites(projects: readonly SiteRecord[]): number {
  return projects.filter((project) => project.status === 'running').length;
}

/**
 * `NavLink`'s `onClick`: selects its section unless the link is disabled, in which case the click
 * does nothing. `NavLink` disables through `aria-disabled` rather than the native attribute (see its
 * doc), so a disabled button still receives clicks and this guard is what makes it inert.
 *
 * @param input.disabled `NavLink`'s own optional flag; `undefined` means enabled.
 * @complexity O(1).
 */
export function navLinkClick(input: {
  disabled: boolean | undefined;
  id: RunnerSectionId;
  onSelectSection: (id: RunnerSectionId) => void;
}): () => void {
  return () => {
    if (input.disabled) return;
    input.onSelectSection(input.id);
  };
}

/** `SettingsControl`'s three handlers — see {@link settingsControlHandlers}. */
export interface SettingsControlHandlers {
  /** The gear button: flips the dropdown, unless the control is disabled. */
  toggleOpen: () => void;
  /** A theme pill: applies the theme, then closes the dropdown. */
  chooseTheme: (next: ThemePreference) => void;
  /** The "Appearance" link: closes the dropdown, then opens the page. */
  openAppearancePage: () => void;
}

/**
 * `SettingsControl`'s handlers, built from its dropdown setter and its two callbacks.
 *
 * Only the gear button checks `disabled`, for the same `aria-disabled` reason as
 * {@link navLinkClick}. The two dropdown entries do not, because a dropdown that cannot open offers
 * nothing to click.
 *
 * @complexity O(1).
 */
export function settingsControlHandlers(input: {
  disabled: boolean;
  setOpen: Dispatch<SetStateAction<boolean>>;
  onThemeChange: (next: ThemePreference) => void;
  onOpenAppearance: () => void;
}): SettingsControlHandlers {
  return {
    toggleOpen: () => {
      if (input.disabled) return;
      input.setOpen((current) => !current);
    },
    chooseTheme: (next) => {
      input.onThemeChange(next);
      input.setOpen(false);
    },
    openAppearancePage: () => {
      input.setOpen(false);
      input.onOpenAppearance();
    },
  };
}

/**
 * The project grid's delete-confirm flow: which card (if any) is asking to be confirmed, which
 * one is mid-delete, and the error from the last failed attempt.
 *
 * Confirmation lives on the card rather than in a `window.confirm`: a native modal dialog blocks
 * the whole renderer, and in Electron that also freezes the IPC this window answers on.
 */
export function useDeleteConfirmation(onDelete: (id: string) => Promise<void>): {
  pendingId: string | null;
  deletingId: string | null;
  deleteError: string | null;
  requestDelete: (id: string) => void;
  cancelDelete: () => void;
  confirmDelete: (id: string) => Promise<void>;
} {
  const [pendingId, setPendingId] = useState<string | null>(null);
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [deleteError, setDeleteError] = useState<string | null>(null);

  const requestDelete = (id: string) => {
    setDeleteError(null);
    setPendingId(id);
  };

  const cancelDelete = () => setPendingId(null);
  useEffect(() => {
    if (!pendingId) return;
    const onEscape = (event: KeyboardEvent) => dismissOnEscape({ event, dismiss: cancelDelete, busy: deletingId !== null });
    document.addEventListener('keydown', onEscape, true);
    return () => document.removeEventListener('keydown', onEscape, true);
  }, [pendingId, deletingId]);

  const confirmDelete = async (id: string) => {
    setDeletingId(id);
    setDeleteError(null);
    try {
      await onDelete(id);
      setPendingId(null);
    } catch (err) {
      setDeleteError(humanSiteError({ error: err, fallback: 'Could not delete this website. Its card has been kept so you can try again.' }));
    } finally {
      setDeletingId(null);
    }
  };

  return { pendingId, deletingId, deleteError, requestDelete, cancelDelete, confirmDelete };
}

/** What one `startSite` call came back with: main's refreshed record, or an operator-facing
 *  reason — {@link useSiteStart}'s own counterpart to `use-site-power.hooks.ts`'s
 *  `SitePowerResult`. */
export type SiteStartResult = { record: SiteRecord; error?: undefined } | { record?: undefined; error: string };

/**
 * Runs one `startSite` call against the desktop bridge and reports the outcome.
 *
 * Separated from {@link useSiteStart} for the identical reason `use-site-power.hooks.ts` splits
 * `performPowerAction` out of `useSitePower`: this package has no React renderer, so anything left
 * inside a hook's own closure can only be asserted against source text. This is the plain function
 * a test can call directly.
 *
 * A missing bridge is reported exactly like a rejected call rather than thrown — `useSiteStart`'s
 * `error` state is where an operator reads either one, matching `performPowerAction`'s own
 * contract verbatim (same message shape, same "no exception" rule).
 *
 * @returns `{record}` on success — main's own refreshed record, never one composed here from
 *   whatever was on screen before the click. That record is what lets a caller apply the outcome
 *   the instant this resolves, instead of waiting on `useSitesPolling`'s 4s poll to notice.
 * @complexity O(1) beyond the IPC round trip, which for a start includes the child's own boot
 *   (`DEFAULT_READY_TIMEOUT_MS`, up to 60s).
 */
export async function performSiteStart(
  id: string,
  bridge: { startSite: (id: string) => Promise<SiteRecord> } | undefined,
): Promise<SiteStartResult> {
  if (bridge === undefined) return { error: 'Tovu desktop connection required to start a website.' };
  try {
    return { record: await bridge.startSite(id) };
  } catch (err) {
    return { error: siteOperationError({ error: err, operation: 'start' }) };
  }
}

/**
 * `SiteStartPanel`'s start/pending/error state.
 *
 * Starting from here rather than only from the grid matters because this is where the operator
 * already is when they find out — the tab was opened expecting a site.
 *
 * **`onSiteUpdated` is what closes the gap between "main's call resolved" and "this tab's own
 * `project` prop agrees".** Before it existed, nothing was set locally on success at all: the
 * button's `starting` flag cleared the instant `startSite` resolved, reverting to an enabled,
 * idle-looking "Start site" — while the site had, in fact, already finished its 40-75s boot — and
 * stayed that way for up to `useSitesPolling`'s own 4s before `project.status` caught up to
 * `running` and `SiteWorkspace` swapped this panel for the guest. An operator glancing back in
 * that window saw a button that looked like their click had done nothing. Passing main's own
 * resolved record straight to `App`'s `applySiteRecord` (the same setter `use-site-power.hooks.ts`
 * already wires for the grid card) removes the wait entirely: the prop update and the button
 * clearing land in the same tick.
 *
 * Deliberately NOT built on `useDeleteConfirmation`'s shape, even though both are a "pending flag
 * + error string around one async call": on a missing bridge, `start` sets `error` and returns
 * WITHOUT ever setting `starting` true — a call that never got as far as attempting the action
 * shouldn't flash a loading state. `useDeleteConfirmation`'s `confirmDelete` always sets its
 * pending flag first and lets the try/catch around the call itself produce the error. A shared
 * generic "set pending, run this, catch" wrapper can't reproduce the early return without either
 * special-casing it (which defeats sharing) or setting `starting` true for one tick it was never
 * true for before. That is a real, if small, behaviour change, so the two stay separate.
 *
 * `start` resolves to whether it actually started the site — `false` on a missing bridge or a
 * caught `startSite` error, `true` otherwise — rather than throwing. It never rejects: both failure
 * paths are already reported through `error` state, so a caller does not also need a try/catch.
 * That boolean is what lets {@link startThenNotify} tell a real start apart from a failed attempt
 * that merely finished.
 *
 * @param onSiteUpdated applies main's refreshed record the moment a start resolves. Optional, and
 *   the tab is still eventually correct without it — the 4s poll gets there — but see this
 *   function's own doc above for why that gap is exactly the bug an operator can see.
 */
export function useSiteStart(
  project: SiteRecord,
  onSiteUpdated?: (record: SiteRecord) => void,
  { getBridge = runnerInventoryBridge }: { getBridge?: BridgeLookup<'startSite'> } = {},
): {
  starting: boolean;
  error: string | null;
  start: () => Promise<boolean>;
} {
  const [starting, setStarting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const start = async () => {
    setStarting(true);
    setError(null);
    const result = await performSiteStart(project.id, getBridge());
    try {
      if (result.error !== undefined) {
        setError(result.error);
        return false;
      }
      onSiteUpdated?.(result.record);
      return true;
    } finally {
      setStarting(false);
    }
  };

  return { starting, error, start };
}

/**
 * `SiteStartPanel`'s Start handler: awaits `start`, then calls `onStarted` only if `start` reports
 * it actually started the site.
 *
 * Both of `SiteStartPanel`'s `onStarted` call sites (`App.tsx`'s stalled/failed workspace overlays)
 * pass `workspace.recover`, which remounts the `<webview>` for a fresh attempt at loading the
 * guest. Remounting is only worth doing when the start it is reacting to actually happened — on a
 * failed attempt (missing bridge, or `startSite` itself failing) nothing changed for the guest to
 * find, so recovering would just remount into the same failure or stall. `useSiteStart`'s `start`
 * never rejects (a missing bridge or a caught error both resolve, having recorded `error` state
 * instead), so telling the two apart means reading the resolved boolean rather than whether the
 * promise settled at all. If `start` does reject for some other reason, `onStarted` is skipped and
 * the rejection reaches the caller, same as before.
 *
 * @complexity O(1) plus `start`'s own cost.
 */
export function startThenNotify(
  start: () => Promise<boolean>,
  onStarted: (() => void) | undefined,
): () => Promise<void> {
  return async () => {
    const started = await start();
    if (started) onStarted?.();
  };
}

/**
 * Detects a guest that is alive-but-not-answering, and tells apart the two different ways that
 * can happen — `failed`, a FACT: `did-fail-load` fired on the `<webview>`'s main frame with a
 * real error, as opposed to a normal in-flight navigation being cancelled. `stalled`, a GUESS:
 * neither `did-fail-load` nor `did-finish-load` showed up at all within `STALL_TIMEOUT_MS`, which
 * means exactly nothing — Chromium never told this hook anything either way, and the guest may
 * still be about to answer on its own. `SiteWorkspace` treats the two accordingly: `failed`
 * swaps the guest out outright, the same way a stopped project does, because there is nothing left
 * to wait for. `stalled` only lays a recovery panel over the still-loading guest, because there
 * might be.
 *
 * Two Electron quirks make `isMainFrame`/`errorCode` filtering load-bearing rather than optional.
 * `did-fail-load` fires for sub-resources too — a missing favicon, a failed XHR inside the admin —
 * and `isMainFrame` is what tells those apart from the guest itself being unreachable. It also
 * fires with `errorCode === -3` (`ABORTED`) on completely ordinary navigations: the view toggle
 * and the reload button both cancel whatever load was already in flight, and Chromium reports that
 * cancellation exactly the way it reports a real failure. Counting either as a failure would swap
 * a perfectly good admin for an error panel on every ordinary click.
 *
 * `STALL_TIMEOUT_MS` is this hook's own ceiling on "still loading, no verdict yet" — ported
 * unchanged from Tovu-Runner's own measurement of a freshly created project's slowest real first
 * `/admin/` request (see that file's own history for the live numbers): comfortably past how long a
 * local admin normally takes to answer, comfortably short of leaving the operator staring at a
 * blank pane for the rest of the session.
 *
 * `resetKey` is `useSiteWorkspace`'s `loadResetKey` (`reloadNonce`, `view`, `softLoads`), not read
 * here for its value — only for when it changes. A recovery remount replaces the guest (new DOM
 * node, so listeners must move with it), while a view switch or a soft load (`reload()`,
 * `loadURL()`) renavigates the same node; all of them deserve a clean slate, since
 * without one a single transient failure would pin the recovery panel in place even after the
 * operator's next click plainly asked for another try. The same reset also re-arms the stall timer,
 * which is what lets the recovery panel's own "Start site" retry get a second, fresh judgment.
 *
 * **The guest arrives through `guestRef`, a callback ref, and that is the D-03 fix.** This used to
 * take a `RefObject` and depend on `[webviewRef, resetKey]`. A ref OBJECT is stable for the
 * component's whole life, and `SiteWorkspace` renders the `<webview>` only when
 * `running && !failed` — so on the two ordinary paths that mount a guest (a stopped tab whose 4 s
 * poll flips to `running`, and the failure panel's own retry) neither dependency changed, the
 * effect never re-ran, and NO listener and no stall timer were ever installed on the node actually
 * on screen. Only "Reload while healthy" — where `key` remounts the guest in the same commit the
 * effect follows — attached them, which is the path that needs recovery least. The hook was right
 * in form and wrong in binding: its own doc said the listeners "must move with" the node, and
 * nothing in its inputs changed when the node appeared. Holding the node in STATE makes it a
 * dependency that really does change on attach, so the effect's lifetime IS the node's.
 *
 * The reset is deliberately a SECOND effect keyed on `resetKey` alone. Folding it back into the
 * node-keyed effect looks tidier and reintroduces a worse bug: `failed` going true unmounts the
 * guest, which fires `guestRef(null)`, which would re-run a combined effect and clear the very
 * flag that unmounted it — the guest remounts, fails again, and the panel flickers forever.
 *
 * **`loaded` is the third flag, added alongside `failed`/`stalled` for the same reason those two
 * exist: "the guest is mounted" is not "the admin is on screen".** Before it, a fresh guest gave
 * the operator nothing to look at from the moment it mounted until either `did-finish-load` swapped
 * in real content or `STALL_TIMEOUT_MS` ran out and guessed something was wrong — a blank pane for
 * up to 8 seconds on every ordinary open, indistinguishable from a hang. `loaded` is what a caller
 * checks to show its OWN "still loading" state in that window, instead of leaving it silent.
 * `true` only once `did-finish-load` has actually fired for the CURRENT `resetKey`; it resets to
 * `false` in lockstep with `failed`/`stalled` so a remount, a view switch, or a soft load all start
 * from "not loaded yet" rather than carrying over a previous navigation's finished state.
 *
 * @returns `guestRef` alongside the three flags — the caller MUST put it on the `<webview>`; there
 *   is no other way for this hook to see the node. `guest` is that node, for `useSiteWorkspace`'s
 *   history listeners, which need the same lifetime and cannot take a second ref on one element.
 */
export function useWebviewLoadFailure(
  resetKey: unknown,
  { timers = window }: { timers?: Pick<Window, 'setTimeout' | 'clearTimeout'> } = {},
): {
  failed: boolean;
  stalled: boolean;
  loaded: boolean;
  guest: HTMLWebViewElement | null;
  guestRef: (node: HTMLWebViewElement | null) => void;
} {
  const [failed, setFailed] = useState(false);
  const [stalled, setStalled] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [guest, setGuest] = useState<HTMLWebViewElement | null>(null);

  useEffect(() => {
    // Not read for its value — only for when it changes. `resetKey` is what makes reload and a
    // view switch a clean slate rather than a permanent black mark; without a genuine reference
    // to it here, Biome's exhaustive-deps rule reads the dependency as dead weight and asks to
    // drop it, which would drop the reset along with it.
    void resetKey;
    setLoaded(false);
    setFailed(false);
    setStalled(false);
  }, [resetKey]);

  useEffect(() => {
    if (guest === null) return;

    const STALL_TIMEOUT_MS = 8000;
    const stallTimer = timers.setTimeout(() => setStalled(true), STALL_TIMEOUT_MS);

    const onFailLoad = (event: WebviewDidFailLoadEvent) => {
      if (!event.isMainFrame || event.errorCode === -3) return;
      timers.clearTimeout(stallTimer);
      // A fact arriving after a guess: the guess was wrong (or overtaken), so withdraw it rather
      // than leave both true and ask `SiteWorkspace` to decide which one wins.
      setStalled(false);
      setFailed(true);
    };
    const onFinishLoad = () => {
      timers.clearTimeout(stallTimer);
      setFailed(false);
      setStalled(false);
      setLoaded(true);
    };

    guest.addEventListener('did-fail-load', onFailLoad);
    guest.addEventListener('did-finish-load', onFinishLoad);
    return () => {
      timers.clearTimeout(stallTimer);
      guest.removeEventListener('did-fail-load', onFailLoad);
      guest.removeEventListener('did-finish-load', onFinishLoad);
    };
    // `resetKey` as well as the node: a VIEW switch or a soft load navigates the guest that is
    // already mounted, so the node is unchanged and only this re-arms the stall timer for the new
    // navigation. A recovery remount changes both (`key` remounts the element).
  }, [guest, resetKey, timers]);

  return { failed, stalled, loaded, guest, guestRef: setGuest };
}

/**
 * Connects `WorkspaceChatPane` to the fleet chat transport: the bridge lookup, the transport built
 * on top of it, and the runtime-access and working-directory surfaces `ChatPane` needs. All three
 * are one bridge lookup, so they live in one hook rather than one per concern.
 */
export function useWorkspaceChatTransport(
  _required: Record<string, never> = {},
  { getBridge = runnerInventoryBridge }: { getBridge?: () => RunnerInventoryBridge | undefined } = {},
): {
  transport: WorkspaceChatTransport | undefined;
  runtimeAccess: ChatPaneRuntimeAccess | undefined;
  workingDirectoryAccess: ChatPaneWorkingDirectoryAccess | undefined;
  /** `undefined` only when the bridge itself is (no preload). See `RunnerInventoryBridge.getPathForFile`. */
  getPathForFile: ((file: File) => string) | undefined;
  /** `undefined` only when the bridge itself is. See `chat-attachments.ts`'s `createLocalAttachmentUploader`. */
  uploadAttachments: ChatPaneProps['uploadAttachments'];
} {
  const bridge = useMemo(() => getBridge(), [getBridge]);

  const runtimeAccess = useMemo<ChatPaneRuntimeAccess | undefined>(() => {
    if (bridge === undefined) return undefined;

    return {
      listAgents: bridge.listAgents,
      rescanAgents: bridge.rescanAgents,
      daemonOnline: bridge.daemonOnline,
    };
  }, [bridge]);

  const workingDirectoryAccess = useMemo<ChatPaneWorkingDirectoryAccess | undefined>(() => {
    if (bridge === undefined) return undefined;

    return {
      normalizeWorkingDirectory: bridge.normalizeWorkingDirectory,
      pickWorkingDirectory: bridge.pickWorkingDirectory,
      recentDirectories: bridge.recentWorkingDirectories,
      directoryExists: bridge.workingDirectoryExists,
    };
  }, [bridge]);

  // One transport per pane lifetime. It installs the single run-event listener every subscription
  // multiplexes over, so rebuilding it per render would stack duplicate listeners on that channel.
  const transport = useMemo(
    () => (bridge === undefined ? undefined : createWorkspaceChatTransport(bridge)),
    [bridge],
  );

  // The pane that uses this hook is unmounted, not hidden, when the operator closes it —
  // including mid-run. Without this the listener and every live subscription outlive the pane
  // that owned them.
  useEffect(() => () => transport?.dispose(), [transport]);

  // Runner has no HTTP server (`AGENTS.md`), so this is the IPC uploader
  // (`chat-attachments.ts`), not `@jini-ai/chat`'s daemon-backed one — see that module's doc.
  const uploadAttachments = useMemo(
    () => (bridge === undefined ? undefined : createLocalAttachmentUploader(bridge)),
    [bridge],
  );

  return {
    transport,
    runtimeAccess,
    workingDirectoryAccess,
    getPathForFile: bridge?.getPathForFile,
    uploadAttachments,
  };
}

export interface UseRunnerConversations {
  conversations: readonly WorkspaceConversationSummary[];
  activeId: string | null;
  /**
   * `ChatPane`'s `key`. Deliberately NOT `activeId`.
   *
   * `ChatPane` takes `initialMessages` only at MOUNT (`useConversation.ts`'s
   * `useState(options.initialMessages ?? [])`), so switching to a different conversation's
   * transcript means remounting the pane via a changed `key` — pushing new messages into a live
   * pane would fight its own state instead of replacing it. But `activeId` ALSO changes when an
   * untitled pane silently adopts a freshly created conversation mid-turn (see `onMessagesChange`
   * below), and re-keying on THAT would remount the pane out from under a reply it is currently
   * streaming. So the two stay separate: `paneKey` changes only on `select`/`create`/`remove`;
   * `activeId` tracks where the next write goes. Ported from Tovu admin's
   * `use-assistant-chats.hooks.ts`, which found this the hard way.
   */
  paneKey: string;
  /** Messages to seed the pane with. Changes identity only on a real conversation switch. */
  initialMessages: ChatMessage[];
  select: (id: string) => void;
  create: () => Promise<void>;
  remove: (id: string) => Promise<void>;
  rename: (id: string, title: string) => Promise<void>;
  /**
   * `ChatPane`'s `onMessagesChange`. Fires once on MOUNT with whatever `initialMessages` seeded it
   * with (`useChatPane.hooks.ts`'s effect on `conversation.messages`), so a fresh pane with nothing
   * selected calls this with `[]` at mount — `persistableMessages([]).length === 0` makes that a
   * no-op below, rather than mistaking a mount echo for new content to save.
   */
  onMessagesChange: (messages: ChatMessage[]) => void;
}

/**
 * Owns the fleet chat's persisted conversation threads: which one is open, what's in it, and
 * writing new turns back to Runner's own `runner_conversations`/`runner_conversation_messages`
 * tables over IPC (`fleet-conversation-store.ts`). Structurally mirrors Tovu admin's
 * `useAssistantChats` (`use-assistant-chats.hooks.ts`) — the same hook shape solving the same
 * problem — simplified for a local Sqlite-backed IPC call instead of a flaky HTTP one: no write
 * retry ladder, since a failed local write is not a transient network blip worth re-attempting on
 * a timer, just something to log and let the next delta re-queue.
 *
 * `activeIdRef` mirrors `activeId` state and is written at the point of decision (never from an
 * effect): `onMessagesChange` is called from INSIDE `ChatPane`'s own effect, a child component, and
 * React runs a child's effects before its parent's in the same commit — an effect here mirroring
 * `activeId` would still be reading the outgoing value the moment a delta from the newly-mounted
 * pane arrives. Same hazard `use-assistant-chats.hooks.ts`'s `activeIdRef`/`commitActiveId` documents.
 */
export function useRunnerConversations(
  _required: Record<string, never> = {},
  { getBridge = runnerInventoryBridge }: {
    getBridge?: BridgeLookup<'listConversations' | 'loadConversationMessages' | 'createConversation'
      | 'deleteConversation' | 'renameConversation' | 'saveConversationMessage'>;
  } = {},
): UseRunnerConversations {
  const bridge = useMemo(() => getBridge(), [getBridge]);

  const [conversations, setConversations] = useState<readonly WorkspaceConversationSummary[]>([]);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [paneKey, setPaneKey] = useState('new');
  const [initialMessages, setInitialMessages] = useState<ChatMessage[]>([]);
  const activeIdRef = useRef<string | null>(null);
  /** Message ids already saved, keyed by conversation — without this every delta would re-save the
   *  whole settled transcript, since the callback fires on each one and the settled prefix only grows. */
  const writtenRef = useRef<Map<string, Set<string>>>(new Map());
  /** Guards `select`/`create` against a slower one resolving after a faster, later one already won. */
  const switchSeqRef = useRef(0);
  /** In-flight lazy conversation creation, so concurrent deltas before it resolves adopt ONE conversation, not many. */
  const adoptingRef = useRef<Promise<string | null> | null>(null);
  /** Bumped whenever an in-flight adoption stops belonging to the pane that started it (a `select`/
   *  `create`/`remove` since). An adoption re-checks this before publishing `activeId`. */
  const adoptionGenRef = useRef(0);
  /** Makes each fresh, nothing-selected pane key distinct — `paneKey: 'new'` alone would fail to
   *  remount a pane that had lazily adopted (and is now having that same conversation deleted). */
  const paneNonceRef = useRef(0);
  /** Mirrors the last `conversations` this hook committed, for `remove`'s fallback when its own
   *  `refresh()` lands stale — see `refresh`'s own note. */
  const conversationsRef = useRef<readonly WorkspaceConversationSummary[]>([]);
  /** Conversations this hook deleted. The store refuses writes to them, so a message the old pane
   *  settles before `remove`'s follow-up `select` lands is dropped with the thread it belonged to. */
  const deletedRef = useRef(new Set<string>());
  useEffect(() => {
    conversationsRef.current = conversations;
  }, [conversations]);

  const resetAdoption = useCallback(() => {
    adoptingRef.current = null;
    adoptionGenRef.current += 1;
  }, []);

  const refresh = useCallback(async (): Promise<readonly WorkspaceConversationSummary[]> => {
    if (bridge === undefined) return conversationsRef.current;
    try {
      const list = await bridge.listConversations();
      setConversations(list);
      return list;
    } catch (err) {
      console.error('tovu-runner: could not load fleet chat conversations —', err);
      return conversationsRef.current;
    }
  }, [bridge]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  const commitActive = useCallback((id: string | null) => {
    activeIdRef.current = id;
    setActiveId(id);
  }, []);

  const select = useCallback(
    (id: string) => {
      if (bridge === undefined) return;
      const seq = ++switchSeqRef.current;
      const commit = (messages: ChatMessage[]) => {
        // A slower load for a conversation the operator has since navigated away from must not land.
        if (switchSeqRef.current !== seq) return;
        writtenRef.current.set(id, new Set(messages.map((m) => m.id)));
        setInitialMessages(messages);
        commitActive(id);
        // A deliberate switch is exactly when remounting the pane IS the intent.
        setPaneKey(id);
        resetAdoption();
      };
      void bridge
        .loadConversationMessages(id)
        .then(commit)
        // A failed load still switches, to an empty pane — leaving the operator on the previous
        // conversation while the switcher already says otherwise is the worse of the two failures.
        .catch((err) => {
          console.error(`tovu-runner: could not load fleet chat conversation ${id} —`, err);
          commit([]);
        });
    },
    [bridge, commitActive, resetAdoption],
  );

  const create = useCallback(async () => {
    if (bridge === undefined) return;
    // Claimed BEFORE the request and re-checked after, so a selection made after the click (while
    // the create is still in flight) wins rather than yanking the operator back into a new, empty
    // pane the moment the slower create resolves.
    const seq = ++switchSeqRef.current;
    const conversation = await bridge.createConversation();
    setConversations((current) => [conversation, ...current]);
    if (switchSeqRef.current !== seq) return;
    commitActive(conversation.id);
    setInitialMessages([]);
    setPaneKey(conversation.id);
    writtenRef.current.set(conversation.id, new Set());
    resetAdoption();
  }, [bridge, commitActive, resetAdoption]);

  const remove = useCallback(
    async (id: string) => {
      if (bridge === undefined) return;
      await bridge.deleteConversation(id);
      writtenRef.current.delete(id);
      deletedRef.current.add(id);
      // The delete succeeded, so the thread leaves the switcher now — and is filtered out of what
      // `refresh` returns, whose failure fallback is the list still on screen (deleted row included).
      setConversations((current) => current.filter((c) => c.id !== id));
      const list = (await refresh()).filter((c) => c.id !== id);
      if (activeIdRef.current !== id) return;
      const next = list[0]?.id ?? null;
      if (next === null) {
        // Nothing left to land on. Bump the token so a switch already in flight cannot resurrect a
        // transcript into what is about to become an empty pane.
        switchSeqRef.current += 1;
        commitActive(null);
        setInitialMessages([]);
        paneNonceRef.current += 1;
        setPaneKey(`new-${paneNonceRef.current}`);
        // This is the one place `activeId` goes back to `null`, which is the only state that
        // re-enters the lazy-adoption path below — without this reset, the fresh pane would
        // inherit the deleted conversation's adoption and never persist again.
        resetAdoption();
        return;
      }
      // `select`, deliberately, not a raw `setActiveId(next)` — see `select`'s own doc: only
      // `select` publishes id, transcript and written-ids together, in the order that keeps a
      // remount from ever showing an empty pane under a non-empty switcher entry.
      select(next);
    },
    [bridge, refresh, commitActive, resetAdoption, select],
  );

  const rename = useCallback(
    async (id: string, title: string) => {
      if (bridge === undefined) return;
      // Optimistic: a rename that only appears after a round trip feels broken mid-edit.
      setConversations((current) => current.map((c) => (c.id === id ? { ...c, title } : c)));
      try {
        await bridge.renameConversation({ id, title });
      } catch (err) {
        console.error(`tovu-runner: could not rename fleet chat conversation ${id} —`, err);
      }
      void refresh();
    },
    [bridge, refresh],
  );

  /** Writes whatever in `messages` has settled and is not already stored, into `conversationId`. */
  const flush = useCallback(
    (conversationId: string, messages: ChatMessage[]) => {
      if (bridge === undefined || deletedRef.current.has(conversationId)) return;
      // Always registered by now: every id that can reach here got its set when it became flushable
      // — `select`'s commit, `create` and lazy adoption each register one before `activeId` (or the
      // adoption's own flush) can name it — and `remove` drops a set only after marking the id
      // deleted, which the guard above returns on first. (This used to fall back to a fresh set,
      // which no path could reach.)
      const written = writtenRef.current.get(conversationId) as Set<string>;
      const pending = persistableMessages(messages).filter((m) => !written.has(m.id));
      if (pending.length === 0) return;
      // Marked before the request resolves so a second `onMessagesChange` arriving mid-flight —
      // which it will, since deltas keep coming — does not queue the same message twice.
      for (const message of pending) written.add(message.id);
      for (const message of pending) {
        void bridge.saveConversationMessage({ conversationId, message }).catch((err) => {
          console.error('tovu-runner: could not persist a fleet chat message —', err);
          // Un-marked so a later delta gets one more chance, rather than a single failed write
          // silently dropping this message from the durable transcript forever.
          written.delete(message.id);
        });
      }
      // The first turn is what gives an untitled conversation its auto-generated title, and every
      // turn changes `messageCount`/`updatedAt` — re-read rather than patch, so the switcher stays
      // honest without this hook re-deriving the store's own title/ordering rules.
      void refresh();
    },
    [bridge, refresh],
  );

  const onMessagesChange = useCallback(
    (messages: ChatMessage[]) => {
      const conversationId = activeIdRef.current;
      if (conversationId !== null) {
        flush(conversationId, messages);
        return;
      }

      // No conversation is active — the DEFAULT state, not an edge case: nothing selects one on
      // mount, so typing straight into a freshly opened fleet chat (without first clicking "New" or
      // picking from history) lands here. Adopt one lazily, at the first moment there is actually
      // something worth saving, rather than littering the switcher with an empty row per app open.
      if (bridge === undefined || persistableMessages(messages).length === 0) return;

      const generation = adoptionGenRef.current;
      // Claimed only if nothing is already in flight, so two deltas arriving before the create
      // resolves await the SAME creation, not two. (Not `adoptingRef.current ??= …` — Biome's
      // `noAssignInExpressions` refuses an assignment inside the expression that reads it back.)
      if (adoptingRef.current === null) {
        adoptingRef.current = bridge
          .createConversation()
          .then((conversation) => {
            setConversations((current) => [conversation, ...current]);
            writtenRef.current.set(conversation.id, new Set());
            // Superseded: the row exists and shows up in the switcher, but the pane that asked for
            // it is gone (the operator switched away while this was in flight) — pointing
            // `activeId` at it now would route the NEXT pane's writes here. The flush below still
            // runs regardless: these messages came from the pane that asked for this conversation,
            // and dropping them would be exactly the data loss lazy adoption exists to prevent.
            if (adoptionGenRef.current === generation) commitActive(conversation.id);
            return conversation.id;
          })
          .catch((err) => {
            console.error('tovu-runner: could not create a fleet chat conversation —', err);
            return null;
          });
      }
      const adoption = adoptingRef.current;

      void adoption.then((id) => {
        if (id === null) {
          // Cleared so a later turn can retry — leaving a rejected promise in place would wedge
          // persistence for the rest of the session.
          if (adoptingRef.current === adoption) adoptingRef.current = null;
          return;
        }
        flush(id, messages);
      });
    },
    [bridge, flush, commitActive],
  );

  return { conversations, activeId, paneKey, initialMessages, select, create, remove, rename, onMessagesChange };
}

export interface ConversationDeleteConfirmationState {
  /** The title of the conversation currently asking to be confirmed, or `null` when nothing is
   *  pending. Falls back to `'Untitled'` the same way `ConversationList` itself does. */
  pendingTitle: string | null;
  /**
   * `ConversationList`'s `confirmDelete` prop. Deliberately NOT `window.confirm` — this repo has
   * already paid for that lesson once, for project delete: a native modal blocks the whole
   * renderer, and in Electron that also freezes the IPC this window answers on (see
   * `useDeleteConfirmation`'s doc above). This returns a promise that resolves only when the
   * operator answers the inline confirmation `WorkspaceChatPane` renders from `pendingTitle`.
   */
  confirmDelete: (item: ConversationListItem) => Promise<boolean>;
  /** Answers the pending confirmation, if any. A no-op when nothing is pending. */
  resolvePending: (confirmed: boolean) => void;
}

/**
 * The fleet chat's conversation-delete confirmation. `ConversationList` (`@jini-ai/chat/react`)
 * accepts a `confirmDelete` callback returning `boolean | Promise<boolean>` for exactly this
 * purpose — ours resolves it from a real operator click on `WorkspaceChatPane`'s own inline banner
 * rather than from a blocking native dialog. See commit `204f3e6` ("require operator confirmation
 * for project delete") for the precedent this follows.
 */
export function useConversationDeleteConfirmation(): ConversationDeleteConfirmationState {
  const resolverRef = useRef<((confirmed: boolean) => void) | null>(null);
  const [pendingTitle, setPendingTitle] = useState<string | null>(null);

  const confirmDelete = useCallback((item: ConversationListItem): Promise<boolean> => {
    return new Promise<boolean>((resolve) => {
      // An unresolved earlier prompt loses to a newer one rather than leaving two pending — the
      // operator can only be looking at (and answering) one banner at a time.
      resolverRef.current?.(false);
      resolverRef.current = resolve;
      setPendingTitle(item.title ?? 'Untitled');
    });
  }, []);

  const resolvePending = useCallback((confirmed: boolean) => {
    resolverRef.current?.(confirmed);
    resolverRef.current = null;
    setPendingTitle(null);
  }, []);

  return { pendingTitle, confirmDelete, resolvePending };
}

function refValue(ref: RefObject<HTMLInputElement | null>): string {
  return ref.current?.value ?? '';
}

/** Pure — no React/DOM dependency, so this is unit-testable on its own. */
export function computeCanCreate(input: {
  slug: string;
  database: DatabaseProviderKind;
  supabaseReady: boolean;
  customReady: boolean;
}): boolean {
  if (input.slug.length === 0) return false;
  if (input.database === 'sqlite') return true;
  return input.database === 'supabase' ? input.supabaseReady : input.customReady;
}

/** Select and trim only the selected database's endpoint; SQLite has none.
 * Pure: no side effects or errors. Time and space are O(n) in the chosen endpoint's length.
 */
function createProjectDatabaseEndpoint(input: {
  database: DatabaseProviderKind;
  supabaseUrl: string;
  customConnection: string;
}, _options = {}): string | undefined {
  return input.database === 'supabase'
    ? input.supabaseUrl.trim()
    : input.database === 'custom'
      ? input.customConnection.trim()
      : undefined;
}

/** Pure — takes every value it needs as an explicit argument rather than closing over component
 *  state, so the submit handler that calls it stays a thin orchestrator. */
export function buildCreateProjectInput(input: {
  displayName: string;
  database: DatabaseProviderKind;
  customProviderLabel: string;
  supabaseUrl: string;
  customConnection: string;
  supabaseKey: string;
  customCredential: string;
}): CreateSiteInput {
  const endpoint = createProjectDatabaseEndpoint(input);
  const credentialValue =
    input.database === 'supabase' ? input.supabaseKey : input.database === 'custom' ? input.customCredential : '';

  return {
    displayName: input.displayName,
    database: {
      kind: input.database,
      ...(input.database === 'custom' && input.customProviderLabel.trim() ? { label: input.customProviderLabel.trim() } : {}),
      ...(endpoint ? { endpoint } : {}),
      ...(credentialValue ? { credential: credentialValue } : {}),
    },
  };
}

/**
 * The typed website name reduced to a compact identifier, read by {@link computeCanCreate}
 * as "a name has been entered". The form describes the actual chosen-folder behaviour separately.
 *
 * Unicode-aware by necessity, not by preference. The original `[^a-z0-9]+` deleted every character
 * of a name written in any non-Latin script, so the slug came back empty and `computeCanCreate`
 * refused to enable "Create website": there was no name an operator could type in Japanese, Hindi,
 * Greek, Cyrillic or Arabic that this form would accept at all. It also mangled accented Latin
 * names — `Café Münster` was previewed back as `caf-m-nster`.
 *
 * `\p{M}` is in the keep-set alongside letters and numbers because several scripts write their
 * vowels as combining marks rather than letters; without it `हिन्दी` splits into separator-joined
 * fragments. Anything else still collapses to a separator, so a name with no letters or digits in
 * it (`"!!!"`, whitespace) still yields `''` — the signal the create gate depends on.
 *
 * @complexity O(n) in name length.
 */
export function siteSlug(name: string): string {
  return name
    .trim()
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\p{M}]+/gu, '-')
    .replace(/^-+|-+$/g, '');
}

export interface CreateWebsiteFormState {
  name: string;
  setName: Dispatch<SetStateAction<string>>;
  database: DatabaseProviderKind;
  setDatabase: Dispatch<SetStateAction<DatabaseProviderKind>>;
  supabaseUrl: string;
  setSupabaseUrl: Dispatch<SetStateAction<string>>;
  setHasSupabaseKey: Dispatch<SetStateAction<boolean>>;
  customProvider: string;
  setCustomProvider: Dispatch<SetStateAction<string>>;
  customConnection: string;
  setCustomConnection: Dispatch<SetStateAction<string>>;
  setHasCustomCredential: Dispatch<SetStateAction<boolean>>;
  supabaseKeyRef: RefObject<HTMLInputElement | null>;
  customCredentialRef: RefObject<HTMLInputElement | null>;
  slug: string;
  canCreate: boolean;
  isSubmitting: boolean;
  formError: string | null;
  nameError?: string | null;
  handleSubmit: (event: FormEvent<HTMLFormElement>) => void;
}

/**
 * The create-website onboarding form: every field, its derived validity, and submission.
 *
 * `hasSupabaseKey`/`hasCustomCredential` track only whether a secret was typed, never the secret
 * itself — the two password inputs stay uncontrolled (`supabaseKeyRef`/`customCredentialRef`) so
 * React holds no copy of a credential anywhere in state or a re-render.
 */
export function useCreateWebsiteForm(
  onCreate: (input: CreateSiteInput) => Promise<void>,
): CreateWebsiteFormState {
  const [name, setName] = useState('');
  const [database, setDatabase] = useState<DatabaseProviderKind>('sqlite');
  const [supabaseUrl, setSupabaseUrl] = useState('');
  const [hasSupabaseKey, setHasSupabaseKey] = useState(false);
  const [customProvider, setCustomProvider] = useState('');
  const [customConnection, setCustomConnection] = useState('');
  // Tracked but not read below — see the parity note on `hasSupabaseKey`. A custom provider's
  // credential is optional (the form says so), so `customReady` never gates on it; kept as state
  // so a future required-credential provider has somewhere to plug in without a new field.
  const [hasCustomCredential, setHasCustomCredential] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);
  const supabaseKeyRef = useRef<HTMLInputElement>(null);
  const customCredentialRef = useRef<HTMLInputElement>(null);
  const slug = siteSlug(name);
  const supabaseReady = supabaseUrl.trim().length > 0 && hasSupabaseKey;
  const customReady = customProvider.trim().length > 0 && customConnection.trim().length > 0;
  const nameError = name.length > 0 ? siteNameError({ name }) : null;
  const canCreate = siteNameError({ name }) === null && computeCanCreate({ slug, database, supabaseReady, customReady });

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (siteNameError({ name })) { setFormError(SITE_NAME_ERROR); return; }
    if (!canCreate || isSubmitting) return;

    const input = buildCreateProjectInput({
      displayName: name,
      database,
      customProviderLabel: customProvider,
      supabaseUrl,
      customConnection,
      supabaseKey: refValue(supabaseKeyRef),
      customCredential: refValue(customCredentialRef),
    });
    // Cleared immediately, before the async call, so the DOM never holds the
    // secret longer than it takes to read it — even if the submit fails.
    if (supabaseKeyRef.current) supabaseKeyRef.current.value = '';
    if (customCredentialRef.current) customCredentialRef.current.value = '';

    setFormError(null);
    setIsSubmitting(true);
    try {
      await onCreate(input);
    } catch (error) {
      setFormError(humanSiteError({ error, fallback: 'Could not create website.' }));
    } finally {
      setIsSubmitting(false);
    }
  };

  return {
    name,
    setName,
    database,
    setDatabase,
    supabaseUrl,
    setSupabaseUrl,
    setHasSupabaseKey,
    customProvider,
    setCustomProvider,
    customConnection,
    setCustomConnection,
    setHasCustomCredential,
    supabaseKeyRef,
    customCredentialRef,
    slug,
    canCreate,
    isSubmitting,
    formError,
    nameError,
    handleSubmit,
  };
}

/** Derive root chrome and guest targets from the existing sites-home view.
 * Re-adding a tracked site opens its tab; folder failures stay on the websites view.
 * @param input The current sites-home view and the Add result notice.
 * @returns Chrome selection, the shared Find/Zoom target, and this tab's notice.
 * @complexity O(1) time and space.
 */
export function appPresentation(
  { showSiteTab, showSitesHome, appearanceOpen, activeTab, visibleWorkspaceId, addNotice }: {
    showSiteTab: boolean; showSitesHome: boolean; appearanceOpen: boolean;
    activeTab: string | null; visibleWorkspaceId: string | null;
    addNotice: { siteId: string; message: string } | null;
  }, _options = {},
): { onSitesHome: boolean; selectedTab: string | null; guestTarget: string | null; tabNotice: string | undefined } {
  return {
    onSitesHome: showSitesHome && !appearanceOpen,
    selectedTab: showSiteTab ? activeTab : null,
    guestTarget: showSiteTab ? visibleWorkspaceId : null,
    tabNotice: showSiteTab && addNotice?.siteId === activeTab ? addNotice.message : undefined,
  };
}

