/** Metadata-only Shared Keys state. Secrets are passed through once and never enter React state. */
import { useCallback, useEffect, useRef, useState } from 'react';
import type { LegacyImportReport, OwnerStoreBridge, OwnerStoreEntry, OwnerStoreReply } from '../contracts/owner-store.js';
import { ownerStoreBridge } from './runner-api.js';

const FAILED = 'The shared-key operation failed. Refresh and try again.';

/** Fixed copy ignores arbitrary reply/transport messages that might contain submitted secrets.
 * @complexity O(1); no effects.
 */
function failureText({ code }: { code: string }, _options = {}): string {
  const messages: Record<string, string> = {
    'recovery-required': 'The older key store needs its original owner.key. Restore it, or import a backup.',
    'invalid-backup': 'Check the encrypted backup and passphrase.',
    conflict: 'This key changed. Refresh before replacing it.',
    cancelled: 'The import was cancelled.',
    timeout: 'The operation timed out. Refresh before retrying.',
  };
  return messages[code] ?? FAILED;
}

/** Import feedback counts the report; sites never change, so their copies are only mentioned.
 * @complexity O(i) for i report items; no effects or payload reads.
 */
function importText({ report }: { report: LegacyImportReport }, _options = {}): string {
  const imported = report.items.filter(item => item.status === 'imported').length;
  if (!report.applied || imported === 0) return 'Nothing new to import.';
  const keys = `Imported ${imported} key${imported === 1 ? '' : 's'}.`;
  return report.pending.length ? `${keys} Sites that had copies keep them.` : keys;
}

/** Fixed copy per action; a save never claims any site uses or received the key.
 * @complexity O(i) for an import report; O(1) otherwise.
 */
function successText({ reply }: { reply: Extract<OwnerStoreReply, { ok: true }> }, _options = {}): string {
  if (reply.action === 'import') return importText({ report: reply.data as LegacyImportReport });
  return reply.action === 'put' ? 'Saved to your project. Site usage is unavailable in this version.' : 'Done.';
}

/** One inventory read per open/refresh; one in-flight action, including refresh after mutations.
 * @param input Explicit renderer bridge; undefined handles stale preloads without IPC.
 * @returns Metadata, fixed feedback and an action runner. No secret or passphrase is retained.
 * @complexity O(e) inventory memory for e entries; one bounded main-process request at a time.
 * @example useSharedKeys({ bridge: ownerStoreBridge({}) }, {})
 */
export function useSharedKeys({ bridge = ownerStoreBridge({}) }: { bridge?: OwnerStoreBridge } = {}, _options = {}) {
  const [entries, setEntries] = useState<OwnerStoreEntry[]>([]);
  const [loaded, setLoaded] = useState(false);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const pending = useRef(false);
  const mounted = useRef(false);

  /** Metadata refresh errors withdraw the inventory so stale revisions cannot be replaced. */
  const read = useCallback(async () => {
    if (!bridge) return;
    const reply = await bridge.list({ store: 'project' }, {});
    if (!mounted.current) return;
    if (!reply.ok) {
      setEntries([]); setLoaded(false); setError(failureText({ code: reply.error.code })); return;
    }
    setEntries(reply.data.entries); setLoaded(true);
  }, [bridge]);

  /** Ref guard closes the same-render double-click gap; opaque throws never reach UI/logs. */
  const run = useCallback(async ({ action }: { action?: () => Promise<OwnerStoreReply> } = {}, _options = {}) => {
    function applyActionReply({ reply }: { reply: OwnerStoreReply }, _options = {}): boolean {
      if (!mounted.current) return false;
      if (!reply.ok) { setError(failureText({ code: reply.error.code })); return false; }
      setMessage(successText({ reply }));
      return true;
    }
    if (!bridge || pending.current) return;
    pending.current = true;
    setBusy(true); setError(''); setMessage('');
    try {
      if (action) {
        if (!applyActionReply({ reply: await action() })) return;
      }
      await read();
    } catch {
      if (mounted.current) { setEntries([]); setLoaded(false); setError(FAILED); }
    } finally {
      pending.current = false;
      if (mounted.current) setBusy(false);
    }
  }, [bridge, read]);

  useEffect(() => {
    mounted.current = true;
    void run();
    return () => { mounted.current = false; };
  }, [run]);
  return { entries, loaded, busy, message, error, available: bridge !== undefined, run };
}

import { namePasteHandler } from '../contracts/site-name.js';
/**
 * The site grid: one card per website, and each card's inline delete-confirm overlay. Split out
 * of `App.tsx` as its own module — this family has a small, self-contained props surface
 * (`projects`, `onOpen`, `onDelete`) and no dependency on anything else `App.tsx` renders, which is
 * what makes it a real ownership boundary rather than just a line-count split.
 *
 * **The dashed add-tile that used to lead this grid is gone, and it was redundant rather than
 * merely surplus.** Its `onClick` was the same zero-argument `openCreateWebsite` the header's
 * primary button already calls — the identical handler, from the identical props chain — so the two
 * controls did exactly one thing between them. Its subtitle described the CREATE path too, which
 * made it read as a third, distinct option when it was really a duplicate of one. The header row is
 * now the single place those actions live: Rescan, then add-an-existing-website, then create.
 *
 * The tile was also the de-facto empty state, so removing it alone would have left an operator with
 * no websites looking at nothing at all. `ProjectsBody` (`App.tsx`) renders an explicit empty state
 * instead — this grid is only ever asked to draw cards.
 *
 * **Every action a card carries is always visible in the card body**, not overlaid on the preview
 * image and not revealed by hover. The ⋮ and the trash used to sit on the
 * screenshot and appear on hover; an operator could not see what a card could do without pointing at
 * it, and on a touchpad or by keyboard that is a control you have to go looking for.
 *
 * The layout is the owner's, after four rounds: the ⋮ level with the site name at the card's right
 * edge, "SQLite" under the name and the status ("● Stopped") under the ⋮, then Start/Stop on its
 * own row at the left with Restart on that same row at the right edge. So the body is two rows —
 * `.card__head` (a 2x2 grid: name | ⋮, SQLite | status) and `CardActions` (the labelled buttons) —
 * which is what lets the ⋮ share a line with the name without either one being positioned on top of
 * the other. (Before 2026-10-06 Start/Stop and Restart were stacked under the ⋮ in a right-hand
 * column, and the status sat on its own line under the name.)
 *
 * **The right-hand side carries exactly one icon control: the ⋮ menu.** Delete used to be its own
 * always-visible trash button beside Start/Stop; the owner's own reason for pulling it inside the
 * menu is misclicks — a destructive control next to a button pressed often is too easy to hit by
 * accident. It is a `role="menuitem"` in `SiteCardMenu` now, and it still opens the exact same
 * confirm overlay before anything happens. Start/Stop stays the lifecycle and the one labelled
 * button, wearing `.button--create` — the header's "Create website" style — on the owner's own
 * request, so the app's two ways to bring a site up read as one family rather than two different
 * looks. Nothing is reachable two ways, which is the rule that keeps the column readable as it
 * grows.
 */
import { useDeleteConfirmation, useDismissibleDropdown } from './App.hooks.js';
import { useSiteRename, renameInputKeyDown, showsInvalidNameHint } from './use-site-rename.hooks.js';
import { useSiteActions } from './use-site-actions.hooks.js';
import { codeSpans, externalStopConfirm, powerControl, useSitePower } from './use-site-power.hooks.js';
import { useSiteLocate } from './use-site-locate.hooks.js';
import { useSitePreview } from './use-site-preview.hooks.js';
import { cardOpenClass, cardOpenProps, cardOverlay, closeMenuThen, databaseLabel, deleteActionCopy, isCardOpenable, type CardOverlayMode, type DeleteActionCopy } from './SiteGrid.hooks.js';
import { STATUS_LABEL } from './site-status.js';
import { siteCardStatus, sitePortPresentation } from './site-port.rules.js';
import type { SiteRecord } from '../contracts/project.js';
import type { SiteRenameState } from './use-site-rename.hooks.js';
import type { SiteActions } from './use-site-actions.hooks.js';
import type { SitePower } from './use-site-power.hooks.js';
import type { SiteLocate } from './use-site-locate.hooks.js';
import { ResourceSiteFigure } from './ResourcesPanel.js';

/**
 * `useDeleteState` is the delete-confirm hook itself, defaulted to the real one — the function,
 * never its result. Written as `useDeleteState = useDeleteConfirmation(onDelete)` it would only
 * run when a caller omitted the prop, so hook order would vary by call site; as written it is
 * called unconditionally below and the order is fixed.
 *
 * Worth injecting here because this grid has three visually distinct states — idle, confirming,
 * and deleting-with-an-error — and only the first is reachable without driving an async delete to
 * completion. A stub renders any of them directly. `typeof useDeleteConfirmation` is the type on
 * purpose: a stub that forgets `deletingId`, or takes no `onDelete`, fails `npm run typecheck`.
 *
 * The private components below (`SiteCard`, `CardConfirmOverlay`) take no hooks of their own
 * and are not exported, so there is nothing to inject into them and no way for a test to mount
 * them directly — they are exercised through this grid, which is the boundary that owns them.
 */
export function SiteGrid({
  projects,
  onOpen,
  onDelete,
  onRenamed,
  onSiteUpdated,
  useDeleteState = useDeleteConfirmation,
  useRenameState = useSiteRename,
  useActions = useSiteActions,
  usePower = useSitePower,
  useLocate = useSiteLocate,
  usePreview = useSitePreview,
}: {
  projects: readonly SiteRecord[];
  onOpen: (id: string) => void;
  onDelete: (id: string) => Promise<void>;
  /** Called with main's refreshed record after a rename, so the caller can refresh its list. */
  onRenamed?: (record: SiteRecord) => void;
  /** Called with main's refreshed record after a start or a stop, for the same reason `onRenamed`
   *  exists: the 4s poll would get there eventually, and "eventually" is up to four seconds of a
   *  stopped site still reading `Running`. See `use-site-power.hooks.ts`. */
  onSiteUpdated?: (record: SiteRecord, previousId?: string) => void;
  useDeleteState?: typeof useDeleteConfirmation;
  useRenameState?: typeof useSiteRename;
  /** The ⋮ menu's Open-in-browser implementation. Injectable for the same reason `useDeleteState`
   *  is — see `use-site-actions.hooks.ts` on why it calls the bridge directly rather than arriving
   *  as a prop from `App.tsx`. */
  useActions?: typeof useSiteActions;
  /** The card's Start/Stop. Injectable for the same reason, and the one a test reaches for to
   *  render a mid-transition card without driving a real site's boot. */
  usePower?: typeof useSitePower;
  /** A missing-folder card's Locate. Injectable for the same reason as the others. */
  useLocate?: typeof useSiteLocate;
  /** Each card's preview-capture URL. Defaults to the bridge-backed `useSitePreview`; injectable for
   *  the same reason as the others, so a test can render a card with a capture. */
  usePreview?: typeof useSitePreview;
}) {
  const { pendingId, deletingId, deleteError, requestDelete, cancelDelete, confirmDelete } =
    useDeleteState(onDelete);
  const rename = useRenameState(onRenamed);
  const actions = useActions();
  // Start opens the site once it is running, through the very `onOpen` a card click calls — see
  // `runPowerToggle`.
  const power = usePower(onSiteUpdated, { onStarted: onOpen });
  const locate = useLocate(onSiteUpdated);
  // A name is a label, never site identity. Keep unrelated cards and expose their parent paths.
  const seenNames = new Set<string>();
  const duplicateNames = new Set<string>();
  for (const project of projects) {
    if (seenNames.has(project.displayName)) duplicateNames.add(project.displayName);
    seenNames.add(project.displayName);
  }

  return (
    <div className="grid">
      {projects.map((project) => (
        <SiteCard
          key={project.id}
          project={project}
          showParent={duplicateNames.has(project.displayName)}
          overlay={cardOverlay(project.id, pendingId, rename.renamingId, power.confirmingStopId ?? null)}
          deleting={deletingId === project.id}
          deleteError={deleteError}
          rename={rename}
          onOpen={onOpen}
          actions={actions}
          power={power}
          locate={locate}
          onRequestDelete={requestDelete}
          onCancelDelete={cancelDelete}
          onConfirmDelete={confirmDelete}
          usePreview={usePreview}
        />
      ))}
    </div>
  );
}

function SiteCard({
  project,
  showParent,
  overlay,
  deleting,
  deleteError,
  rename,
  onOpen,
  actions,
  power,
  locate,
  onRequestDelete,
  onCancelDelete,
  onConfirmDelete,
  usePreview = useSitePreview,
}: {
  project: SiteRecord;
  showParent: boolean;
  overlay: CardOverlayMode;
  deleting: boolean;
  deleteError: string | null;
  rename: SiteRenameState;
  onOpen: (id: string) => void;
  actions: SiteActions;
  power: SitePower;
  locate: SiteLocate;
  onRequestDelete: (id: string) => void;
  onCancelDelete: () => void;
  onConfirmDelete: (id: string) => Promise<void>;
  usePreview?: typeof useSitePreview;
}) {
  // ANY overlay makes the card inert, which is why the two are one value rather than two booleans:
  // the click that commits or dismisses an overlay must not also open the site underneath it, and
  // that is true of the rename form for exactly the reason it is true of the delete confirmation.
  const openable = isCardOpenable(project, overlay !== null);
  // All five open-affordance attributes from one decision — see `cardOpenProps`.
  const openProps = cardOpenProps(openable, () => onOpen(project.id));
  // What this card's destructive control means for THIS project — a delete that erases the folder,
  // or a removal that only drops the card. See `deleteActionCopy`'s own doc on why one word for
  // both would be a lie in whichever direction the operator happened to read it.
  const copy = deleteActionCopy(project);
  // `null` until main has actually captured this site once (or the fetch is still in flight) — see
  // `use-site-preview.hooks.ts`.
  const previewUrl = usePreview({ id: project.id, previewVersion: project.previewVersion });
  // The polled status, or the transition THIS window started and is still waiting on — see
  // `use-site-power.hooks.ts` on why the local half exists and why it is never the whole answer.
  const status = power.statusOf(project);
  const powerError = power.errorOf(project.id);
  const connection = sitePortPresentation({ port: project.port, status });
  const statusCopy = siteCardStatus({ project, connection });
  const parentFolder = project.installDir.replace(/[\\/]+[^\\/]+[\\/]*$/, "") || "/";

  return (
    <article className={`card is-${status} ${cardOpenClass({ openable })}`} {...openProps}>
      <div className="card__tile">
        {/* A capture exists once main has seen this site running, in this app or another one, this
            run or a prior one. Until then — and as the fallback if a capture failed — the tile is a
            neutral placeholder, never the port: owner 2026-10-13, "shouldn't I see a preview of the
            actual site where it says 3000?" The address lives in the status line's title. The tile's
            fixed aspect ratio means the image landing causes no layout jump. See
            `use-site-preview.hooks.ts` and `site-preview-store.ts` for why the record carries only a
            version token, never bytes. */}
        {previewUrl ? (
          <img className="card__preview" src={previewUrl} alt="" />
        ) : (
          <svg className="card__placeholder" viewBox="0 0 48 36" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true">
            <rect x="1" y="1" width="46" height="34" rx="4" />
            <path d="M1 9h46M7 5h.01M11 5h.01M15 5h.01M9 17h30M9 23h20" strokeLinecap="round" />
          </svg>
        )}
      </div>
      <div className="card__body">
        {/* The head is a 2x2 grid (`.card__head`): name | ⋮ on row 1, "SQLite" | status on row 2.
            Grid auto-placement fills it in DOM order, so the order below IS the layout — and it is
            also the reading and Tab order, which is why the ⋮ comes second rather than last. */}
        <div className="card__head">
          <div className="card__namewrap">
            <h3 className="card__name" title={project.displayName}>{project.displayName}</h3>
            {showParent && <p className="card__parent" title={project.installDir}>{parentFolder}</p>}
          </div>
          {/* The inline panel owns the card; its actions must not share space with the menu trigger. */}
          {overlay === null && <SiteCardMenu
            project={project}
            status={status}
            copy={copy}
            onRename={() => rename.startRename(project)}
            onRequestDelete={onRequestDelete}
            actions={actions}
          />}
          <p className="card__details">
            {databaseLabel(project)}
            {project.templateVersion && <> · Tovu {project.templateVersion}</>}
          </p>
          <p className="card__meta">
            <span className="state" title={statusCopy.title}>
              <span className="state__dot" aria-hidden="true" />
              {STATUS_LABEL[status]}
            </span>
          </p>
          {/* Everything below spans both columns (`grid-column: 1 / -1`). The failure reason left the
              status line when the status moved into the narrow right column: unbounded text there
              would squeeze the name's column to nothing. "Running in Web (port N)" is not shown here
              any more — it moved into the status's title; see `siteCardStatus`. */}
          {statusCopy.detail && (
            <p className="card__detail" title={statusCopy.detail}>
              {statusCopy.detail}
            </p>
          )}
          {project.status === 'provisioning' && <span className="card__draft">Provisioning setup</span>}
          {/* Main's own sentence, verbatim, when a start or a stop was refused. In the body rather
              than an overlay: nothing is pending, the card is still openable, and the failure is one
              fact about it rather than a question to answer. */}
          {powerError && <p className="card__actionerror">{powerError}</p>}
          <ResourceSiteFigure project={project} />
          <MissingFolderNotice project={project} locate={locate} />
        </div>
        <CardActions
          project={project}
          status={status}
          power={power}
          locate={locate}
          onRequestDelete={onRequestDelete}
        />
      </div>

      <CardOverlays
        project={project}
        overlay={overlay}
        rename={rename}
        copy={copy}
        deleting={deleting}
        deleteError={deleteError}
        power={power}
        onCancelDelete={onCancelDelete}
        onConfirmDelete={onConfirmDelete}
      />
    </article>
  );
}

/** Inline card panels share the same inert-card boundary and add no wrapper to the DOM. */
function CardOverlays({ project, overlay, rename, copy, deleting, deleteError, power, onCancelDelete, onConfirmDelete }: {
  project: SiteRecord;
  overlay: CardOverlayMode;
  rename: SiteRenameState;
  copy: DeleteActionCopy;
  deleting: boolean;
  deleteError: string | null;
  power: SitePower;
  onCancelDelete: () => void;
  onConfirmDelete: (id: string) => Promise<void>;
}, _options = {}) {
  return <>
    {overlay === 'rename' && <CardRenameOverlay project={project} rename={rename} />}
    {overlay === 'confirm' && (
      <CardConfirmOverlay
        project={project}
        copy={copy}
        busy={deleting}
        error={deleteError}
        onCancel={onCancelDelete}
        onConfirm={onConfirmDelete}
      />
    )}
    {/* Stop for a site another process serves (`npm run dev`) — owner 2026-10-13. The overlay
        closes on confirm; the card's own button then reads "Stopping…" and any refusal shows
        on the card's error line, exactly as an ordinary Stop's does. */}
    {overlay === 'stop' && (
      <CardConfirmOverlay
        project={project}
        copy={externalStopConfirm({ project }) ?? copy}
        busy={false}
        error={null}
        onCancel={() => power.cancelStop?.()}
        onConfirm={async () => power.confirmStop?.(project)}
      />
    )}
  </>;
}

/**
 * The body lines of a card whose folder is gone. Only for a folder main could not find on its own —
 * every rename it can prove it has already healed (`site-relocation.ts`). Locate / Remove sit in the
 * action column; a refused Locate's reason, main's own sentence, shows here.
 */
function MissingFolderNotice({ project, locate }: { project: SiteRecord; locate: SiteLocate }) {
  const error = locate.errorOf(project.id);
  return (
    <>
      {project.folderMissing && <p className="card__missing">Folder moved or not a site</p>}
      {error && <p className="card__actionerror">{error}</p>}
    </>
  );
}

/**
 * `role="group"` rather than left as a static `<div>`: this element carries its own click/keydown
 * handlers (to stop them bubbling — see below), and a static element with interactive handlers is
 * exactly what `noStaticElementInteractions` flags. A group of controls is what this actually is,
 * so the role also tells assistive tech the truth about it, not only the linter.
 *
 * Stops both handlers rather than only onClick: the card is a keyboard-activated open target too,
 * so Enter or Space inside the confirmation would otherwise open the project underneath it.
 */
function CardConfirmOverlay({
  project,
  copy,
  busy,
  error,
  onCancel,
  onConfirm,
}: {
  project: SiteRecord;
  copy: Pick<DeleteActionCopy, 'confirmTitle' | 'confirmBody' | 'confirmButtonLabel' | 'confirmButtonBusyLabel' | 'confirmButtonClass'>;
  busy: boolean;
  error: string | null;
  onCancel: () => void;
  onConfirm: (id: string) => Promise<void>;
}) {
  return (
    <div
      className="card__confirm"
      role="group"
      aria-label={copy.confirmTitle}
      onClick={(event) => event.stopPropagation()}
      onKeyDown={(event) => event.stopPropagation()}
    >
      <p className="card__confirmtitle">{copy.confirmTitle}</p>
      <p className="card__confirmbody">
        {codeSpans(copy.confirmBody).map((part, index) => (part.code ? <code key={index}>{part.text}</code> : part.text))}
      </p>
      {error && <p className="card__confirmerror" role="alert">{error}</p>}
      <div className="card__confirmacts">
        <button type="button" className="button button--quiet" onClick={onCancel} disabled={busy}>
          Cancel
        </button>
        <button
          type="button"
          className={copy.confirmButtonClass}
          onClick={() => void onConfirm(project.id)}
          disabled={busy}
        >
          {busy ? copy.confirmButtonBusyLabel : copy.confirmButtonLabel}
        </button>
      </div>
    </div>
  );
}

/**
 * A card's button row, under the text: Start/Stop at the left, Restart on the same row at the right
 * edge — always visible, in the card body, never on the preview image.
 *
 * **The order here is the owner's, and it is the order on screen.** This was a bottom-pinned
 * horizontal row (Start/Stop at the left, ⋮ pushed right), then a right-hand column (⋮ level with
 * the name, Stop and Restart stacked under it). On 2026-10-06 they kept the ⋮ where it was but
 * asked for Start/Stop under the "SQLite" line on the left, and Restart on that same row aligned
 * right — so the ⋮ moved out to `SiteCard`'s `.card__head` and this is a row again. Nothing about
 * what any control DOES changed — only where it lands, in `.card__actions`' own CSS and in the
 * order these are written below, which must keep matching the visual order or the Tab key stops
 * agreeing with the eye.
 *
 * **Always visible is the whole point.** These were hover-revealed overlays on the screenshot, and
 * the operator's own words for why that was wrong are "that way you see it whether you hover or
 * not". A hover-revealed control is invisible to anyone reading the screen rather than pointing at
 * it, and on a trackpad it is a control you have to go hunting for.
 *
 * **`role="group"` with both event handlers stopped**, the identical contract `CardConfirmOverlay`
 * and `SiteCardMenu` document and for the identical reason: the card is an open target for clicks
 * AND for keys, so every event that starts in this row must stop in it, or pressing Start would
 * also open the site in a tab. The grouping moved with the controls; it was not dropped when the
 * column became a row again.
 *
 * **No icon controls here.** Delete moved inside the ⋮ menu — see `SiteCardMenu`'s own doc — so
 * this row carries no standalone trash button at all, hover-revealed or not: the owner's reason is
 * misclicks, a destructive control beside a button pressed often. Start/Stop is
 * the site's lifecycle and stays a LABELLED button rather than a glyph — it is the one control here
 * whose meaning changes with the site's state, and an icon cannot say "Stopping…". It wears
 * `.button--create`, the header's "Create website" style, on the owner's own request: reusing that
 * class rather than a one-off look, so the two read as one family.
 *
 * @complexity O(1) — at most two conditional buttons plus Restart.
 */
function CardActions({
  project,
  status,
  power,
  locate,
  onRequestDelete,
}: {
  project: SiteRecord;
  status: SiteRecord['status'];
  power: SitePower;
  locate: SiteLocate;
  onRequestDelete: (id: string) => void;
}) {
  // `null` for `provisioning`/`blocked` — a site with nothing to start yet, or ever. See
  // `powerControl`'s own doc on why that is no button rather than a disabled one.
  const control = powerControl(status, { external: Boolean(project.externalUrl) && !project.externalLauncher });
  const restart = power.restartControlOf?.(project);

  return (
    <div
      className="card__actions"
      role="group"
      aria-label={`Actions for ${project.displayName}`}
      onClick={(event) => event.stopPropagation()}
      onKeyDown={(event) => event.stopPropagation()}
    >
      {/* A missing folder gets Locate / Remove INSTEAD of Start: `tovu serve` on a folder that is
          not there can only fail. Remove goes through the same confirm overlay as the ⋮ entry. */}
      {project.folderMissing ? (
        <>
          <button
            type="button"
            className="button button--create card__power"
            disabled={locate.locatingId === project.id}
            aria-label={`Locate the folder for ${project.displayName}`}
            onClick={() => void locate.locate(project.id)}
          >
            {locate.locatingId === project.id ? 'Locating…' : 'Locate…'}
          </button>
          <button type="button" className="button button--quiet" onClick={() => onRequestDelete(project.id)}>
            Remove
          </button>
        </>
      ) : control && (
        <button
          type="button"
          className="button button--create card__power"
          // Disabled mid-transition rather than hidden: a row that reflows under the pointer is how
          // a second click lands on Restart beside it.
          disabled={control.action === null}
          aria-label={`${control.label} ${project.displayName}`}
          onClick={() => void power.toggle(project)}
        >
          {control.label}
        </button>
      )}
      {/* Last, and pushed to the row's right edge by `.card__restart` — on its own as well as
          beside Start/Stop. */}
      {restart && (
        <button
          type="button"
          className="button button--quiet card__power card__restart"
          disabled={restart.disabled}
          aria-label={restart.ariaLabel}
          onClick={() => void power.restart(project)}
        >
          {restart.label}
        </button>
      )}
    </div>
  );
}

/**
 * A card's ⋮ overflow menu — the card's only icon control now.
 *
 * **Its own component, following `CardConfirmOverlay`'s precedent rather than the complexity
 * gate.** Two independent reasons, both structural. First, it carries the identical event contract
 * `CardConfirmOverlay` documents: the card is a click target AND a keyboard-activated open target,
 * so a click inside this menu would otherwise open the site underneath it — the same swallowing
 * problem, and the same fix. Second, `SiteCard` holds no local state at all; every flag it renders
 * arrives as a prop from the grid's hooks. A menu needs open/closed state, and introducing this
 * component's first `useState` for a concern that is not the card's job is the smell, independent
 * of any number.
 *
 * `useDismissibleDropdown` rather than a hand-rolled outside-click listener: the top nav's two
 * dropdowns already share it, and it was extracted precisely because that behaviour was duplicated.
 * Re-implementing it here is the difference between a menu and a menu bug.
 *
 * Markup matches `SettingsControl`'s contract (`App.tsx`) — `aria-expanded`, `aria-haspopup`,
 * `role="menu"` with `role="menuitem"` children — so the app has one menu pattern, not two.
 *
 * Entries render only when their action is both possible and meaningful: `openInBrowser` for a
 * running site only. An entry that is present but inert teaches the operator that this menu's items
 * sometimes do nothing, which is worse than a shorter menu. Delete/Remove is the one entry that is
 * always present — a card must always have a way to leave the grid.
 *
 * **Delete moved in here from its own always-visible trash button, on the owner's own request,
 * after seeing that layout.** Their stated reason is misclicks: a destructive control sitting next
 * to Start, a button pressed often, was too easy to hit by accident. The move changes nothing about
 * WHAT the entry does — it still only calls `onRequestDelete`, exactly as the old button did, so the
 * confirm overlay (`CardConfirmOverlay`) still gates the actual delete. It closes the menu first
 * (`choose`, same as every other entry) so the open dropdown cannot float over that overlay. It
 * wears `card__menuitem--danger` — the same `--danger` tokens the confirm dialog's own destructive
 * button uses — only when `project.deleteErasesFiles`; an adopted site's "Remove from Projects"
 * does not touch disk, and `deleteActionCopy`'s own doc explains why that case must not read as the
 * scarier one.
 *
 * **Start and Stop are deliberately absent, and this is the whole reason the card has an action
 * row.** Start used to live here, because a stopped site had no other way up; it is now a
 * labelled button in the row below the card's text (`CardActions`). The same action in a menu AND on a button is the
 * duplicate affordance a coherent card cannot have — an operator would have two places to look for
 * one thing, and the menu's copy would have to restate what the button already says.
 *
 * `status` rather than `project.status`: while THIS window's start or stop is in flight the record
 * has not caught up yet, and a menu offering "Open in browser" for a site that is mid-stop would
 * hand the browser a port about to close. See `use-site-power.hooks.ts`.
 *
 * @complexity O(1) — one hook, two fixed entries (Rename, Delete/Remove) plus one conditional
 *   (Open in browser).
 */
function SiteCardMenu({
  project,
  status,
  copy,
  onRename,
  onRequestDelete,
  actions,
}: {
  project: SiteRecord;
  status: SiteRecord['status'];
  copy: DeleteActionCopy;
  onRename: () => void;
  onRequestDelete: (id: string) => void;
  actions: SiteActions;
}) {
  const { open, setOpen, containerRef } = useDismissibleDropdown<HTMLDivElement>();
  const running = status === 'running';

  // Every entry closes the menu first, then acts. See `closeMenuThen`.
  const choose = closeMenuThen(setOpen);

  return (
    <div
      className="card__menu"
      ref={containerRef}
      // The card is the open target for BOTH clicks and keys, so every event that starts in here
      // must stop here. See `CardConfirmOverlay` below, which carries the identical pair.
      onClick={(event) => event.stopPropagation()}
      onKeyDown={(event) => event.stopPropagation()}
    >
      <button
        type="button"
        className="card__menubutton"
        onClick={() => setOpen((current) => !current)}
        aria-expanded={open}
        aria-haspopup="true"
        title={`More actions for ${project.displayName}`}
        aria-label={`More actions for ${project.displayName}`}
      >
        <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
          <circle cx="8" cy="3.25" r="1.35" />
          <circle cx="8" cy="8" r="1.35" />
          <circle cx="8" cy="12.75" r="1.35" />
        </svg>
      </button>
      {open && (
        <div className="card__menulist" role="menu">
          <button type="button" role="menuitem" className="card__menuitem" onClick={choose(onRename)}>
            Rename…
          </button>
          {running && (
            <button
              type="button"
              role="menuitem"
              className="card__menuitem"
              onClick={choose(() => void actions.openInBrowser(project.id))}
            >
              Open in browser
            </button>
          )}
          {/* Always present, and last: the destructive entry belongs at the bottom of the list,
              separated from the safe entries above it by nothing but that position — the same
              convention every native app menu uses for its own Delete item. */}
          <button
            type="button"
            role="menuitem"
            className={project.deleteErasesFiles ? 'card__menuitem card__menuitem--danger' : 'card__menuitem'}
            onClick={choose(() => onRequestDelete(project.id))}
          >
            {copy.menuItemLabel}
          </button>
        </div>
      )}
    </div>
  );
}

/**
 * The inline rename form, shown in place of the card's own content.
 *
 * An overlay on the card rather than a `window.prompt`, for the reason `useDeleteConfirmation`
 * documents for the delete flow: a native modal blocks the whole renderer, and in Electron that
 * also freezes the IPC this window answers on.
 *
 * Save is disabled for a name Tovu would reject, but that is the courtesy half only — main
 * re-applies the identical rule (`site-config.ts`), because a bad name does not break the running
 * site, it stops the NEXT boot. See `isValidSiteName`'s own doc.
 *
 * `role="group"` and both event handlers stopped, identical to `CardConfirmOverlay` and for the
 * identical reason — including Escape and Enter, which a text field must own here rather than let
 * the card interpret as "open me".
 *
 * @complexity O(1).
 */
function CardRenameOverlay({ project, rename }: { project: SiteRecord; rename: SiteRenameState }) {
  const invalid = showsInvalidNameHint(rename.draft);

  return (
    <div
      className="card__confirm"
      role="group"
      aria-label={`Rename ${project.displayName}`}
      onClick={(event) => event.stopPropagation()}
      onKeyDown={(event) => event.stopPropagation()}
    >
      <p className="card__confirmtitle">Rename website</p>
      <label className="card__renamelabel" htmlFor={`rename-${project.id}`}>
        Display name
      </label>
      <input
        id={`rename-${project.id}`}
        className="card__renameinput"
        type="text"
        value={rename.draft}
        maxLength={200}
        autoComplete="off"
        // Autofocused because the overlay exists only to take this one input, and it replaced a
        // control the operator just clicked — landing focus anywhere else would cost them a tab.
        autoFocus
        onChange={(event) => rename.setDraft(event.target.value)}
        onPaste={namePasteHandler({ setName: rename.setDraft })}
        // Escape cancels, Enter submits when Save is enabled. See `renameInputKeyDown`.
        onKeyDown={renameInputKeyDown(rename, project.id)}
        disabled={rename.saving}
      />
      {invalid && <p className="card__confirmerror">A name must be 1 to 200 characters, not counting spaces at either end.</p>}
      {/* Main's own sentence, verbatim — every refusal it raises names the fix. */}
      {rename.renameError && <p className="card__confirmerror">{rename.renameError}</p>}
      <div className="card__confirmacts">
        <button type="button" className="button button--quiet" onClick={rename.cancelRename} disabled={rename.saving}>
          Cancel
        </button>
        <button
          type="button"
          className="button button--contrast"
          onClick={() => void rename.submitRename(project.id)}
          disabled={!rename.canSave}
        >
          {rename.saving ? 'Saving…' : 'Save'}
        </button>
      </div>
    </div>
  );
}

/**
 * @file The shared jsdom host for `App.render.test.ts` and `App.start-panel.render.test.ts`: one
 * jsdom per test PROCESS (node --test gives each file its own), the CSS resolve hook, the host
 * stand-ins, the recording desktop bridge and `renderApp`. See `App.render.test.ts` for why each
 * piece is a stand-in rather than a module mock. Not a test file itself.
 */
import assert from 'node:assert/strict';
import type { TestContext as NodeTestContext } from 'node:test';
import { createRequire, registerHooks } from 'node:module';
import React, { act, createElement } from 'react';
import type { CreatedSiteRecord, SiteFolders, SiteRecord } from '../contracts/project.js';
import type { RunnerSectionId } from '../contracts/sections.js';
import type { RunnerInventoryBridge } from './runner-api.js';
import type { SiteFoldersSettings } from './use-site-folders.hooks.js';
import { useSiteStorageSettings } from './use-site-storage-settings.hooks.js';

// A resolve hook, not a load hook: under tsx, any sync `load` hook makes Node 24 reject the
// source-less result its default step returns for CommonJS packages such as `react` (an
// ERR_INVALID_RETURN_PROPERTY_VALUE that kills the whole file). Resolving `.css` straight to an
// empty data: module never touches the load chain.
registerHooks({
  resolve(specifier, context, nextResolve) {
    if (specifier.endsWith('.css')) return { url: 'data:text/javascript,', format: 'module', shortCircuit: true };
    return nextResolve(specifier, context);
  },
});

const { JSDOM } = createRequire(import.meta.url)('jsdom');
export const dom = new JSDOM('<!doctype html><body></body>', { url: 'http://localhost/', pretendToBeVisual: true });
const resizeCallbacks = new Set<() => void>();
class RecordingResizeObserver {
  private readonly callback: () => void;
  constructor(callback: () => void) { this.callback = callback; }
  observe() { resizeCallbacks.add(this.callback); }
  disconnect() { resizeCallbacks.delete(this.callback); }
}
dom.window.HTMLElement.prototype.scrollIntoView = function scrollIntoView() {};
dom.window.matchMedia = () => ({ matches: false, addEventListener() {}, removeEventListener() {} });
Object.assign(globalThis, {
  window: dom.window, document: dom.window.document, localStorage: dom.window.localStorage,
  requestAnimationFrame: dom.window.requestAnimationFrame, cancelAnimationFrame: dom.window.cancelAnimationFrame,
  ResizeObserver: RecordingResizeObserver, IS_REACT_ACT_ENVIRONMENT: true,
  // `npm test` runs renderer tests under tsx's classic JSX transform (see `icons.test.ts`).
  React,
});
// Both loaded only now: react-dom decides at module load whether it has a DOM (and which input
// events it can use), so it must not be evaluated before the globals above exist.
const { createRoot } = await import('react-dom/client');
export const { App } = await import('./App.js');

export type TestContext = Pick<NodeTestContext, 'after'>;

export function site(id: string, fields: Partial<SiteRecord> = {}): SiteRecord {
  return {
    id, slug: id, displayName: `Site ${id}`, installDir: `/sites/${id}`, port: 0, partition: `persist:${id}`, templateId: 'starter',
    templateVersion: null, database: { kind: 'sqlite' }, desiredState: 'stopped', status: 'stopped', statusDetail: null,
    deleteErasesFiles: false, previewVersion: null, folderMissing: false, createdAt: '2026-01-01T00:00:00.000Z', updatedAt: '2026-01-01T00:00:00.000Z',
    ...fields,
  } as SiteRecord;
}

/** The preload bridge: inert defaults plus listeners the test can fire, overridable per test. */
function installBridge(overrides: Partial<RunnerInventoryBridge> = {}) {
  const listeners = { navigate: new Set<(section: RunnerSectionId) => void>(), find: new Set<() => void>() };
  const calls: string[] = [];
  const bridge = {
    getAppVersion: async () => '1.2.3',
    listAgents: async () => [], rescanAgents: async () => [], daemonOnline: async () => true,
    listSites: async () => [], rescanSites: async () => { calls.push('rescan'); return []; },
    addSite: async () => { calls.push('add'); return null; },
    createSite: async () => null, renameSite: async (input: { id: string }) => site(input.id),
    getSitePreview: async () => null, locateSite: async (id: string) => site(id),
    startSite: async (id: string) => { calls.push(`start:${id}`); return site(id, { status: 'running', port: 4100 }); },
    stopSite: async (id: string) => site(id), deleteSite: async () => {},
    openSiteExternal: async (input: { siteId: string; view: string }) => { calls.push(`external:${input.siteId}:${input.view}`); },
    chatStart: async () => { throw new Error('unused'); }, chatReattach: async () => {}, chatDetach: async () => {}, chatStop: async () => {}, chatStatus: async () => null,
    saveChatAttachment: async () => { throw new Error('unused'); },
    listConversations: async () => [], createConversation: async () => { throw new Error('unused'); },
    renameConversation: async () => {}, deleteConversation: async () => {}, loadConversationMessages: async () => [], saveConversationMessage: async () => {},
    onChatEvent: () => () => {},
    onNavigate: (listener: (section: RunnerSectionId) => void) => { listeners.navigate.add(listener); return () => listeners.navigate.delete(listener); },
    onSiteHistory: () => () => {},
    onFindToggle: (listener: () => void) => { listeners.find.add(listener); return () => listeners.find.delete(listener); },
    findInPage: async () => { calls.push('find'); }, stopFindInPage: async () => { calls.push('stop-find'); }, onFindResult: () => () => {},
    onZoomCommand: () => () => {}, getZoomLevel: () => 0, setZoomLevel: () => {},
    getPathForFile: () => '', pickWorkingDirectory: async () => null, recentWorkingDirectories: async () => [],
    workingDirectoryExists: async () => true, normalizeWorkingDirectory: async (directory: string) => directory,
    ...overrides,
  } as RunnerInventoryBridge;
  dom.window.tovuRunner = bridge;
  return { bridge, listeners, calls };
}

const FOLDERS: SiteFolders = { roots: [], extraRoots: [] } as unknown as SiteFolders;
function useFakeFolders(): SiteFoldersSettings {
  return { folders: FOLDERS, busy: false, error: null, clearError() {}, addFolder: async () => {}, setHome: async () => {}, saveSettings: async () => {}, removeFolder: async () => {} };
}

export const settle = () => act(async () => { for (let i = 0; i < 6; i++) await new Promise<void>((resolve) => setImmediate(resolve)); });

export async function renderApp(t: TestContext, overrides: Partial<RunnerInventoryBridge> = {}) {
  const host = installBridge(overrides);
  let settingsShown = 0;
  const useSiteSettings: typeof useSiteStorageSettings = (required, options) => ({
    ...useSiteStorageSettings(required, { ...options, useFolders: useFakeFolders }),
    show: () => { settingsShown++; },
  });
  const container = document.body.appendChild(document.createElement('div'));
  const root = createRoot(container);
  t.after(() => { act(() => root.unmount()); container.remove(); });
  const props: NonNullable<Parameters<typeof App>[0]> = { sitesSettings: { useFolders: useFakeFolders, useSiteSettings } };
  // `App`'s whole props object is optional (production calls `<App />`), which `createElement`'s
  // overloads cannot infer through; the cast only restates that signature with props required.
  act(() => root.render(createElement(App as (required: typeof props) => ReturnType<typeof App>, props)));
  await settle();
  const all = (selector: string) => [...container.querySelectorAll<HTMLElement>(selector)];
  const byText = (text: string, selector = 'button') => all(selector).find((el) => el.textContent?.trim() === text);
  const byLabel = (label: string) => container.querySelector<HTMLElement>(`[aria-label="${label}"]`);
  const click = async (el: Element | null | undefined) => {
    assert.ok(el, 'element to click is on screen');
    await act(async () => { el.dispatchEvent(new dom.window.MouseEvent('click', { bubbles: true })); });
    await settle();
  };
  const key = (el: Element, init: Record<string, unknown>) => act(() => { el.dispatchEvent(new dom.window.KeyboardEvent('keydown', { bubbles: true, ...init })); });
  return { ...host, container, all, byText, byLabel, click, key, text: () => container.textContent ?? '', settingsShown: () => settingsShown };
}

