  dom.window.close();
}

/** Explicit shell signals: never DOM text, URLs, site identifiers, arguments or content. */
import type { ShellTelemetryPayload, ShellTelemetryBridge } from '../contracts/product-telemetry.js';

/** Reporting must not break a user action or recursively report a broken IPC bridge. O(1). */
export function reportShellTelemetry({ payload }: { payload: ShellTelemetryPayload }, { bridge = typeof window === 'undefined' ? undefined : window.tovuTelemetry }: {
  bridge?: ShellTelemetryBridge;
} = {}): void {
  try { bridge?.report(payload); } catch { /* Product reporting cannot interrupt the shell. */ }
}

/** Install once at renderer boot, before React mounts. Native browser events retain normal handling.
 * @returns Teardown for host/tests. @complexity O(n) capped error text, two listeners only.
 */
export function installShellErrorReporting({ target }: { target: Pick<Window, 'addEventListener' | 'removeEventListener'> }, {
  report = reportShellTelemetry,
}: { report?: typeof reportShellTelemetry } = {}): () => void {
  const send = (failure: unknown, fallback: string) => {
    const error = failure instanceof Error ? failure : new Error(typeof failure === 'string' ? failure : fallback);
    report({ payload: { kind: 'error', message: error.message.slice(0, 1000), stack: (error.stack ?? '').slice(0, 8000) } });
  };
  const error = (event: ErrorEvent) => send(event.error, event.message);
  const rejection = (event: PromiseRejectionEvent) => send(event.reason, 'Unhandled rejection');
  target.addEventListener('error', error as EventListener);
  target.addEventListener('unhandledrejection', rejection as EventListener);
  return () => {
    target.removeEventListener('error', error as EventListener);
    target.removeEventListener('unhandledrejection', rejection as EventListener);
  };
}

/** Reload only this tab's public guest; Electron can throw from calls on detached webviews. */
import type { SiteThemePreviewRefresh } from '../contracts/project.js';
import type { RunnerInventoryBridge } from './runner-api.js';
import type { SiteWorkspaceAction } from './use-site-workspace.hooks.js';

function publicPath(path: string): boolean {
  if (!path.startsWith('/') || path.startsWith('//') || /[\\\u0000-\u0020]/.test(path)) return false;
  try {
    const decoded = decodeURIComponent(path.split(/[?#]/, 1)[0]!);
    const normalized = new URL(path, 'http://preview.invalid').pathname;
    return !/[\\\u0000-\u0020]|^\/\/|(?:^|\/)\.\.(?:\/|$)|^\/(?:admin|api)(?:\/|$)/i.test(decoded)
      && !/^\/(?:admin|api)(?:\/|$)/i.test(normalized);
  } catch { return false; }
}

export function subscribeWorkspaceThemePreview(
  { bridge, siteDir, port, running, url, guest, dispatch }: {
    bridge: Pick<RunnerInventoryBridge, 'watchSitePreview'> | undefined;
    siteDir: string; port: number; running: boolean; url: string;
    guest: (Pick<HTMLWebViewElement, 'reloadIgnoringCache' | 'loadURL'> & Partial<Pick<HTMLWebViewElement, 'getURL'>>) | null;
    dispatch: (action: SiteWorkspaceAction) => void;
  }, _optional = {},
): (() => void) | undefined {
  if (!running || !guest || !bridge?.watchSitePreview) return undefined;
  const origin = `http://127.0.0.1:${port}`;
  const ownPublicUrl = (raw: string) => {
    try {
      const live = new URL(raw);
      return live.origin === origin && !/^\/(?:admin|api)(?:\/|$)/i.test(live.pathname);
    } catch { return false; }
  };
  if (!ownPublicUrl(url)) return undefined;
  let closed = false, previous: string | undefined;
  const dispose = bridge.watchSitePreview({ siteDir, listener: (frame: SiteThemePreviewRefresh) => {
    if (closed || !refreshFrameAccepted({ frame, siteDir, previous })) return;
    previous = frame.revision;
    try {
      // Navigation may precede React's next render; check the actual guest before touching it.
      if (!ownPublicUrl(guest.getURL?.() ?? url)) return;
      if (frame.path === undefined) guest.reloadIgnoringCache();
      else void guest.loadURL(new URL(frame.path, origin).href, { extraHeaders: 'pragma: no-cache\n' }).catch(() => undefined);
      dispatch({ type: 'soft-load' });
    } catch { /* An unattached guest must never blank the host window; its normal load will recover. */ }
  } });
  return () => { closed = true; dispose(); };
}

/** Accept a new revision only for this site and, for tool navigation, a public path.
 * @complexity O(n) in revision and path length.
 */
function refreshFrameAccepted(
  { frame, siteDir, previous }: { frame: SiteThemePreviewRefresh; siteDir: string; previous: string | undefined }, _options = {},
): boolean {
  if (frame.siteDir !== siteDir || frame.revision === previous || !/^[\w-]{1,100}$/.test(frame.revision)) return false;
  return frame.path === undefined || publicPath(frame.path);
}

import assert from 'node:assert/strict';
import ts from 'typescript';
import React from 'react';

/** Execute a private function's actual source without importing the whole Electron UI. */
export function sourceFunction(source: string, name: string, bindings: Record<string, unknown> = {}): any {
  const file = ts.createSourceFile('renderer.tsx', source, ts.ScriptTarget.Latest, true, ts.ScriptKind.TSX);
  const declaration = file.statements.find((node) => ts.isFunctionDeclaration(node) && node.name?.text === name);
  assert.ok(declaration, `missing function ${name}`);
  const code = ts.transpileModule(declaration.getText(file).replace(/^export\s+/, ''), {
    fileName: 'renderer.tsx',
    compilerOptions: { target: ts.ScriptTarget.ES2022, jsx: ts.JsxEmit.React },
  }).outputText;
  const globals = { React, ...bindings };
  return new Function(...Object.keys(globals), `${code}\nreturn ${name};`)(...Object.values(globals));
}

/** Walk the elements actually returned by a component, including private child components. */
export function elements(node: any): any[] {
  if (Array.isArray(node)) return node.flatMap(elements);
  if (!React.isValidElement(node)) return [];
  const element = node as React.ReactElement<any>;
  if (typeof element.type === 'function') return elements((element.type as any)(element.props));
  return [element, ...elements(element.props.children)];
}

/** Small synchronous hook runner: state, callback closures, effect dependencies and cleanup. */
export function hookHarness() {
  const states: any[] = [];
  const setters: any[] = [];
  const effects: { deps: readonly unknown[]; cleanup?: () => void }[] = [];
  let cursor = 0;
  let dirty = false;
  let queued: (() => void)[] = [];
  const bindings = {
    useState(initial: any) {
      const index = cursor++;
      if (!(index in states)) {
        states[index] = typeof initial === 'function' ? initial() : initial;
        setters[index] = (next: any) => {
          const value = typeof next === 'function' ? next(states[index]) : next;
          if (!Object.is(value, states[index])) { states[index] = value; dirty = true; }
        };
      }
      return [states[index], setters[index]];
    },
    useCallback(callback: any) { cursor++; return callback; },
    useEffect(effect: () => (() => void) | void, deps: readonly unknown[]) {
      const index = cursor++;
      const previous = effects[index];
      if (previous && deps.length === previous.deps.length && deps.every((dep, i) => Object.is(dep, previous.deps[i]))) return;
      queued.push(() => {
        previous?.cleanup?.();
        effects[index] = { deps, cleanup: effect() || undefined };
      });
    },
  };
  return {
    bindings,
    render<T>(run: () => T): T {
      let result: T;
      for (let count = 0; count < 20; count++) {
        cursor = 0; dirty = false; queued = [];
        result = run();
        for (const effect of queued) effect();
        if (!dirty) return result;
      }
      throw new Error('hook did not settle');
    },
    cleanup() { for (const effect of effects) effect?.cleanup?.(); },
  };
}

import { useEffect, useState } from 'react';

export type ThemePreference = 'light' | 'system' | 'dark';

const STORAGE_KEY = 'tovu-runner.theme';

/**
 * Default is `light`, not `system`. Runner is early enough that most of what gets
 * looked at is being designed, and a fixed starting point makes "does this look
 * right" answerable without first asking what the OS is set to. `system` is one
 * click away for anyone who wants it.
 */
const DEFAULT: ThemePreference = 'light';

function readStored(): ThemePreference {
  const stored = localStorage.getItem(STORAGE_KEY);
  return stored === 'light' || stored === 'dark' || stored === 'system' ? stored : DEFAULT;
}

/**
 * `data-theme` on the root element is always the *resolved* value — `light` or
 * `dark`, never `system`. That keeps the stylesheet to a single dark block instead
 * of repeating the whole palette once for the explicit choice and again inside a
 * `prefers-color-scheme` query, which is the usual way these two drift apart.
 */
export function useTheme(): [ThemePreference, (next: ThemePreference) => void] {
  const [preference, setPreference] = useState<ThemePreference>(readStored);

  useEffect(() => {
    const media = window.matchMedia('(prefers-color-scheme: dark)');

    const apply = () => {
      const resolved =
        preference === 'system' ? (media.matches ? 'dark' : 'light') : preference;
      document.documentElement.dataset['theme'] = resolved;
      // Tells the engine which form controls and scrollbars to draw.
      document.documentElement.style.colorScheme = resolved;
    };

    apply();
    localStorage.setItem(STORAGE_KEY, preference);

    // Only `system` tracks the OS; an explicit choice must not move underneath you.
    if (preference !== 'system') return;
    media.addEventListener('change', apply);
    return () => media.removeEventListener('change', apply);
  }, [preference]);

  return [preference, setPreference];
}

/** Version loading for the sites home brand; no package metadata enters the renderer bundle. */
import { useEffect, useState } from 'react';
import type { RunnerAppVersionBridge } from '../contracts/app-version.js';
import { runnerInventoryBridge } from './runner-api.js';

/** No guessed version while pending/unavailable; IPC failures retain their actual message. */
export interface AppVersionState {
  version: string | null;
  error: string | null;
}

/**
 * Read the version once per bridge, ignoring responses after cleanup. An older preload without
 * the new method keeps the brand usable until the preload is rebuilt.
 * @param _requiredArgs No caller-supplied version; main is the source of truth.
 * @param options Optional bridge port for tests; defaults to the sites home preload.
 * @returns Version and error state; failures are contained rather than thrown from React.
 * @complexity O(1) time and space, with one IPC request per bridge.
 */
export function useAppVersion(
  _requiredArgs: Record<string, never>,
  { bridge = runnerInventoryBridge() }: { bridge?: Partial<RunnerAppVersionBridge> } = {},
): AppVersionState {
  const [state, setState] = useState<AppVersionState>({ version: null, error: null });

  useEffect(() => {
    setState({ version: null, error: null });
    const getVersion = bridge?.getAppVersion;
    if (!getVersion) return;
    let live = true;
    const load = async (): Promise<void> => {
      try {
        const version = await getVersion();
        if (live) setState({ version, error: null });
      } catch (error) {
        if (live) setState({ version: null, error: error instanceof Error ? error.message : String(error) });
      }
    };
    void load();
    return () => { live = false; };
  }, [bridge]);

  return state;
}

import { useCallback, useEffect, useRef, useState } from 'react';
import type { CreateSiteInput, CreatedSiteRecord, TokenSignInPlugin } from '../contracts/project.js';
import { runnerInventoryBridge, type RunnerInventoryBridge } from './runner-api.js';

/**
 * @file "+ Create website"'s optional "Connect services" fields (2026-09-29) — the desktop twin of
 * the admin's `features/sites/hooks/use-create-site-plugin-tokens.hooks.ts`, with the same rules:
 * which services are offered comes from Tovu (`listTokenSignInPlugins`, every bundled Agent Plugin
 * that takes a pasted token), nothing here names a vendor, an empty field means "skip", and a typed
 * token is checked by `tovu init` before the site is made.
 *
 * Desktop's own credential discipline applies (see `useCreateWebsiteForm`): the token inputs stay
 * uncontrolled, so React never holds a token in state, and they are cleared the moment the create
 * is sent — whether it then succeeds or fails.
 */

export interface CreateSitePluginTokens {
  /** One field per offered service; empty while loading, or when there are none. */
  plugins: readonly TokenSignInPlugin[];
  /** Ref callback for one service's password input. */
  inputRef: (pluginId: string) => (element: HTMLInputElement | null) => void;
  /** Wraps the form's `onCreate` so the typed tokens ride along (then the inputs are cleared). */
  withTokens: (onCreate: (input: CreateSiteInput) => Promise<void>) => (input: CreateSiteInput) => Promise<void>;
}

/**
 * The typed tokens as `CreateSiteInput.agentPluginTokens`: trimmed, blanks dropped, `undefined` when
 * nothing was typed — so a create with no token sends exactly the input it always did.
 * @complexity O(n) in the offered services.
 */
export function tokensForCreate(values: Readonly<Record<string, string>>): Record<string, string> | undefined {
  const out: Record<string, string> = {};
  for (const [pluginId, value] of Object.entries(values)) {
    if (value.trim() !== '') out[pluginId] = value.trim();
  }
  return Object.keys(out).length > 0 ? out : undefined;
}

/** `supabase` -> `Supabase`, `my-crm` -> `My Crm` — the same rule Tovu uses for a plugin's name. */
function titleCase(pluginId: string): string {
  return pluginId
    .split(/[-_.]/)
    .filter(Boolean)
    .map((part) => part[0]!.toUpperCase() + part.slice(1))
    .join(' ');
}

/**
 * The line under "is ready" for tokens given with the create, or `null` when none were.
 * @complexity O(n) in the plugin ids.
 */
export function createdTokensNote(record: Pick<CreatedSiteRecord, 'agentPluginTokens'> | null): string | null {
  const tokens = record?.agentPluginTokens;
  if (!tokens || tokens.pluginIds.length === 0) return null;
  const names = tokens.pluginIds.map(titleCase).join(', ');
  return tokens.status === 'saved'
    ? `${names} will connect when this site first starts.`
    : `${names} couldn't be saved. Open the site and ask its assistant to connect it.`;
}

/**
 * `enabled` follows onboarding availability: hidden fields never contribute tokens to create.
 * `getBridge` reads this window's preload bridge (absent outside a real desktop window) when the
 * effect runs, never during render, so the form still renders where there is no `window`; a test
 * passes a reader returning a fake of the one method used.
 */
export function useCreateSitePluginTokens(
  _requiredArgs: Record<string, never> = {},
  { enabled = true, getBridge = runnerInventoryBridge }: {
    enabled?: boolean;
    getBridge?: () => Pick<RunnerInventoryBridge, 'listTokenSignInPlugins'> | undefined;
  } = {},
): CreateSitePluginTokens {
  const [plugins, setPlugins] = useState<readonly TokenSignInPlugin[]>([]);
  const inputs = useRef(new Map<string, HTMLInputElement>());

  useEffect(() => {
    // Owner 2026-10-06: hidden — do not offer tokens while the service section is unavailable.
    if (!enabled) return;
    let live = true;
    const list = getBridge()?.listTokenSignInPlugins;
    if (!list) return;
    list()
      .then((found) => {
        if (live) setPlugins(found);
      })
      // Main already turns a failure into `[]`; this covers a bridge that rejects anyway.
      .catch(() => undefined);
    return () => {
      live = false;
    };
  }, [enabled, getBridge]);

  const inputRef = useCallback(
    (pluginId: string) => (element: HTMLInputElement | null) => {
      if (element) inputs.current.set(pluginId, element);
      else inputs.current.delete(pluginId);
    },
    [],
  );

  const withTokens = useCallback(
    (onCreate: (input: CreateSiteInput) => Promise<void>) => (input: CreateSiteInput) => {
      const values: Record<string, string> = {};
      for (const [pluginId, element] of inputs.current) {
        // Hidden means no token is sent, including a ref left over from an earlier render.
        if (enabled) values[pluginId] = element.value;
        element.value = '';
      }
      const agentPluginTokens = tokensForCreate(values);
      return onCreate(agentPluginTokens ? { ...input, agentPluginTokens } : input);
    },
    [enabled],
  );

  return { plugins, inputRef, withTokens };
}

import { createFindQueryScheduler, type FindQueryClock } from './find-query-scheduler.js';
/**
 * @file The sites home window's Cmd+F find bar: opening it, routing a query to whichever surface is
 * actually on screen, and the match counter ("3 of 17") that surface reports back.
 *
 * **Two different targets, two different mechanisms.** When a project tab is the visible surface,
 * its `<webview>` guest is the target, and Electron's `WebviewTag` exposes `findInPage`/
 * `stopFindInPage` and a `found-in-page` event directly on that DOM element — no IPC needed, the
 * renderer already holds the node (`registerGuest`, wired from `App.tsx`'s `SiteWorkspace` the same
 * way `guestRef` already is). When the Projects screen itself is on screen (no tab visible), there
 * is no such element for the window's OWN top-level content — `webContents` is main-process-only —
 * so that target goes through `contracts/find-in-page.ts`'s IPC channels
 * (`find-in-page-ipc.ts`/`RunnerInventoryBridge.findInPage`) instead. {@link resolveFindTarget}
 * is the one place that decides which.
 *
 * **Opening needs main; everything after does not.** Cmd+F is a menu accelerator
 * (`find-menu.ts`) because it is the one key binding that still fires while focus is inside a
 * project tab's `<webview>` guest — the same gap `App.hooks.ts`'s `useExpandedMode` documents for
 * Escape. Once the bar is open, typing, Enter, Shift+Enter and Escape are ordinary keydowns on the
 * bar's own input, which lives in THIS document (`App.tsx`'s `FindBar`), so only `onFindToggle`
 * needs the bridge.
 *
 * **The top-level target searches the document this bar is IN, so the bar's own caret is in the
 * way as a search ANCHOR — not, it turns out, as the cause of the focus loss below.** Chromium
 * anchors a find on the frame's live selection when there is one; with a caret sitting in the find
 * input, every search re-anchored on the bar's own position instead of advancing past the previous
 * match, so Enter appeared to do nothing. {@link runFind} clears the selection itself, first, for
 * that target only — a `<webview>` guest searches its own document, which this frame's selection
 * has no bearing on.
 *
 * **Every match steals keyboard focus, and that is `TextFinder::FindInternal`'s own doing, not a
 * side effect of clearing the selection.** Chromium's finder runs `ClearFocusedElement()` then
 * `SetFocusedFrame()` on the searched frame unconditionally, on every match, whichever target. For
 * a top-level match that blurs the find input, which lives in the very document being searched. For
 * a guest match it moves keyboard focus into the GUEST frame instead — same mechanism, same result:
 * the host input loses focus. A focused text input always holds a selection (a caret is one), so
 * there is no way to keep focus through the search either way; {@link restoreFindInputFocus}
 * restores it after.
 *
 * **A guest's find does not always stay in the guest, and that is Chromium's doing, not ours.**
 * `WebContents::GetFindRequestManager` walks UP the outer-WebContents chain and reuses the first
 * manager it finds. A `<webview>` guest is an inner WebContents of this window, so the moment the
 * window itself has run one find — one Cmd+F on the Projects screen is enough — every later guest
 * find is served by the WINDOW's manager instead of the guest's own. Measured, not assumed: with a
 * cold window the guest reports `1 of 98` on its own `found-in-page` and the window reports
 * nothing; after a single `webContents.findInPage` on the window, the identical guest find reports
 * on the WINDOW and the guest's event never fires. Nothing in the renderer can opt out, so this
 * file tolerates both: {@link runFind} clears this frame's selection for either target, results are
 * subscribed from both sources whenever a guest is the target, and focus is restored for EVERY
 * reported result regardless of which source carried it — see {@link subscribeToFindResults}'s
 * `onReported`. Left unhandled on the guest's own event, the bar took exactly one keystroke before
 * every later character fell through to whatever frame Chromium had just focused.
 *
 * **`findNext`'s meaning is Electron's own, and it reads backwards.** `true` begins a NEW search
 * session (the right value for a fresh or changed query); `false` is a follow-up within the current
 * session (the right value for stepping to the next/previous match). See {@link runFind}.
 *
 * Every decision is a plain exported function, so `use-find-in-page.hooks.test.ts` covers them with
 * fakes — this package has no React renderer, same constraint `use-site-workspace.hooks.ts` and
 * `use-site-rename.hooks.ts` document for their own hooks. The hook itself is additionally rendered
 * from this module under jsdom, with its `bridge`/`clock` ports injected
 * ({@link FindInPagePorts}), in `use-find-in-page.jsdom.test.ts`.
 */
import { useCallback, useEffect, useReducer, useRef } from 'react';
import { runnerInventoryBridge, type RunnerInventoryBridge } from './runner-api.js';
import type { FindInPageResult } from '../contracts/find-in-page.js';

/** The slice of the DOM `Selection` API this file drives — see {@link runFind}. A fake of it is
 *  what tests pass. */
export type AnchorSelection = Pick<Selection, 'removeAllRanges'>;

/**
 * This window's own document selection, or `null` where there is no DOM at all (this package's
 * tests run on bare node — see this file's header). Only the top-level target needs it; a
 * `<webview>` guest searches its OWN document, whose selection this one cannot touch.
 *
 * @complexity O(1).
 */
export function liveAnchorSelection(): AnchorSelection | null {
  return typeof document === 'undefined' ? null : document.getSelection();
}

/** The slice of Electron's `<webview>` this file drives. A fake of it is what tests pass. */
export type FindableGuest = Pick<HTMLWebViewElement, 'findInPage' | 'stopFindInPage' | 'addEventListener' | 'removeEventListener'>;

/** The slice of {@link RunnerInventoryBridge} this file drives. */
export type FindBridge = Pick<RunnerInventoryBridge, 'onFindToggle' | 'findInPage' | 'stopFindInPage' | 'onFindResult'>;

export interface FindBarState {
  readonly open: boolean;
  readonly query: string;
  readonly result: FindInPageResult | null;
  /** Bumped on every `toggle`, including a repeat Cmd+F while already open — see `useFindInPage`'s
   *  focus effect, which keys on this rather than on `open` so a second Cmd+F still refocuses. */
  readonly focusNonce: number;
}

export const initialFindBarState: FindBarState = { open: false, query: '', result: null, focusNonce: 0 };

export type FindBarAction =
  | { type: 'toggle' }
  | { type: 'set-query'; query: string }
  | { type: 'result'; result: FindInPageResult }
  | { type: 'close' };

/**
 * @complexity O(1).
 */
export function findBarReducer(state: FindBarState, action: FindBarAction): FindBarState {
  switch (action.type) {
    case 'toggle':
      return { ...state, open: true, focusNonce: state.focusNonce + 1 };
    case 'set-query':
      // A cleared query drops the last result at once rather than leaving a stale "3 of 17" up
      // while `runFind`'s own stop-instead-of-search takes effect.
      return { ...state, query: action.query, result: action.query === '' ? null : state.result };
    case 'result':
      return { ...state, result: action.result };
    case 'close':
      return initialFindBarState;
  }
}

/** Which surface a search should run against right now. */
export type FindTarget = { kind: 'guest'; element: FindableGuest } | { kind: 'top' } | { kind: 'none' };

/**
 * Decides {@link FindTarget}: the visible project tab's guest when one is on screen and its element
 * has actually mounted, otherwise the window's own top-level page — as long as a bridge exists to
 * reach it (never true outside a real desktop window). `'none'` only when neither is available,
 * which callers treat as an inert no-op rather than an error.
 *
 * @complexity O(1) — one `Map.get`.
 */
export function resolveFindTarget(input: {
  activeGuestId: string | null;
  guests: ReadonlyMap<string, FindableGuest>;
  bridge: FindBridge | undefined;
}): FindTarget {
  if (input.activeGuestId !== null) {
    const element = input.guests.get(input.activeGuestId);
    if (element) return { kind: 'guest', element };
  }
  return input.bridge ? { kind: 'top' } : { kind: 'none' };
}

/**
 * Runs one `findInPage` request against `target`. A guest not yet attached throws from every
 * method (same as `use-site-workspace.hooks.ts`'s guest calls) — swallowed here because there is
 * nothing to recover: the next query change or keypress tries again against whatever is mounted by
 * then.
 *
 * **The top-level target must have NO document selection when Chromium reads it, so the search
 * ANCHORS on the previous match instead of the find bar itself.** The find bar's input lives in
 * the very document that target searches, so a caret sitting in it IS this frame's selection, and
 * Chromium's find takes a live selection as the search's anchor. Left in place, every search
 * re-resolved from the find bar's own position in the DOM instead of advancing past the previous
 * match, so Enter appeared to do nothing. Clearing the selection ourselves first leaves Chromium
 * continuing from the previous match instead. This is NOT what causes the focus loss — that is
 * `ClearFocusedElement()`/`SetFocusedFrame()`, which Chromium runs unconditionally on every match
 * regardless of any selection; see this file's header and {@link restoreFindInputFocus}. Only the
 * `top` target needs the selection clear: a guest searches its own document, which this one's
 * selection has no bearing on.
 *
 * @param options.findNext Electron's own meaning, not the button's: `true` begins a NEW session
 *   (pass it for a query CHANGE), `false` is a follow-up within the current one (pass it for
 *   Enter/Shift+Enter). See this file's own header.
 * @param selection this window's own selection; defaults to the live one, so no call site can
 *   forget it. Tests pass a fake to assert it is cleared BEFORE the search, which is the whole
 *   point — a selection still standing when Chromium reads it is the bug.
 * @complexity O(1) beyond Chromium's own search cost.
 */
export function runFind(
  target: FindTarget,
  bridge: FindBridge | undefined,
  text: string,
  options: { forward: boolean; findNext: boolean },
  selection: AnchorSelection | null = liveAnchorSelection(),
): void {
  // Cleared before EITHER target's search, and only when one is actually issued. For `top` it is
  // this frame's own search anchor (below). For a guest it is insurance that costs nothing:
  // Chromium reroutes a guest's find to the WINDOW's find manager once that manager exists (see
  // this file's header), and a rerouted search reads this frame's selection as its anchor after
  // all. When it is not rerouted, the guest searches its own document and this clearing is inert.
  if (target.kind === 'guest') {
    selection?.removeAllRanges();
    try {
      target.element.findInPage(text, options);
    } catch {
      // Not attached yet — nothing to recover; see this function's own doc.
    }
    return;
  }
  if (target.kind === 'top' && bridge) {
    selection?.removeAllRanges();
    void bridge.findInPage({ text, ...options });
  }
}

/**
 * Puts focus back in the find input after ANY reported find result — every one of them means
 * Chromium just moved keyboard focus somewhere else.
 *
 * `TextFinder::FindInternal` runs unconditionally on a match, whichever frame it is in:
 * `ClearFocusedElement()` on the frame that was searched, then `SetFocusedFrame()` onto it. For a
 * top-level match that blurs the find input, which lives in the same document. For a guest match
 * it does the same to the GUEST frame, which — because a focused text input always holds a
 * selection (a caret is one) — takes keyboard focus away from the host input the identical way.
 * There is no way to keep focus through the search either way; it has to be restored after.
 * Without this the bar accepts exactly one character and Enter reaches nobody.
 *
 * **`blur()` first, then `focus()` — a bare `focus()` is a no-op exactly when it matters.** After a
 * guest match the host input is STILL this document's `activeElement` and `document.hasFocus()` is
 * still `true`: Chromium moved the BROWSER's keyboard routing into the guest without telling this
 * frame. `focus()` on an element Blink already considers focused changes nothing, so the browser
 * never hears that this frame wants the keys back, and every later OS keystroke lands in the guest.
 * Measured live with real OS keystrokes (`scripts/verify-find-in-page.ts`'s native-key phase):
 * typing "the" left "t" in the bar; a `blur()`+`focus()` between keys let every one land. Playwright's
 * `keyboard.type` never saw it — CDP delivers keys to the page it targets, not to wherever the
 * browser's focus routing points — which is why the live verifier passed while the app was broken.
 *
 * The `blur()` fires this input's own `blur` event synchronously, which `useFindInPage`'s blur
 * listener would otherwise read as another Chromium theft and answer with ANOTHER restore — a
 * blur/focus loop for the whole {@link FIND_FOCUS_RECLAIM_MS} window. `restoring` is raised for
 * exactly the duration of that `blur()` so the listener can ignore it.
 *
 * Not keyed on which target was asked, because that and where the result reports come apart: a
 * guest's find is rerouted to the window's own find manager once that manager exists, and only
 * then does the window report instead of the guest. Both sources took focus, so both call this —
 * see {@link subscribeToFindResults}'s `onReported`.
 *
 * @complexity O(1).
 */
export function restoreFindInputFocus(input: { blur(): void; focus(): void } | null, restoring: { current: boolean } = { current: false }): void {
  if (!input) return;
  restoring.current = true;
  try {
    input.blur();
  } finally {
    restoring.current = false;
  }
  input.focus();
}

/** How long after ISSUING a find a blur on the find input is treated as Chromium's own focus
 *  theft rather than the user genuinely clicking away — see {@link shouldReclaimFindFocus}. */
export const FIND_FOCUS_RECLAIM_MS = 1000;

/**
 * Whether a blur on the find input, while the bar is `open`, should be undone because it is
 * almost certainly Chromium's `ClearFocusedElement`/`SetFocusedFrame` reaction to a find this file
 * just issued — not the user clicking away. `false` once {@link FIND_FOCUS_RECLAIM_MS} has passed
 * since the last issued find (a genuine click-away has to stick), `false` when no find has been
 * issued yet (`lastFindAt: null`), and `false` when the bar is already closed.
 *
 * @complexity O(1).
 */
export function shouldReclaimFindFocus(input: { open: boolean; lastFindAt: number | null; now: number }): boolean {
  if (!input.open || input.lastFindAt === null) return false;
  return input.now - input.lastFindAt < FIND_FOCUS_RECLAIM_MS;
}

/**
 * Whether `useFindInPage`'s per-frame reclaim should restore focus again on this animation frame.
 *
 * **Why every frame, and not just once per result.** Measured live with real OS keystrokes: the
 * guest takes the keys the moment it selects its FIRST match, but its `found-in-page` only arrives
 * once it has finished COUNTING every match — 100-600ms later on a real admin page. A key typed in
 * that gap reaches the find input's `keydown` but its text is inserted into the guest instead, and
 * nothing at all — no `blur`, no `focusout`, no `document.hasFocus()` change, no main-process
 * `focus` event — fires on the host when the theft happens, so there is no signal to react to. The
 * only thing that closes the gap is re-asserting focus on every frame from the moment a find is
 * issued until it reports.
 *
 * `false` once the find has reported (`awaitingReport` — the report's own restore takes over),
 * outside {@link shouldReclaimFindFocus}'s window, and during IME composition (`composing`): a
 * `blur()` ends a composition, so reclaiming mid-composition would make the bar untypeable in any
 * input method that composes.
 *
 * @complexity O(1).
 */
export function shouldKeepReclaimingFindFocus(input: {
  open: boolean;
  lastFindAt: number | null;
  now: number;
  awaitingReport: boolean;
  composing: boolean;
}): boolean {
  if (!input.awaitingReport || input.composing) return false;
  return shouldReclaimFindFocus(input);
}

/**
 * Whether a bar that is currently `open` should close because the visible surface just changed
 * (a different tab, or Projects screen <-> a tab) — never for a re-render that left
 * `activeGuestId` the same, and never while already closed (nothing open to reset).
 *
 * Extracted as a plain decision, not inlined in the effect that calls it, for the same reason
 * every other routing choice in this file is a function: `useFindInPage` cannot be unit tested
 * directly (see this file's own header), so the DECISION has to be testable on its own.
 *
 * @complexity O(1).
 */
export function shouldCloseOnGuestChange(previousGuestId: string | null, activeGuestId: string | null, open: boolean): boolean {
  return open && previousGuestId !== activeGuestId;
}

/**
 * Stops any in-flight search on `target` and clears its highlights. Same not-attached-yet tolerance
 * as {@link runFind}.
 *
 * @complexity O(1).
 */
export function stopFind(target: FindTarget, bridge: FindBridge | undefined): void {
  if (target.kind === 'guest') {
    try {
      target.element.stopFindInPage('clearSelection');
    } catch {
      // Not attached yet — nothing to stop.
    }
    return;
  }
  if (target.kind === 'top') void bridge?.stopFindInPage();
}

/** The bar's own counter text: `"<ordinal> of <total>"`, or `"No results"` once a query has
 *  actually returned zero matches — never shown for an empty query, which has no `result` yet
 *  (see `findBarReducer`'s `set-query`). */
export function formatMatchCount(result: FindInPageResult | null): string {
  if (result === null) return '';
  if (result.matches === 0) return 'No results';
  return `${result.activeMatchOrdinal} of ${result.matches}`;
}

/**
 * Subscribes to every source that could report the search running against `target`, and hands back
 * one unsubscribe for all of them.
 *
 * The WINDOW's own results are subscribed for every target, not just `top`: Chromium serves a
 * guest's find from the window's find manager once that manager exists, and then the guest's own
 * `found-in-page` never fires (see this file's header). A guest target subscribes to BOTH, because
 * which one reports is Chromium's choice and not observable from here.
 *
 * @param handlers.onResult every reported result, whichever source carried it.
 * @param handlers.onReported called first, for EVERY reported result whichever source carried
 *   it — Chromium moves keyboard focus for a guest match exactly as it does for a top-level one
 *   (`ClearFocusedElement`/`SetFocusedFrame`), so both sources need the same restore. See
 *   {@link restoreFindInputFocus}.
 * @complexity O(1); at most two listeners, both removed by the returned cleanup.
 */
export function subscribeToFindResults(
  target: FindTarget,
  bridge: FindBridge | undefined,
  handlers: { onResult: (result: FindInPageResult) => void; onReported: () => void },
): () => void {
  const unsubscribeWindow = bridge?.onFindResult((result) => {
    handlers.onReported();
    handlers.onResult(result);
  });
  if (target.kind !== 'guest') return () => unsubscribeWindow?.();
  const onFound = (event: WebviewFoundInPageEvent) => {
    handlers.onReported();
    handlers.onResult(event.result);
  };
  target.element.addEventListener('found-in-page', onFound);
  return () => {
    target.element.removeEventListener('found-in-page', onFound);
    unsubscribeWindow?.();
  };
}

export interface FindInPage {
  open: boolean;
  query: string;
  result: FindInPageResult | null;
  /** Text for the counter — see {@link formatMatchCount}. */
  countLabel: string;
  inputRef: (node: HTMLInputElement | null) => void;
  setQuery: (text: string) => void;
  next: () => void;
  previous: () => void;
  close: () => void;
  /** Wired into every mounted project tab's `<webview>` ref — see `useComposedGuestRef`. `null`
   *  deregisters (the tab closed or its guest remounted). */
  registerGuest: (projectId: string, element: FindableGuest | null) => void;
}

/**
 * The timing slice `useFindInPage` drives: the clock its focus-reclaim window is measured on, the
 * animation frames its per-frame reclaim runs on, and the timers behind both the deferred blur
 * reclaim and the typing-settle scheduler. Injected so a test can step every one of them by hand;
 * {@link liveFindClock} is the real browser wiring.
 */
export interface FindFocusClock extends FindQueryClock {
  now: () => number;
  requestFrame: (callback: () => void) => number;
  cancelFrame: (frame: number) => void;
}

/** The window's own `performance`, animation-frame and timer functions. @complexity O(1). */
export const liveFindClock: FindFocusClock = {
  now: () => performance.now(),
  requestFrame: (callback) => requestAnimationFrame(callback),
  cancelFrame: (frame) => cancelAnimationFrame(frame),
  schedule: (callback, delay) => setTimeout(callback, delay),
  cancel: (timer) => clearTimeout(timer as ReturnType<typeof setTimeout>),
};

/** Optional ports for {@link useFindInPage}; production passes none. */
export interface FindInPagePorts {
  /** Defaults to this window's preload bridge (absent outside a real desktop window). */
  bridge?: FindBridge;
  /** Defaults to {@link liveFindClock}. */
  clock?: FindFocusClock;
}

/**
 * The find bar's whole state machine: open/close, the query, the live target, and the result
 * whichever target reports.
 *
 * @param activeGuestId the visible project tab's id, or `null` when the Projects screen itself is
 *   on screen (`App`'s `showSiteTab ? visibleWorkspaceId : null`).
 * @complexity O(1) per action, beyond `runFind`/`stopFind`'s own cost.
 */
export function useFindInPage(
  activeGuestId: string | null,
  { bridge = runnerInventoryBridge(), clock = liveFindClock }: FindInPagePorts = {},
): FindInPage {
  const [state, dispatch] = useReducer(findBarReducer, initialFindBarState);
  // A ref, not state: registering a guest must never itself trigger a render — every mounted tab
  // calls it on every commit (see `useComposedGuestRef`), and the map's CONTENTS are only ever read
  // at the moment a search actually runs, never rendered.
  const guests = useRef(new Map<string, FindableGuest>()).current;
  const inputElement = useRef<HTMLInputElement | null>(null);
  // When the last find was ISSUED (not when a result was reported) — see `issueFind` and
  // {@link shouldReclaimFindFocus}. A ref, not state: recording it must never itself trigger a
  // render.
  const lastFindAt = useRef<number | null>(null);
  // The pending deferred reclaim (see the blur listener below), so `close`/unmount can cancel one
  // scheduled for a bar that is no longer open by the time it would run.
  const reclaimTimer = useRef<unknown>(null);
  // Raised while {@link restoreFindInputFocus} blurs the input itself, so the blur listener below
  // does not mistake that for a Chromium theft — see that function's doc.
  const restoringFocus = useRef(false);
  // Between ISSUING a find and its first reported result — see {@link shouldKeepReclaimingFindFocus}.
  const awaitingReport = useRef(false);
  // An IME composition is in progress in the find input — reclaiming would end it.
  const composing = useRef(false);
  const reclaimFrame = useRef<number | null>(null);
  const queryScheduler = useRef(createFindQueryScheduler({}, { clock })).current;

  const registerGuest = useCallback(
    (projectId: string, element: FindableGuest | null) => {
      if (element) guests.set(projectId, element);
      else guests.delete(projectId);
    },
    [guests],
  );

  const target = resolveFindTarget({ activeGuestId, guests, bridge });

  // Runs a find and records WHEN, so a blur shortly after can be told apart from the user clicking
  // away — see {@link shouldReclaimFindFocus}. Every call site that starts or steps a search goes
  // through this instead of calling `runFind` directly.
  const cancelReclaimFrame = useCallback(() => {
    if (reclaimFrame.current !== null) {
      clock.cancelFrame(reclaimFrame.current);
      reclaimFrame.current = null;
    }
  }, [clock]);

  // Re-asserts focus on every frame until the find just issued reports — see
  // {@link shouldKeepReclaimingFindFocus} for why no single, event-driven restore can do this.
  const reclaimUntilReported = useCallback(() => {
    cancelReclaimFrame();
    const tick = () => {
      reclaimFrame.current = null;
      const keepGoing = shouldKeepReclaimingFindFocus({
        open: inputElement.current !== null,
        lastFindAt: lastFindAt.current,
        now: clock.now(),
        awaitingReport: awaitingReport.current,
        composing: composing.current,
      });
      if (!keepGoing) return;
      restoreFindInputFocus(inputElement.current, restoringFocus);
      reclaimFrame.current = clock.requestFrame(tick);
    };
    reclaimFrame.current = clock.requestFrame(tick);
  }, [cancelReclaimFrame, clock]);

  const issueFind = useCallback(
    (text: string, options: { forward: boolean; findNext: boolean }) => {
      lastFindAt.current = clock.now();
      awaitingReport.current = true;
      runFind(target, bridge, text, options);
      // Reclaim immediately for a typed query as well as on subsequent frames/results.
      if (options.findNext && !composing.current) restoreFindInputFocus(inputElement.current, restoringFocus);
      // Only for a NEW session (a typed character): Enter/Shift+Enter's step must not be disturbed
      // mid-flight. Each reclaim's focus() puts the input's caret back as this frame's selection, and
      // a follow-up find that reads it anchors on the find bar instead of the previous match (see
      // {@link runFind}) — measured live, the per-frame reclaim turned Enter's 2 -> 3 -> 4 into
      // 2 -> 3 -> 2. Stepping is keyed on Enter, not on text going into the input, so its keys are
      // not the ones the gap loses; the report's own restore still covers it.
      if (options.findNext) reclaimUntilReported();
    },
    [target, bridge, reclaimUntilReported, clock],
  );

  const clearReclaimTimer = useCallback(() => {
    if (reclaimTimer.current !== null) {
      clock.cancel(reclaimTimer.current);
      reclaimTimer.current = null;
    }
  }, [clock]);

  // The app menu's Find (Cmd+F): open (or, if already open, bump `focusNonce` so the effect below
  // refocuses even though `open` itself does not change).
  useEffect(() => {
    if (!bridge) return undefined;
    return bridge.onFindToggle(() => dispatch({ type: 'toggle' }));
  }, [bridge]);

  // Focuses and selects the input every time the bar opens OR is re-summoned while already open —
  // matching Chrome's own Cmd+F, which reselects the existing query for a fast re-type.
  useEffect(() => {
    if (!state.open) return;
    // blur()+focus(), not a bare focus(): Cmd+F pressed while typing in the guest leaves the browser
    // routing keys into the guest, and on a re-summon the input is already this document's
    // activeElement — a bare focus() is then a no-op the browser never hears about. See
    // {@link restoreFindInputFocus}.
    restoreFindInputFocus(inputElement.current, restoringFocus);
    inputElement.current?.select();
  }, [state.open, state.focusNonce]);

  // Subscribes to results from whichever target is live, only while the bar is open — an empty
  // query never subscribes at all (see the early return), matching `runFind`'s own stop-not-search.
  useEffect(() => {
    if (!state.open || state.query === '') return undefined;
    return subscribeToFindResults(target, bridge, {
      onReported: () => {
        awaitingReport.current = false;
        if (!composing.current) restoreFindInputFocus(inputElement.current, restoringFocus);
      },
      onResult: (result) => dispatch({ type: 'result', result }),
    });
    // `target` is a fresh object every render (`resolveFindTarget` builds one), so this depends on
    // its STABLE identity components instead — the guest map is a ref (never itself a dependency
    // trigger) and `activeGuestId` is what actually changes which entry it names.
    // biome-ignore lint/correctness/useExhaustiveDependencies: depends on target's stable inputs (activeGuestId, bridge), not the fresh `target` object itself — see the comment above.
  }, [state.open, state.query === '', activeGuestId, bridge]);

  // A query change — including the FIRST non-empty character — is a NEW search session
  // (`findNext: true`, per this file's header); clearing back to '' stops it instead of searching
  // for nothing.
  useEffect(() => {
    queryScheduler.cancel();
    if (!state.open) return;
    if (state.query === '') {
      awaitingReport.current = false;
      cancelReclaimFrame();
      stopFind(target, bridge);
      return;
    }
    const run = () => {
      // Blurring during an IME composition would discard the text still being composed.
      if (composing.current) { queryScheduler.schedule({ run }); return; }
      issueFind(state.query, { forward: true, findNext: true });
    };
    queryScheduler.schedule({ run });
    return () => queryScheduler.cancel();
    // biome-ignore lint/correctness/useExhaustiveDependencies: depends on target's stable inputs (activeGuestId), not the fresh `target`/`bridge` objects themselves.
  }, [state.query, state.open, activeGuestId]);

  // Closes (and clears the OUTGOING surface's own highlights) on a tab switch while the bar is
  // open — known rough edge until now: switching tabs left the bar open, still showing the
  // previous tab's stale query/count, and never cleared that tab's own highlight because nothing
  // called `stopFind` for it once it went off screen. Mirrors `App.hooks.ts`'s
  // `expandedAfterWorkspaceChange` precedent for the identical class of problem (collapse-on-
  // workspace-change). `previousGuestIdRef` — not `target` — resolves the OUTGOING guest: by the
  // time this effect runs post-commit, `activeGuestId` (and therefore `target`) already point at
  // the NEW surface.
  const previousGuestIdRef = useRef(activeGuestId);
  useEffect(() => {
    if (shouldCloseOnGuestChange(previousGuestIdRef.current, activeGuestId, state.open)) {
      const outgoing = resolveFindTarget({ activeGuestId: previousGuestIdRef.current, guests, bridge });
      stopFind(outgoing, bridge);
      dispatch({ type: 'close' });
    }
    previousGuestIdRef.current = activeGuestId;
    // biome-ignore lint/correctness/useExhaustiveDependencies: keys on activeGuestId's stable identity only, matching this file's other target-derived effects above.
  }, [activeGuestId]);

  // Reclaims focus the moment Chromium takes it, BEFORE the result round trip — on a big page that
  // trip can take long enough for a fast typist's next letters to reach the guest. A native `blur`
  // listener, not React's `onBlur`: the theft is a PAGE-level focus loss (`document.activeElement`
  // stays the input), which does not fire through React's root `focusout` delegation the way a real
  // blur-to-another-element does (memory `component_logic_belongs_hooks` — this stays in the hook,
  // not `App.tsx`). Deferred with `setTimeout(0)` rather than refocusing inline: the host-side blur
  // fires SYNCHRONOUSLY inside Chromium's own find, so an inline refocus would fight it. Never calls
  // `issueFind`/`runFind`/`stopFind` from here — Chromium steals focus once per issued find, so one
  // reclaim per find settles it; re-running the search on refocus is the focus-fight loop a guest
  // theft can otherwise trigger.
  const attachBlurReclaim = useCallback(
    (node: HTMLInputElement) => {
      const onBlur = () => {
        if (restoringFocus.current) return;
        clearReclaimTimer();
        reclaimTimer.current = clock.schedule(() => {
          reclaimTimer.current = null;
          // Re-reads `inputElement.current`, not the closed-over `node`: the bar may have closed
          // (and unmounted the input) by the time this deferred callback runs.
          if (shouldReclaimFindFocus({ open: inputElement.current !== null, lastFindAt: lastFindAt.current, now: clock.now() })) {
            restoreFindInputFocus(inputElement.current, restoringFocus);
          }
        }, 0);
      };
      const onCompositionStart = () => {
        composing.current = true;
      };
      const onCompositionEnd = () => {
        composing.current = false;
      };
      node.addEventListener('blur', onBlur);
      node.addEventListener('compositionstart', onCompositionStart);
      node.addEventListener('compositionend', onCompositionEnd);
      return () => {
        node.removeEventListener('blur', onBlur);
        node.removeEventListener('compositionstart', onCompositionStart);
        node.removeEventListener('compositionend', onCompositionEnd);
        composing.current = false;
      };
    },
    [clearReclaimTimer, clock],
  );

  // Detaches the previous node's blur listener before attaching the next one, so a remount (or the
  // bar closing) never leaves a stale listener on a detached node.
  const detachBlurReclaim = useRef<(() => void) | null>(null);
  const inputRef = useCallback(
    (node: HTMLInputElement | null) => {
      detachBlurReclaim.current?.();
      detachBlurReclaim.current = null;
      inputElement.current = node;
      if (node) detachBlurReclaim.current = attachBlurReclaim(node);
    },
    [attachBlurReclaim],
  );

  useEffect(() => () => {
    queryScheduler.cancel();
    clearReclaimTimer();
    cancelReclaimFrame();
  }, [queryScheduler, clearReclaimTimer, cancelReclaimFrame]);

  const close = () => {
    queryScheduler.cancel();
    clearReclaimTimer();
    cancelReclaimFrame();
    awaitingReport.current = false;
    stopFind(target, bridge);
    dispatch({ type: 'close' });
  };

  return {
    open: state.open,
    query: state.query,
    result: state.result,
    countLabel: formatMatchCount(state.result),
    inputRef,
    setQuery: (text) => dispatch({ type: 'set-query', query: text }),
    // Follow-up requests within the current session — `findNext: false` — never a new one.
    next: () => { if (!queryScheduler.flush()) issueFind(state.query, { forward: true, findNext: false }); },
    previous: () => { if (!queryScheduler.flush()) issueFind(state.query, { forward: false, findNext: false }); },
    close,
    registerGuest,
  };
}

/**
 * Composes a project tab's own `guestRef` (`useSiteWorkspace`'s callback ref, which feeds
 * `useWebviewLoadFailure`'s `setGuest`) with {@link FindInPage.registerGuest}, so `App.tsx` sets ONE
 * `ref` on the `<webview>` rather than two. Memoized on its stable inputs — `guestRef` is a
 * `useState` setter (always stable), `registerGuest` is `useCallback`-stable, and `projectId` does
 * not change for a mounted tab's own instance — so this is not a fresh function every render, which
 * would otherwise make React detach and reattach the ref on every commit for no reason.
 *
 * @param extra an optional third registration, called last, for a feature with its own per-guest
 *   registry — `use-zoom.hooks.ts`'s `registerGuest`, wrapped by its caller as
 *   `(node) => zoom.registerGuest(projectId, node)`. Not typed against `FindableGuest`: a second
 *   feature's own narrower `Pick<HTMLWebViewElement, ...>` is a different type from this file's,
 *   and the real DOM node this ref actually receives satisfies both, so the caller narrows it, not
 *   this function.
 * @complexity O(1).
 */
export function useComposedGuestRef(
  guestRef: (node: HTMLWebViewElement | null) => void,
  registerGuest: (projectId: string, element: FindableGuest | null) => void,
  projectId: string,
  extra?: (node: HTMLWebViewElement | null) => void,
): (node: HTMLWebViewElement | null) => void {
  return useCallback(
    (node: HTMLWebViewElement | null) => {
      guestRef(node);
      registerGuest(projectId, node);
      extra?.(node);
    },
    [guestRef, registerGuest, projectId, extra],
  );
}

/** New-site destination preview; main owns home resolution and collision suffixes. */
import { useEffect, useState } from 'react';
import { runnerInventoryBridge, type RunnerInventoryBridge } from './runner-api.js';
import { humanSiteError } from './site-shell-policy.js';

/** Show the latest name's planned destination, ignoring replies after a name change/unmount.
 * Planning is read-only; Create checks the destination again when submitted.
 * @complexity O(n) display formatting for n path characters; one IPC call per name change.
 */
export function useNewSiteDir({ name }: { name: string }, {
  getBridge = runnerInventoryBridge,
}: { getBridge?: () => Pick<RunnerInventoryBridge, 'planNewDir'> | undefined } = {}): string {
  const [preview, setPreview] = useState({ name: '', hint: 'Checking website destination…' });
  useEffect(() => {
    let active = true;
    const plan = getBridge()?.planNewDir;
    if (!plan) {
      setPreview({ name, hint: 'Website destination is unavailable in this desktop version.' });
      return;
    }
    void plan({ name }).then(({ path, homeDir }) => {
      const separator = homeDir.includes('\\') ? '\\' : '/';
      const display = path.startsWith(homeDir + separator) ? '~' + path.slice(homeDir.length) : path;
      if (active) setPreview({ name, hint: `Creates ${display}` });
    }).catch((error: unknown) => {
      if (active) setPreview({ name, hint: humanSiteError({ error, fallback: 'Could not plan the website destination. Check Sites settings.' }) });
    });
    return () => { active = false; };
  }, [name, getBridge]);
  return preview.name === name ? preview.hint : 'Checking website destination…';
}

/** Pull-only Tovu resource readings. Main owns sampling policy and process attribution. */
import { useEffect, useRef, useState } from 'react';
import { runnerInventoryBridge } from './runner-api.js';
import type { ResourcesRequest, ResourcesSnapshot } from '../contracts/resources.js';

/** Effects at the renderer boundary; fakes need neither Electron nor real timers. */
export interface ResourcesPorts {
  getBridge: () => { getResources?: (input: ResourcesRequest) => Promise<ResourcesSnapshot> } | undefined;
  document: {
    readonly hidden: boolean;
    addEventListener: (event: 'visibilitychange', listener: () => void) => void;
    removeEventListener: (event: 'visibilitychange', listener: () => void) => void;
  };
  setTimer: (run: () => void, delay: number) => number;
  clearTimer: (id: number) => void;
}

const browserPorts: ResourcesPorts = {
  getBridge: runnerInventoryBridge,
  get document() { return document; },
  setTimer: (run, delay) => window.setTimeout(run, delay),
  clearTimer: (id) => window.clearTimeout(id),
};

/** A visibility change invalidates a pending reading; retry it before the next normal cadence. */
function pollDelay({ currentVisibility, snapshot }: { currentVisibility: boolean; snapshot: ResourcesSnapshot | null }, _options = {}) {
  if (!currentVisibility) return 0;
  return snapshot?.pollIntervalMs ?? 60_000;
}

/**
 * Read one shared snapshot while the host document is visible. Returns null on IPC failure or
 * stale preload; native errors never enter the UI. Cleanup removes the listener and timer.
 * A shared promise serializes reads even when opening the panel replaces the effect mid-request.
 * @example const snapshot = useResources({ panelOpen });
 * @complexity O(1) work/state per poll beyond the existing main-process IPC.
 */
export function useResources({ panelOpen }: ResourcesRequest, { ports = browserPorts }: { ports?: ResourcesPorts } = {}) {
  const [snapshot, setSnapshot] = useState<ResourcesSnapshot | null>(null);
  const inFlight = useRef<Promise<ResourcesSnapshot | null> | null>(null);
  useEffect(() => {
    const bridge = ports.getBridge();
    if (!bridge?.getResources) return;
    let active = true;
    let pending = false;
    let visibilityVersion = 0;
    let timer: number | undefined;

    /** Clear the scheduled read before hiding, refreshing or disposing this effect. */
    function clearTimer() {
      if (timer !== undefined) ports.clearTimer(timer);
      timer = undefined;
    }

    /** Re-check visibility after awaiting another effect's read; never overlap IPC requests. */
    async function poll() {
      if (pending) return;
      pending = true;
      await inFlight.current;
      if (!active || ports.document.hidden) { pending = false; return; }
      const version = visibilityVersion;
      // Resolve failures locally: raw native/IPC messages may contain sensitive process details.
      const request = Promise.resolve().then(() => bridge!.getResources!({ panelOpen })).catch(() => null);
      inFlight.current = request;
      const next = await request;
      inFlight.current = null;
      pending = false;
      if (!active || ports.document.hidden) return;
      const currentVisibility = version === visibilityVersion;
      if (currentVisibility) setSnapshot(next);
      timer = ports.setTimer(() => { void poll(); }, pollDelay({ currentVisibility, snapshot: next }));
    }

    /** A hidden document owns no timer. Returning to it asks main for a fresh/cached snapshot. */
    function visibilityChanged() {
      visibilityVersion++;
      clearTimer();
      if (!ports.document.hidden) void poll();
    }
    ports.document.addEventListener('visibilitychange', visibilityChanged);
    void poll();
    return () => {
      active = false;
      clearTimer();
      ports.document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [panelOpen, ports]);
  return snapshot;
}

/** Discovery settings state; all filesystem/picker effects stay behind the preload port. */
import { useCallback, useEffect, useState } from 'react';
import { useAsyncAction } from '@jini-ai/ui/panel-kit';
import { humanSiteError } from './site-shell-policy.js';
import type { SiteFolders } from '../contracts/project.js';
import { runnerInventoryBridge } from './runner-api.js';
import type { RunnerInventoryBridge } from './runner-api.js';

type FoldersBridge = Pick<RunnerInventoryBridge, 'listSiteFolders' | 'addSiteFolder' | 'removeSiteFolder' | 'setSitesHome' | 'saveSiteSettings' | 'rescanSites'>;

/** Presentation contract for the Websites screen's sites-folders setting. */
export interface SiteFoldersSettings {
  folders: SiteFolders;
  busy: boolean;
  error: string | null;
  clearError: () => void;
  addFolder: () => Promise<void>;
  setHome: () => Promise<void>;
  saveSettings: (patch: import("../contracts/project.js").SiteSettingsPatch) => Promise<void>;
  removeFolder: (required: { root: string }, options?: {}) => Promise<void>;
}

/** Load settings once per mount and apply mutation results immediately. Null picker results leave
 * settings intact; transport prefixes are removed from real failures. Add rescans discovery without starting sites.
 * @param options.getBridge Injectable preload reader for tests and hosts with older preloads.
 * @returns Settings plus busy/error state and native-picker/removal actions.
 * @complexity O(n) stored roots in state; Add uses picker + scan, other actions one IPC operation.
 */
export function useSiteFolders(_required = {}, { getBridge = runnerInventoryBridge, useAction = useAsyncAction }: {
  getBridge?: () => FoldersBridge | undefined;
  useAction?: typeof useAsyncAction;
} = {}): SiteFoldersSettings {
  const [folders, setFolders] = useState<SiteFolders>({ roots: [], extraRoots: [] });
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const { saving, error: actionError, setError, run } = useAction();
  useEffect(() => {
    let active = true;
    const bridge = getBridge();
    if (!bridge?.listSiteFolders) {
      setLoadError('Sites folders settings are unavailable in this desktop version.');
      setLoading(false);
      return;
    }
    void bridge.listSiteFolders().then((next) => {
      if (active) setFolders(next);
    }).catch((failure: unknown) => {
      if (active) setLoadError(humanSiteError({ error: failure, fallback: 'Could not update sites folders. Try again.' }));
    }).finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [getBridge]);

  // Jini owns the action lifecycle; Tovu only applies this setting's nullable picker result.
  const change = useCallback((operation: () => Promise<SiteFolders | null>) => run({
    action: async () => {
      const next = await operation();
      if (next !== null) setFolders(next);
      setLoadError(null);
    },
    describeError: (failure) => humanSiteError({ error: failure, fallback: 'Could not update sites folders. Try again.' }),
  }), [run]);

  const addFolder = useCallback(() => change(async () => {
    const bridge = getBridge();
    if (!bridge?.addSiteFolder) throw new Error('Sites folders settings are unavailable in this desktop version.');
    const next = await bridge.addSiteFolder();
    if (next !== null) {
      // Admission validated before saving. A later rescan may still fail if the disk changes;
      // retain the saved root so the operator can retry or remove it.
      setFolders(next);
      await bridge.rescanSites();
    }
    return next;
  }), [change, getBridge]);

  const removeFolder = useCallback(({ root }: { root: string }, _options = {}) => change(async () => {
    const bridge = getBridge();
    if (!bridge?.removeSiteFolder) throw new Error('Sites folders settings are unavailable in this desktop version.');
    return bridge.removeSiteFolder({ root });
  }), [change, getBridge]);

  const setHome = useCallback(() => change(async () => {
    const bridge = getBridge();
    if (!bridge?.setSitesHome) throw new Error('Sites home settings are unavailable in this desktop version.');
    return bridge.setSitesHome();
  }), [change, getBridge]);

  const saveSettings = useCallback((patch: import("../contracts/project.js").SiteSettingsPatch) => change(async () => {
    const bridge = getBridge();
    if (!bridge?.saveSiteSettings) throw new Error('Sites settings are unavailable in this desktop version.');
    return bridge.saveSiteSettings(patch);
  }), [change, getBridge]);

  return { clearError: () => { setError(null); setLoadError(null); }, saveSettings, setHome, folders, busy: loading || saving, error: actionError ?? loadError, addFolder, removeFolder };
}

/**
 * @file The site card's Start/Stop control: what it should say right now, and what a click does.
 *
 * **Why the app needed this at all.** Nothing in this shell could stop ONE site. Quitting stopped
 * every open site (`before-quit`), deleting one stopped it on the way to erasing it, and that was
 * the list — an operator who wanted a single site down had to find its `tovu serve` in a terminal
 * and kill it, which is exactly the move that costs unsaved work.
 *
 * **The label is derived from status, never from what was clicked.** A button that remembers its
 * own press is the one that lies: a start that fails, a site that dies during a stop, a second
 * window acting on the same site, and the button still says what the click implied. `powerControl`
 * below is a pure function of the status, so the only way to make it say "Stopping…" is for the
 * site to actually be stopping.
 *
 * **Two sources of that status, and the local one is the smaller.** Main owns it — `handleStart`
 * and `handleStop` mark the site `starting`/`stopping` for as long as their work runs
 * (`site-transitions.ts`), and every reader of the polled record sees it. But the poll is every 4 s,
 * so between the click and the next poll the card would still be showing the pre-click status. The
 * `pending` map here closes exactly that gap, and it is dropped the moment the call settles; it is
 * never an answer of its own about a site.
 */
import { useCallback, useState } from 'react';
import { reportShellTelemetry } from './product-telemetry.js';

import { runnerInventoryBridge } from './runner-api.js';
import type { SiteLifecycleStatus, SiteRecord } from '../contracts/project.js';
import { desktopCopy, runtimeLocale } from '../desktop-i18n.js';
import { siteOperationError } from './site-shell-policy.js';

/** Which way a click moves a site. */
export type SitePowerAction = 'start' | 'stop';
type SitePowerOperation = SitePowerAction | 'restart';

/** Await a graceful stop before starting; never start if stopping failed. */
export async function performSiteRestart({ id, bridge }: {
  id: string;
  bridge: Parameters<typeof performPowerAction>[2];
}, { onStopped }: { onStopped?: (record: SiteRecord) => void } = {}): Promise<SitePowerResult> {
  const stopped = await performPowerAction('stop', id, bridge);
  if (stopped.error !== undefined) return stopped;
  onStopped?.(stopped.record);
  return performPowerAction('start', id, bridge);
}

export function restartControl({ project, status, restarting }: {
  project: SiteRecord;
  status: SiteLifecycleStatus;
  restarting: boolean;
}, { locale = runtimeLocale() }: { locale?: string } = {}) {
  const copy = desktopCopy({ locale });
  const label = restarting ? copy.restarting : copy.restart;
  return { label, ariaLabel: `${label} ${project.displayName}`, disabled: status !== 'running' || Boolean(project.folderMissing) || Boolean(project.externalUrl) };
}

/**
 * The confirm a Stop needs before stopping a site another process serves, or `null` when Stop needs
 * none. Owner 2026-10-13: Stop on an `npm run dev` site tears down that whole dev stack, so it asks
 * first and says so; any other external owner gets a generic line naming its app.
 *
 * @returns the overlay copy, shaped like the delete confirm's so one overlay renders both.
 * Pure: no effects or errors.
 * @complexity O(1).
 */
export function externalStopConfirm(
  { project }: { project: Pick<SiteRecord, 'displayName' | 'externalUrl' | 'externalLauncher' | 'runningApp'> },
  { locale = runtimeLocale() }: { locale?: string } = {},
) {
  if (!project.externalUrl || !project.externalLauncher) return null;
  const copy = desktopCopy({ locale }).stopConfirm;
  const body = project.externalLauncher === 'npm-run-dev' ? copy.devBody : copy.otherBody.replace('{app}', project.runningApp ?? 'Tovu');
  return {
    confirmTitle: copy.title.replace('{name}', project.displayName),
    confirmBody: body,
    confirmButtonLabel: copy.confirm,
    confirmButtonBusyLabel: copy.confirming,
    // Disruptive, not destructive: nothing is erased, and Start brings the site back in this app.
    confirmButtonClass: 'button button--primary',
  };
}

/**
 * `text` split on backtick pairs, so a confirm body can show `npm run dev` as code without the
 * renderer parsing markup. Odd indexes are the code spans.
 * Pure: no effects or errors.
 * @complexity O(n) in text length.
 */
export function codeSpans(text: string): { text: string; code: boolean }[] {
  return text.split('`').map((part, index) => ({ text: part, code: index % 2 === 1 })).filter((part) => part.text !== '');
}

/** What the card should render for a site's power control. */
export interface SitePowerControl {
  /** What a click does — `null` while a transition is in flight, which renders the button disabled
   *  rather than hiding it, so the row does not reflow under the pointer mid-press. */
  action: SitePowerAction | null;
  label: string;
  busy: boolean;
}

/**
 * The card's power button for a site in `status`, or `null` when there is no honest button to draw.
 *
 * `provisioning` and `blocked` get `null` rather than a disabled Start: there is nothing to start
 * yet for the first, and never will be for the second, and a control that is permanently inert
 * teaches an operator that this card's buttons sometimes do nothing.
 *
 * `failed` gets Start, not a disabled button — a site whose last boot failed is precisely one an
 * operator wants to try again, and `handleStart` is what they would be reaching for.
 *
 * `external` means another process serves the site AND main cannot stop it (no `externalLauncher`):
 * no button. One main can stop gets the ordinary Stop, gated by {@link externalStopConfirm}.
 *
 * @complexity O(1).
 */
export function powerControl(status: SiteLifecycleStatus, { external = false }: { external?: boolean } = {}): SitePowerControl | null {
  if (external) return null;
  if (status === 'running') return { action: 'stop', label: 'Stop', busy: false };
  if (status === 'stopped' || status === 'failed') return { action: 'start', label: 'Start', busy: false };
  if (status === 'starting') return { action: null, label: 'Starting…', busy: true };
  if (status === 'stopping') return { action: null, label: 'Stopping…', busy: true };
  return null;
}

/** What {@link useSitePower} returns. */
export interface SitePower {
  /** The status the card should render for this project — its polled one, or the transition this
   *  window started and is still waiting on. */
  statusOf: (project: SiteRecord) => SiteLifecycleStatus;
  /** Why this site's last start or stop failed, or `null`. Main's own sentence, verbatim. */
  errorOf: (id: string) => string | null;
  /** Start a stopped site or stop a running one. A no-op while one is already in flight. A Stop of a
   *  site another process serves only opens the confirm unless `confirmed`. */
  toggle: (project: SiteRecord, options?: { confirmed?: boolean }) => Promise<void>;
  restart: (project: SiteRecord) => Promise<void>;
  restartControlOf: (project: SiteRecord) => ReturnType<typeof restartControl>;
  /** The site whose Stop is waiting on {@link externalStopConfirm}'s confirm, or `null`. Optional
   *  (with the two below) so card fixtures that never stop an external site need not stub it. */
  confirmingStopId?: string | null;
  confirmStop?: (project: SiteRecord) => Promise<void>;
  cancelStop?: () => void;
}

/** The status a click's own transition reads as while it is in flight. */
export const IN_FLIGHT_STATUS: Record<SitePowerAction, SiteLifecycleStatus> = {
  start: 'starting',
  stop: 'stopping',
};

/** What one start or stop came back with: main's refreshed record, or an operator-facing reason. */
export type SitePowerResult = { record: SiteRecord; error?: undefined } | { record?: undefined; error: string };

/**
 * Run one start or stop against the desktop bridge and report the outcome.
 *
 * Separated from the hook below so the whole decision — which bridge call, what a rejection turns
 * into, what "no bridge at all" means — is directly testable: this package has no React renderer,
 * so anything left inside a `useCallback` can only be asserted against source text. Same split
 * `use-site-rename.hooks.ts` makes, for the same reason.
 *
 * A missing bridge is reported exactly like a rejection rather than thrown: a renderer with no
 * `window.tovuRunner` is a shell that failed to wire its preload, and the card's own error line is
 * where an operator can see that.
 *
 * @returns `{record}` on success — main's, never one composed here from what was clicked.
 * @complexity O(1) beyond the IPC round trip, which for a stop includes the child's own drain.
 */
export async function performPowerAction(
  action: SitePowerAction,
  id: string,
  bridge: { startSite: (id: string) => Promise<SiteRecord>; stopSite: (id: string) => Promise<SiteRecord> } | undefined,
): Promise<SitePowerResult> {
  if (bridge === undefined) return { error: 'The desktop bridge is unavailable.' };
  try {
    return { record: action === 'start' ? await bridge.startSite(id) : await bridge.stopSite(id) };
  } catch (err) {
    return { error: action === 'start' ? siteOperationError({ error: err, operation: 'start' }) : err instanceof Error ? err.message : String(err) };
  }
}

/** What a power press may do once main answers, beyond the card's own state. */
export interface SitePowerCallbacks {
  /** Applies main's refreshed record — see {@link useSitePower}. */
  onSiteUpdated?: (record: SiteRecord) => void;
  /** Opens the site that was just started. The caller passes the card's own open callback, so a
   *  Start lands in exactly the tab a click on the card would have opened — one open path, not two. */
  onStarted?: (id: string) => void;
}

/**
 * One Start/Stop press, end to end: the bridge call, then what its outcome means for the window.
 *
 * **A Start that comes back running opens the site.** Starting a site and then clicking its card to
 * go in was one click too many — nobody presses Start on a site they do not mean to use. It waits
 * for main's record to SAY `running` (main resolves `startSite` only after `tovu serve` is ready),
 * never for the press itself, so a start that fails or settles any other way stays on the card with
 * its error showing exactly as before.
 *
 * Separate from the hook for the same reason {@link performPowerAction} is: this package has no
 * React renderer, so this is the seam a test can call.
 *
 * @returns the operator-facing failure, or `null` on success.
 * @complexity O(1) beyond the IPC round trip.
 */
export async function runPowerToggle(
  { action, id, bridge }: { action: SitePowerAction; id: string; bridge: Parameters<typeof performPowerAction>[2] },
  { onSiteUpdated, onStarted }: SitePowerCallbacks = {},
): Promise<string | null> {
  reportShellTelemetry({ payload: { kind: 'action', id: action === 'start' ? 'start_site' : 'stop_site' } });
  const result = await performPowerAction(action, id, bridge);
  if (result.error !== undefined) return result.error;
  onSiteUpdated?.(result.record);
  if (action === 'start' && result.record.status === 'running') onStarted?.(id);
  return null;
}

/** Decide whether this press is inert, asks permission, or performs the existing power action.
 * Pure: reads the synchronous lock without changing it; no effects or errors.
 * @complexity O(1) time and space.
 */
export function powerToggleIntent({ action, project, inFlight, confirmed }: {
  action: SitePowerAction | null | undefined;
  project: SiteRecord;
  inFlight: ReadonlySet<string>;
  confirmed: boolean;
}, _options = {}): SitePowerAction | 'confirm-stop' | null {
  // `null` covers both "nothing to do for this status" and "a transition is already running",
  // so a second click during a stop cannot queue a second one behind it.
  if (action === undefined || action === null || inFlight.has(project.id)) return null;
  // Another process serves this site, so Stop ends THAT process: ask first. See `externalStopConfirm`.
  if (action === 'stop' && project.externalUrl && !confirmed) return 'confirm-stop';
  return action;
}

/**
 * @param onSiteUpdated applies the refreshed record main resolves with. Optional, and the card is
 *   still correct without it — the 4 s poll would catch up — but up to four seconds of showing a
 *   stopped site as running is exactly the lie this control exists not to tell, so `App.tsx` wires
 *   it. The record is main's, never one composed here from what was clicked.
 * @param onStarted the card's open callback; a Start that comes back running calls it with the
 *   site's id. See {@link runPowerToggle}.
 * @returns the three things a card needs: the status to render, the failure to show, the click.
 * @complexity O(1) per call; the two maps hold one entry per site with an unsettled action.
 */
export function useSitePower(
  onSiteUpdated?: (record: SiteRecord) => void,
  { onStarted, getBridge = runnerInventoryBridge }: Pick<SitePowerCallbacks, 'onStarted'> & {
    /** The bridge port, read at press time; defaults to the preload's `window.tovuRunner`. */
    getBridge?: () => Parameters<typeof performPowerAction>[2];
  } = {},
): SitePower {
  const [pending, setPending] = useState<Readonly<Record<string, SitePowerOperation>>>({});
  const [errors, setErrors] = useState<Readonly<Record<string, string>>>({});
  // A stable lock independent of React's batched render: a fast second click uses the old closure.
  // useState's lazy initializer preserves the Set for this hook's lifetime without scheduling it.
  const [inFlight] = useState(() => new Set<string>());
  const [confirmingStopId, setConfirmingStopId] = useState<string | null>(null);

  const statusOf = useCallback(
    (project: SiteRecord) => {
      const action = pending[project.id];
      return action === undefined ? project.status : action === 'restart' ? 'starting' : IN_FLIGHT_STATUS[action];
    },
    [pending],
  );

  const errorOf = useCallback((id: string) => errors[id] ?? null, [errors]);

  const toggle = useCallback(
    async (project: SiteRecord, { confirmed = false }: { confirmed?: boolean } = {}) => {
      const action = powerControl(statusOf(project), { external: Boolean(project.externalUrl) && !project.externalLauncher })?.action;
      const intent = powerToggleIntent({ action, project, inFlight, confirmed });
      if (intent === null) return;
      if (intent === 'confirm-stop') {
        setConfirmingStopId(project.id);
        return;
      }

      const id = project.id;
      inFlight.add(id);
      setPending((current) => ({ ...current, [id]: intent }));
      setErrors((current) => withoutKey(current, id));

      try {
        const error = await runPowerToggle({ action: intent, id, bridge: getBridge() }, { onSiteUpdated, onStarted });
        if (error !== null) setErrors((current) => ({ ...current, [id]: error }));
      } finally {
        // Cleared on BOTH arms: a start that failed leaves the site stopped, which is what the
        // polled record already says. Holding `starting` after that would be the button remembering
        // its own press — the one thing this control must never do.
        inFlight.delete(id);
        setPending((current) => withoutKey(current, id));
      }
    },
    [onSiteUpdated, onStarted, statusOf, inFlight, getBridge],
  );

  const restartControlOf = useCallback((project: SiteRecord) => restartControl({
    project, status: statusOf(project), restarting: pending[project.id] === 'restart',
  }), [pending, statusOf]);

  const restart = useCallback(async (project: SiteRecord) => {
    if (restartControlOf(project).disabled || inFlight.has(project.id)) return;
    const id = project.id;
    inFlight.add(id);
    setPending(current => ({ ...current, [id]: 'restart' as const }));
    setErrors(current => withoutKey(current, id));
    try {
      const result = await performSiteRestart({ id, bridge: getBridge() }, { onStopped: onSiteUpdated });
      if (result.error === undefined) onSiteUpdated?.(result.record);
      else setErrors(current => ({ ...current, [id]: result.error }));
    } finally {
      inFlight.delete(id);
      setPending(current => withoutKey(current, id));
    }
  }, [inFlight, onSiteUpdated, restartControlOf, getBridge]);

  const cancelStop = useCallback(() => setConfirmingStopId(null), []);
  const confirmStop = useCallback(async (project: SiteRecord) => {
    setConfirmingStopId(null);
    await toggle(project, { confirmed: true });
  }, [toggle]);

  return { statusOf, errorOf, toggle, restart, restartControlOf, confirmingStopId, confirmStop, cancelStop };
}

/**
 * `record` without `key`, as a new object — the two maps above are replaced rather than mutated so
 * React sees the change.
 *
 * @complexity O(n) in the map's size, which is the number of sites with an action in flight.
 */
function withoutKey<T>(record: Readonly<Record<string, T>>, key: string): Record<string, T> {
  const { [key]: _removed, ...rest } = record;
  return rest;
}

/**
 * @file Fetches one project's cached preview image on demand.
 *
 * `SiteRecord.previewVersion` (`contracts/project.ts`) is a version token, never the image — see
 * that field's own doc for why `useSitesPolling`'s 4s poll cannot carry a payload. This hook is the
 * on-demand fetch that token exists to trigger: it calls `SITE_IPC_CHANNELS.preview` once per
 * distinct version rather than once per poll.
 *
 * Refetches when `previewVersion` CHANGES, not when it "increases". The token is a filesystem
 * mtime (`site-preview-store.ts`), and a restored backup or a clock-skewed capture can move it
 * backward as easily as forward — a growth check would silently keep serving a stale image in
 * exactly that case. React's dependency-array comparison (`Object.is`) already does the right thing
 * here for free; the only discipline this file owes is not "improving" it into a `>` comparison.
 *
 * `previewFetchPlan` and `nextPreviewUrl` are pulled out as plain functions — same reason
 * `folder-drop.ts` was pulled out of `App.hooks.ts`: this package has no React renderer at all (no
 * jsdom, no testing-library, no react-test-renderer), so a decision left inside a `useEffect` body
 * is untestable without one. Between them they cover every decision the effect makes; the ONE thing
 * that stays inline is the `[id, previewVersion]` dependency array itself, because a dependency
 * array is React's own wiring — there is no way to observe "did this effect re-run" without a
 * renderer to run it in.
 */
import { useEffect, useState } from 'react';
import { runnerInventoryBridge } from './runner-api.js';
import type { RunnerInventoryBridge } from './runner-api.js';

export type PreviewFetchPlan =
  | { readonly kind: 'clear' }
  | { readonly kind: 'skip' }
  | { readonly kind: 'fetch'; readonly bridge: RunnerInventoryBridge; readonly id: string };

/**
 * What this effect run should do: clear the shown preview (no capture exists for this version, so
 * any URL held from a PRIOR id/version must not keep rendering under a card it no longer belongs
 * to), skip entirely (there IS a version to show, but no desktop bridge to ask), or fetch (the
 * bridge and id to ask it with). Checked in that order — a null version wins even when a bridge is
 * present, matching what the effect must do either way: show nothing.
 *
 * @complexity O(1).
 */
export function previewFetchPlan(
  id: string,
  previewVersion: number | null,
  bridge: RunnerInventoryBridge | undefined,
): PreviewFetchPlan {
  if (previewVersion === null) return { kind: 'clear' };
  if (bridge === undefined) return { kind: 'skip' };
  return { kind: 'fetch', bridge, id };
}

/**
 * What `setUrl` should be called with once `getSitePreview` settles, or `undefined` for "call
 * nothing at all" — this effect run was cancelled (a newer `id`/`previewVersion` started a fresh
 * request) before its own came back, and a stale result must not clobber whatever the newer run is
 * about to show.
 *
 * `outcome` is the settlement itself: `{ ok: true, url }` for a resolved `getSitePreview` (`url` is
 * `null` when there is genuinely no capture yet, which renders identically to a fetch that has not
 * resolved or one that failed — see this file's own `useSitePreview` doc), `{ ok: false }` for a
 * rejected one.
 *
 * @complexity O(1).
 */
export function nextPreviewUrl(
  cancelled: boolean,
  outcome: { readonly ok: true; readonly url: string | null } | { readonly ok: false },
): string | null | undefined {
  if (cancelled) return undefined;
  return outcome.ok ? outcome.url : null;
}

/**
 * `null` until a capture exists, the fetch has not resolved yet, or the fetch failed — all three
 * render identically, as no image, which is exactly `.card__tile`'s existing fallback (the port
 * tile). The caller does not need to tell those apart: whichever it is, there is nothing to show.
 *
 * @complexity O(1) plus one IPC round trip per distinct `previewVersion`.
 */
export function useSitePreview(
  { id, previewVersion }: { id: string; previewVersion: number | null },
  { getBridge = runnerInventoryBridge }: {
    /** The bridge port; defaults to the preload's `window.tovuRunner`. Keep it stable: it is an
     *  effect dependency, so a new function each render would refetch each render. */
    getBridge?: () => RunnerInventoryBridge | undefined;
  } = {},
): string | null {
  const [url, setUrl] = useState<string | null>(null);

  useEffect(() => {
    const plan = previewFetchPlan(id, previewVersion, getBridge());
    if (plan.kind === 'clear') {
      setUrl(null);
      return;
    }
    if (plan.kind === 'skip') return;

    let cancelled = false;
    plan.bridge
      .getSitePreview(plan.id)
      .then((result) => {
        const next = nextPreviewUrl(cancelled, { ok: true, url: result });
        if (next !== undefined) setUrl(next);
      })
      .catch(() => {
        const next = nextPreviewUrl(cancelled, { ok: false });
        if (next !== undefined) setUrl(next);
      });
    return () => {
      cancelled = true;
    };
  }, [id, previewVersion, getBridge]);

  return url;
}

/**
 * @file "Rename…" — the site grid's inline rename flow, kept out of `SiteGrid.tsx` because this
 * repo keeps derived logic and async state out of `.tsx` files (same rule `SiteGrid.hooks.ts` and
 * `use-add-site.hooks.ts` already follow).
 *
 * Shaped deliberately like `useDeleteConfirmation`, its sibling in the same grid: one id saying
 * which card is in the flow, one in-flight flag, one error string from the last failed attempt.
 * Two flows that look the same on a card should read the same in the code.
 *
 * The draft name lives HERE rather than in the card, for the reason the delete flow keeps
 * `pendingId` at grid level: only one card may be renaming at a time, and state that permits two
 * would eventually show two. Opening a rename on a second card replaces the first rather than
 * stacking, which is also what the operator means by clicking it.
 *
 * `canSubmitRename`, `renameSubmission`, and `describeRenameFailure` are pulled out as plain
 * functions — same reason `folder-drop.ts` was pulled out of `App.hooks.ts`: this package has no
 * React renderer at all (no jsdom, no testing-library, no react-test-renderer), so a decision left
 * inside `useSiteRename`'s body is untestable without one. Each takes exactly what it needs as an
 * argument rather than closing over hook state, so `submitRename` below is reduced to calling them
 * and writing whatever they decide into `useState` — no decision of its own left to get wrong.
 *
 * `showsInvalidNameHint` and `renameInputKeyDown` are the rename overlay's own rules
 * (`CardRenameOverlay`, `SiteGrid.tsx`), kept here beside the state they read so the overlay carries
 * markup only.
 */
import { useEffect, useState } from 'react';
import { SITE_NAME_ERROR, siteNameError } from '../contracts/site-name.js';
import { dismissOnEscape, humanSiteError } from './site-shell-policy.js';

import { runnerInventoryBridge } from './runner-api.js';
import type { RunnerInventoryBridge } from './runner-api.js';
import type { RenameSiteInput, SiteRecord } from '../contracts/project.js';

/**
 * `validateConfig`'s bound (`apps/website/src/platform/site-dir/read-site-dir.ts`), mirrored so the
 * Save button can refuse the same names main refuses.
 *
 * **This is the first line, never the guarantee.** `site-config.ts` re-applies the identical rule
 * on the other side of the wire, because a name that slipped past here would not break the running
 * site — it would stop the NEXT boot, with an error naming a file the operator never edited.
 */
const NAME_MAX_LENGTH = 200;

/**
 * Whether `draft` is a name Tovu will still accept at the site's next boot.
 *
 * Trims BEFORE measuring, exactly as `validateConfig` does — `"   "` is empty, not length 3. A
 * check that measured first would enable Save on a name that bricks the boot.
 *
 * @complexity O(n) in the draft length.
 */
export function isValidSiteName(draft: string): boolean {
  const trimmed = draft.trim();
  return trimmed.length > 0 && trimmed.length <= NAME_MAX_LENGTH;
}

/** Whether Save should be enabled — a valid name, and nothing already in flight.
 *  @complexity O(n) in the draft length (delegates to {@link isValidSiteName}). */
export function canSubmitRename(draft: string, saving: boolean): boolean {
  return isValidSiteName(draft) && !saving;
}

/** Shown when `runnerInventoryBridge()` returns nothing — a renderer running outside Electron (a
 *  plain `vite preview`, a test harness). */
export const NO_BRIDGE_RENAME_MESSAGE = 'The desktop bridge is unavailable, so this site could not be renamed.';

export type RenameSubmission =
  | { readonly kind: 'refused'; readonly message: string }
  | { readonly kind: 'submit'; readonly bridge: RunnerInventoryBridge; readonly payload: RenameSiteInput };

/**
 * What submitting a rename should do next: refuse before calling anything (no desktop bridge is
 * reachable), or the bridge to call and the exact payload to send it. Never calls anything itself —
 * the caller acts on the result — so this is testable with a fake bridge and no hook, no state, no
 * renderer.
 *
 * @complexity O(1).
 */
export function renameSubmission(
  bridge: RunnerInventoryBridge | undefined,
  id: string,
  draft: string,
): RenameSubmission {
  if (siteNameError({ name: draft })) return { kind: 'refused', message: SITE_NAME_ERROR };
  if (bridge === undefined) return { kind: 'refused', message: NO_BRIDGE_RENAME_MESSAGE };
  return { kind: 'submit', bridge, payload: { id, name: draft } };
}

/**
 * The message to show for a rejected rename. Main's own sentence, verbatim, when it threw a real
 * `Error` — main's refusals name the fix ("1 to 200 characters once surrounding spaces are
 * removed"), and paraphrasing would drop exactly the half the operator needs, same contract
 * `use-add-site.hooks.ts` documents for its own errors. The coerced string otherwise.
 *
 * @complexity O(n) in the message length.
 */
export function describeRenameFailure(error: unknown): string {
  return humanSiteError({ error, fallback: 'Could not rename this website.' });
}

export interface SiteRenameState {
  /** The card currently being renamed, or `null`. */
  renamingId: string | null;
  draft: string;
  setDraft: (next: string) => void;
  saving: boolean;
  renameError: string | null;
  /** Whether Save should be enabled — a valid name, and nothing already in flight. */
  canSave: boolean;
  startRename: (project: SiteRecord) => void;
  cancelRename: () => void;
  submitRename: (id: string) => Promise<void>;
}

/**
 * Whether the rename overlay shows its "1 to 200 characters" hint: only for a NON-EMPTY draft Tovu
 * would reject. An empty draft shows no hint; Save stays disabled for it through `canSave`.
 *
 * @complexity O(n) in the draft length (delegates to {@link isValidSiteName}).
 */
export function showsInvalidNameHint(draft: string): boolean {
  return draft.length > 0 && !isValidSiteName(draft);
}

/**
 * The rename input's `onKeyDown`: Escape cancels, and Enter submits only when Save itself is enabled
 * (`canSave`). Every other key is left alone. A text field must own both keys here rather than let
 * the card underneath read them as "open me" — see `CardRenameOverlay`'s doc.
 *
 * `canSave` is read off the `rename` object this was built with — the same render's value the inline
 * handler it replaced closed over.
 *
 * @param rename the grid's rename state, narrowed to what the handler reads.
 * @param id the card being renamed, handed to `submitRename`.
 * @returns the handler; composing key events leave the in-progress text untouched.
 * @complexity O(1).
 */
export function renameInputKeyDown(
  rename: Pick<SiteRenameState, 'canSave' | 'cancelRename' | 'submitRename'>,
  id: string,
): (event: { key: string; isComposing?: boolean; nativeEvent?: { isComposing?: boolean }; keyCode?: number }) => void {
  return (event) => {
    if (event.isComposing || event.nativeEvent?.isComposing || event.keyCode === 229) return;
    if (event.key === 'Escape') rename.cancelRename();
    if (event.key === 'Enter' && rename.canSave) void rename.submitRename(id);
  };
}

/**
 * Drive the grid's rename flow.
 *
 * @param onRenamed called after a successful rename so the caller can refresh its list. The record
 *   main returns is handed over rather than re-fetched — main already built it, and a second
 *   `list` round trip would let the card show a stale name for a frame.
 */
export function useSiteRename(
  onRenamed?: (record: SiteRecord) => void,
  { getBridge = runnerInventoryBridge }: {
    /** The bridge port, read at submit time; defaults to the preload's `window.tovuRunner`. */
    getBridge?: () => RunnerInventoryBridge | undefined;
  } = {},
): SiteRenameState {
  const [renamingId, setRenamingId] = useState<string | null>(null);
  const [draft, setDraft] = useState('');
  const [saving, setSaving] = useState(false);
  const [renameError, setRenameError] = useState<string | null>(null);

  const startRename = (project: SiteRecord) => {
    setRenameError(null);
    // Seeded with the CURRENT name, so the common edit (fix a typo, add a word) starts from what is
    // there rather than from an empty field the operator has to retype.
    setDraft(project.displayName);
    setRenamingId(project.id);
  };

  const cancelRename = () => {
    setRenamingId(null);
    setRenameError(null);
  };

  useEffect(() => {
    if (!renamingId) return;
    const onEscape = (event: KeyboardEvent) => dismissOnEscape({ event, dismiss: cancelRename, busy: saving });
    document.addEventListener('keydown', onEscape, true);
    return () => document.removeEventListener('keydown', onEscape, true);
  }, [renamingId, saving]);

  const submitRename = async (id: string) => {
    const decision = renameSubmission(getBridge(), id, draft);
    if (decision.kind === 'refused') {
      // Set the error WITHOUT ever setting `saving` — a call that never reached the bridge did not
      // start, and a spinner for work that is not happening is a lie. Same reasoning
      // `useProjectStart` documents for its own missing-bridge arm.
      setRenameError(decision.message);
      return;
    }
    setSaving(true);
    setRenameError(null);
    try {
      const record = await decision.bridge.renameSite(decision.payload);
      setRenamingId(null);
      onRenamed?.(record);
    } catch (err) {
      setRenameError(describeRenameFailure(err));
    } finally {
      setSaving(false);
    }
  };

  return {
    renamingId,
    draft,
    setDraft,
    saving,
    renameError,
    canSave: canSubmitRename(draft, saving),
    startRename,
    cancelRename,
    submitRename,
  };
}

/**
 * @file One project tab's toolbar: which surface the tab asked for, where its guest actually is,
 * whether it can go back or forward, and how Reload, the view toggle and Cmd+[ / Cmd+] reach the
 * guest.
 *
 * **Reload keeps history.** A healthy guest reloads through `webview.reload()`, which leaves its
 * session history alone. Remounting the `<webview>` (a `reloadNonce` bump, which is its `key`)
 * throws that history away with the process, so it is kept only for the case it was built for:
 * recovering a guest that FAILED or STALLED (`useWebviewLoadFailure`), or one that cannot take an
 * imperative call yet. A soft load still changes `loadResetKey`, so the stall timer re-arms for it
 * exactly as it did when every reload was a remount.
 *
 * **`view` is what was asked for; `liveUrl` is where the guest is.** Back and Forward can cross
 * between the admin and the public site, and `src` must not be rewritten to follow them: changing
 * `src` is itself a navigation, and it would wipe the forward stack the operator just made. So the
 * toggle's highlight and the url text follow `liveUrl`, `src` follows `view`, and choosing the
 * surface `src` already names loads it with `loadURL` because re-setting `src` would do nothing.
 *
 * Every decision is a plain exported function (the reducer, `createWorkspaceActions`,
 * `trackGuestNavigation`, `subscribeSiteHistory`), so `use-site-workspace.hooks.test.ts` covers
 * them with a fake guest. This package has no React renderer; `useSiteWorkspace` only wires them to
 * `useReducer` and two effects.
 */
import { useEffect, useReducer, useState, type Dispatch } from 'react';
import { useWebviewLoadFailure } from './App.hooks.js';
import { runnerInventoryBridge, type RunnerInventoryBridge } from './runner-api.js';
import type { SiteHistoryCommand, SiteRecord, SiteSurface } from '../contracts/project.js';
import { subscribeWorkspaceThemePreview } from './site-theme-preview.hooks.js';
import { sitePortPresentation } from './site-port.rules.js';
import { SITE_ADMIN_PAGES, type SiteAdminPage } from './import-site-entry.js';

/** Whether the guest's own session history has an entry either side of the current one. */
export interface SiteHistory {
  readonly canGoBack: boolean;
  readonly canGoForward: boolean;
}

const NO_HISTORY: SiteHistory = { canGoBack: false, canGoForward: false };

/** The slice of Electron's `<webview>` this file drives. A fake of it is what the tests pass. */
export type WorkspaceGuest = Pick<
  HTMLWebViewElement,
  'canGoBack' | 'canGoForward' | 'goBack' | 'goForward' | 'reload' | 'reloadIgnoringCache' | 'loadURL' | 'addEventListener' | 'removeEventListener'
>;

export interface SiteWorkspaceState {
  /** The surface the toggle last asked for. `src` is built from this, and only this. */
  readonly view: SiteSurface;
  /** The `<webview>`'s `key`. Bumping it remounts the guest, which is recovery, not reload. */
  readonly reloadNonce: number;
  /** Imperative loads (`reload()`, `loadURL()`) that kept the guest. Only feeds `loadResetKey`. */
  readonly softLoads: number;
  /** The main frame's url as the guest last reported it; `null` until it reports one. */
  readonly liveUrl: string | null;
  readonly history: SiteHistory;
}

export const initialSiteWorkspaceState: SiteWorkspaceState = {
  view: 'admin',
  reloadNonce: 0,
  softLoads: 0,
  liveUrl: null,
  history: NO_HISTORY,
};

export type SiteWorkspaceAction =
  | { type: 'select-view'; view: SiteSurface }
  | { type: 'remount' }
  | { type: 'soft-load' }
  /** `url` is `null` for a subframe's in-page navigation: it moves history, not the main url. */
  | { type: 'navigated'; url: string | null; history: SiteHistory }
  | { type: 'guest-changed'; history: SiteHistory };

/**
 * @complexity O(1).
 */
export function siteWorkspaceReducer(state: SiteWorkspaceState, action: SiteWorkspaceAction): SiteWorkspaceState {
  switch (action.type) {
    case 'select-view':
      // Highlight the choice at once; the guest's next `did-navigate` says where it really landed.
      return { ...state, view: action.view, liveUrl: null };
    case 'remount':
      return { ...state, reloadNonce: state.reloadNonce + 1 };
    case 'soft-load':
      return { ...state, softLoads: state.softLoads + 1 };
    case 'navigated':
      return { ...state, liveUrl: action.url ?? state.liveUrl, history: action.history };
    case 'guest-changed':
      return { ...state, liveUrl: null, history: action.history };
  }
}

/**
 * `useWebviewLoadFailure`'s reset key. Any fresh load clears a stale failure and re-arms the stall
 * timer: a remount, a view switch, or a soft load on the guest already mounted.
 */
export function loadResetKey(state: SiteWorkspaceState): string {
  return `${state.reloadNonce}:${state.view}:${state.softLoads}`;
}

function adminPagePath(
  input: { view: SiteSurface; adminPage?: SiteAdminPage },
  _options = {},
): string {
  return input.view === 'admin' && input.adminPage ? SITE_ADMIN_PAGES[input.adminPage] : '';
}

/**
 * A surface URL, or blank when no server is running. Trailing slash on `/admin/` on purpose:
 * `/admin` answers 301, a visible flash on every open. `adminPage` (the "Import site" entry) puts
 * the admin view on one allowlisted page instead of its root. Pure; no effects or errors.
 * @complexity O(1) time and space.
 */
export function siteSurfaceUrl(
  input: { port: number | null | undefined; view: SiteSurface; status?: SiteRecord['status']; externalUrl?: string; adminPage?: SiteAdminPage },
  _optional: Record<string, never> = {},
): string {
  const page = adminPagePath(input);
  if (input.externalUrl) {
    if (input.view === "site") return new URL("/", input.externalUrl).href;
    return page ? new URL(`/admin/${page}`, input.externalUrl).href : input.externalUrl;
  }
  const { origin } = sitePortPresentation(input);
  return origin ? `${origin}${input.view === 'site' ? '/' : `/admin/${page}`}` : '';
}

/** Which surface a guest url belongs to: the admin by its path, everything else is the site. */
export function surfaceOfUrl(url: string): SiteSurface {
  const { pathname } = new URL(url);
  return pathname === '/admin' || pathname.startsWith('/admin/') ? 'admin' : 'site';
}

/** The surface on screen: the guest's own url once it has reported one, the request until then. */
function liveSurface(state: SiteWorkspaceState): SiteSurface {
  return state.liveUrl === null ? state.view : surfaceOfUrl(state.liveUrl);
}

/**
 * Reads the guest's history, or no history when there is no guest or it cannot answer yet —
 * Electron throws from every `<webview>` method until the guest is attached.
 */
export function readHistory(guest: WorkspaceGuest | null): SiteHistory {
  if (guest === null) return NO_HISTORY;
  try {
    return { canGoBack: guest.canGoBack(), canGoForward: guest.canGoForward() };
  } catch {
    return NO_HISTORY;
  }
}

/**
 * Reports every main-frame navigation's url and the history it left behind.
 *
 * Both events, because the admin is a single-page app: its router `pushState`s, which Chromium
 * records as history but reports only as `did-navigate-in-page`. A subframe's in-page navigation
 * is history too, so it refreshes the arrows, but its url is not the page's.
 *
 * @returns the teardown that detaches both listeners.
 */
export function trackGuestNavigation(guest: WorkspaceGuest, dispatch: Dispatch<SiteWorkspaceAction>): () => void {
  const onNavigate = (event: WebviewDidNavigateEvent) => {
    dispatch({ type: 'navigated', url: event.url, history: readHistory(guest) });
  };
  const onNavigateInPage = (event: WebviewDidNavigateInPageEvent) => {
    dispatch({ type: 'navigated', url: event.isMainFrame ? event.url : null, history: readHistory(guest) });
  };
  try { guest.addEventListener('did-navigate', onNavigate); } catch { /* Guest not attached. */ }
  try { guest.addEventListener('did-navigate-in-page', onNavigateInPage); } catch { /* Guest not attached. */ }
  return () => {
    try { guest.removeEventListener('did-navigate', onNavigate); } catch { /* Guest already gone. */ }
    try { guest.removeEventListener('did-navigate-in-page', onNavigateInPage); } catch { /* Guest already gone. */ }
  };
}

/**
 * One step back or forward, asked of the guest itself at the moment of the step rather than of the
 * last rendered state.
 *
 * @returns whether the guest was told to move.
 */
export function stepHistory(guest: WorkspaceGuest | null, command: SiteHistoryCommand): boolean {
  const history = readHistory(guest);
  const allowed = command === 'back' ? history.canGoBack : history.canGoForward;
  if (guest === null || !allowed) return false;
  try {
    if (command === 'back') guest.goBack();
    else guest.goForward();
    return true;
  } catch { return false; }
}

/**
 * Routes the app menu's Back/Forward (Cmd+[ / Cmd+]) to this tab. Every open tab stays mounted, so
 * only the one on screen subscribes; with no site tab showing, every tab is hidden and the
 * accelerator does nothing.
 *
 * @returns the unsubscribe, or `undefined` when this tab is hidden or there is no desktop bridge.
 */
export function subscribeSiteHistory(input: {
  bridge: RunnerInventoryBridge | undefined;
  hidden: boolean;
  guest: WorkspaceGuest | null;
}): (() => void) | undefined {
  if (input.hidden || input.bridge === undefined) return undefined;
  return input.bridge.onSiteHistory((command) => void stepHistory(input.guest, command));
}

export interface WorkspaceActions {
  reload: () => void;
  /** The recovery panels' retry: always a remount, because the guest it replaces failed. */
  recover: () => void;
  goBack: () => void;
  goForward: () => void;
  selectView: (option: SiteSurface) => void;
  openInBrowser: () => void;
}

/**
 * The toolbar's actions over one render's guest, flags and state.
 *
 * @complexity O(1) per action.
 */
export function createWorkspaceActions(input: {
  guest: WorkspaceGuest | null;
  failed: boolean;
  stalled: boolean;
  state: SiteWorkspaceState;
  dispatch: Dispatch<SiteWorkspaceAction>;
  bridge: RunnerInventoryBridge | undefined;
  siteId: string;
  port: number;
  externalUrl?: string;
}): WorkspaceActions {
  const { guest, state, dispatch } = input;
  const surface = liveSurface(state);
  const remount = () => dispatch({ type: 'remount' });
  // A guest that is not attached yet throws from `reload()`/`loadURL()`; remounting it is the only
  // load left to try.
  const loadOrRemount = (load: (target: WorkspaceGuest) => void) => {
    if (guest === null) return remount();
    try {
      load(guest);
    } catch {
      return remount();
    }
    dispatch({ type: 'soft-load' });
  };

  return {
    // Cache bypass covers external theme edits while retaining guest history.
    reload: () => (input.failed || input.stalled ? remount() : loadOrRemount((target) => target.reloadIgnoringCache())),
    recover: remount,
    goBack: () => void stepHistory(guest, 'back'),
    goForward: () => void stepHistory(guest, 'forward'),
    selectView: (option) => {
      if (option === surface) return;
      dispatch({ type: 'select-view', view: option });
      // A different `src` is the navigation. The same `src` would navigate nowhere, so load it.
      if (option !== state.view) return;
      // `loadURL` rejects when a newer navigation aborts it, which is ordinary, not a failure.
      const url = siteSurfaceUrl({ port: input.port, view: option, externalUrl: input.externalUrl });
      if (!url) return;
      loadOrRemount((target) => void target.loadURL(url).catch(() => undefined));
    },
    // An id and a surface, never a url: main rebuilds the url from the registry row. A rejection
    // means the project stopped existing, and the next poll takes the tab away.
    openInBrowser: () => void input.bridge?.openSiteExternal({ siteId: input.siteId, view: surface }).catch(() => undefined),
  };
}

/** A Web-owned server must enter main's exact-origin allowlist before a guest navigates.
 * The existing start IPC attaches when the shared lease is live; it never launches another owner.
 */
export async function prepareExternalWorkspace({ project, bridge }: {
  project: Pick<SiteRecord, 'id' | 'externalUrl'>;
  bridge: Pick<RunnerInventoryBridge, 'startSite'> | undefined;
}, _options = {}): Promise<string | null> {
  if (!project.externalUrl) return null;
  if (!bridge) throw new Error('The desktop bridge is unavailable.');
  const record = await bridge.startSite(project.id);
  const url = siteSurfaceUrl({ port: record.port, status: record.status, view: 'admin', externalUrl: record.externalUrl });
  if (url !== project.externalUrl) throw new Error('The running server changed. Wait for the site list to refresh.');
  return url;
}

export interface SiteWorkspace extends WorkspaceActions {
  /** Running status with a real port; a port-zero record never mounts a guest. */
  running: boolean;
  attachError: string | null;
  /** The guest's `src`: the requested surface's root. */
  src: string;
  /** The url to show: where the guest is, or where it was sent until it says. */
  displayUrl: string;
  /** The surface on screen, for the toggle's highlight. */
  surface: SiteSurface;
  history: SiteHistory;
  reloadNonce: number;
  failed: boolean;
  stalled: boolean;
  /** Whether the guest's admin has actually finished its FIRST load since the last mount, view
   *  switch, or soft load — `useWebviewLoadFailure`'s own flag, passed through unchanged. `false`
   *  is the window `SiteWorkspace` covers with its own loading state: the guest is mounted and
   *  navigating, but nothing is on screen for the operator to read yet. */
  loaded: boolean;
  guestRef: (node: HTMLWebViewElement | null) => void;
}

/**
 * Per tab, never lifted into `App`: every open project stays mounted at once, so a shared value
 * would move every other tab's guest too.
 */
export function useSiteWorkspace(project: SiteRecord, hidden: boolean, { adminPage, getBridge = runnerInventoryBridge }: {
  adminPage?: SiteAdminPage;
  /** The bridge port; defaults to the preload's `window.tovuRunner`. */
  getBridge?: () => RunnerInventoryBridge | undefined;
} = {}): SiteWorkspace {
  const [state, dispatch] = useReducer(siteWorkspaceReducer, initialSiteWorkspaceState);
  const [attachedUrl, setAttachedUrl] = useState<string | null>(null);
  const [attachError, setAttachError] = useState<string | null>(null);
  useEffect(() => {
    let active = true;
    setAttachedUrl(null); setAttachError(null);
    if (project.externalUrl) void prepareExternalWorkspace({ project, bridge: getBridge() }).then(
      (url) => { if (active) setAttachedUrl(url); },
      (error: unknown) => { if (active) setAttachError(error instanceof Error ? error.message : String(error)); },
    );
    return () => { active = false; };
  }, [project.id, project.externalUrl, getBridge]);
  const { failed, stalled, loaded, guest, guestRef } = useWebviewLoadFailure(loadResetKey(state));

  // A new guest node (a remount, or the guest appearing at all) has its own, empty history.
  useEffect(() => {
    dispatch({ type: 'guest-changed', history: readHistory(guest) });
    return guest === null ? undefined : trackGuestNavigation(guest, dispatch);
  }, [guest]);

  useEffect(() => subscribeSiteHistory({ bridge: getBridge(), hidden, guest }), [hidden, guest, getBridge]);

  const src = project.externalUrl && attachedUrl !== project.externalUrl ? "" : siteSurfaceUrl({ port: project.port, view: state.view, status: project.status, externalUrl: project.externalUrl, adminPage });
  useEffect(() => subscribeWorkspaceThemePreview({
    bridge: getBridge(), siteDir: project.installDir, port: project.port,
    running: src !== '', url: state.liveUrl ?? src, guest, dispatch,
  }), [project.installDir, project.port, src, state.liveUrl, guest, getBridge]);

  const actions = createWorkspaceActions({
    guest,
    failed,
    stalled,
    state,
    dispatch,
    bridge: getBridge(),
    siteId: project.id,
    port: project.port,
    externalUrl: project.externalUrl,
  });
  return {
    ...actions,
    running: src !== '',
    attachError,
    src,
    // A stopped tab can still remember the last guest URL until its ref effect runs. Hide it now.
    displayUrl: src ? state.liveUrl ?? src : '',
    surface: liveSurface(state),
    history: state.history,
    reloadNonce: state.reloadNonce,
    failed,
    stalled,
    loaded,
    guestRef,
  };
}

import { useEffect, useRef, useState, type KeyboardEvent as ReactKeyboardEvent } from 'react';
import type { SiteRecord } from '../contracts/project.js';

export function revealActiveTab({ strip }: { strip: Pick<HTMLElement, 'querySelector'> }, _optional = {}): void {
  strip.querySelector<HTMLElement>('.is-active')?.scrollIntoView({ block: 'nearest', inline: 'nearest' });
}
export function tabOverflow({ strip }: { strip: Pick<HTMLElement, 'scrollWidth' | 'clientWidth' | 'scrollLeft'> }, _optional = {}) {
  return { left: strip.scrollLeft > 1, right: strip.scrollLeft + strip.clientWidth < strip.scrollWidth - 1 };
}
/** Only the selected tab is in the tab order; a removed selection falls back to All. */
export function tabStripTabIndex(
  { activeTab, projects, tabId }: { activeTab: string | null; projects: readonly Pick<SiteRecord, 'id'>[]; tabId: string | null },
  _optional = {},
): 0 | -1 {
  const selected = projects.some((project) => project.id === activeTab) ? activeTab : null;
  return selected === tabId ? 0 : -1;
}

/** WAI-ARIA horizontal tabs: wrap arrows and activate on focus because workspaces stay mounted. */
export function navigateTabStrip(
  { strip, event }: {
    strip: Pick<HTMLElement, 'querySelectorAll'>;
    event: Pick<ReactKeyboardEvent, 'key' | 'target' | 'preventDefault' | 'altKey' | 'ctrlKey' | 'metaKey' | 'shiftKey'>;
  },
  _optional = {},
): void {
  if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
  const tabs = Array.from(strip.querySelectorAll<HTMLButtonElement>('[role="tab"]'));
  const index = tabs.findIndex((tab) => tab === event.target);
  // Close buttons and overflow arrows keep their own keyboard behaviour.
  if (index < 0) return;
  const next = nextTabIndex({ key: event.key, index, count: tabs.length });
  if (next === undefined) return;
  event.preventDefault();
  tabs[next]!.focus();
  tabs[next]!.click();
}

/** Resolve horizontal tab navigation without touching focus or activation.
 * @complexity O(1) time and space.
 */
function nextTabIndex({ key, index, count }: { key: string; index: number; count: number }, _options = {}): number | undefined {
  switch (key) {
    case 'ArrowLeft': return (index + count - 1) % count;
    case 'ArrowRight': return (index + 1) % count;
    case 'Home': return 0;
    case 'End': return count - 1;
    default: return undefined;
  }
}

/** Recheck on resize as well as selection: the active tab can leave view without a tab change. */
export function useTabStrip(
  { activeTab, projects }: { activeTab: string | null; projects: readonly SiteRecord[] },
  { ResizeObserverImpl = globalThis.ResizeObserver }: {
    /** The resize port; defaults to the browser's `ResizeObserver`. */
    ResizeObserverImpl?: typeof ResizeObserver;
  } = {},
) {
  const stripRef = useRef<HTMLDivElement>(null);
  const [overflow, setOverflow] = useState({ left: false, right: false });
  const tabKey = JSON.stringify(projects.map((project) => [project.id, project.displayName]));
  useEffect(() => {
    const strip = stripRef.current;
    if (!strip) return;
    const update = () => setOverflow(tabOverflow({ strip }));
    const reveal = () => { revealActiveTab({ strip }); update(); };
    reveal();
    const observer = new ResizeObserverImpl(reveal);
    observer.observe(strip);
    strip.addEventListener('scroll', update);
    return () => { observer.disconnect(); strip.removeEventListener('scroll', update); };
  }, [activeTab, tabKey, ResizeObserverImpl]);
  const scrollLeft = () => stripRef.current?.scrollBy({ left: -200, behavior: 'smooth' });
  const scrollRight = () => stripRef.current?.scrollBy({ left: 200, behavior: 'smooth' });
  const tabIndex = ({ tabId }: { tabId: string | null }, _options = {}) => tabStripTabIndex({ activeTab, projects, tabId }, {});
  const onKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => {
    if (stripRef.current) navigateTabStrip({ strip: stripRef.current, event }, {});
  };
  // Arrows exist only while the strip actually overflows; otherwise they read as dead controls.
  return { stripRef, overflow, showArrows: overflow.left || overflow.right, scrollLeft, scrollRight, tabIndex, onKeyDown };
}

/**
 * @file `WorkspaceChatPane`'s hook (`WorkspaceChatPane.tsx`): everything the fleet chat pane holds and every
 * handler it hands to its markup, so the component itself is markup only — this repo keeps functions
 * and raw React primitives out of `.tsx` component bodies.
 *
 * `captureFolderDrop`, `workspaceConversationView` and `WORKSPACE_RUN_CONTEXT` are plain exports
 * rather than logic inside `useWorkspaceChatPane`'s body, for the reason `use-site-rename.hooks.ts`
 * gives: this package has no React renderer, so a decision left inside a hook body cannot be tested
 * here, while a plain function can (`use-workspace-chat-pane.hooks.test.ts`).
 *
 * The pane has no call site today — see the comment at the end of `App`'s JSX, and
 * `one-chat-fab-wiring.test.ts`. It is kept for the workspace-level chat panel that replaces the
 * removed FAB.
 */
import {
  useCallback,
  useRef,
  useState,
  type Dispatch,
  type DragEvent,
  type RefObject,
  type SetStateAction,
} from 'react';
import type { ChatPaneComposerHandle, ChatPaneRunContext } from '@jini-ai/chat/react/chat-pane';
import type { ConversationListItem } from '@jini-ai/chat/react';
import {
  useConversationDeleteConfirmation,
  useRunnerConversations,
  useWorkspaceChatTransport,
  type ConversationDeleteConfirmationState,
  type UseRunnerConversations,
} from './App.hooks.js';
import { folderPathsFromDataTransfer } from './folder-drop.js';

/**
 * The picker's model/reasoning choice reaches the transport through `runContext`, not through
 * `startRun`'s own arguments: `ChatTransport.StartRunInput` carries `agentId` but nothing about how
 * that agent should be configured, and `context` is the port's designated opaque per-host payload.
 *
 * An unset `model` or `reasoning` is left out of the context entirely rather than sent as
 * `undefined`. `satisfies` rather than a `ChatPaneRunContext` annotation so the constant keeps its
 * callable type — `ChatPaneRunContext` is a union with a plain object, which a test cannot call.
 */
export const WORKSPACE_RUN_CONTEXT = (({ selection }) => ({
  ...(selection.model === undefined ? {} : { model: selection.model }),
  ...(selection.reasoning === undefined ? {} : { reasoning: selection.reasoning }),
})) satisfies ChatPaneRunContext;

/** Exactly what {@link captureFolderDrop} reads off a drop event, so a test can pass a plain object. */
export interface FolderDropEvent {
  dataTransfer: DataTransfer;
  preventDefault: () => void;
  stopPropagation: () => void;
}

/**
 * The pane's capture-phase drop handler: a drop carrying at least one FOLDER is swallowed and the
 * folder path(s) go into the composer draft as text; any other drop passes through untouched.
 *
 * Capture phase, deliberately not a bubble-phase `onDrop`: this has to see the raw event BEFORE
 * `ChatPane`'s own drop handler (buried in its tree, attached in the bubble phase) would expand a
 * dropped folder into synthesized leaf files via the `FileSystemEntry` API — see
 * `folderPathsFromDataTransfer`'s doc for why that expansion loses the folder's own path.
 *
 * Unlike an earlier version of this handler, a recovered folder path now `preventDefault`s AND
 * `stopPropagation`s instead of passing the event through: letting `ChatPane` see it is exactly
 * the bug this exists to fix (TODO.md, "Chat composer: folder drop should yield a path, not an
 * upload") — the owner dropped a folder wanting a path and got "You can attach at most 10 files
 * to one message." The path goes into the composer as TEXT via `composerHandle.insertText`
 * instead; the fleet agent already has filesystem/Bash access on this machine and can act on it
 * directly. A drop that resolves to no folder at all (a loose file, a plain text drag) is left
 * alone on purpose: `ChatPane` now has `uploadAttachments` wired (`chat-attachments.ts`'s
 * `createLocalAttachmentUploader`), so that case is a real staged attachment, not an unhandled
 * drop — exactly the folder/file distinction this handler exists to preserve.
 *
 * @param event the drop, narrowed to the three members read.
 * @param getPathForFile the bridge's path lookup; `undefined` without a desktop bridge, which
 *   leaves every drop to `ChatPane`.
 * @param composerHandle populated by `ChatPane` once mounted. A folder drop while it is still
 *   `null` is swallowed all the same, and nothing is inserted.
 * @complexity O(n) in the number of dragged items (`folderPathsFromDataTransfer`).
 */
export function captureFolderDrop(
  event: FolderDropEvent,
  getPathForFile: ((file: File) => string) | undefined,
  composerHandle: RefObject<Pick<ChatPaneComposerHandle, 'insertText'> | null>,
): void {
  if (getPathForFile === undefined) return;
  const folders = folderPathsFromDataTransfer(event.dataTransfer, getPathForFile);
  if (folders.length === 0) return;
  event.preventDefault();
  event.stopPropagation();
  composerHandle.current?.insertText(folders.join(' '));
}

/** What `WorkspaceChatPane` hands `ConversationList` and `ChatPane` from `useRunnerConversations`. */
export interface WorkspaceConversationView {
  /** `ConversationList`'s `conversations`. */
  listItems: ConversationListItem[];
  /** Spread onto `ChatPane`: `{}` while nothing is active, so no `conversationId` prop is passed. */
  conversationIdProp: { conversationId?: string };
}

/**
 * The two values `WorkspaceChatPane` derives from `useRunnerConversations`.
 *
 * `listItems` is a shallow copy: `ConversationListItem[]` (mutable) is the package's own prop type,
 * while `useRunnerConversations` returns `readonly` for consistency with every other list in
 * `App.hooks.ts` (`useSitesPolling`'s `projects`, etc.), so the boundary copies here rather than
 * widening the hook's own contract for one caller.
 *
 * @complexity O(n) in the number of conversations (the copy).
 */
export function workspaceConversationView(
  conversations: Pick<UseRunnerConversations, 'conversations' | 'activeId'>,
): WorkspaceConversationView {
  return {
    listItems: [...conversations.conversations],
    conversationIdProp: conversations.activeId === null ? {} : { conversationId: conversations.activeId },
  };
}

export interface WorkspaceChatPaneState extends WorkspaceConversationView {
  transport: ReturnType<typeof useWorkspaceChatTransport>['transport'];
  runtimeAccess: ReturnType<typeof useWorkspaceChatTransport>['runtimeAccess'];
  workingDirectoryAccess: ReturnType<typeof useWorkspaceChatTransport>['workingDirectoryAccess'];
  uploadAttachments: ReturnType<typeof useWorkspaceChatTransport>['uploadAttachments'];
  conversations: UseRunnerConversations;
  deleteConfirmation: ConversationDeleteConfirmationState;
  /** The working-directory picker's value (native folder dialog + MRU list). */
  workingDirectory: string | null;
  setWorkingDirectory: Dispatch<SetStateAction<string | null>>;
  /** Handed to `ChatPane`, which populates it once mounted. */
  composerHandle: RefObject<ChatPaneComposerHandle | null>;
  /** The `<aside>`'s `onDropCapture` — see {@link captureFolderDrop}. */
  onDropCapture: (event: DragEvent<HTMLElement>) => void;
}

/**
 * Everything `WorkspaceChatPane` holds.
 *
 * The hooks run in the order the component itself called them before this extraction — transport,
 * conversations, delete confirmation, then the pane's own state, ref and drop callback — so moving
 * them here changed no hook's position.
 */
export function useWorkspaceChatPane(
  _input: Record<string, never> = {},
  {
    useTransport = useWorkspaceChatTransport,
    useConversations = useRunnerConversations,
    useDeleteConfirmation = useConversationDeleteConfirmation,
  }: {
    /** The three hook ports, defaulting to `App.hooks.ts`'s; each must keep its position stable. */
    useTransport?: typeof useWorkspaceChatTransport;
    useConversations?: typeof useRunnerConversations;
    useDeleteConfirmation?: typeof useConversationDeleteConfirmation;
  } = {},
): WorkspaceChatPaneState {
  const { transport, runtimeAccess, workingDirectoryAccess, getPathForFile, uploadAttachments } =
    useTransport();
  const conversations = useConversations();
  const deleteConfirmation = useDeleteConfirmation();
  // The working-directory picker (native folder dialog + MRU list) — unrelated to, and untouched
  // by, the drop handler below. A folder drop no longer feeds this: see `captureFolderDrop`'s doc.
  const [workingDirectory, setWorkingDirectory] = useState<string | null>(null);
  // Populated by `ChatPane` itself once mounted (`ChatPaneComposerHandle`, `@jini-ai/chat`). The
  // seam `captureFolderDrop` uses to write a dropped folder's path into the draft as text.
  const composerHandle = useRef<ChatPaneComposerHandle | null>(null);
  const onDropCapture = useCallback(
    (event: DragEvent<HTMLElement>) => captureFolderDrop(event, getPathForFile, composerHandle),
    [getPathForFile],
  );

  return {
    transport,
    runtimeAccess,
    workingDirectoryAccess,
    uploadAttachments,
    conversations,
    deleteConfirmation,
    ...workspaceConversationView(conversations),
    workingDirectory,
    setWorkingDirectory,
    composerHandle,
    onDropCapture,
  };
}

/**
 * @file The sites home window's Zoom In / Zoom Out / Actual Size (Cmd+Plus / Cmd+- / Cmd+0):
 * routing a command to whichever surface is actually on screen, and remembering a project tab's own
 * zoom level across reloads and relaunches.
 *
 * **Two different targets, same split `use-find-in-page.hooks.ts` documents at length for Find.**
 * When a project tab is the visible surface, its `<webview>` guest is the target — Electron's
 * `WebviewTag` exposes `getZoomLevel`/`setZoomLevel` directly on that DOM element, no IPC needed.
 * When the Projects screen itself is on screen, the target is the window's OWN top-level page,
 * reached through {@link ZoomBridge}'s `getZoomLevel`/`setZoomLevel` — synchronous calls into the
 * preload's own `webFrame`, not a main-process round trip (see the preload's own doc on why that
 * target needs no IPC here, unlike Find's). {@link resolveZoomTarget} is the one place that decides
 * which.
 *
 * **Per-site zoom persists in `localStorage`, keyed by project id.** A `<webview>`'s own zoom level
 * lives on its Chromium WebContents instance, which `key={workspace.reloadNonce}` (`App.tsx`)
 * discards and recreates on every recovery reload — so without this, a remembered zoom would reset
 * the moment a stalled site guest gets rebuilt, let alone across an app relaunch. `localStorage` is
 * the sites home window's OWN per-origin storage (a stable `file://` origin — `main.ts`'s
 * `openSitesHomeWindow` loads it via `loadFile`), so no new main-process store or IPC channel earns
 * its cost for ten bytes per site; {@link registerGuest} re-applies the stored level every time a
 * guest (re)registers, which covers both a tab switch back to an already-zoomed guest and a fresh
 * WebContents after a recovery reload — waiting on that guest's `dom-ready` when it is not attached
 * yet, since a ref callback fires at attach and every `<webview>` method throws until then
 * ({@link applyStoredZoom}). The window's own top-level zoom is deliberately NOT
 * persisted — it is shell chrome, not site content, and always starting a fresh session at 100% is
 * the same convention Chrome itself follows for its own UI zoom.
 */
import { useCallback, useEffect, useRef } from 'react';
import { runnerInventoryBridge, type RunnerInventoryBridge } from './runner-api.js';
import type { ZoomDirection } from '../contracts/zoom.js';

/** The slice of Electron's `<webview>` this file drives. A fake of it is what tests pass.
 *
 *  The two listener methods are spelled out for `'dom-ready'` alone rather than `Pick`ed like the
 *  rest: `HTMLWebViewElement`'s `addEventListener` is an OVERLOAD SET covering every webview event
 *  (`electron-webview.d.ts`), and picking it would oblige a fake to satisfy all of them. A real
 *  `<webview>` still satisfies this narrower pair, and it says exactly what zoom listens for —
 *  see {@link applyStoredZoom}. */
export type ZoomableGuest = Pick<HTMLWebViewElement, 'getZoomLevel' | 'setZoomLevel'> & {
  addEventListener(event: 'dom-ready', listener: (event: Event) => void): void;
  removeEventListener(event: 'dom-ready', listener: (event: Event) => void): void;
};

/** The slice of {@link RunnerInventoryBridge} this file drives. */
export type ZoomBridge = Pick<RunnerInventoryBridge, 'onZoomCommand' | 'getZoomLevel' | 'setZoomLevel'>;

/** The slice of `Storage` this file drives — narrow enough that a plain object satisfies it in
 *  tests, and permissive about a call that throws (a private window, or storage disabled). */
export type ZoomStorage = Pick<Storage, 'getItem' | 'setItem'>;

/** The shell's own `localStorage`, resolved at each call rather than once at render. Reading the
 *  `window.localStorage` getter can itself throw (storage denied, a sandboxed origin), so it must
 *  never run during a render — a throw there would blank the whole sites home window even when no
 *  guest or zoom command is in play. Resolved here instead, inside {@link readStoredZoom} /
 *  {@link writeStoredZoom}'s own `try`, a denied store degrades to session-only zoom. A module-level
 *  constant, so its identity is stable across renders and never re-runs the hook's effects. */
export const shellZoomStorage: ZoomStorage = {
  getItem: (key) => window.localStorage.getItem(key),
  setItem: (key, value) => window.localStorage.setItem(key, value),
};

/** Electron's own zoom-level step (`webContents.zoomIn`/`zoomOut`'s default), kept identical so
 *  this shell's custom Zoom menu (`zoom-menu.ts`) feels like the built-in one it replaces. Each
 *  step is roughly a 20% factor change; see Electron's own `WebContents.zoomLevel` doc. */
const ZOOM_STEP = 0.5;

/** `localStorage` key for one project's remembered zoom level. */
function zoomStorageKey(projectId: string): string {
  return `tovu:zoom:${projectId}`;
}

/** Which surface a zoom command should run against right now. Mirrors `use-find-in-page.hooks.ts`'s
 *  `FindTarget`, one target kind narrower: there is no `'none'` project id to carry for `'guest'`
 *  here, so the element itself doubles as its own key via the caller's own `projectId`. */
export type ZoomTarget = { kind: 'guest'; element: ZoomableGuest; projectId: string } | { kind: 'top' } | { kind: 'none' };

/**
 * Decides {@link ZoomTarget}: the visible project tab's guest when one is on screen and its element
 * has actually mounted, otherwise the window's own top-level page — as long as a bridge exists to
 * reach it (never true outside a real desktop window). `'none'` only when neither is available.
 *
 * @complexity O(1) — one `Map.get`.
 */
export function resolveZoomTarget(input: {
  activeGuestId: string | null;
  guests: ReadonlyMap<string, ZoomableGuest>;
  bridge: ZoomBridge | undefined;
}): ZoomTarget {
  if (input.activeGuestId !== null) {
    const element = input.guests.get(input.activeGuestId);
    if (element) return { kind: 'guest', element, projectId: input.activeGuestId };
  }
  return input.bridge ? { kind: 'top' } : { kind: 'none' };
}

/** One command's new zoom level. `'reset'` returns to 0 (100%) outright; `'in'`/`'out'` step by
 *  {@link ZOOM_STEP} from `current`. Chromium itself clamps the result to its own zoom range, so
 *  this does not — a cap here could only ever be looser or stricter than the real one underneath. */
export function nextZoomLevel(current: number, direction: ZoomDirection): number {
  if (direction === 'reset') return 0;
  return direction === 'in' ? current + ZOOM_STEP : current - ZOOM_STEP;
}

/** Reads a persisted per-project zoom level, defaulting to 0 (100%) for an unset, corrupt, or
 *  unreadable entry — never throws, since a lost preference is a cosmetic regression and a thrown
 *  read must not be.
 *  @complexity O(1). */
export function readStoredZoom(storage: ZoomStorage, projectId: string): number {
  try {
    const raw = storage.getItem(zoomStorageKey(projectId));
    const parsed = raw === null ? NaN : Number(raw);
    return Number.isFinite(parsed) ? parsed : 0;
  } catch {
    return 0;
  }
}

/** Persists one project's zoom level. Best-effort: a full or disabled store must not break zooming
 *  for the rest of the session, only the memory of it.
 *  @complexity O(1). */
export function writeStoredZoom(storage: ZoomStorage, projectId: string, level: number): void {
  try {
    storage.setItem(zoomStorageKey(projectId), String(level));
  } catch {
    // Storage full, disabled, or a private window with no persistence — zoom still applies this
    // session; there is nothing more useful to do with the failure.
  }
}

/** Sets a guest's zoom level, reporting whether it landed rather than throwing when it did not.
 *  Electron's `<webview>` throws from EVERY method until the guest is attached to the DOM and has
 *  emitted `dom-ready` — the same tolerance `use-find-in-page.hooks.ts` and
 *  `use-site-workspace.hooks.ts` already wrap their own guest calls in. */
function setGuestZoom(element: ZoomableGuest, level: number): boolean {
  try {
    element.setZoomLevel(level);
    return true;
  } catch {
    return false;
  }
}

/** A guest's current zoom level, or `null` when it cannot answer yet — same not-attached-yet gate
 *  as {@link setGuestZoom}. */
function readGuestZoom(element: ZoomableGuest): number | null {
  try {
    return element.getZoomLevel();
  } catch {
    return null;
  }
}

/**
 * Applies a project's remembered zoom to a guest that has just (re)registered, deferring to the
 * guest's `dom-ready` when it is not attached yet.
 *
 * **This runs inside a React ref callback, so it must not throw.** A `<webview>` is attached to the
 * DOM before it is usable, and the ref fires at attach — every method on it throws until
 * `dom-ready`, and a throw escaping a ref callback unmounts the tree, blanking the whole sites home
 * window the moment a project tab mounts. Swallowing alone would not do, either: the ref is the
 * ONLY moment a registration happens, so a swallowed first attempt would quietly retire per-site
 * zoom memory altogether. Hence the one-shot `dom-ready` wait — the level is deferred, not lost.
 *
 * @complexity O(1). At most one listener per registration, removed the first time it fires.
 */
export function applyStoredZoom(element: ZoomableGuest, projectId: string, storage: ZoomStorage): void {
  const level = readStoredZoom(storage, projectId);
  if (setGuestZoom(element, level)) return;
  const onReady = () => {
    element.removeEventListener('dom-ready', onReady);
    setGuestZoom(element, level);
  };
  element.addEventListener('dom-ready', onReady);
}

/**
 * Runs one zoom command against `target`, persisting the result when the target is a guest.
 *
 * @complexity O(1).
 */
export function applyZoomCommand(target: ZoomTarget, bridge: ZoomBridge | undefined, direction: ZoomDirection, storage: ZoomStorage): void {
  if (target.kind === 'guest') {
    // A command that arrives before the guest is attached does nothing — see {@link setGuestZoom}.
    // Nothing is persisted in that case either: a remembered level the guest never took would be
    // re-applied on its next registration and silently shift the site under the owner.
    const current = readGuestZoom(target.element);
    if (current === null) return;
    const level = nextZoomLevel(current, direction);
    if (setGuestZoom(target.element, level)) writeStoredZoom(storage, target.projectId, level);
    return;
  }
  if (target.kind === 'top' && bridge) {
    bridge.setZoomLevel(nextZoomLevel(bridge.getZoomLevel(), direction));
  }
}

export interface UseZoom {
  /** Wired into every mounted project tab's `<webview>` ref, composed with the tab's own `guestRef`
   *  and Find's `registerGuest` the same way `useComposedGuestRef` already composes those two — see
   *  `App.tsx`'s `SiteWorkspace`. `null` deregisters (the tab closed or its guest remounted); a
   *  non-null registration immediately re-applies that project's stored zoom, which is what makes a
   *  remembered zoom survive a recovery reload's fresh `<webview>` instance. */
  registerGuest: (projectId: string, element: ZoomableGuest | null) => void;
}

/**
 * The Zoom feature's whole runtime behaviour: subscribing to the app menu's command and routing it
 * to whichever surface is on screen, plus re-applying a project's remembered zoom whenever its guest
 * (re)mounts.
 *
 * @param activeGuestId the visible project tab's id, or `null` when the Projects screen itself is on
 *   screen (`App`'s `showSiteTab ? visibleWorkspaceId : null` — identical argument to
 *   `useFindInPage`'s).
 * @complexity O(1) per command, beyond `applyZoomCommand`'s own cost.
 */
export function useZoom(
  activeGuestId: string | null,
  { bridge = runnerInventoryBridge(), storage = shellZoomStorage }: {
    /** The bridge port; defaults to the preload's `window.tovuRunner`. */
    bridge?: RunnerInventoryBridge | undefined;
    /** Where per-site zoom levels persist; defaults to {@link shellZoomStorage}, the shell's own
     *  `localStorage` resolved lazily. */
    storage?: ZoomStorage;
  } = {},
): UseZoom {
  // A ref, not state, for the same reason `useFindInPage`'s own `guests` map is: registering a
  // guest must never itself trigger a render, and the map's contents are only ever read at the
  // moment a command actually runs.
  const guests = useRef(new Map<string, ZoomableGuest>()).current;

  const registerGuest = useCallback(
    (projectId: string, element: ZoomableGuest | null) => {
      if (element) {
        guests.set(projectId, element);
        applyStoredZoom(element, projectId, storage);
      } else {
        guests.delete(projectId);
      }
    },
    [guests, storage],
  );

  // The app menu's Zoom In / Zoom Out / Actual Size: resolve the live target at the moment the
  // command fires (not when this effect was set up), so a tab switch since the last render is
  // still honored.
  useEffect(() => {
    if (!bridge) return undefined;
    return bridge.onZoomCommand((direction) => {
      const target = resolveZoomTarget({ activeGuestId, guests, bridge });
      applyZoomCommand(target, bridge, direction, storage);
    });
    // `guests` is a ref (stable identity, never itself a trigger); `activeGuestId` is what actually
    // changes which entry a fired command should resolve to.
  }, [bridge, activeGuestId, guests, storage]);

  return { registerGuest };
}

/**
 * @file A repeating timer that only runs while the window is visible.
 *
 * An idle app must not keep working for nobody: a poll that keeps firing while the window is
 * minimized, on another Space, or fully covered wakes the renderer and main (and whatever main does
 * per tick) for a screen no one can see. This stops the timer on `visibilitychange` → hidden and,
 * on → visible, ticks once at once (so a shown window is never a whole period stale) and restarts it.
 *
 * Plain function, not a hook, so it is testable without a DOM; `useSitesPolling` is its caller.
 */

/** The slice of `document` this reads. */
export interface VisibilitySource {
  readonly visibilityState: DocumentVisibilityState;
  addEventListener(type: "visibilitychange", listener: () => void): void;
  removeEventListener(type: "visibilitychange", listener: () => void): void;
}

/** The two timer functions this uses, injectable for tests. */
export interface IntervalTimers {
  setInterval(callback: () => void, ms: number): unknown;
  clearInterval(handle: unknown): void;
}

const WINDOW_TIMERS: IntervalTimers = {
  setInterval: (callback, ms) => globalThis.setInterval(callback, ms),
  clearInterval: (handle) => globalThis.clearInterval(handle as ReturnType<typeof globalThis.setInterval>),
};

/**
 * Call `tick` every `periodMs` while `doc` is visible. Does not tick at start — the caller does its
 * own first load.
 *
 * @returns a stop function that clears the timer and the listener.
 * @complexity O(1) per visibility change.
 */
export function startVisibleInterval(
  tick: () => void,
  periodMs: number,
  doc: VisibilitySource = document,
  timers: IntervalTimers = WINDOW_TIMERS,
): () => void {
  let handle: unknown = null;
  const run = () => {
    if (handle === null) handle = timers.setInterval(tick, periodMs);
  };
  const halt = () => {
    if (handle !== null) timers.clearInterval(handle);
    handle = null;
  };
  const onVisibility = () => {
    if (doc.visibilityState === "hidden") return halt();
    if (handle !== null) return;
    tick();
    run();
  };

  if (doc.visibilityState !== "hidden") run();
  doc.addEventListener("visibilitychange", onVisibility);
  return () => {
    halt();
    doc.removeEventListener("visibilitychange", onVisibility);
  };
}

/**
 * `ChatTransport` over Electron IPC — the renderer half of the fleet chat.
 *
 * The port is written for a streaming transport, and Electron's `invoke` is not one. The shape that
 * closes the gap is documented on the main-process side (`main/workspace-chat-ipc.ts`); what matters
 * here is the consequence: every run's events arrive on ONE shared push channel, tagged with a
 * subscription id this module minted. So this module owns a demultiplexer — one channel listener,
 * installed once, fanning out to per-subscription records — rather than a listener per run. A
 * listener per run is how a pane that remounts mid-conversation ends up rendering every token twice.
 *
 * It is also the reducer. `@jini-ai/chat` renders `AgentEvent`s and deliberately does not know about
 * `@jini-ai/protocol`'s wire vocabulary; reducing one to the other is the transport adapter's job by
 * that package's own contract, so `translateRunEvent` below is the only place the two vocabularies
 * meet.
 */
import { buildTranscript } from '@jini-ai/chat/core';
import type {
  AgentEvent,
  ChatRunStatus,
  ChatTransport,
  ReattachRunOptions,
  RunHandlers,
  StartRunInput,
  ToolResultMediaBlock,
} from '@jini-ai/chat/core';
import type { RunAgentPayload, RunProtocolEvent } from '@jini-ai/protocol';
import { parseUsageEvent } from '@jini-ai/chat/core/run-events';
import { desktopVerbForAgentToolName } from '../contracts/workspace-chat.js';
import type { WorkspaceChatEventMessage, WorkspaceChatRunState } from '../contracts/workspace-chat.js';
import type { RunnerInventoryBridge } from './runner-api.js';

interface SubscriptionRecord {
  readonly handlers: RunHandlers;
  readonly events: AgentEvent[];
  /**
   * Tool-use ids already rendered.
   *
   * `@jini-ai/protocol` states outright that run-event delivery is at-least-once and that the
   * client reducer deduplicates, so this is the reducer holding up its end — and it is not
   * theoretical: `@jini-ai/agent-runtime`'s Claude stream parser emits each `tool_use` twice
   * (once from the streaming `content_block_stop`, once again from the `assistant` wrapper, whose
   * `streamedToolUseIds` guard misses when the wrapper itself arrives twice). Verified live against
   * Claude Code 2.1.221: two distinct log cursors, identical `toolu_…` id.
   */
  readonly renderedToolUseIds: Set<string>;
  /** Agent-reported tool-use ids whose `tool_result` must be dropped too — see `translateAgentPayload`. */
  readonly mirroredToolUseIds: Set<string>;
  /** Set once the run is known. `stopRun`/`detach` need it; `startRun` learns it only after its invoke resolves. */
  runId: string | null;
  errored: boolean;
  settled: boolean;
  /** Resolves the `reattachRun` promise, which must stay pending for the life of the stream. */
  finish: (() => void) | null;
}

let nextSubscriptionSeq = 0;

/** The clock/entropy ports {@link subscriptionRandomPart} reads; defaults are the real globals. */
export interface SubscriptionEntropy {
  crypto?: { randomUUID?: () => string } | null;
  now?: () => number;
  random?: () => number;
}

/**
 * The random half of a subscription id: a UUID where the runtime has one, else a time+random token.
 * Uniqueness within this module comes from the sequence number; this part only keeps ids from two
 * transports (or two renderer reloads) from colliding in main's subscription table.
 * Pure given its ports; no errors.
 * @complexity O(1).
 */
export function subscriptionRandomPart(
  _input: Record<string, never> = {},
  { crypto = globalThis.crypto, now = Date.now, random = Math.random }: SubscriptionEntropy = {},
): string {
  return crypto?.randomUUID?.() ?? `${now().toString(36)}-${random().toString(36).slice(2)}`;
}

function mintSubscriptionId(): string {
  nextSubscriptionSeq += 1;
  return `sub-${nextSubscriptionSeq}-${subscriptionRandomPart()}`;
}

/** `@jini-ai/protocol` spells it `cancelled`; `@jini-ai/chat` spells it `canceled`. One L, one place. */
function toChatRunStatus(state: WorkspaceChatRunState): ChatRunStatus {
  switch (state) {
    case 'queued':
    case 'starting':
      return 'queued';
    case 'running':
      return 'running';
    case 'succeeded':
      return 'succeeded';
    case 'cancelled':
      return 'canceled';
    case 'failed':
      return 'failed';
  }
}

function isMediaBlock(value: unknown): value is ToolResultMediaBlock {
  if (typeof value !== 'object' || value === null) return false;
  const block = value as { type?: unknown; text?: unknown; mimeType?: unknown; data?: unknown };
  if (block.type === 'text') return typeof block.text === 'string';
  return block.type === 'image' && typeof block.mimeType === 'string' && typeof block.data === 'string';
}

function mediaBlocks(media: unknown): readonly ToolResultMediaBlock[] {
  return Array.isArray(media) ? media.filter(isMediaBlock) : [];
}

function translateStatus(payload: Extract<RunAgentPayload, { type: 'status' }>): AgentEvent | null {
  return { kind: 'status', label: payload.label, ...(payload.detail === undefined ? {} : { detail: payload.detail }) };
}

function translateTextDelta(payload: Extract<RunAgentPayload, { type: 'text_delta' }>): AgentEvent | null {
  return { kind: 'text', text: payload.delta };
}

function translateThinkingDelta(payload: Extract<RunAgentPayload, { type: 'thinking_delta' }>): AgentEvent | null {
  return { kind: 'thinking', text: payload.delta };
}

/** A bracket with no content of its own. */
function translateThinkingStart(): AgentEvent | null {
  return null;
}

/**
 * A `desktop.*` call reaches the transcript TWICE by design: once as the agent's own view of the
 * MCP call it made, and once as the `DelegatedToolBridge`'s canonical record of executing it. The
 * bridge's is the one that matters — it is the pair the deny-by-default gate actually produced,
 * and it carries the real verb name rather than the client's MCP alias — so the agent's mirror is
 * dropped here, along with the `tool_result` that will follow it.
 */
function translateToolUse(payload: Extract<RunAgentPayload, { type: 'tool_use' }>, record: SubscriptionRecord): AgentEvent | null {
  if (desktopVerbForAgentToolName(payload.name) !== undefined) {
    record.mirroredToolUseIds.add(payload.id);
    return null;
  }
  if (record.renderedToolUseIds.has(payload.id)) return null;
  record.renderedToolUseIds.add(payload.id);
  return { kind: 'tool_use', id: payload.id, name: payload.name, input: payload.input };
}

/** An ephemeral live preview the port routes through its own handler rather than the persisted event list. */
function translateToolInputDelta(payload: Extract<RunAgentPayload, { type: 'tool_input_delta' }>, record: SubscriptionRecord): AgentEvent | null {
  record.handlers.onToolInputDelta?.(payload.id, payload.name, payload.delta);
  return null;
}

function translateToolResult(payload: Extract<RunAgentPayload, { type: 'tool_result' }>, record: SubscriptionRecord): AgentEvent | null {
  if (record.mirroredToolUseIds.has(payload.toolUseId)) return null;
  const blocks = mediaBlocks(payload.media);
  return {
    kind: 'tool_result',
    toolUseId: payload.toolUseId,
    content: payload.content,
    isError: payload.isError === true,
    // `media` is `unknown` on the wire by design (`@jini-ai/protocol` sits below every feature
    // package). `@jini-ai/chat` ports the same block vocabulary, so this narrows rather than
    // reinterprets — and drops anything that is not a recognised block instead of trusting it.
    ...(blocks.length === 0 ? {} : { media: blocks }),
  };
}

// Share the usage owner with web chat, including cumulative/session cost guards.
function translateUsage(payload: Extract<RunAgentPayload, { type: 'usage' }>): AgentEvent | null {
  return parseUsageEvent({ payload: { ...payload } });
}

function translateRaw(payload: Extract<RunAgentPayload, { type: 'raw' }>): AgentEvent | null {
  return { kind: 'raw', line: payload.line };
}

type PayloadTranslator = (payload: RunAgentPayload, record: SubscriptionRecord) => AgentEvent | null;

/**
 * One entry per named wire variant, keyed by `payload.type`. Anything not listed here — `stage_*`,
 * `surface_*`, `a2ui`, `mcp-ui`, and any future addition — falls through `translateAgentPayload`'s
 * `ext` escape hatch below rather than needing its own entry, so this table only grows when a
 * variant needs REAL handling, not for every wire addition.
 */
const payloadTranslators: Record<string, PayloadTranslator> = {
  status: translateStatus as PayloadTranslator,
  text_delta: translateTextDelta as PayloadTranslator,
  thinking_delta: translateThinkingDelta as PayloadTranslator,
  thinking_start: translateThinkingStart as PayloadTranslator,
  tool_use: translateToolUse as PayloadTranslator,
  tool_input_delta: translateToolInputDelta as PayloadTranslator,
  tool_result: translateToolResult as PayloadTranslator,
  usage: translateUsage as PayloadTranslator,
  raw: translateRaw as PayloadTranslator,
};

/**
 * Reduces one `agent` wire payload to the renderable event, or to a `onToolInputDelta` side effect.
 * Returning `null` means "nothing to render". Dispatch is a lookup against `payloadTranslators`
 * rather than a switch over ten variants — each variant's own logic lives in its own named
 * `translate*` function above, independently readable and independently low-complexity.
 */
function translateAgentPayload(payload: RunAgentPayload, record: SubscriptionRecord): AgentEvent | null {
  const translator = payloadTranslators[payload.type];
  if (translator === undefined) {
    // Every remaining variant is host-specific scaffolding no producer in this app emits. Carried
    // through the `ext` escape hatch rather than dropped, so a future producer shows up in the
    // transcript instead of vanishing.
    return { kind: 'ext', name: payload.type, data: payload };
  }
  return translator(payload, record);
}

function settle(record: SubscriptionRecord): void {
  if (record.settled) return;
  record.settled = true;
  record.handlers.onDone([...record.events]);
  record.finish?.();
}

/** `stdout`/`stderr` are the raw child bytes, which the driver emits *alongside* the parsed `agent`
 *  events purely for diagnostics; `start` carries nothing to render. Rendering any of them shows
 *  every token twice. */
const NOOP_RUN_EVENT_KINDS = new Set<RunProtocolEvent['kind']>(['start', 'stdout', 'stderr']);

function applyAgentEvent(record: SubscriptionRecord, payload: RunAgentPayload): void {
  const translated = translateAgentPayload(payload, record);
  if (translated === null) return;
  record.events.push(translated);
  record.handlers.onEvent(translated);
}

function applyRunEndEvent(record: SubscriptionRecord, event: Extract<RunProtocolEvent, { kind: 'end' }>): void {
  // A failed run that never emitted an `error` event still has to surface as an error, or the pane
  // shows a turn that simply stopped mid-sentence with no explanation.
  const failedSilently = event.payload.status === 'failed' && !record.errored;
  if (failedSilently) {
    record.errored = true;
    record.handlers.onError(new Error(exitDescription(event.payload.code, event.payload.signal ?? null)));
  }
  settle(record);
}

function applyRunEvent(record: SubscriptionRecord, event: RunProtocolEvent): void {
  if (record.settled) return;
  if (NOOP_RUN_EVENT_KINDS.has(event.kind)) return;
  switch (event.kind) {
    case 'agent':
      applyAgentEvent(record, event.payload);
      return;
    case 'error':
      record.errored = true;
      record.handlers.onError(new Error(event.payload.message));
      return;
    case 'end':
      applyRunEndEvent(record, event);
      return;
  }
}

function exitDescription(code: number | null, signal: string | null): string {
  if (signal !== null) return `The agent process was terminated by ${signal}.`;
  if (code !== null) return `The agent process exited with code ${code}.`;
  return 'The agent run failed before producing a result.';
}

export interface WorkspaceChatTransport extends ChatTransport {
  /**
   * Removes the shared run-event listener and detaches every live subscription in main.
   *
   * The owner must call this when the pane unmounts. Closing the pane is NOT the same event as the
   * window being destroyed — main cleans up after the latter on its own, but a pane that opens and
   * closes ten times would otherwise leave ten listeners on the run-event channel, each still
   * holding its own `Map` of dead subscriptions, and a turn left running would keep pushing into
   * all of them.
   */
  dispose(): void;
}

interface ChatStartPayload {
  conversationId?: string;
  subscriptionId: string;
  prompt: string;
  agentId: string;
  model?: string;
  reasoning?: string;
  attachmentPaths?: readonly string[];
}

function buildChatStartPayload(subscriptionId: string, agentId: string, input: StartRunInput): ChatStartPayload {
  return {
    subscriptionId,
    prompt: buildTranscript({ history: input.history }, { targetAgentId: agentId }),
    ...(input.conversationId == null ? {} : { conversationId: input.conversationId }),
    agentId,
    ...(input.context?.['model'] === undefined ? {} : { model: String(input.context['model']) }),
    ...(input.context?.['reasoning'] === undefined ? {} : { reasoning: String(input.context['reasoning']) }),
    // `StartRunInput.attachments` is `ChatPane`'s own record of this turn's staged `+` files
    // (`chat-attachments.ts` populated their `.path` when `uploadAttachments` ran) — only their
    // paths cross into main, which is the only part `runner-daemon.ts` forwards on to the agent.
    ...(input.attachments === undefined || input.attachments.length === 0
      ? {}
      : { attachmentPaths: input.attachments.map((attachment) => attachment.path) }),
  };
}

/**
 * The user may have hit stop while the start invoke was still in flight, in which case the abort
 * already fired against a run id nobody had yet. Honour it now that we have one. Takes `bridge`
 * explicitly rather than closing over the outer one, so this stays testable independent of
 * `createWorkspaceChatTransport`'s closure.
 */
function wireCancelSignal(bridge: RunnerInventoryBridge, cancelSignal: AbortSignal | undefined, runId: string): void {
  if (cancelSignal?.aborted === true) {
    void bridge.chatStop(runId).catch(() => {});
    return;
  }
  cancelSignal?.addEventListener('abort', () => void bridge.chatStop(runId).catch(() => {}), { once: true });
}

export function createWorkspaceChatTransport(bridge: RunnerInventoryBridge): WorkspaceChatTransport {
  const records = new Map<string, SubscriptionRecord>();

  // One listener per transport instance, installed at construction. `WorkspaceChatPane` memoizes the
  // transport, so this is one registration per pane lifetime, not per turn.
  const offChatEvent = bridge.onChatEvent((message: WorkspaceChatEventMessage) => {
    const record = records.get(message.subscriptionId);
    if (record === undefined) return;
    if (message.kind === 'event') {
      applyRunEvent(record, message.event);
      return;
    }
    if (message.kind === 'closed') {
      if (message.reason !== 'terminal' && !record.settled) {
        record.errored = true;
        record.handlers.onError(
          new Error(
            message.reason === 'unknown-run'
              ? 'Runner no longer has this run; send the message again.'
              : "Runner couldn't replay this run's history; send the message again.",
          ),
        );
      }
      settle(record);
      records.delete(message.subscriptionId);
    }
  });

  function open(handlers: RunHandlers): { subscriptionId: string; record: SubscriptionRecord } {
    const subscriptionId = mintSubscriptionId();
    const record: SubscriptionRecord = {
      handlers,
      events: [],
      renderedToolUseIds: new Set(),
      mirroredToolUseIds: new Set(),
      runId: null,
      errored: false,
      settled: false,
      finish: null,
    };
    records.set(subscriptionId, record);
    return { subscriptionId, record };
  }

  /** Detaches the browser side. The run keeps going in main — that is exactly `StartRunInput.signal`'s contract. */
  function detach(subscriptionId: string): void {
    if (!records.delete(subscriptionId)) return;
    void bridge.chatDetach(subscriptionId).catch(() => {
      // The renderer is already done with this subscription; a failed teardown invoke (window
      // closing, main already torn down) has no remedy and nothing left to report to.
    });
  }

  return {
    async startRun(input: StartRunInput, handlers: RunHandlers): Promise<{ runId: string }> {
      const agentId = input.agentId;
      if (agentId === undefined || agentId === '') {
        throw new Error('Choose an agent runtime before sending a message.');
      }

      // Registered BEFORE the invoke. Main attaches its subscription inside the `start` handler, so
      // the first events can be pushed while this promise is still in flight; without the record
      // already in place they would arrive with nowhere to go.
      const { subscriptionId, record } = open(handlers);
      const alreadyDetached = input.signal.aborted;
      if (alreadyDetached) records.delete(subscriptionId);
      else input.signal.addEventListener('abort', () => detach(subscriptionId), { once: true });

      try {
        const { runId } = await bridge.chatStart(buildChatStartPayload(subscriptionId, agentId, input));
        record.runId = runId;
        // Main now owns the subscription; a pane that was already gone must detach it too.
        if (alreadyDetached) void bridge.chatDetach(subscriptionId).catch(() => {});
        wireCancelSignal(bridge, input.cancelSignal, runId);
        return { runId };
      } catch (error) {
        records.delete(subscriptionId);
        throw error;
      }
    },

    async reattachRun(runId: string, handlers: RunHandlers, options?: ReattachRunOptions): Promise<void> {
      const { subscriptionId, record } = open(handlers);
      record.runId = runId;

      // Resolves only when the stream ends — the same shape an SSE reader has, and what
      // `ReattachRunOptions.signal` exists to interrupt.
      const streamed = new Promise<void>((resolve) => {
        record.finish = resolve;
      });

      const abort = (): void => {
        detach(subscriptionId);
        record.finish?.();
      };
      if (options?.signal?.aborted === true) {
        records.delete(subscriptionId);
        return;
      }
      options?.signal?.addEventListener('abort', abort, { once: true });

      try {
        await bridge.chatReattach({ subscriptionId, runId });
      } catch (error) {
        records.delete(subscriptionId);
        throw error;
      }
      await streamed;
    },

    async fetchRunStatus(runId: string): Promise<ChatRunStatus | null> {
      const snapshot = await bridge.chatStatus(runId);
      return snapshot === null ? null : toChatRunStatus(snapshot.state);
    },

    async stopRun(runId: string): Promise<void> {
      await bridge.chatStop(runId);
    },

    dispose(): void {
      offChatEvent();
      for (const subscriptionId of [...records.keys()]) detach(subscriptionId);
    },
  };
}

/** Tovu's folder/filenames; generic resolution, locking and registry policy belong to Jini. */
import fs from "node:fs";
import { createHash } from "node:crypto";
import type { DirectoryRecord } from "@jini-ai/platform/fs";
import os from "node:os";
import path from "node:path";
import { readCatalogSite } from "./site-config.ts";
import { createDurableJsonFile, createNodeDirectoryWorkspace, createNodeDurableJsonPorts, type DurableJsonPorts } from "@jini-ai/platform/fs";

export function createSitesWorkspace(_required: Record<string, never>, { homeDir = os.homedir(), env = process.env, cwd = process.cwd(), sourceRoots, catalogRecovery = false, appDataDir, ...directoryOptions }: {
  homeDir?: string; env?: NodeJS.ProcessEnv; cwd?: string; sourceRoots?: readonly string[]; catalogRecovery?: boolean;
  appDataDir?: string;
  ports?: import("@jini-ai/platform/fs").DurableJsonPorts;
  canonicalPath?: (required: { path: string }) => string;
  platform?: NodeJS.Platform; windowsDocuments?: () => string | undefined; readText?: (file: string) => string | undefined;
} = {}) {
  const workspace = createNodeDirectoryWorkspace({ homeDir, defaultFolder: "Tovu", envName: "TOVU_SITES_HOME",
    settingsFile: path.join(homeDir, ".tovu", "sites-home.json"), registryName: "sites.json", runningName: ".tovu-running.json",
    ...(catalogRecovery ? { registryRecovery: { fixtureIdPattern: /^(?:minted-id|new-site-id)-\d+$/ } } : {}),
    userConfig: { appName: "Tovu", rootsEnvName: "TOVU_SITE_ROOTS", legacyDefaultFolder: "Tovu Sites",
      legacySettingsFile: path.join(homeDir, ".tovu", "sites-home.json"),
      sourceRoots: desktopSourceRoots({ cwd, sourceRoots }),
    } }, { env, cwd, ...directoryOptions,
      appDataDir: desktopAppDataDir({ appDataDir, env, cwd, platform: directoryOptions.platform }),
    });
  return { ...workspace, ...nestedSitesCompat({ workspace }, { ports: directoryOptions.ports }), invalidCatalogNotices: new Set<string>() };
}
export type SitesWorkspace = ReturnType<typeof createSitesWorkspace>;

/** Select Tovu checkout discovery roots only when the caller supplied no roots. O(1) disk probe. */
export function desktopSourceRoots(
  { cwd, sourceRoots }: { cwd: string; sourceRoots?: readonly string[] }, _options = {},
): readonly string[] {
  return sourceRoots ?? (fs.existsSync(path.join(cwd, "apps", "website", "src")) ? [path.join(cwd, "sites")] : []);
}

/** Resolve Tovu's inherited profile override before the Jini directory resolver. O(n) path bytes. */
export function desktopAppDataDir(
  { appDataDir, env, cwd, platform }: { appDataDir?: string; env: NodeJS.ProcessEnv; cwd: string; platform?: NodeJS.Platform }, _options = {},
): string | undefined {
  // The inherited override also reaches CLI/MCP callers without an Electron app instance.
  return appDataDir ?? (env.TOVU_DESKTOP_USER_DATA_DIR?.trim() ? (platform === "win32" ? path.win32 : path).resolve(cwd, env.TOVU_DESKTOP_USER_DATA_DIR.trim()) : undefined);
}

/** The released 0.1.14 default nested sites in Documents/Tovu/sites; desktop startup moves them back up.
 * Explicit homes (saved setting or environment override) keep their contracts and never qualify.
 * Sites the move skips (running, locked, name clash) stay discoverable without saving an extra root.
 * @complexity O(n) immediate children of the nested folder; never writes settings.
 */
function nestedSitesCompat({ workspace }: { workspace: ReturnType<typeof createNodeDirectoryWorkspace> }, { ports = createNodeDurableJsonPorts({}) }: { ports?: DurableJsonPorts } = {}) {
  const nestedSitesRoot = (_required: Record<string, never>, _options = {}) => nestedRoot({ workspace }, { ports });
  return { nestedSitesRoot, roots: (_required: Record<string, never>, _options = {}) => {
    const roots = workspace.roots({}), nested = nestedSitesRoot({});
    try {
      return nested && fs.readdirSync(nested).some((name) => fs.existsSync(path.join(nested, name, ".site-meta.json"))) ? [...new Set([...roots, nested])] : roots;
    } catch { return roots; }
  } };
}

/** The sites settings file bound to Tovu's own notices; `nestedRoot` only reads it, but a lock taken
 * on it through this handle times out with Tovu wording rather than the platform default.
 * @complexity O(1).
 */
export function sitesSettingsFile({ filePath }: { filePath: string }, { ports = createNodeDurableJsonPorts({}) }: { ports?: DurableJsonPorts } = {}) {
  return createDurableJsonFile({ ...ports, filePath,
    notices: { prefix: "Tovu sites", lockTimeout: () => "Tovu sites settings are locked." },
  });
}

function nestedRoot({ workspace }: { workspace: ReturnType<typeof createNodeDirectoryWorkspace> }, { ports }: { ports: DurableJsonPorts }): string | undefined {
  const config = workspace.config({});
  if (config.overrides.sitesHome) return undefined;
  const saved = sitesSettingsFile({ filePath: config.configPath }, { ports }).read({});
  // An unreadable setting may contain a custom pointer: discovery must not authorize a move.
  if (saved.state === "unreadable") return undefined;
  if (saved.state === "ok" && (saved.value as { sitesHome?: unknown } | null)?.sitesHome !== undefined) return undefined;
  const root = path.join(workspace.home({}), "sites");
  try {
    if (!fs.lstatSync(root).isDirectory()) return undefined;
    // A real website named "sites" is a website, never a compatibility container.
    if (fs.existsSync(path.join(root, ".site-meta.json"))) return undefined;
    return root;
  } catch { return undefined; }
}


type SitesRegistry = ReturnType<SitesWorkspace["registry"]>;

/** Merge one folder into the catalog under its marker identity, relocating a moved record.
 * Throws (ENOENT for an unmounted folder) when the entry must be skipped.
 * @complexity O(1) catalog work plus one metadata read.
 */
function shareOneDirectory(
  { workspace, registry, registered, dir, createdBy, allowRelocation }: { workspace: SitesWorkspace; registry: SitesRegistry; registered: Map<string, DirectoryRecord>; dir: string; createdBy: string; allowRelocation: boolean }, _options = {},
): void {
  // Probe the folder before tolerant config reading erases ENOENT: an unmounted MRU
  // entry must keep its import pending so the original path is retried after remount.
  const canonical = fs.realpathSync(dir);
  const { name, siteId } = readCatalogSite({ siteDir: canonical });
  const id = siteId !== undefined ? siteId : createHash("sha256").update(canonical).digest("hex");
  const previous = registered.get(id);
  if (previous && previous.path !== canonical) relocateRecord({ workspace, registry, from: previous.path, to: canonical, id, allowRelocation });
  const entry = { id, name, path: canonical, createdBy, lastOpened: null };
  registry.merge({ entries: [entry] }); registered.set(id, entry);
}

/** Move a catalog record whose marker identity now lives at `to`, unless that is a copy.
 * @complexity O(1).
 */
function relocateRecord(
  { workspace, registry, from, to, id, allowRelocation }: { workspace: SitesWorkspace; registry: SitesRegistry; from: string; to: string; id: string; allowRelocation: boolean }, _options = {},
): void {
  if (fs.existsSync(from)) throw new Error("Copied identity");
  const database = workspace.databasePath({ dir: to, id, filename: "content.db" });
  const appDataRoot = path.join(workspace.config({}).appData, "databases") + path.sep;
  // An unplugged app-data site's marker can also be a Finder copy: retain its reservation
  // until the operator explicitly uses Locate (or the stopped-site migration owner).
  if (!allowRelocation && database.startsWith(appDataRoot)) throw new Error("App-data identity needs explicit relocation");
  // The existing marker identity is the relocation proof used by Desktop's Locate/scan owner.
  registry.relocate({ from, to });
}

/** Report a skipped catalog entry once per folder, not on every poll. @complexity O(1). */
function noticeSkippedEntry({ notices, dir, report }: { notices: Set<string>; dir: string; report: (message: string) => void }, _options = {}): void {
  if (notices.has(dir)) return;
  notices.add(dir);
  report(`tovu desktop: skipped shared catalog entry ${dir}; its metadata, identity or folder is unavailable/invalid.`);
}

/** Share available Tovu folders independently; report whether a missing volume needs retry.
 * @returns True if any folder failed with ENOENT, even when later siblings succeed.
 * @complexity O(n) metadata reads and O(n * r) registry work for n folders and r records.
 */
export function shareAvailableDirectories(
  { workspace, registry, registered, dirs, createdBy, allowRelocation, notices, report }: {
    workspace: SitesWorkspace; registry: SitesRegistry; registered: Map<string, DirectoryRecord>; dirs: readonly string[];
    createdBy: string; allowRelocation: boolean; notices: Set<string>; report: (message: string) => void;
  }, _options = {},
): boolean {
  let unavailable = false;
  for (const dir of dirs) {
    try {
      shareOneDirectory({ workspace, registry, registered, dir, createdBy, allowRelocation });
      notices.delete(dir);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") unavailable = true;
      noticeSkippedEntry({ notices, dir, report });
    }
  }
  return unavailable;
}

/** Desktop keeps deletion authority/aliases locally; this catalog only owns discoverability.
 * A record for an unavailable volume retains its saved path and metadata.
 * @complexity O(n) metadata reads and O(n * r) catalog work for n directories and r records.
 */
export function shareSiteDirectories(
  { workspace, dirs, createdBy, migration, allowRelocation = false }: { workspace: SitesWorkspace; dirs: readonly string[]; createdBy: string; migration?: string; allowRelocation?: boolean }, { report = console.warn }: { report?: (message: string) => void } = {},
): DirectoryRecord[] {
  const notices = workspace.invalidCatalogNotices;
  try {
    const registry = workspace.registry({});
    if (migration && registry.hasMigration({ migration })) return registry.list({});
    const registered = new Map(registry.list({}).map((entry) => [entry.id, entry]));
    const unavailable = shareAvailableDirectories({ workspace, registry, registered, dirs, createdBy, allowRelocation, notices, report });
    // Missing-volume MRU entries are retried after remount; do not certify an incomplete import.
    if (migration && !unavailable) registry.merge({ entries: [], migration });
    return registry.list({});
  } catch {
    report("tovu desktop: shared catalog bookkeeping is unavailable; local websites remain usable.");
    return [];
  }
}

/** Attach to an existing local server without acquiring process ownership. Stop only withdraws
 * this observer; it must never signal the other application's process or enter its crash registry.
 * @complexity O(1) per liveness poll.
 */
export function attachRunningSite({ workspace, dir }: { workspace: SitesWorkspace; dir: string }, _options = {}) {
  const running = workspace.running({ path: dir }).read({});
  if (!running) return null;
  if (!["http", "https"].includes(running.scheme) || !Number.isInteger(running.port) || running.port < 0 || running.port > 65535) throw new Error("Invalid running site address. Stop the owning app and repair its lease before attaching.");
  if (!running.port) throw new Error(`Running in ${running.app} (starting). Wait for this site to finish starting.`);
  const origin = `${running.scheme}://localhost:${running.port}`;
  const timers = new Set<ReturnType<typeof setInterval>>();
  return { external: true as const, pid: running.pid, port: running.port, origin, adminUrl: `${origin}/admin/`,
    workspaceId: "", schemaVersion: 0, bootToken: null,
    async stop() { for (const timer of timers) clearInterval(timer); timers.clear(); },
    onExit(listener: (exit: { code: number | null; signal: NodeJS.Signals | null }) => void) {
      const timer = setInterval(() => {
        const current = workspace.running({ path: dir }).read({});
        if (current?.token === running.token) return;
        clearInterval(timer); timers.delete(timer); listener({ code: null, signal: null });
      }, 2000);
      timer.unref(); timers.add(timer);
    },
  };
}

/** Shared discovery/MRU is best-effort after a successful open, never server ownership. */
export function rememberSharedSiteOpen({ workspace, dir }: { workspace: SitesWorkspace; dir: string }, _options = {}): void {
  shareSiteDirectories({ workspace, dirs: [dir], createdBy: "Desktop" });
  try { workspace.registry({}).opened({ path: dir, at: new Date().toISOString() }); }
  catch { console.warn("tovu desktop: could not remember the opened website in the shared catalog."); }
}

import { shareSiteDirectories, rememberSharedSiteOpen, type SitesWorkspace } from "./shared-sites.ts";
/**
 * @file Where the desktop app's site dir — and therefore its `content.db` — lives, and how a user
 * chooses it.
 *
 * This is the question packaging cannot start without. `tovu serve <dir>` already puts `content.db`,
 * `uploads/` and `themes/` inside the site dir, so the shape is right; nothing decided *which* dir a
 * shipped app should use. A hidden dir under `app.getPath('userData')` is invisible and awkward to
 * back up, so the answer here is the one Tovu-Runner arrived at: **a folder the user picks, plus a
 * most-recently-used list so they are asked exactly once.**
 *
 * Ported from Runner's `working-directory-store.ts` + its `dialog.showOpenDialog` picker, with one
 * deliberate deviation: Runner keeps its MRU in a `runner_recent_working_directories` table inside
 * the fleet registry's SQLite database. That database exists because Runner supervises N projects.
 * A single-site shell has no such database, and adding `@jini-ai/sqlite-chat` + `better-sqlite3` to
 * `apps/desktop` to persist ten strings would buy a native dependency, an `electron-rebuild`
 * postinstall step and a second DB for nothing. The MRU is a JSON file in `userData` instead — same
 * solution, storage sized to the problem.
 *
 * No `electron` import, so all of it is testable under plain `node --test`; `main.ts` supplies the
 * `userData` path and the native folder dialog.
 */
import fs from "node:fs";
import { readCatalogSite } from "./site-config.ts";
import path from "node:path";
import { spawn as nodeSpawn } from "node:child_process";
import type { SpawnOptions } from "node:child_process";
import { finished } from "node:stream";
import type { Readable, Writable } from "node:stream";

import { buildCliSpawnPlan, buildCliEnv, parseCliErrorLine } from "./tovu-server.ts";
import { readJsonFile, quarantineUnreadableFile, withFileLock, writeJsonFileAtomic } from "./durable-json-file.ts";
import type { QuarantineNotice } from "./durable-json-file.ts";

/** Matches Runner's own quick-pick list length — an affordance, not a full history. */
const MAX_RECENT_SITE_DIRS = 10;

const STATE_FILE_NAME = "desktop-state.json";

/** How a damaged MRU file is announced on stderr — see {@link rememberSiteDir} for why starting the
 *  list over is the right answer for this file and the wrong one for `tracked-sites.ts`'. */
const RECENT_SITES_QUARANTINE_NOTICE: QuarantineNotice = {
  label: "recent-sites list",
  consequence: "the recently opened sites it listed are only in that copy now.",
};

/**
 * Every Tovu site dir has both. `read-site-dir.ts:81-86` refuses a dir missing either one
 * unconditionally — `errors.ts`'s `SITE_DIR_INVALID` doc lists the two as alternatives ("config.json
 * or .site-meta.json"), but that names which file a given failure blames, not that either alone is
 * enough. `classifySiteDir` below used to check only `SITE_MARKER_FILE`, which was looser than the
 * server: a dir with `config.json` but no `.site-meta.json` classified as `"site"`, sailed past the
 * picker, and only died once `tovu serve` actually spawned — late, not silent, but later than it
 * needed to be. Fixed 2026-09-05.
 */
const SITE_MARKER_FILE = "config.json";
const SITE_META_FILE = ".site-meta.json";

/** Raised when the user dismisses the folder picker — a cancellation, not a failure to diagnose. */
class SiteDirSelectionCancelled extends Error {}

/** `classifySiteDir`'s four possible verdicts. See that function's own doc. */
type SiteClassification = "site" | "incomplete" | "empty" | "occupied";

/** `"source"` or `"compiled"` — see `tovu-server.ts`'s `buildCliSpawnPlan`. */
type CliMode = "source" | "compiled";

/**
 * The subset of Node's `ChildProcess` surface {@link initSiteDir} touches — narrower than
 * `tovu-server.ts`'s own `SpawnedChild`, since this caller never kills or polls the child, only
 * reads its output and waits for one `exit`.
 */
interface InitChildLike {
  /** Present when spawned with a piped stdin — for Agent Plugin tokens or explicit create credentials. */
  stdin?: Writable | null;
  stdout: Readable;
  stderr: Readable;
  once(event: "exit", listener: (code: number | null) => void): void;
  once(event: "error", listener: (error: Error) => void): void;
}

/** Injectable `child_process.spawn` for {@link initSiteDir} — the test seam. */
type InitSpawnFn = (command: string, args: string[], options: SpawnOptions) => InitChildLike;

/** @returns the MRU file's path inside Electron's per-user `userData` directory. */
function stateFilePath(userDataDir: string): string {
  return path.join(userDataDir, STATE_FILE_NAME);
}

/** The persisted MRU shape — the only thing {@link readDesktopState} ever returns. */
interface DesktopState {
  recentSiteDirs: string[];
}

/** {@link readRecentSiteDirs}' answer: the list, plus whether the file it came from is damaged. */
interface RecentSiteDirsRead extends DesktopState {
  damaged: boolean;
}

/**
 * Read the persisted state, treating any unreadable or malformed file as "no state yet".
 *
 * Deliberately forgiving: this file holds a convenience list, and refusing to launch because a
 * cache got truncated would trade a real failure for a cosmetic one. Unlike
 * `tracked-sites.ts`, nothing here is salvaged out of a damaged file: every dir this list holds is
 * either already a tracked project or one folder-pick away, so recovering the cache would buy back
 * the ordering of a menu, not anything the operator made.
 *
 * @complexity O(n) in file size.
 */
function readDesktopState(statePath: string): DesktopState {
  const { recentSiteDirs } = readRecentSiteDirs(statePath);
  return { recentSiteDirs };
}

/**
 * {@link readDesktopState} plus the one fact a WRITER also needs: whether the file it is about to
 * replace is damaged, and therefore must be moved aside rather than written over.
 *
 * @complexity O(n) in file size.
 */
function readRecentSiteDirs(statePath: string): RecentSiteDirsRead {
  const read = readJsonFile(statePath);
  if (read.state === "missing") return { recentSiteDirs: [], damaged: false };
  const recent = (read.state === "ok" ? read.value : null) as { recentSiteDirs?: unknown } | null;
  if (!Array.isArray(recent?.recentSiteDirs)) return { recentSiteDirs: [], damaged: true };
  return { recentSiteDirs: recent.recentSiteDirs.filter((entry): entry is string => typeof entry === "string"), damaged: false };
}

/**
 * Replace the persisted state, atomically — a crash partway through leaves the previous file whole
 * rather than a torn one that the next launch would read as an empty list and then persist as that
 * (`durable-json-file.ts`, and `tracked-sites.ts`'s header for the full shape of that bug).
 *
 * A whole-value replace, so it takes no lock of its own; a caller that first READS this file holds
 * the lock across both halves — see {@link rememberSiteDir}, the only one there is.
 * @complexity O(n) in the MRU length.
 */
function writeDesktopState(statePath: string, state: DesktopState): void {
  writeJsonFileAtomic(statePath, state);
}

/**
 * Move `dir` to the front of the MRU list, de-duplicated and capped.
 *
 * Runs inside the cross-process lock for this file, because several instances can be opening sites
 * at once (the owner runs them on purpose) and two unlocked read-modify-writes lose whichever list
 * was read before the other was written. One list shared by every window is the point of it: "Open
 * Recent" should show what the operator opened, in whichever window they opened it.
 *
 * A damaged file is moved aside first, and the list starts over from this one dir — the policy that
 * fits a cache, and deliberately NOT `tracked-sites.ts`'s, which recovers what it can because its
 * file is the operator's own work. If it cannot be moved aside, nothing is written over it and the
 * dir is simply not remembered: this runs after a site has already been created or opened, and
 * failing that whole operation over an unwritable cache would be the cosmetic failure taking down
 * the real one.
 *
 * @returns the new list, most-recent first — what was persisted, or what would have been.
 * @complexity O(n) in the MRU length, plus the lock wait.
 */
function rememberSiteDir(statePath: string, dir: string, { workspace }: { workspace?: SitesWorkspace } = {}): string[] {
  if (workspace) {
    // Import old state before the first shared write; all later MRU reads/writes use the catalog.
    existingRecentSiteDirs(statePath, { workspace });
    rememberSharedSiteOpen({ workspace, dir });
    return existingRecentSiteDirs(statePath, { workspace });
  }
  return withFileLock(statePath, () => {
    const previous = readRecentSiteDirs(statePath);
    const recentSiteDirs = [dir, ...previous.recentSiteDirs.filter((entry) => entry !== dir)].slice(0, MAX_RECENT_SITE_DIRS);
    if (previous.damaged && !quarantineUnreadableFile(statePath, RECENT_SITES_QUARANTINE_NOTICE)) return recentSiteDirs;
    writeDesktopState(statePath, { recentSiteDirs });
    return recentSiteDirs;
  });
}

/**
 * The remembered dirs that are still real Tovu sites on disk.
 *
 * Filtered on read rather than pruned on write, because a folder can be moved, renamed or deleted
 * while the app is not running — the list is a cache of the world, and the world is what decides.
 *
 * @complexity O(n) stat calls, bounded by {@link MAX_RECENT_SITE_DIRS}.
 */
function existingRecentSiteDirs(statePath: string, { workspace }: { workspace?: SitesWorkspace } = {}): string[] {
  if (workspace) {
    const entries = shareSiteDirectories({ workspace, dirs: readDesktopState(statePath).recentSiteDirs, createdBy: "desktop-legacy", migration: `mru:${statePath}` });
    return entries.sort((a, b) => (b.lastOpened ? Date.parse(b.lastOpened) : 0) - (a.lastOpened ? Date.parse(a.lastOpened) : 0))
      .map((entry) => entry.path).filter((dir) => classifySiteDirSafely(dir) === "site").slice(0, MAX_RECENT_SITE_DIRS);
  }
  return readDesktopState(statePath).recentSiteDirs.filter((dir) => classifySiteDirSafely(dir) === "site");
}

/**
 * Which of the two required marker files are absent from `dir`. Only meaningful when `dir` exists
 * — callers check that first — and empty when both are present.
 *
 * @returns a subset of `[SITE_MARKER_FILE, SITE_META_FILE]`, in that fixed order.
 * @complexity O(1) — two `fs.existsSync` calls.
 */
function missingSiteMarkers(dir: string): string[] {
  const missing: string[] = [];
  if (!fs.existsSync(path.join(dir, SITE_MARKER_FILE))) missing.push(SITE_MARKER_FILE);
  if (!fs.existsSync(path.join(dir, SITE_META_FILE))) missing.push(SITE_META_FILE);
  return missing;
}

/**
 * Decide what a chosen folder is, in `bootSiteDir`'s terms.
 *
 * @returns `"site"` (has both `config.json` and `.site-meta.json` — `read-site-dir.ts:81-86`'s exact
 *   contract, serve it), `"incomplete"` (has exactly one of the two — a half-initialized or
 *   half-corrupted site, distinct from both a fresh folder and a real site), `"empty"` (absent or
 *   empty, `tovu init` can create a site here), or `"occupied"` (someone's real folder full of
 *   unrelated files — refuse, since `initSite` would throw `INIT_DIR_NOT_EMPTY` and serving would
 *   throw `SITE_DIR_INVALID`).
 * @complexity O(1) probes plus bounded marker reads (64 KiB each); one entry read for other dirs.
 */
function classifySiteDir(dir: string): SiteClassification {
  if (!fs.existsSync(dir)) return "empty";
  const missing = missingSiteMarkers(dir);
  if (missing.length === 0) {
    try { readCatalogSite({ siteDir: dir }); return "site"; }
    catch { return "incomplete"; }
  }
  if (missing.length === 1) return "incomplete";
  const directory = fs.opendirSync(dir);
  try { return directory.readSync() === null ? "empty" : "occupied"; }
  finally { directory.closeSync(); }
}

/**
 * {@link classifySiteDir}'s answer, or `"unreadable"` in place of the throw — the classifier as a
 * BULK-SCAN predicate rather than as an operator-picked-folder verdict.
 *
 * D-01, and the reason both forms exist. `classifySiteDir` was written for one folder the operator
 * chose in a dialog, where throwing is exactly right: the picker catches it and shows them why
 * their folder cannot be used. It was then reused, unchanged, as the filter predicate of two bulk
 * scans ({@link existingRecentSiteDirs} and `tracked-sites.ts`'s `discoverSiteDirs`) — and a
 * predicate that throws turns "one candidate out of forty is unreadable" into "the whole list
 * fails". Both scans run inside `main.ts`'s `app.whenReady()` chain, whose only handler is
 * `reportBootFailure`, and both run BEFORE any window is opened: one plain file where a remembered
 * site dir used to be, or one EACCES directory under `<repo>/sites`, showed the operator a dialog
 * and quit — with no way to fix it from inside the app, since the Rescan button never got a
 * renderer to live in.
 *
 * So this is the deliberate split rather than a change of contract: the picker path keeps the
 * throw, and every list filter asks this instead. Callers that filter to `"site"` reject
 * `"unreadable"` for free; callers that report a rejection (`resolveDevFallback`) name it.
 *
 * @returns {@link classifySiteDir}'s own values, plus `"unreadable"` when the directory cannot be
 *   examined at all — EACCES on an unreadable directory, ENOTDIR where a file has replaced one,
 *   ELOOP on a symlink cycle.
 * @complexity same as {@link classifySiteDir}.
 */
function classifySiteDirSafely(dir: string): SiteClassification | "unreadable" {
  try {
    return classifySiteDir(dir);
  } catch {
    return "unreadable";
  }
}

/** Input to {@link initSiteDir}. */
interface InitSiteDirInput {
  repoRoot: string;
  dir: string;
  name?: string;
  adminPassword?: string;
  baseEnv?: NodeJS.ProcessEnv;
  spawnFn?: InitSpawnFn;
  cliMode?: CliMode;
  /** Optional `{ [pluginId]: token }` from the create form's "Connect services" fields. Handed to
   *  `tovu init --agent-plugin-tokens-stdin` on stdin — never argv or env, which other processes can
   *  read — and checked there before anything is created. */
  agentPluginTokens?: Readonly<Record<string, string>>;
  /** Called with `tovu init`'s output once it succeeds (its `agent-plugin-tokens:` line). */
  onInitOutput?: (output: string) => void;
}

/**
 * Create a new site in `dir` by running Tovu's own `tovu init`.
 *
 * Uses the CLI rather than importing `initSite` for the same reason the rest of this shell shells
 * out: it keeps `apps/desktop` a consumer of a published contract instead of a second importer of
 * `apps/website`'s internals, so nothing under `apps/website/` has to change or stay stable for it.
 *
 * `buildCliEnv` is given `input.dir` as its site dir — NOT optional here, unlike that function's own
 * signature. `tovu init`'s import chain reaches the same module-load-time `createApp()` `tovu
 * serve` does (see `buildCliEnv`'s own doc: `program.ts` statically imports `init.js` and `serve.js`
 * both, unconditionally), so an empty `TOVU_SITE_DIR` here crashes `init` exactly the way it used to
 * crash `serve` before that fix existed — confirmed live, 2026-09-05, from a cwd with no
 * `sites/tovu-dev` (own-server mode's actual cwd): "Open Site…"/"Open Recent" onto an empty folder
 * calls this function, and used to die with an uncaught `TypeError` before `runInitCommand` ran.
 *
 * @param input.cliMode `"source"` or `"compiled"` — see `tovu-server.ts`'s `buildCliSpawnPlan`;
 *   defaults to `"compiled"` when omitted (unchanged prior behavior for any existing caller).
 * @throws {Error} carrying Tovu's own `tovu: <CODE>: <message>` line when init fails.
 * @complexity O(1) beyond `initSite`'s own cost.
 */
function initSiteDir(input: InitSiteDirInput): Promise<string> {
  const spawnFn = input.spawnFn ?? nodeSpawn as InitSpawnFn;
  const cliArgs = ["init", input.dir];
  if (input.name) cliArgs.push("--name", input.name);
  const tokens = input.agentPluginTokens ?? {};
  const withTokens = Object.keys(tokens).length > 0;
  const withPassword = input.adminPassword !== undefined;
  if (withPassword) cliArgs.push("--create-input-stdin");
  else {
    cliArgs.push("--admin-password", "tovu-dev");
    if (withTokens) cliArgs.push("--agent-plugin-tokens-stdin");
  }
  const plan = buildCliSpawnPlan({ repoRoot: input.repoRoot, cliMode: input.cliMode, cliArgs });
  // Init and serve are separate children. No inherited deployment credential may enter init;
  // a custom password travels with the tokens over stdin, never in argv or the child env.
  const initEnv = buildCliEnv({ baseEnv: input.baseEnv, siteDir: input.dir });
  delete initEnv.TOVU_ADMIN_PASSWORD;
  delete initEnv.TOVU_ADMIN_USER;

  const child = spawnFn(plan.command, plan.args, {
    env: initEnv,
    stdio: [withTokens || withPassword ? "pipe" : "ignore", "pipe", "pipe"],
  });
  const payload = initStdinPayload({ adminPassword: input.adminPassword, tokens });
  const tokenDelivery = deliverTokens(child.stdin, payload);

  return new Promise((resolve, reject) => {
    let output = "";
    child.stdout.setEncoding("utf8");
    child.stderr.setEncoding("utf8");
    child.stdout.on("data", (chunk) => (output += chunk));
    child.stderr.on("data", (chunk) => (output += chunk));
    child.once("error", reject);
    child.once("exit", (code) => {
      if (code !== 0) {
        const cliError = parseCliErrorLine(output);
        const detail = cliError === null ? output.trim() : `${cliError.code}: ${cliError.message}`;
        return reject(new Error(`tovu init failed for ${input.dir}: ${detail}`));
      }
      void tokenDelivery.then((deliveryError) => {
        if (deliveryError !== null) {
          const subject = withPassword ? "create credentials" : "Agent Plugin tokens";
          return reject(new Error(`tovu init for ${input.dir} could not receive its ${subject}: ${deliveryError.message}`));
        }
        input.onInitOutput?.(output);
        resolve(input.dir);
      });
    });
  });
}

/** Encode create credentials only for stdin; absent credentials produce no payload.
 * @complexity O(n) in the serialized token data.
 */
function initStdinPayload(
  { adminPassword, tokens }: { adminPassword: string | undefined; tokens: Readonly<Record<string, string>> }, _options = {},
): string | null {
  if (adminPassword !== undefined) return JSON.stringify({ adminPassword, agentPluginTokens: tokens });
  return Object.keys(tokens).length > 0 ? JSON.stringify(tokens) : null;
}

/**
 * Writes `payload` to `tovu init`'s stdin and settles with the write's error, or `null` once it is
 * flushed (immediately when there is nothing to write).
 *
 * A child that exits before reading its stdin — an older CLI rejecting the flag, a crash at startup —
 * turns the write into an EPIPE on the stdin stream, and a stream `error` with no listener is an
 * uncaught exception: it would take down the Electron main process. `finished` holds an `error`
 * listener on the stream for its whole life, so that error becomes this promise's value instead.
 *
 * @complexity O(1) beyond the write itself.
 */
function deliverTokens(stdin: Writable | null | undefined, payload: string | null): Promise<Error | null> {
  if (payload === null || !stdin) return Promise.resolve(null);
  const delivered = new Promise<Error | null>((resolve) => finished(stdin, (error) => resolve(error ?? null)));
  stdin.end(payload);
  return delivered;
}

/** `"init"` or `"fail"` — see {@link resolveOrInitSiteDir}'s own param doc. */
type OnMissingSite = "init" | "fail";

/** Input to {@link resolveOrInitSiteDir}. `repoRoot` is only actually required on the "empty" + "init" path. */
interface ResolveOrInitSiteDirInput {
  dir: string;
  onMissingSite: OnMissingSite;
  repoRoot?: string;
  name?: string;
  adminPassword?: string;
  baseEnv?: NodeJS.ProcessEnv;
  spawnFn?: InitSpawnFn;
  cliMode?: CliMode;
  /** See {@link InitSiteDirInput}. Used only when this call runs `tovu init`. */
  agentPluginTokens?: Readonly<Record<string, string>>;
  onInitOutput?: (output: string) => void;
}

/**
 * THE single chokepoint through which any folder becomes a servable site dir, or is refused with a
 * specific reason. Every entry point that turns an operator-named folder into a site dir — the
 * picker, "+ Create website", an env-var override — must call this rather than re-deciding for
 * itself, so the four kinds {@link classifySiteDir} distinguishes are handled identically everywhere.
 * The ONLY thing allowed to vary between call sites is `onMissingSite`, declared explicitly by each
 * one — never an accident of which branch happened to run. This is what closed the bug where the
 * picker initialized an empty folder correctly but the env-var arms handed the same empty folder
 * straight to `tovu serve`, which does not know how to create a site and dies confusingly.
 *
 * `"occupied"` and `"incomplete"` always refuse, regardless of `onMissingSite` — neither is a
 * *missing* site for the policy to have an opinion about: `"occupied"` is the WRONG folder (someone's
 * real, unrelated files) and `"incomplete"` is a corrupt/half-written one. Auto-repairing either would
 * risk data loss no policy should paper over silently.
 *
 * @param input.onMissingSite `"init"` — an EMPTY folder is a real answer to "start a new site here";
 *   run `tovu init` and return `dir`, same as {@link classifySiteDir}'s own doc on `"empty"`.
 *   `"fail"` — refuse an empty folder with a specific, informative error instead of creating anything
 *   there; for a call site that treats `dir` as a claim the site already exists (`resolveSiteDir`'s
 *   own doc: an operator override is "taken as given") rather than an invitation to create one.
 * @throws {Error} naming the exact reason: occupied, incomplete (naming which marker file(s) are
 *   missing), or — under `"fail"` only — empty.
 * @complexity O(1) beyond `classifySiteDir`'s and, for `"init"` on an empty dir, `initSiteDir`'s own cost.
 */
async function resolveOrInitSiteDir(input: ResolveOrInitSiteDirInput): Promise<string> {
  const kind = classifySiteDir(input.dir);
  if (kind === "occupied") {
    throw new Error(`${input.dir} is not a Tovu site and is not empty. Choose an empty folder to create a new site, or a folder that already contains a site (one with a ${SITE_MARKER_FILE} and a ${SITE_META_FILE}).`);
  }
  if (kind === "incomplete") {
    const missing = missingSiteMarkers(input.dir).join(" and ");
    throw new Error(`${input.dir} is missing ${missing} — it looks like a half-initialized site, not a complete one. Choose a different folder.`);
  }
  if (kind === "empty") {
    if (input.onMissingSite === "fail") {
      throw new Error(
        `${input.dir} has no Tovu site in it yet (no ${SITE_MARKER_FILE}/${SITE_META_FILE}). This folder was named directly rather than picked interactively, so Tovu will not create a site there automatically — point it at an existing site's folder, or use "Open Site…" to create a new one there yourself.`,
      );
    }
    // `repoRoot` is required by `initSiteDir` itself; every real caller on the "init" path supplies
    // one (the picker and "+ Create website" always know the repo root), so this is a non-null
    // assertion on an already-existing contract rather than a new one.
    await initSiteDir({
      repoRoot: input.repoRoot!,
      dir: input.dir,
      name: input.name,
      adminPassword: input.adminPassword,
      baseEnv: input.baseEnv,
      spawnFn: input.spawnFn,
      cliMode: input.cliMode,
      agentPluginTokens: input.agentPluginTokens,
      onInitOutput: input.onInitOutput,
    });
  }
  return input.dir;
}

/** Input to {@link adoptSiteDir}. */
interface AdoptSiteDirInput {
  sharedSites?: SitesWorkspace;
  dir: string;
  statePath: string;
  repoRoot?: string;
  name?: string;
  adminPassword?: string;
  baseEnv?: NodeJS.ProcessEnv;
  spawnFn?: InitSpawnFn;
  cliMode?: CliMode;
  /** See {@link InitSiteDirInput}. */
  agentPluginTokens?: Readonly<Record<string, string>>;
  onInitOutput?: (output: string) => void;
}

/**
 * Turn a folder the user just picked into a servable site dir, creating one if the folder is empty.
 * A thin, fixed-policy wrapper over {@link resolveOrInitSiteDir} (`onMissingSite: "init"`) — the
 * picker's and "+ Create website"'s own semantics: an empty folder IS a legitimate answer to "start a
 * new site here" when a person just chose it — plus remembering the result in the MRU, which is a
 * picker-specific concern {@link resolveOrInitSiteDir} itself has no opinion about.
 *
 * @throws {Error} see {@link resolveOrInitSiteDir}.
 * @complexity O(1) beyond {@link resolveOrInitSiteDir}'s own cost.
 */
async function adoptSiteDir(input: AdoptSiteDirInput): Promise<string> {
  await resolveOrInitSiteDir({ ...input, onMissingSite: "init" });
  rememberSiteDir(input.statePath, input.dir, { workspace: input.sharedSites });
  return input.dir;
}

/** What {@link resolveDevFallback} rejected, and why — `resolveSiteDir`'s own `pickDir` param doc. */
interface RejectedDevFallback {
  dir: string;
  kind: SiteClassification | "unreadable";
  missing?: string[];
}

/** What {@link resolveDevFallback} returns: exactly one of the two fields is set. */
interface ResolveDevFallbackResult {
  useDir: string | null;
  rejected: RejectedDevFallback | null;
}

/**
 * Classify `devFallbackDir` (step 3 of {@link resolveSiteDir}'s precedence) — split out so that
 * function's own branching stays under the complexity gate. A `null` `devFallbackDir` (the packaged
 * case, which never sets one) is the common early-out.
 *
 * @returns `{ useDir, rejected }` — never `null` itself (so callers never need optional chaining,
 *   which the complexity gate counts as its own branch), with exactly one of the two fields set:
 *   `useDir` when the fallback is itself a real site, ready to use directly; `rejected` — the exact
 *   `{ dir, kind, missing? }` shape `resolveSiteDir`'s own doc describes — naming why it was turned
 *   down, including the "nothing to try" case (`devFallbackDir` absent), which reports `rejected:
 *   null` rather than a fabricated reason.
 * @complexity O(1) beyond `classifySiteDir`'s own cost.
 */
function resolveDevFallback(devFallbackDir: string | null | undefined): ResolveDevFallbackResult {
  if (!devFallbackDir) return { useDir: null, rejected: null };
  // Safely: a candidate NOBODY picked must be turned down, never allowed to take the launch with
  // it. `resolveStartupSiteDirs` runs this inside the `whenReady()` chain (D-01).
  const kind = classifySiteDirSafely(devFallbackDir);
  if (kind === "site") return { useDir: devFallbackDir, rejected: null };
  const rejected: RejectedDevFallback = { dir: devFallbackDir, kind };
  if (kind === "incomplete" || kind === "occupied") {
    rejected.missing = missingSiteMarkers(devFallbackDir);
  }
  return { useDir: null, rejected };
}

/** `resolveSiteDir`'s own picker seam — see that function's param doc. */
type PickDirFn = (rejectedDefault: RejectedDevFallback | null) => string | null | undefined | Promise<string | null | undefined>;

/** Input to {@link resolveSiteDir}. */
interface ResolveSiteDirInput {
  sharedSites?: SitesWorkspace;
  envDir?: string;
  onMissingSite?: OnMissingSite;
  statePath: string;
  devFallbackDir?: string | null;
  repoRoot?: string;
  name?: string;
  adminPassword?: string;
  baseEnv?: NodeJS.ProcessEnv;
  spawnFn?: InitSpawnFn;
  cliMode?: CliMode;
  pickDir?: PickDirFn;
}

/**
 * Decide which site dir this launch serves.
 *
 * Precedence, most explicit first:
 * 1. `TOVU_DESKTOP_SITE_DIR` — an operator override always wins. Routed through
 *    {@link resolveOrInitSiteDir} like every other entry point, under whichever `onMissingSite`
 *    policy `input.onMissingSite` declares for this one — see this function's own param doc for why
 *    that is `"fail"` in production, not `"init"`.
 * 2. The most recent remembered folder that is still a site — so the user is asked exactly once.
 * 3. `devFallbackDir` (`<repo>/sites/tovu-dev` in a checkout), when it is a site. Correct for a
 *    developer, absent in a packaged app, which is why it cannot be the only answer. See
 *    {@link resolveDevFallback}.
 * 4. Ask, via `pickDir`. An empty folder becomes a new site; a folder of unrelated files is refused.
 *
 * @param input.onMissingSite Required — the policy step 1 declares for its OWN branch only; steps
 *   2-3 never reach an empty/incomplete/occupied dir at all (each already filters to `"site"` before
 *   returning), and step 4 (the picker) always uses `"init"` via `adoptSiteDir`. Required rather than
 *   defaulted so a call site cannot skip declaring it — the whole point of routing this branch through
 *   {@link resolveOrInitSiteDir} at all.
 * @param input.pickDir async `(rejectedDefault) => string | null`; `null` means the user
 *   cancelled. `rejectedDefault` is `null` when there was nothing to try (no `devFallbackDir`, or a
 *   packaged app that never sets one), else `{ dir, kind, missing? }` naming the candidate step 3
 *   just turned down, `classifySiteDir`'s verdict on it (`"empty"`, `"incomplete"`, or `"occupied"`),
 *   and — for `"incomplete"`/`"occupied"` — exactly which marker file(s) it lacks, so the picker can
 *   say *why* it's asking instead of just asking.
 * @param input.cliMode `"source"` or `"compiled"` — threaded through to `initSiteDir` via
 *   `adoptSiteDir` when the picked folder is empty; see `tovu-server.ts`'s `buildCliSpawnPlan`.
 * @throws {SiteDirSelectionCancelled} when the user dismisses the picker.
 * @throws {Error} see {@link resolveOrInitSiteDir} — when `envDir` is set but is not a usable site
 *   under the declared `onMissingSite` policy.
 * @complexity O(n) stat calls over the MRU, bounded by {@link MAX_RECENT_SITE_DIRS}.
 */
async function resolveSiteDir(input: ResolveSiteDirInput): Promise<string> {
  const envDir = input.envDir?.trim();
  if (envDir) {
    if (input.onMissingSite !== "init" && input.onMissingSite !== "fail") {
      throw new Error('resolveSiteDir: input.onMissingSite must be "init" or "fail" when envDir is set.');
    }
    return await resolveOrInitSiteDir({
      dir: envDir,
      onMissingSite: input.onMissingSite,
      repoRoot: input.repoRoot,
      name: input.name,
      adminPassword: input.adminPassword,
      baseEnv: input.baseEnv,
      spawnFn: input.spawnFn,
      cliMode: input.cliMode,
    });
  }

  const [mostRecent] = existingRecentSiteDirs(input.statePath, { workspace: input.sharedSites });
  if (mostRecent !== undefined) return mostRecent;

  const fallback = resolveDevFallback(input.devFallbackDir);
  if (fallback.useDir) return fallback.useDir;

  const picked = await input.pickDir!(fallback.rejected);
  if (picked === null || picked === undefined) {
    throw new SiteDirSelectionCancelled("No site folder was chosen.");
  }
  return await adoptSiteDir({
    dir: picked,
    repoRoot: input.repoRoot,
    statePath: input.statePath,
    name: input.name,
    adminPassword: input.adminPassword,
    baseEnv: input.baseEnv,
    spawnFn: input.spawnFn,
    cliMode: input.cliMode,
  });
}

export {
  MAX_RECENT_SITE_DIRS,
  SITE_MARKER_FILE,
  SITE_META_FILE,
  STATE_FILE_NAME,
  SiteDirSelectionCancelled,
  stateFilePath,
  readDesktopState,
  writeDesktopState,
  rememberSiteDir,
  existingRecentSiteDirs,
  classifySiteDir,
  classifySiteDirSafely,
  resolveDevFallback,
  initSiteDir,
  resolveOrInitSiteDir,
  adoptSiteDir,
  resolveSiteDir,
};
export type { RejectedDevFallback };

/** Tovu site discovery settings, stored in the shared config; legacy MRU-profile imports preserve discovery.
 * Atomic replacement and cross-process locking remain owned by Jini's durable JSON adapter.
 */
import fs from 'node:fs';
import path from 'node:path';
import { readJsonFile, withFileLock, writeJsonFileAtomic, quarantineUnreadableFile } from './durable-json-file.ts';
import type { SitesWorkspace } from './shared-sites.ts';
import type { SiteFolders } from './contracts/project.ts';
import { assertSpecificSiteRoot } from './site-scan-policy.ts';

interface StoredSiteFolders {
  creationRoots: string[];
  extraRoots: string[];
}

/** Native-picking IPC and discovery consume this Tovu-specific settings port. */
export interface SiteFoldersPort {
  read(required: {}, options?: {}): SiteFolders;
  add(required: { root: string }, options?: {}): SiteFolders;
  remove(required: { root: string }, options?: {}): SiteFolders;
  rememberCreated(required: { siteDir: string }, options?: {}): void;
}

/** Resolve existing root aliases once per read; absent/removable volumes keep their saved path.
 * @complexity O(n) path resolutions for n roots.
 */
function distinctRoots({ roots }: { roots: string[] }, _options = {}): string[] {
  return [...new Set(roots.map((root) => {
    try { return fs.realpathSync(root); }
    catch { return path.resolve(root); }
  }))];
}

/** Missing/damaged settings cannot prevent the Websites window opening. Preserve damaged bytes
 * before the next mutation, using the same recovery policy as the MRU.
 * @complexity O(n) in settings size.
 */
function readStoredFolders({ filePath }: { filePath: string }, _options = {}): { stored: StoredSiteFolders; damaged: boolean } {
  const result = readJsonFile(filePath);
  const value = result.state === 'ok' ? result.value as Partial<StoredSiteFolders> | null : null;
  const valid = Array.isArray(value?.creationRoots) && Array.isArray(value?.extraRoots);
  if (!valid) return { stored: { creationRoots: [], extraRoots: [] }, damaged: result.state !== 'missing' };
  return {
    stored: {
      creationRoots: value!.creationRoots!.filter((root): root is string => typeof root === 'string' && path.isAbsolute(root)),
      extraRoots: value!.extraRoots!.filter((root): root is string => typeof root === 'string' && path.isAbsolute(root)),
    },
    damaged: false,
  };
}

/** Bind discovery settings to this profile. Creation parents survive MRU eviction and card removal;
 * old creation rows contribute parents until the operator creates another site there.
 * @param required The MRU path, built-in roots and optional live legacy creation-row reader.
 * @param optional.quarantine Moves a damaged settings file aside, `false` when it could not; defaults to `quarantineUnreadableFile`.
 * @returns The settings port; mutations lock, recover and atomically write only its own JSON file.
 * @throws Filesystem errors, or an error if damaged settings cannot be preserved on mutation.
 * @example createSiteFolders({ statePath, defaultRoots: [repoSites] }).read({})
 * @complexity O(n) roots per operation, plus JSON I/O and the durable lock wait for mutations.
 */
export function createSiteFolders({ statePath, defaultRoots, createdSiteDirs = () => [], home, workspace }: {
  statePath: string;
  defaultRoots: string[];
  createdSiteDirs?: () => string[];
  home?: () => string;
  workspace?: SitesWorkspace;
}, { quarantine = quarantineUnreadableFile }: { quarantine?: typeof quarantineUnreadableFile } = {}): SiteFoldersPort {
  const filePath = path.join(path.dirname(statePath), 'desktop-site-folders.json');
  if (workspace) return sharedSiteFolders({ workspace, filePath, createdSiteDirs, quarantine });
  const read = (_required: {}, _optional = {}): SiteFolders => {
    const { stored } = readStoredFolders({ filePath });
    const sitesHome = home?.();
    return {
      ...(sitesHome ? { home: sitesHome } : {}),
      roots: distinctRoots({ roots: [...(sitesHome ? [sitesHome] : []), ...defaultRoots, ...stored.creationRoots, ...createdSiteDirs().map((dir) => path.dirname(dir)), ...stored.extraRoots] }),
      extraRoots: distinctRoots({ roots: stored.extraRoots }),
    };
  };
  /** Preserve sibling-process edits and damaged bytes across a settings mutation. */
  const update = (change: (stored: StoredSiteFolders) => StoredSiteFolders): void => {
    withFileLock(filePath, () => {
      const { stored, damaged } = readStoredFolders({ filePath });
      if (damaged && !quarantine(filePath, {
        label: 'sites folders settings', consequence: 'the previous folder settings are only in that copy now.',
      })) throw new Error(`Could not preserve damaged sites folders settings at ${filePath}. Nothing was saved.`);
      writeJsonFileAtomic(filePath, change(stored));
    });
  };
  return {
    read,
    add({ root }, _optional = {}) {
      assertSpecificSiteRoot({ root });
      const canonical = fs.realpathSync(root);
      assertSpecificSiteRoot({ root: canonical });
      if (!fs.statSync(canonical).isDirectory()) throw new Error(`Sites folder is not a directory: ${root}`);
      update((stored) => ({ ...stored, extraRoots: distinctRoots({ roots: [...stored.extraRoots, canonical] }) }));
      return read({});
    },
    remove({ root }, _optional = {}) {
      const [canonical] = distinctRoots({ roots: [root] });
      update((stored) => ({ ...stored, extraRoots: distinctRoots({ roots: stored.extraRoots }).filter((entry) => entry !== canonical) }));
      return read({});
    },
    rememberCreated({ siteDir }, _optional = {}) {
      update((stored) => ({ ...stored, creationRoots: distinctRoots({ roots: [...stored.creationRoots, path.dirname(siteDir)] }) }));
    },
  };
}

/** Import old profile roots once, then every writer uses the same app-data config as Web/CLI.
 * Discovery changes never relocate a site or database. Missing volumes retain their paths.
 * @complexity O(n) roots and legacy created rows per read, one atomic settings mutation per action.
 */
function sharedSiteFolders({ workspace, filePath, createdSiteDirs, quarantine }: {
  workspace: SitesWorkspace; filePath: string; createdSiteDirs: () => string[]; quarantine: typeof quarantineUnreadableFile;
}): SiteFoldersPort {
  const read = (): SiteFolders => {
    const config = workspace.config({});
    return { roots: workspace.roots({}), extraRoots: config.extraRoots.filter((root) => root !== config.sitesHome && !config.defaultRoots.includes(root)), home: config.sitesHome,
      databases: config.databases, warning: config.warning, configPath: config.configPath, overrides: config.overrides };
  };
  const registry = workspace.registry({});
  try {
    if (!registry.hasMigration({ migration: "desktop-roots-config-v1" })) {
      const { stored, damaged } = readStoredFolders({ filePath });
      if (damaged) {
        withFileLock(filePath, () => {
          if (readStoredFolders({ filePath }).damaged && !quarantine(filePath, {
            label: "sites folders settings", consequence: "Using shared settings; the damaged legacy bytes are preserved.",
          })) throw new Error("Could not preserve legacy settings.");
        });
      }
      const config = workspace.config({});
      if (!config.overrides.siteRoots) {
        const inherited = [...stored.extraRoots, ...stored.creationRoots, ...createdSiteDirs().map((dir) => path.dirname(dir))];
        if (inherited.length) workspace.updateRoots({ add: inherited });
        registry.merge({ entries: [], migration: "desktop-roots-config-v1" });
      }
    }
  } catch { console.warn("tovu desktop: legacy sites folder import could not complete; using shared settings and retrying next boot."); }
  return { read,
    add({ root }, _options = {}) {
      const policy = { homeDir: workspace.homeDir, sitesHome: workspace.home({}) };
      assertSpecificSiteRoot({ root }, policy);
      assertSpecificSiteRoot({ root: fs.realpathSync(root) }, policy);
      if (!fs.statSync(root).isDirectory()) throw new Error(`Sites folder is not a directory: ${root}`);
      workspace.updateRoots({ add: [root] });
      return read();
    },
    remove({ root }, _options = {}) {
      workspace.updateRoots({ remove: distinctRoots({ roots: [root] }) });
      return read();
    },
    rememberCreated({ siteDir }, _options = {}) {
      const parent = path.dirname(siteDir);
      if (workspace.roots({}).includes(parent)) return;
      workspace.updateRoots({ add: [parent] });
    },
  };
}

/**
 * @file The pure half of `scripts/verify-site-power.ts`'s live checks: the card-state shape the run
 * reads off the DOM, the three geometric layout claims (with the tolerance each one carries), the
 * flattened view the checks read, and seeding the isolated profile with the scratch site. All of it
 * is unit-tested here; the live run itself (a real Electron app driven by Playwright) is opt-in and
 * not part of `npm test`.
 */
import path from "node:path";

/** A laid-out element's edges, from `getBoundingClientRect`. */
interface Box {
  top: number;
  right: number;
  bottom: number;
  left: number;
}

/** Everything the first card is currently saying — see `cardState`. */
interface CardState {
  className: string;
  name: string | null;
  status: string;
  port: string | null;
  power: { label: string; disabled: boolean; visible: boolean } | null;
  menuVisible: boolean;
  menuInTile: boolean;
  trashOnCard: boolean;
  actionsInBody: boolean;
  layout: { name: Box | null; menu: Box | null; power: Box | null; details: Box | null; status: Box | null };
  error: string | null;
}

/** One geometric claim's verdict, with the pixels that decided it. */
interface Claim {
  ok: boolean;
  why: string;
}

interface LayoutClaims {
  onNameRow: Claim;
  powerUnderText: Claim;
  statusUnderMenu: Claim;
}

export const MISSING_BOX: Claim = { ok: false, why: 'card is missing a name, a ⋮, a database line or a status' };
/** What `layoutClaims` reports when there is no layout to read: every claim fails, and says why. */
export const NO_LAYOUT: LayoutClaims = { onNameRow: MISSING_BOX, powerUnderText: MISSING_BOX, statusUnderMenu: MISSING_BOX };

/** Vertical centre of a box — rows are centre-aligned in the head grid. */
const middle = (b: Box): number => (b.top + b.bottom) / 2;

/** "align dotes with tovu-com" — the ⋮ sits on the same row as the name, not under it. */
function onNameRow(name: Box, menu: Box): Claim {
  return {
    ok: Math.abs(middle(menu) - middle(name)) <= 4 && menu.left >= name.right,
    why: `⋮ middle ${middle(menu).toFixed(1)} vs name middle ${middle(name).toFixed(1)}; ⋮ left ${menu.left.toFixed(1)} vs name right ${name.right.toFixed(1)}`,
  };
}

/** "put the start/stop under the SQLite" — on the database line's left edge, below row 2. */
function powerUnderText(details: Box, status: Box, power: Box | null): Claim {
  if (power === null) return { ok: true, why: 'no power button for this status' };
  const rowBottom = Math.max(details.bottom, status.bottom);
  return {
    ok: Math.abs(power.left - details.left) <= 1 && power.top >= rowBottom - 1,
    why: `power left ${power.left.toFixed(1)} vs SQLite left ${details.left.toFixed(1)}; power top ${power.top.toFixed(1)} vs row 2 bottom ${rowBottom.toFixed(1)}`,
  };
}

/** "status on the right under the ⋮" — right edges shared, below the ⋮, level with "SQLite". */
function statusUnderMenu(menu: Box, details: Box, status: Box): Claim {
  return {
    ok: Math.abs(status.right - menu.right) <= 1 && status.top >= menu.bottom - 1 && Math.abs(middle(status) - middle(details)) <= 4,
    why: `status right ${status.right.toFixed(1)} vs ⋮ right ${menu.right.toFixed(1)}; status top ${status.top.toFixed(1)} vs ⋮ bottom ${menu.bottom.toFixed(1)}; status middle ${middle(status).toFixed(1)} vs SQLite middle ${middle(details).toFixed(1)}`,
  };
}

/**
 * The three geometric claims the owner's second layout makes, each with the tolerance that belongs
 * to it: sub-pixel rounding for two edges that must line up, and a real gap where one element sits
 * under another. Returns a reason per claim rather than a bare boolean, so a failure names the
 * pixels rather than sending the reader back to the screenshot.
 */
export function layoutClaims(state: CardState | null): LayoutClaims {
  const layout = state === null ? null : state.layout;
  if (!layout || !layout.name || !layout.menu || !layout.details || !layout.status) return NO_LAYOUT;
  return {
    onNameRow: onNameRow(layout.name, layout.menu),
    powerUnderText: powerUnderText(layout.details, layout.status, layout.power),
    statusUnderMenu: statusUnderMenu(layout.menu, layout.details, layout.status),
  };
}

/** True when every one of `layoutClaims`' three claims holds. */
export function allLayoutClaimsHold(claims: LayoutClaims): boolean {
  return claims.onNameRow.ok && claims.powerUnderText.ok && claims.statusUnderMenu.ok;
}

/** A card state with the optional parts flattened out, so the checks below read plain fields
 *  instead of chaining through a possibly-absent card and a possibly-absent power button. Every
 *  field is `undefined` when there was no card at all. */
interface FlatCard {
  name?: string | null;
  status?: string;
  port?: string | null;
  error?: string | null;
  menuVisible?: boolean;
  menuInTile?: boolean;
  trashOnCard?: boolean;
  actionsInBody?: boolean;
  label?: string;
  disabled?: boolean;
  hasPower?: boolean;
}

export function flat(state: CardState | null): FlatCard {
  if (state === null) return {};
  const { power, ...rest } = state;
  return { ...rest, label: power?.label, disabled: power?.disabled, hasPower: power !== null };
}

/** The filesystem surface {@link seedSitePowerProfile} uses — `node:fs` at the composition edge. */
interface SeedFs {
  existsSync(target: string): boolean;
  readFileSync(target: string, encoding: "utf8"): string;
  mkdirSync(target: string, options: { recursive: true }): unknown;
  writeFileSync(target: string, data: string): void;
}

/** Validates `SITE_POWER_SITE_DIR` and seeds the isolated profile with it. Returns the site's
 *  display name, or `null` (after printing the FAIL line) when the directory is not a real site.
 *
 * @param input.siteDir the scratch site (`SITE_POWER_SITE_DIR`), possibly unset.
 * @param input.shotDir where the run's screenshots land; created here.
 * @param input.userDataDir the isolated `TOVU_DESKTOP_USER_DATA_DIR`; created and seeded here.
 * @param ports.now the clock stamped into the seeded project's `createdAt`. */
export function seedSitePowerProfile(
  { siteDir, shotDir, userDataDir }: { siteDir: string | undefined; shotDir: string; userDataDir: string },
  { fs, log, now }: { fs: SeedFs; log: (line: string) => void; now: () => Date },
): string | null {
  if (!siteDir || !fs.existsSync(path.join(siteDir, "config.json"))) {
    log("FAIL:: SITE_POWER_SITE_DIR must name a real Tovu site directory (one with config.json)");
    return null;
  }
  // The display name the seeded card must carry, read from the site's own config.json rather than
  // passed in a second env var that could disagree with it. `CARD_IS_SEEDED_SITE` in the script is
  // the reason this exists.
  const expectedSiteName = (JSON.parse(fs.readFileSync(path.join(siteDir, "config.json"), "utf8")) as { name: string }).name;
  fs.mkdirSync(shotDir, { recursive: true });
  fs.mkdirSync(userDataDir, { recursive: true });
  // The seed a fresh profile cannot produce for itself: `handleList` renders this file and there is
  // no scan that would reach a site outside the scan roots.
  fs.writeFileSync(
    path.join(userDataDir, "desktop-projects.json"),
    JSON.stringify(
      { projects: [{ siteDir, createdAt: now().toISOString(), origin: "adopted" }], dismissed: [] },
      null,
      2,
    ),
  );
  return expectedSiteName;
}

export type { Box, CardState, Claim, FlatCard, LayoutClaims, SeedFs };

/**
 * @file Persisted record of which sites THIS app has spawned a `tovu serve` child for, and the
 * boot-time reconciliation that uses it.
 *
 * Multi-site sharpens a risk `main.js`'s own prior comment already named for the single-site case:
 * "A hard kill of Electron itself (SIGKILL, a crash, a logout) still bypasses [graceful shutdown] and
 * can strand the child. Tovu-Runner answers that with a pid registry and boot-time orphan
 * reconciliation; that machinery belongs with the fleet supervisor, not here, and is reported rather
 * than ported." With N sites open at once, the SAME hard kill strands N children instead of one —
 * this file is that machinery, now that the sites home UI gives good reason to build it: Tovu-Runner's own
 * `project-provisioner.ts:617-871` (~255 lines) cluster (`isProcessAlive`, `isProjectSidecar`,
 * `terminateOrphan`, `reconcile`), reproduced at the size this shell actually needs.
 *
 * **Storage shape: one JSON file PER APP INSTANCE, each with exactly one writer (2026-09-20).**
 * `userData/site-processes/<electron pid>-<nonce>.json`. It used to be one shared `open-sites.json`,
 * justified by `site-dir-store.ts`'s "one Electron main process, no concurrent writers" — a premise
 * that was never true here: nothing stops two instances running at once (the owner runs several on
 * purpose, and ruled out a single-instance lock), and every write was an unlocked read-modify-write
 * of the whole file. Two instances therefore lost each other's rows, and boot-time reconciliation —
 * whose read-to-write gap spans every orphan's SIGTERM grace window — wiped any row a sibling recorded
 * in the meantime. Splitting the file removes that race by construction instead of guarding it: an
 * instance only ever rewrites its OWN file, and another instance's file is only ever deleted once its
 * owner pid is gone (the nonce means a recycled pid can never name a dead instance's file as its own).
 * Every write is temp-file + `fsync` + `rename`, so a reader sees the old file or the new one, never
 * half of one — and an unreadable file is reported as unreadable, never read as an empty list (see
 * {@link readRegistryFile}). Those two mechanisms, and moving an unreadable file aside rather than
 * writing over it, now live in `durable-json-file.ts`: the same bug was found in `tracked-sites.ts`
 * and `site-dir-store.ts` the same day, and a second and third copy of this code here is how the
 * three would drift. Still flat JSON rather than `better-sqlite3`: a handful of rows, no query
 * beyond "read them all". Each row carries exactly what reconciliation needs to prove identity before
 * killing anything — `{siteDir, port, workspaceId, pid, updatedAt}`, the same fields Tovu-Runner's own
 * `RunnerProjectRow` carries (`last_pid`, `installDir`, `port`). A bare path could never support the
 * identity check below; a row can.
 *
 * **Identity proof before killing**, ported as a SHAPE, not literal code: Tovu-Runner's
 * `isProjectSidecar` (`project-provisioner.ts:701-716`) proves a recovered pid is still the row's own
 * `tovu serve` — never trusted just because a number in a file happens to still name a running
 * process, since the OS could have recycled that pid to something unrelated since the row was
 * written — by checking the live process's argv contains BOTH its install dir and its `--port <n>`
 * flag. That proof is free here with NO new argv marker needed: `tovu-server.ts` already spawns
 * `tovu serve <siteDir> --port <port>` (via `--import tsx` or the compiled CLI — either way the same
 * two tokens land in argv), unlike the agent-daemon child one level down inside each `tovu serve`,
 * which had no site-specific argv at all until `daemon-supervisor.ts`'s own `--workspace` fix.
 *
 * **What this deliberately does NOT do**: reopen or reattach a reconciled site. This app holds no
 * live `ChildProcess` reference for a process it did not spawn this boot — no stdout/stderr pipe, no
 * handle {@link import("./tovu-server.ts").startTovuServer}'s `stop()` could ever use — so
 * "reclaiming" it would mean fabricating a fake handle around a process the shell cannot actually
 * supervise. Terminating it and leaving the site closed (findable again through "Open Recent",
 * `site-dir-store.ts`'s existing MRU) is the smaller, honest surface this pass actually verified;
 * auto-restoring a full session is a follow-up, not this fix.
 */
import fs from "node:fs";
import path from "node:path";
import { randomBytes } from "node:crypto";
import { execFileSync } from "node:child_process";

import { readJsonFile, writeJsonFileAtomic, tempPathFor, quarantineUnreadableFile } from "./durable-json-file.ts";
import type { QuarantineNotice } from "./durable-json-file.ts";

/** The directory inside `userData` holding one registry file per running app instance. */
const REGISTRY_DIR_NAME = "site-processes";

/** The single shared file every build before 2026-09-20 wrote, next to {@link REGISTRY_DIR_NAME}.
 *  Still READ — reconciliation must reap a crashed older build's orphans, and the delete guard must
 *  see a still-running older build's sites — but never rewritten: older builds are its writers, and
 *  writing a file this build does not own is the race this layout removes. The one exception is an
 *  unreadable copy, moved aside at boot (see {@link reconcileLegacyFile}). */
const LEGACY_REGISTRY_FILE_NAME = "open-sites.json";

/** `<owner pid>-<nonce>.json`. Temp (`.<pid>.tmp`) and quarantined (`.corrupt-<ms>`) files never match. */
const INSTANCE_FILE_PATTERN = /^(\d+)-[0-9a-f]+\.json$/;

/** This process's own file stem. The nonce keeps a pid the OS recycled from a crashed instance from
 *  ever adopting that instance's file as its own. */
const OWN_INSTANCE_ID = `${process.pid}-${randomBytes(4).toString("hex")}`;

/** SIGTERM-to-SIGKILL window for a reconciled orphan — matches `tovu-server.ts`'s own
 *  `DEFAULT_STOP_GRACE_MS`, the same grace `serve.ts`'s BR-07 drain gets when this app spawned the
 *  child itself this boot. */
const DEFAULT_TERMINATE_GRACE_MS = 5_000;
const TERMINATE_POLL_MS = 200;

/** One persisted row: everything reconciliation needs to prove identity before killing anything. */
interface SiteProcessRow {
  siteDir: string;
  port: number;
  workspaceId: string;
  pid: number;
  updatedAt: number;
}

/**
 * What {@link readRegistryFile} found in one file. `unreadable` is deliberately its own state and
 * never folded into an empty list: an empty list is a valid registry, while an unreadable file (torn,
 * not JSON, not our shape, or an I/O error) holds rows nobody can know. Folding the two together is
 * how a torn file used to be read as `[]` and the next write persisted that, dropping every row.
 */
type RegistryFileRead = { state: "ok"; sites: SiteProcessRow[] } | { state: "missing" } | { state: "unreadable" };

/** {@link readRegistry}'s answer across every instance's file plus the legacy one. */
interface RegistrySnapshot {
  sites: SiteProcessRow[];
  /** Paths that exist but could not be read — their rows are UNKNOWN, not absent. */
  unreadable: string[];
}

/** One instance's file, as {@link listInstanceFiles} found it. */
interface InstanceFile {
  filePath: string;
  instanceId: string;
  ownerPid: number;
}

/** A raw parsed row, before {@link readRegistryFile} checks which fields are actually usable. */
interface RawSiteProcessRow {
  siteDir?: unknown;
  pid?: unknown;
  [key: string]: unknown;
}

/**
 * The fields {@link isServeProcessForSite}, {@link isLiveServeRow} and {@link terminateOrphan} need
 * to prove a pid is still its row's own `tovu serve` — a subset of {@link SiteProcessRow}, since
 * none of them touch `workspaceId` or `updatedAt`.
 */
interface ServeIdentityRow {
  siteDir: string;
  port: number;
  pid: number;
}

/** @returns the registry DIRECTORY inside Electron's per-user `userData` directory — the value every
 *  `registryDir` parameter below takes. */
function registryDirPath(userDataDir: string): string {
  return path.join(userDataDir, REGISTRY_DIR_NAME);
}

/** @returns where pre-2026-09-20 builds kept their single shared file: beside `registryDir`. */
function legacyRegistryFilePath(registryDir: string): string {
  return path.join(path.dirname(registryDir), LEGACY_REGISTRY_FILE_NAME);
}

/** @returns one instance's own file inside `registryDir` — this process's unless a test names another. */
function instanceFilePath(registryDir: string, instanceId: string = OWN_INSTANCE_ID): string {
  return path.join(registryDir, `${instanceId}.json`);
}

/** Whether a parsed row has the two fields every reader keys on. Other fields are trusted as written.
 *  @complexity O(1). */
function isUsableRow(row: unknown): boolean {
  return typeof row === "object" && row !== null && typeof (row as RawSiteProcessRow).siteDir === "string" && typeof (row as RawSiteProcessRow).pid === "number";
}

/**
 * Read ONE registry file. Malformed ROWS inside a well-formed file are dropped (they cannot be
 * reconciled or matched anyway); a malformed FILE is `unreadable`, never an empty list — see
 * {@link RegistryFileRead}. Launch is still never blocked: callers decide what unreadable means.
 * @complexity O(n) in file size.
 */
function readRegistryFile(filePath: string): RegistryFileRead {
  const read = readJsonFile(filePath);
  if (read.state !== "ok") return read.state === "missing" ? { state: "missing" } : { state: "unreadable" };
  const sites = (read.value as { sites?: unknown } | null)?.sites;
  if (!Array.isArray(sites)) return { state: "unreadable" };
  return { state: "ok", sites: sites.filter(isUsableRow) as SiteProcessRow[] };
}

/**
 * Every instance file in `registryDir`. A missing directory is simply "no instance has written yet".
 * @returns the files, or `null` when the directory exists but cannot be listed — its rows are
 *   unknown, which each caller must treat as such rather than as "none".
 * @complexity O(n) in directory entries.
 */
function listInstanceFiles(registryDir: string): InstanceFile[] | null {
  let names: string[];
  try {
    names = fs.readdirSync(registryDir);
  } catch (error) {
    return (error as NodeJS.ErrnoException).code === "ENOENT" ? [] : null;
  }
  return names.flatMap((name) => {
    const match = INSTANCE_FILE_PATTERN.exec(name);
    return match ? [{ filePath: path.join(registryDir, name), instanceId: name.slice(0, -".json".length), ownerPid: Number(match[1]) }] : [];
  });
}

/**
 * Every row any instance has recorded — each instance's own file plus the legacy shared file — for
 * readers that must see sibling instances (the delete guard's `liveForeignServers`).
 *
 * A file that vanishes between the listing and the read was deleted by a booting instance because
 * its owner is gone, so it is correctly skipped. An unreadable one is listed in `unreadable` instead.
 * @complexity O(total file size) across every instance file.
 */
function readRegistry(registryDir: string): RegistrySnapshot {
  const files = listInstanceFiles(registryDir);
  const snapshot: RegistrySnapshot = { sites: [], unreadable: files === null ? [registryDir] : [] };
  for (const filePath of [...(files ?? []).map((file) => file.filePath), legacyRegistryFilePath(registryDir)]) {
    const read = readRegistryFile(filePath);
    if (read.state === "ok") snapshot.sites.push(...read.sites);
    else if (read.state === "unreadable") snapshot.unreadable.push(filePath);
  }
  return snapshot;
}

/**
 * A row as {@link writeRegistry} accepts it — every field `unknown`, so a test proving
 * {@link readRegistryFile}'s own filtering can write deliberately malformed rows (a missing `siteDir`, a
 * non-numeric `pid`) straight through this same function rather than reaching for a second, raw
 * `fs.writeFileSync` just for that.
 */
interface WritableSiteProcessRow {
  siteDir?: unknown;
  port?: unknown;
  workspaceId?: unknown;
  pid?: unknown;
  updatedAt?: unknown;
}

/** {@link writeRegistry}'s own parameter shape. */
interface WritableSiteProcessRegistry {
  sites: WritableSiteProcessRow[];
}

/**
 * How a quarantined registry file is announced. The mechanism — and the message's shape — is shared
 * with every other durable store in this app (`durable-json-file.ts`); only these two sentences are
 * the registry's own.
 */
const REGISTRY_QUARANTINE_NOTICE: QuarantineNotice = {
  label: "site-process registry file",
  consequence: "site processes it listed cannot be reconciled automatically.",
};

/**
 * Atomically replace one registry file. The mechanism (temp file, `fsync`, `rename`) is
 * `durable-json-file.ts`'s {@link writeJsonFileAtomic} — this is the registry-typed doorway to it,
 * kept so every caller and test still names the registry rather than a generic writer.
 *
 * A crash can leave a `.tmp` behind; the next write by that pid truncates it, and
 * {@link reconcileInstanceFile} removes a dead owner's.
 * @complexity O(n) in row count.
 */
function writeRegistry(filePath: string, state: WritableSiteProcessRegistry): void {
  writeJsonFileAtomic(filePath, state);
}

/**
 * This instance's own rows, for a read-modify-write of its own file.
 *
 * An unreadable own file is moved aside and the write proceeds from empty, rather than refusing the
 * write: the caller is recording a child it has just spawned or just stopped, and refusing would leave
 * that child with no crash-recovery row (or a stale one) — the very thing the registry exists to
 * prevent — while throwing from `startSiteBackend` would strand a started server with no handle.
 * The unreadable bytes survive aside either way. With atomic writes this takes outside damage.
 *
 * @returns the rows, or `null` when the unreadable file could not be moved aside: do not write.
 * @complexity O(n) in file size.
 */
function readOwnRowsForUpdate(filePath: string, quarantine: typeof quarantineUnreadableFile = quarantineUnreadableFile): SiteProcessRow[] | null {
  const read = readRegistryFile(filePath);
  if (read.state === "ok") return read.sites;
  if (read.state === "missing") return [];
  return quarantine(filePath, REGISTRY_QUARANTINE_NOTICE) ? [] : null;
}

/** {@link recordSiteOpened}'s own options. */
interface RecordSiteOpenedOptions {
  isLiveRow?: (row: SiteProcessRow) => boolean;
  /** Test seam: whose file to update. Defaults to this process's own. */
  instanceId?: string;
}

/**
 * Record one open site's row in THIS instance's own file — called once `startTovuServer` has actually
 * resolved, so a row is never written for a spawn attempt that failed.
 *
 * **Refuse-not-replace (D-07).** This used to drop every existing row with the same `siteDir`
 * unconditionally, which — back when every instance shared one file — let instance B opening a site
 * instance A had open erase A's row. Since 2026-09-20 a sibling's rows live in the sibling's own
 * file, so this can no longer touch them at all. The rule still matters inside one instance: a
 * window's `closed` handler drops its `openSites` entry before that child's `stop()` has finished
 * draining, so the same site can be reopened while its previous child is still alive, and that
 * child's row must survive until its own `recordSiteClosed`, or a hard kill mid-drain strands it.
 *
 * A row is only displaced once it is PROVEN dead — the same identity proof
 * ({@link isServeProcessForSite}) reconciliation makes before it kills anything, so a pid the OS
 * recycled to something unrelated never counts as "still live" and rows cannot accumulate. Two rows
 * for one `siteDir` in this file therefore mean exactly what they say: this instance really has two
 * `tovu serve` children over that site, the old one still stopping.
 *
 * @param options.isLiveRow test seam — the "is this row's process still its own live `tovu serve`"
 *   predicate. Defaults to {@link isLiveServeRow}, which really asks the OS.
 * @complexity O(n) in row count, times one `ps` call per same-`siteDir` row (in practice zero or one).
 */
function recordSiteOpened(registryDir: string, row: SiteProcessRow, options: RecordSiteOpenedOptions = {}): void {
  const isLiveRow = options.isLiveRow ?? isLiveServeRow;
  const filePath = instanceFilePath(registryDir, options.instanceId);
  const sites = readOwnRowsForUpdate(filePath);
  if (sites === null) return;
  const retained = sites.filter((existing) => existing.siteDir !== row.siteDir || isLiveRow(existing));
  writeRegistry(filePath, { sites: [row, ...retained] });
}

/**
 * Whether `row`'s pid is still alive AND still that row's own `tovu serve` — alive alone is not
 * enough, since the OS is free to have reassigned that number to something unrelated.
 * @complexity O(1) beyond one `ps` call.
 */
function isLiveServeRow(row: ServeIdentityRow): boolean {
  if (!isProcessAlive(row.pid)) return false;
  return isServeProcessForSite(readProcessCommand(row.pid) ?? "", row);
}

/** {@link recordSiteClosed}'s own options. */
interface RecordSiteClosedOptions {
  pid?: number;
  /** Test seam: whose file to update. Defaults to this process's own. */
  instanceId?: string;
  /** Test seam: moves an unreadable file aside, `false` when it could not. Defaults to `quarantineUnreadableFile`. */
  quarantine?: typeof quarantineUnreadableFile;
}

/**
 * Drop a site's row from THIS instance's own file — called once its `tovu serve` child has been asked
 * to stop deliberately (a window closed, or the whole app quit cleanly), so an ordinary shutdown is
 * never mistaken for a crash and reconciled against on the next launch.
 *
 * @param options.pid drop only the row carrying this pid. Every caller that HAS a pid passes it,
 *   and they all do — this is only ever called about a child the caller is holding a handle to.
 *   It matters because {@link recordSiteOpened} can legitimately leave two rows for one `siteDir` in
 *   this file (a still-stopping child plus its replacement): closing by `siteDir` alone would wipe the
 *   other one too. Omitting it keeps the original drop-every-row-for-this-site behaviour, so a future
 *   caller that genuinely means "forget this site entirely" still has that, and no existing call site
 *   changed meaning silently.
 * @complexity O(n) in row count.
 */
function recordSiteClosed(registryDir: string, siteDir: string, options: RecordSiteClosedOptions = {}): void {
  const filePath = instanceFilePath(registryDir, options.instanceId);
  const sites = readOwnRowsForUpdate(filePath, options.quarantine);
  if (sites === null) return;
  const isDoomed = (existing: SiteProcessRow) => existing.siteDir === siteDir && (options.pid === undefined || existing.pid === options.pid);
  writeRegistry(filePath, { sites: sites.filter((existing) => !isDoomed(existing)) });
}

/**
 * Whether a pid still names a live process. Signal `0` sends nothing and reads nothing — it only
 * asks the kernel "does this pid exist and can I signal it" — the same check Tovu-Runner's own
 * `isProcessAlive` makes.
 * @complexity O(1).
 */
function isProcessAlive(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

/** Options for the two `ps` readers; `runPs` runs `ps` with the given argv-only column args (test seam). */
interface PsOptions {
  runPs?: (args: string[]) => string;
}

/** The real `ps`, stdout as text; throws when `ps` exits non-zero (a gone pid). @complexity O(1). */
function runPsArgvOnly(args: string[]): string {
  return execFileSync("ps", args, { encoding: "utf8" });
}

/**
 * Read a live process's own argv — `ps -o command=`, deliberately NEVER `ps eww`/`pgrep -fl`. Both
 * of those dump a process's ENVIRONMENT, which can hold live secrets, and are banned in this
 * codebase for exactly that reason. `ps`'s plain `command=` column is argv only, never env, so
 * nothing sensitive can leak through this call.
 *
 * **win32 has no `ps`**, so this returns `null` immediately without spawning anything (plan item
 * W9). Every caller already treats `null` as "cannot confirm identity" and skips reaping rather
 * than erroring — the same fallback a genuinely-gone pid takes — so orphan reaping is a documented
 * no-op on Windows v1: a leak (an orphan is left running), never a crash or a wrongful kill.
 *
 * @param platform test seam; defaults to the real `process.platform`. Production never passes this.
 * @param options.runPs test seam for the `ps` call itself; defaults to the real `ps`.
 * @returns the command line, or `null` once the pid is gone (a race between {@link isProcessAlive}
 *   and this call, or the row's pid was never real) — or unconditionally on win32.
 * @complexity O(1); one subprocess call, skipped entirely on win32.
 */
function readProcessCommand(pid: number, platform: NodeJS.Platform = process.platform, { runPs = runPsArgvOnly }: PsOptions = {}): string | null {
  if (platform === "win32") return null;
  try {
    const output = runPs(["-o", "command=", "-p", String(pid)]);
    return output.trim() || null;
  } catch {
    return null;
  }
}

/**
 * A live process's parent pid, read the same argv-only way as {@link readProcessCommand} (`ps`'s
 * plain `ppid=` column is a number, never environment, so nothing sensitive can leak through it).
 *
 * **win32 has no `ps`** either — same no-op documented on {@link readProcessCommand}, and for the
 * same reason (plan item W9): every caller of this function already treats `null` as "cannot tell,"
 * which is the correct answer on a platform this cannot check.
 *
 * @param platform test seam; defaults to the real `process.platform`. Production never passes this.
 * @param options.runPs test seam for the `ps` call itself; defaults to the real `ps`.
 * @returns the parent pid, or `null` once the pid is gone or `ps` prints something unparseable — or
 *   unconditionally on win32.
 * @complexity O(1); one subprocess call, skipped entirely on win32.
 */
function readProcessParentPid(pid: number, platform: NodeJS.Platform = process.platform, { runPs = runPsArgvOnly }: PsOptions = {}): number | null {
  if (platform === "win32") return null;
  try {
    const parsed = Number.parseInt(runPs(["-o", "ppid=", "-p", String(pid)]).trim(), 10);
    return Number.isNaN(parsed) ? null : parsed;
  } catch {
    return null;
  }
}

/**
 * Whether `pid`'s own parent is gone — the property that separates a real ORPHAN from a live
 * sibling instance's perfectly healthy child.
 *
 * This distinction became load-bearing when {@link reconcileOrphans} moved above `main.ts`'s
 * boot-mode split so the sites home UI reaps orphans too. Nothing prevents two Electron instances running
 * at once (there is no `requestSingleInstanceLock`), and the identity proof above cannot help: a
 * live sibling's child matches its own row's argv EXACTLY, by construction. Without this check the
 * second instance's boot would SIGTERM every site the first instance has open.
 *
 * Parentage rather than a persisted owner-pid field on purpose. A field only protects rows written
 * by a build that has the field, so the very first launch after shipping it would still reap the
 * children of an instance already running from the previous build — the one case that matters most.
 * Parentage is a property of the running process, so it protects rows of every vintage immediately.
 *
 * Measured on macOS 2026-09-06 against `tovu-server.ts`'s exact `detached: true` spawn shape:
 * `detached` makes the child a process-GROUP leader and leaves its parent unchanged, so its ppid is
 * the Electron main pid while that process lives and becomes `1` (launchd) the moment it dies.
 *
 * Fails CLOSED in the only direction that matters: anything other than a confirmed reparent-to-
 * launchd reads as "not an orphan" and is left running. Leaking a stray process costs a port and
 * some memory; killing a live sibling's server costs whatever that site was doing.
 *
 * @complexity O(1) beyond {@link readProcessParentPid}'s own subprocess call.
 */
function isOrphanedProcess(pid: number): boolean {
  return readProcessParentPid(pid) === 1;
}

/**
 * Runner's `isProjectSidecar` technique: a pid is only trusted to BE this row's `tovu serve` once
 * its live argv contains the complete site dir and its `--port <n>` flag — never taken on faith just
 * because a number in a persisted row happens to still name a running process.
 * @complexity O(n) in command-line length.
 */
function isServeProcessForSite(commandLine: string, row: Pick<ServeIdentityRow, "siteDir" | "port">): boolean {
  const siteDir = row.siteDir.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp(`(?:^|\\s)${siteDir}(?=\\s|$)`).test(commandLine)
    && new RegExp(`(?:^|\\s)--port\\s+${row.port}(?=\\s|$)`).test(commandLine);
}

/** @complexity O(1); the caller bounds how many times this is awaited. */
function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Terminate one confirmed orphan: SIGTERM, poll for real exit, then — only if it is STILL alive AND
 * STILL identifiable as this row's own process — escalate to SIGKILL. Re-identifying before
 * escalating (not just before the FIRST signal) is the same discipline as Runner's own
 * `terminateOrphan` (`project-provisioner.ts:724-747`): a pid the OS reassigned to something
 * unrelated during the poll window must never be killed on this row's authority.
 * A successful SIGKILL request is not observed exit; allow a bounded final poll before the
 * caller clears the crash-recovery row. This also lets Node collect a child's exit status.
 *
 * @complexity O((graceMs + DEFAULT_TERMINATE_GRACE_MS) / TERMINATE_POLL_MS) — bounded polls.
 */
async function terminateOrphan(row: ServeIdentityRow, graceMs: number = DEFAULT_TERMINATE_GRACE_MS): Promise<void> {
  try {
    process.kill(row.pid, "SIGTERM");
  } catch {
    return; // already gone
  }

  const deadline = Date.now() + graceMs;
  while (Date.now() < deadline) {
    if (!isProcessAlive(row.pid)) return;
    await sleep(TERMINATE_POLL_MS);
  }

  await finishOrphanTermination({ row });
}

/** Reconfirm the orphan's identity before escalating, then observe exit before its row is cleared.
 * @complexity O(DEFAULT_TERMINATE_GRACE_MS / TERMINATE_POLL_MS) — bounded final poll. */
async function finishOrphanTermination(
  { row }: { row: ServeIdentityRow },
  _optional: Record<string, never> = {},
): Promise<void> {
  if (isProcessAlive(row.pid) && isServeProcessForSite(readProcessCommand(row.pid) ?? "", row)) {
    try {
      process.kill(row.pid, "SIGKILL");
    } catch {
      return; // already gone
    }
    const killDeadline = Date.now() + DEFAULT_TERMINATE_GRACE_MS;
    while (isProcessAlive(row.pid) && Date.now() < killDeadline) {
      await sleep(TERMINATE_POLL_MS);
    }
  }
}

/**
 * Boot-time orphan reconciliation — the piece `main.js`'s own prior comment named as deliberately
 * deferred. Call once, before any window is created: for every row this app persisted before its
 * last exit, prove whether the pid is STILL that row's own `tovu serve` (identity-before-kill, see
 * {@link isServeProcessForSite}), and if so terminate it — a prior run's window is gone, so nothing
 * will ever call that child's own `stop()` again, and a plain SIGTERM here still gives it the same
 * BR-07 graceful drain `serve.ts` runs for any other shutdown signal.
 *
 * Reads every OTHER instance's file (this process has written none yet at boot) plus the legacy
 * shared file, and REWRITES NONE of them. That is the 2026-09-20 fix: this used to rewrite the one
 * shared file with only the rows it kept, AFTER awaiting every orphan's SIGTERM grace window, so any
 * row a live sibling recorded during those seconds was silently dropped. Now:
 * - every row gets the same per-row proof as before, so a live sibling's child ({@link isOrphanedProcess})
 *   is never killed, whichever file names it;
 * - a file is deleted only once its OWNER pid is gone, since nothing will ever write it again —
 *   which also stops a later boot re-processing its rows. A live owner's file is left byte-for-byte
 *   as its owner wrote it; that owner drops its own rows as it closes sites;
 * - a pid the OS recycled keeps a dead owner's file around (fails toward keeping it), but its
 *   orphans are still reaped, because the parentage proof is per row, not per file.
 *
 * @param options.instanceId test seam: whose file counts as this process's own and is skipped.
 * @returns the rows that were found to be live orphans and terminated — for logging/reporting only.
 * @complexity O(n) in persisted row count across all files; each row's own cost is
 *   `terminateOrphan`'s bounded poll.
 */
async function reconcileOrphans(registryDir: string, options: { instanceId?: string } = {}): Promise<SiteProcessRow[]> {
  const ownInstanceId = options.instanceId ?? OWN_INSTANCE_ID;
  const files = listInstanceFiles(registryDir);
  if (files === null) console.error(`tovu desktop: could not list ${registryDir}; orphans recorded there are not reconciled this boot.`);

  const reconciled: SiteProcessRow[] = [];
  for (const file of files ?? []) {
    if (file.instanceId === ownInstanceId) continue;
    reconciled.push(...(await reconcileInstanceFile(file)));
  }
  reconciled.push(...(await reconcileLegacyFile(legacyRegistryFilePath(registryDir))));
  return reconciled;
}

/**
 * Terminate every row in `sites` that is still its own `tovu serve` AND a proven orphan. Rows whose
 * process is gone, recycled, or still parented by a live sibling instance are left alone.
 * @returns the rows terminated.
 * @complexity O(n) in `sites`; each orphan's cost is `terminateOrphan`'s bounded poll.
 */
async function reconcileRows(sites: SiteProcessRow[]): Promise<SiteProcessRow[]> {
  const reconciled: SiteProcessRow[] = [];
  for (const row of sites) {
    if (!isProcessAlive(row.pid)) continue;
    if (!isServeProcessForSite(readProcessCommand(row.pid) ?? "", row)) continue;
    if (!isOrphanedProcess(row.pid)) continue;
    reconciled.push(row);
    await terminateOrphan(row);
  }
  return reconciled;
}

/**
 * {@link reconcileOrphans} for one other instance's file. Deleted (with any temp file a crash left) only
 * when its owner pid is gone; an unreadable one is moved aside under the same condition, and
 * otherwise left for its live owner, whose next write moves it aside itself.
 * @complexity see {@link reconcileRows}.
 */
async function reconcileInstanceFile(file: InstanceFile): Promise<SiteProcessRow[]> {
  const ownerGone = !isProcessAlive(file.ownerPid);
  const read = readRegistryFile(file.filePath);
  if (read.state === "unreadable") {
    if (ownerGone) quarantineUnreadableFile(file.filePath, REGISTRY_QUARANTINE_NOTICE);
    else console.error(`tovu desktop: site-process registry file ${file.filePath} is unreadable; its owner (pid ${file.ownerPid}) is still running, so it is left untouched.`);
    return [];
  }
  const reconciled = read.state === "ok" ? await reconcileRows(read.sites) : [];
  if (ownerGone) {
    fs.rmSync(file.filePath, { force: true });
    fs.rmSync(tempPathFor(file.filePath, file.ownerPid), { force: true });
  }
  return reconciled;
}

/**
 * {@link reconcileOrphans} for the pre-2026-09-20 shared file: its orphans are reaped, the file itself
 * is never rewritten (see {@link LEGACY_REGISTRY_FILE_NAME}). An unreadable one — a torn write by an
 * older build — is moved aside so its bytes survive and it stops tripping readers.
 * @complexity see {@link reconcileRows}.
 */
async function reconcileLegacyFile(legacyPath: string): Promise<SiteProcessRow[]> {
  const read = readRegistryFile(legacyPath);
  if (read.state === "unreadable") {
    quarantineUnreadableFile(legacyPath, REGISTRY_QUARANTINE_NOTICE);
    return [];
  }
  return read.state === "ok" ? reconcileRows(read.sites) : [];
}

export {
  REGISTRY_DIR_NAME,
  LEGACY_REGISTRY_FILE_NAME,
  registryDirPath,
  legacyRegistryFilePath,
  instanceFilePath,
  readRegistryFile,
  readRegistry,
  writeRegistry,
  recordSiteOpened,
  recordSiteClosed,
  isLiveServeRow,
  isProcessAlive,
  readProcessCommand,
  readProcessParentPid,
  isOrphanedProcess,
  isServeProcessForSite,
  terminateOrphan,
  reconcileOrphans,
};

/** Tovu discovery is for folders of websites, never a whole user account or volume. */
import os from 'node:os';
import path from 'node:path';

/** Refuse obvious broad roots before filesystem access (including Windows/UNC spellings).
 * @returns Nothing for a specific folder.
 * @throws Error with the folder-picker remedy when the root is broad.
 * @complexity O(n) in the path length, with no filesystem probes.
 */
export function assertSpecificSiteRoot({ root }: { root: string }, { homeDir = os.homedir(), sitesHome }: { homeDir?: string; sitesHome?: string } = {}): void {
  const normalized = normalizeRoot(root);
  const home = trimSlashes(homeDir);
  // The selected local fallback has one known Tovu parent at the former level. This narrow
  // application folder can be scanned without admitting unrelated direct home children.
  if (normalized === `${home}/Tovu` && sitesHome !== undefined && trimSlashes(sitesHome) === `${normalized}/sites`) return;
  if (isBroadRoot(normalized, home)) throw new Error(`Sites folder is too broad: ${root}. Choose a specific folder containing your Tovu websites.`);
}

const trimSlashes = (value: string) => value.replaceAll('\\', '/').replace(/\/+$/, '');

/** Forward slashes, no trailing slash; a UNC `//host/share` is kept as written. */
function normalizeRoot(root: string): string {
  const spelling = root.replaceAll('\\', '/');
  return spelling.startsWith('//') ? spelling.replace(/\/+$/, '') : path.posix.normalize(spelling).replace(/\/+$/, '') || '/';
}

/** Whole accounts, volumes, drives, shares and direct home children. */
const BROAD_ROOT_PATTERNS = [
  /^~\/[^/]+$/, /^\/(?:Users|home)(?:\/[^/]+)?$/, /^[a-z]:$/i, /^\/\/[^/]+(?:\/[^/]+)?$/, /^\/(?:Volumes|mnt|media)(?:\/[^/]+)?$/,
];

function isBroadRoot(normalized: string, home: string): boolean {
  if (['/', '~', home].includes(normalized) || path.posix.dirname(normalized) === home) return true;
  return BROAD_ROOT_PATTERNS.some((pattern) => pattern.test(normalized));
}

/** One sender owns its own claims. Closing a tab or destroying its window releases the stream. */
import { SITE_THEME_PREVIEW_CHANNELS as channels, type SiteThemePreviewRefresh } from './contracts/project.ts';
import type { createSiteThemePreviewSubscriptions } from './site-theme-preview.ts';
interface PreviewSender {
  id: number;
  once: (name: 'destroyed', listener: () => void) => unknown;
  removeListener: (name: 'destroyed', listener: () => void) => unknown;
  isDestroyed: () => boolean;
  send: (channel: string, frame: SiteThemePreviewRefresh) => void;
}

export function registerSiteThemePreviewIpc(
  { ipcMain, subscriptions, allowed }: {
    ipcMain: {
      handle: (channel: string, listener: (event: { sender: PreviewSender }, input: unknown) => void) => void;
      removeHandler: (channel: string) => void;
    };
    subscriptions: Pick<ReturnType<typeof createSiteThemePreviewSubscriptions>, 'watch'>;
    allowed: (sender: PreviewSender) => boolean;
  }, _optional = {},
): () => void {
  type Owner = { claims: Map<string, () => void>; destroy: () => void };
  const owners = new Map<PreviewSender, Owner>();
  // Every caller already holds the sender's live owner, and each path removes it (and its destroy
  // hook) before anything else, so an owner is released at most once.
  const release = (sender: PreviewSender, owner: Owner) => {
    owners.delete(sender);
    sender.removeListener('destroyed', owner.destroy);
    for (const off of owner.claims.values()) off();
  };
  const inputId = (input: unknown) => input && typeof input === 'object' && 'subscriptionId' in input && typeof input.subscriptionId === 'string' && /^[\w-]{1,100}$/.test(input.subscriptionId) ? input.subscriptionId : undefined;
  ipcMain.handle(channels.watch, ({ sender }, input) => {
    const id = inputId(input);
    if (!allowed(sender) || sender.isDestroyed() || !id) return;
    const siteDir = watchSiteDirectory({ input });
    if (siteDir === undefined) return;
    let owner = owners.get(sender);
    if (!owner) {
      const created: Owner = { claims: new Map(), destroy: () => release(sender, created) };
      owner = created;
      owners.set(sender, owner); sender.once('destroyed', owner.destroy);
    }
    if (owner.claims.has(id)) return;
    owner.claims.set(id, subscriptions.watch({ siteDir, listener: (frame) => {
      if (!sender.isDestroyed()) sender.send(channels.event, frame);
    } }));
  });
  ipcMain.handle(channels.unwatch, ({ sender }, input) => {
    const id = inputId(input);
    if (!id) return;
    const owner = owners.get(sender);
    owner?.claims.get(id)?.(); owner?.claims.delete(id);
    if (owner?.claims.size === 0) release(sender, owner);
  });
  return () => {
    for (const [sender, owner] of owners) release(sender, owner);
    ipcMain.removeHandler(channels.watch); ipcMain.removeHandler(channels.unwatch);
  };
}

/** Read only a string directory from a watch claim; leave sender trust checks at the boundary.
 * @complexity O(1) time and space.
 */
function watchSiteDirectory({ input }: { input: unknown }, _options = {}): string | undefined {
  if (!input || typeof input !== 'object' || !('siteDir' in input) || typeof input.siteDir !== 'string') return undefined;
  return input.siteDir;
}

/** Tovu theme feed adapter. Transport and lifecycle ports keep the desktop shell replaceable.
 * NEEDS-JINI: reusable watched-stream ownership belongs in @jini-ai/desktop-host (read-only dispatch). */
import { EventSource } from 'eventsource';
import type { SiteThemePreviewRefresh } from './contracts/project.ts';

export interface ThemePreviewFrame { revision: string; path?: string }
export interface SiteThemePreviewTarget {
  port: number;
  workspaceId: string;
  partition: string;
  /** The actual supervised server handle, so even a restart reusing a port is a new lifecycle. */
  lifecycle: object;
}
interface StreamSource {
  addEventListener: (name: string, listener: (event: { data: string }) => void) => void;
  close: () => void;
}
type StreamFetch = NonNullable<ConstructorParameters<typeof EventSource>[1]>['fetch'];

export function openSiteThemePreviewStream(
  { target, getRevision, onFrame, fetch }: {
    target: SiteThemePreviewTarget;
    getRevision: () => string | undefined;
    onFrame: (frame: ThemePreviewFrame) => void;
    fetch: NonNullable<StreamFetch>;
  },
  { open = (url, options) => new EventSource(url, options) }: {
    open?: (url: string, options: { fetch: NonNullable<StreamFetch> }) => StreamSource;
  } = {},
): () => void {
  const url = `http://127.0.0.1:${target.port}/api/admin/v1/workspaces/${encodeURIComponent(target.workspaceId)}/settings/events?themePreview=1`;
  let closed = false;
  const source = open(url, { fetch: (_url, init) => {
    // Every retry uses the same site's cookie jar and the last revision it actually delivered.
    const next = new URL(url);
    const revision = getRevision();
    if (revision) next.searchParams.set('themeRevision', revision);
    return fetch(next.href, init);
  } });
  source.addEventListener('theme-preview-refresh', (event) => {
    if (closed) return;
    try {
      const frame: unknown = JSON.parse(event.data);
      const refresh = themePreviewFrame({ frame });
      if (refresh) onFrame(refresh);
    } catch { /* A bad frame must never break independent settings notifications or the host window. */ }
  });
  return () => { closed = true; source.close(); };
}

/** Validate the Tovu feed's refresh frame; unsupported frames are ignored.
 * @complexity O(n) in revision length.
 */
function themePreviewFrame({ frame }: { frame: unknown }, _options = {}): ThemePreviewFrame | undefined {
  const input = { frame };
  if (!hasPreviewRevision(input)) return undefined;
  const valid = input.frame;
  if ('path' in valid && typeof valid.path !== 'string') return undefined;
  return { revision: valid.revision, ...('path' in valid ? { path: valid.path as string } : {}) };
}

/** Narrow a raw feed frame to the revision contract before reading optional fields.
 * @complexity O(n) in revision length.
 */
function hasPreviewRevision(input: { frame: unknown }, _options = {}): input is { frame: { revision: string } } {
  const { frame } = input;
  return !!frame && typeof frame === 'object' && 'revision' in frame && typeof frame.revision === 'string' && /^[\w-]{1,100}$/.test(frame.revision);
}

export interface SiteThemePreviewPorts {
  current: (required: { siteDir: string }, optional: {}) => SiteThemePreviewTarget | undefined;
  open: (required: { siteDir: string; target: SiteThemePreviewTarget; getRevision: () => string | undefined; onFrame: (frame: ThemePreviewFrame) => void }, optional: {}) => () => void;
}

export function createSiteThemePreviewSubscriptions(
  { ports }: { ports: SiteThemePreviewPorts }, _optional = {},
) {
  const watchers = new Map<string, Set<(frame: SiteThemePreviewRefresh) => void>>();
  const streams = new Map<string, { target: SiteThemePreviewTarget; close?: () => void; revision?: string }>();
  const stop = ({ siteDir }: { siteDir: string }, _optional = {}) => {
    const stream = streams.get(siteDir);
    // Remove ownership before closing: late callbacks cannot affect the replacement lifecycle.
    streams.delete(siteDir);
    try { stream?.close?.(); } catch { /* Best-effort teardown cannot block stopping a site. */ }
  };
  const sync = ({ siteDir }: { siteDir: string }, _optional = {}) => {
    const target = ports.current({ siteDir }, {});
    if (!target || !watchers.get(siteDir)?.size) { stop({ siteDir }); return; }
    if (streams.get(siteDir)?.target.lifecycle === target.lifecycle) return;
    stop({ siteDir });
    const stream: { target: SiteThemePreviewTarget; close?: () => void; revision?: string } = { target };
    streams.set(siteDir, stream);
    try {
      stream.close = ports.open({ siteDir, target, getRevision: () => stream.revision, onFrame: (frame) => {
        if (streams.get(siteDir) !== stream || ports.current({ siteDir }, {})?.lifecycle !== target.lifecycle || stream.revision === frame.revision) return;
        stream.revision = frame.revision;
        // A live stream implies watchers for its site: `sync` opens one only for a watched site, and
        // every path that empties a site's watchers (`watch`'s unsubscribe, `dispose`) stops it first.
        for (const listener of watchers.get(siteDir)!) {
          try { listener({ siteDir, ...frame }); } catch { /* A destroyed renderer cannot stop other tabs' notifications. */ }
        }
      } }, {});
    } catch { streams.delete(siteDir); }
  };
  return {
    sync, stop,
    watch({ siteDir, listener }: { siteDir: string; listener: (frame: SiteThemePreviewRefresh) => void }, _optional = {}) {
      const listeners = watchers.get(siteDir) ?? new Set();
      watchers.set(siteDir, listeners); listeners.add(listener); sync({ siteDir });
      return () => {
        listeners.delete(listener);
        if (listeners.size === 0) { watchers.delete(siteDir); stop({ siteDir }); }
      };
    },
    dispose(_required = {}, _optional = {}) {
      for (const siteDir of streams.keys()) stop({ siteDir });
      watchers.clear();
    },
  };
}

/** Packaged MCP release checks. Command construction and reply validation are independently testable. */
import { spawn } from "node:child_process";
import path from "node:path";
import { redactLocalText } from "../../website/src/platform/server-logs/redact-local-text.ts";
import { sanitizeUntrustedText } from "@jini-ai/core/text";
import { buildSitesMcpLauncherScript, buildSitesMcpRegistration } from "./sites-mcp-registration.ts";
import { resolveSmokeTargets } from "./smoke-native.ts";

/** --app copies the exact mounted DMG app; --platform-dir reuses the native smoke layout.
 * Directory reads remain at the script boundary.
 * @param input CLI arguments, desktop root and directory-reading port.
 * @param _options Reserved optional settings.
 * @returns The packaged executable and staged native modules.
 * @throws If arguments or the native layout are missing, or the directory read fails.
 */
export function resolveBridgeSmokeTargets(
  { argv, desktopRoot, readDirectory }: { argv: string[]; desktopRoot: string; readDirectory: (directory: string) => string[] },
  _options: Record<string, never> = {},
): ReturnType<typeof resolveSmokeTargets> {
  const appAt = argv.indexOf("--app");
  const platformAt = argv.indexOf("--platform-dir");
  if (appAt !== -1 && argv[appAt + 1]) {
    const app = path.resolve(desktopRoot, argv[appAt + 1]!);
    return {
      executablePath: path.join(app, "Contents", "MacOS", "Tovu"),
      nodeModulesDir: path.join(app, "Contents", "Resources", "tovu", "node_modules"),
    };
  } else if (platformAt !== -1 && argv[platformAt + 1]) {
    const platformDir = path.resolve(desktopRoot, argv[platformAt + 1]!);
    return resolveSmokeTargets(platformDir, readDirectory(platformDir));
  } else {
    throw new Error("smoke-bridge: --platform-dir <dir> or --app <Tovu.app> is required");
  }
}

export interface BridgeCommand {
  label: string;
  command: string;
  args: string[];
  env: Record<string, string>;
  serverName: string;
  toolName: string;
}

// Match mcp-bridge-launch.smoke.test.ts: no developer credentials or NODE_PATH may reach the child.
const CLI_BASELINE_KEYS = ["PATH", "HOME", "TMPDIR", "SHELL", "LANG", "USER"] as const;

/** Selects only the CLI baseline, then applies the real bridge entry's environment. */
export function buildBridgeEnv(
  { hostEnv, entryEnv = {} }: { hostEnv: NodeJS.ProcessEnv; entryEnv?: Record<string, string> },
): Record<string, string> {
  const baseline: Record<string, string> = {};
  for (const key of CLI_BASELINE_KEYS) {
    if (hostEnv[key] !== undefined) baseline[key] = hostEnv[key];
  }
  return { ...baseline, ...entryEnv };
}

/**
 * Runs INSIDE the shipped binary, whose loader understands app.asar. Import the packaged resolver
 * and entry builder rather than reproducing their environment/credential contract in the smoke.
 */
export function buildJiniEntryScript(
  { resourcesDir, executablePath }: { resourcesDir: string; executablePath: string },
): string {
  return `
(async () => {
  const { createRequire } = require("node:module");
  const { join, dirname } = require("node:path");
  const { pathToFileURL } = require("node:url");
  const resources = ${JSON.stringify(resourcesDir)};
  const tovu = join(resources, "tovu");
  const asar = join(resources, "app.asar");
  const fromTovu = createRequire(join(tovu, "package.json"));
  const { resolveMcpJsonInjection } = await import(pathToFileURL(join(tovu, "dist/src/assistant/mcp-injection.js")).href);
  const { buildMcpJsonServerEntry } = await import(pathToFileURL(fromTovu.resolve("@jini-ai/daemon")).href);
  const injection = resolveMcpJsonInjection("http://127.0.0.1:9", () => "smoke", {
    execPath: ${JSON.stringify(executablePath)}, electronVersion: "smoke", env: {},
  });
  const desktopScript = join(dirname(createRequire(join(asar, "package.json")).resolve("@jini-ai/mcp")), "bin", "serve.js");
  const entries = [injection, { ...injection, args: [desktopScript] }].map(options =>
    buildMcpJsonServerEntry({ runId: "release-smoke", options }, { credential: "smoke" }));
  console.log(JSON.stringify(entries));
})().catch(error => { console.error(error.stack || error.message); process.exitCode = 1; });
`;
}

/** Rejects incomplete resolver output so a failed packaged bootstrap cannot silently skip a bridge. */
export function parseJiniEntries({ stdout }: { stdout: string }, _options = {}): BridgeCommand[] {
  let entries: unknown;
  try { entries = JSON.parse(stdout); }
  catch { throw new Error(`invalid packaged Jini entries: ${sanitizeUntrustedText({ text: redactLocalText({ text: stdout }) })}`); }
  if (!Array.isArray(entries) || entries.length !== 2) throw new Error("expected two packaged Jini entries");
  return entries.map((entry: unknown, index) => {
    if (!isRecord(entry) || typeof entry.command !== "string" || entry.command.length === 0
      || !Array.isArray(entry.args) || !entry.args.every((arg: unknown) => typeof arg === "string")) {
      throw new Error("malformed packaged Jini entry");
    }
    const env = parseJiniEntryEnv({ env: entry.env });
    return {
      label: index === 0 ? "site jini-mcp" : "desktop jini-mcp",
      command: entry.command, args: entry.args as string[], env,
      serverName: "jini-mcp", toolName: "execute_delegated_tool",
    };
  });
}

/** Require the packaged resolver's fixed smoke identity and Electron Node mode.
 * @param input The environment reported by the packaged resolver.
 * @param _options Reserved optional settings.
 * @returns The validated environment, retaining its identity and extra string values.
 * @throws If the environment is malformed or has the wrong smoke identity.
 */
export function parseJiniEntryEnv(
  { env }: { env: unknown },
  _options: Record<string, never> = {},
): Record<string, string> {
  if (!isRecord(env) || !Object.values(env).every(value => typeof value === "string")
    || env.JINI_RUN_ID !== "release-smoke" || env.ELECTRON_RUN_AS_NODE !== "1") {
    throw new Error("malformed packaged Jini entry");
  }
  return env as Record<string, string>;
}

/** Uses the production launcher on POSIX, and production registration argv on Windows. Pure. */
export function buildSitesBridgeCommand(
  { executablePath, resourcesDir, userDataDir, platform }: {
    executablePath: string; resourcesDir: string; userDataDir: string; platform: NodeJS.Platform;
  },
): { entry: BridgeCommand; launcherPath: string; launcherScript: string | undefined } {
  const bridgePath = path.join(resourcesDir, "app.asar", "bin", "mcp-bridge.ts");
  const launcherPath = path.join(userDataDir, "tovu-desktop-mcp-launcher.sh");
  const windows = platform === "win32";
  const registration = buildSitesMcpRegistration({
    launcherPath: windows ? executablePath : launcherPath, platform, bridgePath, userDataDir,
  });
  // Registration stores a string; consume its quoted tokens just as the stdio adapter does.
  const args = windows
    ? Array.from(registration.args.matchAll(/"([^"]*)"|(\S+)/g), match => match[1] ?? match[2]!)
    : [registration.command];
  return {
    entry: {
      label: "tovu-desktop", command: windows ? registration.command : "/bin/sh", args,
      env: windows ? { ELECTRON_RUN_AS_NODE: "1" } : {}, serverName: "tovu-desktop", toolName: "list_sites",
    },
    launcherPath,
    launcherScript: windows ? undefined : buildSitesMcpLauncherScript({ electronPath: executablePath, bridgePath, userDataDir }),
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

/** Validates one JSON-RPC line; unrelated replies/notifications cannot satisfy the pending request. */
export function parseBridgeReply(
  { line, id }: { line: string; id: number },
): Record<string, unknown> | undefined {
  const reply: unknown = JSON.parse(line);
  if (!isRecord(reply) || reply.jsonrpc !== "2.0") throw new Error("invalid MCP JSON-RPC reply");
  if (reply.id !== id) return undefined;
  if (reply.error !== undefined || !isRecord(reply.result)) throw new Error(`MCP request ${id} failed`);
  return reply.result;
}

/** Checks bridge identity and its static tool roster; never invokes a delegated tool or a model. */
export function assertBridgeReplies(
  { initialize, tools, serverName, toolName }: {
    initialize: Record<string, unknown>; tools: Record<string, unknown>; serverName: string; toolName: string;
  },
): void {
  if (!isRecord(initialize.serverInfo) || initialize.serverInfo.name !== serverName) {
    throw new Error(`initialize did not identify ${serverName}`);
  }
  if (!Array.isArray(tools.tools) || !tools.tools.some(tool => isRecord(tool) && tool.name === toolName)) {
    throw new Error(`tools/list did not include ${toolName}`);
  }
}

/**
 * Temporary local handshake until @jini-ai/daemon publishes probeMcpBridge. A 30 s watchdog covers
 * the entire exchange; stdout is bounded and stderr is retained only for failure diagnostics.
 * Always SIGKILL and await close, including failed initialization and spawn errors.
 */
export async function smokeBridge(
  { entry, hostEnv }: { entry: BridgeCommand; hostEnv: NodeJS.ProcessEnv },
  { spawnBridge = spawn, watchdogMs = 30_000, cwd }: { spawnBridge?: typeof spawn; watchdogMs?: number; cwd?: string } = {},
): Promise<void> {
  const child = spawnBridge(entry.command, entry.args, {
    env: buildBridgeEnv({ hostEnv, entryEnv: entry.env }), stdio: ["pipe", "pipe", "pipe"], ...(cwd ? { cwd } : {}),
  });
  const closed = new Promise<void>(resolve => child.once("close", () => resolve()));
  let stderr = "";
  let stderrOverflow = false;
  let timer: ReturnType<typeof setTimeout> | undefined;
  child.stderr.setEncoding("utf8");
  child.stderr.on("data", (chunk: string) => {
    if (stderrOverflow) return;
    stderrOverflow = stderr.length + chunk.length > 65_536;
    stderr = stderrOverflow ? "[oversized stderr omitted]" : stderr + chunk;
  });
  try {
    await new Promise<void>((resolve, reject) => {
      let buffer = "";
      let id = 1;
      let initialize: Record<string, unknown> | undefined;
      const send = (message: object) => child.stdin.write(`${JSON.stringify(message)}\n`);
      timer = setTimeout(() => reject(new Error(`MCP watchdog exceeded ${watchdogMs} ms`)), watchdogMs);
      child.once("error", reject);
      child.stdin.on("error", reject);
      child.once("close", (code, signal) => reject(new Error(`bridge closed before completing MCP handshake (code ${code ?? "none"}, signal ${signal ?? "none"})`)));
      child.stdout.setEncoding("utf8");
      child.stdout.on("data", (chunk: string) => {
        buffer += chunk;
        if (buffer.length > 1_000_000) return reject(new Error("MCP stdout exceeded smoke buffer limit"));
        let newline: number;
        while ((newline = buffer.indexOf("\n")) !== -1) {
          const line = buffer.slice(0, newline);
          buffer = buffer.slice(newline + 1);
          try {
            const reply = parseBridgeReply({ line, id });
            if (!reply) continue;
            if (id === 1) {
              initialize = reply;
              id = 2;
              send({ jsonrpc: "2.0", method: "notifications/initialized" });
              send({ jsonrpc: "2.0", id, method: "tools/list", params: {} });
            } else {
              assertBridgeReplies({ initialize: initialize!, tools: reply, serverName: entry.serverName, toolName: entry.toolName });
              resolve();
              return;
            }
          } catch (error) { reject(error); return; }
        }
      });
      send({ jsonrpc: "2.0", id, method: "initialize", params: {
        protocolVersion: "2025-06-18", capabilities: {}, clientInfo: { name: "release-smoke", version: "0" },
      } });
    });
  } catch (error) {
    const detail = `${entry.label}: ${error instanceof Error ? error.message : String(error)}${stderr ? `\n${stderr}` : ""}`;
    // The expected tool name is trusted entry metadata; without the exemption a missing-tool failure reads "[redacted]".
    throw new Error(sanitizeUntrustedText({ text: redactLocalText({ text: detail }) },
      { maxLength: 2_000, diagnosticToolIds: [entry.toolName] }));
  } finally {
    clearTimeout(timer);
    child.kill("SIGKILL");
    await closed;
  }
}

/** Packaged release gate decisions. Effects enter through ports; no dev runtime is loaded here. */
import path from "node:path";

export const PACKAGED_CHAT_PROMPT = 'Call the site_guide tool with operation "overview" and then reply with exactly DONE.';

export class PackagedChatSmokeError extends Error {}

/** Build the shipped CLI invocation from the shell-owned serve environment.
 * @param input Paths and the environment returned by buildServeEnv.
 * @returns A spawn plan with every asset rooted in the packaged payload.
 */
export function buildPackagedChatServerPlan(
  { executablePath, nodeModulesDir, siteDir, port, serveEnv }: {
    executablePath: string; nodeModulesDir: string; siteDir: string; port: number; serveEnv: NodeJS.ProcessEnv;
  },
): { command: string; args: string[]; env: NodeJS.ProcessEnv; payloadRoot: string } {
  const payloadRoot = path.dirname(nodeModulesDir);
  const env: NodeJS.ProcessEnv = { ...serveEnv, ELECTRON_RUN_AS_NODE: "1", TOVU_REPO_ROOT: payloadRoot,
    TOVU_SITE_DIR: siteDir, TOVU_AGENT_CWD: siteDir, TOVU_HOST: "127.0.0.1",
    TOVU_ADMIN_DIST: path.join(payloadRoot, "apps/admin/dist"),
    TOVU_SITE_CHAT_DIST: path.join(payloadRoot, "apps/site-chat/dist") };
  // An inherited dev loader or proxy would let a broken package borrow the checkout's code/UI.
  for (const key of ["NODE_PATH", "NODE_OPTIONS", "TOVU_ADMIN_DEV_PROXY_URL"]) delete env[key];
  // A scratch site must own its daemon; an inherited origin can attach to an unrelated live site.
  for (const key of ["JINI_AGENT_DAEMON_URL", "JINI_AGENT_DAEMON_PORT", "TOVU_AGENT_DAEMON_TOKEN"]) delete env[key];
  return { command: executablePath, args: [path.join(payloadRoot, "dist/src/cli/main.js"),
    "serve", siteDir, "--port", String(port), "--emit-boot-token"], env, payloadRoot };
}

/** Select the lowest-cost Claude family offered by the actual picker; never silently use Opus.
 * @param input The authenticated /api/agents response.
 * @returns The advertised Haiku alias or concrete Haiku model ID.
 */
export function selectPackagedChatModel({ agents }: { agents: readonly {
  id: string; available?: boolean; authStatus?: string; discoveryPending?: boolean;
  models?: readonly { id: string }[];
}[] }): string {
  const claude = agents.find(agent => agent.id === "claude");
  if (!claude || claude.available === false || claude.authStatus === "missing" || claude.discoveryPending) {
    throw new PackagedChatSmokeError("Claude is not ready; sign in to the local CLI before the release smoke.");
  }
  const models = claude.models ?? [];
  const model = models.find(item => item.id === "haiku") ?? models.find(item => /(?:^|-)haiku(?:-|$)/.test(item.id));
  if (!model) throw new PackagedChatSmokeError("The Claude picker offers no Haiku model.");
  return model.id;
}

/** Interpret one inventory poll, leaving retry timing and cancellation with the gate.
 * @param input The authenticated inventory response.
 * @param _options Reserved optional settings.
 * @returns The selected Haiku model, or undefined while inventory discovery is pending.
 * @throws On an unexpected HTTP status, invalid inventory or failed body cancellation.
 */
export async function readPackagedChatModel(
  { response }: { response: Response },
  _options: Record<string, never> = {},
): Promise<string | undefined> {
  if (response.ok) {
    const inventory = await response.json() as Parameters<typeof selectPackagedChatModel>[0];
    const claude = inventory.agents.find(agent => agent.id === "claude");
    if (claude && !claude.discoveryPending) return selectPackagedChatModel(inventory);
  } else {
    await response.body?.cancel();
    if (response.status !== 503) throw new PackagedChatSmokeError("Packaged agent inventory is unavailable.");
  }
  return undefined;
}

/** The local release gate tolerates absent or inaccessible groups before verifying exit.
 * @param input Group leader PID, signal and process-signaling port.
 * @param _options Reserved optional settings.
 * @returns Nothing; exit verification remains with the caller.
 * @throws The original signaling error unless its code is ESRCH or EPERM.
 */
export function signalPackagedChatGroup(
  { pid, signal, kill }: { pid: number; signal: NodeJS.Signals; kill: typeof process.kill },
  _options: Record<string, never> = {},
): void {
  try { kill(-pid, signal); }
  catch (error) { if (!["ESRCH", "EPERM"].includes(String((error as NodeJS.ErrnoException).code))) throw error; }
}

export interface PackagedChatEvidence {
  run_id: string;
  run_status: string;
  content: string;
  attempt_base_json: string;
  events_json: string;
}

function record(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function eventsFrom(json: string): Record<string, unknown>[] {
  let value: unknown;
  try { value = JSON.parse(json); }
  catch { throw new PackagedChatSmokeError("chat.db contains invalid event JSON."); }
  if (!Array.isArray(value) || !value.every(record)) throw new PackagedChatSmokeError("chat.db contains invalid events.");
  return value;
}

/** The packaged daemon writes daemon.log as JSONL (`{"seq":…,"message":"[agent-daemon] …"}`), so
 *  an end-anchored match on the raw line never sees the message end; 0.1.18's first gate run failed
 *  on exactly that while the preflight had passed. Plain lines are still accepted as they are. */
function daemonLogMessages(daemonLog: string): string[] {
  return daemonLog.split(/\r?\n/).map(line => {
    try { const entry: unknown = JSON.parse(line); return record(entry) && typeof entry.message === "string" ? entry.message : line; }
    catch { return line; }
  });
}

function rawFrames(events: readonly Record<string, unknown>[]): Record<string, unknown>[] {
  return events.flatMap(event => {
    if (event.kind !== "raw") return [];
    const lines = Array.isArray(event.line) ? event.line : [event.line];
    return lines.flatMap(line => {
      if (typeof line !== "string") return [];
      return line.split(/\r?\n/).flatMap(part => {
        try { const frame: unknown = JSON.parse(part); return record(frame) ? [frame] : []; }
        catch { return []; } // Non-JSON CLI diagnostics are also legitimate raw lines.
      });
    });
  });
}

/** Require the overview call's own successful result, preserving the first matching result.
 * @param input Durable events and the previously selected delegated overview call.
 * @param _options Reserved optional settings.
 * @returns Nothing when the matching result explicitly reports success.
 * @throws PackagedChatSmokeError when the call or successful result is absent.
 */
export function assertPackagedSiteGuideResult(
  { events, delegated }: { events: readonly Record<string, unknown>[]; delegated: Record<string, unknown> | undefined },
  _options: Record<string, never> = {},
): void {
  if (!delegated) throw new PackagedChatSmokeError("The run did not call site_guide overview through the jini gateway.");
  const result = events.find(event => event.kind === "tool_result" && event.toolUseId === delegated.id);
  if (!result || result.isError !== false) throw new PackagedChatSmokeError("The delegated site_guide call did not return a successful result.");
}

/** Assert durable evidence for precisely the run we started, without returning transcript data.
 * @param input Joined chat.db row, expected run ID, and daemon log text.
 * @throws PackagedChatSmokeError with credential-free diagnostics on a failed gate.
 */
export function assertPackagedChatEvidence(
  { row, runId, daemonLog }: { row: PackagedChatEvidence | null; runId: string; daemonLog: string },
): void {
  if (!row || row.run_id !== runId) throw new PackagedChatSmokeError("chat.db has no evidence for the smoke run.");
  if (row.run_status !== "succeeded") throw new PackagedChatSmokeError("The packaged chat run did not succeed.");
  // attempt_base_json is the recovery baseline, not this attempt's live projection. A first run
  // starts with []; its new events and final status live on the joined ai_chat_messages row.
  const events = [...eventsFrom(row.attempt_base_json), ...eventsFrom(row.events_json)];
  const frames = rawFrames(events);
  const connected = frames.some(frame => frame.type === "system" && frame.subtype === "init"
    && Array.isArray(frame.mcp_servers) && frame.mcp_servers.some(server =>
      record(server) && server.name === "jini" && server.status === "connected"));
  if (!connected) throw new PackagedChatSmokeError("The init frame did not report jini connected.");
  const tools = events.filter(event => event.kind === "tool_use");
  const delegated = tools.find(event => ["mcp__jini__execute_readonly_delegated_tool", "mcp__jini__execute_delegated_tool"].includes(String(event.name))
    && record(event.input) && event.input.toolId === "site_guide"
    && record(event.input.input) && event.input.input.operation === "overview");
  assertPackagedSiteGuideResult({ events, delegated });
  if (row.content.trim() !== "DONE") throw new PackagedChatSmokeError("The packaged chat reply was not exactly DONE.");
  if (!daemonLogMessages(daemonLog).some(message => /^.*\[agent-daemon\] jini bridge preflight ok \(\d+ms\)\s*$/.test(message))) {
    throw new PackagedChatSmokeError("daemon.log has no successful jini bridge preflight.");
  }
}

export interface PackagedChatSmokePorts {
  acquireLock(): Promise<() => Promise<void>>;
  createSite(): Promise<string>;
  /** The launch adapter owns partial-start cleanup before rejecting. */
  start(siteDir: string): Promise<{ stop(): Promise<void> }>;
  chat(): Promise<string>;
  evidence(siteDir: string, runId: string): Promise<{ row: PackagedChatEvidence | null; daemonLog: string }>;
  removeSite(siteDir: string): Promise<void>;
}

/** Coordinate one local gate; teardown attempts every owned resource, including on partial startup.
 * @param input Effect ports, allowing failure/teardown tests without real servers or module mocks.
 * @returns Resolves only after evidence and all teardown have succeeded.
 */
export async function runPackagedChatSmoke({ ports }: { ports: PackagedChatSmokePorts }): Promise<void> {
  const release = await ports.acquireLock();
  let siteDir: string | undefined;
  let server: { stop(): Promise<void> } | undefined;
  const failures: unknown[] = [];
  try {
    siteDir = await ports.createSite();
    server = await ports.start(siteDir);
    const runId = await ports.chat();
    assertPackagedChatEvidence({ ...await ports.evidence(siteDir, runId), runId });
  } catch (error) { failures.push(error); }
  // Cleanup failures must not skip the remaining resources, or turn a failed release gate green.
  if (server) { try { await server.stop(); } catch (error) { failures.push(error); } }
  if (siteDir) { try { await ports.removeSite(siteDir); } catch (error) { failures.push(error); } }
  try { await release(); } catch (error) { failures.push(error); }
  if (failures.length) throw new AggregateError(failures, "Packaged chat smoke or teardown failed.");
}

/**
 * @file Filesystem-reading/writing helpers `scripts/stage-payload.ts` uses to walk source trees,
 * resolve Jini's pnpm-hoisted transitive dependencies, and verify the staged tree is complete —
 * extracted for the same reason `shell-staleness.ts` was: `stage-payload.ts` itself runs its
 * entire staging pipeline (real `rmSync`/`cpSync` against the live repo) the moment it is
 * imported, so nothing defined inside it can be exercised by a test that imports the script
 * directly. **This module has no import-time side effects at all** — importing it does nothing to
 * the filesystem; every effectful function here only acts when called, with paths the caller
 * supplies.
 *
 * `stageTransitiveDependencies` and `assertClosureComplete` (added in later commits) take `outDir`
 * as an explicit parameter rather than closing over `scripts/stage-payload.ts`'s module-level
 * constant of the same name, so a test can point them at a throwaway `fs.mkdtempSync` directory
 * instead of the real `staging/tovu-payload` tree.
 */
import { closeSync, cpSync, existsSync, lstatSync, mkdirSync, openSync, readdirSync, readFileSync, readSync, realpathSync, rmSync, statSync } from "node:fs";
import type { Dirent } from "node:fs";
import path from "node:path";

import { isBundleInput, type StalenessShell } from "./shell-staleness.ts";

/** One `{platform, arch}` a staging run targets, or a prebuild was built for (see {@link prebuildTarget}). */
interface Target {
  platform: string;
  arch: string;
}

/** The two fields {@link resolveTargets} reads off its `host` argument — real callers pass `process`
 *  itself, tests pass a plain object, and both satisfy this shape structurally. */
interface HostInfo {
  platform: string;
  arch: string;
}

/** The fields {@link resolveNpmLsCommand} reads off its `host` argument — real callers pass
 *  `process` itself (whose `execPath`/`platform`/`env` all satisfy this shape structurally), tests
 *  pass a plain object. */
interface NpmLsHost {
  execPath: string;
  platform: string;
  env: { npm_execpath?: string };
}

/** Byte/count tally shared by {@link stripGeneratedFiles} and {@link stripCoverageReports}, returned
 *  from {@link stripNonRuntimeFiles}. */
interface StripTally {
  declaration: number;
  sourceMap: number;
  coverage: number;
  bytes: number;
}

/** Byte/count tally shared by {@link prunePrebuildDir}, returned from {@link pruneNativePrebuilds}. */
interface PruneTally {
  prebuilds: number;
  buildInputs: number;
  bytes: number;
}

/** What {@link prebuildTarget} parses a `prebuilds/` entry name into. */
interface PrebuildBuilt {
  platform: string;
  architectures: string[];
}

/**
 * Top-level `node_modules` entries never staged, each for a reason that was checked rather than
 * assumed:
 *
 * - `@playwright` — test tooling only. Keep the production `playwright` / `playwright-core` driver:
 *   rendered fetch, screenshots and site evidence all use it through the host's dynamic loader.
 *   Browser downloads are separate; `stageDir` omits `.local-browsers` so desktop can use system
 *   Chrome without shipping a downloaded Chromium binary.
 * - `@oven` — 132 MB of Bun runtimes, `optionalDependencies` of `@modelcontextprotocol/ext-apps`,
 *   which uses Bun only to build and test ITSELF. Reached only through the `@jini-ai/*` pnpm store.
 * - `@rollup` — same package, same root cause: every `@rollup/rollup-<platform>` native listed under
 *   its `optionalDependencies`.
 * - `lucide-react` — 41.3 MB. The server never loads it: a static import walk from
 *   `dist/src/cli/main.js` never reaches it, and all 21 server files importing `@jini-ai/ui` still
 *   loaded with it hidden (`ADS-memory/reports/2026-09-12-desktop-payload-slim.md`). Its only
 *   importers were three shadcn primitives in `@jini-ai/ui`, which now use vendored icons, so no Jini
 *   compiled code imports it. `@jini-ai/ui` 0.3.7 and earlier still declare it.
 */
export const EXCLUDED_PACKAGES = new Set(["@playwright", "@oven", "@rollup", "lucide-react"]);

export function isExcluded(name: string): boolean {
  // `!`: `split` always returns at least one element, even for a separator-free string.
  const [head] = name.split(path.sep);
  return EXCLUDED_PACKAGES.has(head!) || EXCLUDED_PACKAGES.has(name);
}

/** Copies a package tree, always omitting browser downloads and optionally nested dependencies.
 * Filesystem failures propagate to staging; source files are never modified.
 * @complexity O(entries copied), with filesystem-managed copy buffers. */
export function stageDir(src: string, dest: string, dropNestedModules: boolean): void {
  mkdirSync(path.dirname(dest), { recursive: true });
  cpSync(src, dest, {
    recursive: true,
    dereference: true,
    // Hermetic Playwright installs put browser downloads inside playwright-core; keep only the driver.
    filter: (from) => path.basename(from) !== ".local-browsers" && (!dropNestedModules || path.basename(from) !== "node_modules"),
  });
}

export function declaredDependencies(packageDir: string): string[] {
  const manifestPath = path.join(packageDir, "package.json");
  if (!existsSync(manifestPath)) return [];
  return Object.keys(JSON.parse(readFileSync(manifestPath, "utf8")).dependencies ?? {});
}

/** Node's own upward `node_modules` walk — the only way to find a package in pnpm's store. */
export function findPackageDir(fromDir: string, depName: string): string | undefined {
  let dir = fromDir;
  for (;;) {
    const candidate = path.join(dir, "node_modules", depName);
    if (existsSync(path.join(candidate, "package.json"))) return realpathSync(candidate);
    const parent = path.dirname(dir);
    if (parent === dir) return undefined;
    dir = parent;
  }
}

/**
 * Resolves one `from -> dep` dependency edge and, unless `dep` is excluded, already visited, or
 * unresolvable, stages it (skipping the copy — but not the walk — when its destination is already
 * staged). Returns `undefined` when there is nothing further to walk from this edge, or the
 * resolved package's real directory plus whether staging it actually copied anything (as opposed
 * to finding it already there).
 */
function resolveDependencyEdge(
  from: string,
  dep: string,
  { outDir, visited }: { outDir: string; visited: Set<string> }
): { resolved: string; staged: boolean } | undefined {
  if (isExcluded(dep)) return undefined;
  const resolved = findPackageDir(from, dep);
  if (resolved === undefined || visited.has(resolved)) return undefined;
  visited.add(resolved);
  const dest = path.join(outDir, "node_modules", dep);
  const alreadyStaged = existsSync(dest);
  if (!alreadyStaged) stageDir(resolved, dest, true);
  return { resolved, staged: !alreadyStaged };
}

/**
 * Jini's packages declare ordinary npm dependencies of their own — `@jini-ai/devops` needs `undici`
 * — that exist only inside Jini's pnpm store. Tovu never names them, so the caller's own
 * `productionDependencyPaths()` never sees them and stages none of them.
 *
 * Takes `outDir` explicitly (rather than closing over `scripts/stage-payload.ts`'s module-level
 * constant of the same name) so a test can point it at a throwaway directory.
 */
export function stageTransitiveDependencies({ roots, outDir }: { roots: string[]; outDir: string }): number {
  const visited = new Set(roots);
  const queue = [...roots];
  let count = 0;
  while (queue.length > 0) {
    // `!`: the loop guard proves the queue is non-empty here.
    const from = queue.pop()!;
    for (const dep of declaredDependencies(from)) {
      const edge = resolveDependencyEdge(from, dep, { outDir, visited });
      if (edge === undefined) continue;
      queue.push(edge.resolved);
      if (edge.staged) count += 1;
    }
  }
  return count;
}

export function stagedPackageDirs(modulesDir: string): string[] {
  return readdirSync(modulesDir)
    .filter((entry) => !entry.startsWith("."))
    .flatMap((entry) => {
      const full = path.join(modulesDir, entry);
      return entry.startsWith("@") ? readdirSync(full).map((scoped) => path.join(full, scoped)) : [full];
    });
}

/**
 * Every declared dependency of every staged package must resolve INSIDE the staged tree.
 *
 * Without this the tree can ship incomplete and still pass every local test: `staging/` sits inside
 * this repo, so Node's upward walk quietly satisfies a missing import from the repo's OWN
 * `node_modules`. The `.app` only breaks once it is moved somewhere else, which is every real
 * install. A static check is the honest guard, because no in-repo runtime test can distinguish
 * "resolved from the bundle" from "resolved from an ancestor".
 *
 * Deliberately excluded packages are exempt — they are absent on purpose, not by accident.
 *
 * Takes `outDir` explicitly (rather than closing over `scripts/stage-payload.ts`'s module-level
 * constant of the same name) so a test can point it at a throwaway directory.
 *
 * Throws a plain `Error` on an incomplete closure, rather than calling
 * `scripts/stage-payload.ts`'s own `fail()` (which writes to stderr and calls `process.exit(1)`) —
 * `process.exit` inside a function under test kills the test runner itself. The script's own call
 * site catches this and forwards the same message to `fail()`, so ITS observable behavior — stderr
 * text, exit code — is unchanged; only how the message gets there changed.
 *
 * @throws {Error} listing every `pkg -> dep` pair that did not resolve.
 */
export function assertClosureComplete({ outDir }: { outDir: string }): void {
  const modulesDir = path.join(outDir, "node_modules");
  const unresolved = (packageDir: string, dep: string) => {
    const hoisted = path.join(modulesDir, dep, "package.json");
    const nested = path.join(packageDir, "node_modules", dep, "package.json");
    return !existsSync(hoisted) && !existsSync(nested);
  };
  // flatMap/filter/map preserve array order throughout, so this reports missing dependencies in
  // the same order the equivalent nested loop would have.
  const missing = stagedPackageDirs(modulesDir).flatMap((packageDir) =>
    declaredDependencies(packageDir)
      .filter((dep) => !isExcluded(dep) && unresolved(packageDir, dep))
      .map((dep) => `${path.relative(modulesDir, packageDir)} -> ${dep}`)
  );
  if (missing.length > 0) {
    throw new Error(
      `staged tree is missing ${missing.length} declared dependencies, so the packaged app would fail once installed outside this repo:\n  ${missing.join("\n  ")}`
    );
  }
}

/**
 * Package-name scopes whose `.map` files survive {@link stripNonRuntimeFiles}.
 *
 * `@jini-ai/*` is first-party, and a user crash report naming `dist/index.js:1:48210` is worth
 * nothing without the map that turns it back into a source position. Third-party maps buy no such
 * thing: nobody here is going to read a stack frame inside `drizzle-orm`.
 *
 * Keeping them is a PACKAGE DEAL with each package's own `src/`, and that is why nothing here
 * strips Jini sources. Jini's maps carry no `sourcesContent` — 400 of 400 `dist/**.js.map` sampled
 * under `staging/tovu-payload/node_modules/@jini-ai/` had the key absent entirely — so they resolve
 * a frame only by reading the `../src/*.ts` their `sources` array points at. Dropping `src/` would
 * leave 31 MB of maps that cannot name a single line.
 */
export const SOURCE_MAP_KEEP_SCOPES = new Set(["@jini-ai"]);

/** `.d.ts`, `.d.mts`, `.d.cts`, and the `.d.ts.map` that only exists to serve one. */
const DECLARATION_PATTERN = /\.d\.[cm]?ts(\.map)?$/;

/**
 * Why one staged `node_modules` file cannot be executed by the packaged app, or `undefined` to keep
 * it. `relPath` is POSIX-relative to the staged `node_modules` directory.
 *
 * Declarations are unconditional: `tsc` reads them at COMPILE time and no runtime ever opens one.
 * Their `.d.ts.map` siblings go with them by the same argument plus a stronger one — a declaration
 * map whose `.d.ts` is gone can be read by nothing at all.
 *
 * Source maps are conditional on {@link SOURCE_MAP_KEEP_SCOPES}. A `//# sourceMappingURL=` comment
 * pointing at a file that is not there is not an error in Node or Electron: the comment is only
 * consulted when something asks for a source position, and a miss degrades to the generated
 * position. It is how every `--omit=dev`-style install already behaves.
 *
 * @complexity O(1).
 */
export function strippableReason(relPath: string): "declaration" | "sourceMap" | undefined {
  const name = path.posix.basename(relPath);
  if (DECLARATION_PATTERN.test(name)) return "declaration";
  if (!name.endsWith(".map")) return undefined;
  // `!`: `split` always returns at least one element.
  return SOURCE_MAP_KEEP_SCOPES.has(relPath.split("/")[0]!) ? undefined : "sourceMap";
}

/** On-disk bytes of a file or tree — `st_blocks`, not `st_size`, because that is what the installed
 *  app costs. The payload's declarations average 4 KB apparent but a full block each.
 *  @complexity O(n) in entries walked. */
export function diskBytes(abs: string): number {
  const stat = lstatSync(abs);
  if (!stat.isDirectory()) return stat.blocks * 512;
  let total = 0;
  for (const entry of readdirSync(abs)) total += diskBytes(path.join(abs, entry));
  return total;
}

/** Deletes every file under `modulesDir` that {@link strippableReason} condemns, tallying by reason.
 *  @complexity O(n) in entries walked. */
function stripGeneratedFiles(modulesDir: string, tally: StripTally): void {
  const walk = (dir: string): void => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(full);
        continue;
      }
      const reason = strippableReason(path.relative(modulesDir, full).split(path.sep).join("/"));
      if (reason === undefined) continue;
      tally.bytes += diskBytes(full);
      tally[reason] += 1;
      rmSync(full, { force: true });
    }
  };
  walk(modulesDir);
}

/**
 * Deletes each staged package's own top-level `coverage/` directory.
 *
 * These are vitest HTML reports — 12.6 MB across the `@jini-ai/*` tree, 5.7 MB of it in
 * `@jini-ai/ui` alone. They are present because those packages are pnpm-linked local checkouts
 * that stage whole, not published tarballs whose `files:` would have excluded them.
 *
 * Only a package's OWN top-level `coverage/` is touched, never an arbitrary nested directory that
 * happens to share the name — a package is free to ship a runtime module called `coverage`.
 *
 * @complexity O(n) in staged packages.
 */
function stripCoverageReports(modulesDir: string, tally: StripTally): void {
  for (const packageDir of stagedPackageDirs(modulesDir)) {
    const coverage = path.join(packageDir, "coverage");
    if (!existsSync(coverage) || !statSync(coverage).isDirectory()) continue;
    tally.bytes += diskBytes(coverage);
    tally.coverage += 1;
    rmSync(coverage, { recursive: true, force: true });
  }
}

/**
 * Remove from the STAGED tree what the packaged app can never execute: type declarations, most
 * source maps, and vitest coverage reports. Roughly a third of the staged `node_modules`.
 *
 * This operates on `outDir` — the staging output — and NEVER on the repo's own `node_modules`.
 * Stripping declarations there would break `tsc` on the next typecheck, which is why the deletion
 * belongs in the staging step and nowhere earlier.
 *
 * @returns counts by reason plus the on-disk bytes freed.
 * @complexity O(n) in files under the staged `node_modules`.
 */
export function stripNonRuntimeFiles({ outDir }: { outDir: string }): StripTally {
  const modulesDir = path.join(outDir, "node_modules");
  const tally: StripTally = { declaration: 0, sourceMap: 0, coverage: 0, bytes: 0 };
  if (!existsSync(modulesDir)) return tally;
  stripCoverageReports(modulesDir, tally);
  stripGeneratedFiles(modulesDir, tally);
  return tally;
}

/**
 * The platform half of every prebuildify-style tag seen in the staged tree, plus the other values
 * `process.platform` can take. A `prebuilds/` entry whose prefix is not in here is left ALONE — see
 * {@link prebuildTarget} for why an unrecognized shape must never be read as "wrong architecture".
 */
const PREBUILD_PLATFORMS = new Set(["aix", "android", "darwin", "freebsd", "linux", "linuxmusl", "openbsd", "sunos", "win32"]);

/**
 * The `{platform, arch}` a `prebuilds/` entry was built for, or `undefined` when its name is not a
 * `<platform>-<arch>` tag this code recognizes.
 *
 * Both layouts in the payload share the tag: `better-sqlite3/prebuilds/darwin-x64.node` (a file,
 * resolved by `lib/binding.js:44` as `` `${target}.node` ``) and `argon2/prebuilds/darwin-x64/`
 * (a directory, resolved by `node-gyp-build`).
 *
 * `architectures` is a LIST because prebuildify writes a multi-architecture binary as one tag joined
 * by `+` — `darwin-x64+arm64` — and `node-gyp-build`'s own `parseTuple` splits it the same way
 * (`arr[1].split('+')`) before asking `architectures.includes(arch)`. Reading that as the single
 * arch `"x64+arm64"` would match no target and DELETE a binary that serves every one of them.
 *
 * `undefined` is the fail-safe answer. A future package naming its prebuilds differently
 * (`node-v127-darwin-x64`, say) must be kept whole rather than misread as a mismatch and deleted —
 * the pruner may only remove what it can positively identify as built for somewhere else.
 *
 * @complexity O(1).
 */
export function prebuildTarget(entryName: string): PrebuildBuilt | undefined {
  const tag = entryName.endsWith(".node") ? entryName.slice(0, -".node".length) : entryName;
  const split = tag.indexOf("-");
  if (split <= 0) return undefined;
  const platform = tag.slice(0, split);
  const architectures = tag.slice(split + 1).split("+");
  if (!PREBUILD_PLATFORMS.has(platform) || !architectures.every(Boolean)) return undefined;
  return { platform, architectures };
}

/**
 * Whether a prebuild for `built` can load on any of `targets`. `linuxmusl` is accepted for a `linux`
 * target because `better-sqlite3` picks it at runtime on an Alpine-style host (`isLinuxMusl()`), and
 * which libc the app lands on is not knowable at staging time.
 *
 * @complexity O(t) in targets.
 */
function prebuildServesTarget(built: PrebuildBuilt, targets: readonly Target[]): boolean {
  return targets.some(
    (target: Target) =>
      built.architectures.includes(target.arch) &&
      (target.platform === built.platform || (target.platform === "linux" && built.platform === "linuxmusl"))
  );
}

/**
 * The architectures a staging run must keep prebuilds for.
 *
 * electron-builder decides the architecture at PACK time, from its CLI flags, and
 * `electron-builder.yml` declares no `arch` to read. Staging runs first (`package.json`'s `package`
 * script: `... npm run stage && electron-builder --mac`), so it cannot ask electron-builder what it
 * is about to build. With no flag, electron-builder packs for the host — confirmed on
 * `release-probe2/mac/Tovu.app`, whose `Contents/MacOS/Tovu` is `lipo`-reported `x86_64` on this
 * `x86_64` machine — and the host is therefore the default here too.
 *
 * A cross-architecture or universal build MUST say so: `TOVU_TARGET_ARCH=arm64`, or
 * `TOVU_TARGET_ARCH=universal` for `electron-builder --universal`, which needs BOTH macOS
 * architectures. Getting this wrong does not produce a warning — it produces an app whose
 * `better-sqlite3` cannot find its binding on the other half of the fleet — which is why
 * {@link pruneNativePrebuilds} refuses a target it cannot serve rather than shipping one.
 *
 * @complexity O(1).
 */
export function resolveTargets(env: NodeJS.ProcessEnv, host: HostInfo): Target[] {
  const platform = env.TOVU_TARGET_PLATFORM || host.platform;
  const arch = env.TOVU_TARGET_ARCH || host.arch;
  if (arch === "universal") return [{ platform, arch: "x64" }, { platform, arch: "arm64" }];
  return [{ platform, arch }];
}

/**
 * How to invoke `npm ls`, portably. Plain `execFileSync("npm", …)` fails on Windows: the real
 * binary is `npm.cmd`, which `execFileSync` cannot exec directly (ENOENT), and even a shell-less
 * `.cmd` throws EINVAL on Node >= 18.20 without `shell: true`.
 *
 * Preferred, on every platform: when npm invoked this script as an npm script, npm has already set
 * `npm_execpath` to ITS OWN `npm-cli.js` — a plain JS file, not a `.cmd`/`.sh` wrapper — so
 * re-invoking that same file under this process's own `execPath` needs no shell at all.
 *
 * Fallback, only reached with no `npm_execpath` (e.g. this script run directly with
 * `node scripts/stage-payload.ts`, outside npm): run `npm` through the platform shell on win32,
 * where a shell is what resolves `npm` to `npm.cmd`. Elsewhere a shell changes nothing, since a
 * bare `npm` already execs directly — so it stays off there rather than added for no reason.
 *
 * @complexity O(1).
 */
export function resolveNpmLsCommand(host: NpmLsHost): { command: string; args: string[]; shell: boolean } {
  const lsArgs = ["ls", "--omit=dev", "--parseable", "--all"];
  if (host.env.npm_execpath) return { command: host.execPath, args: [host.env.npm_execpath, ...lsArgs], shell: false };
  return { command: "npm", args: lsArgs, shell: host.platform === "win32" };
}

/**
 * Inputs `node-gyp` reads to compile an addon from source. With a matching prebuild present, and
 * `electron-builder.yml`'s `npmRebuild: false`, nothing ever compiles — so these can never be read.
 * `better-sqlite3/deps/` alone is 9.8 MB: the SQLite amalgamation plus its gyp files.
 */
const NATIVE_BUILD_INPUTS = ["deps", "binding.gyp"];

/** Prunes one `prebuilds/` directory in place. Throws if nothing left in it serves the target.
 *  @complexity O(e) in entries of that one directory. */
function prunePrebuildDir(packageDir: string, targets: readonly Target[], modulesDir: string, tally: PruneTally): void {
  const prebuildsDir = path.join(packageDir, "prebuilds");
  let servesTarget = false;
  for (const entry of readdirSync(prebuildsDir)) {
    const built = prebuildTarget(entry);
    if (built === undefined) continue;
    if (prebuildServesTarget(built, targets)) {
      servesTarget = true;
      continue;
    }
    const full = path.join(prebuildsDir, entry);
    tally.bytes += diskBytes(full);
    tally.prebuilds += 1;
    rmSync(full, { recursive: true, force: true });
  }
  if (!servesTarget) {
    const wanted = targets.map((target: Target) => `${target.platform}-${target.arch}`).join(", ");
    throw new Error(
      `${path.relative(modulesDir, packageDir)} ships no prebuild for ${wanted}, so the packaged app could not load it. ` +
        `Set TOVU_TARGET_PLATFORM / TOVU_TARGET_ARCH to the architecture electron-builder will pack.`
    );
  }
}

/**
 * Keep only the native prebuilds the target can load, and drop the from-source build inputs that
 * only a failed prebuild lookup would ever reach for.
 *
 * Only packages that HAVE a `prebuilds/` directory are touched at all, so a package that builds its
 * addon at install time — and genuinely needs `binding.gyp` — keeps it.
 *
 * @throws {Error} naming the package, when a `prebuilds/` directory has nothing for the target.
 *   Deliberately a hard stop: this runs before signing and notarizing, which is the cheap end of
 *   discovering it.
 * @complexity O(n) in staged packages plus their prebuild entries.
 */
export function pruneNativePrebuilds({ outDir, targets }: { outDir: string; targets: readonly Target[] }): PruneTally {
  const modulesDir = path.join(outDir, "node_modules");
  const tally: PruneTally = { prebuilds: 0, buildInputs: 0, bytes: 0 };
  if (!existsSync(modulesDir)) return tally;
  for (const packageDir of stagedPackageDirs(modulesDir)) {
    if (!existsSync(path.join(packageDir, "prebuilds"))) continue;
    prunePrebuildDir(packageDir, targets, modulesDir, tally);
    for (const input of NATIVE_BUILD_INPUTS) {
      const full = path.join(packageDir, input);
      if (!existsSync(full)) continue;
      tally.bytes += diskBytes(full);
      tally.buildInputs += 1;
      rmSync(full, { recursive: true, force: true });
    }
  }
  return tally;
}

/** Whether to descend into / consider one directory entry at all.
 *  @complexity O(1). */
function isWalkable(entry: Dirent): boolean {
  if (entry.name === "node_modules" || entry.name.startsWith(".")) return false;
  return isBundleInput(entry.isDirectory() ? `${entry.name}/` : entry.name);
}

/** Newest mtime under a directory tree, or 0 if it does not exist.
 *  @complexity O(n) in files walked. */
export function newestMtime(abs: string): number {
  if (!existsSync(abs)) return 0;
  const stat = statSync(abs);
  if (!stat.isDirectory()) return isBundleInput(abs) ? stat.mtimeMs : 0;
  let newest = 0;
  for (const entry of readdirSync(abs, { withFileTypes: true })) {
    if (isWalkable(entry)) newest = Math.max(newest, newestMtime(path.join(abs, entry.name)));
  }
  return newest;
}

/**
 * The package paths in `npm ls --parseable` output that live under `modulesDir`, relative to it,
 * de-duplicated and sorted.
 *
 * Splits on `/\r?\n/`, not `"\n"`: npm on Windows can end lines with CRLF, and a `"\n"` split
 * would leave a `\r` on every name — a path that does not exist, so the package would silently
 * fail to stage.
 *
 * @param sep the platform path separator between `modulesDir` and each package path; production
 *   passes `path.sep`, tests pass either platform's.
 * @complexity O(n log n) in the number of lines.
 */
export function parseNpmLsPaths(stdout: string, modulesDir: string, sep: string): string[] {
  const prefix = `${modulesDir}${sep}`;
  const names = stdout
    .split(/\r?\n/)
    .filter((line) => line.startsWith(prefix))
    .map((line) => line.slice(prefix.length));
  return [...new Set(names)].sort();
}

/** {@link stageBundledNpm}'s input. */
interface StageBundledNpmInput {
  npmSrc: string;
  outDir: string;
}

/** {@link stageBundledNpm}'s result — used to log the measured size (plan §5, §6 S5). */
interface StageBundledNpmResult {
  fileCount: number;
  bytes: number;
}

/**
 * Hex prefixes of the first 4 bytes of a Mach-O (32/64-bit, either byte order), ELF, or PE ("MZ")
 * binary — see `plan-desktop-bundled-npx-2026-09-24.md` §5 and §6 S5. npm ships no compiled
 * binaries today (verified: `file` over all ~1,962 files); this is the guard that makes a FUTURE
 * npm version that adds one fail the build loudly instead of shipping unsigned inside
 * `Contents/Resources/` (which carries no per-file code signature of its own).
 */
export const NATIVE_BINARY_MAGIC_HEX_PREFIXES = ["feedface", "feedfacf", "cafebabe", "cefaedfe", "cffaedfe", "7f454c46", "4d5a"];

/**
 * Whether `filePath`'s first 4 bytes match a known native-binary magic number.
 *
 * A file shorter than 4 bytes cannot carry any of these magics (all are exactly 4 bytes, except
 * PE's 2-byte "MZ", which still needs at least those 2), so it reads as `false` rather than
 * throwing on a short read.
 *
 * @complexity O(1) — reads at most 4 bytes.
 */
export function hasNativeBinaryMagic(filePath: string): boolean {
  const fd = openSync(filePath, "r");
  let hex: string;
  try {
    const buf = Buffer.alloc(4);
    const bytesRead = readSync(fd, buf, 0, 4, 0);
    hex = buf.subarray(0, bytesRead).toString("hex");
  } finally {
    closeSync(fd);
  }
  return NATIVE_BINARY_MAGIC_HEX_PREFIXES.some((prefix) => hex.startsWith(prefix));
}

/** Directory names {@link stageBundledNpm} drops wholesale, at any depth — npm's own `docs/` and
 *  `man/`, neither of which the packaged app ever reads. Checked at every level, not only the npm
 *  root, since some of npm's bundled dependencies ship their own `docs/`/`man/` too. */
const NPM_DROPPED_DIR_NAMES = new Set(["docs", "man"]);

/** Whether {@link stageBundledNpm} should skip copying `absPath` (a directory or a file under
 *  `npmSrc`). `bin/*.cmd` is deliberately NOT excluded here — only `*.ps1` is, per plan §6 S5 step 1
 *  ("keeps bin/*.cmd"). @complexity O(1). */
function isNpmStagingDrop(absPath: string, isDirectory: boolean): boolean {
  const name = path.basename(absPath);
  if (isDirectory) return NPM_DROPPED_DIR_NAMES.has(name);
  return name.endsWith(".ps1");
}

/** Throws naming the first file under `dir` whose first 4 bytes match a native-binary magic
 *  number, relative to `root` — see {@link hasNativeBinaryMagic}.
 *  @complexity O(n) in files walked. */
function assertNoNativeBinaries(root: string, dir: string = root): void {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      assertNoNativeBinaries(root, full);
      continue;
    }
    if (!entry.isFile() || !hasNativeBinaryMagic(full)) continue;
    throw new Error(
      `stageBundledNpm: ${path.relative(root, full)} starts with native-binary (Mach-O/ELF/PE) magic bytes. npm is ` +
        `expected to ship no compiled binaries — files under Contents/Resources carry no per-file code signature, ` +
        `so shipping one unsigned would be a silent security regression rather than a build failure.`
    );
  }
}

/**
 * Stages the bundled npm package (`apps/desktop/node_modules/npm`) into `outDir` (`staging/npm`,
 * sibling to `staging/tovu-payload`), for `electron-builder.yml`'s `extraResources` to ship as
 * `Contents/Resources/npm/`. See `plan-desktop-bundled-npx-2026-09-24.md` §5 and §6 S5.
 *
 * Drops `docs/` and `man/` at every depth and any `*.ps1` file (Windows-only PowerShell wrappers
 * this app never execs — the `.cmd` wrappers next to them are kept). Refuses to stage a tree that
 * is not really an npm package root, and refuses — after copying — a staged tree that contains any
 * file starting with native-binary magic bytes (see {@link assertNoNativeBinaries}).
 *
 * @throws {Error} if `npmSrc` has no `bin/npx-cli.js`, or if the staged tree contains a native
 *   binary.
 * @complexity O(n) in files under `npmSrc`.
 */
export function stageBundledNpm({ npmSrc, outDir }: StageBundledNpmInput): StageBundledNpmResult {
  if (!existsSync(path.join(npmSrc, "bin", "npx-cli.js"))) {
    throw new Error(`stageBundledNpm: no bin/npx-cli.js under ${npmSrc} — is this really an npm package root?`);
  }

  rmSync(outDir, { recursive: true, force: true });
  mkdirSync(path.dirname(outDir), { recursive: true });
  cpSync(npmSrc, outDir, {
    recursive: true,
    dereference: true,
    filter: (src) => {
      if (src === npmSrc) return true;
      let isDirectory: boolean;
      try {
        isDirectory = statSync(src).isDirectory();
      } catch {
        return false;
      }
      return !isNpmStagingDrop(src, isDirectory);
    },
  });

  assertNoNativeBinaries(outDir);

  return { fileCount: countFiles(outDir), bytes: diskBytes(outDir) };
}

/** Recursive file count under `dir` — used only for {@link stageBundledNpm}'s reported result.
 *  @complexity O(n) in entries walked. */
function countFiles(dir: string): number {
  let count = 0;
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) count += countFiles(full);
    else count += 1;
  }
  return count;
}

/**
 * The two SPA builds, staged at their checkout-relative paths so one `path.join` serves both modes.
 *
 * `marker` is the exact file the SERVER probes to decide between serving the shell and answering
 * 503 — `admin-static.ts:92/115` checks `index.html`, and `site-chat-static.ts:37` checks
 * `site-assistant.js`. Site-chat has NO `index.html` at all: it is a single self-mounting IIFE
 * bundle loaded by a `<script>` tag, not an app with client-side routing (`app.ts:1336-1338`).
 * Asserting the wrong marker would have hard-failed staging on a perfectly good build.
 */
export const STAGED_SHELLS: (StalenessShell & { sourceDirs?: string[]; sourceFiles?: string[] })[] = [
  {
    relative: path.join("apps", "admin", "dist"),
    marker: "index.html",
    // NOT `npm run admin:build`. That chains through `check-no-linked-jini.mjs`, which correctly
    // refuses to build while any @jini-ai/* package is npm-linked -- a guard that exists for
    // DISTRIBUTABLE builds. Refreshing a shell for a local package run is not that, and the direct
    // vite invocation is the command that actually works on a linked checkout. Do not suggest
    // `npm run unlink:jini` here: it swaps the whole tree to published Jini for no benefit.
    buildWith: "cd apps/admin && npx vite build",
    sourceDirs: [path.join("apps", "admin", "src")],
    sourceFiles: [path.join("apps", "admin", "package.json")],
  },
  {
    relative: path.join("apps", "site-chat", "dist"),
    marker: "site-assistant.js",
    buildWith: "cd apps/site-chat && npx vite build",
    sourceDirs: [path.join("apps", "site-chat", "src")],
    sourceFiles: [path.join("apps", "site-chat", "package.json")],
  },
];

/** Copy the runtime files at the same relative paths consumed by the packaged server. */
export function stagePayloadFiles({ repoRoot, outDir }: { repoRoot: string; outDir: string }): void {
  cpSync(path.join(repoRoot, "package.json"), path.join(outDir, "package.json"));
  cpSync(path.join(repoRoot, "dist"), path.join(outDir, "dist"), { recursive: true, dereference: true });
  for (const shell of STAGED_SHELLS) {
    cpSync(path.join(repoRoot, shell.relative), path.join(outDir, shell.relative), { recursive: true, dereference: true });
  }
}

/**
 * @file The orchestration half of `scripts/stage-payload.ts`: every precondition, staging step,
 * post-condition and summary line of assembling `apps/desktop/staging/tovu-payload/` — see that
 * script's header for WHY the payload ships, what ships, and its provenance.
 *
 * The filesystem, the `npm ls` child, the effectful staging steps from `./stage-payload-lib.ts`
 * (each already tested on its own there), the environment, the host and the output stream are all
 * injected ports; the script binds the real ones. Every refusal is a thrown
 * {@link StagePayloadError} carrying the exact message the CLI prints after `stage-payload: `, so the
 * script's only job left is to print it and exit 1.
 */
import type * as nodeFs from "node:fs";
import path from "node:path";

import type { assertDistImportsDeclared } from "./dist-import-check.ts";
import { shellStalenessFailure } from "./shell-staleness.ts";
import type { StalenessShell } from "./shell-staleness.ts";
import { isExcluded, parseNpmLsPaths, resolveNpmLsCommand, resolveTargets } from "./stage-payload-lib.ts";
import type * as lib from "./stage-payload-lib.ts";

/** A refusal to stage; `message` is printed verbatim after `stage-payload: `. */
export class StagePayloadError extends Error {}

/** One `dist/runtime-manifest.json`, as far as staging reads it — see {@link readRuntimeManifest}. */
interface RuntimeManifest {
  cliEntry: string;
}

/** One `STAGED_SHELLS` entry. `sourceDirs`/`sourceFiles` stay optional to match the defensive
 *  `?? []` reads in {@link failIfShellIsStale}. */
interface ShellEntry extends StalenessShell {
  sourceDirs?: string[];
  sourceFiles?: string[];
}

/** The `node:fs` surface staging uses — the real module at the composition edge. */
type StageFs = Pick<typeof nodeFs, "cpSync" | "existsSync" | "lstatSync" | "mkdirSync" | "readdirSync" | "readFileSync" | "realpathSync" | "rmSync" | "statSync" | "unlinkSync">;

/** The effectful staging steps, each defined and tested in `./stage-payload-lib.ts` / `./dist-import-check.ts`. */
interface StageSteps {
  stagePayloadFiles: typeof lib.stagePayloadFiles;
  stageDir: typeof lib.stageDir;
  stageTransitiveDependencies: typeof lib.stageTransitiveDependencies;
  stripNonRuntimeFiles: typeof lib.stripNonRuntimeFiles;
  pruneNativePrebuilds: typeof lib.pruneNativePrebuilds;
  assertClosureComplete: typeof lib.assertClosureComplete;
  assertDistImportsDeclared: typeof assertDistImportsDeclared;
  stageBundledNpm: typeof lib.stageBundledNpm;
  diskBytes: typeof lib.diskBytes;
  newestMtime: typeof lib.newestMtime;
}

/** Everything {@link runStagePayload} touches outside its own arguments. */
interface StagePorts {
  fs: StageFs;
  steps: StageSteps;
  shells: readonly ShellEntry[];
  execFileSync(command: string, args: string[], options: { cwd: string; encoding: "utf8"; maxBuffer: number; shell: boolean }): string;
  env: NodeJS.ProcessEnv;
  host: { execPath: string; platform: string; arch: string };
  stdout: { write(text: string): unknown };
}

/** The repo-derived locations every step reads or writes. */
interface StageLayout {
  repoRoot: string;
  desktopDir: string;
  outDir: string;
  repoModulesDir: string;
}

function fail(message: string): never {
  throw new StagePayloadError(message);
}

const megabytes = (bytes: number) => (bytes / 1048576).toFixed(1);
const readJson = (fs: StageFs, file: string) => JSON.parse(fs.readFileSync(file, "utf8"));

/** Tovu's production dependency closure, as package paths relative to its `node_modules`. */
function productionDependencyPaths(layout: StageLayout, ports: StagePorts): string[] {
  let stdout: string;
  // `resolveNpmLsCommand` picks the portable invocation — see its doc comment for why a bare
  // `execFileSync("npm", …)` fails on Windows.
  const { command, args, shell } = resolveNpmLsCommand({ ...ports.host, env: ports.env });
  try {
    stdout = ports.execFileSync(command, args, { cwd: layout.repoRoot, encoding: "utf8", maxBuffer: 64 * 1024 * 1024, shell });
  } catch (err) {
    // `npm ls` exits non-zero on any tree quibble (the linked `@jini-ai/*` produce several) while
    // still printing a complete, usable tree on stdout.
    // `as`: `execFileSync`'s thrown error carries the same `stdout` it would have returned.
    stdout = (err as { stdout?: string }).stdout ?? "";
  }
  const names = parseNpmLsPaths(stdout, layout.repoModulesDir, path.sep);
  if (names.length === 0) {
    fail(`npm ls listed no packages under ${layout.repoModulesDir}. Has \`npm install\` run at the repo root?`);
  }
  return names;
}

/**
 * The package names the built server may import bare: root `dependencies` plus every npm workspace
 * package (`@tovu/sdk`), both of which {@link productionDependencyPaths} stages. Anything else it
 * imports is a devDependency and absent from the payload -- see `./dist-import-check.ts`.
 */
function declaredRuntimePackages({ repoRoot }: StageLayout, { fs }: StagePorts): Set<string> {
  const rootPackage = readJson(fs, path.join(repoRoot, "package.json"));
  const packagesDir = path.join(repoRoot, "packages");
  const workspaces = fs.readdirSync(packagesDir)
    .map((entry) => path.join(packagesDir, entry, "package.json"))
    .filter((manifestPath) => fs.existsSync(manifestPath))
    .map((manifestPath) => readJson(fs, manifestPath).name as string);
  return new Set([...Object.keys(rootPackage.dependencies ?? {}), ...workspaces]);
}

function stagePackage(name: string, layout: StageLayout, { fs, steps }: StagePorts): boolean {
  if (isExcluded(name)) return false;
  const src = path.join(layout.repoModulesDir, name);
  const dest = path.join(layout.outDir, "node_modules", name);
  if (!fs.existsSync(src)) return false;
  // A nested entry (`liquidjs/node_modules/commander`) already came along with its parent.
  if (fs.existsSync(dest)) return false;

  // `@jini-ai/*` and `@tovu/sdk` are `file:`/workspace links whose real directories carry a pnpm
  // symlink farm under `node_modules/`. Dereferencing that would drag in the entire pnpm store;
  // dropping it makes their imports resolve from the staged root instead, which is where npm
  // hoisted those same dependencies.
  steps.stageDir(src, dest, fs.lstatSync(src).isSymbolicLink());
  return true;
}

/**
 * npm's hoisted view only covers the `@jini-ai/*` packages this repo names directly. Their imports
 * of each other — `@jini-ai/agent-runtime` needing `@jini-ai/platform`, which Tovu never mentions —
 * resolve in dev through Jini's own pnpm workspace links, which cannot ship. Staging every Jini
 * package flat puts all of them somewhere one upward walk can find.
 *
 * @returns the real source directory of each staged package, to seed the dependency closure.
 */
function stageJiniPackages(layout: StageLayout, { fs, steps }: StagePorts): string[] {
  const anchor = path.join(layout.repoModulesDir, "@jini-ai", "core");
  if (!fs.existsSync(anchor)) {
    fail(`no @jini-ai/core under ${layout.repoModulesDir}; cannot locate the Jini packages.`);
  }
  // Derived from the link itself so it cannot drift from wherever Jini really is.
  const packagesDir = path.dirname(fs.realpathSync(anchor));
  const roots: string[] = [];
  for (const entry of fs.readdirSync(packagesDir)) {
    const src = path.join(packagesDir, entry);
    const manifest = path.join(src, "package.json");
    if (!fs.existsSync(manifest)) continue;
    roots.push(src);
    const dest = path.join(layout.outDir, "node_modules", readJson(fs, manifest).name);
    if (fs.existsSync(dest)) continue;
    steps.stageDir(src, dest, true);
  }
  return roots;
}

/** Replace one symlink with a dereferenced copy of what it points at; a dangling link is dropped.
 *  Unlink/copy failures propagate; the target is never removed.
 *  @returns 1 when replaced, 0 when the link dangled.
 *  @complexity O(entries copied), with filesystem-managed copy buffers. */
function materializeLink(fs: StageFs, full: string): number {
  // Node 24.2's native rmSync follows links during its type check: directory links throw EISDIR,
  // and dangling links are left behind. Unlink the known symlink itself on both Node 22 and 24.
  let target;
  try {
    target = fs.realpathSync(full);
  } catch {
    fs.unlinkSync(full);
    return 0;
  }
  fs.unlinkSync(full);
  fs.cpSync(target, full, { recursive: true, dereference: true });
  return 1;
}

/**
 * Replace every symlink in the staged tree with the real thing it points at.
 *
 * `cpSync`'s `dereference` only dereferences links whose target lies inside the subtree being
 * copied. A link pointing OUT of it (npm's `.bin/node-which -> ../which/bin/…`) is recreated as a
 * symlink to the resolved ABSOLUTE path — so a developer-machine path ends up inside the bundle.
 * `codesign --verify --deep --strict` rejects that outright ("invalid destination for symbolic link
 * in bundle"), and on any other machine it would simply dangle.
 */
function materializeSymlinks(fs: StageFs, dir: string): number {
  let replaced = 0;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isSymbolicLink()) replaced += materializeLink(fs, full);
    // Re-stat rather than trusting the dirent: an entry just materialized from a link to a
    // directory needs walking too, in case its own contents carried links outward.
    if (fs.existsSync(full) && fs.statSync(full).isDirectory()) replaced += materializeSymlinks(fs, full);
  }
  return replaced;
}

function assertNoSymlinks(fs: StageFs, dir: string): void {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isSymbolicLink()) fail(`staged tree still contains a symlink after materialization: ${full}`);
    if (entry.isDirectory()) assertNoSymlinks(fs, full);
  }
}

/**
 * `dist/runtime-manifest.json` is the root build's own output (`emit-dist-package-json.mjs`, derived
 * from the root `package.json`'s `bin.tovu`) — read here rather than assuming the conventional
 * `dist/src/cli/main.js`, since that literal is exactly what broke once already when `src/` was
 * renamed (2026-08-27 restructure).
 */
function readRuntimeManifest(fs: StageFs, dir: string, repoRoot: string): RuntimeManifest {
  const manifestPath = path.join(dir, "dist", "runtime-manifest.json");
  if (!fs.existsSync(manifestPath)) {
    fail(`no ${manifestPath}. Run \`npm run build\` at ${repoRoot} first.`);
  }
  const manifest = readJson(fs, manifestPath);
  if (typeof manifest.cliEntry !== "string") fail(`${manifestPath} has no "cliEntry" string field.`);
  return manifest;
}

/**
 * The shell resolves the CLI through `resolveCliEntry`, which reads `<payloadRoot>/package.json`'s
 * `bin.tovu` — so that manifest has to be staged, and it has to agree with the `cliEntry` the build
 * recorded. Two independently-derived paths that are allowed to disagree are exactly the failure
 * `runtime-manifest.json` was introduced to prevent, so assert they match instead of picking one.
 */
function assertCliEntryAgreement(fs: StageFs, repoRoot: string, manifest: RuntimeManifest): void {
  const binEntry = readJson(fs, path.join(repoRoot, "package.json")).bin?.tovu;
  if (binEntry !== manifest.cliEntry) {
    fail(`the root package.json's bin.tovu ("${binEntry}") and dist/runtime-manifest.json's cliEntry ("${manifest.cliEntry}") disagree. Re-run \`npm run build\`.`);
  }
}

/** Count `.sql` migrations on both sides — a stale `dist/` is the single likeliest reason a
 *  packaged app rejects a site with `SITE_NEWER_THAN_RUNTIME`, and it is invisible otherwise. */
function countMigrations(fs: StageFs, dir: string): number {
  return fs.existsSync(dir) ? fs.readdirSync(dir).filter((entry) => entry.endsWith(".sql")).length : 0;
}

function failIfDistIsStale(layout: StageLayout, { fs }: StagePorts): void {
  const source = countMigrations(fs, path.join(layout.repoRoot, "apps", "website", "src", "platform", "db", "drizzle"));
  const built = countMigrations(fs, path.join(layout.outDir, "dist", "src", "platform", "db", "drizzle"));
  if (built < source) {
    fail(
      `the staged dist/ carries ${built} migrations but source has ${source}. This payload is built ` +
        `from a stale dist/ and will reject any site created from current source with ` +
        `SITE_NEWER_THAN_RUNTIME. Re-run \`npm run build\` at the repo root for a shippable payload.`
    );
  }
}

/**
 * Refuse a shell whose build output is OLDER than its own source. The comparison itself lives in
 * `./shell-staleness.ts` (and is tested there, against the real 2026-09-12 incident); this
 * function is only the filesystem half.
 *
 * BEHAVIOUR CHANGE, deliberately: anyone packaging from a checkout whose shells are behind their
 * source now hits a HARD STOP where they previously got a shipped-but-wrong artifact.
 *
 * mtime is the floor, not the ceiling. A build-provenance record (git HEAD sha plus a dirty flag,
 * written at build time and asserted here) would be stricter — but a matching `head_sha` is NOT
 * proof of freshness if the build came from a dirty tree, so such a record must carry the dirty
 * flag and staging must refuse a dirty-built payload. Otherwise it becomes another
 * green-for-the-wrong-reason check, which is the failure class this guard exists to end.
 *
 * @complexity O(n) in source files under the shell's own tree.
 */
function failIfShellIsStale(repoRoot: string, shell: ShellEntry, { steps }: StagePorts): void {
  const builtAt = steps.newestMtime(path.join(repoRoot, shell.relative, shell.marker));
  let sourceAt = 0;
  for (const dir of shell.sourceDirs ?? []) sourceAt = Math.max(sourceAt, steps.newestMtime(path.join(repoRoot, dir)));
  for (const file of shell.sourceFiles ?? []) sourceAt = Math.max(sourceAt, steps.newestMtime(path.join(repoRoot, file)));

  const failure = shellStalenessFailure(builtAt, sourceAt, shell);
  if (failure) fail(failure);
}

/** Every check that must pass before anything under `staging/` is touched. */
function assertSourcePreconditions(layout: StageLayout, ports: StagePorts): RuntimeManifest {
  const { fs } = ports;
  const manifest = readRuntimeManifest(fs, layout.repoRoot, layout.repoRoot);
  assertCliEntryAgreement(fs, layout.repoRoot, manifest);
  if (!fs.existsSync(path.join(layout.repoRoot, manifest.cliEntry))) {
    fail(`no built Tovu CLI at ${path.join(layout.repoRoot, manifest.cliEntry)} (from runtime-manifest.json's cliEntry). Run \`npm run build\` at ${layout.repoRoot} first.`);
  }
  /**
   * The admin and site-chat SPAs are SEPARATE builds from `dist/`: the root `npm run build` compiles
   * the server only. So a checkout that builds cleanly can still have neither shell, and a build made
   * from it produces an app whose every site tab answers `/admin` and `/site-chat` with a 503 — a
   * failure that first shows up after packaging, signing and notarizing. Refusing to stage is the
   * cheap end of that.
   */
  for (const shell of ports.shells) {
    if (!fs.existsSync(path.join(layout.repoRoot, shell.relative, shell.marker))) {
      fail(`no built shell at ${path.join(layout.repoRoot, shell.relative, shell.marker)}. Run \`${shell.buildWith}\` at ${layout.repoRoot} first.`);
    }
    // Existence was never enough -- see failIfShellIsStale's header for the bundle this missed.
    failIfShellIsStale(layout.repoRoot, shell, ports);
  }
  return manifest;
}

/** Copy the payload and its dependency closure into a fresh `outDir`; returns the staged package count. */
function stageTree(layout: StageLayout, ports: StagePorts): number {
  const { fs, steps } = ports;
  fs.rmSync(layout.outDir, { recursive: true, force: true });
  fs.mkdirSync(layout.outDir, { recursive: true });
  // `package.json` is staged verbatim because `resolveCliEntry` reads `bin.tovu` from it in BOTH
  // modes — copying it is what keeps that function free of any packaged-mode branch at all.
  steps.stagePayloadFiles({ repoRoot: layout.repoRoot, outDir: layout.outDir });
  const jiniRoots = stageJiniPackages(layout, ports);
  const staged =
    productionDependencyPaths(layout, ports).filter((name) => stagePackage(name, layout, ports)).length +
    jiniRoots.length +
    steps.stageTransitiveDependencies({ roots: jiniRoots, outDir: layout.outDir });
  if (!fs.existsSync(path.join(layout.outDir, "node_modules", "better-sqlite3"))) {
    fail("staged tree has no better-sqlite3 — Tovu's CLI cannot open a site database without it.");
  }
  return staged;
}

/** Run a lib step whose only failure mode is a plain `Error`, as a staging refusal. */
function asRefusal<T>(step: () => T): T {
  try {
    return step();
  } catch (err) {
    // `as`: assertClosureComplete, assertDistImportsDeclared, pruneNativePrebuilds and
    // stageBundledNpm only ever throw a plain Error.
    return fail((err as Error).message);
  }
}

/** Trim the staged tree to what ships, then prove the closure and imports are still complete. */
function trimAndVerify(layout: StageLayout, ports: StagePorts, manifest: RuntimeManifest) {
  const { fs, steps } = ports;
  const materialized = materializeSymlinks(fs, layout.outDir);
  assertNoSymlinks(fs, layout.outDir);
  // BEFORE assertClosureComplete, deliberately: the closure is then verified against the tree that
  // actually ships, not against a fuller one the strip has yet to touch.
  const stripped = steps.stripNonRuntimeFiles({ outDir: layout.outDir });
  // See `resolveTargets` for why this is the host unless TOVU_TARGET_ARCH says otherwise.
  const targets = resolveTargets(ports.env, ports.host);
  const pruned = asRefusal(() => {
    const tally = steps.pruneNativePrebuilds({ outDir: layout.outDir, targets });
    steps.assertClosureComplete({ outDir: layout.outDir });
    steps.assertDistImportsDeclared({
      distDir: path.join(layout.outDir, "dist"),
      entry: path.join(layout.outDir, manifest.cliEntry),
      declared: declaredRuntimePackages(layout, ports),
    });
    return tally;
  });
  return { materialized, stripped, targets, pruned };
}

/** The staged tree must still carry the CLI entry and every shell the source checks demanded. */
function assertStagedTree(layout: StageLayout, ports: StagePorts, manifest: RuntimeManifest): void {
  const { fs } = ports;
  const stagedManifest = readRuntimeManifest(fs, layout.outDir, layout.repoRoot);
  if (stagedManifest.cliEntry !== manifest.cliEntry || !fs.existsSync(path.join(layout.outDir, stagedManifest.cliEntry))) {
    fail(`the staged tree's runtime-manifest.json names cliEntry "${stagedManifest.cliEntry}", which did not survive the dist/ copy.`);
  }
  for (const shell of ports.shells) {
    // After `materializeSymlinks`, not before: that pass could in principle empty out a dangling link.
    if (!fs.existsSync(path.join(layout.outDir, shell.relative, shell.marker))) {
      fail(`staged tree has no shell at ${path.join(layout.outDir, shell.relative, shell.marker)} — the copy must have gone wrong.`);
    }
  }
  failIfDistIsStale(layout, ports);
}

/**
 * The bundled npm package (plan-desktop-bundled-npx-2026-09-24.md §5, §6 S5) — staged into its own
 * `staging/npm` tree, a SIBLING of `outDir` (`staging/tovu-payload`), not inside it: `npm` is a
 * devDependency of apps/desktop itself (package.json), never a runtime dependency of the Tovu
 * payload above, so it has nothing to do with `productionDependencyPaths()`. `electron-builder.yml`
 * ships it via its own pair of `extraResources` entries at `Contents/Resources/npm/`.
 */
function stageNpm(layout: StageLayout, ports: StagePorts): void {
  const npmSrc = path.join(layout.desktopDir, "node_modules", "npm");
  const npmStagingDir = path.join(layout.desktopDir, "staging", "npm");
  const npmStaged = asRefusal(() => ports.steps.stageBundledNpm({ npmSrc, outDir: npmStagingDir }));
  ports.stdout.write(`stage-payload: staged bundled npm -> ${npmStagingDir} (${npmStaged.fileCount} files, ${megabytes(npmStaged.bytes)} MB)\n`);
}

/**
 * Assemble the whole shippable payload.
 *
 * @param input.repoRoot the Tovu checkout whose build output and dependencies are staged.
 * @param input.desktopDir `apps/desktop`; the payload lands at `staging/tovu-payload/` under it.
 * @throws {StagePayloadError} on every refusal, before or after any staging write.
 * @complexity O(n) in files under the staged tree.
 */
export function runStagePayload({ repoRoot, desktopDir }: { repoRoot: string; desktopDir: string }, ports: StagePorts): void {
  const layout: StageLayout = {
    repoRoot, desktopDir,
    outDir: path.join(desktopDir, "staging", "tovu-payload"),
    repoModulesDir: path.join(repoRoot, "node_modules"),
  };
  const manifest = assertSourcePreconditions(layout, ports);
  const staged = stageTree(layout, ports);
  const { materialized, stripped, targets, pruned } = trimAndVerify(layout, ports, manifest);
  assertStagedTree(layout, ports, manifest);
  stageNpm(layout, ports);

  // `diskBytes`, not `du -sh`: `du` does not exist on Windows, and diskBytes already walks the same
  // on-disk block accounting the strip/prune tallies below use, so all three sizes stay comparable.
  const sizeMb = megabytes(ports.steps.diskBytes(layout.outDir));
  ports.stdout.write(`stage-payload: staged ${staged} packages, materialized ${materialized} symlinks -> ${layout.outDir} (${sizeMb} MB)\n`);
  ports.stdout.write(
    `stage-payload: stripped ${stripped.declaration} declarations, ${stripped.sourceMap} third-party source maps, ` +
      `${stripped.coverage} coverage reports (${megabytes(stripped.bytes)} MB on disk)\n`
  );
  ports.stdout.write(
    `stage-payload: native prebuilds kept for ${targets.map((target) => `${target.platform}-${target.arch}`).join(" + ")} only; ` +
      `removed ${pruned.prebuilds} other-architecture prebuilds and ${pruned.buildInputs} from-source build inputs ` +
      `(${megabytes(pruned.bytes)} MB on disk)\n`
  );
}

/**
 * The repo the payload is staged FROM: this checkout (`apps/desktop/../..`) unless
 * `--repo-root <dir>` names another one (a clean clone, or a deliberately incomplete tree to prove
 * a refusal). The payload always lands under THIS `apps/desktop/staging/`.
 */
export function resolveStageRoot({ argv, desktopDir }: { argv: readonly string[]; desktopDir: string }): string {
  const flagAt = argv.indexOf("--repo-root");
  const explicit = flagAt === -1 ? undefined : argv[flagAt + 1];
  return explicit ? path.resolve(explicit) : path.resolve(desktopDir, "..", "..");
}

/**
 * The CLI contract: a {@link StagePayloadError} prints as `stage-payload: <message>` and exits 1;
 * anything else is a bug and propagates with its stack, as an uncaught error always did.
 *
 * @returns the process exit code.
 */
export function stagePayloadCli(
  { argv, desktopDir }: { argv: readonly string[]; desktopDir: string },
  ports: StagePorts & { stderr: { write(text: string): unknown } },
): 0 | 1 {
  try {
    runStagePayload({ repoRoot: resolveStageRoot({ argv, desktopDir }), desktopDir }, ports);
    return 0;
  } catch (err) {
    if (!(err instanceof StagePayloadError)) throw err;
    ports.stderr.write(`stage-payload: ${err.message}\n`);
    return 1;
  }
}

export type { ShellEntry, StageFs, StagePorts, StageSteps };

import { SITES_MCP_SERVER_ID } from "./sites-mcp-registration.ts";
/**
 * @file Own-server mode: spawn Tovu's own `tovu serve <dir>` CLI, learn the port it bound, and
 * supervise it for the life of the window.
 *
 * Deliberately free of any `electron` import. Everything here is plain Node, so every function is
 * directly assertable from `node --test` without an Electron runtime — `main.ts` keeps the parts
 * that genuinely need `app`/`BrowserWindow` and nothing else. `spawnFn` is injectable for the same
 * reason: the supervision contract (ready, boot timeout, premature exit, graceful stop) is testable
 * against a fake child, so no test ever has to boot a real site.
 *
 * The seam is Tovu's, not ours. `apps/website/src/cli/commands/serve.ts` boots the site dir end to
 * end and prints exactly one startup line (api.spec.md §5); `cli/errors.ts` prints exactly one
 * `tovu: <CODE>: <message>` line on failure. This module reads both and nothing else, so no file
 * under `apps/website/` has to change for the desktop shell to exist.
 */
import net from "node:net";
import path from "node:path";
import { pathToFileURL } from "node:url";
import fs from "node:fs";
import { redactLocalText } from "../../website/src/platform/server-logs/redact-local-text.ts";
import { createRedactedOutputSink } from "../../website/src/platform/server-logs/console-tee.ts";
import { spawn as nodeSpawn, execFileSync } from "node:child_process";
import { randomBytes } from "node:crypto";
import { createRequire } from "node:module";
import { omitEnvironmentKeys } from "@jini-ai/platform/child-environment";
import type { SpawnOptions } from "node:child_process";
import type { Readable, Writable } from "node:stream";
import { redactSecretShapes } from "../../website/src/contracts/core/secret-redaction.ts";

// {@link buildCliSpawnPlan} needs `require.resolve("tsx")`'s CommonJS resolution, which walks up
// from THIS file to `apps/desktop/node_modules/tsx`. `import.meta.resolve` would pick the package's
// `import` condition instead of the `require` one and so could name a different entry file.
const require = createRequire(import.meta.url);

/** `apps/website/src/cli/commands/serve.ts`'s documented startup line (api.spec.md §5). */
const BOOT_LINE = /^tovu serve: dir=(.+) port=(\d+) schemaVersion=(\d+) workspaceId=(\S+)$/m;

/**
 * The optional boot-token line, printed by `tovu serve --emit-boot-token` immediately BEFORE the
 * startup line above (see that file for why the order matters). A single-use, in-memory,
 * loopback-only token this parent can exchange once for an admin session.
 *
 * Deliberately a second pattern rather than a fifth capture group on {@link BOOT_LINE}: that line
 * is a documented contract other readers parse, and it is printed unconditionally, so widening it
 * would put a secret in front of every consumer including an operator's own terminal.
 */
const BOOT_TOKEN_LINE = /^tovu serve: bootToken=(\S+)$/m;

/** Every boot-token line, whole. Used to keep the secret out of anything this module echoes or
 *  puts in an error — see {@link redactBootToken}. */
const BOOT_TOKEN_LINE_GLOBAL = /^tovu serve: bootToken=\S*\r?\n?/gm;

/** The most child output one mirror write or one boot-failure message echoes. */
const MAX_ECHOED_OUTPUT_CHARS = 2_000;

/**
 * `text` with any boot-token line removed and remaining secret values redacted.
 *
 * The token must never reach the parent's own stdout, a log file, or an `Error` message: the E2E
 * suite captures child output, and `describeBootFailure` puts accumulated output straight into a
 * thrown error. Stripped at every egress rather than trusting each call site to remember.
 *
 * @complexity O(n) in the text length.
 */
function redactBootToken(text: string): string {
  return redactLocalText({ text: redactSecretShapes({ text: text.replace(BOOT_TOKEN_LINE_GLOBAL, "") }).text });
}

/**
 * The boot token from accumulated child output, or `null` when none was printed.
 * @complexity O(n) in the text length.
 */
function parseBootToken(text: string): string | null {
  const match = BOOT_TOKEN_LINE.exec(text);
  return match === null ? null : match[1]!;
}

/** `apps/website/src/cli/errors.ts`'s single stderr line — `stderrLine()` builds exactly this shape. */
const CLI_ERROR_LINE = /^tovu: (\S+): (.*)$/m;

/**
 * How long to wait for the boot line before giving up. `bootSiteDir` runs migrations on a cold site
 * dir, which is the slow case; the daemon spawn happens *after* the line is printed and so is not
 * on this clock.
 * Three minutes accommodates cold-dir migrations plus source-mode tsx compilation under machine
 * load, which overran 60s in desktop E2E on 2026-10-16; a slow user machine's first boot would hit
 * the same wall. The child prints nothing before the boot line, so an output-reset idle timer
 * would not help; an exit or spawn error still fails at once, so the longer budget only applies
 * to a child that is still alive.
 */
const DEFAULT_READY_TIMEOUT_MS = 180_000;

/** Grace given to `serve.ts`'s own SIGTERM drain (BR-07) before the process group is force-killed. */
const DEFAULT_STOP_GRACE_MS = 5_000;

/** The fields {@link BOOT_LINE} captures, parsed. */
interface BootLineFields {
  dir: string;
  port: number;
  schemaVersion: number;
  workspaceId: string;
}

/**
 * Parse the startup line out of accumulated stdout.
 *
 * @param text stdout captured so far; partial output is fine, the line is matched with `^…$`.
 * @returns the reported fields, or `null` if the line has not been printed yet.
 * @complexity O(n) in `text` length per call.
 */
function parseBootLine(text: string): BootLineFields | null {
  const match = BOOT_LINE.exec(text);
  if (match === null) return null;
  return { dir: match[1]!, port: Number(match[2]!), schemaVersion: Number(match[3]!), workspaceId: match[4]! };
}

/** The fields {@link CLI_ERROR_LINE} captures, parsed. */
interface CliErrorFields {
  code: string;
  message: string;
}

/**
 * Parse Tovu's single CLI error line, so a failed boot reports Tovu's own diagnosis rather than a
 * bare exit code. `PORT_IN_USE`, `SITE_DIR_INVALID` and `SITE_CORRUPT` all arrive this way.
 *
 * @returns `{ code, message }`, or `null` when the child failed without printing one.
 * @complexity O(n) in `text` length per call.
 */
function parseCliErrorLine(text: string): CliErrorFields | null {
  const match = CLI_ERROR_LINE.exec(text);
  return match === null ? null : { code: match[1]!, message: match[2]! };
}

/** The one field this module reads out of the repo's own `package.json`. */
interface TovuPackageManifest {
  bin?: { tovu?: string };
}

/**
 * Tovu's own `bin.tovu` entry, read from its `package.json` rather than hardcoded.
 *
 * Same "read the manifest, never the literal path" rule Tovu-Runner adopted after Tovu's `src/` was
 * renamed once already (2026-08-27 restructure) and broke a hardcoded `dist/src/cli/main.js` in two
 * places at once. The existence check is here rather than left to `spawn` because the failure is
 * routine — a fresh checkout has no `dist/` — and `ENOENT` on an Electron child is otherwise
 * invisible to whoever has to fix it.
 *
 * @throws {Error} when the manifest has no `bin.tovu`, or the entry it names is not built yet.
 * @complexity O(1).
 */
function resolveCliEntry(repoRoot: string): string {
  const manifestPath = path.join(repoRoot, "package.json");
  const manifest = JSON.parse(fs.readFileSync(manifestPath, "utf8")) as TovuPackageManifest;
  if (typeof manifest.bin?.tovu !== "string") {
    throw new Error(`${manifestPath} has no "bin.tovu" field.`);
  }
  const entry = path.join(repoRoot, manifest.bin.tovu);
  if (!fs.existsSync(entry)) {
    throw new Error(`Tovu's CLI is not built: ${entry} does not exist (from ${manifestPath}'s bin.tovu). Run \`npm run build\` at the repo root first.`);
  }
  return entry;
}

/**
 * The CLI's own TypeScript source, run directly instead of the compiled `dist/` this checkout's
 * `bin.tovu` names — the "source" {@link buildCliSpawnPlan} mode.
 *
 * Exists to close a real bug found 2026-09-05: `dist/` is only ever as fresh as the last manual
 * `npm run build`, and this checkout's own `dist/src/cli/main.js` was last built 2026-08-28 —
 * schema v50 against current source's v57. Own-server mode therefore rejected every site created
 * from current source with `SITE_NEWER_THAN_RUNTIME`, a SECOND, independent reason the app didn't
 * work, on top of nothing being multi-site yet. Rebuilding `dist/` was not an option here: `npm run
 * build` is gated behind `check-no-linked-jini.mjs`, and this checkout deliberately keeps 13
 * `@jini-ai/*` packages symlinked to a local Jini checkout for active development — running the
 * build (or `unlink:jini`) would fight that, not fix this.
 *
 * `development/scripts/dev.mjs` already runs `apps/website/src/index.ts` this same way (`npx tsx
 * watch ...`) for exactly this reason: a dev checkout's compiled output cannot be trusted to match
 * its own source. This function points at the CLI's equivalent entry — `apps/website/src/cli/main.ts`
 * — so `serve`/`init` reach the SAME uncompiled code the running dev server does.
 *
 * @throws {Error} when the TS source itself is missing (a checkout with no `apps/website/src/cli/`
 *   at all, which "packaged" mode would use instead — see {@link buildCliSpawnPlan}).
 * @complexity O(1).
 */
function resolveDevCliEntry(repoRoot: string): string {
  const entry = path.join(repoRoot, "apps", "website", "src", "cli", "main.ts");
  if (!fs.existsSync(entry)) {
    throw new Error(`Tovu's CLI source is missing: ${entry} does not exist.`);
  }
  return entry;
}

/** `buildCliSpawnPlan`'s two supported invocation modes. See that function's own doc. */
export type CliMode = "source" | "compiled";

/** Input to {@link buildCliSpawnPlan}. */
interface CliSpawnPlanInput {
  repoRoot: string;
  cliMode?: CliMode;
  cliArgs: string[];
}

/** The `{ command, args }` {@link buildCliSpawnPlan} builds, ready for `spawn`. */
interface CliSpawnPlan {
  command: string;
  args: string[];
}

/**
 * Build the `{ command, args }` to spawn for one Tovu CLI invocation (`serve` or `init`), in either
 * of two modes:
 *
 * - `"source"` (the default own-server mode uses, via `main.ts`'s `TOVU_DESKTOP_CLI_MODE`) runs
 *   current TypeScript directly under `--import tsx` — see {@link resolveDevCliEntry} for why this
 *   is the mode that actually needs to exist.
 * - `"compiled"` runs the built `dist/` CLI via {@link resolveCliEntry} — this function's OWN
 *   default when no mode is given, unchanged from before `"source"` existed, so every existing
 *   caller and test that never mentions a mode keeps its exact prior behavior.
 *
 * Either way the command is `process.execPath` (Electron's own Node, `ELECTRON_RUN_AS_NODE=1` from
 * {@link buildCliEnv}), never `npx`/a bare `tsx` shebang — running `npx` would hand execution to
 * whatever Node is first on `PATH`, reintroducing exactly the system-Node dependency
 * `buildServeEnv`'s own comment already explains was removed on purpose.
 *
 * `--import` names `require.resolve("tsx")`'s own ABSOLUTE path as a `file:` URL (a bare `C:\` path is
 * read as a URL scheme on Windows: `ERR_UNSUPPORTED_ESM_URL_SCHEME`), not the bare specifier `"tsx"`:
 * Node resolves a bare `--import` specifier relative to the CHILD's own `cwd`, walking up through
 * ITS ancestor `node_modules` directories — which happens to still find this repo's own
 * `node_modules/tsx` for any cwd still inside the repo (confirmed: works from `apps/desktop/`, whose
 * own `node_modules` has no `tsx` of its own), but fails outright once the child's cwd has no such
 * ancestor at all (confirmed: `ERR_MODULE_NOT_FOUND` from a cwd under the OS temp dir) — exactly the
 * scenario a packaged app's `userData` cwd would be. `apps/website`'s own
 * `serve-command.integration.test.ts` already resolves the loader this same way, for this same
 * reason (see its `TSX_LOADER` constant's own comment).
 *
 * Source mode also imports `dev-source-maps-off.mjs` after tsx (`TOVU_DEV_SOURCE_MAPS=1` keeps maps on).
 *
 * Pure — no `spawn()` call — so mode selection is directly assertable without a real checkout or a
 * real child process.
 *
 * @param input.cliArgs the CLI's own argv, e.g. `["serve", siteDir, "--port", "3601"]`.
 * @complexity O(1).
 */
function buildCliSpawnPlan(input: CliSpawnPlanInput): CliSpawnPlan {
  const cliMode = input.cliMode ?? "compiled";
  if (cliMode === "source") {
    const mapsOff = path.join(input.repoRoot, "development", "scripts", "dev-source-maps-off.mjs");
    return { command: process.execPath, args: ["--import", pathToFileURL(require.resolve("tsx")).href,
      "--import", pathToFileURL(mapsOff).href, resolveDevCliEntry(input.repoRoot), ...input.cliArgs] };
  }
  return { command: process.execPath, args: [resolveCliEntry(input.repoRoot), ...input.cliArgs] };
}

/**
 * The part of the child environment every `tovu` subcommand needs — {@link buildServeEnv} layers
 * `serve`-only concerns (daemon token, admin dist) on top, and `tovu init` uses this bare form.
 * Split out so a one-shot `init` does not mint a daemon token it has no daemon for.
 *
 * `TOVU_SITE_DIR` is set here, not only in `buildServeEnv`, because the crash it works around used
 * to be NOT `serve`-specific: `cli/main.ts`'s `createProgram()` statically imports every subcommand
 * module up front (`program.ts` imports both `init.js` and `serve.js` unconditionally), and
 * `serve.js`'s own top-level `import { createApp } from ".../app.js"` used to mean `app.ts`'s
 * MODULE-LOAD-TIME `export const app = createApp();` fired for ANY `tovu` invocation — `init`
 * included — not just when `serve`'s action handler actually ran. Confirmed live, 2026-09-05: `tovu
 * init` run with this shell's own `buildCliEnv` (no `TOVU_SITE_DIR`) from a cwd with no
 * `sites/tovu-dev` crashed the same way `serve` did — same stack (`assistant-byok.ts`'s
 * `resolveToolAttemptAuditSink` → `defaultContentDbPath` → `siteDir()` → `resolveSiteRoot()`'s
 * cwd-relative fallback), before `runInitCommand` ever got a chance to run. That eager export was
 * removed on 2026-09-16 (t91 F4.1), so the crash no longer reproduces from `apps/website` — but the
 * variable stays because every `tovu` subcommand must resolve its site from the directory this shell
 * chose, never from the child's cwd, independent of what triggered this doc originally. Setting it
 * here instead of only in `buildServeEnv` is what keeps "Open Site…"/"Open Recent" onto an EMPTY
 * folder — which calls `initSiteDir`, `buildCliEnv`'s own caller, never `buildServeEnv` — consistent
 * with `buildServeEnv`'s own doc for `serve`. See that doc for the full trace.
 *
 * `TOVU_ADMIN_USER`/`TOVU_ADMIN_PASSWORD` are seeded here too (LAN-bind plan, 2026-09-23, Slice 3),
 * as a PAIR — overwriting any inherited value, the same shape as the `TOVU_HOST` pin in
 * `buildServeEnv` below, not merely defaulted like `TOVU_AGENT_DAEMON_TOKEN`. Without this, a
 * brand-new site's owner is `admin`/`DEFAULT_OWNER_PASSWORD` ("tovu-dev",
 * `apps/website/src/features/identity/wiring.ts`) — a password baked into this repo's own docs and
 * test fixtures, so ANY process on the machine (not just another machine on the LAN) can log in as
 * owner the instant this shell seeds a new site. Set in `buildCliEnv`, not only `buildServeEnv`, so
 * BOTH the `init` spawn (`site-dir-store.ts`'s `initSiteDir`, which calls this function directly)
 * and the `serve` spawn (`buildServeEnv` below, which calls this function first) seed the same
 * random password before `seedIdentity` ever runs — `init` is what actually creates the owner row
 * on a brand-new site dir, so seeding only in `buildServeEnv` would have missed the one call site
 * that matters most. Never printed, logged, or written to disk anywhere in this file. Inert on a
 * site that has already been seeded, because `seedIdentity` seeds exactly once, idempotently — this
 * only changes what a genuinely NEW site's first owner credential is.
 *
 * @param input.siteDir the site dir the child will operate on (`init`'s target dir, or `serve`'s), set
 *   into `TOVU_SITE_DIR`, replacing any inherited site selection. Optional so a caller with no
 *   specific site in mind (none exists today) still gets a valid env.
 * @complexity O(n) in the number of inherited environment variables, plus one `randomBytes` call.
 */
function buildCliEnv({ baseEnv, siteDir }: { baseEnv?: NodeJS.ProcessEnv; siteDir?: string },
  { warn = console.warn }: { warn?: (message: string) => void } = {},
): NodeJS.ProcessEnv {
  // Desktop launches many sites: a relocation exported for one CLI run must not become shared state.
  const isolated = omitEnvironmentKeys({ env: baseEnv ?? process.env,
    keys: ["TOVU_PLUGINS_DIR", "TOVU_SKILLS_DIR", "TOVU_AGENT_PLUGINS_DIR",
      // Each site gets a fresh native-render capability from its launcher, never an inherited one.
      "JINI_DESKTOP_RENDER_URL", "JINI_DESKTOP_RENDER_TOKEN",
      ...(siteDir ? ["TOVU_SITE_DIR", "TOVU_AGENT_CWD"] : [])],
  }, { caseInsensitive: process.platform === "win32" });
  const env = isolated.env;
  if (isolated.omitted.length) {
    warn(`tovu desktop: dropped inherited ${isolated.omitted.join(", ")}; spawned sites use their own plugin and skill folders. Set overrides only for a direct single-site run.`);
  }

  env.ELECTRON_RUN_AS_NODE = "1";

  if (siteDir) {
    env.TOVU_SITE_DIR = siteDir;
  }

  delete env.PORT;
  delete env.TOVU_CHAT_DB;
  delete env.TOVU_CONTENT_DB;
  delete env.TOVU_DB;

  // LAN-bind plan (2026-09-23), Slice 3 — see this function's own doc above. Overwritten as a PAIR:
  // an inherited half of either variable (this machine's own shell exports `TOVU_ADMIN_PASSWORD`
  // ambiently — see `buildServeEnv`'s own `desktopCredential` comment on the identical trap) must
  // never combine with the other half to seed an account nobody can log into.
  env.TOVU_ADMIN_USER = "admin";
  env.TOVU_ADMIN_PASSWORD = randomBytes(32).toString("hex");

  return env;
}

/** The desktop shell's own owner account, seeded into a brand-new site — see {@link buildServeEnv}. */
interface DesktopCredential {
  username: string;
  password: string;
}

/** Input to {@link buildServeEnv}. */
interface BuildServeEnvInput {
  productTelemetry?: { configPath: string; preferencePath: string; release: string };
  repoRoot: string;
  siteDir?: string;
  baseEnv?: NodeJS.ProcessEnv;
  desktopCredential?: DesktopCredential;
  adminDevProxyUrl?: string | null;
  /** The two-key env contract `node-toolchain.ts`'s `buildNodeToolchainEnv` returns
   *  (`TOVU_NODE_TOOLCHAIN_DIR`, `TOVU_BUNDLED_NPM_ROOT`), read by the website's
   *  `stdioLaunchResolverFromEnv` (plan `plan-desktop-bundled-npx-2026-09-24.md` §2). `main.ts` is
   *  the only real caller; every other caller and every existing test omits it, which is what MUST
   *  delete rather than merely leave unmerged any inherited value of either key — see this
   *  function's own doc below. */
  nodeToolchainEnv?: Record<string, string>;
}

/**
 * Build the child's environment for `tovu serve`.
 *
 * Five deliberate decisions, each of which was a real defect somewhere before it was a line here:
 *
 * - **`ELECTRON_RUN_AS_NODE` is SET, not deleted.** The child command is `process.execPath` — the
 *   Electron binary — run as Node, so this variable is what makes it a Node process at all. Tovu-
 *   Runner deletes it instead, because Runner hunts down a *system* Node (`resolveNodeBinary()`,
 *   ~90 lines probing Homebrew/Volta/nvm/fnm/asdf/n) on the belief that Tovu's `better-sqlite3` is
 *   an ABI-locked node-gyp build. That is no longer true: `better-sqlite3` 13 is N-API with
 *   `prebuilds/`, and it, `argon2` and `sharp` all load unmodified under Electron 43 (measured
 *   2026-09-05, incl. a real SQLite roundtrip). Running the child on Electron's own Node is what
 *   lets this shell drop the probe entirely and stop depending on a Node install it does not ship.
 *   `daemon-supervisor.ts` spawns the agent daemon with `process.execPath` too and inherits this
 *   variable through `{...process.env}`, so the daemon comes up the same way.
 *
 * - **`TOVU_AGENT_DAEMON_TOKEN` is minted here.** `apps/website/src/index.ts` calls
 *   `ensureAgentDaemonToken()` as the first statement of `main()`; `cli/commands/serve.ts` does
 *   NOT (verified — no `cli/` file references it). `daemon-auth.ts` is fail-closed by design: an
 *   unset token makes the daemon answer **503**, so without this line the assistant is dead in
 *   own-server mode with no error anywhere that names the cause. An operator-set value wins, since
 *   someone who exported a token to reach the daemon from outside must not have it replaced.
 *
 * - **`TOVU_ADMIN_DIST` and `TOVU_SITE_CHAT_DIST` are set when their builds exist.** `app.ts`
 *   resolves BOTH from `import.meta.dirname` six levels up when unset (`:1316` and `:1340`), which
 *   lands on the repo root from `src/` but *overshoots it* from `dist/` — and own-server mode runs
 *   the compiled `dist/` CLI, so `/admin` and `/site-chat` both answer 503 without these. Tovu's
 *   own documented overrides, set from outside, so `apps/website/` needs no change; the underlying
 *   off-by-one is reported separately rather than fixed from here. `Dockerfile:170-171` sets the
 *   same PAIR for the same reason — this shell set only the admin half until 2026-09-11, which is
 *   why site-chat 503'd in every compiled-mode desktop run.
 *
 * - **`TOVU_SITE_DIR` is pinned to the requested site, replacing inherited selections.** Confirmed live, 2026-09-05:
 *   `apps/website/src/server/runtime/composition/app.ts` used to have a MODULE-LOAD-TIME side
 *   effect — `export const app = createApp();`, evaluated the instant `cli/main.ts`'s static import
 *   chain reached that file, before `cli/commands/serve.ts`'s own `runServeCommand()` body ever ran
 *   — and that default `createApp()` call composed `assistant-byok.ts`'s audit sink unconditionally
 *   (`resolveToolAttemptAuditSink` → `defaultContentDbPath` → `siteDir()` → `resolveSiteRoot()`),
 *   which fell back to `<cwd>/sites/tovu-dev` whenever `TOVU_SITE_DIR` was unset. Own-server mode's
 *   cwd is whatever launched Electron, not the repo root, so that fallback directory did not exist
 *   and the child crashed at import time with "Cannot open database because the directory does not
 *   exist" — before printing a boot line, before `runServeCommand` got a chance to do anything. That
 *   eager export was removed on 2026-09-16 (t91 F4.1), so this exact crash no longer reproduces from
 *   `apps/website` — the variable stays regardless: every `tovu` subcommand must resolve its site
 *   from the directory this shell chose, never from the child's cwd, which is a standing requirement
 *   independent of what triggered this doc originally. The actual fix lived in {@link buildCliEnv}
 *   (this function's own base), not here, because the same crash was reachable through `init` too —
 *   see that function's own doc. This is a real, pre-existing "systemic gap" in `apps/website`
 *   itself, unrelated to the eager-export crash above (two of its own certified integration tests —
 *   the foreign-cwd `CR-R04/CR-R01` test and the `BR-07`/`BR-04` test — already failed at HEAD for
 *   exactly this reason as of 2026-09-05, confirmed independent of any change made here), reported
 *   rather than fixed structurally: setting it in the child's own env only ever helped
 *   `apps/desktop`'s OWN spawned children, since it lives in the env this shell controls, not in the
 *   CLI's own spawn path those two tests exercise directly.
 *
 * - **`TOVU_REPO_ROOT` is set unless the operator already pinned one.** Same shape of gap as
 *   `TOVU_SITE_DIR` above, one layer over in `features/publish-trust`: `findCandidateDestination`
 *   and the provisioning port behind the Publish dialog's Connect button resolve the repo-relative
 *   committed config they read and write (`.github/workflows/fly-deploy.yml`, `deploy/publish-trust.json`) against
 *   `process.cwd()` when this is unset (`resolveCommittedConfigRoot()`'s own doc) — correct for a
 *   plain `tovu serve` and for the deployed container (`Dockerfile`'s `WORKDIR` IS the repo root),
 *   wrong for own-server mode. Confirmed live 2026-09-19: with this unset, the dialog reported "no
 *   live site" for a site that had already been deployed, because the scan looked for
 *   `apps/desktop/fly.toml` instead of the then-committed repo-root config.
 *
 * `PORT`, `TOVU_CHAT_DB`, `TOVU_CONTENT_DB` and `TOVU_DB` are dropped so an exported shell
 * variable cannot silently repoint the desktop app's database or port — this shell's `--port` and
 * `<dir>` are the only authority over those. `TOVU_HOST` is overwritten to `127.0.0.1` for the
 * same reason — see the LAN-bind plan note above the identity-seeding paragraph.
 * `TOVU_PUBLIC_URL` is dropped because desktop development loads the repo-root
 * `.env`: its public origin belongs to that site, not each spawned site's loopback server.
 * `TOVU_SITE_KEY` and the rest of the inherited environment remain available.
 * `TOVU_ADMIN_USER`/
 * `TOVU_ADMIN_PASSWORD` are ALREADY a random, never-shown pair by the time this function runs —
 * {@link buildCliEnv} above seeds them unconditionally — so a caller that passes no
 * `desktopCredential` (every existing caller before this dispatch) no longer leaves a brand-new
 * site on the default `admin`/`tovu-dev` password; a caller that DOES pass one still overrides that
 * pair below, unchanged.
 *
 * @param input.repoRoot repo root, used to locate `apps/admin/dist` and threaded into
 *   `TOVU_REPO_ROOT` for `features/publish-trust`'s committed-config resolution.
 * @param input.siteDir the site dir this server will boot — threaded into `TOVU_SITE_DIR` via
 *   {@link buildCliEnv} so every code path in the child that resolves its own site independently of
 *   the CLI's `<dir>` argument still agrees with it.
 * @param input.baseEnv environment to layer onto (defaults to `process.env`).
 * @complexity O(n) in the number of inherited environment variables.
 */
function buildServeEnv(input: BuildServeEnvInput, { warn = console.warn }: { warn?: (message: string) => void } = {}): NodeJS.ProcessEnv {
  const repoRoot = input.repoRoot;
  const env = buildCliEnv({ baseEnv: input.baseEnv, siteDir: input.siteDir }, { warn });
  // Only main's successfully booted config authorizes child telemetry; inherited values cannot.
  delete env.TOVU_PRODUCT_TELEMETRY_CONFIG;
  delete env.TOVU_PRODUCT_TELEMETRY_PREFS;
  delete env.TOVU_PRODUCT_RELEASE;
  if (input.productTelemetry) {
    env.TOVU_PRODUCT_TELEMETRY_CONFIG = input.productTelemetry.configPath;
    env.TOVU_PRODUCT_TELEMETRY_PREFS = input.productTelemetry.preferencePath;
    env.TOVU_PRODUCT_RELEASE = input.productTelemetry.release;
  }
  delete env.TOVU_PUBLIC_URL;
  // Ownership comes from the host that registers this connection, never from its display name.
  env.TOVU_BUILT_IN_MCP_SERVER_IDS = JSON.stringify([SITES_MCP_SERVER_ID]);

  if (!env.TOVU_AGENT_DAEMON_TOKEN) {
    env.TOVU_AGENT_DAEMON_TOKEN = randomBytes(32).toString("hex");
  }

  // LAN-bind plan (2026-09-23). Overwritten on purpose, like the PORT drop in `buildCliEnv` above —
  // NOT merely defaulted like TOVU_AGENT_DAEMON_TOKEN above, whose inherited value wins. Every
  // client of this child dials 127.0.0.1 literally (this file's own connect calls, `main.ts`, the
  // integration tests), so a developer's shell export (or `--port`-style operator intent) must never
  // put a desktop-spawned site on the LAN — this is what keeps it off, unconditionally. The literal
  // string, not an import of `bind-host.ts`'s `DEFAULT_LOCAL_BIND_HOST`: this directory stays
  // self-contained from `apps/website`, same reasoning as `desktop-auth.ts:62-65`.
  env.TOVU_HOST = "127.0.0.1";
  // The local desktop is the trusted launcher. A fresh private capability arms owner re-entry
  // for this server lifetime, independently of development mode and the one-use boot token.
  env.TOVU_DESKTOP_OWNER_SIGNIN = randomBytes(32).toString("hex");
  env.TOVU_DESKTOP_OWNER_PID = String(process.pid);

  // Seeds the desktop shell's OWN owner account so `desktop-auth.ts` can log in and the operator
  // never meets a login form for a server this app started. Omitted entirely when the caller passes
  // no credential (every existing caller and every existing test), so the child's identity seeding
  // is byte-for-byte unchanged in that case.
  //
  // **Both variables are OVERWRITTEN, deliberately — an inherited value does NOT win here**, unlike
  // `TOVU_AGENT_DAEMON_TOKEN` above. Copying that rule to this pair was a bug, found by running it:
  // this machine has `TOVU_ADMIN_PASSWORD` exported in the ambient shell (a known trap in this
  // repo's own test tooling) and `TOVU_ADMIN_USER` unset, so honoring the inherited half seeded
  // `admin` with an unrelated password while the shell went on to log in as `tovu-desktop` — an
  // account that then never existed. The two are a PAIR and half of one operator's intent combined
  // with half of the shell's is guaranteed-broken rather than conservative.
  //
  // Overwriting costs the operator nothing they can otherwise have: `seedIdentity` seeds exactly
  // ONE owner per boot, the one its configured username names, so `admin` and `tovu-desktop` were
  // never both reachable from a single spawn. It is also a no-op on any site that has been booted
  // before, since seeding is idempotent. What it changes is a BRAND-NEW site opened through this
  // shell: its first owner is `tovu-desktop` rather than `admin`. That is the intended trade — the
  // operator arrives authenticated as a real owner and can create any further account from the
  // admin UI, instead of the site being seeded with a password the shell cannot know.
  if (input.desktopCredential) {
    env.TOVU_ADMIN_USER = input.desktopCredential.username;
    env.TOVU_ADMIN_PASSWORD = input.desktopCredential.password;
  }

  // **`TOVU_AGENT_CWD` is pinned to the site dir.** The agent daemon `tovu serve` spawns runs every
  // assistant turn in `process.env.TOVU_AGENT_CWD ?? process.cwd()`
  // (`apps/website/src/server/inbound/assistant/agent-daemon-server.ts`), and a macOS app launched
  // from Finder/dock has cwd `/`. `tovu serve` inherits that, the daemon inherits it from
  // `tovu serve`, so before this line every turn in the packaged app died before spawn with
  // `EROFS: read-only file system, open '/.mcp.jini-<runId>.json'` — the daemon writes a per-run
  // `.mcp.json` into the agent's cwd, and `/` is not writable. The run finished `failed` with
  // `code=null, signal=null` ~13ms after starting, which reaches the pane as an `end` frame carrying
  // no message, so the operator saw their own turn render and then nothing at all, three times over.
  // Measured live 2026-09-12: the running daemon's cwd was `/` (`lsof -a -p <pid> -d cwd`), and the
  // same packaged daemon binary re-launched from a writable cwd streamed a reply.
  //
  // The SITE dir rather than merely some writable dir, and that is the substantive choice here: it
  // is the active site's own tree (`content.db`, `uploads/`, `themes/`, `skills/`,
  // `agent-plugins/`), so "which site am I working on" is answered by the agent's own working
  // directory. `AssistantDock.tsx` already names this variable as the only thing that can really
  // move the agent — a browser directory picker yields a folder name and never a path — and says the
  // feature belongs to the Electron shell, which is this line.
  //
  // Set through the child's env rather than `spawn`'s own `cwd` option on purpose: several code
  // paths in the child resolve their site from `process.cwd()` when `TOVU_SITE_DIR` is absent (see
  // {@link buildCliEnv}), so moving the real cwd would change more than the agent's working
  // directory. It also keeps the server side free of any knowledge that a desktop shell exists —
  // this is a variable `agent-daemon-server.ts` already reads for its own reasons, not a new hook.
  // Pin to this launch's site: inherited working directories can put the agent in another site's tree.
  if (input.siteDir) {
    env.TOVU_AGENT_CWD = input.siteDir;
  }

  applyRepoRootDefaults(env, repoRoot);

  // Set LAST and only when the caller resolved a live dev server (`admin-dev-proxy.ts` probes; a
  // packaged app yields no candidate at all). `admin-static.ts`'s precedence makes this override
  // `TOVU_ADMIN_DIST` above rather than sit beside it — the dev-proxy branch returns before the
  // static branch is reached — which is exactly the point: the built bundle is what goes stale.
  // Omitted by every caller that passes nothing, so the child env is unchanged for them.
  if (typeof input.adminDevProxyUrl === "string" && input.adminDevProxyUrl !== "") {
    env.TOVU_ADMIN_DEV_PROXY_URL = input.adminDevProxyUrl;
  }

  // Node-toolchain plan (2026-09-24), S4. Unlike every other pair in this function, an inherited
  // value is DELETED rather than left alone when the caller passes nothing — `main.ts` is the only
  // real caller of `nodeToolchainEnv`, and every other caller (every existing test, and any future
  // one that does not opt in) must reach the child with neither key present, even on a developer
  // machine whose shell still exports a stale pair from a previous checkout. A stale
  // `TOVU_NODE_TOOLCHAIN_DIR` pointing at a deleted `userData` would make the resolver hand back
  // paths under a toolchain that no longer exists, rather than the safe identity fallback.
  delete env.TOVU_NODE_TOOLCHAIN_DIR;
  delete env.TOVU_BUNDLED_NPM_ROOT;
  if (input.nodeToolchainEnv) {
    Object.assign(env, input.nodeToolchainEnv);
  }

  return env;
}

/**
 * The repo-root-derived defaults {@link buildServeEnv} layers onto the child env: the built admin
 * and site-chat bundles (only when they exist on disk) and `TOVU_REPO_ROOT` itself. Every one of
 * them yields to a value the operator already set. Split out of `buildServeEnv` only to keep that
 * function under the complexity ceiling; the rules are unchanged.
 *
 * @param env the env being built, mutated in place.
 * @param repoRoot the repo root the defaults are resolved against.
 * @complexity O(1); two `existsSync` probes.
 */
function applyRepoRootDefaults(env: NodeJS.ProcessEnv, repoRoot: string): void {
  const adminDist = path.join(repoRoot, "apps", "admin", "dist");
  if (!env.TOVU_ADMIN_DIST && fs.existsSync(adminDist)) {
    env.TOVU_ADMIN_DIST = adminDist;
  }

  const siteChatDist = path.join(repoRoot, "apps", "site-chat", "dist");
  if (!env.TOVU_SITE_CHAT_DIST && fs.existsSync(siteChatDist)) {
    env.TOVU_SITE_CHAT_DIST = siteChatDist;
  }

  // **`TOVU_REPO_ROOT` is set unless the operator already pinned one.** Same class of gap as
  // `TOVU_SITE_DIR` above, one layer over in `features/publish-trust`: `findCandidateDestination`
  // and the provisioning port that backs the Publish dialog's Connect button resolve their
  // repo-relative committed config (`.github/workflows/fly-deploy.yml`, `deploy/publish-trust.json`) against
  // `process.cwd()` when this is unset (`resolveCommittedConfigRoot()`'s own doc) — correct for a
  // plain `tovu serve` run from the repo root and for the deployed container, wrong for own-server
  // mode, whose cwd is wherever opened Electron. Confirmed live 2026-09-19: with this unset, the
  // dialog reported "no live site" for a site that HAD been deployed, because the scan looked for
  // `apps/desktop/fly.toml` instead of the then-committed repo-root config.
  if (!env.TOVU_REPO_ROOT) {
    env.TOVU_REPO_ROOT = repoRoot;
  }
}

/**
 * Ask the OS for a free loopback port by binding to `:0` and releasing it.
 *
 * Inherently a hint rather than a reservation — the port is free when it is reported and could be
 * taken before `tovu serve` binds it. That race is why the caller still surfaces Tovu's own
 * `PORT_IN_USE` line: this narrows the window, `serve.ts` closes it.
 *
 * @complexity O(1); one bind/close round trip.
 */
function allocatePort(): Promise<number> {
  return new Promise((resolve, reject) => {
    const server = net.createServer();
    server.once("error", reject);
    server.listen(0, "127.0.0.1", () => {
      const { port } = server.address() as net.AddressInfo;
      server.close(() => resolve(port));
    });
  });
}

/**
 * The subset of Node's `ChildProcess` surface this module touches. Kept narrow, rather than
 * importing `ChildProcess` itself, so `spawnFn`'s test double (`fakeChild()` in the test file) only
 * has to implement the fields `startTovuServer` actually reads — a real `ChildProcess` satisfies
 * this structurally, so `nodeSpawn` needs no cast.
 */
interface SpawnedChild {
  pid?: number;
  stdin?: Writable | null;
  stdout: Readable | null;
  stderr: Readable | null;
  exitCode: number | null;
  signalCode: NodeJS.Signals | null;
  kill(signal?: NodeJS.Signals | number): boolean;
  once(event: "exit", listener: (code: number | null, signal: NodeJS.Signals | null) => void): this;
  once(event: "error", listener: (error: Error) => void): this;
  removeListener(event: "exit", listener: (code: number | null, signal: NodeJS.Signals | null) => void): this;
}

/**
 * Default win32 tree-kill escalation: `taskkill /pid <pid> /T /F`.
 *
 * Windows has no process groups — the `detached: true` spawn binds no group there the way it does
 * on POSIX, so {@link stopChild}'s POSIX `process.kill(-pid, "SIGKILL")` escalation has nothing to
 * target and would only ever reach the immediate `tovu serve` process, orphaning its agent-daemon
 * grandchild exactly the way plan item W7 describes. `/T` walks the whole tree taskkill itself
 * spawned, the same intent as the negative-pid signal on POSIX; `/F` forces it, matching SIGKILL.
 *
 * @param pid the child's own pid (never negated — there is no process-group id to negate on win32).
 * @complexity O(1); delegates to the OS via a synchronous child process.
 */
function taskkillTree(pid: number): void {
  execFileSync("taskkill", ["/pid", String(pid), "/T", "/F"], { stdio: "ignore" });
}

/**
 * Terminate a spawned `tovu serve` and everything it spawned, then resolve once it is really gone.
 *
 * SIGTERM goes to the child itself, because `serve.ts` handles it with a real graceful drain
 * (BR-07: stop accepting, finish in-flight, `shutdownAssistantDaemon()`, close the sqlite handle) —
 * that path also reaps the agent daemon, so the polite signal is the *complete* one. SIGKILL is the
 * escalation, and it goes to the process **group** (`-pid`, which the `detached: true` spawn makes
 * available) on POSIX: a `tovu serve` wedged badly enough to ignore SIGTERM has not run its own
 * shutdown, so its daemon child is exactly what would be left behind. On win32 there is neither a
 * process group nor a polite signal: a child spawned with a stdin pipe (the real one) is asked to stop by
 * closing that pipe (`serve.ts` runs the same drain on its end) and tree-killed after the grace;
 * without one the injected `killTree(pid)` (production default: {@link taskkillTree}) runs
 * IMMEDIATELY instead of SIGTERM — see {@link killWin32Tree} for why it cannot wait for the grace.
 *
 * @param input the spawned child and graceful/forced-exit wait bound in milliseconds.
 * @param options.platform selects the escalation primitive; defaults to the real `process.platform`. Test
 *   seam so the win32 branch is exercised on any host.
 * @param options.killTree win32-only tree-kill, defaulting to {@link taskkillTree}. Never called on POSIX.
 * @throws {Error} if no exit event arrives within another `graceMs` after escalation. The caller
 *   must retain its crash-recovery row: requesting SIGKILL does not prove the process has exited.
 * @complexity O(1) time/space; waits at most twice `graceMs`.
 */
function stopChild(
  { child, graceMs }: { child: SpawnedChild; graceMs: number },
  { platform = process.platform, killTree = taskkillTree }: {
    platform?: NodeJS.Platform; killTree?: (pid: number) => void;
  } = {},
): Promise<void> {
  if (child.exitCode !== null || child.signalCode !== null) return Promise.resolve();

  return new Promise((resolve, reject) => {
    let exitTimer: ReturnType<typeof setTimeout> | undefined;
    let signalError: unknown;
    const timer = setTimeout(() => {
      // Keep listening after the kill request; the OS may deliver exit later. Bound that wait
      // separately so a failed signal or missing exit is reported instead of claiming success.
      exitTimer = setTimeout(() => {
        child.removeListener("exit", onExit);
        reject(new Error(`tovu serve (pid ${child.pid}) did not exit within ${graceMs}ms after forced Stop.`, { cause: signalError }));
      }, graceMs);
      try {
        if (platform === "win32") {
          if (child.stdin) killWin32Tree(child, killTree);
        } else {
          // `!`: `stopChild` only runs on an already-spawned child, so it has a pid.
          process.kill(-child.pid!, "SIGKILL");
        }
      } catch (error) {
        // Even ESRCH is not the exit event. Await it, or report the failure at the bound.
        signalError = error;
      }
    }, graceMs);

    const onExit = () => {
      clearTimeout(timer);
      clearTimeout(exitTimer);
      resolve();
    };
    child.once("exit", onExit);

    try {
      if (platform === "win32") {
        // EPIPE when the child exits first must not become an unhandled stream error.
        if (child.stdin) child.stdin.once("error", () => undefined).end();
        else killWin32Tree(child, killTree);
      } else {
        child.kill("SIGTERM");
      }
    } catch (error) {
      // A failed polite signal still needs escalation and exit confirmation.
      signalError = error;
    }
  });
}

/**
 * {@link stopChild}'s win32 stop, run FIRST rather than as an escalation. Node on Windows ignores
 * the signal name in `child.kill(...)` and terminates the direct child at once, so sending that
 * first would fire `exit`, clear the escalation timer, and leave the agent-daemon grandchild
 * orphaned (plan item W7). There is no graceful signal a console child can receive on win32, so
 * without a stdin pipe to close the forced tree kill is the whole stop; SQLite's journal is what
 * makes that safe. A failing
 * `taskkill` (missing binary, pid already gone) falls back to the direct-child kill.
 *
 * @complexity O(1); delegates to the OS.
 */
function killWin32Tree(child: SpawnedChild, killTree: (pid: number) => void): void {
  try {
    // `!`: `stopChild` only runs on an already-spawned child, so it has a pid.
    killTree(child.pid!);
  } catch {
    child.kill("SIGTERM");
  }
}

/** Compose the most useful failure message available: Tovu's own error line, else the raw tail.
 *  `output` is the whole (redacted) text: Tovu prints its error line last, so only the fallback
 *  tail is capped (from its start, where a native fatal error names itself), never the text
 *  searched for that line. */
function describeBootFailure(output: string, fallback: string): string {
  const cliError = parseCliErrorLine(output);
  if (cliError !== null) return `tovu serve failed: ${cliError.code}: ${cliError.message}`;
  const tail = output.trim().split("\n").slice(-5).join("\n").slice(0, MAX_ECHOED_OUTPUT_CHARS);
  return tail.length > 0 ? `${fallback}\n${tail}` : fallback;
}

/** One child exit, as {@link createExitSignal} replays it. */
interface ExitOutcome {
  code: number | null;
  signal: NodeJS.Signals | null;
}

/** What {@link createExitSignal} returns. */
interface ExitSignal {
  onExit(listener: (exit: ExitOutcome) => void): void;
}

/**
 * A one-shot, replayable exit signal for a spawned child.
 *
 * The gap this closes (D-06): the only `exit` listener {@link startTovuServer} had fed its
 * single-settle `finish()`, which is a NO-OP once the boot line has already resolved the promise.
 * So nothing in this process observed a child dying AFTER it came up — `main.ts`'s `openSites`
 * kept the dead handle, `buildSiteRecord` kept reporting `running`, and "Start site" handed the
 * corpse straight back instead of spawning a replacement.
 *
 * REPLAYING rather than just forwarding is the load-bearing part. A supervisor attaches its
 * listener after `startTovuServer` resolves, and a child is free to die inside that gap; a plain
 * `child.once("exit", listener)` registered then would never fire, and the entry would be wedged
 * "running" for the whole session — the very state this exists to prevent. Registering the capture
 * here, immediately after `spawn` and before any `await`, means there is no instant at which an
 * exit can go unrecorded.
 *
 * @returns `{ onExit }` — `onExit(listener)` calls `listener({code, signal})` when the child exits,
 *   or immediately if it already has. Listeners fire once each and are then dropped.
 * @complexity O(1) per registration; O(n) in registered listeners at exit time.
 */
function createExitSignal(child: SpawnedChild): ExitSignal {
  let exit: ExitOutcome | null = null;
  const waiting: Array<(exit: ExitOutcome) => void> = [];

  child.once("exit", (code, signal) => {
    exit = { code, signal };
    for (const listener of waiting.splice(0)) listener(exit);
  });

  return {
    onExit(listener) {
      if (exit !== null) {
        listener(exit);
        return;
      }
      waiting.push(listener);
    },
  };
}

/** Injectable `child_process.spawn` — the test seam. See {@link SpawnedChild}. */
type SpawnFn = (command: string, args: string[], options: SpawnOptions) => SpawnedChild;

/** Where a spawned child's output is echoed — defaults to this process's own streams. */
interface MirrorStreams {
  stdout: Writable;
  stderr: Writable;
}

/** Input to {@link startTovuServer}. */
interface StartTovuServerInput {
  productTelemetry?: BuildServeEnvInput['productTelemetry'];
  repoRoot: string;
  siteDir: string;
  port?: number;
  spawnFn?: SpawnFn;
  readyTimeoutMs?: number;
  stopGraceMs?: number;
  mirror?: MirrorStreams;
  desktopCredential?: DesktopCredential;
  cliMode?: CliMode;
  adminDevProxyUrl?: string | null;
  baseEnv?: NodeJS.ProcessEnv;
  /** Forwarded to {@link buildServeEnv}'s own field of the same name; see its doc there. Omitted by
   *  every existing caller and every existing test. */
  nodeToolchainEnv?: Record<string, string>;
  emitBootToken?: boolean;
  /** Test seam: injects the OS platform {@link stopChild} branches its kill escalation on. Defaults
   *  to the real `process.platform`; production never passes this. */
  platform?: NodeJS.Platform;
  /** Test seam: win32-only tree-kill passed through to {@link stopChild}. Defaults to `taskkill /pid
   *  <pid> /T /F`; production never passes this. */
  killTree?: (pid: number) => void;
}

/** What a resolved {@link startTovuServer} call hands back. */
interface TovuServerHandle {
  external?: boolean;
  port: number;
  pid: number;
  origin: string;
  adminUrl: string;
  workspaceId: string;
  schemaVersion: number;
  bootToken: string | null;
  /** Main-process-only launch proof; never serialize into SiteRecord or renderer IPC. */
  ownerSignInCapability?: string;
  /** Resolve only after confirmed exit; reject if escalation's bounded exit wait expires. */
  stop(): Promise<void>;
  onExit: ExitSignal["onExit"];
}

/**
 * Spawn `tovu serve <siteDir> --port <port>` and resolve once it reports the port it bound.
 *
 * Resolves to a handle whose `stop()` is the only supported way to shut the server down. Rejects
 * after shutdown if the boot line does not arrive before `readyTimeoutMs`, or if the child exits
 * first, in which case Tovu's own `tovu: <CODE>: <message>` line is reported. Unconfirmed cleanup
 * instead reports its bounded exit-wait failure.
 *
 * @param input.repoRoot Tovu repo root; `bin.tovu` and `apps/admin/dist` are resolved from it.
 * @param input.siteDir the site directory to serve — owns `content.db`, `uploads/` and `themes/`.
 * @param input.port port to bind; allocated from the OS when omitted.
 * @param input.spawnFn injectable `child_process.spawn` (test seam).
 * @param input.readyTimeoutMs boot-line deadline; defaults to 180s.
 * @param input.stopGraceMs SIGTERM-to-SIGKILL window and subsequent exit-event wait; each defaults to 5s.
 * @param input.mirror where the child's output is echoed; defaults to this process's own streams.
 * @param input.desktopCredential `{username, password}` seeding the shell's own owner account, so
 *   the admin comes up authenticated (see `desktop-auth.ts`). Omit to leave the child's identity
 *   seeding exactly as it was.
 * @param input.cliMode `"source"` or `"compiled"` — see {@link buildCliSpawnPlan}; defaults to
 *   `"compiled"` when omitted (unchanged prior behavior for any existing caller).
 * @param input.adminDevProxyUrl a live admin Vite dev-server origin, which makes this site serve
 *   `/admin/*` from current source instead of the built `apps/admin/dist`. Resolve it with
 *   `admin-dev-proxy.ts`'s `resolveAdminDevProxyUrl` — which probes, and yields nothing when
 *   packaged — rather than passing a bare URL, since an unreachable origin turns `/admin/` into a
 *   502 rather than falling back. Omit to serve the built bundle exactly as before.
 * @param input.platform test seam forwarded to {@link stopChild}; defaults to `process.platform`.
 * @param input.killTree win32-only test seam forwarded to {@link stopChild}; defaults to
 *   {@link taskkillTree}.
 * @param input.nodeToolchainEnv forwarded to {@link buildServeEnv}'s field of the same name — the
 *   bundled node/npm toolchain's env contract. Omit to leave the child's env exactly as before.
 * @returns `{ port, pid, origin, adminUrl, workspaceId, schemaVersion, stop(), onExit(cb) }` —
 *   `onExit` is the post-ready liveness signal a supervisor needs; see {@link createExitSignal}.
 * @throws {Error} when the CLI is unbuilt/missing, the boot line times out, or the child exits early.
 * @complexity O(1) plus `bootSiteDir`'s own cost inside the child.
 */
async function startTovuServer(input: StartTovuServerInput): Promise<TovuServerHandle> {
  const spawnFn: SpawnFn = input.spawnFn ?? nodeSpawn;
  const readyTimeoutMs = input.readyTimeoutMs ?? DEFAULT_READY_TIMEOUT_MS;
  const stopGraceMs = input.stopGraceMs ?? DEFAULT_STOP_GRACE_MS;
  const port = input.port ?? (await allocatePort());
  const plan = buildCliSpawnPlan({
    repoRoot: input.repoRoot,
    cliMode: input.cliMode,
    cliArgs: [
      "serve",
      input.siteDir,
      "--port",
      String(port),
      // Opt-in per call. Omitted entirely by every existing caller and every existing test, so a
      // server booted without it mints nothing and its redemption route stays permanently closed.
      ...(input.emitBootToken === true ? ["--emit-boot-token"] : []),
    ],
  });

  const serveEnv = buildServeEnv({ repoRoot: input.repoRoot, siteDir: input.siteDir, baseEnv: input.baseEnv, desktopCredential: input.desktopCredential, adminDevProxyUrl: input.adminDevProxyUrl, nodeToolchainEnv: input.nodeToolchainEnv, productTelemetry: input.productTelemetry });
  // Windows has no SIGTERM to send: Stop closes this stdin pipe instead (see `stopChild`).
  const win32 = (input.platform ?? process.platform) === "win32";
  const child = spawnFn(
    plan.command,
    plan.args,
    {
      env: win32 ? { ...serveEnv, TOVU_STOP_ON_STDIN_EOF: "1" } : serveEnv,
      stdio: [win32 ? "pipe" : "ignore", "pipe", "pipe"],
      // Own process group, so `stopChild`'s SIGKILL escalation can reap the agent daemon
      // `tovu serve` spawns rather than just the immediate child. Same reason
      // `development/scripts/dev.mjs` and `daemon-supervisor.ts` both detach.
      detached: true,
      // Windows pops a console window for every detached child otherwise (plan item W6) — inert on
      // POSIX, where a hidden console window does not exist to suppress.
      windowsHide: true,
    },
  );

  const exitSignal = createExitSignal(child);

  return await new Promise<TovuServerHandle>((resolve, reject) => {
    let output = "";
    let settled = false;

    const timer = setTimeout(() => {
      finish(() => reject(new Error(describeBootFailure(redactBootToken(output), `tovu serve did not report a port within ${readyTimeoutMs}ms.`))));
    }, readyTimeoutMs);

    /** Single-settle guard: whichever of ready / timeout / exit happens first owns the outcome. */
    function finish(settleWith: () => void): void {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      settleWith();
    }

    function readStream(stream: Readable, mirror: Writable): void {
      stream.setEncoding("utf8");
      const safeMirror = createRedactedOutputSink({ sink: mirror, redact: (text) => redactBootToken(text).slice(0, MAX_ECHOED_OUTPUT_CHARS) });
      stream.once("end", () => safeMirror.end());
      stream.on("data", (chunk) => {
        safeMirror.write(chunk);
        if (settled) return;
        if (output.length + chunk.length > 1_000_000) {
          finish(() => reject(new Error("tovu serve startup output exceeded the diagnostic limit.")));
          return;
        }
        output += chunk;

        const boot = parseBootLine(output);
        if (boot === null) return;
        const origin = `http://127.0.0.1:${boot.port}`;
        finish(() =>
          resolve({
            port: boot.port,
            pid: child.pid!, // `!`: resolved from a boot line this child printed, so it spawned and has a pid.
            origin,
            adminUrl: `${origin}/admin/`,
            workspaceId: boot.workspaceId,
            schemaVersion: boot.schemaVersion,
            // Printed BEFORE the boot line, so by the time this resolves it is already in `output`
            // — no second wait and no timing window. `null` whenever `--emit-boot-token` was not
            // passed, which is every caller but the desktop shell.
            bootToken: parseBootToken(output),
            ownerSignInCapability: serveEnv.TOVU_DESKTOP_OWNER_SIGNIN,
            stop: () => stopChild({ child, graceMs: stopGraceMs }, { platform: input.platform, killTree: input.killTree }),
            onExit: exitSignal.onExit,
          }),
        );
      });
    }

    const mirror = input.mirror ?? { stdout: process.stdout, stderr: process.stderr };
    readStream(child.stdout!, mirror.stdout);
    readStream(child.stderr!, mirror.stderr);

    child.once("error", (error) => finish(() => reject(error)));
    child.once("exit", (code, signal) => {
      finish(() => reject(new Error(describeBootFailure(redactBootToken(output), `tovu serve exited (code ${code ?? signal ?? "none"}) before reporting a port.${signal ? ` Signal: ${signal}.` : ""}`))));
    });
  }).catch(async (error) => {
    await stopChild({ child, graceMs: stopGraceMs }, { platform: input.platform, killTree: input.killTree });
    throw error;
  });
}

export {
  parseBootLine,
  parseBootToken,
  redactBootToken,
  buildCliEnv,
  parseCliErrorLine,
  resolveCliEntry,
  resolveDevCliEntry,
  buildCliSpawnPlan,
  buildServeEnv,
  allocatePort,
  createExitSignal,
  startTovuServer,
  DEFAULT_READY_TIMEOUT_MS,
  DEFAULT_STOP_GRACE_MS,
};

/**
 * "Check for updates…" in the sites home Settings menu. The Jini controller only checks from the
 * elected owner copy, every four hours, so a copy launched later could sit on an old version for
 * hours. This runs one check in the clicking copy, through the same native updater the controller
 * already listens to: a download it starts ends in the controller's own "Update ready" prompt, and
 * electron-updater reuses a download another copy already cached, so nothing downloads twice.
 */
import { RUNNER_APP_CHECK_FOR_UPDATES_CHANNEL } from './contracts/app-version.ts';

/** The slice of electron-updater's `autoUpdater` a manual check needs. */
export interface CheckableUpdater {
  autoDownload: boolean;
  autoInstallOnAppQuit: boolean;
  checkForUpdates(): Promise<{
    isUpdateAvailable?: boolean;
    updateInfo?: { version: string };
    downloadPromise?: Promise<unknown> | null;
  } | null>;
}

export type UpdateCheckOutcome =
  | { kind: 'unavailable'; reason: string }
  | { kind: 'ready'; version: string }
  | { kind: 'up-to-date'; version: string }
  | { kind: 'downloading'; version: string }
  | { kind: 'available'; version: string }
  | { kind: 'error' };

/** One native message box's text. */
export interface UpdateNotice {
  type: 'info' | 'error';
  message: string;
  detail: string;
}

export interface UpdateCheckNowDeps {
  isPackaged: boolean;
  currentVersion: () => string;
  /** `update-policy.ts`'s reason this launch runs no updater, or null. */
  skipReason: () => string | null;
  automaticUpdates: () => boolean;
  /** The version this copy's controller already downloaded and prompted for, or null. */
  readyVersion: () => string | null;
  loadUpdater: () => Promise<CheckableUpdater>;
  /** The existing "Update ready" prompt; restarts when the operator picks Restart. */
  showReadyPrompt: (args: { version: string }) => Promise<void>;
  notify: (notice: UpdateNotice) => void;
  log: (args: { message: string }) => void;
}

const NETWORK_ERROR = /ERR_INTERNET_DISCONNECTED|ERR_NAME_NOT_RESOLVED|ERR_NETWORK|ERR_CONNECTION|ERR_TIMED_OUT|ENOTFOUND|ENETUNREACH|ECONNREFUSED|ECONNRESET|ETIMEDOUT|EAI_AGAIN/;

/** Plain words for electron-updater's technical errors; the raw text goes to the log only. */
export function plainUpdateError({ message }: { message: string }, _optionalArgs = {}): string {
  if (NETWORK_ERROR.test(message)) return 'Tovu couldn’t reach the update server. Check your internet connection and try again.';
  return 'Something went wrong while checking. Try again in a few minutes.';
}

const AUTO_OFF = 'Automatic updates are off.';

function versionUpdateNotice(
  { outcome, currentVersion, automaticUpdates }: {
    outcome: Extract<UpdateCheckOutcome, { kind: 'up-to-date' | 'downloading' | 'available' }>;
    currentVersion: string; automaticUpdates: boolean;
  },
): UpdateNotice {
  switch (outcome.kind) {
    case 'up-to-date': return {
      type: 'info', message: `You’re up to date (${outcome.version})`,
      detail: automaticUpdates ? 'This is the newest version of Tovu.' : `This is the newest version of Tovu. ${AUTO_OFF}`,
    };
    case 'downloading': return {
      type: 'info', message: `Downloading Tovu ${outcome.version}…`,
      detail: `You have ${currentVersion}. Tovu asks you to restart when the download finishes.`,
    };
    case 'available': return {
      type: 'info', message: `Tovu ${outcome.version} is available`,
      detail: `You have ${currentVersion}. ${AUTO_OFF} Turn on Settings › Automatically update Tovu to download and install it.`,
    };
  }
}

/** What the operator reads for each outcome; `ready` reuses the existing prompt instead. */
export function updateCheckNotice(
  { outcome, currentVersion, isPackaged, automaticUpdates, errorMessage = '' }: {
    outcome: UpdateCheckOutcome; currentVersion: string; isPackaged: boolean; automaticUpdates: boolean; errorMessage?: string;
  },
  _optionalArgs = {},
): UpdateNotice | null {
  switch (outcome.kind) {
    case 'ready': return null;
    case 'unavailable': return isPackaged
      ? { type: 'info', message: 'Updates are off for this copy of Tovu', detail: `Reason: ${outcome.reason}.` }
      : { type: 'info', message: 'Updates only work in the installed app', detail: `This is a development copy of Tovu (${currentVersion}).` };
    case 'error': return { type: 'error', message: 'Couldn’t check for updates', detail: plainUpdateError({ message: errorMessage }) };
    default: return versionUpdateNotice({ outcome, currentVersion, automaticUpdates });
  }
}

const messageOf = (error: unknown): string => error instanceof Error ? error.message : String(error);

/**
 * One manual check at a time: a second click while one runs joins it, so no second dialog opens.
 * With automatic updates off it only looks: nothing downloads, and the notice says so.
 * @complexity O(1) per click, plus one network check.
 */
export function createUpdateCheckNow(deps: UpdateCheckNowDeps, _optionalArgs = {}): { checkNow: () => Promise<UpdateCheckOutcome> } {
  let inFlight: Promise<UpdateCheckOutcome> | null = null;

  function report(outcome: UpdateCheckOutcome, errorMessage?: string): UpdateCheckOutcome {
    const notice = updateCheckNotice({
      outcome, currentVersion: deps.currentVersion(), isPackaged: deps.isPackaged,
      automaticUpdates: deps.automaticUpdates(), errorMessage,
    });
    if (notice) deps.notify(notice);
    return outcome;
  }

  function reportCheckResult({ result, automatic }: {
    result: Awaited<ReturnType<CheckableUpdater['checkForUpdates']>>; automatic: boolean;
  }): UpdateCheckOutcome {
    const version = result?.updateInfo?.version;
    if (!result?.isUpdateAvailable || !version) return report({ kind: 'up-to-date', version: deps.currentVersion() });
    if (!automatic) return report({ kind: 'available', version });
    // The controller's own listener prompts when this finishes; only a failure needs saying here.
    result.downloadPromise?.catch((error: unknown) => {
      deps.log({ message: `update download failed: ${messageOf(error)}` });
      deps.notify({ type: 'error', message: `Couldn’t download Tovu ${version}`, detail: plainUpdateError({ message: messageOf(error) }) });
    });
    return report({ kind: 'downloading', version });
  }

  async function run(): Promise<UpdateCheckOutcome> {
    const skip = deps.skipReason();
    if (skip !== null) return report({ kind: 'unavailable', reason: skip });
    const automatic = deps.automaticUpdates();
    try {
      const ready = automatic ? deps.readyVersion() : null;
      if (ready !== null) {
        await deps.showReadyPrompt({ version: ready });
        return { kind: 'ready', version: ready };
      }
      const updater = await deps.loadUpdater();
      if (!automatic) {
        // A first import has electron-updater's defaults; the operator asked for a look only.
        updater.autoDownload = false;
        updater.autoInstallOnAppQuit = false;
      }
      const result = await updater.checkForUpdates();
      return reportCheckResult({ result, automatic });
    } catch (error) {
      deps.log({ message: `update check failed: ${messageOf(error)}` });
      return report({ kind: 'error' }, messageOf(error));
    }
  }

  return {
    checkNow() {
      inFlight ??= run().finally(() => { inFlight = null; });
      return inFlight;
    },
  };
}

/** Register once with the sites home IPC. The renderer only awaits; main shows every notice. */
export function registerUpdateCheckIpc(
  { ipcMain, checkNow }: {
    ipcMain: { handle: (channel: string, listener: () => Promise<void>) => void };
    checkNow: () => Promise<UpdateCheckOutcome>;
  },
  _optionalArgs = {},
): void {
  ipcMain.handle(RUNNER_APP_CHECK_FOR_UPDATES_CHANNEL, async () => { await checkNow(); });
}

/**
 * @file The main-process half of the desktop chat: every `workspace:chat:*`, `runner:agents:*`,
 * `workspace:conversations:*` and `runner:working-directory:*` invoke channel the ported pane calls,
 * backed by the ONE desktop agent (`desktop-agent.ts`) and the app-level conversation store.
 *
 * This is the "phase 2" `runner-ipc-stubs.ts` has been holding the place of: each channel registered
 * here is removed from that file's stub list in the same change, because Electron's `ipcMain.handle`
 * throws on a duplicate registration — a real handler and a stub for one verb is a bug.
 *
 * **Channel literals are INLINED, not imported from `src/contracts/*.ts`** — same trade, same reason
 * as `runner-ipc-stubs.ts`: those contracts import `./sections.js`, which only exists after a build,
 * and main loads `.ts` sources directly. `workspace-chat-ipc.test.ts` parses the contract sources and
 * fails on any drift, so the contracts stay the source of truth. Type-only imports are erased and safe.
 *
 * Streaming over a request/response IPC: `start` attaches the run's `RunLifecycle.stream()`
 * subscription BEFORE it resolves (the contract's own load-bearing ordering — see
 * `contracts/workspace-chat.ts`), and every event is pushed on `workspace:chat:event` tagged with the
 * renderer-minted `subscriptionId`.
 */
import fs from "node:fs";
import path from "node:path";
import type { RunProtocolEvent } from "@jini-ai/protocol";
import type { DesktopAgentRuntime } from "./desktop-agent.ts";
import type { TurnAddressee } from "./desktop-agent-tools.ts";
import type { ConversationStore } from "./workspace-conversation-store.ts";
import type { WorkspaceChatEventMessage, WorkspaceChatReattachInput, WorkspaceChatRunSnapshot, WorkspaceChatStartInput } from "./contracts/workspace-chat.ts";
import type { RunnerAgentSummary } from "./contracts/runtime-inventory.ts";
import type { RenameConversationInput, SaveConversationMessageInput } from "./contracts/workspace-conversations.ts";

const WORKSPACE_CHAT_IPC = Object.freeze({
  start: "workspace:chat:start",
  reattach: "workspace:chat:reattach",
  detach: "workspace:chat:detach",
  stop: "workspace:chat:stop",
  status: "workspace:chat:status",
  event: "workspace:chat:event",
  navigate: "workspace:chat:navigate",
});

const AGENT_INVENTORY_IPC = Object.freeze({
  list: "runner:agents:list",
  rescan: "runner:agents:rescan",
  daemonOnline: "runner:daemon:online",
});

const CONVERSATION_IPC = Object.freeze({
  list: "workspace:conversations:list",
  create: "workspace:conversations:create",
  rename: "workspace:conversations:rename",
  delete: "workspace:conversations:delete",
  loadMessages: "workspace:conversations:load-messages",
  saveMessage: "workspace:conversations:save-message",
});

const WORKING_DIRECTORY_IPC = Object.freeze({
  pick: "runner:working-directory:pick",
  recent: "runner:working-directory:recent",
  exists: "runner:working-directory:exists",
  normalize: "runner:working-directory:normalize",
});

/** Every invoke channel this module claims — `runner-ipc-stubs.ts` must not stub any of them. */
const DESKTOP_CHAT_INVOKE_CHANNELS: readonly string[] = Object.freeze([
  WORKSPACE_CHAT_IPC.start, WORKSPACE_CHAT_IPC.reattach, WORKSPACE_CHAT_IPC.detach, WORKSPACE_CHAT_IPC.stop, WORKSPACE_CHAT_IPC.status,
  ...Object.values(AGENT_INVENTORY_IPC),
  ...Object.values(CONVERSATION_IPC),
  ...Object.values(WORKING_DIRECTORY_IPC),
]);

/** The slice of a `WebContents` a subscription pushes to. */
interface EventSink {
  send(channel: string, message: WorkspaceChatEventMessage): void;
  isDestroyed(): boolean;
}

/** The slice of Electron's `ipcMain` this module uses. */
interface ChatIpcMain {
  handle(channel: string, listener: (event: { sender: EventSink }, ...args: any[]) => unknown): void;
}

/** The pane's start input plus the active site the shell renderer reports for THIS turn. */
type DesktopChatStartInput = WorkspaceChatStartInput & { activeSiteDir?: string | null };

interface WorkspaceChatIpcDeps {
  ipcMain: ChatIpcMain;
  /** A promise: the runtime binds its loopback listener asynchronously, while these handlers must
   *  be registered synchronously before the shell window can call any of them. */
  runtime: Promise<Pick<DesktopAgentRuntime, "lifecycle" | "startTurn">>;
  conversations: ConversationStore;
  /** Resolves a renderer-reported site dir to a TRACKED site, or `null`. Never trusts the path itself. */
  resolveAddressee: (siteDir: string) => TurnAddressee | null;
  listAgents: (required: { rescan: boolean }) => Promise<RunnerAgentSummary[]>;
  pickDirectory: (currentDirectory?: string) => Promise<string | null>;
}

/**
 * The turn's addressee from the renderer's report: only a site this app tracks counts, so a
 * renderer cannot point the agent's site tools at an arbitrary folder. Pure over its port.
 * @complexity O(1) plus the resolver.
 */
function addresseeForStart(input: DesktopChatStartInput, resolve: WorkspaceChatIpcDeps["resolveAddressee"]): TurnAddressee | null {
  const siteDir = input.activeSiteDir;
  return typeof siteDir === "string" && siteDir !== "" ? resolve(siteDir) : null;
}

/**
 * Registers every handler. Returns the subscription table's size reader for tests.
 *
 * @param deps ports — `ipcMain`, the agent runtime, the store, and three resolvers.
 * @complexity O(1) per registration; each pushed event is O(1).
 */
function registerWorkspaceChatIpc(deps: WorkspaceChatIpcDeps): { activeSubscriptions: () => number } {
  const subscriptions = new Map<string, () => void>();
  const lifecycleOf = async () => (await deps.runtime).lifecycle;

  const detach = (subscriptionId: string) => {
    subscriptions.get(subscriptionId)?.();
    subscriptions.delete(subscriptionId);
  };

  /** Attaches one subscription; resolves with its outcome. Every event is pushed tagged. */
  async function subscribe(sender: EventSink, subscriptionId: string, runId: string, afterCursor: string | null): Promise<void> {
    const push = (message: WorkspaceChatEventMessage) => {
      if (sender.isDestroyed()) return detach(subscriptionId);
      sender.send(WORKSPACE_CHAT_IPC.event, message);
    };
    let ended = false;
    const onEvent = (event: RunProtocolEvent) => {
      push({ subscriptionId, kind: "event", event });
      if (event.kind === "end") {
        ended = true;
        push({ subscriptionId, kind: "closed", reason: "terminal" });
        // Deferred: `stream()` may deliver a replayed `end` before it has returned its unsubscribe.
        queueMicrotask(() => detach(subscriptionId));
      }
    };
    try {
      const result = await (await lifecycleOf()).stream({ runId, onEvent }, { afterCursor });
      if (result.kind === "ok") {
        // A REPLAYED `end` (an already-finished run) queues its detach before `stream()`'s promise
        // settles, so that detach runs first and finds nothing to drop; registering now would leave a
        // dead subscription in the table for good. Release it instead.
        if (ended) {
          result.unsubscribe();
          return;
        }
        if (!subscriptions.has(subscriptionId)) subscriptions.set(subscriptionId, result.unsubscribe);
        return;
      }
      // Jini answers an evicted / never-started run with `unknown-run`; every other refusal
      // (`replay-gap`, `invalid-cursor`) means the cursor cannot be replayed, so the turn restarts.
      push({ subscriptionId, kind: "closed", reason: result.kind === "unknown-run" ? "unknown-run" : "replay-gap" });
    } catch {
      push({ subscriptionId, kind: "closed", reason: "unknown-run" });
    }
  }

  deps.ipcMain.handle(WORKSPACE_CHAT_IPC.start, async (event, input: DesktopChatStartInput) => {
    const { runId } = await (await deps.runtime).startTurn(
      { prompt: input.prompt, agentId: input.agentId },
      {
        ...(input.conversationId === undefined ? {} : { chatId: input.conversationId }),
        ...(input.model === undefined ? {} : { model: input.model }),
        ...(input.reasoning === undefined ? {} : { reasoning: input.reasoning }),
        ...(input.attachmentPaths === undefined ? {} : { attachmentPaths: input.attachmentPaths }),
        addressee: addresseeForStart(input, deps.resolveAddressee),
      },
    );
    await subscribe(event.sender, input.subscriptionId, runId, null);
    return { runId };
  });
  deps.ipcMain.handle(WORKSPACE_CHAT_IPC.reattach, async (event, input: WorkspaceChatReattachInput) => {
    await subscribe(event.sender, input.subscriptionId, input.runId, input.afterCursor ?? null);
  });
  deps.ipcMain.handle(WORKSPACE_CHAT_IPC.detach, (_event, { subscriptionId }: { subscriptionId: string }) => detach(subscriptionId));
  deps.ipcMain.handle(WORKSPACE_CHAT_IPC.stop, async (_event, { runId }: { runId: string }) => {
    await (await lifecycleOf()).cancel({ runId, reason: "Stopped by the operator." });
  });
  deps.ipcMain.handle(WORKSPACE_CHAT_IPC.status, async (_event, { runId }: { runId: string }): Promise<WorkspaceChatRunSnapshot | null> => {
    const run = await (await lifecycleOf()).get({ runId });
    return run === undefined ? null : { runId: run.id, state: run.state };
  });

  deps.ipcMain.handle(AGENT_INVENTORY_IPC.list, () => deps.listAgents({ rescan: false }));
  deps.ipcMain.handle(AGENT_INVENTORY_IPC.rescan, () => deps.listAgents({ rescan: true }));
  // The daemon is in-process: if this handler answers, it is online.
  deps.ipcMain.handle(AGENT_INVENTORY_IPC.daemonOnline, () => true);

  deps.ipcMain.handle(CONVERSATION_IPC.list, () => deps.conversations.list());
  deps.ipcMain.handle(CONVERSATION_IPC.create, () => deps.conversations.create());
  deps.ipcMain.handle(CONVERSATION_IPC.rename, (_event, input: RenameConversationInput) => deps.conversations.rename(input));
  deps.ipcMain.handle(CONVERSATION_IPC.delete, (_event, { id }: { id: string }) => deps.conversations.remove({ id }));
  deps.ipcMain.handle(CONVERSATION_IPC.loadMessages, (_event, { conversationId }: { conversationId: string }) => deps.conversations.loadMessages({ conversationId }));
  deps.ipcMain.handle(CONVERSATION_IPC.saveMessage, (_event, input: SaveConversationMessageInput) => deps.conversations.saveMessage(input));

  deps.ipcMain.handle(WORKING_DIRECTORY_IPC.pick, (_event, currentDirectory?: string) => deps.pickDirectory(currentDirectory));
  deps.ipcMain.handle(WORKING_DIRECTORY_IPC.recent, () => []);
  deps.ipcMain.handle(WORKING_DIRECTORY_IPC.exists, (_event, directory: string) => isDirectory(directory));
  deps.ipcMain.handle(WORKING_DIRECTORY_IPC.normalize, (_event, directory: string) => (isDirectory(directory) ? path.resolve(directory) : null));

  return { activeSubscriptions: () => subscriptions.size };
}

/** `true` only for an existing directory. @complexity O(1) syscall. */
function isDirectory(directory: unknown): boolean {
  if (typeof directory !== "string" || directory === "") return false;
  try {
    return fs.statSync(directory).isDirectory();
  } catch {
    return false;
  }
}

export { registerWorkspaceChatIpc, addresseeForStart, DESKTOP_CHAT_INVOKE_CHANNELS, WORKSPACE_CHAT_IPC, AGENT_INVENTORY_IPC, CONVERSATION_IPC, WORKING_DIRECTORY_IPC };
export type { WorkspaceChatIpcDeps, DesktopChatStartInput, EventSink, ChatIpcMain };

import { useCallback, useEffect, useMemo, useRef } from 'react';
import { useEmbedChatDialog } from '@jini-ai/chat/react/embed';
import { createReactSiteComparisonControl } from './site-chat-comparison';
import { createSiteChatI18n } from './site-chat-i18n';

/** Public adapter over Jini's shared dialog lifecycle and the page's own language. O(1). */
export function useSiteAssistantSurface({ open, setOpen }: {
  open: boolean; setOpen: (open: boolean) => void;
}, { resetKey }: { resetKey?: number } = {}) {
  const panelRef = useRef<HTMLDivElement>(null);
  const launcherRef = useRef<HTMLDivElement>(null);
  const closePanel = useCallback(() => setOpen(false), [setOpen]);
  useEmbedChatDialog({ open, onClose: closePanel, panelRef, launcherRef }, { resetKey });
  const i18n = useMemo(() => createSiteChatI18n({ document }), []);
  const suggestions = useMemo(() => [i18n.t('What can I find on this site?'), i18n.t('Show me the latest posts')], [i18n]);
  return { panelRef, launcherRef, closePanel, i18n, suggestions };
}

/** The bridge is stable across streaming renders; only the dev comparison frame enables it. */
export function useSiteAssistantComparison({ root }: { root: HTMLElement | null }, _options = {}) {
  return useMemo(() => createReactSiteComparisonControl({ root }), [root]);
}

/** Loader activation may precede React's first effect; the mount attribute carries that intent. */
export function readSiteChatOpen({ persistedOpen, root }: { persistedOpen: boolean; root: HTMLElement | null }, _options = {}): boolean {
  return persistedOpen || root?.dataset.chatOpen === 'true';
}

/** Retains explicit open intent across script load and React commit without toggling twice. */
export function useSiteAssistantActivation({ root, open, setOpen }: {
  root: HTMLElement | null; open: boolean; setOpen: (open: boolean) => void;
}, _options = {}): { toggleOpen: () => void } {
  const focusRequested = useRef(false);
  const openRef = useRef(open);
  openRef.current = open;
  const toggleOpen = useCallback(() => {
    focusRequested.current = !open;
    setOpen(!open);
  }, [open, setOpen]);
  useEffect(() => {
    if (!root) return;
    const activate = () => {
      focusRequested.current ||= root.dataset.chatFocus === 'true';
      delete root.dataset.chatFocus;
      setOpen(true);
      if (focusRequested.current && openRef.current) {
        focusRequested.current = false;
        root.querySelector<HTMLTextAreaElement>('textarea:not(:disabled)')?.focus();
      }
    };
    root.addEventListener('jini-chat-open', activate);
    if (root.dataset.chatOpen === 'true') activate();
    return () => root.removeEventListener('jini-chat-open', activate);
  }, [root, setOpen]);
  useEffect(() => {
    if (!open || !focusRequested.current) return;
    focusRequested.current = false;
    root?.querySelector<HTMLTextAreaElement>('textarea:not(:disabled)')?.focus();
  }, [root, open]);
  useEffect(() => {
    if (!root) return;
    root.dataset.chatMounted = 'true';
    root.dispatchEvent(new Event('jini-chat-mounted'));
    return () => { delete root.dataset.chatMounted; };
  }, [root]);
  return { toggleOpen };
}

import type { ChatMessage } from "@jini-ai/chat/core";
import { readSiteChatComparisonVariant } from "./site-chat-comparison";

/**
 * @file SPEC-046 REQ-1/REQ-2 — the single `sessionStorage` module for the public site chat: the
 * transcript, the pane's open/closed state, and the post-navigation action queue.
 *
 * All three used to live in two files (`transcript-storage.ts`, `action-queue.ts`) with two
 * independent key schemes. Collapsed into one module, per the owner's explicit preference not to
 * have storage access "saved across a bunch of files" — two schemes that can drift is exactly the
 * failure mode a second file invites, even though transcript+open-state and the action queue remain
 * two separate keys (see "Two keys, one module" below; REQ-2 requires the queue to survive
 * independently of the transcript). This is a shape change, not a rewrite: every function's
 * behavior, and the tests that prove it, are unchanged from the two-file version.
 *
 * `sessionStorage`, never `localStorage`: per-tab, dies with the tab. That is the correct privacy
 * default for an anonymous visitor on a widget mounted on every page of the site — a transcript must
 * not leak into a LATER, unrelated visit on a shared machine, which is exactly what `localStorage`
 * would do.
 *
 * ## Two keys, one module
 *
 * `TRANSCRIPT_STORAGE_KEY` holds `{ open, messages }` as a single JSON envelope — both fields
 * together so "the corrupt entry" is one well-defined thing (REQ-1's fail-soft rehydrate) instead of
 * two independently-corruptible keys that could disagree. `ACTION_QUEUE_STORAGE_KEY` is a second,
 * separate key: REQ-2 requires it to be queued "beside" the transcript and drained independently on
 * every mount, regardless of transcript state, so folding it into the same envelope would couple two
 * things that fail, clear, and drain on entirely different triggers. Both keys share the
 * `tovu.site-assistant.*.v1` namespace and live in this one file — that is the "one versioned
 * namespace" the consolidation asked for, not a merged key.
 *
 * ## Narrow storage seam, not the DOM `Storage` type
 *
 * Every exported function takes a `SessionStore`, a 3-method interface (`getItem`/`setItem`/
 * `removeItem`), instead of the full DOM `Storage` type. `Storage` also requires `length`, `key()`,
 * and `clear()`, none of which this module ever calls — a test double for the full type has to
 * implement three methods nobody exercises. `SessionStore` documents exactly what is touched and
 * keeps fakes trivial. This is dependency injection for testability only: there is exactly one real
 * backend (`sessionStorage`) and no swappable-adapter goal, so there is no port/adapter abstraction
 * here beyond this one interface.
 */

/** The narrow seam every function in this module depends on, instead of the full DOM `Storage`
 *  type (`length`, `key()`, `clear()` — unused here). A real `Storage` instance (including
 *  `sessionStorage` itself) satisfies this structurally with no adapter needed. */
export interface SessionStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

export const TRANSCRIPT_STORAGE_KEY = "tovu.site-assistant.transcript.v1";
const ACTION_QUEUE_STORAGE_KEY = "tovu.site-assistant.action-queue.v1";

/** Oldest-dropped-first message cap. Generous enough for a real visitor conversation; small enough
 *  that nothing here approaches `sessionStorage`'s much larger real-world quota on its own. */
const MAX_MESSAGES = 50;
/** Serialized byte cap enforced independently of the message-count cap: `PublicEntryDetail.text` (up
 *  to 4000 chars, `assistant/site/tools.ts`) can appear inside an assistant reply, so a handful of
 *  long messages could otherwise blow the budget well under `MAX_MESSAGES`. An unbounded transcript
 *  is a quota-exceeded exception mid-conversation, which is the failure this cap exists to prevent. */
const MAX_BYTES = 200_000;

export interface PersistedSiteAssistantState {
  readonly open: boolean;
  readonly messages: ChatMessage[];
}

const EMPTY_STATE: PersistedSiteAssistantState = { open: false, messages: [] };

/** Deliberately `unknown` — SPEC-046 REQ-4 through REQ-8 (the typed `client_directive` payload) are a
 *  separate slice; whatever they eventually queue must be JSON-serializable (it round-trips through
 *  `sessionStorage` via `JSON.stringify`/`JSON.parse`), but no shape beyond that is asserted here. */
export type QueuedAction = unknown;

function isPlainRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Structural allowlist for one persisted `ChatMessage`, not a full schema — this is a
 * fail-soft-rehydrate gate (REQ-1), not a REQ-6-style security boundary; the transcript is rendered
 * by `@jini-ai/chat`'s own message list either way. Only the fields this widget actually reads back
 * are checked; anything else on a real `ChatMessage` (`events`, `attachments`, …) is passed through
 * unchecked if present, same as it always was before this file existed.
 */
function isValidMessage(value: unknown): value is ChatMessage {
  if (!isPlainRecord(value)) return false;
  return typeof value.id === "string" && (value.role === "user" || value.role === "assistant") && typeof value.content === "string";
}

function byteLength(value: string): number {
  return new TextEncoder().encode(value).length;
}

/**
 * Fail-soft rehydrate (REQ-1): malformed JSON, a non-object envelope, a wrong-shaped `open`/`messages`
 * field, or a single wrong-shaped message ANYWHERE in the array all take the same path — the key is
 * cleared and mount proceeds with the empty default. A corrupt entry must never throw during mount,
 * and it never partially recovers (no "keep the valid messages, drop the bad one"): the whole point is
 * that one bad entry costs at most this session's transcript, never a broken widget.
 *
 * Storage access itself is also guarded: a browser that throws on `sessionStorage` access at all
 * (private-mode Safari historically, a sandboxed iframe without the `allow-storage-access-by-user-
 * activation` permission) degrades to the same empty default rather than crashing the widget on load.
 *
 * @complexity O(n) in message count for the shape check; O(1) storage calls.
 * @overallScore 100
 */
export function loadPersistedState(storage: SessionStore): PersistedSiteAssistantState {
  let raw: string | null;
  try {
    raw = storage.getItem(TRANSCRIPT_STORAGE_KEY);
  } catch {
    return EMPTY_STATE;
  }
  if (raw === null) return EMPTY_STATE;

  try {
    const parsed: unknown = JSON.parse(raw);
    if (!isPlainRecord(parsed)) throw new Error("persisted state is not an object");
    if (typeof parsed.open !== "boolean") throw new Error("persisted state.open is not a boolean");
    if (!Array.isArray(parsed.messages) || !parsed.messages.every(isValidMessage)) {
      throw new Error("persisted state.messages is not a valid ChatMessage[]");
    }
    return { open: parsed.open, messages: parsed.messages };
  } catch {
    clearPersistedState(storage);
    return EMPTY_STATE;
  }
}

/**
 * Persists transcript + pane-open state, dropping the OLDEST messages first until both the count cap
 * (`MAX_MESSAGES`) and the serialized byte cap (`MAX_BYTES`) are satisfied (REQ-1). Never throws: a
 * `setItem` failure (quota still exceeded despite capping, storage disabled mid-session) degrades to
 * "this turn is not persisted," never a broken send path — the visitor's live conversation must not
 * depend on a background write succeeding.
 *
 * @complexity O(n) in message count (repeated re-serialization while trimming); n is bounded by
 *   `MAX_MESSAGES` on entry in the caller's normal usage, so this is not unbounded in practice.
 * @overallScore 100
 */
export function savePersistedState(storage: SessionStore, state: PersistedSiteAssistantState): void {
  let messages = state.messages;
  if (messages.length > MAX_MESSAGES) messages = messages.slice(messages.length - MAX_MESSAGES);

  let serialized = JSON.stringify({ open: state.open, messages });
  while (messages.length > 0 && byteLength(serialized) > MAX_BYTES) {
    messages = messages.slice(1);
    serialized = JSON.stringify({ open: state.open, messages });
  }

  try {
    storage.setItem(TRANSCRIPT_STORAGE_KEY, serialized);
  } catch {
    // Quota exceeded (even after trimming) or storage disabled — the conversation continues in
    // memory for this tab; nothing here may throw into a message-send path.
  }
}

/** "New thread" must clear the persisted copy, not just in-memory state (REQ-1) — otherwise a reload
 *  right after resetting would rehydrate the discarded conversation straight back. */
export function clearPersistedState(storage: SessionStore): void {
  try {
    storage.removeItem(TRANSCRIPT_STORAGE_KEY);
  } catch {
    // Storage inaccessible — there is nothing to clear, and nothing here may throw.
  }
}

/**
 * Queues one action to run after the next navigation. Overwrites any action already queued — this is
 * a single-slot queue, not a FIFO: SPEC-046 §4's first consumers are all triggered by an explicit
 * visitor action ("take me there"), so there is never a legitimate reason for two directives to be
 * in flight for the same visitor at once, and a queue with unbounded depth would just be more
 * unclaimed state to leak across an abandoned navigation.
 */
export function enqueueAction(storage: SessionStore, action: QueuedAction): void {
  try {
    storage.setItem(ACTION_QUEUE_STORAGE_KEY, JSON.stringify(action));
  } catch {
    // Storage full/disabled — the action is simply not queued. Failing to queue must degrade to "the
    // visitor's own subsequent click/scroll behaves normally," never a broken nav.
  }
}

/**
 * Drains at most one queued action. **Deletes the entry from storage before returning it** — not
 * after a caller finishes "executing" it — so that if the page is reloaded mid-execution (or the
 * execution step is never reached at all, e.g. a future consumer throws), the SAME action can never
 * be read again on the next mount. This ordering is REQ-2's entire point: a queued action surviving a
 * reload and re-firing on every subsequent page load is the one failure mode the mechanism exists to
 * prevent.
 *
 * Call exactly once per mount. A corrupt entry (malformed JSON) is treated as nothing queued, not an
 * error — it has already been deleted above by the time the parse is attempted, so this can never
 * leave a poisoned entry behind for a later mount to trip over again.
 *
 * @complexity O(1) — two storage calls and one JSON parse, independent of anything else in the app.
 * @overallScore 100
 */
export function drainQueuedAction(storage: SessionStore): QueuedAction | null {
  let raw: string | null;
  try {
    raw = storage.getItem(ACTION_QUEUE_STORAGE_KEY);
  } catch {
    return null;
  }
  if (raw === null) return null;

  try {
    storage.removeItem(ACTION_QUEUE_STORAGE_KEY);
  } catch {
    // If removal itself fails, this call cannot guarantee the action won't be read again on the next
    // mount — failing closed (never returning it) is safer than risking a re-fire, since "the action
    // silently didn't run once" is a much smaller failure than "the action re-runs on every reload."
    return null;
  }

  try {
    return JSON.parse(raw) as QueuedAction;
  } catch {
    // Already deleted above, so this degrades to "nothing was queued" with no residue left behind.
    return null;
  }
}

/**
 * Caller-facing wrappers, bound to the real `sessionStorage`. `SiteAssistantWidget.tsx` and
 * `main.tsx` call these, never `sessionStorage` itself — this is what makes the guard test in
 * `__tests__/session-store.test.ts` ("no other file in `src` names `sessionStorage`") meaningful
 * rather than accidental. The injectable forms above stay exported for tests, which supply a fake
 * `SessionStore` instead.
 */
export function loadSiteAssistantState(): PersistedSiteAssistantState {
  return loadPersistedState(browserStorage);
}

export function saveSiteAssistantState(state: PersistedSiteAssistantState): void {
  savePersistedState(browserStorage, state);
}

export function clearSiteAssistantState(): void {
  clearPersistedState(browserStorage);
}

export function enqueuePageAction(action: QueuedAction): void {
  enqueueAction(browserStorage, action);
}

export function drainQueuedPageAction(): QueuedAction | null {
  return drainQueuedAction(browserStorage);
}

// Access the browser getter inside the injectable helpers' existing try blocks: private browsing
// may throw even when reading sessionStorage itself, before getItem can run.
const browserStorage: SessionStore = {
  getItem: (key) => sessionStorage.getItem(siteStorageKey({ key })),
  setItem: (key, value) => sessionStorage.setItem(siteStorageKey({ key }), value),
  removeItem: (key) => sessionStorage.removeItem(siteStorageKey({ key })),
};

/** Same-origin frames share session storage. Keep each comparison transcript/queue apart from
 * both its sibling and the visitor's real thread, while retaining this module's caps and guards. */
export function siteStorageKey({ key }: { key: string }, options: { root?: HTMLElement | null } = {}): string {
  const root = options.root === undefined ? globalThis.document?.getElementById('tovu-site-assistant-root') : options.root;
  const variant = root ? readSiteChatComparisonVariant({ document: root.ownerDocument }) : null;
  return variant === 'react' || variant === 'vanilla' ? `${key}.compare.${variant}` : key;
}

/** The tiny loader checks pending effects without draining the widget's single-use queue. */
export function hasQueuedPageAction(_input = {}, _options = {}): boolean {
  try { return browserStorage.getItem(ACTION_QUEUE_STORAGE_KEY) !== null; } catch { return false; }
}

/**
 * @file Visitor-facing wording for a failed "Ask this site" turn. Both widget builds (React
 * `ChatPane` and the Pure JS vanilla widget) render whatever `Error.message` the transport hands to
 * `RunHandlers.onError` — React as the failed reply's `run_terminal` notice under the assistant
 * message, vanilla in its `role="alert"` error row — so phrasing it once here covers both.
 */

/** Reported when the stream settles with neither text nor a page action — the visitor would
 *  otherwise see an empty reply and no hint that anything went wrong. */
export const NO_REPLY_REASON = "the assistant sent no reply";

/** `fetch` rejects with a bare `TypeError` on a network failure; its message is browser-specific
 *  ("Failed to fetch", "Load failed", "NetworkError when attempting to fetch resource."). */
const NETWORK_FAILURE = /failed to fetch|load failed|networkerror/i;

/**
 * Wraps any failure as "Couldn't get an answer: <reason>. Try again.", keeping the server's own
 * reason (the JSON `error` body or SSE `error` frame) visible rather than a generic "failed".
 *
 * @param input.error - Whatever the transport caught or was told; non-Errors are stringified.
 * @returns A new `Error` carrying the visitor-facing message.
 * @complexity O(n) in the reason's length.
 */
export function visitorFacingError({ error }: { error: unknown }, _options = {}): Error {
  const raw = error instanceof Error ? error.message : String(error ?? "");
  const reason = error instanceof TypeError && NETWORK_FAILURE.test(raw)
    ? "couldn't reach the site"
    : raw.trim().replace(/[.!\s]+$/, "") || "something went wrong";
  return new Error(`Couldn't get an answer: ${reason}. Try again.`);
}

/**
 * @file The PUBLIC site chat's implementation of `@jini-ai/chat/core`'s `ChatTransport` port
 * (ADR-054 Task 2), the browser half of `src/server/modules/site-assistant.ts`.
 *
 * Deliberately NOT a copy of `apps/admin/src/lib/assistant-transport.ts`, and not only because this
 * bundle must not import admin code at all (enforced by `vite.config.ts`'s `forbidAdminImports`):
 * the two backends speak different protocols end to end.
 *
 * - The admin transport calls `POST /api/runs` (start) then opens a native `EventSource` against
 *   `GET /api/runs/:runId/events` — a persisted, reattachable run behind an admin-session daemon.
 * - This transport calls `POST /api/site-assistant/chat` exactly once per visitor turn. The whole
 *   reply streams back on that SAME request's response body (`text`/`error`/`end`/`client_directive`
 *   SSE frames — see `site-assistant.ts`'s `sse()` helper), and nothing about the RUN is persisted
 *   server-side: there is still no run id to reattach to (see `reattachRun` below). `startRun` sends
 *   the latest user
 *   turn as `message` (`latestUserPromptFromHistory`) plus, as of SPEC-046 REQ-3, a bounded `history`
 *   of the turns before it — not a flattened transcript string the way `buildTranscript`'s "## user /
 *   ## assistant" replay format works (that is built for a coding-agent transcript, not a
 *   natural-language question); the server keeps each turn's own `role` and feeds them to Gemini as
 *   real multi-turn `Content` entries (`assistant/site/history.ts`). `boundHistoryForRequest` below
 *   is a bandwidth/politeness courtesy only — the server treats whatever arrives as untrusted and
 *   re-bounds/validates it independently, so this file's caps do not need to match the server's
 *   exactly.
 *
 * Because a native `EventSource` cannot POST, the SSE body is parsed by hand off `fetch`'s
 * `ReadableStream`, matching the exact two-line `event:`/`data:` framing `sse()` writes server-side.
 */
import { latestUserPromptFromHistory } from "@jini-ai/chat/core";
import type { AgentEvent, ChatMessage } from "@jini-ai/chat/core";
import type { ChatTransport, RunHandlers, StartRunInput } from "@jini-ai/chat/react";

import { NO_REPLY_REASON, visitorFacingError } from "./site-assistant-errors";
import { parseToolConfirmation, type ToolConfirmation } from "./tool-confirmation";

const CHAT_URL = "/api/site-assistant/chat";
/** Silence (no bytes at all) this long ends the turn with a visible error instead of an endless
 *  "Replying…". The server sends no keep-alive frames, and a reply can pause while it searches
 *  content, so this is generous; any received chunk restarts it. */
const IDLE_TIMEOUT_MS = 90_000;
const TIMEOUT_REASON = "the site took too long to respond";
/** Oldest-dropped-first turn cap and per-turn character cap for the `history` sent alongside a
 *  message — matches `assistant/site/history.ts`'s server-side defaults in VALUE only (the server is
 *  the actual enforcement point; see this file's header). */
const MAX_HISTORY_MESSAGES = 12;
const MAX_HISTORY_MESSAGE_CHARS = 2000;

interface HistoryTurn {
  readonly role: ChatMessage["role"];
  readonly content: string;
}

/**
 * `input.history`'s trailing entry is the message currently being sent — `useConversation.ts`'s
 * `sendMessage` builds `history` as `[...priorMessages, userMessage]` before calling `run.start`, and
 * `latestUserPromptFromHistory` extracts that same trailing user turn as `message`. This returns
 * everything BEFORE it, scanning from the end (the same direction `latestUserPromptFromHistory` scans
 * in) rather than assuming a fixed "drop the last element" so this stays correct even if a future
 * caller's `history` does not end in the user turn.
 */
function priorTurnsBeforeLatestUserMessage(history: ChatMessage[]): ChatMessage[] {
  // Precondition: `history` holds a user turn. `startRun` calls `latestUserPromptFromHistory` first,
  // which throws when there is none and scans for the same condition (last `role === "user"`, from
  // the end) over the same unmutated array — so this scan always stops at an index >= 0. The former
  // "no user turn" fallback (`return history`) was unreachable through the public API and was
  // removed; a caller breaking the precondition now fails fast instead of sending everything.
  let i = history.length - 1;
  while (history[i]!.role !== "user") i -= 1;
  return history.slice(0, i);
}

/** Bounds the prior turns sent alongside a message. Not the security boundary (see file header) —
 *  just keeps a long local conversation from ballooning every request's payload. */
function boundHistoryForRequest(history: ChatMessage[]): HistoryTurn[] {
  const prior = priorTurnsBeforeLatestUserMessage(history);
  const recent = prior.length > MAX_HISTORY_MESSAGES ? prior.slice(prior.length - MAX_HISTORY_MESSAGES) : prior;
  return recent
    .filter((m) => m.content.trim().length > 0)
    .map((m) => ({
      role: m.role,
      content: m.content.length > MAX_HISTORY_MESSAGE_CHARS ? m.content.slice(0, MAX_HISTORY_MESSAGE_CHARS) : m.content,
    }));
}

interface ChatFrameText {
  readonly delta: string;
}
interface ChatFrameError {
  readonly message: string;
}
interface ChatFrameEnd {
  readonly reason: string;
}

/** SPEC-046 REQ-4: the one new SSE event kind. Carried through `@jini-ai/chat/core`'s `AgentEvent`
 *  via its `{ kind: 'ext', name, data }` escape hatch (`events.ts`'s own doc: "a host can carry its
 *  own product-specific event kinds... through the same envelope without this package knowing about
 *  them") — this is exactly that case, so no fork of chat-core's event union was needed. `data` is
 *  passed through unvalidated at THIS layer; `client-directives.ts`'s `isPageActionDirective` is what
 *  actually narrows it before anything acts on it (see `SiteAssistantWidget.tsx`). */
const CLIENT_DIRECTIVE_EXT_NAME = "client_directive";

/** Parses one complete SSE frame's `event:`/`data:` lines (defaulting `event` to `"message"`). */
function parseSseFrame(frame: string): { event: string; data: string | null } {
  let event = "message";
  let data: string | null = null;
  for (const line of frame.split("\n")) {
    if (line.startsWith("event:")) event = line.slice("event:".length).trim();
    else if (line.startsWith("data:")) data = line.slice("data:".length).trim();
  }
  return { event, data };
}

/**
 * Extracts and dispatches every complete `\n\n`-delimited frame currently in `buffer` via `onFrame`,
 * returning the remaining not-yet-terminated tail for the next read.
 */
function drainCompleteFrames(buffer: string, onFrame: (event: string, data: unknown) => void): string {
  let remaining = buffer;
  let boundary = remaining.indexOf("\n\n");
  while (boundary !== -1) {
    const frame = remaining.slice(0, boundary);
    remaining = remaining.slice(boundary + 2);

    const { event, data } = parseSseFrame(frame);
    // `sse()` always writes both lines together; a frame with no `data:` line is not one of ours
    // (a proxy keep-alive comment, e.g.) and is skipped rather than handed to `JSON.parse(null)`.
    if (data !== null) onFrame(event, JSON.parse(data));

    boundary = remaining.indexOf("\n\n");
  }
  return remaining;
}

/**
 * Parses one `fetch` response body as the `event:`/`data:` SSE framing `sse()` writes
 * (`src/server/modules/site-assistant.ts`), invoking `onFrame` once per complete frame and `onChunk`
 * once per received chunk (any bytes, complete frame or not — the idle timer's "still alive" signal).
 *
 * Hand-rolled rather than a library SSE client because `fetch` is required here (a POST body), and
 * the browser's native `EventSource` only ever issues GET — the same constraint the admin transport
 * itself does not have, since its run-events endpoint IS a GET.
 *
 * @complexity O(n) in response bytes; buffers only the not-yet-terminated tail between reads.
 * @overallScore 100
 */
async function pumpServerSentEvents(
  response: Response,
  onFrame: (event: string, data: unknown) => void,
  onChunk: () => void,
): Promise<void> {
  const body = response.body;
  if (!body) throw new Error("site assistant response had no stream body");

  const reader = body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";

  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    onChunk();
    buffer += decoder.decode(value, { stream: true });
    buffer = drainCompleteFrames(buffer, onFrame);
  }
}

/** Tracks the one in-flight fetch per `runId` so `stopRun` can cancel it. Module-scope: the
 *  transport itself is stateless per call, but a cancellation has to reach a specific earlier call. */
const activeRuns = new Map<string, AbortController>();

export interface SiteAssistantTransportOptions {
  /** Live UI only: challenges never enter events, persisted messages or provider history. */
  readonly onToolConfirmation?: (required: { directive: ToolConfirmation | null }, optional?: Record<string, never>) => void;
  /** Defaults to the global `fetch`, resolved per call. */
  readonly fetch?: typeof fetch;
  /** Defaults to {@link IDLE_TIMEOUT_MS}. */
  readonly idleTimeoutMs?: number;
}

/** Consume the human-only envelope even when malformed or late. It must never fall through into
 * transcript events, session persistence or a later provider history.
 */
function consumeToolConfirmation({ data, settled, receive }: {
  data: unknown; settled: boolean; receive: SiteAssistantTransportOptions['onToolConfirmation'];
}, _options = {}): boolean {
  if (!data || typeof data !== 'object' || (data as { kind?: unknown }).kind !== 'tool_confirmation') return false;
  const directive = parseToolConfirmation({ value: data });
  if (directive && !settled) receive?.({ directive });
  return true;
}

/**
 * Every failure a visitor can hit — non-ok HTTP (incl. the server's JSON `{ error }`), an SSE
 * `error` frame, a network/stream failure, a stream that settles with no reply, or
 * {@link IDLE_TIMEOUT_MS} of silence — reaches `onError` exactly once, worded by
 * `visitorFacingError`, and the run always finishes so the composer re-enables for another try.
 */
export function createSiteAssistantTransport(_required: Record<string, never> = {}, options: SiteAssistantTransportOptions = {}): ChatTransport {
  const fetchChat: typeof fetch = options.fetch ?? ((...args) => globalThis.fetch(...args));
  const idleTimeoutMs = options.idleTimeoutMs ?? IDLE_TIMEOUT_MS;
  return {
    async startRun(input: StartRunInput, handlers: RunHandlers): Promise<{ runId: string }> {
      const message = latestUserPromptFromHistory({ history: input.history as ChatMessage[] });
      if (!message) throw new Error("no user message to send");

      const runId = crypto.randomUUID();
      const controller = new AbortController();
      activeRuns.set(runId, controller);
      // `input.signal` closes the browser-side subscription (component unmount, pane reset). This
      // backend has no host-side continuation once that happens — the whole run IS this fetch — so
      // unlike the admin transport's `signal` doc, here that also means stopping the run for real.
      input.signal.addEventListener("abort", () => controller.abort());

      const collected: AgentEvent[] = [];
      let settled = false;
      let failed = false;
      let replied = false;
      let timedOut = false;
      let idleTimer: ReturnType<typeof setTimeout> | undefined;
      const armIdleTimer = () => {
        clearTimeout(idleTimer);
        idleTimer = setTimeout(() => { timedOut = true; controller.abort(); }, idleTimeoutMs);
      };
      // Settled runs stay silent: an error after `end` (a late frame, a reset socket) must not
      // paint a failure under a reply the visitor already has.
      const fail = (error: unknown) => {
        if (settled) return;
        failed = true;
        handlers.onError(visitorFacingError({ error }));
      };
      // `expectReply: false` only for an abort: a visitor's own Stop is not a missing reply.
      const finish = ({ expectReply = true }: { expectReply?: boolean } = {}) => {
        if (settled) return;
        if (expectReply && !failed && !replied) fail(NO_REPLY_REASON);
        settled = true;
        options.onToolConfirmation?.({ directive: null });
        clearTimeout(idleTimer);
        activeRuns.delete(runId);
        handlers.onDone(collected);
      };

      (async () => {
        try {
          armIdleTimer();
          const response = await fetchChat(CHAT_URL, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            // No credentials, no key: ADR-054 Decision 3 — the visitor never supplies or sees a
            // provider key, and this route requires no admin session either.
            body: JSON.stringify({ message, history: boundHistoryForRequest(input.history as ChatMessage[]) }),
            signal: controller.signal,
          });

          if (!response.ok) {
            const body = (await response.json().catch(() => null)) as { error?: string } | null;
            fail(new Error(body?.error || `site assistant request failed (${response.status})`));
            finish();
            return;
          }

          await pumpServerSentEvents(response, (event, data) => {
            if (event === "text") {
              const ev: AgentEvent = { kind: "text", text: (data as ChatFrameText).delta };
              if (ev.text.trim()) replied = true;
              collected.push(ev);
              handlers.onEvent(ev);
            } else if (event === "error") {
              fail(new Error((data as ChatFrameError).message || "site assistant error"));
            } else if (event === "end") {
              void (data as ChatFrameEnd); // reason is server telemetry only; nothing here branches on it.
              finish();
            } else if (event === "client_directive") {
              if (consumeToolConfirmation({ data, settled, receive: options.onToolConfirmation })) return;
              const ev: AgentEvent = { kind: "ext", name: CLIENT_DIRECTIVE_EXT_NAME, data };
              // A page action alone (e.g. "take me there") is a real answer, not an empty reply.
              replied = true;
              collected.push(ev);
              handlers.onEvent(ev);
            }
          }, armIdleTimer);
          // Stream ended without an explicit "end" frame (e.g. the connection just closed) —
          // finish anyway so the pane never shows a run stuck "in progress" forever.
          finish();
        } catch (error) {
          // An abort we caused ourselves (stopRun, or the pane unmounting) is not a failure to
          // report — it is the requested outcome, and `res.on("close")` server-side already turned
          // it into a clean upstream cancellation rather than a wasted completed generation. The
          // idle timer's abort is the exception: the visitor asked nothing to stop, so say why.
          if (error instanceof DOMException && error.name === "AbortError") {
            if (timedOut) fail(TIMEOUT_REASON);
            finish({ expectReply: false });
            return;
          }
          fail(error);
          finish();
        }
      })();

      return { runId };
    },

    /**
     * There is nothing to reattach to: this backend persists no run state once a fetch completes or
     * is aborted (see this file's header). In practice this is never called — the widget never
     * hands `ChatPane` an `initialMessages` entry with a run still "in progress" (no conversation is
     * ever persisted across a page load), which is the only case `ChatPane` calls this for. Resolves
     * immediately with an empty event log rather than throwing, so a call that does happen (a future
     * caller relying on a different assumption) degrades to "nothing more arrived" instead of an
     * unhandled rejection.
     */
    async reattachRun(_runId: string, handlers: RunHandlers): Promise<void> {
      handlers.onDone([]);
    },

    /** No server-side run registry exists to ask — every run's outcome is observed only through its
     *  own `RunHandlers`, never polled after the fact. */
    async fetchRunStatus(): Promise<null> {
      return null;
    },

    async stopRun(runId: string): Promise<void> {
      activeRuns.get(runId)?.abort();
    },
  };
}

import { micromark } from 'micromark';
import { gfm, gfmHtml } from 'micromark-extension-gfm';
import { allowsSitePageAction } from './site-page-actions';
import { createSiteAssistantTransport } from './site-assistant-transport';
import { clearSiteAssistantState, drainQueuedPageAction, enqueuePageAction, loadSiteAssistantState, saveSiteAssistantState } from './session-store';
import { applyHighlight, clearHighlight, findTargetElement, scrollToElement } from './highlight';
import type { PageAction } from './client-directives';
import { installSiteChatComparisonSend } from './site-chat-comparison';
import { createSiteChatI18n } from './site-chat-i18n';
import { createVanillaToolConfirmation } from './vanilla-tool-confirmation';

/** Binds the existing product adapters; Jini owns the DOM widget and conversation state. */
export function createSiteVanillaArgs({ element }: { element: HTMLElement }, options: {
  document?: Document;
  /** Full-page navigation for a `navigate` page action; defaults to the page's `location.assign`. */
  assign?: (input: { path: string }) => void;
} = {}) {
  const document = options.document ?? window.document;
  const assign = options.assign ?? (({ path }: { path: string }) => window.location.assign(path));
  const { t } = createSiteChatI18n({ document });
  const showConfirmation = createVanillaToolConfirmation({ element, document });
  return { element, document, transport: createSiteAssistantTransport({}, { onToolConfirmation: showConfirmation }), agentId: 'site-assistant',
    suggestions: [t('What can I find on this site?'), t('Show me the latest posts')],
    directiveEventName: 'client_directive', ids: () => crypto.randomUUID(), createAbortController: () => new AbortController(),
    session: {
      load: () => loadSiteAssistantState(), save: ({ state }: { state: ReturnType<typeof loadSiteAssistantState> }) => saveSiteAssistantState(state),
      clear: () => clearSiteAssistantState(), enqueue: ({ action }: { action: unknown }) => enqueuePageAction(action), drain: () => drainQueuedPageAction(),
    },
    pageActions: {
      allows: allowsSitePageAction,
      navigate: ({ action }: { action: Extract<PageAction, { type: 'navigate' }> }) => {
        if (!allowsSitePageAction({ action })) return false;
        assign({ path: action.target.path }); return true;
      },
      execute: ({ action }: { action: Exclude<PageAction, { type: 'navigate' }> }) => {
        if (!allowsSitePageAction({ action })) return false;
        const target = findTargetElement(action.target.title);
        if (!target) return false;
        scrollToElement(target); if (action.type === 'highlight') applyHighlight(target); return true;
      },
      clearHighlight: () => clearHighlight(),
    },
    scheduleFrame: ({ callback }: { callback: () => void }) => {
      const handle = requestAnimationFrame(callback); return () => cancelAnimationFrame(handle);
    },
    renderMarkdown: ({ content, element: target }: { content: string; element: HTMLElement }) => {
      // micromark is already installed in this host. Defaults escape raw HTML and reject unsafe
      // protocols; never enable allowDangerousHtml or allowDangerousProtocol for visitor replies.
      // Footnotes are disabled: per-message IDs otherwise collide and expose an unstyled sr-only heading.
      const template = document.createElement('template');
      template.innerHTML = micromark(content, { extensions: [gfm(), { disable: { null: ['gfmFootnoteDefinition', 'gfmFootnoteCall', 'gfmPotentialFootnoteCall'] } }], htmlExtensions: [gfmHtml()] });
      // Filter the detached fragment before insertion so an untrusted image never starts a request.
      const base = new URL(document.baseURI);
      for (const image of template.content.querySelectorAll<HTMLImageElement>('img')) {
        const source = image.getAttribute('src');
        if (!source) { image.remove(); continue; }
        try {
          const url = new URL(source, base);
          if (!['http:', 'https:'].includes(url.protocol) || url.origin !== base.origin) image.remove();
        } catch { image.remove(); }
      }
      target.replaceChildren(template.content);
      for (const link of target.querySelectorAll<HTMLAnchorElement>('a[href]')) link.rel = 'noopener noreferrer';
    },
    copy: { title: t('Ask this site'), fabLabel: t('Chat with this site'), placeholder: t("Ask about this site's posts and pages…"),
      greeting: t('Ask about posts, pages or docs on this site.'), suggestionsLabel: t('Example prompts'),
      send: t('Send'), stop: t('Stop run'), close: t('Close chat'), reset: t('New thread'), resetQuestion: t('Discard chat?'), confirm: t('Discard chat'), confirmDraft: t('Discard draft'), keep: t('Cancel'),
      proposalGo: 'Go there', proposalLabel: ({ title }: { title: string }) => `Go to “${title}”?`, thinking: 'Replying…' },
  };
}

/** Called by the build-only entry after Jini has been built; no unbuilt export enters the dev graph. */
export function mountSiteVanillaChat({ mount }: { mount: (args: ReturnType<typeof createSiteVanillaArgs>, options: { initialOpen: boolean }) => {
  controller: { send: (input: { text: string }) => Promise<unknown>; getState: (input: Record<string, never>) => { busy: boolean; error: string | null } };
} }, _options = {}): void {
  const element = document.getElementById('tovu-site-assistant-root');
  if (!element) return;
  const widget = mount(createSiteVanillaArgs({ element }), { initialOpen: element.dataset.chatOpen === 'true' || loadSiteAssistantState().open });
  installSiteChatComparisonSend({ root: element, send: async ({ text }) => {
    if (widget.controller.getState({}).busy) throw new Error('This pane is already replying.');
    await widget.controller.send({ text });
    const error = widget.controller.getState({}).error;
    if (error) throw new Error(error);
  } });
}

/**
 * @file ADR-049 Decision 5: probe the full `@jini-ai/agent-runtime` AGENT_DEFS registry.
 * Every def reports its own availability and diagnostic, preventing a picker from offering a CLI
 * whose run would fail. The host owns discovery, timeouts, caching and PATH/environment policy;
 * the transport serializes safe summaries.
 *
 * PATH probing performs filesystem I/O. Cache it across session-lifetime health polls because
 * installed CLIs do not change each turn; explicit rescan refreshes that fact.
 */
import { AGENT_DEFS, detectAgents, probeAgentModels, type DetectedAgent, runtimeSupportsExternalTools, runtimeSupportsSubagents, runtimeSupportsChromeIntegration, createNativeAgentRuntime, type NativeAgentRuntime } from "@jini-ai/agent-runtime";
import { createCliProbeCache } from "./cli-probe-cache.js";
import { MODEL_NEGATIVE_TTL_MS } from "@jini-ai/agent-runtime/model-discovery";
import type { AgentSummary } from "@jini-ai/daemon/http";

/**
 * `AgentSummary` plus one extra, Tovu-only field the shared `@jini-ai/daemon/http` wire type doesn't
 * declare — added here rather than upstream because it is a Tovu-side transport decision
 * (`assistant-transport.ts`'s prompt-assembly gate), not a `@jini-ai/daemon/http` transport concern.
 * The extra key rides the same JSON body `AgentSummary` already serializes to; a consumer that only
 * knows `AgentSummary` (e.g. `@jini-ai/chat`'s `ChatPaneAgent`) simply never reads it.
 *
 * @see {@link probeAssistantAgents} for where `carriesOwnMemory` is derived.
 */
export type AssistantAgentSummary = AgentSummary & {
  readonly discoveryPending?: boolean;
  /** Structural bridge until @jini-ai/agent-runtime publishes declarative failure hints. */
  readonly failureHints?: readonly {
    readonly category: "auth" | "unsupported-client";
    readonly patterns: readonly string[];
    readonly hint: string;
    readonly suggestedAgentId?: string;
  }[];
  /**
   * True when this def's own CLI/ACP session already carries its multi-turn conversation memory
   * across spawns — the client-safe projection of `@jini-ai/agent-runtime`'s
   * `resumesSessionViaCli`/`resumesSessionViaAcpLoad` (`types.ts`), whose own doc says a caller
   * "should skip resending the rendered transcript on follow-up turns and send just the latest user
   * message" for such a def. `apps/admin/src/lib/assistant-transport.ts`'s `startRun` reads this to
   * decide whether a turn needs the full transcript or just the newest message.
   */
  readonly carriesOwnMemory: boolean;
  /** The runtime has a native subagent tool (`@jini-ai/agent-runtime`'s `runtimeSupportsSubagents`);
   *  the admin hides the "Prefer subagents" preference for a runtime without one. */
  readonly supportsSubagents: boolean;
  /** The runtime honors Claude in Chrome (`runtimeSupportsChromeIntegration`); the admin hides the
   *  "Use Claude in Chrome" preference for a runtime without it. */
  readonly supportsClaudeInChrome: boolean;
};

/** Tovu projections and background inventory lifecycle bound to one native runtime. */
export interface AssistantAgentInventory {
  readonly runtime: NativeAgentRuntime;
  readonly listDetectedAssistantAgents: typeof listDetectedAssistantAgents;
  readonly assistantAgentDiscoveryPending: typeof assistantAgentDiscoveryPending;
  readonly listAssistantAgents: typeof listAssistantAgents;
  readonly rescanAssistantAgents: typeof rescanAssistantAgents;
  dispose(required: Record<string, never>, optional?: Record<string, never>): Promise<void>;
}

/** Defs the executor cannot drive stay out of the picker. Keep this list aligned with the
 * runtime's compatibility rules; its compatibility predicate is not publicly exported. */
const UNSUPPORTED_AGENT_IDS = new Set<string>([]);

/**
 * Test port for one available def's model list — `@jini-ai/agent-runtime`'s `probeAgentModels`, which runs
 * the def's own `fetchModels`/`listModels` (e.g. `claude`'s credential-free `initialize` probe,
 * `codex debug models`) and falls back to `fallbackModels` on any failure. Live discovery keeps
 * the Local CLI picker current. Swappable so tests never spawn real CLIs.
 */
type AgentModelProber = typeof probeAgentModels;
/** The agent-def registry an inventory projects; `AGENT_DEFS` unless a host/test injects one. A def
 * may carry the Tovu-side `failureHints` bridge (see {@link AssistantAgentSummary}). */
export type AssistantAgentDefs = readonly ((typeof AGENT_DEFS)[number] & Pick<AssistantAgentSummary, "failureHints">)[];
let agentModelProber: AgentModelProber | null = null;

/** Compatibility test wrapper: install a fake model prober (or `null` to restore the real one)
 * and replace the default inventory. Native host inventories keep their own bindings. */
export function setAgentModelProberForTesting(prober: AgentModelProber | null): void {
  agentModelProber = prober;
  defaultInventory = createAssistantAgentInventory({ runtime: createNativeAgentRuntime({ env: process.env }) });
}

/**
 * The actual probe — one PATH check per `AGENT_DEFS` entry, plus one model-listing call per
 * AVAILABLE def, plus its version/capability/auth checks. Never called directly by a route; only through
 * {@link listAssistantAgents}/{@link rescanAssistantAgents} below, which own when it re-runs.
 * `force` bypasses Jini's catalog cache on rescan; structured default evidence travels with
 * the catalog so the picker can show and dispatch the same concrete model.
 *
 * @complexity Time: O(d) in `AGENT_DEFS.length` (24 today): a PATH walk each, and for installed
 * defs read-only metadata processes bounded by each def's timeout and the shared process queue. Space: O(d).
 * @overallScore 100
 */
async function probeAssistantAgents({ force = false }: { force?: boolean } = {}, { modelProber = agentModelProber, runtime, defs = AGENT_DEFS }: { modelProber?: AgentModelProber | null; runtime: NativeAgentRuntime; defs?: AssistantAgentDefs }): Promise<DetectedAgent[]> {
  // The full detector owns version, capabilities, auth and models. Both HTTP inventories share
  // this result instead of launching a separate model-only sweep for the chat picker.
  if (!modelProber) return runtime.detectAgents({}, { force });
  const results: DetectedAgent[] = [];
  for (const def of defs.filter((candidate) => !UNSUPPORTED_AGENT_IDS.has(candidate.id))) {
    const launch = runtime.resolveAgentLaunch({ def });
    const modelResult = launch.launchPath
      ? await modelProber({ def }, { force, state: runtime.state, env: runtime.hostEnv })
      : { models: def.fallbackModels, source: "fallback" as const };
    results.push(toDetectedAgent({ def, launch, modelResult }));
  }
  return results;
}

/** One prober-path detection result: availability from the resolved launch, models from the probe.
 * Split out of {@link probeAssistantAgents} purely to keep it under the shop complexity ceiling.
 * @complexity O(1). */
function toDetectedAgent({ def, launch, modelResult }: {
  def: AssistantAgentDefs[number];
  launch: ReturnType<NativeAgentRuntime["resolveAgentLaunch"]>;
  modelResult: Awaited<ReturnType<AgentModelProber>>;
}): DetectedAgent {
  return { ...def, available: Boolean(launch.launchPath), models: modelResult.models,
    modelsSource: modelResult.source, ...(launch.selectedPath ? { path: launch.selectedPath } : {}),
    ...(modelResult.catalog ? { modelCatalog: modelResult.catalog } : {}),
    ...(modelResult.defaultModelResolution ? { defaultModelResolution: modelResult.defaultModelResolution } : {}) };
}

/** The same projection serves cheap PATH-only snapshots and completed live discovery. */
function projectAssistantAgent({ def, launch, modelResult }: {
  def: AssistantAgentDefs[number];
  launch: { launchPath?: string; diagnostic?: string };
  modelResult: Awaited<ReturnType<AgentModelProber>>;
}): AssistantAgentSummary {
  const available = Boolean(launch.launchPath);
  const { failureHints } = def;
  const { models, source, catalog, defaultModelResolution } = modelResult;
  return {
    id: def.id,
    name: def.name,
    ...(failureHints ? { failureHints } : {}),
    available,
    supportsCustomModel: def.supportsCustomModel,
    models,
    modelsSource: source,
    ...(catalog ? { modelCatalog: catalog } : {}),
    ...(defaultModelResolution ? { defaultModelResolution } : {}),
    ...(def.supportsConcreteModelSelection !== undefined ? { supportsConcreteModelSelection: def.supportsConcreteModelSelection } : {}),
    // See `runtimeSupportsExternalTools`'s own doc (`@jini-ai/agent-runtime`'s `registry.ts`):
    // the single derivation point for "can this runtime receive Tovu/Jini tools at all,"
    // keyed off the def's own `externalMcpInjection` declaration rather than a hardcoded
    // runtime-id list here.
    supportsTools: runtimeSupportsExternalTools({ def }),
    // See `AssistantAgentSummary.carriesOwnMemory`'s own doc — either resume mechanism means
    // the CLI itself, not this transport, owns the def's multi-turn memory.
    carriesOwnMemory: Boolean(def.resumesSessionViaCli) || Boolean(def.resumesSessionViaAcpLoad),
    supportsSubagents: runtimeSupportsSubagents({ def }),
    supportsClaudeInChrome: runtimeSupportsChromeIntegration({ def }),
    ...(def.reasoningOptions ? { reasoningOptions: def.reasoningOptions } : {}),
    ...(available ? {} : { diagnostic: launch.diagnostic ?? `${def.name} CLI not found on PATH` }),
  };
}

/** The runtime owns discovery; this host owns the shared snapshot consumed by both HTTP routes.
 * An injected detector supplies an isolated inventory for embedding hosts and route tests; injected
 * `defs` (default: the runtime's own `AGENT_DEFS`) is the registry both the cheap PATH-only snapshot
 * and the projection read from, so a host or test can supply a def shape Jini does not ship yet. */
export function createAssistantDetectionCache(
  { detector, runtime = createNativeAgentRuntime({ env: process.env }), defs = AGENT_DEFS }: { detector?: typeof detectAgents; runtime?: NativeAgentRuntime; defs?: AssistantAgentDefs },
  _options: Record<string, never> = {},
) {
  const modelProber = agentModelProber;
  const detect: typeof detectAgents = detector ?? ((_input, options = {}) => probeAssistantAgents({ ...(options.force !== undefined ? { force: options.force } : {}) }, { modelProber, runtime, defs }));
  return createCliProbeCache({
    initial: (): DetectedAgent[] => defs.filter((def) => !UNSUPPORTED_AGENT_IDS.has(def.id)).map((def) => {
      const launch = runtime.resolveAgentLaunch({ def });
      return { ...def, available: Boolean(launch.launchPath), models: def.fallbackModels.filter(model => model.id !== "default"),
        modelsSource: "fallback", ...(launch.selectedPath ? { path: launch.selectedPath } : {}) };
    }),
    probe: ({ force }) => detect({}, { force }),
  }, {
    retryAfterMs: MODEL_NEGATIVE_TTL_MS,
    // Catalogs own their retry/refresh lifetimes; executable detection stays cached in Jini.
    expiresAt: ({ snapshot }) => Math.min(Infinity, ...snapshot.flatMap(agent =>
      agent.available && agent.modelCatalog ? [Date.parse(agent.modelCatalog.expiresAt)] : [])),
  });
}
/** Tovu's picker and settings projection over one host-owned Jini runtime.
 * @param required - The runtime created by the native composition root, plus an optional detector.
 * @returns One inventory shared by both HTTP surfaces, with cleanup after background scans settle.
 * @example const inventory = createAssistantAgentInventory({ runtime });
 */
export function createAssistantAgentInventory(
  { runtime, detector, defs = AGENT_DEFS }: { runtime: NativeAgentRuntime; detector?: typeof detectAgents; defs?: AssistantAgentDefs },
  _optional: Record<string, never> = {},
): AssistantAgentInventory {
  const cachedAgents = createAssistantDetectionCache({ runtime, defs, ...(detector ? { detector } : {}) });
  let projectedSource: Promise<DetectedAgent[]> | undefined;
  let projectedPending = false;
  let projectedAgents: Promise<AssistantAgentSummary[]> | undefined;

  /** Admin detection and the chat picker read one settled inventory. No request waits for probes. */
  function listDetectedAssistantAgents({ force = false }: { force?: boolean } = {}, _options = {}): Promise<DetectedAgent[]> {
    return cachedAgents.read({ force });
  }

  function assistantAgentDiscoveryPending(_input = {}, _options = {}): boolean { return cachedAgents.isPending({}); }

  /** Preserve promise identity until the runtime snapshot changes, including while a scan runs. */
  function listAssistantAgents(_input = {}, { waitForProbe = false } = {}): Promise<AssistantAgentSummary[]> {
    const source = listDetectedAssistantAgents();
    if (waitForProbe) return cachedAgents.settled({}).then(() => listAssistantAgents());
    const discoveryPending = cachedAgents.isPending({});
    if (source !== projectedSource || discoveryPending !== projectedPending) {
      projectedPending = discoveryPending;
      projectedSource = source;
      projectedAgents = source.then(agents => agents.map(agent => {
        const registered = defs.find(candidate => candidate.id === agent.id)!;
        const def = { ...registered, ...(agent.reasoningOptions ? { reasoningOptions: agent.reasoningOptions } : {}) };
        return { ...projectAssistantAgent({ def, launch: { launchPath: agent.available ? agent.path : undefined }, modelResult: {
          models: agent.models, source: agent.modelsSource,
          ...(agent.modelCatalog ? { catalog: agent.modelCatalog } : {}),
          ...(agent.defaultModelResolution ? { defaultModelResolution: agent.defaultModelResolution } : {}),
        } }), discoveryPending,
          ...(agent.version ? { version: agent.version } : {}),
          ...(agent.authStatus ? { authStatus: agent.authStatus } : {}),
        };
      }));
    }
    return projectedAgents!;
  }

  /** Explicit Rescan schedules a forced refresh while retaining the previous inventory.
   * The optional completion port is for diagnostics/tests; HTTP never opts into waiting. */
  function rescanAssistantAgents(_input = {}, { waitForProbe = false } = {}): Promise<AssistantAgentSummary[]> {
    listDetectedAssistantAgents({ force: true });
    return waitForProbe ? cachedAgents.settled({}).then(() => listAssistantAgents()) : listAssistantAgents();
  }

  return { runtime, listDetectedAssistantAgents, assistantAgentDiscoveryPending, listAssistantAgents, rescanAssistantAgents,
    /** Dispose only after the host stops admitting requests; a pending scan finishes before cache clear. */
    async dispose(_required: Record<string, never>, _optional: Record<string, never> = {}): Promise<void> {
      await cachedAgents.settled({});
      await runtime.dispose({});
    },
  };
}

// Published process-level functions remain compatibility wrappers; native hosts create inventories.
let defaultInventory = createAssistantAgentInventory({ runtime: createNativeAgentRuntime({ env: process.env }) });
export function listDetectedAssistantAgents(input: { force?: boolean } = {}, options = {}): Promise<DetectedAgent[]> {
  return defaultInventory.listDetectedAssistantAgents(input, options);
}
export function assistantAgentDiscoveryPending(input = {}, options = {}): boolean {
  return defaultInventory.assistantAgentDiscoveryPending(input, options);
}
export function listAssistantAgents(input = {}, options: { waitForProbe?: boolean } = {}): Promise<AssistantAgentSummary[]> {
  return defaultInventory.listAssistantAgents(input, options);
}
export function rescanAssistantAgents(input = {}, options: { waitForProbe?: boolean } = {}): Promise<AssistantAgentSummary[]> {
  return defaultInventory.rescanAssistantAgents(input, options);
}

import { buildUIToolResult, type UIResource } from "./mcp-ui.js";

const HTML_MIME_TYPES: ReadonlySet<string> = new Set(["text/html", "text/html;profile=mcp-app", "text/html+skybridge"]);

/** Narrows the renderer's unknown package boundary without casting a required presentation port. */
export function isAskChoiceUiResource(ui: unknown): ui is UIResource {
  return isRecord(ui) && ui.type === "resource" && isRecord(ui.resource)
    && hasUiUri({ resource: ui.resource }) && hasHtmlText({ resource: ui.resource });
}

/** Any non-null object; properties are then read as unknown. A positional parameter because a type
 * predicate cannot name a destructured binding. */
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

/** The resource names a `ui://` URI. */
function hasUiUri({ resource }: { resource: Record<string, unknown> }): boolean {
  return typeof resource.uri === "string" && resource.uri.startsWith("ui://");
}

/** The resource carries HTML text in one of the MCP-UI HTML mime types. */
function hasHtmlText({ resource }: { resource: Record<string, unknown> }): boolean {
  return typeof resource.mimeType === "string" && HTML_MIME_TYPES.has(resource.mimeType) && typeof resource.text === "string";
}

/** The ask-choice tool result for a rendered form; the renderer's output crosses an unknown package boundary.
 * @throws Error when the renderer returned anything other than an HTML `ui://` resource. @complexity O(1). */
export function askChoiceToolResult({ modelText, ui }: { modelText: string; ui: unknown }, _options = {}) {
  if (!isAskChoiceUiResource(ui)) throw new Error("ask-choice renderer returned an invalid UI resource");
  return { ...buildUIToolResult({ modelText, ui }) };
}

import { type Clock } from "@jini-ai/core/primitives";
import { buildVaultAad, type SecretsVaultService, VaultError, type VaultContext, type VaultRecord, type VaultRepoPort } from "@jini-ai/platform/secrets/credential-sets";
import type { KeyringPort, SecretSealerPort } from "../features/webhooks/index.js";
import { credentialTokenHint, type CredentialTokenHint } from "../contracts/core/credential-token.js";
import { createTovuStoreVault, parseTovuStoreMeta } from "#src/platform/secrets/vault-kinds";

export type AssistantVaultRepo = VaultRepoPort & { findOne: NonNullable<VaultRepoPort["findOne"]> };

/** Compatibility adapters expose their Jini persistence port without changing the public stores.
 * Missing capabilities fail closed; there is no parallel legacy persistence/crypto path. */
export function assistantVaultRepo({ repo }: { repo: object }, _options = {}): AssistantVaultRepo {
  if (!("vault" in repo)) throw new VaultError({ code: "invalid-record" });
  const vault = repo.vault as VaultRepoPort | undefined;
  if (!vault?.findOne) throw new VaultError({ code: "invalid-record" });
  return vault as AssistantVaultRepo;
}

/** Tovu singleton ownership matches the pinned migration; personal scope comes from the session. */
export function assistantVaultContext({ workspaceId, kind, principalId = null }: {
  workspaceId: string; kind: "site-assistant" | "personal-execution"; principalId?: string | null;
}, _options = {}): VaultContext {
  return { workspaceId, kind, ownerKey: "tovu", principalId, binding: null };
}

/** Matches the migration's singleton ID shape; concurrent creates contend on one CAS key. */
export function assistantVaultId({ context }: { context: VaultContext }, _options = {}): string {
  return `vault:${JSON.stringify([context.kind, context.principalId])}`;
}

/** Bind Jini's lifecycle to one already-authorized feature scope. Routes remain permission owners.
 * Crypto failures alone map to the feature's unconfigured error; persistence/CAS errors retain
 * their own contract. Read-only calls cannot accidentally derive a key or seal a payload. */
export function createAssistantVault({ repo, context, sealer, keyring, clock }: {
  repo: VaultRepoPort; context: VaultContext; sealer?: SecretSealerPort; keyring?: KeyringPort; clock?: Clock;
}, { onSealFailure }: { onSealFailure?: (error: unknown) => never } = {}): SecretsVaultService {
  const unavailable = (): Promise<never> => Promise.reject(new VaultError({ code: "invalid-record" }));
  if (context.kind !== "site-assistant" && context.kind !== "personal-execution") throw new VaultError({ code: "context" });
  return createTovuStoreVault({ repo: { vault: repo }, kind: context.kind, context, keyring, clock,
    sealer: sealer ?? { seal: unavailable, open: unavailable },
    storageError: error => {
      if (onSealFailure) onSealFailure(error);
      return error instanceof Error ? error : new VaultError({ code: "invalid-record" });
    },
    newId: () => assistantVaultId({ context }),
  });
}

/** Read metadata once and open that exact snapshot through Jini. A failed open removes the hint
 * while retaining settings, and concurrent rotation cannot mix old settings with a new key.
 * @complexity One indexed singleton read and at most one open, O(payload size) memory. */
export async function readAssistantVault({ repo, context, sealer }: {
  repo: VaultRepoPort; context: VaultContext; sealer?: SecretSealerPort;
}, { record: supplied }: { record?: VaultRecord } = {}): Promise<{ record: VaultRecord | null; tokenHint: CredentialTokenHint | null }> {
  if (!repo.findOne) throw new VaultError({ code: "invalid-record" });
  const raw = supplied ?? await repo.findOne(context);
  if (!raw) return { record: null, tokenHint: null };
  if (buildVaultAad({ ...context, id: raw.id }) !== buildVaultAad(raw)) throw new VaultError({ code: "context" });
  const record = { ...raw, meta: parseTovuStoreMeta({ kind: context.kind as "site-assistant" | "personal-execution", meta: raw.meta }) };
  return { record, tokenHint: record.sealed && sealer ? await openTokenHint({ repo, context, sealer, record }) : null };
}

/** Open exactly the supplied snapshot through Jini and derive its token hint.
 * @returns null when the payload has no string apiKey or the envelope cannot be opened.
 * @complexity One open, O(payload size) memory; never reads the repository again. */
async function openTokenHint({ repo, context, sealer, record }: {
  repo: VaultRepoPort; context: VaultContext; sealer: SecretSealerPort; record: VaultRecord;
}, _options = {}): Promise<CredentialTokenHint | null> {
  // This port only serves get's identity read; every other operation remains with the owner.
  const snapshot: VaultRepoPort = Object.create(repo);
  snapshot.find = async () => record;
  try {
    const opened = await createAssistantVault({ repo: snapshot, context, sealer }).get({ ...context, id: record.id });
    return typeof opened?.payload?.apiKey === "string" ? credentialTokenHint({ token: opened.payload.apiKey }) : null;
  } catch { /* Site-key rotation must not prevent reading settings. */ return null; }
}

/**
 * @file Pure mapping between free-form model output and BYOK meta-tool results, split out of
 * `byok-tool-surface.ts` so every branch can be asserted directly: argument-bag guards, the
 * `execute_delegated_tool` input normalizer, tool-output rendering (JSON string vs. image content
 * blocks), and the `ToolExecutor` status-to-message map. No I/O and no registry access here.
 */
import type { ToolExecutor } from "@jini-ai/daemon";

import type { ByokToolResultBlock } from "./byok-provider-turn.js";

/** What one meta-tool call resolves to — deliberately the exact `{content, isError?}` shape
 *  `byok-provider-turn.ts`'s `ByokToolExecutor` contract returns, so the route hands this straight
 *  back to the provider adapter with no second mapping layer of its own. */
export interface ByokMetaToolResult {
  readonly content: string | readonly ByokToolResultBlock[];
  readonly isError?: boolean;
}

/** True for the meta-tool argument bags this dispatch accepts — a model can emit anything, including
 *  `null` or a bare string, and every read below has to survive that. */
export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** A model-readable refusal: `content` is the message, flagged `isError` so the provider shows it as a failed call. */
export function err(content: string): ByokMetaToolResult {
  return { content, isError: true };
}

/** One MCP content block as a provider block, or `null` for anything outside the text/image whitelist. */
function toResultBlock(required: { readonly block: unknown }): ByokToolResultBlock | null {
  const { block } = required;
  if (!isRecord(block)) return null;
  if (block.type === "text" && typeof block.text === "string") return { type: "text", text: block.text };
  if (block.type === "image" && typeof block.mimeType === "string" && typeof block.data === "string") {
    return { type: "image", mimeType: block.mimeType, data: block.data };
  }
  return null;
}

/**
 * The output's content blocks when it is an MCP content envelope (`{content: [...]}`) of only `text`
 * and `image` blocks with at least one image — so a picture a tool returns (e.g.
 * `media_view_image`) reaches the provider as an image, not as base64 inside a JSON
 * string. Anything else, including a text-only envelope, returns `null` and keeps the JSON-string
 * contract every other tool relies on. Whitelist, like `@jini-ai/mcp`'s `okResult()`: one unknown
 * block type and the whole output stays a string.
 *
 * @complexity O(blocks).
 */
function imageContentBlocksOf(output: unknown): ByokToolResultBlock[] | null {
  if (!isRecord(output) || !Array.isArray(output.content)) return null;
  const blocks: ByokToolResultBlock[] = [];
  for (const raw of output.content as unknown[]) {
    const block = toResultBlock({ block: raw });
    if (!block) return null;
    blocks.push(block);
  }
  return blocks.some((block) => block.type === "image") ? blocks : null;
}

/** A successful tool output as the model sees it: image content blocks when {@link imageContentBlocksOf}
 *  admits them, the bare string for a string output, and JSON text (`null` for nothing) otherwise. */
export function ok(output: unknown): ByokMetaToolResult {
  const blocks = imageContentBlocksOf(output);
  if (blocks) return { content: blocks };
  return { content: typeof output === "string" ? output : JSON.stringify(output ?? null) };
}

/**
 * Normalizes `execute_delegated_tool`'s `input` argument into what a tool handler accepts.
 *
 * Three shapes are allowed in, deliberately: an object (the declared contract), absent/null (a tool
 * that takes no input), and a JSON-encoded object string. The last is not sloppiness — see the
 * `input` schema comment in `byok-tool-surface.ts`'s `META_TOOL_DESCRIPTORS`: it is a real, observed provider behavior whose failure mode is every
 * input-taking tool silently becoming uncallable. A string that does not parse, or parses to a
 * non-object, is refused with a message naming the problem rather than passed down to fail inside a
 * handler's own type check where the model would see a far less actionable error.
 */
export type DelegatedInputResolution =
  | { readonly ok: true; readonly input: unknown }
  | { readonly ok: false; readonly message: string };

/** The string-input branch of {@link resolveDelegatedInput}, split out purely to keep that function's
 *  cognitive complexity under the shop ceiling — see {@link DelegatedInputResolution}'s doc for why a
 *  JSON-encoded string has to be accepted here at all. */
function resolveDelegatedInputFromString(trimmed: string): DelegatedInputResolution {
  if (trimmed.length === 0) return { ok: true, input: undefined };
  try {
    const parsed: unknown = JSON.parse(trimmed);
    if (isRecord(parsed)) return { ok: true, input: parsed };
    return { ok: false, message: "'input' parsed as JSON but is not an object — send a JSON object of the tool's input fields." };
  } catch {
    return { ok: false, message: "'input' must be a JSON object of the tool's input fields, not a plain string." };
  }
}

/** See {@link DelegatedInputResolution} for the three accepted shapes and why. */
export function resolveDelegatedInput(raw: unknown): DelegatedInputResolution {
  if (raw === undefined || raw === null) return { ok: true, input: undefined };
  if (isRecord(raw)) return { ok: true, input: raw };
  if (typeof raw === "string") return resolveDelegatedInputFromString(raw.trim());
  return { ok: false, message: `'input' must be a JSON object of the tool's input fields, not ${Array.isArray(raw) ? "an array" : typeof raw}.` };
}

/** Maps one `ToolExecutor.execute` outcome onto the meta-tool result shape — split out of
 *  `runExecuteDelegatedTool` so its per-case branching does not also count against that
 *  function's own complexity. */
export function mapToolExecutionResult(result: Awaited<ReturnType<ToolExecutor["execute"]>>, toolId: string): ByokMetaToolResult {
  switch (result.status) {
    case "completed":
      return ok(result.output);
    case "denied":
      return err(`tool "${toolId}" was denied for this caller`);
    case "confirmation-denied":
      return err(`tool "${toolId}" requires human confirmation, which BYOK mode cannot supply yet`);
    case "timed-out":
      return err(`tool "${toolId}" timed out`);
    case "cancelled":
      return err(`tool "${toolId}" was cancelled`);
    case "failed":
      return err(result.error ?? `tool "${toolId}" failed`);
  }
}

