/** `content_read.<resource>` — the card id a caller/model actually names. */
function contentReadToolId(resource: string): string {
  return `content_read.${resource}`;
}

/**
 * **The single authority for "what id serves this capability now."** Every retired Tier-1 read tool
 * id -> the `content_read.<resource>` card that took over for it, derived from
 * {@link CONTENT_READ_CARDS} itself rather than hand-listed, so it cannot drift from what actually
 * ships.
 *
 * Exists because the collapse invalidated ground truth in several retrieval eval suites at once: a
 * suite whose expected id is `comments_list_moderation_queue` scores a retrieval that correctly
 * returned `content_read.comment_moderation_queue` as a MISS, manufacturing a regression that is not
 * real. The capability did not go away — only its id changed — so the honest fix is to resolve
 * expected ids through here.
 *
 * Deliberately ONE export rather than a mapping table copied into each suite: nine private copies is
 * nine things to forget the next time a tool id is retired, and stranded references surviving a
 * retirement is the exact failure this whole exercise exists to clean up.
 *
 * NOTE this is a *read-side* alias map only. It does NOT belong in `TOOL_SEARCH_KEYWORDS` /
 * `DOC2QUERY` lookups: those are keyed by the MEMBER id on purpose, because {@link cardDescription}
 * folds each member's own vocabulary into the card's indexed text by that key. Re-keying them onto
 * card ids would delete that vocabulary from the index — which is precisely the vocabulary the
 * measured retrieval parity depends on.
 */
export const RETIRED_READ_TOOL_TO_CARD: ReadonlyMap<string, string> = new Map(
  CONTENT_READ_CARDS.flatMap((card) => {
    const cardId = contentReadToolId(card.resource);
    return [card.get?.toolId, card.list?.toolId]
      .filter((memberId): memberId is string => memberId !== undefined)
      .map((memberId) => [memberId, cardId] as const);
  }),
);

/**
 * Resolves a possibly-retired read tool id to the id that actually ships today; any other id is
 * returned unchanged, so a caller can pass every expected id through it unconditionally.
 *
 * @complexity O(1).
 */
export function currentToolIdFor(toolId: string): string {
  return RETIRED_READ_TOOL_TO_CARD.get(toolId) ?? toolId;
}

/** One card id repeated in a list ("X, X, or Y", "X or X", "X/X") once two retired members of the
 *  same card both resolve to it. */
const REPEATED_CARD_ID_PATTERN = /(content_read\.[a-z_]+)(?:(?:\s*,\s*|\s+or\s+|\s+and\s+|\s*\/\s*)\1\b)+/g;

/** Applies `rewriteText` to every string `description` in a JSON schema.
 *  @complexity O(n) in the schema size. */
function rewriteSchemaDescriptions(value: unknown, rewriteText: (text: string) => string): unknown {
  if (Array.isArray(value)) return value.map((child) => rewriteSchemaDescriptions(child, rewriteText));
  if (typeof value !== "object" || value === null) return value;
  return Object.fromEntries(
    Object.entries(value).map(([key, child]) => [key, key === "description" && typeof child === "string" ? rewriteText(child) : rewriteSchemaDescriptions(child, rewriteText)]),
  );
}

/**
 * Builds the rewrite that points every retired read tool id in a registration's description and
 * input-schema descriptions at the card that serves it now.
 *
 * Package-owned catalogs (menus, media, identity, ...) still say "the menu's id, as returned by
 * menus_list_menus" — true in a host that does not collapse reads, but in this one those ids no
 * longer exist and a model told to call them finds nothing. The
 * collapse is THIS host's decision, so the rewrite lives here rather than in each package. Only the
 * plain text before {@link KEYWORD_MARKER} is rewritten: the indexed tail is keyed vocabulary, not
 * prose, and must stay exactly what the retrieval measurements scored.
 *
 * @param required.retiredIds the member ids this collapse actually retired. A member whose card was
 *        skipped (not every member present) still ships under its own id and must keep its name.
 * @returns a function returning the registration unchanged (same object) when nothing mentions a
 *          retired id, else a copy with the rewritten descriptor.
 * @complexity O(r) to build; O(n) per registration in its descriptor size.
 */
export function createRetiredReadToolIdRewriter(required: { retiredIds: ReadonlySet<string> }): (registration: ToolRegistration) => ToolRegistration {
  if (required.retiredIds.size === 0) return (registration) => registration;
  // Whole words only: `\b` stops `content_post_get` matching inside a longer id.
  const retiredIdPattern = new RegExp(`\\b(${[...required.retiredIds].join("|")})\\b`, "g");
  const rewriteText = (text: string): string => {
    const markerAt = text.indexOf(KEYWORD_MARKER);
    const plain = markerAt === -1 ? text : text.slice(0, markerAt);
    const tail = markerAt === -1 ? "" : text.slice(markerAt);
    return plain.replace(retiredIdPattern, (id) => currentToolIdFor(id)).replace(REPEATED_CARD_ID_PATTERN, "$1") + tail;
  };
  return (registration) => {
    const description = registration.descriptor.description === undefined ? undefined : rewriteText(registration.descriptor.description);
    const inputSchema = rewriteSchemaDescriptions(registration.descriptor.inputSchema, rewriteText) as typeof registration.descriptor.inputSchema;
    if (description === registration.descriptor.description && JSON.stringify(inputSchema) === JSON.stringify(registration.descriptor.inputSchema)) return registration;
    return { ...registration, descriptor: { ...registration.descriptor, description, inputSchema } };
  };
}

/** Every wired tool in this codebase publishes a real `inputSchema` (`buildDomainRegistrations`
 *  refuses to wire one that does not), so this is a type-satisfying fallback only, never expected
 *  to actually apply — typed explicitly because a bare `{}` literal has no index signature. */
const EMPTY_SCHEMA: Readonly<Record<string, unknown>> = {};

/**
 * Whether EVERY member tool a card names is actually present in this composition's built
 * registration set.
 *
 * A narrow/partial composition is ordinary, not an error: many existing tests build an isolated
 * registry holding only ONE domain's contributor (`resetToolContributorsForTests()` plus a single
 * `registerToolContributor(contribute<Domain>Tools())`) and call `buildAssistantToolRegistrations`
 * directly to exercise that domain alone. Such a composition legitimately has no
 * `backup_list_restore_points` at all when it is testing Post, say — that is not catalog drift, it
 * is the test's own deliberate scope. A card whose members are not all present is simply left
 * un-collapsed for that composition: its member tool(s) pass through under their ORIGINAL id(s),
 * completely unaffected by this file, exactly as they did before this file existed. Only the one
 * real production composition (`installFirstPartyToolContributors()`, all ~30 domains) ever has
 * every member of every card present, so only there do all 29 cards actually get built — which is
 * the composition the measured retrieval numbers describe.
 *
 * @complexity O(1) per member, O(m) per card (m <= 2).
 */
function cardIsAvailable(byId: ReadonlyMap<string, ToolRegistration>, card: ContentReadCard): boolean {
  return (!card.get || byId.has(card.get.toolId)) && (!card.list || byId.has(card.list.toolId));
}

/**
 * Looks up one already-built source registration by its ORIGINAL tool id.
 *
 * Callers only ever pass a `toolId` a prior {@link cardIsAvailable} check already confirmed is
 * present, so an absent id here is a genuine internal-invariant break — the two checks disagreeing
 * — not a normal "this composition doesn't include that domain" case.
 *
 * @throws {Error} If `toolId` is absent from `sourceRegistrations` despite `cardIsAvailable` having
 * confirmed it. This can only fire from a bug in this file, never from a caller's input or from a
 * narrow test composition.
 * @complexity O(1) against the pre-indexed map the caller builds once.
 */
function sourceRegistration(byId: ReadonlyMap<string, ToolRegistration>, toolId: string): ToolRegistration {
  const found = byId.get(toolId);
  if (!found) {
    throw new Error(`content-read-tool.ts: internal error — '${toolId}' passed cardIsAvailable but is missing from byId`);
  }
  return found;
}

/**
 * **The one shared handler factory** every merged (get+list) card wires through. Dispatches to
 * `get` when the caller supplied `idProperty`, to `list` otherwise — both branches invoke the
 * ORIGINAL, already-shipped handler completely unchanged, including its own input validation and
 * its own permission enforcement (see this file's header for why that is sufficient).
 *
 * `value !== undefined` rather than a stricter non-empty-string check: an empty-string id is left
 * for the underlying `get` handler's own `requireString` to reject with its own message, rather
 * than this wrapper inventing a second, possibly-inconsistent validation error.
 * A batch-enabled get owns `items` before id dispatch: its existing wrapper validates the batch
 * and runs each item through get, so a missing item id fails instead of disclosing a whole list.
 *
 * @complexity O(1) plus whichever branch's own cost.
 */
function dispatchByIdPresence(
  { idProperty, get, list }: { idProperty: string; get: ToolHandler; list: ToolHandler },
  { batchGet = false }: { batchGet?: boolean } = {},
): ToolHandler {
  return async (ctx, options) => {
    const candidate = { value: ctx.input };
    if (batchGet && isRecord(candidate) && Object.hasOwn(candidate.value, "items")) return get(ctx, options);
    const value = isRecord(candidate) ? candidate.value[idProperty] : undefined;
    return value !== undefined ? get(ctx, options) : list(ctx, options);
  };
}

/** The value at `path` inside `item`, or `undefined` when any step is not a record. */
function valueAtPath(item: unknown, path: readonly string[]): unknown {
  let current: unknown = item;
  for (const key of path) {
    const candidate = { value: current };
    if (!isRecord(candidate)) return undefined;
    current = candidate.value[key];
  }
  return current;
}

/**
 * The `get` half of a {@link ListLookup} card: runs the list member's ORIGINAL handler — so its own
 * input validation and permission check run exactly as for a plain list call — with the id removed
 * from the input (several list readers refuse any input at all; the list's other filters still pass
 * through), then returns each source array filtered to the matching item plus declared context.
 *
 * Returning the list shape rather than a bare item keeps one view contract per resource and stays
 * honest if two families both match (plugins_list).
 *
 * @throws {ToolInputError} when the id is not a non-empty string, or when nothing matches (the
 *         message names how to list valid ids, or that a truncated list makes the miss inconclusive).
 * @throws {Error} when the list result lacks a declared source array — a shape drift in the list
 *         reader, which must not read as "not found".
 * @complexity O(n) in the listed items; one list call, no per-item I/O of its own.
 */
function lookupInList(required: { resource: string; listToolId: string; lookup: ListLookup; list: ToolHandler }, _options = {}): ToolHandler {
  const { resource, listToolId, lookup, list } = required;
  const cardId = contentReadToolId(resource);
  return async (ctx) => {
    const input = requireInputRecord({ input: ctx.input });
    const id = requireString({ input, key: lookup.idProperty });
    const listInput = Object.fromEntries(Object.entries(input).filter(([key]) => key !== lookup.idProperty));
    const listed = { value: await list({ ...ctx, input: listInput }) };
    if (!isRecord(listed)) throw new Error(`content-read-tool.ts: '${listToolId}' returned a non-object result`);

    const filtered: Record<string, unknown[]> = {};
    let matches = 0;
    for (const source of lookup.sources) {
      const items = listed.value[source.itemsKey];
      if (!Array.isArray(items)) {
        throw new Error(`content-read-tool.ts: '${listToolId}' result has no '${source.itemsKey}' array — the ${cardId} lookup is out of date`);
      }
      const matchingItems = items.filter((item) => valueAtPath(item, source.idPath) === id);
      filtered[source.itemsKey] = matchingItems;
      matches += matchingItems.length;
    }
    if (matches > 0) {
      const context = Object.fromEntries((lookup.contextKeys ?? [])
        .filter(key => Object.hasOwn(listed.value, key)).map(key => [key, listed.value[key]]));
      return { ...context, ...filtered };
    }

    throw new ToolInputError({
      message:
        listed.value.truncated === true
          ? `${resource} '${id}' was not found among the listed items, but ${cardId}'s list is truncated, so it may still exist`
          : `${resource} '${id}' was not found — call ${cardId} without id to list valid ids`,
    });
  };
}

/** The synthetic get-side schema a {@link ListLookup} card feeds {@link unionInputSchema}. */
function listLookupIdSchema(required: { resource: string; lookup: ListLookup; listSchema: Readonly<Record<string, unknown>> }, _optional: Record<string, never> = {}): Readonly<Record<string, unknown>> {
  const { resource, lookup, listSchema } = required;
  return {
    ...listSchema,
    type: "object",
    // Lookup still needs the list's context (for example themeId); both branches require it.
    required: [...((listSchema.required as readonly string[] | undefined) ?? []), lookup.idProperty],
    properties: {
      ...((listSchema.properties as Record<string, unknown> | undefined) ?? {}),
      [lookup.idProperty]: {
        type: "string",
        minLength: 1,
        description: `Fetch the one ${resource.replace(/_/g, " ")} with this id, as ${contentReadToolId(resource)} lists it.`,
      },
    },
  };
}

/**
 * A card's model-visible description: every member tool's OWN plain description, concatenated,
 * plus the exact id parameter guidance, followed by ONE {@link KEYWORD_MARKER} boundary and every member's combined keyword/doc2query
 * vocabulary (via `indexedDescriptionFor(id, "")`, which returns exactly that tail with no marker of
 * its own — see that function's own doc).
 *
 * Deliberately NOT `members.map(id => indexedDescriptionFor(id, plainDescOf(id))).join(" ")` (each
 * member's own already-marked text, naively concatenated) even though that is what the measured
 * eval arm literally computes and BM25 scores identically either way (same token bag, order-blind).
 * The reason to build it this way instead: {@link stripSearchKeywords} cuts a description at the
 * FIRST marker it finds. A naive per-member concatenation embeds a marker after the FIRST member
 * that happens to have a keyword entry, silently truncating every LATER member's plain prose from
 * what the model ever sees in `describe_tool` — invisible to the eval (which only scores the FTS
 * index, never the stripped/display text) but a real product bug for a merged card. Collecting every
 * member's plain text first and every member's tail second, with exactly one marker between them,
 * produces the SAME indexed token bag (so the measured retrieval numbers still apply) while keeping
 * the full, untruncated prose visible after stripping.
 *
 * @complexity O(m) in member count (at most 2).
 */
function cardDescription(
  { id, memberIds, byId, idDescription }: { id: string; memberIds: readonly string[]; byId: ReadonlyMap<string, ToolRegistration>; idDescription: string },
  _optional: Record<string, never> = {},
): string {
  const prose = [...memberIds.map((id) => sourceRegistration(byId, id).descriptor.description), idDescription,
    "content_read is a namespace, not a tool; call this exact tool id without a resource argument."].filter(Boolean).join(" ");
  const plain = `${id}: ${prose}`;
  const tail = memberIds
    .map((id) => indexedDescriptionFor(id, ""))
    .filter((part) => part.length > 0)
    .join(" ");
  return tail.length > 0 ? `${plain}${KEYWORD_MARKER}${tail}` : plain;
}

/** Put the exact id parameter name in both model-visible surfaces so generic "id" prose cannot
 * obscure it. The card publishes `id`; the source selector remains an ingress alias for 90 days
 * from release. Natural keys (labels, folder names, page names) keep their source meaning.
 * Copies only selector schema keys and descriptions; validation and dispatch stay with their owners.
 * @complexity O(p) time and space for p schema properties; no I/O or input mutation.
 */
function describeCardIdInput(
  { card, inputSchema }: { card: ContentReadCard; inputSchema: Readonly<Record<string, unknown>> },
  _optional: Record<string, never> = {},
): { inputSchema: Readonly<Record<string, unknown>>; idDescription: string } {
  const idProperty = card.get?.idProperty ?? card.listLookup?.idProperty;
  if (!idProperty || idProperty === "id") return { inputSchema, idDescription: "" };
  const idDescription = `id: the ${card.resource.replace(/_/g, " ")}'s selector, using the same value as legacy '${idProperty}' (accepted for 90 days from release).`;
  return { inputSchema: canonicalCardSchema({ inputSchema, idProperty }), idDescription };
}

/** Project the source selector to `id`, including a source-owned batch's item schema.
 * Other filters, required context and natural-key constraints are preserved verbatim.
 * @complexity O(p) time/space in the single and batch-item properties; no effects.
 */
function canonicalCardSchema(
  { inputSchema, idProperty }: { inputSchema: Readonly<Record<string, unknown>>; idProperty: string },
  _options = {},
): Readonly<Record<string, unknown>> {
  // A schema-less reader keeps its empty fallback: there is no selector to project.
  if (inputSchema.properties === undefined && inputSchema.required === undefined) return inputSchema;
  const properties = (inputSchema.properties as Readonly<Record<string, unknown>> | undefined) ?? EMPTY_SCHEMA;
  const projected = Object.fromEntries(Object.entries(properties).map(([key, value]) => [key === idProperty ? "id" : key, value]));
  const batch = properties.items as Readonly<Record<string, unknown>> | undefined;
  if (batch?.items) projected.items = { ...batch, items: canonicalCardSchema({ inputSchema: batch.items as Readonly<Record<string, unknown>>, idProperty }) };
  return { ...inputSchema, properties: projected,
    required: ((inputSchema.required as readonly string[] | undefined) ?? []).map((key) => key === idProperty ? "id" : key),
  };
}

/** Rename one selector without mutating caller input or exposing values in errors/notes.
 * @throws ToolInputError for conflicting spellings, even when their values are equal.
 * @complexity O(k) time/space for k input keys; no I/O.
 */
function renameCardSelector(
  { input, from, to }: { input: unknown; from: string; to: string }, _options = {},
): NormalizedToolInput {
  const candidate = { value: input };
  if (!isRecord(candidate) || !Object.hasOwn(candidate.value, from)) return { input, notes: [] };
  if (Object.hasOwn(candidate.value, to)) throw new ToolInputError({ message: `Conflicting inputs '${from}' and '${to}' both name '${to}'. Send only '${to}'.` });
  const { [from]: selector, ...rest } = candidate.value;
  return { input: { ...rest, [to]: selector }, notes: [`${from}→${to}`] };
}

/** Translate only the target selector at the root and in source-owned batch items.
 * Batch execution, limits, per-item authorization and result envelopes remain with Jini.
 * @throws ToolInputError if any single item contains both spellings, before a read begins.
 * @complexity O(k) time/space in root and batch-item keys; no per-item I/O.
 */
function mapCardSelectors(
  { input, from, to }: { input: unknown; from: string; to: string }, _options = {},
): NormalizedToolInput {
  const renamed = renameCardSelector({ input, from, to });
  const candidate = { value: renamed.input };
  if (!isRecord(candidate) || !Array.isArray(candidate.value.items)) return renamed;
  const notes = [...renamed.notes];
  const items = candidate.value.items.map((item, index) => {
    const result = renameCardSelector({ input: item, from, to });
    notes.push(...result.notes.map((note) => `items[${index}].${note}`));
    return result.input;
  });
  return { input: { ...candidate.value, items }, notes };
}

/** Adapt canonical card input back to the original handler ABI; aliases belong to the gate hook.
 * The direct handler also refuses collisions for callers that already own their execution gate.
 * @complexity O(k) time/space in supplied keys, plus the unchanged source handler cost.
 */
function canonicalCardDispatch(
  { card, byId }: { card: ContentReadCard; byId: ReadonlyMap<string, ToolRegistration> }, _options = {},
) {
  const dispatch = cardDispatch({ card, byId });
  const idProperty = card.get?.idProperty ?? card.listLookup?.idProperty;
  if (!idProperty || idProperty === "id") return { ...dispatch, normalizeInput: undefined };
  const normalizeInput: ToolInputNormalizer = ({ input }, _optional = {}) => {
    // Slug lookup belongs to the host target adapter after site selection and authorization;
    // this card owns only canonical id ↔ source-selector spelling.
    return mapCardSelectors({ input, from: idProperty, to: "id" });
  };
  const handler: ToolHandler = (ctx, options) => dispatch.handler({ ...ctx, input: mapCardSelectors({ input: ctx.input, from: "id", to: idProperty }).input }, options);
  return { ...dispatch, handler, normalizeInput };
}

/**
 * Builds a merged card's inputSchema as the union of its `get` and `list` members' own ALREADY-
 * PUBLISHED schemas — never hand-authored, so it cannot drift from what those two tools actually
 * accept. `idProperty` becomes optional in the union (its presence, not a `required` entry, is the
 * dispatch signal `dispatchByIdPresence` reads) with a one-line note appended explaining that.
 * `required` is the intersection of the two members' own required fields (with `idProperty` removed
 * from `get`'s side first) — a field required by only ONE branch cannot be required overall, since
 * the other branch never needs it. Shared required context stays required; `content_post`'s `id`
 * is get-only and becomes optional, while its `kind` is optional on both branches.
 *
 * @complexity O(p) in combined property count.
 */
function unionInputSchema(
  getSchema: Readonly<Record<string, unknown>>,
  listSchema: Readonly<Record<string, unknown>>,
  idProperty: string,
): Readonly<Record<string, unknown>> {
  const getProps = (getSchema.properties as Record<string, unknown> | undefined) ?? {};
  const listProps = (listSchema.properties as Record<string, unknown> | undefined) ?? {};
  const getRequired = new Set(((getSchema.required as readonly string[] | undefined) ?? []).filter((key) => key !== idProperty));
  const listRequired = new Set((listSchema.required as readonly string[] | undefined) ?? []);
  const required = [...getRequired].filter((key) => listRequired.has(key));

  const idSchema = getProps[idProperty] as Record<string, unknown> | undefined;
  const idPropertyEntry = idSchema
    ? {
        [idProperty]: {
          ...idSchema,
          description: `${(idSchema.description as string | undefined) ?? ""} Omit to list instead of fetching a single item.`.trim(),
        },
      }
    : {};

  const properties = { ...listProps, ...getProps, ...idPropertyEntry };
  // A merged card may advertise peer reads only when either dispatch branch can honor them.
  if (!Object.hasOwn(listProps, "site") || !Object.hasOwn(getProps, "site")) delete properties.site;

  return {
    type: "object",
    additionalProperties: false,
    required,
    properties,
  };
}

/**
 * The composition-root read pass: takes the already-built flat registration list every domain
 * contributed (`buildAssistantToolRegistrations`'s own loop), replaces the 36 Tier-1 read tools it
 * contains with the `content_read.<resource>` cards defined above, and leaves everything else —
 * all 141 other tools — untouched except that a retired id named in their prose is pointed at its
 * card (see {@link createRetiredReadToolIdRewriter}).
 *
 * Called from `tool-registrations.ts`'s `buildAssistantToolRegistrations` before host target and batch wrappers, NOT
 * registered as a `ToolContributor` — see this file's header for why it structurally cannot be one
 * (it needs to see what the contributor loop already produced).
 *
 * @param sourceRegistrations Every domain's own registrations, exactly as `buildAssistantToolRegistrations`'s
 * main loop assembled them, before this collapse.
 * @returns The same list with each FULLY-AVAILABLE card's member ids removed and that card appended
 * in their place. A card whose member(s) are not all present in `sourceRegistrations` (see
 * {@link cardIsAvailable}) is skipped entirely — its members pass through unchanged.
 * @throws {Error} If `buildDomainRegistrations`'s own build-time gates refuse (see that function's
 * own throws) — never for a missing member, which {@link cardIsAvailable} filters out first.
 * @complexity O(t) in total tool count — one pass to index, one pass over the cards, one filter.
 * @overallScore 100
 */
export function deriveContentReadRegistrations(sourceRegistrations: readonly ToolRegistration[]): ToolRegistration[] {
  const byId = new Map(sourceRegistrations.map((registration) => [registration.descriptor.id, registration] as const));
  const retiredIds = new Set<string>();
  const catalog = new Map<string, AgentToolDefinition>();
  const handlers: Record<string, ToolHandler> = {};
  const inputNormalizers: Record<string, ToolInputNormalizer> = {};
  const derivedRisk = new Map<string, AgentToolSideEffect>();

  for (const card of CONTENT_READ_CARDS) {
    if (!cardIsAvailable(byId, card)) continue;

    const id = contentReadToolId(card.resource);
    const { memberIds, handler, inputSchema, normalizeInput } = canonicalCardDispatch({ card, byId });

    for (const memberId of memberIds) retiredIds.add(memberId);

    const authorization: AgentToolDefinition["authorization"] = card.orPermission
      ? { permission: card.permission, orPermission: card.orPermission }
      : { permission: card.permission };

    const described = describeCardIdInput({ card, inputSchema });
    catalog.set(id, {
      name: id,
      description: cardDescription({ id, memberIds, byId, idDescription: described.idDescription }),
      sideEffects: "none",
      authorization,
      inputSchema: described.inputSchema,
    });
    handlers[id] = handler;
    if (normalizeInput) inputNormalizers[id] = normalizeInput;
    derivedRisk.set(id, "none");
  }

  const collapsed = buildDomainRegistrations({ metadata: toolMetadata,
    domain: "content-read",
    catalogModule: "assistant/content-read-tool.ts",
    catalog,
    handlers,
    inputNormalizers,
    derivedRisk: derivedRisk as DerivedRiskByToolId,
  });

  // Survivors and cards alike may still name a retired id in their prose; see `createRetiredReadToolIdRewriter`.
  return [...sourceRegistrations.filter((registration) => !retiredIds.has(registration.descriptor.id)), ...collapsed].map(createRetiredReadToolIdRewriter({ retiredIds }));
}

/** Resolve a card through its original domain handlers; permission enforcement stays there. */
function cardDispatch({ card, byId }: { card: ContentReadCard; byId: ReadonlyMap<string, ToolRegistration> }, _options = {}) {
  const memberIds: string[] = [];
  let handler: ToolHandler;
  let inputSchema: Readonly<Record<string, unknown>>;
  if (card.get && card.listLookup) {
    throw new Error(`content-read-tool.ts: card '${card.resource}' declares both get and listLookup — a hand-written get always serves read-one`);
  }

  if (card.list && card.listLookup) {
    return lookupCardDispatch({ card, list: card.list, lookup: card.listLookup, byId });
  } else if (card.get && card.list) {
    return pairedCardDispatch({ card, get: card.get, list: card.list, byId });
  } else if (card.get) {
    const getReg = sourceRegistration(byId, card.get.toolId);
    memberIds.push(card.get.toolId);
    handler = getReg.handler;
    inputSchema = registrationInputSchema({ registration: getReg });
  } else if (card.list) {
    const listReg = sourceRegistration(byId, card.list.toolId);
    memberIds.push(card.list.toolId);
    handler = listReg.handler;
    inputSchema = registrationInputSchema({ registration: listReg });
  } else {
    throw new Error(`content-read-tool.ts: card '${card.resource}' declares neither get nor list`);
  }

  return { memberIds, handler, inputSchema };
}

function pairedCardDispatch({ card, get, list, byId }: {
  card: ContentReadCard; get: NonNullable<ContentReadCard["get"]>; list: NonNullable<ContentReadCard["list"]>;
  byId: ReadonlyMap<string, ToolRegistration>;
}, _options = {}) {
  if (!get.idProperty) {
    throw new Error(`content-read-tool.ts: card '${card.resource}' declares both get and list but no idProperty on get`);
  }
  const getReg = sourceRegistration(byId, get.toolId);
  const listReg = sourceRegistration(byId, list.toolId);
  const getSchema = registrationInputSchema({ registration: getReg });
  const handler = dispatchByIdPresence({ idProperty: get.idProperty, get: getReg.handler, list: listReg.handler }, {
    batchGet: Object.hasOwn((getSchema.properties as Readonly<Record<string, unknown>> | undefined) ?? EMPTY_SCHEMA, "items"),
  });
  const inputSchema = unionInputSchema(
    getSchema,
    registrationInputSchema({ registration: listReg }),
    get.idProperty,
  );
  return { memberIds: [get.toolId, list.toolId], handler, inputSchema };
}

function registrationInputSchema({ registration }: { registration: ToolRegistration }, _options = {}): Readonly<Record<string, unknown>> {
  return (registration.descriptor.inputSchema as Readonly<Record<string, unknown>> | undefined) ?? EMPTY_SCHEMA;
}

function lookupCardDispatch({ card, list, lookup, byId }: {
  card: ContentReadCard; list: NonNullable<ContentReadCard["list"]>; lookup: ListLookup;
  byId: ReadonlyMap<string, ToolRegistration>;
}, _options = {}) {
  const listReg = sourceRegistration(byId, list.toolId);
  const get = lookupInList({ resource: card.resource, listToolId: list.toolId, lookup, list: listReg.handler });
  const handler = dispatchByIdPresence({ idProperty: lookup.idProperty, get, list: listReg.handler });
  const inputSchema = unionInputSchema(
    listLookupIdSchema({ resource: card.resource, lookup, listSchema: registrationInputSchema({ registration: listReg }) }),
    registrationInputSchema({ registration: listReg }),
    lookup.idProperty,
  );
  return { memberIds: [list.toolId], handler, inputSchema };
}

import type { VaultRecord } from '@jini-ai/platform/secrets/credential-sets';
import type { CredentialTokenHint } from '../contracts/core/credential-token.js';

/** Both assistant views expose presence and hints from the same vault snapshot. */
export function credentialViewFields({ record, tokenHint = null }: { record: VaultRecord | null; tokenHint?: CredentialTokenHint | null }, _options = {}) {
  return { isSet: record?.sealed != null, masked: tokenHint?.last4 ? `••••${tokenHint.last4}` : null,
    tokenHint, updatedAt: record?.updatedAt ?? null };
}

/** Omitted keys preserve envelopes; a new settings-only singleton has no payload. Jini still
 * owns preparation, sealing and CAS; these are the two feature adapters' shared input fields. */
export function credentialWriteFields({ existing, apiKey }: { existing: VaultRecord | null; apiKey: string | undefined }, _options = {}) {
  return { ...(existing ? { id: existing.id } : {}), expectedRevision: existing?.revision ?? null,
    label: existing?.label ?? '',
    payload: apiKey === undefined ? (existing ? undefined : null) : { apiKey },
    ...(apiKey === undefined ? {} : { hintToken: apiKey }) };
}

/**
 * @file G3: the per-call Confirm/Cancel card for protected external actions: permanent deletion,
 * delivery to people, and changes to assistant privacy/instructions/access (shared trust R3,
 * plus trash/restore-over-existing/publication under owner policy). The handler classifies actual arguments as well as remote hints;
 * neither removing a card nor remembering approval grants admission or permissions.
 *
 * Built on `requireHumanConfirm` (`contracts/core/human-confirm.ts`) — the same held-open MCP-UI
 * exchange every confirmed native tool uses — so a click reaches the parked call through
 * `mcp-ui-tool-calls-route.ts`. Federated ids are dynamic, so they are not on
 * `MCP_UI_REDEEMABLE_TOOL_IDS`; `isMcpUiToolCallPermitted` lets an `mcp__` id ANSWER an open card and
 * never be executed by that route.
 *
 * The card shows the service, the tool and every argument in plain words: a string argument (the SQL
 * of `execute_sql`, say) exactly as it will be sent, anything else as JSON. The arguments it is given
 * are the frozen object the handler sends on Confirm (`registrations.ts`'s `frozenArguments`), so what
 * the human approves is what runs.
 *
 * Remembered approvals under owner policy: besides Allow (this one call) and Cancel, the card
 * offers "Allow for this chat" (kept with the conversation) and, for a call that can be remembered,
 * "Always allow" (kept per site + connection + tool). Both are pinned to the tool's identity
 * (@jini-ai/mcp/federation), so a changed server, name or hints asks again. A remembered
 * approval skips the card; it never changes what is sent — the frozen arguments go out as before.
 *
 * Trash/delete/restore-over-existing/publish calls are asked every time. Existing specific
 * protected calls with write-shaped inputs also offer nothing to remember; neither scope skips them.
 * An ordinary read or write needs no card solely because an input happens to be named query/sql.
 *
 * Architectural role: `assistant` composition helper, implementing `FederationDeps.confirmCall`.
 */
import type { UUID } from "@jini-ai/core/primitives";
import type { AuthorizeFn } from "@jini-ai/cms/core";
import type { ToolExecutionContext, ToolExecutionOptions } from "@jini-ai/core";
import {
  buildFederatedCallConfirmSpec as buildJiniSpec,
  createFederatedCallConfirmer as createJiniConfirmer,
  type FederatedCardOffers,
} from "@jini-ai/mcp/federation/approvals";
import { notConfirmedResult, approvalToolHandler, type HumanConfirmSpec } from "../contracts/core/human-confirm.js";
import type { AssistantSurfaceDeps } from "@jini-ai/daemon/surface-exchanges";
import type { ConversationToolApprovalStore, ExternalMcpToolApprovalRepoPort } from "./external-mcp-tool-approval-ports.js";
import { toJiniConversationApprovalStore, toJiniToolApprovalRepo } from "./external-mcp-tool-approval-adapters.js";
import type { FederatedPolicyConfirmationRequest, FederationDeps } from "./mcp-federation/registrations.js";
import { tovuFederationMessages, TOVU_MCP_APPROVAL_FINGERPRINT_DOMAIN } from "./mcp-federation/presets.js";

/** Saving Always allow changes site settings for everyone, requiring the Integrations permission. */
const ALWAYS_ALLOW_PERMISSION = "admin.integrations.manage";

/** Host storage and permission ports; missing stores remove the corresponding card choice. */
export interface FederatedApprovalDeps {
  readonly workspaceId: UUID;
  readonly authorize: AuthorizeFn;
  readonly always?: ExternalMcpToolApprovalRepoPort;
  readonly chat?: ConversationToolApprovalStore;
  readonly conversationIdForRun?: (runId: string) => string | undefined;
  readonly now?: () => Date;
}

/** Bind settings wording/error codes to the package's pure card reducer.
 * Existing callers keep the host ABI; Jini refuses remember choices for destructive calls.
 * @complexity O(a) in the argument count and rendered values.
 */
export function buildFederatedCallConfirmSpec(request: FederatedPolicyConfirmationRequest,
  offers: FederatedCardOffers = { offerChat: false, offerAlways: false },
): HumanConfirmSpec {
  return actionConfirmSpec(buildJiniSpec({ request, messages: tovuFederationMessages, errorCode: "EXTERNAL_MCP" }, { offers }), request);
}

/** Per-call consent and irreversible-deletion wording are separate decisions. Jini still refuses
 * remembered grants; these CMS cards describe the real action instead of relabeling it a delete. */
function actionConfirmSpec(spec: HumanConfirmSpec, request: FederatedPolicyConfirmationRequest): HumanConfirmSpec {
  const action = request.approvalClass === 'publish' ? 'publishes, unpublishes or deploys content'
    : request.approvalClass === 'trash' ? 'moves data to Trash'
    : request.approvalClass === 'restore-over-existing' ? 'restores over existing data' : undefined;
  return action ? { ...spec, danger: request.approvalClass !== 'publish',
    warning: `This action ${action} in ${request.connectionLabel}. Approval applies to this call only.`,
  } : spec;
}

/** Bind the parked MCP-UI exchange and CMS permission evaluator to Jini's approval lifecycle.
 * The exchange store must be the one used by the click route. Cancellation remains fail-closed;
 * persistence failures allow this explicitly approved call and make the next one ask again.
 * @complexity O(1) plus store reads and the human's wait; no I/O until the returned callback runs.
 */
export function createFederatedCallConfirmer(surfaces: AssistantSurfaceDeps,
  approvals?: FederatedApprovalDeps,
): NonNullable<FederationDeps["confirmCall"]> {
  const confirm = createJiniConfirmer<ToolExecutionContext & ToolExecutionOptions & { approvalRequest: FederatedPolicyConfirmationRequest }, AssistantSurfaceDeps>({
    fingerprintDomain: TOVU_MCP_APPROVAL_FINGERPRINT_DOMAIN,
    errorCode: "EXTERNAL_MCP", messages: tovuFederationMessages, surfaceExchanges: surfaces,
    humanConfirm: { ask: async ({ context, surfaceExchanges, spec }) => {
      return approvalToolHandler({ surfaces: surfaceExchanges,
        prepare: async () => actionConfirmSpec(spec, context.approvalRequest),
        describe: ({ prepared }) => prepared,
        run: async ({ choice }) => ({ confirmed: true, ...(choice === undefined ? {} : { choice }) }),
      }, { declined: ({ reason }) => ({ confirmed: false, result: notConfirmedResult({ confirmed: false, reason }) }) })(context, { emitSurface: context.emitSurface }) as Promise<{ confirmed: true; choice?: string } | { confirmed: false; result: ReturnType<typeof notConfirmedResult> }>;
    } },
  }, {
    ...(approvals ? { scope: approvals.workspaceId, approvals: {
      clock: { nowMs: () => (approvals.now?.() ?? new Date()).getTime() },
      mayAlwaysAllow: async ({ principalId }: { principalId: string }) => (await approvals.authorize({
        principalId, permission: ALWAYS_ALLOW_PERMISSION, workspaceId: approvals.workspaceId, entityType: "integration",
      })).allowed,
      ...(approvals.always ? { always: toJiniToolApprovalRepo({ repo: approvals.always, workspaceId: approvals.workspaceId }) } : {}),
      ...(approvals.chat ? { chat: toJiniConversationApprovalStore({ store: approvals.chat }) } : {}),
      ...(approvals.conversationIdForRun ? { conversationIdForRun: ({ runId }: { runId: string }) => approvals.conversationIdForRun!(runId) } : {}),
    } } : {}),
    onPersistenceError: ({ choice, toolId, error }) => console.warn(
      `[external-mcp] could not remember the "${choice}" approval for ${toolId}; this call runs, the next one asks again — ${error instanceof Error ? error.message : String(error)}`,
    ),
  });
  return (context, request) => confirm({ context: { ...context, approvalRequest: request }, request });
}

import type { UUID } from "@jini-ai/core/primitives";
import type { AuthorizeFn } from "@jini-ai/cms/core";
import type { resolveAgentPluginReadOnlyRemoteNames } from "../features/agent-plugins/federate-mcp.js";

import type { SecretSealerPort } from "../features/webhooks/index.js";

import type { SurfaceExchangeStore } from "@jini-ai/daemon/surface-exchanges";

import { createFederatedCallConfirmer, type FederatedApprovalDeps } from "./external-mcp-call-confirmation.js";
import { createExternalMcpConnectionGate, type ExternalMcpOAuthService } from "./external-mcp-oauth.js";
import {
  readEnabledExternalMcpConfigs,
  toResolvedFederatedConnections,
  type ExternalMcpOAuthTokenResolverPort,
  type ExternalMcpServerConfig,
  type ExternalMcpServerRepoPort,
} from "./external-mcp-store.js";
import type { ResolvedFederatedConnection } from "@jini-ai/mcp/federation";
import type { McpAuthFailedError } from "@jini-ai/mcp/federation";
import type { FederationDeps } from "./mcp-federation/registrations.js";

/**
 * @file Shared stored-roster resolution and federation dependency binding for daemon and BYOK.
 * Each composition supplies its own log prefix so process-specific diagnostics remain identifiable.
 */

/** One roster-read failure, in the shape both the daemon's admissions route and BYOK's refusal
 *  diagnosis already expect. */
export interface StoredExternalMcpConnectionFailure {
  readonly connectionId: string;
  readonly reason: string;
}

export interface StoredExternalMcpConnectionSourceDeps {
  readonly agentPluginLayout: import("../features/agent-plugins/layout.js").AgentPluginLayout;
  readonly repo: ExternalMcpServerRepoPort;
  readonly sealer: SecretSealerPort;
  /** Resolves (and refreshes, if due) an `authMode: "oauth"` row's access token before its child
   *  process is launched with it. Omitted where no root wires OAuth-backed connections. */
  readonly oauth?: ExternalMcpOAuthTokenResolverPort;
  readonly workspaceId: UUID;
  /** Log-line prefix (`"[agent-daemon]"`, `"[assistant-byok]"`, ...) identifies the composition root. */
  readonly log: string;
  /** Local manifest lookup, never remote annotations. Injected to exercise roster reloads. */
  readonly resolvePluginReadOnlyRemoteNames?: typeof resolveAgentPluginReadOnlyRemoteNames;
}

export interface StoredExternalMcpConnectionSource {
  /**
   * Reads the workspace's enabled external-MCP roster and resolves it into federation's launch
   * shape. Never rejects: a read failure (the whole call throwing) or a per-row resolution failure
   * both fall back to an empty connection list, with the failure logged and recorded for
   * {@link StoredExternalMcpConnectionSource.failures} instead of propagating.
   */
  resolve(): Promise<ResolvedFederatedConnection[]>;
  /**
   * The most recent call's per-row failures — REPLACED, not accumulated, on every {@link resolve}
   * call, so a stale failure from an earlier attempt never lingers next to a since-succeeded
   * connection. Empty before the first {@link resolve} call, and also after a call whose whole read
   * failed (a per-row failure could not be attributed in that case either).
   */
  failures(): readonly StoredExternalMcpConnectionFailure[];
}

/**
 * Loads stored launch configs and current bundled-plugin read declarations. Manifest lookup
 * failures omit read grants for that connection without removing usable connections.
 * @returns A reloadable source with the latest store-resolution failures.
 * @complexity O(c) configs plus one installed-package scan/manifest lookup per plugin connection;
 * O(c + r) output space for connection configs and read names. No remote I/O is added here.
 */
export function createStoredExternalMcpConnectionSource(
  deps: StoredExternalMcpConnectionSourceDeps,
): StoredExternalMcpConnectionSource {
  let configFailures: readonly StoredExternalMcpConnectionFailure[] = [];
  const resolvePluginReads = deps.resolvePluginReadOnlyRemoteNames ?? loadPluginReadOnlyRemoteNames;

  return {
    async resolve(): Promise<ResolvedFederatedConnection[]> {
      try {
        const { configs, failures } = await readEnabledExternalMcpConfigs(
          { repo: deps.repo, sealer: deps.sealer, oauth: deps.oauth },
          deps.workspaceId,
        );
        for (const failure of failures) {
          console.warn(`${deps.log} mcp-federation: stored server '${failure.serverId}' skipped — ${failure.reason}`);
        }
        configFailures = failures.map((failure) => ({ connectionId: failure.serverId, reason: failure.reason }));
        return toResolvedFederatedConnections(configs, await pluginReadOnlyNames({ deps, configs, resolvePluginReads }));
      } catch (error) {
        console.warn(
          `${deps.log} mcp-federation: the stored external-MCP roster could not be read, continuing without it — ${errorDetail(error)}`,
        );
        configFailures = [];
        return [];
      }
    },
    failures(): readonly StoredExternalMcpConnectionFailure[] {
      return configFailures;
    },
  };
}

// Defer the plugin adapter until roster resolution: its provisioning half reaches the
// assistant barrel, so importing it eagerly would make this module part of that boot cycle.
async function loadPluginReadOnlyRemoteNames(
  input: Parameters<typeof resolveAgentPluginReadOnlyRemoteNames>[0],
): ReturnType<typeof resolveAgentPluginReadOnlyRemoteNames> {
  return (await import("../features/agent-plugins/federate-mcp.js")).resolveAgentPluginReadOnlyRemoteNames(input);
}

/** Read-only remote names for each plugin-provisioned remote connection; other connections get none.
 * @complexity O(c) configs plus one manifest lookup per plugin-provisioned remote connection. */
async function pluginReadOnlyNames({ deps, configs, resolvePluginReads }: {
  deps: StoredExternalMcpConnectionSourceDeps; configs: readonly ExternalMcpServerConfig[];
  resolvePluginReads: typeof resolveAgentPluginReadOnlyRemoteNames;
}, _options = {}): Promise<Map<string, ReadonlySet<string>>> {
  const readOnlyNames = new Map<string, ReadonlySet<string>>();
  for (const config of configs) {
    if (!config.provisionedByPluginId || config.target.kind !== "streamable_http") continue;
    try {
      readOnlyNames.set(config.serverId, await resolvePluginReads({
        agentPluginLayout: deps.agentPluginLayout,
        workspaceId: deps.workspaceId,
        pluginId: config.provisionedByPluginId,
        serverId: config.serverId,
        url: config.target.url,
      }));
    } catch (error) {
      // Classification fails closed without dropping unrelated, otherwise usable connections.
      console.warn(`${deps.log} mcp-federation: plugin read declarations for '${config.serverId}' unavailable — ${errorDetail(error)}`);
    }
  }
  return readOnlyNames;
}

/** A thrown value's message for a diagnostic line. */
function errorDetail(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/**
 * Builds the `FederationDeps` shared by the boot admission pass and every reload pass: the SAME
 * gate/failure-reporting wiring must back both, or a connection admitted by a reload could be held
 * to different liveness behaviour than one admitted at boot for no reason other than which pass
 * happened to register it (mirrors `agent-daemon-server.ts`'s own reasoning at `:1267-1270`).
 */
export function buildExternalMcpFederationDeps(inputs: {
  readonly authorize: AuthorizeFn;
  readonly workspaceId: UUID;
  readonly repo: ExternalMcpServerRepoPort;
  /** When present, a live 401/403 mid-session records `needs_reauth` (so the gate below catches the
   *  NEXT call cheaply) and replaces the transport-shaped error with the gate's own terminal
   *  message. Absent, `onAuthFailed` is left unset — not set to a no-op — so `FederationDeps`'s own
   *  "propagate unchanged" default applies. */
  readonly oauth?: Pick<ExternalMcpOAuthService, "reportAuthFailure">;
  /**
   * G3: the exchange store the root's MCP-UI click route is mounted with. When present, every
   * federated tool that is not marked read-only asks the human on a per-call Confirm/Cancel card
   * (`external-mcp-call-confirmation.ts`). Absent, `confirmCall` is left unset and those tools are
   * refused at the call — fail closed, nothing is sent.
   */
  readonly surfaceExchanges?: SurfaceExchangeStore;
  /**
   * G3 remembered approvals: where "Allow for this chat" / "Always allow" are kept and how a run
   * finds its conversation (`external-mcp-call-confirmation.ts`). Only read when `surfaceExchanges`
   * is present. Absent parts are simply not offered on the card.
   */
  readonly approvals?: Omit<FederatedApprovalDeps, "workspaceId" | "authorize">;
}): FederationDeps {
  const assertConnectionUsable = createExternalMcpConnectionGate({
    workspaceId: inputs.workspaceId,
    repo: inputs.repo,
  });
  const oauth = inputs.oauth;
  const surfaceExchanges = inputs.surfaceExchanges;
  return {
    authorize: inputs.authorize,
    workspaceId: inputs.workspaceId,
    assertConnectionUsable,
    ...(oauth
      ? { onAuthFailed: (connectionId: string, error: McpAuthFailedError) => oauth.reportAuthFailure(connectionId, error) }
      : {}),
    ...(surfaceExchanges
      ? {
          confirmCall: createFederatedCallConfirmer(
            { surfaceExchanges },
            { ...inputs.approvals, workspaceId: inputs.workspaceId, authorize: inputs.authorize },
          ),
        }
      : {}),
  };
}

import { CredentialInputError, assertCredentialFreeField, normalizeCredentialToken, assertCredentialToken, CREDENTIAL_MESSAGES, CREDENTIAL_TOKEN_LIMIT, credentialTokenHint, type CredentialTokenHint } from '../contracts/core/credential-token.js';
import { createHash } from "node:crypto";

import { nowIso, type Clock as ClockPort, type ISODateTime, type UUID } from "@jini-ai/core/primitives";

import type { KeyringPort, SealedSecret, SecretSealerPort } from "../features/webhooks/index.js";
import { FEDERATED_CONNECTION_DEFAULTS, type ResolvedFederatedConnection } from "@jini-ai/mcp/federation";
import type { McpLaunchSpec } from "@jini-ai/mcp/federation";
import { assertValidConnectionId } from "@jini-ai/mcp/federation";
import {
  EXTERNAL_MCP_AUTH_MODES,
  externalMcpRecordHasStaticAccessToken,
  resolveExternalMcpAuthMode,
  type ExternalMcpAuthMode,
} from "../features/external-mcp/auth-mode.js";

/**
 * @file The operator-editable roster of external MCP servers — what Settings → External MCP writes,
 * and what the agent daemon reads at boot to decide which third-party servers to federate.
 *
 * This is the SECOND config source for `mcp-federation/`. The first is `presets.ts`, whose
 * resolvers read `TOVU_<VENDOR>_MCP_*` environment variables; it stays exactly as it was. The two
 * differ in kind, which is why this is not written as a preset: a preset resolver is synchronous and
 * returns at most one connection, while this store is async (sealing is promise-based) and returns
 * N. `bootstrap.ts`'s `extraConnections` parameter is the seam that carries them.
 *
 * ## Secrets
 *
 * An MCP server's `env` block routinely carries live credentials, so it is sealed through ADR-058's
 * Jini vault service using the same keyring instance the BYOK/media-provider stores share
 * — `src/webhooks/ports.ts` states the rule this follows: keep secret material out of the
 * portable `content.db`.
 *
 * The block is sealed WHOLE rather than per-variable. Every read path wants all of it at once (it
 * becomes one child process's environment), so per-variable sealing would buy nothing and cost N
 * round-trips. Variable NAMES are stored separately in plaintext so the tab can show which
 * variables are set without unsealing anything.
 *
 * ## What this file does NOT do
 *
 * It does not decide whether a remote tool may be called. That is `mcp-federation/trust.ts`'s
 * default-deny admission tier, applied at connect time to whatever this store produced.
 * `allowedToolNames` is carried here and enforced there, on purpose: a config store that also
 * adjudicated trust would be two mechanisms with one owner.
 *
 * It does not run the OAuth flow either. That is `assistant/external-mcp-oauth.ts` over the generic
 * client in `src/platform/oauth/`; this store owns only the ROW — which auth mode a server uses, its
 * plaintext OAuth metadata, and the sealed blob. Same split as `allowedToolNames`, same reason.
 *
 * ## Transport and auth mode are ORTHOGONAL
 *
 * {@link ExternalMcpTransport} and {@link ExternalMcpAuthMode} are two independent fields and must
 * stay that way. Encoding OAuth as a transport (`transport: "oauth"`) would be the wrong
 * abstraction immediately, not eventually: a hosted server may be HTTP + OAuth, and a LOCAL stdio
 * server may also require OAuth — Tovu obtains the token and hands it to the child process in its
 * environment. Both combinations are real, so neither field can be derived from the other.
 */

/**
 * Both transports are federated. `stdio` is served by `mcp-federation/adapter.stdio.ts` (a local
 * child process); `streamable_http` by `mcp-federation/adapter.http.ts` (a hosted endpoint, with a
 * bearer header when the row is OAuth- or access-token-authenticated — see `resolveHttpTarget`).
 * {@link readEnabledExternalMcpConfigs} resolves a hosted row to a `streamable_http` target,
 * `toFederatedLaunchSpec` maps it to a `{ url, headers }` launch spec, and
 * `mcp-federation/bootstrap.ts`'s `defaultConnect` picks the HTTP adapter from that spec's shape.
 * A hosted row is reported unusable only when it has no URL or its token cannot be resolved.
 */
export const SUPPORTED_EXTERNAL_MCP_TRANSPORTS = ["stdio", "streamable_http"] as const;
export type ExternalMcpTransport = (typeof SUPPORTED_EXTERNAL_MCP_TRANSPORTS)[number];

/** `EXTERNAL_MCP_AUTH_MODES`/`ExternalMcpAuthMode` (how a server's credentials are obtained) and
 *  their two readers live in the external-MCP domain module `features/external-mcp/auth-mode.ts`
 *  (owner decision C — see that file's header). Re-exported here so every
 *  `#src/assistant/index` importer keeps working unchanged. */
export {
  EXTERNAL_MCP_AUTH_MODES,
  externalMcpRecordHasStaticAccessToken,
  resolveExternalMcpAuthMode,
  type ExternalMcpAuthMode,
} from "../features/external-mcp/auth-mode.js";

/**
 * The runtime lifecycle of an OAuth-backed connection.
 *
 * `needs_reauth` is the state that earns its place here. It is deliberately NOT the boot-time "skip
 * this row and report why" path {@link readEnabledExternalMcpConfigs} already uses for a sealed blob
 * that will not decrypt: that is a STORAGE failure, nothing the operator types can fix it, and it is
 * discovered while the daemon starts. `needs_reauth` is an expected RUNTIME lifecycle state — a
 * token expired or was revoked while everything was working — it is exactly operator-actionable, and
 * it must be visible in the admin tab rather than buried in a boot log nobody is reading at the time.
 */
export const EXTERNAL_MCP_OAUTH_STATUSES = ["disconnected", "pending", "connected", "needs_reauth"] as const;
export type ExternalMcpOAuthStatus = (typeof EXTERNAL_MCP_OAUTH_STATUSES)[number];

/** Which OAuth grant an operator chose. Mirrors `src/platform/oauth/`'s `OAuthGrantKind`; restated rather
 *  than imported so the stored row shape does not depend on the flow module. */
export const EXTERNAL_MCP_OAUTH_GRANTS = ["authorization_code", "device_code"] as const;
export type ExternalMcpOAuthGrant = (typeof EXTERNAL_MCP_OAUTH_GRANTS)[number];

/** Raised when operator-supplied input cannot be stored. Carries `field` so a route can point the
 *  form at the offending input rather than rejecting the whole submission opaquely. */
export class ExternalMcpValidationError extends Error {
  readonly field: string;

  constructor(
    message: string,
    field: string,
  ) {
    super(message);
    this.field = field;
    this.name = "ExternalMcpValidationError";
  }
}

/** Raised when sealing fails because no site key is configured — distinct from a validation error,
 *  because nothing the operator types can fix it. */
export class ExternalMcpSecretStoreUnconfiguredError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ExternalMcpSecretStoreUnconfiguredError";
  }
}

/** One stored row. `sealedEnv` is null when the server needs no credentials, which is normal. */
/** Compatibility DTO version for normalized vault envelopes; historical formats live in recovery. */
export const EXTERNAL_MCP_VAULT_VERSION = 1;
type ExternalMcpIdentity = { workspaceId: string; serverId: string };
import { openExternalMcpVaultPayload, sealExternalMcpVaultPayload } from "./external-mcp-vault.js";

export interface ExternalMcpServerRecord {
  workspaceId: UUID;
  serverId: string;
  label: string | null;
  /** The Agent Plugin id that auto-provisioned this row, or `null` for an operator-created one. See
   *  `schema.sqlite.ts`'s `provisioned_by_plugin_id` column doc for the full rule. */
  provisionedByPluginId: string | null;
  transport: string;
  /** How credentials are obtained. Independent of `transport` — see this file's header. */
  authMode: string;
  enabled: boolean;
  command: string | null;
  /** Endpoint for a remote transport. NULL for `stdio`, where `command` is used instead. */
  url: string | null;
  /** JSON array of argv strings, as stored. */
  args: string | null;
  /** JSON array of admissible remote tool names, as stored. */
  allowedToolNames: string | null;
  /**
   * JSON array of remote tool names separately authorized to write, as stored. `trust.ts` R3's
   * override — a tool declaring `readOnlyHint: false` is admitted only when it also appears in
   * {@link allowedToolNames}. See `@jini-ai/mcp/federation`'s `FederatedMcpConnectionConfig
   * .writeAllowedToolNames` for the full argument.
   */
  writeAllowedToolNames: string | null;
  /** Principal who last CHANGED {@link writeAllowedToolNames}'s contents. `null` until that list is
   *  ever touched, or for a row written before this column existed. */
  writeGrantsUpdatedByPrincipalId: string | null;
  /** When {@link writeAllowedToolNames} was last changed. `null` under the same condition. */
  writeGrantsUpdatedAt: ISODateTime | null;
  /** JSON array of env variable names, as stored. Plaintext by design. */
  envNames: string | null;
  sealedEnv: SealedSecret | null;
  /** Which registered provider descriptor this connection authorizes against. */
  oauthProviderId: string | null;
  oauthGrant: string | null;
  /** Plaintext: a client id is not a secret — it travels in the authorization URL by design. */
  oauthClientId: string | null;
  /** JSON object of operator-typed endpoints, when this connection defines its own provider instead
   *  of naming a registered one. Non-secret. */
  oauthEndpointsJson: string | null;
  /** JSON array of requested scopes. Non-secret. */
  oauthScopesJson: string | null;
  oauthStatus: string | null;
  /**
   * PLAINTEXT absolute expiry of the stored access token, beside the sealed blob rather than inside
   * it. Exactly the split this file already makes for `envNames` beside `sealedEnv`, and here it is
   * load-bearing rather than merely convenient: expiry has to be checkable by a scheduler and
   * displayable in the admin tab, and neither can afford a keyring round trip — nor should either be
   * a code path that decrypts a live token to answer a question about when it dies.
   */
  oauthExpiresAt: ISODateTime | null;
  /**
   * For `stdio` + `oauth`: which child-process environment variable receives the access token.
   * Plaintext because it is a NAME, exactly as `envNames` is.
   */
  oauthTokenEnvName: string | null;
  /**
   * Cross-process refresh lease. Held while one process is redeeming the refresh token, so the other
   * — the admin web server and the agent daemon are separate processes with separate database
   * handles — does not redeem the same single-use rotating token. Plaintext for the same reason as
   * `oauthExpiresAt`: a lease you must decrypt to inspect is a lease you cannot break after a crash.
   */
  oauthRefreshLeaseUntil: ISODateTime | null;
  /** Sealed `{ clientSecret?, tokens? }`. See `external-mcp-oauth.ts` for the read-modify-write rule. */
  sealedOAuth: SealedSecret | null;
  /** Compatibility read field; normalized vault envelopes use lineage 1. */
  aadVersion: number;
  /** Compatibility read field; actual authenticated context lives on the vault row. */
  oauthAadVersion: number;
  createdAt: ISODateTime;
  updatedAt: ISODateTime;
}

/** Workspace-scoped persistence (ADR-007 §1). Multi-row per workspace, so list/upsert/delete rather
 *  than a single-row find/upsert. */
export interface ExternalMcpServerRepoPort {
  listByWorkspaceId(workspaceId: UUID): Promise<ExternalMcpServerRecord[]>;
  findByServerId(input: { workspaceId: UUID; serverId: string }): Promise<ExternalMcpServerRecord | null>;
  upsert(record: ExternalMcpServerRecord): Promise<void>;
  deleteByServerId(input: { workspaceId: UUID; serverId: string }): Promise<boolean>;
  /**
   * Atomically claims the OAuth refresh lease for one row, iff nobody holds an unexpired one.
   *
   * A COMPARE-AND-SET, not a read-then-write, and that is the entire point: `upsert` cannot express
   * it, because between reading "no lease" and writing "my lease" the other process does the same
   * and both go on to redeem the same single-use rotating refresh token. One statement with the
   * condition in its `WHERE` is what makes the loser observable.
   *
   * @returns `true` when this caller now holds the lease.
   */
  tryClaimOAuthRefreshLease(input: {
    workspaceId: UUID;
    serverId: string;
    /** Now, per the caller's clock. A lease at or before this instant is treated as abandoned. */
    nowIso: ISODateTime;
    /** When this claim expires, so a crashed holder cannot wedge the connection forever. */
    leaseUntil: ISODateTime;
  }): Promise<boolean>;
  /** Releases the lease unconditionally. Safe when not held — the lease is advisory and
   *  time-bounded, so a spurious release costs at most one extra refresh attempt. */
  releaseOAuthRefreshLease(input: { workspaceId: UUID; serverId: string }): Promise<void>;
}

/** The decrypted, validated domain shape. Only ever exists in memory. */
/**
 * Where a resolved connection's credentials go, which is the one thing the two transports do
 * genuinely differently.
 *
 * A union rather than a flat shape with an empty `command` on one arm and an empty `url` on the
 * other: a config carrying both is not a degraded row to tolerate, it is a bug, and this makes it
 * unrepresentable. It mirrors `@jini-ai/mcp/federation`'s `McpLaunchSpec` deliberately — this is
 * the same distinction one layer earlier, before policy is attached.
 */
export type ExternalMcpServerTarget =
  | {
      readonly kind: "stdio";
      readonly command: string;
      readonly args: string[];
      /**
       * The child process's environment. For an `oauth` connection this ALREADY contains the
       * resolved access token under the operator's chosen variable name — resolution happens before
       * this shape exists, so nothing downstream needs to know whether a value came from a pasted
       * block or a token endpoint.
       */
      readonly env: Record<string, string>;
    }
  | {
      readonly kind: "streamable_http";
      readonly url: string;
      /**
       * Request headers, carrying the resolved access token as `Authorization: Bearer ...` for an
       * `oauth` connection. The hosted analogue of `env` above, and resolved at the same point for
       * the same reason.
       */
      readonly headers: Record<string, string>;
    };

export interface ExternalMcpServerConfig {
  /** Retained for matching the reviewed plugin declaration when the roster is loaded. */
  provisionedByPluginId?: string;
  serverId: string;
  label: string;
  transport: ExternalMcpTransport;
  authMode: ExternalMcpAuthMode;
  enabled: boolean;
  allowedToolNames: string[];
  /** The operator's second, write-authorization list. See {@link ExternalMcpServerRecord
   *  .writeAllowedToolNames}. Passed through untouched for `trust.ts` to enforce. */
  writeAllowedToolNames: string[];
  target: ExternalMcpServerTarget;
  /** {@link externalMcpAdmissionRevision} of the row this config was resolved from — carried onto
   *  {@link ResolvedFederatedConnection.config}'s `origin` by {@link toResolvedFederatedConnections}
   *  for `external-mcp-revocation.ts`'s per-call gate. */
  admissionRevision: string;
}

/** The OAuth half of {@link ExternalMcpServerView}. Non-secret by construction: no access token, no
 *  refresh token and no client secret appears here or in anything that builds it. */
export interface ExternalMcpOAuthView {
  providerId: string | null;
  grant: string | null;
  clientId: string | null;
  scopes: string[];
  status: ExternalMcpOAuthStatus;
  /** Plaintext expiry, straight off the row — nothing is unsealed to produce it. */
  expiresAt: ISODateTime | null;
  tokenEnvName: string | null;
  /** Whether an access TOKEN is stored. Presence, never the value — the same technique
   *  `routes/admin/system/deployment-overview.ts` uses for environment variables. Decided from
   *  PLAINTEXT columns only; see {@link externalMcpRecordHasStoredToken} for why it must not unseal
   *  and for the one state it under-reports. */
  hasStoredToken: boolean;
}

/** The read model the admin tab renders — never carries env VALUES or any OAuth secret. */
export interface ExternalMcpServerView {
  serverId: string;
  label: string;
  /** Which Agent Plugin auto-provisioned this row, or `null` for one an operator created by hand —
   *  what lets the admin tab (and a future uninstall flow) tell the two apart. */
  provisionedByPluginId: string | null;
  transport: string;
  authMode: string;
  enabled: boolean;
  command: string;
  url: string | null;
  args: string[];
  allowedToolNames: string[];
  /** The operator's second, write-authorization list. See {@link ExternalMcpServerRecord
   *  .writeAllowedToolNames}. */
  writeAllowedToolNames: string[];
  /** Who last changed {@link writeAllowedToolNames}, and when — so the tab can render "authorized by
   *  X on Y". `null` until that list is ever touched. */
  writeGrantsUpdatedByPrincipalId: string | null;
  writeGrantsUpdatedAt: ISODateTime | null;
  /** Variable names only. The tab masks values it never receives. */
  envNames: string[];
  /** Whether a `static_env` access token is stored. Presence only, decided from plaintext columns —
   *  see {@link externalMcpRecordHasStaticAccessToken}. */
  hasAccessToken: boolean;
  accessTokenHint?: CredentialTokenHint | null;
  envTokenHints?: Readonly<Record<string, CredentialTokenHint>>;
  /** For `stdio` + `static_env`: the child env variable that receives that token. A NAME, so plaintext. */
  accessTokenEnvName: string | null;
  oauth: ExternalMcpOAuthView;
}

export interface ExternalMcpStoreDeps {
  repo: ExternalMcpServerRepoPort;
  sealer: SecretSealerPort;
  keyring: KeyringPort;
  clock: ClockPort;
}

const MAX_SERVERS_PER_WORKSPACE = 32;
const MAX_ENV_VARS = 64;
const MAX_ARGS = 64;
const MAX_ALLOWED_TOOLS = 64;
/** Matches `trust.ts`'s own `REMOTE_TOOL_NAME_PATTERN`. Restated rather than imported because that
 *  constant is private to the trust tier; `__tests__/external-mcp-store.test.ts` asserts the two
 *  agree by round-tripping a name through `admitRemoteTools`. */
const REMOTE_TOOL_NAME_PATTERN = /^[a-zA-Z0-9][a-zA-Z0-9_.-]{0,63}$/;
/** POSIX-ish environment variable name. Deliberately stricter than what a shell tolerates: a name
 *  outside this set is far more likely a mis-pasted line than an intentional variable. */
const ENV_NAME_PATTERN = /^[A-Za-z_][A-Za-z0-9_]*$/;
/** Generous — a provider asking for more distinct scopes than this is misconfigured, not ambitious. */
const MAX_OAUTH_SCOPES = 64;
/** Bounds the single-line OAuth identity fields (client id, secret). A real one is far shorter; the
 *  cap exists so a pasted file cannot become a database row. */
const MAX_OAUTH_FIELD_LENGTH = 1024;
/** Matches `src/platform/oauth/providers.ts`'s own rule. Restated rather than imported for the reason this
 *  file's header gives: the row shape must not depend on the flow module. */
const OAUTH_PROVIDER_ID_PATTERN = /^[a-z0-9][a-z0-9-]{0,63}$/;

/** Parses a stored JSON object column, tolerating a null/absent/corrupt value as `{}` — the same
 *  posture {@link parseJsonArray} takes, and for the same reason: one unreadable column must not
 *  make a whole row unreadable. */
function parseJsonObject(raw: string | null): Record<string, string> {
  if (!raw) return {};
  try {
    const parsed: unknown = JSON.parse(raw);
    if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) return {};
    return Object.fromEntries(Object.entries(parsed).filter((entry): entry is [string, string] => typeof entry[1] === "string"));
  } catch {
    return {};
  }
}

function parseJsonArray(raw: string | null): string[] {
  if (!raw) return [];
  try {
    const parsed: unknown = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.filter((v): v is string => typeof v === "string") : [];
  } catch {
    return [];
  }
}

/**
 * A connection's "admitted under this" fingerprint — what `external-mcp-revocation.ts`'s per-call
 * gate compares a roster connection's row against to catch a delete-then-recreate, a
 * url/command/args/transport/authMode edit, or a rotated/cleared static credential, none of
 * which re-admit an already-running connection (the registry is append-only;
 * `mcp-federation/reload.ts` never re-admits an admitted id).
 *
 * `sealedEnv`'s CIPHERTEXT is included: a `static_env`/`stdio` credential is
 * resealed only when an operator actually submits a new `env` block — an ordinary toggle/rename
 * leaves `env` undefined and carries the existing seal through byte-for-byte (see
 * `resolveExternalMcpSealedEnv`'s `rawEnv === undefined` branch), so the ciphertext is stable across
 * cosmetic saves and only moves when the credential itself is rotated or cleared. On `static_env`
 * rows, `sealedOAuth` holds the dedicated static access token and follows the same preservation rule,
 * so its ciphertext is included too. On OAuth rows it is excluded: re-sealing on token refresh must
 * not refuse an otherwise valid connection.
 *
 * Otherwise deliberately narrow: `label`, `enabled`, both grant lists, OAuth status/expiry/tokens,
 * and `updatedAt` are excluded, because none of them identify WHERE or via WHAT credentials a call
 * reaches the remote, and including any of them would flip the revision on a toggle or a token
 * refresh that must not refuse an already-admitted tool. `createdAt` is included so a delete +
 * re-create under the same id (same url/command, different row) still changes the revision.
 *
 * Hashed rather than kept as plain text, because a hosted row's `url` can itself carry a bearer
 * token as a query parameter — this value is compared, logged, and passed to a model-facing gate, so
 * it must never be a place a credential could leak through.
 *
 * @complexity O(1).
 * @overallScore 100
 */
export function externalMcpAdmissionRevision(
  record: Pick<ExternalMcpServerRecord, "createdAt" | "transport" | "url" | "command" | "args" | "authMode" | "sealedEnv" | "sealedOAuth">,
): string {
  return createHash("sha256")
    .update(
      JSON.stringify([
        record.createdAt,
        record.transport,
        record.url,
        record.command,
        record.args,
        record.authMode,
        record.sealedEnv?.ciphertext ?? null,
        record.authMode === "static_env" ? (record.sealedOAuth?.ciphertext ?? null) : null,
      ]),
    )
    .digest("hex");
}

/** Parses a row's two grant lists the same way {@link resolveExternalMcpConfig} does — shared so
 *  admission and `external-mcp-revocation.ts`'s per-call re-check can never silently disagree about
 *  what a malformed list means (both fail closed to `[]`).
 *  @complexity O(n) in the size of the two JSON blobs. */
export function readExternalMcpToolGrants(
  record: Pick<ExternalMcpServerRecord, "allowedToolNames" | "writeAllowedToolNames">,
): { allowedToolNames: string[]; writeAllowedToolNames: string[] } {
  return {
    allowedToolNames: parseJsonArray(record.allowedToolNames),
    writeAllowedToolNames: parseJsonArray(record.writeAllowedToolNames),
  };
}

/**
 * Parses an operator's `KEY=VALUE`-per-line environment block into a map.
 *
 * Blank lines and `#` comments are skipped so an operator can annotate the block. Everything else
 * must parse: a line without `=` is rejected rather than ignored, because silently dropping what
 * looks like a credential is how a server ends up launching without the token the operator believes
 * they supplied. Only the FIRST `=` splits, so values may contain `=` (base64 padding, connection
 * strings).
 *
 * @param text - Raw textarea content.
 * @returns The parsed variables, in first-seen order.
 * @throws {ExternalMcpValidationError} On a malformed line, an invalid name, a duplicate, or more
 * than {@link MAX_ENV_VARS} variables.
 * @complexity O(n) in the number of lines.
 * @overallScore 100
 */
/** One line of {@link parseEnvBlock}'s input, parsed and name-validated but not yet checked against
 *  the running `env` map (dedup/cap are the loop's own job, since they need cross-line state). Split
 *  out purely to keep `parseEnvBlock`'s cognitive complexity under the shop ceiling — `null` means
 *  "skip this line" (blank or `#` comment), matching the original inline `continue`. */
function parseEnvLine(rawLine: string, index: number): { readonly name: string; readonly value: string } | null {
  const line = rawLine;
  if (line.trim() === "" || line.trimStart().startsWith("#")) return null;

  const separator = line.indexOf("=");
  // Validation reaches the model through the human form; never echo the credential block.
  if (separator <= 0) {
    throw new ExternalMcpValidationError(
      `line ${index + 1} of the environment block is not \`NAME=VALUE\` — correct it in the connection form`,
      "env",
    );
  }

  const name = line.slice(0, separator).trim();
  if (!ENV_NAME_PATTERN.test(name)) {
    throw new ExternalMcpValidationError(
      `line ${index + 1} of the environment block has an invalid variable name (letters, digits and underscore, not starting with a digit)`,
      "env",
    );
  }
  return { name, value: line.slice(separator + 1).trim() };
}

export function parseEnvBlock(text: string): Record<string, string> {
  // JSON is the lossless representation for multiline values; NAME=VALUE remains compatible.
  if (text.trimStart().startsWith('{')) {
    return parseJsonEnvBlock({ text });
  }
  const env: Record<string, string> = {};
  const lines = text.split(/\r?\n/);

  for (const [index, rawLine] of lines.entries()) {
    const parsed = parseEnvLine(rawLine, index);
    if (!parsed) continue;
    // Rejected rather than last-write-wins: two lines setting the same variable means the operator
    // believes both are in effect, and picking one silently is the failure mode this guards.
    if (Object.hasOwn(env, parsed.name)) {
      throw new ExternalMcpValidationError(`environment variable '${parsed.name}' is set more than once`, "env");
    }
    if (Object.keys(env).length >= MAX_ENV_VARS) {
      throw new ExternalMcpValidationError(`at most ${MAX_ENV_VARS} environment variables are supported`, "env");
    }
    if (parsed.value.length > CREDENTIAL_TOKEN_LIMIT) throw new ExternalMcpValidationError("The token exceeds the 8192-character limit. Copy only the token.", "env");
    assertExternalMcpPlainField({ value: parsed.name, field: "env" });
    env[parsed.name] = parsed.value;
  }

  return env;
}

function assertJsonEnvEntry({ name, value }: { name: string; value: unknown }, _options = {}): void {
  if (!ENV_NAME_PATTERN.test(name) || typeof value !== 'string' || value.includes('\0')) throw new ExternalMcpValidationError(CREDENTIAL_MESSAGES.env, 'env');
  assertExternalMcpPlainField({ value: name, field: 'env' });
  if (value.length > CREDENTIAL_TOKEN_LIMIT) throw new ExternalMcpValidationError('The token exceeds the 8192-character limit. Copy only the token.', 'env');
}

function parseJsonEnvBlock({ text }: { text: string }, _options = {}): Record<string, string> {
  let parsed: unknown;
  try { parsed = JSON.parse(text); } catch { throw new ExternalMcpValidationError(CREDENTIAL_MESSAGES.env, 'env'); }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new ExternalMcpValidationError(CREDENTIAL_MESSAGES.env, 'env');
  const entries = Object.entries(parsed);
  if (entries.length > MAX_ENV_VARS) throw new ExternalMcpValidationError(`at most ${MAX_ENV_VARS} environment variables are supported`, 'env');
  for (const [name, value] of entries) assertJsonEnvEntry({ name, value });
  return Object.fromEntries(entries) as Record<string, string>;
}

/**
 * Splits an operator's space-separated argv string.
 *
 * One quoting rule, and only one: a token that STARTS with `"` runs to the next `"`, which must end
 * the token (whitespace or end of string after it), and both quotes are dropped. That is what lets a
 * path with a space in it — `"C:\\Users\\John Smith\\..."`, the desktop shell's win32
 * registration — arrive as one argument. There are no escapes (a backslash is always literal, since
 * Windows paths are full of them), and a `"` anywhere else in a token stays literal exactly as it did
 * before this rule existed, so `--name="x"` still reaches the child unchanged. This is NOT shell
 * quoting: the command is spawned WITHOUT a shell (`adapter.stdio.ts` uses `spawn` with an argv
 * array), and nothing else a shell would do happens here.
 *
 * @throws {ExternalMcpValidationError} On an unterminated quoted token, a closing quote followed by
 *   more characters, or more than `MAX_ARGS` arguments.
 * @complexity O(n) in the string length.
 */
export function parseArgs(raw: string): string[] {
  const args: string[] = [];
  let index = 0;
  while (index < raw.length) {
    if (/\s/.test(raw[index]!)) {
      index += 1;
      continue;
    }
    const token = raw[index] === '"' ? readQuotedArg(raw, index) : readBareArg(raw, index);
    args.push(token.value);
    index = token.end;
  }
  if (args.length > MAX_ARGS) {
    throw new ExternalMcpValidationError(`at most ${MAX_ARGS} arguments are supported`, "args");
  }
  return args;
}

/** {@link parseArgs}'s unquoted token: everything up to the next whitespace, quotes included. */
function readBareArg(raw: string, start: number): { readonly value: string; readonly end: number } {
  const match = /\s/.exec(raw.slice(start));
  const end = match === null ? raw.length : start + match.index;
  return { value: raw.slice(start, end), end };
}

/** {@link parseArgs}'s quoted token, `start` pointing at its opening `"`.
 *  @throws {ExternalMcpValidationError} When the quote never closes, or does not end the token. */
function readQuotedArg(raw: string, start: number): { readonly value: string; readonly end: number } {
  const close = raw.indexOf('"', start + 1);
  if (close === -1) {
    throw new ExternalMcpValidationError("an argument opens a double quote that never closes", "args");
  }
  const end = close + 1;
  if (end < raw.length && !/\s/.test(raw[end]!)) {
    throw new ExternalMcpValidationError("a closing double quote must be followed by a space or the end of the arguments", "args");
  }
  return { value: raw.slice(start + 1, close), end };
}

/**
 * Splits an operator's comma-separated list of remote tool names, shared by {@link
 * parseAllowedToolNames} and {@link parseWriteAllowedToolNames} — the two lists use the identical
 * charset, cap and dedup rule, and differ only in which field a rejection names.
 *
 * An empty result is a legitimate, meaningful value on either list — it yields a server that
 * contributes (or write-authorizes) zero tools — so it is returned rather than rejected. That is the
 * safe direction and matches `trust.ts` R2's default-deny posture.
 *
 * @throws {ExternalMcpValidationError} On a name the trust tier would refuse anyway, so the operator
 * learns at save time instead of discovering an unexplained absence after a restart.
 * @complexity O(n) in the number of names.
 */
function parseToolNameList(raw: string, field: string): string[] {
  const names = raw
    .split(",")
    .map((part) => part.trim())
    .filter((part) => part.length > 0);

  if (names.length > MAX_ALLOWED_TOOLS) {
    throw new ExternalMcpValidationError(`at most ${MAX_ALLOWED_TOOLS} tools are supported`, field);
  }
  for (const name of names) {
    if (!REMOTE_TOOL_NAME_PATTERN.test(name)) {
      throw new ExternalMcpValidationError(
        `'${name}' is not a valid MCP tool name, so the trust tier would refuse it on connect`,
        field,
      );
    }
  }
  return [...new Set(names)];
}

/**
 * Splits an operator's comma-separated allowlist of remote tool names.
 *
 * @throws {ExternalMcpValidationError} See {@link parseToolNameList}. `field` is `"allowedToolNames"`.
 * @complexity O(n) in the number of names.
 * @overallScore 100
 */
export function parseAllowedToolNames(raw: string): string[] {
  return parseToolNameList(raw, "allowedToolNames");
}

/**
 * Splits an operator's comma-separated list of remote tool names separately authorized to write —
 * `trust.ts` R3's override, checked only after {@link parseAllowedToolNames}'s allowlist passes (see
 * {@link assertWriteAllowlistSubset}).
 *
 * @throws {ExternalMcpValidationError} See {@link parseToolNameList}. `field` is
 * `"writeAllowedToolNames"`.
 * @complexity O(n) in the number of names.
 * @overallScore 100
 */
export function parseWriteAllowedToolNames(raw: string): string[] {
  return parseToolNameList(raw, "writeAllowedToolNames");
}

/**
 * C-006: a tool may be write-authorized only if it is ALSO allowlisted. Enforced at save time so an
 * operator learns of the mistake immediately rather than the entry sitting inert (or, worse, being
 * misread as intentional) until a boot-time report surfaces it.
 *
 * @throws {ExternalMcpValidationError} Naming the first write-authorized tool absent from the
 * allowlist, with `field === "writeAllowedToolNames"`.
 * @complexity O(n) in the number of write-authorized names.
 */
function assertWriteAllowlistSubset(writeAllowedToolNames: readonly string[], allowedToolNames: readonly string[]): void {
  const allowed = new Set(allowedToolNames);
  for (const name of writeAllowedToolNames) {
    if (!allowed.has(name)) {
      throw new ExternalMcpValidationError(
        `'${name}' is authorized to write but is not in the allowlist — a tool must be allowlisted before it can be write-authorized`,
        "writeAllowedToolNames",
      );
    }
  }
}

/** Whether two tool-name lists name the same SET of tools, ignoring order — the write list is a set
 *  of operator decisions, not an ordered sequence, so a save that re-sends the same names in a
 *  different order must not read as a change. Used only to decide whether {@link
 *  resolveWriteGrantAttribution} owes a new attribution.
 *  @complexity O(n) in the longer list. */
function toolNameSetsEqual(a: readonly string[], b: readonly string[]): boolean {
  if (a.length !== b.length) return false;
  const setB = new Set(b);
  return a.every((name) => setB.has(name));
}

/** A row's OAuth status, defaulting an absent or unrecognized value to `disconnected` — the safe
 *  direction, since it is the state in which no token is used and the operator is prompted. */
export function resolveExternalMcpOAuthStatus(record: Pick<ExternalMcpServerRecord, "oauthStatus">): ExternalMcpOAuthStatus {
  const status = record.oauthStatus;
  return status !== null && EXTERNAL_MCP_OAUTH_STATUSES.includes(status as ExternalMcpOAuthStatus)
    ? (status as ExternalMcpOAuthStatus)
    : "disconnected";
}

/**
 * Whether this row holds an access TOKEN — answered from PLAINTEXT columns alone, never by unsealing.
 *
 * Token clearing preserves the client secret sharing the sealed blob (setOAuthStatus). A
 * disconnected row can therefore have a non-null blob containing a secret but no access token;
 * blob presence alone cannot answer this question.
 *
 * Not repaired by unsealing, deliberately. This is read by a plain list route that must answer
 * without a keyring round trip, and must keep answering TRUTHFULLY for a row whose blob will not
 * open at all: a rotated site key, or a legacy `aad_version 0` ciphertext. A decrypt here would turn
 * either into a failed settings tab, and would put a keyring dependency on a read path that has
 * never had one.
 *
 * The blob check leads because it is the NECESSARY condition — no blob, no token, whatever the
 * plaintext says. Each of the two disjuncts after it is independently SUFFICIENT, which is what
 * makes a false positive unreachable:
 *
 * - `connected` is written by exactly one place, `persistTokens`, and that same upsert writes the
 *   tokens. Every path that clears a token moves the row off `connected` in the same write.
 * - `oauthExpiresAt` is written beside the tokens by that same `persistTokens`, and nulled by every
 *   clear (`setOAuthStatus`'s `clearToken` branch) and by every save that invalidates the token
 *   ({@link carryOAuthRuntimeState}), so a non-null expiry cannot outlive the token it describes.
 *
 * @returns `true` only when a token is stored. The single state it can UNDER-report is a token
 * issued with no `expires_in` — RFC 6749 §5.1 makes it optional and `platform/oauth/token-endpoint
 * .ts` stores `null` rather than fabricating one — on a row that has since moved off `connected`
 * without its token being cleared: a re-connect left `pending`, or a terminal device-poll failure.
 * Under-reporting is the safe direction, and closing it exactly needs a plaintext token-presence
 * column, which is a schema change rather than a read fix.
 * @complexity O(1) — three field reads, no I/O.
 */
export function externalMcpRecordHasStoredToken(
  record: Pick<ExternalMcpServerRecord, "sealedOAuth" | "oauthStatus" | "oauthExpiresAt">,
): boolean {
  if (record.sealedOAuth === null) return false;
  return resolveExternalMcpOAuthStatus(record) === "connected" || record.oauthExpiresAt !== null;
}

async function externalMcpEnvHints({ record, sealer }: { record: ExternalMcpServerRecord; sealer?: SecretSealerPort }, _options = {}) {
  const envTokenHints: Record<string, CredentialTokenHint> = {};
  if (!sealer || !record.sealedEnv) return envTokenHints;
  const opened = await openExternalMcpEnv(record, sealer);
  if (!opened.ok) return envTokenHints;
  for (const [name, value] of Object.entries(opened.env)) {
    if (typeof value === 'string') envTokenHints[name] = credentialTokenHint({ token: value });
  }
  return envTokenHints;
}

async function externalMcpAccessTokenHint({ record, sealer }: { record: ExternalMcpServerRecord; sealer?: SecretSealerPort }, _options = {}) {
  let accessTokenHint: CredentialTokenHint | null = null;
  if (sealer && record.sealedOAuth) {
    try {
      const payload = await openExternalMcpOAuthPayload(sealer, record);
      const token = payload.staticAccessToken ?? payload.tokens?.accessToken;
      if (token) accessTokenHint = credentialTokenHint({ token });
    } catch { /* A rotated site key must not prevent listing non-secret metadata. */ }
  }
  return accessTokenHint;
}

async function toView(record: ExternalMcpServerRecord, sealer?: SecretSealerPort): Promise<ExternalMcpServerView> {
  const envTokenHints = await externalMcpEnvHints({ record, sealer });
  const accessTokenHint = await externalMcpAccessTokenHint({ record, sealer });
  return {
    serverId: record.serverId,
    label: record.label ?? record.serverId,
    provisionedByPluginId: record.provisionedByPluginId,
    transport: record.transport,
    authMode: resolveExternalMcpAuthMode(record),
    enabled: record.enabled,
    command: record.command ?? "",
    url: record.url,
    args: parseJsonArray(record.args),
    allowedToolNames: parseJsonArray(record.allowedToolNames),
    writeAllowedToolNames: parseJsonArray(record.writeAllowedToolNames),
    writeGrantsUpdatedByPrincipalId: record.writeGrantsUpdatedByPrincipalId,
    writeGrantsUpdatedAt: record.writeGrantsUpdatedAt,
    envNames: parseJsonArray(record.envNames),
    hasAccessToken: externalMcpRecordHasStaticAccessToken(record),
    accessTokenHint,
    ...(Object.keys(envTokenHints).length ? { envTokenHints } : {}),
    accessTokenEnvName: resolveExternalMcpAuthMode(record) === "static_env" ? record.oauthTokenEnvName : null,
    oauth: {
      providerId: record.oauthProviderId,
      grant: record.oauthGrant,
      clientId: record.oauthClientId,
      scopes: parseJsonArray(record.oauthScopesJson),
      status: resolveExternalMcpOAuthStatus(record),
      expiresAt: record.oauthExpiresAt,
      tokenEnvName: record.oauthTokenEnvName,
      hasStoredToken: externalMcpRecordHasStoredToken(record),
    },
  };
}

/**
 * Lists the workspace's servers for the admin tab. The tab has no use for env
 * values and must not be a route that decrypts them. Token hints alone are now derived by
 * server-side unsealing, per the owner decision; no secret value is returned.
 *
 * @complexity O(n) in the stored server count.
 * @overallScore 100
 */
export async function listExternalMcpServerViews(
  deps: Pick<ExternalMcpStoreDeps, "repo"> & Partial<Pick<ExternalMcpStoreDeps, "sealer">>,
  workspaceId: UUID,
): Promise<ExternalMcpServerView[]> {
  const records = await deps.repo.listByWorkspaceId(workspaceId);
  return Promise.all(records.map(record => toView(record, deps.sealer)));
}

/**
 * Reads and decrypts every ENABLED server, for the daemon's boot-time federation pass.
 *
 * A row whose sealed env cannot be opened is SKIPPED rather than thrown on, and the reason is
 * returned in `failures`. This mirrors `bootstrap.ts`'s fail-open posture for the same reason: a
 * rotated site key or a corrupt row must not stop the daemon booting, and one unusable server must
 * not take out a second working one. Disabled rows never reach the sealer at all.
 *
 * @returns The usable configs plus a per-server accounting of what could not be read.
 * @complexity O(n) in the enabled server count, one unseal each.
 * @overallScore 100
 */
/** Opens `record`'s sealed env block, or returns `{}` when there is none to open. Split out of
 *  {@link resolveExternalMcpConfig} purely to keep that function's complexity under the shop
 *  ceiling — a decrypt failure is reported through the same ok/reason shape the caller already
 *  threads through, not thrown, since one unreadable server must not abort the whole read. */
async function openExternalMcpEnv(
  record: Pick<ExternalMcpServerRecord, "sealedEnv" | "workspaceId" | "serverId" | "aadVersion">,
  sealer: Pick<SecretSealerPort, "open">,
): Promise<{ readonly ok: true; readonly env: Record<string, string> } | { readonly ok: false; readonly reason: string }> {
  if (record.sealedEnv === null) return { ok: true, env: {} };
  try {
    const env = await openExternalMcpVaultPayload({ sealer, sealed: record.sealedEnv, identity: record, kind: "mcp-env" }) as Record<string, string>;
    return { ok: true, env };
  } catch {
    // These reasons reach admissions and chat tools. Parser/sealer errors can contain secret plaintext.
    return { ok: false, reason: "stored credentials could not be decrypted — check the site credential store and re-enter them in Settings → External MCP" };
  }
}

/**
 * Resolves an `oauth` row's contribution to the child environment.
 *
 * Kept behind a port rather than inlined, so this store never imports a token endpoint, a refresher,
 * or `src/platform/oauth/` at all: the boot path asks for a token, and whoever wired the daemon decides where
 * it comes from. That is also what keeps this module testable without a network.
 */
export interface ExternalMcpOAuthTokenResolverPort {
  /**
   * Returns the access token to inject, refreshing first when it is due.
   *
   * @throws When the connection needs re-authorization or the provider could not be reached. The
   * caller turns that into a per-server failure entry rather than letting it abort the whole read.
   */
  resolveAccessToken(input: { serverId: string }): Promise<string>;
}

/**
 * A `needs_reauth`/`disconnected`/`pending` row is reported rather than connected.
 *
 * Reported, not silently skipped: an operator whose token expired needs to see WHY the server's
 * tools vanished, and the reason string is the only thing carrying that at boot. The admin tab's
 * `needs_reauth` badge is the out-of-band half of the same signal.
 */
function oauthStatusFailure(record: ExternalMcpServerRecord): string | null {
  const status = resolveExternalMcpOAuthStatus(record);
  if (status === "connected") return null;
  if (status === "needs_reauth") {
    return "its authorization expired or was revoked — reconnect it in Settings → External MCP";
  }
  return `it has not been authorized yet (status '${status}') — connect it in Settings → External MCP`;
}

/**
 * Obtains one record's OAuth access token, or explains why it cannot be.
 *
 * Returns the raw token rather than a placement, because WHERE it goes is the transport's business:
 * a child-process variable for `stdio`, an `Authorization` header for a hosted endpoint. Splitting
 * "can we get a token" from "where does it go" is what stops the second question's answer from
 * being duplicated per transport.
 *
 * @complexity O(1) plus at most one token refresh round trip.
 */
async function resolveExternalMcpAccessToken(
  record: ExternalMcpServerRecord,
  oauth: ExternalMcpOAuthTokenResolverPort | undefined,
): Promise<{ readonly ok: true; readonly token: string } | { readonly ok: false; readonly reason: string }> {
  const statusFailure = oauthStatusFailure(record);
  if (statusFailure !== null) return { ok: false, reason: statusFailure };
  if (!oauth) {
    return { ok: false, reason: "this process was not wired with an OAuth token resolver, so its access token cannot be obtained" };
  }
  try {
    return { ok: true, token: await oauth.resolveAccessToken({ serverId: record.serverId }) };
  } catch (err) {
    // Preserve reauthorization as a typed outcome, without echoing raw provider error messages.
    const needsReauth = err instanceof Error && "code" in err && err.code === "EXTERNAL_MCP_REAUTH_REQUIRED";
    return { ok: false, reason: needsReauth
      ? "its authorization expired or was revoked — reconnect it in Settings → External MCP"
      : "its OAuth access token could not be obtained: OAuth token resolution failed — reconnect this server in Settings → External MCP" };
  }
}

/** A failure entry for one record, in the shape {@link readEnabledExternalMcpConfigs} collects. */
function externalMcpFailure(record: ExternalMcpServerRecord, reason: string): { readonly ok: false; readonly failure: { serverId: string; reason: string } } {
  return { ok: false, failure: { serverId: record.serverId, reason } };
}

/**
 * Builds a `stdio` row's target: its pasted environment, plus the access token under the operator's
 * chosen variable name when the row is OAuth-authenticated.
 *
 * The two credential sources compose rather than exclude: a server can need a pasted `BASE_URL` AND
 * an OAuth bearer token. The OAuth-derived variable is applied LAST so it cannot be shadowed by a
 * stale hand-typed copy of the same name in the pasted block.
 */
async function resolveStdioTarget(
  record: ExternalMcpServerRecord,
  env: Record<string, string>,
  authMode: ExternalMcpAuthMode,
  oauth: ExternalMcpOAuthTokenResolverPort | undefined,
  staticAccessToken: string | null,
): Promise<{ readonly ok: true; readonly target: ExternalMcpServerTarget } | { readonly ok: false; readonly failure: { serverId: string; reason: string } }> {
  if (!record.command) return externalMcpFailure(record, "no command is configured to launch it");

  const withStaticToken = withStaticAccessToken(record, env, authMode, staticAccessToken);
  if (withStaticToken === null) {
    return externalMcpFailure(record, "no environment variable name is configured to receive its access token");
  }
  let resolvedEnv = withStaticToken;
  if (authMode === "oauth") {
    if (!record.oauthTokenEnvName) {
      return externalMcpFailure(record, "no environment variable name is configured to receive its OAuth access token");
    }
    const token = await resolveExternalMcpAccessToken(record, oauth);
    if (!token.ok) return externalMcpFailure(record, token.reason);
    resolvedEnv = { ...resolvedEnv, [record.oauthTokenEnvName]: token.token };
  }

  return { ok: true, target: { kind: "stdio", command: record.command, args: parseJsonArray(record.args), env: resolvedEnv } };
}

/**
 * Builds a hosted row's target: its endpoint, plus the bearer header when the row is
 * OAuth-authenticated.
 *
 * A hosted row's pasted `env` block is deliberately NOT turned into headers. An operator typing
 * `FOO=bar` means an environment variable, and silently promoting it to a request header would send
 * a value they scoped to a local process to a third party over the network. A hosted server's static
 * credential is the dedicated `static_env` access token instead: typed for THIS endpoint, and sent as
 * `Authorization: Bearer`.
 */
async function resolveHttpTarget(
  record: ExternalMcpServerRecord,
  authMode: ExternalMcpAuthMode,
  oauth: ExternalMcpOAuthTokenResolverPort | undefined,
  staticAccessToken: string | null,
): Promise<{ readonly ok: true; readonly target: ExternalMcpServerTarget } | { readonly ok: false; readonly failure: { serverId: string; reason: string } }> {
  if (!record.url) return externalMcpFailure(record, "no URL is configured to reach it");

  const headers: Record<string, string> = {};
  if (authMode === "static_env" && staticAccessToken !== null) headers.authorization = `Bearer ${staticAccessToken}`;
  if (authMode === "oauth") {
    const token = await resolveExternalMcpAccessToken(record, oauth);
    if (!token.ok) return externalMcpFailure(record, token.reason);
    headers.authorization = `Bearer ${token.token}`;
  }

  if (headers.authorization !== undefined) {
    const failure = hostedTokenFailure({ authorization: headers.authorization });
    if (failure !== null) return externalMcpFailure(record, failure);
  }
  return { ok: true, target: { kind: "streamable_http", url: record.url, headers } };
}

function hostedTokenFailure({ authorization }: { authorization: string }, _options = {}): string | null {
  try { assertCredentialToken({ value: authorization.slice('Bearer '.length), hosted: true }); }
  catch (err) { return err instanceof CredentialInputError ? err.message : CREDENTIAL_MESSAGES.ascii; }
  return null;
}

/**
 * `env` with a `static_env` row's access token applied under its variable name — LAST, as the OAuth
 * token is in {@link resolveStdioTarget}, so a stale pasted copy of the same variable cannot shadow it.
 *
 * @returns `env` unchanged when the row holds no static token; `null` when it holds one but names no
 *   variable to put it in (the save path refuses that, so reaching it means another writer).
 * @complexity O(n) in the env variable count.
 */
function withStaticAccessToken(
  record: Pick<ExternalMcpServerRecord, "oauthTokenEnvName">,
  env: Record<string, string>,
  authMode: ExternalMcpAuthMode,
  staticAccessToken: string | null,
): Record<string, string> | null {
  if (authMode !== "static_env" || staticAccessToken === null) return env;
  if (!record.oauthTokenEnvName) return null;
  return { ...env, [record.oauthTokenEnvName]: staticAccessToken };
}

/**
 * Opens a `static_env` row's sealed access token, or resolves `null` when it holds none — without
 * touching the sealer for any other row. A blob that will not open is a per-row failure, the same
 * posture {@link openExternalMcpEnv} takes for the env block.
 *
 * @complexity O(1) — at most one unseal.
 */
async function openExternalMcpStaticAccessToken(
  record: ExternalMcpServerRecord,
  sealer: Pick<SecretSealerPort, "open">,
): Promise<{ readonly ok: true; readonly token: string | null } | { readonly ok: false; readonly reason: string }> {
  if (!externalMcpRecordHasStaticAccessToken(record)) return { ok: true, token: null };
  try {
    const payload = await openExternalMcpOAuthPayload(sealer, record);
    return { ok: true, token: payload.staticAccessToken ?? null };
  } catch {
    // Never put decrypted payloads or cryptographic exception text into an operator/model response.
    return { ok: false, reason: "its stored access token could not be decrypted — re-enter it in Settings → External MCP" };
  }
}

/** Resolves one ENABLED record into either a usable config or a failure entry, for
 *  {@link readEnabledExternalMcpConfigs}'s loop. */
async function resolveExternalMcpConfig(
  record: ExternalMcpServerRecord,
  sealer: Pick<SecretSealerPort, "open">,
  oauth: ExternalMcpOAuthTokenResolverPort | undefined,
): Promise<
  | { readonly ok: true; readonly config: ExternalMcpServerConfig }
  | { readonly ok: false; readonly failure: { serverId: string; reason: string } }
> {
  const transport = record.transport as ExternalMcpTransport;
  if (!SUPPORTED_EXTERNAL_MCP_TRANSPORTS.includes(transport)) {
    return externalMcpFailure(record, `unsupported transport '${record.transport}'`);
  }
  const opened = await openExternalMcpEnv(record, sealer);
  if (!opened.ok) return externalMcpFailure(record, opened.reason);

  const authMode = resolveExternalMcpAuthMode(record);
  const staticToken = await openExternalMcpStaticAccessToken(record, sealer);
  if (!staticToken.ok) return externalMcpFailure(record, staticToken.reason);
  const resolved =
    transport === "stdio"
      ? await resolveStdioTarget(record, opened.env, authMode, oauth, staticToken.token)
      : await resolveHttpTarget(record, authMode, oauth, staticToken.token);
  if (!resolved.ok) return resolved;

  const grants = readExternalMcpToolGrants(record);
  return {
    ok: true,
    config: {
      serverId: record.serverId,
      ...(record.provisionedByPluginId ? { provisionedByPluginId: record.provisionedByPluginId } : {}),
      label: record.label ?? record.serverId,
      transport,
      authMode,
      enabled: true,
      allowedToolNames: grants.allowedToolNames,
      writeAllowedToolNames: grants.writeAllowedToolNames,
      target: resolved.target,
      admissionRevision: externalMcpAdmissionRevision(record),
    },
  };
}

export async function readEnabledExternalMcpConfigs(
  deps: Pick<ExternalMcpStoreDeps, "repo" | "sealer"> & { oauth?: ExternalMcpOAuthTokenResolverPort },
  workspaceId: UUID,
): Promise<{ configs: ExternalMcpServerConfig[]; failures: { serverId: string; reason: string }[] }> {
  const records = await deps.repo.listByWorkspaceId(workspaceId);
  const configs: ExternalMcpServerConfig[] = [];
  const failures: { serverId: string; reason: string }[] = [];

  for (const record of records) {
    if (!record.enabled) continue;
    const resolved = await resolveExternalMcpConfig(record, deps.sealer, deps.oauth);
    if (resolved.ok) configs.push(resolved.config);
    else failures.push(resolved.failure);
  }

  return { configs, failures };
}

/**
 * Maps stored configs onto the shape `mcp-federation/bootstrap.ts` consumes.
 *
 * Timeouts and caps come from core's shared `FEDERATED_CONNECTION_DEFAULTS` rather than being
 * stored per server: they are policy about how much a third party may cost this process, which is
 * Tovu's call and not an operator preference. `allowedToolNames` is the one field that IS the
 * operator's, and it is passed through untouched for `trust.ts` to enforce.
 *
 * @param readOnlyRemoteNamesByServer - Reviewed manifest lists matched by the roster source;
 * never inferred from remote annotations or the tool admission allowlist.
 * @complexity O(n) time and output space in the config count.
 */
export function toResolvedFederatedConnections(
  configs: readonly ExternalMcpServerConfig[],
  readOnlyRemoteNamesByServer: ReadonlyMap<string, ReadonlySet<string>> = new Map(),
): ResolvedFederatedConnection[] {
  return configs.map((config) => ({
    config: {
      connectionId: config.serverId,
      label: config.label,
      allowedToolNames: config.allowedToolNames,
      writeAllowedToolNames: config.writeAllowedToolNames,
      ...(readOnlyRemoteNamesByServer.has(config.serverId) ? { readOnlyRemoteNames: readOnlyRemoteNamesByServer.get(config.serverId)! } : {}),
      connectTimeoutMs: FEDERATED_CONNECTION_DEFAULTS.connectTimeoutMs,
      callTimeoutMs: FEDERATED_CONNECTION_DEFAULTS.callTimeoutMs,
      maxResultBytes: FEDERATED_CONNECTION_DEFAULTS.maxResultBytes,
      maxTools: FEDERATED_CONNECTION_DEFAULTS.maxTools,
      origin: { kind: "roster", admissionRevision: config.admissionRevision },
    },
    launch: toFederatedLaunchSpec(config.target),
  }));
}

/** Maps a resolved target onto the federation layer's launch spec. The two shapes are deliberately
 *  separate — this one is the store's, that one is federation's — so neither domain has to widen
 *  when the other gains a field. */
function toFederatedLaunchSpec(target: ExternalMcpServerTarget): McpLaunchSpec {
  if (target.kind === "streamable_http") return { url: target.url, headers: target.headers };
  return {
    command: target.command,
    args: target.args,
    // The child's environment REPLACES the daemon's rather than extending it, matching the
    // Supabase preset. `PATH`/`HOME`/`TMPDIR` are added by the launcher, not here; anything else
    // a server needs is an explicit, written-down grant in its own env block.
    env: target.env,
  };
}

/**
 * The OAuth half of a save. Every field follows the same three-state rule `env` established:
 * ABSENT keeps what is stored, a STRING replaces it, an EMPTY string clears it.
 *
 * Structural validation only happens here — charsets, lengths, required-when-oauth. Whether
 * `providerId` names a registered descriptor, and whether the endpoints form a usable provider, is
 * `external-mcp-oauth.ts`'s call: resolving a descriptor is the flow module's job, and importing its
 * registry here would put the store back in the business of the thing its header says it is not.
 */
export interface SaveExternalMcpOAuthInput {
  /** A registered provider id, or empty to define this connection's own endpoints below — or, on a
   *  REMOTE connection, to leave both to discovery at connect time. */
  providerId?: string;
  grant?: string;
  /** Empty on a remote connection means "mint one by dynamic client registration at connect". */
  clientId?: string;
  /** SECRET. Sealed, never returned by any read model. */
  clientSecret?: string;
  /** Raw operator input, comma- or space-separated. */
  scopes?: string;
  /** For `stdio`: which child env variable receives the access token. */
  tokenEnvName?: string;
  authorizationEndpoint?: string;
  tokenEndpoint?: string;
  deviceAuthorizationEndpoint?: string;
}

export interface SaveExternalMcpServerInput {
  workspaceId: UUID;
  serverId: string;
  label?: string;
  transport: string;
  /** One of {@link EXTERNAL_MCP_AUTH_MODES}. Absent keeps an existing row's mode, or defaults a new
   *  row to `static_env` — the mode every row written before this field existed effectively had. */
  authMode?: string;
  enabled: boolean;
  command: string;
  /** Endpoint for a remote transport. Required for `streamable_http`, ignored for `stdio`. */
  url?: string;
  /** Raw operator input, space-separated. */
  args: string;
  /** Raw operator input, comma-separated remote tool names. */
  allowedToolNames: string;
  /** Raw operator input, comma-separated remote tool names the operator separately authorizes to
   *  write. Same shape and same "resent in full on every save" convention as {@link
   *  allowedToolNames} — this is NOT tri-state like {@link env}, because the admin tab shows this
   *  list in the clear and can always resend it. Rejected at save (C-006) if it names a tool absent
   *  from {@link allowedToolNames}. Defaulted defensively to `""` if a caller omits it, so a route or
   *  test written before this field existed degrades to "no write grants" rather than throwing. */
  writeAllowedToolNames: string;
  /** Raw operator input, `KEY=VALUE` per line. `undefined` leaves an existing block untouched. */
  env?: string;
  /** SECRET, `static_env` only. Sealed, never returned by any read model. Three-state like {@link env}:
   *  `undefined` keeps the stored token, a string replaces it, `""` clears it. Delivered as
   *  {@link accessTokenEnvName} to a stdio child, or as `Authorization: Bearer` to a hosted server. */
  accessToken?: string;
  /** For `stdio` + `static_env`: which child env variable receives {@link accessToken}. `undefined`
   *  keeps the stored name. */
  accessTokenEnvName?: string;
  oauth?: SaveExternalMcpOAuthInput;
  /**
   * Set ONLY by `features/agent-plugins/federate-mcp.ts`, on the ONE save that creates a brand-new
   * plugin-provisioned row. Every other caller (the admin PUT route, the assistant's own
   * `external_mcp_save` tool) omits this field entirely, and an omitted field PRESERVES whatever the
   * row already has — the same three-state rule `env` establishes, minus the "empty string clears
   * it" arm: nothing should ever intentionally clear this column once set, so no clear signal is
   * defined for it. See `schema.sqlite.ts`'s `provisioned_by_plugin_id` doc for the full rule.
   */
  provisionedByPluginId?: string;
  /**
   * The principal performing this save, threaded from `getAuthedPrincipal(res)` at the route. Used
   * ONLY to attribute a change to {@link writeAllowedToolNames} — see {@link
   * resolveWriteGrantAttribution}. Required so every new caller has to supply one; a caller that
   * never touches the write list never reads it, so an un-migrated caller cannot crash on its
   * absence (see that function's doc).
   */
  principalId: string;
}

/**
 * Validates and persists one server, sealing its env block.
 *
 * `env: undefined` preserves whatever is already stored, which is what lets the tab patch `enabled`
 * or `label` without the operator re-typing credentials the UI never sent them. `env: ""` is the
 * distinct, explicit "clear the credentials" instruction — the same unset-vs-empty distinction
 * `mcp-federation/config.ts` draws for allowlists, and for the same reason.
 *
 * @throws {ExternalMcpValidationError} On any invalid operator input.
 * @throws {ExternalMcpSecretStoreUnconfiguredError} When no site key is available to seal under.
 * @complexity O(n) in the size of the env block.
 * @overallScore 100
 */
/** Validates `serverId` via the trust tier's own assertion, remapped onto this store's own error
 *  type. Split out purely to keep {@link saveExternalMcpServer}'s complexity under the shop
 *  ceiling — reuses `trust.ts`'s rule rather than restating it, since this id becomes part of every
 *  federated tool id and two copies of that rule could drift. */
function assertValidExternalMcpServerId(serverId: string): void {
  try {
    assertValidConnectionId({ connectionId: serverId });
  } catch (err) {
    throw new ExternalMcpValidationError(err instanceof Error ? err.message : String(err), "id");
  }
}

function assertSupportedExternalMcpTransport(transport: string): void {
  if (!SUPPORTED_EXTERNAL_MCP_TRANSPORTS.includes(transport as ExternalMcpTransport)) {
    throw new ExternalMcpValidationError(
      `transport '${transport}' is not supported — only ${SUPPORTED_EXTERNAL_MCP_TRANSPORTS.join(", ")} is implemented`,
      "transport",
    );
  }
}

/** Resolves the auth mode for one save: explicit input wins, then the existing row's mode, then
 *  `static_env` for a brand-new row.
 *  @throws {ExternalMcpValidationError} On a mode outside {@link EXTERNAL_MCP_AUTH_MODES}. */
function resolveSavedAuthMode(input: SaveExternalMcpServerInput, existing: ExternalMcpServerRecord | null): ExternalMcpAuthMode {
  if (input.authMode === undefined) return existing ? resolveExternalMcpAuthMode(existing) : "static_env";
  if (!EXTERNAL_MCP_AUTH_MODES.includes(input.authMode as ExternalMcpAuthMode)) {
    throw new ExternalMcpValidationError(
      `auth mode '${input.authMode}' is not supported — expected one of ${EXTERNAL_MCP_AUTH_MODES.join(", ")}`,
      "authMode",
    );
  }
  return input.authMode as ExternalMcpAuthMode;
}

/**
 * Splits an operator's comma- or space-separated OAuth scope list.
 *
 * An empty result is legitimate — several providers infer scope from the client registration — so it
 * is returned rather than rejected, the same call {@link parseAllowedToolNames} makes.
 *
 * @throws {ExternalMcpValidationError} Past {@link MAX_OAUTH_SCOPES}.
 * @complexity O(n) in the number of scopes.
 */
export function parseOAuthScopes(raw: string): string[] {
  const scopes = raw.split(/[\s,]+/).filter((part) => part.length > 0);
  if (scopes.length > MAX_OAUTH_SCOPES) {
    throw new ExternalMcpValidationError(`at most ${MAX_OAUTH_SCOPES} OAuth scopes are supported`, "oauth.scopes");
  }
  return [...new Set(scopes)];
}

/** The endpoints an operator typed for a connection that defines its own provider. Empty strings are
 *  dropped so `{}` — "this connection names a registered provider instead" — stays representable. */
function buildOAuthEndpoints(oauth: SaveExternalMcpOAuthInput): Record<string, string> {
  const entries: readonly (readonly [string, string | undefined])[] = [
    ["authorizationEndpoint", oauth.authorizationEndpoint],
    ["tokenEndpoint", oauth.tokenEndpoint],
    ["deviceAuthorizationEndpoint", oauth.deviceAuthorizationEndpoint],
  ];
  const endpoints: Record<string, string> = {};
  for (const [key, value] of entries) {
    const trimmed = value?.trim();
    if (trimmed) endpoints[key] = trimmed;
  }
  return endpoints;
}

/**
 * The identity a stored token was issued under.
 *
 * Compared before and after a save so a token cannot silently survive a change that invalidates it:
 * a new client id, a different provider, a re-pointed token endpoint or a changed scope list all mean
 * the stored access token no longer corresponds to what the row now says. Keeping it would leave a
 * connection reporting `connected` while holding a credential for something else — which then fails
 * opaquely at a tool call instead of loudly at save time.
 *
 * @complexity O(1).
 */
function oauthBindingFingerprint(
  record: Pick<ExternalMcpServerRecord, "oauthProviderId" | "oauthGrant" | "oauthClientId" | "oauthEndpointsJson" | "oauthScopesJson">,
): string {
  return JSON.stringify([
    record.oauthProviderId,
    record.oauthGrant,
    record.oauthClientId,
    record.oauthEndpointsJson,
    record.oauthScopesJson,
  ]);
}

/** The OAuth columns produced by one save, plus the operator's client-secret instruction. */
interface ResolvedOAuthFields {
  readonly oauthProviderId: string | null;
  readonly oauthGrant: string | null;
  readonly oauthClientId: string | null;
  readonly oauthEndpointsJson: string | null;
  readonly oauthScopesJson: string | null;
  readonly oauthTokenEnvName: string | null;
  /** Three-state, as `env` is: `undefined` keeps, a string replaces, `""` clears. */
  readonly clientSecret: string | undefined;
}

/**
 * Validates and resolves the OAuth columns for one save.
 *
 * @throws {ExternalMcpValidationError} On any invalid operator input, with `field` naming the
 * offending form control (`oauth.clientId`, `oauth.grant`, ...).
 * @complexity O(n) in the number of scopes.
 */
/** The OAuth columns of a row that is NOT OAuth-authenticated: all cleared.
 *
 *  Cleared rather than preserved, deliberately: a row switched to `static_env` that still carried a
 *  provider and a client id would silently re-adopt them if it were ever switched back, along with a
 *  token issued under configuration nobody has looked at since. */
const NO_OAUTH_FIELDS: ResolvedOAuthFields = {
  oauthProviderId: null,
  oauthGrant: null,
  oauthClientId: null,
  oauthEndpointsJson: null,
  oauthScopesJson: null,
  oauthTokenEnvName: null,
  clientSecret: "",
};

/**
 * The first non-empty trimmed candidate, or `""`.
 *
 * Every OAuth identity field follows the same precedence — what the operator just submitted, then
 * what the row already holds, then nothing — and writing that as a `??` chain at each field is both
 * repetitive and, measurably, most of these functions' branch count. One helper makes the precedence
 * a single named rule instead of five copies of it.
 *
 * @complexity O(n) in the number of candidates, each trimmed once.
 */
function firstTrimmed(...candidates: readonly (string | null | undefined)[]): string {
  for (const candidate of candidates) {
    const trimmed = candidate?.trim();
    if (trimmed) return trimmed;
  }
  return "";
}

/**
 * Validates a sign-in method, or admits its absence on a row that can discover it for itself.
 *
 * The same exception {@link assertOAuthClientId} documents, extended to the grant: a REMOTE row can
 * run RFC 8414 discovery against its own URL at connect time and read the authorization server's own
 * `grant_types_supported` (`discovery.ts`) instead of an operator having to guess between "Browser
 * sign-in" and "Device code" before they know what the server even offers. See
 * `external-mcp-oauth.ts`'s `selfConfigureConnection`, which resolves and persists a concrete grant
 * the first time such a row connects. A stdio row has no URL to discover from, so for those the
 * requirement stands unchanged.
 *
 * @returns The validated grant, or `null` when the row will resolve one at connect.
 * @throws {ExternalMcpValidationError} On an empty grant the row cannot leave to discovery, or one
 * outside {@link EXTERNAL_MCP_OAUTH_GRANTS}.
 * @complexity O(1).
 */
function assertOAuthGrant(grant: string, selfConfigurable: boolean): ExternalMcpOAuthGrant | null {
  if (grant === "") {
    if (selfConfigurable) return null;
    throw new ExternalMcpValidationError("an OAuth connection needs a sign-in method", "oauth.grant");
  }
  if (!EXTERNAL_MCP_OAUTH_GRANTS.includes(grant as ExternalMcpOAuthGrant)) {
    throw new ExternalMcpValidationError(
      `OAuth grant '${grant}' is not supported — expected one of ${EXTERNAL_MCP_OAUTH_GRANTS.join(", ")}`,
      "oauth.grant",
    );
  }
  return grant as ExternalMcpOAuthGrant;
}

/**
 * Validates a client id, or admits its absence on a row that can obtain one for itself.
 *
 * `selfConfigurable` is what makes an empty client id legitimate rather than a validation failure.
 * A growing share of hosted authorization servers publish an RFC 7591 `registration_endpoint` and no
 * developer console at all, so for those there is no human path to a client id — demanding one here
 * would make the connection unreachable by any amount of operator effort. A row that carries a REMOTE
 * URL can run discovery against it at connect time and mint one; a stdio row has nothing to discover
 * from, so for those the requirement stands unchanged.
 *
 * @returns The validated client id, or `null` when the row will mint one at connect.
 * @throws {ExternalMcpValidationError} On an empty client id the row cannot obtain, or an oversized one.
 * @complexity O(1).
 */
function assertOAuthClientId(clientId: string, selfConfigurable: boolean): string | null {
  if (clientId === "") {
    if (selfConfigurable) return null;
    throw new ExternalMcpValidationError("an OAuth connection needs a client id", "oauth.clientId");
  }
  if (clientId.length > MAX_OAUTH_FIELD_LENGTH) {
    throw new ExternalMcpValidationError(`the OAuth client id may be at most ${MAX_OAUTH_FIELD_LENGTH} characters`, "oauth.clientId");
  }
  return clientId;
}

/**
 * Resolves the provider half of an OAuth connection: a registered provider id, its own endpoints, or
 * both.
 *
 * Endpoints are re-derived whenever the operator actually TYPED into either identity field, so
 * clearing a provider id and typing endpoints (or the reverse) cannot leave half of the old pairing
 * behind. "Actually typed" is judged by content, not key presence: the admin form sends both fields
 * on every save (it cannot round-trip a connection's own endpoints), so treating mere presence as a
 * touch made an untouched save look like an identity change on every edit — see
 * `use-external-mcp.hooks.ts`'s header for the caller-side half of this fix.
 *
 * The dynamic-registration members (`clientAuth`, `dynamicClientId`, `registeredRedirectUri`) are
 * exempted from re-derivation regardless of branch: they are server-owned, written only by dynamic
 * client registration (`external-mcp-oauth.ts`), and no operator input can express them, so even a
 * save that legitimately edits the other endpoints must not drop them.
 *
 * @throws {ExternalMcpValidationError} When neither a provider id nor a token endpoint is present,
 * or the provider id is malformed.
 * @complexity O(1).
 */
function resolveOAuthEndpoints(
  oauth: SaveExternalMcpOAuthInput,
  existing: ExternalMcpServerRecord | null,
): Record<string, string> {
  const stored = parseJsonObject(existing?.oauthEndpointsJson ?? null);
  const touchedIdentity = (oauth.providerId ?? "").trim() !== "" || (oauth.tokenEndpoint ?? "").trim() !== "";
  if (!touchedIdentity) return stored;
  const rebuilt = buildOAuthEndpoints(oauth);
  for (const key of DYNAMIC_REGISTRATION_ENDPOINT_KEYS) {
    if (stored[key] !== undefined) rebuilt[key] = stored[key];
  }
  return rebuilt;
}

/** The endpoints-blob members only dynamic client registration writes. */
const DYNAMIC_REGISTRATION_ENDPOINT_KEYS = ["clientAuth", "dynamicClientId", "registeredRedirectUri"] as const;

/**
 * @param selfConfigurable - Whether this row can discover its own endpoints — see
 *   {@link assertOAuthClientId} for the same argument applied to the client id.
 * @throws {ExternalMcpValidationError} When neither identity is present on a row that cannot
 *   discover one, or the id is malformed.
 */
function assertOAuthProviderIdentity(providerId: string, endpoints: Record<string, string>, selfConfigurable: boolean): void {
  if (providerId === "" && endpoints.tokenEndpoint === undefined && !selfConfigurable) {
    throw new ExternalMcpValidationError(
      "an OAuth connection needs either a registered provider id or its own token endpoint",
      "oauth.providerId",
    );
  }
  if (providerId !== "" && !OAUTH_PROVIDER_ID_PATTERN.test(providerId)) {
    throw new ExternalMcpValidationError(
      `'${providerId}' is not a valid provider id (lowercase letters, digits and hyphens)`,
      "oauth.providerId",
    );
  }
}

function resolveOAuthProviderIdentity(
  oauth: SaveExternalMcpOAuthInput,
  existing: ExternalMcpServerRecord | null,
  selfConfigurable: boolean,
): { readonly oauthProviderId: string | null; readonly oauthEndpointsJson: string | null } {
  const providerId = firstTrimmed(oauth.providerId, existing?.oauthProviderId);
  const endpoints = resolveOAuthEndpoints(oauth, existing);
  assertOAuthProviderIdentity(providerId, endpoints, selfConfigurable);

  return {
    oauthProviderId: providerId === "" ? null : providerId,
    oauthEndpointsJson: Object.keys(endpoints).length === 0 ? null : JSON.stringify(endpoints),
  };
}

/**
 * Resolves which child-process environment variable receives the access token.
 *
 * `null` for every non-`stdio` transport: only `stdio` hands credentials to a child process, so only
 * `stdio` needs a name for one.
 *
 * @throws {ExternalMcpValidationError} When a stdio+OAuth row names none, or names an invalid one.
 * @complexity O(n) in the name length.
 */
function resolveOAuthTokenEnvName(
  transport: ExternalMcpTransport,
  oauth: SaveExternalMcpOAuthInput,
  existing: ExternalMcpServerRecord | null,
): string | null {
  if (transport !== "stdio") return null;

  const tokenEnvName = firstTrimmed(oauth.tokenEnvName, existing?.oauthTokenEnvName);
  if (tokenEnvName === "") {
    throw new ExternalMcpValidationError(
      "a stdio server authenticated with OAuth needs the name of the environment variable that receives its access token",
      "oauth.tokenEnvName",
    );
  }
  if (!ENV_NAME_PATTERN.test(tokenEnvName)) {
    throw new ExternalMcpValidationError(
      `'${tokenEnvName}' is not a valid environment variable name (letters, digits and underscore, not starting with a digit)`,
      "oauth.tokenEnvName",
    );
  }
  return tokenEnvName;
}

/** Scopes for one save. Absent input KEEPS the stored list (the three-state rule `env` sets); an
 *  empty string clears it, since {@link parseOAuthScopes} of `""` is `[]`. */
function resolveSavedOAuthScopes(oauth: SaveExternalMcpOAuthInput, existing: ExternalMcpServerRecord | null): string[] {
  if (oauth.scopes === undefined) return parseJsonArray(existing?.oauthScopesJson ?? null);
  return parseOAuthScopes(oauth.scopes);
}

function resolveOAuthFields(
  authMode: ExternalMcpAuthMode,
  transport: ExternalMcpTransport,
  input: SaveExternalMcpServerInput,
  existing: ExternalMcpServerRecord | null,
): ResolvedOAuthFields {
  if (authMode !== "oauth") return NO_OAUTH_FIELDS;

  const oauth = input.oauth ?? {};
  // Only a remote row has a URL for `external-mcp-oauth.ts` to run RFC 9728 / RFC 8414 discovery
  // against, so only a remote row may leave its provider identity, grant and client id to be filled
  // in at connect time.
  const selfConfigurable = transport !== "stdio";

  return {
    ...resolveOAuthProviderIdentity(oauth, existing, selfConfigurable),
    oauthGrant: assertOAuthGrant(firstTrimmed(oauth.grant, existing?.oauthGrant), selfConfigurable),
    oauthClientId: assertOAuthClientId(firstTrimmed(oauth.clientId, existing?.oauthClientId), selfConfigurable),
    oauthScopesJson: JSON.stringify(resolveSavedOAuthScopes(oauth, existing)),
    oauthTokenEnvName: resolveOAuthTokenEnvName(transport, oauth, existing),
    clientSecret: oauth.clientSecret === '' ? undefined : oauth.clientSecret === undefined ? undefined : normalizeOAuthClientSecret({ value: oauth.clientSecret }),
  };
}

/** Trims and validates `rawCommand`, returning the trimmed value. Split out purely to keep
 *  {@link saveExternalMcpServer}'s complexity under the shop ceiling. */
function assertNonEmptyExternalMcpCommand(rawCommand: string): string {
  const command = rawCommand.trim();
  if (command === "") {
    throw new ExternalMcpValidationError("a stdio server needs a command to launch", "command");
  }
  return command;
}

/** Enforces {@link MAX_SERVERS_PER_WORKSPACE} for a NEW server only — an existing row is always an
 *  update, never a new slot, so it is exempt. Split out purely to keep
 *  {@link saveExternalMcpServer}'s complexity under the shop ceiling. */
async function assertUnderExternalMcpServerCap(
  deps: Pick<ExternalMcpStoreDeps, "repo">,
  workspaceId: UUID,
  existing: ExternalMcpServerRecord | null,
): Promise<void> {
  if (existing) return;
  const count = (await deps.repo.listByWorkspaceId(workspaceId)).length;
  if (count >= MAX_SERVERS_PER_WORKSPACE) {
    throw new ExternalMcpValidationError(
      `this workspace already has the maximum of ${MAX_SERVERS_PER_WORKSPACE} external MCP servers`,
      "id",
    );
  }
}

/** Resolves the sealed env block and its plaintext variable-name index for one save. `rawEnv ===
 *  undefined` preserves whatever `existing` already has (see {@link saveExternalMcpServer}'s doc for
 *  why); an empty parsed block clears the seal to `null` rather than sealing `{}`. Split out purely
 *  to keep {@link saveExternalMcpServer}'s complexity under the shop ceiling.
 *  @throws {ExternalMcpValidationError} On a malformed env block (via {@link parseEnvBlock}).
 *  @throws {ExternalMcpSecretStoreUnconfiguredError} When no site key is available to seal under. */
/** {@link resolveExternalMcpSealedEnv}'s `rawEnv === undefined` branch — carries the existing sealed
 *  env block through untouched. Split out purely to keep that function's complexity under the shop
 *  ceiling.
 *
 *  Carried through untouched, so its lineage must be carried too — bumping the version here would
 *  claim an AAD binding the stored ciphertext does not have, and brick the row. */
function carryForwardExternalMcpSealedEnv(
  existing: ExternalMcpServerRecord | null,
): { readonly sealedEnv: SealedSecret | null; readonly envNames: string[]; readonly aadVersion: number } {
  return {
    sealedEnv: existing?.sealedEnv ?? null,
    envNames: parseJsonArray(existing?.envNames ?? null),
    aadVersion: existing?.aadVersion ?? EXTERNAL_MCP_VAULT_VERSION,
  };
}

/** {@link resolveExternalMcpSealedEnv}'s fresh-seal branch — parses and seals a NEW env block. Split
 *  out purely to keep that function's complexity under the shop ceiling.
 *  @throws {ExternalMcpValidationError} On a malformed env block (via {@link parseEnvBlock}).
 *  @throws {ExternalMcpSecretStoreUnconfiguredError} When no site key is available to seal under. */
async function sealFreshExternalMcpEnv(
  deps: Pick<ExternalMcpStoreDeps, "sealer" | "keyring">,
  identity: ExternalMcpIdentity,
  rawEnv: string,
): Promise<{ readonly sealedEnv: SealedSecret | null; readonly envNames: string[]; readonly aadVersion: number }> {
  const env = parseEnvBlock(rawEnv);
  const envNames = Object.keys(env);
  if (envNames.length === 0) return { sealedEnv: null, envNames, aadVersion: EXTERNAL_MCP_VAULT_VERSION };

  try {
    const sealedEnv = await sealExternalMcpVaultPayload({ deps, identity, kind: "mcp-env", payload: env });
    return { sealedEnv, envNames, aadVersion: EXTERNAL_MCP_VAULT_VERSION };
  } catch (err) {
    throw new ExternalMcpSecretStoreUnconfiguredError(
      CREDENTIAL_MESSAGES.storage,
    );
  }
}

async function resolveExternalMcpSealedEnv(
  deps: Pick<ExternalMcpStoreDeps, "sealer" | "keyring">,
  identity: ExternalMcpIdentity,
  rawEnv: string | undefined,
  existing: ExternalMcpServerRecord | null,
): Promise<{ readonly sealedEnv: SealedSecret | null; readonly envNames: string[]; readonly aadVersion: number }> {
  // Owner policy: an exact blank update keeps credentials; whitespace cannot clear them.
  if (rawEnv !== undefined && rawEnv !== '' && rawEnv.trim() === '') throw new ExternalMcpValidationError(CREDENTIAL_MESSAGES.blank, 'env');
  return rawEnv === undefined || rawEnv === ''
    ? carryForwardExternalMcpSealedEnv(existing)
    : sealFreshExternalMcpEnv(deps, identity, rawEnv);
}

/** Hosts for which plaintext `http` is tolerated — a local development server, and nothing else. */
const LOOPBACK_HOSTNAMES: ReadonlySet<string> = new Set(["localhost", "127.0.0.1", "[::1]", "::1"]);

/**
 * Validates a remote MCP server URL.
 *
 * Same rule the OAuth endpoints follow (`oauth/endpoint-safety.ts`): https, or http only for
 * loopback. A remote MCP endpoint carries the bearer token this whole subsystem exists to obtain, so
 * a plaintext one to anywhere but a developer's own machine is a credential on the wire.
 *
 * @returns The normalized absolute URL.
 * @throws {ExternalMcpValidationError} On an empty, unparseable, or plaintext-non-loopback URL.
 * @complexity O(n) in the URL length.
 */
function assertSafeRemoteMcpUrl(rawUrl: string, transport: ExternalMcpTransport): string {
  const url = rawUrl.trim();
  if (url === "") {
    throw new ExternalMcpValidationError(`a ${transport} server needs a URL`, "url");
  }
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    throw new ExternalMcpValidationError(CREDENTIAL_MESSAGES.url, "url");
  }
  assertExternalMcpPlainField({ value: url, field: "url" });
  const loopback = LOOPBACK_HOSTNAMES.has(parsed.hostname.toLowerCase());
  if (parsed.protocol !== "https:" && !(parsed.protocol === "http:" && loopback)) {
    throw new ExternalMcpValidationError("a remote MCP server URL must use https (http is permitted only for loopback)", "url");
  }
  return parsed.toString();
}

/** A `stdio` row needs a command; a remote row needs a URL. Split out to keep
 *  {@link saveExternalMcpServer}'s complexity under the shop ceiling.
 *  @throws {ExternalMcpValidationError} When the transport's own required field is missing or unsafe. */
function resolveTransportTarget(
  transport: ExternalMcpTransport,
  input: SaveExternalMcpServerInput,
): { readonly command: string | null; readonly url: string | null } {
  if (transport === "stdio") return { command: assertNonEmptyExternalMcpCommand(input.command), url: null };

  return { command: null, url: assertSafeRemoteMcpUrl(input.url ?? "", transport) };
}

/**
 * The OAuth runtime columns a save carries forward.
 *
 * A save that leaves the token's binding unchanged preserves the live connection untouched — an
 * operator toggling `enabled` or renaming a server must not have to re-authorize. A save that
 * CHANGES the binding discards the token and returns the row to `disconnected`, because the stored
 * credential was issued for configuration that no longer exists.
 *
 * @complexity O(1).
 */
function carryOAuthRuntimeState(
  authMode: ExternalMcpAuthMode,
  resolved: ResolvedOAuthFields,
  existing: ExternalMcpServerRecord | null,
): Pick<ExternalMcpServerRecord, "oauthStatus" | "oauthExpiresAt" | "oauthRefreshLeaseUntil"> & { readonly keepToken: boolean } {
  const cleared = { oauthStatus: null, oauthExpiresAt: null, oauthRefreshLeaseUntil: null, keepToken: false } as const;
  if (authMode !== "oauth" || existing === null) return cleared;

  const unchanged = oauthBindingFingerprint(existing) === oauthBindingFingerprint({ ...resolved });
  if (!unchanged) return { oauthStatus: "disconnected", oauthExpiresAt: null, oauthRefreshLeaseUntil: null, keepToken: false };

  return {
    oauthStatus: existing.oauthStatus ?? "disconnected",
    oauthExpiresAt: existing.oauthExpiresAt,
    oauthRefreshLeaseUntil: existing.oauthRefreshLeaseUntil,
    keepToken: true,
  };
}

/**
 * What the OAuth sealed blob holds.
 *
 * ONE blob rather than a column per secret, for exactly the reason the env block is one blob: every
 * read path wants the whole thing at once, and per-secret sealing would buy nothing and cost N
 * keyring round trips. The consequence is a READ-MODIFY-WRITE rule that every writer must honour —
 * unseal, change one member, reseal — because a writer that seals `{ tokens }` alone silently
 * deletes the operator's client secret.
 *
 * Structurally compatible with `src/platform/oauth/`'s `OAuthTokenSet`, but declared here rather than
 * imported: this is the STORED shape, and it must be able to stay still while the flow module's
 * in-memory type moves.
 */
/**
 * Schema version of the *plaintext* inside the sealed OAuth blob.
 *
 * Distinct from `oauth_aad_version`, which versions how the blob is BOUND to its row and says
 * nothing about what is inside it. Without this, a field could be added but never renamed, changed,
 * or removed — there would be nothing to branch on at open time, and the only way out would be a
 * migration over live credentials. Stamped at seal; a blob without it predates versioning and is
 * upgraded on read.
 */
export const EXTERNAL_MCP_OAUTH_PAYLOAD_VERSION = 1;

/**
 * The branching read for a sealed OAuth payload. A missing version is v0 (pre-versioning) and is
 * upgraded in place; a newer version is refused rather than misread, because silently
 * reinterpreting an unknown shape here means handing back a wrong or partial live credential.
 *
 * `schemaVersion` is stripped from the result: it is a wire concern, and a caller that saw it could
 * persist it back into a payload it does not own.
 *
 * The vault's open already refuses a non-object payload, so `parsed` is always an object here.
 *
 * @throws When the payload was written by a newer build than this one understands.
 * @complexity O(1).
 */
export function hydrateExternalMcpOAuthPayload(parsed: Record<string, unknown>): ExternalMcpSealedOAuthPayload {
  const { schemaVersion, ...rest } = parsed;
  const stored = typeof schemaVersion === "number" ? schemaVersion : 0;
  if (stored > EXTERNAL_MCP_OAUTH_PAYLOAD_VERSION) {
    throw new Error(
      `external MCP OAuth payload was written at schema version ${stored}, newer than this build understands (${EXTERNAL_MCP_OAUTH_PAYLOAD_VERSION}) — upgrade rather than risk misreading a live credential`,
    );
  }
  // v0 -> v1 added only the discriminator, so the upgrade is a stamp; a later version adds its own
  // branch here rather than a backfill over live credentials.
  return rest as ExternalMcpSealedOAuthPayload;
}

export interface ExternalMcpSealedOAuthPayload {
  /**
   * A `static_env` row's operator-pasted access token — the only member such a row's blob ever holds
   * (see {@link externalMcpRecordHasStaticAccessToken}). Additive to payload v1: the OAuth flow never
   * reads a `static_env` row (`requireOAuthRecord` refuses it), so no older reader can mishandle it.
   */
  readonly staticAccessToken?: string;
  readonly clientSecret?: string;
  readonly tokens?: {
    readonly accessToken: string;
    readonly refreshToken: string | null;
    readonly tokenType: string;
    readonly scopes: readonly string[];
    readonly expiresAt: ISODateTime | null;
  };
}

/**
 * Opens a row's sealed OAuth blob.
 *
 * @returns `{}` when the row holds none, which is the normal state before a connection is authorized.
 * @throws {ExternalMcpSecretStoreUnconfiguredError} When the blob exists but cannot be opened — a
 * rotated site key or a corrupt row. Distinct from "no blob" on purpose: the caller must not treat a
 * decryption failure as "not connected yet" and start a fresh authorization over a token that is
 * still live at the provider.
 * @complexity O(1) — one unseal.
 */
export async function openExternalMcpOAuthPayload(
  sealer: Pick<SecretSealerPort, "open">,
  record: Pick<ExternalMcpServerRecord, "sealedOAuth" | "workspaceId" | "serverId" | "oauthAadVersion">,
): Promise<ExternalMcpSealedOAuthPayload> {
  if (record.sealedOAuth === null) return {};
  let parsed: Record<string, unknown>;
  try {
    parsed = await openExternalMcpVaultPayload({ sealer, sealed: record.sealedOAuth, identity: record, kind: "mcp-auth" });
  } catch (err) {
    throw new ExternalMcpSecretStoreUnconfiguredError(
      "Stored OAuth credentials could not be decrypted.",
    );
  }
  // Deliberately OUTSIDE the catch above: a version mismatch is not a decryption failure, and must
  // not be swallowed by a caller that treats that error as "not connected yet".
  return hydrateExternalMcpOAuthPayload(parsed);
}

/**
 * Seals an OAuth payload, or resolves `null` when there is nothing worth sealing.
 *
 * An empty payload seals to `null` rather than to a blob containing `{}`, so `sealedOAuth !== null`
 * is a truthful answer to "does this connection hold anything secret". It is NOT an answer to "does
 * it hold a token" — a cleared connection keeps its client secret in that blob — which is why
 * {@link externalMcpRecordHasStoredToken} reads the plaintext columns instead.
 *
 * @throws {ExternalMcpSecretStoreUnconfiguredError} When no site key is available.
 * @complexity O(1) — one seal.
 */
/**
 * A sealed OAuth blob with its compatibility lineage. Vault identity travels with the opaque
 * envelope so carried credentials keep the exact ID/context they were authenticated under.
 * The server repository commits that vault row, its pointer, status and expiry together.
 */
export interface SealedExternalMcpOAuth {
  readonly sealedOAuth: SealedSecret | null;
  readonly oauthAadVersion: number;
}

export async function sealExternalMcpOAuthPayload(
  deps: Pick<ExternalMcpStoreDeps, "sealer" | "keyring">,
  identity: ExternalMcpIdentity,
  payload: ExternalMcpSealedOAuthPayload,
): Promise<SealedExternalMcpOAuth> {
  const hasSecret =
    (payload.clientSecret !== undefined && payload.clientSecret !== "") || payload.tokens !== undefined || Boolean(payload.staticAccessToken);
  if (!hasSecret) return { sealedOAuth: null, oauthAadVersion: EXTERNAL_MCP_VAULT_VERSION };
  try {
    const sealedOAuth = await sealExternalMcpVaultPayload({ deps, identity, kind: "mcp-auth",
      // The discriminator remains authenticated inside the payload, never plain metadata.
      payload: JSON.parse(JSON.stringify({ ...payload, schemaVersion: EXTERNAL_MCP_OAUTH_PAYLOAD_VERSION })),
    });
    return { sealedOAuth, oauthAadVersion: EXTERNAL_MCP_VAULT_VERSION };
  } catch (err) {
    throw new ExternalMcpSecretStoreUnconfiguredError(
      CREDENTIAL_MESSAGES.storage,
    );
  }
}

/**
 * Applies one save's client-secret instruction to the stored blob, preserving the token.
 *
 * `carryToken` is `null` when the save invalidated the stored token (see
 * {@link carryOAuthRuntimeState}); passing the record means "keep whatever token it holds".
 *
 * @throws {ExternalMcpSecretStoreUnconfiguredError} When the blob cannot be opened or resealed.
 * @complexity O(1) — at most one unseal plus one seal.
 */
async function resolveSealedOAuthBlob(
  deps: Pick<ExternalMcpStoreDeps, "sealer" | "keyring">,
  identity: ExternalMcpIdentity,
  clientSecret: string | undefined,
  carryToken: ExternalMcpServerRecord | null,
): Promise<SealedExternalMcpOAuth> {
  // Nothing to preserve and nothing to write: skip the keyring entirely rather than seal an empty
  // object, which is what keeps a `none`/`static_env` row's OAuth blob genuinely absent.
  if (carryToken === null && (clientSecret === undefined || clientSecret === "")) {
    return { sealedOAuth: null, oauthAadVersion: EXTERNAL_MCP_VAULT_VERSION };
  }

  const existingPayload = carryToken === null ? {} : await openExternalMcpOAuthPayload(deps.sealer, carryToken);
  const next: ExternalMcpSealedOAuthPayload = {
    ...(clientSecret === undefined
      ? existingPayload.clientSecret === undefined
        ? {}
        : { clientSecret: existingPayload.clientSecret }
      : clientSecret === ""
        ? {}
        : { clientSecret }),
    ...(existingPayload.tokens === undefined ? {} : { tokens: existingPayload.tokens }),
  };
  return sealExternalMcpOAuthPayload(deps, identity, next);
}

/**
 * Resolves the two write-grant attribution columns for one save.
 *
 * Written ONLY when {@link writeAllowedToolNames}'s contents actually change — compared as a set
 * against whatever the row already has — so a save that merely renames a connection or flips
 * `enabled` does not stamp a new "authorized by / on" over an untouched grant. `input.principalId`
 * is read only on the changed branch, which is what lets it stay a required TYPE without becoming a
 * runtime hazard: a caller written before this field existed can only reach `undefined` here if it
 * also never sets a non-empty {@link SaveExternalMcpServerInput.writeAllowedToolNames}, in which case
 * the list never changes and this branch never runs.
 *
 * @complexity O(n) in the length of the longer list (via {@link toolNameSetsEqual}).
 */
function resolveWriteGrantAttribution(
  input: Pick<SaveExternalMcpServerInput, "principalId">,
  writeAllowedToolNames: readonly string[],
  existing: ExternalMcpServerRecord | null,
  nowIso: ISODateTime,
): Pick<ExternalMcpServerRecord, "writeGrantsUpdatedByPrincipalId" | "writeGrantsUpdatedAt"> {
  const previousWriteAllowedToolNames = parseJsonArray(existing?.writeAllowedToolNames ?? null);
  if (toolNameSetsEqual(previousWriteAllowedToolNames, writeAllowedToolNames)) {
    return {
      writeGrantsUpdatedByPrincipalId: existing?.writeGrantsUpdatedByPrincipalId ?? null,
      writeGrantsUpdatedAt: existing?.writeGrantsUpdatedAt ?? null,
    };
  }
  return { writeGrantsUpdatedByPrincipalId: input.principalId, writeGrantsUpdatedAt: nowIso };
}

/** Tovu error adapter for the shared token policy. The store alone normalizes the value. */
function normalizeOAuthClientSecret({ value }: { value: string }): string {
  try { return normalizeCredentialToken({ value, field: 'oauth.clientSecret' }); }
  catch (err) { if (err instanceof CredentialInputError) throw new ExternalMcpValidationError(err.message, err.field); throw err; }
}

export function normalizeExternalMcpAccessToken(
  { value, transport }: { value: unknown; transport: string }, _optional = {},
): string {
  try { return normalizeCredentialToken({ value, field: 'accessToken', hosted: transport !== 'stdio' }); }
  catch (err) {
    if (err instanceof CredentialInputError) throw new ExternalMcpValidationError(err.message, err.field);
    throw err;
  }
}

/**
 * The sealed blob for a `static_env` row's access token, under the `env` field's three-state rule.
 *
 * Stored in the row's existing sealed OAuth columns (and AAD lineage) rather than a new column: it is
 * the same kind of thing — a sealed connection credential beside the env block — and while a row is
 * `static_env` that blob holds nothing else. A carried token keeps its ciphertext AND its
 * `oauthAadVersion` together, for the reason {@link SealedExternalMcpOAuth} gives.
 *
 * @throws {ExternalMcpValidationError} Via {@link assertValidStaticAccessToken}.
 * @throws {ExternalMcpSecretStoreUnconfiguredError} When no site key is available to seal under.
 * @complexity O(n) in the token length; at most one seal.
 */
async function resolveSealedStaticAccessToken(
  deps: Pick<ExternalMcpStoreDeps, "sealer" | "keyring">,
  identity: ExternalMcpIdentity,
  rawToken: string | undefined,
  existing: ExternalMcpServerRecord | null,
  transport: ExternalMcpTransport,
): Promise<SealedExternalMcpOAuth> {
  const none: SealedExternalMcpOAuth = { sealedOAuth: null, oauthAadVersion: EXTERNAL_MCP_VAULT_VERSION };
  if (rawToken === undefined || rawToken === "") {
    return existing !== null && externalMcpRecordHasStaticAccessToken(existing)
      ? { sealedOAuth: existing.sealedOAuth, oauthAadVersion: existing.oauthAadVersion }
      : none;
  }
  const token = normalizeExternalMcpAccessToken({ value: rawToken, transport });
  return sealExternalMcpOAuthPayload(deps, identity, { staticAccessToken: token });
}

/**
 * Which child env variable receives a `stdio` + `static_env` row's access token. `null` for a hosted
 * row (its token travels in a header) and for a stdio row that neither holds a token nor names one.
 *
 * @throws {ExternalMcpValidationError} When a stdio row holds a token but names no variable, or an
 *   invalid one.
 * @complexity O(n) in the name length.
 */
function resolveStaticAccessTokenEnvName(
  transport: ExternalMcpTransport,
  input: Pick<SaveExternalMcpServerInput, "accessTokenEnvName">,
  existing: ExternalMcpServerRecord | null,
  holdsToken: boolean,
): string | null {
  if (transport !== "stdio") return null;
  const name = firstTrimmed(input.accessTokenEnvName, existing?.oauthTokenEnvName);
  if (name === "") {
    if (!holdsToken) return null;
    throw new ExternalMcpValidationError(
      "a local command given an access token needs the name of the environment variable that receives it",
      "accessTokenEnvName",
    );
  }
  if (!ENV_NAME_PATTERN.test(name)) {
    throw new ExternalMcpValidationError(
      `'${name}' is not a valid environment variable name (letters, digits and underscore, not starting with a digit)`,
      "accessTokenEnvName",
    );
  }
  return name;
}

/**
 * The sealed-credential columns for one save, by auth mode: a `static_env` row's access token and its
 * variable name, or an `oauth`/`none` row's client secret and carried token set (nothing, for `none`).
 * Split out to keep {@link saveExternalMcpServer} under the shop's complexity ceiling.
 *
 * @complexity O(1) beyond at most one unseal and one seal.
 */
async function resolveSavedCredentialColumns(
  deps: Pick<ExternalMcpStoreDeps, "sealer" | "keyring">,
  identity: ExternalMcpIdentity,
  context: {
    readonly authMode: ExternalMcpAuthMode;
    readonly transport: ExternalMcpTransport;
    readonly input: SaveExternalMcpServerInput;
    readonly oauthFields: ResolvedOAuthFields;
    readonly keepToken: boolean;
    readonly existing: ExternalMcpServerRecord | null;
  },
): Promise<SealedExternalMcpOAuth & { readonly oauthTokenEnvName: string | null }> {
  const { authMode, transport, input, oauthFields, keepToken, existing } = context;
  if (authMode !== "static_env") {
    const sealed = await resolveSealedOAuthBlob(deps, identity, oauthFields.clientSecret, keepToken ? existing : null);
    return { ...sealed, oauthTokenEnvName: oauthFields.oauthTokenEnvName };
  }
  const sealed = await resolveSealedStaticAccessToken(deps, identity, input.accessToken, existing, transport);
  if (transport !== "stdio" && sealed.sealedOAuth === null) {
    throw new ExternalMcpValidationError("Enter a token. Spaces alone are not a token.", "accessToken");
  }
  return { ...sealed, oauthTokenEnvName: resolveStaticAccessTokenEnvName(transport, input, existing, sealed.sealedOAuth !== null) };
}

function assertExternalMcpPlainField(required: { value: string; field: string }): void {
  try { assertCredentialFreeField(required); }
  catch (err) {
    if (err instanceof CredentialInputError) throw new ExternalMcpValidationError(err.message, err.field);
    throw err;
  }
}

function assertExternalMcpPlainInput({ input }: { input: SaveExternalMcpServerInput }, _options = {}): void {
  for (const field of ["serverId", "label", "command", "args", "url", "transport", "authMode", "accessTokenEnvName"] as const) {
    assertExternalMcpPlainField({ value: input[field] ?? "", field });
  }
  for (const [field, value] of Object.entries(input.oauth ?? {})) {
    if (field !== 'clientSecret' && typeof value === 'string') assertExternalMcpPlainField({ value, field: `oauth.${field}` });
  }
}

export async function saveExternalMcpServer(
  deps: ExternalMcpStoreDeps,
  input: SaveExternalMcpServerInput,
): Promise<ExternalMcpServerView> {
  assertExternalMcpPlainInput({ input });
  const serverId = input.serverId.trim().toLowerCase();
  assertValidExternalMcpServerId(serverId);
  assertSupportedExternalMcpTransport(input.transport);
  const transport = input.transport as ExternalMcpTransport;
  const { command, url } = resolveTransportTarget(transport, input);
  const args = parseArgs(input.args);
  const allowedToolNames = parseAllowedToolNames(input.allowedToolNames);
  // `?? ""` is a defensive fallback, not the documented contract (the type requires the field): a
  // caller that predates this field reaches `undefined` here, and must degrade to "no write grants"
  // rather than throw on `undefined.split`. See `SaveExternalMcpServerInput.writeAllowedToolNames`'s
  // doc.
  const writeAllowedToolNames = parseWriteAllowedToolNames(input.writeAllowedToolNames ?? "");
  assertWriteAllowlistSubset(writeAllowedToolNames, allowedToolNames);

  const existing = await deps.repo.findByServerId({ workspaceId: input.workspaceId, serverId });
  await assertUnderExternalMcpServerCap(deps, input.workspaceId, existing);
  const authMode = resolveSavedAuthMode(input, existing);
  const oauthFields = resolveOAuthFields(authMode, transport, input, existing);
  const runtime = carryOAuthRuntimeState(authMode, oauthFields, existing);
  const aadIdentity: ExternalMcpIdentity = { workspaceId: input.workspaceId, serverId };
  const { sealedEnv, envNames, aadVersion } = await resolveExternalMcpSealedEnv(deps, aadIdentity, input.env, existing);
  const { sealedOAuth, oauthAadVersion, oauthTokenEnvName } = await resolveSavedCredentialColumns(deps, aadIdentity, {
    authMode,
    transport,
    input,
    oauthFields,
    keepToken: runtime.keepToken,
    existing,
  });

  const now = nowIso({ clock: deps.clock });
  const writeGrantAttribution = resolveWriteGrantAttribution(input, writeAllowedToolNames, existing, now);
  const record: ExternalMcpServerRecord = {
    workspaceId: input.workspaceId,
    serverId,
    label: input.label?.trim() || null,
    provisionedByPluginId: input.provisionedByPluginId ?? existing?.provisionedByPluginId ?? null,
    transport: input.transport,
    authMode,
    enabled: input.enabled,
    command,
    url,
    args: JSON.stringify(args),
    allowedToolNames: JSON.stringify(allowedToolNames),
    writeAllowedToolNames: JSON.stringify(writeAllowedToolNames),
    writeGrantsUpdatedByPrincipalId: writeGrantAttribution.writeGrantsUpdatedByPrincipalId,
    writeGrantsUpdatedAt: writeGrantAttribution.writeGrantsUpdatedAt,
    envNames: JSON.stringify(envNames),
    sealedEnv,
    oauthProviderId: oauthFields.oauthProviderId,
    oauthGrant: oauthFields.oauthGrant,
    oauthClientId: oauthFields.oauthClientId,
    oauthEndpointsJson: oauthFields.oauthEndpointsJson,
    oauthScopesJson: oauthFields.oauthScopesJson,
    oauthStatus: runtime.oauthStatus,
    oauthExpiresAt: runtime.oauthExpiresAt,
    oauthTokenEnvName,
    oauthRefreshLeaseUntil: runtime.oauthRefreshLeaseUntil,
    sealedOAuth,
    aadVersion,
    oauthAadVersion,
    createdAt: existing?.createdAt ?? now,
    updatedAt: now,
  };
  await deps.repo.upsert(record);
  return toView(record, deps.sealer);
}

/**
 * Removes one server. Returns whether a row was actually deleted, so a route can answer 404 rather
 * than reporting success for an id that never existed.
 *
 * @complexity O(1).
 * @overallScore 100
 */
export async function deleteExternalMcpServer(
  deps: Pick<ExternalMcpStoreDeps, "repo">,
  input: { workspaceId: UUID; serverId: string },
): Promise<boolean> {
  return deps.repo.deleteByServerId(input);
}

import { randomUUID } from "node:crypto";
import { InMemoryVaultRepo, SecretsVaultService, VaultError, type VaultMeta, type VaultRecord,
  type VaultRepoPort } from "@jini-ai/platform/secrets/credential-sets";
import type { KeyringPort, SealedSecret, SecretSealerPort } from "@jini-ai/platform/secrets";
import { createTovuVaultKinds } from "#src/platform/secrets/vault-kinds";

type Identity = { workspaceId: string; serverId: string };
type Kind = "mcp-env" | "mcp-auth";
const contextKey = Symbol("external-mcp-vault-context");
const stagedKey = Symbol("external-mcp-staged");
type Envelope = SealedSecret & { [contextKey]?: Omit<VaultRecord, "sealed">; [stagedKey]?: boolean };

// The public MCP row still carries opaque envelopes. A non-enumerable context travels with each
// envelope in memory; only its vault ID is persisted on the server. No plaintext cache or registry.
export function externalMcpVaultEnvelope({ record }: { record: VaultRecord }, { staged = false }: { staged?: boolean } = {}): SealedSecret | null {
  if (!record.sealed) return null;
  const { sealed, ...context } = record;
  return Object.defineProperties({ ...sealed }, { [contextKey]: { value: context }, [stagedKey]: { value: staged } });
}

/** Validate the expected server/kind before a read or write; never infer authorization from a row. */
export function externalMcpVaultRecord(
  { sealed, identity, kind }: { sealed: SealedSecret; identity: Identity; kind: Kind }, _options = {},
): VaultRecord {
  const context = (sealed as Envelope)[contextKey];
  if (!context || context.workspaceId !== identity.workspaceId || context.ownerKey !== identity.serverId ||
    context.kind !== kind || context.principalId !== null || context.binding !== null) throw new VaultError({ code: "context" });
  return { ...context, sealed: { keyId: sealed.keyId, ciphertext: sealed.ciphertext, nonce: sealed.nonce, alg: sealed.alg } };
}

function service({ repo, sealer, keyring, identity, kind }: {
  repo: VaultRepoPort; sealer: SecretSealerPort; keyring: KeyringPort; identity: Identity; kind: Kind;
}) {
  // Refuse a foreign kind before its metadata parser or any crypto can run.
  if (kind !== "mcp-env" && kind !== "mcp-auth") throw new VaultError({ code: "context" });
  const registry = createTovuVaultKinds({ policy: {
    validateMeta: ({ kind: requested, meta }) => {
      if (requested !== "mcp-env" && requested !== "mcp-auth") throw new VaultError({ code: "context" });
      return meta;
    }, legacyPublishCredential: () => undefined, tokenField: () => undefined,
  } });
  return new SecretsVaultService({ repo, sealer, keyring, metaParsers: registry.metaParsers,
    authorize: async ({ context }) => {
      if (context.workspaceId !== identity.workspaceId || context.ownerKey !== identity.serverId ||
        context.kind !== kind || context.principalId !== null) throw new VaultError({ code: "context" });
    }, now: () => new Date().toISOString(), newId: () => randomUUID() });
}

/** Stage ciphertext through Jini; the host repository commits it with pointers/status/expiry.
 * @complexity O(payload bytes), one seal, no database I/O before the host transaction.
 */
export async function sealExternalMcpVaultPayload(
  { deps, identity, kind, payload }: { deps: { sealer: SecretSealerPort; keyring: KeyringPort }; identity: Identity;
    kind: Kind; payload: VaultMeta }, _options = {},
): Promise<SealedSecret> {
  const repo = new InMemoryVaultRepo({});
  const id = randomUUID();
  const saved = await service({ repo, sealer: deps.sealer, keyring: deps.keyring, identity, kind }).put({ workspaceId: identity.workspaceId,
    kind, ownerKey: identity.serverId, principalId: null, binding: null, expectedRevision: null,
    id, provider: null, label: id, meta: {}, payload });
  const record = await repo.find(saved);
  if (!record?.sealed) throw new VaultError({ code: "invalid-record" });
  return externalMcpVaultEnvelope({ record }, { staged: true })!;
}

/** Opening a hydrated envelope performs no extra SQL; legacy AAD belongs to boot normalization.
 * @complexity O(payload bytes), one open; expected ownership is checked before crypto.
 */
export async function openExternalMcpVaultPayload(
  { sealer, sealed, identity, kind }: { sealer: Pick<SecretSealerPort, "open">; sealed: SealedSecret;
    identity: Identity; kind: Kind }, _options = {},
): Promise<VaultMeta> {
  const record = externalMcpVaultRecord({ sealed, identity, kind });
  const repo = new InMemoryVaultRepo({});
  await repo.put({ record: { ...record, revision: 1 }, expectedRevision: null });
  // Reads never acquire a sealing key. These fail-closed ports guard accidental future writes.
  const unavailable = async (): Promise<never> => { throw new VaultError({ code: "invalid-record" }); };
  const vault = service({ repo, identity, kind, sealer: { open: sealer.open.bind(sealer), seal: unavailable },
    keyring: { activeKey: unavailable, deriveSigningSecret: unavailable, derive: unavailable } });
  const opened = await vault.get({ workspaceId: identity.workspaceId, id: record.id, kind,
    ownerKey: identity.serverId, principalId: null, binding: null });
  if (!opened?.payload) throw new VaultError({ code: "invalid-record" });
  return opened.payload;
}

/** Persist staged envelopes with Jini CAS; carried envelopes must still exist byte-for-byte.
 * @complexity Constant indexed reads/writes per envelope; callers own the surrounding transaction.
 */
export async function persistExternalMcpVaultEnvelope(
  { repo, sealed, identity, kind }: { repo: VaultRepoPort; sealed: SealedSecret | null; identity: Identity; kind: Kind }, _options = {},
): Promise<string | null> {
  if (!sealed) return null;
  const record = externalMcpVaultRecord({ sealed, identity, kind });
  const existing = await repo.find(record);
  if (existing) {
    if (existing.kind !== kind || existing.ownerKey !== identity.serverId ||
      JSON.stringify(existing.sealed) !== JSON.stringify(record.sealed)) throw new VaultError({ code: "conflict" });
    return record.id;
  }
  if (!(sealed as Envelope)[stagedKey]) throw new VaultError({ code: "conflict" });
  await repo.put({ record: { ...record, revision: 1 }, expectedRevision: null });
  return record.id;
}

/** Call only after unlinking the server pointer; read the revision after any default changes. */
export async function deleteExternalMcpVaultEnvelope(
  { repo, workspaceId, id }: { repo: VaultRepoPort; workspaceId: string; id: string | null }, _options = {},
): Promise<void> {
  if (!id) return;
  const record = await repo.find({ workspaceId, id });
  if (record) await repo.delete({ workspaceId, id, expectedRevision: record.revision });
}

import { createHash } from "node:crypto";
import { listProviderModels, type ProviderModelOption } from "@jini-ai/agent-runtime";
import { ModelCatalogCache, unionModels as unionModelCatalog } from "@jini-ai/agent-runtime/model-catalog/cache";
import type { Clock } from "@jini-ai/core/primitives";
import type { AgentModelSummary } from "@jini-ai/daemon/http";

import type { SecretSealerPort } from "../features/webhooks/index.js";
import { resolveExecutionCredential, type AdminExecutionCredentialRepoPort } from "./execution-credential-store.js";

/**
 * @file Live model discovery for the Local CLI picker's `claude` entry — the enrichment step
 * `server/runtime/composition/modules/assistant.ts`'s `respondWithEnrichedAgentList` calls. Design:
 * `ADS-memory/reports/local-cli-live-model-discovery-design-2026-08-05.md` §3.1/§3.5.
 *
 * Two independent concerns, deliberately not folded into one function:
 * - {@link LiveModelDiscovery.getLiveClaudeModels} — the "never a gate" credential branch. Resolves the admin's own
 *   `admin_execution_credentials` row and returns immediately, with NO network call, whenever
 *   there is no row, no key, or a protocol other than `anthropic`. Only a resolved `anthropic`
 *   credential reaches the cache/network path below.
 * - The in-memory TTL cache — wraps ONLY the `listProviderModels` call, not the credential check
 *   (that check is a single cheap repo read + decrypt, per `resolveExecutionCredential`'s own
 *   `@complexity O(1)` contract, so caching it buys nothing and would only obscure the "zero
 *   network calls" property under a cache hit/miss branch). Sized so a busy admin dock (mount, tab
 *   switch back to the dock) doesn't reissue a live HTTPS call on every `/api/agents` load — see
 *   the design doc's Risks §5 for the accepted staleness window this trades for that.
 *
 * {@link unionModels} is the §3.5 merge policy: fallback entries (including the `sonnet`/`opus`/
 * `haiku` aliases and the `'default'` sentinel) are ALWAYS present, unconditionally — this function
 * has no code path that can drop one. Live-discovered ids are appended only when not already
 * present, deduped by `id`.
 */

/** How long one successful-or-failed live call is trusted before the next request re-issues it.
 *  Deliberately minutes, not seconds: installing/rotating a stored key is a deliberate admin
 *  action, not one that needs sub-minute staleness (design doc §3.1's own reasoning). */
const LIVE_MODEL_CACHE_TTL_MS = 5 * 60_000;

interface LiveModelHostDependencies {
  readonly repo: AdminExecutionCredentialRepoPort;
  readonly sealer: SecretSealerPort;
}
interface DiscoveryOutcome {
  readonly models: readonly ProviderModelOption[];
}
export interface LiveModelDiscovery {
  /**
   * Resolves the admin's stored execution credential for `(workspaceId, principalId)` and, only
   * when it is a usable `anthropic` credential, returns Claude's live model catalog (cached — see
   * this file's header). Returns `null` for every other outcome: no row, no key, wrong protocol, or
   * a failed/timed-out live call. `null` is not an error signal — the caller's contract
   * (`unionModels`) is to treat it as "nothing to enrich with" and leave the static fallback list
   * exactly as it was, which is what makes this a strict enrichment layer rather than a dependency
   * the picker can be blocked or degraded by.
   *
   * No network call is made at all on the `null`/wrong-protocol paths — verified directly by this
   * file's own tests stubbing `globalThis.fetch` to throw. That is the "never a gate" invariant a
   * Max-subscription admin with no stored key depends on: zero added latency, by construction, not
   * by a cache that merely answers fast.
   *
   * @complexity O(1) plus, at most, one cached network call.
   */
  getLiveClaudeModels(key: { workspaceId: string; principalId: string }): Promise<readonly ProviderModelOption[] | null>;
}

/** Creates one host-owned discovery/cache instance; generic cache and its rationale now live in
 * `@jini-ai/agent-runtime/model-catalog/cache`. The in-flight call itself is shared so concurrent
 * requests in a TTL window issue one provider call, rather than caching only its eventual value.
 * Successes and failures keep the same five-minute TTL; credentials are resolved before each read.
 * Tovu is multi-workspace: delimiter-joined `${workspaceId}:${principalId}` keys would alias tenants
 * if either ID contained `:`. The package encodes the full tuple structurally, including credential
 * and endpoint scope. SHA-256 fingerprints invalidate rotation without retaining a raw key in cache
 * keys. A result wrapper preserves the distinction between a successful empty catalog and failure.
 */
export function createLiveModelDiscovery(
  { repo, sealer, clock, discover }: LiveModelHostDependencies & {
    clock: Clock;
    discover: (required: { apiKey: string; baseUrl: string }) => Promise<readonly ProviderModelOption[] | null>;
  },
  { ttlMs = LIVE_MODEL_CACHE_TTL_MS }: { ttlMs?: number } = {},
): LiveModelDiscovery {
  const cache = new ModelCatalogCache<DiscoveryOutcome>({
    clock,
    // Each get supplies a discovery closure AFTER resolving that principal's credential. This
    // required default is fail-closed if a future caller forgets that closure; it never does I/O.
    discover: async () => null,
    merge: ({ live }) => live,
  }, { ttlMs });
  return {
    async getLiveClaudeModels(key) {
      const stored = await resolveExecutionCredential({ repo, sealer }, key);
      if (!stored || stored.protocol !== "anthropic" || !stored.apiKey.trim()) return null;
      const baseUrl = stored.baseUrl ?? "https://api.anthropic.com";
      const credentialFingerprint = createHash("sha256").update(stored.apiKey).digest("hex");
      const outcomes = await cache.get({
        cacheKey: [key.workspaceId, key.principalId, stored.protocol, stored.providerId ?? "", baseUrl, credentialFingerprint],
        fallback: [],
      }, {
        discover: async () => {
          const models = await discover({ apiKey: stored.apiKey, baseUrl });
          return models === null ? null : [{ models }];
        },
      });
      return outcomes[0]?.models ?? null;
    },
  };
}

/**
 * The one network call this module makes, isolated so {@link LiveModelDiscovery.getLiveClaudeModels} stays
 * readable. `listProviderModels` returns expected auth, network, timeout and malformed-response failures
 * as `{ok: false, ...}`. The package cache also catches unexpected discovery rejections and records
 * a null result for the same TTL, so a rejected promise never poisons the slot.
 *
 * Logs on `!result.ok` — deliberately the ONLY log line in this module. A live call only reaches
 * this function once {@link LiveModelDiscovery.getLiveClaudeModels} has already resolved a real `anthropic`
 * credential, so a failure here means an admin who set up BYOK for Claude is silently getting the
 * static fallback list instead of the live one they configured — worth an operator seeing, unlike
 * the no-credential/wrong-protocol paths (expected, quiet by design). One line, not a stack: the
 * `listProviderModels` result already redacts the key (`redactSecrets`), so `result.detail` is
 * safe to log as-is.
 *
 * @complexity O(1) local work; one outbound HTTPS call bounded by `listProviderModels`'s own
 *   12s timeout.
 */
export async function fetchLiveClaudeModels(
  { apiKey, baseUrl }: { apiKey: string; baseUrl: string },
  { listModels = listProviderModels }: { listModels?: typeof listProviderModels } = {},
): Promise<readonly ProviderModelOption[] | null> {
  const result = await listModels({ protocol: "anthropic", baseUrl, apiKey });
  if (!result.ok) {
    console.warn(
      `[assistant] live Claude model discovery failed (${result.kind}${result.detail ? `: ${result.detail}` : ""}) — falling back to the static model list`,
    );
    return null;
  }
  return result.models ?? null;
}

/**
 * Merges a live-discovered model list into the static fallback list, per design doc §3.5: UNION,
 * never replace. `fallback` is always fully present in the result, in its original order — there
 * is no code path here that can drop the `'default'` sentinel or the bare `sonnet`/`opus`/`haiku`
 * aliases, because nothing is ever removed from it. `live` entries are appended in their given
 * order, skipping any `id` already present (from `fallback` or an earlier `live` entry).
 *
 * @complexity O(f + l) where f/l are the fallback/live list lengths — one `Set` built from
 *   `fallback`, one pass over `live`.
 */
export function unionModels(
  fallback: readonly AgentModelSummary[],
  live: readonly ProviderModelOption[],
): AgentModelSummary[] {
  // Preserve Tovu's client-safe projection: fallback metadata survives, while discovered entries
  // expose only the model ID and label. Deduplication/order belong to the package merger.
  return unionModelCatalog({ fallback, live: live.map(({ id, label }) => ({ id, label })) });
}

import { nativeToolMetadata } from '../contracts/core/tool-metadata/index.js';
// Membership is derived from each owning domain's reviewed metadata.
// Credential forms submit secrets only to an already parked, principal-bound exchange.
// See the owning tool metadata and handlers for each card's rationale.
/**
 * @file The MCP-UI confirmation redemption allowlist (ADR-053 Decision 3, Decision 6's stopgap
 * posture carried forward into the real transport).
 *
 * `POST /api/admin/v1/mcp-ui/tool-calls` executes a named tool on a human's confirmed click inside
 * a rendered MCP-UI dialog — but the dialog's HTML is untrusted (`@jini-ai/chat`'s
 * `create-mcp-ui-tool-caller.ts`, the client half, says this outright: it performs no validation of
 * `toolName`/`params` and holds no allow-list of its own by design, because a View's HTML came from
 * a tool author, not this host). Without a server-side allowlist, this endpoint would be a general
 * tool-execution surface reachable by anything an agent's own tool result can render — exactly the
 * "worse than no gate" outcome ADR-053's Context section names for a confirmation the model can
 * route around. This module is that allowlist, shared by both halves of the redemption path (the
 * daemon-side execution route and Tovu's session-authenticated proxy in front of it — see
 * `mcp-ui-tool-calls-route.ts` and `server/modules/assistant.ts`) so the two cannot drift apart.
 */

import { FEDERATED_TOOL_ID_PREFIX } from "@jini-ai/mcp/federation";

/**
 * Tool ids `mcp-ui-tool-calls-route.ts`'s callback endpoint is willing to reach at all — for either
 * shape it speaks: an exchange delivery (ADR-055 Decisions 1/2) or the legacy token-redemption call
 * (ADR-053 Decision 3). Every other `toolName` is refused unconditionally, before either shape's
 * branch even runs.
 *
 * Being on this list is necessary but not sufficient for safety — it is not what MAKES a tool safe
 * to reach this way, only a gate on which already-safe tools this endpoint will forward to. A tool
 * with effects belongs here only if its handler parks on a principal-bound exchange or performs
 * single-use, TTL-bound token redemption. Otherwise a fresh callback could execute without human
 * approval. Pure callbacks have explicit per-tool carve-outs at the owning metadata rows (for
 * example demo form readback and content_post_search); ordinary authorization still applies.
 *
 * ADR-053 Decision 6 requires widening this surface only by deliberate per-tool review.
 */
export const MCP_UI_REDEEMABLE_TOOL_IDS: ReadonlySet<string> = nativeToolMetadata.redeemableIds;

/**
 * Whether `toolName` may be executed through the MCP-UI redemption endpoint.
 *
 * @complexity O(1) — a `Set` lookup.
 * @overallScore 100
 */
export function isMcpUiToolCallAllowed(toolName: string): boolean {
  return MCP_UI_REDEEMABLE_TOOL_IDS.has(toolName);
}

/**
 * The one rule both halves of the redemption path apply (the daemon route and Tovu's proxy):
 * all secret-bearing forms and permanent-delete cards require an exchange;
 * other allowlisted ids pass.
 * A FEDERATED id (`mcp__<connection>__<name>`) passes only when the
 * request answers an open card (names an exchange, or is a typed answer resolved to one).
 *
 * Why federated ids are not simply allowlisted: they are discovered at runtime, and every one of them
 * declaring a protected action opens a per-call confirmation card (G3, `external-mcp-call-
 * confirmation.ts`). Answering that card only hands a decision to a call that is already parked and
 * already authorized; it executes nothing, and the exchange's own binding (tool id + principal)
 * decides whether the answer lands. Letting the same id reach Shape 2 would make this route a way to
 * RUN a third-party tool from a surface's HTML with no human in the loop, so it never does.
 *
 * @complexity O(1).
 */
export function isMcpUiToolCallPermitted(toolName: string, answersAnExchange: boolean): boolean {
  // Form secrets must reach a parked handler, never a fresh tool execution or its input audit.
  // Destructive/publish policy cards may answer a parked call, never execute a new call via this endpoint.
  // An exchange-only constraint does not itself admit an otherwise unlisted callback.
  if (MCP_UI_REDEEMABLE_TOOL_IDS.has(toolName)) return answersAnExchange || !nativeToolMetadata.exchangeOnlyIds.has(toolName);
  // Plugin tools (`p_<plugin>__<tool>`) park on the same principal-bound exchange when they ask;
  // only the click answering that parked call is accepted, never a fresh execution.
  return answersAnExchange && (toolName.startsWith(FEDERATED_TOOL_ID_PREFIX) || PLUGIN_TOOL_ID.test(toolName));
}

/** The plugin tool contract's namespaced id shape (`pluginToolIdFor` in `@jini-ai/plugins/host`). */
const PLUGIN_TOOL_ID = /^p_[a-z0-9_]+__[a-z0-9_]+$/;

import type { SettingsRepoPort, getEffective } from "@jini-ai/core/settings";
import { ASSISTANT_PERMANENT_DELETES_NAMESPACE, ASSISTANT_PERMANENT_DELETES_KEY, DEFAULT_PERMANENT_DELETES_POLICY, PERMANENT_DELETE_TOOLS, type AssistantPermanentDeletesPolicy } from "../contracts/headless/assistant-permanent-deletes-policy.js";
export interface PermanentDeleteSettingsDeps {
  settingsRepo: SettingsRepoPort; getEffective: typeof getEffective; settingsReady: Promise<void>; workspaceId: string;
}
/** Owner chats inherit the admin's delete capabilities; the human card still gates every effect.
 * Non-owner callers retain the site's explicit grant, including fresh revocation checks.
 * @complexity O(13) local time/space plus owner lookup or one settings read. */
export async function readChatPermanentDeletesPolicy(
  required: PermanentDeleteSettingsDeps & { ownerPrincipalId: Promise<string>; principalId?: string },
  _optional = {},
): Promise<AssistantPermanentDeletesPolicy> {
  if (required.principalId && required.principalId === await required.ownerPrincipalId) {
    return { enabled: true, allowedToolIds: PERMANENT_DELETE_TOOLS.map(tool => tool.id) };
  }
  return readAssistantPermanentDeletesPolicy(required);
}
/** Fresh per run/call. Missing or invalid values deny; unavailable storage propagates.
 * @param required - The existing site ledger, effective-value resolver and definition readiness.
 * @returns A copied OFF policy for absent/malformed values, or the validated site grant.
 * @throws Storage/readiness failures propagate and cannot become a grant.
 * @example await readAssistantPermanentDeletesPolicy({ settingsRepo, getEffective, settingsReady, workspaceId });
 * @complexity O(13) time/space and one effective workspace-setting resolution. */
export async function readAssistantPermanentDeletesPolicy(required: PermanentDeleteSettingsDeps, _optional = {}): Promise<AssistantPermanentDeletesPolicy> {
  await required.settingsReady;
  const result = await required.getEffective({ repo: required.settingsRepo }, {
    namespace: ASSISTANT_PERMANENT_DELETES_NAMESPACE, key: ASSISTANT_PERMANENT_DELETES_KEY,
    scopeContext: { workspaceId: required.workspaceId },
  });
  const value = result?.value as Partial<AssistantPermanentDeletesPolicy> | null;
  if (!value || typeof value.enabled !== "boolean" || !Array.isArray(value.allowedToolIds) ||
    value.allowedToolIds.length > PERMANENT_DELETE_TOOLS.length || new Set(value.allowedToolIds).size !== value.allowedToolIds.length ||
    value.allowedToolIds.some(id => !PERMANENT_DELETE_TOOLS.some(tool => tool.id === id))) {
    return { ...DEFAULT_PERMANENT_DELETES_POLICY, allowedToolIds: [] };
  }
  return { enabled: value.enabled, allowedToolIds: [...value.allowedToolIds] };
}

import { createSqliteChatMaintenance } from "@jini-ai/chat/store/sqlite";
import { createPgliteChatMaintenance } from "@jini-ai/chat/store/pglite";
import { createPostgresChatMaintenance } from "@jini-ai/chat/store/postgres";
import { sweepExpiredChats as sweep, startChatExpirySweep as startSweep } from "@jini-ai/chat/store/runtime";
import { chatKernel, type ChatKernel } from "#src/platform/db/chat-kernel";
import type { SqliteConnectionSource } from "@jini-ai/db/kernel/sqlite";
export { CHAT_EXPIRY_SWEEP_INTERVAL_MS } from "@jini-ai/chat/store/runtime";
/** Maintenance authority stays at composition time; no owner-scoped store can sweep others. */
function maintenanceFor(store: ChatKernel | SqliteConnectionSource) {
  const kernel = chatKernel(store);
  return kernel.transport === "better-sqlite3" ? createSqliteChatMaintenance({ kernel })
    : kernel.transport === "pglite" || kernel.transport === "pglite-socket" ? createPgliteChatMaintenance({ kernel })
    : createPostgresChatMaintenance({ kernel });
}
export function sweepExpiredChats(store: ChatKernel | SqliteConnectionSource, now = Date.now()): Promise<number> {
  return sweep({ maintenance: maintenanceFor(store) }, { now });
}
export function startChatExpirySweep(store: ChatKernel | SqliteConnectionSource, options: Parameters<typeof startSweep>[1] = {}): () => Promise<void> {
  return startSweep({ maintenance: maintenanceFor(store) }, options);
}

