/**
 * One wired domain: its builder and the risk classification its own wiring file maintains.
 *
 * `build`'s second parameter is optional to implement, not optional to pass — every domain builder
 * that ignores surfaces simply declares one parameter, which is assignable.
 *
 * Local name for the assistant-owned static contributions; the contract is {@link ToolContributor}.
 */
type DomainSlice = ToolContributor;

/**
 * Assistant-owned tools, in stable registration order. Feature-owned tools arrive through the
 * composition-owned registry; see `tool-contribution-registry.ts`.
 *
 * Ordering is not required for correctness: {@link buildAssistantToolRegistrations} refuses
 * duplicate ids rather than letting a later entry win. Stable order keeps catalog snapshots readable.
 */
const DOMAIN_SLICES: readonly DomainSlice[] = [
  { domain: "tool-gaps", build: buildToolGapsRegistrations, risk: toolGapsDerivedRisk },
  // The four in-chat UI surfaces register unconditionally. Each module explains why its
  // transport demonstration belongs in a real chat pane.
  { domain: "demo-choices", build: buildDemoChoicesRegistrations, risk: demoChoicesDerivedRisk },
  // A2UI's multi-turn counterpart — `demo-choices` above proves the one-shot MCP-UI return path;
  // this proves the shape A2UI exists for (`createSurface -> action -> updateComponents -> action`).
  { domain: "demo-a2ui", build: buildDemoA2uiRegistrations, risk: demoA2uiDerivedRisk },
  // Proves the typed-media transport (`tool_result.media`, a hand-rolled real PNG) end to end in a
  // real chat pane — the counterpart to `demo-choices`/`demo-a2ui` proving MCP-UI/A2UI's own
  // transports. See `demo-image-tool.ts`'s own header for why the image is generated in-process
  // rather than fetched from a real image-generation service.
  { domain: "demo-image", build: buildDemoImageRegistrations, risk: demoImageDerivedRisk },
  // General-purpose: lets the model draw ANY component the catalog knows about (basic primitives
  // plus every shadcn/recharts registry component), not a scripted fixed shape.
  { domain: "render-ui", build: buildRenderUiRegistrations, risk: renderUiDerivedRisk },
  // Also registers the component-catalog tools for BYOK delegated execution; MCP top-level
  // registration alone does not put them in this registry. See `component-catalog-tool.ts`.
  { domain: "component-catalog", build: buildComponentCatalogRegistrations, risk: componentCatalogDerivedRisk },
  // Production choices accept the model's title/options; demo-choices uses a fixed sample.
  // See `ask-choice-tool.ts` for the separate contracts.
  { domain: "ask-choice", build: buildAskChoiceRegistrations, risk: askChoiceDerivedRisk },
  // Re-auth notices point to Settings' authorize flow; see `external-mcp-reauth-tool.ts`
  // for the cross-process and sandbox constraints against calling beginConnect here.
  { domain: "external-mcp-reauth", build: buildExternalMcpReauthRegistrations, risk: externalMcpReauthDerivedRisk },
  // Read-only fallback for actions requiring an admin screen; `admin-screen-link-tool.ts`
  // explains why neither server-route validation nor page.navigate owns that contract.
  { domain: "admin-screen-link", build: buildAdminScreenLinkRegistrations, risk: adminScreenLinkDerivedRisk },
];

/**
 * Every wired domain, static and registry-contributed together, in the order their tools are
 * registered — `DOMAIN_SLICES` first, then whatever `installFirstPartyToolContributors()` (or a
 * test) has registered into its explicit core contribution registry.
 *
 * Computed fresh on every call rather than once at module load: unlike `DOMAIN_SLICES`, contributed
 * entries are populated at COMPOSITION-ROOT-BOOT time, not at module-import time (that is the whole
 * point of the registry — see `tool-contribution-registry.ts`'s header), so a value captured at
 * module load could observe zero contributors if evaluated before the composition root's install
 * call runs. This function is cheap (one array concat) and is not on any hot request path.
 */
function allToolContributors(contributions?: AssistantToolContributions): readonly DomainSlice[] {
  return [...DOMAIN_SLICES, ...(contributions?.contributors.list({}) ?? [])];
}

/**
 * Every domain's risk classification folded into one map, refusing any id two domains both wire.
 *
 * Computed fresh per call (see {@link allToolContributors}) rather than once at module load — a
 * cross-domain id collision still stops the FIRST real use (the composition root's own
 * `buildAssistantToolRegistrations` call, immediately after its `installFirstPartyToolContributors()`
 * call) rather than surfacing as a mysteriously double-registered tool deep in a request handler;
 * it is simply no longer module-load time specifically, since contributed domains do not exist yet
 * at module-load time. The one real collision in the current catalogs —
 * `backup_create_restore_point`, declared by both Database and Recovery — passes because Recovery
 * declares it unwired and so contributes no risk entry, which is the resolution this check exists
 * to force.
 */
function derivedRiskByToolId(contributions?: AssistantToolContributions): DerivedRiskByToolId {
  // Derived (post-processing) contributors — today `trash_item`, a tool of its own (a new id, a new
  // schema, its own `deletes-durable-state` declaration) — are classified and cross-checked like any
  // other wired tool. The `content_read.*` cards are deliberately absent: each is a relabel of member
  // tools whose risk was already checked under their original ids (see `content-read-tool.ts`).
  return mergeDerivedRiskMaps({ slices: [...allToolContributors(contributions), ...(contributions?.derivedContributors.list({}) ?? [])] });
}

/**
 * The assistant-wide view of the kit's `assertToolIsWirable`: same gate, consulting every domain's
 * classification at once instead of one domain's.
 *
 * Exported because the contract tests assert this layer's refusals directly — that a catalog entry
 * cannot downgrade its own declared risk, that an unclassified id is refused rather than assumed
 * safe, and that no tool demanding a human-confirmation transport can be wired while none exists.
 * Those are properties of the whole tool surface, so the test needs the whole-surface map.
 *
 * @param toolId - The tool id to check.
 * @param catalogEntry - Its `agent-tools.ts` entry, the declared side of the comparison.
 * @throws {Error} If the tool is unclassified, misclassified, or needs missing confirmation support.
 * @complexity O(1).
 * @overallScore 100
 */
export function assertRiskMetadataIsWirable(toolId: string, catalogEntry: AgentToolDefinition, contributions?: AssistantToolContributions): void {
  assertToolIsWirable({ toolId, catalogEntry, derivedRisk: derivedRiskByToolId(contributions) });
}

/** Supply host-owned site ports while preserving the peer bag's fail-closed lookup contract. */
function enrichToolRouteDeps({ routeDeps }: { routeDeps: AssistantToolRegistryDeps }, _optional = {}): AssistantToolRegistryDeps {
  // Enriches (never mutates) the caller's own `routeDeps` with the site-switcher flag `sites` needs
  // and cannot import for itself. `routeDeps.isSiteSwitcherEnabled ??` preserves a test's own fake.
  const enrichment = {
    ...routeDeps,
    isSiteSwitcherEnabled: routeDeps.isSiteSwitcherEnabled ?? REAL_IS_SITE_SWITCHER_ENABLED,
    devRestart: routeDeps.devRestart === undefined ? devRestartPortFromEnv() : routeDeps.devRestart,
  };
  // Keep peer composition's fail-closed missing-field behavior through this enrichment.
  return new Proxy(enrichment, {
    get: (target, key, receiver) => key === "isSiteSwitcherEnabled" || key === "devRestart"
      ? Reflect.get(target, key, receiver) : Reflect.get(routeDeps, key),
  });
}

type ToolAssemblyInput = {
  routeDeps: AssistantToolRegistryDeps;
  surfaces: ChatDeleteSurfaceDeps;
  contributions?: AssistantToolContributions;
  policy: AssistantPermanentDeletesPolicy;
};

/** Assemble domain handlers in catalog order, refusing duplicate admitted ids. */
function collectDomainRegistrations({ routeDeps, surfaces, contributions, policy }: ToolAssemblyInput, _optional = {}) {
  const registrations: ToolRegistration[] = [];
  const ownerByToolId = new Map<string, string>();
  for (const slice of allToolContributors(contributions)) {
    for (const registration of slice.build(routeDeps, surfaces)) {
      // The owner opt-in absorbs the former static ban; forbidden tools never pass.
      if (!isChatToolAllowed({ toolId: registration.descriptor.id, policy })) continue;
      const owner = ownerByToolId.get(registration.descriptor.id);
      if (owner) {
        // Unreachable while `derivedRiskByToolId()`'s merge holds — a tool cannot be wired
        // without a risk entry, and the merge already refuses a shared id. Kept because that
        // argument is about today's code: this is the check on the actual registration list, and
        // it is what `ToolRegistry` would otherwise silently accept a second binding for.
        throw new Error(
          `tool-registrations.ts: '${registration.descriptor.id}' is registered by both the ${owner} and ${slice.domain} domains — one tool id must resolve to exactly one handler`,
        );
      }
      ownerByToolId.set(registration.descriptor.id, slice.domain);
      registrations.push(registration);
    }
  }

  return { registrations, ownerByToolId };
}

/** Append derived handlers, retaining the original domain-only snapshot for every pass. */
function appendDerivedRegistrations({ registrations, ownerByToolId, routeDeps, surfaces, contributions, policy }:
  ToolAssemblyInput & { registrations: ToolRegistration[]; ownerByToolId: Map<string, string> }, _optional = {}): void {
  // Derived contributors reuse already-built domain handlers, so run after domain assembly.
  // Each derive sees only the domain contributions, not earlier derived passes.
  // Pushed before the collapse's early return so both shapes include them.
  const contributed: readonly ToolRegistration[] = [...registrations];
  for (const derived of contributions?.derivedContributors.list({}) ?? []) {
    for (const registration of derived.derive({ registrations: contributed, routeDeps, surfaces })) {
      if (!isChatToolAllowed({ toolId: registration.descriptor.id, policy })) continue;
      const owner = ownerByToolId.get(registration.descriptor.id);
      if (owner) {
        throw new Error(
          `tool-registrations.ts: '${registration.descriptor.id}' is registered by both the ${owner} domain and ${derived.domain}'s post-processing pass — one tool id must resolve to exactly one handler`,
        );
      }
      ownerByToolId.set(registration.descriptor.id, derived.domain);
      registrations.push(registration);
    }
  }
}

/** Derive read cards before host target adaptation, retaining their source domain for peer gates.
 * @complexity O(t) registration work for t tools, no storage access or input mutation.
 */
function prepareReadRegistrations({ registrations, ownerByToolId, routeDeps, options, beforeLookup }: {
  registrations: readonly ToolRegistration[]; ownerByToolId: Map<string, string>; routeDeps: AssistantToolRegistryDeps;
  options: { includeContentReadCollapse?: boolean; contributions?: AssistantToolContributions };
  beforeLookup: ChatDeleteSurfaceDeps["assertChatDeleteAllowed"];
}, _optional = {}): ToolRegistration[] {
  const readRegistrations = options.includeContentReadCollapse === false ? [...registrations] : deriveContentReadRegistrations(registrations);
  for (const [toolId, owner] of [...ownerByToolId]) ownerByToolId.set(currentToolIdFor(toolId), owner);
  return options.contributions?.contentTargetInputs?.({ registrations: readRegistrations, routeDeps, beforeLookup }) ?? readRegistrations;
}

/**
 * Builds the complete agent-tool surface for one workspace's route-deps bag.
 *
 * @param routeDeps - The same dependency bag the admin HTTP routes are built from (structurally —
 * see {@link AssistantToolRegistryDeps}), so a tool call and the equivalent human click reach
 * identical domain code.
 * @param surfaces - Assistant-transport machinery for surface-raising tools. Defaults to a fresh,
 * unshared store, which is right for the many tests that build the registration list only to inspect
 * descriptors and never execute a handler. A caller that also mounts
 * `registerMcpUiToolCallsRoute` must pass its own instance — see {@link AssistantSurfaceDeps}.
 * Production composition passes the same store to this builder and the callback route.
 * Tests that execute a surface-raising handler must do likewise or its exchange is unreachable.
 * @returns Every wired domain's registrations, concatenated in {@link DOMAIN_SLICES} order.
 * @throws {Error} If two domains register the same tool id, or if any domain's own build-time gates
 * refuse (unclassified risk, missing `inputSchema`, catalog drift, an entry neither wired nor
 * declared unwired).
 * @complexity O(t) in the total wired-tool count.
 * @overallScore 100
 */
export function buildAssistantToolRegistrations(
  routeDeps: AssistantToolRegistryDeps,
  surfaces: AssistantSurfaceDeps = { surfaceExchanges: createSurfaceExchangeStore({ scheduler: createTimeoutScheduler({}), clock: createSystemClock(), idGenerator: createRandomUuidGenerator(), defaultChannel: "mcp-ui" }) },
  /** Test seam, mirroring `buildToolCatalogQuery`'s own `includeSearchKeywords`/`indexedDescriptionFor`'s
   *  own `includeDoc2query`. `includeContentReadCollapse: false` returns every domain's raw
   *  registrations BEFORE the `content_read` collapse below — the ONLY way to reconstruct the
   *  pre-collapse tool set now that this function performs the real collapse unconditionally by
   *  default, needed by `development/evals/tool-search-parent-tool-read.eval.ts`'s own earlier,
   *  synthetic-arm sections to keep measuring a valid "what if we had not collapsed" comparison
   *  against the now-real thing. Every real caller (the two production composition roots) leaves
   *  this at its default. */
  options: {
    readonly contributions?: AssistantToolContributions; readonly includeContentReadCollapse?: boolean;
    /** Test seam: which tools take `items` (default: every tool not on `BATCH_OPT_OUT`); lets a test batch a tool whose approval class asks. */
    readonly batchableTools?: readonly BatchableTool[];
    /** Boot roots retain all eligible handlers; discovery applies a fresh per-run grant. */
    readonly permanentDeletePolicy?: AssistantPermanentDeletesPolicy;
    /** Disable only when rebuilding handlers over the host's read-only peer dependencies. */
    readonly targetScope?: "on" | "off";
  } = {},
): ToolRegistration[] {
  const enrichedRouteDeps = enrichToolRouteDeps({ routeDeps });
  const assertChatDeleteAllowed = async ({ toolId, principalId }: { toolId: string; principalId?: string }) => {
    const policy = await readChatPermanentDeletesPolicy({ ...routeDeps, principalId, settingsReady: routeDeps.settingsUiTabsReady });
    if (!isChatToolAllowed({ toolId, policy })) throw chatDeleteRefusal({ toolId });
  };
  const guardedSurfaces: ChatDeleteSurfaceDeps = { ...surfaces, assertChatDeleteAllowed };
  const policy = options.permanentDeletePolicy ?? DEFAULT_PERMANENT_DELETES_POLICY;
  const { registrations, ownerByToolId } = collectDomainRegistrations({ routeDeps: enrichedRouteDeps,
    surfaces: guardedSurfaces, contributions: options.contributions, policy });

  appendDerivedRegistrations({ registrations, ownerByToolId, routeDeps: enrichedRouteDeps,
    surfaces: guardedSurfaces, contributions: options.contributions, policy });

  // `content_read` runs after domain assembly because it reuses the built registrations;
  // see `content-read-tool.ts` for its ownership and per-resource permission contract.
  // Apply after derivation: trash_item delegates to the original domain handlers, so one
  // approval covers the selected action instead of asking again inside its delegate.
  // Before collapse: content_read cards inherit the checked read registrations.
  const guardedRegistrations = registrations.map(registration => PERMANENT_DELETE_TOOLS.some(tool => tool.id === registration.descriptor.id)
    ? { ...registration, handler: async (ctx: import("@jini-ai/core").ToolExecutionContext, optional?: import("@jini-ai/core").ToolExecutionOptions) => {
      await assertChatDeleteAllowed({ toolId: registration.descriptor.id, principalId: ctx.principal.id });
      return registration.handler(ctx, optional);
    } } : registration);
  const approvedRegistrations = guardedRegistrations.map(registration => applyToolApprovalPolicy({ registration, surfaces: guardedSurfaces }, {
    localeFor: async ctx => {
      if (!routeDeps.settingsRepo) return "en";
      const setting = await getEffectiveSetting({ repo: routeDeps.settingsRepo }, {
        namespace: LANGUAGE_NAMESPACE, key: "locale",
        scopeContext: { workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id },
      });
      return typeof setting?.value === "string" ? setting.value : "en";
    },
  }));
  // Collapse before target adapters/scoping/batching: every card item selects get/list after its
  // own normalization, and a slug is resolved only after the selected site's permission gate.
  const inputRegistrations = prepareReadRegistrations({ registrations: approvedRegistrations, ownerByToolId, routeDeps: enrichedRouteDeps, options, beforeLookup: assertChatDeleteAllowed });
  const peer = routeDeps.peerSiteReads;
  const peerReadable = ({ registration }: { registration: ToolRegistration }) => !!peer && isReadOnlyTool({ descriptor: registration.descriptor })
    && peer.readDomains.has(ownerByToolId.get(registration.descriptor.id) ?? '') && !peer.excludedReadTools?.has(registration.descriptor.id);
  const scopedRegistrations = options.targetScope !== "off" && peer ? inputRegistrations.flatMap(registration => applyTargetScope({
    registrations: [registration],
    isCurrentTarget: ({ target }) => peer.isCurrentSite({ siteName: target }),
    resolveTarget: async ({ target, toolId, principal }) => {
      // Installation ownership is checked BEFORE registry discovery or opening another site's files.
      if (principal.id !== await routeDeps.ownerPrincipalId) throw new ToolInputError({ message: "Only this installation's owner can read other sites." });
      const resolved = await peer.resolve({ siteName: target, toolId, callerPrincipalId: principal.id,
        buildRegistrations: peerDeps => {
          const peerContributions = options.contributions ? {
            ...options.contributions,
            // Excluded builders may touch credentials/live hosts during construction. Never run
            // them over a peer bag, even if their registrations would be discarded afterwards.
            contributors: { ...options.contributions.contributors, list: (required: Record<string, never>) => options.contributions!.contributors.list(required).filter(slice => peer.readDomains.has(slice.domain)) },
            derivedContributors: { ...options.contributions.derivedContributors, list: (required: Record<string, never>) => options.contributions!.derivedContributors.list(required).filter(slice => peer.readDomains.has(slice.domain)) },
            // Adapt once after deriving cards so a card cannot resolve the same target twice.
            contentTargetInputs: undefined,
          } : undefined;
          const raw = buildAssistantToolRegistrations(peerDeps, surfaces, {
            ...options, targetScope: "off", includeContentReadCollapse: false,
            batchableTools: [], contributions: peerContributions,
          });
          // A peer bag is cached across callers using raw or collapsed catalogs. Retain both
          // names over the same domain handlers instead of making the first caller choose its ABI.
          const rawIds = new Set(raw.map(tool => tool.descriptor.id));
          const combined = [...raw, ...deriveContentReadRegistrations(raw).filter(tool => !rawIds.has(tool.descriptor.id))];
          const adapted = options.contributions?.contentTargetInputs?.({ registrations: combined, routeDeps: peerDeps }) ?? combined;
          return adapted.filter(registration => peerReadable({ registration }));
        },
      });
      if (resolved === "current") return resolved;
      return { principal: resolved.principal, handler: async (ctx: import("@jini-ai/core").ToolExecutionContext, optional?: import("@jini-ai/core").ToolExecutionOptions) => {
        // The extra row belongs to the ACTIVE site. Input-key-only executor telemetry cannot
        // identify the selected registry name; no audit sink is constructed on the target.
        await routeDeps.toolAttemptAuditSink.append({
          attemptId: routeDeps.idGen.newId(), executionId: ctx.executionId, workspaceId: routeDeps.workspaceId,
          runId: ctx.run.id, toolId, principalId: principal.id, phase: "requested", at: nowIso({ clock: routeDeps.clock }),
        }, { detail: `cross-site read: ${resolved.site.name} (${resolved.site.siteId})` });
        return resolved.handler(ctx, optional);
      } };
    },
  }, {
    param: "site", describeParam: "Optional. Another local site's name from sites_list; reads that site instead of this one.",
    refuseMessage: isReadOnlyTool({ descriptor: registration.descriptor })
      ? `${registration.descriptor.id} can't read another site yet.`
      : "Writes run only on the active site. Switch with sites_switch_site first.",
    scoped: peerReadable,
  })) : inputRegistrations;
  // `items` batches wrap the APPROVED handler, so each item is classified on its own input; see
  // `batch-tool-inputs.ts` for why the reverse order would let a batch skip an item's approval.
  const batchedRegistrations = applyBatchInputs({ registrations: scopedRegistrations }, { tools: options.batchableTools }).map(registration => {
    const toolId = registration.descriptor.id;
    if (!PERMANENT_DELETE_TOOLS.some(tool => tool.id === toolId) || toolId === "trash_empty" || toolId === "deployment_ops_unset_secret") return registration;
    // The domain's approval lifecycle prepares all selections and asks once. Do not put the
    // ordinary per-item batch executor around it: that would create one confirmation per item.
    const plan = withBatchInput({ registration, tool: { toolId } }, { mode: 'plan' });
    return { ...plan, descriptor: { ...plan.descriptor, description: `${registration.descriptor.description} Batch: pass items: [{...}, ...] (up to 25) to review all targets in ONE confirmation card. No per-item asks. All inputs are prepared before confirmation; a failure during execution stops subsequent items, and earlier effects are not rolled back. Returns {batch:true,total,results}.` } };
  });
  if (options.includeContentReadCollapse === false) return batchedRegistrations;
  const finalRegistrations = batchedRegistrations;
  // A new collapsed card is a new registered tool too: never exempt it from the guard.
  for (const registration of finalRegistrations) toolApprovalPolicyFor({ registration });
  return finalRegistrations;
}

import { nativeToolMetadata } from '../contracts/core/tool-metadata/index.js';
import type { ToolMetadata } from '@jini-ai/core';
import { createSearchEnricher } from '@jini-ai/registry/tool-catalog-builder';
import { DOC2QUERY } from "./tool-search-doc2query.js";
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { bundledContributionSources } from '../features/agent-plugins/bundled-contribution-sources.js';
import { resolveProductRoot } from '../platform/site-dir/product-root.js';

/**
 * Read search-only words from shipped manifests, including disabled plugins. Installed packages
 * cannot contribute here: this root follows the existing bundled contribution trust boundary.
 * Missing or malformed optional metadata contributes nothing; no plugin code is executed.
 * @param required Product-owned bundled root.
 * @param optional Source enumeration and text-reader ports for failure-path tests.
 * @returns Tool vocabulary only, with no authority over registration, approval or callbacks.
 * @complexity O(p + k) for p manifests and k keyword entries; one read per manifest.
 */
export function readBundledToolKeywords(required: { sourceRoot: string }, optional: {
  sources?: typeof bundledContributionSources;
  readText?: (file: string) => string;
} = {}): Record<string, string> {
  const keywords: Record<string, string> = Object.create(null);
  let sources: ReturnType<typeof bundledContributionSources>;
  try { sources = (optional.sources ?? bundledContributionSources)({ ...required, filename: 'plugin.json' }); }
  catch { return keywords; }
  for (const source of sources) {
    try {
      const readText = optional.readText ?? ((file: string) => readFileSync(file, 'utf8'));
      const manifest = JSON.parse(readText(path.join(source.packageRoot, 'plugin.json')));
      appendToolKeywords({ keywords, declaration: manifest?.extensions?.tovu?.toolKeywords });
    } catch { /* Optional search data never prevents tool catalog construction. */ }
  }
  return keywords;
}

/** Ignore non-string values and unknown tool ids; metadata can enrich only existing native tools.
 * @complexity O(k) declared entries, without I/O. */
function appendToolKeywords({ keywords, declaration }: { keywords: Record<string, string>; declaration: unknown }, _optional = {}): void {
  if (typeof declaration !== 'object' || declaration === null || Array.isArray(declaration)) return;
  for (const [id, words] of Object.entries(declaration)) {
    if (!Object.hasOwn(nativeToolMetadata.byId, id) || typeof words !== 'string' || !words.trim()) continue;
    keywords[id] = [keywords[id], words.trim()].filter(Boolean).join(' ');
  }
}

let bundledKeywords: Record<string, string> | undefined;

/** Load optional bundled vocabulary only when search needs it. @complexity O(p + k) once. */
function bundledToolKeywords(_required: Record<string, never>, _optional: Record<string, never> = {}): Record<string, string> {
  return bundledKeywords ??= readBundledToolKeywords({ sourceRoot: path.join(resolveProductRoot(), 'content', 'agent-plugins') });
}
/**
 * @file Operator vocabulary for tool search — the words a human uses that a tool's own description
 * does not contain.
 *
 * ## Why this exists
 *
 * BM25 can rank only indexed vocabulary. Operators ask for "images" or "snapshots" while domain
 * descriptions may say "assets" or "restore points". Meta-tool discovery is the model's route to
 * the catalog, so missing vocabulary makes a working tool unreachable.
 *
 * Choose everyday domain synonyms independently of evaluation queries. The held-out cases in
 * `development/evals/tool-search-quality.eval.ts` assess discovery without shaping this vocabulary.
 * Domain registration contracts own the words; Jini metadata projects them and the shared search
 * enricher folds/strips indexed text without changing authored descriptions.
 *
 * Only tools an operator plausibly asks for in plain language need an entry. A tool absent from this
 * map is unchanged — it keeps ranking on its id and description alone.
 */

/**
 * Tool id -> extra search vocabulary. Space-separated terms; word order does not matter (BM25 treats
 * these as a bag of terms). Include plurals AND singulars explicitly: the index uses FTS5's default
 * `unicode61` tokenizer, which does not stem, so "image" and "images" are different tokens.
 */
let searchKeywords: Readonly<Record<string, string>> | undefined;

/** Merge search-only declarations on first use. Optional manifest failures contribute no words.
 * @complexity O(p + k) manifests and keyword entries once, then O(1). */
export function toolSearchKeywords(_required: Record<string, never>, _optional: Record<string, never> = {}): Readonly<Record<string, string>> {
  if (searchKeywords) return searchKeywords;
  const bundled = bundledToolKeywords({});
  searchKeywords = Object.fromEntries(
    [...new Set([...Object.keys(nativeToolMetadata.keywords), ...Object.keys(bundled)])]
      .map(id => [id, [nativeToolMetadata.keywords[id], bundled[id]].filter(Boolean).join(' ')]),
  );
  return searchKeywords;
}

/** Separates a tool's real description from its appended search vocabulary. Written once, used by
 *  both halves of the fold/strip pair below so the two can never disagree about the boundary.
 *  Exported for `content-read-tool.ts`'s own card-description builder: a merged
 *  `content_read.<resource>` card composes ITS OWN single marker boundary from several retired
 *  tools' plain descriptions plus their combined keyword/doc2query tails (see that file's header)
 *  — reusing this constant keeps that boundary byte-identical to the one `indexedDescriptionFor`
 *  itself would draw, so `stripSearchKeywords` cuts a card's description in exactly the right place
 *  without either file having to know the other's marker text separately. */
export const KEYWORD_MARKER = " — also known as: ";
let enricher: ReturnType<typeof createSearchEnricher> | undefined;

/** Defer vocabulary I/O until search first uses the shared fold/strip implementation. */
function searchEnricher(_required: Record<string, never>, _optional: Record<string, never> = {}): ReturnType<typeof createSearchEnricher> {
  return enricher ??= createSearchEnricher({ marker: KEYWORD_MARKER, keywords: toolSearchKeywords({}), questions: DOC2QUERY });
}

/**
 * Folds a tool's keywords into the text that gets INDEXED.
 *
 * Appending behind one marker lets the shared enricher strip the indexed vocabulary on return.
 *
 * The obvious cost of that shortcut — the model seeing a keyword tail on every hit — is NOT paid,
 * because {@link stripSearchKeywords} removes it again on the way out of `search_tools` and
 * `describe_tool`. The vocabulary exists only inside the FTS index, where BM25 can rank on it and
 * nothing else ever reads it. That split is the whole point: a tool's description is a contract
 * shown to a model, and padding it with synonyms to game a search index would degrade the thing
 * the model actually reasons about in order to fix the thing it searches with.
 */
export function indexedDescriptionFor(
  toolId: string,
  description: string,
  /** Test seam, mirroring `buildToolCatalogQuery`'s own `includeSearchKeywords`. `false` folds the
   *  operator nouns but NOT the doc2query questions, which is the only way to still measure the
   *  pre-adoption baseline now that production includes both — without it, the adoption eval's
   *  "before" arm silently becomes its "after" arm and the comparison reports a null result. */
  options: { readonly includeDoc2query?: boolean; readonly metadata?: ToolMetadata } = {},
): string {
  // Keywords supply operator nouns; doc2query adds verbs and question phrasing that distinguish
  // sibling tools. Both sit behind KEYWORD_MARKER so callers see only authored descriptions.
  return searchEnricher({}).indexedDescription({ id: toolId, description,
    // Registered metadata takes precedence in Jini's enricher. Add the same declared words there
    // without mutating the registration or projecting plugin data into approval policy.
    ...(options.metadata ? { metadata: { ...options.metadata, search: {
      ...options.metadata.search,
      keywords: [options.metadata.search?.keywords ?? nativeToolMetadata.keywords[toolId], bundledToolKeywords({})[toolId]].filter(Boolean).join(' '),
    } } } : {}),
  }, { includeDoc2query: options.includeDoc2query ?? true });
}

/**
 * Inverse of {@link indexedDescriptionFor} — recovers the tool's authored description from whatever
 * was indexed, so no caller of `search_tools`/`describe_tool` ever sees the search vocabulary.
 *
 * Tolerates text with no marker unchanged because every hit passes here, including tools with
 * no search vocabulary. Demo-only tools are excluded from operator-language enrichment.
 */
export function stripSearchKeywords(indexed: string): string {
  return searchEnricher({}).authoredDescription({ description: indexed });
}

import { postJsonToDaemon, readPromptFromFlags } from "@jini-ai/cli";
import { parseSiteImportInput } from "#src/features/site-backup/import-backend";
import { ValidationError } from "#src/platform/site-dir/errors";
import { isLoopbackHost } from "#src/server/runtime/boot/bind-host";
import { isIP } from "node:net";

/** Thin CLI adapter to the SAME authenticated import route, never a second restore lifecycle.
 * Reads {authorization, url|uploadId, displayName?, requestId?} on bounded stdin so credentials,
 * share tokens and owner passwords never become argv. Owner password setup stays in the browser.
 * @throws ValidationError for invalid request/server; transport errors use Jini's CLI contract.
 * @complexity O(request JSON), capped at 16 KiB; the server owns ZIP transfer and verification.
 */
export async function runImportSiteCommand(required: { server: string; workspaceId: string }, optional: {
  readRequest?: () => Promise<string>;
  post?: typeof postJsonToDaemon;
} = {}): Promise<unknown> {
  const server = parseImportServer({ value: required.server });
  if (!required.workspaceId) throw new ValidationError("import: --workspace is required.");
  const text = await readPromptFromFlags({ flags: { "prompt-file": "-" } }, { maxBytes: 16 * 1024, readStdin: optional.readRequest });
  const raw = parseImportRequest({ text });
  const { authorization, ...input } = raw;
  if (typeof authorization !== "string" || !/^Bearer [^\r\n]{1,4096}$/.test(authorization)) throw new ValidationError("import: provide a Bearer API-key authorization in stdin JSON. Never provide an owner password.");
  const parsed = parseSiteImportInput({ input });
  const body = { ...parsed.source, displayName: parsed.displayName, requestId: parsed.requestId };
  const result = await (optional.post ?? postJsonToDaemon)({ base: server.origin, route: "/api/admin/v1/workspaces/" + encodeURIComponent(required.workspaceId) + "/site-imports", body }, { headers: { authorization }, timeoutMs: 5 * 60_000, maxResponseBytes: 64 * 1024 });
  if (result && typeof result === "object" && typeof (result as { setupUrl?: unknown }).setupUrl === "string") return { ...result, setupUrl: new URL((result as { setupUrl: string }).setupUrl, server).href };
  return result;
}

function parseImportServer({ value }: { value: string }, _options: Record<string, never> = {}): URL {
  let server: URL;
  try { server = new URL(value); } catch { throw new ValidationError("import: --server must be an admin server origin."); }
  if (server.username || server.password || server.pathname !== "/" || server.search || server.hash ||
      !isImportProtocolAllowed({ server })) throw new ValidationError("import: use an HTTPS server origin, or HTTP loopback for local development.");
  return server;
}

function isImportProtocolAllowed({ server }: { server: URL }, _options: Record<string, never> = {}): boolean {
  const hostname = server.hostname.replace(/^\[|\]$/g, "");
  return server.protocol === "https:" || Boolean(server.protocol === "http:" && isIP(hostname) && isLoopbackHost(hostname));
}

function parseImportRequest({ text }: { text: string | null }, _options: Record<string, never> = {}): Record<string, unknown> {
  let raw: Record<string, unknown>;
  try {
    // `readPromptFromFlags` with `prompt-file: "-"` always yields the stdin text; a missing value
    // would stringify to non-JSON or `null` and fail the shape check below, never parse as a request.
    raw = JSON.parse(String(text)) as Record<string, unknown>;
    if (!raw || typeof raw !== "object" || Array.isArray(raw)) throw new Error("shape");
  } catch { throw new ValidationError("import: stdin must contain one JSON request object."); }
  return raw;
}

import { createInterface } from "node:readline";
import { Writable } from "node:stream";

import { ValidationError } from "../../platform/site-dir/errors.js";
import { initSite } from "#src/server/runtime/composition/site-dir";
import { readSiteDir } from "../../platform/site-dir/read-site-dir.js";
import type { SiteStorage } from "../../platform/site-dir/types.js";
import { resolveNewSiteAdminPassword } from "../../platform/site-dir/new-site-owner.js";
import {
  readAllStdin,
  assertNewSiteAgentPluginTokensAccepted,
  defaultNewSiteAgentPluginTokenCheck,
  readNewSiteAgentPluginTokensFromStdin,
  storeNewSiteAgentPluginTokens,
  type NewSiteAgentPluginTokenCheck,
  type SealNewSiteAgentPluginTokens,
} from "./agent-plugin-tokens.js";

/**
 * @file SPEC-003 C-001 (`CLI_INIT`) — wires a commander action's parsed arguments to
 * `site-dir/init-site.ts`'s `initSite`, and formats the `CLI_INIT` stdout contract.
 *
 * Architectural role:
 * `cli` layer. Formats stdout only — never maps errors to exit codes itself (that is
 * `cli/errors.ts`'s job; this function lets `initSite`'s typed errors propagate uncaught).
 */

export interface RunInitCommandInput {
  dir: string;
  /** Explicit password; defaults to tovu-dev. Never read from the parent environment. */
  adminPassword?: string;
  /** Desktop's private stdin envelope: { adminPassword, agentPluginTokens? }. */
  createInputStdin?: boolean;
  readCreateInput?: () => Promise<string>;
  name?: string;
  /** Explicit demo/journey fixture opt-in; normal installs contain no posts or pages. */
  withSampleContent?: boolean;
  /** `--storage sqlite|pglite|postgres` (default sqlite). The only way a site is created on PGlite/Postgres. */
  storage?: string;
  /** `--storage-env NAME` (postgres only): the site reads its connection string from this variable. */
  storageEnv?: string;
  /** Postgres without `--storage-env`: where the connection string to seal comes from (default: a terminal prompt, else stdin). */
  readConnectionString?: () => Promise<string>;
  /** `--agent-plugin-tokens-stdin`: read `{ [pluginId]: token }` JSON from stdin, check each token,
   *  and seal them into the new site for its first boot (`agent-plugin-tokens.ts`). */
  agentPluginTokensStdin?: boolean;
  /** Injected for tests. Default: all of stdin. */
  readAgentPluginTokens?: () => Promise<string>;
  /** Injected for tests. Default: the bundled plugins' probe over the guarded client. */
  checkAgentPluginToken?: NewSiteAgentPluginTokenCheck;
  /** Injected for tests. Default: `sealPendingAgentPluginTokensForNewSite`. */
  sealAgentPluginTokens?: SealNewSiteAgentPluginTokens;
}

const STORAGE_KINDS = ["sqlite", "pglite", "postgres"] as const;

/**
 * `--storage` + `--storage-env` to the site's storage choice.
 *
 * @throws {ValidationError} an unknown kind, or `--storage-env` without `--storage postgres`.
 */
export function parseInitStorage(storage: string | undefined, storageEnv: string | undefined): SiteStorage {
  const kind = storage ?? "sqlite";
  if (!(STORAGE_KINDS as readonly string[]).includes(kind)) {
    throw new ValidationError(`init: --storage must be one of ${STORAGE_KINDS.join(", ")}`);
  }
  if (kind !== "postgres") {
    if (storageEnv !== undefined) throw new ValidationError("init: --storage-env applies to --storage postgres only");
    return { kind } as SiteStorage;
  }
  if (storageEnv === undefined) return { kind, secretRef: "site" };
  if (!/^[A-Za-z_]\w*$/.test(storageEnv)) throw new ValidationError("init: --storage-env must be an environment variable name");
  return { kind, secretRef: { env: storageEnv } };
}

/**
 * The connection string to seal: asked for without echo on a terminal, else read from stdin
 * (`printf '%s' "$URL" | tovu init --storage postgres <dir>`). Shared with `tovu storage move`.
 */
export async function readConnectionStringFromUser(
  _required: Record<string, never> = {},
  { input = process.stdin, output = process.stdout }: {
    input?: NodeJS.ReadableStream & { isTTY?: boolean };
    output?: Pick<NodeJS.WritableStream, "write">;
  } = {},
): Promise<string> {
  if (!input.isTTY) {
    const chunks: Buffer[] = [];
    for await (const chunk of input) chunks.push(Buffer.from(chunk as Buffer));
    // Only the first line is the connection string; anything after it is ignored.
    const text = Buffer.concat(chunks).toString("utf8");
    const lineEnd = text.search(/\r?\n/);
    return lineEnd === -1 ? text : text.slice(0, lineEnd);
  }
  output.write("Postgres connection string (not shown): ");
  const muted = new Writable({ write: (_chunk, _encoding, done) => done() });
  const rl = createInterface({ input, output: muted, terminal: true });
  try {
    return await new Promise<string>((resolve) => rl.once("line", resolve));
  } finally {
    rl.close();
    output.write("\n");
  }
}

/**
 * Run `tovu init <dir> [--name]`: create the install dir, then print the api.spec.md §5 success
 * contract (`created site '<name>' at <dir>` + `next: tovu serve <dir>`).
 *
 * @throws whatever `initSite` throws (`ValidationError`, `InitDirNotEmptyError`,
 *   `InternalError`) — `cli/main.ts` maps these to the correct exit code.
 * @complexity O(1) beyond `initSite`'s own bounded cost.
 * @overallScore 100
 */
export async function runInitCommand(input: RunInitCommandInput, _options: Record<string, never> = {}): Promise<void> {
  const storage = parseInitStorage(input.storage, input.storageEnv);
  const sealed = storage.kind === "postgres" && storage.secretRef === "site";
  assertSeparateInitStdin({ input, sealed });
  const createInput = await readCreateInput(input);
  const adminPassword = resolveNewSiteAdminPassword({ adminPassword: input.createInputStdin ? createInput.adminPassword : input.adminPassword });
  const tokens = await readAndCheckInitTokens({ input, createInput });
  const connectionString = sealed ? (await (input.readConnectionString ?? readConnectionStringFromUser)()).trim() : undefined;
  const result = await initSite({ dir: input.dir, name: input.name, storage, connectionString, adminPassword }, { withSampleContent: input.withSampleContent });
  // Read the ACTUAL written config.json back (rather than re-deriving the name here) so the
  // printed name can never drift from what `initSite` really wrote to disk.
  const { config } = readSiteDir({ dir: result.dir });
  process.stdout.write(`created site '${config.name}' at ${result.dir}\n`);
  process.stdout.write(`next: tovu serve ${result.dir}\n`);
  await storeNewSiteAgentPluginTokens(result, tokens, input.sealAgentPluginTokens);
}

/** Read desktop's create credentials once, without putting a secret in argv, env, or diagnostics.
 * @throws {ValidationError} conflicting stdin consumers or malformed input. @complexity O(n) in stdin bytes.
 */
async function readCreateInput(input: RunInitCommandInput, _options: Record<string, never> = {}): Promise<{ adminPassword?: unknown; agentPluginTokens?: unknown }> {
  if (!input.createInputStdin) return {};
  if (input.adminPassword !== undefined || input.agentPluginTokensStdin) {
    throw new ValidationError("init: --create-input-stdin cannot be combined with --admin-password or --agent-plugin-tokens-stdin");
  }
  // The real stdin reader is wired here, at the command edge; tests inject their own.
  const { readCreateInput: readInput = readAllStdin } = input;
  let raw: unknown;
  try {
    raw = JSON.parse(await readInput());
  } catch {
    throw new ValidationError("init: --create-input-stdin expects a JSON object on stdin");
  }
  if (raw === null || typeof raw !== "object" || Array.isArray(raw)) {
    throw new ValidationError("init: --create-input-stdin expects a JSON object on stdin");
  }
  const value = raw as Record<string, unknown>;
  return { adminPassword: value.adminPassword, agentPluginTokens: value.agentPluginTokens };
}

function assertSeparateInitStdin({ input, sealed }: { input: RunInitCommandInput; sealed: boolean }, _options: Record<string, never> = {}): void {
  if (sealed && (input.agentPluginTokensStdin || input.createInputStdin) && !input.readConnectionString) {
    const stdinFlag = input.createInputStdin ? "--create-input-stdin" : "--agent-plugin-tokens-stdin";
    throw new ValidationError(`init: ${stdinFlag} cannot share stdin with a Postgres connection string; use --storage-env`);
  }
}

async function readAndCheckInitTokens({ input, createInput }: {
  input: RunInitCommandInput;
  createInput: Awaited<ReturnType<typeof readCreateInput>>;
}, _options: Record<string, never> = {}): Promise<Record<string, string>> {
  // Read and checked BEFORE the site is made: a rejected token creates nothing.
  const tokens = input.createInputStdin
    ? await readNewSiteAgentPluginTokensFromStdin(async () => JSON.stringify(createInput.agentPluginTokens ?? {}))
    : input.agentPluginTokensStdin ? await readNewSiteAgentPluginTokensFromStdin(input.readAgentPluginTokens) : {};
  if (Object.keys(tokens).length > 0) await assertNewSiteAgentPluginTokensAccepted(tokens, input.checkAgentPluginToken ?? defaultNewSiteAgentPluginTokenCheck());
  return tokens;
}

