 * the boot log and graceful shutdown (BR-07); `site-dir` remains independent of Express.
 * Bind host is loopback by default (BR-02a), with `--host` overriding `TOVU_HOST` and a
 * warning for a non-loopback result. Errors propagate to `cli/main.ts`; `cli/errors.ts`
 * owns exit-code mapping.
 *
 * Daemon startup waits for settings readiness to avoid duplicate settings writes and
 * resolves an instance-specific port before app composition to avoid cross-site collisions.
 * The CLI owns signal handling: a second daemon signal handler could exit before its
 * graceful drain. Mint the daemon token before spawning so the child inherits it;
 * the daemon auth gate fails closed when no token is configured.
 *
 * CIC U-002-B1/ORD1 and ADR-005 require synchronous SDK resolver registration before
 * any route or plugin-import path, with no preceding await. Otherwise a site plugin
 * can shadow `@tovu/sdk` with its own node_modules and defeat the deep-import boundary.
 * See `runtime/boot/plugin-sdk-resolver.ts` for the owner contract.
 *
 * Shared production-readiness and boot lifecycle gates run before listening or daemon
 * startup: crash-interrupted migrations are reconciled and critical settings/SEO failures
 * refuse serving. Lifecycle failures throw here rather than exiting inside the command.
 *
 * Dev-proxy HMR needs `registerAdminDevProxyUpgrade` on the raw HTTP server: WebSocket
 * upgrade events bypass Express, even though ordinary admin requests reach the proxy.
 * The helper gates itself on the dev-proxy env and SEA packaging.
 */

export interface RunServeCommandInput {
  dir: string;
  port?: string;
  workspaceId?: string;
  /**
   * IP address to bind (LAN-bind plan, 2026-09-23). Wins over `TOVU_HOST` — same precedence shape
   * as `--port` over the `PORT` env var, and the same reason: an explicit flag on THIS invocation is
   * a stronger signal than an ambient env var that might be stale or inherited from a parent shell.
   * Unset means "defer to `TOVU_HOST`, then `DEFAULT_LOCAL_BIND_HOST`" — see `resolveBindHost`.
   */
  host?: string;
  /**
   * Print a single-use loopback boot token on stdout once the listener is up, for a launching
   * process to exchange for an admin session (`features/identity/boot-session-token.ts`). Default
   * OFF: an operator running this by hand must never have a secret appear in their terminal, and a
   * server that mints nothing has the redemption route permanently closed.
   */
  emitBootToken?: boolean;
}

const DEFAULT_PORT = 3000;

/** behavior.spec.md §4: `--port` must be an integer in 1..65535 — out-of-range/non-integer is VALIDATION, not a fall-through. */
function parsePort(raw: string | number): number {
  const str = String(raw).trim();
  if (!/^\d+$/.test(str)) {
    throw new ValidationError(`--port must be an integer between 1 and 65535 (got "${raw}")`);
  }
  const value = Number(str);
  if (value < 1 || value > 65535) {
    throw new ValidationError(`--port must be between 1 and 65535 (got ${value})`);
  }
  return value;
}

/** BR-02: `--port` flag, then `config.json.port`, then `PORT` env, then 3000 — first PRESENT value wins; a present-but-invalid value at any tier is VALIDATION, never a fall-through to the next tier. */
function resolveServePort(input: RunServeCommandInput, config: ConfigJson): number {
  if (input.port !== undefined) return parsePort(input.port);
  if (config.port !== null && config.port !== undefined) return parsePort(config.port);
  if (process.env.PORT !== undefined) return parsePort(process.env.PORT);
  return DEFAULT_PORT;
}

/** BR-04/EC-08: a `dir` argument overrides legacy env vars — logs a warning naming whichever is set, rather than silently ignoring it. */
function warnIfLegacyEnvVarsIgnored(): void {
  if (process.env.TOVU_CHAT_DB !== undefined) {
    process.stderr.write("tovu: warning: TOVU_CHAT_DB is ignored when a dir argument is given\n");
  }
  if (process.env.TOVU_CONTENT_DB !== undefined) {
    process.stderr.write("tovu: warning: TOVU_CONTENT_DB is ignored when a dir argument is given\n");
  }
  if (process.env.TOVU_DB !== undefined) {
    process.stderr.write("tovu: warning: TOVU_DB is ignored when a dir argument is given\n");
  }
}

/**
 * Pins `TOVU_DISABLE_DEV_TLS=1` for this process and (by inheritance) the agent daemon it spawns.
 * `tovu serve` always listens on plain HTTP, but `deps.ts`'s `devCapabilityScheme`/
 * `derivedPublicOrigin` — computed in both processes — say `https` whenever the checkout's `.certs/`
 * pair exists, which would hand OAuth providers and emailed links an `https://` URL for an
 * `http://` server. Set unconditionally for the same reason as {@link pinServedSiteDirIntoEnv}:
 * this listener's scheme is a fact, not a preference.
 *
 * @param env - defaults to `process.env`; injectable for tests.
 * @complexity O(1).
 */
export function pinPlainHttpIntoEnv(env: NodeJS.ProcessEnv = process.env): void {
  env.TOVU_DISABLE_DEV_TLS = "1";
}

/**
 * Pins `TOVU_SITE_DIR` to the resolved CLI target before any site-derived read or spawn.
 * API and daemon must share chat, journal, skills, plugin and attachment paths; deriving
 * them from cwd would disagree with explicit `tovu serve <dir>` overrides.
 * The explicit CLI target wins over an existing env value for every path family.
 * Setting the parent env also propagates the same binding to its daemon child.
 * Legacy DB overrides are cleared here so the daemon inherits the same database layout.
 *
 * @param target - Already-resolved absolute install-dir target.
 * @param env - Defaults to `process.env`; injectable to avoid mutating the test runner.
 * @complexity O(1).
 */
export function pinServedSiteDirIntoEnv(target: string, env: NodeJS.ProcessEnv = process.env): void {
  env.TOVU_SITE_DIR = target;
  // The API passes explicit site paths; the daemon resolves defaults from this inherited env.
  delete env.TOVU_CHAT_DB;
  delete env.TOVU_CONTENT_DB;
  delete env.TOVU_DB;
  // An explicit CLI target must be unswitchable in the daemon as well as the API.
  // The child reconstructs its binding from env; see SITE_BINDING_NOT_SWITCHABLE_ENV.
  env[SITE_BINDING_NOT_SWITCHABLE_ENV] = "1";
}

export interface RunServeCommandOptional {
  /** Preserve the real boot while allowing per-command resolver and worker lifecycle witnesses. */
  registerPluginSdkResolver?: typeof registerPluginSdkResolver;
  createServingApp?: typeof createServingApp;
}

/**
 * Run `tovu serve <dir> [--port]`: validate/guard/migrate/stamp/resolve the install dir
 * (`bootSiteDir`), wire the existing composition root's `overrides` branch, and bind a listener.
 *
 * @throws whatever `bootSiteDir` throws (`SiteDirInvalidError`, `SiteNewerThanRuntimeError`,
 *   `SiteCorruptError`), a `ValidationError` (bad `--port`), or a `PortInUseError` (`EADDRINUSE`)
 *   — `cli/main.ts` maps each to the correct exit code.
 * @complexity O(1) beyond `bootSiteDir`'s own bounded cost; the returned promise resolves once
 *   the listener is bound (the process then stays alive on the open socket, not on this promise).
 * @overallScore 100
 */
export async function runServeCommand(input: RunServeCommandInput, optional: RunServeCommandOptional = {}): Promise<void> {
  // Install before boot: detached identity seed promises can reject independently of identityReady.
  // See runtime/boot/process-error-guards.ts for the process-wide guard rationale.
  installUnhandledRejectionGuard();
  // Server log capture (gap A-04): keeps recent console output in memory, redacted, so the admin
  // server-logs route and the `system_read_server_logs` chat tool can show recent errors. Installed
  // right after the rejection guard so boot-time failures are captured too.
  installServerLogCapture({ release: processBuildRelease({}), environment: telemetryEnvironment({ env: process.env }) });

  // Mints `TOVU_AGENT_DAEMON_TOKEN` (unless the operator already set one) into this process's env
  // so `startAssistantDaemon()` — called later, from inside `app.listen()`'s callback — hands it to
  // the daemon child through the inherited env. See this file's header for the ordering contract.
  ensureAgentDaemonToken({}, {});
  // The tool RPC token (ADR-070) stays in module memory, NOT this env: see `daemon-access.ts`.
  ensureToolExecToken({}, {});

  // CIC U-002/ADR-005 (ESCALATE_SECURITY) — see this file's header. Must precede `createApp()`
  // below (and therefore every route it mounts, including the `plugins` module's
  // `PLUGIN_SET_ENABLED`) and every boot step that could lead there; placed here, with no `await`
  // ahead of it, for the same reason `index.ts`'s own call site gives.
  (optional.registerPluginSdkResolver ?? registerPluginSdkResolver)();

  // The shared gate contains unsafe defaults for production CLI boots and is inert locally.
  // See runtime/boot/boot-readiness-gate.ts for the policy.
  await runProductionReadinessGateOrExit();

  warnIfLegacyEnvVarsIgnored();

  const target = resolveInstallDirTarget(input.dir);
  // Must precede EVERY `siteDir()`-derived read below (and the daemon spawn much further down) —
  // see {@link pinServedSiteDirIntoEnv} for the divergence this closes.
  pinServedSiteDirIntoEnv(target);
  // Persist captured log lines to `<site>/ops/logs/server.log` (L2), including those buffered since
  // `installServerLogCapture()` above, so errors survive a restart; reads merge the daemon's log too.
  const logFiles = serverLogFilePaths({ siteDir: target });
  attachServerLogFile({ filePath: logFiles.server }, { alsoRead: [logFiles.daemon] });
  pinPlainHttpIntoEnv();
  const runningLease = claimSiteRunning({ dir: target, app: process.env.TOVU_RUNNING_APP === "Desktop" ? "Desktop" : "Web" });
  let bootResult: BootSiteDirResult;
  try { bootResult = await bootSiteDir({ dir: target }, { workspaceId: input.workspaceId }); }
  catch (error) { runningLease.release(); throw error; }
  // From here on this command owns what `bootSiteDir` opened: any failure before the listener is
  // bound (bad port/host, a composition or lifecycle failure, the daemon port, `EADDRINUSE`) stops
  // the workers already started and closes the store before the error reaches `cli/main.ts`, so a
  // refused boot never leaves a PGlite owner lock/socket or a Postgres pool behind.
  const owned: ServeOwnership = { bootResult, composedStore: undefined, workers: [], bootWork: [], runningLease };
  try {
    await serveBootedSite(input, target, owned, optional);
  } catch (err) {
    await releaseServeOwnership(owned);
    runningLease.release();
    throw err;
  }
}

/** What a `tovu serve` run holds open once `bootSiteDir` has succeeded. */
interface ServeOwnership {
  runningLease: ReturnType<typeof claimSiteRunning>;
  readonly bootResult: BootSiteDirResult;
  /** The composition's store (`onStoreOpened`); closing it stops the guest-chat sweep first. */
  composedStore: SiteStore | undefined;
  /** Background loops started by `createServingApp`. */
  readonly workers: Array<{ stop(): Promise<void> }>;
  /** Boot passes the composition started and never awaited, which read the store: the legacy
   *  publish-credential tail and `createApp`'s BYOK pass. See `await-boot-work.ts`. */
  readonly bootWork: Array<Promise<unknown>>;
}

/** Stops every started worker, then closes the store (the composition's, or `bootSiteDir`'s). */
async function releaseServeOwnership(owned: ServeOwnership): Promise<void> {
  await Promise.allSettled(owned.workers.map((worker) => worker.stop()));
  await closeOwnedStore(owned);
}

/** Closes the store once the boot work still reading it has settled (bounded, see
 *  `awaitBootWorkWithinBound`), so a site stopped seconds after boot does not close under it. */
async function closeOwnedStore(owned: ServeOwnership): Promise<void> {
  await awaitBootWorkWithinBound({ work: owned.bootWork });
  await closeSiteDirBoot(owned.bootResult, owned.composedStore);
}

/**
 * {@link runServeCommand} after `bootSiteDir`: compose, run the boot lifecycle, bind the listener and
 * install the BR-07 shutdown. Records what it starts in `owned`, so a rejection can be cleaned up.
 */
async function serveBootedSite(input: RunServeCommandInput, target: string, owned: ServeOwnership, optional: RunServeCommandOptional): Promise<void> {
  const { bootResult } = owned;
  const port = resolveServePort(input, bootResult.config);
  // LAN-bind plan (2026-09-23): loopback-only unless TOVU_HOST opts in. Resolved before the boot
  // lifecycle below, same reasoning as `port` above — a bad value fails fast as VALIDATION rather
  // than after `bootSiteDir`'s migrations/side effects have already run.
  const host = resolveBindHost(input.host ?? process.env.TOVU_HOST, DEFAULT_LOCAL_BIND_HOST);
  pinSiteListenerOrigin({ scheme: "http", host, port });

  // site-key plan §A3a: safe to call on every boot (a valid per-site file is read, not rewritten —
  // see `ensureSiteKeyForBoot`'s own header). Result is discarded — no caller here needs it, same
  // "safe to call on every boot" framing `ensureSiteKey` itself documents. Must precede
  // `createSiteRouteDeps` below, which is what actually resolves the site key this may have just
  // adopted or minted. Must FOLLOW `bootSiteDir` and the port/host checks above: it can write
  // `.site-meta.json`, and a boot those refuse must leave the directory untouched — a refused
  // marker-less dir that gained a `.site-meta.json` here is one `tovu adopt` then refuses as
  // partially adopted.
  await ensureSiteKeyForBoot({ siteDir: target, findSiteKeyDependentData });

  // Local boots also need the missing-site-key notice; the readiness gate is production-only.
  // See runtime/boot/site-key-boot-notice.ts. After the ensure above, with this site, so a fresh
  // site's just-minted per-site key counts (2026-10-22: it warned "no key file at .").
  warnIfNoSiteKeyAtBoot({ siteDir: target });

  reportSitesSyncWarning({});
  const paths = resolveSiteDatabasePaths({ dir: target });
  const dbPath = paths.contentDbPath;
  const deps = await createSiteRouteDeps(dbPath, {
    db: bootResult.db,
    chatDbPath: paths.chatDbPath,
    store: bootResult.store,
    workspaceId: bootResult.workspaceId,
    onStoreOpened: (store) => (owned.composedStore = store),
    uploadsDir: path.join(target, "uploads"),
    // Same install-dir-relative reasoning as `uploadsDir` right above (CR-R01): the default themes
    // root is `process.cwd()`-relative, so without this a `<dir>` run would seed and serve a
    // `sites/tovu-dev/themes` beside the operator's shell instead of the site it was given.
    themesDir: path.join(target, "themes"),
    // 2026-09-06 composition-root fix: without this, `RouteDeps.siteBinding` fell back to
    // `describeSiteBinding()`, which re-derives `<process.cwd()>/sites/tovu-dev` — unrelated to
    // `target` whenever this command is invoked from outside `target`'s own parent directory. The
    // admin Sites screen then reported the WRONG site as "currently serving", and (had a caller
    // exercised Create/Activate against it) `sites.ts`/`sites_duplicate_site` would have written
    // under that unrelated `<cwd>/sites` tree instead of anywhere near `target`.
    // `switcherCompatible: false` because `target` is an arbitrary install-dir argument with no
    // `{cwd, env}`-relative `sites/`-sibling relationship at all — see `SiteBinding.switcherCompatible`'s
    // own doc. `dirOverridden: true` for the same reason `TOVU_SITE_DIR` reports it: this run's
    // served site was pinned by an explicit argument, so a persisted Activate choice would be inert
    // on a subsequent `tovu serve <dir>` invocation exactly as it already is under `TOVU_SITE_DIR`.
    siteBinding: {
      dir: target,
      name: path.basename(target),
      dirOverridden: true,
      switcherCompatible: false,
    },
  });
  if (deps.legacyPublishCredentialsReady) owned.bootWork.push(deps.legacyPublishCredentialsReady);
  // Unhandled rejections/exceptions reach the error tracker too, now that its port exists.
  installProcessErrorReporting({ tracker: deps.tracker, processRole: "server" }, { flush: deps.flushTelemetry });

  // 2026-09-05 dispatch (boot-path parity): this command never ran `runBootLifecycle` at all —
  // only `src/index.ts`'s `main()` did (ADR-046 Phase 3/SPEC-031). Two concrete gaps that opened:
  // (1) `database-migration-reconciliation` (`reconcile-interrupted-migration.ts`) — the scan that
  // detects a crash-interrupted migration and flips `siteStatusRepo` to `BLOCKED_PENDING_RECOVERY`
  // — never ran for a `tovu serve`-booted site, so `site-serving-gate.ts`'s per-request enforcement
  // (which reads that SAME `siteStatusRepo`, not this function's return value) could never trigger
  // no matter how badly interrupted a real migration was; (2) `settings`/`seo` are CRITICAL exactly
  // because their promise chains have no `.catch()` anywhere (an unhandled-rejection risk), so a
  // failure there must abort boot cleanly rather than serve a half-seeded site. Composed and run
  // BEFORE `ensureAgentDaemonPortResolved()`/`createApp()`/`app.listen()` below — mirroring
  // `index.ts`'s exact ordering — so a critical failure refuses to serve at all, not merely to spawn
  // the daemon. `defaultContentDbPath` is this invocation's OWN resolved `dbPath` (install-dir-
  // relative), not `deps.ts`'s `siteDir()`-based default — passing that default here would point the
  // `store-plugin` boot module at the wrong site entirely whenever `<dir>` differs from the default
  // site root.
  const lifecycleResult = await runBootLifecycle(buildBootModules(deps, { useMemory: false, defaultContentDbPath: () => dbPath }));
  setReadinessSnapshot(lifecycleResult);
  if (!lifecycleResult.ok) {
    logCriticalBootFailures(lifecycleResult);
    // The store is closed by `runServeCommand`'s catch. Never `process.exit()` here (unlike `index.ts`): this file's own header records the
    // established contract — `cli` layer errors propagate uncaught to `cli/main.ts`, which maps
    // them to an exit code via `errors.ts`. An unrecognized plain `Error` falls through to
    // `mapErrorToCliOutcome`'s `INTERNAL` (exit 1) bucket, matching `index.ts`'s own `process.exit(1)`
    // outcome for the identical failure without inventing a new SPEC-003 error code for it.
    throw new Error("Refusing to boot — a critical module failed. See failures above.");
  }

  // Must resolve — and, when neither `JINI_AGENT_DAEMON_URL` nor `JINI_AGENT_DAEMON_PORT` is set,
  // allocate — this instance's daemon origin BEFORE `createApp()` wires the assistant proxy's
  // routes, so no inbound request can ever reach `getAgentDaemonUrl()` before it has something to
  // return. See this file's own header and `agent-daemon-port.ts`'s for the full contract.
  await assertSafeOwnerCredentialBeforeListen({ deps, host: host });
  await ensureAgentDaemonPortResolved();
  // `createServingApp`, not bare `createApp`: it also starts the background outbox drainer (after
  // `createApp` has attached every subscriber), Trash auto-purge sweeper, theme watcher, the
  // automatic form pull, the post go-live sweep, the webhook delivery loop, the due-bindings DNS
  // sweep and the site-search maintenance loop. All stop in `shutdown` below.
  const { app, outboxDrainer, trashSweeper, themeWatcher, formPullTrigger, postGoLiveSweep, webhookDeliveryWorker, domainBindingSweeper, siteSearchMaintenance, bootWork } = (optional.createServingApp ?? createServingApp)(deps);
  owned.workers.push(outboxDrainer, { stop: () => trashSweeper.stop({}) }, themeWatcher, formPullTrigger, postGoLiveSweep, webhookDeliveryWorker, domainBindingSweeper, siteSearchMaintenance);
  owned.bootWork.push(...bootWork);

  await new Promise<void>((resolve, reject) => {
    // Express's own `.listen()` overloads type `hostname` as a required `string`, not
    // `string | undefined` (`@types/express-serve-static-core`) — so `host === undefined` (the
    // "no TOVU_HOST override, use Node's own all-interfaces default" case) is routed to the
    // callback-only overload explicitly, rather than widening the type with a cast.
    const server = host !== undefined ? app.listen(port, host) : app.listen(port);
    server.once("close", () => { void themeWatcher.stop(); });

    // Forwards Vite's HMR WebSocket when `TOVU_ADMIN_DEV_PROXY_URL` is set. `registerAdminStatic`
    // (reached via `createApp` above) already proxies ordinary `/admin/*` REQUESTS on this path, but
    // an `upgrade` is a raw `http.Server` event Express's request pipeline never sees — so without
    // this, a dev-proxied `tovu serve` served current admin source that could never hot-reload.
    // Measured before the fix, same handshake against the same Vite: `index.ts`'s server answered
    // `101 Switching Protocols`; this one answered nothing at all.
    //
    // The FIFTH instance of this file's own recurring defect class — see the header above for the
    // other four (agent daemon, daemon token, plugin SDK resolver, readiness gate + boot lifecycle),
    // each of them "`src/index.ts` was the only boot path that did it". `apps/desktop` spawns this
    // command, so every desktop site window was on the wrong side of all five.
    //
    // Self-gating, so production and packaged builds are unaffected: the function returns
    // immediately when `TOVU_ADMIN_DEV_PROXY_URL` is unset or the runtime is a SEA single-binary.
    // Registered on `server`, not `app`, for the same reason `index.ts` does it that way.
    registerAdminDevProxyUpgrade(server);

    server.once("error", (err: NodeJS.ErrnoException) => {
      if (err.code === "EADDRINUSE") {
        reject(new PortInUseError(`Port ${port} is already in use.`, port));
      } else {
        reject(err);
      }
    });

    server.once("listening", () => {
      try { owned.runningLease.ready({ port }); }
      catch (error) { server.close(); reject(error); return; }
      const runtime = runtimeSchemaVersion();
      // BEFORE the documented startup line below, on purpose. A launcher treats that line as the
      // ready signal and stops waiting the moment it sees it, so a token printed after it would
      // race the parent's own resolve. Printed first, it is already in the parent's buffer by the
      // time the line it is waiting for arrives — no extra handshake, no timing window.
      //
      // A SEPARATE line, deliberately not a fifth field on the startup line: that line is a
      // documented contract (api.spec.md §5) other readers parse, and widening it would put a
      // secret in front of every consumer of it. Emitted only when explicitly asked for, and only
      // once the listener is bound, so a token can never outlive a boot that failed.
      if (input.emitBootToken === true) {
        // eslint-disable-next-line no-console
        console.log(`tovu serve: bootToken=${mintBootSessionToken()}`);
      }
      // api.spec.md §5: "one startup line including: dir, resolved port, schemaVersion, workspace id".
      // eslint-disable-next-line no-console
      console.log(`tovu serve: dir=${target} port=${port} schemaVersion=${runtime.index} workspaceId=${bootResult.workspaceId}`);
      // AFTER the documented startup line, same ordering reason as the boot token above — a parser
      // treating that line as the ready signal must see it exactly as documented, unwidened by a
      // second line ahead of it. LAN-bind plan (2026-09-23): this is the one place `--host`/
      // `TOVU_HOST` widening a `tovu serve` instance beyond loopback becomes visible to whoever
      // started it.
      if (!isLoopbackHost(host)) {
        process.stderr.write(
          `tovu serve: warning: listening on ${host ?? "all interfaces"}; this site is reachable from other machines on your network (--host/TOVU_HOST)\n`
        );
      }
      resolve();

      // Same readiness-await-then-spawn ordering as `index.ts`'s own `app.listen()` callback, and
      // for the identical reason (see `server/runtime/boot/site-boot-readiness.ts`, the list both
      // boot paths now share): spawning before these settle raced this process's own first-boot identity/settings seeding and
      // shipped a real duplicate-`core.execution.mode`-row defect. `registerProcessSignalHandlers:
      // false` because this command already owns SIGINT/SIGTERM below (BR-07) — see
      // `startAssistantDaemon`'s own option doc for why a second listener here would race it.
      awaitSiteBootReadiness({ deps })
        .then(async () => {
          if (!(await agentDaemonWanted(deps))) return;
          startAssistantDaemon(
            { workspaceId: deps.workspaceId, siteDir: target, pgSocketPath: bootResult.store?.pgliteSocketPath },
            { registerProcessSignalHandlers: false }
          );
        })
        .catch((error: unknown) => {
          console.error("[cli/serve] a boot-readiness promise rejected — not starting the agent daemon", error);
        });

      // BR-07: on SIGINT/SIGTERM, stop accepting new connections, let the current request finish,
      // then close the db handle and exit 0.
      // First, so no new outbox drain or trash sweep starts while the grace window below runs
      // toward the db close. A sweep caught mid-batch leaves its rows leased, and the next boot
      // re-claims them once the lease expires.
      // Awaits the store close (PGlite flushes, removes its socket and releases its owner lock),
      // bounded like the default boot's (`closeWithinBound`, 4 s) so a hung close still exits.
      // The close itself first waits (2 s of that) for boot work still reading the store.
      // Idle keep-alive sockets don't block in-flight requests, but a client-pooled connection
      // that never sends another request WOULD block `server.close()`'s callback indefinitely
      // otherwise — better-sqlite3 is synchronous, so any genuinely in-flight request completes
      // within milliseconds, not seconds; a short grace window is more than enough before the
      // shared helper force-closes anything still lingering (BR-07 only promises the current
      // request finishes, not that an idle keep-alive socket outlives shutdown).
      closeStoreOnShutdown({
        store: { storage: bootResult.storage, close: () => closeSiteDirBoot(bootResult, owned.composedStore) },
        onShutdown: shutdownAssistantDaemon,
      }, {
        bootWork: () => owned.bootWork,
        stopServing: () => stopServingWithinGrace({ server, workers: [
          { stop: () => outboxDrainer.stop() }, { stop: () => trashSweeper.stop({}) }, themeWatcher, formPullTrigger, postGoLiveSweep, webhookDeliveryWorker, domainBindingSweeper, siteSearchMaintenance,
        ] }),
        // Opt-in (the desktop on Windows): an ignored or terminal stdin must never stop the site.
        stopOnEnd: process.env.TOVU_STOP_ON_STDIN_EOF === "1" ? process.stdin : undefined,
      });
    });
  });
}

import path from "node:path";

import { migrateThemeToV2, type MigrateThemeResult } from "#src/features/theme/index";

/**
 * @file `tovu theme migrate <dir> [--dry-run] [--json]` — `migrate-theme.ts`'s CLI surface. Mirrors
 * `theme validate`'s shape (`cli/commands/theme/validate.ts`): formats stdout only, signals a
 * migration that did not succeed via `process.exitCode = 1` rather than throwing (a theme that isn't
 * ready to migrate is an expected, ran-to-completion outcome, not a CLI crash).
 */

export interface RunThemeMigrateCommandInput {
  dir: string;
  dryRun?: boolean;
  json?: boolean;
}

/** `formatSummary`'s `"failed"` case, split out to keep the switch below a flat dispatch (each
 * remaining case is a single-line template) — this is the one case with its own internal branching
 * (two error lists plus an optional trailing line). */
function formatFailedSummary(id: string, result: MigrateThemeResult): string {
  const lines = [`theme '${id}': migration FAILED — ${result.reason ?? "see validation/load errors below"}`];
  for (const error of result.validation?.errors ?? []) lines.push(`  [validator:${error.ruleId}] ${error.message}`);
  for (const error of result.loadErrors ?? []) lines.push(`  [loadTheme] ${error}`);
  if (result.outputDir) lines.push(`staged output left for inspection at ${result.outputDir}`);
  return `${lines.join("\n")}\n`;
}

/** Injectable effects of {@link runThemeMigrateCommand}. */
export interface RunThemeMigrateCommandPorts {
  migrate?: typeof migrateThemeToV2;
  output?: (message: string) => void;
  setExitCode?: (code: number) => void;
}

function writeStdout(message: string): void {
  process.stdout.write(message);
}

function setProcessExitCode(code: number): void {
  process.exitCode = code;
}

function formatSummary(id: string, result: MigrateThemeResult): string {
  switch (result.status) {
    case "already-migrated":
      return `theme '${id}': already schema v2, nothing to do\n`;
    case "staged-dry-run":
      return `theme '${id}': dry run OK — staged v2 output at ${result.outputDir}, real theme directory untouched\n`;
    case "migrated":
      return `theme '${id}': migrated to schema v2 in place — v1 backup kept at ${result.backupDir}\n`;
    case "failed":
      return formatFailedSummary(id, result);
  }
}

/**
 * Run `tovu theme migrate <dir> [--dry-run] [--json]`.
 *
 * @complexity O(1) beyond `migrateThemeToV2`'s own bounded cost.
 */
export async function runThemeMigrateCommand(
  input: RunThemeMigrateCommandInput,
  optional: RunThemeMigrateCommandPorts = {}
): Promise<void> {
  // Default ports are wired here, at the command edge; tests inject their own.
  const { migrate = migrateThemeToV2, output = writeStdout, setExitCode = setProcessExitCode } = optional;
  const dir = path.resolve(input.dir);
  const id = path.basename(dir);
  const result = migrate({ themeDir: dir, id }, { dryRun: input.dryRun });

  output(input.json ? `${JSON.stringify(result, null, 2)}\n` : formatSummary(id, result));

  if (result.status === "failed") {
    setExitCode(1);
  }
}

import { Command } from "commander";
import { runPluginInstallCommand } from "./commands/plugin/install.js";
import { runPluginIntegrityCommand } from "./commands/plugin/integrity.js";

import { runAdoptCommand } from "./commands/adopt.js";
import { runTokenSignInPluginsCommand } from "./commands/agent-plugin-tokens.js";
import { deployConfigTargetOptionHelp, runDeployConfigCommand } from "./commands/deploy-config.js";
import { runExportCommand } from "./commands/export.js";
import { runInitCommand } from "./commands/init.js";
import { runImportSiteCommand } from "./commands/import-site.js";
import { OWNER_STORE_ACTIONS, runOwnerStoreCommand } from "./commands/owner-store.js";
import { runStorageMoveCommand } from "./commands/storage-move.js";
import { runSiteRenameCommand } from "./commands/site-rename.js";
import { runIntrospectCommand } from "./commands/introspect.js";
import { runServeCommand } from "./commands/serve.js";
import { runThemeGenerateIndexCommand } from "./commands/theme/generate-index.js";
import { runThemeMigrateCommand } from "./commands/theme/migrate.js";
import { runThemeNormalizeBuildCommand } from "./commands/theme/normalize-build.js";
import { runThemeSyncOriginalsCommand } from "./commands/theme/sync-originals.js";
import { runThemeValidateCommand } from "./commands/theme/validate.js";
import { introspectProgram } from "./introspect.js";

/**
 * @file SPEC-003 — the single `commander` `Command` program: the one source of truth for the
 * `tovu` CLI's subcommands and options (ADR-PIPE-003 v1.1.0 Enforcement — no command may
 * hand-roll its own argv tokenization alongside this).
 *
 * Purpose:
 * Declares `init`/`serve` and their positional/option shape. Commander itself performs argv
 * tokenization and basic coercion (e.g. required-argument enforcement); all VALUE-level
 * validation (empty `--name`, out-of-range `--port`) is `site-dir`'s / the command modules' job,
 * not commander's, so validation error text and classes stay stable regardless of the parsing
 * library underneath.
 *
 * `configureOutput({ writeErr: () => {} })` suppresses commander's OWN default error/usage
 * writes to stderr — `cli/main.ts` is the sole writer of the `tovu: <CODE>: <message>` stderr
 * contract (errors.spec.md §1: "exactly one machine-parseable stderr line"); commander's help
 * output (`--help`, `helpInformation()`) still goes through `writeOut` (stdout), unaffected.
 *
 * Architectural role:
 * `cli` layer. Never imports Drizzle types directly (dependency-cruiser rule
 * `cli-no-direct-drizzle-imports`).
 */
export function createProgram(): Command {
  const program = new Command("tovu");
  program.description("Tovu — the website product you own. Manage local site install directories.");
  program.exitOverride();
  program.configureOutput({ writeErr: () => {} });
  registerOwnerStoreCommands({ program });
  program.command("site").description("manage local site folders")
    .command("rename").description("rename a stopped site's folder in the sites home; preserve its display name")
    .argument("<old-name>", "current folder name")
    .argument("<new-name>", "new folder name")
    .action(async (oldName: string, newName: string) => {
      await runSiteRenameCommand({ oldName, newName });
    });
  program.command("import").description("install a Tovu share into a NEW site via a running admin server; reads {authorization,url|uploadId,displayName?,requestId?} JSON from stdin; owner password setup stays private in the browser")
    .requiredOption("--server <origin>", "running admin server origin")
    .requiredOption("--workspace <id>", "workspace authorizing local site creation")
    .action(async (options: { server: string; workspace: string }) => {
      console.log(JSON.stringify(await runImportSiteCommand({ server: options.server, workspaceId: options.workspace })));
    });

  program.command("sites").description("manage shared local sites")
    .command("move-home").argument("<dir>", "stopped site inside the former default sites/ folder")
    .option("--projects-path <file>", "also update this desktop profile's catalog")
    .action(async (dir: string, options: { projectsPath?: string }) => {
      const { moveLegacySite } = await import("../platform/site-dir/move-sites-home.js");
      const { createSitesWorkspace } = await import("../platform/site-dir/sites-home.js");
      const workspace = createSitesWorkspace({});
      const to = await moveLegacySite({ dir }, { workspace,
        projectsPaths: [...workspace.projectsPaths, ...(options.projectsPath ? [options.projectsPath] : [])],
      });
      console.log(JSON.stringify({ to }));
    });

  const pluginProgram = program.command("plugin").description("install and inspect local site plugins");
  pluginProgram.command("install").argument("<dir>", "plugin package folder")
    .option("--site <dir>", "site directory (default: TOVU_SITE_DIR / active site)")
    .option("--replace", "replace the same version, only while disabled everywhere")
    .option("--yes", "acknowledge the full-machine-access consent warning")
    .action(async (dir: string, options: { site?: string; replace?: boolean; yes?: boolean }) => {
      await runPluginInstallCommand({ dir, ...options });
    });
  pluginProgram.command("integrity").argument("<dir>", "plugin package folder")
    .option("--write", "write the complete integrity map to jini.plugin.json")
    .action(async (dir: string, options: { write?: boolean }) => { await runPluginIntegrityCommand({ dir, ...options }); });

  program
    .command("init")
    .description("instantiate the starter template into a new install dir")
    .argument("<dir>", "target install directory")
    .option("--name <name>", "site display name (defaults to the directory's basename)")
    .option("--with-sample-content", "include the starter demo posts and pages (for demos and test fixtures)")
    .option("--admin-password <password>", "new site's admin password (default: tovu-dev; ignores TOVU_ADMIN_PASSWORD)")
    .option("--create-input-stdin", "read {adminPassword, agentPluginTokens?} JSON privately from stdin")
    .option("--storage <kind>", "where the site keeps its data: sqlite (default), pglite, or postgres")
    .option("--storage-env <name>", "postgres: read the connection string from this environment variable (default: asked for once and sealed in the site folder)")
    .option("--agent-plugin-tokens-stdin", "read {\"<pluginId>\": \"<access token>\"} JSON from stdin; each token is checked, then connects that plugin when the site first starts")
    .action(async (dir: string, options: { name?: string; withSampleContent?: boolean; adminPassword?: string; createInputStdin?: boolean; storage?: string; storageEnv?: string; agentPluginTokensStdin?: boolean }) => {
      await runInitCommand({
        dir,
        name: options.name,
        withSampleContent: options.withSampleContent === true,
        adminPassword: options.adminPassword,
        createInputStdin: options.createInputStdin === true,
        storage: options.storage,
        storageEnv: options.storageEnv,
        agentPluginTokensStdin: options.agentPluginTokensStdin === true,
      });
    });

  program
    .command("agent-plugins")
    .description("Agent Plugin commands")
    .command("token-sign-in")
    .description("list the bundled Agent Plugins a new site can connect with a pasted access token")
    .option("--json", "print JSON (the only format)")
    .action(async () => {
      await runTokenSignInPluginsCommand();
    });

  program
    .command("storage")
    .description("change where a site keeps its data")
    .command("move")
    .description("move a stopped PGlite site onto an empty Postgres database (the PGlite data dir is kept)")
    .argument("<dir>", "site directory")
    .requiredOption("--to <kind>", "the new storage: postgres")
    .option("--storage-env <name>", "read the connection string from this environment variable, and keep reading it there (default: asked for once and sealed in the site folder)")
    .action(async (dir: string, options: { to?: string; storageEnv?: string }) => {
      await runStorageMoveCommand({ dir, to: options.to, storageEnv: options.storageEnv });
    });

  // Registered next to `init` deliberately: the two are the only ways a directory becomes servable,
  // and they are exact complements — `init` creates a site in an EMPTY folder, `adopt` takes an
  // EXISTING one that predates the marker convention. Keeping them adjacent in `--help` is what
  // makes the second discoverable to an operator who only knows the first.
  program
    .command("adopt")
    .description("give an existing site directory the marker files 'serve' requires — derived from its own database, which is never modified")
    .argument("<dir>", "existing site directory to adopt")
    .option("--name <name>", "site display name (defaults to the directory's basename)")
    .option("--dry-run", "print exactly what would be written, and write nothing")
    .action(async (dir: string, options: { name?: string; dryRun?: boolean }) => {
      await runAdoptCommand({ dir, name: options.name, dryRun: options.dryRun === true });
    });

  program
    .command("serve")
    .description(
      "validate, migrate, and boot an install dir — serves site + admin; listens on 127.0.0.1 unless TOVU_HOST is set (e.g. TOVU_HOST=0.0.0.0 for a server or container)"
    )
    .argument("<dir>", "install directory to serve")
    .option("--port <port>", "port to listen on (default: config.json.port, then PORT env, then 3000)")
    .option("--host <ip>", "IP address to listen on (default: TOVU_HOST env, then 127.0.0.1 — this computer only; use 0.0.0.0 for a server or container)")
    .option("--workspace <id>", "workspace id to serve (default: the oldest workspace, if the install has more than one)")
    // Opt-in and off by default, so an operator running `tovu serve` by hand never sees a secret in
    // their terminal. See `boot-session-token.ts` for what the token is and what it cannot do.
    .option("--emit-boot-token", "print a single-use loopback token on stdout that a launching process can exchange once for an admin session")
    .action(async (dir: string, options: { port?: string; host?: string; workspace?: string; emitBootToken?: boolean }) => {
      await runServeCommand({ dir, port: options.port, host: options.host, workspaceId: options.workspace, emitBootToken: options.emitBootToken === true });
    });

  program
    .command("export")
    .description("render the install dir's public site to a folder of static files (no admin, no browser)")
    .argument("<dir>", "install directory to export")
    .option("--out <dir>", "output directory (default: $TOVU_EXPORT_DIR, then <cwd>/infra/export)")
    .option("--workspace <id>", "workspace id to export (default: the oldest workspace, if the install has more than one)")
    .option("--clean", "remove the output directory's existing contents first, if any")
    .option("--base-path <path>", 'rewrite root-relative links/assets for a subpath deploy (e.g. "/my-repo" for a host that serves a project site under a subpath) — omit for an apex-domain deploy')
    .action(async (dir: string, options: { out?: string; workspace?: string; clean?: boolean; basePath?: string }) => {
      await runExportCommand({ dir, out: options.out, workspaceId: options.workspace, clean: options.clean, basePath: options.basePath });
    });

  // Namespaced command group (2026-08-18, Milestone 2 of the theme v2 build) — a sibling `theme
  // migrate`/`theme package` are expected from later milestones, hence a real subcommand group
  // rather than a flat `theme-validate` command. `theme` itself has no `.action()`: invoked alone it
  // prints commander's own default usage for a group with subcommands, which is the right behavior
  // for a namespace that is not itself invocable.
  const themeProgram = program.command("theme").description("theme package authoring/validation commands");
  themeProgram
    .command("validate")
    .description("validate a theme package directory against the theme.json schema, package shape, and markup rules")
    .argument("<dir>", "theme package directory to validate")
    .option("--profile <profile>", "validation strictness: author (default), publish, or install", "author")
    .option("--json", "print the full machine-readable result instead of a human-readable summary")
    .action(async (dir: string, options: { profile?: string; json?: boolean }) => {
      await runThemeValidateCommand({ dir, profile: options.profile, json: options.json });
    });
  themeProgram
    .command("migrate")
    .description("migrate a v1 theme package directory to schema v2 in place (idempotent; keeps a v1 backup alongside on success)")
    .argument("<dir>", "theme package directory to migrate")
    .option("--dry-run", "stage the v2 output and verify it, but never touch the real theme directory")
    .option("--json", "print the full machine-readable result instead of a human-readable summary")
    .action(async (dir: string, options: { dryRun?: boolean; json?: boolean }) => {
      await runThemeMigrateCommand({ dir, dryRun: options.dryRun, json: options.json });
    });
  themeProgram
    .command("generate-index")
    .description("(re)generate a static-tier theme's portability-backup root index.html — real nav/footer partials spliced in, dynamic menu/post/content markers placeholdered")
    .argument("<dir>", "theme package directory to generate into")
    .option("--json", "print the full machine-readable result instead of a human-readable summary")
    .action(async (dir: string, options: { json?: boolean }) => {
      await runThemeGenerateIndexCommand({ dir, json: options.json });
    });
  themeProgram
    .command("sync-originals")
    .description(
      "(re)generate every shipped theme's '__original-themes__' entry from its live folder, filtered the same way the Explore file list is (no generated preview output) — removes the need to hand-maintain the 'reset to original' catalog"
    )
    .argument("<themesRoot>", "themes root directory (e.g. content/themes) — NOT a single theme's own folder")
    .option("--json", "print the full machine-readable result instead of a human-readable summary")
    .action(async (themesRoot: string, options: { json?: boolean }) => {
      await runThemeSyncOriginalsCommand({ themesRoot, json: options.json });
    });
  themeProgram
    .command("normalize-build")
    .description("normalize a code-tier framework's raw build output (e.g. `ng build`) in place into Tovu's static-asset-contract shape, ready for artifactHashes + publish")
    .argument("<dir>", "the build's flat output directory (e.g. Angular's dist/<project>/browser/) — mutated in place")
    .option("--primary-stylesheet <file>", "the build's global CSS entry point's output filename (e.g. \"styles.css\"), matching angular.json's styles entry point")
    .option("--pages <files>", "comma-separated top-level HTML page files to rewrite", "index.html")
    .option("--json", "print the full machine-readable result instead of a human-readable summary")
    .action(async (dir: string, options: { primaryStylesheet?: string; pages?: string; json?: boolean }) => {
      await runThemeNormalizeBuildCommand({ dir, primaryStylesheet: options.primaryStylesheet, pages: options.pages, json: options.json });
    });

  // Namespaced command group (mirrors `theme`'s own group above) — `deploy config` today, with room
  // for sibling `deploy` subcommands later without a flat-command rename.
  const deployProgram = program.command("deploy").description("deployment config generation commands");
  deployProgram
    .command("config")
    .description(
      "generate one platform's deploy config file from Tovu's single deployment descriptor (Dockerfile/package.json as source of truth) — prints to stdout, or writes to --out"
    )
    .option("--target <target>", deployConfigTargetOptionHelp())
    .option("--region <region>", "platform region (required — no default region is assumed)")
    .option("--site <name>", "which local site's id to stamp as TOVU_SITE_ID (default: the site this process serves)")
    .option("--out <file>", "write the generated config to this file instead of stdout")
    .action(async (options: { target?: string; region?: string; site?: string; out?: string }) => {
      await runDeployConfigCommand({ target: options.target, region: options.region, site: options.site, out: options.out });
    });

  program
    .command("introspect")
    .description("output a machine-readable JSON description of this CLI's own commands and options (for programmatic/agent callers, e.g. Tovu-Runner)")
    .option("--format <format>", 'output format: "commander" (raw command/option shape) or "mcp" (MCP tool definitions)', "commander")
    .action(async (options: { format?: string }) => {
      await runIntrospectCommand({ manifest: introspectProgram(program), format: options.format });
    });

  return program;
}

/** The private desktop protocol has no inline secret flags; Commander owns argv parsing. */
function registerOwnerStoreCommands({ program }: { program: Command }, _options = {}): void {
  const ownerStore = program.command("owner-store").description("manage desktop shared keys; private JSON request on stdin");
  for (const action of OWNER_STORE_ACTIONS) {
    const command = ownerStore.command(action)
      .description(`${action} shared keys; reads {userDataDir, ...request} JSON on stdin`)
      .option("--json", "print one JSON reply (the only format)");
    command.action(async () => {
      await runOwnerStoreCommand({ action });
    });
  }
}

import { assistantCliPermissions, type AssistantCliPermissions } from "../headless/assistant-subagents-policy.js";
import { CORE_HOST_SIGNAL_FALLBACK, evaluateHostSignals, type HostSignalOptions } from "./host-signals.js";
/** Product policy shared by the site daemon and Electron host. No I/O or framework imports. */
export const TOOLS_FIRST_RULE = 'Use Tovu tools first. Before any Bash or direct file read/edit/write of site files (themes, content, config), call search_tools describing the job; if no candidate fits, retry with different phrasing or a higher limit. Only if those searches find no suitable Tovu tool may you use native fallbacks. Only after those searches, report the fallback in one line: `Tool gap: <what you needed> — no Tovu tool for it.` Include the queries you searched in <what you needed>. Reading theme or site files counts too: use theme_read_file (with find) or fs_read_file, never cat/grep/sed.';

/** Hosted signals override every owner opt-in, including legacy permission-mode overrides.
 * The host injects validated platform facts; absent facts retain the core baseline without I/O.
 * @param required Environment snapshot containing the product's own host policy switches.
 * @param optional Matched shipped facts, resolved at the host boundary before policy evaluation.
 * @returns Whether native assistant tools must remain restricted. @complexity O(1).
 * @example isHostedAssistantRuntime({ env }, { hostSignals });
 */
export function isHostedAssistantRuntime(required: {
  env: Readonly<Record<string, string | undefined>>;
}, optional: HostSignalOptions = {}): boolean {
  const env = required.env;
  const hostSignals = optional.hostSignals ?? evaluateHostSignals({ env, declaration: CORE_HOST_SIGNAL_FALLBACK });
  return env.TOVU_RUNTIME_MODE === 'production' || env.TOVU_HOSTED === '1' || env.TOVU_HOSTED === 'true' ||
    hostSignals.nativeToolsRestricted === true ||
    /^https?:\/\/(?:[^/]+\.)?tovu\.dev(?::\d+)?(?:\/|$)/i.test(env.TOVU_PUBLIC_URL ?? '');
}

/** Names the local env switch that turns Full CLI access off on this machine, or undefined.
 * Hosted runtimes are reported separately. The settings route shows this name so a locked switch
 * explains itself instead of snapping back. Pure, O(1).
 * TOVU_AGENT_NATIVE_FALLBACKS remains an alias; either explicit OFF switch denies access.
 */
export function fullCliEnvLock(required: {
  env: Readonly<Record<string, string | undefined>>;
}, _optional: Record<string, never> = {}): string | undefined {
  const env = required.env;
  if (env.TOVU_AGENT_PERMISSION_MODE === 'restricted') return 'TOVU_AGENT_PERMISSION_MODE';
  if (env.TOVU_AGENT_FORBID_BASH === '1') return 'TOVU_AGENT_FORBID_BASH';
  return (['TOVU_AGENT_FULL_CLI_ACCESS', 'TOVU_AGENT_NATIVE_FALLBACKS'] as const)
    .find(key => ['0', 'false'].includes(env[key] ?? ''));
}

/** One fresh owner grant governs every CLI capability. Missing local settings default ON;
 * failed reads supply false. Request/contextRef fields never participate. Pure, O(1).
 * Platform facts are injected with the same snapshot used for permission-mode policy.
 */
export function resolveFullCliAccess(required: {
  isOwner: boolean; setting?: boolean | undefined; env: Readonly<Record<string, string | undefined>>;
}, optional: HostSignalOptions = {}): boolean {
  const env = required.env;
  return required.isOwner && required.setting !== false && !isHostedAssistantRuntime({ env }, optional) &&
    fullCliEnvLock({ env }, {}) === undefined;
}

/** Compatibility alias; there is no second grant resolver. */
export const resolveAssistantNativeFallbacks = resolveFullCliAccess;

/** Apply the structural owner/host gate before projecting any persisted per-capability choice.
 * The master is a default, not a second veto: individual toggles can be turned back on below it.
 * The host supplies matched facts so the projection shares the launch's host decision.
 * @complexity O(1), a fixed number of permissions. No I/O.
 */
export function resolveAssistantCliPermissions(required: {
  isOwner: boolean; env: Readonly<Record<string, string | undefined>>; settings: AssistantCliPermissions;
}, optional: HostSignalOptions = {}): AssistantCliPermissions {
  if (!resolveFullCliAccess({ isOwner: required.isOwner, env: required.env }, optional)) return assistantCliPermissions({ enabled: false });
  return assistantCliPermissions(required.settings);
}

/** Locked run policy (SEC-assistant-env-isolation-2026-09-07 Finding 2).
 * Owner decision 2026-10-17 supersedes native-tool restrictions for local full-access runs.
 * Historical rationale: those runs retained Read path denies as defense in depth only; Bash
 * could read keys and write other sites, which the owner accepted on 2026-10-17.
 * Owner decision 2026-10-23 supersedes that broader access for the in-app SITE agent:
 * Tovu supplies its site folder to Jini's mandatory filesystem boundary independently of these
 * capability grants. Bash stays available under the CLI sandbox on macOS/Linux; native Windows
 * retains shell access with an explicit warning. Desktop-agent confinement is a separate scope.
 * Bridge/site tool credentials stay scoped.
 * All other principals keep the complete list; native providers must enforce it or refuse spawn.
 */
export const ASSISTANT_DISALLOWED_TOOLS: readonly string[] = [
  "Bash",
  "Edit",
  "Write",
  "MultiEdit",
  "NotebookEdit",
  "BashOutput",
  "KillShell",
  "Task",
  // Claude Code 2.1.296 names the spawn tool Agent and recognizes Task as its legacy name.
  "Agent",
  "CronCreate",
  "CronDelete",
  "CronList",
  "EnterWorktree",
  "ExitWorktree",
  "RemoteTrigger",
  "Workflow",
  // Read/Grep/Glob path denies remain useful in locked runs and as defense in depth locally.
  // Historical Full CLI access accepted Bash reading these files (owner, 2026-10-17); the site
  // agent's 2026-10-23 filesystem boundary now applies independently. `//`
  // anchors at the filesystem root, so `//**/.tovu/**` covers the folder at any depth; `/proc` is
  // the Linux `/proc/<pid>/environ` route to the env-held key. Confirmed live on Claude Code
  // 2.1.281 under bypassPermissions: Read refused, Grep/Glob return no match on the denied files.
  "Read(//**/.tovu/**)",
  "Read(~/.tovu/**)",
  "Read(//**/*-key*.hex)",
  "Read(//proc/**)",
];


/** Project the one verified grant into native tool denies for both site and desktop hosts.
 * Legacy agent/subagent fields are accepted for compatibility but never establish a grant.
 * The October 17 owner accepted hand-run filesystem access; October 23 limits site agents to
 * their site folder without changing this capability projection. Read path denies remain.
 * @complexity O(t) for t fixed deny entries when enabled, O(1) for the locked policy.
 */
export function resolveAssistantDisallowedTools(required: {
  nativeToolAccess?: boolean; agentId?: string; subagentsEnabled?: boolean;
}, _optional: Record<string, never> = {}): readonly string[] {
  return required.nativeToolAccess
    ? ASSISTANT_DISALLOWED_TOOLS.filter(tool => tool.startsWith("Read("))
    : ASSISTANT_DISALLOWED_TOOLS;
}

import { ToolInputError } from "@jini-ai/core";
import type { AssistantSurfaceDeps } from "@jini-ai/daemon/surface-exchanges";
import { PERMANENT_DELETE_TOOLS } from "../headless/assistant-permanent-deletes-policy.js";
/** Host port carried alongside the existing authenticated human exchange. */
export type ChatDeleteSurfaceDeps = AssistantSurfaceDeps & {
  assertChatDeleteAllowed?: (required: { toolId: string; principalId?: string }, optional?: Record<string, never>) => Promise<void>;
};
/** Construct the same refusal for raw and assembled execution without another destination map.
 * @returns A safe ToolInputError containing only the tool id and canonical admin path.
 * @example throw chatDeleteRefusal({ toolId: "trash_empty" });
 * @complexity O(13) time, O(1) space; no effects. */
export function chatDeleteRefusal(required: { toolId: string }, _optional = {}): ToolInputError {
  const tool = PERMANENT_DELETE_TOOLS.find(tool => tool.id === required.toolId);
  return new ToolInputError({ message: `${required.toolId}: permanent deletes from chat are disabled. ${tool?.adminPath ? `Open ${tool.adminPath} to delete it as a human.` : "There is no Tovu admin screen for this operation."} Nothing was deleted.` });
}
/** Freshly authorize an eligible permanent delete through the injected site port.
 * @throws ToolInputError if a required reader is missing; read/policy errors propagate.
 * @example await requireChatDeleteGrant({ surfaces, toolId: "trash_empty" });
 * @complexity O(13) lookup and one injected read, O(1) local space. */
export async function requireChatDeleteGrant(required: { surfaces: ChatDeleteSurfaceDeps; toolId: string; principalId?: string }, _optional = {}): Promise<void> {
  const tool = PERMANENT_DELETE_TOOLS.find(tool => tool.id === required.toolId);
  if (!tool) return;
  if (!required.surfaces.assertChatDeleteAllowed) throw chatDeleteRefusal({ toolId: tool.id });
  await required.surfaces.assertChatDeleteAllowed({ toolId: tool.id,
    ...(required.principalId === undefined ? {} : { principalId: required.principalId }) });
}

import { isNonArrayRecord } from "@jini-ai/core";
/**
 * @file `extractEntryRefs` — the chokepoint-side `entry_refs` extractor (ADR-022 §5, SPEC-043
 * REQ-29..32).
 *
 * Purpose:
 * Walks a written entry's `bodyJson`/`fields.ext.*` for `ref`-typed fields (ADR-022 §5's field-type
 * vocabulary) and widget-reference-shaped nodes (`widget_area` placements, `widgetEmbed` nodes),
 * producing the rows `EntryRefsRepoPort.replaceForSource` writes in the SAME transaction as the
 * triggering entry write (INV-06) — never a follow-up async job. Entry-target references (menu,
 * form definition, success-page) are fully covered; a config field whose target kind is a
 * taxonomy term is extracted as a documented soft reference only where the installed schema
 * supports that target kind (REQ-32) — not claimed as safe-delete-protected.
 *
 * Architectural role:
 * TDD-certified implementation (implementation outline C-009). Called from the single entries
 * chokepoint — this function performs no I/O; the caller writes the returned rows inside its own
 * transaction. `extractEntryRefs()` handles structured entry bodies/config, while the later
 * `extractHtmlEntryRefs()` sibling indexes supported markers in HTML page bodies.
 */
import type { UUID } from "@jini-ai/core/primitives";
import { describeRejection, galleryMediaReferences, scanEmbedMarkers, type EmbedMarkerRejection } from "@jini-ai/cms/widgets/markers";
import type { EntryRefRow, EntryRefTargetKind } from "./types.js";

export interface ExtractEntryRefsInput {
  readonly workspaceId: UUID;
  readonly sourceEntryId: UUID;
  readonly sourceEntryType: string;
  /** The entry's post-write `bodyJson`, already validated. */
  readonly bodyJson: unknown;
  /** The entry's post-write `fields.ext.*` bag, already validated against its type's registered schema. */
  readonly fieldsExt: Readonly<Record<string, unknown>>;
}

/**
 * REQ-31/32's ref-suffix convention: a config field's KEY (not its schema) decides whether its
 * string value is a reference and, if so, which target kind. Keys ending in `TermId` are
 * taxonomy-term-target soft references (REQ-32); keys ending in `RefId`, `Ref`, or `Id` are
 * entry-target references (REQ-31) — covers every v1 ref-typed field `Jini/packages/cms/src/widgets/registry.ts`
 * declares (`formDefinitionId`, `menuRef`, `categoryTermId`, each now also carrying a matching
 * `x-ref-target` JSON-schema annotation) without this pure function needing to import that
 * registry — `extractEntryRefs` deliberately takes no injected schema/registry dependency (see
 * the certified test suite, which calls it with plain data only), so a structural, key-name-based
 * convention is the only mechanism available that stays a pure function of its literal input. A
 * schema-driven extractor (consulting the registry's `x-ref-target` markers directly) would be a
 * reasonable future upgrade if this function's signature is ever widened.
 *
 * @complexity O(1).
 * @overallScore 100
 */
function classifyRefFieldKey(key: string): EntryRefTargetKind | null {
  if (key.endsWith("TermId")) return "term";
  if (key.endsWith("RefId") || key.endsWith("Ref") || key.endsWith("Id")) return "entry";
  return null;
}

/**
 * Walks a TipTap-shaped document tree (`{ type, content: [...] }`, arrays of such
 * nodes) looking for `widgetEmbed` atoms (REQ-18/30), regardless of nesting depth — matches
 * `embed-validation.ts`'s INV-04 stance that nesting depth never matters, only presence.
 *
 * @complexity O(n) over the document's total node count.
 * @overallScore 100
 */
function collectWidgetEmbedRefs(root: unknown, rootPath: string, input: ExtractEntryRefsInput, refs: EntryRefRow[]): void {
  // An explicit stack, not recursion: a saved document's nesting depth is caller/import-controlled
  // and a 5000-deep body overflowed the call stack here on save (same class as f646ba397's GET-path
  // walkers). Children are pushed in reverse so the walk stays pre-order — the same ref order and
  // `fieldPath` strings the recursive version produced.
  const stack: Array<{ node: unknown; path: string }> = [{ node: root, path: rootPath }];
  while (stack.length > 0) {
    const { node, path } = stack.pop()!;
    if (Array.isArray(node)) {
      for (let index = node.length - 1; index >= 0; index--) stack.push({ node: node[index], path: `${path}[${index}]` });
      continue;
    }
    collectWidgetEmbedNode({ node, path, input, refs, stack });
  }
}

function collectWidgetEmbedNode(
  { node, path, input, refs, stack }: {
    node: unknown; path: string; input: ExtractEntryRefsInput; refs: EntryRefRow[];
    stack: Array<{ node: unknown; path: string }>;
  },
  _optional: Record<string, never> = {},
): void {
  const candidate = { value: node };
  if (!isNonArrayRecord(candidate)) return;
  const attrs = { value: candidate.value.type === "widgetEmbed" ? candidate.value.attrs : undefined };

  if (isNonArrayRecord(attrs) && typeof attrs.value.widgetEntryId === "string") {
    refs.push({
      workspaceId: input.workspaceId,
      sourceEntryId: input.sourceEntryId,
      sourceKind: "widget-embed",
      fieldPath: path,
      targetKind: "entry",
      targetId: attrs.value.widgetEntryId,
    });
  }

  if (isNonArrayRecord(attrs)) addMediaConfigRefs({ config: attrs.value.content, path: `${path}.attrs.content`, input, refs });
  if (Array.isArray(candidate.value.content)) stack.push({ node: candidate.value.content, path: `${path}.content` });
}

/**
 * REQ-30 (a): a widget_area's placement list — shape-detected, not type-gated (REQ-17 already
 * guarantees only a widget_area entry's bodyJson ever carries this shape).
 *
 * @complexity O(n) over the placement list's length.
 * @overallScore 100
 */
function collectPlacementRefs(input: ExtractEntryRefsInput, refs: EntryRefRow[]): void {
  const body = { value: input.bodyJson };
  if (!isNonArrayRecord(body) || !Array.isArray(body.value.placements)) return;

  (body.value.placements as unknown[]).forEach((placement, index) => {
    const candidate = { value: placement };
    if (!isNonArrayRecord(candidate) || typeof candidate.value.widgetEntryId !== "string") return;

    addMediaConfigRefs({ config: candidate.value.content, path: `bodyJson.placements[${index}].content`, input, refs });
    refs.push({
      workspaceId: input.workspaceId,
      sourceEntryId: input.sourceEntryId,
      sourceKind: "widget-area-placement",
      fieldPath: `bodyJson.placements[${index}]`,
      targetKind: "entry",
      targetId: candidate.value.widgetEntryId,
    });
  });
}

/**
 * REQ-31/32 — one namespace's `config` bag: every string-valued, non-empty, ref-suffixed key
 * (per {@link classifyRefFieldKey}) becomes a `config-field` row.
 *
 * @complexity O(k) over the config bag's key count.
 * @overallScore 100
 */
function collectNamespaceConfigRefs(
  namespace: string,
  config: Record<string, unknown>,
  input: ExtractEntryRefsInput,
  refs: EntryRefRow[]
): void {
  for (const [key, value] of Object.entries(config)) {
    if (typeof value !== "string" || value.length === 0) continue;
    const targetKind = classifyRefFieldKey(key);
    if (!targetKind) continue;

    refs.push({
      workspaceId: input.workspaceId,
      sourceEntryId: input.sourceEntryId,
      sourceKind: "config-field",
      fieldPath: `fields.ext.${namespace}.config.${key}`,
      targetKind,
      targetId: value,
    });
  }
}

/** Media reference keys include authored slugs. Read services match both id and slug; this pure
 * extractor intentionally does no repository I/O inside the caller's write transaction. */
function addMediaConfigRefs({ config, path, input, refs }: { config: unknown; path: string; input: Pick<ExtractEntryRefsInput, 'workspaceId' | 'sourceEntryId'>; refs: EntryRefRow[] }): void {
  for (const [index, ref] of galleryMediaReferences({ config }).entries()) refs.push({
    workspaceId: input.workspaceId, sourceEntryId: input.sourceEntryId, sourceKind: 'config-field',
    fieldPath: `${path}.media[${index}]`, targetKind: 'asset', targetId: ref.mediaId,
  });
}

/**
 * REQ-31/32: ref-typed config fields inside fields.ext.<namespace>.config, across every
 * namespace in `fieldsExt`.
 *
 * @complexity O(n) over `fieldsExt`'s namespace count (per-namespace key scan delegated to
 *   {@link collectNamespaceConfigRefs}).
 * @overallScore 100
 */
function collectConfigFieldRefs(input: ExtractEntryRefsInput, refs: EntryRefRow[]): void {
  // `fieldsExt` is a required bag: every caller (the widget/region/embed write services and
  // content-references) passes an object, `{}` when the entry has no ext fields.
  for (const [namespace, namespaceValue] of Object.entries(input.fieldsExt)) {
    const namespaceRecord = { value: namespaceValue };
    if (!isNonArrayRecord(namespaceRecord)) continue;
    const config = { value: namespaceRecord.value.config };
    if (!isNonArrayRecord(config)) continue;

    collectNamespaceConfigRefs(namespace, config.value, input, refs);
    collectWidgetConfigMedia({ namespace, widgetType: namespaceRecord.value.widgetType, config: config.value, input, refs });
  }
}

function collectWidgetConfigMedia(
  { namespace, widgetType, config, input, refs }: {
    namespace: string; widgetType: unknown; config: Record<string, unknown>;
    input: ExtractEntryRefsInput; refs: EntryRefRow[];
  },
  _optional: Record<string, never> = {},
): void {
  if (namespace === "widget" && (widgetType === "gallery" || widgetType === "media")) {
    for (const { mediaId, index } of galleryMediaReferences({ config })) refs.push({
      workspaceId: input.workspaceId, sourceEntryId: input.sourceEntryId, sourceKind: "config-field",
      fieldPath: `fields.ext.${namespace}.config.media[${index}]`, targetKind: "asset", targetId: mediaId,
    });
  }
}

/**
 * REQ-29..32 — extracts every `entry_refs` row implied by one entry's written state: a
 * `widget_area` placement list (REQ-30), any `widgetEmbed` node inside `bodyJson` (REQ-30/18), and
 * any ref-typed config field inside `fieldsExt` (REQ-31/32). Pure and idempotent (INV-06's
 * "same-transaction, re-extract on every write" discipline depends on this being a deterministic
 * function of the entry's own state, never accumulating hidden extractor-local state) — no I/O, no
 * side effects. The caller (the entries write chokepoint composition in `Jini/packages/cms/src/widgets/write-service.ts`/
 * `region-area-service.ts`) is responsible for writing the returned rows via
 * `EntryRefsRepoPort.replaceForSource`.
 *
 * @complexity O(n) over `bodyJson`'s node count plus O(k) over `fieldsExt`'s config keys.
 * @overallScore 100
 */
export function extractEntryRefs(input: ExtractEntryRefsInput): readonly EntryRefRow[] {
  const refs: EntryRefRow[] = [];

  collectPlacementRefs(input, refs);
  // REQ-30 (b): widgetEmbed nodes anywhere inside bodyJson.
  collectWidgetEmbedRefs(input.bodyJson, "bodyJson", input, refs);
  collectConfigFieldRefs(input, refs);

  return refs;
}

// ---------------------------------------------------------------------------
// SPEC-047 Slice 3 — `"html"`-format Page bodies (`body_html`, a plain string, not a `bodyJson`
// tree). A sibling entry point to `extractEntryRefs` above, not a mode of it: an html Page is
// written through `features/pages/html-document-store.sqlite.ts`'s `PagesHtmlDocumentStore`, a completely
// separate write path from the `entries` chokepoint `extractEntryRefs` is called from (ADR-056
// CIC-3 — Pages bypass that chokepoint entirely), so it needs its own call site, not a widened
// `ExtractEntryRefsInput`.
// ---------------------------------------------------------------------------

/**
 * Mirrors `Jini/packages/cms/src/widgets/html/html-embeds.ts`'s `MAX_HTML_EMBEDS_PER_PAGE` — the index must never grow past
 * what a render can actually resolve, so the same resource bound applies here too. */
const MAX_HTML_PAGE_EMBED_REFS = 50;

/** Mirrors `Jini/packages/cms/src/widgets/html/html-embeds.ts`'s id sanity bound. */
const MAX_HTML_EMBED_REF_ID_LENGTH = 200;

/**
 * Embed types this function currently knows how to target-map into `entry_refs`, and which
 * {@link EntryRefTargetKind} each maps to. `widget` -> `"entry"` (mirrors `MENU_REGISTRATION`'s
 * `menuRef`/`CONTACT_FORM_REGISTRATION`'s `formDefinitionId` both being extracted as
 * `"entry"`-target refs elsewhere in this codebase even though neither a menu nor a Forms definition
 * is a literal `entries`-table row; `targetKind` marks "a durable content object", not literal table
 * membership). `media` -> `"asset"`: a media asset lives in a different storage domain
 * than the generic `entries` graph, so it gets its own target kind rather
 * than overloading `"entry"`). A type absent from this map is still SCANNED (the shared parser
 * reports every marker regardless of type) but produces no row: an unrecognized/future type has no
 * known target-kind mapping yet, and guessing one would be actively wrong data, not just
 * incomplete. Widening this map is exactly the "one place to change" a new indexable type needs; the
 * parser never does.
 *
 * Forms definitions are referenced through persisted contact-form widget configuration:
 * `classifyRefFieldKey` indexes `config.formDefinitionId` as an entry-target config-field row.
 * Safe-delete therefore follows page -> widget -> form definition, with a persisted object at
 * each hop; see `development/docs/architecture/embed-type-inventory.md`.
 */
const HTML_EMBED_TARGET_KINDS: ReadonlyMap<string, EntryRefTargetKind> = new Map([
  ["widget", "entry"],
  ["media", "asset"],
]);

/**
 * A marker that carries `data-embed-config` but could not be parsed. **This is the loudest failure
 * in this file, and deliberately so.**
 *
 * Every other skip here is a decision: an unmapped type has no `targetKind`, an absent id has
 * nothing to populate `targetId` with. A REJECTED marker is different — it is a reference that
 * exists in the markup and that this index cannot see. `entry_refs` is what safe-delete's where-used
 * check reads (SPEC-043 REQ-34/REQ-42), so a dropped row does not degrade the feature, it INVERTS
 * it: the delete is reported safe precisely because the reference protecting the target went
 * missing. One stray character in one config is enough.
 *
 * This function is pure and contractually never throws, so it warns rather than refusing — the write
 * has already been validated and is in flight by the time extraction runs. Refusing the write is the
 * write chokepoint's job (migration contract step 2), and that gate is what makes this warning rare
 * rather than routine. Until it exists, this line is the only signal that an index is incomplete.
 */
function warnRejectedMarkers(rejected: readonly EmbedMarkerRejection[], sourceEntryId: UUID): void {
  for (const rejection of rejected) {
    console.warn(
      `[entry-refs] extractHtmlEntryRefs: UNINDEXED reference — ${describeRejection({ rejection: rejection })}. ` +
        `Safe-delete cannot see it, so a target it references may be deleted as unused.`,
      { sourceEntryId }
    );
  }
}

/**
 * REQ-30-style — extracts one `entry_refs` row per embed marker found in `html`, up to
 * {@link MAX_HTML_PAGE_EMBED_REFS}. `targetKind` is looked up per embed type via
 * {@link HTML_EMBED_TARGET_KINDS} — an embed type with no entry there (unrecognized/future type)
 * produces no row rather than a guessed `targetKind`. Pure, never throws, matching
 * `extractEntryRefs`'s own contract.
 *
 * Marker parsing belongs to Jini CMS's shared widget marker parser. Rendering and indexing
 * consume the same definition so their marker interpretations cannot drift.
 *
 * A reference whose `id` key is absent, empty, non-string, or beyond
 * {@link MAX_HTML_EMBED_REF_ID_LENGTH} produces no row — `EntryRefRow.targetId` is a required
 * `UUID`, so an unusable id has nothing to populate it with (mirrors `scanHtmlEmbeds`'s own
 * id-normalization, but this function drops the occurrence entirely rather than reporting a null-id
 * row, since an indexable-or-not decision is exactly what this function's contract already commits
 * to for every other ref kind it extracts).
 *
 * **Disclosed gap: a `slug`-only `{"type":"widget","slug":"..."}` marker — no `id` at
 * all — produces no `entry_refs` row either, for the same "no id" branch above, even though
 * `resolver-service.ts`'s `resolveWidgetTypeEmbeds` now resolves it to a real widget at render time.**
 * This function is deliberately pure (see this file's own header — no repo/resolver dependency), and
 * turning a `slug` into the `UUID` `EntryRefRow.targetId` requires exactly the I/O this function's
 * contract forbids itself, so the two cannot be reconciled without either widening this function's
 * signature (a real architectural change, not attempted here) or normalizing a marker's `slug` to a
 * real `id` at WRITE time instead (`PagesHtmlDocumentStore.write()`, not this pass's scope). Until
 * one of those lands, a page embedding a widget ONLY by slug is invisible to safe-delete's where-used
 * check — the exact "reference exists in the markup, index can't see it" hazard this function's own
 * `warnRejectedMarkers` was built to be loud about for a REJECTED marker, but a valid slug-only one
 * does not reach `rejected` (it parses fine), so no warning fires here today. Flagged prominently
 * rather than silently shipped; see this feature's handoff for the same disclosure.
 *
 * `fieldPath` counts every marker, not only indexable ones, so adding a target-kind mapping
 * cannot change an existing occurrence's locator. Nothing parses this human-readable locator;
 * existing stored rows retain their spelling until the next source-page write replaces them.
 *
 * **Indexes REFERENCES, never RESOLUTIONS — by construction, not by discipline.** This function
 * takes no repo/resolver dependency (only a plain `html` string), so it has no way to check whether
 * a placeholder's target currently exists, let alone resolves. A marker pointing at a deleted widget
 * produces a row here exactly like one pointing at a live widget does. This is required, not
 * incidental: `entry_refs`' whole purpose is catching "deleting a widget silently breaks a page",
 * and that is precisely the page whose reference has stopped resolving — indexing only what
 * currently resolves would make the one broken page the one page the integrity check silently
 * ignores. `resolver-service.ts`'s `resolveHtmlPageEmbeds` (a completely separate function, called
 * from the render path, never from here) is where "does this currently resolve" is answered — this
 * function never asks.
 *
 * @complexity O(n) over `html`'s length for the shared scan.
 * @overallScore 100
 */
export function extractHtmlEntryRefs(input: {
  readonly workspaceId: UUID;
  readonly sourceEntryId: UUID;
  readonly html: string;
}, _optional: Record<string, never> = {}): readonly EntryRefRow[] {
  const { markers, rejected } = scanEmbedMarkers({ html: input.html });
  warnRejectedMarkers(rejected, input.sourceEntryId);

  const refs: EntryRefRow[] = [];
  addMediaConfigRefs({ config: { html: input.html }, path: 'bodyHtml.raw', input, refs });
  let singleTargetRefs = 0;
  let galleryMarkers = 0;
  for (const marker of markers) {
    if (marker.type.toLowerCase() === "gallery") {
      galleryMarkers += 1;
      if (galleryMarkers > MAX_HTML_PAGE_EMBED_REFS) continue;
      collectHtmlGalleryRefs({ marker, input, refs });
      continue;
    }
    addMediaConfigRefs({ config: marker.config, path: `bodyHtml[embed:${marker.type.toLowerCase()}#${marker.occurrence}]`, input, refs });
    const ref = htmlSingleTargetRef({ marker, input });
    if (!ref) continue;
    refs.push(ref);
    // Gallery images do not consume unrelated markers' existing single-target reference budget.
    singleTargetRefs += 1;
    if (singleTargetRefs >= MAX_HTML_PAGE_EMBED_REFS) break;
  }

  return refs;
}

type HtmlMarker = ReturnType<typeof scanEmbedMarkers>["markers"][number];
type HtmlRefInput = Pick<ExtractEntryRefsInput, "workspaceId" | "sourceEntryId">;

function collectHtmlGalleryRefs(
  { marker, input, refs }: { marker: HtmlMarker; input: HtmlRefInput; refs: EntryRefRow[] },
  _optional: Record<string, never> = {},
): void {
  // Keep image-specific locators, including repeated media ids. Index authored references
  // even if layout/alt validation fails: safe-delete must still see the dependent page.
  for (const image of galleryMediaReferences({ config: marker.config })) {
    refs.push({
      workspaceId: input.workspaceId,
      sourceEntryId: input.sourceEntryId,
      sourceKind: "page-html-embed",
      fieldPath: `bodyHtml[embed:gallery#${marker.occurrence}].images[${image.index}].mediaId`,
      targetKind: "asset",
      targetId: image.mediaId,
    });
  }
}

function htmlSingleTargetRef(
  { marker, input }: { marker: HtmlMarker; input: HtmlRefInput },
  _optional: Record<string, never> = {},
): EntryRefRow | undefined {
  const targetKind = HTML_EMBED_TARGET_KINDS.get(marker.type.toLowerCase());
  if (!targetKind) return;
  const id = marker.id;
  if (!id || id.length > MAX_HTML_EMBED_REF_ID_LENGTH) return;

  return {
    workspaceId: input.workspaceId,
    sourceEntryId: input.sourceEntryId,
    sourceKind: "page-html-embed",
    fieldPath: `bodyHtml[embed:${marker.type.toLowerCase()}#${marker.occurrence}]`,
    targetKind,
    targetId: id,
  };
}

import { isTrashed } from "./soft-delete.js";

/**
 * @file Scheduled publishing — the one rule for "is this published row live yet?".
 *
 * A scheduled post is NOT a third status. It is a `status: "published"` row whose `publishAt` is
 * still in the future: stored as published, hidden from every public read until that instant
 * passes. Render-time on purpose — there is no background job to miss, crash or lag, so a post is
 * live at the first request after its time with nothing else having to run.
 *
 * Why not a `"scheduled"` status: `PostStatus` is a two-value union matched by ~50 call sites
 * (admin editors, headless contracts, publish-to-live), and every one of them would have had to
 * learn a third value. Here they keep working unchanged and only the public read gates add this
 * check. Lives in `contracts/core` (beside `isTrashed`) so `platform/routing` can apply the same
 * rule without importing `features/post` — the cycle `soft-delete.ts`'s own header describes.
 *
 * `publishAt` and `nowIso` are both ISO-8601 UTC strings from `Date.prototype.toISOString()`
 * (`normalizePublishAt` in `features/post/post.ts` is the only writer), so a plain string compare
 * orders them correctly.
 */

export interface SchedulableRecord {
  readonly status: string;
  readonly publishAt?: string | null;
}

/** The current instant in the same ISO shape `publishAt` is stored in. */
export function currentIso(): string {
  return new Date().toISOString();
}

/** True when a published row's go-live time is still ahead of `nowIso`. A draft is never "scheduled":
 *  its `publishAt` only takes effect once it is published. @complexity O(1). */
export function isScheduledAt(record: SchedulableRecord, nowIso: string): boolean {
  return record.status === "published" && typeof record.publishAt === "string" && record.publishAt > nowIso;
}

/** The date a post's date line shows (owner policy): its go-live time when it has one —
 *  so a scheduled post's Preview shows the day it will go live, and the same post shows that date once
 *  live — else `updatedAt`, since `PostRecord` has no separate published-at column. @complexity O(1). */
export function postDisplayDateIso(record: { readonly publishAt?: string | null; readonly updatedAt: string }): string {
  return record.publishAt ?? record.updatedAt;
}

/** Newest display date first ({@link postDisplayDateIso}), then `id` ascending — the in-JS twin of
 *  the post repo's `ORDER BY coalesce(publish_at, updated_at) DESC, id ASC`. @complexity O(1). */
export function comparePostsByDisplayDate(
  a: { readonly id: string; readonly publishAt?: string | null; readonly updatedAt: string },
  b: { readonly id: string; readonly publishAt?: string | null; readonly updatedAt: string }
): number {
  const left = postDisplayDateIso(a);
  const right = postDisplayDateIso(b);
  if (left !== right) return left < right ? 1 : -1;
  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

/** Published, not trashed, and past its go-live time — the whole public-visibility rule for a post
 *  or page row. @complexity O(1). */
export function isLiveAt(record: SchedulableRecord & { readonly deletedAt?: string | null }, nowIso: string): boolean {
  return record.status === "published" && !isTrashed(record) && !isScheduledAt(record, nowIso);
}

