  { namespace: "core.execution", key: "byok.providerId", reason: "Changes which provider receives assistant requests" },
  { namespace: "core.execution", key: "byok.baseUrl", reason: "Changes the endpoint receiving assistant requests" },
] as const;
export const TOOL_APPROVAL_POLICY: Readonly<Record<string, ToolApprovalPolicy>> = nativeToolMetadata.approvals;

/** Only parked approval calls can be answered through the MCP-UI callback route. */
export const POLICY_CONFIRMATION_TOOL_IDS = nativeToolMetadata.policyConfirmationIds;

/** Behavior-reviewed plugin-add controls: input/disclosure/cancel or installation that stays off.
 * Do not add destructive or publish controls here, including their final confirmation buttons. */
const DIRECT_PAGE_HANDLES: ReadonlySet<string> = new Set([
  'plugins-install-advanced', 'plugins-install-folder', 'plugins-install-folder-upload',
  'plugins-install-zip', 'plugins-install-replace', 'plugins-install-preview',
  'plugins-install-cancel', 'plugins-install-confirm',
  'agent-plugin-add-choose', 'agent-plugin-add-choose-folder', 'agent-plugin-add-replace',
  'agent-plugin-add-install', 'agent-plugin-add-url', 'agent-plugin-add-from-url',
  'skills-add-github-url', 'skills-add-github', 'skills-add-files', 'skills-add-folder',
  'skills-install-cancel', 'skills-install-confirm',
]);
export function directPageAction({ capabilityId, input }: { capabilityId: string; input: unknown }, _optional = {}): boolean {
  if (!Object.hasOwn(TOOL_APPROVAL_POLICY, capabilityId)) throw new Error(`${capabilityId} has no approval classification`);
  if (capabilityId !== 'page.click') return TOOL_APPROVAL_POLICY[capabilityId]!.confirmation === 'direct';
  const handle = input && typeof input === 'object' ? (input as Record<string, unknown>).handle : undefined;
  return typeof handle === 'string' && DIRECT_PAGE_HANDLES.has(handle);
}

/** Data-generated ids are classified by the host factory's behavior, never their names or prose.
 * Memory refresh is a plain text edit; guidance and computed capability results save nothing.
 * These host-specific families use core's descriptor metadata, the same contract as native tools. */
export const EXTENSION_TOOL_APPROVAL_POLICY = {
  'installed-guidance': { class: 'read', confirmation: 'direct' },
  'plugin-capability-result': { class: 'read', confirmation: 'direct' },
  'plugin-memory-read': { class: 'read', confirmation: 'direct' },
  'plugin-memory-write': { class: 'edit', confirmation: 'direct' },
  // Executable Agent Plugin tools act on an external account. The plugin's declared effect may only
  // add friction: a read runs directly, a write leaves this site and asks, a destructive change asks
  // as a delete (danger styling). The host adds the affected-resource disclosure to the card.
  'agent-plugin-read': { class: 'read', confirmation: 'direct' },
  'agent-plugin-write': { class: 'publish', confirmation: 'policy' },
  'agent-plugin-destructive': { class: 'delete', confirmation: 'policy' },
} as const satisfies Readonly<Record<string, ToolApprovalPolicy>>;
export function withExtensionApprovalPolicy(
  { registration, family }: { registration: ToolRegistration; family: keyof typeof EXTENSION_TOOL_APPROVAL_POLICY }, _optional = {},
): ToolRegistration {
  if (!Object.hasOwn(EXTENSION_TOOL_APPROVAL_POLICY, family)) throw new Error(`${registration.descriptor.id} has no approval classification`);
  return { ...registration, descriptor: { ...registration.descriptor, metadata: { ...registration.descriptor.metadata, approval: EXTENSION_TOOL_APPROVAL_POLICY[family] } } };
}
export function toolApprovalPolicyFor({ registration }: { registration: ToolRegistration }, _optional = {}): ToolApprovalPolicy {
  const policy = registration.descriptor.metadata?.approval as ToolApprovalPolicy | undefined
    ?? (Object.hasOwn(TOOL_APPROVAL_POLICY, registration.descriptor.id) ? TOOL_APPROVAL_POLICY[registration.descriptor.id] : undefined);
  if (!policy) throw new Error(`${registration.descriptor.id} has no approval classification`);
  return policy;
}

/** CMS chat naming adapter. Preserve a named post/page as a complete phrase instead of spending
 * Jini's six-word heuristic on "publish a short blog post titled How". The generic title policy
 * stays in Jini; this adapter only recognizes CMS requests and delegates all other prompts.
 * Long named content gets a complete action label, never a sliced fragment of its title. */
import { stripConversationTitleMarkdown } from "@jini-ai/chat/core";

export function deriveContentConversationTitle(
  required: { prompt: string; deriveFallback: (input: { prompt: string }) => string },
  _optional: Record<string, never> = {},
): string {
  // Strip markup before recognizing CMS names: an early period boundary once stranded **plannie.
  // The generic text policy belongs to Jini; this adapter still owns only CMS-specific naming.
  const prompt = stripConversationTitleMarkdown({ text: required.prompt });
  // Standalone resource/skill slugs are already meaningful titles; retain the existing behavior.
  if (/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(prompt) && prompt.length <= 64) return prompt;
  const content = /\b(blog\s+post|post|page|article)\b/i.exec(prompt);
  if (!content) return required.deriveFallback({ prompt });
  const tail = prompt.slice(content.index + content[0].length);
  const title = readContentName({ tail });
  if (title) return formatContentName({ prompt, contentKind: content[0], title });
  // A dangling title introducer never identifies content. Fall back to the complete CMS action.
  const fallback = required.deriveFallback({ prompt });
  return fallback.replace(/\s+(?:titled|called|named)(?:\s+.*)?$/i, "");
}

function readContentName({ tail }: { tail: string }, _optional: Record<string, never> = {}): string | undefined {
  // Domains and versions contain punctuation too; only a following space or end ends a sentence.
  const named = /\b(?:titled|called|named)\s*(?::\s*)?(?:["“]([^"”]+)["”]|'([^']+)'|([^\n]+?)(?=[.!?](?:\s|$)|\n|$))/i.exec(tail);
  const quoted = /["“]([^"”]+)["”]/.exec(tail);
  return (named?.[1] ?? named?.[2] ?? named?.[3] ?? quoted?.[1])?.trim();
}

function formatContentName(
  { prompt, contentKind, title }: { prompt: string; contentKind: string; title: string },
  _optional: Record<string, never> = {},
): string {
  const label = contentKind.toLowerCase() === "page" ? "Page" : contentKind.toLowerCase() === "article" ? "Article" : "Blog post";
  const candidate = `${label}: ${title}`;
  if (candidate.length <= 80) return candidate;
  const action = /\bpublish\b/i.test(prompt) ? "Publish" : /\b(?:create|write)\b/i.test(prompt) ? "Write" : "Edit";
  return `${action} ${label.toLowerCase()}`;
}

/**
 * A theme id. Open string under SPEC-004 because themes are discovered from disk, so
 * the valid set is dynamic.
 * Clients read the current valid ids from `availableThemeIds`.
 *
 * One value is RESERVED and never names a theme: `"none"` (`features/theme`'s `NO_THEME_ID`) means
 * the operator turned the theme off deliberately and the site renders unstyled. A headless client
 * reading `activeThemeId` must treat it as "no theme", not as a theme id to look up — asking for a
 * theme by that id 404s. It deliberately never appears in `availableThemeIds`, which is a catalogue
 * of themes a client can PICK, not a list of values the API will accept. No type change: the
 * sentinel is a legal `HeadlessThemeId` because this alias is an open string.
 */
export type HeadlessThemeId = string;

/**
 * SPEC-002 (content-entry-authoring) discriminates a blog-style `"post"` from a
 * standalone `"page"` over the same underlying record shape (see
 * `features/post/post.ts`'s `PostKind` doc). Declared locally rather than
 * importing `features/post`'s `PostKind` — `headless` is the wire-contract
 * layer and stays decoupled from feature internals (mirrors `HeadlessThemeId`'s
 * open-string precedent just above); the two are kept in lockstep by
 * `toHeadlessPost`/`toHeadlessContentPost`, the only callers that populate it.
 */
export type HeadlessEntryKind = "post" | "page";

/**
 * SPEC-047/ADR-056 Decision 3 — discriminates which body an `AdminPost` actually carries. Declared
 * locally rather than importing `features/post`'s `PostBodyFormat`, for the same reason
 * `HeadlessEntryKind` is declared locally just above: `headless` is the wire-contract layer and
 * stays decoupled from feature internals; `toHeadlessPost` is the only place the two are kept in
 * lockstep.
 */
export type HeadlessBodyFormat = "doc" | "html";

interface AdminPostFields {
  /** Editable display credit, independent of the creator principal. */
  author?: string | null;
  showAuthor?: boolean;
  id: string;
  workspaceId: string;
  /** SPEC-002 api.spec.md §5 — entry kind. */
  kind: HeadlessEntryKind;
  title: string;
  slug: string;
  status: "draft" | "published";
  updatedAt: string;
  version: number;
  /**
   * SPEC-005 REQ-11/AC-14 — optional plugin extension-field bag,
   * namespaced per plugin (`{ [pluginId]: { …declaredFields } }`). Present only when a plugin has
   * actually written to this entry; an entry with no contributing plugin carries no `ext` key at
   * all.
   */
  ext?: Record<string, Record<string, unknown>>;
  /**
   * Optional `pages/*.html` filename (of the active static theme's
   * `theme.json` `postTemplate` array) this post renders through. `toHeadlessPost` always populates
   * a real value (`post.templateChoice ?? null`) on every live response, so a consumer only ever
   * sees `undefined` in a hand-built test fixture that predates this field, never from the real API.
   * `null` and `""` are NOT interchangeable — see `PostRecord.templateChoice` for the tri-state.
   */
  templateChoice?: string | null;
  /**
   * Optional slug-collision override: `null` means this post never had an explicit opinion set
   * (the resolver's current default policy applies), `true`/`false` is a permanent explicit author
   * choice. `toHeadlessPost` always populates a real value (`post.overridesThemePage ?? null`) on
   * every live response; `undefined` only appears in a pre-feature test fixture.
   */
  overridesThemePage?: boolean | null;
  /** Scheduled publishing — ISO UTC go-live instant; absent when not scheduled. A
   *  `published` post whose `publishAt` is in the future is not yet visible on the public site. */
  publishAt?: string;
  /** Featured image — media asset id; absent when the post has none. */
  featuredMediaId?: string;
}

/**
 * SPEC-047/ADR-056 Decision 3 / REQ-3 — a discriminated union, not one loose type with two optional
 * body fields. The trap this closes: TipTap silently discards markup outside its node vocabulary and
 * saves the loss with no error, so "never build a TipTap editor's props from an `html`-format row"
 * cannot be left to a runtime `if` a future refactor can quietly delete. Narrowing on `bodyFormat`
 * (e.g. `if (post.bodyFormat === "doc")`) is the only way to reach a non-null `bodyJson` — a caller
 * that does not narrow, or narrows on the wrong field, gets a type error, not a runtime surprise. See
 * `admin-post-response.type.test.ts` for the compile-time proof.
 */
export type AdminPost =
  | (AdminPostFields & { bodyFormat: "doc"; bodyJson: Record<string, unknown>; bodyHtml: null })
  | (AdminPostFields & { bodyFormat: "html"; bodyJson: null; bodyHtml: string });

export interface AdminPostEnvelope {
  post: AdminPost;
}

export interface ContentPost {
  author?: string | null;
  showAuthor?: boolean;
  id: string;
  /** SPEC-002 api.spec.md §5 (`CONTENT_ENTRY_BY_SLUG`) — entry kind. */
  kind: HeadlessEntryKind;
  title: string;
  slug: string;
  bodyJson: Record<string, unknown>;
  updatedAt: string;
}

/**
 * ADR-020 capability tier, mirrored locally from `features/theme`'s `ThemeTier` for the same
 * decoupling reason as `HeadlessEntryKind` above — the wire contract doesn't import feature
 * internals. Kept in lockstep by `toAdminPresentationResponse`, the only place that populates it.
 */
export type HeadlessThemeTier = "declarative" | "templated" | "handlebars" | "static" | "code";

export interface HeadlessThemeSummary {
  /** Existing screenshot URL, or null when the theme has no preview image. */
  previewImageUrl?: string | null;
  id: HeadlessThemeId;
  /** The theme's display name — `theme.json`'s `name`, or the id when the manifest has none
   *  (`ThemeManifest.name`'s own fallback, `theme.ts`). What the admin shows the owner; the id
   *  stays the key. */
  name: string;
  tier: HeadlessThemeTier;
  /**
   * The theme's manifest `apiVersion` (`2`, or `undefined` for v1) tells the admin whether page
   * templates live under `pages/` (v1) or `render/pages/` (v2). Mirrors `ThemeManifest.apiVersion`.
   */
  apiVersion?: 2;
  /** Ships with the package itself (its originals catalog has this id), so the Themes screen does
   *  not offer to delete it. A copy of a shipped theme is `false`. Optional for older servers. */
  builtIn?: boolean;
}

export interface AdminPresentation {
  settings: {
    workspaceId: string;
    activeThemeId: HeadlessThemeId;
    updatedAt: string;
  };
  availableThemeIds: HeadlessThemeId[];
  /**
   * Themes admin screen — every available theme's id plus its ADR-020 capability
   * tier, so the Themes screen can group cards by tier without a second round trip. Same id set
   * as `availableThemeIds` above (that field stays for callers that only need ids); this is the
   * superset callers that need tier read instead.
   */
  availableThemes: HeadlessThemeSummary[];
  /**
   * Template picker — the active theme's `theme.json`
   * `templates` array (e.g. `["blog-post.html", "page-shell.html"]`), or `[]` when the active theme
   * doesn't declare one. BOTH the Post editor's and the Pages editor's picker read this SAME field to
   * populate their options. The unified `content` marker makes the template list common;
   * see `ThemeManifest.templates` (`features/theme/theme.ts`) for the
   * historical reasoning). Editor GETs now supply `kind=post` or `kind=page` to filter this
   * array using `ThemeManifest.templateFor`, preserving manifest order. Omitting kind retains the
   * full catalog. An empty array means a picker has nothing to offer and stays hidden unless its
   * content row already has a saved choice, which the editor keeps visible.
   */
  activeThemeTemplates: string[];
  /**
   * Slug-collision override — every page id (`theme.pages` key) the active theme ships,
   * or `[]` for a non-`static`-tier theme. The Post editor uses this to warn an author when a post's
   * slug matches one of these — that slug's route currently belongs to the theme's own page, not the
   * post, unless the post's `overridesThemePage` is set.
   */
  activeThemeStaticPageIds: string[];
}

export interface ContentPostPayload {
  post: ContentPost;
  presentation: {
    activeThemeId: HeadlessThemeId;
  };
}

import { readFile, stat } from "node:fs/promises";
import path from "node:path";
import { ToolInputError, requireInputRecord } from "@jini-ai/core";
import { CHAT_ATTACHMENT_REF_PATTERN, type ChatAttachmentReadResult } from "./chat-attachment.js";

/** Host-owned byte access: composition scopes opaque refs by principal and accepted message/run. */
export type InstallAttachmentReader = (
  required: { ref: string; ownerId: string; runId: string },
  optional: { maxBytes: number },
) => Promise<ChatAttachmentReadResult>;

export const PLUGIN_INSTALL_SOURCE_SCHEMA = {
  type: "object", additionalProperties: false, required: ["kind"],
  oneOf: [{ required: ["path"], not: { required: ["attachmentRef"] } }, { required: ["attachmentRef"], not: { required: ["path"] }, properties: { kind: { const: "zip" } } }],
  properties: {
    kind: { type: "string", enum: ["folder", "zip"], description: "folder for an unpacked package; zip for a local ZIP or chat attachment." },
    path: { type: "string", minLength: 1, description: "Absolute path on the machine Tovu runs on. Exactly one of path/attachmentRef." },
    attachmentRef: { type: "string", pattern: "^attachment:[A-Za-z0-9-]{8,80}$", description: "Opaque attachment:<uuid> for a file on this message: copy it from chat_list_pending_attachments. Not derivable from the file's disk path or folder. ZIP only; exactly one of path/attachmentRef." },
  },
} as const;

export interface PluginInstallRequest { readonly kind: "folder" | "zip"; readonly path?: string; readonly attachmentRef?: string; readonly replace: boolean }

export interface InstallArchiveFiles {
  stat(required: { path: string }, optional?: Record<string, never>): Promise<{ size: number }>;
  read(required: { path: string }, optional?: Record<string, never>): Promise<Uint8Array>;
}

const nodeArchiveFiles: InstallArchiveFiles = {
  stat: ({ path: sourcePath }, _optional) => stat(sourcePath),
  read: ({ path: sourcePath }, _optional) => readFile(sourcePath),
};

export function readPluginInstallRequest(
  { input: rawInput }: { input: unknown },
  _optional: Record<string, never> = {},
): PluginInstallRequest {
  const input = requireInputRecord({ input: rawInput });
  if (!input.source || typeof input.source !== "object" || Array.isArray(input.source)) throw new ToolInputError({ message: "source is required." });
  const source = input.source as Record<string, unknown>;
  const { kind, path: sourcePath, attachmentRef } = source;
  if (kind !== "folder" && kind !== "zip") throw new ToolInputError({ message: "source.kind must be 'folder' or 'zip'." });
  validateInstallLocation({ source, kind, sourcePath, attachmentRef });
  if (input.replace !== undefined && typeof input.replace !== "boolean") throw new ToolInputError({ message: "replace must be a boolean." });
  return { kind, ...(typeof sourcePath === "string" ? { path: sourcePath } : { attachmentRef: attachmentRef as string }), replace: input.replace === true };
}

/** Bound reads BEFORE allocation; never interpret an opaque attachment id as a filesystem path. */
export async function readPluginInstallArchive(
  required: { request: PluginInstallRequest; ownerId: string; runId: string; maxBytes: number },
  optional: { readAttachment?: InstallAttachmentReader; files?: InstallArchiveFiles } = {},
): Promise<Uint8Array> {
  const { request, ownerId, runId, maxBytes } = required;
  if (request.attachmentRef) {
    const result = await optional.readAttachment?.({ ref: request.attachmentRef, ownerId, runId }, { maxBytes });
    if (!result?.ok) throw new ToolInputError({ message: "Chat ZIP attachment is unavailable or exceeds the 32 MiB upload limit. Use an attachmentRef listed by chat_list_pending_attachments." });
    requireArchiveSize({ size: result.bytes.byteLength, maxBytes });
    return result.bytes;
  }
  const sourcePath = request.path!;
  const files = optional.files ?? nodeArchiveFiles;
  let size: number;
  try { size = (await files.stat({ path: sourcePath })).size; } catch { throw new ToolInputError({ message: `No readable ZIP at ${sourcePath}.` }); }
  requireArchiveSize({ size, maxBytes });
  const bytes = await files.read({ path: sourcePath });
  // Re-check in case the local file grew between stat and read.
  requireArchiveSize({ size: bytes.byteLength, maxBytes });
  return bytes;
}

function validateInstallLocation(
  { source, kind, sourcePath, attachmentRef }: { source: Record<string, unknown>; kind: "folder" | "zip"; sourcePath: unknown; attachmentRef: unknown },
  _optional: Record<string, never> = {},
): void {
  if (Object.hasOwn(source, "path") === Object.hasOwn(source, "attachmentRef")) throw new ToolInputError({ message: "Exactly one of source.path/source.attachmentRef is required." });
  if (Object.hasOwn(source, "attachmentRef")) {
    if (kind !== "zip" || typeof attachmentRef !== "string" || !CHAT_ATTACHMENT_REF_PATTERN.test(attachmentRef)) throw new ToolInputError({ message: "source.attachmentRef must be an attachment:<uuid> ZIP reference." });
  } else if (typeof sourcePath !== "string" || !path.isAbsolute(sourcePath)) throw new ToolInputError({ message: "source.path must be an absolute path on the machine Tovu runs on (expand ~ first)." });
}

function requireArchiveSize({ size, maxBytes }: { size: number; maxBytes: number }, _optional: Record<string, never> = {}): void {
  if (size > maxBytes) throw new ToolInputError({ message: "ZIP exceeds the 32 MiB upload limit." });
}

import { probeCredentialConnection } from "../custom-credentials/credentialed-request.js";
import { findPluginCredentialCard, type PluginCredentialCard, type LoadPluginCredentialCards } from "../custom-credentials/plugin-credential-card.js";
import { CREDENTIAL_SAVE_TOOL_ID } from "../../contracts/headless/secret-form-cards.js";
import { credentialText, translateCredentialMessage } from '../../contracts/core/credential-copy.js';
import { resolveOperatorLocale, type OperatorLocaleDeps } from './operator-locale.js';
import { assertCredentialToken, CredentialInputError } from '../../contracts/core/credential-token.js';
import { adaptLegacyAuthorize } from "@jini-ai/cms/core";
import { requireToolPermission } from "@jini-ai/cms/core";
import { requireInputRecord, ToolInputError, type ToolExecutionOptions, type ToolExecutionContext } from "@jini-ai/core";
import { defineSecretCardTool, type SecretCardRun } from "@jini-ai/ui/mcp-ui/secret-card";

import { askThenReport, type AssistantSurfaceDeps } from "@jini-ai/daemon/surface-exchanges";
import type { HttpClientPort } from "../../platform/http/index.js";
import {
  ExternalMcpSecretStoreUnconfiguredError,
  ExternalMcpValidationError,
  saveExternalMcpServer,
  type ExternalMcpServerRecord,
} from "#src/assistant/index";

import { buildAgentPluginAccessTokenForm, buildAgentPluginAccessTokenOutcome } from "./connect-card-ui.js";
import { defaultResolveInstalledAgentPlugin, titleCaseFromPluginId, type AgentPluginConnectToolDeps } from "./connect-tool.js";
import { deriveAgentPluginConnectionId, provisionAgentPluginMcpServers } from "./federate-mcp.js";
import type { AgentPluginTokenAuth } from "@jini-ai/agent-plugins/lifecycle";
import type { RemoteMcpServerConfig } from "./mcp-metadata.js";
import { describeSavedTokenSwitch, switchOnSavedTokenConnection, type SwitchOnSavedTokenDeps } from "./switch-on-saved-token.js";

/**
 * @file `agent_plugin_set_access_token` — the generic access-token fallback for an Agent Plugin whose
 * remote server declares `tovuTokenAuth { helpUrl, probeUrl }` in its `mcp.json` (`manifest.ts`).
 * Used when `agent_plugin_connect`'s sign-in cannot start.
 *
 * Moved here on 2026-09-29 from `features/supabase-connect/` (SPEC-052's `supabase_set_access_token`),
 * so no vendor code is left in core: the tokens page and the probe URL now come from the plugin.
 *
 * A Jini secret-card spec with domain copy from `connect-card-ui.ts`; the submitted token is probed with one GET to the declared
 * `probeUrl` (401/403 = refused for this purpose), then saved as the plugin row's sealed `static_env` access token
 * through `saveExternalMcpServer`. The store sends that token to the hosted server as
 * `Authorization: Bearer`, and switching the row's auth mode replaces any unfinished OAuth attempt on
 * it. The save itself carries `enabled` and the tool lists forward; then `switch-on-saved-token.ts`
 * switches the plugin on with its declared default tools, exactly as a first sign-in does, unless an
 * operator deliberately turned it off (the result then names the screen that turns it back on).
 *
 * The tool takes only a `pluginId`: the token arrives through the form's own submission, never
 * through a model-issued call. Driven by `askThenReport`, like `custom_credential_set_token`: a second
 * send replaces the form with the real outcome once the probe and save have run. Fails closed with no
 * `emitSurface`.
 */



/** Same permission `agent_plugin_connect` restates (`connect-tool.ts`). */
const AGENT_PLUGIN_ACCESS_TOKEN_PERMISSION = "admin.integrations.manage";


/** What resolving and saving onto a plugin's token row needs — no permission check, no HTTP client.
 *  Shared with `import-access-token.ts`, which saves a token that did not come from this form. */
export type AgentPluginTokenTargetDeps = Pick<
  AgentPluginConnectToolDeps,
  "agentPluginLayout" | "workspaceId" | "clock" | "externalMcpServerRepo" | "siteAssistantSecretSealer" | "siteAssistantSecretKeyring" | "resolveInstalledPlugin"
>;

export interface AgentPluginAccessTokenToolDeps
  extends AgentPluginConnectToolDeps, OperatorLocaleDeps,
    Pick<SwitchOnSavedTokenDeps, "onConnected" | "isPluginOffByOperator" | "switchPluginOn"> {
  /** The guarded outbound client (ADR-038) whose egress policy already admits any public HTTPS host. */
  readonly customCredentialsHttpClient: HttpClientPort;
  readonly loadPluginCredentialCards?: LoadPluginCredentialCards;
}







/** Plain-language messages from SPEC-052's errors.spec.md. None ever carries a token or a vendor body. */
const MESSAGES = {
  tokenInvalid: "The server rejected this token.",
  blankToken: "The access token cannot be blank. Nothing was saved.",
  saveFailed: "The access token could not be saved. Nothing was changed.",
} as const;

type UnansweredReason = "cancelled" | "expired" | "abandoned";
type SetAccessTokenResult =
  | { saved: true; next: string }
  | { saved: false; reason: UnansweredReason | "invalid" | "refused" | "unavailable" | "error"; message?: string };

/** The one declared token-auth server this call saves onto. */
export interface TokenAuthTarget {
  readonly pluginId: string;
  readonly displayName: string;
  readonly connectionId: string;
  readonly config: RemoteMcpServerConfig & { readonly tovuTokenAuth: AgentPluginTokenAuth };
}

function hostOf(url: string | null): string | null {
  if (url === null) return null;
  try {
    return new URL(url).host;
  } catch {
    return null;
  }
}

/**
 * The plugin row, freshly read. Refused when it is missing or no longer points at the host the plugin
 * declares, so a token is never sent to a server an operator re-pointed.
 *
 * @throws {ToolInputError}
 */
export async function requireTargetRow(routeDeps: AgentPluginTokenTargetDeps, target: TokenAuthTarget): Promise<ExternalMcpServerRecord> {
  const row = await routeDeps.externalMcpServerRepo.findByServerId({ workspaceId: routeDeps.workspaceId, serverId: target.connectionId });
  if (row === null) {
    throw new ToolInputError({ message: `agent_plugin_set_access_token: '${target.pluginId}''s connection could not be set up in this Tovu version. Nothing was changed.` });
  }
  if (hostOf(row.url) !== hostOf(target.config.url)) {
    throw new ToolInputError({ message: `agent_plugin_set_access_token: the '${target.connectionId}' connection no longer points at ${target.displayName}. Nothing was changed.` });
  }
  return row;
}

/**
 * Resolves the plugin's one server declaring `tovuTokenAuth`, provisioning its row (idempotent, the
 * same call `agent_plugin_connect` makes) so a first-time fallback needs no earlier step.
 *
 * @throws {ToolInputError} Not installed; no or several token-auth servers.
 * @param optional.signal Stops provisioning when the run ends during plugin resolution.
 * @throws The signal's abort reason before provisioning when cancelled.
 */
export async function resolveTarget(routeDeps: AgentPluginTokenTargetDeps, pluginId: string, principalId: string, optional: { signal?: AbortSignal } = {}): Promise<TokenAuthTarget> {
  const resolvePlugin = routeDeps.resolveInstalledPlugin ?? ((id: string) => defaultResolveInstalledAgentPlugin({ workspaceId: routeDeps.workspaceId, pluginId: id, agentPluginLayout: routeDeps.agentPluginLayout }));
  const plugin = await resolvePlugin(pluginId);
  if (!plugin) throw new ToolInputError({ message: `agent_plugin_set_access_token: '${pluginId}' is not an installed Agent Plugin in this workspace.` });

  const declared = Object.entries(plugin.servers).flatMap(([serverKey, config]) =>
    config.type !== "stdio" && config.tovuTokenAuth ? [{ serverKey, config: config as TokenAuthTarget["config"] }] : [],
  );
  if (declared.length === 0) throw new ToolInputError({ message: `agent_plugin_set_access_token: '${pluginId}' declares no access-token sign-in.` });
  if (declared.length > 1) throw new ToolInputError({ message: `agent_plugin_set_access_token: '${pluginId}' declares more than one access-token sign-in.` });
  const [{ serverKey, config }] = declared as [(typeof declared)[number]];
  const connectionId = deriveAgentPluginConnectionId(serverKey);
  if (!connectionId) throw new ToolInputError({ message: `agent_plugin_set_access_token: '${pluginId}''s '${serverKey}' connection could not be set up in this Tovu version.` });

  optional.signal?.throwIfAborted();
  await provisionAgentPluginMcpServers(
    { repo: routeDeps.externalMcpServerRepo, sealer: routeDeps.siteAssistantSecretSealer, keyring: routeDeps.siteAssistantSecretKeyring, clock: routeDeps.clock },
    { workspaceId: routeDeps.workspaceId, pluginId, servers: plugin.servers, principalId },
  );
  return { pluginId, displayName: titleCaseFromPluginId(pluginId), connectionId, config };
}

/** Token sign-in keeps its input validation; Jini owns the GET, redirects and status classification.
 * @returns Invalid only for malformed input; HTTP 401/403 mean refused for this purpose.
 * @complexity One bounded GET; no persistence, response bodies or transport errors escape.
 */
export async function probeToken({ probeUrl, token }: { probeUrl: string; token: string }, { httpClient }: { httpClient: HttpClientPort }): Promise<"ok" | "invalid" | "refused" | "unavailable"> {
  try { assertCredentialToken({ value: token, field: 'token' }); }
  catch { return "invalid"; }
  return probeCredentialConnection({ connection: { token }, url: probeUrl, schemes: [] }, { httpClient });
}

function joinStoredList(raw: string | null): string {
  const parsed: unknown = raw === null ? [] : JSON.parse(raw);
  return Array.isArray(parsed) ? parsed.filter((name): name is string => typeof name === "string").join(",") : "";
}

/**
 * Seals `token` onto the freshly re-read row as its `static_env` access token, carrying every
 * operator-set field forward unchanged. Re-read at write time because the human may sit on the form
 * while the operator edits the allowlists.
 * @param optional.signal Stops the write when the run ends during the fresh row read.
 * @throws The signal's abort reason before saving when cancelled.
 */
export async function saveStaticAccessToken(routeDeps: AgentPluginTokenTargetDeps, target: TokenAuthTarget, principalId: string, token: string, optional: { signal?: AbortSignal } = {}): Promise<void> {
  const row = await requireTargetRow(routeDeps, target);
  // A row read or probe may finish after the run ends; never start a credential write then.
  optional.signal?.throwIfAborted();
  await saveExternalMcpServer(
    { repo: routeDeps.externalMcpServerRepo, sealer: routeDeps.siteAssistantSecretSealer, keyring: routeDeps.siteAssistantSecretKeyring, clock: routeDeps.clock },
    {
      workspaceId: routeDeps.workspaceId,
      serverId: row.serverId,
      ...(row.label !== null ? { label: row.label } : {}),
      transport: "streamable_http",
      authMode: "static_env",
      enabled: row.enabled,
      command: "",
      url: row.url ?? target.config.url,
      args: "",
      allowedToolNames: joinStoredList(row.allowedToolNames),
      writeAllowedToolNames: joinStoredList(row.writeAllowedToolNames),
      accessToken: token,
      principalId,
    },
  );
}

/** Only the store's known validation/unconfigured errors are shown. Sealing failures can quote
 * plaintext, so unconfigured storage gets fixed copy; the engine redacts allowlisted messages. */
function describeSaveError(err: unknown): string {
  if (err instanceof ExternalMcpSecretStoreUnconfiguredError) return credentialText({ id: "storage", locale: "en" });
  const known = err instanceof ExternalMcpValidationError || err instanceof ToolInputError;
  return known ? (err as Error).message : MESSAGES.saveFailed;
}

/**
 * The form's answer: probe, then seal. The token lives only in a local for the width of this function
 * and is never returned, logged, or put in an outcome.
 *
 * @complexity O(1) plus one outbound GET and one store save.
 */
async function saveSubmittedAccessToken(
  { values, routeDeps, target, principalId, locale, signal, credentialCard }: {
    values: Readonly<Record<string, unknown>>; routeDeps: AgentPluginAccessTokenToolDeps;
    target: TokenAuthTarget; principalId: string; locale: string; signal: AbortSignal; credentialCard?: PluginCredentialCard;
  }, _optional = {},
): Promise<SetAccessTokenResult> {
  const submitted = values.token;
  try { assertCredentialToken({ value: submitted, field: 'token' }); }
  catch (err) { if (err instanceof CredentialInputError) return { saved: false, reason: 'invalid', message: credentialText({ id: err.rule, locale }) }; throw err; }

  const token = (submitted as string).trim();
  const probe = await probeToken({ probeUrl: target.config.tovuTokenAuth.probeUrl, token }, { httpClient: routeDeps.customCredentialsHttpClient });
  signal.throwIfAborted();
  if (probe === "invalid") return { saved: false, reason: "invalid", message: translateCredentialMessage({ message: MESSAGES.tokenInvalid, locale }) };
  if (probe === "refused") return { saved: false, reason: "refused", message: `This token was refused for this purpose.${credentialCard?.keyHint ? ` This card needs: ${credentialCard.keyHint}` : ''}` };
  if (probe === "unavailable") return { saved: false, reason: "unavailable", message: `${target.displayName} is unavailable right now. Try again shortly.` };
  await saveStaticAccessToken(routeDeps, target, principalId, token, { signal });
  let next: string;
  try {
    next = describeSavedTokenSwitch(await switchOnSavedTokenConnection(routeDeps, target), target);
  } catch {
    // The token is saved; only switching on failed. The next save or sign-in retries it.
    next = `Token saved, but ${target.displayName} could not be switched on automatically. Save the token again to retry.`;
  }
  return { saved: true, next };
}

/** Preserve the catalog's result contract while Jini owns answer classification and error redaction. */
function accessTokenResult({ run, locale }: { run: SecretCardRun<SetAccessTokenResult>; locale: string }, _optional = {}): SetAccessTokenResult {
  if (run.status === "saved") return run.saved;
  if (run.status === "blank") return { saved: false, reason: "invalid", message: credentialText({ id: "blank", locale }) };
  if (run.status === "failed") return { saved: false, reason: "error", message: run.safeMessage };
  return { saved: false, reason: run.status };
}

/**
 * Runs `agent_plugin_set_access_token` end to end: permission, resolve, form, probe, save.
 *
 * @throws {ToolInputError} Extra input, unknown plugin, no token-auth server, or a re-pointed row.
 * @throws {ToolInputError} No `emitSurface` on this execution context.
 */
// -> one outbound GET to the declared probeUrl, then saveExternalMcpServer: a sealed write, via the human's form.
export async function saveAgentPluginToken(
  { routeDeps, surfaces, ctx }: { routeDeps: AgentPluginAccessTokenToolDeps; surfaces: AssistantSurfaceDeps; ctx: ToolExecutionContext },
  optional: ToolExecutionOptions = {},
): Promise<SetAccessTokenResult> {
  const input = requireInputRecord({ input: ctx.input });
  const card = defineSecretCardTool<{ target: TokenAuthTarget; principalId: string; locale: string; credentialCard?: PluginCredentialCard }, SetAccessTokenResult, SetAccessTokenResult>({
    toolId: CREDENTIAL_SAVE_TOOL_ID,
    prepare: async ({ ctx }) => {
      if (Object.keys(input).some((key) => key !== "pluginId")) {
        throw new ToolInputError({ message: `agent_plugin_set_access_token takes only a pluginId. The token is pasted into the form, never passed here.` });
      }
      const pluginId = input.pluginId;
      if (typeof pluginId !== "string" || pluginId.trim() === "") throw new ToolInputError({ message: `agent_plugin_set_access_token: pluginId is required.` });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: AGENT_PLUGIN_ACCESS_TOKEN_PERMISSION }, { entityType: "agent-plugin", entityId: pluginId });
      // Resolution provisions a missing plugin row; an ended run must not start that effect.
      ctx.signal.throwIfAborted();
      const target = await resolveTarget(routeDeps, pluginId, ctx.principal.id, { signal: ctx.signal });
      await requireTargetRow(routeDeps, target);
      const locale = await resolveOperatorLocale({ deps: routeDeps, workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id });
      const credentialCard = await findPluginCredentialCard({ loadCards: routeDeps.loadPluginCredentialCards, workspaceId: routeDeps.workspaceId, saveKind: "agent-plugin-token", target: pluginId });
      return { target, principalId: ctx.principal.id, locale, credentialCard };
    },
    form: ({ prep }) => buildAgentPluginAccessTokenForm({ pluginDisplayName: prep.target.displayName, helpUrl: prep.target.config.tovuTokenAuth.helpUrl, credentialCard: prep.credentialCard }),
    save: ({ values, prep, signal }) => saveSubmittedAccessToken({ values, routeDeps, ...prep, signal }),
    result: ({ prep, run }) => accessTokenResult({ run, locale: prep.locale }),
    outcome: ({ prep, run }) => {
      const result = accessTokenResult({ run, locale: prep.locale });
      if (!result.saved && result.message === undefined) return undefined;
      return buildAgentPluginAccessTokenOutcome({
        pluginDisplayName: prep.target.displayName, state: result.saved ? "success" : "failure",
        title: result.saved ? "Token saved" : "Token not saved", message: result.saved ? result.next : result.message!,
      });
    },
  }, { uriHost: "tovu", frameSize: ["100%", "380px"], safeError: describeSaveError, text: { saveFailure: MESSAGES.saveFailed } });
  return card.handler({ surfaceExchanges: surfaces.surfaceExchanges, askThenReport })(ctx, optional);
}

import { AdminSurfaceActionError, type AdminSurfaceDeliveryBinding, type AdminSurfaceDeliveryBindingDraft, type AdminSurfaceDeliveryBindings } from "@jini-ai/agent-plugins/admin-surfaces";
import type { FormDeliveryBinding } from "@jini-ai/cms/forms";
import { ValueValidationFailedError } from "@jini-ai/core/settings";
import { deriveApiConnectionKey } from "@jini-ai/integrations/api-connections";

import { FormDeliveryBindingsConflictError } from "#src/features/settings/index";

/**
 * @file Tovu's `deliveryBindings` port for plugin admin-surface handlers (Jini's
 * `AdminSurfaceDeliveryBindings`): a plugin's destination screen lists, saves and removes the
 * site's form-delivery bindings for the adapters THIS plugin contributes, so an admin no longer
 * copies a destination's config by hand.
 *
 * Why the host re-checks what Jini's session already checked: the session knows only the surface's
 * declared adapter and connection ids; only the host knows which adapters the calling plugin really
 * contributes (`tovu-form-destinations.json`) and which connections it declares in this workspace.
 * And the session's ownership check is a separate `list` before the `save`/`remove`, so ownership is
 * re-read here inside the write itself (another writer may have changed the setting in between).
 *
 * Bindings are written through the forms build's binding owner (`core.forms/deliveryBindings`, via
 * the settings chokepoint), with the signed-in admin as the caller: the same validation and the same
 * `settings.workspace.write` authorization every other writer gets. No second store. The plugin
 * sees its own connection id, never the stored connection ref, and names forms by slug (the only
 * form identity a destination ever receives: the frozen job carries `form.slug`); the stored binding
 * keeps the forms' row ids, which is what delivery planning matches.
 */

/** Read and write of the site's `core.forms/deliveryBindings` list (the forms build owns both). */
export interface FormDeliveryBindingsStore {
  read(required: { readonly workspaceId: string }): Promise<readonly FormDeliveryBinding[]>;
  /** Atomically refuses a stale expectedValue with FormDeliveryBindingsConflictError. */
  write(required: { readonly workspaceId: string; readonly callerPrincipalId: string; readonly value: readonly FormDeliveryBinding[]; readonly expectedValue: readonly FormDeliveryBinding[] }): Promise<void>;
}

export interface SurfaceDeliveryBindingsDeps {
  /** The one workspace this site serves; any other scope owns nothing here. */
  readonly siteWorkspaceId: string;
  /** Connection ids the plugin declares in this workspace (active plugins only). */
  readonly declaredConnectionIds: (required: { readonly pluginId: string }) => Promise<readonly string[]>;
  /** Form-destination adapter ids the plugin contributes in the workspace (active plugins only). */
  readonly contributedAdapterIds: (required: { readonly workspaceId: string; readonly pluginId: string }) => Promise<readonly string[]>;
  readonly forms: { list(required: { readonly workspaceId: string }): Promise<readonly { readonly id: string; readonly slug: string }[]> };
  readonly bindings: FormDeliveryBindingsStore;
  readonly newBindingId: () => string;
}

/** What one call knows about ownership, read fresh per call. */
interface Ownership {
  readonly all: readonly FormDeliveryBinding[];
  readonly adapterIds: ReadonlySet<string>;
  readonly refByConnectionId: ReadonlyMap<string, string>;
  readonly connectionIdByRef: ReadonlyMap<string, string>;
  readonly slugByFormId: ReadonlyMap<string, string>;
  readonly formIdBySlug: ReadonlyMap<string, string>;
}

const NOTHING_OWNED: Ownership = { all: [], adapterIds: new Set(), refByConnectionId: new Map(), connectionIdByRef: new Map(), slugByFormId: new Map(), formIdBySlug: new Map() };

/** Names in messages come from plugin code: cut them so a message stays a message. */
const named = (value: string) => JSON.stringify(value.slice(0, 64));

function refusal(code: string, message: string): AdminSurfaceActionError {
  return new AdminSurfaceActionError({ code, message });
}

/**
 * This plugin's stored bindings: the adapter is one the plugin contributes and the ref one of the
 * plugin's connections (a binding the plugin cannot name by connection id is not its to manage).
 * @complexity O(b).
 */
function ownEntries(ownership: Ownership): { readonly binding: FormDeliveryBinding; readonly index: number; readonly connectionId: string }[] {
  return ownership.all.flatMap((binding, index) => {
    const connectionId = ownership.adapterIds.has(binding.adapterId) ? ownership.connectionIdByRef.get(binding.connectionRef) : undefined;
    return connectionId === undefined ? [] : [{ binding, index, connectionId }];
  });
}

/**
 * The surface's view of a stored binding: connection id instead of ref, slugs instead of form ids
 * (an id whose form is gone is left out).
 * @complexity O(f) form ids.
 */
function toView(ownership: Ownership, binding: FormDeliveryBinding, connectionId: string): AdminSurfaceDeliveryBinding {
  // A stored binding without `formIds` delivers every form (the forms build's meaning); the port
  // states that explicitly, so the plugin never has to infer it from a missing field.
  const forms = binding.formIds === undefined ? { allForms: true as const } : { formIds: binding.formIds.flatMap((formId) => ownership.slugByFormId.get(formId) ?? []) };
  return {
    bindingId: binding.bindingId, adapterId: binding.adapterId, connectionId,
    enabled: binding.enabled, ...forms,
    // Stored config passed the binding owner's JSON validation and Jini's plain-JSON check on save.
    config: binding.config as AdminSurfaceDeliveryBinding["config"],
  };
}

/** Slugs → this site's form row ids. @throws AdminSurfaceActionError `form-not-found`. @complexity O(f). */
function storedFormIds(ownership: Ownership, slugs: readonly string[]): string[] {
  return slugs.map((slug) => {
    const formId = ownership.formIdBySlug.get(slug);
    if (formId === undefined) throw refusal("form-not-found", `No form with the short name ${named(slug)} exists on this site. Check the form's short name and save again.`);
    return formId;
  });
}

/**
 * The binding to store for a draft the plugin owns.
 * @throws AdminSurfaceActionError `adapter-not-owned`, `connection-not-declared` or `form-not-found`.
 * @complexity O(f) form ids.
 */
function toStored(ownership: Ownership, draft: AdminSurfaceDeliveryBindingDraft, bindingId: string): FormDeliveryBinding {
  if (!ownership.adapterIds.has(draft.adapterId)) throw refusal("adapter-not-owned", `This plugin does not provide the delivery adapter ${named(draft.adapterId)} here, so it cannot save its bindings.`);
  const connectionRef = ownership.refByConnectionId.get(draft.connectionId);
  if (connectionRef === undefined) throw refusal("connection-not-declared", `This plugin has no connection ${named(draft.connectionId)} here. Reopen the plugin's settings from this site's admin and retry.`);
  return {
    bindingId, adapterId: draft.adapterId, connectionRef, enabled: draft.enabled,
    // `allForms: true` is stored as no `formIds`, which the forms build reads as every form.
    ...(draft.allForms === true ? {} : { formIds: storedFormIds(ownership, draft.formIds) }),
    config: { ...draft.config },
  };
}

/**
 * `stored` keeping the form ids of `previous` this site's form list does not show (a trashed form):
 * the plugin only ever saw the visible slugs, so a re-save must not drop a form that comes back.
 * @complexity O(f) form ids.
 */
function keepHiddenFormIds(ownership: Ownership, stored: FormDeliveryBinding, previous: FormDeliveryBinding | undefined): FormDeliveryBinding {
  if (stored.formIds === undefined || previous?.formIds === undefined) return stored;
  const hidden = previous.formIds.filter((formId) => !ownership.slugByFormId.has(formId) && !stored.formIds!.includes(formId));
  return hidden.length === 0 ? stored : { ...stored, formIds: [...stored.formIds, ...hidden] };
}

/** The index of one of this plugin's stored bindings. @throws AdminSurfaceActionError `binding-not-found`. @complexity O(b). */
function ownIndex(ownership: Ownership, bindingId: string): number {
  const own = ownEntries(ownership).find((entry) => entry.binding.bindingId === bindingId);
  if (own === undefined) throw refusal("binding-not-found", `No delivery binding ${named(bindingId)} belongs to this plugin here. List the bindings again and retry.`);
  return own.index;
}

/**
 * Builds the per-call port for one plugin, workspace and signed-in admin.
 * @param required.principalId - The admin the route authenticated; every call is refused without one,
 *   and every write is authorized for this principal by the settings chokepoint.
 * @complexity Each call: one bindings read, one connection and one adapter listing, one forms list,
 *   then O(b + f); `save` and `remove` add one guarded settings write and retry once on conflict.
 */
export function createSurfaceDeliveryBindings(
  required: SurfaceDeliveryBindingsDeps & { readonly pluginId: string; readonly workspaceId: string; readonly principalId?: string | undefined },
  _optional: Record<string, never> = {},
): AdminSurfaceDeliveryBindings {
  const { pluginId, workspaceId, principalId } = required;

  function admin(): string {
    if (principalId === undefined) throw refusal("admin-required", "Delivery settings need a signed-in admin. Open the plugin's settings from this site's admin and retry.");
    return principalId;
  }

  /** @complexity O(b + c + a + forms), four reads in parallel. */
  async function ownership(): Promise<Ownership> {
    if (workspaceId !== required.siteWorkspaceId) return NOTHING_OWNED;
    const [all, adapterIds, connectionIds, forms] = await Promise.all([
      required.bindings.read({ workspaceId }), required.contributedAdapterIds({ workspaceId, pluginId }),
      required.declaredConnectionIds({ pluginId }), required.forms.list({ workspaceId }),
    ]);
    const refs = connectionIds.map((connectionId) => [connectionId, deriveApiConnectionKey({ workspaceId, pluginId, connectionId })] as const);
    return {
      all, adapterIds: new Set(adapterIds),
      refByConnectionId: new Map(refs), connectionIdByRef: new Map(refs.map(([connectionId, ref]) => [ref, connectionId])),
      slugByFormId: new Map(forms.map((form) => [form.id, form.slug])), formIdBySlug: new Map(forms.map((form) => [form.slug, form.id])),
    };
  }

  /**
   * Merges against fresh ownership and writes through the binding owner; one conflict retries the
   * whole ownership check, so a concurrent removal or ownership change cannot be undone.
   * Validation keeps its people-facing message; a second conflict asks the panel to refresh.
   * @complexity At most two ownership reads and guarded writes; O(b + f) merge time/space per try.
   */
  async function update<T>(
    input: { callerPrincipalId: string; merge: (owned: Ownership) => { value: readonly FormDeliveryBinding[]; result: T } },
    optional: { retry?: boolean } = {},
  ): Promise<T> {
    const owned = await ownership();
    const { value, result } = input.merge(owned);
    try {
      await required.bindings.write({ workspaceId, callerPrincipalId: input.callerPrincipalId, value, expectedValue: owned.all });
      return result;
    } catch (error) {
      if (error instanceof FormDeliveryBindingsConflictError) {
        if (optional.retry !== false) return update(input, { retry: false });
        throw new AdminSurfaceActionError({ code: "delivery-binding-conflict", message: "Delivery settings changed in another panel. List the bindings again and retry your change." }, { cause: error });
      }
      if (!(error instanceof ValueValidationFailedError)) throw error;
      throw new AdminSurfaceActionError({ code: "delivery-binding-invalid", message: error.message }, { cause: error });
    }
  }

  return {
    async list() {
      admin();
      const owned = await ownership();
      return ownEntries(owned).map((entry) => toView(owned, entry.binding, entry.connectionId));
    },
    async save(draft) {
      const callerPrincipalId = admin();
      const bindingId = draft.bindingId ?? required.newBindingId();
      return update({ callerPrincipalId, merge: (owned) => {
        const replaced = draft.bindingId === undefined ? owned.all.length : ownIndex(owned, draft.bindingId);
        const stored = keepHiddenFormIds(owned, toStored(owned, draft, bindingId), owned.all[replaced]);
        return { value: [...owned.all.slice(0, replaced), stored, ...owned.all.slice(replaced + 1)], result: toView(owned, stored, draft.connectionId) };
      } });
    },
    async remove({ bindingId }) {
      const callerPrincipalId = admin();
      return update({ callerPrincipalId, merge: (owned) => {
        const index = ownIndex(owned, bindingId);
        return { value: owned.all.filter((_binding, at) => at !== index), result: undefined };
      } });
    },
  };
}

import { nowIso as clockNowIso } from "@jini-ai/core/primitives";
import type { ExternalMcpServerRecord, ExternalMcpServerRepoPort, ExternalMcpStoreDeps } from "#src/assistant/index";

import { deriveAgentPluginConnectionId } from "./federate-mcp.js";
import { listInstalledAgentPluginServers, type InstalledAgentPluginServers, type TokenImportLog } from "./import-access-token.js";

/**
 * @file Carries saved tool selections across a vendor's tool rename, so an operator never has to
 * re-tick a tool the server now offers under a new name.
 *
 * A plugin's `mcp.json` declares the rename on the server entry (`tovuRenamedTools: { "get_logs":
 * "query_logs" }`, parsed by `manifest.ts`). At boot, every row that plugin provisioned has each old
 * name in `allowedToolNames` and `writeAllowedToolNames` replaced by the new one. Added 2026-09-29
 * when Supabase renamed `get_logs` to `query_logs` and the saved dev row kept asking for a tool the
 * server no longer offers.
 *
 * Applied only to a row that names this plugin as its provisioner AND sits at the url the plugin
 * declares — the same match `apply-connect-defaults.ts` uses — so an operator's own row, or one
 * pointed elsewhere, is never touched.
 *
 * Never widens access: a new name takes exactly the grants its old name had (read stays read, write
 * stays write), and a rename whose old name is not in a list adds nothing to that list. Idempotent:
 * once rewritten, the old names are gone and later boots write nothing. Reversible: declaring the
 * opposite rename puts the old names back.
 */

/** Recorded as the row's write-grant attribution when a rename changes its write list. */
const TOOL_RENAMES_ACTOR = "system:tool-renames";

export interface ApplyAgentPluginToolRenamesDeps {
  readonly workspaceId: string;
  readonly agentPluginLayout: import("./layout.js").AgentPluginLayout;
  readonly externalMcpServerRepo: ExternalMcpServerRepoPort;
  readonly clock: ExternalMcpStoreDeps["clock"];
  /** Injected for tests. Defaults to `import-access-token.ts`'s `listInstalledAgentPluginServers`. */
  readonly listPlugins?: () => Promise<readonly InstalledAgentPluginServers[]>;
  /** Announces a changed roster so live runtimes reload — the composition root passes
   *  `notifyExternalMcpRosterChanged`. A port rather than a value import: a feature module may not
   *  value-import `#src/assistant/` (`domain-no-direct-tool-registration.boundary.test.ts`). */
  readonly notifyRosterChanged: () => Promise<void>;
}

/** A stored JSON tool list as names, or `null` when it is not a JSON array of strings (left alone). */
function readToolList(raw: string | null): string[] | null {
  if (!raw) return [];
  try {
    const parsed: unknown = JSON.parse(raw);
    return Array.isArray(parsed) && parsed.every((name): name is string => typeof name === "string") ? parsed : null;
  } catch {
    return null;
  }
}

/**
 * `names` with every renamed entry replaced, order kept, duplicates dropped — or `null` when
 * nothing in it was renamed.
 * @complexity O(n) in the list length.
 */
export function renameToolNames(names: readonly string[], renames: Readonly<Record<string, string>>): string[] | null {
  if (!names.some((name) => Object.hasOwn(renames, name))) return null;
  return [...new Set(names.map((name) => (Object.hasOwn(renames, name) ? renames[name]! : name)))];
}

/** The matching provisioned row with its two tool lists renamed, or `null` when neither list
 * changed (or either is unreadable). */
function renameRowTools(
  input: {
    readonly row: ExternalMcpServerRecord;
    readonly renames: Readonly<Record<string, string>>;
    readonly clock: ExternalMcpStoreDeps["clock"];
    readonly pluginId: string;
    readonly url: string;
  },
  _options = {},
): ExternalMcpServerRecord | null {
  const { row, renames, clock, pluginId, url } = input;
  if (row.provisionedByPluginId !== pluginId || row.url !== url) return null;
  const nowIso = clockNowIso({ clock });
  const allow = readToolList(row.allowedToolNames);
  const write = readToolList(row.writeAllowedToolNames);
  if (allow === null || write === null) return null;
  const renamedAllow = renameToolNames(allow, renames);
  const renamedWrite = renameToolNames(write, renames);
  if (renamedAllow === null && renamedWrite === null) return null;
  return {
    ...row,
    ...(renamedAllow === null ? {} : { allowedToolNames: JSON.stringify(renamedAllow) }),
    ...(renamedWrite === null
      ? {}
      : { writeAllowedToolNames: JSON.stringify(renamedWrite), writeGrantsUpdatedByPrincipalId: TOOL_RENAMES_ACTOR, writeGrantsUpdatedAt: nowIso }),
    updatedAt: nowIso,
  };
}

/** Applies one declaration only to its provisioned row at the declared endpoint. */
async function applyServerToolRenames(
  input: {
    readonly deps: ApplyAgentPluginToolRenamesDeps;
    readonly pluginId: string;
    readonly serverKey: string;
    readonly config: import("./mcp-metadata.js").McpServerConfig;
    readonly log: TokenImportLog;
  },
  _options = {},
): Promise<boolean> {
  const { deps, pluginId, serverKey, config, log } = input;
  if (config.type === "stdio" || !config.tovuRenamedTools) return false;
  const serverId = deriveAgentPluginConnectionId(serverKey);
  if (serverId === null) return false;
  let changed = false;
  try {
    const row = await deps.externalMcpServerRepo.findByServerId({ workspaceId: deps.workspaceId, serverId });
    if (!row) return false;
    const renamed = renameRowTools({ row, renames: config.tovuRenamedTools, clock: deps.clock, pluginId, url: config.url });
    if (!renamed) return false;
    await deps.externalMcpServerRepo.upsert(renamed);
    changed = true;
    log.info(`[agent-plugins] '${serverId}': renamed saved tools to follow the '${pluginId}' plugin (${Object.entries(config.tovuRenamedTools).map(([from, to]) => `${from} -> ${to}`).join(", ")}).`);
    return true;
  } catch (err) {
    log.warn(`[agent-plugins] could not apply the '${pluginId}' plugin's tool renames to '${serverId}': ${err instanceof Error ? err.message : String(err)}`);
  }
  return changed;
}

/**
 * Boot: rewrites renamed tool names on every row an installed plugin provisioned. Logs each rewrite
 * once (the next boot finds nothing to do) and notifies the roster when any row changed. Never
 * throws: a failure is a warning and the next boot tries again.
 *
 * @complexity O(p·s) over installed plugins and their servers, plus one row read per declared rename
 * and at most one write per row.
 */
export async function applyAgentPluginToolRenames(deps: ApplyAgentPluginToolRenamesDeps, log: TokenImportLog): Promise<void> {
  let plugins: readonly InstalledAgentPluginServers[];
  try {
    plugins = await (deps.listPlugins ?? (() => listInstalledAgentPluginServers(deps)))();
  } catch (err) {
    log.warn(`[agent-plugins] could not list plugins to apply tool renames: ${err instanceof Error ? err.message : String(err)}`);
    return;
  }

  let changed = false;
  for (const { pluginId, servers } of plugins) {
    for (const [serverKey, config] of Object.entries(servers)) {
      if (await applyServerToolRenames({ deps, pluginId, serverKey, config, log })) changed = true;
    }
  }
  if (changed) await deps.notifyRosterChanged();
}

/**
 * @file Projects executable Agent Plugin tools (`tovu-agent-tools.json` + `.mjs` modules, admitted
 * by `@jini-ai/agent-plugins/lifecycle/tools`) onto the assistant's ToolRegistry.
 *
 * Reuses, in order: the lifecycle's trusted contribution loader (active plugin, bundled digest,
 * contained module path), Jini's tool projection (schema validation, revocable per-call
 * capabilities, affected-resource disclosure), the plugin tool contract's registration builder
 * (`p_<plugin>__<tool>` ids, enablement + authorization recheck before the handler), a core
 * registration scope (replaced when the plugin set changes), and Tovu's approval owner.
 *
 * Two Tovu-specific adjustments, both explained where they happen: the contract's
 * `requiresConfirmation` flag is replaced by the approval owner's card (this host has no executor
 * confirmation transport, so that flag would park the call forever), and confirming tools carry no
 * executor deadline (the deadline would expire while the human reads the card, as for native tools).
 */
import { createToolRegistrationScope, type ToolExecutionContext, type ToolAuthorizationContext, type ToolRegistration, type ToolRegistry } from '@jini-ai/core';
import { adaptLegacyAuthorize, requireToolPermission } from '@jini-ai/cms/core';
import { buildPluginContributionToolRegistrations, createPluginContributionRegistry, pluginToolIdFor } from '@jini-ai/plugins/host';
import { createAgentPluginToolProjection, defineAgentPluginToolContribution, type AgentPluginToolEffect, type IssuedTokenMemories, type LoadedAgentPluginTool } from '@jini-ai/agent-plugins/lifecycle/tools';
import { buildAdminSurfaceActionTools } from '@jini-ai/agent-plugins/admin-surfaces';
import { deriveApiConnectionKey } from '@jini-ai/integrations/api-connections';
import { ADMIN_SURFACE_ACTION_PERMISSION, withAdminSurfaceSignIns, type AdminSurfaceSource } from '../admin-surfaces/surfaces.js';
import type { AgentPluginAdminSurfaceHandlers } from '../admin-surfaces/handlers.js';
import type { SurfaceDetail } from '@jini-ai/ui/mcp-ui/surfaces';
import type { HttpClientPort } from '@jini-ai/core/primitives';
import { EXTENSION_TOOL_APPROVAL_POLICY, withExtensionApprovalPolicy } from '../../../contracts/headless/assistant-tool-approval-policy.js';
import type { AuthorizeFn } from '../../../contracts/core/commands/index.js';
import { APPROVAL_FAMILY_BY_EFFECT, createAgentPluginDisclosure } from './approval.js';
import {
  createAgentPluginToolCapabilities, createFrozenConnectionAccounts,
  type AgentPluginArtifactWriter, type AgentPluginConnectionAccess, type FrozenConnectionAccounts, type AgentPluginRateLimiter, type AgentPluginStateReaderFor, type AgentPluginApiOriginsFor,
} from './host-capabilities.js';

/** The file a plugin ships at its package root to contribute executable tools. */
export const AGENT_PLUGIN_TOOLS_FILENAME = 'tovu-agent-tools.json';
const toolContribution = defineAgentPluginToolContribution({ filename: AGENT_PLUGIN_TOOLS_FILENAME });

/** Host ports the composition root binds once per site (see this folder's README). */
export interface AgentPluginExecutableToolHost {
  /** Same active/trusted source and handler host used by the sandboxed admin screen. */
  readonly adminSurfaces?: { readonly source: Pick<AdminSurfaceSource, 'list'>; readonly host: AgentPluginAdminSurfaceHandlers };
  /** The lifecycle's `loadPluginContributions`, narrowed to this contribution. */
  readonly loadContributions: (
    required: { readonly workspaceId: string; readonly definition: typeof toolContribution },
    optional: { readonly orderByPluginId?: boolean },
  ) => Promise<{ readonly items: readonly LoadedAgentPluginTool[]; readonly refusals: readonly string[] }>;
  readonly connections: AgentPluginConnectionAccess;
  readonly http: HttpClientPort;
  readonly limiter: AgentPluginRateLimiter;
  readonly artifacts?: AgentPluginArtifactWriter;
  /** The plugin settings reader (the store its admin surface writes); tools only read it. */
  readonly state: AgentPluginStateReaderFor;
  /** Each plugin's declared API origins: the only hosts its tools' HTTP may reach. */
  readonly apiOrigins: AgentPluginApiOriginsFor;
  /** The site's ONE token memory, shared with the admin-surface handler host: a plugin's tools and
   *  handlers share module scope, so a token either obtained must be withheld from both. */
  readonly issuedTokens: IssuedTokenMemories;
  /** The accounts confirmations freeze, shared with the admin-surface connections port so an admin
   *  action run as a tool is pinned like a tool call. Omitted, the registrar keeps its own. */
  readonly frozen?: FrozenConnectionAccounts;
}

/** Wraps one registration in the approval owner (`applyToolApprovalPolicy`, injected by the composition root). */
export type ApplyAgentPluginApproval = (
  required: { readonly registration: ToolRegistration },
  optional: { readonly disclose: (required: { readonly ctx: ToolExecutionContext }) => Promise<readonly SurfaceDetail[]> },
) => ToolRegistration;

interface ToolOwner { readonly pluginId: string; readonly effect: AgentPluginToolEffect }

/** Tool id → owning plugin and declared effect, from the contribution registry's current snapshots. @complexity O(t). */
function ownersById(contributions: ReturnType<typeof createPluginContributionRegistry>): Map<string, ToolOwner> {
  const owners = new Map<string, ToolOwner>();
  for (const snapshot of contributions.list({})) {
    for (const tool of snapshot.tools) owners.set(pluginToolIdFor({ pluginId: snapshot.pluginId, name: tool.name }), { pluginId: snapshot.pluginId, effect: tool.effect ?? 'destructive' });
  }
  return owners;
}

/**
 * Loads this workspace's executable Agent Plugin tools and keeps them registered on `registry`.
 * @param required.registry - The core ToolRegistry the assistant executes from (a registration scope needs it).
 * @param required.workspaceId - The workspace whose plugins, activation and connections apply.
 * @param required.host - Loader, connection accessor, guarded HTTP, limiter and optional artifact writer.
 * @param required.isActive - Fresh activation read for one plugin; must deny on any fault.
 * @param required.authorize - The workspace RBAC evaluator; callers need `admin.assistant.use`.
 * @param required.applyApproval - The approval owner, applied to write and destructive tools.
 * @returns Refusal lines, `refresh` to reload the active set, and `dispose` to remove every tool.
 * @complexity O(t) tools plus one contained import per tool module (cached by Node).
 */
export async function registerAgentPluginExecutableTools(
  required: {
    readonly registry: ToolRegistry; readonly workspaceId: string; readonly host: AgentPluginExecutableToolHost;
    readonly isActive: (required: { readonly pluginId: string }) => Promise<boolean>;
    readonly authorize: AuthorizeFn; readonly applyApproval: ApplyAgentPluginApproval;
  },
  _optional: Record<string, never> = {},
): Promise<{ readonly refusals: readonly string[]; refresh(): Promise<{ readonly refusals: readonly string[] }>; dispose(): void }> {
  const { registry, workspaceId, host } = required;
  const frozen = host.frozen ?? createFrozenConnectionAccounts();
  const capabilities = createAgentPluginToolCapabilities({ connections: host.connections, http: host.http, limiter: host.limiter, frozen, state: host.state, apiOrigins: host.apiOrigins }, host.artifacts ? { artifacts: host.artifacts } : {});
  const contributions = createPluginContributionRegistry({});
  const projection = createAgentPluginToolProjection({ registry: contributions, toolIdFor: pluginToolIdFor, capabilities, issuedTokens: host.issuedTokens });
  const disclose = createAgentPluginDisclosure({ source: projection, connections: host.connections, frozen });
  const authorize = adaptLegacyAuthorize({ authorize: required.authorize });
  /** One fresh trust/activation load. Each generation's closures retain its own declaration. */
  async function loadTools() {
    const load = await host.loadContributions({ workspaceId, definition: toolContribution }, { orderByPluginId: true });
    const admin = host.adminSurfaces;
    const surfaces = admin ? await admin.source.list({ workspaceId }) : [];
    if (admin) await admin.host.refresh();
    const additionalTools = admin ? buildAdminSurfaceActionTools({
      surfaces: surfaces.map(({ plugin, descriptor }) => ({ pluginId: plugin.pluginId, descriptor })),
      handlersFor: (input) => admin.host.handlersFor(input),
      authorize: async ({ context }) => {
        if (context.workspaceId !== workspaceId || !context.principalId) throw new Error('Admin surface caller is unavailable.');
        await requireToolPermission({ authorize, workspaceId, principalId: context.principalId, permission: ADMIN_SURFACE_ACTION_PERMISSION });
        // Re-read the trust gate after the human's confirmation, just as the screen action route does.
        const latest = await admin.source.list({ workspaceId });
        const original = surfaces.find(surface => surface.plugin.pluginId === context.pluginId && surface.descriptor.id === context.surfaceId);
        if (!original || !latest.some(surface => surface.plugin.pluginId === context.pluginId && surface.descriptor.id === context.surfaceId
          && JSON.stringify(surface.descriptor) === JSON.stringify(original.descriptor))) throw new Error('This admin surface is no longer available.');
        await admin.host.refresh();
      },
    }, {
      run: ({ dispatch }) => withAdminSurfaceSignIns({ host: admin.host, run: dispatch }),
      connectionRefFor: ({ pluginId, connectionId }) => deriveApiConnectionKey({ workspaceId, pluginId, connectionId }),
    }) : [];
    return { loaded: load.items, refusals: load.refusals, additionalTools };
  }
  const initial = await loadTools();
  let adminToolIds = new Set(initial.additionalTools.map(entry => pluginToolIdFor({ pluginId: entry.pluginId, name: entry.tool.name })));
  const { refusals } = projection.sync(initial);

  const ports = {
    contributions, isEnabled: required.isActive,
    resolveAuth: async ({ pluginId, principalId }: { pluginId: string; principalId: string }) => {
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: required.authorize }), workspaceId, principalId, permission: 'admin.assistant.use' }, { entityType: 'plugin', entityId: pluginId });
      return { access: 'admin' as const, principalId, workspaceId };
    },
    metadata: { approval: EXTENSION_TOOL_APPROVAL_POLICY[APPROVAL_FAMILY_BY_EFFECT.read] },
  };
  const adapt = (registration: ToolRegistration, owner: ToolOwner): ToolRegistration => {
    const toolId = registration.descriptor.id;
    // The contract asks the executor to confirm; Tovu's executor has no transport for that and would
    // park forever, so the approval owner's card below confirms instead (never less friction).
    const { requiresConfirmation: _parked, timeoutMs, ...descriptor } = registration.descriptor;
    const asks = owner.effect !== 'read';
    const gated = adminToolIds.has(toolId) ? { ...registration, policy: { ...registration.policy, authorize: async (ctx: ToolAuthorizationContext) => {
      if (await registration.policy.authorize(ctx) !== 'allow') return 'deny' as const;
      try {
        await requireToolPermission({ authorize, workspaceId, principalId: ctx.principal.id, permission: ADMIN_SURFACE_ACTION_PERMISSION });
        return 'allow' as const;
      } catch { return 'deny' as const; }
    } } } : registration;
    const classified = withExtensionApprovalPolicy({ registration: { ...gated, descriptor: { ...descriptor, readOnly: !asks, sideEffects: owner.effect === 'destructive' ? 'deletes-durable-state' : asks ? 'mutates-durable-state' : 'none', ...(asks ? {} : { timeoutMs }) } }, family: APPROVAL_FAMILY_BY_EFFECT[owner.effect] });
    // An admin action may be the one that signs a connection in, so its unconnected ones are left unbound.
    const skipUnconnected = adminToolIds.has(toolId);
    return asks ? required.applyApproval({ registration: classified }, { disclose: ({ ctx }) => disclose({ ctx, toolId, pluginId: owner.pluginId, workspaceId }, { skipUnconnected }) }) : classified;
  };
  const scope = createToolRegistrationScope({ registry });
  const refresh = () => {
    const owners = ownersById(contributions);
    scope.replace({ registrations: buildPluginContributionToolRegistrations(ports).map((registration) => {
      const owner = owners.get(registration.descriptor.id);
      // Both come from the same snapshots; refusing beats registering a tool with no approval family.
      if (!owner) throw new Error(`agent plugin tool '${registration.descriptor.id}' has no owning plugin, so its approval could not be classified`);
      return adapt(registration, owner);
    }) });
  };
  refresh();
  const unsubscribe = contributions.subscribe({ onChanged: refresh });
  let disposed = false;
  // One refresh at a time: an older load that finishes late would otherwise re-register the tools of
  // a plugin a newer load already saw disabled.
  let queue: Promise<unknown> = Promise.resolve();
  return {
    refusals,
    refresh() {
      const run = queue.then(async () => {
        const next = await loadTools();
        if (disposed) throw new Error('Plugin tool registration was disposed.');
        adminToolIds = new Set(next.additionalTools.map(entry => pluginToolIdFor({ pluginId: entry.pluginId, name: entry.tool.name })));
        return projection.sync(next);
      });
      queue = run.catch(() => undefined);
      return run;
    },
    dispose() { disposed = true; unsubscribe(); scope.replace({ registrations: [] }); },
  };
}

import {
  saveExternalMcpServer,
  type ExternalMcpServerRecord,
  type ExternalMcpStoreDeps,
} from "#src/assistant/index";
import { externalMcpRecordHasStaticAccessToken } from "../external-mcp/auth-mode.js";

import { classifyAgentPluginMcpServerTrust, readInstalledMcpServers } from "./capability-projection.js";
import type { AgentPluginLayout } from "./layout.js";
import type { AgentPluginDefaultTools } from "@jini-ai/agent-plugins/lifecycle";
import type { McpServerConfig } from "./mcp-metadata.js";
import { preferBundledAgentPluginDigests, readBundledAgentPluginDigests } from "./lifecycle.js";
import { listInstalledPlugins } from "./lifecycle.js";

/**
 * @file Phase 4 of the 2026-09-10 plugin-MCP-wiring work: PROVISIONS an activated Agent Plugin's
 * auto-admitted remote MCP servers as real rows in the SAME external-MCP store
 * (`assistant/external-mcp-store.ts`) Settings → External MCP already owns — reusing that path
 * rather than building a parallel one. A provisioned row appears in Settings → External MCP exactly
 * like an operator-typed one: the same allowlist/"may write" tool picker, the same enable toggle,
 * the same revoke button. There is no second, plugin-only registration path.
 *
 * ---------------------------------------------------------------------------
 * 2026-09-10, owner refinement — three collision rules, and why each exists
 * ---------------------------------------------------------------------------
 * A `higgsfield` row already exists on the live dev site with connected OAuth tokens, an allowlist,
 * and write grants — created by hand, by an operator following the bundled skill's old instructions,
 * before this file existed. That row is the concrete case every rule below defends:
 *
 * 1. **NEVER CLOBBER AN EXISTING ROW — ADOPT IT INSTEAD.** {@link provisionAgentPluginMcpServers}
 *    calls `deps.repo.findByServerId` BEFORE ever calling {@link saveExternalMcpServer}. A row
 *    already at the derived id is NEVER passed through {@link saveExternalMcpServer} — no field an
 *    operator or an earlier boot wrote (url, transport, auth mode, allowlist, write grants, any
 *    oauth/sealed column) is ever recomputed or overwritten here. This is why
 *    {@link deriveAgentPluginConnectionId} below no longer hashes or namespaces the id: an id
 *    genuinely equal to what an operator would have hand-typed (the plugin's own declared server
 *    key, e.g. `higgsfield`) is what lets this rule recognize the ACTUAL pre-existing row, rather
 *    than shadowing it with a second, uniquely-derived connection beside it. There is deliberately no
 *    hash-suffixed fallback id — one id, verbatim, always; a vendor's own SKILL.md documents
 *    `mcp__<serverKey>__<tool>` and cannot predict any suffix Tovu might mint, so a fallback scheme
 *    would defeat the exact "no guessing" goal this feature exists for.
 *
 *    A row already at that id splits into two cases, neither of which ever calls
 *    `saveExternalMcpServer`:
 *      - `provisionedByPluginId === input.pluginId` — this same plugin provisioned it on an earlier
 *        enable; nothing has changed. Reported {@link ProvisionAgentPluginMcpServersResult
 *        .alreadyProvisioned}.
 *      - anything else (`null`, or a DIFFERENT plugin's id) — an operator's own hand-configured
 *        connection (with its earned OAuth tokens, allowlist, and write grants), or another plugin's
 *        row. This is ADOPTION: `deps.repo.upsert({ ...existing, provisionedByPluginId: input.pluginId })`
 *        is called directly against the repo port — the raw record, spread, with only that one field
 *        changed — never `saveExternalMcpServer`, which has no way to leave every other field
 *        untouched while changing just this one (even its "tri-state" fields resolve a default the
 *        caller must supply). Reported {@link ProvisionAgentPluginMcpServersResult.adopted}. The
 *        operator's own configuration and any live tokens always outrank a package's declaration —
 *        that is this rule, applied to the id-collision case specifically.
 *      - EXCEPT a row owned by a DIFFERENT plugin whose url, transport, or auth mode DIFFERS from the
 *        declaration — a different server whose key merely normalized to the same id. Rewriting that
 *        plugin's provenance would leave calls for this plugin pointing at the other plugin's
 *        endpoint, so the collision is refused, never adopted, and reported
 *        {@link ProvisionAgentPluginMcpServersResult.failed}. Two plugins declaring the identical key
 *        AND endpoint therefore share one row (whichever enabled most recently owns
 *        `provisionedByPluginId`); two declaring the same key but different endpoints do not. An
 *        operator's row (`provisionedByPluginId === null`) is still adopted unconditionally — the
 *        operator typed the endpoint they wanted, so recording the association is not a rewrite of
 *        another plugin's provenance.
 *    KNOWN RACE: the existence check and the create/adopt are not one atomic operation (no
 *    compare-and-set primitive exists on `ExternalMcpServerRepoPort` today, unlike
 *    `tryClaimOAuthRefreshLease`'s purpose-built one). Two concurrent provisioning attempts for the
 *    SAME id are harmless — creation races write the identical disabled/empty-allowlist config, and
 *    adoption races both write the same one field. A provisioning attempt racing an operator's
 *    concurrent hand-edit of the same id is the one real gap, and it is the same class of risk any two
 *    concurrent saves to this store already have — not a new one, but also not eliminated by this
 *    file. Closing it fully needs a new repo primitive, deliberately not added here as disproportionate
 *    to this feature's scope.
 *
 * 1b. **EXCEPT A STALE ROW THIS SAME PLUGIN PROVISIONED AND NOBODY USED.** When a plugin update
 *    changes a server's url or auth mode, a row the plugin provisioned earlier is re-provisioned from
 *    the new declaration (deleted, then saved fresh) — but only while it is still exactly what
 *    provisioning left behind: never enabled, both tool lists empty. Otherwise the new url could
 *    never reach an existing site, and `apply-connect-defaults.ts` (which grants defaults only when
 *    the row's url equals the declared one) would never fire there. Any sign-in state on such a row
 *    was minted for the old endpoint and is dropped with it. A saved access token on a server that
 *    declares `tovuTokenAuth` counts as the declared auth mode, so it is only dropped when the url
 *    itself changes. A row that is enabled or has any tool
 *    granted is the operator's, and stays byte-identical as above.
 *
 * 2. **SEED DISABLED, LIKE BUNDLED PLUGINS ALREADY DO.** Mirrors `activation.ts`'s
 *    `recordBundledAgentPluginIfAbsent`: idempotent, create-if-absent, and — because rule 1 already
 *    means an existing row is never revisited — a row this file created is never re-enabled by a
 *    later boot or a later plugin toggle either. `enabled: false` is passed on the ONE
 *    {@link saveExternalMcpServer} call that creates a brand-new row; there is no code path here that
 *    ever sets `enabled: true` on any row, new or existing.
 *
 * 3. **PROVISIONING IS NOT AUTHORIZATION.** `allowedToolNames`/`writeAllowedToolNames` are always
 *    `""` on a newly created row, even though a plugin's `mcp.json`/skill content might suggest
 *    names. A downloaded marketplace package must not be able to grant itself tool access — the same
 *    trust argument Phase 3's stdio split makes, applied here to the allowlist instead of to
 *    execution. The operator ticks tools in Settings → External MCP's picker, which already lets
 *    them choose from a live, server-advertised list (`probe.ts`) rather than guessing names. The one
 *    other writer is the operator's own first sign-in, which grants the plugin's declared
 *    `tovuDefaultTools` to a still-empty row (`apply-connect-defaults.ts`) — the sign-in, not this
 *    file, is what authorizes.
 *
 * ---------------------------------------------------------------------------
 * What happens on plugin disable or uninstall: THE ROW SURVIVES
 * ---------------------------------------------------------------------------
 * Nothing in this file, and nothing this dispatch added to `set-enabled.ts` or
 * `features/agent-plugins/uninstall.ts`, ever deletes or disables a provisioned row when its plugin
 * is turned off or removed. This is a deliberate position, not an oversight: a provisioned row may
 * already hold OAuth tokens the operator earned through a real browser sign-in, and deleting an
 * external MCP connection is UNRECOVERABLE in this app (`project_external_mcp_delete_is_unrecoverable`
 * — no soft-delete, no undo). Silently destroying that on a disable/uninstall would be a strictly
 * worse failure mode than leaving an inert, disabled row behind. `provisioned_by_plugin_id`
 * (`schema.sqlite.ts`) records which plugin created a surviving row, so a FUTURE uninstall flow can offer
 * to remove it explicitly — an operator decision, never an automatic side effect of this file.
 *
 * ---------------------------------------------------------------------------
 * What this does NOT do
 * ---------------------------------------------------------------------------
 * - Never touches a `stdio` server. `classifyAgentPluginMcpServerTrust` (`capability-projection.ts`)
 *   is consulted first, and only an `"auto-admit"` (remote) server ever reaches
 *   {@link saveExternalMcpServer}. There is no code path in this file that can launch a local
 *   process on a plugin's say-so — see Phase 3's own gate for the full argument.
 * - Never completes an OAuth handshake. `authMode: "oauth"` rows still need the operator's own
 *   browser-interactive consent (Higgsfield's authorization_code + PKCE flow has no other kind) —
 *   this file only makes sure the row EXISTS with the right URL and transport so that consent step
 *   is the operator's only remaining action.
 * - Does not run at request time and makes no live network call. Only the row's own data is
 *   written. The daemon's boot-time federation read (`resolveStoredExternalMcpConnections`) is what
 *   actually connects, and per that module's own doc, requires an assistant restart to pick up a
 *   newly-provisioned (and since-enabled) row.
 *
 * ---------------------------------------------------------------------------
 * Why authMode defaults to "none", not "oauth"
 * ---------------------------------------------------------------------------
 * The real Agent Plugins v1.0.0 mcp.schema.json defines NO auth field at all (verified live,
 * 2026-09-10 — see `manifest.ts`'s header). Guessing "oauth" for every remote server would attempt
 * RFC 8414 discovery against a plugin's server even when it needs no auth at all, failing where a
 * plain connection would have worked. `"none"` is the safe default; a plugin author who KNOWS their
 * server requires OAuth (Higgsfield's own `mcp.json` does) sets the `tovuAuthMode` extension
 * (`manifest.ts`) to say so explicitly.
 */

/** `mcp-federation/trust.ts`'s `CONNECTION_ID_PATTERN` caps a connection id at 40 characters. */
const MAX_CONNECTION_ID_LENGTH = 40;

/**
 * Derives the `external_mcp_servers.serverId` one plugin-declared server maps to: its OWN declared
 * server key (the `mcp.json` object member name), sanitized into `CONNECTION_ID_PATTERN`'s
 * `[a-z0-9][a-z0-9-]{0,39}` charset — lowercased, every run of other characters collapsed to one
 * `-`, leading/trailing `-` trimmed, truncated to 40.
 *
 * Deliberately NOT namespaced by `pluginId` and NOT hash-suffixed (an earlier revision of this file
 * did both, for collision safety) — see this file's header, rule 1: the id must equal what an
 * operator would have hand-typed, because matching that exact id is what lets a pre-existing,
 * hand-configured row (e.g. `higgsfield`) be recognized and left untouched rather than shadowed by a
 * second, uniquely-derived connection beside it.
 *
 * @returns The derived id, or `null` when the server key sanitizes to nothing usable (e.g. a key
 * made entirely of characters outside `[a-z0-9-]`) — reported as a skip by
 * {@link classifyAgentPluginMcpServerForFederation}, never thrown.
 * @complexity O(n) in the server key's length.
 */
export function deriveAgentPluginConnectionId(serverKey: string): string | null {
  const sanitized = serverKey
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, MAX_CONNECTION_ID_LENGTH)
    .replace(/-+$/g, "");
  return sanitized.length > 0 ? sanitized : null;
}

/** One server this plugin declared that {@link planAgentPluginMcpFederation} will not attempt to
 *  provision, and why — reported rather than silently dropped, matching `mcp-federation/trust.ts`'s
 *  own "every refusal is reportable, never silent" discipline. */
export interface SkippedAgentPluginMcpServer {
  readonly serverKey: string;
  readonly reason: string;
}

/** One server {@link planAgentPluginMcpFederation} determined should be provisioned (subject to
 *  rule 1's existence check at apply time). Carries the derived id and the resolved config, but not
 *  yet `workspaceId`/`principalId` — those are per-CALL, not per-server. */
/** The shape of `classifyAgentPluginMcpServerTrust` (`capability-projection.ts`). */
export type AgentPluginMcpTrustClassifier = (server: Pick<McpServerConfig, "type">) => "auto-admit" | "requires-confirmation";

export interface PlannedAgentPluginMcpUpsert {
  readonly connectionId: string;
  readonly serverKey: string;
  readonly url: string;
  readonly authMode: "oauth" | "none";
  /** The server declares `tovuTokenAuth`, so a `static_env` row holding a saved access token is one
   *  of its declared sign-ins, not a changed auth mode. */
  readonly acceptsAccessToken: boolean;
}

export interface AgentPluginMcpFederationPlan {
  readonly toUpsert: readonly PlannedAgentPluginMcpUpsert[];
  readonly skipped: readonly SkippedAgentPluginMcpServer[];
}

/** One server's classification result — either it is planned for provisioning, or it is skipped
 *  with a reason. Split out of {@link planAgentPluginMcpFederation}'s loop so that function has
 *  exactly one branch point per entry instead of several sequential early-exits.
 *
 * Narrows on the server's OWN `type` first — not merely on `classifyAgentPluginMcpServerTrust`'s
 * return value — so `config.url` below is real TypeScript narrowing, not an assertion. The
 * classifier is still consulted right after: if its rule ever changes to reclassify a remote
 * transport as "requires-confirmation" without this file being updated to match, that mismatch is
 * caught here and refused rather than silently auto-wired against stale reasoning.
 *
 * @complexity O(1).
 */
function classifyAgentPluginMcpServerForFederation(
  serverKey: string,
  config: McpServerConfig,
  classifyTrust: AgentPluginMcpTrustClassifier,
): { readonly kind: "upsert"; readonly planned: PlannedAgentPluginMcpUpsert } | { readonly kind: "skip"; readonly reason: string } {
  if (config.type === "stdio") {
    return { kind: "skip", reason: "declares a 'stdio' local process — requires explicit operator confirmation, never auto-wired from a plugin" };
  }
  if (classifyTrust(config) !== "auto-admit") {
    return {
      kind: "skip",
      reason: "this server's trust classification is not 'auto-admit' — refusing to wire it until this file is re-verified against classifyAgentPluginMcpServerTrust's current rule",
    };
  }
  if (config.type === "sse") {
    return {
      kind: "skip",
      reason: "declares the legacy 'sse' transport, which this Tovu version's external-MCP store does not support (only stdio/streamable_http)",
    };
  }
  // `headers` is validated and preserved by `manifest.ts` but has no column in the external-MCP
  // store, so a non-empty set would otherwise vanish without a skip, warning, or failure. Refuse it
  // explicitly rather than silently provisioning a row that omits configuration the plugin declared —
  // and never copy a header that may carry authorization material into a row this store cannot seal.
  if (config.headers !== undefined && Object.keys(config.headers).length > 0) {
    return {
      kind: "skip",
      reason: "declares HTTP headers, which this Tovu version's external-MCP store does not persist — refusing to provision a row that silently drops them",
    };
  }

  const connectionId = deriveAgentPluginConnectionId(serverKey);
  if (connectionId === null) {
    return { kind: "skip", reason: `server key '${serverKey}' has no valid characters to derive a connection id from` };
  }

  return {
    kind: "upsert",
    planned: { connectionId, serverKey, url: config.url, authMode: config.tovuAuthMode ?? "none", acceptsAccessToken: config.tovuTokenAuth !== undefined },
  };
}

/**
 * Pure classification pass over one plugin's full mcp.json server configs — no I/O, no
 * `saveExternalMcpServer` call, so this is independently testable from the store's own DB-shaped
 * dependencies.
 *
 * @complexity O(s) in the declared server count.
 */
export function planAgentPluginMcpFederation(input: {
  readonly servers: Readonly<Record<string, McpServerConfig>>;
}, options: {
  /** The trust rule consulted after the stdio narrowing. Defaults to the real
   *  `classifyAgentPluginMcpServerTrust`; injectable so the drift guard above (a remote transport
   *  reclassified as "requires-confirmation") stays verifiable while today's rule never trips it. */
  readonly classifyTrust?: AgentPluginMcpTrustClassifier;
} = {}): AgentPluginMcpFederationPlan {
  const classifyTrust = options.classifyTrust ?? classifyAgentPluginMcpServerTrust;
  const toUpsert: PlannedAgentPluginMcpUpsert[] = [];
  const skipped: SkippedAgentPluginMcpServer[] = [];

  for (const [serverKey, config] of Object.entries(input.servers)) {
    const result = classifyAgentPluginMcpServerForFederation(serverKey, config, classifyTrust);
    if (result.kind === "upsert") toUpsert.push(result.planned);
    else skipped.push({ serverKey, reason: result.reason });
  }

  return { toUpsert, skipped };
}

/**
 * Resolves one installed plugin's full, validated `mcp.json` server configs, given only its
 * `workspaceId`/`pluginId` — the pair a route naturally has, rather than the `packageRoot`
 * `readInstalledMcpServers` actually needs (`AgentPluginSearchCandidate`, the admin route's own read
 * model, deliberately never carries `packageRoot`: an absolute host path, per
 * `tool-registrations.ts`'s own header). Mirrors the identical `listInstalledPlugins` lookup
 * `set-enabled.ts`'s `setAgentPluginEnabled` already performs for its own installed-check — kept as
 * an independent, small duplication rather than widening that function's settled, tested return
 * shape just to smuggle a path through it.
 *
 * @returns `{}` for a plugin id not installed in this workspace — the caller (a route that already
 * 404s on that condition via `setAgentPluginEnabled`'s own precondition) never actually reaches this
 * case, but this function fails closed rather than throwing a second, redundant error for it.
 * @complexity O(d) in installed-digest count, plus one `mcp.json` read.
 */
export async function resolveAgentPluginMcpServers(input: {
  readonly agentPluginLayout: AgentPluginLayout;
  readonly workspaceId: string;
  readonly pluginId: string;
  /** Read-only trust grants require the build's bundled digest, never an arbitrary install. */
  readonly bundledOnly?: boolean;
}, _optional = {}): Promise<Readonly<Record<string, McpServerConfig>>> {
  const workspaceLayout = input.agentPluginLayout.forWorkspace(input.workspaceId);
  // A bundled plugin that was upgraded in place has its superseded package dropped here, so the
  // servers this provisions come from the digest the running build published rather than whichever
  // one the directory walk happened to reach first (`bundled-digests.ts`).
  const bundledDigests = await readBundledAgentPluginDigests(workspaceLayout.root);
  if (input.bundledOnly && !bundledDigests.has(input.pluginId)) return {};
  const installed = preferBundledAgentPluginDigests(
    await listInstalledPlugins(workspaceLayout.root),
    bundledDigests,
  );
  const plugin = installed.find((candidate) => candidate.pluginId === input.pluginId);
  if (input.bundledOnly && plugin?.archiveDigest !== bundledDigests.get(input.pluginId)) return {};
  return plugin ? readInstalledMcpServers(plugin.packageRoot) : {};
}

/**
 * Matches a declaration to the stored server identity AND exact endpoint. A URL edit or
 * normalized-name collision must never inherit another endpoint's defaults.
 * @returns The matching defaults, or `null`.
 * @complexity O(s) time, O(1) space in declared servers.
 */
export function findAgentPluginMcpServerDefaults(
  servers: Readonly<Record<string, McpServerConfig>>,
  row: { readonly serverId: string; readonly url: string | null },
): AgentPluginDefaultTools | null {
  for (const [serverKey, config] of Object.entries(servers)) {
    if (config.type === "stdio" || deriveAgentPluginConnectionId(serverKey) !== row.serverId) continue;
    return config.url === row.url ? config.tovuDefaultTools ?? null : null;
  }
  return null;
}

/**
 * Reads the bundled plugin's current manifest on every roster load. Only a build-seeded
 * digest supplies read trust; URL-only connections and arbitrary installed packages cannot.
 * @returns Reviewed remote names for this exact stored endpoint, otherwise an empty set.
 * @complexity One installed-package scan and manifest read, plus O(s + r) matching/list conversion.
 */
export async function resolveAgentPluginReadOnlyRemoteNames(input: {
  readonly agentPluginLayout: AgentPluginLayout;
  readonly workspaceId: string;
  readonly pluginId: string;
  readonly serverId: string;
  readonly url: string;
}, _optional = {}): Promise<ReadonlySet<string>> {
  const servers = await resolveAgentPluginMcpServers({ ...input, bundledOnly: true });
  return new Set(findAgentPluginMcpServerDefaults(servers, input)?.read ?? []);
}

export interface ProvisionAgentPluginMcpServersInput {
  readonly workspaceId: string;
  readonly pluginId: string;
  readonly servers: Readonly<Record<string, McpServerConfig>>;
  /** Attributed on the row exactly as an operator's own Settings → External MCP save would be —
   *  `saveExternalMcpServer`'s own `principalId` doc. */
  readonly principalId: string;
}

export interface ProvisionAgentPluginMcpServersResult {
  /** Connection ids for which a brand-new, disabled row was created this call. */
  readonly provisioned: readonly string[];
  /** Connection ids that already had a row THIS SAME plugin provisioned on an earlier enable, left
   *  completely untouched — rule 1's first case. */
  readonly alreadyProvisioned: readonly string[];
  /** Connection ids that already had a row belonging to an operator, or to a DIFFERENT plugin whose
   *  url, transport, and auth mode match this declaration, left byte-identical except for
   *  `provisionedByPluginId`, which now names this plugin — rule 1's adoption case. Every other field
   *  (url, transport, auth mode, allowlist, write grants, any oauth/sealed column) is exactly what it
   *  was before this call. A different plugin's row at a non-matching endpoint is refused instead —
   *  see {@link failed}. */
  readonly adopted: readonly string[];
  readonly skipped: readonly SkippedAgentPluginMcpServer[];
  readonly failed: readonly SkippedAgentPluginMcpServer[];
}

/** Builds the ONE-TIME creation input for a planned server that rule 1's existence check already
 *  confirmed has no row yet. Split out of {@link provisionAgentPluginMcpServers} purely to keep that
 *  function's complexity under the shop ceiling. `enabled: false` and empty allowlists are rules 2
 *  and 3 — see this file's header. */
function buildProvisioningSaveInput(
  planned: PlannedAgentPluginMcpUpsert,
  input: {
    readonly workspaceId: string;
    readonly pluginId: string;
    readonly principalId: string;
  },
) {
  return {
    workspaceId: input.workspaceId,
    serverId: planned.connectionId,
    label: `${input.pluginId} · ${planned.serverKey}`,
    transport: "streamable_http" as const,
    authMode: planned.authMode,
    enabled: false,
    command: "",
    url: planned.url,
    args: "",
    allowedToolNames: "",
    writeAllowedToolNames: "",
    // A brand-new oauth row structurally REQUIRES a grant (`external-mcp-store.ts`'s
    // `assertOAuthGrant`) even though nothing else is set — `authorization_code` is the only grant
    // Tovu's own RFC 8414/7591 discovery-then-DCR flow can complete without a device-code endpoint,
    // which the Agent Plugins spec has no field to declare anyway.
    ...(planned.authMode === "oauth" ? { oauth: { grant: "authorization_code" as const } } : {}),
    principalId: input.principalId,
    provisionedByPluginId: input.pluginId,
  };
}

/** Whether a row this same plugin provisioned still sits at an endpoint or auth mode the plugin no
 *  longer declares AND nobody has used it yet (never enabled, both tool lists empty, no saved
 *  secret). Such a row holds nothing an operator chose, only provisioning's own defaults plus, at
 *  most, a registered OAuth client minted for the OLD endpoint, which must not carry over to the new
 *  one. It is re-provisioned from the current declaration (rule 1b in this file's header).
 *  @complexity O(1) plus two short JSON parses. */
function isStaleUntouchedProvisioning(existing: ExternalMcpServerRecord, planned: PlannedAgentPluginMcpUpsert): boolean {
  // Saved tokens (OAuth or a pasted access token) mean someone signed in: the row may differ from
  // the declaration because an operator edited its URL or auth mode, and deleting it would throw
  // away those edits and the sign-in (Gemini triage T15).
  if (existing.sealedOAuth) return false;
  // A saved access token on a server that declares token sign-in is that declaration in use, not a
  // changed auth mode: treating it as stale deleted the token whenever the row was still disabled
  // (e.g. saved while an operator keeps the plugin off) — Codex review 2026-09-29.
  const authModeMatches = existing.authMode === planned.authMode || (planned.acceptsAccessToken && externalMcpRecordHasStaticAccessToken(existing));
  const declarationChanged = existing.url !== planned.url || !authModeMatches;
  return declarationChanged && !existing.enabled && isEmptyJsonList(existing.allowedToolNames) && isEmptyJsonList(existing.writeAllowedToolNames);
}

/** A stored JSON tool list that is null, blank, `[]`, or unreadable (the store reads those as `[]`).
 *  Shared with `apply-connect-defaults.ts`. */
export function isEmptyJsonList(raw: string | null): boolean {
  if (!raw) return true;
  try {
    const parsed: unknown = JSON.parse(raw);
    return !Array.isArray(parsed) || parsed.length === 0;
  } catch {
    return true;
  }
}

/** One outcome of handling a planned server for which rule 1's existence check found a row already
 *  present. `alreadyProvisioned` and `adopted` leave every field but `provisionedByPluginId`
 *  untouched (see this file's header); `failed` reports either a refused collision (a DIFFERENT
 *  plugin's row whose endpoint/transport/auth differ from this declaration) or an upsert error. Split
 *  out of {@link provisionAgentPluginMcpServers} purely to keep that function's complexity under the
 *  shop ceiling: the loop gets exactly one branch point per planned server instead of a nested
 *  try/catch inline.
 *  @complexity O(1) plus at most one `repo.upsert` for the adoption case. */
async function adoptOrRecognizeExistingAgentPluginMcpServer(
  deps: Pick<ExternalMcpStoreDeps, "repo">,
  existing: ExternalMcpServerRecord,
  planned: PlannedAgentPluginMcpUpsert,
  pluginId: string,
): Promise<
  | { readonly kind: "alreadyProvisioned" }
  | { readonly kind: "stale" }
  | { readonly kind: "adopted" }
  | { readonly kind: "failed"; readonly reason: string }
> {
  if (existing.provisionedByPluginId === pluginId) {
    return { kind: isStaleUntouchedProvisioning(existing, planned) ? "stale" : "alreadyProvisioned" };
  }
  // The connection id is unnamespaced and normalized, so a row already owned by a DIFFERENT plugin
  // may belong to a different server whose key merely sanitized to the same id. Adopting it would
  // rewrite that plugin's provenance while the endpoint stayed put — calls this plugin expects at
  // `mcp__<serverKey>__*` would still reach the other plugin's server (finding 5-2). Such a collision
  // is adopted only when the declared endpoint, transport, and auth mode match exactly; otherwise it
  // is refused and reported, never silently rebound. An operator's own row (`provisionedByPluginId
  // === null`) is still adopted unconditionally: recording an association where none existed is the
  // documented rule-1 behavior, not a rewrite of another plugin's provenance.
  if (
    existing.provisionedByPluginId !== null &&
    (existing.url !== planned.url ||
      existing.transport !== "streamable_http" ||
      existing.authMode !== planned.authMode)
  ) {
    return {
      kind: "failed",
      reason: `connection id '${planned.connectionId}' is owned by plugin '${existing.provisionedByPluginId}' at a different endpoint (url='${existing.url ?? ""}', transport='${existing.transport}', authMode='${existing.authMode}') — refusing to rebind it to plugin '${pluginId}' (declared url='${planned.url}', transport='streamable_http', authMode='${planned.authMode}')`,
    };
  }
  // Direct repo write, never `saveExternalMcpServer` — that function has no way to leave every
  // other field untouched while changing only this one (even its "tri-state" fields resolve a
  // default the caller must supply). Spreading `existing` and changing one property is the only
  // way to guarantee byte-identical preservation of the operator's url/transport/auth/allowlist/
  // write-grants/oauth state.
  await deps.repo.upsert({ ...existing, provisionedByPluginId: pluginId });
  return { kind: "adopted" };
}

/**
 * Idempotently provisions one plugin's auto-admitted remote MCP servers into the external-MCP
 * store, called when an operator ENABLES the plugin (never on disable — see this file's header:
 * disabling a plugin has no effect on any row).
 *
 * Rule 1 is enforced per server, right here: `deps.repo.findByServerId` runs BEFORE any write. A row
 * already at the derived id is NEVER passed through `saveExternalMcpServer` — it is either
 * recognized as this same plugin's earlier work (`alreadyProvisioned`), adopted byte-identical
 * except for `provisionedByPluginId` via a direct `repo.upsert` (`adopted`), or, when it belongs to a
 * DIFFERENT plugin at a non-matching endpoint/transport/auth mode, refused as a genuine collision
 * (`failed`). See {@link adoptOrRecognizeExistingAgentPluginMcpServer}.
 *
 * Per-server failures (a store validation error, an unconfigured secret store, a refused collision,
 * or an adoption's upsert failing) are caught and reported rather than thrown, matching
 * `readEnabledExternalMcpConfigs`'s own fail-open posture: one unwritable row must not stop every
 * other server in the same plugin, or the plugin's own activation, from succeeding.
 *
 * @complexity O(s) in the plugin's declared server count, each one an existence check plus at most
 * one create or adopt.
 */
export async function provisionAgentPluginMcpServers(
  deps: ExternalMcpStoreDeps,
  input: ProvisionAgentPluginMcpServersInput,
): Promise<ProvisionAgentPluginMcpServersResult> {
  const plan = planAgentPluginMcpFederation(input);
  const provisioned: string[] = [];
  const alreadyProvisioned: string[] = [];
  const adopted: string[] = [];
  const failed: SkippedAgentPluginMcpServer[] = [];

  for (const planned of plan.toUpsert) {
    const outcome = await provisionPlannedServer({ deps, input, planned });
    if (outcome.kind === "failed") failed.push({ serverKey: planned.serverKey, reason: outcome.reason });
    else if (outcome.kind === "provisioned") provisioned.push(planned.connectionId);
    else if (outcome.kind === "adopted") adopted.push(planned.connectionId);
    else alreadyProvisioned.push(planned.connectionId);
  }

  return { provisioned, alreadyProvisioned, adopted, skipped: plan.skipped, failed };
}

/** Execute one planned write, keeping lookup, adoption and replacement failures isolated. */
async function provisionPlannedServer(
  required: {
    readonly deps: ExternalMcpStoreDeps;
    readonly input: ProvisionAgentPluginMcpServersInput;
    readonly planned: PlannedAgentPluginMcpUpsert;
  },
  _options = {},
): Promise<{ readonly kind: "provisioned" | "alreadyProvisioned" | "adopted" } | { readonly kind: "failed"; readonly reason: string }> {
  const { deps, input, planned } = required;
  try {
    const existing = await deps.repo.findByServerId({ workspaceId: input.workspaceId, serverId: planned.connectionId });
    if (existing) {
      const outcome = await adoptOrRecognizeExistingAgentPluginMcpServer(deps, existing, planned, input.pluginId);
      if (outcome.kind !== "stale") return outcome;
      // Rule 1b: replaced by a fresh row, exactly as a first enable would write it.
      await deps.repo.deleteByServerId({ workspaceId: input.workspaceId, serverId: planned.connectionId });
    }

    await saveExternalMcpServer(deps, buildProvisioningSaveInput(planned, input));
    return { kind: "provisioned" };
  } catch (err) {
    return { kind: "failed", reason: err instanceof Error ? err.message : String(err) };
  }
}

import { readFileSync } from "node:fs";
import path from "node:path";
import { resolveProductRoot } from "../../platform/site-dir/product-root.js";
import { evaluateHostSignals, selectCoreHostSignalDeclaration, type HostSignal, type HostSignalDeclaration, type HostSignals } from "../../contracts/core/host-signals.js";
import { bundledContributionSources } from "./bundled-contribution-sources.js";

/** JSON objects only, including the manifest's optional extension containers. */
function record(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** Diagnostic copy is a single bounded line, never an environment value. */
function diagnosticText(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0 && value.length <= 2048 && !/[\r\n\x00-\x1f\x7f]/.test(value);
}

/** Accept only known boolean facts and a finite positive safe hop count. No truthy coercion. */
function validFacts(value: unknown): value is HostSignal["facts"] {
  if (!record(value)) return false;
  return Object.entries(value).every(([key, fact]) => {
    if (key === "hosted" || key === "nativeToolsRestricted") return typeof fact === "boolean";
    return key === "trustProxyHops" && Number.isSafeInteger(fact) && (fact as number) > 0;
  });
}

/** Invalid env names or labels cannot become host hints. @complexity O(1). */
function validSignal(value: unknown): value is HostSignal {
  if (!record(value)) return false;
  if (typeof value.env !== "string" || !/^[A-Z_][A-Z0-9_]*$/.test(value.env)) return false;
  if (!validFacts(value.facts)) return false;
  return value.label === undefined || diagnosticText(value.label);
}

/**
 * Parse the existing extensions.tovu convention; a malformed declaration contributes nothing.
 * @param required Parsed JSON manifest, never executable plugin code.
 * @returns Validated hints, or undefined for absent/invalid metadata. Never throws for JSON input.
 * @complexity O(s) for s declared signals; no I/O.
 * @example parseHostSignalDeclaration({ manifest: JSON.parse(text) });
 */
export function parseHostSignalDeclaration({ manifest }: { manifest: unknown }, _optional = {}): HostSignalDeclaration | undefined {
  if (!record(manifest) || !record(manifest.extensions) || !record(manifest.extensions.tovu)) return undefined;
  const extension = manifest.extensions.tovu;
  if (!Array.isArray(extension.hostSignals) || !extension.hostSignals.every(validSignal)) return undefined;
  if (extension.deploymentAdvice !== undefined && !diagnosticText(extension.deploymentAdvice)) return undefined;
  return { signals: extension.hostSignals, ...(extension.deploymentAdvice === undefined ? {} : { deploymentAdvice: extension.deploymentAdvice as string }) };
}

interface ReaderPorts {
  readonly sources?: typeof bundledContributionSources;
  readonly readText?: (file: string) => string;
}

/**
 * Read only manifests from the hermetic bundled source policy, independent of site activation.
 * @param required Product-controlled content/agent-plugins root, never an installed package dir.
 * @param optional Directory and text reader ports for direct failure-path tests.
 * @returns Validated unambiguous data. Absent/malformed packages contribute no declaration;
 * the resolver applies the core security fallback rather than treating absent data as permission.
 * @complexity O(p + s) for p plugin manifests and s signals; one synchronous read per manifest.
 * @example readBundledHostSignalDeclaration({ sourceRoot });
 */
export function readBundledHostSignalDeclaration(
  required: { readonly sourceRoot: string }, optional: ReaderPorts = {},
): HostSignalDeclaration {
  let sources: ReturnType<typeof bundledContributionSources>;
  // Preboot readers must not turn a missing bundled payload into a boot failure (phase 2 policy).
  try { sources = (optional.sources ?? bundledContributionSources)({ ...required, filename: "plugin.json" }); }
  catch { return { signals: [] }; }
  const declarations = sources.flatMap(source => {
    try {
      const text = (optional.readText ?? readManifestText)(path.join(source.packageRoot, "plugin.json"));
      const declaration = parseHostSignalDeclaration({ manifest: JSON.parse(text) });
      return declaration === undefined ? [] : [declaration];
    } catch { return []; }
  });
  return combineDeclarations({ declarations });
}

/** Reject the whole ambiguous declaration so the resolver can retain the complete core fallback.
 * @complexity O(s + p) for s signals and p declarations, with no I/O or input mutation. */
function combineDeclarations({ declarations }: { declarations: readonly HostSignalDeclaration[] }, _optional = {}): HostSignalDeclaration {
  const signals = declarations.flatMap(declaration => declaration.signals);
  const names = new Set(signals.map(signal => signal.env));
  const advice = [...new Set(declarations.flatMap(declaration => declaration.deploymentAdvice === undefined ? [] : [declaration.deploymentAdvice]))];
  if (names.size !== signals.length || advice.length > 1) return { signals: [] };
  return { signals, ...(advice.length === 1 ? { deploymentAdvice: advice[0] } : {}) };
}

/** Node's text-only manifest read; errors are caught at the bundled adapter boundary. */
function readManifestText(file: string): string { return readFileSync(file, "utf8"); }

/**
 * Bind product-root discovery to the pure evaluator; no plugin imports, DB or activation needed.
 * @param required Environment snapshot, values are never logged or returned as diagnostic copy.
 * @param optional Trusted source root or reader/root-discovery ports; desktop may supply its payload.
 * @returns Facts only; unavailable/incomplete/ambiguous security data uses the core HEAD fallback.
 * Discovery and read failures never fail boot or disable the baseline hosted protections.
 * @complexity O(p + s) as for the reader, plus bounded product-root discovery.
 * @example resolveBundledHostSignals({ env }, { sourceRoot });
 */
export function resolveBundledHostSignals(
  required: { env: Readonly<Record<string, string | undefined>> },
  optional: { sourceRoot?: string; readDeclaration?: typeof readBundledHostSignalDeclaration; productRoot?: () => string } = {},
): HostSignals {
  try {
    const sourceRoot = optional.sourceRoot ?? path.join((optional.productRoot ?? resolveProductRoot)(), "content", "agent-plugins");
    const declaration = selectCoreHostSignalDeclaration({ declaration: (optional.readDeclaration ?? readBundledHostSignalDeclaration)({ sourceRoot }) });
    return evaluateHostSignals({ ...required, declaration });
  } catch { return evaluateHostSignals({ ...required, declaration: selectCoreHostSignalDeclaration({}) }); }
}

import { resolveTarget, saveStaticAccessToken, type AgentPluginTokenTargetDeps } from "./access-token-tool.js";
import { preferBundledAgentPluginDigests, readBundledAgentPluginDigests } from "./lifecycle.js";
import { readInstalledMcpServers } from "./capability-projection.js";
import { hasStoredAgentPluginCredential } from "./connect-tool.js";
import type { AgentPluginLayout } from "./layout.js";
import type { McpServerConfig } from "./mcp-metadata.js";
import { listInstalledPlugins } from "./lifecycle.js";
import { AGENT_PLUGINS_SCREEN, switchOnSavedTokenConnection, type SwitchOnSavedTokenDeps } from "./switch-on-saved-token.js";

/**
 * @file Saves an access token that did NOT come through `agent_plugin_set_access_token`'s form onto
 * an Agent Plugin's token-auth row, then switches the plugin on (`switch-on-saved-token.ts`, shared
 * with the tool) — the same end state as a pasted token followed by a first sign-in.
 *
 * Two callers, both at boot (`server/runtime/boot/bootstrap.ts`):
 * - {@link importAgentPluginAccessTokensFromEnv}: a plugin's `mcp.json` may name an old env var
 *   (`tovuTokenAuth.importFromEnv`) whose token is copied over. Added 2026-09-29 when the Supabase
 *   env preset (`TOVU_SUPABASE_MCP_*`) was retired in favour of the Supabase plugin.
 * - create-site onboarding's pending tokens (`composition/pending-agent-plugin-tokens.ts`).
 *
 * Never overwrites: a row that already holds a credential (a sign-in or a saved token) keeps it; the
 * switch-on still runs, so a save whose switch-on failed is finished by the next import.
 * Not probed: the env token was already in use, and onboarding probes before it seals.
 *
 * The env import trusts only what THIS Tovu build shipped: a declaration is read from a plugin only
 * when its installed digest is the one `seed-bundled.ts` recorded (`bundled-digests.ts`), and the
 * token only goes to a row still at that declaration's URL. Any installed package can declare
 * `importFromEnv`, so without this an operator-installed plugin could name `OPENAI_API_KEY` and an
 * endpoint of its own and be handed that secret at boot (Codex review 2026-09-29).
 */

/** Recorded as `updatedBy`/principal on what an import writes. */
export const AGENT_PLUGIN_TOKEN_IMPORT_ACTOR = "system:token-import";

export interface ImportAgentPluginAccessTokenDeps
  extends AgentPluginTokenTargetDeps,
    Pick<SwitchOnSavedTokenDeps, "onConnected" | "isPluginOffByOperator" | "switchPluginOn"> {}

/** `saved-left-off`: the token is saved but an operator had turned the plugin or its connection off,
 *  so it stays off (`switch-on-saved-token.ts`). */
export type ImportAgentPluginAccessTokenOutcome = "saved" | "saved-left-off" | "already-connected";

/**
 * Seals `token` onto `pluginId`'s token-auth row unless that row already has a credential, then
 * switches the plugin on (also when it already had one, to finish an earlier interrupted import).
 *
 * @throws {import("@jini-ai/core").ToolInputError} Plugin not installed, or no single token-auth server.
 * @throws Whatever the store throws on save (e.g. an unconfigured secret store).
 * @complexity O(s) in the plugin's declared servers, plus one row read and at most two writes.
 */
export async function importAgentPluginAccessToken(
  deps: ImportAgentPluginAccessTokenDeps,
  input: {
    readonly pluginId: string;
    readonly token: string;
    readonly principalId?: string;
    /** When set, the token is saved only onto a row at exactly this URL (the env import's rule). */
    readonly onlyAtUrl?: string;
  },
): Promise<ImportAgentPluginAccessTokenOutcome> {
  const principalId = input.principalId ?? AGENT_PLUGIN_TOKEN_IMPORT_ACTOR;
  const target = await resolveTarget(deps, input.pluginId, principalId);
  const row = await deps.externalMcpServerRepo.findByServerId({ workspaceId: deps.workspaceId, serverId: target.connectionId });
  if (row && hasStoredAgentPluginCredential(row)) {
    // Finishes a switch-on an earlier import saved the token for but did not complete (it threw
    // after the save): idempotent, and it keeps an operator's off switch (`switch-on-saved-token.ts`).
    await switchOnSavedTokenConnection(deps, target);
    return "already-connected";
  }
  if (input.onlyAtUrl !== undefined && (row?.url ?? target.config.url) !== input.onlyAtUrl) {
    throw new Error(`its '${target.connectionId}' connection points at a different URL than the '${input.pluginId}' plugin declares, so the token is not copied there`);
  }

  await saveStaticAccessToken(deps, target, principalId, input.token);
  const switched = await switchOnSavedTokenConnection(deps, target);
  return switched.state === "on" ? "saved" : "saved-left-off";
}

/** One installed plugin's id and declared servers. */
export interface InstalledAgentPluginServers {
  readonly pluginId: string;
  readonly servers: Readonly<Record<string, McpServerConfig>>;
  /** True only when this is the digest this Tovu build seeded for the id (`bundled-digests.ts`).
   *  Absent reads as not bundled. */
  readonly bundled?: boolean;
}

/** Every installed plugin in the workspace, one per id (the bundled-preferred digest). */
export async function listInstalledAgentPluginServers(input: { workspaceId: string; agentPluginLayout: AgentPluginLayout }, _options = {}): Promise<readonly InstalledAgentPluginServers[]> {
  const workspaceLayout = input.agentPluginLayout.forWorkspace(input.workspaceId);
  const ledger = await readBundledAgentPluginDigests(workspaceLayout.root);
  const installed = preferBundledAgentPluginDigests(await listInstalledPlugins(workspaceLayout.root), ledger);
  const seen = new Set<string>();
  const out: InstalledAgentPluginServers[] = [];
  for (const plugin of installed) {
    if (seen.has(plugin.pluginId)) continue;
    seen.add(plugin.pluginId);
    out.push({ pluginId: plugin.pluginId, servers: await readInstalledMcpServers(plugin.packageRoot), bundled: ledger.get(plugin.pluginId) === plugin.archiveDigest });
  }
  return out;
}

export interface TokenImportLog {
  info(message: string): void;
  warn(message: string): void;
}

export interface ImportAgentPluginAccessTokensFromEnvDeps extends ImportAgentPluginAccessTokenDeps {
  /** Injected for tests. Defaults to {@link listInstalledAgentPluginServers}. */
  readonly listPlugins?: () => Promise<readonly InstalledAgentPluginServers[]>;
}

/** The env declarations of every token-auth server across the BUNDLED plugins (see this file's header). */
function envDeclarations(plugins: readonly InstalledAgentPluginServers[]) {
  return plugins.flatMap(({ pluginId, servers, bundled }) =>
    bundled === true
      ? Object.values(servers).flatMap((config) => (config.type !== "stdio" && config.tovuTokenAuth ? [{ pluginId, url: config.url, auth: config.tovuTokenAuth }] : []))
      : [],
  );
}

/**
 * Boot: for each bundled plugin whose token-auth server names `importFromEnv`, copies a set env
 * token onto its row (logged once, on the boot that copies it — later boots find the row connected
 * and say nothing), and names any set `retiredEnv` vars as no longer used. Never throws: a failed
 * import is a warning and the next boot tries again.
 *
 * @complexity O(p·s) over installed plugins and their servers, plus one import per set env token.
 */
export async function importAgentPluginAccessTokensFromEnv(
  deps: ImportAgentPluginAccessTokensFromEnvDeps,
  env: Readonly<Record<string, string | undefined>>,
  log: TokenImportLog,
  options: {
    /** Plugins with a create-site onboarding token still pending: that explicit token wins over the
     *  env one, so the env token is not copied onto them (`bootstrap.ts`). */
    readonly skipPluginIds?: ReadonlySet<string>;
  } = {},
): Promise<void> {
  let plugins: readonly InstalledAgentPluginServers[];
  try {
    plugins = await (deps.listPlugins ?? (() => listInstalledAgentPluginServers(deps)))();
  } catch (err) {
    log.warn(`[agent-plugins] could not list plugins to import env tokens: ${err instanceof Error ? err.message : String(err)}`);
    return;
  }

  for (const { pluginId, url, auth } of envDeclarations(plugins)) {
    reportRetiredEnv({ pluginId, auth, env, log });
    const token = auth.importFromEnv ? (env[auth.importFromEnv] ?? "").trim() : "";
    await importDeclaredEnvToken({ deps, pluginId, url, auth, token, log, skipPluginIds: options.skipPluginIds });
  }
}

type EnvDeclaration = ReturnType<typeof envDeclarations>[number];

/** Retirement notices are independent of whether this boot has a token to import. */
function reportRetiredEnv(input: Pick<EnvDeclaration, "pluginId" | "auth"> & { readonly env: Readonly<Record<string, string | undefined>>; readonly log: TokenImportLog }, _options = {}): void {
  const { pluginId, auth, env, log } = input;
  const retiredSet = (auth.retiredEnv ?? []).filter((name) => (env[name] ?? "").trim() !== "");
  if (retiredSet.length > 0) {
    log.info(`[agent-plugins] ${retiredSet.join(", ")} ${retiredSet.length === 1 ? "is" : "are"} no longer used; the '${pluginId}' plugin's connection replaces them. You can remove them.`);
  }
}

/** Isolate one import's failure so later declarations still run. */
async function importDeclaredEnvToken(input: EnvDeclaration & { readonly deps: ImportAgentPluginAccessTokensFromEnvDeps; readonly token: string; readonly log: TokenImportLog; readonly skipPluginIds?: ReadonlySet<string> }, _options = {}): Promise<void> {
  const { deps, pluginId, url, auth, token, log, skipPluginIds } = input;
  if (!auth.importFromEnv || token === "" || skipPluginIds?.has(pluginId)) return;
  try {
    const outcome = await importAgentPluginAccessToken(deps, { pluginId, token, onlyAtUrl: url });
    if (outcome === "saved") {
      log.info(`[agent-plugins] copied ${auth.importFromEnv} onto the '${pluginId}' plugin's connection and switched it on. The env var is no longer needed.`);
    } else if (outcome === "saved-left-off") {
      log.info(`[agent-plugins] copied ${auth.importFromEnv} onto the '${pluginId}' plugin's connection; it stays off because an operator turned it off (${AGENT_PLUGINS_SCREEN}). The env var is no longer needed.`);
    }
  } catch {
    // Importer/store failures can echo the token; keep all importer text out of boot logs.
    log.warn(`[agent-plugins] could not copy ${auth.importFromEnv} onto the '${pluginId}' plugin. Check the site credential store and try again.`);
  }
}

