import { readdir, readFile } from "node:fs/promises";
import path from "node:path";

import { resolveProductRoot } from "../../platform/site-dir/index.js";

import { readInstalledMcpServers } from "./capability-projection.js";
import { titleCaseFromPluginId, type ResolvedAgentPluginForConnect } from "./connect-tool.js";
import type { InstalledAgentPluginServers } from "./import-access-token.js";
import { RETIRED_BUNDLED_AGENT_PLUGINS } from "./lifecycle.js";
import { listTokenSignInPlugins, type TokenCheckOutcome, type TokenSignInPlugin } from "./token-sign-in.js";

/**
 * @file The rules for access tokens given while CREATING a site, shared by every create path: the
 * admin's `POST .../system/sites` (`routes/system/sites.ts`) and `tovu init --agent-plugin-tokens-stdin`
 * (`cli/commands/init.ts`, which the desktop app's "Create website" runs). Added 2026-09-29 so the
 * desktop create form offers the same optional "Connect services" step as the admin's.
 *
 * Generic: keyed by plugin id; a plugin qualifies by declaring `tovuTokenAuth` (`token-sign-in.ts`).
 * Nothing here ever returns or logs a token.
 */

const PLUGIN_ID_PATTERN = /^[a-z0-9][a-z0-9-]{0,63}$/;
const MAX_AGENT_PLUGIN_TOKENS = 8;
const MAX_TOKEN_LENGTH = 4096;

export const NEW_SITE_AGENT_PLUGIN_TOKENS_SHAPE_ERROR = "'agentPluginTokens' must map plugin ids to token strings";

function isValidTokenEntry(
  { pluginId, value }: { pluginId: string; value: string },
  _optional = {},
): boolean {
  return PLUGIN_ID_PATTERN.test(pluginId) && value.length <= MAX_TOKEN_LENGTH;
}

/**
 * `{ [pluginId]: token }`, trimmed, blanks dropped. `null`/`undefined` is "none given".
 * @complexity O(n) in the entry count (bounded).
 */
export function parseNewSiteAgentPluginTokens(raw: unknown): { ok: true; tokens: Record<string, string> } | { ok: false; error: string } {
  if (raw === undefined || raw === null) return { ok: true, tokens: {} };
  const invalid = { ok: false as const, error: NEW_SITE_AGENT_PLUGIN_TOKENS_SHAPE_ERROR };
  if (typeof raw !== "object" || Array.isArray(raw) || Object.keys(raw).length > MAX_AGENT_PLUGIN_TOKENS) return invalid;
  const tokens: Record<string, string> = {};
  for (const [pluginId, value] of Object.entries(raw)) {
    if (typeof value !== "string" || !isValidTokenEntry({ pluginId, value })) return invalid;
    const token = value.trim();
    if (token !== "") tokens[pluginId] = token;
  }
  return { ok: true, tokens };
}

/** Why a token given at create time stops the create, or `null` when it may be stored. A token the
 *  vendor could not be reached to check is still stored: the new site's first use tells. */
export function describeNewSiteAgentPluginTokenRefusal(
  pluginId: string,
  outcome: TokenCheckOutcome,
): { code: "AGENT_PLUGIN_TOKEN_INVALID" | "AGENT_PLUGIN_TOKEN_REFUSED" | "AGENT_PLUGIN_TOKEN_UNSUPPORTED"; error: string } | null {
  const name = titleCaseFromPluginId(pluginId);
  // A purpose refusal must still stop a pre-save check, without mislabelling a usable key.
  if (outcome === "refused") {
    return { code: "AGENT_PLUGIN_TOKEN_REFUSED", error: `That ${name} access token was refused for this purpose. Check its permissions, or leave it empty and connect ${name} later from chat. No site was created.` };
  }
  if (outcome === "invalid") {
    return { code: "AGENT_PLUGIN_TOKEN_INVALID", error: `That ${name} access token didn't work. Check it, or leave it empty and connect ${name} later from chat. No site was created.` };
  }
  if (outcome === "unsupported") {
    return { code: "AGENT_PLUGIN_TOKEN_UNSUPPORTED", error: `${name} can't be connected with an access token here. Leave it empty and connect it later from chat. No site was created.` };
  }
  return null;
}

/**
 * The first refusal across `tokens`, checked in order, or `null` when every token may be stored.
 * @complexity One check (at most one outbound GET) per token.
 */
export async function firstNewSiteAgentPluginTokenRefusal(
  check: (input: { pluginId: string; token: string }) => Promise<TokenCheckOutcome>,
  tokens: Readonly<Record<string, string>>,
): Promise<{ pluginId: string; code: string; error: string } | null> {
  for (const [pluginId, token] of Object.entries(tokens)) {
    const refusal = describeNewSiteAgentPluginTokenRefusal(pluginId, await check({ pluginId, token }));
    if (refusal) return { pluginId, ...refusal };
  }
  return null;
}

/** The plugin's manifest `name`, or `null` when `plugin.json` is missing or unreadable. */
async function readBundledPluginId(pluginDir: string): Promise<string | null> {
  try {
    const manifest = JSON.parse(await readFile(path.join(pluginDir, "plugin.json"), "utf8")) as { name?: unknown };
    return typeof manifest.name === "string" && PLUGIN_ID_PATTERN.test(manifest.name) ? manifest.name : null;
  } catch {
    return null;
  }
}

/**
 * The bundled plugins shipped with this Tovu (`content/agent-plugins/`, `deps.ts`'s
 * `bundledAgentPluginsDir()`), for a create path that runs before the new site has a workspace to
 * install them into — the new site's first boot seeds exactly these. An absent dir is an empty list.
 *
 * @complexity O(p) plugin dirs, one manifest and one `mcp.json` read each.
 */
export async function listBundledAgentPluginServers(sourceRoot: string): Promise<readonly InstalledAgentPluginServers[]> {
  let entries: Dirent[];
  try {
    entries = await readdir(sourceRoot, { withFileTypes: true });
  } catch {
    return [];
  }
  const out: InstalledAgentPluginServers[] = [];
  for (const entry of entries) {
    // Same skip as `seed-bundled.ts`: a retired id is never seeded, so it is never offered.
    if (!entry.isDirectory() || RETIRED_BUNDLED_AGENT_PLUGINS.has(entry.name)) continue;
    const pluginDir = path.join(sourceRoot, entry.name);
    const pluginId = await readBundledPluginId(pluginDir);
    if (pluginId === null) continue;
    out.push({ pluginId, servers: await readInstalledMcpServers(pluginDir) });
  }
  return out;
}

/** `checkAgentPluginAccessToken`'s `resolveInstalledPlugin`, answered from the bundled plugins. */
export function resolveBundledAgentPlugin(sourceRoot: string): (pluginId: string) => Promise<ResolvedAgentPluginForConnect | null> {
  return async (pluginId) => {
    const found = (await listBundledAgentPluginServers(sourceRoot)).find((plugin) => plugin.pluginId === pluginId);
    return found ? { servers: found.servers } : null;
  };
}

/** The bundled plugins' source dir: `TOVU_BUNDLED_AGENT_PLUGINS_DIR`, else `<product>/content/agent-plugins`.
 *  Same resolution as `deps.ts`'s `bundledAgentPluginsDir()` (not imported: that module pulls in the
 *  whole server composition graph for one path). `optional.env`/`optional.productRoot` default to the
 *  process environment and the resolved product root. @complexity O(1). */
export function bundledAgentPluginsSourceRoot(
  optional: { env?: Readonly<Record<string, string | undefined>>; productRoot?: () => string } = {},
): string {
  const env = optional.env ?? process.env;
  return env.TOVU_BUNDLED_AGENT_PLUGINS_DIR ?? path.join((optional.productRoot ?? resolveProductRoot)(), "content", "agent-plugins");
}

/**
 * The plugins a NEW site can be connected to with a pasted token: the bundled ones its first boot
 * seeds. Not the creating site's installs — a plugin only that site has would be offered, pass the
 * check, and then never exist on the new site.
 *
 * @complexity O(p) bundled plugin dirs.
 */
export function listNewSiteAgentPluginTokenSignInPlugins(sourceRoot: string = bundledAgentPluginsSourceRoot()): Promise<readonly TokenSignInPlugin[]> {
  return listTokenSignInPlugins("new-site", () => listBundledAgentPluginServers(sourceRoot));
}

import type { Clock as ClockPort } from "@jini-ai/core/primitives";

import type { ExternalMcpServerRepoPort } from "#src/assistant/index";


import { createApplyConnectDefaults, isPluginOffByOperator as defaultIsPluginOffByOperator, switchPluginOnUnlessOperatorOff } from "./apply-connect-defaults.js";
import type { AgentPluginLayout } from "./layout.js";

/**
 * @file After an access token is saved onto a plugin's token-auth row, switches the plugin on the
 * same way a first sign-in does (`apply-connect-defaults.ts`), so saving a token is the only step —
 * unless an operator deliberately turned it off, in which case it stays off and the caller names the
 * screen that turns it back on.
 *
 * Two callers: `agent_plugin_set_access_token` (`access-token-tool.ts`) and the token import
 * (`import-access-token.ts`, boot env import and create-site onboarding). Added 2026-09-29: the
 * tool used to end with "ask the operator to enable it in Settings", a manual step nothing required.
 *
 * "Deliberately off" is either:
 * - a disabled Agent Plugins activation record that anyone other than the boot seeder wrote (the
 *   seeder's own disabled record is the default, not a decision — `activation.ts`'s same exception);
 * - a row the operator already edited (tool lists filled) and left disabled — `apply-connect-defaults`
 *   never touches an edited row.
 */


/** Where each "off" is switched back on in the admin (`apps/admin/src/panels.tsx` nav labels). */
export const AGENT_PLUGINS_SCREEN = "Add-Ons → Agent Plugins";
export const EXTERNAL_MCP_SCREEN = "Add-Ons → Integrations → External MCP";

export type SavedTokenSwitchOutcome =
  | { readonly state: "on" }
  | { readonly state: "plugin-off-by-operator" }
  | { readonly state: "connection-off-by-operator" };

export interface SwitchOnSavedTokenDeps {
  readonly workspaceId: string;
  readonly agentPluginLayout: AgentPluginLayout;
  readonly externalMcpServerRepo: ExternalMcpServerRepoPort;
  readonly clock: ClockPort;
  /** Injected for tests. Defaults to `createApplyConnectDefaults`, the sign-in's own `onConnected`. */
  readonly onConnected?: (serverId: string) => Promise<void>;
  /** Injected for tests. Defaults to reading this workspace's activations file. */
  readonly isPluginOffByOperator?: (pluginId: string) => Promise<boolean>;
  /** Injected for tests. Switches the plugin's activation on unless an operator turned it off; false
   *  when an operator's "off" stopped it. Defaults to `apply-connect-defaults.ts`'s {@link switchPluginOnUnlessOperatorOff}. */
  readonly switchPluginOn?: (pluginId: string) => Promise<boolean>;
}

/**
 * Switches the plugin and its `connectionId` row on after a token was saved there, unless an
 * operator turned either off. "on" means both the row and the plugin's own activation are on.
 *
 * @throws Whatever the activation read or write, the connect-defaults write, or the row read throws.
 * @complexity Two activation reads, at most one connect-defaults apply and one activation write, one row read.
 */
export async function switchOnSavedTokenConnection(
  deps: SwitchOnSavedTokenDeps,
  target: { readonly pluginId: string; readonly connectionId: string },
): Promise<SavedTokenSwitchOutcome> {
  const isOff = deps.isPluginOffByOperator ?? ((pluginId: string) => defaultIsPluginOffByOperator({ ...deps, pluginId }));
  if (await isOff(target.pluginId)) return { state: "plugin-off-by-operator" };

  const onConnected = deps.onConnected ?? createApplyConnectDefaults({ agentPluginLayout: deps.agentPluginLayout, workspaceId: deps.workspaceId, repo: deps.externalMcpServerRepo, clock: deps.clock });
  await onConnected(target.connectionId);

  const row = await deps.externalMcpServerRepo.findByServerId({ workspaceId: deps.workspaceId, serverId: target.connectionId });
  if (row?.enabled !== true) return { state: "connection-off-by-operator" };

  const switchPluginOn = deps.switchPluginOn ?? ((pluginId: string) => switchPluginOnUnlessOperatorOff({ ...deps, pluginId }));
  return (await switchPluginOn(target.pluginId)) ? { state: "on" } : { state: "plugin-off-by-operator" };
}

/** The plain next-step line for each outcome. Never carries a token. */
export function describeSavedTokenSwitch(outcome: SavedTokenSwitchOutcome, names: { readonly displayName: string; readonly connectionId: string }): string {
  switch (outcome.state) {
    case "on":
      return `${names.displayName} is connected and switched on. Its tools are ready to use.`;
    case "plugin-off-by-operator":
      return `Token saved. ${names.displayName} stays off because an operator turned it off. To use it, switch '${names.displayName}' on in ${AGENT_PLUGINS_SCREEN}.`;
    case "connection-off-by-operator":
      return `Token saved. The '${names.connectionId}' connection stays off because an operator changed its settings. To use it, switch it on in ${EXTERNAL_MCP_SCREEN}.`;
  }
}

