/**
 * This wiring layer's OWN risk classification, authored from what each handler below actually
 * calls. See `DerivedRiskByToolId` in the kit for why it is independent of the catalog's own
 * `sideEffects` declaration.
 */
export const commentsDerivedRisk: DerivedRiskByToolId = new Map<string, AgentToolSideEffect>([
  ['comments_get_provider', 'none'],
  ['comments_set_provider', 'mutates-durable-state'],
  // -> commentRepo.listModerationQueue: read only.
  ["comments_list_moderation_queue", "none"],
  // Workspace-scoped findById, projected through the same moderation view.
  ["comments_get_comment", "none"],
  // -> getCommentsSettings (settings.ts): settingsRepo read only.
  ["comments_get_settings", "none"],
  // -> setCommentsSettings (settings.ts): N ledger set() calls, one per changed field.
  ["comments_update_settings", "mutates-durable-state"],
  // -> commentWriteService.applyModeration: status flip + moderation_log append + outbox/hooks.
  ["comments_approve_comment", "mutates-durable-state"],
  ["comments_mark_comment_spam", "mutates-durable-state"],
  ["comments_trash_comment", "mutates-durable-state"],
  ["comments_restore_comment", "mutates-durable-state"],
]);

/** What a comment looks like to the model — trims `CommentRecord` to what a moderation decision actually needs. */
function toCommentModerationView(record: {
  id: string;
  entryId: string;
  parentId: string | null;
  status: CommentStatus;
  authorName: string;
  authorEmail: string | null;
  bodyText: string;
  spamScore: number | null;
  createdAt: string;
  version: number;
}) {
  return {
    id: record.id,
    entryId: record.entryId,
    parentId: record.parentId,
    status: record.status,
    authorName: record.authorName,
    authorEmail: record.authorEmail,
    bodyText: record.bodyText,
    spamScore: record.spamScore,
    createdAt: record.createdAt,
    version: record.version,
  };
}

/** Projects a `ModerationQueuePage` into the model-facing shape — `workspaceId`/internal fields (threadRootId, depth, authorIpHash, spamProvider, updatedAt) dropped, same discipline as content-types' `toContentTypeView`. */
function toModerationQueueToolView(page: ModerationQueuePage): { items: ReturnType<typeof toCommentModerationView>[]; nextCursor: string | null } {
  return { items: page.items.map(toCommentModerationView), nextCursor: page.nextCursor };
}

/**
 * The Comments refusals safe to show the model verbatim (wm S16). Without this list every one of
 * them — a permission denial, a stale `expectedVersion`, an unknown id — reached the model as the
 * transport's redacted INTERNAL_ERROR, so it could not tell "retry with the fresh version" from a
 * crash. The messages carry only ids/versions the caller itself supplied or must resend; comment
 * bodies and author data never appear in them.
 */
const COMMENTS_MODEL_FACING_ERRORS: readonly ModelFacingErrorRule[] = [
  forbiddenRule({ domainPrefix: "COMMENTS", error: ForbiddenError }),
  // `comments_update_settings` is refused by the settings kit's own ForbiddenError (a separate
  // class, not a subclass of the cms one) — see that handler's note on self-enforcement.
  forbiddenRule({ domainPrefix: "COMMENTS", error: SettingsForbiddenError }),
  { error: CommentNotFoundError, code: "COMMENTS_NOT_FOUND" },
  {
    error: CommentVersionConflictError,
    code: "COMMENTS_VERSION_CONFLICT",
    guidance: "Re-read it with comments_list_moderation_queue and retry with the fresh version",
  },
];

/** Maps `applyModeration`'s returned failure to the typed domain error the handlers throw. */
function moderationFailureError(required: { commentId: string; result: { reason: "not-found" | "conflict"; currentVersion?: number } }): Error {
  const { commentId, result } = required;
  return result.reason === "conflict"
    ? new CommentVersionConflictError({ commentId, ...(result.currentVersion !== undefined ? { currentVersion: result.currentVersion } : {}) })
    : new CommentNotFoundError({ commentId });
}

/**
 * Builds one moderation-action tool handler — shared by approve/mark_spam/trash/restore, which
 * differ only in the permission gated on and the `action`/`toStatus` pair passed to
 * `commentWriteService.applyModeration`. Factored out rather than four near-duplicate handlers.
 *
 * `applyModeration`'s success half is `{ok:true}` with no updated record (a real interface
 * limitation, not a shortcut this file takes — `CommentWriteService`'s declared return type
 * carries nothing else back), so the acknowledgement echoes what the model already told it
 * (commentId, the resulting status) — the same "echo the id back" convention
 * `identity_role_delete` uses for a void-resolving domain call.
 *
 * @complexity O(1) beyond the wrapped `applyModeration` call.
 * @overallScore 100
 */
function buildCommentsModerationHandler(
  routeDeps: CommentsToolDeps,
  spec: { permission: string; action: ModerationAction; toStatus: CommentStatus },
): ToolHandler {
  return async (ctx) => {
    const input = requireInputRecord({ input: ctx.input });
    const commentId = requireString({ input: input, key: "commentId" });

    await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: spec.permission }, { entityType: "comment", entityId: commentId });

    await routeDeps.commentsReady;
    const result = await routeDeps.commentWriteService.applyModeration({
      workspaceId: routeDeps.workspaceId,
      id: commentId,
      expectedVersion: requireNumber({ input, key: "expectedVersion" }),
      action: spec.action,
      toStatus: spec.toStatus,
      actorPrincipalId: ctx.principal.id,
      note: typeof input.note === "string" ? input.note : null,
    });
    if (!result.ok) {
      throw moderationFailureError({ commentId, result });
    }

    return { moderated: { commentId, toStatus: spec.toStatus } };
  };
}

const COMMENTS_TRASH_TOOL_ID = "comments_trash_comment";

/** See `trash/trash-item-tool.ts`'s identical constant's doc — duplicated here rather than
 *  imported, the same "structurally typed, no `features/trash` import" convention this file's own
 *  header already follows. */
const ASSISTANT_ACTOR_PLUGIN_ID = "assistant";

/** Reads the optional patch members of `comments_update_settings`, requiring at least one — mirrors Forms' `requireFormsPatch`'s identical "no accepted-as-no-op empty patch" discipline. */
function requireCommentsSettingsPatch(input: Record<string, unknown>): Partial<CommentsSettings> {
  const patch: Partial<CommentsSettings> = {};
  if (typeof input.enabled === "boolean") patch.enabled = input.enabled;
  if (typeof input.requireModeration === "boolean") patch.requireModeration = input.requireModeration;
  if (typeof input.maxDepth === "number") patch.maxDepth = input.maxDepth;
  if (input.closeAfterDays === null || typeof input.closeAfterDays === "number") patch.closeAfterDays = input.closeAfterDays as number | null;
  if (typeof input.spamAutoRejectScore === "number") patch.spamAutoRejectScore = input.spamAutoRejectScore;
  if (typeof input.maxPerIpPerHour === "number") patch.maxPerIpPerHour = input.maxPerIpPerHour;
  if (Object.keys(patch).length === 0) {
    throw new ToolInputError({ message: "at least one of enabled, requireModeration, maxDepth, closeAfterDays, spamAutoRejectScore, maxPerIpPerHour is required" });
  }
  return patch;
}

export function buildCommentsRegistrations(
  routeDeps: CommentsToolDeps,
  surfaces: AssistantSurfaceDeps = { surfaceExchanges: createSurfaceExchangeStore({ scheduler: createTimeoutScheduler({}), clock: createSystemClock(), idGenerator: createRandomUuidGenerator(), defaultChannel: "mcp-ui" }) },
): ToolRegistration[] {
  const providerRegistry = (_required = {}, _options = {}) => {
    if (!routeDeps.commentsProviders) throw new ToolInputError({ message: 'Comments provider service is unavailable.' });
    return routeDeps.commentsProviders;
  };
  const providerPermission = async ({ principalId }: { principalId: string }, _options = {}) => {
    await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId, permission: 'comments.configure' }, { entityType: 'comments-provider' });
    await Promise.all([routeDeps.commentsReady, routeDeps.commentsSettingsReady]);
  };
  const handlers: Record<string, ToolHandler> = {
    comments_get_provider: async ctx => {
      await providerPermission({ principalId: ctx.principal.id });
      const active = await providerRegistry().active({ siteId: routeDeps.workspaceId });
      const settings = await getCommentsSettings({ settingsRepo: routeDeps.settingsRepo }, { workspaceId: routeDeps.workspaceId });
      const ready = !!active.adapter && settings.enabled;
      return { providerId: active.providerId, revision: active.revision, ready,
        pendingCount: await routeDeps.commentRepo.countByStatus({ workspaceId: routeDeps.workspaceId, status: 'pending' }),
        ...(ready ? {} : { note: providerNote({ providerId: active.providerId, adapterReady: !!active.adapter }) }) };
    },
    comments_set_provider: approvalToolHandler({ surfaces,
      prepare: async ({ ctx }) => {
        const input = requireInputRecord({ input: ctx.input });
        refuseUnexpectedKeys(input, ['providerId', 'expectedRevision']);
        if (input.providerId !== null && input.providerId !== 'built-in') throw new ToolInputError({ message: 'Select built-in or null to disable comments.' });
        const expectedRevision = requireNumber({ input, key: 'expectedRevision' });
        if (!Number.isSafeInteger(expectedRevision) || expectedRevision < 0) throw new ToolInputError({ message: 'expectedRevision must be a non-negative integer.' });
        await providerPermission({ principalId: ctx.principal.id });
        const current = await providerRegistry().active({ siteId: routeDeps.workspaceId });
        if (current.revision !== expectedRevision) throw new ToolInputError({ message: 'Comments provider changed; read it again.' });
        return { providerId: input.providerId as string | null, expectedRevision,
          pendingCount: await routeDeps.commentRepo.countByStatus({ workspaceId: routeDeps.workspaceId, status: 'pending' }) };
      },
      describe: ({ prepared }) => ({ toolId: 'comments_set_provider', errorCode: 'COMMENTS', title: 'Change the comments provider?',
        details: [{ label: 'Provider', value: prepared.providerId ?? 'Disabled' }, { label: 'Pending stored comments', value: String(prepared.pendingCount) }],
        warning: 'Switching or disabling hides public stored comments. Stored data and the readable moderation queue are preserved.', confirmLabel: 'Change provider' }),
      run: async ({ ctx, prepared }) => {
        await providerPermission({ principalId: ctx.principal.id });
        const pendingCount = await routeDeps.commentRepo.countByStatus({ workspaceId: routeDeps.workspaceId, status: 'pending' });
        if (pendingCount > prepared.pendingCount) throw new ToolInputError({ message: 'More comments arrived. Review a fresh provider confirmation.' });
        await providerRegistry().select({ siteId: routeDeps.workspaceId, providerId: prepared.providerId, expectedRevision: prepared.expectedRevision, actorPrincipalId: ctx.principal.id });
        return { changed: true, providerId: prepared.providerId };
      },
    }, { flag: 'changed' }),
    /** Reads any status directly; pagination cannot establish that an id is absent. */
    comments_get_comment: async (ctx) => {
      const commentId = requireString({ input: requireInputRecord({ input: ctx.input }), key: "commentId" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "comments.read" }, { entityType: "comment", entityId: commentId });
      await routeDeps.commentsReady;
      const comment = await routeDeps.commentRepo.findById({ workspaceId: routeDeps.workspaceId, id: commentId });
      if (!comment) throw new CommentNotFoundError({ commentId });
      return { comment: toCommentModerationView(comment) };
    },
    comments_list_moderation_queue: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });

      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "comments.read" }, { entityType: "comment" });

      await routeDeps.commentsReady;
      const status: CommentStatus = optionalOneOf({ input, key: "status", values: COMMENT_STATUSES }) ?? "pending";
      const limit = readToolLimit({ input, max: 100, fallback: 20 });
      // A non-string cursor is refused, not read as "no cursor" and page 1.
      const cursor = optionalString({ input, key: "cursor" }) ?? null;
      const page = await routeDeps.commentRepo.listModerationQueue({ workspaceId: routeDeps.workspaceId, status, limit, cursor });
      return toModerationQueueToolView(page);
    },

    comments_get_settings: async (ctx) => {
      // `getCommentsSettings` has no `authorize` in its deps at all (unlike `setCommentsSettings`,
      // which self-enforces via its own `set()` call below) — the GET route gates explicitly
      // before calling it, so this handler mirrors that same explicit call.
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "comments.configure" }, { entityType: "comments-settings" });

      await routeDeps.commentsSettingsReady;
      const settings = await getCommentsSettings({ settingsRepo: routeDeps.settingsRepo }, { workspaceId: routeDeps.workspaceId });
      return { settings };
    },

    comments_update_settings: async (ctx) => {
      const patch = requireCommentsSettingsPatch(requireInputRecord({ input: ctx.input }));

      // No explicit pre-check here, unlike every other Comments handler: `setCommentsSettings`
      // (settings.ts) self-enforces internally — its `set()` call is invoked with
      // `requiredPermissionOverride: 'comments.configure'` HARD-CODED inside settings.ts itself, so
      // passing `authorize: routeDeps.authorize` through is exactly ADR-021 §2's "one evaluator",
      // reached the domain-function way Forms/Identity use, not the explicit-handler way the rest
      // of this file uses. See settings.ts's own comment on that override for why.
      await routeDeps.commentsSettingsReady;
      const settings = await setCommentsSettings(
        {
          settingsRepo: routeDeps.settingsRepo,
          clock: routeDeps.clock,
          ids: routeDeps.idGen,
          authorize: routeDeps.authorize,
          principals: routeDeps.principalRepo,
        },
        { workspaceId: routeDeps.workspaceId, patch, callerPrincipalId: ctx.principal.id },
      ).catch((error: unknown) => {
        if (error instanceof CommentsSettingsValidationError) throw new ToolInputError({ message: error.message });
        throw error;
      });
      return { settings };
    },

    comments_approve_comment: buildCommentsModerationHandler(routeDeps, { permission: "comments.moderate", action: "approve", toStatus: "approved" }),
    comments_mark_comment_spam: buildCommentsModerationHandler(routeDeps, { permission: "comments.moderate", action: "mark_spam", toStatus: "spam" }),

    /** Reversibly trashes a comment through the existing moderation and version checks. */
    comments_trash_comment: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      const commentId = requireString({ input: input, key: "commentId" });
      const expectedVersion = requireNumber({ input, key: "expectedVersion" });

      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "comments.delete" }, { entityType: "comment", entityId: commentId });

      await routeDeps.commentsReady;
      const existing = await routeDeps.commentRepo.findById({ workspaceId: routeDeps.workspaceId, id: commentId });
      if (!existing) throw new CommentNotFoundError({ commentId });

      // Re-check authorization immediately before the service write.
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "comments.delete" }, { entityType: "comment", entityId: commentId });
      const result = await routeDeps.commentWriteService.applyModeration({
        workspaceId: routeDeps.workspaceId,
        id: commentId,
        expectedVersion,
        action: "trash",
        toStatus: "trash",
        actorPrincipalId: ctx.principal.id,
        actorPluginId: ASSISTANT_ACTOR_PLUGIN_ID,
        note: typeof input.note === "string" ? input.note : null,
      });
      if (!result.ok) {
        throw moderationFailureError({ commentId, result });
      }

      return { trashed: true, cancelled: false, moderated: { commentId, toStatus: "trash" } };

    },

    comments_restore_comment: buildCommentsModerationHandler(routeDeps, { permission: "comments.moderate", action: "restore", toStatus: "approved" }),
  };

  // No `unwiredToolIds`: Comments wires its ENTIRE catalog, same tripwire discipline as Forms.
  return buildDomainRegistrations({ metadata: toolMetadata,
    domain: "comments",
    catalogModule: "comments/agent-tools.ts",
    catalog: CATALOG_BY_ID,
    // Wrapped once over the whole map, never per handler — see `withModelFacingErrors`' own doc.
    handlers: withModelFacingErrors({ handlers, rules: COMMENTS_MODEL_FACING_ERRORS }),
    derivedRisk: commentsDerivedRisk,
  });
}

/**
 * Contributes Comments' AI tools to the assistant's catalog — called once by
 * `server/tool-catalog-manifest.ts`'s `installFirstPartyToolContributors()`, not by importing this
 * module. `assistant/tool-registrations.ts` no longer imports `buildCommentsRegistrations`/
 * `commentsDerivedRisk` by name; this is the seam that replaced it (2026-08-17 — see
 * `tool-contribution-registry.ts`'s header for why: this edge used to close a module cycle with
 * `assistant`, and a one-directional `comments -> assistant` registration call does not).
 */
export function contributeCommentsTools(): ToolContributor {
  return { domain: "comments", build: buildCommentsRegistrations, risk: commentsDerivedRisk };
}

/** @file Read-only projection of Jini's denied-visitor gate, never a second classifier. */
import { CONSENT_CATEGORIES, type ConsentConfig } from '@jini-ai/cms/consent';
import { gateConsentHtml } from '@jini-ai/cms/consent/html';
import { parse, type DefaultTreeAdapterMap } from 'parse5';
import type { ConsentProblem } from './validation.js';

type Node = DefaultTreeAdapterMap['childNode'];
export interface ConsentInventoryItem { tag: string; category: string; source: string | null; attributes?: string[] }

/** Remove query/fragment values and URL credentials from diagnostic source labels. O(url length). */
function sourceLabel({ value }: { value: string | undefined }, _options = {}): string | null {
  if (!value) return null;
  try { const url = new URL(value, 'https://site.invalid'); return `${url.origin === 'https://site.invalid' ? '' : url.origin}${url.pathname}`.slice(0, 500); }
  catch { return '[invalid resource URL]'; }
}

/** Project one engine payload; templates contribute only their first element, not its subtree. */
function inventoryItem({ node }: { node: DefaultTreeAdapterMap['element'] }, _options = {}): ConsentInventoryItem | null {
  const attrs = new Map(node.attrs.map(attr => [attr.name, attr.value]));
  if (node.tagName === 'template') {
    if (!attrs.has('data-jini-consent-script') && !attrs.has('data-jini-consent-resource')) return null;
    const child = (node as DefaultTreeAdapterMap['template']).content.childNodes.find((item): item is DefaultTreeAdapterMap['element'] => 'tagName' in item);
    if (!child) return null;
    const source = child.attrs.find(attr => ['src', 'href', 'data', 'poster'].includes(attr.name))?.value;
    return { tag: child.tagName, category: attrs.get('data-category') ?? 'blocked', source: sourceLabel({ value: source }) };
  }
  const payload = attrs.get('data-jini-consent-attributes');
  return payload ? { tag: node.tagName, category: attrs.get('data-jini-consent-category') ?? 'blocked', source: null, attributes: Object.keys(JSON.parse(payload)) } : null;
}

/** Projects engine-created inert templates/attribute payloads, capped at 200 entries.
 * It neither interprets authored category labels nor executes scripts. O(n) gated HTML bytes. */
export function consentGateInventory({ html }: { html: string }, _options = {}): { items: ConsentInventoryItem[]; truncated: boolean } {
  const nodes: Node[] = [...parse(html).childNodes];
  const items: ConsentInventoryItem[] = [];
  let truncated = false;
  while (nodes.length) {
    const node = nodes.pop()!;
    if (!('tagName' in node)) continue;
    const item = inventoryItem({ node });
    if (item) {
      if (items.length === 200) { truncated = true; break; }
      items.push(item);
    }
    if (node.tagName !== 'template') nodes.push(...node.childNodes);
  }
  return { items, truncated };
}

/** The engine gate a dry run renders through (a seam so the fail-closed path is testable). */
export type ConsentDryRunGate = typeof gateConsentHtml;

/** A bounded rendered sample; failures are blocking evidence, never a green readiness result.
 * @param options.gate the engine gate (default `gateConsentHtml`); injectable so the fail-closed path is testable.
 * @example consentDryRun({ html, config })
 * @complexity O(n) time/space for at most 1 MB of rendered HTML. */
export function consentDryRun({ html, config }: { html: string; config: ConsentConfig }, options: { gate?: ConsentDryRunGate } = {}) {
  const problems: ConsentProblem[] = [];
  const gate = options.gate ?? gateConsentHtml;
  try {
    const gated = gate({ html, config: { ...config, enabled: true }, record: null, regionMode: 'opt-in', gpc: false, endpoint: '/api/site-consent' });
    const inventory = consentGateInventory({ html: gated });
    if (inventory.truncated) problems.push({ code: 'INVENTORY_TRUNCATED', message: 'More than 200 gated items. Inspect a smaller page sample.' });
    return { ...inventory, gatedHtml: gated, problems, categories: CONSENT_CATEGORIES.map(id => ({ id, required: id === 'necessary', editable: false })) };
  } catch {
    return { items: [], gatedHtml: null, truncated: false, categories: CONSENT_CATEGORIES.map(id => ({ id, required: id === 'necessary', editable: false })), problems: [{ code: 'GATE_FAILED', message: 'The consent engine could not safely process this page. Optional content stays blocked.' }] };
  }
}

/** @file Visitor-region readers for cookie consent, contributed as DATA by host plugins in
 * {@link CONSENT_CONTRIBUTIONS_FILENAME} (schema 2: one open `contributions` list of `{ kind, id, … }`).
 * Core names no host. Only the plugin that is this site's configured ingress may contribute: a
 * country header from anywhere else can be forged by the visitor. No ingress (Fly, Electron, a
 * static export) means no reader, and every visitor gets the strict banner with Reject.
 *
 * Trust: data-only (no plugin code runs) and loaded for ACTIVE plugins only, so switching a host
 * plugin off stops trusting its header. Kinds this file doesn't know are skipped, not refused. */
import { REGION_SLOT } from '@jini-ai/cookie-consent/server';
import type { RawContribution, RegionResolver } from '@jini-ai/cookie-consent';
import type { LoadPluginContributions, PluginContributionDefinition } from '../agent-plugins/lifecycle.js';

/** The file a plugin ships at its root to contribute cookie-consent pieces. */
export const CONSENT_CONTRIBUTIONS_FILENAME = 'tovu-consent.json';

/** Parse one schema-2 file into its region-reader entries. Pure. @complexity O(entries). */
export function parseConsentContributions({ raw }: { raw: string }, _optional = {}): { ok: true; descriptors: RawContribution[] } | { ok: false; reason: string } {
  let file: unknown;
  try { file = JSON.parse(raw); } catch { return { ok: false, reason: 'not JSON' }; }
  const { schemaVersion, contributions } = (file ?? {}) as { schemaVersion?: unknown; contributions?: unknown };
  if (schemaVersion !== 2 || !Array.isArray(contributions)) return { ok: false, reason: 'expected { "schemaVersion": 2, "contributions": [...] }' };
  const descriptors = contributions.filter((item): item is RawContribution =>
    Boolean(item) && typeof item === 'object' && typeof item.id === 'string' && item.kind === 'region-resolver');
  return { ok: true, descriptors };
}

type PluginRegion = { pluginId: string; entry: RawContribution };
const regionContribution: PluginContributionDefinition<RawContribution, PluginRegion> = {
  filename: CONSENT_CONTRIBUTIONS_FILENAME, contribution: 'cookie consent region readers', kind: 'data',
  parse: parseConsentContributions,
  load: ({ plugin, descriptor }) => ({ pluginId: plugin.pluginId, entry: descriptor }),
  onReadError: ({ error }) => (error as NodeJS.ErrnoException).code === 'ENOENT' ? [] : undefined,
};

/** Turn data entries into resolvers through the package's own trust boundary; refused entries drop.
 * `legacyHeader` absorbs the older TOVU_CONSENT_REGION_HEADER setting as one more header reader.
 * @complexity O(entries). */
export function toRegionResolvers({ entries }: { entries: readonly RawContribution[] }, { legacyHeader }: { legacyHeader?: string | undefined } = {}): RegionResolver[] {
  const all = legacyHeader ? [...entries, { kind: 'region-resolver', id: 'configured-header', header: legacyHeader }] : entries;
  return all.flatMap(contribution => {
    const accepted = REGION_SLOT.accept({ contribution });
    return typeof accepted === 'string' ? [] : [accepted];
  });
}

/** This site's region readers: the configured ingress plugin's entries (when active), then the legacy
 * header. A plugin fault leaves the site strict; it never fails a page. @complexity O(p) plugins. */
export async function loadSiteRegionResolvers(
  { workspaceId, loadContributions }: { workspaceId: string; loadContributions: LoadPluginContributions },
  { ingress, legacyHeader }: { ingress?: string | undefined; legacyHeader?: string | undefined } = {},
): Promise<RegionResolver[]> {
  let entries: RawContribution[] = [];
  if (ingress) {
    try {
      const load = await loadContributions({ workspaceId, definition: regionContribution }, { requireActive: true });
      entries = load.items.flatMap(item => (item.pluginId === ingress ? [item.entry] : []));
    } catch { console.error('[consent] region readers could not be loaded; visitors get the strict banner'); }
  }
  return toRegionResolvers({ entries }, { legacyHeader });
}

/** @file Shared site consent use cases for HTTP and assistant adapters. */
import type { ConsentConfig } from '@jini-ai/cms/consent';
import type { ConsentReceiptStorageHealth } from '@jini-ai/cms/consent/node';
import { adaptLegacyAuthorize, requireToolPermission } from '@jini-ai/cms/core';
import { ToolInputError } from '@jini-ai/core';
import type { AuthorizeFn } from '#src/contracts/core/commands/index';
import type { SiteConsentState, SiteConsentStore } from './revisions.js';
import { SiteConsentConflict } from './revisions.js';
import { consentConfigProblems, parseConsentConfig, type ConsentProblem } from './validation.js';
import { CONSENT_CATEGORIES, CONSENT_MAX_AGE_MS, CONSENT_MAX_CSS_LENGTH, CONSENT_CSS_SELECTORS } from '@jini-ai/cms/consent';
import { SITE_CONSENT_BANNER_MODES, SITE_CONSENT_DEFAULT_CSS, SITE_CONSENT_DEFAULTS, SITE_CONSENT_PLACEMENTS, SITE_CONSENT_TEXT_LIMITS, withSiteConsentDefaultCss } from './config.js';
import { consentPagePath } from './request.js';
import { consentDryRun, type ConsentDryRunGate } from './readiness.js';
import { renderSiteConsentPreview } from './cookie-consent.js';

export interface ConsentServicePorts {
  workspaceId: string;
  authorize: AuthorizeFn;
  store?: SiteConsentStore;
  ready: Promise<void>;
  clock: { nowIso(): string };
  ids: { newId(): string };
  trustedRegion: boolean;
  readLegacy(required: Record<string, never>, optional?: Record<string, never>): Promise<ConsentConfig>;
  /** True when no owner on/off choice exists, so `readLegacy().enabled` is only the product default. */
  defaultOnly(required: Record<string, never>, optional?: Record<string, never>): Promise<boolean>;
  privacyPageExists(required: { url: string }, optional?: Record<string, never>): Promise<boolean>;
  renderPage(required: { path: string }, optional?: Record<string, never>): Promise<{ html: string; ok: boolean; truncated: boolean }>;
  /** Inspect the live receipt backend without saving a visitor choice; errors block readiness. */
  receiptStorage(required: Record<string, never>, optional?: Record<string, never>): Promise<ConsentReceiptStorageHealth>;
  /** The engine consent gate used by dry runs; omitted means the real `gateConsentHtml`. */
  consentGate?: ConsentDryRunGate;
  /** Set when `@jini-ai/cookie-consent` serves the site: banner modes are editable, a bad CSS rule is
   * dropped alone instead of blocking, and static exports carry the banner. TODO(P4): always on. */
  cookieConsent?: boolean;
}

/** Unsaved input takes precedence over the draft, then the effective published/legacy policy.
 * An emptied Custom CSS previews the default style, exactly as the public site delivers it. */
function sampleConsentConfig({ state, proposed }: { state: SiteConsentState & { effective: ConsentConfig }; proposed: unknown }, _options = {}): ConsentConfig {
  return withSiteConsentDefaultCss({ config: parseConsentConfig({ value: proposed === undefined ? state.draft?.config ?? state.effective : proposed }) });
}

/** Readiness and preview require the same complete bounded page evidence. */
function isCompleteConsentPage({ page }: { page: { ok: boolean; truncated: boolean } }, _options = {}): boolean {
  return page.ok && !page.truncated;
}

/** The legacy ledger allowed empty or longer copy; editor reads must let the owner repair it.
 * Defaults replace only out-of-range text in a copy; published policies and writes stay strict.
 * @complexity O(n) text length across seven bounded legacy fields; no storage writes. */
function legacyEditorConsentConfig({ config }: { config: ConsentConfig }, _options = {}): ConsentConfig {
  const normalized = { ...config };
  const limits = { ...SITE_CONSENT_TEXT_LIMITS, policyVersion: 64 };
  for (const key of Object.keys(limits) as (keyof typeof limits)[]) {
    const text = normalized[key];
    if (typeof text !== 'string') continue;
    const emptyAllowed = key === 'secondaryLinkLabel' && text.length === 0;
    if (text.length > limits[key] || (!emptyAllowed && !text.trim())) normalized[key] = SITE_CONSENT_DEFAULTS[key];
  }
  return normalized;
}

/** Creates one workspace's adapters over the engine and durable policy store.
 * Authorization remains in each operation so direct/tool callers cannot bypass the HTTP guard.
 * @example createSiteConsentService({ ports })
 * @complexity Fixed repository operations; readiness scans receipt filenames and renders one bounded page, never executes JS. */
export function createSiteConsentService({ ports }: { ports: ConsentServicePorts }, _options = {}) {
  /** Deny before touching readiness, configuration or rendered content. */
  const authorize = async ({ principalId, write = false }: { principalId: string; write?: boolean }, _optional = {}) => {
    await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: ports.authorize }), principalId, workspaceId: ports.workspaceId, permission: write ? 'settings.workspace.write' : 'settings.read' }, { entityType: 'site-consent' });
    await ports.ready;
    if (!ports.store) throw new Error('The durable site consent policy store is unavailable.');
    return ports.store;
  };
  /** Resolve draft and published separately; malformed published data never falls back to OFF. */
  const read = async ({ principalId }: { principalId: string }, _optional = {}) => {
    const store = await authorize({ principalId });
    const state = await store.read({});
    const legacy = state.published ? null : legacyEditorConsentConfig({ config: await ports.readLegacy({}) });
    // An empty Custom CSS is what the public site fills with the default style, so the editor shows
    // that default in the field for the owner to edit (owner, 2026-10-22).
    const draft = state.draft && { ...state.draft, config: withSiteConsentDefaultCss({ config: state.draft.config }) };
    return { ...state, draft, effective: withSiteConsentDefaultCss({ config: parseConsentConfig({ value: state.published?.config ?? legacy }) }), categoriesEditable: false,
      editor: { defaults: { ...SITE_CONSENT_DEFAULTS, customCss: SITE_CONSENT_DEFAULT_CSS }, placements: [...SITE_CONSENT_PLACEMENTS], textLimits: { ...SITE_CONSENT_TEXT_LIMITS },
        maxCssLength: CONSENT_MAX_CSS_LENGTH, cssSelectors: [...CONSENT_CSS_SELECTORS],
        regionModes: ['opt-in', 'auto'], ...(ports.cookieConsent ? { bannerModes: [...SITE_CONSENT_BANNER_MODES] } : {}),
        categories: CONSENT_CATEGORIES.map(id => ({ id, required: id === 'necessary', editable: false })),
        rules: { gpc: 'always-enforced', preferenceMaxAgeMs: CONSENT_MAX_AGE_MS, staticReceipts: false } } };
  };
  /** Engine validation plus this site's privacy-page linkage; no HTTP fetch to external policies. */
  const problems = async ({ config }: { config: ConsentConfig }, _optional = {}): Promise<ConsentProblem[]> => {
    const found = consentConfigProblems({ config, trustedRegion: ports.trustedRegion }, { cssBlocks: !ports.cookieConsent });
    if (config.enabled && config.privacyPolicyUrl && !found.some(problem => problem.field === 'privacyPolicyUrl') && !await ports.privacyPageExists({ url: config.privacyPolicyUrl })) found.push({ code: 'PRIVACY_PAGE_MISSING', field: 'privacyPolicyUrl', message: 'Publish the linked privacy page before enabling consent.' });
    return found;
  };
  /** Readiness needs writable proof storage as well as a safe local page sample.
   * Storage errors expose no private paths; render failure/truncation also blocks readiness. */
  const readiness = async ({ principalId, path = '/', config: proposed }: { principalId: string; path?: string; config?: unknown }, _optional = {}) => {
    const state = await read({ principalId });
    const config = sampleConsentConfig({ state, proposed });
    path = consentPagePath({ path });
    const blockingProblems = await problems({ config: { ...config, enabled: true } });
    let receipts: ConsentReceiptStorageHealth;
    try { receipts = await ports.receiptStorage({}); }
    catch { receipts = { writable: false, count: null }; }
    if (!receipts.writable || receipts.count === null) blockingProblems.push({ code: 'RECEIPT_STORAGE_UNAVAILABLE', message: 'Consent receipt storage is unavailable or not writable. Visitor choices cannot be saved reliably.' });
    // `config` came through parseConsentConfig, which refuses a config without a string placement,
    // so no default placement is needed here.
    const metadata = { receipts, enabled: state.effective.enabled, placement: config.placement, regionMode: config.regionMode, delivery: 'live', staticSupported: false, sampledPaths: [path], sampleOnly: true, blockingProblems };
    try {
      const page = await ports.renderPage({ path });
      if (!isCompleteConsentPage({ page })) blockingProblems.push({ code: 'PAGE_UNAVAILABLE', message: 'The rendered page is unavailable or exceeds the 1 MB audit limit.' });
      const dryRun = consentDryRun({ html: page.html, config }, { gate: ports.consentGate });
      blockingProblems.push(...dryRun.problems);
      return { ...metadata, ready: blockingProblems.length === 0, categories: dryRun.categories, detected: dryRun.items, truncated: dryRun.truncated || page.truncated,
        limitations: ['One server-rendered page sample; dynamic requests, server cookies and legal compliance require separate review.'] };
    } catch {
      blockingProblems.push({ code: 'RENDER_FAILED', message: 'The page could not be rendered safely. Readiness cannot be established.' });
      return { ...metadata, ready: false, categories: CONSENT_CATEGORIES.map(id => ({ id, required: id === 'necessary', editable: false })), detected: [], truncated: false, limitations: ['Rendered evidence unavailable.'] };
    }
  };
  /** Render the real gated page into an inert iframe document for the separate admin UI.
   * Returned HTML must only be used in a sandbox without scripts, forms or same-origin access.
   * The cookie-consent renderer also returns dropped-style warnings, separate from blockers. */
  const preview = async ({ principalId, path = '/', config: proposed }: { principalId: string; path?: string; config?: unknown }, _optional = {}) => {
    const state = await read({ principalId });
    const config = sampleConsentConfig({ state, proposed });
    path = consentPagePath({ path });
    const page = await ports.renderPage({ path });
    if (!isCompleteConsentPage({ page })) throw new ToolInputError({ message: 'Preview requires one complete rendered page of at most 1 MB.' });
    const result = consentDryRun({ html: page.html, config }, { gate: ports.consentGate });
    if (result.gatedHtml === null) throw new ToolInputError({ message: 'The consent engine could not safely render the preview.' });
    const diagnostics = ports.cookieConsent ? { warnings: renderSiteConsentPreview({ config, policy: config.policyVersion }).problems.map(problem => ({ ...problem, field: 'appearance' })) } : {};
    return { html: result.gatedHtml, blockingProblems: [...await problems({ config }), ...result.problems], ...diagnostics, sandbox: '', revisionId: state.draft?.id ?? state.published?.id ?? null };
  };
  /** Append an immutable draft; the legacy engine blocks invalid CSS, cookie-consent drops it. */
  const saveDraft = async ({ principalId, config: value, expectedDraftId }: { principalId: string; config: unknown; expectedDraftId: string | null }, _optional = {}) => {
    const store = await authorize({ principalId, write: true });
    const config = parseConsentConfig({ value });
    const blockingProblems = await problems({ config });
    const revision = { id: ports.ids.newId(), config, actorId: principalId, createdAt: ports.clock.nowIso() };
    await store.saveDraft({ revision, expectedDraftId });
    return { revision, blockingProblems };
  };
  /** The stored draft, never caller replacement fields, is what becomes public atomically. */
  const publish = async ({ principalId, draftId, expectedPublishedId }: { principalId: string; draftId: string; expectedPublishedId: string | null }, _optional = {}) => {
    const store = await authorize({ principalId, write: true });
    const state = await store.read({});
    if (state.draft?.id !== draftId) throw new SiteConsentConflict();
    const config = parseConsentConfig({ value: state.draft.config });
    const blockingProblems = await problems({ config });
    if (blockingProblems.length) throw new ToolInputError({ message: blockingProblems.map(problem => problem.message).join(' ') });
    await store.publish({ draftId, expectedPublishedId });
    return { published: true, revisionId: draftId };
  };
  const staticDeploymentRefusal = async ({ config }: { config: ConsentConfig }, _options = {}) => {
    const blockingProblems = await problems({ config });
    // The cookie-consent banner works on a static host (choices kept in the browser, labelled so).
    if (ports.cookieConsent) return blockingProblems.length ? deploymentRefusal({ problems: blockingProblems }) : null;
    blockingProblems.push({ code: 'STATIC_RECEIPTS_UNAVAILABLE', message: 'Static delivery cannot save consent receipts. Keep the banner on a live server, or explicitly publish with the banner disabled.' });
    return deploymentRefusal({ problems: blockingProblems });
  };
  /** Static publication has no receipt backend. A choice offers existing settings APIs, never a bypass.
   * Unknown configuration is blocking; OFF must be explicitly readable before exporting. */
  const deploymentCheck = async ({ principalId, permission }: { principalId: string; permission: 'system.publish' | 'deployments.publish' }, _optional = {}) => {
    await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: ports.authorize }), principalId, workspaceId: ports.workspaceId, permission }, { entityType: 'site-publish' });
    try {
      await ports.ready;
      if (!ports.store) throw new Error('Consent store unavailable');
      const state = await ports.store.read({});
      // Default-only consent (no owner choice, nothing published) exports without the banner, as the
      // export crawl skips it (site-consent.ts isDefaultOnlyConsent); live serving keeps it on.
      if (!state.published && await ports.defaultOnly({})) return null;
      const effective = state.published?.config ?? await ports.readLegacy({});
      // Explicit OFF remains a rollback even when saved legacy copy exceeds today's editor limits.
      if (effective.enabled === false) return null;
      const config = parseConsentConfig({ value: effective });
      return await staticDeploymentRefusal({ config });
    } catch {
      return deploymentRefusal({ problems: [{ code: 'CONSENT_UNAVAILABLE', message: 'The published consent policy could not be verified. Deployment was not started.' }] });
    }
  };
  return { read, readiness, preview, saveDraft, publish, deploymentCheck };
}
export type SiteConsentService = ReturnType<typeof createSiteConsentService>;

/** The existing HTTP 409 / choice envelope; clients perform a reviewed settings publication, then retry.
 * Keeping the choice declarative prevents an untrusted flag from disabling consent in a crawler. */
export function deploymentRefusal({ problems }: { problems: ConsentProblem[] }, _options = {}) {
  return { code: 'CONSENT_REVIEW_REQUIRED', error: 'Review cookie consent before publishing this site.', blockingProblems: problems,
    choices: [
      { id: 'fix-now', label: 'Fix now', href: '/consent?tab=overview', action: 'Review readiness and use live hosting while consent is enabled.' },
      { id: 'publish-without-banner', label: 'Publish without banner', href: '/consent?tab=rules&intent=publish-without-banner', action: 'Explicitly save enabled:false through PUT consent/settings, POST consent/publish with current revision ids, then retry deployment.', warning: 'This disables the banner and optional-content enforcement on the live site too. Optional scripts may run without a visitor choice.' },
    ] };
}

/** @file Tovu owns the persistent withdrawal link; Jini owns the preferences UI and lifecycle. */
import { parse, type DefaultTreeAdapterMap } from 'parse5';

type Node = DefaultTreeAdapterMap['childNode'];
type Element = DefaultTreeAdapterMap['element'];
/** Which consent engine delivered the page: the old one marks its runtime; cookie-consent emits its
 * config script and opens on `data-consent-open`. TODO(P4): drop 'legacy'. */
type Engine = 'legacy' | 'cookie-consent';
const ANCHORS: Readonly<Record<Engine, string>> = {
  legacy: '<a href="#jini-consent" data-jini-consent-open>Cookie settings</a>',
  'cookie-consent': '<a href="#privacy-choices" data-consent-open>Cookie settings</a>',
};
// In a footer the link joins the theme's last row (the "© Site" line) and takes that row's text
// style; a centred row of its own read as stray. The margin only matters in a non-flex row.
const inlineLink = (anchor: string) => `<span data-tovu-consent-settings style="margin-inline-start:1em">${anchor}</span>`;
// A footerless page has no row to join; a centred row needs no theme container class to line up.
const rowLink = (anchor: string) => `<p data-tovu-consent-settings style="margin:0;padding:0 1rem 1.25rem;text-align:center;font-size:0.8125rem">${anchor}</p>`;
/** A theme's own live control for this engine: then the page never shows two links. */
const ownControl = ({ engine, tag, attrs }: { engine: Engine; tag: string; attrs: Map<string, string> }) => engine === 'legacy'
  ? attrs.has('data-jini-consent-open') : attrs.has('data-consent-open') || (tag === 'a' && attrs.get('href') === '#privacy-choices');

/** Legacy only: the engine's own section says whether it reopens through a link; undefined for any other
 * element. TODO(P4): delete with the legacy engine. */
const legacyReopensByLink = ({ engine, tag, attrs }: { engine: Engine; tag: string; attrs: Map<string, string> }) =>
  engine === 'legacy' && tag === 'section' && attrs.get('id') === 'jini-consent' ? attrs.get('data-reopen') === 'link' : undefined;

/** Only live, non-hidden markup can host a withdrawal control. O(n) nodes, iterative for deep HTML. */
function* liveElements({ html }: { html: string }, _options = {}): Generator<Element> {
  const nodes: Node[] = [...parse(html, { sourceCodeLocationInfo: true }).childNodes];
  while (nodes.length) {
    const node = nodes.pop()!;
    if (!('tagName' in node) || node.tagName === 'template' || node.attrs.some(attr => attr.name === 'hidden')) continue;
    yield node;
    for (const child of node.childNodes) nodes.push(child);
  }
}

/** HTML may omit a footer's closing tag; parse5 still identifies the end of its content. */
function contentEnd({ node }: { node: Element }, { fallback = -1 }: { fallback?: number } = {}): number {
  return node.sourceCodeLocation?.endTag?.startOffset ?? node.sourceCodeLocation?.endOffset ?? fallback;
}

/** The footer's bottom row: follow last-child `<div>`s down (`.wrap > .footer-bottom` in the
 * starter theme). A footer that ends in anything else is its own last row. O(footer nodes). */
function lastRow({ footer }: { footer: Element }, _options = {}): Element {
  let row = footer;
  for (;;) {
    const last = [...row.childNodes].reverse().find((child): child is Element => 'tagName' in child);
    if (last?.tagName !== 'div' || last.attrs.some(attr => attr.name === 'hidden')) return row;
    row = last;
  }
}

/** Keep the footer whose content ends last, including implicitly closed markup. */
function laterFooter({ node, footer }: { node: Element; footer: Element | null }, _options = {}): Element | null {
  if (node.tagName !== 'footer') return footer;
  return contentEnd({ node }) > (footer ? contentEnd({ node: footer }) : -1) ? node : footer;
}

/** Locate the live engine UI and the theme's footer/body insertion point in one parse.
 * The last-ending footer is the page footer: article/card footers close before it. A theme that
 * already ships its own live control keeps it alone, so the page never shows two links. */
function linkPlacement({ html }: { html: string }, { engine = 'legacy' }: { engine?: Engine } = {}): { enabled: boolean; offset: number; inline: boolean } {
  // cookie-consent: Tovu rendered the banner in link mode (or the owner's own banner), so the page needs the link.
  let enabled = engine === 'cookie-consent';
  let footer: Element | null = null;
  let bodyEnd = html.length;
  for (const node of liveElements({ html })) {
    const attrs = new Map(node.attrs.map(attr => [attr.name, attr.value]));
    if (ownControl({ engine, tag: node.tagName, attrs })) return { enabled: false, offset: 0, inline: false };
    enabled = legacyReopensByLink({ engine, tag: node.tagName, attrs }) ?? enabled;
    footer = laterFooter({ node, footer });
    if (node.tagName === 'body') bodyEnd = contentEnd({ node }, { fallback: bodyEnd });
  }
  if (!footer) return { enabled, offset: bodyEnd, inline: false };
  return { enabled, offset: contentEnd({ node: lastRow({ footer }) }), inline: true };
}

/** Add the host control only to HTML actually gated by Jini in link mode (legacy) or carrying the
 * cookie-consent config (Tovu renders that banner in link mode), once per page.
 * Source offsets preserve SEO and theme bytes; implicit bodies append the control. Jini has
 * already bounded and buffered this response. No config read competes with its lastGood policy.
 * @complexity O(n) time/space for n HTML bytes; no I/O. */
export function withSiteConsentSettingsLink({ html }: { html: string }, { engine = 'legacy' }: { engine?: Engine } = {}): string {
  if (!html.includes(engine === 'legacy' ? 'data-jini-consent-runtime' : 'id="jini-consent-config"')) return html;
  const { enabled, offset, inline } = linkPlacement({ html }, { engine });
  if (!enabled) return html;
  const anchor = ANCHORS[engine];
  return html.slice(0, offset) + (inline ? inlineLink(anchor) : rowLink(anchor)) + html.slice(offset);
}

import { CustomCredentialValidationError } from "./store.js";

/**
 * @file The one place a token typed or pasted into a credential card is cleaned before the store
 * validates it. Copying a key from a provider's dashboard often brings a trailing newline or space,
 * and from some web pages an invisible zero-width character that `String.prototype.trim` keeps
 * (2026-10-22: a pasted key was refused with the raw "visible ASCII (0x21–0x7E)" rule). Edge junk is
 * dropped; the interior is never rewritten, so a real stray character still refuses, in words a
 * person can act on.
 */

/** Whitespace plus the zero-width characters (ZWSP, ZWNJ, ZWJ, word joiner, BOM) `trim` keeps. */
const EDGE_JUNK = /^[\s​-‍⁠﻿]+|[\s​-‍⁠﻿]+$/gu;

/** Shown instead of the store's byte-range rule when a cleaned token still has a non-visible-ASCII character. */
export const TOKEN_PASTE_AGAIN_MESSAGE = "The token has a space, line break or special character in it — paste it again.";

/**
 * Strips leading and trailing whitespace and zero-width characters from a card-submitted token.
 *
 * @param required - The raw submitted token.
 * @returns The token without edge junk; an all-junk token returns "" for the store's blank rule.
 * @throws CustomCredentialValidationError with {@link TOKEN_PASTE_AGAIN_MESSAGE} when an interior
 *   character is outside visible ASCII. The message never quotes the token.
 * @complexity O(n) in the token length.
 */
export function cleanCardToken({ token }: { token: string }, _optional = {}): string {
  const cleaned = token.replace(EDGE_JUNK, "");
  if (/[^\x21-\x7e]/.test(cleaned)) throw new CustomCredentialValidationError(TOKEN_PASTE_AGAIN_MESSAGE);
  return cleaned;
}

import { buildDomainRegistrations, indexCatalogById, ToolInputError,
  type AgentToolDefinition, type DerivedRiskByToolId, type ToolRegistration, type SurfaceMessage } from '@jini-ai/core';
import { requireToolPermission, adaptLegacyAuthorize, ForbiddenError, type AuthorizeFn } from '@jini-ai/cms/core';
import type { InstanceAuthorizeFn } from '@jini-ai/core/gated-mutations';
import type { VaultKind, VaultCopyResult } from '@jini-ai/platform/secrets/credential-sets';
import { askThenReport, SURFACE_DISMISSED_PARAM, SURFACE_EXCHANGE_ID_PARAM,
  type AssistantSurfaceDeps } from '@jini-ai/daemon/surface-exchanges';
import { buildFormSurface, buildOutcomeSurface, type FormSurfaceSpec, type UIResource, type UIResourceUri } from '@jini-ai/ui/mcp-ui/surfaces';
import { toolMetadata } from '../../contracts/core/tool-metadata/custom-credentials.js';

export const CREDENTIAL_COPY_TOOL_ID = 'credential_copy_from_project';
type SourceChoice = { siteId: string; name: string; reasonCode?: string; message?: string;
  keys: { kind: VaultKind; id: string; label: string; provider: string | null; last4?: string; worksFor: string[]; publishHosts?: string[] }[] };

/** Allowlisted local discovery for model results. No key IDs, hints, paths or envelope fields.
 * No I/O or mutation; O(sites + keys + host IDs) time and space.
 */
export function summarizeCredentialSources({ sources }: { sources: readonly SourceChoice[] }, _options = {}) {
  return sources.map(source => ({ siteId: source.siteId, name: source.name,
    ...(source.reasonCode ? { reasonCode: source.reasonCode } : {}),
    keys: source.keys.map(key => ({ kind: key.kind, label: key.label, provider: key.provider,
      worksFor: [...(key.worksFor ?? [])], publishHosts: [...(key.publishHosts ?? [])] })) }));
}
/** Structural C2 port: inventory eligibility, source re-resolution, CAS and resealing have one owner. */
export interface CredentialCopyToolDeps {
  readonly workspaceId: string;
  readonly ownerPrincipalId: Promise<string>;
  readonly authorize: AuthorizeFn;
  readonly gatedMutations: { gatewayDeps: { authorizeInstance?: InstanceAuthorizeFn } };
  readonly localCredentialCopy?: {
    localHost: boolean;
    list(required: Record<string, never>, optional?: Record<string, never>): Promise<SourceChoice[]>;
    copy(required: { sourceSiteId: string; ids: readonly string[]; overwrite: boolean; actorId: string },
      optional?: Record<string, never>): Promise<VaultCopyResult[]>;
  };
}
export const catalog: AgentToolDefinition[] = [{ name: CREDENTIAL_COPY_TOOL_ID,
  description: 'Copy saved keys from another registered local Tovu project into this project. Call when the owner wants to reuse another project’s keys. ' +
    'Opens a human card to choose the source, keys and optional Overwrite; waits for copy, cancel or expiry. Accepts no model-supplied selection or secrets. ' +
    'Returns secret-free kind, id, status and optional last4/reasonCode. Requires the local installation owner and system.write; sources needing upgrade must be started normally first.',
  sideEffects: 'mutates-durable-state', authorization: { permission: 'system.write' },
  inputSchema: { type: 'object', additionalProperties: false, properties: {} } }];
export const credentialCopyDerivedRisk: DerivedRiskByToolId = new Map([[CREDENTIAL_COPY_TOOL_ID, 'mutates-durable-state']]);
const failureMessages: { 'copy-failed': string; [reasonCode: string]: string } = {
  'copy-refused': 'Copy is no longer authorized.', 'copy-failed': 'Copying keys failed. Try again.',
  'invalid-selection': 'Choose an available source and its keys.', 'source-unavailable': 'The source is no longer available.',
  'source-missing': 'A selected key is no longer available. Choose it again.', 'source-busy': 'The source is busy. Try again.',
  'source-key-unavailable': 'Recover this source site’s key in Tovu, then copy.',
  'source-unsupported': 'Only local SQLite sources are supported.',
};

/** Require current owner, workspace RBAC, instance admission and explicit local capability.
 * Throws a fixed input/permission error before discovery or mutation. O(1), two admission calls.
 */
async function admit({ deps, principalId }: { deps: CredentialCopyToolDeps; principalId: string }, _optional = {}): Promise<void> {
  if (principalId !== await deps.ownerPrincipalId) throw new ToolInputError({ message: 'Use the installation owner’s session to copy keys.' });
  await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }),
    workspaceId: deps.workspaceId, principalId, permission: 'system.write' });
  const instance = deps.gatedMutations.gatewayDeps.authorizeInstance;
  if (instance && !(await instance({ principalId, permission: 'system.write' })).allowed) {
    throw new ToolInputError({ message: 'Copy is not authorized for this installation.' });
  }
  if (!deps.localCredentialCopy?.localHost) throw new ToolInputError({ message: 'Copy keys on a local Tovu host.' });
}

/** Jini owns controls/bridge; product CSS makes the native picker inline and actions right-aligned.
 * No interpolated CSS or new form lifecycle. O(fields + document length); returns a fresh resource.
 */
function form({ uri, exchangeId, fields, submitLabel }: {
  uri: UIResourceUri; exchangeId: string; fields: FormSurfaceSpec['fields']; submitLabel: string;
}, _optional = {}): UIResource {
  const resource = buildFormSurface({ uri, title: 'Copy keys from another project', fields, submitLabel,
    toolName: CREDENTIAL_COPY_TOOL_ID, baseParams: { [SURFACE_EXCHANGE_ID_PARAM]: exchangeId },
    cancel: { label: 'Cancel', toolName: CREDENTIAL_COPY_TOOL_ID,
      params: { [SURFACE_EXCHANGE_ID_PARAM]: exchangeId, [SURFACE_DISMISSED_PARAM]: true } },
    // Start compact; Jini's shared bridge fits the body on load and content changes.
    preferredFrameSize: ['100%', '1px'] });
  return { ...resource, resource: { ...resource.resource, text: resource.resource.text.replace('</head>',
    '<style>.mcpui-field:has(select){flex-direction:row;align-items:center;gap:8px}' +
    '.mcpui-select{width:auto;max-width:75%}.mcpui-actions{justify-content:flex-end}</style></head>') } };
}

/** Terminal exchange answers never imply consent; O(1), no effects. */
function ended({ answer, aborted }: { answer: SurfaceMessage; aborted: boolean }, _optional = {}): string | undefined {
  if (aborted) return 'abandoned';
  if (answer.status !== 'received') return answer.status;
  if (answer.params[SURFACE_DISMISSED_PARAM] === true) return 'cancelled';
  return undefined;
}

/** Validate the entire batch against the shown inventory, with a 100-key cap; O(keys + ids).
 * A forged key mixed with valid ones refuses all of them. No I/O or input mutation.
 */
function selection({ params, source }: { params: Record<string, unknown>; source: SourceChoice }, _optional = {}):
  { ids: string[]; overwrite: boolean } | undefined {
  const { ids, overwrite } = params;
  const allowed = new Set(source.keys.map(key => key.id));
  if (Object.keys(params).some(key => !['ids', 'overwrite', SURFACE_EXCHANGE_ID_PARAM].includes(key)) ||
    !Array.isArray(ids) || ids.length < 1 || ids.length > 100 || new Set(ids).size !== ids.length ||
    !ids.every((id: unknown) => typeof id === 'string' && allowed.has(id)) || typeof overwrite !== 'boolean') return undefined;
  return { ids, overwrite };
}

function validateCopyInput({ input }: { input: unknown }, _options = {}): void {
  if (!input || typeof input !== 'object' || Array.isArray(input) || Object.keys(input).length) {
    throw new ToolInputError({ message: 'Choose the source and keys in the human card; model input must be {}.' });
  }
}

function keyFields({ source }: { source: SourceChoice }, _options = {}): FormSurfaceSpec['fields'] {
  return [
    { kind: 'multi-enum', name: 'ids', label: 'Keys', required: true, options: source.keys.map(key => ({
      value: key.id, label: `${key.label} · ${key.provider ?? key.kind}${key.last4 ? ` · …${key.last4}` : ''}` +
        ` · Works for: ${(key.worksFor ?? []).join(', ') || 'none'}` +
        (key.publishHosts === undefined ? '' : key.publishHosts.length
          ? ` · Publish: ${key.publishHosts.join(', ')}` : ' · No static publish host') })) },
    { kind: 'boolean', name: 'overwrite', label: 'Overwrite existing', value: false },
  ];
}

function copyOutcome({ copied, source, uri }: {
  copied: VaultCopyResult[]; source: SourceChoice; uri: UIResourceUri;
}, _options = {}) {
  // Allowlist projection: neither unexpected payload fields nor exceptions reach model/card.
  const results = copied.map(({ kind, id, status, last4, reasonCode }) => ({ kind, id, status,
    ...(last4 ? { last4: last4.slice(-4) } : {}), ...(reasonCode ? { reasonCode } : {}) }));
  const keysById = new Map(source.keys.map(key => [key.id, key]));
  const failed = results.some(row => row.status === 'failed');
  return { result: { results }, outcome: { channel: 'mcp-ui' as const, payload: { resource: buildOutcomeSurface({ uri, preferredFrameSize: ['100%', '1px'], title: 'Copy results',
    state: failed ? (results.some(row => row.status === 'copied') ? 'partial' : 'failure') : 'success', message: '',
    details: results.map(row => {
      const key = keysById.get(row.id);
      return { label: key?.label ?? row.kind,
        description: `${row.kind}${key?.provider ? ` · ${key.provider}` : ''}`, format: 'status',
        value: row.status === 'copied' ? `copied ✓${row.last4 ? ` …${row.last4}` : ''}`
          : row.reasonCode === 'target-exists' ? 'skipped — already there' : `not copied — ${row.reasonCode ?? 'copy-failed'}` };
    }) }) } } };
}

/** Register one human-only selection flow. C2 owns all storage effects and fresh revision checks.
 * @param required - Injected C2/admission ports and the daemon's principal-bound exchanges.
 * @returns One tool registration; results contain only safe summaries or a fixed refusal code.
 * @example buildCredentialCopyRegistrations({ deps, surfaces });
 * @complexity O(sources + keys + results), plus C2 inventory/copy I/O; selection is capped at 100.
 */
export function buildCredentialCopyRegistrations({ deps, surfaces }: {
  deps: CredentialCopyToolDeps; surfaces: AssistantSurfaceDeps;
}, _optional = {}): ToolRegistration[] {
  return buildDomainRegistrations({ metadata: toolMetadata, domain: 'credential-copy',
    catalogModule: 'features/custom-credentials/credential-copy-tool.ts', catalog: indexCatalogById({ catalog }),
    derivedRisk: credentialCopyDerivedRisk, handlers: { [CREDENTIAL_COPY_TOOL_ID]: async (ctx, options = {}) => {
      validateCopyInput({ input: ctx.input });
      if (!options.emitSurface) throw new ToolInputError({ message: 'Copying keys requires an interactive card.' });
      await admit({ deps, principalId: ctx.principal.id });
      if (ctx.signal.aborted) return { results: [], reasonCode: 'abandoned' };
      let sources: SourceChoice[];
      try { sources = await deps.localCredentialCopy!.list({}); }
      catch { throw new ToolInputError({ message: failureMessages['copy-failed'] }); }
      if (ctx.signal.aborted) return { results: [], reasonCode: 'abandoned' };
      const exchange = surfaces.surfaceExchanges.open({ binding: { toolId: CREDENTIAL_COPY_TOOL_ID,
        principalId: ctx.principal.id, channel: 'mcp-ui' }, emit: options.emitSurface });
      const uri: UIResourceUri = `ui://tovu/credential-copy/${exchange.id}`;
      const abort = () => exchange.close({});
      ctx.signal.addEventListener('abort', abort, { once: true });
      if (ctx.signal.aborted) abort();
      const emission = (resource: UIResource) => ({ channel: 'mcp-ui' as const, payload: { resource } });
      const refused = (reasonCode: string, message = failureMessages[reasonCode] ?? failureMessages['copy-failed']) => ({
        result: { results: [] as VaultCopyResult[], reasonCode },
        outcome: emission(buildOutcomeSurface({ uri, preferredFrameSize: ['100%', '1px'], title: 'Keys not copied', state: 'failure', message })) });
      async function copySelectedSource({ source }: { source: SourceChoice }, _options = {}) {
        await admit({ deps, principalId: ctx.principal.id });
        if (source.reasonCode) return refused(source.reasonCode, source.reasonCode === 'source-needs-upgrade'
          ? `Start ${source.name} once in Tovu to upgrade it, then copy.` : failureMessages[source.reasonCode]);
        await exchange.send({ emission: emission(form({ uri, exchangeId: exchange.id, submitLabel: 'Copy',
          fields: keyFields({ source }) })) });
        const answer = await exchange.receive({});
        const ending = ended({ answer, aborted: ctx.signal.aborted });
        if (ending) return { result: { results: [], reasonCode: ending } };
        const selected = selection({ params: (answer as Extract<SurfaceMessage, { status: 'received' }>).params, source });
        if (!selected) return refused('invalid-selection');
        await admit({ deps, principalId: ctx.principal.id });
        if (ctx.signal.aborted) return { result: { results: [], reasonCode: 'abandoned' } };
        const copied = await deps.localCredentialCopy!.copy({ sourceSiteId: source.siteId, ...selected, actorId: ctx.principal.id });
        return copyOutcome({ copied, source, uri });
      }
      function copyFailure({ error, source }: { error: unknown; source: SourceChoice }, _options = {}) {
        const code = error && typeof error === 'object' && 'reasonCode' in error ? error.reasonCode : undefined;
        if (code === 'source-needs-upgrade') return refused(code, `Start ${source.name} once in Tovu to upgrade it, then copy.`);
        return refused(error instanceof ToolInputError || error instanceof ForbiddenError ? 'copy-refused'
          : typeof code === 'string' && Object.hasOwn(failureMessages, code) ? code : 'copy-failed');
      }
      try {
        return await askThenReport<{ results: VaultCopyResult[]; reasonCode?: string }>({ exchange, confirmationEmission: emission(form({ uri, exchangeId: exchange.id,
          fields: [{ kind: 'enum', name: 'sourceSiteId', label: 'Source project', required: true,
            options: sources.map(choice => ({ value: choice.siteId, label: choice.name })) }], submitLabel: 'Next' })),
        handle: async answer => {
          const ending = ended({ answer, aborted: ctx.signal.aborted });
          if (ending) return { result: { results: [], reasonCode: ending } };
          const params = (answer as Extract<SurfaceMessage, { status: 'received' }>).params;
          if (Object.keys(params).some(key => !['sourceSiteId', SURFACE_EXCHANGE_ID_PARAM].includes(key))) return refused('invalid-selection');
          const source = sources.find(choice => choice.siteId === params.sourceSiteId);
          if (!source) return refused('invalid-selection');
          try {
            return await copySelectedSource({ source });
          } catch (error) {
            return copyFailure({ error, source });
          }
        } });
      } finally { ctx.signal.removeEventListener('abort', abort); exchange.close({}); }
    } } });
}

import type { ToolExecutionOptions } from "@jini-ai/core";
import { loadPluginCredentialCardsSafely, type PluginCredentialCard } from "./plugin-credential-card.js";
import { toolMetadata } from '../../contracts/core/tool-metadata/custom-credentials.js';
import { buildDomainRegistrations, indexCatalogById, requireInputRecord, requireString, ToolInputError, type AgentToolDefinition, type DerivedRiskByToolId, type ToolExecutionContext, type ToolHandler, type ToolRegistration } from '@jini-ai/core';
import { CREDENTIAL_SAVE_TOOL_ID } from '../../contracts/headless/secret-form-cards.js';
import { CUSTOM_CREDENTIAL_CATEGORIES } from './types.js';

/** Tovu credential kinds delegate to the existing domain authorization and sealed-store owners.
 * Jini owns the secret-card lifecycle; this module only routes non-secret model metadata.
 */
export interface CredentialSaveAdapters {
  readonly apiCreate: ToolHandler;
  readonly apiRotate: ToolHandler;
  readonly mediaProvider: ToolHandler;
  readonly sourceControl: ToolHandler;
  readonly publishHost: ToolHandler;
  readonly agentPluginToken: ToolHandler;
  readonly pluginProvider: ToolHandler;
  /** A provider plugin's settings card (`saveKind: "provider-settings"`); absent where no settings store is wired. */
  readonly providerSettings?: ToolHandler;
}

const KINDS = ['api', 'media-provider', 'source-control', 'publish-host', 'agent-plugin-token', 'plugin-provider', 'provider-settings'] as const;
type CredentialKind = typeof KINDS[number];

/** Model input carries non-secret metadata only. Schema additionalProperties is descriptive:
 * selectSave and each domain handler enforce the allowed keys independently, so no model-issued
 * argument can smuggle a token into the human-form path. Creation and rotation have distinct
 * contracts: optional creation hints make a new row; target addresses an existing credential.
 */
export const credentialSaveCatalog: AgentToolDefinition[] = [{
  name: CREDENTIAL_SAVE_TOOL_ID,
  description: 'Save, add, connect or rotate a credential through a secure human form. The person types the API key, token or password in a masked card; it is sealed server-side and never enters chat or model input. This one call waits for submit, cancel, expiry or abandonment. ' +
    'Choose kind: api for any third-party API, such as a payments or email API, DNS registrar or hosting API; media-provider for image/video generation keys; source-control for git repository commit and backup tokens; publish-host for static site hosting or object storage credentials; agent-plugin-token for an installed plugin personal access token fallback after agent_plugin_connect could not start OAuth sign-in; provider-settings to show a provider plugin’s manifest settings card (target is the pluginId from provider_status); plugin-provider for a provider whose installed plugin ships its own key card, which asks for the key and required public connection fields and saves through that domain’s existing owner. Prefer a plugin-declared card whenever one covers the task. ' +
    'Examples: create an API credential with {kind:"api",label:"payments",baseUrl:"https://api.example.test",category:"general"}; rotate a saved API token with {kind:"api",target:"hosting-prod"} (target is the exact saved label, username is preserved); save an image generation key with {kind:"media-provider",target:"image-provider"}; connect repository backups with {kind:"source-control",target:"<repository provider id>",label:"default"}; save a hosting connection with {kind:"publish-host",target:"<storage provider id>",prefill:{bucket:"my-site",region:"us-east-1"}}; use a plugin token with {kind:"agent-plugin-token",target:"<plugin id>"}; open a plugin’s own key card with {kind:"plugin-provider",target:"<provider id>"}. ' +
    'Discover targets first with content_read.custom_credential, media_list_providers, source_control_get_capabilities or deployment_get_static_publish_capabilities. Choose the card or saved key whose usedFor covers the task; do not ask the person. usedFor is display text, not permission or verification. API creation accepts optional label/baseUrl/category/worksFor prefill; without target it creates a new row and refuses a duplicate label. Publish prefill accepts only provider-declared non-secret fields. Never supply a secret in any argument. ' +
    'Before opening any key card, explain which service and purpose it is for. Refuse to open a replacement-token card for a saved working credential unless the person explicitly asked to replace that key. When explicitly asked to show provider settings, open kind provider-settings; opening the card does not save anything until the person submits. Never open secret-entry cards during a read-only request or to answer what a token is. Read saved metadata and answer in words first. Account-management access may require a separate plugin connection; do not overwrite a working sending key to obtain broader access. ' +
    'Permissions stay per kind: custom-credentials.write, admin.integrations.manage (media/plugin), source-control.credentials.write, deployments.credentials.write, admin.plugins.enable (provider-settings). Results retain each kind’s safe save status and errors; only API creation returns created/credential. Saving a media key does not verify it or add adapter support. External MCP server config, user creation, database destinations and app environment secrets use their own action tools. Saving a project key on a card attaches it to this site. After success retry the original request once.',
  sideEffects: 'mutates-durable-state',
  authorization: { permission: 'resolved-per-kind' },
  inputSchema: {
    type: 'object', additionalProperties: false, required: ['kind'],
    properties: {
      kind: { type: 'string', enum: [...KINDS] },
      target: { type: 'string', minLength: 1, description: 'Existing API credential label to rotate, media/source-control/publish/plugin provider id, or installed plugin id.' },
      label: { type: 'string', description: 'Optional new API or source-control credential label; never a secret.' },
      baseUrl: { type: 'string', description: 'API creation only: non-secret base URL prefill.' },
      worksFor: { type: "array", items: { type: "string" }, description: "API creation only: explicit host or vendor IDs to preselect in the secure form." },
      category: { type: 'string', enum: [...CUSTOM_CREDENTIAL_CATEGORIES], description: 'API creation only: category prefill.' },
      reason: { type: 'string', maxLength: 1000, description: 'Media only: non-secret reason shown on the form.' },
      prefill: { type: 'object', additionalProperties: { type: 'string' }, description: 'Publish only: provider-declared non-secret credential fields. Never tokens, keys or passwords.' },
    },
  },
}];

export const credentialSaveDerivedRisk: DerivedRiskByToolId = new Map([[CREDENTIAL_SAVE_TOOL_ID, 'mutates-durable-state']]);

/** Select one domain owner without authorizing, opening a card, or inspecting secret fields.
 * @param required - Kind, non-secret metadata and injected domain handlers.
 * @returns The selected handler and its original input contract.
 * @throws ToolInputError for unknown kinds, cross-kind fields or malformed prefill.
 * @complexity Time/space O(k + f), input keys plus publish prefill fields.
 */
function selectSave({ input, adapters }: { input: Record<string, unknown>; adapters: CredentialSaveAdapters }, _optional = {}): { handler: ToolHandler; input: Record<string, unknown> } {
  const kind = requireString({ input, key: 'kind' });
  if (!KINDS.includes(kind as CredentialKind)) throw new ToolInputError({ message: 'Unknown credential kind. Use api, media-provider, source-control, publish-host, agent-plugin-token, plugin-provider or provider-settings.' });
  const selectedKind = kind as CredentialKind;
  const { kind: _kind, ...metadata } = input;
  const targetOnly = ['plugin-provider', 'provider-settings'].includes(selectedKind);
  const fields = selectedKind === 'api'
    ? ['target', 'label', 'baseUrl', 'category', 'worksFor']
    : targetOnly ? ['target'] : ['target', 'prefill'];
  // A plugin card fixes its row on the server, so no label, base URL or category may ride along.
  const validateHere = selectedKind === 'publish-host' || targetOnly || (selectedKind === 'api' && !('target' in metadata));
  if (validateHere && Object.keys(metadata).some(key => !fields.includes(key))) {
    // Creation previously ignored unknown hints. Refuse them here; other owners already validate
    // their entire input and retain their exact per-kind errors. Never silently drop an extra key.
    throw new ToolInputError({ message: 'credential_save accepts only non-secret metadata for the selected kind; enter secrets in the human form.' });
  }
  return routeSave({ selectedKind, metadata, adapters });
}

function routeSave({ selectedKind, metadata, adapters }: {
  selectedKind: CredentialKind; metadata: Record<string, unknown>; adapters: CredentialSaveAdapters;
}, _options = {}): { handler: ToolHandler; input: Record<string, unknown> } {
  const { target: _target, ...hints } = metadata;
  // Forward the raw target under the owner's field name. Its validation retains the exact
  // per-kind error and ordering; a generic target validator would change both.
  switch (selectedKind) {
    case 'api': return selectApiSave({ metadata, hints, adapters });
    case 'media-provider':
    case 'source-control': return selectProviderSave({ selectedKind, metadata, hints, adapters });
    case 'agent-plugin-token': {
      if ('pluginId' in hints) throw new ToolInputError({ message: 'Use target for the installed plugin id.' });
      return { handler: adapters.agentPluginToken, input: { ...hints, pluginId: metadata.target } };
    }
    case 'publish-host': return selectPublishSave({ metadata, adapters });
    case 'provider-settings': return selectProviderSettingsSave({ adapters, target: metadata.target });
    case 'plugin-provider': return { handler: adapters.pluginProvider, input: { provider: metadata.target } };
    // No default: selectSave refuses any kind outside KINDS before routing, and this switch covers
    // every CredentialKind, so the compiler proves no other value reaches here.
  }
}

function selectProviderSettingsSave({ adapters, target }: { adapters: CredentialSaveAdapters; target: unknown }, _options = {}): { handler: ToolHandler; input: Record<string, unknown> } {
  if (!adapters.providerSettings) throw new ToolInputError({ message: 'Provider settings are not available here.' });
  return { handler: adapters.providerSettings, input: { pluginId: target } };
}

/** Forward a provider target to its existing domain, retaining that domain's validation.
 * @throws ToolInputError on an attempted target override. @complexity O(k) metadata keys. */
function selectProviderSave({ selectedKind, metadata, hints, adapters }: { selectedKind: 'media-provider' | 'source-control'; metadata: Record<string, unknown>; hints: Record<string, unknown>; adapters: CredentialSaveAdapters }, _options = {}): { handler: ToolHandler; input: Record<string, unknown> } {
  if ('provider' in hints) throw new ToolInputError({ message: 'Use target for the credential provider.' });
  return { handler: selectedKind === 'media-provider' ? adapters.mediaProvider : adapters.sourceControl, input: { ...hints, provider: metadata.target } };
}

function selectApiSave({ metadata, hints, adapters }: { metadata: Record<string, unknown>; hints: Record<string, unknown>; adapters: CredentialSaveAdapters; }, _options = {}): { handler: ToolHandler; input: Record<string, unknown> } {
  if (!('target' in metadata)) return { handler: adapters.apiCreate, input: metadata };
  if ('label' in hints) throw new ToolInputError({ message: 'API token rotation accepts target rather than a creation label.' });
  return { handler: adapters.apiRotate, input: { ...hints, label: metadata.target } };
}

function selectPublishSave({ metadata, adapters }: { metadata: Record<string, unknown>; adapters: CredentialSaveAdapters; }, _options = {}): { handler: ToolHandler; input: Record<string, unknown> } {
  // requireInputRecord intentionally accepts arrays; publish prefill requires named fields.
  if (Array.isArray(metadata.prefill)) throw new ToolInputError({ message: 'Credential prefill must be an object.' });
  const prefill = metadata.prefill === undefined ? {} : requireInputRecord({ input: metadata.prefill });
  // Keep the resolved target binding authoritative; provider validation owns all other field names.
  if ('target' in prefill) throw new ToolInputError({ message: 'Credential prefill cannot replace target.' });
  return { handler: adapters.publishHost, input: { ...prefill, target: metadata.target } };
}

/** Register the sole credential save tool through the existing registry, forwarding options intact.
 * @param required - Domain adapters, each retaining its own authorization, validation and save port.
 * @returns One registration; no executable aliases for the retired tools.
 * @example buildCredentialSaveRegistrations({ adapters });
 * @complexity Registration O(1); each invocation performs O(k + f) routing before one domain save.
 */
export function buildCredentialSaveRegistrations({ adapters, loadPluginCredentialCards, authorizePluginProvider, adaptersForCards, savedResult }: { savedResult?: (input: { result: unknown }) => Promise<unknown>; adapters: CredentialSaveAdapters; loadPluginCredentialCards?: () => Promise<readonly PluginCredentialCard[]>; authorizePluginProvider?: (ctx: ToolExecutionContext) => Promise<void>; adaptersForCards?: (required: { cards: readonly PluginCredentialCard[] }) => CredentialSaveAdapters }, _optional = {}): ToolRegistration[] {
  return buildDomainRegistrations({ metadata: toolMetadata,
    domain: 'credential-save', catalogModule: 'features/custom-credentials/credential-save-tool.ts',
    catalog: indexCatalogById({ catalog: credentialSaveCatalog }), derivedRisk: credentialSaveDerivedRisk,
    handlers: { [CREDENTIAL_SAVE_TOOL_ID]: async (ctx, optional = {}) => {
      const selected = selectSave({ input: requireInputRecord({ input: ctx.input }), adapters });
      if (selected.handler !== adapters.pluginProvider || !loadPluginCredentialCards) {
        return invokeSaveAdapter({ selected, ctx, options: optional, savedResult });
      }
      // A card can choose a domain, so require the entry permission before reading plugin data.
      if (!authorizePluginProvider) throw new ToolInputError({ message: 'Plugin credential card authorization is unavailable. Use the credential kind directly.' });
      await authorizePluginProvider(ctx);
      const cards = await loadPluginCredentialCardsSafely({ loadCards: loadPluginCredentialCards, workspaceId: '' });
      const resolvedAdapters = adaptersForCards?.({ cards }) ?? adapters;
      const card = cards.find(entry => entry.providerId === selected.input.provider);
      const resolved = { ...selected, handler: resolvedAdapters.pluginProvider };
      const routed = routePluginCard({ card, selected: resolved, adapters: resolvedAdapters });
      const result = await routed.handler({ ...ctx, input: routed.input }, optional);
      return savedResult ? savedResult({ result }) : result;
    } },
  });
}

/** A declared destination reuses the existing permission, validation, probe and sealed-store owner. */
function routePluginCard({ card, selected, adapters }: { card?: PluginCredentialCard; selected: { handler: ToolHandler; input: Record<string, unknown> }; adapters: CredentialSaveAdapters }, _options = {}): { handler: ToolHandler; input: Record<string, unknown> } {
  if (!card) return selected;
  const target = card.saveTarget ?? card.providerId;
  switch (card.saveKind) {
    case 'publish-host': return { handler: adapters.publishHost, input: { target } };
    case 'source-control': return { handler: adapters.sourceControl, input: { provider: target } };
    case 'agent-plugin-token': return { handler: adapters.agentPluginToken, input: { pluginId: target } };
    case 'provider-settings': return selectProviderSettingsSave({ adapters, target });
    case 'oauth': throw new ToolInputError({ message: 'This plugin connects by browser sign-in. Use agent_plugin_connect with its pluginId.' });
    default: return selected;
  }
}


/** Domain saves own the human exchange; one shared result hook attaches successful project saves. */
async function invokeSaveAdapter({ selected, ctx, options, savedResult }: {
  selected: { handler: ToolHandler; input: Record<string, unknown> }; ctx: ToolExecutionContext; options: ToolExecutionOptions;
  savedResult?: (input: { result: unknown }) => Promise<unknown>;
}, _optional = {}): Promise<unknown> {
  const result = await selected.handler({ ...ctx, input: selected.input }, options);
  return savedResult ? savedResult({ result }) : result;
}

import { CustomCredentialValidationError } from "./store.js";
import { assertCredentialFreeField } from "../../contracts/core/credential-token.js";
import type { SecretCardForm } from "@jini-ai/ui/mcp-ui/secret-card";

/**
 * @file A key card an installed plugin declares for its own provider (2026-10-22, starting with mail
 * providers). The generic "Save an API credential" card asks for a label, base URL, category and
 * deploy targets the person has no reason to know; a plugin that already knows them declares its own
 * card copy, and core fills the rest in on the server. The form carries a masked token plus
 * declared non-secret fields. Fixed labels, origins and categories remain server-owned, so a
 * submission cannot redirect the key to another row. Instance-specific origins are explicit fields. Core names no vendor: every word on the card comes from the plugin's descriptor.
 */

/** Extra public connection metadata, entered directly on the secure card. */
export interface PluginCredentialField {
  readonly name: string;
  readonly label: string;
  readonly hint?: string;
  readonly required?: boolean;
}

/** One plugin-declared key card, already resolved to the saved row it fills. */
export interface PluginCredentialCard {
  /** Declaring installed plugin, supplied by the trusted contribution loader. */
  readonly pluginId?: string;
  /** Provider id the assistant passes as `target` (e.g. a mail provider's id). */
  readonly providerId: string;
  /** API credential label, or the connection name for a domain-owned save. */
  readonly label: string;
  /** Explicit ownership of this API card's exact label; conflicting plugins are refused at merge. */
  readonly ownedApiLabel?: string;
  readonly category: string;
  readonly baseUrl: string;
  readonly title: string;
  readonly intro?: string;
  readonly helpUrl?: string;
  readonly helpLabel?: string;
  /** Hint under the key field, e.g. which access the key needs. */
  readonly keyHint?: string;
  /** Plain-text purposes for people and the assistant; never selects or authorizes a key in code. */
  readonly usedFor?: readonly string[];
  readonly fields?: readonly PluginCredentialField[];
  /** Optional read-only GET before sealing; absolute HTTPS on the declared baseUrl origin. */
  readonly probeUrl?: string;
  readonly additionalHosts?: readonly string[];
  /** Absent preserves the original mail/API save path. `provider-settings` saves a provider plugin's
   *  declared settings (saveTarget = that plugin's id; see provider-settings-card.ts). */
  readonly saveKind?: "api" | "publish-host" | "source-control" | "agent-plugin-token" | "oauth" | "provider-settings";
  readonly saveTarget?: string;
  /** Permissions explained on a hosted sign-in card; never grants authority itself. */
  readonly permissions?: string;
}

/** Composition-supplied loader; absent when no plugin catalog can declare cards here. */
export type LoadPluginCredentialCards = (workspaceId: string) => Promise<readonly PluginCredentialCard[]>;

/**
 * Renders a plugin's key card: its title, intro and help link above declared public fields and one masked token field.
 * The help link is a detail row (the form surface has no link control), and the saved label is
 * shown so the person can find the row later under Access Tokens.
 *
 * @complexity O(f) declared public fields; mail retains its original one-field form.
 */
export function buildPluginCredentialForm({ card }: { card: PluginCredentialCard }, _optional = {}): SecretCardForm & { preferredFrameSize: readonly [string, string] } {
  return {
    title: card.title,
    description: `${card.intro ? `${card.intro} ` : ""}The key is sealed on the server the moment you submit — the assistant never sees it.`,
    details: pluginCardDetails({ card }),
    submitLabel: "Save key",
    fields: [...(card.fields ?? []).map(field => ({ kind: "string" as const, ...field })), {
      kind: "string",
      name: "token",
      label: "API key",
      hint: card.keyHint ?? "Paste the key here. It is never shown to the assistant.",
      required: true,
      secret: true,
    }],
    app: { appName: "tovu-plugin-credential-card", appVersion: "1" },
    preferredFrameSize: ["100%", "360px"],
  };
}

/** Apply plugin copy to an existing domain form, preserving its fields, update and blank-token rules.
 * Domain stores remain authoritative for connection validation. @complexity O(f) form fields.
 */
export function applyPluginCredentialCard({ card, form }: { card?: PluginCredentialCard; form: SecretCardForm }, _options = {}): SecretCardForm {
  if (!card) return form;
  const pluginForm = buildPluginCredentialForm({ card });
  return { ...form, title: pluginForm.title, description: form.description ? `${card.intro ?? ""} ${form.description}`.trim() : pluginForm.description, details: [...(form.details ?? []), ...(pluginForm.details ?? [])],
    fields: form.fields.map(field => field.kind === "string" && field.name === "token" && field.secret ? { ...field, hint: card.keyHint ?? field.hint } : field) };
}

/** Extract API inputs from the human card. Fixed destinations cannot be changed by form params.
 * Required public fields and dynamic HTTPS origins are checked before sealing. @complexity O(f).
 */
export function readPluginCredentialValues({ card, values }: { card: PluginCredentialCard; values: Readonly<Record<string, unknown>> }, _options = {}): {
  label: string; category: string; baseUrl: string; username?: string; token: string; additionalHosts?: readonly string[];
} {
  const publicValues = Object.fromEntries((card.fields ?? []).map(field => [field.name, readPublicField({ field, values })]));
  const baseUrl = card.baseUrl || publicValues.baseUrl || '';
  if (!card.baseUrl) assertHttpsInput({ value: baseUrl });
  return { label: card.label, category: card.category, baseUrl, username: publicValues.username,
    token: typeof values.token === 'string' ? values.token : '',
    ...(card.additionalHosts === undefined ? {} : { additionalHosts: card.additionalHosts }) };
}

/** Public fields share the existing credential-free-value invariant with other credential forms. */
function readPublicField({ field, values }: { field: PluginCredentialField; values: Readonly<Record<string, unknown>> }, _options = {}): string | undefined {
  const value = values[field.name];
  if (field.required && (typeof value !== 'string' || !value.trim())) throw new CustomCredentialValidationError(`${field.name} is required`);
  if (value === undefined) return undefined;
  if (typeof value !== 'string') throw new CustomCredentialValidationError(`${field.name} must be text`);
  assertCredentialFreeField({ value, field: field.name });
  return value;
}

/** The API store permits HTTP for legacy rows; plugin-declared dynamic origins require HTTPS. */
function assertHttpsInput({ value }: { value: string }, _options = {}): void {
  let url: URL;
  try { url = new URL(value); } catch { throw new CustomCredentialValidationError('Server URL must use HTTPS'); }
  if (url.protocol !== 'https:' || url.username || url.password) throw new CustomCredentialValidationError('Server URL must use HTTPS without credentials');
}

/** Resolve copy only for the matching domain and provider, never a similarly named card. */
export async function findPluginCredentialCard({ loadCards, workspaceId, saveKind, target }: {
  loadCards?: LoadPluginCredentialCards; workspaceId: string; saveKind: PluginCredentialCard['saveKind']; target: string;
}, _options = {}): Promise<PluginCredentialCard | undefined> {
  return (await loadPluginCredentialCardsSafely({ loadCards, workspaceId })).find(card => cardMatches({ card, saveKind, target }));
}

/** A missing saveKind keeps the original API-card contract (credential-cards.ts isApiCard). */
function cardMatches({ card, saveKind, target }: { card: PluginCredentialCard; saveKind: PluginCredentialCard['saveKind']; target: string }, _options = {}): boolean {
  if (saveKind === "api") return (card.saveKind ?? "api") === "api" && card.label === target;
  return card.saveKind === saveKind && (card.saveTarget ?? card.providerId) === target;
}

/** API rows have a fixed label; domain owners choose their own connection identity. */
function pluginCardDetails({ card }: { card: PluginCredentialCard }, _options = {}): SecretCardForm['details'] {
  const help = card.helpUrl ? [{ label: card.helpLabel ?? 'Get a key', value: card.helpUrl }] : [];
  const details = [...help, ...(card.usedFor?.length ? [{ label: 'Used for', value: card.usedFor.join('; ') }] : [])];
  return card.saveKind && card.saveKind !== 'api' ? details : [...details, { label: 'Saved as', value: card.label }];
}

/** Optional display data cannot prevent a domain's authorized credential operation. O(cards).
 * Failures report a fixed warning, without reflecting filesystem paths or credential metadata.
 */
export async function loadPluginCredentialCardsSafely({ loadCards, workspaceId }: { loadCards?: LoadPluginCredentialCards; workspaceId: string }, options: { warn?: (message: string) => void } = {}): Promise<readonly PluginCredentialCard[]> {
  try { return await loadCards?.(workspaceId) ?? []; }
  catch { (options.warn ?? console.warn)("[plugin-credential-cards] Optional card lookup failed; using the default credential form."); return []; }
}

import type { ProviderKeyUsage } from "../project-keys/service.js";
import { requireInputRecord, requireString, ToolInputError, type ToolExecutionContext, type ToolExecutionOptions, type ToolHandler } from "@jini-ai/core";
import { askThenReport, type AssistantSurfaceDeps } from "@jini-ai/daemon/surface-exchanges";
import type { PluginProviderSettingField } from "@jini-ai/plugins/host";
import { defineSecretCardTool, type SecretCardField, type SecretCardForm } from "@jini-ai/ui/mcp-ui/secret-card";
import type { SurfaceOutcomeSpec } from "@jini-ai/ui/mcp-ui/surfaces";

import { CREDENTIAL_SAVE_TOOL_ID } from "../../contracts/headless/secret-form-cards.js";
import type { PluginCredentialCard } from "./plugin-credential-card.js";

/**
 * @file The assistant's key card for a PROVIDER plugin's settings (2026-10-25): an agent plugin
 * declares a credential card with `saveKind: "provider-settings"` and `saveTarget: <provider plugin
 * id>`, and `credential_save` (kind plugin-provider) opens it. The form's fields are the provider
 * plugin's own manifest-declared settings (public values, declared defaults and choices, masked
 * secrets); the agent plugin only supplies the copy (title, intro, help link). A submission saves
 * through the host's shared provider-settings save rule (the admin Settings card's rule and store),
 * so a key typed here lands in the same row, never in a credential row, the transcript or model input.
 * Core names no vendor: every word on the card comes from the two manifests.
 */

/** Host ports, bound by the composition root to the shared save rule and `ProviderConfigSource`. */
export interface ProviderSettingsCardPorts {
  readonly usage?: (required: { pluginId: string }) => Promise<ProviderKeyUsage>;
  /** The provider plugin's declared settings; undefined when it is not installed or declares none. */
  readonly fields: (required: { pluginId: string }) => Promise<readonly PluginProviderSettingField[] | undefined>;
  /** Saved public values and the NAMES of saved secrets; null when nothing is saved or it is unreadable. */
  readonly readSettings: (required: { pluginId: string }) => Promise<{ settings: Readonly<Record<string, string>>; secretNames: readonly string[] } | null>;
  /** The shared save rule: writes, or returns the refusal text without writing. */
  readonly save: (required: { pluginId: string; values: Readonly<Record<string, string>> }) => Promise<Saved | { refusal: string }>;
  /** The admin Settings card's save permission (`admin.plugins.enable`). */
  readonly authorize: (ctx: ToolExecutionContext) => Promise<void>;
}

type SavedView = Awaited<ReturnType<ProviderSettingsCardPorts["readSettings"]>>;
type Prep = { pluginId: string; card?: PluginCredentialCard; fields: readonly PluginProviderSettingField[]; saved: SavedView; usage?: ProviderKeyUsage };
type Saved = { configured?: boolean; store: "project" | "site"; keyId?: string; usedByThisSite?: boolean; usedBy?: readonly string[]; appliesAt?: "now" | "restart" | "failed"; message?: string };
export type ProviderSettingsSaveResult =
  | { saved: true; pluginId: string; store: "project" | "site"; configured?: boolean; appliesAt: "now" | "restart" | "failed"; message?: string; keyId?: string; usedByThisSite?: boolean; usedBy?: readonly string[]; ask?: string }
  | { saved: false; reason: string; message?: string };

/** The select option that reveals a field's free-text twin (`allowCustom`). */
const CUSTOM = "__custom";
const customName = (name: string) => `${name}__custom`;

/** All controls retain the provider's conditional requirement metadata. */
function fieldRequirements({ field }: { field: PluginProviderSettingField }, _options = {}) {
  return {
    ...(field.requiredUnless ? { requiredUnless: field.requiredUnless } : {}),
    ...(field.requiredWhen ? { requiredWhen: field.requiredWhen } : {}),
  };
}

/** A declared public field with choices: a select (plus "Custom…" and its text field when allowed). */
function choiceFields({ field, value }: { field: PluginProviderSettingField; value?: string }): SecretCardField[] {
  const options = field.options ?? [];
  const custom = Boolean(value) && !options.some((option) => option.value === value);
  const select: SecretCardField = { kind: "enum", name: field.name, label: field.label, required: field.required === true,
    ...fieldRequirements({ field }),
    options: [...options, ...(field.allowCustom ? [{ value: CUSTOM, label: "Custom…" }] : [])], value: custom && field.allowCustom ? CUSTOM : value ?? field.default };
  if (!field.allowCustom) return [select];
  return [select, { kind: "string", name: customName(field.name), label: `Custom ${field.label.toLowerCase()}`, ...(field.hint ? { hint: field.hint } : {}), ...(custom ? { value } : {}) }];
}

/** A secret control never carries its value; conditional blanks reach the shared server save rule. */
function secretFieldOf({ field, saved, required }: { field: PluginProviderSettingField; saved: SavedView; required: boolean }): SecretCardField {
  const kept = saved?.secretNames.includes(field.name) === true;
  const hint = [field.hint, kept ? "Leave blank to keep the saved one." : undefined].filter(Boolean).join(" ");
  return { kind: "string", name: field.name, label: field.label, secret: true, required, ...(kept ? { hasSavedValue: true } : {}),
    ...(field.requiredUnless ? { requiredUnless: field.requiredUnless } : {}),
    ...(field.requiredWhen ? { requiredWhen: field.requiredWhen } : {}),
    allowBlank: !required || kept || Boolean(field.requiredUnless || field.requiredWhen), ...(hint ? { hint } : {}) };
}

/** One declared field → its form controls. A saved secret may be left blank to keep it. */
function formFieldsOf({ field, saved }: { field: PluginProviderSettingField; saved: SavedView }): SecretCardField[] {
  // Conditional fields keep their base requirement; the form evaluates it as the public choice changes.
  const required = field.required === true;
  if (field.secret) return [secretFieldOf({ field, saved, required })];
  const value = saved?.settings[field.name] || undefined;
  if (field.options?.length) return choiceFields({ field, value });
  const initial = value ?? field.default;
  return [{ kind: "string", name: field.name, label: field.label, required, ...fieldRequirements({ field }),
    ...(field.hint ? { hint: field.hint } : {}), ...(initial ? { value: initial } : {}) }];
}

/** The declared card's help, key-entry hint and purposes; values never come from saved settings. */
function providerCardDetails({ card }: { card?: PluginCredentialCard }, _optional = {}) {
  const details: { label: string; value: string }[] = [];
  if (!card) return details;
  if (card.helpUrl) details.push({ label: card.helpLabel ?? "Help", value: card.helpUrl });
  if (card.keyHint) details.push({ label: "Where to find it", value: card.keyHint });
  if (card.usedFor?.length) details.push({ label: "Used for", value: card.usedFor.join("; ") });
  return details;
}

/** Explain a site-only replacement before the person enters a different project's key. */
function otherSiteKeyNotice({ usage, label }: { usage?: ProviderKeyUsage; label: string }, _optional = {}): string {
  if (!usage || usage.store !== "project" || usage.usedByThisSite || usage.usedBy.length === 0) return "";
  return ` Your project's saved ${label} key is used by ${usage.usedBy.join(", ")}. A key entered here is used by this site only.`;
}

/** The card: plugin copy over the provider's declared fields. @complexity O(f) declared fields. */
export function buildProviderSettingsForm({ prep }: { prep: Prep }, _optional = {}): SecretCardForm {
  const { card } = prep;
  const otherUse = otherSiteKeyNotice({ usage: prep.usage, label: card?.label ?? "provider" });
  return {
    title: card?.title ?? "Connect provider",
    description: `${card?.intro ? `${card.intro} ` : ""}Keys are sealed on the server the moment you submit — the assistant never sees them.${otherUse}`,
    details: providerCardDetails({ card }),
    submitLabel: "Save",
    fields: prep.fields.flatMap((field) => formFieldsOf({ field, saved: prep.saved })),
    app: { appName: "tovu-provider-settings-card", appVersion: "1" },
  };
}

/** Submitted controls → declared setting values (a "Custom…" choice takes its text field). @complexity O(f). */
export function readProviderSettingsValues({ fields, values }: { fields: readonly PluginProviderSettingField[]; values: Readonly<Record<string, unknown>> }): Record<string, string> {
  const out: Record<string, string> = {};
  for (const field of fields) {
    const chosen = values[field.name] === CUSTOM ? values[customName(field.name)] : values[field.name];
    if (typeof chosen === "string") out[field.name] = chosen;
  }
  return out;
}

/** Model-facing projection: where it saved and when it applies, never a value. */
function resultOf({ run, pluginId }: { run: { status: string; saved?: Saved; safeMessage?: string }; pluginId: string }): ProviderSettingsSaveResult {
  if (run.status === "saved" && run.saved) return { saved: true, pluginId, ...run.saved, appliesAt: run.saved.appliesAt ?? "restart" };
  if (run.status === "failed") return { saved: false, reason: "error", message: run.safeMessage };
  if (run.status === "blank") return { saved: false, reason: "invalid", message: "A required key was left blank. Nothing was saved." };
  return { saved: false, reason: run.status };
}

/** A committed save can need browser reload or provider startup without becoming a failed save. */
function savedMessage({ result }: { result: Extract<ProviderSettingsSaveResult, { saved: true }> }, _optional = {}): string {
  if (result.appliesAt === "failed") return result.message ?? "Saved, but the provider could not start. Check the plugin settings and save again.";
  const location = result.store === "site" ? "Saved for this site." : result.usedBy?.length
    ? `Saved. Used by ${result.usedBy.join(", ")}. Other sites pick it up within 30 seconds.`
    : "Saved to your project — not used by any site yet.";
  if (!result.configured) return location;
  return location + (result.appliesAt === "now" ? " Now sending." : " Reload open pages or restart this site to finish applying the saved settings.");
}

function outcomeOf({ result, title }: { result: ProviderSettingsSaveResult; title: string }): SurfaceOutcomeSpec | undefined {
  if (!result.saved && result.message === undefined) return undefined;
  return { title, state: result.saved && result.appliesAt !== "failed" ? "success" : "failure", app: { appName: "tovu-provider-settings-outcome", appVersion: "1" },
    message: result.saved ? savedMessage({ result }) : result.message! };
}

/** Thrown with fixed refusal text from the shared rule (names fields, never values). */
class ProviderSettingsRefusedError extends Error {}

/**
 * The `provider-settings` save adapter for `credential_save`. Input: `{ pluginId }` (the card's
 * saveTarget), resolved by `routePluginCard`; never a value.
 * @complexity O(f) per card plus one settings read and one save.
 */
export function buildProviderSettingsCredentialHandler({ ports, surfaces, loadCards }: {
  ports: ProviderSettingsCardPorts; surfaces: AssistantSurfaceDeps; loadCards: () => Promise<readonly PluginCredentialCard[]>;
}, _optional = {}): ToolHandler {
  return async (ctx: ToolExecutionContext, options: ToolExecutionOptions = {}) => {
    const pluginId = requireString({ input: requireInputRecord({ input: ctx.input }), key: "pluginId" });
    const card = defineSecretCardTool<Prep, Saved, ProviderSettingsSaveResult>({
      toolId: CREDENTIAL_SAVE_TOOL_ID,
      prepare: async () => {
        await ports.authorize(ctx);
        const fields = await ports.fields({ pluginId });
        if (!fields) throw new ToolInputError({ message: `The provider plugin '${pluginId}' is not installed or declares no settings. Install and enable it first (plugins_list, plugins_set_enabled).` });
        const declared = (await loadCards()).find((entry) => entry.saveKind === "provider-settings" && entry.saveTarget === pluginId);
        return { pluginId, fields, usage: await ports.usage?.({ pluginId }), saved: await ports.readSettings({ pluginId }), ...(declared ? { card: declared } : {}) };
      },
      form: ({ prep }) => buildProviderSettingsForm({ prep }),
      save: async ({ values, prep }) => {
        const outcome = await ports.save({ pluginId, values: readProviderSettingsValues({ fields: prep.fields, values }) });
        if ("refusal" in outcome) throw new ProviderSettingsRefusedError(outcome.refusal);
        return outcome;
      },
      result: ({ run }) => resultOf({ run, pluginId }),
      outcome: ({ prep, run }) => outcomeOf({ result: resultOf({ run, pluginId }), title: prep.card?.title ?? "Provider settings" }),
    }, { uriHost: "tovu", frameSize: ["100%", "460px"],
      // The refusal names fields only (shared rule); every other failure keeps the engine's fixed text.
      safeError: (error) => error instanceof ProviderSettingsRefusedError ? error.message : "Saving failed. Nothing was saved." });
    return card.handler({ surfaceExchanges: surfaces.surfaceExchanges, askThenReport })(ctx, options);
  };
}

import { normalizeCredentialWorksFor, VaultError, type VaultSummary } from "@jini-ai/platform/secrets/credential-sets";
import { CredentialInputError, CREDENTIAL_MESSAGES, assertCredentialFreeField, normalizeCredentialToken } from '../../contracts/core/credential-token.js';
import type { Clock as ClockPort, UUID } from "@jini-ai/core/primitives";

import { isUniqueViolation } from "../../platform/db/kernel/dialect.js";
import type { KeyringPort, SecretSealerPort } from "../webhooks/index.js";
import { byVaultLabel, createTovuStoreVault } from "#src/platform/secrets/vault-kinds";
import { customVaultRecord, customVaultScope } from "./vault-repo.js";
import { credentialDeletionRepo, credentialCreateTarget, credentialScopes, type ScopedCredentialDeps } from "../vendor-credentials/project-scope.js";
import {
  CUSTOM_CREDENTIAL_CATEGORIES,
  type CustomCredentialCategoryId,
  type CustomCredentialScope,
  type CustomCredentialSetRecord,
  type CustomCredentialSetRepoPort,
  type CustomCredentialSummary,
  type CustomProviderConnectionInput,
} from "./types.js";

/**
 * @file Feature validation and CRUD over Jini's vault. Public summaries contain saved origins,
 * usernames and safe hints only. Tokens live in sealed JSON; boot/recovery owns legacy decoding.
 * Label selection and origin checks never open unrelated credentials.
 */

const MAX_LABEL_LENGTH = 200;
const CATEGORY_IDS: ReadonlySet<CustomCredentialCategoryId> = new Set(CUSTOM_CREDENTIAL_CATEGORIES);

function isCustomCredentialCategoryId(value: string): value is CustomCredentialCategoryId {
  return CATEGORY_IDS.has(value as CustomCredentialCategoryId);
}

export class CustomCredentialValidationError extends Error {}

/** A `(workspaceId, label)` collision — the route maps this to `409 DUPLICATE_LABEL`. */
export class CustomCredentialDuplicateLabelError extends Error {}

/** A share copied an older revision; the concurrently changed site row remains intact. */
export class CustomCredentialConcurrentModificationError extends Error {}

/** Thrown when `sealer.seal()`/`keyring.activeKey()` fails while writing a connection — the
 *  realistic cause is a missing site key (`TOVU_SITE_KEY`), same fail-closed
 *  contract every sibling credential table's store documents. */
export class CustomCredentialSecretStoreUnconfiguredError extends Error {}

export class CustomCredentialNotFoundError extends Error {}

/** Safe hints are stored with the envelope; no per-row decrypt is needed for readback. `scope` is
 *  reported only where a project store is attached, so a site-only server's summaries are unchanged. */
async function toSummary(record: CustomCredentialSetRecord, optional: { scope?: CustomCredentialScope } = {}): Promise<CustomCredentialSummary> {
  const row = record.vaultRecord;
  return { credentialType: "custom", worksFor: [...(record.worksFor ?? [])], id: record.id, label: record.label, category: record.category, baseUrl: record.baseUrl,
    additionalHosts: record.additionalHosts, ...(record.username !== undefined ? { username: record.username } : {}),
    configured: true, tokenHint: row?.tokenLength === null || row?.tokenLength === undefined ? null :
      { length: row.tokenLength, last4: row.tokenLength >= 12 ? row.last4 : null },
    ...(optional.scope ? { scope: optional.scope } : {}),
    createdAt: record.createdAt, updatedAt: record.updatedAt };
}

/** A row and the store holding it (`vendor-credentials/project-scope.ts`: this site's own vault first,
 *  then the project half `types.ts`'s `repo.project` attaches), with the deps that open it. */
interface Located<D> { readonly scoped: ScopedCredentialDeps<D>; readonly record: CustomCredentialSetRecord }

/** The summary's `scope`, only when a project store is attached. */
const reportedScope = (deps: CustomCredentialInventoryDeps, scoped: ScopedCredentialDeps<unknown>): { scope?: CustomCredentialScope } =>
  deps.repo.project ? { scope: scoped.scope } : {};

/** The row with this id, from the first store holding it (ids are unique across both). @complexity O(scopes). */
async function locateById<D extends CustomCredentialReadDeps>(deps: D, input: { workspaceId: UUID; id: UUID }): Promise<Located<D> | null> {
  for (const scoped of credentialScopes(deps, input.workspaceId)) {
    const record = await scoped.deps.repo.findById({ workspaceId: scoped.workspaceId, id: input.id });
    if (record) return { scoped, record };
  }
  return null;
}

/**
 * Every row this site uses, in label order: its own rows, then project rows whose label no site row
 * already claims (a site row of the same label is the override).
 * @complexity O(n log n) in the two stores' (small) credential counts; no row is opened.
 */
async function listEffective<D extends CustomCredentialInventoryDeps>(deps: D, workspaceId: UUID): Promise<Located<D>[]> {
  const found: Located<D>[] = [];
  const labels = new Set<string>();
  for (const scoped of credentialScopes(deps, workspaceId)) {
    const records = await scoped.deps.repo.listByWorkspace({ workspaceId: scoped.workspaceId });
    for (const record of records.filter((row) => !labels.has(row.label))) found.push({ scoped, record });
    for (const record of records) labels.add(record.label);
  }
  return found.sort((a, b) => byVaultLabel(a.record, b.record));
}

/** Presence inventory never needs a sealer or write ports. */
export interface CustomCredentialInventoryDeps {
  repo: Pick<CustomCredentialSetRepoPort, "listByWorkspace" | "project">;
}

export interface CustomCredentialReadDeps {
  repo: CustomCredentialSetRepoPort;
  sealer?: SecretSealerPort;
}

/**
 * The read model for ONE credential set. Pure DB read — no sealer, no keyring, cannot fail on a
 * misconfigured site key. Returns `null` if no row exists for `(workspaceId, id)` (not an
 * error — the caller decides whether that is a 404).
 *
 * @complexity O(1) — one `findById` lookup.
 */
export async function describeCredential(deps: CustomCredentialReadDeps, input: { workspaceId: UUID; id: UUID }): Promise<CustomCredentialSummary | null> {
  const located = await locateById(deps, input);
  return located ? toSummary(located.record, reportedScope(deps, located.scoped)) : null;
}

/**
 * The non-decrypting sibling of {@link resolveCustomCredentialByLabel}: finds a credential by its
 * exact label and returns its read model — `baseUrl`/`additionalHosts` included, since both are
 * plaintext columns (`db/schema.sqlite.ts`'s own doc) — WITHOUT ever touching `sealer`/`keyring`. Exists so
 * a caller that only needs to validate a request's target origin or render a confirmation dialog
 * (`features/custom-credentials/credentialed-request.ts`'s `resolveRequestTarget`,
 * `tool-registrations.ts`'s DELETE confirmation gate) never has to decrypt just to read two plaintext
 * fields — the same "never touches the sealer" contract {@link describeCredential} already documents,
 * applied to a label lookup instead of an id lookup.
 *
 * @complexity O(n) in the workspace's own (small) credential-set count — same `listByWorkspace` +
 *   filter shape {@link resolveCustomCredentialByLabel} uses, since this table has no `findByLabel`
 *   repo method (see that function's own doc for why).
 */
export async function describeCredentialByLabel(deps: CustomCredentialReadDeps, input: { workspaceId: UUID; label: string }): Promise<CustomCredentialSummary | null> {
  const located = (await listEffective(deps, input.workspaceId)).find(({ record }) => record.label === input.label);
  return located ? toSummary(located.record, reportedScope(deps, located.scoped)) : null;
}

/**
 * The effective credential sets this workspace uses. The admin inventory has its own unfiltered
 * read model below. Same "never decrypts" contract as {@link describeCredential}.
 *
 * @complexity O(n) in the workspace's own (small) credential-set count. One repo read, one array
 *   map, no per-row I/O.
 */
export async function listCustomCredentials(deps: CustomCredentialInventoryDeps, input: { workspaceId: UUID }): Promise<CustomCredentialSummary[]> {
  const located = await listEffective(deps, input.workspaceId);
  return Promise.all(located.map(({ scoped, record }) => toSummary(record, reportedScope(deps, scoped))));
}

/** Admin inventory includes unattached project keys and same-label site overrides. The existing
 * guarded metadata repo exposes those rows without changing runtime credential resolution.
 * @param required Metadata repositories and the current site's workspace id.
 * @returns Safe summaries only; never opens an envelope.
 * @throws Repository or metadata-validation errors propagate to the admin adapter.
 * @complexity O(n log n) time and O(n) space for n saved keys; at most two store reads, no per-key I/O.
 * @example await listCustomCredentialInventory({ deps, workspaceId });
 */
export async function listCustomCredentialInventory({ deps, workspaceId }: {
  deps: CustomCredentialInventoryDeps; workspaceId: UUID;
}, _optional = {}): Promise<CustomCredentialSummary[]> {
  const inventoryDeps = { ...deps, repo: credentialDeletionRepo({ repo: deps.repo }) };
  const stores = await Promise.all(credentialScopes(inventoryDeps, workspaceId).map(async scoped => {
    const records = await scoped.deps.repo.listByWorkspace({ workspaceId: scoped.workspaceId });
    return Promise.all(records.map(record => toSummary(record, reportedScope(deps, scoped))));
  }));
  return stores.flat().sort((a, b) => a.label.localeCompare(b.label));
}

export interface CustomCredentialWriteDeps extends CustomCredentialReadDeps {
  sealer: SecretSealerPort;
  keyring: KeyringPort;
  clock: ClockPort;
  idGen: { newId(): string };
}

/** Narrows and validates a caller-supplied `label`. Never throws a raw `TypeError` — every
 *  rejection is a {@link CustomCredentialValidationError} the route layer can map to its own `400`. */
function validateLabel(raw: unknown): string {
  if (typeof raw !== "string" || raw.trim() === "") {
    throw new CustomCredentialValidationError("label must be a non-empty string");
  }
  if (raw.length > MAX_LABEL_LENGTH) {
    throw new CustomCredentialValidationError(`label must be ${MAX_LABEL_LENGTH} characters or fewer`);
  }
  assertPlainField({ value: raw, field: "label" });
  return raw;
}

/** Narrows and validates a caller-supplied `category` against the Access Tokens page's own known
 *  set — see `types.ts`'s `CustomCredentialCategoryId` doc for why this list is duplicated (not
 *  imported) from the admin app. */
function validateCategory(raw: unknown): CustomCredentialCategoryId {
  if (typeof raw === "string") assertPlainField({ value: raw, field: "category" });
  if (typeof raw !== "string" || !isCustomCredentialCategoryId(raw)) {
    throw new CustomCredentialValidationError(`category must be one of: ${CUSTOM_CREDENTIAL_CATEGORIES.join(", ")}`);
  }
  return raw;
}

/** Narrows and validates a caller-supplied `baseUrl` — must parse as an absolute `http`/`https` URL
 *  (`new URL()` accepts far more schemes than this form should — `javascript:`, `file:`, a bare
 *  `mailto:` — so the scheme is checked explicitly rather than trusting "did not throw"). */
function validateBaseUrl(raw: unknown): string {
  if (typeof raw !== "string" || raw.trim() === "") {
    throw new CustomCredentialValidationError("baseUrl must be a non-empty string");
  }
  let parsed: URL;
  try {
    parsed = new URL(raw);
  } catch {
    throw new CustomCredentialValidationError("baseUrl must be a valid absolute URL");
  }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    throw new CustomCredentialValidationError("baseUrl must use http or https");
  }
  assertPlainField({ value: raw, field: "baseUrl" });
  return raw;
}

/** One `additionalHosts` entry's own validation — split out of {@link validateAdditionalHosts} so
 *  that function's `.map()` body stays a single call, and so each rejection names its own index. */
function validateAdditionalHostEntry(raw: unknown, index: number): string {
  if (typeof raw !== "string" || raw.trim() === "") {
    throw new CustomCredentialValidationError(`additionalHosts[${index}] must be a non-empty string`);
  }
  let parsed: URL;
  try {
    parsed = new URL(raw);
  } catch {
    throw new CustomCredentialValidationError(`additionalHosts[${index}] must be a valid absolute URL`);
  }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    throw new CustomCredentialValidationError(`additionalHosts[${index}] must use http or https`);
  }
  assertPlainField({ value: raw, field: "additionalHosts" });
  return parsed.origin;
}

/**
 * Validates and normalizes the optional `additionalHosts` field (2026-08-31, owner-driven multi-host
 * support — see `db/schema.sqlite.ts`'s `customCredentialSets.additionalHostsJson` doc). `undefined` (the
 * field was omitted) degrades to no extra hosts, matching every other optional field's "omitted is
 * not an error" contract on this store. Each entry is normalized to its own ORIGIN (scheme+host+port,
 * no path) and the result is deduped — this is what lets
 * `features/custom-credentials/credentialed-request.ts` compare a request's resolved URL origin
 * against this list with plain `===`/`.includes()`, never re-parsing at request time.
 *
 * @throws {CustomCredentialValidationError} `raw` is not an array, or any entry fails
 *   {@link validateAdditionalHostEntry}.
 * @complexity O(n) in the number of supplied hosts.
 */
function validateAdditionalHosts(raw: unknown): readonly string[] {
  if (raw === undefined) return [];
  if (!Array.isArray(raw)) {
    throw new CustomCredentialValidationError("additionalHosts must be an array of absolute http/https URLs");
  }
  return [...new Set(raw.map((entry, index) => validateAdditionalHostEntry(entry, index)))];
}

function optionalString(raw: unknown, field: string): string | undefined {
  if (raw === undefined) return undefined;
  if (typeof raw !== "string" || raw.trim() === "") {
    throw new CustomCredentialValidationError(`'${field}' must be a non-empty string when provided`);
  }
  return raw;
}

/**
 * Validates {@link UpdateCustomCredentialInput.username} — a THREE-way field, unlike
 * {@link optionalString}'s two-way "omitted or a non-empty string": this function is only ever
 * called once the caller has already checked `raw !== undefined` (omitted = leave the column alone,
 * a case this function never sees), so the two values left to distinguish are "clear it" and "set
 * it". `null` is the deliberate clear sentinel — chosen specifically because a blank string could not
 * serve double duty as both "leave alone" (the `optionalString` convention every other field on this
 * store already trained a caller to expect from a falsy value) and "clear" without one of those two
 * meanings silently winning over the other; `updateCustomCredential`'s own doc has the full
 * precedence writeup. A blank string is therefore still rejected here, same as everywhere else on
 * this store — it is neither of this field's two valid non-omitted values, not a quiet no-op.
 *
 * @throws {CustomCredentialValidationError} `raw` is present, not `null`, and not a non-empty string.
 * @complexity O(1).
 */
function validateUsernamePatch(raw: unknown): string | undefined {
  if (raw === null) return undefined;
  if (typeof raw !== "string" || raw.trim() === "") {
    throw new CustomCredentialValidationError("'username' must be a non-empty string, or null to clear it");
  }
  assertPlainField({ value: raw, field: "username" });
  return raw;
}

/**
 * Validates a caller-supplied `connection` — just `{token, username?}`, no provider dispatch (see
 * this file's own header). Never throws a raw shape error — every rejection is a
 * {@link CustomCredentialValidationError}.
 *
 * @complexity O(1) — fixed-shape field reads, no iteration.
 */
function isEmptyTokenPatch(raw: unknown): boolean {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return false;
  const token = (raw as Record<string, unknown>).token;
  return token === '' || token === undefined;
}
function normalizeStoredToken({ value }: { value: unknown }): string {
  try { return normalizeCredentialToken({ value }); }
  catch (err) { if (err instanceof CredentialInputError) throw new CustomCredentialValidationError(err.message); throw err; }
}
function assertPlainField(required: { value: string; field: string }): void {
  try { assertCredentialFreeField(required); }
  catch (err) { if (err instanceof CredentialInputError) throw new CustomCredentialValidationError(err.message); throw err; }
}

function validateConnection(raw: unknown): CustomProviderConnectionInput {
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
    throw new CustomCredentialValidationError("connection must be an object");
  }
  const value = raw as Record<string, unknown>;
  const token = normalizeStoredToken({ value: value.token });
  const username = optionalString(value.username, "username");
  if (username !== undefined) assertPlainField({ value: username, field: "username" });
  return { token, ...(username !== undefined ? { username } : {}) };
}

export interface CreateCustomCredentialInput {
  workspaceId: UUID;
  label: unknown;
  category: unknown;
  baseUrl: unknown;
  connection: unknown;
  /** Omitted = no extra hosts beyond `baseUrl`. See `validateAdditionalHosts`'s own doc. */
  additionalHosts?: unknown;
  worksFor?: unknown;
  /** `"site"` = a site-owned key. Omitted (or `"project"`) = the project store when one is
   *  attached, visible to attached sites only; this site's vault otherwise. */
  scope?: unknown;
}

/** Where a new row is written (`vendor-credentials/project-scope.ts`): the project store unless "site".
 * @throws {CustomCredentialValidationError} `scope` is neither omitted, `"site"` nor `"project"`. */
const createTarget = <D extends CustomCredentialReadDeps>(deps: D, input: { workspaceId: UUID; scope?: unknown }): ScopedCredentialDeps<D> =>
  credentialCreateTarget(deps, input, message => new CustomCredentialValidationError(message));

const duplicateLabel = (label: string) => new CustomCredentialDuplicateLabelError(`a custom credential labeled '${label}' already exists in this workspace`);

/**
 * A project row whose label this site already uses would be hidden here by the site row (site rows
 * override), so the save would look lost: refused as the same duplicate as within one store.
 */
async function assertLabelFreeOnSite(deps: CustomCredentialReadDeps, input: { target: ScopedCredentialDeps<unknown>; workspaceId: UUID; label: string }): Promise<void> {
  if (input.target.scope !== "project") return;
  const site = await deps.repo.listByWorkspace({ workspaceId: input.workspaceId });
  if (site.some((row) => row.label === input.label)) throw duplicateLabel(input.label);
}

/**
 * Translates a failed insert/update of row `id` into the domain duplicate-label error, else rethrows.
 * @throws {CustomCredentialDuplicateLabelError} The store refused `label` as taken.
 * @throws The original error otherwise.
 */
async function throwSaveError(deps: CustomCredentialReadDeps, input: { err: unknown; target: ScopedCredentialDeps<unknown>; id: UUID; label: string }): Promise<never> {
  const { err, target, id, label } = input;
  // Unattached project rows are hidden from the normal reader. Check metadata only to distinguish
  // a duplicate label from a CAS conflict; never attach or open the existing credential.
  const inventory = credentialDeletionRepo({ repo: deps.repo }).project;
  const hiddenDuplicate = target.scope === "project" && err instanceof VaultError && err.code === "conflict"
    && (await inventory!.repo.listByWorkspace({ workspaceId: target.workspaceId })).some(row => row.label === label && row.id !== id);
  // The storage kernel recognizes the label's UNIQUE (workspace_id, …, label) index on any database.
  if (isUniqueViolation(err) || hiddenDuplicate) throw target.scope === "project" ? new CustomCredentialDuplicateLabelError(`Your project already has a key named '${label}'. Use it here, or pick another name.`) : duplicateLabel(label);
  throw err;
}

/**
 * Validates, seals, and inserts a new credential set. `id` is minted here (`deps.idGen`), not
 * caller-supplied.
 *
 * @throws {CustomCredentialValidationError} `label`/`category`/`baseUrl`/`connection` fails shape
 *   validation.
 * @throws {CustomCredentialDuplicateLabelError} `(workspaceId, label)` already exists.
 * @throws {CustomCredentialSecretStoreUnconfiguredError} The site key is unavailable.
 * @complexity O(1) plus one keyring derivation, one seal, and one insert (which may itself throw on
 *   the UNIQUE index, translated here rather than propagated raw).
 */
export async function createCustomCredential(deps: CustomCredentialWriteDeps, input: CreateCustomCredentialInput): Promise<CustomCredentialSummary> {
  const label = validateLabel(input.label);
  const category = validateCategory(input.category);
  const baseUrl = validateBaseUrl(input.baseUrl);
  const additionalHosts = validateAdditionalHosts(input.additionalHosts);
  const connection = validateConnection(input.connection);
  const target = createTarget(deps, input);
  await assertLabelFreeOnSite(deps, { target, workspaceId: input.workspaceId, label });
  const id = deps.idGen.newId();
  const prepared = await customVault(target.deps).prepare({ ...customVaultScope({ workspaceId: target.workspaceId, id }),
    id, expectedRevision: null, provider: null, label,
    meta: { credentialType: "custom", worksFor: validatedWorksFor({ value: input.worksFor === undefined ? [] : input.worksFor }), category, baseUrl, additionalHosts: [...additionalHosts], username: connection.username ?? null },
    payload: { token: connection.token }, hintToken: connection.token });
  const record = customVaultRecord({ row: prepared, expectedRevision: null });
  try { await target.deps.repo.insert(record); }
  catch (err) { return throwSaveError(deps, { err, target, id, label }); }
  return toSummary(record, reportedScope(deps, target));
}

export interface UpdateCustomCredentialInput {
  workspaceId: UUID;
  id: UUID;
  /** Omitted = leave the label unchanged. */
  label?: unknown;
  /** Omitted = leave the category unchanged. */
  category?: unknown;
  /** Omitted = leave the base URL unchanged. */
  baseUrl?: unknown;
  /** Omitted = leave the additional hosts unchanged. Supplying a value REPLACES the whole list
   *  (never merges) — same "full replace, not append" contract this store's other array-ish writes
   *  don't have to disclaim only because none existed before this field. */
  additionalHosts?: unknown;
  worksFor?: unknown;
  /** Omitted = leave the stored connection untouched — same "omitting `connection` keeps the
   *  secret" contract every sibling credential route documents. */
  connection?: unknown;
  /**
   * Independent, top-level control over the plaintext `username` column — added 2026-09-01 so an
   * operator can fix a saved credential's username (the name.com incident this field exists for: the
   * saved row had no username, so every request 401'd, and the only correct value was already known —
   * re-pasting the token to say so was pure friction) WITHOUT retyping the token. Before this field
   * existed, `username` only ever changed as a side effect of a full `connection` replacement (see
   * {@link connection}'s own doc) — correct when username lived inside the sealed blob, no longer
   * necessary now that it is its own column (`db/schema.sqlite.ts`'s `customCredentialSets.username` doc).
   *
   * Three states, validated by {@link validateUsernamePatch}: omitted (`undefined`) leaves the column
   * exactly as `connection` (if supplied) would otherwise have set it; `null` explicitly clears it;
   * any other value must be a non-empty string. See `updateCustomCredential`'s own doc for the
   * precedence rule when this field AND `connection` are both supplied in the same call.
   */
  username?: unknown;
}

/** Constrain one feature service; permission checks remain in routes/tools. */
function customVault(deps: CustomCredentialResolveDeps & Partial<CustomCredentialWriteDeps>, { kind = "vendor" }: { kind?: "vendor" | "custom" } = {}) {
  return createTovuStoreVault({ ...deps, kind,
    storageError: () => new CustomCredentialSecretStoreUnconfiguredError(CREDENTIAL_MESSAGES.storage) });
}

/** Validate metadata in its original order before inspecting a replacement connection. */
function updatedMetadata({ input, existing }: {
  input: UpdateCustomCredentialInput; existing: CustomCredentialSetRecord;
}, _options = {}) {
  const label = input.label !== undefined ? validateLabel(input.label) : existing.label;
  const category = input.category !== undefined ? validateCategory(input.category) : existing.category;
  const baseUrl = input.baseUrl !== undefined ? validateBaseUrl(input.baseUrl) : existing.baseUrl;
  const additionalHosts = input.additionalHosts !== undefined ? validateAdditionalHosts(input.additionalHosts) : existing.additionalHosts;
  return { label, category, baseUrl, additionalHosts };
}

/** Blank connection patches preserve both the envelope and its saved username. */
function updatedConnection({ input, existing }: {
  input: UpdateCustomCredentialInput; existing: CustomCredentialSetRecord;
}, _options = {}) {
  const connection = input.connection !== undefined && !isEmptyTokenPatch(input.connection) ? validateConnection(input.connection) : undefined;
  let username = connection ? connection.username : existing.username;
  if (input.username !== undefined) username = validateUsernamePatch(input.username);
  return { connection, username };
}

/** Partial update: blank/omitted connection preserves the envelope, replacing a connection resets
 * its username, and a supplied top-level username wins (null clears). Username is metadata only;
 * removing the old ciphertext fallback makes clear impossible to resurrect, without opening it.
 * @complexity Constant queries/seals plus metadata size; CAS rejects a concurrent replacement.
 */
export async function updateCustomCredential(deps: CustomCredentialWriteDeps, input: UpdateCustomCredentialInput): Promise<CustomCredentialSummary> {
  // Changed where it lives: this site's own row, else the project's attached row.
  const located = await locateById(deps, input);
  if (!located) throw new CustomCredentialNotFoundError(`no custom credential '${input.id}' in this workspace`);
  const { scoped, record: existing } = located;
  const { label, category, baseUrl, additionalHosts } = updatedMetadata({ input, existing });
  const { connection, username } = updatedConnection({ input, existing });
  // A rename gets the same site-label check as a create (`assertLabelFreeOnSite`).
  if (label !== existing.label) await assertLabelFreeOnSite(deps, { target: scoped, workspaceId: input.workspaceId, label });
  const expectedRevision = existing.vaultRecord!.revision;
  const kind = existing.vaultRecord!.kind === "custom" ? "custom" : "vendor";
  const prepared = await customVault(scoped.deps, { kind }).prepare({ ...customVaultScope({ workspaceId: scoped.workspaceId, kind }), id: input.id,
    expectedRevision, provider: null, label,
    meta: { ...existing.vaultRecord!.meta, worksFor: input.worksFor === undefined ? [...(existing.worksFor ?? [])] : validatedWorksFor({ value: input.worksFor }), category, baseUrl, additionalHosts: [...additionalHosts], username: username ?? null },
    ...(connection ? { payload: { token: connection.token }, hintToken: connection.token } : {}) });
  const record = customVaultRecord({ row: prepared, expectedRevision });
  try { await scoped.deps.repo.update(record); }
  catch (err) { return throwSaveError(deps, { err, target: scoped, id: input.id, label }); }
  return toSummary(record, reportedScope(deps, scoped));
}

/**
 * Deletes a credential set. No-op (not an error) if no row exists for `(workspaceId, id)` — matches
 * `CustomCredentialSetRepoPort.delete`'s own idempotent contract and this feature's `DELETE`
 * route's documented 204-always behavior.
 *
 * @complexity O(1).
 */
export async function deleteCustomCredential(deps: CustomCredentialReadDeps, input: { workspaceId: UUID; id: UUID }): Promise<void> {
  // A project row is removed only when no other site uses it, with its attachments.
  const located = await locateById({ ...deps, repo: credentialDeletionRepo({ repo: deps.repo }) }, input);
  if (located) await located.scoped.deps.repo.delete({ workspaceId: located.scoped.workspaceId, id: input.id });
}

export interface CustomCredentialResolveDeps {
  repo: CustomCredentialSetRepoPort;
  sealer: SecretSealerPort;
}

/** Select by saved label without opening, then open only that row under its expected ownership.
 * Saved metadata is the authoritative source of allowed origins and username, including clears.
 * @throws CustomCredentialSecretStoreUnconfiguredError on crypto failure.
 * @complexity O(n) metadata selection, n workspace rows, plus one selected envelope open.
 */
export async function resolveCustomCredentialByLabel(
  deps: CustomCredentialResolveDeps,
  input: { workspaceId: UUID; label: string }
): Promise<{ id: UUID; category: CustomCredentialCategoryId; baseUrl: string; additionalHosts: readonly string[]; connection: CustomProviderConnectionInput } | null> {
  // Site row first, else the project's (`credentialScopes`); opened with the store that sealed it.
  const located = (await listEffective(deps, input.workspaceId)).find(({ record }) => record.label === input.label);
  if (!located) return null;
  const opened = await openLocated(located);
  if (!opened) return null;
  // Use metadata from the same read as the payload, so a concurrent origin/username update cannot
  // pair a new token with the old allowlist. Never fall back to an embedded legacy username.
  const { token, meta: current } = opened;
  return { id: located.record.id, category: current.category as CustomCredentialCategoryId, baseUrl: current.baseUrl as string,
    additionalHosts: current.additionalHosts as string[], connection: { token,
      ...(typeof current.username === "string" ? { username: current.username } : {}) } };
}

/** Opens one located row with the store that sealed it: its token and the metadata of that same read.
 * @throws CustomCredentialSecretStoreUnconfiguredError on crypto failure or a payload without a token. */
async function openLocated({ scoped, record }: Located<CustomCredentialResolveDeps>): Promise<{ token: string; meta: Record<string, unknown>; summary: VaultSummary } | null> {
  const kind = record.vaultRecord!.kind === "custom" ? "custom" : "vendor";
  const resolved = await customVault(scoped.deps, { kind }).get({ ...customVaultScope({ ...record, kind }), id: record.id });
  if (!resolved) return null;
  if (typeof resolved.payload?.token !== "string") throw new CustomCredentialSecretStoreUnconfiguredError(CREDENTIAL_MESSAGES.storage);
  return { token: resolved.payload.token, meta: resolved.summary.meta, summary: resolved.summary };
}

/** Keep the feature's HTTP validation error contract while reusing Jini's canonical ID parser. */
function validatedWorksFor({ value }: { value: unknown }, _options = {}): string[] {
  try { const ids = normalizeCredentialWorksFor({ value }); for (const id of ids) assertPlainField({ value: id, field: "worksFor" }); return ids; }
  catch (error) { if (error instanceof VaultError) throw new CustomCredentialValidationError("worksFor must be an array of provider IDs"); throw error; }
}

