/** Tovu's copy and real schema names ('tovu', 'tovu_'), not Jini's neutral defaults ('the source', 'app'). */
export const databaseTransferAgentToolCatalog = getDatabaseTransferAgentToolCatalog({}, { naming: TRANSFER_NAMING, messages: TOVU_TRANSFER_MESSAGES });
/** Composition adapter; all moved transfer/tool rationale now lives in @jini-ai/db/{transfer,tools}. */
const DOMAIN = "database-transfer";
const PLAN_TOOL_ID = "database_transfer_plan";
const STATUS_TOOL_ID = "database_transfer_status";
const CATALOG_BY_ID = indexCatalogById({ catalog: databaseTransferAgentToolCatalog });
export const databaseTransferDerivedRisk: DerivedRiskByToolId = new Map<string, AgentToolSideEffect>([
  [PLAN_TOOL_ID, "none"],
  [DATABASE_TRANSFER_RUN_TOOL_ID, "mutates-durable-state"],
  [SET_DESTINATION_TOOL_ID, "mutates-durable-state"],
  [STATUS_TOOL_ID, "none"],
]);

/** The slice of the route-deps bag these tools read. Structural, so this module never imports `server/routes/types`. */
export interface DatabaseTransferToolDeps extends OperatorLocaleDeps {
  readonly authorize: AuthorizeFn;
  readonly workspaceId: string;
  readonly dbOps: DbOpsPort;
  /** The site's folder name, written into the copy's marker. */
  readonly siteBinding?: { readonly name: string; readonly dir?: string };
  readonly db?: Parameters<typeof contentKernel>[0];
  /** Disposable test capture seam; runtime resolves the exact sibling of its content DB. */
  readonly databaseTransferChatSnapshot?: () => Promise<Buffer>;
  /** Test-only; defaults to the process-wide store. */
  readonly databaseTransferPlanStore?: DatabaseTransferPlanStore;
  /** The sealed, persistent store (`server/runtime/composition/deps.ts`); absent -> the in-memory fallback. */
  readonly databaseTransferDestinationStore?: DatabaseDestinationStorePort;
  /** Test-only; defaults to the `psql` adapter. */
  readonly databaseTransferTarget?: (connectionString: string) => PostgresTargetPort;
  /** Test-only; defaults to `console.warn`. Never receives a connection string or row data. */
  readonly databaseTransferFailureLog?: (line: string) => void;
}

/** Input errors name the rule, never the connection string. */
const DATABASE_TRANSFER_MODEL_FACING_ERRORS: readonly ModelFacingErrorRule[] = [
  forbiddenRule("DATABASE_TRANSFER"),
  { error: InvalidConnectionStringError, code: "DATABASE_TRANSFER_INVALID_CONNECTION_STRING" },
  { error: DestinationUnreadableError, code: "DATABASE_TRANSFER_DESTINATION_UNREADABLE" },
];


/** Read-only online backup of the exact configured chat DB; never create a missing source. */
async function captureChatSnapshot(deps: DatabaseTransferToolDeps): Promise<Buffer> {
  if (deps.databaseTransferChatSnapshot) return deps.databaseTransferChatSnapshot();
  const contentPath = deps.db === undefined ? null : await databaseFile(contentKernel(deps.db));
  if (contentPath === null) throw new Error("the chat snapshot source is not wired");
  const path = process.env.TOVU_CHAT_DB ?? join(dirname(contentPath), "chat.db");
  const dir = await mkdtemp(join(tmpdir(), "tovu-transfer-chat-"));
  let source: SqliteKernel<unknown> | undefined;
  try {
    source = openSqliteFileKernel(path, { readOnly: true });
    const snapshotPath = join(dir, "chat.db");
    await source.backupTo(snapshotPath);
    return await readFile(snapshotPath);
  } finally {
    try { await source?.close(); }
    finally { await rm(dir, { recursive: true, force: true }); }
  }
}
/** @complexity O(1) at registration; consumer adapters supply all schema/security/UI policy. */
export function buildDatabaseTransferRegistrations(deps: DatabaseTransferToolDeps, surfaces: AssistantSurfaceDeps): ToolRegistration[] {
  const destinations = deps.databaseTransferDestinationStore ?? DEFAULT_DESTINATION_STORE;
  const localeByExchange = new Map<string, Promise<string>>();
  const reportDestination = createDestinationExchangeReporter({ store: destinations, workspaceId: deps.workspaceId }, {
    localeForExchange: async ({ exchangeId }) => {
      const locale = await (localeByExchange.get(exchangeId) ?? Promise.resolve('en'));
      localeByExchange.delete(exchangeId);
      return locale;
    },
  });
  const tools = createDatabaseTransferTools({
    workspaceId: deps.workspaceId, site: deps.siteBinding?.name ?? deps.workspaceId, naming: TRANSFER_NAMING,
    clock: { nowIso: () => new Date().toISOString() },
    dbOps: deps.dbOps, plans: deps.databaseTransferPlanStore ?? DEFAULT_PLAN_STORE,
    destinations,
    target: connectionString => {
      try { assertCredentialToken({ value: connectionString, field: 'address', hosted: false }); }
      catch (err) { if (err instanceof CredentialInputError) throw new InvalidConnectionStringError(err.message); throw err; }
      return (deps.databaseTransferTarget ?? createPsqlPostgresTarget)(connectionString);
    },
    requirePermission: request => requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: request.principalId, permission: request.permission }, { entityType: request.entityType }),
    openSource: openSqliteSnapshotSource,
    catalog: (name, source) => name === "chat" ? planChatSnapshotTables(source) : planSnapshotTables(source),
    partialExclusions: (name, source) => name === "content" ? countPartialExclusions(source) : [],
    captureChatSnapshot: () => captureChatSnapshot(deps),
    failureLog: deps.databaseTransferFailureLog ?? (line => console.warn(line)), describeError: describeErrorForLog,
    schemaMismatchGuidance: "this Tovu version's Postgres layout does not match it",
    readers: { inputRecord: input => requireInputRecord({ input }), string: (input, key) => requireString({ input, key }) },
    surfaces: {
      open: ({ binding, emit }) => {
        const exchange = surfaces.surfaceExchanges.open({ binding, emit });
        if (binding.toolId === SET_DESTINATION_TOOL_ID) localeByExchange.set(exchange.id, resolveOperatorLocale({ deps, workspaceId: deps.workspaceId, principalId: binding.principalId }));
        return exchange;
      },
      askThenReport: reportDestination,
      confirmApproval: ({ ctx, plan }, options) => requireHumanConfirm({ ctx, surfaces, spec: describeTransferApproval({ plan }) }, options),
      destinationForm: exchangeId => ({ channel: "mcp-ui", payload: { resource: buildDestinationForm(exchangeId) } }),
      destinationOutcome: input => ({ channel: "mcp-ui", payload: { resource: buildDestinationOutcome(input) } }),
      dismissedParam: SURFACE_DISMISSED_PARAM, addressField: DESTINATION_ADDRESS_FIELD,
    },
  }, { messages: TOVU_TRANSFER_MESSAGES });
  return buildDomainRegistrations({ metadata: toolMetadata, domain: DOMAIN, catalogModule: "features/database-transfer/tool-registrations.ts", catalog: CATALOG_BY_ID,
    handlers: withModelFacingErrors({ handlers: Object.fromEntries(tools.map(tool => [tool.descriptor.id, tool.handler])), rules: DATABASE_TRANSFER_MODEL_FACING_ERRORS }), derivedRisk: databaseTransferDerivedRisk });
}
/** Called once by server/runtime/composition/tool-catalog-manifest.ts. */
export function contributeDatabaseTransferTools(): ToolContributor {
  return { domain: DOMAIN, build: buildDatabaseTransferRegistrations, risk: databaseTransferDerivedRisk };
}

import type { LedgerReadPort, LedgerRow } from "./timeline.js";
import type { CreateRestorePointRepoPort } from "../recovery/restore-points.js";
import type { RestorePointListPort, RestorePointRecord } from "./restore-points.js";
import type { BootLedgerPort, MigrationRunsRepoPort, SiteServeStatus, SiteStatusPort } from "./boot/reconcile-interrupted-migration.js";
import type { DbOpsPort } from "../../contracts/core/gated-mutations/ports.js";
import type { DatabaseHealthSummary, DatabaseIntrospectionPort, PendingMigration, SchemaStateSummary } from "./adapter.sqlite.js";

/**
 * @file In-memory `LedgerReadPort` double (ADR-006 rule-of-two's "one being built now" partner
 * to `db/sqlite/database-journal-repo.ts`'s `SqliteDatabaseLedgerRepo`). Backs
 * `server/app.ts`'s hermetic test/dev composition, mirroring every other feature's
 * `repo.memory.ts`/`repo.sqlite.ts` split in this codebase.
 */
export class InMemoryDatabaseLedgerRepo implements LedgerReadPort, BootLedgerPort {
  private rows: LedgerRow[] = [];

  private readonly now: () => string;

  /** @param optional.now clock for synthesized rows (defaults to the system clock). */
  constructor(initial: LedgerRow[] = [], optional: { now?: () => string } = {}) {
    this.rows = [...initial];
    this.now = optional.now ?? (() => new Date().toISOString());
  }

  async append(row: LedgerRow): Promise<void> {
    this.rows.push(row);
  }

  /** ADR-041/043/044/045 re-audit (2026-07-16, TM-adr041-043-044-045-audit-001, Finding 2 fix)
   * — mirrors `SqliteDatabaseLedgerRepo.appendInterruptedRow`'s exact row shape.
   *
   * Round-5 re-audit (TM-adr041-043-044-045-audit-001, R5-F1 / Fable's
   * R5-F1-INTERRUPTED-SECOND-BOOT-BRICK, both independently confirmed): idempotent on
   * `migrationRunId` — a second boot with the same still-unresolved migration must re-detect and
   * re-block without erroring, not treat the deterministic id as a fresh row. */
  async appendInterruptedRow(params: { siteId: string; migrationRunId: string }): Promise<void> {
    const id = `interrupted-${params.migrationRunId}`;
    if (this.rows.some((row) => row.id === id)) return;
    await this.append({
      id,
      kind: "migration.interrupted",
      createdAt: this.now(),
      restorePointId: null,
      outcome: "blocked_pending_recovery",
    });
  }

  async query(filter: {
    kind?: string;
    fromDate?: string;
    toDate?: string;
    outcome?: string;
    cursor?: string | null;
    limit: number;
  }): Promise<{ items: LedgerRow[]; nextCursor: string | null }> {
    const filtered = this.rows
      .filter((row) => !filter.kind || row.kind === filter.kind)
      .filter((row) => !filter.outcome || row.outcome === filter.outcome)
      .filter((row) => !filter.fromDate || row.createdAt >= filter.fromDate)
      .filter((row) => !filter.toDate || row.createdAt <= filter.toDate)
      .sort((a, b) => (a.createdAt === b.createdAt ? (a.id < b.id ? 1 : -1) : a.createdAt < b.createdAt ? 1 : -1));

    const startIndex = filter.cursor ? filtered.findIndex((row) => row.id === filter.cursor) + 1 : 0;
    const page = filtered.slice(startIndex, startIndex + filter.limit);
    const nextCursor = startIndex + filter.limit < filtered.length ? page[page.length - 1]?.id ?? null : null;

    return { items: page, nextCursor };
  }
}

/**
 * In-memory double for both `recovery/restore-points.ts`'s `CreateRestorePointRepoPort` (the
 * idempotency-keyed persistence side) and `database/restore-points.ts`'s `RestorePointListPort`
 * (the read side this dispatch adds) — the same dual-port shape
 * `db/sqlite/database-journal-repo.ts`'s real `SqliteRestorePointsRepo` already implements.
 * Backs `server/app.ts`'s hermetic composition.
 */
export class InMemoryRestorePointsRepo implements CreateRestorePointRepoPort, RestorePointListPort {
  private readonly rows: Array<{
    restorePointId: string;
    idempotencyKey: string;
    trigger: string;
    createdAt: string;
    createdBy: string;
    costClass?: string;
    kind?: string;
    watermarkAtCapture?: number | null;
    artifactRef?: string;
  }> = [];

  async save(row: {
    restorePointId: string;
    idempotencyKey: string;
    trigger: string;
    createdAt: string;
    createdBy: string;
    costClass?: string;
    kind?: string;
    watermarkAtCapture?: number | null;
    artifactRef?: string;
  }): Promise<void> {
    this.rows.push(row);
  }

  async findByIdempotencyKey(key: string): Promise<{ restorePointId: string; idempotencyKey: string } | null> {
    const row = this.rows.find((r) => r.idempotencyKey === key);
    return row ? { restorePointId: row.restorePointId, idempotencyKey: row.idempotencyKey } : null;
  }

  async list(): Promise<RestorePointRecord[]> {
    return [...this.rows]
      .sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1))
      .map((row) => ({
        id: row.restorePointId,
        trigger: row.trigger,
        costClass: row.costClass ?? "cheap",
        kind: row.kind ?? "file-snapshot",
        watermarkAtCapture: row.watermarkAtCapture ?? null,
        createdAt: row.createdAt,
        // In-memory `restoreFromArtifact` is a no-op regardless of this value (no real file to
        // restore into) — a fabricated in-process reference is enough to satisfy the type.
        artifactRef: row.artifactRef ?? `memory://restore-point/${row.restorePointId}`,
      }));
  }
}

/** In-memory `SiteStatusPort` double, defaulted to `"SERVING"` — no boot-time reconciliation
 * caller is wired this pass (`reconcileInterruptedMigrationOnBoot`/`evaluateBootMigrationPolicy`
 * are domain logic only, not yet invoked from a composition root's boot sequence; see this
 * dispatch's handoff), so this status only ever changes if a future route/boot-hook calls
 * `.set()`. Backs both `server/app.ts` and, until a real persisted site-status store exists,
 * `server/deps.ts` too. */
export class InMemorySiteStatusRepo implements SiteStatusPort {
  private status: SiteServeStatus = "SERVING";

  async get(_siteId: string): Promise<SiteServeStatus> {
    return this.status;
  }

  async set(_siteId: string, status: SiteServeStatus): Promise<void> {
    this.status = status;
  }
}

/** In-memory `MigrationRunsRepoPort` double (Finding 2 fix, TM-adr041-043-044-045-audit-001) —
 * `server/app.ts`'s hermetic composition never runs a real migration, so `findNonTerminalForSite`
 * always returns `null` by default; tests that DO need to simulate a crash-interrupted migration
 * can override via `setNonTerminal`. */
export class InMemoryMigrationRunsRepo implements MigrationRunsRepoPort {
  private nonTerminal: { id: string; status: string } | null = null;

  setNonTerminal(value: { id: string; status: string } | null): void {
    this.nonTerminal = value;
  }

  async findNonTerminalForSite(_siteId: string): Promise<{ id: string; status: string } | null> {
    return this.nonTerminal;
  }

  /** Round-5 re-audit (2026-07-16, TM-adr041-043-044-045-audit-001, R5-F1/R5-F2 fix) — mirrors
   * `SqliteMigrationRunsRepo.markResolved`: clears the tracked non-terminal run once resolved, so a
   * subsequent boot's `findNonTerminalForSite` no longer re-detects it. */
  async markResolved(params: { id: string }): Promise<void> {
    if (this.nonTerminal?.id === params.id) this.nonTerminal = null;
  }
}

/** In-memory `DbOpsPort` double (`core/gated-mutations/ports.ts`) — reports the same static
 * `cheap`/`file-snapshot` capability `db/sqlite/db-ops.ts`'s real `SqliteDbOpsAdapter` reports
 * for a SQLite-backed site (this codebase's only dialect today), and fabricates an in-process
 * `artifactRef` instead of performing a real online backup, since `server/app.ts`'s hermetic
 * composition never touches a real content.db file. `server/deps.ts`'s real composition uses
 * `SqliteDbOpsAdapter` instead. */
export class InMemoryDbOpsAdapter implements DbOpsPort {
  private watermark = 0;

  async getCapabilities(): Promise<{ restorePoint: { costClass: "cheap" | "expensive" | "unavailable"; kind: "file-snapshot" | "logical-dump" | "external" } }> {
    return { restorePoint: { costClass: "cheap", kind: "file-snapshot" } };
  }

  async captureRestorePoint(required: { scopeId: string }): Promise<{ artifactRef: string; watermarkAtCapture: number }> {
    this.watermark += 1;
    return { artifactRef: `memory://restore-point/${required.scopeId}/${this.watermark}`, watermarkAtCapture: this.watermark };
  }

  /** No real content.db file exists in this hermetic composition — nothing to swap, no restart
   * needed. `server/deps.ts`'s real composition uses `SqliteDbOpsAdapter.restoreFromArtifact`
   * instead, which performs the actual atomic file swap. */
  async restoreFromArtifact(_required: { artifactRef: string }): Promise<{ restartRequired: boolean }> {
    return { restartRequired: false };
  }
}

/** In-memory `DatabaseIntrospectionPort` double (`adapter.sqlite.ts`) — `server/app.ts`'s hermetic
 * composition never opens a real `content.db`/`.site-meta.json` pair, so this reports a fixed,
 * always-"in-sync" snapshot with zero pending migrations rather than touching a filesystem. Mirrors
 * `InMemoryDbOpsAdapter`'s identical "plausible static double" precedent. */
export class InMemoryDatabaseIntrospectionAdapter implements DatabaseIntrospectionPort {
  async getHealth(): Promise<DatabaseHealthSummary> {
    return { canOpenDb: true, migrationsTableReadable: true, driftStatus: "in-sync" };
  }

  async getSchemaState(): Promise<SchemaStateSummary> {
    const snapshot = { version: 0, tag: "memory" };
    return { status: "in-sync", siteMeta: snapshot, runtime: snapshot };
  }

  async listPendingMigrations(): Promise<{ items: PendingMigration[] }> {
    return { items: [] };
  }
}

import type { AgentToolDefinition as SharedAgentToolDefinition } from "@jini-ai/core";
import path from "node:path";
import { resolveProductRoot } from "#src/platform/site-dir/index";
import { readBundledDeployOpsDescriptors } from "./registry.js";
import { MAX_WAIT_SECONDS } from "./run-ops.js";
import type { DeployOpsDescriptor, DeployOpsRegistry } from "./types.js";
type AgentToolDefinition = SharedAgentToolDefinition & { inputSchema: Readonly<Record<string, unknown>> };
/** Data-only source snapshot for hermetic catalog construction; never used to authorize or import modules. */
function bundledDescriptors(read: BundledDescriptorReader): readonly DeployOpsDescriptor[] {
  try {
    return read({ sourceRoot: path.join(resolveProductRoot(), "content", "agent-plugins") });
  } catch { return []; }
}
/** Reads the bundled deploy-ops descriptors from a plugin source root (injectable for tests). */
export type BundledDescriptorReader = (input: { sourceRoot: string }) => readonly DeployOpsDescriptor[];
const platformList = (platforms: readonly DeployOpsDescriptor[]) => ` Platforms: ${platforms.map(p => `${p.id} (${p.label})`).join(", ") || "none available; enable a hosting plugin under Agent Plugins"}.`;
/** Build schemas from the loaded registry. O(platforms + eight tools); a missing registry uses bundled data only. */
export function getDeployOpsAgentToolCatalog(registry?: DeployOpsRegistry, optional: { readBundledDescriptors?: BundledDescriptorReader } = {}): AgentToolDefinition[] {
  const platforms = registry ? registry.list().map(p => p.descriptor) : bundledDescriptors(optional.readBundledDescriptors ?? readBundledDeployOpsDescriptors);
  const ids = platforms.map(p => p.id);
  const listed = platformList(platforms);
  // Secrets are an optional adapter verb set, so their tools advertise only adapters that export it
  // (github-actions has none). Bundled data cannot say which do; the handler refuses the rest.
  const secrets = registry ? registry.list().filter(p => typeof p.module.listSecrets === "function").map(p => p.descriptor) : platforms;
  const secretsListed = registry ? platformList(secrets) : " Platforms: whichever deploy platforms have a secrets adapter.";
  const common = `${listed} Use these instead of custom_credential_make_request for deploy checks on these platforms. They don't deploy or change anything; to start a deploy use deployment_ops_deploy. For a static-site publish use deployment_get_static_publish_capabilities / the publish tools instead. Refuses unknown platforms, ambiguous credentials, saved-host mismatches, and rejected auth (use custom_credential_verify).`;
  const base = { platform: { type: "string", enum: ids }, target: { type: "string", minLength: 1, maxLength: 200, description: "App name or owner/repo, as required by the platform." }, credentialLabel: { type: "string", minLength: 1, maxLength: 200 }, runId: { type: "string", pattern: "^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$" }, branch: { type: "string", minLength: 1, maxLength: 200 } };
  const definition = (name: string, description: string, properties: Record<string, unknown>, required: string[]): AgentToolDefinition => ({ name, description: description + common, sideEffects: "none", authorization: { permission: "custom-credentials.read" }, inputSchema: { type: "object", additionalProperties: false, properties, required } });
  return [
    definition("deployment_ops_status", "Check whether an app is up, running and healthy or whether a deployment workflow build passed or failed. Returns platform, target, healthy/deploying/failing/stopped/unknown state, summary, machine/job items, optional run URL and checkedAt.", base, ["platform", "target"]),
    definition("deployment_ops_logs", "Read bounded error logs to explain why a hosted app crashed or a deployment workflow build failed. Returns platform, target, lines with message and optional time/source/level, and truncated. Workflow adapters return failed steps and check annotations, not the redirected full log archive.", { ...base, limit: { type: "integer", minimum: 1, maximum: 500, default: 100 } }, ["platform", "target"]),
    definition("deployment_ops_wait", "Wait until an app is healthy or a workflow is finished; poll status every 10 seconds and tell the user when it is done. Returns reached, waitedSeconds, polls and last status; reached:false on timeout. Finished includes failure/stopped; unknown is not finished. Cancellation stops polling.", { ...base, until: { type: "string", enum: ["healthy", "finished"] }, timeoutSeconds: { type: "integer", minimum: 10, maximum: MAX_WAIT_SECONDS, default: 180 } }, ["platform", "target", "until"]),
    definition("deployment_ops_list_targets", "List my apps or other deployment targets on a supported platform before choosing one to inspect. Returns platform and targets with id, name and optional state. Listing may be unsupported by the platform; then supply a target to status.", { platform: base.platform, credentialLabel: base.credentialLabel, org: { type: "string", minLength: 1, maxLength: 200, description: "Optional organization slug." } }, ["platform"]),
    {
      name: "deployment_ops_deploy",
      description: `Deploy, ship or redeploy my server app now through a supported platform, using one saved credential. Returns platform, target, started (false means nothing was dispatched; follow the summary to select or enable a workflow), summary, and when the platform provides them runId, sha, machineIds, image and url. For workflow-based platforms, target identifies the repository holding the deployment workflow; the hosting plugin describes its workflow, ref pinning and required credential permissions. started means the platform accepted the deploy, not that it has landed: next call deployment_ops_wait with the same platform and target (plus runId when returned) until 'finished', then check the live site with fetch_live_url. Never retry a deploy whose connection dropped before checking deployment_ops_status. Refuses platforms without a deploy adapter, unknown platforms, ambiguous credentials, saved-host mismatches and rejected auth (use custom_credential_verify). Does not copy site content to the server; a static-site publish uses deployment_execute_static_publish.${listed}`,
      sideEffects: "mutates-durable-state",
      authorization: { permission: "custom-credentials.write" },
      inputSchema: { type: "object", additionalProperties: false, properties: { platform: base.platform, target: base.target, ref: { type: "string", minLength: 1, maxLength: 200, description: "Branch, tag or commit, as the platform supports; the hosting plugin's skill says which." }, workflowFile: { type: "string", description: "Optional workflow filename from an installed, active deployment config. Required when several workflows are declared." }, credentialLabel: base.credentialLabel }, required: ["platform", "target"] },
    },
    ...secretTools({ platforms: secrets.map(p => p.id), target: base.target, credentialLabel: base.credentialLabel, listed: secretsListed }),
  ];
}
/** Generic host-secrets tools; vendors are the bundled deployment plugins' adapters, never per-vendor tools. O(1). */
function secretTools(required: { platforms: string[]; target: Record<string, unknown>; credentialLabel: Record<string, unknown>; listed: string }): AgentToolDefinition[] {
  const { platforms, target, credentialLabel, listed } = required;
  const name = { type: "string", pattern: "^[A-Za-z_][A-Za-z0-9_]{0,127}$", description: "Secret (environment variable) name, e.g. TOVU_SITE_KEY." };
  const common = ` Works for any platform whose adapter supports secrets; others are refused with the list of platforms that do. Never returns a secret value or accepts one in model input.${listed}`;
  const targetProps = { platform: { type: "string", enum: platforms }, target, credentialLabel };
  return [
    {
      name: "deployment_ops_list_secrets",
      description: `List the secrets (environment variables) set on a hosted app: names, the platform's own digest and update time only, never values. Returns platform, target, secrets [{name, digest?, updatedAt?}], truncated, appliesOn (next-deploy | vendor-restart | immediately), supportsStaging and deployNeeded (true when writes wait for the next deploy).${common}`,
      sideEffects: "none",
      authorization: { permission: "custom-credentials.read" },
      inputSchema: { type: "object", additionalProperties: false, properties: targetProps, required: ["platform", "target"] },
    },
    {
      name: "deployment_ops_set_secret",
      description: `Set or copy a secret (environment variable) on a hosted app from a server-side source or a masked secure card; the assistant never sees the value. source {kind:'typed'} opens the masked card for a new key such as API_KEY; the human types the value there. source {kind:'site-key'} copies this site's own site key (needs the site-key permission); source {kind:'secret', name} copies another secret already on the same target (platform side, value never shown). Compares first: if the stored value is identical nothing is written (comparison 'same'). Replacing an existing secret asks the human to confirm on a card; creating a new one does not. dryRun:true only compares. Returns platform, target, name, source, comparison (same | different | absent | unknown), changed, fingerprint and fingerprintKind ('site-key' fingerprints match the admin Security page), appliesOn, supportsStaging, deployNeeded, optional version and dryRun, and summary; a declined card returns changed:false with cancelled/reason/note. Writes are staged where the platform allows: when deployNeeded is true, run deployment_ops_deploy afterwards.${common}`,
      sideEffects: "mutates-durable-state",
      authorization: { permission: "custom-credentials.write" },
      inputSchema: { type: "object", additionalProperties: false, properties: {
        ...targetProps, name,
        source: { type: "object", additionalProperties: false, description: "Where the server reads the value. kind 'typed' opens a secure card and takes no value; kind 'site-key' takes no name; kind 'secret' requires name (another secret on the same target).", properties: { kind: { type: "string", enum: ["site-key", "secret", "typed"] }, name }, required: ["kind"] },
        dryRun: { type: "boolean", default: false, description: "Only compare and report; write nothing." },
      }, required: ["platform", "target", "name", "source"] },
    },
    {
      name: "deployment_ops_unset_secret",
      description: `Remove a secret (environment variable) from a hosted app. Always asks the human to confirm on a card first; a name that is not set is reported, not removed. If the provider cannot list the secret with a digest or update timestamp, remove it in the provider console; Tovu has no admin screen for this operation. Returns platform, target, name, removed, appliesOn, supportsStaging, deployNeeded, optional version and summary; a declined card returns removed:false with cancelled/reason/note. When deployNeeded is true the running app keeps the variable until deployment_ops_deploy runs.${common}`,
      sideEffects: "deletes-durable-state",
      authorization: { permission: "custom-credentials.write" },
      inputSchema: { type: "object", additionalProperties: false, properties: { ...targetProps, name }, required: ["platform", "target", "name"] },
    },
  ];
}
export const deployOpsAgentToolCatalog = getDeployOpsAgentToolCatalog();

import { readFileSync } from "node:fs";
import path from "node:path";
import { resolveProductRoot } from "#src/platform/site-dir/index";
import { bundledContributionSources } from "../../agent-plugins/bundled-contribution-sources.js";
import { ToolInputError } from "@jini-ai/core";
import { defineExecutablePluginContribution, type LoadPluginContributions, loadPluginContributionsFromSource, type TrustedPluginPackage } from "../../agent-plugins/lifecycle.js";
import type { DeployOpsDescriptor, DeployOpsModule, DeployOpsRegistry, LoadedDeployOps } from "./types.js";

/** Installed modules use the same activation, bundled digest and disk containment gates as deploy targets. */
export const DEPLOY_OPS_FILENAME = "tovu-deploy-ops.json";
type ParseResult = { ok: true; descriptors: DeployOpsDescriptor[] } | { ok: false; reason: string };
const object = (value: unknown): value is Record<string, unknown> => typeof value === "object" && value !== null && !Array.isArray(value);

/** Parse data only. Duplicate ids, URL hosts and escaping paths refuse the entire manifest. O(platforms). */
export function parseDeployOpsFile(raw: string): ParseResult {
  let value: unknown;
  try { value = JSON.parse(raw); } catch { return { ok: false, reason: "not valid JSON" }; }
  if (!object(value) || value.schemaVersion !== 1) return { ok: false, reason: "schemaVersion must be 1" };
  if (!Array.isArray(value.platforms) || value.platforms.length > 32) return { ok: false, reason: "platforms must be an array of at most 32 entries" };
  const descriptors: DeployOpsDescriptor[] = [];
  const seen = new Set<string>();
  for (const [i, entry] of value.platforms.entries()) {
    const at = `platforms[${i}]`;
    if (!object(entry)) return { ok: false, reason: `${at} must be an object` };
    const reason = descriptorError({ entry, at, seen }, {});
    if (reason) return { ok: false, reason };
    const { id, label, module, hosts } = entry as unknown as DeployOpsDescriptor;
    seen.add(id); descriptors.push({ id, label, module, hosts });
  }
  return { ok: true, descriptors };
}

/** Lexical containment is checked before the lifecycle loader checks disk containment. */
function containedModule({ module }: { module: unknown }, _optional = {}): boolean {
  return typeof module === "string" && module.endsWith(".mjs") && !module.startsWith("/") && !module.includes("\\") && !module.split("/").some(s => s === ".." || s === "." || !s);
}

function validHosts({ hosts }: { hosts: unknown }, _optional = {}): boolean {
  return Array.isArray(hosts) && hosts.length > 0 && hosts.length <= 8 && hosts.every(host => typeof host === "string" && host.length <= 253 && /^(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$/.test(host));
}

function descriptorError({ entry, at, seen }: { entry: Record<string, unknown>; at: string; seen: Set<string> }, _optional = {}): string | undefined {
  const { id, label, module, hosts } = entry;
  if (typeof id !== "string" || id.length > 64 || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(id)) return `${at}.id must be a lowercase hyphenated id`;
  if (seen.has(id)) return `${at}.id '${id}' is declared twice`;
  return descriptorFieldsError({ label, module, hosts, at }, {});
}

function descriptorFieldsError({ label, module, hosts, at }: { label: unknown; module: unknown; hosts: unknown; at: string }, _optional = {}): string | undefined {
  if (typeof label !== "string" || !label.trim() || label.length > 100) return `${at}.label must be a non-empty string`;
  if (!containedModule({ module }, {})) return `${at}.module must be a contained relative .mjs path`;
  if (!validHosts({ hosts }, {})) return `${at}.hosts must be a non-empty array of HTTPS hostnames`;
  return undefined;
}

const OPTIONAL_VERBS = ["listTargets", "deploy", "listSecrets", "setSecret", "unsetSecret", "readSecret"] as const;
const SECRET_VERBS = ["listSecrets", "setSecret", "unsetSecret"] as const;
/** A half secrets adapter would list what it cannot remove (or the reverse), so the verbs and capabilities come as one set. O(1). */
function secretsShapeError(candidate: Record<string, unknown>): string | undefined {
  const present = SECRET_VERBS.filter(verb => candidate[verb] !== undefined);
  if (present.length === 0) return candidate.secretCapabilities !== undefined || candidate.readSecret !== undefined ? "secretCapabilities and readSecret need listSecrets(), setSecret() and unsetSecret()" : undefined;
  if (present.length !== SECRET_VERBS.length) return "a secrets adapter must export listSecrets(), setSecret() and unsetSecret() together";
  const caps = candidate.secretCapabilities;
  if (!object(caps) || !["next-deploy", "vendor-restart", "immediately"].includes(caps.appliesOn as string) || typeof caps.supportsStaging !== "boolean") return "secretCapabilities must declare appliesOn and supportsStaging";
  return undefined;
}

/** Export shape and secrets capabilities remain this domain's contract. @complexity O(1). */
function asOpsModule(candidate: unknown): DeployOpsModule | string {
  if (!object(candidate) || typeof candidate.status !== "function" || typeof candidate.logs !== "function" || OPTIONAL_VERBS.some(verb => candidate[verb] !== undefined && typeof candidate[verb] !== "function")) return "module must export status() and logs()";
  const reason = secretsShapeError(candidate);
  return reason ?? (candidate as unknown as DeployOpsModule);
}

const opsContribution = defineExecutablePluginContribution<DeployOpsDescriptor, DeployOpsModule>({
  filename: DEPLOY_OPS_FILENAME, contribution: "deploy ops",
  parse: ({ raw }) => parseDeployOpsFile(raw), modulePath: ({ descriptor }) => descriptor.module,
  validate: ({ exported }) => asOpsModule(exported),
  refusal: ({ descriptor, reason }) => `deploy ops platform '${descriptor.id}' was not loaded: ${reason}`,
}, {
  onReadError: ({ plugin }) => [`deploy ops from '${plugin.pluginId}' were not loaded: ${DEPLOY_OPS_FILENAME} could not be read`],
  importRefusalReason: "module could not be imported", importErrorReason: "module could not be read or imported",
});

/**
 * Import contained modules; isolate unreadable manifests, invalid exports and missing modules as refusals.
 * @param plugin - Trusted source directory. The caller owns activation/digest gates; this seam is for tests.
 * @returns Loaded modules and refusal messages; never throws for a malformed package.
 * @complexity Time and space: O(platforms), bounded to 32 entries.
 * @example await loadDeployOpsRegistryFromSource({ pluginId: "my-host", packageRoot: bundledRoot });
 */
export async function loadDeployOpsRegistryFromSource(plugin: TrustedPluginPackage, _optional: Record<string, never> = {}): Promise<DeployOpsRegistry> {
  const load = await loadPluginContributionsFromSource({ plugin, definition: opsContribution });
  return buildRegistry(load.items, load.refusals);
}

/** All Tovu bundled ops sources; category parsing and duplicate refusal stay with this registry.
 * @complexity O(p + platforms), one contained import per contribution. */
export async function loadBundledDeployOpsRegistry(required: { readonly sourceRoot: string }, _optional: Record<string, never> = {}): Promise<DeployOpsRegistry> {
  const items: LoadedDeployOps[] = [];
  const refusals: string[] = [];
  for (const plugin of bundledContributionSources({ ...required, filename: DEPLOY_OPS_FILENAME })) {
    const registry = await loadDeployOpsRegistryFromSource(plugin);
    items.push(...registry.list());
    refusals.push(...registry.refusals);
  }
  return buildRegistry(items, refusals);
}

/** Data-only enum discovery for hermetic tool catalogs, never authorization or module loading.
 * Ambiguous ids are omitted, as in the executable registry. @complexity O(p + platforms). */
export function readBundledDeployOpsDescriptors(required: { readonly sourceRoot: string }, _optional: Record<string, never> = {}): readonly DeployOpsDescriptor[] {
  const descriptors = bundledContributionSources({ ...required, filename: DEPLOY_OPS_FILENAME }).flatMap(plugin => {
    try {
      const parsed = parseDeployOpsFile(readFileSync(path.join(plugin.packageRoot, DEPLOY_OPS_FILENAME), "utf8"));
      return parsed.ok ? parsed.descriptors : [];
    } catch { return []; }
  });
  const counts = new Map<string, number>();
  for (const descriptor of descriptors) counts.set(descriptor.id, (counts.get(descriptor.id) ?? 0) + 1);
  return descriptors.filter(descriptor => counts.get(descriptor.id) === 1);
}

/**
 * Load only active, bundled-digest-trusted installed deployment packages; never fall back to source.
 * @param ctx - Workspace whose installed packages and activation records are checked fresh.
 * @returns Loaded modules and refusals, including filesystem faults; no expected failure escapes.
 * @param required - Contribution loader from this boot's lifecycle; no site-dependent module default.
 * @complexity Time: O(bundled sources + installed packages + platforms). Space: O(packages + platforms + refusals).
 * @example await loadDeployOpsRegistry({ workspaceId }, { loadContributions: lifecycle.loadPluginContributions });
 */
export async function loadDeployOpsRegistry(ctx: { workspaceId: string }, required: { readonly loadContributions: LoadPluginContributions }): Promise<DeployOpsRegistry> {
  try {
    // Only packages that ship this category in this build own it. The shared source selector
    // excludes retired packages: an old package retained until its successors are usable must
    // not contribute duplicate ids (duplicates are dropped). Installed activation and digest
    // checks still run in the lifecycle loader; this source list never authorizes an import.
    const owners = new Set(bundledContributionSources({
      sourceRoot: path.join(resolveProductRoot(), "content", "agent-plugins"), filename: DEPLOY_OPS_FILENAME,
    }).map(plugin => plugin.pluginId));
    const load = await required.loadContributions({ ...ctx, definition: opsContribution }, {
      packageRefusal: ({ plugin }) => owners.has(plugin.pluginId) ? undefined : `deploy ops from '${plugin.pluginId}' were not loaded: only bundled plugins shipping ${DEPLOY_OPS_FILENAME} may contribute`,
    });
    return buildRegistry(load.items, load.refusals);
  } catch { return buildRegistry([], ["deploy ops were not loaded: installed plugin packages could not be read"]); }
}

/** Refuse an absent id with the available ids and loader refusals, rather than guessing a platform. */
export function requirePlatform(registry: DeployOpsRegistry, id: string): LoadedDeployOps {
  const platform = registry.get(id);
  if (!platform) throw new ToolInputError({ message: `Unknown deployment ops platform '${id}'. Choose: ${registry.list().map(p => p.descriptor.id).join(", ") || "(none)"}.${registry.refusals.length ? ` ${registry.refusals.join(" ")}` : ""}` });
  return platform;
}
/** Index uniquely claimed ids. Ambiguous ids are refused for all claimants. O(platforms). */
function buildRegistry(loaded: readonly LoadedDeployOps[], inputRefusals: readonly string[]): DeployOpsRegistry {
  const map = new Map<string, LoadedDeployOps>(); const duplicates = new Set<string>(); const refusals = [...inputRefusals];
  for (const platform of loaded) { if (map.has(platform.descriptor.id)) duplicates.add(platform.descriptor.id); else map.set(platform.descriptor.id, platform); }
  for (const id of duplicates) { map.delete(id); refusals.push(`deploy ops platform '${id}' was not loaded: declared more than once`); }
  return { get: id => map.get(id), list: () => [...map.values()], refusals };
}

import type { PublishHistoryStore } from "../static-publish/publish-history.js";
import type { OperatorLocaleDeps } from "#src/features/agent-plugins/operator-locale";
import { issueCredentialSetup, type ToolFailureDiagnostic } from "#src/contracts/core/tool-failure-diagnostics";
import { nowIso } from "@jini-ai/core/primitives";
import { ToolInputError } from "@jini-ai/core";
import { makeCredentialedRequest, resolveRequestTarget, CredentialedRequestValidationError, CredentialedRequestTransportError, type CredentialedRequestDeps, listCustomCredentials, CustomCredentialNotFoundError, allowedOriginsFor } from "#src/features/custom-credentials/index";
import { EgressRefusedError } from "../../../platform/http/index.js";
import type { AuthorizeFn } from "../../../contracts/core/commands/index.js";
import { requirePlatform } from "./registry.js";
import type { DeployOpsContext, DeployOpsDeployResult, DeployOpsInput, DeployOpsResponse, DeployOpsSendRequest, DeployOpsLogs, DeployOpsRegistry, DeployOpsStatus, DeployOpsTargets, DeployOpsWaitResult, LoadedDeployOps } from "./types.js";

/** Response text is capped before parsing; the credential layer has already redacted secrets. */
export const MAX_RESPONSE_CHARS = 256_000;
/** The daemon applies no default tool timeout; this tool owns its 300s deadline and cancellation. */
export const MAX_WAIT_SECONDS = 300;
/** One module pause is short; a module that needs longer must poll, so cancellation stays prompt. */
export const MAX_MODULE_SLEEP_MS = 5_000;
export interface DeployOpsToolDeps extends OperatorLocaleDeps {
  authorize: AuthorizeFn;
  /** Shared site ledger, injected by production; optional for credential-only consumers. */
  publishHistoryStore?: PublishHistoryStore;
  workspaceId: string;
  clock: CredentialedRequestDeps["clock"];
  customCredentialSetRepo: CredentialedRequestDeps["repo"];
  siteAssistantSecretSealer: CredentialedRequestDeps["sealer"];
  /** Dedicated guarded client with redirects disabled, constructed by the composition root. */
  deployOpsHttpClient?: CredentialedRequestDeps["httpClient"];
  customCredentialsAudit?: CredentialedRequestDeps["audit"];
  loadAuthSchemes: CredentialedRequestDeps["loadAuthSchemes"];
  /** Production injects freshly gated installed packages; tests/hermetic composition inject source. */
  loadDeployOps: (ctx: { workspaceId: string }) => Promise<DeployOpsRegistry>;
  deployOpsRegistry?: DeployOpsRegistry;
  /** Workflow declared by the deployment config owner, passed by the host. */
  loadDeployWorkflowFiles?: (input: { workspaceId: string }) => Promise<readonly string[]>;
  waitClock?: WaitClock;
  /** This boot's site folder; the default site-key reader resolves the same sources the Security page does. */
  siteBinding?: { dir?: string };
  /** Test seam: this site's active site key in hex, or undefined when none is usable. Never returned to the model. */
  readSiteKey?: () => string | undefined;
}
export interface WaitClock { now(): number; sleep(ms: number, signal?: AbortSignal): Promise<void> }
const systemClock: WaitClock = {
  now: () => performance.now(),
  sleep: (ms, signal) => new Promise((resolve, reject) => {
    if (signal?.aborted) { reject(aborted()); return; }
    const finish = () => { signal?.removeEventListener("abort", onAbort); resolve(); };
    const timer = setTimeout(finish, ms);
    const onAbort = () => { clearTimeout(timer); signal?.removeEventListener("abort", onAbort); reject(aborted()); };
    signal?.addEventListener("abort", onAbort, { once: true });
  }),
};
export const aborted = () => new ToolInputError({ message: "Deployment ops wait was aborted." });
const TIMEOUT = Symbol("deployment ops timeout");

/** Internal control signal caught at the registration boundary; tools return the diagnostic. */
export class DeployCredentialSetupRequired extends ToolInputError {
  readonly credentialSetup: ToolFailureDiagnostic;
  constructor({ label, baseUrl }: { label: string; baseUrl: string }, _optional = {}) {
    super({ message: "No matching deployment credential is saved. Call credential_save with kind api to open its secure card, then retry once." });
    this.credentialSetup = issueCredentialSetup({ setupToolId: "credential_save", prefill: { kind: "api", label, baseUrl, category: "ops" } }, {});
  }
}

/** Resolve by explicit label or exactly one saved host match, without decrypting. O(credentials). */
async function credentialLabel(deps: DeployOpsToolDeps, platform: LoadedDeployOps, explicit?: string): Promise<string> {
  const credentials = await listCustomCredentials({ repo: deps.customCredentialSetRepo }, { workspaceId: deps.workspaceId });
  if (explicit !== undefined) {
    if (!credentials.some(c => c.label === explicit)) throw new DeployCredentialSetupRequired({ label: explicit, baseUrl: `https://${platform.descriptor.hosts[0]!}` }, {});
    return explicit;
  }
  const host = platform.descriptor.hosts[0]!;
  const matches = credentials.filter(c => allowedOriginsFor(c).includes(`https://${host}`));
  if (matches.length === 0) throw new DeployCredentialSetupRequired({ label: platform.descriptor.id, baseUrl: `https://${host}` }, {});
  if (matches.length !== 1) throw new ToolInputError({ message: `Several saved custom credentials match '${host}'. Set credentialLabel to one of: ${matches.map(c => c.label).sort().join(", ")}.` });
  return matches[0]!.label;
}

function requirePlatformUrl({ rawUrl, platform }: { rawUrl: string; platform: LoadedDeployOps }, _optional = {}): URL {
  let url: URL;
  try { url = new URL(rawUrl); } catch { throw new ToolInputError({ message: "Deployment ops module supplied an invalid URL." }); }
  if (url.protocol !== "https:" || url.username || url.password || url.port || !platform.descriptor.hosts.includes(url.hostname)) throw new ToolInputError({ message: `Deployment ops platform '${platform.descriptor.id}' does not allow host '${url.hostname}'.` });
  return url;
}

/** Validate both independent host bindings before any credentialed request. */
async function requireBoundUrl({ rawUrl, platform, requestDeps, workspaceId, label }: { rawUrl: string; platform: LoadedDeployOps; requestDeps: CredentialedRequestDeps; workspaceId: string; label: string }, _optional = {}): Promise<URL> {
  const url = requirePlatformUrl({ rawUrl, platform }, {});
  try { await resolveRequestTarget({ repo: requestDeps.repo }, { workspaceId, label, url: rawUrl }); }
  catch (error) {
    if (error instanceof CredentialedRequestValidationError) throw new ToolInputError({ message: `Credential '${label}' does not allow host '${url.hostname}'. Add that host to the saved credential or choose another credentialLabel.` });
    if (error instanceof CustomCredentialNotFoundError) throw new ToolInputError({ message: `No saved custom credential labeled '${label}'. Choose another credentialLabel.` });
    throw error;
  }
  return url;
}

/** Translate only known credential/transport failures without echoing provider payloads. */
function requestFailure({ error, signal, method, host, label }: { error: unknown; signal?: AbortSignal; method: string; host: string; label: string }, _optional = {}): unknown {
  if (signal?.aborted) return aborted();
  if (error instanceof EgressRefusedError) return new ToolInputError({ message: `Deployment ops host '${host}' was refused by outbound HTTP policy. Use a public HTTPS endpoint allowed by the saved credential.` });
  if (error instanceof CredentialedRequestTransportError) return new ToolInputError({ message: method === "GET" ? `Could not reach deployment ops host '${host}' using credential '${label}'. Retry the check.` : `Lost the connection to deployment ops host '${host}' during a ${method}; it may or may not have been accepted. Check deployment_ops_status before retrying.` });
  if (error instanceof CredentialedRequestValidationError || error instanceof CustomCredentialNotFoundError) return new ToolInputError({ message: `Credential '${label}' changed or no longer allows host '${host}'. Check its saved hosts or choose another credentialLabel.` });
  return error;
}

/** Response text is bounded before parsing; clipped JSON must remain text. */
function normalizeResponse({ response, transportTruncated, host, label }: { response: { status: number; bodyText: string }; transportTruncated: boolean; host: string; label: string }, _optional = {}): DeployOpsResponse {
  if (response.status === 401 || response.status === 403) throw new ToolInputError({ message: `Credential '${label}' was rejected (HTTP ${response.status}). Run custom_credential_verify with label '${label}' and check its saved token/scopes.` });
  if (response.status < 200 || response.status >= 300) throw new ToolInputError({ message: `Deployment ops host '${host}' returned HTTP ${response.status}. Check the target and retry; redirects are not followed.` });
  const text = response.bodyText.slice(0, MAX_RESPONSE_CHARS);
  const truncated = transportTruncated || response.bodyText.length > MAX_RESPONSE_CHARS;
  let json: unknown;
  if (!truncated) { try { json = JSON.parse(text); } catch { /* Plain logs are valid text. */ } }
  return { status: response.status, ...(json !== undefined ? { json } : {}), text, truncated };
}

/**
 * Bound GET/write facade. Both the platform and saved credential must allow the exact HTTPS origin.
 * `allowDelete` is set only by the secret-removal verb, so no other verb's module can send a DELETE.
 */
export async function boundContext(deps: DeployOpsToolDeps, platform: LoadedDeployOps, explicit: string | undefined, signal?: AbortSignal, options: { allowDelete?: boolean } = {}): Promise<DeployOpsContext> {
  if (!deps.deployOpsHttpClient) throw new ToolInputError({ message: "Deployment ops HTTP client is unavailable. Restart the site to rebuild its tool dependencies." });
  const label = await credentialLabel(deps, platform, explicit);
  const requestDeps: CredentialedRequestDeps = {
    repo: deps.customCredentialSetRepo,
    sealer: deps.siteAssistantSecretSealer,
    httpClient: deps.deployOpsHttpClient,
    clock: deps.clock,
    ...(deps.customCredentialsAudit ? { audit: deps.customCredentialsAudit } : {}),
    loadAuthSchemes: deps.loadAuthSchemes,
  };
  /** One guarded path for every method, so a write can never get a looser binding than a read. */
  const call = async (method: "GET" | DeployOpsSendRequest["method"], rawUrl: string, body?: unknown): Promise<DeployOpsResponse> => {
    if (signal?.aborted) throw aborted();
    const url = await requireBoundUrl({ rawUrl, platform, requestDeps, workspaceId: deps.workspaceId, label }, {});
    if (signal?.aborted) throw aborted();
    let response;
    let transportTruncated = false;
    // Preserve the text clipping flag the credential API does not expose in its returned shape.
    const boundedDeps: CredentialedRequestDeps = { ...requestDeps, httpClient: { send: async request => {
      // Auth scheme loading can yield after the earlier abort check. Recheck at the I/O boundary.
      if (signal?.aborted) throw aborted();
      const result = await requestDeps.httpClient.send({ ...request, ...(signal ? { signal } : {}), maxResponseBytes: MAX_RESPONSE_CHARS });
      transportTruncated = result.bodyTruncated === true;
      return result;
    } } };
    // `content-type` only with a body: some APIs refuse a bodyless DELETE/POST that claims JSON.
    const write = method === "GET" ? {} : body === undefined ? { headers: { accept: "application/json" } }
      : { headers: { "content-type": "application/json", accept: "application/json" }, body: JSON.stringify(body) };
    try { response = await makeCredentialedRequest(boundedDeps, { workspaceId: deps.workspaceId, label, method, url: rawUrl, ...write }); }
    catch (error) { throw requestFailure({ error, signal, method, host: url.hostname, label }, {}); }
    if (signal?.aborted) throw aborted();
    return normalizeResponse({ response, transportTruncated, host: url.hostname, label }, {});
  };
  return {
    nowIso: () => nowIso({ clock: deps.clock }),
    fail: message => { throw new ToolInputError({ message: message }); },
    sleep: ms => (deps.waitClock ?? systemClock).sleep(Math.min(Math.max(0, Number(ms) || 0), MAX_MODULE_SLEEP_MS), signal),
    get: rawUrl => call("GET", rawUrl),
    send: input => {
      if (![...["POST", "PATCH", "PUT"], ...(options.allowDelete ? ["DELETE"] : [])].includes(input.method)) throw new ToolInputError({ message: `Deployment ops module supplied unsupported method '${String(input.method)}'.` });
      return call(input.method, input.url, input.body);
    },
  };
}

type Operation = "status" | "logs" | "listTargets";
export function runDeployOps(deps: DeployOpsToolDeps, input: DeployOpsInput, operation: "status", signal?: AbortSignal): Promise<DeployOpsStatus>;
export function runDeployOps(deps: DeployOpsToolDeps, input: DeployOpsInput, operation: "logs", signal?: AbortSignal): Promise<DeployOpsLogs>;
export function runDeployOps(deps: DeployOpsToolDeps, input: DeployOpsInput, operation: "listTargets", signal?: AbortSignal): Promise<DeployOpsTargets>;
/**
 * Read through a freshly gated installed adapter, passing only a bound GET facade to the module.
 * @param deps - Saved-credential ports, audited HTTP client with redirects disabled, and test seams.
 * @param input - Platform, target, optional credential label and operation-specific selectors.
 * @param operation - Selects the normalized status, logs or target-list result.
 * @param signal - Cancels before further requests and propagates to the transport.
 * @throws {ToolInputError} Unknown platforms, credential/host/auth failures or cancelled requests.
 * @complexity Time: O(credentials + response size) plus bounded adapter requests. Space: O(response size).
 * @example await runDeployOps(deps, { platform: platformId, target: targetId }, "status", signal);
 */
export async function runDeployOps(deps: DeployOpsToolDeps, input: DeployOpsInput, operation: Operation, signal?: AbortSignal): Promise<DeployOpsStatus | DeployOpsLogs | DeployOpsTargets> {
  if (signal?.aborted) throw aborted();
  const registry = await deps.loadDeployOps({ workspaceId: deps.workspaceId });
  const platform = requirePlatform(registry, input.platform);
  if (operation === "listTargets" && !platform.module.listTargets) throw new ToolInputError({ message: `Deployment ops platform '${input.platform}' does not support listing targets. Supply a target for deployment_ops_status.` });
  const ctx = await boundContext(deps, platform, input.credentialLabel, signal);
  if (signal?.aborted) throw aborted();
  if (operation === "listTargets") return platform.module.listTargets!(ctx, { org: input.org });
  if (operation === "logs") return platform.module.logs(ctx, { ...input, limit: input.limit ?? 100 });
  return platform.module.status(ctx, input);
}

export interface DeployRequest { platform: string; target: string; ref?: string; credentialLabel?: string; workflowFile?: string }
const clip = (value: unknown) => String(value).slice(0, 2000);
function validateDeployResult({ input, result }: { input: DeployRequest; result: DeployOpsDeployResult }, _optional = {}): void {
  if (typeof result?.started !== "boolean" || typeof result.summary !== "string") throw new ToolInputError({ message: `Deployment ops platform '${input.platform}' returned an invalid deploy result.` });
  if (result.runId !== undefined && !/^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$/.test(String(result.runId))) throw new ToolInputError({ message: `Deployment ops platform '${input.platform}' returned an invalid run id.` });
}

/** Keep only the documented fields; platform/target come from the request, never from the module. O(machineIds). */
function normalizeDeployResult(input: DeployRequest, result: DeployOpsDeployResult): DeployOpsDeployResult {
  validateDeployResult({ input, result }, {});
  return {
    platform: input.platform, target: input.target, started: result.started, summary: clip(result.summary),
    ...(result.runId !== undefined ? { runId: String(result.runId) } : {}),
    ...(typeof result.sha === "string" ? { sha: clip(result.sha) } : {}),
    ...(Array.isArray(result.machineIds) ? { machineIds: result.machineIds.slice(0, 32).map(clip) } : {}),
    ...(typeof result.image === "string" ? { image: clip(result.image) } : {}),
    ...(typeof result.url === "string" && result.url.startsWith("https://") ? { url: clip(result.url) } : {}),
  };
}

/**
 * Start a deploy through a freshly gated installed adapter. The chat tool and the admin route both call this.
 * @param required - `deps`: saved-credential ports and the no-redirect HTTP client; `input`: platform, target, optional ref and credential label.
 * @param optional - `signal` cancels before further requests and propagates to the transport.
 * @returns The normalized accepted-deploy result; landing is observed afterwards with status/wait.
 * @throws {ToolInputError} Unknown or observe-only platforms, credential/host/auth failures, invalid module results, or cancellation.
 * @complexity Time: O(credentials + response size) plus bounded adapter requests. Space: O(response size).
 * @example await runDeploy({ deps, input: { platform: "github-actions", target: "owner/repo", ref: "main" } }, { signal });
 */
export async function runDeploy(required: { deps: DeployOpsToolDeps; input: DeployRequest }, optional: { signal?: AbortSignal } = {}): Promise<DeployOpsDeployResult> {
  const { deps, input } = required; const { signal } = optional;
  if (signal?.aborted) throw aborted();
  const registry = await deps.loadDeployOps({ workspaceId: deps.workspaceId });
  const platform = requirePlatform(registry, input.platform);
  if (!platform.module.deploy) {
    const deployable = registry.list().filter(p => typeof p.module.deploy === "function").map(p => p.descriptor.id);
    throw new ToolInputError({ message: `Deployment ops platform '${input.platform}' cannot deploy; it is observe-only. Platforms that can deploy: ${deployable.join(", ") || "(none)"}.` });
  }
  const ctx = await boundContext(deps, platform, input.credentialLabel, signal);
  if (signal?.aborted) throw aborted();
  const adapterInput = await deployAdapterInput({ deps, input });
  const result = await platform.module.deploy(ctx, adapterInput);
  const normalized = normalizeDeployResult(input, result);
  if (normalized.started) await recordAcceptedDeploy({ deps, platform, normalized }, {});
  return normalized;
}

async function recordAcceptedDeploy({ deps, platform, normalized }: { deps: DeployOpsToolDeps; platform: LoadedDeployOps; normalized: DeployOpsDeployResult }, _optional = {}): Promise<void> {
  // Accepted requests are successful dispatches, not proof of a healthy landing. Preserve that
  // distinction in status; never invent a URL when the adapter cannot supply one.
  // Status may describe an older healthy run (runId is optional), so acceptance stays pending.
  if (deps.publishHistoryStore) {
    try {
      await deps.publishHistoryStore.recordSuccess({ workspaceId: deps.workspaceId, entry: {
        kind: "deploy", target: platform.descriptor.id, projectName: normalized.target, url: normalized.url ?? "",
        reachable: false, status: "started", publishedAt: nowIso({ clock: deps.clock }), triggeredBy: "agent_tool",
      } });
    } catch {
      // Dispatch already succeeded; never turn a ledger failure into a duplicate deploy retry.
      // No raw error: database parameters can contain credentials or provider response data.
      console.warn("[deploy-ops] destination history write failed after accepted deploy");
    }
  }
}

/** Race an in-flight status against the deadline and cancellation. Listeners/timers always cleaned up.
 * The signal is never already aborted here: the one caller chain (`waitForDeployOps` ->
 * `pollBeforeDeadline`) checks `signal.aborted` and reaches this function synchronously, with no await
 * in between, so a pre-aborted guard here could never fire and was removed. */
async function boundedPoll(status: (signal: AbortSignal) => Promise<DeployOpsStatus>, remaining: number, signal?: AbortSignal): Promise<DeployOpsStatus> {
  const controller = new AbortController();
  let timer: ReturnType<typeof setTimeout> | undefined;
  let onAbort: (() => void) | undefined;
  const stopped = new Promise<never>((_, reject) => {
    onAbort = () => { controller.abort(); reject(aborted()); };
    signal?.addEventListener("abort", onAbort, { once: true });
    timer = setTimeout(() => { controller.abort(); reject(TIMEOUT); }, remaining);
  });
  try { return await Promise.race([status(controller.signal), stopped]); }
  finally { if (timer) clearTimeout(timer); if (onAbort) signal?.removeEventListener("abort", onAbort); }
}

async function pollBeforeDeadline({ status, clock, deadline }: { status(signal: AbortSignal): Promise<DeployOpsStatus>; clock: WaitClock; deadline: number }, { signal }: { signal?: AbortSignal } = {}): Promise<DeployOpsStatus | typeof TIMEOUT> {
  try {
    const observation = await boundedPoll(status, deadline - clock.now(), signal);
    if (signal?.aborted) throw aborted();
    return observation;
  } catch (error) { if (error === TIMEOUT) return TIMEOUT; throw error; }
}

function reachedCondition({ until, state }: { until: "healthy" | "finished"; state: DeployOpsStatus["state"] }, _optional = {}): boolean {
  return until === "healthy" ? state === "healthy" : ["healthy", "failing", "stopped"].includes(state);
}

async function sleepBeforeDeadline({ clock, deadline }: { clock: WaitClock; deadline: number }, { signal }: { signal?: AbortSignal } = {}): Promise<void> {
  const remaining = deadline - clock.now();
  if (remaining > 0) await clock.sleep(Math.min(10_000, remaining), signal);
}

function waitSettings({ deps, input }: { deps: { clock?: WaitClock; initial?: DeployOpsStatus }; input: { timeoutSeconds?: number } }, _optional = {}) {
  const clock = deps.clock ?? systemClock; const started = clock.now(); const deadline = started + (input.timeoutSeconds ?? 180) * 1000;
  const initial: DeployOpsStatus = deps.initial ?? { platform: "unknown", target: "unknown", state: "unknown", summary: "No status received before timeout.", items: [], checkedAt: "" };
  return { clock, started, deadline, initial };
}

/**
 * Poll immediately and every 10s, bounding sleeps and in-flight polls by the remaining deadline.
 * @param deps - Status reader, optional monotonic clock/sleep seam, and initial unknown observation.
 * @param input - Desired condition, timeout (default 180s; validated by the tool handler), and abort signal.
 * @returns Reached flag, elapsed seconds, attempted poll count and last observation; timeout is a result.
 * @throws {ToolInputError} Cancellation or a refusal from the status reader.
 * @complexity Time: O(timeout / 10s) polls. Space: O(one status response).
 * @example await waitForDeployOps({ status }, { until: "healthy", timeoutSeconds: 180, signal });
 */
export async function waitForDeployOps(deps: { status(signal: AbortSignal): Promise<DeployOpsStatus>; clock?: WaitClock; initial?: DeployOpsStatus }, input: { until: "healthy" | "finished"; timeoutSeconds?: number; signal?: AbortSignal }): Promise<DeployOpsWaitResult> {
  const { clock, started, deadline, initial } = waitSettings({ deps, input }, {});
  let polls = 0;
  let last = initial;
  const result = (reached: boolean): DeployOpsWaitResult => ({ reached, waitedSeconds: Math.min((clock.now() - started) / 1000, (deadline - started) / 1000), polls, last });
  while (clock.now() < deadline) {
    if (input.signal?.aborted) throw aborted();
    polls++;
    const observation = await pollBeforeDeadline({ status: deps.status, clock, deadline }, { signal: input.signal });
    if (observation === TIMEOUT) return result(false);
    last = observation;
    if (clock.now() > deadline) return result(false);
    if (reachedCondition({ until: input.until, state: last.state }, {})) return result(true);
    await sleepBeforeDeadline({ clock, deadline }, { signal: input.signal });
  }
  if (input.signal?.aborted) throw aborted();
  return result(false);
}

/** Pass active workflow choices per invocation without changing ordinary adapter input shapes. */
async function deployAdapterInput({ deps, input }: { deps: DeployOpsToolDeps; input: DeployRequest }, _options = {}): Promise<import('./types.js').DeployOpsDeployInput> {
  const workflowFiles = await deps.loadDeployWorkflowFiles?.({ workspaceId: deps.workspaceId });
  return { target: input.target, ...(input.ref === undefined ? {} : { ref: input.ref }),
    ...(input.workflowFile === undefined ? {} : { workflowFile: input.workflowFile }),
    ...(workflowFiles === undefined ? {} : { workflowFiles }) };
}

import { isDeepStrictEqual } from "node:util";
import { createHash, timingSafeEqual } from "node:crypto";
import { homedir } from "node:os";
import { ToolInputError } from "@jini-ai/core";
import { resolveRuntimeMode } from "#src/contracts/core/runtime-mode";
import { fingerprintSiteKeyHex, parseSiteKeyHex, revealSiteKeyMaterial } from "#src/features/webhooks/keyring.env";
import { siteKeySourcesForSiteDir } from "#src/features/webhooks/site-key-sources";
import { requirePlatform } from "./registry.js";
import { aborted, boundContext, type DeployOpsToolDeps } from "./run-ops.js";
import type { DeployOpsContext, DeployOpsSecretAppliesOn, DeployOpsSecretInfo, DeployOpsSecretRead, DeployOpsSecretWrite, LoadedDeployOps } from "./types.js";

/**
 * @file Generic host-secrets verbs (owner 2026-10-05: "a tool that sets and unsets secrets ... not just
 * for one host ... it should work for really any vendor"). Vendors are adapters exported by the trusted
 * deploy plugin's deploy-ops modules (`listSecrets`/`setSecret`/`unsetSecret`, optional `readSecret`);
 * this file owns everything vendor-neutral: the value source, the compare-before-write, the human
 * confirmation before an overwrite or removal, and a result that never carries a secret value.
 *
 * A value never comes from the model. `source` names where the server reads it: this site's own key
 * (`site-key`), or another secret on the same target (`secret`, copied vendor side through
 * `readSecret`). Values stay inside this process: the audit records metadata only, and the result
 * reports a one-way fingerprint.
 */

export type SecretValueSource = { kind: "site-key" } | { kind: "secret"; name: string } | { kind: "typed" };
export interface SecretTargetInput { platform: string; target: string; credentialLabel?: string }
export interface SetSecretInput extends SecretTargetInput { name: string; source: SecretValueSource; dryRun?: boolean }
export interface UnsetSecretInput extends SecretTargetInput { name: string }
/** `unknown`: the secret may exist but cannot be compared or ruled out by a complete listing. */
export type SecretComparison = "same" | "different" | "absent" | "unknown";
/** What a human is asked to approve; fixed before the card is drawn. */
export interface SecretConfirmRequest { action: "overwrite" | "remove"; platform: string; target: string; name: string; source?: string; comparison?: SecretComparison; appliesOn: DeployOpsSecretAppliesOn }
/** The model-facing shape of a card the human did not confirm (`notConfirmedResult`). */
export interface SecretNotConfirmed { cancelled: boolean; reason?: "expired" | "abandoned"; note: string }
/** The tool layer's card. A refusal carries the model-facing not-confirmed result to spread into the reply. */
export type SecretConfirm = (request: SecretConfirmRequest) => Promise<{ confirmed: true } | { confirmed: false; result: SecretNotConfirmed }>;
interface SecretWriteResultBase extends Partial<SecretNotConfirmed> {
  platform: string; target: string; name: string; appliesOn: DeployOpsSecretAppliesOn; supportsStaging: boolean; deployNeeded: boolean; summary?: string; version?: string;
}
/** Never carries a value: only the comparison verdict and a one-way fingerprint. */
export interface SetSecretResult extends SecretWriteResultBase {
  source: SecretValueSource; comparison: SecretComparison; fingerprint: string; fingerprintKind: "site-key" | "sha256"; changed: boolean; dryRun?: true;
}
export interface UnsetSecretResult extends SecretWriteResultBase { removed: boolean }

export const SECRET_NAME_PATTERN = /^[A-Za-z_][A-Za-z0-9_]{0,127}$/;
const clip = (value: unknown, max: number) => String(value).slice(0, max);
const sha256 = (value: string) => createHash("sha256").update(value, "utf8").digest();

/** Constant-time over fixed-length digests, so neither length nor prefix leaks through timing. O(n). */
function sameValue(left: string, right: string): boolean {
  return timingSafeEqual(sha256(left), sha256(right));
}

/** A site-key-shaped value gets the Security page's own fingerprint, so the two can be compared by eye. O(n). */
export function secretFingerprint(value: string): { fingerprint: string; fingerprintKind: "site-key" | "sha256" } {
  const parsed = parseSiteKeyHex(value);
  return parsed.ok ? { fingerprint: fingerprintSiteKeyHex(parsed.hex), fingerprintKind: "site-key" } : { fingerprint: sha256(value).toString("hex").slice(0, 12), fingerprintKind: "sha256" };
}

/** Same ordered sources and precedence the Security page and the keyring read; re-read on every call. */
function defaultReadSiteKey(deps: DeployOpsToolDeps): string | undefined {
  const siteDir = deps.siteBinding?.dir;
  if (!siteDir) return undefined;
  const env = process.env;
  return revealSiteKeyMaterial({ sources: siteKeySourcesForSiteDir({ siteDir, mode: resolveRuntimeMode({ env }), env, home: homedir(), cwd: process.cwd() }) }).hex;
}

function requireSiteKey(deps: DeployOpsToolDeps): string {
  const hex = deps.readSiteKey ? deps.readSiteKey() : defaultReadSiteKey(deps);
  if (!hex) throw new ToolInputError({ message: "This site has no usable site key to copy. Check Security > Site key in the admin first." });
  return hex;
}

/** Refuse unknown platforms and platforms without a secrets adapter before any credential or network work. */
async function secretsPlatform(deps: DeployOpsToolDeps, id: string, signal?: AbortSignal): Promise<LoadedDeployOps> {
  if (signal?.aborted) throw aborted();
  const registry = await deps.loadDeployOps({ workspaceId: deps.workspaceId });
  const platform = requirePlatform(registry, id);
  if (!platform.module.setSecret || !platform.module.secretCapabilities) {
    const capable = registry.list().filter(p => typeof p.module.setSecret === "function").map(p => p.descriptor.id);
    throw new ToolInputError({ message: `Deployment ops platform '${id}' has no secrets adapter. Platforms with one: ${capable.join(", ") || "(none)"}.` });
  }
  return platform;
}

function requireName(value: string, key = "name"): string {
  if (!SECRET_NAME_PATTERN.test(value)) throw new ToolInputError({ message: `${key} must be an environment variable name (letters, digits and underscores, not starting with a digit, at most 128 characters).` });
  return value;
}

/** Keep only documented fields; a malformed adapter result is refused rather than echoed. O(secrets). */
async function listNormalized(platform: LoadedDeployOps, ctx: DeployOpsContext, target: string): Promise<{ secrets: DeployOpsSecretInfo[]; truncated: boolean }> {
  const result = await platform.module.listSecrets!(ctx, { target });
  if (!Array.isArray(result?.secrets) || result.secrets.some(s => !s || typeof s.name !== "string" || !s.name)) throw new ToolInputError({ message: `Deployment ops platform '${platform.descriptor.id}' returned an invalid secret list.` });
  const secrets = result.secrets.slice(0, 500).map(s => ({ name: clip(s.name, 128), ...(typeof s.digest === "string" ? { digest: clip(s.digest, 200) } : {}), ...(typeof s.updatedAt === "string" ? { updatedAt: clip(s.updatedAt, 64) } : {}) }));
  return { secrets, truncated: result.truncated === true || result.secrets.length > 500 };
}

const applies = (platform: LoadedDeployOps) => {
  const { appliesOn, supportsStaging } = platform.module.secretCapabilities!;
  return { appliesOn, supportsStaging, deployNeeded: appliesOn === "next-deploy" };
};
const version = (write: DeployOpsSecretWrite | undefined): { version?: string } => (typeof write?.version === "string" || typeof write?.version === "number" ? { version: clip(write.version, 64) } : {});
const nextStep = (platform: LoadedDeployOps, target: string) => (platform.module.secretCapabilities!.appliesOn === "next-deploy" ? ` The running app keeps the old environment until the next deploy of '${target}' (deployment_ops_deploy).` : "");

/**
 * List a target's secret names with the vendor's digest and update time; never a value.
 * @param required - `deps`: saved-credential ports and the no-redirect client; `input`: platform, target, optional credential label.
 * @param optional - `signal` cancels before further requests.
 * @returns Names, vendor digests, update times, truncation and when writes take effect.
 * @throws {ToolInputError} Unknown or secrets-less platforms, credential/host/auth failures, malformed adapter output.
 * @complexity Time and space: O(credentials + secrets).
 * @example await runListSecrets({ deps, input: { platform: "my-host", target: "my-app" } });
 */
export async function runListSecrets(required: { deps: DeployOpsToolDeps; input: SecretTargetInput }, optional: { signal?: AbortSignal } = {}) {
  const { deps, input } = required; const { signal } = optional;
  const platform = await secretsPlatform(deps, input.platform, signal);
  const ctx = await boundContext(deps, platform, input.credentialLabel, signal);
  const listed = await listNormalized(platform, ctx, input.target);
  return { platform: input.platform, target: input.target, ...listed, ...applies(platform) };
}

/** Read the source value server side. A copy needs the adapter's read verb and a source that exists. */
async function resolveValue({ platform, ctx, input, siteKey }: { platform: LoadedDeployOps; ctx: DeployOpsContext; input: SetSecretInput; siteKey: string | undefined }, { typedValue }: { typedValue?: unknown } = {}): Promise<string> {
  if (input.source.kind === "typed") return requireTypedValue({ value: typedValue }, {});
  if (siteKey !== undefined) return siteKey;
  const source = input.source as { kind: "secret"; name: string };
  const read = await platform.module.readSecret!(ctx, { target: input.target, name: source.name });
  if (!read || !("value" in read) || typeof read.value !== "string") throw new ToolInputError({ message: `Secret '${source.name}' is not set on '${input.target}', so there is nothing to copy. List the secrets with deployment_ops_list_secrets.` });
  return read.value;
}

function comparisonOfRead({ current, value }: { current: DeployOpsSecretRead | undefined; value: string }, _optional = {}): SecretComparison | undefined {
  if (current && "value" in current && typeof current.value === "string") return sameValue(current.value, value) ? "same" : "different";
  if (current && "absent" in current && current.absent === true) return "absent";
  return undefined;
}

async function readComparison({ platform, ctx, input, value }: { platform: LoadedDeployOps; ctx: DeployOpsContext; input: SetSecretInput; value: string }, { signal }: { signal?: AbortSignal } = {}): Promise<SecretComparison | undefined> {
  if (platform.module.readSecret) {
    try {
      const current = await platform.module.readSecret(ctx, { target: input.target, name: input.name });
      return comparisonOfRead({ current, value }, {});
    } catch (error) { if (signal?.aborted) throw error; /* An unreadable value (e.g. a token without secret-read scope) degrades to a presence check. */ }
  }
  return undefined;
}

/** Compare the stored value when the adapter can read it; otherwise only a complete list can establish absence. */
async function compareCurrent(platform: LoadedDeployOps, ctx: DeployOpsContext, input: SetSecretInput, value: string, signal?: AbortSignal): Promise<SecretComparison> {
  const comparison = await readComparison({ platform, ctx, input, value }, { signal });
  if (comparison !== undefined) return comparison;
  const listed = await listNormalized(platform, ctx, input.target);
  return listed.truncated || listed.secrets.some(s => s.name === input.name) ? "unknown" : "absent";
}

/** Fail closed: an overwrite or removal without a confirmation channel never runs. */
async function confirmOrRefuse(confirm: SecretConfirm | undefined, request: SecretConfirmRequest) {
  if (!confirm) throw new ToolInputError({ message: `Changing existing secret '${request.name}' needs a human confirmation, and this call has no way to ask. Nothing was changed.` });
  return confirm(request);
}

function validateSetInput(platform: LoadedDeployOps, input: SetSecretInput): void {
  requireName(input.name);
  if (input.source.kind !== "secret") return;
  requireName(input.source.name, "source.name");
  if (input.source.name === input.name) throw new ToolInputError({ message: "source.name must differ from name; a secret cannot be copied onto itself." });
  if (!platform.module.readSecret) throw new ToolInputError({ message: `Deployment ops platform '${input.platform}' cannot read secret values, so it cannot copy one secret to another. Use source kind 'site-key'.` });
}

/** Private card-only value: preserve bytes and refuse missing values without displaying them. */
function requireTypedValue({ value }: { value: unknown }, _optional = {}): string {
  if (typeof value !== "string" || value.trim() === "" || value.length > 8192) throw new ToolInputError({ message: "The secure form requires a non-blank secret of at most 8192 characters." });
  return value;
}

function describeSource({ source }: { source: SecretValueSource }, _optional = {}): string {
  return source.kind === "site-key" ? "this site's key" : source.kind === "typed" ? "the secure card" : `secret ${source.name}`;
}

/**
 * Set one secret on a host target from a server-side source; skips the write when the value is already there.
 * @param required - `deps`: credential ports, no-redirect client, site-key reader; `input`: platform, target, name, source, optional dryRun and credential label.
 * @param optional - `signal` cancels; `confirm` asks a human before an existing secret is replaced.
 * @returns changed, comparison, the value's fingerprint, when it applies, and an optional vendor version. Never the value.
 * @throws {ToolInputError} Invalid names, unusable sources, secrets-less platforms, credential/host/auth failures, or an overwrite with no confirm channel.
 * @complexity Time: O(credentials + secrets + value length) plus at most four adapter requests. Space: O(secrets).
 * @example await runSetSecret({ deps, input: { platform: "my-host", target: "my-app", name: "TOVU_SITE_KEY", source: { kind: "site-key" } } }, { confirm });
 */
export async function runSetSecret(required: { deps: DeployOpsToolDeps; input: SetSecretInput }, optional: { signal?: AbortSignal; confirm?: SecretConfirm; typedValue?: unknown } = {}): Promise<SetSecretResult> {
  const { deps, input } = required; const { signal, confirm } = optional;
  const platform = await secretsPlatform(deps, input.platform, signal);
  validateSetInput(platform, input);
  const siteKey = input.source.kind === "site-key" ? requireSiteKey(deps) : undefined;
  const ctx = await boundContext(deps, platform, input.credentialLabel, signal);
  const value = await resolveValue({ platform, ctx, input, siteKey }, { typedValue: optional.typedValue });
  const comparison = await compareCurrent(platform, ctx, input, value, signal);
  const source = describeSource({ source: input.source }, {});
  const base = { platform: input.platform, target: input.target, name: input.name, source: input.source, comparison, ...secretFingerprint(value), ...applies(platform) };
  if (comparison === "same") return { ...base, changed: false, deployNeeded: false, summary: `'${input.name}' on '${input.target}' already holds ${source}; nothing was written.` };
  if (input.dryRun) return { ...base, changed: false, dryRun: true, deployNeeded: false, summary: `Dry run: '${input.name}' would be ${comparison === "absent" ? "created" : "replaced"} from ${source}. Nothing was written.` };
  if (comparison !== "absent") {
    const decision = await confirmOrRefuse(confirm, { action: "overwrite", platform: input.platform, target: input.target, name: input.name, source, comparison, appliesOn: base.appliesOn });
    if (!decision.confirmed) return { ...base, changed: false, deployNeeded: false, ...decision.result };
  }
  if (signal?.aborted) throw aborted();
  const write = await platform.module.setSecret!(ctx, { target: input.target, name: input.name, value });
  return { ...base, changed: true, ...version(write), summary: `Set '${input.name}' on '${input.target}' from ${source}.${nextStep(platform, input.target)}` };
}

/** Confirmation must be tied to an identifiable provider version. */
function requireSecretSnapshot({ secrets, name }: { secrets: DeployOpsSecretInfo[]; name: string }, _optional = {}): DeployOpsSecretInfo {
  const targetSnapshot = secrets.find(secret => secret.name === name);
  if (!targetSnapshot || (!targetSnapshot.digest && !targetSnapshot.updatedAt)) throw new ToolInputError({ message: "deployment_ops_unset_secret: the provider cannot identify the current secret version safely. Remove it in the provider console; nothing was deleted." });
  return targetSnapshot;
}

/**
 * Remove one secret from a host target after a human confirms; an absent name is reported, not deleted.
 * @param required - `deps`: credential ports and the no-redirect client; `input`: platform, target, name, optional credential label.
 * @param optional - `signal` cancels; `confirm` is required for an actual removal.
 * @returns removed, when the removal applies, and an optional vendor version.
 * @throws {ToolInputError} Invalid names, secrets-less platforms, credential/host/auth failures, or no confirm channel.
 * @complexity Time and space: O(credentials + secrets) plus at most three adapter requests.
 * @example await runUnsetSecret({ deps, input: { platform: "my-host", target: "my-app", name: "OLD_KEY" } }, { confirm });
 */
export async function runUnsetSecret(required: { deps: DeployOpsToolDeps; input: UnsetSecretInput }, optional: { signal?: AbortSignal; confirm?: SecretConfirm } = {}): Promise<UnsetSecretResult> {
  const { deps, input } = required; const { signal, confirm } = optional;
  const platform = await secretsPlatform(deps, input.platform, signal);
  requireName(input.name);
  const ctx = await boundContext(deps, platform, input.credentialLabel, signal, { allowDelete: true });
  const listed = await listNormalized(platform, ctx, input.target);
  const base = { platform: input.platform, target: input.target, name: input.name, ...applies(platform) };
  if (!listed.truncated && !listed.secrets.some(s => s.name === input.name)) return { ...base, removed: false, deployNeeded: false, summary: `'${input.name}' is not set on '${input.target}'; nothing was removed.` };
  const targetSnapshot = requireSecretSnapshot({ secrets: listed.secrets, name: input.name }, {});
  const decision = await confirmOrRefuse(confirm, { action: "remove", platform: input.platform, target: input.target, name: input.name, appliesOn: base.appliesOn });
  if (!decision.confirmed) return { ...base, removed: false, deployNeeded: false, ...decision.result };
  if (signal?.aborted) throw aborted();
  const current = (await listNormalized(platform, ctx, input.target)).secrets.find(secret => secret.name === input.name);
  if (!isDeepStrictEqual(current, targetSnapshot)) throw new ToolInputError({ message: "deployment_ops_unset_secret: target changed while confirmation was open. Request a new confirmation; nothing was deleted." });
  const write = await platform.module.unsetSecret!(ctx, { target: input.target, name: input.name });
  return { ...base, removed: true, ...version(write), summary: `Removed '${input.name}' from '${input.target}'.${nextStep(platform, input.target)}` };
}

