const CATALOG_BY_ID = indexCatalogById({ catalog: staticPublishAgentToolCatalog });

/**
 * This wiring layer's OWN risk classification, independent of the catalog's `sideEffects`
 * declaration (`@jini-ai/cms/core`'s `assertToolIsWirable` cross-checks the two and refuses to wire
 * on disagreement).
 */
export const staticPublishDerivedRisk: DerivedRiskByToolId = new Map<string, AgentToolSideEffect>([
  // -> resolves credential presence (`PublishCredentialSource.isConfigured`, read-only) and validates
  // config shape (`validateStaticPublishConfig`, pure). Authenticated provider inspection may
  // resolve server-side for GETs only; no provisioning, uploads or export run.
  ["deployment_preview_static_publish", "none"],
  // -> `listPublishCredentials` (a pure DB read, never decrypts — `publish-credentials/store.ts`'s own
  // doc) plus `PublishCredentialSource.isConfigured` per provider (same non-decrypting contract the
  // preview tool relies on). No write, no decrypt, no network call.
  ["deployment_get_static_publish_capabilities", "none"],
  // -> on confirm, calls `publishStaticSite`: a real `exportSite` pass plus a real provider API call
  // (the selected host plugin's deploy target) using a write-scoped credential — genuinely mutates
  // external durable state. See this file's header for the full risk story.
  ["deployment_execute_static_publish", "mutates-durable-state"],
  // -> on submit, calls `createPublishCredential`/`updatePublishCredential` — a real encrypted write to
  // `vendor_credential_sets`.
  // No secret ever transits the model (see this file's header/the catalog entry's own comment); the
  // write itself is still a genuine external-account-scoped mutation, same category (not merely "some
  // risk classification") as the publish tool above.

  // -> the host plugin module's pure `hostingSetup` over the caller's non-secret fields (never a saved
  // credential). No write, no network call, no decrypt.
  ["deployment_generate_bucket_hosting_setup", "none"],
]);

/** Composition-root-bound export operation, typed locally to avoid cross-feature type coupling.
 * The composition root closes over full application dependencies; this feature passes only options.
 */
type ExportSiteBoundFn = (options: { outputDir: string; clean?: boolean; basePath?: string }) => Promise<ExportReport>;

/** Only ports the tool handlers read, declared structurally without importing RouteDeps.
 * A real publish needs the full application graph for export; exportSiteBound captures it at the
 * composition root, so that requirement does not widen this feature's dependency contract.
 * Every other field is a direct port type, never indexed from the composition root's wide bag.
 */
export interface StaticPublishToolDeps extends OperatorLocaleDeps {
  readonly loadPluginCredentialCards?: LoadPluginCredentialCards;
  readonly siteConsent?: Pick<SiteConsentService, "deploymentCheck">;
  /** Existing shared gateway; required when publishing with infrastructure changes. */
  readonly gatedMutations?: { readonly gatewayDeps: GatewayDeps };
  readonly hostKit?: StaticPublishDeps["hostKit"];
  /** `RouteDeps.formDestination`: the site's forms and receiver key, for a host that receives submissions. */
  readonly formDestination?: StaticPublishDeps["formDestination"];
  readonly localCredentialCopy?: CredentialCopyToolDeps['localCredentialCopy'];
  readonly ownerPrincipalId?: Promise<string>;
  readonly authorize: AuthorizeFn;
  readonly workspaceId: string;
  readonly clock: Clock;
  readonly idGen: { newId(): string };
  readonly siteAssistantSecretSealer: SecretSealerPort;
  readonly siteAssistantSecretKeyring: KeyringPort;
  readonly publishExecutionMode: PublishExecutionMode;
  readonly publishHistoryStore: PublishHistoryStore;
  readonly publishCredentialVerificationCache: PublishCredentialVerificationCache;
  readonly vendorCredentialSetRepo: VendorCredentialSetRepoPort;
  /** `RouteDeps.publishOutputRootDir`, threaded down for the same reason `exportSiteBound` above is —
   *  `publishStaticSite`'s `StaticPublishInput.publishOutputRootDir` needs it directly. */
  readonly publishOutputRootDir: string;
  /** The pre-bound export call — see {@link ExportSiteBoundFn}'s own doc above for what it is and why
   *  it replaces the `routeDeps: RouteDeps` field this interface used to carry (via `extends RouteDeps`). */
  readonly exportSiteBound: ExportSiteBoundFn;
  /** Test-only override — when supplied, replaces the composed `PublishCredentialSource` entirely
   *  (DB-backed + env-fallback composition, `vendorCredentialSetRepo`/`siteAssistantSecretSealer`/
   *  `publishExecutionMode` are all ignored). Production never sets this. */
  credentialSource?: PublishCredentialSource;
  /** Test-only override for `publishStaticSite`'s own `StaticPublishDeps.buildTarget` — lets a test
   *  substitute a fake `DeployTarget` so `deployment_execute_static_publish`'s CONFIRMED path can be
   *  exercised end-to-end without ever constructing a real host plugin's
   *  client or touching `fetch` (mirrors `static-publish/adapter.ts`'s own test-injection seam,
   *  "adapter tests with a faked deploy target — do not hit real providers in tests"). Production
   *  never sets this — `publishStaticSite`'s own default (the real Jini adapters) applies. */
  buildTarget?: StaticPublishDeps["buildTarget"];
  /** `RouteDeps.loadDeployTargets` — this workspace's deploy registry, which decides which config
   *  fields a target takes and judges them. Production composition injects the installed deploy Agent Plugin
   *  (`loadDeployTargetRegistry`); a test injects a registry read from the plugin's source. */
  loadDeployTargets: (workspaceId: string) => Promise<DeployTargetRegistry>;
  /** Installed metadata; production binds the data contribution loader, never executable discovery. */
  readonly loadInstalledDeployTargets?: LoadInstalledDeployTargets;
  /** Post-save connection checks share the verifier's HTTP seam; fixtures never need real egress. */
  readonly fetchFn?: typeof fetch;
  /** Test-only override for `RouteDeps.publishHistoryStore` (2026-08-16 rework — that field is now
   *  the real, DB-backed `SqlitePublishHistoryStore` in production; see `routes/types.ts`'s own doc)
   *  — lets a test inject an `InMemoryPublishHistoryStore` so it can assert on a recorded publish (or
   *  a capabilities read) without touching a real database. Passed straight through to
   *  `runPublishAndAwait` on a confirmed publish AND used by the capabilities handler's own read, so a
   *  test sees one consistent store on both sides. Production never sets this; both paths fall back to
   *  `deps.publishHistoryStore`, so a real publish's history is visible to this tool with no wiring
   *  change outside this domain (see `publish-run.ts`'s header, "Publish history"). */
  historyStore?: PublishHistoryStore;
  /** `RouteDeps.observability`, forwarded so a confirmed publish's deploy egress is traced. */
  readonly observability?: ObservabilityPort;
  readonly tracker?: import("@jini-ai/diagnostics/observability").Tracker;
}

/** {@link StaticPublishToolDeps.loadDeployTargets}, bound by composition to installed plugins or trusted source. */
function deployTargetsLoader(deps: StaticPublishToolDeps): (workspaceId: string) => Promise<DeployTargetRegistry> {
  return deps.loadDeployTargets;
}

/**
 * Reads a tool input into a publish config for `target` (already looked up in `registry`) and plans
 * it (`planStaticPublish`, the same call `publishStaticSite` makes). A blank optional field means "not
 * set", matching the old per-target builders.
 *
 * @throws {ToolInputError} A declared field is not a string.
 * @complexity O(f) declared fields.
 */
function planToolPublish(
  registry: DeployTargetRegistry,
  raw: Record<string, unknown>,
  target: LoadedDeployTarget
): { readonly config: StaticPublishConfig; readonly plan: ReturnType<typeof planStaticPublish>; readonly detailRows: DetailRow[] } {
  requireOnlyDeclaredFields(raw, target.descriptor);
  const read = readStaticPublishConfig(target, raw, { blankAsAbsent: true });
  if (!read.ok) throw new ToolInputError({ message: read.message });
  return { config: read.config, plan: planStaticPublish(registry, read.config), detailRows: configDetailRows(read.config, target) };
}

/** The publish request's own keys; every other input key must be one of the host's config fields. */
const PUBLISH_REQUEST_KEYS: ReadonlySet<string> = new Set(["target", "projectName", "credentialId"]);

/** Only the explicit, non-secret connection choice crosses into the publish input. */
function toolCredentialChoice({ raw }: { raw: Readonly<Record<string, unknown>> }, _options = {}): { credentialId?: string } {
  if (raw.credentialId === undefined) return {};
  if (typeof raw.credentialId !== "string" || !raw.credentialId.trim()) throw new ToolInputError({ message: "credentialId must be a non-empty string naming the person's selected connection. Choose it again before previewing or executing." });
  return { credentialId: raw.credentialId };
}

/** Refuses an input key the chosen host does not declare, so nothing (a token included) reaches a
 *  publish except the host's own config fields. The schemas allow any string key because the fields
 *  come from the host's descriptor.
 *  @throws {ToolInputError} naming the first undeclared key and the fields the host takes.
 *  @complexity O(k·f) input keys by declared fields. */
function requireOnlyDeclaredFields(raw: Record<string, unknown>, descriptor: DeployTargetDescriptor): void {
  const declared = descriptor.configFields.map((field) => field.name);
  const unknown = Object.keys(raw).find((key) => !PUBLISH_REQUEST_KEYS.has(key) && !declared.includes(key));
  if (unknown === undefined) return;
  const takes = declared.length > 0 ? `It takes: ${declared.join(", ")}.` : "It takes no config fields.";
  throw new ToolInputError({ message: `'${unknown}' is not a field of ${descriptor.id}. ${takes}` });
}

/** One labelled row on a publish confirmation/outcome card. */
type DetailRow = { label: string; value: string };

/** The card rows for a publish: the target module's own `summarize` when it has one, otherwise one
 *  row per declared config field the publish carries, in declaration order and under its declared
 *  label. Which fields exist is the plugin's business, so nothing here names a host.
 *  @complexity O(f) declared fields. */
function configDetailRows(config: StaticPublishConfig, target: LoadedDeployTarget): DetailRow[] {
  if (target.module.summarize !== undefined) return target.module.summarize(config).map(({ label, value }) => ({ label, value }));
  return target.descriptor.configFields.flatMap((field) => {
    const value = config[field.name];
    return typeof value === "string" ? [{ label: field.label, value }] : [];
  });
}

const EXECUTE_STATIC_PUBLISH_TOOL_ID = "deployment_execute_static_publish";

/** The `ui://` URI for one publish-confirmation instance. Keyed by the exchange id (unique per raised
 *  dialog) rather than by an entity+version the way `deleteConfirmationUri`
 *  (`features/post/delete-confirmation-ui.ts`) keys its own — a publish has no existing row/version to
 *  key against, so the exchange id is what keeps two dialogs raised for the same target from
 *  colliding on one URI. */
function publishConfirmationUri(exchangeId: string): UIResourceUri {
  return `ui://tovu/deployment-execute-static-publish/${exchangeId}` as UIResourceUri;
}

/**
 * Renders the RESULT of a confirmed publish — what a human sees replacing the confirmation dialog
 * they just answered, once `askThenReport`'s `handle` callback has actually run `publishStaticSite`
 * (or refused to, e.g. `already-running`). See `assistant/surface-exchanges.ts`'s `askThenReport` doc
 * for the mechanism this depends on: sent under the SAME `uri` the confirmation used
 * (`publishConfirmationUri(exchangeId)`, deliberately reused rather than a fresh one), which is what
 * makes `McpUiSurfaceCard` (`@jini-ai/chat`) replace the dialog in place instead of opening a second
 * card, and what makes `McpUiHost` remount the frame cleanly (its `sessionKey` is
 * `` `${uri}:${documentText}` ``, and this document's text always differs from the confirmation's).
 *
 * `state`/`message`/`url` map straight onto Jini's `SurfaceOutcomeSpec` (`@jini-ai/ui/mcp-ui/surfaces`'s
 * `outcome.ts`) — this function's own job is only deciding the publish-specific title/details/labels,
 * the same division of labor `buildPublishConfirmationResource` above already has with
 * `buildConfirmationSurface`.
 *
 * @param spec.url - Present for `'success'` and `'partial'` only — renders one "Open site"/"Open when
 *   ready" button wired to the bridge's existing `openLink`, no new bridge plumbing. Omitted for
 *   `'failure'`: there is nothing live to open.
 * @complexity O(1) — fixed-size field reads, no iteration.
 */
function buildPublishOutcomeResource(spec: {
  exchangeId: string;
  config: StaticPublishConfig;
  detailRows: readonly DetailRow[];
  projectName: string;
  state: "success" | "partial" | "failure";
  message: string;
  url?: string;
}): UIResource {
  const { exchangeId, config, detailRows, projectName, state, message, url } = spec;
  const title = state === "success" ? "Published" : state === "partial" ? "Uploaded, not live yet" : "Publish failed";
  return buildOutcomeSurface({
    uri: publishConfirmationUri(exchangeId),
    title,
    details: [
      { label: "Target", value: config.target },
      { label: "Project name", value: projectName },
      ...detailRows,
    ],
    state,
    message,
    ...(url !== undefined ? { openLinkUrl: url, openLinkLabel: state === "partial" ? "Open when ready" : "Open site" } : {}),
    app: { appName: "tovu-deployment-execute-static-publish-outcome", appVersion: "1" },
    preferredFrameSize: ["100%", "360px"],
  });
}



/** The label prefix a credential saved from chat is created under — mirrors
 *  `apps/admin/src/features/deployment/rules.ts`'s `PUBLISH_CREDENTIAL_ROW_LABEL` ("default"). Cannot
 *  be imported directly: `apps/admin` is a genuinely separate npm workspace with no import path into
 *  this server's `src/` (spec §5's own verified finding), so this is a deliberate, documented mirror
 *  rather than a shared constant — an operator never sees or types a label for this provider on
 *  either side (spec §4c/§9). New project rows add an id suffix because other sites' unattached
 *  keys are deliberately invisible here and must never block or be overwritten by a new save. */
const CUSTOM_PROVIDER_CREDENTIAL_ROW_LABEL = "default";

/** The `ui://` URI for one propose-credential form instance — same "keyed by exchange id, not an
 *  entity+version" reasoning `publishConfirmationUri` above documents (there is no existing row to key
 *  a fresh save against). */
// The engine supplies this exchange-keyed URI to both the form and its outcome.

/** Shared `target` lookup for `deployment_preview_static_publish` and
 *  `deployment_execute_static_publish`: the input's `target` must be a host this workspace's deploy
 *  registry has loaded.
 *  @throws {ToolInputError} `raw.target` is missing, or no loaded plugin provides it.
 *  @complexity O(1) — one registry lookup. */
function requireStaticPublishTarget(raw: Record<string, unknown>, registry: DeployTargetRegistry): LoadedDeployTarget {
  const targetId = requireString({ input: raw, key: "target" });
  const target = registry.get(targetId);
  if (target === undefined) throw new ToolInputError({ message: unknownTargetMessage(registry, targetId) });
  return target;
}

/** `deployment_preview_static_publish`'s result shape — extracted purely to keep that handler's
 *  own body a flat sequence of steps. */
function buildStaticPublishPreviewResult(
  target: StaticPublishTargetId,
  validationError: string | null,
  basePath: string | undefined,
  credential: { readonly configured: boolean; readonly reason?: string }
) {
  return {
    target,
    valid: validationError === null,
    ...(validationError !== null ? { validationError } : {}),
    basePath: basePath ?? null,
    credentialsConfigured: credential.configured,
    ...(!credential.configured ? { credentialGuidance: credential.reason } : {}),
  };
}

/** Per-provider dependencies {@link buildProviderCapability} needs — the already-fetched credential
 *  summaries plus every port it reads, so the capabilities handler's `registry.list().map()` callback
 *  stays a single call per provider rather than a long inline closure. */
interface ProviderCapabilityContext {
  readonly deps: StaticPublishToolDeps;
  readonly credentialSource: PublishCredentialSource;
  readonly historyStore: PublishHistoryStore;
  readonly saved: Awaited<ReturnType<typeof listPublishCredentials>>;
}

/** {@link buildProviderCapability}'s `savedCredentials` entries: no secret, only the token's last 4. */
function mapSavedCredentials(saved: Awaited<ReturnType<typeof listPublishCredentials>>) {
  return saved.map(({ id, label, isDefault, createdAt, updatedAt, tokenTail, tokenHint, credentialType, worksFor }) => ({ id, label, isDefault, createdAt, updatedAt, tokenTail, tokenHint, credentialType, worksFor }));
}

/**
 * {@link buildProviderCapability}'s result-object assembly, split out from the value computation so
 * neither half alone carries every branch in the original 100-line closure. `verifiedAt`/`accountLabel`
 * are the two fields this handler still needs beyond what {@link buildCapabilityGuidance} itself reads.
 *
 * accountLabel prefers the default credential's stored column, healed by post-save verification,
 * and falls back to cached verification only when that column is null (an unhealed or env-only row).
 * Stored identity survives restart while the cache does not, and prevents guessing a GitHub account
 * from the human's email instead of using the verified token's actual account.
 */
function buildProviderCapabilityResult(spec: {
  readonly descriptor: DeployTargetDescriptor;
  readonly ready: boolean;
  readonly readiness: { configured: true } | { configured: false; reason: string };
  readonly verified: "valid" | "invalid" | "unreachable" | null;
  readonly verification: ReturnType<PublishCredentialVerificationCache["get"]>;
  readonly defaultCredential: { readonly accountLabel: string | null } | undefined;
  readonly lastPublish: Awaited<ReturnType<PublishHistoryStore["getLast"]>>;
  readonly savedCredentials: ReturnType<typeof mapSavedCredentials>;
  readonly credentialOrigin: "saved" | "environment" | null;
  readonly guidance: string | undefined;
}, _options = {}) {
  const { descriptor, ready, readiness, verified, verification, defaultCredential, lastPublish, savedCredentials, credentialOrigin, guidance } = spec;
  return {
    providerId: descriptor.id,
    label: descriptor.label,
    // What a publish to this host takes, besides `target` and `projectName`: pass each as a
    // top-level string property of the same name.
    configFields: descriptor.configFields.map(({ name, label, required, help }) => ({ name, label, required, ...(help !== undefined ? { help } : {}) })),
    ready,
    credentialConfigured: readiness.configured,
    credentialOrigin,
    verified,
    verifiedAt: verification?.checkedAt ?? null,
    // The verified credential's own public account login/username, when the host's verifier
    // reports one — `null` when not yet verified, or for a provider whose verifier has no reviewed
    // account field to read (see `verify.ts`'s header).
    accountLabel: defaultCredential?.accountLabel ?? verification?.accountLabel ?? null,
    lastPublish,
    savedCredentials,
    ...(guidance !== undefined ? { guidance } : {}),
  };
}

/**
 * Computes one provider's `deployment_get_static_publish_capabilities` entry — extracted from that
 * handler's own `PROVIDER_IDS.map()` callback purely to keep this domain's complexity gates: this was
 * previously a single ~100-line inline async arrow.
 *
 * `savedCredentials` include only this host's explicitly compatible keys, with defaults selected
 * after compatibility and token-only shape filtering. `credentialConfigured` comes from
 * `credentialSource.isConfigured` (a saved default, or in self-hosted mode an env var).
 *
 * `ready` means "will actually work," not merely "a credential is saved" (2026-08-16 fix: a saved
 * GitHub token GitHub rejected outright with 401 used to still report `ready: true`) — a credential
 * that is configured but never verified, that failed its last verification, or whose last check could
 * not reach the provider is NOT ready.
 *
 * `verification` is a cached, non-decrypting read only — NEVER `verifyPublishCredential` from here
 * (that decrypts and makes a real provider call; see `static-publish/verify.ts`'s own header for why
 * this handler must never be its caller).
 */
async function buildProviderCapability(loaded: LoadedDeployTarget, ctx: ProviderCapabilityContext) {
  const providerId = loaded.descriptor.id;
  const savedForVendor = ctx.saved.filter(credential => credential.publishHosts.includes(providerId))
    .map(credential => ({ ...credential, isDefault: credential.defaultFor.includes(providerId) }));
  const savedCredentials = mapSavedCredentials(savedForVendor);
  const defaultCredential = savedForVendor.find((credential) => credential.isDefault);
  const readiness = await ctx.credentialSource.isConfigured({ workspaceId: ctx.deps.workspaceId, target: providerId });
  // 2026-08-16, Defect 2: the last successful publish to this provider, if any — see
  // `publish-history.ts`'s own header for the storage design. `null` means never published (from
  // this server, in this history store) rather than an absent key, so an agent-facing JSON result
  // always carries the field.
  const lastPublish = await ctx.historyStore.getLast({ workspaceId: ctx.deps.workspaceId, target: providerId });
  const verification = readiness.configured ? ctx.deps.publishCredentialVerificationCache.get({ workspaceId: ctx.deps.workspaceId, target: providerId }) : undefined;
  const verified = verification ? verification.status : null;
  const ready = readiness.configured && verified === "valid";
  const credentialOrigin = savedCredentials.length ? "saved" : readiness.configured ? "environment" : null;
  const guidance = buildCapabilityGuidance({ providerId, readiness, verification, credentialOrigin });

  return { ...buildProviderCapabilityResult({ descriptor: loaded.descriptor, ready, readiness, verified, verification, defaultCredential, lastPublish, savedCredentials, credentialOrigin, guidance }),
    defaultForNewDestination: loaded.module.defaultForNewDestination === true,
    authenticatedPreview: loaded.module.preview !== undefined };
}

/** Preserve enabled-host readiness while exposing disabled/unknown hosts without claiming their
 * credentials were inspected. Only activation permits executable use; loader refusals remain visible.
 * @returns One host choice with explicit installation, activation and readiness states.
 * @complexity O(1) metadata; enabled hosts delegate to the existing credential/history read model.
 */
async function buildInstalledProviderCapability({ installed, registry, context }: {
  installed: InstalledDeployTarget; registry: DeployTargetRegistry; context: ProviderCapabilityContext;
}, _optional: Record<string, never> = {}) {
  const loaded = registry.get(installed.descriptor.id);
  const identity = { pluginId: installed.pluginId, enabled: installed.enabled };
  if (installed.enabled === true && loaded?.pluginId === installed.pluginId) {
    return { ...await buildProviderCapability(loaded, context), ...identity, executable: true };
  }
  return { providerId: installed.descriptor.id, label: installed.descriptor.label, ...identity,
    executable: false, ready: false, credentialConfigured: null, savedCredentials: null,
    guidance: installed.enabled === true
      ? "The hosting plugin is enabled but its target could not be loaded. Inspect refusals before publishing."
      : `Turn on Agent Plugin '${installed.pluginId}' under Admin → Agent Plugins, then call deployment_get_static_publish_capabilities again. Credentials and readiness have not been inspected for this host.` };
}

/** Every dependency {@link handlePublishConfirmationAnswer} needs to run the confirmed publish and
 *  report its result — bundled so `deployment_execute_static_publish`'s own `askThenReport` call
 *  passes a single object instead of the handler's whole closure. */
interface PublishConfirmationContext {
  readonly deps: StaticPublishToolDeps;
  readonly credentialSource: PublishCredentialSource;
  readonly historyStore: PublishHistoryStore;
  readonly exchange: SurfaceExchange;
  readonly config: StaticPublishConfig;
  /** The card's config rows, labelled from the target descriptor (see `configDetailRows`). */
  readonly detailRows: readonly DetailRow[];
  readonly target: StaticPublishTargetId;
  readonly projectName: string;
}

/**
 * Maps `publishStaticSite`'s own `StaticPublishOutcome` (via {@link handlePublishConfirmationAnswer}'s
 * `runPublishAndAwait` call) to `deployment_execute_static_publish`'s agent-facing result plus the
 * `outcome` emission that corrects the confirmation dialog with the truth (see
 * {@link handlePublishConfirmationAnswer}'s own header for why that emission exists at all).
 *
 * "Uploaded, but not yet reachable" (spec `custom-publish-provider-contract.md` §3a) — a `"partial"`
 * outcome's files DID upload (so `published: true`, never a hard failure), but the site is not
 * confirmed live yet (so `reachable: false`, never a plain success either). Structurally a distinct
 * branch from both — see `static-publish/types.ts`'s `StaticPublishOutcome` header for why
 * `outcome.ok` itself is `true | false | "partial"`, not merely a boolean.
 *
 * Every branch of `publishStaticSite`'s own failure contract (`static-publish/types.ts`'s
 * `StaticPublishOutcome` doc, `adapter.ts`'s own `catch`) is already an actionable, credential-free
 * message: `NO_CREDENTIALS_CONFIGURED` names the provider via the resolved credential source's own
 * reason text, a credential missing a host-required field (e.g. an account id) names the exact
 * missing field (the target's own `DeployError`), and `PROVIDER_ERROR` is `err.message` only — never a
 * raw response body, never a credential. Passed straight through rather than re-wrapped, and straight
 * into the outcome surface too — the same actionable text a human would need either way.
 */
function mapPublishOutcomeToToolResult(
  outcome: StaticPublishOutcome,
  exchange: Pick<SurfaceExchange, "id">,
  config: StaticPublishConfig,
  detailRows: readonly DetailRow[],
  projectName: string
): { result: unknown; outcome: SurfaceEmission } {
  if (outcome.ok === "partial") {
    return {
      result: {
        published: true,
        reachable: false,
        target: outcome.targetId,
        url: outcome.url,
        status: outcome.status,
        message: outcome.message,
        ...(outcome.deploymentId !== undefined ? { deploymentId: outcome.deploymentId } : {}),
        ...(outcome.basePath !== undefined ? { basePath: outcome.basePath } : {}),
      },
      outcome: {
        channel: "mcp-ui",
        payload: {
          resource: buildPublishOutcomeResource({ exchangeId: exchange.id, config, detailRows, projectName, state: "partial", message: outcome.message, url: outcome.url }),
        },
      },
    };
  }
  if (!outcome.ok) {
    return {
      result: { published: false, cancelled: false, code: outcome.code, message: outcome.message, ...(outcome.credentialSetup ? { credentialSetup: outcome.credentialSetup } : {}) },
      outcome: {
        channel: "mcp-ui",
        payload: { resource: buildPublishOutcomeResource({ exchangeId: exchange.id, config, detailRows, projectName, state: "failure", message: outcome.message }) },
      },
    };
  }
  return {
    result: {
      published: true,
      reachable: true,
      target: outcome.targetId,
      url: outcome.url,
      status: outcome.status,
      ...(outcome.deploymentId !== undefined ? { deploymentId: outcome.deploymentId } : {}),
      ...(outcome.basePath !== undefined ? { basePath: outcome.basePath } : {}),
    },
    outcome: {
      channel: "mcp-ui",
      payload: {
        resource: buildPublishOutcomeResource({
          exchangeId: exchange.id,
          config,
          detailRows,
          projectName,
          state: "success",
          message: `Published live at ${outcome.url}.`,
          url: outcome.url,
        }),
      },
    },
  };
}

/** The host whose credential the propose-credential tool saves: it must be loaded and declare one.
 *  @throws {ToolInputError} unknown host, or a host that takes no saved credential.
 *  @complexity O(1) — one registry lookup. */
function requireCredentialTarget(raw: Record<string, unknown>, registry: DeployTargetRegistry): { readonly descriptor: DeployTargetDescriptor; readonly credential: DeployTargetCredentialSpec } {
  const { descriptor } = requireStaticPublishTarget(raw, registry);
  if (descriptor.credential === undefined) throw new ToolInputError({ message: `${descriptor.id} takes no saved credential.` });
  return { descriptor, credential: descriptor.credential };
}

/**
 * The agent's non-secret credential-field values (form pre-fill, or hosting-setup input). Refuses a
 * secret field, so a secret can never come from the chat, and a field the host does not declare. A
 * blank value is left out.
 *
 * @throws {ToolInputError} naming the first refused key.
 * @complexity O(k·f) input keys by credential fields.
 */
function readCredentialHints(raw: Record<string, unknown>, descriptor: DeployTargetDescriptor): Record<string, string> {
  const fields = descriptor.credential?.fields ?? [];
  const hints: Record<string, string> = {};
  for (const [key, value] of Object.entries(raw)) {
    if (key === "target") continue;
    const field = fields.find((candidate) => candidate.name === key);
    if (field === undefined) {
      const takes = fields.length > 0 ? `It takes: ${fields.map((candidate) => candidate.name).join(", ")}.` : "It takes none.";
      throw new ToolInputError({ message: `'${key}' is not a credential field of ${descriptor.id}. ${takes}` });
    }
    const hint = readCredentialHint({ key, value, field, tokenField: descriptor.credential?.tokenField });
    if (hint.trim() !== "") hints[key] = hint;
  }
  return hints;
}

/** Validate a declared chat hint before allowing it into a credential form. */
function readCredentialHint({ key, value, field, tokenField }: {
  key: string; value: unknown; field: DeployTargetCredentialSpec["fields"][number]; tokenField: string | undefined;
}, _options = {}): string {
  if (field.secret === true || key === tokenField) throw new ToolInputError({ message: `'${key}' is secret: the person types it into the form, never into the chat.` });
  if (typeof value !== "string") throw new ToolInputError({ message: `'${key}' must be a string.` });
  assertCredentialFreeField({ value, field: key });
  return value;
}

/** The propose-credential form, built from the host's credential spec. Posts back on cancel rather
 *  than closing silently: with the call parked, a silent close would strand the handler for the full
 *  TTL. */
function buildProposeCredentialForm(required: {
  descriptor: DeployTargetDescriptor; credential: DeployTargetCredentialSpec; prefill: Record<string, string>; updating: boolean;
}, _optional = {}): SecretCardForm & { preferredFrameSize: readonly [string, string] } {
  const { descriptor, credential, prefill, updating } = required;
  return {
    title: `Connect ${descriptor.label}`,
    ...(credential.help !== undefined ? { description: credential.help } : {}),
    submitLabel: "Save connection",
    fields: credential.fields.flatMap((field): SecretCardField[] => {
      const base = { kind: "string" as const, name: field.name, label: field.label,
        ...(field.help !== undefined ? { hint: field.help } : {}), required: field.required };
      if (field.secret === true || field.name === credential.tokenField) {
        // The store keeps exact blank secrets on update; the form must permit that submission too.
        const secret: SecretCardField = { ...base, secret: true, required: updating ? false : field.required, allowBlank: updating || !field.required };
        if (updating && !field.required && field.name !== credential.tokenField) {
          return [secret, { kind: "boolean", name: `clear-${field.name}`, label: `Remove ${field.label}`, value: false,
            hint: "Remove the saved value when this connection is saved. Leave unchecked to keep or replace it." }];
        }
        return [secret];
      }
      return [{ ...base, ...(prefill[field.name] !== undefined ? { value: prefill[field.name] } : {}) }];
    }),
    app: { appName: "tovu-deployment-propose-custom-provider-credential", appVersion: "1" },
    preferredFrameSize: ["100%", "560px"],
  };
}

/** Only declared host fields enter the persisted connection; blank secrets keep their prior value. */
function publishConnectionValues({ targetId, credential, values }: {
  targetId: string; credential: DeployTargetCredentialSpec; values: Readonly<Record<string, unknown>>;
}, _optional = {}): Record<string, unknown> {
  const connection: Record<string, unknown> = { providerId: targetId };
  for (const field of credential.fields) {
    // The form submits a blank optional secret as ""; omitted, the store reads it as not provided
    // on create and keeps the stored one on update.
    const blankOptionalSecret = values[field.name] === "" && field.secret === true && !field.required;
    // The explicit remove choice wins over typed text; blank alone still keeps the saved secret.
    if (values[`clear-${field.name}`] === true) connection[field.name] = null;
    else if (typeof values[field.name] === "string" && !blankOptionalSecret) connection[field.name] = values[field.name];
  }
  return connection;
}

/** An explicit default wins; a sole visible row is also an unambiguous update target. */
function publishCredentialToUpdate({ rows, targetId }: { rows: Awaited<ReturnType<typeof listPublishCredentials>>; targetId: string }, _optional = {}) {
  const candidates = rows.filter(row => row.providerId === targetId);
  return candidates.find(row => row.isDefault) ?? (candidates.length === 1 ? candidates[0] : undefined);
}

/**
 * Saves the submitted form as the host's connection: updates its default or sole visible row,
 * otherwise creates a distinct project key. Only the host's declared
 * fields are forwarded; `publish-credentials/store.ts` is the one place that decides what is valid
 * (the form ships `novalidate`, so this is the real enforcement point). Its messages name fields,
 * never values.
 *
 * @complexity O(n) in the workspace's saved credential count.
 */
async function saveProposedCredential(required: {
  deps: StaticPublishToolDeps; targetId: string; credential: DeployTargetCredentialSpec;
  values: Readonly<Record<string, unknown>>; signal: AbortSignal;
}, _optional = {}): Promise<{ credentialId: string; tokenHint: CredentialTokenHint | null; usedByThisSite: boolean }> {
  const { deps, targetId, credential, values, signal } = required;
  const connection = publishConnectionValues({ targetId, credential, values });
  const repo = abortGuardedCredentialRepo({ store: deps.vendorCredentialSetRepo, signal });
  const writeDeps: PublishCredentialWriteDeps = {
    repo,
    loadDeployTargets: deployTargetsLoader(deps),
    sealer: deps.siteAssistantSecretSealer,
    keyring: deps.siteAssistantSecretKeyring,
    clock: deps.clock,
    idGen: deps.idGen,
  };
  const saved = await listPublishCredentials(writeDeps, { workspaceId: deps.workspaceId });
  const existing = publishCredentialToUpdate({ rows: saved, targetId });
  // A failed replacement check must leave the working default key intact, before any seal/write.
  if (existing) await checkPublishReplacement({ deps, targetId, credential, connection });
  // Cancellation may arrive during the metadata read or probe; refuse before invoking persistence.
  signal.throwIfAborted();
  const stored = existing
    ? await updatePublishCredential(writeDeps, { workspaceId: deps.workspaceId, id: existing.id, connection })
    : await createPublishCredential(writeDeps, { workspaceId: deps.workspaceId, label: `${CUSTOM_PROVIDER_CREDENTIAL_ROW_LABEL}-${deps.idGen.newId()}`, connection,
      // New project keys stay non-default while the shared save-result path attaches them to this site.
      ...(deps.vendorCredentialSetRepo.project ? { isDefault: false } : {}) });
  return { credentialId: stored.id, tokenHint: stored.tokenHint ?? null, usedByThisSite: existing !== undefined || stored.scope !== "project" };
}

/** Reuse the provider-owned verifier only where replacement would destroy an existing key.
 * @throws PublishCredentialValidationError with fixed copy on refusal/unavailability; preserves legacy hosts without checks.
 * @complexity One registry lookup/load plus one bounded provider check, no persistence.
 */
async function checkPublishReplacement({ deps, targetId, credential, connection }: {
  deps: StaticPublishToolDeps; targetId: string; credential: DeployTargetCredentialSpec; connection: Record<string, unknown>;
}, _options = {}): Promise<void> {
  // A blank secret keeps the stored one (store.ts updatedConnection), so no working key is replaced.
  // A blank OPTIONAL secret is no reason to skip checking a replaced token.
  if (credential.fields.some(field => (field.secret === true && field.required || field.name === credential.tokenField) && !connection[field.name])) return;
  const registry = await deployTargetsLoader(deps)(deps.workspaceId);
  if (!registry.get(targetId)?.module.verifyCredential) return;
  const verification = await verifySubmittedPublishCredential({
    deps: { loadDeployTargets: async () => registry, clock: { nowIso: () => clockNowIso({ clock: deps.clock }) }, fetchFn: deps.fetchFn, observability: deps.observability },
    workspaceId: deps.workspaceId, target: targetId, spec: credential,
    connection: connection as Parameters<typeof verifySubmittedPublishCredential>[0]['connection'],
  });
  if (verification.status === 'valid') return;
  throw new PublishCredentialValidationError(verification.status === 'invalid'
    ? 'This key was refused for this purpose. Nothing was saved. The previous key was kept.'
    : "The service couldn't be reached. Nothing was saved. The previous key was kept.");
}

/**
 * `deployment_propose_custom_provider_credential`'s domain save and post-save probe — kept separate
 * so their cost is measured independently of the engine's exchange lifecycle.
 * @complexity One existing credential write plus an optional provider verification.
 */
async function saveProposeCredential(required: {
  deps: StaticPublishToolDeps; targetId: string; credential: DeployTargetCredentialSpec;
  values: Readonly<Record<string, unknown>>; signal: AbortSignal; locale: string;
}, _optional = {}) {
  const { deps, targetId, locale } = required;
  const saveResult = await saveProposedCredential(required);

  // NEVER echoes a field value, secret or not. Owner 2026-10-07: the submitted human card
  // now authorizes the same post-save read-only check as the admin form. Model-only reads stay probe-free.
  let connection: 'saved' | 'connected' | 'auth' | 'timeout' | 'unreachable' = 'saved';
  try {
    const registry = await deployTargetsLoader(deps)(deps.workspaceId);
    if (saveResult.usedByThisSite && registry.get(targetId)?.module.verifyCredential) {
      const verification = await verifyPublishCredentialById({
        repo: deps.vendorCredentialSetRepo, sealer: deps.siteAssistantSecretSealer,
        cache: deps.publishCredentialVerificationCache, clock: { nowIso: () => clockNowIso({ clock: deps.clock }) },
        loadDeployTargets: deployTargetsLoader(deps), observability: deps.observability, fetchFn: deps.fetchFn,
      }, { workspaceId: deps.workspaceId, id: saveResult.credentialId });
      connection = credentialConnectionStatus({ verification });
    }
  } catch { connection = 'unreachable'; }
  const hint = formatCredentialHint({ hint: saveResult.tokenHint, locale });
  return { saved: true as const, credentialId: saveResult.credentialId, providerId: targetId, connected: connection === 'connected', connection,
    tokenHint: saveResult.tokenHint, message: `${hint ? `${hint}. ` : ''}${credentialText({ id: connection, locale })}` };

}

/** Translate verification into the credential card's existing connection vocabulary. */
function credentialConnectionStatus({ verification }: {
  verification: Awaited<ReturnType<typeof verifyPublishCredentialById>>;
}, _options = {}): 'connected' | 'auth' | 'timeout' | 'unreachable' {
  if (verification?.status === 'valid') return 'connected';
  if (verification?.status === 'invalid') return 'auth';
  return verification?.message === credentialText({ id: 'timeout' }) ? 'timeout' : 'unreachable';
}

/** All blocked assistant publishes report the same event and product source. */
function trackBlockedToolPublish({ deps, principalId, target, reasonClass }: { deps: StaticPublishToolDeps; principalId: string; target: string; reasonClass: "config" | "consent" | "busy" }, _options = {}): void {
  deps.tracker?.capture({ name: "site_publish_blocked", userId: principalId }, { properties: { target, reasonClass, source: "assistant" } });
}

/** Consent remains a fail-closed preflight before credential reads or publishing. */
async function checkToolPublishConsent({ deps, principalId }: {
  deps: StaticPublishToolDeps; principalId: string;
}, _options = {}) {
  return deps.siteConsent
    ? await deps.siteConsent.deploymentCheck({ principalId, permission: 'deployments.publish' })
    : deploymentRefusal({ problems: [{ code: 'CONSENT_UNAVAILABLE', message: 'Cookie consent readiness is unavailable. No publish was started.' }] });
}

/**
 * Builds this domain's `ToolRegistration[]` — the same shape every other domain's
 * `build<Domain>Registrations` produces (see e.g. `recovery/tool-registrations.ts`'s
 * `buildRecoveryRegistrations`). Called by `assistant/tool-registrations.ts`, which imports
 * `buildStaticPublishRegistrations`/`staticPublishDerivedRisk` from this file and lists them as
 * their own `"static-publish"` entry in `DOMAIN_SLICES` — see that file's own comment on that entry
 * for why static-publish stays a separate slice rather than folding into this directory's sibling
 * `deployments`/`agent-tools.ts` slice.
 *
 * @param deps - `StaticPublishToolDeps` plus this file's own test-only overrides (`credentialSource`,
 *   `buildTarget`). `credentialSource` defaults to the same DB-first, env-fallback-only-in-
 *   `"self-hosted-cli"`-mode composition `publish-site.ts`'s route constructs.
 * @param surfaces - The held-open confirmation exchange store `deployment_execute_static_publish`
 *   parks on — see this file's header. Required, matching `buildPostRegistrations`' own shape (the
 *   other domain whose gate needs this), since a domain with no store at all could never wire this
 *   tool's gate at all.
 * @complexity O(1) registration-time cost; each wired handler's own cost is documented at its call
 *   site above (preview/capabilities: O(1) plus the provider count; execute: one `exportSite` pass
 *   plus one provider API call, only after a human confirms).
 */
/** Bind publish credential saving to its existing descriptor, permission and sealed-store owner.
 * @param required - Existing publish dependencies and shared surface exchanges.
 * @returns An internal save adapter, never a retired tool registration.
 * @example buildPublishHostCredentialHandler({ deps, surfaces });
 * @complexity O(1) binding; invocation reads the provider registry and saved credential summaries.
 */
export function buildPublishHostCredentialHandler({ deps, surfaces }: { deps: StaticPublishToolDeps; surfaces: AssistantSurfaceDeps }, _optional = {}): ToolHandler {
  return async (ctx, optional = {}) => {
      const raw = requireInputRecord({ input: ctx.input });
      const { descriptor, credential } = requireCredentialTarget(raw, await deployTargetsLoader(deps)(deps.workspaceId));
      const prefill = readCredentialHints(raw, descriptor);

      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "deployments.credentials.write" }, { entityType: "site-publish" });

      // Fail closed rather than degrade — identical posture to the execute-publish guard above.
      // The engine supplies a ToolInputError so the refusal remains caller-safe through transport.
      const stored = await listPublishCredentials({ repo: deps.vendorCredentialSetRepo, loadDeployTargets: deployTargetsLoader(deps) }, { workspaceId: deps.workspaceId });
      const updating = publishCredentialToUpdate({ rows: stored, targetId: descriptor.id }) !== undefined;
      const locale = await resolveOperatorLocale({ deps, workspaceId: deps.workspaceId, principalId: ctx.principal.id });
      const pluginCard = await findPluginCredentialCard({ loadCards: deps.loadPluginCredentialCards, workspaceId: deps.workspaceId, saveKind: 'publish-host', target: descriptor.id });
      const card = defineSecretCardTool<{
        descriptor: DeployTargetDescriptor; credential: DeployTargetCredentialSpec; prefill: Record<string, string>; updating: boolean; locale: string;
      }, Awaited<ReturnType<typeof saveProposeCredential>>, Awaited<ReturnType<typeof saveProposeCredential>> | {
        saved: false; cancelled: boolean; reason?: string; message?: string; note?: string;
      }>({
        toolId: CREDENTIAL_SAVE_TOOL_ID,
        prepare: async () => ({ descriptor, credential, prefill, updating, locale }),
        // New project keys need explicit attachment; an update changes the saved row where it lives.
        form: ({ prep }) => applyPluginCredentialCard({ card: pluginCard, form: buildProposeCredentialForm(prep) }),
        save: ({ values, prep, signal }) => saveProposeCredential({ deps, targetId: prep.descriptor.id, credential: prep.credential, values, signal, locale: prep.locale }),
        result: ({ prep, run }) => {
          if (run.status === 'saved') return run.saved;
          if (run.status === 'cancelled') return { saved: false, cancelled: true };
          if (run.status === 'blank' || run.status === 'failed') return { saved: false, cancelled: false, reason: 'invalid',
            message: run.status === 'blank' ? credentialText({ id: 'blank', locale: prep.locale }) : run.safeMessage };
          return { saved: false, cancelled: false, reason: run.status,
            note: run.status === 'expired' ? "The user did not respond to the credential form before it expired. Nothing was saved." : "The credential form was closed because the run ended. Nothing was saved." };
        },
        outcome: ({ prep, run }) => {
          if (run.status === 'cancelled' || run.status === 'expired' || run.status === 'abandoned') return undefined;
          const saved = run.status === 'saved';
          const message = saved ? run.saved.message : run.status === 'blank' ? credentialText({ id: 'blank', locale: prep.locale }) : run.status === 'failed' ? run.safeMessage : credentialText({ id: 'unreachable', locale: prep.locale });
          return { title: credentialText({ id: saved ? 'savedTitle' : 'unreachable', locale: prep.locale }), state: saved ? 'success' : 'failure', message };
        },
      }, {
        uriHost: 'tovu',
        text: { noEmitter: "deployment_propose_custom_provider_credential: this execution context has no interactive confirmation channel " +
          "(no emitSurface), so a credential form cannot be shown here. Nothing was saved.", saveFailure: credentialText({ id: 'unreachable', locale }) },
        safeError: err => err instanceof PublishCredentialDuplicateLabelError ? err.message : err instanceof PublishCredentialValidationError ? translateCredentialMessage({ message: err.message, locale }) : undefined,
        logFailure: metadata => console.warn(JSON.stringify(metadata)),
      });
      return card.handler({ surfaceExchanges: surfaces.surfaceExchanges, askThenReport })(ctx, optional);
  };
}

export function buildStaticPublishRegistrations(deps: StaticPublishToolDeps, surfaces: AssistantSurfaceDeps): ToolRegistration[] {
  const credentialSource =
    deps.credentialSource ??
    composePublishCredentialSource({
      workspaceId: deps.workspaceId,
      executionMode: deps.publishExecutionMode,
      dbDeps: { repo: deps.vendorCredentialSetRepo, sealer: deps.siteAssistantSecretSealer, loadDeployTargets: deployTargetsLoader(deps) },
    });
  const historyStore = deps.historyStore ?? deps.publishHistoryStore;

  const handlers: Record<string, ToolHandler> = {
    deployment_preview_static_publish: async (ctx) => {
      const raw = requireInputRecord({ input: ctx.input });
      const registry = await deployTargetsLoader(deps)(deps.workspaceId);
      const loaded = requireStaticPublishTarget(raw, registry);
      const target = loaded.descriptor.id;

      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "deployments.read" }, { entityType: "site-publish" });

      const { config, plan } = planToolPublish(registry, raw, loaded);
      const validationError = plan.ok ? null : plan.message;
      const basePath = plan.ok ? plan.basePath : undefined;
      // Local readiness stays non-decrypting. A provider inspection below is an explicit
      // authenticated read; its server-side credential never enters this tool result.
      const credential = await credentialSource.isConfigured({ workspaceId: deps.workspaceId, target, ...toolCredentialChoice({ raw }) });

      const inspected = plan.ok && credential.configured ? await inspectStaticPublish({
        deps: { credentialSource, loadDeployTargets: deps.loadDeployTargets, tracker: deps.tracker, observability: deps.observability, hostKit: deps.hostKit, formDestination: deps.formDestination },
        input: { workspaceId: deps.workspaceId, config, projectName: typeof raw.projectName === "string" ? raw.projectName : "",
          ...toolCredentialChoice({ raw }) },
      }) : {};
      return { ...buildStaticPublishPreviewResult(target, validationError, basePath, credential),
        ...(inspected.inspection ? { providerInspection: inspected.inspection } : {}) };
    },

    /**
     * Never decrypts — reads through `listPublishCredentials` (a pure DB read of
     * `vendor_credential_sets`; see its own "read model only" doc) and `credentialSource.isConfigured`
     * (this file's own preview handler already relies on the identical never-decrypting contract).
     * Structurally cannot reach `resolveForPublish`/`resolveDefaultForPublish`: this handler never
     * hands them a `SecretSealerPort`. `tokenTail` is the stored last 4 characters, never derived by
     * decrypting.
     */
    deployment_get_static_publish_capabilities: async (ctx) => {
      requireNoInput({ input: ctx.input });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "deployments.read" }, { entityType: "site-publish" });

      const loadDeployTargets = deployTargetsLoader(deps);
      // Owner policy: unseal only server-side to derive the safe hint.
      // Readiness still uses isConfigured(); no usable credential or provider probe reaches this result.
      const saved = await listPublishCredentials({ repo: deps.vendorCredentialSetRepo, sealer: deps.siteAssistantSecretSealer, loadDeployTargets } satisfies PublishCredentialReadDeps, {
        workspaceId: deps.workspaceId,
      });

      const registry = await loadDeployTargets(deps.workspaceId);
      const providerCapabilityContext: ProviderCapabilityContext = { deps, credentialSource, historyStore, saved };
      const inventory = deps.loadInstalledDeployTargets
        ? await deps.loadInstalledDeployTargets({ workspaceId: deps.workspaceId })
        : { items: registry.list().map(({ descriptor, pluginId }) => ({ descriptor, pluginId, enabled: true })), refusals: [] };
      const providers = await Promise.all(inventory.items.map(installed => buildInstalledProviderCapability({ installed, registry, context: providerCapabilityContext })));
      const refusals = [...new Set([...inventory.refusals, ...registry.refusals])];

      // Cross-site labels belong only to the local installation owner. Reuse the copy inventory;
      // discovery never opens a token, chooses a source or authorizes a copy.
      const missingSaved = new Set(providers.filter(provider => provider.savedCredentials?.length === 0).map(provider => provider.providerId));
      if (missingSaved.size && deps.localCredentialCopy?.localHost && ctx.principal.id === await deps.ownerPrincipalId) {
        try {
          const sources = summarizeCredentialSources({ sources: await deps.localCredentialCopy.list({}) });
          return { executionMode: deps.publishExecutionMode, providers, refusals,
            credentialSources: sources.map(source => ({ ...source,
              keys: source.keys.filter(key => key.publishHosts.some(host => missingSaved.has(host))) })) };
        } catch {
          return { executionMode: deps.publishExecutionMode, providers, refusals, credentialSourcesUnavailable: true };
        }
      }
      return { executionMode: deps.publishExecutionMode, providers, refusals };
    },

    /** Validates and publishes with server-side credentials after the shared registration policy
     * asks for human approval. The result still waits for the provider and
     * public reachability check; headless assistant calls without consent fail closed. */
    deployment_execute_static_publish: async (ctx, optional = {}) => {
      const raw = requireInputRecord({ input: ctx.input });
      const registry = await deployTargetsLoader(deps)(deps.workspaceId);
      const loaded = requireStaticPublishTarget(raw, registry);
      const target = loaded.descriptor.id;
      const projectName = requireString({ input: raw, key: "projectName" });

      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "deployments.publish" }, { entityType: "site-publish" });

      const { config, plan, detailRows } = planToolPublish(registry, raw, loaded);
      if (!plan.ok) {
        trackBlockedToolPublish({ deps, principalId: ctx.principal.id, target, reasonClass: "config" });
        throw new ToolInputError({ message: `deployment_execute_static_publish: ${plan.message}` });
      }
      const consent = await checkToolPublishConsent({ deps, principalId: ctx.principal.id });
      if (consent) {
        trackBlockedToolPublish({ deps, principalId: ctx.principal.id, target, reasonClass: "consent" });
        return { published: false, cancelled: false, ...consent };
      }

      if (config.customDomain && loaded.module.preview) {
        return domainPublishTool({ deps, surfaces, credentialSource, historyStore, config, projectName,
          ...toolCredentialChoice({ raw }) })(ctx, optional);
      }

      // Never decrypts (same `isConfigured()` contract the preview/capabilities handlers use above).
      // Refuse unavailable credentials before starting an export.
      const readiness = await credentialSource.isConfigured({ workspaceId: deps.workspaceId, target, ...toolCredentialChoice({ raw }) });
      if (!readiness.configured) {
        trackBlockedToolPublish({ deps, principalId: ctx.principal.id, target, reasonClass: "config" });
        return {
          published: false,
          cancelled: false,
          reason: "no-credential",
          credentialSetup: issueCredentialSetup({ setupToolId: "credential_save", prefill: { kind: "publish-host", target } }, {}),
          message: `No publish credential is configured for '${target}'. Call credential_save with kind publish-host to open its secure card, then retry once. The admin's Static Site tab is an alternative. (${readiness.reason})`,
        };
      }

      if (ctx.signal.aborted) return { published: false, cancelled: false, reason: "abandoned" };
      if (getPublishRunSnapshot().status === "running") {
        trackBlockedToolPublish({ deps, principalId: ctx.principal.id, target, reasonClass: "busy" });
        return { published: false, cancelled: false, code: "ALREADY_RUNNING", message: "A publish is already running. Wait for it to finish before publishing again." };
      }
      const outcome = await runPublishAndAwait(
        { credentialSource, loadDeployTargets: deployTargetsLoader(deps), buildTarget: deps.buildTarget, tracker: deps.tracker, observability: deps.observability, hostKit: deps.hostKit, formDestination: deps.formDestination },
        { productEvent: { userId: ctx.principal.id, source: "assistant" }, workspaceId: deps.workspaceId, publishOutputRootDir: deps.publishOutputRootDir, idGen: deps.idGen, exportSiteBound: deps.exportSiteBound, config, projectName,
          ...toolCredentialChoice({ raw }) },
        { nowIso: () => clockNowIso({ clock: deps.clock }) },
        historyStore,
      );
      const mapped = mapPublishOutcomeToToolResult(outcome, { id: ctx.executionId }, config, detailRows, projectName);
      if (optional.emitSurface) await optional.emitSurface(mapped.outcome);
      return mapped.result;
    },

    /**
     * The MCP-UI form-gated credential save for any host whose plugin declares a credential. Same
     * Opens an exchange, emits a form, then uses `askThenReport` to replace it with the real save
     * outcome: the model proposes structure for a human to fill in.
     *
     * The schema has no secret property, and a secret or undeclared field is refused before any form
     * is raised. The human's typed secret lands in `answer.params` server-side and is sealed by
     * `publish-credentials/store.ts`; it never enters a prompt or a completion, and the result never
     * echoes any field.
     */
    /**
     * Pure read — the host plugin module's own `hostingSetup` over the caller's non-secret credential
     * fields (never a saved credential). A host with no such steps is refused with the reason.
     */
    deployment_generate_bucket_hosting_setup: async (ctx) => {
      const raw = requireInputRecord({ input: ctx.input });
      const loaded = requireStaticPublishTarget(raw, await deployTargetsLoader(deps)(deps.workspaceId));
      const { descriptor, module } = loaded;
      if (module.hostingSetup === undefined) throw new ToolInputError({ message: `${descriptor.id} has no hosting-setup steps: publishing to it serves the site.` });
      const fields = readCredentialHints(raw, descriptor);

      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "deployments.read" }, { entityType: "site-publish" });

      try {
        return module.hostingSetup({ fields });
      } catch (err) {
        throw new ToolInputError({ message: err instanceof Error ? err.message : String(err) });
      }
    },
  };

  // No `unwiredToolIds`: this domain now wires its ENTIRE catalog, same tripwire discipline as
  // Posts/Pages/Forms/Entries/Widgets — a 4th catalog entry added without a handler fails the build.
  return buildDomainRegistrations({ metadata: toolMetadata,
    domain: "static-publish",
    catalogModule: "features/deployments/publish-agent-tools.ts",
    catalog: CATALOG_BY_ID,
    handlers,
    derivedRisk: staticPublishDerivedRisk,
  });
}

/**
 * Contributes Static Publish's AI tools; called once by the composition root's
 * `installFirstPartyToolContributors()`, never as an import side effect.
 * See ./tool-registrations.ts for the shared deployments/credential dependency boundary.
 */
export function contributeStaticPublishTools(): ToolContributor {
  return { domain: "static-publish", build: buildStaticPublishRegistrations, risk: staticPublishDerivedRisk };
}

import { CredentialInputError, CREDENTIAL_MESSAGES, assertCredentialFreeField, normalizeCredentialToken } from '../../../contracts/core/credential-token.js';
import type { Clock as ClockPort, UUID } from "@jini-ai/core/primitives";

import { isUniqueViolation } from "../../../platform/db/kernel/dialect.js";
import type { StorageKernel } from "@jini-ai/db/kernel";
import { parseTovuStoreMeta } from "#src/platform/secrets/vault-kinds";
import type { KeyringPort, SecretSealerPort } from "../../webhooks/index.js";
import { VaultError, matchingCredentialProviderIds, selectCredentialForProvider, normalizeCredentialWorksFor, type VaultSummary } from "@jini-ai/platform/secrets/credential-sets";
import { credentialVault, credentialScope, credentialHint } from "../../vendor-credentials/vault-adapter.js";
import type { VendorCredentialSetRecord, VendorCredentialSetRepoPort } from "../../vendor-credentials/types.js";
import { credentialDeletionRepo, credentialCreateTarget, credentialScopes, type ScopedCredentialDeps } from "../../vendor-credentials/project-scope.js";
import type { DeployTargetCredentialSpec, DeployTargetFieldSpec, DeployTargetRegistry } from "../deploy-targets/types.js";
import type { PublishConnectionInput, PublishCredentialScope, PublishCredentialSummary, PublishProviderId } from "./types.js";

/** Publish credentials map deploy hosts to vendor accounts. Feature validation and human-gated
 * verification remain here; Jini's vault owns sealing, defaults and persistence. Create/update
 * are shared with an agent-facing caller, so provider probes stay in the human-gated verify path.
 * Migration 0012 folds legacy rows once; there is no recurring backfill to resurrect deletions. */

const MAX_LABEL_LENGTH = 200;

/** Thrown for any caller-supplied value that fails shape validation — the route maps this to `400`. */
export class PublishCredentialValidationError extends Error {}

/** A `(workspaceId, vendor, label)` collision — the route maps this to `409 DUPLICATE_LABEL`. */
export class PublishCredentialDuplicateLabelError extends Error {}

/** Thrown when `sealer.seal()`/`keyring.activeKey()` fails while writing a connection — the realistic
 *  cause is a missing site key (`TOVU_SITE_KEY`), same fail-closed contract
 *  `SiteAssistantSecretStoreUnconfiguredError` documents for the sibling ADR-058 table. */
export class PublishCredentialSecretStoreUnconfiguredError extends Error {}

export class PublishCredentialNotFoundError extends Error {}

/** Deploy descriptors adapt into Jini's compatibility and selection policy. Required companion
 * fields exclude token-only custom keys before any default is selected. No I/O; O(hosts).
 */
export function publishHostsForCredential({ credential, registry }: {
  credential: Pick<VaultSummary, "kind" | "provider" | "label" | "meta">; registry: DeployTargetRegistry;
}, _options = {}): string[] {
  return matchingCredentialProviderIds({ credential, providers: registry.list().flatMap(({ descriptor }) => {
    if (!moduleAcceptsCredential({ credential, registry, targetId: descriptor.id })) return [];
    const spec = descriptor.credential;
    return spec ? [{ id: descriptor.id, vendorId: spec.vendorId,
      acceptsCustomToken: !spec.fields.some(field => field.required && field.name !== spec.tokenField) }] : [];
  }) });
}

/** Only narrow eligibility here; the existing Jini matcher still owns worksFor/default selection.
 * No persisted metadata changes, so an old vendor grant cannot silently acquire a new capability. */
function moduleAcceptsCredential({ credential, registry, targetId }: {
  credential: Pick<VaultSummary, "meta">; registry: DeployTargetRegistry; targetId: string;
}, _options = {}): boolean {
  const accepts = registry.get(targetId)?.module.acceptsCredential;
  if (!accepts) return true;
  const worksFor = credential.meta.worksFor;
  if (!Array.isArray(worksFor) || !worksFor.every(id => typeof id === "string")) return false;
  return accepts({ worksFor });
}

/** An explicit id is found in either store. Otherwise the first store (in `inventory` order: this
 * site's, then the project's) holding any compatible row decides alone (owner 2026-10-25: a site row
 * overrides), so an ambiguous site stays ambiguous instead of silently using a project key.
 * @complexity O(rows × compatibility IDs).
 */
function selectPublishCredential({ registry, credentials, provider, id }: {
  registry: DeployTargetRegistry; credentials: readonly VaultSummary[];
  provider: NonNullable<ReturnType<typeof providerContract>>; id?: string;
}, _options = {}): VaultSummary | null {
  const eligible = credentials.filter(credential => moduleAcceptsCredential({ credential, registry, targetId: provider.id }));
  if (id !== undefined) return selectCredentialForProvider({ credentials: eligible, provider, id });
  const decides = eligible.find(row => selectCredentialForProvider({ credentials: [row], provider, id: row.id }));
  return selectCredentialForProvider({ credentials: eligible.filter(row => row.workspaceId === decides?.workspaceId), provider });
}
/** Compatibility edits invalidate only hosts whose eligibility changed, through the existing cache
 * port. Catalog adaptation and custom token shape rules are shared with runtime matching.
 * @complexity O(hosts × compatibility IDs); no credential reads, opens or provider requests.
 */
export function invalidatePublishCredentialCompatibility({ workspaceId, registry, cache, before, after }: {
  workspaceId: string; registry: DeployTargetRegistry;
  cache: { delete(input: { workspaceId: string; target: string }): void };
  before?: { credentialType: "vendor" | "custom"; worksFor: string[] };
  after?: { credentialType: "vendor" | "custom"; worksFor: string[] };
}, _options = {}): void {
  const hosts = (value: typeof before) => value ? publishHostsForCredential({ registry,
    credential: { kind: "vendor", provider: null, label: "", meta: { credentialType: value.credentialType, worksFor: value.worksFor } } }) : [];
  const previous = new Set(hosts(before));
  const next = new Set(hosts(after));
  for (const target of new Set([...previous, ...next])) if (previous.has(target) !== next.has(target)) cache.delete({ workspaceId, target });
}

function providerContract({ registry, providerId }: { registry: DeployTargetRegistry; providerId: string }, _options = {}) {
  const spec = registry.get(providerId)?.descriptor.credential;
  return spec ? { id: providerId, vendorId: spec.vendorId,
    acceptsCustomToken: !spec.fields.some(field => field.required && field.name !== spec.tokenField) } : null;
}
function vaultSummary({ summary, providerId, publishHosts = [], defaultFor = [] }: {
  summary: VaultSummary; providerId: PublishProviderId; publishHosts?: string[]; defaultFor?: string[];
}, _options = {}): PublishCredentialSummary {
  const tokenHint = credentialHint({ record: summary });
  return { id: summary.id, providerId, vendorId: summary.provider ?? providerId, label: summary.label, configured: true,
    credentialType: summary.meta.credentialType as "vendor" | "custom", worksFor: [...summary.meta.worksFor as string[]],
    publishHosts, defaultFor, isDefault: defaultFor.includes(providerId), tokenTail: tokenHint?.last4 ?? "", tokenHint,
    accountLabel: typeof summary.meta.accountLabel === "string" ? summary.meta.accountLabel : null,
    createdAt: summary.createdAt, updatedAt: summary.updatedAt };
}
function vault(deps: PublishCredentialReadDeps & Partial<PublishCredentialWriteDeps>, _options = {}) {
  return credentialVault({ ...deps, sealer: deps.sealer!, storageError: () => new PublishCredentialSecretStoreUnconfiguredError(CREDENTIAL_MESSAGES.storage) });
}
export interface PublishCredentialReadDeps {
  repo: VendorCredentialSetRepoPort;
  sealer?: SecretSealerPort;
  loadDeployTargets(workspaceId: string): Promise<DeployTargetRegistry>;
}

/** The store a listed row came from: rows carry their own store's workspace id. */
function scopeOfRow<D extends PublishCredentialReadDeps>(deps: D, input: { workspaceId: string; row: { workspaceId: string } }): ScopedCredentialDeps<D> {
  const scopes = credentialScopes(deps, input.workspaceId);
  return scopes.find(scoped => scoped.workspaceId === input.row.workspaceId) ?? scopes[0]!;
}

/** The vendor row with this id, from the first store holding it (ids are unique across both). @complexity O(scopes). */
async function locateById<D extends PublishCredentialReadDeps>(deps: D, input: { workspaceId: string; id: string }): Promise<{ scoped: ScopedCredentialDeps<D>; existing: VendorCredentialSetRecord } | null> {
  for (const scoped of credentialScopes(deps, input.workspaceId)) {
    const existing = await scoped.deps.repo.findById({ workspaceId: scoped.workspaceId, id: input.id });
    if (existing) return { scoped, existing };
  }
  return null;
}

/** A site row overrides the project row it would collide with: custom keys share one label space,
 *  vendor keys one per vendor (the vault's own unique-label scopes). */
const labelKey = (row: VaultSummary): string => row.meta.credentialType === "custom" ? `custom\0${row.label}` : `vendor\0${row.provider}\0${row.label}`;

/** Every row this site can publish with: its own, then the project's whose label no site row claims.
 * @complexity O(rows); one inventory per store, no row is opened.
 */
async function inventory({ deps, workspaceId }: { deps: PublishCredentialReadDeps; workspaceId: string }, _options = {}): Promise<VaultSummary[]> {
  const rows: VaultSummary[] = [];
  const claimed = new Set<string>();
  for (const scoped of credentialScopes(deps, workspaceId)) {
    const own = await storeInventory({ deps: scoped.deps, workspaceId: scoped.workspaceId });
    rows.push(...own.filter(row => !claimed.has(labelKey(row))));
    for (const row of own) claimed.add(labelKey(row));
  }
  return rows;
}

/** One authorized, metadata-only inventory of one store for both subtypes. No secret is opened, and an
 * injected port cannot widen the workspace/owner/binding. Jini parses every canonical row before matching.
 * @complexity O(rows + metadata); two scoped reads during rollout, no per-row queries.
 */
async function storeInventory({ deps, workspaceId }: { deps: PublishCredentialReadDeps; workspaceId: string }, _options = {}): Promise<VaultSummary[]> {
  const service = vault(deps);
  const unified = await service.list(credentialScope({ workspaceId, kind: "vendor" }));
  const legacy = await service.list(credentialScope({ workspaceId, kind: "custom" }));
  return [...unified, ...legacy]
    .filter(row => row.workspaceId === workspaceId && (row.kind === "vendor" || row.kind === "custom") && row.ownerKey === "tovu" &&
      row.principalId === null && row.binding === null && row.configured);
}

/** Safe publish inventory; empty compatibility stays editable on vendor cards. Display host
 * fallback is used only for editing, never for runtime eligibility. Defaults are selected per host.
 * @complexity O(rows × hosts), one metadata inventory and one catalog load.
 */
export async function listPublishCredentials(deps: PublishCredentialReadDeps, input: { workspaceId: UUID }): Promise<PublishCredentialSummary[]> {
  const registry = await deps.loadDeployTargets(input.workspaceId);
  const rows = await inventory({ deps, workspaceId: input.workspaceId });
  const defaults = new Map<string, string>();
  for (const { descriptor } of registry.list()) {
    const provider = providerContract({ registry, providerId: descriptor.id });
    const selected = provider && selectPublishCredential({ registry, credentials: rows, provider });
    if (selected) defaults.set(descriptor.id, selected.id);
  }
  return rows.flatMap(row => {
    const publishHosts = publishHostsForCredential({ credential: row, registry });
    const providerId = publishHosts[0] ?? (row.meta.credentialType === "vendor"
      ? registry.list().find(target => target.descriptor.credential?.vendorId === row.provider)?.descriptor.id : undefined);
    if (providerId === undefined) return [];
    const defaultFor = [...defaults].filter(([, id]) => id === row.id).map(([host]) => host);
    const summary = vaultSummary({ summary: row, providerId, publishHosts, defaultFor });
    return [{ ...summary, vendorId: row.provider ?? registry.get(providerId)!.descriptor.credential!.vendorId, ...reportedScope({ deps, workspaceId: input.workspaceId, row }) }];
  });
}

/** The summary's `scope`, only where a project store is attached (a site-only server's output is unchanged). */
function reportedScope({ deps, workspaceId, row }: { deps: PublishCredentialReadDeps; workspaceId: string; row: VaultSummary }, _options = {}): { scope?: PublishCredentialScope } {
  return deps.repo.project ? { scope: scopeOfRow(deps, { workspaceId, row }).scope } : {};
}

/** Metadata-only ID projection; custom keys keep their existing custom edit/permission boundary. */
export async function describeCredential(deps: PublishCredentialReadDeps, input: { workspaceId: UUID; id: UUID }): Promise<PublishCredentialSummary | null> {
  return (await listPublishCredentials(deps, input)).find(row => row.id === input.id) ?? null;
}

/** Configuration requires a compatible selected candidate, not merely a provider-group default.
 * An explicit id must select that authorized row; no secret is opened.
 * @complexity O(rows × compatibility IDs), one metadata inventory per store and one catalog load. */
export async function hasDefaultForPublish(deps: PublishCredentialReadDeps, input: { workspaceId: UUID; providerId: PublishProviderId; id?: UUID }): Promise<boolean> {
  const registry = await deps.loadDeployTargets(input.workspaceId);
  const provider = providerContract({ registry, providerId: input.providerId });
  return provider !== null && selectPublishCredential({ registry, credentials: await inventory({ deps, workspaceId: input.workspaceId }), provider, id: input.id }) !== null;
}

function validatedWorksFor({ value }: { value: unknown }, _options = {}): string[] {
  try { const ids = normalizeCredentialWorksFor({ value }); for (const id of ids) assertPlainField({ value: id, field: "worksFor" }); return ids; }
  catch (error) { if (error instanceof VaultError) throw new PublishCredentialValidationError("worksFor must be an array of provider IDs"); throw error; }
}

/** A provider move retargets the old host/vendor compatibility, preserving unrelated IDs.
 * Explicit compatibility edits win, including an empty list. No I/O; O(compatibility IDs).
 */
function updatedWorksFor({ value, row, provider, host }: {
  value: unknown; row: Pick<VaultSummary, "provider" | "meta">; provider: string; host: string;
}, _options = {}): string[] {
  if (value !== undefined) return validatedWorksFor({ value });
  const previous = parseTovuStoreMeta({ kind: "vendor", meta: row.meta, provider: row.provider }).worksFor as string[];
  if (provider === row.provider) return previous;
  return validatedWorksFor({ value: previous.map(id => id === row.provider?.toLowerCase() || id === host.toLowerCase() ? provider : id) });
}

export interface PublishCredentialWriteDeps extends PublishCredentialReadDeps {
  sealer: SecretSealerPort;
  keyring: KeyringPort;
  clock: ClockPort;
  idGen: { newId(): string };
}

/** Narrows and validates a caller-supplied `label`. Never throws a raw `TypeError` — every rejection
 *  is a {@link PublishCredentialValidationError} the route/tool layer can map to its own `400`. */
function validateLabel(raw: unknown): string {
  if (typeof raw !== "string" || raw.trim() === "") {
    throw new PublishCredentialValidationError("label must be a non-empty string");
  }
  if (raw.length > MAX_LABEL_LENGTH) {
    throw new PublishCredentialValidationError(`label must be ${MAX_LABEL_LENGTH} characters or fewer`);
  }
  assertPlainField({ value: raw, field: "label" });
  return raw;
}

/** Shared check-then-trim step for {@link requireNonEmptyString}/{@link optionalString} — the two
 *  differ only in whether `undefined` is acceptable, never in what counts as "non-empty" or what gets
 *  persisted. Always returns the TRIMMED value, never the raw one just validated: a leading or trailing
 *  space pasted alongside a real value (an endpoint URL, an access key, a bearer token) is never
 *  meaningful, and returning it unmodified lets it survive into storage, then into every reader
 *  downstream — for a secret field, that surfaces later as a misleading "wrong credentials" far from
 *  where the stray space was typed. Extracted (2026-09-05) after `optionalString` was fixed alone once
 *  already and `requireNonEmptyString` was found carrying the identical untrimmed-return bug days
 *  later — a single shared step is what keeps the two from drifting apart a second time. */
function assertNonEmptyTrimmed(raw: unknown, message: string): string {
  if (typeof raw !== "string" || raw.trim() === "") {
    throw new PublishCredentialValidationError(message);
  }
  return raw.trim();
}

function requireNonEmptyString(raw: unknown, field: string, providerId: string): string {
  return assertNonEmptyTrimmed(raw, `'${field}' (non-empty string) is required for provider '${providerId}'`);
}

function optionalString(raw: unknown, field: string): string | undefined {
  if (raw === undefined) return undefined;
  // A blank optional form field (e.g. an optional zone id left empty) means "not provided", not an
  // invalid value: secure forms send every field, so rejecting "" blocked saving a valid credential.
  if (typeof raw === "string" && raw.trim() === "") return undefined;
  return assertNonEmptyTrimmed(raw, `'${field}' must be a non-empty string when provided`);
}

/** Narrows a caller-supplied `isDefault`. `undefined` means "no default change requested" (the same
 *  omitted-means-unchanged convention `label`/`connection` already use); any other non-boolean value
 *  is rejected rather than coerced, so a stray string/number in the request body cannot silently be
 *  read as truthy. */
function optionalBoolean(raw: unknown, field: string): boolean | undefined {
  if (raw === undefined) return undefined;
  if (typeof raw !== "boolean") {
    throw new PublishCredentialValidationError(`'${field}' must be a boolean when provided`);
  }
  return raw;
}

/** A validated connection plus the host credential spec it was validated against. */
interface ValidatedConnection {
  readonly connection: PublishConnectionInput;
  readonly spec: DeployTargetCredentialSpec;
}

/**
 * Validates a caller-supplied `connection` against the credential its host declares
 * (`DeployTargetDescriptor.credential` in this workspace's deploy registry): `providerId` must be a
 * target that takes a saved credential; every declared required field must be a non-empty string,
 * every declared optional one a non-empty string when present. Required fields are checked before
 * optional ones, in declaration order. Values are trimmed; undeclared keys are dropped. Never throws a
 * raw shape error — every rejection is a {@link PublishCredentialValidationError}.
 *
 * @complexity O(t + f): one pass over the registry's targets (for the error text), one over the fields.
 */
function normalizeSecret(required: { value: unknown; field: string }): string {
  try { return normalizeCredentialToken(required); }
  catch (err) { if (err instanceof CredentialInputError) throw new PublishCredentialValidationError(err.message); throw err; }
}
function assertPlainField(required: { value: string; field: string }): void {
  try { assertCredentialFreeField(required); }
  catch (err) { if (err instanceof CredentialInputError) throw new PublishCredentialValidationError(err.message); throw err; }
}

function validateConnection(raw: unknown, registry: DeployTargetRegistry): ValidatedConnection {
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
    throw new PublishCredentialValidationError("connection must be an object");
  }
  const value = raw as Record<string, unknown>;
  const { providerId, spec } = connectionCredentialSpec({ value, registry });

  const fields: Record<string, string> = {};
  const ordered = [...spec.fields.filter(field => field.required), ...spec.fields.filter(field => !field.required)];
  for (const field of ordered) {
    const normalized = validatedConnectionField({ value: value[field.name], field, spec, providerId });
    if (normalized !== undefined) fields[field.name] = normalized;
  }
  if (fields[spec.tokenField] === undefined) normalizeSecret({ value: undefined, field: spec.tokenField });
  return { connection: { providerId, ...fields }, spec };
}

function connectionCredentialSpec({ value, registry }: {
  value: Record<string, unknown>; registry: DeployTargetRegistry;
}, _options = {}): { providerId: string; spec: DeployTargetCredentialSpec } {
  const providerId = value.providerId;
  const spec = typeof providerId === "string" ? registry.get(providerId)?.descriptor.credential : undefined;
  if (typeof providerId !== "string" || spec === undefined) {
    const known = registry.list().flatMap((target) => (target.descriptor.credential !== undefined ? [target.descriptor.id] : []));
    throw new PublishCredentialValidationError(`connection.providerId must be one of: ${known.join(", ")}`);
  }

  return { providerId, spec };
}

function isSecretField({ field, spec }: {
  field: DeployTargetFieldSpec; spec: DeployTargetCredentialSpec;
}, _options = {}): boolean {
  return Boolean(field.secret || field.name === spec.tokenField);
}

function validatedConnectionField({ value, field, spec, providerId }: {
  value: unknown; field: DeployTargetFieldSpec; spec: DeployTargetCredentialSpec; providerId: string;
}, _options = {}): string | undefined {
  const secret = isSecretField({ field, spec });
  if (secret && (field.required || value !== undefined)) return normalizeSecret({ value, field: field.name });
  const normalized = field.required ? requireNonEmptyString(value, field.name, providerId) : optionalString(value, field.name);
  if (!secret && normalized !== undefined) assertPlainField({ value: normalized, field: field.name });
  return normalized;
}

export interface CreatePublishCredentialInput {
  workspaceId: UUID;
  label: unknown;
  connection: unknown;
  /** `true` makes this the vendor's default connection (clearing any previous one — see
   *  `VendorCredentialSetRepoPort`'s own header). Omitted auto-defaults the vendor's FIRST saved
   *  connection; explicit `false` opts out. Jini owns atomic auto-defaulting. */
  isDefault?: unknown;
  worksFor?: unknown;
  /** `"site"` = a site-owned key. Omitted (or `"project"`) = the project store when one is
   *  attached, visible to attached sites only; this site's vault otherwise. */
  scope?: unknown;
}

/**
 * A project row whose vendor and label this site already uses would be hidden here by the site row
 * (site rows override), so the save would look lost: refused as the same duplicate as within one store.
 */
async function assertLabelFreeOnSite({ deps, target, workspaceId, vendorId, label, providerId }: { deps: PublishCredentialReadDeps;
  target: ScopedCredentialDeps<unknown>; workspaceId: string; vendorId: string; label: string; providerId: string }, _options = {}): Promise<void> {
  if (target.scope !== "project") return;
  if ((await deps.repo.listByVendor({ workspaceId, vendorId })).some(row => row.label === label)) {
    throw new PublishCredentialDuplicateLabelError(`a '${providerId}' credential labeled '${label}' already exists in this workspace`);
  }
}

/** Label conflicts keep the feature's error contract; stale CAS failures stay conflicts.
 * @complexity One vault write; on conflict, O(vendor rows) metadata lookup without opening secrets. */
async function saveConnection({ deps, target, input, providerId }: { deps: PublishCredentialWriteDeps; target: ScopedCredentialDeps<PublishCredentialWriteDeps>;
  input: Parameters<ReturnType<typeof vault>["put"]>[0]; providerId: PublishProviderId }, _options = {}): Promise<VaultSummary> {
  try { return await vault(target.deps).put(input); }
  catch (error) {
    // Unattached project rows are hidden from normal reads. Use only deletion metadata to
    // distinguish a duplicate label from a CAS conflict; never attach or open the existing key.
    const labelRepo = target.scope === "project" ? credentialDeletionRepo({ repo: deps.repo }).project!.repo : target.deps.repo;
    // The storage kernel recognizes UNIQUE (workspace_id, vendor_id, label) via SQLite's
    // code/message or Postgres SQLSTATE 23505.
    const duplicate = isUniqueViolation(error) || error instanceof VaultError && error.code === "conflict" &&
      (await labelRepo.listByVendor({ workspaceId: input.workspaceId, vendorId: input.provider! })).some(row => row.id !== input.id && row.label === input.label);
    if (duplicate) throw new PublishCredentialDuplicateLabelError(input.workspaceId === 'project' ? `Your project already has a key named '${input.label}'. Use it here, or pick another name.` : `a '${providerId}' credential labeled '${input.label}' already exists in this workspace`);
    throw error;
  }
}

/** Validate before the vault write. Jini atomically auto-defaults the first vendor credential. */
export async function createPublishCredential(deps: PublishCredentialWriteDeps, input: CreatePublishCredentialInput): Promise<PublishCredentialSummary> {
  const label = validateLabel(input.label);
  const registry = await deps.loadDeployTargets(input.workspaceId);
  const validated = validateConnection(input.connection, registry);
  const isDefault = optionalBoolean(input.isDefault, "isDefault");
  const { providerId, ...fields } = validated.connection;
  // Project-first (`vendor-credentials/project-scope.ts`); "site" = only for this site.
  const target = credentialCreateTarget(deps, input, message => new PublishCredentialValidationError(message));
  await assertLabelFreeOnSite({ deps, target, workspaceId: input.workspaceId, vendorId: validated.spec.vendorId, label, providerId });
  const summary = await saveConnection({ deps, target, providerId, input: {
    ...credentialScope({ workspaceId: target.workspaceId, kind: "vendor" }), id: deps.idGen.newId(), expectedRevision: null,
    provider: validated.spec.vendorId, label, meta: { credentialType: "vendor", worksFor: validatedWorksFor({ value: input.worksFor === undefined ? registry.get(providerId)?.module.defaultCredentialWorksFor ?? [validated.spec.vendorId] : input.worksFor }), accountLabel: null }, payload: { vendorId: validated.spec.vendorId, ...fields },
    hintToken: fields[validated.spec.tokenField], ...(isDefault === undefined ? {} : { isDefault }),
  } });
  // The project read view deliberately hides this new row until it is attached; use put's result.
  const publishHosts = publishHostsForCredential({ credential: summary, registry });
  return { ...vaultSummary({ summary, providerId, publishHosts, defaultFor: summary.isDefault ? publishHosts : [] }), ...reportedScope({ deps, workspaceId: input.workspaceId, row: summary }) };
}

export interface UpdatePublishCredentialInput {
  workspaceId: UUID;
  id: UUID;
  /** Omitted = leave the label unchanged. */
  label?: unknown;
  /** Omitted = leave the stored connection (and its vendor) untouched — this route's own
   *  "connection omitted => keep the stored secret untouched" contract. Supplying a NEW connection
   *  may change the host and vendor. A provider-only move between token-only hosts retains the
   *  envelope: vault AAD binds the stable identity, not the vendor. Explicit secrets rotate.
   *  On same-vendor updates, null removes an optional secret; blank keeps it. */
  connection?: unknown;
  /** `true` makes this the default connection for its (possibly new — see `connection` above)
   *  vendor, clearing any previous default in the same repo call. Omitted/`false` preserves a
   *  same-vendor default; moves use the destination's default/first-row rule. Use
   *  `createPublishCredential`/another `updatePublishCredential` call with `isDefault: true` to
   *  promote a different row instead. */
  isDefault?: unknown;
  worksFor?: unknown;
}

/** Preserve only a provider change between compatible token-only contracts. Companion-field
 * changes and different secret schemas still require the validated replacement path.
 * @complexity O(k) time/space for k supplied keys; fixed schema checks, no I/O. */
function preservedMove({ raw, registry, host }: { raw: unknown; registry: DeployTargetRegistry; host: PublishProviderId }, _options = {}): { providerId: string; spec: DeployTargetCredentialSpec } | undefined {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return undefined;
  const values = raw as Record<string, unknown>;
  if (typeof values.providerId !== "string" || values.providerId === host) return undefined;
  const spec = tokenOnlyMoveSpec({ registry, host, providerId: values.providerId });
  if (!spec || !isProviderOnlyMove({ values, spec })) return undefined;
  return { providerId: values.providerId, spec };
}

function tokenOnlyMoveSpec({ registry, host, providerId }: {
  registry: DeployTargetRegistry; host: PublishProviderId; providerId: string;
}, _options = {}): DeployTargetCredentialSpec | undefined {
  const spec = registry.get(providerId)?.descriptor.credential;
  const previous = registry.get(host)?.descriptor.credential;
  if (!spec || !previous || spec.tokenField !== previous.tokenField) return undefined;
  // Token-only = the token is the only REQUIRED field; an optional extra (a host's add-on secret) may
  // be absent, so the retained envelope is still a valid connection for the destination.
  if (![spec, previous].every(candidate => candidate.fields.every(field => field.name === candidate.tokenField || !field.required))) return undefined;
  return spec;
}

function isProviderOnlyMove({ values, spec }: {
  values: Record<string, unknown>; spec: DeployTargetCredentialSpec;
}, _options = {}): boolean {
  return Object.keys(values).every(key => key === "providerId" || key === spec.tokenField) &&
    (values[spec.tokenField] === undefined || values[spec.tokenField] === "");
}

/** Blank secret fields keep their stored value; null explicitly removes an optional secret.
 * Required secrets remain required, and non-secret companion fields still update.
 * @complexity O(fields + sealed payload bytes), at most one existing connection open.
 */
async function updatedConnection({ deps, input, existing, registry, host }: { deps: PublishCredentialWriteDeps; input: UpdatePublishCredentialInput;
  existing: VendorCredentialSetRecord; registry: DeployTargetRegistry; host: PublishProviderId }, _options = {}): Promise<ValidatedConnection> {
  const raw = input.connection;
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return validateConnection(raw, registry);
  const values = raw as Record<string, unknown>;
  const { spec } = connectionCredentialSpec({ value: values, registry });
  if (spec.vendorId !== existing.vendorId) return validateConnection(raw, registry);
  const blankSecrets = spec.fields.filter(field => isSecretField({ field, spec }) && (values[field.name] === "" || values[field.name] === undefined));
  const clearedSecrets = spec.fields.filter(field => isSecretField({ field, spec }) && !field.required && field.name !== spec.tokenField && values[field.name] === null);
  if (blankSecrets.length === 0 && clearedSecrets.length === 0) return validateConnection(raw, registry);
  const stored = await decryptRecord(deps, existing, host);
  const merged = { ...stored, ...values };
  for (const field of blankSecrets) merged[field.name] = stored[field.name];
  for (const field of clearedSecrets) delete merged[field.name];
  return validateConnection(merged, registry);
}

/** Omitted connections retain their sealed envelope/hints and never require a site key.
 * Provider moves retarget the old compatibility IDs unless the caller supplies worksFor.
 * Reject labels that would hide a project row behind a site's row before writing.
 */
export async function updatePublishCredential(deps: PublishCredentialWriteDeps, input: UpdatePublishCredentialInput): Promise<PublishCredentialSummary> {
  // Changed where it lives: this site's own row, else the project's (shared by every site).
  const located = await locateById(deps, input);
  const registry = await deps.loadDeployTargets(input.workspaceId);
  const host = located ? registry.list().find(target => target.descriptor.credential?.vendorId === located.existing.vendorId)?.descriptor.id : undefined;
  if (!located || host === undefined) throw new PublishCredentialNotFoundError(`no publish credential '${input.id}' in this workspace`);
  const { scoped, existing } = located;
  const label = input.label !== undefined ? validateLabel(input.label) : existing.label;
  const requestedDefault = optionalBoolean(input.isDefault, "isDefault");
  const row = await scoped.deps.repo.vault!.find({ workspaceId: scoped.workspaceId, id: input.id });
  if (!row) throw new PublishCredentialNotFoundError(`no publish credential '${input.id}' in this workspace`);
  const { providerId, accountLabel, ...changes } = await connectionChanges({ deps: scoped.deps, input, existing, registry, host, row });
  await assertLabelFreeOnSite({ deps, target: scoped, workspaceId: input.workspaceId, vendorId: changes.provider, label, providerId });
  const summary = await saveConnection({ deps, target: scoped, providerId, input: { ...credentialScope({ workspaceId: scoped.workspaceId, kind: "vendor" }), id: input.id,
    expectedRevision: row.revision, label, ...changes,
    meta: { ...row.meta, worksFor: updatedWorksFor({ value: input.worksFor, row, provider: changes.provider, host }), accountLabel },
    ...(requestedDefault === true ? { isDefault: true } : {}) } });
  return (await describeCredential(deps, { workspaceId: input.workspaceId, id: summary.id }))!;
}

async function connectionChanges({ deps, input, existing, registry, host, row }: {
  deps: PublishCredentialWriteDeps; input: UpdatePublishCredentialInput; existing: VendorCredentialSetRecord;
  registry: DeployTargetRegistry; host: PublishProviderId; row: Pick<VaultSummary, "meta">;
}, _options = {}) {
  const move = preservedMove({ raw: input.connection, registry, host });
  if (input.connection !== undefined && !move) {
    const validated = await updatedConnection({ deps, input, existing, registry, host });
    const { providerId, ...fields } = validated.connection;
    return { providerId, provider: validated.spec.vendorId, accountLabel: null,
      payload: { vendorId: validated.spec.vendorId, ...fields }, hintToken: fields[validated.spec.tokenField] };
  }
  // Payload omission preserves ciphertext/hints; the vault atomically promotes/selects defaults.
  const providerId = move?.providerId ?? host;
  const provider = move?.spec.vendorId ?? existing.vendorId;
  return { providerId, provider, accountLabel: provider === existing.vendorId ? row.meta.accountLabel : null };
}

/** The store holding vendor row `id`: this site's, else the project's when one is attached (ids are
 *  unique across both). Never opens a row. @complexity At most one lookup. */
async function ownerOf<R extends Pick<VendorCredentialSetRepoPort, "findById" | "project">>(repo: R, input: { workspaceId: string; id: string }): Promise<{ repo: R | VendorCredentialSetRepoPort; workspaceId: string }> {
  const project = repo.project;
  if (!project || await repo.findById(input)) return { repo, workspaceId: input.workspaceId };
  return { repo: project.repo, workspaceId: project.workspaceId };
}

/** The vendor row with this id from whichever store holds it — this site's or the project's. */
export async function findPublishCredentialRecord(deps: { repo: Pick<VendorCredentialSetRepoPort, "findById" | "project"> },
  input: { workspaceId: UUID; id: UUID }): Promise<VendorCredentialSetRecord | null> {
  const owner = await ownerOf(deps.repo, input);
  return owner.repo.findById({ workspaceId: owner.workspaceId, id: input.id });
}

/** Legacy rows were folded by 0012. Delete only the vault row; reboot has no source to recopy.
 *  A project row is removed only when no other site uses it; its attachments are removed with it. */
export async function deletePublishCredential(deps: {
  repo: Pick<VendorCredentialSetRepoPort, "delete" | "findById" | "project">;
  transaction?: Pick<StorageKernel<unknown>, "transaction">;
}, input: { workspaceId: UUID; id: UUID }): Promise<void> {
  const owner = await ownerOf(credentialDeletionRepo({ repo: deps.repo }), input);
  await owner.repo.delete({ workspaceId: owner.workspaceId, id: input.id });
}

/** Jini checks exact ownership before opening. Keep the typed error used by HTTP and daemon
 * boundaries: a missing key must not become an unhandled rejection in a publishing process. */
async function decryptRecord(deps: PublishCredentialResolveDeps, record: VendorCredentialSetRecord, providerId: PublishProviderId): Promise<PublishConnectionInput> {
  try {
    const resolved = await vault(deps).get({ ...credentialScope({ workspaceId: record.workspaceId, kind: "vendor" }), id: record.id });
    if (!resolved?.payload) throw new PublishCredentialSecretStoreUnconfiguredError(CREDENTIAL_MESSAGES.storage);
    const { vendorId: _vendorId, ...fields } = resolved.payload as Record<string, string>;
    return { ...fields, providerId };
  } catch { throw new PublishCredentialSecretStoreUnconfiguredError(CREDENTIAL_MESSAGES.storage); }
}

export interface PublishCredentialResolveDeps extends PublishCredentialReadDeps {
  sealer: SecretSealerPort;
}

/** Resolve exactly one compatible row. Recheck metadata from the same read as its payload so
 * concurrent compatibility edits cannot pair an ineligible secret with an old selection.
 * @throws PublishCredentialSecretStoreUnconfiguredError on crypto or payload failure.
 * @complexity O(rows × hosts + payload), one metadata inventory and one selected open.
 */
export async function resolveForPublish(deps: PublishCredentialResolveDeps,
  input: { workspaceId: UUID; id: UUID; providerId?: PublishProviderId },
): Promise<{ providerId: PublishProviderId; vendorId: string; label: string; isDefault: boolean; connection: PublishConnectionInput } | null> {
  const registry = await deps.loadDeployTargets(input.workspaceId);
  const rows = await inventory({ deps, workspaceId: input.workspaceId });
  return resolveFromInventory({ deps, input, registry, rows });
}

/** Open the selected credential through Jini using one already-authorized inventory.
 * Both resolution entrypoints share compatibility rechecks and connection projection.
 * @throws PublishCredentialSecretStoreUnconfiguredError on crypto or payload failure.
 * @complexity O(rows × compatibility IDs + payload); one selected row read/open, no list reads.
 */
async function resolveFromInventory({ deps, input, registry, rows }: {
  deps: PublishCredentialResolveDeps; input: { workspaceId: UUID; id: UUID; providerId?: PublishProviderId };
  registry: DeployTargetRegistry; rows: VaultSummary[];
}, _options = {}): ReturnType<typeof resolveForPublish> {
  const candidate = rows.find(row => row.id === input.id);
  const providerId = selectedCandidateProviderId({ explicitId: input.providerId, candidate, registry });
  if (!candidate || !providerId) return null;
  const provider = providerContract({ registry, providerId });
  if (!provider || !selectPublishCredential({ registry, credentials: rows, provider, id: input.id })) return null;
  const resolved = await openPublishVaultRecord({ deps, input, candidate });
  if (!resolved || !selectPublishCredential({ registry, credentials: [resolved.summary], provider, id: input.id })) return null;
  const connection = publishConnectionFromPayload({ providerId, spec: registry.get(providerId)!.descriptor.credential!,
    summary: resolved.summary, payload: resolved.payload });
  return { providerId, vendorId: provider.vendorId, label: resolved.summary.label,
    isDefault: selectPublishCredential({ registry, credentials: rows, provider })?.id === input.id, connection };
}

function selectedCandidateProviderId({ explicitId, candidate, registry }: {
  explicitId: string | undefined; candidate: VaultSummary | undefined; registry: DeployTargetRegistry;
}, _options = {}): string | undefined {
  if (explicitId !== undefined) return explicitId;
  if (!candidate) return undefined;
  return publishHostsForCredential({ credential: candidate, registry })[0];
}

/** Crypto faults retain the established typed refusal and never echo payloads. */
async function openPublishVaultRecord({ deps, input, candidate }: {
  deps: PublishCredentialResolveDeps; input: { workspaceId: UUID; id: UUID }; candidate: VaultSummary;
}, _options = {}) {
  // Opened with the store that sealed it: this site's, or the project's (`credentialScopes`).
  const scoped = scopeOfRow(deps, { workspaceId: input.workspaceId, row: candidate });
  try { return await vault(scoped.deps).get({ ...credentialScope({ workspaceId: scoped.workspaceId, kind: candidate.kind === "custom" ? "custom" : "vendor" }), id: input.id }); }
  catch { throw new PublishCredentialSecretStoreUnconfiguredError(CREDENTIAL_MESSAGES.storage); }
}

function publishConnectionFromPayload({ providerId, spec, summary, payload }: {
  providerId: string; spec: DeployTargetCredentialSpec; summary: VaultSummary; payload: unknown;
}, _options = {}): PublishConnectionInput {
  if (!payload) throw new PublishCredentialSecretStoreUnconfiguredError(CREDENTIAL_MESSAGES.storage);
  const { vendorId: _vendorId, ...fields } = payload as Record<string, string>;
  const connection = summary.meta.credentialType === "custom" ? { providerId, [spec.tokenField]: fields.token! } : { ...fields, providerId };
  if (typeof connection[spec.tokenField] !== "string" || !connection[spec.tokenField]!.trim()) throw new PublishCredentialSecretStoreUnconfiguredError(CREDENTIAL_MESSAGES.storage);
  return connection;
}

/** The same selection policy serves implicit publishing, readiness and explicit-ID resolution.
 * @complexity O(rows × compatibility IDs + payload); one two-kind inventory and one selected open.
 */
export async function resolveDefaultForPublish(deps: PublishCredentialResolveDeps,
  input: { workspaceId: UUID; providerId: PublishProviderId },
): Promise<{ id: UUID; label: string; connection: PublishConnectionInput } | null> {
  const registry = await deps.loadDeployTargets(input.workspaceId);
  const provider = providerContract({ registry, providerId: input.providerId });
  if (!provider) return null;
  const rows = await inventory({ deps, workspaceId: input.workspaceId });
  const selected = selectPublishCredential({ registry, credentials: rows, provider });
  if (!selected) return null;
  const resolved = await resolveFromInventory({ deps, input: { ...input, id: selected.id }, registry, rows });
  return resolved ? { id: selected.id, label: resolved.label, connection: resolved.connection } : null;
}

/**
 * Persists a freshly-verified account label onto an existing row — see this file's own header for
 * why {@link createPublishCredential}/{@link updatePublishCredential} never do this themselves. The
 * ONE intended caller is the admin credential-CRUD route (`server/routes/admin/system/publish-
 * credentials.ts`), immediately after its own `verifyPublishCredentialById` call returns a `"valid"`
 * result carrying an `accountLabel`. Never call this with an EMPTY/absent label to "clear" one: a
 * failed or inconclusive re-verify carries no `accountLabel` at all and must leave a previously-healed
 * value alone — the caller's own `result.accountLabel !== undefined` check enforces that.
 *
 * A targeted single-column write ({@link VendorCredentialSetRepoPort.updateAccountLabel}), not a
 * full-row replace — never touches `sealed`, `isDefault`, or `updatedAt`.
 *
 * Written where the row lives: this site's vault, else the project's.
 *
 * @complexity O(1) — one lookup and one repo write (a no-op, not an error, if the row vanished meanwhile).
 */
export async function healAccountLabel(deps: { repo: VendorCredentialSetRepoPort }, input: { workspaceId: UUID; id: UUID; accountLabel: string }): Promise<void> {
  const owner = await ownerOf(deps.repo, input);
  await owner.repo.updateAccountLabel({ ...input, workspaceId: owner.workspaceId });
}

import type { CredentialTokenHint } from '../../../contracts/core/credential-token.js';
import type { ISODateTime, UUID } from "@jini-ai/core/primitives";

/**
 * @file Domain types for named, workspace-scoped provider connections used to publish a static
 * export to a host plugin's deploy target (`publish_credential_sets`,
 * `src/platform/db/schema.sqlite.ts`). Design: `ADS-memory/reports/external-audit/runs/
 * 2026-08-15-terra-xhigh-publish-credentials-design.md`.
 *
 * Purpose:
 * `PublishProviderId` is this codebase's ONE canonical 4-provider union — `../static-publish/
 * types.ts`'s `StaticPublishTargetId` is a type ALIAS of this union (not a second, independently
 * declared one), so the provider set can never drift between "what a credential can be saved for"
 * and "what a publish can target". This module owns the canonical declaration (not the other way
 * around) because a credential's provider identity is the more general, storage-shaped concept; a
 * one-shot publish operation borrows it, not the reverse.
 *
 * `PublishConnectionInput` is a CLOSED discriminated union on `providerId` — deliberately not an
 * open bag of optional fields, so a caller can never construct a connection with the wrong provider's
 * companion fields and have it silently ignored. Every host's required/optional split comes from
 * its plugin's descriptor (some need more than a bare token, e.g. an owner/repo or an account id,
 * HARD required — see `store.ts`'s `validateConnection`); other hosts' companion fields are
 * genuinely optional. Per-host notes on which stored companion fields a deploy target actually
 * reads live with the host plugin (`content/agent-plugins/<host>/NOTES.md`).
 *
 * A companion field is accepted and stored here even when, as of this pass, the host's deploy
 * target has nowhere to send it once decrypted. Storing it anyway keeps this module's contract
 * stable for whichever side (this store, or a future deploy-target change) ships second — see `../static-publish/adapter.ts`'s header for where this gap is flagged again at
 * the point it would actually matter (wiring a real publish).
 *
 * Architectural role:
 * Domain types only — no I/O, no sealer/keyring dependency. `store.ts` is the one place a
 * `PublishConnectionInput` is validated, serialized, and sealed. Since migration 0012 the sealed
 * connections are vendor vault rows, persisted through `VendorCredentialSetRepoPort`
 * (`../../vendor-credentials/types.ts`, which carries the `isDefault`/`updateAccountLabel` contract).
 */

/** A deploy target id (`DeployTargetDescriptor.id`) that takes a saved credential. Open: which ids
 *  exist is the deploy registry's business, validated where a connection is written (`store.ts`). */
export type PublishProviderId = string;

/**
 * A saved connection: the target id plus the flat string fields that host's deploy-plugin descriptor
 * declares for its credential (`DeployTargetDescriptor.credential`), validated by `store.ts`. This
 * whole object is what gets serialized to JSON and sealed as ONE ciphertext blob per credential set
 * (never per-field columns — see `src/platform/db/schema.sqlite.ts`'s `publishCredentialSets` header
 * for why). The shape is byte-compatible with rows sealed before hosts moved into the plugin: same
 * `providerId`, same field names.
 *
 * Publish-TARGET settings (a repository, a team) are never credential fields: they are chosen per
 * publish run and live on the publish config.
 */
export type PublishConnectionInput = { readonly providerId: PublishProviderId } & Readonly<Record<string, string>>;

/** The read model every route/tool in this feature returns — see `store.ts`'s `toSummary`. NEVER
 *  contains `sealed`, a token, or any `PublishConnectionInput` field — enforced by construction: this
 *  type has no field capable of carrying one. */
export interface PublishCredentialSummary {
  readonly credentialType: "vendor" | "custom";
  readonly worksFor: string[];
  readonly publishHosts: string[];
  readonly defaultFor: string[];
  readonly tokenHint?: CredentialTokenHint | null;
  readonly id: UUID;
  /** Display host: the first compatible target, or the stored vendor's editing host. */
  readonly providerId: PublishProviderId;
  /** Stored vendor group; custom NULL-provider keys use the display host's vendor. */
  readonly vendorId: string;
  readonly label: string;
  readonly configured: true;
  /** At most one `true` per vendor group, maintained by `store.ts`'s write path — see
   *  `VendorCredentialSetRepoPort`'s doc for the invariant. */
  readonly isDefault: boolean;
  /** Last 4 characters of the token field — see `vendor_credential_sets.token_tail`'s own doc. */
  readonly tokenTail: string;
  /** The verified account's public login, held in the clear (never sealed) — carried through
   *  unchanged, never re-derived here (this is a read model, it never decrypts or verifies anything).
   *  Create, a connection rotation or a vendor move reset it; only the verify heal
   *  (`healAccountLabel`) populates it. */
  readonly accountLabel: string | null;
  /** Where the row lives — present only where a project store is attached (local web + desktop):
   *  `"project"` is visible to attached sites only, `"site"` is this site's own (an override). */
  readonly scope?: PublishCredentialScope;
  readonly createdAt: ISODateTime;
  readonly updatedAt: ISODateTime;
}

/** This site's own vault, or the project store every site of the project shares (`project.db`). */
export type PublishCredentialScope = "site" | "project";

