/**
 * @file Publishes Tovu's own static export through a deploy target that an Agent Plugin contributes
 * (`deploy-targets/registry.ts`). Core names no hosting vendor: which targets exist, which config
 * fields each takes, how each validates them, which base path each serves from, and what extra files
 * each host needs all come from the plugin's descriptor and module (deploy plan T7).
 *
 * Purpose:
 * "Wrap it, do not reimplement" — this module does no host HTTP itself. It (a) resolves the target
 * and checks its config ({@link planStaticPublish}), (b) runs Tovu's real static exporter with the
 * base path the target's module computes, (c) maps the resulting `ExportReport` into `DeployFile[]`,
 * and (d) hands the file set, plus the live security headers as data (`responseHeaders`), to the
 * `DeployTarget` the module builds.
 *
 * Base-path/target mismatch, made structurally impossible rather than merely documented:
 * `StaticPublishConfig` has NO `basePath` field — a caller can never supply one. The target module
 * derives it from the config, and {@link publishStaticSite} always runs a FRESH `exportSite` with
 * that exact value immediately before publishing, so no previously-produced export (built with some
 * other or no base path) can reach a target. The cost is a full re-export per publish, accepted
 * deliberately: a stale base path silently 404ing every asset on a live site is strictly worse.
 *
 * A refused export (any route or asset failed) never reaches a target at all — this module will not
 * publish a known-incomplete site, mirroring `cli/commands/export.ts`'s own honesty contract.
 *
 * Architectural role:
 * `features/deployments/static-publish` domain logic. Depends on `deploy-targets/` for the target
 * registry and host kit. No dependency on `../ports.ts`/`content/agent-plugins/github/deployments/github.mjs` (the sibling
 * continuous-deployment feature) — see `./types.ts`'s header for why these stay separate.
 */

const MAX_PROJECT_NAME_LENGTH = 200;

/** {@link planStaticPublish}'s answer: the resolved target and the base path it serves from, or a
 *  human-readable refusal safe to return over an HTTP/tool boundary. */
export type StaticPublishPlan =
  | { readonly ok: true; readonly target: LoadedDeployTarget; readonly basePath?: string }
  | { readonly ok: false; readonly message: string };

/**
 * Resolves `config.target` in `registry` and checks `config` against it: every required descriptor
 * field present and non-blank, then the module's own `validateConfig`. Pure given the registry, so
 * the admin preview, the agent tools and a real publish all reach the SAME verdict and base path.
 *
 * @returns The plan, or the first refusal. Messages never echo more than the offending field.
 * @complexity O(f) declared config fields plus the module's own (constant-size) checks.
 */
export function planStaticPublish(registry: DeployTargetRegistry, config: StaticPublishConfig): StaticPublishPlan {
  const target = registry.get(config.target);
  if (target === undefined) return { ok: false, message: unknownTargetMessage(registry, config.target) };
  const missing = missingRequiredFieldMessage(target, config);
  if (missing !== null) return { ok: false, message: missing };
  const moduleConfig = config as unknown as UnknownRecord;
  const configError = target.module.validateConfig?.(moduleConfig);
  if (configError) return { ok: false, message: configError };
  const basePath = target.module.basePath?.(moduleConfig);
  return { ok: true, target, ...(basePath !== undefined ? { basePath } : {}) };
}

/** The refusal for the first descriptor-required field `config` leaves absent or blank, else `null`.
 *  Exported so the admin preview can answer a missing field as a malformed request (400) while a
 *  present-but-invalid value stays a 200 `valid:false`. @complexity O(f) declared config fields. */
export function missingRequiredFieldMessage(target: LoadedDeployTarget, config: StaticPublishConfig): string | null {
  for (const field of target.descriptor.configFields) {
    const value = config[field.name];
    if (field.required && (typeof value !== "string" || value.trim() === "")) {
      return `'${field.name}' (non-empty string) is required for target '${config.target}'`;
    }
  }
  return null;
}

/** The refusal for an id the registry does not know, naming what IS available. @complexity O(t). */
export function unknownTargetMessage(registry: DeployTargetRegistry, targetId: string): string {
  const ids = registry.list().map((target) => target.descriptor.id);
  if (ids.length === 0) return `publish target '${targetId.slice(0, 64)}' is not available: no publish targets are installed (turn on a hosting plugin under Agent Plugins)`;
  return `publish target '${targetId.slice(0, 64)}' is not available; choose one of: ${ids.join(", ")}`;
}

/**
 * Builds a publish config from loosely-typed input (a JSON body, a query string, a tool input):
 * `target` plus every descriptor-declared field that arrived as a string. Unknown keys are dropped,
 * so nothing a caller invents reaches a module. Whether required fields are present is judged once,
 * by {@link planStaticPublish}.
 *
 * @param blankAsAbsent - `true` for a query string or tool input, where an empty optional field
 *   means "not set"; `false` for a JSON body, which keeps it so the module can refuse it by name.
 * @returns The config, or the refusal for a declared field that arrived as a non-string.
 * @complexity O(f) declared fields.
 */
export function readStaticPublishConfig(
  target: LoadedDeployTarget,
  raw: Readonly<Record<string, unknown>>,
  options: { readonly blankAsAbsent: boolean },
): { readonly ok: true; readonly config: StaticPublishConfig } | { readonly ok: false; readonly message: string } {
  const config: Record<string, string> = { target: target.descriptor.id };
  for (const field of target.descriptor.configFields) {
    const value = raw[field.name];
    if (value === undefined || (options.blankAsAbsent && typeof value === "string" && value.trim() === "")) continue;
    if (typeof value !== "string") return { ok: false, message: `'${field.name}' must be a string` };
    config[field.name] = value;
  }
  return { ok: true, config: config as StaticPublishConfig };
}

/**
 * Each publish RUN gets its OWN directory under `infra/` (the Docker-volume-mounted directory every
 * other export/publish artifact already lives under) — `<parent>/<target>/<runId>`, not merely
 * `<parent>/<target>`. Exported (not merely internal) specifically so this per-run isolation is
 * directly testable.
 *
 * MEDIUM audit finding (2026-08-19, Codex sol bug/architecture audit): a fixed `<parent>/<target>`
 * directory meant two publishes overlapping for the SAME target — the admin UI and a confirmed
 * agent tool call, or two OS processes (`publish-run.ts`'s own header discloses its single-flight
 * guard is process-local only, a DELIBERATE, disclosed gap this fix closes as a side effect) — could
 * `clean:true` and rewrite the same directory out from under each other. `runId` (always a fresh
 * `input.idGen.newId()` value, minted once per {@link publishStaticSite} call) makes that
 * collision structurally impossible: no lock is needed because there is no longer anything shared to
 * lock. The directory is disposable once `exportSiteBound` returns — see
 * {@link cleanupPublishRunDir}'s own doc for why nothing downstream re-reads it from disk.
 *
 * `parent` is `RouteDeps.publishOutputRootDir` (`TOVU_PUBLISH_DIR` env, then `infra/publish` —
 * mirroring `export-site.ts`'s own `TOVU_EXPORT_DIR` knob), resolved ONCE by the composition root
 * (`server/app.ts`/`server/deps.ts`) and threaded through as {@link StaticPublishInput.publishOutputRootDir}
 * (2026-08-20 RouteDeps-narrowing fix — this used to be `input.routeDeps.publishOutputRootDir`; the
 * field moved, the value and its single-resolution-point discipline did not) — never read from
 * `process.env` in this file. A test overrides it the same way it always did: by setting
 * `publishOutputRootDir` on the fake `StaticPublishInput` it constructs, not by mutating real process
 * env vars.
 * @complexity O(1) — fixed-shape path join, no I/O.
 */
export function publishOutputDir(parent: string, target: StaticPublishTargetId, runId: string): string {
  return path.join(parent, target, runId);
}

/** Best-effort cleanup of one run's isolated export directory (see {@link publishOutputDir}'s own
 *  doc). Safe to call once `exportSiteBound` has returned or thrown: every byte `publishStaticSite`
 *  still needs travels through `report.routes.succeeded`/`report.assets.succeeded`'s own `data`
 *  fields (captured in memory at write time — `site-exporter.ts`'s own "reachable as DATA" header),
 *  never by re-reading this directory, so removing it here cannot affect anything downstream. Never
 *  throws: a cleanup failure (a stray permission error, a file another process still holds open)
 *  must not turn an otherwise-successful publish into a reported failure — the same best-effort,
 *  disclosed-rather-than-silent posture `publish-run.ts`'s `recordHistoryIfPublished` already
 *  documents for an analogous non-essential side effect.
 * @complexity O(n) in the (typically small) exported file count — a recursive directory removal. */
function cleanupPublishRunDir(outputDir: string): void {
  try {
    rmSync(outputDir, { recursive: true, force: true });
  } catch {
    // Swallowed deliberately — see this function's own doc.
  }
}

/** Normalizes an `ExportedRoute`/`ExportedAsset`'s `outputFile` (already deploy-relative, per that
 *  interface's own doc) to forward slashes — `path.relative` uses the platform separator, and every
 *  deploy target in `@jini-ai/devops` treats `DeployFile.file` as a literal repo/deployment path,
 *  where a stray backslash on a Windows host would be be a wrong path, not a normalized one.
 *
 *  `contentType` also accepts `null` here (as well as the caller simply omitting it): `ExportedRoute`/
 *  `ExportedAsset` carry it as `string | null` because a fetched response can genuinely have no
 *  `Content-Type` header — see that interface's own doc. `DeployFile.contentType` has no concept of
 *  `null`, so both "absent" states collapse to "omit the field" the same way here, at the one place
 *  that actually needs the narrower `string | undefined` shape. */
export function toDeployFile(entry: { outputFile: string; data: string | Buffer; contentType?: string | null }): DeployFile {
  return {
    file: entry.outputFile.split(path.sep).join("/"),
    data: entry.data,
    ...(entry.contentType !== undefined && entry.contentType !== null ? { contentType: entry.contentType } : {}),
  };
}

/** The resolved credential a `DeployTarget` is built from: `token` plus the host's other declared
 *  credential fields (see `types.ts`'s `PublishCredentialSource.resolve()` doc). */
export type ResolvedPublishCredential = DeployTargetCredential;

export interface StaticPublishDeps {
  readonly credentialSource: PublishCredentialSource;
  /** This workspace's plugin-contributed deploy targets (`deploy-targets/registry.ts`): the only
   *  place a target id, its config fields and its host behavior come from. */
  readonly loadDeployTargets: (workspaceId: string) => Promise<DeployTargetRegistry>;
  /** Test seam: builds the `DeployTarget` in place of the resolved module's `create()`. Config
   *  checks and the base path still come from the registry. */
  readonly buildTarget?: (config: StaticPublishConfig, credential: ResolvedPublishCredential) => DeployTarget;
  /** The kit handed to a plugin module. Defaults to {@link createDeployHostKit}; tests inject one. */
  readonly hostKit?: DeployHostKit;
  /** `RouteDeps.observability`: the default kit traces the plugin's egress through it. */
  readonly observability?: ObservabilityPort;
  readonly tracker?: Tracker;
  /** The site's form submissions destination. Absent: publishing carries no forms (the old behavior). */
  readonly formDestination?: StaticPublishFormDestinationPort;
}

/** What a publish does with the site's forms (`features/form-destinations/port.ts`): selection,
 *  receiver keys and an external receiver's `prepare` all live behind it. The receiver key is
 *  created on the first publish with active forms and saved only after that publish reaches the host. */
export type StaticPublishFormDestinationPort = FormReceiverPort;

/**
 * The composition-root-bound export call this domain takes instead of `RouteDeps` itself (2026-08-20
 * RouteDeps-narrowing fix, continuing `src/features/source-control/commit-site.ts`'s own
 * `ExportSiteBoundFn` fix onto this sibling domain — see that file's doc for the fuller design
 * rationale, and `server/routes/types.ts`'s `RouteDeps.exportSiteBound` doc for why this shape is
 * deliberately NOT the same as `RouteDeps.runExportSite`/`ExportEngine<RouteDeps>`).
 *
 * Declared locally, never imported from `RouteDeps` or from `commit-site.ts`'s identical copy — same
 * "duplicate the tiny type, never share across features" convention that file's own doc documents,
 * and the same one this file already followed for `OWNER_PATTERN`/`REPO_PATTERN`/`BRANCH_PATTERN`.
 */
export type ExportSiteBoundFn = (options: { outputDir: string; clean?: boolean; basePath?: string }) => Promise<ExportReport>;

export interface StaticPublishInput {
  /** Authenticated caller attribution, supplied by the HTTP/tool adapter, never publish config. */
  readonly productEvent?: { readonly userId: string; readonly source: "admin" | "assistant" };
  /** Server-held approval from the existing human exchange/gateway; never read from JSON input. */
  readonly domainApproval?: {
    readonly credentialBinding: string;
    readonly plan: NonNullable<import("../deploy-targets/types.js").DeployTargetInspection["domains"]>;
    readonly authorize: (required: { readonly fingerprint: string; readonly accountId: string }) => Promise<boolean>;
  };
  readonly workspaceId: string;
  /** `RouteDeps.publishOutputRootDir`, threaded down rather than the whole `RouteDeps` bag — see
   *  {@link ExportSiteBoundFn}'s own doc immediately above for why. */
  readonly publishOutputRootDir: string;
  readonly idGen: { newId(): string };
  /** The pre-bound export call — see {@link ExportSiteBoundFn}'s own doc for what it is and why it
   *  replaces the `routeDeps: RouteDeps` field this input used to carry. */
  readonly exportSiteBound: ExportSiteBoundFn;
  readonly config: StaticPublishConfig;
  /** Human-facing label — becomes e.g. a commit message subject or a host project-name seed.
   *  Sanitized further by the host's deploy target; validated here only
   *  for length and non-blankness. */
  readonly projectName: string;
  /** The saved connection the OPERATOR chose for this publish, when the caller has one (terra review
   *  2026-09-20, finding 1 — Critical). Passed through to `credentialSource.resolve()` VERBATIM and
   *  validated there, never here: this module has no repo/sealer and no way to judge an id. Absent
   *  means the caller genuinely has no chosen connection (`deployment_execute_static_publish`, and
   *  any install whose credentials come from server env vars) and the established default lookup
   *  applies — see `./types.ts`'s `PublishCredentialSource.resolve` doc for that contract. */
  readonly credentialId?: string;
}

/** The `{ok:true, ...}` member of `PublishCredentialSource["resolve"]`'s return union — the shape
 *  {@link resolvePublishCredentialForSite} hands back once it has already ruled out both a thrown
 *  decrypt failure and an `{ok:false}` "not configured" result. */
type ResolvedCredentialSourceSuccess = Extract<Awaited<ReturnType<PublishCredentialSource["resolve"]>>, { ok: true }>;

/**
 * Resolves `input.config.target`'s credential via `deps.credentialSource.resolve()`, translating
 * both a thrown decrypt failure and an `{ok:false}` "not configured" result into
 * {@link publishStaticSite}'s own `{ok:false, code, message}` channel — see that function's own
 * header doc for the full "never throws" contract this step upholds.
 *
 * `PublishCredentialSource.resolve()`'s own doc documents a throw as a real, DELIBERATE possibility
 * for the DB-backed source (`publish-credentials/store.ts`'s `resolveForPublish`/
 * `resolveDefaultForPublish`: "a decrypt failure here should surface, not degrade" — a corrupted row
 * or a missing site key throws rather than resolving a silent `null`). `publishStaticSite`'s own
 * contract is that IT never throws regardless — so a genuine decrypt failure still needs to
 * "surface", just through the established `{ok:false, code, message}` channel instead of an uncaught
 * exception, exactly like every other failure mode in that function. `err.message` only, same
 * boundary {@link publishAndMapOutcome}'s own catch documents — a decrypt failure's message names the
 * mechanism (bad AAD, tampered ciphertext, missing key), never the ciphertext or a derived secret
 * itself.
 */
async function resolvePublishCredentialForSite(
  deps: StaticPublishDeps,
  input: StaticPublishInput
): Promise<{ ok: true; credential: ResolvedCredentialSourceSuccess } | { ok: false; outcome: StaticPublishOutcome }> {
  let credential: Awaited<ReturnType<PublishCredentialSource["resolve"]>>;
  try {
    credential = await deps.credentialSource.resolve({
      workspaceId: input.workspaceId,
      target: input.config.target,
      // Conditional spread, never `credentialId: input.credentialId` — an absent choice must not
      // travel as an explicit `undefined` key, which a source could read as "a choice was made".
      ...(input.credentialId !== undefined ? { credentialId: input.credentialId } : {}),
    });
  } catch (err) {
    return {
      ok: false,
      outcome: {
        ok: false,
        code: "NO_CREDENTIALS_CONFIGURED",
        credentialSetup: issueCredentialSetup({ setupToolId: "credential_save", prefill: { kind: "publish-host", target: input.config.target } }, {}),
        message: `credential could not be resolved: ${err instanceof Error ? err.message : String(err)}`,
      },
    };
  }
  if (!credential.ok) {
    return { ok: false, outcome: { ok: false, code: "NO_CREDENTIALS_CONFIGURED", credentialSetup: issueCredentialSetup({ setupToolId: "credential_save", prefill: { kind: "publish-host", target: input.config.target } }, {}), message: credential.reason } };
  }
  return { ok: true, credential };
}

/**
 * Runs `input.exportSiteBound` for this one publish run into `outputDir`, translating both a thrown
 * export failure and a report carrying a failed route/asset into {@link publishStaticSite}'s own
 * `{ok:false, code:"EXPORT_FAILED"}` channel. Cleans up the run's output directory in every case
 * (thrown, failed-report, or success) — see {@link cleanupPublishRunDir}'s own doc for why the
 * directory is safe to remove immediately once this call has produced its in-memory `report`.
 *
 * Checks BOTH `routes.failed` and `assets.failed` (HIGH audit finding, 2026-08-19 Codex sol bug/
 * architecture audit) — this used to check only `routes.failed`, so a page could export fine while
 * its own stylesheet or hero image 404s and publishing would still report success. See
 * `firstExportFailure`'s own doc (`#src/features/site-export/export-failure-summary`) for the shared check both this
 * function and `commit-site.ts`'s `commitSiteToSourceControl` now use.
 */
async function runExportForPublish(
  input: StaticPublishInput,
  outputDir: string,
  basePath: string | undefined
): Promise<{ ok: true; report: ExportReport } | { ok: false; outcome: StaticPublishOutcome }> {
  let report: ExportReport;
  try {
    report = await input.exportSiteBound({ outputDir, clean: true, ...(basePath !== undefined ? { basePath } : {}) });
  } catch (err) {
    cleanupPublishRunDir(outputDir);
    return {
      ok: false,
      outcome: {
        ok: false,
        code: "EXPORT_FAILED",
        message: `export failed before publishing could start: ${err instanceof Error ? err.message : String(err)}`,
      },
    };
  }
  cleanupPublishRunDir(outputDir);

  const failure = firstExportFailure(report);
  if (failure) {
    return {
      ok: false,
      outcome: {
        ok: false,
        code: "EXPORT_FAILED",
        message: `refused to publish: ${failure.count} ${failure.kind}(s) failed to export (first: '${failure.identifier}' — ${failure.reason}). Call deployment_diagnose_static_export for the full list.`,
      },
    };
  }
  return { ok: true, report };
}

/** Maps a successful export `report` to the `DeployFile[]` a target's `publish()` takes. A host's
 *  own extra files (a header config, a marker file) are its module's job, never this one's.
 *  @complexity O(n) in the exported route + asset count. */
function buildDeployFilesForPublish(report: ExportReport): DeployFile[] {
  return [...report.routes.succeeded.map(toDeployFile), ...report.assets.succeeded.map(toDeployFile)];
}

/**
 * `result.status` is EVERY target's own honest terminal state (`DeployLinkStatus`) — not merely "did
 * the API call succeed". A status other than 'ready' means the provider accepted the publish but the
 * site is not (yet, or ever, without a further step outside this call) reachable — spec
 * `custom-publish-provider-contract.md` §3a's "uploaded, but not yet reachable" requirement, required
 * regardless of provider once `StaticPublishOutcome` carries a real third branch for it (see that
 * type's own header). Applied uniformly here rather than special-cased per target: every target
 * already resolves its own `status` internally before returning (verified directly against
 * `VercelDeployTarget.publish()`'s own `waitForReachableDeploymentUrl` call), so this is the one
 * place that turns an already-honest `status` into an equally-honest `StaticPublishOutcome`.
 */
function buildPartialPublishOutcome(targetId: StaticPublishTargetId, result: DeployPublishResult, basePath: string | undefined): StaticPublishOutcome {
  return {
    ok: "partial",
    targetId,
    url: result.url,
    status: result.status,
    message: result.statusMessage ?? `Published to ${targetId}, but the public URL is not confirmed reachable yet (status: ${result.status}).`,
    ...(result.deploymentId !== undefined ? { deploymentId: result.deploymentId } : {}),
    ...(basePath !== undefined ? { basePath } : {}),
    ...(result.providerMetadata !== undefined ? { providerMetadata: result.providerMetadata } : {}),
  };
}

/** {@link buildPartialPublishOutcome}'s sibling for `result.status === "ready"` — a full success. */
function buildSuccessPublishOutcome(targetId: StaticPublishTargetId, result: DeployPublishResult, basePath: string | undefined): StaticPublishOutcome {
  return {
    ok: true,
    targetId,
    url: result.url,
    status: result.status,
    ...(result.deploymentId !== undefined ? { deploymentId: result.deploymentId } : {}),
    ...(basePath !== undefined ? { basePath } : {}),
    ...(result.providerMetadata !== undefined ? { providerMetadata: result.providerMetadata } : {}),
  };
}

/**
 * Calls `jiniTarget.publish()` and maps its result to a {@link StaticPublishOutcome}, translating a
 * rejected `publish()` call into {@link publishStaticSite}'s own `{ok:false, code:"PROVIDER_ERROR"}`
 * channel.
 *
 * `err.message` only — never `DeployError.details` (the raw upstream response body) or the error
 * object itself. This crosses an HTTP/tool-result boundary (the admin route's JSON response, the
 * agent tool's result), the same "message, never the raw error" discipline `export-site.ts`'s own
 * errored-run summary already follows. No observed host deploy target puts `credential.token`
 * into a `DeployError` message, but this boundary still holds even if one ever did.
 */
async function publishAndMapOutcome(
  jiniTarget: DeployTarget,
  publishInput: DeployPublishInput,
  input: StaticPublishInput,
  basePath: string | undefined,
  formDestination?: FormDestinationPublishInput
): Promise<StaticPublishOutcome> {
  try {
    const result = await jiniTarget.publish(publishInput, { responseHeaders: publicPageSecurityHeaders({}),
      metadata: { ...input.config, ...(input.domainApproval ? { domainApproval: input.domainApproval } : {}), ...(formDestination ? { formDestination } : {}) } });
    if (result.status !== "ready") {
      return buildPartialPublishOutcome(input.config.target, result, basePath);
    }
    return buildSuccessPublishOutcome(input.config.target, result, basePath);
  } catch (err) {
    const message = err instanceof DeployError || err instanceof Error ? err.message : String(err);
    return { ok: false, code: "PROVIDER_ERROR", message };
  }
}

/**
 * Publishes Tovu's current site content to `input.config.target`. Always runs a fresh, `clean`
 * export with the target-correct base path immediately before publishing (see this file's header)
 * — never reuses a previously-produced export directory.
 *
 * Never throws: every failure (an unknown target or bad config, a registry that will not load, a
 * credential that does not resolve — including a genuine DECRYPT failure, see
 * {@link resolvePublishCredentialForSite} — a failed export, a credential unusable for the target, or
 * a rejected `publish()` call) is returned as `{ok: false, code, message}`. `message` is always built
 * from `err.message`, never a raw `DeployError.details`/response-body object. Every caller
 * (`publish-site.ts`'s HTTP route, `deployment_execute_static_publish`) relies on this.
 *
 * Orchestrates its work as a flat sequence of steps, each translating its own failure mode into this
 * function's `{ok:false, code, message}` channel and returning early: {@link resolvePublishPlan},
 * {@link resolvePublishCredentialForSite}, {@link runExportForPublish}, {@link constructTargetForPublish},
 * then {@link publishAndMapOutcome} for the terminal result.
 *
 * @complexity One registry load, one `exportSite` pass (O(routes + assets) HTTP requests against the
 *   in-process app) plus one `DeployTarget.publish()` call (bounded by that target's own poll budget).
 */
export async function publishStaticSite(deps: StaticPublishDeps, input: StaticPublishInput): Promise<StaticPublishOutcome> {
  // Publish/deploy chokepoint: one `site.publish` operation per run (target id only; the outcome
  // is `published` or the failure code), with its export and host egress as child spans.
  const tracker = deps.tracker ?? createNoopTracker({});
  return tracker.trace({ name: "site.publish", run: async (span) => {
    const outcome = await publishStaticSiteSteps(deps, input);
    span.setOutcome(outcome.ok ? { outcome: "published", failed: false } : { outcome: outcome.code, failed: true });
    return outcome;
  } }, { attributes: { "publish.target": input.config.target } });
}

/** {@link publishStaticSite}'s steps, inside its operation. */
async function publishStaticSiteSteps(deps: StaticPublishDeps, input: StaticPublishInput): Promise<StaticPublishOutcome> {
  if (input.projectName.trim() === "" || input.projectName.length > MAX_PROJECT_NAME_LENGTH) {
    return { ok: false, code: "INVALID_CONFIG", message: `projectName must be 1-${MAX_PROJECT_NAME_LENGTH} characters` };
  }
  const plan = await resolvePublishPlan(deps, input);
  if (!plan.ok) return { ok: false, code: "INVALID_CONFIG", message: plan.message };

  const credentialResult = await resolvePublishCredentialForSite(deps, input);
  if (!credentialResult.ok) {
    return credentialResult.outcome;
  }
  if (input.domainApproval && input.domainApproval.credentialBinding !== createHash("sha256").update(JSON.stringify(toDeployTargetCredential(credentialResult.credential))).digest("hex")) {
    return { ok: false, code: "INVALID_CONFIG", message: "CREDENTIAL_CHANGED: The connection changed after domain review. Preview and confirm again before publishing." };
  }

  const outputDir = publishOutputDir(input.publishOutputRootDir, input.config.target, input.idGen.newId());
  const exportResult = await runExportForPublish(input, outputDir, plan.basePath);
  if (!exportResult.ok) {
    return exportResult.outcome;
  }

  const files = buildDeployFilesForPublish(exportResult.report);
  const resolvedCredential = toDeployTargetCredential(credentialResult.credential);
  const targetResult = constructTargetForPublish(deps, plan.target, input.config, resolvedCredential);
  if (!targetResult.ok) {
    return targetResult.outcome;
  }

  const forms = await prepareFormDestination({ deps, input });
  if (!forms.ok) return forms.outcome;
  const publishInput: DeployPublishInput = { files: filesForReceiver({ files, submitUrl: forms.submitUrl }), projectName: input.projectName };
  const outcome = await publishAndMapOutcome(targetResult.target, publishInput, input, plan.basePath, forms.hosting);
  await saveReceiverKey({ outcome, save: forms.save });
  return finishPublishOutcome({ outcome, credential: credentialResult.credential, target: plan.target });
}

/**
 * The site's active forms and, when there are any, its receiver key, for the receiver the site's
 * form setting selects (`features/form-destinations/port.ts`): the co-hosted add-on for this host
 * (`hosting`), or an external receiver's post address (`submitUrl`). No port: nothing is sent and
 * no key is created.
 * @complexity One forms read plus at most one key read (and an external receiver's own prepare).
 */
async function prepareFormDestination({ deps, input }: { deps: StaticPublishDeps; input: StaticPublishInput }, _options = {}): Promise<
  ({ ok: true } & FormReceiverPlan) | { ok: false; outcome: StaticPublishOutcome }> {
  if (!deps.formDestination) return { ok: true };
  try {
    const plan = await deps.formDestination.prepare({ workspaceId: input.workspaceId, hostingTargetId: input.config.target, projectName: input.projectName,
      kit: deps.hostKit ?? createDeployHostKit({ observability: deps.observability }) });
    return { ok: true, ...plan };
  } catch (err) {
    return { ok: false, outcome: { ok: false, code: "EXPORT_FAILED", message: `form submissions could not be prepared: ${err instanceof Error ? err.message : String(err)}. Check the site's forms, then publish again.` } };
  }
}

/** An external receiver: exported pages post to its address instead of the site's own path. @complexity O(HTML bytes). */
function filesForReceiver({ files, submitUrl }: { files: DeployFile[]; submitUrl?: string | undefined }, _options = {}): DeployFile[] {
  return submitUrl ? rewriteFormActions({ files, submitUrl }) : files;
}

/** Saves the receiver key (new, or moved after a rename) once the host has it. A failed save is logged, not fatal: the
 *  next publish creates and installs a fresh key, and rows still waiting at the host stay pullable. */
async function saveReceiverKey({ outcome, save }: { outcome: StaticPublishOutcome; save?: (required: { readonly url: string }) => Promise<void> }, _options = {}): Promise<void> {
  if (!save || outcome.ok === false) return;
  try { await save({ url: outcome.url }); }
  catch { console.warn("[static-publish] the form receiver key could not be saved; the next publish will replace it"); }
}

/** Redact declared secrets from full/partial provider failures and retain the saved credential id.
 * @complexity O(fields + message bytes × secrets), delegated to the shared redactor. */
function finishPublishOutcome({ outcome, credential, target }: {
  outcome: StaticPublishOutcome; credential: ResolvedCredentialSourceSuccess; target: LoadedDeployTarget;
}, _options = {}): StaticPublishOutcome {
  // A plugin can include its credential in an error message. Keep the useful provider explanation
  // while removing every declared secret before this site-publish response reaches HTTP or a tool.
  const safe = "message" in outcome
    ? { ...outcome, message: redactDeployTargetMessage({ message: outcome.message, credential, target }) } : outcome;
  // Bind history to the row opened for this run, never a later default lookup.
  return safe.ok && credential.credentialId !== undefined ? { ...safe, credentialId: credential.credentialId } : safe;
}

/**
 * Loads this workspace's registry and plans the publish against it. Every registry refusal (a plugin
 * or module that did not load) is logged, never returned: the caller's answer is about ITS target.
 * @complexity One registry load (see `loadDeployTargetRegistry`).
 */
async function resolvePublishPlan(deps: StaticPublishDeps, input: StaticPublishInput): Promise<StaticPublishPlan> {
  let registry: DeployTargetRegistry;
  try {
    registry = await deps.loadDeployTargets(input.workspaceId);
  } catch (err) {
    return { ok: false, message: `publish targets could not be loaded: ${err instanceof Error ? err.message : String(err)}` };
  }
  for (const refusal of registry.refusals) console.warn(`[static-publish] ${refusal}`);
  return planStaticPublish(registry, input.config);
}

/**
 * Adapts an installed module's target to devops' {@link DeployTarget} port. Installed
 * content-addressed modules keep their ABI: security headers still reach the first object, and
 * `checkReachability` takes the bare URL string, so the port's `{ url }` is unwrapped here.
 * @param installedTarget What the plugin module's `create` returned.
 * @returns The same target behind the devops port.
 * @complexity O(1); each call forwards once.
 */
export function adaptInstalledTarget(installedTarget: HostDeployTarget): DeployTarget {
  return {
    id: installedTarget.id,
    publish: (required, optional) => installedTarget.publish({ ...required, ...optional }),
    checkReachability: ({ url }) => installedTarget.checkReachability(url),
  };
}

/**
 * Constructs the `DeployTarget` `publishAndMapOutcome` will call `publish()` on, translating a throw
 * (typically a credential missing a field the host requires) into {@link publishStaticSite}'s own
 * `{ok:false, code}` channel — the message, never the raw error object, since it crosses an
 * HTTP/tool-result boundary.
 * @complexity O(1) plus the module's own construction.
 */
function constructTargetForPublish(
  deps: StaticPublishDeps,
  pluginTarget: LoadedDeployTarget,
  config: StaticPublishConfig,
  credential: ResolvedPublishCredential
): { ok: true; target: DeployTarget } | { ok: false; outcome: StaticPublishOutcome } {
  try {
    if (deps.buildTarget !== undefined) return { ok: true, target: deps.buildTarget(config, credential) };
    const kit = deps.hostKit ?? createDeployHostKit({ observability: deps.observability });
    return { ok: true, target: adaptInstalledTarget(pluginTarget.module.create({ credential, config: config as unknown as UnknownRecord, kit })) };
  } catch {
    // Adapter exceptions may include a credential field; the card needs only the target identifier.
    return { ok: false, outcome: { ok: false, code: "NO_CREDENTIALS_CONFIGURED", message: `credential is not usable for ${config.target}`,
      credentialSetup: issueCredentialSetup({ setupToolId: "credential_save", prefill: { kind: "publish-host", target: config.target } }, {}) } };
  }
}

import type { DeployTargetInspection } from '../deploy-targets/types.js';

type DetailRow = { readonly label: string; readonly value: string };

/**
 * Projects a plugin's opaque inspection onto the domain confirmation card as short readable rows:
 * what is published where, the current state of every hostname, then each change, one per row.
 * Changes come from `domains.changes` — the exact list that will run, already de-duplicated (a
 * wildcard route seen from both hostnames is removed once) — not from the per-hostname views.
 * Vendor interpretation stays in the plugin: a change's own `reason` (or a host's `summary`) is
 * shown as written; anything without one falls back to its plain fields — never a JSON dump, and
 * never silently dropped, because the card is the person's consent to exactly these changes.
 * @param required - Inspected plan plus the site's project and target labels.
 * @param _options - Reserved options.
 * @returns Plain text rows in card order.
 * @complexity O(n) time/space in the inspection's size.
 */
export function domainPublishRows(required: {
  inspection: DeployTargetInspection; projectName: string; target: string;
}, _options = {}): DetailRow[] {
  const { inspection, projectName, target } = required;
  const changes = inspection.domains?.changes ?? [];
  return [
    { label: 'Project', value: projectName }, { label: 'Target', value: target },
    ...inspection.hostingChanges.map(change => ({ label: 'Hosting', value: describe({ value: change }) })),
    ...(inspection.domains?.hostnames ?? []).map(host => hostnameRow({ host })),
    ...(changes.length ? changes.map(change => ({ label: 'Will change', value: describe({ value: change }) })) : [{ label: 'Will change', value: 'No domain changes.' }]),
    ...(inspection.formSubmissions ? [{ label: 'Form submissions', value: inspection.formSubmissions.message }] : []),
  ];
}

/** One hostname's current state: the plugin's own summary when it gives one, else its status. */
function hostnameRow({ host }: { host: Readonly<Record<string, unknown>> }, _options = {}): DetailRow {
  const hostname = typeof host.hostname === 'string' ? host.hostname : 'hostname';
  const now = typeof host.summary === 'string' && host.summary.trim() ? host.summary
    : typeof host.status === 'string' ? host.status.replaceAll('-', ' ') : 'unknown';
  return { label: `Now on ${hostname}`, value: now };
}

/** A plugin-written `reason` when present; otherwise the value's own fields as `key: value` text. */
function describe({ value }: { value: unknown }, _options = {}): string {
  if (value === null || typeof value !== 'object') return String(value);
  if (Array.isArray(value)) return value.map(item => describe({ value: item })).join('; ');
  const record = value as Readonly<Record<string, unknown>>;
  if (typeof record.reason === 'string' && record.reason.trim()) return record.reason;
  return Object.entries(record).map(([key, item]) => item !== null && typeof item === 'object' ? `${key}: (${describe({ value: item })})` : `${key}: ${String(item)}`).join(', ');
}

import type { UUID } from "@jini-ai/core/primitives";

import type { StaticPublishTargetId } from "./types.js";
import { resolvePublishHistoryListLimit } from "#src/contracts/core/publish-history-list-limit";
import type { DeployTargetDescriptor, DeployTargetRegistry } from "../deploy-targets/types.js";
import type { PublishContentPeerSummary } from "#src/features/publish-content/peers";

/**
 * @file Durable, append-only publish-history ledger.
 * Publish results are records, not cache slots: keeping them in the database makes them durable,
 * queryable and joinable without overwriting earlier publishes. publish-run.ts's in-process
 * snapshot answers whether a publish is running; it cannot supply persistent per-target history.
 *
 * Purpose:
 * {@link PublishHistoryStore} is the port — `getLast` (the single most recent row for a
 * `(workspace, target)` pair, what `deployment_get_static_publish_capabilities` surfaces as
 * `lastPublish`) and `list` (newest-first, workspace-scoped, optionally target-scoped — what a future
 * history UI would page through). {@link InMemoryPublishHistoryStore} is the test double, append-only
 * like the real table (a test asserting "the second publish did not erase the first" needs an
 * in-memory double that can actually fail that assertion). `SqlitePublishHistoryStore`
 * (`src/platform/db/sqlite/publish-history-repo.sqlite.ts`, this feature's real ADR-006 rule-of-two second
 * adapter) is the production implementation — it lives under `src/platform/db/sqlite/`, not here, matching
 * every other DB-backed port/adapter split in this codebase (`VendorCredentialSetRepoPort` in
 * `features/vendor-credentials/`, `SqliteVendorCredentialSetRepo` there in `db/sqlite/`).
 *
 * Architectural role:
 * `features/deployments/static-publish` domain logic — this file declares the port and its in-memory
 * test double only; no Drizzle/SQL import belongs here (that is the adapter's job, one layer down).
 * Static publishes settle through `publish-run.ts` (both its shared entry
 * points — the admin route's fire-and-forget `startPublishRun` and the agent tool's awaited
 * `runPublishAndAwait` — settle through the same function, so both callers record identically with no
 * change needed at either call site). `publish-agent-tools.ts`'s capabilities handler is the one
 * place `getLast` is read from today, surfaced per provider as `lastPublish`.
 * Coordinator decision (2026-10-18): outbound peer execution and deploy-ops also append here;
 * destination memory belongs to this ledger rather than separate per-flow stores.
 */

/** Which of this feature's two entry points produced a given {@link PublishHistoryEntry} — the admin
 *  UI's Static Site tab (`publish-site.ts`'s HTTP trigger route, via `startPublishRun`) or the
 *  assistant's confirmed publish tool (`publish-agent-tools.ts`'s `deployment_execute_static_publish`,
 *  via `runPublishAndAwait`). Free to compute at the source: `publish-run.ts`'s two entry functions
 *  each hardcode their own literal when calling into history recording, since which caller reached
 *  which function IS the answer — no request-scoped or caller-supplied value is needed. */
export type PublishTrigger = "admin_ui" | "agent_tool";

/** One recorded publish — a row in the append-only ledger, not a cache slot. `owner`/`repo`/`branch`/
 *  `commitSha` are present only for a git-backed target (`StaticPublishConfig`'s own per-target
 *  field split — see `types.ts`); every other target carries none of the four. `commitSha` specifically is
 *  NOT a placeholder that is always empty for every other target because it could not be obtained —
 *  it genuinely does not exist for them (their publishes are not git commits); see
 *  `publish-run.ts`'s `toHistoryEntry` for where this is derived from the target's own outcome. */
export interface PublishHistoryEntry {
  /** Absent/null legacy discriminator means static. Other kinds reuse target as their owner id. */
  readonly kind?: "static" | "tovu-peer" | "deploy";
  readonly target: StaticPublishTargetId;
  readonly url: string;
  /** `false` for an accepted deploy without confirmed landing, or an "uploaded, not yet confirmed
   *  reachable" partial outcome (`StaticPublishOutcome`'s own `ok: "partial"` branch). Everything else that reaches this store
   *  at all is a full, confirmed-live success (see {@link PublishHistoryStore.recordSuccess}'s own
   *  doc: an `ok: false` outcome is never recorded, so `reachable` is never "the publish failed"). */
  readonly reachable: boolean;
  readonly status: string;
  readonly projectName: string;
  /** Saved connection actually resolved, including default selection; never its secret. */
  readonly credentialId?: string;
  /** Descriptor-allowlisted non-secret settings. Absent on legacy, non-replayable history. */
  readonly configFields?: Readonly<Record<string, string>>;
  readonly publishedAt: string;
  readonly owner?: string;
  readonly repo?: string;
  readonly basePath?: string;
  /** The provider's own opaque identifier for this publish — `StaticPublishOutcome.deploymentId`,
   *  verbatim, whatever it means for that target (a host deploy id, or, for a git-backed target, the
   *  same commit sha `commitSha` below also carries). Absent when the outcome carried none (a
   *  target with no deployment concept, e.g. an object-store upload). */
  readonly deploymentId?: string;
  /** Git-backed targets only — see this interface's own header. */
  readonly commitSha?: string;
  /** Git-backed targets only — the branch actually published to. */
  readonly branch?: string;
  readonly triggeredBy: PublishTrigger;
}

/** Workspace-and-target-scoped read/write for the publish-history ledger. */
export interface PublishHistoryStore {
  /** Latest success or explicitly pending deploy per (kind, target, projectName), across the full workspace
   * ledger. At most 201 rows; the read service refuses over 200 rather than hiding destinations. */
  listDestinationHistory(input: { workspaceId: UUID }, options?: Record<string, never>): Promise<PublishHistoryEntry[]>;
  /** The single most recent recorded publish for `(workspaceId, target)`, or `null` if none has ever
   *  been recorded — what `deployment_get_static_publish_capabilities` surfaces as `lastPublish`. */
  getLast(input: { workspaceId: UUID; target: StaticPublishTargetId }): Promise<PublishHistoryEntry | null>;
  /** Every recorded publish for `workspaceId`, newest first, optionally narrowed to one `target` —
   *  what a future read-only history view would page through. `limit` defaults to
   *  `DEFAULT_PUBLISH_HISTORY_LIST_LIMIT` and is clamped to `MAX_PUBLISH_HISTORY_LIST_LIMIT`
   *  (`core/publish-history-list-limit.ts`) regardless of what a caller requests: this table is
   *  append-only and grows for the life of an install (`REVIEWED_INTEGER_ID_COLUMNS` in
   *  `db/migration/manifest.ts` reviews `publish_history.id` as `"unbounded"` for exactly this
   *  reason), so an unbounded `list` call is a real resource-exhaustion risk a workspace with years of
   *  publish history could actually trigger, not a hypothetical one. */
  list(input: { workspaceId: UUID; target?: StaticPublishTargetId; limit?: number }): Promise<PublishHistoryEntry[]>;
  /** Distinct workspace-scoped saved live URLs across the full ledger (t08). At most 201:
   * callers refuse an over-200-address set instead of silently losing older destinations. */
  listLiveUrls(input: { workspaceId: UUID }): Promise<string[]>;
  /** Appends a new row — an append-only ledger, never a replace-in-place. Named for what it is ever
   *  called with, not what it is capable of rejecting: an `ok: false` `StaticPublishOutcome` is never
   *  passed to it at all (the caller, `publish-run.ts`'s `toHistoryEntry`, decides that, not this
   *  port), so `recordSuccess` never means "the publish failed." */
  recordSuccess(input: { workspaceId: UUID; entry: PublishHistoryEntry }): Promise<void>;
}

/** Test double — append-only like the real table (a `Map<key, PublishHistoryEntry[]>`, not
 *  `Map<key, PublishHistoryEntry>`), so a test can actually assert "the second publish did not erase
 *  the first." Dies on process restart, same as any in-memory double; production always uses
 *  `SqlitePublishHistoryStore` instead (`server/deps.ts`), never this class. */
export class InMemoryPublishHistoryStore implements PublishHistoryStore {
  private readonly entriesByWorkspace = new Map<UUID, PublishHistoryEntry[]>();

  /** Full-ledger selection, matching SQL's kind-scoped grouped max(id). O(n) time, O(d) space for n runs/d destinations. */
  async listDestinationHistory(input: { workspaceId: UUID }, _options: Record<string, never> = {}): Promise<PublishHistoryEntry[]> {
    const latest = new Map<string, PublishHistoryEntry>();
    const rows = this.entriesByWorkspace.get(input.workspaceId) ?? [];
    for (let i = rows.length - 1; i >= 0; i -= 1) {
      const row = rows[i]!;
      const key = JSON.stringify([row.kind ?? "static", row.target, row.projectName]);
      if (isReplayableDestination({ row }) && !latest.has(key)) latest.set(key, row);
      if (latest.size > 200) break;
    }
    return [...latest.values()];
  }

  async getLast(input: { workspaceId: UUID; target: StaticPublishTargetId }): Promise<PublishHistoryEntry | null> {
    const rows = this.entriesByWorkspace.get(input.workspaceId) ?? [];
    for (let i = rows.length - 1; i >= 0; i -= 1) {
      if ((rows[i]!.kind ?? "static") === "static" && rows[i]!.target === input.target) return rows[i]!;
    }
    return null;
  }

  async list(input: { workspaceId: UUID; target?: StaticPublishTargetId; limit?: number }): Promise<PublishHistoryEntry[]> {
    const limit = resolvePublishHistoryListLimit(input.limit);
    const rows = this.entriesByWorkspace.get(input.workspaceId) ?? [];
    const matching = input.target === undefined ? rows : rows.filter((row) => row.target === input.target);
    // Newest-first: entries are appended oldest-to-newest, so reverse before slicing to `limit`.
    return matching.slice().reverse().slice(0, limit);
  }

  async listLiveUrls(input: { workspaceId: UUID }): Promise<string[]> {
    const urls = new Set<string>();
    for (const entry of this.entriesByWorkspace.get(input.workspaceId) ?? []) {
      urls.add(entry.url);
      if (urls.size > 200) break;
    }
    return [...urls].sort();
  }

  async recordSuccess(input: { workspaceId: UUID; entry: PublishHistoryEntry }): Promise<void> {
    const rows = this.entriesByWorkspace.get(input.workspaceId) ?? [];
    rows.push(input.entry);
    this.entriesByWorkspace.set(input.workspaceId, rows);
  }
}

/** Public replay contract; credentialId identifies a connection and never carries its secret. */
export interface StaticPublishDestination {
  readonly id: string;
  readonly kind: "static";
  readonly lastPublishedAt: string;
  readonly label: string;
  readonly url: string;
  readonly target: string;
  readonly projectName: string;
  readonly credentialId?: string;
  readonly configFields: Readonly<Record<string, string>>;
}

/** Only declared public config may enter history or a response. Credential fields are excluded even
 * if a descriptor accidentally also declares them as config. O(f*c) for f config/c credential fields.
 * @example publicPublishConfigFields({ descriptor, config: input.config }) */
export function publicPublishConfigFields(input: {
  descriptor: DeployTargetDescriptor;
  config: Readonly<Record<string, unknown>>;
}, _options: Record<string, never> = {}): Record<string, string> {
  const credential = input.descriptor.credential;
  return Object.fromEntries(input.descriptor.configFields
    .filter(field => !field.secret && field.name !== "target" && field.name !== "credentialId"
      && field.name !== "projectName" && field.name !== credential?.tokenField
      && !credential?.fields.some(candidate => candidate.name === field.name)
      && typeof input.config[field.name] === "string")
    .map(field => [field.name, input.config[field.name] as string]));
}

/** Read saved destinations without resolving credentials. Store failures propagate to the HTTP
 * boundary. Newest publish time first, independently of ledger insertion order.
 * One bounded ledger read, O(d*f*c + d log d) time, O(d*f) response space; d <= 200.
 * @example listStaticPublishDestinations({ workspaceId, historyStore, registry }) */
export async function listStaticPublishDestinations(input: {
  workspaceId: UUID;
  historyStore: PublishHistoryStore;
  registry: DeployTargetRegistry;
}, _options: Record<string, never> = {}): Promise<StaticPublishDestination[]> {
  const rows = await input.historyStore.listDestinationHistory({ workspaceId: input.workspaceId });
  if (rows.length > 200) throw new Error("publish destination limit exceeded (200)");
  return staticDestinations({ rows, registry: input.registry });
}

/** Descriptor-owned public static projection, shared by the static compatibility API and mixed list. */
function staticDestinations(input: { rows: readonly PublishHistoryEntry[]; registry: DeployTargetRegistry }): StaticPublishDestination[] {
  return input.rows.flatMap(row => {
    const target = input.registry.get(row.target);
    if ((row.kind ?? "static") !== "static" || !row.reachable || row.configFields === undefined || target === undefined) return [];
    return [{
      id: `static:${encodeURIComponent(row.target)}:${encodeURIComponent(row.projectName)}`,
      kind: "static" as const,
      lastPublishedAt: row.publishedAt,
      label: `${target.descriptor.label}: ${row.projectName}`,
      url: row.url,
      target: row.target,
      projectName: row.projectName,
      ...(row.credentialId !== undefined ? { credentialId: row.credentialId } : {}),
      configFields: publicPublishConfigFields({ descriptor: target.descriptor, config: row.configFields }),
    }];
  }).sort((a, b) => Date.parse(b.lastPublishedAt) - Date.parse(a.lastPublishedAt));
}

export type PublishDestination = StaticPublishDestination | {
  readonly id: string;
  readonly kind: "tovu-peer";
  readonly peerId: string;
  readonly label: string;
  readonly url: string;
  readonly lastPublishedAt: string;
} | {
  readonly id: string;
  readonly kind: "deploy";
  readonly status: "started" | "confirmed";
  readonly statusMessage?: string;
  readonly target: string;
  readonly label: string;
  readonly url: string;
  readonly lastPublishedAt: string;
  readonly linkedPeerId?: string;
};

/** One bounded ledger read, no credential resolution. Only caller-authorized saved peer summaries
 * may enter this projection; deleted peers never become destinations from stale history.
 * @returns Latest successful destinations and explicitly pending deploys, newest first; throws on the 200-destination cap.
 * @complexity O(d*p + d*f*c + d log d), d <= 200, p saved peers; no per-row I/O.
 * @example listPublishDestinations({ workspaceId, historyStore, registry, peers })
 */
export async function listPublishDestinations(input: {
  workspaceId: UUID;
  historyStore: PublishHistoryStore;
  registry: DeployTargetRegistry;
  peers: readonly Pick<PublishContentPeerSummary, "id" | "label" | "baseUrl">[];
}, _options: Record<string, never> = {}): Promise<PublishDestination[]> {
  const rows = await input.historyStore.listDestinationHistory({ workspaceId: input.workspaceId });
  if (rows.length > 200) throw new Error("publish destination limit exceeded (200)");
  const destinations: PublishDestination[] = staticDestinations({ rows, registry: input.registry });
  const peers = new Map(input.peers.map(peer => [peer.id, peer]));
  destinations.push(...rows.flatMap((row): PublishDestination[] => {
    if (!isConfirmedOrPending({ row })) return [];
    if (row.kind === "tovu-peer") {
      const peer = peers.get(row.target);
      return peer ? [{ id: `tovu-peer:${peer.id}`, kind: "tovu-peer", peerId: peer.id,
        label: peer.label, url: peer.baseUrl, lastPublishedAt: row.publishedAt }] : [];
    }
    if (row.kind === "deploy" && row.url !== "") {
      return [deployDestination({ row, peers: input.peers })];
    }
    return [];
  }));
  return destinations.sort((a, b) => Date.parse(b.lastPublishedAt) - Date.parse(a.lastPublishedAt));
}

/** Replay needs public static config or a peer/deploy identity, in addition to an eligible outcome. */
function isReplayableDestination({ row }: { row: PublishHistoryEntry }, _options: Record<string, never> = {}): boolean {
  return isConfirmedOrPending({ row }) && (row.kind === "tovu-peer" || row.kind === "deploy" || row.configFields !== undefined);
}

/** Ledger eligibility is shared by selection and projection: only deploys can be pending. */
function isConfirmedOrPending({ row }: { row: PublishHistoryEntry }, _options: Record<string, never> = {}): boolean {
  return row.reachable || (row.kind === "deploy" && row.status === "started");
}

/** A deploy's public status and optional link to a saved peer, without credential resolution. */
function deployDestination({ row, peers }: {
  row: PublishHistoryEntry;
  peers: readonly Pick<PublishContentPeerSummary, "id" | "label" | "baseUrl">[];
}, _options: Record<string, never> = {}): Extract<PublishDestination, { kind: "deploy" }> {
  const pendingDeploy = row.status === "started";
  // Normalized addresses match root URLs with or without a trailing slash, never by hostname alone.
  const peer = peers.find(candidate => candidate.baseUrl.replace(/\/+$/, "") === row.url.replace(/\/+$/, ""));
  return { id: `deploy:${encodeURIComponent(row.target)}:${encodeURIComponent(row.projectName)}`,
    kind: "deploy", target: row.target, label: row.projectName, url: row.url,
    // Acceptance alone never claims a live site, including rows written before this guard.
    status: pendingDeploy ? "started" : "confirmed",
    ...(pendingDeploy ? { statusMessage: "Deploy started, not confirmed" } : {}),
    lastPublishedAt: row.publishedAt, ...(peer ? { linkedPeerId: peer.id } : {}) };
}

import type { ToolFailureDiagnostic } from "#src/contracts/core/tool-failure-diagnostics";
import type { UUID } from "@jini-ai/core/primitives";

/**
 * @file Domain types for one-shot static-site publishing through a deploy target an Agent Plugin
 * contributes (`../deploy-targets/`).
 *
 * Purpose:
 * Deliberately separate from this directory's sibling `../types.ts`/`../ports.ts`
 * (`DeploymentProviderPort`/`DeploymentTargetRecord`) — that machinery promotes an EXISTING git
 * commit through a GitHub App (`content/agent-plugins/github/deployments/github.mjs`), continuous-deployment-shaped. This
 * feature does the opposite: it takes Tovu's own static export (`src/features/site-export`'s `exportSite`, bytes
 * this process just rendered, never a pre-existing commit) and hands the file set to a devops
 * `DeployTarget` — a one-shot "publish this exact file set" operation with no polling-run/webhook
 * lifecycle of its own. Two genuinely different problems that happen to share the word "deploy".
 *
 * How it relates to the project:
 * Target ids are OPEN strings (deploy plan T7): the set of targets, and each target's config
 * fields, come from the deploy-target registry at runtime, which validates them at every entry point
 * (`adapter.ts`'s `planStaticPublish`). Ids stay byte-identical to the historical provider ids:
 * sealed credentials and publish history rows are keyed by them.
 *
 * Architectural role:
 * Domain types only — no I/O.
 */

/** A deploy target id the registry knows (lowercase hyphenated). */
export type StaticPublishTargetId = string;

/**
 * One publish's target and its descriptor-declared config fields, all strings. `basePath` is
 * deliberately NOT a field — the target module derives it, which is what makes "export base path
 * doesn't match the publish target" structurally impossible rather than merely documented.
 */
export interface StaticPublishConfig {
  readonly target: StaticPublishTargetId;
  readonly [field: string]: string | undefined;
}

/** Every outcome this feature returns to a caller (admin route JSON, agent tool result) — never a
 *  `DeployFile`, never a token, never a raw upstream error body.
 *
 * THREE outcomes, not two — `ok` is `true | false | "partial"`, never merely a boolean. Spec
 * `custom-publish-provider-contract.md` §3a names the exact failure mode this third state exists to
 * prevent: uploading objects to a bucket does not, by itself, make them servable — a bucket is private
 * by default on every S3-compatible provider, so "the PUT calls all succeeded" and "a human can
 * actually load this site" are genuinely different claims. Folding "uploaded fine, but not reachable
 * yet" into `ok: true` would be a false "Published" success pointing at a URL that 404s; folding it
 * into `ok: false` would hide that the upload itself DID succeed (nothing needs re-uploading, only the
 * hosting/public-access step is missing — see `deployment_generate_bucket_hosting_setup`, spec §3a).
 * Neither existing branch is honest here, so this is a genuine third branch, not a reuse of either.
 *
 * `adapter.ts`'s `publishStaticSite` is the one place this is decided, from the SAME
 * `DeployPublishResult.status` field every target (not only s3-compatible) already returns — see that
 * function's own doc for why the check applies uniformly rather than being special-cased per target. */
export type StaticPublishOutcome =
  | {
      readonly ok: true;
      /** Saved connection used for this run; absent for environment credentials. */
      readonly credentialId?: UUID;
      readonly targetId: StaticPublishTargetId;
      readonly url: string;
      readonly status: string;
      readonly deploymentId?: string;
      /** The base path this publish's export was rewritten for — e.g. `/${repo}` for a host that
       *  serves the site under a repository subpath; absent for a host serving it at the root. Echoed back so a caller can show "published at /repo" without having to
       *  re-derive the same computation this module already did. */
      readonly basePath?: string;
      /** The host's own facts about this publish (`DeployPublishResult.providerMetadata`), e.g. the
       *  repository and commit a git-backed host wrote. Carried into publish history. */
      readonly providerMetadata?: Readonly<Record<string, unknown>>;
    }
  | {
      /** "Uploaded, not yet reachable" — see this type's own header. Every field below has the exact
       *  same meaning as the `ok: true` branch's namesake field; only the discriminant and `message`
       *  are new, so a caller migrating from a boolean-only reading of `ok` gets a compile error
       *  (an unhandled union member) rather than a silent misclassification. */
      readonly ok: "partial";
      readonly credentialId?: UUID;
      readonly targetId: StaticPublishTargetId;
      readonly url: string;
      readonly status: string;
      readonly message: string;
      readonly deploymentId?: string;
      readonly basePath?: string;
      readonly providerMetadata?: Readonly<Record<string, unknown>>;
    }
  | {
      readonly ok: false;
      readonly code: "INVALID_CONFIG" | "NO_CREDENTIALS_CONFIGURED" | "EXPORT_FAILED" | "PROVIDER_ERROR";
      readonly credentialSetup?: ToolFailureDiagnostic;
      readonly message: string;
    };

/**
 * Resolves the bearer token for one publish target, and separately answers whether one is even
 * configured. `credentials.ts`'s `createEnvPublishCredentialSource` is the env-var implementation;
 * `publish-credentials`'s DB-backed source (2026-08-15, ADR-058-pattern encrypted store) is the
 * second — both implement this same interface so no caller changes when the composition between them
 * changes.
 *
 * TWO separate methods, not one, on purpose (2026-08-15 split, Terra's design): {@link resolve}
 * is the ONLY one of the two that may decrypt/expose a real credential, and must never expose usable credentials to a status display or model. Authenticated provider inspection
 * may resolve server-side for read-only API calls; local readiness previews still use isConfigured.
 * {@link isConfigured} answers the read-only "would a publish work" question every preview/education
 * surface actually needs, without decrypting anything (the DB-backed source's `isConfigured` only
 * ever calls `describeCredential`-shaped reads — never `resolveForPublish`). Before this split, the
 * only method was `resolve()`, and the admin preview route called it just to read `.ok` off the
 * result — harmless while the only implementation was a plain `process.env` read, but it would have
 * meant a REAL decrypt on every preview once a DB-backed source existed.
 *
 * `resolve()`'s success ({@link ResolvedPublishCredentialSuccess}) is flat: `token` (the host
 * descriptor's `credential.tokenField`, e.g. the secret half of an access-key pair) plus every other
 * field that host's credential declares, under its own name. Core names none of them; the host's
 * deploy module reads what it needs.
 */
/** {@link PublishCredentialSource.resolve}'s success: `token` plus the host's other declared credential
 *  fields. `true` is in the index type only so `ok` itself fits it; every field is a string. */
export type ResolvedPublishCredentialSuccess = {
  readonly ok: true;
  readonly token: string;
  /** Saved row actually resolved, including default selection; absent for environment credentials. */
  readonly credentialId?: UUID;
} & Readonly<Record<string, string | true | undefined>>;

export interface PublishCredentialSource {
  /**
   * @param input.credentialId - OPTIONAL id of the saved connection the OPERATOR chose for this one
   *   publish (terra review 2026-09-20, finding 1 — Critical). When present, an implementation must
   *   resolve THAT connection or refuse: never the provider's current default, and never a fallback
   *   source. The silent "whichever row is `is_default` when the publish POST lands" resolution this
   *   parameter replaces is the defect itself — a publish fired while a "make this one the default"
   *   promotion was still in flight went to the PREVIOUS account. Absent means the caller genuinely
   *   has no chosen connection (the `deployment_execute_static_publish` agent tool, and any admin
   *   install whose credentials come from server env vars, which have no ids), and the established
   *   default lookup applies unchanged.
   *
   *   UNTRUSTED input: it arrives from an HTTP body. An implementation must scope its lookup to
   *   `workspaceId` and verify the row's own provider matches `target` before resolving anything —
   *   a request naming another workspace's credential id must refuse, not publish.
   */
  resolve(input: { workspaceId: UUID; target: StaticPublishTargetId; credentialId?: UUID }): Promise<
    ResolvedPublishCredentialSuccess | { readonly ok: false; readonly reason: string }
  >;
  /** Read-only, never decrypts. `reason` (when `configured` is `false`) is the same human-readable,
   *  non-secret guidance `resolve()`'s own `{ok:false}.reason` carries — safe to show in an admin UI
   *  or hand to an agent tool. */
  isConfigured(input: { workspaceId: UUID; target: StaticPublishTargetId }): Promise<
    { readonly configured: true } | { readonly configured: false; readonly reason: string }
  >;
}

import type { ISODateTime, UUID } from "@jini-ai/core/primitives";

/**
 * @file GitHub provider input records: in-memory contracts, not persisted records.
 * Releases name existing artifacts for promotion; the provider does not build those artifacts.
 */

/** Open string, not a closed union — see `features/plugins/lipay/ports.ts`'s `PaymentProviderId`
 * for why (a closed union makes every new provider a core edit). `"github"` is the only value with
 * a real adapter this pass (`content/agent-plugins/github/deployments/github.mjs`). */
export type DeploymentProviderId = string;


/** One provider connection, scoped to a single environment. `config` carries non-secret provider
 * config only (repo owner/name, GitHub environment name); the adapter receives credentials
 * separately through DeploymentProviderContext. This contract has no table writer. */
export interface DeploymentTargetRecord {
  readonly workspaceId: UUID;
  readonly id: UUID;
  readonly environmentId: UUID;
  readonly providerId: DeploymentProviderId;
  readonly label: string;
  readonly config: Readonly<Record<string, unknown>>;
  readonly enabled: boolean;
  readonly createdAtIso: ISODateTime;
  readonly version: number;
}

/** What a release promotes. `git-revision` is the only kind a first-party adapter accepts this
 * adapter — its role is to promote a commit that already exists. `external-artifact` is declared for a future non-GitHub provider (e.g. one
 * that accepts a pre-built tarball URL) and is deliberately rejected by `content/agent-plugins/github/deployments/github.mjs`. */
export type ReleaseSource =
  | { readonly kind: "git-revision"; readonly repoUrl: string; readonly commitSha: string }
  | { readonly kind: "external-artifact"; readonly uri: string; readonly checksum?: string };

/** An immutable, workspace-scoped artifact IDENTITY — "this is the thing that gets promoted". It
 * records a reference to an artifact that already exists; it does not construct one. */
export interface ReleaseRecord {
  readonly workspaceId: UUID;
  readonly id: UUID;
  readonly label: string;
  readonly source: ReleaseSource;
  readonly createdByPrincipalId: UUID;
  readonly createdAtIso: ISODateTime;
  readonly version: number;
}

/** Tovu's own normalized run status. Providers report a wider, provider-specific state (GitHub's
 * real deployment-status enum has seven values — see `content/agent-plugins/github/deployments/github.mjs`'s
 * `mapGitHubDeploymentStatus`) and every adapter narrows it down to this closed set. */
export type DeploymentRunStatus = "queued" | "running" | "succeeded" | "failed" | "cancelled";

import { nowIso, type Clock } from "@jini-ai/core/primitives";

import { isTrashed, type PostKind, type PostRecord, type PostRepoPort } from "../post/index.js";
// Not from the barrel: it re-exports a fixed list, and this kind is not part of the Post API.
import { EMAIL_TEMPLATE_KIND } from "../post/post.js";
import { PageConcurrentEditError, type PagesHtmlDocumentStoreFactory } from "../pages/index.js";
import {
  emailTemplateSkeleton,
  parseFieldDeclarations,
  readTemplateDeclarations,
  renderEmailForSend,
  renderEmailPreview,
  undeclaredFieldsIn,
  type EmailFieldValues,
  type EmailTemplateField,
  type SendableEmail,
} from "./render.js";

/**
 * @file The ONE set of email-template operations — create, edit, list, get, preview and the send
 * render — that both the admin routes (`server/inbound/admin-http/routes/email-templates/`) and the
 * assistant tools (`tool-registrations.ts`) call. Permission checks stay with those two callers, the
 * way the Pages routes and `pages_*` tools each check before reaching the shared store.
 *
 * Storage is the Pages storage, not a parallel system: a template is a `posts` row of kind
 * {@link EMAIL_TEMPLATE_KIND}, written in `"html"` format by the same `PagesHtmlDocumentStore` a
 * bespoke Page is (compare-and-set writes, revision ledger, trash). It is born like a Page too — a
 * plain row, then `ensureHtmlFormat(seed)` — so that store stays the only writer of html bodies.
 */

/** Bounds a template's name; the body is bounded by the routes' JSON body-size limit. */
export const EMAIL_TEMPLATE_NAME_MAX = 200;

export class EmailTemplateNotFoundError extends Error {}
/** The caller's input is malformed; the message says how to fix it. */
export class EmailTemplateInputError extends Error {}
/** `expectedVersion` no longer matches, or another writer landed mid-write. Re-read and retry. */
export class EmailTemplateVersionConflictError extends Error {}

export interface EmailTemplateDeps {
  workspaceId: string;
  postRepo: PostRepoPort;
  pagesHtmlStore: PagesHtmlDocumentStoreFactory;
  clock: Clock;
  idGen: { newId(): string };
}

export interface EmailTemplateSummary {
  id: string;
  name: string;
  subject: string;
  fields: EmailTemplateField[];
  version: number;
  updatedAt: string;
}

export interface EmailTemplateDetail extends EmailTemplateSummary {
  html: string;
  /** `{{field}}`s the HTML uses that `<meta name="email-fields">` does not declare. */
  undeclaredFields: string[];
}

export interface EmailTemplatePreview {
  subject: string;
  html: string;
  missingFields: string[];
  undeclaredFields: string[];
  /** `"admin"` keeps scripts (render in the sandboxed Pages preview iframe); `"sent"` is the static email. */
  mode: "admin" | "sent";
  scriptsStripped: boolean;
  /** The plain-text alternative, `"sent"` mode only. */
  text?: string;
}

/** A template row: our kind, html format, not in the Trash. */
function isTemplateRow(row: PostRecord | null): row is PostRecord & { bodyHtml: string } {
  return row !== null && (row.kind as string) === EMAIL_TEMPLATE_KIND && row.bodyFormat === "html" && row.bodyHtml !== null && !isTrashed(row);
}

async function loadTemplate({ deps, id }: { deps: EmailTemplateDeps; id: string }, _options: Record<string, never> = {}): Promise<PostRecord & { bodyHtml: string }> {
  const row = await deps.postRepo.findById({ workspaceId: deps.workspaceId, id });
  if (!isTemplateRow(row)) throw new EmailTemplateNotFoundError(`email template '${id}' was not found`);
  return row;
}

function toSummary(row: PostRecord & { bodyHtml: string }, _options: Record<string, never> = {}): EmailTemplateSummary {
  const declarations = readTemplateDeclarations({ html: row.bodyHtml });
  return { id: row.id, name: row.title, subject: declarations.subject, fields: declarations.fields, version: row.version, updatedAt: row.updatedAt };
}

function toDetail(row: PostRecord & { bodyHtml: string }, _options: Record<string, never> = {}): EmailTemplateDetail {
  const summary = toSummary(row);
  return { ...summary, html: row.bodyHtml, undeclaredFields: undeclaredFieldsIn({ html: row.bodyHtml, declarations: summary }) };
}

/** A required, trimmed, bounded string. */
export function requireText({ value, key, max }: { value: unknown; key: string; max: number }, _optional: Record<string, never> = {}): string {
  const text = typeof value === "string" ? value.trim() : "";
  if (!text) throw new EmailTemplateInputError(`${key} is required and must be a non-empty string.`);
  if (text.length > max) throw new EmailTemplateInputError(`${key} must be at most ${max} characters.`);
  return text;
}

/** An optional string; `undefined` when absent. */
function optionalString({ value, key }: { value: unknown; key: string }, _options: Record<string, never> = {}): string | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== "string") throw new EmailTemplateInputError(`${key} must be a string.`);
  return value;
}

/** Field values: strings, numbers and booleans (stringified); anything else is refused. */
export function readFieldValues({ value }: { value: unknown }, _optional: Record<string, never> = {}): Record<string, string> {
  if (value === undefined) return {};
  if (value === null || typeof value !== "object" || Array.isArray(value)) throw new EmailTemplateInputError("values must be an object of field name to text.");
  const out: Record<string, string> = {};
  for (const [name, raw] of Object.entries(value)) {
    if (!["string", "number", "boolean"].includes(typeof raw)) throw new EmailTemplateInputError(`values.${name} must be text, a number or a boolean.`);
    out[name] = String(raw);
  }
  return out;
}

/** Field declarations from either a list of names / `{name, sample}` objects, or the meta `content` string form. */
function readFieldsInput({ value }: { value: unknown }, _options: Record<string, never> = {}): EmailTemplateField[] {
  if (value === undefined) return [];
  if (typeof value === "string") return parseFieldDeclarations({ content: value });
  if (!Array.isArray(value)) throw new EmailTemplateInputError("fields must be a list of field names.");
  const entries = value.map((entry) => (typeof entry === "string" ? entry : formatFieldObject({ entry: entry })));
  return parseFieldDeclarations({ content: entries.join(",") });
}

function formatFieldObject({ entry }: { entry: unknown }, _options: Record<string, never> = {}): string {
  const record = (entry ?? {}) as { name?: unknown; sample?: unknown };
  if (typeof record.name !== "string") throw new EmailTemplateInputError("each field must be a name or {name, sample}.");
  if (record.name.includes(",") || record.name.includes("=")) throw new EmailTemplateInputError("field names cannot contain commas or equals signs.");
  if (typeof record.sample === "string" && record.sample.includes(",")) throw new EmailTemplateInputError("field samples cannot contain commas.");
  return typeof record.sample === "string" ? `${record.name}=${record.sample}` : record.name;
}

function readExpectedVersion({ value }: { value: unknown }, _options: Record<string, never> = {}): number | undefined {
  if (value === undefined) return undefined;
  if (!Number.isInteger(value) || (value as number) < 1) throw new EmailTemplateInputError("expectedVersion must be the positive integer version a read returned.");
  return value as number;
}

/** A fresh, `doc`-format template row for `ensureHtmlFormat` to convert, as a new Page is. */
function newTemplateRow({ deps, name }: { deps: EmailTemplateDeps; name: string }, _options: Record<string, never> = {}): PostRecord {
  const id = deps.idGen.newId();
  return {
    id,
    workspaceId: deps.workspaceId,
    title: name,
    // The colon fails `SLUG_FORMAT_PATTERN`, so no Post or Page can ever be given this slug: the row
    // holds a place in the shared unique index without taking a name from the public URL space.
    slug: `email-template:${id}`,
    bodyJson: { type: "doc", content: [] },
    // Forever: `updatePost` refuses this kind, and it is the only path that changes status.
    status: "draft",
    // Not a PostKind on purpose; see EMAIL_TEMPLATE_KIND's own doc.
    kind: EMAIL_TEMPLATE_KIND,
    bodyFormat: "doc",
    bodyHtml: null,
    updatedAt: nowIso({ clock: deps.clock }),
    version: 1,
  };
}

/**
 * Creates a template: a plain row, then the Pages store's `ensureHtmlFormat` births its HTML body.
 * @param required.input - `{ name, html?, subject?, fields? }`; with no `html`, a starter email is
 *   built from `subject` (default: the name) and `fields`.
 * @throws {EmailTemplateInputError} For a missing name or malformed fields/html.
 */
export async function createEmailTemplate(
  { deps, input, actorId }: { deps: EmailTemplateDeps; input: Record<string, unknown>; actorId: string },
  _optional: Record<string, never> = {},
): Promise<EmailTemplateDetail> {
  const name = requireText({ value: input.name, key: "name", max: EMAIL_TEMPLATE_NAME_MAX });
  const html = optionalString({ value: input.html, key: "html" });
  const subject = optionalString({ value: input.subject, key: "subject" }) ?? name;
  const seed = html ?? emailTemplateSkeleton({ subject, fields: readFieldsInput({ value: input.fields }) });
  const row = newTemplateRow({ deps: deps, name: name });
  // Both adapters join the same kernel transaction, so conversion failure leaves no hidden doc row.
  return deps.postRepo.transaction(async () => {
    await deps.postRepo.save(row);
    await deps.pagesHtmlStore({ workspaceId: deps.workspaceId, postId: row.id, actorId }, { allowedKinds: new Set([EMAIL_TEMPLATE_KIND]) }).ensureHtmlFormat(seed);
    return toDetail(await loadTemplate({ deps: deps, id: row.id }));
  });
}

/**
 * Replaces a template's whole HTML through the Pages store's compare-and-set write.
 * @param required.input - `{ id, html, expectedVersion? }`; a stated `expectedVersion` must be the
 *   version the write is actually conditioned on, or nothing is written.
 * @throws {EmailTemplateNotFoundError} When `id` is not a live template.
 * @throws {EmailTemplateVersionConflictError} On a stale `expectedVersion` or a concurrent write.
 */
export async function editEmailTemplate(
  { deps, input, actorId }: { deps: EmailTemplateDeps; input: Record<string, unknown>; actorId: string },
  _optional: Record<string, never> = {},
): Promise<EmailTemplateDetail> {
  const id = requireText({ value: input.id, key: "id", max: EMAIL_TEMPLATE_NAME_MAX });
  const html = requireText({ value: input.html, key: "html", max: Number.MAX_SAFE_INTEGER });
  const expectedVersion = readExpectedVersion({ value: input.expectedVersion });
  await loadTemplate({ deps: deps, id: id });
  const store = deps.pagesHtmlStore({ workspaceId: deps.workspaceId, postId: id, actorId }, { allowedKinds: new Set([EMAIL_TEMPLATE_KIND]) });
  await store.read();
  const basis = store.capturedVersion();
  if (expectedVersion !== undefined && expectedVersion !== basis) {
    throw new EmailTemplateVersionConflictError(`email template '${id}' is at version ${basis}, not ${expectedVersion} — re-read it and retry`);
  }
  try {
    await store.write(html);
  } catch (err) {
    if (err instanceof PageConcurrentEditError) throw new EmailTemplateVersionConflictError(`email template '${id}' was edited elsewhere — re-read it and retry`);
    throw err;
  }
  return toDetail(await loadTemplate({ deps: deps, id: id }));
}

/**
 * Renames a template: only the row's title changes, through the post repo's compare-and-set write,
 * so the HTML body and its revision ledger are untouched. Added for the admin Templates list
 * (2026-10-22); the HTML store has no title of its own, which is why this is not a store write.
 * @param required.input - `{ id, name, expectedVersion? }`.
 * @throws {EmailTemplateNotFoundError} When `id` is not a live template.
 * @throws {EmailTemplateVersionConflictError} On a stale `expectedVersion` or a concurrent write.
 */
export async function renameEmailTemplate(
  { deps, input }: { deps: EmailTemplateDeps; input: Record<string, unknown> },
  _optional: Record<string, never> = {},
): Promise<EmailTemplateDetail> {
  const id = requireText({ value: input.id, key: "id", max: EMAIL_TEMPLATE_NAME_MAX });
  const name = requireText({ value: input.name, key: "name", max: EMAIL_TEMPLATE_NAME_MAX });
  const expectedVersion = readExpectedVersion({ value: input.expectedVersion });
  const row = await loadTemplate({ deps: deps, id: id });
  if (expectedVersion !== undefined && expectedVersion !== row.version) {
    throw new EmailTemplateVersionConflictError(`email template '${id}' is at version ${row.version}, not ${expectedVersion} — re-read it and retry`);
  }
  const record = { ...row, title: name, version: row.version + 1, updatedAt: nowIso({ clock: deps.clock }) };
  const { applied } = await deps.postRepo.saveIfVersion({ record, ifVersion: row.version });
  if (!applied) throw new EmailTemplateVersionConflictError(`email template '${id}' was edited elsewhere — re-read it and retry`);
  return toDetail(await loadTemplate({ deps: deps, id: id }));
}

/** Every live template in the workspace, most recently updated first. */
export async function listEmailTemplates({ deps, input = {} }: { deps: EmailTemplateDeps; input?: { limit?: unknown; cursor?: unknown } }, _optional: Record<string, never> = {}): Promise<{ templates: EmailTemplateSummary[]; nextCursor?: string }> {
  const limit = templatePageLimit({ value: input.limit });
  const before = readTemplateCursor({ value: input.cursor });
  if (!deps.postRepo.listHtmlByKind) throw new Error("Template listing is unavailable.");
  const rows = await deps.postRepo.listHtmlByKind({ workspaceId: deps.workspaceId, kind: EMAIL_TEMPLATE_KIND, limit: limit + 1, ...(before ? { before } : {}) });
  const page = rows.slice(0, limit).filter(isTemplateRow);
  const last = page.at(-1);
  const nextCursor = rows.length > limit && last ? Buffer.from(JSON.stringify({ updatedAt: last.updatedAt, id: last.id })).toString("base64url") : undefined;
  return { templates: page.map(row => toSummary(row)), ...(nextCursor ? { nextCursor } : {}) };
}

/** Bounded list size, shared by the route and tool inputs. */
function templatePageLimit({ value }: { value: unknown }, _options = {}): number {
  const limit = value === undefined ? 25 : Number(value);
  if (!Number.isInteger(limit) || limit < 1 || limit > 100) throw new EmailTemplateInputError("limit must be a whole number from 1 to 100.");
  return limit;
}

/** Only a timestamp/id pair from this list is accepted as a continuation. */
function readTemplateCursor({ value }: { value: unknown }, _options = {}): { updatedAt: string; id: string } | undefined {
  if (value === undefined) return undefined;
  try {
    const parsed = JSON.parse(Buffer.from(String(value), "base64url").toString()) as { updatedAt?: unknown; id?: unknown };
    if (typeof parsed.updatedAt === "string" && typeof parsed.id === "string") return { updatedAt: parsed.updatedAt, id: parsed.id };
  } catch { /* The same typed refusal covers malformed and structurally invalid tokens. */ }
  throw new EmailTemplateInputError("cursor must be a nextCursor returned by email_template_list.");
}

/** One template with its HTML; `version` is the basis an edit states back as `expectedVersion`. */
export async function getEmailTemplate({ deps, id }: { deps: EmailTemplateDeps; id: string }, _optional: Record<string, never> = {}): Promise<EmailTemplateDetail> {
  return toDetail(await loadTemplate({ deps: deps, id: id }));
}

/** The HTML a preview renders: a saved template's, or unsaved HTML straight from the editor. */
async function previewSource(deps: EmailTemplateDeps, input: Record<string, unknown>): Promise<string> {
  if (input.html !== undefined) return requireText({ value: input.html, key: "html", max: Number.MAX_SAFE_INTEGER });
  return (await loadTemplate({ deps: deps, id: requireText({ value: input.id, key: "id", max: EMAIL_TEMPLATE_NAME_MAX }) })).bodyHtml;
}

function readMode({ value }: { value: unknown }, _options: Record<string, never> = {}): "admin" | "sent" {
  if (value === undefined || value === "admin") return "admin";
  if (value === "sent") return "sent";
  throw new EmailTemplateInputError('mode must be "admin" or "sent".');
}

/**
 * Renders a template with `{{field}}` values for the live preview. `"admin"` mode fills declared
 * samples for missing values and keeps scripts (the Pages preview iframe sandboxes them);
 * `"sent"` mode is exactly {@link renderEmailTemplateForSend}'s output, samples unused.
 * @param required.input - `{ id } | { html }`, plus `values?` and `mode?`.
 */
export async function previewEmailTemplate(
  { deps, input }: { deps: EmailTemplateDeps; input: Record<string, unknown> },
  _optional: Record<string, never> = {},
): Promise<EmailTemplatePreview> {
  const mode = readMode({ value: input.mode });
  const values = readFieldValues({ value: input.values });
  const html = await previewSource(deps, input);
  const undeclaredFields = undeclaredFieldsIn({ html, declarations: readTemplateDeclarations({ html }) });
  if (mode === "sent") {
    const sent = renderEmailForSend({ html, values });
    return { ...sent, undeclaredFields, mode, scriptsStripped: true };
  }
  return { ...renderEmailPreview({ html, values }), undeclaredFields, mode, scriptsStripped: false };
}

/**
 * The send-path operation: a saved template + values -> the `subject`/`html`/`text` an
 * `OutboundEmail` carries (static HTML; see `render.ts`'s `renderEmailForSend`). It sends nothing;
 * a mail send path spreads the result into its message alongside `to`/`from`.
 * @param required.values - Field values; a field with none renders empty and is listed in `missingFields`.
 */
export async function renderEmailTemplateForSend(
  { deps, id, values }: { deps: EmailTemplateDeps; id: string; values: EmailFieldValues },
  _optional: Record<string, never> = {},
): Promise<SendableEmail> {
  return renderEmailForSend({ html: (await loadTemplate({ deps: deps, id: id })).bodyHtml, values });
}

// Generic, Jini candidate: tracked in .cloud-coord/round2-progress.md#jini-extraction-backlog.
import { parse, serialize, type DefaultTreeAdapterMap } from "parse5";
import { htmlToText, stripActiveHtml } from "@jini-ai/platform/web";

/**
 * @file The pure half of email templates: `{{field}}` fill-ins, the template's own declarations
 * (subject and fields, read out of its HTML), and the two renders — the admin PREVIEW, which keeps
 * the template's scripts because it is shown in the Pages preview iframe's sandbox, and the SEND
 * render, which is static HTML because mail clients strip script anyway and a message that relied
 * on it would arrive broken.
 *
 * Everything a template declares lives in its HTML, not in extra columns: a template is an
 * `"html"`-format row in the Pages store (see `operations.ts`), and that store's single body is the
 * one source of truth an agent edits with the same full-document writes it uses for a Page.
 *
 * - Subject: the document's `<title>` (it may itself contain `{{field}}`s).
 * - Fields: `<meta name="email-fields" content="name=Ada, orderId">` — comma-separated names, each
 *   optionally `=sample` (the value a preview shows when the caller gives none).
 */

type ParentNode = DefaultTreeAdapterMap["parentNode"];
type ChildNode = DefaultTreeAdapterMap["childNode"];
type Element = DefaultTreeAdapterMap["element"];

/** The `<meta name>` a template declares its fill-in fields with. */
export const EMAIL_FIELDS_META_NAME = "email-fields";

/** `{{ name }}` — a field name is an identifier, optionally dotted or dashed. */
const PLACEHOLDER = /\{\{\s*([A-Za-z_][A-Za-z0-9_.-]*)\s*\}\}/g;
const FIELD_NAME = /^[A-Za-z_][A-Za-z0-9_.-]*$/;
const HTML_NAMESPACE = "http://www.w3.org/1999/xhtml";

/** Tags a sent email never carries: embedded documents and plugins, on top of `stripActiveHtml`'s. */
const SEND_STRIPPED_TAGS = new Set(["iframe", "object", "embed", "frame", "frameset", "applet", "base", "form", "link"]);
/** Script-bearing URL schemes; tested after removing the whitespace/control characters a browser ignores. */
const ACTIVE_URL = /^(?:javascript|vbscript):/i;

export interface EmailTemplateField {
  name: string;
  /** Shown by the preview when the caller gives no value for this field. */
  sample?: string;
}

export interface EmailTemplateDeclarations {
  /** The raw `<title>` text, placeholders unfilled; `""` when the template has none. */
  subject: string;
  fields: EmailTemplateField[];
}

export type EmailFieldValues = Readonly<Record<string, string>>;

export interface FilledText {
  text: string;
  /** Placeholders the values did not cover, in first-use order; each was rendered empty. */
  missingFields: string[];
}

/** The `{{field}}` names a string uses, de-duplicated in first-use order. */
export function placeholdersIn({ text }: { text: string }, _optional: Record<string, never> = {}): string[] {
  // PLACEHOLDER requires this capture; narrow it explicitly because indexed reads may be undefined.
  const names = [...text.matchAll(PLACEHOLDER)].map((match) => match[1]).filter((name): name is string => name !== undefined);
  return [...new Set(names)];
}

/** Escapes a value for HTML text AND quoted-attribute context. */
export function escapeHtml({ value }: { value: string }, _optional: Record<string, never> = {}): string {
  return value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

/**
 * Replaces every `{{field}}` with its value. An unknown field renders empty — never the literal
 * braces a recipient would see — and is reported so the caller can refuse or warn.
 * @param required.escape - Applied to every value: {@link escapeHtml} for HTML, identity for a subject.
 * @complexity O(n) in the text length.
 */
export function fillPlaceholders(
  { text, values, escape }: { text: string; values: EmailFieldValues; escape: (value: string) => string },
  _optional: Record<string, never> = {},
): FilledText {
  const missing = new Set<string>();
  const filled = text.replace(PLACEHOLDER, (_match, name: string) => {
    if (!Object.hasOwn(values, name)) {
      missing.add(name);
      return "";
    }
    // Own keys contain strings by contract; the default also makes the indexed read explicit.
    return escape(values[name] ?? "");
  });
  return { text: filled, missingFields: [...missing] };
}

/** One `name` or `name=sample` entry; `null` for a malformed name, which is ignored. */
function parseFieldEntry({ entry }: { entry: string }, _options: Record<string, never> = {}): EmailTemplateField | null {
  const separator = entry.indexOf("=");
  const name = (separator === -1 ? entry : entry.slice(0, separator)).trim();
  if (!FIELD_NAME.test(name)) return null;
  if (separator === -1) return { name };
  return { name, sample: entry.slice(separator + 1).trim() };
}

/** The declared fields from a `content` attribute, first declaration of a name winning. */
export function parseFieldDeclarations({ content }: { content: string }, _optional: Record<string, never> = {}): EmailTemplateField[] {
  const byName = new Map<string, EmailTemplateField>();
  for (const entry of content.split(",")) {
    const field = parseFieldEntry({ entry: entry });
    if (field && !byName.has(field.name)) byName.set(field.name, field);
  }
  return [...byName.values()];
}

/** Writes a field list back into the `content` form {@link parseFieldDeclarations} reads. */
export function formatFieldDeclarations({ fields }: { fields: readonly EmailTemplateField[] }, _optional: Record<string, never> = {}): string {
  return fields.map((field) => (field.sample === undefined ? field.name : `${field.name}=${field.sample}`)).join(", ");
}

function isElement(node: ChildNode | ParentNode): node is Element {
  return "tagName" in node;
}

function attribute({ element, name }: { element: Element; name: string }, _options: Record<string, never> = {}): string | undefined {
  return element.attrs.find((attr) => attr.name === name)?.value;
}

/** Every element under `root`, in document order (so "the first `<title>`" means the first one written). */
function* elementsIn(root: ParentNode, _options: Record<string, never> = {}): Generator<Element> {
  const pending: ParentNode[] = [root];
  while (pending.length > 0) {
    const node = pending.pop();
    // Array length checks do not narrow pop() or indexed reads under the desktop config.
    if (node === undefined) continue;
    if (isElement(node)) yield node;
    queueChildParents({ node, pending });
  }
}

/** Reverse insertion preserves document order on the traversal's stack. */
function queueChildParents({ node, pending }: { node: ParentNode; pending: ParentNode[] }, _options = {}): void {
  for (let i = node.childNodes.length - 1; i >= 0; i--) {
    const child = node.childNodes[i];
    if (child !== undefined && "childNodes" in child) pending.push(child);
  }
}

function textOf(element: Element, _options: Record<string, never> = {}): string {
  return element.childNodes.map((child) => ("value" in child && child.nodeName === "#text" ? child.value : "")).join("");
}

function isFieldsMeta(element: Element, _options: Record<string, never> = {}): boolean {
  return element.tagName === "meta" && attribute({ element: element, name: "name" })?.toLowerCase() === EMAIL_FIELDS_META_NAME;
}

/**
 * Reads a template's subject (`<title>`) and declared fields (`<meta name="email-fields">`).
 * @complexity O(nodes).
 */
export function readTemplateDeclarations({ html }: { html: string }, _optional: Record<string, never> = {}): EmailTemplateDeclarations {
  let subject: string | undefined;
  let fields: EmailTemplateField[] = [];
  let fieldsDeclared = false;
  for (const element of elementsIn(parse(html))) {
    // HTML namespace only: an inline `<svg><title>` is an image's tooltip, not the subject.
    if (element.tagName === "title" && element.namespaceURI === HTML_NAMESPACE && subject === undefined) subject = textOf(element).trim();
    if (isFieldsMeta(element) && !fieldsDeclared) {
      fieldsDeclared = true;
      fields = parseFieldDeclarations({ content: attribute({ element: element, name: "content" }) ?? "" });
    }
  }
  return { subject: subject ?? "", fields };
}

/** Placeholders used in the HTML (subject included) that the template never declared. */
export function undeclaredFieldsIn({ html, declarations }: { html: string; declarations: EmailTemplateDeclarations }, _optional: Record<string, never> = {}): string[] {
  const declared = new Set(declarations.fields.map((field) => field.name));
  return placeholdersIn({ text: html }).filter((name) => !declared.has(name));
}

/** True when an attribute value would run script once a browser normalizes it as a URL. Tested on
 * every attribute, not only `href`/`src`, the same breadth `stripActiveHtml` applies. */
function isActiveUrl({ value }: { value: string }, _options: Record<string, never> = {}): boolean {
  // Browsers drop ASCII tab/newline anywhere in a URL and leading C0 controls/space, so
  // `java\nscript:` is still script; `stripActiveHtml`'s own test only trims leading whitespace.
  // eslint-disable-next-line no-control-regex
  const normalized = value.replace(/[\u0000- ]/g, "");
  return ACTIVE_URL.test(normalized) || (/^data:/i.test(normalized) && !/^data:image\/[^;,]+[;,]/i.test(normalized));
}

/** Static mail excludes navigation instructions, form submissions and external stylesheets. */
function stripMailElement({ child }: { child: ChildNode }, _optional: Record<string, never> = {}): boolean {
  if (!isElement(child)) return false;
  if (SEND_STRIPPED_TAGS.has(child.tagName) || isFieldsMeta(child)) return true;
  return child.tagName === "meta" && attribute({ element: child, name: "http-equiv" }) !== undefined;
}

/** Second, email-specific pass after `stripActiveHtml`: embeds, obfuscated script URLs, the fields meta. */
function stripForMail(root: ParentNode, _options: Record<string, never> = {}): void {
  for (const node of elementsIn(root)) {
    node.childNodes = node.childNodes.filter((child) => !stripMailElement({ child }));
    node.attrs = node.attrs.filter((attr) => !isActiveUrl({ value: attr.value }));
  }
}

/**
 * The static HTML a mail client receives: `<script>`/`<noscript>`/`<template>`, comments, inline
 * `on*` handlers and `javascript:` URLs removed (the shared `stripActiveHtml` policy), then
 * `<iframe>`/`<object>`/`<embed>` (and their legacy kin), obfuscated script URLs and the template's
 * own field declarations. Navigation/form/link elements and non-image data URLs are removed.
 * Inline styles and classes survive: email layout depends on them.
 *
 * Known cost: comments are removed, so Outlook `<!--[if mso]>` conditional blocks do not survive.
 * @complexity O(nodes), two parses.
 */
export function sanitizeEmailHtml({ html }: { html: string }, _optional: Record<string, never> = {}): string {
  const document = parse(stripActiveHtml({ html }));
  stripForMail(document);
  return serialize(document);
}

/** A visible ` (url)` after a link whose text is not already its URL, so the text part keeps links. */
function annotateLinks(root: ParentNode, _options: Record<string, never> = {}): void {
  for (const element of elementsIn(root)) {
    const href = element.tagName === "a" ? attribute({ element: element, name: "href" })?.trim() : undefined;
    if (!href || !/^(?:https?:|mailto:)/i.test(href) || textOf(element).trim() === href) continue;
    element.childNodes.push({ nodeName: "#text", value: ` (${href.replace(/^mailto:/i, "")})`, parentNode: element } as ChildNode);
  }
}

/**
 * The plain-text alternative: the shared `htmlToText` (one line per block; head, scripts and styles
 * omitted), with each link's URL written after its text so a text-only reader can still follow it.
 * @complexity O(nodes).
 */
export function emailHtmlToText({ html }: { html: string }, _optional: Record<string, never> = {}): string {
  const document = parse(html);
  annotateLinks(document);
  return htmlToText({ html: serialize(document) });
}

/** A subject is one header line: fill raw (it is not HTML) and fold any line break a value carried. */
function renderSubject({ subject, values }: { subject: string; values: EmailFieldValues }, _options: Record<string, never> = {}): FilledText {
  const filled = fillPlaceholders({ text: subject, values, escape: (value) => value });
  return { text: filled.text.replace(/[\r\n]+/g, " ").trim(), missingFields: filled.missingFields };
}

export interface RenderedEmail {
  subject: string;
  html: string;
  /** Placeholders no value covered, subject and body together; each rendered empty. */
  missingFields: string[];
}

function renderWith({ html, values }: { html: string; values: EmailFieldValues }, _options: Record<string, never> = {}): RenderedEmail {
  const declarations = readTemplateDeclarations({ html });
  const subject = renderSubject({ subject: declarations.subject, values: values });
  const body = fillPlaceholders({ text: html, values, escape: (value) => escapeHtml({ value }) });
  return { subject: subject.text, html: body.text, missingFields: [...new Set([...subject.missingFields, ...body.missingFields])] };
}

/** The values a preview renders with: declared samples, overridden by whatever the caller gave. */
export function previewValues(
  { declarations, values }: { declarations: EmailTemplateDeclarations; values: EmailFieldValues },
  _optional: Record<string, never> = {},
): Record<string, string> {
  const samples = declarations.fields.flatMap((field) => (field.sample === undefined ? [] : [[field.name, field.sample] as const]));
  return { ...Object.fromEntries(samples), ...values };
}

/**
 * The admin preview. Scripts are KEPT — the preview is the Pages preview iframe, sandboxed without
 * `allow-same-origin`, so they run in an opaque origin — and `scriptsStripped: false` says so.
 * @complexity O(n) in the template length.
 */
export function renderEmailPreview({ html, values }: { html: string; values: EmailFieldValues }, _optional: Record<string, never> = {}): RenderedEmail {
  const declarations = readTemplateDeclarations({ html });
  return renderWith({ html: html, values: previewValues({ declarations, values }) });
}

export interface SendableEmail extends RenderedEmail {
  /** The plain-text alternative, derived from the sanitized HTML. */
  text: string;
}

/**
 * Template + values -> the `subject`/`html`/`text` an `OutboundEmail` carries. Values are filled
 * BEFORE sanitizing, so a value that smuggles a `javascript:` URL into an `href="{{url}}"` is
 * removed with everything else. Samples are never used: a sent email shows only real values.
 * @complexity O(n) in the template length.
 */
export function renderEmailForSend({ html, values }: { html: string; values: EmailFieldValues }, _optional: Record<string, never> = {}): SendableEmail {
  const rendered = renderWith({ html: html, values: values });
  const safeHtml = sanitizeEmailHtml({ html: rendered.html });
  return { subject: rendered.subject, html: safeHtml, text: emailHtmlToText({ html: safeHtml }), missingFields: rendered.missingFields };
}

/** The starter body a template is born with when its creator gives no HTML. */
export function emailTemplateSkeleton(
  { subject, fields }: { subject: string; fields: readonly EmailTemplateField[] },
  _optional: Record<string, never> = {},
): string {
  const meta = fields.length > 0 ? `\n<meta name="${EMAIL_FIELDS_META_NAME}" content="${escapeHtml({ value: formatFieldDeclarations({ fields }) })}">` : "";
  // Guard the first field itself so an empty list keeps its plain greeting.
  const firstField = fields[0];
  const greeting = firstField === undefined ? "Hello," : `Hello {{${firstField.name}}},`;
  return `<!doctype html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">${meta}
<title>${escapeHtml({ value: subject })}</title>
</head>
<body style="margin:0;padding:0;background:#f4f4f5;font-family:Arial,Helvetica,sans-serif;color:#18181b;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f5;">
<tr><td align="center" style="padding:24px;">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:8px;">
<tr><td style="padding:32px;font-size:16px;line-height:1.5;">
<p>${greeting}</p>
<p></p>
</td></tr>
</table>
</td></tr>
</table>
</body>
</html>
`;
}

import { type Kysely, type SelectQueryBuilder, sql } from "kysely";

import type { ContentKernel } from "../../platform/db/content-kernel.js";
import type { ContentDatabase } from "../../platform/db/content-database.generated.js";
import { isUniqueViolation, jsonScalarEquals, jsonSortKey } from "../../platform/db/kernel/dialect.js";
import { EntrySlugConflictError, VersionConflictError } from "./index.js";
import type { EntryListPort, EntryRecord, EntryRepoPort, EntryRevisionInput, EntryStatus } from "./index.js";
import type {
  CollectionListQuery,
  CollectionSortBy,
  EntryDisplayListPort,
  EntryListExcludingTypesPort,
} from "./public-list.js";
import { type EntryRow, toRecord, toRevisionRow, toRow } from "./repo.rows.js";
import type { TrashableEntryRecord } from "./trash-aware-memory-repo.js";

/**
 * @file THE durable `EntryRepoPort` + `EntryListPort` (and the display / exclude-types / publish
 * read ports): one Kysely query body for every database the storage kernel drives (SQLite, PGlite,
 * Postgres). The second rule-of-two adapter (`trash-aware-memory-repo.ts` is the first);
 * `repo.sqlite.ts` keeps `SqliteEntryRepo` as a thin subclass built from the content db handle.
 *
 * Trash: a row with `deleted_at` set is in the Trash (only widgets get there today). Every read here
 * hides it, so every widget reader — region placements, embeds, the admin list — treats a trashed
 * widget as missing (the REQ-28 placeholder). `save` never writes `deleted_at` and never touches a
 * trashed row; only the Trash moves a row in or out.
 */

type EntriesSelect = SelectQueryBuilder<ContentDatabase, "entries", EntryRow>;

/** A write refused by the slug index: the reads hide a trashed holder, so that is the one the
 *  chokepoint's own slug check could not have seen. */
function trashedSlugConflict(slug: string): EntrySlugConflictError {
  return new EntrySlugConflictError({ message: `an entry with slug '${slug}' is in the Trash — restore it, or delete it permanently from the Trash, to reuse the slug` });
}

/** Publish-content's entry read (`publish-content.ts`): the row plus its Trash marker, trashed rows
 *  included, so a precheck refuses a trashed destination instead of planning a create that `save`
 *  would then silently skip. */
export interface EntryPublishReadPort {
  findAnyById(params: { workspaceId: string; id: string }): Promise<TrashableEntryRecord | null>;
  /** The `(type, slug)` holder, trashed or not: the slug index spans the Trash, so a trashed holder
   *  still blocks a create and precheck must see it. */
  findAnyBySlug(params: { workspaceId: string; type: string; slug: string }): Promise<TrashableEntryRecord | null>;
}

/**
 * What a custom field's name must look like to be used as a JSON path key. Content-type field names
 * are `^[a-z][a-z0-9_]{0,63}$` (`IDENTIFIER_GRAMMAR_PATTERN`), which always passes; anything else
 * can only be a caller that skipped that validation, and it matches nothing rather than throwing
 * (today's behaviour) — the name never reaches SQL either way.
 */
const SITE_FIELD_KEY = /^[A-Za-z0-9_]+$/;

/** The path of a custom field's value inside `entries.fields_json`. */
const siteFieldPath = (field: string): string[] => ["ext", "site", field];

export class SqlEntryRepo implements EntryRepoPort, EntryListPort, EntryDisplayListPort, EntryListExcludingTypesPort, EntryPublishReadPort {
  protected readonly kernel: ContentKernel;
  constructor(kernel: ContentKernel) {
    this.kernel = kernel;
  }

  /** `entries` in the workspace, the Trash hidden unless `includeTrashed`. */
  private scoped(db: Kysely<ContentDatabase>, workspaceId: string, includeTrashed = false): EntriesSelect {
    const query = db.selectFrom("entries").selectAll().where("workspace_id", "=", workspaceId);
    return includeTrashed ? query : query.where("deleted_at", "is", null);
  }

  async findBySlug(params: { workspaceId: string; type: string; slug: string }): Promise<EntryRecord | null> {
    const row = await this.kernel.run((db) =>
      this.scoped(db, params.workspaceId).where("type", "=", params.type).where("slug", "=", params.slug).limit(1).executeTakeFirst()
    );
    return row ? toRecord(row) : null;
  }

  async findById(params: { workspaceId: string; id: string }): Promise<EntryRecord | null> {
    const row = await this.kernel.run((db) => this.scoped(db, params.workspaceId).where("id", "=", params.id).limit(1).executeTakeFirst());
    return row ? toRecord(row) : null;
  }

  /** Trash-blind: see {@link EntryPublishReadPort}. @complexity O(1). */
  async findAnyById(params: { workspaceId: string; id: string }): Promise<TrashableEntryRecord | null> {
    const row = await this.kernel.run((db) => this.scoped(db, params.workspaceId, true).where("id", "=", params.id).limit(1).executeTakeFirst());
    return row ? { ...toRecord(row), deletedAt: row.deleted_at } : null;
  }

  /** Trash-blind: see {@link EntryPublishReadPort}. @complexity O(1). */
  async findAnyBySlug(params: { workspaceId: string; type: string; slug: string }): Promise<TrashableEntryRecord | null> {
    const row = await this.kernel.run((db) =>
      this.scoped(db, params.workspaceId, true).where("type", "=", params.type).where("slug", "=", params.slug).limit(1).executeTakeFirst()
    );
    return row ? { ...toRecord(row), deletedAt: row.deleted_at } : null;
  }

  /**
   * Upserts an `entries` row by id — full-replace semantics, matching `InMemoryEntryRepo.save`'s
   * `Map.set` behavior exactly. A trashed row is left as it is (a stale save cannot bring it back).
   *
   * With `expectedVersion` the save is a compare-and-set instead (wm S3): one conditional UPDATE on
   * the live row holding that version, inside the caller's transaction, so two writers that read the
   * same version cannot both land (a Postgres writer blocked on the row lock re-checks the WHERE
   * against the winner's row). With `expectedVersion: null` (an import-as-create) it is an insert that
   * lands only when the id is free, so two creates of one id cannot both land either.
   * @throws EntrySlugConflictError when a trashed row holds the slug: the reads above hide it, so the
   *         chokepoint's own slug check could not see it.
   * @throws VersionConflictError ``expected version <n> for entry '<id>', found <stored|none>`` when the
   *         compare-and-set misses (stale version, trashed or missing row), or
   *         ``expected no entry '<id>', found <stored>`` when a create finds the id taken.
   * @complexity O(1).
   */
  async save(record: EntryRecord, options: { expectedVersion?: number | null | undefined } = {}): Promise<void> {
    const values = toRow(record);
    try {
      if (options.expectedVersion === null) {
        await this.insertIfAbsent(record, values);
        return;
      }
      if (options.expectedVersion !== undefined) {
        await this.compareAndSet(record, values, options.expectedVersion);
        return;
      }
      await this.kernel.run((db) =>
        db
          .insertInto("entries")
          .values(values)
          .onConflict((oc) => oc.column("id").doUpdateSet(values).where("entries.deleted_at", "is", null))
          .execute()
      );
    } catch (error) {
      if (isUniqueViolation(error)) throw trashedSlugConflict(record.slug);
      throw error;
    }
  }

  /**
   * The insert behind `save`'s `expectedVersion: null`. `ON CONFLICT DO NOTHING` has no target on
   * purpose: with only `(id)` as the target, a Postgres create racing another on the same id can hit
   * the `(workspace_id, type, slug)` unique index first and fail with a unique violation, which also
   * aborts the transaction. Untargeted, a writer blocked on the winner's uncommitted insert waits,
   * then inserts nothing. A miss is told apart by whether a row (trashed, or in any workspace) holds
   * the id; if none does, the only other unique index, the slug, refused it.
   */
  private async insertIfAbsent(record: EntryRecord, values: ReturnType<typeof toRow>): Promise<void> {
    const inserted = await this.kernel.run((db) => db.insertInto("entries").values(values).onConflict((oc) => oc.doNothing()).executeTakeFirst());
    // A driver that reported no count reads as inserted: read as a miss, the holder lookup below would
    // find this very row and turn a create that succeeded into a false version conflict.
    if (Number(inserted.numInsertedOrUpdatedRows) !== 0) return;
    const holder = await this.kernel.run((db) => db.selectFrom("entries").select("version").where("id", "=", record.id).executeTakeFirst());
    if (!holder) throw trashedSlugConflict(record.slug);
    throw new VersionConflictError({ message: `expected no entry '${record.id}', found ${holder.version}` });
  }

  /** The conditional UPDATE behind `save`'s `expectedVersion`; on a miss, re-reads the live version for the message. */
  private async compareAndSet(record: EntryRecord, values: ReturnType<typeof toRow>, expectedVersion: number): Promise<void> {
    const result = await this.kernel.run((db) =>
      db
        .updateTable("entries")
        .set(values)
        .where("workspace_id", "=", record.workspaceId)
        .where("id", "=", record.id)
        .where("deleted_at", "is", null)
        .where("version", "=", expectedVersion)
        .executeTakeFirst()
    );
    if (Number(result.numUpdatedRows) > 0) return;
    const found = (await this.findById({ workspaceId: record.workspaceId, id: record.id }))?.version ?? "none";
    throw new VersionConflictError({ message: `expected version ${expectedVersion} for entry '${record.id}', found ${found}` });
  }

  async appendRevision(revision: EntryRevisionInput): Promise<void> {
    await this.kernel.run((db) => db.insertInto("entry_revisions").values(toRevisionRow(revision)).execute());
  }

  async listByWorkspace(
    required: Parameters<EntryListPort["listByWorkspace"]>[0],
    optional: NonNullable<Parameters<EntryListPort["listByWorkspace"]>[1]> = {}
  ): Promise<EntryRecord[]> {
    const { type } = optional;
    return this.listLive({ ...required, ...optional }, type ? (query) => query.where("type", "=", type) : undefined);
  }

  /**
   * Review fix 3b (`public-list.ts`'s {@link EntryListExcludingTypesPort} doc) — same shape as
   * {@link listByWorkspace}, but `excludeTypes` rows are filtered out in SQL, before `LIMIT`, so
   * they can never crowd a bounded result out of real content.
   *
   * @complexity O(log n + k) via `idx_entries_workspace(workspace_id, type)`; `k` is bounded by
   * `params.limit`, never a full-table scan.
   */
  async listByWorkspaceExcludingTypes(params: {
    workspaceId: string;
    excludeTypes: readonly string[];
    status?: EntryStatus;
    orderBy?: "updatedAt";
    orderDirection?: "asc" | "desc";
    limit?: number;
  }): Promise<EntryRecord[]> {
    return this.listLive(
      params,
      params.excludeTypes.length > 0 ? (query) => query.where("type", "not in", [...params.excludeTypes]) : undefined
    );
  }

  /** The shared body of the two workspace lists: live rows, an optional type filter, status, order, limit. */
  private async listLive(
    params: Parameters<EntryListPort["listByWorkspace"]>[0] & NonNullable<Parameters<EntryListPort["listByWorkspace"]>[1]>,
    narrow?: (query: EntriesSelect) => EntriesSelect
  ): Promise<EntryRecord[]> {
    const rows = await this.kernel.run((db) => {
      let query = this.scoped(db, params.workspaceId);
      if (narrow) query = narrow(query);
      if (params.status) query = query.where("status", "=", params.status);
      if (params.orderBy === "updatedAt") query = query.orderBy("updated_at", params.orderDirection === "asc" ? "asc" : "desc");
      if (typeof params.limit === "number") query = query.limit(params.limit);
      return query.execute();
    });
    return rows.map(toRecord);
  }

  /** Callback repo calls join ONE transaction; nested calls join the outer one (the widget adoption
   *  runs an entry update and its Trash move as one). */
  async transaction<T>({ fn }: { fn: () => Promise<T> }): Promise<T> {
    return this.kernel.transaction(fn);
  }

  /**
   * C2 (plan lines 149-167) — the `{"type":"collection"}` marker's read path: published,
   * non-trashed rows of `query.type`, narrowed by every `query.where` clause, ordered by
   * `query.sort`, bounded to `query.limit`. Every `where`/`sort` field name and value reaches SQL
   * only as a bound parameter, never interpolated into the query text. NULL sort keys come first
   * ascending and last descending on every dialect, and `entries.id` is the final tiebreak so a
   * result is stable across calls when the primary key ties.
   *
   * @complexity O(log n + k): `idx_entries_workspace(workspace_id, type)` narrows to the
   * workspace+type first; each matched row is then charged one JSON read per `where` clause plus the
   * sort key (no expression index yet — plan §1 unknown 3's "queryable index provisioner" follow-up
   * is later work). `k` is bounded by `query.limit` at the SQL layer.
   */
  async listPublishedForDisplay(params: { workspaceId: string; query: CollectionListQuery }): Promise<EntryRecord[]> {
    const { workspaceId, query } = params;
    const rows = await this.kernel.run((db) => {
      let select = this.scoped(db, workspaceId).where("type", "=", query.type).where("status", "=", "published");
      for (const clause of query.where) {
        select = select.where(
          SITE_FIELD_KEY.test(clause.field)
            ? jsonScalarEquals(this.kernel.dialect, sql.ref("fields_json"), siteFieldPath(clause.field), clause.value)
            : sql<boolean>`(1 = 0)`
        );
      }
      const dir = query.sort.dir;
      const key = this.sortKey(query.sort.by);
      if (key) select = select.orderBy(key, (ob) => (dir === "asc" ? ob.asc().nullsFirst() : ob.desc().nullsLast()));
      return select.orderBy("id", "asc").limit(query.limit).offset(query.offset ?? 0).execute();
    });
    return rows.map(toRecord);
  }

  /** The `ORDER BY` target: the three built-in keywords are real columns; `{field}` is the JSON sort
   *  key. A field name that cannot be a path key has none (`null`): `id` alone decides the order. */
  private sortKey(by: CollectionSortBy) {
    if (by === "published") return sql.ref("published_at");
    if (by === "updated") return sql.ref("updated_at");
    if (by === "title") return sql.ref("title");
    if (!SITE_FIELD_KEY.test(by.field)) return null;
    return jsonSortKey(this.kernel.dialect, sql.ref("fields_json"), siteFieldPath(by.field));
  }
}

/** The entry repo for `kernel`. */
export function entryRepoFor(kernel: ContentKernel): SqlEntryRepo {
  return new SqlEntryRepo(kernel);
}

import { EntrySlugConflictError, InMemoryEntryRepo, VersionConflictError } from "./index.js";
import type { EntryListPort, EntryRecord, EntryRepoPort, EntryRevisionInput, EntryStatus } from "./index.js";
import type { CollectionListQuery, CollectionSortBy, EntryDisplayListPort, EntryListExcludingTypesPort } from "./public-list.js";

/**
 * @file The in-memory twin of `repo.sqlite.ts`'s Trash rules, for the hermetic composition
 * (`server/runtime/composition/app.ts`), which has no `content.db`. Wraps the package's
 * `InMemoryEntryRepo` and keeps each trashed row's `deletedAt` beside it:
 *  - every read hides a trashed row;
 *  - `save` leaves a trashed row as it is, and refuses a slug a trashed row holds;
 *  - `findAnyById`/`saveAny` are the trash-blind seam the Trash's record-store adapter flips the
 *    marker through (the SQLite root flips `entries.deleted_at` with the generic table adapter).
 */

/** An entry plus its Trash marker, as the Trash's record-store adapter sees it. */
export type TrashableEntryRecord = EntryRecord & { deletedAt: string | null };

/**
 * Reads one custom field's value out of an entry's namespaced `fields.ext.site.<name>` bag — the
 * in-memory twin of `repo.sqlite.ts`'s `json_extract($.ext.site.<name>)`. Unlike the SQLite side,
 * no boolean-to-`1`/`0` conversion is needed here: a JS `boolean`/`number`/`string` compares
 * directly against the same JS type read back from `fieldsJson`, since neither side ever passes
 * through a JSON-in-SQLite round trip.
 *
 * @complexity O(1).
 */
function siteFieldValue(row: EntryRecord, field: string): unknown {
  const fields = row.fieldsJson as { ext?: { site?: Record<string, unknown> } } | null | undefined;
  return fields?.ext?.site?.[field];
}

/**
 * Resolves a {@link CollectionSortBy} into the value `listPublishedForDisplay`'s sort compares —
 * the in-memory twin of `repo.sqlite.ts`'s `sortByExpression`.
 *
 * @complexity O(1).
 */
function sortKey(row: EntryRecord, by: CollectionSortBy): unknown {
  if (by === "published") return row.publishedAt;
  if (by === "updated") return row.updatedAt;
  if (by === "title") return row.title;
  return siteFieldValue(row, by.field);
}

/**
 * Orders two arbitrary, possibly-mixed-type sort key values: `null`/`undefined` sort first,
 * same-typed numbers compare numerically (so `9` sorts before `10`, matching SQLite's
 * `json_extract`-returns-typed-values behavior for the SQLite adapter's own numeric fields),
 * everything else compares as a string. Not a general-purpose comparator — scoped to the sort
 * keys {@link sortKey} can produce (an entry's own scalar column values or one JSON field value).
 *
 * @complexity O(1) (O(n) only in the rare cross-type string-coercion branch's implicit
 * `String()` call, n being the value's own serialized length).
 */
function compareSortKeys(a: unknown, b: unknown): number {
  if (a == null && b == null) return 0;
  if (a == null) return -1;
  if (b == null) return 1;
  if (typeof a === "number" && typeof b === "number") return a - b;
  const aText = String(a);
  const bText = String(b);
  if (aText < bText) return -1;
  if (aText > bText) return 1;
  return 0;
}

export class TrashAwareInMemoryEntryRepo implements EntryRepoPort, EntryListPort, EntryDisplayListPort, EntryListExcludingTypesPort {
  private readonly inner = new InMemoryEntryRepo();
  /** id → when it was trashed. */
  private readonly deletedAt = new Map<string, string>();

  /** @complexity O(n) over stored entries (the inner repo's scan). */
  async findBySlug(params: { workspaceId: string; type: string; slug: string }): Promise<EntryRecord | null> {
    const row = await this.inner.findBySlug(params);
    return row && !this.deletedAt.has(row.id) ? row : null;
  }

  /** @complexity O(1). */
  async findById(params: { workspaceId: string; id: string }): Promise<EntryRecord | null> {
    const row = await this.inner.findById(params);
    return row && !this.deletedAt.has(row.id) ? row : null;
  }

  /**
   * With `expectedVersion`, the inner repo's compare-and-set decides; a trashed row is a conflict
   * (found none — the same as the SQL repo), not a silent skip, since the inner repo cannot see the Trash.
   * A create (`expectedVersion: null`) goes on to the inner repo, which still holds a trashed row and
   * so refuses its id, as the SQL primary key does.
   * @throws EntrySlugConflictError when a trashed row holds the slug (same text as the SQLite repo).
   * @throws VersionConflictError when the compare-and-set misses or a create finds the id taken.
   * @complexity O(n) over stored entries (one slug scan).
   */
  async save(row: EntryRecord, options: { expectedVersion?: number | null | undefined } = {}): Promise<void> {
    if (this.deletedAt.has(row.id) && options.expectedVersion !== null) {
      if (options.expectedVersion === undefined) return;
      throw new VersionConflictError({ message: `expected version ${options.expectedVersion} for entry '${row.id}', found none` });
    }
    const holder = await this.inner.findBySlug({ workspaceId: row.workspaceId, type: row.type, slug: row.slug });
    if (holder && holder.id !== row.id && this.deletedAt.has(holder.id)) {
      throw new EntrySlugConflictError({ message: `an entry with slug '${row.slug}' is in the Trash — restore it, or delete it permanently from the Trash, to reuse the slug` });
    }
    await this.inner.save(row, options);
  }

  async appendRevision(revision: EntryRevisionInput): Promise<void> {
    await this.inner.appendRevision(revision);
  }

  async transaction<T>({ fn }: { fn: () => Promise<T> }): Promise<T> {
    return this.inner.transaction({ fn });
  }

  /** `limit` applies after trashed rows are dropped, as the SQLite `LIMIT` does.
   *  @complexity O(n log n) over the workspace's entries when ordered. */
  async listByWorkspace(
    required: Parameters<EntryListPort["listByWorkspace"]>[0],
    optional: NonNullable<Parameters<EntryListPort["listByWorkspace"]>[1]> = {}
  ): Promise<EntryRecord[]> {
    const { limit, ...rest } = optional;
    const live = (await this.inner.listByWorkspace(required, rest)).filter((row) => !this.deletedAt.has(row.id));
    return typeof limit === "number" ? live.slice(0, limit) : live;
  }

  /**
   * Review fix 3b — the in-memory twin of `SqliteEntryRepo.listByWorkspaceExcludingTypes`:
   * `excludeTypes` and the trash filter are both applied to the FULL scan before `limit` slices
   * it, so newer system rows can never crowd real content out of a bounded result (the bug this
   * method replaces: the old call site applied its own type filter after `listByWorkspace`'s own
   * `limit` had already run).
   * @complexity O(n log n) over the workspace's live rows when ordered (see `listByWorkspace`).
   */
  async listByWorkspaceExcludingTypes(params: {
    workspaceId: string;
    excludeTypes: readonly string[];
    status?: EntryStatus;
    orderBy?: "updatedAt";
    orderDirection?: "asc" | "desc";
    limit?: number;
  }): Promise<EntryRecord[]> {
    const { workspaceId, excludeTypes, status, orderBy, orderDirection, limit } = params;
    const rows = (await this.inner.listByWorkspace({ workspaceId }, { status, orderBy, orderDirection })).filter(
      (row) => !this.deletedAt.has(row.id) && !excludeTypes.includes(row.type)
    );
    return typeof limit === "number" ? rows.slice(0, limit) : rows;
  }

  /** Trash seam: the row whether or not it is trashed. @complexity O(1). */
  async findAnyById(params: { workspaceId: string; id: string }): Promise<TrashableEntryRecord | null> {
    const row = await this.inner.findById(params);
    return row ? { ...row, deletedAt: this.deletedAt.get(row.id) ?? null } : null;
  }

  /** The `(type, slug)` holder whether or not it is trashed. @complexity O(n) (one slug scan). */
  async findAnyBySlug(params: { workspaceId: string; type: string; slug: string }): Promise<TrashableEntryRecord | null> {
    const row = await this.inner.findBySlug(params);
    return row ? { ...row, deletedAt: this.deletedAt.get(row.id) ?? null } : null;
  }

  /** Trash seam: writes the row and its marker as given. @complexity O(1). */
  async saveAny(record: TrashableEntryRecord): Promise<void> {
    const { deletedAt, ...row } = record;
    await this.inner.save(row);
    if (deletedAt === null) this.deletedAt.delete(row.id);
    else this.deletedAt.set(row.id, deletedAt);
  }

  /** Purge seam: delegates physical deletion and forgets the marker only for this workspace.
   * @complexity O(r) over the inner repository's stored revisions. */
  async hardDelete(required: { workspaceId: string; id: string }, _optional: Record<string, never> = {}): Promise<void> {
    if (!(await this.inner.findById(required))) return;
    await this.inner.hardDelete(required);
    this.deletedAt.delete(required.id);
  }

  /**
   * C2 (plan lines 149-167) — the in-memory twin of `SqliteEntryRepo.listPublishedForDisplay`:
   * same filter/sort/limit semantics (published, non-trashed, `query.type`, every `where` clause
   * matched, `query.sort` order with an `id` tiebreak, `query.limit` applied last), reached
   * through this host's own `InMemoryEntryRepo.listByWorkspace` plus the trash filter every other
   * read method here applies, rather than a raw `json_extract` SQL query.
   *
   * @complexity O(n log n) over the workspace+type's live rows: one full scan (bounded by
   * `listByWorkspace`'s own workspace+type filter) plus a JS sort. `n` is never the full table —
   * `InMemoryEntryRepo` only ever backs the hermetic composition root (`server/runtime/
   * composition/app.ts`), which has no real persistence and no production-sized data.
   */
  async listPublishedForDisplay(params: { workspaceId: string; query: CollectionListQuery }): Promise<EntryRecord[]> {
    const { workspaceId, query } = params;
    const rows = (await this.inner.listByWorkspace({ workspaceId }, { type: query.type, status: "published" })).filter(
      (row) => !this.deletedAt.has(row.id)
    );
    const matching = rows.filter((row) => query.where.every((clause) => siteFieldValue(row, clause.field) === clause.value));

    const direction = query.sort.dir === "asc" ? 1 : -1;
    const sorted = [...matching].sort((a, b) => {
      const primary = compareSortKeys(sortKey(a, query.sort.by), sortKey(b, query.sort.by)) * direction;
      if (primary !== 0) return primary;
      if (a.id < b.id) return -1;
      if (a.id > b.id) return 1;
      return 0;
    });
    const offset = query.offset ?? 0;
    return sorted.slice(offset, offset + query.limit);
  }
}

import type { SecretCardField, SecretCardForm } from "@jini-ai/ui/mcp-ui/secret-card";
import type { ExternalMcpServerView } from "#src/assistant/index";
import { SECRET_FORM_CARD_DEFINITIONS } from "../../contracts/headless/secret-form-cards.js";

/**
 * @file The confirmation form `external_mcp_save` renders — see `tool-registrations.ts`'s handler
 * for how it is opened, answered, and turned into a real write.
 *
 * ## Why the field LIST is computed once, not reactive
 *
 * `apps/admin/src/features/settings/rules.ts`'s `buildExternalMcpFieldSpecs` solves the identical
 * "which fields apply to this transport/authMode" decision for the admin UI, where it must be
 * REACTIVE — a human can change their mind mid-form. An MCP-UI form has no such need: it is a
 * server-rendered HTML document generated once per tool call, and the agent has already committed
 * to a transport/authMode by the time it calls this tool (see `agent-tools.ts`'s own schema doc).
 * So this file restates the SAME decision rules as a one-shot computation over the tool's own input,
 * rather than importing the admin package's React-specific type. Two independent, intentionally
 * parallel implementations of one documented rule — not a shared abstraction — because the two
 * outputs are genuinely different shapes (`@jini-ai/ui`'s `SourceFieldSpec` vs `@jini-ai/ui/mcp-ui/
 * secret-card`'s `SecretCardField`) for two different rendering systems.
 *
 * ## Secrets never appear as `value`
 *
 * `env`/`accessToken`/`oauthClientSecret` are rendered `secret: true` with NO `value` — never pre-filled, even
 * when updating a row that already has one, because there is nothing to pre-fill FROM: no read model
 * in this subsystem ever returns a stored secret (see `apps/admin`'s own `use-external-mcp.hooks.ts`
 * header for the identical rule, restated for the identical reason). Leaving it blank on submit is
 * what "keep what's stored" means to `saveExternalMcpServer` — the same tri-state convention the
 * admin form's own write path already relies on.
 */

export const EXTERNAL_MCP_SAVE_TOOL_ID = "external_mcp_save";

/** `external_mcp_save`'s own non-secret input, narrowed to what {@link buildExternalMcpSaveFormFields}
 *  and {@link buildExternalMcpSaveForm} actually read. Matches `agent-tools.ts`'s `SAVE_INPUT_SCHEMA`
 *  property-for-property. */
export interface ExternalMcpSaveInput {
  id: string;
  label?: string;
  transport: string;
  command?: string;
  args?: string;
  url?: string;
  allowedToolNames?: string;
  /** Raw operator input, comma-separated remote tool names separately authorized to write —
   *  `SaveExternalMcpServerInput.writeAllowedToolNames`'s own tri-state convention (resent in full on
   *  every save, not tri-state like `env`; see `tool-registrations.ts`'s
   *  `buildSaveExternalMcpServerInputFromFormParams` for why). The store rejects a name here that is
   *  not also in `allowedToolNames` (`external-mcp-store.ts`'s `assertWriteAllowlistSubset`). */
  writeAllowedToolNames?: string;
  authMode?: string;
  /** Non-secret name of the stdio variable that receives the human-entered token. */
  accessTokenEnvName?: string;
  oauthProviderId?: string;
  oauthGrant?: string;
  oauthClientId?: string;
  oauthScopes?: string;
  oauthTokenEnvName?: string;
  oauthAuthorizationEndpoint?: string;
  oauthTokenEndpoint?: string;
  oauthDeviceAuthorizationEndpoint?: string;
}

/**
 * Merges the agent's own input over an existing row's current (non-secret) values, so an UPDATE's
 * form shows the human accurate current state for anything the agent did not explicitly restate,
 * rather than blanks. `existing` is `undefined` for a brand-new id.
 *
 * @complexity O(1).
 */
export function mergeExternalMcpSavePrefill(
  input: ExternalMcpSaveInput,
  existing: ExternalMcpServerView | undefined,
): ExternalMcpSaveInput {
  if (!existing) return input;
  const prefill: ExternalMcpSaveInput = {
    id: input.id,
    label: existing.label,
    transport: input.transport,
    command: existing.command,
    args: existing.args.join(" "),
    url: existing.url ?? undefined,
    allowedToolNames: existing.allowedToolNames.join(", "),
    writeAllowedToolNames: existing.writeAllowedToolNames.join(", "),
    authMode: existing.authMode,
    accessTokenEnvName: existing.accessTokenEnvName ?? undefined,
    oauthProviderId: existing.oauth.providerId ?? undefined,
    oauthGrant: existing.oauth.grant ?? undefined,
    oauthClientId: existing.oauth.clientId ?? undefined,
    oauthScopes: existing.oauth.scopes.join(" "),
    oauthTokenEnvName: existing.oauth.tokenEnvName ?? undefined,
    // NOT merged from `existing` — `ExternalMcpOAuthView` carries no field for a connection's own
    // typed endpoints (only `providerId`, for a registered one). There is nothing stored to merge
    // from; see `apps/admin`'s `use-external-mcp.hooks.ts` header for the identical, already-disclosed
    // gap on the admin side.
    oauthAuthorizationEndpoint: input.oauthAuthorizationEndpoint,
    oauthTokenEndpoint: input.oauthTokenEndpoint,
    oauthDeviceAuthorizationEndpoint: input.oauthDeviceAuthorizationEndpoint,
  };
  return Object.keys(prefill).reduce((merged, field) => {
    const key = field as keyof ExternalMcpSaveInput;
    return { ...merged, [key]: input[key] ?? merged[key] };
  }, prefill);
}

/** `{ value }` when `value` is present, an empty object otherwise — the shared shape every optional
 *  field spread in this file's field builders used to write inline as `value !== undefined ? {value}
 *  : {}`. Collapsing it into a call removes that ternary from every call site's own complexity count. */
function fieldValue<T>(value: T | undefined): { value: T } | Record<string, never> {
  return value !== undefined ? { value } : {};
}

function buildStdioTransportFields(input: ExternalMcpSaveInput): SecretCardField[] {
  return [
    { kind: "string", name: "command", label: "Command", required: true, ...fieldValue(input.command), placeholder: "e.g. npx, node, /path/to/binary" },
    { kind: "string", name: "args", label: "Args", ...fieldValue(input.args), placeholder: "space-separated" },
  ];
}

/** A credential stays exclusively in the human form, with blank update submissions preserving it.
 * @complexity O(1) for a fixed field list.
 */
function buildStaticTokenFields(input: ExternalMcpSaveInput, isUpdate: boolean, isStdio: boolean): SecretCardField[] {
  return [
    { kind: "string", name: "accessToken", label: "Access token", ...SECRET_FORM_CARD_DEFINITIONS.external_mcp_save.secretField, allowBlank: true, hint: isUpdate ? "Leave blank to keep the stored token." : "Enter the API key or bearer token for this server." },
    ...(isStdio ? [{ kind: "string" as const, name: "accessTokenEnvName", label: "Access token environment variable", ...fieldValue(input.accessTokenEnvName), hint: "The environment variable name the local command reads, e.g. API_TOKEN." }] : []),
  ];
}

function buildEnvField(isUpdate: boolean): SecretCardField {
  return {
    kind: "string",
    name: "env",
    label: "Environment variables",
    multiline: true,
    rows: 3,
    ...SECRET_FORM_CARD_DEFINITIONS.external_mcp_save.secretField, allowBlank: true,
    placeholder: "KEY=VALUE, one per line",
    hint: isUpdate ? "Leave blank to keep the stored values." : undefined,
  };
}

/**
 * `isStdio` decides which OAuth fields a human must actually fill in, and it is not a cosmetic
 * distinction: `external-mcp-store.ts`'s `assertOAuthClientId` / `assertOAuthGrant` /
 * `assertOAuthProviderIdentity` admit an EMPTY client id, sign-in method and provider identity on any
 * non-stdio row, because a row carrying a remote URL can run RFC 8414 discovery against it, read the
 * server's own `grant_types_supported`, and mint its own client by RFC 7591 dynamic registration. A
 * growing share of hosted MCP servers publish a registration endpoint and no developer console at
 * all, so for those there is no client id — or a confident answer about the grant — a human could
 * type; marking either field required made the form unsubmittable by any amount of operator effort.
 * A stdio row has no URL to discover from, so there the requirement stands. Same rule, same
 * reasoning, same wording as `apps/admin/src/features/settings/rules.ts`'s
 * `buildExternalMcpFieldSpecs`.
 */
function buildOAuthCoreFields(input: ExternalMcpSaveInput, isUpdate: boolean, isStdio: boolean): SecretCardField[] {
  return [
    {
      kind: "string",
      name: "oauthProviderId",
      label: "Provider ID",
      ...fieldValue(input.oauthProviderId),
      hint: isStdio
        ? "Leave blank to use your own endpoints below."
        : "Leave blank unless this server is a registered provider — a hosted server discovers its own endpoints.",
    },
    {
      kind: "enum",
      name: "oauthGrant",
      label: "Sign-in method",
      required: isStdio,
      options: [
        { value: "authorization_code", label: "Browser sign-in" },
        { value: "device_code", label: "Device code" },
      ],
      ...fieldValue(input.oauthGrant),
      ...(isStdio ? {} : { hint: "Detected from the server unless overridden." }),
    },
    {
      kind: "string",
      name: "oauthClientId",
      label: "Client ID",
      required: isStdio,
      ...fieldValue(input.oauthClientId),
      ...(isStdio ? {} : { placeholder: "leave blank to register with this server automatically" }),
    },
    { kind: "string", name: "oauthClientSecret", label: "Client secret", ...SECRET_FORM_CARD_DEFINITIONS.external_mcp_save.secretField, allowBlank: true, hint: isUpdate ? "Leave blank to keep the stored secret." : "Leave blank if this provider needs none (a public/PKCE client)." },
    { kind: "string", name: "oauthScopes", label: "Scopes", ...fieldValue(input.oauthScopes), placeholder: "space- or comma-separated" },
  ];
}

function buildOAuthTokenEnvField(input: ExternalMcpSaveInput): SecretCardField {
  return {
    kind: "string",
    name: "oauthTokenEnvName",
    label: "Access token environment variable",
    required: true,
    ...fieldValue(input.oauthTokenEnvName),
  };
}

/** What an endpoint field means on a row that self-configures: a manual override for the case where
 *  discovery does not answer, not something to go and look up. See {@link buildOAuthCoreFields}. */
const DISCOVERABLE_ENDPOINT_HINT = "Leave blank unless discovery against this server's URL fails.";

function buildOAuthEndpointFields(input: ExternalMcpSaveInput, isStdio: boolean): SecretCardField[] {
  return [
    {
      kind: "string",
      name: "oauthAuthorizationEndpoint",
      label: "Authorization endpoint",
      ...fieldValue(input.oauthAuthorizationEndpoint),
      hint: isStdio ? "Needed for Browser sign-in, unless Provider ID is set." : DISCOVERABLE_ENDPOINT_HINT,
    },
    {
      kind: "string",
      name: "oauthTokenEndpoint",
      label: "Token endpoint",
      ...fieldValue(input.oauthTokenEndpoint),
      hint: isStdio ? "Needed unless Provider ID is set." : DISCOVERABLE_ENDPOINT_HINT,
    },
    {
      kind: "string",
      name: "oauthDeviceAuthorizationEndpoint",
      label: "Device authorization endpoint",
      ...fieldValue(input.oauthDeviceAuthorizationEndpoint),
      hint: isStdio ? "Needed for Device code, unless Provider ID is set." : DISCOVERABLE_ENDPOINT_HINT,
    },
  ];
}

function buildOAuthFields(input: ExternalMcpSaveInput, isUpdate: boolean, isStdio: boolean): SecretCardField[] {
  return [...buildOAuthCoreFields(input, isUpdate, isStdio), ...(isStdio ? [buildOAuthTokenEnvField(input)] : []), ...buildOAuthEndpointFields(input, isStdio)];
}

/**
 * The field list for one save form — see this file's header for why this is computed once rather
 * than reactively. Composed from per-section builders (transport, env, oauth) so the section that
 * decides inclusion stays a flat list of ternaries, and each section's own field shape lives in its
 * own single-purpose function.
 *
 * @complexity O(1) — a fixed, bounded number of conditionally-included entries.
 */
export function buildExternalMcpSaveFormFields(input: ExternalMcpSaveInput, isUpdate: boolean): SecretCardField[] {
  const isStdio = input.transport !== "streamable_http";
  const isOAuth = input.authMode === "oauth";

  return [
    ...(isUpdate ? [] : [{ kind: "string" as const, name: "id", label: "ID", required: true, value: input.id, hint: "Lowercase letters, digits and dashes." }]),
    { kind: "string", name: "label", label: "Display name", ...fieldValue(input.label) },
    ...(isStdio ? buildStdioTransportFields(input) : [{ kind: "string" as const, name: "url", label: "URL", required: true, ...fieldValue(input.url), placeholder: "https://…" }]),
    { kind: "string", name: "allowedToolNames", label: "Allowed tools", ...fieldValue(input.allowedToolNames),
      hint: "Comma-separated — nothing runs unless it is listed here." },
    { kind: "string", name: "writeAllowedToolNames", label: "May write", ...fieldValue(input.writeAllowedToolNames),
      hint: "Comma-separated, and must also be listed above under Allowed tools — a name here that isn't is rejected on save. Leave blank to grant no write access." },
    ...(isStdio ? [buildEnvField(isUpdate)] : []),
    ...(input.authMode === "static_env" || input.authMode === undefined ? buildStaticTokenFields(input, isUpdate, isStdio) : []),
    ...(isOAuth ? buildOAuthFields(input, isUpdate, isStdio) : []),
  ];
}

/**
 * Builds `external_mcp_save`'s confirmation form.
 *
 * `id`/`transport`/`authMode` are bound to prepared state at save rather than trusted from submit — see this file's
 * header on why the field SET is fixed per call; changing transport or auth mode is "call this tool
 * again", not an in-form control. The engine posts back on cancel rather than a silent close — with the call
 * parked, a silent close would strand the handler for the full TTL staring at a form the human
 * already walked away from.
 *
 * @complexity O(f) in the field count this call includes.
 * @returns Domain form copy and fields; the engine supplies routing/dismissal and renders the card.
 * @example buildExternalMcpSaveForm({ save: { id: "server", transport: "streamable_http" }, isUpdate: false });
 */
export function buildExternalMcpSaveForm(input: {
  save: ExternalMcpSaveInput;
  isUpdate: boolean;
}, _optional = {}): SecretCardForm {
  const { save, isUpdate } = input;
  return {
    title: isUpdate ? `Update "${save.id}"` : `Add "${save.id}"`,
    description: isUpdate
      ? "The assistant wants to update this external MCP server's configuration. Review and edit anything before saving."
      : "The assistant wants to add this external MCP server. Review and edit anything before saving.",
    details: [
      { label: "Connection type", value: save.transport === "streamable_http" ? "Hosted server (URL)" : "Local command (stdio)" },
      { label: "Credentials", value: save.authMode === "oauth" ? "Connect via OAuth" : save.authMode === "none" ? "None needed" : "API key / token" },
    ],
    submitLabel: isUpdate ? "Save changes" : "Add server",
    fields: buildExternalMcpSaveFormFields(save, isUpdate),
    cancelLabel: "Cancel",
    app: { appName: "tovu-external-mcp-save", appVersion: "1" },
  };
}

