/**
 * @file Wires `agent-tools.ts`'s 5-entry External MCP catalog to real handlers — the domain's own
 * header states the whole reason this file exists: "a non-technical site owner should be able to
 * type 'connect me to Higgsfield' into the admin assistant chat", which required this file and did
 * not work before it (no `contributeExternalMcpTools`, no manifest entry — confirmed by
 * `ADS-memory/reports/2026-09-07-assistant-tool-coverage-audit.md`, Gap #1). Only the narrower,
 * already-wired `external_mcp_reauth_prompt` (`external-mcp-reauth-tool.ts`) reached the assistant
 * before this file.
 *
 * The catalog is wired in FULL — there is no `unwiredToolIds` set here, matching `agent-tools.ts`'s
 * own header ("All five are wired"), which means the kit treats any future catalog entry added
 * without a handler as a build failure.
 *
 * ## `external_mcp_save`: one call, held open, exactly like `content_post_delete`
 *
 * The model's own call never writes anything by itself — it opens an MCP-UI form
 * (`save-form.ts`'s `buildExternalMcpSaveForm`) through Jini's secret-card engine, which parks on
 * `askThenReport` until the human submits or
 * cancels it, or it expires. `mergeExternalMcpSavePrefill` fills the form with an existing row's
 * current (non-secret) values when `id` already names one, so an update shows the human accurate
 * state for anything the model did not restate. Every secret field (`env`, `oauthClientSecret`)
 * exists ONLY in the rendered form, never in the model's own input schema — see `agent-tools.ts`'s
 * header for why that is load-bearing, not incidental.
 *
 * ## `external_mcp_test_connection` never opens a socket
 *
 * It reuses `readEnabledExternalMcpConfigs` — the SAME resolver the daemon runs at boot and
 * `probe.ts` resolves its target through — but, unlike `probe.ts`, stops there: no
 * `connectMcpHttpSession` call. That matches `agent-tools.ts`'s own description: "This does NOT
 * launch the command or make a network call to the remote server".
 *
 * ## `external_mcp_oauth_connect` has no live HTTP request to build a redirect URL from
 *
 * The admin route (`server/inbound/admin-http/routes/external-mcp/oauth.ts`) derives the callback's
 * absolute origin from the LIVE request (`externalMcpOAuthCallbackUrl`/`resolvePublicOrigin(req)`).
 * A tool-call handler has no `req` at all — the identical structural gap
 * `assistant/admin-screen-link-tool.ts`'s own header already worked through for a different tool.
 * This file follows that same precedent rather than inventing a new one: a small, LOCAL
 * `resolveConfiguredPublicOrigin()` reads only `TOVU_PUBLIC_URL` (the one branch of
 * `resolvePublicOrigin` that does not need `req`), duplicated rather than imported for the same
 * reason `admin-screen-link-tool.ts` gives — importing `server/inbound/public-http/routes/
 * external-mcp/oauth-callback-url.ts` would need a `Request` this file cannot supply and would pull
 * an `assistant -> server` edge into a domain module, reopening the exact composition-root/domain
 * cycle the tool-contribution registry (`tool-contribution-registry.ts`'s own header) exists to keep
 * closed.
 *
 * ### 2026-09-09: an unset `TOVU_PUBLIC_URL` no longer blocks EVERY grant
 *
 * This handler used to resolve a redirect URI UNCONDITIONALLY and refuse when the env var was unset.
 * That was wrong for `device_code`, which uses no redirect URI at all (RFC 8628: the human types a
 * code at the provider; nothing redirects back) — so the one grant that needed nothing was refused
 * along with the one that did, and in dev (`TOVU_PUBLIC_URL` unset by default) that was every
 * connect. Worse, the refusal was a bare `Error`, which `@jini-ai/daemon` redacts: the message
 * naming the env var never reached the model, making it a silent refusal in practice.
 *
 * ### 2026-09-10: `authorization_code` no longer refuses just because the env var is unset either
 *
 * The previous fix still left every `authorization_code` connect refusing outright in dev (the env
 * var is unset by default) and, worse, in the Electron desktop app, whose non-technical owner has no
 * way to set an environment variable at all — the exact case a 2026-09-09 product review flagged: "it
 * should be automatic". `resolveExternalMcpOAuthRedirectUri` now falls back to
 * `routeDeps.derivedPublicOrigin` — this PROCESS's own known bind origin (`server/routes/types.ts`'s
 * own doc has the derivation), populated by the composition root — when `TOVU_PUBLIC_URL` is unset.
 * Precedence is explicit and one-directional: the operator override always wins when present, the
 * derived origin only fills the gap when it is absent, never the reverse.
 *
 * This reopens a case an earlier version of this file's header rejected as "deriving a localhost
 * origin in dev", on the reasoning that a guessed redirect URI not matching what the provider was
 * registered with fails at the vendor with a confusing error, strictly harder to act on than a
 * refusal naming the variable. That reasoning does not change here — a redirect URI still has to
 * match the provider's registration to work — but the derived origin is no longer a blind guess: it
 * is this process's OWN bind origin, the one thing that matches "what the provider was registered
 * with" in precisely the two cases this fallback ever runs (local dev, and the desktop app's fixed
 * loopback origin). A real deployment behind a proxy or custom domain sets `TOVU_PUBLIC_URL`, per the
 * precedence above, so the derived guess never even reaches that case.
 *
 * Separately fixed since: `deps.ts`'s own former "cross-process caveat" — an `authorization_code`
 * connect started from the spawned agent-daemon used to mint a `pending` record the public callback
 * route's process (the main web server) could never see, so that grant could not complete from a chat
 * tool call running in the daemon, regardless of how correct the redirect URI is. Commit `3c4e30d89`
 * (migration 0062) moved that pending/device state into `content.db`, so a chat-started
 * `authorization_code` connect now completes across the process boundary; `beginConnect`'s in-process
 * BYOK path was unaffected either way. The last-resort refusal (still naming `TOVU_PUBLIC_URL`, now
 * also naming the derived attempt) fires only when a caller's `ExternalMcpToolDeps` never wires
 * `derivedPublicOrigin` at all — in every real composition root today, it always does, so the honest
 * case for that refusal is a future composition root that forgot to, not "the operator forgot an env
 * var".
 */

const CATALOG_BY_ID = indexCatalogById({ catalog: externalMcpAgentToolCatalog });

/** Mirrors `oauth-callback-url.ts`'s own constant — restated, not imported. See this file's header
 *  ("no live HTTP request") for why. Both must keep naming the SAME path: `mcp-federation/registrations.ts`'s
 *  public callback route (`server/inbound/public-http/routes/external-mcp/oauth-callback.ts`) is the
 *  only thing listening on it. */
const EXTERNAL_MCP_OAUTH_CALLBACK_PATH = "/api/mcp-servers/oauth/callback";

/**
 * Resolves `TOVU_PUBLIC_URL` into an absolute origin, or `undefined` when it is unset or blank — the
 * identical local re-implementation `assistant/admin-screen-link-tool.ts`'s
 * `resolveConfiguredPublicOrigin` already uses for the same structural reason (see this file's
 * header). Duplicated rather than shared, matching this codebase's own "duplicate the tiny helper,
 * never share it across features/files" convention (that file's own header cites the precedent).
 *
 * Unlike that helper, a PRESENT-but-invalid value throws here rather than degrading to `undefined`:
 * a bad value there only costs a relative link, but here returning `undefined` for a malformed value
 * would make `resolveExternalMcpOAuthRedirectUri` silently fall back to the derived origin —
 * localhost in dev — handing the provider a callback the operator never configured. The operator
 * override must win whenever it is present, so its invalidity cannot be indistinguishable from its
 * absence. `server/inbound/public-http/routes/oauth/public-origin.ts`'s `resolvePublicOrigin` fails
 * the same way for the same reason.
 *
 * @throws {ToolInputError} `TOVU_PUBLIC_URL` is set but is not a valid `http(s)` URL — named so the
 *   misconfiguration reaches the operator instead of silently resolving to the wrong origin.
 * @complexity O(1).
 */
function resolveConfiguredPublicOrigin(): string | undefined {
  const configured = process.env.TOVU_PUBLIC_URL?.trim();
  if (!configured) return undefined;
  let url: URL | undefined;
  try {
    url = new URL(configured);
  } catch {
    url = undefined;
  }
  if (url === undefined) {
    throw new ToolInputError({ message: `TOVU_PUBLIC_URL must be an absolute http(s) URL, but "${configured}" is not a valid URL.` });
  }
  if (url.protocol !== "http:" && url.protocol !== "https:") {
    throw new ToolInputError({ message: `TOVU_PUBLIC_URL must be an http(s) URL, got "${configured}".` });
  }
  return url.origin;
}

/**
 * Builds `external_mcp_oauth_connect`'s redirect URI for one server id, or `undefined` when NEITHER
 * an operator-configured origin nor a derived one is available.
 *
 * @param derivedPublicOrigin - `routeDeps.derivedPublicOrigin` — this process's own best-effort
 *   origin, read only when `TOVU_PUBLIC_URL` is unset. See this file's header ("2026-09-10") for why
 *   the precedence is one-directional: the operator override always wins when present.
 *
 * `undefined` rather than a throw when the derived origin is ALSO absent — see this file's header ("an
 * unset TOVU_PUBLIC_URL no longer blocks EVERY grant") for why `beginConnect`, not this function, is
 * what decides whether the caller's grant actually needs one. A PRESENT-but-invalid
 * `TOVU_PUBLIC_URL`, by contrast, throws (see {@link resolveConfiguredPublicOrigin}): it is never
 * masked by the derived origin.
 * @complexity O(1).
 */
function resolveExternalMcpOAuthRedirectUri(serverId: string, derivedPublicOrigin: string | undefined): string | undefined {
  const origin = resolveConfiguredPublicOrigin() ?? (derivedPublicOrigin || undefined);
  if (!origin) return undefined;
  return `${origin}${EXTERNAL_MCP_OAUTH_CALLBACK_PATH}/${encodeURIComponent(serverId)}`;
}

/** Reads `input[key]` as a string, or `undefined` for anything else — the same tri-state reading
 *  rule every other optional field in this domain's save path already follows (see `save-form.ts`'s
 *  header). @complexity O(1). */
function optionalStringField(input: Record<string, unknown>, key: string): string | undefined {
  return typeof input[key] === "string" ? (input[key] as string) : undefined;
}

/** Reads `input[key]` as a string, treating a blank (empty-after-trim) value the same as absent:
 *  `undefined`. For the handful of fields this form never prefills back with the stored secret —
 *  `env` (`save-form.ts:164`) and the OAuth client secret (`save-form.ts:212`) — the field hint tells
 *  the human "leave blank to keep the stored value", so a blank submission must carry forward what is
 *  already saved, not `optionalStringField`'s ordinary `""`. The store's own PUT contract still lets
 *  `""` mean "clear" ({@link resolveExternalMcpSealedEnv}, `resolveSealedOAuthBlob` in
 *  `external-mcp-store.ts`) for callers that DO round-trip the current value — that contract is
 *  unchanged; only this form's blank-means-absent mapping is fixed here.
 *  @complexity O(1). */
function optionalSecretField(input: Record<string, unknown>, key: string): string | undefined {
  const value = optionalStringField(input, key);
  return value === undefined || value === "" ? undefined : value;
}

/** The model's own {@link ExternalMcpSaveInput} fields beyond `id`/`transport` — every one of
 *  `SAVE_INPUT_SCHEMA`'s optional string properties (`agent-tools.ts`), read the same tri-state way
 *  the submitted form's own params are read below. */
const SAVE_MODEL_OPTIONAL_FIELDS = [
  "label",
  "command",
  "args",
  "url",
  "allowedToolNames",
  "writeAllowedToolNames",
  "authMode",
  "accessTokenEnvName",
  "oauthProviderId",
  "oauthGrant",
  "oauthClientId",
  "oauthScopes",
  "oauthTokenEnvName",
  "oauthAuthorizationEndpoint",
  "oauthTokenEndpoint",
  "oauthDeviceAuthorizationEndpoint",
] as const satisfies readonly (keyof ExternalMcpSaveInput)[];

/** Narrows the model's OWN `external_mcp_save` call input into {@link ExternalMcpSaveInput} — the
 *  shape `mergeExternalMcpSavePrefill`/`buildExternalMcpSaveForm` take to generate the form the
 *  human actually sees. `id` is normalized the same way `saveExternalMcpServer` itself normalizes
 *  it (trim + lowercase), so the existing-row lookup below matches what a prior save actually
 *  stored. @complexity O(1) — a fixed field list. */
function buildModelSaveInput(input: Record<string, unknown>): ExternalMcpSaveInput {
  if (Object.keys(input).some(key => key !== "id" && key !== "transport" && !SAVE_MODEL_OPTIONAL_FIELDS.some(field => field === key))) {
    throw new ToolInputError({ message: "external_mcp_save: credentials belong in the human form, never in this tool input. Nothing was saved." });
  }
  const id = requireString({ input, key: "id" }).trim().toLowerCase();
  const transport = requireString({ input, key: "transport" });
  let save: ExternalMcpSaveInput = { id, transport };
  for (const key of SAVE_MODEL_OPTIONAL_FIELDS) {
    const value = optionalStringField(input, key);
    if (value !== undefined) { assertCredentialFreeField({ value, field: key }); save = { ...save, [key]: value }; }
  }
  return save;
}

/** The submitted form field name -> {@link SaveExternalMcpOAuthInput} field name pairs —
 *  `save-form.ts`'s `buildOAuthCoreFields`/`buildOAuthTokenEnvField`/`buildOAuthEndpointFields` own
 *  the field NAMES on the rendered side; this is the one place that maps them back. */
const OAUTH_FORM_FIELD_MAP = [
  ["oauthProviderId", "providerId"],
  ["oauthGrant", "grant"],
  ["oauthClientId", "clientId"],
  ["oauthClientSecret", "clientSecret"],
  ["oauthScopes", "scopes"],
  ["oauthTokenEnvName", "tokenEnvName"],
  ["oauthAuthorizationEndpoint", "authorizationEndpoint"],
  ["oauthTokenEndpoint", "tokenEndpoint"],
  ["oauthDeviceAuthorizationEndpoint", "deviceAuthorizationEndpoint"],
] as const;

/** Builds the OAuth half of a save from the submitted form's params — only rendered fields are ever
 *  present (see this file's header), so an absent key here means the form never showed that field,
 *  not that the human left it blank. `undefined` when nothing OAuth-shaped was submitted.
 *  @complexity O(1) — a fixed field list. */
function buildOAuthSaveInputFromFormParams(params: Record<string, unknown>): SaveExternalMcpOAuthInput | undefined {
  let oauth: SaveExternalMcpOAuthInput = {};
  for (const [formKey, oauthKey] of OAUTH_FORM_FIELD_MAP) {
    // `oauthClientSecret` is the one OAuth field this form never prefills back with the stored value
    // (`save-form.ts:212`'s hint: "Leave blank to keep the stored secret") — every other OAuth field
    // IS prefilled from the existing row, so a blank one there is a genuine, intentional clear.
    const value = formKey === "oauthClientSecret" ? optionalSecretField(params, formKey) : optionalStringField(params, formKey);
    if (value !== undefined) oauth = { ...oauth, [oauthKey]: value };
  }
  return Object.keys(oauth).length === 0 ? undefined : oauth;
}

/**
 * Maps the human's SUBMITTED form (`answer.params`, already past the `received`/dismissed checks)
 * onto {@link SaveExternalMcpServerInput} — `saveExternalMcpServer`'s own input shape.
 *
 * `enabled: true` always: `save-form.ts`'s rendered fields never include an enabled toggle (this
 * tool's job is "connect a server", not "flip one that already exists off/on"), so every save this
 * tool ever performs both creates and enables, or re-enables, the row — matching the admin PUT
 * route's own default (`enabled: body.enabled !== false`) for the identical "caller sent nothing"
 * case. `writeAllowedToolNames` is read from the submitted form the same tri-state way
 * `allowedToolNames` is (`optionalStringField(params, ...) ?? ""`) — see `save-form.ts`'s
 * `writeAllowedToolNames` field/`mergeExternalMcpSavePrefill` for the field this reads and its
 * prefill-from-existing-row behavior. 2026-09-08 fix: this used to hardcode `""` unconditionally,
 * silently dropping every write grant on any save performed through the assistant — this domain's
 * form now has the field `SaveExternalMcpServerInput`'s own doc always assumed an un-migrated caller
 * would eventually grow (ADS-memory/reports/2026-09-08-dock-recovery-product-test.md).
 *
 * @complexity O(1) — a fixed field list.
 */
function buildSaveExternalMcpServerInputFromFormParams(
  params: Record<string, unknown>,
  workspaceId: UUID,
  principalId: string,
): SaveExternalMcpServerInput {
  const optionalFields = Object.fromEntries(
    ["label", "url", "authMode", "accessTokenEnvName"]
      .map(key => [key, optionalStringField(params, key)])
      .filter(([, value]) => value !== undefined),
  );
  const env = optionalSecretField(params, "env");
  const accessToken = optionalSecretField(params, "accessToken");
  const oauth = buildOAuthSaveInputFromFormParams(params);

  const serverIdRaw = params.id;
  const transportRaw = params.transport;
  if (typeof serverIdRaw !== "string" || typeof transportRaw !== "string") {
    // Both come from prepared state, formerly `baseParams` on every render — their absence means
    // the domain save port was called without this tool's bound destination.
    throw new Error("external_mcp_save: the submitted form is missing 'id' or 'transport'.");
  }

  return {
    workspaceId,
    serverId: serverIdRaw,
    transport: transportRaw,
    ...optionalFields,
    enabled: true,
    command: optionalStringField(params, "command") ?? "",
    args: optionalStringField(params, "args") ?? "",
    allowedToolNames: optionalStringField(params, "allowedToolNames") ?? "",
    writeAllowedToolNames: optionalStringField(params, "writeAllowedToolNames") ?? "",
    ...(env !== undefined ? { env } : {}),
    ...(accessToken !== undefined ? { accessToken } : {}),
    ...(oauth !== undefined ? { oauth } : {}),
    principalId,
  };
}

/**
 * `external_mcp_save`'s domain save port — kept separate from the engine's exchange lifecycle so
 * the field mapper, sealed store, probe and roster fan-out retain their own contracts.
 *
 * `ExternalMcpValidationError` is the one rejection a DIFFERENT form submission would fix, so it is
 * turned by the engine's error allowlist into the documented `{ saved: false, reason: 'invalid', ... }` result —
 * matching `agent-tools.ts`'s own description of this tool's return shapes.
 * `ExternalMcpSecretStoreUnconfiguredError` is deliberately NOT folded into that same branch: its own
 * doc states nothing the operator types can fix it, which is the opposite of what `reason: 'invalid'`
 * promises the model — it propagates to the engine's fixed storage-failure outcome instead.
 *
 * @complexity O(1) plus one `saveExternalMcpServer` call.
 */
async function saveSubmittedExternalMcpConfiguration(
  { routeDeps, principalId, values, save, locale, signal }: {
    routeDeps: ExternalMcpToolDeps; principalId: string; values: Readonly<Record<string, unknown>>;
    save: ExternalMcpSaveInput; locale: string; signal: AbortSignal;
  }, _optional = {},
): Promise<Record<string, unknown>> {
  // The field set is fixed per call. A submitted routing value cannot change the credential's
  // destination or switch to an auth/transport mode whose fields the human never reviewed.
  if (values.id !== undefined && values.id !== save.id) {
    throw new ExternalMcpValidationError("The server ID must match the connection form. Nothing was saved.", "id");
  }
  const params = { ...values, id: save.id, transport: save.transport, authMode: save.authMode };
  const saveInput = buildSaveExternalMcpServerInputFromFormParams(params, routeDeps.workspaceId, principalId);
  signal.throwIfAborted();
  const server = await saveExternalMcpServer(
    {
      repo: routeDeps.externalMcpServerRepo,
      sealer: routeDeps.siteAssistantSecretSealer,
      keyring: routeDeps.siteAssistantSecretKeyring,
      clock: routeDeps.clock,
    },
    saveInput,
  );
  // Same roster-change fan-out `put.ts`/`oauth-callback.ts` fire on their own save/connect success —
  // see `external-mcp-roster-change.ts`'s own header. Fire-and-forget: this chat-surface save
  // already succeeded and is durable regardless of whether any registered runtime reloads cleanly.
  void notifyExternalMcpRosterChanged();
  const { connection, connectionCode } = await probeSavedExternalMcpConfiguration({
    server, routeDeps, locale,
  });
  const hint = [formatCredentialHint({ hint: server.accessTokenHint, locale }), formatCredentialHints({ hints: server.envTokenHints, locale })].filter(Boolean).join(' · ');
  return { saved: true, server, connection: connectionCode, message: `${hint ? `${hint}. ` : ''}${connection}` };
}

/** Report reachability after a durable save; probe failure does not undo that save. */
async function probeSavedExternalMcpConfiguration(
  { server, routeDeps, locale }: {
    server: { transport: string; serverId: string };
    routeDeps: Pick<ExternalMcpToolDeps, "externalMcpProbe">;
    locale: string;
  }, _optional = {},
): Promise<{ connection: string; connectionCode: string }> {
  if (server.transport === "stdio" || !routeDeps.externalMcpProbe) {
    return { connectionCode: "not_tested", connection: credentialText({ id: "saved", locale }) };
  }
  try {
    const result = await routeDeps.externalMcpProbe({ serverId: server.serverId });
    const connectionCode = result.ok ? "connected" : String(result.body.code ?? "MCP_SERVER_UNREACHABLE");
    const id = result.ok ? "connected" : connectionCode === "MCP_AUTH_REJECTED" ? "auth" : connectionCode === "MCP_TIMEOUT" ? "timeout" : "unreachable";
    return { connectionCode, connection: credentialText({ id, locale }) };
  } catch {
    return { connectionCode: "MCP_SERVER_UNREACHABLE", connection: credentialText({ id: "unreachable", locale }) };
  }
}

/** Project the engine's classified run without exposing any submitted credential. */
function externalMcpSaveResult({ run, locale }: { run: SecretCardRun<Record<string, unknown>>; locale: string }, { validationField }: { validationField?: string } = {}): Record<string, unknown> {
  if (run.status === "saved") return run.saved;
  if (run.status === "cancelled") return { saved: false, cancelled: true };
  if (run.status === "blank") return { saved: false, cancelled: false, reason: "invalid", message: credentialText({ id: "blank", locale }) };
  if (run.status === "failed") return { saved: false, cancelled: false, reason: validationField === undefined ? "error" : "invalid", message: run.safeMessage,
    ...(validationField === undefined ? {} : { field: validationField }) };
  return { saved: false, cancelled: false, reason: run.status, note: run.status === "expired"
    ? "The user did not respond to the connection form before it expired. Nothing was saved."
    : "The connection form was closed because the run ended. Nothing was saved." };
}

/** Bind the domain form/save ports to Jini's one lifecycle owner.
 * @complexity O(s + f) during preparation in server views and fixed form fields, plus store/probe I/O.
 */
function externalMcpSaveHandler({ routeDeps, surfaces }: { routeDeps: ExternalMcpToolDeps; surfaces: AssistantSurfaceDeps }, _optional = {}): ToolHandler {
  return async (ctx, optional = {}) => {
    // Per-call metadata only: concurrent cards must not share a locale or validation field.
    // The engine owns redaction; this allowlist retains the domain's documented invalid/error shape.
    let validationField: string | undefined;
    let errorLocale = "en";
    const card = defineSecretCardTool<{
      save: ExternalMcpSaveInput; isUpdate: boolean; locale: string; principalId: string;
    }, Record<string, unknown>, Record<string, unknown>>({
      toolId: EXTERNAL_MCP_SAVE_TOOL_ID,
      prepare: async ({ ctx }) => {
        const input = requireInputRecord({ input: ctx.input });
        await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }),
          workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: EXTERNAL_MCP_MANAGE_PERMISSION }, { entityType: "external-mcp-server" });
        const locale = await resolveOperatorLocale({ deps: routeDeps, workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id });
        errorLocale = locale;
        const modelInput = buildModelSaveInput(input);
        const views = await listExternalMcpServerViews({ repo: routeDeps.externalMcpServerRepo, sealer: routeDeps.siteAssistantSecretSealer }, routeDeps.workspaceId);
        const existing = views.find(view => view.serverId === modelInput.id);
        return { save: mergeExternalMcpSavePrefill(modelInput, existing), isUpdate: existing !== undefined, locale, principalId: ctx.principal.id };
      },
      form: ({ prep }) => buildExternalMcpSaveForm({ save: prep.save, isUpdate: prep.isUpdate }),
      save: ({ values, prep, signal }) => saveSubmittedExternalMcpConfiguration({ routeDeps, values, ...prep, signal }),
      result: ({ prep, run }) => externalMcpSaveResult({ run, locale: prep.locale }, { validationField }),
      outcome: ({ prep, run }) => {
        if (run.status === "cancelled" || run.status === "expired" || run.status === "abandoned") return undefined;
        const result = externalMcpSaveResult({ run, locale: prep.locale }, { validationField });
        return {
          title: result.saved ? credentialText({ id: result.connection === "connected" ? "connected" : "savedTitle", locale: prep.locale }) : credentialText({ id: "unreachable", locale: prep.locale }),
          state: result.saved ? "success" : "failure",
          message: typeof result.message === "string" ? result.message : credentialText({ id: "unreachable", locale: prep.locale }),
        };
      },
    }, { uriHost: "tovu", frameSize: ["100%", "640px"], safeError: err => {
      if (err instanceof ExternalMcpValidationError) {
        validationField = err.field;
        return translateCredentialMessage({ message: err.message, locale: errorLocale });
      }
      return credentialText({ id: "storage", locale: errorLocale });
    }, text: {
      noEmitter: "external_mcp_save: this execution context has no interactive confirmation channel (no emitSurface), so a connection form cannot be shown here. Nothing was saved.",
      saveFailure: credentialText({ id: "storage", locale: "en" }),
    } });
    return card.handler({ surfaceExchanges: surfaces.surfaceExchanges, askThenReport })(ctx, optional);
  };
}

/** Reuse the daemon's configuration resolver when no live probe is wired. */
async function resolveExternalMcpConfigurationCheck(
  { routeDeps, id }: { routeDeps: ExternalMcpToolDeps; id: string }, _optional = {},
): Promise<{ ok: boolean; reason?: string }> {
  const { configs, failures } = await readEnabledExternalMcpConfigs(
    { repo: routeDeps.externalMcpServerRepo, sealer: routeDeps.siteAssistantSecretSealer, oauth: routeDeps.externalMcpOAuth?.tokenResolver },
    routeDeps.workspaceId,
  );
  if (configs.some((config) => config.serverId === id)) return { ok: true };
  const failure = failures.find((candidate) => candidate.serverId === id);
  return { ok: false, reason: failure?.reason ?? "this server's connection could not be resolved" };
}

/**
 * This wiring layer's OWN risk classification, authored from what each handler below actually
 * calls. See `DerivedRiskByToolId` in the kit for why it is independent of the catalog's own
 * `sideEffects` declaration.
 */
export const externalMcpDerivedRisk: DerivedRiskByToolId = new Map<string, AgentToolSideEffect>([
  // -> listExternalMcpServerViews(): a repo read, never unseals.
  ["external_mcp_list", "none"],
  // -> saveExternalMcpServer(): repo.upsert() plus a seal, gated behind the human's own form
  //    confirmation (ADR-055-style held-open exchange, same shape as content_post_delete).
  ["external_mcp_save", "mutates-durable-state"],
  // -> readEnabledExternalMcpConfigs(): OAuth token resolution may persist a refreshed grant.
  ["external_mcp_test_connection", "mutates-durable-state"],
  // -> externalMcpOAuth.beginConnect(): writes oauthStatus 'pending' (and, for a self-configuring
  //    connection, persists a minted client identity) before returning the authorization/device
  //    start. Durable.
  ["external_mcp_oauth_connect", "mutates-durable-state"],
  // -> externalMcpOAuth.pollDeviceAuthorization(): persists the access token on the 'connected'
  //    outcome, resets state on a terminal failure. Durable.
  ["external_mcp_oauth_poll_device", "mutates-durable-state"],
]);

export function buildExternalMcpRegistrations(routeDeps: ExternalMcpToolDeps, surfaces: AssistantSurfaceDeps): ToolRegistration[] {
  const handlers: Record<string, ToolHandler> = {
    external_mcp_list: async (ctx) => {
      requireNoInput({ input: ctx.input });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }),
        workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: EXTERNAL_MCP_MANAGE_PERMISSION }, { entityType: "external-mcp-server" });

      const servers = await listExternalMcpServerViews({ repo: routeDeps.externalMcpServerRepo, sealer: routeDeps.siteAssistantSecretSealer }, routeDeps.workspaceId);
      return { servers };
    },

    /**
     * See this file's header ("`external_mcp_save`: one call, held open"). Fails closed rather than
     * degrade when this execution context cannot show a dialog — same posture `content_post_delete`
     * and `deployment_propose_custom_provider_credential` both take for the identical case: a form
     * this tool exists specifically to render cannot be skipped without abandoning the "never saves
     * silently" guarantee `agent-tools.ts`'s own description makes.
     */
    external_mcp_save: externalMcpSaveHandler({ routeDeps, surfaces }),

    /** See this file's header ("`external_mcp_test_connection` never opens a socket"). */
    external_mcp_test_connection: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      const id = requireString({ input, key: "id" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }),
        workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: EXTERNAL_MCP_MANAGE_PERMISSION }, { entityType: "external-mcp-server",
        entityId: id });

      const record = await routeDeps.externalMcpServerRepo.findByServerId({ workspaceId: routeDeps.workspaceId, serverId: id });
      if (!record) return { ok: false, reason: `no external MCP server is configured as '${id}'` };
      if (!record.enabled) return { ok: false, reason: "this server is disabled" };

      if (routeDeps.externalMcpProbe) {
        const probe = await routeDeps.externalMcpProbe({ serverId: id });
        return !probe.ok && probe.body.code === "MCP_AUTH_REJECTED" && record.authMode === "static_env"
          ? { ...probe, credentialSetup: issueCredentialSetup({ setupToolId: "external_mcp_save", prefill: { id } }, {}) }
          : probe;
      }

      return resolveExternalMcpConfigurationCheck({ routeDeps, id });
    },

    /** See this file's header ("`external_mcp_oauth_connect` has no live HTTP request"). */
    external_mcp_oauth_connect: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      const id = requireString({ input, key: "id" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }),
        workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: EXTERNAL_MCP_MANAGE_PERMISSION }, { entityType: "external-mcp-server",
        entityId: id });

      if (!routeDeps.externalMcpOAuth) {
        throw new Error(
          `external_mcp_oauth_connect: this execution context has no OAuth service wired, so an authorization ` +
            `cannot be started here. Ask the operator to connect '${id}' from Settings → External MCP instead.`,
        );
      }

      const redirectUri = resolveExternalMcpOAuthRedirectUri(id, routeDeps.derivedPublicOrigin);
      try {
        return await routeDeps.externalMcpOAuth.beginConnect({ serverId: id, ...(redirectUri === undefined ? {} : { redirectUri }) });
      } catch (error) {
        // `ExternalMcpValidationError` is exactly "the caller named something this connection cannot
        // do, and a different input or one config change fixes it" — an unknown id, a non-OAuth row,
        // or (since 2026-09-09) an authorization_code grant with no configured public origin. As a
        // bare `Error` those all reach the model redacted, which is how a clearly-worded refusal
        // naming TOVU_PUBLIC_URL became, in practice, a silent one. Nothing internal is in these
        // messages beyond the server id the caller already sent.
        if (error instanceof ExternalMcpValidationError) throw new ToolInputError({ message: error.message });
        throw error;
      }
    },

    external_mcp_oauth_poll_device: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      const id = requireString({ input, key: "id" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }),
        workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: EXTERNAL_MCP_MANAGE_PERMISSION }, { entityType: "external-mcp-server",
        entityId: id });

      if (!routeDeps.externalMcpOAuth) {
        throw new Error(
          "external_mcp_oauth_poll_device: this execution context has no OAuth service wired, so this device " +
            "authorization cannot be polled here.",
        );
      }

      const result = await routeDeps.externalMcpOAuth.pollDeviceAuthorization({ serverId: id });
      // Same roster-change fan-out as a completed browser OAuth callback — a device-flow connection
      // becomes usable at exactly this "connected" transition, not at every "pending" poll in between.
      if (result.status === "connected") void notifyExternalMcpRosterChanged();
      return result;
    },
  };

  // No `unwiredToolIds`: External MCP wires its ENTIRE catalog, same tripwire discipline as
  // Posts/Themes/Plugins — a 6th catalog entry added without a handler fails the build.
  return buildDomainRegistrations({ metadata: toolMetadata,
    domain: "external-mcp",
    catalogModule: "features/external-mcp/agent-tools.ts",
    catalog: CATALOG_BY_ID,
    handlers,
    derivedRisk: externalMcpDerivedRisk,
  });
}

/**
 * Contributes External MCP's AI tools to the assistant's catalog — called once by
 * `server/runtime/composition/tool-catalog-manifest.ts`'s `installFirstPartyToolContributors()`, not
 * by importing this module. See this file's header for what was unreachable before this existed.
 */
export function contributeExternalMcpTools({ probe }: { probe?: (deps: ExternalMcpToolDeps, serverId: string) => Promise<{ ok: boolean; body: Readonly<Record<string, unknown>> }> } = {}, _optional = {}): ToolContributor {
  return { domain: "external-mcp", build: (deps, surfaces) => buildExternalMcpRegistrations({ ...deps, ...(probe ? { externalMcpProbe: ({ serverId }: { serverId: string }) => probe(deps, serverId) } : {}) }, surfaces), risk: externalMcpDerivedRisk };
}

import type { FormDestinationAddress, FormDestinationKit, FormDestinationModule, FormDestinationPage, RemoteFormSubmission } from "./types.js";

/**
 * @file Pulls a form destination's pending submissions into Tovu, page by page, and acknowledges
 * only the rows the import committed, so a row is never lost between the receiver and Tovu: an
 * unacknowledged row is simply pulled again and the import's receipts absorb the repeat. Generic:
 * the destination is any module that implements `pull` and `ack`.
 */
const DEFAULT_MAX_PAGES = 10;
const DEFAULT_PAGE_SIZE = 50;

/** The longest one receiver request may wait during a pull. A module's own, longer timeout is cut to
 * this, so the pull's duration is bounded by the host rather than by whichever plugin is installed. */
export const FORM_PULL_REQUEST_TIMEOUT_MS = 15_000;

/** Wall-clock time after which a pull starts no further page (it reports `hasMore` instead). A time
 * budget, not a request count: a module may make any number of requests per page. */
export const FORM_PULL_BUDGET_MS = 300_000;

/** Covers the last page's import (local store work, ≤ 50 rows) and clock drift between processes. */
const FORM_PULL_LEASE_MARGIN_MS = 60_000;

/**
 * How long a pull holds its receiver's lease (`withFormPullLease`). It must outlast the slowest pull,
 * or a second pull could start on the same receiver while the first is still importing.
 * Proof: no page starts after {@link FORM_PULL_BUDGET_MS}; every request the pull's kit makes waits
 * at most until budget + one request (15 s), and a request asked for after that is refused at once.
 * So all network waiting ends by 315 s, and what can follow is the local import of the page in
 * hand, which the margin covers: 375 s. An expired lease is free again, so a crashed pull blocks the
 * receiver for at most this long. Pinned by `__tests__/pull.unit.test.ts`.
 */
export const FORM_PULL_LEASE_MS = FORM_PULL_BUDGET_MS + FORM_PULL_REQUEST_TIMEOUT_MS + FORM_PULL_LEASE_MARGIN_MS;

/** The import step, injected so this module stays independent of the forms feature. */
export type FormDestinationImportPort<R extends { readonly committedIds: readonly string[] }> =
  (required: { readonly items: readonly RemoteFormSubmission[]; readonly destinationKey: string }) => Promise<R>;

/** Stable identity of one receiver for dedupe: its scope and origin. @complexity O(1). */
export function formDestinationKey({ scope, url }: { scope: string; url: string }, _optional = {}): string {
  return `${scope}:${new URL(url).origin}`;
}

/**
 * Pull, import, acknowledge, for up to `maxPages` pages and {@link FORM_PULL_BUDGET_MS}. `hasMore`
 * stays true when the page cap or the time budget stopped the loop, so the caller can say "pull
 * again". Errors name the address, never the key.
 * @param optional.now the wall clock in ms (default `Date.now`), for tests.
 * @complexity O(maxPages * pageSize) rows; two module calls per page.
 */
export async function pullFromFormDestination<R extends { readonly committedIds: readonly string[] }>(
  required: { module: Pick<FormDestinationModule, "pull" | "ack">; scope: string; destination: FormDestinationAddress; kit: FormDestinationKit; importPage: FormDestinationImportPort<R> },
  optional: { maxPages?: number; pageSize?: number; now?: () => number } = {},
): Promise<{ destinationKey: string; pulled: number; acknowledged: number; hasMore: boolean; pages: R[] }> {
  const { module, scope, destination, importPage } = required;
  const { maxPages = DEFAULT_MAX_PAGES, pageSize: limit = DEFAULT_PAGE_SIZE, now = Date.now } = optional;
  const budgetEndsMs = now() + FORM_PULL_BUDGET_MS;
  const kit = boundedKit({ kit: required.kit, now, deadlineMs: budgetEndsMs + FORM_PULL_REQUEST_TIMEOUT_MS });
  const { pull, ack } = module;
  if (!pull || !ack) throw new Error(`no installed form destination returns submissions for ${scope}. Turn on the plugin that provides it (or republish the site to a host that receives forms), then pull again.`);
  const destinationKey = formDestinationKey({ scope, url: destination.url });
  const report = { destinationKey, pulled: 0, acknowledged: 0, hasMore: false, pages: [] as R[] };
  try {
    await pullPages({ report, maxPages, outOfTime: () => now() >= budgetEndsMs,
      pullPage: (after) => pull.call(module, { kit, destination }, { after, limit }),
      importPage: (items) => importPage({ items, destinationKey }),
      acknowledge: (ids) => ack.call(module, { kit, destination, ids }) });
  } catch (error) {
    throw pullStopped({ error, destination });
  }
  return report;
}

/** The page loop: pull, import, acknowledge, until the host has no more rows, `maxPages`, or
 * `outOfTime`. Fills `report`; `hasMore` stays as the last page said when the cap or the clock stops
 * the loop. @throws whatever a step throws. @complexity O(maxPages) steps. */
async function pullPages<R extends { readonly committedIds: readonly string[] }>(required: {
  report: { pulled: number; acknowledged: number; hasMore: boolean; pages: R[] };
  maxPages: number;
  outOfTime: () => boolean;
  pullPage: (after: number) => Promise<FormDestinationPage>;
  importPage: (items: readonly RemoteFormSubmission[]) => Promise<R>;
  acknowledge: (ids: readonly string[]) => Promise<{ readonly acknowledged: number }>;
}): Promise<void> {
  const { report } = required;
  let after = 0;
  for (let page = 0; page < required.maxPages; page += 1) {
    // Out of time: the rows still waiting are the next pull's, exactly as when the page cap stops.
    if (required.outOfTime()) break;
    const batch = await required.pullPage(after);
    report.hasMore = batch.hasMore;
    if (batch.items.length === 0) break;
    report.pulled += batch.items.length;
    const imported = await required.importPage(batch.items);
    report.pages.push(imported);
    report.acknowledged += await acknowledgeCommitted({ acknowledge: required.acknowledge, committedIds: imported.committedIds });
    after = batch.nextAfter;
    if (!batch.hasMore) break;
  }
}

/** The caller's kit with every request's timeout capped at {@link FORM_PULL_REQUEST_TIMEOUT_MS} and at
 * the time left before `deadlineMs`; a request asked for after the deadline is refused unsent.
 * @complexity O(1). */
function boundedKit({ kit, now, deadlineMs }: { kit: FormDestinationKit; now: () => number; deadlineMs: number }, _optional = {}): FormDestinationKit {
  return { ...kit, fetch: (url, init, options) => {
    const leftMs = deadlineMs - now();
    if (leftMs <= 0) return Promise.reject(new Error(`the pull used up its ${FORM_PULL_BUDGET_MS / 1000} s time budget`));
    return kit.fetch(url, init, { ...options, timeoutMs: Math.min(options.timeoutMs, FORM_PULL_REQUEST_TIMEOUT_MS, leftMs) });
  } };
}

/** Acknowledges each committed id once; no request when nothing was committed. @complexity O(ids). */
async function acknowledgeCommitted(
  required: { acknowledge: (ids: readonly string[]) => Promise<{ readonly acknowledged: number }>; committedIds: readonly string[] },
  _optional: Record<string, never> = {},
): Promise<number> {
  const ids = [...new Set(required.committedIds)];
  return ids.length > 0 ? (await required.acknowledge(ids)).acknowledged : 0;
}

/** The person-facing stop error: names the address, never the key. @complexity O(message bytes). */
function pullStopped({ error, destination }: { error: unknown; destination: FormDestinationAddress }, _optional = {}): Error {
  const message = (error instanceof Error ? error.message : String(error)).replaceAll(destination.secret, "[redacted]");
  // `cause` keeps the original stack for the server log; the caller redacts the key before logging it.
  return new Error(`pulling form submissions from ${new URL(destination.url).origin} stopped: ${message}. Rows not yet acknowledged stay at the host; pull again later.`, { cause: error });
}

import path from "node:path";

import { defineExecutablePluginContribution, type LoadPluginContributions, loadPluginContributionsFromSource, type TrustedPluginPackage } from "#src/features/agent-plugins/lifecycle";

import type { FormDestinationDescriptor, FormDestinationModule, FormDestinationRegistry, LoadedFormDestination } from "./types.js";

/**
 * @file Loads the form destinations Agent Plugins contribute: a copy of the mail-adapter
 * contribution (`features/agent-plugins/mail-adapter-registry.ts`) on Jini's
 * `defineExecutablePluginContribution`, so there is no new loader.
 *
 * A plugin opts in by shipping {@link FORM_DESTINATIONS_FILENAME} at its root: a data-only list of
 * `{ id, label, module, receive?, hosts?, credentialLabel? }`. `module` is a plain-JS `.mjs` file
 * inside the plugin whose default export is a `FormDestinationModule` (`./types.ts`).
 *
 * TRUST RULE (fail closed), the shared gate in `features/agent-plugins/trusted-plugin-files.ts`: a
 * module runs in this process, so it loads only when the plugin is ACTIVE, its installed digest is
 * the one `bundled-digests.json` records (only plugins Tovu shipped), and the module path stays
 * inside the plugin root and ends in `.mjs`. An id two plugins declare, or a host two co-hosted
 * destinations claim, is dropped for both ("refusing to guess", as the deploy-target registry does).
 * Every drop is reported in `refusals`, never thrown.
 */

/** The file a plugin ships at its root to contribute form destinations. */
export const FORM_DESTINATIONS_FILENAME = "tovu-form-destinations.json";

const DESTINATION_ID_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const MAX_ID_LENGTH = 64;
const MAX_LABEL_LENGTH = 100;
const RECEIVE_MODES: ReadonlySet<unknown> = new Set(["co-hosted", "external"]);

type ParseResult = { readonly ok: true; readonly descriptors: readonly FormDestinationDescriptor[] } | { readonly ok: false; readonly reason: string };

const destinationContribution = defineExecutablePluginContribution<FormDestinationDescriptor, FormDestinationModule>({
  filename: FORM_DESTINATIONS_FILENAME, contribution: "form destinations",
  parse: ({ raw }) => parseFormDestinationsFile(raw), modulePath: ({ descriptor }) => descriptor.module,
  validate: ({ exported }) => (isPlainObject(exported) ? exported as FormDestinationModule : "its module's default export is not an object"),
  refusal: ({ plugin, descriptor, reason }) => `form destination '${descriptor.id}' from '${plugin.pluginId}' was not loaded: ${reason}`,
});

/**
 * Builds this workspace's form destination registry from its installed Agent Plugins. Read fresh on
 * each call; Node caches each module import per file URL, and installed digest directories never change.
 *
 * @throws Nothing for a plugin-level fault; only a filesystem fault listing the package directory itself.
 * @param required - Contribution loader from this boot's lifecycle; no site-dependent module default.
 * @complexity O(p) installed plugins, one small read plus one import per declared destination.
 */
export async function loadFormDestinationRegistry(ctx: { readonly workspaceId: string }, required: { readonly loadContributions: LoadPluginContributions }): Promise<FormDestinationRegistry> {
  const load = await required.loadContributions({ ...ctx, definition: destinationContribution }, { orderByPluginId: true });
  return buildFormDestinationRegistry({ loaded: load.items, refusals: load.refusals });
}

/**
 * A registry read straight from a plugin's SOURCE directory, with no install, activation or digest
 * gate. For tests only, where the directory is this product's own `content/agent-plugins/<id>/`.
 *
 * @complexity O(d) destinations, one import each.
 */
export async function loadFormDestinationRegistryFromSource(plugin: TrustedPluginPackage, _optional: Record<string, never> = {}): Promise<FormDestinationRegistry> {
  const load = await loadPluginContributionsFromSource({ plugin, definition: destinationContribution });
  return buildFormDestinationRegistry({ loaded: load.items, refusals: load.refusals });
}

/**
 * Indexes loaded destinations: drops a module missing the methods its receive mode needs, every id
 * more than one plugin declares, and every host more than one co-hosted destination claims. Pure.
 * @complexity O(n * h) for n loaded destinations with h hosts each.
 */
export function buildFormDestinationRegistry(required: { readonly loaded: readonly LoadedFormDestination[]; readonly refusals: readonly string[] }, _optional: Record<string, never> = {}): FormDestinationRegistry {
  const refusals = [...required.refusals];
  const complete = required.loaded.filter((entry) => {
    const missing = missingMethods({ entry });
    if (missing) refusals.push(`form destination '${entry.descriptor.id}' from '${entry.pluginId}' was not loaded: ${missing}`);
    return !missing;
  });
  const unique = dropShared({ entries: complete, keysOf: (entry) => [entry.descriptor.id], refusals, what: (id) => `form destination '${id}'`, why: "more than one plugin declares it" });
  const unclaimed = dropShared({ entries: unique, keysOf: (entry) => (entry.descriptor.receive === "co-hosted" ? entry.descriptor.hosts ?? [] : []), refusals,
    what: (host) => `form receiver for host '${host}'`, why: "more than one co-hosted destination claims it" });
  return {
    list: () => unclaimed,
    get: (id) => unclaimed.find((entry) => entry.descriptor.id === id),
    resolve: ({ scope }) => unclaimed.find((entry) => entry.descriptor.id === scope)
      ?? unclaimed.find((entry) => entry.descriptor.receive === "co-hosted" && entry.descriptor.hosts?.includes(scope)),
    refusals,
  };
}

/** The methods the descriptor's receive mode needs that the module lacks, as a reason, or nothing. @complexity O(1). */
function missingMethods({ entry }: { entry: LoadedFormDestination }, _optional = {}): string | undefined {
  const { descriptor: { receive }, module } = entry;
  if (receive && (typeof module.pull !== "function" || typeof module.ack !== "function")) return "a destination that receives submissions needs pull() and ack()";
  if (receive === "external" && typeof module.prepare !== "function") return "an external receiver needs prepare()";
  if (!receive && typeof module.deliver !== "function") return "a destination that does not receive submissions needs deliver()";
  return undefined;
}

/** Keeps the entries none of whose keys another entry shares; each shared key is one refusal line.
 * @complexity O(n * k) for n entries with k keys each. */
function dropShared(
  required: { entries: readonly LoadedFormDestination[]; keysOf: (entry: LoadedFormDestination) => readonly string[]; refusals: string[]; what: (key: string) => string; why: string },
  _optional: Record<string, never> = {},
): LoadedFormDestination[] {
  const { entries, keysOf, refusals, what, why } = required;
  const claimants = new Map<string, LoadedFormDestination[]>();
  for (const entry of entries) for (const key of new Set(keysOf(entry))) claimants.set(key, [...(claimants.get(key) ?? []), entry]);
  const dropped = new Set<LoadedFormDestination>();
  for (const [key, owners] of claimants) {
    if (owners.length < 2) continue;
    owners.forEach((owner) => dropped.add(owner));
    refusals.push(`${what(key)} was not loaded: ${why} (${owners.map((owner) => `'${owner.pluginId}'`).sort().join(", ")})`);
  }
  return entries.filter((entry) => !dropped.has(entry));
}

/**
 * Parses a plugin's {@link FORM_DESTINATIONS_FILENAME}. Pure. Unknown keys are ignored.
 *
 * @complexity O(d) in the declared destination count.
 */
export function parseFormDestinationsFile(raw: string): ParseResult {
  let value: unknown;
  try {
    value = JSON.parse(raw);
  } catch {
    return { ok: false, reason: "not valid JSON" };
  }
  if (!isPlainObject(value) || value.schemaVersion !== 1) return { ok: false, reason: "schemaVersion must be 1" };
  if (!Array.isArray(value.destinations)) return { ok: false, reason: "destinations must be an array" };

  const descriptors: FormDestinationDescriptor[] = [];
  for (const [index, entry] of value.destinations.entries()) {
    const result = parseDescriptor(entry, `destinations[${index}]`);
    if (typeof result === "string") return { ok: false, reason: result };
    if (descriptors.some((seen) => seen.id === result.id)) return { ok: false, reason: `destinations[${index}].id '${result.id}' is declared twice` };
    descriptors.push(result);
  }
  return { ok: true, descriptors };
}

/** One descriptor entry, or the reason it is invalid. @complexity O(h) in the declared hosts. */
function parseDescriptor(entry: unknown, at: string): FormDestinationDescriptor | string {
  if (!isPlainObject(entry)) return `${at} must be an object`;
  const { id, label, module } = entry;
  if (!isId(id)) return `${at}.id must be a lowercase hyphenated id`;
  if (!isLabel(label)) return `${at}.label must be a non-empty string`;
  if (typeof module !== "string" || !module.endsWith(".mjs") || path.posix.isAbsolute(module)) return `${at}.module must be a relative path ending in .mjs`;
  const options = parseReceiveOptions(entry, at);
  return typeof options === "string" ? options : { id, label, module, ...options };
}

/** The optional receive fields: mode, co-hosting targets and vendor credential label. @complexity O(h). */
function parseReceiveOptions(entry: Readonly<Record<string, unknown>>, at: string): Pick<FormDestinationDescriptor, "receive" | "hosts" | "credentialLabel"> | string {
  const reason = receiveOptionsReason(entry, at);
  if (reason) return reason;
  const { receive, hosts, credentialLabel } = entry as Pick<FormDestinationDescriptor, "receive" | "hosts" | "credentialLabel">;
  return { ...(receive ? { receive } : {}), ...(hosts ? { hosts } : {}), ...(credentialLabel ? { credentialLabel } : {}) };
}

/** Why the optional receive fields are invalid, or nothing. @complexity O(h). */
function receiveOptionsReason({ receive, hosts, credentialLabel }: Readonly<Record<string, unknown>>, at: string): string | undefined {
  if (receive !== undefined && !RECEIVE_MODES.has(receive)) return `${at}.receive must be "co-hosted" or "external"`;
  if (hosts !== undefined && !isHostList(hosts)) return `${at}.hosts must be an array of hosting target ids`;
  if (receive === "co-hosted" && !(hosts as string[] | undefined)?.length) return `${at}.hosts must name at least one hosting target for a co-hosted receiver`;
  if (credentialLabel !== undefined && !isLabel(credentialLabel)) return `${at}.credentialLabel must be a non-empty string`;
  return undefined;
}

function isHostList(value: unknown): value is string[] {
  return Array.isArray(value) && value.every(isId);
}

function isId(value: unknown): value is string {
  return typeof value === "string" && value.length <= MAX_ID_LENGTH && DESTINATION_ID_PATTERN.test(value);
}

function isLabel(value: unknown): value is string {
  return typeof value === "string" && value.trim() !== "" && value.length <= MAX_LABEL_LENGTH;
}

function isPlainObject(value: unknown): value is Readonly<Record<string, unknown>> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

import type { DeployFile } from "@jini-ai/devops/deploy";

/**
 * @file Points an exported site's forms at an external receiver. Tovu renders every form with
 * `action="/forms/<slug>/submit"`; a co-hosted receiver serves that path itself, so only an external
 * one needs the pages rewritten. The receiver key never enters HTML: it authorizes pulls, not posts.
 * Pure: `DeployFile.data` is already in memory.
 */

const FORM_ACTION = /action="\/forms\/([A-Za-z0-9_-]+)\/submit"/g;
const HTML_ESCAPES: Readonly<Record<string, string>> = { "&": "&amp;", "\"": "&quot;", "<": "&lt;", ">": "&gt;" };

/**
 * The receiver's base address: an https origin plus an optional path, with no userinfo, query or
 * fragment, and no trailing slash. Throws a person-facing Error otherwise.
 * @complexity O(url length).
 */
export function assertSubmitUrl({ submitUrl }: { submitUrl: string }, _optional: Record<string, never> = {}): string {
  let parsed: URL | undefined;
  try { parsed = new URL(submitUrl); } catch { parsed = undefined; }
  if (!parsed || !isPlainHttps({ parsed, raw: submitUrl })) throw new Error("the form destination returned a post address that is not a plain https URL (no user name, query or fragment). Update or reinstall the destination's plugin, then publish again");
  return `${parsed.origin}${parsed.pathname.replace(/\/+$/, "")}`;
}

/** https with no userinfo, query or fragment (an empty `?` or `#` counts too). @complexity O(url length). */
function isPlainHttps({ parsed, raw }: { parsed: URL; raw: string }, _optional = {}): boolean {
  return parsed.protocol === "https:" && [parsed.username, parsed.password, parsed.search, parsed.hash].every((part) => part === "") && !/[?#]/.test(raw);
}

/**
 * Rewrites only the exact Tovu form actions in `.html` files to `${submitUrl}/forms/<slug>/submit`;
 * other actions, already-absolute actions and non-HTML files are returned unchanged.
 * @complexity O(total HTML bytes).
 */
export function rewriteFormActions(required: { files: readonly DeployFile[]; submitUrl: string }, _optional: Record<string, never> = {}): DeployFile[] {
  const base = assertSubmitUrl({ submitUrl: required.submitUrl }).replace(/[&"<>]/g, (char) => HTML_ESCAPES[char]!);
  return required.files.map((file) => {
    if (!file.file.toLowerCase().endsWith(".html")) return file;
    const text = typeof file.data === "string" ? file.data : file.data.toString("utf8");
    const rewritten = text.replace(FORM_ACTION, (_match, slug: string) => `action="${base}/forms/${slug}/submit"`);
    if (rewritten === text) return file;
    return { ...file, data: typeof file.data === "string" ? rewritten : Buffer.from(rewritten, "utf8") };
  });
}

/**
 * @file The Forms agent-tool catalog (SPEC-010, ADR-PIPE-010), instantiating SPEC-016 REQ-22's
 * naming/callability convention for this domain — the same shape
 * `features/content-types/agent-tools.ts` uses, including its `inputSchema` contract.
 *
 * Purpose:
 * A static, in-process catalog describing every agent-callable tool this domain exposes and the
 * permission each carries. Every entry maps 1:1 onto a real exported function of
 * `forms/write-service.ts` — this catalog never names an operation the domain cannot perform.
 *
 * Deliberate absences (the point of a catalog, not an oversight):
 * - There is NO `forms_delete_definition`, and no description here may imply one. A form
 *   definition is removed permanently only by a Trash purge under the owner's policy, never
 *   through this catalog's tools, and
 *   `FormDefinitionRepoPort` enforces that structurally by exposing no `delete` method at all.
 *   "Delete this form" must therefore route an agent to `forms_set_definition_status` (to disable
 *   it) or to the Trash's own tools — never to a lever that does not exist here. This mirrors
 *   `features/recovery/agent-tools.ts`'s identical discipline around `backup_confirm_restore`.
 * - Submissions carry a separate permission tier (`admin.forms.submissions.*`) that does not go
 *   through `write-service.ts` — `routes/admin/forms/{list,get,delete}-submissions.ts` gate
 *   directly, the same split `comments/agent-tools.ts` makes for its read tools. Read access
 *   (`forms_list_submissions`/`forms_get_submission`) IS wired below: a `FormSubmissionRecord` is
 *   `{id, formDefinitionId, data, sourceIp, submittedAt}` (`types.ts`) — the same visitor-typed
 *   field values plus one raw request IP the human admin submissions screen already displays, no
 *   payment or credential material of any kind, so listing/reading what a human operator can
 *   already see through the same permission is not a new exposure. There is deliberately NO
 *   `forms_delete_submission`: unlike a form definition (which only ever gets soft-retired) a
 *   submission's delete is genuinely irreversible and, unlike `identity_role_delete`/
 *   `identity_policy_delete`, carries no "still referenced, so refuse" guard at all — nothing stops
 *   a single call from permanently destroying a visitor's data with no way back. That asymmetry
 *   (reversible read vs. unconditional permanent write) is exactly the read/write split this pass's
 *   directive asks for; delete stays human-UI-only. (Since trash T4, `trash_item` can move a
 *   submission to the Trash, restorable for 60 days; that is not a permanent delete, and
 *   `forms_list_submissions`' description points the model there.)
 *
 * How it relates to the project:
 * `assistant/tool-registrations.ts` maps these entries into `@jini-ai/core` `ToolRegistration`s;
 * the ADR-014 tool filter consumes the catalog to decide which names a session may see. Actual
 * enforcement is `executeCommand`'s ADR-021 `authorize()` inside each write-service function —
 * this module declares shape only and performs no I/O.
 *
 * Architectural role:
 * `forms` domain declaration. Imports only the constants its own domain already enforces, so the
 * published JSON Schemas cannot drift from the validators. Deliberately does NOT import
 * `./manifest` (ADR-PIPE-010 Enforcement: the manifest is read BY activation code, never BY domain
 * code) — the field-type list is taken from `@jini-ai/cms/forms`, which now owns the validators
 * and their rationale.
 */

import type { AgentToolDefinition as SharedAgentToolDefinition } from "@jini-ai/core";
import {
  ATTRIBUTE_NAME_PATTERN,
  FIELD_ID_PATTERN,
  FIELD_TYPES,
  MAX_ATTRIBUTES_PER_FIELD,
  MAX_ATTRIBUTE_VALUE_LENGTH,
  MAX_CLASS_NAME_LENGTH,
  MAX_FIELDS,
  MAX_LABEL_LENGTH,
  MAX_MAX_LENGTH,
  MIN_MAX_LENGTH,
} from "@jini-ai/cms/forms";
import { MAX_NAME_LENGTH, MAX_NOTIFY_RECIPIENTS, SLUG_PATTERN } from "@jini-ai/cms/forms";

export type AgentToolSideEffect = "none" | "mutates-durable-state" | "mints-token";

export type AgentToolActorClassRule = "confirmer-must-equal-own-delegatedBy" | "user-only" | "none";

/**
 * JSON Schema for this tool's `input`, published to the model via `ToolDescriptor.inputSchema`
 * (`assistant/tool-registrations.ts`, which refuses to wire any tool lacking one). Structurally
 * identical to the content-types catalog's field of the same name.
 */
export type AgentToolDefinition = SharedAgentToolDefinition & { sideEffects: AgentToolSideEffect };

/** One entry of a `fields` array, as published to the model. Mirrors what `forms.ts`'s `validateFieldDescriptors` enforces. */
const FIELD_DESCRIPTOR_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["id", "label", "type", "required"],
  properties: {
    id: {
      type: "string",
      pattern: FIELD_ID_PATTERN.source,
      description: "Stable field id. Lowercase letters, digits and underscores; must start with a letter. Ids are permanent — an existing id can never be removed by an update.",
    },
    label: { type: "string", minLength: 1, maxLength: MAX_LABEL_LENGTH, description: "Human-readable label shown above the input." },
    type: {
      type: "string",
      enum: [...FIELD_TYPES],
      description: "A registered native field type. Use select for a dropdown; multi-select, radio and checkbox-group require options. Phone renders type=tel, datetime renders datetime-local, toggle renders an accessible switch.",
    },
    required: { type: "boolean", description: "Whether the visitor must fill this field in. Must be a real boolean, not a string. Required checkbox/toggle consent must be checked." },
    name: { type: "string", pattern: FIELD_ID_PATTERN.source, description: "Optional native input name; must equal id to preserve stored submission keys." },
    placeholder: { type: "string", maxLength: 500 },
    helpText: { type: "string", maxLength: 500, description: "Accessible help shown with the field." },
    default: { oneOf: [{ type: "string" }, { type: "number" }, { type: "boolean" }, { type: "array", maxItems: 100, items: { type: "string" } }], description: "Initial control value, checked state, or selected option values. Must satisfy this field's rules; forbidden for files." },
    options: { type: "array", minItems: 1, maxItems: 100, items: { type: "object", additionalProperties: false, required: ["value", "label"], properties: { value: { type: "string", minLength: 1, maxLength: 200 }, label: { type: "string", minLength: 1, maxLength: 200 } } }, description: "Required for select, multi-select, radio, checkbox-group. Values must be unique; submissions reject values outside this list." },
    minLength: { type: "integer", minimum: 0, maximum: MAX_MAX_LENGTH },
    pattern: { type: "string", maxLength: 300, description: "Full-match text validation. Safe subset: literals, character classes, anchors and one repetition; groups, alternation and backreferences are rejected." },
    min: { type: ["number", "string"], description: "Numeric lower bound, or ISO native date/time lower bound." },
    max: { type: ["number", "string"], description: "Numeric upper bound, or ISO native date/time upper bound." },
    step: { type: "number", exclusiveMinimum: 0, description: "Numeric increment for number/range. Defaults to 1." },
    accept: { type: "array", minItems: 1, maxItems: 20, items: { type: "string" }, description: "Safe MIME types or image/*, video/*, */*. Omitted means any recognized safe file: PNG/JPEG/GIF/WebP/AVIF, MP4/WebM, PDF. Executables, scripts, markup and archives are always refused." },
    maxFileSize: { type: "integer", minimum: 1, maximum: 10485760, description: "File size limit in bytes, capped at 10 MiB. All uploads in one multipart POST must fit 12 MiB." },
    checkboxValue: { type: "string", description: "Optional authored checkbox wire value; every other submitted string is rejected." },
    maxLength: {
      type: ["integer", "null"],
      minimum: MIN_MAX_LENGTH,
      maximum: MAX_MAX_LENGTH,
      description: `Optional per-field character cap (${MIN_MAX_LENGTH}-${MAX_MAX_LENGTH}). Only supported on text, textarea, email, phone, url and hidden fields.`,
    },
    className: {
      type: "string",
      maxLength: MAX_CLASS_NAME_LENGTH,
      description:
        "Optional CSS class names applied verbatim to the rendered input element (e.g. Tailwind utility classes like 'md:col-span-2 w-1/2'). Any string is accepted — classes are escaped, not sanitized or restricted to a vocabulary.",
    },
    attributes: {
      type: "object",
      maxProperties: MAX_ATTRIBUTES_PER_FIELD,
      propertyNames: { pattern: ATTRIBUTE_NAME_PATTERN.source },
      additionalProperties: { type: "string", maxLength: MAX_ATTRIBUTE_VALUE_LENGTH },
      description:
        "Optional extra HTML attributes applied to the rendered input element. Attribute NAMES are strictly allowlisted — 'aria-*', 'data-*', 'placeholder', 'autocomplete', 'inputmode', 'pattern', 'title', 'min', 'max', 'step', 'minlength', 'spellcheck', 'readonly'. Anything else, including any 'on*' event handler, 'style', 'formaction', 'href', 'src', 'srcdoc', 'id', 'name', or 'type', is rejected — the call fails rather than silently dropping it. Values are plain strings.",
    },
  },
} as const;

/** The `fields` property shared by create and update. */
const FIELDS_SCHEMA = {
  type: "array",
  minItems: 1,
  maxItems: MAX_FIELDS,
  items: FIELD_DESCRIPTOR_SCHEMA,
  description: `The COMPLETE field list (1-${MAX_FIELDS} fields). Both tools that accept it replace the whole list, so it must include every field the form keeps — but note that unlike a content type, an EXISTING field id may never be dropped; omitting one is rejected rather than deleting it.`,
} as const;

/** The `notify` property shared by create and update. */
const NOTIFY_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["enabled", "recipients"],
  properties: {
    enabled: { type: "boolean", description: "Whether to email recipients on each submission." },
    recipients: {
      type: "array",
      maxItems: MAX_NOTIFY_RECIPIENTS,
      items: { type: "string", description: "A valid email address." },
      description: `Up to ${MAX_NOTIFY_RECIPIENTS} email addresses. Each must be a valid address or the whole call is rejected.`,
    },
