import type { FormAnalyticsProvenance } from "./index.js";
import type { Clock, IdGenerator } from "@jini-ai/core/primitives";
import { validateSubmissionPayload, type FieldError, type FormAnswer, type FormDefinitionRecord, type FormDefinitionRepoPort, type FormOutboxPort, type FormSubmissionRepoPort } from "@jini-ai/cms/forms";
import type { FormPullRefusal } from "@jini-ai/cms/forms";
import { htmlSubmissionDefinition } from "@jini-ai/cms/forms/html";
import { FORM_LONG_TEXT_MAX_CHARS, capSubmissionFieldLengths, fieldMaxChars } from "./field-length-caps.js";

/**
 * @file Imports submissions a form destination stored where Tovu's server does not run (a static
 * export), into the same submissions store the live endpoint writes. Generic: no host is named here.
 * Each row is validated with the live endpoint's own validator. The store has no status column, so
 * an invalid row is still imported (its declared fields only, cut to the live text caps) and listed in
 * the result with its field errors rather than dropped; it emits no `form.submission.received`, since
 * it was never an accepted submission (owner decision 2026-10-27, T9). A receipt keyed by (workspace, destination, remote id) makes the
 * import idempotent, and it outlives Trash and purge, so a retried pull never resurrects a deleted row.
 */

/** One stored remote submission, before validation. Structurally the deploy target's row shape. */
export interface RemoteSubmissionInput {
  readonly id: string;
  readonly formSlug: string;
  readonly answers: Readonly<Record<string, unknown>>;
  readonly submittedAt: string;
  readonly ip: string | null;
}

/** The dedupe receipt store. `claim` is atomic: false means this remote row was already imported. */
export interface FormSubmissionReceiptPort {
  claim(required: { workspaceId: string; destinationKey: string; remoteId: string; submissionId: string; importedAt: string }, optional?: Record<string, never>): Promise<boolean>;
}

export interface ImportRemoteSubmissionsDeps {
  readonly definitionRepo: Pick<FormDefinitionRepoPort, "findBySlug">;
  /** `transaction` must be the store's own: the receipt, the row and its event commit together. */
  readonly submissionRepo: Pick<FormSubmissionRepoPort, "create" | "transaction">;
  readonly receipts: FormSubmissionReceiptPort;
  readonly outbox: FormOutboxPort;
  readonly clock: Clock;
  readonly idGen: IdGenerator;
  /** Trusted destination adapter's consent evidence; never infer analytics consent from answers. */
  readonly readAnalyticsProvenance?: (required: { item: RemoteSubmissionInput }) => FormAnalyticsProvenance | undefined;
}

export interface RemoteImportResult {
  /** Remote ids now durably in Tovu (new or already imported): safe to acknowledge at the host. */
  readonly committedIds: string[];
  readonly imported: number;
  readonly duplicates: number;
  /** Imported, but the live validator rejected them; review these in the admin. */
  readonly invalid: { remoteId: string; formSlug: string; submissionId: string; fieldErrors: FieldError[] }[];
  /** Not imported and not acknowledged (the form no longer exists); they stay at the host. */
  readonly skipped: { remoteId: string; formSlug: string; reason: "unknown_form" }[];
  /** The same rows counted per form slug, in first-seen order. */
  readonly forms: FormImportCounts[];
}

/** One form's rows in an import: new, already imported earlier, and rows naming a form that does not exist here. */
export interface FormImportCounts {
  readonly formSlug: string;
  imported: number;
  alreadyImported: number;
  unmapped: number;
}

/**
 * Imports one page of remote rows. A failure on one row propagates: rows committed earlier in the
 * page stay committed but are not acknowledged, so the next pull fetches them again and their
 * receipts count them as duplicates.
 * @complexity O(rows * fields), with one definition read and one transaction per row.
 */
export async function importRemoteFormSubmissions(
  required: { deps: ImportRemoteSubmissionsDeps; workspaceId: string; destinationKey: string; items: readonly RemoteSubmissionInput[] },
  _optional: Record<string, never> = {},
): Promise<RemoteImportResult> {
  const { deps, workspaceId, destinationKey, items } = required;
  const result: { -readonly [K in keyof RemoteImportResult]: RemoteImportResult[K] } = { committedIds: [], imported: 0, duplicates: 0, invalid: [], skipped: [], forms: [] };
  const definitions = new Map<string, FormDefinitionRecord | null>();
  // A Map, not an object: form slugs come from the receiver and may be any string.
  const counts = new Map<string, FormImportCounts>();
  for (const item of items) {
    if (!definitions.has(item.formSlug)) definitions.set(item.formSlug, await deps.definitionRepo.findBySlug({ workspaceId, slug: item.formSlug }));
    const definition = definitions.get(item.formSlug);
    const formCounts = countsFor({ counts, formSlug: item.formSlug });
    if (!definition) { result.skipped.push({ remoteId: item.id, formSlug: item.formSlug, reason: "unknown_form" }); formCounts.unmapped += 1; continue; }
    const outcome = await importOne({ deps, workspaceId, destinationKey, item, definition });
    result.committedIds.push(item.id);
    if (outcome.kind === "duplicate") { result.duplicates += 1; formCounts.alreadyImported += 1; continue; }
    result.imported += 1;
    formCounts.imported += 1;
    if (outcome.fieldErrors) result.invalid.push({ remoteId: item.id, formSlug: item.formSlug, submissionId: outcome.submissionId, fieldErrors: outcome.fieldErrors });
  }
  result.forms = [...counts.values()];
  return result;
}

/** The slug's running counts, created at zero on first sight. @complexity O(1). */
function countsFor({ counts, formSlug }: { counts: Map<string, FormImportCounts>; formSlug: string }, _optional = {}): FormImportCounts {
  const existing = counts.get(formSlug);
  if (existing) return existing;
  const created = { formSlug, imported: 0, alreadyImported: 0, unmapped: 0 };
  counts.set(formSlug, created);
  return created;
}

/** Validate, then claim the receipt, write the row and, for a valid row, enqueue `form.submission.received`
 * in one transaction, the same event shape the live submit path emits, so notifications fire once.
 * @complexity O(fields). */
async function importOne(
  required: { deps: ImportRemoteSubmissionsDeps; workspaceId: string; destinationKey: string; item: RemoteSubmissionInput; definition: FormDefinitionRecord },
  _optional: Record<string, never> = {},
): Promise<{ kind: "duplicate" } | { kind: "imported"; submissionId: string; fieldErrors?: FieldError[] }> {
  const { deps, workspaceId, destinationKey, item } = required;
  // The live submit path's view (`forms/index.ts` definitionView): HTML-mode names plus the text caps.
  const htmlView = htmlSubmissionDefinition({ definition: required.definition, body: { ...item.answers } });
  const definition = capSubmissionFieldLengths({ definition: htmlView, body: { ...item.answers } });
  const validation = validateSubmissionPayload({ definition, body: { ...item.answers } });
  const data = validation.valid ? validation.data : declaredAnswers({ definition: htmlView, answers: item.answers });
  const analyticsProvenance = deps.readAnalyticsProvenance?.({ item });
  const now = new Date(deps.clock.nowMs()).toISOString();
  const submissionId = deps.idGen.newId();
  const write = async (): Promise<boolean> => {
    if (!await deps.receipts.claim({ workspaceId, destinationKey, remoteId: item.id, submissionId, importedAt: now })) return false;
    await deps.submissionRepo.create({ id: submissionId, workspaceId, formDefinitionId: definition.id, data, sourceIp: item.ip, submittedAt: submittedAt({ value: item.submittedAt, now }) });
    // An invalid row is kept for review only: notifications and webhooks fire for accepted submissions.
    if (validation.valid) await deps.outbox.enqueue({ id: deps.idGen.newId(), name: "form.submission.received", occurredAt: now, workspaceId, aggregateId: submissionId,
      payload: { workspaceId, formDefinitionId: definition.id, submissionId, deliveryMode: "remote_import", ...(analyticsProvenance ? { analyticsProvenance } : {}) } });
    return true;
  };
  // Called as a method, never detached: the SQL store's `transaction` reads `this.kernel`.
  const claimed = deps.submissionRepo.transaction ? await deps.submissionRepo.transaction(write) : await write();
  if (!claimed) return { kind: "duplicate" };
  return { kind: "imported", submissionId, ...(validation.valid ? {} : { fieldErrors: validation.fieldErrors }) };
}

/** An invalid row keeps only declared fields with text values, so stored answers never gain keys
 * the form does not define, and each value is cut to the field's live text cap (a choice field, which
 * live submits hold to its options, to the long-text cap) so an invalid row is never stored uncapped.
 * @complexity O(total answer length). */
function declaredAnswers({ definition, answers }: { definition: FormDefinitionRecord; answers: Readonly<Record<string, unknown>> }, _optional = {}): Record<string, FormAnswer> {
  const data: Record<string, FormAnswer> = {};
  for (const field of definition.fields) {
    const value = answers[field.id];
    const kept = cappedTextAnswer(value, fieldMaxChars({ field }) ?? FORM_LONG_TEXT_MAX_CHARS);
    if (kept !== undefined) data[field.id] = kept;
  }
  return data;
}

/** A text or text-list answer cut to `max`; undefined for any other value. @complexity O(answer length). */
function cappedTextAnswer(value: unknown, max: number): FormAnswer | undefined {
  if (typeof value === "string") return capped(value, max);
  if (Array.isArray(value) && value.every((entry) => typeof entry === "string")) return value.map((entry: string) => capped(entry, max));
  return undefined;
}

/** The first `max` code points, the unit the live caps count (an emoji counts once). @complexity O(n). */
function capped(value: string, max: number): string {
  // UTF-16 units never undercount code points, so a short value is already within the cap.
  return value.length <= max ? value : [...value].slice(0, max).join("");
}

/** The host's receive time when it is a real timestamp; otherwise the import time. @complexity O(1). */
function submittedAt({ value, now }: { value: string; now: string }, _optional = {}): string {
  const parsed = Date.parse(value);
  return Number.isFinite(parsed) ? new Date(parsed).toISOString() : now;
}

/** One destination's outcome in a pull. `error` is a person-facing reason without any key. */
export interface FormDestinationPullReport {
  readonly targetId: string;
  readonly url: string;
  readonly pulled: number;
  readonly imported: number;
  readonly duplicates: number;
  readonly acknowledged: number;
  /** More rows are waiting at the host than one pull reads. */
  readonly hasMore: boolean;
  readonly invalid: RemoteImportResult["invalid"];
  readonly skipped: RemoteImportResult["skipped"];
  readonly error?: string;
  /** Set when this receiver's pull lease refused the pull; nothing was read from it. */
  readonly refused?: FormPullRefusal;
}

/** One form's rows across a whole pull. `failed` rows were read in a page whose import stopped with
 * an error: none of that page is acknowledged, so they stay at the host and the next pull retries
 * them (rows that page committed before the error then count as already imported).
 * `formId` is null when no form with that slug exists here (its rows are `unmapped`). */
export interface FormPullCounts extends FormImportCounts {
  readonly formId: string | null;
  failed: number;
}

/** What one pull reports. `ran: false` only when every receiver's lease refused it. */
export type FormSubmissionsPullResult = {
  readonly message: string;
  readonly destinations: readonly FormDestinationPullReport[];
  readonly forms: readonly FormPullCounts[];
  readonly totals: { readonly imported: number; readonly alreadyImported: number; readonly unmapped: number; readonly failed: number };
} & ({ readonly ran: true } | { readonly ran: false; readonly reason: FormPullRefusal });

/** Pulls every published destination's pending submissions (or one target's) into this site. The
 * agent tool and the admin route both call this one composed port. */
export interface FormSubmissionsPullPort {
  pull(required: { workspaceId: string }, optional?: { targetId?: string }): Promise<FormSubmissionsPullResult>;
}

/** The automatic pull the serving app's startup and sign-in triggers run (`composeFormSubmissions`).
 * `run` resolves when the pull is done or skipped; it reports nothing. `drained` resolves once every
 * notification drain a pull (manual or automatic) started has settled, so shutdown can wait for it. */
export interface FormsAutoPullPort {
  run(required: { workspaceId: string }, optional?: Record<string, never>): Promise<void>;
  drained(required?: Record<string, never>, optional?: Record<string, never>): Promise<void>;
}

/** Tovu asset-tool destination adapter. Both copy and transform call the existing guarded batch,
 * theme writer/reloader or media importer; no parallel persistence or approval lifecycle.
 * Site paths share fs_write_files' exact-batch approval because they lack theme/media validators.
 */
import { basename } from "node:path";
import { ToolInputError, requireInputRecord, requireString, type ToolExecutionContext } from "@jini-ai/core";
import { adaptLegacyAuthorize, requireToolPermission } from "@jini-ai/cms/core";
import { refuseUnexpectedKeys } from "#src/contracts/core/human-confirm";
import { persistImportedMedia, type MediaImportToolDeps } from "../media-import/tool-registrations.js";
import { validateImageBytes } from "../media-import/fetch-image.js";
import { THEME_WRITE_PERMISSION } from "../theme/agent-tools.js";
import { resolveThemeFilePath, writeThemeBinaryFile, nextAvailableFileName } from "../theme/theme-files.js";
import { assertThemeFileWritable, findThemeOrThrow, reloadThemeInPlace, type ThemeToolDeps } from "../theme/tool-registrations.js";
import { FS_FILES_CUSTOM_ROOT_MANAGE_PERMISSION } from "./custom-root-permission.js";
import { inspectWriteTarget, prepareFileWrites, writePreparedFiles } from "./write-files.js";
import { preparePickedFolderBatch, type FsFilesToolDeps, type PreparedWriteBatch } from "./tool-registrations.js";

export type AssetToolDeps = FsFilesToolDeps & ThemeToolDeps & MediaImportToolDeps;
export interface AssetFile { path: string; bytes: Buffer; sourceUrl?: string }
export interface AssetDestination { kind: "site" | "theme" | "media" | "picked"; themeId?: string }
export interface PreparedAssets { destination: AssetDestination; files: AssetFile[]; skipped: string[]; batch?: PreparedWriteBatch }
export type OverwritePolicy = "skip" | "overwrite" | "rename";
const PERMISSION = { site: FS_FILES_CUSTOM_ROOT_MANAGE_PERMISSION, picked: FS_FILES_CUSTOM_ROOT_MANAGE_PERMISSION, theme: THEME_WRITE_PERMISSION, media: "media.upload" };

/** Authorize the destination before reading sources. @throws ToolInputError or permission refusal.
 * @complexity O(1). @example await requireAssetDestination({ deps, ctx, input: { kind: 'theme', themeId: 'basic' } }); */
export async function requireAssetDestination({ deps, ctx, input }: { deps: AssetToolDeps; ctx: ToolExecutionContext; input: unknown }, _options = {}): Promise<AssetDestination> {
  if (input === undefined) throw new ToolInputError({ message: "A write needs destination.kind: site, theme, media or picked" });
  const value = requireInputRecord({ input });
  refuseUnexpectedKeys(value, ["kind", "themeId", "path"]);
  const kind = requireString({ input: value, key: "kind" }) as AssetDestination["kind"];
  if (!Object.hasOwn(PERMISSION, kind)) throw new ToolInputError({ message: "destination.kind must be site, theme, media or picked" });
  const themeId = kind === "theme" ? requireString({ input: value, key: "themeId" }) : undefined;
  await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: PERMISSION[kind] }, { entityType: kind === "picked" ? "fs-root" : kind, entityId: themeId ?? kind });
  return { kind, themeId };
}

/** Decide collisions against disk AND earlier entries; rename uses the existing file-name owner.
 * No writes occur. Bounded to 1000 suffix probes rather than an unbounded directory scan. */
function choosePath({ folder, path, policy, reserved }: { folder: string; path: string; policy: OverwritePolicy; reserved: Set<string> }): string | undefined {
  let candidate = path;
  const occupiedPaths = new Set<string>();
  for (let attempt = 0; attempt < 1000; attempt++) {
    const alreadyInBatch = reserved.has(candidate.toLowerCase());
    if (alreadyInBatch && policy === "overwrite") throw new ToolInputError({ message: `${candidate}: duplicate destination in this batch` });
    const occupied = inspectWriteTarget({ folder, path: candidate }).overwrite || alreadyInBatch;
    if (!occupied || policy === "overwrite") { reserved.add(candidate.toLowerCase()); return candidate; }
    if (policy === "skip") return undefined;
    occupiedPaths.add(candidate);
    candidate = nextAvailableFileName({ desiredPath: path, existingPaths: occupiedPaths });
  }
  throw new ToolInputError({ message: `${path}: too many filename collisions` });
}

/** Per-destination checks that need no write: theme scope/containment, media file name and type. */
function checkFile({ deps, destination, path, bytes }: { deps: AssetToolDeps; destination: AssetDestination; path: string; bytes: Buffer }): void {
  if (destination.kind === "theme") {
    const theme = findThemeOrThrow(deps, destination.themeId!);
    assertThemeFileWritable(theme, path);
    resolveThemeFilePath({ themeDir: theme.dir, themesRoot: deps.themesDir, relativePath: path });
  }
  if (destination.kind !== "media") return;
  if (path !== basename(path)) throw new ToolInputError({ message: "Media destinations use a filename, not a folder path" });
  validateImageBytes({ source: path, bytes, bytesTruncated: false });
}

/** Validate the whole batch before persistence. Media are always new imports (the importer names
 * and dedups them), so `policy` applies to site and theme paths; picked writes show overwrites on
 * the card. @returns Frozen bytes/paths and the approval batch for site/picked writes; no writes.
 * @throws Existing writer/input errors. @complexity O(files × path depth), bounded collision probes. */
export function prepareAssetWrites({ deps, destination, files, policy = "overwrite" }: { deps: AssetToolDeps; destination: AssetDestination; files: AssetFile[]; policy?: OverwritePolicy }, _options = {}): PreparedAssets {
  const prepared: PreparedAssets = { destination, files: [], skipped: [] };
  const folder = destination.kind === "site" ? deps.siteBinding.dir : destination.kind === "theme" ? findThemeOrThrow(deps, destination.themeId!).dir : undefined;
  const reserved = new Set<string>();
  for (const file of files) {
    const path = folder ? choosePath({ folder, path: file.path, policy, reserved }) : file.path;
    if (path === undefined) { prepared.skipped.push(file.path); continue; }
    checkFile({ deps, destination, path, bytes: file.bytes });
    prepared.files.push({ ...file, path });
  }
  prepared.batch = approvalBatch({ deps, destination, files: prepared.files });
  return prepared;
}

/** Site and picked-folder writes become one fs_write_files batch (and its card); others need none. */
function approvalBatch({ deps, destination, files }: { deps: AssetToolDeps; destination: AssetDestination; files: AssetFile[] }): PreparedWriteBatch | undefined {
  const encoded = files.map(({ path, bytes }) => ({ path, content: bytes.toString("base64"), encoding: "base64" }));
  if (!encoded.length) return undefined;
  if (destination.kind === "picked") return preparePickedFolderBatch({ routeDeps: deps, files: encoded });
  const folder = deps.siteBinding.dir;
  return destination.kind === "site" ? { folder, writes: prepareFileWrites({ folder, files: encoded }) } : undefined;
}

/** Execute prepared writes via the owning writers. Partial failures remain visible to callers.
 * @returns Written/skipped paths and media or theme status. @throws Storage failures.
 * @complexity O(total bytes), sequential output I/O.
 * @example await writeAssetFiles({ deps, ctx, prepared }); */
export async function writeAssetFiles({ deps, ctx, prepared }: { deps: AssetToolDeps; ctx: ToolExecutionContext; prepared: PreparedAssets }, _options = {}) {
  const { destination, files, skipped, batch } = prepared;
  if (batch) return { ...writePreparedFiles(batch), skipped };
  if (destination.kind === "media") {
    const media = [];
    for (const file of files) {
      const contentType = validateImageBytes({ source: file.path, bytes: file.bytes, bytesTruncated: false });
      media.push((await persistImportedMedia({ routeDeps: deps, actorId: ctx.principal.id, sourceUrl: file.sourceUrl ?? "", input: { workspaceId: deps.workspaceId, bytes: file.bytes, filename: file.path, contentType, createdByPrincipal: ctx.principal.id } })).media);
    }
    return { written: files.map(({ path }) => path), skipped, media };
  }
  const theme = findThemeOrThrow(deps, destination.themeId!);
  for (const file of files) writeThemeBinaryFile({ themeDir: theme.dir, themesRoot: deps.themesDir, relativePath: file.path, bytes: file.bytes });
  const reloaded = files.length ? reloadThemeInPlace(deps, theme, destination.themeId!) : theme;
  return { written: files.map(({ path }) => path), skipped, status: reloaded.status, errors: reloaded.errors };
}

/** One bounded asset copy/import tool, parameterized across Tovu source and destination owners.
 * Native path.matchesGlob filters the existing bounded fs listing; all bytes are staged before writes.
 */
import { basename, matchesGlob } from "node:path";
import { ToolInputError, buildDomainRegistrations, indexCatalogById, requireInputRecord, requireString, withSchemaOnRejection, type AgentToolDefinition, type DerivedRiskByToolId, type ToolExecutionContext, type ToolRegistration } from "@jini-ai/core";
import type { AssistantSurfaceDeps } from "@jini-ai/daemon/surface-exchanges";
import type { ToolContributor } from "#src/assistant/index";
import { approvalToolHandler, refuseUnexpectedKeys } from "#src/contracts/core/human-confirm";
import { toolMetadata } from "#src/contracts/core/tool-metadata/files-copy";
import { isShapeRejection as isThemeShapeRejection } from "../theme/tool-registrations.js";
import { fetchImage, MEDIA_IMPORT_POLICY } from "../media-import/fetch-image.js";
import { isImportShapeRejection, withCallerSafeEgressRefusal } from "../media-import/tool-registrations.js";
import { THEME_IMPORT_MAX_BYTES, THEME_IMPORT_POLICY, THEME_IMPORT_ACCEPT } from "../theme/theme-file-import.js";
import { ASSET_SOURCE_SCHEMA, readAssetSource, readLocalFile, resolveAssetSource } from "./asset-sources.js";
import { prepareAssetWrites, requireAssetDestination, writeAssetFiles, type AssetFile, type AssetToolDeps, type OverwritePolicy, type PreparedAssets } from "./asset-destinations.js";
import { FS_FILES_READ_PERMISSION } from "./agent-tools.js";
import { FsFilePathError, listFsFiles } from "./fs-files.js";
import { FsWriteInputError } from "./write-files.js";
import { describeWriteBatch } from "./tool-registrations.js";

export const FILES_COPY_LIMITS = { maxFiles: 50, maxFileBytes: THEME_IMPORT_MAX_BYTES, maxTotalBytes: 25 * 1024 * 1024 } as const;
const catalog: AgentToolDefinition = {
  name: "files_copy",
  description: "Copy/import assets without Bash cp or Python. sources:[{root:'picked'|'site'|'theme'|'media',path,themeId?,glob?}|{root:'url',url,path?}]. " +
    "For a folder, glob filters paths relative to that folder (e.g. '**/*.{png,woff2}'); directory structure is preserved. No glob means one file. " +
    "destination:{kind:'theme',themeId,path:'assets'} | {kind:'site',path:'public/images'} | {kind:'media'}. path is a destination folder. " +
    "overwrite:'skip' (default), 'overwrite' or 'rename' for site/theme paths; media are always added as new items. " +
    "Returns written/skipped paths, media URLs or theme status. Theme/media edits use their existing permissions; site files use fs_write_files batch approval. Never writes to picked folders: use fs_write_files. " +
    "All sources are checked before writing; secrets, symlinks, escapes and truncated folder listings are refused. URLs use the existing SSRF-guarded image/font fetch. " +
    `Caps: ${FILES_COPY_LIMITS.maxFiles} files, ${FILES_COPY_LIMITS.maxFileBytes} bytes/file, ${FILES_COPY_LIMITS.maxTotalBytes} bytes total; site writer additionally caps 2 MiB/file and 10 MiB/batch.`,
  sideEffects: "mutates-durable-state", authorization: { permission: FS_FILES_READ_PERMISSION },
  inputSchema: { type: "object", additionalProperties: false, required: ["sources", "destination"], properties: {
    sources: { type: "array", minItems: 1, maxItems: FILES_COPY_LIMITS.maxFiles, items: { type: "object", additionalProperties: false, required: ["root"], properties: {
      ...ASSET_SOURCE_SCHEMA.properties, root: { type: "string", enum: [...ASSET_SOURCE_SCHEMA.properties.root.enum, "url"] },
      url: { type: "string", minLength: 1 }, glob: { type: "string", minLength: 1, maxLength: 256 },
    } } },
    destination: { type: "object", additionalProperties: false, required: ["kind"], properties: { kind: { type: "string", enum: ["site", "theme", "media"] }, path: { type: "string", minLength: 1 }, themeId: { type: "string", minLength: 1 } } },
    overwrite: { type: "string", enum: ["skip", "overwrite", "rename"] },
  } },
};
export const filesCopyAgentToolCatalog: AgentToolDefinition[] = [catalog];
export const filesCopyDerivedRisk: DerivedRiskByToolId = new Map([["files_copy", "mutates-durable-state"]]);
const byId = indexCatalogById({ catalog: filesCopyAgentToolCatalog });
const callerError = (error: unknown) => error instanceof FsFilePathError || error instanceof FsWriteInputError || isThemeShapeRejection(error) || isImportShapeRejection({ error });

/** URL sources reuse fetchImage and its safe egress port, with the existing theme font sniffer. */
async function readUrl({ deps, source, media }: { deps: AssetToolDeps; source: Record<string, unknown>; media: boolean }): Promise<AssetFile> {
  if (source.glob !== undefined) throw new ToolInputError({ message: "URL sources do not accept glob" });
  const url = requireString({ input: source, key: "url" });
  const fetched = await withCallerSafeEgressRefusal(deps.mediaImportEgressRefusalLog ?? console.warn, () => fetchImage(
    { deps: { httpClient: deps.mediaImportHttpClient, plainHttpTestOrigins: deps.outboundTestOrigins }, url },
    media ? { policy: { ...MEDIA_IMPORT_POLICY, maxBytes: FILES_COPY_LIMITS.maxFileBytes } } : { policy: THEME_IMPORT_POLICY, accept: THEME_IMPORT_ACCEPT },
  ), { toolId: "files_copy" });
  return { bytes: Buffer.from(fetched.bytes), path: source.path === undefined ? basename(fetched.url.pathname) : requireString({ input: source, key: "path" }), sourceUrl: fetched.url.href };
}

/** Validate the native glob input separately from filesystem I/O. */
function requireGlob({ glob, root }: { glob: unknown; root: unknown }): string {
  if (typeof glob !== "string" || !glob || glob.length > 256 || root === "media") throw new ToolInputError({ message: "glob must be 1..256 characters and target a filesystem folder" });
  return glob;
}

/** Expand folders through the existing bounded listing. A truncated listing cannot imply completeness.
 * The listing skips symlinks; each entry is re-walked on read because it may have changed since. */
async function readLocal({ deps, ctx, source }: { deps: AssetToolDeps; ctx: ToolExecutionContext; source: Record<string, unknown> }): Promise<AssetFile[]> {
  const { glob, ...input } = source;
  if (glob === undefined) {
    const file = await readAssetSource({ deps, ctx, input, maxBytes: FILES_COPY_LIMITS.maxFileBytes });
    return [{ ...file, path: basename(file.path) }];
  }
  const pattern = requireGlob({ glob, root: source.root });
  const { rootPath, relativePath: folder } = await resolveAssetSource({ deps, ctx, source: input });
  const listing = listFsFiles({ rootPath, relativePath: folder });
  const paths = listing.files.filter((path) => matchesGlob(path, pattern));
  if (listing.truncated || paths.length > FILES_COPY_LIMITS.maxFiles) throw new ToolInputError({ message: "Folder glob exceeds the file-count/traversal cap; narrow the folder or glob" });
  const files: AssetFile[] = [];
  let total = 0;
  for (const path of paths) {
    const bytes = await readLocalFile({ rootPath, relativePath: folder === "." ? path : `${folder}/${path}`, maxBytes: FILES_COPY_LIMITS.maxFileBytes });
    total += bytes.length;
    if (total > FILES_COPY_LIMITS.maxTotalBytes) throw new ToolInputError({ message: "Folder glob exceeds the total byte cap" });
    files.push({ path, bytes });
  }
  return files;
}

/** Authorize, stage and validate the complete aggregate before any card or write.
 * @throws Input/root/permission errors. @complexity O(total bytes + bounded folder entries). */
async function prepare({ deps, ctx }: { deps: AssetToolDeps; ctx: ToolExecutionContext }): Promise<PreparedAssets> {
  const input = requireInputRecord({ input: ctx.input });
  refuseUnexpectedKeys(input, ["sources", "destination", "overwrite"]);
  if (!Array.isArray(input.sources) || !input.sources.length || input.sources.length > FILES_COPY_LIMITS.maxFiles) throw new ToolInputError({ message: "sources must list 1..50 entries" });
  const { destination, prefix } = await requireCopyDestination({ deps, ctx, input: input.destination });
  const policy = (input.overwrite ?? "skip") as OverwritePolicy;
  if (!["skip", "overwrite", "rename"].includes(policy)) throw new ToolInputError({ message: "overwrite must be skip, overwrite or rename" });
  const files: AssetFile[] = [];
  for (const raw of input.sources) {
    const group = await readGroup({ deps, ctx, raw, media: destination.kind === "media" });
    appendFiles({ files, group, prefix });
  }
  return prepareAssetWrites({ deps, destination, files, policy });
}

/** Authorized destination plus its folder prefix (theme default 'assets'); never the picked folder. */
async function requireCopyDestination({ deps, ctx, input }: { deps: AssetToolDeps; ctx: ToolExecutionContext; input: unknown }) {
  const raw = requireInputRecord({ input });
  if (raw.kind === "picked") throw new ToolInputError({ message: "Use fs_write_files to write to the picked folder" });
  const destination = await requireAssetDestination({ deps, ctx, input: raw });
  if (destination.kind === "media" && raw.path !== undefined) throw new ToolInputError({ message: "Media destinations do not have folders; omit destination.path" });
  const prefix = raw.path === undefined ? (destination.kind === "theme" ? "assets" : "") : requireString({ input: raw, key: "path" });
  return { destination, prefix };
}

/** Select a source adapter after rejecting contradictory URL fields. */
async function readGroup({ deps, ctx, raw, media }: { deps: AssetToolDeps; ctx: ToolExecutionContext; raw: unknown; media: boolean }): Promise<AssetFile[]> {
  const source = requireInputRecord({ input: raw });
  refuseUnexpectedKeys(source, ["root", "path", "url", "themeId", "glob"]);
  if (source.root !== "url" && source.url !== undefined) throw new ToolInputError({ message: "url is only valid for root url" });
  if (source.root === "url") return [await readUrl({ deps, source, media })];
  return readLocal({ deps, ctx, source });
}

/** Aggregate caps count all sources together; failure occurs before destination persistence. */
function appendFiles({ files, group, prefix }: { files: AssetFile[]; group: AssetFile[]; prefix: string }): void {
  for (const file of group) files.push({ ...file, path: prefix ? `${prefix}/${file.path}` : file.path });
  const total = files.reduce((sum, file) => sum + file.bytes.length, 0);
  if (files.length > FILES_COPY_LIMITS.maxFiles || total > FILES_COPY_LIMITS.maxTotalBytes || group.some((file) => file.bytes.length > FILES_COPY_LIMITS.maxFileBytes)) throw new ToolInputError({ message: "Copy exceeds file-count or byte caps; split the selection" });
}

/** Register one generic copy tool; site writes reuse the existing approval exchange.
 * @returns One registration. @complexity O(1). @example buildFilesCopyRegistrations(deps, surfaces); */
export function buildFilesCopyRegistrations(deps: AssetToolDeps, surfaces: AssistantSurfaceDeps): ToolRegistration[] {
  const handler = approvalToolHandler<PreparedAssets>({ surfaces,
    prepare: ({ ctx }) => withSchemaOnRejection({ toolId: "files_copy", catalog: byId, isShapeRejection: ({ error }) => callerError(error), fn: () => prepare({ deps, ctx }) }),
    describe: ({ prepared }) => describeWriteBatch(prepared.batch ?? { folder: "", writes: [] }, { toolId: "files_copy" }),
    run: async ({ ctx, prepared }) => {
      if (!prepared.files.length) return { applied: false, written: [], skipped: prepared.skipped };
      const result = await writeAssetFiles({ deps, ctx, prepared });
      return { applied: !("failed" in result), ...result };
    },
  }, { flag: "applied", ask: ({ prepared }) => prepared.batch !== undefined });
  return buildDomainRegistrations({ metadata: toolMetadata, domain: "files-copy", catalogModule: "features/fs-files/copy-tool.ts", catalog: byId, handlers: { files_copy: handler }, derivedRisk: filesCopyDerivedRisk });
}

/** Composition contribution; its own key preserves the existing fs-files catalog. */
export function contributeFilesCopyTools(): ToolContributor {
  return { domain: "files-copy", build: buildFilesCopyRegistrations, risk: filesCopyDerivedRisk };
}

import { execFile as execFileCallback } from "node:child_process";
import { existsSync } from "node:fs";
import path from "node:path";
import { promisify } from "node:util";

/**
 * @file Opens the OS-native "choose folder" dialog on the machine running this server and returns the
 * chosen absolute path. Backs the admin chat composer's folder button (`routes/fs-files/folder-picker.ts`):
 * a plain browser tab can never read a folder's OS path, but when the server IS the owner's own
 * machine it can ask the OS directly. That route owns the "own machine only" admission; this module
 * only knows how to show the dialog.
 *
 * Every chooser runs through `execFile` with a fixed absolute binary and a fixed argv — no shell, and
 * nothing request-supplied ever reaches the command line.
 */

const PROMPT = "Choose a folder to insert its path";
/** A dialog left open this long is closed (the child is killed) and read as a cancel. */
const PICK_TIMEOUT_MS = 10 * 60_000;

/** The parts of a rejected `execFile` this module reads. `code` is the exit code, or a spawn error
 *  code such as `ENOENT`; `killed` is set when the timeout ended the child. */
export interface ChooserFailure {
  readonly code?: number | string;
  readonly killed?: boolean;
  readonly stderr?: string;
}

export interface FolderChooserCommand {
  readonly file: string;
  readonly args: readonly string[];
  /** Whether a failed run was the user pressing Cancel rather than a real error. */
  readonly cancelled: (failure: ChooserFailure) => boolean;
}

// `activate` (no target) brings osascript itself to the front, so the dialog does not open behind
// the browser. A tell to "System Events" would do the same but costs an Automation permission prompt.
// AppleScript reports Cancel as error -128 (exit 1); every other osascript error also exits 1.
const MAC_COMMAND: FolderChooserCommand = {
  file: "/usr/bin/osascript",
  args: ["-e", "activate", "-e", `POSIX path of (choose folder with prompt "${PROMPT}")`],
  cancelled: (failure) => failure.code === 1 && /\(-128\)/.test(failure.stderr ?? ""),
};

// zenity and kdialog both exit 1 on Cancel with nothing on stdout.
const LINUX_COMMANDS: readonly FolderChooserCommand[] = [
  { file: "/usr/bin/zenity", args: ["--file-selection", "--directory", `--title=${PROMPT}`], cancelled: (failure) => failure.code === 1 },
  { file: "/usr/bin/kdialog", args: ["--title", PROMPT, "--getexistingdirectory"], cancelled: (failure) => failure.code === 1 },
];

// A hidden TopMost owner form keeps the dialog above the browser. Cancel exits 0 with no output.
// UTF-8 output so a non-ASCII folder name survives the trip back to Node.
const WINDOWS_SCRIPT = [
  "Add-Type -AssemblyName System.Windows.Forms",
  "[Console]::OutputEncoding = [System.Text.Encoding]::UTF8",
  "$owner = New-Object System.Windows.Forms.Form -Property @{ TopMost = $true; ShowInTaskbar = $false }",
  "$dialog = New-Object System.Windows.Forms.FolderBrowserDialog",
  `$dialog.Description = '${PROMPT}'`,
  "if ($dialog.ShowDialog($owner) -eq [System.Windows.Forms.DialogResult]::OK) { [Console]::Out.Write($dialog.SelectedPath) }",
].join("; ");

function windowsCommand({ env }: { env: Readonly<Record<string, string | undefined>> }): FolderChooserCommand {
  return {
    file: path.win32.join(env.SystemRoot ?? "C:\\Windows", "System32", "WindowsPowerShell", "v1.0", "powershell.exe"),
    args: ["-NoProfile", "-NonInteractive", "-STA", "-WindowStyle", "Hidden", "-ExecutionPolicy", "Bypass", "-Command", WINDOWS_SCRIPT],
    cancelled: () => false,
  };
}

function candidateCommands({ platform, env }: { platform: string; env: Readonly<Record<string, string | undefined>> }): readonly FolderChooserCommand[] {
  if (platform === "darwin") return [MAC_COMMAND];
  if (platform === "win32") return [windowsCommand({ env })];
  // A Linux server with no display (a container, an SSH session) has nowhere to show a dialog.
  if (platform === "linux" && (env.DISPLAY || env.WAYLAND_DISPLAY)) return LINUX_COMMANDS;
  return [];
}

/**
 * The chooser this machine can run, or `null` when it has none.
 *
 * @param required.platform `process.platform`.
 * @param required.env `process.env` (`SystemRoot` on Windows; `DISPLAY`/`WAYLAND_DISPLAY` on Linux).
 * @param optional.exists File-existence probe; defaults to `fs.existsSync`.
 * @complexity O(1): at most two fixed candidates.
 */
export function folderChooserCommand(
  required: { platform: string; env: Readonly<Record<string, string | undefined>> },
  optional: { exists?: (file: string) => boolean } = {},
): FolderChooserCommand | null {
  const exists = optional.exists ?? existsSync;
  return candidateCommands(required).find((command) => exists(command.file)) ?? null;
}

/**
 * The path a chooser printed, or `null` when it printed nothing (a cancel). Drops the trailing
 * newline, and the trailing `/` macOS adds to a folder, except on the root itself.
 *
 * @complexity O(n) in the output length.
 */
export function chosenFolderPath({ stdout }: { stdout: string }): string | null {
  const printed = stdout.replace(/[\r\n]+$/, "");
  if (printed === "") return null;
  return printed.length > 1 && printed.endsWith("/") ? printed.slice(0, -1) : printed;
}

type ExecFilePort = (file: string, args: readonly string[], options: { timeout: number; maxBuffer: number; encoding: "utf8" }) =>
  Promise<{ stdout: string; stderr: string }>;

export interface NativeFolderPicker {
  /** Whether this machine has a chooser at all. Fixed for the process's life. */
  readonly available: boolean;
  /** Shows the dialog and resolves with the chosen absolute path, or `null` on cancel/timeout.
   *  Rejects when the chooser itself fails. */
  pick(): Promise<string | null>;
}

async function runChooser({ command, execFile }: { command: FolderChooserCommand; execFile: ExecFilePort }): Promise<string | null> {
  try {
    const { stdout } = await execFile(command.file, command.args, { timeout: PICK_TIMEOUT_MS, maxBuffer: 64 * 1024, encoding: "utf8" });
    return chosenFolderPath({ stdout });
  } catch (error) {
    const failure = error as ChooserFailure;
    if (failure.killed === true || command.cancelled(failure)) return null;
    throw error;
  }
}

/**
 * The real picker for this process. The chooser is resolved once, at creation.
 *
 * @param optional Test seams; every real caller passes none. `execFile` is the only thing that
 *   ever spawns, so tests inject a fake and never show a dialog.
 * @complexity O(1) to create; `pick` waits on the user.
 */
export function createNativeFolderPicker(
  _required: Record<string, never> = {},
  optional: {
    platform?: string;
    env?: Readonly<Record<string, string | undefined>>;
    exists?: (file: string) => boolean;
    execFile?: ExecFilePort;
  } = {},
): NativeFolderPicker {
  const command = folderChooserCommand(
    { platform: optional.platform ?? process.platform, env: optional.env ?? process.env },
    optional.exists ? { exists: optional.exists } : {},
  );
  const execFile = optional.execFile ?? (promisify(execFileCallback) as unknown as ExecFilePort);
  return {
    available: command !== null,
    pick: () => command
      ? runChooser({ command, execFile })
      : Promise.reject(new Error("no native folder chooser on this machine")),
  };
}

import type { ISODateTime, UUID } from "@jini-ai/core/primitives";

/**
 * @file The `api_keys` record shape and its two ports (ADR-021 / SPEC-006 REQ-08, state.spec §2).
 *
 * Purpose:
 * `@jini-ai/cms/identity` ships nine repo ports and deliberately stops there — its `INFO.md` names
 * API keys as the one identity table left out of that pass. This file is the tenth port, declared
 * HERE rather than in the library because api-key issuance/verification is implemented in this
 * host (`api-key-service.ts`), and a port belongs with the code that consumes it.
 *
 * Architectural role:
 * Interfaces and types only — no logic, mirroring `@jini-ai/cms/identity`'s own `ports.ts`. The
 * two adapters are `repo.memory.ts` (`InMemoryApiKeyRepo`) and `repo.sqlite.ts`
 * (`SqliteApiKeyRepo`) — a real ADR-006 rule-of-two, not a single-adapter port.
 */

/**
 * One issued key. `keyHash` is a digest of the key's SECRET half only; the raw key exists exactly
 * once, in `APIKEY_ISSUE`'s response, and is never stored or logged (INV-05).
 *
 * `prefix` is the key's non-secret half, stored in the clear on purpose: it is the lookup handle
 * that turns verification into one indexed row read plus one hash comparison. Without it, a salted
 * KDF digest (which is not a deterministic function of the key alone) would force a full-table
 * scan hashing every row on every request.
 */
export interface ApiKeyRecord {
  id: UUID;
  workspaceId: UUID;
  /** The bound `kind='api_key'` principal this key authenticates as (REQ-08). */
  principalId: UUID;
  label: string;
  /** Digest of the secret half — see `api-key-secret.ts` for the format and its cost parameters. */
  keyHash: string;
  /** Non-secret lookup handle, e.g. `tovu_ak_9f2c1b04d7e5`. Unique per workspace. */
  prefix: string;
  /**
   * The `is_frozen` permission-snapshot policy minted for this key at issuance (F-054-01).
   * `revokeApiKey` retires it with the key so no orphan grant rows survive revocation.
   */
  issuedPolicyId?: UUID | undefined;
  createdAt: ISODateTime;
  lastUsedAt?: ISODateTime | undefined;
  expiresAt?: ISODateTime | undefined;
  revokedAt?: ISODateTime | undefined;
}

export interface ApiKeyRepoPort {
  findById(required: { workspaceId: UUID; id: UUID }): Promise<ApiKeyRecord | null>;
  /** The verification path's single row read — see `ApiKeyRecord.prefix` for why this is the seam. */
  findByPrefix(required: { workspaceId: UUID; prefix: string }): Promise<ApiKeyRecord | null>;
  listByPrincipalId(required: { workspaceId: UUID; principalId: UUID }): Promise<ApiKeyRecord[]>;
  save(record: ApiKeyRecord): Promise<void>;
}

/**
 * The hashing seam for api-key secrets, separate from `PasswordHasherPort` because the two hash
 * fundamentally different inputs and are therefore tuned differently — see `api-key-secret.ts`'s
 * header for the entropy argument behind that split.
 *
 * `verify` must be constant-time in the digest comparison and must never throw: a malformed or
 * foreign stored hash resolves `false` (rejected credential), never a 500 and never a bypass.
 */
export interface ApiKeySecretHasherPort {
  hash(secret: string): Promise<string>;
  verify(storedHash: string, secret: string): Promise<boolean>;
}

import type { IdGenerator as IdGeneratorPort, UUID } from "@jini-ai/core/primitives";
import type { PolicyPermissionRepoPort, PolicyRepoPort, RolePolicyRepoPort, RoleRepoPort } from "@jini-ai/user-management";

/**
 * @file Boot-time backfill of a permission onto a BUILT-IN role's policy, for workspaces that were
 * already seeded before that permission existed.
 *
 * ## The gap this closes
 *
 * There are two ways a permission reaches a policy in this system, and between them they miss a
 * case that every deployed install is in:
 *
 * - `seedIdentity`'s built-in grant lists (`@jini-ai/cms`) reach a workspace exactly once, on first
 *   boot. It early-returns the moment an owner user exists, so a string added to those lists later
 *   provably never reaches an already-seeded workspace.
 * - `migrateDeprecatedPermissionGrants` (`permission-migrations.ts`) fans a new string out to every
 *   policy that already holds some OTHER string. That works only when such an anchor exists in the
 *   target workspace — it is a rename/split mechanism, and a `from` row that is absent matches
 *   nothing and grants nothing, silently.
 *
 * A permission introduced after a workspace was seeded, whose intended holder happens not to hold a
 * suitable anchor string in THAT workspace, therefore reaches nobody. It is not a fail-open — the
 * gate still evaluates and still refuses — but it is a silent capability REMOVAL: the feature stops
 * working for its intended role, and the only principal left is `owner`, on its `*` wildcard.
 *
 * This module is the third path: state the grant against the built-in ROLE it belongs to, and let
 * boot reconcile it. That is the same thing the seed list says, expressed so it also applies to a
 * workspace the seed will never visit again.
 *
 * ## Why by role, and why that is safe
 *
 * A registration names a built-in role (`"admin"`), not a policy id and not a policy name. The
 * fan-out resolves that to the role's OWN built-in policy — `seedIdentity` creates each built-in
 * role 1:1 with a `${name}-builtin-policy` marked `isBuiltin` — and writes one row there.
 *
 * The safety property is structural rather than incidental: the write targets one specific policy
 * row, so a policy belonging to a DIFFERENT role cannot be reached. Granting to `admin` cannot
 * touch `editor-builtin-policy` for the same reason it cannot touch an unrelated workspace's rows —
 * not because of an ordering, a guard, or a filter that a later edit could weaken.
 *
 * Non-built-in policies bound to the role are skipped. Those are operator-created attachments whose
 * contents are an operator's decision, not the library's; the built-in seed lists are the only
 * thing this mechanism is reconciling.
 *
 * ## Additive-only, like its neighbour
 *
 * Same invariant as `migrateDeprecatedPermissionGrants` and for the same reason: there is no
 * delete, no update, and no rewrite of any existing row anywhere in this file. A partial or failed
 * run leaves the previous, still-functioning state. Re-running is a no-op once the row exists, so
 * it is safe on every boot. Reverting a grant means deleting its registration — after which this
 * module stops ADDING the row, and removing the already-granted row is a deliberate, separate
 * operator action rather than something a code revert performs silently.
 */

/** One registered "this built-in role should hold this permission" statement. */
export interface BuiltinRoleGrant {
  /** Built-in role name as `seedIdentity` creates it — `"owner"`, `"admin"`, `"editor"`, `"viewer"`. */
  readonly role: string;
  /** The permission string that role's built-in policy should hold. */
  readonly permission: string;
  /** Human-readable rationale, surfaced in docs/reviews — not interpreted by this module. */
  readonly reason: string;
}

/** A host-owned set of built-in-role grants; see {@link createBuiltinRoleGrantRegistry}. */
export interface BuiltinRoleGrantRegistry {
  /**
   * Register a built-in-role grant for later fan-out. Idempotent per `{role, permission}` pair:
   * re-registration overwrites rather than duplicating — matches `PermissionMigrationRegistry.register`'s
   * and `PermissionCatalog.register`'s established overwrite semantics.
   *
   * Called at composition by the feature that owns the permission (see
   * `features/pages/permissions.ts`'s `registerPagesPermissionGrants`), so the feature keeps its own
   * policy statement rather than identity holding a list of other features' strings.
   *
   * @complexity O(1).
   */
  register(grant: BuiltinRoleGrant): void;
  /** Enumerate every registered built-in-role grant, in first-registration order. */
  list(_required: Record<string, never>): BuiltinRoleGrant[];
}

/**
 * Create an empty built-in-role grant registry. One is created per composition root (inside
 * `createPermissionGrantRegistry`, `permission-grants.ts`) and passed to identity wiring as a port.
 * There is deliberately no module-scope registry: one filled by import side effects made which
 * grants existed depend on which modules a process happened to import, and a standalone script that
 * never imported the registering module reconciled against an empty registry (`11aa47080`).
 *
 * @complexity O(g) where g = `optional.grants`.
 */
export function createBuiltinRoleGrantRegistry(
  _required: Record<string, never> = {},
  optional: { grants?: readonly BuiltinRoleGrant[] } = {}
): BuiltinRoleGrantRegistry {
  const byKey = new Map<string, BuiltinRoleGrant>();
  const register = (grant: BuiltinRoleGrant): void => {
    // `\u0000` is the ESCAPED form of the NUL separator this key has always used — same code unit,
    // same comparisons, written so tooling can read this file. A raw NUL byte here made git classify
    // the whole file as binary: `git log --numstat` reported `-\t-` for it, so `ab051e61`'s refactor
    // of this module showed as "Bin 7359 -> 8043 bytes" with no reviewable diff, in a permissions
    // file. Text tools that stop at a NUL byte skipped it for the same reason. Do not paste a literal
    // NUL back in; changing the separator to any other character would change how existing keys
    // compare, which is a different change entirely.
    byKey.set(`${grant.role}\u0000${grant.permission}`, grant);
  };
  for (const grant of optional.grants ?? []) register(grant);
  return { register, list: () => [...byKey.values()] };
}

export interface ApplyBuiltinRoleGrantsDeps {
  /** Every grant to reconcile — normally the composition root's `roleGrants.list({})`. */
  grants: readonly BuiltinRoleGrant[];
  roles: RoleRepoPort;
  rolePolicies: RolePolicyRepoPort;
  policies: PolicyRepoPort;
  policyPermissions: PolicyPermissionRepoPort;
  idGen: IdGeneratorPort;
  workspaceId: UUID;
}

export interface ApplyBuiltinRoleGrantsResult {
  /** New `policy_permissions` rows written across every passed grant. `0` once reconciled. */
  grantedCount: number;
}

/**
 * Reconcile one grant against one already-resolved built-in role: walk that role's policy
 * bindings, skip anything that is not a built-in policy or that already holds the permission, and
 * add the row where it is missing. Split out of `applyBuiltinRoleGrants` so the grant loop and the
 * binding loop are not both inline in one function.
 *
 * @complexity O(p) where p = policies bound to the role; small and bounded (built-in roles are 1:1
 * with their policy).
 */
async function grantToRoleBindings(
  deps: ApplyBuiltinRoleGrantsDeps,
  grant: BuiltinRoleGrant,
  roleId: UUID
): Promise<number> {
  const { workspaceId } = deps;
  let granted = 0;

  const bindings = await deps.rolePolicies.listByRoleId({ workspaceId, roleId });
  for (const binding of bindings) {
    const policy = await deps.policies.findById({ workspaceId, id: binding.policyId });
    if (!policy?.isBuiltin) continue;

    const held = await deps.policyPermissions.listByPolicyId({ workspaceId, policyId: policy.id });
    if (held.some((row) => row.permission === grant.permission)) continue;

    await deps.policyPermissions.save({
      id: deps.idGen.newId(),
      workspaceId,
      policyId: policy.id,
      permission: grant.permission,
      // Unscoped, exactly as every seeded built-in grant is — a `resourceType` here would make
      // the row match only one `entityType` and turn a missing grant into a subtler one.
      resourceType: null,
      constraintJson: null,
    });
    granted += 1;
  }

  return granted;
}

/**
 * For every `{role, permission}` in `deps.grants`, ensure that built-in role's own built-in policy holds
 * the permission — adding only the rows that are missing.
 *
 * Skips a registration whose role does not exist in this workspace, and skips a role that is not
 * `isBuiltin` (an operator-created role that happens to share a built-in's name is not what a
 * registration means). Never removes or mutates any existing row.
 *
 * Safe to call on every boot: a rerun with nothing to add returns `grantedCount: 0`, mirroring
 * `migrateDeprecatedPermissionGrants`' boot-safety contract.
 *
 * @complexity O(g * p) where g = passed grants and p = policies bound to a named role; both are
 * small, bounded collections (built-in roles are 1:1 with their policy).
 */
export async function applyBuiltinRoleGrants(
  deps: ApplyBuiltinRoleGrantsDeps
): Promise<ApplyBuiltinRoleGrantsResult> {
  const { grants } = deps;
  if (grants.length === 0) return { grantedCount: 0 };

  const { workspaceId } = deps;
  let grantedCount = 0;

  for (const grant of grants) {
    const role = await deps.roles.findByName({ workspaceId, name: grant.role });
    if (!role || !role.isBuiltin) continue;

    grantedCount += await grantToRoleBindings(deps, grant, role.id);
  }

  return { grantedCount };
}

/**
 * @file Fails when the seeded default admin credentials appear anywhere in shipped UI source.
 *
 * ---------------------------------------------------------------------------
 * Why this exists
 * ---------------------------------------------------------------------------
 * `apps/admin/src/features/auth/Login.tsx` rendered
 * `local dev default: admin / <the default password>` unconditionally, so the production sign-in
 * page on the hosted production site published a working username and password to anyone who loaded it.
 *
 * It had been fixed twice before (once by deleting the hint, once by gating it to dev builds) and
 * came back both times — most recently on 2026-09-02, when a force-push of this branch over the
 * public deploy mirror reverted the fix, because the branch predated it. A regression that
 * returns three times through three different routes is not a thing to remember; it is a thing to
 * gate.
 *
 * ---------------------------------------------------------------------------
 * What it checks, and why this shape
 * ---------------------------------------------------------------------------
 * The password's VALUE is read from {@link DEFAULT_OWNER_PASSWORD} rather than written here as a
 * literal. Two consequences, both deliberate:
 *   - changing the default in `wiring.ts` cannot silently un-protect this check;
 *   - this file never itself contains the credential, so it does not trip the sibling
 *     `secret-scan-guard.ts` (whose own test file did exactly that and turned CI red).
 *
 * Scope is `apps/admin/src` — the code that becomes the browser bundle a logged-out visitor can
 * fetch. Server source is deliberately NOT scanned: `wiring.ts` must name the default to seed the
 * owner account, and `apps/website`'s own tests legitimately authenticate with it. The invariant
 * is "the default never reaches a shipped UI string", not "the default is never written down".
 *
 * A gate-to-dev-builds fix was considered and rejected. A hint that only has to be correct about
 * its own build environment is a hint that can be wrong in production, and the failure mode there
 * is publishing credentials. There is no legitimate reason for the admin bundle to contain the
 * default password at all, so the check is absolute rather than conditional.
 */
import { readdirSync, readFileSync, statSync } from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";

import { DEFAULT_OWNER_PASSWORD } from "./wiring.js";

const REPO_ROOT = path.resolve(import.meta.dirname, "..", "..", "..", "..", "..");

/** The shipped admin UI. Its build output is served to anyone who can reach `/admin/`. */
const SCANNED_ROOTS = ["apps/admin/src"] as const;

const SCANNED_EXTENSIONS = new Set([".ts", ".tsx", ".js", ".jsx", ".css", ".html"]);

export interface DefaultCredentialHit {
  readonly file: string;
  readonly line: number;
}

/** Directory (or file) names never worth walking into or scanning: build output, dependencies,
 *  and test sources. Test sources are excluded because they are not reachable from the Vite entry
 *  point and so never enter the browser bundle a logged-out visitor can fetch. This is the one
 *  content-scope exclusion, and it is a statement about what ships, not a convenience:
 *  `api-request-unreachable.unit.test.ts` legitimately authenticates with the default to exercise
 *  an unreachable-API path. A test that renders the credential into a COMPONENT would still be
 *  caught, because the component itself is scanned. */
const SKIPPED_ENTRY_NAMES = new Set(["node_modules", "dist", ".vite", "__tests__"]);

/** True iff `entry` is a scannable source file this check must inspect. */
function isScannableFile(entry: string): boolean {
  return SCANNED_EXTENSIONS.has(path.extname(entry)) && !/\.(test|spec)\.[jt]sx?$/.test(entry);
}

/** Enumeration errors must fail the credential gate: an unreadable or missing source tree
 * cannot establish that the shipped UI is free of the default password. */
function readDirEntries(dir: string): string[] {
  return readdirSync(dir);
}

/** `true`/`false`/`null` for "is a directory" / "is a file" / "could not stat" (deleted between
 *  listing and stat, a broken symlink, or a permission error) — `null` tells the caller to skip the
 *  entry entirely rather than mis-scan it as either shape. */
function statIsDirectory(fullPath: string): boolean | null {
  try {
    return statSync(fullPath).isDirectory();
  } catch {
    return null;
  }
}

/** Recursively lists scannable files under `dir`, skipping build output and dependencies. */
function listFiles(dir: string): string[] {
  const out: string[] = [];
  for (const entry of readDirEntries(dir)) {
    if (SKIPPED_ENTRY_NAMES.has(entry)) continue;

    const full = path.join(dir, entry);
    const isDir = statIsDirectory(full);
    if (isDir === null) continue;

    if (isDir) {
      out.push(...listFiles(full));
    } else if (isScannableFile(entry)) {
      out.push(full);
    }
  }
  return out;
}

/**
 * Returns every line in `text` containing `secret`. Exported so the test can exercise the matcher
 * on synthetic input without touching the filesystem.
 *
 * @complexity O(n) in the text length.
 */
export function findSecretInText(text: string, secret: string): number[] {
  const lines: number[] = [];
  text.split("\n").forEach((line, index) => {
    if (line.includes(secret)) lines.push(index + 1);
  });
  return lines;
}

/**
 * Scans the shipped admin UI for the seeded default password.
 *
 * @returns One entry per offending line. Empty means the invariant holds.
 */
export function scanForDefaultCredentialExposure(): DefaultCredentialHit[] {
  const hits: DefaultCredentialHit[] = [];
  for (const root of SCANNED_ROOTS) {
    const abs = path.join(REPO_ROOT, root);
    for (const file of listFiles(abs)) {
      let text: string;
      try {
        text = readFileSync(file, "utf8");
      } catch {
        continue;
      }
      for (const line of findSecretInText(text, DEFAULT_OWNER_PASSWORD)) {
        hits.push({ file: path.relative(REPO_ROOT, file), line });
      }
    }
  }
  return hits;
}

/** Runs the shipped-UI credential gate; output and exit are injectable host effects. */
export function runDefaultCredentialExposureCheck(
  _required: Record<string, never>,
  { log = console.log, error = console.error, exit = process.exit }: {
    log?: (message: string) => void;
    error?: (message: string) => void;
    exit?: (code: number) => never;
  } = {},
): void {
  const hits = scanForDefaultCredentialExposure();
  if (hits.length === 0) {
    log("check:default-credential — OK: the admin UI does not contain the default password.");
    return;
  }
  error(`check:default-credential — the seeded default password appears in ${hits.length} shipped UI line(s):`);
  for (const hit of hits) error(`  - ${hit.file}:${hit.line}`);
  error(
    "\nThe admin bundle is served to anyone who can reach /admin/, so this publishes working " +
      "credentials. Delete the occurrence. Do not gate it behind a dev-build check: a hint that " +
      "has to be right about its own build environment can be wrong in production.",
  );
  exit(1);
}

// Guarded so importing this module from a test does not scan the real repo and exit the runner.
if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  runDefaultCredentialExposureCheck({});
}

import { isDeepStrictEqual } from "node:util";
import type { ChatDeleteSurfaceDeps } from "#src/contracts/core/chat-delete-grant";
