import sharp, { type Sharp } from "sharp";
import { Validator, type Schema } from "@cfworker/json-schema";

/**
 * @file Pure image operations behind `image_transform`: validate output specs, then resize / crop /
 * rotate / flip / re-encode one source into up to {@link IMAGE_LIMITS.maxOutputs} files, ICO
 * included. Bytes in, bytes out — no filesystem, no Tovu imports — so it can move to a Jini package
 * unchanged once a second host needs it.
 *
 * sharp already strips metadata unless asked to keep it, and auto-orients here, so a phone photo
 * comes out the right way up with no GPS/EXIF. ICO has no sharp encoder: {@link encodeIco} packs
 * PNG entries (valid since Windows Vista, read by every current browser).
 */

export const IMAGE_LIMITS = { maxOutputs: 8, maxDimension: 8192, maxSourceBytes: 25 * 1024 * 1024, maxInputPixels: 64_000_000, timeoutSeconds: 20 } as const;
export type ImageLimits = { -readonly [K in keyof typeof IMAGE_LIMITS]: number };

const FORMATS = { png: ["png"], jpeg: ["jpg", "jpeg"], webp: ["webp"], avif: ["avif"], ico: ["ico"] } as const;
export type ImageFormat = keyof typeof FORMATS;
export const IMAGE_FORMATS = Object.keys(FORMATS) as ImageFormat[];
export const IMAGE_CONTENT_TYPES: Record<ImageFormat, string> = { png: "image/png", jpeg: "image/jpeg", webp: "image/webp", avif: "image/avif", ico: "image/x-icon" };
const SOURCE_FORMATS = new Set(["png", "jpeg", "webp", "gif", "heif", "avif", "tiff", "svg"]);
const DEFAULT_ICO_SIZES = [16, 32, 48];
const CLEAR = { r: 0, g: 0, b: 0, alpha: 0 };

export interface ImageOutput {
  path: string; format: ImageFormat; stripMetadata: boolean; icoSizes: number[];
  resize?: { width?: number; height?: number; fit?: "cover" | "contain" | "inside" | "outside" | "fill"; position?: string; withoutEnlargement?: boolean };
  extract?: { left: number; top: number; width: number; height: number };
  rotate?: number; flip?: boolean; flop?: boolean; background?: string; quality?: number;
}
export interface RenderedImage { path: string; format: ImageFormat; width: number; height: number; bytes: Buffer }

const DIM = { type: "integer", minimum: 1, maximum: IMAGE_LIMITS.maxDimension } as const;
/** Bounds every number that sizes work. Previously sharp rejected bad fit/position/colour by name;
 * the schema now checks fit and types first, and sharp still validates position and colour. */
export const OUTPUT_SCHEMA = { type: "object", additionalProperties: false, required: ["path", "format"], properties: {
  path: { type: "string", minLength: 1, description: "File path in the destination, with the format's extension (theme: e.g. 'assets/favicon.ico'; media: the file name)." },
  format: { type: "string", enum: IMAGE_FORMATS },
  resize: { type: "object", additionalProperties: false, properties: { width: DIM, height: DIM, fit: { type: "string", enum: ["cover", "contain", "inside", "outside", "fill"], description: "Default cover." }, position: { type: "string", description: "cover/contain anchor: centre, top, right top, … or attention/entropy." }, withoutEnlargement: { type: "boolean" } } },
  extract: { type: "object", additionalProperties: false, required: ["left", "top", "width", "height"], description: "Crop this source rectangle first.", properties: { left: { type: "integer", minimum: 0 }, top: { type: "integer", minimum: 0 }, width: DIM, height: DIM } },
  rotate: { type: "number", minimum: -360, maximum: 360 }, flip: { type: "boolean" }, flop: { type: "boolean" },
  background: { type: "string", description: "Colour for contain padding / rotation / jpeg flattening, e.g. '#ffffff'. Default transparent (jpeg: white)." },
  quality: { type: "integer", minimum: 1, maximum: 100 },
  stripMetadata: { type: "boolean", description: "Default true (EXIF/GPS removed)." },
  icoSizes: { type: "array", items: { type: "integer", minimum: 1, maximum: 256 }, minItems: 1, uniqueItems: true, maxItems: 8, description: "ico only; default [16,32,48]." },
} } satisfies Schema;

const outputValidator = new Validator(OUTPUT_SCHEMA);

/** A request a different input fixes; the message names the output and the rule. */
export class ImageTransformError extends Error {
  constructor({ message }: { message: string }, _optional = {}) { super(message); this.name = "ImageTransformError"; }
}
const refuse = (message: string): never => { throw new ImageTransformError({ message }); };

/** Schema first (keys, enums, bounded numbers), then a path extension matching the format, so the
 * file opens as what it is. */
function normalizeOne(raw: unknown, index: number): ImageOutput {
  const o = (raw ?? {}) as Record<string, unknown>;
  const at = `outputs[${index}]`;
  const validation = outputValidator.validate(o);
  if (!validation.valid) refuse(`${at}: ${validation.errors.map((error) => `${error.instanceLocation.replaceAll("/", ".")} ${error.error}`).join("; ")}`);
  const format = o.format as ImageFormat;
  if (!(FORMATS[format] as readonly string[]).includes((o.path as string).split(".").pop()!.toLowerCase())) refuse(`${at}: ${format} needs a .${FORMATS[format][0]} extension on '${String(o.path)}'`);
  return { ...o, format, stripMetadata: o.stripMetadata !== false, icoSizes: (o.icoSizes as number[] | undefined) ?? DEFAULT_ICO_SIZES } as ImageOutput;
}

/**
 * Validates every output before any decode: 1..maxOutputs, unique paths, known keys, supported
 * format with a matching extension, bounded numbers. @throws {ImageTransformError} @complexity O(n).
 */
export function normalizeOutputs({ outputs }: { outputs: unknown }, _optional = {}): ImageOutput[] {
  if (!Array.isArray(outputs) || outputs.length === 0 || outputs.length > IMAGE_LIMITS.maxOutputs) refuse(`'outputs' must list 1 to ${IMAGE_LIMITS.maxOutputs} outputs`);
  const normalized = (outputs as unknown[]).map(normalizeOne);
  if (new Set(normalized.map(({ path }) => path.toLowerCase())).size !== normalized.length) refuse("an output path is listed more than once");
  return normalized;
}

const open = (source: Buffer, limits: ImageLimits): Sharp => sharp(source, { limitInputPixels: limits.maxInputPixels }).timeout({ seconds: limits.timeoutSeconds });

/** Size, format and pixel caps on the source. Undecodable bytes become a caller-facing refusal. */
async function checkSource(source: Buffer, limits: ImageLimits) {
  if (source.length > limits.maxSourceBytes) refuse(`the source is larger than ${limits.maxSourceBytes} bytes`);
  const meta = await open(source, limits).metadata().catch((error: Error) => refuse(`the source is not a supported image or exceeds the input pixel limit: ${error.message}`));
  if (!SOURCE_FORMATS.has(meta.format ?? "")) refuse(`the source is not a supported image (it is ${meta.format})`);
  if (meta.width * meta.height > limits.maxInputPixels) refuse(`the source has more than ${limits.maxInputPixels} pixels`);
  return meta;
}

/** Source facts for planning, without rendering anything. @complexity one header decode. */
export async function inspectImage({ source }: { source: Buffer }, { limits = {} }: { limits?: Partial<ImageLimits> } = {}) {
  const meta = await checkSource(source, { ...IMAGE_LIMITS, ...limits });
  return { format: meta.format === "heif" ? "avif" : meta.format, width: meta.autoOrient.width, height: meta.autoOrient.height, hasAlpha: meta.hasAlpha, bytes: source.length };
}

/** Geometry in a fixed order: orient, crop, rotate, mirror, resize. */
function geometry(image: Sharp, o: ImageOutput): Sharp {
  const background = o.background ?? CLEAR;
  let next = image.autoOrient();
  if (o.extract) next = next.extract(o.extract);
  if (o.rotate) next = next.rotate(o.rotate, { background });
  if (o.flip) next = next.flip();
  if (o.flop) next = next.flop();
  return o.resize ? next.resize({ ...o.resize, background }) : next;
}

async function encode(source: Buffer, o: ImageOutput, limits: ImageLimits): Promise<RenderedImage> {
  let image = geometry(open(source, limits), o);
  if (o.format === "jpeg") image = image.flatten({ background: o.background ?? "#ffffff" });
  if (!o.stripMetadata) image = image.keepMetadata();
  const { data, info } = await image.toFormat(o.format as Exclude<ImageFormat, "ico">, { quality: o.quality }).toBuffer({ resolveWithObject: true });
  if (Math.max(info.width, info.height) > limits.maxDimension) refuse(`${o.path}: output exceeds ${limits.maxDimension}px per side`);
  return { path: o.path, format: o.format, width: info.width, height: info.height, bytes: data };
}

/** ICONDIR + one 16-byte entry per PNG; a 256px side is stored as 0. @complexity O(total bytes). */
export function encodeIco({ entries }: { entries: readonly RenderedImage[] }, _options = {}): Buffer {
  const head = Buffer.alloc(6 + 16 * entries.length);
  head.writeUInt16LE(1, 2);
  head.writeUInt16LE(entries.length, 4);
  let offset = head.length;
  entries.forEach(({ width, height, bytes }, index) => {
    const at = 6 + 16 * index;
    head.writeUInt8(width % 256, at); head.writeUInt8(height % 256, at + 1);
    head.writeUInt16LE(1, at + 4); head.writeUInt16LE(32, at + 6);
    head.writeUInt32LE(bytes.length, at + 8); head.writeUInt32LE(offset, at + 12);
    offset += bytes.length;
  });
  return Buffer.concat([head, ...entries.map(({ bytes }) => bytes)]);
}

async function renderOne(source: Buffer, o: ImageOutput, limits: ImageLimits): Promise<RenderedImage> {
  if (o.format !== "ico") return encode(source, o, limits);
  const pngs = [];
  for (const size of o.icoSizes) pngs.push(await encode(source, { ...o, format: "png", resize: { ...o.resize, fit: o.resize?.fit === "cover" ? "cover" : "contain", width: size, height: size, withoutEnlargement: false } }, limits));
  const largest = pngs.reduce((a, b) => (b.width > a.width ? b : a), pngs[0]!);
  return { path: o.path, format: "ico", width: largest.width, height: largest.height, bytes: encodeIco({ entries: pngs }) };
}

/** Bound derived sizes BEFORE decoding: outside fit and one-sided resizes can amplify aspect ratios.
 * ICO entries have their own forced-square size bound. Rotation uses the bounding rectangle.
 * @throws ImageTransformError on an over-cap side. @complexity O(1). */
function checkOutputSize({ output: o, width, height, maxSide }: { output: ImageOutput; width: number; height: number; maxSide: number }): void {
  if (o.format === "ico") return;
  if (o.extract) { width = o.extract.width; height = o.extract.height; }
  const radians = (o.rotate ?? 0) * Math.PI / 180;
  const rotated = [Math.abs(width * Math.cos(radians)) + Math.abs(height * Math.sin(radians)), Math.abs(height * Math.cos(radians)) + Math.abs(width * Math.sin(radians))];
  [width, height] = rotated as [number, number];
  [width, height] = resizedSides({ sides: [width, height], resize: o.resize });
  if (Math.round(Math.max(width, height)) > maxSide) refuse(`${o.path}: output exceeds ${maxSide}px per side`);
}

/** Predict resize bounds; padded/cover/fill sizes are explicit, outside preserves the aspect ratio. */
function resizedSides({ sides, resize }: { sides: [number, number]; resize: ImageOutput["resize"] }): [number, number] {
  if (!resize) return sides;
  const [width, height] = sides;
  const ratios = [resize.width === undefined ? undefined : resize.width / width, resize.height === undefined ? undefined : resize.height / height].filter((r): r is number => r !== undefined);
  if (!ratios.length) refuse("resize needs width or height");
  let scale = Math.min(...ratios);
  if (resize.fit === "outside") scale = Math.max(...ratios);
  if (resize.withoutEnlargement) scale = Math.min(1, scale);
  if (resize.fit === "outside") return [width * scale, height * scale];
  return [resize.width ?? width * scale, resize.height ?? height * scale];
}

/**
 * Checks the source once, then renders each output in turn (sequential: bounded memory).
 * @throws {ImageTransformError} For a capped, unsupported or undecodable source, or an option sharp rejects.
 * @complexity O(outputs × pixels); each encode bounded by the pixel cap and timeout.
 */
export async function renderOutputs({ source, outputs }: { source: Buffer; outputs: readonly ImageOutput[] }, { limits = {} }: { limits?: Partial<ImageLimits> } = {}): Promise<RenderedImage[]> {
  const merged = { ...IMAGE_LIMITS, ...limits };
  const meta = await checkSource(source, merged);
  for (const output of outputs) checkOutputSize({ output, width: meta.autoOrient.width, height: meta.autoOrient.height, maxSide: merged.maxDimension });
  const rendered: RenderedImage[] = [];
  for (const output of outputs) {
    rendered.push(await renderOne(source, output, merged).catch((error: Error) => refuse(error instanceof ImageTransformError ? error.message : `${output.path}: ${error.message}`)));
  }
  return rendered;
}

import { toolMetadata } from "../../contracts/core/tool-metadata/image-transform.js";
import { buildDomainRegistrations, indexCatalogById, requireInputRecord, withSchemaOnRejection, type AgentToolDefinition, type DerivedRiskByToolId, type ToolRegistration } from "@jini-ai/core";
import type { AssistantSurfaceDeps } from "@jini-ai/daemon/surface-exchanges";
import type { ToolContributor } from "#src/assistant/index";
import { approvalToolHandler, refuseUnexpectedKeys } from "#src/contracts/core/human-confirm";
import { FS_FILES_READ_PERMISSION } from "../fs-files/agent-tools.js";
import { FsFilePathError } from "../fs-files/fs-files.js";
import { FsWriteInputError } from "../fs-files/write-files.js";
import { describeWriteBatch } from "../fs-files/tool-registrations.js";
import { ASSET_SOURCE_SCHEMA, readAssetSource } from "../fs-files/asset-sources.js";
import { requireAssetDestination, prepareAssetWrites, writeAssetFiles, type AssetToolDeps, type PreparedAssets } from "../fs-files/asset-destinations.js";
import { isShapeRejection as isThemeShapeRejection } from "../theme/tool-registrations.js";
import { isImportShapeRejection } from "../media-import/tool-registrations.js";
import { ImageTransformError, OUTPUT_SCHEMA, IMAGE_LIMITS, inspectImage, normalizeOutputs, renderOutputs, type RenderedImage } from "./image-ops.js";

/**
 * @file `image_transform` — one parameterized tool for every resize/crop/convert job (owner
 * 2026-10-27: tools first, Bash/Python last; generic and flexible). Found live: an assistant
 * building a site generated favicon sizes with Python because no tool did it.
 *
 * Reuses, never re-implements: the source resolves through fs-files' roots and denylist
 * (`asset-sources.ts` + guarded reader); writes go through each destination's existing writer
 * and permission — the picked folder through `fs_write_files`' own batch rules and card, a theme
 * through `writeThemeBinaryFile` + reload, the media library through `uploadMedia`. Historically only the
 * picked folder asked (it leaves the site); theme and media writes are undoable edits. Site paths
 * now use that same batch approval because arbitrary site files lack a downstream validator.
 */

export const IMAGE_TRANSFORM_TOOL_ID = "image_transform";
export type ImageTransformToolDeps = AssetToolDeps;

const CATALOG: AgentToolDefinition = {
  name: IMAGE_TRANSFORM_TOOL_ID,
  description: "Resize, crop, rotate, flip and convert ONE image into up to 8 files (png, jpeg, webp, avif, ico) — use this instead of Python/ImageMagick. " +
    "Source: {root, path, themeId?}: site/picked paths, theme-relative assets or media id/slug. No outputs = inspect (width/height/format/bytes), writes nothing. " +
    "Destination: {kind:'site'} (paths relative to site) | {kind:'theme', themeId} | {kind:'media'} (not ico) | {kind:'picked'}. Site/picked writes use the fs_write_files batch approval. " +
    "Recipes — favicon set: [{path:'favicon.ico',format:'ico'},{path:'apple-touch-icon.png',format:'png',resize:{width:180,height:180,fit:'contain'}},{path:'icon-512.png',format:'png',resize:{width:512,height:512,fit:'contain'}}]; " +
    "social image: resize {width:1200,height:630,fit:'cover'}; thumbnail: resize {width:400,fit:'inside'}; to webp: {format:'webp',quality:80}. " +
    `Caps: ${IMAGE_LIMITS.maxDimension}px per side, ${IMAGE_LIMITS.maxInputPixels / 1e6} MP and ${IMAGE_LIMITS.maxSourceBytes / 1024 / 1024} MiB source. Metadata is stripped unless stripMetadata: false.`,
  sideEffects: "mutates-durable-state",
  authorization: { permission: FS_FILES_READ_PERMISSION },
  inputSchema: { type: "object", additionalProperties: false, required: ["source"], properties: {
    source: ASSET_SOURCE_SCHEMA,
    outputs: { type: "array", minItems: 1, maxItems: IMAGE_LIMITS.maxOutputs, items: OUTPUT_SCHEMA },
    destination: { type: "object", additionalProperties: false, required: ["kind"], properties: { kind: { type: "string", enum: ["site", "theme", "media", "picked"] }, themeId: { type: "string", minLength: 1 } } },
  } },
};
export const imageTransformAgentToolCatalog: AgentToolDefinition[] = [CATALOG];
const CATALOG_BY_ID = indexCatalogById({ catalog: imageTransformAgentToolCatalog });

/** -> guarded read + in-memory render; then a theme file, a media item or (carded) picked-folder files. */
export const imageTransformDerivedRisk: DerivedRiskByToolId = new Map([[IMAGE_TRANSFORM_TOOL_ID, "mutates-durable-state"]]);

interface Prepared { source: Awaited<ReturnType<typeof inspectImage>>; rendered: RenderedImage[]; assets?: PreparedAssets }
const isCallerError = (error: unknown) => error instanceof ImageTransformError || error instanceof FsFilePathError || error instanceof FsWriteInputError || isThemeShapeRejection(error) || isImportShapeRejection({ error });
const view = (rendered: readonly RenderedImage[]) => rendered.map(({ path, format, width, height, bytes }) => ({ path, format, width, height, bytes: bytes.length }));

/** Validate and authorize before I/O; all outputs render before any approval or destination write.
 * @throws Input, permission, decode and writer refusals. @complexity O(outputs × pixels), bounded. */
async function prepare({ routeDeps, ctx }: { routeDeps: ImageTransformToolDeps; ctx: Parameters<import("@jini-ai/core").ToolHandler>[0] }): Promise<Prepared> {
  const input = requireInputRecord({ input: ctx.input });
  refuseUnexpectedKeys(input, ["source", "outputs", "destination"]);
  const outputs = input.outputs === undefined ? undefined : normalizeOutputs({ outputs: input.outputs });
  // An inspect needs no destination; it cannot reach a writer.
  const destination = outputs ? await requireAssetDestination({ deps: routeDeps, ctx, input: input.destination }) : undefined;
  const { bytes } = await readAssetSource({ deps: routeDeps, ctx, input: input.source, maxBytes: IMAGE_LIMITS.maxSourceBytes });
  const prepared: Prepared = { source: await inspectImage({ source: bytes }), rendered: outputs ? await renderOutputs({ source: bytes, outputs }) : [] };
  if (destination) prepared.assets = prepareAssetWrites({ deps: routeDeps, destination, files: prepared.rendered });
  return prepared;
}

export function buildImageTransformRegistrations(routeDeps: ImageTransformToolDeps, surfaces: AssistantSurfaceDeps): ToolRegistration[] {
  const handler = approvalToolHandler<Prepared>({ surfaces,
    prepare: ({ ctx }) => withSchemaOnRejection({ toolId: IMAGE_TRANSFORM_TOOL_ID, catalog: CATALOG_BY_ID, isShapeRejection: ({ error }) => isCallerError(error), fn: () => prepare({ routeDeps, ctx }) }),
    describe: ({ prepared }) => describeWriteBatch(prepared.assets?.batch ?? { folder: "", writes: [] }, { toolId: IMAGE_TRANSFORM_TOOL_ID }),
    run: async ({ ctx, prepared }) => {
      const base = { source: prepared.source, outputs: view(prepared.rendered) };
      if (!prepared.assets) return { applied: false, ...base };
      const outcome = await writeAssetFiles({ deps: routeDeps, ctx, prepared: prepared.assets }) as { failed?: unknown };
      return { applied: outcome.failed === undefined, ...base, ...outcome };
    },
  }, { flag: "applied", ask: ({ prepared }) => prepared.assets?.batch !== undefined });
  return buildDomainRegistrations({ metadata: toolMetadata, domain: "image-transform", catalogModule: "features/image-transform/tool.ts",
    catalog: CATALOG_BY_ID, handlers: { [IMAGE_TRANSFORM_TOOL_ID]: handler }, derivedRisk: imageTransformDerivedRisk });
}

/** Contributes `image_transform` — registered once by `tool-catalog-manifest.ts`. */
export function contributeImageTransformTools(): ToolContributor {
  return { domain: "image-transform", build: buildImageTransformRegistrations, risk: imageTransformDerivedRisk };
}

/**
 * @file The one activity operation (email phase 4) behind `mail_list_activity`/`mail_get_activity`
 * and `GET system/mail-activity[/:activityId]`: input parsing, the two-tier access rule, masking,
 * opaque ids and cursors over `features/mail/activity.repo.ts`.
 *
 * Access: `mail.activity.read` sees full recipients, ids and message ids; a holder of only the Email
 * page's status permission (`admin.forms.manage`) sees the same outcomes with masked recipients and
 * no id, so they can read the health of sending without learning who was mailed. A recipient filter
 * is a lookup by address, so it needs full access too. Neither tier ever sees a body, subject or
 * sign-in link: the ledger stores none.
 *
 * Cursors carry only a timestamp and a skip count, never a key or an address, so a masked page's
 * cursor discloses nothing its rows did not.
 */
import { ToolInputError } from "@jini-ai/core";
import type { AuthorizeFn } from "../../contracts/core/commands/index.js";
import {
  MAIL_ACTIVITY_OUTCOMES, MAIL_ACTIVITY_USES, type MailActivityFilter, type MailActivityPosition, type MailActivityRecord, type MailActivityRepo, type MailFeedbackRecord,
} from "../mail/activity.repo.js";
import { MAIL_ACTIVITY_READ_PERMISSION, MAIL_STATUS_PERMISSION } from "./permissions.js";

export const DEFAULT_MAIL_ACTIVITY_LIMIT = 25;
export const MAX_MAIL_ACTIVITY_LIMIT = 100;

export type MailActivityAccess = "full" | "masked";

export interface MailActivityDeps {
  workspaceId: string;
  authorize: AuthorizeFn;
  /** Absent in hermetic roots: every read refuses with {@link MailActivityUnavailableError}. */
  mailActivity?: MailActivityRepo;
}

export interface MailActivityQuery {
  limit: number;
  before?: MailActivityPosition;
  filter: MailActivityFilter;
}

export interface MailActivityItem {
  /** Opaque; present only with full access. Pass to `mail_get_activity`. */
  id?: string;
  recipient: string;
  originalRecipient?: string;
  deliveryMode?: "redirect" | "capture";
  use: MailActivityRecord["use"];
  outcome: MailActivityRecord["outcome"];
  lane: MailActivityRecord["lane"];
  providerId: string;
  providerMessageId?: string | null;
  errorCode: string | null;
  /** Full access only: provider diagnostics can contain recipient addresses. */
  message?: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface MailActivityPage {
  access: MailActivityAccess;
  items: MailActivityItem[];
  nextCursor: string | null;
  /** First page with no rows: nothing was ever recorded, or nothing matches the filters. */
  empty: "none_recorded" | "no_matches" | null;
}

/** The permission refusal both adapters translate (403 / the model-facing forbidden rule). */
export class MailActivityForbiddenError extends Error {
  readonly permission: string;
  constructor(required: { permission: string; message: string }) {
    super(required.message);
    this.name = "MailActivityForbiddenError";
    this.permission = required.permission;
  }
}

export class MailActivityUnavailableError extends Error {
  constructor() {
    super("Email activity is unavailable on this server.");
    this.name = "MailActivityUnavailableError";
  }
}

const encode = (value: unknown): string => Buffer.from(JSON.stringify(value), "utf8").toString("base64url");
function decode({ value }: { value: string }, _options: Record<string, never> = {}): unknown {
  try {
    return JSON.parse(Buffer.from(value, "base64url").toString("utf8"));
  } catch {
    return undefined;
  }
}

/** `a***@example.com`: enough to tell two addresses apart at a glance, not to recover one. */
export function maskRecipient({ address }: { address: string }, _options: Record<string, never> = {}): string {
  const at = address.lastIndexOf("@");
  if (at <= 0) return "***";
  return `${address[0]}***${address.slice(at)}`;
}

function oneOf<T extends string>(required: { value: unknown; allowed: readonly T[]; field: string }, _options: Record<string, never> = {}): T | undefined {
  if (required.value === undefined || required.value === "") return undefined;
  if (typeof required.value === "string" && (required.allowed as readonly string[]).includes(required.value)) return required.value as T;
  throw new ToolInputError({ message: `${required.field} must be one of ${required.allowed.join(", ")}.` });
}

/** A page size from a tool argument or a query string; shared with the suppression list. */
export function readMailPageLimit({ value }: { value: unknown }, _options = {}): number {
  if (value === undefined || value === "") return DEFAULT_MAIL_ACTIVITY_LIMIT;
  const limit = typeof value === "string" ? Number(value) : value;
  if (typeof limit === "number" && Number.isInteger(limit) && limit >= 1 && limit <= MAX_MAIL_ACTIVITY_LIMIT) return limit;
  throw new ToolInputError({ message: `limit must be a whole number from 1 to ${MAX_MAIL_ACTIVITY_LIMIT}.` });
}

/** A keyset position from a `nextCursor` this server returned; shared with the suppression list. */
export function readMailCursor({ value }: { value: unknown }, _options = {}): MailActivityPosition | undefined {
  if (value === undefined || value === "") return undefined;
  const decoded = typeof value === "string" ? (decode({ value: value }) as { c?: unknown; k?: unknown } | undefined) : undefined;
  if (decoded && typeof decoded.c === "string" && typeof decoded.k === "string" && decoded.k.length > 0) return { createdAt: decoded.c, key: decoded.k };
  throw new ToolInputError({ message: "cursor is not a nextCursor this server returned." });
}

function readRecipient({ value }: { value: unknown }, _options: Record<string, never> = {}): string | undefined {
  if (value === undefined || value === "") return undefined;
  if (typeof value === "string" && value.length <= 254 && value.includes("@")) return value.trim().toLowerCase();
  throw new ToolInputError({ message: "recipient must be one email address." });
}

/**
 * Parses list input from a tool's arguments or a route's query string (same field names).
 * @throws {ToolInputError} For any malformed field; nothing is read.
 */
export function readMailActivityQuery({ input }: { input: Record<string, unknown> }, _options: Record<string, never> = {}): MailActivityQuery {
  const outcome = oneOf({ value: input.outcome, allowed: MAIL_ACTIVITY_OUTCOMES, field: "outcome" });
  const use = oneOf({ value: input.use, allowed: MAIL_ACTIVITY_USES, field: "use" });
  const recipient = readRecipient({ value: input.recipient });
  const before = readMailCursor({ value: input.cursor });
  return {
    limit: readMailPageLimit({ value: input.limit }),
    ...(before ? { before } : {}),
    filter: { ...(outcome ? { outcome } : {}), ...(use ? { use } : {}), ...(recipient ? { recipient } : {}) },
  };
}

/**
 * Full with `mail.activity.read`, masked with only `admin.forms.manage`, else refused.
 * @throws {MailActivityForbiddenError} Holding neither (or, with `requireFull`, lacking the first).
 */
export async function resolveMailActivityAccess(
  required: { deps: Pick<MailActivityDeps, "authorize" | "workspaceId">; principalId: string },
  optional: { requireFull?: boolean } = {},
): Promise<MailActivityAccess> {
  const ask = (permission: string) => required.deps.authorize({ principalId: required.principalId, permission, workspaceId: required.deps.workspaceId, entityType: "mail" });
  if ((await ask(MAIL_ACTIVITY_READ_PERMISSION)).allowed) return "full";
  if (!optional.requireFull && (await ask(MAIL_STATUS_PERMISSION)).allowed) return "masked";
  const permission = optional.requireFull ? MAIL_ACTIVITY_READ_PERMISSION : `${MAIL_ACTIVITY_READ_PERMISSION} or ${MAIL_STATUS_PERMISSION}`;
  throw new MailActivityForbiddenError({ permission, message: `principal '${required.principalId}' is not authorized for '${permission}'` });
}

function toItem({ record, access }: { record: MailActivityRecord; access: MailActivityAccess }, _options = {}): MailActivityItem {
  const base = { use: record.use, outcome: record.outcome, lane: record.lane, providerId: record.providerId, errorCode: record.errorCode, createdAt: record.createdAt, updatedAt: record.updatedAt };
  if (access === "masked") return { recipient: maskRecipient({ address: record.recipient }), ...base };
  return { id: encode([record.idempotencyKey, record.recipient]), recipient: record.recipient, ...(record.deliveryMode ? { deliveryMode: record.deliveryMode, originalRecipient: record.originalRecipient } : {}), providerMessageId: record.providerMessageId, message: record.message, ...base };
}

/** The next page's opaque cursor: the page's last timestamp, skipping every row already shown at it.
 *  Shared with the suppression list, whose rows page the same way. */
export function nextMailCursor({ page }: { page: readonly { createdAt: string; cursorKey?: string; revision?: string }[] }, _options = {}): string {
  const last = page.at(-1)!;
  return encode({ c: last.createdAt, k: last.cursorKey ?? last.revision });
}

function repo(deps: MailActivityDeps, _options: Record<string, never> = {}): MailActivityRepo {
  if (!deps.mailActivity) throw new MailActivityUnavailableError();
  return deps.mailActivity;
}

/**
 * One page, newest first. Reads `limit + 1` rows to know whether a next page exists.
 * @throws {MailActivityForbiddenError} Without access, or a recipient filter without full access.
 * @complexity One ledger page read.
 * @example listMailActivity({ principalId, query: readMailActivityQuery({ input: {} }) }, deps)
 */
export async function listMailActivity(required: { principalId: string; query: MailActivityQuery ; deps: MailActivityDeps }, _options: Record<string, never> = {}): Promise<MailActivityPage> {
  const { deps } = required;
  const { query } = required;
  const access = await resolveMailActivityAccess({ deps, principalId: required.principalId }, { requireFull: query.filter.recipient !== undefined });
  const rows = await repo(deps).list({ workspaceId: deps.workspaceId, limit: query.limit + 1 }, { ...query.filter, ...(query.before ? { before: query.before } : {}) });
  const page = rows.slice(0, query.limit);
  const filtered = Object.keys(query.filter).length > 0;
  return {
    access,
    items: page.map((row) => toItem({ record: row, access })),
    nextCursor: rows.length > query.limit ? nextMailCursor({ page }) : null,
    empty: page.length > 0 || query.before ? null : filtered ? "no_matches" : "none_recorded",
  };
}

/** Parses an activity id from `mail_list_activity`. @throws {ToolInputError} When it is not one. */
export function readMailActivityId({ value }: { value: unknown }, _options: Record<string, never> = {}): { idempotencyKey: string; recipient: string } {
  const decoded = typeof value === "string" && value !== "" ? decode({ value: value }) : undefined;
  if (Array.isArray(decoded) && decoded.length === 2 && decoded.every((part) => typeof part === "string")) return { idempotencyKey: decoded[0], recipient: decoded[1] };
  throw new ToolInputError({ message: "activityId must be an id from mail_list_activity." });
}

export interface MailActivityDetail {
  activity: MailActivityItem;
  /** Provider feedback for this message, oldest first; empty means none received yet, not delivered. */
  feedback: MailFeedbackRecord[];
}

/**
 * One send with its feedback timeline. Full access only.
 * @returns `null` when no such send exists in this workspace.
 * @complexity One ledger row and one feedback read.
 */
export async function getMailActivity(required: { principalId: string; activityId: { idempotencyKey: string; recipient: string } ; deps: MailActivityDeps }, _options: Record<string, never> = {}): Promise<MailActivityDetail | null> {
  const { deps } = required;
  await resolveMailActivityAccess({ deps, principalId: required.principalId }, { requireFull: true });
  const found = await repo(deps).get({ workspaceId: deps.workspaceId, ...required.activityId });
  return found ? { activity: toItem({ record: found.record, access: "full" }), feedback: found.feedback } : null;
}

/**
 * @file **Feedback setup** (email phase 5) behind `mail_get_feedback_setup` and
 * `GET system/mail-feedback`: for each active provider, whether it can report deliveries, bounces
 * and complaints, the webhook URL to paste into the provider, whether its signing secret is saved
 * (current and previous rotation slots, `features/mail/feedback-sources.ts`), and the newest
 * verified event.
 *
 * Presence only: the secret slots are read from the credential list by label, never decrypted, so
 * this read cannot leak or even touch a secret. "No events yet" (`no_events_yet`) is reported apart
 * from healthy ingestion (`receiving`), because a webhook nobody has called looks the same as a
 * broken one until the first event arrives.
 */
import type { OriginRegistryPort, VerifiedOrigin } from "@jini-ai/http-kit/verified-origin";
import type { CustomCredentialSetRepoPort } from "../custom-credentials/index.js";
import { listCustomCredentials } from "../custom-credentials/store.js";
import { mailWebhookSecretLabels } from "../mail/feedback-sources.js";
import type { MailSuppressionAdminRepo } from "../mail/suppression-admin.repo.js";
import type { MailProviderConfiguration, MailProviderControl } from "../../platform/mail/mail-status.js";

export interface MailFeedbackSetupDeps {
  workspaceId: string;
  mailProviderControl?: Pick<MailProviderControl, "describe">;
  customCredentialSetRepo?: Pick<CustomCredentialSetRepoPort, "listByWorkspace" | "project">;
  originRegistry?: Pick<OriginRegistryPort, "canonicalOrigin">;
  mailSuppressionAdmin?: Pick<MailSuppressionAdminRepo, "lastFeedbackEvent">;
}

export interface MailWebhookSecretSlot {
  label: string;
  configured: boolean;
  updatedAt: string | null;
}

export interface MailFeedbackProviderSetup {
  providerId: string;
  label: string;
  lanes: readonly ("transactional" | "bulk")[];
  supported: boolean;
  /** `/hooks/mail/<providerId>` (`server/inbound/public-http/routes/mail-feedback.ts`). */
  webhookPath: string;
  /** Absolute, from the site's verified origin; null while the origin is unverified. */
  webhookUrl: string | null;
  signingSecret: { current: MailWebhookSecretSlot; previous: MailWebhookSecretSlot } | null;
  lastVerifiedEvent: { kind: "delivered" | "bounced" | "complained"; receivedAt: string } | null;
  state: "unsupported" | "secret_missing" | "no_events_yet" | "receiving";
}

export interface MailFeedbackSetupReport {
  /** False when this root cannot describe its providers; `providers` is then empty. */
  available: boolean;
  providers: MailFeedbackProviderSetup[];
}

/** Mirrors `features/newsletter/confirmation.ts`'s private `composeOriginUrl` (default ports elided). */
function originUrl(origin: VerifiedOrigin, _options: Record<string, never> = {}): string {
  const isDefaultPort = origin.port === undefined || (origin.scheme === "https" && origin.port === 443) || (origin.scheme === "http" && origin.port === 80);
  return `${origin.scheme}://${isDefaultPort ? origin.host : `${origin.host}:${origin.port}`}${origin.basePath ?? ""}`;
}

async function siteOrigin(deps: MailFeedbackSetupDeps, _options: Record<string, never> = {}): Promise<string | null> {
  if (!deps.originRegistry) return null;
  try {
    return originUrl(await deps.originRegistry.canonicalOrigin({ workspaceId: deps.workspaceId }));
  } catch {
    return null;
  }
}

function slot({ label, saved }: { label: string; saved: Map<string, string> }, _options: Record<string, never> = {}): MailWebhookSecretSlot {
  return { label, configured: saved.has(label), updatedAt: saved.get(label) ?? null };
}

function stateOf(setup: Pick<MailFeedbackProviderSetup, "supported" | "signingSecret" | "lastVerifiedEvent">, _options: Record<string, never> = {}): MailFeedbackProviderSetup["state"] {
  if (!setup.supported) return "unsupported";
  if (!setup.signingSecret?.current.configured && !setup.signingSecret?.previous.configured) return "secret_missing";
  return setup.lastVerifiedEvent ? "receiving" : "no_events_yet";
}

async function providerSetup(deps: MailFeedbackSetupDeps, provider: MailProviderConfiguration, context: { origin: string | null; saved: Map<string, string> }): Promise<MailFeedbackProviderSetup> {
  const supported = provider.capabilities.feedback;
  const webhookPath = `/hooks/mail/${encodeURIComponent(provider.id)}`;
  const [current, previous] = mailWebhookSecretLabels({ providerLabel: provider.label });
  const signingSecret = supported ? { current: slot({ label: current, saved: context.saved }), previous: slot({ label: previous, saved: context.saved }) } : null;
  const lastVerifiedEvent = supported && deps.mailSuppressionAdmin ? await deps.mailSuppressionAdmin.lastFeedbackEvent({ workspaceId: deps.workspaceId, providerId: provider.id }) : null;
  const setup = { providerId: provider.id, label: provider.label, lanes: provider.lanes, supported, webhookPath,
    webhookUrl: supported && context.origin ? `${context.origin}${webhookPath}` : null, signingSecret, lastVerifiedEvent };
  return { ...setup, state: stateOf(setup) };
}

/**
 * Feedback setup for every provider that currently sends for a lane.
 * @complexity One provider describe, one credential list, one origin read and one inbox probe per provider.
 * @example await readMailFeedbackSetup(deps)
 */
export async function readMailFeedbackSetup(deps: MailFeedbackSetupDeps, _options: Record<string, never> = {}): Promise<MailFeedbackSetupReport> {
  if (!deps.mailProviderControl?.describe) return { available: false, providers: [] };
  const report = await deps.mailProviderControl.describe();
  const active = report.providers.filter((provider) => provider.lanes.length > 0);
  const records = deps.customCredentialSetRepo ? await listCustomCredentials({ repo: deps.customCredentialSetRepo }, { workspaceId: deps.workspaceId }) : [];
  const saved = new Map(records.map((record) => [record.label, record.updatedAt] as const));
  const origin = await siteOrigin(deps);
  return { available: true, providers: await Promise.all(active.map((provider) => providerSetup(deps, provider, { origin, saved }))) };
}

/**
 * @file The suppression operations (email phase 5) behind `mail_list_suppressions`,
 * `mail_remove_suppression` and `GET/POST system/mail-suppressions[/remove]`.
 *
 * Reading the list needs `mail.activity.read`: it is a list of addresses, the same recipient detail
 * the activity history guards. Removal needs `mail.suppressions.manage` (owner only; the grant alone is not enough, see
 * `./permissions.ts`), a written reason that is recorded with the removal
 * (`mail_suppression_removals`), and a fresh confirmation every time: the tool's card has no
 * remember option and the route performs only with `confirmed: true`. Removal stops the do-not-send
 * block and nothing else: it never subscribes anyone or restores newsletter consent, and the plan
 * says so before the person confirms.
 */
import { ToolInputError } from "@jini-ai/core";
import type { MailSuppressionScope } from "@jini-ai/platform/mail";
import type { AuthorizeFn } from "../../contracts/core/commands/index.js";
import type { MailSuppressionAdminRepo, MailSuppressionEntry, MailSuppressionReason, MailSuppressionRemoval } from "../mail/suppression-admin.repo.js";
import type { MailActivityPosition } from "../mail/activity.repo.js";
import { MailActivityForbiddenError, nextMailCursor, readMailCursor, readMailPageLimit } from "./activity.js";
import { MAIL_ACTIVITY_READ_PERMISSION, MAIL_SUPPRESSIONS_MANAGE_PERMISSION } from "./permissions.js";

export interface MailSuppressionDeps {
  workspaceId: string;
  authorize: AuthorizeFn;
  ownerPrincipalId?: Promise<string>;
  /** Absent in hermetic roots: every call refuses with {@link MailSuppressionsUnavailableError}. */
  mailSuppressionAdmin?: MailSuppressionAdminRepo;
}

export class MailSuppressionsUnavailableError extends Error {
  constructor() {
    super("The suppression list is unavailable on this server. Nothing was changed.");
    this.name = "MailSuppressionsUnavailableError";
  }
}

const SCOPES = ["all", "bulk"] as const satisfies readonly MailSuppressionScope[];
const REASONS = ["bounced", "complained", "manual"] as const satisfies readonly MailSuppressionReason[];
const MIN_REASON = 3;
const MAX_REASON = 500;

export interface MailSuppressionQuery {
  limit: number;
  before?: MailActivityPosition;
  filter: { search?: string; scope?: MailSuppressionScope; reason?: MailSuppressionReason };
}

export interface MailSuppressionPage {
  items: MailSuppressionEntry[];
  nextCursor: string | null;
  empty: "none_recorded" | "no_matches" | null;
}

function pick<T extends string>(required: { value: unknown; allowed: readonly T[]; field: string; optional: boolean }, _options: Record<string, never> = {}): T | undefined {
  if (required.optional && (required.value === undefined || required.value === "")) return undefined;
  if (typeof required.value === "string" && (required.allowed as readonly string[]).includes(required.value)) return required.value as T;
  throw new ToolInputError({ message: `${required.field} must be one of ${required.allowed.join(", ")}.` });
}

function readSearch({ value }: { value: unknown }, _options: Record<string, never> = {}): string | undefined {
  if (value === undefined || value === "") return undefined;
  if (typeof value === "string" && value.trim().length <= 254) return value.trim() || undefined;
  throw new ToolInputError({ message: "search must be text of at most 254 characters." });
}

/** Parses list input from a tool's arguments or a route's query string. @throws {ToolInputError} */
export function readMailSuppressionQuery({ input }: { input: Record<string, unknown> }, _options: Record<string, never> = {}): MailSuppressionQuery {
  const scope = pick({ value: input.scope, allowed: SCOPES, field: "scope", optional: true });
  const reason = pick({ value: input.reason, allowed: REASONS, field: "reason", optional: true });
  const search = readSearch({ value: input.search });
  const before = readMailCursor({ value: input.cursor });
  return { limit: readMailPageLimit({ value: input.limit }), ...(before ? { before } : {}), filter: { ...(search ? { search } : {}), ...(scope ? { scope } : {}), ...(reason ? { reason } : {}) } };
}

async function authorizedRepo({ deps, principalId, permission }: { deps: MailSuppressionDeps; principalId: string; permission: string }, _options: Record<string, never> = {}): Promise<MailSuppressionAdminRepo> {
  const auth = await deps.authorize({ principalId, permission, workspaceId: deps.workspaceId, entityType: "mail" });
  if (!auth.allowed) throw new MailActivityForbiddenError({ permission, message: `principal '${principalId}' is not authorized for '${permission}'` });
  if (permission === MAIL_SUPPRESSIONS_MANAGE_PERMISSION && principalId !== await deps.ownerPrincipalId) {
    throw new MailActivityForbiddenError({ permission, message: "Only the site owner may remove a suppression." });
  }
  if (!deps.mailSuppressionAdmin) throw new MailSuppressionsUnavailableError();
  return deps.mailSuppressionAdmin;
}

/**
 * One page of blocked recipients, newest first: address, scope, reason and time.
 * @throws {MailActivityForbiddenError} Without `mail.activity.read`.
 * @complexity One indexed page read.
 */
export async function listMailSuppressions(required: { principalId: string; query: MailSuppressionQuery ; deps: MailSuppressionDeps }, _options: Record<string, never> = {}): Promise<MailSuppressionPage> {
  const { deps } = required;
  const { query } = required;
  const repo = await authorizedRepo({ deps: deps, principalId: required.principalId, permission: MAIL_ACTIVITY_READ_PERMISSION });
  const rows = await repo.list({ workspaceId: deps.workspaceId, limit: query.limit + 1 }, { ...query.filter, ...(query.before ? { before: query.before } : {}) });
  const items = rows.slice(0, query.limit);
  const filtered = Object.keys(query.filter).length > 0;
  return {
    items,
    nextCursor: rows.length > query.limit ? nextMailCursor({ page: items }) : null,
    empty: items.length > 0 || query.before ? null : filtered ? "no_matches" : "none_recorded",
  };
}

export interface MailSuppressionRemovalInput {
  address: string;
  scope: MailSuppressionScope;
  reason: string;
}

/** Address, scope and the required reason. @throws {ToolInputError} Nothing is changed. */
export function readMailSuppressionRemoval({ input }: { input: Record<string, unknown> }, _options: Record<string, never> = {}): MailSuppressionRemovalInput {
  const address = typeof input.address === "string" ? input.address.trim().toLowerCase() : "";
  if (!address.includes("@") || address.length > 254) throw new ToolInputError({ message: "address must be the suppressed email address. Nothing was changed." });
  const scope = pick({ value: input.scope, allowed: SCOPES, field: "scope", optional: false }) as MailSuppressionScope;
  const reason = typeof input.reason === "string" ? input.reason.trim() : "";
  if (reason.length < MIN_REASON || reason.length > MAX_REASON) {
    throw new ToolInputError({ message: `reason is required: say why this address may be mailed again (${MIN_REASON}-${MAX_REASON} characters). It is recorded. Nothing was changed.` });
  }
  return { address, scope, reason };
}

export interface MailSuppressionRemovalPlan extends MailSuppressionRemovalInput {
  suppressionReason: MailSuppressionReason;
  suppressedAt: string;
  revision: string;
  /** What removal does and does not mean, shown before the person confirms. */
  warnings: string[];
}

const NO_CONSENT = "Removal only lifts the do-not-send block. It does not subscribe this address or restore newsletter consent.";
const WARNINGS: Record<MailSuppressionReason, string | undefined> = {
  bounced: "This address hard-bounced: the mailbox may not exist. Mailing it again can hurt the site's sender reputation.",
  complained: "This person marked the site's mail as spam. Mailing them again without fresh consent risks further complaints.",
  manual: undefined,
};

/**
 * Checks the permission and that the suppression exists, and describes the removal.
 * @throws {MailActivityForbiddenError} Without `mail.suppressions.manage`.
 * @throws {ToolInputError} When the address is not suppressed in that scope.
 */
export async function planMailSuppressionRemoval(required: { principalId: string; input: MailSuppressionRemovalInput ; deps: MailSuppressionDeps }, _options: Record<string, never> = {}): Promise<MailSuppressionRemovalPlan> {
  const { deps } = required;
  const repo = await authorizedRepo({ deps: deps, principalId: required.principalId, permission: MAIL_SUPPRESSIONS_MANAGE_PERMISSION });
  const entry = await repo.find({ workspaceId: deps.workspaceId, address: required.input.address, scope: required.input.scope });
  if (!entry) throw new ToolInputError({ message: `${required.input.address} is not suppressed for ${required.input.scope} mail. Nothing was changed.` });
  const warning = WARNINGS[entry.reason];
  return { ...required.input, suppressionReason: entry.reason, suppressedAt: entry.createdAt, revision: entry.revision, warnings: [...(warning ? [warning] : []), NO_CONSENT] };
}

/**
 * Removes it, re-checking the permission at the moment of the write, and records the audit row.
 * @returns `removed: false` when it was already removed meanwhile.
 */
export async function runMailSuppressionRemoval(required: { principalId: string; plan: MailSuppressionRemovalPlan ; deps: MailSuppressionDeps }, _options: Record<string, never> = {}): Promise<{ removed: boolean; removal?: MailSuppressionRemoval }> {
  const { deps } = required;
  const repo = await authorizedRepo({ deps: deps, principalId: required.principalId, permission: MAIL_SUPPRESSIONS_MANAGE_PERMISSION });
  const { address, scope, reason } = required.plan;
  const removal = await repo.remove({ workspaceId: deps.workspaceId, address, scope, removalReason: reason, removedBy: required.principalId, revision: required.plan.revision });
  return removal ? { removed: true, removal } : { removed: false };
}

/**
 * @file The ONE test-send operation behind `mail_send_test` and
 * `POST /api/admin/v1/workspaces/:workspaceId/system/mail-test-send` (email design, phase 3:
 * "shared callable test operation + HTTP adapter; optional chosen recipient").
 *
 * The message goes through the site's normal mailer, so suppression, test mode, the provider's own
 * rate limit and the send ledger all still apply; this file adds only what a deliberate,
 * person-triggered test needs on top: a validated recipient (the operator's own address by
 * default), Jini token accounting plus a duplicate-click guard, and a truthful outcome. A result says
 * what is KNOWN at send time (accepted by the provider, captured locally, redirected by test mode,
 * or failed); it never says "delivered", because only later provider feedback could.
 */
import { createMailLaneLimiter } from "@jini-ai/platform/mail";
import { ToolInputError } from "@jini-ai/core";
import type { UserRepoPort } from "@jini-ai/user-management";
import type { MailTestModeSetting } from "../settings/mail-provider.js";
import { isMailDeliveryAvailable, mailSenderIdentityFor, type MailerPort, type MailSenderIdentityPort, type MailTestApproval } from "../../platform/mail/index.js";

/** Placeholder From for a non-delivering mailer; a real provider gets the site's configured sender. */
const TEST_FALLBACK_SENDER = { email: "no-reply@mail.local", name: "Tovu" } as const;

/** A local limiter refusal: `duplicate` is a second click inside the guard window. */
export type MailTestSendRefusal = { ok: false; reason: "duplicate" | "rate_limited"; retryAfterMs: number };

/** Deliberate test sends per site; separate from (and in front of) the provider's own bucket. */
export interface MailTestSendLimiter {
  tryTake(required: { principalId: string; to: string }): { ok: true } | MailTestSendRefusal;
}

/** Ports the operation reads; the field names match `RouteDeps`, so a route can pass its deps through. */
export interface MailTestSendDeps {
  workspaceId: string;
  mailer: MailerPort;
  /** Await current transactional resolution before freezing synchronous capabilities. */
  mailLaneReady?: (required: { lane: "transactional" | "bulk" }) => Promise<boolean>;
  /** The operator's account, for the default recipient. */
  userRepo?: Pick<UserRepoPort, "findByPrincipalId">;
  /** The site's system-mail From (`platform/mail/sender-identity.ts`). */
  mailSenderIdentity?: MailSenderIdentityPort;
  /** Shared by the route and the tool (one per site, `deps.ts`); absent (hermetic roots), only the
   *  provider's own limits apply. */
  mailTestSendLimiter?: MailTestSendLimiter;
  /** Fresh `core.mail.testMode`, so a redirect is reported as one. Absent: treated as off. */
  mailTestMode?: () => Promise<MailTestModeSetting>;
  mailTestProvider?: () => Promise<string | null>;
  /** Site-owned request results, shared by HTTP and tools; no token is taken on replay. */
  mailTestRequests?: Map<string, Promise<MailTestSendResult>>;
}

/** Where the message is meant to go, frozen before any approval card or send. */
export interface MailTestSendPlan {
  to: string;
  /** True when the caller chose the recipient; false for the operator's own address. */
  chosen: boolean;
  approval: MailTestApproval;
  driver: string;
  /** Set when test mode will rewrite the recipient. */
  redirectTo?: string;
  /** True when test mode keeps the message locally instead of sending it. */
  capture?: boolean;
}

interface Common { to: string; from: string; driver: string; at: string }
export type MailTestSendResult =
  /** The provider accepted the message for delivery; delivery itself is not yet known. */
  | Common & { outcome: "accepted"; providerMessageId: string }
  /** Nothing left this machine: kept by test-mode capture or printed by the local console driver. */
  | Common & { outcome: "captured"; where: "capture" | "console"; providerMessageId: string }
  /** Test mode sent it to another address instead of `to`. */
  | Common & { outcome: "redirected"; redirectedTo: string; providerMessageId: string }
  /** Refused or failed; the code and message are the mailer's caller-safe ones. */
  | Common & { outcome: "failed" | "unknown"; errorCode: string; message: string; retryable: boolean; retryAfterMs?: number };

const MAX_ADDRESS = 254;
// One mailbox, no display name, no list: anything else is refused rather than guessed at.
const ADDRESS = /^[^\s@<>()[\]",;:\\]+@[^\s@<>()[\]",;:\\]+\.[^\s@<>()[\]",;:\\]+$/;

/**
 * A chosen recipient, or a caller error. Only one plain address is accepted.
 * @complexity O(address length).
 */
export function readTestRecipient(required: { value: unknown }, _options: Record<string, never> = {}): string | undefined {
  if (required.value === undefined) return undefined;
  const value = typeof required.value === "string" ? required.value.trim() : "";
  if (value.length === 0 || value.length > MAX_ADDRESS || !ADDRESS.test(value)) {
    throw new ToolInputError({ message: "to must be one email address, such as owner@example.com. Nothing was sent." });
  }
  return value;
}

/**
 * The signed-in operator's own address: the account email, else a username that is an address.
 * @throws {ToolInputError} When the account has no address and no recipient was chosen.
 */
async function operatorAddress({ deps, principalId }: { deps: MailTestSendDeps; principalId: string }, _options: Record<string, never> = {}): Promise<string> {
  const user = await deps.userRepo?.findByPrincipalId({ workspaceId: deps.workspaceId, principalId });
  const address = [user?.email, user?.username].find((value) => typeof value === "string" && value.includes("@"));
  if (!address) throw new ToolInputError({ message: "Your account has no email address, so there is nowhere to send a test by default. Enter a recipient, or add an address to your user profile. Nothing was sent." });
  return address;
}

/**
 * Resolve the recipient and say where the message will really go. Sends nothing.
 * @param required.principalId - The operator; their account address is the default recipient.
 * @param required.to - An already validated chosen recipient ({@link readTestRecipient}).
 * @complexity One user lookup and one settings read.
 * @example await planMailTestSend({ deps, principalId, to: "ops@example.com" })
 */
export async function planMailTestSend(required: { principalId: string; to?: string ; deps: MailTestSendDeps }, _options: Record<string, never> = {}): Promise<MailTestSendPlan> {
  const { deps } = required;
  await deps.mailLaneReady?.({ lane: "transactional" });
  const to = required.to ?? await operatorAddress({ deps: deps, principalId: required.principalId });
  const mode = deps.mailTestMode ? await deps.mailTestMode() : { mode: "off" as const };
  const identity = mailSenderIdentityFor({ mailer: deps.mailer }, deps.mailSenderIdentity ? { senderIdentity: deps.mailSenderIdentity } : {});
  const from = await identity.resolve({ workspaceId: deps.workspaceId, fallback: TEST_FALLBACK_SENDER });
  const providerId = deps.mailTestProvider ? await deps.mailTestProvider() : null;
  return {
    to, chosen: required.to !== undefined, driver: deps.mailer.capabilities().driver,
    approval: { providerId, driver: deps.mailer.capabilities().driver, from, mode: mode.mode, effectiveRecipient: mode.mode === "redirect" ? mode.to : to },
    ...(mode.mode === "redirect" ? { redirectTo: mode.to } : {}), ...(mode.mode === "capture" ? { capture: true } : {}),
  };
}

const REFUSALS: Readonly<Record<MailTestSendRefusal["reason"], { errorCode: string; message: string }>> = {
  duplicate: { errorCode: "MAIL_TEST_DUPLICATE", message: "A test email to this address was just sent; wait a moment before sending another." },
  rate_limited: { errorCode: "MAIL_TEST_RATE_LIMITED", message: "Too many test emails were sent recently; try again later." },
};

/** What the mailer's answer means for this plan, most local explanation first. */
function outcomeOf({ plan, providerMessageId, mailer }: { plan: MailTestSendPlan; providerMessageId: string; mailer: MailerPort }, _options: Record<string, never> = {}): MailTestSendResult["outcome"] | "console" {
  if (providerMessageId.startsWith("captured:")) return "captured";
  if (!isMailDeliveryAvailable(mailer)) return "console";
  return plan.redirectTo === undefined ? "accepted" : "redirected";
}

function successResult({ common, plan, providerMessageId, mailer }: { common: Common; plan: MailTestSendPlan; providerMessageId: string; mailer: MailerPort }, _options: Record<string, never> = {}): MailTestSendResult {
  const outcome = outcomeOf({ plan: plan, providerMessageId: providerMessageId, mailer: mailer });
  if (outcome === "captured" || outcome === "console") return { ...common, outcome: "captured", where: outcome === "console" ? "console" : "capture", providerMessageId };
  if (outcome === "redirected") return { ...common, outcome, redirectedTo: plan.redirectTo!, providerMessageId };
  return { ...common, outcome: "accepted", providerMessageId };
}

/**
 * Send one test email as planned and report what is known. Refusals (local limiter, suppression,
 * provider) come back as `outcome: "failed"` with their own code, never as a throw.
 * @param required.plan - From {@link planMailTestSend}; re-validated permissions are the caller's job.
 * @param required.ref - Stable id of this request (tool execution id or the route's request id): the
 *   idempotency key, so a retried request replays the ledger's answer instead of sending twice.
 * @param optional.now - Clock for the result timestamp; defaults to `Date.now`.
 * @complexity One limiter take and at most one delivery.
 * @example await runMailTestSend({ deps, principalId, plan, ref: ctx.executionId })
 */
export async function runMailTestSend(
  required: { deps: MailTestSendDeps; principalId: string; plan: MailTestSendPlan; ref: string },
  optional: { now?: () => number } = {},
): Promise<MailTestSendResult> {
  const { deps, plan } = required;
  const key = `${required.principalId}:${required.ref}`;
  const existing = deps.mailTestRequests?.get(key);
  if (existing) return existing;
  const pending = performMailTestSend(required, optional);
  if (deps.mailTestRequests && deps.mailTestRequests.size >= 4096) {
    deps.mailTestRequests.delete(deps.mailTestRequests.keys().next().value!);
  }
  deps.mailTestRequests?.set(key, pending);
  // A failed dependency read has not dispatched a message and may be retried.
  pending.catch(() => { if (deps.mailTestRequests?.get(key) === pending) deps.mailTestRequests.delete(key); });
  return pending;
}

/** Validate the frozen approval before any limiter take or dispatch. */
async function performMailTestSend(
  required: { deps: MailTestSendDeps; principalId: string; plan: MailTestSendPlan; ref: string },
  optional: { now?: () => number } = {},
): Promise<MailTestSendResult> {
  const { deps, plan } = required;
  const fresh = await planMailTestSend({ ...{ principalId: required.principalId, to: plan.to }, deps: deps });
  if (JSON.stringify(fresh.approval) !== JSON.stringify(plan.approval)) {
    throw new ToolInputError({ message: "Mail configuration changed since approval. Prepare a new test-send approval; nothing was sent." });
  }
  const at = () => new Date((optional.now ?? Date.now)()).toISOString();
  const from = fresh.approval.from;
  const base = { to: plan.to, from: from.email, driver: plan.driver };
  const taken = deps.mailTestSendLimiter?.tryTake({ principalId: required.principalId, to: plan.to.toLowerCase() }) ?? { ok: true as const };
  if (!taken.ok) return { ...base, at: at(), outcome: "failed", ...REFUSALS[taken.reason], retryable: true, retryAfterMs: taken.retryAfterMs };
  const result = await deps.mailer.send(
    { workspaceId: deps.workspaceId, to: { email: plan.to }, from, subject: "Test email from your site", text: "This is a test email sent at your request. If you can read it, your site can deliver email." },
    // The operator is waiting on this message: transactional, interactive lane.
    { mailTestApproval: plan.approval, idempotencyKey: `mail:test:${required.principalId}:${required.ref}`, workspaceId: deps.workspaceId, sourceContext: { module: "mail", ref: required.ref }, purpose: "transactional", lane: "interactive" },
  );
  const common = { ...base, at: at() };
  if (result.ok) return successResult({ common: common, plan: plan, providerMessageId: result.providerMessageId, mailer: deps.mailer });
  return { ...common, outcome: result.unknown ? "unknown" : "failed", errorCode: result.errorCode, message: testSendFailureMessage({ errorCode: result.errorCode }), retryable: result.unknown ? false : result.retryable, ...(result.retryAfterMs === undefined ? {} : { retryAfterMs: result.retryAfterMs }) };
}

/** Only locally owned codes get specific copy; provider/SMTP text is never caller-safe. */
const SAFE_SEND_FAILURES: Readonly<Record<string, string>> = {
  MAIL_TEST_DUPLICATE: REFUSALS.duplicate.message,
  MAIL_TEST_RATE_LIMITED: REFUSALS.rate_limited.message,
  MAIL_TEST_CAPTURE_UNAVAILABLE: "Capture mode is unavailable. Nothing was sent.",
  MAIL_TEST_APPROVAL_CHANGED: "Mail configuration changed. Prepare a new approval; nothing was sent.",
  MAIL_RECIPIENT_SUPPRESSED: "The recipient is on the do-not-send list. Nothing was sent.",
  MAIL_RATE_LIMITED: "The mail delivery rate limit was reached. Try again later.",
  MAIL_UNCONFIGURED: "No mail provider is configured. Nothing was sent.",
  MAIL_PROVIDER_UNAVAILABLE: "The configured mail provider is unavailable. Check its configuration.",
};

/** Fixed copy by code, without reading the provider's message. @complexity O(1). */
function testSendFailureMessage({ errorCode }: { errorCode: string }, _optional: Record<string, never> = {}): string {
  const safe = Object.hasOwn(SAFE_SEND_FAILURES, errorCode) ? SAFE_SEND_FAILURES[errorCode] : undefined;
  return safe ?? `The provider refused the message (code ${errorCode}).`;
}

/** Defaults: 5 deliberate tests in a burst, one more every 12 minutes; a second click within 15 s is a duplicate. */
export const TEST_SEND_BURST = 5;
export const TEST_SEND_REFILL_MS = 12 * 60_000;
export const TEST_SEND_DUPLICATE_MS = 15_000;

/**
 * One site-wide token bucket plus a per-(operator, recipient) duplicate-click guard, in memory.
 * In memory is enough here: it protects inboxes and the provider quota from repeated clicks, and
 * the send ledger's idempotency key already covers a replayed request.
 * @param optional.now - Clock in ms; defaults to `Date.now`.
 * @complexity O(1) amortized per take; the duplicate map keeps only entries inside the window.
 * @example createMailTestSendLimiter({}, { now: () => 0 }).tryTake({ principalId: "p", to: "a@b.co" })
 */
export function createMailTestSendLimiter(
  _required: Record<string, never> = {},
  optional: { now?: () => number; burst?: number; refillMs?: number; duplicateMs?: number } = {},
): MailTestSendLimiter {
  const now = optional.now ?? Date.now;
  const burst = optional.burst ?? TEST_SEND_BURST;
  const refillMs = optional.refillMs ?? TEST_SEND_REFILL_MS;
  const duplicateMs = optional.duplicateMs ?? TEST_SEND_DUPLICATE_MS;
  const bucket = createMailLaneLimiter({ limit: { burst, perSecond: 1000 / refillMs } }, { now, reservedForTransactional: 0 });
  const lastByKey = new Map<string, number>();
  return {
    tryTake: ({ principalId, to }) => {
      const at = now();
      for (const [key, last] of lastByKey) if (at - last >= duplicateMs) lastByKey.delete(key);
      const key = `${principalId}\u0000${to}`;
      const last = lastByKey.get(key);
      if (last !== undefined) return { ok: false, reason: "duplicate", retryAfterMs: duplicateMs - (at - last) };
      const taken = bucket.tryTake({ lane: "transactional" });
      if (!taken.ok) return { ...taken, reason: "rate_limited" };
      lastByKey.set(key, at);
      return { ok: true };
    },
  };
}

/**
 * @file Read projection over the send ledger joined with provider feedback (email phase 4): the
 * Email page's **Recent sends and failures** and `mail_list_activity`/`mail_get_activity`. One SQL
 * body for SQLite and Postgres; migrations 0029 and 0031 add the source and lookup indexes.
 *
 * Only body-free metadata leaves here: the ledger stores no subject, body or link, and this never
 * reads `mail_capture`. Outcomes are derived, never stored:
 *
 * - `sent` rows are `accepted` until feedback says more; the most severe event wins
 *   (complained > bounced > delivered), joined by the provider's message id.
 * - `failed` rows keep the policy's reason: `MAIL_RECIPIENT_SUPPRESSED` is `suppressed`,
 *   `MAIL_RATE_LIMITED` is `deferred`, anything else `failed`.
 * - `reserved` (in flight, or a crash mid-send) and `unknown` are `unknown`: the provider may have
 *   taken it, which is exactly why there is no general Resend.
 *
 * The observer persists use (purpose) from the idempotency key prefix each owner already writes
 * (`members:signin:`, `newsletter:confirm-email:`, `forms:notify:`, `newsletter:`, `mail:test:`).
 * Historical ledgers derive it within the recent window; any other key is `unknown` rather than
 * guessed.
 */
import { sql, type RawBuilder } from "kysely";
import type { MailRepoDeps } from "./ledger.repo.js";
import { MAIL_ACTIVITY_RETENTION_MS } from "./retention.js";

export const MAIL_ACTIVITY_OUTCOMES = ["accepted", "delivered", "bounced", "complained", "suppressed", "deferred", "failed", "unknown", "captured"] as const;
export type MailActivityOutcome = (typeof MAIL_ACTIVITY_OUTCOMES)[number];
export const MAIL_ACTIVITY_USES = ["sign_in", "newsletter_confirmation", "form_notification", "newsletter", "test", "unknown"] as const;
export type MailActivityUse = (typeof MAIL_ACTIVITY_USES)[number];

export interface MailActivityRecord {
  cursorKey: string;
  originalRecipient?: string;
  deliveryMode?: "redirect" | "capture";
  idempotencyKey: string;
  recipient: string;
  lane: "transactional" | "bulk";
  providerId: string;
  use: MailActivityUse;
  outcome: MailActivityOutcome;
  providerMessageId: string | null;
  errorCode: string | null;
  message: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface MailFeedbackRecord {
  kind: "delivered" | "bounced" | "complained";
  hardBounce: boolean;
  providerId: string;
  occurredAt: string;
  receivedAt: string;
}

/** Keyset position: rows at or before `createdAt`, skipping the `skip` already returned at exactly that time. */
export interface MailActivityPosition {
  createdAt: string;
  key: string;
}

export interface MailActivityFilter {
  outcome?: MailActivityOutcome;
  use?: MailActivityUse;
  /** Exact address, compared lowercased as the ledger stores it. */
  recipient?: string;
}

export interface MailActivityRepo {
  list(required: { workspaceId: string; limit: number }, optional?: MailActivityFilter & { before?: MailActivityPosition }): Promise<MailActivityRecord[]>;
  get(required: { workspaceId: string; idempotencyKey: string; recipient: string }): Promise<{ record: MailActivityRecord; feedback: MailFeedbackRecord[] } | null>;
}

type Row = {
  activity_id: string; effective_recipient: string; delivery_mode: "off" | "capture" | "redirect"; idempotency_key: string; recipient: string; lane: "transactional" | "bulk"; provider_id: string; use_id: MailActivityUse;
  activity_outcome: MailActivityOutcome; provider_message_id: string | null; error_code: string | null; message: string | null; created_at: string; updated_at: string;
};

const USE_PREFIXES = [
  ["members:signin:", "sign_in"], ["newsletter:confirm-email:", "newsletter_confirmation"],
  ["forms:notify:", "form_notification"], ["mail:test:", "test"], ["newsletter:", "newsletter"],
] as const;

/** Classify an observation once, before writing it; unknown keys stay explicitly unknown. */
export function mailActivityUse({ idempotencyKey }: { idempotencyKey: string }, _optional: Record<string, never> = {}): MailActivityUse {
  return USE_PREFIXES.find(([prefix]) => idempotencyKey.startsWith(prefix))?.[1] ?? "unknown";
}

/** Historical ledgers predate the purpose column. Only their recent window is projected. */
function legacyUse(_required: Record<string, never> = {}, _optional: Record<string, never> = {}): RawBuilder<unknown> {
  const clauses = USE_PREFIXES.map(([prefix, use]) => {
    const pattern = `${prefix}%`;
    return sql`WHEN old.idempotency_key LIKE ${pattern} THEN ${use}`;
  });
  return sql`CASE ${sql.join(clauses, sql` `)} ELSE 'unknown' END`;
}

const feedbackExists = (kind: MailFeedbackRecord["kind"]) => sql`EXISTS (SELECT 1 FROM mail_feedback_inbox f
  WHERE f.workspace_id = l.workspace_id AND f.provider_message_id = l.provider_message_id AND f.provider_id = l.provider_id AND f.recipient = l.effective_recipient AND f.kind = ${kind} AND f.processed_at IS NOT NULL)`;

type SourceQuery = { workspaceId: string; cutoff: string; filter: MailActivityFilter & { before?: MailActivityPosition }; limit?: number; idempotencyKey?: string; effectiveOnly?: boolean };

/** Push non-derived predicates into each indexed source; outcome is resolved after feedback. */
function sourceConditions(required: SourceQuery & { legacy: boolean }, _optional: Record<string, never> = {}): RawBuilder<unknown> {
  const { filter, legacy } = required;
  const alias = legacy ? "old" : "a";
  const col = (name: string) => sql.ref(`${alias}.${name}`);
  const where = [sql`${col("workspace_id")} = ${required.workspaceId}`, sql`${col("created_at")} >= ${required.cutoff}`];
  if (filter.use) where.push(sql`${legacy ? legacyUse() : col("use_id")} = ${filter.use}`);
  if (required.idempotencyKey) where.push(sql`${col("idempotency_key")} = ${required.idempotencyKey}`);
  if (filter.recipient) where.push(recipientCondition({ ...required, recipient: filter.recipient }));
  if (filter.before) where.push(sql`(${col("created_at")} < ${filter.before.createdAt} OR (${col("created_at")} = ${filter.before.createdAt} AND ${col(legacy ? "activity_id" : "id")} < ${filter.before.key}))`);
  return sql.join(where, sql` AND `);
}

/** Exact effective-recipient lookup for details; list filters also match the original address. */
function recipientCondition(required: { legacy: boolean; recipient: string; effectiveOnly?: boolean }, _optional: Record<string, never> = {}): RawBuilder<unknown> {
  const address = required.recipient.trim().toLowerCase();
  const original = sql.ref(required.legacy ? "old.recipient" : "a.recipient");
  const effective = sql.ref(required.legacy ? "old.recipient" : "a.effective_recipient");
  return required.effectiveOnly ? sql`${effective} = ${address}` : sql`(${original} = ${address} OR ${effective} = ${address})`;
}

/** Limit each ordered source before the UNION/feedback work on ordinary page reads. */
function activitySources(required: SourceQuery, _optional: Record<string, never> = {}): RawBuilder<unknown> {
  const limit = required.limit === undefined ? sql`` : sql`LIMIT ${required.limit}`;
  return sql`SELECT * FROM (
    SELECT a.id AS activity_id, a.workspace_id, a.idempotency_key, a.recipient, a.effective_recipient, a.delivery_mode,
      a.lane, a.provider_id, a.outcome, a.provider_message_id, a.error_code, a.message, a.created_at, a.updated_at, a.use_id
      FROM mail_activity_attempts a WHERE ${sourceConditions({ ...required, legacy: false })}
      ORDER BY a.created_at DESC, a.id DESC ${limit}
    ) attempts
    UNION ALL SELECT * FROM (
      SELECT old.activity_id, old.workspace_id, old.idempotency_key, old.recipient, old.recipient AS effective_recipient, 'off' AS delivery_mode,
        old.lane, old.provider_id, old.outcome, old.provider_message_id, old.error_code, NULL AS message, old.created_at, old.updated_at, ${legacyUse()} AS use_id
      FROM mail_send_ledger old WHERE ${sourceConditions({ ...required, legacy: true })}
        AND old.activity_retained = 1 AND NOT EXISTS (SELECT 1 FROM mail_activity_attempts a
          WHERE a.workspace_id = old.workspace_id AND a.idempotency_key = old.idempotency_key AND a.recipient = old.recipient)
      ORDER BY old.created_at DESC, old.activity_id DESC ${limit}
    ) legacy`;
}

/** Feedback is probed only for candidate rows; the attempts' stored purpose remains indexable. */
function projection(required: SourceQuery, _optional: Record<string, never> = {}): RawBuilder<unknown> {
  return sql`SELECT l.*,
    CASE WHEN l.outcome = 'captured' THEN 'captured' WHEN l.outcome = 'sent' THEN
        CASE WHEN ${feedbackExists("complained")} THEN 'complained' WHEN ${feedbackExists("bounced")} THEN 'bounced'
          WHEN ${feedbackExists("delivered")} THEN 'delivered' ELSE 'accepted' END
      WHEN l.outcome = 'failed' THEN
        CASE WHEN l.error_code = 'MAIL_RECIPIENT_SUPPRESSED' THEN 'suppressed' WHEN l.error_code = 'MAIL_RATE_LIMITED' THEN 'deferred' ELSE 'failed' END
      ELSE 'unknown' END AS activity_outcome
    FROM (${activitySources(required)}) l`;
}

function toRecord(row: Row): MailActivityRecord {
  return {
    cursorKey: row.activity_id, idempotencyKey: row.idempotency_key, recipient: row.effective_recipient,
    ...(row.delivery_mode === "off" ? {} : { originalRecipient: row.recipient, deliveryMode: row.delivery_mode }), lane: row.lane, providerId: row.provider_id, use: row.use_id,
    outcome: row.activity_outcome, providerMessageId: row.provider_message_id, errorCode: row.error_code, message: row.message, createdAt: row.created_at, updatedAt: row.updated_at,
  };
}

/**
 * The activity reads. Newest first by creation, ties broken by the opaque activity id, so a page boundary
 * inside one timestamp is resumed by its keyset position without exposing a key or address in the cursor.
 * @complexity Ordinary lists merge at most two limit-sized indexed candidate pages, then probe
 * feedback at most three times per candidate. The legacy branch can scan the recent 30-day window
 * for purpose/duplicate exclusion. Outcome filters evaluate candidates in that window before LIMIT;
 * they are not constant-time indexed reads. Detail uses indexed identity/recipient predicates.
 * @example createMailActivityRepo({ db: kernel }).list({ workspaceId, limit: 26 }, { outcome: "bounced" })
 */
export function createMailActivityRepo<DB>({ db }: MailRepoDeps<DB>, optional: { now?: () => number } = {}): MailActivityRepo {
  const cutoff = () => new Date((optional.now ?? Date.now)() - MAIL_ACTIVITY_RETENTION_MS).toISOString();
  return {
    async list(required, optional = {}) {
      const source: SourceQuery = { workspaceId: required.workspaceId, cutoff: cutoff(), filter: optional, ...(optional.outcome ? {} : { limit: required.limit }) };
      const outcome = optional.outcome ? sql`WHERE a.activity_outcome = ${optional.outcome}` : sql``;
      const rows = await db.query<Row>(sql`SELECT * FROM (${projection(source)}) a ${outcome}
        ORDER BY a.created_at DESC, a.activity_id DESC LIMIT ${required.limit}`);
      return rows.map(toRecord);
    },
    async get({ workspaceId, idempotencyKey, recipient }) {
      const [row] = await db.query<Row>(sql`SELECT * FROM (${projection({ workspaceId, cutoff: cutoff(), filter: { recipient }, idempotencyKey, effectiveOnly: true, limit: 1 })}) a LIMIT 1`);
      if (!row) return null;
      const feedback = row.provider_message_id === null ? [] : await db.query<{ kind: MailFeedbackRecord["kind"]; hard_bounce: number; provider_id: string; occurred_at: string; received_at: string }>(
        sql`SELECT kind, hard_bounce, provider_id, occurred_at, received_at FROM mail_feedback_inbox
          WHERE workspace_id = ${workspaceId} AND provider_message_id = ${row.provider_message_id} AND provider_id = ${row.provider_id} AND recipient = ${row.effective_recipient} AND processed_at IS NOT NULL ORDER BY occurred_at, event_id`);
      return {
        record: toRecord(row),
        feedback: feedback.map((event) => ({ kind: event.kind, hardBounce: Number(event.hard_bounce) === 1, providerId: event.provider_id, occurredAt: event.occurred_at, receivedAt: event.received_at })),
      };
    },
  };
}

/** Body-free observation of every policy result, including preflight refusals and captures. */
import { safeMailProviderText } from "#src/platform/mail/provider-error";
import { mailActivityUse } from "./activity.repo.js";
import { randomUUID } from "node:crypto";
import { sql } from "kysely";
import { laneForPurpose } from "@jini-ai/platform/mail";
import type { MailRepoDeps, MailRepoOptions } from "./ledger.repo.js";
import type { MailTestModeSetting } from "#src/features/settings/mail-provider";
import type { MailerSendOptions, MailerSendResult, OutboundEmail } from "#src/platform/mail/index";

/** The delivery policy's per-result observer. Declared here (not in server/) so features never import server code. */
export type MailAttemptObserver = (required: { message: OutboundEmail; options: MailerSendOptions; providerId: string; mode: MailTestModeSetting; result: MailerSendResult }) => Promise<void>;

/** Upsert one request's latest result without changing its original position in activity history.
 * @complexity One indexed write; no subject, body or authentication link is stored; only a scrubbed failure diagnostic. */
export function createMailAttemptObserver<DB>({ db }: MailRepoDeps<DB>, options: MailRepoOptions & { newId?: () => string } = {}): MailAttemptObserver {
  const nowIso = options.nowIso ?? (() => new Date().toISOString());
  const newId = options.newId ?? randomUUID;
  return async ({ message, options: send, providerId, mode, result }) => {
    const at = nowIso();
    const recipient = message.to.email.trim().toLowerCase();
    const effective = mode.mode === "redirect" ? mode.to.trim().toLowerCase() : recipient;
    const outcome = result.ok ? ((result.providerMessageId.startsWith("captured:") || providerId === "console") ? "captured" : "sent") : (result.unknown ? "unknown" : "failed");
    await db.execute(sql`INSERT INTO mail_activity_attempts
      (id, workspace_id, idempotency_key, recipient, effective_recipient, delivery_mode, use_id, lane, provider_id, outcome, provider_message_id, error_code, message, created_at, updated_at)
      VALUES (${newId()}, ${send.workspaceId}, ${send.idempotencyKey}, ${recipient}, ${effective}, ${mode.mode}, ${mailActivityUse({ idempotencyKey: send.idempotencyKey })}, ${laneForPurpose({ purpose: send.purpose })}, ${providerId}, ${outcome}, ${result.ok ? result.providerMessageId : null}, ${result.ok ? null : safeMailProviderText({ text: result.errorCode })}, ${result.ok ? null : safeMailProviderText({ text: result.message })}, ${at}, ${at})
      ON CONFLICT (workspace_id, idempotency_key, recipient) DO UPDATE SET
        effective_recipient = excluded.effective_recipient, delivery_mode = excluded.delivery_mode, use_id = excluded.use_id,
        provider_id = excluded.provider_id, outcome = excluded.outcome, provider_message_id = excluded.provider_message_id,
        error_code = excluded.error_code, message = excluded.message, updated_at = excluded.updated_at`);
  };
}

/**
 * @file The operator side of the do-not-send list and the feedback inbox (email phase 5, migration
 * 0030): list and search suppressions, remove one with an audit record, and read the newest
 * verified feedback event per provider. One SQL body for SQLite and Postgres.
 *
 * The send-time side stays `suppression.repo.ts` (Jini's `MailSuppressionRepoPort`), untouched: a
 * removal deletes the 0023 row so send-time checks remain one primary-key probe, and the audit row
 * written in the same transaction keeps what was removed, by whom, when and why.
 */
import { randomUUID } from "node:crypto";
import { sql, type RawBuilder } from "kysely";
import type { MailSuppressionScope } from "@jini-ai/platform/mail";
import type { MailRepoDeps } from "./ledger.repo.js";

export type MailSuppressionReason = "bounced" | "complained" | "manual";

export interface MailSuppressionEntry {
  address: string;
  scope: MailSuppressionScope;
  reason: MailSuppressionReason;
  createdAt: string;
  revision: string;
}

export interface MailSuppressionRemoval {
  id: string;
  address: string;
  scope: MailSuppressionScope;
  suppressionReason: MailSuppressionReason;
  suppressedAt: string;
  removalReason: string;
  removedBy: string;
  removedAt: string;
}

export interface MailSuppressionListFilter {
  /** Substring of the address, matched lowercased; `%` and `_` are literal. */
  search?: string;
  scope?: MailSuppressionScope;
  reason?: MailSuppressionReason;
  before?: { createdAt: string; key: string };
}

export interface MailSuppressionAdminRepo {
  list(required: { workspaceId: string; limit: number }, optional?: MailSuppressionListFilter): Promise<MailSuppressionEntry[]>;
  find(required: { workspaceId: string; address: string; scope: MailSuppressionScope }): Promise<MailSuppressionEntry | null>;
  /** Deletes the suppression and records the removal atomically; `null` when it was not suppressed. */
  remove(required: { workspaceId: string; address: string; scope: MailSuppressionScope; removalReason: string; removedBy: string; revision: string }): Promise<MailSuppressionRemoval | null>;
  /** The newest verified webhook event for a provider; only verified events are ever recorded. */
  lastFeedbackEvent(required: { workspaceId: string; providerId: string }): Promise<{ kind: "delivered" | "bounced" | "complained"; receivedAt: string } | null>;
}

type Row = { normalized_address: string; scope: MailSuppressionScope; reason: MailSuppressionReason; created_at: string; revision: string };

const toEntry = (row: Row): MailSuppressionEntry => ({ address: row.normalized_address, scope: row.scope, reason: row.reason, createdAt: row.created_at, revision: row.revision });
const normalize = (address: string): string => address.trim().toLowerCase();
const likeLiteral = (term: string): string => `%${normalize(term).replace(/[\\%_]/g, (c) => `\\${c}`)}%`;

function conditions(workspaceId: string, optional: MailSuppressionListFilter): RawBuilder<unknown>[] {
  const where: RawBuilder<unknown>[] = [sql`workspace_id = ${workspaceId}`];
  if (optional.search) where.push(sql`normalized_address LIKE ${likeLiteral(optional.search)} ESCAPE '\\'`);
  if (optional.scope) where.push(sql`scope = ${optional.scope}`);
  if (optional.reason) where.push(sql`reason = ${optional.reason}`);
  if (optional.before) where.push(sql`(created_at < ${optional.before.createdAt} OR (created_at = ${optional.before.createdAt} AND revision < ${optional.before.key}))`);
  return where;
}

/**
 * @complexity One indexed page read per list; O(1) primary-key statements per find/remove.
 * @example createMailSuppressionAdminRepo({ db: kernel }).list({ workspaceId, limit: 26 }, { search: "example.com" })
 */
export function createMailSuppressionAdminRepo<DB>({ db }: MailRepoDeps<DB>, optional: { nowIso?: () => string; newId?: () => string } = {}): MailSuppressionAdminRepo {
  const nowIso = optional.nowIso ?? (() => new Date().toISOString());
  const newId = optional.newId ?? randomUUID;
  const find: MailSuppressionAdminRepo["find"] = async ({ workspaceId, address, scope }) => {
    const [row] = await db.query<Row>(sql`SELECT normalized_address, scope, reason, created_at, revision FROM mail_suppression
      WHERE workspace_id = ${workspaceId} AND normalized_address = ${normalize(address)} AND scope = ${scope}`);
    return row ? toEntry(row) : null;
  };
  return {
    async list(required, filter = {}) {
      const rows = await db.query<Row>(sql`SELECT normalized_address, scope, reason, created_at, revision FROM mail_suppression
        WHERE ${sql.join(conditions(required.workspaceId, filter), sql` AND `)}
        ORDER BY created_at DESC, revision DESC LIMIT ${required.limit}`);
      return rows.map(toEntry);
    },
    find,
    remove: (required) => db.transaction(async () => {
      await db.lockKey(`mail-suppression:${required.workspaceId}:${normalize(required.address)}:${required.scope}`);
      // DELETE claims the reviewed incarnation. A replacement cannot inherit an old approval;
      // RETURNING also ensures only the winning transaction can write an audit record.
      const [row] = await db.query<Row>(sql`DELETE FROM mail_suppression
        WHERE workspace_id = ${required.workspaceId} AND normalized_address = ${normalize(required.address)}
          AND scope = ${required.scope} AND revision = ${required.revision}
        RETURNING normalized_address, scope, reason, created_at, revision`);
      if (!row) return null;
      const entry = toEntry(row);
      const removal: MailSuppressionRemoval = {
        id: newId(), address: entry.address, scope: entry.scope, suppressionReason: entry.reason, suppressedAt: entry.createdAt,
        removalReason: required.removalReason, removedBy: required.removedBy, removedAt: nowIso(),
      };
      await db.execute(sql`INSERT INTO mail_suppression_removals (id, workspace_id, normalized_address, scope, suppression_reason, suppressed_at, removal_reason, removed_by, removed_at)
        VALUES (${removal.id}, ${required.workspaceId}, ${removal.address}, ${removal.scope}, ${removal.suppressionReason}, ${removal.suppressedAt}, ${removal.removalReason}, ${removal.removedBy}, ${removal.removedAt})`);
      return removal;
    }),
    async lastFeedbackEvent({ workspaceId, providerId }) {
      const [row] = await db.query<{ kind: "delivered" | "bounced" | "complained"; received_at: string }>(sql`SELECT kind, received_at FROM mail_feedback_inbox
        WHERE workspace_id = ${workspaceId} AND provider_id = ${providerId} AND processed_at IS NOT NULL ORDER BY received_at DESC, event_id DESC LIMIT 1`);
      return row ? { kind: row.kind, receivedAt: row.received_at } : null;
    },
  };
}

import { toolMetadata } from '../../contracts/core/tool-metadata/media-generation.js';
import { CREDENTIAL_SAVE_TOOL_ID } from "../../contracts/headless/secret-form-cards.js";
import { assertCredentialFreeField, CREDENTIAL_MESSAGES, type CredentialTokenHint } from '../../contracts/core/credential-token.js';
import { credentialText, formatCredentialHint } from '../../contracts/core/credential-copy.js';
import { resolveOperatorLocale, type OperatorLocaleDeps } from '../agent-plugins/operator-locale.js';
import { type Clock } from "@jini-ai/core/primitives";
import { adaptLegacyAuthorize } from "@jini-ai/cms/core";
import { buildDomainRegistrations, indexCatalogById, optionalString, requireInputRecord, requireNoInput, requireString, type DerivedRiskByToolId, type ToolRegistration } from "@jini-ai/core";
import { requireToolPermission } from "@jini-ai/cms/core";
import { ToolInputError, type ToolExecutionOptions, type ToolExecutionContext } from '@jini-ai/core';
import type { MediaModel, MediaProvider } from '@jini-ai/integrations/media-providers/catalog';
import { defineSecretCardTool } from '@jini-ai/ui/mcp-ui/secret-card';
import type { AuthorizeFn } from '../../contracts/core/commands/index.js';
import { askThenReport, type AssistantSurfaceDeps } from "@jini-ai/daemon/surface-exchanges";
import type { ToolContributor } from '#src/assistant/index';
import { getMediaProviderCredentials, type MediaProviderCredentialRepoPort } from '../media/provider-credential-store.js';
import type { KeyringPort, SecretSealerPort } from '../webhooks/index.js';
import type { AgentToolDefinition } from "@jini-ai/core";
import { saveMediaProviderKey } from './provider-credential-save.js';

/** Native credential setup uses the existing MCP-UI exchange; secrets never enter model input/result. */
interface ProviderView { id: string; label: string; kinds: Array<'image' | 'video'>; integrated: boolean; configured: boolean }
interface ProposalResult { saved: boolean; provider: string; configured: boolean; tokenHint?: CredentialTokenHint | null; message?: string; connection?: "not_tested" }
export interface MediaProviderToolDeps extends OperatorLocaleDeps {
  workspaceId: string;
  authorize: AuthorizeFn;
  mediaProviderCredentialRepo: MediaProviderCredentialRepoPort;
  siteAssistantSecretSealer: SecretSealerPort;
  siteAssistantSecretKeyring: KeyringPort;
  clock: Clock;
  /** The composition-built media provider registry (built-in + plugin vendors); listing and the
   *  credential form read it, so a plugin vendor can be listed and given a key like a built-in one. */
  mediaProviderRegistry: MediaProviderListing;
}

/** Structurally the part of `MediaProviderRegistry` this file reads (keeps the catalog-only import). */
export interface MediaProviderListing {
  listProviders(): readonly MediaProvider[];
  modelsForSurface(required: { surface: 'image' | 'video' }): readonly MediaModel[];
  findProvider(required: { id: string }): MediaProvider | null;
}

interface CatalogueProvider { id: string; label: string; integrated: boolean; kinds: Array<'image' | 'video'> }

/** Image/video providers in registry order, with the surfaces they offer.
 * @complexity Time/space O(p + m), registered providers plus image/video models. */
function catalogueProviders(catalog: MediaProviderListing): CatalogueProvider[] {
  const imageIds = new Set(catalog.modelsForSurface({ surface: 'image' }).map(model => model.provider));
  const videoIds = new Set(catalog.modelsForSurface({ surface: 'video' }).map(model => model.provider));
  return catalog.listProviders().flatMap(provider => {
    const kinds: Array<'image' | 'video'> = [];
    if (imageIds.has(provider.id)) kinds.push('image');
    if (videoIds.has(provider.id)) kinds.push('video');
    return kinds.length === 0 ? [] : [{ id: provider.id, label: provider.label, integrated: provider.integrated, kinds }];
  });
}

export const mediaProvidersAgentToolCatalog: AgentToolDefinition[] = [
  {
    name: 'media_list_providers',
    description: 'Lists the catalogued image/video generation providers and which have a saved workspace key. Call to inspect media provider setup before generation or opening a credential form. Returns {providers:[{id,label,kinds,integrated,configured}]}; configured means saved key presence, not live verification or adapter support. Never returns keys, prefixes, suffixes or lengths. Uses the same media.read permission and saved credential source as the admin Media providers tab. Does not inspect process environment credentials. Permission denial refuses the call.',
    sideEffects: 'none', authorization: { permission: 'media.read' },
    inputSchema: { type: 'object', additionalProperties: false, required: [], properties: {} },
  },

];
export const mediaProvidersDerivedRisk: DerivedRiskByToolId = new Map([
  // -> getMediaProviderCredentials: marker-only repo read, no decrypt or writes.
  ['media_list_providers', 'none'],
  // -> saveMediaProviderKey -> saveMediaProviderCredentials: seals and writes after human submit.

]);
const CATALOG = indexCatalogById({ catalog: mediaProvidersAgentToolCatalog });

/** Marker-only listing with an explicit safe projection; same saved source as GET /media/providers.
 * @complexity Time/space O(p + s), catalogued providers plus saved rows. No decrypt.
 */
async function listProviders(deps: MediaProviderToolDeps): Promise<{ providers: ProviderView[] }> {
  const stored = await getMediaProviderCredentials({ repo: deps.mediaProviderCredentialRepo }, { workspaceId: deps.workspaceId });
  return { providers: catalogueProviders(deps.mediaProviderRegistry).map(provider => ({ id: provider.id, label: provider.label, kinds: [...provider.kinds], integrated: provider.integrated, configured: stored[provider.id]?.apiKeyConfigured === true })) };
}

/** Shared safe copy for the model result and human outcome; no submitted key is accepted.
 * @complexity Time/space O(m), the formatted message length; no I/O.
 */
function savedProviderMessage({ provider, tokenHint, locale }: {
  provider: { integrated: boolean }; tokenHint: CredentialTokenHint | null | undefined; locale: string;
}, _optional = {}): string {
  const hint = formatCredentialHint({ hint: tokenHint, locale });
  const unavailable = provider.integrated === false ? ` ${credentialText({ id: 'generationUnavailable', locale })}` : '';
  return `${hint ? `${hint}. ` : ''}${credentialText({ id: 'saved', locale })}${unavailable}`;
}

/** Strict non-secret model input; bound provider identity is never taken from the form submission.
 * @throws ToolInputError for unknown fields/providers or a missing interactive channel.
 * @complexity Time O(p + s) before a single store patch; space O(p + s).
 */
export async function saveMediaCredential(required: { ctx: ToolExecutionContext; deps: MediaProviderToolDeps; surfaces: AssistantSurfaceDeps }, optional: ToolExecutionOptions = {}): Promise<ProposalResult> {
  const { ctx, deps, surfaces } = required;
  const raw = requireInputRecord({ input: ctx.input });
  if (Object.keys(raw).some(key => key !== 'provider' && key !== 'reason')) throw new ToolInputError({ message: 'media_propose_provider_credential accepts only provider and reason; enter the key in the human form.' });
  const providerId = requireString({ input: raw, key: 'provider' });
  const provider = catalogueProviders(deps.mediaProviderRegistry).find(candidate => candidate.id === providerId);
  if (!provider) throw new ToolInputError({ message: 'Unknown media provider. Call media_list_providers for supported provider ids.' });
  const reason = optionalString({ input: raw, key: 'reason' });
  if (reason !== undefined) assertCredentialFreeField({ value: reason, field: "reason" });
  if (reason !== undefined && reason.length > 1000) throw new ToolInputError({ message: 'Credential setup reason must be at most 1000 characters.' });
  await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: 'admin.integrations.manage' }, { entityType: 'media' });
  const { providers } = await listProviders(deps);
  const configured = providers.find(candidate => candidate.id === providerId)!.configured;
  const locale = await resolveOperatorLocale({ deps, workspaceId: deps.workspaceId, principalId: ctx.principal.id });
  const saveFailure = 'Nothing was saved. Check the key and the server credential store, then try again.';
  // Strict non-secret validation and authorization retain their precedence over channel errors.
  const card = defineSecretCardTool<{
    provider: CatalogueProvider; configured: boolean; reason: string | undefined; locale: string;
  }, Awaited<ReturnType<typeof saveMediaProviderKey>>, ProposalResult>({
    toolId: CREDENTIAL_SAVE_TOOL_ID,
    prepare: async () => ({ provider, configured, reason, locale }),
    form: ({ prep }) => ({
      title: `Connect ${prep.provider.label}`,
      description: prep.reason ?? 'Type the API key directly into this form. The assistant never sees it.',
      submitLabel: 'Save provider key',
      fields: [{ kind: 'string', name: 'apiKey', label: 'API key', secret: true, required: !prep.configured, allowBlank: prep.configured }],
    }),
    save: ({ values, prep, signal }) => {
      const store = deps.mediaProviderCredentialRepo;
      const repo: MediaProviderCredentialRepoPort = {
        vault: store.vault,
        listByWorkspaceId: workspaceId => store.listByWorkspaceId(workspaceId),
        upsert: record => store.upsert(record),
        deleteByProviderIds: input => store.deleteByProviderIds(input),
        // The planner runs inside the transaction, after sealing and any lock wait. Abort rolls it back.
        replaceWorkspace: input => store.replaceWorkspace({ ...input, plan: current => {
          signal.throwIfAborted();
          return input.plan(current);
        } }),
      };
      return saveMediaProviderKey({
        deps: { repo, sealer: deps.siteAssistantSecretSealer, keyring: deps.siteAssistantSecretKeyring, clock: deps.clock, providerCatalog: deps.mediaProviderRegistry },
        workspaceId: deps.workspaceId, provider: prep.provider.id, apiKey: values.apiKey as string,
      });
    },
    result: ({ prep, run }): ProposalResult => {
      const declined: ProposalResult = { saved: false, provider: prep.provider.id, configured: prep.configured };
      if (run.status === 'blank') return { ...declined, message: credentialText({ id: 'blank', locale: prep.locale }) };
      if (run.status === 'failed') return { ...declined, ...(run.safeMessage !== saveFailure ? { message: run.safeMessage } : {}) };
      if (run.status !== 'saved') return declined;
      const message = savedProviderMessage({ provider: prep.provider, tokenHint: run.saved.tokenHint, locale: prep.locale });
      return { saved: true, provider: prep.provider.id, configured: run.saved.configured, tokenHint: run.saved.tokenHint, connection: 'not_tested', message };
    },
    // Fixed outcome text cannot echo a submitted key or a raw persistence error.
    outcome: ({ prep, run }) => {
      if (run.status === 'cancelled' || run.status === 'expired' || run.status === 'abandoned') return undefined;
      const saved = run.status === 'saved';
      const message = run.status === 'saved' ? savedProviderMessage({ provider: prep.provider, tokenHint: run.saved.tokenHint, locale: prep.locale })
        : run.status === 'blank' ? credentialText({ id: 'blank', locale: prep.locale }) : run.status === 'failed' ? run.safeMessage : saveFailure;
      return { title: saved ? 'Provider key saved' : 'Provider key not saved', state: saved ? 'success' : 'failure', message };
    },
  }, {
    uriHost: 'tovu',
    text: { noEmitter: 'media_propose_provider_credential requires an interactive form channel. Nothing was saved.', saveFailure },
    safeError: err => {
      const id = Object.entries(CREDENTIAL_MESSAGES).find(([, text]) => err instanceof Error && text === err.message)?.[0];
      return id ? credentialText({ id: id as keyof typeof CREDENTIAL_MESSAGES, locale }) : undefined;
    },
    logFailure: metadata => console.warn(JSON.stringify(metadata)),
  });
  return card.handler({ surfaceExchanges: surfaces.surfaceExchanges, askThenReport })(ctx, optional);
}

/** Wires read-only listing and human credential saves under a distinct contributor domain.
 * @example buildMediaProviderRegistrations(deps, { surfaceExchanges });
 * @complexity Registration time/space O(1); handlers document their own I/O costs.
 */
export function buildMediaProviderRegistrations(deps: MediaProviderToolDeps, surfaces: AssistantSurfaceDeps): ToolRegistration[] {
  return buildDomainRegistrations({ metadata: toolMetadata, domain: 'media-providers', catalogModule: 'features/media-generation/providers-tools.ts', catalog: CATALOG,
    derivedRisk: mediaProvidersDerivedRisk, handlers: {
      media_list_providers: async ctx => {
        requireNoInput({ input: ctx.input });
        await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: 'media.read' }, { entityType: 'media' });
        return listProviders(deps);
      },
    } });
}

/** Composition-root entrypoint; type-only assistant dependency.
 * @example registerToolContributor(contributeMediaProviderTools());
 * @complexity Time/space O(1).
 */
export function contributeMediaProviderTools(): ToolContributor {
  return { domain: 'media-providers', build: buildMediaProviderRegistrations, risk: mediaProvidersDerivedRisk };
}

import { sniffContentType, type MediaRecord } from "#src/features/media/index";
import type { AssetBlobRepoPort, BlobStorePort } from "@jini-ai/cms/media";
import type { MediaContentTypeStorePort } from "./content-type-store.js";

/**
 * @file Content-type resolution shared by admin media DTOs and static-export URL upgrades.
 *
 * `toAdminMediaResponse` takes `contentType` as a required parameter because it cannot be derived
 * from `MediaRecord` (`@jini-ai/cms`'s type has no such field — see `media/content-type-store.ts`
 * for why the type lives in a side port). This module is the one place that answers it, so the
 * list route and the three single-record routes cannot drift into disagreeing about what a `null`
 * means.
 */

/** The deps slice this module reads — the store plus the two ports the read-path backfill needs. */
export interface ContentTypeDeps {
  readonly workspaceId: string;
  readonly mediaContentTypeStore: MediaContentTypeStorePort;
  readonly assetBlobRepo: AssetBlobRepoPort;
  readonly blobStore: BlobStorePort;
}

/**
 * Resolves every listed asset's content type, sniffing and PERSISTING the type of any blob that
 * does not have one recorded yet.
 *
 * Why backfill on read rather than in the migration that added the column: the type is
 * `sniffContentType(bytes)`, and the bytes live in the blob STORE (a filesystem/S3 concern), not
 * in SQL — a migration cannot reach them. Nor is there anything else to derive a type from: the
 * original filename is never stored at all (`uploadMedia`'s `deriveTitleFromFilename` strips the
 * extension before saving `media.title`), so an extension- or filename-based guess is not merely
 * less accurate here, it is impossible. Magic bytes are the only available source, and they are
 * the exact source `original.ts` already trusts when it serves those same bytes — so a backfilled
 * type is the real answer, not an inference.
 *
 * This converges: each blob is sniffed at most once ever, and only blobs still missing a type are
 * read. After one load of the Media screen a pre-existing library is fully typed, so there is no
 * permanent "untyped" bucket for old uploads to fall into. The cost is bounded by the number of
 * un-backfilled blobs, not by list size, and is paid once.
 *
 * A blob whose bytes cannot be read is skipped rather than failing the whole list — one unreadable
 * asset must not blank the operator's entire media library. Its row goes out with a `null`
 * `contentType`, which the admin UI keeps visible rather than filtering away.
 *
 * @complexity O(n) map lookups plus one blob read per not-yet-sniffed blob.
 */
export async function resolveContentTypes(
  deps: ContentTypeDeps,
  media: readonly MediaRecord[]
): Promise<Map<string, string>> {
  // Document type is a validated filename policy, not a per-blob sniff cache: identical text
  // bytes can legitimately be saved as .md and .txt. Listing must never download those bytes.
  const sha256s = [...new Set(media.filter(item => item.kind !== "document").map((item) => item.source.sha256))];
  const recorded = await deps.mediaContentTypeStore.getMany({ workspaceId: deps.workspaceId, sha256s });

  for (const sha256 of sha256s) {
    if (recorded.has(sha256)) continue;
    try {
      const blob = await deps.assetBlobRepo.findByHash({ workspaceId: deps.workspaceId, sha256 });
      if (!blob) continue;
      const contentType = sniffContentType({ bytes: await deps.blobStore.get({ storageKey: blob.storageKey }) });
      await deps.mediaContentTypeStore.set({ workspaceId: deps.workspaceId, sha256, contentType });
      recorded.set(sha256, contentType);
    } catch {
      // Unreadable blob (missing file, permissions, storage outage). Left unrecorded so a later
      // list retries, and this one row goes out untyped.
      continue;
    }
  }
  return recorded;
}

/**
 * One asset's recorded content type, or `null` if none is recorded yet.
 *
 * Deliberately does NOT backfill, unlike {@link resolveContentTypes}: this serves the write routes
 * (`upload`/`update`/`trash`), whose job is to report the result of the write the caller just made.
 * Reading a blob's bytes to enrich a PATCH response would add unrelated storage I/O to every
 * metadata edit, and the admin UI invalidates and refetches the list after each write anyway — so
 * the backfill happens a moment later on the read path, where it belongs.
 *
 * @complexity O(1) — a single-key batch lookup.
 */
export async function readRecordedContentType(
  deps: Pick<ContentTypeDeps, "workspaceId" | "mediaContentTypeStore">,
  sha256: string
): Promise<string | null> {
  const recorded = await deps.mediaContentTypeStore.getMany({
    workspaceId: deps.workspaceId,
    sha256s: [sha256],
  });
  return recorded.get(sha256) ?? null;
}

import { readFile, readdir } from "node:fs/promises";
import type { Dirent } from "node:fs";
import { join, relative, sep } from "node:path";

import type { BlobStorePort } from "@jini-ai/cms/media";

/**
 * @file `hydrateBlobStoreFromSeed()` — fills in stock blob BYTES for `asset_blobs` rows a fresh
 * site inherited from `content.seed.db` (see `hydrate-content-db-from-seed.ts`'s header for that
 * half of the pair).
 *
 * -----------------------------------------------------------------------------------------------
 * The gap this closes
 * -----------------------------------------------------------------------------------------------
 * `npm run seed:site` prunes and ships `content.seed.db` — including `media`/`asset_blobs` rows,
 * neither of which is in `seed-site.mjs`'s `PRUNE_TABLES` list. `hydrateContentDbFromSeed()` then
 * copies those rows into a fresh deploy's `content.db` on first boot. Nothing analogous ever
 * shipped the BYTES those rows' `storage_key`s point at: the Dockerfile's build stage previously
 * extracted only `content.seed.db` before `RUN rm -rf sites` wiped the whole `sites/` tree (which
 * is where `uploads/` — and therefore every blob's bytes — actually lives). Confirmed live on
 * the hosted production site's `/admin/media`: real `media`/`asset_blobs` rows, zero corresponding files, every
 * preview 500s and falls back to the placeholder icon. This function is the missing other half —
 * same "read-only stock source shipped in the image, copied into the site's own mutable copy"
 * shape `seedSiteThemes()` and `hydrateContentDbFromSeed()` already use for `themes/` and
 * `content.db`. The Dockerfile's own build stage now stages the matching `uploads/` payload
 * alongside `content.seed.db` (see that file's comment at the extraction loop) — this function is
 * the boot-time consumer of that payload.
 *
 * -----------------------------------------------------------------------------------------------
 * Why this does NOT reuse either sibling's "whole-thing presence" gate
 * -----------------------------------------------------------------------------------------------
 * `hydrateContentDbFromSeed()` gates on one file's existence; `seedSiteThemes()` gates on one
 * directory's existence — both correct for a THING that is copied once, as a single unit, and never
 * partially seeded again. `uploads/` is not that shape: it is a content-addressed, ever-growing SET
 * of independent files that real usage adds to throughout a site's life, and — the reason this
 * function exists at all — it may already hold real files (from a boot before this function
 * existed, or from ordinary use) by the time this code ships. A whole-directory presence gate would
 * make the fix's own effect depend on incidental state this code has no way to inspect (does
 * `uploads/` already exist for some unrelated reason?) and could silently leave THIS EXACT bug
 * unfixed on the very deploy meant to fix it. So the gate here applies the same underlying rule —
 * never touch something that might already be real, only fill in what is provably absent — at the
 * store's actual unit of identity: one content-addressed key at a time, via `BlobStorePort
 * .putIfAbsent()`. An existing key, however it got there, is left exactly as it is; only a key
 * genuinely missing from the live store gets written. This also means the function is safe to run
 * on EVERY boot, not just a first one: every call after the first is an all-`skipped` no-op once
 * the store catches up.
 *
 * This used to be a separate `exists()` check followed by a separate `put()` — a check-then-act
 * pair with a real TOCTOU gap: a real uploader's write landing in that gap got silently overwritten
 * by this function's stock seed bytes. `putIfAbsent()` collapses the two into one call the adapter
 * itself makes atomic (the local store's `"wx"` open flag; the s3-compatible object-store provider's
 * conditional `If-None-Match` PUT — see each provider's own doc), closing the gap outright rather than narrowing
 * it. Safe to do unconditionally specifically because this store is content-addressed: whichever
 * writer's bytes end up stored for a given key, they are — short of a sha256 collision — the same
 * bytes any other writer for that key would have written; `putIfAbsent` only needs to guarantee no
 * concurrent writer's write gets torn or clobbered, not that this function's copy "wins".
 *
 * -----------------------------------------------------------------------------------------------
 * Why this goes through `BlobStorePort`, not a filesystem copy
 * -----------------------------------------------------------------------------------------------
 * The SOURCE (the seed payload the image ships) is always a plain directory — that's how the
 * Dockerfile stages it, mirroring `content.seed.db`'s own extraction. The DESTINATION is whatever
 * `createMediaBlobStore()` (`features/object-storage`) resolved for this deployment: the local
 * filesystem store by default, or the bundled s3-compatible object-store provider for any operator
 * who sets `TOVU_MEDIA_BLOB_STORE=s3` (or picks a remote provider in the site's storage setting). Writing straight to a filesystem path would
 * silently stop working — with no error, just permanently-missing bytes on the very backend this
 * fix exists to protect against — the moment an operator makes that switch. Going through
 * `blobStore.putIfAbsent()` instead means this function needs no change at all if the backend
 * changes: same one call, whichever `BlobStorePort` implementation `deps.ts` handed it.
 *
 * Architectural role:
 * Fire-and-forget async boot effect (unlike its two sync siblings above — `BlobStorePort` itself is
 * async), wired the same way `media/bootstrap.ts`'s `ensureCoreMediaTransform` chain is in
 * `deps.ts`: does not gate any request, and its caller logs-and-swallows failure so one bad seed
 * file can never fail boot. Pure filesystem-read + port-write effect, no domain logic of its own.
 */

/**
 * `seedUploadsDir`'s expected shape for one blob file, relative to that root:
 * `ws/{workspaceId}/blobs/{sha256[0..1]}/{sha256}` — `computeBlobStorageKey`'s own template
 * (`blob-key.ts`). Anything else found under the seed payload is not this function's to interpret.
 */
const SEED_BLOB_PATH_PATTERN = /^ws\/([^/]+)\/blobs\/[0-9a-f]{2}\/([0-9a-f]{64})$/;

/** One seed file this run could not resolve into a live blob, and why. */
export interface HydrateBlobStoreFromSeedFailure {
  readonly relativePath: string;
  readonly error: string;
}

/**
 * `"seeded"` — at least one previously-missing blob was written, none failed.
 * `"already-present"` — every seed blob already existed in the live store; nothing written.
 * `"no-seed-source"` — `seedUploadsDir` does not exist (a site with no shipped upload payload).
 * `"partial"` — at least one seed file could not be resolved or written; see `failed`.
 */
export type HydrateBlobStoreFromSeedStatus = "seeded" | "already-present" | "no-seed-source" | "partial";

export interface HydrateBlobStoreFromSeedResult {
  readonly status: HydrateBlobStoreFromSeedStatus;
  /** Number of blobs actually written to the live store this run. */
  readonly copied: number;
  /** Number of seed blobs that already existed in the live store and were left untouched. */
  readonly skipped: number;
  readonly failed: readonly HydrateBlobStoreFromSeedFailure[];
}

export interface HydrateBlobStoreFromSeedRequired {
  /** The read-only stock upload payload shipped with the image (sibling of `content.seed.db`). */
  readonly seedUploadsDir: string;
  /** The site's real, running blob store — only `putIfAbsent` is needed. */
  readonly blobStore: Pick<BlobStorePort, "putIfAbsent">;
}

/**
 * Recursively lists every FILE under `dir`, as paths relative to `root` with `/`-separated
 * segments regardless of platform — matching the `/`-joined shape `computeBlobStorageKey` and
 * `storage_key` column values already use.
 *
 * @returns `[]` when `root` itself does not exist (a site with no shipped upload payload) — not an
 *   error, mirrors `hydrateContentDbFromSeed`'s `no-seed-source` treatment of an absent stock file.
 * @complexity O(n) in the number of files and directories under `root`.
 */
async function listSeedBlobRelativePaths(root: string, dir: string = root): Promise<string[]> {
  let entries: Dirent[];
  try {
    entries = await readdir(dir, { withFileTypes: true });
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw err;
  }

  const results: string[] = [];
  for (const entry of entries) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...(await listSeedBlobRelativePaths(root, full)));
    } else if (entry.isFile()) {
      results.push(relative(root, full).split(sep).join("/"));
    }
  }
  return results;
}

/** One seed file's resolution — extracted so {@link hydrateBlobStoreFromSeed}'s own loop is pure
 *  tallying, never a decision. See that function's own doc, and this file's header, for the per-key
 *  `putIfAbsent` gate this implements. */
type SeedBlobOutcome =
  | { readonly kind: "copied" }
  | { readonly kind: "skipped" }
  | { readonly kind: "failed"; readonly failure: HydrateBlobStoreFromSeedFailure };

/**
 * Resolves ONE seed file: shape-check its path, then read + `putIfAbsent` its bytes.
 * @throws Never — every failure mode (bad path shape, unreadable file, store write failure) is
 *   reported as a `"failed"` outcome instead, matching {@link hydrateBlobStoreFromSeed}'s own
 *   "never fail the whole run over one bad seed file" contract.
 */
async function resolveOneSeedBlob(
  seedUploadsDir: string,
  blobStore: Pick<BlobStorePort, "putIfAbsent">,
  relativePath: string
): Promise<SeedBlobOutcome> {
  const match = SEED_BLOB_PATH_PATTERN.exec(relativePath);
  const [, workspaceId, sha256] = match ?? [];
  if (workspaceId === undefined || sha256 === undefined) {
    return {
      kind: "failed",
      failure: {
        relativePath,
        error: "does not match the expected ws/{workspaceId}/blobs/{shard}/{sha256} shape",
      },
    };
  }

  try {
    const bytes = await readFile(join(seedUploadsDir, relativePath));
    // Single atomic call — see this file's header for why a separate `exists()` check first
    // would reopen the exact TOCTOU gap this function used to have.
    const { written } = await blobStore.putIfAbsent({ workspaceId, sha256, bytes });
    return written ? { kind: "copied" } : { kind: "skipped" };
  } catch (err) {
    return { kind: "failed", failure: { relativePath, error: err instanceof Error ? err.message : String(err) } };
  }
}

/** Derives the run-level status from the tallies — see {@link HydrateBlobStoreFromSeedStatus}'s own doc. */
function computeHydrateStatus(copied: number, failedCount: number): HydrateBlobStoreFromSeedStatus {
  if (failedCount > 0) return "partial";
  return copied > 0 ? "seeded" : "already-present";
}

/**
 * Tops up the live blob store with any stock seed blob it is missing, one content-addressed key at
 * a time. See this file's header for why the gate is per-key rather than per-directory, and why the
 * write goes through `BlobStorePort` rather than a filesystem copy.
 *
 * @param required.seedUploadsDir - Read-only stock payload shipped with the image.
 * @param required.blobStore - The real, running blob store to fill in.
 * @returns Per-run outcome — see {@link HydrateBlobStoreFromSeedStatus}.
 * @throws Never for a missing/malformed individual seed file (recorded in `failed` instead, so one
 *   bad file cannot block the rest); only for an error `listSeedBlobRelativePaths` itself does not
 *   treat as "no seed source" (e.g. a permissions failure reading the seed payload's own tree).
 * @complexity O(n) blob-store round trips (one `putIfAbsent` per file) in the number of files under
 *   `seedUploadsDir` — bounded by how many blobs this site's seed ships, not by anything
 *   request-variable.
 */
export async function hydrateBlobStoreFromSeed(
  required: HydrateBlobStoreFromSeedRequired
): Promise<HydrateBlobStoreFromSeedResult> {
  const { seedUploadsDir, blobStore } = required;

  const relativePaths = await listSeedBlobRelativePaths(seedUploadsDir);
  if (relativePaths.length === 0) {
    return { status: "no-seed-source", copied: 0, skipped: 0, failed: [] };
  }

  let copied = 0;
  let skipped = 0;
  const failed: HydrateBlobStoreFromSeedFailure[] = [];

  for (const relativePath of relativePaths) {
    const outcome = await resolveOneSeedBlob(seedUploadsDir, blobStore, relativePath);
    if (outcome.kind === "copied") copied++;
    else if (outcome.kind === "skipped") skipped++;
    else failed.push(outcome.failure);
  }

  return { status: computeHydrateStatus(copied, failed.length), copied, skipped, failed };
}

import { CredentialInputError, CREDENTIAL_MESSAGES, assertCredentialFreeField, normalizeCredentialToken, type CredentialTokenHint } from '../../contracts/core/credential-token.js';
import { nowIso as clockNowIso } from "@jini-ai/core/primitives";
import { MEDIA_PROVIDERS } from "@jini-ai/integrations/media-providers/catalog";
import type { Clock as ClockPort, ISODateTime, UUID } from "@jini-ai/core/primitives";

import type { KeyringPort, SealedSecret, SecretSealerPort } from "../webhooks/index.js";
import { type VaultRepoPort } from "@jini-ai/platform/secrets/credential-sets";
import { createTovuStoreVault } from "#src/platform/secrets/vault-kinds";
import { mediaProviderVault, mediaVaultId, mediaVaultRecord, mediaVaultScope } from "./provider-credential-vault.js";

type VaultPutRecord = Parameters<VaultRepoPort["put"]>[0]["record"];

/**
 * @file Per-workspace media-generation vendor credentials — what the admin's Media → "Media
 * providers" tab reads and writes. Backs the `MediaProvidersPort` contract in `@jini-ai/ui`
 * (`features/media-providers/ports.ts`), whose two methods this file's two functions answer.
 *
 * WORKSPACE-scoped, not per-principal like `assistant/execution-credential-store.ts`: generation
 * spends real money and publishes assets site-wide, so the install holds one vendor roster. See
 * `db/schema.sqlite.ts`'s `mediaProviderCredentials` header for the full reasoning.
 *
 * Two functions, matching the port exactly:
 * - {@link getMediaProviderCredentials} — read model only. Never decrypts (`keyTail` is a plain
 *   column computed at write time), so it cannot fail on a misconfigured site key.
 * - {@link saveMediaProviderCredentials} — WHOLE-MAP REPLACE, including deletion. The tab's
 *   `saveMediaProviders` sends its entire local map and treats an absent provider as a tombstone
 *   (see `useMediaProvidersTab`'s `flushNow`), so a provider missing from the payload must be
 *   deleted here, not merely left alone.
 *
 * Neither function ever returns key material. The response carries only `apiKeyConfigured` and
 * `apiKeyTail`, which is the "markers" half of the two-kinds-of-present distinction
 * `@jini-ai/ui`'s `types.ts` documents.
 *
 * {@link resolveMediaProviderCredential} — added 2026-09-02 for `media-generation/tool-registrations.ts`'s
 * `media_generate_asset`, the first real decrypting reader this table has ever had. Mirrors
 * `custom-credentials/store.ts`'s own `resolveCustomCredentialByLabel` exactly.
 *
 * Jini binds the workspace and vault identity before opening sealed JSON. Legacy AAD handling
 * lives exclusively in boot normalization/recovery; feature reads never try a legacy fallback.
 */

/** One provider's stored credential row. `sealed`/`keyTail` are both-null or both-set, enforced by
 *  the table's own CHECK — a row may legitimately hold only `baseUrl`/`model` with no key yet. */
export interface MediaProviderCredentialRecord {
  /** Private adapter context; non-enumerable and never part of the view. */
  readonly vaultRecord?: VaultPutRecord;
  workspaceId: UUID;
  providerId: string;
  baseUrl: string | null;
  model: string | null;
  sealed: SealedSecret | null;
  /** Safe last four characters, withheld for short/unknown-length tokens. */
  keyTail: string | null;
  /** Compatibility marker: 1 for a vault envelope, 0 for no envelope. Legacy versions are
   * normalized at boot; the Jini service alone determines AAD for all normal reads. */
  aadVersion: number;
  createdAt: ISODateTime;
  updatedAt: ISODateTime;
}

/** Every write one whole-map replace performs, derived from the rows the replace itself just read. */
export interface MediaProviderCredentialReplacePlan {
  /** Rows to write, in submission order. Already merged against the rows the planner was handed. */
  upserts: readonly MediaProviderCredentialRecord[];
  /** Ids to delete — providers the payload omitted. May be empty. */
  tombstoneProviderIds: readonly string[];
}

/**
 * Turns the workspace's CURRENT rows into the writes that replace them.
 *
 * MUST be synchronous and free of I/O. That is the whole point: `replaceWorkspace` invokes this
 * between its own read and its own writes, inside an open transaction, so a planner that awaited
 * anything would hand the event loop back mid-transaction — which is precisely the defect this
 * signature exists to make unrepresentable (see {@link MediaProviderCredentialRepoPort.replaceWorkspace}).
 * The return type is not a promise, so an `async` planner cannot type-check.
 */
export type MediaProviderCredentialReplacePlanner = (
  existing: readonly MediaProviderCredentialRecord[]
) => MediaProviderCredentialReplacePlan;

/** Workspace-scoped persistence for {@link MediaProviderCredentialRecord} (ADR-007 §1). Multi-row
 *  per workspace, unlike the two single-row credential stores, so the port needs a list read and a
 *  bulk delete rather than a single find and a `clearKey`. */
export interface MediaProviderCredentialRepoPort {
  readonly vault?: VaultRepoPort;
  listByWorkspaceId(workspaceId: UUID): Promise<MediaProviderCredentialRecord[]>;
  upsert(record: MediaProviderCredentialRecord): Promise<void>;
  /** Idempotent: ids with no row are skipped, not an error. A no-op on an empty list. */
  deleteByProviderIds(input: { workspaceId: UUID; providerIds: readonly string[] }): Promise<void>;
  /**
   * READ-PLAN-WRITE for the whole workspace, as one atomic unit: reads the workspace's current
   * rows, calls `plan` with them, then applies that plan's upserts and tombstone deletes. Commits
   * iff every step succeeds; rolls back and rethrows if `plan` throws or any write fails.
   *
   * The read lives INSIDE the boundary on purpose. `saveMediaProviderCredentials` merges each
   * submitted entry against the stored row (an entry with no `apiKey` keeps the stored key, and
   * `createdAt` is preserved), so a read taken before the boundary opens can be stale by the time
   * the merge is written: a concurrent rotation landing in that window would be silently reverted
   * by a metadata-only save that re-wrote the key it had read a moment earlier.
   *
   * `plan` is synchronous by type, which is the second half of the fix — see
   * {@link MediaProviderCredentialReplacePlanner}. Everything that must await (sealing a new key)
   * happens before this method is called.
   *
   * Not reentrant — callers invoke this exactly once, at the outermost level of their own body.
   *
   * @returns the rows written, with authoritative hints and private vault context.
   */
  replaceWorkspace(input: {
    workspaceId: UUID;
    plan: MediaProviderCredentialReplacePlanner;
  }): Promise<readonly MediaProviderCredentialRecord[]>;
}

/**
 * One provider as the admin screen sees it — the marker half only, never the key.
 *
 * Field names are `@jini-ai/ui`'s `MediaProviderCredentials`, not Tovu's own, because this shape
 * crosses the wire straight into that component. Structurally duplicated rather than imported:
 * `@jini-ai/ui` is a browser/React package and this is server code, so the wire contract is
 * restated here and pinned by `__tests__/provider-credential-store.test.ts`.
 */
export interface MediaProviderCredentialView {
  baseUrl?: string;
  model?: string;
  /** `true` iff a sealed key is stored. Absent rather than `false` when none is. */
  apiKeyConfigured?: boolean;
  apiKeyHint?: CredentialTokenHint | null;
  /** Bare tail, no `••••` prefix — `@jini-ai/ui`'s `maskedKeyLabel` adds and clamps that itself. */
  apiKeyTail?: string;
}

/** Credentials keyed by engine-canonical provider id. */
export type MediaProviderCredentialMap = Record<string, MediaProviderCredentialView>;

/** Longest accepted `baseUrl`/`model`. Not a vendor limit — a bound on what an admin payload may
 *  write into a text column, so a malformed client cannot store unbounded blobs. */
const MAX_FIELD_LENGTH = 2048;

/** Engine-canonical ids, the only accepted keys. Frozen at module load from the catalogue the
 *  dispatch engine itself looks credentials up by, which is what stops the UI-vs-engine id
 *  divergence (`xai-grok-imagine` vs `grok`) from ever reaching storage. */
const KNOWN_PROVIDER_IDS: ReadonlySet<string> = new Set(MEDIA_PROVIDERS.map((provider) => provider.id));

export class MediaProviderCredentialValidationError extends Error {}

/** Thrown when a caller supplies a new key but the site key (`TOVU_SITE_KEY`) is
 *  unavailable — fail-closed, mirroring the two sibling credential stores so the route can map it
 *  to its own `503 SECRET_STORE_UNCONFIGURED` rather than a generic `400`. */
export class MediaProviderCredentialSecretStoreUnconfiguredError extends Error {}

/** The key half of a view: only stored safe hints, so reading never opens an envelope. Short or
 *  unknown-length tokens withhold their suffix. */
function keyMarkers(record: MediaProviderCredentialRecord): MediaProviderCredentialView {
  if (record.sealed === null) return {};
  const row = record.vaultRecord;
  if (row?.tokenLength === null || row?.tokenLength === undefined) return { apiKeyConfigured: true };
  const last4 = row.tokenLength >= 12 ? row.last4 : null;
  return { apiKeyConfigured: true, apiKeyHint: { length: row.tokenLength, last4 }, ...(last4 === null ? {} : { apiKeyTail: last4 }) };
}

/** Stored safe hints keep metadata readable without opening any envelopes, even with no site key. */
function toView(record: MediaProviderCredentialRecord): MediaProviderCredentialView {
  return { ...(record.baseUrl === null ? {} : { baseUrl: record.baseUrl }),
    ...(record.model === null ? {} : { model: record.model }), ...keyMarkers(record) };
}

function toMap(records: readonly MediaProviderCredentialRecord[]): MediaProviderCredentialMap {
  return Object.fromEntries(records.map(record => [record.providerId, toView(record)]));
}

export interface MediaProviderCredentialReadDeps {
  repo: MediaProviderCredentialRepoPort;
  sealer?: SecretSealerPort;
}

/**
 * Every configured provider for a workspace, as markers only. Pure DB read — never decrypts, so a
 * missing or rotated site key cannot make this fail.
 *
 * @complexity O(n) over the workspace's provider rows, itself bounded by the catalogue size.
 */
export async function getMediaProviderCredentials(
  deps: MediaProviderCredentialReadDeps,
  input: { workspaceId: UUID }
): Promise<MediaProviderCredentialMap> {
  return toMap(await deps.repo.listByWorkspaceId(input.workspaceId));
}

/** One provider's incoming edit. `apiKey` present and non-blank sets a new key; absent or blank
 *  leaves the stored one alone (`@jini-ai/ui`'s `filled()` treats blank as absent, and the tab
 *  clears a key by omitting the whole provider rather than by sending an empty one). */
export interface MediaProviderCredentialInput {
  apiKey?: string;
  baseUrl?: string;
  model?: string;
  /** Accepted and ignored — the tab echoes back markers it was given. Listed so a payload carrying
   *  them is not rejected as having unknown fields. */
  apiKeyConfigured?: boolean;
  apiKeyHint?: CredentialTokenHint | null;
  apiKeyTail?: string;
  source?: string;
}

export interface SaveMediaProviderCredentialsInput {
  workspaceId: UUID;
  providers: Record<string, MediaProviderCredentialInput>;
}

export interface MediaProviderCredentialWriteDeps extends MediaProviderCredentialReadDeps {
  sealer: SecretSealerPort;
  keyring: KeyringPort;
  clock: ClockPort;
  /** The live media provider registry (built-in + plugin vendors, 2026-10-21). A plugin vendor's id is
   *  accepted only when the registry holds that exact public id; omitted, only built-in ids are. */
  providerCatalog?: MediaProviderIdCatalog;
}

/** Structurally `MediaProviderRegistry['findProvider']` — only the id is read. */
export interface MediaProviderIdCatalog {
  findProvider(required: { id: string }): { readonly id: string } | null;
}

/** Writes use only `replaceWorkspace`; new envelopes are prepared through the vault port. */
export type MediaProviderCredentialSaveDeps = Omit<MediaProviderCredentialWriteDeps, "repo"> & {
  repo: Pick<MediaProviderCredentialRepoPort, "replaceWorkspace" | "vault">;
};

function trimmedOrNull(value: string | undefined): string | null {
  const trimmed = value?.trim();
  return trimmed ? trimmed : null;
}

/** Only a credential-policy refusal is an operator mistake; anything else surfaces unchanged. */
function rethrowAsValidation<T>({ run }: { run: () => T }, _options = {}): T {
  try { return run(); }
  catch (err) { if (err instanceof CredentialInputError) throw new MediaProviderCredentialValidationError(err.message); throw err; }
}

/** An exact (never alias-resolved) non-built-in id the injected registry holds. @complexity O(m). */
function isPluginProviderId(providerId: string, catalog: MediaProviderIdCatalog | undefined): boolean {
  return !KNOWN_PROVIDER_IDS.has(providerId) && catalog?.findProvider({ id: providerId })?.id === providerId;
}

/** Built-in ids, or a plugin vendor id the injected registry holds. @complexity O(m). */
function isKnownProviderId(providerId: string, catalog: MediaProviderIdCatalog | undefined): boolean {
  return KNOWN_PROVIDER_IDS.has(providerId) || isPluginProviderId(providerId, catalog);
}

function assertKnownProviderId({ providerId }: { providerId: string }, { catalog }: { catalog?: MediaProviderIdCatalog } = {}): void {
  rethrowAsValidation({ run: () => assertCredentialFreeField({ value: providerId, field: 'providerId' }) });
  if (!isKnownProviderId(providerId, catalog)) {
    throw new MediaProviderCredentialValidationError(
      `unknown media provider "${providerId}" — expected an engine-canonical id from @jini-ai/integrations/media-providers`
    );
  }
}

/** `apiKey` is only type-checked here: token normalization owns its own policy and limit. */
function assertEntryField({ providerId, field, value }: { providerId: string; field: "apiKey" | "baseUrl" | "model"; value: unknown }, _options = {}): void {
  if (value === undefined) return;
  if (typeof value !== "string") {
    throw new MediaProviderCredentialValidationError(`${field} for "${providerId}" must be a string`);
  }
  if (field === "apiKey") return;
  rethrowAsValidation({ run: () => assertCredentialFreeField({ value, field }) });
  if (value.length > MAX_FIELD_LENGTH) {
    throw new MediaProviderCredentialValidationError(
      `${field} for "${providerId}" exceeds ${MAX_FIELD_LENGTH} characters`
    );
  }
}

/** Rejects anything the row cannot faithfully hold, before a single write happens. */
function assertValidEntry(providerId: string, entry: MediaProviderCredentialInput, catalog: MediaProviderIdCatalog | undefined): void {
  assertKnownProviderId({ providerId }, { catalog });
  if (entry === null || typeof entry !== "object" || Array.isArray(entry)) {
    throw new MediaProviderCredentialValidationError(`provider "${providerId}" must be an object`);
  }
  for (const field of ["apiKey", "baseUrl", "model"] as const) assertEntryField({ providerId, field, value: entry[field] });
}

/** Prepare only supplied keys before the replacement transaction. The later planner re-reads
 * CURRENT rows for all preserved keys, so a rotation during this await cannot be resurrected.
 * @complexity Catalogue-bounded reads/seals; no writes or per-row opens.
 */
async function sealNewProviderKeys(
  deps: MediaProviderCredentialSaveDeps,
  input: SaveMediaProviderCredentialsInput,
): Promise<Map<string, VaultPutRecord>> {
  const fresh = new Map<string, VaultPutRecord>();
  const vault = createTovuStoreVault({ ...deps, kind: "media-provider",
    storageError: () => new MediaProviderCredentialSecretStoreUnconfiguredError(CREDENTIAL_MESSAGES.storage) });
  for (const [providerId, entry] of Object.entries(input.providers)) {
    const submitted = entry.apiKey;
    if (submitted === undefined || submitted === "") continue;
    const apiKey = rethrowAsValidation({ run: () => normalizeCredentialToken({ value: submitted, field: "apiKey" }) });
    const scope = mediaVaultScope({ workspaceId: input.workspaceId, providerId });
    const existing = (await deps.repo.vault!.list(scope))[0];
    fresh.set(providerId, await vault.prepare({ ...scope,
      id: existing?.id ?? mediaVaultId({ providerId }), expectedRevision: existing?.revision ?? null,
      provider: providerId, label: providerId, meta: { ...existing?.meta, baseUrl: trimmedOrNull(entry.baseUrl), model: trimmedOrNull(entry.model) },
      payload: { apiKey }, hintToken: apiKey }));
  }
  return fresh;
}

/** Pure merge against the transaction's snapshot; hints and envelope travel as one private unit. */
function buildProviderUpsertRow(input: {
  workspaceId: UUID; providerId: string; entry: MediaProviderCredentialInput;
  existing?: MediaProviderCredentialRecord; fresh?: VaultPutRecord; now: ISODateTime;
}, _options = {}): MediaProviderCredentialRecord {
  const { workspaceId, providerId, entry, existing, fresh, now } = input;
  const credential = fresh ? mediaVaultRecord({ row: fresh }) : existing;
  // Only a new provider must bring a key. A stored keyless row (migrated or recovered, metadata
  // only) is re-sent by every whole-map save, so refusing it would block every other provider's edit.
  if (!credential) throw new MediaProviderCredentialValidationError('Enter a token. Spaces alone are not a token.');
  const row: MediaProviderCredentialRecord = { workspaceId, providerId,
    baseUrl: trimmedOrNull(entry.baseUrl), model: trimmedOrNull(entry.model),
    sealed: credential.sealed, keyTail: credential.keyTail, aadVersion: credential.aadVersion,
    createdAt: existing?.createdAt ?? now, updatedAt: now };
  Object.defineProperty(row, "vaultRecord", { value: credential.vaultRecord });
  return row;
}

/**
 * Replaces the workspace's ENTIRE provider set and resolves the authoritative copy afterward.
 *
 * Whole-map semantics over the BUILT-IN vendors, because that is what the port promises: a built-in
 * provider absent from `providers` is DELETED, not left in place; any other stored row (a plugin
 * vendor's, registered or not) is kept. A present entry with a blank/absent `apiKey` keeps whatever key is
 * already stored, so an operator editing only `baseUrl` never has to re-paste a key they cannot
 * see.
 *
 * Ordering is deliberate and load-bearing: every entry is validated, then every new key is sealed,
 * and only then is anything written. Sealing is the one step that can fail for an environmental
 * reason (a missing `TOVU_SITE_KEY`), so doing it up front means that failure cannot
 * leave the workspace half-rewritten — the alternative, sealing inside the write loop, would delete
 * some providers and abort before writing the rest.
 *
 * Sealing up front is also what lets the merge itself be synchronous: this function hands
 * `replaceWorkspace` a plain function of the workspace's CURRENT rows, and the repo runs that read,
 * that merge, and every resulting write inside one transaction under the writer lock.
 * Reading preserved keys out here instead — the shape this function used to have — reintroduces a
 * window in which a concurrent rotation lands between the read and the write and is then reverted by
 * this call's own merge, because a metadata-only entry re-writes the sealed key it read.
 *
 * @throws {MediaProviderCredentialValidationError} `providers` is not an object, names an unknown
 *   provider id, or carries a non-string/oversized `apiKey`/`baseUrl`/`model`.
 * @throws {MediaProviderCredentialSecretStoreUnconfiguredError} a new key was supplied but the
 *   site key is unavailable — never downgraded to a plaintext write or a silent skip.
 * @complexity O(n) over the submitted providers, plus one keyring derivation per NEW key. `n` is
 *   bounded by the catalogue: unknown ids are rejected, so the payload cannot exceed its size.
 */
export async function saveMediaProviderCredentials(
  deps: MediaProviderCredentialSaveDeps,
  input: SaveMediaProviderCredentialsInput
): Promise<MediaProviderCredentialMap> {
  const { providers } = input;
  if (providers === null || typeof providers !== "object" || Array.isArray(providers)) {
    throw new MediaProviderCredentialValidationError("providers must be an object keyed by provider id");
  }

  const entries = Object.entries(providers);
  for (const [providerId, entry] of entries) assertValidEntry(providerId, entry, deps.providerCatalog);

  const now = clockNowIso({ clock: deps.clock });

  // Seal every new key BEFORE any write — see this function's doc for why the order matters, and
  // why this is the ONLY async step left before the transaction opens.
  const sealedByProviderId = await sealNewProviderKeys(deps, input);

  const submittedIds = new Set(entries.map(([providerId]) => providerId));

  /** Merges the submitted payload against whatever rows the transaction just read. Synchronous and
   *  pure by contract — it runs inside the open transaction. */
  const plan: MediaProviderCredentialReplacePlanner = (existingRows) => {
    const existingByProviderId = new Map(existingRows.map((row) => [row.providerId, row]));
    const upserts = entries.map(([providerId, entry]) =>
      buildProviderUpsertRow({ workspaceId: input.workspaceId, providerId, entry,
        existing: existingByProviderId.get(providerId), fresh: sealedByProviderId.get(providerId), now })
    );
    return {
      upserts,
      // A plugin vendor's row is never tombstoned by omission: the admin tab renders only built-in
      // vendors, so its whole-map save would otherwise silently delete a key saved for a plugin vendor.
      // Keyed on "not built-in", not "registry holds it": a disabled plugin, a restart or a loader
      // fault drops the vendor from the registry, and its stored key must survive that too.
      tombstoneProviderIds: existingRows
        .map((row) => row.providerId)
        .filter((providerId) => !submittedIds.has(providerId) && KNOWN_PROVIDER_IDS.has(providerId)),
    };
  };

  return toMap(await deps.repo.replaceWorkspace({ workspaceId: input.workspaceId, plan }));
}

export interface MediaProviderCredentialResolveDeps {
  repo: MediaProviderCredentialRepoPort;
  sealer: SecretSealerPort;
}

/** One provider's decrypted, USABLE credential — never logged, never returned from a tool result;
 *  see {@link resolveMediaProviderCredential}'s own doc for the one caller this exists for. */
export interface ResolvedMediaProviderCredential {
  apiKey: string;
  baseUrl: string | null;
  model: string | null;
}

/**
 * The ONLY decrypting read this table has. Finds the workspace's saved credential for `providerId`
 * (an engine-canonical id from `@jini-ai/integrations/media-providers` — same catalogue
 * {@link KNOWN_PROVIDER_IDS} is frozen from) and decrypts it.
 *
 * Returns `null`, never throws, for either "not configured at all" (no row) or "configured with no
 * key yet" (`sealed === null` — `MediaProviderCredentialRecord`'s own doc: "a row may legitimately
 * hold only `baseUrl`/`model` with no key yet"). Both are the same ordinary, expected state for an
 * optional integration a caller should handle with a clear "nothing saved yet" message, not treat as
 * exceptional — matching `resolveCustomCredentialByLabel`'s identical "not found is not an error"
 * contract for the sibling table.
 *
 * @throws {MediaProviderCredentialSecretStoreUnconfiguredError} A row with a sealed key exists but
 *   `sealer.open()` failed — the site key is missing/rotated, or the stored row is corrupted.
 * @complexity One indexed provider-group read, at most one selected envelope open.
 */
export async function resolveMediaProviderCredential(
  deps: MediaProviderCredentialResolveDeps,
  input: { workspaceId: UUID; providerId: string }
): Promise<ResolvedMediaProviderCredential | null> {
  const vault = createTovuStoreVault({ ...deps, repo: { vault: mediaProviderVault({ vault: deps.repo.vault!, providerId: input.providerId }) }, kind: "media-provider",
    storageError: () => new MediaProviderCredentialSecretStoreUnconfiguredError(CREDENTIAL_MESSAGES.storage) });
  const resolved = await vault.findOne(mediaVaultScope(input));
  if (!resolved?.payload) return null;
  if (typeof resolved.payload.apiKey !== "string") throw new MediaProviderCredentialSecretStoreUnconfiguredError(CREDENTIAL_MESSAGES.storage);
  return { apiKey: resolved.payload.apiKey, baseUrl: resolved.summary.meta.baseUrl as string | null,
    model: resolved.summary.meta.model as string | null };
}

import { VaultError, type VaultBatchOp, type VaultRecord, type VaultRepoPort } from "@jini-ai/platform/secrets/credential-sets";
import { parseTovuStoreMeta } from "#src/platform/secrets/vault-kinds";
import type { MediaProviderCredentialRecord, MediaProviderCredentialRepoPort, MediaProviderCredentialReplacePlanner } from "./provider-credential-store.js";

type VaultPutRecord = Parameters<VaultRepoPort["put"]>[0]["record"];

/** Expected nonpersonal ownership, plus an exact provider filter when selecting a singleton. */
export function mediaVaultScope({ workspaceId, providerId }: { workspaceId: string; providerId?: string }, _options = {}) {
  return { workspaceId, kind: "media-provider" as const, ownerKey: "tovu", principalId: null, binding: null,
    ...(providerId === undefined ? {} : { provider: providerId }) };
}

/** Media's singleton is per provider, regardless of default flags (migrated rows may have none).
 * Adapt Jini's indexed exact-group read to its singleton service lifecycle: one read, one open.
 */
export function mediaProviderVault({ vault, providerId }: { vault: VaultRepoPort; providerId: string }, _options = {}): VaultRepoPort {
  return { find: input => vault.find(input), list: input => vault.list(input), put: input => vault.put(input),
    patchMeta: input => vault.patchMeta(input), delete: input => vault.delete(input),
    findOne: async input => {
      const row = (await vault.list({ ...input, ownerKey: "tovu", principalId: null, provider: providerId }))[0];
      if (row && row.provider !== providerId) throw new VaultError({ code: "context" });
      return row ?? null;
    } };
}

/** Deterministic id for a provider's first row; later writes keep whatever id is stored. */
export function mediaVaultId({ providerId }: { providerId: string }, _options = {}): string {
  return `vault:${JSON.stringify(["media-provider", providerId])}`;
}

/** Expected ownership is this adapter's, never the row's: anything else is a context breach. */
function ownedProviderId({ row }: { row: VaultPutRecord }, _options = {}): string {
  if (row.kind !== "media-provider" || row.ownerKey !== "tovu" || row.principalId !== null || row.binding !== null || row.provider === null) {
    throw new VaultError({ code: "context" });
  }
  return row.provider;
}

/** Short/unknown-length tokens withhold their suffix; an unsealed row has no tail at all. */
function keyTailOf({ row }: { row: VaultPutRecord }, _options = {}): string | null {
  if (!row.sealed) return null;
  return row.tokenLength !== null && row.tokenLength >= 12 ? row.last4 ?? "" : "";
}

/** Historical DTO; vault identity/revision/hints remain private to the adapter, never API fields. */
export function mediaVaultRecord({ row }: { row: VaultPutRecord }, _options = {}): MediaProviderCredentialRecord {
  const providerId = ownedProviderId({ row });
  const meta = parseTovuStoreMeta({ kind: "media-provider", meta: row.meta });
  const record: MediaProviderCredentialRecord = { workspaceId: row.workspaceId, providerId,
    baseUrl: meta.baseUrl as string | null, model: meta.model as string | null, sealed: row.sealed,
    keyTail: keyTailOf({ row }), aadVersion: row.sealed ? 1 : 0, createdAt: row.createdAt, updatedAt: row.updatedAt };
  Object.defineProperty(record, "vaultRecord", { value: row });
  return record;
}

/** A prepared row must target the stored row's id; its hints win over the stored row's. */
function rowIdentity({ record, existing }: { record: MediaProviderCredentialRecord; existing?: VaultRecord }, _options = {}) {
  const prepared = record.vaultRecord;
  const id = existing?.id ?? prepared?.id ?? mediaVaultId(record);
  if (prepared && prepared.id !== id) throw new VaultError({ code: "conflict" });
  return { id, hint: prepared ?? existing };
}

/** Safe hints describe one envelope: they survive only while every envelope field is unchanged. */
function preservedHints({ hint, sealed }: { hint?: VaultPutRecord; sealed: VaultPutRecord["sealed"] }, _options = {}) {
  const stored = hint?.sealed;
  const unchanged = stored != null && sealed !== null && stored.keyId === sealed.keyId &&
    stored.ciphertext === sealed.ciphertext && stored.nonce === sealed.nonce && stored.alg === sealed.alg;
  return unchanged ? { last4: hint!.last4, tokenLength: hint!.tokenLength } : { last4: null, tokenLength: null };
}

/** CAS bookkeeping a replacement inherits from the stored row, or a first row's defaults. */
function carriedFromExisting({ record, existing }: { record: MediaProviderCredentialRecord; existing?: VaultRecord }, _options = {}) {
  return { isDefault: existing?.isDefault ?? false, revision: (existing?.revision ?? 0) + 1,
    createdAt: existing?.createdAt ?? record.createdAt, updatedAt: record.updatedAt };
}

/** DTO persistence delegates CAS/batch atomicity to Jini. No plaintext enters this adapter. */
export class MediaProviderCredentialVaultRepo implements MediaProviderCredentialRepoPort {
  readonly vault: VaultRepoPort;
  constructor({ vault }: { vault: VaultRepoPort }, _options = {}) { this.vault = vault; }
  async listByWorkspaceId(workspaceId: string): Promise<MediaProviderCredentialRecord[]> {
    return (await this.vault.list(mediaVaultScope({ workspaceId }))).map(row => mediaVaultRecord({ row }));
  }
  private row({ record, existing }: { record: MediaProviderCredentialRecord; existing?: VaultRecord }, _options = {}): VaultRecord {
    const { id, hint } = rowIdentity({ record, existing });
    return { ...mediaVaultScope(record), id, provider: record.providerId, label: record.providerId,
      meta: parseTovuStoreMeta({ kind: "media-provider", meta: { ...existing?.meta, baseUrl: record.baseUrl, model: record.model } }),
      sealed: record.sealed, ...preservedHints({ hint, sealed: record.sealed }), ...carriedFromExisting({ record, existing }) };
  }
  async upsert(record: MediaProviderCredentialRecord): Promise<void> {
    const existing = (await this.vault.list(mediaVaultScope(record)))[0];
    await this.vault.put({ record: this.row({ record, existing }), expectedRevision: existing?.revision ?? null });
  }
  async deleteByProviderIds(input: { workspaceId: string; providerIds: readonly string[] }): Promise<void> {
    if (!input.providerIds.length) return;
    await this.replaceWorkspace({ workspaceId: input.workspaceId, plan: () => ({ upserts: [], tombstoneProviderIds: input.providerIds }) });
  }
  /** The fresh snapshot alone supplies preserved envelopes/revisions. Sealing happens earlier;
   * CAS rejects a writer racing this snapshot and Jini publishes the complete batch once.
   * @complexity O(n) planning/space for catalogue-bounded providers, one read and one batch.
   */
  async replaceWorkspace(input: { workspaceId: string; plan: MediaProviderCredentialReplacePlanner }): Promise<readonly MediaProviderCredentialRecord[]> {
    if (!this.vault.applyBatch) throw new VaultError({ code: "invalid-record" });
    const current = await this.vault.list(mediaVaultScope(input));
    const byProvider = new Map(current.map(row => [row.provider!, row]));
    const plan = input.plan(current.map(row => mediaVaultRecord({ row })));
    const ops: VaultBatchOp[] = plan.upserts.map(record => {
      if (record.workspaceId !== input.workspaceId) throw new VaultError({ code: "context" });
      const existing = byProvider.get(record.providerId);
      return { put: { record: this.row({ record, existing }), expectedRevision: existing?.revision ?? null } };
    });
    for (const providerId of new Set(plan.tombstoneProviderIds)) {
      const row = byProvider.get(providerId);
      if (row) ops.push({ delete: { workspaceId: input.workspaceId, id: row.id, expectedRevision: row.revision } });
    }
    return (await this.vault.applyBatch({ ops })).filter((row): row is VaultRecord => typeof row !== "boolean").map(row => mediaVaultRecord({ row }));
  }
}

