import { membersAgentToolCatalog } from "./agent-tools.js";
import type {
  MagicLinkTokenRepoPort,
  MemberRepoPort,
  MemberSessionRepoPort,
  MemberSubscriptionRepoPort,
  MemberTierRepoPort,
  MembersWriteServiceDeps,
} from "./ports.js";
import { MemberSignInUnavailableError, MemberConflictError, MemberNotFoundError, MemberValidationError, type MemberRecord } from "./types.js";
import { createMember, disableMember, requestSignInLink, updateProfile } from "./write-service.js";

const CATALOG_BY_ID = indexCatalogById({ catalog: membersAgentToolCatalog });

/**
 * The rate-limiter shape `members_request_magic_link` actually calls (`await limiter.check({ key })`), declared
 * structurally instead of importing `core/rate-limit/rate-limit`'s nominal `RateLimiter` type.
 *
 * This is the one field in this file that would otherwise cost Members its whole architectural win:
 * unlike every other domain wired here, Members has no OTHER file that reaches into `server/*`
 * today, so importing `RateLimiter` from there — even though that specific type carries no Express
 * coupling itself — would single-handedly reintroduce the `members <-> server` module cycle this
 * narrowing exists to remove. `createRateLimiter()`'s real return value already has exactly this
 * shape, so it satisfies this structurally with no adapter needed.
 */
export interface MagicLinkRateLimiter {
  check(required: { key: string }): Promise<{ allowed: true } | { allowed: false; retryAfterSeconds: number }>;
}

/**
 * The exact slice of the route-deps bag Members' tool handlers read. Declared structurally (rather
 * than importing `server/routes/types`'s `RouteDeps`, or `server/routes/admin/members/deps.ts`'s
 * `MembersRouteDeps`, which itself extends `RouteDeps`) so this module carries no back-edge into the
 * composition root. `server/routes/*` satisfies this structurally by passing its existing
 * `MembersRouteDeps` object; nothing there changes.
 */
export interface MembersToolDeps {
  tracker?: Tracker;
  removeMember?: import("@jini-ai/cms/trash").RemoveEntity;
  authorize: AuthorizeFn;
  workspaceId: string;
  clock: Clock;
  idGen: { newId(): string };
  memberRepo: MemberRepoPort;
  memberTierRepo: MemberTierRepoPort;
  memberSubscriptionRepo: MemberSubscriptionRepoPort;
  memberSessionRepo: MemberSessionRepoPort;
  magicLinkRepo: MagicLinkTokenRepoPort;
  mailer: MembersWriteServiceDeps["mailer"];
  originRegistry?: MembersWriteServiceDeps["origin"];
  mailStatus?: MembersWriteServiceDeps["mailStatus"];
  /** See `MembersWriteServiceDeps.principals` — sign-up writes the member's `kind: "member"` principal here. */
  principalRepo: MembersWriteServiceDeps["principals"];
  /** Resolves configuration independently of sending; production supplies this so disabled
   * members (which skip sends) cannot be distinguished during a lazy driver swap. */
  settleMailer?: () => Promise<void>;
  /** The site's system-email From resolver — see `MembersWriteServiceDeps.senderIdentity`. */
  mailSenderIdentity?: MembersWriteServiceDeps["senderIdentity"];
  magicLinkPerEmailLimiter: MagicLinkRateLimiter;
}

/**
 * Assembles `write-service.ts`'s `MembersWriteServiceDeps` bundle from {@link MembersToolDeps} —
 * a local duplicate of `server/routes/admin/members/deps.ts`'s `toMembersWriteServiceDeps` rather
 * than an import of it, for the identical reason `features/settings/tool-registrations.ts`'s header
 * gives for duplicating `toWriteServiceDeps`: importing from the HTTP admin layer would invert this
 * codebase's ports/adapters direction. It is a field mapping, not logic, so the two copies carry no
 * behavioral drift risk.
 */
function toMembersWriteServiceDeps(deps: MembersToolDeps): MembersWriteServiceDeps {
  return {
    clock: deps.clock,
    ids: deps.idGen,
    members: deps.memberRepo,
    tiers: deps.memberTierRepo,
    subscriptions: deps.memberSubscriptionRepo,
    sessions: deps.memberSessionRepo,
    magicLinks: deps.magicLinkRepo,
    mailer: deps.mailer,
    mailStatus: deps.mailStatus,
    origin: deps.originRegistry,
    principals: deps.principalRepo,
    senderIdentity: deps.mailSenderIdentity,
  };
}

/**
 * This wiring layer's OWN risk classification, authored from what each handler below actually
 * calls. See `DerivedRiskByToolId` in the kit for why it is independent of the catalog's own
 * `sideEffects` declaration.
 */
export const membersDerivedRisk: DerivedRiskByToolId = new Map<string, AgentToolSideEffect>([
  // -> memberRepo.list: read only.
  ["members_list", "none"],
  // -> memberRepo.findById: read only.
  ["members_get_by_id", "none"],
  // Existing member creation and profile chokepoints, without auth tokens or entitlements.
  ["members_create", "mutates-durable-state"],
  ["members_update_profile", "mutates-durable-state"],
  // -> disableMember (write-service.ts): status flip + revokes every live session.
  ["members_disable", "mutates-durable-state"],
  ["members_delete", "mutates-durable-state"],
  // -> requestSignInLink (write-service.ts): saves a new-address challenge without creating a member, saves a magic-link
  //    token row, and sends mail; settleMailer refreshes configuration without sending.
  ["members_request_magic_link", "mutates-durable-state"],
]);

/**
 * Projects a `MemberRecord` into the model-facing shape used by every Members tool — mirrors
 * `http/admin/members.ts`'s own `toAdminMemberResponse` field set (so a tool sees exactly what the
 * admin UI already shows a human) MINUS `workspaceId` (the agent is already scoped to one
 * workspace it cannot change, the same reasoning content-types'/Forms' `to*View` apply) and MINUS
 * `note`/`fields` (the admin response itself already withholds the operator-only note and the raw
 * extension bag — this view does not re-expose what the human-facing response hides).
 *
 * @complexity O(1).
 * @overallScore 100
 */
function toMemberToolView(member: MemberRecord) {
  const view: {
    id: string;
    email: string;
    status: MemberRecord["status"];
    name?: string;
    emailVerifiedAt?: string;
    createdAt: string;
    updatedAt: string;
    version: number;
  } = {
    id: member.id,
    email: member.email,
    status: member.status,
    createdAt: member.createdAt,
    updatedAt: member.updatedAt,
    version: member.version,
  };
  if (member.name) view.name = member.name;
  if (member.emailVerifiedAt) view.emailVerifiedAt = member.emailVerifiedAt;
  return view;
}

/**
 * The Members errors that reach the model with their real reason instead of a redacted
 * `INTERNAL_ERROR` — see `contracts/core/model-facing-tool-errors.ts` for the mechanism and for why
 * this list is an ALLOWLIST rather than a blanket unwrap.
 *
 * Every message here is built from the caller's OWN input (`member '<id>' was not found`,
 * `'<email>' is not a valid email address`) plus this domain's vocabulary. None carries a member's
 * stored record, another workspace's data, a token, or an internal path: `types.ts`'s typed errors
 * are all constructed at `write-service.ts` call sites that interpolate ids and the submitted email
 * only. `MemberAuthError` is deliberately ABSENT — it is thrown on the magic-link REDEMPTION path
 * (`consumeSignInLink`), which no tool here calls, and its messages ("sign-in link was already
 * used", "this account has been disabled") answer a question about a token holder rather than about
 * the caller's own request. If a redemption tool is ever wired, that class needs its own decision,
 * not this list's by default.
 */
const MEMBERS_MODEL_FACING_ERRORS: readonly ModelFacingErrorRule[] = [
  forbiddenRule({ domainPrefix: "MEMBERS", error: ForbiddenError }),
  { error: MemberNotFoundError, code: "MEMBERS_NOT_FOUND" },
  { error: MemberValidationError, code: "MEMBERS_VALIDATION_FAILED" },
  { error: MemberConflictError, code: "MEMBERS_CONFLICT" },
  { error: MemberSignInUnavailableError, code: "MEMBERS_SIGN_IN_UNAVAILABLE" },
];

/** `members_list`'s schema cap (`agent-tools.ts`), which is also the repo's own page size. */
const MEMBERS_LIST_MAX_LIMIT = 100;

export function buildMembersRegistrations(deps: MembersToolDeps): ToolRegistration[] {
  const handlers: Record<string, ToolHandler> = {
    /** Operator creation shares sign-up persistence while withholding tokens and mail. */
    members_create: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "member.manage" }, { entityType: "member" });
      const { member } = await createMember({ deps: { ...toMembersWriteServiceDeps(deps), onMemberCreated: ({ workspaceId, memberId, creationSource, initialState }) => {
        deps.tracker?.capture({ name: "member_registered", userId: ctx.principal.id }, { properties: {
          eventId: `member-registered:${workspaceId}:${memberId}`, creationSource, initialState,
        } });
      } }, input: { workspaceId: deps.workspaceId, email: requireString({ input, key: "email" }) } }, { name: optionalString({ input, key: "name" }) });
      return { member: toMemberToolView(member) };
    },
    /** Changes the public profile only; operator notes and extension fields stay private. */
    members_update_profile: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      const memberId = requireString({ input, key: "memberId" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "member.manage" }, { entityType: "member", entityId: memberId });
      const { member } = await updateProfile({ deps: toMembersWriteServiceDeps(deps), input: { workspaceId: deps.workspaceId, memberId, name: requireString({ input, key: "name" }) } });
      return { member: toMemberToolView(member) };
    },
    members_list: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });

      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "member.manage" }, { entityType: "member" });

      const afterId = optionalString({ input, key: "afterId" });
      const limit = readToolLimit({ input, max: MEMBERS_LIST_MAX_LIMIT, fallback: MEMBERS_LIST_MAX_LIMIT });
      // The repo treats an afterId it cannot find as "first page" (the admin list relies on that);
      // a model that passed one meant a real member, so a miss is its mistake to hear about.
      if (afterId !== undefined && !(await deps.memberRepo.findById({ workspaceId: deps.workspaceId, id: afterId }))) {
        throw new ToolInputError({ message: `unknown afterId '${afterId}'` });
      }
      const members = await deps.memberRepo.list({ workspaceId: deps.workspaceId, afterId, limit });
      return { members: members.map(toMemberToolView) };
    },

    members_get_by_id: async (ctx) => {
      const memberId = requireString({ input: requireInputRecord({ input: ctx.input }), key: "memberId" });

      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "member.manage" }, { entityType: "member", entityId: memberId });

      const member = await deps.memberRepo.findById({ workspaceId: deps.workspaceId, id: memberId });
      if (!member) throw new MemberNotFoundError(`member '${memberId}' was not found`);
      return { member: toMemberToolView(member) };
    },

    members_delete: async (ctx) => {
      const memberId = requireString({ input: requireInputRecord({ input: ctx.input }), key: "memberId" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "member.manage" }, { entityType: "member", entityId: memberId });
      return trashMember({ workspaceId: deps.workspaceId, memberId, actor: { principalId: ctx.principal.id } },
        { members: deps.memberRepo, remove: deps.removeMember, clock: { nowIso: () => nowIso({ clock: deps.clock }) } });
    },

    members_disable: async (ctx) => {
      const memberId = requireString({ input: requireInputRecord({ input: ctx.input }), key: "memberId" });

      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "member.manage" }, { entityType: "member", entityId: memberId });

      const { member } = await disableMember({ deps: toMembersWriteServiceDeps(deps), input: { workspaceId: deps.workspaceId, memberId } });
      return { member: toMemberToolView(member) };
    },

    members_request_magic_link: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      const email = requireString({ input: input, key: "email" });

      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "member.manage" }, { entityType: "member" });

      // INV-NEW-03: the shared per-email rate limit is consulted strictly AFTER authorize() —
      // mirrors `request-magic-link.ts`'s own ordering, so an unauthorized caller can never spend
      // rate-limit budget for a target email as a side channel.
      const emailKey = email.trim().toLowerCase();
      // Preserve model-facing validation instead of passing an empty key to the limiter.
      if (!emailKey) throw new MemberValidationError(`'${email}' is not a valid email address`);
      const rateLimitResult = await deps.magicLinkPerEmailLimiter.check({ key: emailKey });
      if (!rateLimitResult.allowed) {
        // A `ToolInputError`, not a bare `Error`: that marker is the ONLY thing `@jini-ai/daemon`'s
        // `ToolExecutor` reads to keep a rejection out of the `errorKind: 'internal'` bucket the
        // delegated-tool transport SEC-005-redacts, and "you are rate limited, retry after Ns" is
        // precisely the reason a model needs in order to back off instead of hammering the same
        // call. Thrown directly rather than routed through `MEMBERS_MODEL_FACING_ERRORS` because
        // this is THIS wiring layer's own check against an injected limiter, not a domain error
        // class `write-service.ts` raises — the same shape `features/forms/tool-registrations.ts`'s
        // `requireSubmissionsLimit` uses for its own ad-hoc check.
        throw new ToolInputError({ message: `MEMBERS_RATE_LIMITED: too many sign-in requests for '${email}' — retry after ${rateLimitResult.retryAfterSeconds}s` });
      }

      await deps.settleMailer?.();
      const result = await requestSignInLink({
        deps: toMembersWriteServiceDeps(deps),
        input: {
          workspaceId: deps.workspaceId,
          email,
          redirectPath: typeof input.redirectPath === "string" ? input.redirectPath : undefined,
        },
      });
      // requestSignInLink refuses (MEMBERS_SIGN_IN_UNAVAILABLE) when mail is off, so reaching
      // here means delivery is available; the privileged operator gets the actual send result.
      return { delivered: result.delivered, mailDeliveryAvailable: true };
    },
  };

  // No `unwiredToolIds`: Members wires its ENTIRE catalog, same tripwire discipline as Forms.
  return buildDomainRegistrations({ metadata: toolMetadata,
    domain: "members",
    catalogModule: "members/agent-tools.ts",
    catalog: CATALOG_BY_ID,
    // The whole map at once, so no handler can be the one that forgot — see
    // `withModelFacingErrors`' own doc for why a per-call-site reshape is the defect this avoids.
    handlers: withModelFacingErrors({ handlers: handlers, rules: MEMBERS_MODEL_FACING_ERRORS }),
    derivedRisk: membersDerivedRisk,
  });
}

/**
 * Contributes Members' AI tools to the assistant's catalog — called once by
 * `server/tool-catalog-manifest.ts`'s `installFirstPartyToolContributors()`, not by importing this
 * module. `assistant/tool-registrations.ts` no longer imports `buildMembersRegistrations`/
 * `membersDerivedRisk` by name; this is the seam that replaced it (2026-08-17, Stage 2 of the
 * rollout — no sibling domain still statically wired through `assistant` imports `members`, so this
 * one-directional `members -> assistant` call closes no new cycle).
 */
export function contributeMembersTools(): ToolContributor {
  return { domain: "members", build: buildMembersRegistrations, risk: membersDerivedRisk };
}

/**
 * @file Core domain types for the `members` Tier-2 core library (ADR-030).
 *
 * Purpose:
 * Type-only definitions for front-end membership: member accounts (a distinct
 * principal kind from admin operators — ADR-021), tiers/subscriptions, gated
 * content access, and member sign-in sessions kept isolated from the admin
 * session (ADR-020/021/025).
 *
 * Architectural role:
 * These are the row/domain shapes the `members` library owns. They mirror the
 * `features/*` conventions (records + workspace-scoped ports in ADR-030's
 * `ports.ts`). No feature logic lives here — interfaces and types only.
 *
 * Scope note (ADR-030 §Trust boundary):
 * A `member` is an authenticated NON-operator principal governed by the
 * *entitlement* axis (tier membership), never by the operator RBAC axis
 * (ADR-021 §1). Nothing in this file grants a member an operator permission.
 */
import type { ISODateTime, JsonObject, UUID } from "@jini-ai/core/primitives";
import type { PrincipalKind } from "@jini-ai/user-management";

/**
 * Principal kind for a front-end member: `@jini-ai/user-management`'s `"member"` kind, distinct from
 * the operator kinds `user | agent | api_key | system`. Sign-up writes a principal row of this kind
 * (`write-service.ts`), and `authorize()` denies it every operator permission through the single
 * `principalKindMayExercisePermission` rule. OWNER DECISION 2026-10-04 (F3144): members may not use
 * admin features for now; allowing some later is a change to that one rule.
 */
export type MemberPrincipalKind = Extract<PrincipalKind, "member">;

/**
 * Member account lifecycle. Disable-only, never hard-deleted, because a member
 * is an ADR-021 principal and `change_set.actorId` / revision history must not
 * dangle (ADR-021 §5). `pending` = created but email not yet verified.
 */
// Trash is a persisted marker; normal by-id/list readers hide it. Email lookup retains the
// marker so a sign-in request cannot recreate an account that still reserves its email.
export type MemberStatus = "pending" | "active" | "disabled" | "trash";

/** Trusted issuer/subject association, independent of the member's current email.
 * An unlink marker reserves the member/provider pair until an explicit signed-in reconnect.
 * No provider tokens, client secrets or claims are persisted here (Google login review, S1).
 */
export interface MemberExternalIdentityRecord {
  id: UUID;
  workspaceId: UUID;
  memberId: UUID;
  providerId: string;
  issuer: string;
  subject: string;
  linkedAt: ISODateTime;
  unlinkedAt?: ISODateTime;
}

/**
 * Front-end member account. `id` is the member's principal id (ULID); the row
 * is the member's profile, analogous to ADR-021's `users` table for operators.
 * Password hashes are credential-only and never enter this profile/view model.
 */
export interface MemberRecord {
  /** Principal id (ULID). Root of identity + audit; disable-only (ADR-021 §5). */
  id: UUID;
  /** Workspace boundary — carried on every scoped row (ADR-007). */
  workspaceId: UUID;
  /** Primary sign-in identifier; unique per workspace (case-folded on write). */
  email: string;
  /** Optional display name. */
  name?: string;
  /** Set once the email is verified (magic-link click or explicit verify). */
  emailVerifiedAt?: ISODateTime;
  /** Credential cutoff: only Trash/restore or explicit revocation changes it. */
  credentialsRevokedAt?: ISODateTime;
  /** Lifecycle state (disable-only). */
  status: MemberStatus;
  /** Operator-only private note (never exposed on the member origin). */
  note?: string;
  /** Namespaced, validated extension bag (`ext.{owner}.*`), per ADR-022 §2. */
  fields?: JsonObject;
  createdAt: ISODateTime;
  updatedAt: ISODateTime;
  /** Monotonic optimistic-concurrency version (ADR-022 §4c). */
  version: number;
}

/** Whether a tier is free or paid. Billing itself is deferred (ADR-030 §6). */
export type MemberTierType = "free" | "paid";

/** Tier lifecycle. Archived tiers stop accepting new subscriptions. */
export type MemberTierStatus = "active" | "archived";

/**
 * A membership tier (Ghost's "tier"). Registry-as-data, mirroring ADR-022
 * content-types / ADR-028 setting-definitions / ADR-027 transform-registry.
 * Price columns are nullable seams: no billing engine ships in v1 (ADR-030 §6).
 */
export interface MemberTierRecord {
  id: UUID;
  workspaceId: UUID;
  name: string;
  /** URL/identifier slug, unique per workspace. */
  slug: string;
  type: MemberTierType;
  status: MemberTierStatus;
  description?: string;
  /** Optional post-signup welcome page path on the public origin. */
  welcomePagePath?: string;
  /** Whether the tier is offered in the public portal (vs comp-only). */
  visibleInPortal: boolean;
  /** Deferred billing seams — populated only by a future billing plugin. */
  monthlyPriceCents?: number;
  yearlyPriceCents?: number;
  /** ISO-4217 code (e.g. "usd"); null until a paid tier is priced. */
  currency?: string;
  createdAt: ISODateTime;
  updatedAt: ISODateTime;
  version: number;
}

/** Subscription lifecycle state; drives entitlement resolution. */
export type MemberSubscriptionStatus = "active" | "canceled" | "expired" | "comped";

/**
 * How a subscription came to exist. `billing` rows are written by a future
 * tier-3 billing plugin through the core chokepoint (ADR-030 §6); v1 core mints
 * `signup` (free) and `comped` (operator-granted) rows only.
 */
export type MemberSubscriptionSource = "signup" | "comp" | "billing";

/**
 * A member's entitlement to a tier. The join carries its own `workspaceId` so
 * the composite `(workspace_id, id)` FKs of ADR-021 §4 are buildable.
 */
export interface MemberSubscriptionRecord {
  id: UUID;
  workspaceId: UUID;
  /** Composite FK → members(workspace_id, id). */
  memberId: UUID;
  /** Composite FK → member_tiers(workspace_id, id). */
  tierId: UUID;
  status: MemberSubscriptionStatus;
  source: MemberSubscriptionSource;
  /** Opaque provider reference (e.g. Stripe subscription id); billing-only. */
  externalRef?: string;
  startedAt: ISODateTime;
  /** For paid/timeboxed entitlements; absent for open-ended free membership. */
  currentPeriodEnd?: ISODateTime;
  canceledAt?: ISODateTime;
  createdAt: ISODateTime;
  updatedAt: ISODateTime;
  version: number;
}

/**
 * A member sign-in session. DELIBERATELY a separate table + cookie + origin
 * from the operator `sessions` of ADR-021 §7 — a member session must never be
 * replayable against an admin route (ADR-030 §3, ADR-020/025 origin isolation).
 */
export interface MemberSessionRecord {
  id: UUID;
  workspaceId: UUID;
  /** Composite FK → members(workspace_id, id). */
  memberId: UUID;
  /** Argon2id/HMAC hash of the session token; the raw token never persists. */
  tokenHash: string;
  createdAt: ISODateTime;
  expiresAt: ISODateTime;
  /** Server-side revocation (ADR-021 §7 revocable sessions). */
  revokedAt?: ISODateTime;
  lastSeenAt?: ISODateTime;
  userAgent?: string;
  ip?: string;
}

/**
 * A single-use, short-TTL member challenge shared by its link and optional sign-in code.
 * Stored hashed; consumed exactly once, then tombstoned. Staff uses a separate realm.
 */
export interface MagicLinkTokenRecord {
  id: UUID;
  workspaceId: UUID;
  /** Existing member id, or reserved id for a new address until consumption. */
  memberId: UUID;
  /** New-address challenge identity; absent on legacy/existing-member links. */
  email?: string;
  tokenHash: string;
  /** Absent for legacy links and link-only password resets; never the raw code. */
  codeHash?: string;
  /** Absent on legacy records means zero; incremented atomically by the repository. */
  failedAttempts?: number;
  /** What the click authorizes — first sign-in also verifies the email. */
  purpose: "signin" | "signup" | "email_change" | "password_reset";
  createdAt: ISODateTime;
  expiresAt: ISODateTime;
  consumedAt?: ISODateTime;
}

/**
 * Content visibility levels stored on an entry at `fields.ext.members.access`
 * (ADR-022 §2 namespaced ext field — no new content table). Mirrors Ghost's
 * public / members / paid / specific-tiers model.
 */
export type MemberContentVisibility = "public" | "members" | "paid" | "tiers";

/** The validated ext-field shape written onto a gated entry. */
export interface MemberContentAccess {
  visibility: MemberContentVisibility;
  /** Required when `visibility === "tiers"`: the entitled tier ids. */
  tierIds?: UUID[];
}

/**
 * The resolved membership context for one front-end request. Anonymous callers
 * get `{ isAuthenticated: false, activeTierIds: [] }`. Derived from a validated
 * member session (never from a client-supplied claim).
 */
export interface MemberContext {
  isAuthenticated: boolean;
  memberId?: UUID;
  /** Tier ids the member currently has an active/comped subscription to. */
  activeTierIds: UUID[];
  /** True if any active tier is a paid tier. */
  isPaid: boolean;
}

/**
 * Outcome of the core content-access decision. This is an ENTITLEMENT decision
 * (tier membership axis), evaluated by the `members` library at the read
 * chokepoint — NOT the ADR-021 operator RBAC `authorize()` (ADR-030 §4).
 */
export interface MemberAccessDecision {
  allowed: boolean;
  /** The entry's declared visibility that produced this decision. */
  visibility: MemberContentVisibility;
  /** Machine-readable reason, e.g. "public", "entitled", "upgrade_required". */
  reason: string;
  /**
   * When `allowed === false`, whether a truncated teaser/paywall may still be
   * rendered (Ghost's "public preview") rather than a hard 404.
   */
  teaser: boolean;
}

/** Raised when a member sign-in credential is invalid, expired, or consumed. */
export class MemberAuthError extends Error {}
/** A passwordless member must prove inbox access again before setting a password. */
export class MemberReauthenticationRequiredError extends MemberAuthError {}
/** Site-wide setup failure; safe to expose before any per-address lookup. */
export class MemberSignInUnavailableError extends Error {}
/** Raised when a member profile/tier/subscription payload fails validation. */
export class MemberValidationError extends Error {}
/** Raised on a unique-constraint clash (e.g. duplicate email or tier slug). */
export class MemberConflictError extends Error {}
/** Raised when a member, tier, or subscription is not found in the workspace. */
export class MemberNotFoundError extends Error {}

/**
 * D1c consent — Members-owned, purpose-keyed consent records (ADR-PIPE-013
 * Decision §4, crosscutting-sweep D1c LOCKED 4-0).
 *
 * Purpose is a module-prefixed string (e.g. `"marketing-email"`,
 * `"newsletter:{listId}"`, `"feature:{ns}:{id}"`) rather than a closed union —
 * new modules mint their own namespaced purposes without touching this file
 * (Article III: no speculative enum, just a documented string convention).
 */
export type ConsentPurpose = string;

/** Consent lifecycle. Only `confirmConsent` may produce `'granted'` (INV-NEW-02) — see `consent-service.ts`. */
export type ConsentStatus = "pending" | "granted" | "revoked";

/** Evidence captured alongside a consent state change (never the raw consent-text body — a reference/hash only). */
export interface ConsentEvidence {
  /** Reference to the consent copy shown (e.g. a CMS entry id), not the text itself. */
  consentTextRef?: string;
  /** Hash of the consent copy shown, for tamper-evidence without storing the body. */
  consentTextHash?: string;
  /** Where the request/confirmation originated, e.g. `"newsletter-signup-form"`. */
  source: string;
  /** The magic/confirm-token id that authorized a `confirmConsent` call, when applicable. */
  confirmTokenId?: string;
  ip?: string;
  userAgent?: string;
}

/**
 * A member's consent record for one `(memberId, purpose)` pair. Reaches
 * `status: 'granted'` ONLY via `requestConsent` then `confirmConsent` in
 * sequence (INV-NEW-02) — no caller may assert `granted` directly.
 */
export interface MemberConsentRecord {
  id: UUID;
  workspaceId: UUID;
  /** Composite FK → members(workspace_id, id). */
  memberId: UUID;
  purpose: ConsentPurpose;
  status: ConsentStatus;
  evidence: ConsentEvidence;
  grantedAt?: ISODateTime;
  revokedAt?: ISODateTime;
  createdAt: ISODateTime;
  updatedAt: ISODateTime;
  version: number;
}

/** A consent state-change op recorded on the shared `member_revisions` ledger (`entity_kind='consent'`). */
export type ConsentRevisionOp = "consent_request" | "consent_confirm" | "consent_revoke";

/**
 * One append-only `member_revisions` row documenting a consent state change.
 * `originModule` attributes the call to the caller (e.g. `"newsletter"`) —
 * satisfies "attributed" without inventing ADR-024 capability infrastructure
 * (ADR-PIPE-013 Decision §4 capability-gating scope decision).
 */
export interface MemberConsentRevisionRecord {
  seq: number;
  workspaceId: UUID;
  memberId: UUID;
  consentId: UUID;
  purpose: ConsentPurpose;
  op: ConsentRevisionOp;
  beforeJson: JsonObject | null;
  afterJson: JsonObject | null;
  originModule: string;
  createdAt: ISODateTime;
}

import { nowIso as clockNowIso } from "@jini-ai/core/primitives";
/**
 * @file `MembersWriteService` implementation (ADR-030 §3/§6, plus the member sign-in amendment).
 *
 * The single write chokepoint for member-domain mutations: email sign-in (link + code), profile
 * updates, disable-only lifecycle and comp/subscription changes, plus the host adapters for
 * Jini's shared email-challenge primitives. Plain async functions taking `{ deps, input }`.
 *
 * New-address challenges reserve a member id and carry the email, without creating a member or
 * principal. Consumption resolves that email again and creates the member then. Legacy
 * challenges without an email remain bound to their existing member id.
 */
import { randomInt } from "node:crypto";
import {
  Argon2PasswordHasher, loadArgon2Binding, NodeSessionTokens,
  newChallengeSecrets, hashChallengeCode, verifyChallengeCode, decideChallenge,
  type AuthChallengeRecord, type ChallengeStorePort,
} from "@jini-ai/user-management/server";
import type { PasswordHasherPort } from "@jini-ai/user-management";
import { renderMemberAuthMail } from "./auth-mail.js";

import { isMailDeliveryAvailable, mailSenderIdentityFor, type MailerSendOptions, type OutboundEmail } from "../../platform/mail/index.js";
import { OriginNotVerifiedError } from "@jini-ai/http-kit/verified-origin";
import {
  MemberAuthError,
  MemberSignInUnavailableError,
  MemberConflictError,
  MemberNotFoundError,
  MemberValidationError,
  type MagicLinkTokenRecord,
  type MemberRecord,
  type MemberSessionRecord,
  type MemberSubscriptionRecord,
  type MemberSubscriptionStatus,
} from "./types.js";
import type { MagicLinkTokenRepoPort, MemberSignInInput, MemberSignInResult, MembersWriteService, MembersWriteServiceDeps } from "./ports.js";

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const MAGIC_LINK_TTL_MS = 15 * 60 * 1000;
/** Placeholder From for a non-delivering mailer; real providers get the site's configured sender. */
const MEMBERS_FALLBACK_SENDER = { email: "no-reply@members.local", name: "Members" } as const;

/**
 * No session lifetime is specified by ADR-030; 30 days is a reasonable default
 * "remember me" duration for a passwordless member portal (Ghost's own default is
 * comparable). Revisit if the ADR pins a value later.
 */
const SESSION_TTL_MS = 30 * 24 * 60 * 60 * 1000;
const VALID_SUBSCRIPTION_STATUSES: readonly MemberSubscriptionStatus[] = [
  "active",
  "canceled",
  "expired",
  "comped",
];

const sessionTokens = new NodeSessionTokens({});
const legacyPasswordHasher = new Argon2PasswordHasher({ loadBinding: loadArgon2Binding });

/** Legacy compositions stay additive; new compositions inject the existing staff hasher. O(1). */
export function memberPasswordHasher({ deps }: { deps: MembersWriteServiceDeps }, _options = {}): PasswordHasherPort {
  return deps.passwordHasher ?? legacyPasswordHasher;
}

// Cache per adapter: tests and alternate hosts must never verify a hash made by another hasher.
const dummyHashes = new WeakMap<PasswordHasherPort, Promise<string>>();

/** One cached, unguessable dummy credential per hasher, so a miss costs the same verify as a hit. */
export function dummyPasswordHash({ hasher }: { hasher: PasswordHasherPort }, _options = {}): Promise<string> {
  let hash = dummyHashes.get(hasher);
  if (!hash) {
    hash = hasher.hash({ password: newRawToken() });
    dummyHashes.set(hasher, hash);
  }
  return hash;
}

/** High-entropy session/link digest; low-entropy codes use Jini's Argon2 helper instead. */
function hashToken(rawToken: string): string {
  return sessionTokens.hashToken({ rawToken });
}

function newRawToken(): string {
  return sessionTokens.newToken({});
}

function isoPlusMs(nowIso: string, ms: number): string {
  return new Date(new Date(nowIso).getTime() + ms).toISOString();
}

/** Normalize + validate an email address. Throws `MemberValidationError` on a bad format. */
function assertValidEmail(email: string): string {
  const normalized = email.trim().toLowerCase();
  if (!normalized || !EMAIL_PATTERN.test(normalized)) {
    throw new MemberValidationError(`'${email}' is not a valid email address`);
  }
  return normalized;
}

/**
 * Resolves or creates a pending member for operator creation or a consumed email challenge.
 * Public sign-in requests never call this owner: unverified addresses must not create accounts.
 * Returns null for a disabled/trashed address. Principal creation precedes the member save.
 * @complexity O(1) — one lookup and at most two saves.
 */
async function resolveOrCreateSignInMember(required: {
  deps: MembersWriteServiceDeps;
  workspaceId: string;
  email: string;
  nowIso: string;
}, optional: { name?: string; memberId?: string; creationSource?: "operator" | "verified_signup"; deferCreatedNotification?: boolean } = {}): Promise<{ member: MemberRecord | null; isNewMember: boolean }> {
  const { deps, workspaceId, email, nowIso } = required;
  const existing = await deps.members.findByEmail({ workspaceId, email });
  if (existing) {
    return { member: existing.status === "disabled" || existing.status === "trash" ? null : existing, isNewMember: false };
  }

  const member: MemberRecord = {
    id: optional.memberId ?? deps.ids.newId(),
    workspaceId,
    email,
    status: "pending",
    ...(optional.name !== undefined ? { name: optional.name } : {}),
    createdAt: nowIso,
    updatedAt: nowIso,
    version: 1,
  };
  // The member's principal row comes first, so a member row never exists without one. Its kind is
  // what makes `authorize()` deny every operator permission to this member (F3144); a principal
  // left behind by a failed member save is inert for the same reason. The display name is not the
  // email, so no second copy of the address lives outside the members tables.
  await deps.principals.save({
    id: member.id,
    workspaceId,
    kind: "member",
    displayName: "Site member",
    status: "active",
    createdAt: nowIso,
  });
  await deps.members.save(member);
  if (!optional.deferCreatedNotification) notifyMemberCreated({ deps, member, creationSource: optional.creationSource ?? "operator", initialState: "pending" });
  return { member, isNewMember: true };
}

/**
 * Creates an operator-requested pending member through the sign-up creation owner.
 * The principal remains kind member; no email verification, consent, token or session is granted.
 * @param required - Injected service ports and workspace-scoped email.
 * @param optional - Optional nonblank display name.
 * @returns The pending member, without a sign-in token or mail side effect.
 * @throws MemberValidationError for malformed input; MemberConflictError for an existing email.
 * @complexity O(1), two indexed email lookups and at most two saves.
 * @example createMember({ deps, input: { workspaceId: "ws", email: "ada@example.com" } }, { name: "Ada" })
 */
export async function createMember(required: {
  deps: MembersWriteServiceDeps;
  input: { workspaceId: string; email: string };
}, optional: { name?: string; deferCreatedNotification?: boolean } = {}): Promise<{ member: MemberRecord }> {
  const { deps, input } = required;
  const email = assertValidEmail(input.email);
  const name = optional.name?.trim();
  if (name !== undefined && !name) throw new MemberValidationError("name must not be blank when provided");
  const existing = await deps.members.findByEmail({ workspaceId: input.workspaceId, email });
  if (existing?.status === "trash") {
    throw new MemberConflictError(`member with email '${email}' is in Trash; restore it from the admin Trash screen`);
  }
  if (existing) {
    throw new MemberConflictError(`member with email '${email}' already exists`);
  }
  const { member } = await resolveOrCreateSignInMember({ deps, workspaceId: input.workspaceId, email, nowIso: clockNowIso({ clock: deps.clock }) }, { name, deferCreatedNotification: optional.deferCreatedNotification });
  if (!member) throw new MemberConflictError(`member with email '${email}' already exists`);
  return { member };
}

/**
 * Builds an absolute link from trusted origin evidence, never request headers.
 * Missing/unverified evidence refuses sign-in for every address before repository writes.
 * @throws MemberSignInUnavailableError when the site origin is not configured.
 * @complexity O(1) — one canonical-origin read.
 */
async function resolveSignInLinkPath(required: {
  deps: MembersWriteServiceDeps;
  workspaceId: string;
  relativePath: string;
}, _options: Record<string, never> = {}): Promise<string> {
  const { deps, workspaceId, relativePath } = required;
  if (!deps.origin) throw new MemberSignInUnavailableError("Member sign-in is unavailable: the site address is not set up.");
  try {
    const origin = await deps.origin.canonicalOrigin({ workspaceId });
    const portSuffix = origin.port ? `:${origin.port}` : "";
    const basePath = origin.basePath ?? "";
    return `${origin.scheme}://${origin.host}${portSuffix}${basePath}${relativePath}`;
  } catch (err) {
    if (!(err instanceof OriginNotVerifiedError)) throw err;
    throw new MemberSignInUnavailableError("Member sign-in is unavailable: the site address is not set up.");
  }
}

/**
 * Checks site-wide mail readiness before any address lookup. Sender resolution settles lazy
 * configuration first; transactional readiness is independent of the bulk lane.
 * @throws MemberSignInUnavailableError for an unconfigured/non-delivering transactional lane.
 * @complexity O(1) status read and capabilities check; no per-address I/O.
 */
async function requireSignInMail(required: { deps: MembersWriteServiceDeps }, _options: Record<string, never> = {}): Promise<void> {
  const { deps } = required;
  const status = await deps.mailStatus?.();
  const transactional = status?.lanes.find(lane => lane.lane === "transactional");
  if ((status && transactional?.state !== "ready") || !isMailDeliveryAvailable(deps.mailer)) {
    throw new MemberSignInUnavailableError("Member sign-in is unavailable: email is not set up for this site.");
  }
}

/**
 * Member-table adapter for Jini's challenge contract. Issuance supplies host identity metadata;
 * reads retain that metadata for deferred signup. Realm is implicit in this dedicated table.
 * @complexity O(1) indexed operations; repository CAS owns concurrent consumption/attempts.
 */
export function memberChallengeStore(required: {
  repo: MagicLinkTokenRepoPort;
  identity?: Pick<MagicLinkTokenRecord, "memberId" | "email" | "createdAt">;
}, _options = {}): ChallengeStorePort {
  const { repo, identity } = required;
  return {
    save: async record => {
      if (!identity || record.realm !== "member") throw new Error("Member challenge issuance requires member identity");
      await repo.save({ ...identity, id: record.id, workspaceId: record.workspaceId,
        purpose: record.purpose as MagicLinkTokenRecord["purpose"], tokenHash: record.tokenHash,
        codeHash: record.codeHash ?? undefined, failedAttempts: record.failedAttempts,
        expiresAt: record.expiresAt, consumedAt: record.consumedAt ?? undefined });
    },
    findById: async input => asChallenge(await repo.findById(input)),
    findByTokenHash: async input => asChallenge(await repo.findByTokenHash(input)),
    reserveCodeAttempt: input => repo.reserveCodeAttempt(input, { maxAttempts: input.maxAttempts }),
    consume: async input => {
      try {
        await repo.consume({ workspaceId: input.workspaceId, id: input.id, consumedAt: input.nowIso });
        return true;
      } catch (error) {
        // Only the repo's known single-use rejections are invalid credentials. Outages must surface.
        const prefix = `magic link token '${input.id}' `;
        if (error instanceof Error && ["was not found", "has expired", "was already consumed"]
          .some(reason => error.message === prefix + reason)) return false;
        throw error;
      }
    },
  };
}

/** Legacy link-only rows normalize to Jini's nullable code hash and zero spent attempts. */
function asChallenge(record: MagicLinkTokenRecord | null): AuthChallengeRecord | null {
  return record && { ...record, realm: "member", codeHash: record.codeHash ?? null, failedAttempts: record.failedAttempts ?? 0 };
}

/**
 * Only local absolute paths survive; controls/backslashes can change browser URL parsing, and an
 * encoded slash/backslash becomes `//host` if any later hop decodes the path before redirecting.
 */
function safeRedirectPath(path?: string): string | undefined {
  return path && /^\/(?!\/)/.test(path) && !/[\\\x00-\x1f\x7f]|%(2f|5c)/i.test(path) ? path : undefined;
}

/** Fragment-only secrets prevent accidental consumption and disclosure through GET request logs. */
function challengeLinkPath(required: {
  purpose: "signin" | "password_reset"; token: string; redirectPath?: string;
}, _options = {}): string {
  const { purpose, token, redirectPath } = required;
  if (purpose === "password_reset") return `/reset-password#token=${token}`;
  const redirect = safeRedirectPath(redirectPath);
  return `/signin#magic=${token}${redirect ? `&redirect=${encodeURIComponent(redirect)}` : ""}`;
}

/** Persist only challenge hashes and the deferred member identity; O(1) adapter calls. */
async function saveMemberChallenge(required: {
  deps: MembersWriteServiceDeps; member: MemberRecord | null; email: string;
  purpose: "signin" | "password_reset"; challengeId: string; nowIso: string; workspaceId: string;
  tokenHash: string; codeHash: string | null;
}, _options = {}): Promise<void> {
  const { deps, member, email, purpose, challengeId, nowIso, workspaceId, tokenHash, codeHash } = required;
  const store = memberChallengeStore({ repo: deps.magicLinks, identity: {
    memberId: member?.id ?? deps.ids.newId(), createdAt: nowIso, ...(member ? {} : { email }),
  } });
  await store.save({ id: challengeId, workspaceId, realm: "member", purpose,
    tokenHash, failedAttempts: 0, codeHash,
    expiresAt: isoPlusMs(nowIso, MAGIC_LINK_TTL_MS) });
}

/**
 * Issue sign-in or link-only reset through the same mail/readiness and challenge lifecycle.
 * Ineligible addresses receive a fresh, unstored handle; requests never create members.
 * Preparation checks site setup; deliver() owns all per-address work.
 * Secrets enter only the rendered send payload, never a profile, repo row or idempotency key.
 * @throws MemberSignInUnavailableError for site-wide setup; validation/adapter errors propagate.
 * @complexity O(1) reads/writes and one bounded password hash for sign-in codes.
 */
export async function prepareMemberChallenge(required: {
  deps: MembersWriteServiceDeps;
  input: { workspaceId: string; email: string; redirectPath?: string };
  purpose: "signin" | "password_reset";
}, _options = {}): Promise<{ challengeId: string; deliver: () => Promise<{ delivered: boolean; challengeId: string }> }> {
  const { deps, input, purpose } = required;
  const email = assertValidEmail(input.email);
  const nowIso = clockNowIso({ clock: deps.clock });
  // Resolved before the member lookup: a missing sender must fail the same way for every address,
  // so the error itself never tells a caller which emails are registered, and no token is minted
  // for a link that could not be sent.
  const from = await mailSenderIdentityFor({ mailer: deps.mailer }, { senderIdentity: deps.senderIdentity })
    .resolve({ workspaceId: input.workspaceId, fallback: MEMBERS_FALLBACK_SENDER });
  await requireSignInMail({ deps });
  const secrets = newChallengeSecrets({ tokens: sessionTokens, randomInt: ({ min, max }) => randomInt(min, max) });
  const relativePath = challengeLinkPath({ purpose, token: secrets.token, redirectPath: input.redirectPath });
  // ADR-040 owns origin evidence. Resolve before the address lookup so a setup error cannot
  // distinguish an existing/disabled address, and never store a token for a relative link.
  const link = await resolveSignInLinkPath({ deps, workspaceId: input.workspaceId, relativePath });
  const challengeId = deps.ids.newId();
  // Public HTTP can acknowledge setup now; every address-dependent effect stays in deliver().
  return { challengeId, deliver: async () => {
    // Hash before the lookup: ineligible addresses return early, and the Argon2 cost must not tell.
    const codeHash = purpose === "signin"
      ? await hashChallengeCode({ code: secrets.code, hasher: memberPasswordHasher({ deps }) }) : null;
    const member = await deps.members.findByEmail({ workspaceId: input.workspaceId, email });
    if (member?.status === "disabled" || member?.status === "trash") return { delivered: false, challengeId };
    if (purpose === "password_reset" && !member) return { delivered: false, challengeId };
    await saveMemberChallenge({ deps, member, email, purpose, challengeId, nowIso,
      tokenHash: secrets.tokenHash, codeHash, workspaceId: input.workspaceId });
    const message: OutboundEmail = { workspaceId: input.workspaceId, to: { email }, from,
      ...renderMemberAuthMail({ purpose, link, code: secrets.code }) };
    const sendOptions: MailerSendOptions = {
      // Reuse the sign_in activity/capture-redaction prefix for reset mail too.
      idempotencyKey: `members:signin:${purpose === "password_reset" ? "reset:" : ""}${secrets.tokenHash}`,
      workspaceId: input.workspaceId, sourceContext: { module: "members" }, purpose: "transactional",
      // Interactive auth mail proceeds without a durable outbox (SPEC-022 REQ-09).
      lane: "interactive",
    };
    const result = await deps.mailer.send(message, sendOptions);
    return { delivered: result.ok && !result.providerMessageId.startsWith("captured:"), challengeId };
  } };
}

/** Existing callers retain the awaited delivery contract; public HTTP uses the same prepared owner. */
export async function requestMemberChallenge(required: Parameters<typeof prepareMemberChallenge>[0], _options = {}): Promise<{ delivered: boolean; challengeId: string }> {
  const prepared = await prepareMemberChallenge(required);
  return prepared.deliver();
}

/** Request a link and six-digit code sharing one single-use challenge; O(1) adapter calls. */
async function requestSignInLink(required: {
  deps: MembersWriteServiceDeps;
  input: { workspaceId: string; email: string; redirectPath?: string };
}, _options = {}): Promise<{ delivered: boolean; challengeId: string }> {
  return requestMemberChallenge({ ...required, purpose: "signin" });
}

/**
 * Purpose-bound completion: reserve attempts before checking a code, then CAS-consume.
 * All invalid credentials (including lost races) give the same MemberAuthError.
 * @complexity O(1) indexed operations and at most one password verification.
 */
export async function consumeMemberChallenge(required: {
  deps: MembersWriteServiceDeps; input: MemberSignInInput; purpose: "signin" | "password_reset"; nowIso: string;
}, _options = {}): Promise<MagicLinkTokenRecord> {
  const { deps, input, purpose, nowIso } = required;
  const store = memberChallengeStore({ repo: deps.magicLinks });
  const scope = { workspaceId: input.workspaceId, realm: "member", purpose };
  const record = input.token !== undefined
    ? await store.findByTokenHash({ ...scope, tokenHash: hashToken(input.token) })
    : await store.findById({ ...scope, id: input.challengeId });
  const hasher = memberPasswordHasher({ deps });
  if (decideChallenge({ ...scope, record, nowIso }) !== "ok" || !record) {
    // Disabled/trashed addresses get unstored handles: spend the same verify so timing cannot tell.
    if (input.token === undefined) await verifyChallengeCode({ code: input.code, hash: await dummyPasswordHash({ hasher }), hasher });
    throw new MemberAuthError("sign-in credential is invalid");
  }
  if (input.token === undefined) {
    if (!await store.reserveCodeAttempt({ ...scope, id: record.id, nowIso })) throw new MemberAuthError("sign-in credential is invalid");
    if (!await verifyChallengeCode({ code: input.code, hash: record.codeHash, hasher })) throw new MemberAuthError("sign-in credential is invalid");
  }
  if (!await store.consume({ ...scope, id: record.id, nowIso })) throw new MemberAuthError("sign-in credential is invalid");
  // The host adapter preserves memberId/email/createdAt while normalizing challenge metadata.
  return record as AuthChallengeRecord & MagicLinkTokenRecord;
}

/**
 * Resolves legacy member-bound links or creates the account for a consumed new-address link.
 * Rechecking email handles two outstanding signup links and accounts created since issuance.
 * @throws MemberAuthError for an ineligible address or a lost legacy member.
 * @complexity O(1), one lookup and at most two saves through the existing creation owner.
 */
async function resolveConsumedSignInMember(required: {
  deps: MembersWriteServiceDeps; tokenRecord: MagicLinkTokenRecord; nowIso: string;
}, _options: Record<string, never> = {}): Promise<{ member: MemberRecord; isNewMember: boolean }> {
  const { deps, tokenRecord, nowIso } = required;
  if (tokenRecord.email !== undefined) {
    const resolved = await resolveOrCreateSignInMember({
      deps, workspaceId: tokenRecord.workspaceId, email: tokenRecord.email, nowIso,
    }, { memberId: tokenRecord.memberId, creationSource: "verified_signup" });
    if (!resolved.member) throw new MemberAuthError("sign-in credential is invalid");
    return { member: resolved.member, isNewMember: resolved.isNewMember };
  }
  const member = await deps.members.findById({ workspaceId: tokenRecord.workspaceId, id: tokenRecord.memberId });
  if (!member) throw new MemberAuthError("sign-in credential is invalid");
  return { member, isNewMember: false };
}

/**
 * Consume a link or code: create/resolve the member, verify email, promote to active,
 * and mint a member session. The raw bearer is returned only for setting the member cookie.
 *
 * @complexity O(1) — one token lookup/consume, one member read/write, one session write.
 * @overallScore 100
 */
async function completeSignIn(required: {
  deps: MembersWriteServiceDeps;
  input: MemberSignInInput;
}, _options: Record<string, never> = {}): Promise<MemberSignInResult> {
  const { deps, input } = required;
  const nowIso = clockNowIso({ clock: deps.clock });
  const tokenRecord = await consumeMemberChallenge({ deps, input, purpose: "signin", nowIso });

  const { member: existingMember, isNewMember } = await resolveConsumedSignInMember({ deps, tokenRecord, nowIso });
  if (existingMember.status === "disabled" || existingMember.status === "trash") {
    throw new MemberAuthError("sign-in credential is invalid");
  }
  // A link minted before Trash/restore (including a request racing credential revocation) must
  // not sign the restored account back in. Profile edits and other sign-ins keep links valid.
  if (existingMember.credentialsRevokedAt && existingMember.credentialsRevokedAt >= tokenRecord.createdAt) {
    throw new MemberAuthError("sign-in credential is invalid");
  }

  const member: MemberRecord = {
    ...existingMember,
    status: existingMember.status === "pending" ? "active" : existingMember.status,
    emailVerifiedAt: existingMember.emailVerifiedAt ?? nowIso,
    updatedAt: nowIso,
    version: existingMember.version + 1,
  };
  await deps.members.save(member);

  return { ...await issueMemberSession({ deps, member, nowIso }, { userAgent: input.userAgent, ip: input.ip }), isNewMember };
}

/**
 * The sole member session minter, reused by password, link and code sign-in.
 * Persists only the bearer digest and returns the raw token for the HTTP cookie adapter.
 * @complexity O(1), one session write.
 */
export async function issueMemberSession(required: {
  deps: MembersWriteServiceDeps; member: MemberRecord; nowIso: string;
}, options: { userAgent?: string; ip?: string } = {}): Promise<MemberSignInResult> {
  const { deps, member, nowIso } = required;
  const rawSessionToken = newRawToken();
  const session: MemberSessionRecord = {
    id: deps.ids.newId(),
    workspaceId: member.workspaceId,
    memberId: member.id,
    tokenHash: hashToken(rawSessionToken),
    createdAt: nowIso,
    expiresAt: isoPlusMs(nowIso, SESSION_TTL_MS),
    userAgent: options.userAgent,
    ip: options.ip,
  };
  await deps.sessions.save(session);

  return { member, session, rawSessionToken };
}

/**
 * Operator/self profile update (validated, revision-recorded via `save`).
 * @complexity O(1).
 * @overallScore 100
 */
async function updateProfile(required: {
  deps: MembersWriteServiceDeps;
  input: { workspaceId: string; memberId: string; name?: string; note?: string };
}): Promise<{ member: MemberRecord }> {
  const { deps, input } = required;
  const existing = await deps.members.findById({ workspaceId: input.workspaceId, id: input.memberId });
  if (!existing) {
    throw new MemberNotFoundError(`member '${input.memberId}' was not found`);
  }

  let name = existing.name;
  if (input.name !== undefined) {
    const trimmed = input.name.trim();
    if (!trimmed) {
      throw new MemberValidationError("name must not be blank when provided");
    }
    name = trimmed;
  }

  const note = input.note !== undefined ? input.note.trim() : existing.note;

  const member: MemberRecord = {
    ...existing,
    name,
    note,
    updatedAt: clockNowIso({ clock: deps.clock }),
    version: existing.version + 1,
  };
  await deps.members.save(member);

  return { member };
}

/**
 * Operator: disable a member (ADR-021 §5 disable-only, never hard-delete).
 * Idempotent — disabling an already-disabled member is a no-op, not an error.
 * Also revokes every live session for the member so a disabled account cannot
 * keep reading gated content through a session minted before the disable.
 *
 * @complexity O(s), s = the member's live session count (small, per-member).
 * @overallScore 100
 */
async function disableMember(required: {
  deps: MembersWriteServiceDeps;
  input: { workspaceId: string; memberId: string };
}): Promise<{ member: MemberRecord }> {
  const { deps, input } = required;
  const existing = await deps.members.findById({ workspaceId: input.workspaceId, id: input.memberId });
  if (!existing) {
    throw new MemberNotFoundError(`member '${input.memberId}' was not found`);
  }

  if (existing.status === "disabled") {
    return { member: existing };
  }

  const nowIso = clockNowIso({ clock: deps.clock });
  const member: MemberRecord = {
    ...existing,
    status: "disabled",
    credentialsRevokedAt: nowIso,
    updatedAt: nowIso,
    version: existing.version + 1,
  };
  await deps.members.save(member);
  await deps.sessions.revokeAllForMember({
    workspaceId: input.workspaceId,
    memberId: input.memberId,
    revokedAt: nowIso,
  });

  return { member };
}

/**
 * Operator: grant a comp subscription. Rejects an archived tier and rejects a
 * duplicate active/comped subscription to the same tier (aggregate invariant:
 * a member cannot hold two simultaneous entitlements to one tier).
 *
 * @complexity O(k), k = the member's active-subscription count (duplicate check).
 * @overallScore 100
 */
async function compSubscription(required: {
  deps: MembersWriteServiceDeps;
  input: { workspaceId: string; memberId: string; tierId: string };
}): Promise<{ subscription: MemberSubscriptionRecord }> {
  const { deps, input } = required;
  const member = await deps.members.findById({ workspaceId: input.workspaceId, id: input.memberId });
  if (!member) {
    throw new MemberNotFoundError(`member '${input.memberId}' was not found`);
  }

  const tier = await deps.tiers.findById({ workspaceId: input.workspaceId, id: input.tierId });
  if (!tier) {
    throw new MemberNotFoundError(`tier '${input.tierId}' was not found`);
  }
  if (tier.status !== "active") {
    throw new MemberValidationError(`tier '${input.tierId}' is archived and cannot accept new subscriptions`);
  }

  const nowIso = clockNowIso({ clock: deps.clock });
  const activeSubscriptions = await deps.subscriptions.listActiveByMember({
    workspaceId: input.workspaceId,
    memberId: input.memberId,
    nowIso,
  });
  if (activeSubscriptions.some((subscription) => subscription.tierId === input.tierId)) {
    throw new MemberConflictError(
      `member '${input.memberId}' already has an active subscription to tier '${input.tierId}'`
    );
  }

  const subscription: MemberSubscriptionRecord = {
    id: deps.ids.newId(),
    workspaceId: input.workspaceId,
    memberId: input.memberId,
    tierId: input.tierId,
    status: "comped",
    source: "comp",
    startedAt: nowIso,
    createdAt: nowIso,
    updatedAt: nowIso,
    version: 1,
  };
  await deps.subscriptions.save(subscription);

  return { subscription };
}

/**
 * Change a subscription's status (cancel/expire; also the entry point a future
 * billing plugin uses for `source='billing'` rows — ADR-030 §6).
 *
 * @complexity O(1).
 * @overallScore 100
 */
async function setSubscriptionStatus(required: {
  deps: MembersWriteServiceDeps;
  input: {
    workspaceId: string;
    subscriptionId: string;
    status: MemberSubscriptionStatus;
    externalRef?: string;
  };
}): Promise<{ subscription: MemberSubscriptionRecord }> {
  const { deps, input } = required;
  const existing = await deps.subscriptions.findById({
    workspaceId: input.workspaceId,
    id: input.subscriptionId,
  });
  if (!existing) {
    throw new MemberNotFoundError(`subscription '${input.subscriptionId}' was not found`);
  }
  if (!VALID_SUBSCRIPTION_STATUSES.includes(input.status)) {
    throw new MemberValidationError(`'${input.status}' is not a valid subscription status`);
  }

  const nowIso = clockNowIso({ clock: deps.clock });
  const subscription: MemberSubscriptionRecord = {
    ...existing,
    status: input.status,
    externalRef: input.externalRef ?? existing.externalRef,
    canceledAt: input.status === "canceled" ? nowIso : existing.canceledAt,
    updatedAt: nowIso,
    version: existing.version + 1,
  };
  await deps.subscriptions.save(subscription);

  return { subscription };
}

/**
 * The `MembersWriteService` implementation, grouped into the port shape.
 */
export const membersWriteService: MembersWriteService = {
  requestSignInLink,
  completeSignIn,
  updateProfile,
  disableMember,
  compSubscription,
  setSubscriptionStatus,
};

export {
  requestSignInLink,
  completeSignIn,
  updateProfile,
  disableMember,
  compSubscription,
  setSubscriptionStatus,
};

/** Notify only an actually written member. Observers cannot change durable identity or auth outcomes.
 * @complexity O(1). */
export function notifyMemberCreated(
  { deps, member, creationSource, initialState }: { deps: MembersWriteServiceDeps; member: MemberRecord;
    creationSource: "operator" | "verified_signup" | "oidc_signup"; initialState: "pending" | "active" },
  _optional: Record<string, never> = {},
): void {
  try { deps.onMemberCreated?.({ workspaceId: member.workspaceId, memberId: member.id, creationSource, initialState }); }
  catch { /* Optional product analytics cannot alter a committed member. */ }
}

