/**
 * The exact slice of the route-deps bag Newsletter's tool handlers read. Declared structurally
 * (rather than importing `server/routes/types`'s `RouteDeps`, or `server/routes/admin/newsletter/
 * deps.ts`'s `NewsletterRouteDeps`, which itself extends `RouteDeps`) so this module carries no
 * back-edge into the composition root. `server/routes/*` satisfies this structurally by passing its
 * existing `NewsletterRouteDeps` object; nothing there changes.
 */
export interface NewsletterToolDeps {
  authorize: AuthorizeFn;
  workspaceId: string;
  clock: { nowIso(): string };
  idGen: { newId(): string };
  outbox: OutboxPort;
  bus: EventBusPort;
  mailer: MailerPort;
  originRegistry: OriginRegistryPort;
  newsletterReady: Promise<void>;
  newsletterCampaignRepo: NewsletterCampaignRepoPort;
  newsletterListRepo: NewsletterListRepoPort;
  newsletterSubscriptionRepo: NewsletterSubscriptionRepoPort;
  newsletterAudienceSnapshotRepo: NewsletterAudienceSnapshotRepoPort;
  newsletterSendRepo: NewsletterSendRepoPort;
  newsletterConfirmationTokenRepo: NewsletterConfirmationTokenRepoPort;
  newsletterSubscriberDirectory: SubscriberDirectoryPort;
  newsletterHooks: HookRegistry;
  membersConsentCapability: MembersConsentCapability | null;
  /** Optional binding to the launch setting; absent preserves the existing fail-closed default. */
  newsletterSendingEnabled?: (workspaceId: string) => Promise<boolean>;
  /** The site's system-email From resolver — see `ConfirmationDeps.senderIdentity`. */
  mailSenderIdentity?: MailSenderIdentityPort;
}

/**
 * Assembles `campaign-write-service.ts`'s deps bundle from {@link NewsletterToolDeps} — a local
 * duplicate of `server/routes/admin/newsletter/deps.ts`'s `toCampaignWriteServiceDeps` rather than
 * an import of it, for the same reason `features/settings/tool-registrations.ts`'s header gives for
 * duplicating `toWriteServiceDeps`: importing from the HTTP admin layer would invert this codebase's
 * ports/adapters direction. Each `to*Deps` mapper below carries the identical rationale.
 */
function toCampaignWriteServiceDeps(deps: NewsletterToolDeps): CampaignWriteServiceDeps {
  return {
    campaignRepo: deps.newsletterCampaignRepo,
    listRepo: deps.newsletterListRepo,
    clock: deps.clock,
    ids: deps.idGen,
  };
}

/** Assembles `lists.ts`'s deps bundle — the local twin of `toCampaignWriteServiceDeps` above. */
function toListsDeps(deps: NewsletterToolDeps): ListsDeps {
  return { listRepo: deps.newsletterListRepo, clock: deps.clock, ids: deps.idGen };
}

/** Assembles `confirmation.ts`'s deps bundle — the local twin of `toCampaignWriteServiceDeps` above. */
function toConfirmationDeps(deps: NewsletterToolDeps): ConfirmationDeps {
  return {
    tokenRepo: deps.newsletterConfirmationTokenRepo,
    subscriptionRepo: deps.newsletterSubscriptionRepo,
    mailer: deps.mailer,
    consentCapability: deps.membersConsentCapability,
    originRegistry: deps.originRegistry,
    clock: deps.clock,
    ids: deps.idGen,
    senderIdentity: deps.mailSenderIdentity,
  };
}

/** Assembles `subscriptions.ts`'s deps bundle (nests `toConfirmationDeps` — `saveSubscription`
 * triggers `issueConfirmationToken`) — the local twin of `toCampaignWriteServiceDeps` above. */
function toSubscriptionsDeps(deps: NewsletterToolDeps): SubscriptionsDeps {
  return {
    subscriptionRepo: deps.newsletterSubscriptionRepo,
    listRepo: deps.newsletterListRepo,
    subscriberDirectory: deps.newsletterSubscriberDirectory,
    confirmationDeps: toConfirmationDeps(deps),
    clock: deps.clock,
    ids: deps.idGen,
  };
}

/** Assembles `subscriptions.ts`'s `unsubscribeSubscription` deps bundle — the local twin of
 * `toCampaignWriteServiceDeps` above. */
function toUnsubscribeSubscriptionDeps(deps: NewsletterToolDeps): UnsubscribeSubscriptionDeps {
  return {
    subscriptionRepo: deps.newsletterSubscriptionRepo,
    consentCapability: deps.membersConsentCapability,
    clock: deps.clock,
  };
}

/**
 * Assembles `send-pipeline.ts`'s deps bundle — the local twin of `toCampaignWriteServiceDeps` above.
 * The optional launch-setting binding defaults to false, preserving the admin routes' existing
 * fail-closed behavior. Runtime composition still has no sending toggle or consent binding.
 */
export function toNewsletterSendPipelineDeps(deps: NewsletterToolDeps): SendPipelineDeps {
  return {
    campaignRepo: deps.newsletterCampaignRepo,
    subscriptionRepo: deps.newsletterSubscriptionRepo,
    audienceSnapshotRepo: deps.newsletterAudienceSnapshotRepo,
    sendRepo: deps.newsletterSendRepo,
    subscriberDirectory: deps.newsletterSubscriberDirectory,
    hooks: deps.newsletterHooks,
    mailer: deps.mailer,
    launchGateDeps: {
      isSendingEnabled: deps.newsletterSendingEnabled ?? (async () => false),
      consentCapability: deps.membersConsentCapability,
      originRegistry: deps.originRegistry,
      mailer: deps.mailer,
    },
    outbox: deps.outbox,
    bus: deps.bus,
    clock: deps.clock,
    ids: deps.idGen,
  };
}

/**
 * This wiring layer's OWN risk classification, authored from what each handler below actually
 * calls. See `DerivedRiskByToolId` in the kit for why it is independent of the catalog's own
 * `sideEffects` declaration.
 */
export const newsletterDerivedRisk: DerivedRiskByToolId = new Map<string, AgentToolSideEffect>([
  // -> newsletterCampaignRepo.list / .findById: read only.
  ["newsletter_list_campaigns", "none"],
  ["newsletter_get_campaign", "none"],
  // -> newsletterListRepo.list: read only.
  ["newsletter_list_lists", "none"],
  // -> newsletterSubscriptionRepo.list: read only.
  ["newsletter_list_subscriptions", "none"],
  // -> newsletterSendRepo.listByCampaign: read only.
  ["newsletter_list_send_log", "none"],
  // -> saveCampaign (campaign-write-service.ts): campaign row + revision write in one tx.
  ["newsletter_create_campaign", "mutates-durable-state"],
  ["newsletter_update_campaign", "mutates-durable-state"],
  // -> cancelCampaign (campaign-write-service.ts): status transition + revision.
  ["newsletter_cancel_campaign", "mutates-durable-state"],
  // -> pauseCampaign (send-pipeline.ts): status transition + revision; only ever HALTS sending.
  ["newsletter_pause_campaign", "mutates-durable-state"],
  // -> saveList (lists.ts): list row write.
  ["newsletter_create_list", "mutates-durable-state"],
  // -> archiveList (lists.ts): status flip.
  ["newsletter_archive_list", "mutates-durable-state"],
  // -> saveSubscription (subscriptions.ts): subscription row write + mints/sends one confirmation email.
  ["newsletter_create_subscription", "mutates-durable-state"],
  // -> unsubscribeSubscription (subscriptions.ts): status flip + conditional consent revoke.
  ["newsletter_remove_subscription", "mutates-durable-state"],
  // -> issueConfirmationToken (confirmation.ts): invalidates prior tokens, writes a new token row, sends mail.
  ["newsletter_resend_confirmation", "mutates-durable-state"],
]);

/** Model-facing campaign view — drops `workspaceId` (same reasoning as every other `to*View` in this codebase) and the pipeline-internal `audienceSnapshotId`/`sendStartedAt`/`createdByPrincipal` (plumbing no wired tool's follow-up call consumes). */
function toCampaignToolView(campaign: CampaignRecord) {
  return {
    id: campaign.id,
    status: campaign.status,
    subject: campaign.subject,
    preheader: campaign.preheader,
    fromName: campaign.fromName,
    fromEmail: campaign.fromEmail,
    replyTo: campaign.replyTo,
    listId: campaign.listId,
    scheduledAt: campaign.scheduledAt,
    counters: { ...campaign.counters },
    version: campaign.version,
    createdAt: campaign.createdAt,
    updatedAt: campaign.updatedAt,
  };
}

/** Model-facing list view. */
function toListToolView(list: NewsletterListRow) {
  return { id: list.id, name: list.name, slug: list.slug, isDefault: list.isDefault, status: list.status };
}

/** Model-facing subscription view — drops `consentRevisionIdAtSubscribe` (an internal binding token, not a decision-relevant value). */
function toSubscriptionToolView(subscription: SubscriptionRow) {
  return {
    id: subscription.id,
    listId: subscription.listId,
    subscriberId: subscription.subscriberId,
    status: subscription.status,
    source: subscription.source,
    subscribedAt: subscription.subscribedAt,
    unsubscribedAt: subscription.unsubscribedAt,
  };
}

/** Model-facing send-log row view — drops `idempotencyKey`/`audienceSnapshotId` (delivery-plumbing internals). */
function toSendLogToolView(row: SendRow) {
  return {
    id: row.id,
    subscriberId: row.subscriberId,
    recipientEmail: row.recipientEmail,
    status: row.status,
    attempts: row.attempts,
    providerMessageId: row.providerMessageId,
    lastError: row.lastError,
    nextAttemptAt: row.nextAttemptAt,
    updatedAt: row.updatedAt,
  };
}

/**
 * The Newsletter errors that reach the model with their real reason instead of a redacted
 * `INTERNAL_ERROR` — see `contracts/core/model-facing-tool-errors.ts` for the mechanism and for why
 * this list is an ALLOWLIST rather than a blanket unwrap.
 *
 * Every message listed is built from the caller's own ids plus this domain's vocabulary; none
 * carries a subscriber's email, name, or any other contact detail. That was checked rather than
 * assumed: `subscriptions.ts`/`campaign-write-service.ts`/`lists.ts` interpolate `listId`,
 * `subscriberId`, `campaignId` and field/limit names only, and `NewsletterSubscriberNotFoundError`
 * names a subscriber UUID, not the person behind it. Note that
 * `newsletter_resend_confirmation` reports mail-off before looking up a subscription and otherwise
 * returns the same acknowledgement whether or not a pending contact resolves.
 *
 * Both TOKEN classes are deliberately ABSENT. `NewsletterConfirmTokenInvalidError` and
 * `NewsletterUnsubscribeTokenInvalidError` are raised on the public confirm/unsubscribe redemption
 * paths (`confirmation.ts`, `unsubscribe.ts`), which no tool in this catalog calls, and their
 * messages ("token was already consumed", "signature is invalid") answer a question about a token
 * HOLDER rather than about the caller's own request — the same line `features/members/tool-
 * registrations.ts` draws around `MemberAuthError`. `NewsletterLaunchGateBlockedError` is absent
 * because delivery/tool-registrations.ts handles launch prerequisites separately with fixed, safe vocabulary.
 */
const NEWSLETTER_MODEL_FACING_ERRORS: readonly ModelFacingErrorRule[] = [
  forbiddenRule({ domainPrefix: "NEWSLETTER", error: ForbiddenError }),
  { error: NewsletterForbiddenError, code: "NEWSLETTER_FORBIDDEN" },
  { error: NewsletterCampaignNotFoundError, code: "NEWSLETTER_CAMPAIGN_NOT_FOUND" },
  { error: NewsletterListNotFoundError, code: "NEWSLETTER_LIST_NOT_FOUND" },
  { error: NewsletterSubscriptionNotFoundError, code: "NEWSLETTER_SUBSCRIPTION_NOT_FOUND" },
  { error: NewsletterSubscriberNotFoundError, code: "NEWSLETTER_SUBSCRIBER_NOT_FOUND" },
  { error: NewsletterValidationError, code: "NEWSLETTER_VALIDATION_FAILED" },
  { error: NewsletterCampaignNotEditableError, code: "NEWSLETTER_CAMPAIGN_NOT_EDITABLE" },
  { error: NewsletterDefaultListProtectedError, code: "NEWSLETTER_DEFAULT_LIST_PROTECTED" },
  {
    error: NewsletterConflictError,
    code: "NEWSLETTER_CONFLICT",
    guidance: "Nothing was written. Re-read the record to get its current version and resend with that as expectedVersion.",
  },
];

async function resendPendingSubscriptionConfirmation(
  { deps, subscriptionId, signal }: { deps: NewsletterToolDeps; subscriptionId: string; signal: AbortSignal },
  _options: Record<string, never> = {},
) {
  try {
    const subscription = await deps.newsletterSubscriptionRepo.findById({ workspaceId: deps.workspaceId, id: subscriptionId });
    // Constant acknowledgement for missing subscriptions, missing contacts and non-pending records.
    if (!subscription || subscription.status !== "pending") return { delivered: true, mailDeliveryAvailable: true };
    const contact = await deps.newsletterSubscriberDirectory.getContact({ workspaceId: deps.workspaceId, subscriberId: subscription.subscriberId });
    if (signal.aborted) return { confirmed: false, reason: "abandoned", delivered: false, mailDeliveryAvailable: true };
    if (contact) {
      await issueConfirmationToken({
        deps: toConfirmationDeps(deps),
        input: { workspaceId: deps.workspaceId, subscriptionId: subscription.id, recipientEmail: contact.email },
      });
    }
  } catch {
    // A contact-specific failure must not turn this acknowledgement into an enumeration oracle.
    // Keep diagnostics free of addresses, tokens and provider endpoints.
    console.error("[newsletter] confirmation request could not be processed; inspect mail configuration");
  }
  return { delivered: true, mailDeliveryAvailable: true };
}

export function buildNewsletterRegistrations(deps: NewsletterToolDeps, _surfaces?: AssistantSurfaceDeps): ToolRegistration[] {
  const handlers: Record<string, ToolHandler> = {
    newsletter_list_campaigns: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "admin.newsletter.read" }, { entityType: "newsletter_campaign" });

      await deps.newsletterReady;
      const status = typeof input.status === "string" ? input.status : undefined;
      const campaigns = await deps.newsletterCampaignRepo.list({ workspaceId: deps.workspaceId });
      const filtered = status ? campaigns.filter((campaign) => campaign.status === status) : campaigns;
      return { campaigns: filtered.map(toCampaignToolView) };
    },

    newsletter_get_campaign: async (ctx) => {
      const campaignId = requireString({ input: requireInputRecord({ input: ctx.input }), key: "campaignId" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "admin.newsletter.read" }, { entityType: "newsletter_campaign" });

      await deps.newsletterReady;
      const campaign = await deps.newsletterCampaignRepo.findById({ workspaceId: deps.workspaceId, id: campaignId });
      if (!campaign) throw new NewsletterCampaignNotFoundError(`campaign ${campaignId} was not found`);
      return { campaign: toCampaignToolView(campaign) };
    },

    newsletter_list_lists: async (ctx) => {
      requireInputRecord({ input: ctx.input });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "admin.newsletter.read" }, { entityType: "newsletter_list" });

      await deps.newsletterReady;
      const lists = await deps.newsletterListRepo.list({ workspaceId: deps.workspaceId });
      return { lists: lists.map(toListToolView) };
    },

    newsletter_list_subscriptions: async (ctx) => {
      const listId = requireString({ input: requireInputRecord({ input: ctx.input }), key: "listId" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "admin.newsletter.subscriber.read" }, { entityType: "newsletter_subscription" });

      await deps.newsletterReady;
      const subscriptions = await deps.newsletterSubscriptionRepo.list({ workspaceId: deps.workspaceId, listId });
      return { subscriptions: subscriptions.map(toSubscriptionToolView) };
    },

    newsletter_list_send_log: async (ctx) => {
      const campaignId = requireString({ input: requireInputRecord({ input: ctx.input }), key: "campaignId" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "admin.newsletter.subscriber.read" }, { entityType: "newsletter_campaign" });

      await deps.newsletterReady;
      const campaign = await deps.newsletterCampaignRepo.findById({ workspaceId: deps.workspaceId, id: campaignId });
      if (!campaign) throw new NewsletterCampaignNotFoundError(`campaign ${campaignId} was not found`);
      const rows = await deps.newsletterSendRepo.listByCampaign({ workspaceId: deps.workspaceId, campaignId });
      return { sends: rows.map(toSendLogToolView) };
    },

    newsletter_create_campaign: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "admin.newsletter.campaign.compose" }, { entityType: "newsletter_campaign" });

      await deps.newsletterReady;
      const { campaign } = await saveCampaign({
        deps: toCampaignWriteServiceDeps(deps),
        input: {
          workspaceId: deps.workspaceId,
          actorId: ctx.principal.id,
          fields: {
            subject: requireString({ input, key: "subject" }),
            preheader: typeof input.preheader === "string" ? input.preheader : null,
            fromName: requireString({ input, key: "fromName" }),
            fromEmail: requireString({ input, key: "fromEmail" }),
            replyTo: requireString({ input, key: "replyTo" }),
            listId: requireString({ input, key: "listId" }),
          },
        },
      });
      return { campaign: toCampaignToolView(campaign) };
    },

    newsletter_update_campaign: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      const campaignId = requireString({ input, key: "campaignId" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "admin.newsletter.campaign.compose" }, { entityType: "newsletter_campaign" });

      await deps.newsletterReady;
      const existing = await deps.newsletterCampaignRepo.findById({ workspaceId: deps.workspaceId, id: campaignId });
      if (!existing) throw new NewsletterCampaignNotFoundError(`campaign ${campaignId} was not found`);

      const { campaign } = await saveCampaign({
        deps: toCampaignWriteServiceDeps(deps),
        input: {
          workspaceId: deps.workspaceId,
          id: campaignId,
          actorId: ctx.principal.id,
          fields: {
            subject: typeof input.subject === "string" ? input.subject : existing.subject,
            preheader: typeof input.preheader === "string" ? input.preheader : existing.preheader,
            fromName: typeof input.fromName === "string" ? input.fromName : existing.fromName,
            fromEmail: typeof input.fromEmail === "string" ? input.fromEmail : existing.fromEmail,
            replyTo: typeof input.replyTo === "string" ? input.replyTo : existing.replyTo,
            listId: typeof input.listId === "string" ? input.listId : existing.listId,
          },
        },
      });
      return { campaign: toCampaignToolView(campaign) };
    },

    newsletter_cancel_campaign: async (ctx) => {
      const campaignId = requireString({ input: requireInputRecord({ input: ctx.input }), key: "campaignId" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "admin.newsletter.campaign.compose" }, { entityType: "newsletter_campaign" });

      await deps.newsletterReady;
      const { campaign } = await cancelCampaign({
        deps: toCampaignWriteServiceDeps(deps),
        input: { workspaceId: deps.workspaceId, id: campaignId, actorId: ctx.principal.id },
      });
      return { campaign: toCampaignToolView(campaign) };
    },

    newsletter_pause_campaign: async (ctx) => {
      const campaignId = requireString({ input: requireInputRecord({ input: ctx.input }), key: "campaignId" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "admin.newsletter.campaign.send" }, { entityType: "newsletter_campaign" });

      await deps.newsletterReady;
      const { campaign } = await pauseCampaign({ deps: toNewsletterSendPipelineDeps(deps), input: { workspaceId: deps.workspaceId, campaignId } });
      return { campaign: toCampaignToolView(campaign) };
    },

    newsletter_create_list: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "admin.newsletter.list.manage" }, { entityType: "newsletter_list" });

      await deps.newsletterReady;
      const { list } = await saveList({
        deps: toListsDeps(deps),
        input: { workspaceId: deps.workspaceId, name: requireString({ input, key: "name" }), slug: requireString({ input, key: "slug" }) },
      });
      return { list: toListToolView(list) };
    },

    newsletter_archive_list: async (ctx) => {
      const listId = requireString({ input: requireInputRecord({ input: ctx.input }), key: "listId" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "admin.newsletter.list.manage" }, { entityType: "newsletter_list" });

      await deps.newsletterReady;
      const { list } = await archiveList({ deps: toListsDeps(deps), input: { workspaceId: deps.workspaceId, id: listId } });
      return { list: toListToolView(list) };
    },

    newsletter_create_subscription: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      const listId = requireString({ input, key: "listId" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "admin.newsletter.subscriber.manage" }, { entityType: "newsletter_subscription" });

      await deps.newsletterReady;
      const source = typeof input.source === "string" ? (input.source as SubscriptionRow["source"]) : "admin";
      const { subscription } = await saveSubscription({
        deps: toSubscriptionsDeps(deps),
        input: { workspaceId: deps.workspaceId, listId, subscriberId: requireString({ input, key: "subscriberId" }), source },
      });
      return { subscription: toSubscriptionToolView(subscription) };
    },

    newsletter_remove_subscription: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      const listId = requireString({ input, key: "listId" });
      const subscriptionId = requireString({ input, key: "subscriptionId" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "admin.newsletter.subscriber.manage" }, { entityType: "newsletter_subscription" });

      await deps.newsletterReady;
      const existing = await deps.newsletterSubscriptionRepo.findById({ workspaceId: deps.workspaceId, id: subscriptionId });
      if (!existing || existing.listId !== listId) {
        throw new NewsletterSubscriptionNotFoundError(`subscription ${subscriptionId} was not found`);
      }

      const { subscription } = await unsubscribeSubscription({
        deps: toUnsubscribeSubscriptionDeps(deps),
        input: { workspaceId: deps.workspaceId, id: subscriptionId },
      });
      return { subscription: toSubscriptionToolView(subscription) };
    },

    newsletter_resend_confirmation: async (ctx) => {
      const subscriptionId = requireString({ input: requireInputRecord({ input: ctx.input }), key: "subscriptionId" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "admin.newsletter.subscriber.manage" }, { entityType: "newsletter_subscription" });

      await deps.newsletterReady;
      const mailOff = { delivered: false, mailDeliveryAvailable: false, note: "Email sending is not configured. Configure an SMTP credential or a mail adapter in Agent Plugins to send real email." };
      const driver = deps.mailer.capabilities().driver;
      if (driver === "console" || driver === "memory") return mailOff;
      if (ctx.signal.aborted) return { confirmed: false, reason: "abandoned", delivered: false, mailDeliveryAvailable: true };
      const currentDriver = deps.mailer.capabilities().driver;
      if (currentDriver === "console" || currentDriver === "memory") return mailOff;
      return resendPendingSubscriptionConfirmation({ deps, subscriptionId, signal: ctx.signal });
    },
  };

  // No `unwiredToolIds`: Newsletter wires its ENTIRE catalog, same tripwire discipline as Forms.
  return buildDomainRegistrations({ metadata: toolMetadata,
    domain: "newsletter",
    catalogModule: "newsletter/agent-tools.ts",
    catalog: CATALOG_BY_ID,
    // The whole map at once, so none of the 14 can be the one that forgot — see
    // `withModelFacingErrors`' own doc for why a per-call-site reshape is the defect this avoids.
    handlers: withModelFacingErrors({ handlers, rules: NEWSLETTER_MODEL_FACING_ERRORS }),
    derivedRisk: newsletterDerivedRisk,
  });
}

/**
 * Contributes Newsletter's AI tools to the assistant's catalog — called once by
 * `server/tool-catalog-manifest.ts`'s `installFirstPartyToolContributors()`, not by importing this
 * module. `assistant/tool-registrations.ts` no longer imports `buildNewsletterRegistrations`/
 * `newsletterDerivedRisk` by name; this is the seam that replaced it (2026-08-17 — see
 * `tool-contribution-registry.ts`'s header for why: this edge used to close a module cycle with
 * `assistant`, and a one-directional `newsletter -> assistant` registration call does not).
 */
export function contributeNewsletterTools(): ToolContributor {
  return { domain: "newsletter", build: buildNewsletterRegistrations, risk: newsletterDerivedRisk };
}

/**
 * @file `unsubscribe.ts` — `processUnsubscribe` (ADR-PIPE-011 C-015, REQ-14/15/30/32, INV-04/INV-09).
 *
 * `[internal-invariant]`: the fail-closed unsubscribe-token check — this feature's SECOND-highest-risk
 * contract after the Launch Gate. Verifies the `KeyringPort`-derived token against
 * `consentRevisionIdAtSubscribe` (INV-04: a token must never verify once `consentRevisionId` has
 * advanced past its mint-time value — e.g. a stale token from before a re-subscribe under a new
 * consent grant). Idempotent on a repeat of an already-processed token (EC-03) — but that narrow
 * carve-out is scoped to "this exact token, already at its own resulting terminal state," never a
 * general bypass of INV-04 (three separate tests keep the two concerns from being conflated, see
 * `__tests__/unsubscribe.test.ts`). Links are built ONLY from `OriginRegistryPort.canonicalOrigin`
 * (REQ-30/INV-09) — never a raw inbound `Host` header.
 */
import { timingSafeEqual } from "node:crypto";

import type { UUID } from "@jini-ai/core/primitives";
import type { KeyringPort } from "../webhooks/index.js";
import type { OriginRegistryPort } from "@jini-ai/http-kit/verified-origin";
import type { VerifiedOrigin } from "@jini-ai/http-kit/verified-origin";
import { NewsletterUnsubscribeTokenInvalidError } from "./errors.js";
import type { MembersConsentCapability, NewsletterSubscriptionRepoPort } from "./ports.js";
import type { SubscriptionRow } from "./types.js";

export interface UnsubscribeTokenClaims {
  workspaceId: UUID;
  subscriberId: UUID;
  listId: UUID;
  campaignId: UUID | null;
  /** The consent-revision id the token was minted against — compared to the subscription's CURRENT value (INV-04).
   *  `null` when the subscription recorded none (no consent capability bound); it must stay `null`
   *  rather than be coerced, or the comparison would reject the subscriber's own token. */
  consentRevisionId: string | null;
}

export interface UnsubscribeDeps {
  subscriptionRepo: NewsletterSubscriptionRepoPort;
  keyring: KeyringPort;
  originRegistry: OriginRegistryPort;
  consentCapability: MembersConsentCapability | null;
  clock: { nowIso(): string };
}

const derivationInfo = (claims: UnsubscribeTokenClaims): string =>
  `${claims.subscriberId}:${claims.listId}:${claims.consentRevisionId}:${claims.campaignId ?? ""}`;

/** Compose an absolute origin URL from a `VerifiedOrigin` — mirrors `redirects/phase-handler.ts`'s local `composeOriginUrl`. */
function composeOriginUrl(origin: VerifiedOrigin): string {
  const isDefaultPort =
    origin.port === undefined || (origin.scheme === "https" && origin.port === 443) || (origin.scheme === "http" && origin.port === 80);
  const authority = isDefaultPort ? origin.host : `${origin.host}:${origin.port}`;
  return `${origin.scheme}://${authority}${origin.basePath ?? ""}`;
}

async function signature(keyring: KeyringPort, claims: UnsubscribeTokenClaims): Promise<string> {
  const secret = await keyring.derive({
    workspaceId: claims.workspaceId,
    purpose: "newsletter-unsubscribe",
    info: derivationInfo(claims),
  });
  return Buffer.from(secret).toString("hex");
}

/** Build a signed, origin-anchored unsubscribe link (REQ-30/INV-09 — never a raw `Host` header). */
export async function buildUnsubscribeLink(required: {
  deps: UnsubscribeDeps;
  claims: UnsubscribeTokenClaims;
}): Promise<string> {
  const { deps, claims } = required;
  const sig = await signature(deps.keyring, claims);
  const token = `${Buffer.from(JSON.stringify(claims)).toString("base64url")}.${sig}`;
  const origin = await deps.originRegistry.canonicalOrigin({ workspaceId: claims.workspaceId });
  return `${composeOriginUrl(origin)}/newsletter/unsubscribe?token=${token}`;
}

/** Decodes the claims half of a token whose two-part shape `processUnsubscribe` already checked. */
function decodeClaims(encoded: string): UnsubscribeTokenClaims {
  try {
    return JSON.parse(Buffer.from(encoded, "base64url").toString("utf8")) as UnsubscribeTokenClaims;
  } catch {
    throw new NewsletterUnsubscribeTokenInvalidError("malformed unsubscribe token", "signature_invalid");
  }
}

/**
 * @complexity O(1).
 * @overallScore 100
 */
export async function processUnsubscribe(required: {
  deps: UnsubscribeDeps;
  input: { rawToken: string };
}): Promise<{ outcome: "unsubscribed" | "already-unsubscribed" }> {
  const { deps, input } = required;
  const [encoded, providedSig] = input.rawToken.split(".");
  if (!encoded || !providedSig) {
    throw new NewsletterUnsubscribeTokenInvalidError("malformed unsubscribe token", "signature_invalid");
  }
  const claims = decodeClaims(encoded);

  const expectedSig = await signature(deps.keyring, claims);
  if (!timingSafeEqualHex(expectedSig, providedSig)) {
    throw new NewsletterUnsubscribeTokenInvalidError("unsubscribe token signature is invalid", "signature_invalid");
  }

  const subscription = await deps.subscriptionRepo.findBySubscriberAndList({
    workspaceId: claims.workspaceId,
    listId: claims.listId,
    subscriberId: claims.subscriberId,
  });
  if (!subscription) {
    throw new NewsletterUnsubscribeTokenInvalidError("subscription was not found", "not_found");
  }

  // INV-04: fail-closed the moment the current consent revision has advanced past this token's
  // mint-time value (e.g. a re-subscribe under a new consent grant since this token was issued).
  if (subscription.consentRevisionIdAtSubscribe !== claims.consentRevisionId) {
    throw new NewsletterUnsubscribeTokenInvalidError(
      "unsubscribe token was minted against a stale consent revision",
      "consent_revision_mismatch"
    );
  }

  // EC-03: a repeat of an already-processed token (same still-matching revision) is idempotent
  // success — narrowly scoped to "this exact token, already at its own resulting terminal state,"
  // never a general bypass of the INV-04 check above (which already ran and passed).
  if (subscription.status === "unsubscribed") {
    return { outcome: "already-unsubscribed" };
  }

  if (deps.consentCapability) {
    await deps.consentCapability.revoke({ workspaceId: claims.workspaceId, subscriberId: claims.subscriberId });
  }

  const now = deps.clock.nowIso();
  const updated: SubscriptionRow = { ...subscription, status: "unsubscribed", unsubscribedAt: now, updatedAt: now };
  await deps.subscriptionRepo.save(updated);
  return { outcome: "unsubscribed" };
}

/** Constant-time hex comparison (defense in depth against signature timing attacks). */
function timingSafeEqualHex(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  return timingSafeEqual(Buffer.from(a, "utf8"), Buffer.from(b, "utf8"));
}

import type { ArtifactStorePort } from "@jini-ai/devops/deploy";

import type { DeployTargetCredential } from "../deployments/deploy-targets/types.js";

import type { LoadedObjectStoreRegistry } from "./registry.js";

/**
 * @file Which object-store provider delivers backup shares: any registered provider that can also
 * hand out a single-object artifact store (today the bundled `s3_compatible`), instead of one
 * hard-coded deploy target id. The site's media choice wins when it qualifies, so media and shares
 * use one provider (and one saved connection); otherwise the first qualifying one in registry order.
 * A provider qualifies only once its saved connection resolves and passes its optional artifact
 * credential check, so an installed but unconnected
 * store never hides a connected one behind it. Revoke names the share's saved provider and resolves
 * only that one, so a store connected later can never take over (or block) another store's delete.
 */

/** A provider's artifact capability as the share path calls it (the deploy-target module ABI). */
export interface ArtifactStoreCapable {
  /** Optional provider-owned readiness check for artifact-specific companion credentials. */
  acceptsArtifactCredential?(required: { readonly credential: unknown }, optional?: Record<string, never>): boolean;
  createArtifactStore(required: { readonly credential: DeployTargetCredential; readonly config: Record<string, never>; readonly kit: unknown }): ArtifactStorePort & {
    /** Non-secret identity of the backing store, when the provider knows it better than the host does. */
    readonly binding?: string;
  };
}

/**
 * @param required.resolveCredential The provider's saved connection, or `undefined` when it has none.
 * @param optional.savedProvider A share's recorded provider (its hyphenated connection id): only that
 *   provider is considered.
 * @returns The first capable provider (preferred first, then registry order) whose connection
 *   resolves and passes the provider's artifact check, with that credential; `undefined` when none qualifies.
 * @complexity O(n) registered providers, one credential lookup per capable provider until a hit.
 */
export async function selectArtifactStoreProvider<C>(
  required: { readonly loaded: LoadedObjectStoreRegistry; readonly preferredId: string; readonly resolveCredential: (required: { readonly id: string }) => Promise<C | undefined> },
  optional: { readonly savedProvider?: string } = {}
): Promise<{ readonly id: string; readonly provider: ArtifactStoreCapable; readonly credential: C } | undefined> {
  const capable = required.loaded.registry.list().filter((entry) => typeof (entry.provider as Partial<ArtifactStoreCapable>).createArtifactStore === "function"
    && (optional.savedProvider === undefined || artifactStoreTarget(entry.id) === optional.savedProvider));
  const ordered = [...capable.filter((entry) => entry.id === required.preferredId), ...capable.filter((entry) => entry.id !== required.preferredId)];
  for (const entry of ordered) {
    const credential = await required.resolveCredential({ id: entry.id });
    if (credential === undefined) continue;
    const provider = entry.provider as unknown as ArtifactStoreCapable;
    if (provider.acceptsArtifactCredential?.({ credential }) === false) continue;
    return { id: entry.id, provider, credential };
  }
  return undefined;
}

/** Provider ids use underscores; the saved connection (and a share's recorded provider) is the hyphenated target id. */
export function artifactStoreTarget(id: string): string {
  return id.replace(/_/g, "-");
}

/**
 * What revoke must match before deleting: a new default connection must never turn revocation into
 * deletion in another bucket. Non-secret storage coordinates bind, so credentials may rotate for the
 * same store; a provider that names its own store (e.g. a token-scoped one) supplies that instead.
 * @complexity O(1).
 */
export function artifactStoreBinding(required: { readonly store: { readonly binding?: string }; readonly credential: Readonly<Record<string, unknown>> }): string {
  const { store, credential } = required;
  return store.binding ?? JSON.stringify([credential.bucket, credential.region, credential.endpoint ?? "", credential.publicUrl]);
}

import { maskNonRenderableRegions } from "@jini-ai/cms/widgets/markers";

/**
 * @file Finds page markup that is hidden until a script reveals it — and so is hidden for good on a
 * Tovu page.
 *
 * Why: markup copied from another site keeps the source's scroll-reveal start state (Webflow and
 * Framer write `style="opacity:0"`, AOS/SAL/WOW.js add attributes or classes, hand-rolled sites ship
 * `.reveal { opacity: 0 }`), but never the script that flips it, because page HTML runs no source
 * script. The result is invisible or washed-out content that looks like a styling bug (Luvira
 * import, 2026-10-08). The page tools still write the markup — a hidden element can be deliberate —
 * and return these findings as a warning so the model fixes them on its next turn.
 *
 * PURE: string in, findings out. A tolerant scan over markup the assistant just wrote, not an HTML
 * parser; comments and raw-text elements are masked first through the shared widget-marker mask.
 */

/** Findings listed before the rest are summarised as a count. */
export const MAX_REVEAL_FINDINGS = 10;

const START_TAG = /<([a-z][a-z0-9-]*)\b((?:[^>"']|"[^"]*"|'[^']*')*)>/gi;
const ATTRIBUTE = /([^\s=/>"']+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>"']+)))?/g;
/** Exactly zero opacity or `visibility: hidden` — `opacity: 0.5` is a design choice, not hidden. */
const HIDING_DECLARATION = /(?:^|;)\s*(opacity\s*:\s*0(?:\.0+)?%?|visibility\s*:\s*hidden)\s*(?:!important\s*)?(?=;|$)/i;
/** Attributes only scroll-reveal libraries write (AOS, SAL, ScrollReveal). */
const REVEAL_ATTRIBUTES: readonly string[] = ["data-aos", "data-sal", "data-sr-id"];
/** Classes only scroll-reveal libraries need (WOW.js hides `.wow` until it runs). */
const REVEAL_CLASSES: readonly string[] = ["wow"];
/** A hidden `<style>` rule is reported only for reveal-named selectors: a hover overlay at opacity 0 is ordinary. */
const REVEAL_SELECTOR = /reveal|fade|animate|aos|wow|in-?view|appear|scroll|sal-/i;
const HTML_COMMENT = /<!--[\s\S]*?-->/g;
const STYLE_BLOCK = /<style\b[^>]*>([\s\S]*?)<\/style\s*>/gi;
const CSS_COMMENT = /\/\*[\s\S]*?\*\//g;
const KEYFRAMES_BLOCK = /@(?:-[a-z]+-)?keyframes[^{]*\{(?:[^{}]*\{[^{}]*\})*[^{}]*\}/gi;
const CSS_RULE = /([^{}]+)\{([^{}]*)\}/g;

function readAttributes(raw: string): Map<string, string> {
  const attributes = new Map<string, string>();
  for (const match of raw.matchAll(ATTRIBUTE)) attributes.set(match[1]!.toLowerCase(), match[2] ?? match[3] ?? match[4] ?? "");
  return attributes;
}

function hidingDeclaration(declarations: string): string | undefined {
  return HIDING_DECLARATION.exec(declarations.trim())?.[1];
}

/** The one reason this element is hidden until a script runs, or `undefined`. */
function elementReason(attributes: Map<string, string>): string | undefined {
  const inline = hidingDeclaration(attributes.get("style") ?? "");
  if (inline !== undefined) return `inline style ${inline}`;
  const attribute = REVEAL_ATTRIBUTES.find((name) => attributes.has(name));
  if (attribute !== undefined) return `${attribute} (a scroll-reveal library attribute)`;
  const classes = (attributes.get("class") ?? "").split(/\s+/);
  const revealClass = REVEAL_CLASSES.find((name) => classes.includes(name));
  return revealClass === undefined ? undefined : `class "${revealClass}" (a scroll-reveal library class)`;
}

function elementFindings(html: string): string[] {
  const findings: string[] = [];
  for (const match of maskNonRenderableRegions({ html }).matchAll(START_TAG)) {
    const attributes = readAttributes(match[2]!);
    const reason = elementReason(attributes);
    if (reason === undefined) continue;
    const className = attributes.get("class");
    findings.push(`<${match[1]!.toLowerCase()}${className ? ` class="${className}"` : ""}> has ${reason}`);
  }
  return findings;
}

function styleRuleFindings(html: string): string[] {
  const findings: string[] = [];
  for (const block of html.replace(HTML_COMMENT, "").matchAll(STYLE_BLOCK)) {
    const css = block[1]!.replace(CSS_COMMENT, "").replace(KEYFRAMES_BLOCK, "");
    for (const rule of css.matchAll(CSS_RULE)) {
      const selector = rule[1]!.trim().replace(/\s+/g, " ");
      const hidden = hidingDeclaration(rule[2]!);
      if (hidden !== undefined && !selector.startsWith("@") && REVEAL_SELECTOR.test(selector)) findings.push(`<style> rule "${selector}" sets ${hidden}`);
    }
  }
  return findings;
}

/**
 * Lists every element (and every reveal-named `<style>` rule) that stays hidden without the source
 * site's reveal script, element findings in document order, then style rules.
 * @param required.html - Page HTML or a region fragment.
 * @returns Human-readable findings, at most {@link MAX_REVEAL_FINDINGS} plus a trailing "...and N more."; empty when clean.
 * @complexity O(n) in the markup length.
 */
export function findScriptRevealedContent({ html }: { html: string }, _optional: {} = {}): readonly string[] {
  const findings = [...elementFindings(html), ...styleRuleFindings(html)];
  if (findings.length <= MAX_REVEAL_FINDINGS) return findings;
  return [...findings.slice(0, MAX_REVEAL_FINDINGS), `...and ${findings.length - MAX_REVEAL_FINDINGS} more.`];
}

/**
 * The model-facing warning for a write whose markup has findings, or `undefined` when it has none.
 * @complexity O(n) in the markup length.
 */
export function describeScriptRevealedContent({ html }: { html: string }, _optional: {} = {}): string | undefined {
  const findings = findScriptRevealedContent({ html });
  if (findings.length === 0) return undefined;
  return (
    "Written, but some of this markup stays invisible: it is hidden until a scroll-reveal script runs, and no " +
    "page script on this site reveals it. Remove the hiding style, attribute or class (or set the element's " +
    `visible state) and write it again: ${findings.join("; ")}`
  );
}

import type { PluginEmbedDiagnostic } from "../agent-plugins/exports/diagnostics.js";
import { nowIso as clockNowIso } from "@jini-ai/core/primitives";
import type { Kysely, Selectable, Updateable } from "kysely";

import { type Clock as ClockPort } from "@jini-ai/core/primitives";
import { assertEntityLive, type OutboxPort } from "@jini-ai/cms/core";

import type { ContentDatabase, PostsTable } from "../../platform/db/content-database.generated.js";
import type { ContentKernel } from "../../platform/db/content-kernel.js";
import { normalizeEmbedMarkerQuoting } from "@jini-ai/cms/widgets/markers";
import { extractHtmlEntryRefs } from "../../contracts/core/entry-refs/extractor.js";
import type { EntryRefsRepoPort } from "../../contracts/core/entry-refs/ports.js";
// Not from `../post/index.js`: that barrel deliberately never re-exports Pages-specific things and,
// symmetrically, `SYSTEM_ACTOR_ID` is a generic actor fallback this file needs directly rather than
// through the barrel (`index.ts`'s own header explains the one-way rule; nothing forbids importing
// FROM `post.ts` here, only re-exporting Pages things there).
import { SYSTEM_ACTOR_ID, type PostKind, type PostRepoPort, type PostStatus } from "../post/post.js";
import { announcePendingGoLive } from "../post/go-live.js";

/**
 * @file SPEC-047/ADR-056 REQ-4 — Tovu's `PagesHtmlDocumentStorePort`
 * (`read(): Promise<string>` / `write(html: string): Promise<void>`) over
 * an `"html"`-format Page row in the shared `posts` table. One Kysely query body for every dialect
 * the storage kernel drives (storage plan §4, ADR-066); `html-document-store.sqlite.ts` keeps the
 * `PagesHtmlDocumentStore` name as the thin subclass the composition root builds from the db handle.
 *
 * Pages uses Jini's HTML scan and pure edit functions, not its `HtmlDocumentStore` or EditTarget.
 * The tool handlers keep the read → compute → write(html) flow here so another read cannot
 * recapture a newer version between computing an edit and its compare-and-set write (CIC-1).
 * Jini's store takes `write({ html })`; this Tovu port deliberately keeps `write(html)`.
 *
 * Bypasses `PostRepoPort`/`SqlitePostRepo`/`createPost`/`updatePost` entirely, on purpose (ADR-056
 * Decision 4 & CIC-3): this store is the ONLY writer of `body_html`/`bodyFormat: "html"` anywhere in
 * this codebase — the general Post/Page CRUD chokepoint (`post.ts`'s `resolveBodyFields`) can never
 * produce that shape, so there is exactly one place a `bodyFormat: "html"` row is ever written, and
 * this is it.
 *
 * CIC-1 (ADR-056) — the reason this file exists rather than a three-line `SELECT`/`UPDATE` pair: two
 * admin sessions editing the same page concurrently, or a retried tool call racing a still-in-flight
 * one, are two separate callers layered over the same row. `write()` is conditioned on the `version`
 * captured by the MATCHING `read()` (compare-and-set), never an unconditional overwrite — a stale
 * writer is rejected with {@link PageConcurrentEditError}, not silently applied on top of content it
 * never saw. See `pages-html-document-store.test.ts`'s interleaving test for the failure mode this
 * prevents (a naive read-splice-write not only loses the first writer's edit, it can splice the
 * second writer's content into the WRONG byte offset if the first edit changed the document's length
 * anywhere before the second writer's target region).
 *
 * Relationship to `updatePost`'s `expectedVersion` (2026-09-07, fable arch audit §4.15): the audit
 * read one `posts.version` column written under three different concurrency contracts and asked
 * whether this store should take a client-stated `expectedVersion` too. It should not, and the
 * difference is not an inconsistency. `updatePost`'s basis comes from a client that loaded the row
 * in an earlier request and states what it believes it is editing, so the guard there is opt-in
 * (a caller that sends nothing gets last-write-wins) and its rejection is a 409 the client must
 * reconcile. Here there is no earlier request and no client to state anything: the basis is the
 * version captured by the `read()` in THIS turn, which is what makes the guard mandatory rather
 * than opt-in — `write()` without a prior `read()` throws rather than falling back to an
 * unconditional overwrite. What the audit was actually pointing at — an arm writing this column
 * with NO predicate at all — was `routes/pages/update.ts` (C02) and `features/seo`'s
 * `setEntrySeoOverrides` (SEO-01); both now write under one, so every writer of `posts.version`
 * is version-predicated. The two remaining mechanisms differ only in where the basis comes from.
 */

/** The query handle a kernel `run` body receives. */
type ContentQueries = Kysely<ContentDatabase>;

export class PageNotFoundError extends Error {}

/**
 * Refuses {@link SqlPagesHtmlDocumentStore.ensureHtmlFormat} on a row that is not `kind: "page"`.
 *
 * Distinct from {@link PageNotFoundError} on purpose, and it is the one place in this file that
 * does NOT follow the "kind-mismatch is indistinguishable from not-found" convention: the other
 * methods hide a Post's existence because they are read/write paths an agent can aim at any id,
 * whereas this one is only ever reached from a route that has already resolved the row through the
 * pages surface. Conflating "this Post cannot become an html Page" with "no such page" here would
 * hide a genuine caller bug (a Post id routed into the Pages editor) behind a 404 that reads as
 * ordinary missing data.
 */
export class PageKindMismatchError extends Error {}

/**
 * CIC-1's rejection — surfaced when `write()`'s `UPDATE ... WHERE version = <captured>` affects zero
 * rows, meaning the row's version moved since the matching `read()`. Never a silent no-op or a
 * fallback overwrite (ADR-056 Decision 2's own wording).
 */
export class PageConcurrentEditError extends Error {}

export interface PagesHtmlDocumentStoreDeps {
  validatePluginEmbeds?: (input: { workspaceId: string; html: string }) => Promise<readonly PluginEmbedDiagnostic[]>;
  /** The content database: one Kysely query body for every dialect (storage plan §4, ADR-066). */
  kernel: ContentKernel;
  /** Each surface selects its own kinds; Pages defaults to page only. */
  allowedKinds?: ReadonlySet<PostKind>;
  clock: ClockPort;
  /**
   * SPEC-047 Slice 3 — when supplied, every successful {@link SqlPagesHtmlDocumentStore.write}/
   * {@link SqlPagesHtmlDocumentStore.ensureHtmlFormat} (the seeding branch only — see that method's own
   * doc) re-extracts this Page's `data-embed-type` references
   * (`core/entry-refs/extractor.ts`'s `extractHtmlEntryRefs`) and replaces its `entry_refs` rows, so
   * "deleting a widget/form silently breaks a page" is covered for html Pages the same way it
   * already is for TipTap `widgetEmbed` nodes.
   *
   * Optional, not required, so every pre-existing construction site (this class's own certified
   * `html-document-store.test.ts`, and any other caller built before this dependency existed) keeps
   * compiling and behaving unchanged — omitting it simply means this store never touches
   * `entry_refs`, not a broken build. Real composition roots (`server/deps.ts`/`server/app.ts`)
   * supply the real/in-memory `entryRefsRepo` they already construct for widgets.
   *
   * Disclosed gap: this write and the `entry_refs` replace are two separate statements, not one
   * transaction — unlike `entries`' own write chokepoint (INV-06's same-transaction guarantee),
   * `PagesHtmlDocumentStore` has no transaction wrapper to hook into (CIC-3's whole point is that it
   * bypasses that chokepoint). A crash between the two, or another writer's `write()` landing in
   * between, can leave `entry_refs` briefly stale — acceptable because the index is derived and
   * rebuildable by definition (`EntryRefsRepoPort`'s own doc), not because the race is impossible.
   */
  entryRefsRepo?: EntryRefsRepoPort;
  /**
   * Fix plan 2026-09-24 row 14 (S1) — when supplied, every successful {@link
   * SqlPagesHtmlDocumentStore.write}/{@link SqlPagesHtmlDocumentStore.ensureHtmlFormat} appends the row's
   * post-write state to the `post_revisions` ledger `createPost`/`updatePost`/`deletePost` already
   * write to (`post.ts`'s `PostRepoPort.appendRevision`), so an html Page's edit history is
   * recoverable the same way a Post's already is — CIC-3 keeps this store the sole WRITER of
   * `bodyFormat: "html"`, but it does not have to be the sole thing that forgets what came before.
   *
   * Optional, not required, for the identical reason {@link entryRefsRepo} is: every pre-existing
   * construction site keeps compiling and behaving unchanged when this is omitted — the ledger
   * append simply does not happen, not a broken build. Real composition roots (`server/deps.ts`)
   * supply the same `postRepo` they already construct.
   *
   * A `Pick`, not the whole port: this store must never gain the ability to `save`/`softDelete`/etc.
   * a Post through the back door — appending to the ledger and reading the row it just wrote are the
   * only two capabilities it needs.
   */
  revisions?: Pick<PostRepoPort, "findById" | "appendRevision" | "transaction" | "listRevisions">;
  /**
   * When supplied, every successful content write of a PUBLISHED page enqueues the same
   * `entry.updated` event `post.ts` emits for a published edit. Without it a bespoke HTML edit was
   * invisible to every event consumer: site search kept serving the removed text, because its
   * backfill watermark is complete after the first pass and never rescans.
   *
   * Review fix 2026-10-21 — also, a write that lands on a scheduled page whose `publishAt`
   * has passed since its last save, but which the go-live sweep (`post/go-live.ts`) has not
   * announced yet, enqueues that page's go-live `entry.published` in the same transaction. This
   * write moves `updated_at` past `publish_at`, after which the sweep no longer sees the row, so
   * without it the announcement would be lost for good. Optional for the same reason as the two
   * above; real composition roots supply the outbox `updatePost` already writes to.
   */
  outbox?: Pick<OutboxPort, "enqueue">;
}

/** The `posts` columns a go-live catch-up reads off a write's own SELECT. */
const GO_LIVE_COLUMNS = ["id", "workspace_id", "kind", "status", "publish_at", "updated_at", "deleted_at"] as const;
type GoLiveColumns = Pick<Selectable<PostsTable>, (typeof GO_LIVE_COLUMNS)[number]>;

/** Scopes one store instance to one Page row — mirrors every other adapter in this feature area
 * being workspace-scoped, so a store built for workspace A can never touch workspace B's row even
 * if handed a colliding `postId` (defense in depth; ids are UUIDs and collision is not the expected
 * threat model, but the scoping costs nothing and matches house convention). */
export interface PagesHtmlDocumentStoreScope {
  workspaceId: string;
  postId: string;
  /**
   * Fix plan 2026-09-24 row 14 (S1) — the `post_revisions.actor_id` a {@link
   * PagesHtmlDocumentStoreDeps.revisions} append attributes this Page's edit to. Defaults to
   * {@link SYSTEM_ACTOR_ID}, the same ledger fallback `post.ts` itself uses for an omitted caller,
   * rather than being required — most construction sites predate this field and a route that never
   * passes one should not have to.
   */
  actorId?: string;
}

/**
 * The capability a Page's bespoke-HTML body is read and written through, as an interface rather
 * than the concrete class.
 *
 * Two implementations satisfy it: {@link SqlPagesHtmlDocumentStore} over the real `content.db`, and
 * `html-document-store.memory.ts`'s `PostRepoPort`-backed twin for `app.ts`'s hermetic root. A
 * class type would not work here even if there were only one — TypeScript compares classes with
 * private fields nominally, so a structurally identical second implementation is not assignable to
 * the first.
 *
 * `read()` deliberately returns only the string; the version an implementation conditions its
 * write on is captured on the instance rather than handed back with the body. Handlers use Jini's
 * pure edits over that body without another store read.
 */
export interface PagesHtmlDocumentStorePort {
  /** Safe warnings from the last validated write, for authenticated authoring surfaces. */
  embedWarnings?(): readonly PluginEmbedDiagnostic[];
  /** Births an `"html"`-format Page, or no-ops if the row already is one. */
  ensureHtmlFormat(seedHtml: string): Promise<void>;
  read(): Promise<string>;
  write(html: string): Promise<void>;
  /**
   * The row `version` captured by the most recent {@link read}/{@link ensureHtmlFormat} — the exact
   * value the next {@link write}'s compare-and-set will condition on — or `null` before either has
   * run.
   *
   * Added 2026-09-09 so a caller-stated `expectedVersion` (the agent tools' optimistic-concurrency
   * basis, mirroring `content_post_update`'s) can be compared against the version the write is
   * ACTUALLY conditioned on, with nothing able to move in between. Comparing against a version read
   * separately — through `postRepo`, say — would leave a window where a concurrent writer lands
   * between the check and this store's own `read()`, and the write would then be conditioned on the
   * intruder's version and silently clobber it. That is precisely the failure a version guard exists
   * to prevent, so the basis and the predicate must be the same number.
   *
   * This is Tovu's concurrency contract, independent of Jini's `HtmlDocumentStore`; pure region
   * edits never read the store or advance this basis.
   */
  capturedVersion(): number | null;
}

/**
 * Builds a store for one Page, with the `content.db` handle and clock already closed over.
 *
 * A factory rather than a store, for the same reason `RouteDeps.chatHistory` is one: composition
 * owns the db handle so no route ever holds it, which is what makes an unscoped `WHERE id = ?`
 * unwritable from a route rather than merely against convention. Every instance is bound to exactly
 * one `(workspaceId, postId)` pair at construction.
 */
export type PagesHtmlDocumentStoreFactory = (
  scope: PagesHtmlDocumentStoreScope,
  options?: { allowedKinds?: ReadonlySet<PostKind> },
) => PagesHtmlDocumentStorePort;

/**
 * Tovu's page HTML store over one `"html"`-format Page row (SPEC-047/ADR-056 REQ-4).
 *
 * Stateful by necessity, not by convenience: this port's `read()` returns only a string (no version),
 * so the row's `version` at the time of the most recent `read()`
 * is captured on the instance and is what the next `write()` conditions its compare-and-set on
 * (CIC-1). Pages handlers read once, compute through Jini's pure functions, then write, with no
 * other store read landing in between — so "condition on the most recently read version" is
 * exactly "condition on the version the content
 * being written was computed from," which is the property CIC-1 requires.
 */
export class SqlPagesHtmlDocumentStore implements PagesHtmlDocumentStorePort {
  private lastReadVersion: number | null = null;
  private pluginWarnings: readonly PluginEmbedDiagnostic[] = [];

  embedWarnings(): readonly PluginEmbedDiagnostic[] { return this.pluginWarnings; }

  private async validatePluginEmbeds(input: { html: string }, _options = {}): Promise<void> {
    this.pluginWarnings = await this.deps.validatePluginEmbeds?.({ workspaceId: this.scope.workspaceId, html: input.html }) ?? [];
  }
  private readonly allowedKinds: ReadonlySet<PostKind>;

  private readonly scope: PagesHtmlDocumentStoreScope;
  private readonly deps: PagesHtmlDocumentStoreDeps;
  constructor(
    scope: PagesHtmlDocumentStoreScope,
    deps: PagesHtmlDocumentStoreDeps
  ) {
    this.scope = scope;
    this.deps = deps;
    this.allowedKinds = deps.allowedKinds ?? new Set(["page"]);
  }

  /**
   * @see PagesHtmlDocumentStorePort.capturedVersion
   * @complexity O(1).
   */
  capturedVersion(): number | null {
    return this.lastReadVersion;
  }

  /** `posts` narrowed to this store's one `(workspaceId, postId)` row. */
  private thisRow(db: ContentQueries) {
    return db.selectFrom("posts").where("workspace_id", "=", this.scope.workspaceId).where("id", "=", this.scope.postId);
  }

  /**
   * The compare-and-set UPDATE both write paths share: this row, at exactly `guard.version`, and
   * (for {@link write}) still an `"html"` row outside the Trash.
   *
   * @returns The number of rows changed — 0 or 1.
   * @complexity O(1) — one indexed, version-conditioned row update.
   */
  /**
   * Runs one write path's statements as one transaction: through `revisions.transaction` when the
   * ledger is wired (the transaction its appends already join), else the kernel's own — so the
   * go-live catch-up commits or rolls back with the row even without a ledger (2026-10-21).
   *
   * @complexity O(1) besides `fn`.
   */
  private inTransaction<T>(fn: () => Promise<T>): Promise<T> {
    return this.deps.revisions ? this.deps.revisions.transaction(fn) : this.deps.kernel.transaction(fn);
  }

  /**
   * The go-live catch-up of {@link PagesHtmlDocumentStoreDeps.outbox}: `row` as it stood BEFORE this
   * write, `nowIso` the write's instant. Call it inside the write's transaction, after the UPDATE
   * matched. A no-op without an outbox.
   *
   * @complexity O(1) — at most one enqueue.
   */
  private async catchUpGoLive(row: GoLiveColumns, nowIso: string): Promise<void> {
    if (!this.deps.outbox) return;
    const post = {
      id: row.id,
      workspaceId: row.workspace_id,
      kind: row.kind as PostKind,
      status: row.status as PostStatus,
      publishAt: row.publish_at,
      updatedAt: row.updated_at,
      deletedAt: row.deleted_at,
    };
    await announcePendingGoLive({ outbox: this.deps.outbox, post, nowIso });
  }

  private async updateThisRow(set: Updateable<PostsTable>, guard: { version: number; liveHtmlOnly?: boolean }): Promise<number> {
    const result = await this.deps.kernel.run((db) => {
      let update = db
        .updateTable("posts")
        .set(set)
        .where("workspace_id", "=", this.scope.workspaceId)
        .where("id", "=", this.scope.postId)
        .where("version", "=", guard.version)
        .where("kind", "in", [...this.allowedKinds]);
      if (guard.liveHtmlOnly) update = update.where("body_format", "=", "html").where("deleted_at", "is", null);
      return update.executeTakeFirst();
    });
    return Number(result.numUpdatedRows);
  }

  /**
   * Reads the current `body_html`, capturing this row's `version` on the instance for the next
   * {@link write} to condition its compare-and-set on.
   *
   * A row that does not exist, or that exists but is not `bodyFormat: "html"`, 404s identically —
   * the same "kind-mismatch is indistinguishable from not-found" convention
   * `pages/get-by-id.ts` already applies, so this store never leaks whether a `doc`-format row with
   * this id exists.
   *
   * @throws {PageNotFoundError} If no `"html"`-format row with this id exists in this workspace.
   * @throws {EntityNotLiveError} If the row is in the Trash (`@jini-ai/cms/core`, S5 web-high fix
   * plan 2026-09-24). Checked BEFORE the `bodyFormat` mismatch below, so a trashed row reports Trash
   * even when its body is `"doc"`-format — the caller needs to know the row is trashed either way.
   * @complexity O(1) — one indexed row lookup.
   * @overallScore 100
   */
  async read(): Promise<string> {
    const row = await this.deps.kernel.run((db) =>
      this.thisRow(db).select(["kind", "body_html", "body_format", "version", "deleted_at"]).limit(1).executeTakeFirst()
    );

    if (!row) throw new PageNotFoundError(`page '${this.scope.postId}' was not found`);
    assertEntityLive({ entityType: "page", entityId: this.scope.postId, state: row.deleted_at ? "trashed" : "live" });
    if (!this.allowedKinds.has(row.kind as PostKind) || row.body_format !== "html" || row.body_html === null) {
      throw new PageNotFoundError(`page '${this.scope.postId}' was not found`);
    }

    this.lastReadVersion = row.version;
    return row.body_html;
  }

  /**
   * Births an `"html"`-format Page: flips a `"doc"`-format row to `"html"` and seeds `body_html`
   * with `seedHtml`. Idempotent — a row already in `"html"` format is left untouched (content
   * included) and only has its `version` captured, so the caller can follow with
   * {@link read}/{@link write} unconditionally.
   *
   * **This is the only path by which an `"html"`-format row ever comes into existence.** It exists
   * because the two halves of the design lock each other out otherwise: `post.ts`'s
   * `resolveBodyFields()` is hardcoded to `"doc"` and can never construct an html row (ADR-056
   * CIC-3, deliberate), while {@link read} refuses a row whose `bodyHtml` is null — so without this
   * method there is no first write. Keeping it here rather than loosening `createPost` is what
   * preserves CIC-3 literally: `createPost`/`updatePost` still cannot produce this shape, and this
   * class remains the sole writer of it.
   *
   * **The conversion is one-way and drops `body_json`** (D-2's explicitly warned, one-way format
   * conversion). The CHECK constraint on `posts` permits exactly one populated body column per
   * format, so flipping to `"html"` requires nulling `body_json` in the same statement — any TipTap
   * content on that row is gone and is not recoverable from this table. Callers must not offer this
   * on a Page with authored `doc` content without warning the operator first; today the only caller
   * is the Pages editor acting on a freshly created, empty Page.
   *
   * @throws {PageNotFoundError} If no row with this id exists in this workspace.
   * @throws {EntityNotLiveError} If the row is in the Trash (`@jini-ai/cms/core`, S5 web-high fix
   * plan 2026-09-24). Checked BEFORE the `kind` mismatch below, matching {@link read}'s ordering.
   * @throws {PageKindMismatchError} If the row exists but is `kind: "post"` — Posts are Tiptap, full
   * stop (D-1), and no Post may be converted to bespoke HTML through this or any other path.
   * @complexity O(1) — one indexed row lookup plus, on a `doc` row, one indexed row update.
   */
  async ensureHtmlFormat(authoredSeedHtml: string): Promise<void> {
    // Canvas-serialized `data-embed-config="{&quot;…}"` is stored in the readable single-quoted form.
    const seedHtml = normalizeEmbedMarkerQuoting({ html: authoredSeedHtml });
    const row = await this.deps.kernel.run((db) =>
      this.thisRow(db).select([...GO_LIVE_COLUMNS, "body_format", "version"]).limit(1).executeTakeFirst()
    );

    if (!row) throw new PageNotFoundError(`page '${this.scope.postId}' was not found`);
    assertEntityLive({ entityType: "page", entityId: this.scope.postId, state: row.deleted_at ? "trashed" : "live" });
    // The factory scopes this shared writer to the calling surface's own document kinds.
    if (!this.allowedKinds.has(row.kind as PostKind)) {
      throw new PageKindMismatchError(`'${this.scope.postId}' is not an allowed HTML document kind`);
    }

    if (row.body_format === "html") {
      // Already born. Capture the version so a following `write()` has something to condition on,
      // and leave the content alone — re-seeding here would silently discard the page's real body
      // every time the editor opened it.
      this.lastReadVersion = row.version;
      return;
    }

    await this.validatePluginEmbeds({ html: seedHtml });
    const nextVersion = row.version + 1;
    const updatedAt = clockNowIso({ clock: this.deps.clock });

    const runConversion = async () => {
      // S1 (fix plan 2026-09-24 row 14) — the PRE-conversion snapshot. `bodyJson` is about to be
      // nulled by the UPDATE below (D-2's one-way conversion), so this is the ledger's only chance
      // ever to record what a legacy doc Page's body was. Skipped when a row at this exact `seq`
      // already exists — `updatePost` ledgers every real edit itself, so a Page with prior edit
      // history already has this snapshot and a second row at the same `seq` would be a redundant
      // duplicate, not a recovery of anything new.
      if (this.deps.revisions) {
        const existing = await this.deps.revisions.listRevisions({
          workspaceId: this.scope.workspaceId,
          postId: this.scope.postId,
        });
        if (!existing.some((revision) => revision.seq === row.version)) {
          await this.appendRevision(row.version, updatedAt);
        }
      }

      const changes = await this.updateThisRow(
        {
          body_format: "html",
          body_html: seedHtml,
          // Required by the table's CHECK constraint, not incidental — see this method's doc.
          body_json: null,
          version: nextVersion,
          updated_at: updatedAt,
        },
        // Same compare-and-set discipline as `write()` (CIC-1): if another writer moved this row
        // between the SELECT above and here, this update matches nothing rather than clobbering.
        { version: row.version }
      );

      // Reject inside the transaction so the pre-conversion snapshot rolls back with a stale CAS.
      if (changes === 0) {
        throw new PageConcurrentEditError(
          `page '${this.scope.postId}' was edited elsewhere while it was being converted to HTML — retry`
        );
      }

      // The POST-conversion snapshot — the row's first ever html-format state.
      await this.appendRevision(nextVersion, updatedAt);
      await this.emitUpdated({ status: row.status, version: nextVersion, occurredAt: updatedAt });
      await this.catchUpGoLive(row, updatedAt);
    };

    await this.inTransaction(runConversion);

    this.lastReadVersion = nextVersion;
    await this.reindexEntryRefs(seedHtml);
  }

  /**
   * Enqueues `entry.updated` for a content change of a published page (see
   * {@link PagesHtmlDocumentStoreDeps.outbox}); the same envelope and idempotent id shape as
   * `post.ts`'s status-transition emitter. A draft or scheduled page emits nothing, exactly as a
   * `post.ts` edit of a non-published row does: no public-facing content changed.
   * @complexity O(1) — one outbox insert.
   */
  private async emitUpdated(required: { status: string; version: number; occurredAt: string }): Promise<void> {
    if (!this.deps.outbox) return;
    await this.deps.outbox.enqueue({
      id: `${this.scope.postId}-content.saved-${required.version}`, name: "content.saved",
      occurredAt: required.occurredAt, aggregateId: this.scope.postId, workspaceId: this.scope.workspaceId,
      payload: { entryId: this.scope.postId, contentType: "page", actorId: this.scope.actorId, source: "service" },
    });
    if (required.status !== "published") return;
    await this.deps.outbox.enqueue({
      id: `${this.scope.postId}-entry.updated-${required.version}`,
      name: "entry.updated",
      occurredAt: required.occurredAt,
      aggregateId: this.scope.postId,
      workspaceId: this.scope.workspaceId,
      payload: { entryId: this.scope.postId, contentType: "page" },
    });
  }

  /**
   * S1 (fix plan 2026-09-24 row 14) — appends one `post_revisions` row capturing this row's state AS
   * OF RIGHT NOW under `seq`, when {@link PagesHtmlDocumentStoreDeps.revisions} was supplied. A no-op
   * (not an error) when it wasn't, matching {@link reindexEntryRefs}'s own optional-dependency shape.
   *
   * Always re-reads the row through `revisions.findById` rather than accepting a caller-built
   * snapshot — the two write paths that call this ({@link write}'s post-write state and {@link
   * ensureHtmlFormat}'s pre- AND post-conversion states) each need a DIFFERENT moment's row, and
   * "read whatever is there right now" is the one implementation that is correct for all three
   * without the caller having to hand-assemble a `PostRecord`.
   *
   * @complexity O(1) — one indexed lookup plus one ledger insert.
   */
  private async appendRevision(seq: number, recordedAt: string): Promise<void> {
    if (!this.deps.revisions) return;
    const row = await this.deps.revisions.findById({ workspaceId: this.scope.workspaceId, id: this.scope.postId });
    // Cannot happen on either call site's success path (each call follows a write that just matched
    // this exact row) — a defensive no-op, not a silent swallow of a real failure.
    if (!row) return;
    await this.deps.revisions.appendRevision({
      postId: this.scope.postId,
      workspaceId: this.scope.workspaceId,
      seq,
      op: "update",
      stateJson: row,
      actorId: this.scope.actorId ?? SYSTEM_ACTOR_ID,
      recordedAt,
    });
  }

  /**
   * SPEC-047 Slice 3 — re-extracts and replaces this Page's `entry_refs` rows for `html`, when
   * {@link PagesHtmlDocumentStoreDeps.entryRefsRepo} was supplied. A no-op (not an error) when it
   * wasn't — see that field's own doc for why this dependency stays optional.
   *
   * @complexity O(n) over `html`'s length (delegates to `extractHtmlEntryRefs`'s own O(n) scan) plus
   * one `replaceForSource` write.
   * @overallScore 100
   */
  private async reindexEntryRefs(html: string): Promise<void> {
    if (!this.deps.entryRefsRepo) return;
    const refs = extractHtmlEntryRefs({
      workspaceId: this.scope.workspaceId,
      sourceEntryId: this.scope.postId,
      html,
    });
    await this.deps.entryRefsRepo.replaceForSource({
      workspaceId: this.scope.workspaceId,
      sourceEntryId: this.scope.postId,
      refs,
    });
  }

  /**
   * Writes a new `body_html`, conditioned on the `version` captured by the most recent {@link read}
   * (CIC-1's compare-and-set). On success, `version` is incremented and the instance's captured
   * version advances to match — so a second `write()` on this same instance (no intervening `read()`
   * call) is conditioned on the version this store itself just produced, not a stale one.
   * Identical normalized HTML leaves the row, ledger and reference index untouched, after checking
   * the current row still matches the captured version and is live HTML.
   *
   * @throws {Error} If called before any {@link read} — there is no captured version to condition on.
   * @throws {EntityNotLiveError} If the row was trashed since the matching `read()`
   * (`@jini-ai/cms/core`, S5 web-high fix plan 2026-09-24) — disambiguated on the rejection path.
   * @throws {PageConcurrentEditError} If zero rows matched the compare-and-set for any other reason —
   * the row's version moved since the matching `read()` (another writer committed first). The caller
   * must re-`read()` and retry; this method never falls back to an unconditional overwrite.
   * @complexity O(n) time for n HTML characters; one indexed lookup, at most one CAS update and
   * revision append, plus the optional reference scan. No persistence writes for unchanged HTML.
   * @overallScore 100
   */
  async write(authoredHtml: string): Promise<void> {
    // Canvas-serialized `data-embed-config="{&quot;…}"` is stored in the readable single-quoted form.
    const html = normalizeEmbedMarkerQuoting({ html: authoredHtml });
    if (this.lastReadVersion === null) {
      throw new Error("PagesHtmlDocumentStore.write() called before read() — there is no version to condition the write on");
    }
    const expectedVersion = this.lastReadVersion;
    // Preserve this call's read basis across asynchronous plugin validation (CIC-1).
    await this.validatePluginEmbeds({ html });
    const nextVersion = expectedVersion + 1;
    const updatedAt = clockNowIso({ clock: this.deps.clock });

    const runWrite = async () => {
      const current = await this.deps.kernel.run((db) =>
        this.thisRow(db).select([...GO_LIVE_COLUMNS, "body_html", "body_format", "version"]).limit(1).executeTakeFirst()
      );
      // Check freshness before equality: matching HTML must never hide a stale captured version.
      if (!current || !this.allowedKinds.has(current.kind as PostKind) || current.version !== expectedVersion || current.body_format !== "html" || current.deleted_at) return 0;
      if (current.body_html === html) return null;
      const changes = await this.updateThisRow(
        { body_html: html, version: nextVersion, updated_at: updatedAt },
        { version: expectedVersion, liveHtmlOnly: true }
      );
      // S1 (fix plan 2026-09-24 row 14) — only on the row this UPDATE actually matched. A 0-row
      // result below throws before any append lands (and, inside `revisions.transaction()`, rolls
      // this back too — though there is nothing to roll back on this path, unlike `ensureHtmlFormat`'s
      // two-append converting branch).
      if (changes > 0) {
        await this.appendRevision(nextVersion, updatedAt);
        await this.emitUpdated({ status: current.status, version: nextVersion, occurredAt: updatedAt });
        await this.catchUpGoLive(current, updatedAt);
      }
      return changes;
    };

    const changes = await this.inTransaction(runWrite);
    if (changes === null) return;

    if (changes === 0) {
      // Disambiguate: the row can have moved off this exact predicate either because it was trashed
      // (a state the model must be told about explicitly) or for the ordinary concurrent-edit reason
      // this class has always guarded against. A trashed row does not get to masquerade as "someone
      // else edited it" — the recovery action is different (restore from Trash vs. re-read and retry).
      const stillHere = await this.deps.kernel.run((db) => this.thisRow(db).select("deleted_at").limit(1).executeTakeFirst());
      const deletedAt = stillHere?.deleted_at;
      if (deletedAt) {
        assertEntityLive({ entityType: "page", entityId: this.scope.postId, state: "trashed" });
      }
      throw new PageConcurrentEditError(
        `page '${this.scope.postId}' was edited elsewhere since this turn started — re-read and retry`
      );
    }

    this.lastReadVersion = nextVersion;
    await this.reindexEntryRefs(html);
  }
}

import type { ChatDeleteSurfaceDeps } from "#src/contracts/core/chat-delete-grant";
import { toolMetadata } from '../../contracts/core/tool-metadata/permanent-delete.js';
import { adaptLegacyAuthorize } from "@jini-ai/cms/core";
