// Disclosed cross-domain read, same shape `agent-tools.ts`'s header already accepts for this
// package: `ext.{pluginId}.*` is written ONLY on a `posts` row (see `post.ts`'s own `ext` field
// doc — "content.entry.beforeSave hook-merge step... immediately before the single
// deps.repo.save() call"), so a tool that reads a plugin's stored output back has nowhere else to
// read it FROM. Read-only (`PostRepoPort.findById`/`PostRecord`/`PostNotFoundError` only) — this
// file never imports anything that could write a post.
import { PostNotFoundError, type PostRecord, type PostRepoPort } from "../post/index.js";

/**
 * @file Projects each ENABLED plugin-runtime plugin's own declared `fields[]` (manifest.ts,
 * SPEC-005 REQ-06) into one real, `search_tools`-discoverable tool per plugin — the fix for the
 * 2026-08-26 registration-gap audit (`ADS-memory/reports/2026-08-26-plugin-discoverability-audit.md`):
 * a live, valid, tier-3 Word Count plugin was computing and storing a real per-post word count on
 * every save, yet no agent-callable tool anywhere ever exposed it, so `search_tools` correctly
 * returned nothing for "compute word count or reading time statistics for post content" — a
 * registration gap, not a ranking or selection miss.
 *
 * ---------------------------------------------------------------------------
 * Why THIS shape and not the other two the dispatch offered
 * ---------------------------------------------------------------------------
 * Historical field-read decision: the 2026-10-09 owner dispatch now authorizes executable tools
 * through this SAME registrar; these reasons still explain why field-read tools retain their
 * separate contract. The generic executable registration owner is Jini plugins/host.
 *
 * (1) "Plugins declare invocable tools" was rejected as the bigger, contract-changing option: v1's
 * entire capability vocabulary (`Jini/packages/plugins/src/host/manifest.ts`'s `VALID_CAPABILITIES`/`VALID_HOOKS`) has no notion of
 * "expose a callable function" at all, and inventing one — arbitrary handler code a plugin author
 * supplies, executed inside the agent's tool-call path — is a real security/sandboxing question this
 * dispatch's time-box cannot responsibly answer.
 * (3) "Discoverable but not invocable" (a catalog entry that only explains a capability exists) was
 * rejected because the owner's own repro ("is there a way to count words in posts?") needed a real
 * ANSWER, not a pointer — a tool the agent cannot actually call would leave it exactly where it
 * started, manually counting words with Bash.
 * This file is (2): a plugin's already-written, already-durable `ext.{pluginId}.*` output becomes
 * READABLE through one native, read-only tool per plugin — no new execution surface, no new
 * capability vocabulary, just a read path onto data that already exists (`post.ts`'s `ext` field).
 *
 * ---------------------------------------------------------------------------
 * One tool PER PLUGIN, not per field (mirrors `agent-plugins/tool-registrations.ts`'s own
 * one-tool-per-plugin collapse, same rationale: crowding `search_tools`' result slots one field at a
 * time does not scale, and a plugin's fields are typically one cohesive capability anyway).
 * ---------------------------------------------------------------------------
 * Tool id: `plugin_capability_<pluginId>` (hyphens folded to underscores, matching
 * `agent_plugin_<pluginId>`'s own scheme) — deliberately NOT `plugins_*` (already
 * `plugins_list`/`plugins_set_enabled`, the MANAGEMENT tools this is not) and NOT `plugin_*` bare
 * (would read as belonging to the Agent Plugins family). Checked against every existing catalog's
 * ids (`grep -rn 'name: "[a-z_]*"' src/**\/agent-tools.ts src/**\/*tool-registrations.ts`) before
 * choosing it — no collision today. `@jini-ai/core`'s `createToolRegistry().register()` throws on a
 * duplicate id at registration time regardless (verified by reading `tool-registry.ts`), so a future
 * collision fails loudly at boot rather than silently shadowing a native tool — this module does not
 * need to (and does not) reimplement that guard.
 *
 * ---------------------------------------------------------------------------
 * The description text IS the fix — folds each field's own manifest-declared, action-oriented
 * `description` (see `Jini/packages/plugins/src/host/manifest.ts`'s `PluginManifestFieldDecl.description`, added alongside this
 * file) into one tool description. A plugin with no authored field description still gets a tool —
 * degraded to a generic, weaker description ({@link genericFieldDescription}) rather than no tool at
 * all, the same graceful-degradation shape `agent-plugins/tool-registrations.ts`'s
 * `extractFallbackSummary` already uses for a skill with no frontmatter.
 *
 * ---------------------------------------------------------------------------
 * Activation gate — the OPPOSITE default from Agent Plugins, and that is a real, disclosed decision
 * ---------------------------------------------------------------------------
 * `features/agent-plugins/activation.ts` treats an absent activation record as ACTIVE ("presence
 * implies consent"). Plugin-runtime's own projection (`admin-response.ts`: `enabled: activation?.
 * enabled ?? false`) is the opposite: absent means DISABLED. This loader follows plugin-runtime's own
 * convention, not the Agent Plugins one it sits next to — a disabled plugin's `content.entry.
 * beforeSave` hook never fires (`Jini/packages/plugins/src/host/hook-registry.ts`), so its `ext` data (if any survives from when it
 * was last enabled, INV-03) is not being kept fresh. Advertising that as a live capability would be a
 * new bug this file exists to avoid, not fix. Only `status: "valid"` AND `activation.enabled === true`
 * plugins are ever projected into a tool source — verified by both an enabled-plugin test and a
 * disabled-plugin (absent-activation) test in this file's own unit suite.
 *
 * ---------------------------------------------------------------------------
 * Revocation — the activation gate runs AGAIN on every call (t91 F1.2, 2026-09-16)
 * ---------------------------------------------------------------------------
 * The loader above runs once, at daemon boot, and `@jini-ai/core`'s `ToolRegistry` is append-only, so
 * a plugin disabled, quarantined or uninstalled afterwards used to keep a callable tool until restart.
 * Every registration built here therefore carries a `ToolPolicy` that re-reads the activation row
 * before the handler can be reached (`withActivationGate`), mirroring `agent-plugins/
 * tool-registrations.ts`'s REVOCATION note: a refused call ends as `denied` in the daemon audit, and a
 * read that throws also denies (and is logged). Boot filter and per-call gate share one predicate,
 * `isPluginEnabledInWorkspace`, so they cannot drift. The tool stays LISTED until restart; enabling a
 * plugin that was disabled at boot still needs a restart, because there is no registration to re-admit.
 *
 * ---------------------------------------------------------------------------
 * Fresh results for Tier-2 plugins (AW-7 Tier 2, 2026-10-04)
 * ---------------------------------------------------------------------------
 * A stored `ext` value is only as fresh as the post's last save, so "analyze this page" used to answer
 * with whatever the plugin computed then. A tier-2 plugin with a `content.entry.beforeSave` filter
 * ({@link PluginCapabilityToolSource.runsFresh}) now runs again on the post as stored, through the
 * optional `previewPluginBeforeSave` port: the same hook-registry preview the admin editor's
 * "Analyze now" uses, so the code runs in a fresh worker and nothing is saved or counted toward
 * quarantine. Still ONE tool per plugin (no second "analyze" tool competing in `search_tools`).
 * Without the port, or when this process has not attached the plugin, it reads the stored values as
 * before. Tier-3 plugins keep reading stored values: their filter runs in-process, and this change
 * was scoped to the worker-isolated tier. `ExtPatch` is scalar-only, so a plugin stores structured
 * output (content-analyzer's `report`) as a JSON string; {@link decodeFieldValue} hands it back
 * parsed instead of as JSON inside JSON.
 *
 * Architectural role:
 * `features/plugin-runtime` domain declaration, alongside (not replacing) `agent-tools.ts`/
 * `tool-registrations.ts`'s static `plugins_list`/`plugins_set_enabled` pair — this file's tool ids
 * are dynamic (learned only by awaiting `discoverPlugins()` + `pluginActivationRepo`), the same
 * reason `agent-plugins/tool-registrations.ts` is not a synchronous `ToolContributor` either. Called
 * once from `agent-daemon-server.ts`'s `start()`, immediately before `buildToolCatalogQuery` snapshots
 * the registry into a one-shot FTS index — see that call site's own comment for why placement there
 * (not before) makes a registered-late tool invisible to `search_tools`.
 */

/** `plugin_capability_<pluginId>` — see this file's header, "Tool id scheme". The derivation lives in
 *  `Jini/packages/plugins/src/host/plugin-claims.ts` (2026-10-04) so the conflict detector claims exactly the id registered here. */

/** The ONE definition of "this plugin's capability tool may exist / may run": this workspace's activation
 *  row says `enabled: true`. Absent, disabled, quarantined (saved `enabled: false`) and uninstalled (every
 *  row deleted) all answer false. Shared by the boot filter and the per-call gate — see this file's header,
 *  "Revocation". @complexity one activation-row read. */
async function isPluginEnabledInWorkspace(repo: PluginActivationRepoPort, workspaceId: string, pluginId: string): Promise<boolean> {
  const activation = await repo.getActivation({ workspaceId, pluginId });
  return activation?.enabled === true;
}

/** One resolved, already-namespace-parsed `ext.{pluginId}.*` field this tool can read back. */
export interface PluginCapabilityFieldSource {
  /** The full manifest-declared path, e.g. `"ext.word-count.count"`. */
  readonly path: string;
  /** The key this field is stored under inside `post.ext[pluginId]` — `path` with the
   *  `ext.{pluginId}.` prefix stripped (e.g. `"count"`). Namespacing is already enforced by
   *  `Jini/packages/plugins/src/host/manifest.ts`'s `validateField` before a record can ever reach `status: "valid"`, so this is a
   *  plain slice, not a re-validation. */
  readonly fieldKey: string;
  readonly type: PluginManifestFieldDecl["type"];
  /** Action-oriented, human-authored text when the manifest supplies one; otherwise
   *  {@link genericFieldDescription}'s weaker fallback. Never empty. */
  readonly description: string;
}

/** One enabled plugin's tool-ready source — everything {@link buildPluginCapabilityToolRegistrations}
 *  needs to mint one real `ToolRegistration`, with nothing left for the handler to (re)compute from
 *  raw discovery/activation state at call time. */
export interface PluginCapabilityToolSource {
  readonly id: string;
  readonly pluginId: string;
  readonly pluginName: string;
  readonly description: string;
  readonly fields: readonly PluginCapabilityFieldSource[];
  /** A tier-2 plugin with a `content.entry.beforeSave` filter: each call runs that filter on the
   *  stored post through `PluginCapabilityToolDeps.previewPluginBeforeSave` — see this file's header,
   *  "Fresh results for Tier-2 plugins". */
  readonly runsFresh: boolean;
}

/** Whether this plugin's tool computes a fresh result instead of reading the stored one — see this
 *  file's header, "Fresh results for Tier-2 plugins". */
function runsFreshFor(manifest: PluginManifest): boolean {
  return manifest.tier === "tier-2" && manifest.hooks.includes("content.entry.beforeSave");
}

/** Fallback for a field whose manifest declares no `description` (see this file's header,
 *  "description text IS the fix") — weaker (a noun-phrase, not an action), but still a usable,
 *  non-empty tool description rather than no tool at all. */
function genericFieldDescription(pluginName: string, field: PluginManifestFieldDecl): string {
  return `The '${pluginName}' plugin's '${field.path}' value (${field.type}), written whenever a post is saved while this plugin is enabled.`;
}

/**
 * Resolves one valid manifest's declared fields into tool-ready sources — `expectedPrefix` mirrors
 * `manifest.ts`'s own `validateFields` derivation exactly, so a field this function accepts is
 * guaranteed already-validated namespacing, never a fresh assumption this file invents.
 *
 * @complexity O(fields.length) — one manifest's own declared array.
 */
function buildFieldSources(manifest: PluginManifest): readonly PluginCapabilityFieldSource[] {
  const expectedPrefix = `ext.${manifest.id}.`;
  return manifest.fields
    .filter((field) => field.path.startsWith(expectedPrefix) && field.path.length > expectedPrefix.length)
    .map((field) => ({
      path: field.path,
      fieldKey: field.path.slice(expectedPrefix.length),
      type: field.type,
      description: field.description ?? genericFieldDescription(manifest.name, field),
    }));
}

/**
 * Builds this plugin tool's model-facing description — an operator SEARCH TARGET, not a card blurb
 * (mirrors `agent-plugins/tool-registrations.ts`'s `buildPluginToolDescription` doc on the same
 * point). Leads with an imperative action clause, folds in every field's own description text (the
 * actual indexed vocabulary a real query needs to match), and states the `postId` precondition and
 * the "no data yet" outcome up front so a model reading only this description already knows how to
 * call it and what an empty result means.
 */
function buildCapabilityToolDescription(manifest: PluginManifest, fields: readonly PluginCapabilityFieldSource[]): string {
  const identity = readPluginIdentity({ manifest: manifest as unknown as Readonly<Record<string, unknown>>, name: manifest.id, namespace: "tovu" });
  const fieldText = fields.map((field) => field.description).join(" ") + ` Plugin discovery: ${[identity.id, ...identity.keywords, ...identity.provides].join(" ")}.`;
  if (runsFreshFor(manifest)) {
    return (
      `Runs the installed '${manifest.name}' plugin on one existing post or page right now and returns its fresh result ` +
      `(nothing is saved). ${fieldText} Requires an existing postId — call content_post_search, content_post_list, or ` +
      `content_post_get first if you do not already have one. JSON-valued fields (such as a report) come back already parsed.`
    );
  }
  return (
    `Reads content metrics and other data the installed '${manifest.name}' plugin has already computed and stored ` +
    `for one existing post or page. ${fieldText} Requires an existing postId — call content_post_search, ` +
    `content_post_list, or content_post_get first if you do not already have one. Returns null for any field this ` +
    `plugin has not written yet for that post (for example, one never saved since '${manifest.name}' was enabled), ` +
    `plus a note explaining why, rather than failing the call.`
  );
}

/**
 * Loads every ENABLED, valid plugin-runtime plugin that declares at least one field, resolved into
 * one tool-ready source per plugin. See this file's header, "Activation gate", for why "enabled"
 * here means `activation.enabled === true` — the opposite default from Agent Plugins.
 *
 * @complexity O(p) plugin-discovery calls times one `pluginActivationRepo.getActivation` each,
 * dominated by `discoverPlugins()`'s own I/O (unchanged, not re-read per plugin).
 */
export async function loadEnabledPluginCapabilityToolSources(deps: {
  readonly workspaceId: string;
  readonly discoverPlugins: () => Promise<readonly PluginDiscoveryRecord[]>;
  readonly pluginActivationRepo: PluginActivationRepoPort;
}): Promise<readonly PluginCapabilityToolSource[]> {
  const discovery = await deps.discoverPlugins();
  const sources: PluginCapabilityToolSource[] = [];

  for (const record of discovery) {
    if (record.status !== "valid" || !record.manifest) continue;
    if (record.manifest.fields.length === 0) continue; // nothing this plugin's tool could ever return

    if (!(await isPluginEnabledInWorkspace(deps.pluginActivationRepo, deps.workspaceId, record.id))) continue; // disabled (or never activated) — see this file's header

    const fields = buildFieldSources(record.manifest);
    if (fields.length === 0) continue;

    sources.push({
      id: capabilityToolIdFor({ pluginId: record.id }),
      pluginId: record.id,
      pluginName: record.manifest.name,
      description: buildCapabilityToolDescription(record.manifest, fields),
      fields,
      runsFresh: runsFreshFor(record.manifest),
    });
  }

  return sources;
}

/** This module's own risk classification — every capability tool is a pure read of an already-saved
 *  post's already-computed `ext` bag: no domain call, no write path. Mirrors
 *  `agent-plugins/tool-registrations.ts`'s identical `"none"` classification for the same reason. */
export function pluginCapabilityToolDerivedRisk(sources: readonly PluginCapabilityToolSource[]): DerivedRiskByToolId {
  return new Map(sources.map((source) => [source.id, "none" as const]));
}

function buildCapabilityInputSchema(): Record<string, unknown> {
  return {
    type: "object",
    additionalProperties: false,
    required: ["postId"],
    properties: {
      postId: {
        type: "string",
        minLength: 1,
        description:
          "The post/page id to read this plugin's computed field(s) for, as returned by content_post_search, " +
          "content_post_list, or content_post_get.",
      },
    },
  };
}

/** Reads one plugin's stored field bag off an already-loaded post, defensively — `post.ext` is
 *  typed as a generic `JsonObject` (see `post.ts`'s own field doc), so this narrows with `isRecord`
 *  at each level rather than casting, and treats any unexpected shape the same as "not yet written"
 *  (`undefined`, then `null` + note) rather than throwing on data this handler does not own the shape of. */
function readStoredFieldBag(source: PluginCapabilityToolSource, post: PostRecord): Record<string, unknown> | undefined {
  const extension = { value: post.ext };
  const candidate = { value: isRecord(extension) ? extension.value[source.pluginId] : undefined };
  return isRecord(candidate) ? candidate.value : undefined;
}

/** A string field holding a JSON object or array comes back parsed (see this file's header, "Fresh
 *  results for Tier-2 plugins"); every other value, including a string that only looks like JSON,
 *  is returned exactly as written. @complexity O(value length). */
function decodeFieldValue(value: unknown): unknown {
  if (typeof value !== "string" || !/^\s*[[{]/.test(value)) return value;
  try {
    return JSON.parse(value) as unknown;
  } catch {
    return value;
  }
}

/** Projects one plugin's field bag — stored, or fresh from the preview port (`computedNow`) — onto
 *  its declared fields, adding the "not computed yet" note when none of them has a value. */
function buildCapabilityToolResult(
  source: PluginCapabilityToolSource,
  post: PostRecord,
  bag: { values: Record<string, unknown> | undefined; computedNow: boolean },
): Record<string, unknown> {
  const pluginBag = bag.values;
  const fields: Record<string, unknown> = {};
  let anyComputed = false;
  for (const field of source.fields) {
    const value = pluginBag ? pluginBag[field.fieldKey] : undefined;
    fields[field.fieldKey] = value === undefined ? null : decodeFieldValue(value);
    if (value !== undefined) anyComputed = true;
  }

  return {
    postId: post.id,
    pluginId: source.pluginId,
    computedNow: bag.computedNow,
    fields,
    ...(anyComputed
      ? {}
      : {
          note:
            `'${source.pluginName}' has not computed any field for this post yet — it will be written the next ` +
            `time this post is saved while the plugin stays enabled.`,
        }),
  };
}

export interface PluginCapabilityToolDeps {
  readonly pluginContributions?: PluginContributionRegistry;
  readonly executablePluginToolRegistry?: ToolRegistry;
  readonly authorize: AuthorizeFn;
  readonly workspaceId: string;
  readonly postRepo: PostRepoPort;
  /** Re-read on EVERY call by each registration's policy — see this file's header, "Revocation". */
  readonly pluginActivationRepo: PluginActivationRepoPort;
  /** Runs ONE attached plugin's beforeSave filter on a draft without saving — the composition
   *  root's `previewPluginBeforeSave` binding (`HookRegistry.previewBeforeSave`). Omitted ⇒ every
   *  tool reads stored values. See this file's header, "Fresh results for Tier-2 plugins". */
  readonly previewPluginBeforeSave?: PluginBeforeSavePreview;
}

/** The field bag one call answers with: a fresh preview for a {@link PluginCapabilityToolSource.runsFresh}
 *  source when the port is injected and this process has the plugin attached, otherwise the stored one.
 *  The draft is the post exactly as stored — the same fields `post.ts` hands the filter on an update.
 *  @throws {ToolInputError} the fresh run failed; the cause stays on the error, the model sees fixed text.
 *  @complexity one post-draft preview (a worker round trip for tier-2) or none. */
async function resolveFieldBag(
  source: PluginCapabilityToolSource,
  post: PostRecord,
  deps: PluginCapabilityToolDeps,
): Promise<{ values: Record<string, unknown> | undefined; computedNow: boolean }> {
  const preview = source.runsFresh ? deps.previewPluginBeforeSave : undefined;
  const fresh = preview
    ? await preview(source.pluginId, {
        id: post.id,
        workspaceId: post.workspaceId,
        title: post.title,
        slug: post.slug,
        status: post.status,
        bodyJson: post.bodyJson,
        ext: (post.ext ?? {}) as Readonly<Record<string, Readonly<Record<string, unknown>>>>,
      }).catch((error: unknown) => {
        throw new ToolInputError(
          {
            message: `PLUGIN_HOOK_FAILED: '${source.pluginName}' could not run on post '${post.id}' just now, so there is no fresh result. Nothing was saved; its stored values are unchanged.`,
          },
          { cause: error },
        );
      })
    : null;
  return fresh ? { values: fresh, computedNow: true } : { values: readStoredFieldBag(source, post), computedNow: false };
}

/** One source's catalog entry. `content.read`, like `content_post_get` — see `buildPluginCapabilityToolRegistrations`. */
function capabilityCatalogEntry(source: PluginCapabilityToolSource): AgentToolDefinition {
  return {
    name: source.id,
    description: source.description,
    sideEffects: "none",
    authorization: { permission: "content.read" },
    inputSchema: buildCapabilityInputSchema(),
  };
}

/** One source's handler. @complexity one permission check, one post read, and at most one fresh preview. */
function capabilityToolHandler(source: PluginCapabilityToolSource, deps: PluginCapabilityToolDeps): ToolHandler {
  return async (ctx) => {
    const input = requireInputRecord({ input: ctx.input });
    const postId = requireString({ input: input, key: "postId" });
    await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "content.read" }, { entityType: "post", entityId: postId });

    const post = await deps.postRepo.findById({ workspaceId: deps.workspaceId, id: postId });
    if (!post) {
      throw new PostNotFoundError(`post '${postId}' was not found`);
    }
    return buildCapabilityToolResult(source, post, await resolveFieldBag(source, post, deps));
  };
}

/** Whether `pluginId` may run right now. A read that throws DENIES and is logged, rather than surfacing as a
 *  failed execution whose cause the daemon redacts. @complexity one activation-row read. */
async function isCapabilityCallableNow(deps: PluginCapabilityToolDeps, pluginId: string): Promise<boolean> {
  try {
    return await isPluginEnabledInWorkspace(deps.pluginActivationRepo, deps.workspaceId, pluginId);
  } catch (error) {
    console.warn(
      `[plugin-runtime] '${pluginId}': capability tool call denied — its activation record could not be read (${error instanceof Error ? error.message : String(error)})`,
    );
    return false;
  }
}

/**
 * Wraps one registration's policy so the plugin's CURRENT activation is re-read before its handler can be
 * reached, then defers to the policy `buildDomainRegistrations` attached — the same shape and reason as
 * `agent-plugins/tool-registrations.ts`'s `withToolGate` (a future kit policy must not be silently dropped).
 * @complexity O(1) plus one activation-row read per call.
 */
function withActivationGate(registration: ToolRegistration, deps: PluginCapabilityToolDeps, pluginId: string): ToolRegistration {
  const inner = registration.policy;
  return {
    ...registration,
    policy: {
      async authorize(authCtx) {
        if (!(await isCapabilityCallableNow(deps, pluginId))) return "deny";
        return inner.authorize(authCtx);
      },
    },
  };
}

/**
 * Turns already-resolved plugin capability sources into real `ToolRegistration`s — pure and
 * synchronous, unlike {@link loadEnabledPluginCapabilityToolSources}, so this half is unit-tested
 * without touching activation/discovery I/O. Uses the same `buildDomainRegistrations` gate every
 * other domain's `tool-registrations.ts` uses (catalog/risk cross-check, `inputSchema` presence,
 * drift tripwire) — not a parallel mechanism.
 *
 * Permission: `content.read`, the same permission `content_post_get` itself requires — this tool
 * reads a post's already-persisted data, nothing a plugin-specific permission would meaningfully
 * narrow further (mirrors `content_post_get`'s own inline `requireToolPermission` call exactly,
 * including the `entityType`/`entityId` pair so a per-post authorization rule can still apply).
 *
 * Every registration carries the per-call activation gate (`withActivationGate`) — see this file's
 * header, "Revocation". Built one source at a time so the owning plugin id is in scope for every
 * registration the kit returns: there is no id-to-plugin lookup that could miss and leave a tool
 * ungated. The build stays synchronous and touches no I/O; the gate reads only when a call is
 * authorized.
 */
export function buildPluginCapabilityToolRegistrations(
  sources: readonly PluginCapabilityToolSource[],
  deps: PluginCapabilityToolDeps,
): ToolRegistration[] {
  return sources.flatMap((source) =>
    buildDomainRegistrations({ metadata: toolMetadata,
      domain: "plugin-capability",
      catalogModule: "features/plugin-runtime/capability-tool-registrations.ts",
      catalog: indexCatalogById({ catalog: [capabilityCatalogEntry(source)] }),
      handlers: { [source.id]: capabilityToolHandler(source, deps) },
      derivedRisk: pluginCapabilityToolDerivedRisk([source]),
    }).map((registration) => withExtensionApprovalPolicy({ registration: withActivationGate(registration, deps, source.pluginId), family: 'plugin-capability-result' })),
  );
}

/**
 * Composition-root entry point: loads every enabled, field-declaring plugin for one workspace and
 * registers each as a real tool directly on `registry` — the same `registry.register(registration)`
 * call `agent-daemon-server.ts`'s own loops make for every other contributor's output, just awaited
 * first (mirrors `registerInstalledAgentPluginTools`'s identical shape and rationale).
 *
 * @throws Whatever `registry.register()` itself throws on an id collision (`@jini-ai/core`'s
 * `createToolRegistry()` throws synchronously — see this file's header) — deliberately not caught
 * here; the caller's own fail-open `try/catch` (matching `registerInstalledAgentPluginTools`'s and
 * `registerInstalledSkillTools`'s call sites in `agent-daemon-server.ts`) is where that is handled,
 * so all three optional registrars degrade identically on failure.
 *
 * Registers with the per-call activation gate, so a tool this puts into the daemon's registry is
 * refused the moment its plugin is disabled, quarantined or uninstalled.
 */
export async function registerEnabledPluginCapabilityTools(
  registry: { register: (registration: ToolRegistration) => void; has?: ToolRegistry["has"]; list?: ToolRegistry["list"] },
  deps: PluginCapabilityToolDeps & {
    readonly discoverPlugins: () => Promise<readonly PluginDiscoveryRecord[]>;
  },
): Promise<void> {
  const sources = await loadEnabledPluginCapabilityToolSources(deps);
  for (const registration of buildPluginCapabilityToolRegistrations(sources, deps)) {
    registry.register(registration);
  }
  if (deps.pluginContributions && (deps.executablePluginToolRegistry || (registry.has && registry.list))) {
    attachPluginContributionTools({ ...executablePluginToolPorts({ deps, contributions: deps.pluginContributions }), registry: deps.executablePluginToolRegistry ?? registry as ToolRegistry });
  }
}

/** Product authorization and approval inputs for Jini's executable registration owner. */
function executablePluginToolPorts({ deps, contributions }: { deps: PluginCapabilityToolDeps; contributions: PluginContributionRegistry }): PluginToolContributionPorts {
  // The caller passes the bound registry it just checked, so there is no unbound case to refuse here.
  return {
    contributions,
    isEnabled: async ({ pluginId }) => (await deps.pluginActivationRepo.getActivation({ workspaceId: deps.workspaceId, pluginId }))?.enabled === true,
    resolveAuth: async ({ pluginId, principalId }) => {
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId, permission: 'admin.plugins.enable' }, { entityType: 'plugin', entityId: pluginId });
      return { access: 'admin', principalId, workspaceId: deps.workspaceId };
    },
    // In-process arbitrary code can leave this site. Its prose cannot self-classify it as read-only.
    // The assistant decides when to invoke it; only permanent-delete tools require confirmation.
    metadata: { approval: { class: 'publish', confirmation: 'direct' } },
  };
}

/**
 * @file A plugin's manifest-declared content types (`tovu.plugin.json` → `contentTypes`) — parse,
 * plan against what the site already has, and apply through the ONE core write path
 * (`registerContentType`, behind {@link DeclaredContentTypePorts}). AW-7 Tier 1, 2026-10-04.
 *
 * Why this exists: ADR-024 §1 defines Tier-1 as a manifest-only plugin whose first contribution is
 * "content types & fields", but `Jini/packages/plugins/src/host/manifest.ts` only ever parsed-and-stored `contentTypes` (state.spec
 * §2: "UNUSED in v1"). This module is the missing half: a bounded, closed declaration grammar
 * (ADR-024 §5 — Tier-1 is only safe while its surface is non-Turing-complete and bounded) and an
 * idempotent provisioner that runs at enable time.
 *
 * Rules the provisioner keeps (and why):
 * - **Create if missing, never overwrite.** An existing type that already holds every declared field
 *   with the same kind is KEPT (the owner may have added fields of their own through Collections —
 *   that is their data model now). An existing type that disagrees is a CONFLICT and the enable is
 *   refused before anything is written, rather than silently reshaping someone's content.
 * - **A tombstoned type is skipped.** The owner deleted it on purpose; tombstone is terminal and the
 *   key can never be reused (content-types INV-06), so re-enabling the plugin does not resurrect it.
 * - **Retain on disable/uninstall** (ADR-023/ADR-024 retain-by-default): nothing here ever removes a
 *   type. The entries are the owner's content, not the plugin's.
 * - **Owner `site`.** Types are registered under the default `ext.site` envelope, not `ext.<plugin>`:
 *   every display path (collection marker, Collection list widget, entries SQL) reads `ext.site`
 *   only, so a plugin-owned envelope would be invisible on the public site. Recorded as a missing
 *   primitive in the AW-7 report.
 *
 * Pure parsing; the plan/apply halves do I/O only through the injected ports.
 */
import {
  CONTENT_TYPE_FIELD_KINDS,
  ContentTypeAlreadyExistsError,
  isContentTypeFieldKind,
  isIndexableFieldKind,
  validateIdentifierGrammar,
  type ContentTypeFieldDef,
  type ContentTypeFieldKind,
  type ContentTypeRecord,
} from "#src/features/content-types/index";
import { SYSTEM_CONTENT_TYPES } from "#src/features/entries/public-list";

import { PluginInvalidError } from "@jini-ai/plugins/host";
import type { PluginManifest, PluginValidationError } from "@jini-ai/plugins/host";

/** ADR-024 §5 bound: how many content types one plugin may declare. */
export const MAX_DECLARED_CONTENT_TYPES = 20;
/** ADR-024 §5 bound: how many fields one declared content type may carry. */
export const MAX_DECLARED_FIELDS = 50;
/** Core's own per-type queryable-field cap (`QUERYABLE_FIELD_CAP` in `@jini-ai/cms`'s
 *  `registerContentType`, not exported). Checked here so a declaration core would refuse is
 *  `invalid` at discovery, instead of failing at enable after the plugin's code attached. */
export const MAX_DECLARED_QUERYABLE_FIELDS = 20;
const MAX_LABEL_LENGTH = 100;
const IDENTIFIER_GRAMMAR_TEXT = "^[a-z][a-z0-9_]{0,63}$";

/** Keys core owns: `post`/`page` are permanently reserved by the content-types package, and the
 *  system types (widgets, widget areas, menus) are platform plumbing. */
const RESERVED_KEYS: ReadonlySet<string> = new Set(["post", "page", ...SYSTEM_CONTENT_TYPES]);
const DECL_KEYS: ReadonlySet<string> = new Set(["key", "label", "fields"]);
const FIELD_KEYS: ReadonlySet<string> = new Set(["name", "kind", "required", "queryable"]);

/** One validated content-type declaration, already in core's `ContentTypeFieldDef` shape. */
export interface DeclaredContentType {
  readonly key: string;
  readonly label: string;
  readonly fields: readonly ContentTypeFieldDef[];
}

export interface ParseDeclaredContentTypesResult {
  readonly decls: readonly DeclaredContentType[];
  readonly errors: readonly PluginValidationError[];
}

function declError(message: string): PluginValidationError {
  return { code: "CONTENT_TYPE_DECL_INVALID", file: null, message };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function unknownKeyErrors(raw: Record<string, unknown>, allowed: ReadonlySet<string>, where: string): PluginValidationError[] {
  return Object.keys(raw)
    .filter((key) => !allowed.has(key))
    .map((key) => declError(`${where} has an unknown key '${key}'`));
}

function optionalFlag(raw: Record<string, unknown>, flag: "required" | "queryable", where: string, errors: PluginValidationError[]): boolean {
  const value = raw[flag];
  if (value === undefined) return false;
  if (typeof value === "boolean") return value;
  errors.push(declError(`${where} '${flag}' must be a boolean`));
  return false;
}

/** The name/kind half of one field — returns the validated pair, or `undefined` after recording why. */
function fieldIdentity(raw: Record<string, unknown>, typeKey: string, errors: PluginValidationError[]): { name: string; kind: ContentTypeFieldKind } | undefined {
  const name = raw.name;
  if (typeof name !== "string" || !validateIdentifierGrammar({ value: name })) {
    errors.push(declError(`content type '${typeKey}' field name '${String(name)}' must match ${IDENTIFIER_GRAMMAR_TEXT}`));
    return undefined;
  }
  const kind = raw.kind;
  if (!isContentTypeFieldKind({ value: kind })) {
    errors.push(declError(`content type '${typeKey}' field '${name}' has kind '${String(kind)}'; allowed: ${CONTENT_TYPE_FIELD_KINDS.join("|")}`));
    return undefined;
  }
  return { name, kind: kind as ContentTypeFieldKind };
}

/** One `fields[]` entry. Collects every problem it finds; returns the field only when it has none. */
function parseField(raw: unknown, index: number, typeKey: string): { field?: ContentTypeFieldDef; errors: PluginValidationError[] } {
  if (!isRecord(raw)) return { errors: [declError(`content type '${typeKey}' field ${index} must be an object`)] };
  const where = `content type '${typeKey}' field '${String(raw.name)}'`;
  const errors = unknownKeyErrors(raw, FIELD_KEYS, where);
  const identity = fieldIdentity(raw, typeKey, errors);
  const required = optionalFlag(raw, "required", where, errors);
  const queryable = optionalFlag(raw, "queryable", where, errors);
  if (identity && queryable && !isIndexableFieldKind({ value: identity.kind })) {
    errors.push(declError(`${where} has storage-only kind '${identity.kind}' and cannot be queryable`));
  }
  if (!identity || errors.length > 0) return { errors };
  return { field: { name: identity.name, kind: identity.kind, required, queryable }, errors };
}

function duplicateNames(names: readonly string[]): string[] {
  const seen = new Set<string>();
  const duplicates = new Set<string>();
  for (const name of names) {
    if (seen.has(name)) duplicates.add(name);
    seen.add(name);
  }
  return [...duplicates];
}

function parseFields(raw: unknown, typeKey: string): { fields: ContentTypeFieldDef[]; errors: PluginValidationError[] } {
  if (!Array.isArray(raw) || raw.length === 0 || raw.length > MAX_DECLARED_FIELDS) {
    return { fields: [], errors: [declError(`content type '${typeKey}' must declare 1-${MAX_DECLARED_FIELDS} fields`)] };
  }
  const parsed = raw.map((field, index) => parseField(field, index, typeKey));
  const fields = parsed.flatMap((result) => (result.field ? [result.field] : []));
  const errors = parsed.flatMap((result) => result.errors);
  for (const name of duplicateNames(fields.map((field) => field.name))) {
    errors.push(declError(`content type '${typeKey}' declares field '${name}' more than once`));
  }
  const queryableCount = fields.filter((field) => field.queryable).length;
  if (queryableCount > MAX_DECLARED_QUERYABLE_FIELDS) {
    errors.push(declError(`content type '${typeKey}' declares ${queryableCount} queryable fields; at most ${MAX_DECLARED_QUERYABLE_FIELDS} are allowed`));
  }
  return { fields, errors };
}

function keyErrors(key: unknown, index: number): PluginValidationError[] {
  if (typeof key !== "string") return [declError(`contentTypes[${index}].key must be a string`)];
  if (!validateIdentifierGrammar({ value: key })) return [declError(`content type key '${key}' must match ${IDENTIFIER_GRAMMAR_TEXT}`)];
  if (RESERVED_KEYS.has(key)) return [declError(`content type key '${key}' is reserved by core`)];
  return [];
}

function labelValid(label: unknown): label is string {
  return typeof label === "string" && label.trim().length > 0 && label.length <= MAX_LABEL_LENGTH;
}

/** One `contentTypes[]` entry. */
function parseDecl(raw: unknown, index: number): { decl?: DeclaredContentType; errors: PluginValidationError[] } {
  if (!isRecord(raw)) return { errors: [declError(`contentTypes[${index}] must be an object`)] };
  const errors = [...unknownKeyErrors(raw, DECL_KEYS, `contentTypes[${index}]`), ...keyErrors(raw.key, index)];
  const key = String(raw.key);
  if (!labelValid(raw.label)) errors.push(declError(`content type '${key}' needs a label of 1-${MAX_LABEL_LENGTH} characters`));
  const fields = parseFields(raw.fields, key);
  errors.push(...fields.errors);
  if (errors.length > 0) return { errors };
  return { decl: { key, label: raw.label as string, fields: fields.fields }, errors };
}

/**
 * Parses a manifest's raw `contentTypes` value. Collect-all, never throws (same contract as
 * `validateManifest`). `undefined`/`null` declare nothing.
 *
 * @complexity O(t · f) over declared types and their fields — both bounded by the MAX_* constants.
 */
export function parseDeclaredContentTypes(required: { value: unknown }, _optional: Record<string, never> = {}): ParseDeclaredContentTypesResult {
  const { value } = required;
  if (value === undefined || value === null) return { decls: [], errors: [] };
  if (!Array.isArray(value)) return { decls: [], errors: [declError("'contentTypes' must be an array")] };
  if (value.length > MAX_DECLARED_CONTENT_TYPES) {
    return { decls: [], errors: [declError(`'contentTypes' declares more than ${MAX_DECLARED_CONTENT_TYPES} content types`)] };
  }
  const parsed = value.map((entry, index) => parseDecl(entry, index));
  const decls = parsed.flatMap((result) => (result.decl ? [result.decl] : []));
  const errors = parsed.flatMap((result) => result.errors);
  for (const key of duplicateNames(decls.map((decl) => decl.key))) {
    errors.push(declError(`content type key '${key}' is declared more than once`));
  }
  return { decls, errors };
}

/** The manifest arrays only executable code can use — a Tier-1 plugin has none to use them with. */
const CODE_SURFACES = ["capabilities", "hooks", "fields"] as const;

/** The manifest keys the declarative rules read. Values are `unknown` so `validateManifest` can pass
 *  its raw, not-yet-validated object, and a parsed `PluginManifest` fits too. */
export interface DeclarativeManifestView {
  readonly tier?: unknown;
  readonly contentTypes?: unknown;
  readonly capabilities?: unknown;
  readonly hooks?: unknown;
  readonly fields?: unknown;
}

/**
 * The declarative half of a manifest's validation: its `contentTypes`, plus — for a `tier-1`
 * plugin — the rule that it declares no code surface. Hooks, capability grants and `ext` fields
 * all exist to be used by plugin code, and a Tier-1 plugin is never imported (ADR-024 §1: "zero
 * executable code"), so declaring one is either a mistake or an attempt to look like something it
 * is not. `validateManifest()` calls this, so discovery lists a bad declaration as `invalid`
 * instead of it failing only at enable. A surface that is not an array is left to
 * `validateManifest`'s own malformed check (reported once, not twice).
 */
export function validateDeclarativeManifest(required: { manifest: DeclarativeManifestView }, _optional: Record<string, never> = {}): ParseDeclaredContentTypesResult {
  const { manifest } = required;
  const parsed = parseDeclaredContentTypes({ value: manifest.contentTypes });
  if (manifest.tier !== "tier-1") return parsed;
  const surfaceErrors = CODE_SURFACES.filter((surface) => {
    const declared = manifest[surface];
    return Array.isArray(declared) && declared.length > 0;
  }).map((surface) => ({
    code: "TIER1_DECLARES_CODE_SURFACE",
    file: null,
    message: `a declarative (tier-1) plugin cannot declare '${surface}' — only code can use them`,
  }));
  return { decls: parsed.decls, errors: [...surfaceErrors, ...parsed.errors] };
}

/**
 * The two content-type operations the provisioner needs. `register` is core's `registerContentType`
 * bound by the composition root (see `createDeclaredContentTypePorts`); it returns core's `Result`
 * rather than throwing for an expected rejection.
 */
export interface DeclaredContentTypePorts {
  findByKey(params: { workspaceId: string; key: string }): Promise<ContentTypeRecord | null>;
  register(input: {
    workspaceId: string;
    key: string;
    label: string;
    fields: ContentTypeFieldDef[];
    actorId: string;
  }): Promise<{ ok: true } | { ok: false; error: Error }>;
}

export type DeclaredContentTypeOutcome = "create" | "keep" | "skip-tombstoned";

export interface DeclaredContentTypePlan {
  readonly items: ReadonlyArray<{ readonly decl: DeclaredContentType; readonly outcome: DeclaredContentTypeOutcome }>;
  /** Human-readable reasons the plugin cannot be turned on. Non-empty ⇒ `items` is empty. */
  readonly conflicts: readonly string[];
}

/** Why `existing` cannot serve as `decl`'s type, one reason per disagreeing field. */
function incompatibilities(decl: DeclaredContentType, existing: ContentTypeRecord): string[] {
  const reasons: string[] = [];
  for (const field of decl.fields) {
    const held = existing.fields.find((candidate) => candidate.name === field.name);
    if (!held) reasons.push(`content type '${decl.key}' already exists without field '${field.name}'`);
    else if (held.kind !== field.kind) reasons.push(`content type '${decl.key}' already exists with field '${field.name}' as '${held.kind}', not '${field.kind}'`);
  }
  return reasons;
}

/**
 * Decides, without writing anything, what enabling would do to each declared type. A conflict on
 * ANY type refuses the whole plan, so an enable never leaves half a plugin's types behind.
 *
 * @complexity O(t) port reads plus O(t · f²) field comparison, all manifest-bounded.
 */
export async function planDeclaredContentTypes(
  required: { ports: Pick<DeclaredContentTypePorts, "findByKey">; workspaceId: string; decls: readonly DeclaredContentType[] },
  _optional: Record<string, never> = {}
): Promise<DeclaredContentTypePlan> {
  const { ports, workspaceId, decls } = required;
  const items: Array<{ decl: DeclaredContentType; outcome: DeclaredContentTypeOutcome }> = [];
  const conflicts: string[] = [];
  for (const decl of decls) {
    const existing = await ports.findByKey({ workspaceId, key: decl.key });
    if (!existing) items.push({ decl, outcome: "create" });
    else if (existing.status === "tombstone") items.push({ decl, outcome: "skip-tombstoned" });
    else {
      const reasons = incompatibilities(decl, existing);
      if (reasons.length === 0) items.push({ decl, outcome: "keep" });
      conflicts.push(...reasons);
    }
  }
  return conflicts.length > 0 ? { items: [], conflicts } : { items, conflicts };
}

export interface ApplyDeclaredContentTypesResult {
  readonly created: readonly string[];
  readonly kept: readonly string[];
  readonly skipped: readonly string[];
}

/**
 * What losing a concurrent create race means: the planning-time compatibility check never saw the
 * winning type, so it is re-read and judged the same way `planDeclaredContentTypes` would have —
 * compatible ⇒ kept, tombstoned ⇒ skipped, anything else refuses the enable.
 *
 * @throws {PluginInvalidError} the winner disagrees with the declaration.
 * @throws the original `lost` error when the winner cannot be read back.
 * @complexity One port read plus O(f²) field comparison.
 */
async function judgeLostRace(
  required: { ports: DeclaredContentTypePorts; workspaceId: string; pluginId: string; decl: DeclaredContentType; lost: Error }
): Promise<"keep" | "skip-tombstoned"> {
  const { ports, workspaceId, pluginId, decl, lost } = required;
  const winner = await ports.findByKey({ workspaceId, key: decl.key });
  if (!winner) throw lost;
  if (winner.status === "tombstone") return "skip-tombstoned";
  const reasons = incompatibilities(decl, winner);
  if (reasons.length > 0) throw new PluginInvalidError(`plugin '${pluginId}' cannot be turned on: ${reasons.join("; ")}`);
  return "keep";
}

/**
 * Carries out a conflict-free plan. Each create is recorded as `plugin:<id>` so the content-type
 * revision log says which plugin made the type; losing a concurrent create race is judged against
 * the winning type ({@link judgeLostRace}) — kept only when it matches the declaration. Any other
 * failure is rethrown as-is.
 */
export async function applyDeclaredContentTypes(
  required: { ports: DeclaredContentTypePorts; workspaceId: string; pluginId: string; plan: DeclaredContentTypePlan },
  _optional: Record<string, never> = {}
): Promise<ApplyDeclaredContentTypesResult> {
  const { ports, workspaceId, pluginId, plan } = required;
  const created: string[] = [];
  const kept: string[] = [];
  const skipped: string[] = [];
  const bucket = { created, keep: kept, "skip-tombstoned": skipped };
  for (const { decl, outcome } of plan.items) {
    const applied = outcome === "keep" || outcome === "skip-tombstoned" ? outcome : await createDeclared({ ports, workspaceId, pluginId, decl });
    bucket[applied].push(decl.key);
  }
  return { created, kept, skipped };
}

/** Registers one planned type as `plugin:<id>`; a lost create race takes the judged winner's outcome. */
async function createDeclared(
  required: { ports: DeclaredContentTypePorts; workspaceId: string; pluginId: string; decl: DeclaredContentType }
): Promise<"created" | "keep" | "skip-tombstoned"> {
  const { ports, workspaceId, pluginId, decl } = required;
  const result = await ports.register({ workspaceId, key: decl.key, label: decl.label, fields: [...decl.fields], actorId: `plugin:${pluginId}` });
  if (result.ok) return "created";
  if (!(result.error instanceof ContentTypeAlreadyExistsError)) throw result.error;
  return judgeLostRace({ ports, workspaceId, pluginId, decl, lost: result.error });
}

/** CMS ZIP policy. Parsing/streaming is the published Jini reader, never a custom ZIP parser.
 * Keep unreviewed bytes off disk; the normal installer alone may publish a verified package.
 */
import * as yauzl from "yauzl";
import { createYauzlAgentPluginArchiveReader, type YauzlEntry, type YauzlPort } from "@jini-ai/agent-plugins/lifecycle/yauzl";
import type { AgentPluginArchiveEntry, AgentPluginArchiveReaderPort } from "@jini-ai/agent-plugins/lifecycle";
import { PluginInstallError } from "@jini-ai/plugins/host/node";

export const MAX_PLUGIN_ARCHIVE_BYTES = 32 * 1024 * 1024;
const MAX_ENTRIES = 4096;
const MAX_FILE_BYTES = 16 * 1024 * 1024;
const MAX_EXPANDED_BYTES = 64 * 1024 * 1024;
const SIZE_LIMIT_MESSAGE = "ZIP exceeds the file or expanded size limit.";

/** True for a Unix-authored entry whose file-type bits are neither unset, a regular file nor a directory. */
function isSpecialUnixEntry(required: { entry: YauzlEntry }): boolean {
  const kind = (required.entry.externalFileAttributes >>> 16) & 0xf000;
  return (required.entry.versionMadeBy >>> 8) === 3 && kind !== 0 && kind !== 0x8000 && kind !== 0x4000;
}

// Compatibility guard for published Jini readers that classify a trailing slash before Unix mode.
// The shared reader fix is in Jini; this job cannot publish it. Also refuse special Unix entries.
const guardedYauzl: YauzlPort = {
  async fromBufferPromise(buffer, options) {
    const zip = await (yauzl as unknown as YauzlPort).fromBufferPromise(buffer, options);
    return {
      close: () => zip.close(),
      openReadStreamPromise: (entry) => zip.openReadStreamPromise(entry),
      async *eachEntry() {
        for await (const entry of zip.eachEntry()) {
          if (isSpecialUnixEntry({ entry })) throw new PluginInstallError("PLUGIN_PACKAGE_UNSAFE", "ZIP links and special entries are not allowed.");
          yield entry;
        }
      },
    };
  },
};
const defaultReader = createYauzlAgentPluginArchiveReader({ yauzl: guardedYauzl });

function fail(code: string, message: string): never { throw new PluginInstallError(code, message); }

/** Everything accepted so far; one instance per archive read. */
interface ArchivePolicyState {
  readonly files: Map<string, Buffer>;
  readonly paths: Map<string, "file" | "directory">;
  // A case-insensitive directory alias can merge two trees on macOS/Windows at publication.
  readonly spellings: Map<string, string>;
  entries: number;
  total: number;
}

type FileEntry = Extract<AgentPluginArchiveEntry, { kind: "file" }>;

/** Refuses empty, NUL, absolute, drive-lettered, dot/dot-dot, empty-segment and colon paths. */
function assertInsidePackage(required: { key: string; segments: readonly string[] }): void {
  const { key, segments } = required;
  if (!key || key.includes("\0") || key.startsWith("/") || /^[a-zA-Z]:/.test(key) || segments.some((s) => !s || s === "." || s === ".." || s.includes(":"))) fail("PLUGIN_PACKAGE_UNSAFE", "ZIP paths must stay inside the package.");
}

/** Records one path prefix's spelling; refuses a second spelling of it and caps distinct prefixes. */
function claimSpelling(required: { spellings: Map<string, string>; prefix: string }): void {
  const { spellings, prefix } = required;
  const lower = prefix.toLowerCase();
  if (spellings.has(lower) && spellings.get(lower) !== prefix) fail("PLUGIN_PACKAGE_UNSAFE", "ZIP has case-aliased paths.");
  spellings.set(lower, prefix);
  if (spellings.size > MAX_ENTRIES) fail("PLUGIN_PACKAGE_TOO_LARGE", "ZIP has too many files and directories.");
}

/** Claims `key` for this entry: no duplicates, aliases, paths through a file, or files over a subtree. */
function claimPath(required: { state: ArchivePolicyState; kind: "file" | "directory"; key: string; segments: readonly string[] }): void {
  const { state, kind, key, segments } = required;
  if (state.paths.has(key)) fail("PLUGIN_PACKAGE_UNSAFE", "ZIP has duplicate paths.");
  for (let i = 1; i <= segments.length; i++) {
    const prefix = segments.slice(0, i).join("/");
    claimSpelling({ spellings: state.spellings, prefix });
    // At i === segments.length the prefix is `key` itself, already refused above if present.
    if (state.paths.get(prefix) === "file") fail("PLUGIN_PACKAGE_UNSAFE", "ZIP path crosses a file.");
  }
  if (kind === "file" && [...state.paths.keys()].some((p) => p.startsWith(key + "/"))) fail("PLUGIN_PACKAGE_UNSAFE", "ZIP file replaces a directory.");
  state.paths.set(key, kind);
}

/** Refuses a declared size that is not a sane integer, exceeds the file cap, or would exceed the total. */
function assertDeclaredSize(required: { declaredSize: number | undefined; total: number }): void {
  const { declaredSize, total } = required;
  if (declaredSize === undefined) return;
  if (!Number.isSafeInteger(declaredSize) || declaredSize < 0 || declaredSize > MAX_FILE_BYTES || total + declaredSize > MAX_EXPANDED_BYTES) fail("PLUGIN_PACKAGE_TOO_LARGE", SIZE_LIMIT_MESSAGE);
}

/** Streams one file into memory, counting real bytes against the file and expanded caps. */
async function readFileBytes(required: { state: ArchivePolicyState; entry: FileEntry }): Promise<Buffer> {
  const { state, entry } = required;
  const chunks: Buffer[] = []; let length = 0;
  for await (const chunk of entry.openReadStream({})) {
    length += chunk.byteLength; state.total += chunk.byteLength;
    if (length > MAX_FILE_BYTES || state.total > MAX_EXPANDED_BYTES) fail("PLUGIN_PACKAGE_TOO_LARGE", SIZE_LIMIT_MESSAGE);
    chunks.push(Buffer.from(chunk));
  }
  return Buffer.concat(chunks, length);
}

/** Applies the whole policy to one entry, in order, and keeps a file's bytes when it passes. */
async function acceptEntry(required: { state: ArchivePolicyState; entry: AgentPluginArchiveEntry }): Promise<void> {
  const { state, entry } = required;
  if (++state.entries > MAX_ENTRIES) fail("PLUGIN_PACKAGE_TOO_LARGE", "ZIP has too many entries.");
  if (entry.kind !== "file" && entry.kind !== "directory") fail("PLUGIN_PACKAGE_UNSAFE", "ZIP links are not allowed.");
  const name = entry.entryPath.replaceAll("\\", "/");
  const key = entry.kind === "directory" ? name.replace(/\/$/, "") : name;
  const segments = key.split("/");
  assertInsidePackage({ key, segments });
  claimPath({ state, kind: entry.kind, key, segments });
  if (entry.kind === "directory") return;
  assertDeclaredSize({ declaredSize: entry.declaredSize, total: state.total });
  state.files.set(key, await readFileBytes({ state, entry }));
}

export async function readSitePluginArchive(
  required: { archive: Uint8Array },
  optional: { reader?: AgentPluginArchiveReaderPort } = {},
): Promise<Map<string, Buffer>> {
  if (required.archive.byteLength > MAX_PLUGIN_ARCHIVE_BYTES) fail("PLUGIN_PACKAGE_TOO_LARGE", "ZIP exceeds the 32 MiB upload limit.");
  const state: ArchivePolicyState = { files: new Map(), paths: new Map(), spellings: new Map(), entries: 0, total: 0 };
  try {
    for await (const entry of (optional.reader ?? defaultReader).entries({ archive: required.archive })) await acceptEntry({ state, entry });
    return state.files;
  } catch (error) {
    if (error instanceof PluginInstallError) throw error;
    fail("PLUGIN_ARCHIVE_INVALID", "ZIP could not be read safely.");
  }
}

import type { PluginInstallPreview } from "@jini-ai/plugins/host/node";

/** What installing does to this computer, in one sentence. The CLI prompt shows it before the human
 *  approves; the assistant's `plugins_install` returns it as its result's `warning`. */
export function pluginInstallRiskSentence(required: { preview: PluginInstallPreview }, _optional = {}): string {
  const p = required.preview;
  // A tier-1 package has nothing to run (install.ts refuses one that ships a code file), so the
  // full-access warning would be false; say what it does instead.
  return p.hasCode ? "This plugin runs code with full access to this computer and every site on it." : `This plugin contains no code.${p.contentTypes.length > 0 ? ` It adds content types: ${p.contentTypes.join(", ")}.` : ""}`;
}

export const PLUGIN_INSTALL_STAYS_OFF = "It stays off in every workspace until you turn it on.";

/** The full trust disclosure a human reviews before a site plugin is installed. */
export function pluginInstallConsent(required: { preview: PluginInstallPreview }, _optional = {}): string {
  const p = required.preview;
  return [
    `${p.name} (${p.id}) ${p.version}`,
    `Trust: ${p.tier} (local / unverified publisher)`,
    `Capabilities: ${p.capabilities.join(", ") || "—"}`,
    `Hooks: ${p.hooks.join(", ") || "—"}`,
    ...(p.warnings ?? []),
    ...(p.upgradeFrom ? [`Replaces installed version ${p.upgradeFrom}.`] : []),
    pluginInstallRiskSentence({ preview: p }),
    PLUGIN_INSTALL_STAYS_OFF, "",
  ].join("\n");
}

