function toAgentPluginListRow(required: { plugin: InstalledAgentPlugin; exports: readonly PluginExportCatalogRow[] }, _options = {}): AgentPluginListRow {
  const p = required.plugin;
  return { pluginId: p.pluginId, version: p.version ?? null, archiveDigest: p.archiveDigest, skills: p.skills.map((s) => s.name), exports: required.exports };
}

/** Reads every installed Agent Plugin for `plugins_list`'s Agent Plugin half. Degrades to `[]` on
 *  any failure (see this file's header, "Failure isolation") rather than failing the whole tool
 *  call over the newer, less-exercised half of this tool. */
async function listAgentPluginsForResponse(routeDeps: PluginsToolDeps): Promise<readonly AgentPluginListRow[]> {
  try {
    const installed = await listInstalledAgentPlugins(routeDeps);
    const exports = await routeDeps.pluginExports?.catalog({ workspaceId: routeDeps.workspaceId }).catch(() => new Map());
    return installed.map(plugin => toAgentPluginListRow({ plugin, exports: exports?.get(plugin.pluginId) ?? [] }));
  } catch {
    return [];
  }
}

/**
 * The exact slice of the route-deps bag Plugins' tool handlers read. Declared structurally (rather
 * than importing `server/routes/types`'s `RouteDeps`) so this module carries no back-edge into the
 * composition root for the `RouteDeps` god type specifically — the `toAdminPluginResponse` import
 * above is a separate, already-disclosed back-edge (`server/http/admin/plugins`) left untouched per
 * the dispatch's explicit out-of-scope list. `server/routes/*` satisfies this structurally by
 * passing its existing `RouteDeps` object; nothing there changes.
 */
export interface PluginsToolDeps extends OperatorLocaleDeps {
  readonly tracker?: Tracker;
  readonly pluginExports?: PluginExportRuntime;
  readonly pluginSource?: import('@jini-ai/plugins/host/node').PluginSourcePort;
  readonly pluginSourcePolicy?: import('@jini-ai/plugins/host').PluginSourcePolicyPort;
  readonly pluginHost?: PluginHostPort;
  readonly agentPluginLayout: AgentPluginLayout;
  authorize: AuthorizeFn;
  workspaceId: string;
  clock: Clock;
  idGen: { newId(): string };
  changeSets: ChangeSetRepoPort;
  outbox: OutboxPort;
  pluginActivationRepo: PluginActivationRepoPort;
  discoverPlugins: () => Promise<readonly PluginDiscoveryRecord[]>;
  /** Uses the existing activation owner; injection lets callers model lock failures without module replacement. */
  assertAgentPluginActivationsWritable?: (required: { workspaceRoot: string }) => Promise<void>;
  /** Bind the same lifecycle owner with host effects; no module replacement is needed for failures. */
  setAgentPluginEnabled?: (required: SetAgentPluginEnabledInput) => Promise<SetAgentPluginEnabledResult>;
  listInstalledAgentPlugins?: (workspaceRoot: string) => Promise<readonly InstalledAgentPlugin[]>;
  /** Bound to the existing remembered-approval store; only enable escalations get reusable keys. */
  nativeApprovalMemory?: RememberedApprovalPort;
  uninstallAgentPlugin?: AgentPluginUninstallToolDeps["uninstallAgentPlugin"];
  onPluginEnabled: (pluginId: string) => Promise<void>;
  onPluginDisabled: (pluginId: string) => void;
  /** 2026-10-04 — see `routes/types.ts`'s `PluginRuntimeDeps.listPluginConflicts`. */
  listPluginConflicts?: () => Promise<ReadonlyMap<string, readonly PluginConflict[]>>;
  removePlugin: RemovePluginFn;
  /** The admin Install Plugin routes' installer; absent when the site has no plugin install dir.
   *  Read by `install-tool.ts`'s `plugins_install`, not by this file's tools. */
  pluginInstaller?: PluginInstallerPort;
  /** The external-MCP store slice `provisionAgentPluginMcpServers` writes into. Enabling an Agent
   *  Plugin from chat must provision its auto-admitted MCP servers exactly as the admin toggle does
   *  (`server/inbound/admin-http/routes/agent-plugins/set-enabled.ts`); these are the same fields
   *  that route's `AgentPluginsRouteDeps` threads. The `clock` above is already the fourth
   *  `ExternalMcpStoreDeps` field, so it is not repeated here. */
  externalMcpServerRepo: ExternalMcpStoreDeps["repo"];
  siteAssistantSecretSealer: ExternalMcpStoreDeps["sealer"];
  siteAssistantSecretKeyring: ExternalMcpStoreDeps["keyring"];
}

/**
 * This wiring layer's OWN risk classification, authored from what each handler below actually
 * calls. See `DerivedRiskByToolId` in the kit for why it is independent of the catalog's own
 * `sideEffects` declaration.
 */
export const pluginsDerivedRisk: DerivedRiskByToolId = new Map<string, AgentToolSideEffect>([
  // -> discoverPlugins() + pluginActivationRepo.getActivation() per record: reads only.
  ["plugins_list", "none"],
  // -> executeCommand(...) -> setPluginEnabled (activation.ts): pluginActivationRepo.save() plus
  //    (on enable) the injected onEnabled hook, which can run ADR-023 schema DDL against the live
  //    database. Genuinely mutating, not a metadata-only flip.
  ["plugins_set_enabled", "mutates-durable-state"],
  // -> uninstallPlugin (uninstall.ts) for family 'site-runtime': the package directory moves to the
  //    60-day Trash, durable and reversible only through the human Admin Trash surface. ->
  //    runAgentPluginUninstall (agent-plugins/uninstall-tool.ts) for family 'agent-plugin': the
  //    package is deleted from disk with no Trash and no undo. One tool id, one risk band (S4,
  //    2026-09-24) — `deletes-durable-state`, the worse of the two families' blast radii, since this
  //    map is keyed per tool id, not per family.
  ["plugins_uninstall", "deletes-durable-state"],
]);

/**
 * ===========================================================================================
 * `plugins_set_enabled` — one tool, two plugin families
 * ===========================================================================================
 * Tovu has two unrelated plugin systems that share the word "plugin":
 *
 * - `.tovu-plugin` SITE/RUNTIME plugins — this feature. Discovered by `discoverPlugins()`, activated
 *   as a database row through `Jini/packages/plugins/src/host/activation.ts`'s `setPluginEnabled`, enable-hook may run ADR-023 DDL.
 * - AGENT PLUGINS — `features/agent-plugins/`. agent-plugins.org packages on disk, activated as a
 *   JSON record through `agent-plugins/set-enabled.ts`, whose `SKILL.md` is injected into a run's
 *   prompt and whose `agent_plugin_<id>` tool only exists while it is active.
 *
 * Before 2026-09-09 the assistant could toggle the first and had NO tool at all for the second, so
 * "find the Higgsfield plugin and use it" dead-ended in chat at the point of turning it on. The fix
 * is one tool with an explicit `family` argument rather than a second, near-identically-named enable
 * tool — a model choosing between `plugins_set_enabled` and `agent_plugins_set_enabled` is precisely
 * the confusion the catalog exists to prevent, and the operator asking to "turn on the Higgsfield
 * plugin" does not know which system that word means either.
 *
 * `family` is REQUIRED and never inferred from the id. The two namespaces are independent, so an id
 * present in both is possible, and guessing has already produced real work in the wrong directory.
 *
 * WHAT IS NOT FOLDED IN, and why it is a rule rather than a preference: install and uninstall stay
 * separate tools. `DERIVED_RISK_BY_TOOL_ID` is keyed PER TOOL ID, so one tool gets exactly one risk
 * band. Enabling is reversible and touches a flag; installing runs third-party code; uninstalling
 * deletes bytes. Merging them would force one band onto three very different blast radii, and the
 * wiring gate that reads that map fails CLOSED.
 */

/** One parsed `plugins_set_enabled` call. */
interface SetEnabledRequest {
  readonly family: PluginFamily;
  readonly pluginId: string;
  readonly enabled: boolean;
}

/** Reads `family` as an explicit choice between the two real systems.
 *
 *  A `ToolInputError`, not a bare `Error`: this genuinely IS "the caller's input was the problem, and
 *  a different input fixes it", and a bare `Error` out of a tool handler is redacted into an opaque
 *  failure by the daemon — so the one message that could tell the model which family to name would
 *  never reach it. @complexity O(1). */
function readFamily(input: Record<string, unknown>): PluginFamily {
  const raw = input["family"];
  if (raw === "site-runtime" || raw === "agent-plugin") return raw;
  throw new ToolInputError({ message: "'family' is required and must be exactly one of: 'site-runtime' (a .tovu-plugin site plugin, as listed by " +
      "content_read.plugin) or 'agent-plugin' (an Agent Plugin, as returned by search_agent_plugin_local). Tovu has two " +
      "unrelated plugin systems and this tool never guesses between them — if you are unsure, call the matching list/search " +
      "tool first and use the family whose results contained this id." });
}

/** @complexity O(1). */
function readSetEnabledRequest(rawInput: unknown): SetEnabledRequest {
  const input = requireInputRecord({ input: rawInput });
  const family = readFamily(input);
  const pluginId = requireString({ input: input, key: "pluginId" });
  if (typeof input["enabled"] !== "boolean") {
    throw new ToolInputError({ message: "'enabled' (boolean) is required — true to turn the plugin on, false to turn it off" });
  }
  return { family, pluginId, enabled: input["enabled"] };
}

/** What one plugin's enable approval is bound to; `discovery` is the site-runtime snapshot it was read from. */
interface PluginApprovalIdentity {
  readonly key: string;
  readonly version?: string;
  readonly label: string;
  readonly discovery?: readonly PluginDiscoveryRecord[];
}

/** Identity/version binding before and after consent. The existing MCP fingerprint owner
 * hashes the version/digest metadata; no second hashing or approval store is introduced.
 * Disabling removes capability, so it needs no identity grant and never raises a dialog.
 * @complexity One family discovery scan, bounded by the installed package count. */
export async function pluginApprovalIdentity(
  { deps: routeDeps, request }: { deps: PluginsToolDeps; request: Pick<SetEnabledRequest, "family" | "pluginId"> }, _optional = {},
): Promise<PluginApprovalIdentity> {
  let revision: string;
  let version: string | undefined;
  let label: string | undefined;
  let discovery: readonly PluginDiscoveryRecord[] | undefined;
  let schema: Readonly<Record<string, unknown>> = {};
  if (request.family === "agent-plugin") {
    const plugins = await listInstalledAgentPlugins(routeDeps);
    const installed = plugins.filter(plugin => plugin.pluginId === request.pluginId);
    if (installed.length === 0) throw new ToolInputError({ message: `Agent Plugin '${request.pluginId}' is not installed` });
    // Every installed digest participates, independent of discovery ordering.
    revision = JSON.stringify(installed.map(plugin => [plugin.version ?? null, plugin.archiveDigest]).sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b))));
    version = installed.map(plugin => plugin.version).filter((value): value is string => value !== undefined).sort().join(", ");
  } else {
    discovery = structuredClone(await routeDeps.discoverPlugins());
    const plugin = discovery.find(plugin => plugin.id === request.pluginId);
    if (!plugin) throw new ToolInputError({ message: `plugin '${request.pluginId}' was not found in the current discovery snapshot` });
    revision = plugin.version;
    schema = { ...plugin.manifest };
    version = plugin.version; label = plugin.name;
  }
  const fingerprint = federatedToolApprovalFingerprint({ fingerprintDomain: "tovu.native-escalation.v1",
    identity: { connectionId: JSON.stringify([routeDeps.workspaceId, request.family, request.pluginId]),
      remoteName: PLUGINS_SET_ENABLED_TOOL_ID, origin: { kind: "roster", admissionRevision: revision },
      declaredAnnotations: undefined, description: "Enable this plugin identity", inputSchema: schema },
  });
  return { key: fingerprint, version, label: label ?? request.pluginId, discovery };
}

/** A fresh `uninstallPlugin` request. Discovery is re-read on every call, so the post-confirmation write never resolves
 *  its target from the snapshot taken before a human was asked. @complexity one discovery scan. */
async function uninstallRequestFor(
  routeDeps: PluginsToolDeps,
  pluginId: string,
  principalId: string,
): Promise<UninstallPluginRequired> {
  const discovery = await routeDeps.discoverPlugins();
  return {
    deps: { repo: routeDeps.pluginActivationRepo, discovery, remove: routeDeps.removePlugin },
    input: {
      pluginId,
      workspaceId: routeDeps.workspaceId,
      at: nowIso({ clock: routeDeps.clock }),
      actor: { principalId, pluginId: "assistant" },
    },
  };
}

/**
 * The post-confirmation half of `plugins_uninstall` (t91 F2.2): re-discovers, then uninstalls only if the plugin is
 * still the name and version the dialog showed. A change is a not-removed RESULT (ADR-055 Decision 6), the same union
 * member `expired`/`abandoned` use; every other refusal still propagates undecorated, per this file's convention.
 * @complexity one discovery scan plus `uninstallPlugin`.
 */
async function uninstallConfirmedPlugin(
  routeDeps: PluginsToolDeps,
  preview: PluginUninstallPreview,
  principalId: string,
): Promise<unknown> {
  const { pluginId } = preview;
  try {
    const result = await uninstallPlugin(await uninstallRequestFor(routeDeps, pluginId, principalId), { confirmedPreview: preview });
    return { pluginId, trashed: result.trashed };
  } catch (error) {
    if (!(error instanceof PluginChangedSincePreviewError)) throw error;
    return {
      pluginId,
      uninstalled: false,
      cancelled: false,
      reason: "changed-since-confirmation",
      note:
        `'${pluginId}' changed after the user was asked: the confirmation showed ${preview.name} version ${preview.version}, and that ` +
        "is no longer what is installed. Nothing was removed. Call plugins_uninstall again so the user can review and confirm what is installed now.",
    };
  }
}

/**
 * What a caller must still do after a successful toggle, per family and direction.
 *
 * This exists because "enabled: true" alone was actively misleading. The activation record is
 * durable and re-read per run, so the GATE moves immediately — but a plugin's own tool
 * (`agent_plugin_<id>` for Agent Plugins, a capability tool for site plugins) is registered once, at
 * agent-daemon boot, and the `search_tools` index is a one-shot snapshot taken right after
 * (`agent-daemon-server.ts`). So a freshly enabled plugin's TOOL is not callable in the daemon that
 * is running now. Reporting plain success and letting the operator discover that themselves is the
 * confusion this field exists to prevent.
 *
 * The two directions are deliberately NOT symmetric, for BOTH families, and the notes say so. DISABLE
 * lands immediately on the tool as well, because each tool's own `ToolPolicy` re-reads the activation
 * record per call: `agent_plugin_<id>` via `features/agent-plugins/tool-registrations.ts`'s REVOCATION
 * note, `plugin_capability_<id>` via `capability-tool-registrations.ts`'s "Revocation" section
 * (t91 F1.2). ENABLE still needs a restart, because there is no registration to re-admit: an
 * append-only `ToolRegistry` has nothing to un-skip.
 *
 * Neither Agent Plugin note may imply that the plugin's provisioned external MCP connections were
 * turned off — they never are (`agent-plugins/federate-mcp.ts`'s header, "THE ROW SURVIVES"), so the
 * disable note says so (t91 F1.3). Turning that connection off DOES stop them at once: the per-call connection gate
 * re-reads the row on every call and refuses once the connection is disabled, deleted, OAuth-disconnected, or
 * narrowed (`external-mcp-revocation.ts`), even though the tool stays admitted and listed — and its live session, if
 * any, stays open — until restart (`mcp-federation/reload.ts`), which is why the External MCP routes still answer
 * `restartRequired: true`.
 * @complexity O(1).
 */
function restartNoteFor(request: SetEnabledRequest): string {
  if (request.family === "agent-plugin") {
    return request.enabled
      ? `Enabled and saved. Read its guidance now with load_agent_plugin({pluginId:"${request.pluginId}"}) and use ` +
          `agent_plugin_connect for account sign-in when needed. Its legacy agent_plugin_${request.pluginId} tool may ` +
          `still be unavailable in this session; use the available tools and explain any remaining limitation. Do not ask the person to restart Tovu.`
      : `Disabled and saved. This takes effect immediately, with no restart: the activation record is re-read at ` +
          `the start of every run AND again before every agent_plugin_${request.pluginId} call, so the plugin's own ` +
          `tool stops answering at once rather than lingering until Tovu restarts. This does NOT change any external ` +
          `MCP server connection the plugin set up: if an operator turned one on, its mcp__<server>__* tools keep ` +
          `working until that connection is disabled under Integrations → External MCP.`;
  }
  return request.enabled
    ? "Enabled and saved. The plugin's hooks are live now, but any tool it contributes is registered only when the agent " +
        "daemon starts — tell the user Tovu has to be restarted before that tool can be called."
    : "Disabled and saved. This takes effect immediately, with no restart: any tool this plugin contributed stays listed " +
        "in the running daemon until Tovu restarts, but every call to it is refused from now on.";
}

/**
 * The Agent Plugin branch. Reuses `agent-plugins/set-enabled.ts` — the SAME composition
 * `AGENT_PLUGIN_SET_ENABLED` (the admin route) calls, so there is one writer and one definition of
 * "installed in this workspace", not a second copy that could drift.
 * @complexity O(d) in installed-digest count plus one small file rewrite.
 */
async function applyAgentPluginDecision(routeDeps: PluginsToolDeps, principalId: string, request: SetEnabledRequest): Promise<unknown> {
  try {
    const input = {
      workspaceId: routeDeps.workspaceId,
      pluginId: request.pluginId,
      enabled: request.enabled,
      actor: principalId,
    };
    const result = await (routeDeps.setAgentPluginEnabled
      ? routeDeps.setAgentPluginEnabled({ ...input, agentPluginLayout: routeDeps.agentPluginLayout })
      : requireAgentPluginHost(routeDeps).setEnabled(input));
    // Enabling an Agent Plugin also provisions its auto-admitted MCP servers, exactly as the admin
    // route's enable branch does; disabling has nothing to provision. Without this, the same logical
    // enable produced a partially enabled plugin in chat while the admin toggle produced the
    // documented disabled connection rows — see this file's header.
    //
    // Best-effort: provisions `pluginId`'s auto-admitted remote MCP servers into the external-MCP store
    // on a successful enable. Calls the SAME two primitives
    // (`resolveAgentPluginMcpServers` + `provisionAgentPluginMcpServers`) the admin route's own
    // `provisionAgentPluginMcpServersBestEffort` does, so the in-chat enable and the admin toggle have
    // identical side effects. Create-if-absent, never clobbering an existing row (`federate-mcp.ts`'s
    // header); a failure is logged, never thrown, matching that route's own fail-open posture — the
    // plugin's own activation, the operation this tool is named for, must not fail because one MCP row
    // could not be written. O(s) in the plugin's declared server count.
    if (result.enabled) {
      await requireAgentPluginHost(routeDeps).provisionMcp({ pluginId: request.pluginId, principalId }, {});
    }
    return {
      changed: true,
      cancelled: false,
      family: request.family,
      agentPlugin: { pluginId: result.pluginId, enabled: result.enabled },
      warnings: result.warnings ?? [],
      restartRequired: result.enabled,
      note: restartNoteFor(request),
    };
  } catch (error) {
    // Re-classified at the tool boundary for the same reason `readFamily` throws one: an id that is
    // not installed here IS a caller-input problem with an actionable fix (search first, then use a
    // real id), and a bare `Error` would reach the model as an opaque failure instead. The message
    // carries only the plugin id the caller already sent — nothing internal leaks.
    if (error instanceof AgentPluginNotInstalledError) throw new ToolInputError({ message: error.message });
    if (error instanceof AgentPluginLinkedError) return linkedFaceResult(request, error);
    // t91 F1.1/R2 (2026-09-16): nothing changed, so this is a RESULT the model can relay — matching
    // ADR-055 Decision 6's `changed: false` shape — not a redacted failure. See
    // `activationsRefusalResult` below.
    const refusal = activationsRefusalResult(request, error);
    if (refusal !== undefined) return refusal;
    throw error;
  }
}

/**
 * Pre-flight for an Agent Plugin ENABLE, run before the confirmation dialog: the not-changed result when this
 * workspace's activations.json cannot be read or cannot be locked, otherwise `undefined`.
 *
 * `applyAgentPluginDecision` would refuse the same write anyway, but only after a human had confirmed it — asking
 * them to approve something that cannot happen, then reporting "nothing changed" (t91 §7.2). This reads the file
 * with the same strict reader every writer uses, so it refuses exactly the files the write would. The file can
 * still break while the dialog is open; `applyAgentPluginDecision`'s own catch covers that. Disabling raises no
 * dialog, so it needs no pre-flight.
 *
 * @complexity One small file read, plus `assertAgentPluginActivationsWritable`'s own cross-process lock
 * acquisition and release — not a pure read: it also creates the workspace root if it is absent.
 */
async function unwritableAgentPluginActivationsResult(routeDeps: PluginsToolDeps, request: SetEnabledRequest): Promise<unknown> {
  try {
    if (routeDeps.assertAgentPluginActivationsWritable) {
      await routeDeps.assertAgentPluginActivationsWritable({ workspaceRoot: routeDeps.agentPluginLayout.forWorkspace(routeDeps.workspaceId).root });
    } else {
      await requireAgentPluginHost(routeDeps).assertWritable({}, {});
    }
    return undefined;
  } catch (error) {
    const refusal = activationsRefusalResult(request, error);
    if (refusal !== undefined) return refusal;
    throw error;
  }
}

/**
 * Pre-flight for an Agent Plugin ENABLE, run before the confirmation dialog: the host-incompatible result when any
 * installed revision of the plugin declares a host range this Tovu does not satisfy, otherwise `undefined`.
 *
 * Same reason as {@link unwritableAgentPluginActivationsResult}: the write would refuse it anyway, but only after a
 * human had approved something that cannot happen. Uses the lifecycle owner's own compatibility check against the
 * same contract version, and, like its enable, requires every installed revision of the id to pass. `hostOk` does
 * not depend on other plugins' capabilities, so none are supplied.
 * @complexity O(p) in installed-plugin count.
 */
async function hostIncompatibleEnableResult(routeDeps: PluginsToolDeps, request: SetEnabledRequest): Promise<unknown> {
  const revisions = (await listInstalledAgentPlugins(routeDeps)).filter(plugin => plugin.pluginId === request.pluginId);
  const incompatible = revisions.some(revision => !checkAgentPluginCompatibility({ manifest: revision, hostVersion: AGENT_PLUGIN_CONTRACT_VERSION, activeProvides: [] }).hostOk);
  return incompatible ? hostIncompatibleResult(request, new AgentPluginHostIncompatibleError({ pluginId: request.pluginId })) : undefined;
}

/** A provider plugin's assistant face has no switch of its own (`agent-plugins/provider-plugin-link.ts`):
 *  nothing changed, and the note names the provider plugin to switch instead. @complexity O(1). */
function linkedFaceResult(request: SetEnabledRequest, error: AgentPluginLinkedError): unknown {
  return { changed: false, cancelled: false, family: request.family, pluginId: request.pluginId, restartRequired: false,
    reason: "linked", code: error.code, providerPluginId: error.providerPluginId, note: `Nothing changed. ${error.message}` };
}

/** Pre-flight: a linked face is refused before the confirmation dialog, not after it. A link that cannot be
 *  read here is left to the write, which checks again. @complexity One manifest read per installed revision. */
async function linkedFaceEnableResult(routeDeps: PluginsToolDeps, request: SetEnabledRequest): Promise<unknown> {
  const ports = bindProviderFacePorts({ workspaceRoot: () => routeDeps.agentPluginLayout.forWorkspace(routeDeps.workspaceId).root });
  const providerPluginId = await linkedProviderOf({ ports, pluginId: request.pluginId }).catch(() => undefined);
  return providerPluginId === undefined ? undefined : linkedFaceResult(request, new AgentPluginLinkedError({ pluginId: request.pluginId, providerPluginId }));
}

/** Every Agent Plugin enable pre-flight, in order; the first not-changed result wins. @complexity As its three checks. */
async function agentPluginEnablePreflight(routeDeps: PluginsToolDeps, request: SetEnabledRequest): Promise<unknown> {
  return (await unwritableAgentPluginActivationsResult(routeDeps, request)) ?? (await linkedFaceEnableResult(routeDeps, request)) ?? hostIncompatibleEnableResult(routeDeps, request);
}

/** An interrupted update of this plugin waits for boot recovery (`PLUGIN_UPDATE_PENDING`, or an
 *  unreadable recovery record): its on/off decision is frozen until then, the same 409 the admin
 *  switch answers. Nothing changed, so an ADR-055 Decision 6 result. @complexity O(1). */
function updatePendingResult(request: SetEnabledRequest, error: AgentPluginUpdateError): unknown {
  return {
    changed: false,
    cancelled: false,
    family: request.family,
    pluginId: request.pluginId,
    restartRequired: false,
    reason: "update-pending",
    code: error.code,
    note: `Nothing changed: an interrupted update of '${request.pluginId}' is still waiting to be recovered, so it was NOT ` +
      `${request.enabled ? "enabled" : "disabled"}. ${updateJournalNextStep(error)}`,
  };
}

/** Only a pending update recovers at start. Any other journal refusal (an unreadable record, an
 *  unsafe recorded path) survives a restart, so telling the user to restart would loop them.
 *  @complexity O(1). */
function updateJournalNextStep(error: AgentPluginUpdateError): string {
  return error.code === "PLUGIN_UPDATE_PENDING"
    ? "Tell the user to restart Tovu (recovery runs at start) and then try again."
    : `Its update recovery record needs manual repair (${error.code}); restarting Tovu will not fix it. Tell the user an operator has to repair it first.`;
}

/** The plugin declares a host range this Tovu does not satisfy, so it cannot be enabled: the same
 *  refusal the admin switch answers with 409 `PLUGIN_HOST_INCOMPATIBLE`. Nothing changed, so it is
 *  an ADR-055 Decision 6 result, not a failure. @complexity O(1). */
function hostIncompatibleResult(request: SetEnabledRequest, error: AgentPluginHostIncompatibleError): unknown {
  return {
    changed: false,
    cancelled: false,
    family: request.family,
    pluginId: request.pluginId,
    restartRequired: false,
    reason: "host-incompatible",
    code: error.code,
    note: `Nothing changed: '${request.pluginId}' is not made for this Tovu version, so it was NOT enabled. ` +
      "Tell the user it needs a version of the plugin that supports this Tovu.",
  };
}

/** ADR-055 Decision 6 shape: nothing changed, so it is a RESULT the model can relay, not a redacted
 *  failure. The host path and parse detail stay in the server log via the `console.warn` below;
 *  `note` carries only the fixed, path-free E3 text.
 *  @complexity O(1). */
function activationsUnreadableResult(request: SetEnabledRequest, error: AgentPluginActivationsUnreadableError): unknown {
  console.warn(`[agent-plugins] '${request.pluginId}': plugins_set_enabled refused — ${error.message}`);
  return {
    changed: false,
    cancelled: false,
    family: request.family,
    pluginId: request.pluginId,
    restartRequired: false,
    reason: "activations-unreadable",
    note:
      `Nothing changed: this workspace's Agent Plugin activation record could not be read, so '${request.pluginId}' was NOT ` +
      `${request.enabled ? "enabled" : "disabled"}. Tell the user an operator has to repair activations.json first (the server ` +
      "log names the file and the fault); until then every Agent Plugin tool call in this workspace is refused.",
  };
}

/** t91 R2 (2026-09-16): another Tovu process held the cross-process activations.json write lock and
 *  the wait timed out, or this process lost the lock before it could commit. Same ADR-055 Decision 6
 *  shape as {@link activationsUnreadableResult}: nothing changed, so it is a RESULT the model can
 *  relay. The host lock path stays in the server log via `console.warn`; `note` is fixed and
 *  path-free.
 *  @complexity O(1). */
function activationsBusyResult(request: SetEnabledRequest, error: AgentPluginActivationsBusyError): unknown {
  console.warn(`[agent-plugins] '${request.pluginId}': plugins_set_enabled refused — ${error.message}`);
  return {
    changed: false,
    cancelled: false,
    family: request.family,
    pluginId: request.pluginId,
    restartRequired: false,
    reason: "activations-busy",
    note:
      `Nothing changed: another Tovu process was writing this workspace's Agent Plugin activation record at the same ` +
      `moment, so '${request.pluginId}' was NOT ${request.enabled ? "enabled" : "disabled"}. Tell the user nothing was ` +
      "changed and to try again in a moment; if it keeps happening, the server log names the lock file.",
  };
}

/** Dispatches a thrown activation error to the matching not-changed RESULT — Unreadable to
 *  {@link activationsUnreadableResult}, Busy to {@link activationsBusyResult} — or `undefined` for
 *  any other error, so the caller can rethrow it unchanged. Shared by both
 *  {@link applyAgentPluginDecision} and {@link unwritableAgentPluginActivationsResult} so the two
 *  call sites classify activation failures identically.
 *  @complexity O(1). */
function activationsRefusalResult(request: SetEnabledRequest, error: unknown): unknown | undefined {
  if (error instanceof AgentPluginHostIncompatibleError) return hostIncompatibleResult(request, error);
  if (error instanceof AgentPluginUpdateError) return updatePendingResult(request, error);
  if (error instanceof AgentPluginActivationsUnreadableError) return activationsUnreadableResult(request, error);
  if (error instanceof AgentPluginActivationsBusyError) return activationsBusyResult(request, error);
  return undefined;
}

/**
 * The `.tovu-plugin` site/runtime branch — unchanged in mechanism from before this file grew a
 * second family: the SAME `executeCommand` composition `routes/admin/plugins/set-enabled.ts` uses,
 * with the same `captureInverse`/`rollback` pair.
 * @complexity O(p) in discovered-plugin count, plus the command gateway's own writes.
 */
async function applySiteRuntimeDecision(routeDeps: PluginsToolDeps, principalId: string, request: SetEnabledRequest, optional: { discovery?: readonly PluginDiscoveryRecord[] } = {}): Promise<unknown> {
  const { pluginId, enabled } = request;
  // Reuse the manifest that passed the post-approval identity check, avoiding another discovery
  // read between checking the approved version/digest and the activation owner loading it.
  const discovery = optional.discovery ?? await routeDeps.discoverPlugins();
  // Captured by `captureInverse` below, reused verbatim by `rollback` — mirrors
  // `routes/admin/plugins/set-enabled.ts`'s identical `priorActivation` shape exactly, since this
  // handler IS that route's own `executeCommand` composition.
  let priorActivation: PluginActivationRecord | null = null;

  const { result } = await executeCommand<{ activation: PluginActivationRecord }>({
    deps: {
      clock: routeDeps.clock,
      idGen: routeDeps.idGen,
      changeSets: routeDeps.changeSets,
      outbox: routeDeps.outbox,
      authorize: routeDeps.authorize,
    },
    command: {
      workspaceId: routeDeps.workspaceId,
      actor: { id: principalId, kind: AGENT_TOOL_PRINCIPAL_KIND },
      summary: `Agent set plugin '${pluginId}' enabled=${enabled}`,
      permission: "admin.plugins.enable",
    },
    mutation: {
      entityType: "plugin-activation",
      entityId: pluginId,
      operation: "update",
      captureInverse: async () => {
        priorActivation = await routeDeps.pluginActivationRepo.getActivation({ workspaceId: routeDeps.workspaceId, pluginId });
        return { enabled: priorActivation?.enabled ?? false };
      },
      execute: () =>
        setPluginEnabled({
          deps: {
            clock: routeDeps.clock,
            repo: routeDeps.pluginActivationRepo,
            discovery,
            onEnabled: routeDeps.onPluginEnabled,
            onDisabled: routeDeps.onPluginDisabled,
          },
          input: { workspaceId: routeDeps.workspaceId, pluginId, enabled },
        }),
      rollback: async () => {
        if (priorActivation) {
          await routeDeps.pluginActivationRepo.save(priorActivation);
        } else {
          await routeDeps.pluginActivationRepo.deleteActivation({ workspaceId: routeDeps.workspaceId, pluginId });
        }
        if (priorActivation?.enabled) {
          await routeDeps.onPluginEnabled(pluginId);
        } else {
          routeDeps.onPluginDisabled(pluginId);
        }
      },
    },
  });

  const record = discovery.find((r) => r.id === pluginId);
  if (!record) throw new ToolInputError({ message: `plugin '${pluginId}' was not found in the current discovery snapshot` });
  if (((priorActivation as PluginActivationRecord | null)?.enabled ?? false) !== result.activation.enabled) routeDeps.tracker?.capture({ name: "plugin_toggled", userId: principalId }, { properties: { pluginId: record.id, pluginKind: "cms", enabled: result.activation.enabled, source: "assistant" } });
  return {
    changed: true,
    cancelled: false,
    family: request.family,
    plugin: toAdminPluginResponse(record, result.activation),
    restartRequired: enabled,
    note: restartNoteFor(request),
  };
}

/** The `admin.plugins.enable` check every write path in this file runs, through the kit's evaluator.
 * @complexity O(1) plus one authorization evaluation. */
async function requireEnablePermission(
  routeDeps: PluginsToolDeps,
  required: { readonly principalId: string; readonly entityType: string; readonly entityId: string },
): Promise<void> {
  await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: required.principalId, permission: "admin.plugins.enable" }, { entityType: required.entityType, entityId: required.entityId });
}

/** `plugins_set_enabled`'s permission check, scoped to the family's own entity type. @complexity O(1) plus one evaluation. */
function requireSetEnabledPermission(routeDeps: PluginsToolDeps, required: { readonly principalId: string; readonly request: SetEnabledRequest }): Promise<void> {
  const { principalId, request } = required;
  return requireEnablePermission(routeDeps, { principalId, entityType: request.family === "agent-plugin" ? "agent-plugin" : "plugin", entityId: request.pluginId });
}

/** What the owner's consent to a site-package enable rests on. Only a site-sourced `.tovu-plugin`
 * that is being enabled can be "sealed here" or carry a capability set; every other call has none. */
interface SiteConsent {
  readonly sealedHere: boolean;
  readonly capabilities: readonly string[] | undefined;
  readonly added: readonly string[];
}

/** The site-sourced record a site-runtime ENABLE's approval identity was read from, else `undefined`
 * (a disable, an Agent Plugin, or a built-in package). @complexity O(p) in the snapshot's plugin count. */
function siteRecordBeingEnabled(
  required: { readonly request: SetEnabledRequest; readonly identity: PluginApprovalIdentity | undefined },
): PluginDiscoveryRecord | undefined {
  const { request, identity } = required;
  const record = identity?.discovery?.find(record => record.id === request.pluginId);
  return request.enabled && request.family === "site-runtime" && record?.source === "site" ? record : undefined;
}

/** Reads the seal and the capabilities beyond the owner's last approval, in that order, for the
 * record the approval identity was read from (so `record.version` IS the identity's version).
 * @complexity O(c) in the manifest's declared capability count, plus two source-port reads. */
async function siteConsentFor(
  routeDeps: PluginsToolDeps,
  required: { readonly request: SetEnabledRequest; readonly identity: PluginApprovalIdentity | undefined },
): Promise<SiteConsent> {
  const { request } = required;
  const record = siteRecordBeingEnabled(required);
  if (record === undefined) return { sealedHere: false, capabilities: undefined, added: [] };
  const sealedHere = routeDeps.pluginSource ? await routeDeps.pluginSource.isSealedHere({ id: request.pluginId, version: record.version }, {}) : false;
  const capabilities = record.manifest ? pluginCapabilitySet({ manifest: record.manifest }) : undefined;
  const added = capabilities === undefined ? [] : addedPluginCapabilities({ approved: await routeDeps.pluginSource?.readApproval({ id: request.pluginId }, {}), next: capabilities });
  return { sealedHere, capabilities, added };
}

/** Whether this enable must show the owner a card (before any remembered approval is consulted).
 * @complexity O(1) plus the policy's own decision. */
function enableNeedsConfirmation(routeDeps: PluginsToolDeps, consent: SiteConsent): boolean {
  // Consent gap (2026-10-12): "sealed here" may mean sealed by the assistant itself, so it skips
  // the card only when this version adds nothing beyond what the owner last approved.
  return (consent.sealedHere && consent.capabilities === undefined) || (routeDeps.pluginSourcePolicy?.confirmEnable({ sealedHere: consent.sealedHere, added: consent.added }, {}) ?? true);
}

/** One prepared `plugins_set_enabled` call: everything the card names and the write re-checks. */
interface SetEnabledPrepared {
  readonly request: SetEnabledRequest;
  readonly identity: PluginApprovalIdentity | undefined;
  readonly refusal: unknown;
  readonly confirm: boolean;
  readonly capabilities: readonly string[] | undefined;
  readonly added: readonly string[];
}

/** parse -> authorize -> (Agent Plugin enable: activations.json writable?) -> identity -> consent
 * inputs. See the `plugins_set_enabled` handler's own comment for why this order is load-bearing.
 * @complexity One family discovery scan plus the source/policy reads in {@link siteConsentFor}. */
async function prepareSetEnabled(routeDeps: PluginsToolDeps, required: { readonly ctx: ToolExecutionContext }): Promise<SetEnabledPrepared> {
  const { ctx } = required;
  const request = readSetEnabledRequest(ctx.input);
  await requireSetEnabledPermission(routeDeps, { principalId: ctx.principal.id, request });
  const refusal = request.enabled && request.family === "agent-plugin" ? await agentPluginEnablePreflight(routeDeps, request) : undefined;
  const identity = request.enabled && refusal === undefined ? await pluginApprovalIdentity({ deps: routeDeps, request }) : undefined;
  const consent = await siteConsentFor(routeDeps, { request, identity });
  return { request, identity, refusal, confirm: enableNeedsConfirmation(routeDeps, consent), capabilities: consent.capabilities, added: consent.added };
}

/** Re-reads an enable's identity after consent; a different key means the human approved something
 * that is no longer what is installed. Disabling binds no identity.
 * @throws {ToolInputError} `PLUGINS_STALE_APPROVAL` when the version or digest changed.
 * @complexity One family discovery scan. */
async function currentApprovedIdentity(
  routeDeps: PluginsToolDeps,
  required: { readonly request: SetEnabledRequest; readonly identity: PluginApprovalIdentity | undefined },
): Promise<PluginApprovalIdentity | undefined> {
  const { request, identity } = required;
  if (!request.enabled) return undefined;
  const current = await pluginApprovalIdentity({ deps: routeDeps, request });
  if (current.key !== identity?.key) throw new ToolInputError({ message: "PLUGINS_STALE_APPROVAL: The plugin version or digest changed. Review and approve it again. Nothing was changed." });
  return current;
}

/** Fails CLOSED without an interactive transport: degrading to "remove it and mention we could
 * not ask" would make confirmation decorative in precisely the contexts that most need it.
 * A cancelled run must not leave a dialog holding a call nobody is listening to, nor hold this
 * handler open until the idle deadline. Core/host approval ports now own that abort lifecycle.
 * ADR-055 Decision 6: a no-answer is a RESULT, not an exception. Nothing was changed or removed
 * either way, and the model is still alive to read this and say something sensible.
 *
 * The confirmed (or card-free) half: refusal -> re-authorize -> identity unchanged -> not cancelled
 * -> record the approval -> write.
 * @complexity One family discovery scan plus the family's own write. */
async function runSetEnabled(
  routeDeps: PluginsToolDeps,
  required: { readonly ctx: ToolExecutionContext; readonly prepared: SetEnabledPrepared },
): Promise<unknown> {
  const { ctx, prepared: { request, identity, refusal, confirm, capabilities } } = required;
  if (refusal !== undefined) return refusal;
  await requireSetEnabledPermission(routeDeps, { principalId: ctx.principal.id, request });
  const currentIdentity = await currentApprovedIdentity(routeDeps, { request, identity });
  // A cancelled run must neither keep a card open until the deadline nor grant capability.
  if (ctx.signal.aborted) return { changed: false, ...notConfirmedResult({ confirmed: false, reason: "abandoned" }) };
  // The owner approved exactly these capabilities (the identity key pins the manifest). Recorded
  // before the write so a failed record leaves the plugin off rather than enabled unrecorded.
  if (confirm && capabilities !== undefined && routeDeps.pluginSource) await routeDeps.pluginSource.recordApproval({ id: request.pluginId, capabilities }, {});
  return request.family === "agent-plugin"
    ? applyAgentPluginDecision(routeDeps, ctx.principal.id, request)
    : applySiteRuntimeDecision(routeDeps, ctx.principal.id, request, { discovery: currentIdentity?.discovery });
}

/**
 * This domain's model-facing allowlist (`contracts/core/model-facing-tool-errors.ts`). Only the
 * conflict refusal is listed (2026-10-04): its message names plugin ids/names and the manifest's own
 * declared names — nothing internal — and it is the one refusal an agent can act on by itself
 * ("turn the other plugin off first"). Without the rule it reached the model as a redacted
 * INTERNAL_ERROR, indistinguishable from a crash. Every other error here keeps its existing
 * classification, unchanged.
 */
const PLUGINS_MODEL_FACING_ERRORS: readonly ModelFacingErrorRule[] = [
  {
    error: PluginConflictError,
    code: "PLUGINS_CONFLICT",
    guidance: "Tell the user which plugin holds the name; disabling that plugin first is their call",
  },
];

export function buildPluginsRegistrations(routeDeps: PluginsToolDeps, surfaces: AssistantSurfaceDeps): ToolRegistration[] {
  const handlers: Record<string, ToolHandler> = {
    plugins_list: async (ctx) => {
      requireNoInput({ input: ctx.input });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.plugins.read" });

      const discovery = await routeDeps.discoverPlugins();
      const conflicts = (await routeDeps.listPluginConflicts?.()) ?? new Map<string, readonly PluginConflict[]>();
      const plugins = await Promise.all(
        discovery.map(async (record) => {
          const activation = await routeDeps.pluginActivationRepo.getActivation({ workspaceId: routeDeps.workspaceId, pluginId: record.id });
          return toAdminPluginResponse(record, activation, { conflicts: conflicts.get(record.id) ?? [] });
        }),
      );
      const agentPlugins = await listAgentPluginsForResponse(routeDeps);
      return { plugins, agentPlugins };
    },

    /**
     * ONE tool, BOTH plugin families. See `agent-tools.ts`'s header for why enable/disable is
     * consolidated here while install/uninstall deliberately are not, and
     * `set-enabled-confirmation-ui.ts`'s for why enabling asks a human and disabling does not.
     *
     * Order is load-bearing: parse -> authorize -> (Agent Plugin enable: activations.json readable?) -> confirm -> write. The explicit
     * `requireToolPermission` ahead of the dialog is NOT a second policy (the site-runtime branch's
     * `executeCommand` still performs its own check on the same permission with the same evaluator,
     * per ADR-021 §2) — it gates SHOWING THE DIALOG, which is its own disclosure: a principal with no
     * `admin.plugins.enable` grant must not be able to make a confirmation prompt appear in a human's
     * chat naming a plugin, let alone reach the write behind it.
     */
    plugins_set_enabled: approvalToolHandler({ surfaces,
      prepare: ({ ctx }) => prepareSetEnabled(routeDeps, { ctx }),
      describe: ({ prepared: { request, identity, added } }) => describeEnableApproval({
        subject: { family: request.family, pluginId: request.pluginId, version: identity?.version, label: identity?.label, adds: added },
      }),
      run: ({ ctx, prepared }) => runSetEnabled(routeDeps, { ctx, prepared }),
    }, { flag: "changed", ask: ({ prepared }) => prepared.request.enabled && prepared.refusal === undefined && prepared.confirm,
      rememberKey: ({ prepared }) => prepared.request.enabled ? prepared.identity?.key : undefined,
      remembered: routeDeps.nativeApprovalMemory,
      declined: ({ reason, prepared }) => ({ changed: false, family: prepared?.request.family,
        pluginId: prepared?.request.pluginId, restartRequired: false, ...notConfirmedResult({ confirmed: false, reason }) }),
    }),

    /**
     * ONE tool, BOTH plugin families (S4, 2026-09-24) — the same merge `plugins_set_enabled` above
     * got on 2026-09-09, for the identical reason: two near-identically-named uninstall tools
     * (`plugins_uninstall` and the now-deleted `agent_plugins_uninstall`) is the exact confusion this
     * catalog exists to prevent, and the operator asking to "uninstall the Higgsfield plugin" does not
     * know which of Tovu's two plugin systems that word means either.
     *
     * The 'site-runtime' branch is UNCHANGED: mirrors `routes/admin/plugins/uninstall.ts`'s own
     * business rules exactly — same permission, same `uninstallPlugin()` module, same pre-bound Trash
     * removal binding. NOT wrapped in `executeCommand` — matching that route's own deliberate choice
     * (`Jini/packages/plugins/src/host/uninstall.ts`'s header: "there is no meaningful 'restore the prior state' for deleted bytes"),
     * so there is nothing here for a `captureInverse`/`rollback` pair to capture. That is a statement
     * about revertability, not about consent — the two are orthogonal, and this DOES now confirm
     * (2026-09-16, see `agent-tools.ts`'s header). Order is load-bearing: parse -> authorize -> preview
     * -> confirm -> re-discover and write only if the plugin is still what the dialog showed.
     * `previewUninstallPlugin` runs BEFORE the dialog so an unknown, built-in, or still-enabled plugin
     * is refused without ever asking a human to approve an uninstall that was never going to happen.
     *
     * The 'agent-plugin' branch delegates to `runAgentPluginUninstall` (`agent-plugins/
     * uninstall-tool.ts`) for its ENTIRE order (permission, preview-or-refusal, confirm, write) —
     * unlike `plugins_set_enabled`, whose single pre-branch `requireToolPermission` call covers both
     * families, this tool's permission check stays INSIDE each branch, exactly where the deleted
     * standalone tool ran it. Both branches reuse the SAME held-open exchange
     * (`uninstall-confirmation-ui.ts` in each family's own module), and both redeem through this one
     * `plugins_uninstall` id — see `PLUGINS_UNINSTALL_TOOL_ID` in each.
     */
    plugins_uninstall: async (ctx, optional = {}) => {
      ctx = { ...ctx, input: structuredClone(ctx.input), principal: { ...ctx.principal }, run: { ...ctx.run } };
      const input = requireInputRecord({ input: ctx.input });
      const family = readFamily(input);
      const pluginId = requireString({ input: input, key: "pluginId" });

      if (family === "agent-plugin") return requireAgentPluginHost(routeDeps).uninstall({ surfaces, ctx, pluginId, executionOptions: optional }, {});

      await requireEnablePermission(routeDeps, { principalId: ctx.principal.id, entityType: "plugin", entityId: pluginId });

      const preview = await previewUninstallPlugin(await uninstallRequestFor(routeDeps, pluginId, ctx.principal.id)); // throws PluginNotFoundError/NotUninstallableError/EnabledError BEFORE any dialog

      return approvalToolHandler({ surfaces,
        prepare: async () => preview,
        describe: ({ prepared }) => describeUninstallApproval({ preview: prepared }),
        run: async ({ ctx: approvedCtx, prepared }) => {
          await requireEnablePermission(routeDeps, { principalId: approvedCtx.principal.id, entityType: "plugin", entityId: pluginId });
          if (approvedCtx.signal.aborted) return { uninstalled: false, ...notConfirmedResult({ confirmed: false, reason: "abandoned" }) };
          return uninstallConfirmedPlugin(routeDeps, prepared, approvedCtx.principal.id);
        },
      }, { flag: "uninstalled", declined: ({ reason }) => ({ pluginId, uninstalled: false, ...notConfirmedResult({ confirmed: false, reason }) }) })(ctx, optional);
    },
  };

  // No `unwiredToolIds`: Plugins wires its ENTIRE catalog, same tripwire discipline as Forms.
  return buildDomainRegistrations({ metadata: toolMetadata,
    domain: "plugins",
    catalogModule: "features/plugin-runtime/agent-tools.ts",
    catalog: CATALOG_BY_ID,
    handlers: withModelFacingErrors({ handlers, rules: PLUGINS_MODEL_FACING_ERRORS }),
    derivedRisk: pluginsDerivedRisk,
  });
}

/**
 * Contributes Plugins' AI tools to the assistant's catalog — called once by
 * `server/tool-catalog-manifest.ts`'s `installFirstPartyToolContributors()`, not by importing this
 * module. `assistant/tool-registrations.ts` no longer imports `buildPluginsRegistrations`/
 * `pluginsDerivedRisk` by name; this is the seam that replaced it (2026-08-17, Stage 2 batch 2).
 * Unlike `database` (tried and reverted earlier in this batch), this domain's own imports are all
 * `core/commands` plus its own sibling files (`admin-response.ts`, `Jini/packages/plugins/src/host/activation.ts`, `agent-tools.ts`,
 * `Jini/packages/plugins/src/host/node/discovery.ts`) — it does not reach `features/database`/`db` at all, so it does not carry that
 * domain's round-trip risk. Every importer outside `server/*` is none — nothing else imports this
 * domain by name.
 */
export function contributePluginsTools(
  required: { createPluginHost?: (required: { deps: PluginsToolDeps }) => PluginHostPort } = {},
  _optional: Record<string, never> = {},
): ToolContributor {
  return { domain: "plugins", build: (deps, surfaces) => buildPluginsRegistrations({
    ...deps, pluginHost: deps.pluginHost ?? required.createPluginHost?.({ deps }),
  }, surfaces), risk: pluginsDerivedRisk };
}

/**
 * @file ADR-023 §5/§6 (T5 fix, round-2 revision) — permanent plugin-ID retirement plus the
 * two-track fail-closed namespace-adoption guard.
 *
 * A `pluginId` is permanently retired the moment it is first minted (this record is never
 * deleted, including after a future uninstall+purge — no purge/uninstall flow exists in this
 * codebase yet, so this module's row is never actually removed by anything today; that absence
 * IS the correct behavior per §6's "retirement is permanent" rule, not a gap).
 *
 * Two-track adoption rule (§6): a SUBSEQUENT declare for an already-identified `pluginId` is
 * allowed automatically when its provenance is unchanged from what's on record (the common case —
 * the same first-party module re-declaring at every boot), OR when both the stored and incoming
 * provenance carry a matching signature (track a — "verified same-key signature"). Anything else
 * (no signature on one/both sides, or a mismatch) requires explicit operator consent (track b) —
 * surfaced here as a typed refusal, since no consent-prompt UI exists in this codebase yet.
 *
 * Signature verification here is a same-string comparison, not real cryptographic verification —
 * ADR-004 leaves `signature` optional and no signing/verification infrastructure exists anywhere
 * in this codebase yet (confirmed: ADR-023 §6 itself says the same — "track (a) will rarely fire
 * ... track (b) is the load-bearing path" — this is the intended, honest degraded behavior, not
 * an unfinished shortcut).
 */
import { sql } from "kysely";

import { columnTypeSql } from "../../platform/db/kernel/dialect.js";
import { type PluginKernel, type PluginStore, pluginKernel } from "./plugin-store.js";

export interface PluginProvenance {
  sourceUrl: string;
  publisher: string;
  signature?: string;
}

export interface PluginIdentityRecord {
  pluginId: string;
  provenance: PluginProvenance;
  mintedAt: number;
}

export type NamespaceAdoptionDecision =
  | { allowed: true; track: "first-mint" | "unchanged" | "verified-signature" }
  | { allowed: false; track: "consent-required"; reason: string };

export async function ensurePluginIdentityTable(store: PluginStore): Promise<void> {
  const kernel = pluginKernel(store);
  const text = sql.raw(columnTypeSql(kernel.dialect, "TEXT"));
  await kernel.execute(sql`CREATE TABLE IF NOT EXISTS _plugin_identity (
       plugin_id ${text} PRIMARY KEY,
       source_url ${text} NOT NULL,
       publisher ${text} NOT NULL,
       signature ${text},
       minted_at ${sql.raw(columnTypeSql(kernel.dialect, "INTEGER"))} NOT NULL
     )`);
}

export async function getPluginIdentity(
  required: { db: PluginStore; pluginId: string },
  _optional: Record<string, never> = {}
): Promise<PluginIdentityRecord | null> {
  const { pluginId } = required;
  const row = await pluginKernel(required.db).run((db) =>
    db
      .selectFrom("_plugin_identity")
      .select(["plugin_id", "source_url", "publisher", "signature", "minted_at"])
      .where("plugin_id", "=", pluginId)
      .executeTakeFirst()
  );
  if (!row) return null;
  return {
    pluginId: row.plugin_id,
    provenance: { sourceUrl: row.source_url, publisher: row.publisher, ...(row.signature != null ? { signature: row.signature } : {}) },
    mintedAt: Number(row.minted_at),
  };
}

/** First-write-wins. Never called again for a `pluginId` once minted (see `checkNamespaceAdoption`). */
async function mintPluginIdentity(kernel: PluginKernel, pluginId: string, provenance: PluginProvenance): Promise<void> {
  await kernel.run((db) =>
    db
      .insertInto("_plugin_identity")
      .values({
        plugin_id: pluginId,
        source_url: provenance.sourceUrl,
        publisher: provenance.publisher,
        signature: provenance.signature ?? null,
        minted_at: Date.now(),
      })
      .execute()
  );
}

function provenanceEqual(a: PluginProvenance, b: PluginProvenance): boolean {
  return a.sourceUrl === b.sourceUrl && a.publisher === b.publisher && (a.signature ?? null) === (b.signature ?? null);
}

/**
 * Mints the identity record on first sight (always `allowed: true`). On a subsequent declare,
 * applies the two-track rule. Does NOT mutate the identity record on anything but first mint —
 * a provenance mismatch never silently overwrites the record on record (permanent retirement).
 */
export async function checkNamespaceAdoption(
  required: { db: PluginStore; pluginId: string; provenance: PluginProvenance },
  _optional: Record<string, never> = {}
): Promise<NamespaceAdoptionDecision> {
  const { pluginId, provenance } = required;
  const kernel = pluginKernel(required.db);
  await ensurePluginIdentityTable(kernel);
  // Read-then-mint: the lock keeps two first declares of one plugin from both minting.
  const existing = await kernel.transaction(async () => {
    await kernel.lockKey(`plugin-identity:${pluginId}`);
    const found = await getPluginIdentity({ db: kernel, pluginId });
    if (!found) await mintPluginIdentity(kernel, pluginId, provenance);
    return found;
  });
  if (!existing) return { allowed: true, track: "first-mint" };
  if (provenanceEqual(existing.provenance, provenance)) {
    return { allowed: true, track: "unchanged" };
  }
  if (existing.provenance.signature && provenance.signature && existing.provenance.signature === provenance.signature) {
    return { allowed: true, track: "verified-signature" };
  }
  return {
    allowed: false,
    track: "consent-required",
    reason: `pluginId '${pluginId}' has retained data from a previously-seen, provenance-mismatched artifact — explicit operator consent is required before adopting this namespace`,
  };
}

/**
 * @file SPIKE — the sample Tier-3 store plugin (C) + checkout.
 *
 * The simplest real plugin that owns tables: it DECLARES `p_store__products` and `p_store__orders`
 * (which core creates through the never-brick dataModule seam, B), seeds products, and exposes a
 * read API + a checkout the site route (D) renders. Tier-3 = trusted/first-party/local (ADR-024):
 * full access, honestly labeled, never in the public marketplace. Exploratory spike beyond
 * ADR-023 §12's v1 disposition.
 *
 * §7/§8 note: reads here are `SELECT`s scoped to the plugin namespace (ADR-023 §8); writes go
 * direct for the spike (a real build routes writes through the typed core repository, §7). Every
 * statement runs on the storage kernel (`kernel.run`), so the same code serves SQLite and Postgres.
 *
 * Relocated from Jini (`@jini-ai/commerce/store`, removed in Jini 3e0122f4): this demo store is a
 * site sample, not generic commerce — Jini's catalog (`@jini-ai/commerce`) is the generic product
 * model and has no equivalent of these `p_store__*` tables or seed. The body is unchanged, so the
 * rendered storefront is identical; `store-plugin.ts` stays the CMS adapter in front of it.
 */
import type { StorageKernel } from "@jini-ai/db/kernel";

export interface Product {
  id: string;
  /** Readable-slugs S7 (2026-09-23): same value as `id` for this sample plugin — its ids are
   *  already short, readable, non-UUID strings, and there is no separate `slug` DB column to add
   *  one from. Real Commerce products have their own real, author-set slug (`features/commerce
   *  /types.ts`); this is just the demo store's stand-in for the same shape. */
  slug: string;
  title: string;
  price: number; // cents
  stock: number;
  version: number;
}

export type CheckoutResult =
  | { ok: true; orderId: string; remainingStock: number; retries: number }
  | { ok: false; reason: "not-found" | "out-of-stock" | "conflict" | "invalid-quantity"; retries: number };

export interface StoreApi {
  listProducts(required?: Record<string, never>, optional?: Record<string, never>): Promise<Product[]>;
  /** Buy `qty` of a product: an OCC-guarded stock decrement plus an order row. */
  checkout(required: { productId: string; qty: number }, optional?: Record<string, never>): Promise<CheckoutResult>;
}

export const STORE_PLUGIN_ID = "store";
const PRODUCTS = `p_${STORE_PLUGIN_ID}__products` as const;
const ORDERS = `p_${STORE_PLUGIN_ID}__orders` as const;

/** The store's two tables, as Kysely sees them. A type alias: `withTables` needs its index signature. */
type StoreTables = {
  [PRODUCTS]: { id: string; title: string; price: number; stock: number; version: number };
  [ORDERS]: { id: string; product_id: string; qty: number; total: number; at: number };
};


export const SEED_PRODUCTS: Product[] = [
  { id: "prod-teacup", slug: "prod-teacup", title: "Hand-thrown Teacup", price: 2800, stock: 5, version: 0 },
  { id: "prod-notebook", slug: "prod-notebook", title: "Linen Notebook", price: 1600, stock: 5, version: 0 },
  { id: "prod-candle", slug: "prod-candle", title: "Beeswax Candle", price: 1200, stock: 5, version: 0 },
];

/**
 * Declare the store's tables through core (snapshot→DDL), seed once, and return the store API.
 *
 * `db` is the site's storage kernel (or a SQLite connection, bridged to its kernel); `dbPath` names
 * the SQLite file behind it, for the declaration's snapshot.
 */
export async function activateStore(
  required: { kernel: StorageKernel<unknown>; prepareStorage: () => Promise<void> },
  _optional: Record<string, never> = {}
): Promise<StoreApi> {
  const kernel = required.kernel;
  // Storage declaration and its recovery guarantees belong to the injected host.
  await required.prepareStorage();

  // Seed once: the count and the inserts share one transaction under a lock, so two boots racing
  // on Postgres cannot both see an empty table.
  await kernel.transaction(async () => {
    await kernel.lockKey(`${PRODUCTS}:seed`);
    const { n } = await kernel.run((k) =>
      k.withTables<StoreTables>().selectFrom(PRODUCTS).select((eb) => eb.fn.countAll<number>().as("n")).executeTakeFirstOrThrow()
    );
    if (Number(n) > 0) return;
    const rows = SEED_PRODUCTS.map(({ id, title, price, stock, version }) => ({ id, title, price, stock, version }));
    await kernel.run((k) => k.withTables<StoreTables>().insertInto(PRODUCTS).values(rows).execute());
  });

  type Attempt = { done: true; result: CheckoutResult } | { done: false };

  /** One checkout attempt: read, then the OCC-guarded decrement and the order row, as ONE transaction. */
  function attemptCheckout(productId: string, qty: number, retries: number): Promise<Attempt> {
    return kernel.transaction(async (): Promise<Attempt> => {
      await kernel.lockKey(`${PRODUCTS}:${productId}`);
      const product = await kernel.run((k) =>
        k.withTables<StoreTables>().selectFrom(PRODUCTS).select(["price", "stock", "version"]).where("id", "=", productId).executeTakeFirst()
      );
      if (!product) return { done: true, result: { ok: false, reason: "not-found", retries } };
      if (product.stock < qty) return { done: true, result: { ok: false, reason: "out-of-stock", retries } };

      // The stock decrement and the order insert are TWO writes. They are atomic here ONLY because
      // this spike store holds the kernel directly. A real Tier-3 plugin behind the frozen async ABI
      // (ADR-024 §3) CANNOT hold a transaction across the seam — which is exactly why core must own
      // an atomic multi-write primitive (see the cowork ABI finding → ADR-026).
      const dec = await kernel.run((k) =>
        k
          .withTables<StoreTables>()
          .updateTable(PRODUCTS)
          .set((eb) => ({ stock: eb("stock", "-", qty), version: eb("version", "+", 1) }))
          .where("id", "=", productId)
          .where("version", "=", product.version)
          .executeTakeFirst()
      );
      if (Number(dec.numUpdatedRows) === 0) return { done: false }; // OCC conflict — the row moved under us; retry
      const orderId = `ord-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
      await kernel.run((k) =>
        k
          .withTables<StoreTables>()
          .insertInto(ORDERS)
          .values({ id: orderId, product_id: productId, qty, total: product.price * qty, at: Date.now() })
          .execute()
      );
      return { done: true, result: { ok: true, orderId, remainingStock: product.stock - qty, retries } };
    });
  }

  async function checkout({ productId, qty }: { productId: string; qty: number }, _optional: Record<string, never> = {}): Promise<CheckoutResult> {
    if (!Number.isSafeInteger(qty) || qty <= 0) return { ok: false, reason: "invalid-quantity", retries: 0 };
    const maxAttempts = 5;
    for (let attempt = 0; attempt < maxAttempts; attempt += 1) {
      const outcome = await attemptCheckout(productId, qty, attempt);
      if (outcome.done) return outcome.result;
    }
    return { ok: false, reason: "conflict", retries: maxAttempts };
  }

  return {
    async listProducts(_required: Record<string, never> = {}, _optional: Record<string, never> = {}): Promise<Product[]> {
      const rows = await kernel.run((k) =>
        k.withTables<StoreTables>().selectFrom(PRODUCTS).select(["id", "title", "price", "stock", "version"]).orderBy("title").execute()
      );
      // No DB column for `slug` — see the `Product` interface's own doc for why `id` stands in.
      return rows.map((row) => ({ ...row, slug: row.id }));
    },
    checkout,
  };
}

/**
 * @file Read-only public cover policy (featfallback, 2026-10-10).
 * Storage/editor semantics stay with featuredMediaId; this only selects public presentation data.
 * Kept host-side until Jini can publish a built CMS export without disrupting the live server.
 */
import { parseFragment, type DefaultTreeAdapterMap } from "parse5";
import { scanEmbedMarkers, type EmbedMarker } from "@jini-ai/cms/widgets/markers";

export interface CoverImagePost {
  title: string;
  featuredMediaId?: string | null;
  bodyFormat: "doc" | "html";
  bodyJson: unknown;
  bodyHtml: string | null;
  kind?: "post" | "page";
  ext?: Record<string, unknown>;
}

export interface CoverMedia {
  /** Canonical id when a body reference was a slug; omitted for id-keyed render metadata. */
  id?: string;
  width: number | null;
  height: number | null;
  contentType: string | null;
}

export interface CoverImage {
  /** Zero-based TipTap image/media occurrence; repeated references remain separate occurrences. */
  bodyOccurrence?: number;
  mediaId?: string;
  /** Only populated when the caller explicitly allows an external HTTPS OG image. */
  url?: string;
  alt: string;
  width: number | null;
  height: number | null;
}

interface Candidate { mediaRef?: string; src?: string; alt?: string; bodyOccurrence?: number }
type HtmlNode = DefaultTreeAdapterMap["childNode"];
const INERT_ELEMENTS = new Set(["script", "style", "template", "noscript"]);

/** Stored JSON is untrusted; narrow objects before reading node/attribute fields. */
function object(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** TipTap image/media nodes with an attrs object are the only body cover occurrences. */
function isMediaNode(node: Record<string, unknown>): node is Record<string, unknown> & { attrs: Record<string, unknown> } {
  return (node.type === "image" || node.type === "media") && object(node.attrs);
}

/** Pushes children last-to-first so popping the stack visits them in document order. */
function pushReversed<T, U>(stack: U[], items: readonly T[], wrap: (item: T) => U): void {
  for (let i = items.length - 1; i >= 0; i--) stack.push(wrap(items[i]!));
}

/** A public rendition src can point back to a library id/slug; originals are never covers. */
function renditionRef(src: string): string | undefined {
  const match = /^\/m\/([^/]+)\/[^/]+\.v\d+\/[^/?#]+(?:[?#].*)?$/.exec(src);
  const encoded = match?.[1];
  if (encoded === undefined) return undefined;
  try { return decodeURIComponent(encoded); } catch { return undefined; }
}

/** Preserve body alt and prefer an explicit library reference to a legacy src. */
function candidate(attrs: Record<string, unknown>): Candidate {
  const src = typeof attrs.src === "string" ? attrs.src.trim() : undefined;
  const mediaRef = typeof attrs.assetId === "string" ? attrs.assetId : src ? renditionRef(src) : undefined;
  return { mediaRef, src, alt: typeof attrs.alt === "string" ? attrs.alt : undefined };
}

/** Pre-order document traversal stays iterative because imported nesting is not bounded. */
function* docCandidates(root: unknown): Generator<Candidate> {
  const stack: unknown[] = [root];
  let occurrence = 0;
  while (stack.length) {
    const node = stack.pop();
    if (Array.isArray(node)) {
      pushReversed(stack, node, item => item);
      continue;
    }
    if (!object(node)) continue;
    if (isMediaNode(node)) yield { ...candidate(node.attrs), bodyOccurrence: occurrence++ };
    if (Array.isArray(node.content)) stack.push(node.content);
  }
}

/** A media marker's library ref (id, else slug) with its alt, preferring the marker's own alt. */
function markerCandidate(marker: EmbedMarker, attrs: Record<string, string>): Candidate | undefined {
  const ref = marker.id ?? marker.config.slug;
  return typeof ref === "string" ? candidate({ assetId: ref, alt: marker.config.alt ?? attrs.alt }) : undefined;
}

/** parse5 owns HTML semantics; the existing marker parser owns embed configuration.
 * Source offsets align each rendered element with its marker without re-parsing marker JSON.
 * Inert content and a media marker's authored fallback are not independent body images.
 */
function* htmlCandidates(html: string): Generator<Candidate> {
  const markers = new Map(scanEmbedMarkers({ html }).markers.map((marker) => [marker.index, marker]));
  const stack: HtmlNode[] = [...parseFragment(html, { sourceCodeLocationInfo: true }).childNodes].reverse();
  while (stack.length) {
    const node = stack.pop()!;
    if (!("tagName" in node) || INERT_ELEMENTS.has(node.tagName)) continue;
    const attrs = Object.fromEntries(node.attrs.map(({ name, value }) => [name, value]));
    const marker = markers.get(node.sourceCodeLocation?.startOffset ?? -1);
    if (marker?.type === "media") {
      const image = markerCandidate(marker, attrs);
      if (image) yield image;
      continue;
    }
    if (node.tagName === "img") yield candidate(attrs);
    pushReversed(stack, node.childNodes, child => child);
  }
}

/** Featured selection is final even if missing; only an unset slot enables the body fallback. */
function candidates(post: CoverImagePost): Iterable<Candidate> {
  if (post.featuredMediaId) return [{ mediaRef: post.featuredMediaId }];
  return post.bodyFormat === "html" ? htmlCandidates(post.bodyHtml ?? "") : docCandidates(post.bodyJson);
}

/** Strict external OG policy. Body rendering has a wider HTTP allowlist; social fallback does not.
 * Credentials and authenticated originals never become a public crawler URL. No fetch occurs.
 */
function externalHttps(src: string | undefined): string | null {
  if (!src || !/^https:\/\/[^\s]+$/i.test(src)) return null;
  try {
    const url = new URL(src);
    if (url.protocol !== "https:" || url.username || url.password) return null;
    if (/\/workspaces\/[^/]+\/media\/[^/]+\/original\b/i.test(url.pathname)) return null;
    return src;
  } catch { return null; }
}

/** Known non-images are skipped; unknown MIME (null) follows the featured-image contract. */
function isCoverMedia(media: CoverMedia | null): media is CoverMedia {
  return media !== null && (media.contentType === null || media.contentType.startsWith("image/"));
}

/** The cover for one candidate, or null when it is unusable under the current options. */
function candidateCover(
  { image, alt }: { image: Candidate; alt: string },
  optional: { mediaLookup: (required: { ref: string }) => CoverMedia | null; allowExternalHttps?: boolean },
): CoverImage | null {
  if (image.mediaRef) {
    const media = optional.mediaLookup({ ref: image.mediaRef });
    if (!isCoverMedia(media)) return null;
    return { mediaId: media.id ?? image.mediaRef, alt, width: media.width, height: media.height, ...(image.bodyOccurrence !== undefined ? { bodyOccurrence: image.bodyOccurrence } : {}) };
  }
  if (!optional.allowExternalHttps) return null;
  const url = externalHttps(image.src);
  return url ? { url, alt, width: null, height: null } : null;
}

/** References needed by the cover policy, deduplicated before host metadata reads.
 * @example collectCoverMediaRefs({ post }, {})
 * @complexity O(n) document traversal and O(a) retained distinct refs; HTML also parses O(bytes).
 */
export function collectCoverMediaRefs({ post }: { post: CoverImagePost }, _optional: Record<string, never> = {}): string[] {
  const refs = new Set<string>();
  for (const image of candidates(post)) if (image.mediaRef) refs.add(image.mediaRef);
  return [...refs];
}

/** Select featured, else the first usable body image, else null, without mutating the post.
 * The host lookup excludes deleted/trashed assets and supplies canonical ids and known MIME.
 * Known non-images are skipped; unknown MIME follows the existing featured-image contract.
 * External body URLs require an explicit OG-only opt-in, never a card/hero permission.
 * @example resolveCoverImage({ post }, { mediaLookup: ({ ref }) => metadata.get(ref) ?? null })
 * @complexity O(n) traversal, O(n) worst-case stack/HTML tree; O(1) injected map reads per ref.
 */
export function resolveCoverImage(
  { post }: { post: CoverImagePost },
  optional: { mediaLookup: (required: { ref: string }) => CoverMedia | null; allowExternalHttps?: boolean },
): CoverImage | null {
  for (const image of candidates(post)) {
    const cover = candidateCover({ image, alt: image.alt?.trim() ? image.alt : post.title }, optional);
    if (cover) return cover;
  }
  return null;
}

/** Pages, HTML bodies, hosts without the public transform, and an explicit
 * hideCoverImageInBody: false all render the stored body as-is.
 */
function keepsStoredBody(post: CoverImagePost, hasPublicTransform: boolean): boolean {
  const presentation = post.ext?.["post-presentation"];
  return post.kind === "page" || post.bodyFormat !== "doc" || !hasPublicTransform ||
    (object(presentation) && presentation.hideCoverImageInBody === false);
}

/** Copies the document without the selected image/media occurrence; the input is never mutated.
 * @complexity O(n) time/space, iterative so imported nesting cannot overflow the stack.
 */
function withoutOccurrence({ body, selected }: { body: Record<string, unknown>; selected: number }): unknown {
  const output: unknown[] = [];
  const stack = [{ source: body as unknown, target: output }];
  let occurrence = 0;
  while (stack.length) {
    const { source, target } = stack.pop()!;
    if (Array.isArray(source)) {
      const copy: unknown[] = [];
      target.push(copy);
      pushReversed(stack, source, item => ({ source: item, target: copy }));
      continue;
    }
    if (!object(source)) { target.push(source); continue; }
    if (isMediaNode(source) && occurrence++ === selected) continue;
    const copy = { ...source };
    target.push(copy);
    if (!Array.isArray(source.content)) continue;
    const content: unknown[] = [];
    copy.content = content;
    pushReversed(stack, source.content, item => ({ source: item, target: content }));
  }
  return output[0];
}

/** Project the body for public rendering and preview; storage and the editable document stay intact.
 * HTML posts are intentionally not hidden: this policy removes only a TipTap occurrence.
 * @complexity O(n) time/space, iterative so imported nesting cannot overflow the stack.
 */
export function projectPostBody(
  { post }: { post: CoverImagePost },
  optional: { mediaLookup: (required: { ref: string }) => CoverMedia | null; hasPublicTransform: boolean },
): unknown {
  if (keepsStoredBody(post, optional.hasPublicTransform)) return post.bodyJson;
  const selected = resolveCoverImage({ post }, optional)?.bodyOccurrence;
  if (selected === undefined || !object(post.bodyJson)) return post.bodyJson;
  return withoutOccurrence({ body: post.bodyJson, selected });
}

import type { JsonObject } from "@jini-ai/core/primitives";

/**
 * @file `content_post_duplicate`'s widgetEmbed handling — see `tool-registrations.ts`'s own
 * `content_post_duplicate` handler doc, and `ADS-memory/reports/2026-09-07-page-tool-gap.md` §2, for
 * the full design rationale this file implements.
 *
 * A page's `bodyJson` can carry `widgetEmbed` nodes. `agent-tools.ts`'s own published
 * `TIPTAP_DOC_SCHEMA` documents a `widgetEmbed` node's `attrs` as carrying only `placementId` — but
 * the REAL node this codebase's write path (`Jini/packages/cms/src/widgets/embed-service.ts`'s `collectEmbeds`/
 * `widgetEmbedNode`) actually reads and writes carries BOTH `placementId` AND `widgetEntryId` in
 * `attrs` (confirmed by reading that file directly: `collectEmbeds` requires
 * `typeof node.attrs.widgetEntryId === "string"` to even recognize the node as an embed). That
 * published schema is model-facing documentation, not a runtime validator (`agent-tools.ts`'s own
 * header), so this mismatch is a pre-existing, separate discrepancy — noted here rather than fixed,
 * since `content_post_duplicate` never authors a `bodyJson` from scratch; it only ever copies one
 * this codebase already wrote.
 *
 * `placementId` is a per-document embed-SLOT identifier: it exists only so
 * `widgets_remove_embed`/`widgets_reorder_embeds` can address "this occurrence" within one host
 * document, and every real lookup combines it with that document's own entry id
 * (`embed-service.ts`'s `loadHostEntry` + `removeEmbedByPlacementId` — there is no placement table
 * keyed by `placementId` alone). `widgetEntryId` is the actual live reference to a reusable widget
 * INSTANCE, and referencing the same instance from multiple host documents at once is the intended,
 * supported shape of a widget — `widgets_get_instance`'s own "where-used" disclosure names multiple
 * simultaneous references as the normal case (the same footer widget embedded on every page).
 *
 * A byte-for-byte `bodyJson` copy therefore carries the source page's `placementId` values verbatim
 * onto the new row. Today's addressing (`hostEntryId` + `placementId` together) means that alone
 * cannot corrupt the source page's own document — but nothing in this codebase documents
 * `placementId` as scoped rather than globally unique, and a future caller assuming global
 * uniqueness is a reasonable mistake this duplicate should not manufacture two live examples of.
 * {@link copyBodyJsonWithFreshEmbedPlacements} removes the ambiguity at the one place it is free to
 * remove: every copied embed gets a FRESH `placementId` (minted the same way
 * `insertWidgetEmbed`/`reorderEmbedSlots` already mint one for every other embed mutation), while
 * `widgetEntryId` is carried over unchanged — reusing the same widget instance across the original
 * and the copy is the intended, documented behavior of a widget, not the trap this function exists
 * to close.
 */

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** Refresh only addressable embed slots; malformed embeds remain structural copies. */
function refreshEmbedPlacement(
  { node, newPlacementId }: { node: Record<string, unknown>; newPlacementId: () => string },
  _options: Record<string, never> = {}
): Record<string, unknown> {
  return node.type === "widgetEmbed" && isPlainObject(node.attrs) && typeof node.attrs.placementId === "string"
    ? { ...node, attrs: { ...node.attrs, placementId: newPlacementId() } }
    : node;
}

function walk(root: unknown, newPlacementId: () => string): unknown {
  // An explicit stack, not recursion: a duplicated page's nesting depth is caller/import-controlled
  // and a 5000-deep body overflowed the call stack here (same class as f646ba397's GET-path
  // walkers). Each frame carries where its copied value goes; children are pushed in reverse so
  // the walk stays pre-order and `newPlacementId` is called in document order, exactly as the
  // recursive version did.
  let result: unknown;
  const stack: Array<{ node: unknown; place: (value: unknown) => void }> = [{ node: root, place: (value) => { result = value; } }];
  while (stack.length > 0) {
    const { node, place } = stack.pop()!;
    if (Array.isArray(node)) {
      const copy: unknown[] = new Array(node.length);
      place(copy);
      for (let i = node.length - 1; i >= 0; i--) stack.push({ node: node[i], place: (value) => { copy[i] = value; } });
      continue;
    }
    if (!isPlainObject(node)) {
      place(node);
      continue;
    }

    const source = refreshEmbedPlacement({ node, newPlacementId });
    const copy: Record<string, unknown> = {};
    place(copy);
    // Clone every field, including leaf text nodes, marks and nested attrs; walking only content
    // would leave the copy sharing mutable objects with its source.
    const entries = Object.entries(source);
    for (let i = entries.length - 1; i >= 0; i--) {
      const [key, value] = entries[i]!;
      stack.push({ node: value, place: (cloned) => { copy[key] = cloned; } });
    }
  }
  return result;
}

/**
 * Deep-clones a TipTap `bodyJson` document, minting a fresh `placementId` on every `widgetEmbed`
 * node it contains (see this file's header for why). Every other node, attribute, and mark is
 * copied unchanged — including a `widgetEmbed` node's `widgetEntryId`, which is deliberately carried
 * over rather than regenerated.
 *
 * A document with no `widgetEmbed` nodes at all (the common case) round-trips as a plain structural
 * clone with no minted ids spent.
 *
 * @complexity O(n) in the size of `bodyJson` — one iterative walk, no repeated work, no backtracking.
 */
export function copyBodyJsonWithFreshEmbedPlacements(bodyJson: JsonObject, newPlacementId: () => string): JsonObject {
  return walk(bodyJson, newPlacementId) as JsonObject;
}

/**
 * @file Plain text out of an `"html"`-format Page's `bodyHtml` (SPEC-047/ADR-056 Decision 3) — the
 * `bodyFormat === "html"` twin of `extractPostPlainText` (`search.ts`) for consumers that must not read
 * the empty `bodyJson` placeholder (`repo.rows.ts`'s `toRecord`). Lives in `post` so both SEO
 * (`Jini/packages/cms/src/seo/seo.ts`) and the post tools can use it without an import cycle.
 */

/** Named entities actually observed in stored `bodyHtml` (numeric entities are handled separately
 *  below); extend only as real content demands it rather than pulling in a full HTML5 entity table.
 *  The typographic row came from live `/media` + `/forms` bodies, whose `&mdash;` otherwise survived
 *  decoding and was re-escaped by the head renderer into a literal "&amp;mdash;" snippet. */
const HTML_NAMED_ENTITIES: Record<string, string> = {
  amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " ",
  mdash: "—", ndash: "–", hellip: "…", lsquo: "‘", rsquo: "’", ldquo: "“", rdquo: "”", laquo: "«", raquo: "»",
  middot: "·", bull: "•", copy: "©", reg: "®", trade: "™", times: "×", deg: "°", rarr: "→", larr: "←",
};

/** Decodes `&amp;`/`&#39;`/`&#x27;`-style entities left over after tag-stripping. Unknown or
 *  malformed entities pass through unchanged rather than being dropped. */
function decodeHtmlEntities(text: string): string {
  return text.replace(/&(#[xX][0-9a-fA-F]+|#\d+|[a-zA-Z]+);/g, (match, entity: string) => {
    if (entity[0] !== "#") {
      const name = entity.toLowerCase();
      return (Object.hasOwn(HTML_NAMED_ENTITIES, name) ? HTML_NAMED_ENTITIES[name] : undefined) ?? match;
    }
    return decodeNumericEntity({ entity, match });
  });
}

function decodeNumericEntity({ entity, match }: { entity: string; match: string }, _options = {}): string {
  const codePoint = entity[1] === "x" || entity[1] === "X" ? parseInt(entity.slice(2), 16) : parseInt(entity.slice(1), 10);
  // Stored prose may contain an invalid reference. Preserve it instead of throwing or creating
  // an unpaired surrogate that cannot represent a Unicode scalar value.
  return !Number.isInteger(codePoint) || codePoint < 0 || codePoint > 0x10ffff || (codePoint >= 0xd800 && codePoint <= 0xdfff)
    ? match : String.fromCodePoint(codePoint);
}

/** Opening tag of any element carrying the `post-detail-header` class (any attribute order/quoting,
 *  extra class names alongside it); group 1 is the tag name used to find its matching close.
 *  Capture the class value in group 3 so its whitespace-delimited tokens can be checked exactly;
 *  a word boundary also matches hyphenated prefixes/suffixes belonging to unrelated prose. */
const POST_DETAIL_HEADER_OPEN = /<([a-z][a-z0-9]*)\b[^>]*\sclass\s*=\s*(["'])((?:(?!\2)[\s\S])*)\2[^>]*>/i;

/** Index just past the close tag that balances an already-open `tag` starting at `from`, counting
 *  same-name opens/closes so a nested `<div class="post-meta">` inside a `<div>` header does not end
 *  the block early; -1 when the element is never closed.
 *  @complexity O(n) over the remaining html. */
function findBalancedCloseEnd(html: string, tag: string, from: number): number {
  const tagPattern = new RegExp(`<(/?)${tag}\\b[^>]*>`, "gi");
  tagPattern.lastIndex = from;
  let depth = 1;
  for (let match = tagPattern.exec(html); match; match = tagPattern.exec(html)) {
    depth += match[1] ? -1 : 1;
    if (depth === 0) return tagPattern.lastIndex;
  }
  return -1;
}

/** Strips every element carrying the `post-detail-header` class — the injected title/date wrapper
 *  (`renderPostDetailHeader` in `render.ts`: `<div class="post-detail-header"><h1>…</h1><div
 *  class="post-meta">…</div></div>`) that the theme prepends ahead of an html-format body's own
 *  prose. Without this, the derived excerpt doubled the title (`/media`'s description started "Media
 *  Media is…"). The close is found by depth-counting same-name tags, not a lazy `</\1>` match, since
 *  the real header nests a `<div>`. An unclosed header is left in place (same as before).
 *  @complexity O(n·h) for h class-bearing elements scanned. */
function stripPostDetailHeader(html: string): string {
  let kept = "";
  let rest = html;
  for (let open = POST_DETAIL_HEADER_OPEN.exec(rest); open; open = POST_DETAIL_HEADER_OPEN.exec(rest)) {
    const contentStart = open.index + open[0].length;
    // Groups 1 (tag) and 3 (class value) are not optional, so a match always fills them.
    const [, tag = "", , classValue = ""] = open;
    if (!classValue.split(/[\t\n\f\r ]+/).includes("post-detail-header")) {
      kept += rest.slice(0, contentStart);
      rest = rest.slice(contentStart);
      continue;
    }
    const end = findBalancedCloseEnd(rest, tag, contentStart);
    kept += end === -1 ? rest.slice(0, contentStart) : `${rest.slice(0, open.index)} `;
    rest = rest.slice(end === -1 ? contentStart : end);
  }
  return kept + rest;
}

/** Plain-text extraction over a bespoke-HTML Page body (SEO's derived excerpt and `content_post_list`
 *  excerpts, SPEC-047 gap): drops the `.post-detail-header` title/date block and `<style>`/`<script>` blocks wholesale
 *  (never prose) before stripping the remaining tags, so a leading stylesheet — real `bodyHtml` rows
 *  start with one, see `/quickstart` — or the injected header can never surface as the description. */
export function extractPlainTextFromHtml(html: string): string {
  const withoutHeader = stripPostDetailHeader(html);
  const withoutNonProse = withoutHeader.replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi, " ");
  const withoutTags = withoutNonProse.replace(/<[^>]+>/g, " ");
  return decodeHtmlEntities(withoutTags);
}

import { toolMetadata } from '../../contracts/core/tool-metadata/post.js';
import { adaptLegacyAuthorize } from "@jini-ai/cms/core";
import { ToolInputError } from "@jini-ai/core";
import { buildDomainRegistrations, indexCatalogById, requireInputRecord, type DerivedRiskByToolId, type ToolRegistration } from "@jini-ai/core";
import { type JsonObject } from "@jini-ai/core/primitives";
import { requireToolPermission, type AuthorizeFn } from "@jini-ai/cms/core";
import type { ToolContributor } from "#src/assistant/index";
import { getAdminPostById, PostNotFoundError, type PublicPostRecord as PostRecord, type PostRepoPort } from "./post.js";
import { readPageBodyOptions, shapePageBody, type ShapedPageBody } from "#src/features/site-inspection/page-body";
import { readPostTemplateOptions, type PostTemplateDeps } from "./template-options.js";

/** Renderer injected at the server composition root; the feature has no server/assistant value edge. */
export interface PostPreviewToolDeps extends PostTemplateDeps { authorize: AuthorizeFn; postRepo: PostRepoPort }
export interface PostPreviewInput { post: PostRecord; templateChoice?: string | null | undefined; bodyJson?: JsonObject | undefined; bodyHtml?: string | undefined }
export interface PostPreviewRenderer {
  renderPostPreview(deps: PostPreviewToolDeps, input: PostPreviewInput): Promise<{ html: string; templateChoice: string | null }>;
}
export const postPreviewAgentToolCatalog = [{
  name: "content_post_preview",
  description: "Renders a post or page by id (or slug; postId is a legacy alias) — including a draft, or edits you haven't saved — through its theme template, exactly as it would look once published. Use before publishing to check a draft, or to try a different template. Changes nothing. For a published page as visitors get it, use fetch_published_page (local) or fetch_live_url (live). Returns postId, title, status, templateChoice, availableTemplates, bodyBytes, truncated and body, or matches with offsets/snippets and matchCount when find is supplied. Set a saved template with content_post_update's template field using one of availableTemplates. Pass textOnly for text without markup. Refuses an unknown id/slug, invalid options, or a template preview when no theme is active.",
  sideEffects: "none" as const, authorization: { permission: "content.read" },
  inputSchema: { type: "object", additionalProperties: false, anyOf: [{ required: ["id"] }, { required: ["postId"] }], properties: {
    id: { type: "string", minLength: 1, description: "Post/page id or slug, any status except Trash. Takes precedence over postId." },
    postId: { type: "string", minLength: 1, description: "Legacy alias for id. Prefer id." },
    templateChoice: { type: "string", description: "Optional pending choice. Omit to use the saved choice; empty string opts out of a template." },
    bodyJson: { type: "object", description: "Optional unsaved document body." },
    bodyHtml: { type: "string", description: "Optional unsaved HTML body for an HTML-format page." },
    find: { type: "string", minLength: 1, maxLength: 200 }, textOnly: { type: "boolean" },
    maxBytes: { type: "integer", minimum: 1, maximum: 1000000 },
  } },
}];
export const postPreviewDerivedRisk: DerivedRiskByToolId = new Map([
  // -> getAdminPostByIdOrSlug + injected renderer: reads and in-memory clones only, no saves.
  ["content_post_preview", "none"],
]);
const CATALOG = indexCatalogById({ catalog: postPreviewAgentToolCatalog });

/** Validate all override fields before copying any of them or performing reads. */
function validatePreviewOverrides(input: Record<string, unknown>, _options: Record<string, never> = {}): void {
  for (const key of ["templateChoice", "bodyHtml"] as const) if (input[key] !== undefined && typeof input[key] !== "string") throw new ToolInputError({ message: `content_post_preview: ${key} must be a string.` });
  if (input.bodyJson !== undefined && (typeof input.bodyJson !== "object" || input.bodyJson === null || Array.isArray(input.bodyJson))) throw new ToolInputError({ message: "content_post_preview: bodyJson must be a JSON object." });
}

/**
 * Reads id (or its legacy postId alias) and unsaved edits without changing the input. A supplied
 * id wins even when invalid, so a stale alias cannot redirect a preview to a different record.
 * Empty HTML/template opt-outs are preserved; malformed fields throw ToolInputError.
 * @complexity O(1) field checks.
 */
function readPreviewInput(input: Record<string, unknown>, _options: Record<string, never> = {}): { postId: string; overrides: Omit<PostPreviewInput, "post"> } {
  const id = input.id === undefined ? input.postId : input.id;
  if (typeof id !== "string" || id.trim().length === 0) throw new ToolInputError({ message: "content_post_preview: id must be a non-empty id or slug (postId is a legacy alias)." });
  validatePreviewOverrides(input);
  const overrides: Omit<PostPreviewInput, "post"> = {};
  if (input.templateChoice !== undefined) overrides.templateChoice = input.templateChoice as string;
  if (input.bodyHtml !== undefined) overrides.bodyHtml = input.bodyHtml as string;
  if (input.bodyJson !== undefined) overrides.bodyJson = input.bodyJson as JsonObject;
  return { postId: id, overrides };
}

/** Builds the read-only preview handler; authorization precedes lookup and any render read. */
export function buildPostPreviewRegistrations(deps: PostPreviewToolDeps, renderer: PostPreviewRenderer): ToolRegistration[] {
  return buildDomainRegistrations({ metadata: toolMetadata, domain: "post-preview", catalogModule: "features/post/preview-tool.ts", catalog: CATALOG, derivedRisk: postPreviewDerivedRisk, handlers: {
    content_post_preview: async ctx => {
      const input = requireInputRecord({ input: ctx.input });
      const { postId, overrides } = readPreviewInput(input);
      const options = readPageBodyOptions(input);
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "content.read" }, { entityType: "post" });
      let post: PostRecord;
      try { ({ post } = await getAdminPostById({ deps: { repo: deps.postRepo }, input: { workspaceId: deps.workspaceId, id: postId } })); }
      catch (error) {
        if (error instanceof PostNotFoundError) throw new ToolInputError({ message: `content_post_preview: no post or page with id or slug '${postId}'. Use content_read.content_post to find it.` });
        throw error;
      }
      const rendered = await renderer.renderPostPreview(deps, { post, ...overrides });
      const availableTemplates = await readPostTemplateOptions({ deps, kind: post.kind });
      const shaped: ShapedPageBody = shapePageBody(rendered.html, options);
      return { postId: post.id, title: post.title, status: post.status, templateChoice: rendered.templateChoice, availableTemplates, ...shaped };
    },
  } });
}
/** Contributes under its own domain, preserving all of post's existing tools. */
export function contributePostPreviewTools(renderer: PostPreviewRenderer): ToolContributor {
  return { domain: "post-preview", build: deps => buildPostPreviewRegistrations(deps, renderer), risk: postPreviewDerivedRisk };
}

import { nowIso as clockNowIso } from "@jini-ai/core/primitives";
import { executeCommand } from "@jini-ai/cms/core";

import { contentHash } from "#src/features/publish-content/content-hash";
import { collectBodyReferences } from "#src/features/publish-content/content-references";
import { PublishContentApplyRowError } from "#src/features/publish-content/apply-errors";
import { addressHeldByOther, trashedAtDestination } from "#src/features/publish-content/precheck-reasons";
import { createRepoPublishHandler, gatewayDeps } from "#src/features/publish-content/repo-handler";
import type {
  PublishContentContributor,
  PublishContentDeps,
  PublishContentPorts,
  PackedEntity,
  PublishContentReference,
  RetireTarget,
  TaxonomyPublishPorts,
} from "#src/features/publish-content/type-registry";
import { prepareTermSync, readTermIds, TERM_SYNC_PERMISSION, withTermIds } from "#src/features/taxonomy/publish-term-ids";

import { importPostEntity, isTrashed, presentScheduleFields, restorePostForward, retirePostForReplacement, PostConflictError, PostNotFoundError, ROOT_SLUG } from "./post.js";
import type { PostKind, PostRecord } from "./post.js";

/**
 * @file `post`'s and `page`'s publish-content contributions, built on `createRepoPublishHandler`
 * (`features/publish-content/repo-handler.ts`; M-POST of
 * `ADS-memory/.local-artifacts/plan-publish-all-types-2026-09-25.md`). One table, one config,
 * distinguished only by `PostKind`.
 *
 * Both contributors return DATA and import only `type-registry.ts`'s TYPES, never
 * `registerPublishContentContributor` — the composition root
 * (`server/runtime/composition/publish-content-manifest.ts`) registers them. See `type-registry.ts`'s
 * header for the module cycle a value edge would reopen, and
 * `__tests__/post-no-direct-registry-import.boundary.test.ts` for the check.
 *
 * ## The write
 *
 * `importPostEntity` (never the raw repo) inside `executeCommand` (`undo`), so an import is auditable
 * and revertible like an admin edit. Authorship (Task 15): `command.actor` is always the IMPORTING
 * operator (`executeCommand` authorizes that principal; a remote peer's author id is not a principal
 * here), while the SOURCE author travels on `record.createdByPrincipalId`, applied only on create
 * (`toImportableRecord`). `CommandActor.kind` has no `"api_key"`, so it is `"user"` like every admin route.
 *
 * ## Terms (plan §3.7, schemaVersion 2)
 *
 * `termIds` rides on the row NON-enumerably ({@link withTerms}): packed and hashed, left out when the
 * row has none (so an untagged row keeps its schemaVersion-1 hash), and never spread into a change
 * set's inverse or a restored row. The write syncs the assignments after the post lands; the gateway
 * rollback unassigns them first.
 *
 * ## Precheck
 *
 * Every refusal (empty slug, slug held, trashed destination, kind change) is enforced again inside
 * `importPostEntity`; precheck exists so an operator sees it in the plan. A body-format change (`doc`
 * vs `html`) is NOT refused (D2, 2026-09-24): it is an ordinary hashed change.
 */

/**
 * `post`'s and `page`'s declared prerequisite types. A page's body embeds media exactly like a post's;
 * `term` because the state carries `termIds`, and assigning one checks the term exists at write time.
 */
const POST_AND_PAGE_DEPENDS_ON: readonly string[] = ["media", "term"];

/**
 * Every `PostRecord` field, classified by what this transport DOES with it. This map is the single
 * place that decision is recorded, and `Record<keyof PostRecord, ...>` is what makes it a decision
 * rather than an omission: adding a field to `PostRecord` fails this file's typecheck until someone
 * classifies the new field here.
 *
 * ## The defect this exists to prevent
 *
 * This file used to hash `{...post}` — the WHOLE record — while `apply()` wrote back a hand-listed
 * subset of six or so fields. Everything in the gap (`bodyFormat`/`bodyHtml`, `seoExtJson`, `ext`,
 * `deletedAt`, `memberAccessJson`, and `templateChoice`/`overridesThemePage` on the create path) was
 * hashed but never applied, so publishing silently dropped or replaced it and still reported
 * success. `memberAccessJson` made that a SECURITY defect and not only a fidelity one: a
 * members-only post published to production as a publicly readable row.
 *
 * **"hashed but not applied" is the defect.** The reverse combination is safe: a field that is
 * applied but not hashed simply never triggers a publish on its own. So `"transferred"` is the only
 * disposition that participates in the content hash, and `"local"` fields are excluded from BOTH
 * sides — they are per-destination facts that a source instance has no standing to overwrite.
 *
 * @see `content-hash.ts`'s `EXCLUDED_KEYS`, which independently drops `id`/`workspaceId`/`version`/
 * `updatedAt`/`createdAt`/`createdByPrincipalId`. This map agrees with it by classifying those same
 * fields `"local"`; the two are belt and braces, not one relying on the other.
 */
const POST_FIELD_DISPOSITIONS: Record<keyof PostRecord, "transferred" | "provenance" | "local"> = {
  // Content — packed, hashed, and written verbatim by `importPostEntity` (`post.ts`).
  title: "transferred",
  slug: "transferred",
  bodyJson: "transferred",
  status: "transferred",
  kind: "transferred",
  bodyFormat: "transferred",
  bodyHtml: "transferred",
  seoExtJson: "transferred",
  templateChoice: "transferred",
  overridesThemePage: "transferred",
  memberAccessJson: "transferred",
  // The public byline is editable content, distinct from the write-once principal provenance below.
  // Unset bylines keep historical hashes; importing that absence clears the destination's byline.
  author: "transferred",
  showAuthor: "transferred",

  // Authorship PROVENANCE (Task 15) — packed and applied, but NOT hashed. The source is the
  // authority on who wrote a post and when, so an import copies both rather than re-stamping every
  // row with the importing operator's id; they are write-once, so only a row that does not exist at
  // the destination yet takes them. Excluded from the hash by `content-hash.ts`'s own
  // `EXCLUDED_KEYS` (which is why they can safely ride along in `state`): two instances that merely
  // disagree on a row's author or creation time must not read as a content edit.
  createdByPrincipalId: "provenance",
  createdAt: "provenance",

  // Identity and per-database write bookkeeping. Two instances holding the same logical content
  // legitimately disagree on all of these — this feature's founding premise, see
  // `content-hash.ts`'s header.
  id: "local",
  workspaceId: "local",
  version: "local",
  updatedAt: "local",

  // Plugin-namespaced extension data (SPEC-005 CIC U-004), written only by the local
  // `content.entry.beforeSave` hook chain. Neither packed nor hashed: a plugin's namespace is a
  // fact about the instance the plugin is INSTALLED on, and a destination running a different
  // plugin set would otherwise repack to a different hash forever and report the row as eternally
  // "changed". The destination's own `ext` survives an import untouched (`toImportableRecord` hands
  // `importPostEntity` the destination's existing bag, and its `beforeSaveHook` merge runs on top),
  // so this exclusion loses nothing that belongs to this instance.
  ext: "local",

  // Trash. Never packed and never hashed: `pack()` skips trashed rows outright rather than shipping
  // them, and `precheck` refuses a trashed DESTINATION row, so publishing can neither export trash
  // nor resurrect it. OPEN PRODUCT QUESTION (2026-09-19): whether a locally-deleted post should
  // instead delete on production. This is the safe reading — it never resurrects trash as live
  // content and never deletes production content — until that is answered.
  deletedAt: "local",

  // Scheduled publishing / featured image (2026-10-05) — carried, so a scheduled post stays
  // scheduled at the destination instead of going live the moment it lands. Packed and hashed ONLY
  // WHEN SET (`omitWhenAbsent` below, and `toPublishableState`): repos keep both keys absent when
  // unset (`presentScheduleFields`), so a row without them keeps the exact state and hash it had
  // before these fields existed (`publish-content.characterization.test.ts` pins those hashes).
  publishAt: "transferred",
  featuredMediaId: "transferred",
};

/** Transferred fields left off the wire (and out of the hash) when the row has no value for them,
 *  so adding them did not move the hash of any row that never set them. */
const OMIT_WHEN_ABSENT: ReadonlySet<keyof PostRecord> = new Set(["publishAt", "featuredMediaId", "author", "showAuthor"]);

/** The keys {@link toPublishableState} puts on the wire: `"transferred"` plus `"provenance"`.
 *  Derived from {@link POST_FIELD_DISPOSITIONS} rather than re-listed, so the two cannot drift. */
const PACKED_POST_FIELDS = Object.freeze(
  (Object.keys(POST_FIELD_DISPOSITIONS) as Array<keyof PostRecord>).filter(
    (field) => POST_FIELD_DISPOSITIONS[field] !== "local"
  )
);

/** The wire shape of a packed `post`/`page`: exactly {@link PACKED_POST_FIELDS}, nothing else.
 *  Named so `pack`, `inspect` and `apply` read one contract instead of three hand-listed field sets
 *  that can drift apart. */
export type PublishablePostState = Pick<PostRecord, (typeof PACKED_POST_FIELDS)[number]>;

/**
 * Projects a `PostRecord` onto {@link PublishablePostState} — the ONE row projection behind the
 * packed state and the content hash (plus the row's `termIds`).
 *
 * Undefined optional fields are normalized to `null` so a row whose optional column was never set
 * and one whose column holds SQL `NULL` hash identically across two instances whose adapters
 * represent that difference differently. (`content-hash.ts`'s `normalize` collapses the same two
 * cases, but doing it here makes the WIRE shape unambiguous too, not just the hash input.)
 * The exception is {@link OMIT_WHEN_ABSENT}: those keys are left out when unset, matching the
 * factory's `omitWhenAbsent`, so this state and the packed hash stay one recipe.
 *
 * Exported so a test can assert against THE state builder rather than re-deriving the field list
 * on its own — a duplicated recipe in a test is the same drift this DTO exists to close, and it
 * is how four suites came to hash `{...post}` while production hashed something else.
 *
 * @complexity O(1) — a fixed field count, no iteration over anything caller-controlled.
 */
export function toPublishableState(post: PostRecord): Record<string, unknown> {
  const state: Record<string, unknown> = {};
  for (const field of PACKED_POST_FIELDS) {
    if (OMIT_WHEN_ABSENT.has(field) && post[field] === undefined) continue;
    if ((field === "author" && post.author === null) || (field === "showAuthor" && post.showAuthor === false)) continue;
    state[field] = post[field] ?? null;
  }
  return state;
}

/** Source absence clears destination presentation fields instead of inheriting them. */
function importedPresentationFields(
  { packed }: { packed: Partial<PostRecord> },
  _options: Record<string, never> = {}
) {
  return {
    // Absent on the wire means "none": the destination's own schedule/featured image is CLEARED, not
    // kept, so a source that went live makes the destination live too.
    ...presentScheduleFields({ publishAt: packed.publishAt ?? null, featuredMediaId: packed.featuredMediaId ?? null }),
    author: packed.author ?? null,
    showAuthor: packed.showAuthor ?? false,
  };
}

/** Keep destination bookkeeping and write-once provenance separate from transferred content. */
function importedLocalFields(
  { existing, wire }: { existing: PostRecord | null; wire: Record<string, unknown> },
  _options: Record<string, never> = {}
) {
  return {
    // Recomputed by `importPostEntity` itself; present only because `PostRecord` requires them, and
    // never read off the wire.
    version: existing?.version ?? 0,
    updatedAt: existing?.updatedAt ?? "",
    // A packed entity is never trashed (`pack` skips trashed rows) and a trashed destination row is
    // refused before this point, so the only correct value here is "live".
    deletedAt: null,
    ...(existing?.ext !== undefined ? { ext: existing.ext } : {}),
    ...importedProvenanceFields({ existing, wire }),
  };
}

/** Existing rows keep write-once provenance, including absence; new rows default wire absence to null. */
function importedProvenanceFields(
  { existing, wire }: { existing: PostRecord | null; wire: Record<string, unknown> },
  _options: Record<string, never> = {}
) {
  return {
    createdByPrincipalId: existing ? existing.createdByPrincipalId : (wire.createdByPrincipalId as string | null) ?? null,
    createdAt: existing ? existing.createdAt : (wire.createdAt as string | null) ?? null,
  };
}

/**
 * Rebuilds the full `PostRecord` `importPostEntity` replicates, from a packed state plus whatever
 * the destination already holds.
 *
 * `"local"` fields are filled from the DESTINATION's own row (or a documented default when there is
 * none) and never from the wire; `"provenance"` fields come from the wire only for a row that does
 * not exist here yet, matching their write-once contract.
 *
 * @complexity O(1).
 */
function toImportableRecord(
  required: { state: Record<string, unknown>; workspaceId: string; id: string; existing: PostRecord | null }
): PostRecord {
  const { state, workspaceId, id, existing } = required;
  const packed = state as Partial<PostRecord>;
  const wire: Record<string, unknown> = {};
  for (const field of PACKED_POST_FIELDS) {
    if (OMIT_WHEN_ABSENT.has(field)) continue;
    wire[field] = packed[field] ?? null;
  }
  return {
    ...(wire as unknown as PublishablePostState),
    ...importedPresentationFields({ packed }),
    id,
    workspaceId,
    ...importedLocalFields({ existing, wire }),
  };
}

/** {@link collectBodyReferences} plus the featured image, so a scoped publish carries that media too. */
function postReferences(state: Readonly<Record<string, unknown>>): readonly PublishContentReference[] {
  const refs = collectBodyReferences(state);
  const featured = state.featuredMediaId;
  if (typeof featured !== "string" || featured.length === 0) return refs;
  if (refs.some((ref) => ref.entityType === "media" && ref.key === featured)) return refs;
  return [...refs, { entityType: "media", key: featured }];
}

/** A row as this transport sees it: see this file's header for `termIds`. */
type PostRow = PostRecord & { readonly termIds?: readonly string[] };

/** The post port plus the taxonomy ports `termIds` needs. */
type PostPorts = PublishContentPorts["post"] & { readonly term?: TaxonomyPublishPorts };

/** Attaches sorted `termIds`, non-enumerable (this file's header), without changing stored fields.
 * @returns A copy suitable for the gateway's compensation row as well as the transport.
 * @throws Taxonomy repository failures propagate before a publish write.
 * @complexity One indexed term read plus O(t log t) time/O(t) space for t assigned terms.
 */
async function withTerms(termPorts: TaxonomyPublishPorts | undefined, row: PostRecord): Promise<PostRow> {
  const termIds = await readTermIds(termPorts, row.kind, row.id);
  // The gateway captures this row as its inverse: preserve the stored byline defaults too.
  const publishRow = { ...row };
  return termIds ? Object.defineProperty(publishRow, "termIds", { value: termIds, enumerable: false }) : publishRow;
}

/** The packed state of `row` (what `pack` ships and hashes), for `planRetire`/`retire`'s hashes. */
async function packedStateOf(termPorts: TaxonomyPublishPorts | undefined, row: PostRecord): Promise<Record<string, unknown>> {
  return withTermIds(toPublishableState(row), await readTermIds(termPorts, row.kind, row.id));
}

/** The apply-time ports, or the error that names what is missing. */
function applyPorts(ports: PostPorts, deps: PublishContentDeps, kind: PostKind) {
  const { forgetRemoved } = ports;
  if (!forgetRemoved) {
    throw new Error(
      `publish-content: ${kind}.apply() requires PublishContentDeps.changeSets/authorize/` +
        "outbox and ports.post.repo/forgetRemoved — wire them from the real apply-loop composition " +
        "root (features/publish-content/apply-loop.ts)."
    );
  }
  return { repo: ports.repo, clock: deps.clock, outbox: gatewayDeps(deps, kind).outbox, forgetRemoved };
}

/**
 * Puts one post import back: the prior row is restored forward (see `restorePostForward`'s doc); a
 * created row has no pre-image, so it must never have existed, and `hardDelete` removes it with the
 * revision it appended and the slug it reserved (trashing it would leave a "restorable" row and keep
 * the slug reserved against the retry). Shared by the gateway's `undo` and `write`'s own catch.
 * @complexity O(1): one read plus one restore or delete.
 */
async function undoPostImport(
  { ports, deps, kind, workspaceId, id, prior, principalId }: {
    ports: PostPorts; deps: PublishContentDeps; kind: PostKind; workspaceId: string; id: string; prior: PostRow | null; principalId: string;
  },
  _options: Record<string, never> = {}
): Promise<void> {
  if (prior) {
    await restorePostForward({ deps: applyPorts(ports, deps, kind), input: { prior, actorId: principalId } });
    return;
  }
  if (await ports.repo.findById({ workspaceId, id })) await ports.repo.hardDelete({ workspaceId, id });
}

/** Why an entity of type `kind` is refused when its packed `kind` differs, or `null`. `kind` is
 *  transferred, so without this a `page` entity could create a post: a publishing grant limited to
 *  `page` authorizes through the `page` handler and would never see the post it wrote. */
function packedKindMismatch(kind: PostKind, id: string, state: Record<string, unknown>): string | null {
  return state.kind === kind ? null : `${kind} entity '${id}' is packed as a '${String(state.kind)}' — a ${kind} publish writes only ${kind}s`;
}

function contributePostKind(kind: PostKind): PublishContentContributor {
  return createRepoPublishHandler<PostRow, PostPorts>({
    entityType: kind, // PostKind's two values are exactly this feature's two entityTypes
    coversTables: ["posts", "post_versions"],
    schemaVersion: 2,
    // The same permission `content_post_create`/`content_post_update` declare.
    permission: "content.write",
    // Carried `termIds` sync through the taxonomy chokepoint.
    alsoAuthorizes: [TERM_SYNC_PERMISSION],
    dependsOn: POST_AND_PAGE_DEPENDS_ON,
    ports: (deps) => deps.ports.post && { ...deps.ports.post, term: deps.ports.term },
    portsKey: "post",
    list: async (p, workspaceId) => {
      const rows = (await p.repo.list({ workspaceId })).filter((row) => row.kind === kind && !isTrashed(row));
      // SQL supplies null/false defaults for older rows. Omit those defaults from the wire/hash;
      // import still clears a destination's old byline when the source leaves these fields absent.
      return Promise.all(rows.map((row) => withTerms(p.term, { ...row, author: row.author ?? undefined, showAuthor: row.showAuthor || undefined })));
    },
    find: async (p, workspaceId, id) => {
      const row = await p.repo.findById({ workspaceId, id });
      return row && row.kind === kind ? withTerms(p.term, row) : null;
    },
    isTrashed,
    fields: { ...POST_FIELD_DISPOSITIONS, termIds: "transferred" },
    omitWhenAbsent: ["termIds", ...OMIT_WHEN_ABSENT],
    // Hash the established transport projection while find() retains the full compensation row.
    legacyHashState: (row) => withTermIds(toPublishableState(row), row.termIds),
    references: (entity) => postReferences(entity.state),
    // Not the factory's `address`: a slug held by a trashed row keeps this sentence, and the slug
    // checks run before the kind check on an unfiltered read, as before the migration.
    validate: async ({ ports, workspaceId, entity }) => {
      const wrongKind = packedKindMismatch(kind, entity.id, entity.state);
      if (wrongKind) return wrongKind;
      const slug = entity.state.slug;
      if (typeof slug !== "string" || slug.length === 0) return `${kind} entity '${entity.id}' has no usable slug to check for a collision`;
      const holder = await ports.repo.findBySlug({ workspaceId, slug });
      if (holder && holder.id !== entity.id) return addressHeldByOther(kind, "slug", slug, holder.id);
      const existing = await ports.repo.findById({ workspaceId, id: entity.id });
      if (existing && isTrashed(existing)) return trashedAtDestination(kind, entity.id);
      if (existing && existing.kind !== kind) {
        return `'${entity.id}' is a '${existing.kind}' at this destination but a '${kind}' at the source — kind is fixed at creation and cannot be changed by publishing`;
      }
      return null;
    },
    write: async ({ ports, deps, workspaceId, id, state, existing, expectedVersion, principalId, onRollback }) => {
      const wrongKind = packedKindMismatch(kind, id, state);
      if (wrongKind) throw new PublishContentApplyRowError("blocked", wrongKind);
      const { repo, outbox } = applyPorts(ports, deps, kind);
      const terms = await prepareTermSync({ ports: ports.term, deps, entityType: kind, entityId: id, principalId, contentType: kind, wanted: state.termIds });
      // Terms first on rollback: Jini resolves the post to (un)assign, and a create's undo deletes it.
      onRollback(terms.revert);
      const imported = await importPostEntity({
        deps: { repo, clock: deps.clock, outbox, beforeSaveHook: deps.beforeSaveHook },
        // The revision ledger's actor is the IMPORTING operator; the source author is on the record.
        input: { workspaceId, record: toImportableRecord({ state, workspaceId, id, existing }), expectedVersion, actorId: principalId },
      });
      try {
        await terms.apply();
      } catch (error) {
        // `executeCommand` compensates only a failed change-set record, never a failed `execute`, and
        // the import above is already committed: undo it here (terms first, as on rollback) and
        // rethrow. A revert failure must not hide the original error or skip the post's undo.
        await terms.revert().catch(() => undefined);
        await undoPostImport({ ports, deps, kind, workspaceId, id, prior: existing, principalId });
        throw error;
      }
      return { version: imported.post.version };
    },
    undo: {
      // Forward, not verbatim: see `restorePostForward`'s doc. A create's undo removes the row.
      restore: async ({ ports, deps, workspaceId, id, principalId }, prior) => {
        await undoPostImport({ ports, deps, kind, workspaceId, id, prior, principalId });
      },
      remove: async ({ ports, deps, workspaceId, id, principalId }) => {
        await undoPostImport({ ports, deps, kind, workspaceId, id, prior: null, principalId });
      },
    },
    errors: { conflict: [PostConflictError, PostNotFoundError] },
    extend: ({ deps }) => ({
      ...postRetireMethods(deps, kind),
      // `retire()`'s own conflicts reach the apply loop raw. `PostVersionConflictError` extends
      // `PostConflictError`.
      isApplyConflict: (error): error is Error => error instanceof PostConflictError || error instanceof PostNotFoundError,
    }),
  });
}

/** S4 (`publish-overwrite-live-plan-2026-09-24.md`): retire the live row a slug-clash overwrite replaces. */
function postRetireMethods(deps: PublishContentDeps, kind: PostKind) {
  const entityType = kind;
  const postRepo = deps.ports.post?.repo;
  const stateOf = (row: PostRecord) => packedStateOf(deps.ports.term, row);

  /**
   * S4's read half (`publish-overwrite-live-plan-2026-09-24.md` §4/§5) — reports the live row a
   * slug-clash overwrite would retire, or `null` when there is none. Never writes.
   *
   * The three conditions under which there is nothing to retire, matching precheck's own
   * slug-taken branch it is meant to answer for:
   * - the slug is free, or already held by `entity` itself — nothing to overwrite;
   * - `entity.id` already exists at this destination — a same-id collision needs a different remedy
   *   (a kind change, S11) than retiring some unrelated row;
   * - the slug is {@link ROOT_SLUG} — the home page has no other address to move to
   *   ({@link retirePostForReplacement}'s own refusal, mirrored here so the box is never even offered).
   *
   * @complexity O(1) — two indexed repo reads, same as precheck.
   */
  async function planRetire(entity: PackedEntity): Promise<RetireTarget | null> {
    if (!postRepo) return null;
    const slug = entity.state.slug;
    if (typeof slug !== "string" || slug.length === 0 || slug === ROOT_SLUG) return null;

    const holder = await postRepo.findBySlug({ workspaceId: deps.workspaceId, slug });
    if (!holder || holder.id === entity.id) return null;

    const existingHere = await postRepo.findById({ workspaceId: deps.workspaceId, id: entity.id });
    if (existingHere) return null;

    return {
      entityType: holder.kind,
      entityId: holder.id,
      entityLabel: holder.title,
      hash: contentHash(holder.kind, await stateOf(holder)),
    };
  }

  /**
   * S4's write half — retires `target` (moves it to Trash under a renamed slug, never in place)
   * through the same `executeCommand` gateway `apply()` uses, wrapping
   * {@link retirePostForReplacement} exactly the way `routes/pages/delete.ts:46-92` wraps
   * `deletePost`: `operation: "delete"`, inverse is the holder's own prior `deletedAt` — `null` for a
   * live holder, its trash time for one that was already trashed. A revert must put the row back
   * exactly where it was, not always un-trash it: `retirePostForReplacement` only renames an
   * already-trashed holder (its own doc), so a literal `{deletedAt: null}` inverse would un-trash a
   * row the human had trashed before this run ever touched it.
   *
   * `captureInverse` reads `target`'s CURRENT row and closes over it as `holder`; `execute` reuses
   * that same read as `retirePostForReplacement`'s required `expectedVersion`, rather than a second,
   * later read, because `executeCommand` guarantees `captureInverse` resolves before `execute` runs
   * (`core/commands/command.ts`'s own "Order matters: idempotency check -> inverse capture ->
   * execute -> record"). The apply loop (S5) is what re-verifies `target.hash` against a FRESH
   * `planRetire()` immediately before calling this — a holder that changed between plan and apply is
   * caught there, not here.
   *
   * `undo()` restores `holder` forward through {@link restorePostForward} — the same primitive
   * the apply rollback uses — and is also what the gateway's `mutation.rollback` calls on a
   * change-set-record failure, so every path that can need to "put this retire back" restores
   * identically.
   *
   * @complexity O(1) plus `executeCommand`'s own cost, same as `apply()`.
   */
  async function retire(input: {
    target: RetireTarget;
    principalId: string;
    idempotencyKey: string;
  }): Promise<{ changeSetId: string; undo(): Promise<void> }> {
    const { changeSets, authorize, outbox } = deps;
    const forgetRemovedPost = deps.ports.post?.forgetRemoved;
    const removePost = deps.ports.post?.remove;
    if (!changeSets || !authorize || !outbox || !postRepo || !forgetRemovedPost || !removePost) {
      throw new Error(
        `publish-content: ${entityType}.retire() requires PublishContentDeps.changeSets/authorize/` +
          "outbox and ports.post.repo/forgetRemoved/remove — wire them from the real apply-loop " +
          "composition root (features/publish-content/apply-loop.ts)."
      );
    }
    const gatewayDeps = { clock: deps.clock, idGen: deps.idGen, changeSets, outbox, authorize };
    const actor = { id: input.principalId, kind: "user" as const };
    const { target } = input;

    let holder: PostRecord | null = null;

    const undoRetire = async () => {
      if (!holder) return;
      await restorePostForward({
        deps: { repo: postRepo, clock: deps.clock, outbox, forgetRemoved: forgetRemovedPost },
        input: { prior: holder, actorId: input.principalId },
      });
    };

    const { changeSetId } = await executeCommand({
      deps: gatewayDeps,
      command: {
        workspaceId: deps.workspaceId,
        actor,
        summary: `Retire ${target.entityType} '${target.entityId}' for publish overwrite`,
        permission: "content.write",
        idempotencyKey: input.idempotencyKey,
      },
      mutation: {
        entityType: target.entityType,
        entityId: target.entityId,
        operation: "delete",
        captureInverse: async () => {
          holder = await postRepo.findById({ workspaceId: deps.workspaceId, id: target.entityId });
          if (!holder) {
            throw new PostNotFoundError(`${target.entityType} '${target.entityId}' was not found`);
          }
          // The apply loop's own re-check runs before this read, outside any lock; checking the
          // hash again here, on the row whose version `execute` pins, closes that gap.
          if (contentHash(holder.kind, await stateOf(holder)) !== target.hash) {
            throw new PostConflictError(`the live ${target.entityType} at this address changed after this run's plan was built`);
          }
          // The slug too: a retire renames it, so a revert from history must be able to move it back.
          return { deletedAt: holder.deletedAt ?? null, slug: holder.slug };
        },
        execute: () =>
          retirePostForReplacement({
            deps: { repo: postRepo, clock: deps.clock, outbox, remove: removePost },
            input: {
              workspaceId: deps.workspaceId,
              id: target.entityId,
              expectedVersion: holder!.version,
              today: todayStamp(clockNowIso({ clock: deps.clock })),
              actorId: input.principalId,
            },
          }),
        captureEntityVersion: ({ result }) => result.post.version,
        rollback: undoRetire,
      },
    });

    return { changeSetId, undo: undoRetire };
  }
  return { planRetire, retire };
}

/**
 * `yyyymmdd` from an ISO clock reading — {@link retirePostForReplacement}'s own `today` input shape
 * (`post.ts`'s own doc: "supplied by the caller rather than derived from `clockNowIso({ clock: deps.clock })`'s ISO
 * format"). The one place that derivation happens, so `retire()` above stays a pure caller of it.
 */
function todayStamp(nowIso: string): string {
  return nowIso.slice(0, 10).replace(/-/g, "");
}

/** `post`'s publish-content contribution. */
export const contributePostPublish = (): PublishContentContributor => contributePostKind("post");

/** `page`'s publish-content contribution: same table, same repo, same config as {@link contributePostPublish}. */
export const contributePagePublish = (): PublishContentContributor => contributePostKind("page");

import { createHash, randomUUID } from "node:crypto";

import {
  type PostAutosaveSnapshot,
  type PostRecord,
  type PostRepoPort,
  type PostRevisionAppendResult,
  type PostRevisionInput,
  type PostRevisionRecord,
} from "./post.js";
import { comparePostsByDisplayDate, currentIso, isLiveAt } from "../../contracts/core/scheduled-publish.js";
import { wentLiveSinceSave, type GoLiveCandidatesPort } from "./go-live.js";

/**
 * SPEC-005 (T021): `ext` needs no special handling here. Unlike `repo.sqlite.ts` — which has to
 * serialize it to a JSON text column and normalize the `{}` default back to an absent field —
 * this adapter stores and returns whole `PostRecord`s verbatim, exactly as it already does for
 * `bodyJson`, so `ext` (present or absent) round-trips unchanged.
 */

export class InMemoryPostRepo implements PostRepoPort, GoLiveCandidatesPort {
  private rows: PostRecord[];
  /** Standing-draft autosave snapshots, keyed apart from `rows` — mirrors `repo.sqlite.ts`'s own
   *  `autosave_json` column being a sibling of the row rather than a `PostRecord` field (see
   *  `PostRepoPort.readAutosave`'s doc for why). */
  private autosaves = new Map<string, PostAutosaveSnapshot>();
  /** This adapter's `post_revisions` stand-in — a plain array mirrors `rows`' own storage choice
   *  (see `PostRepoPort.appendRevision`'s doc for the append-only contract both adapters share). */
  private revisions: PostRevisionRecord[] = [];

  constructor(initialRows: PostRecord[] = []) {
    this.rows = [...initialRows];
  }

  private autosaveKey(workspaceId: string, id: string): string {
    return `${workspaceId}:${id}`;
  }

  async findById(required: { workspaceId: string; id: string }): Promise<PostRecord | null> {
    return (
      this.rows.find((row) => row.workspaceId === required.workspaceId && row.id === required.id) ??
      null
    );
  }

  async findBySlug(required: { workspaceId: string; slug: string }): Promise<PostRecord | null> {
    return (
      this.rows.find(
        (row) => row.workspaceId === required.workspaceId && row.slug === required.slug
      ) ?? null
    );
  }

  async list(required: { workspaceId: string }): Promise<PostRecord[]> {
    return this.rows.filter((row) => row.workspaceId === required.workspaceId);
  }

  /** Same bounded kind-filtered contract as the SQL adapter. */
  async listHtmlByKind(required: { workspaceId: string; kind: import("./post.js").PostKind; limit: number; before?: { updatedAt: string; id: string } }, _options = {}): Promise<PostRecord[]> {
    return this.rows.filter(row => row.workspaceId === required.workspaceId && row.kind === required.kind
      && row.bodyFormat === "html" && row.bodyHtml !== null && !row.deletedAt)
      .filter(row => !required.before || row.updatedAt < required.before.updatedAt || (row.updatedAt === required.before.updatedAt && row.id > required.before.id))
      .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt) || a.id.localeCompare(b.id)).slice(0, required.limit);
  }

  /** See `PostRepoPort.listPublishedPreviews`'s own doc for the exact contract (bounded,
   *  `kind: "post"`-filtered, newest display date first). Filter-sort-slice here is this in-memory
   *  adapter's own stand-in for a real bounded query — `repo.sqlite.ts`'s adapter is the one that
   *  must push the equivalent `WHERE`/`ORDER BY`/`LIMIT` down to SQLite itself. */
  async listPublishedPreviews(required: { workspaceId: string; limit: number; nowIso?: string; offset?: number }): Promise<PostRecord[]> {
    const nowIso = required.nowIso ?? currentIso();
    const offset = required.offset ?? 0;
    return this.rows
      .filter(
        (row) =>
          row.workspaceId === required.workspaceId &&
          row.kind === "post" &&
          isLiveAt(row, nowIso)
      )
      .sort(comparePostsByDisplayDate)
      .slice(offset, offset + required.limit);
  }

  /** See `GoLiveCandidatesPort.listGoLiveCandidates` — the in-JS twin of `repo.ts`'s query. */
  async listGoLiveCandidates(required: { workspaceId: string; nowIso: string; afterIso?: string }, _optional: Record<string, never> = {}): Promise<PostRecord[]> {
    const { workspaceId, nowIso, afterIso } = required;
    return this.rows
      .filter((row) => row.workspaceId === workspaceId && wentLiveSinceSave({ post: row, nowIso }) && (afterIso === undefined || (row.publishAt as string) > afterIso))
      // Fixed-width ISO first, so the concatenation orders by go-live time, then `id` — the SQL order.
      .sort((a, b) => (`${a.publishAt}${a.id}` < `${b.publishAt}${b.id}` ? -1 : 1));
  }

  async save(record: PostRecord): Promise<void> {
    const index = this.rows.findIndex((row) => row.id === record.id);
    if (index === -1) {
      this.rows.push(record);
      return;
    }

    this.rows[index] = record;
  }

  /** See `PostRepoPort.saveIfVersion`'s own doc for the contract this mirrors from
   *  `repo.sqlite.ts`'s conditional `UPDATE`. Deliberately NOT a fall-through to `save()`: a row
   *  that is absent or has moved past `ifVersion` reports `applied: false` and writes nothing at
   *  all — no insert, no partial update, no version bump. The workspace is part of the match here
   *  (unlike `save()` above, which keys on `id` alone) because the SQLite predicate includes it,
   *  and an adapter pair that disagrees on what "the same row" means is how a guard passes its
   *  in-memory tests and fails in production. */
  async saveIfVersion(required: {
    record: PostRecord;
    ifVersion: number;
  }): Promise<{ applied: boolean }> {
    const index = this.rows.findIndex(
      (row) => row.workspaceId === required.record.workspaceId && row.id === required.record.id
    );
    if (index === -1 || this.rows[index]?.version !== required.ifVersion) return { applied: false };

    this.rows[index] = required.record;
    return { applied: true };
  }

  /**
   * Stamps the trash marker (see `post.ts`'s `PostRecord.deletedAt`). The row is KEPT — that is the
   * whole point of a soft delete — so this is a field update on the existing record, never a splice
   * out of `rows`. A row this adapter dropped could not be restored by `postDeleteReverter`, and
   * `findBySlug` would stop reserving its slug, which `repo.sqlite.ts`'s real unique index would
   * then reject at insert time. Both adapters must behave identically here.
   */
  async softDelete(required: {
    workspaceId: string;
    id: string;
    deletedAt: string;
    updatedAt: string;
    version: number;
  }): Promise<void> {
    const index = this.rows.findIndex(
      (row) => row.workspaceId === required.workspaceId && row.id === required.id
    );
    const row = this.rows[index];
    if (row === undefined) return;

    this.rows[index] = {
      ...row,
      deletedAt: required.deletedAt,
      updatedAt: required.updatedAt,
      version: required.version,
    };
  }

  /**
   * See `PostRepoPort.hardDelete`'s own doc. Splices the row out of `rows` AND drops its revisions
   * and its parked autosave — the three places this adapter keeps a post's content. Dropping only
   * the row would leave `listRevisions` serving full copies of every version of something the
   * caller was told is permanently gone, which is exactly what the SQLite adapter's cascade exists
   * to prevent; both adapters must behave identically here.
   *
   * @complexity O(n + r) over the rows and revisions this adapter holds.
   */
  async hardDelete(required: { workspaceId: string; id: string }): Promise<void> {
    this.rows = this.rows.filter(
      (row) => !(row.workspaceId === required.workspaceId && row.id === required.id)
    );
    this.revisions = this.revisions.filter(
      (revision) => !(revision.workspaceId === required.workspaceId && revision.postId === required.id)
    );
    this.autosaves.delete(this.autosaveKey(required.workspaceId, required.id));
  }

  /** See `PostRepoPort.readAutosave`'s own doc. */
  async readAutosave(required: { workspaceId: string; id: string }): Promise<PostAutosaveSnapshot | null> {
    return this.autosaves.get(this.autosaveKey(required.workspaceId, required.id)) ?? null;
  }

  /** See `PostRepoPort.writeAutosave`'s own doc for the staleness contract this mirrors from
   *  `repo.sqlite.ts`'s conditional `UPDATE`: a missing row or a `version` that has moved past
   *  `snapshot.baseVersion` both report `applied: false` without touching the parked snapshot. */
  async writeAutosave(required: {
    workspaceId: string;
    id: string;
    snapshot: PostAutosaveSnapshot;
  }): Promise<{ applied: boolean }> {
    const row = await this.findById(required);
    if (!row || row.version !== required.snapshot.baseVersion) return { applied: false };
    this.autosaves.set(this.autosaveKey(required.workspaceId, required.id), required.snapshot);
    return { applied: true };
  }

  /** See `PostRepoPort.clearAutosave`'s own doc — unconditional, no version guard. */
  async clearAutosave(required: { workspaceId: string; id: string }): Promise<void> {
    this.autosaves.delete(this.autosaveKey(required.workspaceId, required.id));
  }

  /** See `PostRepoPort.appendRevision`'s own doc. Mirrors `repo.sqlite.ts`'s adapter exactly:
   *  `previousId` is the latest existing row for this `(workspaceId, postId)` found BEFORE the new
   *  row is pushed, and `contentHash` is computed here so both adapters apply the identical rule. */
  async appendRevision(input: PostRevisionInput): Promise<PostRevisionAppendResult> {
    const priorForPost = this.revisions.filter(
      (row) => row.workspaceId === input.workspaceId && row.postId === input.postId
    );
    const previousId = priorForPost.at(-1)?.id ?? null;

    const id = randomUUID();
    const contentHash = createHash("sha256").update(JSON.stringify(input.stateJson)).digest("hex");

    this.revisions.push({
      id,
      postId: input.postId,
      workspaceId: input.workspaceId,
      seq: input.seq,
      op: input.op,
      stateJson: input.stateJson,
      contentHash,
      actorId: input.actorId,
      delegatedByWorkspaceId: input.delegatedByWorkspaceId ?? null,
      delegatedById: input.delegatedById ?? null,
      restoredFrom: input.restoredFrom ?? null,
      recordedAt: input.recordedAt,
    });

    return { id, previousId };
  }

  /** See `PostRepoPort.listRevisions`'s own doc — ascending `seq`, matching `repo.sqlite.ts`'s
   *  `ORDER BY seq ASC`. */
  async listRevisions(required: { workspaceId: string; postId: string }): Promise<PostRevisionRecord[]> {
    return this.revisions
      .filter((row) => row.workspaceId === required.workspaceId && row.postId === required.postId)
      .slice()
      .sort((a, b) => a.seq - b.seq);
  }

  /**
   * See `PostRepoPort.transaction`'s own doc for why this exists. No real SQL connection backs
   * this adapter, so "atomic" here means snapshot-and-restore: `rows`/`revisions`/`autosaves` are
   * captured before `fn` runs, and restored verbatim if it throws — safe because JavaScript has no
   * real concurrent access to these arrays between the snapshot and the restore (single-threaded,
   * no I/O yields a competing writer could land in).
   */
  async transaction<T>(fn: () => Promise<T>): Promise<T> {
    const rowsSnapshot = [...this.rows];
    const revisionsSnapshot = [...this.revisions];
    const autosavesSnapshot = new Map(this.autosaves);
    try {
      return await fn();
    } catch (error) {
      this.rows = rowsSnapshot;
      this.revisions = revisionsSnapshot;
      this.autosaves = autosavesSnapshot;
      throw error;
    }
  }
}

import { toSlug } from "../../platform/html/slug.js";

export const MAX_SLUG_LENGTH = 120;
export const DERIVED_SLUG_SUFFIX_ROOM = "-999".length;

/** Leave room for the bounded collision suffix so every derived slug remains editable. */
export function derivePostSlugBase({ title }: { title: string }, _optional: Record<string, never> = {}): string {
  return toSlug(title).slice(0, MAX_SLUG_LENGTH - DERIVED_SLUG_SUFFIX_ROOM).replace(/-+$/, "") || "untitled";
}

/** Automatic slugs are inferred from the stored title, never from an extra preference flag. */
export function isAutomaticPostSlug({ title, slug }: { title: string; slug: string }, _optional: Record<string, never> = {}): boolean {
  const base = derivePostSlugBase({ title });
  return /^untitled(-\d+)?$/.test(slug) || slug === base || (slug.startsWith(`${base}-`) && /^\d+$/.test(slug.slice(base.length + 1)));
}

