      const downgrade = classifyApplyRowFailure(error, row, handler);
      if (downgrade) {
        return {
          row: { ...row, outcome: downgrade.outcome, writes: false, reason: downgrade.reason },
          changeSetId: null,
          retiredChangeSetId: null,
        };
