        // refused at execute time too (same hash both times), so `PLAN_STALE` never intercepts it —
        // `executeMutation()` still calls this port. Nothing to apply; record it and stop.
        await saveRun({
          runId,
          startedAt,
          sourcePrincipalId,
          principalId,
          restorePointId,
          phase: "abandoned",
          changeSetIds: [],
          report,
          items: [],
          finishedAt: clockNowIso({ clock: input.clock }),
