      await retireResult.undo();
    } catch (undoError) {
      const cause = error instanceof Error ? error.message : String(error);
      const undoCause = undoError instanceof Error ? undoError.message : String(undoError);
      throw new Error(
        `${row.entityType} '${row.entityId}' was not created (${cause}), and putting the retired ` +
        `${row.retires.entityType} '${row.retires.entityId}' back failed too (${undoCause}) — restore it from Trash`
      );
    }
  }
}

async function refreshNonWritingRow({ row, ctx }: { row: PublishContentOutcomeRow; ctx: ApplyRowContext }, _optional: Record<string, never> = {}): Promise<ApplyRowResult> {
  const key = entityKey(row.entityType, row.entityId);
  // `conflict`/`blocked` pass through untouched — no baseline write (plan §4 task 8: baselines are
  // upserted for created/unchanged/applied/forced ONLY). `unchanged` is the one non-writing outcome
  // that still refreshes the baseline: the destination already matches the source, so there is
  // nothing to apply, but recording that agreement is exactly what lets FUTURE runs tell "still
  // agrees" apart from "diverged since we last looked".
  if (row.outcome === "unchanged") {
    const entity = ctx.entityByKey.get(key);
    if (entity) {
      await refreshBaseline({ row, entity, ctx });
    }
  }
  return { row, changeSetId: null, retiredChangeSetId: null };
}

import { checkTreePath } from "./file-tree-policy.js";
import { scanTextForSecrets } from "#src/features/webhooks/secret-scan-guard";

/** CMS-specific, immutable boundaries, run on BOTH peers. Neither a grant nor a confirmation
 * can relax these. Plugin tables are allowed (owner B3, 2026-10-04), subject to the same rules. */
export const BACKSTOP_DENIED_TABLE_PATTERNS: readonly RegExp[] = [
  /(?:^|_)(?:members?|identity|principals?|sessions?|roles?|polic(?:y|ies))(?:_|$)/i,
  /^api_keys(?:_|$)/i, /credential/i, /^composio_/i,
  /^(?:origin_settings|deployment|publish_content|publish_trust|publish_backstop|webhook|form_submissions|analytics|redirect_hits|change_sets|outbox|trashed_items)(?:_|$)/i,
  /^(?:sqlite_|__?drizzle|drizzle_|migration)/i,
  /^(?:tovu_(?:chat_)?migrations|schema_migrations)(?:_|$)/i,
];
export const BACKSTOP_DENIED_COLUMN_PATTERN = /secret|token|password|_hash$|key/i;
export const BACKSTOP_DENIED_FILE_ROOTS = [
  "agent-plugins", "plugins", "skills", "uploads", "ops", "out", ".git", "node_modules", ".publish-staging", ".publish-previous",
] as const;
export const BACKSTOP_LIMITS = { rows: 200, files: 50, bytes: 50 * 1024 * 1024, scanBytes: 1024 * 1024 } as const;

export function checkRawTable(
  { table, columns }: { table: string; columns: readonly string[] },
  _optional: Record<string, never> = {},
): string | null {
  if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(table)) return "The table name is not a valid database identifier.";
  if (BACKSTOP_DENIED_TABLE_PATTERNS.some((pattern) => pattern.test(table))) {
    return `Table '${table}' holds private or per-install data and is never sent.`;
  }
  for (const column of columns) {
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(column) || column === "__proto__") return "The column name is not a valid database identifier.";
    if (BACKSTOP_DENIED_COLUMN_PATTERN.test(column)) return `Column '${column}' may hold a key or password; this row is never sent.`;
  }
  return null;
}

export function checkRawFilePath(
  { relPath, isSymbolicLink = false }: { relPath: string; isSymbolicLink?: boolean },
  _optional: Record<string, never> = {},
): string | null {
  if (isSymbolicLink) return "Links are never sent; choose a regular file inside the site folder.";
  // A raw file can start at the site root, unlike a typed tree. Apply the deny-list at EVERY
  // component so a directory named .env (or a nested database backup) cannot evade it.
  const shape = checkTreePath(relPath);
  if (shape) return shape;
  if (/[:%\x01-\x1f\x7f]/.test(relPath)) return `File '${relPath}' has an unsafe path shape.`;
  for (const part of relPath.split("/")) {
    if (isProtectedRawComponent({ part })) {
      return `File '${relPath}' holds private data or belongs to a protected site folder and is never sent.`;
    }
  }
  return null;
}

export function checkRawValues(
  { values, table }: { values: Readonly<Record<string, unknown>>; table?: string },
  _optional: Record<string, never> = {},
): string | null {
  if (table?.toLowerCase().startsWith("setting_values_")) {
    const denied = checkInstallationSetting({ values });
    if (denied) return denied;
  }
  for (const [column, value] of Object.entries(values)) {
    if (typeof value !== "string") continue;
    const hit = scanTextForSecrets(value)[0];
    if (hit) return `Value '${column}' looks like it holds a key (${hit.patternName}); it was not sent.`;
  }
  return null;
}

export function gapLabelFor(
  item: { entityType: "raw-row"; table: string } | { entityType: "raw-file"; relPath: string },
  _optional: Record<string, never> = {},
): string {
  return item.entityType === "raw-row" ? `table:${item.table}` : `folder:${item.relPath.split("/").slice(0, 2).join("/")}`;
}

/** Private names are denied at every depth, including backup and key suffix variants. */
function isProtectedRawComponent({ part }: { part: string }, _optional: Record<string, never> = {}): boolean {
  const lower = part.toLowerCase();
  return BACKSTOP_DENIED_FILE_ROOTS.some((root) => root === lower) || lower.startsWith("restore-point-") ||
      lower.startsWith(".env") || /^\.mcp(?:\..*)?\.json$/.test(lower) ||
      [".npmrc", ".netrc", ".fs-custom-root.json", ".site-meta.json", ".storage-secret.json", "config.json"].includes(lower) ||
      /^id_(?:rsa|dsa|ecdsa|ed25519)(?:\.|$)/.test(lower) || /\.(?:pem|key|p12|pfx)(?:[.-]|$)/.test(lower) || /\.(?:db.*|sqlite.*)$/.test(lower);
}

/** Installation settings stay local independently of the generic secret scan. */
function checkInstallationSetting({ values }: { values: Readonly<Record<string, unknown>> }, _optional: Record<string, never> = {}): string | null {
  if (values.secret === 1 || values.secret === true || values.secret === "1") return "Secret settings are never sent.";
  const key = values.key;
  if (typeof key === "string" && (/^core\.(?:execution|privacy)\./.test(key) ||
    key === "core.instructions.custom" || key === "site.assistant.public_enabled")) {
    return `Setting '${key}' belongs to this installation and is never sent.`;
  }
  return null;
}

import { createHash } from "node:crypto";
import { checkRawTable, checkRawFilePath, checkRawValues } from "./backstop-policy.js";
import type { BackstopPorts, RawRowSnapshot } from "./backstop-ports.js";
import type { PackedEntity } from "./type-registry.js";

export interface BackstopPreview {
  readonly entityType: string;
  readonly entityId: string;
  readonly before: unknown;
  readonly after: unknown;
  readonly unavailableReason: string | null;
}

function safeValues({ row, workspaceId }: { row: RawRowSnapshot; workspaceId: string }, _optional = {}): string | null {
  return checkRawTable({ table: row.table, columns: [...row.columns.map((column) => column.name), ...Object.keys(row.values)] }) ??
    (Object.hasOwn(row.values, "workspace_id") && row.values.workspace_id !== workspaceId ? "This row belongs to a different workspace." : null) ??
    checkRawValues({
      table: row.table, values: Object.fromEntries(Object.entries(row.values).map(([name, value]) => [name,
        typeof value === "object" && value !== null ? Buffer.from(value.blobBase64, "base64").toString("utf8") : value]))
    });
}

/** Only called after import-plan authorization. Preview re-runs the immutable policy on LIVE
 * values too: a safe source must never be used to read a newly private live column or workspace.
 * File values are checksum/size/mode, never arbitrary file text or private absolute paths. */
export async function buildBackstopPreview(
  { entities, backstop, workspaceId }: { entities: readonly PackedEntity[]; backstop: BackstopPorts; workspaceId: string },
  _optional: Record<string, never> = {},
): Promise<readonly BackstopPreview[]> {
  const previews: BackstopPreview[] = [];
  for (const entity of entities) {
    if (entity.entityType !== "raw-row" && entity.entityType !== "raw-file") continue;
    const preview: BackstopPreview = { entityType: entity.entityType, entityId: entity.id, before: null, after: null, unavailableReason: null };
    try {
      previews.push(entity.entityType === "raw-row"
        ? await previewRow({ entity, backstop, workspaceId, preview })
        : await previewFile({ entity, backstop, preview }));
    } catch {
      previews.push({ ...preview, unavailableReason: "These values could not be inspected safely. Check again before sending." });
    }
  }
  return previews;
}

async function previewRow(
  { entity, backstop, workspaceId, preview }: { entity: PackedEntity; backstop: BackstopPorts; workspaceId: string; preview: BackstopPreview },
  _optional: Record<string, never> = {},
): Promise<BackstopPreview> {
  const incoming = entity.state as unknown as RawRowSnapshot;
  const denied = safeValues({ row: incoming, workspaceId }) ??
    (backstop.coveredTables.some((table) => table.toLowerCase() === incoming.table.toLowerCase()) ? "This table already publishes normally." : null);
  if (denied) return { ...preview, unavailableReason: denied };
  if (!backstop.rows) return { ...preview, unavailableReason: "Live row values are not available." };
  const live = await backstop.rows.read({ table: incoming.table, pk: incoming.pk });
  const privateLive = live ? safeValues({ row: live, workspaceId }) : null;
  return { ...preview, before: privateLive ? null : live?.values ?? null, after: incoming.values, unavailableReason: privateLive };
}

async function previewFile(
  { entity, backstop, preview }: { entity: PackedEntity; backstop: BackstopPorts; preview: BackstopPreview },
  _optional: Record<string, never> = {},
): Promise<BackstopPreview> {
  const denied = checkRawFilePath({ relPath: entity.id }) ??
    (backstop.coveredRoots.some((root) => entity.id.toLowerCase() === root.toLowerCase().replace(/\/$/, "") || entity.id.toLowerCase().startsWith(root.toLowerCase().replace(/\/$/, "") + "/")) ? "This file already publishes normally." : null) ??
    await backstop.files?.check({ relPath: entity.id });
  if (denied) return { ...preview, unavailableReason: denied };
  if (!backstop.files) return { ...preview, unavailableReason: "Live file values are not available." };
  const live = await backstop.files.read({ relPath: entity.id });
  const before = live ? { path: entity.id, sha256: createHash("sha256").update(live.bytes).digest("hex"), size: live.bytes.byteLength, mode: live.mode & 0o111 ? 0o755 : 0o644 } : null;
  const { path, sha256, size, mode } = entity.state;
  return { ...preview, before, after: { path, sha256, size, mode } };
}

import type { BackstopAuditPort, BackstopAuditRecord, BackstopMetadata } from "./backstop-audit.js";
import type { BackstopSelection } from "./backstop-ports.js";
import { BACKSTOP_LIMITS, checkRawValues, gapLabelFor } from "./backstop-policy.js";
import type { PackedEntity } from "./type-registry.js";

export const BACKSTOP_FORBIDDEN = "Only the owner and built-in admins can send items by hand.";

export async function mayUseBackstop(
  { actorId, ownerId, roles }: { actorId: string; ownerId: string; roles: { list(): Promise<readonly { name: string; isBuiltin: boolean }[]> } },
  _optional: Record<string, never> = {},
): Promise<boolean> {
  return actorId === ownerId || (await roles.list()).some((role) => role.isBuiltin && (role.name === "admin" || role.name === "owner"));
}

export function validateBackstopRequest(
  { body, destinationHost }: { body: unknown; destinationHost: string },
  _optional: Record<string, never> = {},
): { error: string } | { request: { reason: string; typedHost: string; selection: BackstopSelection } } {
  if (!isBackstopBody({ body })) return { error: "Choose items to send." };
  const b = body as Record<string, unknown>;
  if (!isBackstopReason({ reason: b.reason })) return { error: "Explain why you need this send in at least 10 characters." };
  if (b.typedHost !== destinationHost) return { error: `Type ${destinationHost} to confirm where this send will go.` };
  const rows = b.rows ?? [];
  const files = b.files ?? [];
  const selectionError = checkBackstopSelection({ rows, files });
  if (selectionError) return { error: selectionError };
  const reason = (b.reason as string).trim();
  const secret = checkRawValues({ values: { reason } });
  if (secret) return { error: secret };
  return { request: { reason, typedHost: destinationHost, selection: { rows, files } as BackstopSelection } };
}

/** Persist a pending event BEFORE dialing live so failures leave a source-side record too. */
export async function runAuditedBackstop<T extends Record<string, unknown>>(
  { audit, record, work, successResult = "success" }: { audit: BackstopAuditPort; record: BackstopAuditRecord; work: () => Promise<T>; successResult?: "success" | "planned" },
  _optional: Record<string, never> = {},
): Promise<T> {
  if (!(await audit.ready())) throw new Error("Send by hand needs its audit storage installed before it can send anything.");
  await audit.save({ record: { ...record, result: "pending" } });
  try {
    const result = await work();
    await audit.save({ record: { ...record, result: successResult, runId: typeof result.runId === "string" ? result.runId : record.runId, details: result } });
    return result;
  } catch (error) {
    await audit.save({ record: { ...record, result: "failure", details: { error: error instanceof Error ? error.message : "This send failed." } } });
    throw error;
  }
}

/** Destination trusts only authenticated bundle metadata, validates it again, and derives gaps
 * itself. Metadata lives outside state so an audit reason never changes content equality. */
export function readBackstopMetadata(
  { entities }: { entities: readonly PackedEntity[] },
  _optional: Record<string, never> = {},
): BackstopMetadata | null {
  const raw = entities.filter((e) => e.entityType === "raw-row" || e.entityType === "raw-file");
  if (raw.length === 0) return null;
  if (raw.length !== entities.length) throw new Error("Send by hand cannot include normally published items.");
  if (new Set(raw.map((e) => `${e.entityType}:${e.id}`)).size !== raw.length) throw new Error("Choose each item once.");
  const first = raw[0]?.backstop;
  if (!first || !hasBackstopDetails({ metadata: first })) throw new Error("This send is missing its reason, destination confirmation or source actor.");
  checkBackstopDestination({ destinationHost: first.destinationHost });
  if (raw.some((e) => JSON.stringify(e.backstop) !== JSON.stringify(first))) throw new Error("Every item in this send must have the same audit details.");
  checkBackstopBundleLimits({ raw });
  const secret = checkRawValues({ values: { reason: first.reason } });
  if (secret) throw new Error(secret);
  return { ...first, gapLabels: [...new Set(raw.map((e) => e.entityType === "raw-row"
    ? gapLabelFor({ entityType: "raw-row", table: String(e.state.table) }) : gapLabelFor({ entityType: "raw-file", relPath: e.id })))].sort() };
}

/** Keep the original untrimmed length cap while accepting surrounding whitespace. */
function isBackstopReason({ reason }: { reason: unknown }, _optional: Record<string, never> = {}): boolean {
  return typeof reason === "string" && reason.trim().length >= 10 && reason.length <= 2000;
}

function isBackstopRow({ row }: { row: unknown }, _optional: Record<string, never> = {}): boolean {
  if (!row || typeof row !== "object") return false;
  const candidate = row as Record<string, unknown>;
  return typeof candidate.table === "string" && !!candidate.pk && typeof candidate.pk === "object" &&
    !Array.isArray(candidate.pk) && Object.keys(candidate.pk).length > 0;
}

function checkBackstopSelection({ rows, files }: { rows: unknown; files: unknown }, _optional: Record<string, never> = {}): string | null {
  if (!Array.isArray(rows) || !Array.isArray(files) || rows.length > BACKSTOP_LIMITS.rows || files.length > BACKSTOP_LIMITS.files) return "Choose at most 200 rows and 50 files per send.";
  if (rows.some((row) => !isBackstopRow({ row })) || files.some((file) => typeof file !== "string") || rows.length + files.length === 0) return "Choose rows by their complete primary keys and files by their site-relative paths.";
  if (hasRepeatedBackstopItems({ rows, files })) return "Choose each item once.";
  return null;
}

function hasBackstopDetails({ metadata }: { metadata: BackstopMetadata | undefined }, _optional: Record<string, never> = {}): boolean {
  return !!metadata && metadata.mode === "backstop" && isBackstopReason({ reason: metadata.reason }) &&
    typeof metadata.sourceActor === "string" && metadata.sourceActor.length > 0 && metadata.sourceActor.length <= 512 &&
    typeof metadata.destinationHost === "string" && metadata.destinationHost.length <= 512;
}

function checkBackstopBundleLimits({ raw }: { raw: readonly PackedEntity[] }, _optional: Record<string, never> = {}): void {
  const rows = raw.filter((e) => e.entityType === "raw-row");
  const files = raw.filter((e) => e.entityType === "raw-file");
  if (rows.length > BACKSTOP_LIMITS.rows || files.length > BACKSTOP_LIMITS.files || files.reduce((n, e) => n + (typeof e.state.size === "number" ? e.state.size : Infinity), 0) > BACKSTOP_LIMITS.bytes) throw new Error("Choose at most 200 rows and 50 files totaling at most 50 MB per send.");
}

function isBackstopBody({ body }: { body: unknown }, _optional: Record<string, never> = {}): boolean {
  return !!body && typeof body === "object" && !Array.isArray(body);
}

function hasRepeatedBackstopItems({ rows, files }: BackstopSelection, _optional: Record<string, never> = {}): boolean {
  return new Set(files).size !== files!.length || new Set(rows!.map((row) => `${row.table}:${JSON.stringify(Object.fromEntries(Object.entries(row.pk).sort(([a], [b]) => a.localeCompare(b))))}`)).size !== rows!.length;
}

function checkBackstopDestination({ destinationHost }: { destinationHost: string }, _optional: Record<string, never> = {}): void {
  try { if (new URL(`https://${destinationHost}`).host !== destinationHost) throw new Error(); }
  catch { throw new Error("This send has an invalid destination address."); }
}

import { CONTENT_HASH_VERSION } from "./content-hash.js";
import { PUBLISH_CONTENT_ARTIFACT_FORMAT_VERSION } from "./artifact-format.js";
import { entityKey } from "./planner.js";
import {
  buildPublishContentCatalog,
  type PackedEntity,
  type PublishContentDeps,
  type PublishContentHandler,
  type SkippedPackEntity,
} from "./type-registry.js";
import type { PublishScope } from "./ui/contract.js";

/**
 * @file Task 10 of the publish-content (Publish Content) feature —
 * `ADS-memory/reports/2026-09-18-publish-feature-implementation-plan.md` §4 task 10.
 *
 * The ONE place the export side's "which types may this principal export, and what do they pack"
 * loop lives. Extracted from `routes/publish-content/export.ts` (Task 4) when Task 10's outbound
 * PUSH driver needed the same bundle in memory rather than streamed down a response: two copies of
 * this loop would be two places the per-type permission gate could drift, and that gate is the
 * property plan §3 rule 5 / §5 risk #8 rest on.
 *
 * The two callers differ only in what they do with the entities, which is why the generator is the
 * shared piece and the envelope assembly is not:
 * - `export.ts` streams `packAuthorizedEntities()` straight into the response body, one entity at a
 *   time, so memory stays bounded by one entity regardless of corpus size.
 * - {@link buildExportBundle} accumulates the same generator into an in-memory envelope, because a
 *   push has to hand the whole bundle to `HttpClientPort.send` as one request body. That is a real
 *   memory difference and a disclosed one: a push is bounded by the corpus, a browser download is
 *   not.
 */

/** The narrow authorize seam this module needs — structurally identical to `RouteDeps.authorize`,
 *  declared locally so `features/` never has to import the server's route-deps type. */
export type PublishContentAuthorize = (input: {
  principalId: string;
  permission: string;
  workspaceId: string;
}) => Promise<{ allowed: boolean }>;

export interface PackAuthorizedEntitiesDeps {
  readonly workspaceId: string;
  readonly principalId: string;
  readonly authorize: PublishContentAuthorize;
  readonly publishContentDeps: PublishContentDeps;
}

/**
 * Every entity this principal is allowed to export, across every registered type.
 *
 * `buildPublishContentCatalog()` reads and validates the registry FRESH on every call, never caches
 * it — a contributor registered after an earlier call is visible to the next one.
 *
 * A per-type authorization denial OMITS that type and continues; it is never an error. A principal
 * holding `publish_content.read` but not a given type's own write permission gets a bundle without
 * that type, never a failure — see `export.ts`'s "Two DIFFERENT permission checks" header.
 *
 * @complexity O(t + e) — one `authorize()` call per registered type `t`, then one yield per entity
 * `e` the allowed types pack. Memory is O(1) in the corpus: entities are yielded, never collected.
 */
export async function* packAuthorizedEntities(deps: PackAuthorizedEntitiesDeps): AsyncGenerator<PackedEntity> {
  yield* packHandlerEntities({ ...deps, handlers: buildPublishContentCatalog(deps.publishContentDeps).handlers });
}

/**
 * {@link packAuthorizedEntities}' loop over an already-resolved `handlers` list — the same seam
 * {@link collectSkippedEntities} takes, so the per-type gate and the packed-metadata check are
 * testable without the real registered-contributor graph.
 *
 * @throws Error when a handler packs an entity whose `entityType`/`schemaVersion` is not its own.
 * @complexity O(t + e), as {@link packAuthorizedEntities}.
 */
export async function* packHandlerEntities(input: {
  readonly handlers: readonly PublishContentHandler[];
  readonly authorize: PublishContentAuthorize;
  readonly workspaceId: string;
  readonly principalId: string;
}): AsyncGenerator<PackedEntity> {
  for (const handler of input.handlers) {
    const typeAuth = await input.authorize({
      principalId: input.principalId,
      permission: handler.permission,
      workspaceId: input.workspaceId,
    });
    if (!typeAuth.allowed) continue;

    for await (const entity of handler.pack()) {
      if (entity.entityType !== handler.entityType || entity.schemaVersion !== handler.schemaVersion) {
        throw new Error(
          `publish-content handler '${handler.entityType}' packed incompatible entity metadata ` +
            `(entityType '${entity.entityType}', schema version ${entity.schemaVersion}; expected ` +
            `'${handler.entityType}' version ${handler.schemaVersion})`
        );
      }
      yield entity;
    }
  }
}

/** The export envelope, exactly as `GET .../publish-content/export` serializes it and exactly as
 *  `POST .../publish-content/bundles` accepts it — one shape, so a push never has to reshape what a
 *  pull would have received. */
export interface PublishContentExportEnvelope {
  readonly artifactFormatVersion: number;
  readonly hashVersion: number;
  readonly sourceLabel: string;
  readonly entities: readonly PackedEntity[];
  /** De-duplicated union of every packed entity's `requiredBlobs`, in first-seen order. */
  readonly blobManifest: readonly string[];
  /** Every whole unit an authorized handler found but refused to pack (`SkippedPackEntity`, e.g. a
   *  theme tree `file-tree-policy.ts` blocked) — collected by {@link collectSkippedEntities}. Never
   *  narrowed by {@link selectBundleEntities}: a skipped unit was never selectable in the first
   *  place, so an operator's row selection has nothing to say about it. */
  readonly skipped: readonly SkippedPackEntity[];
}

/**
 * Every whole unit an authorized handler refused to pack, across every registered type — the
 * `listSkipped()` counterpart to {@link packAuthorizedEntities}'s `pack()` loop, kept as its own
 * function (rather than folded into that generator) because a skip is collected EAGERLY per handler
 * (one `listSkipped()` call), not streamed per entity the way packed entities are.
 *
 * Takes an already-resolved `handlers` list, not a `PublishContentDeps` bag, so this stays testable
 * without the real registered-contributor graph — {@link buildExportBundle} is what resolves the
 * catalog and passes its `handlers` through, exactly as `packAuthorizedEntities` does for its own
 * loop.
 *
 * The SAME per-type authorization gate as `packAuthorizedEntities`: a principal not authorized for a
 * type never learns that type refused something, for the identical reason that principal never sees
 * that type's entities either.
 *
 * @complexity O(t) `authorize()` calls plus one `listSkipped()` call per authorized handler that has
 * one.
 */
export async function collectSkippedEntities(input: {
  readonly handlers: readonly PublishContentHandler[];
  readonly authorize: PublishContentAuthorize;
  readonly workspaceId: string;
  readonly principalId: string;
}): Promise<readonly SkippedPackEntity[]> {
  const skipped: SkippedPackEntity[] = [];
  for (const handler of input.handlers) {
    if (!handler.listSkipped) continue;
    const typeAuth = await input.authorize({
      principalId: input.principalId,
      permission: handler.permission,
      workspaceId: input.workspaceId,
    });
    if (!typeAuth.allowed) continue;
    skipped.push(...(await handler.listSkipped()));
  }
  return skipped;
}

/**
 * Narrows an already-built envelope to the entities the operator actually chose, by
 * `planner.ts`'s own {@link entityKey} string.
 *
 * This is where "deselect a row" becomes real, and it is deliberately HERE rather than at apply
 * time: the destination never receives a deselected entity at all, so no downstream code path —
 * not the peer's planner, not its apply loop, not a peer running an older build that has never
 * heard of a selection — has to remember to skip it. Exclusion by construction, the same property
 * `ui/report-rows.ts`'s header states for a skipped row.
 *
 * `blobManifest` is recomputed from the surviving entities rather than carried over, so a push of
 * two selected posts does not upload the bytes of forty deselected images.
 *
 * An empty `selectedKeys` set returns an EMPTY bundle, not the whole corpus: "the operator selected
 * nothing" and "the operator expressed no preference" are different states, and the caller (never
 * this function) is what decides which one it has — `push/plan` only calls this when a selection
 * was actually sent.
 *
 * @complexity O(e) time in the envelope's entity count, O(e) space for the narrowed copy.
 */
export function selectBundleEntities(
  envelope: PublishContentExportEnvelope,
  selectedKeys: ReadonlySet<string>
): PublishContentExportEnvelope {
  const entities = envelope.entities.filter((entity) => selectedKeys.has(entityKey(entity.entityType, entity.id)));
  const requiredBlobs = new Set<string>();
  for (const entity of entities) for (const sha of entity.requiredBlobs) requiredBlobs.add(sha);
  return { ...envelope, entities, blobManifest: Array.from(requiredBlobs) };
}

/**
 * Narrows an already-built envelope to a section (or a section plus specific rows) — the
 * `plan-publish-sections-2026-09-25.md` §1 "Publish pages"/"Publish all content" mechanism. Runs
 * BEFORE {@link selectBundleEntities} on the `push/plan` route (`scope` narrows first, then an
 * operator's row selection narrows that result further), which is why a themes-only scope never even
 * uploads a media blob: `blobManifest` here is already scoped, and `selectBundleEntities` only ever
 * shrinks further from there.
 *
 * `entityTypes` and `entityKeys`, when both given, AND together (an id from a type not in
 * `entityTypes` matches nothing) — this is deliberately stricter than `selectBundleEntities`, which
 * only ever narrows by key. `skipped` is filtered by the identical predicate: a refused theme tree
 * shows up in a `theme-files` scope and nowhere else, the same as any other theme row would.
 *
 * @complexity O(e + s) time in the envelope's entity and skipped counts, O(e + s) space for the
 * narrowed copy.
 */
export function applyPublishScope(
  envelope: PublishContentExportEnvelope,
  scope: PublishScope
): PublishContentExportEnvelope {
  const entityKeys = scope.entityKeys ? new Set(scope.entityKeys) : null;
  const matchesScope = (type: string, id: string): boolean => {
    if (scope.entityTypes && !scope.entityTypes.includes(type)) return false;
    if (entityKeys && !entityKeys.has(entityKey(type, id))) return false;
    return true;
  };

  const entities = envelope.entities.filter((entity) => matchesScope(entity.entityType, entity.id));
  const requiredBlobs = new Set<string>();
  for (const entity of entities) for (const sha of entity.requiredBlobs) requiredBlobs.add(sha);
  const skipped = envelope.skipped.filter((entry) => matchesScope(entry.entityType, entry.id));

  return { ...envelope, entities, blobManifest: Array.from(requiredBlobs), skipped };
}

/** What {@link includeReferencedEntities} returns: the widened envelope, plus which in-scope rows
 *  each ADDED entity was carried along for (keyed and valued by {@link entityKey}). An entity the
 *  envelope already held is never in `includedFor`. */
export interface ReferencedEntityInclusion {
  readonly envelope: PublishContentExportEnvelope;
  readonly includedFor: ReadonlyMap<string, readonly string[]>;
}

/** The handlers {@link includeReferencedEntities} asks what each entity uses — a built catalog's
 *  `handlerByType`, or any map of `references` in a test. */
export type ReferenceHandlers = ReadonlyMap<string, Pick<PublishContentHandler, "references">>;

/** `source`'s entities not already in the envelope, by `type:id` and `type:slug` (an id wins over a
 *  colliding slug). @complexity O(s). */
function indexCarriable(source: PublishContentExportEnvelope, held: ReadonlySet<string>): Map<string, PackedEntity> {
  const byAddress = new Map<string, PackedEntity>();
  const candidates = source.entities.filter((entity) => !held.has(entityKey(entity.entityType, entity.id)));
  for (const entity of candidates) byAddress.set(entityKey(entity.entityType, entity.id), entity);
  for (const entity of candidates) {
    const slug = entity.state.slug;
    const address = typeof slug === "string" && slug.length > 0 ? entityKey(entity.entityType, slug) : null;
    if (address !== null && !byAddress.has(address)) byAddress.set(address, entity);
  }
  return byAddress;
}

/**
 * Owner decision 2026-09-25 ("images go along with pages and posts"), generalized by plan G3. Widens
 * an already-scoped (and already row-selected) envelope with every entity from `source` that an
 * entity still in `envelope` uses ({@link PublishContentHandler.references}), transitively: a page
 * brings its images and embedded widgets, a widget its form, menu or term, an entry its collection,
 * a term its taxonomy and parent. Matched by the target's id or slug.
 *
 * Runs AFTER {@link applyPublishScope} and {@link selectBundleEntities} on `push/plan`, so what is
 * carried along is derived from the rows actually being published: a deselected page brings
 * nothing, and select-all, confirm's narrowed re-plan and execute all see the same rule because the
 * bundle the peer plans IS the bundle it executes. Never adds an entity `envelope` already holds (an
 * in-scope row is the operator's own choice, not an add-on), and never walks through one: that row's
 * own references are its own. `source` never holds a trashed row (every `pack()` skips them).
 *
 * `includedFor` names the in-scope ROOTS that reach an added entity, even through another carried
 * one (page → widget → form names the page for both), because only a root can be ticked.
 *
 * Added entities come FIRST, ahead of the kept ones. Whether an added row is then SHOWN is decided
 * after the peer plans it: an unchanged one is dropped (`report-labels.ts`'s
 * `keepChangingIncludedEntities`).
 *
 * @complexity O(s + r·c) time — one pass to index `source`, then per kept root `r` a walk over at
 * most the `c` entities it can reach; O(s) extra space.
 */
export function includeReferencedEntities(
  envelope: PublishContentExportEnvelope,
  source: PublishContentExportEnvelope,
  handlers: ReferenceHandlers
): ReferencedEntityInclusion {
  const referencesOf = (entity: PackedEntity) => handlers.get(entity.entityType)?.references?.(entity) ?? [];
  const held = new Set(envelope.entities.map((entity) => entityKey(entity.entityType, entity.id)));
  const carriable = indexCarriable(source, held);

  const added: PackedEntity[] = [];
  const rootsByKey = new Map<string, Set<string>>();
  function includeRoot({ root }: { root: PackedEntity }, _options: Record<string, never> = {}): void {
    const rootEntityKey = entityKey(root.entityType, root.id);
    const seen = new Set<string>();
    const pending = [...referencesOf(root)];
    while (pending.length > 0) {
      const ref = pending.pop()!;
      const target = carriable.get(entityKey(ref.entityType, ref.key));
      if (!target) continue;
      const key = entityKey(target.entityType, target.id);
      if (seen.has(key)) continue;
      seen.add(key);
      if (!rootsByKey.has(key)) {
        rootsByKey.set(key, new Set());
        added.push(target);
      }
      rootsByKey.get(key)!.add(rootEntityKey);
      pending.push(...referencesOf(target));
    }
  }
  for (const root of envelope.entities) includeRoot({ root });
  const includedFor = new Map([...rootsByKey].map(([key, roots]) => [key, [...roots].sort()] as const));
  if (added.length === 0) return { envelope, includedFor };

  const entities = [...added, ...envelope.entities];
  const requiredBlobs = new Set<string>();
  for (const entity of entities) for (const sha of entity.requiredBlobs) requiredBlobs.add(sha);
  return { envelope: { ...envelope, entities, blobManifest: Array.from(requiredBlobs) }, includedFor };
}

/**
 * Accumulates {@link packAuthorizedEntities} into a complete in-memory envelope, for the push
 * driver. See this file's header for why the streaming caller does NOT use this.
 *
 * @complexity O(t + e) time; O(e) MEMORY — the whole corpus is held at once. Deliberate and
 * disclosed: an HTTP request body cannot be produced lazily through `HttpClientPort`.
 */
export async function buildExportBundle(
  deps: PackAuthorizedEntitiesDeps & { sourceLabel: string }
): Promise<PublishContentExportEnvelope> {
  const entities: PackedEntity[] = [];
  const requiredBlobs = new Set<string>();
  for await (const entity of packAuthorizedEntities(deps)) {
    entities.push(entity);
    for (const sha of entity.requiredBlobs) requiredBlobs.add(sha);
  }
  // A second, fresh catalog read (rule 2, this file's header) — cheap (small handler count) and
  // kept separate from the `pack()` loop above rather than sharing one catalog build, since a skip
  // is collected eagerly per handler while packed entities stream per entity.
  const { handlers } = buildPublishContentCatalog(deps.publishContentDeps);
  const skipped = await collectSkippedEntities({
    handlers,
    authorize: deps.authorize,
    workspaceId: deps.workspaceId,
    principalId: deps.principalId,
  });
  return {
    artifactFormatVersion: PUBLISH_CONTENT_ARTIFACT_FORMAT_VERSION,
    hashVersion: CONTENT_HASH_VERSION,
    sourceLabel: deps.sourceLabel,
    entities,
    blobManifest: Array.from(requiredBlobs),
    skipped,
  };
}

import { TOVU_MAX_UPLOAD_BYTES } from "#src/contracts/core/upload-limits";
import { scanTextForSecrets } from "#src/features/webhooks/secret-scan-guard";

/**
 * @file `publish-files-plan-2026-09-24.md` §2 — the one pure module every file-tree publish type
 * (`theme-files` today; `agent-skill`/`agent-plugin`/`site-plugin` later) filters through, on BOTH
 * sides of a publish: the source decides what it is willing to pack, and the destination re-runs the
 * identical check in `precheck` because it never trusts the source's own filtering (that file's §3
 * step 1). One module, one set of rules, so the two can never drift apart.
 *
 * ## Why a tree is blocked WHOLE, never trimmed
 *
 * A theme (or skill, or plugin) is one thing an operator recognizes and one thing that must swap
 * atomically (§0's own reasoning for why a whole tree, not one file, is the publish unit). Silently
 * dropping the one file that failed a check would ship a theme missing a file it depends on — broken
 * in a way nothing surfaces until a page 404s. Every check in this module therefore reports one
 * blocking reason for the WHOLE tree, never a per-file skip list.
 *
 * ## What this module does NOT decide
 *
 * - Which files belong to one theme's tree at all (excluding `__original-themes__/`, `README.md`,
 *   generated build output) — that is `pack()`'s own walk (`features/theme/publish-content.ts`,
 *   S-F3), the same way `site-backup/sources.ts`'s `walkTree` decides its own scope before this kind
 *   of check would even apply.
 * - The human-facing "<title> was not published: ..." sentence — every reason this module returns
 *   names the offending path/fact only; the caller (which knows the tree's display title) prefixes
 *   it. Keeping the title out of this module is what lets `checkTreeFiles` stay a pure function of
 *   `(kind, files)`, with no caller-specific wording to keep in sync.
 *
 *   One exception: the disallowed-extension reason (the most common real refusal — a stray video or
 *   other unpublishable file dropped into a theme folder) is returned already final, via
 *   {@link wrapTreePolicyReason}'s sentinel, and a caller must pass every `checkTreeFiles` reason
 *   through that function rather than concatenating a title itself. The row already shows the tree's
 *   title in its own label column, so `"Theme: x was not published: ... has a file type ('mp4') that
 *   is not allowed for this tree"` repeated the label and read as an internal validator message, not
 *   something an operator asked for. Every other reason in this module (path shape, deny-list, caps,
 *   secret scan) is unaffected and still gets the title prefix.
 */

/** Every file-tree publish type this policy module knows about, per §1's inventory table. Only
 *  `theme-files` has a real contributor yet (S-F3/S-F4) — the other three are declared here now so
 *  the shape is fixed once, and the static test in this module's own `__tests__/` pins that this set
 *  never shrinks or silently gains an unreviewed 5th kind. */
export type FileTreeKind = "theme-files" | "agent-skill" | "agent-plugin" | "site-plugin";

/** One kind's static shape: `baseDir` is the fixed, non-configurable first path segment under the
 *  site root (§2's own inventory paths) — never itself a caller-chosen value, which is what makes
 *  {@link resolveTreeRelativePath}'s output structurally unable to ever equal a bare site-root
 *  filename (`config.json`, `.site-meta.json`, ...): every resolved path is `${baseDir}/...`, and no
 *  site-root file name contains a `/`. `idSegmentCount` is how many further, tree-address-choosing
 *  segments follow (theme-files: tier + id; agent-skill: workspace + id; site-plugin: id + version).
 *  `allowedExtensions` is `null` for a code-class kind (§2: "Code-class kinds allow any extension"). */
export interface FileTreeKindSpec {
  readonly baseDir: string;
  readonly idSegmentCount: number;
  readonly allowedExtensions: readonly string[] | null;
}

/** §2's extension allow-list for `theme-files` — any file whose extension is not on this list blocks
 *  the whole tree (never silently dropped; see this file's header). */
export const THEME_FILE_TREE_ALLOWED_EXTENSIONS: readonly string[] = [
  "html", "htm", "css", "js", "mjs", "map", "json", "svg", "png", "jpg", "jpeg", "gif", "webp",
  "avif", "ico", "woff", "woff2", "ttf", "otf", "txt", "md", "xml", "webmanifest", "liquid",
];

export const FILE_TREE_KINDS: Readonly<Record<FileTreeKind, FileTreeKindSpec>> = {
  "theme-files": { baseDir: "themes", idSegmentCount: 2, allowedExtensions: THEME_FILE_TREE_ALLOWED_EXTENSIONS },
  "agent-skill": { baseDir: "skills", idSegmentCount: 2, allowedExtensions: null },
  "agent-plugin": { baseDir: "agent-plugins", idSegmentCount: 2, allowedExtensions: null },
  "site-plugin": { baseDir: "plugins", idSegmentCount: 2, allowedExtensions: null },
};

/** §2: every id segment (a tier name, a theme id, a workspace id, a package digest, ...) must match
 *  this shape — lowercase alphanumerics, optionally hyphen/dot-joined, no leading/trailing separator,
 *  no empty segment. */
const ID_SEGMENT_PATTERN = /^[a-z0-9]+(?:[-.][a-z0-9]+)*$/;
const MAX_ID_SEGMENT_LENGTH = 64;

/**
 * Validates and joins one file tree's own address segments (e.g. `["static", "basic"]` for a theme)
 * into the POSIX-relative root a real contributor resolves against its own themes/skills/plugins
 * root. Returns `null` when any segment fails {@link ID_SEGMENT_PATTERN}/length, the segment count
 * does not match `kind`'s `idSegmentCount`, or a segment is empty.
 *
 * Every kind's result is prefixed with its own fixed, non-configurable `baseDir` — this is the
 * property the static boundary test (§2 item b) checks: no combination of (kind, valid id segments)
 * can ever produce a bare site-root filename, because a site-root file's own name never contains `/`
 * and every result here does.
 *
 * @complexity O(s) in the segment count (fixed, small).
 */
export function resolveTreeRelativePath(kind: FileTreeKind, idSegments: readonly string[]): string | null {
  const spec = FILE_TREE_KINDS[kind];
  if (idSegments.length !== spec.idSegmentCount) return null;
  for (const segment of idSegments) {
    if (segment.length === 0 || segment.length > MAX_ID_SEGMENT_LENGTH || !ID_SEGMENT_PATTERN.test(segment)) {
      return null;
    }
  }
  return [spec.baseDir, ...idSegments].join("/");
}

/** §2 deny-list — path SEGMENTS (never just the leaf name) that block a tree at any depth: a nested
 *  `.git` checkout, a vendored `node_modules`, or this feature's own staging/backup directories
 *  (never legitimately part of a source tree — {@link normalizeMode}'s caller stages under exactly
 *  these names, so a tree that already contains one is either corrupt or hostile). */
const DENY_SEGMENTS: ReadonlySet<string> = new Set([".git", "node_modules", ".publish-staging", ".publish-previous"]);

/** §2 deny-list — file EXTENSIONS (case-insensitive) that block a tree at any depth: private key
 *  material and raw database files, neither of which belongs in a published content/code tree. */
const DENY_EXTENSIONS: ReadonlySet<string> = new Set(["pem", "key", "p12", "pfx", "db", "sqlite", "db-wal", "db-shm"]);

/** Matches `.mcp.<anything>.json` — an MCP server config file, which can carry secrets in its own
 *  right (§2's separate "Structural secret rule" governs the one shape of that file this module still
 *  allows through: an `agent-plugin`'s own `mcp.json`/`.mcp.json`, checked by
 *  {@link checkMcpJsonSecretPlaceholders} instead of being denied outright). */
const MCP_CONFIG_NAME_PATTERN = /^\.mcp\..*\.json$/;

/**
 * OS-generated junk names (macOS Finder, Windows Explorer, AppleDouble sidecar files) that a real
 * contributor never means to publish and that reappear on disk on their own (macOS recreates
 * `.DS_Store` the moment a folder is opened in Finder again). These are IGNORED, not denied: a
 * caller walking a tree ({@link ../../theme/publish-content.ts}'s `walkThemeTree`) excludes them
 * before a file ever becomes a candidate at all. {@link checkTreeFiles} REFUSES one that still
 * reaches it (a sender whose walker did not skip it): the destination writes every file it is sent,
 * so a filtered-out name would be written without any check. Never blocking a tree the WALKER
 * found one of these in is the point of this set existing separately from
 * {@link deniedFileNameReason} — see `publish-files-plan-2026-09-24.md`'s real-world case: a theme's
 * `.DS_Store`, recreated by Finder, silently refused a legitimate publish with no reason shown.
 *
 * @complexity O(1).
 */
export function isIgnoredTreeFileName(name: string): boolean {
  if (name === ".DS_Store" || name === "Thumbs.db" || name === "desktop.ini") return true;
  if (name === ".Spotlight-V100" || name === ".Trashes") return true;
  if (name.startsWith("._")) return true; // AppleDouble sidecar, e.g. "._photo.png".
  return false;
}

/**
 * Whether `name` (a bare file name, not a path) is denied at ANY depth within a tree, and why.
 * `.env`/`.env.*` (any suffix), `.npmrc`/`.netrc` (package manager credentials), `.mcp.*.json`
 * (MCP server env — never THIS shape; an agent-plugin's own `mcp.json`/`.mcp.json` is a different,
 * unprefixed name and is checked by {@link checkMcpJsonSecretPlaceholders} instead),
 * `.fs-custom-root.json` (a local absolute path), `.storage-secret.json` (a Postgres site's sealed
 * connection string, `storage-secret.ts`), and any `id_rsa`/`id_ed25519` private key file
 * (with or without an extension, e.g. `id_rsa.bak`). macOS's `.DS_Store` and its siblings are NOT
 * here — see {@link isIgnoredTreeFileName}: they are silently excluded, never a whole-tree DENY.
 *
 * @complexity O(1).
 */
function deniedFileNameReason(name: string): string | null {
  if (name === ".env" || name.startsWith(".env.")) return "looks like an environment file";
  if (name === ".npmrc" || name === ".netrc") return "is a package-manager credential file";
  if (MCP_CONFIG_NAME_PATTERN.test(name)) return "is an MCP server configuration file, which can hold secrets";
  if (name === ".fs-custom-root.json") return "holds a local filesystem path, never portable across machines";
  if (name.includes(".storage-secret.json")) return "is a site's sealed database connection string";
  if (["id_rsa", "id_ed25519"].some((prefix) => name === prefix || name.startsWith(`${prefix}.`))) {
    return "looks like a private SSH key";
  }
  return null;
}

/** §2: `.site-meta.json` and `config.json` are denied only AT THE TREE ROOT (depth 0) — both are a
 *  site's own per-install identity/host config, never a real theme/skill/plugin file, but the name
 *  alone is not suspicious at depth inside a tree (a theme could legitimately have its own nested
 *  `config.json` fixture). `${path}` here is already known to contain no `/` when this is checked. */
const ROOT_ONLY_DENIED_NAMES: ReadonlySet<string> = new Set([".site-meta.json", "config.json"]);

/** §3 caps: file ≤ `TOVU_MAX_UPLOAD_BYTES`; tree ≤ 64 MiB and ≤2000 files. Exported so a caller
 *  (or a test) can reference the exact numbers rather than re-deriving them. */
export const FILE_TREE_LIMITS = {
  maxFileBytes: TOVU_MAX_UPLOAD_BYTES,
  maxTreeBytes: 64 * 1024 * 1024,
  maxTreeFiles: 2000,
} as const;

/** Above this size, a text-like file is not content-scanned (§2's content-scan clause: "every file
 *  ≤1 MB whose extension is text-like"). A binary this large legitimately exceeds any real theme
 *  source file; scanning it would cost real CPU for a file type this check does not target.
 *  Exported so a `pack()` (`features/theme/publish-content.ts`) can decide, once, whether a file is
 *  even worth decoding into a `textSample` before handing it to {@link checkTreeFiles} — that
 *  decision must use the SAME threshold this module scans against, or a file just over the line would
 *  be decoded for nothing (never scanned) while one just under it would be silently skipped by a
 *  caller using a different number. */
export const MAX_SECRET_SCAN_BYTES = 1024 * 1024;

/** Extensions whose content is worth running {@link scanTextForSecrets} against — a strict subset of
 *  {@link THEME_FILE_TREE_ALLOWED_EXTENSIONS} (binary formats like `png`/`woff2` are never text). */
const TEXT_LIKE_SCAN_EXTENSIONS: ReadonlySet<string> = new Set([
  "html", "htm", "css", "js", "mjs", "map", "json", "svg", "txt", "md", "xml", "webmanifest", "liquid",
]);

/** @complexity O(1). */
function extensionOf(relPath: string): string {
  const base = relPath.slice(relPath.lastIndexOf("/") + 1);
  const dot = base.lastIndexOf(".");
  return dot <= 0 ? "" : base.slice(dot + 1).toLowerCase();
}

/** @complexity O(1). */
function baseNameOf(relPath: string): string {
  return relPath.slice(relPath.lastIndexOf("/") + 1);
}

/** Common video container extensions — the one file type an operator is most likely to accidentally
 *  drop into a theme folder (a recorded demo, a hero clip meant for a CDN instead), which is why the
 *  terse reason names it specifically rather than folding it into the generic "file type" wording. */
const VIDEO_EXTENSIONS: ReadonlySet<string> = new Set(["mp4", "mov", "mkv", "avi", "webm", "m4v", "wmv", "flv"]);

/** The sentinel prefix that marks a `checkTreeFiles` reason as already operator-facing and final —
 *  see this file's header and {@link wrapTreePolicyReason}. Never itself compared against outside this
 *  module; a caller calls {@link wrapTreePolicyReason} instead of checking for this directly. */
const PREFORMATTED_REASON_PREFIX = "Can't publish:";

/**
 * The disallowed-extension reason, terse and operator-facing (this file's header exception) — no
 * title, no path, no raw extension string, just what the operator would ask when told a publish
 * failed: what kind of file, and which one.
 *
 * @complexity O(1).
 */
function disallowedExtensionReason(path: string): string {
  const name = baseNameOf(path);
  const ext = extensionOf(path);
  return VIDEO_EXTENSIONS.has(ext)
    ? `${PREFORMATTED_REASON_PREFIX} contains a video file (${name})`
    : `${PREFORMATTED_REASON_PREFIX} contains a file type that isn't allowed (${name})`;
}

/**
 * Wraps a `checkTreeFiles` reason with `title` for display, UNLESS the reason is already final
 * (currently only {@link disallowedExtensionReason}'s output) — the one seam a caller uses instead of
 * concatenating `"${title} was not published: ${reason}"` itself, so the sentinel that marks a
 * preformatted reason lives in exactly one place.
 *
 * @complexity O(1).
 */
export function wrapTreePolicyReason(title: string, reason: string): string {
  return reason.startsWith(PREFORMATTED_REASON_PREFIX) ? reason : `${title} was not published: ${reason}`;
}

/**
 * §3's "path shape (source AND destination)" rule for ONE relative path, plus §2's deny-list. Applied
 * identically on the packing side and the destination's `precheck` re-check (this file's own header),
 * so a path either side would refuse is refused by both.
 *
 * @returns A human-readable reason `relPath` is not publishable, or `null` when it is clean of every
 *   shape/deny-list rule this function checks — {@link checkTreeFiles} additionally applies the
 *   per-kind extension allow-list, caps, and content scan, none of which a single path can answer on
 *   its own.
 * @complexity O(k) in `relPath`'s length (segment split, one deny-list lookup per segment).
 */
export function checkTreePath(relPath: string): string | null {
  const shapeReason = treePathShapeReason({ relPath });
  if (shapeReason) return shapeReason;
  const segments = relPath.split("/");
  const segmentReason = treePathSegmentReason({ relPath, segments });
  if (segmentReason) return segmentReason;

  const name = segments[segments.length - 1] as string;
  const deniedReason = deniedFileNameReason(name);
  if (deniedReason) return `"${relPath}" ${deniedReason}`;
  if (segments.length === 1 && ROOT_ONLY_DENIED_NAMES.has(name)) {
    return `"${relPath}" is a per-install site file, never part of a published tree`;
  }

  const ext = extensionOf(relPath);
  if (DENY_EXTENSIONS.has(ext)) return `"${relPath}" has a '.${ext}' extension, which is never published`;

  return null;
}

/** Checks raw path shape before interpreting segments. @complexity O(k) in path length. */
function treePathShapeReason({ relPath }: { relPath: string }, _options = {}): string | null {
  if (relPath.length === 0) return `"${relPath}" is empty`;
  if (relPath.length > 512) return `"${relPath}" is longer than the 512-character path limit`;
  if (relPath.startsWith("/")) return `"${relPath}" must be relative, not start with '/'`;
  if (relPath.includes("\\")) return `"${relPath}" contains a backslash, which is never allowed in a tree path`;
  // eslint-disable-next-line no-control-regex -- deliberately matching a literal NUL byte, not a typo.
  if (/\u0000/.test(relPath)) return `"${relPath}" contains a NUL byte`;

  return null;
}

/** Checks depth and every directory component. @complexity O(k) in path length. */
function treePathSegmentReason({ relPath, segments }: { relPath: string; segments: string[] }, _options = {}): string | null {
  if (segments.length > 16) return `"${relPath}" is nested deeper than the 16-level limit`;

  for (const segment of segments) {
    if (segment.length === 0) return `"${relPath}" contains an empty path segment`;
    if (segment === "." || segment === "..") return `"${relPath}" contains a '${segment}' segment, which is never allowed`;
    if (DENY_SEGMENTS.has(segment)) return `"${relPath}" contains a '${segment}' segment, which is never published`;
  }

  return null;
}

/**
 * §2's structural secret rule for an agent-plugin's own `mcp.json`/`.mcp.json`: every `env`/`headers`
 * value must be empty or a `${VAR}` placeholder — never a literal token. Exported for `agent-plugin`'s
 * own contributor (S-F5) to call directly on a candidate file's text; not invoked by
 * {@link checkTreeFiles} itself, since only `agent-plugin` trees ever carry this file shape and
 * {@link checkTreeFiles} has no per-file "this one is mcp.json" signal to key off of without adding a
 * caller contract every other kind would have to satisfy for nothing.
 *
 * @returns A reason naming the first offending key, or `null` when every `env`/`headers` value (at
 *   any nesting, including each server's own sections) is empty or a `${...}` placeholder, or when the JSON
 *   does not parse (a malformed `mcp.json` is a different tree's own problem, not this check's).
 * @complexity O(n) in the JSON text length.
 */
export function checkMcpJsonSecretPlaceholders(jsonText: string): string | null {
  let parsed: unknown;
  try {
    parsed = JSON.parse(jsonText);
  } catch {
    return null;
  }
  if (typeof parsed !== "object" || parsed === null) return null;

  return mcpConfigReason({ value: parsed, path: "" });
}

/** Find env/header sections in server declarations as well as the legacy root shape.
 * @complexity O(n) JSON nodes; traversal uses O(depth) stack space. */
function mcpConfigReason({ value, path }: { value: unknown; path: string }, _options = {}): string | null {
  if (typeof value !== "object" || value === null) return null;
  const record = value as Record<string, unknown>;
  for (const key of ["env", "headers"] as const) {
    const section = path ? `${path}.${key}` : key;
    const reason = mcpSectionReason({ section, value: record[key] });
    if (reason) return reason;
  }
  return mcpNestedConfigReason({ record, path });
}

/** Search child declarations only after this node's env/headers have passed.
 * @complexity O(n) JSON nodes; traversal uses O(depth) stack space. */
function mcpNestedConfigReason(
  { record, path }: { record: Record<string, unknown>; path: string },
  _options: Record<string, never> = {}
): string | null {
  for (const [key, entry] of Object.entries(record)) {
    if (key === "env" || key === "headers") continue;
    const reason = mcpConfigReason({ value: entry, path: path ? `${path}.${key}` : key });
    if (reason) return reason;
  }
  return null;
}

/** Check every string leaf in an MCP section, including nested objects and arrays.
 * @complexity O(n) section nodes; O(depth) stack space. */
function mcpSectionReason({ section, value }: { section: string; value: unknown }, _options = {}): string | null {
  if (typeof value === "string") {
    return value.length === 0 || /^\$\{[^}]+\}$/.test(value) ? null
      : `has a key written into mcp.json (${section}); move it to live's settings`;
  }
  if (typeof value !== "object" || value === null) return null;
  for (const [key, entry] of Object.entries(value)) {
    const reason = mcpSectionReason({ section: `${section}.${key}`, value: entry });
    if (reason) return reason;
  }
  return null;
}

/** Mode bits {@link normalizeMode} strips down to — the exec bit is the only thing a published tree's
 *  mode is ever allowed to carry beyond ordinary read/write; setuid/setgid/sticky and group/other
 *  write bits are never meaningful for a published static/content tree and are a real privilege-
 *  escalation surface if they ever reached disk unmodified. */
const NORMALIZED_FILE_MODE = 0o644;
const NORMALIZED_EXEC_MODE = 0o755;

/**
 * §3's mode normalization: any raw `mode` with any of the owner/group/other EXECUTE bits set becomes
 * `0o755`; every other mode (including one with setuid/setgid/sticky/write-only-by-others bits, which
 * this collapses away entirely) becomes the plain `0o644`. Applied identically to every packed file
 * before it is ever staged, so a hostile or accidental setuid bit never survives a publish.
 *
 * @complexity O(1).
 */
export function normalizeMode(mode: number): number {
  return (mode & 0o111) !== 0 ? NORMALIZED_EXEC_MODE : NORMALIZED_FILE_MODE;
}

/** One file {@link checkTreeFiles} evaluates. `textSample` is the file's own text content (or a
 *  size-capped prefix of it) — required for a real block-or-pass answer on a text-like, ≤1 MiB file;
 *  see {@link checkTreeFiles}'s own doc for what an absent sample means. */
export interface FileTreeFileInput {
  readonly path: string;
  readonly size: number;
  readonly mode: number;
  readonly textSample?: string;
}

/**
 * The whole-tree gate: every file-shape/deny-list/extension/cap/secret-scan rule in §2/§3, over one
 * tree's full file list. The allow-list is applied first (kind-specific extensions), then the
 * deny-list (via {@link checkTreePath}, kind-agnostic), then the content scan — matching §2's own
 * stated order. A tree fails as a WHOLE the instant any file fails any rule (this file's header).
 *
 * `textSample` contract: a file with a text-like extension ({@link TEXT_LIKE_SCAN_EXTENSIONS})
 * at or under {@link MAX_SECRET_SCAN_BYTES} must carry its text for scanning. A missing sample
 * blocks the tree: hash verification alone cannot establish that the bytes are free of secrets.
 * The source walker and destination byte reader must both supply the qualifying file's sample.
 *
 * @returns One human-readable reason (naming the offending path) for the whole tree, or `null` when
 *   every file passes every check.
 * @complexity O(f + b) — one pass over the `f` files for shape/deny/extension/cap checks, plus one
 *   secret scan (§(p) pattern count times sample length) per qualifying file; `b` is the sum of every
 *   scanned file's `textSample` length.
 */
export function checkTreeFiles(kind: FileTreeKind, files: readonly FileTreeFileInput[]): string | null {
  const limits = FILE_TREE_LIMITS;
  if (files.length > limits.maxTreeFiles) {
    return `this tree has ${files.length} files, more than the ${limits.maxTreeFiles}-file limit`;
  }
  const totalBytes = files.reduce((sum, file) => sum + file.size, 0);
  if (totalBytes > limits.maxTreeBytes) {
    return `this tree is ${totalBytes} bytes, larger than the ${limits.maxTreeBytes}-byte limit`;
  }

  const seenLowercase = new Map<string, string>();
  const spec = FILE_TREE_KINDS[kind];

  for (const file of files) {
    const reason = treeFileReason({ file, spec, seenLowercase });
    if (reason) return reason;
  }

  return null;
}

/** Checks one file in original refusal order, recording case collisions. @complexity O(k) in path length. */
function treeFileReason({ file, spec, seenLowercase }: {
  file: FileTreeFileInput; spec: FileTreeKindSpec; seenLowercase: Map<string, string>;
}, _options = {}): string | null {
  const shapeReason = checkTreePath(file.path);
  if (shapeReason) return shapeReason;
  // A walker skips OS junk before this runs (`isIgnoredTreeFileName`), so one reaching here came
  // from a sender that did not — on the destination, every listed file is written. Refused, never
  // filtered: filtering would let it skip every check below and still be staged.
  if (isIgnoredTreeFileName(file.path.slice(file.path.lastIndexOf("/") + 1))) {
    return `"${file.path}" is a system file that is never published`;
  }

  const lower = file.path.toLowerCase();
  const earlier = seenLowercase.get(lower);
  if (earlier !== undefined) {
    return `"${earlier}" and "${file.path}" differ only by letter case, which is not safe to publish`;
  }
  seenLowercase.set(lower, file.path);

  if (file.size > FILE_TREE_LIMITS.maxFileBytes) {
    return `"${file.path}" is ${file.size} bytes, larger than the ${FILE_TREE_LIMITS.maxFileBytes}-byte per-file limit`;
  }

  return treeFileContentReason({ file, spec });
}

/** Applies the kind's allowlist, refusing missing scan input before checking text.
 * @complexity O(b) in sample length. */
function treeFileContentReason({ file, spec }: { file: FileTreeFileInput; spec: FileTreeKindSpec }, _options = {}): string | null {
  const ext = extensionOf(file.path);
  if (spec.allowedExtensions) {
    if (!spec.allowedExtensions.includes(ext)) {
      return disallowedExtensionReason(file.path);
    }
  }

  if (TEXT_LIKE_SCAN_EXTENSIONS.has(ext) && file.size <= MAX_SECRET_SCAN_BYTES) {
    if (file.textSample === undefined) return `"${file.path}" is missing the text required for its secret scan`;
    const hits = scanTextForSecrets(file.textSample);
    if (hits.length > 0) {
      return `"${file.path}" looks like it holds a key (${hits[0]!.patternName})`;
    }
  }
  return null;
}

import { embedMarkerTarget, galleryMediaReferences, scanEmbedMarkers } from "@jini-ai/cms/widgets/markers";

/**
 * @file Which media a packed post/page state points at — owner decision 2026-09-25, "images go along
 * with pages and posts": a scoped "Publish pages"/"Publish posts" run carries the media its in-scope
 * items reference (`export-bundle.ts`'s `includeReferencedEntities`, through `content-references.ts`).
 *
 * Reads the packed WIRE state (`features/post/publish-content.ts`'s `toPublishableState`), not a
 * `PostRecord`, because the scope layer only ever holds packed entities. Every reference shape the
 * content DB actually holds is covered:
 * - a ref-based TipTap `image`/`media` node's `attrs.assetId` (ADR-027 §4) — the same walk
 *   `Jini/packages/cms/src/widgets/resolver-service.ts` and `routes/site/media-rendition.ts` each carry a private copy of;
 *   neither is importable from here (both sit above `features/publish-content/` in the layering);
 * - a legacy `image` node's `attrs.src` — an admin `/media/{id}/…` URL or a public `/m/{key}/…` URL;
 * - any mark's string attrs holding such a URL — a `link` mark whose `href` is a media file's copied
 *   public URL (the Media panel shows it for exactly that);
 * - an `"html"` body's `data-embed-config` media marker, by `id ?? slug` via `embedMarkerTarget` (the
 *   same case-insensitive type match and precedence the embed resolver uses), and any `/m/{key}/` URL
 *   in it;
 * - `seoExtJson.ogImage`/`twitterImage`, a `"{assetId}:{transformName}"` ref or an absolute URL
 *   (`Jini/packages/cms/src/seo/types.ts`).
 *
 * Not covered: an old slug kept alive only by `media_slug_history` (matched against the CURRENT slug
 * only). Media an embedded widget holds is not read here: the widget itself is carried
 * (`content-references.ts`), and its own `references()` reads its config's media URLs through
 * {@link collectMediaUrlKeys}.
 *
 * Returns KEYS — an id or a slug — never resolved media: the caller matches them against the media
 * entities it actually holds, so a key naming nothing (a deleted asset, a stray URL) adds nothing.
 */

/** `/m/{key}/…` (public rendition route) and `/media/{id}/…` (admin media route, what a legacy
 *  `image` node's `src` was saved as). The key stops at the next `/`, quote, `?`, `#` or whitespace. */
const MEDIA_URL_PATTERN = /\/(?:m|media)\/([^/"'\s?#<>]+)\//g;

const SEO_IMAGE_FIELDS = ["ogImage", "twitterImage"] as const;

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** Adds every media key a URL-bearing string names. @complexity O(n) in the string's length. */
function addUrlKeys(text: string, out: Set<string>): void {
  for (const match of text.matchAll(MEDIA_URL_PATTERN)) {
    try {
      out.add(decodeURIComponent(match[1]!));
    } catch {
      out.add(match[1]!); // a malformed %-escape: keep the raw segment rather than throw
    }
  }
}

/** Adds every media URL key held in a mark's string attrs (a `link` mark's `href`, chiefly).
 *  @complexity O(m) in the marks' total attr length. */
function addMarkKeys(marks: unknown, out: Set<string>): void {
  if (!Array.isArray(marks)) return;
  for (const mark of marks) {
    if (!isPlainObject(mark) || !isPlainObject(mark.attrs)) continue;
    for (const value of Object.values(mark.attrs)) if (typeof value === "string") addUrlKeys(value, out);
  }
}

/** Every media key a free-text string names by a `/m/` or `/media/` URL (a text widget's body, a
 *  social link's `url`). @complexity O(n) in the string's length. */
export function collectMediaUrlKeys(text: string): ReadonlySet<string> {
  const keys = new Set<string>();
  addUrlKeys(text, keys);
  for (const ref of galleryMediaReferences({ config: { html: text } })) keys.add(ref.mediaId);
  return keys;
}

/** Shared authored-config reference scan, independent of layout/render validity. */
export function collectMediaConfigKeys({ config }: { config: unknown }, _optional: Record<string, never> = {}): ReadonlySet<string> {
  const keys = new Set(galleryMediaReferences({ config }).map(ref => ref.mediaId));
  if (isPlainObject(config) && typeof config.html === 'string') addUrlKeys(config.html, keys);
  return keys;
}

/** Walks a TipTap tree collecting every `image`/`media` node's `assetId` and legacy `src` key, plus
 *  any media URL in a mark's attrs. @complexity O(n) in the tree's size. */
function addDocKeys(root: unknown, out: Set<string>): void {
  walkDoc({
    root, visit: (node) => {
      addNodeKeys({ node, out });
      addMarkKeys(node.marks, out);
    }
  });
}

/** Saved widget media belongs to the same authored reference owner as inline content. Hosts
 * supply the already-batched saved configs; content overlays are applied before scanning. A host
 * without that read port reports an incomplete scan instead of treating gated media as public. */
export function collectPlacedWidgetMediaKeys(
  { bodyJson, bodyHtml, savedWidgets }: { bodyJson?: unknown; bodyHtml?: string | null; savedWidgets?: ReadonlyMap<string, Record<string, unknown>> },
  _optional: Record<string, never> = {},
): { keys: ReadonlySet<string>; readable: boolean } {
  const keys = new Set<string>();
  let readable = true;
  const collect = (key: string, content: unknown): void => {
    if (!savedWidgets) { readable = false; return; }
    const config = savedWidgets.get(key);
    if (!config) return; // Missing/trashed widgets do not render; there is no served asset to gate.
    const merged = isPlainObject(content) ? { ...config, ...content } : config;
    for (const ref of collectMediaConfigKeys({ config: activeWidgetConfig({ merged }) })) keys.add(ref);
  };
  walkDoc({
    root: bodyJson, visit: (node) => {
      if (node.type === 'widgetEmbed' && isPlainObject(node.attrs) && typeof node.attrs.widgetEntryId === 'string') collect(node.attrs.widgetEntryId, node.attrs.content);
    }
  });
  if (typeof bodyHtml === 'string') for (const marker of scanEmbedMarkers({ html: bodyHtml }).markers) {
    if (marker.type.toLowerCase() !== 'widget') continue;
    const target = embedMarkerTarget({ type: marker.type, config: marker.config });
    if (target && target.key !== 'none') collect(target.value, marker.config.content);
  }
  return { keys, readable };
}

/** @complexity O(n) over `html`'s length (one shared marker scan plus one URL scan). */
function addHtmlKeys(html: string, out: Set<string>): void {
  for (const ref of galleryMediaReferences({ config: { html } })) out.add(ref.mediaId);
  for (const marker of scanEmbedMarkers({ html: html }).markers) {
    for (const key of collectMediaConfigKeys({ config: marker.config })) out.add(key);
    addGalleryKeys({ marker, out });
    if (marker.type.toLowerCase() !== "media") continue;
    const target = embedMarkerTarget({ type: marker.type, config: marker.config });
    if (target !== undefined && target.key !== "none") out.add(target.value);
  }
  addUrlKeys(html, out);
}

/** `seoExtJson` is stored as a raw JSON string (`PostRecord.seoExtJson`'s own doc); an unparseable
 *  one contributes nothing. @complexity O(n) in the string's length for the parse. */
function addSeoKeys(raw: unknown, out: Set<string>): void {
  let seo: unknown = raw;
  if (typeof raw === "string") {
    try {
      seo = JSON.parse(raw);
    } catch {
      return;
    }
  }
  if (!isPlainObject(seo)) return;
  for (const field of SEO_IMAGE_FIELDS) {
    addSeoReference({ ref: seo[field], out });
  }
}

/**
 * Every media key (id or slug) one packed post/page state references, across `bodyJson`,
 * `bodyHtml` and `seoExtJson`. Pure; never throws on an unexpected shape — an unreadable field
 * simply contributes nothing, since this only ever ADDS media to a run and never gates one.
 *
 * @complexity O(n) in the total size of the three fields.
 */
export function collectReferencedMediaKeys(state: Readonly<Record<string, unknown>>): ReadonlySet<string> {
  const keys = new Set<string>();
  addDocKeys(state.bodyJson, keys);
  if (typeof state.bodyHtml === "string") addHtmlKeys(state.bodyHtml, keys);
  addSeoKeys(state.seoExtJson, keys);
  return keys;
}

function addNodeKeys({ node, out }: { node: Record<string, unknown>; out: Set<string> }, _optional: Record<string, never> = {}): void {
  if ((node.type === "image" || node.type === "media") && isPlainObject(node.attrs)) {
    if (typeof node.attrs.assetId === "string") out.add(node.attrs.assetId);
    else if (typeof node.attrs.src === "string") addUrlKeys(node.attrs.src, out);
  }
  if (node.type === 'widgetEmbed' && isPlainObject(node.attrs)) for (const key of collectMediaConfigKeys({ config: node.attrs.content })) out.add(key);
}

function walkDoc({ root, visit }: { root: unknown; visit: (node: Record<string, unknown>) => void }, _optional: Record<string, never> = {}): void {
  const stack: unknown[] = [root];
  while (stack.length) {
    const node = stack.pop();
    if (Array.isArray(node)) { for (const child of node) stack.push(child); continue; }
    if (!isPlainObject(node)) continue;
    visit(node);
    if (Array.isArray(node.content)) stack.push(node.content);
  }
}

function activeWidgetConfig({ merged }: { merged: Record<string, unknown> }, _optional: Record<string, never> = {}): Record<string, unknown> {
  const mode = merged.mode ?? (merged.items !== undefined ? 'media' : merged.html !== undefined ? 'html' : 'legacy');
  return mode === 'html' ? { html: merged.html } : mode === 'media' ? { items: merged.items } : merged;
}

function addGalleryKeys({ marker, out }: { marker: ReturnType<typeof scanEmbedMarkers>["markers"][number]; out: Set<string> }, _optional: Record<string, never> = {}): void {
  if (marker.type.toLowerCase() !== "gallery") return;
  for (const image of galleryMediaReferences({ config: marker.config })) out.add(image.mediaId);
  // Read decoded config values too: a browser save entity-encodes JSON quotes in HTML.
  if (!Array.isArray(marker.config.images)) return;
  for (const image of marker.config.images) {
    if (isPlainObject(image) && typeof image.src === "string") addUrlKeys(image.src, out);
  }
}

function addSeoReference({ ref, out }: { ref: unknown; out: Set<string> }, _optional: Record<string, never> = {}): void {

  if (typeof ref !== "string") return;
  if (ref.includes("/")) {
    addUrlKeys(ref, out); // an absolute URL, not a `"{assetId}:{transformName}"` ref
    return;
  }
  const assetId = ref.split(":")[0];
  if (assetId) out.add(assetId);
}

import { redactSecretShapes } from "../../contracts/core/secret-redaction.js";
import { bytesMatchSha256 } from "./blob-staging.js";
import { peerHostname, peerUrl } from "./peer-url.js";
import type { PublishContentExportEnvelope } from "./export-bundle.js";
import { PUBLISH_CONTENT_ARTIFACT_FORMAT_VERSION } from "./artifact-format.js";
import { EgressRefusedError, type HttpClientPort } from "#src/platform/http/index";
import type { ResolvedPeerCredential } from "./peers.js";
import type { PackedEntity } from "./type-registry.js";
import { nowIso, type Clock } from "@jini-ai/core/primitives";
import type { PublishHistoryStore, PublishTrigger } from "#src/features/deployments/static-publish/publish-history";

/**
 * @file Task 10 of the publish-content (Publish Content) feature —
 * `ADS-memory/reports/2026-09-18-publish-feature-implementation-plan.md` §1.6/§4 task 10.
 *
 * The outbound leg: this instance dialling ANOTHER Tovu's publish-content routes over the guarded
 * ADR-038 `HttpClientPort`. Two directions, one importer:
 *
 * - PUSH ({@link pushBundleToPeer} -> {@link confirmPeerImport} -> {@link executePeerImport}):
 *   builds a bundle here, uploads the blobs the peer is missing, stages it there, then drives the
 *   peer's OWN gated `plan`/`confirm`/`execute` ceremony. Every safety property (PLAN_STALE,
 *   single-redemption tokens, "an agent may never confirm", the restore point) is enforced on the
 *   DESTINATION, by the code that owns the destination's data — this driver only relays.
 * - PULL ({@link pullBundleFromPeer}): fetches the peer's export envelope and stages it HERE, so
 *   this instance's own already-built `/import/plan|confirm|execute` runs `planImport` against it.
 *   One importer, two directions — a pull adds no second classification path.
 *
 * ## Vendor neutrality (plan §0b — this file is the one place Task 10 could regress it)
 *
 * A peer is a URL plus a sealed key. Nothing here knows or asks what runs underneath: no app name,
 * no project id, no region, no platform API, and no reference to any single host's CLI or config
 * file. (Stated in the abstract deliberately: plan §0b's own guard is a grep for those literal
 * platform tokens across this directory, and a comment naming them to disclaim them would trip it.)
 * The private-network question is not answered with a single-host-shaped assumption either — it is
 * delegated whole to ADR-038's `EgressPolicy.denyPrivateAddresses` + `devHostAllowlist`, which
 * classify the RESOLVED address, so Railway's and Render's internal DNS names and an AWS VPC
 * address are handled by exactly the same code path with no per-platform branch.
 *
 * ## The credential
 *
 * The opened key exists only as the `Authorization` header of one in-flight request. It is never
 * logged, never placed in a URL (`HttpClientPort` rejects credentials-in-URL outright), never
 * returned in a result, and never interpolated into an error message — {@link toTransportError} is
 * the single funnel for request failures. Diagnostics use fixed local text and HTTP status, never
 * upstream messages or bodies that could echo the credential. `client.ts` additionally strips `Authorization` on any cross-origin redirect,
 * and this feature's policy sets `maxRedirects: 0` so there is no redirect hop at all.
 */

/** Machine-readable failure classes a peer call can produce. Distinct codes, because a route maps
 *  each to a different HTTP status and an operator acts on each differently. */
export type PeerTransportErrorCode =
  | "EGRESS_REFUSED"
  | "PEER_UNREACHABLE"
  | "PEER_REJECTED"
  | "PEER_RESPONSE_INVALID"
  /** The operator ticked "Overwrite on live" but the peer doesn't advertise `"overwrite-live"`. */
  | "PEER_CANNOT_OVERWRITE";

/** The single error type every failure in this module surfaces as. `message` is operator-facing:
 *  fixed local diagnostics omit upstream error text; the shared redactor also scrubs secret-shaped
 *  values from route/host context. */
export class PublishContentPeerTransportError extends Error {
  readonly code: PeerTransportErrorCode;
  /** The peer's HTTP status, when there was one. Absent for a refusal or an unreachable host. */
  readonly peerStatus?: number;

  constructor(message: string, code: PeerTransportErrorCode, options: { peerStatus?: number } = {}) {
    super(redactSecretShapes({ text: message }).text);
    this.name = "PublishContentPeerTransportError";
    this.code = code;
    if (options.peerStatus !== undefined) this.peerStatus = options.peerStatus;
  }
}

// A peer's error text can be useful, but another process may echo our Authorization header.
// Keep diagnostics local and fixed: even a bounded excerpt or shape redaction can leak an opaque key.

/**
 * Turns an `EgressRefusedError` into the operator diagnosis this task's brief requires: a message
 * that NAMES `devHostAllowlist` and the exact hostname to add, rather than reading as a generic
 * network error.
 *
 * Why every refusal reaching here is a private-address refusal, by construction — this is the
 * reasoning that lets this function state the cause instead of pattern-matching the message text
 * (which would be fragile and would silently degrade if the wording changed):
 * `client.ts`'s `assertAllowedTarget` refuses exactly three things — a scheme outside
 * `allowedSchemes`, credentials embedded in the URL, and (via `assertNoPrivateAddress`) a
 * non-public resolved address. `normalizePeerBaseUrl` has already refused a non-https URL and a
 * URL carrying userinfo before any peer row could be written, and the peer policy sets
 * `maxRedirects: 0`, so no redirect hop can introduce either. Only the third refusal is reachable.
 *
 * The underlying error's own `callerSafeMessage` is used, never `message`: `message` names the
 * resolved ADDRESS, and echoing that to an operator-facing surface lets a caller who can name any
 * host map internal DNS one request at a time (`errors.ts`'s own reasoning).
 *
 * @complexity O(n) in the base URL length.
 */
export function describePeerEgressRefusal(err: EgressRefusedError, baseUrl: string): PublishContentPeerTransportError {
  const hostname = peerHostname(baseUrl);
  return new PublishContentPeerTransportError(
    `${err.callerSafeMessage}. '${hostname}' resolves to a private address, so this peer is unreachable ` +
      `until it is added to this deployment's EgressPolicy devHostAllowlist ` +
      `(TOVU_PUBLISH_CONTENT_DEV_HOSTS, a comma-separated list of hostnames — add '${hostname}'). ` +
      `This is a deliberate SSRF guard, not a network fault.`,
    "EGRESS_REFUSED"
  );
}

/**
 * The single funnel every peer-call failure passes through.
 *
 * @complexity O(n) in the base URL and resulting diagnostic length, including shared redaction.
 */
function toTransportError({ err, baseUrl }: { err: unknown; baseUrl: string }, _options = {}): PublishContentPeerTransportError {
  if (err instanceof PublishContentPeerTransportError) return err;
  if (err instanceof EgressRefusedError) return describePeerEgressRefusal(err, baseUrl);
  return new PublishContentPeerTransportError(
    `the peer at '${peerHostname(baseUrl)}' could not be reached.${peerNetworkReason({ err })}`,
    "PEER_UNREACHABLE"
  );
}

const PEER_NETWORK_REASONS = new Map<string, string>([
  ["ECONNREFUSED", " The peer refused the connection; check that it is running and reachable."],
  ...["ENOTFOUND", "EAI_AGAIN"].map(code => [code, " The peer's hostname could not be resolved; check its address and DNS."] as const),
  ...["ETIMEDOUT", "UND_ERR_CONNECT_TIMEOUT"].map(code => [code, " The connection timed out; check the peer and try again."] as const),
  ...["CERT_HAS_EXPIRED", "CERT_NOT_YET_VALID", "DEPTH_ZERO_SELF_SIGNED_CERT", "SELF_SIGNED_CERT_IN_CHAIN",
    "UNABLE_TO_VERIFY_LEAF_SIGNATURE", "ERR_TLS_CERT_ALTNAME_INVALID"]
    .map(code => [code, " The peer's TLS certificate could not be verified; repair its certificate before trying again."] as const),
]);

/** Classify local network codes without exposing messages or credential-bearing causes.
 * @complexity O(1), inspecting at most the error and its immediate cause. */
function peerNetworkReason({ err }: { err: unknown }, _options = {}): string {
  if (typeof err !== "object" || err === null) return "";
  const cause = "cause" in err ? err.cause : undefined;
  const code = "code" in err ? err.code : peerCauseCode({ cause });
  return typeof code === "string" ? PEER_NETWORK_REASONS.get(code) ?? "" : "";
}

/** Inspect only the immediate cause; messages and deeper causes never supply diagnostics. */
function peerCauseCode({ cause }: { cause: unknown }, _options: Record<string, never> = {}): unknown {
  return typeof cause === "object" && cause !== null && "code" in cause ? cause.code : undefined;
}

const PEER_REFUSAL_REASONS = new Map<string, string>([
  ["WORKSPACE_NOT_FOUND", "The destination workspace was not found; check the peer's workspace setting."],
  ["PAYLOAD_TOO_LARGE", "The transfer exceeds the peer's size limit; publish a smaller selection."],
  ["PLAN_STALE", "The destination changed since the plan was checked; check what would change again."],
  ["TOKEN_EXPIRED", "The confirmation expired; check and confirm the publish again."],
  ["TOKEN_ALREADY_REDEEMED", "This confirmation was already used; check the publish result before trying again."],
  ["RESTORE_POINT_UNAVAILABLE", "The peer could not create a restore point; repair its backup storage before publishing."],
  ["BUNDLE_NOT_FOUND", "The staged bundle was not found on the peer; send the selection again."],
]);

/** Translate only known peer codes/statuses into local operator guidance, never upstream prose.
 * Legacy workspace refusals have no code, so only their exact fixed sentinel is recognised.
 * @complexity O(body bytes), one JSON parse and constant-time map lookups. */
function peerRefusalReason({ status, bodyText }: { status: number; bodyText: string }, _options = {}): string | undefined {
  try {
    const body: unknown = JSON.parse(bodyText);
    const reason = peerBodyRefusalReason({ status, body });
    if (reason) return reason;
  } catch {
    // Proxies may return HTML or an empty body; the HTTP status still provides safe guidance.
  }
  if (status === 413) return PEER_REFUSAL_REASONS.get("PAYLOAD_TOO_LARGE");
  if (status === 409) return "The peer reported a conflict; check what would change again before retrying.";
  return undefined;
}

/** Prefer a recognised code to the exact legacy sentinel; upstream prose is never returned. */
function peerBodyRefusalReason(
  { status, body }: { status: number; body: unknown },
  _options: Record<string, never> = {}
): string | undefined {
  if (typeof body !== "object" || body === null) return undefined;
  if ("code" in body && typeof body.code === "string") {
    const reason = PEER_REFUSAL_REASONS.get(body.code);
    if (reason) return reason;
  }
  if (status === 404 && "error" in body && body.error === "workspace was not found") {
    return PEER_REFUSAL_REASONS.get("WORKSPACE_NOT_FOUND");
  }
  return undefined;
}

/** Per-request timeout for a peer call. A bundle POST is the slow one; 60 s is generous for an API
 *  call and still bounded, so a wedged peer cannot hold an admin request open indefinitely. */
export const PEER_REQUEST_TIMEOUT_MS = 60_000;

/** The narrow blob-read seam the push driver needs — `BlobStorePort`'s read half only, so this
 *  module can never write a blob.
 *
 *  `sha256` joined `storageKey` on both methods (`publish-files-plan-2026-09-24.md` §3, S-F3): a
 *  plain `BlobStorePort` only ever needs `storageKey` and structurally still satisfies this widened
 *  shape (TypeScript checks method-shorthand interface members bivariantly, so a `{storageKey}`-only
 *  implementation is assignable here without change) — `composite-blob-source.ts`'s own
 *  `createCompositePeerBlobSource` is the one implementation that actually reads `sha256`, to fall
 *  back to a `FileBlobIndexPort` lookup and re-verify the bytes it finds there hash to the value the
 *  caller is asking for. Both callers below already have the plain sha in scope when they call these
 *  methods, so passing it through costs nothing. */
export interface PeerBlobSource {
  exists(input: { sha256: string; storageKey: string }): Promise<boolean>;
  get(input: { sha256: string; storageKey: string }): Promise<Uint8Array>;
}

export interface PeerCallDeps {
  readonly httpClient: HttpClientPort;
  readonly credential: ResolvedPeerCredential;
  /** Local source scope, never the peer's remote workspace. Optional for transport-only consumers. */
  readonly publishHistory?: { store: PublishHistoryStore; workspaceId: string; clock: Clock; triggeredBy?: PublishTrigger };
}

/**
 * One authenticated call to a peer route; share uploads reuse this credential/egress owner.
 *
 * @param path - An absolute route path on the peer, already carrying the peer's OWN workspace id.
 * @returns The parsed JSON body.
 * @throws {PublishContentPeerTransportError} for every failure class — see {@link toTransportError}.
 * @complexity O(1) plus one network round trip and one JSON parse of the response.
 */
export async function callPeer(
  deps: PeerCallDeps,
  request: { method: "GET" | "POST" | "PUT" | "DELETE"; path: string; body?: unknown; archive?: Uint8Array; signal?: AbortSignal }
): Promise<unknown> {
  const { baseUrl, apiKey } = deps.credential;
  let response;
  try {
    const payload = peerRequestPayload({ request });
    response = await deps.httpClient.send({
      method: request.method,
      url: peerUrl(baseUrl, request.path),
      headers: {
        // The ONE place the resolved credential is used, and it is deliberately incurious about
        // which kind it got. Two reach here (`features/publish-content/destination-credential.ts`):
        // an explicitly-configured peer's API key, which `dev-auth.ts`'s
        // `API_KEY_AUTHORIZATION_PATTERN` accepts as `Bearer <raw-key>` and whose grants come from
        // its own issuance snapshot (plan §1.2); and a connected destination's short-lived
        // publishing session token, which the destination's `requirePublishTrust` gate recognises
        // ahead of the admin session gate. Both are `Bearer <opaque>` on the wire, so there is
        // still no transport-specific auth mechanism here to get wrong.
        authorization: `Bearer ${apiKey}`,
        ...payload.headers,
      },
      ...payload.content,
      signal: request.signal,
      timeoutMs: PEER_REQUEST_TIMEOUT_MS,
      // Publishing can carry a 96 MB bundle. Keep the feature's intended 60 s
      // total budget explicit; the egress policy's 30 s limit is socket inactivity.
      totalDeadlineMs: PEER_REQUEST_TIMEOUT_MS,
    });
  } catch (err) {
    throw toTransportError({ err, baseUrl });
  }

  if (response.status < 200 || response.status >= 300) {
    const reason = peerRefusalReason({ status: response.status, bodyText: response.bodyText });
    throw new PublishContentPeerTransportError(
      isCredentialKindRefusal(response.status, response.bodyText)
        ? credentialKindRefusalMessage(baseUrl)
        : `the peer refused ${request.method} ${request.path} with HTTP ${response.status}${reason ? `. ${reason}` : ""}`,
      "PEER_REJECTED",
      { peerStatus: response.status }
    );
  }

  if (response.status === 204) return undefined;
  try {
    return JSON.parse(response.bodyText);
  } catch {
    throw new PublishContentPeerTransportError(
      `the peer's response to ${request.method} ${request.path} was not JSON — is '${peerHostname(baseUrl)}' a Tovu instance?`,
      "PEER_RESPONSE_INVALID"
    );
  }
}

/**
 * Whether a peer refusal is live's 403 `credential_kind_not_permitted` — on the publish-content
 * routes, only `/import/plan` and `/import/execute` send it, for "Overwrite on live" ticks that
 * arrived under a saved API key (`routes/publish-content/import.ts`'s `mayOverwrite`). A connected
 * computer's publishing session token is never refused this way.
 * @complexity O(n) in the body length (one JSON parse).
 */
function isCredentialKindRefusal(status: number, bodyText: string): boolean {
  if (status !== 403) return false;
  try {
    const body = JSON.parse(bodyText) as { details?: { reason?: unknown } } | null;
    return body?.details?.reason === "credential_kind_not_permitted";
  } catch {
    return false;
  }
}

/** The operator's sentence for {@link isCredentialKindRefusal}, in place of the raw JSON body.
 *  @complexity O(1). */
function credentialKindRefusalMessage(baseUrl: string): string {
  return (
    `${baseUrl} only accepts "Overwrite on live" from a computer connected to it, not from a saved API key. ` +
    `Connect this computer to ${baseUrl}, then publish again.`
  );
}

/** Builds a peer route path under the peer's OWN workspace id. Never this instance's — a peer's
 *  workspace id is stored on the row precisely because the two are unrelated identifiers.
 *  @complexity O(1). */
function peerRoute(credential: ResolvedPeerCredential, suffix: string): string {
  return `/api/admin/v1/workspaces/${encodeURIComponent(credential.remoteWorkspaceId)}/publish-content${suffix}`;
}

/** @complexity O(1). */
function requireObject(value: unknown, what: string, baseUrl: string): Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new PublishContentPeerTransportError(
      `the peer's ${what} response was not an object — is '${peerHostname(baseUrl)}' a Tovu instance?`,
      "PEER_RESPONSE_INVALID"
    );
  }
  return value as Record<string, unknown>;
}

/** One entity type this bundle held that the peer's own S-F1 capability probe said it cannot
 *  accept — see {@link PushBundleResult.notSupportedByLive}. */
export interface NotSupportedByLiveEntry {
  readonly entityType: string;
  readonly count: number;
}

export interface PushBundleResult {
  /** The bundle id the PEER minted for the staged bundle — required again at execute. */
  readonly bundleId: string;
  /** Blob sha256s actually uploaded on this push (the peer already had the rest). */
  readonly blobsUploaded: readonly string[];
  /** Blob sha256s the peer was missing and this instance does not hold either — every entity that
   *  requires one will be `blocked` by the peer's own planner, which is the fail-closed outcome. */
  readonly blobsUnavailable: readonly string[];
  /** The peer's gated plan, verbatim — `{domain, planId, planHash, details}`. `details` is the
   *  `PublishContentReport` the operator's confirm decision is made against. */
  readonly plan: Record<string, unknown>;
  /** Entity types this bundle held that {@link pushBundleToPeer}'s own capability probe found the
   *  peer cannot accept (an older Tovu, or a grant that has not opted into that type yet), grouped
   *  with a count. Their entities were removed from the bundle BEFORE anything was staged or
   *  uploaded — never sent, never counted in {@link blobsUploaded}/{@link blobsUnavailable}, and
   *  never appearing as a row in `plan`. Empty when the peer accepted every type, or when the
   *  bundle carried no entities at all (the probe is skipped entirely in that case — see
   *  {@link pushBundleToPeer}). */
  readonly notSupportedByLive: readonly NotSupportedByLiveEntry[];
  /** publish-overwrite-live-plan §4/S7 — whether the peer's own capabilities probe reported the
   *  `"overwrite-live"` feature (`capabilities.ts`'s S6 addition). `false` for an older peer whose
   *  `/capabilities` response carries no `features` array, and `false` also when the probe was
   *  skipped because the bundle carried no entities (see {@link notSupportedByLive}) — there is
   *  nothing to overwrite in that case anyway. The admin dialog and the chat tool (S8/S9) read this
   *  to decide whether to offer any "Overwrite on live" tick at all. Non-empty
   *  `overwriteEntityKeys` sent to a peer without the feature are refused with
   *  `PEER_CANNOT_OVERWRITE` before anything is staged: that peer would silently ignore them. */
  readonly liveCanOverwrite: boolean;
}

/** The fixed set every peer predating S-F1's `/capabilities` route accepts — `bundle-create.ts`'s
 *  original `deploy/publish-trust.json` grant, before `theme-files`/`redirect`/anything newer ever
 *  existed. Used only when the probe below reads an ordinary 404: a peer that old never claimed to
 *  support more, so the absence of the route is read as this fixed answer, not as a failure. */
const LEGACY_PEER_ENTITY_TYPES: readonly string[] = ["post", "page", "media"];

/** The probe answers an older peer gives: 404 to an API key (no such route), 401 to a publishing
 *  credential (route not on its allowlist). See {@link probePeerCapabilities}. */
const LEGACY_PROBE_STATUSES: ReadonlySet<number> = new Set([401, 404]);

/**
 * Probes the peer's own `GET .../capabilities` route (`routes/publish-content/capabilities.ts`) for
 * what it currently accepts.
 *
 * A 404 — the shape Express gives an unmatched route, which is exactly what a peer built before
 * this route existed returns to an API key — is read as {@link LEGACY_PEER_ENTITY_TYPES}, not as an
 * error: that peer never claimed to accept anything else. A 401 is read the same way: an older
 * peer's publishing-credential middleware (`publish-trust-auth.ts`) answers 401 for any route its
 * own `PUBLISH_TRUST_ROUTES` predates, and this route is one. That fallback cannot hide a genuinely
 * refused credential — the very next leg of the push is on that peer's allowlist and fails with
 * its own 401. Every OTHER failure (egress refusal, an unreachable host, any other non-2xx status,
 * a malformed body) propagates unchanged, the same fail-closed posture every other call in this
 * module already takes.
 *
 * @complexity O(1) plus one network round trip.
 */
/** What {@link probePeerCapabilities} learned about a peer: the entity types it currently accepts,
 *  plus the feature flags it advertises (publish-overwrite-live-plan §4/S7's `"overwrite-live"` is
 *  the first one). A peer that predates `features` entirely — the {@link LEGACY_PROBE_STATUSES}
 *  case, or an S-F1-only peer whose response has `entityTypes` but no `features` array — reports an
 *  empty features list: fail-closed, the same posture `entityTypes` itself already takes for that
 *  peer. */
interface PeerCapabilities {
  readonly entityTypes: readonly string[];
  readonly features: readonly string[];
}

/**
 * Refuses a non-empty set of "Overwrite on live" ticks for a peer that doesn't advertise
 * `"overwrite-live"`. Such a peer ignores the body field it doesn't know, so forwarding the ticks
 * would plan and execute WITHOUT the overwrite the operator asked for, and say nothing.
 *
 * @complexity O(1).
 */
function refuseOverwriteOnOlderPeer(credential: ResolvedPeerCredential, capabilities: PeerCapabilities): void {
  if (capabilities.features.includes("overwrite-live")) return;
  throw new PublishContentPeerTransportError(
    `${credential.baseUrl} is on an older Tovu, so it can't overwrite these yet. Update ${credential.baseUrl}, then publish again.`,
    "PEER_CANNOT_OVERWRITE"
  );
}

async function probePeerCapabilities(deps: PeerCallDeps): Promise<PeerCapabilities> {
  const { credential } = deps;
  let probed: Record<string, unknown>;
  try {
    probed = requireObject(
      await callPeer(deps, { method: "GET", path: peerRoute(credential, "/capabilities") }),
      "capabilities",
      credential.baseUrl
    );
  } catch (err) {
    if (err instanceof PublishContentPeerTransportError && LEGACY_PROBE_STATUSES.has(err.peerStatus ?? 0)) {
      return { entityTypes: LEGACY_PEER_ENTITY_TYPES, features: [] };
    }
    throw err;
  }

  if (!Array.isArray(probed.entityTypes) || !probed.entityTypes.every((entityType) => typeof entityType === "string")) {
    throw new PublishContentPeerTransportError(
      `the peer's capabilities response carried no 'entityTypes' array — is '${peerHostname(credential.baseUrl)}' a Tovu instance?`,
      "PEER_RESPONSE_INVALID"
    );
  }
  const features =
    Array.isArray(probed.features) && probed.features.every((feature) => typeof feature === "string")
      ? (probed.features as string[])
      : [];
  return { entityTypes: probed.entityTypes as string[], features };
}

/**
 * Narrows a bundle to the entity types a peer just reported it accepts, so the whole-bundle refusal
 * `bundle-create.ts`'s own grant check produces for ONE unsupported type never happens at all.
 *
 * The excluded entities are counted and grouped by type rather than silently dropped — that grouping
 * is exactly {@link PushBundleResult.notSupportedByLive}, which the caller surfaces to a person.
 * `blobManifest` is recomputed from
 * the SURVIVING entities only, mirroring `export-bundle.ts`'s `selectBundleEntities`: a push must
 * never upload bytes that belong solely to an entity it is about to leave behind.
 *
 * @complexity O(e) time and space in the bundle's entity count.
 */
function trimBundleToCapabilities(
  bundle: PublishContentExportEnvelope,
  acceptedEntityTypes: readonly string[]
): { bundle: PublishContentExportEnvelope; notSupportedByLive: readonly NotSupportedByLiveEntry[] } {
  const accepted = new Set(acceptedEntityTypes);
  const kept: PackedEntity[] = [];
  const excludedCounts = new Map<string, number>();
  for (const entity of bundle.entities) {
    if (accepted.has(entity.entityType)) kept.push(entity);
    else excludedCounts.set(entity.entityType, (excludedCounts.get(entity.entityType) ?? 0) + 1);
  }
  if (excludedCounts.size === 0) return { bundle, notSupportedByLive: [] };

  const requiredBlobs = new Set<string>();
  for (const entity of kept) for (const sha of entity.requiredBlobs) requiredBlobs.add(sha);

  return {
    bundle: { ...bundle, entities: kept, blobManifest: Array.from(requiredBlobs) },
    notSupportedByLive: Array.from(excludedCounts, ([entityType, count]) => ({ entityType, count })),
  };
}

/**
 * Push step 1: stage a bundle on the peer and obtain its gated plan.
 *
 * Order is load-bearing: blobs FIRST, then the bundle, then the plan. The peer's `planImport` marks
 * an entity `blocked` when a required blob is absent there, so uploading after planning would
 * produce a plan that is wrong the moment it is acted on.
 *
 * @param required.bundle - Built by `buildExportBundle` from THIS instance's registered types.
 * @param required.overwriteEntityKeys - publish-overwrite-live-plan §4/S7 — the operator's
 * "Overwrite on live" ticks, forwarded verbatim to the peer's `/import/plan` (undefined stays
 * undefined on the wire, never becomes `[]` or `null`; see the peer's own `readOverwriteEntityKeys`
 * doc on why absent must mean "force nothing" rather than an empty, real answer).
 * @param required.blobSource - Read-only access to this instance's blob store.
 * @throws {PublishContentPeerTransportError} on any peer failure.
 * @complexity O(b + 1) network round trips for `b` missing blobs, plus one probe, one stage and one
 * plan. Memory is O(selected manifest size + size of the largest single blob) — hashes are checked
 * as a batch before uploading; blob bytes are uploaded one at a time, never collected.
 */
export async function pushBundleToPeer(
  deps: PeerCallDeps & { blobSource: PeerBlobSource; computeStorageKey: (sha256: string) => string },
  required: { bundle: PublishContentExportEnvelope; overwriteEntityKeys?: readonly string[] }
): Promise<PushBundleResult> {
  const { credential } = deps;

  // S-F1: probe, then trim, BEFORE any blob is probed or uploaded — an excluded entity's blobs must
  // never be sent either. Skipped for an empty bundle: trimming nothing needs no round trip, the
  // same short-circuit the blob probe below already takes for an empty `blobManifest`. An empty
  // bundle also leaves `liveCanOverwrite` at its fail-closed `false` default (S7) — there is nothing
  // in it to overwrite.
  let bundle = required.bundle;
  let notSupportedByLive: readonly NotSupportedByLiveEntry[] = [];
  let liveCanOverwrite = false;
  const wantsOverwrite = (required.overwriteEntityKeys?.length ?? 0) > 0;
  if (bundle.entities.length > 0 || wantsOverwrite) {
    const capabilities = await probePeerCapabilities(deps);
    liveCanOverwrite = capabilities.features.includes("overwrite-live");
    if (wantsOverwrite) refuseOverwriteOnOlderPeer(credential, capabilities);
    const trimmed = trimBundleToCapabilities(bundle, capabilities.entityTypes);
    bundle = trimmed.bundle;
    notSupportedByLive = trimmed.notSupportedByLive;
  }

  const { blobsUploaded, blobsUnavailable } = await uploadMissingPeerBlobs(deps, { bundle });

  const staged = requireObject(
    await callPeer(deps, {
      method: "POST",
      path: peerRoute(credential, "/bundles"),
      body: {
        artifactFormatVersion: bundle.artifactFormatVersion,
        hashVersion: bundle.hashVersion,
        sourceLabel: bundle.sourceLabel,
        entities: bundle.entities,
        blobManifest: bundle.blobManifest,
      },
    }),
    "bundle staging",
    credential.baseUrl
  );
  const bundleId = staged.bundleId;
  if (typeof bundleId !== "string") {
    throw new PublishContentPeerTransportError(
      `the peer staged the bundle but returned no 'bundleId'`,
      "PEER_RESPONSE_INVALID"
    );
  }

  const plan = requireObject(
    await callPeer(deps, {
      method: "POST",
      path: peerRoute(credential, "/import/plan"),
      // publish-overwrite-live-plan §4/S7 — `undefined` here reaches the peer's `/import/plan` as an
      // absent field, which its `readOverwriteEntityKeys` reads as "force nothing", the same
      // absent-means-unforced reading `selectedEntityKeys` already relies on for this same call.
      body:
        required.overwriteEntityKeys === undefined
          ? { bundleId }
          : { bundleId, overwriteEntityKeys: required.overwriteEntityKeys },
    }),
    "import plan",
    credential.baseUrl
  );

  return { bundleId, blobsUploaded, blobsUnavailable, plan, notSupportedByLive, liveCanOverwrite };
}

/**
 * Push step 2: confirm the peer's plan and obtain its single-use confirmation token.
 *
 * The "an agent principal may never confirm" guard lives in `gated-mutations/gateway.ts`'s
 * `confirm()` (`AGENT_CANNOT_CONFIRM`) and is enforced on the PEER, against the peer's own view of
 * the calling principal. This driver cannot weaken it: it has no way to assert a principal kind
 * over the wire — the peer derives that itself from the API key it authenticated.
 *
 * @complexity O(1) plus one network round trip.
 */
export async function confirmPeerImport(
  deps: PeerCallDeps,
  required: { planId: string; planHash: string }
): Promise<{ confirmationToken: string }> {
  const confirmed = requireObject(
    await callPeer(deps, {
      method: "POST",
      path: peerRoute(deps.credential, "/import/confirm"),
      body: { planId: required.planId, planHash: required.planHash },
    }),
    "import confirm",
    deps.credential.baseUrl
  );
  const confirmationToken = confirmed.confirmationToken;
  if (typeof confirmationToken !== "string") {
    throw new PublishContentPeerTransportError(
      `the peer confirmed the plan but returned no 'confirmationToken'`,
      "PEER_RESPONSE_INVALID"
    );
  }
  return { confirmationToken };
}

/**
 * Push step 3: redeem the token and run the peer's apply.
 *
 * @returns The peer's execute body verbatim (`{restorePointId, runId, changeSetIds, ...}`) — this driver
 * never reshapes a destination's own report.
 * Records completed outbound applies in the injected local ledger; ledger failures only warn.
 * @complexity O(1) plus one network round trip and one ledger append (the peer's apply loop dominates).
 */
export async function executePeerImport(
  deps: PeerCallDeps,
  required: { bundleId: string; confirmationToken: string; overwriteEntityKeys?: readonly string[] }
): Promise<Record<string, unknown>> {
  // Re-probed rather than trusted from the plan step: execute is a separate request, and the peer
  // may have been redeployed in between.
  if ((required.overwriteEntityKeys?.length ?? 0) > 0) {
    refuseOverwriteOnOlderPeer(deps.credential, await probePeerCapabilities(deps));
  }
  const result = requireObject(
    await callPeer(deps, {
      method: "POST",
      path: peerRoute(deps.credential, "/import/execute"),
      // publish-overwrite-live-plan §4/S7 — the same forced set confirmed at plan time. A DIFFERENT
      // set here re-derives a different report hash on the peer, and its own PLAN_STALE check
      // refuses it (§4) — no staleness code is needed on this side of the wire either.
      body:
        required.overwriteEntityKeys === undefined
          ? { bundleId: required.bundleId, confirmationToken: required.confirmationToken }
          : {
              bundleId: required.bundleId,
              confirmationToken: required.confirmationToken,
              overwriteEntityKeys: required.overwriteEntityKeys,
            },
    }),
    "import execute",
    deps.credential.baseUrl
  );
  // HTTP failures already throw. A completed apply may contain conflicts/partial writes; both
  // outcomes remember the destination, but a body explicitly reporting failure never does.
  if (deps.publishHistory && peerApplyCompleted({ result })) {
    try {
      await deps.publishHistory.store.recordSuccess({ workspaceId: deps.publishHistory.workspaceId, entry: {
        kind: "tovu-peer", target: deps.credential.id, projectName: "", url: deps.credential.baseUrl,
        configFields: { label: deps.credential.label }, reachable: true, status: "applied",
        publishedAt: nowIso({ clock: deps.publishHistory.clock }), triggeredBy: deps.publishHistory.triggeredBy ?? "admin_ui",
      } });
    } catch {
      // The remote apply already succeeded; bookkeeping must never invite a duplicate retry.
      // Fixed diagnostics exclude credentials, remote bodies and database error parameters.
      console.warn("[publish-content] destination history write failed after remote apply");
    }
  }
  return result;
}

/** A completed (possibly partial) apply names a run; refusals never establish a past destination. */
function peerApplyCompleted({ result }: { result: Record<string, unknown> }): boolean {
  if (typeof result.runId !== "string" || result.ok === false) return false;
  const report = result.report;
  return !(typeof report === "object" && report !== null && "refused" in report && report.refused === true);
}

/**
 * PULL: fetch the peer's export envelope so THIS instance can stage and plan it locally.
 *
 * Deliberately stops at the envelope. Staging and planning are the caller's job, and the caller
 * uses this instance's already-built `stageBundle` + gated `/import/plan` — the same importer a
 * pushed bundle goes through. Nothing in the pull path re-implements classification.
 *
 * This function transfers no blob BYTES — deliberately, and it is no longer a gap: the bytes are
 * {@link pullBlobsFromPeer}'s job, called by the pull route with the `blobManifest` this envelope
 * carries. The split is the same one the push side uses (blobs are their own leg, not a field of
 * the bundle call), and it keeps the envelope fetch a single bounded response.
 *
 * Until 2026-09-19 there was no such function, because the peer exposed `PUT .../blobs/:sha` but no
 * GET — a pulled media entity therefore always ended `blocked` by `planImport`. `media` IS a
 * registered publish-content type (`publish-content-manifest.ts` registers
 * `contributeMediaPublish()`; commits `72e4992c7`/`a9b265ce1`), so that was live, not theoretical:
 * the difference between an empty `blobManifest` and a pull that blocks every image. `blob-get.ts`
 * is the route that closed it.
 *
 * @complexity O(1) network round trip; O(e) memory in the peer's corpus size.
 */
export async function pullBundleFromPeer(deps: PeerCallDeps): Promise<PublishContentExportEnvelope> {
  const body = requireObject(
    await callPeer(deps, { method: "GET", path: peerRoute(deps.credential, "/export") }),
    "export",
    deps.credential.baseUrl
  );

  if (
    typeof body.artifactFormatVersion !== "number" ||
    typeof body.hashVersion !== "number" ||
    !Array.isArray(body.entities) ||
    !Array.isArray(body.blobManifest)
  ) {
    throw new PublishContentPeerTransportError(
      `the peer's export was not a publish-content bundle (expected artifactFormatVersion, hashVersion, entities and blobManifest)`,
      "PEER_RESPONSE_INVALID"
    );
  }
  if (body.artifactFormatVersion !== PUBLISH_CONTENT_ARTIFACT_FORMAT_VERSION) {
    throw new PublishContentPeerTransportError(
      `the peer exported artifact format version ${String(body.artifactFormatVersion)}, but this instance supports ` +
        `${PUBLISH_CONTENT_ARTIFACT_FORMAT_VERSION}`,
      "PEER_RESPONSE_INVALID"
    );
  }

  return {
    artifactFormatVersion: body.artifactFormatVersion,
    hashVersion: body.hashVersion,
    sourceLabel: typeof body.sourceLabel === "string" ? body.sourceLabel : deps.credential.label,
    entities: body.entities as PublishContentExportEnvelope["entities"],
    blobManifest: (body.blobManifest as unknown[]).filter((sha): sha is string => typeof sha === "string"),
    // `GET .../export` (the streaming route, `routes/publish-content/export.ts`) does not serialize
    // `skipped` today — only `buildExportBundle` (the push driver) collects it. A pull therefore
    // never surfaces a source-side refusal; out of scope here (this file's own header: the pull path
    // stages an envelope and defers all classification to this instance's own `planImport`, which has
    // no `skipped` concept yet either). Defaulting to empty is a display gap, never a safety one.
    skipped: [],
  };
}

/** The narrow blob-WRITE seam the pull driver needs — `BlobStorePort`'s presence check plus its
 *  create-only write, and nothing else. No `put`, no `remove`: this module can never overwrite or
 *  delete a blob, only add one that is absent. */
export interface PeerBlobSink {
  exists(input: { storageKey: string }): Promise<boolean>;
  putIfAbsent(input: {
    workspaceId: string;
    sha256: string;
    bytes: Uint8Array;
  }): Promise<{ storageKey: string; written: boolean }>;
}

/**
 * How many blobs ONE pull will fetch from a peer. A resource bound, not a product limit: the
 * manifest is peer-controlled, and without a ceiling a single pull could hold an admin request open
 * for an unbounded number of round trips. Set to the same value as
 * `PUBLISH_CONTENT_BLOB_PROBE_MAX_SHAS` (the push direction's own cap on the same quantity) so the
 * two directions bound the same thing identically.
 *
 * Exceeding it is not an error and loses nothing: the remainder is reported as
 * `deferredOverCap`, whatever entity needed those blobs is `blocked` by this instance's own
 * `planImport` (the established fail-closed outcome), and a SECOND pull picks them up — the blobs
 * already fetched are skipped by the `exists()` short-circuit, so progress is monotonic.
 */
export const PUBLISH_CONTENT_PULL_MAX_BLOBS = 2000;

/** What one pull's blob leg did, per sha. Four disjoint lists rather than a count, because an
 *  operator acts differently on each: nothing to do for `alreadyPresent`, "the source no longer has
 *  these" for `unavailable`, and "pull again" for `deferredOverCap`. */
export interface PullBlobsResult {
  /** Fetched from the peer, verified against the requested sha, and written to this instance. */
  readonly downloaded: readonly string[];
  /** Already in this instance's blob store — no network call was made for these. */
  readonly alreadyPresent: readonly string[];
  /** The peer answered 404: it no longer holds those bytes. Reported, never thrown — the entity
   *  that requires one is `blocked` by `planImport`, which is a fail-closed plan, not a partial
   *  write. Mirrors `PushBundleResult.blobsUnavailable` on the other direction. */
  readonly unavailable: readonly string[];
  /** Beyond {@link PUBLISH_CONTENT_PULL_MAX_BLOBS} for this request. Fetch them with another pull. */
  readonly deferredOverCap: readonly string[];
}

/**
 * PULL step 2: fetch the blob bytes a pulled envelope requires and store them HERE, so the
 * entities that need them plan as applicable instead of `blocked`.
 *
 * ## The security property this function holds
 *
 * A peer's bytes are UNTRUSTED. `BlobStorePort.putIfAbsent` does not verify that bytes hash to the
 * sha256 it is given — it derives the storage key from that string and writes whatever it was
 * handed (`blob-staging.ts`'s header traces this through both adapters). Since the sha IS the
 * identity throughout this feature, storing unverified bytes would poison content-addressed
 * storage: every later "do you have X?" would answer yes for bytes that are not X, and a `probe`
 * from a third instance would then skip re-uploading the real ones. So every response is hashed
 * with {@link bytesMatchSha256} BEFORE `putIfAbsent`, and a mismatch throws rather than being
 * skipped — a peer serving wrong bytes for a requested hash is corrupt or hostile, and neither is
 * something to continue a pull through. Nothing is written on that path.
 *
 * A 404 is the one peer answer that is NOT an error (see `unavailable` above); every other non-2xx
 * propagates from {@link callPeer} unchanged.
 *
 * @param deps.blobSink - This instance's blob store, write half.
 * @param deps.workspaceId - THIS instance's workspace id. Never the peer's: the bytes are being
 * stored locally, and `putIfAbsent` derives the local storage key from it.
 * @param deps.computeStorageKey - Local storage key for a sha, used for the `exists()` short-circuit.
 * @param deps.maxBlobs - Test seam / operator override for {@link PUBLISH_CONTENT_PULL_MAX_BLOBS}.
 * @returns The four disjoint sha lists described by {@link PullBlobsResult}.
 * @throws {PublishContentPeerTransportError} `PEER_RESPONSE_INVALID` when a peer's bytes do not hash
 * to the sha they were requested by, or the response is not a blob body; other codes per
 * {@link toTransportError}.
 * @complexity O(min(b, maxBlobs)) sequential round trips for `b` distinct shas. Memory is O(size of
 * the largest single blob) — downloaded, verified and written one at a time, never collected (the
 * same bound `pushBundleToPeer` documents for the opposite direction).
 */
export async function pullBlobsFromPeer(
  deps: PeerCallDeps & {
    blobSink: PeerBlobSink;
    workspaceId: string;
    computeStorageKey: (sha256: string) => string;
    maxBlobs?: number;
  },
  required: { blobManifest: readonly string[] }
): Promise<PullBlobsResult> {
  const maxBlobs = deps.maxBlobs ?? PUBLISH_CONTENT_PULL_MAX_BLOBS;
  const downloaded: string[] = [];
  const alreadyPresent: string[] = [];
  const unavailable: string[] = [];
  const deferredOverCap: string[] = [];

  // Deduplicated: one manifest legitimately names the same blob for many entities (a logo on every
  // page), and fetching it once per reference would multiply the round trips by the reuse factor.
  for (const sha256 of new Set(required.blobManifest)) {
    if (await deps.blobSink.exists({ storageKey: deps.computeStorageKey(sha256) })) {
      alreadyPresent.push(sha256);
      continue;
    }
    // The cap counts FETCHES, not manifest entries: a blob already held costs no round trip, so it
    // must not consume the budget that bounds them.
    if (downloaded.length + unavailable.length >= maxBlobs) {
      deferredOverCap.push(sha256);
      continue;
    }

    const bytes = await fetchVerifiedPeerBlob(deps, { sha256 });
    if (bytes === null) {
      unavailable.push(sha256);
      continue;
    }

    await deps.blobSink.putIfAbsent({ workspaceId: deps.workspaceId, sha256, bytes });
    downloaded.push(sha256);
  }

  return { downloaded, alreadyPresent, unavailable, deferredOverCap };
}

/** Archive bytes take precedence over JSON when both fields are supplied. */
function peerRequestPayload({ request }: { request: { body?: unknown; archive?: Uint8Array } }, _optional: Record<string, never> = {}): {
  headers: Record<string, string>; content: { body?: string | Uint8Array };
} {
  if (request.archive !== undefined) return { headers: { "content-type": "application/zip" }, content: { body: request.archive } };
  if (request.body === undefined) return { headers: {}, content: {} };
  return { headers: { "content-type": "application/json" }, content: { body: JSON.stringify(request.body) } };
}

/** Probe and upload sequentially before staging, so the peer plans against the uploaded blobs.
 * Refuses out-of-manifest requests before local I/O. O(m + r) validation time and O(m) space for
 * m selected hashes and r requested hashes, followed by sequential blob reads/uploads. */
async function uploadMissingPeerBlobs(
  deps: PeerCallDeps & { blobSource: PeerBlobSource; computeStorageKey: (sha256: string) => string },
  { bundle }: { bundle: PublishContentExportEnvelope },
): Promise<{ blobsUploaded: string[]; blobsUnavailable: string[] }> {
  const { credential } = deps;
  const blobsUploaded: string[] = [];
  const blobsUnavailable: string[] = [];
  if (bundle.blobManifest.length > 0) {
    const probed = requireObject(
      await callPeer(deps, {
        method: "POST",
        path: peerRoute(credential, "/blobs/probe"),
        body: { shas: bundle.blobManifest },
      }),
      "blob probe",
      credential.baseUrl
    );
    const missing = Array.isArray(probed.missing) ? (probed.missing as unknown[]).filter((s): s is string => typeof s === "string") : [];
    // Validate the whole request before any local read or upload: a valid prefix must not let a
    // peer obtain bytes from an invalid mixed batch. This is the manifest AFTER capability trimming.
    const selectedHashes = new Set(bundle.blobManifest);
    if (missing.some(sha256 => !selectedHashes.has(sha256))) {
      throw new PublishContentPeerTransportError(
        "the peer requested a blob outside the selected manifest",
        "PEER_RESPONSE_INVALID"
      );
    }

    for (const sha256 of new Set(missing)) {
      const storageKey = deps.computeStorageKey(sha256);
      if (!(await deps.blobSource.exists({ sha256, storageKey }))) {
        // Not an error: the bundle names a blob this instance no longer holds. Reported, and the
        // peer's own planner blocks whatever needed it rather than applying half an entity.
        blobsUnavailable.push(sha256);
        continue;
      }
      const bytes = await deps.blobSource.get({ sha256, storageKey });
      await callPeer(deps, {
        method: "PUT",
        path: peerRoute(credential, `/blobs/${encodeURIComponent(sha256)}`),
        body: { dataBase64: Buffer.from(bytes).toString("base64") },
      });
      blobsUploaded.push(sha256);
    }
  }

  return { blobsUploaded, blobsUnavailable };
}

/** A missing blob is reportable; malformed or mismatched bytes abort before the local write. */
async function fetchVerifiedPeerBlob(deps: PeerCallDeps, { sha256 }: { sha256: string }): Promise<Uint8Array | null> {
  let body: Record<string, unknown>;
  try {
    body = requireObject(
      await callPeer(deps, { method: "GET", path: peerRoute(deps.credential, `/blobs/${encodeURIComponent(sha256)}`) }),
      "blob fetch",
      deps.credential.baseUrl
    );
  } catch (err) {
    if (err instanceof PublishContentPeerTransportError && err.peerStatus === 404) {
      return null;
    }
    throw err;
  }

  if (typeof body.dataBase64 !== "string") {
    throw new PublishContentPeerTransportError(
      `the peer's response for blob '${sha256}' carried no 'dataBase64' string`,
      "PEER_RESPONSE_INVALID"
    );
  }
  // `Buffer.from(..., "base64")` never throws — it drops invalid characters — so a malformed
  // payload is caught by the hash check below rather than by a decode error, which is the check
  // that has to hold anyway.
  const bytes = new Uint8Array(Buffer.from(body.dataBase64, "base64"));

  // The security property this function exists to hold — see the doc above. MUST precede the
  // write: `putIfAbsent` will not catch it.
  if (!bytesMatchSha256({ bytes, claimedSha256: sha256 })) {
    throw new PublishContentPeerTransportError(
      `the peer's bytes for blob '${sha256}' do not hash to it — refusing to store them under that ` +
        `sha256, because the hash IS the identity this feature addresses content by`,
      "PEER_RESPONSE_INVALID"
    );
  }

  return bytes;
}

import { hasForbiddenRawUrlCharacter } from "@jini-ai/http-kit/verified-origin";

/**
 * @file Task 10 of the publish-content (Publish Content) feature —
 * `ADS-memory/reports/2026-09-18-publish-feature-implementation-plan.md` §4 task 10.
 *
 * `baseUrl` validation for a `publish_content_peers` row — "a Tovu at a URL", which is the whole of
 * a peer's identity (plan §0b: never a platform identifier such as an app name, project id or
 * region, because those are shaped by one host and this feature must work on all of them and
 * on a bare VPS).
 *
 * Deliberately modelled on `features/origin/configured-origin.ts`'s refusal pipeline, and reusing
 * its exported {@link hasForbiddenRawUrlCharacter} rather than re-deriving the raw-character class
 * (a backslash becomes a slash and whitespace is stripped once `new URL()` has run, so the check
 * has to happen on the raw string). Same refusals for the same reasons: non-https, userinfo,
 * query/fragment, control characters, empty host.
 *
 * ONE DELIBERATE DIFFERENCE, and it is load-bearing: `configured-origin.ts` refuses a LOOPBACK host,
 * because a loopback address can never be this deployment's own PUBLIC origin. A peer is the
 * opposite kind of thing — it is a host this process dials OUT to, and a legitimate peer may well
 * sit on a private network: Railway and Render both give services internal DNS names, AWS puts them
 * in a VPC, and a bare VPS may run two Tovus behind one firewall. Refusing private addresses here
 * would make this feature host-shaped (public-internet-only) in exactly the way plan §0b forbids.
 *
 * The private-address decision therefore belongs to the ONE place that already owns it — ADR-038's
 * `EgressPolicy.denyPrivateAddresses` plus its named `devHostAllowlist` capability, enforced in
 * `platform/http/client.ts` against the RESOLVED address, not against a hostname pattern. A peer at
 * a private address is accepted here and refused at send time with a diagnosis that names
 * `devHostAllowlist` (`peer-transport.ts`'s `describePeerEgressRefusal`).
 *
 * `https` stays HARD required, on every host including loopback: the peer credential travels as a
 * bearer `Authorization` header on every request, and the peer egress policy's `allowedSchemes` is
 * `["https"]` so this is a structural property, not just this validator's opinion.
 */

/** Refusal shape — a single operator-facing sentence fragment, ready to be embedded in a 400 body.
 *  Never carries the raw value back (the caller already has it; echoing it into an error body is how
 *  a reflected-value bug starts). */
export interface PeerBaseUrlRefusal {
  readonly error: string;
}

/** Accepted shape — the NORMALIZED value to store, never the caller's raw string, so two peers that
 *  differ only in host case or a trailing slash cannot both exist. */
export interface PeerBaseUrlAccepted {
  readonly baseUrl: string;
}

/**
 * Lower-cases and strips a single trailing dot, matching `features/origin/origin.ts`'s own host
 * normalization so "same host" can never mean two different things across this codebase.
 * @complexity O(n) in the host length.
 */
function normalizeHost(hostname: string): string {
  const lowered = hostname.toLowerCase();
  return lowered.endsWith(".") ? lowered.slice(0, -1) : lowered;
}

/**
 * The refusal pipeline, as one decision function — one readable branch per refusal, mirroring
 * `configured-origin.ts`'s `refusalReason`.
 *
 * @returns The operator-facing refusal reason, or `null` when `url` names a usable peer base URL.
 * @complexity O(n) in the host length.
 */
function refusalReason(url: URL): string | null {
  if (url.protocol !== "https:") return "its scheme must be https";
  if (url.username !== "" || url.password !== "") return "it carries a userinfo component";
  if (url.search !== "" || url.hash !== "") return "it carries a query string or fragment";
  if (normalizeHost(url.hostname) === "") return "its host is empty";
  return null;
}

/**
 * Validates and normalizes an operator-supplied peer base URL.
 *
 * Accepts an optional path prefix (a peer behind a reverse proxy mounted under `/tovu` is a real
 * deployment shape on Render and on a bare VPS) and normalizes it by stripping trailing slashes, so
 * `peerUrl()` can join route paths without producing a double slash.
 *
 * @param raw - The untrusted operator-supplied string, exactly as received.
 * @returns `{baseUrl}` with the normalized origin plus base path, or `{error}` with the single
 * reason it was refused. NEVER throws.
 * @complexity O(n) in the length of `raw` (parser-bound).
 * @example normalizePeerBaseUrl("https://Tovu.example.com/"); // => { baseUrl: "https://tovu.example.com" }
 */
export function normalizePeerBaseUrl(raw: string): PeerBaseUrlAccepted | PeerBaseUrlRefusal {
  const trimmed = raw.trim();
  if (trimmed === "") return { error: "baseUrl is required" };
  if (hasForbiddenRawUrlCharacter({ raw: trimmed })) {
    return { error: "baseUrl carries a backslash, whitespace or control character" };
  }

  let url: URL;
  try {
    url = new URL(trimmed);
  } catch {
    return { error: "baseUrl is not a parseable URL" };
  }

  const reason = refusalReason(url);
  if (reason) return { error: `baseUrl was refused because ${reason}` };

  const host = normalizeHost(url.hostname);
  const authority = url.port === "" ? host : `${host}:${url.port}`;
  const basePath = url.pathname.replace(/\/+$/, "");
  return { baseUrl: `https://${authority}${basePath}` };
}

/**
 * Joins a normalized {@link normalizePeerBaseUrl} result with an absolute route path.
 *
 * @param path - An absolute route path beginning with `/` (e.g. `/api/admin/v1/...`).
 * @complexity O(1).
 */
export function peerUrl(baseUrl: string, path: string): string {
  return `${baseUrl}${path}`;
}

/**
 * The bracket-stripped hostname of a normalized peer base URL — the exact form
 * `EgressPolicy.devHostAllowlist` is matched against (`platform/http/client.ts` strips IPv6 brackets
 * before the lookup, so an allowlist entry is written without them, as a human would type it).
 * Exported so the egress diagnosis can tell an operator the literal string to add.
 *
 * @returns The hostname, or the raw `baseUrl` unchanged if it somehow fails to parse (this function
 * is only ever called on an already-normalized value, so that fallback is unreachable in practice
 * and exists only so a diagnosis path can never itself throw).
 * @complexity O(n) in the length of `baseUrl`.
 */
export function peerHostname(baseUrl: string): string {
  try {
    const hostname = new URL(baseUrl).hostname;
    return hostname.startsWith("[") && hostname.endsWith("]") ? hostname.slice(1, -1) : hostname;
  } catch {
    return baseUrl;
  }
}

import { nowIso, type Clock } from "@jini-ai/core/primitives";
import { isUniqueViolation } from "../../platform/db/kernel/dialect.js";
import { InMemoryVaultRepo, SecretsVaultService, VaultError, type VaultRepoPort, type VaultRecord } from "@jini-ai/platform/secrets/credential-sets";
import { credentialTokenHint } from "#src/contracts/core/credential-token";
import { byVaultLabel, createTovuVaultKinds } from "#src/platform/secrets/vault-kinds";
import { normalizePeerBaseUrl } from "./peer-url.js";
import type { KeyringPort, SealedSecret, SecretSealerPort } from "#src/features/webhooks/index";

/**
 * @file Task 10 of the publish-content (Publish Content) feature —
 * `ADS-memory/reports/2026-09-18-publish-feature-implementation-plan.md` §4 task 10.
 *
 * `publish-peer` vault CRUD — a named remote Tovu this workspace can push content to or pull it
 * from. A peer is a URL plus a sealed API key and nothing else (plan §0b: never a platform
 * identifier, so the same row works against any container host, cloud or a bare VPS).
 *
 * TWO STRICTLY SEPARATED OPERATIONS, the same discipline
 * `features/deployments/publish-credentials/store.ts` documents and for the same reason:
 *
 * - {@link toPeerSummary} / {@link listPublishContentPeers} / {@link getPublishContentPeerSummary} —
 *   read model only. Never decrypts, never touches `sealer`/`keyring` at all, so neither can fail
 *   on a misconfigured site key. This is what every route response is built from.
 * - {@link resolvePeerCredential} — the ONLY function in this module that decrypts. Its one
 *   legitimate caller is the outbound transport driver (`peer-transport.ts`), server-side and
 *   human-gated behind `publish_content.apply`. It is named to say "decrypts" out loud so a future
 *   caller cannot reach for it the way a generically-named `getPeer` would invite.
 *
 * WHAT MAY LEAVE THE SERVER: {@link PublishContentPeerSummary} has no field capable of carrying
 * secret material — `masked` (a display hint derived from the key, never the key) and
 * `hasCredential` (a boolean) are the only credential-shaped fields that exist on it. The sealed
 * columns are not merely omitted from the read model; the read model has nowhere to put them.
 *
 * STORAGE SHAPE: Jini's vault owns persistence, JSON sealing and context-bound AAD. The site
 * key remains installation-owned; no vendor secret-store dependency is introduced here.
 */

/** Thrown when a named peer does not exist in this workspace. */
export class PublishContentPeerNotFoundError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "PublishContentPeerNotFoundError";
  }
}

/** Thrown when operator-supplied peer input is unusable. `message` is operator-facing and never
 *  echoes a supplied credential. */
export class PublishContentPeerValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "PublishContentPeerValidationError";
  }
}

/** Thrown when a write would violate `publish_content_peers_workspace_label_unique`. */
export class PublishContentPeerDuplicateLabelError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "PublishContentPeerDuplicateLabelError";
  }
}

/** Thrown when `sealer.seal()`/`keyring.activeKey()` fails — fail-closed, never a plaintext write.
 *  Mirrors `PublishCredentialSecretStoreUnconfiguredError`. */
export class PublishContentPeerSecretStoreUnconfiguredError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "PublishContentPeerSecretStoreUnconfiguredError";
  }
}

/** Thrown when a peer row exists but carries no sealed credential — a push/pull cannot proceed. */
export class PublishContentPeerCredentialMissingError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "PublishContentPeerCredentialMissingError";
  }
}

/** The existing peer record projected from the vault (`sealed` is the DB's opaque {@link SealedSecret};
 *  the raw API key only exists in memory after {@link resolvePeerCredential} opens it). */
export interface PublishContentPeerRecord {
  readonly workspaceId: string;
  readonly id: string;
  readonly label: string;
  readonly baseUrl: string;
  readonly remoteWorkspaceId: string;
  readonly sealed: SealedSecret | null;
  /** Display-only hint derived from the key at seal time (see {@link maskApiKey}) — held in the
   *  clear deliberately, the same "public label, not secret material" reasoning
   *  `publishCredentialSets.accountLabel` documents. */
  readonly masked: string | null;
  /** Compatibility version; vault AAD is owned by Jini. */
  readonly aadVersion: number;
  readonly createdAt: string;
  readonly updatedAt: string;
}

/**
 * The read model every peers route returns. FROZEN CONTRACT (Task 10's dispatch): `masked` and
 * `hasCredential` are the only credential-shaped fields that ever leave the server — no
 * `sealedCiphertext`, `sealedNonce`, `sealedKeyId` or `sealedAlg` in any response body, log line,
 * error message or report, ever. Enforced by construction: this type has no field capable of
 * carrying one.
 */
export interface PublishContentPeerSummary {
  readonly id: string;
  readonly label: string;
  readonly baseUrl: string;
  readonly remoteWorkspaceId: string;
  readonly masked: string | null;
  readonly hasCredential: boolean;
}

/** Workspace-scoped persistence for {@link PublishContentPeerRecord} (ADR-007 §1). `insert`/`update`
 *  may reject on the `(workspace_id, label)` UNIQUE index; this module turns that driver error into
 *  {@link PublishContentPeerDuplicateLabelError} rather than propagating it raw. */
export interface PublishContentPeerRepoPort {
  readonly vault: VaultRepoPort;
  insert(record: PublishContentPeerRecord): Promise<void>;
  /** Full-row replace by `(workspaceId, id)`. */
  update(record: PublishContentPeerRecord): Promise<void>;
  findById(input: { workspaceId: string; id: string }): Promise<PublishContentPeerRecord | null>;
  /** Every peer a workspace has saved. Inherently small — bounded by how many peers a human types
   *  into this one form, never by a caller-supplied N — so no pagination or cap, the same reasoning
   *  `VendorCredentialSetRepoPort.listByWorkspace` records. */
  listByWorkspace(input: { workspaceId: string }): Promise<PublishContentPeerRecord[]>;
  /** No-op (not an error) if no row exists — matches this feature's DELETE route contract. */
  delete(input: { workspaceId: string; id: string }): Promise<void>;
}

/** Read-side deps: NO sealer, NO keyring — see this file's header. */
export interface PublishContentPeerReadDeps {
  readonly repo: PublishContentPeerRepoPort;
}

/** Write-side deps. `sealer`/`keyring` are the shared ADR-058 instances every other credential table
 *  in this codebase uses (`RouteDeps.siteAssistantSecretSealer`/`siteAssistantSecretKeyring`). */
export interface PublishContentPeerWriteDeps extends PublishContentPeerReadDeps {
  readonly sealer: SecretSealerPort;
  readonly keyring: KeyringPort;
  readonly clock: Clock;
  readonly idGen: { newId(): string };
}

/** Jini owns hint length policy; the feature keeps its existing display format. */
export function maskApiKey(apiKey: string): string {
  const hint = credentialTokenHint({ token: apiKey });
  return `••••${hint.last4 ?? ""}`;
}

const peerKinds = createTovuVaultKinds({ policy: {
  validateMeta: ({ meta }) => meta, legacyPublishCredential: () => undefined, tokenField: () => "apiKey",
} });
const peerScope = { kind: "publish-peer" as const, ownerKey: "tovu", principalId: null, provider: null };

/** Keep feature permissions at the calling route/tool; restrict this adapter to its own kind.
 * @complexity O(1); constructing a service performs no I/O.
 */
function peerVault({ repo, sealer, keyring, now }: {
  repo: PublishContentPeerRepoPort; sealer: SecretSealerPort; keyring?: KeyringPort; now?: () => string;
}, _options = {}): SecretsVaultService {
  const unavailable = async (): Promise<never> => { throw new Error("peer read cannot access keyring"); };
  return new SecretsVaultService({ repo: repo.vault, sealer,
    keyring: keyring ?? { activeKey: unavailable, derive: unavailable, deriveSigningSecret: unavailable },
    metaParsers: peerKinds.metaParsers, now: now ?? (() => new Date().toISOString()), newId: () => { throw new Error("peer ID must be supplied"); },
    authorize: async ({ context }) => {
      if (context.kind !== peerScope.kind || context.ownerKey !== peerScope.ownerKey || context.principalId !== null) throw new VaultError({ code: "context" });
    },
  });
}

/** Vault to the existing internal record; summaries never expose the envelope.
 * @complexity O(metadata size) validation, then fixed projection.
 */
function peerRecord({ record }: { record: VaultRecord }, _options = {}): PublishContentPeerRecord {
  if (record.kind !== "publish-peer" || record.ownerKey !== "tovu" || record.principalId !== null || record.provider !== null || record.binding !== null) throw new VaultError({ code: "context" });
  const meta = peerKinds.metaParsers["publish-peer"]({ meta: record.meta });
  return { workspaceId: record.workspaceId, id: record.id, label: record.label, baseUrl: meta.baseUrl as string,
    remoteWorkspaceId: meta.remoteWorkspaceId as string, sealed: record.sealed,
    masked: peerRecordHint({ record }),
    aadVersion: 1, createdAt: record.createdAt, updatedAt: record.updatedAt };
}

/**
 * The one projection from a stored row to what a route may return.
 *
 * @complexity O(1) — fixed-shape field mapping.
 */
export function toPeerSummary(record: PublishContentPeerRecord): PublishContentPeerSummary {
  return {
    id: record.id,
    label: record.label,
    baseUrl: record.baseUrl,
    remoteWorkspaceId: record.remoteWorkspaceId,
    masked: record.masked,
    hasCredential: record.sealed !== null,
  };
}

/** Trims and rejects a blank required string, with the field's own name in the message.
 *  @complexity O(n). */
function requireNonEmpty(value: unknown, field: string): string {
  if (typeof value !== "string" || value.trim() === "") {
    throw new PublishContentPeerValidationError(`'${field}' is required and must be a non-empty string`);
  }
  return value.trim();
}

/** Longest accepted `label`/`remoteWorkspaceId`/`apiKey` — a bound on what one operator-typed field
 *  can push into a row, so a paste accident cannot write an unbounded value. */
const MAX_FIELD_LENGTH = 512;

/** @complexity O(1). */
function requireBoundedField(value: unknown, field: string): string {
  const trimmed = requireNonEmpty(value, field);
  if (trimmed.length > MAX_FIELD_LENGTH) {
    throw new PublishContentPeerValidationError(`'${field}' must be at most ${MAX_FIELD_LENGTH} characters`);
  }
  return trimmed;
}

/** @complexity O(n) in the length of `raw`. */
function requireBaseUrl(raw: unknown): string {
  const trimmed = requireBoundedField(raw, "baseUrl");
  const result = normalizePeerBaseUrl(trimmed);
  if ("error" in result) throw new PublishContentPeerValidationError(result.error);
  return result.baseUrl;
}

export interface CreatePeerInput {
  readonly workspaceId: string;
  readonly label: unknown;
  readonly baseUrl: unknown;
  readonly remoteWorkspaceId: unknown;
  readonly apiKey: unknown;
}

/**
 * Validates, seals and inserts a new peer. The row id is minted here (`deps.idGen`), never
 * caller-supplied — the AAD binds it, so a caller able to choose it could pre-compute an AAD.
 *
 * @returns The read model, never the record — a create response carries no more than a list row.
 * @throws {PublishContentPeerValidationError} on any unusable field.
 * @throws {PublishContentPeerDuplicateLabelError} when the label is already taken in this workspace.
 * @throws {PublishContentPeerSecretStoreUnconfiguredError} when the site key is unavailable.
 * @complexity O(1) — one seal and one insert.
 */
export async function createPublishContentPeer(
  deps: PublishContentPeerWriteDeps,
  input: CreatePeerInput
): Promise<PublishContentPeerSummary> {
  const label = requireBoundedField(input.label, "label");
  const baseUrl = requireBaseUrl(input.baseUrl);
  const remoteWorkspaceId = requireBoundedField(input.remoteWorkspaceId, "remoteWorkspaceId");
  const apiKey = requireBoundedField(input.apiKey, "apiKey");

  const id = deps.idGen.newId();
  const now = nowIso({ clock: deps.clock });
  try {
    await peerVault({ ...deps, now: () => now }).put({ ...peerScope, workspaceId: input.workspaceId, id,
      binding: null, expectedRevision: null, label, meta: { baseUrl, remoteWorkspaceId },
      payload: { apiKey }, hintToken: apiKey });
  } catch (err) {
    await rethrowPeerWriteError(deps, { err, workspaceId: input.workspaceId, label });
  }
  return { id, label, baseUrl, remoteWorkspaceId, masked: maskApiKey(apiKey), hasCredential: true };
}

export interface UpdatePeerInput {
  readonly workspaceId: string;
  readonly id: string;
  /** Every field is optional: an absent key means "leave it alone", which is what makes a rename
   *  possible without re-typing the credential. An explicitly supplied `apiKey` is ALWAYS resealed
   *  as a fresh ciphertext — never a re-wrap of the stored one. */
  readonly label?: unknown;
  readonly baseUrl?: unknown;
  readonly remoteWorkspaceId?: unknown;
  readonly apiKey?: unknown;
}

/**
 * Applies a partial update to an existing peer.
 *
 * @throws {PublishContentPeerNotFoundError} when no row exists for `(workspaceId, id)`.
 * @complexity O(1) — one read, at most one seal, one update.
 */
export async function updatePublishContentPeer(
  deps: PublishContentPeerWriteDeps,
  input: UpdatePeerInput
): Promise<PublishContentPeerSummary> {
  const existing = await deps.repo.findById({ workspaceId: input.workspaceId, id: input.id });
  if (!existing) throw new PublishContentPeerNotFoundError(`peer '${input.id}' was not found`);

  const label = input.label === undefined ? existing.label : requireBoundedField(input.label, "label");
  const baseUrl = input.baseUrl === undefined ? existing.baseUrl : requireBaseUrl(input.baseUrl);
  const remoteWorkspaceId =
    input.remoteWorkspaceId === undefined
      ? existing.remoteWorkspaceId
      : requireBoundedField(input.remoteWorkspaceId, "remoteWorkspaceId");

  const now = nowIso({ clock: deps.clock });
  if (input.apiKey === undefined) {
    await updatePeerMetadata(deps, { record: { ...existing, label, baseUrl, remoteWorkspaceId, updatedAt: now } });
    return toPeerSummary({ ...existing, label, baseUrl, remoteWorkspaceId });
  }
  const apiKey = requireBoundedField(input.apiKey, "apiKey");
  const current = await deps.repo.vault.find({ workspaceId: input.workspaceId, id: input.id });
  if (!current) throw new PublishContentPeerNotFoundError(`peer '${input.id}' was not found`);
  try {
    await peerVault({ ...deps, now: () => now }).put({ ...peerScope, workspaceId: input.workspaceId, id: input.id,
      binding: null, expectedRevision: current.revision, label, meta: { ...current.meta, baseUrl, remoteWorkspaceId },
      payload: { apiKey }, hintToken: apiKey });
  } catch (err) {
    await rethrowPeerWriteError(deps, { err, workspaceId: input.workspaceId, label, excludeId: input.id });
  }
  return { id: input.id, label, baseUrl, remoteWorkspaceId, masked: maskApiKey(apiKey), hasCredential: true };
}

/**
 * Every peer in a workspace, as read models.
 * @complexity O(n) in the workspace's peer count (one repo read plus one projection each).
 */
export async function listPublishContentPeers(
  deps: PublishContentPeerReadDeps,
  input: { workspaceId: string }
): Promise<PublishContentPeerSummary[]> {
  const records = await deps.repo.listByWorkspace(input);
  return records.map(toPeerSummary);
}

/**
 * One peer's read model.
 * @returns `null` when no row exists — a route decides whether that is a 404.
 * @complexity O(1).
 */
export async function getPublishContentPeerSummary(
  deps: PublishContentPeerReadDeps,
  input: { workspaceId: string; id: string }
): Promise<PublishContentPeerSummary | null> {
  const record = await deps.repo.findById(input);
  return record ? toPeerSummary(record) : null;
}

/**
 * Idempotent delete — removing an already-absent peer is not an error.
 * @complexity O(1).
 */
export async function deletePublishContentPeer(
  deps: PublishContentPeerReadDeps,
  input: { workspaceId: string; id: string }
): Promise<void> {
  await deps.repo.delete(input);
}

/** What {@link resolvePeerCredential} hands the transport driver: everything needed to dial the
 *  peer, with the opened key. NEVER serialize this — see this file's header. */
export interface ResolvedPeerCredential {
  readonly id: string;
  readonly label: string;
  readonly baseUrl: string;
  readonly remoteWorkspaceId: string;
  /** The opened API key. In memory only, for the lifetime of one outbound request. */
  readonly apiKey: string;
}

/**
 * THE ONLY DECRYPTING FUNCTION IN THIS MODULE — see this file's header before adding a caller.
 *
 * @throws {PublishContentPeerNotFoundError} when no row exists.
 * @throws {PublishContentPeerCredentialMissingError} when the row carries no sealed credential.
 * @throws {PublishContentPeerSecretStoreUnconfiguredError} when the site key is unavailable or the
 * ciphertext fails auth-tag verification — a typed error rather than whatever raw error
 * `SecretSealerPort.open()` produced, so a boundary never renders a driver message.
 * @complexity Two row reads and one AEAD open; no group scan.
 */
export async function resolvePeerCredential(
  deps: { repo: PublishContentPeerRepoPort; sealer: SecretSealerPort },
  input: { workspaceId: string; id: string }
): Promise<ResolvedPeerCredential> {
  const record = await deps.repo.findById(input);
  if (!record) throw new PublishContentPeerNotFoundError(`peer '${input.id}' was not found`);
  if (!record.sealed) {
    throw new PublishContentPeerCredentialMissingError(
      `peer '${record.label}' has no saved credential; add one before pushing or pulling`
    );
  }

  let apiKey: string;
  try {
    const opened = await peerVault(deps).get({ ...peerScope, ...input, binding: null });
    if (typeof opened?.payload?.apiKey !== "string") throw new VaultError({ code: "invalid-record" });
    apiKey = opened.payload.apiKey;
  } catch {
    // Raw crypto/driver errors can describe secrets; only the feature's safe error crosses out.
    throw new PublishContentPeerSecretStoreUnconfiguredError(`peer '${record.label}' credential could not be opened`);
  }

  return {
    id: record.id,
    label: record.label,
    baseUrl: record.baseUrl,
    remoteWorkspaceId: record.remoteWorkspaceId,
    apiKey,
  };
}

/** Thin compatibility facade: Jini owns storage, uniqueness, defaults and revision CAS.
 * Metadata-only connected destinations retain the nullable envelope marker.
 */
export class VaultPublishContentPeerRepo implements PublishContentPeerRepoPort {
  constructor({ vault }: { vault: VaultRepoPort }, _options = {}) { this.vault = vault; }
  readonly vault: VaultRepoPort;

  async insert(record: PublishContentPeerRecord): Promise<void> { await this.write({ record, insert: true }); }
  async update(record: PublishContentPeerRecord): Promise<void> { await this.write({ record, insert: false }); }

  /** Preserve opaque bytes for metadata edits; Jini guards the replacement revision.
   * @complexity O(metadata size), one read and one CAS write; only conflicts query labels.
   */
  private async write({ record, insert }: { record: PublishContentPeerRecord; insert: boolean }, _options = {}): Promise<void> {
    const existing = insert ? null : await this.vault.find(record);
    if (!insert && !existing) return;
    if (existing) peerRecord({ record: existing });
    const saved = replacementPeerRecord({ record, existing });
    try { await this.vault.put({ record: saved, expectedRevision: existing?.revision ?? null }); }
    catch (err) {
      if (await vaultLabelConflicts({ vault: this.vault, err, record })) {
        throw new Error("UNIQUE constraint failed: publish_content_peers.workspace_id, publish_content_peers.label");
      }
      throw err;
    }
  }
  async findById(input: { workspaceId: string; id: string }): Promise<PublishContentPeerRecord | null> {
    const record = await this.vault.find(input);
    return record ? peerRecord({ record }) : null;
  }
  async listByWorkspace(input: { workspaceId: string }): Promise<PublishContentPeerRecord[]> {
    // Label order, as before the vault (the label index drove the scan); the vault lists by id.
    return (await this.vault.list({ ...peerScope, ...input })).sort(byVaultLabel).map(record => peerRecord({ record }));
  }
  async delete(input: { workspaceId: string; id: string }): Promise<void> {
    const existing = await this.vault.find(input);
    if (!existing) return;
    peerRecord({ record: existing });
    await this.vault.delete({ ...input, expectedRevision: existing.revision });
  }
}

/** Same facade as SQL, backed by Jini's memory adapter rather than a second lifecycle. */
export class InMemoryPublishContentPeerRepo extends VaultPublishContentPeerRepo {
  constructor(_required = {}, _options = {}) { super({ vault: new InMemoryVaultRepo({}) }); }
}

/**
 * Saves (or refreshes) the row for a destination this install is CONNECTED to — a site whose
 * publishing is authorized by the derived site key handshake rather than by a pasted key.
 *
 * `sealed: null` IS the marker, and it needs no migration or new column because it was previously
 * unreachable: {@link createPublishContentPeer} always seals, and {@link updatePublishContentPeer}
 * can only replace a sealed value, so no existing row can be null. `destination-credential.ts` is
 * the one reader of that distinction.
 *
 * Keyed on `baseUrl`, not on `label`: the address is what identifies a site, and re-connecting the
 * same site must update its row rather than collide with it. A label already taken by a DIFFERENT
 * site falls back to the full address, so connecting can never fail on a name the owner never chose
 * and would have to go and edit.
 *
 * **At most one connected row per workspace.** Connecting to a different address moves the
 * connection — the previous connected row is removed, not left beside the new one. This is not a
 * policy choice; it is what the authorisation layer already does. `publish-trust/connect.ts` writes
 * the grant through `provisioning.connect`, which merges by source installation id and so
 * "replaces this computer's own entry" on every connect, and `disconnectDestination` takes no
 * address because there is only ever one entry to remove. A second `sealed: null` row is therefore
 * not a second connection; it is a row describing an authorisation that no longer exists, and every
 * reader used to take whichever such row the repository listed first (sol review 2026-09-20, High
 * finding 4: the operator is shown "connected", and Publish silently targets the stale site).
 *
 * @returns The read model, which by construction can carry no credential-shaped field.
 * @complexity O(n) in the workspace's peer count (one list scan), plus one write and at most one
 * delete per superseded connection (at most one in practice, since this rule keeps it at one).
 */
/**
 * The one destination this install is CONNECTED to, or `null`.
 *
 * The single definition of "which connected row do we mean", so the three readers that ask —
 * `routes/publish-content/destination.ts`'s view, and `publish-content/tool-registrations.ts`'s
 * readiness and publish handlers — cannot drift apart or answer differently for the same rows.
 *
 * {@link saveConnectedDestination} keeps at most one connected row per workspace, so in practice
 * there is nothing to choose between. The tie-break exists for rows written before that rule
 * (sol review 2026-09-20, High finding 4, where every reader took whichever row the repository
 * happened to list first): this install holds exactly ONE grant, `provisioning.connect` replaces it
 * on every connect, so the only row that grant can possibly authorise is the most recently written
 * one. Picking by repository order could return a connection that no longer exists and publish
 * someone's content to the wrong site.
 *
 * A peer with a sealed key is deliberately NOT a candidate: it is a destination the owner
 * configured by hand, not a connection, and `destination.ts` must not report one as "connected"
 * with `hasCredential: false`.
 *
 * @complexity O(n) in the workspace's peer count.
 */
export function selectConnectedDestination(
  rows: readonly PublishContentPeerRecord[]
): PublishContentPeerRecord | null {
  let chosen: PublishContentPeerRecord | null = null;
  for (const row of rows) {
    if (row.sealed !== null) continue;
    if (chosen === null || row.updatedAt > chosen.updatedAt) chosen = row;
  }
  return chosen;
}

export async function saveConnectedDestination(
  deps: PublishContentPeerReadDeps & { clock: Clock; idGen: { newId(): string } },
  input: { workspaceId: string; label: string; baseUrl: string; remoteWorkspaceId: string }
): Promise<PublishContentPeerSummary> {
  const baseUrl = requireBaseUrl(input.baseUrl);
  const remoteWorkspaceId = requireBoundedField(input.remoteWorkspaceId, "remoteWorkspaceId");
  const existing = await deps.repo.listByWorkspace({ workspaceId: input.workspaceId });
  const match = existing.find((row) => row.baseUrl === baseUrl) ?? null;

  // Connecting to a different site MOVES the connection; it does not add a second one. See this
  // function's doc comment for why a second connected row cannot describe anything real. Only
  // `sealed === null` rows are superseded — a peer the owner configured by hand with a pasted key
  // is untouched, exactly as `removeConnectedDestination` refuses to delete one.
  const superseded = existing.filter((row) => row.sealed === null && row.baseUrl !== baseUrl);
  const supersededIds = new Set(superseded.map((row) => row.id));

  const wanted = requireBoundedField(input.label, "label");
  const takenByAnother = existing.some(
    (row) => row.label === wanted && row.id !== match?.id && !supersededIds.has(row.id)
  );
  const label = takenByAnother ? baseUrl : wanted;

  const now = nowIso({ clock: deps.clock });
  const record: PublishContentPeerRecord = {
    workspaceId: input.workspaceId,
    id: match?.id ?? deps.idGen.newId(),
    label,
    baseUrl,
    remoteWorkspaceId,
    // Never a key: a connected destination authenticates by proving possession of the site key
    // at publish time, so there is nothing to store between publishes.
    sealed: null,
    masked: null,
    aadVersion: 1,
    createdAt: match?.createdAt ?? now,
    updatedAt: now,
  };

  // Superseded rows go BEFORE the new one lands, deliberately. The grant has already been rewritten
  // for the new site by the time this runs, so if the write below fails the two possible end states
  // are "no connected row" (the owner is told to connect again — `connect.ts` makes clicking it
  // again explicitly safe) and "the stale row plus the new one", which is the state this whole rule
  // exists to prevent. Being briefly disconnected is truthful; publishing to the wrong site is not.
  for (const row of superseded) await deps.repo.delete({ workspaceId: input.workspaceId, id: row.id });

  if (match) await deps.repo.update(record);
  else await deps.repo.insert(record);
  return toPeerSummary(record);
}

/**
 * Removes the row for a connected destination, by address.
 *
 * Refuses to touch a row that carries a sealed key — disconnecting must never silently delete a
 * peer the owner configured by hand with a credential they would then have to find again.
 *
 * @returns `true` when a row was removed.
 * @complexity O(n) in the workspace's peer count, plus at most one delete.
 */
export async function removeConnectedDestination(
  deps: PublishContentPeerReadDeps,
  input: { workspaceId: string; baseUrl: string }
): Promise<boolean> {
  const rows = await deps.repo.listByWorkspace({ workspaceId: input.workspaceId });
  const match = rows.find((row) => row.baseUrl === input.baseUrl && row.sealed === null);
  if (!match) return false;
  await deps.repo.delete({ workspaceId: input.workspaceId, id: match.id });
  return true;
}

/** Read-only hint projection retains the legacy length threshold without opening the envelope. */
function peerRecordHint({ record }: { record: VaultRecord }, _options = {}): string | null {
  if (!record.sealed) return null;
  const last4 = record.tokenLength !== null && record.tokenLength >= 12 ? record.last4?.slice(-4) ?? "" : "";
  return `••••${last4}`;
}

/** The same vault-write failure policy governs create and credential replacement.
 * Recognises the `(workspace_id, label)` UNIQUE index rejecting a write, from any database
 * (`isUniqueViolation`, storage kernel: SQLite's message, Postgres SQLSTATE 23505).
 * @complexity O(n) in the message length, plus a workspace vault read for conflicts. */
async function rethrowPeerWriteError(
  { repo }: PublishContentPeerReadDeps,
  { err, workspaceId, label, excludeId }: { err: unknown; workspaceId: string; label: string; excludeId?: string },
): Promise<never> {
  if (isUniqueViolation(err)) throw new PublishContentPeerDuplicateLabelError(`a peer labelled '${label}' already exists in this workspace`);
  if (err instanceof VaultError && err.code === "conflict") {
    const rows = await repo.listByWorkspace({ workspaceId });
    if (rows.some(row => row.id !== excludeId && row.label === label)) throw new PublishContentPeerDuplicateLabelError(`a peer labelled '${label}' already exists in this workspace`);
  }
  if (err instanceof VaultError) throw err;
  throw new PublishContentPeerSecretStoreUnconfiguredError("publish-content peer secret store is unconfigured");
}

async function updatePeerMetadata({ repo }: PublishContentPeerReadDeps, { record }: { record: PublishContentPeerRecord }): Promise<void> {
  try { await repo.update(record); }
  catch (err) {
    if (isUniqueViolation(err)) throw new PublishContentPeerDuplicateLabelError(`a peer labelled '${record.label}' already exists in this workspace`);
    throw err;
  }
}

/** Preserve opaque envelope bytes and vault defaults when the feature edits metadata. */
function replacementPeerRecord({ record, existing }: { record: PublishContentPeerRecord; existing: VaultRecord | null }, _options = {}): VaultRecord {
  const meta = peerKinds.metaParsers["publish-peer"]({ meta: { ...existing?.meta, baseUrl: record.baseUrl, remoteWorkspaceId: record.remoteWorkspaceId } });
  return { ...peerScope, workspaceId: record.workspaceId, id: record.id, binding: null,
    label: record.label, meta, sealed: record.sealed, updatedAt: record.updatedAt,
    ...peerRevisionFields({ record, existing }), ...peerEnvelopeHint({ record, existing }) };
}

function peerRevisionFields({ record, existing }: { record: PublishContentPeerRecord; existing: VaultRecord | null }, _options = {}): Pick<VaultRecord, "isDefault" | "revision" | "createdAt"> {
  return { isDefault: existing?.isDefault ?? false, revision: (existing?.revision ?? 0) + 1, createdAt: existing?.createdAt ?? record.createdAt };
}

function peerEnvelopeHint({ record, existing }: { record: PublishContentPeerRecord; existing: VaultRecord | null }, _options = {}): Pick<VaultRecord, "last4" | "tokenLength"> {
  if (!record.sealed) return { last4: null, tokenLength: null };
  return { last4: existing?.last4 ?? null, tokenLength: existing?.tokenLength ?? null };
}

async function vaultLabelConflicts({ vault, err, record }: { vault: VaultRepoPort; err: unknown; record: PublishContentPeerRecord }, _options = {}): Promise<boolean> {
  return err instanceof VaultError && err.code === "conflict" &&
    (await vault.list({ ...peerScope, workspaceId: record.workspaceId })).some(row => row.id !== record.id && row.label === record.label);
}

import { ToolInputError } from "@jini-ai/core";
import type { PublishContentToolDeps } from "./tool-registrations.js";
import { resolvePublishDestinationCredential } from "./destination-credential.js";
import { selectConnectedDestination } from "./peers.js";
import { canPublishToLive, PUBLISH_FROM_LIVE_SITE_ERROR } from "./live-site-policy.js";
import { planPublishToPeer } from "./push-plan.js";
import { confirmPeerImport, executePeerImport } from "./peer-transport.js";
import { applyPublishCriteria, parsePublishContentToolInput, type PublishCriteria } from "./ui/criteria.js";
import { canConfirmPlan } from "./ui/phase.js";
import { overwriteReplanIsConsistent, preparePublishConfirmation } from "./ui/replan.js";
import { selectableRowKeys, toPublishReportRows } from "./ui/report-rows.js";
import type { PublishContentPlanResult, PublishContentReport } from "./ui/contract.js";

/** Strict tool boundary: misspelled filters must never widen an autonomous publish. */
function readCriteria(input: Record<string, unknown>): PublishCriteria & { readonly excludeItems?: readonly string[] } {
  for (const key of ["types", "items", "excludeItems"] as const) {
    const value = input[key];
    if (value !== undefined && (!Array.isArray(value) || value.length > 1000 ||
      !value.every(item => typeof item === "string" && item.trim().length > 0))) {
      throw new ToolInputError({ message: `'${key}' must be an array of at most 1000 non-empty strings.` });
    }
  }
  try {
    return { ...parsePublishContentToolInput(input), ...(input.excludeItems === undefined ? {} : { excludeItems: input.excludeItems as string[] }) };
  } catch (error) {
    throw new ToolInputError({ message: error instanceof Error ? error.message.replace(/^admin\.publish_content:/, "publish_content_publish:") : "Invalid publish selection." });
  }
}

/** The remote report is untrusted; refuse malformed/refused plans before any confirm call. */
function readReport(value: unknown): PublishContentReport {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new ToolInputError({ message: "The live site returned no publish report." });
  const report = value as PublishContentReport;
  const outcomes = new Set(["created", "applied", "forced", "unchanged", "conflict", "blocked"]);
  if (typeof report.refused !== "boolean" || !Array.isArray(report.rows) || !report.rows.every(row => validReportRow({ row, outcomes }))) {
    throw new ToolInputError({ message: "The live site returned an invalid publish report." });
  }
  if (report.refused) throw new ToolInputError({ message: report.refusalReason ?? "The live site refused this publish." });
  return report;
}

/** A remote row's write flag must agree with its outcome before it can be reported as published.
 * @complexity O(1) time and space per row. */
function validReportRow(
  { row, outcomes }: { row: PublishContentReport["rows"][number]; outcomes: ReadonlySet<string> },
  _options: Record<string, never> = {},
): boolean {
  return row && typeof row.entityType === "string" && typeof row.entityId === "string" &&
    typeof row.writes === "boolean" && outcomes.has(row.outcome) &&
    row.writes === ["created", "applied", "forced"].includes(row.outcome);
}

/** CMS-specific autonomous push. Ports supply credential resolution, export and peer HTTP; no
