    return {
      published: [], skipped, unverified: confirmed.details.rows.filter(row => row.writes).map(row => ({
        entityKey: `${row.entityType}:${row.entityId}`, title: row.entityLabel, publicUrl: urls[`${row.entityType}:${row.entityId}`] ?? null
