    };
    return handler;
  } };
}

/** Used by the audited undo route, never by normal publish. Check and inverse share the same DB
 * transaction, preventing an edit between OCC and restoration. FK failures roll back the undo. */
export async function undoRawRow(
  { deps, entity, before, afterHash }: { deps: PublishContentDeps; entity: PackedEntity; before: RawRowSnapshot | null; afterHash: string },
  _optional: Record<string, never> = {},
): Promise<string | null> {
  const rows = deps.backstop?.rows;
  if (!rows) return "Send by hand is not available on this destination.";
  const handler = contributeRawRowPublish().build(deps);
  const reason = await handler.precheck(entity);
  if (reason) return reason;
  return rows.transaction({ work: async () => {
    const live = await handler.inspect(entity.id);
    if (live?.hash !== afterHash) return `Row '${entity.id}' changed on live after this send; it was left alone.`;
    if (before) {
      const inverse = { ...entity, state: rowState(before), contentHash: rowHash(before) };
      const denied = await handler.precheck(inverse);
      if (denied) return denied;
      await rows.upsert(before);
    } else {
      const incoming = entity.state as unknown as RawRowSnapshot;
      await rows.removeCreated({ table: incoming.table, pk: incoming.pk });
    }
    return null;
  } });
}

function blobScalar({ value }: { value: unknown }, _optional: Record<string, never> = {}): boolean {
  return (typeof value === "object" && value !== null && Object.keys(value).length === 1 &&
    typeof (value as { blobBase64?: unknown }).blobBase64 === "string" &&
    /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test((value as { blobBase64: string }).blobBase64));
}

function invalidColumn({ column }: { column: RawColumn | null }, _optional: Record<string, never> = {}): boolean {
  return !column || typeof column.name !== "string" || typeof column.type !== "string" || !Number.isInteger(column.pk) || !Number.isInteger(column.notnull);
}

function recordValue({ value }: { value: unknown }, _optional: Record<string, never> = {}): boolean {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

function checkContent({ entity }: { entity: PackedEntity }, _optional: Record<string, never> = {}): string | null {
  const { table, values } = entity.state as unknown as RawRowSnapshot;
  const scannable = Object.fromEntries(Object.entries(values).map(([name, value]) => [name,
    typeof value === "object" && value !== null ? Buffer.from((value as { blobBase64: string }).blobBase64, "base64").toString("utf8") : value]));
  return checkRawValues({ table, values: scannable }) ??
    (entity.contentHash === rowHash(entity.state as unknown as RawRowSnapshot) ? null : "The raw row does not match its checked content hash.");
}

import { executeCommand } from "@jini-ai/cms/core";
import type { JsonObject } from "@jini-ai/core/primitives";

import { PublishContentApplyRowError } from "./apply-errors.js";
import { contentHash, CONTENT_HASH_VERSION } from "./content-hash.js";
import { addressHeldByOther, addressHeldInTrash, changedSincePlan, notWired, trashedAtDestination } from "./precheck-reasons.js";
import type { PackedEntity, PublishContentContributor, PublishContentDeps, PublishContentHandler, PublishContentReference } from "./type-registry.js";

/**
 * @file Slice F1 of `ADS-memory/.local-artifacts/plan-publish-all-types-2026-09-25.md` (§2): the
 * generic `PublishContentHandler` factory. It owns what every repo-backed handler (post/page, media,
 * menu, redirect) repeats: the trash skip on pack, the second-address and trashed-destination
 * prechecks, the three version (CAS) checks at apply, domain-error-to-row-outcome mapping, and the
 * optional `executeCommand` wrapping with compensating rollback. A type supplies only a config.
 *
 * Imports only `type-registry.ts` TYPES plus the zero-import helpers, the same dependency shape as a
 * hand-written `features/<type>/publish-content.ts`, so a config built on it sits at the same place in
 * the module graph (see `type-registry.ts`'s header for the cycle this avoids).
 */

/** `"transferred"` is packed and hashed; `"provenance"` is packed but not hashed (a value the
 *  destination cannot be made to hold identically); `"local"` never leaves the row. */
export type FieldDisposition = "transferred" | "provenance" | "local";

type ErrorClass = abstract new (...args: never[]) => Error;

/** What {@link RepoPublishTypeConfig.write} and `undo` receive. `existing` is the destination row,
 *  already version-checked. */
export interface RepoWriteContext<Row, Ports> {
  readonly ports: Ports;
  readonly deps: PublishContentDeps;
  readonly workspaceId: string;
  readonly id: string;
  readonly state: Record<string, unknown>;
  readonly existing: Row | null;
  readonly expectedVersion: number | undefined;
  readonly principalId: string;
  /** With `undo`: registers an undo for a side effect of `write` beyond the row (e.g. post's term
   *  assignments). The gateway's rollback runs these, last first, before `restore`/`remove`. */
  readonly onRollback: (undo: () => Promise<void>) => void;
}

/** What `write` may return. `version` is the row's version after the write (the change set's revert
 *  guard when `undo` is set); other fields pass through on `apply()`'s result (media's `blobWritten`). */
export interface RepoWriteResult {
  readonly changeSetId?: string;
  readonly version?: number;
  readonly [extra: string]: unknown;
}

/** One publishable type's config for {@link createRepoPublishHandler} (plan §2.1). */
export interface RepoPublishTypeConfig<Row, Ports> {
  readonly coversTables?: readonly string[];
  readonly coversRoots?: readonly string[];
  readonly entityType: string;
  /** Defaults to 1. */
  readonly schemaVersion?: number;
  /** The type's own write permission: the handler's `permission` and, with `undo`, the command's. */
  readonly permission: string;
  /** The other permissions `write` asks for ({@link PublishContentHandler.alsoAuthorizes}). */
  readonly alsoAuthorizes?: readonly string[];
  /** Types that must apply first. Only references the destination validates at write time. */
  readonly dependsOn?: readonly string[];

  /** `undefined` = not wired on this instance: pack yields nothing, inspect is `null`, precheck
   *  refuses, apply throws. */
  readonly ports: (deps: PublishContentDeps) => Ports | undefined;
  /** The `PublishContentDeps.ports` key the not-wired messages name. Defaults to `entityType`. */
  readonly portsKey?: string;
  readonly list: (ports: Ports, workspaceId: string) => Promise<readonly Row[]>;
  /** Must also return a trashed row, so precheck can refuse it rather than plan a create. */
  readonly find: (ports: Ports, workspaceId: string, id: string) => Promise<Row | null>;
  /** Defaults to `row.id`. */
  readonly idOf?: (row: Row) => string;
  /** Defaults to `row.version`. */
  readonly versionOf?: (row: Row) => number;
  /** Pack filter beyond trash (kind, active status, excluded keys). */
  readonly include?: (row: Row) => boolean;
  /** Pack skips a trashed row; precheck refuses a trashed destination row. */
  readonly isTrashed?: (row: Row) => boolean;
  /** e.g. parent-first for a tree-shaped type. */
  readonly packOrder?: (rows: readonly Row[]) => readonly Row[];

  /** Every field of `Row`, so a new column fails to compile until classified. */
  readonly fields: Record<Extract<keyof Row, string>, FieldDisposition>;
  /** Fields left out of the state while `undefined` (instead of packed as `null`), so a field added
   *  later keeps every existing hash of a row that has no value for it (e.g. `termIds`). */
  readonly omitWhenAbsent?: readonly string[];
  /** Only for a MIGRATED type whose existing `contentHash` must stay byte-identical (plan §7): replaces
   *  the default hash input (the `"transferred"` fields). A new type never sets it. */
  readonly legacyHashState?: (row: Row, packedState: Record<string, unknown>) => Record<string, unknown>;
  /** Defaults to `[]`. */
  readonly requiredBlobs?: (row: Row) => readonly string[];
  /** A better on-screen name than any packed field (`PackedEntity.displayLabel`). Display only:
   *  never hashed or applied. `undefined` leaves the row named from its state. */
  readonly displayLabel?: (row: Row) => string | undefined;

  /** A second unique address (slug, key, name). Precheck refuses when `holder` returns a row with a
   *  different `idOf`. An empty value is not checked. When the address stays held by a trashed row,
   *  `holder` must return that row too (and `isTrashed` say so), or the create collides at apply. */
  readonly address?: {
    readonly field: string;
    readonly holder: (ports: Ports, workspaceId: string, value: string, state: Record<string, unknown>) => Promise<Row | null>;
  };
  /** What a packed entity uses, carried along by a scoped publish ({@link PublishContentHandler.references}). */
  readonly references?: (entity: PackedEntity) => readonly PublishContentReference[];
  /** Type-specific refusals, after the generic ones. Returns a reason or `null`. */
  readonly validate?: (input: { ports: Ports; workspaceId: string; entity: PackedEntity; existing: Row | null }) => Promise<string | null>;

  /** The one write. Throws domain errors, which `errors` maps. Without `undo`, a returned
   *  `changeSetId` is the report's (else the packed id); with `undo`, the gateway's id wins. */
  readonly write: (ctx: RepoWriteContext<Row, Ports>) => Promise<RepoWriteResult | void>;
  /** When set, `write` runs inside `executeCommand` (inverse = the prior row; rollback = `restore`
   *  or, for a create, `remove`). When unset, the domain write keeps its own revision (redirect, menu). */
  readonly undo?: {
    readonly restore: (ctx: RepoWriteContext<Row, Ports>, prior: Row) => Promise<void>;
    readonly remove: (ctx: RepoWriteContext<Row, Ports>) => Promise<void>;
    /** Defaults to `Import <type> '<id>' via publish-content`. `ctx.existing` is not read yet. */
    readonly summary?: (ctx: RepoWriteContext<Row, Ports>) => string | Promise<string>;
  };
  /** `blocked` keeps the error's message; `conflict` wraps it in {@link changedSincePlan}. Anything
   *  else rethrows and aborts the run. `conflict` is matched first, so `blocked` may name a base class
   *  (e.g. Jini's `ToolInputError`) that a conflict class also extends. */
  readonly errors?: { readonly blocked?: readonly ErrorClass[]; readonly conflict?: readonly ErrorClass[] };
  /** Builds every conflict this type reports (the version checks and `errors.conflict`). Defaults to a
   *  plain `PublishContentApplyRowError`; a migrated type may keep its own exported subclass. */
  readonly conflictError?: (message: string) => PublishContentApplyRowError;

  /** Type-specific handler methods, passed through unchanged. */
  readonly extend?: (ctx: { deps: PublishContentDeps; ports: () => Ports | undefined }) => Partial<
    Pick<PublishContentHandler, "planRetire" | "retire" | "referencesTo" | "repointReferences" | "verifyApplied" | "seedHash" | "listSkipped" | "isApplyConflict">
  >;
}

/** For a `write` that calls a domain service which runs its own `executeCommand` (no `undo`): the
 *  gateway deps that service needs, or a loud error naming the missing ones. The apply bag
 *  (`apply-loop.ts`'s `PublishContentApplyDeps`) always carries them. */
export function gatewayDeps(deps: PublishContentDeps, entityType: string) {
  const { clock, idGen, changeSets, authorize, outbox } = deps;
  if (!changeSets || !authorize || !outbox) {
    throw new Error(`publish-content: ${entityType}.apply() requires PublishContentDeps.changeSets/authorize/outbox — wire it from the apply-loop composition root (features/publish-content/apply-loop.ts).`);
  }
  return { clock, idGen, changeSets, authorize, outbox };
}

/** Unwraps a Jini-style `Result`, throwing its error for `errors` to map. */
export function okOrThrow<T>(result: { ok: true; value: T } | { ok: false; error: Error }): T {
  if (!result.ok) throw result.error;
  return result.value;
}

/** Builds a `PublishContentContributor` from a {@link RepoPublishTypeConfig}. */
export function createRepoPublishHandler<Row, Ports>(config: RepoPublishTypeConfig<Row, Ports>): PublishContentContributor {
  const { entityType, permission } = config;
  const portsKey = config.portsKey ?? entityType;
  const schemaVersion = config.schemaVersion ?? 1;
  const dependsOn = config.dependsOn ?? [];
  const idOf = config.idOf ?? ((row: Row) => (row as { id: string }).id);
  const versionOf = config.versionOf ?? ((row: Row) => (row as { version: number }).version);
  const fieldsWhere = (keep: (d: FieldDisposition) => boolean) =>
    Object.entries<FieldDisposition>(config.fields).filter(([, d]) => keep(d)).map(([field]) => field);
  const packedFields = fieldsWhere((d) => d !== "local");
  const hashedFields = fieldsWhere((d) => d === "transferred");

  /** Missing values become `null`, so an unset column and SQL `NULL` pack and hash alike, except an
   *  `omitWhenAbsent` field, which is left out. */
  const omittable = new Set(config.omitWhenAbsent ?? []);
  const pick = (row: Row, fields: readonly string[]) =>
    Object.fromEntries(
      fields
        .filter((field) => !(omittable.has(field) && (row as Record<string, unknown>)[field] === undefined))
        .map((field) => [field, (row as Record<string, unknown>)[field] ?? null])
    );
  const hashOf = (row: Row) =>
    contentHash(entityType, config.legacyHashState ? config.legacyHashState(row, pick(row, packedFields)) : pick(row, hashedFields));

  const conflict = (id: string, detail: string) => {
    const message = changedSincePlan(entityType, id, detail);
    return config.conflictError?.(message) ?? new PublishContentApplyRowError("conflict", message);
  };

  function toRowError(err: unknown, id: string): unknown {
    if (err instanceof PublishContentApplyRowError || !(err instanceof Error)) return err;
    if (config.errors?.conflict?.some((cls) => err instanceof cls)) {
      return conflict(id, err.message);
    }
    if (config.errors?.blocked?.some((cls) => err instanceof cls)) return new PublishContentApplyRowError("blocked", err.message);
    return err;
  }

  function build(deps: PublishContentDeps): PublishContentHandler {
    const ports = () => config.ports(deps);
    const { workspaceId } = deps;

    async function* pack(): AsyncIterable<PackedEntity> {
      const p = ports();
      if (!p) return;
      const rows = (await config.list(p, workspaceId)).filter((row) => !config.isTrashed?.(row) && (config.include?.(row) ?? true));
      for (const row of config.packOrder ? config.packOrder(rows) : rows) {
        const displayLabel = config.displayLabel?.(row);
        yield {
          entityType,
          id: idOf(row),
          schemaVersion,
          contentHash: hashOf(row),
          hashVersion: CONTENT_HASH_VERSION,
          requiredBlobs: config.requiredBlobs?.(row) ?? [],
          state: pick(row, packedFields),
          ...(displayLabel ? { displayLabel } : {}),
        };
      }
    }

    async function inspect(id: string): Promise<{ version: number; hash: string } | null> {
      const p = ports();
      const row = p ? await config.find(p, workspaceId, id) : null;
      return row ? { version: versionOf(row), hash: hashOf(row) } : null;
    }

    async function precheckAddress(
      { entity, p }: { entity: PackedEntity; p: Ports },
      _options: Record<string, never> = {}
    ): Promise<string | null> {
      const { address } = config;
      const value = address ? entity.state[address.field] : undefined;
      if (address && typeof value === "string" && value) {
        const holder = await address.holder(p, workspaceId, value, entity.state);
        if (holder && idOf(holder) !== entity.id) {
          const held = config.isTrashed?.(holder) ? addressHeldInTrash : addressHeldByOther;
          return held(entityType, address.field, value, idOf(holder));
        }
      }
      return null;
    }

    /** Order (plan §2.2): not wired, address held, destination trashed, then `validate`. */
    async function precheck(entity: PackedEntity): Promise<string | null> {
      const p = ports();
      if (!p) return notWired(entityType, entity.id, `${portsKey} port`);
      const addressReason = await precheckAddress({ entity, p });
      if (addressReason !== null) return addressReason;
      const existing = await config.find(p, workspaceId, entity.id);
      if (existing && config.isTrashed?.(existing)) return trashedAtDestination(entityType, entity.id);
      return (await config.validate?.({ ports: p, workspaceId, entity, existing })) ?? null;
    }

    async function apply(input: {
      entity: PackedEntity;
      expectedVersion: number | undefined;
      principalId: string;
      idempotencyKey: string;
    }): Promise<{ changeSetId: string }> {
      const unwired = (what: string) =>
        new Error(`publish-content: ${entityType}.apply() requires ${what} — wire it from the apply-loop composition root (features/publish-content/apply-loop.ts).`);
      const p = ports();
      if (!p) throw unwired(`PublishContentDeps.ports.${portsKey}`);
      const { entity, expectedVersion } = input;
      const rollbacks: Array<() => Promise<void>> = [];
      const ctx = (existing: Row | null): RepoWriteContext<Row, Ports> => ({
        ports: p,
        deps,
        workspaceId,
        id: entity.id,
        state: entity.state,
        existing,
        expectedVersion,
        principalId: input.principalId,
        onRollback: (undo) => void rollbacks.push(undo),
      });

      /** The three CAS failures (plan §2.2 step 2), then the write with its errors mapped. */
      async function write(existing: Row | null): Promise<RepoWriteResult> {
        const found = existing ? versionOf(existing) : null;
        const mismatch =
          expectedVersion === undefined
            ? found !== null && `expected no existing row, found version ${found}`
            : found === null
              ? `expected version ${expectedVersion}, but the row is gone`
              : found !== expectedVersion && `expected version ${expectedVersion}, found version ${found}`;
        if (mismatch) throw conflict(entity.id, mismatch);
        try {
          return (await config.write(ctx(existing))) ?? {};
        } catch (err) {
          throw toRowError(err, entity.id);
        }
      }

      const { undo } = config;
      if (!undo) {
        const written = await write(await config.find(p, workspaceId, entity.id));
        return { ...written, changeSetId: written.changeSetId ?? entity.id };
      }
      const { changeSets, authorize, outbox } = deps;
      if (!changeSets || !authorize || !outbox) throw unwired("PublishContentDeps.changeSets/authorize/outbox");

      let prior: Row | null = null;
      const { result, changeSetId } = await executeCommand<RepoWriteResult>({
        deps: { clock: deps.clock, idGen: deps.idGen, changeSets, outbox, authorize },
        command: {
          workspaceId,
          actor: { id: input.principalId, kind: "user" },
          summary: (await undo.summary?.(ctx(null))) ?? `Import ${entityType} '${entity.id}' via publish-content`,
          permission,
          idempotencyKey: input.idempotencyKey,
        },
        mutation: {
          entityType,
          entityId: entity.id,
          operation: expectedVersion === undefined ? "create" : "update",
          // Read inside the gateway so the CAS check and the inverse are the same, freshest read.
          captureInverse: async () => {
            prior = await config.find(p, workspaceId, entity.id);
            return prior ? ({ ...prior } as unknown as JsonObject) : null;
          },
          execute: () => write(prior),
          captureEntityVersion: ({ result: written }) => written.version ?? null,
          rollback: async () => {
            for (const sideEffect of rollbacks.reverse()) await sideEffect();
            await (prior ? undo.restore(ctx(prior), prior) : undo.remove(ctx(null)));
          },
        },
      });
      return { ...result, changeSetId };
    }

    return {
      entityType,
      schemaVersion,
      permission,
      ...(config.alsoAuthorizes ? { alsoAuthorizes: config.alsoAuthorizes } : {}),
      dependsOn,
      pack,
      inspect,
      precheck,
      apply,
      ...(config.references ? { references: config.references } : {}),
      ...config.extend?.({ deps, ports }),
    };
  }

  return { entityType, dependsOn, build, coversTables: config.coversTables, coversRoots: config.coversRoots };
}

import type { PublishReportRow, PublishRowDisposition } from "./report-rows.js";

/**
 * @file The one display order every list of publishable content uses (owner rule, 2026-09-26):
 * what WILL be published comes first, A–Z; then what can't be published yet, A–Z; then what is
 * already up to date, A–Z.
 *
 * Display only. Nothing here touches what a run writes, the plan it confirms, or the keys a
 * selection is sent back as — callers sort a copy of rows they already derived, never the report
 * the planner returned (which stays in `dependsOn` apply order, see `report-rows.ts`).
 *
 * "A–Z" is by the label the operator reads, compared case-insensitively and locale-aware
 * (`sensitivity: "base"`, `numeric: true`, so "Page 2" sorts before "Page 10").
 */

/** Which band an item sorts into. Lower sorts first. */
export type PublishOrderGroup = "publish" | "blocked" | "current";

const GROUP_RANK: Readonly<Record<PublishOrderGroup, number>> = { publish: 0, blocked: 1, current: 2 };

const GROUP_BY_DISPOSITION: Readonly<Record<PublishRowDisposition, PublishOrderGroup>> = {
  publish: "publish",
  skipped: "blocked",
  unchanged: "current",
};

/** What the comparator needs to know about one item. `tieBreak` only settles two items that read
 *  the same, so the order never depends on the input order. */
export interface PublishOrderKey {
  readonly group: PublishOrderGroup;
  readonly label: string;
  readonly tieBreak?: string;
}

/**
 * A collator for `locale`, falling back to the runtime default when the tag is malformed rather than
 * throwing a `RangeError` into a render.
 *
 * @complexity O(1).
 */
function collatorFor(locale: string | undefined): Intl.Collator {
  const options: Intl.CollatorOptions = { sensitivity: "base", numeric: true };
  try {
    return new Intl.Collator(locale, options);
  } catch {
    return new Intl.Collator(undefined, options);
  }
}

/**
 * The shared comparator: group first, then label A–Z, then `tieBreak`.
 *
 * @complexity O(1) per comparison (plus the label length).
 */
export function publishOrderComparator<T>(
  locale: string | undefined,
  keyOf: (item: T) => PublishOrderKey
): (a: T, b: T) => number {
  const collator = collatorFor(locale);
  return (a, b) => {
    const ka = keyOf(a);
    const kb = keyOf(b);
    const byGroup = GROUP_RANK[ka.group] - GROUP_RANK[kb.group];
    if (byGroup !== 0) return byGroup;
    const byLabel = collator.compare(ka.label, kb.label);
    if (byLabel !== 0) return byLabel;
    const ta = ka.tieBreak ?? "";
    const tb = kb.tieBreak ?? "";
    return ta < tb ? -1 : ta > tb ? 1 : 0;
  };
}

/**
 * The report rows in display order — a sorted copy; `rows` is left as it was.
 *
 * @complexity O(n log n).
 */
export function sortPublishReportRows(
  rows: readonly PublishReportRow[],
  locale: string | undefined
): readonly PublishReportRow[] {
  return [...rows].sort(
    publishOrderComparator<PublishReportRow>(locale, (row) => ({
      group: GROUP_BY_DISPOSITION[row.disposition],
      label: row.entityLabel,
      tieBreak: `${row.entityTypeLabel}\u0000${row.key}`,
    }))
  );
}

import type { PublishContentOutcomeRow, PublishContentReport } from "./contract.js";
import { publishEntityTypeLabel } from "./sections.js";

/**
 * @file Task 11 — turning a `PublishContentReport` into the rows the Publish Content dialog
 * renders, and the counts its primary button is labelled with.
 *
 * ## The one property this file is responsible for
 *
 * Plan §4 task 11: *a conflict row renders its reason and is not selectable for silent apply.*
 *
 * **2026-09-19 (owner-directed): rows a run WOULD write are now selectable; rows it would not are
 * still not.** {@link PublishReportRow.selectable} is derived from the disposition map below and
 * from nothing else, so only `publish` rows can ever carry a checkbox — an `unchanged` or `skipped`
 * row renders no control at all (not a disabled one), which keeps the original property exactly as
 * stated: there is no affordance anywhere in the dialog that could move a skipped row into the set
 * the run writes.
 *
 * Deselection is still **exclusion by construction**, not an apply-time flag: deselecting rows makes
 * the dialog re-plan against a bundle containing only the selected entities (`export-bundle.ts`'s
 * `selectBundleEntities`, reached through `push/plan`'s `selectedEntityKeys`), so a deselected entity
 * is never staged on the destination at all and no code path downstream has to remember to skip it.
 * `forced` (plan §4's seventh outcome, the operator explicitly choosing a conflicted row) is a
 * different feature and still unbuilt; when it lands it lands here, next to `publishRowDisposition`,
 * not as a second copy in `apps/admin`.
 *
 * `appliesOnExecute` is read straight off the planner's own `writes` flag rather than re-derived
 * from `outcome`, so this file cannot disagree with `planner.ts` about what a run does.
 */

/**
 * What the dialog says will happen to one entity.
 *
 * - `publish` — the run writes this row.
 * - `unchanged` — the destination already matches; nothing happens, and that is the expected case.
 * - `skipped` — the run deliberately does not touch this row, and owes the operator a reason.
 */
export type PublishRowDisposition = "publish" | "unchanged" | "skipped";

/** One rendered report row. `key` is stable across re-plans, so React can keep row identity, and it
 *  is byte-identical to `planner.ts`'s own `entityKey(type, id)` — the string a selection is sent
 *  back to the server as. */
export interface PublishReportRow {
  /** Source titles/slugs used by server-side named selection, when available. */
  readonly names?: readonly string[];
  readonly key: string;
  readonly entityType: string;
  /** What the TYPE column reads — a short plain word for every registered handler
   *  (`sections.ts`), or {@link entityType} itself for one this file has not seen yet
   *  (degraded, never blank, same fallback shape as {@link entityLabel}'s own short-id floor). */
  readonly entityTypeLabel: string;
  readonly entityId: string;
  /** Always renderable, never blank: the planner's `entityLabel` when the entity had one, otherwise
   *  a {@link SHORT_ID_LENGTH}-character prefix of the id. A full uuid is never a display value —
   *  the whole column was unreadable while it was one. */
  readonly entityLabel: string;
  /** Whether this row may be deselected before publishing. True for `publish` rows ONLY — an
   *  `unchanged` or `skipped` row is a statement, not an action, and gets no control at all. */
  readonly selectable: boolean;
  readonly outcome: PublishContentOutcomeRow["outcome"];
  readonly disposition: PublishRowDisposition;
  readonly dispositionLabel: string;
  /** Never `null` for a `skipped` row — see {@link MISSING_REASON}. Rewritten for a non-technical
   *  owner by {@link friendlyPublishReason} before it ever reaches this shape; the planner's own raw
   *  wording (ids, "peer", "baseline") never renders. */
  readonly reason: string | null;
  /** The planner's own `writes` flag, carried through unmodified. */
  readonly appliesOnExecute: boolean;
  /**
   * publish-overwrite-live-plan §4/S9 — whether this row may render the "Overwrite on live"
   * checkbox. `true` only for a `skipped` row whose planner `canOverwrite` is `true`: a row the run
   * already writes (an ordinary `publish` disposition, including an already-forced conflict) never
   * gets a SECOND control offering to do the same thing again, and an `unchanged` row has nothing to
   * overwrite. Ticking one re-plans with `overwriteEntityKeys` (`use-publish-content-confirm.hooks.ts`),
   * which is what turns this same row `forced` and moves it out of `skipped` on the next render — the
   * checkbox is never itself what publishes anything.
   */
  readonly overwritable: boolean;
  /** The live row an overwrite of this entity would retire, named for the dialog — the planner's own
   *  `retires.entityLabel`, falling back to a short id the same way {@link entityLabel} does. `null`
   *  when this row retires nothing (every outcome but a resolvable slug clash). */
  readonly retiresLabel: string | null;
  /**
   * `plan-publish-repoint-menus-2026-09-24.md` §2.2/R6 — the live entities (e.g. menus) that still
   * link to this row's {@link retires} holder, named for the dialog the same way {@link retiresLabel}
   * is — the planner's own `referencedBy[].entityLabel`, falling back to a short id. Empty for every
   * row that retires nothing, and for a retire target with no live references at all.
   */
  readonly referencedByLabels: readonly string[];
  /**
   * Owner decision 2026-09-25 — the `entityKey`s of the in-scope pages/posts a carried-along media
   * row was brought along for (`PublishContentOutcomeRowDto.includedFor`). Empty for every other row.
   * A non-empty list makes the row pre-ticked and untickable: never {@link selectable}, but counted as
   * publishing while any of these keys is still ticked ({@link countSelectedPublishing}).
   */
  readonly includedFor: readonly string[];
  /** The dialog's note for a carried-along row — see {@link usedByNoteFor}. `null` on every other
   *  row. English source text; the dialog translates it. */
  readonly usedByNote: string | null;
  /** This update trashes the item on live (`PublishContentOutcomeRowDto.trashes`): labelled
   *  {@link TRASH_ON_LIVE_LABEL} and styled apart from an ordinary publish. */
  readonly trashes: boolean;
}

/** What the counts under the table add up to. */
export interface PublishReportSummary {
  readonly total: number;
  readonly publishing: number;
  readonly unchanged: number;
  readonly skipped: number;
}

/**
 * Stand-in for a `skipped` row whose planner reason is `null`. A skip with a blank cell reads as a
 * rendering bug and leaves the operator with no way to act; a sentence that says the reason is
 * missing is at least honest about which of the two it is.
 */
const MISSING_REASON = "No reason recorded.";

/** The one reason prefix that is already final, operator-facing copy — `file-tree-policy.ts`'s
 *  {@link import("../file-tree-policy.js").wrapTreePolicyReason}. {@link friendlyPublishReason}
 *  must never rewrite it a second time. */
const ALREADY_FINAL_PREFIX = "Can't publish:";

/**
 * One raw-reason pattern this dialog is known to receive, and the owner-facing sentence it becomes.
 * Order matters: {@link friendlyPublishReason} returns the first match, so a narrower pattern (e.g.
 * the two conflict wordings) is listed before anything broader it could also satisfy.
 */
interface ReasonRewrite {
  readonly pattern: RegExp;
  readonly friendly: string;
}

/**
 * The closed set of reason strings `planner.ts` and its registered handlers (`post`, `media`,
 * `redirects`, `navigation`, `theme`, and the `repo-handler.ts` factory types) can currently produce
 * for a `skipped`, `forced` or `blocked` row, each
 * paired with the plain sentence a non-technical owner should read instead. Every raw string here is
 * quoted verbatim (minus the interpolated id/type) from where it is thrown, so this list is the
 * traceable map from "what the code says" to "what the dialog shows" — updating a handler's wording
 * means updating the matching pattern here, not guessing at a new regex blind.
 *
 * publish-content-copy-2026-09-25.md — every entry drops ids, "peer", "baseline" and "entity", and
 * names the available action ("tick Overwrite") only where the row that carries the reason actually
 * offers that control ({@link PublishReportRow.overwritable}).
 */
const REASON_REWRITES: readonly ReasonRewrite[] = [
  {
    pattern: /^no registered publish-content handler for entity type/,
    friendly: "This kind of content can't be published from here yet.",
  },
  {
    // Owner decision 2026-09-25: a push plans ON the live site, so "this instance"/"this destination"
    // in the raw text is LIVE — and the push driver uploads every required file before planning, so
    // a file still absent there is one this site could not send. The old "hasn't finished syncing
    // here yet" named the wrong side.
