/** Matches `file-tree-policy.ts`'s generic `"<title> was not published: <detail>"` wrapping — every
 *  `checkTreeFiles` reason this module has no specific rewrite for yet (a path-shape or deny-list
 *  detail, all of which name a raw relative path). Kept last and generic on purpose: the title is
 *  real information ("Theme: static/basic") worth keeping, the raw path/segment detail after the
 *  colon is not. */
const GENERIC_TREE_WRAP_PATTERN = /^(.+) was not published: .+$/;

/**
 * Owner decision 2026-09-25 — a tree refusal that is about ONE file names that file, the way
 * `file-tree-policy.ts`'s already-final video reason does, instead of the generic "one of its files
 * isn't allowed". Each pattern matches a `wrapTreePolicyReason`-wrapped `checkTreeFiles`/
 * `checkTreePath` detail, quoted from that module, and captures the offending path; only the file's
 * own name is shown. The secret scan's pattern name (and so anything about what matched) is dropped.
 */
interface NamedFileRewrite {
  readonly pattern: RegExp;
  readonly friendly: (fileName: string) => string;
}

const TOO_LARGE = (name: string): string => `Can't publish: a file is too large (${name})`;
const LOOKS_SECRET = (name: string): string => `Can't publish: a file looks like it contains a key or password (${name})`;

const NAMED_FILE_REWRITES: readonly NamedFileRewrite[] = [
  { pattern: /^.+ was not published: "(.+)" is \d+ bytes, larger than the \d+-byte per-file limit$/, friendly: TOO_LARGE },
  {
    pattern:
      /^.+ was not published: "(.+)" (?:looks like it holds a key \(.+\)|looks like an environment file|is a package-manager credential file|is an MCP server configuration file, which can hold secrets|looks like a private SSH key|has a '\.(?:pem|key|p12|pfx)' extension, which is never published)$/,
    friendly: LOOKS_SECRET,
  },
];

/**
 * Rewrites one raw planner/handler reason into the sentence the dialog shows an owner — terse, free
 * of ids and sync-protocol terms ("baseline", "peer", "entity"), and naming the action when the
 * matched cause has one. `file-tree-policy.ts`'s own `"Can't publish: ..."` sentinel is already
 * exactly this (that module's header explains why it alone gets to skip the title wrapper) and is
 * returned unchanged rather than double-translated.
 *
 * Anything matching none of {@link REASON_REWRITES}, {@link NAMED_FILE_REWRITES} or {@link GENERIC_TREE_WRAP_PATTERN} — a future
 * handler's wording this file has not seen yet, or a test fixture that is not real handler text —
 * passes through unchanged rather than being mangled by a guess.
 *
 * @complexity O(1) — a fixed, small number of regex tests against one string.
 */
export function friendlyPublishReason(reason: string): string {
  if (reason.startsWith(ALREADY_FINAL_PREFIX)) return reason;
  for (const { pattern, friendly } of REASON_REWRITES) {
    if (pattern.test(reason)) return friendly;
  }
  for (const { pattern, friendly } of NAMED_FILE_REWRITES) {
    const path = reason.match(pattern)?.[1];
    if (path !== undefined) return friendly(path.slice(path.lastIndexOf("/") + 1));
  }
  const wrapped = reason.match(GENERIC_TREE_WRAP_PATTERN);
  if (wrapped) return `${wrapped[1]} can't be published — one of its files isn't allowed.`;
  return reason;
}

/** How much of an id to show when an entity has no human identifier at all. Eight hex characters is
 *  the git-short-sha convention and stays unique enough to tell two rows apart on one screen, which
 *  is the only job left for an id once the label column is doing the naming. */
const SHORT_ID_LENGTH = 8;

/**
 * The shared fallback behind both {@link displayLabelFor} and {@link retiresLabelFor}: prefer a real
 * label, fall back to a short id prefix, never the full uuid.
 *
 * @complexity O(1).
 */
function labelOrShortId(label: string | null | undefined, id: string): string {
  if (label !== null && label !== undefined && label.trim().length > 0) return label;
  return id.slice(0, SHORT_ID_LENGTH);
}

/**
 * What to print in the entity column. Prefers the planner's own label; falls back to a short id
 * prefix, never the full uuid (`?? null` covers an older peer whose report predates the field).
 *
 * @complexity O(1).
 */
function displayLabelFor(row: PublishContentOutcomeRow): string {
  return labelOrShortId(row.entityLabel, row.entityId);
}

/**
 * What the dialog names the live row an overwrite would retire, or `null` when this row retires
 * nothing. Same fallback as {@link displayLabelFor} — a `RetireTarget` carries its own
 * `entityLabel`/`entityId` pair, not the row's.
 *
 * @complexity O(1).
 */
function retiresLabelFor(row: PublishContentOutcomeRow): string | null {
  const target = row.retires ?? null;
  if (target === null) return null;
  return labelOrShortId(target.entityLabel, target.entityId);
}

/**
 * What the dialog names every live holder still linking to this row's retire target — empty when the
 * row retires nothing, or when nothing live references it. Same fallback as {@link displayLabelFor}
 * and {@link retiresLabelFor}, applied per holder.
 *
 * @complexity O(h) in the row's holder count.
 */
function referencedByLabelsFor(row: PublishContentOutcomeRow): readonly string[] {
  const holders = row.referencedBy ?? [];
  return holders.map((holder) => labelOrShortId(holder.entityLabel, holder.entityId));
}

/**
 * The note a carried-along row shows, named by the types of the rows that use it: pages and/or
 * posts by name, any other mix (a widget region, an entry, ...) generically.
 *
 * @complexity O(k) in the referrer count.
 */
function usedByNoteFor(includedFor: readonly string[]): string | null {
  if (includedFor.length === 0) return null;
  const types = new Set(includedFor.map((key) => key.slice(0, key.indexOf(":"))));
  if ([...types].some((type) => type !== "page" && type !== "post")) return "Used by items you're publishing";
  if (types.has("page") && types.has("post")) return "Used by these pages and posts";
  return types.has("post") ? "Used by these posts" : "Used by these pages";
}

/** The registered `PublishContentHandler.entityType` ids, named for an owner rather than a
 *  developer (`"theme-files"` reads "Theme"), from the one section table (`sections.ts`) the
 *  section buttons also read. An unlisted type falls back to its raw id — degraded, never wrong.
 *  @complexity O(sections). */
function entityTypeLabelFor(entityType: string): string {
  return publishEntityTypeLabel(entityType);
}

const DISPOSITION_BY_OUTCOME: Readonly<Record<PublishContentOutcomeRow["outcome"], PublishRowDisposition>> = {
  created: "publish",
  applied: "publish",
  forced: "publish",
  unchanged: "unchanged",
  conflict: "skipped",
  blocked: "skipped",
};

/** Terse, operator-facing, and specific about *why* — "Skipped" alone sends someone hunting. */
const LABEL_BY_OUTCOME: Readonly<Record<PublishContentOutcomeRow["outcome"], string>> = {
  created: "Will publish — new",
  applied: "Will publish — update",
  forced: "Will publish — overwrite",
  unchanged: "Already up to date",
  conflict: "Skipped",
  blocked: "Skipped",
};

/** The label for a row whose update trashes the item on live. */
const TRASH_ON_LIVE_LABEL = "Will trash on live";

/**
 * Whether the run writes this row, stated as a disposition rather than a boolean so the table can
 * distinguish "nothing to do" from "deliberately not done".
 *
 * @complexity O(1).
 */
export function publishRowDisposition(row: PublishContentOutcomeRow): PublishRowDisposition {
  return DISPOSITION_BY_OUTCOME[row.outcome];
}

/**
 * Shapes a report for rendering. A refused report has no rows by construction (`planner.ts`), so
 * this returns an empty list for one rather than inventing a placeholder — the dialog renders the
 * refusal reason on its own.
 *
 * @complexity O(n) in the report's row count, single pass, no sorting: the planner already emits
 * rows in `dependsOn` apply order and this keeps it. The dialog shows a sorted copy instead
 * (`publish-order.ts`, owner rule 2026-09-26: to publish first, A–Z).
 */
export function toPublishReportRows(report: PublishContentReport): readonly PublishReportRow[] {
  if (report.refused) return [];
  return report.rows.map((row) => {
    const disposition = publishRowDisposition(row);
    const rawReason = disposition === "skipped" ? (row.reason ?? MISSING_REASON) : row.reason;
    const includedFor = row.includedFor ?? [];
    return {
      key: `${row.entityType}:${row.entityId}`,
      entityType: row.entityType,
      entityTypeLabel: entityTypeLabelFor(row.entityType),
      entityId: row.entityId,
      entityLabel: displayLabelFor(row),
      selectable: disposition === "publish" && includedFor.length === 0,
      outcome: row.outcome,
      disposition,
      dispositionLabel: row.trashes === true ? TRASH_ON_LIVE_LABEL : LABEL_BY_OUTCOME[row.outcome],
      reason: rawReason === null ? null : friendlyPublishReason(rawReason),
      appliesOnExecute: row.writes,
      overwritable: disposition === "skipped" && row.canOverwrite === true,
      retiresLabel: retiresLabelFor(row),
      referencedByLabels: referencedByLabelsFor(row),
      includedFor,
      usedByNote: usedByNoteFor(includedFor),
      trashes: row.trashes === true,
    };
  });
}

/**
 * The counts the dialog's primary button and summary line read from.
 *
 * `publishing` counts rows by disposition, not by `appliesOnExecute`: the two agree for every
 * outcome the planner produces, and disagreeing would mean the table said one thing and the button
 * said another. `report-rows.test.ts` pins them together.
 *
 * @complexity O(n), single pass.
 */
export function summarizePublishReport(rows: readonly PublishReportRow[]): PublishReportSummary {
  let publishing = 0;
  let unchanged = 0;
  let skipped = 0;
  for (const row of rows) {
    if (row.disposition === "publish") publishing += 1;
    else if (row.disposition === "unchanged") unchanged += 1;
    else skipped += 1;
  }
  return { total: rows.length, publishing, unchanged, skipped };
}

/**
 * Every row key the operator is allowed to deselect — the dialog's initial "everything is checked"
 * state, its header checkbox's whole reach, and the yardstick for "is this a strict subset?".
 *
 * Exported rather than left as a filter at the call site so all three of those reads apply the same
 * {@link PublishReportRow.selectable} rule; a fourth that spelled it `disposition === "publish"`
 * itself would silently disagree the day a new outcome lands.
 *
 * @complexity O(n), single pass.
 */
export function selectableRowKeys(rows: readonly PublishReportRow[]): readonly string[] {
  return rows.filter((row) => row.selectable).map((row) => row.key);
}

/**
 * Whether this row publishes given the operator's current selection: a selectable row when it is
 * ticked, a carried-along row ({@link PublishReportRow.includedFor}) while any page/post that uses it
 * is ticked — the same rule `push/plan`'s narrowed re-plan applies when it re-derives what to carry.
 *
 * @complexity O(k) in the row's referrer count.
 */
export function rowPublishesWithSelection(row: PublishReportRow, selected: ReadonlySet<string>): boolean {
  if (row.selectable) return selected.has(row.key);
  return row.disposition === "publish" && row.includedFor.some((key) => selected.has(key));
}

/**
 * How many rows this run would actually write given the operator's current selection — the number
 * the primary button commits to out loud.
 *
 * Counts the INTERSECTION rather than `selected.size`: a key left over from a previous plan, or one
 * naming a row that is no longer selectable, must not inflate the promise on the button. A
 * carried-along row counts through {@link rowPublishesWithSelection}.
 *
 * @complexity O(n·k), single pass; `k` is a carried-along row's referrer count.
 */
export function countSelectedPublishing(rows: readonly PublishReportRow[], selected: ReadonlySet<string>): number {
  let count = 0;
  for (const row of rows) if (rowPublishesWithSelection(row, selected)) count += 1;
  return count;
}

import {
  grantAllowsCapability,
  isGrantActive,
  type PublishTrustGrant,
  type PublishingCapability,
} from "./grant.js";
import { verifyPublishSignature } from "./keys.js";

/**
 * @file Zero-setup publishing auth — proof of possession.
 * Design note: `ADS-memory/reports/2026-09-19-publish-zero-setup-auth-design.md`.
 *
 * The source never sends a secret. It proves it holds the private half of a public key the
 * destination was already given (as committed deploy config) by signing a nonce the DESTINATION
 * chose. Four bindings are inside the signed bytes, and each one closes a specific attack:
 *
 * - `nonce` — single-use and short-lived, so a captured response cannot be replayed.
 * - `targetInstallationId` (the audience) — so a response captured by, or produced for, one
 *   destination cannot be presented at another. Note this is belt AND braces: `keys.ts` already
 *   derives a different keypair per destination, so a cross-destination replay fails on the
 *   signature too. Two independent mechanisms, because an audience check is the one a future
 *   refactor is most likely to drop.
 * - `sourceInstallationId` + `generation` — pins which installation and which rotation generation
 *   is claiming to speak, so a valid signature from an old generation cannot be re-labelled as a
 *   new one.
 * - `capabilities` — the caller states what it is asking for and signs it, so the request cannot be
 *   escalated in flight. It is then intersected with the grant, which is the real ceiling.
 *
 * FAIL-CLOSED EVERYWHERE: every rejection below returns a reason string, never a throw and never a
 * partially-verified result. `reason` names the check that failed for the operator's log; it is
 * never returned to the caller, because "expired nonce" vs "unknown nonce" is an oracle.
 */

/** Canonical message format version. Inside the signed bytes, so a future format cannot be swapped
 *  in under a signature made for this one. */
const CHALLENGE_MESSAGE_VERSION = "tovu-publish-challenge-v1";

/** How long an issued nonce stays usable. Long enough for one round trip on a slow link, short
 *  enough that a captured-but-unused nonce is worthless almost immediately. */
export const CHALLENGE_TTL_MS = 60_000;

/** An issued, not-yet-answered challenge. */
export interface PublishChallengeRecord {
  readonly nonce: string;
  readonly targetInstallationId: string;
  readonly issuedAtIso: string;
  readonly expiresAtIso: string;
}

/**
 * Single-use nonce storage.
 *
 * {@link takeOnce} is named to say "consumes" out loud: it MUST delete the record it returns, in
 * the same operation, or replay protection does not exist. A `get`-shaped method would invite a
 * caller to verify first and delete later, which is exactly the window a replay needs.
 */
export interface PublishChallengeStorePort {
  put(record: PublishChallengeRecord): Promise<void>;
  /** Returns the record AND removes it. A second call for the same nonce returns `null`. */
  takeOnce(nonce: string): Promise<PublishChallengeRecord | null>;
}

/** What the source sends back. Every field is attacker-controlled — nothing here is trusted until
 *  the signature over {@link buildChallengeMessage} verifies. */
export interface PublishChallengeResponse {
  readonly nonce: string;
  readonly sourceInstallationId: string;
  readonly generation: number;
  readonly capabilities: readonly string[];
  readonly signatureB64u: string;
}

/**
 * The exact bytes both sides sign and verify.
 *
 * Newline-separated because every field is an identifier, a base64url value, an integer or a
 * comma-joined capability list — none of which can contain a newline — so the encoding is
 * unambiguous and no field can be shifted into another by choosing a clever value. Capabilities are
 * sorted so the two sides cannot disagree about order.
 *
 * @complexity O(n log n) in the capability count (the sort), n ≤ 2.
 */
export function buildChallengeMessage(input: {
  nonce: string;
  targetInstallationId: string;
  sourceInstallationId: string;
  generation: number;
  capabilities: readonly string[];
}): string {
  return [
    CHALLENGE_MESSAGE_VERSION,
    input.nonce,
    input.targetInstallationId,
    input.sourceInstallationId,
    String(input.generation),
    [...input.capabilities].sort().join(","),
  ].join("\n");
}

/**
 * Issues a fresh single-use challenge. Called by the destination, for anyone who asks — issuing a
 * nonce discloses nothing, so this route needs no credential (which is what makes the whole flow
 * possible for a caller that has none yet).
 *
 * @complexity O(1) — one id generation and one store write.
 */
export async function issuePublishChallenge(deps: {
  store: PublishChallengeStorePort;
  clock: { nowIso(): string };
  idGen: { newId(): string };
  targetInstallationId: string;
}): Promise<PublishChallengeRecord> {
  const issuedAtIso = deps.clock.nowIso();
  const record: PublishChallengeRecord = {
    nonce: deps.idGen.newId(),
    targetInstallationId: deps.targetInstallationId,
    issuedAtIso,
    expiresAtIso: new Date(Date.parse(issuedAtIso) + CHALLENGE_TTL_MS).toISOString(),
  };
  await deps.store.put(record);
  return record;
}

/** A verified challenge response: who proved possession, and what they may do. `capabilities` is
 *  the INTERSECTION with the grant, never what the caller asked for. */
export interface VerifiedChallenge {
  readonly sourceInstallationId: string;
  readonly targetInstallationId: string;
  readonly generation: number;
  readonly capabilities: readonly PublishingCapability[];
}

export type ChallengeVerification =
  | { readonly ok: true; readonly verified: VerifiedChallenge }
  | { readonly ok: false; readonly reason: string };

/** @complexity O(1). */
function refuse(reason: string): ChallengeVerification {
  return { ok: false, reason };
}

/**
 * Missing or corrupt expiry (or clock) must fail closed in verification and store cleanup.
 * @returns Whether the record lacks a provably future expiry. No side effects.
 * @complexity O(1).
 */
function isChallengeExpired(input: { record: PublishChallengeRecord; now: number }, _options = {}): boolean {
  return !(Date.parse(input.record.expiresAtIso) > input.now);
}

/**
 * Names why an already-consumed nonce record cannot be answered at `nowIso` — expired, then issued
 * for another destination — or `null`.
 *
 * @complexity O(1).
 */
function issuedRefusal({ issued, nowIso, targetInstallationId }: {
  issued: PublishChallengeRecord;
  nowIso: string;
  targetInstallationId: string;
}, _options = {}): string | null {
  const now = Date.parse(nowIso);
  if (isChallengeExpired({ record: issued, now })) return "nonce has expired";
  if (issued.targetInstallationId !== targetInstallationId) return "nonce was issued for another destination";
  return null;
}

/**
 * Names why `grant` cannot back this response — inactive, then for another installation — or `null`.
 *
 * @complexity O(1).
 */
function grantRefusal({ grant, nowIso, response }: {
  grant: PublishTrustGrant;
  nowIso: string;
  response: PublishChallengeResponse;
}, _options = {}): string | null {
  if (!isGrantActive(grant, nowIso)) return "the publishing grant has expired or been revoked";
  if (response.sourceInstallationId !== grant.sourceInstallationId) {
    return "the response names an installation this grant is not for";
  }
  return null;
}

/**
 * Names why the requested capabilities are refused — none requested, or the FIRST one outside the
 * grant — or `null`.
 *
 * @complexity O(n) in the requested capability count.
 */
function capabilityRefusal({ grant, capabilities }: {
  grant: PublishTrustGrant;
  capabilities: readonly string[];
}, _options = {}): string | null {
  if (!Array.isArray(capabilities) || capabilities.length === 0) return "no capabilities requested";
  // Intersect, do not accept: a caller asking for something the grant does not hold is refused
  // outright rather than quietly narrowed, so a widening attempt is visible in the log.
  for (const capability of capabilities) {
    if (!grantAllowsCapability(grant, capability)) return `'${String(capability)}' is outside this grant`;
  }
  return null;
}

/**
 * Names why the signature is refused — no key for the claimed generation, no signature, or a
 * signature that does not verify over {@link buildChallengeMessage} — or `null`.
 * Verify the signature only after nonce and grant checks pass. No side effects.
 *
 * @complexity O(n) in the grant's key count plus one Ed25519 verification.
 */
function signatureRefusal({ grant, targetInstallationId, response }: {
  grant: PublishTrustGrant;
  targetInstallationId: string;
  response: PublishChallengeResponse;
}, _options = {}): string | null {
  const key = grant.publicKeys.find((candidate) => candidate.generation === response.generation);
  if (!key) return "no accepted public key for the claimed generation";

  if (typeof response.signatureB64u !== "string" || response.signatureB64u === "") {
    return "the response carries no signature";
  }
  const message = buildChallengeMessage({
    nonce: response.nonce,
    targetInstallationId,
    sourceInstallationId: response.sourceInstallationId,
    generation: response.generation,
    capabilities: response.capabilities,
  });
  if (!verifyPublishSignature({ publicKeyB64u: key.publicKeyB64u, message, signatureB64u: response.signatureB64u })) {
    return "signature verification failed";
  }
  return null;
}

/**
 * Verifies a challenge response against a grant.
 *
 * ORDER MATTERS: the nonce is consumed FIRST, before any other check. A nonce spent on a failed
 * attempt is gone — an attacker cannot use a rejected request to keep a nonce alive for another
 * try, and cannot probe which later check would have failed without burning a fresh nonce each
 * time.
 *
 * @returns The verified identity and its capability intersection, or a reason. Never throws.
 * @complexity O(n) in the grant's key count plus one Ed25519 verification.
 */
export async function verifyChallengeResponse(
  deps: { store: PublishChallengeStorePort; clock: { nowIso(): string } },
  input: {
    grant: PublishTrustGrant;
    targetInstallationId: string;
    response: PublishChallengeResponse;
  }
): Promise<ChallengeVerification> {
  const { response, grant } = input;
  if (typeof response?.nonce !== "string" || response.nonce === "") return refuse("no nonce supplied");

  // FIRST, and unconditionally — see this function's doc.
  const issued = await deps.store.takeOnce(response.nonce);
  if (!issued) return refuse("nonce is unknown or was already used");

  // One clock reading: the nonce's TTL and the grant's validity are judged at the same instant.
  const nowIso = deps.clock.nowIso();
  const reason =
    issuedRefusal({ issued, nowIso, targetInstallationId: input.targetInstallationId }) ??
    grantRefusal({ grant, nowIso, response }) ??
    capabilityRefusal({ grant, capabilities: response.capabilities }) ??
    signatureRefusal({ grant, targetInstallationId: input.targetInstallationId, response });
  if (reason !== null) return refuse(reason);

  return {
    ok: true,
    verified: {
      sourceInstallationId: response.sourceInstallationId,
      targetInstallationId: input.targetInstallationId,
      generation: response.generation,
      capabilities: response.capabilities as readonly PublishingCapability[],
    },
  };
}

/**
 * In-memory {@link PublishChallengeStorePort} — the ADR-006 rule-of-two second adapter, and the one
 * a single-process install actually runs on (a nonce outliving a restart is not a requirement:
 * {@link CHALLENGE_TTL_MS} is a minute, and the source simply asks for another).
 *
 * Expired records are swept on write so an unanswered-challenge flood cannot grow the map without
 * bound — the destination issues nonces to unauthenticated callers, so this is a reachable path.
 */
export class InMemoryPublishChallengeStore implements PublishChallengeStorePort {
  private readonly records = new Map<string, PublishChallengeRecord>();

  private readonly clock: { nowIso(): string };
  constructor(clock: { nowIso(): string }) {
    this.clock = clock;
  }

  /** @complexity O(n) in the stored record count (the sweep), bounded by the TTL window. */
  async put(record: PublishChallengeRecord): Promise<void> {
    const now = Date.parse(this.clock.nowIso());
    for (const [nonce, existing] of this.records) {
      if (isChallengeExpired({ record: existing, now })) this.records.delete(nonce);
    }
    this.records.set(record.nonce, record);
  }

  /** @complexity O(1). Deletes as it reads — see {@link PublishChallengeStorePort.takeOnce}. */
  async takeOnce(nonce: string): Promise<PublishChallengeRecord | null> {
    const record = this.records.get(nonce) ?? null;
    if (record) this.records.delete(nonce);
    return record;
  }
}

import { isContainedDeployConfigPath } from "../deployments/index.js";
import { nowIso, type Clock } from "@jini-ai/core/primitives";
import type { KeyringPort } from "#src/features/webhooks/index";

import {
  DEFAULT_PUBLISHING_CAPABILITIES,
  isBackstopEntityType,
  PUBLISH_TRUST_GRANT_VERSION,
  type PublishTrustGrant,
} from "./grant.js";
import { fetchDestinationIdentity, PUBLISH_TRUST_GENERATION, PublishTrustHandshakeError, type DestinationIdentity, type HandshakeClientDeps } from "./handshake-client.js";
import { deriveInstallationId, derivePublishSigningKey } from "./keys.js";
import {
  grantNotAfterFrom,
  type ProvisioningFileIo,
  type ProvisioningTarget,
  type PublishTrustProvisioningPort,
} from "./provisioning.js";

/**
 * @file Zero-setup publishing auth — the one action a person takes: "this site is mine".
 *
 * `provisioning.ts` can write a grant and `handshake-client.ts` can ask a destination who it is;
 * neither knows how to turn "the owner clicked Connect" into a grant. This file is that step, and
 * it is deliberately the ONLY place that composes them, so there is exactly one definition of what
 * connecting means.
 *
 * ## The whole user-visible surface is one confirmation
 *
 * {@link findCandidateDestination} reads the address out of the deploy config the repo already
 * carries, so the common case is a pre-filled "Publish to <site>?" rather than a field to fill in.
 * Everything else — the destination's workspace id, this install's identity, the key, the entity
 * allowlist, the expiry — is derived or asked for. The owner sees none of it and is asked for none
 * of it.
 *
 * ## What connecting does and does not do
 *
 * It writes a public key into committed deploy config, and stops. It cannot deploy (that would need
 * provider credentials on the owner's machine — the dependency this design exists to remove), so
 * the grant takes effect on the next deploy and {@link ConnectedDestination.nextStep} says so in
 * one sentence. Nothing secret is written, displayed, copied or stored: the private half is derived
 * from the site key on demand and never exists between publishes.
 */

/* Deploy-config files a repo may carry, in the order they are consulted for a candidate address.
 *  The vendor paths and their order are declared as plain data by the bundled deploy-config
 *  plugins (`candidatePaths` in `tovu-deploy-configs.json`); core adds only the neutral `app.json`.
 *  Operator repos may commit generated configs; this repo keeps generation inputs in its workflow.
 *
 *  This is a SUGGESTION mechanism, never a trust decision: whatever it finds is shown to the owner
 *  for confirmation and is re-validated as a URL before anything is done with it. That is why a
 *  plain scan is adequate here where a real parser would be required to WRITE one (a provisioning codec) — the
 *  cost of a wrong guess is a pre-filled field the owner corrects, not a misdirected publish. */

/** The deploy-config key naming a deployment's public origin. Already this repo's own convention
 *  for exactly that (`features/origin/configured-origin.ts`); reusing it means a site that has ever
 *  been deployed needs no new setting to be connectable. */
const PUBLIC_URL_KEY = "TOVU_PUBLIC_URL";

/** Matches `TOVU_PUBLIC_URL = "https://…"` / `TOVU_PUBLIC_URL: https://…` / `TOVU_PUBLIC_URL=https://…`
 *  across TOML, YAML and JSON alike, which is why one expression covers every file above. */
const PUBLIC_URL_PATTERN = new RegExp(`${PUBLIC_URL_KEY}\\s*[:=]\\s*["']?(https://[^"'\\s,]+)`);

/**
 * The address to offer the owner, read out of the repo's own deploy config.
 *
 * Deliberately NOT `process.env.TOVU_PUBLIC_URL`: on the machine doing the connecting that names
 * THIS install (usually `localhost`), not the site being published to. The committed config is the
 * one place that names the deployed site, and every install that has ever been deployed has it.
 *
 * @returns The first `https` origin found, or `null` — an install that has never been deployed has
 * no candidate, which is an ordinary empty state and not an error.
 * @complexity O(f · n) for `f` config files of length `n`; f is the number of declared candidate paths.
 */
export async function findCandidateDestination(deps: {
  readonly io: ProvisioningFileIo;
  /** Absolute path for a repo-relative config file. */
  readonly resolvePath: (relative: string) => string;
}, { candidatePaths = ["app.json"] }: { readonly candidatePaths?: readonly string[] } = {}): Promise<string | null> {
  for (const relative of candidatePaths) {
    if (!isContainedDeployConfigPath({ value: relative })) continue;
    const contents = await deps.io.read(deps.resolvePath(relative));
    if (contents === null) continue;
    const found = PUBLIC_URL_PATTERN.exec(contents)?.[1];
    if (found !== undefined) return found;
  }
  return null;
}

export interface ConnectDeps extends HandshakeClientDeps {
  readonly keyring: KeyringPort;
  readonly provisioning: PublishTrustProvisioningPort;
  readonly clock: Clock;
  /** THIS install's workspace — the site key the publishing key is derived from. */
  readonly workspaceId: string;
}

/** What a successful connect produced. No key material and no identifier a person has to keep. */
export interface ConnectedDestination {
  readonly identity: DestinationIdentity;
  /** The normalized address that was connected, and the key-derivation audience. */
  readonly baseUrl: string;
  /** `false` when the config already said exactly this — nothing to commit, nothing to deploy. */
  readonly changed: boolean;
  readonly target: ProvisioningTarget;
  /** The one sentence to show the owner next. */
  readonly nextStep: string;
}

/** Thrown when the grant could not be written. `message` is a sentence for the owner. */
export class PublishTrustConnectError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "PublishTrustConnectError";
  }
}

/**
 * Connects this install to a destination: learn who it is, derive this install's public key for it,
 * and write the grant into the deploy config.
 *
 * Idempotent by construction — `provisioning.connect` merges by source installation id, so running
 * it twice replaces this computer's own entry and leaves every other computer's alone. That is what
 * makes "click it again if you are not sure" a safe instruction to give a non-developer.
 *
 * @param input.entityTypes - What this source may publish, from its own registered publish-content
 * types. An empty list is a grant that can do nothing (`grant.ts`), so a caller that cannot
 * enumerate its types must not call this.
 * @throws {PublishTrustHandshakeError} when the destination cannot be reached or is not a Tovu site.
 * @throws {PublishTrustConnectError} when the deploy config could not be written.
 * @complexity O(1) plus one round trip, two HKDFs, one file read and one file write.
 */
export async function connectDestination(
  deps: ConnectDeps,
  input: { baseUrl: string; entityTypes: readonly string[] }
): Promise<ConnectedDestination> {
  const identity = await fetchDestinationIdentity(deps, input);

  const sourceInstallationId = await deriveInstallationId({ keyring: deps.keyring, workspaceId: deps.workspaceId });
  const signingKey = await derivePublishSigningKey({
    keyring: deps.keyring,
    workspaceId: deps.workspaceId,
    sourceInstallationId,
    // VERBATIM the same string `openPublishSession` signs with later. A grant written against a
    // different spelling of the same site produces a public key that verifies nothing.
    targetOrigin: input.baseUrl,
    generation: PUBLISH_TRUST_GENERATION,
  });

  const grant: PublishTrustGrant = {
    version: PUBLISH_TRUST_GRANT_VERSION,
    sourceInstallationId,
    publicKeys: [{ publicKeyB64u: signingKey.publicKeyB64u, generation: signingKey.generation }],
    // The DESTINATION's workspace, as the destination itself just stated it. This is the value the
    // old flow made a human find and retype, and the reason `/identity` exists.
    workspaceId: identity.workspaceId,
    // Connecting is the ordinary publish path. Backstop trust is reviewed in deploy config.
    entityTypes: input.entityTypes.filter((entityType) => !isBackstopEntityType({ entityType })),
    capabilities: DEFAULT_PUBLISHING_CAPABILITIES,
    notAfter: grantNotAfterFrom(nowIso({ clock: deps.clock })),
  };

  const written = await deps.provisioning.connect({ grant });
  if (!written.ok) throw new PublishTrustConnectError(`This site's publishing settings could not be saved: ${written.reason}`);

  return {
    identity,
    baseUrl: input.baseUrl,
    changed: written.changed,
    target: written.target,
    nextStep: written.changed
      ? written.target.nextStep
      : "This computer was already connected to that site. Nothing to change.",
  };
}

/**
 * Removes this install's grant from the deploy config.
 *
 * The weaker of the two disconnects on purpose: it takes effect on the next deploy. The immediate
 * one is the destination-side deny list (`revocations.ts`), which needs no deploy and wins over any
 * grant. Both exist because they answer different questions — "stop shipping my key in the repo"
 * and "cut this computer off right now".
 *
 * @complexity O(1) plus one HKDF, one file read and one file write.
 */
export async function disconnectDestination(
  deps: Pick<ConnectDeps, "keyring" | "provisioning" | "workspaceId">
): Promise<{ changed: boolean; target: ProvisioningTarget }> {
  const sourceInstallationId = await deriveInstallationId({ keyring: deps.keyring, workspaceId: deps.workspaceId });
  const written = await deps.provisioning.disconnect({ sourceInstallationId });
  if (!written.ok) throw new PublishTrustConnectError(`This site's publishing settings could not be saved: ${written.reason}`);
  return { changed: written.changed, target: written.target };
}

export { PublishTrustHandshakeError };

/**
 * @file Zero-setup publishing auth — provisioning: how a grant reaches the destination.
 * Design note: `ADS-memory/reports/2026-09-19-publish-zero-setup-auth-design.md`.
 *
 * `grant.ts` defines WHAT the destination trusts. This file defines HOW that document gets there,
 * and it is the whole reason the feature needs no key ceremony: a grant is secret-free, so it can
 * travel as **committed deploy config** — a file in the repo, or a plain env var — instead of
 * through a secret store, a vendor CLI, or a human copying a value between two browser tabs.
 *
 * THE VENDOR-NEUTRALITY RULE, and how it is enforced structurally rather than by discipline:
 * there is no provider branch anywhere in this feature. A provider is a {@link ProvisioningCodec} —
 * "where in this file does the value live, and how is it quoted" — handed to the one
 * {@link createFileProvisioning} flow that every adapter shares. A hosting platform's config file is
 * a codec, not an `if`; adding one is a new codec and no change to this file (the committed-JSON
 * codec below is the one shipped today). Nothing here imports a provider SDK, and nothing here shells out; the whole
 * port is `read a file, decode, merge, encode, write a file`, which is why it works identically on
 * a laptop, in CI, and on a machine that has never heard of the provider.
 *
 * TWO READ PATHS THAT MUST NOT BE CONFUSED:
 *
 * - {@link PublishTrustProvisioningPort.readProvisioned} answers "what does the REPO carry" — the
 *   source machine's question, asked before it offers to connect or disconnect.
 * - {@link resolvePublishTrust} answers "what does THIS RUNNING INSTALL see" — the destination's
 *   question, asked once at boot. It consults the env var first and the committed file second, and
 *   that precedence is load-bearing: it is the only way an operator who still has the provider
 *   console but has lost repository access can switch publishing off. See {@link resolvePublishTrust}.
 *
 * FAIL-CLOSED, BUT NEVER BOOT-BLOCKING. A malformed grant document disables publishing and says why;
 * it does not refuse to start the site. A site is not worth taking down over a feature it may not
 * even use, and `state: "invalid"` carries no grants, so the failure mode is "nobody may publish",
 * never "anybody may".
 */

import type { PublishTrustGrant } from "./grant.js";
import { isGrantActive, parsePublishTrustGrant } from "./grant.js";

/** The env var a destination reads at boot. Non-secret by construction — see this file's header. */
export const PUBLISH_TRUST_ENV_VAR = "TOVU_PUBLISH_TRUST";

/** Repo-relative home of the committed grant document for the default (provider-agnostic) adapter.
 *  In the container this is `/workspace/Tovu/deploy/publish-trust.json`: the `Dockerfile`'s
 *  `COPY . .` puts the repo at the runtime `WORKDIR`, so a repo-root-relative path is also the
 *  deployed path. Callers pass an absolute path; this module never guesses one from `cwd`. */
export const PUBLISH_TRUST_CONFIG_PATH = "deploy/publish-trust.json";

/** Most sources one destination may accept. One entry per computer the owner publishes from; a
 *  longer list means provisioning is appending where it should be replacing, which is a bug worth
 *  failing on rather than absorbing. */
export const MAX_PROVISIONED_GRANTS = 8;

/** Bound on the whole document, so a malformed or hostile `TOVU_PUBLISH_TRUST` cannot be a memory
 *  amplifier before `grant.ts`'s own per-field bounds get a chance to apply. Eight maximal grants
 *  are comfortably under this. */
const MAX_DOCUMENT_BYTES = 16_384;

/** How long a freshly written grant stays valid.
 *
 *  Long on purpose. The expiry exists as the LAST-RESORT revocation path for the case where both
 *  deliberate ones are gone (no repository access and no provider console) — not as a renewal
 *  ritual. Every provisioning write re-stamps it, so reconnecting or rotating renews it for free,
 *  and {@link describeConnection} warns {@link RENEWAL_WARNING_DAYS} ahead rather than letting
 *  publishing stop without notice. */
export const GRANT_LIFETIME_DAYS = 365;

/** How far ahead of `notAfter` the source starts saying "renew this on your next deploy". */
export const RENEWAL_WARNING_DAYS = 30;

const MS_PER_DAY = 86_400_000;

// ---------------------------------------------------------------------------
// The document: a LIST of grants, never one
// ---------------------------------------------------------------------------

/**
 * A parsed grant document. Never a partially-valid list: one bad element rejects the document, for
 * the same reason `grant.ts` refuses to repair a grant — a document that degrades into a valid
 * subset hides the fact that something in it was wrong.
 */
export type GrantDocumentParse =
  | { readonly ok: true; readonly grants: readonly PublishTrustGrant[] }
  | { readonly ok: false; readonly reason: string };

/**
 * Parses the serialised grant document.
 *
 * The document is a LIST keyed by `sourceInstallationId`, not a single grant. A single grant object
 * is still accepted, because the design note describes the value that way and an early install may
 * carry one — but a second computer provisioning against a single-grant document must ADD to it,
 * not overwrite it, or connecting a desktop would silently disconnect the laptop.
 *
 * Whitespace-only input is an empty list, not an error: an untouched file and a deliberately
 * emptied one are told apart by {@link resolvePublishTrust}, which knows where the text came from.
 *
 * @returns Every grant in document order, or the reason the document was refused.
 * @complexity O(n²) in the grant count for the duplicate scan, bounded by
 *   {@link MAX_PROVISIONED_GRANTS} — a pairwise scan reads clearer than a set at eight elements.
 */
export function parseGrantDocument(text: string): GrantDocumentParse {
  if (text.length > MAX_DOCUMENT_BYTES) {
    return { ok: false, reason: `grant document exceeds ${MAX_DOCUMENT_BYTES} bytes` };
  }
  if (text.trim().length === 0) return { ok: true, grants: [] };

  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch (error) {
    return { ok: false, reason: `grant document is not valid JSON: ${(error as Error).message}` };
  }

  const entries = Array.isArray(raw) ? raw : [raw];
  if (entries.length > MAX_PROVISIONED_GRANTS) {
    return { ok: false, reason: `grant document holds more than ${MAX_PROVISIONED_GRANTS} grants` };
  }

  const grants: PublishTrustGrant[] = [];
  for (const entry of entries) {
    const parsed = parsePublishTrustGrant(entry);
    if (!parsed.ok) return { ok: false, reason: parsed.reason };
    if (grants.some((g) => g.sourceInstallationId === parsed.grant.sourceInstallationId)) {
      return { ok: false, reason: `grant document repeats source installation ${parsed.grant.sourceInstallationId}` };
    }
    grants.push(parsed.grant);
  }
  return { ok: true, grants };
}

/**
 * Serialises grants for storage.
 *
 * Always writes an array, even for one grant, so the file's shape never changes when a second
 * computer is connected — a committed file whose top-level type flips produces a confusing diff at
 * exactly the moment someone is trying to understand what changed.
 *
 * @param grants - Grants to write, in the order they should appear.
 * @param options - `pretty` produces the indented form a committed file deserves in a git diff;
 *   compact is for codecs that must fit the value on one line (a TOML or dotenv assignment).
 * @complexity O(n) in the grant count.
 */
export function serializeGrantDocument(
  grants: readonly PublishTrustGrant[],
  options: { readonly pretty: boolean }
): string {
  return options.pretty ? `${JSON.stringify(grants, null, 2)}\n` : JSON.stringify(grants);
}

/** Outcome of a list edit. `changed: false` means the write was a no-op and the caller has nothing
 *  to commit — worth saying out loud rather than inviting an empty commit. */
export type GrantListEdit =
  | { readonly ok: true; readonly grants: readonly PublishTrustGrant[]; readonly changed: boolean }
  | { readonly ok: false; readonly reason: string };

/**
 * Merges `incoming` into `existing`, keyed by `sourceInstallationId`.
 *
 * REPLACES the matching source and leaves every other source untouched. Overwriting the whole list
 * would mean connecting a second computer silently revokes the first — the failure this list shape
 * exists to prevent.
 *
 * @complexity O(n) in the existing grant count.
 */
export function mergeGrant(existing: readonly PublishTrustGrant[], incoming: PublishTrustGrant): GrantListEdit {
  const index = existing.findIndex((g) => g.sourceInstallationId === incoming.sourceInstallationId);
  if (index >= 0) {
    const grants = existing.map((g, i) => (i === index ? incoming : g));
    const changed = JSON.stringify(existing[index]) !== JSON.stringify(incoming);
    return { ok: true, grants, changed };
  }
  if (existing.length >= MAX_PROVISIONED_GRANTS) {
    return { ok: false, reason: `this site already accepts ${MAX_PROVISIONED_GRANTS} computers; disconnect one first` };
  }
  return { ok: true, grants: [...existing, incoming], changed: true };
}

/**
 * Removes one source's grant.
 *
 * Removing a source that is not there is a successful no-op with `changed: false`, not an error:
 * the caller asked for a state ("this computer cannot publish here"), and that state already holds.
 *
 * @complexity O(n) in the existing grant count.
 */
export function removeGrant(existing: readonly PublishTrustGrant[], sourceInstallationId: string): GrantListEdit {
  const grants = existing.filter((g) => g.sourceInstallationId !== sourceInstallationId);
  return { ok: true, grants, changed: grants.length !== existing.length };
}

/**
 * The `notAfter` a grant written now should carry.
 *
 * @complexity O(1).
 */
export function grantNotAfterFrom(nowIso: string, options?: { readonly lifetimeDays?: number }): string {
  const days = options?.lifetimeDays ?? GRANT_LIFETIME_DAYS;
  return new Date(Date.parse(nowIso) + days * MS_PER_DAY).toISOString();
}

// ---------------------------------------------------------------------------
// The destination's boot-time read
// ---------------------------------------------------------------------------

export type PublishTrustState = "configured" | "absent" | "revoked" | "invalid";

/** What this running install sees. `grants` is empty unless `state === "configured"`, so a caller
 *  that reads `grants` without checking `state` still fails closed. */
export interface PublishTrustResolution {
  readonly state: PublishTrustState;
  /** Which input the answer came from, for a boot log that can be acted on. */
  readonly origin: "env" | "file" | "none";
  readonly grants: readonly PublishTrustGrant[];
  /** Why, when the state is `invalid`. Always about the DOCUMENT, never about a live credential. */
  readonly reason: string | null;
}

/** The ONLY constructor that puts grants in a resolution, which is what makes "nothing but
 *  `configured` can authorise anything" a property of the type rather than of a guard someone has
 *  to remember to write.
 *  @complexity O(1). */
function configured(origin: "env" | "file", grants: readonly PublishTrustGrant[]): PublishTrustResolution {
  return { state: "configured", origin, grants, reason: null };
}

/** @complexity O(1). */
function withoutGrants(
  state: Exclude<PublishTrustState, "configured">,
  origin: PublishTrustResolution["origin"],
  reason: string | null = null
): PublishTrustResolution {
  return { state, origin, grants: [], reason };
}

/** @complexity O(n) in the document's grant count. */
function resolveText(
  text: string,
  origin: "env" | "file",
  emptyState: Exclude<PublishTrustState, "configured">
): PublishTrustResolution {
  if (text.trim().length === 0) return withoutGrants(emptyState, origin);
  const parsed = parseGrantDocument(text);
  if (!parsed.ok) return withoutGrants("invalid", origin, parsed.reason);
  if (parsed.grants.length === 0) return withoutGrants("revoked", origin);
  return configured(origin, parsed.grants);
}

/**
 * Resolves what this install accepts publishes from, at boot.
 *
 * PRECEDENCE — env over file, and it is deliberate. The committed file is the normal channel: it
 * needs no provider console and survives a provider token being rotated or revoked. The env var
 * exists so that an operator who has the provider console but NOT the repository can still switch
 * publishing off, by setting `TOVU_PUBLISH_TRUST` to an empty value. If the file won ties, that
 * operator would have no kill switch at all. This is the mechanism behind the claim that revoking
 * publishing and revoking provider access are independent in both directions:
 *
 * - Revoke publishing WITHOUT provider access: edit the committed file, commit, deploy.
 * - Revoke publishing WITH ONLY provider access: set the env var empty; it overrides the file.
 * - Revoke PROVIDER access without touching publishing: nothing in this path reads a provider
 *   credential — the inputs are an env value and a file's text — so publishing is unaffected.
 *
 * Pure: the caller does the reading, so the whole precedence rule is testable without a filesystem
 * or a process env.
 *
 * @param input - `envValue` is `undefined` when the variable is unset and `""` when it is set but
 *   empty; those mean different things here and must not be collapsed by the caller. `fileContents`
 *   is `null` when the file does not exist.
 * @complexity O(n) in the document's grant count.
 */
export function resolvePublishTrust(input: {
  readonly envValue: string | undefined;
  readonly fileContents: string | null;
}): PublishTrustResolution {
  if (input.envValue !== undefined) return resolveText(input.envValue, "env", "revoked");
  if (input.fileContents !== null) return resolveText(input.fileContents, "file", "absent");
  return withoutGrants("absent", "none");
}

/**
 * The grant for one source, or `null`.
 *
 * The `state` check guards the MODULE BOUNDARY, not this file's own paths: {@link resolvePublishTrust}
 * already cannot produce grants outside `configured`. It is here because callers — a middleware, a
 * test double — build `PublishTrustResolution` values of their own, and a caller who sets a
 * plausible-looking `state: "invalid"` beside a leftover `grants` array must still be refused.
 *
 * @complexity O(n) in the resolved grant count.
 */
export function findGrantForSource(
  res: PublishTrustResolution,
  sourceInstallationId: string
): PublishTrustGrant | null {
  if (res.state !== "configured") return null;
  return res.grants.find((g) => g.sourceInstallationId === sourceInstallationId) ?? null;
}

/**
 * One plain sentence describing what this site currently accepts — the destination-side empty
 * state, and the reason a fresh install shows a sentence instead of an error code.
 *
 * @complexity O(1).
 */
export function describePublishTrustState(res: PublishTrustResolution): string {
  switch (res.state) {
    case "configured": {
      const n = res.grants.length;
      return `${n} ${n === 1 ? "computer" : "computers"} can publish to this site.`;
    }
    case "revoked":
      return res.origin === "env"
        ? `Publishing to this site is switched off in this deployment's own settings (${PUBLISH_TRUST_ENV_VAR}), which overrides whatever the repository carries.`
        : "Publishing to this site is switched off. No computer is connected.";
    case "invalid":
      return `This site's publishing settings could not be read, so nobody can publish to it. ${res.reason ?? ""}`.trim();
    case "absent":
      return "No computer is connected to this site for publishing yet. Connect one, then deploy — the connection travels with the deploy, and there is nothing to copy.";
  }
}

// ---------------------------------------------------------------------------
// The source's question: is this computer connected to that site?
// ---------------------------------------------------------------------------

export type ConnectionVerdict =
  | "connected"
  | "expiring-soon"
  | "expired"
  | "superseded-key"
  | "not-connected"
  | "unavailable";

export interface ConnectionStatus {
  readonly verdict: ConnectionVerdict;
  /** Plain language, naming the site and the next action. Never an error code. */
  readonly message: string;
}

/** @complexity O(1). */
function daysUntil(iso: string, nowIso: string): number {
  return Math.floor((Date.parse(iso) - Date.parse(nowIso)) / MS_PER_DAY);
}

/**
 * Whether the destination described by `resolution` currently accepts publishes signed by
 * `publicKeyB64u` from `sourceInstallationId`.
 *
 * MATCHES ON THE PUBLIC KEY, NOT THE GENERATION, and that distinction is the whole point. Rotation
 * bumps the generation, but regenerating the site key changes the derived key while leaving the
 * generation alone (`keys.ts`: the key is HKDF over the site key). A grant naming the right
 * generation and the previous key is therefore DEAD, and a generation comparison would report it
 * as current — publishing would fail with the destination insisting it was connected.
 *
 * @complexity O(n) in the grant's public-key count (at most four, per `grant.ts`).
 */
export function describeConnection(input: {
  readonly resolution: PublishTrustResolution;
  readonly sourceInstallationId: string;
  readonly publicKeyB64u: string;
  readonly siteLabel: string;
  readonly nowIso: string;
}): ConnectionStatus {
  const { resolution: res, siteLabel, nowIso } = input;
  if (res.state !== "configured") {
    return { verdict: "unavailable", message: `${siteLabel}: ${describePublishTrustState(res)}` };
  }

  const grant = findGrantForSource(res, input.sourceInstallationId);
  if (grant === null) {
    return {
      verdict: "not-connected",
      message: `${siteLabel} does not recognise this computer yet. Connect it and deploy once — nothing to copy, and no key to keep.`,
    };
  }
  if (!isGrantActive(grant, nowIso)) {
    return {
      verdict: "expired",
      message: `This computer's connection to ${siteLabel} expired on ${grant.notAfter}. Reconnect and deploy to restore it.`,
    };
  }
  if (!grant.publicKeys.some((k) => k.publicKeyB64u === input.publicKeyB64u)) {
    return {
      verdict: "superseded-key",
      message: `${siteLabel} is still carrying an older key for this computer, so it will refuse a publish. This happens after the Site key is regenerated. Reconnect and deploy to finish the change.`,
    };
  }

  const remaining = daysUntil(grant.notAfter, nowIso);
  if (remaining <= RENEWAL_WARNING_DAYS) {
    return {
      verdict: "expiring-soon",
      message: `This computer can publish to ${siteLabel} for ${remaining} more ${remaining === 1 ? "day" : "days"}. Reconnecting and deploying renews it.`,
    };
  }
  return { verdict: "connected", message: `This computer can publish to ${siteLabel}.` };
}

// ---------------------------------------------------------------------------
// The port, and the one flow every adapter shares
// ---------------------------------------------------------------------------

/** Where an adapter puts the grant, in terms an operator can act on. */
export interface ProvisioningTarget {
  /** Stable machine-readable adapter name, e.g. `"committed-json"`. */
  readonly kind: string;
  /** Absolute path of the config file this adapter edits. */
  readonly path: string;
  /** The one sentence to show after a successful write. */
  readonly nextStep: string;
}

/** The file access a provisioning adapter needs, as a seam — so every adapter is testable without
 *  a filesystem, and so nothing in this feature reaches for `node:fs` on its own. */
export interface ProvisioningFileIo {
  /** File contents, or `null` when the file does not exist. */
  read(path: string): Promise<string | null>;
  write(path: string, contents: string): Promise<void>;
}

/** Instrumentation seam for the only I/O this feature performs (Constitution Article VIII). The
 *  composition root decides what a log line is; this module only announces what it did. */
export type ProvisioningEvent =
  | { readonly kind: "read"; readonly target: ProvisioningTarget; readonly grants: number }
  | { readonly kind: "write"; readonly target: ProvisioningTarget; readonly grants: number; readonly changed: boolean }
  | { readonly kind: "error"; readonly target: ProvisioningTarget; readonly reason: string };

export type ProvisionedRead =
  | { readonly ok: true; readonly grants: readonly PublishTrustGrant[] }
  | { readonly ok: false; readonly reason: string };

export type ProvisioningWrite =
  | {
      readonly ok: true;
      readonly grants: readonly PublishTrustGrant[];
      /** `false` when the config already said this — nothing to commit, nothing to deploy. */
      readonly changed: boolean;
      readonly target: ProvisioningTarget;
    }
  | { readonly ok: false; readonly reason: string };

/**
 * Getting a grant into (and out of) the deploy config the destination will boot with.
 *
 * Deliberately NOT a "deploy" port: it edits a file the operator commits, and stops. Provisioning
 * that could deploy on its own would need provider credentials on the developer's machine, which
 * is exactly the dependency this design exists to avoid.
 */
export interface PublishTrustProvisioningPort {
  readonly target: ProvisioningTarget;
  /** What the repo's deploy config carries today. */
  readProvisioned(): Promise<ProvisionedRead>;
  /** Add or replace one source's grant, leaving every other source untouched. */
  connect(input: { readonly grant: PublishTrustGrant }): Promise<ProvisioningWrite>;
  /** Remove one source's grant. */
  disconnect(input: { readonly sourceInstallationId: string }): Promise<ProvisioningWrite>;
}

/**
 * How one provider's config file carries the grant document.
 *
 * This is the ONLY thing that differs between providers, which is why there is no provider branch
 * anywhere above: a codec says where the value lives inside a file and how it is quoted, and
 * {@link createFileProvisioning} does the rest identically for all of them.
 */
export interface ProvisioningCodec {
  readonly kind: string;
  /** Repo-relative conventional path, for callers that have not chosen one. */
  readonly defaultPath: string;
  /** Compact JSON when the format needs the value on a single line. */
  readonly pretty: boolean;
  readonly nextStep: string;
  /** Extract the grant document from the config file's text; `null` when it carries none. */
  decode(fileContents: string | null): string | null;
  /** Put `document` back, preserving everything else in the file. */
  encode(input: { readonly fileContents: string | null; readonly document: string }):
    | { readonly ok: true; readonly contents: string }
    | { readonly ok: false; readonly reason: string };
}

/** The whole grant document IS the file. The provider-agnostic default: a committed JSON file
 *  needs no provider format, no secret store and no console, so it is the one adapter that works
 *  on a bare VPS as readily as on a managed platform. */
export const COMMITTED_JSON_CODEC: ProvisioningCodec = {
  kind: "committed-json",
  defaultPath: PUBLISH_TRUST_CONFIG_PATH,
  pretty: true,
  nextStep: `Commit ${PUBLISH_TRUST_CONFIG_PATH} and deploy. It holds public keys only — there is nothing secret in it.`,
  decode: (fileContents) => fileContents,
  encode: ({ document }) => ({ ok: true, contents: document }),
};

/**
 * Builds a provisioning port over one config file.
 *
 * Every adapter in this feature is this function plus a codec. Keeping the read/decode/parse/edit/
 * encode/write sequence in one place means a provider cannot accidentally get different merge
 * semantics from another — the bug that would show up as "connecting my desktop disconnected my
 * laptop, but only on the hosted server".
 *
 * @param deps - `path` overrides the codec's conventional location; callers pass an absolute path.
 * @complexity O(n) in the provisioned grant count per call; one file read and at most one write.
 */
export function createFileProvisioning(deps: {
  readonly io: ProvisioningFileIo;
  readonly codec: ProvisioningCodec;
  readonly path: string;
  readonly onEvent?: (event: ProvisioningEvent) => void;
}): PublishTrustProvisioningPort {
  const { io, codec, path, onEvent } = deps;
  const target: ProvisioningTarget = { kind: codec.kind, path, nextStep: codec.nextStep };

  const grantsIn = (fileContents: string | null): ProvisionedRead => {
    const parsed = parseGrantDocument(codec.decode(fileContents) ?? "");
    if (!parsed.ok) {
      onEvent?.({ kind: "error", target, reason: parsed.reason });
      return { ok: false, reason: parsed.reason };
    }
    return { ok: true, grants: parsed.grants };
  };

  const readGrants = async (): Promise<ProvisionedRead> => {
    const current = grantsIn(await io.read(path));
    if (current.ok) onEvent?.({ kind: "read", target, grants: current.grants.length });
    return current;
  };

  const applyEdit = async (edit: (grants: readonly PublishTrustGrant[]) => GrantListEdit): Promise<ProvisioningWrite> => {
    // One read, reused for both the parse and the re-encode: reading twice could decode one
    // version of the file and write its edit back into another.
    const fileContents = await io.read(path);
    const current = grantsIn(fileContents);
    if (!current.ok) return current;

    const next = edit(current.grants);
    if (!next.ok) {
      onEvent?.({ kind: "error", target, reason: next.reason });
      return next;
    }
    if (!next.changed) {
      onEvent?.({ kind: "write", target, grants: next.grants.length, changed: false });
      return { ok: true, grants: next.grants, changed: false, target };
    }

    const encoded = codec.encode({
      fileContents,
      document: serializeGrantDocument(next.grants, { pretty: codec.pretty }),
    });
    if (!encoded.ok) {
      onEvent?.({ kind: "error", target, reason: encoded.reason });
      return encoded;
    }
    await io.write(path, encoded.contents);
    onEvent?.({ kind: "write", target, grants: next.grants.length, changed: true });
    return { ok: true, grants: next.grants, changed: true, target };
  };

  return {
    target,
    readProvisioned: readGrants,
    connect: ({ grant }) => applyEdit((grants) => mergeGrant(grants, grant)),
    disconnect: ({ sourceInstallationId }) => applyEdit((grants) => removeGrant(grants, sourceInstallationId)),
  };
}

import type { PublishTrustGrant } from "./grant.js";
import { isGrantActive } from "./grant.js";
import type { PublishTrustResolution } from "./provisioning.js";
import { findGrantForSource } from "./provisioning.js";

/**
 * @file Zero-setup publishing auth — disconnecting a computer, without a deploy.
 *
 * `provisioning.ts` carries GRANTS in committed config, which is what makes the feature need no key
 * ceremony. It also means a grant only changes when someone deploys, and that is not good enough for
 * revocation: "this computer must stop publishing here" cannot wait on a pipeline, a provider
 * console, or whoever happens to push next.
 *
 * So there are two stores, with a deliberate asymmetry:
 *
 * - **Committed config can only GRANT.** It ships inside the image, it is reviewable in a diff, and
 *   it is restored by a redeploy.
 * - **This store can only DENY.** Production persists it in the destination's content database,
 *   is written by the running process, and takes effect on the next request.
 *
 * Deny wins, and a redeploy cannot clear a denial because denials are not in the image. That single
 * property is what makes three separate claims true at once: revocation does not need a deploy,
 * revocation does not need provider access, and a ROLLBACK to an older commit cannot resurrect a
 * computer the owner disconnected — which the committed-config path on its own could not promise.
 *
 * FAIL-CLOSED HERE MEANS THE OPPOSITE OF `provisioning.ts`. An unreadable GRANT document must admit
 * nobody; an unreadable REVOCATION list must also admit nobody. Both stores fail towards "no
 * publishing", which means this one fails towards treating everyone as disconnected — see
 * {@link admitPublish}. Getting that backwards would turn a corrupt file into a bypass.
 *
 * The durable production adapter is deliberately selected by the composition root, over the same
 * `content.db` that holds the site's content. A deployment that loses that database has an obvious
 * content-loss outage; there is no second mount path whose omission can silently reconnect a
 * disconnected computer.
 */

/** Most disconnections one destination keeps. Bounded like every other document in this feature; a
 *  list longer than the machine list it shadows means something is appending in a loop. */
export const MAX_REVOCATIONS = 64;

/** Bound on the stored file, for the same reason the grant document has one. */
const MAX_DOCUMENT_BYTES = 16_384;

const MAX_FIELD_LENGTH = 512;

/** One computer the owner has disconnected from this site. Carries no key material: it names a
 *  source installation and when the owner said no. */
export interface PublishTrustRevocation {
  readonly sourceInstallationId: string;
  /** ISO-8601, for the admin list — "disconnected on the 3rd" is the question people actually ask. */
  readonly revokedAt: string;
  /** Optional plain-words reason, shown back to the owner. Never interpreted. */
  readonly note: string | null;
}

export type RevocationRead =
  | { readonly ok: true; readonly revocations: readonly PublishTrustRevocation[] }
  | { readonly ok: false; readonly reason: string };

export type RevocationWrite =
  | { readonly ok: true; readonly revocations: readonly PublishTrustRevocation[]; readonly changed: boolean }
  | { readonly ok: false; readonly reason: string };

/**
 * Disconnecting and reconnecting a computer at the destination, effective immediately.
 *
 * Reconnecting is deliberately an explicit act rather than something a later publish or deploy can
 * do on its own. A revocation that could lapse by accident is not a revocation.
 * Production has no revocation-file path or environment override: its deny rows live in the site's
 * content database instead, so a missing second mount cannot silently reconnect a computer.
 */
export interface PublishTrustRevocationPort {
  list(): Promise<RevocationRead>;
  revoke(input: {
    readonly sourceInstallationId: string;
    readonly nowIso: string;
    readonly note?: string;
  }): Promise<RevocationWrite>;
  restore(input: { readonly sourceInstallationId: string }): Promise<RevocationWrite>;
}

/** @complexity O(1). */
function isBoundedString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0 && value.length <= MAX_FIELD_LENGTH;
}

/**
 * Parses the stored revocation list.
 *
 * Refuses the whole document on any bad element, like every other parser in this feature — and here
 * the consequence of refusing is that NOBODY publishes, which is the safe direction for a list whose
 * job is to say no.
 *
 * @complexity O(n) in the record count, bounded by {@link MAX_REVOCATIONS}.
 */
export function parseRevocationDocument(text: string): RevocationRead {
  if (text.length > MAX_DOCUMENT_BYTES) return { ok: false, reason: `revocation list exceeds ${MAX_DOCUMENT_BYTES} bytes` };
  if (text.trim().length === 0) return { ok: true, revocations: [] };

  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch (error) {
    return { ok: false, reason: `revocation list is not valid JSON: ${(error as Error).message}` };
  }
  if (!Array.isArray(raw)) return { ok: false, reason: "revocation list must be a JSON array" };
  if (raw.length > MAX_REVOCATIONS) return { ok: false, reason: `revocation list holds more than ${MAX_REVOCATIONS} records` };

  const revocations: PublishTrustRevocation[] = [];
  for (const entry of raw) {
    const revocation = parseRevocationEntry(entry);
    if (typeof revocation === "string") return { ok: false, reason: revocation };
    revocations.push(revocation);
  }
  return { ok: true, revocations };
}

/**
 * Validates one stored record in a fixed order — object, id, date, note — keeping only those three
 * fields; an absent or null note becomes `null`.
 *
 * @returns The record, or a reason string.
 * @complexity O(1) — every string is bounded by `MAX_FIELD_LENGTH`.
 */
function parseRevocationEntry(entry: unknown): PublishTrustRevocation | string {
  if (typeof entry !== "object" || entry === null) return "each revocation must be an object";
  const { sourceInstallationId, revokedAt, note } = entry as Record<string, unknown>;
  if (!isBoundedString(sourceInstallationId)) return "each revocation needs a 'sourceInstallationId'";
  if (!isBoundedString(revokedAt) || Number.isNaN(Date.parse(revokedAt))) {
    return "each revocation needs an ISO-8601 'revokedAt'";
  }
  if (note !== undefined && note !== null && !isBoundedString(note)) {
    return "a revocation 'note' must be a non-empty string when present";
  }
  return { sourceInstallationId, revokedAt, note: typeof note === "string" ? note : null };
}

/**
 * True when `sourceInstallationId` has been disconnected.
 *
 * @complexity O(n) in the record count.
 */
export function isRevoked(revocations: readonly PublishTrustRevocation[], sourceInstallationId: string): boolean {
  return revocations.some((r) => r.sourceInstallationId === sourceInstallationId);
}

// ---------------------------------------------------------------------------
// The one admission decision
// ---------------------------------------------------------------------------

export type AdmissionRefusal =
  | "site-not-configured"
  | "not-connected"
  | "disconnected"
  | "expired"
  | "superseded-key"
  | "revocations-unreadable";

export type PublishAdmission =
  | { readonly allowed: true; readonly grant: PublishTrustGrant }
  | { readonly allowed: false; readonly refusal: AdmissionRefusal; readonly message: string };

/** Ordinary words for each refusal. No key vocabulary, no identifiers, no error codes — the owner is
 *  not a developer and must never be shown one of these as a string like
 *  "no accepted public key for the claimed generation".
 *  @complexity O(1). */
function refusalMessage(refusal: Exclude<AdmissionRefusal, never>, siteLabel: string): string {
  switch (refusal) {
    case "site-not-configured":
      return `${siteLabel} isn't set up to accept published changes yet.`;
    case "not-connected":
      return `${siteLabel} doesn't recognise this computer yet. Connect it once and publishing will work — there's nothing to copy and no key to keep.`;
    case "disconnected":
      return `This computer was disconnected from ${siteLabel}. Reconnect it on ${siteLabel} to publish from here again.`;
    case "expired":
      return `This computer's connection to ${siteLabel} has run out. Reconnect it to carry on publishing.`;
    case "superseded-key":
      return `${siteLabel} is still set up for this computer's previous sign-in. This happens right after the Site key is regenerated — reconnect and deploy once to finish the change.`;
    case "revocations-unreadable":
      return `${siteLabel} can't check which computers are allowed to publish right now, so it isn't accepting changes. This clears once the site is healthy again.`;
  }
}

/**
 * The single question the destination asks on a publish: may THIS computer, presenting THIS key,
 * publish here right now?
 *
 * Composes the two stores with deny winning. Deliberately says nothing about routes: the reachable
 * method+path set is owned by `grant.ts`'s `PUBLISH_TRUST_ROUTES` and must never be carried by a
 * credential, a session, or this decision — a surface that can name its own routes can widen itself.
 *
 * @param input - `revocations` is the ALREADY-READ list, or `null` when the list could not be read.
 *   `null` refuses: a destination that cannot tell whether a computer was disconnected must assume
 *   it was.
 * @returns The grant to authorise against, or a refusal with a sentence fit to show a person.
 * @complexity O(n) in the grant and revocation counts; both are small bounded lists.
 */
export function admitPublish(input: {
  readonly resolution: PublishTrustResolution;
  readonly revocations: readonly PublishTrustRevocation[] | null;
  readonly sourceInstallationId: string;
  readonly publicKeyB64u: string;
  readonly siteLabel: string;
  readonly nowIso: string;
}): PublishAdmission {
  const refuse = (refusal: AdmissionRefusal): PublishAdmission => ({
    allowed: false,
    refusal,
    message: refusalMessage(refusal, input.siteLabel),
  });

  // Deny first, and before anything that could throw or short-circuit: a disconnected computer must
  // be refused even while the grant side of the config is broken or absent.
  if (input.revocations === null) return refuse("revocations-unreadable");
  if (isRevoked(input.revocations, input.sourceInstallationId)) return refuse("disconnected");

  if (input.resolution.state !== "configured") return refuse("site-not-configured");
  const grant = findGrantForSource(input.resolution, input.sourceInstallationId);
  if (grant === null) return refuse("not-connected");
  if (!isGrantActive(grant, input.nowIso)) return refuse("expired");
  if (!grant.publicKeys.some((k) => k.publicKeyB64u === input.publicKeyB64u)) return refuse("superseded-key");

  return { allowed: true, grant };
}

// ---------------------------------------------------------------------------
// The edits the in-memory adapter applies
// ---------------------------------------------------------------------------

/** One whole-list edit for the in-memory adapter. */
type RevocationEdit = (current: readonly PublishTrustRevocation[]) => readonly PublishTrustRevocation[];

/**
 * The revoke edit: append a record unless the computer is already listed, so a repeat disconnect
 * keeps the FIRST timestamp and note.
 *
 * @complexity O(n) in the record count.
 */
function revokeEdit({ sourceInstallationId, nowIso, note }: Parameters<PublishTrustRevocationPort["revoke"]>[0]): RevocationEdit {
  return (current) =>
    isRevoked(current, sourceInstallationId)
      ? current
      : [...current, { sourceInstallationId, revokedAt: nowIso, note: note ?? null }];
}

/** The restore edit: drop every record for the computer. @complexity O(n) in the record count. */
function restoreEdit({ sourceInstallationId }: Parameters<PublishTrustRevocationPort["restore"]>[0]): RevocationEdit {
  return (current) => current.filter((revocation) => revocation.sourceInstallationId !== sourceInstallationId);
}

/**
 * Applies `edit` to `current` under {@link MAX_REVOCATIONS}: the refusal, or the next list and
 * whether it differs from `current`. Pure — the adapter decides whether and where to persist.
 *
 * @complexity O(n) in the record count (the edit and one JSON comparison).
 */
function planEdit({ current, edit }: {
  current: readonly PublishTrustRevocation[];
  edit: RevocationEdit;
}): { ok: false; reason: string } | { ok: true; next: readonly PublishTrustRevocation[]; changed: boolean } {
  const next = edit(current);
  if (next.length > MAX_REVOCATIONS) {
    return { ok: false, reason: `this site already lists ${MAX_REVOCATIONS} disconnected computers` };
  }
  return { ok: true, next, changed: JSON.stringify(next) !== JSON.stringify(current) };
}

/**
 * Hermetic half of the revocation-store rule of two. The running server uses the SQLite adapter;
 * this tiny process-local store lets the filesystem-free composition root keep exercising the same
 * read/write port without manufacturing a pretend database path.
 */
export function createInMemoryRevocations(): PublishTrustRevocationPort {
  let current: readonly PublishTrustRevocation[] = [];

  const list = async (): Promise<RevocationRead> => ({ ok: true, revocations: current });
  const applyEdit = async (edit: RevocationEdit): Promise<RevocationWrite> => {
    const plan = planEdit({ current, edit });
    if (!plan.ok) return plan;
    if (plan.changed) current = plan.next;
    return { ok: true, revocations: current, changed: plan.changed };
  };

  return {
    list,
    revoke: (input) => applyEdit(revokeEdit(input)),
    restore: (input) => applyEdit(restoreEdit(input)),
  };
}

