  siteStatusRepo: SiteStatusPort;
  disclosureWatermarkSource: DisclosureWatermarkSourcePort;
  deepLinkRestorePointLookup: DeepLinkRestorePointLookupPort;
  gatedMutations: { gatewayDeps: GatewayDeps };
}

/**
 * This wiring layer's OWN risk classification, authored from what each handler below actually
 * calls. See `DerivedRiskByToolId` in the kit for why it is independent of the catalog's own
 * `sideEffects` declaration. Neither excluded tool appears here at all, which is itself the
 * strongest of the guards: an unclassified id cannot be wired.
 */
export const recoveryDerivedRisk: DerivedRiskByToolId = new Map<string, AgentToolSideEffect>([
  // -> listRestorePoints (features/database/restore-points.ts, the same repo Database's own list
  //    tool reads): one read.
  ["backup_list_restore_points", "none"],
  // -> dbOps.getCapabilities(): pure, side-effect-free per its own doc comment.
  ["backup_get_capabilities", "none"],
  // -> planRestore (recovery-orchestrator.ts) + gateway.ts's plan() + computeDisclosure(): three
  //    reads composed together, nothing persisted.
  ["backup_plan_restore", "none"],
  // -> dbOps.getCapabilities() + siteStatusRepo.get() + isOperationInFlight() (a lock PEEK, not an
  //    acquire) + resolveDegradedBanner() (pure): all reads.
  ["recovery_get_status", "none"],
  // -> resolveDeepLinkContext (deep-link.ts): one DeepLinkRestorePointLookupPort read; never
  //    mutates the input envelope (see that function's own doc comment).
  ["recovery_resolve_deep_link", "none"],
  // -> gateway confirm() (as the human, after their click) + execute() via buildRestoreHooks,
  //    inside executeRestore's operation lock: swaps the site's data for the restore point's.
  ["backup_execute_restore", "mutates-durable-state"],
]);

const RESTORE_TOOL_ID = "backup_execute_restore";

/** Mirrors `routes/admin/recovery/disclosure.ts`'s own `COVERED_CATEGORIES` constant exactly — that
 * route-local const is not exported, so this is a deliberate, disclosed duplication rather than a
 * reach into a route file's private state. Keep the two in sync if either changes. */
const RECOVERY_DISCLOSURE_COVERED_CATEGORIES = ["posts_pages", "plugin_table"] as const;

const UNWIRED_RECOVERY_TOOL_IDS = new Set([
  // Pre-existing (SPEC-019) catalog entry, deliberately left unwired HERE: this id collides with
  // `features/database/agent-tools.ts`'s own `backup_create_restore_point`, which
  // `buildDatabaseRegistrations` already wires as the canonical tool (ADR-041 §6 names the
  // Database/Storage domain as this permission's "named tool"). Recovery's OWN local
  // `createRestorePoint` (`recovery/restore-points.ts`) never calls `DbOpsPort.captureRestorePoint()`
  // — wiring it here too would silently mint a SECOND, artifact-less restore point under the same
  // tool id, reintroducing the exact "artifactRef silently dropped" defect
  // `database/restore-points.ts`'s own file header records as already fixed. One tool id, one
  // handler, backed by the real snapshot path.
  "backup_create_restore_point",
]);

/** One field's "must be typeof number" check for {@link requireDeepLinkEnvelope} — same rejection
 *  style as the kit's own `requireNumber`, just scoped to a nested envelope field path. */
function requireEnvelopeNumber(value: unknown, fieldPath: string): number {
  if (typeof value !== "number") throw new ToolInputError({ message: `'${fieldPath}' (number) is required` });
  return value;
}

/** One field's "must be typeof string" check for {@link requireDeepLinkEnvelope}. */
function requireEnvelopeString(value: unknown, fieldPath: string): string {
  if (typeof value !== "string") throw new ToolInputError({ message: `'${fieldPath}' (string) is required` });
  return value;
}

/** One field's "must be a string, or explicitly null" check — `ledgerEventId`/`restorePointId`
 *  are the only two nullable fields on the envelope. */
function requireEnvelopeStringOrNull(value: unknown, fieldPath: string): string | null {
  if (value !== null && typeof value !== "string") throw new ToolInputError({ message: `'${fieldPath}' must be a string or null` });
  return value;
}

/**
 * Validates a raw `envelope` value against `recovery_resolve_deep_link`'s published schema and
 * returns it narrowed to `DatabaseContextEnvelope`.
 *
 * Hand-written rather than delegating to `identity/agent-tool-input.ts`'s generic schema
 * interpreter, because this is the only nested-object tool input in the whole wiring layer and that
 * interpreter is flat-only — it cannot express a nested `envelope` object at all.
 *
 * @throws {ToolInputError} Naming the first missing/mistyped field, matching the kit's
 * `requireString`/`requireNumber` rejection style.
 * @complexity O(1) — a fixed number of field checks.
 * @overallScore 100
 */
function requireDeepLinkEnvelope(raw: unknown): DatabaseContextEnvelope {
  const candidate = { value: raw };
  if (!isRecord(candidate)) throw new ToolInputError({ message: "'envelope' (object) is required" });
  const value = candidate.value;

  return {
    v: requireEnvelopeNumber(value.v, "envelope.v"),
    correlationId: requireEnvelopeString(value.correlationId, "envelope.correlationId"),
    siteId: requireEnvelopeString(value.siteId, "envelope.siteId"),
    ledgerEventId: requireEnvelopeStringOrNull(value.ledgerEventId, "envelope.ledgerEventId"),
    restorePointId: requireEnvelopeStringOrNull(value.restorePointId, "envelope.restorePointId"),
    drift: requireEnvelopeString(value.drift, "envelope.drift"),
    intent: requireEnvelopeString(value.intent, "envelope.intent"),
    issuedAt: requireEnvelopeString(value.issuedAt, "envelope.issuedAt"),
  };
}

export function buildRecoveryRegistrations(
  routeDeps: RecoveryToolDeps,
  surfaces: AssistantSurfaceDeps = { surfaceExchanges: createSurfaceExchangeStore({ scheduler: createTimeoutScheduler({}), clock: createSystemClock(), idGenerator: createRandomUuidGenerator(), defaultChannel: "mcp-ui" }) },
): ToolRegistration[] {
  const restoreHooks = (actorId: string, restorePointId: string) =>
    buildRestoreHooks({
      workspaceId: routeDeps.workspaceId,
      actorId,
      restorePointId,
      clock: routeDeps.clock,
      idGen: routeDeps.idGen,
      restorePointsRepo: routeDeps.restorePointsRepo,
      databaseLedgerRepo: routeDeps.databaseLedgerRepo,
      dbOps: routeDeps.dbOps,
      migrationRunsRepo: routeDeps.migrationRunsRepo,
      siteStatus: routeDeps.siteStatusRepo,
    });

  // Plans a restore as the agent and folds in the discarded-write-window disclosure — shared by
  // `backup_plan_restore` and the confirm dialog of `backup_execute_restore`.
  const planRestoreWithDisclosure = async (actorId: string, restorePointId: string) => {
    const result = await planRestore({
      deps: {
        dbOps: {
          getCapabilities: async () => {
            const capabilities = await routeDeps.dbOps.getCapabilities();
            return { costClass: capabilities.restorePoint.costClass, restorePointKind: capabilities.restorePoint.kind };
          },
        },
        gateway: {
          plan: (input) =>
            toRecoveryResult({ run: () =>
              gatewayPlan({
                deps: routeDeps.gatedMutations.gatewayDeps,
                principalId: input.principalId,
                principalKind: input.principalKind,
                hooks: restoreHooks(actorId, input.restorePointId),
              }) }, {},
            ),
        },
      },
      input: { principalId: actorId, principalKind: AGENT_TOOL_PRINCIPAL_KIND, restorePointId },
    });

    if (!result.ok) throw new Error(result.error.message ?? result.error.code);

    const disclosure = await computeDisclosure({
      deps: { watermarkSource: routeDeps.disclosureWatermarkSource, coveredCategories: RECOVERY_DISCLOSURE_COVERED_CATEGORIES },
      input: { restorePointId },
    });
    return { plan: result.value, disclosure };
  };

  const handlers: Record<string, ToolHandler> = {
    backup_list_restore_points: async (ctx) => {
      requireNoInput({ input: ctx.input });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "backup.read" }, { entityType: "restore-point" });
      // Same repo/function Database's own `database_list_restore_points` reads — one persisted
      // list, two gated views (ADR-045 §1, "Database and Recovery are sibling faces").
      return listRestorePoints({ repo: routeDeps.restorePointsRepo });
    },

    backup_get_capabilities: async (ctx) => {
      requireNoInput({ input: ctx.input });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "backup.read" }, { entityType: "restore-point" });
      const capabilities = await routeDeps.dbOps.getCapabilities();
      return { costClass: capabilities.restorePoint.costClass, kind: capabilities.restorePoint.kind,
        fullSiteBackup: {
          discoveryTool: "source_control_get_capabilities", planTool: "site_backup_plan", pushTool: "site_backup_push",
          guidance: "Discover installed source-control hosts, including disabled hosts, before choosing a private repository. Enable the chosen plugin and configure its connection through the secure card. Plan and review the private full-site backup before pushing; rendered static output commits are separate.",
        },
        portableExport: { href: "/admin/sites", guidance: "Admin → Sites → Export creates a portable .tovu.zip." },
      };
    },

    backup_plan_restore: async (ctx) => {
      const restorePointId = requireString({ input: requireInputRecord({ input: ctx.input }), key: "restorePointId" });

      // Defensive, explicit check ahead of `planRestore()`: that function's own cost-class
      // short-circuit (COST_CLASS_UNAVAILABLE) returns BEFORE the gateway's internal authorize()
      // ever runs — a pre-existing gap this wiring found in the real HTTP route too (it calls
      // `planRestore` with no authorize() of its own either). This tool stays strictly more
      // conservative than that route by never skipping the check, rather than reproducing the gap.
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "backup.read" }, { entityType: "restore-point" });

      // An unknown id is a caller mistake, not a planning question — reject it here rather than
      // letting it reach `planRestore()`/the gateway, which have no reason to name a nonexistent
      // restore point in a way that points the caller back to the list tool.
      const points = await routeDeps.restorePointsRepo.list();
      if (!points.some((point) => point.id === restorePointId)) {
        throw new ToolInputError({ message: `restore point '${restorePointId}' was not found — call backup_list_restore_points for valid ids` });
      }

      // Folds in the discarded-write-window disclosure, matching this tool's own catalog
      // description ("including the discarded-write-window disclosure") — the human admin UI reads
      // this from a separate `/recovery/disclosure` request; a tool call composes both in one turn.
      return planRestoreWithDisclosure(ctx.principal.id, restorePointId);
    },

    recovery_get_status: async (ctx) => {
      requireNoInput({ input: ctx.input });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "backup.read" }, { entityType: "restore-point" });

      const capabilities = await routeDeps.dbOps.getCapabilities();
      const siteStatus = await routeDeps.siteStatusRepo.get(routeDeps.workspaceId);
      const banner = resolveDegradedBanner({
        capabilities: {
          costClass: capabilities.restorePoint.costClass,
          operationInFlight: isOperationInFlight({ siteId: routeDeps.workspaceId }, {}),
          pendingMigration: siteStatus === "PENDING_MIGRATION",
          migrationInterrupted: siteStatus === "BLOCKED_PENDING_RECOVERY",
          // Matches `routes/admin/recovery/status.ts`'s own honest stub — no per-category
          // write-count tracker exists anywhere in this codebase yet (see `disclosure.ts`'s doc).
          watermarkBaselineAvailable: false,
        },
      });

      return { costClass: capabilities.restorePoint.costClass, banner };
    },

    recovery_resolve_deep_link: async (ctx) => {
      const candidate = { value: ctx.input };
      if (!isRecord(candidate)) throw new ToolInputError({ message: "'envelope' (object) is required" });
      const envelope = requireDeepLinkEnvelope(candidate.value.envelope);

      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "backup.read" }, { entityType: "restore-point" });

      return resolveDeepLinkContext({
        deps: { lookup: routeDeps.deepLinkRestorePointLookup },
        input: { principalId: ctx.principal.id, principalKind: AGENT_TOOL_PRINCIPAL_KIND, envelope },
      });
    },

    // Plans as the agent, asks the human, then confirms as the human and executes as the agent
    // inside the same operation lock the admin execute route uses. No restore point is taken
    // first, so the dialog says the current data is replaced and it can't be undone. The human's
    // confirm click is the disclosure acknowledgment (CIC U-002).
    [RESTORE_TOOL_ID]: humanConfirmedToolHandler(surfaces, {
      flag: "restored",
      prepare: async (ctx) => {
        const input = requireInputRecord({ input: ctx.input });
        refuseUnexpectedKeys(input, ["restorePointId"]);
        const restorePointId = requireString({ input: input, key: "restorePointId" });
        await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "backup.restore" }, { entityType: "restore-point" });
        const { plan } = await planRestoreWithDisclosure(ctx.principal.id, restorePointId);
        const { items } = await listRestorePoints({ repo: routeDeps.restorePointsRepo });
        const createdAt = items.find((item) => item.id === restorePointId)?.createdAt;
        return { restorePointId, plan: plan as { planId: string; planHash: string }, createdAt };
      },
      dialog: ({ restorePointId, createdAt }) => ({
        toolId: RESTORE_TOOL_ID,
        errorCode: "RECOVERY",
        title: "Restore the site's data?",
        details: [{ label: "Restore point", value: createdAt ? `${restorePointId} (${createdAt})` : restorePointId }],
        warning:
          "Your current data will be replaced with this restore point. Anything changed since then is lost. " +
          "No restore point is taken first, so this can't be undone.",
        danger: true,
        confirmLabel: "Replace current data",
      }),
      run: async (ctx, { restorePointId, plan }, confirmer) => {
        const hooks = restoreHooks(ctx.principal.id, restorePointId);
        const confirmed = await confirmRestore({
          deps: {
            gateway: {
              confirm: (params) =>
                toRecoveryResult({ run: async () => {
                  const record = await gatewayConfirm({
                    deps: routeDeps.gatedMutations.gatewayDeps,
                    principalId: confirmer.id,
                    principalKind: confirmer.kind,
                    hooks,
                    planId: params.planId,
                    planHash: params.planHash,
                  });
                  return { confirmationToken: record.confirmationToken };
                } }, {}),
            },
          },
          input: { principalId: confirmer.id, principalKind: confirmer.kind, planId: plan.planId, planHash: plan.planHash, disclosureAcknowledged: true },
        });
        if (!confirmed.ok) throw new Error(confirmed.error.message ?? confirmed.error.code);
        const { confirmationToken } = confirmed.value as { confirmationToken: string };

        const executed = await executeRestore({
          deps: {
            gateway: {
              execute: (params) =>
                toRecoveryResult({ run: () =>
                  gatewayExecute({
                    deps: routeDeps.gatedMutations.gatewayDeps,
                    principalId: ctx.principal.id,
                    principalKind: AGENT_TOOL_PRINCIPAL_KIND,
                    hooks,
                    confirmationToken: params.confirmationToken,
                  }) }, {},
                ),
            },
            operationLock: { acquireOperationLock, releaseOperationLock },
            clock: routeDeps.clock,
          },
          input: {
            principalId: ctx.principal.id,
            principalKind: AGENT_TOOL_PRINCIPAL_KIND,
            confirmationToken,
            siteId: routeDeps.workspaceId,
            delegatedByPrincipalId: confirmer.id,
          },
        });
        if (!executed.ok) throw new Error(executed.error.message ?? executed.error.code);
        return { restored: true, ...executed.value };
      },
    }),
  };

  return buildDomainRegistrations({ metadata: toolMetadata, domain: "recovery", catalogModule: "features/recovery/agent-tools.ts", catalog: CATALOG_BY_ID, handlers, derivedRisk: recoveryDerivedRisk }, { unwiredToolIds: UNWIRED_RECOVERY_TOOL_IDS });
}

/**
 * Contributes Recovery's AI tools to the assistant's catalog — called once by
 * `server/tool-catalog-manifest.ts`'s `installFirstPartyToolContributors()`, not by importing this
 * module. `assistant/tool-registrations.ts` no longer imports `buildRecoveryRegistrations`/
 * `recoveryDerivedRisk` by name; this is the seam that replaced it (2026-08-17, Stage 2 batch 2).
 * Unlike `database` (tried and reverted earlier in this same batch — see
 * `features/database/tool-registrations.ts`'s trailing comment), Recovery's only imports of
 * `features/database` (`../database/boot/reconcile-interrupted-migration`, `../database/gated-hooks`)
 * are both `import type` — erased from the runtime-only graph `check:architecture` uses for module
 * cycles/SCC — so this domain does not carry `database`'s `db`-hub round-trip risk.
 */
export function contributeRecoveryTools(): ToolContributor {
  return { domain: "recovery", build: buildRecoveryRegistrations, risk: recoveryDerivedRisk };
}

import { MAX_IMPORT_BATCH_SIZE, MAX_PRIORITY, MAX_TARGET_LENGTH, MIN_PRIORITY, MIN_TARGET_LENGTH, VALID_STATUS_CODES } from "@jini-ai/cms/redirects";
import { REDIRECT_MATCH_TYPES, REDIRECT_SOURCES, REDIRECT_STATUSES } from "@jini-ai/cms/redirects";

/**
 * @file The Redirects domain's agent-tool catalog, instantiating SPEC-016 REQ-22's
 * naming/callability convention (the same shape `features/workspace/agent-tools.ts`,
 * `newsletter/agent-tools.ts`, and every other domain catalog already use).
 *
 * Purpose:
 * A static, in-process catalog describing every agent-callable tool this domain exposes. Every
 * entry maps 1:1 onto a real admin HTTP route already exposed to a human operator
 * (`server/routes/admin/redirects/*.ts`) — this catalog never names an operation the admin UI does
 * not already perform.
 *
 * 2026-09-24 (tool-design audit F2/F3, dispatch item 3): `redirects_import` is now wired. It was
 * previously withheld as "a mass, immediate site-behavior change with no per-item human review
 * step" — but every rule still routes through the identical `createRedirect` chokepoint a single
 * `redirects_create` call uses (no validation bypassed at scale), each import row is reversible the
 * same way a single created rule is (`redirects_update`/`redirects_tombstone`), and a per-rule
 * failure never aborts the batch (`importRedirects`'s own `created`/`failed` split, EC-08) — the
 * same risk envelope as `redirects_create`/`redirects_update`, just N rows instead of one. It is not
 * a destructive/publish action, so the owner 2026-10-07 policy leaves ordinary creation/import
 * unconfirmed, same as `redirects_create`; `redirects_tombstone` separately requires approval.
 *
 * `redirects_create`/`redirects_update` both accept `override` (a rule that preempts already-live
 * content resolution rather than only filling a 404). This is real, meaningful behavior — but it is
 * gated by the exact same `admin.redirects.manage` permission as every other write here (the
 * codebase enforces no separate, stronger gate for `override:true` today), it targets exactly one
 * named rule per call, and it is always reversible (`redirects_update`/`redirects_tombstone` can
 * undo it). That keeps it inside this catalog's ordinary single-record CRUD risk envelope rather
 * than warranting its own exclusion.
 *
 * How it relates to the project:
 * The server-side tool filter (ADR-014) consumes this catalog to decide which tool names an agent
 * session may even see; `authorize()` (ADR-021 §2) enforces the actual permission checks at call
 * time — this module only declares the catalog shape, it performs no I/O and no enforcement itself.
 *
 * Architectural role:
 * `redirects` domain logic. Imports only the constants its own domain already enforces
 * (Jini `packages/cms/src/redirects/redirects.ts`'s length/priority/status-code/batch-size bounds), so the published JSON Schemas
 * cannot drift from the validators — same discipline `seo/agent-tools.ts` uses for
 * `write-service.ts`'s constants.
 */

export type AgentToolSideEffect = "none" | "mutates-durable-state" | "mints-token";

export interface AgentToolDefinition {
  name: string;
  description: string;
  sideEffects: AgentToolSideEffect;
  authorization: { permission: string };
  /**
   * JSON Schema for this tool's `input`, published via `ToolDescriptor.inputSchema`
   * (`assistant/tool-registration-kit.ts`'s `buildDomainRegistrations`, which refuses to wire any
   * tool lacking one). Optional, matching `features/database/agent-tools.ts`'s convention for a
   * domain entry that IS deliberately excluded and so carries no schema at all — every entry in
   * this domain's own catalog is wired, so every entry here declares one.
   */
  inputSchema?: Readonly<Record<string, unknown>>;
}

const REDIRECT_ID_PROPERTY = {
  type: "string",
  minLength: 1,
  description: "A redirect rule's id, as returned by redirects_create or content_read.redirect.",
} as const;

const REDIRECT_ID_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["id"],
  properties: { id: REDIRECT_ID_PROPERTY },
} as const;

const MATCH_TYPE_PROPERTY = {
  type: "string",
  enum: ["exact", "prefix", "wildcard", "regex"],
  description:
    "How fromPattern is matched. 'exact': full-path equality. 'prefix': longest-prefix match. 'wildcard': glob with '*' captures. 'regex' is a valid value but is ALWAYS rejected by this write chokepoint today (gated behind a currently-off feature flag) — expect a validation error if you pass it.",
} as const;

const STATUS_CODE_PROPERTY = {
  type: "integer",
  enum: [...VALID_STATUS_CODES],
  description: "HTTP redirect status. 301/308 are permanent; 302/307 are temporary. 307/308 preserve the request method/body.",
} as const;

const TO_TARGET_PROPERTY = {
  type: "string",
  minLength: MIN_TARGET_LENGTH,
  maxLength: MAX_TARGET_LENGTH,
  description: `The destination: a site-relative path, or an absolute URL. An absolute target must resolve against this workspace's redirect-target allowlist; a site-relative target must stay on this site and must not resolve onto '/admin' or '/api' (the authenticated admin application, not public pages) — either way the write is refused. ${MIN_TARGET_LENGTH}-${MAX_TARGET_LENGTH} characters.`,
} as const;

const PRIORITY_PROPERTY = {
  type: "integer",
  minimum: MIN_PRIORITY,
  maximum: MAX_PRIORITY,
  description: `Tie-breaker within an equal-specificity band — higher wins. ${MIN_PRIORITY}-${MAX_PRIORITY}. Omit to default to ${MIN_PRIORITY}.`,
} as const;

const OVERRIDE_PROPERTY = {
  type: "boolean",
  description:
    "When true, this rule is consulted BEFORE live content resolution (it can redirect away from an already-published URL). Defaults to false, meaning the rule only fills the 404 path.",
} as const;

const LIST_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: [],
  properties: {
    status: { type: "string", enum: [...REDIRECT_STATUSES], description: "Filter to rules in exactly this status. Omit to list every status." },
    source: {
      type: "string",
      enum: [...REDIRECT_SOURCES],
      description: "Filter to rules with exactly this provenance. Omit to list every source.",
    },
    matchType: { type: "string", enum: [...REDIRECT_MATCH_TYPES], description: "Filter to rules of exactly this match type. Omit to list every match type." },
  },
} as const;

const CREATE_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["matchType", "fromPattern", "toTarget", "statusCode"],
  properties: {
    matchType: MATCH_TYPE_PROPERTY,
    fromPattern: { type: "string", minLength: 1, description: "The source path/pattern to match against incoming requests. Its decoded first segment cannot be 'admin' or 'api' (case-insensitive)." },
    toTarget: TO_TARGET_PROPERTY,
    statusCode: STATUS_CODE_PROPERTY,
    override: OVERRIDE_PROPERTY,
    priority: PRIORITY_PROPERTY,
  },
} as const;

const IMPORT_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["rules"],
  properties: {
    rules: {
      type: "array",
      minItems: 1,
      maxItems: MAX_IMPORT_BATCH_SIZE,
      description: `1-${MAX_IMPORT_BATCH_SIZE} redirect rules to create. Each rule is validated and written through the identical chokepoint a single redirects_create call uses (own pattern/target-allowlist/duplicate/cycle checks); one invalid rule does not abort the rest of the batch — check the response's 'failed' list.`,
      items: CREATE_SCHEMA,
    },
  },
} as const;

const UPDATE_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["id"],
  properties: {
    id: REDIRECT_ID_PROPERTY,
    matchType: MATCH_TYPE_PROPERTY,
    fromPattern: { type: "string", minLength: 1, description: "The source path/pattern to match against incoming requests. Its decoded first segment cannot be 'admin' or 'api' (case-insensitive). Omit to leave unchanged." },
    toTarget: { ...TO_TARGET_PROPERTY, description: `${TO_TARGET_PROPERTY.description} Omit to leave unchanged.` },
    statusCode: STATUS_CODE_PROPERTY,
    status: {
      type: "string",
      enum: ["active", "disabled"],
      description:
        "'disabled' turns the rule off; 'active' turns it back on (on a rule in the Trash this restores it). To delete a rule, use redirects_tombstone, which moves it to the Trash. A rule in the Trash can't be edited until it is restored.",
    },
    override: OVERRIDE_PROPERTY,
    priority: PRIORITY_PROPERTY,
  },
} as const;

/**
 * The Redirects domain's fixed agent-tool catalog (SPEC-009) — see this file's header for the one
 * withheld operation and why.
 *
 * @complexity O(1) — a fixed, statically-defined list.
 * @overallScore 100
 */
export function getRedirectsAgentToolCatalog(): AgentToolDefinition[] {
  return [
    {
      name: "redirects_list",
      description: "Lists the workspace's redirect rules, optionally filtered by status/source/matchType. Rules in the Trash (removed with redirects_tombstone) are not listed; 'disabled' rules here are ones switched off, not removed. Read-only.",
      sideEffects: "none",
      authorization: { permission: "admin.redirects.manage" },
      inputSchema: LIST_SCHEMA,
    },
    {
      name: "redirects_get",
      description: "Fetches a single redirect rule by id. Read-only.",
      sideEffects: "none",
      authorization: { permission: "admin.redirects.manage" },
      inputSchema: REDIRECT_ID_SCHEMA,
    },
    {
      name: "redirects_get_hits",
      description: "Fetches aggregate hit stats (total hit count, last-hit time) for a redirect rule by id. Read-only. Returns hitCount:0 if the rule has never been hit.",
      sideEffects: "none",
      authorization: { permission: "admin.redirects.manage" },
      inputSchema: REDIRECT_ID_SCHEMA,
    },
    {
      name: "redirects_create",
      description:
        "Creates a new manual redirect rule. Rejects an unsafe/disallowed absolute target, collapses a one-hop chain onto an existing active rule's own target, and rejects a resulting cycle. Rejects a duplicate exact-match rule for the same fromPattern.",
      sideEffects: "mutates-durable-state",
      authorization: { permission: "admin.redirects.manage" },
      inputSchema: CREATE_SCHEMA,
    },
    {
      name: "redirects_update",
      description: "Edits one or more fields on an existing redirect rule. Only provided fields change; omitted fields keep their current value. Same validation as redirects_create.",
      sideEffects: "mutates-durable-state",
      authorization: { permission: "admin.redirects.manage" },
      inputSchema: UPDATE_SCHEMA,
    },
    {
      name: "redirects_tombstone",
      description: "Removes a redirect rule by moving it to the Trash: it stops matching and leaves the redirect rule list (only the Trash shows it). Works on an active or a switched-off rule. Restore it from the Trash, or with redirects_update status 'active'. Idempotent: removing a rule already in the Trash is a no-op.",
      sideEffects: "mutates-durable-state",
      authorization: { permission: "admin.redirects.manage" },
      inputSchema: REDIRECT_ID_SCHEMA,
    },
    {
      name: "redirects_import",
      description:
        `Creates up to ${MAX_IMPORT_BATCH_SIZE} redirect rules in one call. Each rule gets the identical validation a single redirects_create call gets (pattern/target-allowlist/duplicate/cycle checks); a per-rule failure is reported in 'failed' and does not abort the rest of the batch.`,
      sideEffects: "mutates-durable-state",
      authorization: { permission: "admin.redirects.manage" },
      inputSchema: IMPORT_SCHEMA,
    },
  ];
}

import { toolMetadata } from '../../contracts/core/tool-metadata/redirects.js';
import { adaptLegacyAuthorize } from "@jini-ai/cms/core";
/**
 * @file Redirects' half of ADR-049 Decision 4 (SPEC-009): maps `agent-tools.ts`'s 7 catalog entries
 * onto the list/get/hits/create/update/tombstone/import operations `server/routes/admin/
 * redirects/*.ts` expose, as `ToolRegistration`s. All 7 are wired (2026-09-24: `redirects_import`
 * joined the other 6 — see `agent-tools.ts`'s own file header for why).
 *
 * Authorization shape: none of `createRedirect`/`updateRedirect`/`tombstoneRedirect`
 * (Jini `packages/cms/src/redirects/redirects.ts`) accept an `authorize` dependency at all — `RedirectsWriteDeps` has no such field,
 * so the chokepoint itself never gates. Every admin route therefore calls `authorize()` inline as
 * its own first line, and every handler below does the same via the kit's `requireToolPermission`,
 * mirroring those routes' identical check (ADR-021 §2's single evaluator, located at the handler
 * here rather than inside the domain function).
 */
import { buildDomainRegistrations, indexCatalogById, isRecord, optionalBoolean, optionalNumber, optionalOneOf, optionalString, requireInputRecord, requireNumber, requireString, type AgentToolSideEffect, type DerivedRiskByToolId, type ToolHandler, type ToolRegistration } from "@jini-ai/core";
import { type AuthorizeFn, requireToolPermission } from "@jini-ai/cms/core";
import { ToolInputError } from "@jini-ai/core";
import { ForbiddenError } from "@jini-ai/cms/core";
import { withModelFacingErrors } from "@jini-ai/core/model-facing-tool-errors";
import type { ToolContributor } from "#src/assistant/index";
import { forbiddenRule, type ModelFacingErrorRule } from "@jini-ai/core/model-facing-tool-errors";
import { createSurfaceExchangeStore, type AssistantSurfaceDeps } from "@jini-ai/daemon/surface-exchanges";
import { getRedirectsAgentToolCatalog } from "./agent-tools.js";
import type { RedirectHitSink, RedirectRepoPort } from "@jini-ai/cms/redirects";
import { createRedirect, importRedirects, listRedirects, tombstoneRedirect, updateRedirect, MAX_IMPORT_BATCH_SIZE, type RedirectsWriteDeps } from "@jini-ai/cms/redirects";
import { REDIRECT_MATCH_TYPES, REDIRECT_SOURCES, REDIRECT_STATUSES, RedirectConflictError, RedirectLoopError, RedirectNotFoundError, RedirectTargetNotAllowedError, RedirectValidationError } from "@jini-ai/cms/redirects";
import type { CreateRedirectInput, RedirectMatchType, RedirectRecord, RedirectStatus, RedirectStatusCode } from "@jini-ai/cms/redirects";
import { createSystemClock, createRandomUuidGenerator } from "@jini-ai/core/primitives";
import { createTimeoutScheduler } from "@jini-ai/daemon/scheduler";


const CATALOG_BY_ID = indexCatalogById({ catalog: getRedirectsAgentToolCatalog() });

/**
 * The exact slice of the route-deps bag Redirects' tool handlers read. Declared structurally
 * (rather than importing `server/routes/types`'s `RouteDeps`) so this module carries no back-edge
 * into the composition root. `server/routes/*` satisfies this structurally by passing its existing
 * `RouteDeps` object; nothing there changes.
 */
export interface RedirectsToolDeps {
  authorize: AuthorizeFn;
  workspaceId: string;
  redirectRepo: RedirectRepoPort;
  redirectHitSink: RedirectHitSink;
  redirectsWriteDeps: RedirectsWriteDeps;
}

/** Model-facing redirect-rule view — drops `workspaceId` (redundant: every call is already scoped
 * to the caller's own workspace) and the actor/lineage-attribution internals
 * (`createdByPrincipal`/`createdByPluginId`/`sourceEntryId`/`fromPathAtCapture`/`toPathAtCapture`)
 * that no wired tool's follow-up call consumes — mirrors `newsletter/tool-registrations.ts`'s
 * `toCampaignToolView`'s identical reasoning for dropping actor attribution. */
function toRedirectToolView(record: RedirectRecord) {
  return {
    id: record.id,
    matchType: record.matchType,
    fromPattern: record.fromPattern,
    toTarget: record.toTarget,
    statusCode: record.statusCode,
    status: record.status,
    override: record.override,
    priority: record.priority,
    source: record.source,
    createdAt: record.createdAt,
    updatedAt: record.updatedAt,
    version: record.version,
  };
}

const REDIRECTS_TOMBSTONE_TOOL_ID = "redirects_tombstone";

/** See `trash/trash-item-tool.ts`'s identical constant's doc — duplicated here rather than
 *  imported, the same "structurally typed, no `features/trash` import" convention this domain's
 *  `TombstoneRedirectRequired.input.pluginId` already follows. */
const ASSISTANT_ACTOR_PLUGIN_ID = "assistant";

/**
 * This wiring layer's OWN risk classification, authored from what each handler below actually
 * calls. See `DerivedRiskByToolId` in the kit for why it is independent of the catalog's own
 * `sideEffects` declaration.
 */
export const redirectsDerivedRisk: DerivedRiskByToolId = new Map<string, AgentToolSideEffect>([
  // -> listRedirects (redirectRepo.list() minus rules in the Trash): read only.
  ["redirects_list", "none"],
  // -> redirectRepo.findById(): read only.
  ["redirects_get", "none"],
  // -> redirectRepo.findById() + redirectHitSink.getStats(): read only.
  ["redirects_get_hits", "none"],
  // -> createRedirect (redirects.ts): validate -> write record + revision in one tx -> enqueue event.
  ["redirects_create", "mutates-durable-state"],
  // -> updateRedirect (redirects.ts): same write shape as create.
  ["redirects_update", "mutates-durable-state"],
  // -> tombstoneRedirect (redirects.ts): moves the rule to the Trash — status flip + Trash row +
  //    revision write (no-op if already in the Trash).
  ["redirects_tombstone", "mutates-durable-state"],
  // -> importRedirects (redirects.ts): createRedirect in a loop, one call each — same write shape
  //    as redirects_create, N times, with a per-item try/catch (EC-08).
  ["redirects_import", "mutates-durable-state"],
]);

/**
 * Redirects' model-facing allowlist (wm S16, 2026-10-04). Every `Redirect*Error` and the kit's
 * `ForbiddenError` extend plain `Error`, so before this wrap `ToolExecutor` classified each refusal
 * as `internal` and the model saw only a redacted INTERNAL_ERROR — it could not tell "that id does
 * not exist" or "that would loop" from a crash, and could not correct its call.
 *
 * Message safety, checked against every construction site in Jini `packages/cms/src/redirects/{redirects,matcher}.ts`/this
 * file: each message is fixed text plus the caller's own input (id, pattern, target, numbers) or a
 * fixed `siteRelativeTargetReason`/`siteRelativeRefusalReason` phrase — no paths, SQL, or other
 * tenants' data. `RedirectTargetNotAllowedError` names only the caller's `toTarget` and a fixed
 * reason. `EntityNotLiveError` (a trashed rule) is not listed: it already extends `ToolInputError`.
 * The plain `Error` for a missing Trash adapter is deliberately NOT listed: it is a wiring fault and
 * stays redacted.
 */
const REDIRECTS_MODEL_FACING_RULES: readonly ModelFacingErrorRule[] = [
  forbiddenRule({ domainPrefix: "REDIRECTS", error: ForbiddenError }),
  { error: RedirectNotFoundError, code: "REDIRECTS_NOT_FOUND" },
  { error: RedirectValidationError, code: "REDIRECTS_VALIDATION" },
  { error: RedirectLoopError, code: "REDIRECTS_LOOP" },
  { error: RedirectTargetNotAllowedError, code: "REDIRECTS_TARGET_NOT_ALLOWED" },
  { error: RedirectConflictError, code: "REDIRECTS_CONFLICT" },
];

export function buildRedirectsRegistrations(
  routeDeps: RedirectsToolDeps,
  surfaces: AssistantSurfaceDeps = { surfaceExchanges: createSurfaceExchangeStore({ scheduler: createTimeoutScheduler({}), clock: createSystemClock(), idGenerator: createRandomUuidGenerator(), defaultChannel: "mcp-ui" }) },
): ToolRegistration[] {
  const handlers: Record<string, ToolHandler> = {
    redirects_list: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.redirects.manage" }, { entityType: "redirect" });

      // Rules in the Trash are left out (Bug B) — the same list the admin Redirects screen shows.
      const rules = await listRedirects({
        deps: { repo: routeDeps.redirectRepo, isInTrash: routeDeps.redirectsWriteDeps.isInTrash },
        filter: {
          workspaceId: routeDeps.workspaceId,
          status: optionalOneOf({ input, key: "status", values: REDIRECT_STATUSES }),
          source: optionalOneOf({ input, key: "source", values: REDIRECT_SOURCES }),
          matchType: optionalOneOf({ input, key: "matchType", values: REDIRECT_MATCH_TYPES }),
        },
      });
      return { rules: rules.map(toRedirectToolView) };
    },

    redirects_get: async (ctx) => {
      const id = requireString({ input: requireInputRecord({ input: ctx.input }), key: "id" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.redirects.manage" }, { entityType: "redirect", entityId: id });

      const rule = await routeDeps.redirectRepo.findById({ workspaceId: routeDeps.workspaceId, id });
      if (!rule) throw new RedirectNotFoundError(`redirect '${id}' was not found`);
      return { rule: toRedirectToolView(rule) };
    },

    redirects_get_hits: async (ctx) => {
      const id = requireString({ input: requireInputRecord({ input: ctx.input }), key: "id" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.redirects.manage" }, { entityType: "redirect", entityId: id });

      const rule = await routeDeps.redirectRepo.findById({ workspaceId: routeDeps.workspaceId, id });
      if (!rule) throw new RedirectNotFoundError(`redirect '${id}' was not found`);

      const stats = await routeDeps.redirectHitSink.getStats({ workspaceId: routeDeps.workspaceId, redirectId: id });
      return { stats: stats ?? { redirectId: id, workspaceId: routeDeps.workspaceId, hitCount: 0, lastHitAt: undefined } };
    },

    redirects_create: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.redirects.manage" }, { entityType: "redirect" });

      const { record } = await createRedirect({
        deps: routeDeps.redirectsWriteDeps,
        input: {
          workspaceId: routeDeps.workspaceId,
          matchType: requireString({ input: input, key: "matchType" }) as RedirectMatchType,
          fromPattern: requireString({ input: input, key: "fromPattern" }),
          toTarget: requireString({ input: input, key: "toTarget" }),
          statusCode: requireNumber({ input: input, key: "statusCode" }) as RedirectStatusCode,
          override: optionalBoolean({ input: input, key: "override" }),
          priority: optionalNumber({ input: input, key: "priority" }),
          actorId: ctx.principal.id,
        },
      });
      return { rule: toRedirectToolView(record) };
    },

    redirects_update: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      const id = requireString({ input: input, key: "id" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.redirects.manage" }, { entityType: "redirect", entityId: id });

      const { record } = await updateRedirect({
        deps: routeDeps.redirectsWriteDeps,
        input: {
          workspaceId: routeDeps.workspaceId,
          id,
          matchType: optionalString({ input: input, key: "matchType" }) as RedirectMatchType | undefined,
          fromPattern: optionalString({ input: input, key: "fromPattern" }),
          toTarget: optionalString({ input: input, key: "toTarget" }),
          statusCode: optionalNumber({ input: input, key: "statusCode" }) as RedirectStatusCode | undefined,
          status: optionalString({ input: input, key: "status" }) as RedirectStatus | undefined,
          override: optionalBoolean({ input: input, key: "override" }),
          priority: optionalNumber({ input: input, key: "priority" }),
          actorId: ctx.principal.id,
        },
      });
      return { rule: toRedirectToolView(record) };
    },

    /** Moves the redirect to the Trash after authorization; removing one already there is a no-op. */
    redirects_tombstone: async (ctx) => {
      const id = requireString({ input: requireInputRecord({ input: ctx.input }), key: "id" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.redirects.manage" }, { entityType: "redirect", entityId: id });

      const rule = await routeDeps.redirectRepo.findById({ workspaceId: routeDeps.workspaceId, id });
      if (!rule) throw new RedirectNotFoundError(`redirect '${id}' was not found`);

      const { record } = await tombstoneRedirect({
        deps: routeDeps.redirectsWriteDeps,
        input: { workspaceId: routeDeps.workspaceId, id, actorId: ctx.principal.id, pluginId: ASSISTANT_ACTOR_PLUGIN_ID },
      });
      return { tombstoned: true, cancelled: false, rule: toRedirectToolView(record) };

    },

    // Wired 2026-09-24 (tool-design audit F2/F3, dispatch item 3) — see `agent-tools.ts`'s file
    // header for why the earlier "mass autonomous change" exclusion no longer holds. No confirmation
    // gate: same reversible, single-chokepoint risk envelope as `redirects_create`, just N rows.
    redirects_import: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.redirects.manage" }, { entityType: "redirect" });

      if (!Array.isArray(input.rules) || input.rules.length < 1 || input.rules.length > MAX_IMPORT_BATCH_SIZE) {
        throw new ToolInputError({ message: `'rules' (array of 1-${MAX_IMPORT_BATCH_SIZE} items) is required` });
      }

      const rules: CreateRedirectInput[] = input.rules.map((raw, index) => {
        const candidate = { value: raw };
        if (!isRecord(candidate)) throw new ToolInputError({ message: `rules[${index}] must be an object` });
        const rule = candidate.value;
        return {
          workspaceId: routeDeps.workspaceId,
          matchType: requireString({ input: rule, key: "matchType" }) as RedirectMatchType,
          fromPattern: requireString({ input: rule, key: "fromPattern" }),
          toTarget: requireString({ input: rule, key: "toTarget" }),
          statusCode: requireNumber({ input: rule, key: "statusCode" }) as RedirectStatusCode,
          override: optionalBoolean({ input: rule, key: "override" }),
          priority: optionalNumber({ input: rule, key: "priority" }),
          actorId: ctx.principal.id,
        };
      });

      const { created, failed } = await importRedirects({
        deps: routeDeps.redirectsWriteDeps,
        input: { workspaceId: routeDeps.workspaceId, actorId: ctx.principal.id, rules },
      });
      return { created: created.map(toRedirectToolView), failed };
    },
  };

  return buildDomainRegistrations({ metadata: toolMetadata,
    domain: "redirects",
    catalogModule: "redirects/agent-tools.ts",
    catalog: CATALOG_BY_ID,
    handlers: withModelFacingErrors({ handlers, rules: REDIRECTS_MODEL_FACING_RULES }),
    derivedRisk: redirectsDerivedRisk,
  });
}

/**
 * Contributes Redirects' AI tools to the assistant's catalog — called once by
 * `server/tool-catalog-manifest.ts`'s `installFirstPartyToolContributors()`, not by importing this
 * module. `assistant/tool-registrations.ts` no longer imports `buildRedirectsRegistrations`/
 * `redirectsDerivedRisk` by name; this is the seam that replaced it (2026-08-17, Stage 2 of the
 * rollout — no sibling domain still statically wired through `assistant` imports `redirects`, so this
 * one-directional `redirects -> assistant` call closes no new cycle).
 */
export function contributeRedirectsTools(): ToolContributor {
  return { domain: "redirects", build: buildRedirectsRegistrations, risk: redirectsDerivedRisk };
}

import { OG_TYPE_VALUES, STRING_FIELD_MAX_LENGTH, TWITTER_CARD_VALUES, URL_FIELD_MAX_LENGTH } from "@jini-ai/cms/seo";
import {
  DEFAULT_DESCRIPTION_MAX_LENGTH,
  DEFAULT_OG_IMAGE_MAX_LENGTH,
  MAX_ROBOTS_RULES,
  MAX_RULE_PATH_ENTRIES,
  TITLE_TEMPLATE_MAX_LENGTH,
  TWITTER_SITE_MAX_LENGTH,
} from "./settings.js";

/**
 * @file The SEO domain's agent-tool catalog, instantiating SPEC-016 REQ-22's naming/callability
 * convention (the same shape `features/workspace/agent-tools.ts`, `newsletter/agent-tools.ts`, and
 * every other domain catalog already use).
 *
 * Purpose:
 * A static, in-process catalog describing every agent-callable tool this domain exposes. Every
 * entry maps 1:1 onto a real admin HTTP route already exposed to a human operator
 * (`server/routes/admin/seo/*.ts`) — this catalog never names an operation the admin UI does not
 * already perform.
 *
 * All 6 admin SEO routes are wired; there is no deliberate exclusion in this domain (unlike
 * Workspace/Settings/Recovery, which each withhold at least one entry). Read the full route
 * surface first: `get-entry.ts`/`get-entry-analyze.ts` (reads), `put-entry.ts` (per-entry override
 * write), `get-settings.ts`/`put-settings.ts` (site-wide settings read/write), and
 * `post-sitemap-regenerate.ts` (forces a sitemap cache rebuild). None of the 6 is bulk (each call
 * targets exactly one entry or the single workspace-level settings row — the same "narrow, single-
 * row write" class as `workspace_update`), none is irreversible (`seo_set_entry_overrides` can
 * always be re-called to change or clear a field; `seo_set_settings` is likewise a re-appliable
 * patch; `seo_regenerate_sitemap` only recomputes a cache from already-durable data, it cannot lose
 * anything), and none is credential-adjacent. So every entry is wired.
 *
 * `seo_regenerate_sitemap`'s `sideEffects` is declared `'mutates-durable-state'` even though
 * `sitemap.ts`'s cache is an in-process `Map`, not a SQL row: `regenerateSitemapCache` forces a
 * real, observable state transition — the next public `/sitemap.xml`/`/robots.txt` read reflects
 * the recomputed entries — so classifying it `'none'` (as a pure read) would understate what the
 * tool actually does. `'mutates-durable-state'` is the closest of this catalog's 3-value vocabulary
 * to "has a real, persisted-for-the-process-lifetime effect other reads depend on," which is a
 * closer match than either `'none'` or `'mints-token'`.
 *
 * `seo_set_entry_overrides` and `seo_set_settings` publish JSON Schemas built from the SAME
 * exported constants (`STRING_FIELD_MAX_LENGTH`/`URL_FIELD_MAX_LENGTH`/`OG_TYPE_VALUES`/
 * `TWITTER_CARD_VALUES` from `write-service.ts`; `TITLE_TEMPLATE_MAX_LENGTH`/
 * `DEFAULT_DESCRIPTION_MAX_LENGTH`/`DEFAULT_OG_IMAGE_MAX_LENGTH`/`MAX_ROBOTS_RULES`/
 * `MAX_RULE_PATH_ENTRIES` from `settings.ts`) their respective chokepoints (`setEntrySeoOverrides`/
 * `setSeoSettings`) actually validate against — those constants were previously module-private;
 * this dispatch adds `export` to each (no value changes) so the published schema cannot silently
 * drift from the validator, the same discipline `newsletter/agent-tools.ts` uses for
 * `campaign-write-service.ts`'s `SUBJECT_MAX`/`SUBJECT_MIN`/`PREHEADER_MAX`.
 *
 * How it relates to the project:
 * The server-side tool filter (ADR-014) consumes this catalog to decide which tool names an agent
 * session may even see; `authorize()` (ADR-021 §2) enforces the actual permission checks at call
 * time — this module only declares the catalog shape, it performs no I/O and no enforcement itself.
 *
 * Architectural role:
 * `seo` domain logic. Imports only the constants its own domain already enforces (`write-service.ts`/
 * `settings.ts`), so the published JSON Schemas cannot drift from the single sources of those
 * values, rather than restating either.
 */

export type AgentToolSideEffect = "none" | "mutates-durable-state" | "mints-token";

export interface AgentToolDefinition {
  name: string;
  description: string;
  sideEffects: AgentToolSideEffect;
  authorization: { permission: string };
  /**
   * JSON Schema for this tool's `input`, published to the model via `ToolDescriptor.inputSchema`
   * (`assistant/tool-registration-kit.ts`'s `buildDomainRegistrations`, which refuses to wire any
   * tool lacking one). Every entry in this catalog is wired, so this is required, not optional —
   * mirrors `identity/agent-tools.ts`'s identical reasoning.
   */
  inputSchema: Readonly<Record<string, unknown>>;
}

/** No arguments. */
const NO_INPUT_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: [],
  properties: {},
} as const;

const ENTRY_ID_PROPERTY = {
  type: "string",
  minLength: 1,
  description: "The entry's id (a post or page), as returned by other tools that list or return entries.",
} as const;

