import type { FormDeliveryBinding } from "@jini-ai/cms/forms";
import { ensureSettingDefinitions, getEffective, SCOPE_BIT, ValueValidationFailedError, type EnsureSettingDefinitionsDeps, type SetValueRequired, type SettingsRepoPort } from "@jini-ai/core/settings";

/**
 * @file The two site settings behind durable form delivery, on the existing settings ledger:
 * `core.forms/deliveryBindings` (which destinations receive each new submission) and
 * `core.forms/autoPull` (whether the serving app pulls static-site submissions on its own).
 *
 * A binding names an adapter (a form destination id) and a connection by reference only. The
 * secret behind `connectionRef` is resolved fresh on each delivery attempt and never copied into
 * the setting or the delivery job, which is why `config` refuses anything shaped like a secret.
 * Delivery copies what it sends: deleting a submission or a binding here later does NOT remove
 * copies a destination already received.
 *
 * Validation lives in one pure function, {@link parseFormDeliveryBindings}, used when the setting
 * is read for planning and by the host settings chokepoint (`site-title-write.ts`) through
 * {@link enforceFormDeliveryBindingsWrite}, which every write goes through: the typed write a later
 * admin or plugin UI calls (`form-delivery-write.ts`), the generic settings route and the tools. So
 * none of them can store a list planning would refuse, or a secret in `config`.
 */

const NAMESPACE = "core.forms";
const BINDINGS_KEY = "deliveryBindings";
const AUTO_PULL_KEY = "autoPull";

/** Caps that keep planning O(bindings × formIds) small and bounded per submission. */
const MAX_FORM_DELIVERY_BINDINGS = 100;
const MAX_FORM_DELIVERY_FORM_IDS = 1000;
const MAX_REFERENCE_LENGTH = 256;

const BINDING_FIELDS: ReadonlySet<string> = new Set(["bindingId", "adapterId", "connectionRef", "enabled", "formIds", "config"]);
/** Matched against a config key lowercased with separators removed (`api_key`, `API-Key` → `apikey`).
 *  `auth` and `pwd` match only as the whole key, so `author` or `authorName` stay usable. */
const SECRET_KEY = /token|secret|password|passphrase|apikey|privatekey|accesskey|credential|authorization|^auth$|^pwd$/;
/** Values that are credentials whatever their key is called: a Bearer Authorization header value, a
 *  JWT, a PEM private key, a URL carrying `user:pass@`. HTTP Basic is {@link isBasicCredential}. */
const SECRET_VALUES: readonly RegExp[] = [/^\s*bearer\s+\S/i, /\beyJ[\w-]+\.eyJ[\w-]+\./, /-----BEGIN [A-Z ]*PRIVATE KEY-----/, /\b[a-z][\w+.-]*:\/\/[^\s/@:]+:[^\s/@]+@/i];
const BASIC_VALUE = /^\s*basic\s+([A-Za-z0-9+/]+={0,2})\s*$/i;
const FIX_HINT = "Save the secret as a connection and point to it with connectionRef; config holds non-secret settings only.";

/**
 * Registers both definitions without replacing an owner's stored values. Delivery bindings default
 * to none; automatic pull defaults to ON (owner decision 2026-10-20).
 * @complexity O(1), two definitions.
 */
export function ensureFormDeliverySettings(
  required: { deps: EnsureSettingDefinitionsDeps; systemPrincipalId: string },
  _optional: Record<string, never> = {},
): Promise<void> {
  return ensureSettingDefinitions(required.deps, { namespace: NAMESPACE, systemPrincipalId: required.systemPrincipalId, definitions: [
    { key: BINDINGS_KEY, schema: { type: "json" }, defaultValue: [], scopes: SCOPE_BIT.workspace },
    { key: AUTO_PULL_KEY, schema: { type: "boolean" }, defaultValue: true, scopes: SCOPE_BIT.workspace },
  ] });
}

/**
 * Whether automatic pulls run for this site. Read fresh at every trigger; only an explicit
 * `false` turns them off, so an unregistered definition keeps the ON default.
 * @complexity One effective setting read.
 */
export async function readFormsAutoPull(
  required: { settingsRepo: SettingsRepoPort; workspaceId: string },
  _optional: Record<string, never> = {},
): Promise<boolean> {
  const found = await getEffective({ repo: required.settingsRepo }, { namespace: NAMESPACE, key: AUTO_PULL_KEY, scopeContext: { workspaceId: required.workspaceId } });
  return found?.value !== false;
}

/**
 * The site's validated bindings, read fresh when a submission is planned.
 * @throws ValueValidationFailedError when the stored value breaks a rule (the planning event then
 *   retries, so a fixed setting takes effect without losing the submission).
 * @complexity One effective read plus {@link parseFormDeliveryBindings}.
 */
export async function readFormDeliveryBindings(
  required: { settingsRepo: SettingsRepoPort; workspaceId: string },
  _optional: Record<string, never> = {},
): Promise<FormDeliveryBinding[]> {
  const found = await getEffective({ repo: required.settingsRepo }, { namespace: NAMESPACE, key: BINDINGS_KEY, scopeContext: { workspaceId: required.workspaceId } });
  return parseFormDeliveryBindings({ value: found?.value ?? [] });
}

/**
 * One settings write: a `core.forms.deliveryBindings` value is checked against every binding rule;
 * any other setting passes through unchanged. Pure. The value is stored as written: for JSON input
 * the parsed bindings hold exactly the same fields and values (unknown fields are refused, not
 * dropped), so there is no cleaned form to substitute.
 * @throws ValueValidationFailedError for any rule {@link parseFormDeliveryBindings} enforces.
 * @complexity {@link parseFormDeliveryBindings} for this setting, O(1) otherwise.
 */
export function enforceFormDeliveryBindingsWrite(input: SetValueRequired["input"]): SetValueRequired["input"] {
  if (input.namespace === NAMESPACE && input.key === BINDINGS_KEY) parseFormDeliveryBindings({ value: input.value });
  return input;
}

/**
 * Pure validator: returns fresh, cleaned binding objects or throws naming the first rule broken.
 * Rules: a list of at most {@link MAX_FORM_DELIVERY_BINDINGS}; each binding has only the known
 * fields, non-empty bounded `bindingId`/`adapterId`/`connectionRef`, a boolean `enabled`, optional
 * `formIds` (at most {@link MAX_FORM_DELIVERY_FORM_IDS}; absent = every form, `[]` = none), an
 * object `config` with no secret-shaped key or value at any depth, and a `bindingId` no other
 * binding uses (the job index is unique per submission and binding, so a duplicate would abort
 * the whole delivery plan). Messages never repeat a config value.
 * @throws ValueValidationFailedError
 * @complexity O(bindings × (formIds + config size)).
 */
export function parseFormDeliveryBindings(required: { value: unknown }, _optional: Record<string, never> = {}): FormDeliveryBinding[] {
  const { value } = required;
  if (!Array.isArray(value)) throw invalid("must be a JSON list of bindings.");
  if (value.length > MAX_FORM_DELIVERY_BINDINGS) throw invalid(`has ${value.length} bindings; at most ${MAX_FORM_DELIVERY_BINDINGS} are allowed. Remove some, then save again.`);
  const seen = new Set<string>();
  return value.map((entry: unknown, index) => {
    const binding = parseBinding({ value: entry, where: `binding ${index + 1}` });
    if (seen.has(binding.bindingId)) throw invalid(`binding ${index + 1} repeats bindingId ${quote(binding.bindingId)}; give every binding its own id.`);
    seen.add(binding.bindingId);
    return binding;
  });
}

function parseBinding(required: { value: unknown; where: string }): FormDeliveryBinding {
  const { value, where } = required;
  if (!isPlainObject(value)) throw invalid(`${where} must be an object.`);
  const unknown = Object.keys(value).find(key => !BINDING_FIELDS.has(key));
  if (unknown !== undefined) throw invalid(`${where} has unknown field ${quote(unknown)}; allowed fields are ${[...BINDING_FIELDS].join(", ")}.`);
  if (typeof value.enabled !== "boolean") throw invalid(`${where}: enabled must be true or false.`);
  const formIds = parseFormIds({ value: value.formIds, where });
  return {
    bindingId: parseReference({ value: value.bindingId, where, field: "bindingId" }),
    adapterId: parseReference({ value: value.adapterId, where, field: "adapterId" }),
    connectionRef: parseReference({ value: value.connectionRef, where, field: "connectionRef" }),
    enabled: value.enabled,
    ...(formIds === undefined ? {} : { formIds }),
    config: parseConfig({ value: value.config, where }),
  };
}

/** Ids and references are checked like config values: a secret pasted into one would be stored
 *  and copied into every delivery job as plainly as one in `config`. */
function parseReference(required: { value: unknown; where: string; field: string }): string {
  const { value, where, field } = required;
  if (typeof value !== "string" || value.length === 0 || value.length > MAX_REFERENCE_LENGTH) {
    throw invalid(`${where}: ${field} must be a non-empty string of at most ${MAX_REFERENCE_LENGTH} characters.`);
  }
  assertNotSecretValue({ path: field, value, where });
  return value;
}

function parseFormIds(required: { value: unknown; where: string }): string[] | undefined {
  const { value, where } = required;
  if (value === undefined) return undefined;
  if (!Array.isArray(value)) throw invalid(`${where}: formIds must be a list of form ids (omit it for every form).`);
  if (value.length > MAX_FORM_DELIVERY_FORM_IDS) throw invalid(`${where}: formIds has ${value.length} entries; at most ${MAX_FORM_DELIVERY_FORM_IDS} are allowed (omit formIds to mean every form).`);
  return value.map((id: unknown) => parseReference({ value: id, where, field: "every formIds entry" }));
}

/** Walks the config iteratively (no recursion limit to hit) and returns a deep copy. */
function parseConfig(required: { value: unknown; where: string }): Record<string, unknown> {
  const { value, where } = required;
  if (!isPlainObject(value)) throw invalid(`${where}: config must be an object (use {} when the destination needs none).`);
  const pending: { path: string; value: unknown }[] = [{ path: "config", value }];
  for (let next = pending.pop(); next; next = pending.pop()) {
    if (typeof next.value === "string") assertNotSecretValue({ path: next.path, value: next.value, where });
    else if (next.value !== null && typeof next.value === "object") pending.push(...childrenOf({ path: next.path, value: next.value, where }));
  }
  return structuredClone(value);
}

function childrenOf(required: { path: string; value: object; where: string }): { path: string; value: unknown }[] {
  return Object.entries(required.value).map(([key, child]) => {
    const path = `${required.path}.${key}`;
    if (SECRET_KEY.test(key.toLowerCase().replace(/[^a-z0-9]/g, ""))) throw invalid(`${required.where}: ${quote(path)} is named like a secret. ${FIX_HINT}`);
    return { path, value: child };
  });
}

function assertNotSecretValue(required: { path: string; value: string; where: string }): void {
  if (SECRET_VALUES.some(pattern => pattern.test(required.value)) || isBasicCredential(required.value)) {
    throw invalid(`${required.where}: ${quote(required.path)} holds a value that looks like a credential. ${FIX_HINT}`);
  }
}

/** An HTTP Basic Authorization value: base64 that decodes to `user:password`. Decoding keeps plain
 *  words after "Basic" (a "Basic tier" plan name) usable. */
function isBasicCredential(value: string): boolean {
  const encoded = BASIC_VALUE.exec(value)?.[1];
  return encoded !== undefined && Buffer.from(encoded, "base64").toString("utf8").includes(":");
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** Names from the setting are echoed bounded and quoted, never config values. */
function quote(text: string): string {
  return JSON.stringify(text.length > 80 ? `${text.slice(0, 80)}…` : text);
}

function invalid(detail: string): ValueValidationFailedError {
  return new ValueValidationFailedError(`Form delivery bindings (${NAMESPACE}.${BINDINGS_KEY}) ${detail}`);
}

import type { JsonValue } from "@jini-ai/core/primitives";

import { PublishContentApplyRowError } from "#src/features/publish-content/apply-errors";
import { createRepoPublishHandler, gatewayDeps } from "#src/features/publish-content/repo-handler";
import type { PublishContentContributor, PublishContentPorts } from "#src/features/publish-content/type-registry";

import {
  clear,
  createSettingsPrincipalLookup,
  DefinitionNotFoundError,
  DefinitionTombstonedError,
  ForbiddenError,
  resolveDefinitionRaw,
  SCOPE_BIT,
  ScopeNotAllowedError,
  SecretNotSupportedError,
  set,
  ValueValidationFailedError,
  type SettingDefinitionRecord,
} from "./index.js";

/**
 * @file `site-setting` on the publish factory (`features/publish-content/repo-handler.ts`): the
 * owner-authored site identity — title and SEO defaults — travels to the live site (plan §1,
 * OQ1 = yes).
 *
 * Settings are a security boundary, so this is an ALLOWLIST ({@link PUBLISHABLE_SETTINGS}), never a
 * denylist: plenty of non-secret settings are per-environment (BYOK/provider chips, `site.testing`,
 * analytics IP ranges, privacy installation ids). A key must be listed AND its definition must be
 * non-secret and allow workspace scope, checked on the sending side (pack) and again on the receiving
 * side (precheck and write), so a hand-made bundle naming any other key is refused.
 *
 * Deliberately left out, though owner-authored: the crawl controls (`site.seo`
 * `default_robots_noindex`/`default_robots_nofollow`/`robots_rules`/`sitemap_enabled`) — a local or
 * staging value would deindex the live site; `site.comments.*` and `site.assistant.public_enabled`
 * are site behaviour, not identity. Only workspace values travel; a user's own preference never does.
 *
 * Addressed by `namespace:key`. Version is the value row's `seq` (the ledger revision that wrote it);
 * `set` records a `setting_revisions` row like any admin edit. A key cleared on the source (its
 * workspace row is `state='cleared'`) packs as `{ value: null, cleared: true }` and the destination
 * clears its own through `clear`, which records the revision too. A key never set on the source packs
 * nothing, so a fresh install never wipes the live site's values. `cleared` is left out of a set
 * row's state, so every hash packed before it existed stays the same.
 */

/** `namespace:key` -> the label the publish dialog shows. */
export const PUBLISHABLE_SETTINGS: Readonly<Record<string, string>> = {
  "core.site:title": "Site title",
  "site.seo:title_template": "SEO title template",
  "site.seo:default_description": "Default description",
  "site.seo:default_og_image": "Default share image",
  "site.seo:twitter_site": "X (Twitter) handle",
};

const OG_IMAGE = "site.seo:default_og_image";

export interface SiteSettingRow {
  readonly key: string;
  readonly label: string;
  readonly value: JsonValue | null;
  /** Only on a cleared workspace row; absent (not `false`) on a set one. */
  readonly cleared?: true;
  readonly version: number;
}

type Ports = PublishContentPorts["site-setting"];

/** Loopback, private-range and `.local` hosts: a URL naming one only works on this computer. */
const LOCAL_HOST = /^(?:localhost|.*\.localhost|.*\.local|127(?:\.\d+){3}|0\.0\.0\.0|\[::1?\]|10(?:\.\d+){3}|192\.168(?:\.\d+){2}|172\.(?:1[6-9]|2\d|3[01])(?:\.\d+){2})$/i;

/** An absolute URL whose host is this computer or its private network. A media ref (`<id>:<transform>`)
 *  or a public URL is fine. @complexity O(n) in the value's length. */
export function pointsAtThisComputer(value: unknown): boolean {
  if (typeof value !== "string" || !/^[a-z][a-z\d+.-]*:\/\//i.test(value.trim())) return false;
  try {
    return LOCAL_HOST.test(new URL(value.trim()).hostname);
  } catch {
    return true;
  }
}

function splitKey(id: string): { namespace: string; key: string } {
  const at = id.indexOf(":");
  return { namespace: id.slice(0, at), key: id.slice(at + 1) };
}

/** The definition, when `id` is allowlisted and it is non-secret, active and workspace-scoped. */
async function publishableDefinition(ports: Ports, workspaceId: string, id: string): Promise<SettingDefinitionRecord | null> {
  if (!Object.hasOwn(PUBLISHABLE_SETTINGS, id)) return null;
  const definition = await resolveDefinitionRaw({ repo: ports.settings }, { ...splitKey(id), workspaceId });
  const ok = definition && definition.status === "active" && !definition.secret && (definition.scopes & SCOPE_BIT.workspace) !== 0;
  return ok ? definition : null;
}

/** The workspace row, set or cleared; `null` when the key was never written here.
 *  @complexity two indexed reads. */
async function findSetting(ports: Ports, workspaceId: string, id: string): Promise<SiteSettingRow | null> {
  const definition = await publishableDefinition(ports, workspaceId, id);
  if (!definition) return null;
  const row = await ports.settings.getWorkspaceValue({ workspaceId, settingId: definition.settingId });
  if (!row) return null;
  const label = PUBLISHABLE_SETTINGS[id]!;
  return row.state === "cleared" ? { key: id, label, value: null, cleared: true, version: row.seq } : { key: id, label, value: row.valueJson, version: row.seq };
}

/** Plain refusals, rewritten for the owner by `ui/report-rows.ts`. */
const notPublishable = (id: string) => `site-setting '${id}' is not one this site publishes`;
const localOnly = (id: string) => `site-setting '${id}' points at this computer`;

export const contributeSiteSettingPublish = (): PublishContentContributor =>
  createRepoPublishHandler<SiteSettingRow, Ports>({
    entityType: "site-setting",
    coversTables: ["setting_values_workspace"],
    // What `deriveRequiredPermission` names for a workspace-scope `set`.
    permission: "settings.workspace.write",
    // The share image may name a media item.
    dependsOn: ["media"],
    ports: (deps) => deps.ports["site-setting"],
    list: async (p, workspaceId) => {
      const rows = await Promise.all(Object.keys(PUBLISHABLE_SETTINGS).map((id) => findSetting(p, workspaceId, id)));
      return rows.filter((row): row is SiteSettingRow => row !== null);
    },
    find: findSetting,
    idOf: (row) => row.key,
    include: (row) => !(row.key === OG_IMAGE && pointsAtThisComputer(row.value)),
    fields: { key: "local", label: "provenance", value: "transferred", cleared: "transferred", version: "local" },
    omitWhenAbsent: ["cleared"],
    references: (entity) => {
      // `<media id>:<transform>`; a slug or URL names nothing a scoped publish can carry.
      const ref = entity.id === OG_IMAGE ? entity.state.value : null;
      const mediaId = typeof ref === "string" ? ref.split(":")[0] : "";
      return mediaId && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(mediaId) ? [{ entityType: "media", key: mediaId }] : [];
    },
    validate: async ({ ports, workspaceId, entity }) => {
      if (!(await publishableDefinition(ports, workspaceId, entity.id))) return notPublishable(entity.id);
      return entity.id === OG_IMAGE && pointsAtThisComputer(entity.state.value) ? localOnly(entity.id) : null;
    },
    write: async ({ ports, deps, workspaceId, id, state, principalId }) => {
      // Precheck already refused these; checked again because this is the one write.
      if (!(await publishableDefinition(ports, workspaceId, id))) throw new PublishContentApplyRowError("blocked", notPublishable(id));
      if (id === OG_IMAGE && pointsAtThisComputer(state.value)) throw new PublishContentApplyRowError("blocked", localOnly(id));
      const { authorize } = gatewayDeps(deps, "site-setting");
      const writeDeps = { repo: ports.settings, clock: deps.clock, ids: deps.idGen, authorize, principals: createSettingsPrincipalLookup({ repo: ports.principals }) };
      const target = { ...splitKey(id), scope: "workspace" as const, workspaceId, callerPrincipalId: principalId, authWorkspaceId: workspaceId };
      const { revisionSeq } =
        state.cleared === true
          ? await clear({ deps: writeDeps, input: target })
          : await set({ deps: writeDeps, input: { ...target, value: (state.value ?? null) as JsonValue } });
      return { version: revisionSeq };
    },
    errors: {
      blocked: [ValueValidationFailedError, ForbiddenError, DefinitionNotFoundError, DefinitionTombstonedError, ScopeNotAllowedError, SecretNotSupportedError],
    },
  });

import { toolMetadata } from '../../contracts/core/tool-metadata/settings.js';
import { withToolMetadata } from '@jini-ai/core';
import { ASSISTANT_EXECUTION_APPROVAL_SETTINGS } from "../../contracts/headless/assistant-tool-approval-policy.js";
import { ASSISTANT_PERMANENT_DELETES_NAMESPACE, ASSISTANT_PERMANENT_DELETES_WRITE_REASON } from "../../contracts/headless/assistant-permanent-deletes-policy.js";
import { ASSISTANT_SUBAGENTS_NAMESPACE, ASSISTANT_SUBAGENTS_WRITE_REASON } from "../../contracts/headless/assistant-subagents-policy.js";
/**
 * @file Settings' agent-tool registrations — adapted from `@jini-ai/core/settings`.
 *
 * The package owns the catalog, validation and writes. This host adapter supplies the shared
 * human card for the six assistant execution escalations and the existing site-title validator.
 * It contributes those tools through the same registration seam used before value writes existed.
 *
 * Converted to the standard `registerToolContributor` pattern 2026-08-17, the last domain to do so —
 * see `assistant/tool-registrations.ts`'s own former `settings` `DOMAIN_SLICES` entry (now removed)
 * for the full trace of why this was a genuinely different shape of blocker than every other
 * conversion in this rollout, not just a later-scheduled one. Short version: `settings` itself had NO
 * edge into `assistant` before this file's `contributeSettingsTools()` below — the blocker was that 3
 * OTHER files inside `assistant/` (`public-assistant-settings.ts`, `custom-instructions.ts`,
 * `execution-mode-settings.ts`) value-imported `features/settings`'s engine functions directly
 * (`getEffective`/`resolveDefinitionRaw`/`registerDefinitions`/`set`/`ensureSettingDefinitions`),
 * which would have closed a 2-node `[assistant, features/settings]` cycle the moment this file added
 * the reverse `features/settings -> assistant` edge below. Those 3 files now take those 5 functions
 * (plus the `SCOPE_BIT`/`INSTRUCTIONS_NAMESPACE` constants, injected for uniformity with the rest of
 * each file's deps surface) as injected deps fields instead of static imports — the same Option-B-style
 * technique `vendor-credentials/store.ts`'s `extractGitHubLogin`, `dual-read.ts`'s legacy-table
 * imports, and `assistant/site/*`'s `listPublishedPosts` already use elsewhere in this rollout —
 * wired to the real `features/settings` implementations at the composition root
 * (`RouteDeps.getEffective`/`.set`/`.instructionsNamespace` in `server/routes/types.ts`, populated
 * once in both `server/app.ts`/`server/deps.ts`; the boot-time `ensure*` registrars' own
 * `resolveDefinitionRaw`/`registerDefinitions`/`scopeBit`/`ensureSettingDefinitions` fields populated
 * at each of their 2+2 call sites in the same 2 files). `check:architecture` confirms 0 module cycles
 * / largest SCC 0 with `settings` wired this way.
 */
import type { ToolContributor } from "#src/assistant/index";
import type { ToolExecutionOptions, ToolExecutionContext, ToolRegistration, RememberedApprovalPort } from "@jini-ai/core";
import { buildSettingsRegistrations as buildCmsSettingsRegistrations, settingsDerivedRisk, type SettingsToolDeps as CoreSettingsToolDeps, type AgentSettingWriteRule } from "@jini-ai/core/settings";
import { approvalToolHandler } from "#src/contracts/core/human-confirm";
import type { AssistantSurfaceDeps } from "@jini-ai/daemon/surface-exchanges";
import { DEDICATED_SETTINGS_WRITERS, set } from "./site-title-write.js";
import { ADMIN_INTERFACE_NAMESPACE, CHAT_AGENT_PLUGINS_KEY, USE_CLAUDE_IN_CHROME_KEY } from "./admin-interface.js";
import { CHAT_EXECUTION_KEYS, prepareChatExecutionWrite } from "./chat-execution-write.js";
import type { AssistantAgentInventory } from "#src/assistant/agents";

export { settingsDerivedRisk } from "@jini-ai/core/settings";

/** Native grants are bound to the invoking plugin's admitted identity/version/digest, never model input. */
export type SettingsToolDeps = CoreSettingsToolDeps & {
  assistantAgentInventory?: AssistantAgentInventory;
  /** The composed host writer applies title bounds and visitor-credential policy alike. */
  set?: typeof set;
  nativeApprovalMemory?: RememberedApprovalPort;
  approvalIdentityForRun?: (required: { ctx: ToolExecutionContext }) => Promise<{ key: string; label: string; version?: string }>;
};

/** Where visitors' form answers go: delivery bindings send every new submission to outside
 * destinations, and the receiver collects a static site's submissions. Both always ask, because a
 * plugin's saved escalation grant was given for execution settings, not for routing answers. */
const FORMS_NAMESPACE = "core.forms";
const FORM_ROUTING_SETTINGS: readonly AgentSettingWriteRule[] = [
  { namespace: FORMS_NAMESPACE, key: "deliveryBindings", reason: "Changes where new form submissions are sent" },
  { namespace: FORMS_NAMESPACE, key: "receiver", reason: "Changes which receiver collects your published site's form submissions" },
];

/** Which mail provider sends and whether mail is redirected/captured change where every email goes;
 * only the approval-gated `mail_set_provider` tool (never rememberable) may change the provider. */
export const MAIL_SETTINGS_WRITE_DENIALS: readonly AgentSettingWriteRule[] = [
  { namespace: "core.mail", key: "provider", reason: "The mail provider changes only through mail_set_provider, which needs a human approval every time." },
  { namespace: "core.mail", key: "testMode", reason: "Mail test mode (redirect/capture) is an operator setting the assistant cannot change." },
];

/** Host-owned assistant configuration: changes are possible only after a human card.
 * Credentials are not settings: core.execution intentionally omits byok.apiKey; provider
 * credentials, OAuth state and external-MCP grants use their own repositories. */
export const TOVU_CONFIRMATION_SETTINGS: readonly AgentSettingWriteRule[] = [
  ...ASSISTANT_EXECUTION_APPROVAL_SETTINGS.filter(rule => rule.key !== "localCli.agentId"),
  ...CHAT_EXECUTION_KEYS.map(key => ({ namespace: "core.execution", key, reason: "Changes your chat agent, model or thinking effort for the next turn" })),
  { namespace: ADMIN_INTERFACE_NAMESPACE, key: CHAT_AGENT_PLUGINS_KEY, reason: "Changes your Agent plugins mode (Auto / Ask first / Off)" },
  { namespace: ADMIN_INTERFACE_NAMESPACE, key: USE_CLAUDE_IN_CHROME_KEY, reason: "Lets the assistant control your own Chrome browser, including sites you are logged into (Claude in Chrome)" },
  ...FORM_ROUTING_SETTINGS,
];

/** Personal grants in `core.interface` that a saved approval must never cover. Agent plugins
 * opt-in belongs to the person: a saved plugin grant must never let prompt injection silently flip
 * Ask first to Auto (or clear its override). Claude in Chrome likewise: the assistant must not
 * silently grant itself control of the owner's real, logged-in Chrome.
 * @complexity O(1). */
const ALWAYS_ASK_INTERFACE_KEYS: ReadonlySet<string> = new Set([CHAT_AGENT_PLUGINS_KEY, USE_CLAUDE_IN_CHROME_KEY]);
function isAlwaysAskInterfaceSetting({ namespace, key }: { namespace: string; key: string }, _options = {}): boolean {
  return namespace === ADMIN_INTERFACE_NAMESPACE && ALWAYS_ASK_INTERFACE_KEYS.has(key);
}

/** Wires the generic cms tools to the host's authenticated card transport and title validator.
 * Card parameters carry only a decision, never replacement setting coordinates or values.
 * @complexity O(t) registration construction; one bounded card exchange per protected write. */
export function buildSettingsRegistrations(routeDeps: SettingsToolDeps, surfaces: AssistantSurfaceDeps): ToolRegistration[] {
  // The chat-selection how-to lives in this tool's search metadata: descriptions stay the catalog's verbatim.
  return withToolMetadata({ metadata: toolMetadata, registrations: buildCmsSettingsRegistrations({
    ...routeDeps,
    extraDeniedSettings: [...(routeDeps.extraDeniedSettings ?? []), { namespace: "core.consent", reason: "Cookie consent changes require consent_update_settings and consent_publish_settings with a human confirmation card." }, { namespace: ASSISTANT_SUBAGENTS_NAMESPACE, reason: ASSISTANT_SUBAGENTS_WRITE_REASON }, { namespace: ASSISTANT_PERMANENT_DELETES_NAMESPACE, reason: ASSISTANT_PERMANENT_DELETES_WRITE_REASON }, ...MAIL_SETTINGS_WRITE_DENIALS,
      // `settings_clear_value` calls the package's `clear`, which would restore the built-in default.
      ...DEDICATED_SETTINGS_WRITERS.map(({ namespace, key, reason }) => ({ namespace, key, reason }))],
    setValue: routeDeps.set ?? set,
    confirmationSettings: TOVU_CONFIRMATION_SETTINGS,
    // `options` carries the transport's emitSurface; without it the card has no way to reach a human.
    // Declared optional so this still type-checks against a @jini-ai/cms whose confirmWrite takes one argument.
    confirmWrite: async ({ ctx, toolId, namespace, key, scope, previous, value, reason }, options?: ToolExecutionOptions) => {
      const request = { ctx, toolId, namespace, key, scope, value };
      const selectionSnapshot = await prepareChatExecutionWrite({ deps: routeDeps, request });
      // Personal grants always ask; see `ALWAYS_ASK_INTERFACE_KEYS` for why.
      const alwaysAsk = isAlwaysAskInterfaceSetting({ namespace, key }) || namespace === FORMS_NAMESPACE || selectionSnapshot !== null;
      // Reuse the invoking plugin's canonical enable grant. Escalation consent applies once to
      // that admitted identity/version/digest; it never replaces fresh per-write scope permissions.
      const handler = approvalToolHandler({ surfaces,
        prepare: async ({ ctx: snapshot }) => {
          const identity = await routeDeps.approvalIdentityForRun?.({ ctx: snapshot });
          return { rememberKey: identity?.key, identity };
        },
        describe: ({ prepared }) => ({ toolId, errorCode: "SETTINGS",
          title: toolId === "settings_set_value" ? "Change this assistant setting?" : "Clear this assistant setting override?",
          description: reason + (alwaysAsk ? ". This change requires your confirmation every time." : prepared.identity ? ". This escalation approval is saved for this plugin identity, version and digest. It also covers enabling this plugin and the six assistant execution settings; every action still checks its current permissions." : ""),
          details: [...(prepared.identity ? [{ label: "Plugin", value: prepared.identity.label },
            ...(prepared.identity.version ? [{ label: "Plugin version", value: prepared.identity.version }] : [])] : []), { label: "Setting", value: `${namespace}.${key}` }, { label: "Scope", value: scope },
            { label: "Previous override", value: JSON.stringify(previous) },
            ...(selectionSnapshot !== null ? [{ label: "Resulting chat selection", value: JSON.stringify(JSON.parse(selectionSnapshot)) }] : []),
            { label: "New value", value: toolId === "settings_clear_value" ? "Fall back to the next layer or default" : JSON.stringify(value ?? null) }],
          confirmLabel: "Confirm change",
        }),
        // The settings owner retains fresh authorization, layer-sequence and definition-version checks.
        run: async ({ ctx: snapshot, prepared }) => {
          // The model/effort depends on the selected runtime too. Consent must not drift to a
          // different selection if another picker changes it while this card is held open.
          const currentSelection = await prepareChatExecutionWrite({ deps: routeDeps, request: { ...request, ctx: snapshot } });
          const currentKey = (await routeDeps.approvalIdentityForRun?.({ ctx: snapshot }))?.key;
          return { confirmed: !snapshot.signal.aborted && currentKey === prepared.rememberKey && currentSelection === selectionSnapshot };
        },
      }, { remembered: alwaysAsk ? undefined : routeDeps.nativeApprovalMemory, rememberKey: ({ prepared }) => prepared.rememberKey,
        declined: () => ({ confirmed: false }),
      });
      // No credentials enter this description; they use the secret-card engine and separate stores.
      const result = await handler(ctx, options) as { confirmed: boolean; key?: string };
      return result.confirmed;
    },
  }) });
}

/**
 * Contributes Settings' AI tools to the assistant's catalog — called once by
 * `server/tool-catalog-manifest.ts`'s `installFirstPartyToolContributors()`, not by importing this
 * module. `assistant/tool-registrations.ts` no longer imports `buildSettingsRegistrations`/
 * `settingsDerivedRisk` by name, and `server/tool-catalog-manifest.ts` no longer inlines this
 * `registerToolContributor` call itself — this is the seam that replaced both, the same shape every
 * other domain in this rollout uses (see this file's header for why `settings` needed the 3 side-door
 * files fixed first rather than converting directly).
 */
export function contributeSettingsTools(): ToolContributor {
  return { domain: "settings", build: buildSettingsRegistrations, risk: settingsDerivedRisk };
}

import { createHash } from "node:crypto";
import { resolveThemeOriginalSource } from "#src/features/theme/index";
import { createTovuAgentPluginLifecycle } from "#src/features/agent-plugins/lifecycle";
import { collectSiteBackupFiles, readPlannedFile, type PlannedDiskFile, type SiteBackupSources } from "./sources.js";
import type { ArchivePlugin } from "./archive-manifest.js";
import { runtimeToArchivePath } from "./archive-paths.js";
import { SiteShareRefusal } from "./share-policy.js";
import { PLUGIN_MANIFEST_FILENAMES } from "@jini-ai/plugins/host";

/** Selects installed package versions through the lifecycle owner; includes reset baselines.
 * @throws SiteShareRefusal for multiple workspaces, unsafe originals or stale planned files.
 * @complexity O(files × (themes + plugins) + package bytes), bounded by share caps.
 */
export async function prepareArchiveExtensions(required: { sources: SiteBackupSources; files: readonly PlannedDiskFile[] }, optional: { packageThemesRoot?: string } = {}): Promise<{ files: PlannedDiskFile[]; plugins: ArchivePlugin[] }> {
  const files = [...required.files];
  await includeThemeOriginals({ sources: required.sources, files }, optional);
  const workspaces = new Set(files.flatMap(file => /^agent-plugins\/ws\/([^/]+)\//.exec(file.path)?.[1] ?? []));
  if (workspaces.size > 1) throw new SiteShareRefusal({ code: "UNSUPPORTED_DATA", message: "Export requires a single plugin workspace." });
  const plugins: ArchivePlugin[] = [];
  let selected = files;
  const workspaceId = [...workspaces][0];
  if (workspaceId) {
    const lifecycle = createTovuAgentPluginLifecycle({ layout: required.sources.agentPlugins });
    const workspaceRoot = required.sources.agentPlugins.forWorkspace(workspaceId).root;
    const candidates = await lifecycle.listInstalledPlugins(workspaceRoot);
    const installed = lifecycle.preferBundledAgentPluginDigests(candidates, await lifecycle.readBundledAgentPluginDigests(workspaceRoot));
    if (new Set(installed.map(plugin => plugin.pluginId)).size !== installed.length) throw new SiteShareRefusal({ code: "UNSUPPORTED_PLUGIN", message: "Export requires one installed digest per plugin id." });
    const activations = await lifecycle.readAgentPluginActivations({ workspaceRoot });
    const supersededRoots = candidates.filter(candidate => !installed.includes(candidate)).map(plugin => plugin.packageRoot + "/");
    selected = files.filter(file => !supersededRoots.some(root => file.absPath.startsWith(root)));
    for (const plugin of installed) plugins.push({ kind: "agent", id: plugin.pluginId, version: plugin.version ?? "unknown", digest: plugin.archiveDigest, enabled: activations.plugins[plugin.pluginId]?.enabled ?? true, shipped: true });
  }
  plugins.push(...await unindexedAgentRecords({ files: selected, plugins }));
  plugins.push(...await sitePluginRecords({ files: selected }));
  return { files: selected.filter(file => runtimeToArchivePath({ path: file.path }) !== null), plugins };
}

async function includeThemeOriginals(required: { sources: SiteBackupSources; files: PlannedDiskFile[] }, optional: { packageThemesRoot?: string }): Promise<void> {
  const themes = required.files.filter(file => /^themes\/(static|declarative|code)\/[^/]+\/theme.json$/.test(file.path));
  for (const file of themes) {
    const [, tier, id] = file.path.split("/");
    const originalPrefix = `themes/__original-themes__/${tier}/${id}/`;
    if (required.files.some(file => file.path.startsWith(originalPrefix))) continue;
    const original = resolveThemeOriginalSource({ manifest: { tier: tier as "static", id: id! }, siteThemesRoot: required.sources.themesDir, packageThemesRoot: optional.packageThemesRoot });
    if (original) {
      const collected = await collectSiteBackupFiles({ sources: { ...required.sources, themesDir: original.originalDir }, include: { database: false, media: false, themes: true, plugins: false, settings: false } }, { profile: "share" });
      if (collected.skipped.length) throw new SiteShareRefusal({ code: "UNSAFE_FILE", message: `Cannot export theme original '${id}': ${collected.skipped[0]!.reason}.` });
      required.files.push(...collected.files.filter(file => file.path.startsWith("themes/")).map(file => ({ ...file, path: originalPrefix + file.path.slice("themes/".length) })));
    } else {
      // A theme without a recorded baseline still needs a recoverable original in v2.
      // Preserve its current snapshot as that baseline; never invent package content.
      const livePrefix = `themes/${tier}/${id}/`;
      required.files.push(...required.files.filter(file => file.path.startsWith(livePrefix)).map(file => ({ ...file, path: originalPrefix + file.path.slice(livePrefix.length) })));
    }
  }
}

async function sitePluginRecords({ files }: { files: readonly PlannedDiskFile[] }): Promise<ArchivePlugin[]> {
  const groups = new Map<string, PlannedDiskFile[]>();
  for (const file of files) {
    const mapped = runtimeToArchivePath({ path: file.path });
    const id = mapped && /^plugins\/([^/]+)\/package\//.exec(mapped)?.[1];
    if (id) { const group = groups.get(id) ?? []; group.push(file); groups.set(id, group); }
  }
  const plugins: ArchivePlugin[] = [];
  for (const [id, entries] of groups) {
    const digest = createHash("sha256");
    let version = "unknown";
    for (const file of entries) {
      const read = await readPlannedFile(file);
      if (!read.ok) throw new SiteShareRefusal({ code: "PLAN_STALE", message: read.message });
      digest.update(file.path).update(createHash("sha256").update(read.bytes).digest());
      version = sitePluginVersion({ file, bytes: read.bytes, id, current: version });
    }
    plugins.push({ kind: "site", id, version, digest: digest.digest("hex"), enabled: false, shipped: true });
  }
  return plugins;
}

/** Malformed/unindexed packages are still site content. Preserve their bytes, never infer trust. */
async function unindexedAgentRecords(required: { files: readonly PlannedDiskFile[]; plugins: readonly ArchivePlugin[] }): Promise<ArchivePlugin[]> {
  const known = new Map(required.plugins.map(plugin => [plugin.id, plugin.digest]));
  const extras: ArchivePlugin[] = [];
  for (const file of required.files) {
    const match = /^agent-plugins\/ws\/[^/]+\/([^/]+)\/package\/sha256\/([a-f0-9]{64})\//.exec(file.path);
    if (!match) continue;
    const [, id, digest] = match;
    const previous = known.get(id!);
    if (previous && previous !== digest) throw new SiteShareRefusal({ code: "UNSUPPORTED_PLUGIN", message: `Plugin '${id}' has multiple installed digests.` });
    if (previous) continue;
    known.set(id!, digest!);
    extras.push({ kind: "agent", id: id!, version: "unknown", digest: digest!, enabled: false, shipped: true });
  }
  return extras;
}

/** Only the package's own manifest names its version; nested example manifests do not. Jini lists exactly
 *  one manifest per package (the one discovery validated against its version folder). */
function sitePluginVersion(required: { file: PlannedDiskFile; bytes: Buffer; id: string; current: string }): string {
  if (!PLUGIN_MANIFEST_FILENAMES.some(name => required.file.path === `plugins/${required.id}/package/${name}`)) return required.current;
  return String(JSON.parse(required.bytes.toString("utf8")).version ?? "unknown");
}

import { createHash } from "node:crypto";
import path from "node:path";
import { sniffContentType, sanitizeSvg, computeBlobStorageKey, mimeForTransformFormat, type BlobStorePort, type ImageTransformerPort, type TransformParams } from "#src/features/media/index";
import { SiteShareRefusal } from "./share-policy.js";
import { sharePathAlias, validateSharePath } from "./share-file-policy.js";
import { addBuffered, reportedBlobSize, fetchVerifiedBlob, type ShareLedger } from "./share-preparation-steps.js";
import type { ArchiveMedia } from "./archive-manifest.js";

/** Snapshot-owned metadata, never a read from mutable live media repositories. */
export interface ArchiveMediaSource {
  readonly id: string; readonly workspaceId: string; readonly slug: string;
  readonly originalFilename: string | null; readonly kind: string;
  readonly storageKey: string; readonly sha256: string;
  readonly documentOwned?: boolean;
  readonly public?: { readonly storageKey?: string; readonly sha256?: string; readonly version: number; readonly params: TransformParams };
}
export interface ArchiveMediaCopy extends ArchiveMedia {
  readonly workspaceId: string; readonly storageKey: string; readonly contentType: string;
  readonly publicVersion?: number;
  readonly documentOwned?: boolean;
}
export type ArchiveMediaRewriter = (required: { bytes: Buffer; copies: readonly ArchiveMediaCopy[] }, optional?: { signal?: AbortSignal }) => Promise<Buffer>;
const EXTENSIONS: Record<string, string> = { "video/mp4": "mp4", "video/webm": "webm", "audio/wav": "wav", "audio/mpeg": "mp3", "audio/flac": "flac", "audio/mp4": "m4a" };

/** Picks exactly one public copy per item, in id order, without writing to the source site.
 * @throws SiteShareRefusal naming missing, corrupt or unbounded media; raster failures never fall back to raw bytes.
 * @complexity O(items log items + media bytes); shared caps bound retained output and each input read.
 */
export async function bufferArchiveMedia(required: { sources: readonly ArchiveMediaSource[]; blobStore: Pick<BlobStorePort, "get" | "sizeOf">; imageTransformer: ImageTransformerPort; ledger: ShareLedger }, optional: { signal?: AbortSignal } = {}): Promise<ArchiveMediaCopy[]> {
  const aliases = new Set<string>();
  const copies: ArchiveMediaCopy[] = [];
  for (const source of [...required.sources].sort((a, b) => a.id < b.id ? -1 : Number(a.id > b.id))) {
    optional.signal?.throwIfAborted();
    const original = await readCopy({ blobStore: required.blobStore, source });
    const selected = await publicCopy({ source, original, blobStore: required.blobStore, imageTransformer: required.imageTransformer });
    const file = mediaPath({ source, extension: selected.extension, aliases });
    const sha256 = createHash("sha256").update(selected.bytes).digest("hex");
    const storageKey = computeBlobStorageKey({ workspaceId: source.workspaceId, sha256 });
    validateSharePath({ path: "uploads/" + storageKey });
    addBuffered({ ledger: required.ledger, file: { path: file, content: selected.bytes } });
    copies.push({ id: source.id, slug: source.slug, path: file, sha256, workspaceId: source.workspaceId, storageKey, contentType: selected.contentType, documentOwned: source.documentOwned, ...(selected.publicVersion === undefined ? {} : { publicVersion: selected.publicVersion }) });
  }
  return copies;
}

/** Size and checksum must come from the snapshot/store contract before bytes can be archived. */
async function readCopy(required: { blobStore: Pick<BlobStorePort, "get" | "sizeOf">; source: { storageKey: string; sha256?: string; kind?: string } }): Promise<Buffer> {
  validateSharePath({ path: "uploads/" + required.source.storageKey });
  const size = await reportedBlobSize({ blobStore: required.blobStore, storageKey: required.source.storageKey, document: required.source.kind === "document" });
  return fetchVerifiedBlob({ blobStore: required.blobStore, media: required.source, size });
}

async function publicCopy(required: { source: ArchiveMediaSource; original: Buffer; blobStore: Pick<BlobStorePort, "get" | "sizeOf">; imageTransformer: ImageTransformerPort }): Promise<{ bytes: Buffer; contentType: string; extension: string; publicVersion?: number }> {
  const contentType = sniffContentType({ bytes: required.original });
  if (required.source.kind === "document") return { bytes: required.original, contentType, extension: originalExtension(required.source) };
  if (contentType === "image/svg+xml") return { bytes: Buffer.from(await sanitizeSvg({ bytes: required.original })), contentType, extension: "svg" };
  if (!contentType.startsWith("image/")) return { bytes: required.original, contentType, extension: EXTENSIONS[contentType] ?? originalExtension(required.source) };
  return rasterCopy(required);
}

async function rasterCopy(required: { source: ArchiveMediaSource; original: Buffer; blobStore: Pick<BlobStorePort, "get" | "sizeOf">; imageTransformer: ImageTransformerPort }): Promise<{ bytes: Buffer; contentType: string; extension: string; publicVersion: number }> {
  const definition = required.source.public;
  if (!definition || definition.params.format !== "webp") throw new SiteShareRefusal({ code: "INVALID_MEDIA", message: `Media '${required.source.id}' has no public webp transform.` });
  try {
    const bytes = definition.storageKey
      ? await readCopy({ blobStore: required.blobStore, source: { storageKey: definition.storageKey, ...(definition.sha256 ? { sha256: definition.sha256 } : {}) } })
      : Buffer.from((await required.imageTransformer.transform({ bytes: required.original, params: definition.params })).bytes);
    if (sniffContentType({ bytes }) !== "image/webp") throw new Error("public rendition is not webp");
    return { bytes, contentType: mimeForTransformFormat({ format: definition.params.format }), extension: "webp", publicVersion: definition.version };
  } catch (error) {
    throw new SiteShareRefusal({ code: "INVALID_MEDIA", message: `Cannot export media '${required.source.id}' (${required.source.slug}): ${error instanceof Error ? error.message : "image decode failed"}` });
  }
}

function originalExtension(source: ArchiveMediaSource): string {
  const extension = path.extname(source.originalFilename ?? "").slice(1).toLowerCase();
  return /^[a-z0-9]{1,12}$/.test(extension) ? extension : "bin";
}
function mediaPath(required: { source: ArchiveMediaSource; extension: string; aliases: Set<string> }): string {
  const slug = required.source.slug || required.source.id;
  const extension = portableExtension({ slug, extension: required.extension });
  let candidate = `media/${slug}.${extension}`, suffix = 2;
  while (required.aliases.has(sharePathAlias({ path: candidate }))) candidate = `media/${slug}-${suffix++}.${extension}`;
  validateSharePath({ path: candidate });
  required.aliases.add(sharePathAlias({ path: candidate }));
  return candidate;
}

/** A document keeps its own extension, which the share path policy may never publish (Keynote's
 * `.key`). The archive name is cosmetic: the media row keeps the original filename, so `.bin` names it. */
function portableExtension(required: { slug: string; extension: string }): string {
  try { validateSharePath({ path: `media/${required.slug}.${required.extension}` }); return required.extension; } catch (error) {
    if (error instanceof SiteShareRefusal) return "bin";
    throw error;
  }
}

