/**
 * @file The site-backup service behind the agent tools `site_backup_plan` (read-only) and
 * `site_backup_push` (authorized, immediate) AND the admin Git backup route
 * (`admin-http/routes/system/site-backups.ts`): one code path, so the screen and the assistant run
 * the same checks under the same permissions. Together they put the site's content — the database, media, themes, plugins
 * and settings — into ONE folder of a private repository on a plugin-provided git host, in one commit, through a saved
 * custom credential (the same credentials `custom_credential_write_files` uses).
 *
 * Why two calls: the plan does every check that can fail (credential, repository visibility and
 * permissions, branch, folder, database snapshot, sizes) and returns what WOULD be written, so the
 * model can report the planned backup. The push uploads exactly what was planned: the database snapshot is
 * held in memory with the plan (`plan-store.ts`), and each disk file is re-read and refused if it
 * changed since (`readPlannedFile`).
 *
 * A large backup outlasts one tool call: the push runs as a job (`push-jobs.ts`), the call waits for
 * it up to {@link PUSH_WAIT_MS} and otherwise returns its progress; calling the push again with the
 * same planId keeps waiting on the same job. The upload itself is `push-engine.ts`.
 *
 * Safety rules, each re-checked at push time where the world can change in between:
 * - The database is the share projection ({@link captureBackupDatabase}): content, themes and
 *   settings, never accounts, members, RBAC, sessions or secrets.
 * - Private repositories only (public and "internal" both refused), because the database holds
 *   unpublished content. Re-checked before pushing.
 * - Never a force push, and never a surprise overwrite: the push commits on the PLAN's tip, and a
 *   branch that moved since is refused (`DIVERGED_BRANCH`) before a single blob is uploaded, and
 *   again by the host itself on the non-force ref update.
 * - The token never leaves the server: not in any result, dialog or log line.
 *
 * Credential errors are split so an operator can act on them: a label with no saved row is
 * `CREDENTIAL_NOT_FOUND` (with the labels that do exist), and a saved row this server cannot decrypt
 * is `CREDENTIAL_UNREADABLE`, whose message says WHICH problem it is from THIS SITE's own site key
 * status (`inspectSiteKeyMaterial` run over `siteKeySourcesForSiteDir`'s site-aware source ordering —
 * site-key plan §A3b, the same composed helper the admin site key route reuses, so an active
 * per-site key file is never mistaken for "no site key" — see `unreadableCredentialMessage`) —
 * never from the decrypt error's own text, which can quote plaintext. (The same "unreadable reads as
 * missing" confusion `ADS-memory/.local-artifacts/reports/2026-09-21-byok-triage.md` traced for BYOK
 * keys.)
 *
 * Out of scope: restoring from a backup, and scheduled backups.
 */

export const SITE_BACKUP_DOMAIN = "site-backup";
const DOMAIN = SITE_BACKUP_DOMAIN;
export const PLAN_TOOL_ID = "site_backup_plan";
export const SITE_BACKUP_PUSH_TOOL_ID = "site_backup_push";
/** The one permission that names this feature. Not in any built-in role but the owner's `*`. */
export const PUSH_PERMISSION = "site-backup.push";
/** Also required: the push sends a saved credential's token to its provider, which is exactly what
 *  `custom_credential_write_files` gates on this permission. */
const CREDENTIAL_WRITE_PERMISSION = "custom-credentials.write";
/** The restore-point name the database snapshot is captured under, so an orphan is recognizable. */
const SNAPSHOT_SCOPE_ID = "site-backup";

/** What one plan or push call carries: the caller's raw input, who is calling, and when to stop. A
 *  tool's `ToolExecutionContext` is one; the admin route builds one from the request. */
export interface SiteBackupCall {
  readonly input: unknown;
  readonly principal: { readonly id: string };
  readonly signal: AbortSignal;
}

/** The slice of the route-deps bag these tools read. Structural, so this module never imports
 *  `server/routes/types`. */
export interface SiteBackupToolDeps {
  readonly siteImportBackend?: SiteImportBackend;
  readonly authorize: AuthorizeFn;
  readonly workspaceId: string;
  readonly customCredentialSetRepo: CustomCredentialSetRepoPort;
  /** The connections chat's "Connect <host>" form saves (`credential_save with kind source-control`); a
   *  host's default one is used when no custom credential points at it. `RouteDeps` has it. */
  readonly sourceControlCredentialSetRepo?: SourceControlCredentialSetRepoPort;
  readonly siteAssistantSecretSealer: SecretSealerPort;
  readonly customCredentialsHttpClient: HttpClientPort;
  /** The client a backup talks to its host with (`SITE_BACKUP_EGRESS_POLICY`: a 2-minute idle
   *  ceiling for large blob uploads); {@link customCredentialsHttpClient} when absent. */
  readonly siteBackupHttpClient?: HttpClientPort;
  /** The git-host providers a backup pushes through (the installed, enabled Agent Plugins supplied by
   *  composition — the bundled `github` one today). */
  readonly loadSourceControlProviders: LoadSourceControlProviders;
  /** `RouteDeps.observability`: a backup's raw git-host calls are outbound spans. */
  readonly observability?: ObservabilityPort;
  readonly dbOps: DbOpsPort;
  /** Where this site's files live. Absent in the in-memory `app.ts` runtime, which has no site
   *  folder — both tools then answer `UNAVAILABLE`. */
  readonly siteBackupSources?: SiteBackupSources;
  readonly siteShareBackend?: SiteShareBackend;
  /** Test-only; defaults to {@link sanitizeShareDatabase}, the share/export policy. */
  readonly siteBackupSanitize?: ShareDatabaseSanitizer;
  /** Test-only; defaults to the process-wide store. */
  readonly siteBackupPlanStore?: SiteBackupPlanStore;
  /** Test-only; defaults to {@link siteAwareSiteKeyStatus} (site-aware — see that function's doc). */
  readonly siteBackupSiteKeyStatus?: () => { readonly active: boolean; readonly invalid?: boolean };
  /** Test-only; defaults to `console.warn`. Receives only lines built here — never a token. */
  readonly siteBackupFailureLog?: (line: string) => void;
  /** Test-only; defaults to the real clock. */
  readonly siteBackupNow?: () => Date;
  /** Test-only; defaults to the process-wide job registry. */
  readonly siteBackupPushJobs?: SiteBackupPushJobs<PushResult>;
  /** Test-only; defaults to {@link PUSH_WAIT_MS}. */
  readonly siteBackupPushWaitMs?: number;
  /** Test-only; replaces the host's retry timer. */
  readonly siteBackupSleep?: (ms: number) => Promise<void>;
}

/** Every refusal both tools return, as `{code, message}`. */
interface Refusal {
  readonly ok: false;
  readonly code: string;
  readonly message: string;
}

function failureLog(deps: SiteBackupToolDeps): (line: string) => void {
  return deps.siteBackupFailureLog ?? ((line: string) => console.warn(line));
}

/** Logs a failure's server-only detail (a network failure's class and code). Never the token. */
function logFailureDetail(deps: SiteBackupToolDeps, toolId: string, failure: { readonly code: string; readonly logDetail?: string }): void {
  if (failure.logDetail !== undefined) failureLog(deps)(`[site-backup] ${toolId}: failed code=${failure.code} detail=${failure.logDetail}`);
}

// ---------------------------------------------------------------------------
// Credential
// ---------------------------------------------------------------------------

interface ResolvedBackupCredential {
  readonly ok: true;
  readonly label: string;
  readonly baseUrl: string;
  readonly connection: CustomProviderConnectionInput;
  /** The plugin provider for the credential's host. */
  readonly provider: SourceControlProvider;
}

/** A resolved credential's repository target: its API plus the `Authorization` header built from it. */
function backupTarget(credential: ResolvedBackupCredential, owner: string, repo: string): CredentialedRepositoryTarget {
  return { baseUrl: credential.baseUrl, authorization: buildAuthorizationHeader({ connection: credential.connection, schemes: [] }), owner, repo };
}

/** Every git-host provider an enabled plugin ships, or the refusal when there is none. */
async function loadBackupProviders(deps: SiteBackupToolDeps): Promise<{ ok: true; providers: readonly SourceControlProvider[]; noProviderMessage: string } | Refusal> {
  const built = await buildSourceControlProviders({
    load: deps.loadSourceControlProviders,
    workspaceId: deps.workspaceId,
    httpClient: deps.siteBackupHttpClient ?? deps.customCredentialsHttpClient,
    observability: deps.observability,
    ...(deps.siteBackupSleep ? { sleep: deps.siteBackupSleep } : {}),
  });
  for (const refusal of built.refusals) failureLog(deps)(`[site-backup] ${refusal}`);
  if (built.providers.length === 0) {
    return { ok: false, code: "NO_PROVIDER", message: built.noProviderMessage };
  }
  return { ok: true, providers: built.providers, noProviderMessage: built.noProviderMessage };
}

function originOf(url: string): string | null {
  try {
    return new URL(url).origin;
  } catch {
    return null;
  }
}

function labelList(labels: readonly string[]): string {
  return labels.length === 0 ? "none are saved" : `saved labels: ${labels.map((label) => `'${label}'`).join(", ")}`;
}

/**
 * Picks the credential's label: the one named, or — when none is — the single saved credential
 * pointing at a provider's API origin. A pure list read; nothing is decrypted here.
 *
 * @complexity O(saved credentials).
 */
async function pickCredentialLabel(deps: SiteBackupToolDeps, providers: readonly SourceControlProvider[], requested: string | undefined): Promise<{ ok: true; label: string } | Refusal> {
  const saved = await listCustomCredentials({ repo: deps.customCredentialSetRepo }, { workspaceId: deps.workspaceId });
  const labels = saved.map((credential) => credential.label);
  if (requested !== undefined) {
    if (labels.includes(requested)) return { ok: true, label: requested };
    return { ok: false, code: "CREDENTIAL_NOT_FOUND", message: `no saved credential is labeled '${requested}' (${labelList(labels)})` };
  }
  const apiOrigins = providers.map((provider) => provider.apiOrigin);
  const where = apiOrigins.join(" or ");
  const matching = saved.filter((credential) => apiOrigins.includes(originOf(credential.baseUrl) ?? "")).map((credential) => credential.label);
  if (matching.length === 1) return { ok: true, label: matching[0]! };
  if (matching.length === 0) {
    return {
      ok: false,
      code: "CREDENTIAL_NOT_FOUND",
      message: `no saved credential points at ${where} (${labelList(labels)}). Connect ${providers.map((provider) => provider.label).join(" or ")} with credential_save with kind source-control (a form in this chat), or save a token on the Access Tokens page ('Add custom provider', base URL ${where}), or name one with 'credential'.`,
    };
  }
  return { ok: false, code: "CREDENTIAL_AMBIGUOUS", message: `${matching.length} saved credentials point at ${where} (${labelList(matching)}); name one with 'credential'.` };
}

/**
 * This site's own site key status ({@link inspectSiteKeyMaterial}), resolved over THIS site's
 * site-aware source ordering ({@link siteKeySourcesForSiteDir} — site-key plan §A3b, the same
 * composed helper the admin site key route's `resolveSiteKeySources` reuses) rather than the
 * module-wide env-then-legacy-file default `inspectSiteKeyMaterial()` falls back to when called
 * bare. That default cannot see a per-site key file at all (`~/.tovu/site-keys/<id>.hex`), so a site
 * whose OWN key is active but has no env var and no legacy shared file would be reported `active:
 * false` — the exact gap {@link unreadableCredentialMessage} used to surface as "this server has no
 * site key" for a site that in fact has one.
 *
 * Falls back to the bare, non-site-aware status only when this runtime has no site folder at all
 * (`deps.siteBackupSources` absent — the in-memory `app.ts` runtime; in practice the plan tool's own
 * `UNAVAILABLE` check already refuses before this is ever reached for that case, but the push path
 * re-resolves the credential independently and must not throw if it ever is).
 *
 * @complexity O(1) — one `.site-meta.json` read plus a fixed-size source list, matching
 *   {@link inspectSiteKeyMaterial}'s own cost.
 */
function siteAwareSiteKeyStatus(deps: SiteBackupToolDeps): { active: boolean; invalid?: boolean } {
  const siteDir = deps.siteBackupSources?.siteDir;
  if (siteDir === undefined) return inspectSiteKeyMaterial({ sources: siteKeySources({ mode: resolveRuntimeMode(), env: process.env, home: homedir(), cwd: process.cwd() }) });
  const sources = siteKeySourcesForSiteDir({ siteDir, mode: resolveRuntimeMode(), env: process.env, home: homedir(), cwd: process.cwd() });
  return inspectSiteKeyMaterial({ sources });
}

/** Why a saved credential could not be decrypted, from THIS SITE's own site key status
 *  ({@link siteAwareSiteKeyStatus}) — never the bare, env/legacy-only default (see that function's
 *  own doc for why that used to misreport an active per-site key as "no site key"). */
function unreadableCredentialMessage(deps: SiteBackupToolDeps, label: string): string {
  const status = (deps.siteBackupSiteKeyStatus ?? (() => siteAwareSiteKeyStatus(deps)))();
  if (status.active) {
    return (
      `the credential '${label}' is saved but cannot be decrypted with this server's Site key: it differs from the one the credential was saved under, ` +
      "or the stored row is corrupted. Check Secrets → Site key in the admin, or save the credential again."
    );
  }
  if (status.invalid) {
    return `the credential '${label}' is saved but cannot be decrypted: this server's Site key (TOVU_SITE_KEY or its key file) is set but malformed. Fix it under Secrets → Site key.`;
  }
  return (
    `the credential '${label}' is saved but cannot be decrypted: this server has no Site key (TOVU_SITE_KEY is not set and there is no key file). ` +
    "Start Tovu with it (`npm run dev` from the repo root, or `npm run desktop`)."
  );
}

/**
 * The host's default connection saved through chat's "Connect <host>" form, when no custom
 * credential points at the host. Demo dry run 2026-10-05: that form saves into the source-control
 * store, which this tool never read, so a person who had just filled it in was still told
 * CREDENTIAL_NOT_FOUND. A named `credential` matches the connection's label, which is also how the
 * push re-resolves the plan's credential.
 *
 * @complexity O(providers) repo reads, at most one decrypt each.
 */
async function resolveHostConnection(deps: SiteBackupToolDeps, providers: readonly SourceControlProvider[], requested: string | undefined): Promise<ResolvedBackupCredential | Refusal | null> {
  const repo = deps.sourceControlCredentialSetRepo;
  if (!repo) return null;
  for (const provider of providers) {
    const lookup = await findHostConnection({ deps, repo, provider, providerId: provider.id });
    if (!lookup.ok) return lookup;
    if (lookup.found && (requested === undefined || requested === lookup.found.label)) return hostCredential({ found: lookup.found, provider });
  }
  return null;
}

type HostConnection = NonNullable<Awaited<ReturnType<typeof resolveDefaultForSourceControl>>>;

/** One host's default saved connection (or null); an unconfigured store is the safe CREDENTIAL_UNREADABLE diagnosis. */
async function findHostConnection(required: {
  deps: SiteBackupToolDeps;
  repo: SourceControlCredentialSetRepoPort;
  provider: SourceControlProvider;
  providerId: SourceControlProviderId;
}): Promise<{ ok: true; found: HostConnection | null } | Refusal> {
  const { deps, provider } = required;
  try {
    return { ok: true, found: await resolveDefaultForSourceControl({ repo: required.repo, sealer: deps.siteAssistantSecretSealer }, { workspaceId: deps.workspaceId, providerId: required.providerId }) };
  } catch (err) {
    if (err instanceof SourceControlCredentialSecretStoreUnconfiguredError) return { ok: false, code: "CREDENTIAL_UNREADABLE", message: unreadableCredentialMessage(deps, `${provider.label} connection`) };
    throw err;
  }
}

/** A saved host connection as the backup's credential: its token, plus the username when one was saved. */
function hostCredential(required: { found: HostConnection; provider: SourceControlProvider }): ResolvedBackupCredential {
  const { found, provider } = required;
  const { token } = found.connection;
  const connection: CustomProviderConnectionInput = "username" in found.connection ? { token, username: found.connection.username } : { token };
  return { ok: true, label: found.label, baseUrl: provider.apiOrigin, connection, provider };
}

/**
 * Resolves the credential the backup pushes with. A missing row and an undecryptable one are
 * different codes; the decrypt error's own text is never used (it can quote plaintext).
 *
 * @complexity O(saved credentials) plus one decrypt.
 */
async function resolveBackupCredential(deps: SiteBackupToolDeps, requested: string | undefined): Promise<ResolvedBackupCredential | Refusal> {
  const providers = await loadBackupProviders(deps);
  if (!providers.ok) return providers;
  const picked = await pickCredentialLabel(deps, providers.providers, requested);
  if (!picked.ok) {
    if (picked.code !== "CREDENTIAL_NOT_FOUND") return picked;
    return (await resolveHostConnection(deps, providers.providers, requested)) ?? picked;
  }
  let resolved;
  try {
    resolved = await resolveCustomCredentialByLabel({ repo: deps.customCredentialSetRepo, sealer: deps.siteAssistantSecretSealer }, { workspaceId: deps.workspaceId, label: picked.label });
  } catch (err) {
    if (err instanceof CustomCredentialSecretStoreUnconfiguredError) return { ok: false, code: "CREDENTIAL_UNREADABLE", message: unreadableCredentialMessage(deps, picked.label) };
    throw err;
  }
  if (!resolved) return { ok: false, code: "CREDENTIAL_NOT_FOUND", message: `the credential '${picked.label}' was deleted while the backup was being prepared` };
  const provider = pickSourceControlProviderForApi(providers.providers, resolved.baseUrl, providers.noProviderMessage);
  if (!provider.ok) return { ok: false, code: "NO_PROVIDER", message: provider.message };
  return { ok: true, label: picked.label, baseUrl: resolved.baseUrl, connection: resolved.connection, provider: provider.provider };
}

// ---------------------------------------------------------------------------
// Repository
// ---------------------------------------------------------------------------

const INSPECT_CODES: Record<string, string> = {
  "repo-not-found": "REPOSITORY_NOT_FOUND",
  "repo-not-private": "REPOSITORY_NOT_PRIVATE",
  "no-push-permission": "NO_PUSH_PERMISSION",
  "repo-empty": "REPOSITORY_EMPTY",
  "branch-not-found": "BRANCH_NOT_FOUND",
  "folder-is-file": "FOLDER_IS_FILE",
  "provider-error": "PROVIDER_ERROR",
  "network-unreachable": "NETWORK_UNREACHABLE",
  diverged: "DIVERGED_BRANCH",
};

/** A provider failure as this tool's `{code, message}`, logging any server-only detail. */
function providerRefusal(deps: SiteBackupToolDeps, toolId: string, failure: { readonly code: string; readonly message: string; readonly logDetail?: string }): Refusal {
  logFailureDetail(deps, toolId, failure);
  return { ok: false, code: INSPECT_CODES[failure.code] ?? "PROVIDER_ERROR", message: failure.message };
}

async function inspect(
  deps: SiteBackupToolDeps,
  provider: SourceControlProvider,
  toolId: string,
  input: CredentialedRepositoryTarget & { branch?: string; folder: string }
): Promise<Extract<InspectBackupRepositoryResult, { ok: true }> | Refusal> {
  const result = await provider.inspectBackupRepository(input);
  return result.ok ? result : providerRefusal(deps, toolId, result);
}

// ---------------------------------------------------------------------------
// site_backup_plan
// ---------------------------------------------------------------------------

interface ParsedPlanInput {
  readonly credential: string | undefined;
  /** Checked against the host's rules once the credential names it ({@link validateRepositoryTarget}). */
  readonly owner: unknown;
  readonly repo: unknown;
  readonly branch: string | undefined;
  readonly folder: string | undefined;
  readonly include: SiteBackupInclude;
  readonly commitMessage: string | undefined;
}

function optionalString(raw: Record<string, unknown>, field: string): string | undefined {
  const value = raw[field];
  if (value === undefined) return undefined;
  if (typeof value !== "string") throw new CustomCredentialValidationError(`'${field}' must be a string`);
  return value;
}

/** Every switch defaults to true; anything but a boolean for a known scope is refused. */
function parseInclude(value: unknown): SiteBackupInclude {
  if (value === undefined) return { database: true, media: true, themes: true, plugins: true, settings: true };
  const include = readIncludeSwitches({ raw: requireIncludeRecord({ value }) });
  if (!SITE_BACKUP_SCOPES.some((scope) => include[scope])) throw new CustomCredentialValidationError("'include' switches everything off; there would be nothing to back up");
  return include;
}

/** The `include` object itself: a plain object whose keys are all known scopes. */
function requireIncludeRecord(required: { value: unknown }): Record<string, unknown> {
  const { value } = required;
  if (typeof value !== "object" || value === null || Array.isArray(value)) throw new CustomCredentialValidationError("'include' must be an object of true/false switches");
  const raw = value as Record<string, unknown>;
  const unknownKeys = Object.keys(raw).filter((key) => !(SITE_BACKUP_SCOPES as readonly string[]).includes(key));
  if (unknownKeys.length > 0) throw new CustomCredentialValidationError(`'include' has unknown switch(es): ${unknownKeys.join(", ")} (known: ${SITE_BACKUP_SCOPES.join(", ")})`);
  return raw;
}

/** Each scope's switch, true when absent; a non-boolean is refused by name. */
function readIncludeSwitches(required: { raw: Record<string, unknown> }): SiteBackupInclude {
  const include = {} as Record<(typeof SITE_BACKUP_SCOPES)[number], boolean>;
  for (const scope of SITE_BACKUP_SCOPES) {
    const flag = required.raw[scope];
    if (flag !== undefined && typeof flag !== "boolean") throw new CustomCredentialValidationError(`'include.${scope}' must be true or false`);
    include[scope] = flag ?? true;
  }
  return include;
}

/** The backup folder: repository-relative, never `.git`. The host's own reserved folders
 *  ({@link requireUnreservedFolder}) are checked once the credential names the host. */
function parseFolder(raw: string | undefined): string | undefined {
  if (raw === undefined) return undefined;
  return normalizeWriteFilePath(raw);
}

/**
 * Refuses a backup folder inside one the host reserves (`SourceControlHostFacts.reservedPaths`; the
 * `github` plugin declares `.github`, where GitHub runs workflows from). Before any network call.
 *
 * @throws {CustomCredentialValidationError} naming the reserved folder.
 * @complexity O(r) reserved paths.
 */
function requireUnreservedFolder(folder: string, provider: SourceControlProvider): void {
  const reserved = findReservedPath(folder, provider.reservedPaths);
  if (reserved !== undefined) throw new CustomCredentialValidationError(`the backup folder must not be inside '${reserved}': '${folder}'`);
}

/** @throws {CustomCredentialValidationError} Any malformed field — before any permission check,
 *  decrypt or network call. Owner and repo are the host's to judge, after the credential is resolved. */
function parsePlanInput(rawInput: unknown): ParsedPlanInput {
  const raw = requireInputRecord({ input: rawInput });
  const branch = optionalString(raw, "branch");
  const commitMessage = optionalString(raw, "commitMessage");
  return {
    credential: optionalString(raw, "credential"),
    owner: raw.owner,
    repo: raw.repo,
    branch: branch === undefined ? undefined : validateBranch(branch),
    folder: parseFolder(optionalString(raw, "folder")),
    include: parseInclude(raw.include),
    commitMessage: commitMessage === undefined ? undefined : validateCommitMessage(commitMessage),
  };
}

async function requireBackupPermissions(deps: SiteBackupToolDeps, ctx: SiteBackupCall): Promise<void> {
  await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: PUSH_PERMISSION }, { entityType: DOMAIN });
  await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: CREDENTIAL_WRITE_PERMISSION }, { entityType: "custom-credentials" });
}

const UNAVAILABLE: Refusal = { ok: false, code: "UNAVAILABLE", message: "site backup is not available in this runtime: it has no site folder on disk" };

/** The site's display name from its `config.json`, falling back to the folder name. */
async function readSiteName(siteDir: string): Promise<string> {
  try {
    const config = JSON.parse(await readFile(path.join(siteDir, "config.json"), "utf8")) as { name?: unknown };
    if (typeof config.name === "string" && config.name.trim() !== "") return config.name;
  } catch {
    // A missing or unreadable config.json only costs the nicer name.
  }
  return path.basename(siteDir);
}

/** What the plan tool returns on success: every fact the human should see before confirming. */
function planResult(plan: SiteBackupPlan): Record<string, unknown> {
  const files = [...(plan.database ? [{ path: SITE_BACKUP_DATABASE_PATH, bytes: plan.database.bytes.length }] : []), ...plan.files.map((file) => ({ path: file.path, bytes: file.bytes }))];
  return {
    planned: true,
    planId: plan.planId,
    expiresAt: new Date(plan.expiresAtMs).toISOString(),
    credential: plan.credentialLabel,
    repository: `${plan.owner}/${plan.repo}`,
    visibility: "private",
    branch: plan.repository.branch,
    folder: plan.folder,
    folderExists: plan.repository.folderExists,
    include: plan.include,
    fileCount: files.length,
    totalBytes: plan.totalBytes,
    totalSize: formatByteSize(plan.totalBytes),
    files,
    skipped: plan.skipped,
    notes: SITE_BACKUP_SCOPES.flatMap((scope) => (plan.scopeNotes[scope] ? [plan.scopeNotes[scope]] : [])),
    nextStep:
      `Show the human this plan: ${plan.owner}/${plan.repo}, branch '${plan.repository.branch}', folder '${plan.folder}' ` +
      `(${plan.repository.folderExists ? "its current contents will be replaced" : "new"}), ${files.length} files (${formatByteSize(plan.totalBytes)}), plus anything skipped. ` +
      "Then call site_backup_push with this planId within 10 minutes; it pushes the planned backup immediately (a large one may return inProgress: call it again with the same planId). A tovu-backup.json manifest is added at push time.",
  };
}

/**
 * The plan (`site_backup_plan` and `POST …/site-backups/plan`): every check that can fail, in the order that wastes the least — validate, permissions,
 * credential, repository (so a public repository is refused before a snapshot is taken), database
 * snapshot, disk files, limits — then the in-memory plan.
 *
 * @complexity O(site files) for the walk, O(database size) for the snapshot, four GETs.
 */
export async function planSiteBackup(required: { deps: SiteBackupToolDeps; call: SiteBackupCall }, _optional: Record<string, never> = {}): Promise<unknown> {
  const { deps, call: ctx } = required;
  const input = parsePlanInput(ctx.input);
  await requireBackupPermissions(deps, ctx);
  const sources = deps.siteBackupSources;
  if (!sources) return { planned: false, code: UNAVAILABLE.code, message: UNAVAILABLE.message };

  const credential = await resolveBackupCredential(deps, input.credential);
  if (!credential.ok) return { planned: false, code: credential.code, message: credential.message };

  const folderName = path.basename(sources.siteDir);
  const folder = input.folder ?? normalizeWriteFilePath(folderName);
  const { owner, repo: repoName } = validateRepositoryTarget({ owner: input.owner, repo: input.repo }, credential.provider.validateTarget);
  requireUnreservedFolder(folder, credential.provider);
  const target = backupTarget(credential, owner, repoName);
  const repo = await inspect(deps, credential.provider, PLAN_TOOL_ID, { ...target, ...(input.branch !== undefined ? { branch: input.branch } : {}), folder });
  if (!repo.ok) return { planned: false, code: repo.code, message: repo.message };

  const prepared = await prepareContent(deps, sources, input.include, credential.provider);
  if (!prepared.ok) return { planned: false, code: prepared.code, message: prepared.message };

  return planResult(await savePlan({ deps, ctx, sources, input, folderName, content: { credentialLabel: credential.label, owner, repo: repoName, folder, repository: repo.state, ...prepared.content } }));
}

/**
 * Stores the checked plan under the caller's principal: stamps its creation time, the site's name,
 * schema and version, and the default commit message when none was given.
 */
async function savePlan(required: {
  deps: SiteBackupToolDeps;
  ctx: SiteBackupCall;
  sources: SiteBackupSources;
  input: ParsedPlanInput;
  folderName: string;
  content: Pick<SiteBackupPlan, "credentialLabel" | "owner" | "repo" | "folder" | "repository"> & PreparedContent;
}): Promise<SiteBackupPlan> {
  const { deps, input, content } = required;
  const createdAt = (deps.siteBackupNow?.() ?? new Date()).toISOString();
  const siteName = await readSiteName(required.sources.siteDir);
  return (deps.siteBackupPlanStore ?? DEFAULT_PLAN_STORE).save({
    principalId: required.ctx.principal.id,
    workspaceId: deps.workspaceId,
    content: {
      target: { kind: "repository" },
      credentialLabel: content.credentialLabel,
      owner: content.owner,
      repo: content.repo,
      folder: content.folder,
      commitMessage: input.commitMessage ?? `Tovu site backup: ${siteName} (${createdAt})`,
      repository: content.repository,
      include: input.include,
      database: content.database,
      files: content.files,
      skipped: content.skipped,
      scopeNotes: content.scopeNotes,
      totalBytes: content.totalBytes,
      site: { name: siteName, folderName: required.folderName },
      schema: runtimeSchemaVersion(),
      tovuVersion: required.sources.tovuVersion,
      createdAt,
    },
  });
}

type PreparedContent = Pick<SiteBackupPlan, "database" | "files" | "skipped" | "scopeNotes" | "totalBytes">;

/**
 * The database a backup uploads: the snapshot rebuilt through the share projection.
 * Why: the raw snapshot holds password hashes, sessions, magic-link tokens and sealed vault rows
 * (security review SEC-1). Deleting rows would leave them in free pages, so the backup is a NEW
 * database built by the same policy as share/export (owner decision 2026-10-26: one policy, never
 * a second backup-only scrub). A share refusal (unknown populated table, secret in content) is
 * the plan's refusal.
 *
 * @complexity O(database size).
 */
async function captureBackupDatabase(required: { deps: SiteBackupToolDeps }): Promise<{ ok: true; database: NonNullable<PreparedContent["database"]> } | Refusal> {
  const { deps } = required;
  const snapshot = await captureDatabaseSnapshot({ dbOps: deps.dbOps, scopeId: SNAPSHOT_SCOPE_ID });
  if (!snapshot.ok) {
    logFailureDetail(deps, PLAN_TOOL_ID, { code: "database-snapshot", ...(snapshot.logDetail !== undefined ? { logDetail: snapshot.logDetail } : {}) });
    return { ok: false, code: "DATABASE_SNAPSHOT_FAILED", message: snapshot.message };
  }
  try {
    const projected = await (deps.siteBackupSanitize ?? sanitizeShareDatabase)({ snapshot: snapshot.bytes });
    return { ok: true, database: { bytes: projected.bytes, watermarkAtCapture: snapshot.watermarkAtCapture } };
  } catch (err) {
    if (err instanceof SiteShareRefusal) return { ok: false, code: err.code, message: err.message };
    throw err;
  }
}

/**
 * The bytes a plan holds: the sanitized database (when included), the disk files, and the limit
 * check over both, so the limits measure the uploaded bytes.
 *
 * @complexity O(database size + site files).
 */
async function prepareContent(deps: SiteBackupToolDeps, sources: SiteBackupSources, include: SiteBackupInclude, host: SiteBackupHostLimit): Promise<{ ok: true; content: PreparedContent } | Refusal> {
  let database: PreparedContent["database"] = null;
  if (include.database) {
    const captured = await captureBackupDatabase({ deps });
    if (!captured.ok) return captured;
    database = captured.database;
  }
  const collected = await collectSiteBackupFiles({ sources, include });
  const fitting = skipOversizedFiles(collected.files, host);
  const limits = checkSiteBackupLimits([...(database ? [{ path: SITE_BACKUP_DATABASE_PATH, bytes: database.bytes.length }] : []), ...fitting.files], host);
  if (!limits.ok) return { ok: false, code: "LIMIT_EXCEEDED", message: limits.message };
  return { ok: true, content: { database, files: fitting.files, skipped: [...collected.skipped, ...fitting.skipped], scopeNotes: collected.scopeNotes, totalBytes: limits.totalBytes } };
}

// ---------------------------------------------------------------------------
// site_backup_push
// ---------------------------------------------------------------------------

export type PushResult =
  | { pushed: true; commitSha: string; commitUrl: string; repository: string; branch: string; folder: string; filesWritten: number; totalBytes: number }
  | { pushed: false; cancelled: true }
  | { pushed: false; cancelled: false; reason: "expired" | "abandoned" }
  | { pushed: false; cancelled: false; inProgress: true; planId: string; progress: SiteBackupPushProgress; message: string }
  | { pushed: false; cancelled: false; code: string; message: string };

function pushRefusal(refusal: Refusal): PushResult {
  return refusal.code === CANCELLED.code ? { pushed: false, cancelled: false, reason: "abandoned" } : { pushed: false, cancelled: false, code: refusal.code, message: refusal.message };
}

/**
 * The authorized push: re-resolve the credential, re-check the repository (still
 * private, branch not moved), upload, commit on the PLAN's parent. Stopping (`signal`) takes effect
 * between files and before the commit, never half-way through one.
 *
 * @complexity O(total bytes); see `push-engine.ts` for the uploads, plus a few fixed tree writes,
 *   one commit and one ref update.
 */
async function pushPlannedBackup(deps: SiteBackupToolDeps, plan: SiteBackupPlan, run: { signal: AbortSignal; progress: SiteBackupPushProgress }): Promise<PushResult> {
  const credential = await resolveBackupCredential(deps, plan.credentialLabel);
  if (!credential.ok) return pushRefusal(credential);
  const target = backupTarget(credential, plan.owner, plan.repo);

  const repo = await inspect(deps, credential.provider, SITE_BACKUP_PUSH_TOOL_ID, { ...target, branch: plan.repository.branch, folder: plan.folder });
  if (!repo.ok) return pushRefusal(repo);
  if (repo.state.parentCommitSha !== plan.repository.parentCommitSha) {
    return pushRefusal({
      ok: false,
      code: "DIVERGED_BRANCH",
      message: `branch '${plan.repository.branch}' moved since the backup was planned (someone pushed to it). Nothing was written. Call site_backup_plan again.`,
    });
  }

  const uploaded = await uploadPlannedContent({
    provider: credential.provider,
    target,
    plan,
    signal: run.signal,
    progress: run.progress,
    toRefusal: (failure) => providerRefusal(deps, SITE_BACKUP_PUSH_TOOL_ID, failure),
  });
  if (!uploaded.ok) return pushRefusal(uploaded);
  if (run.signal.aborted) return pushRefusal(CANCELLED);

  const committed = await credential.provider.commitBackupTree({
    ...target,
    branch: plan.repository.branch,
    folder: plan.folder,
    commitMessage: plan.commitMessage,
    parentCommitSha: plan.repository.parentCommitSha,
    baseTreeSha: plan.repository.baseTreeSha,
    htmlUrl: plan.repository.htmlUrl,
    entries: uploaded.entries,
  });
  if (!committed.ok) return pushRefusal(providerRefusal(deps, SITE_BACKUP_PUSH_TOOL_ID, committed));
  return {
    pushed: true,
    commitSha: committed.commitSha,
    commitUrl: committed.commitUrl,
    repository: `${plan.owner}/${plan.repo}`,
    branch: plan.repository.branch,
    folder: plan.folder,
    filesWritten: uploaded.entries.length,
    totalBytes: uploaded.entries.reduce((sum, entry) => sum + entry.bytes, 0),
  };
}

const PLAN_TAKE_MESSAGES = {
  PLAN_NOT_FOUND: "no backup plan with that planId is waiting (a planId works once, for this principal, and a server restart drops plans). Call site_backup_plan again.",
  PLAN_EXPIRED: "that backup plan expired (plans last 10 minutes). Call site_backup_plan again.",
} as const;

/** How long one push call waits for its job before reporting progress: under the 6-minute cut-off
 *  of a delegated tool call (`push-jobs.ts`), with room for the checks before the upload. */
export const PUSH_WAIT_MS = 4 * 60 * 1000;

const DEFAULT_PUSH_JOBS = new SiteBackupPushJobs<PushResult>();

/** What a call returns while its job is still uploading. */
function inProgressResult(planId: string, progress: SiteBackupPushProgress, elapsedMs: number): PushResult {
  return {
    pushed: false,
    cancelled: false,
    inProgress: true,
    planId,
    progress,
    message:
      `Still uploading after ${Math.round(elapsedMs / 1000)} s: ${progress.filesDone} of ${progress.filesTotal} files (${formatByteSize(progress.bytesDone)} of ${formatByteSize(progress.bytesTotal)}). ` +
      "Nothing is committed until every file is up. Call site_backup_push again with the same planId to keep waiting; it does not start a second upload.",
  };
}

function pushWaitBudget({ deps, waitMs }: { deps: SiteBackupToolDeps; waitMs: number | undefined }, _options = {}): number {
  return waitMs ?? deps.siteBackupPushWaitMs ?? PUSH_WAIT_MS;
}

/**
 * The push (`site_backup_push` and `POST …/site-backups/push`): consume the principal-bound plan and start its job — or, for a planId whose job is
 * still running, wait on that job — then report its outcome or its progress.
 *
 * @complexity O(1) plan and job lookup; then see {@link pushPlannedBackup}.
 */
export async function pushSiteBackup(
  required: { deps: SiteBackupToolDeps; call: SiteBackupCall },
  optional: { waitMs?: number } = {}
): Promise<PushResult> {
  const { deps, call: ctx } = required;
  const planId = requireString({ input: requireInputRecord({ input: ctx.input }), key: "planId" });
  await requireBackupPermissions(deps, ctx);
  if (ctx.signal.aborted) return { pushed: false, cancelled: false, reason: "abandoned" };

  const jobs = deps.siteBackupPushJobs ?? DEFAULT_PUSH_JOBS;
  const key = { planId, principalId: ctx.principal.id, workspaceId: deps.workspaceId };
  let job = jobs.find(key);
  if (!job) {
    const taken = (deps.siteBackupPlanStore ?? DEFAULT_PLAN_STORE).take(key);
    if (!taken.ok) return { pushed: false, cancelled: false, code: taken.code, message: PLAN_TAKE_MESSAGES[taken.code] };
    job = jobs.start(key, initialPushProgress(taken.plan), (signal, progress) => pushPlannedBackup(deps, taken.plan, { signal, progress }));
  }

  const waited = await jobs.wait(job, { signal: ctx.signal, budgetMs: pushWaitBudget({ deps, waitMs: optional.waitMs }) });
  if (waited.state === "done") return waited.result;
  if (waited.state === "abandoned") return { pushed: false, cancelled: false, reason: "abandoned" };
  return inProgressResult(planId, waited.progress, waited.elapsedMs);
}

import { createYauzlAgentPluginArchiveReader, type YauzlPort, type YauzlEntry } from "@jini-ai/agent-plugins/lifecycle/yauzl";
import type * as yauzl from "yauzl";
import { SiteShareRefusal } from "./share-policy.js";

interface ShareZipEntry extends YauzlEntry {
  generalPurposeBitFlag: number;
  compressionMethod: number;
  relativeOffsetOfLocalHeader: number;
  extraFields: readonly { id: number }[];
}
// @types/yauzl predates 3.4's promise/iterator API. Keep that adapter gap here.
interface ShareYauzl {
  fromBufferPromise(buffer: Buffer, options: { lazyEntries: boolean; validateEntrySizes: boolean; strictFileNames: boolean }): Promise<{
    eachEntry(): AsyncIterable<ShareZipEntry>;
    openReadStreamPromise(entry: ShareZipEntry): Promise<AsyncIterable<Uint8Array>>;
    close(): void;
  }>;
}

/** Refuses an entry whose local header does not restate its central entry. O(name). */
function requireMatchingLocalHeader(required: { buffer: Buffer; entry: ShareZipEntry }): void {
  const { buffer, entry } = required;
  const local = entry.relativeOffsetOfLocalHeader;
  if (local < 0 || local + 30 > buffer.length || buffer.readUInt32LE(local) !== 0x04034b50 ||
      buffer.readUInt16LE(local + 6) !== entry.generalPurposeBitFlag || buffer.readUInt16LE(local + 8) !== entry.compressionMethod ||
      buffer.subarray(local + 30, local + 30 + buffer.readUInt16LE(local + 26)).toString("utf8") !== entry.fileName) {
    throw new SiteShareRefusal({ code: "UNSAFE_ARCHIVE", message: "ZIP local and central entry headers disagree." });
  }
}

/** Parses the local header's own extra fields; refuses metadata that runs past the archive. O(extra bytes). */
function readLocalExtraFields(required: { buffer: Buffer; entry: ShareZipEntry; yauzl: typeof yauzl }): readonly { id: number }[] {
  const { buffer } = required;
  const local = required.entry.relativeOffsetOfLocalHeader;
  const extraStart = local + 30 + buffer.readUInt16LE(local + 26);
  const extraEnd = extraStart + buffer.readUInt16LE(local + 28);
  if (extraEnd > buffer.length) throw new SiteShareRefusal({ code: "UNSAFE_ARCHIVE", message: "Truncated ZIP local entry metadata." });
  return required.yauzl.parseExtraFields(buffer.subarray(extraStart, extraEnd));
}

/** A trailing-slash name must be an empty, non-regular entry; any other name must not be a directory. */
function hasAmbiguousDirectoryMetadata(required: { entry: ShareZipEntry; type: number }): boolean {
  if (required.entry.fileName.endsWith("/")) return required.entry.uncompressedSize !== 0 || required.type === 0x8000;
  return required.type === 0x4000;
}

/** True for encryption, links, special entries, or ambiguous filename metadata. O(extra fields). */
function hasUnsupportedFeature(required: { entry: ShareZipEntry; localExtra: readonly { id: number }[] }): boolean {
  const { entry } = required;
  const type = (entry.externalFileAttributes >>> 16) & 0xf000;
  // PKWARE Unix and ASi Unix fields can encode links independently of st_mode.
  // Reject these optional variants wholesale; v1 shares never emit them.
  return (entry.generalPurposeBitFlag & (1 | 64 | 8192)) !== 0 ||
    ![0, 0x8000, 0x4000].includes(type) ||
    [...entry.extraFields, ...required.localExtra].some(field => [0x000d, 0x756e, 0x7075, 0x9901].includes(field.id)) ||
    hasAmbiguousDirectoryMetadata({ entry, type });
}

/** Tovu share-profile preflight over the existing Jini reader, not another ZIP decoder.
 * Reject ZIP features the portable profile cannot represent before Jini projects entries.
 * Strict filenames preserve backslashes for rejection rather than silently rewriting them.
 * @complexity O(entries); decompression and byte accounting remain with the reader/verifier.
 */
export function createShareArchiveReader(required: { yauzl: typeof yauzl }, _options: Record<string, never> = {}) {
  const port: YauzlPort = {
    async fromBufferPromise(buffer, options) {
      const zip = await (required.yauzl as unknown as ShareYauzl).fromBufferPromise(buffer, { ...options, strictFileNames: true });
      return {
        async *eachEntry() {
          for await (const entry of zip.eachEntry()) {
            requireMatchingLocalHeader({ buffer, entry });
            const localExtra = readLocalExtraFields({ buffer, entry, yauzl: required.yauzl });
            if (hasUnsupportedFeature({ entry, localExtra })) {
              throw new SiteShareRefusal({ code: "UNSAFE_ARCHIVE", message: "Share ZIP contains encryption, a link, a special entry, or ambiguous filename metadata." });
            }
            yield entry;
          }
        },
        openReadStreamPromise: entry => zip.openReadStreamPromise(entry as ShareZipEntry),
        close: () => zip.close(),
      };
    },
  };
  return createYauzlAgentPluginArchiveReader({ yauzl: port });
}

import fs from "node:fs";
import type { HttpClientPort } from "#src/platform/http/index";
import { assertPortableSiteName, reconcileSiteCreation } from "#src/platform/site-dir/site-registry";
import type { SitesWorkspace } from "#src/platform/site-dir/sites-home";
import type { SiteImportRegistry, SiteImportRecord } from "./import-registry.js";
import { SHARE_LIMITS, SiteShareRefusal } from "./share-policy.js";

/**
 * @file The import backend's individual steps: input parsing, the private staging budget, the
 * share download, upload consumption, interrupted-creation recovery and the public row view.
 * Each takes its ports explicitly; `import-backend.ts` sequences them under the import lock.
 */

export type SiteImportSource = { url: string } | { uploadId: string };
export interface SiteImportView {
  importId: string; source: SiteImportSource; newSiteId: string | null; newSiteName: string | null;
  state: SiteImportRecord["status"]; status: SiteImportRecord["status"]; createdAt: string;
  warnings?: readonly string[];
  setupUrl?: string; adminUrl?: string | null; error?: string; instructions: string;
}
export interface ParsedSiteImportInput { source: SiteImportSource; displayName?: string; requestId?: string }

export function refusal(code: string, message: string): never { throw new SiteShareRefusal({ code, message }); }

const INPUT_KEYS = ["url", "uploadId", "displayName", "requestId"];
const REQUEST_ID = /^[a-zA-Z0-9_-]{1,128}$/;
const UPLOAD_ID = /^[a-f0-9-]{36}$/;
const ARCHIVE_CONTENT_TYPES = ["application/zip", "application/x-zip-compressed", "application/octet-stream"];

/** Source union is enforced at every remote boundary; server paths are never accepted. */
export function parseImportInput(required: { input: unknown }): ParsedSiteImportInput {
  const input = requireSourceShape(required.input);
  if (input.displayName !== undefined && !isDisplayName(input.displayName)) refusal("INVALID_INPUT", "displayName must be 1..200 characters.");
  if (input.requestId !== undefined && (typeof input.requestId !== "string" || !REQUEST_ID.test(input.requestId))) refusal("INVALID_INPUT", "requestId must be 1..128 letters, digits, dashes or underscores.");
  const source = input.url !== undefined ? parseUrlSource({ url: input.url }) : parseUploadSource({ uploadId: input.uploadId });
  return { source, ...(input.displayName !== undefined ? { displayName: input.displayName as string } : {}), ...(input.requestId !== undefined ? { requestId: input.requestId as string } : {}) };
}

function requireSourceShape(value: unknown): Record<string, unknown> {
  const input = value as Record<string, unknown>;
  if (!input || typeof input !== "object" || Array.isArray(input) || Object.keys(input).some(key => !INPUT_KEYS.includes(key)) ||
      (input.url !== undefined) === (input.uploadId !== undefined)) refusal("INVALID_INPUT", "Provide exactly one source: url or uploadId; optional displayName and requestId only.");
  return input;
}

function isDisplayName(value: unknown): boolean {
  return typeof value === "string" && Boolean(value.trim()) && value.length <= 200;
}

function parseUrlSource(required: { url: unknown }): SiteImportSource {
  if (typeof required.url !== "string" || required.url.length > 4096) refusal("INVALID_INPUT", "url must be an HTTPS share URL.");
  let url: URL;
  try { url = new URL(required.url); } catch { refusal("INVALID_INPUT", "url must be an HTTPS share URL."); }
  if (url.protocol !== "https:" || url.username || url.password || url.hash) refusal("INVALID_INPUT", "Import URLs require HTTPS without credentials or fragments.");
  return { url: url.href };
}

function parseUploadSource(required: { uploadId: unknown }): SiteImportSource {
  if (typeof required.uploadId !== "string" || !UPLOAD_ID.test(required.uploadId)) refusal("INVALID_INPUT", "uploadId must come from the authenticated ZIP upload endpoint.");
  return { uploadId: required.uploadId };
}

/** Refuses when the volume holding `dir` has less than three expanded-archive caps free. */
export function requireFreeSpace(required: { dir: string; message: string }): void {
  const space = fs.statfsSync(required.dir);
  if (space.bavail * space.bsize < SHARE_LIMITS.maxExpandedBytes * 3) refusal("INSUFFICIENT_STORAGE", required.message);
}

/** At most four private payloads (uploads or stages) and 900 MiB free before retaining more bytes. */
export function requireStagingBudget(required: { registry: SiteImportRegistry }): void {
  required.registry.expire({});
  const payloads = fs.readdirSync(required.registry.directory).filter(name => name.endsWith(".upload.zip") || name.endsWith(".stage"));
  if (payloads.length >= 4) refusal("BUSY", "Four imports are staged. Complete owner setup or wait for expiry before uploading another.");
  requireFreeSpace({ dir: required.registry.directory, message: "Import requires 900 MiB of free private staging space." });
}

/** The caller's signal (when given) combined with this step's own deadline. */
export function deadlineSignal(required: { timeoutMs: number }, optional: { signal?: AbortSignal | undefined } = {}): AbortSignal {
  return AbortSignal.any([...(optional.signal ? [optional.signal] : []), AbortSignal.timeout(required.timeoutMs)]);
}

/** Marks one unconsumed upload as consumed by `importId` and returns its id. */
export function consumeUpload(required: { registry: SiteImportRegistry; uploadId: string; principalId: string; importId: string }): string {
  const upload = required.registry.getUpload({ uploadId: required.uploadId, principalId: required.principalId });
  if (upload.consumedBy) refusal("UPLOAD_USED", "This upload was already imported. Use the original requestId or upload again for a separate site.");
  required.registry.saveUpload({ row: { ...upload, consumedBy: required.importId } });
  return upload.uploadId;
}

/**
 * Downloads a share archive through the guarded HTTP port: a bounded identity GET whose body must
 * be complete and labelled ZIP or binary.
 * @complexity O(archive bytes), at most 300 MiB.
 */
export async function downloadShareArchive(required: { http: HttpClientPort; url: string; signal: AbortSignal }): Promise<Buffer> {
  const response = await required.http.send({ method: "GET", url: required.url, headers: { Accept: "application/zip", "Accept-Encoding": "identity" }, idleTimeoutMs: 30_000, totalDeadlineMs: 120_000, maxResponseBytes: SHARE_LIMITS.maxArchiveBytes, signal: required.signal });
  if (response.status !== 200 || !response.bodyBytes || response.bodyBytesTruncated !== false) refusal("DOWNLOAD_FAILED", "Share download failed or exceeded the 300 MiB archive cap.");
  const contentType = Object.entries(response.headers).find(([name]) => name.toLowerCase() === "content-type")?.[1]?.split(";", 1)[0]?.trim().toLowerCase();
  if (!contentType || !ARCHIVE_CONTENT_TYPES.includes(contentType)) refusal("INVALID_CONTENT_TYPE", "Share download must have a ZIP or binary Content-Type.");
  return Buffer.from(response.bodyBytes);
}

/**
 * Only the lock holder may classify a verifying or creating row as interrupted, never a concurrent
 * reader: both statuses exist only while the import lock is held, so the holder finding one means
 * the previous holder crashed. A verifying row failed; a creating row with an allocation is
 * reconciled against the workspace, one without it failed. Either way its stage is discarded.
 */
export async function reconcileInterruptedImports(required: { registry: SiteImportRegistry; workspace: SitesWorkspace; put: (row: SiteImportRecord) => void }): Promise<void> {
  for (const row of required.registry.list({})) {
    if (row.status === "verifying") required.put({ ...row, status: "failed", error: "Archive verification was interrupted. Import the archive again." });
    else if (row.status === "creating") required.put(await reconcileCreatingRow({ row, workspace: required.workspace }));
    else continue;
    fs.rmSync(required.registry.stagePath(row), { recursive: true, force: true });
  }
}

/** The settled row for an interrupted creation: kept when the workspace has the site, else failed. */
async function reconcileCreatingRow(required: { row: SiteImportRecord; workspace: SitesWorkspace }): Promise<SiteImportRecord> {
  const { row } = required;
  const status = row.creation ? await reconcileSiteCreation({ allocation: row.creation, workspace: required.workspace }) : "failed";
  return { ...row, status, ...(status === "failed" ? { newSiteId: null, newSiteName: null, error: "Site creation was interrupted and rolled back. Import the archive again." } : {}) };
}

/** A folder-safe site name from the display name; non-Latin names fall back to `imported-site`.
 * @throws {ValidationError} Windows device names or trailing dots/spaces, before or after slugification.
 * @complexity O(display name length), no I/O.
 */
export function importSiteSlug(required: { displayName: string }, _optional = {}): string {
  assertPortableSiteName({ name: required.displayName });
  const slug = required.displayName.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 80) || "imported-site";
  assertPortableSiteName({ name: slug });
  return slug;
}

/** The owner-setup gate: only a pending import, and never without a new password. */
export function requireOwnerSetup(required: { row: SiteImportRecord; adminPassword: unknown }): void {
  if (required.row.status !== "needs-owner") refusal("INVALID_STATE", "This import is not awaiting owner setup. Import the archive again if it failed or expired.");
  if (required.adminPassword === undefined || required.adminPassword === "tovu-dev") refusal("INVALID_PASSWORD", "Choose a new owner password; the development default cannot be used for an import.");
}

/** Owner and restore are committed; a start failure is recorded, never retried as a new site. */
export async function startImportedSite(required: { row: SiteImportRecord; name: string; startSite: (required: { name: string }) => Promise<{ adminUrl: string | null }> }): Promise<SiteImportRecord> {
  try {
    const started = await required.startSite({ name: required.name });
    return { ...required.row, adminUrl: started.adminUrl, ...(started.adminUrl ? {} : { error: "Site created; start it from Sites to open admin." }) };
  } catch { return { ...required.row, error: "Site created with its owner. Start it from Sites to open admin." }; }
}

/** The public view of a stored import row. */
export function siteImportView(required: { row: SiteImportRecord }, optional: { setupBase?: string | undefined }): SiteImportView {
  const { row } = required;
  const pending = row.status === "needs-owner";
  return {
    importId: row.importId, source: row.source,
    newSiteId: row.newSiteId, newSiteName: row.newSiteName, state: row.status, status: row.status, createdAt: row.createdAt,
    ...(pending ? { setupUrl: (optional.setupBase ?? "/api/admin/v1/site-imports") + "/" + row.importId + "/owner" } : {}),
    adminUrl: row.adminUrl, error: row.error,
    instructions: pending ? "Open setupUrl while signed in as the importing principal and choose a new owner password privately. The site is unavailable until setup completes." : "Open adminUrl when available. Imported extensions remain quarantined and need explicit review before activation.",
  };
}

import fs from "node:fs";
import path from "node:path";
import { createDurableJsonFile, createNodeDurableJsonPorts, withFileLock } from "@jini-ai/platform/fs";
import type { SiteCreationAllocation } from "#src/platform/site-dir/site-registry";
import { SiteShareRefusal } from "./share-policy.js";

export interface SiteImportRecord {
  importId: string;
  principalId: string;
  requestId?: string;
  source: { url: string } | { uploadId: string };
  newSiteId: string | null;
  newSiteName: string | null;
  displayName: string;
  /** Private write-ahead allocation, supplied only by the existing site lifecycle. */
  creation?: SiteCreationAllocation;
  status: "verifying" | "needs-owner" | "creating" | "ready" | "failed";
  createdAt: string;
  expiresAt: number;
  adminUrl?: string | null;
  error?: string;
}
export interface SiteImportUpload { uploadId: string; principalId: string; createdAt: number; consumedBy?: string }
const ID = /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
/** A staged upload is claimable for one hour after it is saved. */
const UPLOAD_TTL_MS = 3600_000;
/** The statuses whose import may still own a `<id>.stage` directory. */
const STAGED_STATUSES: ReadonlySet<SiteImportRecord["status"]> = new Set(["verifying", "needs-owner", "creating"]);
/** The import id behind an `<id>.json` history record name; undefined for every other file. */
function recordIdOf(name: string): string | undefined {
  const id = name.slice(0, -5);
  return name.endsWith(".json") && ID.test(id) ? id : undefined;
}

/** CMS import history and private staging. Jini owns atomic JSON replacement and locking.
 * No public list, caller-controlled filesystem path, or source URL in a filename.
 */
export class SiteImportRegistry {
  readonly directory: string;
  constructor(required: { directory: string }, _options: Record<string, never> = {}) {
    this.directory = path.resolve(required.directory);
    fs.mkdirSync(this.directory, { recursive: true, mode: 0o700 });
    fs.chmodSync(this.directory, 0o700);
  }
  private file(id: string, suffix: string) {
    if (!ID.test(id)) throw new SiteShareRefusal({ code: "INVALID_INPUT", message: "Invalid import or upload id." });
    return path.join(this.directory, id + suffix);
  }
  private store(id: string, suffix: string) {
    return createDurableJsonFile({ ...createNodeDurableJsonPorts({}), filePath: this.file(id, suffix), notices: { prefix: "Site imports", lockTimeout: () => "Import registry is busy." } });
  }
  /** Reads one history record; an unreadable file is refused (with the caller's wording) and left in place. */
  private readRecord(required: { importId: string; unreadable: string }): SiteImportRecord | undefined {
    const read = this.store(required.importId, ".json").read({});
    if (read.state === "unreadable") throw new SiteShareRefusal({ code: "REGISTRY_UNREADABLE", message: required.unreadable });
    return read.state === "ok" ? read.value as SiteImportRecord : undefined;
  }
  get(required: { importId: string; principalId: string }, _options: Record<string, never> = {}): SiteImportRecord {
    const row = this.readRecord({ importId: required.importId, unreadable: "Import record is unreadable; it was left untouched." });
    if (!row || row.principalId !== required.principalId) throw new SiteShareRefusal({ code: "NOT_FOUND", message: "Import not found." });
    return row;
  }
  put(required: { row: SiteImportRecord }, _options: Record<string, never> = {}): void {
    this.store(required.row.importId, ".json").write({ value: required.row });
    fs.chmodSync(this.file(required.row.importId, ".json"), 0o600);
  }
  list(required: { principalId?: string }, _options: Record<string, never> = {}): SiteImportRecord[] {
    return fs.readdirSync(this.directory).map(recordIdOf).filter(id => id !== undefined).flatMap(importId => {
      const row = this.readRecord({ importId, unreadable: "Import history is unreadable; it was left untouched." });
      return row && (required.principalId === undefined || row.principalId === required.principalId) ? [row] : [];
    }).sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  }
  uploadPath(required: { uploadId: string }, _options: Record<string, never> = {}): string { return this.file(required.uploadId, ".upload.zip"); }
  stagePath(required: { importId: string }, _options: Record<string, never> = {}): string { return this.file(required.importId, ".stage"); }
  saveUpload(required: { row: SiteImportUpload }, _options: Record<string, never> = {}): void { this.store(required.row.uploadId, ".upload.json").write({ value: required.row }); }
  getUpload(required: { uploadId: string; principalId: string }, _options: Record<string, never> = {}): SiteImportUpload {
    const read = this.store(required.uploadId, ".upload.json").read({});
    const row = read.state === "ok" ? read.value as SiteImportUpload : undefined;
    if (!row || row.principalId !== required.principalId || row.createdAt + UPLOAD_TTL_MS < Date.now()) throw new SiteShareRefusal({ code: "NOT_FOUND", message: "Upload not found or expired. Upload the ZIP again." });
    return row;
  }
  /** One process-wide/disk-backed transfer lane bounds buffered memory and cross-process retries. */
  async exclusive<T>(required: { run: () => Promise<T> }, _options: Record<string, never> = {}): Promise<T> {
    return withFileLock({ lockPath: path.join(this.directory, ".import.lock"), run: required.run }, { staleMs: Infinity });
  }
  /** Removes an upload (payload, then record) once it is past its one-hour claim window. */
  private expireUpload(required: { id: string }): void {
    if (!ID.test(required.id)) return;
    const read = this.store(required.id, ".upload.json").read({});
    if (read.state !== "ok" || (read.value as SiteImportUpload).createdAt + UPLOAD_TTL_MS >= Date.now()) return;
    fs.rmSync(this.uploadPath({ uploadId: required.id }), { force: true });
    fs.rmSync(this.file(required.id, ".upload.json"), { force: true });
  }
  /** Fails an owner setup past its deadline and discards its stage; history keeps the named failure. */
  private expireOwnerSetup(required: { importId: string }): void {
    const read = this.store(required.importId, ".json").read({});
    if (read.state !== "ok") return;
    const row = read.value as SiteImportRecord;
    if (row.status === "needs-owner" && row.expiresAt < Date.now()) {
      fs.rmSync(this.stagePath(row), { recursive: true, force: true });
      this.put({ row: { ...row, status: "failed", error: "Owner setup expired. Import the archive again." } });
    }
  }
  /** Removes a ZIP whose metadata is missing or unreadable: a crash between the two writes. */
  private removeOrphanUpload(required: { id: string }): void {
    if (!ID.test(required.id) || this.store(required.id, ".upload.json").read({}).state === "ok") return;
    fs.rmSync(this.uploadPath({ uploadId: required.id }), { force: true });
  }
  /** Removes a stage no in-progress record owns; an unreadable record keeps its stage untouched. */
  private removeOrphanStage(required: { importId: string }): void {
    if (!ID.test(required.importId)) return;
    const read = this.store(required.importId, ".json").read({});
    if (read.state === "unreadable") return;
    const status = read.state === "ok" ? (read.value as SiteImportRecord | null)?.status : undefined;
    if (status === undefined || !STAGED_STATUSES.has(status)) fs.rmSync(this.stagePath(required), { recursive: true, force: true });
  }
  /** Expired payloads are disposable; retain history with a named failure rather than dead setup.
   * Crash leftovers (a ZIP without metadata, a stage without a pending record) are removed too, so
   * they never pin the staging budget. Callers hold the import lock: an upload writes its ZIP
   * before its metadata, so an unlocked sweep could remove a payload that is still being saved.
   */
  expire(_required: Record<string, never>, _options: Record<string, never> = {}): void {
    for (const filename of fs.readdirSync(this.directory)) {
      const importId = recordIdOf(filename);
      if (filename.endsWith(".upload.json")) this.expireUpload({ id: filename.slice(0, -12) });
      else if (filename.endsWith(".upload.zip")) this.removeOrphanUpload({ id: filename.slice(0, -11) });
      else if (filename.endsWith(".stage")) this.removeOrphanStage({ importId: filename.slice(0, -6) });
      else if (importId !== undefined) this.expireOwnerSetup({ importId });
    }
  }
}

import fs from "node:fs";
import path from "node:path";
import { validateSharePath } from "./share-file-policy.js";
import { checkSourceDirContainment } from "#src/features/theme/validation/structure";
import { loadTheme } from "#src/features/theme/theme";

/**
 * @file Where each staged import file may land: the live site, or the unserved
 * `.import-quarantine/` tree. Untrusted extensions never enter a discovery/activation root.
 */

/** Theme ids (`<tier>/<name>`) to quarantine, and each compiled theme's authored-source prefix. */
export interface ThemeManifestFindings {
  readonly quarantinedThemes: ReadonlySet<string>;
  readonly compiledSources: ReadonlyMap<string, string>;
}

type ThemeManifestVerdict = { kind: "plain" } | { kind: "quarantine" } | { kind: "compiled"; sourcePrefix: string };
/** The manifest's `build` exactly as staged; its fields are re-checked before use. */
type CompiledBuild = Parameters<typeof checkSourceDirContainment>[0]["build"];
const PLAIN: ThemeManifestVerdict = { kind: "plain" };
const QUARANTINE: ThemeManifestVerdict = { kind: "quarantine" };

const THEME_MANIFEST = /^themes\/((?:__original-themes__\/)?(?:static|declarative))\/([^/]+)\/theme.json$/;
const THEME_FILE = /^themes\/((?:__original-themes__\/)?(?:static|declarative))\/([^/]+)\/(.+)$/;
const THEME_ID = /^themes\/((?:__original-themes__\/)?(?:static|declarative)\/[^/]+)\//;
const STATIC_ASSET = /\.(?:html?|css|m?js|json|webmanifest|xml|liquid|map|png|jpe?g|gif|webp|avif|svg|ico|woff2?|ttf|otf|txt|md|mp4|webm|pdf)$/i;

/**
 * Reads every staged static/declarative `theme.json`: a tier that disagrees with its folder, an
 * unreadable manifest, or an unsafe/invalid compiled build quarantines the theme.
 * @complexity O(themes × theme validation).
 */
export function inspectThemeManifests(required: { root: string; files: readonly string[] }): ThemeManifestFindings {
  const quarantinedThemes = new Set<string>();
  const compiledSources = new Map<string, string>();
  for (const file of required.files) {
    const match = THEME_MANIFEST.exec(file);
    if (!match) continue;
    const id = match[1] + "/" + match[2];
    const verdict = inspectThemeManifest({ root: required.root, file, tier: match[1]!, name: match[2]! });
    if (verdict.kind === "quarantine") quarantinedThemes.add(id);
    if (verdict.kind === "compiled") compiledSources.set(id, verdict.sourcePrefix);
  }
  return { quarantinedThemes, compiledSources };
}

function inspectThemeManifest(required: { root: string; file: string; tier: string; name: string }): ThemeManifestVerdict {
  try {
    const manifest = JSON.parse(fs.readFileSync(path.join(required.root, required.file), "utf8"));
    if (manifest.tier !== required.tier.split("/").at(-1)) return QUARANTINE;
    if (manifest.build?.source !== "compiled") return PLAIN;
    return inspectCompiledTheme({ root: required.root, id: required.tier + "/" + required.name, name: required.name, manifest });
  } catch { return QUARANTINE; }
}

/** @throws whatever the share path policy or theme loader throws; the caller quarantines on it. */
function inspectCompiledTheme(required: { root: string; id: string; name: string; manifest: { tier: unknown; build: CompiledBuild } }): ThemeManifestVerdict {
  const { build } = required.manifest;
  if (required.manifest.tier !== "static" || typeof build.sourceDir !== "string" || checkSourceDirContainment({ build, schemaVersion: 2 }).length) return QUARANTINE;
  // A trailing '/' is an empty segment, so this refusal also guarantees `sourcePrefix` below.
  validateSharePath({ path: build.sourceDir });
  // The theme owner treats compiled output as static, never as a server code tier. Reuse its
  // artifact validation; preserve authored build source ONLY in the quarantine tree.
  const theme = loadTheme({ themeDir: path.join(required.root, "themes", required.id), id: required.name, source: "site" });
  if (theme.status === "invalid") return QUARANTINE;
  return { kind: "compiled", sourcePrefix: "themes/" + required.id + "/" + build.sourceDir + "/" };
}

/**
 * Every staged theme tree that may go live: all its files are supported static assets (compiled
 * source excepted) and its manifest was not quarantined.
 * @complexity O(files).
 */
export function liveThemeTrees(required: { files: readonly string[]; findings: ThemeManifestFindings }): Set<string> {
  const live = new Set<string>();
  const quarantined = new Set(required.findings.quarantinedThemes);
  for (const file of required.files) {
    const match = THEME_FILE.exec(file);
    if (!match) continue;
    const id = match[1] + "/" + match[2];
    live.add(id);
    if (isCompiledSource({ file, theme: id, compiledSources: required.findings.compiledSources })) continue;
    // Browser JS is an ordinary static asset, unlike TS/JS modules in a code theme. The whole
    // tree is quarantined if it includes build source or declares a different executable tier.
    if (!STATIC_ASSET.test(match[3]!)) quarantined.add(id);
  }
  for (const id of quarantined) live.delete(id);
  return live;
}

function isCompiledSource(required: { file: string; theme: string; compiledSources: ReadonlyMap<string, string> }): boolean {
  const prefix = required.compiledSources.get(required.theme);
  return prefix !== undefined && required.file.startsWith(prefix);
}

/**
 * The site-relative destination of one staged file, or `null` when it is never restored.
 * Uploads and live theme files keep their path; everything else lands under `.import-quarantine/`.
 */
export function restoreDestination(required: { file: string; liveThemes: ReadonlySet<string>; compiledSources: ReadonlyMap<string, string> }): string | null {
  const { file } = required;
  if (file === "settings.json") return null; // Init regenerates host config and fresh identity.
  if (file.startsWith("uploads/")) return file;
  const theme = THEME_ID.exec(file)?.[1];
  const live = theme !== undefined && required.liveThemes.has(theme) && !isCompiledSource({ file, theme, compiledSources: required.compiledSources });
  return live ? file : ".import-quarantine/" + file;
}

/** Private roots plus exclusive files prevent extraction through pre-existing links or aliases.
 * @param optional.validatePath the share path policy; injectable only so the containment guard
 *   behind it can be proven on its own.
 */
export function writeExclusive(required: { root: string; relative: string; bytes: Buffer }, optional: { validatePath?: (required: { path: string }) => void } = {}): void {
  (optional.validatePath ?? validateSharePath)({ path: required.relative });
  const target = path.resolve(required.root, required.relative);
  if (!target.startsWith(path.resolve(required.root) + path.sep)) throw new Error("Import path escaped staging");
  fs.mkdirSync(path.dirname(target), { recursive: true, mode: 0o700 });
  fs.writeFileSync(target, required.bytes, { flag: "wx", mode: 0o600 });
}

import { createHash } from "node:crypto";
import type { AgentPluginArchiveEntry, AgentPluginArchiveReaderPort } from "@jini-ai/agent-plugins/lifecycle";
import { checkShareLimits, SHARE_LIMITS, SiteShareRefusal } from "./share-policy.js";
import { validateSharePath, excludedSharePath, requireShareSecretFree, claimSharePath, sharePathAlias, type PackageFileInventory } from "./share-file-policy.js";
import { ARCHIVE_MANIFEST_PATH as SITE_BACKUP_MANIFEST_PATH, ARCHIVE_DATABASE_PATH as SITE_BACKUP_DATABASE_PATH, parseArchiveManifest, requireArchiveFileRecord, type ArchiveManifest } from "./archive-manifest.js";
import { archiveCodeUnit, archiveSecretScanPath } from "./archive-paths.js";

/**
 * @file The archive half of `verifySiteImport`: the metadata-only first pass, the manifest contract,
 * the manifest inventory, and the bounded, hash-checked second pass. Every refusal here is
 * `INVALID_ARCHIVE` unless a shared share policy (path, limits, secrets) refuses first.
 */

type FileEntry = Extract<AgentPluginArchiveEntry, { kind: "file" }>;

/** One manifest file record after validation: the exact bytes and hash the archive must match. */
export interface InventoryRecord { readonly path: string; readonly bytes: number; readonly sha256: string }

/** A manifest that passed the share identity contract; only the fields later steps read are typed. */
export type SupportedShareManifest = ArchiveManifest;

/** What the metadata pass learned, before any listed content is read. */
export interface ArchiveScan {
  readonly manifestBytes: Buffer;
  readonly wrapper: string;
  /** Case/Unicode alias of every file entry, the manifest included. */
  readonly fileAliases: Set<string>;
  readonly directories: Set<string>;
}

/** The per-archive claim sets the first pass fills in place. */
interface EntryClaims {
  readonly aliases: Map<string, string>;
  readonly fileAliases: Set<string>;
  readonly directories: Set<string>;
  readonly sizes: { path: string; bytes: number }[];
}

const SHARE_INVENTORY_ROOTS = /^(?:media|themes|plugins|agent-plugins|skills)\/.+/;
const SHARE_SETTINGS_FILES = ["settings.json"];

export function refuseArchive(message: string): never { throw new SiteShareRefusal({ code: "INVALID_ARCHIVE", message }); }

/** Hex SHA-256 of a whole buffer. O(bytes). */
export function sha256Hex(bytes: Buffer): string { return createHash("sha256").update(bytes).digest("hex"); }

/**
 * First pass, metadata only: refuses links/special entries and enforces the entry cap, reads only
 * the one manifest (bounded), then claims every entry path, refusing collisions, invalid declared
 * sizes and the declared-size caps. ZIP ordering is never trusted; the manifest may appear anywhere.
 * @throws SiteShareRefusal (INVALID_ARCHIVE, UNSAFE_PATH, LIMIT_EXCEEDED) or the signal's reason.
 * @complexity O(entries × path depth + manifest bytes), at most 2,000 entries.
 */
export async function scanArchiveMetadata(required: { archive: Buffer; reader: AgentPluginArchiveReaderPort }, optional: { signal?: AbortSignal } = {}): Promise<ArchiveScan> {
  const claims: EntryClaims = { aliases: new Map(), fileAliases: new Set(), directories: new Set(), sizes: [] };
  const entries: AgentPluginArchiveEntry[] = [];
  let count = 0;
  for await (const entry of required.reader.entries({ archive: required.archive })) {
    optional.signal?.throwIfAborted();
    if (++count > SHARE_LIMITS.maxFiles) refuseArchive("Import exceeds the 2,000-entry cap.");
    const name = entry.entryPath.replace(/\/$/, "");
    validateRawEntry({ entry, name });
    if (!ignoredArchivePath({ path: name })) entries.push(entry);
  }
  const wrapper = sharedWrapperFolder({ entries });
  const manifestBytes = await readManifest({ ...required, path: wrapper + SITE_BACKUP_MANIFEST_PATH }, optional);
  claimNormalizedEntries({ entries, claims, wrapper });
  return { manifestBytes, wrapper, fileAliases: claims.fileAliases, directories: claims.directories };
}

/**
 * The Finder wrapper is the one top-level folder that holds every entry; any root file (the root
 * manifest included) or a second top-level folder means there is no wrapper. Deciding it from the
 * whole tree, never from where a `manifest.json` sits, keeps a media file named `manifest.json`
 * from passing for a wrapped manifest. O(entries).
 */
function sharedWrapperFolder(required: { entries: readonly AgentPluginArchiveEntry[] }): string {
  const tops = new Set(required.entries.map(entry => {
    const parts = entry.entryPath.replace(/\/$/, "").split("/");
    return parts.length > 1 || entry.kind === "directory" ? parts[0]! : "";
  }));
  const [top] = tops;
  return tops.size === 1 && top ? top + "/" : "";
}

/** A separate pass for the manifest alone: the reader closes the ZIP when an iteration ends, so
 * the bounded read happens inside it. */
async function readManifest(required: { archive: Buffer; reader: AgentPluginArchiveReaderPort; path: string }, optional: { signal?: AbortSignal }): Promise<Buffer> {
  for await (const entry of required.reader.entries({ archive: required.archive })) {
    optional.signal?.throwIfAborted();
    if (entry.kind === "file" && entry.entryPath === required.path) return readBounded({ entry, maxBytes: SHARE_LIMITS.maxManifestBytes, signal: optional.signal });
  }
  return refuseArchive("A v2 manifest.json at root, or inside one wrapper folder with nothing outside it, is required.");
}

/** Finder metadata is discarded identically in both passes, without decompressing it. */
export function ignoredArchivePath(required: { path: string }, _optional = {}): boolean {
  return required.path.split("/").some(part => part === "__MACOSX" || part === ".DS_Store");
}
function stripArchiveWrapper(required: { path: string; wrapper: string }): string {
  if (!required.path.startsWith(required.wrapper)) refuseArchive("Files outside the single wrapper folder are forbidden.");
  const path = required.path.slice(required.wrapper.length);
  validateSharePath({ path: path.replace(/\/$/, "") });
  return path;
}

/** Claims one entry; returns it when it is a file, `undefined` for a directory. */
function claimEntry(required: { claims: EntryClaims; entry: AgentPluginArchiveEntry }): FileEntry | undefined {
  const { claims, entry } = required;
  if (entry.kind !== "file" && entry.kind !== "directory") refuseArchive("ZIP links and special entries are forbidden.");
  if (entry.kind === "directory") {
    claimDirectory({ claims, name: entry.entryPath.replace(/\/$/, "") });
    return undefined;
  }
  claimFile({ claims, entry });
  return entry;
}

function claimDirectory(required: { claims: EntryClaims; name: string }): void {
  const { claims, name } = required;
  claimSharePath({ path: name, directory: true, aliases: claims.aliases, files: claims.fileAliases });
  if (claims.directories.has(name) || claims.fileAliases.has(sharePathAlias({ path: name }))) refuseArchive("Duplicate directory or file/directory collision.");
  claims.directories.add(name);
}

function claimFile(required: { claims: EntryClaims; entry: FileEntry }): void {
  const { claims, entry } = required;
  const name = entry.entryPath;
  claimSharePath({ path: name, directory: false, aliases: claims.aliases, files: claims.fileAliases });
  if (claims.directories.has(name)) refuseArchive("ZIP file/directory collision.");
  const size = entry.declaredSize;
  if (!Number.isSafeInteger(size) || size! < 0) refuseArchive("ZIP has an invalid declared size.");
  claims.sizes.push({ path: name, bytes: size! });
  checkShareLimits({ files: claims.sizes });
}

/**
 * Parses the manifest and refuses anything but this build's exact share identity.
 * @throws SiteShareRefusal INVALID_ARCHIVE for invalid JSON or an unsupported identity.
 * @complexity O(manifest bytes).
 */
export function parseShareManifest(required: { manifestBytes: Buffer; schema: { index: number; tag: string } }): SupportedShareManifest {
  return parseArchiveManifest({ bytes: required.manifestBytes, schema: required.schema });
}

/**
 * Validates every manifest record and keys it by exact path. Only the projected database and the
 * recognised portable roots/settings files may be listed; known private paths refuse.
 * @throws SiteShareRefusal (INVALID_ARCHIVE, UNSAFE_PATH, UNSAFE_FILE).
 * @complexity O(records × path length).
 */
export function buildManifestInventory(required: { files: readonly unknown[] }): Map<string, InventoryRecord> {
  const inventory = new Map<string, InventoryRecord>();
  for (const record of required.files) {
    const file = requireArchiveFileRecord({ file: record });
    validateSharePath({ path: file.path });
    if (inventory.has(file.path) || file.path === SITE_BACKUP_MANIFEST_PATH) refuseArchive("Duplicate manifest file.");
    if (refusedInventoryPath(file.path)) refuseArchive("Unrecognized or private file in share inventory.");
    inventory.set(file.path, file);
  }
  return inventory;
}

function refusedInventoryPath(path: string): boolean {
  if (path === SITE_BACKUP_DATABASE_PATH) return false;
  return excludedSharePath({ path: archiveSecretScanPath({ path, plugins: [] }) }) || !SHARE_INVENTORY_ROOTS.test(path) && !SHARE_SETTINGS_FILES.includes(path);
}

/**
 * The archive holds exactly the manifest plus one file per record (counted by alias), the database
 * is listed, and every directory entry has a listed file below it.
 * @complexity O(directories × records).
 */
export function checkArchiveMatchesInventory(required: { inventory: ReadonlyMap<string, InventoryRecord>; fileAliases: ReadonlySet<string>; directories: ReadonlySet<string> }): void {
  const { inventory } = required;
  if (inventory.size + 1 !== required.fileAliases.size || !inventory.has(SITE_BACKUP_DATABASE_PATH)) refuseArchive("ZIP inventory differs from the manifest.");
  for (const dir of required.directories) if (![...inventory.keys()].some(file => file.startsWith(dir + "/"))) refuseArchive("Unlisted ZIP directory.");
}

/**
 * Second pass: reads every listed file under its manifest size and the remaining expanded budget,
 * checks its SHA-256, and secret-scans everything except the database (the sanitizer owns that).
 * @throws SiteShareRefusal (INVALID_ARCHIVE, SECRET_IN_CONTENT) or the signal's reason.
 * @complexity O(payload bytes), at most 300 MiB buffered.
 */
export async function readListedFiles(required: { archive: Buffer; reader: AgentPluginArchiveReaderPort; inventory: ReadonlyMap<string, InventoryRecord>; manifestBytes: Buffer; wrapper?: string; manifest?: ArchiveManifest; modified?: Set<string> }, optional: { signal?: AbortSignal; packageFiles?: PackageFileInventory } = {}): Promise<Map<string, Buffer>> {
  const files = new Map<string, Buffer>();
  let expanded = required.manifestBytes.length;
  for await (const entry of required.reader.entries({ archive: required.archive })) {
    if (entry.kind !== "file" || ignoredArchivePath({ path: entry.entryPath })) continue;
    const entryPath = stripArchiveWrapper({ path: entry.entryPath, wrapper: required.wrapper ?? "" });
    if (entryPath === SITE_BACKUP_MANIFEST_PATH) continue;
    const content = await readListedFile({ entry: { ...entry, entryPath }, inventory: required.inventory, remainingBytes: SHARE_LIMITS.maxExpandedBytes - expanded, manifest: required.manifest, modified: required.modified }, optional);
    expanded += content.length;
    files.set(entryPath, content);
  }
  return files;
}

async function readListedFile(required: { entry: FileEntry; inventory: ReadonlyMap<string, InventoryRecord>; remainingBytes: number; manifest?: ArchiveManifest | undefined; modified?: Set<string> | undefined }, optional: { signal?: AbortSignal | undefined; packageFiles?: PackageFileInventory | undefined }): Promise<Buffer> {
  const { entry } = required;
  const expected = required.inventory.get(entry.entryPath);
  if (!expected) refuseArchive("Unlisted ZIP file.");
  const unit = archiveCodeUnit({ path: entry.entryPath });
  if (!unit && expected.bytes !== entry.declaredSize) refuseArchive("ZIP size mismatch.");
  const content = await readBounded({ entry, maxBytes: Math.min(entry.declaredSize!, required.remainingBytes), signal: optional.signal });
  verifyListedIntegrity({ content, expected, unit, modified: required.modified });
  if (entry.entryPath !== SITE_BACKUP_DATABASE_PATH) requireShareSecretFree({ path: archiveSecretScanPath({ path: entry.entryPath, plugins: required.manifest?.plugins ?? [] }), bytes: content }, { packageFiles: optional.packageFiles, shownPath: entry.entryPath });
  return content;
}

/** Count decompressed bytes before retaining each chunk; metadata is never a memory budget. */
async function readBounded(required: { entry: FileEntry; maxBytes: number; signal?: AbortSignal | undefined }): Promise<Buffer> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of required.entry.openReadStream({})) {
    required.signal?.throwIfAborted();
    size += chunk.length;
    if (size > required.maxBytes) refuseArchive("Expanded ZIP bytes exceed the manifest or archive cap (possible ZIP bomb).");
    chunks.push(Buffer.from(chunk));
  }
  if (size !== required.entry.declaredSize) refuseArchive("ZIP declared and actual size differ.");
  return Buffer.concat(chunks, size);
}

function validateRawEntry(required: { entry: AgentPluginArchiveEntry; name: string }): void {
  // Validate traversal/aliases even on ignored metadata. Its known OS name and the database
  // extension are placeholders only during the pre-strip path check, never extraction paths.
  validateSharePath({ path: required.name.split("/").map(part => part === ".DS_Store" ? "finder-metadata" : part).join("/").replace(/(^|\/)content\.db$/, "$1content-database") });
  if (required.entry.kind !== "file" && required.entry.kind !== "directory") refuseArchive("ZIP links and special entries are forbidden.");
}

function claimNormalizedEntries(required: { entries: readonly AgentPluginArchiveEntry[]; claims: EntryClaims; wrapper: string }): void {
  const { entries, claims, wrapper } = required;
  for (const entry of entries) {
    if (entry.kind === "directory" && entry.entryPath.replace(/\/$/, "") === wrapper.slice(0, -1)) continue;
    const entryPath = stripArchiveWrapper({ path: entry.entryPath, wrapper });
    claimEntry({ claims, entry: { ...entry, entryPath } });
  }
}

/** Editable code changes disable their entire unit; data integrity failures always refuse. */
function verifyListedIntegrity(required: { content: Buffer; expected: InventoryRecord; unit: string | undefined; modified: Set<string> | undefined }): void {
  if (required.content.length === required.expected.bytes && sha256Hex(required.content) === required.expected.sha256) return;
  if (!required.unit || !required.modified) refuseArchive("ZIP size or SHA-256 mismatch.");
  required.modified.add(required.unit);
}

import { createHash } from "node:crypto";

import type { BackupTreeEntry, CredentialedRepositoryTarget, ProviderCallFailure, SourceControlProvider } from "../source-control/provider-module.js";
import type { SiteBackupPlan } from "./plan-store.js";
import { buildSiteBackupManifest, readPlannedFile, SITE_BACKUP_DATABASE_PATH, SITE_BACKUP_MANIFEST_PATH } from "./sources.js";

/**
 * @file Uploads a planned backup's content for `site_backup_push`: the in-memory database snapshot,
 * each disk file re-read and refused if it changed since the plan, then the manifest built from what
 * was uploaded. The result is the folder's tree entries, in plan order, for ONE commit.
 *
 * Built for large sites (a 212 MiB, 1510-file backup failed live on 2026-10-06):
 * - {@link SITE_BACKUP_UPLOAD_CONCURRENCY} files at a time, each read from disk only when a worker
 *   takes it, so at most that many files are in memory, never the whole site;
 * - a small UTF-8 file goes inline in the host's tree request when the provider accepts that
 *   (`backupInlineTextMaxBytes`), which saves one write request per file against the host's rate
 *   limits;
 * - identical content is uploaded once;
 * - a failure stops every worker from taking another file and names the file that failed. Transient
 *   host errors are retried inside the provider, so a failure that reaches here is final.
 */

/** Files uploaded at a time: a few overlapping requests hide per-request latency, and stay far
 *  below a host's concurrent-request limit (GitHub: 100). */
export const SITE_BACKUP_UPLOAD_CONCURRENCY = 4;

/** Inline text is held until the commit, so it is bounded; past this, files go up as blobs. */
const INLINE_TEXT_BUDGET_BYTES = 64 * 1024 * 1024;

export interface PushFailure {
  readonly ok: false;
  readonly code: string;
  readonly message: string;
}

/** How far a push has got, updated in place as files go up. The manifest is not counted. */
export interface SiteBackupPushProgress {
  filesDone: number;
  readonly filesTotal: number;
  bytesDone: number;
  readonly bytesTotal: number;
}

export interface UploadPlannedContentInput {
  readonly provider: SourceControlProvider;
  readonly target: CredentialedRepositoryTarget;
  readonly plan: SiteBackupPlan;
  /** Aborted: no worker takes another file, and the upload reports `CANCELLED`. */
  readonly signal: AbortSignal;
  readonly progress: SiteBackupPushProgress;
  /** Maps a provider failure to the tool's code, logging its server-only detail. */
  readonly toRefusal: (failure: ProviderCallFailure) => PushFailure;
  readonly concurrency?: number;
}

export const CANCELLED: PushFailure = { ok: false, code: "CANCELLED", message: "the push was stopped before anything was committed" };

/** The progress a plan starts from. @complexity O(1). */
export function initialPushProgress(plan: SiteBackupPlan): SiteBackupPushProgress {
  return { filesDone: 0, filesTotal: plan.files.length + (plan.database ? 1 : 0), bytesDone: 0, bytesTotal: plan.totalBytes };
}

/** One file to upload: its path and how to get its bytes when a worker takes it. */
interface PendingFile {
  readonly path: string;
  load(): Promise<{ ok: true; bytes: Uint8Array } | PushFailure>;
}

/** The bytes, as text, when they are valid UTF-8 without a NUL — else `null`. The BOM is kept. */
function asUtf8Text(content: Uint8Array): string | null {
  if (content.includes(0)) return null;
  try {
    return new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(content);
  } catch {
    return null;
  }
}

/** Turns file content into tree entries: inline text when the provider takes it, else an uploaded
 *  blob — once per distinct content, even when two workers meet the same bytes at once. */
class EntryBuilder {
  private readonly uploads = new Map<string, Promise<{ ok: true; blobSha: string } | PushFailure>>();
  private inlineBytes = 0;
  private readonly input: UploadPlannedContentInput;
  constructor(input: UploadPlannedContentInput) {
    this.input = input;
  }

  /** @complexity O(bytes) to hash and decode; at most one upload per distinct content. */
  async entryFor(path: string, content: Uint8Array): Promise<BackupTreeEntry | PushFailure> {
    const sha256 = createHash("sha256").update(content).digest("hex");
    const text = this.inlineText(content);
    if (text !== null) return { path, text, bytes: content.byteLength, sha256 };
    let pending = this.uploads.get(sha256);
    if (pending === undefined) {
      pending = this.upload(path, content);
      this.uploads.set(sha256, pending);
    }
    const uploaded = await pending;
    if (!uploaded.ok) return { ok: false, code: uploaded.code, message: `uploading '${path}' failed: ${uploaded.message}` };
    return { path, blobSha: uploaded.blobSha, bytes: content.byteLength, sha256 };
  }

  private inlineText(content: Uint8Array): string | null {
    const max = this.input.provider.backupInlineTextMaxBytes;
    if (max === undefined || content.byteLength > max || this.inlineBytes + content.byteLength > INLINE_TEXT_BUDGET_BYTES) return null;
    const text = asUtf8Text(content);
    if (text !== null) this.inlineBytes += content.byteLength;
    return text;
  }

  private async upload(path: string, content: Uint8Array): Promise<{ ok: true; blobSha: string } | PushFailure> {
    const uploaded = await this.input.provider.uploadBackupBlob(this.input.target, { path, content });
    return uploaded.ok ? { ok: true, blobSha: uploaded.blob.blobSha } : this.input.toRefusal(uploaded);
  }
}

/** The plan's files in order: the database snapshot first, then each disk file, re-read at upload. */
function pendingFiles(plan: SiteBackupPlan): PendingFile[] {
  const database = plan.database;
  const fromDisk = plan.files.map((file): PendingFile => ({
    path: file.path,
    load: async () => {
      const read = await readPlannedFile(file);
      return read.ok ? { ok: true, bytes: read.bytes } : { ok: false, code: "PLAN_STALE", message: read.message };
    },
  }));
  if (!database) return fromDisk;
  return [{ path: SITE_BACKUP_DATABASE_PATH, load: async () => ({ ok: true, bytes: database.bytes }) }, ...fromDisk];
}

/**
 * Runs `work` over `count` indexes with at most `concurrency` in flight; the first failure (or an
 * abort) stops every worker from taking another index.
 *
 * @complexity O(count) calls of `work`.
 */
async function runBounded(count: number, concurrency: number, signal: AbortSignal, work: (index: number) => Promise<PushFailure | null>): Promise<PushFailure | null> {
  let next = 0;
  let failure: PushFailure | null = null;
  const worker = async (): Promise<void> => {
    while (failure === null && !signal.aborted && next < count) {
      const outcome = await work(next++);
      if (outcome !== null && failure === null) failure = outcome;
    }
  };
  await Promise.all(Array.from({ length: Math.max(1, Math.min(concurrency, count)) }, worker));
  return failure ?? (signal.aborted ? CANCELLED : null);
}

/**
 * Uploads the plan's content and returns the folder's entries, the manifest last.
 *
 * @complexity O(total bytes); one upload per distinct non-inline content.
 */
export async function uploadPlannedContent(input: UploadPlannedContentInput): Promise<{ ok: true; entries: BackupTreeEntry[] } | PushFailure> {
  const { plan, progress } = input;
  const builder = new EntryBuilder(input);
  const files = pendingFiles(plan);
  const entries: BackupTreeEntry[] = new Array(files.length);
  const failure = await runBounded(files.length, input.concurrency ?? SITE_BACKUP_UPLOAD_CONCURRENCY, input.signal, async (index) => {
    const file = files[index]!;
    const loaded = await file.load();
    if (!loaded.ok) return loaded;
    const entry = await builder.entryFor(file.path, loaded.bytes);
    if ("ok" in entry) return entry;
    entries[index] = entry;
    progress.filesDone += 1;
    progress.bytesDone += entry.bytes;
    return null;
  });
  if (failure !== null) return failure;

  const manifest = buildSiteBackupManifest({
    createdAt: plan.createdAt,
    tovuVersion: plan.tovuVersion,
    schema: plan.schema,
    site: plan.site,
    database: plan.database ? { watermarkAtCapture: plan.database.watermarkAtCapture } : null,
    include: plan.include,
    scopeNotes: plan.scopeNotes,
    files: entries,
  });
  const manifestEntry = await builder.entryFor(SITE_BACKUP_MANIFEST_PATH, Buffer.from(manifest, "utf8"));
  if ("ok" in manifestEntry) return manifestEntry;
  return { ok: true, entries: [...entries, manifestEntry] };
}

import { createHash } from "node:crypto";
import { checkTreePath } from "../publish-content/file-tree-policy.js";
import { SiteShareRefusal, SHARE_LIMITS } from "./share-policy.js";
import { redactSecretShapes } from "#src/contracts/core/secret-redaction";

/** The seven-segment root of an installed plugin package payload (matched against the lowercased path). */
const PACKAGE_CONTENT_ROOT = /^agent-plugins\/ws\/[^/]+\/[^/]+\/package\/sha256\/[a-f0-9]{64}\//;
/** The same root, capturing its archive digest and the package-relative path below it. */
const PACKAGE_FILE = /^agent-plugins\/ws\/[^/]+\/[^/]+\/package\/sha256\/([a-f0-9]{64})\/(.+)$/i;
/** Names an installed package ships as content (MCP declarations, credential schemes), never runtime secrets. */
const PACKAGE_MANIFEST_NAMES = ["mcp.json", "tovu-credential-schemes.json"];

/** Archive digest -> (package-relative path -> SHA-256 of the bytes) for every package THIS build
 *  ships (`package-file-inventory.ts`). The only proof a package-shaped path is the installer's. */
export type PackageFileInventory = ReadonlyMap<string, ReadonlyMap<string, string>>;

/** The plugin memory a share carries. Every other folder under a plugin's `memory/` is private runtime
 *  state: export excludes it ({@link excludedSharePath}) and import refuses it (`archive-manifest.ts`). */
export const SHARED_PLUGIN_MEMORY = String.raw`memory\/(?:notes|learned)`;
const PRIVATE_PLUGIN_MEMORY = String.raw`memory\/(?!(?:notes|learned)(?:\/|$))`;
const AGENT_PLUGIN_RUNTIME = new RegExp(String.raw`^agent-plugins\/ws\/[^/]+\/[^/]+\/(?:data(?:\/|$)|${PRIVATE_PLUGIN_MEMORY})`);

function excludedRuntimeSharePath({ path, parts }: { path: string; parts: string[] }, _options = {}): boolean {
  // Plugin runtime data/memory have fixed roots. A package's src/data or docs/notes is content.
  // A site plugin needs no rule here: the share walks only the files Jini lists as its package
  // (`sources.ts` walkSitePlugins), so its data/ and private memory are never reached.
  const roots = [
    /^agent-plugins\/ws\/[^/]+\/(?:data|staging)(?:\/|$)/,
    AGENT_PLUGIN_RUNTIME,
    /^uploads\/chat-attachments(?:\/|$)/,
  ];
  return roots.some(root => root.test(path)) ||
    parts.some(part => part.startsWith(".env") || /^chat\.db(?:$|[.-])/.test(part));
}

/** A name that only hints at a secret; below a package root the file's bytes decide (see requireShareSecretFree). */
const CREDENTIAL_NAME = /(?:credential|vault|keyring|site-key|private[-_]?key)/;

function suspiciousSharePart({ part }: { part: string }, { packageContent = false } = {}): boolean {
  const names = [".git", "node_modules", ".publish-staging", ".publish-previous", ".storage-secret.json", ".ds_store", "_share", "mcp.json", ".npmrc", ".netrc", ".fs-custom-root.json"];
  const prefixes = [".share-", "restore-point-", "superseded-"];
  const patterns = [
    /^id_(?:rsa|dsa|ecdsa|ed25519)(?:\.|$)/,
    /\.(?:pem|key|p12|pfx)(?:[.-]|$)/,
    /\.(?:db|sqlite|sqlite3)(?:$|[.-])/,
    /^\.mcp(?:\..*)?\.json$/,
  ];
  return names.includes(part) || prefixes.some(prefix => part.startsWith(prefix)) || patterns.some(pattern => pattern.test(part)) ||
    (!packageContent && CREDENTIAL_NAME.test(part));
}

/** Exclude known private locations only; suspicious required content must refuse, not disappear. O(depth).
 * Names only: below a package root a credential-like name is provisional, and
 * {@link requireShareSecretFree}, which has the bytes, keeps it only for a verified package file. */
export function excludedSharePath(required: { path: string }, _optional: Record<string, never> = {}): boolean {
  const p = required.path.toLowerCase();
  if (excludedRuntimeSharePath({ path: p, parts: p.split("/") })) return true;
  refuseSuspiciousSharePath(required, { credentialNameAllowed: true });
  return false;
}

/** Refuses a suspicious segment. {@link PACKAGE_MANIFEST_NAMES} pass below the seven-segment package
 *  root, their bytes still scanned; a credential-like name passes there only when `credentialNameAllowed`.
 *  Every other name rule (.git, node_modules, .pem/.key, .db, id_rsa, .mcp*.json, .npmrc) always applies. */
function refuseSuspiciousSharePath(required: { path: string }, { credentialNameAllowed, shownPath = required.path }: { credentialNameAllowed: boolean; shownPath?: string }): void {
  const p = required.path.toLowerCase();
  const packageContent = PACKAGE_CONTENT_ROOT.test(p);
  const suspicious = (part: string, index: number): boolean => {
    const inPackage = packageContent && index >= 7;
    return !(inPackage && PACKAGE_MANIFEST_NAMES.includes(part)) && suspiciousSharePart({ part }, { packageContent: inPackage && credentialNameAllowed });
  };
  if (p.split("/").some(suspicious)) {
    throw new SiteShareRefusal({ code: "UNSAFE_FILE", message: `Share refuses suspicious required path '${shownPath}'. Remove it before sharing.` });
  }
}

/**
 * True only when this build ships these exact bytes at this package-relative path under this digest.
 * Anyone who can write into the site folder can create a package-SHAPED path, and install records
 * live in that same folder, so the shape, the folder name and the ledger prove nothing; the build's
 * own bundled sources do. An operator-installed package, a superseded digest, an unlisted file under a
 * verified root, or a tampered file all get the ordinary rules. O(bytes).
 */
function verifiedPackageFile(required: { path: string; bytes: Uint8Array }, optional: { packageFiles?: PackageFileInventory | undefined }): boolean {
  const match = PACKAGE_FILE.exec(required.path);
  if (!match) return false;
  // The root: a digest this build ships. The file: listed below that root, with the same bytes.
  const shipped = optional.packageFiles?.get(match[1]!.toLowerCase());
  const expected = shipped?.get(match[2]!);
  return expected !== undefined && createHash("sha256").update(required.bytes).digest("hex") === expected;
}

/** True for a spelling some supported recipient filesystem rejects, rewrites or aliases. O(path). */
function hasUnportableSpelling(required: { path: string }): boolean {
  const p = required.path;
  const parts = p.split("/");
  return /[:%\x00-\x1f\x7f\\]/.test(p) || p.normalize("NFC") !== p || p.normalize("NFKC") !== p || /[<>"|?*]/.test(p) ||
    parts.some(part => /^(?:con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\.|$)/i.test(part)) || parts.length > SHARE_LIMITS.maxPathSegments ||
    parts.some(part => /[. ]$/.test(part));
}

/** A ZIP path has one canonical spelling on every supported recipient filesystem. O(path). */
export function validateSharePath(required: { path: string }, _optional: Record<string, never> = {}): void {
  const p = required.path;
  // This one exact path is produced by trusted projection, never by a filesystem walk.
  const reason = ["database/content.db", "content.db"].includes(p) ? null : checkTreePath(p);
  if (reason || hasUnportableSpelling({ path: p })) {
    const suffix = reason ? `: ${reason}` : ".";
    throw new SiteShareRefusal({ code: "UNSAFE_PATH", message: `Share path '${p}' is unsafe${suffix}` });
  }
}

/** Scan the complete bytes, including binary content; a required file is refused, never damaged. O(bytes).
 * `path` picks the rules; a refusal names `shownPath` when given (the archive path the owner can find,
 * not the synthetic scan path `archiveSecretScanPath` builds). */
export function requireShareSecretFree(required: { path: string; bytes: Uint8Array }, optional: { packageFiles?: PackageFileInventory | undefined; shownPath?: string } = {}): void {
  const shownPath = optional.shownPath ?? required.path;
  const text = Buffer.from(required.bytes).toString("latin1");
  // Only code can contain credential references; content/settings retain strict secret detection.
  const codeAware = /\.(?:js|mjs|cjs|ts|tsx|jsx)$/i.test(required.path);
  // A verified package file is public plugin code, docs and manifests this build ships: its translated
  // labels ("API token": "Token de API"), doc placeholders (`Authorization: Bearer <API_KEY>`) and test
  // names (__tests__/credential-card.test.mjs) are not owner secrets, so only provider key formats, PEM
  // and JWT shapes refuse it. Any other package-shaped file gets every name rule and the full scan. The
  // scanner does not decode compressed or encoded bytes (credentials.gz), so for those the name refusal
  // is the guard; a verified one is the build's own bytes, so nothing is hidden in it.
  const vendorOnly = verifiedPackageFile(required, optional);
  if (!vendorOnly && PACKAGE_CONTENT_ROOT.test(required.path.toLowerCase())) refuseSuspiciousSharePath(required, { credentialNameAllowed: false, shownPath });
  if (redactSecretShapes({ text }, { codeAware, vendorOnly }).redactions > 0) throw new SiteShareRefusal({ code: "SECRET_IN_CONTENT", message: `Share refused: '${shownPath}' contains credential-shaped content. Remove the secret before sharing.` });
}

function unsafeSharePath(message: string): never { throw new SiteShareRefusal({ code: "UNSAFE_PATH", message }); }

/** Upper/lower expansion also catches sharp-s/SS and final-sigma aliases, including ancestors. */
export function sharePathAlias(required: { path: string }, _options: Record<string, never> = {}): string { return required.path.normalize("NFKC").toUpperCase().toLowerCase().normalize("NFC"); }

/** Reject aliases, including aliases in directory ancestors, before any content is read.
 * Mutates only the caller's per-archive claim sets; throws UNSAFE_PATH on conflicts.
 * @complexity O(path depth² + prior claims), bounded by 32 segments and 2,000 ZIP entries.
 */
export function claimSharePath(required: { path: string; directory: boolean; aliases: Map<string, string>; files: Set<string> }, _options: Record<string, never> = {}): void {
  validateSharePath({ path: required.path });
  const parts = required.path.split("/");
  for (let index = 1; index <= parts.length; index++) {
    const spelling = parts.slice(0, index).join("/");
    const alias = sharePathAlias({ path: spelling });
    const prior = required.aliases.get(alias);
    if (prior !== undefined && prior !== spelling) unsafeSharePath("ZIP contains unsafe case or Unicode aliases.");
    required.aliases.set(alias, spelling);
    if (index < parts.length && required.files.has(alias)) unsafeSharePath("ZIP file/directory collision.");
  }
  const key = sharePathAlias(required);
  if (!required.directory) {
    if (required.files.has(key) || [...required.aliases.keys()].some(alias => alias.startsWith(key + "/"))) unsafeSharePath("Duplicate file or file/directory collision.");
    required.files.add(key);
  }
}

import type { ArtifactStorePort } from "@jini-ai/devops/deploy";
import { createHash } from "node:crypto";
import { createConsoleLogger, type HttpClientPort, type HttpResponse, type Logger } from "@jini-ai/core/primitives";
import { callPeer, type PeerCallDeps } from "../publish-content/peer-transport.js";
import { peerUrl } from "../publish-content/peer-url.js";
import { SiteShareRefusal } from "./share-policy.js";
import { SHARE_TOKEN_PATTERN, type SiteShareRegistry } from "./share-registry.js";
import { receiveSiteShareArtifact, type ShareDelivery } from "./share-service.js";

const ARTIFACT_KEY = new RegExp(`^_share/(${SHARE_TOKEN_PATTERN})/([a-z0-9][a-z0-9-]{0,79}\\.tovu\\.zip)$`);

/** Validates a share artifact key and returns its token and file; refuses INVALID_INPUT otherwise. O(key). */
function parseArtifactKey(key: string): { token: string; file: string } {
  const match = ARTIFACT_KEY.exec(key);
  if (!match) throw new SiteShareRefusal({ code: "INVALID_INPUT", message: "Invalid share artifact key." });
  return { token: match[1]!, file: match[2]! };
}

/** A 200 anonymous attachment of exactly `bytes`, served uncached, unsniffed and unindexed. */
function isPublicAttachment(required: { response: HttpResponse; bytes?: number }): boolean {
  const headers = new Headers(required.response.headers);
  return required.response.status === 200 && Number(headers.get("content-length")) === required.bytes && headers.get("cache-control") === "no-store" && headers.get("x-content-type-options") === "nosniff" && headers.get("x-robots-tag") === "noindex, nofollow" && /^attachment(?:;|$)/i.test(headers.get("content-disposition") ?? "");
}

/** Both Tovu delivery variants verify through the same anonymous attachment contract. */
async function verifyServerShare(required: { http: HttpClientPort; key: string; url: string; expectedUrl: string; present: boolean; bytes?: number }, optional: { signal?: AbortSignal } = {}): Promise<boolean> {
  parseArtifactKey(required.key);
  if (required.url !== required.expectedUrl) return false;
  // Never send a destination credential to the anonymous download endpoint.
  const response = await required.http.send({ request: { method: "HEAD", url: required.url, headers: {}, idleTimeoutMs: 15_000, totalDeadlineMs: 20_000, maxResponseBytes: 1024, signal: optional.signal } }, { redirect: "error" });
  if (!required.present) return response.status === 404 || response.status === 410;
  return isPublicAttachment({ response, bytes: required.bytes });
}

/** Public origin is an explicit operator capability, never inferred from a local request Host. */
export function createRuntimeShareDelivery(required: { registry: SiteShareRegistry; site: string; publicOrigin: string; http: HttpClientPort }, _optional: Record<string, never> = {}): ShareDelivery {
  const origin = URL.parse(required.publicOrigin);
  if (!origin || origin.protocol !== "https:" || origin.username || origin.password || origin.pathname !== "/" || origin.search || origin.hash) throw new SiteShareRefusal({ code: "STORAGE_SETUP", message: "TOVU_SHARE_PUBLIC_ORIGIN must be a public HTTPS origin without a path or credentials." });
  const store: ArtifactStorePort = {
    async upload({ key, bytes }, _optional = {}) {
      const { token, file } = parseArtifactKey(key);
      const existing = await required.registry.findToken({ token, file });
      if (existing && (existing.site !== required.site || existing.sha256 !== createHash("sha256").update(bytes).digest("hex"))) throw new SiteShareRefusal({ code: "ARTIFACT_CHANGED", message: "This token already names a different artifact." });
      if (!existing) await receiveSiteShareArtifact({ registry: required.registry, site: required.site, token, file, archive: Buffer.from(bytes) });
      return { url: `${origin.origin}/${key}` };
    },
    async delete({ key }, _optional = {}) {
      parseArtifactKey(key);
      const row = (await required.registry.list({ site: required.site })).find(row => key === `_share/${row.token}/${row.file}`);
      if (!row) return;
      await required.registry.disable({ shareId: row.shareId, site: row.site });
      await required.registry.deleteArtifact({ shareId: row.shareId });
    },
    verify: (input, options = {}) => verifyServerShare({ ...input, http: required.http, expectedUrl: `${origin.origin}/${input.key}` }, options),
  };
  return { provider: "tovu-server", binding: required.registry.directory, store };
}

/** Connected deployment artifact adapter. Reuses publishing credentials and guarded transport;
 * the deployed receiver needs no environment opt-in. The base URL pins revocation to that site. */
export function createPeerShareDelivery(required: { peer: PeerCallDeps; http: HttpClientPort }, _optional: Record<string, never> = {}): ShareDelivery {
  const baseUrl = required.peer.credential.baseUrl;
  const artifactPath = (key: string) => {
    const { token, file } = parseArtifactKey(key);
    return `/api/admin/v1/workspaces/${encodeURIComponent(required.peer.credential.remoteWorkspaceId)}/site-shares/artifacts/${token}/${file}`;
  };
  return { provider: "tovu-server", binding: baseUrl, store: {
    async upload({ key, bytes }, options = {}) {
      await callPeer(required.peer, { method: "PUT", path: artifactPath(key), archive: bytes, signal: options.signal });
      return { url: peerUrl(baseUrl, `/${key}`) };
    },
    async delete({ key }, options = {}) {
      // DELETE is idempotent, including after a previous successful remote cleanup.
      try { await callPeer(required.peer, { method: "DELETE", path: artifactPath(key), signal: options.signal }); }
      catch (error) { if ((error as { peerStatus?: number }).peerStatus !== 404) throw error; }
    },
    verify: (input, options = {}) => verifyServerShare({ ...input, http: required.http, expectedUrl: peerUrl(baseUrl, `/${input.key}`) }, options),
  } };
}

type ShareDeliverySources = {
  peer: () => Promise<PeerCallDeps | undefined>;
  http: HttpClientPort;
  objectStore: () => Promise<ShareDelivery | undefined>;
  runtime?: () => ShareDelivery;
  /** Where a skipped runtime delivery is reported; defaults to the console. */
  logger?: Pick<Logger, "warn">;
};
type SavedShareDelivery = { provider?: string; binding?: string };

/** No saved binding accepts any delivery; a saved one must name this delivery's own binding. */
function bindingMatches(required: { saved?: string; actual?: string }): boolean {
  return required.saved === undefined || required.saved === required.actual;
}

/** The connected deployed peer, else this server's runtime delivery, when its binding matches. */
async function resolveServerDelivery(required: ShareDeliverySources, optional: SavedShareDelivery = {}): Promise<ShareDelivery | undefined> {
  try {
    const peer = await required.peer();
    if (peer && bindingMatches({ saved: optional.binding, actual: peer.credential.baseUrl })) return createPeerShareDelivery({ peer, http: required.http });
  } catch { /* An unavailable connection still permits the configured object-store/ZIP fallback. */ }
  const runtime = runtimeDelivery(required);
  return runtime && bindingMatches({ saved: optional.binding, actual: runtime.binding }) ? runtime : undefined;
}

/** This server's runtime delivery; a misconfigured public origin leaves the object-store/ZIP fallback.
 * The warning carries the refusal code only: the configured origin may hold credentials. */
function runtimeDelivery(required: ShareDeliverySources): ShareDelivery | undefined {
  try { return required.runtime?.(); } catch (error) {
    const code = error instanceof SiteShareRefusal ? error.code : "UNEXPECTED";
    (required.logger ?? createConsoleLogger({ prefix: "" })).warn({ message: "[site-share] runtime share delivery is misconfigured; falling back to object storage or a private ZIP." }, { meta: { code } });
    return undefined;
  }
}

/** The configured object-store delivery when its provider and binding match the saved ones. */
async function resolveObjectStoreDelivery(required: ShareDeliverySources, optional: SavedShareDelivery = {}): Promise<ShareDelivery | undefined> {
  try {
    const objectStore = await required.objectStore();
    if (!objectStore || (optional.provider && optional.provider !== objectStore.provider)) return undefined;
    return bindingMatches({ saved: optional.binding, actual: objectStore.binding }) ? objectStore : undefined;
  } catch { return undefined; } // Failed credential resolution still leaves a private ZIP download.
}

/** Selection is shared by create and revoke: connected deployed peer, object store, then ZIP only.
 * A saved binding is mandatory on revoke; a changed default may never delete another site's ZIP. */
export async function resolveShareDelivery(required: ShareDeliverySources, optional: SavedShareDelivery = {}): Promise<ShareDelivery | undefined> {
  if (!optional.provider || optional.provider === "tovu-server") {
    const server = await resolveServerDelivery(required, optional);
    if (server || optional.provider) return server;
  }
  // Any object-store provider exposing an artifact store may deliver (not one hard-coded vendor);
  // a saved provider must be the one the site's object store resolves to now.
  return resolveObjectStoreDelivery(required, optional);
}

import { createHash } from "node:crypto";
import path from "node:path";
import { MAX_DOCUMENT_BYTES, type BlobStorePort } from "#src/features/media/index";
import type { DbOpsPort } from "#src/contracts/core/gated-mutations/ports";
import { captureDatabaseSnapshot, collectSiteBackupFiles, readPlannedFile, type CollectedSiteBackupFiles, type PlannedDiskFile, type SiteBackupInclude, type SiteBackupSources } from "./sources.js";
import { checkShareLimits, SHARE_LIMITS, SiteShareRefusal, type ShareDatabaseProjection, type ShareDatabaseSanitizer } from "./share-policy.js";

/**
 * @file The steps of `prepareShareContent`: the projected database, the collected site files, the
 * referenced media read through the blob store, and the regenerated portable settings.
 */

type ShareBlobStore = Pick<BlobStorePort, "get" | "sizeOf">;

/** Every byte the share will carry, checked against the archive caps on each addition. */
export interface ShareLedger {
  readonly sizes: { path: string; bytes: number }[];
  readonly buffered: { path: string; content: Buffer }[];
}

const PROVENANCE_KEYS = ["templateId", "templateVersion", "schemaVersion", "schemaTag"];
const PROVENANCE_TEXT = /^[a-z\d_.+-]{1,128}$/i;

/** Adds one buffered file after re-checking the caps with it counted. */
export function addBuffered(required: { ledger: ShareLedger; file: { path: string; content: Buffer } }): void {
  required.ledger.sizes.push({ path: required.file.path, bytes: required.file.content.length });
  checkShareLimits({ files: required.ledger.sizes });
  required.ledger.buffered.push(required.file);
}

/**
 * Snapshots the site database and returns only the sanitizer's fresh projection.
 * Release the private snapshot before buffering media and assembling the public ZIP: the snapshot
 * is scoped to this helper, so it is released before the caller does either.
 * `snapshotRoot` is a private folder outside the source site: Export never writes into site storage.
 * @throws SiteShareRefusal DATABASE_SNAPSHOT_FAILED with the snapshot's caller-safe message.
 */
export async function captureProjectedDatabase(required: { dbOps: DbOpsPort; sanitize: ShareDatabaseSanitizer; snapshotRoot: string }, optional: { signal?: AbortSignal } = {}): Promise<{ projected: ShareDatabaseProjection; watermarkAtCapture: number }> {
  const snapshot = await captureDatabaseSnapshot({ dbOps: required.dbOps, scopeId: "site-share" }, { maxBytes: SHARE_LIMITS.maxExpandedBytes, snapshotRoot: required.snapshotRoot });
  if (!snapshot.ok) throw new SiteShareRefusal({ code: "DATABASE_SNAPSHOT_FAILED", message: snapshot.message });
  const projected = await required.sanitize({ snapshot: snapshot.bytes }, { signal: optional.signal });
  return { projected, watermarkAtCapture: snapshot.watermarkAtCapture };
}

/** Collects the share profile's files (never the media folder); any skipped file refuses by name. */
export async function collectShareFiles(required: { sources: SiteBackupSources; include: SiteBackupInclude }): Promise<CollectedSiteBackupFiles> {
  const collected = await collectSiteBackupFiles({ sources: required.sources, include: { ...required.include, media: false } }, { profile: "share" });
  if (collected.skipped.length) throw new SiteShareRefusal({ code: "UNSAFE_FILE", message: `Cannot share '${collected.skipped[0]!.path}': ${collected.skipped[0]!.reason}. Remove it or replace it with a regular file.` });
  return collected;
}

export async function reportedBlobSize(required: { blobStore: ShareBlobStore; storageKey: string; document: boolean }): Promise<number> {
  if (!required.blobStore.sizeOf) throw new SiteShareRefusal({ code: "UNBOUNDED_MEDIA", message: "This media store cannot report blob sizes. Configure a size-aware blob store before sharing." });
  const size = await required.blobStore.sizeOf({ storageKey: required.storageKey });
  if (size === null) throw new SiteShareRefusal({ code: "MISSING_MEDIA", message: `Share media '${required.storageKey}' is missing from the blob store.` });
  if (!Number.isSafeInteger(size) || size < 0) throw new SiteShareRefusal({ code: "UNBOUNDED_MEDIA", message: "Media storage returned an invalid byte count; nothing was shared." });
  if (required.document && (size === 0 || size > MAX_DOCUMENT_BYTES)) throw new SiteShareRefusal({ code: "INVALID_DOCUMENT", message: "Library document blobs must be non-empty and at most 10 MiB; nothing was shared." });
  checkShareLimits({ files: [{ path: "media/blob", bytes: size }] });
  return size;
}

export async function fetchVerifiedBlob(required: { blobStore: ShareBlobStore; media: ShareDatabaseProjection["media"][number]; size: number }): Promise<Buffer> {
  const { media } = required;
  const content = Buffer.from(await required.blobStore.get({ storageKey: media.storageKey }));
  if (content.length !== required.size || (media.sha256 && createHash("sha256").update(content).digest("hex") !== media.sha256)) throw new SiteShareRefusal({ code: "MEDIA_CHANGED", message: `Share media '${media.storageKey}' changed or failed its checksum.` });
  return content;
}

/**
 * Regenerates root `settings.json` with name and named template provenance, never host configuration.
 * @returns the shared site name: the config's string `name`, else the site folder name.
 */
export async function addPortableSettings(required: { files: readonly PlannedDiskFile[]; siteDir: string; ledger: ShareLedger }): Promise<string> {
  const config = await readPortableJson({ file: required.files.find(file => file.path === "settings/config.json") });
  const name = typeof config.name === "string" ? config.name : path.basename(required.siteDir);
  const meta = await readPortableJson({ file: required.files.find(file => file.path === "settings/.site-meta.json") });
  addBuffered({ ledger: required.ledger, file: { path: "settings.json", content: Buffer.from(JSON.stringify({ name, template: pickProvenance({ meta }) })) } });
  return name;
}

function pickProvenance(required: { meta: Record<string, unknown> }): Record<string, unknown> {
  const provenance: Record<string, unknown> = {};
  // Pick named provenance fields; never spread site identity, paths, fingerprints or storage.
  for (const key of PROVENANCE_KEYS) {
    const value = required.meta[key];
    if (typeof value === "string" && PROVENANCE_TEXT.test(value) || typeof value === "number" && Number.isSafeInteger(value) && value >= 0) provenance[key] = value;
  }
  return provenance;
}

/** Read only the small, no-follow planned settings files; all other metadata is discarded. */
async function readPortableJson(required: { file?: PlannedDiskFile | undefined }): Promise<Record<string, unknown>> {
  if (!required.file) return {};
  if (required.file.bytes > SHARE_LIMITS.maxManifestBytes) throw new SiteShareRefusal({ code: "INVALID_SETTINGS", message: `Share settings '${required.file.path}' exceeds 2 MiB.` });
  const read = await readPlannedFile(required.file);
  if (!read.ok) throw new SiteShareRefusal({ code: "PLAN_STALE", message: read.message });
  try {
    const value: unknown = JSON.parse(read.bytes.toString("utf8"));
    if (value !== null && typeof value === "object" && !Array.isArray(value)) return value as Record<string, unknown>;
  } catch { /* A malformed portable setting must not produce a partial share. */ }
  throw new SiteShareRefusal({ code: "INVALID_SETTINGS", message: `Share settings '${required.file.path}' must contain a JSON object.` });
}

import { randomInt, randomUUID } from "node:crypto";
import { mkdir, readFile, readdir, rename, statfs, unlink, writeFile } from "node:fs/promises";
import path from "node:path";
import { SHARE_LIMITS, SiteShareRefusal } from "./share-policy.js";

export interface SiteShareRecord {
  readonly shareId: string;
  readonly token: string;
  readonly site: string;
  readonly file: string;
  readonly bytes: number;
  readonly sha256: string;
  readonly url: string | null;
  readonly status: "active" | "revoked" | "failed";
  readonly createdAt: string;
  readonly revokedAt: string | null;
  readonly storage?: { readonly provider: string; readonly key: string; readonly url?: string; readonly binding?: string };
}
const ID = /^[0-9a-f-]{36}$/;
/** Owner decision 2026-10-25: share tokens are 16 ASCII letters (~91 bits), short enough to read
 * aloud yet unguessable. No digits, and no other shape is accepted: old 64-hex links are dead.
 * The one source of the token shape; route and object-store key checks build on SHARE_TOKEN_PATTERN. */
export const SHARE_TOKEN_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
export const SHARE_TOKEN_LENGTH = 16;
export const SHARE_TOKEN_PATTERN = `[A-Za-z]{${SHARE_TOKEN_LENGTH}}`;
export const SHARE_TOKEN = new RegExp(`^${SHARE_TOKEN_PATTERN}$`);
export const SHARE_FILE = /^[a-z0-9][a-z0-9-]{0,79}\.tovu\.zip$/;

/**
 * Private per-site share catalog, outside every backup walk and public static root. One atomic
 * metadata file per export prevents unrelated concurrent creates from overwriting each other.
 * Revocation is a permanent create-only tombstone: a racing upload can never resurrect access.
 * @complexity O(exports) listing; O(1) token lookup/updates, plus artifact bytes on disk.
 */
export class SiteShareRegistry {
  readonly directory: string;
  constructor(required: { directory: string }, _optional: Record<string, never> = {}) { this.directory = required.directory; }
  private meta(id: string): string {
    if (!ID.test(id)) throw new SiteShareRefusal({ code: "INVALID_INPUT", message: "Invalid shareId." });
    return path.join(this.directory, `${id}.json`);
  }
  artifactPath(required: { shareId: string }, _optional: Record<string, never> = {}): string {
    this.meta(required.shareId);
    return path.join(this.directory, `${required.shareId}.tovu.zip`);
  }
  /** Immutable token-to-id claim gives O(1) public lookups and forbids replay after revocation. */
  async reserveToken(required: { token: string; shareId: string }, _optional: Record<string, never> = {}): Promise<void> {
    if (!SHARE_TOKEN.test(required.token)) throw new SiteShareRefusal({ code: "INVALID_INPUT", message: "Invalid share token." });
    this.meta(required.shareId);
    await mkdir(this.directory, { recursive: true, mode: 0o700 });
    const file = path.join(this.directory, `${required.token}.token`);
    try { await writeFile(file, required.shareId, { flag: "wx", mode: 0o600 }); }
    catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
      if (await readFile(file, "utf8") !== required.shareId) throw new SiteShareRefusal({ code: "TOKEN_EXISTS", message: "This share token has already been used. Create a new export." });
    }
  }
  async put(required: { record: SiteShareRecord }, _optional: Record<string, never> = {}): Promise<void> {
    await this.reserveToken(required.record);
    await this.writeRecord(required.record);
  }
  /** Atomic metadata write with no token-shape check, so `disable` can still tombstone a row minted
   * before the 16-letter switch (its token was reserved when it was created). */
  private async writeRecord(record: SiteShareRecord): Promise<void> {
    const temp = path.join(this.directory, `.${randomUUID()}.tmp`);
    try {
      await writeFile(temp, JSON.stringify(record), { flag: "wx", mode: 0o600 });
      await rename(temp, this.meta(record.shareId));
    } finally { await unlink(temp).catch(error => { if (error.code !== "ENOENT") throw error; }); }
  }
  async get(required: { shareId: string; site?: string }, _optional: Record<string, never> = {}): Promise<SiteShareRecord | null> {
    let row: SiteShareRecord;
    try { row = JSON.parse(await readFile(this.meta(required.shareId), "utf8")) as SiteShareRecord; }
    catch (error) { if ((error as NodeJS.ErrnoException).code === "ENOENT") return null; throw error; }
    if (required.site !== undefined && row.site !== required.site) return null;
    try {
      const revokedAt = await readFile(path.join(this.directory, `${row.shareId}.revoked`), "utf8");
      return { ...row, status: "revoked", revokedAt };
    } catch (error) { if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error; }
    return row;
  }
  async list(required: { site?: string }, _optional: Record<string, never> = {}): Promise<SiteShareRecord[]> {
    let names: string[];
    try { names = await readdir(this.directory); }
    catch (error) { if ((error as NodeJS.ErrnoException).code === "ENOENT") return []; throw error; }
    const rows: SiteShareRecord[] = [];
    for (const name of names) {
      if (!name.endsWith(".json") || !ID.test(name.slice(0, -5))) continue;
      const row = await this.get({ shareId: name.slice(0, -5), ...required });
      if (row) rows.push(row);
    }
    return rows.sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  }
  async findToken(required: { token: string; file: string }, _optional: Record<string, never> = {}): Promise<SiteShareRecord | null> {
    if (!SHARE_TOKEN.test(required.token) || !SHARE_FILE.test(required.file)) return null;
    let shareId: string;
    try { shareId = await readFile(path.join(this.directory, `${required.token}.token`), "utf8"); }
    catch (error) { if ((error as NodeJS.ErrnoException).code === "ENOENT") return null; throw error; }
    const row = await this.get({ shareId });
    return row?.token === required.token && row.file === required.file && row.status === "active" ? row : null;
  }
  async disable(required: { shareId: string; site: string }, _optional: Record<string, never> = {}): Promise<SiteShareRecord | null> {
    const row = await this.get(required);
    if (!row) return null;
    const revokedAt = row.revokedAt ?? new Date().toISOString();
    try { await writeFile(path.join(this.directory, `${row.shareId}.revoked`), revokedAt, { flag: "wx", mode: 0o600 }); }
    catch (error) { if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error; }
    const revoked = { ...row, status: "revoked" as const, revokedAt };
    await this.writeRecord(revoked);
    return revoked;
  }
  async writeArtifact(required: { shareId: string; bytes: Buffer }, _optional: Record<string, never> = {}): Promise<void> {
    if (required.bytes.length > SHARE_LIMITS.maxArchiveBytes) throw new SiteShareRefusal({ code: "LIMIT_EXCEEDED", message: "Share exceeds the 300 MiB archive cap." });
    await mkdir(this.directory, { recursive: true, mode: 0o700 });
    const space = await statfs(this.directory);
    if (space.bavail * space.bsize < required.bytes.length + 16 * 1024 * 1024) throw new SiteShareRefusal({ code: "INSUFFICIENT_STORAGE", message: "Insufficient private storage for this ZIP and 16 MiB of working space." });
    await writeFile(this.artifactPath(required), required.bytes, { flag: "wx", mode: 0o600 });
  }
  async deleteArtifact(required: { shareId: string }, _optional: Record<string, never> = {}): Promise<void> {
    await unlink(this.artifactPath(required)).catch(error => { if (error.code !== "ENOENT") throw error; });
  }
}

/**
 * A fresh share id and public token. `randomInt` draws from the CSPRNG and rejection-samples, so each
 * of the 52 letters is equally likely (no modulo bias): 16 draws give log2(52^16) ≈ 91 bits.
 * @complexity O(SHARE_TOKEN_LENGTH).
 */
export function newShareIdentity(_required: Record<string, never>, _optional: Record<string, never> = {}): { shareId: string; token: string } {
  const token = Array.from({ length: SHARE_TOKEN_LENGTH }, () => SHARE_TOKEN_ALPHABET[randomInt(SHARE_TOKEN_ALPHABET.length)]).join("");
  return { shareId: randomUUID(), token };
}

import { createHash } from "node:crypto";
import path from "node:path";
import type { ArtifactStorePort } from "@jini-ai/devops/deploy";
import { SiteShareRegistry, newShareIdentity, SHARE_FILE, type SiteShareRecord } from "./share-registry.js";
import { SiteShareRefusal } from "./share-policy.js";

export const SHARE_DOWNLOAD_HEADERS = {
  "Content-Type": "application/zip",
  "Cache-Control": "no-store",
  "X-Content-Type-Options": "nosniff",
  "X-Robots-Tag": "noindex, nofollow",
  "Referrer-Policy": "no-referrer",
} as const;
export interface ShareDelivery { readonly provider: string; readonly binding?: string; readonly store: ArtifactStorePort }

/** The one receiver for locally generated and authenticated management-uploaded artifacts. */
export async function receiveSiteShareArtifact(required: { registry: SiteShareRegistry; site: string; token: string; file: string; archive: Buffer }, optional: { storage?: SiteShareRecord["storage"] } = {}): Promise<SiteShareRecord> {
  const row: SiteShareRecord = { shareId: newShareIdentity({}).shareId, token: required.token, site: required.site, file: required.file, bytes: required.archive.length, sha256: createHash("sha256").update(required.archive).digest("hex"), url: null, status: "active", createdAt: new Date().toISOString(), revokedAt: null, ...(optional.storage ? { storage: optional.storage } : {}) };
  if (!SHARE_FILE.test(row.file)) throw new SiteShareRefusal({ code: "INVALID_INPUT", message: "Invalid share file name." });
  await required.registry.reserveToken(row);
  try {
    await required.registry.writeArtifact({ shareId: row.shareId, bytes: required.archive });
    await required.registry.put({ record: row });
  } catch (error) { await required.registry.deleteArtifact({ shareId: row.shareId }); throw error; }
  return row;
}

/** Persist before delivery; publish a URL only after an anonymous verification succeeds. O(bytes). */
export async function createSiteShare(required: { registry: SiteShareRegistry; site: string; name: string; archive: Buffer }, optional: { delivery?: ShareDelivery; signal?: AbortSignal } = {}): Promise<SiteShareRecord> {
  const identity = newShareIdentity({});
  // The derived stem always satisfies SHARE_FILE; receiveSiteShareArtifact re-checks it before any write.
  const file = `${shareFileStem({ name: required.name })}.tovu.zip`;
  const key = `_share/${identity.token}/${file}`;
  const row = await receiveSiteShareArtifact({ ...required, token: identity.token, file }, optional.delivery ? { storage: deliveryStorage({ delivery: optional.delivery, key }) } : {});
  if (optional.signal?.aborted) await cancelReceivedShare({ registry: required.registry, row });
  if (!optional.delivery) return row;
  return deliverShare({ registry: required.registry, row, delivery: optional.delivery, key, file, archive: required.archive }, { signal: optional.signal });
}

/** A lowercase, dash-separated file stem of at most 80 characters; `site` when nothing is left. */
function shareFileStem(required: { name: string }): string {
  return required.name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 80) || "site";
}

function deliveryStorage(required: { delivery: ShareDelivery; key: string }): NonNullable<SiteShareRecord["storage"]> {
  return { provider: required.delivery.provider, key: required.key, ...(required.delivery.binding ? { binding: required.delivery.binding } : {}) };
}

/**
 * True when the artifact lives in this server's own share folder, so there is nothing remote. This server's
 * runtime delivery binds a share to its catalog's absolute path; a connected peer binds it to a URL. A record
 * sits in the catalog that made it, and that catalog moves with the site folder, so the path it saved may be
 * stale after a move or rename: only its shape is compared, never its value (design 2026-10-27).
 */
export function isOwnShareFolder(required: { storage: { provider: string; binding?: string | undefined } }): boolean {
  return required.storage.provider === "tovu-server" && required.storage.binding !== undefined && path.isAbsolute(required.storage.binding);
}

async function cancelReceivedShare(required: { registry: SiteShareRegistry; row: SiteShareRecord }): Promise<never> {
  await required.registry.disable({ shareId: required.row.shareId, site: required.row.site });
  await required.registry.deleteArtifact({ shareId: required.row.shareId });
  throw new SiteShareRefusal({ code: "CANCELLED", message: "Share export was cancelled." });
}

async function deliverShare(required: { registry: SiteShareRegistry; row: SiteShareRecord; delivery: ShareDelivery; key: string; file: string; archive: Buffer }, optional: { signal?: AbortSignal | undefined }): Promise<SiteShareRecord> {
  const { registry, row, delivery, key } = required;
  let uploadedUrl: string | null = null;
  try {
    const { url } = await delivery.store.upload({ key, bytes: required.archive, headers: { ...SHARE_DOWNLOAD_HEADERS, "Content-Disposition": `attachment; filename="${required.file}"` } }, { signal: optional.signal });
    uploadedUrl = url;
    await registry.put({ record: { ...row, storage: { ...row.storage, provider: delivery.provider, key, url } } });
    if (!await delivery.store.verify({ key, url, present: true, bytes: row.bytes }, { signal: optional.signal })) throw new SiteShareRefusal({ code: "DELIVERY_FAILED", message: "Storage upload could not be verified anonymously with the required download headers. Configure public object access and download headers." });
    const current = await registry.get({ shareId: row.shareId });
    if (current?.status === "revoked") throw new SiteShareRefusal({ code: "REVOKED", message: "Share was revoked during upload." });
    const delivered = { ...row, url };
    await registry.put({ record: delivered });
    return delivered;
  } catch (error) {
    // A failed public upload must be removed too. Keep its locator if deletion fails, so revoke
    // can retry; the failure is never reported as a successful link.
    await registry.put({ record: { ...row, status: "failed", storage: { ...row.storage, provider: delivery.provider, key, ...(uploadedUrl ? { url: uploadedUrl } : {}) } } });
    await purgeFailedDelivery({ registry, row, delivery, key, uploadedUrl });
    if (error instanceof SiteShareRefusal) throw error;
    throw new SiteShareRefusal({ code: "DELIVERY_FAILED", message: `Share ${row.shareId} delivery failed. Download the ZIP or configure storage and retry.` });
  }
}

async function purgeFailedDelivery(required: { registry: SiteShareRegistry; row: SiteShareRecord; delivery: ShareDelivery; key: string; uploadedUrl: string | null }): Promise<void> {
  const { delivery, key, uploadedUrl } = required;
  try {
    if (!isOwnShareFolder({ storage: delivery })) {
      await delivery.store.delete({ key });
      if (uploadedUrl && !await delivery.store.verify({ key, url: uploadedUrl, present: false })) throw new Error("purge unverified");
    }
  }
  catch { throw new SiteShareRefusal({ code: "DELIVERY_CLEANUP_FAILED", message: `Share ${required.row.shareId} delivery failed and remote deletion/purge could not be verified. Retry site_share_revoke.` }); }
}

/** Disable locally first, then delete remotely and verify disappearance; failed cleanup is retryable. */
export async function revokeSiteShare(required: { registry: SiteShareRegistry; site: string; shareId: string }, optional: { delivery?: ShareDelivery } = {}): Promise<SiteShareRecord> {
  const row = await required.registry.disable(required);
  if (!row) throw new SiteShareRefusal({ code: "NOT_FOUND", message: "Share not found for this site." });
  try { await required.registry.deleteArtifact({ shareId: row.shareId }); }
  catch { throw new SiteShareRefusal({ code: "DELETE_FAILED", message: "Share token is disabled but its ZIP could not be deleted. Retry revoke." }); }
  if (row.storage && !isOwnShareFolder({ storage: row.storage })) await deleteRemoteArtifact({ row, storage: row.storage }, { delivery: optional.delivery });
  return row;
}

async function deleteRemoteArtifact(required: { row: SiteShareRecord; storage: NonNullable<SiteShareRecord["storage"]> }, optional: { delivery?: ShareDelivery | undefined }): Promise<void> {
  const { storage } = required, { delivery } = optional;
  if (!delivery || delivery.provider !== storage.provider || storage.binding !== delivery.binding) throw new SiteShareRefusal({ code: "DELETE_FAILED", message: "Share is disabled locally; configure its original storage to delete the remote artifact." });
  try {
    await delivery.store.delete({ key: storage.key });
    const url = required.row.url ?? storage.url;
    if (url && !await delivery.store.verify({ key: storage.key, url, present: false })) throw new Error("purge unverified");
  } catch { throw new SiteShareRefusal({ code: "DELETE_FAILED", message: "Share is disabled locally but remote deletion/purge is not verified. Retry revoke." }); }
}

import { excludedSharePath, validateSharePath } from "./share-file-policy.js";
import { checkShareLimits, SiteShareRefusal } from "./share-policy.js";
import { createHash } from "node:crypto";
import { constants as fsConstants, type Dirent, type Stats } from "node:fs";
import { lstat, mkdtemp, open, readdir, readFile, realpath, rm, stat, unlink } from "node:fs/promises";
import path from "node:path";

import type { DbOpsPort } from "#src/contracts/core/gated-mutations/ports";
import { describeErrorForLog } from "@jini-ai/core/model-facing-tool-errors";
import { listSitePluginPackage, type PluginDiscoveryRecord } from "@jini-ai/plugins/host/node";
import type { AgentPluginLayout } from "../agent-plugins/layout.js";

/**
 * @file What a site backup is made of, read from this machine: which files on disk each scope switch
 * picks up, the database snapshot, the size limits, re-reading a planned file at push time, and the
 * `tovu-backup.json` manifest a future restore reads first. No network here — the git-host plugin provider (`source-control/provider-module.ts`) owns
 * GitHub, `tool-registrations.ts` owns the order these run in.
 *
 * The backup folder's layout (paths relative to the folder root):
 * - `tovu-backup.json` — the manifest ({@link buildSiteBackupManifest}).
 * - `database/content.db` — the snapshot ({@link captureDatabaseSnapshot}), rebuilt through the share
 *   policy before upload (`backup-service.ts` `captureBackupDatabase`: no accounts or secrets). NEVER the live
 *   `content.db` file: a plain read of a WAL-mode database can miss committed pages still in
 *   `content.db-wal`. The snapshot comes only from `DbOpsPort.captureRestorePoint` (SQLite's online
 *   backup API), the same consistent copy the gated-mutation restore points use.
 * - `uploads/**` (media), `themes/**` (themes), `agent-plugins/**` and `skills/**` (plugins),
 *   `settings/config.json` and `settings/.site-meta.json` (settings).
 *
 * Deliberately never included, by construction (each scope walks only its own subtree):
 * - `chat.db` and `uploads/chat-attachments/` — chat history, not site content.
 * - `ops/` (the database journal), `out/` (the rendered export, which `source_control_execute_commit`
 *   already pushes), `content.seed.db` and stray `restore-point-*.db` files.
 * - `.mcp.*.json` (MCP server env, can hold tokens) and `.fs-custom-root.json` (a local path).
 * - `agent-plugins/ws/<id>/<plugin>/data/` and the legacy `agent-plugins/ws/<id>/data/` (plugin OAuth
 *   tokens), `staging/` and `packages/superseded-*`.
 * - `.DS_Store` and any `.git` segment.
 * - Symbolic links, never followed: a link to `~/.ssh` inside `themes/` must not ride along. Each
 *   one is reported in `skipped` so the human sees it was left out.
 */

/** One switch in a backup's `include`. */
export type SiteBackupScope = "database" | "media" | "themes" | "plugins" | "settings";

/** Every scope, in the fixed order the manifest and the confirmation dialog list them. */
export const SITE_BACKUP_SCOPES: readonly SiteBackupScope[] = ["database", "media", "themes", "plugins", "settings"];

/** Which scopes a backup includes. */
export type SiteBackupInclude = Record<SiteBackupScope, boolean>;

const MIB = 1024 * 1024;

/** This tool's own caps, checked before anything is uploaded, so one call cannot hold an unbounded
 *  number of blob uploads open against the site's own request budget. The host's per-file limit is
 *  not here: the host's plugin declares it ({@link SiteBackupHostLimit}). */
export const SITE_BACKUP_LIMITS = { maxTotalBytes: 1024 * MIB, maxFiles: 3000 } as const;

/** The repository host a backup goes to, as its plugin declares it (`SourceControlHostFacts`): its
 *  name, and the largest single file it accepts in a push (a push with a larger blob is rejected). */
export interface SiteBackupHostLimit {
  readonly label: string;
  readonly maxFileBytes?: number;
}

export interface SiteBackupLimits {
  readonly maxTotalBytes: number;
  readonly maxFiles: number;
}

/** Where the manifest and the database snapshot live inside the backup folder. */
export const SITE_BACKUP_MANIFEST_PATH = "tovu-backup.json";
export const SITE_BACKUP_DATABASE_PATH = "database/content.db";

/** Where each scope's bytes live on this machine — resolved once by the composition root
 *  (`server/runtime/composition/deps.ts`'s `createSiteRouteDeps`), so this file never re-derives a
 *  site path itself. */
export interface SiteBackupSources {
  readonly siteDir: string;
  /** `null` when media lives in object storage (`TOVU_MEDIA_BLOB_STORE=s3`): there is no folder on
   *  this machine to back up, and {@link collectSiteBackupFiles} says so instead of backing up
   *  nothing silently. */
  readonly mediaUploadsDir: string | null;
  /** The effective media provider is remote — read at backup time, since a site-setting choice
   *  (`core.storage.mediaObjectStore`) is not known at boot the way the env override is. When it
   *  answers `true` the uploads folder is not walked (it is not where media lives) and the scope
   *  note is written, exactly as for a `null` {@link mediaUploadsDir}. */
  readonly isMediaRemote?: () => Promise<boolean>;
  readonly themesDir: string;
  /** The installer's own layout (`features/agent-plugins/layout.ts`), never a re-derived path: every
   *  plugin folder the backup reads comes from the same helpers `install.ts` writes through, so a
   *  layout move cannot silently drop installed packages from a backup again. */
  readonly agentPlugins: AgentPluginLayout;
  readonly skillsDir: string;
  readonly tovuVersion: string;
  /** The site plugin install folder and Jini's discovery of it with the activation pins (the version
   *  boot runs): a share ships only what Jini lists for a valid record. Absent: no plugin ships. */
  readonly sitePlugins?: () => Promise<{ installDir: string; records: readonly PluginDiscoveryRecord[] }>;
}

/** One file on disk a backup will upload. `bytes` and `mtimeMs` are what {@link readPlannedFile}
 *  compares against at push time. */
export interface PlannedDiskFile {
  /** Relative to the backup folder, `/`-separated. A share's site plugin file is already its archive
   *  path (`plugins/<id>/package/<path in the package>`); `absPath` is still the file on disk. */
  readonly path: string;
  readonly bytes: number;
  readonly scope: SiteBackupScope;
  readonly absPath: string;
  readonly mtimeMs: number;
  /** A share's theme or site plugin package file: the sha256 hex of the bytes checked when it was planned, at an
   *  `absPath` reached through no link. {@link readPlannedFile} then returns only those exact bytes, so
   *  what ships is what was checked (size and mtime alone cannot tell a same-size swap). */
  readonly sha256?: string;
}

export interface SkippedSiteBackupFile {
  readonly path: string;
  readonly reason: string;
}

export interface CollectedSiteBackupFiles {
  readonly files: PlannedDiskFile[];
  readonly skipped: SkippedSiteBackupFile[];
  readonly scopeNotes: Partial<Record<SiteBackupScope, string>>;
}

/** Names never backed up wherever they appear. `.publish-staging`/`.publish-previous` are
 *  theme-files publish's own scratch and replaced-tree copies (`features/theme/publish-content.ts`) —
 *  a backup must never capture a half-staged tree. `.storage-secret.json` is a Postgres site's sealed
 *  connection string (`storage-secret.ts`): it lives in the site root, which no scope walks, and is
 *  named here too so a stray copy inside a walked folder never rides along. */
const IGNORED_NAMES = new Set([".DS_Store", ".git", ".publish-staging", ".publish-previous", ".storage-secret.json"]);

const SYMLINK_REASON = "a symbolic link — never followed, so nothing outside the site can ride along";

/** The walk's shared output, appended to in place by every scope. */
interface WalkSink {
  readonly files: PlannedDiskFile[];
  readonly skipped: SkippedSiteBackupFile[];
  readonly fileSystem: SiteBackupWalkFileSystem;
  readonly profile?: "share";
}

/** The filesystem reads used by backup collection, including files removed during the walk. */
export interface SiteBackupWalkFileSystem {
  readonly lstat: (file: string) => Promise<Stats>;
  readonly readdir: (dir: string) => Promise<Dirent[]>;
}

const WALK_FILE_SYSTEM: SiteBackupWalkFileSystem = {
  lstat,
  readdir: (dir) => readdir(dir, { withFileTypes: true }),
};

function isMissing(err: unknown): boolean {
  return typeof err === "object" && err !== null && (err as { code?: unknown }).code === "ENOENT";
}

/** `readdir` that treats a folder that doesn't exist as empty: a site with no themes folder yet has
 *  nothing to back up there, which is not an error. */
async function readdirOrEmpty(dir: string, fileSystem: SiteBackupWalkFileSystem): Promise<Dirent[]> {
  try {
    return await fileSystem.readdir(dir);
  } catch (err) {
    if (isMissing(err)) return [];
    throw err;
  }
}

/**
 * Adds one regular file to the sink, or records why it was left out. `lstat`, never `stat`: a
 * symlink's own metadata, never its target's.
 *
 * @complexity O(1) — one `lstat`.
 */
async function addFile(sink: WalkSink, input: { absPath: string; relPath: string; scope: SiteBackupScope }): Promise<void> {
  if (sink.profile === "share" && excludedSharePath({ path: input.relPath })) return;
  let info;
  try {
    info = await sink.fileSystem.lstat(input.absPath);
  } catch (err) {
    if (isMissing(err)) return;
    throw err;
  }
  if (info.isSymbolicLink()) {
    sink.skipped.push({ path: input.relPath, reason: SYMLINK_REASON });
    return;
  }
  if (!info.isFile()) {
    sink.skipped.push({ path: input.relPath, reason: "not a regular file" });
    return;
  }
  if (sink.profile === "share") {
    validateSharePath({ path: input.relPath });
    if (info.nlink > 1) throw new SiteShareRefusal({ code: "UNSAFE_FILE", message: `Share refuses hardlinked file '${input.relPath}'.` });
    checkShareLimits({ files: [...sink.files, { path: input.relPath, bytes: info.size }] });
  }
  sink.files.push({ path: input.relPath, bytes: info.size, scope: input.scope, absPath: input.absPath, mtimeMs: info.mtimeMs });
}

/**
 * Recursively adds every regular file under `absDir`. Symlinks (to files or folders) are reported
 * and never entered; {@link IGNORED_NAMES} are dropped silently; `excludeTopLevel` names are dropped
 * at the first level only (`uploads/chat-attachments`).
 *
 * @complexity O(entries under `absDir`) filesystem calls; recursion depth is the folder depth.
 */
async function walkTree(sink: WalkSink, input: { absDir: string; relDir: string; scope: SiteBackupScope; excludeTopLevel?: ReadonlySet<string> }): Promise<void> {
  if (sink.profile === "share" && !(await enterShareDirectory({ sink, absDir: input.absDir, relDir: input.relDir }))) return;
  const entries = await readdirOrEmpty(input.absDir, sink.fileSystem);
  for (const entry of entries) {
    if (skippedWalkEntry({ sink, relDir: input.relDir, name: entry.name }, { excludeTopLevel: input.excludeTopLevel })) continue;
    await walkEntry({ sink, entry, absDir: input.absDir, relDir: input.relDir, scope: input.scope });
  }
}

/** Share profile: a private folder is not entered, a missing one is empty, a linked or special one refuses. */
async function enterShareDirectory(required: { sink: WalkSink; absDir: string; relDir: string }): Promise<boolean> {
  if (excludedSharePath({ path: required.relDir })) return false;
  const info = await required.sink.fileSystem.lstat(required.absDir).catch(err => isMissing(err) ? null : Promise.reject(err));
  if (!info) return false;
  if (!info.isDirectory() || info.isSymbolicLink()) throw new SiteShareRefusal({ code: "UNSAFE_FILE", message: `Share refuses linked or special directory '${required.relDir}'.` });
  validateSharePath({ path: required.relDir });
  return true;
}

function skippedWalkEntry(required: { sink: WalkSink; relDir: string; name: string }, optional: { excludeTopLevel?: ReadonlySet<string> | undefined }): boolean {
  const { name } = required;
  // Finder writes .DS_Store into any folder it opens; it is junk, never content, so drop it before the share refusal list sees it.
  if (name === ".DS_Store") return true;
  if (required.sink.profile === "share" && excludedSharePath({ path: `${required.relDir}/${name}` })) return true;
  return IGNORED_NAMES.has(name) || optional.excludeTopLevel?.has(name) === true;
}

async function walkEntry(required: { sink: WalkSink; entry: Dirent; absDir: string; relDir: string; scope: SiteBackupScope }): Promise<void> {
  const { sink, entry, scope } = required;
  const absPath = path.join(required.absDir, entry.name);
  const relPath = `${required.relDir}/${entry.name}`;
  if (entry.isSymbolicLink()) {
    sink.skipped.push({ path: relPath, reason: SYMLINK_REASON });
  } else if (entry.isDirectory()) {
    await walkTree(sink, { absDir: absPath, relDir: relPath, scope });
  } else {
    await addFile(sink, { absPath, relPath, scope });
  }
}

/** The files each installed-plugin workspace keeps that a restore needs. Everything else there is
 *  left out on purpose: `data/` holds plugin OAuth tokens, `staging/` is a half-finished install,
 *  and `packages/superseded-*` are replaced versions. */
const PLUGIN_WORKSPACE_FILES: ReadonlySet<string> = new Set(["activations.json", "bundled-digests.json"]);

/** `agent-plugins/<path under the layout root>`, `/`-separated. */
function agentPluginsRelPath(layout: AgentPluginLayout, absPath: string): string {
  return ["agent-plugins", ...path.relative(layout.root, absPath).split(path.sep)].join("/");
}

/**
 * Walks `absDir` only when it, and every folder between `baseDir` and it, is a real directory: a
 * symlinked `package/` or `memory/` is reported, never entered, and a missing one is nothing to
 * back up.
 *
 * @complexity O(depth from `baseDir`) `lstat`s, plus the walk itself.
 */
async function walkOwnedDir(sink: WalkSink, input: { layout: AgentPluginLayout; baseDir: string; absDir: string }): Promise<void> {
  let current = input.baseDir;
  for (const segment of path.relative(input.baseDir, input.absDir).split(path.sep)) {
    current = path.join(current, segment);
    const info = await sink.fileSystem.lstat(current).catch((err: unknown) => (isMissing(err) ? null : Promise.reject(err)));
    if (info === null) return;
    if (info.isSymbolicLink()) {
      sink.skipped.push({ path: agentPluginsRelPath(input.layout, current), reason: SYMLINK_REASON });
      return;
    }
    if (!info.isDirectory()) return;
  }
  await walkTree(sink, { absDir: input.absDir, relDir: agentPluginsRelPath(input.layout, input.absDir), scope: "plugins" });
}

/**
 * The plugins scope's `agent-plugins/` half: per workspace, {@link PLUGIN_WORKSPACE_FILES}, the
 * legacy flat `packages/sha256/**` store (a site not yet migrated to per-plugin folders still has its
 * packages there), and per installed plugin its `package/sha256/**` store and its learned/notes
 * memory — nothing else. Memory is included because it is the site's own record (uninstall offers to
 * keep it); a plugin's `data/` is not, since it holds OAuth tokens. Every path comes from
 * `layout`'s helpers, the same ones the installer writes through.
 *
 * @complexity O(entries under each included folder).
 */
async function walkAgentPlugins(sink: WalkSink, layout: AgentPluginLayout): Promise<void> {
  for (const entry of await readdirOrEmpty(layout.workspacesDir, sink.fileSystem)) {
    const workspace = installerWorkspace({ sink, layout, entry });
    if (workspace) await walkPluginWorkspace({ sink, layout, workspace });
  }
}

type PluginWorkspace = ReturnType<AgentPluginLayout["forWorkspace"]>;

/** The workspace folder `entry` names, or `null` (reported when it is a link or a foreign folder). */
function installerWorkspace(required: { sink: WalkSink; layout: AgentPluginLayout; entry: Dirent }): PluginWorkspace | null {
  const { sink, layout, entry } = required;
  const absWorkspace = path.join(layout.workspacesDir, entry.name);
  if (entry.isSymbolicLink()) {
    sink.skipped.push({ path: agentPluginsRelPath(layout, absWorkspace), reason: SYMLINK_REASON });
    return null;
  }
  if (!entry.isDirectory()) return null;
  let workspace;
  try {
    workspace = layout.forWorkspace(entry.name);
  } catch {
    workspace = null;
  }
  // A folder the installer could never have written (an invalid id, or one that only resolves
  // after case-folding to a different folder) is reported rather than walked under a guessed shape.
  if (workspace === null || workspace.root !== absWorkspace) {
    sink.skipped.push({ path: agentPluginsRelPath(layout, absWorkspace), reason: "not a workspace folder the plugin installer writes" });
    return null;
  }
  return workspace;
}

async function walkPluginWorkspace(required: { sink: WalkSink; layout: AgentPluginLayout; workspace: PluginWorkspace }): Promise<void> {
  const { sink, layout, workspace } = required;
  for (const name of PLUGIN_WORKSPACE_FILES) {
    const absPath = path.join(workspace.root, name);
    await addFile(sink, { absPath, relPath: agentPluginsRelPath(layout, absPath), scope: "plugins" });
  }
  await walkOwnedDir(sink, { layout, baseDir: workspace.root, absDir: workspace.packages });
  for (const pluginEntry of await readdirOrEmpty(workspace.root, sink.fileSystem)) await walkInstalledPlugin({ sink, layout, workspace, pluginEntry });
}

async function walkInstalledPlugin(required: { sink: WalkSink; layout: AgentPluginLayout; workspace: PluginWorkspace; pluginEntry: Dirent }): Promise<void> {
  const { sink, layout, workspace, pluginEntry } = required;
  if (PLUGIN_WORKSPACE_FILES.has(pluginEntry.name) || (!pluginEntry.isDirectory() && !pluginEntry.isSymbolicLink())) return;
  let pluginRoot: string;
  try {
    pluginRoot = workspace.pluginRootDir({ pluginId: pluginEntry.name });
  } catch {
    return; // `staging/`, `packages/`, `data/` and anything not named like a plugin id.
  }
  if (pluginEntry.isSymbolicLink()) {
    sink.skipped.push({ path: agentPluginsRelPath(layout, pluginRoot), reason: SYMLINK_REASON });
    return;
  }
  const pluginId = pluginEntry.name;
  for (const absDir of [
    workspace.pluginPackagesDir({ pluginId }),
    workspace.pluginMemoryDir({ pluginId, kind: "learned" }),
    workspace.pluginMemoryDir({ pluginId, kind: "notes" }),
  ]) {
    await walkOwnedDir(sink, { layout, baseDir: pluginRoot, absDir });
  }
}

/** The one media note a backup can carry, and why: the bytes are not on this machine. */
const MEDIA_IN_OBJECT_STORAGE_NOTE =
  "Media is stored in object storage (TOVU_MEDIA_BLOB_STORE=s3 or the site's media storage setting), not in a folder on this server, so media files are not in this backup. The database still lists every media item.";

/**
 * Every file on disk the switched-on scopes pick up. The database scope is never a disk walk — see
 * {@link captureDatabaseSnapshot}.
 *
 * @returns `files` sorted by path, `skipped` (symlinks and non-regular files, each with its reason),
 *   and `scopeNotes` for a scope whose content could not be collected here at all.
 * @throws SiteShareRefusal for unsafe share files or stale themes, or an unexpected filesystem error
 *   (a missing folder is treated as empty).
 * @complexity O(entries + shared theme bytes), plus O(n log n) to sort n files.
 */
export async function collectSiteBackupFiles(input: { sources: SiteBackupSources; include: SiteBackupInclude }, optional: { fileSystem?: SiteBackupWalkFileSystem; profile?: "share" } = {}): Promise<CollectedSiteBackupFiles> {
  const { sources, include } = input;
  const sink: WalkSink = { files: [], skipped: [], fileSystem: optional.fileSystem ?? WALK_FILE_SYSTEM, ...(optional.profile ? { profile: optional.profile } : {}) };
  const scopeNotes: Partial<Record<SiteBackupScope, string>> = {};

  if (include.media) await collectMediaScope({ sink, sources, scopeNotes });
  if (include.themes) await walkTree(sink, { absDir: sources.themesDir, relDir: "themes", scope: "themes" });
  if (include.plugins) await collectPluginScope({ sink, sources });
  if (sink.profile === "share") {
    await collectShareOnlyTrees({ sink, sources, include, scopeNotes });
    await pinShareThemeFiles({ sink, siteDir: sources.siteDir });
  }
  if (include.settings) {
    for (const name of ["config.json", ".site-meta.json"]) {
      await addFile(sink, { absPath: path.join(sources.siteDir, name), relPath: `settings/${name}`, scope: "settings" });
    }
  }

  sink.files.sort(byPath);
  return { files: sink.files, skipped: sink.skipped, scopeNotes };
}

/** Pins share themes and overrides through the same no-linked-ancestor read as site plugins.
 *  Canonicalize only the trusted site root (macOS's /var can be a link), never the walked descendants.
 *  @throws SiteShareRefusal PLAN_STALE when a theme cannot be read as planned.
 *  @complexity O(files + theme bytes), one verified read and hash per theme; O(largest theme) bytes.
 */
async function pinShareThemeFiles(required: { sink: WalkSink; siteDir: string }): Promise<void> {
  const { files } = required.sink;
  if (!files.some(file => file.scope === "themes")) return;
  const root = await realpath(required.siteDir);
  const sitePrefix = path.resolve(required.siteDir) + path.sep;
  for (const [index, file] of files.entries()) {
    if (file.scope !== "themes") continue;
    // Packaged originals can live outside the site; retain their own absolute path.
    const absPath = file.absPath.startsWith(sitePrefix) ? path.join(root, file.absPath.slice(sitePrefix.length)) : file.absPath;
    const planned = { ...file, absPath };
    const read = await readDiskFile(planned, { unlinkedPath: true });
    if (!read.ok) throw new SiteShareRefusal({ code: "PLAN_STALE", message: read.message });
    files[index] = { ...planned, sha256: sha256Hex(read.bytes) };
  }
}

/** Code-unit order: -1, 0 or 1, the same as `a < b ? -1 : a > b ? 1 : 0`. */
function byPath(a: { path: string }, b: { path: string }): number {
  return Number(a.path > b.path) - Number(a.path < b.path);
}

/** The uploads folder, minus chat attachments; object-storage media is noted, never silently empty. */
async function collectMediaScope(required: { sink: WalkSink; sources: SiteBackupSources; scopeNotes: Partial<Record<SiteBackupScope, string>> }): Promise<void> {
  const { mediaUploadsDir, isMediaRemote } = required.sources;
  if (mediaUploadsDir === null || (await isMediaRemote?.())) required.scopeNotes.media = MEDIA_IN_OBJECT_STORAGE_NOTE;
  else await walkTree(required.sink, { absDir: mediaUploadsDir, relDir: "uploads", scope: "media", excludeTopLevel: new Set(["chat-attachments"]) });
}

/** Installed agent plugins and skills; a share first refuses a linked or special plugin root. */
async function collectPluginScope(required: { sink: WalkSink; sources: SiteBackupSources }): Promise<void> {
  const { sink, sources } = required;
  if (sink.profile === "share") {
    for (const root of [sources.agentPlugins.root, sources.agentPlugins.workspacesDir]) {
      const info = await sink.fileSystem.lstat(root).catch(err => isMissing(err) ? null : Promise.reject(err));
      if (info && (!info.isDirectory() || info.isSymbolicLink())) throw new SiteShareRefusal({ code: "UNSAFE_FILE", message: "Share refuses a linked plugin root." });
    }
  }
  await walkAgentPlugins(sink, sources.agentPlugins);
  await walkTree(sink, { absDir: sources.skillsDir, relDir: "skills", scope: "plugins" });
}

/** Site-local plugin packages and theme overrides travel only in a share. */
async function collectShareOnlyTrees(required: { sink: WalkSink; sources: SiteBackupSources; include: SiteBackupInclude; scopeNotes: Partial<Record<SiteBackupScope, string>> }): Promise<void> {
  const { sink, sources, include } = required;
  if (include.plugins) await walkSitePlugins(required);
  if (include.themes) await walkTree(sink, { absDir: path.join(sources.siteDir, "overrides"), relDir: "overrides", scope: "themes" });
}

/**
 * Site plugins exactly as Jini lays them out: for each folder in the install dir, the files
 * `listSitePluginPackage` names for its valid, pinned discovery record (manifest plus integrity files),
 * as `plugins/<id>/package/<path>`. Nothing else under the folder is walked, so no folder name, missing
 * manifest or fallen-forward pin can turn data/ or private memory into package content. A folder that
 * is not a valid installed plugin, or whose files fail their checks, ships nothing and is named in the
 * plugins scope note; the export carries on (the owner never has to repair a folder by hand).
 * @complexity O(install-dir entries + listed files), one read and hash per listed file.
 */
async function walkSitePlugins(required: { sink: WalkSink; sources: SiteBackupSources; scopeNotes: Partial<Record<SiteBackupScope, string>> }): Promise<void> {
  const { sink, sources } = required;
  const { installDir, records } = await sources.sitePlugins?.() ?? { installDir: path.join(sources.siteDir, "plugins"), records: [] };
  if (!(await enterShareDirectory({ sink, absDir: installDir, relDir: "plugins" }))) return;
  const leftOut: string[] = [];
  for (const { name } of await readdirOrEmpty(installDir, sink.fileSystem)) {
    if (name.startsWith(".")) continue; // Jini's own staging (`.drafts`) and Finder files; never a plugin.
    const record = records.find(candidate => candidate.source === "site" && candidate.id === name);
    const files = record && await sitePluginPackageFiles({ sink, installDir, record });
    if (files) sink.files.push(...files);
    else leftOut.push(name);
  }
  if (leftOut.length > 0) required.scopeNotes.plugins = `Left out because they aren't valid installed plugins (damaged manifest, version not installed, or changed files): ${leftOut.sort().map(name => `'${name}'`).join(", ")}.`;
}

/** One plugin's planned files, each through the walk's guards, read once through no linked folder and
 *  checked against its integrity sha256, then pinned to the bytes read (the manifest too) so the ZIP
 *  carries exactly them; `null` when Jini will not list it or any listed file is missing, linked,
 *  excluded or changed. */
async function sitePluginPackageFiles(required: { sink: WalkSink; installDir: string; record: PluginDiscoveryRecord }): Promise<PlannedDiskFile[] | null> {
  const { record } = required;
  const listed = await listSitePluginPackage({ installDir: required.installDir, record }).catch(() => null);
  if (listed === null) return null;
  const staged: WalkSink = { ...required.sink, files: [], skipped: [] };
  for (const file of listed.files) {
    await addFile(staged, { absPath: path.join(listed.rootDir, file.relativePath), relPath: `plugins/${record.id}/package/${file.relativePath}`, scope: "plugins" });
  }
  // addFile adds nothing for a missing, excluded, linked or non-regular file, so a short list is every refusal.
  if (staged.files.length !== listed.files.length) return null;
  const pinned: PlannedDiskFile[] = [];
  for (const [index, planned] of staged.files.entries()) {
    const expected = listed.files[index]!.sha256;
    const read = await readDiskFile(planned, { unlinkedPath: true });
    const sha256 = read.ok ? sha256Hex(read.bytes) : null;
    if (sha256 === null || (expected !== null && sha256 !== expected)) return null;
    pinned.push({ ...planned, sha256 });
  }
  return pinned;
}

function sha256Hex(bytes: Buffer): string {
  return createHash("sha256").update(bytes).digest("hex");
}

export type DatabaseSnapshotResult = { ok: true; bytes: Buffer; watermarkAtCapture: number } | { ok: false; message: string; logDetail?: string };

const SNAPSHOT_FAILED = "the database snapshot failed; nothing was backed up";

/**
 * A consistent copy of the whole site database, held in memory.
 *
 * Only a cheap file snapshot (SQLite) is accepted: that is the only restore mechanism whose artifact
 * is a single file this process can read back. Anything else is refused BEFORE a capture is attempted.
 * The restore-point file `captureRestorePoint` writes (beside `content.db`, or inside a fresh private
 * folder under `optional.snapshotRoot`) is deleted as soon as it is read, success or not, so a backup
 * never leaves one behind. A site export passes `snapshotRoot` so it never writes into source-site storage.
 *
 * @returns The snapshot bytes and the watermark stamped at capture, or a caller-safe `message` (a
 *   capture failure's own text stays in `logDetail`, which is for the server log only).
 * @complexity O(database size) — one full copy, one read, one unlink.
 */
export async function captureDatabaseSnapshot(input: { dbOps: DbOpsPort; scopeId: string }, optional: { maxBytes?: number; snapshotRoot?: string } = {}): Promise<DatabaseSnapshotResult> {
  const { restorePoint } = await input.dbOps.getCapabilities();
  if (restorePoint.costClass !== "cheap" || restorePoint.kind !== "file-snapshot") {
    return {
      ok: false,
      message: `this site's database cannot be snapshotted into a backup file: only SQLite sites are supported (this database reports a '${restorePoint.kind}' restore mechanism)`,
    };
  }
  if (optional.snapshotRoot === undefined) return readRestorePoint(input, optional);
  let directory: string;
  try {
    directory = await mkdtemp(path.join(optional.snapshotRoot, "tovu-snapshot-"));
  } catch (err) {
    return { ok: false, message: SNAPSHOT_FAILED, logDetail: describeErrorForLog({ err }) };
  }
  try {
    return await readRestorePoint(input, { ...optional, directory });
  } finally {
    await rm(directory, { recursive: true, force: true }).catch(() => undefined);
  }
}

/** Captures one restore point (into `directory` when given), reads it back and unlinks it. */
async function readRestorePoint(input: { dbOps: DbOpsPort; scopeId: string }, optional: { maxBytes?: number; directory?: string }): Promise<DatabaseSnapshotResult> {
  let artifactRef: string;
  let watermarkAtCapture: number;
  try {
    const scope = { scopeId: input.scopeId };
    ({ artifactRef, watermarkAtCapture } = await (optional.directory === undefined ? input.dbOps.captureRestorePoint(scope) : input.dbOps.captureRestorePoint(scope, { directory: optional.directory })));
  } catch (err) {
    return { ok: false, message: SNAPSHOT_FAILED, logDetail: describeErrorForLog({ err }) };
  }
  try {
    if (optional.maxBytes !== undefined && (await stat(artifactRef)).size > optional.maxBytes) return { ok: false, message: "Database snapshot exceeds the 300 MiB share cap." };
    return { ok: true, bytes: await readFile(artifactRef), watermarkAtCapture };
  } catch (err) {
    return { ok: false, message: "the database snapshot could not be read back; nothing was backed up", logDetail: describeErrorForLog({ err }) };
  } finally {
    await unlink(artifactRef).catch(() => undefined);
  }
}

/** One decimal place, dropped when it is `.0` (`100 MiB`, not `100.0 MiB`). */
function oneDecimal(value: number): string {
  return value.toFixed(1).replace(/\.0$/, "");
}

/** `123 B`, `4.2 KiB`, `12.5 MiB`, `1 GiB` — for messages and the confirmation dialog. */
export function formatByteSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < MIB) return `${oneDecimal(bytes / 1024)} KiB`;
  if (bytes < 1024 * MIB) return `${oneDecimal(bytes / MIB)} MiB`;
  return `${oneDecimal(bytes / (1024 * MIB))} GiB`;
}

/**
 * Leaves out every disk file over the host's per-file limit, each named in `skipped` with its size,
 * so one huge video does not cost the whole backup (2026-10-06: the owner asked for a full backup
 * that just works). The database is not a disk file here: an oversized snapshot still fails the plan
 * in {@link checkSiteBackupLimits}, because a backup without its database is not a backup.
 *
 * @complexity O(n).
 */
export function skipOversizedFiles(files: readonly PlannedDiskFile[], host: SiteBackupHostLimit): { files: PlannedDiskFile[]; skipped: SkippedSiteBackupFile[] } {
  const maxFileBytes = host.maxFileBytes;
  if (maxFileBytes === undefined) return { files: [...files], skipped: [] };
  const skipped = files
    .filter((file) => file.bytes > maxFileBytes)
    .map((file) => ({ path: file.path, reason: `${formatByteSize(file.bytes)}, over ${host.label}'s ${formatByteSize(maxFileBytes)} per-file limit` }));
  return { files: files.filter((file) => file.bytes <= maxFileBytes), skipped };
}

export type SiteBackupLimitsResult = { ok: true; totalBytes: number } | { ok: false; message: string };

/**
 * Checks a backup against {@link SITE_BACKUP_LIMITS} and the host's own per-file limit (when its
 * plugin declares one) before anything is uploaded. A file over the per-file limit is refused, never truncated or split — and EVERY such file is named, so one retry
 * after removing them is enough. The plan runs {@link skipOversizedFiles} over the disk files first,
 * so in practice only an oversized database snapshot reaches this refusal.
 *
 * @complexity O(n) in the file count.
 */
export function checkSiteBackupLimits(
  files: readonly { path: string; bytes: number }[],
  host: SiteBackupHostLimit,
  limits: SiteBackupLimits = SITE_BACKUP_LIMITS,
): SiteBackupLimitsResult {
  const maxFileBytes = host.maxFileBytes;
  const oversized = maxFileBytes === undefined ? [] : files.filter((file) => file.bytes > maxFileBytes);
  if (maxFileBytes !== undefined && oversized.length > 0) {
    // The exact byte count too: a file 1 byte over rounds to the limit's own size.
    const named = oversized.map((file) => `${file.path} (${formatByteSize(file.bytes)}, ${file.bytes} bytes)`).join(", ");
    return {
      ok: false,
      message: `${oversized.length} file(s) exceed ${host.label}'s ${formatByteSize(maxFileBytes)} per-file limit and cannot be backed up: ${named}. Nothing is truncated or split; remove or shrink these, or turn off the scope that holds them.`,
    };
  }
  if (files.length > limits.maxFiles) {
    return { ok: false, message: `the backup has ${files.length} files, over the ${limits.maxFiles}-file cap. Turn off a scope (media usually holds the most files) and plan again.` };
  }
  const totalBytes = files.reduce((sum, file) => sum + file.bytes, 0);
  if (totalBytes > limits.maxTotalBytes) {
    return { ok: false, message: `the backup totals ${formatByteSize(totalBytes)}, over the ${formatByteSize(limits.maxTotalBytes)} cap. Turn off a scope (media usually holds the most bytes) and plan again.` };
  }
  return { ok: true, totalBytes };
}

export type ReadPlannedFileResult = { ok: true; bytes: Buffer } | { ok: false; message: string };

/** The opened file's metadata and bytes must come from the same handle. */
export interface SiteBackupReadHandle {
  stat(): Promise<Pick<Stats, "isFile" | "size" | "mtimeMs">>;
  readFile(): Promise<Buffer>;
  close(): Promise<void>;
}

type ReadPlannedFileOptions = { openFile?: (file: string, flags: number) => Promise<SiteBackupReadHandle> };

/**
 * Reads a planned file at push time, refusing it if it is no longer the file the human reviewed.
 *
 * Opened with `O_NOFOLLOW` and checked through the SAME handle it is read from, so a file swapped
 * for a symlink after the plan cannot be followed, and the size/mtime compared are the bytes
 * actually read. A file planned with a `sha256` must also still be reached through no linked folder
 * and hash to exactly that digest.
 *
 * @complexity O(file size) — one open, one fstat, one read (plus one realpath and one hash when pinned).
 */
export async function readPlannedFile(file: PlannedDiskFile, optional: ReadPlannedFileOptions = {}): Promise<ReadPlannedFileResult> {
  const read = await readDiskFile(file, { ...optional, unlinkedPath: file.sha256 !== undefined });
  return read.ok && file.sha256 !== undefined && sha256Hex(read.bytes) !== file.sha256 ? staleResult(file) : read;
}

function staleResult(file: PlannedDiskFile): ReadPlannedFileResult {
  return { ok: false, message: `'${file.path}' changed since the plan was made. Call site_backup_plan again.` };
}

/** The one disk read behind planning checks and push: `unlinkedPath` also refuses an `absPath` whose
 *  realpath differs, i.e. one reached through a linked folder (`O_NOFOLLOW` guards only the last name). */
async function readDiskFile(file: PlannedDiskFile, optional: ReadPlannedFileOptions & { unlinkedPath?: boolean }): Promise<ReadPlannedFileResult> {
  const stale = staleResult(file);
  let handle;
  try {
    handle = await (optional.openFile ?? open)(file.absPath, fsConstants.O_RDONLY | (fsConstants.O_NOFOLLOW ?? 0));
  } catch {
    return stale;
  }
  try {
    if (optional.unlinkedPath && (await realpath(file.absPath).catch(() => null)) !== file.absPath) return stale;
    const info = await handle.stat();
    if (!info.isFile() || info.size !== file.bytes || info.mtimeMs !== file.mtimeMs) return stale;
    const bytes = await handle.readFile();
    return bytes.length === file.bytes ? { ok: true, bytes } : stale;
  } finally {
    await handle.close();
  }
}

export interface SiteBackupManifestInput {
  readonly createdAt: string;
  readonly tovuVersion: string;
  readonly schema: { readonly index: number; readonly tag: string };
  readonly site: { readonly name: string; readonly folderName: string };
  /** `null` when the database scope is off. */
  readonly database: { readonly watermarkAtCapture: number } | null;
  readonly include: SiteBackupInclude;
  readonly scopeNotes: Partial<Record<SiteBackupScope, string>>;
  readonly files: readonly { readonly path: string; readonly bytes: number; readonly sha256: string }[];
}

/**
 * The backup's `tovu-backup.json`: what produced it (Tovu version, migration schema), when, which
 * scopes it holds and why any is incomplete, and every file with its sha256 — what a future restore
 * checks before touching anything.
 *
 * @complexity O(n) in the file count.
 */
export function buildSiteBackupManifest(input: SiteBackupManifestInput): string {
  const scopes = Object.fromEntries(
    SITE_BACKUP_SCOPES.map((scope) => {
      const note = input.scopeNotes[scope];
      return [scope, { included: input.include[scope], ...(note !== undefined ? { note } : {}) }];
    })
  );
  const manifest = {
    format: "tovu-site-backup",
    formatVersion: 1,
    createdAt: input.createdAt,
    tovu: { version: input.tovuVersion },
    schema: { index: input.schema.index, tag: input.schema.tag },
    site: { name: input.site.name, folderName: input.site.folderName },
    database: input.database === null ? null : { path: SITE_BACKUP_DATABASE_PATH, engine: "sqlite", watermarkAtCapture: input.database.watermarkAtCapture },
    scopes,
    files: input.files.map((file) => ({ path: file.path, bytes: file.bytes, sha256: file.sha256 })),
  };
  return `${JSON.stringify(manifest, null, 2)}\n`;
}

