const SHARE_ACTIONS: Record<"create" | "list" | "revoke", ShareAction> = {
  list: async ({ backend, raw }) => {
    if (Object.keys(raw).length) throw new SiteShareRefusal({ code: "INVALID_INPUT", message: "site_share_list takes no fields." });
    return { shares: await backend.list({}) };
  },
  revoke: async ({ backend, raw }) => {
    if (Object.keys(raw).some(key => key !== "shareId")) throw new SiteShareRefusal({ code: "INVALID_INPUT", message: "Only shareId is accepted." });
    return await backend.revoke({ shareId: requireString({ input: raw, key: "shareId" }) });
  },
  create: async ({ backend, raw, ctx }) => {
    if (Object.keys(raw).some(key => key !== "jobId") || raw.jobId !== undefined && (typeof raw.jobId !== "string" || !/^[0-9a-f-]{36}$/.test(raw.jobId))) throw new SiteShareRefusal({ code: "INVALID_INPUT", message: "Only an optional share jobId is accepted." });
    return await backend.create({ principalId: ctx.principal.id, signal: ctx.signal, ...(typeof raw.jobId === "string" ? { jobId: raw.jobId } : {}) });
  },
};

/** Authorization stays on the existing backup contributor; backend effects are shared with HTTP. */
async function handleShare(required: { deps: SiteBackupToolDeps; ctx: ToolExecutionContext; action: "create" | "list" | "revoke" }, _optional: Record<string, never> = {}): Promise<unknown> {
  const { deps, ctx, action } = required;
  const raw = requireInputRecord({ input: ctx.input });
  await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: PUSH_PERMISSION }, { entityType: DOMAIN });
  if (!deps.siteShareBackend) return { ok: false, code: "UNAVAILABLE", message: "Site sharing requires a site folder and private storage." };
  try {
    return await SHARE_ACTIONS[action]({ backend: deps.siteShareBackend, raw, ctx });
  } catch (error) {
    if (error instanceof SiteShareRefusal) return { ok: false, code: error.code, message: error.message };
    throw error;
  }
}

/**
 * Builds this domain's `ToolRegistration[]`.
 *
 * @complexity O(1) at registration.
 */
export function buildSiteBackupRegistrations(deps: SiteBackupToolDeps, _surfaces: AssistantSurfaceDeps): ToolRegistration[] {
  const handlers: Record<string, ToolHandler> = {
    site_import_backup: ctx => handleImport({ deps, ctx, list: false }),
    site_import_list: ctx => handleImport({ deps, ctx, list: true }),
    [PLAN_TOOL_ID]: (ctx) => planSiteBackup({ deps, call: ctx }),
    [SITE_BACKUP_PUSH_TOOL_ID]: (ctx) => pushSiteBackup({ deps, call: ctx }),
    site_share_create: (ctx) => handleShare({ deps, ctx, action: "create" }),
    site_share_list: (ctx) => handleShare({ deps, ctx, action: "list" }),
    site_share_revoke: (ctx) => handleShare({ deps, ctx, action: "revoke" }),
  };
  return buildDomainRegistrations({ metadata: toolMetadata,
    domain: DOMAIN,
    catalogModule: "features/site-backup/tool-registrations.ts",
    catalog: CATALOG_BY_ID,
    handlers: withModelFacingErrors({ handlers, rules: SITE_BACKUP_MODEL_FACING_ERRORS }),
    derivedRisk: siteBackupDerivedRisk,
  });
}

/** Contributes the site-backup tools — called once by `server/runtime/composition/
 *  tool-catalog-manifest.ts`'s `installFirstPartyToolContributors()`. */
export function contributeSiteBackupTools(): ToolContributor {
  return { domain: DOMAIN, build: buildSiteBackupRegistrations, risk: siteBackupDerivedRisk };
}

/** Local creation permissions precede all download, upload consumption and registry effects. */
async function handleImport(required: { deps: SiteBackupToolDeps; ctx: ToolExecutionContext; list: boolean }, _options: Record<string, never> = {}): Promise<unknown> {
  const { deps, ctx, list } = required;
  await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: list ? "system.read" : "system.write" }, { entityType: "site-registry" });
  if (!deps.siteImportBackend) return { ok: false, code: "UNAVAILABLE", message: "Import requires local site creation and a configured sites home." };
  try {
    const input = requireInputRecord({ input: ctx.input });
    if (list) {
      if (Object.keys(input).length) throw new SiteShareRefusal({ code: "INVALID_INPUT", message: "site_import_list takes no fields." });
      return { imports: await deps.siteImportBackend.list({ principalId: ctx.principal.id }) };
    }
    return await deps.siteImportBackend.importBackup({ ...parseSiteImportInput({ input }), principalId: ctx.principal.id }, { signal: ctx.signal });
  } catch (error) {
    if (error instanceof SiteShareRefusal) return { ok: false, code: error.code, message: error.message };
    throw error;
  }
}

import { toolMetadata } from '../../contracts/core/tool-metadata/site-evidence.js';
import { buildDomainRegistrations, indexCatalogById, requireInputRecord, type AgentToolSideEffect, type DerivedRiskByToolId, type ToolHandler, type ToolRegistration } from "@jini-ai/core";
import { adaptLegacyAuthorize, requireToolPermission } from "@jini-ai/cms/core";
// `ToolInputError` specifically — see `features/post/tool-registrations.ts`'s identical import for
// why: the marker `@jini-ai/daemon`'s `ToolExecutor` reads to classify a rejection 400 rather than
// redacting it into a message-stripped 500.
import { ToolInputError } from "@jini-ai/core";

import type { HttpClientPort } from "#src/platform/http/index";
import type { ToolContributor } from "#src/assistant/index";

import type { AuthorizeFn } from "../../contracts/core/commands/index.js";
import { OriginNotVerifiedError, type OriginRegistryPort } from "@jini-ai/http-kit/verified-origin";
import { siteEvidenceAgentToolCatalog, SITE_EVIDENCE_TOOL_ID } from "./agent-tools.js";
import { SITE_EVIDENCE_LIMITS, type SiteEvidenceBrowserFactory } from "@jini-ai/diagnostics/web-evidence";
// Browser/privacy rationale: Jini/packages/diagnostics/src/web-evidence/browser-port.ts; serialized DOM rationale: page-structure-script.ts beside it.
import { collectPageEvidence } from "./collect-page-evidence.js";
import { playwrightModuleLoader } from "#src/platform/headless-browser/playwright-loader";
import { openPlaywrightSiteEvidenceBrowser, createRequestRouter, fetchOwnSiteResource, PUBLIC_RENDER_LAUNCH_OPTIONS } from "@jini-ai/diagnostics/web-evidence/playwright";

/**
 * @file Wires `site_collect_page_evidence` into the assistant's tool catalog, through the same
 * `buildDomainRegistrations` gate and the same `registerToolContributor` seam every other
 * first-party domain uses.
 *
 * **Authorization.** `content.read`, checked inline. The tool reads this workspace's own published
 * pages, which is exactly what that permission already governs for `content_post_list`/`pages_read_html`
 * — a principal who may read the site's content may read the site's rendered content. Stated plainly
 * rather than implied: this tool ALSO returns response headers and attempted-request hosts, which is
 * slightly wider than page bodies. That is a deliberate call, not an oversight — those facts are
 * observable by anyone who can open the site in a browser, so gating them behind an operator-level
 * permission would restrict something the public can already see while leaving the page body (the
 * genuinely privileged part on an unpublished draft) at `content.read` anyway.
 *
 * **Why the browser factory is optional in the deps.** `RouteDeps` has no browser field and should
 * not grow one: a headless browser is not a route dependency, it is an on-demand subprocess this one
 * tool launches per call and closes in a `finally`. Defaulting to
 * {@link openPlaywrightSiteEvidenceBrowser} keeps `SiteEvidenceToolDeps` structurally satisfied by
 * the existing `RouteDeps` with no composition-root change, while the optional field is the seam a
 * test substitutes a fake through. No browser is launched at registration time — only inside a
 * handler call.
 *
 * The browser seam for `site_collect_page_evidence`, plus the evidence shapes that cross it,
 * now owned by Jini diagnostics.
 *
 * ---------------------------------------------------------------------------
 * Why a port at all
 * ---------------------------------------------------------------------------
 * A headless browser is a heavyweight, optional, environment-dependent runtime dependency. Three
 * things follow, and the port is what makes all three cheap:
 *
 * 1. **It may be absent.** Tovu is self-hosted; an operator's image may not carry Chromium at all.
 *    `SiteEvidenceBrowserFactory` therefore returns a discriminated result rather than throwing, so
 *    "this deployment cannot observe rendered behaviour" is a first-class, reportable state instead
 *    of a stack trace. The skill's output contract requires it to say `cannot-determine` in exactly
 *    this case, which it can only do if the tool tells it plainly.
 * 2. **It must be testable without one.** Every bound, every same-origin refusal, every redaction
 *    rule in `collect-page-evidence.ts` is exercised against a fake implementing this interface.
 *    Nothing about those rules should require downloading a browser to assert.
 * 3. **Playwright is not the contract.** Jini's `playwright-browser.ts` is one adapter. This Tovu host wiring supplies the optional
 *    module loader, so swapping vendors does not change the collector or evidence contract.
 *
 * ---------------------------------------------------------------------------
 * What this port is NOT allowed to carry
 * ---------------------------------------------------------------------------
 * The evidence types below are the whole contract, and they are deliberately incapable of carrying
 * personal data out of a page:
 *
 * - A cookie's **value is not a field**. Names, domains, flags and the observation phase are; the
 *   value is not modelled, so an adapter has nothing to put it in and a report has nothing to leak.
 * - A request's **body is not a field**, and neither are its headers. Method, host, path, resource
 *   type, phase.
 * - A form control's **value is not a field**. Its selector, name, type, and whether it has an
 *   accessible label are.
 * - Page text is a bounded **excerpt**, capped by the collector, never the full document.
 *
 * This is the same "unrepresentability, not redaction" discipline `same-origin.ts` applies to the
 * URL: a field that does not exist cannot be forgotten in a redaction pass.
 */

const siteEvidenceDerivedRisk: DerivedRiskByToolId = new Map<string, AgentToolSideEffect>([
  // -> collectPageEvidence(): one origin lookup + up to 5 GET page loads. Writes nothing, anywhere.
  [SITE_EVIDENCE_TOOL_ID, "none"],
]);

const CATALOG_BY_ID = indexCatalogById({ catalog: siteEvidenceAgentToolCatalog });

// `--no-sandbox` is required to launch Chromium as a non-root user inside a container without
// granting SYS_ADMIN. Acceptable here and only here: this browser opens exactly one origin —
// the operator's own site — never arbitrary attacker-chosen URLs, so the sandbox is not the
// boundary doing the security work; Jini's web-evidence/same-origin.ts is.
const TOVU_BROWSER_LAUNCH_OPTIONS = {
  headless: true,
  args: [...PUBLIC_RENDER_LAUNCH_OPTIONS.args, "--no-sandbox"],
};

export interface SiteEvidenceToolDeps {
  workspaceId: string;
  authorize: AuthorizeFn;
  originRegistry: OriginRegistryPort;
  /** Test seam. Absent in production, where {@link openPlaywrightSiteEvidenceBrowser} is used. */
  siteEvidenceBrowser?: SiteEvidenceBrowserFactory;
}

/**
 * Reads and validates the tool's `paths` argument.
 *
 * Kept separate from the handler so the argument rules are directly assertable without a browser,
 * an origin registry, or a principal. Rejects a non-array or an array containing a non-string
 * outright — those are caller bugs a model can fix on its next turn, and reporting them as
 * per-path `skipped` entries would bury the shape error inside a result that otherwise looks like a
 * successful run.
 *
 * @throws {ToolInputError} If `paths` is missing, not an array, empty, or contains a non-string.
 * @complexity O(n) in the array's length.
 */
export function readPathsArgument(input: Readonly<Record<string, unknown>>): readonly string[] {
  const raw = input.paths;
  if (!Array.isArray(raw)) {
    throw new ToolInputError({ message: "'paths' is required and must be an array of site-relative path strings, e.g. ['/', '/legal/privacy']" });
  }
  if (raw.length === 0) {
    throw new ToolInputError({ message: "'paths' must contain at least one site-relative path" });
  }
  const paths: string[] = [];
  for (const [index, value] of raw.entries()) {
    if (typeof value !== "string") {
      throw new ToolInputError({ message: `'paths[${index}]' must be a string, got ${typeof value}` });
    }
    paths.push(value);
  }
  return paths;
}

/** Reads one optional evidence capture flag without coercing caller input. */
function readOptionalEvidenceFlag(
  { input, name }: { input: Readonly<Record<string, unknown>>; name: "collectAccessibility" | "collectPerformance" },
  _options: Record<string, never> = {},
): boolean | undefined {
  const value = input[name];
  if (value !== undefined && typeof value !== "boolean") {
    throw new ToolInputError({ message: `'${name}' must be a boolean when provided` });
  }
  return value;
}

/**
 * Reads optional consent, accessibility and on-demand performance arguments.
 *
 * @throws {ToolInputError} If either is present with the wrong type.
 * @complexity O(1).
 */
export function readOptionalEvidenceArguments(input: Readonly<Record<string, unknown>>, _options: Record<string, never> = {}): {
  readonly consentAcceptSelector?: string;
  readonly collectAccessibility?: boolean;
  readonly collectPerformance?: boolean;
} {
  const selector = input.consentAcceptSelector;
  if (selector !== undefined && typeof selector !== "string") {
    throw new ToolInputError({ message: "'consentAcceptSelector' must be a CSS selector string when provided" });
  }
  const collectAccessibility = readOptionalEvidenceFlag({ input, name: "collectAccessibility" });
  const collectPerformance = readOptionalEvidenceFlag({ input, name: "collectPerformance" });
  return {
    ...(typeof collectPerformance === "boolean" ? { collectPerformance } : {}),
    ...(typeof selector === "string" && selector.trim().length > 0 ? { consentAcceptSelector: selector.trim() } : {}),
    ...(typeof collectAccessibility === "boolean" ? { collectAccessibility } : {}),
  };
}

export function buildSiteEvidenceRegistrations(routeDeps: SiteEvidenceToolDeps, { httpClient }: { httpClient?: HttpClientPort } = {}): ToolRegistration[] {
  const handlers: Record<string, ToolHandler> = {
    [SITE_EVIDENCE_TOOL_ID]: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "content.read" }, { entityType: "post" });

      const paths = readPathsArgument(input);
      const optional = readOptionalEvidenceArguments(input);

      try {
        return await collectPageEvidence(
          {
            workspaceId: routeDeps.workspaceId,
            originRegistry: routeDeps.originRegistry,
            openBrowser: routeDeps.siteEvidenceBrowser ?? (required => openPlaywrightSiteEvidenceBrowser(required, {
              moduleLoader: playwrightModuleLoader,
              launchOptions: httpClient ? TOVU_BROWSER_LAUNCH_OPTIONS : { headless: true, args: ["--no-sandbox", "--disable-dev-shm-usage"] },
              ...(httpClient ? { routerFactory: ({ originBaseUrl, signal }) => createRequestRouter({
                httpClient: { send: ({ request }) => httpClient.send(request) }, ownSiteFetch: fetchOwnSiteResource,
                allowedOrigins: [new URL(originBaseUrl).origin], signal,
              }, { preserveOwnSiteCookies: true }) } : {}),
            })),
            paths,
          },
          optional,
        );
      } catch (error) {
        if (error instanceof OriginNotVerifiedError) {
          // Returned as model-facing data rather than thrown: this is an operator configuration gap
          // the model can report and route around, not a bug. Guessing an origin from a request
          // host is what ADR-040 F2 exists to forbid, so there is no fallback to offer — only an
          // accurate explanation of why nothing could be observed.
          return {
            collected: false,
            reason:
              "This workspace has no verified canonical origin registered, so there is no site origin to " +
              "load pages from. Rendered-page evidence cannot be collected here. Report this as " +
              "'cannot-determine' and ask the operator to register the site's public origin.",
            limits: SITE_EVIDENCE_LIMITS,
          };
        }
        throw error;
      }
    },
  };

  return buildDomainRegistrations({ metadata: toolMetadata,
    domain: "site-evidence",
    catalogModule: "features/site-evidence/agent-tools.ts",
    catalog: CATALOG_BY_ID,
    handlers,
    derivedRisk: siteEvidenceDerivedRisk,
  });
}

export { siteEvidenceDerivedRisk };

/**
 * Contributes the site-evidence tool to the assistant's catalog — called once by
 * `server/tool-catalog-manifest.ts`'s `installFirstPartyToolContributors()`.
 */
export function contributeSiteEvidenceTools({ httpClient }: { httpClient?: HttpClientPort } = {}, _optional = {}): ToolContributor {
  return { domain: "site-evidence", build: deps => buildSiteEvidenceRegistrations(deps, httpClient ? { httpClient } : {}), risk: siteEvidenceDerivedRisk };
}

import { exportUrlLocations } from "@jini-ai/devops/static-export";
import type { MediaRepoPort } from "@jini-ai/cms/media";
import type { OriginRegistryPort } from "@jini-ai/http-kit/verified-origin";
import { findMediaByIdOrSlug } from "@jini-ai/cms/media";
import { mediaPublicPath } from "../media/public-path.js";
import { resolveContentTypes, type ContentTypeDeps } from "../media/content-type-resolution.js";

export interface ExportMediaUrlDeps extends ContentTypeDeps {
  mediaRepo: MediaRepoPort;
  originRegistry: OriginRegistryPort;
}

// Match complete local media paths in HTML, CSS, XML and JSON, retaining query/fragment tails.
// Check absolute URLs against the configured origin: another site's /m/ namespace is not ours.
const ORIGINAL_URL = /(?<![\w/.:%-])((?:https?:)?\/\/[^/\s"'<>\\()]+)?\/m\/([^/\s"'<>\\()?#]+)\/original(?=[\s"'<>\\()?#,;]|$)/g;

/** Same origin as the configured site; an unparsable URL is never ours. */
function sameOrigin({ url, origin }: { url: string; origin: string }): boolean {
  try { return new URL(url, origin).origin === origin; } catch { return false; }
}

/** Local paths need no origin lookup; absolute references must belong to the configured site.
 * With no verified origin, absolute references stay as written: a link must never fail the export. */
async function localOriginalPaths({ body, deps, locations }: { body: string; deps: ExportMediaUrlDeps; locations: readonly { start: number; end: number }[] }, _optional = {}): Promise<Map<string, { prefix: string; key: string }>> {
  const matches = locations.flatMap(({ start, end }) => [...body.slice(start, end).matchAll(ORIGINAL_URL)]);
  const paths = new Map<string, { prefix: string; key: string }>();
  let origin: string | null | undefined;
  for (const match of matches) {
    if (match[1]) {
      origin ??= await deps.originRegistry.canonicalOrigin({ workspaceId: deps.workspaceId })
        .then(configured => `${configured.scheme}://${configured.host}`, () => null);
      if (!origin || !sameOrigin({ url: match[0], origin })) continue;
    }
    let key: string;
    try { key = decodeURIComponent(match[2]!); } catch { continue; } // Malformed escapes are not media keys.
    // Absolute URLs stay absolute (sitemaps and og:image require them); only the path is upgraded.
    paths.set(match[0], { prefix: match[1] ?? "", key });
  }
  return paths;
}

/** Upgrade stored URLs using the same lookup and read-path type backfill as the media library.
 * O(text length + URL positions log URL positions + distinct media keys) work, one batched type lookup; legacy bytes read only
 * when their type was never recorded. Missing/private documents retain their existing URLs.
 */
export async function rewriteMediaOriginalUrls(
  { body, deps }: { body: string; deps: ExportMediaUrlDeps }, { contentType = "text/html" }: { contentType?: string } = {},
): Promise<string> {
  // Parsed once: the same URL positions are scanned for keys and then rewritten.
  const locations = exportUrlLocations({ body, contentType });
  const paths = await localOriginalPaths({ body, deps, locations });
  if (paths.size === 0) return body;
  const records = await exportableMediaRecords({ paths, deps });
  const contentTypes = await resolveContentTypes(deps, [...records.values()]);
  const replacements = new Map<string, string>();
  for (const [url, record] of records) {
    const type = contentTypes.get(record.source.sha256);
    const { prefix, key } = paths.get(url)!;
    if (type) replacements.set(url, prefix + mediaPublicPath(key, { kind: "original", contentType: type }));
  }
  const output: string[] = [];
  let offset = 0;
  for (const { start, end } of locations) {
    const value = body.slice(start, end).replace(ORIGINAL_URL, url => replacements.get(url) ?? url);
    output.push(body.slice(offset, start), value);
    offset = end;
  }
  output.push(body.slice(offset));
  return output.join('');
}

/** Missing, inactive and document records keep their original URL; lookups remain sequential. */
async function exportableMediaRecords({ paths, deps }: { paths: ReadonlyMap<string, { key: string }>; deps: ExportMediaUrlDeps }, _options = {}) {
  const records = new Map<string, NonNullable<Awaited<ReturnType<typeof findMediaByIdOrSlug>>>>();
  for (const [url, { key }] of paths) {
    const record = await findMediaByIdOrSlug({ deps, input: { workspaceId: deps.workspaceId, idOrSlug: key } });
    if (record && record.status === "active" && record.kind !== "document") records.set(url, record);
  }
  return records;
}

/** Rewrite textual responses before the existing exporter writes AND crawls them. Binary responses
 * stay streaming and untouched. Response headers remain authoritative except for the byte length,
 * which must be recalculated after a text rewrite. No extra HTTP requests or renderer are used.
 */
export async function rewriteExportMediaResponse(
  { response, deps }: { response: Response; deps: ExportMediaUrlDeps }, _options = {},
): Promise<Response> {
  if (response.body === null) return response;
  if (!/^(?:text\/(?:html|css)|application\/(?:[\w.+-]*\+)?(?:json|xml))\b/i.test(response.headers.get("content-type") ?? "")) return response;
  const body = await rewriteMediaOriginalUrls({ body: await response.text(), deps }, { contentType: response.headers.get("content-type") ?? "" });
  const headers = new Headers(response.headers);
  headers.delete("content-length");
  headers.delete("content-encoding");
  return new Response(body, { status: response.status, statusText: response.statusText, headers });
}

import { randomUUID } from "node:crypto";

import type { UUID } from "@jini-ai/core/primitives";

import type { PostRecord, PostRepoPort } from "#src/features/post/index";
import { NO_THEME_ID, resolveActiveTheme, isStandaloneThemePage } from "#src/features/theme/index";
import { postPublicPath } from "#src/platform/routing/adapter";
import type { DiscoveredTheme } from "#src/features/theme/index";
import type { PresentationSettingsRepoPort } from "#src/features/presentation/index";
import type { RedirectRecord, RedirectRepoPort } from "@jini-ai/cms/redirects";
import type { ManifestRoute, ManifestSkip, RouteManifest } from "./ports.js";

/**
 * @file The public-site route enumerator, shared by the exporter and theme previews.
 *
 * Reuses the SAME selection logic the real public routes render with — rather than re-deriving
 * "which theme is active" or "which products are live" a second time, so a manifest built from
 * independent logic could never silently drift from what the routes it is describing actually do.
 *
 * Every one of `resolveActiveThemeId`/`listPublishedPosts`/`resolveStorefrontProducts` is reached
 * through `RouteManifestDeps` injection (`deps.resolveActiveThemeId()`/`deps.listPublishedPosts()`/
 * `deps.resolveStorefrontProducts()` below), not a direct import, and all three are bound to the
 * real implementation at the composition root (`server/runtime/composition/app.ts`/`deps.ts`) —
 * mirroring `runExportSite`/`createSiteApp`'s existing precedent on the same `RouteDeps` type. This
 * file lives under `platform/` (Tier-2, foundation-layer), while `resolveActiveThemeId` and
 * `listPublishedPosts` are owned by `features/presentation` and `features/post` respectively;
 * calling either directly from here would make `platform` reach back up into a feature that itself
 * depends on `platform` (via `platform/db`, `platform/routing`), closing a runtime module cycle
 * (`check:architecture` flagged `features/post <-> platform` and `features/presentation <->
 * platform`, SCC 0 -> 3). `resolveStorefrontProducts` was already injected for an unrelated reason
 * (its return type is deliberately off-limits to `features/commerce`, see `storefront.ts`'s own
 * file header) — the other two now take the identical shape for the module-boundary reason above,
 * per the established Option-A structural-injection technique (see
 * `ADS-memory/reports/architecture/2026-08-17-post-listpublishedposts-design-options.md` for the
 * same technique applied to a different `features/post` cycle).
 * `resolveActiveTheme`/`isStandaloneThemePage` stay as direct imports from `#src/features/theme/index`.
 * That edge is why this library moved out of `platform/export/` into `features/site-export/`
 * (2026-09-26): once `features/theme` reached `platform` at runtime (through its publish-content
 * adapters), `platform -> features/theme` closed a module cycle. The header text above describes
 * the pre-move layering; the two injected deps stay injected.
 *
 * The one non-obvious piece of domain knowledge this file owns: a static theme's `pages/*.html`
 * folder (`DiscoveredTheme.pages`, `features/theme/theme.ts`) holds BOTH real standalone pages
 * (`about.html`, `pricing.html`, …) and content-embedding template shells a Post/Page picks via
 * `templateChoice` (`page-shell.html`, `blog-post.html`, …, declared in `theme.manifest.templates`).
 * Both live in the identical `Record<string, string>`, keyed the identical way (filename minus
 * `.html`) — nothing in the loaded theme shape distinguishes them by TYPE, only by which OTHER list
 * names them. Enumerating `theme.pages` without excluding `theme.manifest.templates` would offer a
 * template shell as if it were its own page route — it IS technically reachable at that URL today
 * (`pages.ts`'s `theme.pages[slug]` check has no such exclusion), but exporting it produces a
 * broken/incomplete document (a shell meant to have a Post's content substituted in, rendered with
 * none), not a second copy of a real page. Excluded here for that reason.
 */

/**
 * The minimal structural slice {@link buildRouteManifest} actually reads, declared locally rather
 * than importing `server/routes/types.ts`'s `RouteDeps` (2026-08-20 RouteDeps-narrowing fix,
 * mirroring `features/theme/active-theme.ts`'s own `ActiveThemeResolutionDeps` — see that file's own
 * header for why a type-only import of the god type still counts as a real graph edge under
 * `check:architecture`'s `--ts-pre-compilation-deps` resolution, not just a runtime one).
 *
 * `resolveActiveThemeId` (`#src/features/presentation/index`) and `resolveActiveTheme`
 * (`#src/features/theme/index`) each only need their own narrow
 * `ActiveThemeIdResolutionDeps`/`ActiveThemeResolutionDeps` — this interface is a structural
 * superset of both (the same `presentationRepo`/`workspaceId`/`themes` fields, same types), so
 * passing `deps` through to either call works with no cast, exactly as it did against the real
 * `RouteDeps` object before this change.
 *
 * `resolveStorefrontProducts` is now NULLARY (`() => Promise<RouteManifestProduct[]>`), not
 * `(routeDeps: RouteDeps) => ...` — the matching 2026-08-20 field-contract change on `RouteDeps`
 * itself (see that field's own doc in `server/routes/types.ts`) that is what lets this file drop
 * `RouteDeps` entirely: the real implementation (`server/routes/site/products.ts`) is now bound to
 * its own `routeDeps` ONCE, at composition-root construction time, the same way
 * `RouteDeps.exportSiteBound` already binds `exportSite` itself. See {@link RouteManifestProduct}'s
 * own doc for why its return type is a local minimal shape rather than an import of the real
 * `SiteProduct`.
 *
 * A real `RouteDeps` object (what `createApp`/`serve.ts` already build) always satisfies this
 * trivially; only a test needs to assemble one, and every route test in this repo already does via
 * `createRouteDeps()`.
 */
export interface RouteManifestDeps {
  readonly workspaceId: UUID;
  readonly postRepo: PostRepoPort;
  readonly presentationRepo: PresentationSettingsRepoPort;
  readonly themes: DiscoveredTheme[];
  readonly redirectRepo: RedirectRepoPort;
  /** The same `resolveActiveThemeId` (`features/presentation/active-theme-id.ts`) the live routes
   *  resolve the active theme with, injected rather than imported directly — see file header. */
  readonly resolveActiveThemeId: () => Promise<string>;
  /** The same `listPublishedPosts` (`features/post/post.ts`) the live routes render posts/pages
   *  with, injected rather than imported directly — see file header. */
  readonly listPublishedPosts: () => Promise<{ posts: PostRecord[] }>;
  readonly resolveStorefrontProducts: () => Promise<RouteManifestProduct[]>;
}

/**
 * The exact 2 fields {@link buildRouteManifest} reads off each resolved storefront product — a
 * minimal structural slice of the real `SiteProduct` (`server/http/site/render.ts`), not an import
 * of it: importing `SiteProduct` here would relocate this file's `RouteDeps` back-edge rather than
 * remove it (`SiteProduct` itself lives under `src/server/**`, same as `RouteDeps`). Return-type
 * covariance means the real `resolveStorefrontProducts` (which returns full `SiteProduct[]`, a
 * strict superset of these 3 fields) satisfies {@link RouteManifestDeps}'s narrower field with no
 * cast anywhere — every `SiteProduct` already has `id`, `slug`, and `title`.
 */
export interface RouteManifestProduct {
  readonly id: string;
  /** Readable-slugs S7 (2026-09-23): the exported route uses this, not `id` — see
   *  `buildProductRoutes` below. */
  readonly slug: string;
  readonly title: string;
}

/** Base slug for the synthetic 404-probe route (`ports.ts`'s `ManifestRoute.kind: "not-found"`
 *  doc) — a real-looking, `[a-z0-9-]+`-shaped slug chosen specifically to miss every real post,
 *  page, and theme page, so requesting it exercises the SAME "nothing matched" branch a genuinely
 *  broken visitor link would. */
const NOT_FOUND_PROBE_BASE = "tovu-export-404-check";

/**
 * Picks a request path guaranteed not to collide with any route already in the manifest, so the
 * 404 probe (below) cannot accidentally hit real content. Collision is vanishingly unlikely for the
 * base slug alone (a genuine post/page would need that exact, deliberately-unusual title-shaped
 * slug), but a random suffix costs nothing and turns "vanishingly unlikely" into "cannot happen"
 * without the caller needing to reason about the odds.
 *
 * @complexity O(n) in the number of already-claimed paths for the (typical) zero-collision case;
 *   each retry is another O(n) membership check against the same fixed set, bounded in practice by
 *   collision probability rather than by any loop guard — a `Set` lookup is O(1) amortized, so this
 *   is not a hot path even for a large route count.
 */
function chooseNotFoundProbePath(claimedPaths: ReadonlySet<string>): string {
  let candidate = `/${NOT_FOUND_PROBE_BASE}`;
  while (claimedPaths.has(candidate)) {
    candidate = `/${NOT_FOUND_PROBE_BASE}-${randomUUID().slice(0, 8)}`;
  }
  return candidate;
}

/**
 * Builds the full {@link RouteManifest} for one workspace: home, the two always-registered
 * convention routes (`/robots.txt`, `/sitemap.xml`), every published post/page, every theme-owned
 * static marketing page not shadowed by a post, the product grid + each product detail page (when
 * any product exists), every statically-enumerable (`exact`-match, `active`) redirect rule, and a
 * collision-checked 404 probe. `prefix`/`wildcard`/`regex` redirect rules — and the fact that Tovu
 * has no favicon/manifest route to enumerate at all — are recorded in `skipped` rather than
 * silently dropped: the redirect rules match a FAMILY of paths, not one enumerable path, so no
 * finite manifest entry can represent them; favicon/manifest are convention-addressed paths with no
 * backing route to find in the first place.
 *
 * Also resolves and returns `activeTheme` (id + on-disk `dir`) when a theme was found — the one
 * piece of theme-resolution state a caller outside this function needs (the exporter's
 * unreferenced-theme-file diff) without re-resolving "which theme is active" a third time.
 *
 * Never throws for "no theme installed" — that is itself a real, reportable state (an export with
 * only `/`, the two convention routes, and a 404 probe, and a `skipped` entry explaining why), not
 * a crash; every other error (a repo failure, for instance) propagates uncaught, same as the live
 * routes it mirrors.
 *
 * @complexity O(P + T + R) — P published posts, T theme pages, R redirect rules — one pass over
 *   each, no nested iteration. Products add O(K) for K storefront products. All four sources are
 *   already loaded in full by their own repos (no pagination exists yet anywhere in this codebase),
 *   so this makes no additional query-shape assumption beyond what those repos already commit to.
 */
/**
 * Enumerates a static theme's own pages as routes, skipping `index`/`404` (handled elsewhere) and
 * template shells (see file header), and skipping any page whose slug a post has claimed (per the
 * same `overridesThemePage` tri-state the live resolver uses). Non-static themes contribute none.
 */
function buildThemePageRoutes(
  theme: DiscoveredTheme,
  postBySlug: ReadonlyMap<string, PostRecord>
): { routes: ManifestRoute[]; shadowedSlugs: ReadonlySet<string> } {
  const routes: ManifestRoute[] = [];
  const shadowedSlugs = new Set<string>();
  if (theme.manifest.tier !== "static") return { routes, shadowedSlugs };

  for (const pageId of Object.keys(theme.pages)) {
    // `index`/`404`/template-shell exclusion, shared with the live `GET /:slug` resolver rather
    // than respelled here — see `isStandaloneThemePage`'s own doc (`features/theme/theme.ts`).
    if (!isStandaloneThemePage(theme, pageId)) continue;

    const collidingPost = postBySlug.get(pageId);
    if (collidingPost && collidingPost.overridesThemePage !== false) continue; // the post loop adds it instead.

    routes.push({ path: `/${pageId}`, kind: "theme-page", label: pageId });
    shadowedSlugs.add(pageId);
  }
  return { routes, shadowedSlugs };
}

/** Every published post/page not shadowed by a theme-owned static page at the same slug. */
function buildPostRoutes(posts: readonly PostRecord[], shadowedSlugs: ReadonlySet<string>): ManifestRoute[] {
  const routes: ManifestRoute[] = [];
  for (const post of posts) {
    if (shadowedSlugs.has(post.slug)) continue;
    routes.push({ path: postPublicPath({ slug: post.slug }), kind: post.kind === "page" ? "page" : "post", label: post.title });
  }
  return routes;
}

/**
 * Resolves theme + post routes together (the post loop needs the theme's shadowed-slug set). When
 * there is no theme to render with, records the `no-theme` skip and returns no routes/`activeTheme`
 * — a real, reportable state rather than a crash (see file header).
 *
 * TWO states share that skip `reason`, with deliberately different `detail` text. `undefined` means
 * discovery found no valid theme: something is broken and the operator should reinstall one.
 * `"deliberate"` means the operator turned the theme off themselves — nothing is broken and there
 * is nothing to fix, so telling them "no valid theme discovered" would be simply false. The
 * `reason` is kept identical so every existing consumer of the skip list is unaffected; only the
 * human-readable sentence distinguishes them.
 */
function resolveThemeAndPostRoutes(
  theme: DiscoveredTheme | undefined | "deliberate",
  posts: readonly PostRecord[],
  skipped: ManifestSkip[]
): { activeTheme?: RouteManifest["activeTheme"]; routes: ManifestRoute[] } {
  if (theme === undefined || theme === "deliberate") {
    skipped.push({
      reason: "no-theme",
      detail:
        theme === "deliberate"
          ? "this site has its theme turned off deliberately — only '/' and the 404 probe could be enumerated; reactivating a theme restores every theme-owned route"
          : "no valid theme discovered for this workspace — only '/' and the 404 probe could be enumerated",
    });
    return { routes: [] };
  }

  const activeTheme: RouteManifest["activeTheme"] = { id: theme.manifest.id, dir: theme.dir, apiVersion: theme.manifest.apiVersion };
  const postBySlug = new Map<string, PostRecord>(posts.map((post) => [post.slug, post]));
  const { routes: themeRoutes, shadowedSlugs } = buildThemePageRoutes(theme, postBySlug);
  return { activeTheme, routes: [...themeRoutes, ...buildPostRoutes(posts, shadowedSlugs)] };
}

/** The product grid + one detail route per storefront product — omitted entirely when there are none. */
function buildProductRoutes(products: readonly RouteManifestProduct[]): ManifestRoute[] {
  if (products.length === 0) return [];
  const routes: ManifestRoute[] = [{ path: "/products", kind: "product-list", label: "products" }];
  for (const product of products) {
    routes.push({ path: `/products/${product.slug}`, kind: "product", label: product.title });
  }
  return routes;
}

/** `exact` redirect rules become routes; every other match type is recorded in `skipped` (see file header). */
function buildRedirectRoutes(redirectRules: readonly RedirectRecord[], skipped: ManifestSkip[]): ManifestRoute[] {
  const routes: ManifestRoute[] = [];
  for (const rule of redirectRules) {
    if (rule.matchType !== "exact") {
      skipped.push({
        reason: "non-exact-redirect",
        detail: `${rule.matchType} rule '${rule.fromPattern}' -> '${rule.toTarget}' matches a family of paths, not one enumerable path`,
      });
      continue;
    }
    routes.push({
      path: rule.fromPattern,
      kind: "redirect",
      label: rule.fromPattern,
      redirectTarget: rule.toTarget,
      redirectStatusCode: rule.statusCode,
    });
  }
  return routes;
}

export async function buildRouteManifest(deps: RouteManifestDeps): Promise<RouteManifest> {
  const routes: ManifestRoute[] = [
    { path: "/", kind: "home", label: "home" },
    // Convention-addressed files: nothing in any rendered page LINKS to these — browsers and
    // crawlers request them by name — so a crawl-based asset discovery pass (site-exporter.ts)
    // structurally cannot find them. All three are always-registered routes regardless of settings
    // (`registerSeoRobotsRoute`/`registerSeoSitemapRoute`/`registerLlmsTxtRoute`, mounted
    // unconditionally by `modules/seo.ts`; `sitemapEnabled` only gates whether `robots.txt`
    // ADVERTISES the sitemap URL, not whether `/sitemap.xml` itself responds), so — unlike
    // favicon/manifest below — they belong in the manifest proper rather than in `skipped`.
    { path: "/robots.txt", kind: "well-known", label: "robots.txt" },
    { path: "/sitemap.xml", kind: "well-known", label: "sitemap.xml" },
    { path: "/llms.txt", kind: "well-known", label: "llms.txt" },
    // RSS (`registerFeedRoute`, also mounted unconditionally by `modules/seo.ts`). Feed readers find
    // it through the `<link rel="alternate">` in every page head, but request it by name.
    { path: "/feed.xml", kind: "well-known", label: "feed.xml" },
  ];
  const skipped: ManifestSkip[] = [
    // Also convention-addressed and also invisible to a crawl — but unlike robots.txt/sitemap.xml,
    // Tovu registers no `/favicon.ico` or web-app-manifest route at all today (grep-confirmed
    // against `server/app.ts`/`server/routes/site/*`), so there is nothing here to enumerate, not a
    // route this manifest failed to find. Recorded so the export report names the gap rather than
    // looking complete — the fix, if wanted, is a product-level route, not an exporter change.
    {
      reason: "no-favicon-or-manifest-route",
      detail: "Tovu has no /favicon.ico or web-app-manifest route today — nothing to export for either convention",
    },
  ];

  const [activeThemeId, { posts }] = await Promise.all([deps.resolveActiveThemeId(), deps.listPublishedPosts()]);

  const theme = resolveActiveTheme(deps, activeThemeId);
  // Slugs claimed by a theme-owned static page THIS pass are tracked inside `resolveThemeAndPostRoutes`
  // so the post loop can skip a post shadowed at its own slug (pages.ts:765-786: tri-state
  // `overridesThemePage` — post wins unless the stored value is explicitly `false`; see that
  // resolver's own doc for the full contract). Mirrored here rather than shared code so the exported
  // manifest matches exactly what the live site would serve for the same row.
  // `resolveActiveTheme` returns `null` for "nothing installed"; this helper's parameter is optional
  // (`| undefined`). Both mean the same absent-theme case, so normalize rather than widening the
  // helper's signature to accept two spellings of nothing. `NO_THEME_ID` is NOT normalized with
  // them — it is a third state that reports differently (see the helper's own doc).
  const { activeTheme, routes: themeAndPostRoutes } = resolveThemeAndPostRoutes(
    theme === NO_THEME_ID ? "deliberate" : (theme ?? undefined),
    posts,
    skipped
  );
  // Content-owned homepage (SPEC-0XX): a `kind: "page"` row may claim the reserved "/" slug and
  // `buildPostRoutes` above already resolves its path through the same `postPublicPath` the live
  // `GET /` handler uses, so it can appear in `themeAndPostRoutes` at path "/" too. The seeded
  // `{ path: "/", kind: "home" }` entry above is what the live site serves ONLY when no such page
  // exists — replace it with the real page's route instead of pushing a second, duplicate "/" entry,
  // the same "post wins over what the manifest would otherwise show at this path" shape
  // `buildThemePageRoutes`'s own `shadowedSlugs` already applies for a theme-owned static page.
  const homePageRouteIndex = themeAndPostRoutes.findIndex((route) => route.path === "/");
  if (homePageRouteIndex !== -1) {
    const [homePageRoute] = themeAndPostRoutes.splice(homePageRouteIndex, 1);
    if (homePageRoute) routes[0] = homePageRoute;
  }
  routes.push(...themeAndPostRoutes);

  const products = await deps.resolveStorefrontProducts();
  routes.push(...buildProductRoutes(products));

  const redirectRules = await deps.redirectRepo.list({ workspaceId: deps.workspaceId, status: "active" });
  routes.push(...buildRedirectRoutes(redirectRules, skipped));

  const claimedPaths = new Set(routes.map((route) => route.path));
  routes.push({ path: chooseNotFoundProbePath(claimedPaths), kind: "not-found", label: "404" });

  return { routes, skipped, activeTheme };
}

import { resolveActiveThemeId } from "#src/features/presentation/active-theme-id";
import type { PresentationSettingsRepoPort } from "@jini-ai/cms/presentation";
import type { RequestListener } from "node:http";
import type { AuthorizeFn } from "@jini-ai/cms/core";
import type { ObservabilityPort } from "#src/platform/observability/index";
import type { SettingsRepoPort, getEffective } from "@jini-ai/core/settings";

import type { LiveOriginSourceDeps } from "./live-url.js";
import { ADMIN_SCREENS } from "./admin-screens.generated.js";
import type { SiteCapabilitiesDeps, SiteCapabilityToolRow } from "./site-capabilities.js";
import type {
  SiteProfileContentTypeRow,
  SiteProfileDeps,
  SiteProfileJsonValue,
  SiteProfilePluginActivationRow,
  SiteProfilePluginRow,
  SiteProfilePostRow,
  SiteProfileThemeRow,
} from "./site-profile.js";

/**
 * @file The adapter between a composition root's deps bag and the narrow port bags this domain's
 * services actually take.
 *
 * This is the file that makes the secret-safety claim checkable. `buildSiteProfile` cannot reach a
 * credential store because `SiteProfileDeps` has no field that could carry one — but SOMETHING has
 * to turn the real `RouteDeps` into that shape, and this is that something. Keeping the conversion
 * in one named function (rather than inline in the tool handler and again in the HTTP route) means
 * there is exactly one place to audit, and both adapters provably feed the service the same thing.
 * `toSiteCapabilitiesDeps` does the same for `buildSiteCapabilities`.
 *
 * {@link SiteInspectionToolDeps} is declared STRUCTURALLY rather than as
 * `Pick<RouteDeps, ...>` — the same discipline `features/theme/tool-registrations.ts`'s
 * `ThemeToolDeps` and `features/plugin-runtime/tool-registrations.ts`'s `PluginsToolDeps` already
 * use, so this module carries no back-edge into the composition root for the `RouteDeps` god type.
 * `server/routes/*` satisfies it by passing its existing `RouteDeps` object; nothing there changes.
 *
 * The two exceptions to "structural, nothing imported" are `settingsRepo` and `getEffective`, which
 * are typed against `@jini-ai/core/settings`'s own exports. That is an EXTERNAL package import, not
 * an internal module edge, and it is what lets this file hand `getEffective` the exact repo it was
 * written for instead of inventing a second settings resolver — the divergence this whole design
 * exists to avoid.
 */

/**
 * The exact slice of the route-deps bag `buildSiteProfile` is fed from. Every field is a read port;
 * none of them is, or can be widened into, a credential store.
 *
 * Split out from {@link SiteInspectionToolDeps} because the admin HTTP route needs exactly this and
 * nothing more — it never fetches a published page, so requiring it to carry `createSiteApp` would
 * make its declared surface wider than what it actually uses.
 */
export interface SiteProfileSourceDeps {
  workspaceId: string;
  authorize: AuthorizeFn;
  clock: { nowIso(): string };
  postRepo: { list(required: { workspaceId: string }): Promise<readonly SiteProfilePostRow[]> };
  /** Boot-discovered themes. Read only — this domain never mutates the roster. */
  themes: readonly SiteProfileThemeRow[];
  presentationRepo: { findByWorkspaceId(required: { workspaceId: string }): Promise<{ activeThemeId: string } | null> };
  settingsRepo: SettingsRepoPort;
  /** The real `@jini-ai/core/settings` resolver, injected rather than re-implemented. */
  getEffective: typeof getEffective;
  contentTypeRepo: { listByWorkspace(params: { workspaceId: string }): Promise<readonly SiteProfileContentTypeRow[]> };
  pluginActivationRepo: { listAll(): Promise<readonly SiteProfilePluginActivationRow[]> };
  discoverPlugins: () => Promise<readonly SiteProfilePluginRow[]>;
}

/**
 * Everything the AGENT-TOOL adapter needs: the profile's read ports, plus the site's own app
 * factory that `fetch_published_page` renders through and the registry reader
 * `site_describe_capabilities` lists tools from.
 */
export interface SiteInspectionToolDeps extends SiteProfileSourceDeps, LiveOriginSourceDeps {
  /**
   * The site's own app factory (`RouteDeps.createSiteApp`), used by `fetchPublishedPage` and
   * `web_screenshot_page`'s own-site mode (which may pass a `themeId` render override). Typed as
   * Node's `RequestListener` because that is all `fetchPublishedPage` does with it — see
   * `published-page.ts`'s `FetchPublishedPageDeps` for the full note.
   */
  createSiteApp(optional?: { themeId?: string; consentAudit?: true }): RequestListener;
  /** Passed through to `fetchPublishedPage` to trace its loopback render (`RouteDeps.observability`). */
  readonly observability?: ObservabilityPort;
  /**
   * Reads the composition root's live `ToolRegistry` as catalog entries: `assistant/
   * tool-catalog-query.ts`'s `listToolCatalogEntries(registry)`, bound to the SAME registry that
   * root's `search_tools`/`describe_tool` serve. Supplied by the two roots that own a registry
   * (`server/inbound/assistant/agent-daemon-server.ts`, `assistant/byok-tool-surface.ts`), and
   * injected rather than imported because `features/**` may not import `assistant/**` by value.
   *
   * Optional because every other builder of this bag (the admin HTTP routes, tests) has no registry.
   * Without it `site_describe_capabilities` reports its tools section `unavailable`/`not-wired`,
   * never an empty catalog.
   */
  listCatalogTools?: (() => readonly SiteCapabilityToolRow[]) | undefined;
}

/**
 * Binds a composition root's deps bag down to the narrow read ports `buildSiteProfile` takes.
 *
 * Every closure below is a single read, scoped to `deps.workspaceId`. Nothing here filters,
 * redacts, or post-processes: the projections live in `site-profile.ts` where the DTO is declared,
 * so there is one place that decides what a field means and one place that decides whether it is
 * reported at all.
 *
 * @param deps - The composition root's deps bag (a real `RouteDeps` at every call site).
 * @returns The narrow port bag. Pure: constructing it performs no I/O.
 * @throws Nothing. The closures throw whatever their underlying repo throws, when invoked.
 * @complexity O(1) — closure construction only.
 * @example const profile = await buildSiteProfile(toSiteProfileDeps(routeDeps), { principalId });
 */
export function toSiteProfileDeps(deps: SiteProfileSourceDeps): SiteProfileDeps {
  return {
    workspaceId: deps.workspaceId,
    authorize: deps.authorize,
    clock: deps.clock,
    listPosts: () => deps.postRepo.list({ workspaceId: deps.workspaceId }),
    // `themes` is already-resolved boot state, not a read — wrapped in a promise so every port on
    // `SiteProfileDeps` has one shape and the service never branches on sync-vs-async.
    listThemes: async () => deps.themes,
    readActiveThemeId: async () => {
      // The resolver reads only findByWorkspaceId; its package type names the wider repo.
      // Keep this adapter's public port read-only rather than granting the profile write methods.
      return (await resolveActiveThemeId({
        workspaceId: deps.workspaceId, presentationRepo: deps.presentationRepo as PresentationSettingsRepoPort,
      })) || null;
    },
    listPlugins: () => deps.discoverPlugins(),
    listPluginActivations: () => deps.pluginActivationRepo.listAll(),
    readSetting: async ({ namespace, key }) => {
      const resolved = await deps.getEffective(
        { repo: deps.settingsRepo },
        { namespace, key, scopeContext: { workspaceId: deps.workspaceId } },
      );
      // `ResolvedSetting.value` is the settings package's own `JsonValue`. The cast restates that
      // as this module's structurally identical `SiteProfileJsonValue` rather than importing a
      // second JSON type into the DTO; it narrows nothing and hides nothing.
      return (resolved?.value ?? null) as SiteProfileJsonValue | null;
    },
    listContentTypes: () => deps.contentTypeRepo.listByWorkspace({ workspaceId: deps.workspaceId }),
  };
}

/**
 * Binds a composition root's deps bag down to the ports `buildSiteCapabilities` takes.
 *
 * `listCatalogTools` passes straight through (absent stays absent, so the service can report it).
 * `listAdminScreens` returns the generated admin screen list; `listContentTypes` is the same
 * `contentTypeRepo.listByWorkspace` read `collections_content_type_list` makes.
 *
 * @param deps - The agent-tool deps bag.
 * @returns The narrow port bag. Pure: constructing it performs no I/O.
 * @throws Nothing. The closures throw whatever their underlying reads throw, when invoked.
 * @complexity O(1) — closure construction only.
 * @example const capabilities = await buildSiteCapabilities(toSiteCapabilitiesDeps(routeDeps), { principalId });
 */
export function toSiteCapabilitiesDeps(deps: SiteInspectionToolDeps): SiteCapabilitiesDeps {
  return {
    workspaceId: deps.workspaceId,
    authorize: deps.authorize,
    clock: deps.clock,
    listCatalogTools: deps.listCatalogTools,
    listAdminScreens: () => ADMIN_SCREENS,
    listContentTypes: () => deps.contentTypeRepo.listByWorkspace({ workspaceId: deps.workspaceId }),
  };
}

import { ToolInputError } from "@jini-ai/core";
import { EgressRefusedError, type HttpClientPort, type HttpResponse } from "#src/platform/http/index";
import { OriginNotVerifiedError, type OriginRegistryPort } from "@jini-ai/http-kit/verified-origin";
import { selectConnectedDestination, type PublishContentPeerRepoPort } from "#src/features/publish-content/peers";
import type { PublishHistoryStore } from "#src/features/deployments/static-publish/index";
import { readPageBodyOptions, shapePageBody, DEFAULT_MAX_BODY_BYTES, MAX_MAX_BODY_BYTES, type PageBodyOptions } from "./page-body.js";
import { PublishedPagePathError, resolveSameOriginPath, toCookieShapes, type PublishedPageResult } from "./published-page.js";

/** Read ports only; missing ports on a test/older composition do not invent an address. */
export interface LiveOriginSourceDeps {
  workspaceId: string;
  publishContentPeerRepo?: Pick<PublishContentPeerRepoPort, "listByWorkspace">;
  publishHistoryStore?: Pick<PublishHistoryStore, "listLiveUrls">;
  originRegistry?: Pick<OriginRegistryPort, "canonicalOrigin">;
}
export interface FetchLiveUrlDeps {
  /** Fresh workspace-scoped reads, never request Host or a caller-supplied arbitrary URL. */
  listKnownOrigins(): Promise<readonly string[]>;
  /** The shared guarded client with redirects disabled and a raw 1 MB ceiling. */
  httpClient: HttpClientPort;
  /** Optional host instrumentation; receives no body, headers, credentials or query parameters. */
  observeFetch?: (event: { origin: string; status?: number; durationMs: number; outcome: "response" | "refused" | "failed" }) => void;
}
export interface FetchLiveUrlInput extends PageBodyOptions { path: string; origin?: string | undefined }
export type LivePageResult = PublishedPageResult & { url: string; origin: string; redirects: string[]; untrusted: true; location?: string };
const REDIRECTS = new Set([301, 302, 303, 307, 308]);
const NO_LIVE_ADDRESS = "fetch_live_url: this site has no known live address yet. Publish it first, or use fetch_published_page to check the local render.";
const DEADLINE_MESSAGE = "fetch_live_url: fetching the live page exceeded 15000ms. Check the hosting service before retrying.";

/** Normalizes saved URLs to origins; embedded credentials never become an allowed origin. */
function liveOrigin(raw: string): string {
  let url: URL;
  try { url = new URL(raw); } catch { throw new ToolInputError({ message: "fetch_live_url: a saved live address is invalid. Correct the publishing address and retry." }); }
  if (url.protocol !== "https:" || url.port !== "" || url.username || url.password) throw new ToolInputError({ message: "fetch_live_url: live origins must use HTTPS on port 443 without credentials." });
  return url.origin;
}

/** Reads connected + keyed peers, full-ledger publish URL projection, and the trusted configured origin. */
export async function listKnownLiveOrigins(deps: LiveOriginSourceDeps): Promise<string[]> {
  const peers = await deps.publishContentPeerRepo?.listByWorkspace({ workspaceId: deps.workspaceId }) ?? [];
  const connected = selectConnectedDestination(peers);
  const urls = peers.filter(peer => peer.sealed !== null || peer === connected).map(peer => peer.baseUrl);
  const historyUrls = await deps.publishHistoryStore?.listLiveUrls({ workspaceId: deps.workspaceId }) ?? [];
  if (historyUrls.length > 200) throw new ToolInputError({ message: "fetch_live_url: more than 200 distinct live addresses are recorded. Review the publish history before fetching." });
  urls.push(...historyUrls);
  urls.push(...await configuredLiveOrigins(deps));
  return [...new Set(urls.map(liveOrigin))].sort();
}

/** Reads only explicitly configured trust evidence; absent verification supplies no address. */
async function configuredLiveOrigins({ originRegistry, workspaceId }: LiveOriginSourceDeps, _options: Record<string, never> = {}): Promise<string[]> {
  if (!originRegistry) return [];
  try {
    const configured = await originRegistry.canonicalOrigin({ workspaceId });
    if (configured.source !== "workspace-setting") return [];
    const base = `${configured.scheme}://${configured.host}`;
    const port = configured.port ? `:${configured.port}` : "";
    return [`${base}${port}`];
  } catch (error) {
    if (!(error instanceof OriginNotVerifiedError)) throw error;
    return [];
  }
}

/** Only the origin itself is accepted for explicit selection, never a path/userinfo-bearing URL. */
function selectOrigin(known: readonly string[], requested: string | undefined): string {
  const origins = [...new Set(known.map(liveOrigin))].sort();
  if (origins.length === 0) throw new ToolInputError({ message: NO_LIVE_ADDRESS });
  if (requested !== undefined) {
    const normalized = liveOrigin(requested);
    const explicit = new URL(requested);
    if (explicit.pathname !== "/" || explicit.search || explicit.hash) throw new ToolInputError({ message: `fetch_live_url: origin is not a known live address. Pass one of: ${origins.join(", ")}.` });
    if (!origins.includes(normalized)) throw new ToolInputError({ message: `fetch_live_url: origin is not a known live address. Pass one of: ${origins.join(", ")}.` });
    return normalized;
  }
  if (origins.length > 1) throw new ToolInputError({ message: `fetch_live_url: several live origins are known. Pass origin as one of: ${origins.join(", ")}.` });
  return origins[0]!;
}

/** Reuses the local path boundary while retaining actionable errors at the assistant boundary. */
function resolveLivePath(path: string, origin: string): string {
  try { return resolveSameOriginPath(path, origin); }
  catch (error) {
    if (error instanceof PublishedPagePathError) throw new ToolInputError({ message: `fetch_live_url: ${error.message}` });
    throw error;
  }
}

/** Validates raw and resolved same-origin paths before URL normalization can erase traversal. */
function redirectTarget(location: string, current: string, origin: string): string | null {
  let next: URL;
  try { next = new URL(location, current); }
  catch { throw new ToolInputError({ message: "fetch_live_url: the live site returned an invalid redirect address. Check the hosting service before retrying." }); }
  if (next.origin !== origin) return null;
  if (next.username || next.password) throw new ToolInputError({ message: "fetch_live_url: redirects with embedded credentials are refused." });
  const rawPath = location.replace(/^(?:[a-z][a-z0-9+.-]*:)?\/\/[^/?#]*/i, "").split("#")[0]!;
  resolveLivePath(rawPath.startsWith("/") ? rawPath : "/" + rawPath, origin);
  resolveLivePath(next.pathname + next.search, origin);
  next.hash = "";
  return next.href;
}

/**
 * GETs this site's own live copy through the existing pinned-public-peer guard. One 15 s deadline
 * covers origin reads, DNS, redirects and body reads. Cross-origin and fourth redirects are results.
 * @returns Visitor response evidence; third-party text is explicitly untrusted, cookie values omitted.
 * @throws ToolInputError for address selection, unsafe input/egress, or timeout.
 */
export async function fetchLiveUrl(deps: FetchLiveUrlDeps, input: FetchLiveUrlInput): Promise<LivePageResult> {
  const options = readPageBodyOptions(input as unknown as Record<string, unknown>);
  const deadline = AbortSignal.timeout(15_000);
  return awaitWithDeadline(fetchWithinDeadline(deps, input, options, deadline), deadline);
}

/** One bounded operation, including slow repositories and time between redirect hops. */
async function fetchWithinDeadline(deps: FetchLiveUrlDeps, input: FetchLiveUrlInput, options: PageBodyOptions, deadline: AbortSignal): Promise<LivePageResult> {
  const started = Date.now();
  const origin = selectOrigin(await deps.listKnownOrigins(), input.origin);
  const path = resolveLivePath(input.path, origin);
  const rawReadCap = options.textOnly || options.find !== undefined ? MAX_MAX_BODY_BYTES : options.maxBytes ?? DEFAULT_MAX_BODY_BYTES;
  let url = origin + path;
  const redirects: string[] = [];
  for (;;) {
    deadline.throwIfAborted();
    const response = await sendPage(deps, url, deadline, Math.max(1, 15_000 - (Date.now() - started)), rawReadCap);
    const headers = pageHeaders(response);
    const location = headers.location;
    if (REDIRECTS.has(response.status) && location && redirects.length < 3) {
      const next = redirectTarget(location, url, origin);
      if (next !== null) { redirects.push(next); url = next; continue; }
    }
    return livePageResult({ response, headers, options, url, origin, redirects });
  }
}

/** Header names are case-insensitive; cookie values are projected separately. */
function pageHeaders({ headers }: HttpResponse, _options: Record<string, never> = {}): Record<string, string> {
  const result: Record<string, string> = {};
  for (const [key, value] of Object.entries(headers)) {
    if (key.toLowerCase() !== "set-cookie") result[key.toLowerCase()] = value;
  }
  return result;
}

/** Shapes the final hop, retaining both upstream and local truncation evidence. */
function livePageResult({ response, headers, options, url, origin, redirects }: {
  response: HttpResponse; headers: Record<string, string>; options: PageBodyOptions;
  url: string; origin: string; redirects: string[];
}, _options: Record<string, never> = {}): LivePageResult {
  const cookies = new Headers();
  for (const cookie of response.setCookies ?? []) cookies.append("set-cookie", cookie);
  const raw = Buffer.from(response.bodyText).subarray(0, MAX_MAX_BODY_BYTES).toString("utf8");
  const shaped = shapePageBody(raw, options);
  const location = headers.location;
  return { path: new URL(url).pathname + new URL(url).search, status: response.status, ok: response.status >= 200 && response.status < 300, headers, cookies: toCookieShapes(cookies), ...shaped, truncated: shaped.truncated || response.bodyTruncated === true || Buffer.byteLength(response.bodyText) > MAX_MAX_BODY_BYTES, url, origin, redirects, untrusted: true, ...(REDIRECTS.has(response.status) && location ? { location } : {}) };
}

/** Caller-safe egress refusals, following media-import's policy-error projection without leaking IPs. */
async function sendPage(deps: FetchLiveUrlDeps, url: string, signal: AbortSignal, timeoutMs: number, maxResponseBytes: number) {
  const started = Date.now();
  try {
    const response = await deps.httpClient.send({ method: "GET", url, headers: {}, timeoutMs, signal, maxResponseBytes });
    deps.observeFetch?.({ origin: new URL(url).origin, status: response.status, durationMs: Date.now() - started, outcome: "response" });
    return response;
  } catch (error) {
    deps.observeFetch?.({ origin: new URL(url).origin, durationMs: Date.now() - started, outcome: error instanceof EgressRefusedError ? "refused" : "failed" });
    if (error instanceof EgressRefusedError) throw new ToolInputError({ message: `fetch_live_url: ${error.callerSafeMessage}` });
    if (signal.aborted) throw new ToolInputError({ message: DEADLINE_MESSAGE });
    throw error;
  }
}

/** Bounds the whole operation while releasing its listener on either completion path. */
async function awaitWithDeadline<T>(work: Promise<T>, signal: AbortSignal): Promise<T> {
  let abort: (() => void) | undefined;
  try {
    return await Promise.race([work, new Promise<never>((_resolve, reject) => {
      abort = () => reject(new ToolInputError({ message: DEADLINE_MESSAGE }));
      signal.addEventListener("abort", abort, { once: true });
      if (signal.aborted) abort();
    })]);
  } finally { if (abort) signal.removeEventListener("abort", abort); }
}

import { ToolInputError } from "@jini-ai/core";
import { parse, type DefaultTreeAdapterMap } from "parse5";

/** t08: shared HTML/text/find projection. Network producers also enforce a raw 1 MB ceiling. */
export const DEFAULT_MAX_BODY_BYTES = 20_000;
export const MAX_MAX_BODY_BYTES = 1_000_000;
export interface PageBodyOptions { maxBytes?: number | undefined; find?: string | undefined; textOnly?: boolean | undefined }
export type ShapedPageBody = { bodyBytes: number; truncated: boolean } & (
  { body: string; matches?: never; matchCount?: never } |
  { matches: Array<{ offset: number; snippet: string }>; matchCount: number; body?: never }
);

/** Validates all shared options at the tool boundary; no implicit coercion or silent defaults. */
export function readPageBodyOptions(input: Record<string, unknown>): PageBodyOptions {
  const { find, textOnly, maxBytes } = input;
  if (find !== undefined && (typeof find !== "string" || find.length < 1 || find.length > 200)) throw new ToolInputError({ message: "find must be a string of 1..200 characters." });
  if (textOnly !== undefined && typeof textOnly !== "boolean") throw new ToolInputError({ message: "textOnly must be a boolean." });
  assertMaxBodyBytes({ maxBytes });
  return { find: find as string | undefined, textOnly: textOnly as boolean | undefined, maxBytes: maxBytes as number | undefined };
}

/** Keeps the numeric budget validation and its boundary error together. */
function assertMaxBodyBytes({ maxBytes }: { maxBytes: unknown }, _options: Record<string, never> = {}): void {
  if (maxBytes !== undefined && (typeof maxBytes !== "number" || !Number.isInteger(maxBytes) || maxBytes < 1 || maxBytes > MAX_MAX_BODY_BYTES)) throw new ToolInputError({ message: "maxBytes must be an integer of 1..1000000." });
}

const OMITTED_ELEMENTS = new Set(["script", "style", "noscript", "template"]);
const BLOCK_ELEMENTS = new Set(["html", "head", "body", "p", "div", "section", "article", "main", "header", "footer", "nav", "br", "li", "ul", "ol", "table", "tr", "td", "th", "h1", "h2", "h3", "h4", "h5", "h6", "hr", "pre", "blockquote"]);
/** Iterative traversal avoids stack overflow on deeply nested untrusted HTML. Parser decodes entities. */
function visibleText(body: string): string {
  const pending: Array<DefaultTreeAdapterMap["node"] | string> = [parse(body)];
  const text: string[] = [];
  while (pending.length) {
    appendVisibleNode({ node: pending.pop()!, pending, text });
  }
  return text.join("").replace(/\s+/g, " ").trim();
}

/** Visits one parsed node, scheduling children in document order and spaces around blocks. */
function appendVisibleNode({ node, pending, text }: {
  node: DefaultTreeAdapterMap["node"] | string;
  pending: Array<DefaultTreeAdapterMap["node"] | string>;
  text: string[];
}, _options: Record<string, never> = {}): void {
  if (typeof node === "string") { text.push(node); return; }
  if ("tagName" in node && OMITTED_ELEMENTS.has(node.tagName)) return;
  if (node.nodeName === "#text" && "value" in node) { text.push(node.value); return; }
  scheduleVisibleChildren({ node, pending, text });
}

/** Schedules children in document order, surrounding blocks with deferred closing spaces. */
function scheduleVisibleChildren({ node, pending, text }: {
  node: DefaultTreeAdapterMap["node"];
  pending: Array<DefaultTreeAdapterMap["node"] | string>;
  text: string[];
}, _options: Record<string, never> = {}): void {
  if (!("childNodes" in node)) return;
  const block = "tagName" in node && BLOCK_ELEMENTS.has(node.tagName);
  if (block) { text.push(" "); pending.push(" "); }
  for (let i = node.childNodes.length - 1; i >= 0; i--) pending.push(node.childNodes[i]!);
}

/** Cuts at a UTF-8 boundary so shaping does not expand a clipped byte into a replacement character. */
function capText(body: string, maxBytes: number): string {
  const bytes = Buffer.from(body);
  if (bytes.length <= maxBytes) return body;
  let end = maxBytes;
  while (end > 0 && (bytes[end]! & 0xc0) === 0x80) end--;
  return bytes.subarray(0, end).toString("utf8");
}

/** O(body length + matches); counts the full available source, retains at most 20 bounded snippets. */
function findMatches(body: string, find: string, maxBytes: number): ShapedPageBody {
  const pattern = new RegExp(RegExp.escape(find), "giu");
  const matches: Array<{ offset: number; snippet: string }> = [];
  let matchCount = 0;
  let bytesLeft = maxBytes;
  let truncated = false;
  for (const match of body.matchAll(pattern)) {
    matchCount++;
    if (matches.length === 20 || bytesLeft === 0) { truncated = true; continue; }
    const offset = match.index;
    const context = body.slice(Math.max(0, offset - 160), offset + match[0].length + 160);
    const snippet = capText(context, bytesLeft);
    if (snippet !== context) truncated = true;
    bytesLeft -= Buffer.byteLength(snippet);
    matches.push({ offset, snippet });
  }
  return { matches, matchCount, bodyBytes: Buffer.byteLength(body), truncated };
}

/**
 * Shapes available page text, stripping before capping. With find, offsets are UTF-16 positions in
 * the shaped source; matchCount counts non-overlapping matches in that source, even after the
 * snippet budget is exhausted. Producers OR their raw-read truncation into this flag.
 * @returns Body or matches (never both), source byte count and an explicit truncation flag.
 */
export function shapePageBody(body: string, options: PageBodyOptions): ShapedPageBody {
  const maxBytes = options.maxBytes ?? DEFAULT_MAX_BODY_BYTES;
  const source = options.textOnly ? visibleText(body) : body;
  if (options.find !== undefined) return findMatches(source, options.find, maxBytes);
  // Preserve the existing raw-page decode behavior at a split multibyte character.
  const bytes = Buffer.from(source);
  if (bytes.length <= maxBytes) return { body: source, bodyBytes: bytes.length, truncated: false };
  const capped = options.textOnly ? capText(source, maxBytes) : bytes.subarray(0, maxBytes).toString("utf8");
  return { body: capped, bodyBytes: options.textOnly ? Buffer.byteLength(capped) : maxBytes, truncated: true };
}

import { DEFAULT_MAX_BODY_BYTES, MAX_MAX_BODY_BYTES, shapePageBody, type PageBodyOptions, type ShapedPageBody } from "./page-body.js";
import { createServer, type RequestListener, type Server } from "node:http";
import { once } from "node:events";
import type { AddressInfo } from "node:net";

import { createNoopObservabilityPort, trackFetch, type ObservabilityPort } from "#src/platform/observability/index";
import { checkSitePathname, hasControlCharacter } from "#src/platform/routing/index";
import type { SitePathCheck } from "#src/platform/routing/index";

/**
 * @file `fetchPublishedPage()` — renders ONE route of this site's own public surface and returns
 * what a visitor would actually receive: status, headers, cookie shapes and (bounded) body.
 *
 * Why this exists as a sibling of `site-profile.ts` rather than a bigger snapshot (2026-08-26
 * swarm-consensus, "config truth vs. render truth", agreed 5/5): a configuration snapshot can
 * truthfully report "cookie-consent widget: installed, enabled" while the published page renders
 * nothing of the sort. This codebase has three render paths that do not agree, and configuration is
 * not one of them. Anything that must know what is LIVE has to fetch the live thing.
 *
 * ---------------------------------------------------------------------------
 * This is an SSRF-shaped surface. Here is why it structurally is not one.
 * ---------------------------------------------------------------------------
 *
 * The tool takes a **path**, never a URL. There is no caller-supplied host, scheme, port or
 * credential anywhere in this module, so there is no allowlist to get wrong and no redirect hop to
 * re-validate against a denylist of private ranges.
 *
 * The origin is one this process CREATES for the duration of a single call: `createSiteApp()`'s own
 * Express app on an ephemeral `127.0.0.1` port, exactly the way `export/site-exporter.ts` already
 * renders the site for a static export. Nothing in the input can steer that origin. Even a caller
 * that smuggles an absolute URL past the string checks would fail the explicit
 * `url.origin === base.origin` assertion in {@link resolveSameOriginPath}, which compares against
 * the origin this module minted rather than against a pattern.
 *
 * On top of that, the path itself is validated allowlist-style before it is used
 * ({@link resolveSameOriginPath}): must be root-relative, no protocol-relative `//` prefix, no
 * backslashes, no control characters (CR/LF request splitting), no `..` segments after a single
 * percent-decode, and not under `/api/` — see that function's own doc for why each one is there.
 *
 * `redirect: "manual"` is deliberate: a 30x is EVIDENCE (a compliance consumer wants to know the
 * privacy-policy URL redirects), and following it automatically would be the one place a
 * server-controlled `Location` could walk this fetch off-origin.
 *
 * ---------------------------------------------------------------------------
 * What is and is not returned
 * ---------------------------------------------------------------------------
 * - **All response headers except `set-cookie`.** An allowlist would defeat the point: "does this
 *   site emit an unexpected header" is exactly the kind of question this tool exists to answer.
 *   These are headers this site's own code emits; none of them is a stored credential.
 * - **`set-cookie` is projected to name + attributes, never a value** ({@link toCookieShapes}).
 *   For the compliance case the cookie NAME and its `Secure`/`HttpOnly`/`SameSite`/`Max-Age`
 *   attributes are the whole signal; the value is the only part that could carry a session token.
 * - **The body, capped** at {@link DEFAULT_MAX_BODY_BYTES} with an explicit `truncated` flag. The
 *   read stops at the cap rather than buffering the whole response and slicing afterwards, so a
 *   pathologically large route cannot be turned into a memory-exhaustion lever.
 */

export { DEFAULT_MAX_BODY_BYTES, MAX_MAX_BODY_BYTES } from "./page-body.js";

/** Longest path string accepted before validation even begins. */
export const MAX_PATH_LENGTH = 2_048;

/** Wall clock for one render+fetch, including booting the ephemeral app. */
export const DEFAULT_FETCH_TIMEOUT_MS = 15_000;

/** The origin this module mints for every call. Fixed loopback host; only the port varies. */
const LOOPBACK_HOST = "http://127.0.0.1";

/**
 * Raised when `path` is not a fetchable same-origin site path. Its own class so the tool layer can
 * publish the input schema back with it: every rejection here is one a DIFFERENT `path` would fix.
 */
export class PublishedPagePathError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "PublishedPagePathError";
  }
}

/** One `Set-Cookie` header, with the value removed. */
export interface PublishedPageCookieShape {
  name: string;
  /** `Secure`, `HttpOnly`, `SameSite=Lax`, `Path=/`, ... — verbatim, minus the `name=value` pair. */
  attributes: string[];
}

export interface PublishedPageMetadata {
  /** The canonical path actually requested, after normalization — not the raw caller string. */
  path: string;
  status: number;
  /** `true` for 2xx only. A 30x/404 is a successful OBSERVATION, so the call does not throw. */
  ok: boolean;
  /** Response headers, lowercased, `set-cookie` excluded (see {@link cookies}). */
  headers: Record<string, string>;
  /** `Set-Cookie` headers with their values stripped — see this file's header. */
  cookies: PublishedPageCookieShape[];
  /** Bytes actually read into {@link body} (not `Content-Length`, which may disagree). */
  bodyBytes: number;
  /** `true` when the cap stopped the read before the response ended. */
  truncated: boolean;
}

export type PublishedPageResult = Omit<PublishedPageMetadata, "bodyBytes" | "truncated"> & ShapedPageBody;

export interface FetchPublishedPageDeps {
  /**
   * The SAME site-app factory the static exporter renders through (`RouteDeps.createSiteApp`).
   *
   * Takes the optional render override (`{ themeId }`, 2026-10-08: `web_screenshot_page` seeing a
   * theme copy without activating it). It used to be handed the deps bag itself, for a historical
   * `(routeDeps: RouteDeps) => Express` shape; both composition roots have long been nullary-closed
   * over their deps, so nothing reads that argument any more.
   *
   * Typed as Node's `RequestListener` rather than Express's `Express` because that is what this
   * module actually consumes — the sole use is `createServer(deps.createSiteApp(...))`, and
   * `http.createServer` takes a request listener. Naming `Express` here made the feature import a
   * web framework to describe a two-argument callback, which is the `features/` boundary violation
   * `src/features/__tests__/features-no-server-imports.boundary.test.ts` fails on. A real Express
   * app still satisfies this: `@types/express-serve-static-core`'s `Application` declares an
   * explicit `(req: http.IncomingMessage, res: http.ServerResponse)` call signature, which is
   * exactly why `createServer(app)` type-checked before this change and still does.
   */
  createSiteApp(optional?: { themeId?: string; consentAudit?: true }): RequestListener;
  /** Native server factory; injected fakes can exercise rendering without opening a socket. */
  readonly createServer?: (listener: RequestListener) => Server;
  /** HTTP transport; omitted, uses the global fetch read at call time. */
  readonly fetch?: typeof globalThis.fetch;
  /** Traces the loopback render as one outbound span (method, host/port, status — never the path).
   *  `RouteDeps.observability` in production; omitted, the render is untraced. */
  readonly observability?: ObservabilityPort;
}

const UNTRACED = createNoopObservabilityPort({});

export interface FetchPublishedPageOptions extends PageBodyOptions {
  /** Body bytes to keep, clamped to `[1, MAX_MAX_BODY_BYTES]`. */
  maxBytes?: number | undefined;
  /** Wall clock for the whole call. */
  timeoutMs?: number | undefined;
}

/**
 * Refuses any `..` segment in a raw path, before and after ONE percent-decode.
 *
 * Runs on the RAW string rather than a parsed `URL.pathname` because `new URL()` resolves `..`
 * away silently — see the call site's own comment. One decode pass is the right depth: a
 * double-encoded `%252e%252e` decodes to the literal text `%2e%2e`, which a static-file handler
 * treats as a filename, not as traversal.
 *
 * @param pathOnly - The raw path with any query string already removed.
 * @param raw - The caller's original string, for the error message.
 * @throws {PublishedPagePathError} On a raw or singly-encoded `..` segment, or on a malformed
 * percent-encoding (which cannot be decoded and therefore cannot be cleared).
 * @complexity O(L) in the path length.
 * @example assertNoTraversalSegment("/a/%2e%2e/b", "/a/%2e%2e/b"); // throws
 */
function assertNoTraversalSegment(pathOnly: string, raw: string): void {
  for (const segment of pathOnly.split("/")) {
    if (segment === "..") {
      throw new PublishedPagePathError(`path must not contain a '..' segment (encoded or not): '${raw}'.`);
    }
    if (!segment.includes("%")) continue;
    let decoded: string;
    try {
      decoded = decodeURIComponent(segment);
    } catch {
      throw new PublishedPagePathError(`path contains a malformed percent-encoding: '${raw}'.`);
    }
    if (decoded === "..") {
      throw new PublishedPagePathError(`path must not contain a '..' segment (encoded or not): '${raw}'.`);
    }
  }
}

/**
 * The syntactic rejections that operate on the raw caller value, before any URL parsing happens.
 * Split out of {@link resolveSameOriginPath} purely to keep that function's own complexity below
 * the repo's gate — the checks, their order, and every message are unchanged.
 *
 * @throws {PublishedPagePathError} On the first rule `raw` fails.
 * @returns `raw`, narrowed to `string`, once every rule has passed.
 */
function assertRawPathShape(raw: unknown): string {
  if (typeof raw !== "string" || raw.length === 0) {
    throw new PublishedPagePathError("path must be a non-empty string, e.g. '/' or '/blog/hello'.");
  }
  if (raw.length > MAX_PATH_LENGTH) {
    throw new PublishedPagePathError(`path must be at most ${MAX_PATH_LENGTH} characters, got ${raw.length}.`);
  }
  if (!raw.startsWith("/")) {
    throw new PublishedPagePathError(
      `path must start with '/' — this tool fetches a route on THIS site and never accepts a full URL or a remote host. Got '${raw}'.`,
    );
  }
  if (raw.startsWith("//")) {
    throw new PublishedPagePathError(
      "path must not start with '//' — a protocol-relative path resolves to a different host, which this tool never fetches.",
    );
  }
  if (raw.includes("\\")) {
    throw new PublishedPagePathError("path must not contain a backslash — URL parsers treat '\\' as '/'.");
  }
  if (hasControlCharacter(raw)) {
    throw new PublishedPagePathError("path must not contain control characters (including CR/LF).");
  }
  // BEFORE `new URL()`, because the URL parser RESOLVES `..` away rather than reporting it:
  // `new URL("/a/../../etc/passwd", base).pathname` is already `/etc/passwd`, so a check on the
  // parsed pathname sees nothing to reject. Silent normalization is exactly the "rewrite rather
  // than refuse" behavior this validator must not have — a caller that wrote `..` gets told so.
  assertNoTraversalSegment(raw.split("?")[0] ?? "", raw);
  return raw;
}

/**
 * Parses `raw` against `base` and asserts the result stayed on `base`'s origin. Split out of
 * {@link resolveSameOriginPath} purely to keep that function's own complexity below the repo's
 * gate — the structural same-origin assertion itself is unchanged.
 *
 * @throws {PublishedPagePathError} If `raw` does not parse, or parses off-origin.
 */
function resolveWithinOrigin(raw: string, base: string): URL {
  const baseUrl = new URL(base);
  let resolved: URL;
  try {
    resolved = new URL(raw, baseUrl);
  } catch {
    throw new PublishedPagePathError(`path is not a valid URL path: '${raw}'.`);
  }
  if (resolved.origin !== baseUrl.origin) {
    throw new PublishedPagePathError(
      `path resolved off-origin (to '${resolved.origin}') — this tool only fetches routes on this site.`,
    );
  }
  return resolved;
}

/**
 * Why a resolved pathname was refused, phrased for this module's caller.
 *
 * Split out of {@link assertNoDisallowedDecodedForm} so the wording lives next to the verdict
 * union it exhausts: with an explicit `string | null` return type and no `default` arm, a future
 * case added to `SitePathCheck` is a compile error here rather than a silent fall-through to
 * "allowed". Mirrors `redirects.ts`'s `siteRelativeRefusalReason`, the sibling that already gets
 * this right for `SiteRelativeTargetCheck`.
 *
 * The rule itself is deliberately NOT restated here: `redirects`' write chokepoint has to refuse
 * exactly the same surfaces for a stored redirect target, and two copies of a denylist is how one
 * of them ends up a decode or a case-fold behind the other.
 *
 * @param check - The verdict from `checkSitePathname`.
 * @param raw - The original caller-supplied path, for the error message only.
 * @returns The refusal message, or `null` when the path is allowed.
 * @complexity O(1).
 */
function disallowedFormReason(check: SitePathCheck, raw: string): string | null {
  switch (check.kind) {
    case "ok":
      return null;
    case "malformed-encoding":
      return `path contains a malformed percent-encoding: '${raw}'.`;
    case "disallowed-character":
      return "path decodes to a backslash or control character, which is refused.";
    case "reserved":
      return `path must not target '/${check.surface}' — that is the authenticated admin/API surface, not a published page.`;
  }
}

/**
 * Applies `platform/routing`'s shared reserved-path rule to the resolved pathname and maps its
 * verdict onto this module's own error type. Split out purely to keep {@link resolveSameOriginPath}
 * below the repo's complexity gate.
 *
 * @throws {PublishedPagePathError} On a malformed encoding, a decoded backslash/control character,
 * or a path that resolves onto `/admin` or `/api`.
 */
function assertNoDisallowedDecodedForm(resolved: URL, raw: string): void {
  const reason = disallowedFormReason(checkSitePathname(resolved), raw);
  if (reason !== null) throw new PublishedPagePathError(reason);
}

/**
 * Validates and canonicalizes a caller-supplied site path against the loopback origin this module
 * minted, following canonicalize-then-validate order.
 *
 * Each rule closes a specific hole rather than being defensive in general:
 * - **must be a non-empty string within {@link MAX_PATH_LENGTH}** — bounds the work every later
 *   check does.
 * - **must start with `/`** — rejects an absolute URL (`http://evil.example/x`) and a bare relative
 *   path, both of which would resolve somewhere other than this site's root.
 * - **must not start with `//`** — a protocol-relative URL resolves to a DIFFERENT HOST while still
 *   starting with a slash. This is the single most commonly missed same-origin bypass.
 * - **no backslash anywhere** — `\` is treated as `/` by URL parsers and browsers, so `/\evil.com`
 *   is a protocol-relative URL wearing a disguise.
 * - **no C0/C1 control characters** — CR/LF in a request target is HTTP request splitting; NUL and
 *   friends are path-truncation tricks.
 * - **`new URL(raw, base)` must keep `base`'s origin** — the structural assertion. Everything above
 *   is belt; this is braces, and it compares against the origin this process minted rather than
 *   against a pattern someone has to keep correct.
 * - **no `..` segment after ONE percent-decode** — blocks `%2e%2e` and its double-encoded variants
 *   from reaching a static-file handler. `..` cannot escape the origin, but it can escape a
 *   directory, and a single decode pass is enough because the check runs on the decoded form and
 *   rejects a remaining `%` sequence that decodes to a traversal.
 * - **not on `/admin` or `/api`** — the site app, the admin SPA and the admin API share one
 *   Express app (`admin-static.ts`'s `app.use("/admin", ...)`, `core.ts`'s
 *   `app.use("/api/admin", ...)`). Both are session-gated, so an unauthenticated in-process request
 *   already fails, but "a published page" is a claim about the public site and this tool must not
 *   become a second, unaudited door to the admin surface. Defense in depth, stated as a rule rather
 *   than relied on as a side effect. The comparison is per SEGMENT and post-decode
 *   (`platform/routing/reserved-paths.ts`), so `/%61dmin` is refused while `/administer-survey`
 *   — ordinary site content that merely starts with the same letters — is not.
 *
 * @param raw - The caller's path, untrusted.
 * @param base - The loopback origin this call minted, e.g. `http://127.0.0.1:53142`.
 * @returns The canonical `pathname + search` to request, re-encoded by the URL parser.
 * @throws {PublishedPagePathError} With a message naming the specific rule that rejected it, so the
 * model can fix the input in one turn instead of guessing.
 * @complexity O(L) in the path length, bounded by {@link MAX_PATH_LENGTH}.
 * @example resolveSameOriginPath("/blog/hello", "http://127.0.0.1:53142"); // => "/blog/hello"
 */
export function resolveSameOriginPath(raw: unknown, base: string): string {
  const path = assertRawPathShape(raw);
  const resolved = resolveWithinOrigin(path, base);
  assertNoDisallowedDecodedForm(resolved, path);
  return `${resolved.pathname}${resolved.search}`;
}

/**
 * Strips the value from each `Set-Cookie` header, keeping the name and the attribute list.
 *
 * `Headers.getSetCookie()` is used rather than `headers.get("set-cookie")` because the latter joins
 * multiple cookies with `, `, which is ambiguous (an `Expires` attribute legally contains a comma)
 * and would corrupt the split.
 *
 * @param headers - The fetch response's headers.
 * @returns One entry per `Set-Cookie` header, in wire order. Empty array when none were sent.
 * @complexity O(C * A) in cookie count and attributes per cookie — both bounded by the response.
 * @example toCookieShapes(res.headers); // => [{ name: "sid", attributes: ["Path=/", "HttpOnly"] }]
 */
export function toCookieShapes(headers: Headers): PublishedPageCookieShape[] {
  const raw = typeof headers.getSetCookie === "function" ? headers.getSetCookie() : [];
  return raw.map((cookie) => {
    const parts = cookie.split(";");
    const pair = parts[0] ?? "";
    const equals = pair.indexOf("=");
    return {
      name: (equals >= 0 ? pair.slice(0, equals) : pair).trim(),
      attributes: parts.slice(1).map((part) => part.trim()).filter((part) => part.length > 0),
    };
  });
}

/**
 * Reads at most `maxBytes` from a fetch response body, stopping the stream once the cap is hit.
 *
 * Stops rather than buffering-then-slicing so an unexpectedly large route cannot be used to
 * exhaust memory. Decoding is UTF-8 and non-strict, so a multi-byte character split by the cap
 * degrades to a replacement character instead of throwing.
 *
 * @param response - The fetch response.
 * @param maxBytes - Cap, already clamped by the caller.
 * @returns The decoded text, how many bytes were read, and whether the cap stopped the read.
 * @complexity O(min(B, maxBytes)) in the response size.
 * @example await readBoundedBody(res, 200_000);
 */
export async function readBoundedBody(
  response: Response,
  maxBytes: number,
): Promise<{ body: string; bodyBytes: number; truncated: boolean }> {
  if (!response.body) return { body: "", bodyBytes: 0, truncated: false };

  const reader = response.body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;
  let truncated = false;

  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      if (!value) continue;
      const remaining = maxBytes - total;
      if (value.byteLength > remaining) {
        chunks.push(value.subarray(0, remaining));
        total += remaining;
        truncated = true;
        break;
      }
      chunks.push(value);
      total += value.byteLength;
    }
  } finally {
    await reader.cancel().catch(() => {
      // The response is already being abandoned; a cancel failure adds nothing the caller can act on.
    });
  }

  return { body: new TextDecoder("utf-8").decode(Buffer.concat(chunks)), bodyBytes: total, truncated };
}

/** Clamps `maxBytes` into `[1, MAX_MAX_BODY_BYTES]`, defaulting when absent or nonsensical. */
function resolveMaxBytes(requested: number | undefined): number {
  if (requested === undefined || !Number.isInteger(requested) || requested < 1) return DEFAULT_MAX_BODY_BYTES;
  return Math.min(requested, MAX_MAX_BODY_BYTES);
}

/** This site's own app, listening on a per-call loopback origin until `close` is awaited. */
export interface LoopbackSiteServer {
  /** e.g. `http://127.0.0.1:53142` — fixed host, ephemeral port, no trailing slash. */
  readonly origin: string;
  close(required?: {}, optional?: {}): Promise<void>;
}

/**
 * Boots the site's real app on an ephemeral `127.0.0.1` port. Shared by `fetch_published_page` and
 * `web_screenshot_page`'s own-site mode, so both observe the one render path the static exporter uses.
 * The caller owns the lifetime: `close()` in a `finally` (see {@link fetchPublishedPage} for why a
 * per-call server rather than a long-lived one).
 * @param required.deps - Supplies `createSiteApp` and an optional `createServer`.
 * @param optional.themeId - Render this site through that installed theme instead of the active one
 *   (`createSiteApp({ themeId })`); the caller checks it exists. Never reachable from a visitor: it is
 *   an option of this one throwaway app, not anything a request carries.
 * @param optional.consentAudit - Build the app without the cookie consent layer, so a screenshot shows
 *   the page rather than the banner over it. Same reach as `themeId`: this throwaway app only.
 * @complexity O(1) beyond one app construction.
 */
export async function openLoopbackSiteServer(
  { deps }: { deps: Pick<FetchPublishedPageDeps, "createSiteApp" | "createServer"> },
  { themeId, consentAudit }: { themeId?: string; consentAudit?: true } = {},
): Promise<LoopbackSiteServer> {
  const server = (deps.createServer ?? createServer)(deps.createSiteApp({ ...(themeId === undefined ? {} : { themeId }), ...(consentAudit ? { consentAudit } : {}) }));
  server.listen(0, "127.0.0.1");
  await once(server, "listening");
  const address = server.address() as AddressInfo;
  return {
    origin: `${LOOPBACK_HOST}:${address.port}`,
    async close() {
      server.closeAllConnections?.();
      // Resolves once the server is fully closed. Mirrors `export/site-exporter.ts`'s own teardown.
      await new Promise<void>((resolve) => server.close(() => resolve()));
    },
  };
}

/** Maps transport aborts to the published-page error while leaving body-read failures unchanged. */
async function requestPublishedPage({ deps, baseUrl, path, timeoutMs }: {
  deps: FetchPublishedPageDeps; baseUrl: string; path: string; timeoutMs: number;
}, _options: Record<string, never> = {}): Promise<Response> {
  try {
    // The default global `fetch` is read per call, so a test that swaps it is still honored.
    const send = trackFetch({ fetch: deps.fetch ?? ((url, init) => fetch(url, init)), observability: deps.observability ?? UNTRACED });
    return await send(`${baseUrl}${path}`, {
      redirect: "manual",
      signal: AbortSignal.timeout(timeoutMs),
    });
  } catch (err) {
    if (err instanceof Error && (err.name === "TimeoutError" || err.name === "AbortError")) {
      const timeout = new Error(`rendering '${path}' exceeded ${timeoutMs}ms`);
      timeout.name = "PublishedPageTimeoutError";
      throw timeout;
    }
    throw err;
  }
}

/**
 * Fetches one route of this site's own published surface and reports exactly what came back.
 *
 * Boots the site's real Express app on an ephemeral loopback port for the duration of ONE call,
 * requests the validated path, and tears the server down in a `finally` — the same lifecycle
 * `export/site-exporter.ts` uses to render a static export, so this observes the real render path
 * rather than a second, agreeing-today copy of it.
 *
 * A per-call server rather than a memoized one is deliberate: a long-lived listening socket in the
 * agent daemon would be a resource with no owner, and the cost here (route registration plus a
 * loopback round trip) is nothing against the LLM turn that requested it.
 *
 * @param deps - Supplies `createSiteApp` (see {@link FetchPublishedPageDeps} for why the signature
 * is written the way it is).
 * @param input.path - A root-relative path on this site, e.g. `/` or `/blog/hello?page=2`.
 * @param options.maxBytes - Body bytes to keep, clamped to `[1, MAX_MAX_BODY_BYTES]`.
 * @param options.timeoutMs - Wall clock for the whole call, default {@link DEFAULT_FETCH_TIMEOUT_MS}.
 * @returns A {@link PublishedPageResult}. A 404 or 30x is a RESULT, not an error — the caller
 * asked what is live, and "nothing is there" is a true answer.
 * @throws {PublishedPagePathError} When `path` fails {@link resolveSameOriginPath}.
 * @throws {Error} Named `PublishedPageTimeoutError` when the render exceeds `timeoutMs`.
 * @complexity O(min(B, maxBytes)) in the rendered response size, plus one Express app construction.
 * @example
 * const live = await fetchPublishedPage(routeDeps, { path: "/privacy" }, { maxBytes: 50_000 });
 * if (live.status === 404) console.log("no privacy policy is published");
 */
export async function fetchPublishedPage(
  deps: FetchPublishedPageDeps,
  input: { path: string },
  options: FetchPublishedPageOptions = {},
): Promise<PublishedPageResult> {
  const maxBytes = resolveMaxBytes(options.maxBytes);
  const timeoutMs = options.timeoutMs ?? DEFAULT_FETCH_TIMEOUT_MS;

  const site = await openLoopbackSiteServer({ deps });
  const baseUrl = site.origin;

  try {
    // Validated against the origin this call just minted — see `resolveSameOriginPath`'s doc.
    const path = resolveSameOriginPath(input.path, baseUrl);

    const response = await requestPublishedPage({ deps, baseUrl, path, timeoutMs });

    const headers: Record<string, string> = {};
    response.headers.forEach((value, key) => {
      // `set-cookie` is reported separately, with values stripped — see this file's header.
      if (key.toLowerCase() !== "set-cookie") headers[key.toLowerCase()] = value;
    });

    const raw = await readBoundedBody(response, options.textOnly || options.find !== undefined ? MAX_MAX_BODY_BYTES : maxBytes);
    // Preserve exact byte accounting/decoding for legacy reads, including split UTF-8.
    const legacy = !options.textOnly && options.find === undefined;
    const shaped = legacy ? raw : shapePageBody(raw.body, { ...options, maxBytes });

    return {
      path,
      status: response.status,
      ok: response.status >= 200 && response.status < 300,
      headers,
      cookies: toCookieShapes(response.headers),
      ...shaped,
      truncated: raw.truncated || shaped.truncated,
    };
  } finally {
    await site.close();
  }
}

/**
 * @file The per-section authorize-then-collect step both Site Inspection aggregators share:
 * `buildSiteProfile` (`site-profile.ts`) and `buildSiteCapabilities` (`site-capabilities.ts`).
 * Each section uses its own permission, isolates failures and excludes error messages from the
 * response. One implementation prevents the two aggregators' security guarantees from drifting.
 *
 * `site-profile.ts`'s header explains why that shape is structural rather than a convention: an
 * aggregator gated on one permission would be a privilege-escalation shortcut around every domain
 * gate it aggregates.
 */

/**
 * Why a section carries no data.
 * - `ok` — collected.
 * - `forbidden` — `authorize()` denied THIS section's own permission. Never silent.
 * - `unavailable` — the read threw, timed out, or its port was never wired. Also never silent: a
 *   consumer must read this as "unable to assess", not as a pass or as "nothing there".
 */
export type InspectionSectionStatus = "ok" | "forbidden" | "unavailable";

export interface InspectionSection<T> {
  status: InspectionSectionStatus;
  /** Present if and only if `status === "ok"`. */
  data?: T;
  /** `true` when a cap dropped rows/values from `data` — never inferred from array length. */
  truncated?: boolean;
  /**
   * Machine-readable cause for a non-`ok` status. For `forbidden` this is `authorize()`'s own
   * `reason`. For `unavailable` it is `"timed-out"`, a {@link SectionUnavailableError}'s own reason,
   * or the thrown error's CLASS NAME — deliberately not its message: an error message can quote row
   * data the DTO never chose to expose, and this response is handed to an LLM. The full error is
   * logged server-side instead.
   */
  reason?: string;
}

/** What one section collector produced, before it is wrapped in an {@link InspectionSection}. */
export interface CollectedSection<T> {
  data: T;
  truncated?: boolean;
}

/**
 * `authorize()`'s shape, declared structurally rather than imported from `@jini-ai/cms/core`, so this
 * module names only what it calls. `AuthorizeFn` satisfies it directly.
 */
export type InspectionAuthorizeFn = (params: {
  principalId: string;
  permission: string;
  workspaceId: string;
  entityType?: string | undefined;
  entityId?: string | undefined;
}) => Promise<{ allowed: boolean; reason: string }>;

/** Default per-section wall clock. These are local reads; a section still hanging past this is a
 *  fault, and reporting `unavailable` beats hanging the agent's turn. */
export const DEFAULT_SECTION_TIMEOUT_MS = 5_000;

/**
 * Thrown by a collector that knows exactly why it cannot run — today, a port the composition root
 * never supplied. Its `reason` is a fixed, data-free string, so unlike an arbitrary error it is safe
 * to report verbatim.
 */
export class SectionUnavailableError extends Error {
  readonly reason: string;

  constructor(reason: string) {
    super(`section unavailable: ${reason}`);
    this.name = "SectionUnavailableError";
    this.reason = reason;
  }
}

/**
 * Rejects after `ms`, so one wedged read cannot hang the whole aggregate.
 *
 * The timer is always cleared, including on the success path, so nothing here keeps a Node process
 * (or a `node:test` run) alive past the call.
 *
 * @throws {Error} Named `SectionTimeoutError` when `ms` elapses first.
 * @complexity O(1) beyond `work`.
 */
async function withTimeout<T>(work: Promise<T>, ms: number, label: string): Promise<T> {
  let timer: NodeJS.Timeout | undefined;
  try {
    return await Promise.race([
      work,
      new Promise<never>((_resolve, reject) => {
        timer = setTimeout(() => {
          const error = new Error(`${label} section timed out after ${ms}ms`);
          error.name = "SectionTimeoutError";
          reject(error);
        }, ms);
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}

/**
 * Authorizes ONE section against its own permission, then collects it.
 *
 * `authorize()` runs BEFORE `collect` is ever called, so a denied section performs no read at all.
 *
 * @param spec.authorize - The authorization port.
 * @param spec.workspaceId - The workspace every decision is scoped to.
 * @param spec.principalId - Who is asking.
 * @param spec.section - The section name, passed to `authorize()` as the entity id.
 * @param spec.permission - That section's own domain permission.
 * @param spec.entityType - The aggregate's entity type for `authorize()` (e.g. `site-profile-section`).
 * @param spec.logLabel - Prefix for the server-side log line and the timeout message.
 * @param spec.timeoutMs - Wall clock before the section is `unavailable`/`timed-out`.
 * @param spec.collect - The section's read, invoked only after authorization passes.
 * @returns `ok` on success, `forbidden` on denial, `unavailable` on throw/timeout. Never throws: one
 * broken section must not fail the others.
 * @complexity O(1) plus one `authorize()` call plus `collect`'s own cost.
 * @example
 * await authorizeAndCollectSection({ authorize, workspaceId, principalId, section: "tools", permission: "admin.assistant.use",
 *   entityType: "site-capabilities-section", logLabel: "site-capabilities", timeoutMs: 5000, collect: async () => ({ data }) });
 */
export async function authorizeAndCollectSection<T>(spec: {
  authorize: InspectionAuthorizeFn;
  workspaceId: string;
  principalId: string;
  section: string;
  permission: string;
  entityType: string;
  logLabel: string;
  timeoutMs: number;
  collect: () => Promise<CollectedSection<T>>;
}): Promise<InspectionSection<T>> {
  try {
    const decision = await spec.authorize({
      principalId: spec.principalId,
      permission: spec.permission,
      workspaceId: spec.workspaceId,
      entityType: spec.entityType,
      entityId: spec.section,
    });
    if (!decision.allowed) {
      return { status: "forbidden", reason: decision.reason };
    }

    const collected = await withTimeout(spec.collect(), spec.timeoutMs, spec.logLabel);
    return collected.truncated
      ? { status: "ok", data: collected.data, truncated: true }
      : { status: "ok", data: collected.data };
  } catch (err) {
    // Observability: the FULL error goes to the server log, where a secret in an error message is
    // no worse off than it already was. Only a fixed reason or the class name crosses into the
    // response — see `InspectionSection.reason`'s own doc for why the message deliberately does not.
    console.error(`[${spec.logLabel}] section '${spec.section}' failed`, err);
    if (err instanceof SectionUnavailableError) return { status: "unavailable", reason: err.reason };
    const name = err instanceof Error ? err.name : "UnknownError";
    return { status: "unavailable", reason: name === "SectionTimeoutError" ? "timed-out" : name };
  }
}

/**
 * De-duplicates and orders requested section names against a closed vocabulary, so a response's key
 * order is stable however the caller ordered its `sections` array.
 *
 * @param input.vocabulary - Every section the aggregate can report, in response order.
 * @param input.requested - The caller's selection. Omitted or empty means all of `vocabulary`.
 * @returns The selected names, in vocabulary order.
 * @complexity O(V + R) in the vocabulary and requested sizes.
 * @example resolveRequestedSections({ vocabulary: ["a", "b"], requested: ["b", "a", "b"] }); // => ["a", "b"]
 */
export function resolveRequestedSections<N extends string>(input: {
  vocabulary: readonly N[];
  requested: readonly N[] | undefined;
}): N[] {
  if (input.requested === undefined || input.requested.length === 0) return [...input.vocabulary];
  const asked = new Set<string>(input.requested);
  return input.vocabulary.filter((name) => asked.has(name));
}

import {
  authorizeAndCollectSection,
  DEFAULT_SECTION_TIMEOUT_MS,
  resolveRequestedSections,
  SectionUnavailableError,
  type CollectedSection,
  type InspectionAuthorizeFn,
  type InspectionSection,
} from "./section-collector.js";

/**
 * @file `buildSiteCapabilities()` — the one answer to "what can this site do?", behind the
 * `site_describe_capabilities` agent tool. It brings together three answers that used to live in
 * three places: the assistant's tools (`search_tools`/`describe_tool`), the admin app's screens
 * (reachable only through the live `page.find_elements` browser bridge), and content types
 * (`collections_content_type_list`).
 *
 * A call-time list keeps capability discovery on the tools' existing sources instead of making
 * an agent choose between parallel indexes. Nothing here is seeded, cached or ranked:
 * - tools — the composition root's live `ToolRegistry`, injected as `listCatalogTools` (bound to
 *   `assistant/tool-catalog-query.ts`'s `listToolCatalogEntries`; `features/**` may not import
 *   `assistant/**` by value). Same `source` domain and same stripped description `search_tools` and
 *   `describe_tool` report.
 * - admin screens — `admin-screens.generated.ts`, the checked-in copy of the admin app's own
 *   `listAdminAgentScreens()`, which an `apps/admin` test keeps from drifting.
 * - content types — the same `contentTypeRepo.listByWorkspace` read `collections_content_type_list`
 *   makes.
 *
 * Detail stays with the tools that own it: a tool entry is an id and one line, and the section says
 * to call `describe_tool`/`search_tools` for the rest.
 *
 * Per-section authorization, per-section status, and "one failing section never fails the call" come
 * from `section-collector.ts`, shared with `buildSiteProfile`.
 */

/** Every section this call can report — the closed vocabulary the `sections` input, the permission
 *  map and the response shape all derive from. */
export const SITE_CAPABILITIES_SECTION_NAMES = ["tools", "adminScreens", "contentTypes"] as const;

export type SiteCapabilitiesSectionName = (typeof SITE_CAPABILITIES_SECTION_NAMES)[number];

/**
 * The permission each section is authorized against, reused rather than minted:
 * - `tools` -> `admin.assistant.use` — what the assistant's own general tools
 *   (`assistant_admin_screen_link`, `assistant_ask_choice`) require. The list is the catalog a
 *   principal already reaches through `search_tools`.
 * - `adminScreens` -> `admin.assistant.use` — the same assistant-level floor. A screen list only tells
 *   an agent where a human could go; every screen still enforces its own permissions.
 * - `contentTypes` -> `admin.collections.read` (`collections_content_type_list`, and
 *   `site_get_profile`'s own `contentTypes` section).
 */
export const SITE_CAPABILITIES_SECTION_PERMISSIONS: Readonly<Record<SiteCapabilitiesSectionName, string>> = {
  tools: "admin.assistant.use",
  adminScreens: "admin.assistant.use",
  contentTypes: "admin.collections.read",
};

/** Longest tool summary, ellipsis included. The constraint is context tokens. Measured 2026-09-15 on the
 *  BYOK catalog (181 tools): the tools section is ~27KB of compact JSON at this cap, the whole response
 *  ~30KB compact and ~45KB pretty-printed (the MCP path pretty-prints tool results), and the same
 *  entries with full descriptions are ~118KB. The daemon's catalog is larger. */
export const MAX_TOOL_SUMMARY_CHARS = 120;

/** The `tools` section's `reason` when the composition root supplied no registry reader. */
export const TOOLS_NOT_WIRED_REASON = "not-wired";

const TOOLS_NOTE =
  "Each tool is listed by id with the first line of its description. Call describe_tool with an id for its full description and input schema, or search_tools to find a tool by what it does. A listed tool still checks its own permission when you run it.";

const ADMIN_SCREENS_NOTE =
  "Screens of the admin app, served under /admin: path is the route inside it (path '/posts' opens /admin/posts). id is what page.navigate accepts when a live admin tab is attached. Each screen still enforces its own permissions.";

// ---------------------------------------------------------------------------
// Ports — structural, so this module imports nothing from the composition root or `assistant/`.
// ---------------------------------------------------------------------------

/** One registered tool as the catalog presents it. `listToolCatalogEntries` returns this shape. */
export interface SiteCapabilityToolRow {
  id: string;
  /** The catalog domain `search_tools` reports for this id. */
  source: string;
  /** The authored description, search vocabulary already stripped. */
  description: string;
}

/** One agent-navigable admin screen. `admin-screens.generated.ts`'s rows are this shape. */
export interface SiteCapabilityAdminScreen {
  id: string;
  label: string;
  /** Route path inside the admin app (base-agnostic; the app is served under `/admin`). */
  path: string;
}

/** The subset of a content-type row this call reads. `ContentTypeRecord` is a structural superset. */
export interface SiteCapabilityContentTypeRow {
  key: string;
  label: string;
  tombstonedAt?: string | null;
}

/** Every dependency `buildSiteCapabilities` has, bound by `deps.ts`'s `toSiteCapabilitiesDeps`. */
export interface SiteCapabilitiesDeps {
  workspaceId: string;
  authorize: InspectionAuthorizeFn;
  clock: { nowIso(): string };
  /** The live registry reader. Absent when the composition root has no registry — the tools section
   *  then reports `unavailable`/{@link TOOLS_NOT_WIRED_REASON}, never an empty catalog. */
  listCatalogTools?: (() => readonly SiteCapabilityToolRow[]) | undefined;
  listAdminScreens(): readonly SiteCapabilityAdminScreen[];
  listContentTypes(): Promise<readonly SiteCapabilityContentTypeRow[]>;
}

export interface BuildSiteCapabilitiesOptions {
  /** Which sections to collect. Omitted/empty means all of {@link SITE_CAPABILITIES_SECTION_NAMES}. */
  sections?: readonly SiteCapabilitiesSectionName[] | undefined;
  /** Per-section wall clock before the section is marked `unavailable`/`timed-out`. */
  sectionTimeoutMs?: number | undefined;
}

