/** `authorize()`'s shape — `section-collector.ts`'s structural {@link InspectionAuthorizeFn}, so this
 *  module still names only what it reads. `AuthorizeFn` satisfies it directly. */
export type SiteProfileAuthorizeFn = InspectionAuthorizeFn;

/**
 * Every dependency `buildSiteProfile` has. Each field is a narrow read port bound by an ADAPTER
 * (`site-profile-deps.ts`) from the composition root's deps bag — deliberately NOT the deps bag
 * itself, so this signature enumerates exactly what the profile can reach and a reader can check
 * the secret-safety claim by reading this one interface.
 */
export interface SiteProfileDeps {
  workspaceId: string;
  authorize: SiteProfileAuthorizeFn;
  clock: { nowIso(): string };
  listPosts(): Promise<readonly SiteProfilePostRow[]>;
  listThemes(): Promise<readonly SiteProfileThemeRow[]>;
  readActiveThemeId(): Promise<string | null>;
  listPlugins(): Promise<readonly SiteProfilePluginRow[]>;
  listPluginActivations(): Promise<readonly SiteProfilePluginActivationRow[]>;
  /** One effective setting value, or `null` when the definition does not resolve. */
  readSetting(input: { namespace: string; key: string }): Promise<SiteProfileJsonValue | null>;
  listContentTypes(): Promise<readonly SiteProfileContentTypeRow[]>;
}

export interface BuildSiteProfileOptions {
  /** Which sections to collect. Omitted/empty means all of {@link SITE_PROFILE_SECTION_NAMES}. */
  sections?: readonly SiteProfileSectionName[] | undefined;
  /** Page rows to include, capped at {@link MAX_PAGE_ITEMS}. Defaults to {@link DEFAULT_PAGE_ITEMS}. */
  pageLimit?: number | undefined;
  /** Per-section wall clock before the section is marked `unavailable`/`timed-out`. */
  sectionTimeoutMs?: number | undefined;
}

/** Default page rows returned. Small on purpose: the constraint is LLM context tokens, not
 *  database milliseconds, and `total`/`countsBy*` already answer "how big is this site". */
export const DEFAULT_PAGE_ITEMS = 50;

/** Hard ceiling on page rows regardless of `pageLimit`. `PostRepoPort.list()` has no limit
 *  parameter, so the underlying read is O(N) in the workspace's row count no matter what — this
 *  caps the RESPONSE, which is the cost that actually matters here. */
export const MAX_PAGE_ITEMS = 200;

/** A setting value serializing beyond this is reported as `truncated` with `value: null` rather
 *  than inlined. Bounds a single misconfigured JSON setting from dominating the whole snapshot. */
export const MAX_SETTING_VALUE_CHARS = 2_000;

/** Default per-section wall clock. Owned by `section-collector.ts`; re-exported here under the name
 *  this module has always published. */
export { DEFAULT_SECTION_TIMEOUT_MS };

/**
 * The inventory-safe settings this profile reports, as an explicit allowlist of `(namespace, key)`
 * pairs — never "every registered setting".
 *
 * Two reasons it is an allowlist rather than an enumeration:
 * 1. `@jini-ai/core/settings` refuses `secret: true` definitions today
 *    ("secret:true definitions are not supported in the core-only subset"), but this boundary must
 *    not depend on that staying true forever. An allowlist stays correct if it changes.
 * 2. A plugin or a future capability can register arbitrary namespaces. Enumerating them would put
 *    third-party configuration into an LLM's context with nobody having decided it belongs there.
 *
 * Every entry below is a first-party, non-credential display/SEO setting registered by this repo's
 * own boot path (`seo/settings.ts`). Theme identity is read live by the theme section,
 * never from the obsolete core.presentation boot mirror.
 */
export const INVENTORY_SAFE_SETTINGS: readonly { namespace: string; key: string }[] = [
  { namespace: "site.seo", key: "title_template" },
  { namespace: "site.seo", key: "default_description" },
  { namespace: "site.seo", key: "default_og_image" },
  { namespace: "site.seo", key: "twitter_site" },
  { namespace: "site.seo", key: "default_robots_noindex" },
  { namespace: "site.seo", key: "default_robots_nofollow" },
  { namespace: "site.seo", key: "sitemap_enabled" },
  { namespace: "site.seo", key: "robots_rules" },
];

/**
 * Authorizes ONE profile section against {@link SITE_PROFILE_SECTION_PERMISSIONS}, then collects it,
 * through `section-collector.ts`'s shared mechanism (also used by `site_describe_capabilities`).
 *
 * Every profile section goes through this one binding of the permission map, so no section can be
 * added without its own gate. `authorize()` runs BEFORE `collect` is ever called, so a denied section
 * performs no read at all.
 *
 * @param deps - The profile's dependency bag (supplies `authorize` and `workspaceId`).
 * @param spec.principalId - Who is asking.
 * @param spec.section - Which section, used to look up its permission.
 * @param spec.timeoutMs - Per-section wall clock.
 * @param spec.collect - The section's own read, invoked only after authorization passes.
 * @returns An `ok` section on success, `forbidden` on denial, `unavailable` on throw/timeout.
 * Never throws: one broken section must not fail the other four.
 * @complexity O(1) plus one `authorize()` call plus `collect`'s own cost.
 * @example
 * await authorizeAndCollect(deps, { principalId: "p1", section: "theme", timeoutMs: 5000, collect: () => collectTheme(deps) });
 */
function authorizeAndCollect<T>(
  deps: SiteProfileDeps,
  spec: {
    principalId: string;
    section: SiteProfileSectionName;
    timeoutMs: number;
    collect: () => Promise<CollectedSection<T>>;
  },
): Promise<SiteProfileSection<T>> {
  return authorizeAndCollectSection({
    authorize: deps.authorize,
    workspaceId: deps.workspaceId,
    principalId: spec.principalId,
    section: spec.section,
    permission: SITE_PROFILE_SECTION_PERMISSIONS[spec.section],
    entityType: "site-profile-section",
    logLabel: "site-profile",
    timeoutMs: spec.timeoutMs,
    collect: spec.collect,
  });
}

/** Tally of one field's values across rows — the `countsBy*` maps' single implementation.
 *  @complexity O(N) in `rows`. */
function tally<T>(rows: readonly T[], pick: (row: T) => string): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const row of rows) {
    const key = pick(row);
    counts[key] = (counts[key] ?? 0) + 1;
  }
  return counts;
}

/** Field-by-field page projection. Never spreads the row — see this file's header. */
function toPageSummary(row: SiteProfilePostRow): SiteProfilePageSummary {
  return {
    id: row.id,
    title: row.title,
    slug: row.slug,
    kind: row.kind,
    status: row.status,
    bodyFormat: row.bodyFormat,
    updatedAt: row.updatedAt,
  };
}

/** Field-by-field theme projection. Never spreads the manifest — a `ThemeManifest` carries
 *  build-provenance and font fields this snapshot has no consumer for. */
function toThemeSummary(row: SiteProfileThemeRow): SiteProfileThemeSummary {
  return {
    id: row.manifest.id,
    name: row.manifest.name,
    version: row.manifest.version,
    tier: row.manifest.tier,
    source: row.source,
    status: row.status,
    errorCount: row.errors.length,
  };
}

/**
 * Collects the `pages` section: every non-trashed post/page row, counted in full and sampled to
 * `limit`.
 *
 * Counts come from the FULL row set while `items` is capped, so "this site has 4,000 pages" stays
 * true even when only 50 are listed. Trashed rows are excluded because they are invisible on every
 * admin and public read (`features/post/post.ts`'s `isTrashed`), so including them here would
 * describe a site nobody can see.
 *
 * @param deps - Supplies `listPosts()`.
 * @param limit - Maximum rows in `items`, already clamped by the caller.
 * @returns The section payload, with `truncated` set when rows were dropped.
 * @throws Whatever `listPosts()` throws — the caller converts it to `unavailable`.
 * @complexity O(N) in the workspace's post count; `PostRepoPort.list()` has no limit parameter, so
 *   the READ is unbounded by that port's design and only the response is capped.
 * @example await collectPages(deps, 50);
 */
async function collectPages(deps: SiteProfileDeps, limit: number): Promise<CollectedSection<SiteProfilePages>> {
  const rows = (await deps.listPosts()).filter((row) => row.deletedAt === undefined || row.deletedAt === null);
  const items = rows.slice(0, limit).map(toPageSummary);
  const data: SiteProfilePages = {
    total: rows.length,
    countsByKind: tally(rows, (row) => row.kind),
    countsByStatus: tally(rows, (row) => row.status),
    items,
  };
  return rows.length > items.length ? { data, truncated: true } : { data };
}

/**
 * Collects the `theme` section: the configured active theme id, its discovered row when it exists,
 * and every discovered theme.
 *
 * `active: null` with a non-null `activeThemeId` is a REAL state (the configured theme is missing
 * or was renamed) and is reported rather than smoothed over by the render-time fallback, because
 * "the site renders a different theme than the one configured" is exactly the kind of drift a
 * profile exists to surface.
 *
 * `themeDisabled` separates the one `active: null` case that is NOT drift: the operator turned the
 * theme off on purpose. Both states are reported; only one is a problem.
 *
 * @param deps - Supplies `readActiveThemeId()`/`listThemes()`.
 * @returns The section payload. Never truncated — the theme roster is boot-discovered and small.
 * @throws Whatever either read throws.
 * @complexity O(T) in the discovered-theme count.
 * @example await collectTheme(deps);
 */
async function collectTheme(deps: SiteProfileDeps): Promise<CollectedSection<SiteProfileTheme>> {
  const [activeThemeId, themes] = await Promise.all([deps.readActiveThemeId(), deps.listThemes()]);
  const installed = themes.map(toThemeSummary);
  return {
    data: {
      activeThemeId,
      active:
        activeThemeId === null
          ? null
          : (themeIdCandidates(activeThemeId)
              .map((id) => installed.find((theme) => theme.id === id))
              .find((theme) => theme !== undefined) ?? null),
      themeDisabled: activeThemeId === NO_THEME_ID,
      installed,
    },
  };
}

/**
 * Collects the `plugins` section: every discovered plugin, joined to THIS workspace's activation
 * rows.
 *
 * `PluginActivationRepoPort.listAll()` returns rows across every workspace (its own doc says so),
 * so the join filters on `deps.workspaceId` — without that filter a multi-tenant install would
 * report another workspace's activation state as this one's.
 *
 * @param deps - Supplies `listPlugins()`/`listPluginActivations()`.
 * @returns One row per discovered plugin. A plugin with no activation row reports `enabled: false`,
 * which is the real default, not a guess.
 * @throws Whatever either read throws.
 * @complexity O(P + A) — one pass to index activations, one pass over discovered plugins.
 * @example await collectPlugins(deps);
 */
async function collectPlugins(deps: SiteProfileDeps): Promise<CollectedSection<SiteProfilePluginSummary[]>> {
  const [discovered, activations] = await Promise.all([deps.listPlugins(), deps.listPluginActivations()]);
  const enabledByPluginId = new Map<string, boolean>();
  for (const row of activations) {
    if (row.workspaceId === deps.workspaceId) enabledByPluginId.set(row.pluginId, row.enabled);
  }
  return {
    data: discovered.map((plugin) => ({
      id: plugin.id,
      name: plugin.name,
      version: plugin.version,
      source: plugin.source,
      tier: plugin.tier ?? null,
      status: plugin.status,
      enabled: enabledByPluginId.get(plugin.id) ?? false,
    })),
  };
}

/**
 * Collects the `settings` section: exactly {@link INVENTORY_SAFE_SETTINGS}, read one at a time.
 *
 * An oversized value is reported as `truncated` with `value: null` rather than inlined, so one
 * misconfigured JSON setting cannot dominate the snapshot's token budget.
 *
 * @param deps - Supplies `readSetting()`.
 * @returns One row per allowlisted setting, in allowlist order. Section-level `truncated` is set
 * when ANY value was dropped.
 * @throws Whatever `readSetting()` throws.
 * @complexity O(S) reads for the S allowlisted settings — a fixed module constant, not caller data.
 * @example await collectSettings(deps);
 */
async function collectSettings(deps: SiteProfileDeps): Promise<CollectedSection<SiteProfileSettingSummary[]>> {
  const rows = await Promise.all(
    INVENTORY_SAFE_SETTINGS.map(async ({ namespace, key }): Promise<SiteProfileSettingSummary> => {
      const value = await deps.readSetting({ namespace, key });
      if (value === null) return { namespace, key, configured: false, value: null };
      const serialized = JSON.stringify(value) ?? "";
      if (serialized.length > MAX_SETTING_VALUE_CHARS) {
        return { namespace, key, configured: true, value: null, truncated: true };
      }
      return { namespace, key, configured: true, value };
    }),
  );
  return rows.some((row) => row.truncated) ? { data: rows, truncated: true } : { data: rows };
}

/**
 * Collects the `contentTypes` section: every non-tombstoned content type, as key/label/status/
 * version plus a field COUNT.
 *
 * Field definitions themselves are omitted: a content type's full field list is a schema document
 * an agent asks for through the `collections_*` tools when it actually needs it, and inlining every
 * field of every type would be the same context bomb the `pages` cap exists to prevent.
 *
 * @param deps - Supplies `listContentTypes()`.
 * @returns One row per live content type.
 * @throws Whatever `listContentTypes()` throws.
 * @complexity O(C) in the registered content-type count.
 * @example await collectContentTypes(deps);
 */
async function collectContentTypes(deps: SiteProfileDeps): Promise<CollectedSection<SiteProfileContentTypeSummary[]>> {
  const rows = await deps.listContentTypes();
  return {
    data: rows
      .filter((row) => row.tombstonedAt === undefined || row.tombstonedAt === null)
      .map((row) => ({
        key: row.key,
        label: row.label,
        status: row.status,
        version: row.version,
        fieldCount: row.fields.length,
      })),
  };
}

/** Clamps a caller-supplied page limit into `[1, MAX_PAGE_ITEMS]`, defaulting when absent.
 *  Non-integers and out-of-range values fall back to the default rather than propagating into a
 *  `slice()` that would silently return nothing. */
function resolvePageLimit(requested: number | undefined): number {
  if (requested === undefined || !Number.isInteger(requested) || requested < 1) return DEFAULT_PAGE_ITEMS;
  return Math.min(requested, MAX_PAGE_ITEMS);
}

/**
 * Builds the site profile: every requested section, each authorized against its own domain
 * permission and collected concurrently.
 *
 * Sections run in parallel (`Promise.all` over at most 5 entries) because they share no state and a
 * serial fan-out would multiply the slowest read by five for no benefit. No section can fail the
 * call: {@link authorizeAndCollect} converts every denial and every throw into a status on that
 * section alone.
 *
 * @param deps - The narrow read ports (see {@link SiteProfileDeps} — this is where the
 * secret-safety claim is checkable).
 * @param input.principalId - The principal every section's `authorize()` call is made for.
 * @param options.sections - Which sections to collect. Omitted/empty means all of them.
 * @param options.pageLimit - Page rows to include, clamped to `[1, MAX_PAGE_ITEMS]`.
 * @param options.sectionTimeoutMs - Per-section wall clock, default {@link DEFAULT_SECTION_TIMEOUT_MS}.
 * @returns A {@link SiteProfile}. `completeness` is `partial` when any requested section is not
 * `ok`. Never rejects for a section-level failure; only a caller-side wiring error (a missing dep)
 * can reject.
 * @complexity O(N + T + P + A + C + S) — one read per section, run concurrently; `N` (posts)
 * dominates on a large site.
 * @example
 * const profile = await buildSiteProfile(deps, { principalId: "p-1" }, { sections: ["theme", "settings"] });
 */
export async function buildSiteProfile(
  deps: SiteProfileDeps,
  input: { principalId: string },
  options: BuildSiteProfileOptions = {},
): Promise<SiteProfile> {
  const capturedAt = deps.clock.nowIso();
  // Key order follows the closed vocabulary, however the caller ordered or repeated `sections`.
  const requested = resolveRequestedSections({ vocabulary: SITE_PROFILE_SECTION_NAMES, requested: options.sections });
  const pageLimit = resolvePageLimit(options.pageLimit);
  const timeoutMs = options.sectionTimeoutMs ?? DEFAULT_SECTION_TIMEOUT_MS;
  const principalId = input.principalId;

  const collectors: Record<SiteProfileSectionName, () => Promise<SiteProfileSection<unknown>>> = {
    pages: () =>
      authorizeAndCollect(deps, { principalId, section: "pages", timeoutMs, collect: () => collectPages(deps, pageLimit) }),
    theme: () => authorizeAndCollect(deps, { principalId, section: "theme", timeoutMs, collect: () => collectTheme(deps) }),
    plugins: () =>
      authorizeAndCollect(deps, { principalId, section: "plugins", timeoutMs, collect: () => collectPlugins(deps) }),
    settings: () =>
      authorizeAndCollect(deps, { principalId, section: "settings", timeoutMs, collect: () => collectSettings(deps) }),
    contentTypes: () =>
      authorizeAndCollect(deps, {
        principalId,
        section: "contentTypes",
        timeoutMs,
        collect: () => collectContentTypes(deps),
      }),
  };

  const results = await Promise.all(requested.map(async (name) => [name, await collectors[name]()] as const));

  const sections: SiteProfile["sections"] = {};
  for (const [name, section] of results) {
    // The collector map is keyed by the same closed vocabulary the response shape is, so this
    // assignment is exhaustive by construction; the cast only tells the compiler that a section's
    // payload type matches its own key, which the map above already guarantees.
    (sections as Record<string, SiteProfileSection<unknown>>)[name] = section;
  }

  return {
    schemaVersion: "1",
    capturedAt,
    completeness: results.every(([, section]) => section.status === "ok") ? "complete" : "partial",
    sections,
  };
}

/**
 * @file The site-search indexer's bookkeeping on the content database (migration 0027): one Kysely
 * body for SQLite, PGlite and Postgres, behind `@jini-ai/search`'s `SearchIndexStatePort` and
 * `SearchTargetPort`. No search logic here: the generic indexer decides, this only stores.
 *
 * The two ports are returned as two objects because both name a `get` with different inputs.
 */
import { sql } from "kysely";

import type { StorageKernel } from "#src/platform/db/kernel/port";
import { encodeSearchKey } from "@jini-ai/search";
import type {
  SearchIndexStatePort, SearchIndexStateRow, SearchIndexStatus, SearchSiteTargets,
  SearchStatusCounts, SearchTarget, SearchTargetPort,
} from "@jini-ai/search";

/** Numbers stored as `bigint` come back as a number (SQLite), a string or a bigint (Postgres drivers). */
type Big = number | string | bigint;

interface StateTable {
  site_id: string; provider_id: string; generation: number; doc_key: string;
  workspace_id: string; collection: string; document_id: string;
  revision: Big; deleted: number; status: string; attempts: number;
  task_id: string | null; last_error: string | null; updated_at_ms: Big;
}
interface WatermarkTable { site_id: string; provider_id: string; generation: number; collection: string; cursor: string | null; done: number }
interface RetiredTable { site_id: string; provider_id: string; generation: number; retired_at_ms: Big }
interface TargetTable {
  site_id: string; active_provider_id: string | null; active_generation: number | null;
  building_provider_id: string | null; building_generation: number | null; updated_at_ms: Big;
}

/** The three tables 0027 owns, plus 0028's retired generations. They are raw-SQL managed (no Drizzle
 *  declaration), so the generated `ContentDatabase` type never holds them; this local shape is what
 *  the queries are typed against. */
export interface SearchIndexDatabase {
  search_index_state: StateTable;
  search_index_watermarks: WatermarkTable;
  search_index_targets: TargetTable;
  search_index_retired: RetiredTable;
}

export interface SqlSearchIndexStore {
  readonly indexState: SearchIndexStatePort;
  readonly targets: SearchTargetPort;
}

const STATUSES: readonly SearchIndexStatus[] = ["pending", "indexed", "unknown", "failed"];

/** Row → port shape; optional fields are omitted rather than `undefined`. @complexity O(1). */
function toStateRow(row: StateTable): SearchIndexStateRow {
  return {
    target: { siteId: row.site_id, providerId: row.provider_id, generation: Number(row.generation) },
    key: { siteId: row.site_id, workspaceId: row.workspace_id, collection: row.collection, documentId: row.document_id },
    revision: Number(row.revision),
    deleted: Number(row.deleted) === 1,
    status: row.status as SearchIndexStatus,
    attempts: Number(row.attempts),
    ...(row.task_id === null ? {} : { taskId: row.task_id }),
    ...(row.last_error === null ? {} : { lastError: row.last_error }),
    updatedAtMs: Number(row.updated_at_ms),
  };
}

/** Port row → columns. The key's own `siteId` is the target's (one site per target). @complexity O(key length). */
function toStateColumns(row: SearchIndexStateRow): StateTable {
  return {
    site_id: row.target.siteId, provider_id: row.target.providerId, generation: row.target.generation,
    doc_key: encodeSearchKey({ key: row.key }),
    workspace_id: row.key.workspaceId, collection: row.key.collection, document_id: row.key.documentId,
    revision: row.revision, deleted: row.deleted ? 1 : 0, status: row.status, attempts: row.attempts,
    task_id: row.taskId ?? null, last_error: row.lastError ?? null, updated_at_ms: row.updatedAtMs,
  };
}

/** A stored pointer pair, or `null` when that half is empty (the CHECK keeps both columns in step). */
function toTarget(siteId: string, providerId: string | null, generation: number | null): SearchTarget | null {
  return providerId === null || generation === null ? null : { siteId, providerId, generation: Number(generation) };
}

/** The bookkeeping half. @complexity each method is one indexed statement (deleteTarget: two). */
function createIndexState(kernel: StorageKernel<SearchIndexDatabase>): SearchIndexStatePort {
  const scoped = (target: SearchTarget) => ({ site_id: target.siteId, provider_id: target.providerId, generation: target.generation });
  return {
    async get({ target, key }) {
      const row = await kernel.run(db => db.selectFrom("search_index_state").selectAll()
        .where("site_id", "=", target.siteId).where("provider_id", "=", target.providerId)
        .where("generation", "=", target.generation).where("doc_key", "=", encodeSearchKey({ key }))
        .executeTakeFirst());
      return row ? toStateRow(row) : null;
    },
    async put({ row }) {
      const values = toStateColumns(row);
      const { site_id: _s, provider_id: _p, generation: _g, doc_key: _k, ...updatable } = values;
      await kernel.run(db => db.insertInto("search_index_state").values(values)
        .onConflict(oc => oc.columns(["site_id", "provider_id", "generation", "doc_key"]).doUpdateSet(updatable))
        .execute());
    },
    /**
     * Compare-and-swap settle: ONE UPDATE that matches only while the stored row still carries the
     * observed revision and task, so an older write's completion never replaces a newer revision's
     * bookkeeping. @complexity O(1), one primary-key UPDATE.
     */
    async settle({ row, expected }) {
      const values = toStateColumns(row);
      const { site_id: _s, provider_id: _p, generation: _g, doc_key: _k, ...updatable } = values;
      const result = await kernel.run(db => db.updateTable("search_index_state").set(updatable)
        .where("site_id", "=", values.site_id).where("provider_id", "=", values.provider_id)
        .where("generation", "=", values.generation).where("doc_key", "=", values.doc_key)
        .where("revision", "=", expected.revision)
        .where("task_id", expected.taskId === null ? "is" : "=", expected.taskId)
        .executeTakeFirst());
      return Number(result.numUpdatedRows) === 1;
    },
    async listByStatus({ target, statuses, limit }, { failedBelowAttempts } = {}) {
      // `IN ()` is not valid SQL; asking for no status matches no row.
      if (statuses.length === 0) return [];
      const rows = await kernel.run(db => db.selectFrom("search_index_state").selectAll()
        .where("site_id", "=", target.siteId).where("provider_id", "=", target.providerId)
        .where("generation", "=", target.generation).where("status", "in", [...statuses])
        // Exhausted failures leave the candidate set BEFORE the limit, so they cannot starve the rest.
        .$if(failedBelowAttempts !== undefined, qb => qb.where(eb => eb.or([eb("status", "!=", "failed"), eb("attempts", "<", failedBelowAttempts!)])))
        // Oldest first so a retry sweep reaches every row, with the key breaking ties stably.
        .orderBy("updated_at_ms", "asc").orderBy("doc_key", "asc")
        .limit(limit).execute());
      return rows.map(toStateRow);
    },
    async counts({ target }) {
      const rows = await kernel.run(db => db.selectFrom("search_index_state")
        .select(eb => ["status", eb.fn.countAll<Big>().as("n")])
        .where("site_id", "=", target.siteId).where("provider_id", "=", target.providerId)
        .where("generation", "=", target.generation).groupBy("status").execute());
      const counts = Object.fromEntries(STATUSES.map(status => [status, 0])) as Record<SearchIndexStatus, number>;
      for (const row of rows) counts[row.status as SearchIndexStatus] = Number(row.n);
      return counts as SearchStatusCounts;
    },
    async getWatermark({ target, collection }) {
      const row = await kernel.run(db => db.selectFrom("search_index_watermarks").select(["cursor", "done"])
        .where("site_id", "=", target.siteId).where("provider_id", "=", target.providerId)
        .where("generation", "=", target.generation).where("collection", "=", collection)
        .executeTakeFirst());
      if (!row) return null;
      return { ...(row.cursor === null ? {} : { cursor: row.cursor }), done: Number(row.done) === 1 };
    },
    async putWatermark({ target, collection, cursor, done }) {
      const changes = { cursor: cursor ?? null, done: done ? 1 : 0 };
      await kernel.run(db => db.insertInto("search_index_watermarks").values({ ...scoped(target), collection, ...changes })
        .onConflict(oc => oc.columns(["site_id", "provider_id", "generation", "collection"]).doUpdateSet(changes))
        .execute());
    },
    async deleteTarget({ target }) {
      await kernel.transaction(async () => {
        for (const table of ["search_index_state", "search_index_watermarks"] as const) {
          await kernel.run(db => db.deleteFrom(table).where("site_id", "=", target.siteId)
            .where("provider_id", "=", target.providerId).where("generation", "=", target.generation).execute());
        }
      });
    },
  };
}

/**
 * ONE compare-and-swap statement: the building pointer must still be `expected` AND the active
 * pointer still `active` (as just read), so the caller's `replaced` is exactly what this switch
 * displaced. A concurrent promote, rebuild or clear changes one of them first and no row updates.
 * @complexity O(1), one primary-key UPDATE.
 */
async function swapPointers(
  kernel: StorageKernel<SearchIndexDatabase>,
  required: { siteId: string; expected: SearchTarget; active: SearchTarget | null; nowMs: number },
): Promise<boolean> {
  const { siteId, expected, active, nowMs } = required;
  const result = await kernel.run(db => db.updateTable("search_index_targets")
    .set(({ ref }) => ({
      active_provider_id: ref("building_provider_id"), active_generation: ref("building_generation"),
      building_provider_id: null, building_generation: null, updated_at_ms: nowMs,
    }))
    .where("site_id", "=", siteId)
    .where("building_provider_id", "=", expected.providerId).where("building_generation", "=", expected.generation)
    .where(active === null
      ? sql<boolean>`active_provider_id IS NULL`
      : sql<boolean>`active_provider_id = ${active.providerId} AND active_generation = ${active.generation}`)
    .executeTakeFirst());
  return Number(result.numUpdatedRows) === 1;
}

/** The pointer half. `promote` is the atomic generation switch. @complexity O(1) per call. */
function createTargets(kernel: StorageKernel<SearchIndexDatabase>, now: () => number): SearchTargetPort {
  const read = async (siteId: string): Promise<SearchSiteTargets> => {
    const row = await kernel.run(db => db.selectFrom("search_index_targets").selectAll().where("site_id", "=", siteId).executeTakeFirst());
    if (!row) return { active: null, building: null };
    return {
      active: toTarget(siteId, row.active_provider_id, row.active_generation),
      building: toTarget(siteId, row.building_provider_id, row.building_generation),
    };
  };
  return {
    get: ({ siteId }) => read(siteId),
    async setBuilding({ target }) {
      const building = { building_provider_id: target.providerId, building_generation: target.generation, updated_at_ms: now() };
      await kernel.run(db => db.insertInto("search_index_targets")
        .values({ site_id: target.siteId, active_provider_id: null, active_generation: null, ...building })
        .onConflict(oc => oc.column("site_id").doUpdateSet(building)).execute());
    },
    promote: ({ siteId, expected }) => kernel.transaction(async () => {
      const { active } = await read(siteId);
      const swapped = await swapPointers(kernel, { siteId, expected, active, nowMs: now() });
      if (!swapped) return false;
      // Same transaction as the switch: the replaced index is dropped later even if this process dies now.
      if (active !== null) {
        await kernel.run(db => db.insertInto("search_index_retired")
          .values({ site_id: siteId, provider_id: active.providerId, generation: active.generation, retired_at_ms: now() })
          .onConflict(oc => oc.columns(["site_id", "provider_id", "generation"]).doNothing()).execute());
      }
      return { replaced: active };
    }),
    async listRetired({ siteId }) {
      const rows = await kernel.run(db => db.selectFrom("search_index_retired").select(["provider_id", "generation"])
        .where("site_id", "=", siteId).orderBy("retired_at_ms", "asc").orderBy("provider_id", "asc").orderBy("generation", "asc").execute());
      return rows.map(row => ({ siteId, providerId: row.provider_id, generation: Number(row.generation) }));
    },
    async forgetRetired({ target }) {
      await kernel.run(db => db.deleteFrom("search_index_retired").where("site_id", "=", target.siteId)
        .where("provider_id", "=", target.providerId).where("generation", "=", target.generation).execute());
    },
    async clearBuilding({ siteId }) {
      await kernel.run(db => db.updateTable("search_index_targets")
        .set({ building_provider_id: null, building_generation: null, updated_at_ms: now() })
        .where("site_id", "=", siteId).execute());
    },
  };
}

/**
 * The SQL search-index store on one content database.
 * @example const { indexState, targets } = createSqlSearchIndexStore({ kernel, now: clock.nowMs });
 * @complexity O(1) to build; see each half for per-call cost.
 */
export function createSqlSearchIndexStore<DB>(
  required: { readonly kernel: StorageKernel<DB>; readonly now: () => number },
  _optional: Record<string, never> = {},
): SqlSearchIndexStore {
  // The content kernel is typed against the generated schema, which never lists 0027's raw-SQL
  // tables; the same kernel is re-typed for them (Kysely types are compile-time only).
  const kernel = required.kernel as unknown as StorageKernel<SearchIndexDatabase>;
  return { indexState: createIndexState(kernel), targets: createTargets(kernel, required.now) };
}

/**
 * @file When an admin Sites card's preview is (re)captured, and the one-at-a-time queue that does it.
 *
 * Policy, mirroring the desktop's `site-preview-scheduler.ts` and adding the one thing a browser
 * admin needs that the desktop does not (a long-lived server outlives many card views):
 *
 * - **Never on the request path.** {@link SitePreviewService.versions} only reads mtimes and
 *   enqueues; the Sites listing never waits on a capture, and the image route only reads the file.
 * - **Only running sites.** A stopped site has no address; its card shows the last capture.
 * - **Once per live lifecycle**, like the desktop (a restart is a new pid, so a new capture), plus a
 *   refresh when the stored capture is older than `refreshMs` while someone is looking at the
 *   Sites screen — "recent", without a timer running when nobody is.
 * - **One capture at a time, machine-wide for this server**, deduped by site name, and a failed site
 *   waits `retryMs` before it is tried again, so a broken site cannot keep a browser busy.
 * - **A capture older than the site's `createdAt` is ignored**: it belongs to a deleted folder that
 *   had the same name, and must not decorate its replacement.
 *
 * The browser, store, clock and deferral are ports; this module does no I/O itself.
 */
import type { SitePreviewStore } from "./site-preview-store.js";

/** A running site this server can screenshot: its public root URL and an identity for this run. */
export interface SitePreviewTarget {
  name: string;
  /** The site's PUBLIC root, always a loopback URL this server built — never caller-supplied. */
  url: string;
  /** Changes on every restart (a pid), so a new run gets one fresh capture. */
  lifecycle: string;
}

export interface SitePreviewCapturePort {
  /** The resized image bytes, or `null` on any failure. Must not throw. */
  capture(required: { url: string }, optional?: {}): Promise<Buffer | null>;
  /** Release the browser once the queue drains, so no Chromium idles between card views. */
  close(required?: {}, optional?: {}): Promise<void>;
}

export interface SitePreviewService {
  /**
   * Version tokens for every listed site that has a usable capture, and enqueue whichever running
   * targets are due. Returns immediately.
   */
  versions(required: { sites: readonly { name: string; createdAt: string }[]; targets: readonly SitePreviewTarget[] }, optional?: {}): Record<string, number>;
  read(required: { name: string }, optional?: {}): Buffer | null;
  /** Resolves once the queue is empty — for tests and shutdown, never awaited by a route. */
  idle(required?: {}, optional?: {}): Promise<void>;
}

export interface SitePreviewServiceOptions {
  now?: () => number;
  /** A stored capture older than this is refreshed while the Sites screen is being viewed. */
  refreshMs?: number;
  /** A site whose capture failed is not retried sooner than this. */
  retryMs?: number;
  /** Runs the drain off the caller's stack (`setImmediate` in production). */
  defer?: (work: () => void) => void;
}

const MINUTE_MS = 60_000;

/**
 * @complexity `versions` is O(s + t·q) for s sites, t targets and a queue of at most t entries
 *   (t ≤ the local-site limit + 1, so in practice a handful); the drain is one capture at a time.
 */
export function createSitePreviewService(
  { store, capture }: { store: SitePreviewStore; capture: SitePreviewCapturePort },
  { now = Date.now, refreshMs = 30 * MINUTE_MS, retryMs = 5 * MINUTE_MS, defer = (work) => { setImmediate(work); } }: SitePreviewServiceOptions = {},
): SitePreviewService {
  const capturedLifecycle = new Map<string, string>();
  const failedAt = new Map<string, number>();
  const queue: SitePreviewTarget[] = [];
  let active: string | null = null;
  let drain: Promise<void> = Promise.resolve();

  /** A capture made before this folder existed belongs to a deleted namesake. */
  function usableVersion(name: string, createdAt: string): number | null {
    const version = store.version({ name });
    const created = Date.parse(createdAt);
    return version !== null && !(created > version) ? version : null;
  }

  function isDue(target: SitePreviewTarget, version: number | null): boolean {
    if (active === target.name || queue.some((queued) => queued.name === target.name)) return false;
    const failed = failedAt.get(target.name);
    if (failed !== undefined && now() - failed < retryMs) return false;
    if (version === null || capturedLifecycle.get(target.name) !== target.lifecycle) return true;
    return now() - version >= refreshMs;
  }

  async function runQueue(): Promise<void> {
    try {
      for (let target = queue.shift(); target !== undefined; target = queue.shift()) {
        active = target.name;
        const bytes = await capture.capture({ url: target.url });
        const written = bytes === null ? null : store.write({ name: target.name, bytes });
        if (written === null) {
          failedAt.set(target.name, now());
        } else {
          failedAt.delete(target.name);
          capturedLifecycle.set(target.name, target.lifecycle);
        }
      }
    } finally {
      active = null;
      await capture.close();
    }
  }

  function enqueue(target: SitePreviewTarget): void {
    const wasIdle = queue.length === 0 && active === null;
    queue.push(target);
    if (!wasIdle) return;
    drain = new Promise<void>((resolve) => {
      defer(() => { void runQueue().catch(() => {}).finally(resolve); });
    });
  }

  return {
    versions({ sites, targets }) {
      const result: Record<string, number> = {};
      const createdAtByName = new Map(sites.map((site) => [site.name, site.createdAt]));
      for (const site of sites) {
        const version = usableVersion(site.name, site.createdAt);
        if (version !== null) result[site.name] = version;
      }
      for (const target of targets) {
        if (!createdAtByName.has(target.name)) continue;
        if (isDue(target, result[target.name] ?? null)) enqueue(target);
      }
      return result;
    },
    read({ name }) {
      return store.read({ name });
    },
    idle() {
      return drain;
    },
  };
}

import { toolMetadata } from '../../contracts/core/tool-metadata/skills.js';
import { adaptLegacyAuthorize, requireToolPermission, type AuthorizeFn } from "@jini-ai/cms/core";
import {
  buildDomainRegistrations,
  indexCatalogById,
  requireInputRecord,
  ToolInputError,
  type AgentToolDefinition,
  type DerivedRiskByToolId,
  type ToolRegistration,
} from "@jini-ai/core";

import type { ToolContributor } from "#src/assistant/index";
import { commitSkillInstall, listManagedSkills, prepareSkillInstall, SkillInputError } from "./install-service.js";

/**
 * @file `skills_install` — installs a standalone Agent Skill from a public GitHub URL, through the
 * SAME `install-service.ts` the admin Skills screen's "Add from GitHub" calls (`routes/skills/
 * manage.ts` -> `installSkill`, which is `prepareSkillInstall` + `commitSkillInstall`). Same
 * `admin.assistant.use` permission as that route.
 *
 * It fetches and validates first, then writes exactly those validated bytes (one fetch, pinned to one
 * commit). No confirmation card (owner 2026-10-07: ordinary installs run directly; trash/delete/publish ask; it shipped with
 * one in 444e9dfca and was dropped the same day) — the admin screen's own dialog is unchanged. Uploaded folders/ZIPs
 * are not a source here: the admin chat composer already installs a dropped skill through the Skills
 * screen's own upload path.
 */

export interface SkillsInstallToolDeps {
  readonly workspaceId: string;
  readonly skillLayout: import("./layout.js").SkillLayout;
  readonly siteBinding: { readonly dir: string };
  readonly authorize: AuthorizeFn;
  /** Test seam for the GitHub fetch; defaults to global `fetch` inside the service. */
  readonly skillFetch?: typeof fetch;
}

export const SKILLS_INSTALL_TOOL_ID = "skills_install";

export const catalog: AgentToolDefinition[] = [{
  name: SKILLS_INSTALL_TOOL_ID,
  description:
    "Installs a standalone Agent Skill (a folder with SKILL.md) from a public GitHub URL into this workspace. Use when the user asks to " +
    "install or add a skill from GitHub. The skill is fetched from api.github.com at one pinned commit and validated before anything is " +
    "written; the result names the skill, its source and commit. The installed skill is ON and becomes its own skill_<name> tool, found by search_tools. Refused if a skill with that name is " +
    "already installed. Installation runs no code. Does not install plugins, Agent Plugins or themes, and does not take local files.",
  sideEffects: "mutates-durable-state",
  authorization: { permission: "admin.assistant.use" },
  inputSchema: {
    type: "object",
    additionalProperties: false,
    required: ["githubUrl"],
    properties: {
      githubUrl: {
        type: "string",
        minLength: 1,
        description: "HTTPS github.com repository URL, optionally ending in /tree/<ref>/<skill-folder>, e.g. https://github.com/owner/repo/tree/main/skills/my-skill.",
      },
    },
  },
}];

export const derivedRisk: DerivedRiskByToolId = new Map([
  // -> prepareSkillInstall (GitHub fetch, read-only) then commitSkillInstall: writes the skill folder
  //    under <site>/skills/ws/<workspaceId>/. Durable file writes; no code runs. The admin Skills
  //    screen's Remove is the inverse.
  [SKILLS_INSTALL_TOOL_ID, "mutates-durable-state"],
]);

/** Service refusals are input problems the model can relay; anything else propagates. */
async function asToolInput<T>(work: () => Promise<T>): Promise<T> {
  try { return await work(); }
  catch (error) { if (error instanceof SkillInputError) throw new ToolInputError({ message: error.message }); throw error; }
}

/**
 * Order: authorize -> parse -> fetch+validate -> already-installed check -> write.
 * @complexity O(skill files + bytes).
 */
export function buildRegistrations(deps: SkillsInstallToolDeps): ToolRegistration[] {
  return buildDomainRegistrations({ metadata: toolMetadata,
    domain: "skills-install",
    catalogModule: "features/skills/install-tool.ts",
    catalog: indexCatalogById({ catalog }),
    derivedRisk,
    handlers: {
      [SKILLS_INSTALL_TOOL_ID]: async (ctx) => {
        await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "admin.assistant.use" }, { entityType: "skill" });
        const input = requireInputRecord({ input: ctx.input });
        if (typeof input.githubUrl !== "string" || !input.githubUrl.trim() || Object.keys(input).some((key) => key !== "githubUrl")) {
          throw new ToolInputError({ message: "githubUrl (an https://github.com/... URL) is the only, required argument." });
        }
        const githubUrl = input.githubUrl.trim();
        const prepared = await asToolInput(() => prepareSkillInstall({ workspaceId: deps.workspaceId, githubUrl }, deps.skillFetch ? { fetchImpl: deps.skillFetch } : {}));
        if ((await listManagedSkills(deps)).some((skill) => skill.toolId === prepared.toolId)) {
          throw new ToolInputError({ message: `Skill '${prepared.name}' is already installed. Remove it from the Skills screen before installing another version.` });
        }
        const skill = await asToolInput(() => commitSkillInstall({ ...deps, workspaceId: deps.workspaceId, prepared }));
        return { installed: true, skill, note: `Installed the ${skill.name} skill; it is on. Its tool ${skill.toolId} is picked up by the next search_tools call.` };
      },
    },
  });
}

/** Contributes `skills_install` as its own domain. */
export function contributeSkillsInstallTools(): ToolContributor {
  return { domain: "skills-install", build: buildRegistrations, risk: derivedRisk };
}

import { toolMetadata } from '../../contracts/core/tool-metadata/skills.js';
import { withExtensionApprovalPolicy } from '../../contracts/headless/assistant-tool-approval-policy.js';
import * as filesystem from "node:fs/promises";
import { readFile, readdir } from "node:fs/promises";
import { createSkillFileReader, type SkillFileReader } from "@jini-ai/agent-plugins/lifecycle";
import path from "node:path";

import { buildDomainRegistrations, indexCatalogById, requireInputRecord, optionalString, type AgentToolSideEffect, type DerivedRiskByToolId, type ToolHandler, type ToolRegistration, type AgentToolDefinition } from "@jini-ai/core";

import { readFrontmatterField } from "#src/platform/markdown/frontmatter";

import { createLiveSkillRegistration, type SkillsRefreshRegistry } from "./live-registration.js";
import { readSkillState } from "./state.js";
import type { SkillLayout } from "./layout.js";

/**
 * @file Registers every installed standalone Agent Skill (`<site>/skills/ws/<workspaceId>/<dir>/
 * SKILL.md`) as ONE real tool in the `ToolRegistry` — the standalone-skill counterpart to
 * `src/features/agent-plugins/tool-registrations.ts`, structurally mirrored but deliberately NOT
 * built on top of it (owner decision, verbatim: "they are different things. there should be a
 * skills/ and a separate agent-plugins/ directory").
 *
 * ---------------------------------------------------------------------------
 * A Skill is not a Plugin — why that difference reaches this file
 * ---------------------------------------------------------------------------
 * Per the Agent Skills spec (agentskills.io): a skill is a folder — `SKILL.md` with YAML frontmatter
 * (at minimum `name` and `description`), then instructions, plus optional `references/`, `scripts/`,
 * `assets/`. "A single skill doesn't require a plugin wrapper." Loading is PROGRESSIVE DISCLOSURE:
 * discovery sees only `name`/`description`; the full body is read only once the task actually
 * matches. An Agent Plugin (agent-plugins.org, `src/features/agent-plugins/`) is a PACKAGE that
 * bundles multiple skills plus `mcp.json` plus client config — already implemented, and this file
 * does not modify it. Because a standalone skill is already the atomic unit (unlike a plugin, which
 * may bundle several skills under one id), this file is simpler than its agent-plugin counterpart in
 * one structural way worth naming up front: there is no "combined description across many skills" and
 * no optional `skill` argument to pick among them — one skill folder is one tool, full stop.
 *
 * ---------------------------------------------------------------------------
 * Tool id scheme: `skill_<sanitized name>`
 * ---------------------------------------------------------------------------
 * `agent-plugins/tool-registrations.ts`'s own header records that an earlier revision of THAT file
 * used `skill_<pluginId>` and that this was a category error the product owner caught — an Agent
 * Plugin is a packaging paradigm, not itself a skill. That same header explicitly names the
 * consequence: "`skill_` was wrong the moment this file started minting one tool per INSTALLED
 * PLUGIN... and it burned a prefix real standalone skill tools will need later." This file is that
 * later use. `plugin_` is not available either — it collides with the existing native
 * `plugins_list`/`plugins_set_enabled` tools (`features/plugin-runtime/`, an unrelated "plugin"
 * concept). `skill_` is free and is exactly the reserved prefix this feature claims.
 *
 * ---------------------------------------------------------------------------
 * Tool description = the skill's own frontmatter `description`, VERBATIM
 * ---------------------------------------------------------------------------
 * That is the whole point of progressive disclosure: `search_tools`' discovery pass must see what the
 * skill's own author wrote as the trigger condition ("Use when handling production incidents..."),
 * not a wrapper sentence this module invents. No combining, no humanizing, no folding in other
 * fields — unlike the agent-plugin tool's `buildPluginToolDescription`, which has to fold several
 * skills' vocabulary into one description because several skills share one tool there. Here, one
 * skill is one tool, so its own description already IS the correct indexed text.
 *
 * ---------------------------------------------------------------------------
 * The handler's output: full `SKILL.md` body, plus a pointer to the rest — never inlined
 * ---------------------------------------------------------------------------
 * A skill's optional `references/`, `scripts/`, `assets/` files are the second stage of progressive
 * disclosure: read only once the agent is actually doing the task and needs more than the top-level
 * instructions. Inlining their contents into every tool call would defeat that (and, for a skill like
 * this feature's own installed `incident-response` fixture, balloon a call that usually only needs
 * the top-level workflow). The handler instead returns each bundled file's path so the caller can
 * request it with this tool's optional `file` argument (Jini's shared skill-file reader) — the same
 * "list paths, do not inline" progressive disclosure run-start injection uses.
 *
 * Bundled files use `{ root: "site", path }` for direct fs_read_file calls. Files outside
 * the active site (an operator override) are omitted rather than advertising unreadable paths.
 *
 * ---------------------------------------------------------------------------
 * Bad-folder isolation: skip and warn, never throw — except for one real ambiguity
 * ---------------------------------------------------------------------------
 * A skill folder with no `SKILL.md`, or with frontmatter missing `name`/`description`, is skipped
 * with a `console.warn` naming the folder — never fatal to every OTHER folder in the same workspace,
 * mirroring `listInstalledPlugins`'s own per-digest failure isolation. The one case this file DOES
 * throw on on a valid-looking installed set is two DIFFERENT skill folders whose frontmatter `name`
 * collides (so both would mint the identical tool id) — not covered by the "skip a bad folder" rule
 * above, because neither folder is individually bad. This mirrors
 * `loadInstalledAgentPluginToolSources`'s own multi-digest ambiguity guard and the same
 * `resolveOnePluginRef` "more than one match" rule: silently registering only one of the two (e.g.
 * "whichever `readdir` returned first") would be a worse failure than a loud, actionable error,
 * because nothing about the resulting tool call would look wrong until someone noticed it always
 * answered from the folder they did not mean.
 *
 * Architectural role:
 * `loadInstalledSkillToolSources` is the only disk-reading half; `buildSkillToolRegistrations` is
 * pure and synchronous so a unit test exercises the registration/schema/handler shape without a real
 * filesystem, matching the same split `agent-plugins/tool-registrations.ts` keeps.
 */

/** One parsed skill's required frontmatter fields — `name` and `description` per the Agent Skills
 *  spec's stated minimum. Anything else a skill's frontmatter carries (`version`, `last_updated`,
 *  `allowed-tools`, ...) is not this loader's concern. */
interface SkillFrontmatter {
  readonly name: string;
  readonly description: string;
}

/**
 * Extracts `name:` and `description:` from a `SKILL.md`'s YAML frontmatter block, via the shared
 * {@link readFrontmatterField} (a real YAML parse of the isolated block, falling back to a single-line
 * regex only when that block isn't valid YAML — see that module's header for why: a folded/literal
 * block scalar `description:` value needs a real parse to resolve, not a regex over its marker line).
 *
 * @returns `undefined` when the file has no frontmatter block, or the block is missing either
 * required field — the caller treats that as "skip this folder" (see this file's header), never a
 * thrown error.
 * @complexity O(n) in the frontmatter block's own length.
 */
function parseSkillFrontmatter(markdown: string): SkillFrontmatter | undefined {
  const name = readFrontmatterField(markdown, "name");
  const description = readFrontmatterField(markdown, "description");
  if (!name || !description) return undefined;

  return { name, description };
}

/** `skill_<sanitized name>` — see this file's header, "Tool id scheme", for why `skill_` is the
 *  correct, reserved prefix. Sanitizes more aggressively than `agent-plugins/tool-registrations.ts`'s
 *  own `toAgentPluginToolId` (which only folds hyphens): a skill's `name` frontmatter field is
 *  free-form author-supplied text, not a value already constrained by the Agent Plugins manifest name
 *  grammar, so every run of characters outside `[a-z0-9]` collapses to one underscore and any
 *  leading/trailing underscore is trimmed — the id stays a legal, predictable identifier regardless
 *  of what an author wrote.
 *  @returns `undefined` when sanitizing leaves nothing usable (e.g. a name made entirely of symbols)
 *  — the caller treats that the same as unparseable frontmatter: skip and warn. */
function toSkillToolId(name: string): string | undefined {
  const sanitized = name
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
  return sanitized.length > 0 ? `skill_${sanitized}` : undefined;
}

/** The three optional bundled-content subdirectories the Agent Skills spec names. Order here is also
 *  the order {@link listBundledFiles} walks them in. */
const BUNDLED_SUBDIRS = ["references", "scripts", "assets"] as const;
type SkillBundledFileKind = (typeof BUNDLED_SUBDIRS)[number];

/** One bundled file, with a path relative to the active site for fs_read_file. */
export interface SkillBundledFile {
  readonly kind: SkillBundledFileKind;
  readonly path: string;
}

/**
 * Recursively lists every file under one skill's `references/`, `scripts/`, and `assets/`
 * subdirectories — whichever exist. A missing subdirectory contributes nothing and is never an
 * error: the Agent Skills spec marks all three optional, and the reference `incident-response`
 * fixture this feature installs has only `references/`.
 *
 * @complexity O(f) in the total file count under the three subdirectories.
 */
async function listBundledFiles(input: { skillDir: string; siteDir: string }, _options = {}): Promise<readonly SkillBundledFile[]> {
  const files: SkillBundledFile[] = [];
  for (const kind of BUNDLED_SUBDIRS) {
    await walkFiles(path.join(input.skillDir, kind), (absolutePath) => {
      const relative = path.relative(input.siteDir, absolutePath).split(path.sep).join("/");
      if (relative && !relative.startsWith("../") && !path.isAbsolute(relative)) files.push({ kind, path: relative });
    });
  }
  return files;
}

/** One directory's worth of recursion for {@link listBundledFiles}. A missing `dir` (the common case
 *  — most skills do not bundle all three subdirectories) is silently a no-op, not an error. Entries
 *  are visited in sorted order so the resulting file list is deterministic across filesystems. */
async function walkFiles(dir: string, onFile: (absolutePath: string) => void): Promise<void> {
  let entries;
  try {
    entries = await readdir(dir, { withFileTypes: true });
  } catch (error) {
    if (isEnoent(error)) return;
    throw error;
  }
  for (const entry of [...entries].sort((a, b) => a.name.localeCompare(b.name))) {
    const entryPath = path.join(dir, entry.name);
    if (entry.isDirectory()) await walkFiles(entryPath, onFile);
    else if (entry.isFile()) onFile(entryPath);
  }
}

function isEnoent(error: unknown): boolean {
  return typeof error === "object" && error !== null && "code" in error && (error as { code?: unknown }).code === "ENOENT";
}

/** One installed standalone Agent Skill, fully resolved into a single tool-ready source. */
export interface SkillToolSource {
  readonly id: string;
  /** The skill's own frontmatter `name`, unsanitized — carried through for handler output and error
   *  messages; {@link id} is the sanitized, tool-safe derivative of this value. */
  readonly skillName: string;
  /** The skill's own frontmatter `description`, verbatim — see this file's header. */
  readonly description: string;
  /** The full `SKILL.md` file content, frontmatter included — the same "handler returns the exact
   *  file" precedent `agent-plugins/tool-registrations.ts`'s handler already establishes. */
  readonly markdown: string;
  readonly bundledFiles: readonly SkillBundledFile[];
  /** Deferred reader keeps the host path private while all assistant surfaces can load references. */
  readonly readFile?: SkillFileReader["read"];
  readonly directory?: string;
}

/** Human-readable reason a skill folder's `SKILL.md` could not be read — split out of
 *  {@link resolveSkillEntry} so its nested "missing vs. unreadable" ternary lives in its own function
 *  rather than adding two nested-ternary steps to that function's own complexity count. */
function describeSkillMdReadFailure(error: unknown): string {
  if (isEnoent(error)) return "no SKILL.md";
  return `SKILL.md could not be read (${error instanceof Error ? error.message : String(error)})`;
}

/** One entry-resolution outcome: `"skip"` covers every tolerated case this loader's header documents
 *  under "Bad-folder isolation" (not a directory, missing/unreadable SKILL.md, unparseable
 *  frontmatter, unusable id) — only `"resolved"` contributes to the loaded source list. */
type SkillEntryResolution = { readonly kind: "skip" } | { readonly kind: "resolved"; readonly source: SkillToolSource };

/**
 * Resolves one workspace-root directory entry into a ready {@link SkillToolSource}, or a `"skip"`
 * outcome for every tolerated failure — pulled out of {@link loadInstalledSkillToolSources} so that
 * function's own loop body is a flat dispatch on the result instead of nested try/catch and
 * early-continue branches for each entry.
 *
 * @param input.seenDirById - Mutated in place: records `id -> folder name` for every entry this call
 * resolves, so the caller's next call (for the next entry) can detect a same-id collision.
 * @throws {Error} Only for the one non-tolerated case: `frontmatter.name` sanitizes to an `id` already
 * present in `seenDirById` — see this file's header, "Bad-folder isolation".
 * @complexity O(f) in the entry's own bundled-file count (from {@link listBundledFiles}).
 */
async function resolveSkillEntry(input: {
  readonly workspaceRoot: string;
  readonly siteDir: string;
  readonly entry: { readonly name: string; isDirectory: () => boolean };
  readonly seenDirById: Map<string, string>;
  readonly includeDisabled?: boolean;
}): Promise<SkillEntryResolution> {
  const { workspaceRoot, entry, seenDirById } = input;
  if (!entry.isDirectory()) return { kind: "skip" };
  const skillDir = path.join(workspaceRoot, entry.name);
  if (!(await readSkillState(skillDir)).enabled && !input.includeDisabled) return { kind: "skip" };

  let markdown: string;
  try {
    markdown = await readFile(path.join(skillDir, "SKILL.md"), "utf8");
  } catch (error) {
    console.warn(`[skills] '${entry.name}': ${describeSkillMdReadFailure(error)} — skipped`);
    return { kind: "skip" };
  }

  const frontmatter = parseSkillFrontmatter(markdown);
  if (!frontmatter) {
    console.warn(`[skills] '${entry.name}': SKILL.md has no parseable frontmatter with both 'name' and 'description' — skipped`);
    return { kind: "skip" };
  }

  const id = toSkillToolId(frontmatter.name);
  if (!id) {
    console.warn(`[skills] '${entry.name}': frontmatter name '${frontmatter.name}' could not be turned into a valid tool id — skipped`);
    return { kind: "skip" };
  }

  const priorDir = seenDirById.get(id);
  if (priorDir !== undefined) {
    throw new Error(
      `skills: '${frontmatter.name}' is declared by more than one installed skill folder ('${priorDir}' and '${entry.name}') — ` +
        `both would register the same tool id '${id}'; rename one skill's frontmatter 'name' to disambiguate`,
    );
  }
  seenDirById.set(id, entry.name);

  return {
    kind: "resolved",
    source: { directory: entry.name, id, skillName: frontmatter.name, description: frontmatter.description, markdown, readFile: createSkillFileReader({ skillRoot: skillDir, filesystem }).read, bundledFiles: await listBundledFiles({ skillDir, siteDir: input.siteDir }) },
  };
}

/**
 * Loads every installed standalone Agent Skill for one workspace, resolved into one tool-ready
 * source per skill folder.
 *
 * @throws {Error} If two installed skill folders declare the same frontmatter `name` — see
 * {@link resolveSkillEntry}.
 * @complexity O(d * f) in installed skill-folder count times average bundled-file count per skill.
 */
export async function loadInstalledSkillToolSources(ctx: {
  readonly includeDisabled?: boolean;
  readonly workspaceId: string;
  readonly skillLayout: SkillLayout;
  readonly siteBinding: { readonly dir: string };
}, _optional = {}): Promise<readonly SkillToolSource[]> {
  const workspaceRoot = ctx.skillLayout.forWorkspace(ctx.workspaceId).root;

  let entries;
  try {
    entries = await readdir(workspaceRoot, { withFileTypes: true });
  } catch (error) {
    if (isEnoent(error)) return [];
    throw error;
  }

  const sources: SkillToolSource[] = [];
  const seenDirById = new Map<string, string>();
  for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
    const resolution = await resolveSkillEntry({ siteDir: ctx.siteBinding.dir, workspaceRoot, entry, seenDirById, includeDisabled: ctx.includeDisabled });
    if (resolution.kind === "resolved") sources.push(resolution.source);
  }

  return sources;
}

/** This module's own risk classification: every skill tool is a pure read of already-installed,
 *  operator-trusted local content — no domain call, no write path, mirroring
 *  `agent-plugins/tool-registrations.ts`'s identical `"none"` classification for the same reason. */
export function skillToolDerivedRisk(sources: readonly SkillToolSource[]): DerivedRiskByToolId {
  return new Map<string, AgentToolSideEffect>(sources.map((source) => [source.id, "none"]));
}

/** Optional file only — one skill is one tool, so no `skill` argument selects siblings.
 *  The file schema documents progressive disclosure through this tool's shared reader. */
const SKILL_INPUT_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: [],
  properties: { file: { type: "string", description: "Optional supporting text file relative to this skill folder, e.g. references/guide.md. Omit to read SKILL.md. Responses list readable files; unknown, unsafe, binary or over-256-KiB requests return a note and valid files." } },
} as const;

/** Formats standalone-skill guidance while retaining cached instructions when a file is refused. */
function buildSkillToolResult({ source, content, file }: {
  readonly source: SkillToolSource;
  readonly content: Awaited<ReturnType<SkillFileReader["read"]>> | undefined;
  readonly file: string | undefined;
}, _options = {}) {
  const result: Awaited<ReturnType<SkillFileReader["read"]>> = content ?? { text: source.markdown, files: [] };
  return {
    skillName: source.skillName,
    guidance: result.note && !result.text ? source.markdown : result.text,
    files: result.files ?? [],
    ...(result.note ? { note: result.note } : {}),
    ...(file !== undefined && !source.readFile ? { note: "File request refused: no supporting-file reader is available. Valid supporting files: (none)." } : {}),
    bundledFiles: source.bundledFiles.map((file) => ({ kind: file.kind, root: "site", path: file.path })),
  };
}

/**
 * Turns already-resolved skill sources into real `ToolRegistration`s — pure and synchronous, unlike
 * {@link loadInstalledSkillToolSources}, so this is the half a unit test exercises without touching
 * disk. Uses the SAME `buildDomainRegistrations` gate every other domain's `tool-registrations.ts`
 * uses (catalog/risk cross-check, `inputSchema` presence, drift tripwire) — not a parallel mechanism.
 * Handlers reject non-object inputs and keys other than `file` before invoking the injected reader.
 * @throws Error when a handler receives invalid input; reader errors propagate unchanged.
 * @complexity O(s) registration time/space for s sources; a handler validates O(k) keys before one read.
 */
export function buildSkillToolRegistrations(sources: readonly SkillToolSource[]): ToolRegistration[] {
  const catalog: AgentToolDefinition[] = sources.map((source) => ({
    name: source.id,
    description: source.description,
    sideEffects: "none",
    authorization: { permission: "admin.assistant.use" },
    inputSchema: SKILL_INPUT_SCHEMA,
  }));

  const handlers: Record<string, ToolHandler> = {};
  for (const source of sources) {
    handlers[source.id] = async (ctx) => {
      const input = ctx.input === undefined ? {} : requireInputRecord({ input: ctx.input });
      if (Array.isArray(input) || Object.keys(input).some(key => key !== "file")) throw new Error("this tool accepts only an optional 'file' argument");
      const file = optionalString({ input, key: "file" });
      const content = source.readFile ? await source.readFile({}, file !== undefined ? { file } : {}) : undefined;
      return buildSkillToolResult({ source, content, file });
    };
  }

  return buildDomainRegistrations({ metadata: toolMetadata,
    domain: "skill",
    catalogModule: "features/skills/tool-registrations.ts",
    catalog: indexCatalogById({ catalog: catalog }),
    handlers,
    derivedRisk: skillToolDerivedRisk(sources),
  }).map(registration => withExtensionApprovalPolicy({ registration, family: 'installed-guidance' }));
}

/**
 * Composition-root entry point: loads every installed standalone Agent Skill for one workspace and
 * registers each as a real tool directly on `registry` — the same `registry.register(registration)`
 * call `agent-daemon-server.ts`'s own top-level loops make for every other domain, just awaited
 * first. Mirrors `agent-plugins/tool-registrations.ts`'s own `registerInstalledAgentPluginTools`.
 */
const liveRegistrations = new WeakMap<object, (tools: readonly ToolRegistration[]) => boolean>();

export async function registerInstalledSkillTools(
  registry: Pick<SkillsRefreshRegistry, "register"> & Partial<Pick<SkillsRefreshRegistry, "has" | "list" | "refreshInstalledSkills">>,
  ctx: { readonly workspaceId: string; readonly skillLayout: SkillLayout; readonly siteBinding: { readonly dir: string } },
): Promise<void> {
  if (!registry.has || !registry.list) {
    for (const registration of buildSkillToolRegistrations(await loadInstalledSkillToolSources(ctx))) registry.register(registration);
    return;
  }
  let replace = liveRegistrations.get(registry);
  if (!replace) {
    replace = createLiveSkillRegistration(registry as SkillsRefreshRegistry);
    liveRegistrations.set(registry, replace);
    // Single-flight disk reads prevent an older snapshot from overwriting a newer one.
    let pending: Promise<boolean> | undefined;
    const apply = replace;
    registry.refreshInstalledSkills = () => {
      if (!pending) pending = loadInstalledSkillToolSources(ctx)
        .then(sources => apply(buildSkillToolRegistrations(sources)))
        .finally(() => { pending = undefined; });
      return pending;
    };
  }
  await registry.refreshInstalledSkills!();
}

import { applyPluginCredentialCard, findPluginCredentialCard, type LoadPluginCredentialCards } from "../custom-credentials/plugin-credential-card.js";
import { abortGuardedCredentialRepo } from "../vendor-credentials/abort-guarded-repo.js";
import { CREDENTIAL_SAVE_TOOL_ID } from "../../contracts/headless/secret-form-cards.js";
import { assertCredentialFreeField, CREDENTIAL_MESSAGES, type CredentialTokenHint, type CredentialConnection } from '../../contracts/core/credential-token.js';
import { credentialText, formatCredentialHint } from '../../contracts/core/credential-copy.js';
import { resolveOperatorLocale, type OperatorLocaleDeps } from '../agent-plugins/operator-locale.js';
import { adaptLegacyAuthorize } from "@jini-ai/cms/core";
import { optionalString, requireInputRecord, requireString } from "@jini-ai/core";
import { requireToolPermission } from "@jini-ai/cms/core";
import { ToolInputError, type ToolExecutionOptions, type ToolExecutionContext } from '@jini-ai/core';
import { defineSecretCardTool, type SecretCardField, type SecretCardRun } from '@jini-ai/ui/mcp-ui/secret-card';
import { askThenReport, type AssistantSurfaceDeps } from "@jini-ai/daemon/surface-exchanges";
import { SourceControlCredentialDuplicateLabelError, createSourceControlCredential, type SourceControlCredentialWriteDeps } from './store.js';
import type { LoadSourceControlProviders, SourceControlProviderDescriptor } from './provider-registry.js';
import type { AuthorizeFn } from '../../contracts/core/commands/index.js';

/** Narrow save dependencies; independent of the registration module to avoid a type-import cycle.
 * `loadSourceControlProviders` is required: the composition root (`tool-registrations.ts`) resolves the
 * installed-plugins default, so this module never reads a workspace it was not handed. */
export interface SourceControlCredentialSetupDeps extends OperatorLocaleDeps {
  readonly loadPluginCredentialCards?: LoadPluginCredentialCards;
  workspaceId: string;
  authorize: AuthorizeFn;
  sourceControlCredentialSetRepo: SourceControlCredentialWriteDeps['repo'];
  siteAssistantSecretSealer: SourceControlCredentialWriteDeps['sealer'];
  siteAssistantSecretKeyring: SourceControlCredentialWriteDeps['keyring'];
  clock: SourceControlCredentialWriteDeps['clock'];
  idGen: SourceControlCredentialWriteDeps['idGen'];
  fetchFn?: SourceControlCredentialWriteDeps['fetchFn'];
  observability?: SourceControlCredentialWriteDeps['observability'];
  loadSourceControlProviders: LoadSourceControlProviders;
}

/** Human-only credential setup; model inputs/results never carry connection fields or raw errors. */

interface ProposalResult { saved: boolean; credentialId: string | null; provider: string; label: string; cancelled?: boolean; message?: string; tokenHint?: CredentialTokenHint | null; connection?: CredentialConnection }

/** Why nothing was saved, one per cause. Demo dry run 2026-10-05: all three used to return the same
 *  `{saved: false}`, so a person's Cancel was reported as "Either it was closed or the save failed". */
export const PROPOSE_CREDENTIAL_CANCELLED = 'The person cancelled the form. Nothing was saved.';
export const PROPOSE_CREDENTIAL_CLOSED = 'The form closed without an answer (it timed out or the chat run ended). Nothing was saved.';
export const PROPOSE_CREDENTIAL_ABORTED = 'The chat run ended before the form opened. Nothing was saved.';
export const PROPOSE_CREDENTIAL_SAVE_FAILED = 'The person submitted the form but the token could not be saved; the form told them why. Nothing was saved.';

/** Repository rules a site backup enforces (`site_backup_plan`), shown on the form beside the provider's token help. */
const BACKUP_REPOSITORY_RULES = 'For a site backup, the repository must be private and already have at least one commit (for example a README).';

/** Opens the registry-defined human form and parks this tool call until answered or aborted.
 * @param spec - Tool context, explicit store dependencies and the shared exchange store.
 * @example await proposeSourceControlCredential({ ctx, deps, surfaces });
 * @returns Safe save status; throws ToolInputError for invalid model input or absent form channel.
 * @complexity Time O(p + f) provider/field count before one existing credential save; space O(f).
 */
export async function proposeSourceControlCredential(spec: { ctx: ToolExecutionContext; deps: SourceControlCredentialSetupDeps; surfaces: AssistantSurfaceDeps }, optional: ToolExecutionOptions = {}): Promise<ProposalResult> {
  const { ctx, deps, surfaces } = spec;
  const { provider, label } = parseProposalInput({ input: ctx.input });
  await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: 'source-control.credentials.write' }, { entityType: 'source-control' });
  // An ended run must not load plugins; the engine classifies abandonment without opening a card.
  const registry = ctx.signal.aborted ? undefined : await deps.loadSourceControlProviders(deps.workspaceId);
  const descriptor = registry?.get(provider)?.descriptor;
  if (!ctx.signal.aborted && !descriptor?.credential) {
    throw new ToolInputError({ message: 'No enabled source control provider declares this credential form. Call source_control_get_capabilities for available hosts.' });
  }
  const locale = await resolveOperatorLocale({ deps, workspaceId: deps.workspaceId, principalId: ctx.principal.id });
  const pluginCard = ctx.signal.aborted ? undefined : await findPluginCredentialCard({ loadCards: deps.loadPluginCredentialCards, workspaceId: deps.workspaceId, saveKind: 'source-control', target: provider });
  const card = defineSecretCardTool<{
    descriptor: SourceControlProviderDescriptor | undefined; provider: string; label: string; locale: string;
  }, Awaited<ReturnType<typeof createSourceControlCredential>>, ProposalResult>({
    toolId: CREDENTIAL_SAVE_TOOL_ID,
    prepare: async () => ({ descriptor: ctx.signal.aborted ? undefined : descriptor, provider, label, locale }),
    form: ({ prep }) => applyPluginCredentialCard({ card: pluginCard, form: {
      title: `Connect ${prep.descriptor!.label}`,
      description: `${prep.descriptor!.credential!.help ?? 'Type the secret here. The assistant never sees it.'} ${BACKUP_REPOSITORY_RULES}`,
      submitLabel: 'Save credential',
      fields: [{ kind: 'string', name: 'label', label: 'Label', required: true, value: prep.label },
        ...prep.descriptor!.credential!.fields.map((field): SecretCardField => {
          const base = { kind: 'string' as const, name: field.name, label: field.label, required: field.required };
          return field.secret || field.name === prep.descriptor!.credential!.tokenField
            ? { ...base, secret: true, allowBlank: !field.required } : base;
        })],
    } }),
    // Saves only provider-declared fields through the admin POST's existing store function.
    // Returns an explicit safe projection; errors may quote secrets and are never forwarded.
    save: ({ values, prep, signal }) => {
      const connection = connectionFromForm({ descriptor: prep.descriptor!, values });
      const store = deps.sourceControlCredentialSetRepo;
      // The async seal can outlive the run; the existing store must not insert after abandonment.
      // Saves write through `vault`, so it must be forwarded (omitting it fails every save) with the same guard.
      const vault = store.vault;
      const repo: SourceControlCredentialSetupDeps['sourceControlCredentialSetRepo'] = {
        ...(vault ? { vault: sourceControlSaveVault({ vault, signal }) } : {}),
        insert: record => { signal.throwIfAborted(); return store.insert(record); },
        update: record => store.update(record),
        findById: input => store.findById(input),
        findDefaultByProvider: input => store.findDefaultByProvider(input),
        listByProvider: input => store.listByProvider(input),
        listByWorkspace: input => store.listByWorkspace(input),
        delete: input => store.delete(input),
        ...(store.updateAccountLabel ? { updateAccountLabel: (input: Parameters<NonNullable<typeof store.updateAccountLabel>>[0]) => store.updateAccountLabel!(input) } : {}),
        // The project half writes too (project-first saves): guarded alike.
        ...(store.project ? { project: { ...store.project, repo: abortGuardedCredentialRepo({ store: store.project.repo, signal }) } } : {}),
      };
      // New project keys stay non-default while the shared save-result path attaches them to this site.
      return createSourceControlCredential({ deps: {
        repo, sealer: deps.siteAssistantSecretSealer,
        keyring: deps.siteAssistantSecretKeyring, clock: deps.clock, idGen: deps.idGen,
        loadSourceControlProviders: deps.loadSourceControlProviders,
        ...(deps.fetchFn ? { fetchFn: deps.fetchFn } : {}), observability: deps.observability,
      }, input: { workspaceId: deps.workspaceId, label: values.label, connection, ...(store.project ? { isDefault: false } : {}) } });
    },
    result: ({ prep, run }): ProposalResult => {
      const declined = { saved: false, credentialId: null, provider: prep.provider, label: prep.label, cancelled: run.status === 'cancelled' };
      if (run.status !== 'saved') {
        const message = declinedMessage({ prep, run });
        return { ...declined, message };
      }
      const credential = run.saved;
      const connection = credential.connection ?? 'saved';
      return { saved: true, credentialId: credential.id, provider: prep.provider, label: credential.label, tokenHint: credential.tokenHint, connection,
        message: savedMessage({ credential, locale: prep.locale }) };
    },
    // Renders a value-free save outcome on the form's URI, supplied by the engine.
    outcome: ({ prep, run }) => {
      if (run.status === 'cancelled' || run.status === 'expired' || run.status === 'abandoned') return undefined;
      const saved = run.status === 'saved';
      const message = saved ? savedMessage({ credential: run.saved, locale: prep.locale })
        : run.status === 'blank' ? credentialText({ id: 'blank', locale: prep.locale }) : run.status === 'failed' ? run.safeMessage : PROPOSE_CREDENTIAL_SAVE_FAILED;
      return { title: saved ? 'Credential saved' : 'Credential not saved', state: saved ? 'success' : 'failure', message };
    },
  }, {
    uriHost: 'tovu',
    text: { noEmitter: 'source_control_propose_credential requires an interactive form channel. Nothing was saved.', saveFailure: PROPOSE_CREDENTIAL_SAVE_FAILED },
    safeError: err => {
      if (err instanceof SourceControlCredentialDuplicateLabelError) return err.message;
      const id = Object.entries(CREDENTIAL_MESSAGES).find(([, text]) => err instanceof Error && text === err.message)?.[0];
      return id ? credentialText({ id: id as keyof typeof CREDENTIAL_MESSAGES, locale }) : undefined;
    },
    // Fixed metadata only: neither an exception's text nor a submitted value is safe to log.
    logFailure: metadata => console.warn(JSON.stringify(metadata)),
  });
  return card.handler({ surfaceExchanges: surfaces.surfaceExchanges, askThenReport })(ctx, optional);
}

/** Preserve this adapter's vault ABI and its write guards, including optional batch writes. */
function sourceControlSaveVault({ vault, signal }: { vault: NonNullable<SourceControlCredentialSetupDeps['sourceControlCredentialSetRepo']['vault']>; signal: AbortSignal }, _options = {}): typeof vault {
  return {
    find: (input, options) => vault.find(input, options),
    list: (input, options) => vault.list(input, options),
    put: (input, options) => { signal.throwIfAborted(); return vault.put(input, options); },
    patchMeta: (input, options) => vault.patchMeta(input, options),
    delete: (input, options) => vault.delete(input, options),
    ...(vault.findDefault ? { findDefault: (input: Parameters<NonNullable<typeof vault.findDefault>>[0], options?: Parameters<NonNullable<typeof vault.findDefault>>[1]) => vault.findDefault!(input, options) } : {}),
    ...(vault.findOne ? { findOne: (input: Parameters<NonNullable<typeof vault.findOne>>[0], options?: Parameters<NonNullable<typeof vault.findOne>>[1]) => vault.findOne!(input, options) } : {}),
    ...(vault.applyBatch ? { applyBatch: (input: Parameters<NonNullable<typeof vault.applyBatch>>[0], options?: Parameters<NonNullable<typeof vault.applyBatch>>[1]) => { signal.throwIfAborted(); return vault.applyBatch!(input, options); } } : {}),
  };
}

/** Keep provider-defined names on the human form and canonical `token` on the store contract.
 * Only declared fields cross the save boundary. @complexity O(f) time/space, f <= 10. */
function connectionFromForm({ descriptor, values }: {
  descriptor: SourceControlProviderDescriptor; values: Readonly<Record<string, unknown>>;
}, _options = {}): Record<string, unknown> {
  const connection: Record<string, unknown> = { providerId: descriptor.id };
  for (const field of descriptor.credential!.fields) {
    const name = field.name === descriptor.credential!.tokenField ? 'token' : field.name;
    connection[name] = values[field.name];
  }
  return connection;
}

/** Validate only public model fields before authorization or plugin lookup. @complexity O(k) input keys. */
function parseProposalInput({ input }: { input: unknown }, _options = {}): { provider: string; label: string } {
  const raw = requireInputRecord({ input });
  if (Object.keys(raw).some(key => key !== 'provider' && key !== 'label')) {
    throw new ToolInputError({ message: 'source_control_propose_credential accepts only provider and label; enter secrets in the human form.' });
  }
  const provider = requireString({ input: raw, key: 'provider' });
  const label = optionalString({ input: raw, key: 'label' }) ?? 'default';
  assertCredentialFreeField({ value: label, field: "label" });
  if (label.length > 200) throw new ToolInputError({ message: 'Credential label must be at most 200 characters.' });
  return { provider, label };
}

type CredentialPrep = { descriptor: SourceControlProviderDescriptor | undefined; locale: string };
type SavedCredential = Awaited<ReturnType<typeof createSourceControlCredential>>;

/** Fixed decline copy preserves the distinction between unopened and closed forms. @complexity O(1). */
function declinedMessage({ prep, run }: { prep: CredentialPrep; run: Exclude<SecretCardRun<SavedCredential>, { status: 'saved' }> }, _options = {}): string {
  switch (run.status) {
    case 'cancelled': return PROPOSE_CREDENTIAL_CANCELLED;
    case 'blank': return credentialText({ id: 'blank', locale: prep.locale });
    case 'failed': return run.safeMessage;
    case 'abandoned': return prep.descriptor === undefined ? PROPOSE_CREDENTIAL_ABORTED : PROPOSE_CREDENTIAL_CLOSED;
    default: return PROPOSE_CREDENTIAL_CLOSED;
  }
}

/** Both projections use the same safe hint and connection copy. @complexity O(1). */
function savedMessage({ credential, locale }: { credential: SavedCredential; locale: string }, _options = {}): string {
  const hint = formatCredentialHint({ hint: credential.tokenHint, locale });
  return `${hint ? `${hint}. ` : ''}${credentialText({ id: credential.connection ?? 'saved', locale })}`;
}

import { CredentialInputError, CREDENTIAL_MESSAGES, assertCredentialFreeField, normalizeCredentialToken, type CredentialConnection } from '../../contracts/core/credential-token.js';
import type { Clock as ClockPort, UUID } from "@jini-ai/core/primitives";

import { isUniqueViolation } from "../../platform/db/kernel/dialect.js";
import type { KeyringPort, SecretSealerPort } from "../webhooks/index.js";
import { VaultError, type VaultSummary } from "@jini-ai/platform/secrets/credential-sets";
import { credentialVault, credentialScope, credentialHint } from "../vendor-credentials/vault-adapter.js";
import { credentialDeletionRepo, credentialCreateTarget, credentialScopes, type CredentialScope, type ScopedCredentialDeps } from "../vendor-credentials/project-scope.js";
import { buildSourceControlProvider, type LoadSourceControlProviders, type SourceControlProviderRegistry, type SourceControlProviderDescriptor } from "./provider-registry.js";
import type {
  SourceControlConnectionInput,
  SourceControlCredentialSetRecord,
  SourceControlCredentialSetRepoPort,
  SourceControlCredentialSummary,
  SourceControlProviderId,
} from "./types.js";
import type { ObservabilityPort } from "../../platform/observability/index.js";

/** Source-control validation and inline identity probes remain feature policy. Jini owns
 * sealing, persistence, hints and defaults. Plain read models require neither keys nor opens. */

const MAX_LABEL_LENGTH = 200;
export class SourceControlCredentialValidationError extends Error {}

/** A `(workspaceId, providerId, label)` collision — the route maps this to `409 DUPLICATE_LABEL`. */
export class SourceControlCredentialDuplicateLabelError extends Error {}

/** Thrown when `sealer.seal()`/`keyring.activeKey()` fails while writing a connection — the
 *  realistic cause is a missing site key (`TOVU_SITE_KEY`), same fail-closed
 *  contract `PublishCredentialSecretStoreUnconfiguredError` documents for the sibling table. */
export class SourceControlCredentialSecretStoreUnconfiguredError extends Error {}

export class SourceControlCredentialNotFoundError extends Error {}

async function toSummary(record: SourceControlCredentialSetRecord): Promise<SourceControlCredentialSummary> {
  return { id: record.id, providerId: record.providerId, label: record.label, configured: true,
    tokenHint: record.tokenHint ?? null, isDefault: record.isDefault, accountLabel: record.accountLabel,
    createdAt: record.createdAt, updatedAt: record.updatedAt };
}
function vaultSummary({ summary }: { summary: VaultSummary }, _options = {}): SourceControlCredentialSummary {
  return { id: summary.id, providerId: summary.provider as SourceControlProviderId, label: summary.label,
    configured: true, tokenHint: credentialHint({ record: summary }), isDefault: summary.isDefault,
    accountLabel: summary.meta.accountLabel as string | null, createdAt: summary.createdAt, updatedAt: summary.updatedAt };
}
function vault(deps: SourceControlCredentialReadDeps & Partial<SourceControlCredentialWriteDeps>, _options = {}) {
  return credentialVault({ ...deps, sealer: deps.sealer!, storageError: () => new SourceControlCredentialSecretStoreUnconfiguredError(CREDENTIAL_MESSAGES.storage) });
}

/**
 * Best-effort "who does this token belong to" probe, run inline at save time — see this file's own
 * header for why THIS table's `create`/`update` may do this while `publish-credentials/store.ts`'s
 * may not. NEVER throws: no provider, a network failure, timeout, or non-2xx response degrades to
 * `null` (no account label learned) rather than failing the save.
 *
 * The host-specific read lives in the plugin that provides the host (`provider-module.ts`'s
 * `readAccountLabel`; each provider owns its account identity read). A host no enabled
 * plugin provides yields `null` with no request made.
 *
 * @complexity One registry load plus at most one bounded HTTP request.
 */
async function probeAccountLabel(deps: SourceControlCredentialWriteDeps, workspaceId: UUID, providerId: SourceControlProviderId, token: string): Promise<{ accountLabel: string | null; connection: CredentialConnection }> {
  let connection: CredentialConnection = 'saved';
  const fetchFn: typeof fetch = async (input, init) => {
    try {
      const response = await (deps.fetchFn ?? fetch)(input, init);
      connection = response.status === 401 || response.status === 403 ? 'auth' : response.ok ? 'connected' : 'unreachable';
      return response;
    } catch (err) {
      connection = err instanceof Error && (err.name === 'AbortError' || err.name === 'TimeoutError') ? 'timeout' : 'unreachable';
      throw err;
    }
  };
  try {
    // Write-only callers may omit account discovery; production supplies its boot-bound loader.
    if (!deps.loadSourceControlProviders) return { accountLabel: null, connection };
    const built = await buildSourceControlProvider({
      load: deps.loadSourceControlProviders,
      fetchFn,
      observability: deps.observability,
      workspaceId,
      providerId,
    });
    const accountLabel = built.ok ? await built.provider.readAccountLabel(token) : null;
    return { accountLabel, connection };
  } catch {
    return { accountLabel: null, connection };
  }
}

export interface SourceControlCredentialReadDeps {
  repo: SourceControlCredentialSetRepoPort;
  sealer?: SecretSealerPort;
}

/** A row and the store holding it (`vendor-credentials/project-scope.ts`: this site's own vault first,
 *  then the project half `types.ts`'s `repo.project` attaches), with the deps that open it. */
interface Located<D> { readonly scoped: ScopedCredentialDeps<D>; readonly record: SourceControlCredentialSetRecord }

/** The summary's `scope`, only where a project store is attached (a site-only server's output is unchanged). */
const reportedScope = (deps: SourceControlCredentialReadDeps, scoped: ScopedCredentialDeps<unknown>): { scope?: CredentialScope } =>
  deps.repo.project ? { scope: scoped.scope } : {};

/** The row with this id, from the first store holding it (ids are unique across both). @complexity O(scopes). */
async function locateById<D extends SourceControlCredentialReadDeps>(deps: D, input: { workspaceId: UUID; id: UUID }): Promise<Located<D> | null> {
  for (const scoped of credentialScopes(deps, input.workspaceId)) {
    const record = await scoped.deps.repo.findById({ workspaceId: scoped.workspaceId, id: input.id });
    if (record) return { scoped, record };
  }
  return null;
}

/**
 * Every row this site uses: its own rows, then project rows whose host and label no site row already
 * claims (a site row of the same host and label is the override).
 * @complexity O(n) in the two stores' (small) credential counts; no row is opened.
 */
async function listEffective<D extends SourceControlCredentialReadDeps>(deps: D, workspaceId: UUID): Promise<Located<D>[]> {
  const found: Located<D>[] = [];
  const claimed = new Set<string>();
  for (const scoped of credentialScopes(deps, workspaceId)) {
    const records = await scoped.deps.repo.listByWorkspace({ workspaceId: scoped.workspaceId });
    for (const record of records.filter((row) => !claimed.has(`${row.providerId}\0${row.label}`))) found.push({ scoped, record });
    for (const record of records) claimed.add(`${record.providerId}\0${record.label}`);
  }
  return found;
}

/**
 * The read model for ONE credential set. Pure DB read — no sealer, no keyring, cannot fail on a
 * misconfigured site key. Returns `null` if no row exists for `(workspaceId, id)` (not an
 * error — the caller decides whether that is a 404).
 *
 * @complexity O(1) — one `findById` lookup.
 */
export async function describeCredential(
  deps: SourceControlCredentialReadDeps,
  input: { workspaceId: UUID; id: UUID }
): Promise<SourceControlCredentialSummary | null> {
  const located = await locateById(deps, input);
  return located ? { ...await toSummary(located.record), ...reportedScope(deps, located.scoped) } : null;
}

/**
 * The read model for EVERY credential set a workspace has saved — what
 * `GET .../source-control/credentials` returns. Same "never decrypts" contract as
 * {@link describeCredential}.
 *
 * @complexity O(n) in the workspace's own (small) credential-set count. One repo read, one array
 *   map, no per-row I/O.
 */
export async function listSourceControlCredentials(
  deps: SourceControlCredentialReadDeps,
  input: { workspaceId: UUID }
): Promise<SourceControlCredentialSummary[]> {
  const located = await listEffective(deps, input.workspaceId);
  return Promise.all(located.map(async ({ scoped, record }) => ({ ...await toSummary(record), ...reportedScope(deps, scoped) })));
}

export interface SourceControlCredentialWriteDeps extends SourceControlCredentialReadDeps {
  sealer: SecretSealerPort;
  keyring: KeyringPort;
  clock: ClockPort;
  idGen: { newId(): string };
  /** Injected by tests; defaults to global `fetch`. Used only by {@link probeAccountLabel}. */
  fetchFn?: typeof fetch;
  /** `RouteDeps.observability`: the identity probe is one outbound span. */
  observability?: ObservabilityPort;
  /** Loaded provider declarations govern admission and optional account-label discovery. */
  loadSourceControlProviders?: LoadSourceControlProviders;
}

/** Narrows and validates a caller-supplied `label`. Never throws a raw `TypeError` — every
 *  rejection is a {@link SourceControlCredentialValidationError} the route layer can map to its own
 *  `400`. */
function validateLabel(raw: unknown): string {
  if (typeof raw !== "string" || raw.trim() === "") {
    throw new SourceControlCredentialValidationError("label must be a non-empty string");
  }
  if (raw.length > MAX_LABEL_LENGTH) {
    throw new SourceControlCredentialValidationError(`label must be ${MAX_LABEL_LENGTH} characters or fewer`);
  }
  assertPlainField({ value: raw, field: "label" });
  return raw;
}

function requireNonEmptyString(raw: unknown, field: string, providerId: string): string {
  if (typeof raw !== "string" || raw.trim() === "") {
    throw new SourceControlCredentialValidationError(`'${field}' (non-empty string) is required for provider '${providerId}'`);
  }
  return raw;
}

/** Narrows a caller-supplied `isDefault`. `undefined` means "no default change requested"; any
 *  other non-boolean value is rejected rather than coerced. */
function optionalBoolean(raw: unknown, field: string): boolean | undefined {
  if (raw === undefined) return undefined;
  if (typeof raw !== "boolean") {
    throw new SourceControlCredentialValidationError(`'${field}' must be a boolean when provided`);
  }
  return raw;
}

/** Blank/omitted canonical tokens preserve the envelope after connection-shape validation. */
function isEmptyTokenPatch({ value }: { value: Record<string, unknown> }, _options = {}): boolean {
  const token = value.token;
  return token === '' || token === undefined;
}

/** Reject malformed connection shapes before either rotation or envelope preservation. */
function connectionObject({ raw }: { raw: unknown }, _options = {}): Record<string, unknown> {
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
    throw new SourceControlCredentialValidationError('connection must be an object');
  }
  return raw as Record<string, unknown>;
}

/** Forms and vault payloads use `token`; accept a declared form name at the store boundary too.
 * An explicitly supplied canonical value takes precedence, including blank/invalid values. */
function canonicalConnection({ value, descriptor }: { value: Record<string, unknown>; descriptor?: SourceControlProviderDescriptor }, _options = {}): Record<string, unknown> {
  if (value.token !== undefined) return value;
  const tokenField = descriptor?.credential?.tokenField ?? 'token';
  return { ...value, token: value[tokenField] };
}

/** Normalize alternate form names before deciding whether this is a rotation. Ordinary metadata
 * patches and canonical-token patches need no registry lookup, keeping opaque saved rows editable.
 * @complexity O(k) input keys plus at most one registry load for provider-specific fields. */
async function normalizeConnectionPatch({ raw, existing, registry }: {
  raw: unknown; existing: SourceControlProviderId; registry: () => Promise<SourceControlProviderRegistry>;
}, _options = {}): Promise<Record<string, unknown> | undefined> {
  if (raw === undefined) return undefined;
  // A patch that leaves out the host keeps the saved one (a token-only rotation names no provider).
  const value = { ...connectionObject({ raw }) };
  value.providerId ??= existing;
  if (value.token !== undefined || Object.keys(value).every(key => key === 'providerId' || key === 'token')) return value;
  const loaded = await registry();
  const descriptor = typeof value.providerId === 'string' ? loaded.get(value.providerId)?.descriptor : undefined;
  return canonicalConnection({ value, descriptor });
}

/** A blank token keeps the sealed envelope, and the envelope cannot be rewritten without the token,
 * so a blank patch carrying any other connection field is refused rather than dropping it silently.
 * The provider's declared token name is a blank token too. @complexity O(k) patch keys; the registry
 * loads only when the patch names a field besides `providerId`/`token`. */
async function assertBlankPatchChangesNoField({ patch, registry }: {
  patch: Record<string, unknown> | undefined; registry: () => Promise<SourceControlProviderRegistry>;
}, _options = {}): Promise<void> {
  const named = Object.keys(patch ?? {}).filter(key => key !== 'providerId' && key !== 'token');
  if (named.length === 0) return;
  const providerId = typeof patch?.providerId === 'string' ? patch.providerId : '';
  const tokenField = (await registry()).get(providerId)?.descriptor.credential?.tokenField;
  const changed = named.filter(key => key !== tokenField);
  if (changed.length > 0) throw new SourceControlCredentialValidationError(`changing ${changed.join(', ')} requires a new token`);
}
/** A token-only host can move without opening the secret. Entering a host with required
 * paired fields needs a new connection; an envelope-only move cannot invent those fields.
 * Saved, unlisted ids may keep their envelope and metadata without loading plugin code. */
async function preservedProvider({ raw, existing, registry }: {
  raw: unknown; existing: SourceControlProviderId; registry: () => Promise<SourceControlProviderRegistry>;
}, _options = {}): Promise<SourceControlProviderId> {
  if (raw === undefined) return existing;
  const providerId = (raw as Record<string, unknown>).providerId;
  if (providerId === undefined || providerId === existing) return existing;
  const descriptor = requireProvider({ providerId, registry: await registry() });
  const paired = descriptor.credential?.fields.find(field => field.required && field.name !== descriptor.credential!.tokenField);
  if (paired) throw new SourceControlCredentialValidationError(`moving to ${descriptor.id} requires a new token and ${paired.name}`);
  return descriptor.id;
}

/** Only loaded providers admit new connections; stored ids are never checked against this list. */
function requireProvider({ providerId, registry }: { providerId: unknown; registry: SourceControlProviderRegistry }, _options = {}): SourceControlProviderDescriptor {
  const loaded = typeof providerId === 'string' ? registry.get(providerId) : undefined;
  if (!loaded) throw new SourceControlCredentialValidationError(`connection.providerId must be one of: ${registry.list().map(provider => provider.descriptor.id).join(', ')}`);
  return loaded.descriptor;
}

/** Write-only callers without a provider port cannot introduce a new credential/provider. */
async function credentialRegistry({ deps, workspaceId }: { deps: SourceControlCredentialWriteDeps; workspaceId: UUID }, _options = {}): Promise<SourceControlProviderRegistry> {
  if (!deps.loadSourceControlProviders) return { list: () => [], get: () => undefined, refusals: [] };
  return deps.loadSourceControlProviders(workspaceId);
}

function normalizeStoredToken({ value }: { value: unknown }): string {
  try { return normalizeCredentialToken({ value }); }
  catch (err) { if (err instanceof CredentialInputError) throw new SourceControlCredentialValidationError(err.message); throw err; }
}
function assertPlainField(required: { value: string; field: string }): void {
  try { assertCredentialFreeField(required); }
  catch (err) { if (err instanceof CredentialInputError) throw new SourceControlCredentialValidationError(err.message); throw err; }
}

/** Validate declared fields before sealing. Authentication pairs stay in one ciphertext blob.
 * Only declared fields are accepted on new writes; existing saved payloads remain opaque.
 * @complexity O(f) time/space, f bounded by the existing credential-form parser (10 fields). */
function validateConnection({ raw, registry }: { raw: unknown; registry: SourceControlProviderRegistry }, _options = {}): SourceControlConnectionInput {
  const value = connectionObject({ raw });
  const descriptor = requireProvider({ providerId: value.providerId, registry });
  const canonical = canonicalConnection({ value, descriptor });
  const token = normalizeStoredToken({ value: canonical.token });
  return { ...collectDeclaredFields({ value, descriptor }), providerId: descriptor.id, token };
}

/** Collect only the provider's additional declared fields; the primary secret is stored as `token`.
 * Authentication pairs stay in the same ciphertext blob. @complexity O(f) time/space, f <= 10. */
function collectDeclaredFields({ value, descriptor }: { value: Record<string, unknown>; descriptor: SourceControlProviderDescriptor }, _options = {}): Record<string, string> {
  const tokenField = descriptor.credential?.tokenField ?? 'token';
  const fields: Record<string, string> = {};
  for (const field of descriptor.credential?.fields ?? []) {
    if (field.name === tokenField) continue;
    const validated = validateDeclaredField({ value: value[field.name], field, providerId: descriptor.id });
    if (validated !== undefined) fields[field.name] = validated;
  }
  return fields;
}

/** Non-secret metadata uses the existing credential-free admission check; secrets use token admission. */
function validateDeclaredField({ value, field, providerId }: {
  value: unknown; field: import('./credential-form.js').SourceControlCredentialField; providerId: string;
}, _options = {}): string | undefined {
  if (value === undefined && !field.required) return undefined;
  const text = requireNonEmptyString(value, field.name, providerId);
  if (field.secret) return normalizeStoredToken({ value: text });
  assertPlainField({ value: text, field: field.name });
  return text;
}

/** True iff `err` is the label's UNIQUE `(workspace_id, provider_id, label)` index rejecting a
 *  duplicate, on any database (`isUniqueViolation`, storage kernel: SQLite's code/message, Postgres
 *  SQLSTATE 23505). */
export function isUniqueLabelViolation(err: unknown): boolean {
  return isUniqueViolation(err);
}

export interface CreateSourceControlCredentialInput {
  workspaceId: UUID;
  label: unknown;
  connection: unknown;
  /** `true` makes this the provider's default connection. Omitted auto-defaults the provider's
   *  FIRST saved connection; explicit `false` opts out. Jini owns atomic auto-defaulting. */
  isDefault?: unknown;
  /** `"site"` = a site-owned key. Omitted (or `"project"`) = the project store when one is
   *  attached, visible to attached sites only; this site's vault otherwise. */
  scope?: unknown;
}

/**
 * A project row whose host and label this site already uses would be hidden here by the site row
 * (site rows override), so the save would look lost: refused as the same duplicate as within one store.
 */
async function assertLabelFreeOnSite({ deps, target, workspaceId, providerId, label }: { deps: SourceControlCredentialReadDeps;
  target: ScopedCredentialDeps<unknown>; workspaceId: UUID; providerId: SourceControlProviderId; label: string }, _options = {}): Promise<void> {
  if (target.scope !== "project") return;
  if ((await deps.repo.listByProvider({ workspaceId, providerId })).some(row => row.label === label)) {
    throw new SourceControlCredentialDuplicateLabelError(`a '${providerId}' credential labeled '${label}' already exists in this workspace`);
  }
}

/** A rename or host move of a project row is checked as a create is: a label this site's own row
 * already uses would hide the moved row here. An unchanged label and host needs no check. */
async function assertMoveFreeOnSite({ deps, scoped, existing, workspaceId, providerId, label }: { deps: SourceControlCredentialReadDeps;
  scoped: ScopedCredentialDeps<unknown>; existing: SourceControlCredentialSetRecord; workspaceId: UUID; providerId: SourceControlProviderId; label: string }, _options = {}): Promise<void> {
  if (label === existing.label && providerId === existing.providerId) return;
  await assertLabelFreeOnSite({ deps, target: scoped, workspaceId, providerId, label });
}

/** Validate the loaded declaration, then make the secret durable before identity discovery.
 * @param required Explicit store ports and create input. @returns A summary with no secret fields.
 * @throws {SourceControlCredentialValidationError} Invalid or unavailable provider/fields.
 * Probe failures never undo a save; Jini owns sealing, hints and atomic defaults. */
export async function createSourceControlCredential(
  { deps, input }: { deps: SourceControlCredentialWriteDeps; input: CreateSourceControlCredentialInput },
  _options = {},
): Promise<SourceControlCredentialSummary> {
  const label = validateLabel(input.label);
  const connection = validateConnection({ raw: input.connection, registry: await credentialRegistry({ deps, workspaceId: input.workspaceId }) });
  const isDefault = optionalBoolean(input.isDefault, "isDefault");
  // Project-first (`vendor-credentials/project-scope.ts`); "site" = only for this site.
  const target = credentialCreateTarget(deps, input, message => new SourceControlCredentialValidationError(message));
  await assertLabelFreeOnSite({ deps, target, workspaceId: input.workspaceId, providerId: connection.providerId, label });
  const id = deps.idGen.newId();
  const summary = await saveConnection({ deps: target.deps, input: { ...credentialScope({ workspaceId: target.workspaceId, kind: "source-control", id }),
    id, provider: connection.providerId, label, expectedRevision: null, payload: { ...connection }, hintToken: connection.token,
    meta: { accountLabel: null }, ...(isDefault === undefined ? {} : { isDefault }) } });
  return { ...await probeSavedConnection({ deps: target.deps, summary, connection, workspaceId: input.workspaceId }), ...reportedScope(deps, target) };
}

/** Conflict translation is label-specific; a CAS conflict is never reported as a duplicate. */
async function saveConnection({ deps, input }: { deps: SourceControlCredentialWriteDeps; input: Parameters<ReturnType<typeof vault>["put"]>[0] }, _options = {}): Promise<VaultSummary> {
  try { return await vault(deps).put(input); }
  catch (error) {
    const duplicate = isUniqueLabelViolation(error) || error instanceof VaultError && error.code === "conflict" &&
      (await deps.repo.listByProvider({ workspaceId: input.workspaceId, providerId: input.provider as SourceControlProviderId }))
        .some(row => row.id !== input.id && row.label === input.label);
    if (duplicate) throw new SourceControlCredentialDuplicateLabelError(input.workspaceId === 'project' ? `Your project already has a key named '${input.label}'. Use it here, or pick another name.` : `a '${input.provider}' credential labeled '${input.label}' already exists in this workspace`);
    throw error;
  }
}

/** `deps` writes the store holding `summary`'s row; `workspaceId` is the site's (its provider registry). */
async function probeSavedConnection({ deps, summary, connection, workspaceId }: { deps: SourceControlCredentialWriteDeps; summary: VaultSummary; connection: SourceControlConnectionInput; workspaceId: UUID }, _options = {}): Promise<SourceControlCredentialSummary> {
  const probe = await probeAccountLabel(deps, workspaceId, connection.providerId, connection.token);
  try { if (probe.accountLabel !== null) assertPlainAccountLabel({ value: probe.accountLabel }); } catch { probe.accountLabel = null; }
  if (probe.accountLabel !== null) {
    // This is the saved revision, not a new read's revision: an old probe must not heal a rotation.
    try { await deps.repo.vault!.patchMeta({ workspaceId: summary.workspaceId, id: summary.id,
      expectedRevision: summary.revision, patch: { accountLabel: assertPlainAccountLabel({ value: probe.accountLabel }) }, updatedAt: summary.updatedAt }); }
    catch { /* A metadata failure does not undo the saved token. */ }
  }
  return { ...vaultSummary({ summary }), accountLabel: probe.accountLabel, connection: probe.connection };
}
function assertPlainAccountLabel({ value }: { value: string }, _options = {}): string {
  assertPlainField({ value, field: "accountLabel" });
  return value;
}

export interface UpdateSourceControlCredentialInput {
  workspaceId: UUID;
  id: UUID;
  /** Omitted = leave the label unchanged. */
  label?: unknown;
  /** Omitted = leave the stored connection (and its provider) untouched. */
  connection?: unknown;
  /** `true` selects the destination default. Omitted/`false` preserves a same-provider default;
   * a move uses the destination group's default/first-row rule. */
  isDefault?: unknown;
}

/** Omitted/blank tokens keep the envelope; explicit rotations reset and re-probe the label.
 * @param required Explicit store ports and update input. @returns A summary with no secret fields.
 * @throws {SourceControlCredentialValidationError} Invalid or unavailable destination/fields.
 * Metadata updates for an unchanged opaque id need neither a provider nor decryption. */
export async function updateSourceControlCredential(
  { deps, input }: { deps: SourceControlCredentialWriteDeps; input: UpdateSourceControlCredentialInput },
  _options = {},
): Promise<SourceControlCredentialSummary> {
  // Changed where it lives: this site's own row, else the project's attached row.
  const located = await locateById(deps, input);
  if (!located) throw new SourceControlCredentialNotFoundError(`no source control credential '${input.id}' in this workspace`);
  const { scoped, record: existing } = located;
  const label = input.label !== undefined ? validateLabel(input.label) : existing.label;
  const requestedDefault = optionalBoolean(input.isDefault, "isDefault");
  const row = await scoped.deps.repo.vault!.find({ workspaceId: scoped.workspaceId, id: input.id });
  if (!row) throw new SourceControlCredentialNotFoundError(`no source control credential '${input.id}' in this workspace`);
  const where = credentialScope({ workspaceId: scoped.workspaceId, kind: "source-control" });
  const patch = await normalizeConnectionPatch({ raw: input.connection, existing: existing.providerId, registry: () => credentialRegistry({ deps, workspaceId: input.workspaceId }) });
  if (patch !== undefined && !isEmptyTokenPatch({ value: patch })) {
    const connection = validateConnection({ raw: patch, registry: await credentialRegistry({ deps, workspaceId: input.workspaceId }) });
    await assertMoveFreeOnSite({ deps, scoped, existing, workspaceId: input.workspaceId, providerId: connection.providerId, label });
    const summary = await saveConnection({ deps: scoped.deps, input: { ...where, id: input.id,
      expectedRevision: row.revision, provider: connection.providerId, label, payload: { ...connection }, hintToken: connection.token,
      meta: { ...row.meta, accountLabel: null }, ...(requestedDefault === true ? { isDefault: true } : {}) } });
    return { ...await probeSavedConnection({ deps: scoped.deps, summary, connection, workspaceId: input.workspaceId }), ...reportedScope(deps, scoped) };
  }
  await assertBlankPatchChangesNoField({ patch, registry: () => credentialRegistry({ deps, workspaceId: input.workspaceId }) });
  const provider = await preservedProvider({ raw: patch, existing: existing.providerId, registry: () => credentialRegistry({ deps, workspaceId: input.workspaceId }) });
  await assertMoveFreeOnSite({ deps, scoped, existing, workspaceId: input.workspaceId, providerId: provider, label });
  // Omitting payload retains ciphertext/hints without a key; Jini owns both groups' defaults.
  const summary = await saveConnection({ deps: scoped.deps, input: { ...where, id: input.id,
    expectedRevision: row.revision, provider, label,
    meta: { ...row.meta, accountLabel: provider === existing.providerId ? row.meta.accountLabel : null },
    ...(requestedDefault === true ? { isDefault: true } : {}) } });
  return { ...vaultSummary({ summary }), connection: "saved", ...reportedScope(deps, scoped) };
}

/**
 * Deletes a credential set. No-op (not an error) if no row exists for `(workspaceId, id)` — matches
 * `SourceControlCredentialSetRepoPort.delete`'s own idempotent contract and this feature's `DELETE`
 * route's documented 204-always behavior. If the deleted row was its provider's default,
 * `SourceControlCredentialSetRepoPort.delete` itself promotes the group's next candidate.
 *
 * @complexity O(1) at this layer (the repo's own promotion work is O(n) in the small provider
 *   group).
 */
export async function deleteSourceControlCredential(deps: SourceControlCredentialReadDeps, input: { workspaceId: UUID; id: UUID }): Promise<void> {
  // A project row is removed only when no other site uses it, with its attachments.
  const located = await locateById({ ...deps, repo: credentialDeletionRepo({ repo: deps.repo }) }, input);
  if (located) await located.scoped.deps.repo.delete({ workspaceId: located.scoped.workspaceId, id: input.id });
}

/** Select from this view's inventory: a visible default wins, else exactly one eligible row.
 * A project-wide default may belong to another site. Never mutate it or guess among nondefaults.
 * `claimed` holds the labels an earlier (site) store already has for this host: those project rows
 * are overridden (as {@link listEffective} hides them), so they are never the fallback. This store's
 * labels are added to it for the next store.
 * @complexity O(visible credentials); the attached read view enforces site eligibility.
 */
async function selectSourceControlCredential({ repo, workspaceId, providerId, claimed }: {
  repo: SourceControlCredentialSetRepoPort; workspaceId: UUID; providerId: SourceControlProviderId; claimed: Set<string>;
}, _options = {}): Promise<SourceControlCredentialSetRecord | null> {
  const all = await repo.listByProvider({ workspaceId, providerId });
  const rows = all.filter(row => !claimed.has(row.label));
  for (const row of all) claimed.add(row.label);
  return rows.find(row => row.isDefault) ?? (rows.length === 1 ? rows[0]! : null);
}

/** The selected credential's metadata for a host, never decrypted: this site's, else the project's. */
export async function findDefaultSourceControlCredential(deps: SourceControlCredentialReadDeps,
  input: { workspaceId: UUID; providerId: SourceControlProviderId }): Promise<SourceControlCredentialSetRecord | null> {
  const claimed = new Set<string>();
  for (const scoped of credentialScopes(deps, input.workspaceId)) {
    const found = await selectSourceControlCredential({ repo: scoped.deps.repo, workspaceId: scoped.workspaceId, providerId: input.providerId, claimed });
    if (found) return found;
  }
  return null;
}

/** The first store's selected credential for the host: this site's, else the attached project's.
 * @complexity O(attached inventory); opening retains the vault's context and authentication checks. */
async function findDefaultOpened(deps: { repo: SourceControlCredentialSetRepoPort; sealer: SecretSealerPort }, input: { workspaceId: UUID; providerId: SourceControlProviderId }) {
  const claimed = new Set<string>();
  for (const scoped of credentialScopes(deps, input.workspaceId)) {
    const selected = await selectSourceControlCredential({ repo: scoped.deps.repo, workspaceId: scoped.workspaceId, providerId: input.providerId, claimed });
    if (!selected) continue;
    // The attached-only inventory can select a sole nondefault without changing the project's default.
    // Open by identity so the default-only reader does not reject that valid selection.
    // The expected group makes Jini refuse a stale selection from another group before opening it.
    const resolved = await vault(scoped.deps).get({ ...credentialScope({ workspaceId: scoped.workspaceId, kind: "source-control" }), id: selected.id }, { provider: input.providerId });
    if (resolved) return resolved;
  }
  return null;
}

/** Resolve exactly one eligible credential through Jini's context-checked open. Genuine decrypt
 * failures stay typed: this runs in the daemon as well as the HTTP process. */
export async function resolveDefaultForSourceControl(
  deps: { repo: SourceControlCredentialSetRepoPort; sealer: SecretSealerPort },
  input: { workspaceId: UUID; providerId: SourceControlProviderId }
): Promise<{ id: UUID; label: string; connection: SourceControlConnectionInput } | null> {
  try {
    // This site's default first (a site with any row for the host has one), else the project's.
    const resolved = await findDefaultOpened(deps, input);
    if (!resolved) return null;
    if (!resolved.payload) throw new SourceControlCredentialSecretStoreUnconfiguredError(CREDENTIAL_MESSAGES.storage);
    // Reading a saved connection never requires its plugin or reinterprets its paired fields.
    const connection = { ...resolved.payload, providerId: resolved.summary.provider,
      token: normalizeStoredToken({ value: resolved.payload.token }) } as SourceControlConnectionInput;
    return { id: resolved.summary.id, label: resolved.summary.label, connection };
  } catch { throw new SourceControlCredentialSecretStoreUnconfiguredError(CREDENTIAL_MESSAGES.storage); }
}

