/**
 * @file This domain's agent-tool catalog + wiring — mirrors `features/deployments/
 * publish-agent-tools.ts`'s shape closely (that file's own header explains the MCP-UI held-open
 * exchange gate this reuses; not re-derived here).
 *
 * Three tools:
 * - `credential_save with kind source-control` — opens a provider-defined human form and creates a sealed connection; no secret crosses the model boundary.
 * - `source_control_get_capabilities` — read-only, risk `"none"`: reports which providers (github,
 *   gitlab, bitbucket) have a saved credential, by id/label/isDefault/timestamps only — never a
 *   token. Deliberately does NOT report a verified/ready tri-state the way
 *   `deployment_get_static_publish_capabilities` does for its own five providers — there is no
 *   `verify.ts` equivalent for `source_control_credential_sets` yet, and fabricating one would
 *   reproduce the exact false-positive defect that file's own header describes fixing (`configured:
 *   true` here means only "a credential row exists," stated plainly in this tool's description).
 *   Also reports `commitSupported` per provider — `true` when an enabled Agent Plugin provides that
 *   host (`provider-registry.ts`; the bundled `github` plugin today) — so a workspace that saved a
 *   credential for a host no plugin serves learns from THIS tool that committing isn't available,
 *   never from a failed commit attempt (2026-08-16 review requirement).
 * - `source_control_execute_commit` performs an authorized Git commit after the shared approval gate. Provider,
 *   credential, target and branch checks still apply; existing Git history preserves overwritten
 *   files. Credentials remain server-side and are never included in the model's call or result.
 */

interface AgentToolDefinition {
  name: string;
  description: string;
  sideEffects: AgentToolSideEffect;
  authorization: { permission: string };
  inputSchema?: Readonly<Record<string, unknown>>;
}

/** No arguments — matches `publish-agent-tools.ts`'s own `NO_INPUT_SCHEMA`, declared separately here
 *  per this file's own "no dependency on `features/deployments/**`" rule. */
const NO_INPUT_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: [],
  properties: {},
} as const;

/** A declared host's facts as `source_control_get_capabilities` reports them. @complexity O(1). */
function hostFacts(descriptor: SourceControlProviderDescriptor): { label: string; apiOrigin: string; maxFileBytes?: number } {
  return { label: descriptor.label, apiOrigin: descriptor.apiOrigin, ...(descriptor.maxFileBytes !== undefined ? { maxFileBytes: descriptor.maxFileBytes } : {}) };
}

/**
 * The hosts `source_control_get_capabilities` reports, in order: the ones an enabled plugin provides
 * (registry order), then ones a switched-off plugin declares, then any other host a credential is
 * saved for. No host id is hard-coded here; the registry and the saved rows are the whole list.
 *
 * @complexity O(p + s) providers plus saved credentials.
 */
function reportedProviderIds(registry: SourceControlProviderRegistry, savedProviderIds: readonly string[]): readonly string[] {
  const ids = [...registry.list().map((loaded) => loaded.descriptor.id), ...(registry.switchedOff?.keys() ?? []), ...savedProviderIds];
  return [...new Set(ids)];
}

/** The loader for the workspace's plugin-provided hosts ({@link SourceControlToolDeps.loadSourceControlProviders}),
 *  resolved once here so `credential-setup.ts` takes it as a required port. */
function providerLoader(deps: SourceControlToolDeps): LoadSourceControlProviders {
  return deps.loadSourceControlProviders;
}

/** The injected adapter, or the plugin provider's for `providerId`; a caller-safe refusal otherwise. */
async function resolveCommitAdapter(deps: SourceControlToolDeps, providerId: string): Promise<{ ok: true; adapter: SourceControlCommitAdapter } | { ok: false; message: string }> {
  if (deps.gitAdapter) return { ok: true, adapter: deps.gitAdapter };
  const built = await buildSourceControlProvider({ load: deps.loadSourceControlProviders, observability: deps.observability, workspaceId: deps.workspaceId, providerId });
  return built.ok ? { ok: true, adapter: { commit: built.provider.commitSite } } : { ok: false, message: built.message };
}

/**
 * The host's display name for `providerId` and its plugin's own owner/repo check, refusing an id no
 * plugin declares and no credential can be saved for (a typo, or a host that does not exist) before
 * anything else runs. A switched-off or saved-only host has no check of its own; the generic rule in
 * `validateCommitTarget` still applies.
 *
 * @throws {ToolInputError} naming the hosts that do exist.
 * @complexity One registry load and, for a saved-only id, one authorized metadata lookup.
 */
async function requireKnownHost({ deps, providerId, authorizeSavedLookup }: {
  deps: SourceControlToolDeps; providerId: string; authorizeSavedLookup: () => Promise<void>;
}, _options = {}): Promise<{ label: string; validateTarget?: RepositoryTargetValidator }> {
  const registry = await providerLoader(deps)(deps.workspaceId);
  const loaded = registry.get(providerId);
  if (loaded !== undefined) return { label: loaded.descriptor.label, ...(loaded.module.validateTarget ? { validateTarget: loaded.module.validateTarget } : {}) };
  if (registry.switchedOff?.has(providerId)) return { label: providerId };
  // Saved-only ids are opaque. Authorize before inspecting their existence (registry metadata is public).
  await authorizeSavedLookup();
  if (await findSavedDefault({ deps, providerId })) return { label: providerId };
  const hosts = registry.list().map((loaded) => `'${loaded.descriptor.id}'`);
  throw new ToolInputError({ message: `source_control_execute_commit: '${providerId}' is not a source control host. ${hosts.length > 0 ? `Hosts: ${hosts.join(", ")}` : "No turned-on Agent Plugin provides one"} (see source_control_get_capabilities).` });
}

/** Saved default metadata for any opaque id, never decrypted; null when no default exists. */
async function findSavedDefault({ deps, providerId }: { deps: SourceControlToolDeps; providerId: string }, _options = {}) {
  return findDefaultSourceControlCredential({ repo: deps.sourceControlCredentialSetRepo }, { workspaceId: deps.workspaceId, providerId });
}

const EXECUTE_COMMIT_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["provider", "owner", "repo", "commitMessage"],
  properties: {
    provider: {
      type: "string",
      description:
        "Which source control host to commit to: a providerId source_control_get_capabilities lists with commitSupported: true. Call that first; a host listed with commitSupported: false is refused.",
    },
    owner: { type: "string", description: "Owner or organization login that owns the target repository on the host." },
    repo: { type: "string", description: "Repository name to commit to." },
    branch: {
      type: "string",
      description:
        "Branch to commit to. Optional; when omitted, the repository's own default branch is used. If the named branch does not exist yet, it is created from this commit. If it exists, this commit is added on top of its current history. NEVER force-pushed: if the branch has moved since this call read its head (someone else pushed to it), the commit is refused rather than overwriting that history, and the result is {committed:false, code:'DIVERGED_BRANCH'}.",
    },
    commitMessage: { type: "string", description: "The git commit message. 1-500 characters." },
    dryRun: {
      type: "boolean",
      description:
        "Pass dryRun: true first to see how many files the export would commit, without contacting the host. Optional; defaults to false.",
    },
  },
} as const;

/**
 * This domain's fixed agent-tool catalog. Every entry is wired.
 *
 * @complexity O(1) — a fixed, statically-defined list.
 */
export const sourceControlAgentToolCatalog: AgentToolDefinition[] = [

  {
    name: "source_control_get_capabilities",
    description:
      "Reports the source control hosts for this workspace — every host a turned-on Agent Plugin provides, every host a plugin declares but is switched off, and every host that has a saved connection — WITHOUT decrypting or exposing any credential. For each provider: providerId; label, apiOrigin (the API base URL a saved custom credential for that host points at) and maxFileBytes (the largest single file the host accepts in a push; absent when it declares none), when a plugin declares the host; whether a credential is configured (a row exists — this is presence only, NOT a live verification that the token still works; a saved credential that the host has since revoked still reports configured:true here and would only be discovered as invalid by an actual commit attempt), every named credential set saved for it (id, label, isDefault, createdAt, updatedAt — NEVER a token or any part of one), and whether committing to that provider is supported yet (commitSupported: true only when an enabled Agent Plugin provides committing to that host; a saved credential for an unavailable host is reported honestly here, but source_control_execute_commit will refuse it; do not imply to the user that saving such a credential enables committing). Call this before telling a human what committing would do, before calling source_control_execute_commit, or whenever asked something like 'can I commit, and where'. Do NOT ask the user to paste a token into this chat — a value typed into chat is written into the conversation transcript, which is exactly what this workspace's encrypted credential store exists to avoid; call credential_save with kind source-control to open a human form, which saves it encrypted server-side and never shows it to you.",
    sideEffects: "none",
    authorization: { permission: "source-control.read" },
    inputSchema: NO_INPUT_SCHEMA,
  },
  {
    name: "source_control_execute_commit",
    description:
      "Commits a fresh site export to a source control repository using its saved credential. Requires human approval before exporting to the remote repository with {provider, owner, repo, commitMessage, branch?}; provider must be listed by source_control_get_capabilities with commitSupported:true. Pass dryRun:true to preview files and bytes without contacting the host. Returns {committed:true, owner, repo, branch, branchCreated, commitSha, commitUrl, filesChanged, filesDeleted, divergedPaths}. Reports deleted and diverged paths; only previously exported paths whose live content still matches the export may be removed. Other files and human edits are preserved. Git history retains prior content. Returns {committed:false, reason, message} when the credential or provider is unavailable, and {committed:false, cancelled:false, code, message} when the commit itself fails. Never accepts or exposes a token. Requires source-control.commit.",
    // Genuinely consequential (pushes a real commit into someone's actual git history using a
    // write-scoped external credential) — classified accordingly, cross-checked against
    // `sourceControlDerivedRisk` below at build time. Deliberately carries NO `actorClassRule` — see
    // this file's header for why the MCP-UI held-open exchange gate needs none.
    sideEffects: "mutates-durable-state",
    authorization: { permission: "source-control.commit" },
    inputSchema: EXECUTE_COMMIT_SCHEMA,
  },
];

const CATALOG_BY_ID = indexCatalogById({ catalog: sourceControlAgentToolCatalog });

/**
 * This wiring layer's OWN risk classification, independent of the catalog's `sideEffects` declaration
 * (`@jini-ai/cms/core`'s `assertToolIsWirable` cross-checks the two).
 */
export const sourceControlDerivedRisk: DerivedRiskByToolId = new Map<string, AgentToolSideEffect>([
  // -> `listSourceControlCredentials` (a pure DB read, never decrypts) plus a plain `.length > 0`
  // presence check. No decrypt, no network call.
  ["source_control_get_capabilities", "none"],
  // -> proposeSourceControlCredential -> createSourceControlCredential: seals and inserts a saved connection after human submit.

  // -> calls `commitSiteToSourceControl`: a real `exportSite` pass plus a real GitHub Git
  // Data API commit using a write-scoped credential — genuinely mutates external durable state.
  ["source_control_execute_commit", "mutates-durable-state"],
]);

/**
 * The exact slice of the route-deps bag this domain's tool handlers read. Declared structurally
 * (rather than importing `server/routes/types`'s `RouteDeps`) so this module carries no back-edge
 * into the composition root — same discipline `comments/tool-registrations.ts`'s `CommentsToolDeps`
 * documents for its own narrowing.
 *
 * exportSiteBound is closed over the full application dependencies at the composition root.
 * Passing that one pre-bound operation lets the tool run a real export without importing the
 * composition root's wide RouteDeps type; route callers satisfy the narrower shape structurally.
 */
export interface SourceControlToolDeps {
  readonly loadPluginCredentialCards?: LoadPluginCredentialCards;
  readonly authorize: AuthorizeFn;
  readonly workspaceId: string;
  readonly sourceControlCredentialSetRepo: SourceControlCredentialSetRepoPort;
  readonly siteAssistantSecretSealer: SecretSealerPort;
  readonly siteAssistantSecretKeyring: KeyringPort;
  readonly clock: Clock;
  /** Overrides only the existing save-time provider identity probe in tests. */
  readonly fetchFn?: typeof fetch;
  /** `RouteDeps.observability`: a commit's git-host calls are outbound spans. */
  readonly observability?: ObservabilityPort;
  readonly sourceControlExportRootDir: string;
  readonly idGen: { newId(): string };
  /** See `commit-site.ts`'s `ExportSiteBoundFn` doc for what this is and why it replaces the
   *  `routeDeps: RouteDeps` field `commitSiteToSourceControl`'s input used to carry. */
  readonly exportSiteBound: ExportSiteBoundFn;
  /** Overrides the plugin provider's commit adapter, which is the default when this is omitted.
   *  Tests inject a fake here. */
  readonly gitAdapter?: SourceControlCommitAdapter;
  /** This workspace's git-host providers; the installed, enabled Agent Plugins supplied by composition. */
  readonly loadSourceControlProviders: LoadSourceControlProviders;
}

const EXECUTE_COMMIT_TOOL_ID = "source_control_execute_commit";

/** The validated, typed shape of `source_control_execute_commit`'s input, once parsed. */
interface ParsedCommitCommand {
  provider: string;
  owner: string;
  repo: string;
  commitMessage: string;
  branch: string | undefined;
  dryRun: boolean;
}

/** Reads `source_control_execute_commit`'s raw input; {@link requireValidTarget} checks it once the
 *  host is known. @throws {ToolInputError} on a missing or non-string required field, or a present
 *  non-string `branch` (dropping it would commit to the default branch the model did not name). */
function parseCommitCommand(raw: Record<string, unknown>): ParsedCommitCommand {
  const provider = requireString({ input: raw, key: "provider" });
  const owner = requireString({ input: raw, key: "owner" });
  const repo = requireString({ input: raw, key: "repo" });
  const commitMessage = requireString({ input: raw, key: "commitMessage" });
  if (raw.branch !== undefined && typeof raw.branch !== "string") {
    throw new ToolInputError({ message: `${EXECUTE_COMMIT_TOOL_ID}: 'branch' must be a string when provided` });
  }
  const branch = raw.branch;
  const dryRun = optionalBoolean({ input: raw, key: "dryRun" }) ?? false;
  return { provider, owner, repo, commitMessage, branch, dryRun };
}

/**
 * The owner/repo/branch/commitMessage shape via `validateCommitTarget`, with the host plugin's own
 * owner/repo rules first. Runs before any permission check or dialog.
 *
 * @throws {ToolInputError} on any invalid field.
 * @complexity O(1).
 */
function requireValidTarget(command: ParsedCommitCommand, validateTarget: RepositoryTargetValidator | undefined): void {
  const { owner, repo, branch, commitMessage } = command;
  const configError = validateCommitTarget({ owner, repo, ...(branch !== undefined ? { branch } : {}), commitMessage }, validateTarget);
  if (configError !== null) {
    throw new ToolInputError({ message: `source_control_execute_commit: ${configError}` });
  }
}

/**
 * Maps `commitSiteToSourceControl`'s outcome to the tool's result shape — the failure branch stays
 * a typed `{code, message}` pass-through, the success branch reports every field a human or a
 * follow-up call might need, including `divergedPaths` (see the field's own doc at the call site).
 */
function buildCommitOutcomeResult(outcome: SourceControlCommitOutcome): unknown {
  if (!outcome.ok) {
    return { committed: false, cancelled: false, code: outcome.code, message: outcome.message };
  }
  return {
    committed: true,
    owner: outcome.owner,
    repo: outcome.repo,
    branch: outcome.branch,
    branchCreated: outcome.branchCreated,
    commitSha: outcome.commitSha,
    commitUrl: outcome.commitUrl,
    filesChanged: outcome.filesChanged,
    filesDeleted: outcome.filesDeleted,
    // Paths this tool previously committed that the current export dropped, but did NOT delete —
    // their live content no longer matches what this tool itself last wrote (or pre-dates this
    // tool's ability to verify that at all). See `commit-site.ts`'s `SourceControlCommitOutcome`
    // doc. Surfaced so the human is told exactly what survived and why, not just a bare count.
    divergedPaths: outcome.divergedPaths,
  };
}

/**
 * Builds this domain's `guidance` string for `source_control_get_capabilities` — extracted purely for
 * readability, same reasoning `publish-agent-tools.ts`'s own `buildCapabilityGuidance` gives.
 * `undefined` means "nothing to tell the human" (configured AND commit-supported).
 *
 * @complexity O(1) — fixed string interpolation, no iteration.
 */
function buildCapabilityGuidance(providerId: string, configured: boolean, commitReady: boolean, switchedOffPluginId: string | undefined): string | undefined {
  const switchOn = switchedOffPluginId === undefined ? "" : `: ${switchedOffPluginSentence(switchedOffPluginId)}`;
  if (!configured && !commitReady) {
    return `No ${providerId} credential is saved, and no enabled Agent Plugin supports committing to ${providerId}${switchOn || "."}`;
  }
  if (!configured) {
    // Demo dry run 2026-10-05: the token form opened before the person had heard any of this.
    return `No ${providerId} credential is saved yet. First tell the person what is needed and ask which repository (owner/name) to use: ` +
      "for a site backup it must be private and already have at least one commit (for example a README), and the token needs " +
      "Contents read and write on it. Then call credential_save with kind source-control to open the human credential form.";
  }
  if (!commitReady) {
    return `A ${providerId} credential is saved, but no enabled Agent Plugin supports committing to ${providerId}${switchOn || "."}`;
  }
  return undefined;
}

/**
 * Builds this domain's `ToolRegistration[]` — same shape every other domain's
 * `build<Domain>Registrations` produces.
 *
 * @param deps - `SourceControlToolDeps` (the narrow slice of `RouteDeps` this domain reads, plus
 *   this file's own test-only `gitAdapter` override).
 * @param surfaces - The surface exchange store used by the credential setup forms; commits run
 *   on — required, matching `buildStaticPublishRegistrations`' own shape.
 * @complexity O(1) registration-time cost; each wired handler's own cost is documented at its call
 *   site above.
 */
/** Bind the source-control credential owner with the same installed-provider loader as other tools.
 * @param required - Existing domain dependencies and shared surface exchanges.
 * @returns Internal save adapter; permissions and errors remain domain-owned.
 * @example buildSourceControlCredentialHandler({ deps, surfaces });
 * @complexity O(1) binding; provider/save costs are documented by proposeSourceControlCredential.
 */
export function buildSourceControlCredentialHandler({ deps, surfaces }: { deps: SourceControlToolDeps; surfaces: AssistantSurfaceDeps }, _optional = {}): ToolHandler {
  return (ctx, optional = {}) => proposeSourceControlCredential({ ctx, deps: { ...deps, loadSourceControlProviders: providerLoader(deps) }, surfaces }, optional);
}

export function buildSourceControlRegistrations(deps: SourceControlToolDeps, surfaces: AssistantSurfaceDeps): ToolRegistration[] {
  const handlers: Record<string, ToolHandler> = {
    source_control_get_capabilities: async (ctx) => {
      requireNoInput({ input: ctx.input });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "source-control.read" }, { entityType: "source-control" });

      const saved = await listSourceControlCredentials({ repo: deps.sourceControlCredentialSetRepo }, { workspaceId: deps.workspaceId });
      const registry = await providerLoader(deps)(deps.workspaceId);

      const providers = reportedProviderIds(registry, saved.map((credential) => credential.providerId)).map((providerId) => {
        const savedCredentials = saved
          .filter((credential) => credential.providerId === providerId)
          .map((credential) => ({ id: credential.id, label: credential.label, isDefault: credential.isDefault, createdAt: credential.createdAt, updatedAt: credential.updatedAt }));
        const configured = savedCredentials.length > 0;
        const loaded = registry.get(providerId);
        const ready = loaded !== undefined;
        const guidance = buildCapabilityGuidance(providerId, configured, ready, registry.switchedOff?.get(providerId));

        return {
          providerId,
          ...(loaded ? hostFacts(loaded.descriptor) : {}),
          configured,
          commitSupported: ready,
          savedCredentials,
          ...(guidance !== undefined ? { guidance } : {}),
        };
      });

      return { providers };
    },

    /** Shared approval precedes real export commits, which can remove stale paths;
     * dry-run previews stay direct. Target, credential and branch checks remain. */
    source_control_execute_commit: async (ctx) => {
      const raw = requireInputRecord({ input: ctx.input });
      const command = parseCommitCommand(raw);

      const authorizeCommit = () => requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: deps.authorize }), workspaceId: deps.workspaceId, principalId: ctx.principal.id, permission: "source-control.commit" }, { entityType: "source-control" });
      const host = await requireKnownHost({ deps, providerId: command.provider, authorizeSavedLookup: authorizeCommit });
      const hostLabel = host.label;
      requireValidTarget(command, host.validateTarget);
      await authorizeCommit();

      if (command.dryRun) {
        // Same "presence only" read `source_control_get_capabilities` and the real-commit path
        // below both rely on — never decrypts. No dialog: a dry run only previews what a real
        // commit would export, so it never opens the confirmation surface or touches `emitSurface`.
        const existing = await findSavedDefault({ deps, providerId: command.provider });
        const preview = await previewCommitExport({
          workspaceId: deps.workspaceId,
          sourceControlExportRootDir: deps.sourceControlExportRootDir,
          idGen: deps.idGen,
          exportSiteBound: deps.exportSiteBound,
          owner: command.owner,
          repo: command.repo,
          ...(command.branch !== undefined ? { branch: command.branch } : {}),
          commitMessage: command.commitMessage,
        }, { providerId: command.provider, validateTarget: host.validateTarget });
        if (!preview.ok) {
          return {
            dryRun: true,
            committed: false,
            owner: command.owner,
            repo: command.repo,
            branch: command.branch,
            credentialConfigured: existing !== null,
            code: preview.code,
            message: preview.message,
          };
        }
        return {
          dryRun: true,
          committed: false,
          owner: command.owner,
          repo: command.repo,
          branch: command.branch,
          credentialConfigured: existing !== null,
          fileCount: preview.fileCount,
          totalBytes: preview.totalBytes,
          paths: preview.paths,
          note: "Nothing was sent. Call again without dryRun to commit.",
        };
      }

      // Never decrypts — a plain repo read, same "presence only" contract `source_control_get_capabilities`
      // relies on. Checked before raising any dialog so a guaranteed-fail call never wastes a human's
      // attention.
      const existing = await findSavedDefault({ deps, providerId: command.provider });
      if (!existing) {
        return {
          committed: false,
          reason: "no-credential",
          message: `No ${hostLabel} source control credential is configured for this workspace. Call credential_save with kind source-control to open a human credential form before committing.`,
        };
      }
      const commitAdapter = await resolveCommitAdapter(deps, command.provider);
      if (!commitAdapter.ok) return { committed: false, reason: "no-provider", message: commitAdapter.message };

      // The run ended during the pre-dialog reads: no dialog, and no call left waiting on an abort already past.
      if (ctx.signal.aborted) return { committed: false, cancelled: false, reason: "abandoned" };
      const outcome = await commitSiteToSourceControl(
        { providerId: existing.providerId, credentialDeps: { repo: deps.sourceControlCredentialSetRepo, sealer: deps.siteAssistantSecretSealer }, gitAdapter: commitAdapter.adapter, ...(host.validateTarget ? { validateTarget: host.validateTarget } : {}) },
        {
          workspaceId: deps.workspaceId,
          sourceControlExportRootDir: deps.sourceControlExportRootDir,
          idGen: deps.idGen,
          exportSiteBound: deps.exportSiteBound,
          owner: command.owner,
          repo: command.repo,
          ...(command.branch !== undefined ? { branch: command.branch } : {}),
          commitMessage: command.commitMessage,
        }
      );

      return buildCommitOutcomeResult(outcome);

    },
  };

  // No `unwiredToolIds`: this domain wires its ENTIRE catalog — a 3rd catalog entry added without a
  // handler fails the build.
  return buildDomainRegistrations({ metadata: toolMetadata,
    domain: "source-control",
    catalogModule: "features/source-control/tool-registrations.ts",
    catalog: CATALOG_BY_ID,
    handlers,
    derivedRisk: sourceControlDerivedRisk,
  });
}

/**
 * Contributes Source Control's AI tools; called once by the composition root's
 * `installFirstPartyToolContributors()`, never as an import side effect.
 * Credential resolution is injected with structural signatures; importing this feature from
 * credential discovery would close a runtime cycle back through the assistant.
 */
export function contributeSourceControlTools(): ToolContributor {
  return { domain: "source-control", build: buildSourceControlRegistrations, risk: sourceControlDerivedRisk };
}

import type { VaultRepoPort } from "@jini-ai/platform/secrets/credential-sets";
import type { CredentialTokenHint, CredentialConnection } from '../../contracts/core/credential-token.js';
import type { ISODateTime, UUID } from "@jini-ai/core/primitives";

import type { SealedSecret } from "../webhooks/index.js";
import type { CredentialProjectHalf } from "../vendor-credentials/project-scope.js";

/** Source-control identities are separate from deploy targets: they carry authentication,
 * never a repository, owner or branch. The store seals the complete connection as one blob.
 * Provider ids and saved fields remain opaque when their plugin is absent. */
export type SourceControlProviderId = string;

/** New writes follow the provider's existing credential declaration; persisted fields survive reads. */
export interface SourceControlConnectionInput {
  readonly providerId: SourceControlProviderId;
  readonly token: string;
  readonly [field: string]: string;
}

/** A `source_control_credential_sets` row, decrypted-shape (`sealed` is the DB's opaque
 *  `SealedSecret` — nothing in this feature decrypts it yet; see this file's header on the
 *  connect-an-identity-only scope). */
export interface SourceControlCredentialSetRecord {
  readonly tokenHint?: CredentialTokenHint | null;
  readonly workspaceId: UUID;
  readonly id: UUID;
  readonly providerId: SourceControlProviderId;
  readonly label: string;
  readonly sealed: SealedSecret;
  /** At most one `TRUE` per `(workspaceId, providerId)`, maintained by `store.ts`'s write path —
   *  see `src/platform/db/schema.sqlite.ts`'s `sourceControlCredentialSets.isDefault` doc. */
  readonly isDefault: boolean;
  /** Verified account label, or null when no provider identity probe succeeds. */
  readonly accountLabel: string | null;
  readonly createdAt: ISODateTime;
  readonly updatedAt: ISODateTime;
}

/** The read model every route in this feature returns — see `store.ts`'s `toSummary`. NEVER
 *  contains `sealed`, a token, or any `SourceControlConnectionInput` field — enforced by
 *  construction: this type has no field capable of carrying one. */
export interface SourceControlCredentialSummary {
  readonly tokenHint?: CredentialTokenHint | null;
  readonly connection?: CredentialConnection;
  readonly id: UUID;
  readonly providerId: SourceControlProviderId;
  readonly label: string;
  readonly configured: true;
  readonly isDefault: boolean;
  /** See `SourceControlCredentialSetRecord.accountLabel`'s own doc — carried through unchanged. */
  readonly accountLabel: string | null;
  /** Where the row lives — present only where a project store is attached (local web + desktop):
   *  `"project"` is visible to attached sites only, `"site"` is this site's own (an override). */
  readonly scope?: "site" | "project";
  readonly createdAt: ISODateTime;
  readonly updatedAt: ISODateTime;
}

/** Workspace-scoped persistence for {@link SourceControlCredentialSetRecord} (ADR-007 §1). `insert`
 *  assumes the caller already checked/accepted the `(workspaceId, providerId, label)` UNIQUE
 *  constraint may reject it — see `store.ts`'s `isUniqueLabelViolation` for how that DB error is
 *  turned into `SourceControlCredentialDuplicateLabelError` rather than propagated as a raw driver
 *  error.
 *
 * `insert`/`update`/`delete` ALSO own the `isDefault` invariant, mirroring
 * `VendorCredentialSetRepoPort`'s own contract exactly: if the written `record.isDefault` is
 * `true`, `insert`/`update` atomically clear `isDefault` on every OTHER row sharing
 * `(workspaceId, providerId)`, in the SAME transaction as the write. `delete` promotes the group's
 * most-recently-updated remaining row to default if the deleted row WAS the default. */
export interface SourceControlCredentialSetRepoPort {
  readonly vault?: VaultRepoPort;
  /** The project store this site's rows fall back to (`store.ts`'s scope rule, shared in
   *  `vendor-credentials/project-scope.ts`: site first, then attached project rows; new rows go to the project
   *  unless saved "only for this site"). Absent = site only (Fly/production). */
  readonly project?: CredentialProjectHalf<SourceControlCredentialSetRepoPort>;
  insert(record: SourceControlCredentialSetRecord): Promise<void>;
  /** Full-row replace by `(workspaceId, id)` — used for both a label rename and a connection
   *  rotation. Same UNIQUE-violation possibility as `insert` (renaming into another row's label). */
  update(record: SourceControlCredentialSetRecord): Promise<void>;
  /** Probe metadata must never replace a token rotated while the network request was pending.
   * Adapters may omit this best-effort capability; a save still returns the verified label. */
  updateAccountLabel?(input: { workspaceId: UUID; id: UUID; accountLabel: string; expectedSealed?: SealedSecret }, optional?: {}): Promise<void>;
  findById(input: { workspaceId: UUID; id: UUID }): Promise<SourceControlCredentialSetRecord | null>;
  /** The current default row for one `(workspaceId, providerId)` pair — `null` if that provider has
   *  no rows at all for this workspace. */
  findDefaultByProvider(input: { workspaceId: UUID; providerId: SourceControlProviderId }): Promise<SourceControlCredentialSetRecord | null>;
  /** Every row for one `(workspaceId, providerId)` pair — used by `store.ts`'s write path to decide
   *  "is this the group's first row" (create-time auto-default) and, ahead of `delete`, to reason
   *  about the promotion candidate. */
  listByProvider(input: { workspaceId: UUID; providerId: SourceControlProviderId }): Promise<SourceControlCredentialSetRecord[]>;
  /** Every credential set a workspace has saved, across all providers — inherently small (bounded
   *  by how many connections a human bothers to save through this exact form), so no
   *  pagination/cap is added here. */
  listByWorkspace(input: { workspaceId: UUID }): Promise<SourceControlCredentialSetRecord[]>;
  /** No-op (not an error) if no row exists for `(workspaceId, id)` — matches this feature's own
   *  `DELETE .../credentials/:id` route contract (204, idempotent). */
  delete(input: { workspaceId: UUID; id: UUID }): Promise<void>;
}

import { toolMetadata } from '../../contracts/core/tool-metadata/taxonomy.js';
import { type Clock } from "@jini-ai/core/primitives";
import { adaptLegacyAuthorize } from "@jini-ai/cms/core";
/**
 * @file Taxonomy's half of ADR-049 Decision 4 (SPEC-018/ADR-044): maps `agent-tools.ts`'s 8 catalog
 * entries onto `write-service.ts`'s ordinary mutations, `list.ts`'s read, and `merge-term.ts`'s
 * plan-only slice of the gated-mutation ceremony, as `ToolRegistration`s.
 *
 * Scope: all 8 catalog entries are wired. `taxonomy_execute_merge_term` (2026-09-24) asks the human
 * in chat first: a merge deletes the source term's assignments with no Trash or undo. On the
 * human's click it confirms as that human and executes as the agent acting for them — see
 * `contracts/core/human-confirm.ts`'s `humanConfirmedToolHandler`.
 *
 * Authorization shape, mixed and deliberately so: `createTaxonomy`/`createTerm`/`renameTerm`/
 * `assignTerms` each call `authorizeTaxonomyManage` (`admin.taxonomy.manage`) as their own first line
 * (confirmed directly against `write-service.ts`), so those four handlers must NOT re-check
 * (ADR-021 §2 "one evaluator"). The tagging tools (`taxonomy_assign_terms`/`taxonomy_unassign_terms`)
 * first check a DIFFERENT permission, the content's own edit one (`authorizeContentEdit`), exactly as
 * the admin assign/unassign routes do. `listTaxonomiesWithTerms` (`list.ts`) has no such call of its own —
 * its file header says so explicitly ("no authorization of its own") — so `taxonomy_list`'s handler
 * performs that identical inline check itself, mirroring `taxonomy/list.ts`'s admin route.
 * `taxonomy_plan_merge_term` is a THIRD shape: `core/gated-mutations/gateway.ts`'s `plan()` itself
 * calls `authorize()` unconditionally before `hooks.computePlan()` ever runs (verified directly
 * against that function's body) — mirrors `features/database/tool-registrations.ts`'s identical
 * `database_plan_migrate_forward` precedent, including reusing this domain's own
 * `gated-hooks.ts`'s `buildMergeTermHooks` directly.
 */
import { AGENT_TOOL_PRINCIPAL_KIND, buildDomainRegistrations, indexCatalogById, optionalString, requireInputRecord, requireString, type AgentToolSideEffect, type DerivedRiskByToolId, type ToolHandler, type ToolRegistration } from "@jini-ai/core";
import { type AuthorizeFn, type OutboxPort, requireToolPermission } from "@jini-ai/cms/core";
// `ToolInputError` specifically — see `features/post/tool-registrations.ts`'s identical import
// for why: the marker `@jini-ai/daemon`'s `ToolExecutor` reads to classify a rejection 400 rather
// than redacting it into a message-stripped 500.
import { ToolInputError } from "@jini-ai/core";
import {
  confirm as gatewayConfirm,
  execute as gatewayExecute,
  plan as gatewayPlan,
  type GatewayDeps,
} from "../../contracts/core/gated-mutations/gateway.js";
import { humanConfirmedToolHandler, refuseUnexpectedKeys } from "#src/contracts/core/human-confirm";
import { createSurfaceExchangeStore, type AssistantSurfaceDeps } from "@jini-ai/daemon/surface-exchanges";
import type { ToolContributor } from "#src/assistant/index";
import { ForbiddenError } from "@jini-ai/cms/core";
import { forbiddenRule } from "@jini-ai/core/model-facing-tool-errors";
import { withModelFacingErrors } from "@jini-ai/core/model-facing-tool-errors";
import { toSlug } from "../../platform/html/slug.js";
import type { PostRepoPort } from "../post/index.js";
import { authorizeContentEdit, createContentTargetPorts, createLiveCollectionTermPolicy, type CollectionOwnerLookupPort } from "./collection-term-policy.js";
import { buildMergeTermHooks, type MergeableEntryTermRepoPort } from "./gated-hooks.js";
import { taxonomyAgentToolCatalog } from "./agent-tools.js";
import {
  listTaxonomiesWithTerms,
  isContentTypeOnAllowList,
  confirmMergeTerm,
  executeMergeTerm,
  planMergeTerm,
  toTaxonomyOutbox,
  assignTerms,
  unassignTerms,
  createTaxonomy,
  createTerm,
  renameTerm,
  type TaxonomyListPort,
  type TermListPort,
  type EntryRecordLookupPort,
  type EntryTermRepoPort,
  type TaxonomyRepoPort,
  type TaxonomyRevisionRepoPort,
  type TermRepoPort,
  type ImportableTermRepoPort,
  type UnassignableEntryTermRepoPort,
  type WriteServiceDeps,
  type TransactionalRepoPort,
} from "./index.js";
import { createSystemClock, createRandomUuidGenerator } from "@jini-ai/core/primitives";
import { createTimeoutScheduler } from "@jini-ai/daemon/scheduler";


const CATALOG_BY_ID = indexCatalogById({ catalog: taxonomyAgentToolCatalog });

/**
 * The exact slice of the route-deps bag Taxonomy's tool handlers read. Declared structurally
 * (rather than importing `server/routes/types`'s `RouteDeps`) so this module carries no back-edge
 * into the composition root for the `RouteDeps` god type. This domain's `buildMergeTermHooks`/
 * `MergeableEntryTermRepoPort` now live in this module's own `gated-hooks.ts` (moved out of
 * `server/gated-mutations-composition.ts`, closing the back-edge into `server/` that file's import
 * previously required), so `server/routes/*` satisfies this interface structurally by passing its
 * existing `RouteDeps` object; nothing there changes.
 */
export interface TaxonomyToolDeps {
  authorize: AuthorizeFn;
  workspaceId: string;
  clock: Clock;
  idGen: { newId(): string };
  taxonomyRepo: TaxonomyRepoPort & TaxonomyListPort & TransactionalRepoPort;
  termRepo: TermRepoPort & TermListPort & ImportableTermRepoPort;
  entryTermRepo: EntryTermRepoPort & MergeableEntryTermRepoPort & UnassignableEntryTermRepoPort & {
    listForContent(input: { contentType: string; contentId: string }): Promise<ReadonlyArray<{ termId: string }>>;
  };
  taxonomyRevisionRepo: TaxonomyRevisionRepoPort;
  /** Passed wholesale to `repo.memory.ts`'s `toTaxonomyOutbox` adapter, which reads this field plus
   * `clock`/`idGen` off the same bag rather than taking a pre-built outbox — see that function's own
   * doc comment. */
  outbox: OutboxPort;
  postRepo: PostRepoPort;
  /** With `contentTypeRepo`, lets the tagging tools reach collection entries — the same
   * `createContentTargetPorts` the admin assign/unassign routes use. */
  entryRepo: EntryRecordLookupPort;
  contentTypeRepo: CollectionOwnerLookupPort;
  gatedMutations: { gatewayDeps: GatewayDeps };
  /** See `RouteDeps.stampWatermark`'s doc comment (`server/routes/types.ts`) — same field, this
   * domain's tool-calling deps bag is structurally satisfied by the same composition-root object
   * the admin HTTP routes use. */
  stampWatermark: () => Promise<void> | void;
}

/**
 * This wiring layer's OWN risk classification, authored from what each handler below actually
 * calls. See `DerivedRiskByToolId` in the kit for why it is independent of the catalog's own
 * `sideEffects` declaration.
 */
export const taxonomyDerivedRisk: DerivedRiskByToolId = new Map<string, AgentToolSideEffect>([
  // -> listTaxonomiesWithTerms (list.ts): taxonomies.list() + terms.listByTaxonomy() reads only.
  ["taxonomy_list", "none"],
  // Full live term read, no assignment or revision writes.
  ["taxonomy_get_term", "none"],
  // -> entryTermRepo.listForContent + taxonomyRepo.list + termRepo.listByTaxonomy,
  //    with contentTypeRepo.findByKey for collection validation; reads only.
  ["taxonomy_get_assigned_terms", "none"],
  // -> createTaxonomy (write-service.ts): taxonomies.insert + revisions.insert in effect.
  ["taxonomy_create_taxonomy", "mutates-durable-state"],
  // -> createTerm (write-service.ts): terms.insert + revisions.insert.
  ["taxonomy_create_term", "mutates-durable-state"],
  // -> renameTerm (write-service.ts): terms.update + revisions.insert.
  ["taxonomy_rename_term", "mutates-durable-state"],
  // -> assignTerms (write-service.ts): entryTerms.upsert per termId (INV-05: no revision row, see
  //    that function's own doc comment for the disclosed narrowing this implements).
  ["taxonomy_assign_terms", "mutates-durable-state"],
  // -> unassignTerms (write-service.ts): entryTerms.remove per termId — same INV-05 no-revision-row
  //    narrowing as assignTerms (that function's own doc comment discloses it applies equally here).
  ["taxonomy_unassign_terms", "mutates-durable-state"],
  // -> gateway.ts's plan() via buildMergeTermHooks: authorizes, then recomputes a plan and returns
  //    it — verified directly against plan()'s own body, which persists nothing (AC-10).
  ["taxonomy_plan_merge_term", "none"],
  // -> gateway confirm() (as the human, after their click) + execute() via buildMergeTermHooks:
  //    entryTerms.repointTerm (re-points, then deletes the source rows) + terms.update (deprecate)
  //    + revisions.insert.
  ["taxonomy_execute_merge_term", "mutates-durable-state"],
]);

const MERGE_TOOL_ID = "taxonomy_execute_merge_term";

/** Shared read/assignment validation: posts, pages and live collections can carry terms.
 * @throws {ToolInputError} For widget, unknown or tombstoned collection types.
 * @complexity O(1), at most one indexed content-type read.
 */
async function requireTaggableContentType(deps: TaxonomyToolDeps, contentType: string): Promise<void> {
  if (isContentTypeOnAllowList({ contentType })) return;
  if (await createLiveCollectionTermPolicy(deps).taxonomiesFor({ contentType }) !== null) return;
  throw new ToolInputError({ message: `content type '${contentType}' does not support taxonomy assignments. Use post, page, or a live collection key.` });
}

/** Shared dependency bag for `write-service.ts` calls — every mutating handler here takes this
 * identical shape, mirroring each admin route's own inline construction. */
function taxonomyDeps(routeDeps: TaxonomyToolDeps): WriteServiceDeps {
  return {
    authorize: (params) => routeDeps.authorize({ ...params, workspaceId: routeDeps.workspaceId }),
    clock: routeDeps.clock,
    idGen: routeDeps.idGen,
    taxonomies: routeDeps.taxonomyRepo,
    terms: routeDeps.termRepo,
    entryTerms: routeDeps.entryTermRepo,
    revisions: routeDeps.taxonomyRevisionRepo,
    stampWatermark: routeDeps.stampWatermark,
    outbox: toTaxonomyOutbox(routeDeps),
    workspaceId: routeDeps.workspaceId,
    ...createContentTargetPorts(routeDeps),
  };
}

export function buildTaxonomyRegistrations(
  routeDeps: TaxonomyToolDeps,
  surfaces: AssistantSurfaceDeps = { surfaceExchanges: createSurfaceExchangeStore({ scheduler: createTimeoutScheduler({}), clock: createSystemClock(), idGenerator: createRandomUuidGenerator(), defaultChannel: "mcp-ui" }) },
): ToolRegistration[] {
  const mergeHooks = (ctx: { principal: { id: string } }, fromTermId: string, intoTermId: string) =>
    buildMergeTermHooks({
      workspaceId: routeDeps.workspaceId,
      fromTermId,
      intoTermId,
      actorId: ctx.principal.id,
      clock: routeDeps.clock,
      termRepo: routeDeps.termRepo,
      entryTermRepo: routeDeps.entryTermRepo,
      taxonomyRevisionRepo: routeDeps.taxonomyRevisionRepo,
    });
  const termName = async (id: string) => (await routeDeps.termRepo.findById({ id }))?.name ?? `${id} (not found)`;

  const handlers: Record<string, ToolHandler> = {
    /** Uses the live, workspace-bound repository, including its parent-taxonomy Trash filter. */
    ...withModelFacingErrors({ handlers: { taxonomy_get_term: async (ctx) => {
      const termId = requireString({ input: requireInputRecord({ input: ctx.input }), key: "termId" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.taxonomy.manage" }, { entityType: "term", entityId: termId });
      const term = await routeDeps.termRepo.findByIdFull({ id: termId });
      if (!term) throw new ToolInputError({ message: `term '${termId}' was not found — call content_read.taxonomy to list valid terms` });
      return { term };
    } }, rules: [forbiddenRule({ domainPrefix: "TAXONOMY", error: ForbiddenError })] }),
    taxonomy_list: async (ctx) => {
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.taxonomy.manage" }, { entityType: "taxonomy" });
      return listTaxonomiesWithTerms({ taxonomies: routeDeps.taxonomyRepo, terms: routeDeps.termRepo });
    },

    ...withModelFacingErrors({ handlers: {
      taxonomy_get_assigned_terms: async (ctx) => {
        const input = requireInputRecord({ input: ctx.input });
        const contentType = requireString({ input: input, key: "contentType" });
        const contentId = requireString({ input: input, key: "contentId" });
        await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.taxonomy.manage" }, { entityType: "taxonomy" });
        await authorizeContentEdit(routeDeps, ctx.principal.id, contentType);
        await requireTaggableContentType(routeDeps, contentType);
        const assignments = await routeDeps.entryTermRepo.listForContent({ contentType, contentId });
        if (!assignments.length) return { contentType, contentId, terms: [] };
        const assigned = new Set(assignments.map(row => row.termId));
        // Bulk lists resolve names without one query per assignment. O(all terms + a log a)
        // time, O(all terms) space, a = assigned terms; no assignment or revision writes.
        const { items } = await listTaxonomiesWithTerms({ taxonomies: routeDeps.taxonomyRepo, terms: routeDeps.termRepo });
        const terms = items.flatMap(({ taxonomy, terms }) => terms.filter(term => assigned.has(term.id)).map(term => ({
          termId: term.id, name: term.name, slug: toSlug(term.name), taxonomyId: taxonomy.id, taxonomyName: taxonomy.name,
        })));
        terms.sort((a, b) => a.taxonomyName.localeCompare(b.taxonomyName) || a.name.localeCompare(b.name) || a.termId.localeCompare(b.termId));
        return { contentType, contentId, terms };
      },
    }, rules: [forbiddenRule({ domainPrefix: "TAXONOMY", error: ForbiddenError })] }),

    taxonomy_create_taxonomy: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      const taxonomy = await createTaxonomy({
        deps: taxonomyDeps(routeDeps),
        principalId: ctx.principal.id,
        name: requireString({ input: input, key: "name" }),
        hierarchical: input.hierarchical === true,
      });
      return { taxonomy };
    },

    taxonomy_create_term: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      const term = await createTerm({
        deps: taxonomyDeps(routeDeps),
        principalId: ctx.principal.id,
        taxonomyId: requireString({ input: input, key: "taxonomyId" }),
        name: requireString({ input: input, key: "name" }),
      }, { parentId: optionalString({ input: input, key: "parentId" }) ?? null });
      return { term };
    },

    taxonomy_rename_term: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      const term = await renameTerm({
        deps: { ...taxonomyDeps(routeDeps), transaction: (required) => routeDeps.taxonomyRepo.transaction(required) },
        principalId: ctx.principal.id,
        termId: requireString({ input: input, key: "termId" }),
        newName: requireString({ input: input, key: "newName" }),
      });
      return { term };
    },

    taxonomy_assign_terms: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      const contentType = requireString({ input: input, key: "contentType" });
      const contentId = requireString({ input: input, key: "contentId" });
      if (!Array.isArray(input.termIds) || !input.termIds.every((id: unknown) => typeof id === "string")) {
        throw new ToolInputError({ message: "'termIds' (string array) is required" });
      }
      const termIds = input.termIds as string[];

      // The content's own edit permission first, as the admin route does; assignTerms then checks
      // admin.taxonomy.manage itself.
      await authorizeContentEdit(routeDeps, ctx.principal.id, contentType);
      const deps = taxonomyDeps(routeDeps);
      await assignTerms({
        deps: { ...deps, authorize: async params => {
          const result = await deps.authorize(params);
          // The service owns the taxonomy permission check. Validate the shared content-type
          // contract only after that grant, including empty assignment requests, before writes.
          if (result.allowed) await requireTaggableContentType(routeDeps, contentType);
          return result;
        } },
        principalId: ctx.principal.id, contentType, contentId, termIds,
      });
      return { contentType, contentId, assignedTermIds: termIds };
    },

    taxonomy_unassign_terms: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      const contentType = requireString({ input: input, key: "contentType" });
      const contentId = requireString({ input: input, key: "contentId" });
      if (!Array.isArray(input.termIds) || !input.termIds.every((id: unknown) => typeof id === "string")) {
        throw new ToolInputError({ message: "'termIds' (string array) is required" });
      }
      const termIds = input.termIds as string[];

      await authorizeContentEdit(routeDeps, ctx.principal.id, contentType);
      // `taxonomyDeps(routeDeps)` is typed as the base `WriteServiceDeps` (its `entryTerms` narrowed
      // to plain `EntryTermRepoPort`), but `unassignTerms` needs the `UnassignableEntryTermRepoPort`
      // capability too — override `entryTerms` back to `routeDeps.entryTermRepo`'s own wider type
      // rather than widening `taxonomyDeps`'s return type for every OTHER handler that doesn't need it.
      const { removedTermIds } = await unassignTerms({
        deps: { ...taxonomyDeps(routeDeps), entryTerms: routeDeps.entryTermRepo },
        principalId: ctx.principal.id,
        contentType,
        contentId,
        termIds,
      });
      const removed = new Set(removedTermIds);
      return { contentType, contentId, unassignedTermIds: removedTermIds, notAssignedTermIds: termIds.filter(id => !removed.has(id)) };
    },

    taxonomy_plan_merge_term: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      const fromTermId = requireString({ input: input, key: "fromTermId" });
      const intoTermId = requireString({ input: input, key: "intoTermId" });

      const hooks = buildMergeTermHooks({
        workspaceId: routeDeps.workspaceId,
        fromTermId,
        intoTermId,
        actorId: ctx.principal.id,
        clock: routeDeps.clock,
        termRepo: routeDeps.termRepo,
        entryTermRepo: routeDeps.entryTermRepo,
        taxonomyRevisionRepo: routeDeps.taxonomyRevisionRepo,
      });

      // No explicit pre-check here: `gateway.ts`'s plan() calls authorize() unconditionally, BEFORE
      // hooks.computePlan() ever runs (see `taxonomyDerivedRisk`'s comment for this tool). Adding a
      // second check here would be the duplicate evaluator ADR-021 §2 forbids.
      return planMergeTerm({
        principalId: ctx.principal.id,
        principalKind: AGENT_TOOL_PRINCIPAL_KIND,
        fromTermId,
        intoTermId,
        computeOverlap: async () => ({ overlappingContentCount: await routeDeps.entryTermRepo.countOverlap({ fromTermId, intoTermId }) }),
        gatewayPlan: async () =>
          gatewayPlan({
            deps: routeDeps.gatedMutations.gatewayDeps,
            principalId: ctx.principal.id,
            principalKind: AGENT_TOOL_PRINCIPAL_KIND,
            hooks,
          }),
      });
    },

    // Plans as the agent, asks the human, then confirms as the human and executes as the agent —
    // the gateway's own check sequence (authorize, token, actor-class, plan hash) runs unchanged.
    [MERGE_TOOL_ID]: humanConfirmedToolHandler(surfaces, {
      flag: "merged",
      prepare: async (ctx) => {
        const input = requireInputRecord({ input: ctx.input });
        refuseUnexpectedKeys(input, ["fromTermId", "intoTermId"]);
        const fromTermId = requireString({ input: input, key: "fromTermId" });
        const intoTermId = requireString({ input: input, key: "intoTermId" });
        const hooks = mergeHooks(ctx, fromTermId, intoTermId);
        const plan = await planMergeTerm({
          principalId: ctx.principal.id,
          principalKind: AGENT_TOOL_PRINCIPAL_KIND,
          fromTermId,
          intoTermId,
          computeOverlap: async () => ({ overlappingContentCount: await routeDeps.entryTermRepo.countOverlap({ fromTermId, intoTermId }) }),
          gatewayPlan: async () =>
            gatewayPlan({ deps: routeDeps.gatedMutations.gatewayDeps, principalId: ctx.principal.id, principalKind: AGENT_TOOL_PRINCIPAL_KIND, hooks }),
        });
        return { hooks, plan, fromName: await termName(fromTermId), intoName: await termName(intoTermId) };
      },
      dialog: ({ plan, fromName, intoName }) => ({
        toolId: MERGE_TOOL_ID,
        errorCode: "TAXONOMY",
        title: `Merge ${fromName} into ${intoName}?`,
        details: [
          { label: "Merge away", value: fromName },
          { label: "Keep", value: intoName },
          ...(plan.details.overlappingContentCount > 0
            ? [{ label: "Tagged with both", value: String(plan.details.overlappingContentCount) }]
            : []),
        ],
        warning: `Everything tagged ${fromName} is re-tagged ${intoName}, and ${fromName} is retired. This can't be undone.`,
        danger: true,
        confirmLabel: "Merge terms",
      }),
      run: async (ctx, { hooks, plan }, confirmer) => {
        const { token } = await confirmMergeTerm({
          principalId: confirmer.id,
          principalKind: confirmer.kind,
          planId: plan.planId,
          planHash: plan.planHash,
          gatewayConfirm: async (params) => {
            const record = await gatewayConfirm({
              deps: routeDeps.gatedMutations.gatewayDeps,
              principalId: confirmer.id,
              principalKind: confirmer.kind,
              hooks,
              planId: params.planId,
              planHash: params.planHash,
            });
            return { token: record.confirmationToken };
          },
        });
        const result = await executeMergeTerm({
          confirmationToken: token,
          gatewayExecute: (params) =>
            gatewayExecute({
              deps: routeDeps.gatedMutations.gatewayDeps,
              principalId: ctx.principal.id,
              principalKind: AGENT_TOOL_PRINCIPAL_KIND,
              hooks,
              confirmationToken: params.confirmationToken,
            }),
        });
        return { merged: true, ...result };
      },
    }),
  };

  return buildDomainRegistrations({ metadata: toolMetadata,
    domain: "taxonomy",
    catalogModule: "features/taxonomy/agent-tools.ts",
    catalog: CATALOG_BY_ID,
    handlers,
    derivedRisk: taxonomyDerivedRisk,
  });
}

/**
 * Contributes Taxonomy's AI tools to the assistant's catalog — called once by
 * `server/tool-catalog-manifest.ts`'s `installFirstPartyToolContributors()`, not by importing this
 * module. `assistant/tool-registrations.ts` no longer imports `buildTaxonomyRegistrations`/
 * `taxonomyDerivedRisk` by name; this is the seam that replaced it (2026-08-17, Stage 2 of the
 * rollout — no sibling domain still statically wired through `assistant` imports `taxonomy`, so this
 * one-directional `taxonomy -> assistant` call closes no new cycle).
 */
export function contributeTaxonomyTools(): ToolContributor {
  return { domain: "taxonomy", build: buildTaxonomyRegistrations, risk: taxonomyDerivedRisk };
}

import { MAX_THEME_FILE_BYTES } from "./theme-files.js";

/**
 * @file The Themes domain's agent-tool catalog, instantiating SPEC-016 REQ-22's naming/callability
 * convention (the same shape `redirects/agent-tools.ts`, `seo/agent-tools.ts`, and every other
 * domain catalog already use).
 *
 * Purpose:
 * A static, in-process catalog describing every agent-callable tool this domain exposes: list the
 * discovered themes, list one theme's files, read one file, write one file.
 *
 * Why this domain is deliberately BROADER than every other one here, and why that is sound rather
 * than an exception being carved out:
 *
 * Every other domain in this repo exposes narrow, schema-validated operations — `redirects_create`
 * takes a match type and a target, not a row of SQL. That narrowness IS the safety boundary there,
 * because the durable state behind those tools has no independent validator: nothing re-checks a
 * redirect rule after it is written, so the only place to enforce "a redirect is well-formed" is the
 * operation that creates one.
 *
 * Theme content is not like that, and never was. A theme is validated at LOAD time, every time,
 * against validators that have no idea who wrote the file:
 *   - a `.liquid` template must pass `liquid-allowlist.ts` (tag/filter allowlist, AST-walked),
 *   - a `.hbs` template must pass `handlebars-allowlist.ts` (helper/expression allowlist, no
 *     partials, no decorators, no raw output outside one sanctioned path),
 *   - a `.json` template is a closed block vocabulary the declarative renderer will not step
 *     outside of,
 *   - and whichever tier it is, rendering happens inside a `worker_threads` sandbox with a
 *     wall-clock timeout and V8 heap caps, falling back to a built-in body on any failure.
 * A human typing a template in an editor, an external coding agent editing the checkout, and this
 * in-app tool all produce a file on disk that goes through exactly that same gate. A narrow
 * `theme_set_template_header_tagline`-style tool would therefore buy no safety at all — it would
 * only buy inexpressiveness, while the actual guarantee stayed where it already is.
 *
 * So the boundary this catalog enforces is the one that IS load-bearing: WHICH FILES. Not which
 * edit. `theme_read_file`/`theme_write_file` resolve strictly inside one theme's own folder, under a
 * recognized theme root, with a real path-containment check (`theme-files.ts` — resolve first,
 * compare with `path.relative`, then re-verify against the `realpath` of the deepest existing
 * ancestor, so neither `../` traversal nor a symlink escape passes). That same reasoning is exactly
 * why this shape would NOT be sound for arbitrary filesystem access: there is no equivalent
 * load-time validator for "any file on the disk".
 *
 * Deliberate absences (the point of a catalog, not an oversight):
 * - `theme_delete_file` (HARD delete). Destructive and irreversible: this repo has no theme-file
 *   revision history to restore from, so a deleted `home.liquid` is gone, and the theme it belonged
 *   to silently drops to `status: "invalid"`. Same caution class as every other domain's excluded
 *   irreversible operation (`redirects_import`'s mass live-routing change, Recovery's
 *   `backup_execute_restore`, Database's `database_execute_migrate_forward`).
 *
 *   Owner decision, 2026-08-30, resolving the "should the human Explore screen gaining its own
 *   gated file-delete route reopen this" question raised the same day: **agents get soft-delete
 *   only; hard delete stays human-gated.** `theme_trash_file`/`theme_restore_trashed_file` (below)
 *   are the agent-reachable, fully-reversible alternative — moving a file into `.trash/` (never
 *   removing bytes) through the exact same `validateFileIdentityChange` gate rename uses, so a
 *   theme's own required files, a built theme's generated tree, and `script`/`other`-group files
 *   stay just as un-trashable as they are un-renamable. `theme_delete_file` itself stays OUT of this
 *   catalog, unconditionally: `assistant/__tests__/tool-registrations.themes.test.ts`'s "no
 *   whole-theme or file-delete operation is agent-callable..." test asserts this by name and is
 *   certified to stay that way — do not add it, and do not weaken that test to add it.
 * - `theme_rename_folder` / `theme_create` / `theme_delete`. A theme's folder name IS its id
 *   (`loadTheme` fails a theme whose `theme.json` id disagrees with its folder), and the active
 *   theme is referenced by that id from presentation settings. Renaming or removing a folder can
 *   therefore break the LIVE site's active-theme resolution — a blast radius categorically wider
 *   than editing a FILE inside one theme, and one no per-file containment check constrains. Left
 *   out this pass on the same basis. (`theme_rename_file`, below, only ever touches a file inside an
 *   already-discovered theme's own folder — a different, narrower operation from renaming the
 *   folder itself, and not what this bullet excludes.) `theme_duplicate` (owner-approved
 *   2026-10-08, `duplicate-theme-tool.ts`) is not a `theme_create` either: it only ADDS a copy under
 *   a fresh id nothing references yet and never writes, renames, or removes an existing folder, so
 *   none of the active-theme blast radius above applies.
 *
 *   `theme_delete` stays unwired, but a whole theme CAN now be removed reversibly: `theme_trash`
 *   (owner-approved 2026-10-08, `trash-theme-tool.ts`) moves the folder to the Trash (restorable via
 *   `trash_restore_item`) and refuses the active theme, so the blast radius above cannot happen.
 * - Nothing here touches the ACTIVE theme selection. `theme.set` is a separate operation, exposed
 *   both to a human (`server/inbound/admin-http/routes/presentation/patch-active-theme.ts`) and, as
 *   of F7a (2026-09-24), to an agent (`theme_set_active`, `features/theme/set-active-theme-tool.ts`
 *   — deliberately its OWN file/catalog, not an entry in THIS catalog: it shares no validator with
 *   the file operations above, and it is the one write this domain's own `writableThemeIds`-shaped
 *   allowlist governs); this domain edits theme content, it does not decide which theme the site
 *   serves.
 *
 * How it relates to the project:
 * The server-side tool filter (ADR-014) consumes this catalog to decide which tool names an agent
 * session may even see; `authorize()` (ADR-021 §2) enforces the actual permission checks at call
 * time — this module only declares the catalog shape, it performs no I/O and no enforcement itself.
 *
 * Architectural role:
 * `theme` feature domain. Imports only its own domain's constants, so the published JSON Schemas
 * cannot drift from the validators — same discipline `redirects/agent-tools.ts` uses.
 */

export type AgentToolSideEffect = "none" | "mutates-durable-state" | "mints-token";

export interface AgentToolDefinition {
  name: string;
  description: string;
  sideEffects: AgentToolSideEffect;
  authorization: { permission: string };
  /**
   * JSON Schema for this tool's `input`, published via `ToolDescriptor.inputSchema`
   * (`assistant/tool-registration-kit.ts`'s `buildDomainRegistrations`, which refuses to wire any
   * tool lacking one). Optional to match the shared structural type; every entry in THIS catalog
   * carries one, because every entry in this catalog is wired.
   */
  inputSchema?: Readonly<Record<string, unknown>>;
}

/**
 * The permission gating reads in this domain. Reused rather than invented: `theme.set` is what
 * already gates the presentation/theme surface a human operator reaches
 * (`patch-active-theme.ts`, `admin/themes/list.ts`), so anyone who can already see and switch the
 * workspace's themes can read their files.
 */
export const THEME_READ_PERMISSION = "theme.set";

/**
 * The permission gating writes. A NEW permission rather than a reuse of `theme.set`, because the
 * existing catalog had no natural fit: `theme.set` is described as "Change the active
 * theme/presentation settings" — choosing among already-validated themes, an operation whose worst
 * outcome is the site looking wrong until it is switched back. Editing a theme's source files is a
 * different capability with a different worst case (a template that fails validation takes that
 * theme's pages to the fallback body until fixed), so it gets its own string and is granted to
 * `admin` but not `editor` in the built-in seed — while `theme.set` stays granted to both.
 */
export const THEME_WRITE_PERMISSION = "theme.edit";

const THEME_ID_PROPERTY = {
  type: "string",
  minLength: 1,
  description: "A theme's id, exactly as returned by content_read.theme (it is also the theme's folder name).",
} as const;

const RELATIVE_PATH_PROPERTY = {
  type: "string",
  minLength: 1,
  description:
    "A path relative to the theme's own folder, e.g. 'theme.json', 'tokens.json', 'styles.css', or 'templates/home.liquid'. Must stay inside that folder: an absolute path, or one escaping via '../', is refused. Use theme_list_files to discover what exists.",
} as const;

const LIST_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: [],
  properties: {
    tier: {
      type: "string",
      enum: ["declarative", "templated", "handlebars", "static", "code"],
      description:
        "Filter to themes of exactly this capability tier. 'declarative' = JSON block trees, 'templated' = LiquidJS, 'handlebars' = Handlebars, 'static' = plain HTML/CSS/JS pages, 'code' = signed-plugin JS (reserved, no themes exist). Omit to list every tier.",
    },
    status: {
      type: "string",
      enum: ["valid", "invalid"],
      description: "Filter to themes in exactly this validation status. Omit to list both.",
    },
  },
} as const;

const THEME_ID_ONLY_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["themeId"],
  properties: { themeId: THEME_ID_PROPERTY },
} as const;

const LIST_FILES_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["themeId"],
  properties: {
    themeId: THEME_ID_PROPERTY,
    includeTrash: {
      type: "boolean",
      description:
        "Include files currently in this theme's trash (paths starting with '.trash/'), soft-deleted via theme_trash_file. Defaults to false — trashed files are hidden from the ordinary listing. Set true to see what can be restored with theme_restore_trashed_file.",
    },
  },
} as const;

const READ_FILE_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["themeId", "path"],
  properties: {
    themeId: THEME_ID_PROPERTY,
    path: RELATIVE_PATH_PROPERTY,
    startLine: {
      type: "integer", minimum: 1,
      description: "First line to return (1-based). Defaults to 1 when lineCount is given.",
    },
    lineCount: {
      type: "integer", minimum: 1, maximum: 2000, default: 2000,
      description: "Maximum lines in a window, or search range when find is given. Read windows default to 2000; search ranges extend to EOF when omitted.",
    },
    find: {
      type: "string", maxLength: 200,
      description: "Search text inside theme files with this case-sensitive plain substring. Optional startLine/lineCount limit the search and context to that range; omitted lineCount searches through EOF. Returns up to 50 matching lines with context, merging overlapping windows. Each window is capped at 2000 characters and all windows at 4000 characters per item; returned.truncated and returned.hint explain omitted text.",
    },
    context: {
      type: "integer", minimum: 0, maximum: 20, default: 3,
      description: "Lines before and after each matching line when find is given. Defaults to 3; maximum 20. Larger integers are clamped to 20 with a result note; negatives and non-integers are refused.",
    },
  },
} as const;

const WRITE_FILE_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["themeId", "path", "content"],
  properties: {
    themeId: THEME_ID_PROPERTY,
    path: RELATIVE_PATH_PROPERTY,
    content: {
      type: "string",
      maxLength: MAX_THEME_FILE_BYTES,
      description: `The file's complete new contents as UTF-8 text. This is an overwrite, not a patch — send the whole file. Up to ${MAX_THEME_FILE_BYTES} bytes. For a small change to a large file, theme_edit_file is usually cheaper and safer: it replaces one exact substring instead of requiring you to re-send the entire file.`,
    },
    overwriteOversized: {
      type: "boolean",
      description: `Set to true only to replace an EXISTING file larger than ${MAX_THEME_FILE_BYTES} bytes. theme_read_file cannot read a file that size, so without this flag the write is refused instead of discarding contents you never saw. Not needed for a new file or one within the limit.`,
    },
  },
} as const;

/**
 * `oldString`/`newString` share {@link WRITE_FILE_SCHEMA}'s own `content` ceiling: an edit's RESULT
 * still goes through `writeThemeFile`, which enforces {@link MAX_THEME_FILE_BYTES} on the file as a
 * whole regardless of how it was produced, so capping each half at the same bound is a schema-level
 * early rejection of an input that could never succeed, not a new limit.
 */
const EDIT_FILE_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["themeId", "path", "oldString", "newString"],
  properties: {
    themeId: THEME_ID_PROPERTY,
    path: RELATIVE_PATH_PROPERTY,
    oldString: {
      type: "string",
      minLength: 1,
      maxLength: MAX_THEME_FILE_BYTES,
      description:
        "The EXACT existing text to replace, byte-for-byte (including whitespace/indentation) — read the file first with theme_read_file to copy it precisely. Must appear in the file exactly once, unless replaceAll is true; zero matches or more than one match (with replaceAll left false) is refused rather than guessed at.",
    },
    newString: {
      type: "string",
      maxLength: MAX_THEME_FILE_BYTES,
      description: "The text to put in oldString's place. May be an empty string to delete oldString outright. An edit that would leave the whole file empty (or whitespace-only) is refused unless intent is 'delete'.",
    },
    intent: {
      type: "string",
      enum: ["delete"],
      description: "Pass 'delete' only to confirm an edit that empties the WHOLE file. Not needed for ordinary deletions (an empty newString removing part of the file).",
    },
    replaceAll: {
      type: "boolean",
      description: "Replace every occurrence of oldString instead of requiring exactly one. Defaults to false.",
    },
  },
} as const;

const RENAME_FILE_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["themeId", "path", "name"],
  properties: {
    themeId: THEME_ID_PROPERTY,
    path: RELATIVE_PATH_PROPERTY,
    name: {
      type: "string",
      minLength: 1,
      description:
        "The new bare FILENAME (not a path) — no '/' or '\\', and it stays in the same folder as path. Renaming also cannot change the file's extension (e.g. 'x.css' to 'y.css' is fine, 'x.css' to 'x.html' is refused): the extension decides how a browser serves the file, so it must survive a rename unchanged.",
    },
  },
} as const;

/** Same `{themeId, path}` shape as {@link READ_FILE_SCHEMA} — kept as its own named constant
 *  rather than reused directly so `theme_trash_file`'s schema reads as its own contract in the
 *  catalog, not a borrowed one that would look coincidental. */
const TRASH_FILE_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["themeId", "path"],
  properties: { themeId: THEME_ID_PROPERTY, path: RELATIVE_PATH_PROPERTY },
} as const;

/** Same `{themeId, path}` shape as {@link READ_FILE_SCHEMA} — kept as its own named constant for the
 *  same reason {@link TRASH_FILE_SCHEMA} is: so `theme_reset_file`'s schema reads as its own
 *  contract in the catalog, not a borrowed one that would look coincidental. */
const RESET_FILE_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["themeId", "path"],
  properties: { themeId: THEME_ID_PROPERTY, path: RELATIVE_PATH_PROPERTY },
} as const;

/** Same `{themeId, path}` shape again, for `theme_copy_file` — the destination name is always
 *  server-computed (the next available `name-1`, `name-2`, … suffix), never operator input, so
 *  unlike {@link RENAME_FILE_SCHEMA} there is no second field to add. */
const COPY_FILE_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["themeId", "path"],
  properties: { themeId: THEME_ID_PROPERTY, path: RELATIVE_PATH_PROPERTY },
} as const;

const RESTORE_TRASHED_FILE_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["themeId", "trashedPath"],
  properties: {
    themeId: THEME_ID_PROPERTY,
    trashedPath: {
      type: "string",
      minLength: 1,
      description:
        "The exact trashedPath a prior theme_trash_file call returned (or one seen via theme_list_files with includeTrash: true) — looks like '.trash/1730000000000/pages/about.html'.",
    },
    restoreTo: {
      type: "string",
      minLength: 1,
      description:
        "Where to put the file back. Omit to restore to its original path (recovered from trashedPath itself); pass this only to restore to a DIFFERENT path than where it was trashed from — e.g. if something else already occupies the original path.",
    },
  },
} as const;

/**
 * The Themes domain's fixed agent-tool catalog — see this file's header for the withheld operations
 * and why.
 *
 * @complexity O(1) — a fixed, statically-defined list.
 * @overallScore 100
 */
export function getThemesAgentToolCatalog(): AgentToolDefinition[] {
  return [
    {
      name: "theme_list_page_publications",
      description: "Lists standalone page publication states in one static theme. Call to see whether about or pricing is public before toggling it. Returns {pages:[{themeId,page,published}]} sorted by page id; excludes index, 404 and declared template shells. Reads fresh theme files, defaults undeclared publication to false, and refuses missing themes or non-static tiers. Requires theme.set; use theme_set_page_published to change visibility.",
      sideEffects: "none", authorization: { permission: THEME_READ_PERMISSION },
      inputSchema: { type: "object", additionalProperties: false, required: ["themeId"], properties: { themeId: THEME_ID_PROPERTY } },
    },
    {
      name: "preview_reload",
      description: "Reloads every open admin theme/site preview with fresh page, CSS and JS. Optionally navigates previews to a site-relative public path such as /create-a-theme. Does not change published content.",
      sideEffects: "mutates-durable-state",
      authorization: { permission: THEME_READ_PERMISSION },
      inputSchema: { type: "object", additionalProperties: false, properties: { path: { type: "string", description: "Optional site-relative public URL starting with /." } } },
    },
    {
      name: "theme_rescan",
      description:
        "Rescans theme folders and refreshes the site's theme registry. Call after a NEW theme folder was created or removed after boot, or when a theme is not showing. Returns { added, removed, invalid: [{ themeId, errors }] }. Invalid themes remain discoverable with their errors. Requires theme.set. Does not change the active selection.",
      sideEffects: "mutates-durable-state",
      authorization: { permission: THEME_READ_PERMISSION },
      inputSchema: { type: "object", additionalProperties: false, properties: {}, required: [] },
    },
    {
      name: "theme_list",
      description:
        "Lists every discovered theme with its id, name, tier, validation status, validation errors and active flag, plus activeThemeId (the configured selection, which can differ from the renderer's fallback). Read-only. Start here: a theme's id is the handle every other tool in this domain takes, and the errors array is how you find out what is currently wrong with a theme.",
      sideEffects: "none",
      authorization: { permission: THEME_READ_PERMISSION },
      inputSchema: LIST_SCHEMA,
    },
    {
      name: "theme_list_files",
      description:
        "Lists every file inside one theme's folder, as paths relative to that folder (e.g. 'theme.json', 'templates/home.liquid'). Read-only. Use this to discover what a theme actually ships before reading or editing it, rather than guessing filenames. To search text inside theme files, use theme_read_file with find. Trashed files (soft-deleted via theme_trash_file) are hidden unless includeTrash: true.",
      sideEffects: "none",
      authorization: { permission: THEME_READ_PERMISSION },
      inputSchema: LIST_FILES_SCHEMA,
    },
    {
      name: "theme_read_file",
      description:
        "Reads one file's raw text content from inside a theme's folder. Read-only. The path must stay inside that theme's own folder. " +
        "To search or grep text inside theme files, use theme_read_file with find; no separate Grep tool is needed. Use theme_list_files to discover paths, then batch find over those files. " +
        "For a large file, pass find (to locate a string) or startLine/lineCount (to read a window) instead of reading the whole file. " +
        "Selected reads also return totalLines, totalBytes and returned (startLine/endLine for a window; matches/truncated for find). " +
        "Find returns at most 2000 characters per window and 4000 per item (80000 content characters across a 20-item batch). When returned.truncated is true, follow returned.hint to narrow the find pattern or reduce context. " +
        "The 1 MB read limit still applies to the whole file, even for a selected read.",
      sideEffects: "none",
      authorization: { permission: THEME_READ_PERMISSION },
      inputSchema: READ_FILE_SCHEMA,
    },
    {
      name: "theme_write_file",
      description:
        "Writes (creates or overwrites) one file inside a theme's folder, then immediately re-validates the whole theme and returns its resulting status and errors. This is a full-file overwrite, not a patch — for changing one line or a short section of an EXISTING file, use theme_edit_file instead, which is cheaper and cannot accidentally drop the rest of the file. The path must stay inside that theme's own folder — absolute paths and '../' escapes are refused. ALWAYS read the returned status: 'invalid' means what you wrote did not pass validation (bad JSON, a disallowed Liquid/Handlebars construct, a syntax error, a missing required template) and the errors array says exactly what to fix. The re-validated theme also becomes what the live site serves, so an invalid write degrades that theme's pages to the built-in fallback body until it is corrected. Replacing an EXISTING file over the 1 MB read limit is refused unless you pass overwriteOversized: true: theme_read_file cannot read a file that size, so set it only when you mean to discard its whole current contents. If you created a NEW theme folder, call theme_rescan so the site picks it up.",
      sideEffects: "mutates-durable-state",
      authorization: { permission: THEME_WRITE_PERMISSION },
      inputSchema: WRITE_FILE_SCHEMA,
    },
    {
      name: "theme_edit_file",
      description:
        "Makes a targeted change to one EXISTING file inside a theme's folder by replacing one exact occurrence of oldString with newString — a patch, not an overwrite, so you never have to re-send content you are not changing. Read the file with theme_read_file first so oldString matches byte-for-byte; a find window with enough context is sufficient. Refused (no write happens) if oldString does not appear in the file, or appears more than once and replaceAll was left false — pass more surrounding context in oldString to make it unique, or pass replaceAll: true to change every occurrence deliberately. To DELETE text, pass newString: '' (empty string). An edit that would leave the whole file empty is refused unless intent: 'delete' is passed. Immediately re-validates the whole theme afterward and returns its resulting status and errors, exactly like theme_write_file — ALWAYS read the returned status the same way.",
      sideEffects: "mutates-durable-state",
      authorization: { permission: THEME_WRITE_PERMISSION },
      inputSchema: EDIT_FILE_SCHEMA,
    },
    {
      name: "theme_reset_file",
      description:
        "Resets one file inside a theme's folder back to its pristine original — the exact bytes captured when this theme was installed or downloaded — discarding whatever is there now, whether it was changed by theme_write_file, theme_edit_file, or a human editing it directly. This is the undo for those tools when 'undo' means 'go back to where it started', not 'go back one step': there is no history, so a reset cannot be reset again except by re-editing. Refused if this theme has no stored original at all (a hand-authored theme with nothing to reset to), or if this particular file has no original of its own — for example a file created after the theme was installed, or landed here via theme_copy_file. If the live file already matches its original byte-for-byte, nothing is written: the call succeeds with wasModified: false and bytesWritten: 0. Otherwise the original's exact bytes are copied back, binary files and files over the 1 MB read limit included, and wasModified is true. The result's content is the restored file as text, or null for a file over that limit. The comparison is exact bytes, so a line-ending-only difference (CRLF vs LF) counts as modified and is reset.",
      sideEffects: "mutates-durable-state",
      authorization: { permission: THEME_WRITE_PERMISSION },
      inputSchema: RESET_FILE_SCHEMA,
    },
    {
      name: "theme_rename_file",
