      sideEffects: "mutates-durable-state",
      authorization: { permission: THEME_WRITE_PERMISSION },
      inputSchema: COPY_FILE_SCHEMA,
    },
    {
      name: "theme_trash_file",
      description:
        "Soft-deletes one file inside a theme's folder: moves it into that theme's own trash (a '.trash/...' path), out of the way of pages/partials/file listings, WITHOUT deleting its bytes. Fully reversible with theme_restore_trashed_file, which is why this exists instead of a hard delete — there is no agent-callable hard delete in this domain at all; permanent removal is a human-only action in the Explore screen. Refused for the same reasons a rename would be refused: a theme's own required files (its index page, theme.json, tokens.json), a script (.js/.mjs/.cjs) or any other not-a-page/partial/style/config/asset file, and anything inside a built theme's generated tree.",
      sideEffects: "mutates-durable-state",
      authorization: { permission: THEME_WRITE_PERMISSION },
      inputSchema: TRASH_FILE_SCHEMA,
    },
    {
      name: "theme_restore_trashed_file",
      description:
        "Restores one file previously soft-deleted with theme_trash_file, moving it out of '.trash/...' and back to a normal path — by default the exact path it was trashed from, or pass restoreTo for a different one. Refused if trashedPath does not look like something theme_trash_file produced, if the destination is already occupied by another file, or if the destination falls inside a built theme's generated tree.",
      sideEffects: "mutates-durable-state",
      authorization: { permission: THEME_WRITE_PERMISSION },
      inputSchema: RESTORE_TRASHED_FILE_SCHEMA,
    },
  ];
}

import { createHash } from "node:crypto";
import { existsSync, lstatSync, readdirSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";

import { findUnrewrittenAssetPaths, rewriteAssetPaths, tokenStylesheetSentinel } from "./static-asset-contract.js";

/**
 * @file The install-time conformance gate a `build.source: "compiled"` theme (ADR-020 §5) must pass
 * before `loadTheme()` accepts it as `status: "valid"`.
 *
 * Why this exists at all: the headline decision on framework-authored themes is "frameworks compile at
 * build time down to the existing `static` contract; Tovu never runs the build." That contract is
 * currently enforced only by convention — `static-render.ts` string-matches a LITERAL stylesheet tag
 * and a LITERAL `../css/`/`../js/` asset-path shape, and silently degrades (a console warning, not a
 * rejection) when a page doesn't carry them. That degradation is an acceptable failure mode for a
 * human hand-authoring HTML, who sees the broken page immediately. It is not acceptable for a bundler's
 * output landing in the theme catalog unreviewed: a build that renames the stylesheet, hashes an asset
 * path, or minifies away the sentinel would ship a page with silently missing tokens and dead assets
 * with NO error anywhere. This module is what turns that into a hard, install-time rejection instead —
 * `loadTheme()` never serves an invalid theme's pages, so a build that fails this gate never reaches a
 * visitor at all (see this repo's `SPEC-004 REQ-10` fault-isolation contract this module extends).
 *
 * Reuses `static-asset-contract.ts`'s sentinel constant and rewrite/detect pair rather than
 * re-implementing the same regex here — the whole point is that this gate checks the SAME contract
 * `static-render.ts` depends on at request time, not a parallel approximation of it that could drift.
 *
 * Only ever called from `loadTheme()` for a `manifest.build?.source === "compiled"` theme (see that
 * function's own call site). An authored theme (every theme on disk today, `build` absent) never runs
 * these checks — this module changes nothing about the 7 live themes' validation.
 *
 * Scope history: {@link checkArtifactHashes} originally (09b1ab7, 2026-08-12) verified only the files
 * `build.artifactHashes` LISTS, not a full-tree inventory — deliberate, not an oversight, pending an
 * unresolved product question the FINAL debate report left to the owner: *who authors a built theme?*
 * That trigger fired the same day (2026-08-12): the owner decided anyone can author themes and
 * plugins, putting untrusted publishers in scope. {@link checkArtifactHashes} was promoted to a
 * full-tree inventory — every real file under the generated region must have a listed hash, every
 * listed hash must resolve to a real file inside that region, and a symlink anywhere in the tree is
 * refused outright rather than followed or silently skipped — matching the posture
 * `agent-plugins/install.ts`'s package extraction already uses for the identical "content from someone
 * other than the operator" threat model (see {@link checkArtifactHashes}'s own doc for why that
 * module's implementation is reproduced locally here rather than imported directly).
 */

/**
 * Marks one element as a hydration island: interactivity added ON TOP of content that must already be
 * present, server-rendered, in the raw HTML — never the mechanism that first-paints that content.
 *
 * The reason this is enforced at all: GPTBot, ClaudeBot, and PerplexityBot execute no JavaScript
 * whatsoever and see only this raw HTML; Bingbot's JS support is partial; even Googlebot's rendered-
 * content indexing is a delayed second pass, not immediate. An island whose content only exists after
 * client-side hydration is therefore invisible to most of the traffic that matters for indexing, not
 * just a graceful-degradation edge case.
 *
 * A plain `data-*` marker on any element (not a dedicated custom tag) — the same vocabulary shape as
 * this codebase's existing `data-embed-type`/`data-tovu-slot` markers, deliberately distinct from them:
 * an embed marker is resolved by the SERVER at request time; `data-tovu-island` is resolved by the BUILD
 * at compile time and the server never touches it, so reusing the embed vocabulary here would misstate
 * which layer owns it.
 */
const ISLAND_MARKER = /<([a-z][a-z0-9-]*)\b[^>]*\bdata-tovu-island\b[^>]*>([\s\S]*?)<\/\1>/gi;

/** One conformance failure, always naming which page and which rule. */
export interface ConformanceIssue {
  readonly page: string;
  readonly rule: "stylesheet-sentinel" | "asset-path" | "island-content" | "artifact-hash";
  readonly message: string;
}

/**
 * How many times `needle` occurs in `haystack`, non-overlapping. `String.split(needle).length - 1` is
 * the plain-string-count idiom this codebase already reaches for over a regex when the needle has no
 * pattern metacharacters worth escaping (the sentinel is a fixed literal).
 */
function countOccurrences(haystack: string, needle: string): number {
  return haystack.split(needle).length - 1;
}

/**
 * A built page must carry its `apiVersion`-matched sentinel ({@link tokenStylesheetSentinel})
 * EXACTLY ONCE — zero means token injection silently no-ops (`static-render.ts`'s own runtime warning
 * for this same condition), more than one means the runtime's single `.replace()` only tokens the
 * first occurrence and leaves the rest bare.
 */
function checkStylesheetSentinel(pageId: string, html: string, apiVersion?: 2): ConformanceIssue[] {
  const sentinel = tokenStylesheetSentinel(apiVersion);
  const count = countOccurrences(html, sentinel);
  if (count === 1) return [];
  return [
    {
      page: pageId,
      rule: "stylesheet-sentinel",
      message:
        count === 0
          ? `missing the literal stylesheet tag ${JSON.stringify(sentinel)} — token injection would silently no-op and this page would ship with no design tokens`
          : `the stylesheet tag appears ${count} times — token injection replaces only the first match, later duplicates get no tokens`,
    },
  ];
}

/**
 * Runs the SAME rewrite-then-detect pipeline `renderStaticPage` runs at request time
 * (`rewriteAssetPaths` then {@link findUnrewrittenAssetPaths} on the result), against the theme's raw
 * on-disk HTML instead of a live request. Anything still unrewritten after that pipeline is a `../css/`
 * or `../js/` reference the runtime rewrite cannot recognize and that will 404 in the browser — exactly
 * the failure `static-render.ts` currently only reports as a `console.warn` at serve time. Here it fails
 * the install instead.
 *
 * Also reports a page that references NO `../css/`/`../js/` asset at all (checked against the RAW html,
 * before rewriting) as its own finding — found empirically (`astro-real-bundler-conformance.test.ts`):
 * real Astro output with inlined CSS and no client JS made this function return `[]`, which reads
 * identically to "every asset reference on this page was verified correct." Those are not the same
 * claim — the difference between "nothing to check" and "checked, and it's fine" would otherwise be
 * lost the moment this function's result is read as a boolean pass/fail. A compliant page always carries
 * at least the mandatory stylesheet sentinel (itself a `../css/` reference — see
 * {@link checkStylesheetSentinel}), so this can only fire in tandem with that rule already failing; it
 * exists so a reader filtering issues down to just the `asset-path` rule still sees that this page's
 * assets were never actually verified, rather than reading silence as a clean bill of health.
 */
function checkAssetPaths(pageId: string, html: string, themeId: string, apiVersion?: 2): ConformanceIssue[] {
  const totalReferences = findUnrewrittenAssetPaths(html, apiVersion).length; // count BEFORE rewriting -- rewritable or not
  const unrewritten = findUnrewrittenAssetPaths(rewriteAssetPaths(html, themeId, apiVersion), apiVersion);
  const issues: ConformanceIssue[] = unrewritten.map((reference) => ({
    page: pageId,
    rule: "asset-path",
    message: `asset reference '${reference}' cannot be rewritten to the served theme-assets route and will 404 in the browser`,
  }));
  if (totalReferences === 0) {
    const jsFolder = apiVersion === 2 ? "../scripts/" : "../js/";
    issues.push({
      page: pageId,
      rule: "asset-path",
      message: `page ships no '../css/' or '${jsFolder}' asset references at all — this check has nothing to verify, which is not the same as verifying the page's assets are correct`,
    });
  }
  return issues;
}

/**
 * Strip an island's inner markup down to its visible text, the same "is there really something here"
 * question a crawler with no JavaScript is asking. Comments and `<script>`/`<style>` bodies never count
 * as content; nested tags are stripped, not their text.
 */
function visibleIslandText(innerHtml: string): string {
  return innerHtml
    .replace(/<!--[\s\S]*?-->/g, "")
    .replace(/<(script|style)\b[\s\S]*?<\/\1>/gi, "")
    .replace(/<[^>]+>/g, "")
    .replace(/&(?:nbsp|#160);/gi, "")
    .trim();
}

/**
 * Every `data-tovu-island` element must have non-empty server-rendered text in the RAW artifact — see
 * {@link ISLAND_MARKER}'s own doc for why. An island whose entire content is filled in by client-side
 * hydration (an empty mount point) fails here rather than shipping invisible-to-most-crawlers content.
 */
function checkIslandContent(pageId: string, html: string): ConformanceIssue[] {
  const issues: ConformanceIssue[] = [];
  for (const match of html.matchAll(ISLAND_MARKER)) {
    if (visibleIslandText(match[2] ?? "").length === 0) {
      issues.push({
        page: pageId,
        rule: "island-content",
        message:
          "an interactive island (data-tovu-island) has no server-rendered text content in the shipped HTML — GPTBot, ClaudeBot, and PerplexityBot execute no JavaScript and would see nothing here; an island may only add interactivity on top of content already present in the artifact, never be what first-paints it",
      });
    }
  }
  return issues;
}

/** Internal signal that {@link walkGeneratedTree} could not safely finish — thrown, not returned, so
 * {@link checkArtifactHashes} short-circuits rather than report partial results from an inventory walk
 * it never completed. Never escapes {@link checkArtifactHashes}. */
class GeneratedTreeInventoryLimitExceeded extends Error {}

/** Ceiling on how many files {@link walkGeneratedTree} will enumerate, mirroring `theme-files.ts`'s own
 * `MAX_LISTED_FILES` — an untrusted publisher's build output is walked before any of it is trusted, so
 * the walk itself needs a bound, not just the checks it feeds. */
const MAX_INVENTORY_FILES = 2_000;

/** Depth ceiling on the same walk, mirroring `theme-files.ts`'s `MAX_WALK_DEPTH`. */
const MAX_INVENTORY_WALK_DEPTH = 12;

/**
 * Per-file and cumulative byte ceilings on the hashing pass, matching the order of magnitude
 * `agent-plugins/install.ts`'s own `LIMITS` uses for the identical "content from someone other than
 * the operator" threat model (this module's file header already names that precedent). `sha256` reads
 * a whole file into memory at once (`readFileSync`), so one unbounded file — or an unbounded SUM across
 * many merely-legal-sized ones — is a memory/CPU cost a hostile publisher's build could run up, not
 * just a correctness gap.
 *
 * Tripwire, recorded so a future "why did my theme stop installing" report starts here instead of a
 * cold re-derivation: these are a POLICY call, not a measured requirement, and a legitimately large
 * theme (a hero video, a large image gallery) can hit them. That failure must always surface as a
 * named, specific conformance issue — the size and the exact cap it exceeded, both in the message
 * (`checkArtifactHashes`'s own per-file/total-size branches interpolate both) — never a silent
 * truncation or an unexplained `invalid`. If a real theme trips this, the fix is to raise these two
 * constants, not to loosen the containment or symlink rules they sit next to.
 */
const MAX_HASHED_FILE_BYTES = 16 * 1024 * 1024;
const MAX_TOTAL_HASHED_BYTES = 64 * 1024 * 1024;

/**
 * Whether a theme-root-relative path (POSIX, produced by {@link walkGeneratedTree}) falls inside a
 * built theme's GENERATED region — the boundary the full-tree inventory below must account for.
 * Mirrors `theme-files.ts`'s `resolveThemeFileWriteScope` boundary (`theme.json` and everything under
 * `build.sourceDir` stay out) WITHOUT importing that module: `theme.ts` already imports this module,
 * and `theme-files.ts` imports `theme.ts` for `ThemeManifest` — importing `theme-files.ts` from here
 * would close that back into a cycle (`theme.ts` → `build-conformance.ts` → `theme-files.ts` →
 * `theme.ts`), the same cycle 09b1ab7's own commit message already routed around once already, for
 * `static-asset-contract.ts`. `theme-files.ts` is also under active structural refactor elsewhere in
 * this session, a second reason to leave its internals alone rather than a first. The predicate itself
 * is a handful of lines of pure string logic — one extra copy of a boundary rule is the smaller,
 * contained risk, and a cross-check test in `build-conformance.test.ts` pins it equal to the original.
 */
function isInGeneratedTree(relativePath: string, sourceDir: string | undefined): boolean {
  if (relativePath === "theme.json") return false;
  if (sourceDir !== undefined && (relativePath === sourceDir || relativePath.startsWith(`${sourceDir}/`))) {
    return false;
  }
  return true;
}

/** {@link walkGeneratedTree}'s result: every real file found (keyed by theme-relative path, valued by
 * its absolute path), plus every path refused outright as a symlink (keyed the same way, valued by the
 * `ConformanceIssue` explaining why) — kept separate from `files` rather than merged into one issue
 * list here, so {@link checkArtifactHashes} can use `rejected`'s KEYS to recognize "this path is
 * missing because it was refused, not because it was never there" and avoid reporting the same path
 * wrong twice (see that function's own doc). */
interface GeneratedTreeInventory {
  readonly files: ReadonlyMap<string, string>;
  readonly rejected: ReadonlyMap<string, ConformanceIssue>;
}

/**
 * Walks `themeDir`'s GENERATED region (see {@link isInGeneratedTree}) and returns every regular file
 * found. A symlink anywhere in the walk — file or directory — is refused OUTRIGHT rather than followed
 * or validated: recorded in the result's `rejected` map and neither descended into (so a symlinked
 * directory can never be used to walk this enumeration out of the theme folder) nor hashed. Matches
 * `agent-plugins/install.ts`'s own rule for the identical "content from someone other than the
 * operator" threat model (this module's file header already cites it): a theme's generated output has
 * no legitimate reason to contain a symlink, so this rejects the ENTRY KIND rather than attempting to
 * reason about where it points.
 *
 * Unlike an archive extractor's entry-PATH traversal risk (`agent-plugins/package-paths.ts`'s own
 * reason for full `realpath`-based containment on every entry), this walk has no equivalent lexical
 * `../` exposure: every path segment it ever joins comes from `readdirSync`'s own directory-entry
 * names, which the OS guarantees are single path components with no separator or `..` token — there is
 * no caller-supplied string here for a hostile name to smuggle a traversal through, the way an
 * archive's own entry-name field can. The symlink check above is therefore the whole containment
 * surface this walk has, and `lstatSync` (never `statSync`, which would follow the link) closes it.
 *
 * @throws {GeneratedTreeInventoryLimitExceeded} If the walk exceeds {@link MAX_INVENTORY_FILES} or
 * {@link MAX_INVENTORY_WALK_DEPTH} — an untrusted publisher's build is never walked unbounded.
 * @complexity O(n) in the generated tree's own file+directory count, bounded by the two ceilings above.
 */
/** What one directory entry turns out to be, once `isInGeneratedTree` and `lstatSync` have looked
 * at it — everything `walk`'s loop body needs to decide what to do next, without itself running
 * the `lstatSync` call (kept pure w.r.t. the walk's own mutable `files`/`rejected` maps). "Anything
 * else" (a FIFO, a socket, a device node) reports as `"skip"`, matching `theme-files.ts`'s own
 * `listThemeFiles` posture — none of those are a "file" this gate has any business hashing, and
 * none can be used to escape containment the way a symlink can. */
type GeneratedTreeEntryKind = "skip" | "symlink" | "directory" | "file";

function classifyGeneratedTreeEntry(relativePath: string, absolute: string, sourceDir: string | undefined): GeneratedTreeEntryKind {
  if (!isInGeneratedTree(relativePath, sourceDir)) return "skip";
  const linkStat = lstatSync(absolute);
  if (linkStat.isSymbolicLink()) return "symlink";
  if (linkStat.isDirectory()) return "directory";
  if (linkStat.isFile()) return "file";
  return "skip";
}

/** One directory entry's full disposition: classifies it, records a symlink rejection or a found
 * file directly into the walk's own maps, and returns where to recurse for a directory (`undefined`
 * otherwise). Pulled the ENTIRE loop body out of `walk` — not just the classification — because
 * cognitive complexity penalizes nesting depth, not branch count: four sequential ifs one level
 * inside `walk`'s own `for` loop cost roughly double what the same four ifs cost sitting at a
 * function's own top level. */
function visitGeneratedTreeEntry(
  dir: string,
  relPrefix: string,
  name: string,
  sourceDir: string | undefined,
  files: Map<string, string>,
  rejected: Map<string, ConformanceIssue>
): { absolute: string; relativePath: string } | undefined {
  const absolute = join(dir, name);
  const relativePath = relPrefix ? `${relPrefix}/${name}` : name;
  const kind = classifyGeneratedTreeEntry(relativePath, absolute, sourceDir);

  if (kind === "skip") return undefined;
  if (kind === "symlink") {
    rejected.set(relativePath, {
      page: relativePath,
      rule: "artifact-hash",
      message: `'${relativePath}' is a symbolic link inside the built theme's generated tree — symlinks are never permitted there, matching this repo's Agent Plugins package-extraction rule for the identical "content from someone other than the operator" threat model; the entry is refused outright, not followed`,
    });
    return undefined;
  }
  if (kind === "file") {
    files.set(relativePath, absolute);
    return undefined;
  }
  return { absolute, relativePath }; // kind === "directory" — caller recurses
}

function walkGeneratedTree(themeDir: string, sourceDir: string | undefined): GeneratedTreeInventory {
  const files = new Map<string, string>();
  const rejected = new Map<string, ConformanceIssue>();
  if (!existsSync(themeDir)) return { files, rejected };

  const walk = (dir: string, relPrefix: string, depth: number): void => {
    if (depth > MAX_INVENTORY_WALK_DEPTH) {
      throw new GeneratedTreeInventoryLimitExceeded(
        `generated tree exceeds the ${MAX_INVENTORY_WALK_DEPTH}-level depth cap under '${relPrefix || "."}'`
      );
    }
    for (const name of readdirSync(dir)) {
      if (files.size >= MAX_INVENTORY_FILES) {
        throw new GeneratedTreeInventoryLimitExceeded(`generated tree exceeds the ${MAX_INVENTORY_FILES}-file inventory cap`);
      }
      const toRecurse = visitGeneratedTreeEntry(dir, relPrefix, name, sourceDir, files, rejected);
      if (toRecurse) walk(toRecurse.absolute, toRecurse.relativePath, depth + 1);
    }
  };

  walk(themeDir, "", 0);
  return { files, rejected };
}

/**
 * Verify a built theme's ENTIRE generated tree against `build.artifactHashes`: every real file under
 * the generated region (see {@link isInGeneratedTree}) must have a listed hash whose digest matches
 * its actual bytes, every listed hash must resolve to a real file inside that region, and no symlink
 * may appear anywhere in the tree ({@link walkGeneratedTree}). A file referenced that doesn't exist
 * (or resolves outside the generated region, or was refused as a symlink), or whose sha256 no longer
 * matches, means the shipped bytes drifted from what the build actually recorded — the integrity
 * property "immutable, versioned" (ADR-020 §5) depends on. A real file present but not listed is now
 * its own finding: promoted from "listed-file-only" hashing to this full-tree inventory on 2026-08-12
 * — see this module's file header for why, and for the promotion trigger this was deferred behind
 * only hours earlier the same day (74cdeee).
 *
 * A side effect of walking the tree to answer "what exists" rather than trusting each
 * `artifactHashes` key as a path to open directly (the prior implementation's own behavior, via
 * `join(themeDir, relativePath)`): a key shaped like `"../../../etc/passwd"` can no longer reach the
 * filesystem as a path component at all — it simply never appears in {@link walkGeneratedTree}'s
 * result (every relative path that function produces is built exclusively from real, OS-returned
 * directory-entry names, which cannot contain a `..` token), so it now reports as an ordinary "does
 * not exist" finding instead of ever calling `readFileSync` on an attacker-influenced path. Not the
 * motivating reason for this rewrite, but a real containment improvement that falls out of it for
 * free — locked in by a regression test in `build-conformance.test.ts`.
 *
 * An `artifactHashes` entry naming a path that turned out to be a REJECTED symlink reports only the
 * `walkGeneratedTree`-recorded symlink finding, not a second, redundant "does not exist" finding for
 * the same path — the symlink message already explains why the path can't be verified; restating it
 * as merely "missing" would be misleading (it isn't missing, it was refused) and would double-count
 * one real problem as two.
 *
 * @complexity O(f · s) — f = generated files actually found (bounded by {@link MAX_INVENTORY_FILES}),
 * s = each file's size (bounded by {@link MAX_HASHED_FILE_BYTES} per file and
 * {@link MAX_TOTAL_HASHED_BYTES} cumulatively).
 */
/** One `artifactHashes` entry's own verification result: `issue` when something is wrong with it
 * (absent from `undefined` otherwise carries no meaning of "ok" vs "not yet checked" —  callers
 * only ever branch on `issue`/`stop`), the running total-hashed-bytes count so far (unconditionally
 * returned so the caller's accumulator stays a straight assignment), and whether the cumulative cap
 * was just tripped — the one condition that stops the WHOLE loop, not just this entry. */
interface ArtifactHashEntryResult {
  readonly issue?: ConformanceIssue;
  readonly bytesHashed: number;
  readonly stop: boolean;
}

function checkOneArtifactHashEntry(
  relativePath: string,
  expected: string,
  discovered: ReadonlyMap<string, string>,
  rejected: ReadonlyMap<string, ConformanceIssue>,
  totalHashedBytesSoFar: number
): ArtifactHashEntryResult {
  if (rejected.has(relativePath)) return { bytesHashed: totalHashedBytesSoFar, stop: false }; // already reported, as a symlink, not "missing"

  const absolutePath = discovered.get(relativePath);
  if (absolutePath === undefined) {
    return {
      issue: {
        page: relativePath,
        rule: "artifact-hash",
        message: `build.artifactHashes references '${relativePath}', which does not exist on disk (or is outside the generated tree)`,
      },
      bytesHashed: totalHashedBytesSoFar,
      stop: false,
    };
  }

  const size = statSync(absolutePath).size;
  if (size > MAX_HASHED_FILE_BYTES) {
    return {
      issue: {
        page: relativePath,
        rule: "artifact-hash",
        message: `'${relativePath}' is ${size} bytes, over the ${MAX_HASHED_FILE_BYTES}-byte per-file verification cap`,
      },
      bytesHashed: totalHashedBytesSoFar,
      stop: false,
    };
  }

  const bytesHashed = totalHashedBytesSoFar + size;
  if (bytesHashed > MAX_TOTAL_HASHED_BYTES) {
    return {
      issue: {
        page: relativePath,
        rule: "artifact-hash",
        message: `the generated tree's total verified size exceeds the ${MAX_TOTAL_HASHED_BYTES}-byte cap at '${relativePath}'`,
      },
      bytesHashed,
      stop: true, // matches agent-plugins' own fail-fast on TOTAL_SIZE_EXCEEDED
    };
  }

  const actual = createHash("sha256").update(readFileSync(absolutePath)).digest("hex");
  // Accept both a bare hex digest and a "sha256:"/"sha256-"-prefixed one — theme.json authors and
  // build tooling both write either convention; the digest itself is the only thing being verified.
  const normalizedExpected = expected.replace(/^sha256[:-]/, "").toLowerCase();
  if (actual !== normalizedExpected) {
    return {
      issue: {
        page: relativePath,
        rule: "artifact-hash",
        message: `'${relativePath}' does not match its recorded build.artifactHashes digest — the file changed after the build produced it`,
      },
      bytesHashed,
      stop: false,
    };
  }

  return { bytesHashed, stop: false };
}

/** Phase 2 of {@link checkArtifactHashes}: every `artifactHashes` entry against the inventory
 * `walkGeneratedTree` already found — existence, the per-file and cumulative size caps, and the
 * digest itself. Stops hashing further entries (but not the whole function — phase 3 below still
 * runs against every declared key) once the cumulative cap trips. */
function verifyArtifactHashEntries(
  artifactHashes: Readonly<Record<string, string>>,
  discovered: ReadonlyMap<string, string>,
  rejected: ReadonlyMap<string, ConformanceIssue>
): ConformanceIssue[] {
  const issues: ConformanceIssue[] = [];
  let totalHashedBytes = 0;
  for (const [relativePath, expected] of Object.entries(artifactHashes)) {
    const result = checkOneArtifactHashEntry(relativePath, expected, discovered, rejected, totalHashedBytes);
    totalHashedBytes = result.bytesHashed;
    if (result.issue) issues.push(result.issue);
    if (result.stop) break;
  }
  return issues;
}

/** Phase 3 of {@link checkArtifactHashes}: every real generated file with no `artifactHashes`
 * entry at all — promoted from "listed-file-only" hashing to full-tree inventory (see this
 * function's own file header for the promotion trigger). */
function findUndeclaredGeneratedFiles(
  discovered: ReadonlyMap<string, string>,
  artifactHashes: Readonly<Record<string, string>>
): ConformanceIssue[] {
  const declared = new Set(Object.keys(artifactHashes));
  const issues: ConformanceIssue[] = [];
  for (const relativePath of discovered.keys()) {
    if (!declared.has(relativePath)) {
      issues.push({
        page: relativePath,
        rule: "artifact-hash",
        message: `'${relativePath}' exists in this build's generated tree but has no entry in build.artifactHashes — every generated file must be accounted for now that a built theme can originate from an untrusted publisher`,
      });
    }
  }
  return issues;
}

function checkArtifactHashes(
  themeDir: string,
  sourceDir: string | undefined,
  artifactHashes: Readonly<Record<string, string>>
): ConformanceIssue[] {
  let inventory: GeneratedTreeInventory;
  try {
    inventory = walkGeneratedTree(themeDir, sourceDir);
  } catch (error) {
    if (error instanceof GeneratedTreeInventoryLimitExceeded) {
      // an unfinished walk cannot safely back a "here is everything" claim either way
      return [{ page: themeDir, rule: "artifact-hash", message: error.message }];
    }
    throw error;
  }
  const { files: discovered, rejected } = inventory;

  return [
    ...rejected.values(),
    ...verifyArtifactHashEntries(artifactHashes, discovered, rejected),
    ...findUndeclaredGeneratedFiles(discovered, artifactHashes),
  ];
}

/**
 * The install-time gate: every check a `build.source: "compiled"` theme must pass before `loadTheme()`
 * accepts it as `status: "valid"`. A no-op (`[]`) for any theme that isn't a compiled build — see this
 * module's own file header for why that's the only case this is ever called for.
 *
 * @param required.themeId - `manifest.id`, threaded through to {@link rewriteAssetPaths} rather than
 * re-read off `manifest` here, so this function's signature says exactly what it uses.
 * @param required.themeDir - The theme's own folder on disk, for {@link checkArtifactHashes}'s walk.
 * @param required.sourceDir - `manifest.build.sourceDir`, the theme-relative authored-source root that
 * stays OUT of {@link checkArtifactHashes}'s generated-tree inventory (see {@link isInGeneratedTree}).
 * `undefined` only for a fixture/test calling this function directly without going through `loadTheme`
 * — `loadTheme`'s own manifest-shape validation already flags a real `compiled` theme `invalid` if
 * `sourceDir` is missing, so this function never needs to guess a fallback convention.
 * @param required.pages - Raw `pages/*.html` source, keyed by page id (`loadStaticTierAssets`'s shape).
 * @param required.partials - Raw root-partial source (`nav.html`, `footer.html`, …) — checked for
 * island content only (see {@link checkIslandContent}'s call site below): a partial never carries the
 * page-level stylesheet sentinel itself (`renderStaticPartial` supplies that via its own host-document
 * wrapper), so sentinel/asset-path checks stay scoped to real pages.
 * @param required.artifactHashes - `manifest.build.artifactHashes`, or `{}` if the theme declares none
 * (a case `loadTheme`'s manifest-shape validation already flags `invalid` on its own).
 * @param required.apiVersion - `manifest.apiVersion`, threaded to {@link checkStylesheetSentinel}/
 * {@link checkAssetPaths} so a v2-shaped compiled theme (`css/theme.css`, `scripts/`) is checked
 * against the v2 contract instead of v1's. `undefined` for every real theme today — no behavior change
 * for any of them.
 * @complexity O(p · n) over pages' combined HTML length, p = page count, n = average page length; plus
 * {@link checkArtifactHashes}'s own O(f · s).
 */
export function checkBuiltThemeConformance(
  required: {
    themeId: string;
    themeDir: string;
    sourceDir?: string;
    pages: Readonly<Record<string, string>>;
    partials: Readonly<Record<string, string>>;
    artifactHashes: Readonly<Record<string, string>>;
    apiVersion?: 2;
  },
  _optional: Record<string, never> = {}
): ConformanceIssue[] {
  const { themeId, themeDir, sourceDir, pages, partials, artifactHashes, apiVersion } = required;
  const issues: ConformanceIssue[] = [];

  for (const [pageId, html] of Object.entries(pages)) {
    issues.push(...checkStylesheetSentinel(pageId, html, apiVersion));
    issues.push(...checkAssetPaths(pageId, html, themeId, apiVersion));
    issues.push(...checkIslandContent(pageId, html));
  }
  for (const [partialId, html] of Object.entries(partials)) {
    issues.push(...checkIslandContent(partialId, html));
  }
  issues.push(...checkArtifactHashes(themeDir, sourceDir, artifactHashes));

  return issues;
}

/**
 * @file Post-build normalization from a framework's raw `code`-tier build output into Tovu's static-tier
 * on-disk contract (`static-asset-contract.ts`): the literal `TOKEN_STYLESHEET_SENTINEL` `<link>` tag and
 * the `../css/`/`../js/` asset-path shape `checkBuiltThemeConformance` (`build-conformance.ts`) enforces
 * at install time.
 *
 * Exists because no framework build tool emits this shape natively by configuration alone — see
 * `ADS-memory/reports/spikes/20260812-angular-code-tier-build-output-verification.md` for the empirical
 * verification this module is built from (real `ng build` output, not inference).
 *
 * ## Required build configuration (Angular) — not optional, not a footnote
 *
 * A theme author building with Angular MUST set BOTH of these on the `production` build configuration
 * before this normalizer's preconditions hold:
 *
 * - `outputHashing: "none"` — without it, Angular hashes bundle filenames (`main-<HASH>.js`), which this
 *   module has no way to predict or match against `primaryStylesheetFile`.
 * - `optimization.styles.inlineCritical: false` — this is the more important of the two, and the one a
 *   "designed but unverified" version of this normalizer would have missed: Angular's default production
 *   optimization runs Beasties (critical-CSS inlining), which rewrites the plain `<link rel="stylesheet">`
 *   into an inlined `<style>` block plus an async-loading `<link media="print" onload="this.media='all'">`
 *   plus a duplicate `<noscript><link></noscript>` fallback. None of those shapes can ever contain the
 *   literal sentinel string, regardless of path or hashing config — {@link rewriteBundlerHtml} THROWS
 *   rather than silently ships a page missing the sentinel when it finds this shape instead of the plain
 *   tag, specifically because this is the setting most likely to be missed.
 *
 * ## Product statement: "Angular support" means PRERENDERED Angular only
 *
 * A CSR-only Angular build ships `<app-root></app-root>` — a literally empty mount point — as the page's
 * raw HTML; all real content arrives only after client-side hydration. That is invisible to GPTBot,
 * ClaudeBot, and PerplexityBot (none execute JavaScript) and delayed for Googlebot's two-phase indexing,
 * for the ENTIRE page, not just one `data-tovu-island` element — worse than the empty-island case
 * `checkIslandContent` (`build-conformance.ts`) already guards against. A theme built for Tovu MUST
 * run `ng add @angular/ssr` with `outputMode: "static"` and prerender every route that needs to be
 * indexable. This module does not enforce that — it normalizes whatever HTML it is given — so a theme
 * author skipping prerendering will not be stopped here; they will ship a page that passes every
 * conformance rule in this codebase while being invisible to the crawlers that matter.
 *
 * ## Design
 *
 * Split into a pure planning/rewriting core ({@link planAssetRelocation}, {@link rewriteBundlerHtml},
 * {@link rewriteCssRelativeUrls}) and a thin filesystem-effectful wrapper
 * ({@link normalizeBuildOutputDirectory}) — the decision of WHAT to move and HOW to rewrite is
 * unit-testable with in-memory strings; only the wrapper touches disk. This mirrors `build-conformance.ts`'s
 * own split between the pure `check*` functions and `walkGeneratedTree`'s effectful walk.
 *
 * Scope: this normalizes a build's OUTPUT tree in place. It has no opinion on which framework produced
 * that output — Angular is the framework this module's design was verified against, but the transform
 * (relocate top-level `.css`/`.js` files into `css/`/`js/`, rewrite the referencing tags) is generic
 * enough to apply to any framework whose default output is similarly flat. `ThemeBuildInfo.framework`
 * (`theme.ts`) remains purely descriptive metadata, unrelated to this module.
 *
 * ## Resolved risks (previously flagged, now handled)
 *
 * - **CSS-internal relative `url(...)` references** (background images, `@font-face` `src`) shift one
 *   directory level when their stylesheet moves from the output root into `css/` — `url(favicon.ico)`
 *   resolved from the output root, but resolves to the WRONG file (`css/favicon.ico`, which doesn't exist)
 *   once the stylesheet carrying it lives one level deeper. {@link rewriteCssRelativeUrls} prepends `../`
 *   to every relative `url(...)` reference in a relocated CSS file's content (skipping absolute URLs,
 *   scheme-prefixed URLs like `data:`, root-relative `/...`, protocol-relative `//...`, and bare
 *   fragments `#...`, none of which are affected by the directory shift), and
 *   {@link normalizeBuildOutputDirectory} runs it on every relocated CSS file automatically. NOT handled:
 *   a bare `@import "other.css";` (the quoted-string import form without a `url(...)` wrapper) — only the
 *   `url(...)` form is rewritten, matching what Angular's own build emits for component/global styles.
 * - **`index.csr.html`** — the CSR-fallback shell `ng add @angular/ssr` also emits into the output root
 *   alongside the prerendered `index.html`. Tovu's static-tier serving model has no client-side router to
 *   fall back to (`loadStaticTierAssets` serves each theme page's own prerendered HTML directly, one entry
 *   per route) — this file is dead weight that would otherwise trip `checkArtifactHashes`'s full-tree
 *   inventory rule as an unlisted file with no reason to be hashed and shipped.
 *   {@link normalizeBuildOutputDirectory} deletes it (see {@link DISCARDED_FRAMEWORK_ARTIFACTS}).
 * - **`.js.map`/`.css.map` sourcemaps** — a `.js.map` file doesn't end in `.js` (it ends in `.map`), so
 *   without explicit handling {@link planAssetRelocation} would leave it at the output root while its
 *   bundle moves into `js/`/`css/`; the bundle's own `//# sourceMappingURL=` comment (a bare relative
 *   filename) would then point at a file that no longer exists at that location — a 404 for the map,
 *   invisible until a theme author actually opens dev tools, and looking nothing like its cause
 *   (compiled-output-only debugging with no diagnostic pointing at "the map moved"). This class of
 *   failure — latent, silent, armed by a future config change nobody sees today — is exactly what this
 *   whole session went looking for, so it is fixed rather than left as a caveat: `.js.map`/`.mjs.map`
 *   relocate into `js/` alongside their bundle, `.css.map` into `css/` alongside its stylesheet, as part
 *   of the SAME relocation entries `planAssetRelocation` already produces (see its own doc). Because a
 *   bundle and its map always move together into the same target directory, their relative relationship
 *   to EACH OTHER is unchanged — no rewrite of the `sourceMappingURL` comment's text is needed, the same
 *   reasoning already documented for JS chunk-to-chunk relative imports. NOT handled: a sourcemap's own
 *   internal `sources`/`sourceRoot` JSON fields (build-time-absolute paths to original `.ts` sources) —
 *   unrelated to the 404 this fixes, a pre-existing property of every bundler's sourcemap output in every
 *   toolchain, and never something Tovu serves back to a browser regardless.
 *
 * ## Wired (2026-08-18, Milestone 4) — still open beyond this
 *
 * `tovu theme normalize-build <dir> --primary-stylesheet <file> [--pages <a.html,b.html>] [--json]`
 * (`cli/commands/theme/normalize-build.ts`, wired in `cli/program.ts`) is now this module's real
 * entrypoint — a standalone CLI a theme author runs locally or in their own CI after `ng build`, per
 * option (1) below, consistent with this codebase's "Tovu never runs the build" decision
 * (`build-conformance.ts`'s file header cites the same `worker_threads`-isn't-code-isolation
 * reasoning); running it server-side inside Tovu's own process remains a different, larger
 * architectural decision this module does not make. `outputDir`/`pageFileNames`/
 * `primaryStylesheetFile` are still supplied explicitly via `--pages`/`--primary-stylesheet` — option
 * (2) below's "derive from `angular.json`/`theme.json`" alternative was not built; not yet needed
 * with no real Angular theme shipping (see the frozen-fixture caveat in this module's own test file).
 * Still genuinely open: (3) theme-authoring documentation describing the full `ng build` → normalize
 * → compute `artifactHashes` → publish workflow end to end — no such workflow is written down
 * anywhere yet, and nothing in this repository computes `artifactHashes` for a compiled theme today
 * either (that remains a separate, unbuilt piece).
 */

import { lstatSync, mkdirSync, readdirSync, readFileSync, renameSync, unlinkSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

import { TOKEN_STYLESHEET_SENTINEL } from "./static-asset-contract.js";

/** Framework-emitted output files this module deletes outright rather than relocating or leaving in
 * place — see this module's file header ("Resolved risks") for why each entry is here. A file only
 * belongs on this list if Tovu's serving model has NO path that would ever read it; deleting a file
 * something still needs would be a silent breakage worse than the vacuous-pass problem this whole
 * normalizer/gate pairing exists to close. */
const DISCARDED_FRAMEWORK_ARTIFACTS: ReadonlySet<string> = new Set(["index.csr.html"]);

/** One top-level output file's relocation: `from` is its original flat filename (no path separators —
 * this module only reasons about files sitting directly in the build's output root, matching what a flat
 * bundler output like Angular's actually produces), `to` is where it belongs under Tovu's contract. */
export interface AssetRelocation {
  readonly from: string;
  readonly to: string;
}

/** How a build's flat output root maps onto Tovu's `css/`/`js/` split. Kept as data (not applied as a
 * side effect here) so {@link rewriteBundlerHtml} and {@link normalizeBuildOutputDirectory} can each
 * consume the same decision without re-deriving it. */
export interface AssetRelocationPlan {
  readonly relocations: readonly AssetRelocation[];
}

/**
 * Classifies a flat build-output file listing into what needs to move where. A file only moves if its
 * name ends in `.css`, `.js`, `.mjs`, or one of those three's `.map` sourcemap counterpart (`.css.map`,
 * `.js.map`, `.mjs.map`) — everything else (HTML pages, `favicon.ico`, an already-nested `media/` asset)
 * is left exactly where the build put it; Tovu's asset-path contract only ever concerns itself with
 * `../css/`/`../js/` references, so only those extensions are this function's business. A sourcemap
 * relocates to the SAME target directory as its bundle (`main.js.map` → `js/main.js.map`, right alongside
 * `main.js` → `js/main.js`) purely from its own filename's extension — it does not need to look up which
 * bundle it belongs to, because every bundle/map pair lands in the same directory either way.
 *
 * @param required.fileNames - Every file sitting directly in the build's flat output root (e.g. Angular's
 * `dist/<project>/browser/`). Subdirectory entries (already-nested paths containing `/`) are rejected —
 * see `@throws` — because a build whose output ISN'T flat is not the case this module exists to fix, and
 * silently no-op'ing on an already-nested `css/main.css` would hide that assumption breaking rather than
 * surface it.
 * @throws {RangeError} If any entry in `fileNames` contains a path separator.
 * @complexity O(n) over `fileNames`.
 */
/** Extensions that relocate to `css/` — a sourcemap counts as its bundle's own extension, per this
 *  function's own header. */
const RELOCATED_CSS_EXTENSIONS: readonly string[] = [".css", ".css.map"];
/** Extensions that relocate to `js/`. */
const RELOCATED_JS_EXTENSIONS: readonly string[] = [".js", ".mjs", ".js.map", ".mjs.map"];

/** One flat-output filename's relocation, or `null` if it stays exactly where the build put it — the
 *  per-entry classification `planAssetRelocation`'s loop applies. Split out so the loop itself carries
 *  none of the extension-matching branches. */
function classifyAssetRelocation(name: string): AssetRelocation | null {
  if (name.includes("/") || name.includes("\\")) {
    throw new RangeError(
      `planAssetRelocation expects a FLAT build-output root, but got '${name}' — a build whose output already has subdirectories is not the flat-output case this normalizer exists to fix; verify the build config (see this module's file header)`
    );
  }
  if (RELOCATED_CSS_EXTENSIONS.some((ext) => name.endsWith(ext))) {
    return { from: name, to: `css/${name}` };
  }
  if (RELOCATED_JS_EXTENSIONS.some((ext) => name.endsWith(ext))) {
    return { from: name, to: `js/${name}` };
  }
  return null;
}

export function planAssetRelocation(required: { fileNames: readonly string[] }, _optional: Record<string, never> = {}): AssetRelocationPlan {
  const { fileNames } = required;
  const relocations: AssetRelocation[] = [];

  for (const name of fileNames) {
    const relocation = classifyAssetRelocation(name);
    if (relocation) relocations.push(relocation);
  }

  return { relocations };
}

/**
 * Rewrites every bare-filename `href="fileName"`/`src="fileName"` occurrence in `html` to
 * `${attr}="${replacementValue}"` — anchored so the ENTIRE attribute value must equal `fileName` exactly
 * (same quote character on both sides), not merely contain it as a substring, so `main.js` never
 * accidentally matches inside `vendor-main.js` or a query-stringed `main.js?v=2`. Preserves every other
 * attribute on the tag untouched (only the one attribute value changes) — a `<script>`'s `type="module"`
 * or a `<link>`'s other attributes survive the rewrite verbatim.
 *
 * @complexity O(n) over `html`'s length — one regex scan per call.
 */
function rewriteExactBareAttributeValue(html: string, attr: "href" | "src", fileName: string, replacementValue: string): string {
  /** Escapes every regex metacharacter in `value` so it can be embedded literally inside a `RegExp` source
   * string — filenames are build output, not attacker input, but a `.` in `styles.css` must still match
   * only a literal dot, not "any character", or `stylesXcss` would wrongly match too. */
  const pattern = new RegExp(`(${attr}=)(["'])${RegExp.escape(fileName)}\\2`, "g");
  return html.replace(pattern, (_match, attrEquals: string, quote: string) => `${attrEquals}${quote}${replacementValue}${quote}`);
}

/**
 * Applies an {@link AssetRelocationPlan} to one page's raw HTML: every relocated `.css`/`.js`/`.mjs` file
 * that page's `<link>`/`<script>` tags reference by its ORIGINAL flat filename gets that reference
 * rewritten to the new `../css/`/`../js/`-relative location. The theme's single primary stylesheet
 * (`primaryStylesheetFile`, matching `angular.json`'s configured global-styles entry point) is handled
 * specially: rather than rewriting just its `href` attribute, the WHOLE `<link rel="stylesheet" ...>` tag
 * the build emitted is replaced with {@link TOKEN_STYLESHEET_SENTINEL} verbatim — the exact literal string
 * `checkBuiltThemeConformance`'s stylesheet-sentinel rule requires, imported from the single source of
 * truth (`static-asset-contract.ts`) rather than reconstructed here, so the two can never drift apart.
 *
 * @param required.html - One page's raw build-output HTML (e.g. Angular's emitted `index.html`).
 * @param required.plan - From {@link planAssetRelocation}, run over the SAME build's flat output listing.
 * @param required.primaryStylesheetFile - The relocated CSS file's original flat name that should become
 * the sentinel — e.g. `"styles.css"` when `angular.json`'s `styles` array names its one global entry
 * `src/styles.css` and `outputHashing` is `"none"` (Angular names the output bundle after the source
 * file's basename in that configuration — verified in the spike doc cited in this module's header).
 * @returns The page's HTML with every relocated asset reference rewritten.
 * @throws {Error} If `primaryStylesheetFile` names a file the plan does not relocate as CSS, or if the
 * expected plain `<link rel="stylesheet" href="${primaryStylesheetFile}">` tag shape is not found in
 * `html` — a precondition mismatch (e.g. Beasties' critical-CSS inlining left enabled) must surface
 * loudly here rather than silently ship a page missing the sentinel; see this module's file header for
 * why that precondition (`optimization.styles.inlineCritical: false`) is required upstream, in the build
 * config, not patched around after the fact.
 * @complexity O(r · n) — r = relocated files referenced, n = `html`'s length (each rewrite re-scans).
 */
export function rewriteBundlerHtml(
  required: { html: string; plan: AssetRelocationPlan; primaryStylesheetFile: string },
  _optional: Record<string, never> = {}
): string {
  const { plan, primaryStylesheetFile } = required;
  let { html } = required;

  const primaryRelocation = plan.relocations.find((r) => r.from === primaryStylesheetFile && r.from.endsWith(".css"));
  if (!primaryRelocation) {
    throw new Error(
      `rewriteBundlerHtml: primaryStylesheetFile '${primaryStylesheetFile}' is not among the plan's relocated CSS files — check angular.json's 'styles' entry point matches this value`
    );
  }

  const plainStylesheetTag = `<link rel="stylesheet" href="${primaryStylesheetFile}">`;
  if (!html.includes(plainStylesheetTag)) {
    throw new Error(
      `rewriteBundlerHtml: expected the plain build-output tag ${JSON.stringify(plainStylesheetTag)} in the page HTML but did not find it — ` +
        `if the build's critical-CSS inlining (Beasties) is still enabled, disable it via optimization.styles.inlineCritical: false ` +
        `(see ADS-memory/reports/spikes/20260812-angular-code-tier-build-output-verification.md, finding 4)`
    );
  }
  html = html.split(plainStylesheetTag).join(TOKEN_STYLESHEET_SENTINEL);

  for (const relocation of plan.relocations) {
    if (relocation.from === primaryStylesheetFile) continue; // already handled above, as the sentinel
    // Derived from the relocation's TARGET directory, not from re-parsing `from`'s extension a second
    // time — correct uniformly for `.css`/`.js`/`.mjs` and their `.map` counterparts alike, none of which
    // any real page HTML ever references by tag anyway (a sourcemap is reached only via its bundle's own
    // `//# sourceMappingURL=` comment, never an `href=`/`src=` attribute), so this is a harmless no-op for
    // `.map` entries rather than a load-bearing rewrite.
    const attr = relocation.to.startsWith("css/") ? "href" : "src";
    html = rewriteExactBareAttributeValue(html, attr, relocation.from, `../${relocation.to}`);
  }

  return html;
}

/** Matches a CSS `url(...)` function, capturing an optional surrounding quote (`'`/`"`, or none) and the
 * raw URL content between the parens. Does not attempt to handle an escaped quote or parenthesis INSIDE
 * the URL itself (`url('foo\'bar.png')`) — a real but narrower gap than the directory-shift problem this
 * exists to fix, and not a shape any bundler in this codebase's toolchain emits (matching the precedent
 * `rewriteAssetPaths`'s own doc in `static-asset-contract.ts` sets for scoping a regex to observed shapes
 * rather than every theoretical one). */
const CSS_URL_FUNCTION = /url\(\s*(["']?)([^"')]*)\1\s*\)/gi;

/** Whether a CSS `url(...)` reference is affected by its stylesheet moving one directory level deeper —
 * true for an ordinary relative path (`foo.png`, `../fonts/x.woff2`, `media/logo.png`), false for
 * anything already independent of the stylesheet's own location: a URL scheme (`data:`, `http:`, ...), a
 * protocol-relative (`//cdn...`) or root-relative (`/...`) path, a bare fragment (`#...`), or empty. */
function isRelativeCssUrl(value: string): boolean {
  if (value.length === 0) return false;
  if (value.startsWith("#")) return false;
  if (value.startsWith("/")) return false; // covers both root-relative '/x' and protocol-relative '//x'
  if (/^[a-z][a-z0-9+.-]*:/i.test(value)) return false; // has an explicit scheme, e.g. data:, http:, https:
  return true;
}

/**
 * Prepends `../` to every relative `url(...)` reference in a CSS file's own content — the compensation a
 * stylesheet needs when {@link normalizeBuildOutputDirectory} relocates it one directory level deeper
 * (output root → `css/`). `url(favicon.ico)` resolved against the output root before the move; after the
 * move, the SAME reference resolves against `css/` instead, which is the wrong location unless every such
 * reference gains one more `../` to compensate. Scheme-prefixed, root-relative, protocol-relative, and
 * fragment-only URLs are left untouched — see {@link isRelativeCssUrl}.
 *
 * @complexity O(n) over `cssContent`'s length — one regex scan.
 */
export function rewriteCssRelativeUrls(cssContent: string): string {
  return cssContent.replace(CSS_URL_FUNCTION, (match, quote: string, rawUrl: string) => {
    if (!isRelativeCssUrl(rawUrl)) return match;
    return `url(${quote}../${rawUrl}${quote})`;
  });
}

/** {@link normalizeBuildOutputDirectory}'s result: what moved, what was rewritten, and what was deleted.
 * Returned rather than left implicit so a caller (a CLI, a build script) can log or verify exactly what
 * changed, instead of re-deriving it by diffing the directory itself. */
export interface NormalizeBuildOutputResult {
  readonly plan: AssetRelocationPlan;
  readonly rewrittenPageFiles: readonly string[];
  readonly discardedFiles: readonly string[];
}

/**
 * The thin filesystem-effectful wrapper around this module's pure planning/rewriting functions: deletes
 * {@link DISCARDED_FRAMEWORK_ARTIFACTS}, reads `outputDir`'s remaining flat top-level listing, decides the
 * relocation plan ({@link planAssetRelocation}, pure), physically moves each relocated file (rewriting a
 * moved CSS file's own `url(...)` references via {@link rewriteCssRelativeUrls} immediately after it
 * lands at its new location), then rewrites every named page file's HTML in place on disk
 * ({@link rewriteBundlerHtml}, pure decision + effectful write). All of this repository's actual
 * matching/rewriting LOGIC lives in the pure functions this wraps — this function's own job is only
 * sequencing real I/O around them, which is why it has no dedicated unit tests of its own rewrite
 * correctness (those live on the pure functions); its own tests only need to prove the sequencing (files
 * really moved, pages really got rewritten on disk, discarded files are really gone).
 *
 * Directory entries are skipped, not relocated, even if their name happens to end in `.css`/`.js`/`.mjs`
 * — {@link planAssetRelocation}'s flat-output precondition is about FILES, and a same-named directory is
 * never something a real bundler emits, but skipping it here (via `lstatSync`) rather than deferring to
 * {@link planAssetRelocation}'s own path-separator check keeps this function's own contract (it hands
 * that function a flat FILE listing) honest without a special case leaking into the pure layer.
 *
 * @param required.outputDir - Absolute path to the build's flat output root (e.g. Angular's
 * `dist/<project>/browser/`). Mutated in place — files move or are deleted, page files are overwritten.
 * @param required.pageFileNames - Which top-level `.html` files in `outputDir` are pages to rewrite (an
 * Angular SPA build emits exactly one, `index.html`; a prerendered multi-route build emits one per route).
 * @param required.primaryStylesheetFile - Passed through to {@link rewriteBundlerHtml} for every page.
 * @throws Whatever {@link planAssetRelocation} or {@link rewriteBundlerHtml} throw — a precondition
 * violation must stop the normalization, not leave the output directory partially rewritten and silently
 * declared done.
 * @complexity O(f + p·n + c·m) — f = top-level file count (one `readdirSync` + one move per relocated
 * file), p = page count, n = average page HTML length, c = relocated CSS file count, m = average CSS
 * file length (one `rewriteCssRelativeUrls` pass per relocated CSS file).
 */
export function normalizeBuildOutputDirectory(
  required: { outputDir: string; pageFileNames: readonly string[]; primaryStylesheetFile: string },
  _optional: Record<string, never> = {}
): NormalizeBuildOutputResult {
  const { outputDir, pageFileNames, primaryStylesheetFile } = required;

  const allFileNames = readdirSync(outputDir).filter((name) => !lstatSync(join(outputDir, name)).isDirectory());
  const discardedFiles = allFileNames.filter((name) => DISCARDED_FRAMEWORK_ARTIFACTS.has(name));
  for (const name of discardedFiles) {
    unlinkSync(join(outputDir, name));
  }

  const fileNames = allFileNames.filter((name) => !DISCARDED_FRAMEWORK_ARTIFACTS.has(name));
  const plan = planAssetRelocation({ fileNames });

  for (const relocation of plan.relocations) {
    const destination = join(outputDir, relocation.to);
    mkdirSync(dirname(destination), { recursive: true });
    renameSync(join(outputDir, relocation.from), destination);
    if (relocation.from.endsWith(".css")) {
      writeFileSync(destination, rewriteCssRelativeUrls(readFileSync(destination, "utf8")), "utf8");
    }
  }

  for (const pageFileName of pageFileNames) {
    const pagePath = join(outputDir, pageFileName);
    const rewritten = rewriteBundlerHtml({ html: readFileSync(pagePath, "utf8"), plan, primaryStylesheetFile });
    writeFileSync(pagePath, rewritten, "utf8");
  }

  return { plan, rewrittenPageFiles: pageFileNames, discardedFiles };
}

import { isUtf8 } from "node:buffer";
import { randomBytes } from "node:crypto";
import { constants as fsConstants, copyFileSync, existsSync, lstatSync, mkdirSync, readdirSync, readFileSync, realpathSync, renameSync, rmSync, writeFileSync } from "node:fs";
import { basename, dirname, join } from "node:path";

import { rewriteThemeAssetPaths } from "./asset-path-rewrites.js";
import { fileExtension, fileGroup, TRASH_DIR_NAME } from "./file-identity-lock.js";
import { isRecognizedThemeRoot, MAX_LISTED_FILES, MAX_THEME_FILE_BYTES, MAX_WALK_DEPTH } from "./theme-files.js";
import { writeGeneratedThemeOriginal } from "./sync-originals.js";
import { MIGRATION_STAGING_DIR_PREFIX, nextAvailableThemeId, rescanThemes, THEME_CATALOG_DIR, type DiscoveredTheme, type ThemeTier } from "./theme.js";

/**
 * @file `duplicateTheme` — the one way a NEW theme folder comes into existence at runtime: copy an
 * existing discovered theme (a stock theme the site was seeded with counts — every stock theme is
 * a discovered theme under the site's own `themesDir`) into a fresh sibling folder, then give the
 * copy its own identity in `theme.json`.
 *
 * Two callers, one service (owner, 2026-10-08): the `theme_duplicate` agent tool
 * (`duplicate-theme-tool.ts`) and the admin Themes screen's Duplicate action
 * (`server/inbound/admin-http/routes/themes/duplicate.ts`). Both go through
 * {@link duplicateDiscoveredTheme}, so "what id does the copy get", "what counts as taken", and
 * "what gets refused" can never differ between the human and the agent.
 *
 * Same "copy the original, edit the copy" model `development/scripts/theme-tool.ts`'s `copy`
 * command implements for the CLI, including its `lineage` manifest field and its id-assignment rule
 * ({@link nextAvailableThemeId}). The source is only ever READ: every write lands in a staging
 * folder that is renamed into place at the end, so a refusal or crash halfway never leaves a
 * half-copied theme for discovery to find, and never touches the source.
 *
 * Generic? No — this is Tovu's on-disk theme layout (`<themesRoot>/<tier>/<id>/theme.json`), not a
 * Jini concern.
 */

/** Total bytes one duplicate may copy. 50 × the per-file text ceiling: the largest stock theme is
 *  ~2.5MB, so this only stops a pathological folder, never a real theme. */
export const MAX_DUPLICATE_THEME_BYTES = MAX_THEME_FILE_BYTES * 50;

/** Display-name length ceiling — a label, not a description. */
const MAX_THEME_NAME_LENGTH = 120;

/** Folder-safe id: lowercase alphanumerics and single hyphens, no leading/trailing hyphen, ≤ 64
 *  chars. Excludes `.`/`_` outright, so an id can never spell `..`, a dot-folder, or a `__catalog__`
 *  name. */
const THEME_ID_PATTERN = /^[a-z0-9](?:[a-z0-9-]{0,62}[a-z0-9])?$/;

/** The version a copy starts at — it is a new theme, not the source's next release. */
const DUPLICATE_INITIAL_VERSION = "1.0.0";

export type DuplicateThemeErrorCode =
  | "SOURCE_NOT_FOUND"
  | "INVALID_NAME"
  | "INVALID_ID"
  | "ID_TAKEN"
  | "SOURCE_NOT_COPYABLE"
  | "SYMLINK"
  | "TOO_LARGE"
  | "BAD_MANIFEST";

/** Every refusal {@link duplicateTheme} raises. A different input (or a different source) fixes each
 *  one, so callers map it to a 4xx / a tool input error, never a 500. `ID_TAKEN` is a conflict. */
export class DuplicateThemeError extends Error {
  readonly code: DuplicateThemeErrorCode;
  constructor(code: DuplicateThemeErrorCode, message: string) {
    super(message);
    this.name = "DuplicateThemeError";
    this.code = code;
  }
}

export interface DuplicateThemeResult {
  id: string;
  name: string;
  tier: ThemeTier;
  /** Absolute folder of the new theme. Callers addressing a model or a browser drop this. */
  dir: string;
  sourceThemeId: string;
  files: number;
  bytes: number;
}

/**
 * Turn a display name into a folder-safe id candidate: strip diacritics, lowercase, collapse every
 * run of non-alphanumerics to one hyphen, trim hyphens, cap at 48 chars (leaving room for a `-N`
 * suffix inside {@link THEME_ID_PATTERN}'s 64). Empty when the name has no Latin letters/digits.
 * @complexity O(n) in the name length.
 */
export function themeIdFromName(name: string): string {
  return name
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 48)
    .replace(/-+$/g, "");
}

/** Trimmed, length-checked, control-character-free display name, or a refusal. */
function validateThemeName(newName: string): string {
  const name = newName.trim();
  if (name.length === 0) throw new DuplicateThemeError("INVALID_NAME", "newName must not be empty");
  if (name.length > MAX_THEME_NAME_LENGTH) {
    throw new DuplicateThemeError("INVALID_NAME", `newName must be at most ${MAX_THEME_NAME_LENGTH} characters`);
  }
  // eslint-disable-next-line no-control-regex
  if (/[\u0000-\u001f\u007f]/.test(name)) throw new DuplicateThemeError("INVALID_NAME", "newName must not contain control characters");
  return name;
}

/**
 * The id the copy gets. An explicit `newId` is the caller's exact choice: malformed or taken is
 * refused, never silently suffixed (the caller asked for THAT id). An omitted one is derived from the
 * name and suffixed `-1`, `-2`, … through {@link nextAvailableThemeId} — the CLI's rule.
 */
function assignThemeId(
  required: { source: DiscoveredTheme; themesRoot: string; name: string; takenIds: ReadonlySet<string> },
  optional: { newId?: string }
): string {
  const { source, themesRoot, name, takenIds } = required;
  const parentDir = dirname(source.dir);
  const alsoTaken = (id: string): boolean => takenIds.has(id) || existsSync(join(parentDir, id));
  const pick = (desiredId: string): string =>
    nextAvailableThemeId({ desiredId, themesRoot, tier: source.manifest.tier }, { alsoTaken });

  if (optional.newId !== undefined) {
    if (!THEME_ID_PATTERN.test(optional.newId)) {
      throw new DuplicateThemeError(
        "INVALID_ID",
        `newId '${optional.newId}' must be lowercase letters, digits and single hyphens (1-64 chars, no leading/trailing hyphen)`
      );
    }
    if (pick(optional.newId) !== optional.newId) {
      throw new DuplicateThemeError("ID_TAKEN", `theme id '${optional.newId}' is already taken — pick another newId, or omit it to get a free one`);
    }
    return optional.newId;
  }
  return pick(themeIdFromName(name) || `${source.manifest.id}-copy`);
}

/** One file to copy, relative to the theme folder (`/`-separated). */
interface PlannedFile {
  relativePath: string;
  bytes: number;
}

/** What {@link planThemeCopy} accumulates: every file and folder to create, and the total bytes. */
interface ThemeCopyPlan {
  files: PlannedFile[];
  dirs: string[];
  bytes: number;
}

/**
 * Walk the source folder and plan the copy, refusing — before a single byte is written — anything
 * the theme store would not hold: a symlink anywhere (never followed, never copied: a link is how a
 * copy would read outside the theme), more files than {@link MAX_LISTED_FILES}, deeper than
 * {@link MAX_WALK_DEPTH}, or more than {@link MAX_DUPLICATE_THEME_BYTES} in total. The top-level
 * `.trash/` is skipped: soft-deleted files are not part of the theme.
 * @complexity O(n) in the source's file count, one `lstat` each.
 */
function planThemeCopy(sourceDir: string): ThemeCopyPlan {
  const plan: ThemeCopyPlan = { files: [], dirs: [], bytes: 0 };
  planThemeFolder({ plan, absDir: sourceDir, relDir: "", depth: 0 });
  return plan;
}

/**
 * Plan one folder of the copy (depth-first, sorted), recursing through {@link planThemeEntry}.
 * @throws {DuplicateThemeError} `TOO_LARGE` past {@link MAX_WALK_DEPTH}, plus every entry refusal.
 * @complexity O(e) in the folder's entry count, plus the recursion.
 */
function planThemeFolder(required: { plan: ThemeCopyPlan; absDir: string; relDir: string; depth: number }): void {
  const { absDir, relDir, depth } = required;
  if (depth > MAX_WALK_DEPTH) {
    throw new DuplicateThemeError("TOO_LARGE", `source theme is nested deeper than ${MAX_WALK_DEPTH} folders ('${relDir}')`);
  }
  for (const entry of readdirSync(absDir).sort()) {
    const relativePath = relDir ? `${relDir}/${entry}` : entry;
    if (relativePath === TRASH_DIR_NAME) continue;
    planThemeEntry({ plan: required.plan, absPath: join(absDir, entry), relativePath, depth });
  }
}

/**
 * Plan one folder entry: refuse a symlink, recurse into a folder, record a regular file, and skip
 * anything else (FIFOs, sockets, devices are not theme content).
 * @throws {DuplicateThemeError} `SYMLINK`, or a {@link planThemeFolder} / {@link addPlannedFile} refusal.
 * @complexity O(1) plus the recursion for a folder.
 */
function planThemeEntry(required: { plan: ThemeCopyPlan; absPath: string; relativePath: string; depth: number }): void {
  const { plan, absPath, relativePath, depth } = required;
  const stat = lstatSync(absPath);
  if (stat.isSymbolicLink()) {
    throw new DuplicateThemeError("SYMLINK", `source theme contains a symbolic link ('${relativePath}'); themes with links cannot be duplicated`);
  }
  if (stat.isDirectory()) {
    plan.dirs.push(relativePath);
    planThemeFolder({ plan, absDir: absPath, relDir: relativePath, depth: depth + 1 });
    return;
  }
  if (stat.isFile()) addPlannedFile({ plan, file: { relativePath, bytes: stat.size } });
}

/**
 * Record one file in the plan, refusing once the plan passes {@link MAX_LISTED_FILES} files or
 * {@link MAX_DUPLICATE_THEME_BYTES} bytes.
 * @throws {DuplicateThemeError} `TOO_LARGE`.
 * @complexity O(1).
 */
function addPlannedFile(required: { plan: ThemeCopyPlan; file: PlannedFile }): void {
  const { plan, file } = required;
  plan.bytes += file.bytes;
  plan.files.push(file);
  if (plan.files.length > MAX_LISTED_FILES) {
    throw new DuplicateThemeError("TOO_LARGE", `source theme has more than ${MAX_LISTED_FILES} files`);
  }
  if (plan.bytes > MAX_DUPLICATE_THEME_BYTES) {
    throw new DuplicateThemeError("TOO_LARGE", `source theme is larger than ${MAX_DUPLICATE_THEME_BYTES} bytes`);
  }
}

/**
 * Give the staged copy its own identity: `id` (must equal the folder name or the theme loads
 * `invalid`), `name`, a reset `version`, and `lineage` — the same metadata-only record the CLI's
 * `copy` writes (nothing at runtime reads it; it answers "what was this forked from").
 */
function rewriteCopiedManifest(stagingDir: string, identity: { id: string; name: string; source: DiscoveredTheme }): void {
  const manifestPath = join(stagingDir, "theme.json");
  let manifest: unknown;
  try {
    manifest = JSON.parse(readFileSync(manifestPath, "utf8"));
  } catch {
    throw new DuplicateThemeError("BAD_MANIFEST", `source theme '${identity.source.manifest.id}' has no readable theme.json`);
  }
  if (typeof manifest !== "object" || manifest === null || Array.isArray(manifest)) {
    throw new DuplicateThemeError("BAD_MANIFEST", `source theme '${identity.source.manifest.id}' has a theme.json that is not a JSON object`);
  }
  const record = manifest as Record<string, unknown>;
  const sourceVersion = String(record.version ?? identity.source.manifest.version);
  record.id = identity.id;
  record.name = identity.name;
  record.version = DUPLICATE_INITIAL_VERSION;
  record.lineage = { from: identity.source.manifest.id, tier: identity.source.manifest.tier, version: sourceVersion };
  writeFileSync(manifestPath, `${JSON.stringify(record, null, 2)}\n`, "utf8");
}

/**
 * Rebind absolute asset URLs in every staged text file before the copy and its stored original
 * become visible. Reuse the theme file groups to skip binary media (SVG is text), then inspect
 * bytes so templates, CSS and manifests all participate, including extensionless text. NUL-bearing
 * or invalid UTF-8 files stay byte-identical: decoding binary assets as UTF-8 and writing them back
 * would corrupt them.
 *
 * @throws Whatever `node:fs` throws; the caller removes staging on failure.
 * @complexity O(b) time and O(m) space for total copied bytes b and largest file size m, bounded by
 * the already-checked copy plan.
 */
function rewriteCopiedAssetPaths(required: {
  stagingDir: string;
  files: readonly PlannedFile[];
  sourceThemeId: string;
  targetThemeId: string;
}): void {
  const { stagingDir, files, sourceThemeId, targetThemeId } = required;
  for (const file of files) {
    if (fileGroup(file.relativePath, undefined) === "asset" && fileExtension(file.relativePath) !== ".svg") continue;
    const filePath = join(stagingDir, file.relativePath);
    const bytes = readFileSync(filePath);
    if (bytes.includes(0) || !isUtf8(bytes)) continue;
    const original = bytes.toString("utf8");
    const rewritten = rewriteThemeAssetPaths(
      { content: original, sourceThemeId, rules: [{ v1Prefix: "", v2Prefix: "" }] },
      { targetThemeId }
    );
    if (rewritten !== original) writeFileSync(filePath, rewritten, "utf8");
  }
}

/**
 * Snapshot the just-created copy into the site's originals catalog
 * (`<themesRoot>/__original-themes__/<tier>/<id>`), the same place a seeded theme's original lives,
 * so the copy's Explore has something to Reset to and shows no "no stored original" banner (owner
 * 2026-10-08). Reuses `writeGeneratedThemeOriginal` — the generator the shipped originals come from —
 * so a copy's original is filtered exactly like theirs. `nextAvailableThemeId` already counts a
 * catalog folder as taken, so the target is free and nothing existing is replaced.
 *
 * A copy without its original is the state this exists to end, so a failure here removes the copy
 * (a folder this same call just created) and rethrows — the caller sees one failed duplicate.
 *
 * @throws Whatever `node:fs` throws writing the catalog folder, after removing `destDir`.
 * @complexity O(f) in the copy's file count.
 */
function writeCopyOriginal(required: { destDir: string; themesRoot: string; tier: ThemeTier; id: string }): void {
  const { destDir, themesRoot, tier, id } = required;
  try {
    writeGeneratedThemeOriginal({ liveDir: destDir, targetDir: join(themesRoot, THEME_CATALOG_DIR, tier, id) });
  } catch (err) {
    rmSync(destDir, { recursive: true, force: true });
    throw err;
  }
}

/**
 * Copy `source` into a new sibling theme folder named after the assigned id.
 *
 * @param required.source - The discovered theme to copy. Only read, never written.
 * @param required.themesRoot - The site's themes root (`RouteDeps.themesDir`); the source must sit at
 * a recognized theme root under it.
 * @param required.newName - Display name for the copy (`theme.json` `name`).
 * @param required.takenIds - Every discovered theme id; the copy's id must not collide with any.
 * @param optional.newId - Exact id to use; refused if malformed or taken. Omitted ⇒ derived from
 * `newName` and suffixed until free.
 * @param optional.stagingSuffix - Test seam for the staging folder's random suffix.
 * @returns The new theme's id, name, tier, folder, and what was copied.
 * @throws {DuplicateThemeError} On any refusal; nothing is left on disk. A failed write of the copy's
 * stored original ({@link writeCopyOriginal}) also leaves nothing — the copy is removed.
 * @complexity O(n + b) in the source's file count and bytes (copied twice: the theme and its original).
 */
export function duplicateTheme(
  required: { source: DiscoveredTheme; themesRoot: string; newName: string; takenIds: ReadonlySet<string> },
  optional: { newId?: string; stagingSuffix?: () => string } = {}
): DuplicateThemeResult {
  const { source, themesRoot, takenIds } = required;
  if (!isRecognizedThemeRoot({ themeDir: source.dir, themesRoot }) || !existsSync(source.dir)) {
    throw new DuplicateThemeError("SOURCE_NOT_COPYABLE", `theme '${source.manifest.id}' is not inside this site's themes folder`);
  }
  const name = validateThemeName(required.newName);
  const id = assignThemeId({ source, themesRoot, name, takenIds }, { newId: optional.newId });

  const sourceDir = realpathSync(source.dir);
  const plan = planThemeCopy(sourceDir);
  const parentDir = dirname(source.dir);
  const destDir = join(parentDir, id);
  const suffix = optional.stagingSuffix?.() ?? randomBytes(6).toString("hex");
  const stagingDir = join(parentDir, `${MIGRATION_STAGING_DIR_PREFIX}duplicate-${id}-${suffix}`);

  try {
    mkdirSync(stagingDir);
    for (const dir of plan.dirs) mkdirSync(join(stagingDir, dir), { recursive: true });
    for (const file of plan.files) {
      copyFileSync(join(sourceDir, file.relativePath), join(stagingDir, file.relativePath), fsConstants.COPYFILE_EXCL);
    }
    rewriteCopiedAssetPaths({ stagingDir, files: plan.files, sourceThemeId: source.manifest.id, targetThemeId: id });
    rewriteCopiedManifest(stagingDir, { id, name, source });
    // Re-checked right before the rename: `renameSync` onto an EMPTY existing directory replaces it
    // silently on POSIX, so a folder created since `assignThemeId` must be refused here, not merged.
    if (existsSync(destDir)) throw new DuplicateThemeError("ID_TAKEN", `theme id '${id}' was taken while copying — try again`);
    renameSync(stagingDir, destDir);
  } catch (err) {
    rmSync(stagingDir, { recursive: true, force: true });
    throw err;
  }
  writeCopyOriginal({ destDir, themesRoot, tier: source.manifest.tier, id });

  return { id, name, tier: source.manifest.tier, dir: destDir, sourceThemeId: source.manifest.id, files: plan.files.length, bytes: plan.bytes };
}

/**
 * The service both callers use: find `sourceThemeId` among the live discovered themes, duplicate it,
 * then {@link rescanThemes} so the copy is in `themes` (the array every request reads) before this
 * returns — a duplicate the next page view cannot see would look like a failure.
 *
 * @returns The duplicate's result plus the copy's discovered entry (its `status`/`errors` tell the
 * caller whether it loaded `valid`).
 * @throws {DuplicateThemeError} `SOURCE_NOT_FOUND` for an unknown id, plus every {@link duplicateTheme} refusal.
 * @complexity O(n + b) for the copy, plus one full rediscovery (O(t) themes).
 */
export function duplicateDiscoveredTheme(
  required: { themes: DiscoveredTheme[]; themesDir: string; sourceThemeId: string; newName: string },
  optional: { newId?: string; stagingSuffix?: () => string } = {}
): { result: DuplicateThemeResult; theme: DiscoveredTheme | undefined } {
  const { themes, themesDir, sourceThemeId, newName } = required;
  const source = themes.find((t) => t.manifest.id === sourceThemeId);
  if (!source) {
    const known = themes.map((t) => t.manifest.id).join(", ") || "(none discovered)";
    throw new DuplicateThemeError("SOURCE_NOT_FOUND", `theme '${sourceThemeId}' was not found — discovered themes are: ${known}`);
  }
  const takenIds = new Set(themes.map((t) => t.manifest.id));
  const result = duplicateTheme({ source, themesRoot: themesDir, newName, takenIds }, optional);
  rescanThemes({ themes, dir: themesDir });
  return { result, theme: themes.find((t) => t.manifest.id === result.id && basename(t.dir) === result.id) };
}

import { resolveThemeLayout } from "./theme-layout.js";
import { isPageFilePath, isPartialFilePath } from "./theme-layout.js";
import { isGeneratedThemePath, type ThemeFileWriteScope } from "./theme-files.js";
import type { ThemeManifest } from "./theme.js";

/**
 * @file The shared "can this file's IDENTITY change" gate — extracted (2026-08-30) from
 * `server/inbound/admin-http/routes/themes/explore.ts`, which owned every one of these functions
 * privately until now, so its HTTP rename/delete routes were the ONLY callers. That was fine while
 * rename/delete were human-only operations, but adding `theme_rename_file` as an agent tool
 * (`features/theme/tool-registrations.ts`) meant a second caller needed the identical decision — and
 * `feature-no-server-or-framework-imports` (`.dependency-cruiser.mjs`, `error` severity) forbids a
 * `features/**` module from importing anything under `server/**`, even a type-only edge. There was
 * therefore no way for the agent-tool handlers to reach `explore.ts`'s copy without either violating
 * that boundary or re-deriving the same policy a second time — the exact "two gates that can drift
 * apart" risk `explore.ts`'s own prior doc comments already warned about for
 * `isThemeFileWritable`/`isGeneratedThemePath`. Moving the logic itself down into `features/theme` (a
 * direction `server -> features` already takes everywhere else in this file) resolves both problems
 * at once: `explore.ts` now imports this exactly like every other `features/theme` export it already
 * uses, and `tool-registrations.ts` imports the SAME functions as a same-module sibling.
 *
 * `theme_delete_file` (hard delete) is deliberately NOT one of the agent-tool callers — owner
 * decision 2026-08-30: agents get soft-delete only (`theme_trash_file`/`theme_restore_trashed_file`,
 * below), hard delete stays human-gated through `explore.ts`'s existing, unwidened HTTP route. This
 * module's {@link TRASH_DIR_NAME}/{@link trashDestinationFor}/{@link originalPathFromTrashedPath} are
 * the soft-delete half; the identity-lock gate itself (below) is shared by rename AND trash, exactly
 * as it was already shared by rename and (human) delete.
 *
 * Behavior is unchanged from the code this replaced — this is a relocation, not a rewrite. See
 * {@link validateFileIdentityChange}'s own doc for the three lock reasons, and `explore.ts`'s own
 * `IDENTITY_LOCKED_GROUPS` history (now here) for why `script` stays identity-locked even though its
 * CONTENT became editable (2026-08-29).
 */

/** Every group {@link fileGroup} can return. Renamed from `explore.ts`'s own `ThemeExploreFileGroup`
 *  now that a second module (`features/theme/tool-registrations.ts`) needs it too — `explore.ts`
 *  keeps exporting the old name as a type alias so nothing there had to change. */
export type ThemeFileGroup = "page" | "partial" | "style" | "script" | "config" | "asset" | "other";

/**
 * Media extensions that make up the `asset` group: images, video, audio, and fonts — the file kinds
 * an Explore author might replace but never hand-edits as source. (`.svg` is the one image format
 * also text-readable elsewhere, deliberately — see `explore.ts`'s `TEXT_READABLE_EXTENSIONS`.)
 */
const ASSET_EXTENSIONS = new Set([
  // Images
  ".png", ".jpg", ".jpeg", ".gif", ".webp", ".avif", ".svg", ".ico", ".bmp", ".tif", ".tiff",
  // Video
  ".mp4", ".webm", ".mov", ".avi", ".mkv", ".m4v",
  // Audio
  ".mp3", ".wav", ".ogg", ".m4a", ".flac", ".aac",
  // Fonts
  ".woff", ".woff2", ".ttf", ".otf", ".eot",
]);

function isAssetExtension(relativePath: string): boolean {
  const dot = relativePath.lastIndexOf(".");
  return dot === -1 ? false : ASSET_EXTENSIONS.has(relativePath.slice(dot).toLowerCase());
}

/** A path's own extension, lowercased (`""` if none) — the dot must fall after the last slash to
 *  count, matching {@link import("./theme-layout.js")}'s layout paths using the same rule. */
export function fileExtension(relativePath: string): string {
  const dot = relativePath.lastIndexOf(".");
  const slash = relativePath.lastIndexOf("/");
  return dot > slash ? relativePath.slice(dot).toLowerCase() : "";
}

/**
 * Coarse grouping for a theme file, derived from path/extension (plus the theme's own `apiVersion`,
 * for the page/partial cases) alone. See `explore.ts`'s original doc (git history) for the full
 * per-group reasoning; unchanged here, just relocated.
 */
export function fileGroup(relativePath: string, apiVersion: 2 | undefined): ThemeFileGroup {
  if (isPageFilePath(relativePath, apiVersion)) return "page";
  if (relativePath.endsWith(".css")) return "style";
  if (/\.(m|c)?js$/.test(relativePath)) return "script";
  if (/^(theme|tokens|tokens\.light)\.json$/.test(relativePath)) return "config";
  if (isPartialFilePath(relativePath, apiVersion)) return "partial";
  if (isAssetExtension(relativePath)) return "asset";
  return "other";
}

/**
 * Groups whose files can never be RENAMED or DELETED, regardless of content-editability —
 * unchanged from `explore.ts`'s original `IDENTITY_LOCKED_GROUPS`. `script` stays here on purpose
 * even though its CONTENT became editable (2026-08-29): nothing in this codebase tracks cross-file
 * references, so a `<script src="main.js">` (or an `other`-group `<link rel="manifest" ...>`) the
 * operator renamed or deleted would silently 404 on the live page with no way to trace what still
 * points at the old name. `other` stays for the same reason it was never a group an author was asked
 * to touch from Explore at all.
 */
export const IDENTITY_LOCKED_GROUPS: ReadonlySet<ThemeFileGroup> = new Set(["script", "other"]);

/** A framework's own source extensions inside a compiled theme's `build.sourceDir` — see
 *  `explore.ts`'s original `FRAMEWORK_SOURCE_EXTENSIONS`/`SOURCE_DIR_WRITABLE_EXTENSIONS` doc
 *  (git history) for the full browser-executable-content reasoning this excludes `.html`/`.svg`/
 *  `.js`/`.mjs`/`.cjs`/`.webmanifest` for. */
const FRAMEWORK_SOURCE_EXTENSIONS = new Set([".tsx", ".ts", ".jsx", ".vue", ".svelte", ".astro", ".scss", ".less"]);

const SOURCE_DIR_WRITABLE_EXTENSIONS = new Set([...FRAMEWORK_SOURCE_EXTENSIONS, ".css", ".json", ".md", ".txt"]);

/** Whether `relativePath` sits inside a BUILT theme's real, hand-authored source (ADR-020 §5,
 *  `build.sourceDir`) — the LOCATION half of the sourceDir carve-out; unchanged from `explore.ts`'s
 *  original `isInsideCompiledSourceDir`. */
export function isInsideCompiledSourceDir(
  theme: { manifest: Pick<ThemeManifest, "build"> },
  relativePath: string,
  writeScope: ThemeFileWriteScope
): boolean {
  return theme.manifest.build?.source === "compiled" && writeScope.kind === "editable" && relativePath !== "theme.json";
}

/** The extension half of the sourceDir carve-out — unchanged from `explore.ts`'s original
 *  `isSourceDirWritableExtension`. */
export function isSourceDirWritableExtension(relativePath: string): boolean {
  return SOURCE_DIR_WRITABLE_EXTENSIONS.has(fileExtension(relativePath));
}

/**
 * Files `loadTheme` treats as REQUIRED — their absence pushes a load error and flips a theme's
 * `status` to `"invalid"`. Unchanged from `explore.ts`'s original `requiredThemeFiles`; derived from
 * `resolveThemeLayout` so it stays in lockstep with `pagesDir`/`indexPagePath` rather than
 * re-spelling the same path a second time.
 */
export function requiredThemeFiles(apiVersion: 2 | undefined): readonly string[] {
  return resolveThemeLayout(apiVersion).requiredFiles;
}

/**
 * The top-level folder `theme_trash_file` moves a soft-deleted file into (2026-08-30, owner
 * decision: "agent can only do soft-delete and hard-delete is gated by needing a human" — see
 * `tool-registrations.ts`'s `theme_trash_file`/`theme_restore_trashed_file` for the operations that
 * use this).
 *
 * Deliberately NOT the `_unpublished/` convention an earlier agent invented ad hoc the same week to
 * hide a page from public routing (moving its file out of `render/pages/` and dropping it from
 * `theme.json`, entirely outside any audited read/write path — see that convention's own removal,
 * replaced by `ThemeManifest.publishedPages`). The lesson that removal leaves: a new "hidden" location
 * has to be a location every relevant scanner/writer explicitly knows about, not a side channel
 * nothing else is aware of. `.trash/` is that: every discovery loader in `theme.ts` only ever
 * `readdirSync`s a SPECIFIC named folder (`pagesDir`/`partialsDir`/`templatesDir`, never `themeDir`
 * itself), so a `.trash/` folder is invisible to page/partial/template discovery for every tier by
 * construction — but `theme_list_files` and `explore.ts`'s own file list are BOTH updated to filter
 * it out explicitly (not left to accidentally not-show-up), and `assertThemeFileWritable`/
 * `isThemeFileWritable` both refuse writing INTO it directly, so the only doors in or out are
 * `theme_trash_file`/`theme_restore_trashed_file` themselves.
 */
export const TRASH_DIR_NAME = ".trash";

/** Collapse a theme-relative path to comparable segments — `/` separators, no `.`, no `..`, no empty
 *  segments. A small local copy of the same normalization `theme-files.ts`'s own (private, exported
 *  by nothing) `normalizeThemeRelativePath` performs for `isGeneratedThemePath`, for the identical
 *  reason that function's own doc cites a real historical bypass for: comparing a path AS SPELLED
 *  would let `pages/../.trash/x` look like an ordinary `pages/` path to a caller that never resolves
 *  `..` before asking "is this in the trash folder". */
function normalizedPathSegments(relativePath: string): string[] {
  const segments: string[] = [];
  for (const segment of relativePath.split(/[\\/]/)) {
    if (segment === "" || segment === ".") continue;
    if (segment === "..") {
      segments.pop();
      continue;
    }
    segments.push(segment);
  }
  return segments;
}

/** Whether `relativePath` (once `.`/`..`-collapsed) is `.trash` itself or sits inside it. */
export function isTrashedThemePath(relativePath: string): boolean {
  return normalizedPathSegments(relativePath)[0] === TRASH_DIR_NAME;
}

/**
 * Where `theme_trash_file` moves `relativePath` to: `.trash/<epoch-ms>/<relativePath>`, preserving
 * the ORIGINAL relative path (including its own subfolders) verbatim under a per-operation, always-
 * unique timestamp segment.
 *
 * Why a timestamp segment rather than a `name-1`/`name-2` collision suffix on the trashed name itself
 * (the scheme `explore.ts`'s own `nextAvailableFileName` uses for copy/rename): a suffix on the
 * trashed name would make {@link originalPathFromTrashedPath}
 * lossy — stripping `.trash/` from `.trash/styles-1.css` cannot tell whether the true original was
 * `styles.css` (suffixed to avoid a collision) or genuinely `styles-1.css`. Nesting each trash
 * operation under its own timestamp folder instead makes the ORIGINAL path recoverable byte-for-byte
 * with no ambiguity. If the clock repeats a millisecond already present in the trash, advance the
 * timestamp until an unused folder is found. The caller supplies the current on-disk paths.
 */
export function trashDestinationFor(relativePath: string, existingPaths: ReadonlySet<string> = new Set()): string {
  const usedFolders = new Set(
    [...existingPaths].filter(isTrashedThemePath).map((existing) => normalizedPathSegments(existing)[1]),
  );
  let timestamp = Date.now();
  while (usedFolders.has(String(timestamp))) timestamp += 1;
  return `${TRASH_DIR_NAME}/${timestamp}/${relativePath}`;
}

/**
 * The inverse of {@link trashDestinationFor}: recovers the original relative path from a
 * `.trash/<epoch-ms>/<original>` path, or `null` if `trashedPath` is not shaped that way (not under
 * `.trash/` at all, or missing the timestamp segment) — a caller-supplied `trashedPath` that does not
 * match this shape is a shape error the caller should report (`tool-registrations.ts`'s
 * `theme_restore_trashed_file` throws `theme-files.ts`'s `ThemePathError` for it), not a value this
 * function should guess at.
 */
export function originalPathFromTrashedPath(trashedPath: string): string | null {
  const segments = normalizedPathSegments(trashedPath);
  if (segments.length < 3 || segments[0] !== TRASH_DIR_NAME) return null;
  return segments.slice(2).join("/");
}

/**
 * Whether `path`'s IDENTITY — its name (rename) or its existence (delete) — can change at all, given
 * its already-resolved write scope. Unchanged from `explore.ts`'s original `isFileIdentityChangeAllowed`:
 * inside a compiled theme's sourceDir, ONLY {@link isSourceDirWritableExtension} decides; everywhere
 * else, {@link IDENTITY_LOCKED_GROUPS} does.
 */
function isFileIdentityChangeAllowed(
  theme: { manifest: Pick<ThemeManifest, "apiVersion" | "build"> },
  path: string,
  writeScope: ThemeFileWriteScope
): boolean {
  return (
    !isGeneratedThemePath(path) &&
    (isInsideCompiledSourceDir(theme, path, writeScope)
      ? isSourceDirWritableExtension(path)
      : !IDENTITY_LOCKED_GROUPS.has(fileGroup(path, theme.manifest.apiVersion)))
  );
}

/** One reason `path`'s identity is locked, plus the transport-agnostic pieces both an HTTP response
 *  (`explore.ts`) and a thrown tool error (`tool-registrations.ts`) need: `status` for the former,
 *  `error`/`code` for both. Every reason today maps to 409/`Conflict` — kept as a field rather than
 *  hardcoded at each call site so a future reason with a different status is just a different value
 *  here, not a second place that has to remember the mapping. */
export interface FileIdentityLockResult {
  status: number;
  error: string;
  code: "REQUIRED_FILE_LOCKED" | "GENERATED_READONLY" | "READ_ONLY_FILE" | "NON_CANONICAL_PATH";
}

/**
 * The three independent reasons `path`'s identity might be locked against `action` (`"renamed"`,
 * `"deleted"`, or `"trashed"`), checked in priority order and collapsed into one result so a caller
 * has a single branch to make rather than three. Unchanged from `explore.ts`'s original
 * `validateFileIdentityChange` for `"renamed"`/`"deleted"` — see that function's git history for the
 * full per-reason reasoning (required file, ADR-020 generated tree, `IDENTITY_LOCKED_GROUPS`). `null`
 * means `path`'s identity may change.
 *
 * `"trashed"` (2026-08-30, owner decision) is the SAME question for `theme_trash_file`
 * (`tool-registrations.ts`) as `"deleted"` was for the `theme_delete_file` this replaced: soft-delete
 * still changes whether `path` exists at its current location, so every reason a hard delete would
 * have been refused applies identically — a theme's own required files stay un-trashable (the theme
 * would still drop to `status: "invalid"`), a built theme's generated tree stays un-trashable, and
 * `script`/`other` stay identity-locked (nothing tracks what still references a file by its old
 * location, whether that location stops existing via delete or merely moves via trash).
 *
 * The ONE shared gate for rename AND trash, and for both the HTTP surface (`explore.ts`'s rename
 * route) and the agent-tool surface (`tool-registrations.ts`'s `theme_rename_file`/
 * `theme_trash_file`) — see this file's own header for why a single relocated function, not
 * independently-written copies, is the point.
 */
export function validateFileIdentityChange(
  theme: { manifest: Pick<ThemeManifest, "apiVersion" | "build"> },
  path: string,
  writeScope: ThemeFileWriteScope,
  action: "renamed" | "deleted" | "trashed"
): FileIdentityLockResult | null {
  const hasNonCanonicalSegment = path
    .split("/")
    .some((segment) => segment === "" || segment === "." || segment === "..");
  if (hasNonCanonicalSegment || path.includes("\\")) {
    return {
      status: 400,
      error: `'${path}' is not a canonical theme path — remove empty, '.' and '..' segments`,
      code: "NON_CANONICAL_PATH",
    };
  }
  if (requiredThemeFiles(theme.manifest.apiVersion).includes(path)) {
    return {
      status: 409,
      error: `'${path}' cannot be ${action} — every theme requires it at this exact path`,
      code: "REQUIRED_FILE_LOCKED",
    };
  }
  if (writeScope.kind === "generated-readonly") {
    return { status: 409, error: `'${path}' is read-only: ${writeScope.reason}`, code: "GENERATED_READONLY" };
  }
  if (!isFileIdentityChangeAllowed(theme, path, writeScope)) {
    return { status: 409, error: `'${path}' is read-only in Explore and cannot be ${action}`, code: "READ_ONLY_FILE" };
  }
  return null;
}

import Handlebars from "handlebars";

/**
 * @file ADR-020 Tier-2 guardrail, Handlebars edition: the allowlist of
 * Handlebars helpers/expressions a `"handlebars"` theme may use, plus the
 * AST-walking check that enforces it.
 *
 * Purpose:
 * A `"handlebars"` theme ships raw `.hbs` source that runs on our server, the
 * same exposure the `"templated"` (LiquidJS) tier already carries. This module
 * is the direct counterpart of `liquid-allowlist.ts` and keeps the surface to
 * pure, non-I/O, non-dynamic logic. Enforcement walks the *parsed AST*
 * (`Handlebars.parse()`), not the raw source text, so a helper name appearing
 * inside a string literal or an HTML comment can neither trigger a false
 * positive nor slip past as a false negative.
 *
 * Why an allowlist is load-bearing HERE specifically. Handlebars' historical
 * CVE record (CVE-2019-19919, CVE-2021-23369, CVE-2021-23383 and relatives) is
 * a record of *compiling attacker-controlled template strings* — the exact
 * thing this tier does by design — escaping into prototype pollution and then
 * remote code execution. Those specific bugs are fixed in the pinned 4.7.x
 * line, but the shape of the risk is structural, not incidental: a template
 * language whose compiler emits JavaScript will keep finding new ways for
 * template text to reach the compiler's own object graph. Three constructs
 * carry essentially all of that risk and all three are refused outright below
 * rather than filtered:
 *   - `{{{triple-stash}}}` / `{{&amp;stash}}` raw output (the XSS seam),
 *   - `{{> partial}}` / `{{#> partial-block}}` (the partial-registry read,
 *     Handlebars' analogue of Liquid's `include`/`render` filesystem tags),
 *   - `{{#*inline}}` / `{{*decorator}}` (decorators, which mutate the
 *     runtime's own program/partial resolution from inside a template).
 *
 * How it relates to the project:
 * Called from the same two sites the Liquid allowlist is, matching ADR-020
 * §3's "lint before publish" + "defensive at render time" pair:
 *   - `features/theme/theme.ts`'s `loadTheme()` — lint every `.hbs`/
 *     `.handlebars` file at discovery time, folding violations into the
 *     existing `errors`/`status: "invalid"` mechanism.
 *   - `server/http/site/handlebars-worker.ts` — a second, redundant check
 *     immediately before render, in case a template was hot-edited on disk
 *     after a theme was validated (`loadTheme`'s result is not re-verified
 *     per request).
 */

/**
 * Block helpers (`{{#helper}}…{{/helper}}`) a theme may use. This is the
 * entire reviewed set — Handlebars' own built-in block registry beyond these
 * is `blockHelperMissing` (an internal fallback, never written by hand) and
 * the decorator forms, which are refused separately below.
 *
 * `each`/`if`/`unless`/`with` are pure control flow over already-shaped data:
 * none of them accepts an expression string to evaluate, which is what keeps
 * this list categorically safer than Liquid's `_exp` filter family (excluded
 * there for exactly that reason). Notably absent and deliberately so:
 * `log` (writes to the server's console from template text — an I/O side
 * effect a theme has no business having) and `lookup` (dynamic property
 * access by a runtime-computed key, i.e. `{{lookup this someKey}}`, which is
 * precisely the "reach an arbitrary property this template never named
 * literally" primitive the path rules below exist to close; Handlebars 4.6+
 * blocks prototype *properties* at runtime, but a dynamic key still defeats
 * static review of what a template can read).
 */
export const ALLOWED_HANDLEBARS_BLOCK_HELPERS: ReadonlySet<string> = new Set(["each", "if", "unless", "with"]);

/**
 * Helpers callable in mustache/subexpression position (`{{helper arg}}`,
 * `{{#if (helper arg)}}`). Exactly one entry, and it is Tovu's own:
 * `render_block` is the Handlebars-tier counterpart of the Liquid tier's
 * `{% render_block %}` tag — it resolves against the SAME in-process
 * `COMPONENTS` registry `render.ts` exports (and the same theme-declared
 * widget regions), never a filesystem path and never a theme-supplied
 * partial. That is what makes it a trusted seam back into core rather than a
 * capability: a theme can *arrange* core components, it cannot define one.
 *
 * There is no `registerHelper`/`registerPartial` surface exposed to a theme
 * at all, so this set is closed by construction — `handlebars-worker.ts`
 * builds its engine with `Handlebars.create()` (an isolated environment) and
 * registers only this one helper on it.
 */
export const ALLOWED_HANDLEBARS_HELPERS: ReadonlySet<string> = new Set(["render_block"]);

/**
 * The single unescaped-output seam, re-derived for Handlebars from the exact
 * argument Liquid's `| raw` filter rests on.
 *
 * `handlebars-worker.ts` compiles with escaping ON (`noEscape` left at its
 * default `false`), the direct counterpart of the Liquid engine's
 * `outputEscape: "escape"`. So `{{post.title}}` is HTML-escaped and a hostile
 * post title cannot inject markup. `{{{triple-stash}}}` opts *out* of that
 * per-expression, which makes it the tier's entire XSS surface — and unlike
 * Liquid's `raw`, it is syntax rather than a filter, so it cannot be dropped
 * from a filter allowlist. It is therefore refused for every expression
 * except the ones named here.
 *
 * `post.content` earns the exemption on the same basis `{{ post.content |
 * raw }}` does in `themes/templated/*`: that value is not theme data and not
 * user data as-typed — it is the server's own `renderDocNode()` output, HTML
 * this codebase generated from a TipTap document through a closed node
 * vocabulary with `escapeHtml()` on every text run and `safeHref()` on every
 * link (`render.ts`). It is already sanitized *before* a template ever sees
 * it, and escaping it again would render visible `&lt;p&gt;` tags to readers.
 * Nothing else qualifies: a theme reaching for `{{{site.title}}}` or
 * `{{{post.title}}}` is asking to emit an unsanitized string, which is the
 * bug this rule exists to catch at load time rather than in production.
 */
export const ALLOWED_HANDLEBARS_RAW_PATHS: ReadonlySet<string> = new Set(["post.content"]);

/**
 * `@`-prefixed data variables a theme may read. `each` publishes
 * `@index`/`@key`/`@first`/`@last` for its own body and a loop is unusable
 * without them.
 *
 * `@root` is excluded on least-privilege grounds — it re-enters the top-level
 * context from arbitrary depth, defeating the `with`/`each` scoping a
 * reviewer reads the template's data access off of, and every shipped theme
 * can reach what it needs through ordinary `../` parent paths.
 * `@partial-block` is excluded because partials themselves are (see
 * {@link lintHandlebarsTemplate}'s partial rules).
 */
export const ALLOWED_HANDLEBARS_DATA_VARS: ReadonlySet<string> = new Set(["index", "key", "first", "last"]);

/**
 * Path segments refused anywhere in any expression. Handlebars 4.6+ already
 * refuses prototype properties/methods at *runtime* by default
 * (`allowProtoPropertiesByDefault: false`, which `handlebars-worker.ts` also
 * sets explicitly rather than inheriting), so this is the static half of a
 * two-layer guarantee — the layer that turns "the render would have returned
 * empty" into "the theme never loads", which is the difference between a
 * silently broken page and a reviewable error. These are the segment names
 * every published Handlebars prototype-pollution chain has had to route
 * through.
 */
const FORBIDDEN_PATH_SEGMENTS: ReadonlySet<string> = new Set([
  "constructor",
  "prototype",
  "__proto__",
  "__defineGetter__",
  "__defineSetter__",
  "__lookupGetter__",
  "__lookupSetter__",
]);

/**
 * Source-size ceiling, mirroring the Liquid engine's own `parseLimit:
 * 1_000_000` (`liquid-worker.ts`). Handlebars exposes no equivalent knob, so
 * the cap is applied here, before `Handlebars.parse()` runs — which matters
 * more for this tier than for Liquid's, because `loadTheme()` calls this lint
 * on the MAIN thread at discovery time. The worker's `resourceLimits` protect
 * the render; only this protects the parse.
 */
const MAX_TEMPLATE_SOURCE_BYTES = 1_000_000;

/**
 * Block-nesting ceiling. Handlebars has no numeric-range literal, so it has
 * no direct counterpart to Liquid's `{% for i in (1..N) %}` one-shot
 * allocation vector (`MAX_FOR_RANGE_SPAN` in `liquid-allowlist.ts`) — every
 * `{{#each}}` iterates a real array the server itself shaped. The reachable
 * analogue is depth rather than breadth: deeply nested blocks recurse in both
 * Handlebars' own parser/compiler and in this walker, and a stack overflow
 * during the *lint* would happen on the main thread, outside any worker.
 * Capping the depth this walker will descend closes that, and no real theme
 * comes anywhere near 64 levels of nesting.
 */
const MAX_BLOCK_NESTING_DEPTH = 64;

/**
 * The minimal shape this walker relies on across every Handlebars AST node
 * kind. All fields are optional because different node kinds populate
 * different subsets — `ContentStatement`/`CommentStatement` have none of them;
 * `MustacheStatement` has `path`/`params`/`hash`/`escaped`;
 * `BlockStatement`/`DecoratorBlock`/`PartialBlockStatement` add
 * `program`/`inverse`; `PartialStatement` carries its target in `name` rather
 * than `path`. Typed structurally rather than against `@types/handlebars`'
 * `hbs.AST` union so the walker stays total over node kinds a future
 * Handlebars minor might add — an unrecognized node simply contributes no
 * usage rather than crashing the lint.
 */
interface HbsNode {
  type?: string;
  path?: HbsPath;
  name?: HbsPath;
  params?: HbsNode[];
  hash?: { pairs?: Array<{ value?: HbsNode }> };
  escaped?: boolean;
  program?: { body?: HbsNode[] };
  inverse?: { body?: HbsNode[] };
}

interface HbsPath {
  type?: string;
  parts?: string[];
  original?: string;
  data?: boolean;
  depth?: number;
}

/** True when a mustache/subexpression is unambiguously a helper INVOCATION rather than a data path. */
function isInvocation(node: HbsNode): boolean {
  return (node.params?.length ?? 0) > 0 || (node.hash?.pairs?.length ?? 0) > 0;
}

/** `{{a.b.c}}` → `"a.b.c"`; falls back to joined parts when `original` is absent. */
function pathText(path: HbsPath | undefined): string {
  return path?.original ?? (path?.parts ?? []).join(".");
}

/**
 * Validate one `PathExpression`'s segments: no prototype-chain segment
 * anywhere, and an `@`-data reference only to an allowlisted loop variable.
 */
function checkPath(path: HbsPath | undefined, violations: string[]): void {
  if (path?.type !== "PathExpression") return;
  const parts = path.parts ?? [];

  if (path.data === true) {
    const head = parts[0];
    if (head === undefined || !ALLOWED_HANDLEBARS_DATA_VARS.has(head)) {
      violations.push(`disallowed data variable "@${pathText(path).replace(/^@/, "")}"`);
    }
    // No early return: an allowlisted @-data head (`@index`, `@key`, …) says nothing about the
    // segments after it — `@index.constructor` has an allowed head and a forbidden tail, so it
    // still has to fall through to the same segment loop every non-`@` path goes through below.
  }

  for (const part of parts) {
    if (FORBIDDEN_PATH_SEGMENTS.has(part)) {
      violations.push(`disallowed path segment "${part}" in "${pathText(path)}"`);
    }
  }
}

/**
 * Depth guard shared by the two independent recursion paths through this walker: block bodies
 * (`walkHandlebarsNodes`, `{{#each}}`/`{{#if}}`/… nesting) and subexpressions
 * (`walkExpression`'s `SubExpression` arm, `(helper (helper …))` nesting). Neither path is a
 * counter-example against the other's depth cap without this — a template can only be proven
 * bounded if EVERY recursive descent checks the same ceiling before going one level deeper.
 * Extracted so each call site stays a single guard-and-return rather than duplicating the
 * over-limit branch (and its violation message) inline.
 */
function exceedsNestingDepth(depth: number, violations: string[]): boolean {
  if (depth <= MAX_BLOCK_NESTING_DEPTH) return false;
  violations.push(`template nesting exceeds the maximum allowed depth of ${MAX_BLOCK_NESTING_DEPTH}`);
  return true;
}

/** Walk a node's `params[]` and `hash.pairs[].value` as expressions — the argument-checking half
 * shared by `BlockStatement`, `MustacheStatement`, and `SubExpression` handling below. */
function walkParamsAndHash(node: HbsNode, depth: number, violations: string[]): void {
  for (const param of node.params ?? []) walkExpression(param, depth, violations);
  for (const pair of node.hash?.pairs ?? []) {
    if (pair.value) walkExpression(pair.value, depth, violations);
  }
}

/** `BlockStatement` (`{{#helper}}…{{/helper}}`): allowlist the helper name, walk its arguments,
 * then recurse into both branches one nesting level deeper. */
function handleBlockStatement(node: HbsNode, depth: number, violations: string[]): void {
  const name = pathText(node.path);
  if (!ALLOWED_HANDLEBARS_BLOCK_HELPERS.has(name)) {
    violations.push(`disallowed block helper "${name}"`);
  }
  walkParamsAndHash(node, depth, violations);
  walkHandlebarsNodes(node.program?.body ?? [], depth + 1, violations);
  walkHandlebarsNodes(node.inverse?.body ?? [], depth + 1, violations);
}

/** `MustacheStatement` (`{{expr}}`/`{{{expr}}}`): refuse raw output outside the allowlisted
 * paths, then classify the expression as a helper invocation (allowlisted by name) or a plain
 * data path (allowlisted by {@link checkPath}), and walk its arguments either way. */
function handleMustacheStatement(node: HbsNode, depth: number, violations: string[]): void {
  const name = pathText(node.path);

  if (node.escaped === false && !ALLOWED_HANDLEBARS_RAW_PATHS.has(name)) {
    // `{{{x}}}` and `{{&x}}` both parse to `escaped: false`, so this one check covers the whole
    // raw-output surface.
    violations.push(
      `disallowed raw output "{{{${name}}}}" — use "{{${name}}}" (escaped); raw output is permitted only for ${[...ALLOWED_HANDLEBARS_RAW_PATHS].map((p) => `{{{${p}}}}`).join(", ")}`
    );
  }

  if (isInvocation(node) || ALLOWED_HANDLEBARS_HELPERS.has(name)) {
    if (!ALLOWED_HANDLEBARS_HELPERS.has(name)) violations.push(`disallowed helper "${name}"`);
  } else {
    checkPath(node.path, violations);
  }

  walkParamsAndHash(node, depth, violations);
}

// Literal HTML / `{{! … }}` — no expression, nothing to check.
function handleNoopStatement(): void {}

// Handlebars' analogue of Liquid's `include`/`render`: resolves a name against the environment's
// partial registry, which in a filesystem-backed setup (the normal way Handlebars is deployed) is
// a file read, and in ANY setup is a jump to source this template did not contain. Tovu registers
// no partials at all and exposes no `registerPartial` to a theme, so there is nothing legitimate
// to resolve — refused as syntax rather than left to fail at render.
function handlePartialStatement(node: HbsNode, _depth: number, violations: string[]): void {
  violations.push(`disallowed partial "${pathText(node.name)}" (partials are not available to themes)`);
}

// `{{#*inline}}`/`{{*decorator}}` mutate the runtime's own program and partial resolution from
// inside template text. No theme need, and the single most direct route from "template author" to
// "compiler internals" the language offers.
function handleDecoratorStatement(node: HbsNode, _depth: number, violations: string[]): void {
  violations.push(`disallowed decorator "${pathText(node.path)}"`);
}

// Unknown statement kind: contribute no usage, but never let a nested body escape review because
// the wrapper was unrecognized.
function handleUnknownStatement(node: HbsNode, depth: number, violations: string[]): void {
  walkHandlebarsNodes(node.program?.body ?? [], depth + 1, violations);
  walkHandlebarsNodes(node.inverse?.body ?? [], depth + 1, violations);
}

/** Every node kind is dispatched explicitly here, and {@link handleUnknownStatement} (the
 * fallback for any type absent from this table) descends into `program`/`inverse` rather than
 * ignoring the node — so a construct this walker does not recognize can still never hide an
 * unreviewed block body beneath it. A lookup table rather than a `switch` because the branch
 * count (9 statement kinds) is the thing driving complexity here, not nesting. */
const STATEMENT_HANDLERS: Readonly<Record<string, (node: HbsNode, depth: number, violations: string[]) => void>> = {
  ContentStatement: handleNoopStatement,
  CommentStatement: handleNoopStatement,
  PartialStatement: handlePartialStatement,
  PartialBlockStatement: handlePartialStatement,
  Decorator: handleDecoratorStatement,
  DecoratorBlock: handleDecoratorStatement,
  BlockStatement: handleBlockStatement,
  MustacheStatement: handleMustacheStatement,
};

/**
 * Recursively walk a parsed template's statement list, collecting violations.
 *
 * @complexity O(n) in AST node count — one pass, no backtracking, no
 * re-visiting of a node.
 */
function walkHandlebarsNodes(nodes: HbsNode[], depth: number, violations: string[]): void {
  if (exceedsNestingDepth(depth, violations)) return;

  for (const node of nodes) {
    const handler = node.type !== undefined ? STATEMENT_HANDLERS[node.type] : undefined;
    (handler ?? handleUnknownStatement)(node, depth, violations);
  }
}

/**
 * Validate one expression appearing as a helper parameter or hash value —
 * a literal, a path, or a `(sub expression)`. A subexpression is a helper
 * invocation and is held to the same allowlist as a mustache one, which is
 * what stops `{{#if (lookup a b)}}` from smuggling a refused helper into an
 * allowed block's arguments.
 */
function walkExpression(node: HbsNode, depth: number, violations: string[]): void {
  if (node.type === "SubExpression") {
    if (exceedsNestingDepth(depth, violations)) return;
    const name = pathText(node.path);
    if (!ALLOWED_HANDLEBARS_HELPERS.has(name)) violations.push(`disallowed helper "${name}"`);
    // One nesting level deeper for THIS subexpression's own arguments — `(helper (helper …))`
    // recurses right back into `walkParamsAndHash` → `walkExpression`, the same unbounded path
    // `MAX_BLOCK_NESTING_DEPTH` exists to close, just reached through arguments instead of a block
    // body.
    walkParamsAndHash(node, depth + 1, violations);
    return;
  }
  if (node.type === "PathExpression") checkPath(node as HbsPath, violations);
}

/**
 * Lint a `.hbs` template source against the Handlebars tier's helper/
 * expression allowlist.
 *
 * Uses `Handlebars.parse()`, which produces an AST and nothing else — no
 * compilation to JavaScript, no `new Function`, no execution. That
 * distinction is the whole reason this check is safe to run against
 * untrusted theme content on the main thread at discovery time: every
 * Handlebars RCE class of note begins at *compile*, and a template that fails
 * this lint is never compiled at all.
 *
 * @param source raw `.hbs` template text (untrusted — third-party theme
 *   content).
 * @returns human-readable violation messages; empty means the template is
 *   clean. A Handlebars syntax error is reported the same way (as a single
 *   violation message) rather than thrown, so every caller can treat this
 *   function as a total, non-throwing predicate — the same contract
 *   `lintLiquidTemplate` offers.
 * @complexity O(n) in template size — one parse plus one AST walk.
 * @overallScore 100/100
 */
export function lintHandlebarsTemplate(source: string): string[] {
  if (source.length > MAX_TEMPLATE_SOURCE_BYTES) {
    return [`template exceeds the maximum allowed size of ${MAX_TEMPLATE_SOURCE_BYTES} bytes`];
  }

  let program: { body?: HbsNode[] };
  try {
    program = Handlebars.parse(source) as unknown as { body?: HbsNode[] };
  } catch (err) {
    return [`Handlebars syntax error: ${(err as Error).message}`];
  }

  // Deliberately a SECOND try/catch, not one widened to cover both `parse()` and the walk: parse
  // failures are theme-author syntax mistakes (message stays "Handlebars syntax error"), while
  // anything escaping the walk below is a bug in this file's own traversal — worth a distinct
  // message so a human reading `errors` can tell which side broke. The depth guard threaded through
  // both `walkHandlebarsNodes` and `walkExpression`/`walkParamsAndHash` (see
  // `exceedsNestingDepth`) is what actually stops runaway recursion; this catch is belt-and-
  // suspenders so a walker bug this guard doesn't anticipate still fails CLOSED — the template is
  // rejected — rather than throwing past this function's documented "total, non-throwing predicate"
  // contract and crashing `loadTheme()`'s caller, which wraps nothing in try/catch of its own.
  const violations: string[] = [];
  try {
    walkHandlebarsNodes(program.body ?? [], 0, violations);
  } catch (err) {
    return [`Handlebars template failed lint: ${(err as Error).message}`];
  }
  // De-duplicated because a template can reach the same violation through several branches (a
  // depth overrun trips once for a block's `program` and again for its `inverse`; the same
  // disallowed helper repeated in a loop body trips per occurrence). The caller folds these into a
  // theme's `errors` list for a human to read — the distinct set of problems is the useful signal,
  // not the multiplicity.
  return [...new Set(violations)];
}

import { markersOfType, maskNonRenderableRegions, MENU_MARKER_TYPE } from "@jini-ai/cms/widgets/markers";

/**
 * @file Finds a header, nav or footer partial that hard-codes a list of links instead of rendering a
 * menu through a menu marker.
 *
 * Why: links baked into a partial never show in Admin → Menus, so the owner cannot edit them (Luvira
 * import, 2026-10-08: the copied theme's `footer.html` hard-coded its "Explore" and "Legal" columns).
 * The theme write tools still write the file — a partial may carry plain links on purpose — and
 * return this as a warning so the model creates the menus and swaps in markers on its next turn,
 * the same warn-don't-refuse shape as `features/pages/hidden-until-script.ts`.
 *
 * PURE: string in, findings out. A tolerant scan, not an HTML parser; comments and raw-text elements
 * are masked first (the same mask the marker scanner uses), and a menu marker's whole element is
 * blanked because the links inside it are only its fallback.
 */

/** Fewer internal links than this (a brand link, one CTA) is not a list. */
export const MIN_HARDCODED_LINK_LIST = 3;
/** Links named in the warning before the rest are summarised. */
const MAX_NAMED_LINKS = 10;

/** `nav.html`, `site-header.html`, `footer-minimal.html`, `navbar.hbs` — the partials that carry link lists. */
const CHROME_PARTIAL = /(?:^|[-_.])(?:header|footer|nav|navbar|navigation|menu)(?:[-_.][^/]*)?\.(?:html?|hbs|handlebars|liquid)$/i;
const ANCHOR_HREF = /<a\b(?:[^>"']|"[^"]*"|'[^']*')*?\bhref\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>"']+))/gi;
/** `https:`, `mailto:`, `tel:`, `javascript:` … — not a link to a page of this site. */
const URL_SCHEME = /^[a-z][a-z0-9+.-]*:/i;

function isInternalHref(href: string): boolean {
  const trimmed = href.trim();
  if (trimmed === "" || trimmed.startsWith("#") || trimmed.startsWith("//")) return false;
  // A templated href (`{{ url }}`, `{% … %}`) is already data-driven, not a hard-coded link.
  if (trimmed.includes("{{") || trimmed.includes("{%")) return false;
  return !URL_SCHEME.test(trimmed);
}

/** `html` with every comment, raw-text body and menu-marker element blanked to spaces, same length. */
function maskMenusAndNonRenderable(html: string): string {
  let masked = maskNonRenderableRegions({ html });
  for (const marker of markersOfType({ html, type: MENU_MARKER_TYPE })) {
    masked = masked.slice(0, marker.index) + " ".repeat(marker.whole.length) + masked.slice(marker.index + marker.whole.length);
  }
  return masked;
}

/**
 * Every internal link href written outside a menu marker, in document order.
 * @param required.html - A partial's markup.
 * @returns The hrefs, as authored; empty when every internal link sits inside a menu marker.
 * @complexity O(n · m) for n characters and m menu markers (m is a handful in any partial).
 */
export function findHardcodedLinks({ html }: { html: string }, _optional: {} = {}): readonly string[] {
  const hrefs: string[] = [];
  for (const match of maskMenusAndNonRenderable(html).matchAll(ANCHOR_HREF)) {
    // ANCHOR_HREF's three value groups are alternatives, so exactly one is captured and the other
    // two are undefined; join("") renders undefined as "", yielding the one authored value.
    const href = match.slice(1).join("");
    if (isInternalHref(href)) hrefs.push(href.trim());
  }
  return hrefs;
}

/**
 * The model-facing warning for a header/nav/footer partial that hard-codes a link list, or
 * `undefined` when the path is not such a partial or its links are menu-rendered.
 * @param required.path - The theme-relative path just written.
 * @param required.content - The file's full content after the write.
 * @complexity O(n) in the content length.
 */
export function describeHardcodedLinkList({ path, content }: { path: string; content: string }, _optional: {} = {}): string | undefined {
  if (!CHROME_PARTIAL.test(path.slice(path.lastIndexOf("/") + 1))) return undefined;
  const links = findHardcodedLinks({ html: content });
  if (links.length < MIN_HARDCODED_LINK_LIST) return undefined;
  const named = links.length <= MAX_NAMED_LINKS ? links.join(", ") : `${links.slice(0, MAX_NAMED_LINKS).join(", ")}, ...`;
  return (
    `Written, but this partial hard-codes ${links.length} links (${named}) outside any menu marker, so the owner ` +
    "cannot edit them in Admin → Menus. Make each link list a menu (menus_create_menu, e.g. slug \"footer-explore\") " +
    `and render it here with <div data-embed-config='{"type":"menu","id":"<menu slug>"}'>…</div>, keeping the ` +
    "column heading and classes; links inside the marker are only a fallback."
  );
}

/**
 * @file Tier-specific v2 migration plans — pure functions that decide WHERE a v1 theme's files move
 * to under schema v2's invariant folder shape, without touching disk. Kept separate from
 * `migrate-theme.ts`'s orchestrator so each tier's move logic is independently testable and so a
 * tier not yet supported here fails loudly (`planV2Migration` throws) rather than the orchestrator
 * silently doing nothing.
 *
 * `declarative`/`templated`/`handlebars` share one planner (`planNonStaticTierMigration`) — all three
 * keep the identical v1 shape (an optional root `styles.css`, a `templates/` folder of one extension,
 * an optional flat root `assets/` bag), verified directly against real themes in both tiers before
 * generalizing (`basic-declarative`, `storefront`, `fashion-modern`). `static` has a materially
 * different v1 shape (`pages/`, root partials, `js/`, a much larger `images/` set) and gets its own
 * planner (`planStaticTierMigration`), verified directly against `fuel` before writing it — see that
 * function's own header for what it deliberately does not yet handle (`basic`'s generated `preview/`).
 */

import { existsSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";

import type { ThemeTier } from "../theme.js";

/** One file relocation, both paths relative to the theme's own root. */
export interface MigrationFileMove {
  readonly from: string;
  readonly to: string;
}

/** A moved folder's old/new URL prefix under `/theme-assets/<id>/...` — a file move alone leaves any
 * hardcoded absolute reference to the old location pointing at a 404 (`theme-static-assets.ts` serves
 * a theme's folder with zero path remapping), so the orchestrator uses this to rewrite the moved
 * page/partial files' own content, not just relocate bytes. */
export interface AssetPathRewriteRule {
  readonly v1Prefix: string;
  readonly v2Prefix: string;
}

export interface ThemeMigrationPlan {
  readonly moves: readonly MigrationFileMove[];
  /** Root-level entries this plan found but has no move rule for — surfaced so the orchestrator can
   * refuse rather than silently drop an author's file the planner didn't anticipate. */
  readonly unrecognized: readonly string[];
  /** Present only when a moved folder's absolute `/theme-assets/<id>/...` URL prefix changed. */
  readonly assetPathRewrites?: readonly AssetPathRewriteRule[];
}

/** Root-level entries every tier's plan treats as already-correct (copied byte-identical, never
 * moved) — `theme.json` gets its own manifest rewrite, not a raw copy. `screenshots` is real
 * author-owned marketing content the v2 schema now approves at the same root location (see
 * `structure.ts`'s `V2_APPROVED_ROOTS`) — every real theme on disk ships one. `NOTICE.md` is a v2
 * approved root by the same name, free-text provenance prose only the static tier's real themes
 * carry today. */
const CARRY_OVER_UNCHANGED: ReadonlySet<string> = new Set(["tokens.json", "screenshots", "NOTICE.md"]);

export const TOKENS_MODE_FILE_PATTERN = /^tokens\.[a-z0-9-]+\.json$/;

/** The `templates/` file extension(s) each non-static tier ships, matching `loadTheme()`'s own
 * per-extension dispatch (`theme.ts`'s inline templates-dir scan) — a file in `templates/` with any
 * OTHER extension is a real authoring surprise this planner refuses to guess about. */
const NON_STATIC_TIER_EXTENSIONS: Readonly<Record<"declarative" | "templated" | "handlebars", readonly string[]>> = {
  declarative: [".json"],
  templated: [".liquid"],
  handlebars: [".hbs", ".handlebars"],
};

/** The `templates/` folder's own moves and its non-matching-extension unrecognized entries — pulled
 * out of `planNonStaticTierMigration` because a `for` loop plus its inner branch is the bulk of that
 * function's own complexity, and this section is fully self-contained (no other section reads or
 * writes `templates/`). */
function planTemplatesFolderMoves(
  themeDir: string,
  extensions: readonly string[]
): { moves: MigrationFileMove[]; unrecognized: string[] } {
  const templatesDir = join(themeDir, "templates");
  const moves: MigrationFileMove[] = [];
  const unrecognized: string[] = [];
  if (!existsSync(templatesDir)) return { moves, unrecognized };

  for (const file of readdirSync(templatesDir)) {
    if (extensions.some((ext) => file.endsWith(ext))) {
      moves.push({ from: `templates/${file}`, to: `render/pages/${file}` });
    } else {
      unrecognized.push(`templates/${file}`);
    }
  }
  return { moves, unrecognized };
}

/** A flat root `assets/` bag (fashion-modern's real shape: one hero photo, no images/video/audio/
 * fonts/files subfolders yet) nests under v2's `assets/images/` — any moved page's own absolute
 * `/theme-assets/<id>/assets/...` reference has to move with it (see AssetPathRewriteRule's header). */
function planFlatAssetsFolderMoves(themeDir: string): { moves: MigrationFileMove[]; assetPathRewrites: AssetPathRewriteRule[] } {
  const assetsDir = join(themeDir, "assets");
  if (!existsSync(assetsDir)) return { moves: [], assetPathRewrites: [] };

  const moves = readdirSync(assetsDir).map((file) => ({ from: `assets/${file}`, to: `assets/images/${file}` }));
  return { moves, assetPathRewrites: [{ v1Prefix: "assets/", v2Prefix: "assets/images/" }] };
}

/** Root-level entries `planNonStaticTierMigration` already gave their own section — a `Set` lookup
 * instead of a 4-way `||` so this stays a single branch no matter how many roots are reserved. */
const NON_STATIC_TIER_SKIP_ROOTS: ReadonlySet<string> = new Set(["theme.json", "styles.css", "templates", "assets"]);

function planNonStaticRootScan(themeDir: string): string[] {
  const unrecognized: string[] = [];
  for (const name of readdirSync(themeDir)) {
    if (NON_STATIC_TIER_SKIP_ROOTS.has(name)) continue;
    if (CARRY_OVER_UNCHANGED.has(name) || TOKENS_MODE_FILE_PATTERN.test(name)) continue;
    unrecognized.push(name);
  }
  return unrecognized;
}

/**
 * `declarative`/`templated`/`handlebars` tiers: theme root has an OPTIONAL single `styles.css`
 * (-> `css/theme.css` — `storefront`, a real templated theme, ships none at all, relying entirely on
 * core `render_block` component styling) and a `templates/` folder of the tier's own route-file
 * extension (-> `render/pages/`). No partials, no scripts, no per-page asset-path rewriting — neither
 * declarative JSON props nor a templated theme's `render_block`/product-data Liquid syntax carry a
 * relative asset path the way static HTML's `../css/`/`../js/` does. Verified directly against
 * `basic-declarative` and `storefront`'s real files before writing this planner.
 *
 * @complexity O(f) in the theme root's own (small) entry count.
 */
function planNonStaticTierMigration(
  themeDir: string,
  tier: "declarative" | "templated" | "handlebars"
): ThemeMigrationPlan {
  const stylesCssMove: MigrationFileMove[] = existsSync(join(themeDir, "styles.css"))
    ? [{ from: "styles.css", to: "css/theme.css" }]
    : [];
  const templates = planTemplatesFolderMoves(themeDir, NON_STATIC_TIER_EXTENSIONS[tier]);
  const assets = planFlatAssetsFolderMoves(themeDir);

  const moves = [...stylesCssMove, ...templates.moves, ...assets.moves];
  const unrecognized = [...templates.unrecognized, ...planNonStaticRootScan(themeDir)];

  return { moves, unrecognized, ...(assets.assetPathRewrites.length > 0 ? { assetPathRewrites: assets.assetPathRewrites } : {}) };
}

/** POSIX-relative paths of every FILE under `dir` (recursive) — used for `js/` -> `scripts/`, the one
 * v1 static-tier folder with real nested structure (`js/vendor/<lib>/...`), so the vendor subfolder
 * moves intact rather than needing its own hardcoded case.
 *
 * @complexity O(f) in the folder's own file count.
 */
function walkFilesRecursive(dir: string, relPrefix = ""): string[] {
  const out: string[] = [];
  for (const name of readdirSync(dir)) {
    const rel = relPrefix ? `${relPrefix}/${name}` : name;
    if (statSync(join(dir, name)).isDirectory()) {
      out.push(...walkFilesRecursive(join(dir, name), rel));
    } else {
      out.push(rel);
    }
  }
  return out;
}

/** Root-level partial filenames `theme.ts`'s `DEFAULT_THEME_SLOTS` recognizes by convention (exact
 * stem match, or `<stem>-*` for a named variant like `footer-minimal.html`) — mirrors
 * `loadSlotPartials`'s own matching rule rather than requiring the migrated manifest to declare a
 * `partials` field the runtime doesn't actually need (that field is optional metadata nothing in
 * `loadTheme()` requires; see this module's own header for why nothing here invents metadata that
 * isn't already there). */
const PARTIAL_SLOT_STEMS: readonly string[] = ["nav", "footer"];

function isConventionalPartialFile(name: string): boolean {
  if (!name.endsWith(".html")) return false;
  return PARTIAL_SLOT_STEMS.some((stem) => name === `${stem}.html` || name.startsWith(`${stem}-`));
}

/** `css/` has exactly one recognized entry (`styles.css`); everything else in that folder is
 * unrecognized rather than silently skipped, same policy as the tier's other folders. */
function planCssFolderMoves(themeDir: string): { moves: MigrationFileMove[]; unrecognized: string[] } {
  const cssDir = join(themeDir, "css");
  const moves: MigrationFileMove[] = [];
  const unrecognized: string[] = [];
  if (!existsSync(cssDir)) return { moves, unrecognized };

  for (const file of readdirSync(cssDir)) {
    if (file === "styles.css") moves.push({ from: "css/styles.css", to: "css/theme.css" });
    else unrecognized.push(`css/${file}`);
  }
  return { moves, unrecognized };
}

/** `js/**` moves to `scripts/**` wholesale, nesting preserved (`js/vendor/<lib>/...` is the one v1
 * static-tier folder with real nested structure) — every file found is recognized, so there is no
 * unrecognized side to this section. */
function planScriptsFolderMoves(themeDir: string): MigrationFileMove[] {
  const jsDir = join(themeDir, "js");
  if (!existsSync(jsDir)) return [];
  return walkFilesRecursive(jsDir).map((rel) => ({ from: `js/${rel}`, to: `scripts/${rel}` }));
}

/** OPTIONAL `images/` folder (-> `assets/images/`, with the matching {@link AssetPathRewriteRule}
 * for any moved page's own hardcoded `/theme-assets/<id>/images/...` reference) — `tailark-*` ship
 * no `images/` at all, so the rule comes back absent rather than a no-op empty array. */
function planImagesFolderMoves(themeDir: string): { moves: MigrationFileMove[]; assetPathRewrites: AssetPathRewriteRule[] } {
  const imagesDir = join(themeDir, "images");
  if (!existsSync(imagesDir)) return { moves: [], assetPathRewrites: [] };

  const moves = readdirSync(imagesDir).map((file) => ({ from: `images/${file}`, to: `assets/images/${file}` }));
  return { moves, assetPathRewrites: [{ v1Prefix: "images/", v2Prefix: "assets/images/" }] };
}

/** `pages/*.html` -> `render/pages/`; a non-`.html` entry is unrecognized rather than silently
 * dropped or guessed at. */
function planPagesFolderMoves(themeDir: string): { moves: MigrationFileMove[]; unrecognized: string[] } {
  const pagesDir = join(themeDir, "pages");
  const moves: MigrationFileMove[] = [];
  const unrecognized: string[] = [];
  if (!existsSync(pagesDir)) return { moves, unrecognized };

  for (const file of readdirSync(pagesDir)) {
    if (file.endsWith(".html")) moves.push({ from: `pages/${file}`, to: `render/pages/${file}` });
    else unrecognized.push(`pages/${file}`);
  }
  return { moves, unrecognized };
}

/** Root-level entries the static tier's other sections already own. */
const STATIC_TIER_SKIP_ROOTS: ReadonlySet<string> = new Set(["theme.json", "css", "js", "images", "pages"]);

/** Root partial files matching a known slot stem move to `render/partials/`; everything else
 * carried-over or already-recognized is skipped, and anything left is unrecognized. */
function planStaticRootScan(themeDir: string): { moves: MigrationFileMove[]; unrecognized: string[] } {
  const moves: MigrationFileMove[] = [];
  const unrecognized: string[] = [];
  for (const name of readdirSync(themeDir)) {
    if (STATIC_TIER_SKIP_ROOTS.has(name)) continue;
    if (isConventionalPartialFile(name)) {
      moves.push({ from: name, to: `render/partials/${name}` });
      continue;
    }
    if (CARRY_OVER_UNCHANGED.has(name) || TOKENS_MODE_FILE_PATTERN.test(name)) continue;
    unrecognized.push(name);
  }
  return { moves, unrecognized };
}

/**
 * `static` tier: `css/styles.css` (-> `css/theme.css`), `js/**` (-> `scripts/**`, nesting preserved),
 * `pages/*.html` (-> `render/pages/`), root partial files matching a known slot stem (-> `render/
 * partials/`), and an OPTIONAL `images/` folder (-> `assets/images/`, with the matching
 * {@link AssetPathRewriteRule} for any moved page's own hardcoded `/theme-assets/<id>/images/...`
 * reference — `tailark-*` ship no `images/` at all, so the rule is absent rather than a no-op empty
 * array). Verified directly against `fuel`'s real files before writing this planner; `basic`'s
 * `preview/` (generated output) and `build-preview.mjs` (its own regeneration script) are
 * DELIBERATELY left unrecognized here — regenerating derived output is a different operation from
 * relocating source, out of scope for this planner (see `migrate-theme.ts`'s own header for that
 * theme's separate handling).
 *
 * Each top-level folder's own move/unrecognized logic lives in its own `plan*FolderMoves()`
 * function below (one `for` loop plus its inner branch each) — this function only sequences and
 * merges their results, which is why it stays flat despite covering five sections.
 *
 * @complexity O(f) in the theme's own file count (one walk per top-level folder, one root scan).
 */
function planStaticTierMigration(themeDir: string): ThemeMigrationPlan {
  const css = planCssFolderMoves(themeDir);
  const scripts = planScriptsFolderMoves(themeDir);
  const images = planImagesFolderMoves(themeDir);
  const pages = planPagesFolderMoves(themeDir);
  const rootScan = planStaticRootScan(themeDir);

  const moves = [...css.moves, ...scripts, ...images.moves, ...pages.moves, ...rootScan.moves];
  const unrecognized = [...css.unrecognized, ...pages.unrecognized, ...rootScan.unrecognized];

  return { moves, unrecognized, ...(images.assetPathRewrites.length > 0 ? { assetPathRewrites: images.assetPathRewrites } : {}) };
}

/**
 * Dispatch to the tier-specific planner. Throws for a tier with no planner yet — a loud, immediate
 * failure (never a silent no-op plan) for a theme this migration slice hasn't reached.
 */
export function planV2Migration(required: { themeDir: string; tier: ThemeTier }): ThemeMigrationPlan {
  const { themeDir, tier } = required;
  if (tier === "declarative" || tier === "templated" || tier === "handlebars") {
    return planNonStaticTierMigration(themeDir, tier);
  }
  if (tier === "static") {
    return planStaticTierMigration(themeDir);
  }
  throw new Error(`planV2Migration: no v2 migration plan implemented yet for tier '${tier}'`);
}

import { readFileSync } from "node:fs";
import path from "node:path";
import { resolveProductRoot } from "../../platform/site-dir/product-root.js";
import { createPublicPageSecurityHeaderSet, type PublicThemeResources, type SecurityHeaderSet } from "../../contracts/core/public-page-security-headers.js";

/**
 * Read the shipped theme resource data through a text-reader port. Site themes cannot silently
 * override the shared public-page policy. Missing/invalid product data throws rather than weakening it.
 * @param required Product-owned resource file, included with content/themes in every payload.
 * @param optional Text reader for isolated contract tests.
 * @returns Parsed theme resource declarations; no plugin activation or executable code.
 * @complexity O(b) resource-file bytes; one synchronous read.
 */
export function readPublicThemeResources(required: { resourceFile: string }, optional: {
  readText?: (file: string) => string;
} = {}): PublicThemeResources {
  const readText = optional.readText ?? ((file: string) => readFileSync(file, "utf8"));
  return JSON.parse(readText(required.resourceFile));
}

let resources: PublicThemeResources | undefined;
let headers: SecurityHeaderSet | undefined;

/** Load product-owned resource data on first use, then reuse it. Read/parse failures propagate
 * at use rather than import and are not cached. @complexity O(b) file bytes once, then O(1). */
export function publicThemeResources(_required: Record<string, never>, _optional: Record<string, never> = {}): PublicThemeResources {
  return resources ??= readPublicThemeResources({
    resourceFile: path.join(resolveProductRoot(), "content", "themes", "public-resources.json"),
  });
}

/** Reuse the frozen report-only header set after first use; resource errors propagate.
 * @complexity O(r) declared resource URLs once, then O(1). */
export function publicPageSecurityHeaders(_required: Record<string, never>, _optional: Record<string, never> = {}): SecurityHeaderSet {
  return headers ??= createPublicPageSecurityHeaderSet({ resources: publicThemeResources({}) });
}

import { createHash } from "node:crypto";
import { constants as fsConstants, type Dirent, type Stats } from "node:fs";
import { chmod, lstat, mkdir, open, readFile, readdir, realpath, rename, rm, rmdir, stat } from "node:fs/promises";
import path from "node:path";

import { executeCommand } from "@jini-ai/cms/core";

import { computeBlobStorageKey, isDocumentOnlyBlob } from "#src/features/media/index";
import { PublishContentApplyRowError } from "#src/features/publish-content/apply-errors";
import { contentHash, CONTENT_HASH_VERSION } from "#src/features/publish-content/content-hash";
import {
  checkTreeFiles,
  checkTreePath,
  isIgnoredTreeFileName,
  MAX_SECRET_SCAN_BYTES,
  normalizeMode,
  resolveTreeRelativePath,
  wrapTreePolicyReason,
  type FileTreeFileInput,
} from "#src/features/publish-content/file-tree-policy";
import type { FileBlobIndexPort } from "#src/features/publish-content/file-blob-index";
import type {
  PackedEntity,
  PublishContentContributor,
  PublishContentDeps,
  PublishContentHandler,
  SkippedPackEntity,
} from "#src/features/publish-content/type-registry";

import { MIGRATION_STAGING_DIR_PREFIX, PUBLISH_PREVIOUS_DIR, PUBLISH_STAGING_DIR, THEME_CATALOG_DIR } from "./theme.js";
import { isGeneratedThemePath } from "./theme-files.js";

/**
 * @file `publish-files-plan-2026-09-24.md` §6 S-F3/S-F4 — `theme-files`'s publish-content
 * contribution: the SOURCE half (`pack()`) and the DESTINATION half (`inspect`, `seedHash`,
 * `precheck`, and `apply`'s stage/verify/swap under the themes root's `.publish-staging`).
 * Mirrors `features/media/publish-content.ts`/`features/redirects/publish-content.ts` exactly: a DATA
 * export (`{entityType, dependsOn, build}`) that imports only `type-registry.ts`'s TYPES, never
 * `registerPublishContentContributor` itself — see `type-registry.ts`'s own header for why a value
 * edge here would reopen a real module cycle.
 *
 * `dependsOn` is empty — no other publish-content type depends on a theme's own file tree, and a
 * theme depends on nothing else either.
 *
 * ## What "the tree" means here, and where each exclusion actually lives
 *
 * A theme tree is `<themesDir>/<tier>/<id>/**` for `tier` in {@link THEME_FILE_TREE_TIERS} — a
 * deliberate narrowing to 3 of `theme.ts`'s 4 `ENGINE_SUBFOLDERS` (never `handlebars`, per the plan's
 * own inventory table; flagged, not silently overridden, by the S17 handoff this file continues from).
 * `__original-themes__`/a bare root `README.md` never need an explicit exclusion
 * here at all: the catalog dir and the themes-root `README.md` are SIBLINGS of `static/`/
 * `templated/`/`declarative/` (`theme.ts`'s own `discoverAllBuiltInThemes` scans them at the themes
 * ROOT, separately from each engine subfolder) — walking `themesDir/<tier>/*` for theme ids never
 * reaches any of them. What DOES land inside a tier folder is `MIGRATION_STAGING_DIR_PREFIX` scratch
 * output (a migration's staging dir is a SIBLING of the real theme folder it is migrating, i.e. inside
 * the same tier) — {@link discoverThemeTreeDirs} skips it by the same prefix `discoverThemes` itself
 * checks. Generated build output INSIDE a real theme's own tree (`preview/**`, root `index.html`) is
 * excluded per-file by {@link isGeneratedThemePath} while walking that one tree.
 *
 * ## Why a blocked tree is reported once, for the whole tree, not per file
 *
 * `checkTreeFiles` (`file-tree-policy.ts`) already returns one reason for the first offending file in
 * a tree — see that module's own header for why a tree is never silently trimmed. This file just
 * prefixes that reason with `"<title> was not published: "`, the exact prefixing S17's handoff flagged
 * as this slice's job (`file-tree-policy.ts`'s own header deliberately leaves the title out).
 *
 * ## `packThemeFilesEntities` is exported in its own right
 *
 * `PublishContentHandler.pack()` is a bare `AsyncIterable<PackedEntity>` with no channel to report a
 * blocked tree — {@link pack} below silently does not yield one. A caller (today, only this module's
 * own test) that needs to see WHY a tree did not travel calls {@link packThemeFilesEntities} directly,
 * which is the one real implementation `pack()` is a thin wrapper over.
 */

/** No other type depends on a theme's own files, and a theme depends on nothing else. */
const THEME_FILES_DEPENDS_ON: readonly string[] = [];

/** §1's inventory table, narrowed to 3 of `theme.ts`'s 4 `ENGINE_SUBFOLDERS` — see this file's own
 *  header for the deliberate `handlebars` omission. */
const THEME_FILE_TREE_TIERS: readonly string[] = ["static", "templated", "declarative"];

/** One theme tree {@link discoverThemeTreeDirs} found on disk, not yet packed. */
interface ThemeTreeLocation {
  readonly tier: string;
  readonly id: string;
  readonly absDir: string;
}

/** @complexity O(1). */
function isMissing(err: unknown): boolean {
  return typeof err === "object" && err !== null && (err as { code?: unknown }).code === "ENOENT";
}

/** `readdir` with file types, or `[]` when the folder does not exist; any other error propagates.
 * @complexity O(entries). */
async function readDirIfPresent({ absDir }: { absDir: string }): Promise<Dirent[]> {
  try {
    return await readdir(absDir, { withFileTypes: true });
  } catch (err) {
    if (isMissing(err)) return [];
    throw err;
  }
}

/** `lstat`, or `null` when nothing is there; any other error propagates. @complexity O(1). */
async function lstatIfPresent({ absPath }: { absPath: string }): Promise<Stats | null> {
  try {
    return await lstat(absPath);
  } catch (err) {
    if (isMissing(err)) return null;
    throw err;
  }
}

/** `realpath`, or `null` when nothing is there; any other error propagates. @complexity O(path depth). */
async function realpathIfPresent({ absPath }: { absPath: string }): Promise<string | null> {
  try {
    return await realpath(absPath);
  } catch (err) {
    if (isMissing(err)) return null;
    throw err;
  }
}

/** Ascending code-unit (or numeric) order as a sort comparator: -1, 0 or 1. Positional because
 *  `Array.prototype.sort` dictates the signature. @complexity O(1) per comparison. */
function compareAscending<T extends string | bigint>(a: T, b: T): number {
  return Number(a > b) - Number(a < b);
}

/** A tier-folder entry that is a theme tree: a real directory that is not migration scratch output. */
function isThemeTreeEntry({ entry }: { entry: Dirent }): boolean {
  return !entry.name.startsWith(MIGRATION_STAGING_DIR_PREFIX) && entry.isDirectory();
}

/** Tier first, then id, both by locale. */
function compareTreeLocations(a: ThemeTreeLocation, b: ThemeTreeLocation): number {
  return a.tier === b.tier ? a.id.localeCompare(b.id) : a.tier.localeCompare(b.tier);
}

/**
 * Every theme tree currently on disk under {@link THEME_FILE_TREE_TIERS} — directory NAMES only, no
 * manifest is loaded and no theme.json is parsed here (that happens implicitly: `theme.json` is just
 * another file {@link walkThemeTree} packs). A missing tier folder is treated as empty, mirroring
 * `discoverThemes`'s own "missing dir -> no themes there yet" convention.
 *
 * @complexity O(entries under each tier folder), 3 `readdir` calls.
 */
async function discoverThemeTreeDirs(themesDir: string): Promise<readonly ThemeTreeLocation[]> {
  const found: ThemeTreeLocation[] = [];
  for (const tier of THEME_FILE_TREE_TIERS) {
    const tierDir = path.join(themesDir, tier);
    for (const entry of await readDirIfPresent({ absDir: tierDir })) {
      if (isThemeTreeEntry({ entry })) found.push({ tier, id: entry.name, absDir: path.join(tierDir, entry.name) });
    }
  }
  return found.sort(compareTreeLocations);
}

/** One real file {@link walkThemeTree} found and read. `textSample` is the whole file decoded as
 *  UTF-8 when it is small enough to be worth scanning ({@link MAX_SECRET_SCAN_BYTES}) — `checkTreeFiles`
 *  itself decides, per extension, whether to actually scan it; handing every small file's text through
 *  unconditionally is harmless for a binary one (its extension is simply never in that check's
 *  text-like set) and avoids this walker having to duplicate that set. */
interface WalkedThemeFile {
  readonly path: string;
  readonly size: number;
  readonly mode: number;
  readonly sha256: string;
  readonly absPath: string;
  readonly textSample?: string;
}

/** @complexity O(1). */
function childRelPath({ relDir, name }: { relDir: string; name: string }): string {
  return relDir.length > 0 ? `${relDir}/${name}` : name;
}

/** What {@link walkThemeTree} does with one directory entry: skip it, descend into it, or read it. */
function walkStep({ entry, relPath }: { entry: Dirent; relPath: string }): "skip" | "descend" | "read" {
  if (entry.isSymbolicLink()) return "skip"; // never followed, never part of the tree.
  // OS junk (macOS's `.DS_Store`, `.Spotlight-V100`, `.Trashes`, AppleDouble `._*`; Windows'
  // `Thumbs.db`/`desktop.ini`) is excluded HERE, at the source of the file list every downstream
  // consumer (state, upload, contentHash, `inspect()`'s live re-hash) builds from — never a
  // whole-tree DENY (`file-tree-policy.ts`'s own header on `isIgnoredTreeFileName`).
  if (isIgnoredTreeFileName(entry.name)) return "skip";
  if (entry.isDirectory()) return "descend";
  if (!entry.isFile()) return "skip"; // a socket, fifo, or other non-regular entry — never a theme file.
  if (isGeneratedThemePath(relPath)) return "skip"; // regenerated on every build; never real source.
  return "read";
}

/** Reads and hashes one walked file, or `null` when it is no longer a regular file.
 * @complexity O(file bytes). */
async function readWalkedFile({ absPath, relPath }: { absPath: string; relPath: string }): Promise<WalkedThemeFile | null> {
  const info = await lstat(absPath);
  if (info.isSymbolicLink() || !info.isFile()) return null; // defends a TOCTOU swap between readdir and here.
  const bytes = await readFile(absPath);
  return {
    path: relPath,
    size: bytes.length,
    mode: normalizeMode(info.mode),
    sha256: sha256Of(bytes),
    absPath,
    textSample: bytes.length <= MAX_SECRET_SCAN_BYTES ? bytes.toString("utf8") : undefined,
  };
}

/**
 * Recursively collects every real, publishable-candidate file under one theme tree. Symlinks (to a
 * file or a directory) are never followed and never appear in the result — silently, the same "not
 * part of the tree at all" treatment {@link isGeneratedThemePath} paths get, since neither is a
 * anomaly worth a per-file report (contrast a DENY-LISTED file, which `checkTreeFiles` blocks the
 * WHOLE tree for — see this file's header). A generated path is excluded the same way, per-file,
 * before it is ever read.
 *
 * @complexity O(entries under `absTreeDir`) filesystem calls plus O(bytes) to hash/read each
 *   surviving file; recursion depth is the tree's own folder depth.
 */
async function walkThemeTree(absTreeDir: string): Promise<readonly WalkedThemeFile[]> {
  const files: WalkedThemeFile[] = [];

  async function recurse(absDir: string, relDir: string): Promise<void> {
    for (const entry of await readDirIfPresent({ absDir })) {
      const absPath = path.join(absDir, entry.name);
      const relPath = childRelPath({ relDir, name: entry.name });
      const step = walkStep({ entry, relPath });
      if (step === "descend") await recurse(absPath, relPath);
      if (step !== "read") continue;
      const file = await readWalkedFile({ absPath, relPath });
      if (file) files.push(file);
    }
  }

  await recurse(absTreeDir, "");
  return files;
}

/** One tree {@link packOneThemeTree} could not pack — the WHOLE tree, never a per-file entry (this
 *  file's own header). */
export interface SkippedThemeTree {
  readonly treeKey: string;
  readonly reason: string;
  /** The tree's `theme.json` name, when it has one — see {@link themeDisplayName}. */
  readonly label?: string;
}

/** @complexity O(1). */
function treeTitle(treeKey: string): string {
  return `Theme: ${treeKey}`;
}

/**
 * The walked tree's `theme.json` `name` (what the Themes screen calls it), or `undefined` when it has
 * no readable one. Row display text only: {@link buildTreeState} keeps {@link treeTitle} in `state`,
 * so a name change never changes a tree's hash (or disagrees with a live build that predates this).
 *
 * @complexity O(files) to find `theme.json`, plus O(its bytes) to read and parse it.
 */
async function themeDisplayName(walked: readonly WalkedThemeFile[]): Promise<string | undefined> {
  const manifest = walked.find((file) => file.path === "theme.json");
  if (!manifest) return undefined;
  try {
    const parsed: unknown = JSON.parse(manifest.textSample ?? (await readFile(manifest.absPath, "utf8")));
    const name = typeof parsed === "object" && parsed !== null ? (parsed as { name?: unknown }).name : undefined;
    return typeof name === "string" && name.trim().length > 0 ? name.trim() : undefined;
  } catch {
    return undefined; // a malformed theme.json is the policy pass's and the theme loader's concern, not a label's.
  }
}

/** @complexity O(n log n) in `files.length`. */
function sortByPath<T extends { readonly path: string }>(files: readonly T[]): T[] {
  return [...files].sort((a, b) => compareAscending(a.path, b.path));
}

/**
 * The one `state` shape both sides hash (plan §0): the source's `pack()` and the destination's
 * `inspect()`/`seedHash()`/staged-tree check. One builder, so a tree that is byte-identical on both
 * machines always hashes identically. `files` must already be sorted by path.
 *
 * @complexity O(files).
 */
function buildTreeState(
  treeKey: string,
  sortedFiles: readonly { readonly path: string; readonly sha256: string; readonly size: number; readonly mode: number }[]
): Record<string, unknown> {
  const files = sortedFiles.map((file) => ({ path: file.path, sha256: file.sha256, size: file.size, mode: file.mode }));
  return { title: treeTitle(treeKey), kind: "theme-files", treeKey, files };
}

/**
 * Packs ONE theme tree into a {@link PackedEntity}, or reports why it was left out — the per-tree unit
 * both {@link packThemeFilesEntities} and (indirectly, via that function) `pack()` build on.
 *
 * Order matches `file-tree-policy.ts` §2: the tree's id shape is checked first (this module's own
 * concern — {@link resolveTreeRelativePath} is the same validator every other file-tree kind shares),
 * then {@link checkTreeFiles} runs the full allow-list/deny-list/cap/secret-scan pass over every file
 * the walk found. Only once both pass does this record entries into `fileBlobIndex` — a blocked tree's
 * files are never indexed, so a rejected tree can never be served to a peer by sha alone.
 *
 * @complexity O(files under the tree) — one walk, one policy pass, one sort, one hash.
 */
async function packOneThemeTree(input: {
  readonly tier: string;
  readonly id: string;
  readonly absDir: string;
  readonly fileBlobIndex?: FileBlobIndexPort;
}): Promise<{ entity: PackedEntity } | { skippedTree: SkippedThemeTree }> {
  const treeKey = `${input.tier}/${input.id}`;
  const title = treeTitle(treeKey);

  if (resolveTreeRelativePath("theme-files", [input.tier, input.id]) === null) {
    return { skippedTree: { treeKey, reason: `${title} was not published: '${treeKey}' is not a valid theme tree address` } };
  }

  const walked = await walkThemeTree(input.absDir);
  const label = await themeDisplayName(walked);
  const policyInputs: FileTreeFileInput[] = walked.map((file) => ({
    path: file.path,
    size: file.size,
    mode: file.mode,
    textSample: file.textSample,
  }));
  const blockReason = checkTreeFiles("theme-files", policyInputs);
  if (blockReason) {
    return { skippedTree: { treeKey, reason: wrapTreePolicyReason(title, blockReason), ...(label ? { label } : {}) } };
  }

  const sortedFiles = sortByPath(walked);
  const state = buildTreeState(treeKey, sortedFiles);

  for (const file of sortedFiles) {
    input.fileBlobIndex?.set(file.sha256, { absPath: file.absPath, size: file.size });
  }

  return {
    entity: {
      entityType: "theme-files",
      id: treeKey,
      schemaVersion: 1,
      contentHash: contentHash("theme-files", state),
      hashVersion: CONTENT_HASH_VERSION,
      requiredBlobs: sortedFiles.map((file) => file.sha256),
      state,
      ...(label ? { displayLabel: label } : {}),
    },
  };
}

/**
 * Every theme tree on this machine, packed or reported as skipped — the one real implementation
 * `pack()` below wraps. Exported so a caller (today, this module's own test) can see WHY a tree did
 * not travel, a channel `PublishContentHandler.pack()`'s bare `AsyncIterable` has no room for (this
 * file's own header).
 *
 * @complexity O(trees) sequential `packOneThemeTree` calls (each already documented above).
 */
export async function packThemeFilesEntities(input: {
  readonly themesDir: string;
  readonly fileBlobIndex?: FileBlobIndexPort;
}): Promise<{ entities: readonly PackedEntity[]; skipped: readonly SkippedThemeTree[] }> {
  const trees = await discoverThemeTreeDirs(input.themesDir);
  const entities: PackedEntity[] = [];
  const skipped: SkippedThemeTree[] = [];
  for (const tree of trees) {
    const result = await packOneThemeTree({ tier: tree.tier, id: tree.id, absDir: tree.absDir, fileBlobIndex: input.fileBlobIndex });
    if ("entity" in result) entities.push(result.entity);
    else skipped.push(result.skippedTree);
  }
  return { entities, skipped };
}

// ---------------------------------------------------------------------------
// Destination half (S-F4): inspect, seedHash, precheck, apply
// ---------------------------------------------------------------------------

/** Plan §3 step 2's one link/escape refusal, shared by `precheck()` and `apply()`. */
const LINK_REASON = "live's themes folder contains a link; nothing was written";

/** Plan §3 step 6. */
const KEEP_PREVIOUS_COPIES = 2;

/** One entity id (`"<tier>/<themeId>"`) split and validated, or `null` for anything else. */
interface ThemeTreeAddress {
  readonly tier: string;
  readonly themeId: string;
  readonly treeKey: string;
}

/**
 * Parses an entity id through the same `resolveTreeRelativePath` validator `pack()` used, so an id
 * the source could never have produced (`../x`, a 3-segment path, the `handlebars` tier) never
 * resolves to a directory here.
 *
 * @complexity O(id length).
 */
function parseTreeAddress(id: string): ThemeTreeAddress | null {
  const segments = id.split("/");
  if (segments.length !== 2) return null;
  const [tier, themeId] = segments;
  if (!THEME_FILE_TREE_TIERS.includes(tier)) return null;
  if (resolveTreeRelativePath("theme-files", [tier, themeId]) === null) return null;
  return { tier, themeId, treeKey: id };
}

/**
 * The `contentHash` of the tree at `absDir`, built exactly like `pack()` builds it, or `null` when
 * there is no real directory there. A symlinked tree root is treated as absent (never followed);
 * `precheck()` is what refuses it with a reason.
 *
 * @complexity O(files under `absDir`) reads + hashes.
 */
async function hashTreeAt(absDir: string, treeKey: string): Promise<string | null> {
  const info = await lstatIfPresent({ absPath: absDir });
  if (!info?.isDirectory()) return null;
  const walked = await walkThemeTree(absDir);
  return contentHash("theme-files", buildTreeState(treeKey, sortByPath(walked)));
}

/**
 * Plan §3 step 2: `realpath(root) === root`, and every existing component from the root down to the
 * target (plus publish's own scratch dirs) is a real directory, never a link. Also refuses a tier
 * folder on a different device than the root, since the swap's renames must stay on one filesystem
 * (no `EXDEV` half-swap). A missing root or component is fine — apply creates it.
 *
 * @complexity O(1) — at most 5 `lstat`/`stat` calls.
 */
async function checkDestinationLinks(themesDir: string, address: ThemeTreeAddress): Promise<string | null> {
  const rootReal = await realpathIfPresent({ absPath: themesDir });
  if (rootReal === null) return null;
  if (rootReal !== path.resolve(themesDir)) return LINK_REASON;
  const rootDev = (await stat(themesDir)).dev;
  const components = [
    path.join(themesDir, address.tier),
    path.join(themesDir, address.tier, address.themeId),
    path.join(themesDir, PUBLISH_STAGING_DIR),
    path.join(themesDir, PUBLISH_PREVIOUS_DIR),
  ];
  for (const component of components) {
    const reason = componentLinkReason({ info: await lstatIfPresent({ absPath: component }), rootDev });
    if (reason) return reason;
  }
  return null;
}

/** One destination path component's refusal, or `null` when it is absent or a same-device real folder. */
function componentLinkReason({ info, rootDev }: { info: Stats | null; rootDev: number }): string | null {
  if (!info) return null;
  if (info.isSymbolicLink() || !info.isDirectory()) return LINK_REASON;
  if (info.dev !== rootDev) return "live's themes folder spans two disks; nothing was written";
  return null;
}

/** One `state.files[]` entry after shape validation. */
interface IncomingThemeFile {
  readonly path: string;
  readonly sha256: string;
  readonly size: number;
  readonly mode: number;
}

/**
 * Validates an incoming entity's `state` shape — the destination never trusts the source (plan §3
 * step 1). Returns the files, or a reason (without the title prefix).
 *
 * @complexity O(files).
 */
function readIncomingFiles(entity: PackedEntity): { files: readonly IncomingThemeFile[] } | { reason: string } {
  const notDescribed = { reason: `its file list does not describe '${entity.id}'` };
  const { state } = entity;
  if (state.kind !== "theme-files" || state.treeKey !== entity.id || !Array.isArray(state.files)) return notDescribed;
  const raws = state.files as unknown[];
  if (!raws.every(isIncomingFileShape)) return notDescribed;
  return { files: raws.map((file) => ({ path: file.path, sha256: file.sha256, size: file.size, mode: normalizeMode(file.mode) })) };
}

/** One raw `state.files[]` entry has the {@link IncomingThemeFile} shape (mode not yet normalized). */
function isIncomingFileShape(raw: unknown): raw is IncomingThemeFile {
  const file = raw as Partial<IncomingThemeFile> | null;
  return (
    Boolean(file) &&
    typeof file!.path === "string" &&
    typeof file!.sha256 === "string" &&
    /^[0-9a-f]{64}$/.test(file!.sha256) &&
    typeof file!.size === "number" &&
    typeof file!.mode === "number"
  );
}

/** True when this site cannot vouch that `sha256` is not a library document: no media port wired,
 *  or media's own ownership policy says the blob is document-only.
 * @complexity O(workspace media rows), plus one indexed asset lookup. */
async function isBlockedLibraryBlob({ deps, sha256 }: { deps: PublishContentDeps; sha256: string }): Promise<boolean> {
  const media = deps.ports.media;
  return !media || isDocumentOnlyBlob({ deps: { mediaRepo: media.repo, blobRepo: media.assetBlobRepo },
    input: { workspaceId: deps.workspaceId, sha256 } });
}

/** Reads one staged blob, or `null` when this destination never received it.
 * Ownership is rechecked on each read because it can change after precheck.
 * @complexity O(workspace media rows + blob bytes), plus one indexed asset lookup. */
async function readBlob({ deps, sha256 }: { deps: PublishContentDeps; sha256: string },
  _optional: Record<string, never> = {}): Promise<Uint8Array | null> {
  // All readers share media's policy, including the authoritative read just before staging.
  if (await isBlockedLibraryBlob({ deps, sha256 })) {
    throw new PublishContentApplyRowError("blocked", "Library documents cannot be published");
  }
  const { blobStore } = deps.ports.media!;
  const workspaceId = deps.workspaceId;
  const storageKey = computeBlobStorageKey({ workspaceId, sha256 });
  if (!(await blobStore.exists({ storageKey }))) return null;
  return blobStore.get({ storageKey });
}

/** @complexity O(bytes). */
function sha256Of(bytes: Uint8Array): string {
  return createHash("sha256").update(bytes).digest("hex");
}

/**
 * Removes every previous copy of `address` beyond the newest {@link KEEP_PREVIOUS_COPIES}, newest by
 * the key folder's own mtime (ns). Housekeeping only: it runs after the swap has landed, so a failure
 * here must never fail the publish — it leaves an extra copy on disk, nothing worse.
 *
 * @complexity O(previous key folders) `stat` calls.
 */
async function prunePreviousCopies(themesDir: string, address: ThemeTreeAddress): Promise<void> {
  const previousRoot = path.join(themesDir, PUBLISH_PREVIOUS_DIR);
  try {
    const copies: { keyDir: string; mtimeNs: bigint }[] = [];
    for (const key of await readdir(previousRoot)) {
      const keyDir = path.join(previousRoot, key);
      try {
        await lstat(path.join(keyDir, address.tier, address.themeId));
      } catch {
        continue;
      }
      copies.push({ keyDir, mtimeNs: (await stat(keyDir, { bigint: true })).mtimeNs });
    }
    copies.sort((a, b) => compareAscending(b.mtimeNs, a.mtimeNs)); // newest first.
    for (const { keyDir } of copies.slice(KEEP_PREVIOUS_COPIES)) {
      await rm(path.join(keyDir, address.tier, address.themeId), { recursive: true, force: true });
      for (const emptied of [path.join(keyDir, address.tier), keyDir]) {
        await rmdir(emptied).catch(() => undefined); // still holds another tree's copy — keep it.
      }
    }
  } catch {
    // See this function's doc: never fail a landed publish over housekeeping.
  }
}

/**
 * {@link precheck}'s policy inputs for every incoming file, or the library-document refusal.
 * @complexity O(files) ownership checks plus O(bytes) for the text files small enough to scan.
 */
async function incomingPolicyInputs({ deps, files }: { deps: PublishContentDeps; files: readonly IncomingThemeFile[] }):
  Promise<{ inputs: FileTreeFileInput[] } | { reason: string }> {
  const inputs: FileTreeFileInput[] = [];
  for (const file of files) {
    // Check even files too large for the secret scan, before staging creates any files.
    if (await isBlockedLibraryBlob({ deps, sha256: file.sha256 })) return { reason: "Library documents cannot be published" };
    inputs.push({ path: file.path, size: file.size, mode: file.mode, textSample: await incomingTextSample({ deps, file }) });
  }
  return { inputs };
}

/**
 * The bytes that actually arrived for one small, policy-clean path, decoded for the secret scan, or
 * `undefined` (too large, a refused path, or a blob not here yet — the planner's `hasBlob` leg).
 * Reads through `ports.media`'s blob store — the SAME ADR-027 instance a composition root threads to
 * both (see the comment above `buildHandler`'s `themePort`). `theme-files` has no blob store of its
 * own; media's ownership policy must be wired before any bytes can be read.
 * @complexity O(blob bytes).
 */
async function incomingTextSample({ deps, file }: { deps: PublishContentDeps; file: IncomingThemeFile }): Promise<string | undefined> {
  if (file.size > MAX_SECRET_SCAN_BYTES || checkTreePath(file.path) !== null) return undefined;
  const bytes = await readBlob({ deps, sha256: file.sha256 });
  return bytes && bytes.length <= MAX_SECRET_SCAN_BYTES ? Buffer.from(bytes).toString("utf8") : undefined;
}

/** `apply()`'s gateway wiring, or the error naming what to wire. @complexity O(1). */
function requireApplyWiring({ deps }: { deps: PublishContentDeps }) {
  const { changeSets, authorize, outbox } = deps;
  const themesDir = deps.ports["theme-files"]?.themesDir;
  if (!changeSets || !authorize || !outbox || !deps.ports.media?.blobStore || !themesDir) {
    throw new Error(
      "publish-content: theme-files.apply() requires PublishContentDeps.changeSets/authorize/outbox, " +
        "ports.media.blobStore and ports['theme-files'].themesDir — wire them from the real " +
        "apply-loop composition root (features/publish-content/apply-loop.ts)."
    );
  }
  return { changeSets, authorize, outbox, themesDir };
}

/** Where the live tree and its kept previous copy live; empty for an invalid address, which
 *  `apply()`'s precheck refuses before either path is used. @complexity O(1). */
function swapPaths({ themesDir, address, keyHash }: { themesDir: string; address: ThemeTreeAddress | null; keyHash: string }) {
  if (!address) return { target: "", previousPath: "" };
  return {
    target: path.join(themesDir, address.tier, address.themeId),
    previousPath: path.join(themesDir, PUBLISH_PREVIOUS_DIR, keyHash, address.tier, address.themeId),
  };
}

function buildHandler(deps: PublishContentDeps): PublishContentHandler {
  const entityType = "theme-files";
  const schemaVersion = 1;
  // F2 — `theme-files`' own port. `blobStore` is deliberately NOT part of it: it reuses the SAME
  // ADR-027 store instance `ports.media` carries (one composition-root singleton, threaded to both).
  const themePort = deps.ports["theme-files"];

  async function* pack(): AsyncIterable<PackedEntity> {
    // Absent the port degrades to "nothing to export" — the same convention every other optional
    // port already follows (`type-registry.ts`'s own header on `PublishContentPorts`).
    if (!themePort) return;
    const { entities } = await packThemeFilesEntities({ themesDir: themePort.themesDir, fileBlobIndex: themePort.fileBlobIndex });
    for (const entity of entities) yield entity;
  }

  /**
   * `type-registry.ts`'s `PublishContentHandler.listSkipped` — every theme tree this machine found
   * but refused to pack, for an export envelope to surface as a non-selectable, reason-carrying row.
   *
   * Re-walks every theme tree via {@link packThemeFilesEntities} rather than sharing a single pass
   * with {@link pack}: `pack()` is a bare `AsyncIterable` with no room to also report a skip (this
   * file's own header), and `PublishContentHandler` gives no caller a way to ask for both from one
   * call. The extra walk costs one more `readFile`+`sha256` pass over every already-packed file,
   * which is bounded by this machine's own theme corpus (never remote, never per-request-multiplied)
   * — accepted here rather than restructuring `pack()`'s contract for every other handler to satisfy.
   *
   * @complexity O(trees) — see {@link packThemeFilesEntities}'s own doc.
   */
  async function listSkipped(): Promise<readonly SkippedPackEntity[]> {
    if (!themePort) return [];
    const { skipped } = await packThemeFilesEntities({ themesDir: themePort.themesDir });
    return skipped.map((tree) => ({ entityType, id: tree.treeKey, label: tree.label ?? treeTitle(tree.treeKey), reason: tree.reason }));
  }

  /** The destination's tree, hashed like `pack()` hashes it. `version` is always 0 (plan §3): the
   *  apply loop re-inspects and compares hashes before every write. */
  async function inspect(id: string): Promise<{ version: number; hash: string } | null> {
    const address = parseTreeAddress(id);
    if (!themePort || !address) return null;
    const hash = await hashTreeAt(path.join(themePort.themesDir, address.tier, address.themeId), address.treeKey);
    return hash === null ? null : { version: 0, hash };
  }

  /** What this destination was seeded with: its own `__original-themes__/<tier>/<id>` copy (plan §4). */
  async function seedHash(id: string): Promise<string | null> {
    const address = parseTreeAddress(id);
    if (!themePort || !address) return null;
    return hashTreeAt(path.join(themePort.themesDir, THEME_CATALOG_DIR, address.tier, address.themeId), address.treeKey);
  }

  /**
   * Plan §3 steps 1-2, read-only: the state's shape, the link check, then the whole
   * `file-tree-policy` pass again — including the secret scan, over the bytes that actually arrived
   * in this site's blob store (a blob not here yet is left to the planner's `hasBlob` leg).
   *
   * @complexity O(files) plus O(bytes) for the text files small enough to scan.
   */
  async function precheck(entity: PackedEntity): Promise<string | null> {
    const checked = await precheckIncoming(entity);
    return "reason" in checked ? checked.reason : null;
  }

  /** {@link precheck}'s whole pass, returning the validated files on success so `apply()` stages
   *  exactly what was checked. */
  async function precheckIncoming(entity: PackedEntity): Promise<{ reason: string } | { files: readonly IncomingThemeFile[] }> {
    const title = treeTitle(entity.id);
    const address = parseTreeAddress(entity.id);
    if (!address) return { reason: `${title} was not published: '${entity.id}' is not a valid theme tree address` };
    if (!themePort) return { reason: `${title} was not published: this site has no themes folder` };
    const incoming = readIncomingFiles(entity);
    if ("reason" in incoming) return { reason: `${title} was not published: ${incoming.reason}` };

    const linkReason = await checkDestinationLinks(themePort.themesDir, address);
    if (linkReason) return { reason: linkReason };

    const policy = await incomingPolicyInputs({ deps, files: incoming.files });
    if ("reason" in policy) return policy;
    const policyReason = checkTreeFiles("theme-files", policy.inputs);
    return policyReason ? { reason: wrapTreePolicyReason(title, policyReason) } : incoming;
  }

  /**
   * Plan §3 steps 3-6, inside `executeCommand` (permission `theme.set`): stage every file into
   * `<themesDir>/.publish-staging/<keyHash>/` (`O_CREAT|O_EXCL|O_NOFOLLOW`, normalized mode, sha
   * re-verified), hash the staged tree against `entity.contentHash`, then swap with two renames —
   * the old tree to `<themesDir>/.publish-previous/<keyHash>/<tier>/<id>`, the staged tree into
   * place. Staging and previous copies live under the SAME themes root as the target, so both
   * renames stay on one filesystem. Any failure before the swap removes the staging folder and
   * leaves the old tree serving; `rollback` (a change-set record failing after the swap) moves the
   * old tree back.
   *
   * @complexity O(files) blob reads + writes, one staged-tree hash pass, O(previous copies) pruning.
   */
  async function apply(input: {
    entity: PackedEntity;
    expectedVersion: number | undefined;
    principalId: string;
    idempotencyKey: string;
  }): Promise<{ changeSetId: string }> {
    const { changeSets, authorize, outbox, themesDir } = requireApplyWiring({ deps });
    const { entity } = input;
    const title = treeTitle(entity.id);
    const address = parseTreeAddress(entity.id);
    const keyHash = createHash("sha256").update(input.idempotencyKey).digest("hex").slice(0, 32);
    const stagingRoot = path.join(themesDir, PUBLISH_STAGING_DIR);
    const stagingDir = path.join(stagingRoot, keyHash);
    const { target, previousPath } = swapPaths({ themesDir, address, keyHash });
    let swapped: { previous: string | null } | null = null;

    const blocked = (reason: string): never => {
      throw new PublishContentApplyRowError("blocked", reason);
    };

    async function stageFiles(files: readonly IncomingThemeFile[]): Promise<void> {
      await mkdir(stagingRoot, { recursive: true });
      await rm(stagingDir, { recursive: true, force: true }); // a crashed earlier attempt under this same key.
      await mkdir(stagingDir);
      for (const file of files) {
        const bytes = await readBlob({ deps, sha256: file.sha256 });
        if (!bytes) blocked(`${title} was not published: the bytes for "${file.path}" never reached this site`);
        if (sha256Of(bytes!) !== file.sha256) blocked(`${title} was not published: the bytes for "${file.path}" do not match their checksum`);
        const abs = path.join(stagingDir, ...file.path.split("/"));
        await mkdir(path.dirname(abs), { recursive: true });
        const handle = await open(abs, fsConstants.O_CREAT | fsConstants.O_EXCL | fsConstants.O_WRONLY | fsConstants.O_NOFOLLOW, file.mode);
        try {
          await handle.writeFile(bytes!);
        } finally {
          await handle.close();
        }
        await chmod(abs, file.mode); // `open`'s mode is masked by the process umask.
      }
      if ((await hashTreeAt(stagingDir, entity.id)) !== entity.contentHash) {
        blocked(`${title} was not published: the copy written on this site does not match what was sent`);
      }
    }

    async function swapIntoPlace(): Promise<{ previous: string | null }> {
      await mkdir(path.dirname(target), { recursive: true });
      const hadTarget = (await lstatIfPresent({ absPath: target })) !== null;
      if (hadTarget) {
        await rm(previousPath, { recursive: true, force: true });
        await mkdir(path.dirname(previousPath), { recursive: true });
        await rename(target, previousPath);
      }
      try {
        await rename(stagingDir, target);
      } catch (err) {
        if (hadTarget) await rename(previousPath, target);
        throw err;
      }
      return { previous: hadTarget ? previousPath : null };
    }

    const { changeSetId } = await executeCommand({
      deps: { clock: deps.clock, idGen: deps.idGen, changeSets, outbox, authorize },
      command: {
        workspaceId: deps.workspaceId,
        actor: { id: input.principalId, kind: "user" as const },
        summary: `Publish ${title} via publish-content`,
        permission: "theme.set",
        idempotencyKey: input.idempotencyKey,
      },
      mutation: {
        entityType,
        entityId: entity.id,
        operation: input.expectedVersion === undefined ? "create" : "update",
        // The tree this publish replaces is kept on disk, not in the ledger — the inverse names where.
        captureInverse: async () => ({ treeKey: entity.id, previousPath: previousPath || null }),
        execute: async (): Promise<{ previous: string | null }> => {
          // Authoritative re-check inside the gateway, after `authorize` (same order as media).
          const incoming = await precheckIncoming(entity);
          if ("reason" in incoming) return blocked(incoming.reason);
          try {
            await stageFiles(incoming.files);
            swapped = await swapIntoPlace();
          } catch (err) {
            await rm(stagingDir, { recursive: true, force: true });
            throw err;
          }
          await prunePreviousCopies(themesDir, address!);
          // The renderer serves partials/pages from memory, not disk — re-read them now.
          await themePort?.onReplaced?.();
          return swapped;
        },
        captureEntityVersion: () => 0,
        // The gateway calls rollback only after `execute` resolved (`executeCommand` in
        // @jini-ai/cms core/commands/command.ts), and every resolving `execute` has swapped.
        rollback: async () => {
          const discard = `${stagingDir}.rollback`;
          await rename(target, discard);
          if (swapped!.previous) await rename(swapped!.previous, target);
          await rm(discard, { recursive: true, force: true });
          await themePort?.onReplaced?.();
        },
      },
    });
    return { changeSetId };
  }

  return {
    entityType,
    schemaVersion,
    // Theme content's own existing write permission (`features/theme/agent-tools.ts`,
    // `routes/themes/*`) — never a flat transport-wide permission, per
    // `PublishContentHandler.permission`'s own contract.
    permission: "theme.set",
    dependsOn: THEME_FILES_DEPENDS_ON,
    pack,
    inspect,
    precheck,
    apply,
    seedHash,
    listSkipped,
  };
}

/**
 * `theme-files`'s publish-content contribution. Called from a composition root
 * (`server/runtime/composition/publish-content-manifest.ts`), NOT from within `features/theme` itself
 * — see this file's header.
 */
export function contributeThemeFilesPublish(): PublishContentContributor {
  return { entityType: "theme-files", coversRoots: ["themes"], dependsOn: THEME_FILES_DEPENDS_ON, build: buildHandler };
}

import type { ThemeSlotDescriptor, TemplateNode } from "./theme.js";

/** @file Pure theme defaults and route selection, shared without loading filesystem validators. */
/**
 * The `nav`/`footer` pair `resolveSlots` hardcoded before {@link ThemeManifest.slots} was parsed.
 * Used verbatim when a static theme declares no `slots`, so such a theme renders exactly as it did.
 */
export const DEFAULT_THEME_SLOTS: Readonly<Record<string, ThemeSlotDescriptor>> = {
  nav: { source: "nav.html", honorsCurrentPage: true },
  footer: { source: "footer.html" },
};

/**
 * SPEC-004 REQ-03 fallthrough chain, keyed by route, trimmed to the spike's routes: `home` and
 * `products`/`product` are own-named only (no fallthrough — a theme that doesn't declare one
 * simply has no such page, REQ-10 spirit); `post` tries `post` first, then falls through to
 * `entry` (built-ins ship `entry`; `post` is an optional override a theme may add to specialize
 * posts — AC-07). One candidate list per route rather than a route-shaped if/else chain, so
 * {@link resolveRouteTemplateId} stays a single loop instead of re-deriving this same shape three
 * times (once per source-map type below).
 */
const ROUTE_TEMPLATE_CANDIDATES: Readonly<Record<"home" | "post" | "products" | "product", readonly string[]>> = {
  home: ["home"],
  post: ["post", "entry"],
  products: ["products"],
  product: ["product"],
};

/**
 * Shared REQ-03 resolution core behind `resolveTemplateId`/`resolveLiquidTemplateId`/
 * `resolveHandlebarsTemplateId` — the three differ only in which source-map type they resolve
 * against (declarative block trees, raw `.liquid` source, raw `.hbs` source), never in the
 * fallthrough logic itself, so that logic lives here once. `templates` is read generically
 * (presence/truthiness only, via `Record<string, unknown>`) because none of the three callers'
 * value types matter to this decision — only whether a given template id exists.
 */
function resolveRouteTemplateId(
  route: "home" | "post" | "products" | "product",
  templates: Readonly<Record<string, unknown>>
): string | null {
  for (const candidateId of ROUTE_TEMPLATE_CANDIDATES[route]) {
    if (templates[candidateId]) return candidateId;
  }
  return null;
}

/**
 * Resolve a page route to a template id — see {@link ROUTE_TEMPLATE_CANDIDATES} for the REQ-03
 * fallthrough chain this applies.
 * @complexity O(1) time and space — at most two candidate lookups.
 */
export function resolveTemplateId(
  required: { route: "home" | "post" | "products" | "product"; templates: Record<string, TemplateNode> },
  _optional: Record<string, never> = {}
): string | null {
  return resolveRouteTemplateId(required.route, required.templates);
}

/**
 * Templated-tier (LiquidJS) analogue of `resolveTemplateId`: same REQ-03 fallthrough over the raw
 * `.liquid` source map.
 * @complexity O(1) time and space — at most two candidate lookups.
 */
export function resolveLiquidTemplateId(
  required: { route: "home" | "post" | "products" | "product"; liquidTemplates: Record<string, string> },
  _optional: Record<string, never> = {}
): string | null {
  return resolveRouteTemplateId(required.route, required.liquidTemplates);
}

/**
 * Handlebars-tier analogue of `resolveTemplateId`: same REQ-03 fallthrough over the raw `.hbs`
 * source map.
 * @complexity O(1) time and space — at most two candidate lookups.
 */
export function resolveHandlebarsTemplateId(
  required: { route: "home" | "post" | "products" | "product"; handlebarsTemplates: Record<string, string> },
  _optional: Record<string, never> = {}
): string | null {
  return resolveRouteTemplateId(required.route, required.handlebarsTemplates);
}

