import { COLLECTION_MARKER_TYPE, FEATURED_IMAGE_MARKER_TYPE, markersOfType, MENU_MARKER_TYPE, PARTIAL_MARKER_TYPE, POST_PREVIEWS_MARKER_TYPE, substituteMarkers, withAddedId, withElementKeptIfAttributed, withInnerContent, withInnerContentFinal, type EmbedMarker } from "@jini-ai/cms/widgets/markers";
import { extractListingCardTemplate, injectListingScript, listingKeyOfAttributes, parseListingBatchSize, renderListingMore, wrapListingItems } from "@jini-ai/cms/listing";
import { injectMenuDropdownScript, renderMenuToggle } from "@jini-ai/cms/navigation/dropdown";
import { postAuthorForDisplay } from "../post/author.js";
import { renderHtmlMenu } from "#src/features/navigation/html-render";
import { escapeHtml } from "#src/platform/html/escape";
import { withEntryListStyleOnce } from "./entry-list-render.js";
import { findUnrewrittenAssetPaths, rewriteAssetPaths, tokenStylesheetSentinel } from "./static-asset-contract.js";
import type { DiscoveredTheme, ThemeSlotDescriptor, ThemeTokens } from "./theme.js";
import { DEFAULT_THEME_SLOTS } from "./render-contract.js";
import { themeTokenAliasDeclarations } from "./token-aliases.js";

/**
 * @file Real (non-spike) request-time rendering for `static`-tier themes.
 *
 * Ports the logic each static theme's own `build-preview.mjs` (an authoring-time stand-in written
 * before this file existed) already proved out over 18+ screenshots this session: token injection,
 * asset-path rewriting, and `data-tovu-slot` resolution. That script still exists per-theme for
 * local preview/iteration; this module is the one real counterpart `render.ts` calls when actually
 * serving a static theme as the live site.
 *
 * Scope of this pass: **home route only.** Posts/products routes are not handled here at all;
 * callers fall back to the existing `fallbackBody()` for those.
 */

/** Theme aliases ({@link themeTokenAliasDeclarations}) ride on the dark `:root` rule so they
 *  resolve against whichever mode's tokens are active — see `token-aliases.ts`. */
function tokensToRootCss(tokens: ThemeTokens, tokensLight: ThemeTokens): string {
  const darkEntries = [...Object.entries(tokens), ...themeTokenAliasDeclarations({ tokens, tokensLight })];
  const darkLines = darkEntries.map(([k, v]) => `  ${k}: ${v};`);
  const lightLines = Object.entries(tokensLight).map(([k, v]) => `  ${k}: ${v};`);
  return (
    `:root {\n${darkLines.join("\n")}\n}\n` +
    `:root[data-theme="light"] {\n${lightLines.join("\n")}\n}`
  );
}

/**
 * `tokenStylesheetSentinel` (formerly a bare `TOKEN_STYLESHEET_SENTINEL` import), `rewriteAssetPaths`,
 * and `findUnrewrittenAssetPaths` live in `static-asset-contract.ts` (2026-08-12, ADR-020 §5) so
 * `build-conformance.ts`'s install-time gate can import the exact same sentinel/rewrite logic this file
 * uses at request time, without creating an import cycle back through `theme.ts` (see that file's own
 * header for why). All three now take the theme's `apiVersion` to pick between the v1 (`css/styles.css`,
 * `js/`) and v2 (`css/theme.css`, `scripts/`) asset-path shape — added for the Milestone 3 theme
 * migration work; every call site already threading `theme.manifest.apiVersion` through (undefined for
 * every theme on disk today) keeps this file's own behavior byte-for-byte unchanged from before.
 */

/**
 * A static page's internal nav/footer/body links point at sibling page files (`href="pricing.html"`)
 * — correct only when viewing the raw file on disk. Rewritten generically to the real route
 * (`href="/pricing"`, `href="/"` for `index.html`) so a real click in the browser lands on the route
 * Tovu actually serves instead of a bare filename the server never registers. Hash links (`href="#..."`)
 * and the already-rewritten `../css/`/`../js/` asset paths are untouched — this only matches a bare
 * `<name>.html` href, never one containing `/`.
 */
function rewritePageLinks(html: string): string {
  return html.replace(/href="([a-z0-9-]+)\.html"/g, (_m, name: string) => (name === "index" ? 'href="/"' : `href="/${name}"`));
}

/** `true` for a marker carrying a NON-EMPTY string `slug` — an explicit reference to another entity.
 * An empty `slug` names nothing (every resolver stage treats `""` as absent, `html-embeds.ts`'s
 * `normalizeEmbedSlug`), so it must not block filling in the current entity's id. */
function hasAuthoredSlug(marker: EmbedMarker): boolean {
  const slug = marker.config.slug;
  return typeof slug === "string" && slug.length > 0;
}

/**
 * Fills the current entity's real id into every `{"type":"content"}` marker in `html` that carries NO
 * id — the unified-marker (2026-08-11) replacement for BOTH `injectPostEmbedId`'s `{{post}}` literal
 * substitution AND `injectPageContent`'s direct body-HTML splice.
 *
 * A theme-authored, id-less `{"type":"content"}` marker means "the entity the route already
 * resolved" (the unified-content-marker design doc's own wording) — the route layer (`pages.ts`)
 * knows that entity's real id by the time it calls this, so it fills it in here, BEFORE the embed
 * scanner/resolver ever sees the html. Everything downstream (the recursive `"html"`-format
 * pre-splice pass, `resolveHtmlPageEmbeds`'s registered `"content"` resolver, a later re-scan) then
 * sees an ORDINARY id-carrying marker — the same one an author gets by typing a real id directly —
 * with no "no id means current entity" special case anywhere else in the pipeline.
 *
 * A marker that ALREADY carries an id (an author's explicit reference to some OTHER entity) is left
 * completely untouched — this function only ever fills a gap, never overwrites an explicit choice.
 * The same rule applies to a marker carrying a `slug` instead of an `id` (S3, 2026-09-23 widget-attrs
 * plan): `{"type":"content","slug":"some-other-entity"}` is just as much an explicit reference to
 * some OTHER entity as an id-carrying marker is — filling in the CURRENT entity's id here would win
 * over that authored `slug` (`resolveContentTypeEmbeds`'s id-authoritative-when-present order) and
 * silently redirect the marker to the wrong row. Checking `marker.id === undefined` alone would miss
 * this — a slug-only marker also has no `id` yet, but for a completely different reason than "this
 * means the current entity".
 * The old `blog-post.html`/`page-shell.html` split (one marker type per kind) is gone: BOTH doc-format
 * Posts and Pages, and html-format Pages, use this exact same function now, since the row's
 * `bodyFormat` — not the marker's type — is what decides how the referenced content actually renders
 * (`resolveContentTypeEmbeds`, `resolver-service.ts`, and the recursive pre-splice in `pages.ts`).
 *
 * Marker-based (via {@link withAddedId}), not a literal string replace like the retired
 * `injectPostEmbedId` — that function could rely on `{{post}}` being authored as a specific literal
 * JSON value; here there is no literal token to search for (the marker's ABSENCE of an `id` key is
 * the whole signal), so filling the gap correctly for a marker carrying extra config keys (e.g. a
 * future `{"type":"content","variant":"..."}"`) needs the real parsed marker, not a substring match.
 *
 * @complexity O(n) over `html`'s length — one `substituteMarkers` scan-and-splice pass, the same cost
 * shape every other marker-substitution call in this codebase already pays.
 */
export function injectCurrentEntityContentId(html: string, entityId: string): string {
  return substituteMarkers({ html: html, resolve: (marker) => {
    if (marker.type !== "content" || marker.id !== undefined || hasAuthoredSlug(marker)) return undefined;
    return withAddedId({ marker: marker, id: entityId });
  } });
}

/**
 * Substitutes a page-template's title placeholder with the rendered row's own real title —
 * {@link injectCurrentEntityContentId}'s sibling for the `<title>` tag, a string substitution rather
 * than a marker rewrite (same convention that function documents for filling in a marker's `id`).
 *
 * Matches the WHOLE `<title>...</title>` element the placeholder sits in, not a bare token search —
 * learned the hard way while authoring `page-shell.html`: that file's own explanatory HTML comment
 * mentions the placeholder as prose, and a bare-token `.replace()` matched THAT occurrence (the first
 * one in the file) instead of the real one in `<head>`, silently leaving the `<title>` tag unfilled.
 * Scoping the match to the full element makes an incidental mention elsewhere in the template (a
 * comment, authored copy) structurally unable to collide with the real slot.
 *
 * Runs for every kind now (2026-08-11 unification; previously Post-rendered pages accepted a fixed
 * title as a disclosed limitation and only Pages got this substitution) — `basic`'s own `posts-*.html`
 * templates (`blog-post.html` before the 2026-09-03 posts-* / pages-* rename) keep one fixed `<title>`
 * string with no placeholder, so calling this on a Post rendered through one is still a no-op,
 * unchanged; a Post rendered through `pages-default.html` (`page-shell.html` before that same rename)
 * now correctly gets its own title instead of a generic one, closing that disclosed gap for free.
 *
 * A template file authored without this exact `<title>...</title>` shape is simply unaffected —
 * `replace` is a no-op when the pattern isn't present.
 *
 * @complexity O(n) over `html`'s length — one string search-and-replace.
 */
export function injectPageTitle(html: string, title: string): string {
  return html.replace(/<title>\{\{title\}\}<\/title>/, () => `<title>${escapeHtml(title)}</title>`);
}

/**
 * The minimal structural shape this module needs from a resolved menu item — matches
 * `ResolvedNavItem` (`@jini-ai/cms/navigation`, re-exported by `#src/navigation`) field-for-field on
 * every field actually used here. A local shape rather than importing that type keeps `features/theme`
 * from gaining a new import edge onto `navigation` purely for a type; the real `ResolvedNavItem[]` the
 * route layer resolves already satisfies this structurally (same convention `render.ts`'s own
 * `MediaAssetRenderMeta` uses for pre-resolved render-time data owned by a different feature).
 */
export interface StaticMenuItem {
  readonly label: string;
  readonly href: string | null;
  readonly available: boolean;
  readonly isCurrent: boolean;
  /** True when this item OR a descendant is current — what a sidebar uses to expand a section. */
  readonly isActive?: boolean | undefined;
  /** `NavItemAttrs` passthrough — all five presentational fields (`cssClass`/`description`/`icon`
   *  render as before; `rel`/`openInNewTab` added alongside them, same escaped/no-allowlist posture). */
  readonly attrs?:
    | {
        readonly cssClass?: string | undefined;
        readonly description?: string | undefined;
        readonly icon?: string | undefined;
        readonly rel?: string | undefined;
        readonly openInNewTab?: boolean | undefined;
      }
    | undefined;
  readonly children: readonly StaticMenuItem[];
}

/** An HTML-mode menu (owner 2026-10-08): the author's own stored markup, placed as-is at the marker.
 *  Trusted, admin/owner-only markup like HTML-mode forms; the save path (Jini `menu-html.ts`) balances it. */
export interface StaticHtmlMenu {
  readonly html: string;
}

/** What the route layer resolved for one menu id: its item tree, or its authored HTML. */
export type StaticMenuContent = readonly StaticMenuItem[] | StaticHtmlMenu;

/**
 * Fixed placeholder origin {@link safeHref} resolves a claimed same-origin-relative href against —
 * mirrors `server/inbound/public-http/http/site/render.ts`'s identically-named constant byte-for-byte.
 */
const SAFE_HREF_RESOLUTION_BASE = "http://tovu-safehref.invalid/";
const SAFE_HREF_RESOLUTION_ORIGIN = new URL(SAFE_HREF_RESOLUTION_BASE).origin;

/**
 * Sanitize a menu item's `href` before it reaches public HTML: allow only in-page (`#…`),
 * same-origin relative (`/…`), `http(s)://`, and `mailto:` targets. Everything else — notably
 * `javascript:`, `data:`, and any other scheme — collapses to `"#"` so a menu link can never smuggle
 * script into the page. A menu item's `href` is operator-authored (the admin menu editor, or an
 * agent tool acting on an operator's behalf) and reaches every visitor of the public site, including
 * an authenticated admin — the same "content is data, so a link is an untrusted string" posture
 * `render.ts`'s own `safeHref` doc already states for post-body links.
 *
 * **This is a deliberate DUPLICATE, not a shared import, of
 * `server/inbound/public-http/http/site/render.ts`'s `safeHref` (confirmed byte-identical logic,
 * including its `/…` branch's 2026-08-20 protocol-relative-URL fix — see that function's own doc for
 * the full attack-shape writeup this mirrors).** `render.ts` sits in `server/inbound/`, a layer
 * `features/theme` must never reach into (`check:boundaries`' no-deep-import rule; a feature pulling
 * from an inbound-transport module is backwards), and importing it would open a runtime import cycle
 * back into the file that pulls in widgets/Liquid/Handlebars. (`escapeHtml` had the same problem
 * until it moved to the import-free leaf `platform/html/escape.ts`.) If this logic changes, the `render.ts` copy
 * must change too — that file does not yet cross-reference this one; flagged for whoever next edits
 * either copy to add the reciprocal comment there.
 *
 * **KNOWN GAP, not fixed here (out of this pass's scope):** `render.ts`'s own `announcement`,
 * `siteNav`, and `siteFooterRich` widget renderers build `<a href>` from operator-authored widget
 * props via `escapeHtml(str(o.href, "#"))` alone, with NO `safeHref` call — the exact same class of
 * gap this function closes for static-tier menus, still live in that file's widget-IR path.
 *
 * @returns the original value when it passes the allowlist, otherwise `"#"` — never a malformed or
 *   unsafe href, matching this codebase's "degrade, don't disappear" convention for a link target.
 *
 * Takes `string`, not `string | null` — matching `escapeHtml`'s own signature (`platform/html/escape.ts`).
 * `render.ts`'s `safeHref` accepts `JsonValue | undefined` because ITS callers hand it raw,
 * attacker-shaped widget-prop JSON; both of THIS function's callers already narrow `StaticMenuItem`'s
 * `href: string | null` to a real string before calling (the same `available && href !== null` gate
 * `renderMenuLinks`'s `.filter()` and `renderMenuItem`'s `linkable` both already apply) — adding a
 * second, always-false null guard here would be untestable dead code, not defense in depth.
 */
export function safeHref(value: string): string {
  const href = value.trim();
  if (href.startsWith("#")) return href;
  if (/^https?:\/\//i.test(href) || /^mailto:/i.test(href)) return href;
  if (href.startsWith("/")) {
    let resolved: URL;
    try {
      resolved = new URL(href, SAFE_HREF_RESOLUTION_BASE);
    } catch {
      return "#";
    }
    return resolved.origin === SAFE_HREF_RESOLUTION_ORIGIN ? href : "#";
  }
  return "#";
}

/**
 * Renders one location's resolved menu items as a flat sequence of `<a>` tags. Top-level items
 * only — v1: every static theme's nav/footer markup this session is a flat link row/column with no
 * dropdown/submenu CSS to hook a nested render into, so rendering `children` would need chrome none
 * of these themes ship (a real gap, not silently papered over: nested items are simply not emitted).
 * An unavailable item (deleted/unpublished target, or an unresolvable ref) is omitted entirely,
 * never rendered as a dead link — mirrors `render.ts`'s own `renderWidgetMenuItems` convention for
 * the same `ResolvedNavItem` shape.
 */
function renderMenuLinks(items: readonly StaticMenuItem[]): string {
  // `menuItemLinkAttrs` (not a bare aria-current) so authored `rel`/`openInNewTab` reach a FLAT nav
  // too — the tree variant and the widget-IR menu already honored them, and the admin menu editor
  // offers both, so a flat header/footer silently ignoring them was a render-path divergence.
  return items
    .filter((item) => item.available && item.href !== null)
    .map((item) => `<a href="${escapeHtml(safeHref(item.href as string))}"${menuItemLinkAttrs(item)}>${escapeHtml(item.label)}</a>`)
    .join("");
}

/**
 * Renders a resolved menu as a nested `<ul>`/`<li>` tree — the shape a docs sidebar needs and
 * {@link renderMenuLinks} cannot produce. **Opt-in per marker** via `{"variant":"tree"}` in the
 * marker's `data-embed-config`, and
 * that is a hard requirement rather than a preference: every static theme's nav CSS today targets
 * direct `<a>` children of a flex container (`basic`'s own `.main-nav { display: flex }` with
 * `.main-nav a`, and the same shape in the other six), so unconditionally introducing a `<ul>` wrapper
 * would collapse each of those navs to a single flex child. Flat stays the default and stays
 * byte-identical; a theme opts a specific marker into the tree when its CSS is ready for one.
 * `{"variant":"dropdown"}` is that tree plus Jini's disclosure toggles and keyboard script
 * (`@jini-ai/cms/navigation`); see {@link renderMenuItem}.
 *
 * Emitted hooks, all of which `renderMenuLinks` drops on the floor: `is-current` (this item is the
 * page), `is-active` (this item or a descendant is — what expands the right section), `has-children`,
 * a `depth-N` class, and the item's own authored `attrs.cssClass`. `description`/`icon` render as
 * child spans so a theme can style or ignore them without the renderer knowing an icon set.
 * `attrs.rel`/`attrs.openInNewTab` render onto the `<a>` itself (`rel="…"`/`target="_blank"`) —
 * escaped, not allowlist-validated, same posture as `cssClass`/`icon` despite this file's own
 * `NavItemAttrs` doc comment describing `rel` as "validated against an allowlist": no such
 * allowlist exists anywhere in the write chokepoint (`validateAndCloneTree` clones `attrs`
 * untouched) — flagged, not fixed, here; fixing it is a Jini `menu-service.ts` change, out of this
 * pass's scope.
 *
 * Availability rule, which differs from the flat renderer's on purpose: an unavailable **leaf** is
 * omitted entirely (the flat contract — never emit a dead link), but an unavailable **branch** is
 * kept as inert text so its available children are not deleted along with it. A trashed section
 * heading should not silently take its whole subtree off the page.
 */
/** The `<li>` class list: structural hooks first, then the item's own authored `cssClass`. Raw —
 *  the caller escapes it, since authored `cssClass` is admin-controlled attribute text. */
function menuItemClasses(item: StaticMenuItem, depth: number): string {
  return [
    "menu-item",
    `depth-${depth}`,
    item.children.length > 0 ? "has-children" : "",
    item.isCurrent ? "is-current" : "",
    item.isActive ? "is-active" : "",
    item.attrs?.cssClass ?? "",
  ]
    .filter((c) => c !== "")
    .join(" ");
}

/** The item's icon/label/description markup, shared by both the linkable and inert renderings of
 *  {@link menuItemBody}. `icon`/`description` render as child spans so a theme can style or ignore
 *  them without this renderer having to know an icon set. */
function menuItemInnerHtml(item: StaticMenuItem): string {
  const label = escapeHtml(item.label);
  const icon = item.attrs?.icon ? `<span class="menu-item-icon" data-icon="${escapeHtml(item.attrs.icon)}"></span>` : "";
  const description = item.attrs?.description
    ? `<span class="menu-item-desc">${escapeHtml(item.attrs.description)}</span>`
    : "";
  return `${icon}${label}${description}`;
}

/** The `<a>` tag's own attribute suffix (`aria-current`/`rel`/`target`) for a linkable item. */
function menuItemLinkAttrs(item: StaticMenuItem): string {
  const current = item.isCurrent ? ' aria-current="page"' : "";
  const rel = item.attrs?.rel ? ` rel="${escapeHtml(item.attrs.rel)}"` : "";
  const target = item.attrs?.openInNewTab ? ' target="_blank"' : "";
  return `${current}${rel}${target}`;
}

/**
 * The item's own label markup — an `<a>` when it resolves, an inert `<span>` when it does not.
 * `icon`/`description` render as child spans so a theme can style or ignore them without this
 * renderer having to know an icon set.
 */
function menuItemBody(item: StaticMenuItem, linkable: boolean): string {
  const inner = menuItemInnerHtml(item);
  if (!linkable) return `<span class="menu-item-label">${inner}</span>`;
  return `<a href="${escapeHtml(safeHref(item.href as string))}"${menuItemLinkAttrs(item)}>${inner}</a>`;
}

/** Set for `{"variant":"dropdown"}` menus: hands out the child-`<ul>` ids the toggles point at. */
type MenuDropdown = { nextId(): string };

/**
 * One `<li>`, or `""` when the item is neither linkable nor a branch worth keeping for its children.
 * With `dropdown`, a branch gets a Jini toggle as a direct child of its `<li>` whose `aria-controls`
 * is the child `<ul>`'s id: after the `<a>` (split button), or in place of the label when the parent
 * has no real link (unresolved, or exactly `"#"`). Leaves render exactly as the tree variant.
 */
function renderMenuItem(item: StaticMenuItem, depth: number, dropdown?: MenuDropdown): string {
  const linkable = item.available && item.href !== null;
  const lis = item.children.length > 0 ? renderMenuItems(item.children, depth + 1, dropdown) : "";
  if (!linkable && lis === "") return "";
  const classes = escapeHtml(menuItemClasses(item, depth));
  if (dropdown === undefined || lis === "") {
    const children = lis === "" ? "" : `<ul class="menu-list depth-${depth + 1}">${lis}</ul>`;
    return `<li class="${classes}">${menuItemBody(item, linkable)}${children}</li>`;
  }
  const controlsId = dropdown.nextId();
  const body = linkable && item.href !== "#"
    ? menuItemBody(item, true) + renderMenuToggle({ controlsId, label: item.label })
    : renderMenuToggle({ controlsId, label: item.label }, { asLabel: true });
  return `<li class="${classes}">${body}<ul class="menu-list depth-${depth + 1}" id="${escapeHtml(controlsId)}">${lis}</ul></li>`;
}

function renderMenuItems(items: readonly StaticMenuItem[], depth: number, dropdown?: MenuDropdown): string {
  return items
    .map((item) => renderMenuItem(item, depth, dropdown))
    .filter((li) => li !== "")
    .join("");
}

function renderMenuTree(items: readonly StaticMenuItem[], dropdown?: MenuDropdown): string {
  const rendered = renderMenuItems(items, 0, dropdown);
  if (rendered === "") return "";
  return `<ul class="menu-list depth-0"${dropdown === undefined ? "" : " data-jini-dropdown"}>${rendered}</ul>`;
}

/**
 * Fill every `{"type":"menu"}` marker with that menu's resolved items, or leave the marker's authored
 * content completely untouched when no data is supplied for its id (deleted menu, typo in the theme's
 * markup, or the id simply resolves to zero renderable links). That fallback is the contract, not a
 * convenience: an active static theme must render as it did before menus existed, never an empty nav.
 *
 * The marker element itself survives — {@link withInnerContent} rebuilds it from its own tag and
 * attributes, so `nav.html`'s `class="main-nav"` and the docs sidebar's `aria-label` are preserved.
 *
 * Marker location and parsing are `Jini/packages/cms/src/widgets/markers/marker.ts`'s job; this function only decides what goes
 * inside. That split is the point of the 2026-08-10 unification — four scanners with four regexes
 * became one.
 */
function injectMenuEmbeds(
  html: string,
  menus: Readonly<Record<string, StaticMenuContent>>
): string {
  // One counter per page, so two dropdown markers never mint the same submenu id.
  let submenuCount = 0;
  const dropdown: MenuDropdown = { nextId: () => `jini-submenu-${++submenuCount}` };
  return substituteMarkers({ html: html, resolve: (marker) => {
    if (marker.type !== MENU_MARKER_TYPE || marker.id === undefined) return undefined;
    const items = menus[marker.id];
    if (items === undefined) return undefined;
    if (!Array.isArray(items)) return injectAuthoredMenuHtml(marker, (items as StaticHtmlMenu).html);
    if (marker.config.mode === "html") {
      const plain = renderHtmlMenu({ id: marker.id, items, sanitizeHref: safeHref });
      // Match forms: a bare marker disappears; explicitly authored wrapper attributes survive.
      return plain === "" ? undefined : withElementKeptIfAttributed({ marker: marker, inner: plain });
    }
    const variant = marker.config.variant;
    const inner = variant === "tree" ? renderMenuTree(items)
      : variant === "dropdown" ? renderMenuTree(items, dropdown)
      : renderMenuLinks(items);
    return inner === "" ? undefined : withInnerContent({ marker: marker, inner: inner });
  } });
}

/**
 * An HTML-mode menu's markup at its marker. The theme's own wrapper (`<nav class="main-nav">`) keeps
 * its tag and attributes so theme layout still applies around the author's markup; a bare "Copy HTML
 * embed" marker disappears, the same rule the generated `mode: "html"` menu above follows. Empty
 * markup leaves the authored fallback, like an empty item tree.
 */
function injectAuthoredMenuHtml(marker: EmbedMarker, html: string): string | undefined {
  if (html.trim() === "") return undefined;
  return marker.config.mode === "html"
    ? withElementKeptIfAttributed({ marker: marker, inner: html })
    : withInnerContent({ marker: marker, inner: html });
}

/**
 * Every menu id a static theme's pages and partials reference, deduped, in no particular order. Pure
 * — reads only the in-memory shapes `loadTheme()` produced, no I/O. The route layer calls this BEFORE
 * `renderStaticPage` to know which real menus to fetch, since this file stays I/O-free.
 *
 * Scans every page and partial rather than only the one about to render: the route layer runs once
 * per request before the exact page is chosen, and `nav.html`/`footer.html` are shared across every
 * page anyway.
 *
 * @complexity O(n) over the theme's total authored HTML length across all pages and partials.
 */
export function scanMenuEmbedIds(theme: DiscoveredTheme): readonly string[] {
  const ids = new Set<string>();
  for (const html of [...Object.values(theme.pages), ...Object.values(theme.partials)]) {
    for (const marker of markersOfType({ html: html, type: MENU_MARKER_TYPE })) {
      if (marker.id !== undefined) ids.add(marker.id);
    }
  }
  return Array.from(ids);
}

/**
 * Post-previews marker (2026-09-03) — a theme/page marker that renders a bounded list of published
 * post previews wherever `{"type":"post-previews"}` appears, so any authored Page can host a post
 * listing (the immediate consumer is a themed `/blog`-style marketing page, but the mechanism is not
 * special-cased to one slug or theme). Follows the SAME "route resolves the I/O, this file only
 * decides how it renders" split {@link injectMenuEmbeds}/{@link scanMenuEmbedIds} already establish
 * for `{"type":"menu"}`.
 */

/** A `{"type":"post-previews"}` marker with no `limit` keeps its legacy 6 (no silent change); a
 *  configured one is clamped by the shared listing rule (`parseListingBatchSize`, ceiling 24, the
 *  same REQ-25 bound `recent-entries.ts` applies), so no config can turn the listing into a scan. */
const LEGACY_POST_PREVIEWS_LIMIT = 6;

/**
 * Minimal render-time shape for one post shown by a `{"type":"post-previews"}` marker — the
 * post-listing counterpart to {@link StaticMenuItem}: the route layer resolves the real, bounded,
 * visibility-filtered `PostRecord[]` (query, ADR-030 §4 gate, public path) and hands this file only
 * what it renders, keeping this module I/O- and domain-free per the file's own header.
 */
export interface StaticPostPreview {
  readonly title: string;
  readonly href: string;
  /** ISO 8601, for `<time datetime>` — `PostRecord` has no `publishedAt` (the unified-content-marker
   *  design doc's own note on why), so this is the go-live time (`publishAt`) when the post has one,
   *  else `updatedAt`, the same field the bounded query orders by (`postDisplayDateIso`). */
  readonly dateIso: string;
  /** Pre-formatted for display (e.g. "Sep 3, 2026") — no date-formatting/locale logic belongs in
   *  this pure render layer, mirroring every other pre-resolved field on this shape. */
  readonly dateLabel: string;
  /** Library cover from the shared public policy; an absent image emits no tag. */
  readonly featuredImage?: StaticFeaturedImage | null;
}

/** One marker's batch size — what the route fetches, what {@link injectPostPreviewsEmbeds} shows,
 *  and a see-more listing's batch size, so they never disagree.
 *  The route scans only the current page: unlike shared menu chrome, post listings are page-scoped,
 *  so pages without a marker must not query posts. Plain markers share one bounded query at the
 *  widest clamped size; each marker slices its own limit. Keyed/paged listings resolve separately. */
export function postPreviewsBatchSize(marker: Pick<EmbedMarker, "config">): number {
  return parseListingBatchSize({ config: marker.config }, { fallback: LEGACY_POST_PREVIEWS_LIMIT });
}

/** `{"type":"post-previews","paged":true}` — a numbered-pages listing (Bug C, 2026-10-22): the route
 *  resolves the requested page (`/page/<n>`, `/blog/page/<n>`) and its nav, so no list stops at one
 *  batch with older posts unreachable from any link. */
export function isPagedPostPreviewsMarker(marker: Pick<EmbedMarker, "config">): boolean {
  return marker.config.paged === true;
}

/** A paged post-previews listing's current page, resolved by the route: its posts and its
 *  already-rendered nav (`''` when there is only one page). */
export interface StaticPostPreviewsPage {
  readonly items: readonly StaticPostPreview[];
  readonly nav: string;
}

/** One see-more listing's rendered batch (`data-jini-see-more`, keyed by `data-jini-listing`): the
 *  items at the requested cursor, plus the next batch URL when more exist. */
export interface StaticListingBatch<T> {
  readonly items: readonly T[];
  readonly nextHref?: string;
}

/** One preview's markup — optional cover, title link and display date, already resolved by the route. */
function renderPostPreviewCard(preview: StaticPostPreview): string {
  return (
    `<article class="post-card">` +
    (preview.featuredImage ? renderCoverImageTag({ image: preview.featuredImage }, { loading: "lazy" }) : "") +
    `<h3><a href="${escapeHtml(preview.href)}">${escapeHtml(preview.title)}</a></h3>` +
    `<div class="post-meta"><time datetime="${escapeHtml(preview.dateIso)}">${escapeHtml(preview.dateLabel)}</time></div>` +
    `</article>`
  );
}

/**
 * Fill every `{"type":"post-previews"}` marker with up to its own (clamped) `limit` of `previews`'
 * leading entries, or leave the marker's authored fallback content completely untouched when there
 * is nothing to show (`previews` empty — mechanism not wired for this page, or zero visible posts —
 * or this marker's own slice comes up empty). Identical "no data ⇒ theme's own fallback survives"
 * contract {@link injectMenuEmbeds} already established for `{"type":"menu"}`: a theme with no
 * published posts yet renders exactly as authored rather than an empty grid.
 *
 * `previews` is already the CALLER's bounded, visibility-filtered, ordered result — see
 * {@link StaticPostPreview}'s own doc. This function only decides how many of it one marker shows
 * and how each one renders; it performs no I/O and applies no visibility rule of its own.
 *
 * A `paged` marker ({@link isPagedPostPreviewsMarker}) renders `page` (the route's requested page and
 * its nav) instead, when the route resolved one; a see-more key on it is then ignored.
 *
 * @complexity O(n) over `html`'s length for the marker scan/splice, plus O(m) over the small, fixed
 * number of post-previews markers a real page carries.
 */
function injectPostPreviewsEmbeds(
  html: string,
  previews: readonly StaticPostPreview[],
  batches: ReadonlyMap<number, StaticListingBatch<StaticPostPreview>>,
  page?: StaticPostPreviewsPage
): string {
  return substituteMarkers({ html: html, resolve: (marker) => {
    if (marker.type !== POST_PREVIEWS_MARKER_TYPE) return undefined;
    if (page !== undefined && isPagedPostPreviewsMarker(marker)) return renderPagedPostPreviews({ marker, page });
    const key = listingKeyOfAttributes({ attrs: marker.attrs });
    const batch = key === undefined ? undefined : batches.get(key);
    if (key !== undefined && batch !== undefined) return renderKeyedPostPreviews({ marker, key, batch });
    const slice = previews.slice(0, postPreviewsBatchSize(marker));
    return slice.length === 0 ? undefined : withInnerContent({ marker: marker, inner: slice.map(renderPostPreviewCard).join("") });
  } });
}

/** A see-more listing's batch, or `undefined` (authored fallback) when it is empty. */
function renderKeyedPostPreviews(
  { marker, key, batch }: { marker: EmbedMarker; key: number; batch: StaticListingBatch<StaticPostPreview> },
  _optional: Record<string, never> = {}
): string | undefined {
  if (batch.items.length === 0) return undefined;
  // A theme's client-side card stays in the listing for the see-more script to fill.
  const card = extractListingCardTemplate({ html: marker.inner }) ?? "";
  const inner = card + wrapListingItems({ key, items: batch.items.map(renderPostPreviewCard).join("") });
  return withInnerContent({ marker, inner }) + (batch.nextHref === undefined ? "" : renderListingMore({ key, href: batch.nextHref }));
}

/** A paged listing's current page followed by its nav, or `undefined` (authored fallback, no nav)
 *  when there are no posts at all. */
function renderPagedPostPreviews(
  { marker, page }: { marker: EmbedMarker; page: StaticPostPreviewsPage },
  _optional: Record<string, never> = {}
): string | undefined {
  if (page.items.length === 0) return undefined;
  return withInnerContent({ marker, inner: page.items.map(renderPostPreviewCard).join("") }) + page.nav;
}

/**
 * One collection marker's already-rendered entry list, keyed by {@link collectionMarkerKey}. The
 * route layer (`pages.ts`'s `resolveCollectionListsForRender`, C5) builds these — one query per
 * distinct marker config found on the page, run through `entry-list-render.ts`'s `renderEntryList` —
 * and hands the result to {@link renderStaticPage} as a `ReadonlyMap<string, string | undefined>`.
 * `html` is `undefined` for a marker this file's caller looked up but found nothing to show for
 * (unknown type, invalid config, or zero matching entries): the map still records the key so
 * {@link injectCollectionEmbeds} treats it as a deliberate miss rather than re-querying, but the
 * marker's authored fallback survives either way (`collectionLists`'s own contract, same as
 * `postPreviews`'s "absent input, absent effect").
 */
export interface StaticCollectionList {
  /** {@link collectionMarkerKey}'s output for the marker this list answers. */
  readonly key: string;
  readonly html: string;
}

/**
 * A stable identity for one `{"type":"collection",…}` marker's config, so a page with several
 * differently-configured collection markers (or the same config repeated) can be resolved as
 * independent entries in a `Map` — the same per-marker addressing `withAddedId`'s own `id` field
 * gives markers that need one, done here via the WHOLE config instead because two collection markers
 * can differ in `typeKey`/`sort`/`where`/`limit` without either carrying an `id`. `JSON.stringify` of
 * the parsed config as-is (no key filtering) is deterministic for a given authored marker: both this
 * file's {@link injectCollectionEmbeds} and the route layer's map-builder parse the identical marker
 * text into the identical `config` object, so they always agree on the key.
 *
 * The authored `<template>` ({@link splitCollectionMarkerInner}) is part of the identity too: the
 * rendered list depends on it, so two markers with the same config but different templates must not
 * share one map entry (the route layer dedupes by this key and renders with the FIRST marker's
 * template). A template-less marker keeps the plain config-JSON key; a templated one uses a JSON
 * array `[config, template]`, which starts with `[` and so can never equal an object key.
 *
 * @complexity O(k + n) over the config's own key count and the marker's inner length — independent of
 * the surrounding document.
 */
export function collectionMarkerKey(marker: EmbedMarker): string {
  const { template } = splitCollectionMarkerInner(marker.inner);
  const key = template === undefined ? JSON.stringify(marker.config) : JSON.stringify([marker.config, template]);
  // A see-more listing renders its own key's batch, so it never shares an entry with another marker.
  const listingKey = listingKeyOfAttributes({ attrs: marker.attrs });
  return listingKey === undefined ? key : `listing:${listingKey}:${key}`;
}

/**
 * Splits a collection marker's authored inner content into an optional per-item `template` (the
 * first `<template>…</template>` found, exclusive of the tags themselves) and the remaining
 * `fallback` markup (everything else, shown untouched on a miss — see {@link injectCollectionEmbeds}).
 * A marker authored with no `<template>` returns its whole inner content as `fallback` and no
 * `template`, which routes the route layer's renderer into its built-in cards/list markup instead of
 * per-item template mode (`entry-list-render.ts`'s `EntryListRenderOptions.template`).
 *
 * @complexity O(n) over `inner`'s length for the two substring scans plus the slice/concat.
 */
export function splitCollectionMarkerInner(inner: string): { template?: string; fallback: string } {
  const openTag = "<template>";
  const closeTag = "</template>";
  const start = inner.indexOf(openTag);
  if (start === -1) return { fallback: inner };
  const end = inner.indexOf(closeTag, start + openTag.length);
  if (end === -1) return { fallback: inner };
  const template = inner.slice(start + openTag.length, end);
  const fallback = inner.slice(0, start) + inner.slice(end + closeTag.length);
  return { template, fallback };
}

/**
 * Substitutes each `{"type":"collection"}` marker with its pre-resolved, pre-rendered entry list from
 * `lists` (looked up by {@link collectionMarkerKey}), preserving the marker element's own tag and
 * authored attributes but stripping `data-embed-config` on the hit path so a later re-scan of the
 * same output can never rediscover and re-resolve it (D3: matches the widget rule via
 * {@link withInnerContentFinal}, unlike {@link injectPostPreviewsEmbeds}'s `withInnerContent`). A miss
 * — no entry in `lists` for this marker's key, or an entry whose `html` is `undefined` — leaves the
 * marker exactly as authored, so its fallback/empty-state markup survives untouched (same "absent
 * input, absent effect" contract {@link injectMenuEmbeds}/{@link injectPostPreviewsEmbeds} already
 * establish for their own marker types).
 *
 * @complexity O(n) over `html`'s length — one `substituteMarkers` scan-and-splice pass, plus O(1)
 * per collection marker for the map lookup.
 */
function injectCollectionEmbeds(html: string, lists: ReadonlyMap<string, string | undefined>): string {
  return substituteMarkers({ html: html, resolve: (marker) => {
    if (marker.type !== COLLECTION_MARKER_TYPE) return undefined;
    const rendered = lists.get(collectionMarkerKey(marker));
    if (rendered === undefined) return undefined;
    const listingKey = listingKeyOfAttributes({ attrs: marker.attrs });
    const html = withInnerContentFinal({ marker: marker, inner: rendered });
    // A built-in layout's own wrapper is the see-more container, so the marker element gives up the
    // key; in template mode the items sit directly in the marker element, which keeps it.
    return listingKey === undefined || splitCollectionMarkerInner(marker.inner).template !== undefined
      ? html
      : html.replace(` data-jini-listing="${listingKey}"`, "");
  } });
}

/**
 * The current post's featured image, already resolved by the route layer — the same
 * `{ url, alt, width, height }` the Liquid/Handlebars tiers read as `post.featuredImage`
 * (`render.ts`'s `featuredImageView`), so both tiers show the identical image and alt text.
 */
export interface StaticFeaturedImage {
  readonly url: string;
  readonly alt: string;
  readonly width: number | null;
  readonly height: number | null;
}

/** The `<img>` for a public cover. `width`/`height` reserve the box before the bytes arrive (no
 *  layout shift; the theme's CSS scales it with `height: auto`). Eager with high fetch priority, not
 *  lazy: it sits at the top of the post, so it is usually the page's largest paint. Cards opt into
 *  lazy loading; URL/alt escaping and optional dimensions stay identical across both surfaces.
 * @example renderCoverImageTag({ image }, { loading: "lazy" })
 * @complexity O(url + alt) for escaping; no I/O.
 */
export function renderCoverImageTag({ image }: { image: StaticFeaturedImage }, optional: { loading?: "lazy" } = {}): string {
  const width = image.width === null ? "" : ` width="${image.width}"`;
  const height = image.height === null ? "" : ` height="${image.height}"`;
  const priority = optional.loading === "lazy" ? ' loading="lazy"' : ' fetchpriority="high"';
  return `<img src="${escapeHtml(image.url)}" alt="${escapeHtml(image.alt)}"${width}${height} decoding="async"${priority}>`;
}

/**
 * Fills every `{"type":"featured-image"}` marker with the current post's featured image, or removes
 * the marker's WHOLE element when there is none. Deliberately the opposite of the "absent input,
 * absent effect" rule {@link injectMenuEmbeds}/{@link injectPostPreviewsEmbeds} follow: a menu's
 * fallback is real content worth keeping, but a featured-image wrapper with nothing in it is an empty
 * figure with margins. `null`/`undefined` both mean "no image" — every surface that is not rendering
 * a post with one (home, marketing pages, a page with none set) passes nothing.
 *
 * @complexity O(n) over `html`'s length — one `substituteMarkers` scan-and-splice pass.
 */
export function injectFeaturedImage(html: string, image: StaticFeaturedImage | null | undefined): string {
  return substituteMarkers({ html: html, resolve: (marker) => {
    if (marker.type !== FEATURED_IMAGE_MARKER_TYPE) return undefined;
    return image ? withInnerContentFinal({ marker: marker, inner: renderCoverImageTag({ image }) }) : "";
  } });
}

/**
 * Fill author markers and the `{{author}}` shortcut with one escaped, visibility-gated credit.
 * A marker inside a content placeholder declares a byline for that content's header; fill it here
 * too for static previews, where the content itself has not yet been resolved.
 * @returns HTML with hidden marker elements removed and hidden tokens replaced with empty text.
 * @complexity O(n) time and output space in template length; no I/O or input mutation.
 */
export function injectPostAuthor(
  required: { html: string; post?: { author?: string | null; showAuthor?: boolean } },
  _optional: Record<string, never> = {},
): string {
  const author = required.post ? postAuthorForDisplay({ post: required.post }) : null;
  const credit = author ? `By ${escapeHtml(author)}` : "";
  const resolveAuthor = (marker: EmbedMarker): string | undefined => {
    if (marker.type !== "post-author") return undefined;
    return credit ? withInnerContentFinal({ marker, inner: (marker.attrs.includes('data-post-author-separator=') ? " · " : "") + credit }) : "";
  };
  // Substitute tokens before markers so token-like text in a saved author stays literal data.
  const html = required.html.replaceAll("{{author}}", () => credit);
  return substituteMarkers({ html, resolve: (marker) => {
    if (marker.type !== "content") return resolveAuthor(marker);
    const inner = substituteMarkers({ html: marker.inner, resolve: resolveAuthor });
    return inner === marker.inner ? undefined : withInnerContent({ marker, inner });
  } });
}

/**
 * Select the current content header's byline. A nested author marker explicitly places it below
 * the title/date; a byline elsewhere in the expanded template owns its own placement, so the core
 * header contributes none. Otherwise every theme gets the same `post-author` span as fallback: a span,
 * not a paragraph, because the core header sets it inside the date's `.post-meta` line, where a theme's
 * `p` margins or font size would pull it out of that line's typography (2026-10-10).
 * A nested marker goes into that same line, so it is re-tagged as a `span` too, keeping its authored
 * attributes and inner content: themes author it as `<p class="post-author">`, and as a `<p>` it took
 * the theme's 18px body text beside the 13px muted date, off the date's baseline (2026-10-10).
 * Return marker markup for the final {@link injectPostAuthor} pass, which owns escaping and
 * hidden-credit removal. Deferring that pass also keeps token-like text in a saved author literal.
 * @complexity O(n) time and output space in template length; pure, with no I/O.
 */
export function postAuthorForContentHeader(
  required: { html: string; post: { id: string; slug: string } },
  _optional: Record<string, never> = {},
): string {
  const content = markersOfType({ html: required.html, type: "content" }).find(marker =>
    marker.id !== undefined ? marker.id === required.post.id : marker.config.slug === required.post.slug);
  const nestedAuthor = content && markersOfType({ html: content.inner, type: "post-author" })[0];
  if (nestedAuthor) return `<span${nestedAuthor.attrs}>${nestedAuthor.inner}</span>`;
  const tokenInHeader = content?.inner.includes("{{author}}") === true;
  if (!tokenInHeader && (required.html.includes("{{author}}") || markersOfType({ html: required.html, type: "post-author" }).length > 0)) return "";
  return `<span class="post-author" data-embed-config='{"type":"post-author"}'></span>`;
}

/** `nav.html` → `nav`; the partial-id key `loadStaticTierAssets` stores root partials under. */
function partialIdFromSource(source: string): string {
  return source.endsWith(".html") ? source.slice(0, -".html".length) : source;
}

/**
 * Resolve one partial-slot marker to the partial's content: pick the source (the descriptor's
 * explicit `variants` map, else the `<source-stem>-<variant>.html` convention), then splice
 * `aria-current="page"` onto the partial's own `data-nav-id="<current>"` anchor.
 *
 * `descriptor.honorsCurrentPage` no longer names an attribute to read — the config key is always
 * `current`. It survives as the theme's declaration of WHETHER this slot honors a current-page hint
 * at all, which is still a per-slot fact (a footer has no current item).
 *
 * A marker whose resolved partial does not exist collapses to empty, matching the pre-2026-08-10
 * behavior for the same case.
 */
function resolveSlotMarker(
  descriptor: ThemeSlotDescriptor,
  partials: Record<string, string>,
  config: Readonly<Record<string, unknown>>
): string {
  const variant = typeof config.variant === "string" ? config.variant : undefined;
  const current = typeof config.current === "string" ? config.current : undefined;
  const source =
    variant === undefined
      ? descriptor.source
      : descriptor.variants?.[variant] ?? `${partialIdFromSource(descriptor.source)}-${variant}.html`;
  const partial = partials[partialIdFromSource(source)] ?? "";

  if (descriptor.honorsCurrentPage !== true || current === undefined) return partial;
  /** Escape a manifest-supplied string so it matches literally inside a constructed `RegExp`. */
  const linkRe = new RegExp(`(<a href="[^"]+" data-nav-id="${RegExp.escape(current)}")(>)`);
  return partial.replace(linkRe, '$1 aria-current="page"$2');
}

/**
 * Replace every `{"type":"partial"}` marker with the root partial the theme's `theme.json` `slots`
 * block maps that key to. A BARE marker's own element disappears entirely — it is scaffolding, and
 * the partial is a complete `<nav>`/`<footer>` of its own — but one carrying any authored attribute
 * besides `data-embed-config` keeps that element (minus the marker config) around the resolved
 * partial ({@link withElementKeptIfAttributed}, D3 of the 2026-09-23 collections/embeds plan): the
 * same keep-if-attributed rule the `widget` marker type already followed. A survey of every shipped
 * theme found no attributed partial marker in the wild, so this is additive — every existing bare
 * marker keeps disappearing exactly as before.
 *
 * Manifest-driven rather than the hardcoded `nav`/`footer` pair this carried before 2026-08-10; that
 * pair now lives in {@link DEFAULT_THEME_SLOTS} and is used verbatim for a theme declaring no
 * `slots`. A marker naming a key the manifest does not declare is left untouched rather than blanked,
 * so a typo shows the authored fallback instead of a hole.
 *
 * @complexity O(n) over `html` for the single marker scan, plus one map lookup per marker — where the
 * pre-unification version ran one full regex pass per declared slot key, times two spellings.
 */
function resolveSlots(
  html: string,
  partials: Record<string, string>,
  slots: Readonly<Record<string, ThemeSlotDescriptor>> = DEFAULT_THEME_SLOTS
): string {
  return substituteMarkers({ html: html, resolve: (marker) => {
    if (marker.type !== PARTIAL_MARKER_TYPE || marker.id === undefined) return undefined;
    const descriptor = slots[marker.id];
    if (descriptor === undefined) return undefined;
    return withElementKeptIfAttributed({ marker: marker, inner: resolveSlotMarker(descriptor, partials, marker.config) });
  } });
}

/**
 * Partial-slot expansion as its OWN exported step (E2, 2026-09-23), so a caller can run it standalone
 * over already-assembled HTML rather than only as the inline step {@link renderStaticPage} below
 * still takes. Exists for D2's `finishStaticTierDocument` pipeline (`pages.ts`), which expands
 * partials first and only then scans the assembled result for widget/media/post/content/menu/
 * post-previews markers a partial itself might carry.
 *
 * Equivalent to {@link resolveSlots} called with the theme's own partials and declared (or default)
 * slots — no new behavior, just a named entry point for a caller that only has a `theme`, not the
 * two separate `partials`/`slots` arguments.
 *
 * @complexity Same as {@link resolveSlots}: O(n) over `html`'s length.
 */
export function expandPartials(html: string, theme: Pick<DiscoveredTheme, "partials"> & { manifest: Pick<DiscoveredTheme["manifest"], "slots"> }): string {
  return resolveSlots(html, theme.partials, theme.manifest.slots ?? DEFAULT_THEME_SLOTS);
}

/**
 * Stamp the theme's declared `defaultMode` onto the page's `<html>` element as `data-theme`, which is
 * the selector `tokensToRootCss` emits the `tokens.light.json` override block under. Without this the
 * light token set was authored, loaded, and emitted into the page — but unreachable, because nothing
 * ever set the attribute its block keys off.
 *
 * No-ops when the manifest declares no `defaultMode`, and leaves an `<html>` that already carries a
 * `data-theme` alone, so a theme hand-authoring its own value keeps it. A theme wanting the mode to be
 * user-switchable ships its own toggle script against `document.documentElement.dataset.theme`; this
 * only establishes the server-rendered starting value.
 */
function injectColorMode(html: string, defaultMode: string | undefined): string {
  if (defaultMode === undefined) return html;
  return html.replace(/<html(?![^>]*\sdata-theme=)([^>]*)>/i, `<html$1 data-theme="${escapeHtml(defaultMode)}">`);
}

/**
 * {@link renderStaticPage}'s token step: insert the theme's design tokens as a `<style>` block just
 * before the exact sentinel {@link tokenStylesheetSentinel} picks for the theme's `apiVersion`. A page
 * without that sentinel is returned unchanged with a warning naming it — tokens are never guessed in.
 * @complexity O(n) in the page length.
 */
function injectTokenStylesheet(required: { html: string; theme: DiscoveredTheme; pageId: string }): string {
  const { html, theme, pageId } = required;
  const sentinel = tokenStylesheetSentinel(theme.manifest.apiVersion);
  if (!html.includes(sentinel)) {
    console.warn(
      `[theme] static page '${theme.manifest.id}/${pageId}' is missing the exact token stylesheet sentinel; design tokens were not injected`
    );
    return html;
  }
  return html.replace(
    sentinel,
    () => `<style>\n${tokensToRootCss(theme.tokens, theme.tokensLight)}\n</style>\n${sentinel}`
  );
}

/**
 * Warn (never fail) about relative asset references {@link rewriteAssetPaths} left alone — each one
 * will 404 in the browser. The folders named follow the theme's `apiVersion`.
 * @complexity O(n) in the page length.
 */
function warnUnrewrittenAssetPaths(required: { html: string; theme: DiscoveredTheme; pageId: string }): void {
  const { html, theme, pageId } = required;
  const apiVersion = theme.manifest.apiVersion;
  const unrewrittenAssetPaths = findUnrewrittenAssetPaths(html, apiVersion);
  if (unrewrittenAssetPaths.length === 0) return;
  const assetFolders = apiVersion === 2 ? "../css//../scripts/" : "../css//../js/";
  console.warn(
    `[theme] static page '${theme.manifest.id}/${pageId}' has ${unrewrittenAssetPaths.length} unrewritten ${assetFolders} asset reference(s) that will 404 in the browser: ${unrewrittenAssetPaths.join(", ")}`
  );
}

/**
 * Render one page of a `static`-tier theme for the live site. Returns `null` if the theme has no
 * page under that id (caller degrades to `fallbackBody()`, same REQ-10 contract every other tier
 * already follows for an unresolved route).
 *
 * `htmlOverride` (post-template-picker feature, 2026-08-10): when supplied, used as the page source
 * INSTEAD of `theme.pages[pageId]` — the route layer's post-template render path already read the
 * template off `theme.pages`, substituted the real post id via {@link injectPostEmbedId}, and
 * resolved+rendered its `data-embed-type="post"` slot (I/O this file must stay free of, see the file
 * header), so by the time it calls this the embed is already real HTML; this function still applies
 * every OTHER static-tier treatment (token injection, asset-path rewrite, slot resolution, link
 * rewrite) uniformly on top, so a post-template page gets exactly the same treatment any other static
 * page does, not a parallel/divergent code path.
 *
 * `menus` (direct menu-embed wiring, superseding the earlier `header`/`footer` location scheme):
 * pre-resolved items keyed by real menu id (`navigation`'s `resolveMenuDoc`, fetched per id found by
 * {@link scanMenuEmbedIds}, run by the route layer — this file stays I/O-free, same split
 * `pages.ts`'s own resolver functions document). Each key is independently optional: a menu id with
 * no entry in this map (or a request for a non-static-tier theme, which never calls this with
 * `menus` at all) simply leaves that marker's theme-authored fallback content untouched, see
 * {@link injectMenuEmbeds}.
 *
 * `postPreviews` (post-previews marker, 2026-09-03): the route layer's already-bounded,
 * visibility-filtered result — see {@link postPreviewsBatchSize}/{@link StaticPostPreview}'s own
 * docs for how it decides whether to fetch anything at all. Omitted (or empty) leaves every
 * `{"type":"post-previews"}` marker's authored fallback untouched, see
 * {@link injectPostPreviewsEmbeds} — same "absent input, absent effect" contract `menus` already has.
 *
 * `collectionLists` (collection marker, 2026-09-23): the route layer's already-resolved,
 * already-rendered entry lists, one per distinct marker config — see {@link StaticCollectionList}'s
 * own doc for how a miss is recorded. Omitted (or a miss for a given marker) leaves that
 * `{"type":"collection"}` marker's authored fallback untouched, see {@link injectCollectionEmbeds} —
 * same "absent input, absent effect" contract `menus`/`postPreviews` already have.
 */
export function renderStaticPage(
  required: {
    theme: DiscoveredTheme;
    pageId: string;
    htmlOverride?: string;
    menus?: Readonly<Record<string, StaticMenuContent>>;
    postPreviews?: readonly StaticPostPreview[];
    /** See-more post-previews listings by listing key; a keyed marker absent here renders from `postPreviews`. */
    postPreviewBatches?: ReadonlyMap<number, StaticListingBatch<StaticPostPreview>>;
    /** The requested page of every `paged` post-previews marker; absent ⇒ those markers render as plain ones. */
    postPreviewsPage?: StaticPostPreviewsPage;
    collectionLists?: ReadonlyMap<string, string | undefined>;
    /** The current post's featured image ({@link injectFeaturedImage}); omitted ⇒ no image. */
    featuredImage?: StaticFeaturedImage | null;
    /** Current post metadata; absent on other static surfaces, which removes the byline marker. */
    postAuthor?: { author?: string | null; showAuthor?: boolean };
  },
  _optional: Record<string, never> = {}
): string | null {
  const { theme, pageId, htmlOverride, menus, postPreviews, postPreviewBatches, postPreviewsPage, collectionLists, featuredImage, postAuthor } = required;
  const source = htmlOverride ?? theme.pages[pageId];
  if (source === undefined) return null;

  let html = injectTokenStylesheet({ html: source, theme, pageId });
  html = rewriteAssetPaths(html, theme.manifest.id, theme.manifest.apiVersion);
  warnUnrewrittenAssetPaths({ html, theme, pageId });
  html = injectColorMode(html, theme.manifest.defaultMode);
  html = expandPartials(html, theme);
  html = injectMenuEmbeds(html, menus ?? {});
  html = injectPostPreviewsEmbeds(html, postPreviews ?? [], postPreviewBatches ?? new Map(), postPreviewsPage);
  html = injectCollectionEmbeds(html, collectionLists ?? new Map());
  html = injectFeaturedImage(html, featuredImage);
  html = injectPostAuthor({ html, post: postAuthor });
  html = withEntryListStyleOnce(html);
  html = rewritePageLinks(html);
  return injectMenuDropdownScript({ html: injectListingScript({ html }) });
}

/**
 * The minimal host document a partial renders inside when previewed standalone. Carries whichever
 * sentinel {@link tokenStylesheetSentinel} picks for `apiVersion` — the exact one
 * {@link renderStaticPage}'s own token-injection step matches against (see its call to
 * {@link tokensToRootCss} above) — so a partial preview picks up the theme's design tokens and
 * stylesheet through the SAME code path a real page uses, for either schema version, no second
 * "inject styles into a fragment" mechanism to keep in sync with the first.
 */
function wrapPartialInHostDocument(partialHtml: string, apiVersion?: 2): string {
  return `<!doctype html>
<html>
<head>
<meta charset="utf-8" />
<title>Partial preview</title>
${tokenStylesheetSentinel(apiVersion)}
</head>
<body>
${partialHtml}
</body>
</html>`;
}

/**
 * Render a static theme's PARTIAL (`nav`, `footer`, `sidebar`, any slot's root file) standalone,
 * styled with the theme's own tokens and stylesheet — for the Explore screen's preview, which used to
 * refuse partials outright ("Partials have no standalone preview") on the theory that a fragment out
 * of page context is meaningless. It isn't: a partial IS complete, styled markup the moment its CSS
 * loads, and wrapping it in {@link wrapPartialInHostDocument} and handing that to
 * {@link renderStaticPage} as `htmlOverride` gets it every treatment a real page gets — token
 * injection, asset-path rewrite, its own slot/menu markers (if it happens to carry any), internal
 * link rewrite — through the one pipeline rather than a parallel partial-only one.
 *
 * `pageId` passed to `renderStaticPage` is irrelevant here (it only reads `theme.pages[pageId]` as a
 * fallback when `htmlOverride` is absent, and this always supplies one), so the partial id doubles
 * for it rather than inventing a placeholder.
 *
 * Returns `null` if the theme has no partial under that id — same "unknown id, not found" contract
 * {@link renderStaticPage} already uses for an unknown page id.
 */
export function renderStaticPartial(
  required: { theme: DiscoveredTheme; partialId: string },
  _optional: Record<string, never> = {}
): string | null {
  const { theme, partialId } = required;
  const partial = theme.partials[partialId];
  if (partial === undefined) return null;
  return renderStaticFragment({ theme, html: partial, label: partialId });
}

/** Unsaved fragments use the same document, token injection and asset rewriting as partials.
 * @complexity The existing static-page render cost over the fragment's HTML.
 */
export function renderStaticFragment(
  { theme, html, label }: { theme: DiscoveredTheme; html: string; label: string },
  _optional: Record<string, never> = {},
): string {
  return renderStaticPage({
    theme,
    pageId: label,
    htmlOverride: wrapPartialInHostDocument(html, theme.manifest.apiVersion),
  })!; // htmlOverride is always supplied, so renderStaticPage's missing-source branch cannot run.
}

/**
 * Outcome of {@link resolveTemplate}: either a usable template, or the diagnostic page. Name kept
 * singular ("Post") for historical/import-compatibility reasons — the type predates the 2026-08-11
 * unification and was already documented as shared/kind-agnostic before this change; renaming it
 * remains a pure rename with no behavior change and stays out of this pass's scope too.
 */
export type PostTemplateResolution =
  | { kind: "template"; pageId: string; html: string }
  | { kind: "diagnostic" };

/**
 * Legacy -> current filename map for the live `basic` theme's 2026-09-03 rename to a
 * `posts-*.html`/`pages-*.html` content-template naming convention (`blog-post.html` ->
 * `posts-default.html`, `blog-sidebar-template.html` -> `posts-sidebar.html`, `page-shell.html` ->
 * `pages-default.html` — the theme's own `theme.json` `templates` array carries only the new names
 * now). Keyed and valued by `theme.pages` id (no `.html`), matching {@link resolveTemplate}'s own
 * `pageId` convention.
 *
 * Consulted ONLY as a fallback inside {@link resolveTemplate}'s `resolveAgainstTheme`, after a direct
 * `theme.pages[pageId]` lookup already missed — never as a first choice, and never for any OTHER
 * theme's own naming (a theme that still ships `blog-post.html` resolves it directly, this map is
 * never reached). This is what keeps every row whose stored `template_choice` still names an OLD
 * filename (27 counted 2026-09-03) rendering byte-for-byte identically after the rename, on `basic`
 * AND on every one of the five other installed static themes that still ship the old names — a row's
 * stored choice is theme-relative but not theme-scoped (this function's own doc above), so it must
 * keep resolving correctly however the active theme later changes. Explicitly NOT paired with a
 * database backfill of those 27 rows: backfilling `template_choice` to the new name would make a row
 * MORE fragile on a future theme switch (a theme that still ships only the old name would no longer
 * match), not less — this alias map is the only direction that stays correct in both timelines.
 *
 * A COMPATIBILITY SHIM, not a permanent feature — the mapping only exists because exactly one of six
 * installed static themes has adopted the new convention so far. Remove an entry once every
 * currently-installed static theme (`sites/tovu-com/themes/static/*`) ships the RIGHT-hand filename
 * instead of the left, and no `posts`/`pages` row's `template_choice` still names the left-hand one —
 * check both before deleting a line, not just one.
 */
const LEGACY_TEMPLATE_FILENAME_ALIASES: Readonly<Record<string, string>> = {
  "blog-post": "posts-default",
  "blog-sidebar-template": "posts-sidebar",
  "page-shell": "pages-default",
};

/**
 * Decide which of a static theme's template pages a Post or Page renders through (2026-08-11
 * unification — collapses what were the separate `resolvePostTemplate`/`resolvePageTemplate`
 * specializations of this same tri-state engine into one function, now that both kinds resolve
 * against the SAME `theme.manifest.templates` array and the SAME `"content"` slot marker). Pure —
 * the caller owns the embed-resolution I/O that follows.
 *
 * `templateChoice` is a **tri-state**, and the difference between two of its values is the whole
 * point of this function (regression, 2026-08-09: 15 of 19 published posts served the diagnostic
 * page at HTTP 200 because the two were conflated):
 *
 * - `null`/`undefined` — *never chosen*. Migration `0028` added `template_choice` as an additive
 *   nullable column with no backfill, so every pre-feature row reads `null`, as does any row
 *   written by a path that doesn't know this field exists (seed script, agent tool, direct API or
 *   DB insert). That is the absence of a decision, not a decision, so it falls back to the theme's
 *   first-listed template — the same value the admin editor's picker already defaults an unset row
 *   to on load, which keeps what an author sees selected and what the public site renders in
 *   agreement. Making the *column default* the *safe* behavior is deliberate: it is what stops this
 *   bug reappearing on the next row created outside the editor.
 *
 *   For a `kind: "page"` row specifically, this fallback arm is never reached in practice —
 *   `isEligibleForTemplateBranch`'s Page rule (`pages.ts`) refuses to route a Page into this
 *   resolution at all unless `templateChoice` is already non-`null`/`undefined`. It stays here
 *   rather than being special-cased away because the tri-state is a property of the CHOICE, not of
 *   which kind of row is asking — a caller that ever legitimately wants "never chosen -> theme's
 *   first template" for a Page (none does today) gets correct behavior for free, and that asymmetry
 *   living in the ELIGIBILITY gate rather than in here is exactly what let it survive this merge:
 *   this function did not have to change to preserve it, only its caller's gating did.
 * - `""` — *explicitly opted out*, the admin picker's "No template chosen" option. A deliberate
 *   author action, and the one value no naive insert produces. For a `kind: "post"` row, keeps
 *   showing the diagnostic page, which is the designed product behavior ("not a silent fallback to
 *   generic rendering") — the ONLY value that reaches the diagnostic page without the theme first
 *   getting a say.
 *
 *   For a `kind: "page"` row, `""` means something else since the owner's 2026-09-23 ruling: a
 *   **bare page** ({@link isBarePageChoice}), serving the Page's own HTML with no theme chrome at
 *   all — not the diagnostic page above. `isPageTemplateChoiceEligible` (below) now refuses a
 *   Page's `""` in both body formats, so this function is never reached with `""` for a Page in
 *   practice; the arm above applies to a Post only.
 * - `"blog-post.html"` — an explicit choice. Rendered as-is when the ACTIVE theme can honor it,
 *   and otherwise treated exactly like the never-chosen case, for the reason below.
 *
 * A stored choice is **theme-relative but not theme-scoped**: it names a file in whatever theme was
 * active when an author picked it, and nothing on the row records which theme that was. Switching
 * the site's active theme therefore strands every explicit choice at once. Reading a stranded
 * choice as an opt-out would put every one of those rows back on the HTTP-200 diagnostic page —
 * the same outage as the `null` regression, reached by a routine admin action instead of a
 * migration, and unreachable by any backfill because the stored value is a real filename rather
 * than `null`. "This theme has no such template" is the absence of a decision *for this theme*, not
 * a decision, so it falls back. Only `""` is theme-independent enough to mean opt-out.
 *
 * A page that exists but ships no `"content"` slot counts as "cannot honor" for the same reason and
 * falls back too; the diagnostic page is reached only when the theme's own first template is also
 * unusable, since rendering a slotless template would silently drop the row's body.
 *
 * `theme.pages` is keyed by filename WITHOUT `.html` (`loadTheme`'s convention) while
 * `templateChoice`/`theme.manifest.templates` entries carry it; the `.replace` below is the one
 * place that naming mismatch is bridged. A `pageId` absent from `theme.pages` gets ONE more chance
 * against {@link LEGACY_TEMPLATE_FILENAME_ALIASES} before counting as "cannot honor" — see that
 * constant's own doc for why this, not a database backfill, is what keeps a stranded old-named choice
 * resolving correctly on `basic` after its 2026-09-03 rename.
 *
 * @complexity O(n) in the template's HTML length for the slot check, over at most two candidates;
 *   O(1) lookups otherwise.
 */
export function resolveTemplate(
  required: { theme: DiscoveredTheme; templateChoice: string | null | undefined },
  _optional: Record<string, never> = {}
): PostTemplateResolution {
  const { theme, templateChoice } = required;
  if (templateChoice === "") return { kind: "diagnostic" };

  const resolveAgainstTheme = (choice: string | undefined): PostTemplateResolution | undefined => {
    if (choice === undefined || choice === "") return undefined;
    const requestedId = choice.replace(/\.html$/, "");
    const pageId = theme.pages[requestedId] !== undefined ? requestedId : (LEGACY_TEMPLATE_FILENAME_ALIASES[requestedId] ?? requestedId);
    const html = theme.pages[pageId];
    // "Ships a slot" is asked of the shared parser, never of a substring match. The literal
    // `data-embed-id="{{post}}"` this used to test for stopped existing the moment the themes moved
    // onto `data-embed-config` (2026-08-10), and because the miss is indistinguishable from "this
    // theme has no such template", EVERY post silently fell through to the diagnostic page at HTTP
    // 200 — the exact 2026-08-09 regression this function's own doc was written about, re-entered
    // through a different door. Asking `markersOfType` also means a template carrying a hardcoded
    // real id (or an already-spliced body) counts as having a slot, which it does.
    if (html === undefined || markersOfType({ html: html, type: "content" }).length === 0) return undefined;
    return { kind: "template", pageId, html };
  };

  return (
    resolveAgainstTheme(templateChoice ?? undefined) ??
    resolveAgainstTheme(theme.manifest.templates?.[0]) ?? { kind: "diagnostic" }
  );
}

/**
 * Gates whether a `posts`-table record should even be routed into the template render branch
 * (`renderViaTemplate` in `server/routes/site/pages.ts`) — a decision distinct from, and prior to,
 * {@link resolveTemplate}'s own tri-state resolution of WHICH template to use once inside that
 * branch.
 *
 * 2026-08-11 unification: collapses what were the separate `isEligibleForPostTemplateBranch`/
 * `isEligibleForPageTemplateBranch` gates into one function, now that both route to the SAME
 * `renderViaTemplate` using the SAME `theme.manifest.templates` array. The two gates existed
 * separately only because a Post-shaped and a Page-shaped template used to be structurally different
 * artifacts (different marker type, different manifest array) that needed different eligibility
 * arrays to check against; the unified `"content"` marker and single `templates` array removed that
 * split at the source, so keeping two near-identical functions here would just be the same
 * duplicated-logic risk `resolveTemplate`'s own doc already warns about.
 *
 * The BEHAVIORAL asymmetries the two old gates encoded are preserved exactly, not merged away —
 * losing either would silently reintroduce a live bug:
 *
 * - `kind: "post"` — eligible whenever the record is `doc`-format, `templateChoice` included.
 *   {@link resolveTemplate} treats `null`/`undefined` as "never chosen" and deliberately falls back
 *   to the theme's first-listed template (see that function's own doc): migration `0028` added
 *   `template_choice` as an additive nullable column with no backfill, so every pre-feature and
 *   externally-inserted Post reads `null`, and "no opinion yet" must render *something* sensible
 *   rather than a diagnostic page. Posts are always `doc`-format (CIC-3, `PostBodyFormat`'s own
 *   doc), so `bodyFormat` needs no separate check for this arm.
 * - `kind: "page"`, `bodyFormat: "doc"` — eligible ONLY when `templateChoice` is a real filename:
 *   not `null`/`undefined`, and — since the owner's 2026-09-23 bare-page ruling described in the next
 *   bullet — not `""` either. The "never chosen → theme's first template" fallback that is safe for
 *   Posts is wrong for Pages: no admin surface set `template_choice` on a `kind: "page"` row before
 *   the Pages template picker shipped, so a Page reading `null` means "an admin surface that didn't
 *   exist yet couldn't have set it", not "no opinion". Falling back would apply a Post-shaped
 *   template to a Page that never asked for one — the live bug this asymmetry fixes: `terms-of-
 *   service`, `privacy-policy`, `contact`, `team`, `faq` rendered under the theme's first template
 *   entry (observed as `<title>Blog post — Basic</title>` on Terms of Service) purely because
 *   `bodyFormat === "doc"` was once the only condition checked, with no `kind` check at all.
 *   `our-story` (`kind: "page"`, `bodyFormat: "doc"`, `templateChoice: "page-shell.html"`, the
 *   proof-of-concept demo row) keeps rendering through this branch under this rule, because its
 *   choice IS explicit.
 * - `kind: "page"`, `bodyFormat: "html"` — same explicit-choice requirement: `""` is ALSO ineligible
 *   here, identically to `null`/`undefined`. Before the owner's 2026-09-23 ruling this was a
 *   documented DIVERGENCE from the `doc`-format Page rule above: a doc-format Page's `""` used to be
 *   eligible (routing to `resolveTemplate`'s diagnostic-page arm, the same as a Post), while an
 *   `"html"`-format Page's `""` was already ineligible (matching `null`), because "no template" was
 *   that format's normal, fully-functional default and a stray dropdown selection shouldn't break an
 *   otherwise-working page. The ruling gave `""` a THIRD, Page-only meaning instead of resolving that
 *   divergence either way: a **bare page** ({@link isBarePageChoice}), serving the Page's own HTML
 *   with no theme chrome at all. A bare Page must never enter this template branch regardless of
 *   which body format it happens to be saved as, which is exactly what retires the divergence — both
 *   formats now agree, and `isPageTemplateChoiceEligible` below no longer even branches on
 *   `bodyFormat`.
 *
 *   CORRECTION (2026-09-02): "fully-functional" above was false for a `static`-tier active theme.
 *   The generic path this arm sends an untemplated `html` Page to (`renderSite`'s
 *   `renderDeclarativeTierBody` -> `fallbackSiteBody` -> `pageShell()`) is Tovu's own built-in demo
 *   chrome, correct for the `declarative`/`templated`/`handlebars` tiers (which have no other shell)
 *   but not a static theme's real document — no `data-theme`, no theme scripts/icons, no real
 *   nav/footer. Live: an agent-authored Page lost the active theme's chrome entirely. This gate's OWN
 *   behavior (never route an unchosen Page into the template branch) is UNCHANGED and stays correct —
 *   what was wrong is the assumption about what the fallback destination looked like. Fixed at that
 *   destination instead of here: see {@link resolveStaticTierPageShellFallback}, consulted by
 *   `renderTemplateBranchIfEligible` (`pages.ts`) only when this gate returns `false`.
 *
 * @complexity O(1) — field comparisons only, no I/O or iteration.
 */
/**
 * The `kind: "page"` half of {@link isEligibleForTemplateBranch} — split out purely to keep that
 * function's own branch count proportional to "which gate applies", not also this gate's own checks.
 *
 * Format-independent since the owner's 2026-09-23 bare-page ruling: `""` is ineligible in BOTH
 * `bodyFormat`s now (a bare Page, see {@link isBarePageChoice}), which retires the doc/html
 * divergence this function used to preserve verbatim — `bodyFormat` is accepted only because callers
 * pass whole records, and is no longer read. See the caller's own doc for the full history.
 */
function isPageTemplateChoiceEligible(post: { bodyFormat: "doc" | "html"; templateChoice?: string | null }): boolean {
  return post.templateChoice !== null && post.templateChoice !== undefined && post.templateChoice !== "";
}

/**
 * Identifies a **bare page** — the owner's 2026-09-23 ruling for `templateChoice: ""` on a
 * `kind: "page"` row: serve the Page's own HTML only, with no theme CSS/JS, header, or footer.
 *
 * Pure, and deliberately checked BEFORE any template-branch gate: `renderTemplateBranchIfEligible`
 * (`routes/site/pages.ts`) must call this first, ahead of the `theme === null` early return and
 * either template-branch gate, because a bare Page renders identically whether or not a theme is even
 * active. {@link isPageTemplateChoiceEligible} and {@link resolveStaticTierPageShellFallback}
 * separately also refuse a bare Page's `""` on their own — belt-and-suspenders, not this predicate's
 * job — so a caller that skips this check still cannot land a bare Page in the template branch or
 * under a static theme's page shell. This predicate exists for the caller that needs to route to the
 * SEPARATE bare-rendering path, not merely to exclude bare Pages from this one.
 *
 * A Post is excluded by construction (`post.kind === "page"`): a Post's `""` keeps its own, unrelated
 * meaning — the diagnostic page, see {@link resolveTemplate} — untouched by this ruling.
 *
 * @param post - The record being rendered. Only `kind` and `templateChoice` are read.
 * @returns `true` only for a `kind: "page"` row whose `templateChoice` is the empty string.
 * @complexity O(1) — two field comparisons, no I/O.
 */
export function isBarePageChoice(post: { kind: "post" | "page"; templateChoice?: string | null }): boolean {
  return post.kind === "page" && post.templateChoice === "";
}

/** The canonical filename(s) `static`-tier themes use for a reusable, content-agnostic document
 *  shell — the same role `"index"` plays for the home route in {@link renderStaticTierHomePage}, just
 *  for any OTHER route. A Tovu-owned convention, not a per-theme manifest choice (see
 *  {@link resolveStaticTierPageShellFallback}'s own doc for why that distinction matters).
 *
 *  ORDERED, new name first: `basic`'s 2026-09-03 rename moved this file from `page-shell.html` to
 *  `pages-default.html`, but `basic-2` — the only other installed static theme that ships this file at
 *  all — still ships it under the OLD name. Both entries are tried, in order, so either theme's real
 *  filename resolves; a COMPATIBILITY SHIM, same removal condition as
 *  {@link LEGACY_TEMPLATE_FILENAME_ALIASES}'s own doc (`resolveTemplate`, above): drop `"page-shell"`
 *  once every currently-installed static theme ships `pages-default.html` instead. */
const STATIC_TIER_PAGE_SHELL_IDS: readonly string[] = ["pages-default", "page-shell"];

/**
 * WIDENED 2026-09-16 to every `kind: "page"` row, not just `"html"`-format ones. The owner's words:
 * "it shouldnt need to be saved to render correctly." A Page is BORN `"doc"`-format — `createPost`
 * forces `(bodyFormat: "doc", bodyHtml: null)` by construction (`features/post/post.ts`'s
 * `resolveBodyFields`, the CIC-3 write chokepoint) for the agent tool and the admin's own "New Page"
 * button alike, and only the first save births the html row. The original `"html"` restriction was
 * therefore not a rule about document shape at all; it was an unstated assumption that every Page
 * reaching here had already been saved once. Measured on a doc-format Page before widening: the live
 * site served a 1231-byte Tovu-generic `pageShell()` with no `data-theme` and no `/theme-assets/` —
 * the EXACT symptom described below, still live for the one shape the fix did not cover.
 *
 * This cannot reopen the `terms-of-service` regression that `isEligibleForTemplateBranch`'s own gate
 * exists to prevent, and the distinction is the whole reason this function is safe to widen: that
 * regression was doc Pages landing on `theme.manifest.templates[0]` — array POSITION, which carries
 * no "this is a page shell" meaning. This function never reads manifest ordering; it looks up a
 * Tovu-owned closed vocabulary ({@link STATIC_TIER_PAGE_SHELL_IDS}) and returns `undefined` when the
 * theme ships neither name, leaving the record on the generic path exactly as before.
 *
 * The 2026-09-02 fix for a live bug: an `html`-format `kind: "page"` row with no explicit
 * `templateChoice` — the state EVERY Page starts in (neither the agent create tool nor the admin
 * Pages editor sets this column on creation; see this repo's `content_post_create` tool and
 * `PageEditor.tsx`'s picker, both of which persist `null`/`""` until an author makes an explicit
 * choice) — is correctly kept OUT of the template branch by {@link isPageTemplateChoiceEligible}. The
 * doc above that gate claims the generic (non-template) path it falls through to is Pages' "normal,
 * fully-functional, default behavior". That claim is true for the `declarative`/`templated`/
 * `handlebars` tiers, where a theme never has a real standalone document of its own — `pageShell()`
 * IS those themes' only shell, template or not. It was FALSE for `static` tier: a static theme's real
 * pages are complete documents (`<html data-theme>`, real `/theme-assets/` scripts, icons, a
 * manifest) that `pageShell()` cannot reproduce — it never sets `data-theme`, never references the
 * theme's own scripts/icons, and only inlines `theme.css`'s raw bytes into a `<style>` tag
 * (`render.ts`'s own `pageShell`). Observed live: an agent-authored Page landed on Tovu's generic
 * `siteHeader`/`siteFooter` markup with zero `/theme-assets/` references and no `data-theme`
 * attribute, instead of the active theme's real chrome.
 *
 * This function restores that claim for `static` tier by giving the generic path a document shell to
 * render into, WITHOUT guessing at the row's intended CONTENT template — the exact distinction that
 * matters against the regression `isEligibleForTemplateBranch`'s own doc records (`resolveTemplate`'s
 * "never chosen -> theme's first template" arm, safe for Posts, put `terms-of-service` et al. under a
 * Post-shaped template's chrome because array position 0 carries no "this is a generic page shell"
 * meaning). This does not read `theme.manifest.templates` or its ordering at all: it looks up one of a
 * small, ORDERED set of canonical, Tovu-owned filenames ({@link STATIC_TIER_PAGE_SHELL_IDS}, new name
 * first) — the same closed-vocabulary lookup `renderStaticTierHomePage` already performs for
 * `"index.html"` on the home route, extended to cover every other route a static theme has no
 * dedicated template for.
 *
 * Most static themes do NOT ship this file. Counted 2026-09-02 (before `basic`'s 2026-09-03
 * posts-* / pages-* rename): of the five installed under `sites/tovu-com/themes/static/`, only `basic`
 * and `basic-2` had `render/pages/page-shell.html` — `tailark-dusk`, `tailark-quartz-dark` and
 * `tailark-quartz-libre` do not, and neither do the seed copies
 * `dist/content/themes/static/{fuel,gracious-timing,portfolite}` nor the pre-migration
 * `content/themes/__original-themes__/static/basic`. After the rename, `basic` ships this file as
 * `pages-default.html` and `basic-2` still ships it as `page-shell.html` — both resolve, in that
 * order, via {@link STATIC_TIER_PAGE_SHELL_IDS}. A theme shipping NEITHER name returns `undefined`
 * here, identical to `resolveTemplate`'s own "theme has no such page" contract, and the caller's
 * pre-existing generic `pageShell()` fallback is unchanged for it — which means switching the active
 * theme to any of the three tailark themes still REOPENS the exact bug described above: an
 * untemplated `html` Page renders in Tovu's generic chrome again, at HTTP 200.
 *
 * That degrade stays deliberate — guessing at some other template is what put `terms-of-service`
 * under a Post-shaped template's chrome, so a miss must remain a no-op rather than a substitution. What it must not
 * remain is SILENT: the miss now emits {@link warnPageShellFallbackMissOnce}'s `[theme] …` warning
 * (this module's existing `console.warn` convention, see `renderStaticPage`), once per distinct
 * message rather than once per request, so the state is visible in the server log instead of being
 * inferable only by eyeballing a rendered page.
 *
 * Scoped to `kind: "page"` + `bodyFormat: "html"` only: `kind: "post"` and `bodyFormat: "doc"` Pages
 * already have their own, unaffected "never chosen" handling (`isPageTemplateChoiceEligible` above)
 * and must keep it — this function is never consulted for either, by construction of its own
 * `post.kind`/`post.bodyFormat` check, not by relying on the caller to gate correctly.
 *
 * @complexity O(n) in the shell template's HTML length for the one `markersOfType` slot check
 *   (identical cost shape to `resolveTemplate`'s own `resolveAgainstTheme`); O(1) otherwise.
 */
/**
 * Miss diagnostics {@link resolveStaticTierPageShellFallback} has already emitted, keyed by the exact
 * message text (which embeds the theme id and the reason), so each distinct miss is reported once per
 * process.
 *
 * De-duplicated where `renderStaticPage`'s two `[theme]` warnings are not, because the two are
 * bounded differently: those fire per page render and a theme has a fixed, small page count, while
 * this one sits on the generic-fallback path taken by EVERY request to EVERY untemplated `html` Page
 * on the site — an unbounded warn would bury its own signal within minutes of real traffic. Bounded
 * by (installed static themes x 2 reasons), so it cannot grow with traffic.
 */
const warnedPageShellFallbackMisses = new Set<string>();

/**
 * Emits a page-shell miss diagnostic at most once per distinct message.
 *
 * @param message - The full `[theme] …` warning text; doubles as the de-duplication key.
 * @returns Nothing. Side effect: one `console.warn`, only on the first call for this message.
 * @complexity O(1) — one `Set` lookup plus at most one insert.
 */
function warnPageShellFallbackMissOnce(message: string): void {
  if (warnedPageShellFallbackMisses.has(message)) return;
  warnedPageShellFallbackMisses.add(message);
  console.warn(message);
}

/** {@link findPageShellCandidate}'s outcome — never more than one usable/slotless id at a time,
 *  since the search stops the moment a usable one is found. */
type PageShellCandidateOutcome = { kind: "usable"; id: string } | { kind: "slotless"; id: string } | { kind: "none" };

/**
 * Walks {@link STATIC_TIER_PAGE_SHELL_IDS} in order and reports the first candidate the theme both
 * SHIPS and can actually use (a real `"content"` slot). When nothing usable turns up, reports the
 * FIRST slotless candidate seen instead (so the caller's miss diagnostic can name the one this
 * function would have preferred), or `{ kind: "none" }` when the theme ships neither candidate at
 * all. Split out of {@link resolveStaticTierPageShellFallback} purely to keep that function's own
 * branch count proportional to "gate, then react to one outcome" rather than also the search's own
 * branching (complexity ceiling).
 *
 * @complexity O(n) in `STATIC_TIER_PAGE_SHELL_IDS.length` (a small, fixed constant) — at most one
 *   `markersOfType` slot check per candidate the theme actually ships.
 */
function findPageShellCandidate(theme: DiscoveredTheme): PageShellCandidateOutcome {
  let slotlessId: string | undefined;
  for (const id of STATIC_TIER_PAGE_SHELL_IDS) {
    const html = theme.pages[id];
    if (html === undefined) continue;
    if (markersOfType({ html: html, type: "content" }).length > 0) return { kind: "usable", id };
    slotlessId ??= id;
  }
  return slotlessId !== undefined ? { kind: "slotless", id: slotlessId } : { kind: "none" };
}

/** The `[theme] …` miss diagnostic for {@link resolveStaticTierPageShellFallback}'s two non-`"usable"`
 *  {@link PageShellCandidateOutcome}s — split out purely to keep that function's own branch count
 *  down; has no side effect of its own, {@link warnPageShellFallbackMissOnce} still owns emitting it. */
function pageShellMissMessage(themeId: string, candidate: { kind: "slotless"; id: string } | { kind: "none" }): string {
  const candidateFilenames = STATIC_TIER_PAGE_SHELL_IDS.map((id) => `${id}.html`);
  const named =
    candidate.kind === "slotless"
      ? `a '${candidate.id}.html' with no {"type":"content"} slot`
      : `none of '${candidateFilenames.join("', '")}'`;
  return `[theme] static theme '${themeId}' ships ${named}; untemplated html Pages render in Tovu's generic chrome instead of this theme's own document`;
}

export function resolveStaticTierPageShellFallback(
  required: {
    theme: DiscoveredTheme;
    post: { kind: "post" | "page"; bodyFormat: "doc" | "html"; templateChoice?: string | null };
  },
  _optional: Record<string, never> = {}
): string | undefined {
  const { theme, post } = required;
  if (theme.manifest.tier !== "static") return undefined;
  // `kind` only — the `bodyFormat === "html"` half of this gate was removed 2026-09-16, see the
  // WIDENED note on this function's own doc. `bodyFormat` is not read at all now, and the parameter
  // keeps it only because callers pass whole records.
  if (post.kind !== "page") return undefined;
  // 2026-09-23: a bare Page (`isBarePageChoice`) never gets a theme's page shell either — the owner's
  // ruling is NO theme chrome for `""`, and a page shell IS theme chrome. `renderTemplateBranchIfEligible`
  // (`routes/site/pages.ts`) already intercepts a bare Page before either gate runs; this check is
  // belt-and-suspenders so a caller that skips that interception still cannot reach a page shell here.
  if (post.templateChoice === "") return undefined;

  const candidate = findPageShellCandidate(theme);
  if (candidate.kind === "usable") return `${candidate.id}.html`;

  warnPageShellFallbackMissOnce(pageShellMissMessage(theme.manifest.id, candidate));
  return undefined;
}

export function isEligibleForTemplateBranch(
  required: {
    theme: DiscoveredTheme;
    post: { kind: "post" | "page"; bodyFormat: "doc" | "html"; templateChoice?: string | null };
  },
  _optional: Record<string, never> = {}
): boolean {
  const { theme, post } = required;
  if (theme.manifest.tier !== "static") return false;

  const templateCount = theme.manifest.templates?.length ?? 0;
  if (templateCount === 0) return false;

  if (post.kind === "post") return true;

  // kind === "page" — no "never chosen" fallback arm, ever (see this function's own doc for why).
  return isPageTemplateChoiceEligible(post);
}

/**
 * {@link resolveTemplateBranchChoice}'s outcome — WHICH template a record actually renders through,
 * once both the eligibility gate and the static-tier page-shell fallback have had their say.
 *
 * - `"as-chosen"` — {@link isEligibleForTemplateBranch} said yes; render the record's own
 *   `templateChoice` unchanged and let {@link resolveTemplate}'s tri-state do the rest.
 * - `"page-shell"` — ineligible, but {@link resolveStaticTierPageShellFallback} found the theme's
 *   canonical page shell. `templateChoice` is the filename to render UNDER, for this render only;
 *   the caller must apply it to a shallow clone and never write it back to the row.
 * - `"ineligible"` — neither applies. The public site falls through to its generic render for this.
 */
export type TemplateBranchChoice =
  | { kind: "as-chosen" }
  | { kind: "page-shell"; templateChoice: string }
  | { kind: "ineligible" };

/**
 * The single answer to "which template does this record render through" — {@link
 * isEligibleForTemplateBranch} and {@link resolveStaticTierPageShellFallback} composed in the one
 * order that is correct, so that no caller has to remember to consult both.
 *
 * Extracted 2026-09-16 from `renderTemplateBranchIfEligible` (`routes/site/pages.ts`), which was the
 * ONLY caller that ran both — the admin template-preview route (`routes/posts/template-preview.ts`)
 * called `renderViaTemplate` directly and so ran NEITHER. For a `kind: "page"`, `bodyFormat: "html"`
 * row with `templateChoice: null` (the state every agent-created and every freshly-saved Page starts
 * in, since no create path writes that column) the two paths therefore disagreed: the public site
 * resolved the page shell while the preview fell through `resolveTemplate`'s "never chosen" arm onto
 * `theme.manifest.templates[0]` — `posts-default.html` on the live `basic` theme. The operator's
 * preview pane showed a Page wearing a blog post's chrome and stylesheet while the public URL served
 * it correctly (owner-observed, `/admin/pages/say-hello`: "the css for the preview wasnt rendering
 * correctly").
 *
 * The fix is this function's EXISTENCE, not its contents: the logic is byte-for-byte what
 * `renderTemplateBranchIfEligible` already did, and the defect was that a second render entry point
 * could reach `renderViaTemplate` without passing through it. Any THIRD entry point must call this,
 * not the two underlying functions in sequence.
 *
 * Deliberately says nothing about what an `"ineligible"` caller should do — the public site has a
 * generic render path to fall to and the admin preview does not, and pretending one answer serves
 * both is how the two drifted apart in the first place.
 *
 * @param required.theme - The active theme, already resolved (never `null` here; a caller with no
 *   theme has nothing to render through and must short-circuit before calling).
 * @param required.post - The record being rendered. Only `kind`, `bodyFormat` and `templateChoice`
 *   are read; a shallow clone carrying a PENDING `templateChoice` (the admin preview's override) is
 *   an intended input, not a misuse.
 * @returns Which template branch applies, per {@link TemplateBranchChoice}.
 * @complexity O(n) in the candidate templates' HTML length for their `"content"` slot checks, over a
 *   small fixed number of candidates; O(1) otherwise. No I/O.
 */
export function resolveTemplateBranchChoice(
  required: {
    theme: DiscoveredTheme;
    post: { kind: "post" | "page"; bodyFormat: "doc" | "html"; templateChoice?: string | null };
  },
  _optional: Record<string, never> = {}
): TemplateBranchChoice {
  const { theme, post } = required;
  if (isEligibleForTemplateBranch({ theme, post })) return { kind: "as-chosen" };

  const pageShell = resolveStaticTierPageShellFallback({ theme, post });
  return pageShell !== undefined ? { kind: "page-shell", templateChoice: pageShell } : { kind: "ineligible" };
}

import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, renameSync, rmSync } from "node:fs";
import { dirname, join, relative } from "node:path";

import { discoverAllBuiltInThemes, THEME_CATALOG_DIR, type ThemeTier } from "./theme.js";
import { isGeneratedThemePath } from "./theme-files.js";

/**
 * @file Generate `__original-themes__` from the shipped themes it is meant to mirror, instead of
 * hand-maintaining it.
 *
 * ---------------------------------------------------------------------------
 * The bug this exists to fix
 * ---------------------------------------------------------------------------
 * `content/themes/__original-themes__/<tier>/<id>` is what "reset to original" restores from
 * (`theme-files.ts`'s `restoreBuiltThemeGeneratedTree`, `explore.ts`'s per-file reset). Nothing
 * connected an edit to a shipped theme with its stored original — it was copied in by hand once and
 * never touched again. `497c9d35` migrated `static/basic` to the v2 folder layout without carrying
 * the change into its original; 16 further commits (WCAG contrast fixes, the observer-threshold fix
 * that un-blanked long pages, Geist vendoring, the PWA icon set) landed on the live theme and none of
 * them touched the original either. `c7ef123d` repaired that ONE theme's data by hand. The other
 * seven of the eight shipped themes had no original at all — not drifted, never created.
 *
 * This module removes the cause: `syncThemeOriginals()` DERIVES `__original-themes__` from the live
 * shipped tree, filtering out the generated-output paths the Explore file list already
 * excludes ({@link isGeneratedThemePath} — `preview/`, a static theme's generated root `index.html`).
 * Run it (`tovu theme sync-originals`) and every shipped theme's original is, by construction, an
 * exact filtered copy of what shipped — nobody maintains it by hand again, and the exclusion cannot
 * silently reopen for a ninth theme added later.
 *
 * ---------------------------------------------------------------------------
 * Scope: the package's own `content/themes/`, never a site
 * ---------------------------------------------------------------------------
 * This is a build-time step against the repo tree, invoked by a maintainer or the release process —
 * never by the running product. It does not reach `<site>/themes/` and must not: a site's copy is
 * meant to diverge from its original (that divergence IS the user's work), and `seedSiteThemes()`
 * already gets a correct, complete catalog to a NEW site for free once this has run once against the
 * package. An already-seeded site is unaffected either way; propagating a package-side update to one
 * is a separate, later question this module deliberately does not answer.
 */

/** One theme's outcome from {@link syncThemeOriginals}. */
export interface SyncThemeOriginalsThemeResult {
  tier: ThemeTier;
  id: string;
}

/** What {@link syncThemeOriginals} did, across every shipped theme it found. */
export interface SyncThemeOriginalsResult {
  themes: SyncThemeOriginalsThemeResult[];
}

/**
 * Name of the sibling staging directory a single theme's generated copy lands in before being
 * renamed into place — same idiom as `seed-site-themes.ts`'s `STAGING_DIR_NAME`, scoped per-theme
 * (suffixed with the theme id) rather than once for the whole tree, so an interrupted run only ever
 * leaves ONE theme's generation incomplete rather than risking every theme's staging output
 * colliding in a shared name.
 */
const STAGING_DIR_PREFIX = ".theme-original-sync-staging-";

/**
 * Copy one theme's live folder into a target directory, filtered to exclude generated output
 * ({@link isGeneratedThemePath}) — the primitive both {@link syncThemeOriginals} and its own test
 * suite build on, and the one this canary re-points at to regenerate-and-diff instead of comparing a
 * tree against itself.
 *
 * Writes to a sibling staging directory first and renames it into place, mirroring
 * `seed-site-themes.ts`'s crash-safety idiom: `targetDir`'s parent never observes a half-written
 * folder under `targetDir`'s own name. Unlike `seedSiteThemes()` this DOES replace an existing
 * `targetDir` — regeneration must mirror `liveDir` exactly, including a file `liveDir` no longer has,
 * so a plain merge-copy onto a pre-existing target would leave a stale file behind. The replace itself
 * (`rmSync` old target, then `renameSync` staging into place) is not one atomic syscall — a crash
 * between those two lines could leave `targetDir` briefly absent — but {@link syncThemeOriginals} only
 * ever runs it against `content/themes/` on a dev/release machine, never a live site, so the failure
 * mode is a dirty `git status` to re-run, not a user-facing loss (see this file's own header). Its one
 * live-site caller, `duplicate-theme.ts` (a theme copy's stored original, 2026-10-08), only ever
 * targets a folder id assignment already proved absent, so that replace never happens there.
 *
 * @param required.liveDir - Absolute path to the shipped theme's live folder to copy from.
 * @param required.targetDir - Absolute path to the original-catalog folder to (re)write.
 * @throws Whatever `node:fs` throws on an unreadable `liveDir` or an unwritable `targetDir` parent.
 * @complexity O(f) in `liveDir`'s file count: one filtered recursive copy, one recursive removal of
 * any pre-existing target, one rename.
 */
export function writeGeneratedThemeOriginal(
  required: { liveDir: string; targetDir: string },
  _optional: Record<string, never> = {}
): void {
  const { liveDir, targetDir } = required;

  const parentDir = dirname(targetDir);
  mkdirSync(parentDir, { recursive: true });
  const stagingDir = join(parentDir, `${STAGING_DIR_PREFIX}${relative(parentDir, targetDir).replaceAll("/", "-")}`);
  // Clears an orphan left by a previous interrupted run — unconditional rather than `existsSync`-guarded
  // for the same reason `seedSiteThemes()` is: `force: true` already makes the absent case a no-op.
  rmSync(stagingDir, { recursive: true, force: true });

  cpSync(liveDir, stagingDir, {
    recursive: true,
    filter: (source: string) => {
      const relativePath = relative(liveDir, source);
      // The root of the copy itself relativizes to "" — always copy it; `isGeneratedThemePath("")`
      // would answer "not generated" anyway (it matches neither a root file nor a generated dir), but
      // being explicit here means this filter never depends on that being true.
      return relativePath === "" || !isGeneratedThemePath(relativePath);
    },
  });

  rmSync(targetDir, { recursive: true, force: true });
  renameSync(stagingDir, targetDir);
}

/**
 * (Re)generate `<themesRoot>/__original-themes__/<tier>/<id>` for every shipped theme discovered
 * under `themesRoot`, from the live shipped copy. Idempotent and safe to run repeatedly: a theme
 * whose live copy has not changed regenerates byte-identical output.
 *
 * Discovery reuses {@link discoverAllBuiltInThemes} (`source: "built-in"`) — the same call every
 * composition root uses — rather than re-walking `themesRoot`'s tiers by hand, so this can never
 * disagree with the product about which folders are real themes (`__original-themes__` is
 * already excluded by that function, and a migration staging leftover is
 * already excluded by name prefix).
 *
 * @param required.themesRoot - A themes root (`content/themes` for the package catalog; a throwaway
 * fixture root in tests). Never a site's `<site>/themes/` — see this file's header.
 * @returns Every theme it (re)generated an original for, in {@link discoverAllBuiltInThemes}'s own
 * id-sorted discovery order.
 * @throws Whatever {@link writeGeneratedThemeOriginal} throws, for the first theme that fails; themes
 * already processed before the failure keep their newly-generated original.
 * @complexity O(t) calls to {@link writeGeneratedThemeOriginal}, t = shipped theme count; O(total
 * shipped bytes) of I/O.
 */
export function syncThemeOriginals(
  required: { themesRoot: string },
  _optional: Record<string, never> = {}
): SyncThemeOriginalsResult {
  const { themesRoot } = required;
  const themes = discoverAllBuiltInThemes({ dir: themesRoot, source: "built-in" });

  const results: SyncThemeOriginalsThemeResult[] = [];
  for (const theme of themes) {
    const tier = theme.manifest.tier;
    const id = theme.manifest.id;
    writeGeneratedThemeOriginal({
      liveDir: theme.dir,
      targetDir: join(themesRoot, THEME_CATALOG_DIR, tier, id),
    });
    results.push({ tier, id });
  }
  return { themes: results };
}

/**
 * Every file under `dir`, as `/`-separated paths relative to it. Shared by {@link syncThemeOriginals}'s
 * own tests and the drift canary so both compare generated output the same way discovery-order issues
 * cannot mask a difference (a missing or extra file, not just a byte mismatch).
 *
 * @param dir - Absolute path to a folder. Returns `[]` for a folder that does not exist, matching
 * "diff against nothing" rather than throwing.
 * @complexity O(f) in `dir`'s entry count — one `readdir` per directory, no file reads.
 */
export function relativeFilePaths(dir: string): string[] {
  if (!existsSync(dir)) return [];
  const walk = (current: string, prefix: string): string[] =>
    readdirSync(current, { withFileTypes: true }).flatMap((entry) => {
      const relativePath = prefix === "" ? entry.name : `${prefix}/${entry.name}`;
      return entry.isDirectory() ? walk(join(current, entry.name), relativePath) : [relativePath];
    });
  return walk(dir, "").sort();
}

/**
 * Whether two folders hold the same set of files with byte-identical contents. Shared by
 * {@link syncThemeOriginals}'s own tests and the drift canary (regenerate-and-diff) for the exact
 * comparison both need: not just "same file list" and not just "same bytes for files present on both
 * sides", but both together, named separately, so a caller reporting a mismatch can say which kind it
 * is.
 *
 * @param aDir - First folder.
 * @param bDir - Second folder.
 * @returns `added` (in `aDir` only), `removed` (in `bDir` only), `changed` (present on both sides with
 * different bytes) — all empty iff the two folders are identical.
 * @complexity O(f) directory-listing calls plus O(bytes shared by both sides) file reads.
 */
export function diffThemeFolders(
  aDir: string,
  bDir: string
): { added: string[]; removed: string[]; changed: string[] } {
  const aPaths = relativeFilePaths(aDir);
  const bPaths = relativeFilePaths(bDir);
  const aSet = new Set(aPaths);
  const bSet = new Set(bPaths);

  const added = aPaths.filter((p) => !bSet.has(p));
  const removed = bPaths.filter((p) => !aSet.has(p));
  const changed = aPaths.filter(
    (p) => bSet.has(p) && !readFileSync(join(aDir, p)).equals(readFileSync(join(bDir, p)))
  );

  return { added, removed, changed };
}

import {
  accessSync,
  chmodSync,
  closeSync,
  constants as fsConstants,
  copyFileSync,
  existsSync,
  lstatSync,
  mkdirSync,
  openSync,
  readdirSync,
  readFileSync,
  readSync,
  realpathSync,
  renameSync,
  rmSync,
  statSync,
  writeFileSync,
  type Stats,
} from "node:fs";
import { randomUUID } from "node:crypto";
import { basename, dirname, isAbsolute, join, relative, resolve, sep } from "node:path";

import { ENGINE_SUBFOLDERS, THEME_CATALOG_DIR, type ThemeManifest } from "./theme.js";
import { resolveThemeLayout } from "./theme-layout.js";

/**
 * @file Path containment and file I/O for the `themes` agent-tool domain
 * (`agent-tools.ts`).
 *
 * Purpose:
 * The `themes` domain exposes a deliberately broad capability — read and write
 * ANY file inside ONE theme's own folder — on the argument that theme content's
 * real safety boundary is the runtime validation every theme goes through
 * regardless of authorship (the Liquid/Handlebars allowlists, worker isolation,
 * the declarative tier's closed JSON vocabulary). That argument holds only for
 * as long as "inside one theme's own folder" is actually true. This module is
 * where that is made true, and it is the only place in the domain that resolves
 * a caller-supplied string into a filesystem path.
 *
 * Why containment is not a string prefix check. The obvious implementation —
 * `resolved.startsWith(themeDir)` — is wrong in three separate ways, each
 * independently exploitable:
 *   1. It admits a SIBLING directory whose name extends the base's:
 *      `themes/handlebars/ledger-evil/x` starts with `themes/handlebars/ledger`.
 *      Comparing against `themeDir + sep` fixes only this one.
 *   2. It compares the wrong string when the input has not been normalized.
 *      `themes/ledger/../../../etc/passwd` must be resolved BEFORE any
 *      comparison, not after.
 *   3. It is blind to symlinks. A `.hbs` file (or a directory) inside the theme
 *      folder that links to `/etc` passes every lexical check ever written,
 *      because lexically it really is inside the folder.
 * {@link resolveThemeFilePath} handles all three: it resolves first, compares
 * with `path.relative` (which cannot be fooled by a name-prefix sibling), and
 * then re-checks against the `realpath` of the deepest ancestor that actually
 * exists on disk — which is what catches a symlink escape for a file that does
 * not exist yet, the case a write must handle.
 *
 * How it relates to the project:
 * Used only by `tool-registrations.ts`'s handlers. Nothing else in the codebase
 * writes theme files at runtime.
 */

/** Thrown for any path that fails containment. Distinct class so the tool layer can map it to a
 * shape rejection (worth publishing the schema back to the model) rather than an internal error. */
export class ThemePathError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ThemePathError";
  }
}

/**
 * Ceiling on one written file, mirroring the Handlebars allowlist's own
 * `MAX_TEMPLATE_SOURCE_BYTES` and the Liquid engine's `parseLimit`. A theme file
 * larger than this is not a theme file.
 */
export const MAX_THEME_FILE_BYTES = 1_000_000;

/** Ceiling on one `theme_list_files` walk, so a pathological folder cannot produce an unbounded response. */
export const MAX_LISTED_FILES = 2_000;

/** Depth ceiling on the same walk — a symlink loop inside a theme folder cannot spin forever. */
export const MAX_WALK_DEPTH = 12;

/**
 * Directories whose contents are GENERATED build output inside a theme-shaped folder — never real
 * source, and never worth copying or listing as editable. `preview/` is `build-preview.mjs`'s output:
 * a full second copy of a theme's pages and scripts, once per color mode — on `novice` (since deleted)
 * that was 36 of 79 listed files, with `js/main.js`, `preview/dark/js/main.js`, and
 * `preview/light/js/main.js` all showing as "main.js" with nothing to distinguish them, burying the
 * ~30 real source files under three-way duplicates of themselves. Editing one is pointless-to-harmful
 * too: the next `build-preview.mjs` run overwrites it, so the change silently disappears.
 *
 * `screenshots/` is deliberately NOT in this list: those are real marketing assets an author may want
 * to look at or replace, not a copy of the theme's own source — excluding them from the Explore list
 * would hide something real, and excluding them from a theme's catalog copy (`__original-themes__`)
 * would make them permanently non-resettable once a user's working copy changed or deleted theirs
 * (that copy is what "reset to original" restores from).
 *
 * The single canonical list — 2026-08-11: this used to be two independent copies, `explore.ts`'s own
 * `GENERATED_DIRS`/`isGenerated` (filtering the Explore file list, given a theme-relative path already
 * in POSIX form) and the theme marketplace's `isGeneratedPreviewPath` (a `cpSync` filter callback,
 * given two ABSOLUTE filesystem paths to relativize itself; deleted 2026-10-04 with the marketplace). Both were answering the identical question —
 * "is this generated preview output" — against the identical directory name, so a third caller would
 * have had to remember to update two places or silently miss one. {@link isGeneratedThemePath} is now
 * that one definition; each caller normalizes its own path shape (already-relative-POSIX for
 * `explore.ts`, `path.relative(root, candidate)` for a `cpSync` filter) into the relative string this expects.
 */
export const GENERATED_THEME_DIRS: readonly string[] = ["preview"];

/**
 * Generated ROOT FILES (as opposed to {@link GENERATED_THEME_DIRS}' whole directories) — same
 * "regenerate the whole thing, never patch it" contract as `preview/`, just a single file instead of a
 * tree. `index.html` (Milestone 5, 2026-08-18) is `static-portability-index.ts`'s own output: a
 * `static`-tier theme's generated portability snapshot, rebuilt from `render/pages/index.html` +
 * `render/partials/*` + `tokens*.json` every time it regenerates, never hand-edited in place — editing
 * it directly is exactly as pointless as editing `preview/`'s output, for the same reason (the next
 * regeneration silently overwrites it).
 */
export const GENERATED_THEME_ROOT_FILES: readonly string[] = ["index.html"];

/**
 * Whether a theme-relative path is inside one of {@link GENERATED_THEME_DIRS} — the bare directory
 * itself (`"preview"`, the shape `cpSync`'s filter callback sees for the directory entry before
 * recursing) or anything under it (`"preview/dark/index.html"`) — or is itself one of
 * {@link GENERATED_THEME_ROOT_FILES} exactly.
 *
 * Deliberately NOT a prefix match on the raw string (`startsWith("preview")`): that would also exclude
 * a merely similarly-named sibling like `preview-notes/`, which is a real author asset with nothing to
 * do with generated output. Matching on the full segment (`=== dir` or `startsWith(dir + "/")`) is what
 * avoids that false positive.
 *
 * `.`/`..` segments are COLLAPSED before comparing (2026-08-13). Without that, this predicate judged
 * the path as literally spelled while `resolveThemeFilePath` — the function that decides which file
 * actually gets written — judged it normalized, so the two disagreed about which file a request names.
 * `PUT {"path":"css/../preview/app.css"}` was accepted (200) and overwrote generated output, walking
 * around the `preview/` rule on EVERY route that consults this predicate. Live-confirmed through the
 * real Express routes before the fix; regression test in `explore-built-theme-gate.test.ts`.
 *
 * A gate and its writer must resolve a name the same way; anything else is a bypass waiting to be
 * spelled differently. `..` popping past the root is left to produce a path that
 * `resolveThemeFilePath`'s own containment check rejects — this function answers only "is it generated".
 *
 * @param relativePath - A path relative to the theme's own root. Backslash-separated input (a raw
 * `path.relative` result on Windows) is normalized to `/` first, so callers on either platform can pass
 * their native separator through unchanged.
 * @returns `true` iff `relativePath`, once normalized, exactly matches a {@link GENERATED_THEME_ROOT_FILES}
 * entry, or is a {@link GENERATED_THEME_DIRS} entry itself or under it.
 * @throws Never. Pure: no filesystem access, no side effects.
 * @complexity Time: O((d+r)·k), d = `GENERATED_THEME_DIRS.length`, r = `GENERATED_THEME_ROOT_FILES.length`
 * (both fixed, tiny constants), k = path length.
 * @complexity Space: O(k) for the normalized copy.
 * @overallScore 100/100
 */
export function isGeneratedThemePath(relativePath: string): boolean {
  const normalized = normalizeThemeRelativePath(relativePath);
  if (GENERATED_THEME_ROOT_FILES.includes(normalized)) return true;
  return GENERATED_THEME_DIRS.some((dir) => normalized === dir || normalized.startsWith(`${dir}/`));
}

/**
 * Whether a compiled theme's declared `build.sourceDir` conflicts with a {@link GENERATED_THEME_DIRS}
 * entry — the install-time half of the two-layer `preview/` defense. {@link isGeneratedThemePath}
 * stops a WRITE that names a generated path; this stops the MANIFEST that would make an entire,
 * ordinary-looking source tree alias generated output, checked by `loadTheme` (`theme.ts`) so a
 * conflicting manifest fails to load at all rather than depending solely on each write route's own
 * `isGeneratedThemePath` refusal (added 2026-08-13 after `PUT {"path":"preview/foo.tsx"}` on a
 * `sourceDir: "preview"` manifest reached disk — see that history in `isGeneratedThemePath`'s doc, and
 * `explore.ts`'s PUT handler for the call-site layer this one is in front of, not a replacement for).
 *
 * Three shapes conflict, because each makes some path indistinguishable as source vs. generated:
 *  1. `sourceDir` names a generated dir exactly (`"preview"`).
 *  2. `sourceDir` is NESTED inside one (`"preview/src"`) — the same "exact segment or a path under it"
 *     shape {@link isGeneratedThemePath} already answers for a file path; reused here for `sourceDir`
 *     rather than re-derived, so a `sourceDir` string and a file path are never judged by two different
 *     rules.
 *  3. `sourceDir` is an ANCESTOR of a generated dir — in practice only the theme root itself (`"."`,
 *     which normalizes to `""`), which would put every {@link GENERATED_THEME_DIRS} entry INSIDE the
 *     declared source tree. An empty `sourceDir` (`""`) is already refused earlier in `loadTheme` as
 *     falsy (`build.sourceDir is required`), so the only shape this adds is a truthy root spelling like
 *     `"."`. Any generated-dir list is non-empty by construction (see that constant's own doc), so a
 *     root `sourceDir` conflicts unconditionally rather than needing a per-entry comparison.
 *
 * `"preview-notes"` — merely PREFIXED with a generated dir's name — must NOT conflict; the per-segment
 * comparison below is what avoids that false positive, exactly as it does for {@link isGeneratedThemePath}.
 *
 * @param sourceDir - `theme.json`'s `build.sourceDir`, as authored (any separator, `./`, `..`).
 * @returns `true` iff normalizing `sourceDir` lands on, inside, or astride any
 * {@link GENERATED_THEME_DIRS} entry.
 * @throws Never. Pure: no filesystem access, no side effects.
 * @complexity Time: O(d·k), d = `GENERATED_THEME_DIRS.length`, k = path length. Space: O(k).
 */
export function isSourceDirGeneratedConflict(sourceDir: string): boolean {
  const normalizedSource = normalizeThemeRelativePath(sourceDir);
  // The root sourceDir case: no per-entry comparison can express "is an ancestor of every entry"
  // via a single startsWith check the way the nested-inside direction can, so it is handled directly.
  if (normalizedSource === "") return true;
  return GENERATED_THEME_DIRS.some(
    (dir) =>
      normalizedSource === dir ||
      normalizedSource.startsWith(`${dir}/`) ||
      dir.startsWith(`${normalizedSource}/`)
  );
}

/**
 * Collapse a theme-relative path to comparable segments: `/` separators, no `.`, no `..`, no empty
 * segments. Shared by every predicate here that compares a path against a directory name, so a gate
 * and the writer it guards cannot disagree about which file a string names.
 *
 * Split on either separator explicitly, not `path.sep` — `sep` is `/` on the POSIX machine this runs
 * on today, which would make the split a no-op for a `\`-separated string instead of normalizing it,
 * silently defeating the cross-platform guarantee these functions' doc comments make.
 */
function normalizeThemeRelativePath(relativePath: string): string {
  const segments: string[] = [];
  for (const segment of relativePath.split(/[\\/]/)) {
    if (segment === "" || segment === ".") continue;
    if (segment === "..") {
      segments.pop();
      continue;
    }
    segments.push(segment);
  }
  return segments.join("/");
}

/**
 * True when `themeDir` is a direct child of the themes root, or of one of the
 * named engine subfolders under it — i.e. exactly the set of locations
 * `discoverAllBuiltInThemes()` scans.
 *
 * This is the SECOND containment question, and it is not implied by the first.
 * `resolveThemeFilePath` proves a file is inside its theme's folder; this proves
 * that folder is somewhere Tovu recognizes as a theme root at all. Without it, a
 * `DiscoveredTheme` fabricated or mutated to carry any other `dir` would grant
 * writes wherever that `dir` pointed.
 *
 * @param required.themeDir - The candidate theme folder (absolute).
 * @param required.themesRoot - The configured themes root (`RouteDeps.themesDir`).
 * @returns Whether the folder sits at a recognized theme root.
 * @complexity O(e) in the engine-subfolder count (a fixed, tiny constant).
 * @overallScore 100/100
 */
export function isRecognizedThemeRoot(
  required: { themeDir: string; themesRoot: string },
  _optional: Record<string, never> = {}
): boolean {
  const root = resolve(required.themesRoot);
  const parent = dirname(resolve(required.themeDir));
  if (parent === root) return true;
  return ENGINE_SUBFOLDERS.some((sub) => parent === join(root, sub));
}

/** Lexical containment: is `target` at or beneath `base`? Uses `path.relative`, which — unlike a
 * prefix match — cannot be satisfied by a sibling whose name merely extends the base's. */
function isWithin(base: string, target: string): boolean {
  if (base === target) return true;
  const rel = relative(base, target);
  return rel !== "" && !rel.startsWith(`..${sep}`) && rel !== ".." && !isAbsolute(rel);
}

/**
 * Walks up from `path` to the deepest existing ancestor, `realpath`s it, and confirms that ancestor
 * is still inside `base` — catches a symlinked directory anywhere along the chain even though the
 * lexical path is clean. `path` need not exist (a write creating a new file).
 *
 * Split out of {@link resolveThemeFilePath} as one unit — the walk-up loop and its containment
 * re-check are one symlink-escape probe, not two independent decisions.
 */
function assertNoSymlinkEscape(base: string, path: string, relativePathForError: string): void {
  let probe = path;
  for (let i = 0; i < MAX_WALK_DEPTH * 4 && !existsSync(probe); i += 1) {
    const parent = dirname(probe);
    if (parent === probe) break;
    probe = parent;
  }
  if (!existsSync(probe)) return;
  const realProbe = realpathSync(probe);
  if (!isWithin(base, realProbe)) {
    throw new ThemePathError(`path '${relativePathForError}' resolves outside the theme folder through a symbolic link`);
  }
}

/**
 * Resolve one caller-supplied relative path against a theme's own folder,
 * refusing anything that escapes it.
 *
 * Rejects, in order: an absolute path, a path with a NUL byte, a path that
 * resolves outside the theme folder (traversal), and a path whose deepest
 * existing ancestor `realpath`s outside the theme folder (symlink escape). The
 * theme folder itself is also re-`realpath`ed first, so a themes root reached
 * through a symlink still compares correctly rather than failing every write.
 *
 * @param required.themeDir - The theme's own folder, as recorded by `loadTheme` (`DiscoveredTheme.dir`).
 * @param required.themesRoot - The configured themes root, for the recognized-root check.
 * @param required.relativePath - The caller-supplied path, relative to the theme folder.
 * @returns The absolute, verified-contained path.
 * @throws {ThemePathError} On any escape or malformed input.
 * @complexity O(d) in the path's directory depth, for the existing-ancestor probe.
 * @overallScore 100/100
 */
export function resolveThemeFilePath(
  required: { themeDir: string; themesRoot: string; relativePath: string },
  _optional: Record<string, never> = {}
): string {
  const { themeDir, themesRoot, relativePath } = required;

  if (!isRecognizedThemeRoot({ themeDir, themesRoot })) {
    throw new ThemePathError(
      `theme folder '${themeDir}' is not under a recognized theme root (${themesRoot} or one of its ${ENGINE_SUBFOLDERS.join("/")} subfolders)`
    );
  }
  if (relativePath.length === 0) {
    throw new ThemePathError("path is required");
  }
  if (relativePath.includes("\0")) {
    throw new ThemePathError("path must not contain a NUL byte");
  }
  if (isAbsolute(relativePath)) {
    throw new ThemePathError(`path '${relativePath}' must be relative to the theme folder, not absolute`);
  }

  // `realpath` the base so a themes root reached through a symlink (a container
  // bind-mount, a dev checkout symlinked into place) compares against the same
  // canonical form the ancestor probe below produces.
  const base = existsSync(themeDir) ? realpathSync(themeDir) : resolve(themeDir);
  const target = resolve(base, relativePath);

  if (!isWithin(base, target)) {
    throw new ThemePathError(`path '${relativePath}' resolves outside the theme folder`);
  }

  // Symlink-aware re-check — the target may not exist (a write creating a new file). See
  // `assertNoSymlinkEscape`'s own doc for what it walks and why.
  assertNoSymlinkEscape(base, target, relativePath);

  return target;
}

/**
 * One directory entry's contribution to {@link walkThemeDir}'s file listing: skip symlinks entirely
 * (neither descended nor reported — see the caller's own header on why a link out of the folder can
 * neither enumerate nor leak anything beyond it), recurse into real subdirectories, and record real
 * files (`found` is mutated in place, the shared accumulator for one `listThemeFiles` call).
 */
function visitThemeDirEntry(dir: string, name: string, depth: number, base: string, found: string[]): void {
  const full = join(dir, name);
  // lstatSync, NEVER statSync — statSync follows the link, so a circular symlink (a -> b -> a) made
  // it throw ELOOP straight out of `listThemeFiles`' own "throws only ThemePathError" contract (this
  // file's JSDoc on that function). lstatSync reports the link itself, never its target, so
  // `isSymbolicLink()` below catches every shape uniformly — normal, broken, or circular — before any
  // call that would follow it, so a symlink is neither descended nor reported as a file. Matches the
  // identical fix in `validation/structure.ts`'s `visitPackageEntry`.
  const stat = lstatSync(full, { throwIfNoEntry: false });
  if (!stat) return;
  if (stat.isSymbolicLink()) return;
  if (stat.isDirectory()) walkThemeDir(full, depth + 1, base, found);
  else if (stat.isFile()) found.push(relative(base, full).split(sep).join("/"));
}

/**
 * Descends real directories under `base` only, collecting relative file paths into `found`
 * (mutated in place), bounded by {@link MAX_WALK_DEPTH} and {@link MAX_LISTED_FILES}. Split from
 * {@link visitThemeDirEntry} so the loop itself carries none of the per-entry branching.
 */
function walkThemeDir(dir: string, depth: number, base: string, found: string[]): void {
  if (depth > MAX_WALK_DEPTH || found.length >= MAX_LISTED_FILES) return;
  for (const name of readdirSync(dir)) {
    if (found.length >= MAX_LISTED_FILES) return;
    visitThemeDirEntry(dir, name, depth, base, found);
  }
}

/**
 * List every regular file under a theme's folder, as paths relative to it.
 *
 * Descends real directories only — a symlinked directory is not followed, so a
 * link out of the folder can neither enumerate nor leak anything beyond it.
 * Bounded by {@link MAX_LISTED_FILES} and {@link MAX_WALK_DEPTH}.
 *
 * @param required.themeDir - The theme's own folder.
 * @param required.themesRoot - The configured themes root, for the recognized-root check.
 * @returns Relative paths, sorted, using `/` separators.
 * @throws {ThemePathError} If the folder is not at a recognized theme root.
 * @complexity O(n) in the file count under the folder.
 * @overallScore 100/100
 */
export function listThemeFiles(
  required: { themeDir: string; themesRoot: string },
  _optional: Record<string, never> = {}
): string[] {
  const { themeDir, themesRoot } = required;
  if (!isRecognizedThemeRoot({ themeDir, themesRoot })) {
    throw new ThemePathError(`theme folder '${themeDir}' is not under a recognized theme root`);
  }
  if (!existsSync(themeDir)) return [];

  const base = realpathSync(themeDir);
  const found: string[] = [];
  walkThemeDir(base, 0, base, found);

  return found.sort();
}

/**
 * `statSync(target, { throwIfNoEntry: false })`, converting circular-symlink `ELOOP` into this
 * module's {@link ThemePathError}. Storage failures such as `EIO` and `EACCES` propagate unchanged,
 * so callers cannot mistake an unreadable original for a missing one. `ELOOP` comes from a circular
 * symlink (`a -> b -> a`) — {@link resolveThemeFilePath}'s own containment check does not resolve this
 * case: its walk-up to find an EXISTING ancestor stops at the theme folder itself, because a
 * self-referential symlink never "exists" by `existsSync`'s own ELOOP-swallowing definition, so it
 * never realpaths the cycle and never throws. Following the link here (rather than `lstat`ing it, the
 * way {@link visitThemeDirEntry}'s listing walk does) is deliberate: a symlink pointing to a real file
 * INSIDE the theme is meant to read through, which `resolveThemeFilePath`'s realpath-based containment
 * check already allows — only the cyclic case needs converting.
 *
 * Return type is `Stats | undefined`, not `ReturnType<typeof statSync>` — `statSync` is overloaded
 * and never called here with `bigint: true`, so the call below can only ever produce a `Stats` (or
 * `undefined` via `throwIfNoEntry: false`); `ReturnType<typeof statSync>` instead resolves against
 * the type's LAST overload (`Stats | BigIntStats | undefined`), which is why callers of this
 * function (`writeFileAtomically`) saw a `bigint` in `existing.mode`'s type that can never actually
 * occur at runtime.
 * @complexity O(1) time and space, with one filesystem stat.
 */
function statOrThemePathError(target: string, relativePath: string, stat: typeof statSync = statSync): Stats | undefined {
  try {
    return stat(target, { throwIfNoEntry: false });
  } catch (err) {
    if ((err as NodeJS.ErrnoException | null)?.code !== "ELOOP") throw err;
    throw new ThemePathError(`path '${relativePath}' could not be read: ${err instanceof Error ? err.message : String(err)}`);
  }
}

/**
 * Read one file inside a theme's folder as UTF-8 text.
 *
 * @throws {ThemePathError} On any containment failure, or when the path is not a regular file.
 * @complexity O(s) in the file size.
 * @overallScore 100/100
 */
export function readThemeFile(
  required: { themeDir: string; themesRoot: string; relativePath: string },
  _optional: Record<string, never> = {}
): string {
  const target = resolveThemeFilePath(required);
  const stat = statOrThemePathError(target, required.relativePath);
  if (!stat) throw new ThemePathError(`file '${required.relativePath}' does not exist in this theme`);
  if (!stat.isFile()) throw new ThemePathError(`path '${required.relativePath}' is not a regular file`);
  if (stat.size > MAX_THEME_FILE_BYTES) {
    throw new ThemePathError(`file '${required.relativePath}' exceeds the ${MAX_THEME_FILE_BYTES}-byte readable limit`);
  }
  return readFileSync(target, "utf8");
}

/** Read size for {@link filesHaveSameBytes}: its memory is two buffers of this size, however large
 *  the files being compared are. */
const COMPARE_CHUNK_BYTES = 64 * 1024;

/** Fills `buffer` from `fd` starting at `position`, looping over short reads. Returns the byte count
 *  that landed, which is below `buffer.length` only at end of file. */
function readFullChunk(fd: number, buffer: Buffer, position: number): number {
  let filled = 0;
  while (filled < buffer.length) {
    const bytesRead = readSync(fd, buffer, filled, buffer.length - filled, position + filled);
    if (bytesRead === 0) break;
    filled += bytesRead;
  }
  return filled;
}

/**
 * Whether the files at `pathA` and `pathB` hold identical bytes, compared chunk by chunk until the
 * first mismatch or end of file. `pathA` is opened first, so an open failure on it is the one thrown.
 *
 * @complexity O(s) time in the file size, O(1) space (two {@link COMPARE_CHUNK_BYTES} buffers).
 */
function filesHaveSameBytes(pathA: string, pathB: string): boolean {
  const fdA = openSync(pathA, "r");
  try {
    const fdB = openSync(pathB, "r");
    try {
      const chunkA = Buffer.allocUnsafe(COMPARE_CHUNK_BYTES);
      const chunkB = Buffer.allocUnsafe(COMPARE_CHUNK_BYTES);
      // A short chunk (readA < COMPARE_CHUNK_BYTES) means end of file: once it compared equal, so are
      // the files. A do/while rather than `for (;;)` with a return inside, so no unreachable
      // fall-through follows the loop.
      let position = 0;
      let readA: number;
      do {
        readA = readFullChunk(fdA, chunkA, position);
        const readB = readFullChunk(fdB, chunkB, position);
        if (readA !== readB || !chunkA.subarray(0, readA).equals(chunkB.subarray(0, readB))) return false;
        position += COMPARE_CHUNK_BYTES;
      } while (readA === COMPARE_CHUNK_BYTES);
      return true;
    } finally {
      closeSync(fdB);
    }
  } finally {
    closeSync(fdA);
  }
}

/**
 * The catalog original's absolute path and size for `relativePath`, or `null` when there is no
 * regular file there to compare against: missing, a directory, or a path that fails containment
 * against the catalog folder. Any containment failure maps to `null` rather than throwing: from the
 * caller's side it means "no original for this path", which `explore.ts`'s per-file reset route
 * reports as `NOT_IN_ORIGINAL` and `theme_reset_file` as `ThemeFileNoOriginalError`.
 */
function originalRegularFile(required: {
  originalDir: string;
  originalsRoot: string;
  relativePath: string;
}): { path: string; size: number } | null {
  try {
    const path = resolveThemeFilePath({
      themeDir: required.originalDir,
      themesRoot: required.originalsRoot,
      relativePath: required.relativePath,
    });
    const stat = statOrThemePathError(path, required.relativePath);
    return stat?.isFile() ? { path, size: stat.size } : null;
  } catch (err) {
    if (err instanceof ThemePathError) return null;
    throw err;
  }
}

/**
 * Whether one file in a theme's live folder differs from its catalog original, byte for byte.
 *
 * Decided from content only, never from mtime. Different sizes answer `true` from the two stats
 * without opening either file; equal sizes always go to a full byte comparison. No line-ending or
 * whitespace normalization: a CRLF-vs-LF difference is a difference.
 *
 * @param required.themeDir - The live theme's own folder (`DiscoveredTheme.dir`).
 * @param required.themesRoot - The configured themes root, for the live side's recognized-root check.
 * @param required.originalDir - The theme's catalog folder (`<themesRoot>/__original-themes__/<tier>/<id>`).
 * @param required.originalsRoot - The catalog root (`<themesRoot>/__original-themes__`).
 * @param required.relativePath - The file, relative to both folders.
 * @returns `null` when the catalog has no regular file at `relativePath` (so there is nothing to
 * compare against, and nothing to reset to). Otherwise `true` when the live file is missing, is not
 * a regular file, or its bytes differ; `false` when the bytes are identical.
 * @throws {ThemePathError} When `relativePath` fails containment against the LIVE folder or names
 * a circular symlink.
 * @throws Filesystem failures from either side's stat or byte comparison (e.g. `EIO` or `EACCES`).
 * @complexity O(1) stats when there is no original or the sizes differ; otherwise O(s) time in the
 * file size and O(1) space.
 */
export function themeFileDiffersFromOriginal(
  required: { themeDir: string; themesRoot: string; originalDir: string; originalsRoot: string; relativePath: string },
  _optional: Record<string, never> = {}
): boolean | null {
  const { themeDir, themesRoot, relativePath } = required;
  const livePath = resolveThemeFilePath({ themeDir, themesRoot, relativePath });
  const original = originalRegularFile(required);
  if (!original) return null;
  const live = statOrThemePathError(livePath, relativePath);
  if (!live?.isFile() || live.size !== original.size) return true;
  return !filesHaveSameBytes(livePath, original.path);
}

/**
 * Replace `target` by filling a sibling temp file in the SAME directory and `renameSync`-ing it over
 * `target`, instead of truncating `target` in place. `fillTemp` creates that temp file at the path it
 * is given: {@link writeThemeFile} writes text there, and {@link resetThemeFileToOriginal} copies a
 * catalog original's bytes there.
 *
 * Why this matters: a plain `writeFileSync(target, …, "w")` truncates `target`'s own inode the
 * instant it opens, before any content lands — a crash or a concurrent reader mid-write can then
 * observe an empty or partial file. For `theme.json`, the file `loadTheme()` must parse whole,
 * that turns one torn write into a broken WHOLE theme. Renaming a fully-written temp file over
 * `target` instead swaps the directory entry atomically: a reader that already has `target` open
 * by descriptor keeps reading the old, complete inode; a reader that opens `target` by path
 * afterward sees either the fully-old or fully-new content, never a partial one.
 *
 * The temp file is a sibling of `target` (same directory), not under a shared system tmp dir,
 * because `renameSync` requires both paths on the SAME filesystem — a cross-device rename throws
 * `EXDEV` instead of renaming.
 *
 * Checks write access on an existing `target` up front: `rename()` only needs write permission on
 * the DIRECTORY, not the destination file, so a bare temp-then-rename would otherwise silently
 * succeed over a read-only target — regressing the permission-denied refusal a `"w"`-flag
 * `writeFileSync` open gave callers before this change. The temp file also inherits `target`'s
 * existing mode before the rename, so replacing a file does not silently change its permissions.
 * When `target` does not exist yet, the new file keeps the mode `fillTemp` created it with.
 *
 * @throws whatever `accessSync`, `fillTemp`, `chmodSync` or `renameSync` throws, or
 * {@link ThemePathError} if the pre-write stat on `target` hits a circular symlink (see
 * {@link statOrThemePathError}). The temp file is removed before the error propagates,
 * so a failed write leaves no artifact behind in the theme folder.
 * @complexity O(s) in the size of what `fillTemp` writes.
 */
function writeFileAtomically(target: string, relativePathForError: string, fillTemp: (tempPath: string) => void, stat: typeof statSync = statSync): void {
  // statOrThemePathError, NEVER a bare statSync — same circular-symlink ELOOP escape the other
  // post-resolve stat calls in this file were fixed for (see that wrapper's own doc). In practice
  // both callers (`writeThemeFile`, `resetThemeFileToOriginal`) already run an identical stat on the
  // same `target` just before and throw first for a circular symlink, so this call is shadowed
  // under ordinary single-process execution; it still guards a genuine TOCTOU window (an external
  // process replacing `target` with a symlink cycle between the two calls) and any future caller
  // that skips that earlier check. Still follows a symlink pointing at a real file inside the theme,
  // matching `renameSync` below, which replaces that symlink's own directory entry.
  const existing = statOrThemePathError(target, relativePathForError, stat);
  if (existing) {
    accessSync(target, fsConstants.W_OK);
  }
  const tempPath = join(dirname(target), `.${basename(target)}.${process.pid}-${randomUUID()}.tmp`);
  try {
    fillTemp(tempPath);
    if (existing) chmodSync(tempPath, existing.mode);
    renameSync(tempPath, target);
  } catch (err) {
    rmSync(tempPath, { force: true });
    throw err;
  }
}

/**
 * Refuses a write over `existing` when it is not a regular file, or when it is past the
 * {@link MAX_THEME_FILE_BYTES} read limit and `overwriteOversized` is false. {@link readThemeFile}
 * refuses a file that size, so a body sent for it was never an edit of its text: checking only the new
 * body's size let a short body replace the whole file. `undefined` (no file yet) always passes.
 *
 * @throws {ThemePathError} On either refusal.
 * @complexity O(1).
 */
function assertOverwritableTarget(existing: Stats | undefined, relativePath: string, overwriteOversized: boolean): void {
  if (!existing) return;
  if (!existing.isFile()) {
    throw new ThemePathError(`path '${relativePath}' exists and is not a regular file`);
  }
  if (existing.size > MAX_THEME_FILE_BYTES && !overwriteOversized) {
    throw new ThemePathError(
      `file '${relativePath}' exceeds the ${MAX_THEME_FILE_BYTES}-byte readable limit; overwriting it requires overwriteOversized: true`
    );
  }
}

/**
 * Write (create or overwrite) one file inside a theme's folder, creating any
 * intermediate directories — which are themselves inside the folder, since the
 * resolved path already passed containment.
 *
 * @param optional.overwriteOversized - Must be `true` to replace an existing file past the
 * {@link MAX_THEME_FILE_BYTES} read limit. The admin editor never sets it.
 * @param optional.stat - Filesystem stat dependency, shared by the pre-check and atomic write.
 * @returns The absolute path written.
 * @throws {ThemePathError} On any containment failure, an oversized body, a
 * target that exists and is not a regular file, or an existing target past the
 * {@link MAX_THEME_FILE_BYTES} read limit without `overwriteOversized`.
 * @complexity O(s) in the content size.
 * @overallScore 100/100
 */
export function writeThemeFile(
  required: { themeDir: string; themesRoot: string; relativePath: string; content: string },
  optional: { overwriteOversized?: boolean; stat?: typeof statSync } = {}
): string {
  const target = resolveThemeFilePath(required);
  if (Buffer.byteLength(required.content, "utf8") > MAX_THEME_FILE_BYTES) {
    throw new ThemePathError(`content exceeds the ${MAX_THEME_FILE_BYTES}-byte per-file limit`);
  }
  // statOrThemePathError, NEVER a bare statSync — same circular-symlink (a -> b -> a) ELOOP escape
  // `readThemeFile` was fixed for (see that wrapper's own doc): `resolveThemeFilePath` does not
  // resolve a `target` that is ITSELF a self-referential symlink, so this is the first call that can
  // observe the cycle. Following the link (rather than `lstat`ing it) is deliberate here too: a
  // symlink pointing to a real file inside the theme is meant to be overwritten through, exactly like
  // any other existing target.
  const existing = statOrThemePathError(target, required.relativePath, optional.stat);
  assertOverwritableTarget(existing, required.relativePath, optional.overwriteOversized === true);
  mkdirSync(dirname(target), { recursive: true });
  writeFileAtomically(target, required.relativePath, (tempPath) => writeFileSync(tempPath, required.content, "utf8"), optional.stat);
  return target;
}

/**
 * Write (create or replace) one BINARY file inside a theme's folder, byte for byte — the
 * `theme_import_file_from_url` half of {@link writeThemeFile}. Same containment, same
 * not-a-regular-file refusal, same atomic temp-and-rename; never decodes. No
 * {@link MAX_THEME_FILE_BYTES} check: that bounds text an agent reads or writes, and the caller
 * has already bounded these bytes (its fetch cap). Replacing an existing file past that limit is
 * allowed for the same reason — a font or image swap is not an edit of unread text.
 *
 * @returns The absolute path written.
 * @throws {ThemePathError} On any containment failure, or a target that exists and is not a regular file.
 * @complexity O(s) in the byte count.
 */
export function writeThemeBinaryFile(
  required: { themeDir: string; themesRoot: string; relativePath: string; bytes: Uint8Array },
  _optional: Record<string, never> = {}
): string {
  const target = resolveThemeFilePath(required);
  const existing = statOrThemePathError(target, required.relativePath, undefined);
  assertOverwritableTarget(existing, required.relativePath, true);
  mkdirSync(dirname(target), { recursive: true });
  writeFileAtomically(target, required.relativePath, (tempPath) => writeFileSync(tempPath, required.bytes), undefined);
  return target;
}

/**
 * Restore one file in a theme's live folder to its catalog original, byte for byte.
 *
 * Never decodes either file. The original is copied with `copyFileSync` into a temp file that
 * {@link writeFileAtomically} renames over the live path, so a binary asset (an image, a font) comes
 * back exactly and then compares unmodified in {@link themeFileDiffersFromOriginal}. Going through
 * {@link readThemeFile}/{@link writeThemeFile} instead would decode via UTF-8 and turn every invalid
 * byte into U+FFFD. There is no {@link MAX_THEME_FILE_BYTES} ceiling here for the same reason: that
 * limit bounds text a caller reads or writes, and a reset carries no text.
 *
 * A live file whose bytes already match is not written at all. A missing live file is recreated,
 * along with any missing parent folders, and takes the original's mode (`copyFileSync` copies it).
 * An existing live file keeps its own mode.
 *
 * @param required.themeDir - The live theme's own folder (`DiscoveredTheme.dir`).
 * @param required.themesRoot - The configured themes root, for the live side's recognized-root check.
 * @param required.originalDir - The theme's catalog folder (`<themesRoot>/__original-themes__/<tier>/<id>`).
 * @param required.originalsRoot - The catalog root (`<themesRoot>/__original-themes__`).
 * @param required.relativePath - The file, relative to both folders.
 * @returns `null` when the catalog has no regular file at `relativePath`. That is checked before the
 * live side is resolved, so nothing is touched. Otherwise `bytes` is the original's size, and
 * `wasModified` is `false` when the live bytes already matched (nothing written) or `true` after the
 * copy.
 * @throws {ThemePathError} When `relativePath` fails containment against the LIVE folder, or the live
 * path exists and is not a regular file.
 * @throws Whatever `openSync`/`readSync`/`accessSync`/`copyFileSync`/`chmodSync`/`renameSync` throw,
 * e.g. `EACCES` for an unreadable original or a read-only live file. A failed copy leaves no temp
 * file behind.
 * @complexity O(s) time in the file size, for the comparison and the copy; O(1) space in this process.
 */
export function resetThemeFileToOriginal(
  required: { themeDir: string; themesRoot: string; originalDir: string; originalsRoot: string; relativePath: string },
  _optional: Record<string, never> = {}
): { wasModified: boolean; bytes: number } | null {
  const { themeDir, themesRoot, relativePath } = required;
  const original = originalRegularFile(required);
  if (!original) return null;
  const target = resolveThemeFilePath({ themeDir, themesRoot, relativePath });
  const live = statOrThemePathError(target, relativePath);
  if (live && !live.isFile()) {
    throw new ThemePathError(`path '${relativePath}' exists and is not a regular file`);
  }
  if (live?.size === original.size && filesHaveSameBytes(target, original.path)) {
    return { wasModified: false, bytes: original.size };
  }
  mkdirSync(dirname(target), { recursive: true });
  writeFileAtomically(target, relativePath, (tempPath) => copyFileSync(original.path, tempPath));
  return { wasModified: true, bytes: original.size };
}

/**
 * Design C (ADS-memory w4-theme-lifecycle-designs.md §5 / w6 dispatch, 2026-09-16): which folder
 * `resetThemeFileToOriginal`/`themeFileDiffersFromOriginal`/`themeOriginalResetRefusal` should treat
 * as one theme's catalog original, and where that folder came from. `"site"` is today's ONLY source
 * (`<siteThemesRoot>/__original-themes__/<tier>/<id>`) and always wins when it exists at all —
 * `"package"` (`<packageThemesRoot>/__original-themes__/<tier>/<id>`) is a READ-ONLY fallback,
 * reached only when the site has no catalog folder for this theme whatsoever. See
 * {@link resolveThemeOriginalSource}.
 */
export type ThemeOriginalSource = {
  readonly source: "site" | "package";
  readonly originalDir: string;
  readonly originalsRoot: string;
};

/**
 * Resolve which catalog original a theme should reset against/compare against: the site's own copy
 * when it exists at all, or — only when the site has none — the package's own read-only copy.
 *
 * This is Design C's entire mechanism. Before this, every caller (`explore.ts`'s detail/copy/rename/
 * reset routes, `tool-registrations.ts`'s `theme_reset_file`) derived
 * `join(siteThemesRoot, THEME_CATALOG_DIR, tier, id)` directly and asked only whether THAT folder
 * exists. Seven of the eight shipped themes never had one on an already-seeded site (Design D fixed
 * this for NEW sites by generating `content/themes/__original-themes__/<tier>/<id>` for all eight at
 * build time; an already-seeded site's own copy, made once at `seedSiteThemes()` time, never gets
 * the backfill). This function adds exactly one more place to look — the package's own generated
 * catalog — without writing anything anywhere: both branches are `existsSync` on a directory, never a
 * copy, a rename, or a stamp. A site's own original is therefore never displaced, only supplemented
 * by a fallback that answers `null` today's `catalogDir`-then-`existsSync` shape already answered
 * `null` for.
 *
 * `packageThemesRoot` is deliberately `string | undefined`, not required: only the SQLite composition
 * root (`server/deps.ts`'s `createSiteRouteDeps`) and the CLI install-dir boot know the package's
 * own themes root at all (`builtInThemesDir()`) — the hermetic in-memory composition root
 * (`server/app.ts`'s `createRouteDeps`) and every hand-built `RouteDeps`/`ContentRouteDeps`/
 * `ThemeToolDeps` test fixture predate this field and have no reason to set it. `undefined` is
 * therefore "no package fallback configured," answered the same as "the package has no original for
 * this theme id" (`null`), never thrown.
 *
 * @param required.manifest - Supplies the theme's own `tier`/`id` — where each catalog stores its
 * per-theme folder, on either side.
 * @param required.siteThemesRoot - The site's own themes root (`RouteDeps.themesDir`), checked first.
 * @param required.packageThemesRoot - The package's own stock themes root
 * (`RouteDeps.packageThemesDir`, ultimately `builtInThemesDir()`), or `undefined`.
 * @returns `null` when neither side has a catalog folder for this theme id — identical to today's
 * "no original" state. Otherwise the folder to read from and which side answered: `"package"` is
 * returned only when `"site"` would have been `null`.
 * @throws Never. Two `existsSync` calls, no reads, no writes.
 * @complexity O(1).
 */
export function resolveThemeOriginalSource(
  required: {
    manifest: Pick<ThemeManifest, "tier" | "id">;
    siteThemesRoot: string;
    packageThemesRoot: string | undefined;
  },
  _optional: Record<string, never> = {}
): ThemeOriginalSource | null {
  const { manifest, siteThemesRoot, packageThemesRoot } = required;

  const siteOriginalsRoot = join(siteThemesRoot, THEME_CATALOG_DIR);
  const siteOriginalDir = join(siteOriginalsRoot, manifest.tier, manifest.id);
  if (existsSync(siteOriginalDir)) {
    return { source: "site", originalDir: siteOriginalDir, originalsRoot: siteOriginalsRoot };
  }

  if (packageThemesRoot === undefined) return null;
  const packageOriginalsRoot = join(packageThemesRoot, THEME_CATALOG_DIR);
  const packageOriginalDir = join(packageOriginalsRoot, manifest.tier, manifest.id);
  if (existsSync(packageOriginalDir)) {
    return { source: "package", originalDir: packageOriginalDir, originalsRoot: packageOriginalsRoot };
  }

  return null;
}

/**
 * Whether this theme id ships with the package itself — the package's own generated originals
 * catalog has a folder for it. The Themes screen keeps such a theme out of its Delete menu item.
 *
 * Deliberately the PACKAGE catalog only, not {@link resolveThemeOriginalSource}'s site-first lookup:
 * a Duplicate writes the copy's own site original (`duplicate-theme.ts`), so "has an original" is
 * true for every copy and cannot tell a shipped theme from the owner's own.
 *
 * @returns `false` when `packageThemesRoot` is `undefined` (no package fallback configured — see
 *   {@link resolveThemeOriginalSource}'s doc) or the catalog has no folder for this tier/id.
 * @throws Never. One `existsSync`.
 * @complexity O(1).
 */
export function isPackageShippedTheme(
  required: { manifest: Pick<ThemeManifest, "tier" | "id">; packageThemesRoot: string | undefined },
  _optional: Record<string, never> = {}
): boolean {
  const { manifest, packageThemesRoot } = required;
  if (packageThemesRoot === undefined) return false;
  return existsSync(join(packageThemesRoot, THEME_CATALOG_DIR, manifest.tier, manifest.id));
}

/** {@link themeOriginalResetRefusal}'s refusal: a stable `code` for a client to translate, and a fixed
 *  English `message` with nothing interpolated into it. */
export type ThemeOriginalResetRefusal = { readonly code: "ORIGINAL_LAYOUT_MISMATCH"; readonly message: string };

const ORIGINAL_LAYOUT_MISMATCH_REFUSAL: ThemeOriginalResetRefusal = Object.freeze({
  code: "ORIGINAL_LAYOUT_MISMATCH",
  message: "this theme's saved original does not match its current layout, so its files cannot be reset",
});

/**
 * The layout version one theme folder's own `theme.json` declares: `2`, or `undefined` for v1, the
 * same normalization `loadTheme` applies (`theme.ts`, `parseRawManifestFields`). `null` when the
 * manifest is missing, is not a regular file, is past {@link MAX_THEME_FILE_BYTES}, cannot be read, or
 * is not a JSON object. Never throws.
 *
 * @complexity O(s) in the manifest size, bounded by {@link MAX_THEME_FILE_BYTES}.
 */
function manifestApiVersionOnDisk(themeDir: string): 2 | undefined | null {
  const manifestPath = join(themeDir, "theme.json");
  try {
    const stat = statSync(manifestPath);
    if (!stat.isFile() || stat.size > MAX_THEME_FILE_BYTES) return null;
    const raw: unknown = JSON.parse(readFileSync(manifestPath, "utf8"));
    if (typeof raw !== "object" || raw === null || Array.isArray(raw)) return null;
    return (raw as { apiVersion?: unknown }).apiVersion === 2 ? 2 : undefined;
  } catch {
    return null;
  }
}

/**
 * The one guard both per-file resets share (`explore.ts`'s reset route and `theme_reset_file`), and
 * what the Explore listing uses to decide `resettable`. Refuses when a theme's catalog original cannot
 * stand in for the live theme file by file: its `theme.json` resolves a different layout
 * (`theme-layout.ts`) than the live one, or cannot be read, so its layout is unknown.
 *
 * The refusal covers every file, not only `theme.json`. Copying a v1 original's `theme.json` over a v2
 * theme writes a manifest with no `apiVersion`, and `loadTheme` then requires v1's `pages/index.html`
 * and marks the theme invalid; copying any other file mixes one layout's file into the other. Found on
 * `basic`, 2026-09-14, whose saved original is still the layout from before `497c9d35`.
 *
 * An unreadable LIVE `theme.json` does not refuse: that theme already loads invalid, and resetting the
 * file from its original is how it gets repaired.
 *
 * Both manifests are read from disk on every call rather than taken from `DiscoveredTheme.manifest`.
 * That snapshot is stale whenever another process wrote the theme, and has no `apiVersion` at all when
 * the live manifest failed to parse.
 *
 * @param required.themeDir - The live theme's own folder (`DiscoveredTheme.dir`).
 * @param required.originalDir - The theme's catalog folder (`<themesRoot>/__original-themes__/<tier>/<id>`).
 * @returns `null` when a per-file reset may go ahead; otherwise the refusal.
 * @complexity O(s) in the two manifests' sizes, each bounded by {@link MAX_THEME_FILE_BYTES}.
 */
export function themeOriginalResetRefusal(
  required: { themeDir: string; originalDir: string },
  _optional: Record<string, never> = {}
): ThemeOriginalResetRefusal | null {
  const original = manifestApiVersionOnDisk(required.originalDir);
  if (original !== null) {
    const live = manifestApiVersionOnDisk(required.themeDir);
    if (live === null || resolveThemeLayout(live) === resolveThemeLayout(original)) return null;
  }
  return ORIGINAL_LAYOUT_MISMATCH_REFUSAL;
}

/**
 * Shared containment + preflight for {@link copyThemeFile}/{@link renameThemeFile}: resolves both
 * the source and destination through {@link resolveThemeFilePath} (so a destination built from
 * operator input — a rename's new filename — is validated exactly as strictly as a write target),
 * confirms the source is a regular file, and refuses to clobber an existing destination.
 *
 * Deliberately does NOT decode either path through `readFileSync(…, "utf8")` /
 * `writeFileSync(…, "utf8")` the way {@link readThemeFile}/{@link writeThemeFile} do: a binary asset
 * (a font, an image) round-tripped through UTF-8 would come back byte-corrupted, and copy/rename
 * must work on every file in a theme's folder, not only the text-editable ones. For the same reason
 * there is no {@link MAX_THEME_FILE_BYTES} ceiling here, as in {@link resetThemeFileToOriginal}: that
 * limit bounds text a caller reads or writes, and copy/rename carry no text.
 */
function resolveCopyOrRenameTargets(
  required: { themeDir: string; themesRoot: string; sourcePath: string; destPath: string }
): { source: string; dest: string } {
  const { themeDir, themesRoot, sourcePath, destPath } = required;
  const source = resolveThemeFilePath({ themeDir, themesRoot, relativePath: sourcePath });
  // statOrThemePathError, NEVER a bare statSync — same circular-symlink ELOOP escape the other
  // post-resolve stat calls in this file were fixed for (see statOrThemePathError's own doc):
  // `resolveThemeFilePath` does not resolve a `source` that is ITSELF a self-referential symlink, so
  // this is the first call that can observe the cycle. Still follows a symlink pointing at a real
  // file inside the theme — `copyFileSync`/`renameSync` below already read/move through such a link
  // the same way `open()` does, so this check must match that, not refuse it.
  const sourceStat = statOrThemePathError(source, sourcePath);
  if (!sourceStat) throw new ThemePathError(`file '${sourcePath}' does not exist in this theme`);
  if (!sourceStat.isFile()) throw new ThemePathError(`path '${sourcePath}' is not a regular file`);

  const dest = resolveThemeFilePath({ themeDir, themesRoot, relativePath: destPath });
  if (existsSync(dest)) {
    throw new ThemePathError(`path '${destPath}' already exists in this theme`);
  }

  return { source, dest };
}

/**
 * Duplicate one file inside a theme's folder to a new path also inside it, byte-for-byte.
 *
 * @param optional.copyFile - The exclusive copy primitive; defaults to `node:fs` `copyFileSync`.
 *   A seam so the lost-race (`EEXIST`) mapping below is testable without a real concurrent copy.
 * @returns The absolute destination path written.
 * @throws {ThemePathError} On containment failure for either path, a missing/non-file source, or a
 * destination that already exists. There is no size limit.
 * @complexity O(s) in the file size.
 * @overallScore 100/100
 */
export function copyThemeFile(
  required: { themeDir: string; themesRoot: string; sourcePath: string; destPath: string },
  optional: { copyFile?: typeof copyFileSync } = {}
): string {
  const { copyFile = copyFileSync } = optional;
  const { source, dest } = resolveCopyOrRenameTargets(required);
  mkdirSync(dirname(dest), { recursive: true });
  try {
    // `COPYFILE_EXCL` closes the TOCTOU window `resolveCopyOrRenameTargets`' own `existsSync(dest)`
    // check leaves open: two concurrent copy requests both landing on the same auto-suffixed name
    // (e.g. two rapid clicks generating `about-1.html` from the same source) would otherwise both
    // pass that pre-check and race to overwrite one another. `copyFileSync` has an atomic
    // exclusive-write mode for exactly this; `renameSync` (below) does not, so the identical race is
    // a known, narrower, accepted gap there — this domain is a single authenticated operator's admin
    // tool, not a multi-tenant race target, and every other write in this file already accepts the
    // same class of risk (`writeThemeFile` has no equivalent guard at all).
    copyFile(source, dest, fsConstants.COPYFILE_EXCL);
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "EEXIST") {
      throw new ThemePathError(`path '${required.destPath}' already exists in this theme`);
    }
    throw err;
  }
  return dest;
}

/**
 * Suffix a caller-desired relative path to avoid colliding with anything already in `existingPaths`,
 * following the same `name`, `name-1`, `name-2` … shape `nextAvailableThemeId` (`theme.ts`) uses for
 * theme ids — but split around the extension, since a theme id (`basic`) is a bare folder name with
 * no extension to preserve, while a file path (`pages/about.html`) needs `about-1.html`, not
 * `about.html-1`. That shape difference is why this is its own small function instead of a direct
 * call into `nextAvailableThemeId`: the collision LOOP is identical, the thing being suffixed is not.
 *
 * Moved here from `explore.ts` (2026-09-12) so `tool-registrations.ts`'s `theme_copy_file` agent tool
 * can call the exact same collision-avoidance the HTTP copy route uses, without a
 * `features/theme` -> `server/**` import — the identical reason `validateFileIdentityChange` moved
 * to `file-identity-lock.ts` on 2026-08-30 (see that module's own header). `explore.ts` re-exports
 * this definition rather than defining its own, so its existing callers and tests are unchanged.
 *
 * @complexity O(n) in the number of existing collisions with the desired name.
 * @overallScore 100/100
 */
export function nextAvailableFileName(
  required: { desiredPath: string; existingPaths: ReadonlySet<string> },
  _optional: Record<string, never> = {}
): string {
  const { desiredPath, existingPaths } = required;
  const slash = desiredPath.lastIndexOf("/");
  const dot = desiredPath.lastIndexOf(".");
  // A dot has to fall AFTER the last slash to be the filename's own extension — otherwise it belongs
  // to a directory segment (not a real case in this theme layout, but cheap to get right).
  const hasExt = dot > slash;
  const base = hasExt ? desiredPath.slice(0, dot) : desiredPath;
  const ext = hasExt ? desiredPath.slice(dot) : "";

  if (!existingPaths.has(desiredPath)) return desiredPath;
  let suffix = 1;
  let candidate = `${base}-${suffix}${ext}`;
  while (existingPaths.has(candidate)) {
    suffix += 1;
    candidate = `${base}-${suffix}${ext}`;
  }
  return candidate;
}

/**
 * Move (rename) one file within a theme's folder, byte-for-byte.
 *
 * @returns The absolute destination path.
 * @throws {ThemePathError} On containment failure for either path, a missing/non-file source, or a
 * destination that already exists. There is no size limit.
 * @complexity O(1) — same-filesystem rename, not a copy.
 * @overallScore 100/100
 */
export function renameThemeFile(
  required: { themeDir: string; themesRoot: string; sourcePath: string; destPath: string },
  _optional: Record<string, never> = {}
): string {
  const { source, dest } = resolveCopyOrRenameTargets(required);
  mkdirSync(dirname(dest), { recursive: true });
  renameSync(source, dest);
  return dest;
}

/**
 * Delete one file inside a theme's folder.
 *
 * Callers are expected to have already decided this delete is SAFE to perform — required-file,
 * generated-tree, and identity-lock checks live one layer up ({@link resolveThemeFileWriteScope}, and
 * `explore.ts`'s own `validateFileIdentityChange`, shared with {@link renameThemeFile}'s own route).
 * This function only enforces the one thing every write in this file enforces: containment. There is
 * no recovery path if a caller got that wrong — this repo keeps no theme-file revision history, so a
 * deleted file is gone until it is re-authored, or (for a file with a catalog original) reset from
 * there before it was deleted, which is no longer possible once the path itself does not exist.
 *
 * @throws {ThemePathError} On containment failure, a missing target, or a target that is not a
 * regular file — deleting a directory through this path is refused, not attempted.
 * @complexity O(1) — a single `rmSync`.
 * @overallScore 100/100
 */
export function deleteThemeFile(
  required: { themeDir: string; themesRoot: string; relativePath: string },
  _optional: Record<string, never> = {}
): void {
  const target = resolveThemeFilePath(required);
  // statOrThemePathError, NEVER a bare statSync — same circular-symlink ELOOP escape `readThemeFile`
  // and `writeThemeFile` were fixed for (see statOrThemePathError's own doc): `resolveThemeFilePath`
  // does not resolve a `target` that is ITSELF a self-referential symlink, so this is the first call
  // that can observe the cycle. Still follows a symlink pointing at a real file inside the theme — the
  // delete then removes that symlink's own directory entry via `rmSync` below, same as deleting any
  // other existing target.
  const stat = statOrThemePathError(target, required.relativePath);
  if (!stat) throw new ThemePathError(`file '${required.relativePath}' does not exist in this theme`);
  if (!stat.isFile()) throw new ThemePathError(`path '${required.relativePath}' is not a regular file`);
  rmSync(target);
}

/**
 * Whether one path resolves to a BUILT theme's generated tree — read-only from every per-file surface
 * — or to a location that stays editable (ADR-020 §5, `ThemeBuildInfo`'s own doc: "a built theme's
 * source keeps per-file reset and AI-authorability; only its generated tree loses granularity").
 *
 * `"editable"` for every theme on disk today (`manifest.build?.source !== "compiled"` — every theme is
 * `authored`, unchanged). For a COMPILED theme, `"editable"` is narrowed to exactly two things: `
 * theme.json` itself (the one file a compiled theme still needs to keep editing — author, lineage —
 * without touching generated output), and anything under `manifest.build.sourceDir`, which is real,
 * hand-authored source with no cross-file desync risk an editable file doesn't already carry on its
 * own. Everything else is `"generated-readonly"`: one `pages/index.html` edited or reset in isolation
 * from the same build's `js/main.js` would desync the release from what `build.artifactHashes` actually
 * verifies (`build-conformance.ts`), so the generated tree is never mutated file-by-file — it is
 * restored, when it is, only as one complete, re-verified release.
 *
 * A compiled theme declaring no `sourceDir` has no editable region here at all beyond `theme.json` —
 * `loadTheme`'s own manifest-shape validation already flags such a theme `invalid` (`sourceDir` is
 * REQUIRED when `build.source` is `"compiled"`), so this function does not need to guess a fallback
 * convention like `src/` a real author's build might not even use.
 *
 * This is a PURE policy decision, not itself a containment check — callers still resolve
 * `relativePath` through {@link resolveThemeFilePath} before touching the filesystem; this only
 * answers "is this write/reset allowed at all for this theme's lifecycle class."
 */
export type ThemeFileWriteScope =
  | { readonly kind: "editable" }
  | { readonly kind: "generated-readonly"; readonly reason: string };

export function resolveThemeFileWriteScope(
  required: { manifest: Pick<ThemeManifest, "build">; relativePath: string },
  _optional: Record<string, never> = {}
): ThemeFileWriteScope {
  const { manifest, relativePath } = required;
  if (manifest.build?.source !== "compiled") return { kind: "editable" };

  // Normalized (not raw) for the same reason `isGeneratedThemePath` is — see its doc. Comparing the
  // path as spelled let `src/../pages/index.html` match the `sourceDir` prefix and resolve "editable",
  // handing back write permission on a built theme's GENERATED tree, which is the ADR-020 §5 refusal
  // this function exists to make.
  const normalized = normalizeThemeRelativePath(relativePath);
  if (normalized === "theme.json") return { kind: "editable" };

  const sourceDir = manifest.build.sourceDir;
  if (sourceDir !== undefined && (normalized === sourceDir || normalized.startsWith(`${sourceDir}/`))) {
    return { kind: "editable" };
  }

  return {
    kind: "generated-readonly",
    reason:
      "this file is generated output of a built theme (theme.json build.source: 'compiled'); it is versioned and restored only as one complete release, never edited or reset file-by-file — edit the source under build.sourceDir and rebuild instead",
  };
}

/**
 * Restore a BUILT theme's entire generated tree — every path {@link resolveThemeFileWriteScope}
 * classifies `generated-readonly` for this manifest — from its catalog original, as one operation.
 * Never partial: every existing generated file is removed first, then every catalog generated file is
 * recopied, so the live tree ends up an EXACT copy of the catalog's generated output rather than a
 * merge of old and new. `theme.json` and everything under `build.sourceDir` are untouched — this
 * restores only the region {@link resolveThemeFileWriteScope} already refuses to write, the other half
 * of ADR-020 §5's "restored atomically" (per-file reset still covers the source, unchanged).
 *
 * "One operation" here means indivisible from the CALLER's perspective — enumerate both sides fully
 * before mutating anything — not an OS-level transaction; a crash mid-restore can still leave a
 * partial tree, the same caveat every other multi-file write in this codebase already accepts.
 *
 * Reuses {@link listThemeFiles}'s walk for both sides (live and catalog) rather than a second directory
 * walker: `THEME_CATALOG_DIR`'s own layout mirrors a real themes root's `<tier>/<id>/` shape (see that
 * constant's doc), so `listThemeFiles({ themeDir: catalogDir, themesRoot: catalogRoot })` passes the
 * same recognized-root check a live theme's call does, and inherits the same symlink-refusing,
 * bounded walk for free.
 *
 * @throws {ThemePathError} If this theme is not a compiled build (nothing to restore — every file
 * already resets per-file), or has no catalog original to restore from at all.
 * @complexity O(f) in the theme's own generated file count — two bounded directory walks plus one
 * `rmSync`/`copyFileSync` per generated file.
 */
export function restoreBuiltThemeGeneratedTree(
  required: { themeDir: string; themesRoot: string; manifest: Pick<ThemeManifest, "id" | "tier" | "build"> },
  _optional: Record<string, never> = {}
): { restoredFiles: string[] } {
  const { themeDir, themesRoot, manifest } = required;
  if (manifest.build?.source !== "compiled") {
    throw new ThemePathError("this theme is not a built release; there is no generated tree to restore");
  }

  const catalogDir = join(themesRoot, THEME_CATALOG_DIR, manifest.tier, manifest.id);
  if (!existsSync(catalogDir)) {
    throw new ThemePathError(`theme '${manifest.id}' has no stored original, so its generated tree cannot be restored`);
  }

  const isGenerated = (relativePath: string): boolean =>
    resolveThemeFileWriteScope({ manifest, relativePath }).kind === "generated-readonly";

  // Enumerate both sides fully before touching disk, so a read failure on either side aborts before
  // any file is removed.
  const liveGenerated = listThemeFiles({ themeDir, themesRoot }).filter(isGenerated);
  const catalogRoot = join(themesRoot, THEME_CATALOG_DIR);
  const catalogGenerated = listThemeFiles({ themeDir: catalogDir, themesRoot: catalogRoot }).filter(isGenerated);

  for (const relativePath of liveGenerated) {
    rmSync(join(themeDir, relativePath), { force: true });
  }
  for (const relativePath of catalogGenerated) {
    const dest = join(themeDir, relativePath);
    mkdirSync(dirname(dest), { recursive: true });
    copyFileSync(join(catalogDir, relativePath), dest);
  }

  return { restoredFiles: catalogGenerated.sort() };
}

import { existsSync, mkdirSync, readdirSync } from "node:fs";
import type { rename } from "node:fs/promises";
import { basename, dirname, join, relative, resolve } from "node:path";

import type { TrashAdapter, TrashMarkerResult } from "@jini-ai/cms/trash";

import { createDirectoryTrashAdapter, THEME_ENTITY_TYPE, type DirectoryTrashLocation } from "#src/features/trash/index";

import { requestThemePreviewRefresh } from "./preview-refresh.js";
import { ENGINE_SUBFOLDERS, findTheme, rescanThemes, THEME_CATALOG_DIR, type DiscoveredTheme } from "./theme.js";

/**
 * @file Where a whole theme folder goes when it is moved to the Trash, and the Trash adapter built on
 * it (2026-10-08, owner: the agent could not delete a theme at all).
 *
 * A theme is a folder, so it reuses the generic directory adapter `plugin` already uses
 * (`features/trash/adapters/directory.ts`): one atomic rename out of the site's `themes/` into a
 * sibling `themes-trash/`, one rename back on restore, and bytes removed only by the Trash's own
 * human-confirmed purge. Nothing here deletes anything.
 *
 * The parking path keeps the engine subfolder (`static/`, `templated/`, ...) the theme was discovered
 * under — `<themes>-trash/static/nordic/nordic` — because once the folder has left `themes/`, discovery
 * no longer knows where it came from, and restore must put it back in the same place.
 *
 * The theme's stored original (`__original-themes__/<tier>/<id>`, what Reset restores from) travels
 * with it (owner 2026-10-08): parked at `<themes>-trash/__original-themes__/<tier>/<id>/<id>` on
 * trash, put back on restore, removed by purge — a trashed theme leaves no orphan original behind,
 * and a restored one can still be reset. Every other original is untouched; no discovered theme's
 * folder can resolve into the catalog, which discovery excludes.
 */

/** Raised when a theme id cannot be addressed as a folder of the site's own themes directory. */
export class ThemeTrashLocationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ThemeTrashLocationError";
  }
}

/** The sibling directory trashed themes are parked in — outside `themes/`, so discovery never sees them. */
export function themeTrashRoot(required: { themesDir: string }): string {
  return `${resolve(required.themesDir)}-trash`;
}

function assertThemeIdSegment(themeId: string): void {
  if (themeId === "" || themeId === "." || themeId === ".." || basename(themeId) !== themeId || themeId.includes("\\")) {
    throw new ThemeTrashLocationError(`'${themeId}' is not a theme folder name`);
  }
}

/**
 * Resolves one theme id to the directory adapter's three paths.
 *
 * A theme already parked wins over a live one with the same id: hiding again then reports
 * `ALREADY_IN_TRASH`, and restoring while any live theme claims the id reports a conflict
 * (`version-changed`) instead of creating a second folder with that id.
 *
 * @throws {ThemeTrashLocationError} When the id is not one path segment, or the live theme's folder is
 *   not directly under `themesDir` or one of its {@link ENGINE_SUBFOLDERS} (e.g. a package stock theme).
 * @complexity O(t) in the discovered theme count, plus at most five `existsSync` probes.
 */
export function locateThemeFolder(required: { themes: readonly DiscoveredTheme[]; themesDir: string; themeId: string }): DirectoryTrashLocation {
  const { themes, themeId } = required;
  assertThemeIdSegment(themeId);
  const root = resolve(required.themesDir);
  const trashRoot = themeTrashRoot({ themesDir: root });
  const live = findTheme({ themes: [...themes], id: themeId });

  for (const sub of ["", ...ENGINE_SUBFOLDERS]) {
    const parkedDir = join(trashRoot, sub, themeId);
    if (existsSync(parkedDir)) return { liveParent: join(root, sub), liveNames: live ? [themeId] : [], parkedDir };
  }

  if (!live) return { liveParent: root, liveNames: [], parkedDir: join(trashRoot, themeId) };
  const liveDir = resolve(live.dir);
  const sub = relative(root, dirname(liveDir));
  if (basename(liveDir) !== themeId || !(sub === "" || (ENGINE_SUBFOLDERS as readonly string[]).includes(sub))) {
    throw new ThemeTrashLocationError(`theme '${themeId}' is not a folder of this site's themes directory, so it cannot be moved to the Trash`);
  }
  return { liveParent: dirname(liveDir), liveNames: [themeId], parkedDir: join(trashRoot, sub, themeId) };
}

/** The tier folders directly under `dir`, or none when it does not exist. @complexity O(entries). */
function tierDirs(dir: string): string[] {
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { withFileTypes: true }).filter((entry) => entry.isDirectory()).map((entry) => entry.name);
}

/**
 * Resolves a theme's stored original to the directory adapter's three paths — the original's own
 * parking spot next to the theme's (see this file's header).
 *
 * The tier is the live theme's when it is discovered; otherwise (the theme is in the Trash) it is read
 * off whichever tier folder holds the id, parked first, then live — so this never needs the registry
 * to restore, and a re-hide after a failed restore finds the original it just put back.
 *
 * @throws {ThemeTrashLocationError} When the id is not one path segment.
 * @complexity O(k) in the catalog's tier folders, plus that many `existsSync` probes.
 */
export function locateThemeOriginal(required: { themes: readonly DiscoveredTheme[]; themesDir: string; themeId: string }): DirectoryTrashLocation {
  const { themes, themeId } = required;
  assertThemeIdSegment(themeId);
  const liveRoot = join(resolve(required.themesDir), THEME_CATALOG_DIR);
  const parkedRoot = join(themeTrashRoot({ themesDir: required.themesDir }), THEME_CATALOG_DIR);
  const at = (tier: string): DirectoryTrashLocation => {
    const liveParent = join(liveRoot, tier);
    return { liveParent, liveNames: existsSync(join(liveParent, themeId)) ? [themeId] : [], parkedDir: join(parkedRoot, tier, themeId) };
  };

  const parkedTier = tierDirs(parkedRoot).find((tier) => existsSync(join(parkedRoot, tier, themeId)));
  if (parkedTier !== undefined) return at(parkedTier);
  const liveTier = findTheme({ themes: [...themes], id: themeId })?.manifest.tier ?? tierDirs(liveRoot).find((tier) => existsSync(join(liveRoot, tier, themeId)));
  return liveTier === undefined ? { liveParent: liveRoot, liveNames: [], parkedDir: join(parkedRoot, themeId) } : at(liveTier);
}

/**
 * The `theme` Trash adapter: the directory adapter over {@link locateThemeFolder}, plus a rescan of the
 * live theme registry (and a preview refresh) after every move, so a trashed theme disappears from
 * `theme_list` at once and a restored one comes back — whichever surface did the restore.
 *
 * The theme's stored original moves alongside ({@link locateThemeOriginal}), all-or-nothing: a theme
 * with no original moves alone; if the original cannot follow, the theme's own move is undone.
 *
 * @param required.themes the live, mutable registry `RouteDeps.themes` holds; rescanned in place.
 * @param optional.rename test seam forwarded to the directory adapter.
 * @complexity O(1) to build; each move costs one rename plus one theme rediscovery.
 */
export function createThemeTrashAdapter(
  required: { themes: DiscoveredTheme[]; themesDir: string },
  optional: { readonly rename?: typeof rename } = {}
): TrashAdapter {
  const { themes, themesDir } = required;
  const refresh = async (): Promise<void> => {
    rescanThemes({ themes, dir: themesDir });
    requestThemePreviewRefresh({ themesDir });
  };
  const adapter = createDirectoryTrashAdapter(
    { entityType: THEME_ENTITY_TYPE, locate: ({ entityId }) => locateThemeFolder({ themes, themesDir, themeId: entityId }) },
    optional
  );
  const original = createDirectoryTrashAdapter(
    {
      entityType: THEME_ENTITY_TYPE,
      locate: ({ entityId }) => {
        const location = locateThemeOriginal({ themes, themesDir, themeId: entityId });
        // The directory adapter stats the live parent before a restore; the tier folder may be gone.
        if (location.liveNames.length === 0 && existsSync(location.parkedDir)) mkdirSync(location.liveParent, { recursive: true });
        return location;
      },
    },
    optional
  );
  /** A move of the original that leaves nothing to undo: it happened, or there was none to move. */
  const settled = (result: TrashMarkerResult): boolean => result.ok || result.reason === "not-found";
  // Not `withFollowUps`: its `afterUnhide` fires only with a stored `priorMarker`, which a directory
  // move never has, so a restore would leave the registry stale.
  return {
    entityType: adapter.entityType,
    async hide(hideRequired, hideOptional) {
      const result = await adapter.hide(hideRequired, hideOptional);
      if (!result.ok) return result;
      // Theme first, then its original (located by the live theme's tier, before the rescan below).
      // The undo rescans first: the registry still lists the theme, which would read as a live
      // folder claiming the id and refuse the move back.
      const undoTheme = async () => {
        await refresh();
        await adapter.unhide({ ...hideRequired, expectedVersion: null });
        await refresh();
      };
      let originalResult: TrashMarkerResult;
      try {
        originalResult = await original.hide(hideRequired, hideOptional);
      } catch (error) {
        await undoTheme();
        throw error;
      }
      if (!settled(originalResult)) {
        await undoTheme();
        return originalResult;
      }
      await refresh();
      return result;
    },
    async unhide(unhideRequired, unhideOptional) {
      // Original first: if the theme then cannot come back, only an original THIS call moved is
      // re-parked — never a live original that some other theme with this id now owns.
      const originalResult = await original.unhide(unhideRequired, unhideOptional);
      const reparkOriginal = async () => {
        if (originalResult.ok) await original.hide({ ...unhideRequired, expectedVersion: null });
      };
      let result: TrashMarkerResult;
      try {
        result = await adapter.unhide(unhideRequired, unhideOptional);
      } catch (error) {
        await reparkOriginal();
        throw error;
      }
      if (!result.ok) {
        await reparkOriginal();
        return result;
      }
      await refresh();
      return result;
    },
    async purge(purgeRequired, purgeOptional) {
      const outcome = await adapter.purge(purgeRequired, purgeOptional);
      if (outcome !== "version-changed") await original.purge(purgeRequired, purgeOptional);
      return outcome;
    },
  };
}

import { DEFAULT_THEME_SLOTS } from "./render-contract.js";
import { readdirSync, readFileSync, existsSync, statSync } from "node:fs";
import { join } from "node:path";

import type { JsonObject, JsonValue } from "@jini-ai/core/primitives";
import { markersOfType } from "@jini-ai/cms/widgets/markers";
import { checkBuiltThemeConformance } from "./build-conformance.js";
import { lintHandlebarsTemplate } from "./handlebars-allowlist.js";
import { lintLiquidTemplate } from "./liquid-allowlist.js";
// `theme-files.ts` imports `ENGINE_SUBFOLDERS`/`THEME_CATALOG_DIR` from this module already, so this
// is a pre-existing module pair, now cyclic in the other direction too — safe because both of these
// are consumed only inside `loadTheme`'s function body below, never at module-evaluation time.
import { GENERATED_THEME_DIRS, isSourceDirGeneratedConflict } from "./theme-files.js";
import { themeIdCandidates } from "./theme-id-aliases.js";
import { resolveThemeLayout } from "./theme-layout.js";
import { RESERVED_SEGMENTS } from "#src/platform/routing/reserved-paths";
import { parseTemplateFor, type ThemeTemplateFor } from "./template-applicability.js";

/**
 * @file Declarative theme package format + discovery (SPEC-004, spike slice).
 *
 * Purpose:
 * A theme is a folder of validated *data* — no executable code. This module
 * defines the on-disk shape, discovers theme folders, and resolves a route to a
 * template id. The template-tree renderer (`server/http/site/render.ts`) turns
 * the resolved block tree into HTML.
 *
 * Spike scope (VibeCoder): discovery + a shallow validity check (required files
 * parse). The full SPEC-004 validation pipeline (CSS sanitization allowlist,
 * component-reference checks, size caps, id-collision rules) is deferred to the
 * proper SPEC-004 build. Treat this as exploratory, not test-certified.
 */

/**
 * ADR-020 capability tier. `declarative` = data-only (safe from anyone),
 * `templated` = LiquidJS-rendered (sandboxed logic, no JS), `handlebars` =
 * Handlebars-rendered (sandboxed logic, no JS — a sibling of `templated` with
 * its own allowlist/worker pair, not a replacement for it), `static` = plain
 * HTML/CSS/JS, no template language at all — every byte editable, a whole
 * `pages/*.html` set instead of one `templates/` route map (see `pages` on
 * {@link DiscoveredTheme}), `code` = trusted signed-plugin JS (not built yet).
 * Absent in `theme.json` ⇒ `declarative`.
 */
export type ThemeTier = "declarative" | "templated" | "handlebars" | "static" | "code";

const THEME_TIERS: readonly ThemeTier[] = ["declarative", "templated", "handlebars", "static", "code"];

/**
 * `theme.json.build` — ADR-020 §5 (2026-08-12): declares which of the two lifecycle classes a
 * `static`-tier theme belongs to.
 *
 * **Authored** — this field absent, every theme on disk today. The working copy on disk IS the
 * source: full per-file edit, reset, and `theme_write_file` AI-authorability, exactly as before this
 * field existed.
 *
 * **Built** (`source: "compiled"`) — the shipped `pages/`, `css/`, `js/` were produced by a framework's
 * own build (React/Vue/Angular) rather than authored directly. Settled by the debate: *the author or
 * publisher CI builds; Tovu never runs the build* — this field records provenance/contract for a build
 * that already happened elsewhere, it never triggers one. A built theme's SOURCE (`sourceDir`) keeps
 * everything an authored theme has today — per-file edit, reset, AI-authorability
 * ({@link import("./theme-files.js").resolveThemeFileWriteScope}). Only its GENERATED tree — everything
 * outside `sourceDir` plus `theme.json` — loses that per-file granularity: it is read-only from every
 * per-file surface, and is restored, when it is, only as one complete release, never file-by-file.
 *
 * `source: "compiled"` requires `tier: "static"` (enforced in {@link loadTheme}) — a compiled theme's
 * RUNTIME is a `static` theme; there is no server-executing `code` tier this maps onto (`code` stays
 * reserved and unbuilt — see {@link ThemeTier}'s own doc).
 */
export interface ThemeBuildInfo {
  /**
   * `"compiled"` marks this theme as a built release (see this interface's own doc). Any other or
   * absent value — including a `build` object present in `theme.json` with no `source` key at all, or
   * an unrecognized string — is treated as `"authored"` rather than failing the theme. This is a
   * descriptive default for an optional field, not {@link parseTier}'s fail-closed contract: that
   * exists because a wrong TIER silently applies a different tier's validation rules with no error;
   * defaulting an ambiguous `build.source` to "this is just an ordinary authored theme" has no
   * equivalent silent-wrong-behavior risk.
   */
  source: "authored" | "compiled";
  /** `compiled` only — which framework produced the source. Purely descriptive: nothing in Tovu's
   * request-time branches reads this field; it exists for the editor UI and support. */
  framework?: "react" | "vue" | "angular";
  /**
   * `compiled` only, REQUIRED — the authored source tree's root, relative to the theme folder (e.g.
   * `"src"`). Everything under this path, plus `theme.json` itself, stays per-file editable exactly
   * like an authored theme; everything outside it is this build's generated output and is read-only
   * through every per-file surface (see {@link import("./theme-files.js").resolveThemeFileWriteScope}).
   * An author-DECLARED path rather than an assumed `src/` convention: a hardcoded prefix would either
   * lock a real source tree named something else out of editing entirely, or (looser) let a generated
   * folder that merely starts with the same letters (`src-legacy/`) slip through as writable.
   */
  sourceDir?: string;
  /** `compiled` only — the tool and version that produced the artifact (e.g. `"astro@4.15.2"`),
   * recorded for support/reproducibility. Never parsed or version-checked by Tovu. */
  builderVersion?: string;
  /** `compiled` only — sha256 of the lockfile the build ran against. Provenance only; Tovu never reads
   * the lockfile's own contents. */
  lockfileHash?: string;
  /**
   * `compiled` only, REQUIRED (non-empty) — sha256 hex digest of each generated file's bytes, keyed by
   * path relative to the theme folder. Verified against the real files on disk by
   * {@link checkBuiltThemeConformance} (`build-conformance.ts`) before the theme is accepted as
   * `status: "valid"` — this is what backs "immutable, versioned, integrity-verified," not a UI label.
   * A file not listed here is not integrity-checked — a documented gap (`build-conformance.ts`'s own
   * header), not a silent one.
   */
  artifactHashes?: Record<string, string>;
}

/** `theme.json` — static theme identity. */
export interface ThemeManifest {
  id: string;
  name: string;
  version: string;
  /**
   * Schema version this manifest declares (`theme-authoring-guide-v2.md` §5/§11). `2` means the
   * theme's on-disk shape uses v2 paths (`css/theme.css`, `scripts/`, `render/pages/`) — read by
   * `static-asset-contract.ts`'s `tokenStylesheetSentinel`/`rewriteAssetPaths`/
   * `findUnrewrittenAssetPaths` (via `static-render.ts` and `build-conformance.ts`), and by
   * `resolveThemeLayout` (`theme-layout.ts`, 2026-08-19 architecture audit findings 1 & 2 — the one
   * apiVersion-aware source of truth every other consumer routes through) to pick the matching
   * sentinel/folder names at request/install time. As of the 2026-08-18 Milestone 3 migration, all
   * seven built-in static themes (`content/themes/static/*`) declare `2` — this is the live, common case,
   * not a forward-looking one. Absent (or any value other than `2` — still fully supported for a
   * site-authored or third-party theme) means v1's flat `css/styles.css`/`js/` shape, preserved
   * exactly, the only behavior this field had before Milestone 3 introduced `2`.
   */
  apiVersion?: 2;
  /** ADR-020 capability tier (defaults to `declarative` when omitted). */
  tier: ThemeTier;
  /** Legacy pre-ADR-020 field; retained for back-compat, superseded by `tier`. */
  class?: "declarative";
  engine: number;
  /**
   * ADR-020 §5 (2026-08-12) — free-text credit for who produced this theme, e.g. "Aurora Themes Co.".
   * Absent for every theme on disk today; `loadTheme` never parsed this field before this change, and
   * nothing in the engine branches on it. Independent of {@link ThemeBuildInfo}: `build` is about HOW
   * the static output was produced, `author` is about WHO produced it — a hand-authored theme can
   * still declare an `author`.
   */
  author?: string;
  /** ADR-020 §5 (2026-08-12) — declares which lifecycle class this theme belongs to. See
   * {@link ThemeBuildInfo}'s own doc for the authored-vs-built distinction and what each keeps/loses. */
  build?: ThemeBuildInfo;
  description?: string;
  /**
   * Legacy font family specs resolved through the shipped URL template for older manifests.
   * SPEC-004 CSS sanitization forbids external font @import in theme CSS, so
   * fonts live in the manifest, not the stylesheet.
   */
  fonts?: string[];
  /** HTTPS stylesheet URLs or root-relative paths, in link order. An empty list disables fonts. */
  fontStylesheets?: string[];
  /**
   * SPEC-043/ADR-047 §2a — the region keys (e.g. `["header","footer"]`) this theme declares for
   * widget placement, the same way it already declares templates/slots. Additive, optional field:
   * absent/undefined means "no declared regions" (unchanged behavior for every existing `theme.json`
   * on disk today — no back-compat migration needed). `resolvePageWidgets`'s `resolvedRegions` input
   * (`Jini/packages/cms/src/widgets/resolver-service.ts`) is sourced directly from this field at render time
   * (`server/http/site/render.ts::renderSite`) — this fulfills what ADR-047 §2a's own framing already
   * assumed existed ("themes declare region keys the same way they already declare template
   * slots/regions") rather than a hardcoded core constant.
   */
  regions?: string[];
  /**
   * `static` tier only — the ordered list of `pages/*.html` filenames (e.g. `["blog-post.html",
   * "page-shell.html"]`) a Post OR a Page can pick between, "ordered to nudge the right choice"
   * (first entry is the implicit default in the Post editor's picker). Absent/undefined means this
   * theme ships no templates — a row's `templateChoice` then has nothing to resolve against, which
   * the render path treats as "misconfigured", not "fall back to generic rendering" (see
   * `pages.ts`'s template branch).
   *
   * ONE array for both kinds (2026-08-11 unification), superseding the earlier separate
   * `postTemplate`/`pageTemplate` split (2026-08-10/11 design docs) — that split existed only
   * because the OLD marker vocabulary made a template's slot type kind-specific
   * (`{"type":"post","id":"{{post}}"}"` vs `{"type":"content"}"`), so the wrong array could offer a
   * Post-shaped template to a Page. The unified `content` marker (`{"type":"content"}"`, optional
   * `id`) removed that distinction at the source: the resolver reads the referenced row's
   * `bodyFormat` at RENDER time and dispatches, so a template file no longer declares which kind it
   * is for. One array is therefore no longer a hazard, and keeping two would just be two
   * independently-maintained copies of the same list to keep in sync — the same "duplicated logic
   * regresses" argument `resolveTemplate`'s own history already made once (2026-08-09
   * null-vs-`""`-conflation).
   *
   * **What this does NOT solve**: which templates make SENSE for a Post vs a Page (a blog template's
   * byline/date/next-post chrome does not belong on Privacy Policy) is a template-APPLICABILITY
   * question this field is silent on — see `ADS-memory/reports/implementation/
   * 2026-08-11-unified-content-marker.md` for why marker-based applicability inference (the design
   * doc's own "interim" proposal) has no signal left to key off now that every template's primary
   * slot carries the identical `{"type":"content"}"` marker, and both admin pickers therefore offer
   * this one flat list unfiltered, same as they always effectively did within their own kind.
   * `templateFor` now declares that applicability explicitly without inferring it from markers.
   */
  templates?: string[];
  /** Optional template -> content kinds. An unlisted template applies to both posts and pages. */
  templateFor?: ThemeTemplateFor;
  /**
   * `static` tier only — the allow-list of {@link isPublishableThemePageCandidate} page ids this
   * theme currently serves publicly (2026-08-30, owner ask: a static theme's public routing was
   * pure file presence with no draft/unpublished concept at all — the gap an agent worked around by
   * moving a live page into an invented `_unpublished/` folder and dropping it from `theme.json`,
   * outside every audited write path. This field is the real mechanism that replaces it).
   *
   * **Absent (no recorded decision — applies RETROACTIVELY to every theme on disk, not only ones
   * touched after this date): off by default.** {@link isStandaloneThemePage} treats every eligible
   * candidate page as unpublished until a decision is recorded. This reverses this field's own
   * first-day default (absent originally meant "everything published", for backward compatibility
   * with pure file-presence routing) per the owner's explicit correction, in their own words: "The
   * pages are not published by default. They shouldn't be... because then they would have wrong
   * information because they're generic themes." Only `index`, `404`, and a declared {@link templates}
   * shell stay live regardless — {@link isPublishableThemePageCandidate} excludes those from this
   * field's reach entirely; they were never "published", they are structurally load-bearing.
   *
   * **Present (a theme where the publish toggle has been used at least once): an explicit allow-list.**
   * A candidate page id NOT in this array is unpublished, same meaning as the absent case — the array
   * only ever records what has been turned ON. The publish route (`explore.ts`'s
   * `registerAdminThemePagePublishRoute`) is the only writer: because the default is already "off",
   * the first toggle on a theme with no recorded array needs no backfill — it simply starts from an
   * empty array and applies the one requested change.
   *
   * Entries are candidate page ids (`pricing`, matching {@link DiscoveredTheme.pages}' own keys), not
   * filenames — `index`/`404` and a declared {@link templates} shell can never appear meaningfully
   * here even if listed: {@link isStandaloneThemePage} excludes them before this array is ever
   * consulted, the same way it always has.
   */
  publishedPages?: string[];
  /**
   * `static` tier only — the color modes this theme ships token sets for, e.g. `["dark", "light"]`.
   * A mode name is just the value written into the page's root `data-theme` attribute, which is the
   * selector `tokensToRootCss` (`static-render.ts`) already emits its `tokens.light.json` override
   * block under (`:root[data-theme="light"]`). Absent/undefined means the theme declares nothing, and
   * {@link renderStaticPage} then emits no `data-theme` at all — the pre-2026-08-10 behavior, where
   * the base `:root` block always won because no attribute existed for an override block to match.
   */
  modes?: string[];
  /**
   * `static` tier only — which of {@link modes} a freshly-served page starts in. Emitted as
   * `data-theme="<defaultMode>"` on the page's `<html>` element, so it selects between the token
   * blocks above. A theme wanting a user-flippable toggle owns that itself: static themes are plain
   * HTML/JS, so their own script sets `document.documentElement.dataset.theme`, and the engine's job
   * ends at establishing the initial value. Declaring a `defaultMode` outside `modes` is a manifest
   * error (the theme loads `invalid` with a message), not a silent fallback.
   */
  defaultMode?: string;
  /**
   * `static` tier only — the `{"type":"partial","id":"<key>"}` `data-embed-config` markers this
   * theme's pages embed, mapped to the root partial file each one pulls in. Read by `resolveSlots`
   * (`static-render.ts`); before this was wired, that function hardcoded exactly the `nav`/`footer`
   * pair every theme on disk happens to declare, so the field was authored but never parsed.
   * {@link DEFAULT_THEME_SLOTS} reproduces that hardcoded pair for a theme that declares no `slots`,
   * which is why wiring this changed no existing theme's output.
   */
  slots?: Record<string, ThemeSlotDescriptor>;
}

/** One entry of {@link ThemeManifest.slots}. */
export interface ThemeSlotDescriptor {
  /** Root partial filename this slot renders, e.g. `nav.html`. */
  source: string;
  /**
   * Whether this slot's marker can carry a `current` key (e.g.
   * `{"type":"partial","id":"nav","current":"pricing"}`) that marks the matching `data-nav-id`
   * anchor inside the resolved partial with `aria-current="page"`. A boolean opt-in, not an
   * attribute name — `data-nav-id` is the only half of this convention themes ever varied, so
   * there was never a second attribute name to configure; only `nav`-shaped slots set this, a
   * `footer` has no current item.
   *
   * Legacy: `theme.json` may instead carry `"activeAttr": "<any string>"` — the pre-2026-08-10
   * spelling, from when this really did name an attribute on the marker element
   * (`data-nav-current`, since retired). {@link parseSlots} treats ANY string value there as
   * `honorsCurrentPage: true`; the string's own content was already dead weight by the time this
   * field was renamed; only its presence ever mattered. Drop that fallback once no in-repo
   * `theme.json` still writes `activeAttr` and the marker drift check
   * (`development/docs/architecture/embed-marker-migration.md` item 4) is extended to gate on it.
   */
  honorsCurrentPage?: boolean;
  /**
   * Alternate sources selected by a marker's `variant` config key, e.g.
   * `{ "minimal": "footer-minimal.html" }`. A variant with no entry here falls back to the
   * `<source-stem>-<variant>.html` filename convention, which is what `resolveSlots` did for every
   * variant before this field was parsed.
   */
  variants?: Record<string, string>;
}

export { DEFAULT_THEME_SLOTS } from "./render-contract.js";

/** Design tokens: CSS custom-property name → value (emitted into `:root`). */
export type ThemeTokens = Record<string, string>;

/** A template is a JSON block tree (doc nodes + slot + component nodes). */
export type TemplateNode = JsonValue;

/** A fully-loaded, discovered theme. */
export interface DiscoveredTheme {
  manifest: ThemeManifest;
  /**
   * Absolute path of the folder this theme was loaded from. Recorded at load time because it is the
   * one fact about a theme that discovery knows and no consumer can re-derive: a theme id alone does
   * not say whether the folder sits at the top level of `themes/` or under one of
   * {@link ENGINE_SUBFOLDERS}. The `themes` agent-tool domain (`agent-tools.ts`) resolves every
   * read/write against THIS value rather than re-deriving a path from the id, so an id can never be
   * used to steer a file operation at a folder discovery did not itself produce.
   */
  dir: string;
  tokens: ThemeTokens;
  /**
   * Light-mode token overrides (static tier only), from an optional `tokens.light.json` sibling to
   * `tokens.json`. Empty object when the theme ships no light variant — a static theme is not
   * required to support both modes, and an empty `:root[data-theme="light"] {}` override block is
   * harmless (it overrides nothing, so the page just stays on its dark values).
   */
  tokensLight: ThemeTokens;
  /** Template id (`home`, `post`, …) → block tree (declarative tier). */
  templates: Record<string, TemplateNode>;
  /** Template id → raw LiquidJS source (templated tier, ADR-020). */
  liquidTemplates: Record<string, string>;
  /** Template id → raw Handlebars source (handlebars tier, ADR-020). */
  handlebarsTemplates: Record<string, string>;
  /**
   * Page id → raw HTML document source (static tier only). Keyed by filename
   * minus `.html`, from `pages/*.html` — unlike `templates`/`liquidTemplates`/
   * `handlebarsTemplates`, these are already-complete `<!doctype html>` documents,
   * not route-driven block trees/fragments, because a static theme has no
   * templating language for a renderer to fill in.
   */
  pages: Record<string, string>;
  /**
   * Partial id → raw HTML source (static tier only): `nav`, `footer`, and any
   * `footer-*` variant (e.g. `footer-minimal`) found at the theme root. A static
   * page embeds these via `data-tovu-slot="nav"` / `data-tovu-slot="footer"`
   * markers rather than a template-include directive — resolving them is the
   * renderer's job, not something baked into the page HTML at author time.
   */
  partials: Record<string, string>;
  /** Raw theme stylesheet (unsanitized in the spike). */
  css: string;
  source: "built-in" | "site";
  status: "valid" | "invalid";
  /** Human-readable validation errors; empty when valid. */
  errors: string[];
}

function isObject(value: unknown): value is JsonObject {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function readJson(path: string): JsonValue {
  return JSON.parse(readFileSync(path, "utf8")) as JsonValue;
}

/** Default an absent/empty `theme.json.tier`; reject a present value this build cannot render. */
function parseTier(value: JsonValue | undefined): ThemeTier {
  if (value === undefined || value === "") return "declarative";
  if (typeof value === "string" && (THEME_TIERS as readonly string[]).includes(value)) {
    return value as ThemeTier;
  }
  throw new Error(`unrecognized theme tier '${String(value)}'`);
}

/** `typeof value === "string" ? value : undefined` — the shape every plain optional-string
 * `theme.json` field shares (`author`, `description`, `defaultMode`, `build.builderVersion`,
 * `build.lockfileHash`, …); factored out once rather than repeated at each call site. */
function parseOptionalString(value: JsonValue | undefined): string | undefined {
  return typeof value === "string" ? value : undefined;
}

/** `Array.isArray(value) ? value.map(String) : undefined` — the shape every plain optional
 * string-array `theme.json` field shares (`fonts`, `regions`, `templates`, `modes`). */
function parseOptionalStringArray(value: JsonValue | undefined): string[] | undefined {
  return Array.isArray(value) ? value.map(String) : undefined;
}

/**
 * `{ ...obj }` minus every key whose value is falsy. Centralizes the "include this optional field
 * only when it has a real value" rule {@link parseThemeBuildInfo}'s return object used to apply as
 * five separate `...(x ? {x} : {})` spreads — one per optional {@link ThemeBuildInfo} field.
 */
function pickTruthy<T extends Record<string, unknown>>(obj: T): Partial<T> {
  return Object.fromEntries(Object.entries(obj).filter(([, v]) => Boolean(v))) as Partial<T>;
}

/** `build.framework` — one of the three known values, or `undefined` for anything else
 * (including an unrecognized framework string, e.g. a theme built with a tool this doesn't
 * name yet — dropped rather than failing the parse, matching every other optional field here). */
function parseBuildFramework(value: JsonValue | undefined): ThemeBuildInfo["framework"] {
  return value === "react" || value === "vue" || value === "angular" ? value : undefined;
}

/** `build.sourceDir` — a non-empty string, or `undefined` (absent, wrong type, or `""`). Presence
 * is enforced separately, at {@link loadTheme}'s call site, once {@link ThemeBuildInfo.source} is
 * known to be `"compiled"` — see this field's own doc for why that check lives there. */
function parseBuildSourceDir(value: JsonValue | undefined): string | undefined {
  return typeof value === "string" && value.length > 0 ? value : undefined;
}

/** `build.artifactHashes` — every entry whose value isn't a string is dropped rather than failing
 * the parse (a build tool emitting one malformed hash shouldn't sink the whole manifest); emptiness
 * after filtering is a {@link loadTheme} call-site concern, matching `sourceDir`'s split above. */
function parseBuildArtifactHashes(value: JsonValue | undefined): Record<string, string> | undefined {
  if (!isObject(value)) return undefined;
  return Object.fromEntries(Object.entries(value).filter((entry): entry is [string, string] => typeof entry[1] === "string"));
}

/**
 * Parse `theme.json.build` into {@link ThemeBuildInfo}. Absent or non-object ⇒ `undefined` (this theme
 * is `authored`, unchanged from before this field existed). Malformed or missing OPTIONAL fields
 * degrade to omission rather than throwing — that is a different failure class than {@link parseTier}'s
 * fail-closed contract (see {@link ThemeBuildInfo.source}'s own doc for why). The two fields REQUIRED
 * for a `compiled` build (`sourceDir`, non-empty `artifactHashes`) are not enforced here — this
 * function only shapes what is present; {@link loadTheme}'s own call site pushes the "required when
 * compiled" errors, matching how `defaultMode`'s cross-field check already lives at the call site
 * rather than inside its own field's parser.
 */
function parseThemeBuildInfo(value: JsonValue | undefined): ThemeBuildInfo | undefined {
  if (!isObject(value)) return undefined;
  const source = value.source === "compiled" ? "compiled" : "authored";
  const framework = parseBuildFramework(value.framework);
  const sourceDir = parseBuildSourceDir(value.sourceDir);
  const builderVersion = parseOptionalString(value.builderVersion);
  const lockfileHash = parseOptionalString(value.lockfileHash);
  const artifactHashes = parseBuildArtifactHashes(value.artifactHashes);

  return {
    source,
    ...pickTruthy({ framework, sourceDir, builderVersion, lockfileHash, artifactHashes }),
  };
}

/**
 * `raw.honorsCurrentPage` (current) or a legacy `raw.activeAttr` string (pre-2026-08-10 spelling —
 * see {@link ThemeSlotDescriptor.honorsCurrentPage}) — either one opts a slot in. Split out of
 * {@link parseSlots} so that function stays a plain per-key loop, the same shape `parseMarkerConfig`
 * was split out of `scanEmbedMarkers` for (`Jini/packages/cms/src/widgets/markers/marker.ts`).
 */
function parseSlotHonorsCurrentPage(raw: Readonly<Record<string, unknown>>): boolean {
  return raw.honorsCurrentPage === true || typeof raw.activeAttr === "string";
}

/** `raw.variants`, keeping only string-valued entries — `undefined` if there are none worth keeping. */
function parseSlotVariants(raw: Readonly<Record<string, unknown>>): Record<string, string> | undefined {
  if (!isObject(raw.variants)) return undefined;
  const variants = Object.fromEntries(
    Object.entries(raw.variants).filter(([, v]) => typeof v === "string").map(([k, v]) => [k, String(v)])
  );
  return Object.keys(variants).length > 0 ? variants : undefined;
}

/**
 * Parse `theme.json.slots` into {@link ThemeSlotDescriptor}s, skipping any entry that isn't an object
 * with a string `source`. Returns `undefined` for an absent/unusable field so the caller falls back to
 * {@link DEFAULT_THEME_SLOTS} rather than resolving zero slots — a theme whose `slots` block is
 * malformed still renders its nav and footer under the legacy convention instead of losing both.
 *
 * `honorsCurrentPage` accepts both spellings, additively: the current boolean, or the legacy
 * `activeAttr` string (any non-empty string). An out-of-tree theme.json that never migrates off
 * `activeAttr` must keep wiring `aria-current` exactly as it does today; this normalizes either
 * spelling onto the one field every downstream reader sees.
 */
function parseSlots(value: JsonValue | undefined): Record<string, ThemeSlotDescriptor> | undefined {
  if (!isObject(value)) return undefined;
  const slots: Record<string, ThemeSlotDescriptor> = {};
  for (const [key, raw] of Object.entries(value)) {
    if (!isObject(raw) || typeof raw.source !== "string") continue;
    const variants = parseSlotVariants(raw);
    slots[key] = {
      source: raw.source,
      ...(parseSlotHonorsCurrentPage(raw) ? { honorsCurrentPage: true } : {}),
      ...(variants ? { variants } : {}),
    };
  }
  return Object.keys(slots).length > 0 ? slots : undefined;
}

/** Everything only a static theme ships. Returned by {@link loadStaticTierAssets}. */
interface StaticTierAssets {
  tokensLight: ThemeTokens;
  pages: Record<string, string>;
  partials: Record<string, string>;
  /** Validation failures, for the caller to merge into the theme's own `errors`. */
  errors: string[];
}

/** No static assets, for every tier that ships none. */
const NO_STATIC_TIER_ASSETS: StaticTierAssets = {
  tokensLight: {},
  pages: {},
  partials: {},
  errors: [],
};

/**
 * Read `tokens.light.json`, a static theme's optional light-mode override set.
 *
 * Optional unlike `tokens.json`: absent is not an error, it just means the theme ships no light
 * variant, which leaves the map empty so no `:root` override block is emitted at all.
 */
function readLightTokens(
  required: { themeDir: string; errors: string[] },
  _optional: Record<string, never> = {}
): ThemeTokens {
  const { themeDir, errors } = required;
  const path = join(themeDir, "tokens.light.json");
  if (!existsSync(path)) return {};
  try {
    const raw = readJson(path);
    if (!isObject(raw)) throw new Error("tokens.light.json is not an object");
    return Object.fromEntries(Object.entries(raw).map(([k, v]) => [k, String(v)]));
  } catch (err) {
    errors.push(`tokens.light.json: ${(err as Error).message}`);
    return {};
  }
}

/**
 * Read the root partial files a static theme's declared {@link ThemeManifest.slots} name.
 *
 * Before this, the partial scan was a hardcoded filename allowlist — `nav.html` or anything starting
 * with `footer` — which meant a theme could DECLARE a slot (`"sidebar": { "source": "sidebar.html" }`)
 * and have its file read by nothing, so the marker resolved empty with no error anywhere. Slots are
 * now the single source of truth for which root `.html` files are partials, which is what makes
 * adding a region to a copied theme a manifest edit rather than a code change here.
 *
 * A slot matches its own `source` plus the `<stem>-<variant>.html` convention `resolveSlots` already
 * falls back to for a variant with no explicit `variants` entry — so `footer.html` still pulls in
 * `footer-minimal.html`, and a new `sidebar` slot gets `sidebar-*.html` on the same terms rather than
 * a second, differently-shaped rule.
 */
/**
 * @param required.partialsDir - v1: the theme's own root (`themeDir`) — partials sit alongside
 * `pages/`/`css/`/`js/`. v2: `render/partials/` — see `theme-authoring-guide-v2.md` §3. Passed in
 * rather than derived here so this function stays agnostic to which schema version picked it.
 */
function loadSlotPartials(
  required: { partialsDir: string; slots: Record<string, ThemeSlotDescriptor> },
  _optional: Record<string, never> = {}
): Record<string, string> {
  const { partialsDir, slots } = required;
  if (!existsSync(partialsDir)) return {};
  const descriptors = Object.values(slots);
  const stems = descriptors.map((slot) => slot.source.replace(/\.html$/, ""));
  const explicitVariants = new Set(descriptors.flatMap((slot) => Object.values(slot.variants ?? {})));

  const partials: Record<string, string> = {};
  for (const file of readdirSync(partialsDir)) {
    if (!file.endsWith(".html")) continue;
    const named = explicitVariants.has(file);
    const conventional = stems.some((stem) => file === `${stem}.html` || file.startsWith(`${stem}-`));
    if (!named && !conventional) continue;
    partials[file.slice(0, -".html".length)] = readFileSync(join(partialsDir, file), "utf8");
  }
  return partials;
}

/** Every `templates` entry must resolve against `pages/<id>.html` and carry this marker type. */
const TEMPLATE_SLOT_MARKER_TYPE = "content";

/**
 * Validates the theme's `templates` array against its already-loaded `pages` (2026-08-11, owner
 * decision — see `ADS-memory/reports/continuity/2026-08-11-pages-template-decisions.md`, extended to
 * the unified single array by `ADS-memory/reports/design/2026-08-11-unified-content-marker-and-
 * templates.md`): a listed entry that resolves to no file, or to a file with zero `"content"`
 * markers, renders a structurally fine page with its actual content silently missing — "the worst
 * failure class this codebase keeps hitting", in the owner's own words, and the same class of bug
 * REQ-10's `pages/index.html is required` check exists to catch at load time rather than on a
 * visitor's page view.
 *
 * One field, one marker type, one call site — collapsed from the pre-unification version that took a
 * `fieldName`/`slotMarkerType` pair and was called twice (once for `postTemplate`/`"post"`, once for
 * `pageTemplate`/`"content"`). With only one array and one marker type left to check, parameterizing
 * either would just be indirection with a single value ever passed through it.
 *
 * Not itself tier-gated — `pages` is empty for every non-static theme (`loadStaticTierAssets`'s own
 * early return), so a non-static theme is already incapable of tripping this on a `templates` field it
 * isn't documented to declare; gating here too would just be a second copy of that same guarantee.
 *
 * @complexity O(t) over `templates`' length; each entry's marker scan is O(n) in that one page's HTML
 *   length (`markersOfType`), the same cost `resolveTemplate` already pays per request.
 */
function validateTemplateDeclarations(
  required: {
    templates: readonly string[] | undefined;
    pages: Readonly<Record<string, string>>;
    pagesDirName?: string;
  },
  _optional: Record<string, never> = {}
): string[] {
  const { templates, pages, pagesDirName = "pages" } = required;
  if (!templates) return [];

  const errors: string[] = [];
  for (const entry of templates) {
    const pageId = entry.replace(/\.html$/, "");
    const html = pages[pageId];
    if (html === undefined) {
      errors.push(`theme.json templates entry '${entry}' has no matching ${pagesDirName}/${pageId}.html file`);
      continue;
    }
    if (markersOfType({ html: html, type: TEMPLATE_SLOT_MARKER_TYPE }).length === 0) {
      errors.push(
        `${pagesDirName}/${pageId}.html is declared in theme.json templates but has no {"type":"${TEMPLATE_SLOT_MARKER_TYPE}"} marker`
      );
    }
  }
  return errors;
}

/**
 * Page ids that live in `pages` but are never their own public URL: `index` is served at `/` by the
 * home route, and `404` is the error document `handlePostNotFoundOnSlugRoute` renders WITH a 404
 * status. Serving either at `/<id>` is a soft 404 — a real 200 response carrying error-page or
 * duplicate-home content, which search engines index as genuine.
 */
const NON_ROUTABLE_THEME_PAGE_IDS: ReadonlySet<string> = new Set(["index", "404"]);

/**
 * Whether `pageId` is a page SHAPE {@link isStandaloneThemePage}'s publish check can apply to at all —
 * every check that predicate makes EXCEPT the publish-state lookup itself: the page exists, isn't
 * `index`/`404`, and isn't a declared {@link ThemeManifest.templates} shell.
 *
 * Split out (2026-08-30) so the publish-toggle UI/route can tell "this isn't a publishable page at
 * all" (index, 404, a Post/Page template shell, or no such page) apart from "it's a real candidate
 * page that is currently turned off" — {@link isStandaloneThemePage} answers only the second question
 * once this one is already true, and re-deriving these same three checks a second time at the route
 * layer is exactly the drift this predicate's own history already warns against once (see that
 * function's own doc for the pre-2026 duplication this file fixed).
 *
 * @complexity O(t) over `manifest.templates`' length — 0–3 entries on every real theme on disk.
 */
export function isPublishableThemePageCandidate(theme: DiscoveredTheme, pageId: string): boolean {
  if (theme.pages[pageId] === undefined) return false;
  if (NON_ROUTABLE_THEME_PAGE_IDS.has(pageId) || RESERVED_SEGMENTS.has(pageId.toLowerCase())) return false;
  return !(theme.manifest.templates ?? []).some((entry) => entry.replace(/\.html$/, "") === pageId);
}

/**
 * Whether `pageId` is one of this theme's own standalone, publicly reachable pages — i.e. whether
 * `GET /<pageId>` should render it directly.
 *
 * **Why this exists as one shared predicate.** A static theme's `pages` record
 * (`DiscoveredTheme.pages`) holds two structurally identical but semantically different kinds of
 * entry under the same string keys: real standalone marketing pages (`about`, `pricing`, …) AND
 * content-embedding template shells a Post/Page selects via `templateChoice` (`blog-post`,
 * `page-shell`, …, declared in `manifest.templates` and validated by
 * {@link validateTemplateDeclarations} above). Nothing in the loaded theme shape distinguishes them
 * by type — only which OTHER list names a given key. A shell served directly is a document whose
 * `{"type":"content"}` marker was never substituted: structurally fine, content silently missing,
 * the exact failure class {@link validateTemplateDeclarations}'s own doc calls "the worst failure
 * class this codebase keeps hitting".
 *
 * The live `GET /:slug` resolver (`server/routes/site/pages.ts`'s `isMarketingPageSlug`) and the
 * static exporter's route enumeration (`export/route-manifest.ts`) both have to answer this same
 * question, and previously each spelled its own answer — the exporter excluded shells and `404`,
 * the live route excluded neither, so `/blog-post` and `/404` were publicly reachable 200s on the
 * running server while the export correctly omitted them. Two resolvers for one question is a
 * drift waiting to happen; this is the single one both now call.
 *
 * NOT tier-gated: `pages` is empty for every non-static theme (`loadStaticTierAssets`'s own early
 * return), and both callers already branch on `tier === "static"` for their own separate reasons
 * (the live route to pick a resolution strategy, the exporter to skip the theme entirely). Gating
 * here too would be a third copy of a guarantee that already holds twice over.
 *
 * **Publish state (2026-08-30 addition, off-by-default retroactively since the same day).** Once
 * every {@link isPublishableThemePageCandidate} check passes, this also consults
 * {@link ThemeManifest.publishedPages} — see that field's own doc for the absent-means-unpublished /
 * present-means-explicit-allow-list contract. Checked LAST, after every shape check above: a page
 * that isn't even a candidate is never "unpublished", it simply isn't a publishable page at all.
 *
 * @complexity O(t) over `manifest.templates`' length — 0–3 entries on every real theme on disk.
 */
export function isStandaloneThemePage(theme: DiscoveredTheme, pageId: string): boolean {
  if (!isPublishableThemePageCandidate(theme, pageId)) return false;
  const { publishedPages } = theme.manifest;
  // No recorded decision on this theme at all — off by default (2026-08-30 owner correction,
  // applied retroactively to every theme, not only ones touched after this date). See
  // `ThemeManifest.publishedPages`'s own doc for the full history and the owner's own reasoning.
  if (publishedPages === undefined) return false;
  return publishedPages.includes(pageId);
}

/**
 * Read the static tier's assets as one unit, or nothing at all for any other tier.
 *
 * A static theme is a different kind of artifact from every other tier — already-complete HTML
 * documents plus their partials and an optional light-token variant, rather than a route map of
 * templates a rendering engine fills in — so none of this shares a branch with the other tiers.
 * Kept out of {@link loadTheme}, tier check included, because inlining it there made one function
 * responsible for four unrelated on-disk layouts and left the caller re-testing the tier three
 * separate times.
 *
 * Errors are returned rather than thrown, matching {@link loadTheme}'s contract that one bad theme
 * degrades to `status: "invalid"` instead of breaking discovery for every other theme.
 *
 * @complexity O(f) in the theme folder's entries, each read at most once.
 * @overallScore 100
 */
function loadStaticTierAssets(
  required: {
    themeDir: string;
    tier: ThemeTier;
    slots?: Record<string, ThemeSlotDescriptor>;
    templates?: string[];
    apiVersion?: 2;
  },
  _optional: Record<string, never> = {}
): StaticTierAssets {
  const { themeDir, tier, slots, templates, apiVersion } = required;
  if (tier !== "static") return NO_STATIC_TIER_ASSETS;

  const errors: string[] = [];
  const tokensLight = readLightTokens({ themeDir, errors });

  // REQ-01's spirit, not its exact home+entry pair: a static theme's minimum is one page to
  // actually show, not a route id a templating engine would fill in. `resolveThemeLayout` is the one
  // apiVersion-aware source of truth for this folder name — v2 nests it one level deeper
  // (`render/pages/`, theme-authoring-guide-v2.md §3) — v1 keeps `pages/` at the theme root.
  const layout = resolveThemeLayout(apiVersion);
  const pagesDirName = layout.pagesDir;
  const pages: Record<string, string> = {};
  const pagesDir = join(themeDir, pagesDirName);
  if (existsSync(pagesDir)) {
    for (const file of readdirSync(pagesDir)) {
      if (file.endsWith(".html")) {
        pages[file.slice(0, -".html".length)] = readFileSync(join(pagesDir, file), "utf8");
      }
    }
  }
  if (!pages.index) errors.push(`${pagesDirName}/index.html is required`);

  errors.push(...validateTemplateDeclarations({ templates, pages, pagesDirName }));

  // Partials (`nav`, `footer`, and anything else the manifest declares) live at the theme root in v1,
  // not under pages/, because a static page embeds them via a `{"type":"partial"}` marker the
  // renderer resolves rather than a template-include directive baked in at author time. v2 moves this
  // to `render/partials/`, alongside `render/pages/` — `layout.partialsDir` is `""` for v1 (the theme
  // root itself, see `ThemeLayout.partialsDir`'s own doc), which `join(themeDir, "")` resolves back to
  // `themeDir` unchanged. A theme with no `slots` block gets DEFAULT_THEME_SLOTS, which is the
  // nav/footer pair this scan used to hardcode.
  const partialsDir = join(themeDir, layout.partialsDir);
  const partials = loadSlotPartials({ partialsDir, slots: slots ?? DEFAULT_THEME_SLOTS });

  return { tokensLight, pages, partials, errors };
}

/**
 * Build a {@link ThemeManifest} from `theme.json`'s already-parsed, already-object-checked
 * contents — pure field-by-field shaping, no validation (see {@link validateManifestCrossFields}
 * for the checks that read more than one field at a time, and {@link parseThemeManifest} for the
 * try/catch this sits inside).
 */
function parseRawManifestFields(raw: Readonly<JsonObject>, id: string): ThemeManifest {
  const resolvedId = String(raw.id ?? id);
  const templates = parseOptionalStringArray(raw.templates);
  return {
    id: resolvedId,
    name: String(raw.name ?? id),
    version: String(raw.version ?? "0.0.0"),
    apiVersion: raw.apiVersion === 2 ? 2 : undefined,
    tier: parseTier(raw.tier),
    engine: typeof raw.engine === "number" ? raw.engine : 1,
    author: parseOptionalString(raw.author),
    build: parseThemeBuildInfo(raw.build),
    description: parseOptionalString(raw.description),
    fonts: parseOptionalStringArray(raw.fonts),
    fontStylesheets: parseOptionalStringArray(raw.fontStylesheets),
    regions: parseOptionalStringArray(raw.regions),
    // Publisher-authored flags must never disable template lint: the allowlist is the boundary
    // between authored templates and the worker. Liquid and Handlebars both enforce it;
    // Handlebars raw output, partials and decorators also expose XSS/compiler-object seams.
    // No `postTemplate`/`pageTemplate` back-compat aliases (2026-08-11 unification, owner's
    // standing rule on this contract: strictness over compat code). A manifest still carrying the
    // retired spelling simply loads with no templates, same as one that never declared any —
    // `check:embed-marker-drift` is what catches a manifest that needed converting, not this parse.
    templates,
    templateFor: parseTemplateFor({ value: raw.templateFor, templates }),
    publishedPages: parseOptionalStringArray(raw.publishedPages),
    modes: parseOptionalStringArray(raw.modes),
    defaultMode: parseOptionalString(raw.defaultMode),
    slots: parseSlots(raw.slots),
  };
}

/**
 * The `build.source: "compiled"` cross-field checks — a compiled theme is, at runtime, an
 * ordinary `static` theme, so there is no server-executing tier it maps onto (see
 * {@link ThemeBuildInfo}'s own doc), and its `sourceDir`/`artifactHashes` are REQUIRED once
 * `source` says `compiled` even though {@link parseThemeBuildInfo} treats them as optional shape.
 * Split out of {@link validateManifestCrossFields} so that function's own three top-level checks
 * (id match, `defaultMode`, and "is this a compiled build") stay a flat sequence.
 */
function validateCompiledBuildManifest(build: ThemeBuildInfo, tier: ThemeTier): string[] {
  const errors: string[] = [];
  if (tier !== "static") {
    errors.push("theme.json build.source 'compiled' requires tier 'static'");
  }
  if (!build.sourceDir) {
    errors.push("theme.json build.sourceDir is required when build.source is 'compiled'");
  } else if (isSourceDirGeneratedConflict(build.sourceDir)) {
    // The deeper fix promised in `explore.ts`'s PUT handler comment (2026-08-13): a manifest is
    // refused HERE, at install time, rather than relying only on each write route's own
    // `isGeneratedThemePath` call-site refusal. That refusal (explore.ts) stays —
    // this is an earlier, independent layer, not a replacement for it. See
    // `isSourceDirGeneratedConflict`'s own doc for the three conflicting shapes (exact, nested
    // inside, or ancestor-of a generated dir) and why `"preview-notes"` is not one of them.
    errors.push(
      `theme.json build.sourceDir '${build.sourceDir}' must not name or contain a generated theme directory (${GENERATED_THEME_DIRS.join(", ")})`
    );
  }
  if (!build.artifactHashes || Object.keys(build.artifactHashes).length === 0) {
    errors.push("theme.json build.artifactHashes is required when build.source is 'compiled'");
  }
  return errors;
}

/**
 * Cross-field manifest checks — each reads more than one field, which is why none of these live
 * inside {@link parseRawManifestFields} or a single field's own parser (matching how
 * {@link parseThemeBuildInfo}'s own doc already draws this line for `build`).
 */
function validateManifestCrossFields(manifest: ThemeManifest, id: string): string[] {
  const errors: string[] = [];
  if (manifest.id !== id) errors.push(`theme.json id '${manifest.id}' must equal folder name '${id}'`);
  // A `defaultMode` the theme ships no tokens for would silently render the base `:root` block
  // while the manifest claims otherwise — the exact "declared but unreachable" failure wiring
  // these fields was meant to end, so it fails the theme loudly instead of falling back.
  if (manifest.defaultMode !== undefined && !(manifest.modes ?? []).includes(manifest.defaultMode)) {
    errors.push(
      `theme.json defaultMode '${manifest.defaultMode}' is not listed in modes [${(manifest.modes ?? []).join(", ")}]`
    );
  }
  if (manifest.build?.source === "compiled") {
    errors.push(...validateCompiledBuildManifest(manifest.build, manifest.tier));
  }
  return errors;
}

/** A manifest that never parsed at all — {@link parseThemeManifest}'s fallback when `theme.json`
 * is missing, unreadable, or not an object. Every field falls back to what `loadTheme` used
 * before any of these fields existed. */
function emptyThemeManifest(id: string): ThemeManifest {
  return { id, name: id, version: "0.0.0", tier: "declarative", engine: 1 };
}

/**
 * Read and validate `theme.json`. Never throws — a read/parse failure degrades to
 * {@link emptyThemeManifest} plus one error, matching {@link loadTheme}'s "one bad theme never
 * breaks discovery" contract (SPEC-004 REQ-10 spirit).
 */
function parseThemeManifest(themeDir: string, id: string): { manifest: ThemeManifest; errors: string[] } {
  try {
    const raw = readJson(join(themeDir, "theme.json"));
    if (!isObject(raw)) throw new Error("theme.json is not an object");
    const manifest = parseRawManifestFields(raw, id);
    return { manifest, errors: validateManifestCrossFields(manifest, id) };
  } catch (err) {
    return { manifest: emptyThemeManifest(id), errors: [`theme.json: ${(err as Error).message}`] };
  }
}

/** Read `tokens.json`. Never throws — a read/parse failure degrades to an empty token map plus
 * one error, the same REQ-10 contract {@link parseThemeManifest} follows for `theme.json`. */
function loadThemeTokens(themeDir: string): { tokens: ThemeTokens; errors: string[] } {
  try {
    const raw = readJson(join(themeDir, "tokens.json"));
    if (!isObject(raw)) throw new Error("tokens.json is not an object");
    return { tokens: Object.fromEntries(Object.entries(raw).map(([k, v]) => [k, String(v)])), errors: [] };
  } catch (err) {
    return { tokens: {}, errors: [`tokens.json: ${(err as Error).message}`] };
  }
}

/**
 * The install-time gate for a built release (ADR-020 §5) — only runs for `build.source:
 * "compiled"` (a no-op otherwise, so every theme on disk today is unaffected). Needs
 * `pages`/`partials`, so {@link loadTheme} cannot call this any earlier than after
 * {@link loadStaticTierAssets} — see `build-conformance.ts`'s own header for what it checks and
 * why a hard failure here, not a runtime warning, is the point.
 */
function checkCompiledBuildConformance(
  manifest: ThemeManifest,
  themeDir: string,
  pages: Readonly<Record<string, string>>,
  partials: Readonly<Record<string, string>>
): string[] {
  if (manifest.build?.source !== "compiled") return [];
  return checkBuiltThemeConformance({
    themeId: manifest.id,
    themeDir,
    sourceDir: manifest.build.sourceDir,
    pages,
    partials,
    artifactHashes: manifest.build.artifactHashes ?? {},
    apiVersion: manifest.apiVersion,
  }).map((issue) => `build conformance (${issue.rule}) '${issue.page}': ${issue.message}`);
}

/** Which of the three template source families a `templates/` (or v2 `render/pages/`) directory
 * entry belongs to, by extension — `"unknown"` for anything {@link loadTemplateSources} ignores
 * (same as the original silent no-op for a non-matching file). */
function classifyTemplateFile(file: string): "json" | "liquid" | "handlebars" | "unknown" {
  if (file.endsWith(".json")) return "json";
  if (file.endsWith(".liquid")) return "liquid";
  if (file.endsWith(".hbs") || file.endsWith(".handlebars")) return "handlebars";
  return "unknown";
}

/** Declarative tier: one block-tree template per `.json` file. */
function loadJsonTemplateFile(
  templatesDir: string,
  templatesDirName: string,
  file: string,
  target: { templates: Record<string, TemplateNode>; errors: string[] }
): void {
  const templateId = file.slice(0, -".json".length);
  try {
    target.templates[templateId] = readJson(join(templatesDir, file));
  } catch (err) {
    target.errors.push(`${templatesDirName}/${file}: ${(err as Error).message}`);
  }
}

/**
 * Templated tier (ADR-020): raw LiquidJS source, rendered by the engine in render.ts. C6/REQ-06
 * lint-before-publish: reject any tag/filter outside the ADR-020 §3 allowlist before the theme
 * can load as valid. Worker isolation, filesystem lockdown and memory/render/parse limits
 * remain independent safeguards; none substitutes for this unconditional lint.
 */
function loadLiquidTemplateFile(
  templatesDir: string,
  templatesDirName: string,
  file: string,
  target: { liquidTemplates: Record<string, string>; errors: string[] }
): void {
  const templateId = file.slice(0, -".liquid".length);
  const source = readFileSync(join(templatesDir, file), "utf8");
  const violations = lintLiquidTemplate(source);
  if (violations.length > 0) {
    target.errors.push(`${templatesDirName}/${file}: ${violations.join("; ")}`);
  } else {
    target.liquidTemplates[templateId] = source;
  }
}

/**
 * Handlebars tier (ADR-020): raw Handlebars source, rendered by the isolated worker in
 * `server/http/site/handlebars-worker.ts`. Exactly the same lint-before-publish contract
 * {@link loadLiquidTemplateFile} applies, against the Handlebars-specific allowlist — a
 * disallowed helper, a partial, a decorator, or a `{{{raw}}}` output outside the one sanctioned
 * path fails the theme rather than reaching the compiler. Both extensions are accepted
 * (Handlebars' ecosystem uses them interchangeably) and map to the same template-id namespace, so
 * `home.hbs` and `home.handlebars` are the same template id — the last one `readdirSync` yields
 * wins, which is why a theme should ship one or the other, not both.
 */
function loadHandlebarsTemplateFile(
  templatesDir: string,
  templatesDirName: string,
  file: string,
  target: { handlebarsTemplates: Record<string, string>; errors: string[] }
): void {
  const ext = file.endsWith(".hbs") ? ".hbs" : ".handlebars";
  const templateId = file.slice(0, -ext.length);
  const source = readFileSync(join(templatesDir, file), "utf8");
  const violations = lintHandlebarsTemplate(source);
  if (violations.length > 0) {
    target.errors.push(`${templatesDirName}/${file}: ${violations.join("; ")}`);
  } else {
    target.handlebarsTemplates[templateId] = source;
  }
}

/**
 * Scan the theme's route-map directory (v1: theme-root `templates/`; v2: `render/pages/` —
 * theme-authoring-guide-v2.md §3, same folder name static pages use, only the naming convention
 * changes) and dispatch each file to its extension's loader. A missing directory is not an error
 * here — the required-template check ({@link validateRequiredTemplates}) is what turns "no home/
 * entry template" into one, the same REQ-10 fault-isolation split {@link loadStaticTierAssets}
 * already draws between "nothing found" and "what's required".
 */
function loadTemplateSources(
  themeDir: string,
  manifest: ThemeManifest
): {
  templatesDirName: string;
  templates: Record<string, TemplateNode>;
  liquidTemplates: Record<string, string>;
  handlebarsTemplates: Record<string, string>;
  errors: string[];
} {
  // v1: non-static tiers keep their route map at theme-root `templates/`. v2 unifies every tier's
  // route map under `render/pages/` — only the naming convention changes, the per-extension
  // dispatch below (json/liquid/hbs) stays identical either way.
  const templatesDirName = manifest.apiVersion === 2 ? "render/pages" : "templates";
  const templatesDir = join(themeDir, templatesDirName);
  const templates: Record<string, TemplateNode> = {};
  const liquidTemplates: Record<string, string> = {};
  const handlebarsTemplates: Record<string, string> = {};
  const errors: string[] = [];

  if (!existsSync(templatesDir)) {
    return { templatesDirName, templates, liquidTemplates, handlebarsTemplates, errors };
  }

  for (const file of readdirSync(templatesDir)) {
    const kind = classifyTemplateFile(file);
    if (kind === "json") {
      loadJsonTemplateFile(templatesDir, templatesDirName, file, { templates, errors });
    } else if (kind === "liquid") {
      loadLiquidTemplateFile(templatesDir, templatesDirName, file, {
        liquidTemplates,
        errors,
      });
    } else if (kind === "handlebars") {
      loadHandlebarsTemplateFile(templatesDir, templatesDirName, file, { handlebarsTemplates, errors });
    }
  }

  return { templatesDirName, templates, liquidTemplates, handlebarsTemplates, errors };
}

/** Which template-id map is authoritative for a tier's required home/entry check, and the file
 * extension its error messages should name — templated themes ship `.liquid`, handlebars themes
 * ship `.hbs`, every other (non-static) tier ships plain `.json`. */
function requiredTemplatesForTier(
  tier: ThemeTier,
  templates: Readonly<Record<string, TemplateNode>>,
  liquidTemplates: Readonly<Record<string, string>>,
  handlebarsTemplates: Readonly<Record<string, string>>
): { ext: string; required: Readonly<Record<string, unknown>> } {
  if (tier === "templated") return { ext: "liquid", required: liquidTemplates };
  if (tier === "handlebars") return { ext: "hbs", required: handlebarsTemplates };
  return { ext: "json", required: templates };
}

/**
 * REQ-01: a theme's required template minimum is home + entry (the base). C3: post/page are
 * optional specializations that fall through to entry (REQ-03). A static theme has no separate
 * route-map folder at all — its required-file check is {@link loadStaticTierAssets}'s job, not
 * this one's.
 */
function validateRequiredTemplates(
  manifest: ThemeManifest,
  templatesDirName: string,
  templates: Readonly<Record<string, TemplateNode>>,
  liquidTemplates: Readonly<Record<string, string>>,
  handlebarsTemplates: Readonly<Record<string, string>>
): string[] {
  if (manifest.tier === "static") return [];
  const { ext, required } = requiredTemplatesForTier(manifest.tier, templates, liquidTemplates, handlebarsTemplates);
  const errors: string[] = [];
  if (!required.home) errors.push(`${templatesDirName}/home.${ext} is required`);
  if (!required.entry) errors.push(`${templatesDirName}/entry.${ext} is required`);
  return errors;
}

/**
 * v1: static keeps CSS under `css/styles.css` (alongside sibling `js/` and `pages/` folders);
 * every other tier keeps a lone `styles.css` at the theme root, the flat single-stylesheet shape
 * that fits a route-map-only theme. v2 unifies every tier onto `css/theme.css`
 * (theme-authoring-guide-v2.md §3) — same folder name static already used, new filename, and now
 * every tier gets the `css/` folder rather than just static.
 */
function loadThemeCss(themeDir: string, manifest: ThemeManifest): string {
  const cssPath = join(
    themeDir,
    manifest.apiVersion === 2 ? "css/theme.css" : manifest.tier === "static" ? "css/styles.css" : "styles.css"
  );
  return existsSync(cssPath) ? readFileSync(cssPath, "utf8") : "";
}

/**
 * Load one theme folder. Returns a DiscoveredTheme with `status: "invalid"` and
 * a populated `errors` list instead of throwing, so one bad theme never breaks
 * discovery (SPEC-004 REQ-10 spirit).
 */
export function loadTheme(
  required: { themeDir: string; id: string; source: "built-in" | "site" },
  _optional: Record<string, never> = {}
): DiscoveredTheme {
  const { themeDir, id, source } = required;
  const errors: string[] = [];

  const { manifest, errors: manifestErrors } = parseThemeManifest(themeDir, id);
  errors.push(...manifestErrors);

  const { tokens, errors: tokenErrors } = loadThemeTokens(themeDir);
  errors.push(...tokenErrors);

  // The static tier's whole on-disk layout — light tokens, pages/, root partials — loaded in one
  // call rather than as branches threaded through the tier-agnostic loading below. Empty for every
  // other tier, so nothing here needs to re-test which tier this is.
  const { tokensLight, pages, partials, errors: staticErrors } = loadStaticTierAssets({
    themeDir,
    tier: manifest.tier,
    slots: manifest.slots,
    templates: manifest.templates,
    apiVersion: manifest.apiVersion,
  });
  errors.push(...staticErrors);

  errors.push(...checkCompiledBuildConformance(manifest, themeDir, pages, partials));

  const { templatesDirName, templates, liquidTemplates, handlebarsTemplates, errors: templateErrors } =
    loadTemplateSources(themeDir, manifest);
  errors.push(...templateErrors);
  errors.push(
    ...validateRequiredTemplates(manifest, templatesDirName, templates, liquidTemplates, handlebarsTemplates)
  );

  const css = loadThemeCss(themeDir, manifest);

  return {
    manifest,
    dir: themeDir,
    tokens,
    tokensLight,
    templates,
    liquidTemplates,
    handlebarsTemplates,
    pages,
    partials,
    css,
    source,
    status: errors.length === 0 ? "valid" : "invalid",
    errors,
  };
}

/**
 * Discover every theme folder under `dir`. Missing dir ⇒ empty list (a site
 * served without a themes/ dir is legal, SPEC-004 REQ-05).
 *
 * `exclude` skips named subdirectories that aren't themes themselves — used by
 * {@link discoverAllBuiltInThemes} to keep the engine-specific subfolders
 * (`templated/`, `handlebars/`) from being scanned as (invalid) top-level theme
 * candidates when it also scans them directly as their own theme roots.
 *
 * Separately (and unconditionally, not via `exclude`), any child directory whose name starts with
 * {@link MIGRATION_STAGING_DIR_PREFIX} is skipped too — `exclude` only expresses exact names known
 * ahead of time (engine subfolders, the two catalog dirs), never a per-run-randomized prefix like
 * migration scratch output, so that one case gets its own always-on check here instead of being
 * threaded through every caller's `exclude` array.
 */
export function discoverThemes(
  required: { dir: string; source: "built-in" | "site"; exclude?: readonly string[] },
  _optional: Record<string, never> = {}
): DiscoveredTheme[] {
  const { dir, source, exclude } = required;
  if (!existsSync(dir)) return [];
  return readdirSync(dir)
    .filter((name) => {
      if (exclude?.includes(name)) return false;
      if (name.startsWith(MIGRATION_STAGING_DIR_PREFIX)) return false;
      if (name === PUBLISH_STAGING_DIR || name === PUBLISH_PREVIOUS_DIR) return false;
      const full = join(dir, name);
      return statSync(full).isDirectory();
    })
    .map((name) => loadTheme({ themeDir: join(dir, name), id: name, source }))
    .sort((a, b) => a.manifest.id.localeCompare(b.manifest.id));
}

/**
 * Named engine-specific subfolders under a themes root, one per {@link ThemeTier} except `code`
 * (not built yet) — every tier's themes live under its own subfolder so `themes/` doesn't mix
 * formats in one flat listing (2026-08-10: `declarative` moved off the bare top level, and the
 * LiquidJS-tier folder renamed from `liquidjs/` to `templated/` to match its `ThemeTier` value —
 * `templated` names the tier, not the engine, so more templating engines can land under this same
 * folder later without another rename). Scanning a missing subfolder is a no-op (`discoverThemes`'s
 * own missing-dir ⇒ empty-list behavior), so adding an engine here ahead of its first theme costs
 * nothing.
 *
 * Exported because it is also the containment boundary the `themes` agent-tool domain enforces
 * (`agent-tools.ts`/`tool-registrations.ts`): a theme folder that is not a direct child of the
 * themes root or of one of THESE subfolders is not a recognized theme root, and no agent-driven file
 * write may resolve into it.
 */
export const ENGINE_SUBFOLDERS = ["declarative", "templated", "handlebars", "static"] as const;

/**
 * The pristine-originals catalog under a themes root: shipped themes kept untouched so a copy can
 * always be compared against, reset to, or re-forked from what it started as.
 *
 * It is NOT a tier and NOT a theme — it holds its own `<tier>/<theme>/` tree — so discovery skips it
 * outright. A catalog theme is never runnable, never listed, and never the active theme; it becomes
 * either of those only by being COPIED into a real tier folder, which is the whole point: editing
 * your copy can never damage the thing you'd want to compare it against.
 *
 * The `__` prefix is load-bearing rather than decorative. It makes "this is not an installed theme"
 * a property of the name that any code path can check, instead of a list every new write path has to
 * remember to consult — see the containment note on {@link ENGINE_SUBFOLDERS}, which already refuses
 * agent-driven writes to anything that isn't a direct child of the root or of an engine subfolder.
 */
export const THEME_CATALOG_DIR = "__original-themes__";

/**
 * Prefix of the scratch directory `migrate-theme.ts`'s `createStagingDir` creates as a sibling of the
 * real theme folder it's migrating (`.tovu-migrate-staging-<id>-<random-hex>`), and deliberately
 * LEAVES ON DISK after a dry run or a failed migration for inspection (see that module's own header).
 * Not a tier and not a theme — same status as {@link THEME_CATALOG_DIR}
 * — but unlike that fixed name, discovery can't skip it by exact-name `exclude` because the
 * random suffix makes every occurrence's name unique; {@link discoverThemes} matches on this prefix
 * instead. ARCH-001 (2026-08-19): two such directories were swept into a commit by a broad `git add`
 * and discovered as three "basic"-id themes (the real one plus both scratch copies, which retain the
 * migrated manifest's `id`) before this constant existed to filter them out.
 *
 * `duplicate-theme.ts` stages a whole-theme copy under this same prefix (`<prefix>duplicate-<id>-<hex>`)
 * before renaming it into place, so every reader that already skips migration scratch (discovery,
 * `publish-content.ts`, `theme-static-assets.ts`) skips a half-written duplicate too, with no new rule.
 * Unlike a migration's, that scratch is removed on failure.
 */
export const MIGRATION_STAGING_DIR_PREFIX = ".tovu-migrate-staging-";

/**
 * The deleted theme marketplace's fixture folder name. The marketplace (and the fixture, gone since
 * `8fb1f2fea`) was removed 2026-10-04, but a site whose `themes/` was seeded before then still has a
 * copy of this folder under its own themes root. Discovery keeps skipping it so that leftover never
 * surfaces as an invalid "__marketplace__" theme, with no manual cleanup needed.
 */
const LEGACY_MARKETPLACE_DIR = "__marketplace__";

/**
 * Publish's own scratch folders at the themes ROOT (`publish-files-plan-2026-09-24.md` §3):
 * `theme-files` apply stages an incoming tree under {@link PUBLISH_STAGING_DIR} and moves the tree
 * it replaces under {@link PUBLISH_PREVIOUS_DIR}, so the swap is two renames on one filesystem. Not
 * tiers and not themes — {@link discoverThemes} skips both by name, as the site backup does.
 */
export const PUBLISH_STAGING_DIR = ".publish-staging";
export const PUBLISH_PREVIOUS_DIR = ".publish-previous";

/**
 * Discover every built-in theme across the top-level (declarative) folder plus every engine
 * subfolder in {@link ENGINE_SUBFOLDERS}. The one call site every composition root should use
 * instead of a raw {@link discoverThemes} call, so the liquidjs/handlebars split is a detail this
 * function owns rather than something every caller re-derives.
 */
export function discoverAllBuiltInThemes(
  required: { dir: string; source: "built-in" | "site" },
  _optional: Record<string, never> = {}
): DiscoveredTheme[] {
  const { dir, source } = required;
  const topLevel = discoverThemes({
    dir,
    source,
    exclude: [...ENGINE_SUBFOLDERS, THEME_CATALOG_DIR, LEGACY_MARKETPLACE_DIR],
  });
  const engineThemes = ENGINE_SUBFOLDERS.flatMap((sub) => discoverThemes({ dir: join(dir, sub), source }));
  return [...topLevel, ...engineThemes].sort((a, b) => a.manifest.id.localeCompare(b.manifest.id));
}

/**
 * Assign a folder-safe id for a NEW theme being installed under `themesRoot`, guaranteeing it does
 * not collide with anything already there. Theme ids are unique per FOLDER, not globally (see
 * {@link duplicateThemeIds}) — the fix is to never create a second folder claiming an id already in
 * use, which is what this makes possible at the call site that creates theme folders today
 * (`development/scripts/theme-tool.ts`'s `copy` command).
 *
 * Checks BOTH the installed tier folder (`<themesRoot>/<tier>/<id>`) and the catalog
 * (`<themesRoot>/{@link THEME_CATALOG_DIR}/<tier>/<id>`) — the two are kept in step, so
 * a folder existing in only one of them (e.g. a previous run left the pair out of sync) still counts
 * as taken. Picking an id free in one and not the other would recreate the exact desync this exists
 * to prevent.
 *
 * `desiredId` is only ever SUFFIXED, never renumbered: an id that already ends in a digit (e.g.
 * `basic9`) gets `basic9-1` on collision, not `basic10` — the suffix always unambiguously means "the
 * Nth copy of this id", never a digit that could be mistaken for part of the original id.
 *
 * @param required.desiredId - The id to try first (typically the source theme's own `theme.json` id).
 * @param required.themesRoot - The themes root both the tier folder and the catalog live under.
 * @param required.tier - Which {@link ENGINE_SUBFOLDERS} tier's folder to check.
 * @param optional.alsoTaken - Extra "taken" rule ORed with the two folder checks. `duplicate-theme.ts`
 * passes every discovered id (ids must stay unique across tiers too — {@link duplicateThemeIds}) and
 * the source theme's own parent folder (a legacy top-level theme's copy lands beside it, not under
 * `<tier>/`). Omitted, only the two folder checks apply — the CLI's original behavior.
 * @returns `desiredId` if free, else `desiredId-1`, `desiredId-2`, … — the first free suffix.
 * @complexity O(n) filesystem existence checks, where n is the number of prior collisions on
 * `desiredId` (2 checks each, plus one `alsoTaken` call); O(1) in the common, no-collision case.
 */
export function nextAvailableThemeId(
  required: { desiredId: string; themesRoot: string; tier: ThemeTier },
  optional: { alsoTaken?: (id: string) => boolean } = {}
): string {
  const { desiredId, themesRoot, tier } = required;
  const isTaken = (id: string): boolean =>
    existsSync(join(themesRoot, tier, id)) ||
    existsSync(join(themesRoot, THEME_CATALOG_DIR, tier, id)) ||
    optional.alsoTaken?.(id) === true;

  if (!isTaken(desiredId)) return desiredId;

  let suffix = 1;
  while (isTaken(`${desiredId}-${suffix}`)) suffix += 1;
  return `${desiredId}-${suffix}`;
}

/**
 * Re-run discovery and refill `themes` IN PLACE with the result.
 *
 * Discovery is otherwise a boot-time snapshot: the composition root calls {@link
 * discoverAllBuiltInThemes} once and freezes the array into `RouteDeps.themes`, so a theme that
 * appears on disk afterwards — copied from the originals catalog,
 * dropped in by hand, pulled in by git — is invisible until the process restarts. That is fine for a
 * server whose themes only ever ship with it, and wrong for one where copying a theme is a normal
 * thing a user does in the admin UI.
 *
 * Mutates rather than returns because `RouteDeps.themes` is a plain array every consumer already
 * holds a reference to and reads per request (`deps.themes.find(...)` at request time, not at
 * registration time). Refilling that one array updates every reader at once; handing back a new array
 * would update only whoever remembered to re-read it, which is the same staleness bug one level in.
 *
 * Returns what changed so a caller can report it — a rescan that silently finds nothing is
 * indistinguishable from a rescan that didn't run.
 */
export function rescanThemes(
  required: { themes: DiscoveredTheme[]; dir: string; source?: "built-in" | "site" },
  _optional: Record<string, never> = {}
): { added: string[]; removed: string[]; total: number } {
  const { themes, dir, source = "built-in" } = required;
  const before = new Set(themes.map((t) => t.manifest.id));
  const fresh = discoverAllBuiltInThemes({ dir, source });
  const after = new Set(fresh.map((t) => t.manifest.id));

  themes.length = 0;
  themes.push(...fresh);

  return {
    added: [...after].filter((id) => !before.has(id)).sort(),
    removed: [...before].filter((id) => !after.has(id)).sort(),
    total: fresh.length,
  };
}

/**
 * Theme ids that more than one discovered theme claims.
 *
 * Ids are unique per FOLDER, not globally: `loadTheme` only checks that `theme.json`'s `id` equals
 * its own folder name, and {@link discoverAllBuiltInThemes} concatenates the top level with every
 * engine subfolder. So `static/nordic` and `handlebars/nordic` both load, both claim `nordic`, and
 * {@link findTheme} silently returns whichever sorts first — meaning `active_theme_id` can name two
 * different themes and the site renders one of them with no error anywhere.
 *
 * Surfaced rather than resolved: picking a winner here would hide the collision, and the real fix is
 * assigning a unique id when the theme is created (a download/copy appends `-1`, `-2`, …). This is
 * what lets the admin say so instead of rendering the wrong theme quietly.
 */
export function duplicateThemeIds(themes: DiscoveredTheme[]): string[] {
  const seen = new Set<string>();
  const duplicates = new Set<string>();
  for (const theme of themes) {
    if (seen.has(theme.manifest.id)) duplicates.add(theme.manifest.id);
    seen.add(theme.manifest.id);
  }
  return [...duplicates].sort();
}

/** Ids of discovered themes that passed validation. */
export function validThemeIds(themes: DiscoveredTheme[]): string[] {
  return themes.filter((t) => t.status === "valid").map((t) => t.manifest.id);
}

/** Find a theme by id (any status). */
export function findTheme(
  required: { themes: DiscoveredTheme[]; id: string },
  _optional: Record<string, never> = {}
): DiscoveredTheme | undefined {
  const { themes, id } = required;
  return themes.find((t) => t.manifest.id === id);
}

/**
 * {@link findTheme} for a STORED id (the active-theme setting), which may name a renamed theme by
 * its retired id or name the current id on a site that still only has the retired folder. Tries
 * `themeIdCandidates(id)` in order (current name first). Explicit per-theme admin routes keep using
 * the exact {@link findTheme}: they address a theme the listing just showed, by its real id.
 */
export function findStoredTheme(required: { themes: DiscoveredTheme[]; id: string }): DiscoveredTheme | undefined {
  for (const candidate of themeIdCandidates(required.id)) {
    const theme = findTheme({ themes: required.themes, id: candidate });
    if (theme) return theme;
  }
  return undefined;
}

export { resolveTemplateId, resolveLiquidTemplateId, resolveHandlebarsTemplateId } from "./render-contract.js";

