import { parse, type DefaultTreeAdapterMap } from 'parse5';
import { createAnnotatedActionsScript } from './generated/annotated-actions-script.js';
import { PUBLISHED_WEBMCP_CONFIRMATION } from './webmcp-i18n.js';

type Node = DefaultTreeAdapterMap['childNode'];
const SCRIPT_MARKER = 'data-tovu-webmcp-script';
const FORM_ATTRIBUTES = new Set(['toolname', 'tooldescription', 'toolautosubmit', 'toolparamtitle', 'toolparamdescription']);

function formToolAttributeRanges(
  { node }: { node: DefaultTreeAdapterMap['element'] },
  _optional: Record<string, never> = {},
): { startOffset: number; endOffset: number }[] {
  const ranges: { startOffset: number; endOffset: number }[] = [];
  for (const attr of node.attrs) {
    const range = node.sourceCodeLocation?.attrs?.[attr.name];
    if (range && FORM_ATTRIBUTES.has(attr.name)) ranges.push(range);
  }
  return ranges;
}

/** Collect only actual HTML attribute/script ranges, including nested templates.
 * @complexity O(n + r log r) in document bytes and r removed ranges. */
function nativeFormToolRanges({ html }: { html: string }, _options = {}): { startOffset: number; endOffset: number }[] {
  const document = parse(html, { sourceCodeLocationInfo: true });
  const stack: Node[] = [...document.childNodes];
  const ranges: { startOffset: number; endOffset: number }[] = [];
  while (stack.length) {
    const node = stack.pop()!;
    if (!('tagName' in node)) continue;
    if (node.tagName === 'script' && node.attrs.some(attr => attr.name === SCRIPT_MARKER) && node.sourceCodeLocation) {
      ranges.push(node.sourceCodeLocation);
      continue;
    }
    ranges.push(...formToolAttributeRanges({ node }));
    stack.push(...node.childNodes);
    if (node.tagName === 'template') stack.push(...(node as DefaultTreeAdapterMap['template']).content.childNodes);
  }
  ranges.sort((a, b) => b.startOffset - a.startOffset);
  return ranges;
}

/** Remove only actual HTML attribute ranges. Re-serializing trusted HTML would
 * change scripts, embeds, formatting and template content on every opt-out.
 * Reparse after removal: parse5 hides duplicate attributes, which otherwise become live when
 * the browser parses the edited bytes. Each pass removes at least one attribute or script.
 * @complexity O(d × (n + r log r)) time, O(n) space, for d duplicate layers,
 * n HTML bytes and r removed ranges per pass; preserves unrelated source bytes. */
function withoutNativeFormTools({ html }: { html: string }, _options = {}): string {
  for (let ranges = nativeFormToolRanges({ html }); ranges.length > 0; ranges = nativeFormToolRanges({ html })) {
    const parts: string[] = [];
    let end = html.length;
    for (const range of ranges) {
      parts.push(html.slice(range.endOffset, end));
      end = range.startOffset;
    }
    parts.push(html.slice(0, end));
    html = parts.reverse().join('');
  }
  return html;
}

/** Server-side switch controls script delivery AND native declarative discovery. */
export function injectPublishedWebMcp(
  { html, enabled }: { html: string; enabled: boolean },
  _optional: Record<string, never> = {},
): string {
  if (!enabled) return withoutNativeFormTools({ html });
  if (html.includes(`<script ${SCRIPT_MARKER}`)) return html;
  // The host’s own browser tools are necessary: this script only reads a preference,
  // registers local actions, and writes no storage or cookies.
  const script = `<script ${SCRIPT_MARKER}>${createAnnotatedActionsScript({ preferenceKey: 'tovu.admin.webmcp.enabled', confirmationMessage: PUBLISHED_WEBMCP_CONFIRMATION.en, confirmationMessages: PUBLISHED_WEBMCP_CONFIRMATION })}</script>`;
  const bodyEnd = html.toLowerCase().lastIndexOf('</body>');
  return bodyEnd < 0 ? html + script : html.slice(0, bodyEnd) + script + html.slice(bodyEnd);
}

/**
 * @file The Widgets agent-tool catalog (SPEC-043, ADR-047) — this domain's instance of the
 * per-domain `agent-tools.ts` convention `forms/agent-tools.ts` and `identity/agent-tools.ts`
 * already use.
 *
 * Purpose:
 * A static, in-process catalog describing every agent-callable tool this domain exposes and the
 * permission each carries. Every entry maps 1:1 onto a real exported function of
 * `Jini/packages/cms/src/widgets/write-service.ts`, `Jini/packages/cms/src/widgets/region-area-service.ts`, or `Jini/packages/cms/src/widgets/embed-service.ts` (plus
 * two pure reads over `Jini/packages/cms/src/widgets/read-service.ts` and `widgetBindingRepo`) — this catalog never names
 * an operation the domain cannot perform.
 *
 * Precedent already in this repo: ADR-047 §5 (REQ-35/44) ships its OWN bespoke "AI tool surface" as
 * HTTP routes (`server/routes/admin/widgets/agent-tools.ts`: `widgets.place`/`widgets.create`/
 * `widgets.remove`/`widgets.diagnose`), a DIFFERENT delivery mechanism than the ADR-049
 * `tool-registrations.ts` MCP path this catalog wires into. That file's own reasoning — every call
 * maps 1:1 to the SAME domain functions the human admin routes use, gated by the SAME `widgets.*`
 * permission check — is exactly this catalog's discipline too, just delivered through the newer
 * mechanism. Notably, that pre-existing surface deliberately ships NO delete/purge tool at all; this
 * catalog's own exclusion below independently arrives at the same boundary.
 *
 * Deliberate absences (the point of a catalog, not an oversight):
 * - There is NO `widgets_purge_instance`. A permanent delete exists only as the Trash screen's purge
 *   (a human action); the old `purgeWidgetInstance` rung was retired with the generic Trash
 *   (2026-09-21).
 * - There is NO widget-type "delete"/"unregister" tool. `Jini/packages/cms/src/widgets/registry.ts`'s
 *   `WIDGET_TYPE_REGISTRATIONS` is core-declared, static data with no admin HTTP surface at all —
 *   wrapping it would invent capability beyond what the human admin UI exposes.
 *
 * What IS included, and why it is safe: `widgets_trash_instance` (`trashWidgetInstance`) is
 * UNCONDITIONAL and non-destructive to data (a status flip only, exactly what a human gets from one
 * click on the admin "trash" button — no additional agent-reachable capability). Region placement
 * and embed mutations (`widgets_set_region_placements`, `widgets_insert_embed`, `widgets_remove_embed`,
 * `widgets_reorder_embeds`) all route through the SAME REQ-16/17/19/20 existence/liveness/recursion/
 * count guardrails a human editor's calls do — nothing here bypasses them.
 *
 * How it relates to the project:
 * `assistant/tool-registrations.ts` maps these entries into `@jini-ai/core` `ToolRegistration`s.
 * Every mutating entry's underlying function calls `requireWidgetPermission` as its own first line
 * (REQ-40/41 — "the SAME check applies whether the caller is a human route or an AI tool route"),
 * so `ToolPolicy.authorize` stays a pass-through exactly as it does for Forms/Identity/content-types
 * (ADR-021 §2 "one evaluator"). The two read tools (`widgets_get_region`/`widgets_list_regions`, both published as the single
 * `content_read.widget_region` card since 2026-09-08) have
 * no such service-layer wrapper to delegate to — `regions-list.ts`/`region-get.ts` gate inline via
 * `requireWidgetsPermissionOrRespond` instead — so this catalog's wiring layer performs that same
 * inline `widgets.read` check itself for those two, mirroring the HTTP route exactly.
 *
 * Architectural role:
 * `widgets` domain declaration. Imports only `WidgetTypeKey`/`WIDGET_TYPE_REGISTRATIONS` from its
 * own registry, so the published `widgetType` enum cannot drift from what the domain actually
 * accepts.
 */

import { WIDGET_TYPE_REGISTRATIONS } from "@jini-ai/cms/widgets";

export type AgentToolSideEffect = "none" | "mutates-durable-state" | "mints-token";

export type AgentToolActorClassRule = "confirmer-must-equal-own-delegatedBy" | "user-only" | "none";

