// The parent-watchdog doc (why, checks, escape hatch, platform posture) moved with the code.
import { startOwnParentWatchdog } from "./server/runtime/boot/parent-watchdog.js";

/**
 * @file Process entrypoint.
 *
 * Starts the HTTP server for the local runtime.
 *
 * Storage: SQLite content.db by default (persists across restarts). Set
 * `TOVU_DB=memory` for an ephemeral in-memory store (re-seeded every boot).
 * Override the db location with `TOVU_CONTENT_DB=/path/to/content.db`.
 *
 * SPIKE: on the SQLite runtime, the sample Tier-3 store plugin is activated at boot — it declares
 * its own table through the never-brick dataModule seam, seeds products, and surfaces them at /store.
 */
let port = Number(process.env.PORT ?? 3000);
const autoStartPort = process.env.TOVU_START_AUTO_PORT === "1";
delete process.env.TOVU_START_AUTO_PORT;
const useMemory = process.env.TOVU_DB === "memory";
// LAN-bind plan (2026-09-23): `undefined` is this entry point's OWN existing default (Node's own
// all-interfaces bind) — unchanged, per the plan's Decision (a container has to listen on every
// interface; Docker, compose and every container host run this file). `TOVU_HOST` now lets an operator
// narrow it, the same resolver `tovu serve` uses (`cli/commands/serve.ts`) for its own, opposite,
// default.
const bindHost = resolveBindHost(process.env.TOVU_HOST, undefined);

// Same repo-root `.certs/` cert pair `apps/admin/vite.config.ts`'s gate reads — found by walking up
// from this module's own location (`resolveCheckoutRoot`), not `process.cwd()`, per the daemon-cwd
// trap already documented elsewhere in this codebase: a boot launched from a different working
// directory must still find the same cert pair. A fixed `../` count was right for tsx only; the
// compiled `dist/src/index.js` sits two levels shallower, so `npm start` silently served plain HTTP.
const devTls = resolveDevTls(resolveDevTlsCertPaths(resolveCheckoutRoot()));
const devScheme = deriveDevScheme(devTls.active);

// Armed as early as possible, before any of the slower boot work in `main()` below — so a parent
// death during this process's own boot is caught too, not only once it has reached steady state.
// Same placement rationale as the daemon's own `startParentWatchdog()` call.
startOwnParentWatchdog({
  env: process.env,
  ppid: () => process.ppid,
  signalZero: (pid) => { process.kill(pid, 0); },
  exit: (code) => { process.exit(code); },
  log: (line) => console.log(line),
  error: (line) => console.error(line),
  setInterval: (callback, ms) => setInterval(callback, ms),
});

/**
 * Applies the same schema-version guard `tovu serve` gets for free from `boot-site-dir.ts` (see
 * `content-db-schema-guard.ts`'s own header for why the non-CLI boot path had no equivalent at
 * all): refuses to boot, rather than silently letting `createSiteRouteDeps()` -> `openContentDb()`
 * migrate forward, when `dbPath` is newer than or has diverged from this runtime's bundled
 * migrations. REFUSE (not warn-and-continue) — chosen for parity with `tovu serve`'s own
 * unconditional throw in this exact situation ("the two paths should not diverge on safety"), and
 * because a warning a developer can scroll past protects real on-disk data no better than doing
 * nothing. A no-op for `useMemory` boots (nothing on disk to guard) and for a brand-new/never-
 * migrated db (nothing to compare against yet — `openContentDb()`'s own first-boot path is correct).
 */
async function guardContentDbSchemaOrExit(dbPath: string): Promise<void> {
  const result = await checkContentDbSchema(dbPath);
  if (result.status !== "refuse") return;

  console.error(`[content-db-schema-guard] ${result.message}`);
  console.error(
    `Refusing to boot against ${dbPath} — this is the same schema guard 'tovu serve' applies before opening a site's content.db.`
  );
  process.exit(1);
}

/**
 * `ensureSiteKeyForBoot` mints a key-only `.site-meta.json` for a dev site (it runs before the db is
 * opened, so it cannot know the schema stamp). Once the composition has migrated the db, complete it
 * — the same completion `bootSiteDir` runs — so this folder also starts through `tovu serve` and the
 * desktop. This boot never reads the meta, so a failure only warns.
 */
async function completeDevSiteMetaOrWarn(dir: string): Promise<void> {
  try {
    await completeKeyOnlySiteMeta({ dir });
  } catch (err) {
    console.warn(`[site-meta] could not complete the key-only .site-meta.json in ${dir}: ${(err as Error).message}`);
  }
}

async function prepareSiteBoot(
  { useMemory }: { useMemory: boolean },
  _options: Record<string, never> = {},
): Promise<ReturnType<typeof claimSiteRunning> | undefined> {
  // Fixes a live-found crash (2026-08-16, `process-error-guards.ts`'s own header has the full
  // account): an unhandled async rejection anywhere beneath an Express 4 route handler used to take
  // down this ENTIRE process, not just the one request that triggered it. Placed first — before any
  // boot step below can trigger background work. main()'s own rejection is fatal and caught at
  // the entrypoint below; this guard protects request-time and background rejections only.
  installUnhandledRejectionGuard();
  if (!useMemory) pinDefaultSiteRoot({}, {});
  // Server log capture (gap A-04): keeps recent console output in memory, redacted, so the admin
  // server-logs route and the `system_read_server_logs` chat tool can show recent errors. Installed
  // right after the rejection guard so boot-time failures are captured too.
  installServerLogCapture({ release: processBuildRelease({}), environment: telemetryEnvironment({ env: process.env }) });
  // Persist it to `<site>/ops/logs/server.log` (L2) so errors survive a restart, and read the agent
  // daemon's `daemon.log` alongside it. A memory-DB run has no site of its own to write into.
  if (!useMemory) {
    const logFiles = serverLogFilePaths({ siteDir: siteDir() });
    attachServerLogFile({ filePath: logFiles.server }, { alsoRead: [logFiles.daemon] });
  }

  // Mints `TOVU_AGENT_DAEMON_TOKEN` (unless the operator already set one) into this process's env
  // so `startAssistantDaemon()` — called much later, from inside `app.listen()`'s callback — hands
  // it to the daemon child (and every respawn after it) through the inherited env, and so
  // `server/modules/assistant.ts`'s proxy
  // can read it at request time. Must precede the spawn; placed first because it is the one boot
  // step with no dependency on anything at all. It is a single synchronous env assignment (no
  // import, no await, no I/O), so it does not weaken `registerPluginSdkResolver`'s ordering
  // guarantee documented immediately below — there is still no `await` point ahead of it.
  ensureAgentDaemonToken({}, {});
  // The tool RPC token (ADR-070) stays in module memory, NOT this env: see `daemon-access.ts`.
  ensureToolExecToken({}, {});

  // SPEC-005 (ADR-005-ARCH, CIC U-002, ESCALATE_SECURITY): must run synchronously, before any
  // other boot step, and unconditionally before `createApp(deps)` wires any route or before any
  // code path could reach `loadPlugin()`'s dynamic `import()`. Placed first in `main()` — even
  // before `runProductionReadinessGateOrExit()` — so no `await` point exists between process start
  // and this registration where a plugin import could theoretically become reachable first. Mirrors
  // this file's own placement rationale for that gate: `index.ts` is the one real top-level boot
  // path (never imported by a test), so it is the safe place to enforce this ordering without
  // touching `app.ts`/`deps.ts`'s synchronous, widely-tested call signatures (W-001).
  registerPluginSdkResolver();

  await runProductionReadinessGateOrExit();

  // Claim before the schema guard, which already opens the site's database.
  const runningLease = useMemory ? undefined : claimSiteRunning({ dir: siteDir(), app: "Web", scheme: devTls.active ? "https" : "http" });
  if (!useMemory) reportSitesSyncWarning({});
  if (!useMemory) await guardContentDbSchemaOrExit(defaultContentDbPath());
  // site-key plan §A3a: gated identically to the schema guard right above — a `:memory:` boot has
  // no site directory at all, so there is nowhere for `ensureSiteKeyForBoot` to look. Must precede
  // `createSiteRouteDeps` below, which is what actually resolves the site key this may have just
  // adopted or minted.
  if (!useMemory) await ensureSiteKeyForBoot({ siteDir: siteDir(), findSiteKeyDependentData });

  // The LOCAL-mode counterpart to the production readiness gate, which returns immediately outside
  // production. "Do not refuse to boot without a site key" was implemented as "do not mention it",
  // and that silence cost an afternoon on 2026-09-18 — see `site-key-boot-notice.ts`'s own header.
  // Warns and carries on; never refuses, never throws. After the ensure above and given the site,
  // so a fresh site's just-minted per-site key counts (2026-10-22: it warned "no key file at .").
  warnIfNoSiteKeyAtBoot(useMemory ? {} : { siteDir: siteDir() });

  return runningLease;
}

async function reserveSiteBootListener(
  { server, runningLease }: {
    server: ReturnType<typeof createHttpServer>;
    runningLease: ReturnType<typeof claimSiteRunning> | undefined;
  },
  _options: Record<string, never> = {},
): Promise<void> {
  // WHY THIS EXISTS: without it, a listen failure is an unhandled `'error'` event on the Server,
  // which Node re-throws — so the process dies with a raw stack trace and no statement of what is
  // wrong. Measured 2026-08-15: `tsx watch` restarted this process on a source edit, force-killed
  // the previous one after its 5s grace period ("Process didn't exit in 5s"), and the replacement
  // hit the still-held port. What the operator saw was a dead server and a login page that would
  // not authenticate; what they needed to see was "port 3000 is already in use".
  //
  // EADDRINUSE gets a named, actionable message because it is the one failure here with an obvious
  // operator fix. Everything else re-raises rather than being swallowed into a generic line — an
  // unknown listen failure should still surface its own error, just not as an unhandled event.
  //
  // Pinned/dev entrypoints use `exit(1)` rather than a retry loop: a port collision in dev means
  // another Tovu is already serving, and silently retrying would make two processes race for the port on every restart.
  // `dev.mjs` already preflights ports and names the holder; `dev:server` alone does not, which is
  // exactly the path this was hit on. Only npm start opts into direct-bind retries.
  try {
    port = await reserveBootListener({ server, port, bindHost }, { autoStartPort });
    process.env.PORT = String(port);
    pinSiteListenerOrigin({ scheme: devTls.active ? "https" : "http", host: bindHost, port });
    runningLease?.ready({ port });
  } catch (caught) {
    const error = caught as NodeJS.ErrnoException;
    if (error.code === "EADDRINUSE") {
      console.error(
        `Refusing to start: port ${port} is already in use.\n` +
          `  Another Tovu (or an orphan from a previous run) is still holding it.\n` +
          `  Find it with:  lsof -ti :${port} -sTCP:LISTEN\n` +
          `  Then stop that process, or set PORT to a free port.`,
      );
      process.exit(1);
    }
    throw error;
  }
}

async function main(): Promise<void> {
  const runningLease = await prepareSiteBoot({ useMemory }, {});

  // Reserve the actual HTTP(S) listener before composition derives origins or spawns daemons.
  // During boot it answers 503; attaching the app later keeps this SAME socket bound throughout.
  let requestHandler: import("node:http").RequestListener = (_request, response) => {
    response.writeHead(503, { "Retry-After": "1" });
    response.end("Server is starting");
  };
  const server = devTls.active && devTls.credentials
    ? createHttpsServer(devTls.credentials, (request, response) => requestHandler(request, response))
    : createHttpServer((request, response) => requestHandler(request, response));
  await reserveSiteBootListener({ server, runningLease }, {});

  server.on("error", (error: Error) => { throw error; });

  // The store the composition opens: a PGlite owner's socket goes to the agent daemon below.
  let siteStore: SiteStore | undefined;
  // The in-memory root scans no plugin folder unless one is named: an explicit TOVU_PLUGINS_DIR
  // (journeys, local opt-in installs) gets the same installer the SQLite root always has.
  const deps = useMemory
    ? createRouteDeps(process.env.TOVU_PLUGINS_DIR ? { installDir: resolvePath(process.env.TOVU_PLUGINS_DIR) } : {})
    : await createSiteRouteDeps(defaultContentDbPath(), { onStoreOpened: (store) => (siteStore = store) });
  // Unhandled rejections/exceptions reach the error tracker too, now that its port exists.
  installProcessErrorReporting({ tracker: deps.tracker, processRole: "server" }, { flush: deps.flushTelemetry });
  if (!useMemory) await completeDevSiteMetaOrWarn(siteDir());
  // Boot passes the composition starts and never awaits, which read the store: the legacy
  // publish-credential tail here, `createServingApp`'s BYOK pass below. The store close waits for
  // them (bounded), or a site stopped seconds after boot closes under them (see `await-boot-work.ts`).
  const bootWork: Promise<unknown>[] = [];
  if (deps.legacyPublishCredentialsReady) bootWork.push(deps.legacyPublishCredentialsReady);
  // Set once `createServingApp` below has started the background loops: stops them and the listener
  // before the store closes, so a drain awaiting a subscriber is not cut off mid-delivery.
  let stopServing: () => Promise<void> = async () => {};
  // Every store closes on shutdown; SQLite close checkpoints and removes its WAL/SHM sidecars.
  const storeOwnsShutdown =
    siteStore !== undefined &&
    closeStoreOnShutdown(
      { store: siteStore, onShutdown: shutdownAssistantDaemon },
      { bootWork: () => bootWork, stopServing: () => stopServing() }
    );

  // ADR-046 Phase 3 (SPEC-031): the boot-module composition itself now lives in
  // `server/runtime/boot/bootstrap.ts` (unit-testable, unlike this file — see the note above on why
  // boot-only enforcement stays here while the composable logic does not).
  const bootResult = await runBootLifecycle(buildBootModules(deps, { useMemory, defaultContentDbPath }));
  setReadinessSnapshot(bootResult);
  if (!bootResult.ok) {
    logCriticalBootFailures(bootResult);
    console.error("Refusing to boot — a critical module failed. See failures above.");
    process.exit(1);
  }

  // Self-allocation fix (2026-08-28): must resolve — and, when neither `JINI_AGENT_DAEMON_URL` nor
  // `JINI_AGENT_DAEMON_PORT` is set, allocate — the daemon's origin BEFORE `createApp()` wires the
  // assistant proxy's routes, so no inbound request can ever reach `getAgentDaemonUrl()` before it
  // has something to return. See `agent-daemon-port.ts`'s own header for the full contract.
  await assertSafeOwnerCredentialBeforeListen({ deps, host: bindHost });
  await ensureAgentDaemonPortResolved();

  // `createServingApp`, not bare `createApp`: it also starts the background outbox drainer, after
  // `createApp` has attached every subscriber. The drainer's timer is unref'd, so it never holds this
  // process open.
  const { app, outboxDrainer, trashSweeper, themeWatcher, formPullTrigger, postGoLiveSweep, webhookDeliveryWorker, domainBindingSweeper, siteSearchMaintenance, bootWork: servingBootWork } = createServingApp(deps);
  bootWork.push(...servingBootWork);
  stopServing = () => stopServingWithinGrace({ server, workers: [outboxDrainer, { stop: () => trashSweeper.stop({}) }, themeWatcher, formPullTrigger, postGoLiveSweep, webhookDeliveryWorker, domainBindingSweeper, siteSearchMaintenance] });
  // TLS-gated the same way `apps/admin/vite.config.ts` gates Vite's own dev server: cert pair
  // present -> HTTPS, absent -> plain HTTP/1.1 (`devTls`/`devScheme`, computed above at module
  // load). Express 4 has no native HTTP/2 support (no `spdy`/`http2` compat shim added here), so
  // this is TLS-only, not HTTP/2, unlike Vite's dev server which gets HTTP/2 for free from the same
  // cert pair.
  //
  // TRIED AND REVERTED (2026-09-06): `http2.createSecureServer({ ...devTls.credentials, allowHTTP1:
  // true }, app)` was attempted here, specifically to close the connection-exhaustion risk
  // `apps/admin/vite.config.ts`'s own HTTP/2 gate exists for, now that `/admin/*` is proxied through
  // this same server (`admin-dev-proxy.ts`) instead of served directly by Vite. It crashed the
  // ENTIRE process, reproducibly, three separate boots in a row, always within ~15s of steady state
  // with an admin tab open — not from any exotic client, just ordinary ambient traffic (this repo's
  // own SSE endpoints reconnecting, e.g. `settings/events`, `frontend-sessions/stream`):
  //
  //   TypeError: Cannot read properties of undefined (reading 'readable')
  //       at IncomingMessage._read (node:_http_incoming:211:19)
  //       at Readable.read (node:internal/streams/readable:737:12)
  //       at resume_ (node:internal/streams/readable:1260:12)
  //
  // Every frame is inside Node core (`node:_http_incoming`, `node:internal/streams/readable`) — none
  // of this repo's own code appears anywhere in the trace — on Node v24.2.0. A/B-confirmed: reverting
  // to plain `createHttpsServer` under the identical ambient conditions (same open admin tab, same
  // reconnecting SSE clients) ran stable for 15s+ with no crash; restoring the http2 line crashed it
  // again on the next boot. This reads as a Node-core bug/incompatibility in the `allowHTTP1`
  // fallback's interaction with a long-lived HTTP/1.1 stream (most likely an SSE `EventSource`
  // reconnect), not something fixable from application code — per this task's own instruction, a
  // half-migrated server that dies under ordinary load is worse than the HTTP/1.1 status quo it
  // would replace, so this was reverted rather than shipped. The two adjustments this attempt made to
  // get past HTTP/2's *header*-level incompatibilities (`admin-dev-proxy.ts`'s hop-by-hop header
  // stripping, and the SSE routes' conditional `Connection` header) are harmless under HTTP/1.1 and
  // were kept — see each site's own comment — but they alone do not make this server HTTP/2-safe;
  // the crash above is a transport-level fault, not a header-level one. Revisiting this needs either
  // a newer/older Node where this is fixed, or a non-`allowHTTP1`-compat approach (e.g. a real
  // HTTP/2-native framework in front, or `spdy`), verified under the same SSE-reconnect load before
  // it ships.
  // The listener above uses Node's options overload and omits an undefined hostname, preserving
  // the all-interfaces container default without Express's required-hostname overload ambiguity.
  server.once("close", () => {
    void themeWatcher.stop();
    void shutdownLocalSiteHosts({}).catch(() => {});
  });
  requestHandler = app;

  // Forwards Vite's HMR WebSocket through this server's own `upgrade` event when
  // `TOVU_ADMIN_DEV_PROXY_URL` is set — the one thing `admin-static.ts`'s ordinary Express routing
  // cannot carry (an `upgrade` request never reaches Express's request pipeline; it is a raw
  // `http.Server`/`https.Server` event). No-ops in production/SEA builds — see that function's own
  // doc for the precedence this mirrors. Registered on `server` directly rather than `app`, so it
  // works identically whether TLS is active or not.
  registerAdminDevProxyUpgrade(server);
  onListening();

  function onListening() {
    const store = useMemory ? "in-memory" : `sqlite (${defaultContentDbPath()})`;
    console.log(`tovu server running on ${devScheme}://localhost:${port} — store: ${store}`);

    // Readiness before spawn: `app.listen()`'s callback firing says nothing about whether the
    // boot-time seeders have settled, and spawning the daemon early raced them (duplicate identity
    // and `core.execution.mode` rows). The list and the full why live in
    // `server/runtime/boot/site-boot-readiness.ts`, shared with `cli/commands/serve.ts`.
    awaitSiteBootReadiness({ deps })
      .then(async () => {
        if (!(await agentDaemonWanted(deps))) return;
        startAssistantDaemon(
          { workspaceId: deps.workspaceId, siteDir: siteDir(), pgSocketPath: siteStore?.pgliteSocketPath },
          { registerProcessSignalHandlers: !storeOwnsShutdown }
        );
      })
      .catch((error: unknown) => {
        console.error("[index] a boot-readiness promise rejected — not starting the agent daemon", error);
      });
  }

}

// ADR-049 (process-shape correction) — Tovu never spawns a coding-agent CLI itself; that lives
// entirely in `src/assistant/agent-daemon-server.ts`, a separate OS process. `startAssistantDaemon`
// (called above, inside `app.listen()`'s callback, after the boot-readiness promises settle) now
// owns the full spawn-and-supervise lifecycle — including automatic respawn with backoff, a
// crash-loop cap, and the manual restart seam a future admin action can call — in
// `src/assistant/daemon-supervisor.ts`. Moved out of this file because `index.ts` self-invokes
// `main()` at module load (see this file's own header), so it can never be imported by a test;
// `daemon-supervisor.ts` carries the same env-propagation (`TOVU_WORKSPACE`, `TOVU_PARENT_PID`),
// process-group-detachment, and stdio-piping behavior this function used to, unchanged — see that
// file's own header for the full rationale on each.

void main().catch((error: unknown) => reportFatalBootFailure({ error }));

import crypto from "node:crypto";

import { sql } from "kysely";

import { listTables } from "../kernel/dialect.js";
import type { StorageKernel } from "../kernel/port.js";
import { POSTGRES_BASELINE } from "./0000_legacy_baseline.postgres.js";
import { adoptLegacySqlite, readFrozenChain } from "./legacy-sqlite.js";
import { LEDGER_TABLE } from "./runner.js";
import { type MigrationContext, type MigrationStep, LegacyHistoryError } from "./step.js";

/**
 * @file Step `0000_legacy_baseline` (ADR-066 §5–6): everything the schema was at the freeze.
 *
 * - SQLite: adopt in place. `legacy-sqlite.ts` reconciles the database's drizzle history by hash,
 *   applies a missing tail and verifies the schema before the runner records this step (the runner
 *   takes the pre-change copy when its caller asks for one). A brand-new file gets the whole chain.
 *   Nothing is copied or rewritten.
 * - Postgres/PGlite: the frozen baseline statements on an empty schema. A schema that already has
 *   tables but no ledger (e.g. a data dir left by the deleted 2026-09-28 posts-on-PGlite
 *   prototype) is refused: recreate it.
 */

export const LEGACY_BASELINE_ID = "0000_legacy_baseline";

/** What the step applies: the frozen chain's hashes and the Postgres statements. */
export function legacyBaselineChecksum(): string {
  const sqlite = readFrozenChain().map((entry) => [entry.tag, entry.hash]);
  return crypto.createHash("sha256").update(JSON.stringify({ sqlite, postgres: POSTGRES_BASELINE })).digest("hex");
}

async function up(kernel: StorageKernel<unknown>, context: MigrationContext): Promise<void> {
  if (kernel.dialect === "sqlite") return adoptLegacySqlite(kernel, context.note);
  const existing = (await listTables(kernel)).filter((name) => name !== LEDGER_TABLE);
  if (existing.length > 0) {
    throw new LegacyHistoryError(
      `this Postgres schema already has tables (${existing.slice(0, 5).join(", ")}…) but no migration ledger; ` +
        "it was made by the pre-migrator PGlite prototype — recreate the data dir"
    );
  }
  for (const statement of POSTGRES_BASELINE) await kernel.execute(sql.raw(statement));
}

export const legacyBaseline = (checksum: string): MigrationStep => ({ id: LEGACY_BASELINE_ID, checksum, up });

import { sql } from "kysely";

import { tableExists } from "../kernel/dialect.js";
import type { StorageKernel } from "../kernel/port.js";
import type { MigrationContext, MigrationStep } from "./step.js";

/**
 * @file Step `0002_drop_empty_legacy_chat_tables`: the `content.db` half of the two-database split
 * (`0fb84ae0`). Legacy migrations `0023`/`0051` still create the AI chat tables in every SQLite
 * content database, but the chat lives in `chat.db` from the first write on. This drops each of
 * the three that holds NO rows; one with rows (a pre-split install's real history) is left for
 * `sqlite/chat-orphan-check.ts` to keep flagging for a human. Conditional on a row count, which is
 * why it was never a `.sql` migration (SQLite has no `DROP TABLE ... WHERE`).
 *
 * Postgres/PGlite: nothing. Their baseline never had these tables in `public` (chat is in
 * `ai_chat`, ADR-067).
 *
 * Names are written out, not imported from `chat-orphan-check.ts`: the pinned checksum hashes this
 * file.
 */

export const DROP_EMPTY_LEGACY_CHAT_TABLES_ID = "0002_drop_empty_legacy_chat_tables";

const LEGACY_CHAT_TABLES = ["ai_chats", "ai_chat_messages", "assistant_agent_sessions"];

async function up(kernel: StorageKernel<unknown>, context: MigrationContext): Promise<void> {
  if (kernel.dialect !== "sqlite") return;
  for (const table of LEGACY_CHAT_TABLES) {
    if (!(await tableExists(kernel, table))) continue;
    const [row] = await kernel.query<{ n: number }>(sql`SELECT count(*) AS n FROM ${sql.table(table)}`);
    if (Number(row?.n ?? 0) > 0) {
      context.note(`kept legacy chat table ${table}: it has rows`);
      continue;
    }
    await kernel.execute(sql`DROP TABLE ${sql.table(table)}`);
  }
}

export const dropEmptyLegacyChatTables = (checksum: string): MigrationStep => ({ id: DROP_EMPTY_LEGACY_CHAT_TABLES_ID, checksum, up });

import { sql } from "kysely";
import type { StorageKernel } from "../kernel/port.js";
import type { MigrationStep } from "./step.js";

/**
 * @file Owner decision 2026-10-04: a form submission's source IP is cleared after 90 days, so the
 * column must accept NULL. SQLite cannot drop NOT NULL in place, so the table is rebuilt with every
 * row, index and trigger preserved; Postgres drops the constraint. Adds the partial index the
 * daily sweep scans (submissions that still hold an IP, oldest first).
 */
export const SUBMISSION_IP_RETENTION_MIGRATION_ID = "0006_submission_ip_retention";

async function up(kernel: StorageKernel<unknown>): Promise<void> {
  if (kernel.dialect === "sqlite") {
    const columns = await kernel.query<{ name: string; notnull: number }>(sql`PRAGMA table_info(form_submissions)`);
    const ip = columns.find(column => column.name === "source_ip");
    if (!ip) throw new Error("form_submissions.source_ip is missing");
    if (ip.notnull !== 0) {
      const expected = ["id", "workspace_id", "form_definition_id", "data_json", "source_ip", "submitted_at", "deleted_at", "version"];
      if (columns.length !== expected.length || columns.some(column => !expected.includes(column.name))) {
        throw new Error("form_submissions schema changed; revise this migration before applying it");
      }
      // Preserve site-added indexes and triggers as well as the shipped definition/workspace
      // indexes. The migration runner holds the lock and supplies the transaction/rollback.
      const objects = await kernel.query<{ sql: string }>(sql`
        SELECT sql FROM sqlite_master WHERE tbl_name = 'form_submissions'
        AND type IN ('index', 'trigger') AND sql IS NOT NULL
      `);
      const tables = await kernel.query<{ name: string }>(sql`SELECT name FROM sqlite_master WHERE type = 'table'`);
      for (const table of tables) {
        const foreignKeys = await kernel.query<{ table: string }>(sql`PRAGMA foreign_key_list(${sql.ref(table.name)})`);
        if (foreignKeys.some(key => key.table === "form_submissions")) {
          throw new Error("form_submissions acquired an incoming foreign key; revise this migration before applying it");
        }
      }
      await kernel.execute(sql`
        CREATE TABLE form_submissions_ip_retention_new (
          id TEXT PRIMARY KEY NOT NULL,
          workspace_id TEXT NOT NULL,
          form_definition_id TEXT NOT NULL REFERENCES form_definitions(id) ON DELETE RESTRICT,
          data_json TEXT NOT NULL,
          source_ip TEXT,
          submitted_at TEXT NOT NULL,
          deleted_at TEXT,
          version INTEGER NOT NULL DEFAULT 1
        )
      `);
      await kernel.execute(sql`
        INSERT INTO form_submissions_ip_retention_new
          (id, workspace_id, form_definition_id, data_json, source_ip, submitted_at, deleted_at, version)
        SELECT id, workspace_id, form_definition_id, data_json, source_ip, submitted_at, deleted_at, version
        FROM form_submissions
      `);
      await kernel.execute(sql`DROP TABLE form_submissions`);
      await kernel.execute(sql`ALTER TABLE form_submissions_ip_retention_new RENAME TO form_submissions`);
      for (const object of objects) await kernel.execute(sql.raw(object.sql));
    }
  } else {
    await kernel.execute(sql`ALTER TABLE form_submissions ALTER COLUMN source_ip DROP NOT NULL`);
  }
  await kernel.execute(sql`
    CREATE INDEX IF NOT EXISTS idx_form_submissions_ip_retention
    ON form_submissions(submitted_at, id) WHERE source_ip IS NOT NULL
  `);
}

export function submissionIpRetentionMigration(
  { checksum }: { checksum: string },
  _optional: Record<string, never> = {},
): MigrationStep {
  return { id: SUBMISSION_IP_RETENTION_MIGRATION_ID, checksum, up };
}

/**
 * @file Retire the six unwired core commerce tables (owner, 2026-10-11; ADR-066).
 * The store plugin owns live commerce. The parked Jini commerce library and all plugin tables stay.
 * Frozen baselines still create these tables, so fresh installs and upgrades need this forward step.
 * Any populated target refuses the entire step before a DROP. The runner supplies the transaction;
 * SQLite holds BEGIN IMMEDIATE, and Postgres/PGlite locks all existing targets before counting.
 *
 * Historical schema rationale follows, preserved from the removed definitions.
 */

// ---------------------------------------------------------------------------
// Commerce (2026-08-12 swarm-consensus debate, section 5 — "Commerce and the tri-dialect data
// model"). First vertical slice only: catalog (products/prices), orders/order_items, and the
// webhook inbox that makes provider event ingestion idempotent AND ordered. Refunds, proration,
// carts, and multi-provider reconciliation are explicitly next-slice work — see each table's doc.
//
// Column-vs-document rule applied throughout (converged unanimously across the debate): if a
// query, index, constraint, join, or sort ever touches a field, it is a column; if it is read
// back whole by id and only ever rendered, it is JSON, never indexed. The only JSON column in
// this slice is `commerceWebhookEvents.payloadJson` — a provider-owned payload Tovu never
// queries into. Every other field the debate looked at (currency, amounts, status, timestamps,
// the ordering cursor) is a real column, per that rule.
//
// SQLite JSON storage stays `text("*_json")`, matching every other JSON column in this file
// (see this file's own module doc: "portable to Postgres `jsonb` later"). This is a TOOLING
// decision, not a durability or contract one — persisting SQLite's binary JSONB is safe
// (sqlite.org/jsonb.html commits to backward compatibility across versions) and its JSON
// functions (`json()`, `json_extract()`, `jsonb_extract()`, `json_type()`) work directly against
// a `jsonb()`-written BLOB. The actual blocker is that `jsonb()` is NOT a `drizzle-orm/
// sqlite-core` column builder (verified against the installed package: `integer`, `real`,
// `text`, `blob`, `numeric` is the complete list) and Drizzle's `customType.fromDriver` cannot
// rewrite a SELECT to wrap the column in `json(...)`, so binary storage would mean hand-written
// `sql` fragments at every call site. What would change this: a Drizzle `jsonb` column builder,
// or a codegen layer that rewrites SELECTs. The unwired JSONB codec this decision was grounded in
// (`sqlite/jsonb-column.ts`) was deleted in the storage-kernel move; it is in git history.
// ---------------------------------------------------------------------------

/**
 * Commerce products — the sellable thing. Deliberately NOT folded into `memberTiers` above:
 * that table carries `welcomePagePath`/`visibleInPortal` (portal-presentation fields, meaningless
 * for a one-time digital good) and locks pricing to exactly two recurring slots
 * (`monthlyPriceCents`/`yearlyPriceCents`, no one-time representation at all). `grantsMemberTierId`
 * is the one bridge column: set only when purchasing this product is how a member obtains a tier.
 * Commerce owns financial truth; `memberSubscriptions` stays the access-entitlement projection —
 * this slice does not yet derive one from an order (see the commerce feature's own README/report
 * for what remains).
 */

/** Open string, not a DB enum — matches this file's existing convention (e.g. `posts.status`). */

// 'one_time' | 'membership' | 'digital' ...
// 'active' | 'archived'

/**
     * Set only when this product's purchase grants a `memberTiers` row. The composite FK below
     * targets `(memberTiers.workspaceId, memberTiers.id)`, not just `.id` — a plain single-column
     * FK to `memberTiers.id` would accept a tier id that belongs to a DIFFERENT workspace, which
     * is exactly the cross-tenant mistake C2 (every table workspace-scoped) exists to prevent.
     * NULL is exempt from FK enforcement by SQL's ordinary MATCH SIMPLE semantics, so a product
     * with no tier bridge needs no special-casing here.
     */

/**
     * Migration 0038 — variable-key, per-product display attributes (theme example: "Material" ->
     * "Thick premium weight combed cotton", "Care" -> "...", "Warranty" -> "..."; different
     * products use different keys). Column-vs-document call, made explicitly rather than by
     * silently stretching this file's "provider-owned payload" JSON scope: this data is
     * author-owned, not provider-owned, so that framing doesn't literally apply — but the
