/** SQLite cannot DROP a column referenced by a table CHECK. Rebuild its parent, retaining all
 * plain fields and the approval child rows that ON DELETE CASCADE would otherwise remove.
 * The device table references workspaces only and is never read or changed by this step.
 */
async function finishMcp({ kernel }: { kernel: StorageKernel<unknown> }): Promise<void> {
  if (kernel.dialect === "sqlite") {
    const unknownChildren = await kernel.query(sql`SELECT DISTINCT m.name FROM sqlite_schema m,
      pragma_foreign_key_list(m.name) fk WHERE m.type='table' AND fk."table"='external_mcp_servers'
      AND m.name <> 'external_mcp_tool_approvals'`);
    if (unknownChildren.length) throw new Error("secrets vault: unsupported MCP child table; preserve before rebuilding");
    const approvals = await tableExists(kernel, "external_mcp_tool_approvals");
    for (const statement of MCP_VAULT_SQLITE_STATEMENTS) {
      if (!approvals && statement.includes("_vault_mcp_approvals")) continue;
      await kernel.execute(sql.raw(statement));
    }
  } else {
    await kernel.execute(sql`ALTER TABLE external_mcp_servers DROP CONSTRAINT external_mcp_servers_sealed_shape,
      DROP CONSTRAINT external_mcp_servers_oauth_sealed_shape`);
    for (const column of CRYPTO_COLUMNS) await kernel.execute(sql`ALTER TABLE external_mcp_servers DROP COLUMN ${sql.ref(column)}`);
    await kernel.execute(sql`ALTER TABLE external_mcp_servers
      ADD CONSTRAINT external_mcp_env_secret_fk FOREIGN KEY(workspace_id,env_secret_id) REFERENCES secrets_vault(workspace_id,id) ON DELETE RESTRICT,
      ADD CONSTRAINT external_mcp_oauth_secret_fk FOREIGN KEY(workspace_id,oauth_secret_id) REFERENCES secrets_vault(workspace_id,id) ON DELETE RESTRICT`);
    await kernel.execute(sql`CREATE FUNCTION secrets_vault_check_mcp_pointer() RETURNS trigger LANGUAGE plpgsql AS $$
      BEGIN
        IF (NEW.env_secret_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM secrets_vault WHERE workspace_id=NEW.workspace_id AND id=NEW.env_secret_id AND kind='mcp-env' AND owner_key=NEW.server_id))
          OR (NEW.oauth_secret_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM secrets_vault WHERE workspace_id=NEW.workspace_id AND id=NEW.oauth_secret_id AND kind='mcp-auth' AND owner_key=NEW.server_id))
        THEN RAISE EXCEPTION 'invalid vault MCP pointer'; END IF; RETURN NEW;
      END $$`);
    await kernel.execute(sql`CREATE TRIGGER secrets_vault_mcp_pointer BEFORE INSERT OR UPDATE ON external_mcp_servers
      FOR EACH ROW EXECUTE FUNCTION secrets_vault_check_mcp_pointer()`);
    await kernel.execute(sql`CREATE FUNCTION secrets_vault_check_mcp_identity() RETURNS trigger LANGUAGE plpgsql AS $$
      BEGIN
        IF (NEW.kind <> OLD.kind OR NEW.owner_key <> OLD.owner_key) AND EXISTS
          (SELECT 1 FROM external_mcp_servers WHERE workspace_id=OLD.workspace_id AND (env_secret_id=OLD.id OR oauth_secret_id=OLD.id))
        THEN RAISE EXCEPTION 'linked vault MCP identity'; END IF; RETURN NEW;
      END $$`);
    await kernel.execute(sql`CREATE TRIGGER secrets_vault_mcp_identity BEFORE UPDATE OF kind,owner_key ON secrets_vault
      FOR EACH ROW EXECUTE FUNCTION secrets_vault_check_mcp_identity()`);
  }
}

/** O(n log n) CPU/O(n) memory for n credential rows; fixed table reads, one opaque insert per row.
 * Runner supplies the transaction and migration lock. Coverage failure rolls back copies and DDL.
 */
async function up(kernel: StorageKernel<unknown>, context: MigrationContext): Promise<void> {
  const affected = [...SOURCES.map(source => source.table), "external_mcp_servers", "oauth_pending_authorizations", "tovu_migrations"];
  if (await tableExists(kernel, "external_mcp_tool_approvals")) affected.push("external_mcp_tool_approvals");
  if (kernel.dialect === "postgres") {
    // Backups are restore artifacts, never ordinary transfer/export input. A pre-existing backup
    // refuses re-entry rather than overwriting the only old ciphertext or ledger available.
    for (const table of affected) {
      await kernel.execute(sql`LOCK TABLE ${sql.table(table)} IN ACCESS EXCLUSIVE MODE`);
      await kernel.execute(sql`CREATE TABLE ${sql.table(`_vault_backup_${table}`)} AS TABLE ${sql.table(table)}`);
    }
  }
  await createVault({ kernel });
  await kernel.execute(sql`ALTER TABLE external_mcp_servers ADD COLUMN env_secret_id text`);
  await kernel.execute(sql`ALTER TABLE external_mcp_servers ADD COLUMN oauth_secret_id text`);
  const coverage = Object.fromEntries(KINDS.map(kind => [kind, { rows: 0, envelopes: 0 }])) as Coverage;
  const entries: { table: string; kind: VaultKind; row: LegacyRow }[] = [];
  for (const { table, kind } of SOURCES) {
    const rows = await kernel.query<LegacyRow>(sql`SELECT * FROM ${sql.table(table)} ORDER BY workspace_id`);
    coverage[kind].rows += await count({ kernel, table });
    coverage[kind].envelopes += await count({ kernel, table, where: sql`sealed_ciphertext IS NOT NULL` });
    entries.push(...rows.map(row => ({ table, kind, row })));
  }
  for (const kind of ["mcp-env", "mcp-auth"] as const) {
    const column = kind === "mcp-env" ? "sealed_ciphertext" : "oauth_sealed_ciphertext";
    const where = sql`${sql.ref(column)} IS NOT NULL`;
    coverage[kind].rows = coverage[kind].envelopes = await count({ kernel, table: "external_mcp_servers", where });
    const rows = await kernel.query<LegacyRow>(sql`SELECT * FROM external_mcp_servers WHERE ${where} ORDER BY workspace_id,server_id`);
    entries.push(...rows.map(row => ({ table: "external_mcp_servers", kind, row })));
  }
  const reserved = new Map<string, Set<string>>();
  const ids = new Map<string, Set<string>>();
  for (const entry of entries) {
    const workspaceId = text({ row: entry.row, field: "workspace_id" });
    const values = reserved.get(workspaceId) ?? new Set<string>();
    values.add(originalId(entry));
    reserved.set(workspaceId, values);
  }
  const labels = new Map<string, Set<string>>();
  const defaults = new Set<string>();
  // Vendor rows win their historical identity over publish predecessors, regardless of defaults.
  // Sorting within each source gives deterministic mapping even after dump/restore row reordering.
  entries.sort((a, b) => {
    const rank = (entry: typeof a) => entry.table === "publish_credential_sets" ? 1 : 0;
    const left = JSON.stringify([a.table, a.row.workspace_id, originalId(a)]);
    const right = JSON.stringify([b.table, b.row.workspace_id, originalId(b)]);
    return rank(a) - rank(b) || (left < right ? -1 : left > right ? 1 : 0);
  });
  for (const entry of entries) {
    const { row, kind, table } = entry;
    const workspaceId = text({ row, field: "workspace_id" });
    const preferred = originalId(entry);
    const takenIds = ids.get(workspaceId) ?? new Set<string>();
    ids.set(workspaceId, takenIds);
    const id = freeValue({ preferred, fallback: `vault:${JSON.stringify([table, preferred])}`,
      taken: takenIds, reserved: reserved.get(workspaceId)! });
    const provider = row.vendor_id ?? row.provider_id ?? row.provider ?? row.oauth_provider_id ?? null;
    const group = JSON.stringify([workspaceId, kind, table === "external_mcp_servers" ? row.server_id : "tovu", row.principal_id ?? null, provider]);
    const taken = labels.get(group) ?? new Set<string>();
    labels.set(group, taken);
    const originalLabel = nullable({ row, field: "label" }) ?? kind;
    const label = freeLabel({ preferred: originalLabel, taken });
    const wantsDefault = row.is_default === true || row.is_default === 1;
    const isDefault = wantsDefault && !defaults.has(group);
    if (isDefault) defaults.add(group);
    await insertMapped({ kernel, table, kind, row, id, label, isDefault });
    if (id !== preferred || label !== originalLabel || wantsDefault !== isDefault) context.note(`vault mapping preserved ${table} identity/default in meta.migration`);
  }
  for (const kind of KINDS) {
    const rows = await count({ kernel, table: "secrets_vault", where: sql`kind = ${kind}` });
    const envelopes = await count({ kernel, table: "secrets_vault", where: sql`kind = ${kind} AND sealed_ciphertext IS NOT NULL` });
    if (rows !== coverage[kind].rows || envelopes !== coverage[kind].envelopes) throw new Error(`secrets vault coverage mismatch: ${kind}`);
    context.note(`vault coverage ${kind}: rows=${rows}, envelopes=${envelopes}`);
  }
  await finishMcp({ kernel });
  for (const { table } of SOURCES) await kernel.execute(sql`DROP TABLE ${sql.table(table)}`);
  await kernel.execute(sql`DROP TABLE oauth_pending_authorizations`);
}

/** Activated content step; the final source checksum is pinned in checksums.ts. */
export function secretsVault(required: { checksum: string }, _options: Record<string, never> = {}): MigrationStep {
  return { id: SECRETS_VAULT_ID, checksum: required.checksum, up };
}

import { sql } from "kysely";
import type { StorageKernel } from "../kernel/port.js";
import type { MigrationStep } from "./step.js";

/** Data only: the runner owns transaction, backup and ledger. Existing coalesced provider indexes
 * already isolate custom rows' NULL-provider group. The kind CHECK retains dead value 'custom'
 * as schema debt; removing it requires a separate, justified DDL migration.
 * No crypto/envelope reads here. Boot alone opens and reseals the pinned historical custom AAD.
 */
export const UNIFY_VAULT_CREDENTIALS_ID = "0013_unify_vault_credentials";

// Frozen 2026-10-17 deploy-targets + source-control catalog. Never import a live plugin registry
// or Jini's evolving suggestion function into a checksummed migration.
const CATALOG = [
  { id: "github-pages", vendorId: "github" },
  { id: "cloudflare-pages", vendorId: "cloudflare" },
  { id: "vercel", vendorId: "vercel" },
  { id: "netlify", vendorId: "netlify" },
  { id: "s3-compatible", vendorId: "s3-compatible" },
  { id: "github", vendorId: "github" },
] as const;

type Meta = Record<string, unknown>;
type Row = { workspace_id: string; id: string; kind: "vendor" | "custom"; provider: string | null;
  label: string; revision: number; meta: string | Meta };

/** Exact spelling modulo case only; conflicting vendor identities are never guessed.
 * @complexity O(catalog size), frozen constant space.
 */
function inferredWorksFor({ label }: { label: string }, _options = {}): string[] {
  const identity = label.toLowerCase();
  const matches = CATALOG.filter(entry => entry.id === identity || entry.vendorId === identity);
  return matches.length && new Set(matches.map(entry => entry.vendorId)).size === 1 ? [identity] : [];
}

/** Convert metadata without touching timestamps, defaults, IDs, providers or opaque envelopes.
 * Preserve pre-0012 lineage when it still needs boot normalization; normalized custom vault rows
 * instead pin precisely the old custom-kind vault AAD. Re-entry skips already canonical rows.
 * @complexity O(rows × frozen catalog), O(rows + metadata) memory; one metadata scan and CAS/update.
 */
async function up(kernel: StorageKernel<unknown>): Promise<void> {
  const rows = await kernel.query<Row>(sql`SELECT workspace_id,id,kind,provider,label,revision,meta
    FROM secrets_vault WHERE kind IN ('vendor','custom') ORDER BY workspace_id,id`);
  for (const row of rows) {
    const meta: Meta = typeof row.meta === "string" ? JSON.parse(row.meta) : row.meta;
    if (row.kind === "vendor" && (meta.credentialType === "vendor" || meta.credentialType === "custom") && Array.isArray(meta.worksFor)) continue;
    const updated: Meta = { ...meta, credentialType: row.kind,
      worksFor: row.kind === "vendor" ? (row.provider === null ? [] : [row.provider]) : inferredWorksFor({ label: row.label }) };
    if (row.kind === "custom" && meta.legacyAad === undefined) {
      const legacy = { table: "secrets_vault_custom_v1", workspaceId: row.workspace_id, id: row.id,
        principalId: null, provider: null, serverId: null, aadVersion: 1 };
      updated.legacyAad = legacy;
      updated.migration = { ...legacy, mappedId: row.id, mappedLabel: row.label,
        // Retain previous provenance without letting it override the pinned historical identity.
        ...(meta.migration === undefined ? {} : { previous: meta.migration }) };
    }
    const changed = await kernel.query<{ id: string }>(sql`UPDATE secrets_vault SET kind='vendor',
      meta=${JSON.stringify(updated)},revision=revision+1
      WHERE workspace_id=${row.workspace_id} AND id=${row.id} AND revision=${row.revision} RETURNING id`);
    if (changed.length !== 1) throw new Error("credential unification revision conflict");
  }
}

/** Kept unregistered until the coordinator explicitly activates the reviewed rollout patch. */
export function unifyVaultCredentials({ checksum }: { checksum: string }, _options = {}): MigrationStep {
  return { id: UNIFY_VAULT_CREDENTIALS_ID, checksum, up };
}

import { sql } from "kysely";
import type { StorageKernel } from "../kernel/port.js";
import type { MigrationStep } from "./step.js";

/**
 * @file Admits the `api-connection` vault kind (plugin-declared OAuth API connections: sealed token
 * sets, connection records and sign-in attempts) in `secrets_vault`'s kind CHECK.
 *
 * Why a migration: Jini's platform vault gained the kind, but the CHECK written by
 * `0012_secrets_vault` rejects it, and no existing kind can be borrowed (every other kind belongs to
 * a feature whose lists, copies and reseals would then see these rows).
 *
 * PostgreSQL swaps the named constraint. SQLite cannot alter a CHECK, so the table is rebuilt inside
 * the runner's transaction: `external_mcp_servers` points at vault rows with `ON DELETE RESTRICT`,
 * which SQLite never defers, so its pointers are parked in a temp table and nulled before the drop and
 * restored after. `legacy_alter_table` is on only for the rename, because the MCP pointer triggers name
 * `secrets_vault` and the modern rename re-checks them while the table is briefly absent. Dropping the
 * table also drops its own indexes and the `secrets_vault_mcp_identity` trigger, so both are re-created
 * from their stored text. This file owns its DDL edit: a database whose vault DDL is not the 0012 shape
 * is refused, never guessed at. The fresh-database constructor shares `widenedVaultTableDdl`.
 */
export const VAULT_API_CONNECTION_KIND_ID = "0020_vault_api_connection_kind";
const OLD_KINDS = "'source-control','mcp-env','mcp-auth')";
const NEW_KINDS = "'source-control','mcp-env','mcp-auth','api-connection')";
const KIND_LIST = "'site-assistant','personal-execution','media-provider','custom','publish-peer','database-destination','vendor','source-control','mcp-env','mcp-auth','api-connection'";

/** The 0012 table DDL with the widened kind list under the temporary name `secrets_vault_0020`.
 * @example widenedVaultTableDdl({ original: tableSql }) @throws {Error} Unexpected DDL. */
export function widenedVaultTableDdl({ original }: { original: string }, _options: Record<string, never> = {}): string {
  const [before, ...rest] = original.split(OLD_KINDS);
  // @ts-ignore frozen step (ADR-066, checksum-pinned code): `split` always yields a first element; only the strict desktop config flags it.
  if (rest.length !== 1 || !before.startsWith("CREATE TABLE secrets_vault (")) {
    throw new Error("secrets_vault does not have the 0012 shape; revise this migration before applying it");
  }
  // @ts-ignore frozen step (ADR-066, checksum-pinned code): `split` always yields a first element; only the strict desktop config flags it.
  return `${before.replace("CREATE TABLE secrets_vault (", "CREATE TABLE secrets_vault_0020 (")}${NEW_KINDS}${rest[0]}`;
}

async function upSqlite(kernel: StorageKernel<unknown>): Promise<void> {
  const [table] = await kernel.query<{ sql: string }>(sql`SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'secrets_vault'`);
  if (!table) throw new Error("secrets_vault is missing; 0012_secrets_vault must run first");
  const objects = await kernel.query<{ sql: string }>(sql`SELECT sql FROM sqlite_master WHERE type IN ('index', 'trigger') AND tbl_name = 'secrets_vault' AND sql IS NOT NULL`);
  await kernel.execute(sql`PRAGMA defer_foreign_keys = ON`);
  await kernel.execute(sql`CREATE TEMP TABLE _vault_0020_pointers AS SELECT workspace_id, server_id, env_secret_id, oauth_secret_id
    FROM external_mcp_servers WHERE env_secret_id IS NOT NULL OR oauth_secret_id IS NOT NULL`);
  await kernel.execute(sql`UPDATE external_mcp_servers SET env_secret_id = NULL, oauth_secret_id = NULL
    WHERE env_secret_id IS NOT NULL OR oauth_secret_id IS NOT NULL`);
  await kernel.execute(sql.raw(widenedVaultTableDdl({ original: table.sql })));
  await kernel.execute(sql`INSERT INTO secrets_vault_0020 SELECT * FROM secrets_vault`);
  await kernel.execute(sql`DROP TABLE secrets_vault`);
  await kernel.execute(sql`PRAGMA legacy_alter_table = ON`);
  try {
    await kernel.execute(sql`ALTER TABLE secrets_vault_0020 RENAME TO secrets_vault`);
  } finally {
    await kernel.execute(sql`PRAGMA legacy_alter_table = OFF`);
  }
  for (const object of objects) await kernel.execute(sql.raw(object.sql));
  // The pointer triggers re-check kind and owner against the rebuilt vault on this restore.
  await kernel.execute(sql`UPDATE external_mcp_servers SET
    env_secret_id = (SELECT p.env_secret_id FROM _vault_0020_pointers p WHERE p.workspace_id = external_mcp_servers.workspace_id AND p.server_id = external_mcp_servers.server_id),
    oauth_secret_id = (SELECT p.oauth_secret_id FROM _vault_0020_pointers p WHERE p.workspace_id = external_mcp_servers.workspace_id AND p.server_id = external_mcp_servers.server_id)
    WHERE EXISTS (SELECT 1 FROM _vault_0020_pointers p WHERE p.workspace_id = external_mcp_servers.workspace_id AND p.server_id = external_mcp_servers.server_id)`);
  await kernel.execute(sql`DROP TABLE _vault_0020_pointers`);
}

async function up(kernel: StorageKernel<unknown>): Promise<void> {
  if (kernel.dialect === "sqlite") return upSqlite(kernel);
  await kernel.execute(sql.raw(`ALTER TABLE secrets_vault DROP CONSTRAINT secrets_vault_kind,
    ADD CONSTRAINT secrets_vault_kind CHECK(kind IN (${KIND_LIST}))`));
}

/** Widen the vault kind CHECK in both dialects. @example vaultApiConnectionKind({ checksum }) */
export function vaultApiConnectionKind(required: { checksum: string }, _options: Record<string, never> = {}): MigrationStep {
  return { id: VAULT_API_CONNECTION_KIND_ID, checksum: required.checksum, up };
}

import { sql, type Selectable } from "kysely";
import { SqlSecretsVaultRepo, type SecretsVaultDatabase, type SecretsVaultTable } from "@jini-ai/db/secrets-vault";
import { VaultError, type VaultRecord } from "@jini-ai/platform/secrets/credential-sets";
import { externalMcpVaultEnvelope, persistExternalMcpVaultEnvelope, deleteExternalMcpVaultEnvelope } from "#src/assistant/external-mcp-vault";
import type { StorageKernel } from "../kernel/port.js";

import type { UUID } from "@jini-ai/core/primitives";

import type { ExternalMcpServerRecord, ExternalMcpServerRepoPort } from "#src/assistant/index";
import type { ContentKernel } from "../content-kernel.js";
import type { ExternalMcpServersTable } from "../content-database.generated.js";
import { toBool } from "../kernel/dialect.js";

/**
 * @file THE `ExternalMcpServerRepoPort` adapter: one Kysely query body for every dialect (storage
 * plan §4, ADR-066) — the ADR-006 rule-of-two "second adapter" half;
 * `assistant/external-mcp-store.memory.ts` is the first. `sqlite/external-mcp-repo.sqlite.ts` is
 * the thin subclass the composition root builds from the content db handle.
 *
 * Secret envelopes live in Jini's vault, with two pointers on the server. Reads hydrate both
 * pointers in one query; writes join the host transaction before replacing pointers or status.
 *
 * One method here is NOT a plain translation: {@link SqlExternalMcpServerRepo.tryClaimOAuthRefreshLease}
 * is a compare-and-set, and it is the only place in this adapter where the SQL shape carries a
 * correctness guarantee rather than a storage detail. See its doc.
 */

type Row = Selectable<ExternalMcpServersTable>;
type ServerKey = { workspaceId: UUID; serverId: string };
type JoinedRow = Row & Record<string, unknown>;
type PayloadKind = "mcp-env" | "mcp-auth";
const vaultColumns = ["workspace_id", "id", "kind", "owner_key", "principal_id", "binding", "provider", "label", "is_default",
  "revision", "sealed_key_id", "sealed_ciphertext", "sealed_nonce", "sealed_alg", "last4", "token_length", "meta", "created_at", "updated_at"] as const;

function joinedEnvelope({ row, prefix, kind }: { row: JoinedRow; prefix: "env" | "oauth"; kind: PayloadKind }) {
  if (row[`${prefix}_secret_id`] === null) return null;
  const vault = Object.fromEntries(vaultColumns.map(column => [column, row[`${prefix}_${column}`]])) as unknown as SecretsVaultTable;
  assertJoinedContext({ vault, row, kind });
  return externalMcpVaultEnvelope({ record: toVaultRecord({ vault }) });
}

/** Refuses a joined payload that is not this server's own unscoped `kind` payload (or is missing). */
function assertJoinedContext({ vault, row, kind }: { vault: SecretsVaultTable; row: JoinedRow; kind: PayloadKind }): void {
  if (!vault.id || vault.workspace_id !== row.workspace_id || vault.owner_key !== row.server_id || vault.kind !== kind ||
    vault.principal_id !== null || vault.binding !== null) throw new VaultError({ code: "context" });
}

/** The vault record behind a context-checked payload; one missing any sealed part is refused. */
function toVaultRecord({ vault }: { vault: SecretsVaultTable }): VaultRecord {
  const parts = [vault.sealed_key_id, vault.sealed_ciphertext, vault.sealed_nonce, vault.sealed_alg];
  if (parts.some(value => typeof value !== "string")) throw new VaultError({ code: "invalid-record" });
  return { workspaceId: vault.workspace_id, id: vault.id, kind: vault.kind, ownerKey: vault.owner_key,
    principalId: vault.principal_id, binding: vault.binding, provider: vault.provider, label: vault.label,
    isDefault: toBool(vault.is_default) ?? false, revision: Number(vault.revision),
    sealed: { keyId: vault.sealed_key_id!, ciphertext: vault.sealed_ciphertext!, nonce: vault.sealed_nonce!, alg: vault.sealed_alg! },
    last4: vault.last4, tokenLength: vault.token_length, meta: typeof vault.meta === "string" ? JSON.parse(vault.meta) : vault.meta,
    createdAt: vault.created_at, updatedAt: vault.updated_at };
}

function toRecord(row: JoinedRow): ExternalMcpServerRecord {
  const sealedEnv = joinedEnvelope({ row, prefix: "env", kind: "mcp-env" });
  const sealedOAuth = joinedEnvelope({ row, prefix: "oauth", kind: "mcp-auth" });
  return {
    workspaceId: row.workspace_id,
    serverId: row.server_id,
    label: row.label,
    provisionedByPluginId: row.provisioned_by_plugin_id,
    transport: row.transport,
    authMode: row.auth_mode,
    enabled: toBool(row.enabled) ?? false,
    command: row.command,
    url: row.url,
    args: row.args,
    allowedToolNames: row.allowed_tool_names,
    writeAllowedToolNames: row.write_allowed_tool_names,
    writeGrantsUpdatedByPrincipalId: row.write_grants_updated_by_principal_id,
    writeGrantsUpdatedAt: row.write_grants_updated_at,
    envNames: row.env_names,
    sealedEnv,
    oauthProviderId: row.oauth_provider_id,
    oauthGrant: row.oauth_grant,
    oauthClientId: row.oauth_client_id,
    oauthEndpointsJson: row.oauth_endpoints_json,
    oauthScopesJson: row.oauth_scopes_json,
    oauthStatus: row.oauth_status,
    oauthExpiresAt: row.oauth_expires_at,
    oauthTokenEnvName: row.oauth_token_env_name,
    oauthRefreshLeaseUntil: row.oauth_refresh_lease_until,
    sealedOAuth,
    aadVersion: 1,
    oauthAadVersion: 1,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function toRow(record: ExternalMcpServerRecord, pointers: { env_secret_id: string | null; oauth_secret_id: string | null }) {
  return {
    workspace_id: record.workspaceId,
    server_id: record.serverId,
    label: record.label,
    provisioned_by_plugin_id: record.provisionedByPluginId,
    transport: record.transport,
    auth_mode: record.authMode,
    enabled: record.enabled,
    command: record.command,
    url: record.url,
    args: record.args,
    allowed_tool_names: record.allowedToolNames,
    write_allowed_tool_names: record.writeAllowedToolNames,
    write_grants_updated_by_principal_id: record.writeGrantsUpdatedByPrincipalId,
    write_grants_updated_at: record.writeGrantsUpdatedAt,
    env_names: record.envNames,
    ...pointers,
    oauth_provider_id: record.oauthProviderId,
    oauth_grant: record.oauthGrant,
    oauth_client_id: record.oauthClientId,
    oauth_endpoints_json: record.oauthEndpointsJson,
    oauth_scopes_json: record.oauthScopesJson,
    oauth_status: record.oauthStatus,
    oauth_expires_at: record.oauthExpiresAt,
    oauth_token_env_name: record.oauthTokenEnvName,
    oauth_refresh_lease_until: record.oauthRefreshLeaseUntil,
    created_at: record.createdAt,
    updated_at: record.updatedAt,
  };
}

export class SqlExternalMcpServerRepo implements ExternalMcpServerRepoPort {
  readonly vaultRepo: SqlSecretsVaultRepo;
  constructor(protected readonly kernel: ContentKernel) {
    this.vaultRepo = new SqlSecretsVaultRepo({ kernel: kernel as unknown as StorageKernel<SecretsVaultDatabase> });
  }

  /** One query hydrates both pointers for the entire roster, including empty rosters.
   * @complexity O(server count + envelope bytes); two indexed LEFT JOINs, no per-row I/O.
   */
  private async read({ workspaceId, serverId }: { workspaceId: UUID; serverId?: string }): Promise<ExternalMcpServerRecord[]> {
    const projection = (["env", "oauth"] as const).flatMap(prefix => vaultColumns.map(column =>
      sql`${sql.ref(`${prefix}.${column}`)} AS ${sql.ref(`${prefix}_${column}`)}`));
    const rows = await this.kernel.query<JoinedRow>(sql`SELECT s.*, ${sql.join(projection)} FROM external_mcp_servers s
      LEFT JOIN secrets_vault env ON env.workspace_id=s.workspace_id AND env.id=s.env_secret_id
      LEFT JOIN secrets_vault oauth ON oauth.workspace_id=s.workspace_id AND oauth.id=s.oauth_secret_id
      WHERE s.workspace_id=${workspaceId} ${serverId === undefined ? sql`` : sql`AND s.server_id=${serverId}`}`);
    return rows.map(toRecord);
  }

  async listByWorkspaceId(workspaceId: UUID): Promise<ExternalMcpServerRecord[]> {
    return this.read({ workspaceId });
  }

  async findByServerId(input: ServerKey): Promise<ExternalMcpServerRecord | null> {
    return (await this.read(input))[0] ?? null;
  }

  async upsert(record: ExternalMcpServerRecord): Promise<void> {
    await this.kernel.transaction(async () => {
      // Match Jini's writer lock before reading pointers, including callbacks and token refresh.
      await this.kernel.lockKey(`secrets_vault:${record.workspaceId}`);
      const previous = await this.kernel.run(db => db.selectFrom("external_mcp_servers")
        .select(["env_secret_id", "oauth_secret_id"]).where("workspace_id", "=", record.workspaceId)
        .where("server_id", "=", record.serverId).executeTakeFirst());
      const env_secret_id = await persistExternalMcpVaultEnvelope({ repo: this.vaultRepo, sealed: record.sealedEnv, identity: record, kind: "mcp-env" });
      const oauth_secret_id = await persistExternalMcpVaultEnvelope({ repo: this.vaultRepo, sealed: record.sealedOAuth, identity: record, kind: "mcp-auth" });
      const row = toRow(record, { env_secret_id, oauth_secret_id });
      await this.kernel.run(db => db.insertInto("external_mcp_servers").values(row)
        .onConflict(oc => oc.columns(["workspace_id", "server_id"]).doUpdateSet(row)).execute());
      // The upsert unlinks old pointers first; RESTRICT foreign keys remain satisfied throughout.
      if (previous?.env_secret_id !== env_secret_id) await deleteExternalMcpVaultEnvelope({ repo: this.vaultRepo, workspaceId: record.workspaceId, id: previous?.env_secret_id ?? null });
      if (previous?.oauth_secret_id !== oauth_secret_id) await deleteExternalMcpVaultEnvelope({ repo: this.vaultRepo, workspaceId: record.workspaceId, id: previous?.oauth_secret_id ?? null });
    });
  }

  async deleteByServerId(input: ServerKey): Promise<boolean> {
    return this.kernel.transaction(async () => {
      await this.kernel.lockKey(`secrets_vault:${input.workspaceId}`);
      const previous = await this.kernel.run(db => db.selectFrom("external_mcp_servers")
        .select(["env_secret_id", "oauth_secret_id"]).where("workspace_id", "=", input.workspaceId)
        .where("server_id", "=", input.serverId).executeTakeFirst());
      if (!previous) return false;
      await this.kernel.run(db => db.deleteFrom("external_mcp_servers").where("workspace_id", "=", input.workspaceId)
        .where("server_id", "=", input.serverId).execute());
      for (const id of [previous.env_secret_id, previous.oauth_secret_id]) await deleteExternalMcpVaultEnvelope({ repo: this.vaultRepo, workspaceId: input.workspaceId, id });
      return true;
    });
  }

  /**
   * Claims the OAuth refresh lease with a single conditional UPDATE.
   *
   * The condition is in the `WHERE`, not in a preceding `SELECT`, and that is the whole guarantee:
   * a read-then-write loses the race it exists to prevent, because between reading "no lease" and
   * writing "my lease" the other process does exactly the same and both go on to redeem the same
   * single-use rotating refresh token — which permanently kills the connection. The updated-row
   * count is therefore the answer, not a diagnostic. (One statement is atomic on every dialect: on
   * Postgres the second UPDATE waits for the first's row lock, then re-checks the `WHERE`.)
   *
   * A lease at or before `nowIso` is treated as abandoned, so a process that crashed mid-refresh
   * cannot wedge the connection until someone restarts something.
   *
   * @returns `true` when this caller now holds the lease.
   * @complexity O(1) — one indexed conditional UPDATE on the primary key.
   */
  async tryClaimOAuthRefreshLease(input: ServerKey & { nowIso: string; leaseUntil: string }): Promise<boolean> {
    const result = await this.kernel.run((db) =>
      db
        .updateTable("external_mcp_servers")
        .set({ oauth_refresh_lease_until: input.leaseUntil })
        .where("workspace_id", "=", input.workspaceId)
        .where("server_id", "=", input.serverId)
        .where((eb) => eb.or([eb("oauth_refresh_lease_until", "is", null), eb("oauth_refresh_lease_until", "<=", input.nowIso)]))
        .executeTakeFirst()
    );
    return Number(result.numUpdatedRows) > 0;
  }

  async releaseOAuthRefreshLease(input: ServerKey): Promise<void> {
    await this.kernel.run((db) =>
      db
        .updateTable("external_mcp_servers")
        .set({ oauth_refresh_lease_until: null })
        .where("workspace_id", "=", input.workspaceId)
        .where("server_id", "=", input.serverId)
        .execute()
    );
  }
}

import type { DomainEvent, OutboxRecord } from "@jini-ai/cms/core";
import {
  type FormDeliveryJob, type FormDeliveryPlan, type FormDeliveryPlanPort,
  type FormPullClaim, type FormPullLeasePort, type FormPullRefusal, formDeliveryStatusFromOutbox,
} from "@jini-ai/cms/forms";
import { DELIVERY_STATUS_MAX_LIMIT, type FormDeliveryStatusRow } from "#src/features/forms/index";

import type { Kysely } from "kysely";

import type { ContentDatabase } from "../content-database.generated.js";
import type { ContentKernel } from "../content-kernel.js";
import { outboxEventValues } from "./outbox-repo.js";

/**
 * @file SQL adapters (one Kysely body for SQLite and Postgres) for durable form delivery
 * (migration 0019): the plan-once store behind `@jini-ai/cms/forms`' `FormDeliveryPlanPort`, the
 * per-binding status reads, and the receiver pull lease behind `FormPullLeasePort`.
 *
 * Status is never stored here. It is projected from each child job's `outbox_events` row by the
 * Jini `formDeliveryStatusFromOutbox`, so the outbox worker stays the only state machine. The
 * frozen job payload (answers included) lives only in `outbox_events`; `form_delivery_jobs` holds
 * just the ids a status read prints, so status reads never load answers.
 */

export type { FormDeliveryStatusRow };

/** Outbox statuses that are not `delivered`; matches `idx_outbox_events_claim`'s leading column. */
const UNFINISHED_STATUSES = ["pending", "processing", "failed"];

/** The safe code a purged submission's unfinished jobs fail with (the contract has no closer one). */
const PURGED_JOB_ERROR = "delivery-failed";

interface StatusSqlRow {
  binding_id: string; adapter_id: string; form_id: string; submission_id: string;
  status: string; attempts: number; next_attempt_at: string; last_error: string | null;
}

/** The status columns of `workspaceId`'s jobs: the job index row, its outbox row and its plan. */
function statusQuery(db: Kysely<ContentDatabase>, workspaceId: string) {
  return db.selectFrom("form_delivery_jobs as j")
    .innerJoin("outbox_events as o", "o.id", "j.job_id")
    .innerJoin("form_delivery_plans as p", join => join.onRef("p.workspace_id", "=", "j.workspace_id").onRef("p.submission_id", "=", "j.submission_id"))
    .select(["j.binding_id", "j.adapter_id", "p.form_id", "j.submission_id", "o.status", "o.attempts", "o.next_attempt_at", "o.last_error"])
    .where("j.workspace_id", "=", workspaceId);
}

/** The job's outbox columns once its submission is purged: answers blanked, and an unfinished job
 * failed so the worker never claims it again. `failed` is terminal for the outbox worker. */
function purgedJobColumns(row: { event_json: string; status: string }) {
  const event = JSON.parse(row.event_json) as DomainEvent<FormDeliveryJob>;
  const { snapshot } = event.payload;
  const payload = { ...event.payload, snapshot: { ...snapshot, submission: { ...snapshot.submission, answers: {} } } };
  const scrubbed = { event_json: JSON.stringify({ ...event, payload }) };
  return row.status === "pending" || row.status === "processing" ? { ...scrubbed, status: "failed", last_error: PURGED_JOB_ERROR } : scrubbed;
}

function toStatusRow(row: StatusSqlRow): FormDeliveryStatusRow {
  const status = formDeliveryStatusFromOutbox({ row: {
    status: row.status as OutboxRecord["status"], attempts: row.attempts, nextAttemptAt: row.next_attempt_at, lastError: row.last_error,
  } });
  return { bindingId: row.binding_id, adapterId: row.adapter_id, formId: row.form_id, submissionId: row.submission_id, ...status };
}

/** Refuses a plan or child job built for another workspace or submission: the plan row and its
 * jobs are keyed by the REQUESTED identity, so a mismatch would file one workspace's deliveries
 * (and answers) under another. */
function assertSameIdentity(required: { requested: { workspaceId: string; submissionId: string }; what: string; workspaceId: string; submissionId: string | undefined }): void {
  const { requested } = required;
  if (required.workspaceId === requested.workspaceId && required.submissionId === requested.submissionId) return;
  throw new Error(`Form delivery plan refused: ${required.what} is for workspace ${required.workspaceId}, submission ${required.submissionId}, ` +
    `not workspace ${requested.workspaceId}, submission ${requested.submissionId}. The planner must build for the requested submission; nothing was stored.`);
}

/** Plans (plan-once with child jobs) and per-binding status reads. */
export class SqlFormDeliveryRepo implements FormDeliveryPlanPort {
  private readonly required: { kernel: ContentKernel };
  constructor(required: { kernel: ContentKernel }, _optional: Record<string, never> = {}) {
    this.required = required;
  }

  /**
   * Returns the stored plan, or runs `build` and stores the plan row, every child outbox job and
   * its index row in ONE transaction. `lockKey` serializes concurrent callers for the same
   * submission on Postgres (on SQLite the write transaction already does), so a replayed source
   * event never plans twice. A replay returns the jobs from the outbox in job-id order (each job
   * delivers independently, so order carries no meaning).
   * @throws Error when the built plan or a child job names another workspace/submission (rolled back).
   * @complexity O(jobs) inserts on first call; one indexed read on replay.
   */
  async once(
    required: { workspaceId: string; submissionId: string; build: () => Promise<FormDeliveryPlan> },
    _optional: Record<string, never> = {},
  ): Promise<FormDeliveryPlan> {
    const { kernel } = this.required;
    const { workspaceId, submissionId } = required;
    return kernel.transaction(async () => {
      await kernel.lockKey(JSON.stringify(["form-delivery-plan", workspaceId, submissionId]));
      const stored = await this.storedPlan({ workspaceId, submissionId });
      if (stored) return stored;
      const plan = await required.build();
      await this.store({ requested: { workspaceId, submissionId }, plan });
      return plan;
    });
  }

  private async storedPlan(required: { workspaceId: string; submissionId: string }): Promise<FormDeliveryPlan | null> {
    const { workspaceId, submissionId } = required;
    const row = await this.required.kernel.run(db => db.selectFrom("form_delivery_plans").select("form_id")
      .where("workspace_id", "=", workspaceId).where("submission_id", "=", submissionId).executeTakeFirst());
    if (!row) return null;
    const jobs = await this.required.kernel.run(db => db.selectFrom("form_delivery_jobs as j")
      .innerJoin("outbox_events as o", "o.id", "j.job_id").select("o.event_json")
      .where("j.workspace_id", "=", workspaceId).where("j.submission_id", "=", submissionId).orderBy("j.job_id").execute());
    return { workspaceId, submissionId, formId: row.form_id, jobs: jobs.map(job => JSON.parse(job.event_json) as DomainEvent<FormDeliveryJob>) };
  }

  private async store(required: { requested: { workspaceId: string; submissionId: string }; plan: FormDeliveryPlan }): Promise<void> {
    const { requested, plan } = required;
    assertSameIdentity({ requested, what: "the built plan", workspaceId: plan.workspaceId, submissionId: plan.submissionId });
    for (const job of plan.jobs) assertSameIdentity({ requested, what: `child job ${job.id}`, workspaceId: job.workspaceId, submissionId: job.aggregateId });
    const { kernel } = this.required;
    await kernel.run(db => db.insertInto("form_delivery_plans")
      .values({ workspace_id: plan.workspaceId, submission_id: plan.submissionId, form_id: plan.formId }).execute());
    for (const job of plan.jobs) {
      await kernel.run(db => db.insertInto("outbox_events").values(outboxEventValues(job)).execute());
      await kernel.run(db => db.insertInto("form_delivery_jobs").values({ job_id: job.id, workspace_id: plan.workspaceId,
        submission_id: plan.submissionId, binding_id: job.payload.binding.bindingId, adapter_id: job.payload.binding.adapterId }).execute());
    }
  }

  /**
   * After a permanent delete (a Trash purge of the submission, or of its form with every submission
   * it had): blanks the answers frozen into those submissions' delivery jobs and fails the jobs not
   * yet finished, so the deleted answers neither stay in Tovu nor reach a destination later.
   * Copies a destination already received are outside Tovu and stay. Runs inside the purge's own
   * transaction (the kernel joins it), so the purge and the scrub commit or roll back together.
   * @complexity O(jobs of the purged submissions): one indexed read, one update per job.
   */
  async scrubPurged(
    required: { workspaceId: string; purged: { submissionId: string } | { formId: string } },
    _optional: Record<string, never> = {},
  ): Promise<void> {
    const { kernel } = this.required;
    const { workspaceId, purged } = required;
    const [column, id] = "submissionId" in purged ? ["p.submission_id", purged.submissionId] as const : ["p.form_id", purged.formId] as const;
    const jobs = await kernel.run(db => db.selectFrom("form_delivery_jobs as j")
      .innerJoin("form_delivery_plans as p", join => join.onRef("p.workspace_id", "=", "j.workspace_id").onRef("p.submission_id", "=", "j.submission_id"))
      .innerJoin("outbox_events as o", "o.id", "j.job_id")
      .select(["o.id", "o.event_json", "o.status"])
      .where("j.workspace_id", "=", workspaceId).where(column, "=", id).execute());
    for (const job of jobs) {
      await kernel.run(db => db.updateTable("outbox_events").set(purgedJobColumns(job)).where("id", "=", job.id).execute());
    }
  }

  /**
   * Every binding's status for one submission of `workspaceId`, ordered by binding id.
   * @complexity O(bindings of the submission), via `ux_form_delivery_jobs_binding` and primary keys.
   */
  async forSubmission(required: { workspaceId: string; submissionId: string }, _optional: Record<string, never> = {}): Promise<FormDeliveryStatusRow[]> {
    const { kernel } = this.required;
    const rows = await kernel.run(db => statusQuery(db, required.workspaceId).where("j.submission_id", "=", required.submissionId)
      .orderBy("j.binding_id").execute());
    return rows.map(toStatusRow);
  }

  /**
   * The most recent jobs of `workspaceId` that are not completed (pending, retrying or failed),
   * newest first, `limit` of them (default {@link DELIVERY_STATUS_MAX_LIMIT}).
   * @param optional.limit not validated here: the only caller, `forms_delivery_status`, already
   *   refuses anything but an integer from 1 to {@link DELIVERY_STATUS_MAX_LIMIT}.
   * @complexity Driven from `idx_outbox_events_claim` (undelivered rows only), joined by primary key.
   */
  async recentUnfinished(required: { workspaceId: string }, optional: { limit?: number } = {}): Promise<FormDeliveryStatusRow[]> {
    const { kernel } = this.required;
    const rows = await kernel.run(db => statusQuery(db, required.workspaceId).where("o.status", "in", UNFINISHED_STATUSES)
      .orderBy("o.created_at", "desc").orderBy("o.id", "desc").limit(optional.limit ?? DELIVERY_STATUS_MAX_LIMIT).execute());
    return rows.map(toStatusRow);
  }
}

interface PullRow { lease_token: string | null; lease_expires_at: string | null; last_started_at: string }

/** Why a claim at `nowMs` must wait, or null when it may start. An expired lease is free again,
 * which is how a pull that crashed mid-way recovers. `recentMs` 0 (manual) never refuses `recent`,
 * even when the clock moved back past the last start. */
function refusalOf(row: PullRow | undefined, nowMs: number, recentMs: number): FormPullRefusal | null {
  if (!row) return null;
  // Claim and release always set or clear token and expiry together, so the expiry alone says "held".
  if (row.lease_expires_at !== null && Date.parse(row.lease_expires_at) > nowMs) return "already-running";
  if (recentMs > 0 && nowMs - Date.parse(row.last_started_at) < recentMs) return "recent";
  return null;
}

/** The lease end. A non-positive or non-finite `leaseMs` would grant a lease that is already
 * over, letting two pulls overlap, so it is refused instead of stored. */
function leaseExpiresAt(nowIso: string, leaseMs: number): string {
  const nowMs = Date.parse(nowIso);
  if (!Number.isFinite(nowMs) || !Number.isFinite(leaseMs) || leaseMs <= 0) {
    throw new RangeError(`Form pull lease refused: nowIso must be an ISO time and leaseMs a positive finite number (got ${leaseMs}); pass the pull's bounded duration.`);
  }
  return new Date(nowMs + leaseMs).toISOString();
}

/**
 * The per-receiver pull lease. `leaseMs` comes from the caller, which owns the pull's page and time
 * bounds and must prove the lease outlasts the bounded pull (see `withFormPullLease`).
 */
export class SqlFormPullLeaseRepo implements FormPullLeasePort {
  private readonly required: { kernel: ContentKernel };
  constructor(required: { kernel: ContentKernel }, _optional: Record<string, never> = {}) {
    this.required = required;
  }

  /**
   * Atomic admission: under `lockKey` (Postgres advisory lock; SQLite's write transaction), reads
   * the receiver row, refuses with the reason, or records this start and lease in one upsert.
   * @throws RangeError when `nowIso` or `leaseMs` is unusable (before touching the database).
   * @complexity O(1): one primary-key read and one upsert.
   */
  async claim(
    required: { workspaceId: string; receiverKey: string; token: string; nowIso: string; recentMs: number; leaseMs: number },
    _optional: Record<string, never> = {},
  ): Promise<FormPullClaim> {
    const { kernel } = this.required;
    const { workspaceId, receiverKey, token, nowIso } = required;
    const expiresAt = leaseExpiresAt(nowIso, required.leaseMs);
    return kernel.transaction(async () => {
      await kernel.lockKey(JSON.stringify(["form-receiver-pull", workspaceId, receiverKey]));
      const row = await kernel.run(db => db.selectFrom("form_receiver_pulls").select(["lease_token", "lease_expires_at", "last_started_at"])
        .where("workspace_id", "=", workspaceId).where("receiver_key", "=", receiverKey).executeTakeFirst());
      const reason = refusalOf(row, Date.parse(nowIso), required.recentMs);
      if (reason) return { claimed: false, reason };
      const lease = { lease_token: token, lease_expires_at: expiresAt, last_started_at: nowIso };
      await kernel.run(db => db.insertInto("form_receiver_pulls").values({ workspace_id: workspaceId, receiver_key: receiverKey, ...lease })
        .onConflict(conflict => conflict.columns(["workspace_id", "receiver_key"]).doUpdateSet(lease)).execute());
      return { claimed: true };
    });
  }

  /** Clears the lease only while `token` still holds it, so a pull that outlived its lease cannot
   * free a newer holder; the last start stays for the `recent` check. @complexity O(1). */
  async release(required: { workspaceId: string; receiverKey: string; token: string }, _optional: Record<string, never> = {}): Promise<void> {
    await this.required.kernel.run(db => db.updateTable("form_receiver_pulls").set({ lease_token: null, lease_expires_at: null })
      .where("workspace_id", "=", required.workspaceId).where("receiver_key", "=", required.receiverKey)
      .where("lease_token", "=", required.token).execute());
  }
}

import type { Kysely, Selectable } from "kysely";

import type { ContentDatabase, AssetBlobsTable, AssetRenditionsTable, MediaSlugHistoryTable, MediaTable, TransformRegistryTable } from "../content-database.generated.js";
import type { ContentKernel } from "../content-kernel.js";
import { isUniqueViolation, listColumns } from "../kernel/dialect.js";
import type { MediaRecord } from "@jini-ai/cms/media";
import type { MediaContentTypeStorePort } from "#src/features/media/content-type-store";
import type { VersionedMediaRepoPort } from "#src/features/media/versioned-media-repo";
import type { UUID } from "@jini-ai/core/primitives";
import { MediaConflictError } from "@jini-ai/cms/media";
import type {
  AssetBlobRepoPort,
  AssetRenditionRepoPort,
  TransformDefinitionRepoPort,
  AssetBlobRecord,
  AssetBlobStatus,
  AssetRenditionRecord,
  MediaStatus,
  TransformDefinitionRecord,
  TransformParams,
} from "@jini-ai/cms/media";

/**
 * @file ADR-046 Phase 1 — THE durable adapters for the `media` library's four route-consumed repo
 * ports (ADR-006 rule-of-two "second adapter" half; `media/repo.memory.ts`'s in-memory doubles are
 * the first) plus `MediaContentTypeStorePort`: one Kysely query body each for every dialect the
 * storage kernel drives (storage plan §4, ADR-066). `sqlite/media-repo.sqlite.ts` keeps the
 * `Sqlite*` names as thin subclasses the composition root builds from the content db handle.
 *
 * `BlobGcJournalRepoPort` (the fifth media port) is deliberately NOT given an adapter here —
 * `RouteDeps` has no `blobGcJournalRepo` field and no composition root wires one; the real
 * journaled-GC protocol (ADR-027 §5) itself is still a disclosed, deferred build, not just its
 * persistence. Wiring an adapter nothing calls is out of scope (mirrors SPEC-025's identical
 * `SqliteMemberConsentRepo` scope decision).
 *
 * JSON: `transform_registry.params_json` is compact JSON text (a Postgres `jsonb`), always parsed
 * on read, so jsonb's key order changes nothing a caller sees.
 *
 * Architectural role:
 * Infrastructure adapters. `media` never imports this file — it depends only on the ports;
 * composition roots (`server/deps.ts`) bind the concrete classes.
 */

type ContentQueries = Kysely<ContentDatabase>;

function toMediaRecord(row: Selectable<MediaTable> & { created_by?: string | null }): MediaRecord {
  return {
    id: row.id,
    // selectAll works on both schemas; absence/NULL is honest legacy unknown attribution.
    ...(row.created_by != null ? { createdBy: row.created_by } : {}),
    workspaceId: row.workspace_id,
    kind: row.kind === "document" ? "document" : "media",
    originalFilename: row.original_filename ?? null,
    title: row.title,
    // `row.slug` is nullable in the DB (see `schema.sqlite.ts`'s doc: backfilled out of band, not on
    // write) but `MediaRecord.slug` is non-nullable in the domain model — every row this repo
    // itself ever writes always has a real slug (`save()`'s values below never omit it), so a `null`
    // here can only mean a genuinely pre-backfill row. Falling back to the row's own `id` rather
    // than `""`/`"untitled"` keeps the fallback ALREADY unique (ids are primary keys) without a
    // repo-layer uniqueness check of its own.
    slug: row.slug ?? row.id,
    alt: row.alt,
    caption: row.caption,
    credit: row.credit,
    source: { sha256: row.source_sha256 },
    status: row.status as MediaStatus,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    version: row.version,
    width: row.width,
    height: row.height,
    cssClass: row.css_class,
    htmlAttributes: row.html_attributes,
  };
}

/**
 * Extracted so `save`, `saveIfVersion`, and `insertIfAbsent` persist the IDENTICAL columns from the
 * identical record — a second hand-maintained copy of this mapping is how one write path silently
 * stops honouring a column the others still write. Mirrors the post repo's identical `toRow`.
 *
 * @complexity O(1) — a fixed field-by-field copy, no iteration.
 */
function toMediaRow(record: MediaRecord): Omit<MediaTable, "created_by" | "kind" | "original_filename"> {
  return {
    id: record.id,
    workspace_id: record.workspaceId,
    title: record.title,
    slug: record.slug,
    alt: record.alt,
    caption: record.caption,
    credit: record.credit,
    source_sha256: record.source.sha256,
    status: record.status,
    created_at: record.createdAt,
    updated_at: record.updatedAt,
    version: record.version,
    width: record.width,
    height: record.height,
    css_class: record.cssClass,
    html_attributes: record.htmlAttributes,
  };
}

/**
 * Translates a unique-constraint violation on `idx_media_workspace_slug` (any dialect) into the same
 * `MediaConflictError` the app-level `findBySlug` courtesy check throws, so every caller of every
 * write method on this repo (`save`, `saveIfVersion`, `insertIfAbsent`) handles one error shape
 * regardless of which layer actually caught the collision. Re-throws anything that is not a unique-
 * constraint violation unchanged.
 *
 * @complexity O(1).
 */
function translateSlugConflict(err: unknown, slug: string): never {
  if (isUniqueViolation(err)) {
    throw new MediaConflictError({ message: `slug '${slug}' is already used by another media asset in this workspace` });
  }
  throw err;
}

/** The `media_slug_history` row currently claiming `slug` in this workspace, or `null` if none
 *  (readable-slugs plan, S2a — see `VersionedMediaRepoPort.listRetiredSlugs`'s doc for the full
 *  rename-safety contract this and its sibling helpers below implement). */
async function findSlugClaimant(db: ContentQueries, workspaceId: UUID, slug: string): Promise<Selectable<MediaSlugHistoryTable> | null> {
  const row = await db
    .selectFrom("media_slug_history")
    .selectAll()
    .where("workspace_id", "=", workspaceId)
    .where("slug", "=", slug)
    .limit(1)
    .executeTakeFirst();
  return row ?? null;
}

/** Throws `MediaConflictError` — the same shape a live-row `idx_media_workspace_slug` violation
 *  throws — when `claimant` belongs to a DIFFERENT asset. A `null` claimant, or one that already
 *  belongs to `mediaId` (reclaiming its own old slug), is fine. */
function assertSlugReclaimable(claimant: Selectable<MediaSlugHistoryTable> | null, mediaId: UUID, slug: string): void {
  if (claimant && claimant.media_id !== mediaId) {
    throw new MediaConflictError({ message: `slug '${slug}' is already used by another media asset in this workspace` });
  }
}

/** Removes a slug from `media_slug_history` — called once its claimant has actually reclaimed it
 *  (the row write that reclaims it has already landed in the same transaction). */
async function deleteHistoryRow(db: ContentQueries, workspaceId: UUID, slug: string): Promise<void> {
  await db.deleteFrom("media_slug_history").where("workspace_id", "=", workspaceId).where("slug", "=", slug).execute();
}

/** Moves `oldSlug` into `media_slug_history` for `mediaId`, unless the write left the slug
 *  unchanged or there was no prior slug (a brand-new row) — mirrors
 *  `InMemoryVersionedMediaRepo`'s identical `retireSlug` private method. */
async function retireSlug(db: ContentQueries, workspaceId: UUID, mediaId: UUID, oldSlug: string | null, newSlug: string, retiredAt: string): Promise<void> {
  if (!oldSlug || oldSlug === newSlug) return;
  await db.insertInto("media_slug_history").values({ workspace_id: workspaceId, slug: oldSlug, media_id: mediaId, retired_at: retiredAt }).execute();
}

/** The `lockKey` every slug-claiming write in one workspace takes: the history read, the conflict
 *  check and the write must not interleave with another claimant's (Postgres; SQLite's write lock
 *  already serializes them). */
function slugLockKey(workspaceId: UUID): string {
  return `media_slugs:${workspaceId}`;
}

export class SqlMediaRepo implements VersionedMediaRepoPort {
  protected readonly kernel: ContentKernel;
  constructor(kernel: ContentKernel) {
    this.kernel = kernel;
  }

  /** Only creation writes stamp provenance, privacy kind and original filename. Metadata/Trash
   * updates omit those columns so stale drafts cannot publicize a document or rename its source.
   * Use the existing dialect port to inspect the
   * optional column before INSERT, avoiding a failed statement that would abort a PG transaction.
   * Do not cache absence: the owner can install the staged migration while this repo is alive. */
  private async creationValues(required: { record: MediaRecord }, _optional: Record<string, never> = {}):
    Promise<Omit<MediaTable, "created_by" | "kind" | "original_filename"> & { created_by?: string | null; kind: string; original_filename: string | null }> {
    const { record } = required;
    const columns = await listColumns(this.kernel, "media");
    return { ...toMediaRow(record), kind: record.kind ?? "media", original_filename: record.originalFilename ?? null, ...(columns.some(column => column.name === "created_by")
      ? { created_by: record.createdBy ?? null } : {}) };
  }

  async findById(required: { workspaceId: UUID; id: UUID }): Promise<MediaRecord | null> {
    const row = await this.kernel.run((db) =>
      db.selectFrom("media").selectAll().where("workspace_id", "=", required.workspaceId).where("id", "=", required.id).limit(1).executeTakeFirst()
    );
    return row ? toMediaRecord(row) : null;
  }

  /**
   * Second lookup key (`MediaRepoPort.findBySlug`, 2026-09-07) — same shape as `findById`, just
   * against `idx_media_workspace_slug` instead of the primary key. Falls back to
   * `media_slug_history` (S2a, 2026-09-23) when no LIVE row currently holds `slug`, so a retired
   * slug keeps resolving to the asset that retired it — see
   * `VersionedMediaRepoPort.listRetiredSlugs`'s doc for the full rename-safety contract.
   */
  async findBySlug(required: { workspaceId: UUID; slug: string }): Promise<MediaRecord | null> {
    const live = await this.kernel.run((db) =>
      db.selectFrom("media").selectAll().where("workspace_id", "=", required.workspaceId).where("slug", "=", required.slug).limit(1).executeTakeFirst()
    );
    if (live) return toMediaRecord(live);
    const retired = await this.kernel.run((db) => findSlugClaimant(db, required.workspaceId, required.slug));
    if (!retired) return null;
    return this.findById({ workspaceId: required.workspaceId, id: retired.media_id });
  }

  /**
   * Newest-first (owner-directed, 2026-09-11: "have a sort by to see our most recent images" —
   * she checks this list right after an agent plugin generates one, e.g. Higgsfield's
   * `media_import_from_url`, so "what did I just make" has to land at the top with no extra
   * step). `MediaRepoPort.list()`'s own doc (`@jini-ai/cms/media/ports.ts`) never promised any
   * particular order, and no caller in this codebase sorted the result itself (confirmed: neither
   * `listMedia()` in `@jini-ai/cms/media/media-service.ts`, nor `media_list_assets`'s handler in
   * that same package's `tool-registrations.ts`, nor the admin route below, nor
   * `apps/admin/src/features/media/hooks/use-media.hooks.ts` on the client) — so choosing newest-
   * first here is additive, not a documented-contract break, and it is the ONE choke point both
   * consumers share: `media_list_assets` and the admin `GET .../media` route both resolve to
   * `listMedia()` -> `deps.mediaRepo.list()`, and production wires exactly one `MediaRepoPort`
   * implementation (`composition/deps.ts`'s `mediaRepo: new SqliteMediaRepo(db)`) — fixing it here
   * reaches both surfaces without a second change.
   *
   * `id desc` is a tiebreaker only, mirroring `database-journal-repo.ts`'s identical
   * `createdAt` + `id` compound `orderBy` — `id` is a random UUID (`idGen.newId()`), not
   * chronological, so it cannot repair a same-instant tie into true creation order; it only makes
   * repeated queries against an unchanged table return rows in the same order (no database gives
   * such a guarantee on its own once two rows share a sort key). `createdAt` itself is
   * `clock.nowIso()` = `Date.prototype.toISOString()`, millisecond-precision and never rewritten
   * after a row's first `save()` (`save()` above always persists the caller's `record.createdAt`
   * verbatim, update or insert alike), so a same-millisecond collision is possible only for two
   * rows created by the same batch call in the same tick — rare enough that the tiebreaker's job
   * is determinism, not correctness of "which is newer."
   *
   * Deliberately NOT added to `InMemoryMediaRepo.list()` (`@jini-ai/cms/media/repo.memory.ts`):
   * that adapter lives in the separate Jini package/repo this file's own header says composition
   * roots bind against, not maintain, and production never constructs it (see this comment's own
   * "one choke point" note above) — a disclosed, Tovu-scoped fix, not a silent rule-of-two parity
   * gap. `features/media/__tests__/repo.contract.test.ts`'s shared `runMediaSuite` still runs both
   * adapters through the SAME order-agnostic assertions it always has; the ordering assertion is a
   * durable-adapter-only test there, following that file's own established pattern for
   * adapter-specific behavior (see its slug-conflict tests).
   */
  async list(required: { workspaceId: UUID }): Promise<MediaRecord[]> {
    const rows = await this.kernel.run((db) =>
      db.selectFrom("media").selectAll().where("workspace_id", "=", required.workspaceId).orderBy("created_at", "desc").orderBy("id", "desc").execute()
    );
    return rows.map(toMediaRecord);
  }

  /**
   * S2a (readable slugs, 2026-09-23): the read, the retired-slug conflict check, the write, and the
   * slug-history move (reclaim the new slug out of history if it was retired; retire the row's PRIOR
   * slug if this write actually changes it) all run inside ONE kernel transaction under the
   * workspace's slug lock — never a separate `findById()`/history-read followed by a separate write,
   * the same "one atomic step, not a check-then-write pair" reasoning `saveIfVersion`'s own doc gives.
   */
  async save(record: MediaRecord): Promise<void> {
    const values = toMediaRow(record);
    // `updateMediaMetadata`'s own `findBySlug` check (see `@jini-ai/cms/media`'s `media-service.ts`)
    // is a friendly-error courtesy, not the enforcement — `idx_media_workspace_slug` (a LIVE
    // collision) and `assertSlugReclaimable` (a RETIRED-slug collision) are. A caller that races
    // past those checks (or bypasses the service entirely) hits the real DB constraint here;
    // translated to the SAME `MediaConflictError` type the app-level check throws, so every caller
    // handles one error shape regardless of which layer actually caught the collision.
    try {
      await this.kernel.transaction(async () => {
        await this.kernel.lockKey(slugLockKey(record.workspaceId));
        await this.kernel.run(async (db) => {
          const existingRow = await db
            .selectFrom("media")
            .select(["slug", "source_sha256"])
            .where("workspace_id", "=", record.workspaceId)
            .where("id", "=", record.id)
            .executeTakeFirst();
          // A metadata draft captured before replacement may arrive afterwards. Never let
          // that ordinary save silently restore the old source or discard the replacement.
          if (existingRow && existingRow.source_sha256 !== record.source.sha256) {
            throw new MediaConflictError({ message: 'media file changed before metadata could be saved' });
          }
          const claimant = await findSlugClaimant(db, record.workspaceId, record.slug);
          assertSlugReclaimable(claimant, record.id, record.slug);
          if (existingRow) {
            await db.updateTable("media").set(values).where("workspace_id", "=", record.workspaceId).where("id", "=", record.id).execute();
          } else {
            await db.insertInto("media").values(await this.creationValues({ record })).execute();
          }
          if (claimant) await deleteHistoryRow(db, record.workspaceId, record.slug);
          await retireSlug(db, record.workspaceId, record.id, existingRow?.slug ?? null, record.slug, record.updatedAt);
        });
      });
    } catch (err) {
      translateSlugConflict(err, record.slug);
    }
  }

  /**
   * See `VersionedMediaRepoPort.saveIfVersion`'s own doc for the contract. An
   * `UPDATE … WHERE workspace_id = ? AND id = ? AND version = ?` — never the upsert `save()` above
   * uses, because an absent or already-superseded row must report `applied: false` rather than be
   * inserted or silently overwritten. The predicate and the write are ONE statement, which is the
   * whole point: a compare done in JavaScript with a write issued afterwards (this repo's `save()`,
   * called from a caller that read a stale version first) is exactly the race this method closes —
   * mirrors the post repo's identical `saveIfVersion`.
   *
   * @complexity O(1) — one statement against the `media` primary key.
   */
  async saveIfVersion(required: { record: MediaRecord; ifVersion: number }): Promise<{ applied: boolean }> {
    const { record, ifVersion } = required;
    try {
      return await this.kernel.transaction(async () => {
        await this.kernel.lockKey(slugLockKey(record.workspaceId));
        return this.kernel.run(async (db) => {
          const existingRow = await db
            .selectFrom("media")
            .select("slug")
            .where("workspace_id", "=", record.workspaceId)
            .where("id", "=", record.id)
            .where("version", "=", ifVersion)
            .executeTakeFirst();
          if (!existingRow) return { applied: false };
          const claimant = await findSlugClaimant(db, record.workspaceId, record.slug);
          assertSlugReclaimable(claimant, record.id, record.slug);
          const updated = await db
            .updateTable("media")
            .set(toMediaRow(record))
            .where("workspace_id", "=", record.workspaceId)
            .where("id", "=", record.id)
            .where("version", "=", ifVersion)
            .returning("id")
            .execute();
          if (updated.length === 0) return { applied: false };
          if (claimant) await deleteHistoryRow(db, record.workspaceId, record.slug);
          await retireSlug(db, record.workspaceId, record.id, existingRow.slug, record.slug, record.updatedAt);
          return { applied: true };
        });
      });
    } catch (err) {
      translateSlugConflict(err, record.slug);
    }
  }

  /** An authorized replace command is the sole mutable-source operation. Invalidate derived
   * previews in the SAME transaction: a failed insert must leave the old source and previews
   * intact. Ordinary metadata/import writes retain their existing source policy. */
  async replaceFileIfVersion(required: {
    workspaceId: UUID; id: UUID; ifVersion: number; sha256: string; storageKey: string;
    originalRenditionId: UUID; updatedAt: string;
  }, _optional: Record<string, never> = {}): Promise<{ applied: boolean }> {
    return this.kernel.transaction(async () => {
      await this.kernel.lockKey(slugLockKey(required.workspaceId));
      return this.kernel.run(async db => {
        const blob = await db.selectFrom('asset_blobs').select('id')
          .where('workspace_id', '=', required.workspaceId).where('sha256', '=', required.sha256)
          .where('storage_key', '=', required.storageKey).where('status', '=', 'active').executeTakeFirst();
        if (!blob) return { applied: false };
        const rows = await db.updateTable('media').set({ source_sha256: required.sha256,
          version: required.ifVersion + 1, updated_at: required.updatedAt })
          .where('workspace_id', '=', required.workspaceId).where('id', '=', required.id)
          .where('version', '=', required.ifVersion).where('status', '=', 'active')
          .returning('id').execute();
        if (!rows.length) return { applied: false };
        await db.deleteFrom('asset_renditions').where('workspace_id', '=', required.workspaceId)
          .where('asset_id', '=', required.id).execute();
        await db.insertInto('asset_renditions').values({ id: required.originalRenditionId,
          workspace_id: required.workspaceId, asset_id: required.id, transform_name: 'original',
          version: 1, storage_key: required.storageKey, created_at: required.updatedAt }).execute();
        return { applied: true };
      });
    });
  }

  async saveRenditionIfSource({ record, sourceSha256 }: { record: AssetRenditionRecord; sourceSha256: string },
    _optional: Record<string, never> = {}): Promise<{ applied: boolean }> {
    return this.kernel.transaction(async () => {
      await this.kernel.lockKey(slugLockKey(record.workspaceId));
      const current = await this.kernel.run(db => db.selectFrom('media').select('id')
        .where('workspace_id', '=', record.workspaceId).where('id', '=', record.assetId)
        .where('source_sha256', '=', sourceSha256).where('status', '=', 'active').executeTakeFirst());
      if (!current) return { applied: false };
      // run() joins this transaction; replacement cannot interleave between compare and insert.
      await new SqlAssetRenditionRepo(this.kernel).save(record);
      return { applied: true };
    });
  }

  /**
   * See `VersionedMediaRepoPort.insertIfAbsent`'s own doc for the contract. The conflict target is
   * deliberately `id` (the primary key) and NOT an untargeted `ON CONFLICT DO NOTHING` — an
   * untargeted one would also swallow `idx_media_workspace_slug`'s unique-constraint violation,
   * silently reporting `applied: false` for a slug collision instead of throwing
   * `MediaConflictError` the way every other write on this repo does.
   *
   * @complexity O(1) — one statement against the `media` primary key.
   */
  async insertIfAbsent(record: MediaRecord): Promise<{ applied: boolean }> {
    try {
      return await this.kernel.transaction(async () => {
        await this.kernel.lockKey(slugLockKey(record.workspaceId));
        return this.kernel.run(async (db) => {
          const claimant = await findSlugClaimant(db, record.workspaceId, record.slug);
          assertSlugReclaimable(claimant, record.id, record.slug);
          const inserted = await db
            .insertInto("media")
            .values(await this.creationValues({ record }))
            .onConflict((oc) => oc.column("id").doNothing())
            .returning("id")
            .execute();
          // Only drop the history row once the insert actually landed — an `applied: false` (id
          // already taken) must leave `media_slug_history` exactly as it was, same "no partial
          // effect on a refused write" rule every other branch here follows.
          if (inserted.length > 0 && claimant) await deleteHistoryRow(db, record.workspaceId, record.slug);
          return { applied: inserted.length > 0 };
        });
      });
    } catch (err) {
      translateSlugConflict(err, record.slug);
    }
  }

  /** Drops the row's `media_slug_history` entries in the SAME transaction as the delete itself —
   *  S2a: "permanent delete drops that asset's history rows, which frees the name." */
  async remove(required: { workspaceId: UUID; id: UUID }): Promise<void> {
    await this.kernel.transaction(async () => {
      await this.kernel.run(async (db) => {
        await db.deleteFrom("media").where("workspace_id", "=", required.workspaceId).where("id", "=", required.id).execute();
        await db.deleteFrom("media_slug_history").where("workspace_id", "=", required.workspaceId).where("media_id", "=", required.id).execute();
      });
    });
  }

  async listRetiredSlugs(required: { workspaceId: UUID; mediaId: UUID }): Promise<string[]> {
    const rows = await this.kernel.run((db) =>
      db.selectFrom("media_slug_history").select("slug").where("workspace_id", "=", required.workspaceId).where("media_id", "=", required.mediaId).execute()
    );
    return rows.map((row) => row.slug);
  }
}

function toAssetBlobRecord(row: Selectable<AssetBlobsTable>): AssetBlobRecord {
  const record: AssetBlobRecord = {
    id: row.id,
    workspaceId: row.workspace_id,
    sha256: row.sha256,
    storageKey: row.storage_key,
    createdByPrincipal: row.created_by_principal,
    createdAt: row.created_at,
    status: row.status as AssetBlobStatus,
  };
  // Omitted entirely when unset, not set to explicit `undefined` — a key present-but-`undefined`
  // is NOT deep-equal to an absent key under `assert.deepStrictEqual` (see origin-repo.ts's
  // identical fix for the same class of bug).
  if (row.tombstoned_at != null) record.tombstonedAt = row.tombstoned_at;
  if (row.document_owned === true || row.document_owned === 1) record.documentOwned = true;
  return record;
}

export class SqlAssetBlobRepo implements AssetBlobRepoPort {
  protected readonly kernel: ContentKernel;
  constructor(kernel: ContentKernel) {
    this.kernel = kernel;
  }

  async findByHash(required: { workspaceId: UUID; sha256: string }): Promise<AssetBlobRecord | null> {
    const row = await this.kernel.run((db) =>
      db.selectFrom("asset_blobs").selectAll().where("workspace_id", "=", required.workspaceId).where("sha256", "=", required.sha256).limit(1).executeTakeFirst()
    );
    return row ? toAssetBlobRecord(row) : null;
  }

  async list(required: { workspaceId: UUID }): Promise<AssetBlobRecord[]> {
    const rows = await this.kernel.run((db) => db.selectFrom("asset_blobs").selectAll().where("workspace_id", "=", required.workspaceId).execute());
    return rows.map(toAssetBlobRecord);
  }

  /** Update-or-insert by `(workspace_id, sha256)`: the read and the write run in one kernel
   *  transaction under a lock on that hash, so two saves of the same blob cannot both insert. */
  async save(record: AssetBlobRecord): Promise<void> {
    const values = {
      id: record.id,
      workspace_id: record.workspaceId,
      sha256: record.sha256,
      storage_key: record.storageKey,
      created_by_principal: record.createdByPrincipal,
      created_at: record.createdAt,
      status: record.status,
      tombstoned_at: record.tombstonedAt ?? null,
      document_owned: record.documentOwned === true,
    };
    await this.kernel.transaction(async () => {
      await this.kernel.lockKey(`asset_blobs:${record.workspaceId}:${record.sha256}`);
      const existing = await this.findByHash({ workspaceId: record.workspaceId, sha256: record.sha256 });
      await this.kernel.run(async (db) => {
        if (existing) {
          // `content_type` is deliberately absent from `values` above, so this `.set()` leaves the
          // existing value alone. `AssetBlobRecord` is `@jini-ai/cms`'s frozen port type and has no
          // content-type field, so anything this method could put there would be `null` — and this
          // branch runs on `uploadMedia`'s dedup RESURRECT path (tombstoned -> active), which would
          // then silently erase the recorded type of a blob that is being re-referenced, not deleted.
          // The type is owned by `SqlMediaContentTypeStore` below; this repo never writes it.
          // Ownership is monotonic until GC removes the blob; stale saves cannot clear it.
          await db.updateTable("asset_blobs").set({ ...values, document_owned: existing.documentOwned === true || record.documentOwned === true }).where("workspace_id", "=", record.workspaceId).where("sha256", "=", record.sha256).execute();
        } else {
          await db.insertInto("asset_blobs").values(values).execute();
        }
      });
    });
  }

  async remove(required: { workspaceId: UUID; sha256: string }): Promise<void> {
    await this.kernel.run((db) =>
      db.deleteFrom("asset_blobs").where("workspace_id", "=", required.workspaceId).where("sha256", "=", required.sha256).execute()
    );
  }
}

/**
 * `MediaContentTypeStorePort`'s durable adapter — reads and writes `asset_blobs.content_type`, the
 * one column on that table `SqlAssetBlobRepo` above deliberately never touches (see its `save()`
 * comment for why the two are split rather than merged).
 *
 * No row is ever INSERTED here: the blob row is always created first by `uploadMedia`'s own
 * `blobRepo.save()` (its INV-1a "bytes before the media row" ordering guarantees it exists), so
 * `set` is a pure column UPDATE. A `set` for a sha256 with no blob row updates nothing and throws
 * nothing — the correct outcome, since there is no blob to describe.
 */
export class SqlMediaContentTypeStore implements MediaContentTypeStorePort {
  protected readonly kernel: ContentKernel;
  constructor(kernel: ContentKernel) {
    this.kernel = kernel;
  }

  async getMany(required: { workspaceId: UUID; sha256s: readonly string[] }): Promise<Map<string, string>> {
    if (required.sha256s.length === 0) return new Map();
    const rows = await this.kernel.run((db) =>
      db
        .selectFrom("asset_blobs")
        .select(["sha256", "content_type"])
        .where("workspace_id", "=", required.workspaceId)
        .where("sha256", "in", [...required.sha256s])
        .execute()
    );

    const found = new Map<string, string>();
    for (const row of rows) {
      // A `null` column is "not sniffed yet" and must stay ABSENT from the map rather than become
      // a null entry — the port's `getMany` contract is what lets a caller tell that apart from a
      // recorded `application/octet-stream`.
      if (row.content_type != null) found.set(row.sha256, row.content_type);
    }
    return found;
  }

  async set(required: { workspaceId: UUID; sha256: string; contentType: string }): Promise<void> {
    await this.kernel.run((db) =>
      db
        .updateTable("asset_blobs")
        .set({ content_type: required.contentType })
        .where("workspace_id", "=", required.workspaceId)
        .where("sha256", "=", required.sha256)
        .execute()
    );
  }
}

function toAssetRenditionRecord(row: Selectable<AssetRenditionsTable>): AssetRenditionRecord {
  return {
    id: row.id,
    workspaceId: row.workspace_id,
    assetId: row.asset_id,
    transformName: row.transform_name,
    version: row.version,
    storageKey: row.storage_key,
    createdAt: row.created_at,
  };
}

export class SqlAssetRenditionRepo implements AssetRenditionRepoPort {
  protected readonly kernel: ContentKernel;
  constructor(kernel: ContentKernel) {
    this.kernel = kernel;
  }

  async listByAsset(required: { workspaceId: UUID; assetId: UUID }): Promise<AssetRenditionRecord[]> {
    const rows = await this.kernel.run((db) =>
      db.selectFrom("asset_renditions").selectAll().where("workspace_id", "=", required.workspaceId).where("asset_id", "=", required.assetId).execute()
    );
    return rows.map(toAssetRenditionRecord);
  }

  async findOne(required: { workspaceId: UUID; assetId: UUID; transformName: string; version: number }): Promise<AssetRenditionRecord | null> {
    const row = await this.kernel.run((db) =>
      db
        .selectFrom("asset_renditions")
        .selectAll()
        .where("workspace_id", "=", required.workspaceId)
        .where("asset_id", "=", required.assetId)
        .where("transform_name", "=", required.transformName)
        .where("version", "=", required.version)
        .limit(1)
        .executeTakeFirst()
    );
    return row ? toAssetRenditionRecord(row) : null;
  }

  /** Upsert by id: one statement, so there is no read-then-write window. */
  async save(record: AssetRenditionRecord): Promise<void> {
    const values: AssetRenditionsTable = {
      id: record.id,
      workspace_id: record.workspaceId,
      asset_id: record.assetId,
      transform_name: record.transformName,
      version: record.version,
      storage_key: record.storageKey,
      created_at: record.createdAt,
    };
    const { id: _id, ...updates } = values;
    await this.kernel.run((db) =>
      db
        .insertInto("asset_renditions")
        .values(values)
        .onConflict((oc) => oc.column("id").doUpdateSet(updates))
        .execute()
    );
  }

  async removeByAsset(required: { workspaceId: UUID; assetId: UUID }): Promise<void> {
    await this.kernel.run((db) =>
      db.deleteFrom("asset_renditions").where("workspace_id", "=", required.workspaceId).where("asset_id", "=", required.assetId).execute()
    );
  }
}

function toTransformDefinitionRecord(row: Selectable<TransformRegistryTable>): TransformDefinitionRecord {
  return {
    id: row.id,
    workspaceId: row.workspace_id,
    name: row.name,
    version: row.version,
    params: JSON.parse(row.params_json) as TransformParams,
    owner: row.owner,
    createdAt: row.created_at,
  };
}

export class SqlTransformDefinitionRepo implements TransformDefinitionRepoPort {
  protected readonly kernel: ContentKernel;
  constructor(kernel: ContentKernel) {
    this.kernel = kernel;
  }

  async listByName(required: { workspaceId: UUID; name: string }): Promise<TransformDefinitionRecord[]> {
    const rows = await this.kernel.run((db) =>
      db.selectFrom("transform_registry").selectAll().where("workspace_id", "=", required.workspaceId).where("name", "=", required.name).execute()
    );
    return rows.map(toTransformDefinitionRecord);
  }

  async findByNameVersion(required: { workspaceId: UUID; name: string; version: number }): Promise<TransformDefinitionRecord | null> {
    const row = await this.kernel.run((db) =>
      db
        .selectFrom("transform_registry")
        .selectAll()
        .where("workspace_id", "=", required.workspaceId)
        .where("name", "=", required.name)
        .where("version", "=", required.version)
        .limit(1)
        .executeTakeFirst()
    );
    return row ? toTransformDefinitionRecord(row) : null;
  }

  /** Append-only — the unique `(workspace_id, name, version)` index makes a duplicate insert
   * fail at the storage layer (a unique-constraint violation on any dialect), not just by convention. */
  async insert(record: TransformDefinitionRecord): Promise<void> {
    try {
      await this.kernel.run((db) =>
        db
          .insertInto("transform_registry")
          .values({
            id: record.id,
            workspace_id: record.workspaceId,
            name: record.name,
            version: record.version,
            params_json: JSON.stringify(record.params),
            owner: record.owner,
            created_at: record.createdAt,
          })
          .execute()
      );
    } catch (err) {
      if (isUniqueViolation(err)) {
        throw new Error(
          `transform_registry row (workspace=${record.workspaceId}, name=${record.name}, v${record.version}) already exists — append-only violation`
        );
      }
      throw err;
    }
  }
}

import { sql } from "kysely";
import type { Selectable } from "kysely";

import type { UUID } from "@jini-ai/core/primitives";
import type { OriginSettingRepoPort } from "@jini-ai/http-kit/verified-origin";
import {
  createVerifiedOrigin,
  type OriginScheme,
  type OriginSource,
  type VerifiedOrigin,
} from "@jini-ai/http-kit/verified-origin";
import type { ContentKernel } from "../content-kernel.js";
import type { OriginSettingsTable } from "../content-database.generated.js";

/**
 * @file ADR-046 Phase 1 — THE durable `OriginSettingRepoPort` adapter: one Kysely query body for
 * every dialect (storage plan §4, ADR-066); ADR-006 rule-of-two "second adapter" half,
 * `origin/repo.memory.ts`'s `InMemoryOriginSettingRepo` is the first.
 * `sqlite/origin-repo.sqlite.ts` is the thin layer the composition root builds from the content db
 * handle.
 *
 * Purpose:
 * The workspace's verified origin and its two allowlists previously lived only in-memory in the
 * real running server (`server/deps.ts`) — worse, hardcoded fresh into the constructor's seed
 * array on every boot, not even genuinely "seeded once." This adapter makes the row durable.
 *
 * The READ adapter is read-only by design (matches `OriginSettingRepoPort`, which declares no write
 * method). Writes are two standalone boot-time functions below, not port methods — ADR-006's
 * rule-of-two says don't abstract before the second adapter needs it, and there is still only one
 * durable adapter:
 *
 * 1. {@link seedDevCapabilityOriginOn} — the idempotent find-or-create dev default
 *    (the current loopback listener), preserving operator registrations.
 * 2. {@link registerConfiguredOriginOn} — the operator-declared public origin, from
 *    `features/origin/configured-origin.ts`'s `TOVU_PUBLIC_URL` resolver (2026-09-18; design note:
 *    `ADS-memory/reports/2026-09-18-public-origin-registration-design.md`). This is what finally
 *    closes the "no way to register a real production origin" gap this header used to disclose as
 *    permanent, and it is why production's sitemap can emit absolute URLs again.
 *
 * Both writers are async (the kernel is), so the composition root hands the read adapter the boot
 * write's promise as `after`: every read waits for it, and a boot write that failed fails the reads
 * instead of letting them see a half-booted row.
 *
 * Still open, and still a real gap: no ADMIN route or reachability/ownership VERIFICATION flow
 * exists (ADR-040's own "Open" section keeps that as a v0.1 item). Registration authority today is
 * "whoever can set this deployment's process environment", nothing weaker and nothing stronger.
 */

type Row = Selectable<OriginSettingsTable>;

function toVerifiedOrigin(row: Row): VerifiedOrigin {
  // Built up conditionally, not `port: row.port ?? undefined` — an object literal with an
  // explicit `undefined`-valued key is NOT deep-equal to one that never had the key at all
  // (`assert.deepStrictEqual` is strict about this), and `VerifiedOrigin.port`/`.basePath` are
  // genuinely optional fields the in-memory adapter simply omits when unset.
  const candidate: VerifiedOrigin = {
    scheme: row.scheme as OriginScheme,
    host: row.host,
    verifiedAt: row.verified_at,
    source: row.source as OriginSource,
  };
  if (row.port != null) candidate.port = row.port;
  if (row.base_path != null) candidate.basePath = row.base_path;
  return createVerifiedOrigin(candidate);
}

function normalizeHostList(hosts: string[] | undefined): string[] {
  return (hosts ?? []).map((host) => host.trim().toLowerCase());
}

export class SqlOriginSettingRepo implements OriginSettingRepoPort {
  /** @param options.after - Reads wait for it (the composition root's boot write); see the file header. */
  protected readonly kernel: ContentKernel;
  private readonly options: { after?: Promise<unknown> };
  constructor(
    kernel: ContentKernel,
    options: { after?: Promise<unknown> } = {}
  ) {
    this.kernel = kernel;
    this.options = options;
  }

  private async row(workspaceId: UUID): Promise<Row | undefined> {
    await this.options.after;
    return this.kernel.run((db) => db.selectFrom("origin_settings").selectAll().where("workspace_id", "=", workspaceId).executeTakeFirst());
  }

  async findByWorkspaceId({ workspaceId }: { workspaceId: UUID }): Promise<VerifiedOrigin | null> {
    const row = await this.row(workspaceId);
    return row ? toVerifiedOrigin(row) : null;
  }

  async findRedirectAllowlist({ workspaceId }: { workspaceId: UUID }): Promise<string[]> {
    const row = await this.row(workspaceId);
    return row ? (JSON.parse(row.redirect_allowlist_json) as string[]) : [];
  }

  async findEgressAllowlist({ workspaceId }: { workspaceId: UUID }): Promise<string[]> {
    const row = await this.row(workspaceId);
    return row ? (JSON.parse(row.egress_allowlist_json) as string[]) : [];
  }
}

const LOOPBACK_HOSTS = ["localhost", "127.0.0.1", "::1"];

/**
 * Idempotent boot seed. Only a dev-capability loopback row follows a changed listener's scheme
 * and port. Owner registrations, non-loopback rows, base paths and allowlists are never overwritten.
 * The conditional upsert is atomic, including when another process registers an origin concurrently.
 * @complexity O(1), one primary-key upsert.
 */
export async function seedDevCapabilityOriginOn(
  kernel: ContentKernel,
  seed: { workspaceId: UUID; origin: VerifiedOrigin; redirectAllowlist?: string[]; egressAllowlist?: string[] }
): Promise<void> {
  const verified = createVerifiedOrigin(seed.origin);
  const refreshesLoopback = verified.source === "dev-capability" && LOOPBACK_HOSTS.includes(verified.host);
  await kernel.run((db) =>
    db
      .insertInto("origin_settings")
      .values({
        workspace_id: seed.workspaceId,
        scheme: verified.scheme,
        host: verified.host,
        port: verified.port ?? null,
        base_path: verified.basePath ?? null,
        verified_at: verified.verifiedAt,
        source: verified.source,
        redirect_allowlist_json: JSON.stringify(normalizeHostList(seed.redirectAllowlist)),
        egress_allowlist_json: JSON.stringify(normalizeHostList(seed.egressAllowlist)),
      })
      .onConflict((oc) => !refreshesLoopback ? oc.column("workspace_id").doNothing() : oc.column("workspace_id").doUpdateSet({
        scheme: verified.scheme, port: verified.port ?? null, verified_at: verified.verifiedAt,
      }).where("origin_settings.source", "=", "dev-capability")
        .where("origin_settings.host", "in", LOOPBACK_HOSTS)
        // Unchanged listener: no write, so its verification stamp does not churn on every boot.
        .where(sql<boolean>`(origin_settings.scheme <> ${verified.scheme} OR origin_settings.port IS DISTINCT FROM ${verified.port ?? null})`))
      .execute()
  );
}

/** What {@link registerConfiguredOriginOn} did, so the composition root can log it. */
export type ConfiguredOriginWriteResult = "inserted" | "updated" | "unchanged";

/** The origin columns only — deliberately NOT the allowlist columns. See
 *  {@link registerConfiguredOriginOn}. */
function originColumns(origin: VerifiedOrigin) {
  return {
    scheme: origin.scheme,
    host: origin.host,
    port: origin.port ?? null,
    base_path: origin.basePath ?? null,
    verified_at: origin.verifiedAt,
    source: origin.source,
  };
}

/**
 * Whether the stored row already names the same origin. `verifiedAt` is excluded on purpose: it is
 * a stamp, not part of the origin's identity, so including it would make every boot an UPDATE and
 * churn the row forever.
 *
 * @complexity O(1).
 */
function sameOrigin(row: Row, origin: VerifiedOrigin): boolean {
  return (
    row.scheme === origin.scheme &&
    row.host === origin.host &&
    row.port === (origin.port ?? null) &&
    row.base_path === (origin.basePath ?? null) &&
    row.source === origin.source
  );
}

/**
 * Registers the operator-declared public origin — insert-or-correct, NOT find-or-create.
 *
 * This is deliberately a different function with a different contract from
 * {@link seedDevCapabilityOriginOn}, not a change to it. The certified idempotency test
 * (`features/origin/__tests__/repo.contract.test.ts`) protects "a re-run of the boot seed can never
 * clobber a real registered origin", and that assertion stands unchanged: the dev seed only refreshes its own loopback listener
 * scheme and port. What this function adds is the one authority that IS allowed to correct the
 * row — whoever can set this deployment's process environment (the host's secret store /
 * the deploy workflow's non-secret env inputs to the hosting plugin), which is strictly more privileged than an admin-UI login and can already deploy
 * arbitrary code. Without a correcting writer, production's `http://localhost:3000` row — durably
 * persisted by the first production boot and immortal under find-or-create — could never be fixed without a
 * hand-written migration against the live DB.
 *
 * WRITES THE ORIGIN COLUMNS ONLY. `redirect_allowlist_json` and `egress_allowlist_json` are left
 * exactly as found. A blind full-row overwrite would silently empty both, which in production
 * fail-closes every `isAllowedEgressTarget` check — a behavior change with no relationship to the
 * origin it is here to fix. Pinned by that suite's "preserves both allowlists" test.
 *
 * The read and the write run in one kernel transaction under `lockKey` on the workspace's row, so
 * two booting processes cannot both see "no row" and both insert.
 *
 * @param origin - Re-validated through `createVerifiedOrigin`, so the ADR-040 scheme/source
 * invariant cannot be bypassed by a caller that hand-built the object.
 * @returns which write happened, for the boot log.
 * @throws {InsecureOriginSourceError} if `origin` violates the scheme/source invariant. Callers
 * pass `resolveConfiguredOrigin`'s output, which can never produce that combination.
 * @complexity O(1) — one indexed lookup plus at most one write.
 */
export async function registerConfiguredOriginOn(
  kernel: ContentKernel,
  workspaceId: UUID,
  origin: VerifiedOrigin
): Promise<ConfiguredOriginWriteResult> {
  const verified = createVerifiedOrigin(origin);
  return kernel.transaction(async () => {
    await kernel.lockKey(`origin_settings:${workspaceId}`);
    const existing = await kernel.run((db) =>
      db.selectFrom("origin_settings").selectAll().where("workspace_id", "=", workspaceId).executeTakeFirst()
    );
    if (!existing) {
      await kernel.run((db) =>
        db
          .insertInto("origin_settings")
          .values({ workspace_id: workspaceId, ...originColumns(verified), redirect_allowlist_json: "[]", egress_allowlist_json: "[]" })
          .execute()
      );
      return "inserted";
    }

    if (sameOrigin(existing, verified)) return "unchanged";

    await kernel.run((db) => db.updateTable("origin_settings").set(originColumns(verified)).where("workspace_id", "=", workspaceId).execute());
    return "updated";
  });
}

/** Trusted helper entrypoint. Never import archived code or execute source DDL/migrations.
 * SQLite native work is isolated from the serving process and killed by its parent deadline.
 */
import { sql } from "kysely";
import { openSqliteConnection, verifySqliteIntegrity } from "@jini-ai/db/sqlite";
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { openContentDb } from "./content-db.js";
import { sqliteKernel, closeSqliteConnection, openNativeSqlite, openSqliteFileKernel, sqliteConnectionOf } from "../kernel/drivers/sqlite.js";
import { listColumns } from "../kernel/dialect.js";
import { sqliteForeignKeyCheckedTransaction, sqliteSchemaObjects } from "../kernel/sqlite-only.js";
import type { StorageKernel } from "../kernel/port.js";
import { sanitizeShareDatabase, prepareSharePluginTables } from "./share-database.js";
import { SHARE_TABLES } from "#src/features/site-backup/share-policy";
import { readTemplate } from "#src/platform/site-dir/read-template";
import { computeBlobStorageKey } from "#src/features/media/index";

type ImportKernel = StorageKernel<Record<string, Record<string, unknown>>>;

/** These portable relationships are application-owned rather than SQLite FKs. Identity actor
 * strings are intentionally excluded: the share policy omits source accounts, not attribution.
 * Each join uses existing id/lookup indexes; the helper's byte/deadline caps bound the scan.
 * @throws Error if any fixed relationship is dangling; reads only.
 * @complexity O(portable rows) across six fixed joins, with at most one result per join.
 */
async function validatePortableReferences(required: { db: ImportKernel }, _options: Record<string, never> = {}): Promise<void> {
  const checks = [
    "SELECT 1 FROM nav_location_bindings b LEFT JOIN menus m ON m.workspace_id=b.workspace_id AND m.id=b.menu_id WHERE m.id IS NULL LIMIT 1",
    "SELECT 1 FROM media m LEFT JOIN asset_blobs b ON b.workspace_id=m.workspace_id AND b.sha256=m.source_sha256 WHERE b.id IS NULL LIMIT 1",
    "SELECT 1 FROM asset_renditions r LEFT JOIN media m ON m.workspace_id=r.workspace_id AND m.id=r.asset_id WHERE m.id IS NULL LIMIT 1",
    "SELECT 1 FROM posts p LEFT JOIN media m ON m.workspace_id=p.workspace_id AND m.id=p.featured_media_id WHERE p.featured_media_id IS NOT NULL AND m.id IS NULL LIMIT 1",
    "SELECT 1 FROM widget_region_bindings b LEFT JOIN entries e ON e.workspace_id=b.workspace_id AND e.id=b.area_entry_id WHERE e.id IS NULL LIMIT 1",
    "SELECT 1 FROM entry_terms r LEFT JOIN terms t ON t.workspace_id=r.workspace_id AND t.id=r.term_id WHERE t.id IS NULL LIMIT 1",
  ];
  for (const check of checks) if ((await required.db.query(sql.raw(check))).length) throw new Error("Dangling portable content reference");
}

/** Exact trusted schema equality rejects views, virtual-table substitutions, hidden/generated
 * columns, CHECK expressions, extension triggers and malicious indices before table reads.
 * The archive's migration ledger is data only and is never used to choose code to execute.
 * @complexity O(schema objects + database rows), bounded by the helper's input/deadline caps.
 */
async function run(required: { root: string }, _options: Record<string, never> = {}): Promise<void> {
  const sourceOptions = { readonly: true, fileMustExist: true, timeout: 1000 };
  const source = openSqliteConnection({ filePath: path.join(required.root, "input.db"),
    open: ({ filePath }) => openNativeSqlite(filePath, sourceOptions),
  }, { pragmas: ["trusted_schema = OFF", "query_only = ON"] });
  const sourceKernel = sqliteKernel<Record<string, Record<string, unknown>>>(source);
  const trusted = openContentDb({ filePath: ":memory:" });
  let portablePluginTables = new Set<string>();
  try {
    // Extension loading remains disabled: this helper never exposes/calls loadExtension.
    const actual = await sqliteSchemaObjects({ kernel: sourceKernel });
    const plugins = await prepareSharePluginTables({ target: sqliteKernel(trusted), present: new Set(actual.filter(object => object.type === "table").map(object => object.name)) });
    portablePluginTables = plugins.portable;
    const expected = await sqliteSchemaObjects({ kernel: sqliteKernel(trusted) });
    // No archived SQL is executed or relaxed: every table, index and trigger must match
    // this build. Historical ADD COLUMN schema variants are not part of the v2 contract.
    if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error("Unsupported SQLite schema objects");
    if ((await sourceKernel.query(sql`SELECT id FROM workspaces LIMIT 2`)).length !== 1) throw new Error("Import requires one workspace");
    // Source FKs may reference private rows omitted by projection; validate rebuilt FKs below.
    if (verifySqliteIntegrity({ db: source, quick: true }).issues.some(issue => issue.kind === "integrity")) throw new Error("Invalid SQLite integrity");
  } finally { source.close(); closeSqliteConnection(trusted); }
  const projection = await sanitizeShareDatabase({ snapshot: await readFile(path.join(required.root, "input.db")) });
  const output = path.join(required.root, "output.db");
  await writeFile(output, projection.bytes, { flag: "wx", mode: 0o600 });
  const fresh = openSqliteFileKernel<Record<string, Record<string, unknown>>>(output);
  const documentKeys = new Map<string, string>();
  try {
    const workspaces = await fresh.query<{ id: string }>(sql`SELECT id FROM workspaces LIMIT 2`);
    if (workspaces.length !== 1) throw new Error("Import requires exactly one workspace");
    const recipient = readTemplate({ templateId: "starter" }).seed.workspace.id;
    // Runtime queries use the recipient template workspace. Content/media IDs stay stable.
    // Defer FKs while both sides change, then validate before commit through the kernel owner.
    await sqliteForeignKeyCheckedTransaction({ kernel: fresh, onViolation: () => new Error("Invalid imported references"), work: async () => {
      for (const table of [...SHARE_TABLES, ...portablePluginTables, "setting_values_workspace"]) {
        const columns = await listColumns(fresh, table);
        if (columns.some(column => column.name === "workspace_id")) {
          if ((await fresh.query(sql`SELECT 1 FROM ${sql.table(table)} WHERE workspace_id <> ${workspaces[0]!.id} LIMIT 1`)).length) throw new Error("Portable row belongs to a missing workspace");
          // Identifiers come exclusively from the trusted core allowlist and bundled declarations.
          await fresh.execute(sql`UPDATE ${sql.table(table)} SET workspace_id = ${recipient}`);
        }
      }
      await fresh.execute(sql`UPDATE workspaces SET id = ${recipient}`);
      // Documents must keep canonical keys in the recipient workspace, including blobs shared
      // with ordinary media. Return the mapping so the verifier moves only verified bytes.
      const documents = await fresh.query<{ storage_key: string; sha256: string }>(sql`SELECT DISTINCT b.storage_key, b.sha256 FROM asset_blobs b JOIN media m ON m.workspace_id=b.workspace_id AND m.source_sha256=b.sha256 WHERE m.kind='document'`);
      for (const blob of documents) {
        const destination = computeBlobStorageKey({ workspaceId: recipient, sha256: blob.sha256 });
        documentKeys.set(blob.storage_key, destination);
        await fresh.execute(sql`UPDATE asset_blobs SET storage_key=${destination} WHERE workspace_id=${recipient} AND sha256=${blob.sha256}`);
      }
      // Scan renditions once rather than issuing one unindexed storage-key scan per blob.
      const renditions = await fresh.query<{ id: string; storage_key: string }>(sql`SELECT id,storage_key FROM asset_renditions`);
      for (const rendition of renditions) {
        const destination = documentKeys.get(rendition.storage_key);
        if (destination) await fresh.execute(sql`UPDATE asset_renditions SET storage_key=${destination} WHERE id=${rendition.id}`);
      }
    } });
    await validatePortableReferences({ db: fresh });
    if (!verifySqliteIntegrity({ db: sqliteConnectionOf(fresh)!, quick: true }).ok) throw new Error("Invalid rebuilt database");
  } finally { await fresh.close(); }
  const media = projection.media.map(blob => documentKeys.has(blob.storageKey) ? { ...blob, destinationStorageKey: documentKeys.get(blob.storageKey) } : blob);
  await writeFile(path.join(required.root, "media.json"), JSON.stringify(media), { flag: "wx", mode: 0o600 });
  // sanitizeShareDatabase() always returns both lists; they are optional only on the shared projection type.
  await writeFile(path.join(required.root, "documents.json"), JSON.stringify(projection.documents!), { flag: "wx", mode: 0o600 });
}

run({ root: process.argv[2]! }).then(() => process.exit(0), () => process.exit(1));

import { sql } from "kysely";
import type { ContentKernel } from "../content-kernel.js";
import { sqliteForeignKeyCheckedTransaction, sqliteTableInfo } from "../kernel/sqlite-only.js";
import type { RawColumn, RawRowPort, RawValue } from "#src/features/publish-content/backstop-ports";
import { checkRawTable } from "#src/features/publish-content/backstop-policy";

function identifier(name: string): string {
  if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(name)) throw new Error("Invalid raw database identifier.");
  return `"${name}"`;
}
function allowed(table: string, columns: readonly string[]): void {
  const denied = checkRawTable({ table, columns });
  if (denied) throw new Error(denied);
}
function encode(value: unknown): RawValue {
  if (value instanceof Uint8Array) return { blobBase64: Buffer.from(value).toString("base64") };
  // The default SQLite driver reads INTEGER as number; refuse values that JSON would round.
  if (value === null || typeof value === "string" || (typeof value === "number" && Number.isFinite(value) &&
    (!Number.isInteger(value) || Number.isSafeInteger(value)))) return value;
  throw new Error("This row contains a database value that cannot be sent safely.");
}
function decode(value: RawValue): string | number | null | Buffer {
  return typeof value === "object" && value !== null ? Buffer.from(value.blobBase64, "base64") : value;
}

/** Site content.db adapter, using Jini's storage kernel for transaction serialization (including
 * nested command gateways). It never opens a second connection and does no schema installation. */
export function createRawRowSqlitePort({ kernel }: { kernel: ContentKernel }, _optional: Record<string, never> = {}): RawRowPort {
  if (kernel.dialect !== "sqlite") throw new Error("Send by hand currently requires a SQLite content database.");
  async function columns({ table }: { table: string }): Promise<readonly RawColumn[] | null> {
    allowed(table, []);
    // SQLite's own table_info shape, not listColumns': both peers compare and hash it (see sqlite-only.ts).
    const info = await sqliteTableInfo({ kernel, table });
    if (!info) return null;
    identifier(table); // a live table whose name later SQL could not quote is refused here, as before
    allowed(table, info.map((c) => c.name));
    return info.map(({ name, type, pk, notnull }) => ({ name, type, pk, notnull })).sort((a, b) => a.name.localeCompare(b.name));
  }
  /** Callers run verifyPk() first, which already refuses an empty or partial primary key. */
  function where(pk: Readonly<Record<string, RawValue>>) {
    return sql.join(Object.entries(pk).map(([name, value]) => sql`${sql.raw(identifier(name))} = ${decode(value)}`), sql` AND `);
  }
  async function verifyPk(table: string, pk: Readonly<Record<string, RawValue>>): Promise<readonly RawColumn[]> {
    const info = await columns({ table });
    if (!info) throw new Error(`Table '${table}' does not exist.`);
    const names = info.filter((c) => c.pk > 0).map((c) => c.name).sort();
    if (names.length === 0 || JSON.stringify(names) !== JSON.stringify(Object.keys(pk).sort()) ||
      Object.values(pk).some((value) => value === null || !["string", "number"].includes(typeof value))) throw new Error("Choose a row by its complete primary key.");
    return info;
  }
  return {
    columns,
    read: async ({ table, pk }) => {
      const info = await verifyPk(table, pk);
      const [row] = await kernel.query<Record<string, unknown>>(sql`SELECT * FROM ${sql.raw(identifier(table))} WHERE ${where(pk)}`);
      return row ? { table, pk, columns: info, values: Object.fromEntries(Object.entries(row).map(([name, value]) => [name, encode(value)])) } : null;
    },
    upsert: async ({ table, pk, values }) => {
      allowed(table, Object.keys(values));
      const info = await verifyPk(table, pk);
      if (JSON.stringify(Object.keys(values).sort()) !== JSON.stringify(info.map((c) => c.name).sort()) ||
        Object.keys(pk).some((name) => values[name] !== pk[name])) throw new Error("The raw row does not contain every column or its primary key.");
      const names = Object.keys(values).sort();
      const nonPk = names.filter((name) => !Object.hasOwn(pk, name));
      const updates = nonPk.length > 0 ? sql`DO UPDATE SET ${sql.join(nonPk.map((name) => sql`${sql.raw(identifier(name))} = excluded.${sql.raw(identifier(name))}`))}` : sql`DO NOTHING`;
      await kernel.execute(sql`INSERT INTO ${sql.raw(identifier(table))} (${sql.join(names.map((name) => sql.raw(identifier(name))))})
        VALUES (${sql.join(names.map((name) => sql`${decode(values[name]!)}`))})
        ON CONFLICT (${sql.join(Object.keys(pk).map((name) => sql.raw(identifier(name))))}) ${updates}`);
    },
    removeCreated: async ({ table, pk }) => {
      await verifyPk(table, pk);
      await kernel.execute(sql`DELETE FROM ${sql.raw(identifier(table))} WHERE ${where(pk)}`);
    },
    transaction: async ({ work }) => {
      // A per-row gateway may join the push's outer transaction; only that outer call checks FKs.
      if (kernel.inTransaction()) return work();
      return sqliteForeignKeyCheckedTransaction({ kernel, work, onViolation: (first) =>
        new Error(`Foreign key check failed: '${first.table}' row '${first.rowid}' points at a missing '${first.parent}' row; this send was rolled back.`) });
    },
  };
}

import type { ArchiveMediaSource, ArchiveMediaCopy } from "#src/features/site-backup/archive-media";
import { mkdtemp, rm, statfs, writeFile } from "node:fs/promises";
import { scheduler } from "node:timers/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { sql } from "kysely";
import { redactSecretShapes } from "#src/contracts/core/secret-redaction";
import { validateValueAgainstSchema, type SettingValueSchema } from "@jini-ai/core/settings";
import type { JsonValue } from "@jini-ai/core/primitives";
import { PUBLISHABLE_SETTINGS } from "#src/features/settings/publish-content";
import { backfillPostSearchIndex } from "#src/features/post/search-index";
import { SHARE_TABLES, SHARE_LEGACY_PRIVATE_TABLES, SHARE_LIMITS, SiteShareRefusal, type ShareDatabaseProjection } from "#src/features/site-backup/share-policy";
import { requireShareSecretFree } from "#src/features/site-backup/share-file-policy";
import { computeBlobStorageKey, documentContentType } from "#src/features/media/index";
import { listColumns, listTables } from "../kernel/dialect.js";
import { openSqliteFileKernel, sqliteKernel, sqliteClientOf, sqliteConnectionOf, closeSqliteConnection } from "../kernel/drivers/sqlite.js";
import type { StorageKernel } from "../kernel/port.js";
import { CHAT_TABLE_NAMES } from "./chat-orphan-check.js";
import { openContentDb } from "./content-db.js";
import { FIRST_PARTY_DATA_MODULES } from "#src/features/plugins/data-modules";
import { declareDataModule, type DataModuleDecl, type TableDecl } from "#src/features/plugins/data-module";

type Row = Record<string, unknown>;
type Tables = Record<string, Row>;
type Kernel = StorageKernel<Tables>;
/** Free-space probe for the private staging directory (`node:fs/promises` `statfs` by default). */
export type StagingSpacePort = (path: string) => Promise<{ bavail: number; bsize: number }>;

/** Build only present portable plugin tables through the existing trusted DDL owner.
 * Private tables contribute neither schema nor rows. O(declared tables + columns).
 * `modules` is the trusted bundled registry; tests pass their own typed declarations.
 * @throws SiteShareRefusal if the trusted declaration cannot be installed.
 */
export async function prepareSharePluginTables(required: { target: Kernel; present: ReadonlySet<string> }, { modules = FIRST_PARTY_DATA_MODULES }: { modules?: readonly DataModuleDecl[] } = {}): Promise<{ portable: Set<string>; private: Set<string> }> {
  const portable = new Set<string>();
  const privateTables = new Set<string>();
  for (const decl of modules) {
    const plan = sharePluginPlan({ decl, present: required.present });
    plan.portable.forEach(name => portable.add(name));
    plan.private.forEach(name => privateTables.add(name));
    if (plan.tables.length) await declarePortableTables({ target: required.target, decl, tables: plan.tables });
  }
  return { portable, private: privateTables };
}

/** One trusted declaration's share plan: its present portable tables trimmed to their policy
 * columns, and the physical names of its private tables (present or not). Pure; O(tables + columns).
 * @throws SiteShareRefusal when a portable policy names a column the table does not declare.
 */
function sharePluginPlan(required: { decl: DataModuleDecl; present: ReadonlySet<string> }, _options: Record<string, never> = {}): { tables: TableDecl[]; portable: string[]; private: string[] } {
  const plan: { tables: TableDecl[]; portable: string[]; private: string[] } = { tables: [], portable: [], private: [] };
  for (const table of required.decl.tables) {
    const name = `p_${required.decl.pluginId}__${table.name}`;
    const policy = table.portability;
    if (policy?.kind === "private") plan.private.push(name);
    if (policy?.kind !== "portable" || !required.present.has(name)) continue;
    plan.portable.push(name);
    plan.tables.push(portableColumnsOnly({ name, table, columns: policy.columns }));
  }
  return plan;
}

/** The table declaration narrowed to exactly its portable policy columns. O(columns × policy columns).
 * @throws SiteShareRefusal when the policy names a column the declaration lacks. */
function portableColumnsOnly(required: { name: string; table: TableDecl; columns: readonly string[] }, _options: Record<string, never> = {}): TableDecl {
  const columns = required.table.columns.filter(column => required.columns.includes(column.name));
  if (columns.length !== required.columns.length) throw new SiteShareRefusal({ code: "UNSUPPORTED_SCHEMA", message: `Invalid portable columns for '${required.name}': its portability policy names a column the table does not declare.` });
  return { ...required.table, columns };
}

/** Installs the trimmed portable tables through `declareDataModule`, the trusted DDL owner.
 * @throws SiteShareRefusal carrying the declaration error when the owner refuses. */
async function declarePortableTables(required: { target: Kernel; decl: DataModuleDecl; tables: TableDecl[] }, _options: Record<string, never> = {}): Promise<void> {
  const result = await declareDataModule({ db: required.target, dbPath: ":memory:", decl: { ...required.decl, tables: required.tables } });
  if (!result.ok) throw new SiteShareRefusal({ code: "UNSUPPORTED_SCHEMA", message: `Cannot build portable plugin schema for '${required.decl.pluginId}': ${result.error?.message}` });
}

/** Never execute source DDL. Even an unknown empty table contributes no schema. O(tables).
 * `listTables` already omits SQLite's own `sqlite_*` tables. */
async function refuseUnknownTables(source: Kernel, trusted: Set<string>): Promise<void> {
  for (const table of await listTables(source)) {
    if (trusted.has(table) || SHARE_LEGACY_PRIVATE_TABLES.has(table) || CHAT_TABLE_NAMES.includes(table) || table.startsWith("_vault_backup_")) continue;
    const rows = await source.query<{ found: number }>(sql`SELECT 1 AS found FROM ${sql.id(table)} LIMIT 1`);
    if (rows.length) throw new SiteShareRefusal({ code: "UNSUPPORTED_DATA", message: `Cannot share unsupported nonempty table '${table}'. Add an approved portable-data policy for this table first.` });
  }
}

// Only the additive Library columns may be absent in an older share. Never accept an
// archive's DDL. Plugin owners explicitly allow dropping fields outside their column policy.
const ADDITIVE_COLUMN_DEFAULTS: ReadonlyMap<string, Row> = new Map<string, Row>([
  ["media", { kind: "media", original_filename: null }],
  ["asset_blobs", { document_owned: 0 }],
]);

/** Refuses a source table whose columns differ from the trusted target schema: an extra source
 * column (unless a portable plugin table, whose extra fields are dropped) or a missing column with
 * no additive default. Pure; O(columns²) over two short column lists.
 * @throws SiteShareRefusal UNSUPPORTED_SCHEMA naming the table. */
function requireTrustedColumns(required: { table: string; columns: string[]; sourceColumns: string[]; defaults: Row }, { portablePlugin = false }: { portablePlugin?: boolean } = {}): void {
  const extra = !portablePlugin && required.sourceColumns.some(column => !required.columns.includes(column));
  const missing = required.columns.some(column => !required.sourceColumns.includes(column) && !Object.hasOwn(required.defaults, column));
  if (extra || missing) throw new SiteShareRefusal({ code: "UNSUPPORTED_SCHEMA", message: `Cannot share '${required.table}': its columns differ from the trusted current schema. Update the site first.` });
}

/** Copy rows using the trusted schema, preserving only explicit portable plugin columns.
 * Core extension columns still refuse; historical Library columns retain their trusted defaults.
 * O(rows × columns) projection/insertion; rows remain bounded by the snapshot cap.
 * @throws SiteShareRefusal for missing required columns or unapproved core columns.
 */
async function copyTable({ source, target, table }: { source: Kernel; target: Kernel; table: string }, { signal, portablePlugin }: { signal?: AbortSignal; portablePlugin?: boolean } = {}): Promise<void> {
  const columns = (await listColumns(target, table)).map(row => row.name);
  const sourceColumns = (await listColumns(source, table)).map(row => row.name);
  const defaults = ADDITIVE_COLUMN_DEFAULTS.get(table) ?? {};
  requireTrustedColumns({ table, columns, sourceColumns, defaults }, { portablePlugin });
  const rows = await source.run(db => db.selectFrom(table).select(columns.filter(column => sourceColumns.includes(column))).execute());
  const project = await mediaRowProjection({ target, table });
  for (const [index, sourceRow] of rows.entries()) {
    if (index % 1000 === 0) { await scheduler.yield(); signal?.throwIfAborted(); }
    const row = project({ ...defaults, ...sourceRow });
    if (row) await target.run(db => db.insertInto(table).values(row).execute());
  }
}

const SIDECAR_TABLES: readonly string[] = ["media_slug_history", "asset_blobs", "asset_renditions"];

/** Who owns which bytes, from the retained (already projected) `media` rows. */
interface MediaOwners {
  readonly byId: ReadonlyMap<string, Row>;
  readonly byHash: ReadonlyMap<string, { document: boolean; media: boolean }>;
  /** Blob keys only a document owns: no active public-media owner shares the bytes. */
  readonly privateKeys: ReadonlySet<string>;
}

/** Workspace-scoped identity key for an owner lookup. O(1). */
function ownerKey(workspace: unknown, identity: unknown): string {
  return JSON.stringify([workspace, identity]);
}

/** Select sidecars from retained editorial owners, never the filesystem or orphan blobs.
 * One bounded owner scan per sidecar table, then O(1) lookup per row; O(media rows) space.
 * Document ownership is sticky even when an active public-media owner shares the bytes.
 */
async function mediaRowProjection(required: { target: Kernel; table: string }, _options: Record<string, never> = {}): Promise<(row: Row) => Row | null> {
  if (required.table === "media") return projectMediaRow;
  if (!SIDECAR_TABLES.includes(required.table)) return row => row;
  const owners = indexMediaOwners({ owners: await required.target.run(db => db.selectFrom("media").selectAll().execute()) });
  if (required.table === "asset_blobs") return row => projectAssetBlob({ row, owners });
  const ownerColumn = required.table === "media_slug_history" ? "media_id" : "asset_id";
  return row => {
    const owner = owners.byId.get(ownerKey(row.workspace_id, row[ownerColumn]));
    if (!owner) return null;
    return required.table === "asset_renditions" ? projectRendition({ row, owner, privateKeys: owners.privateKeys }) : row;
  };
}

/** Ordinary media travels as is; an active document loses its uploader; any other document drops.
 * @throws SiteShareRefusal INVALID_DOCUMENT for a kind other than media/document. O(1). */
function projectMediaRow(row: Row): Row | null {
  if (row.kind !== "media" && row.kind !== "document") throw new SiteShareRefusal({ code: "INVALID_DOCUMENT", message: "Unsupported media kind in share database." });
  if (row.kind === "media") return row;
  return row.status === "active" ? { ...row, created_by: null } : null;
}

/** Indexes the retained media rows by id and by content hash, and derives document-only blob keys.
 * O(media rows) time and space. */
function indexMediaOwners(required: { owners: Row[] }, _options: Record<string, never> = {}): MediaOwners {
  const byId = new Map(required.owners.map(row => [ownerKey(row.workspace_id, row.id), row]));
  const byHash = new Map<string, { document: boolean; media: boolean }>();
  for (const row of required.owners) {
    const hash = ownerKey(row.workspace_id, row.source_sha256);
    const kinds = byHash.get(hash) ?? { document: false, media: false };
    if (row.kind === "document") kinds.document = true;
    else if (row.status === "active") kinds.media = true;
    byHash.set(hash, kinds);
  }
  const privateKeys = new Set(required.owners.filter(row => row.kind === "document" && !byHash.get(ownerKey(row.workspace_id, row.source_sha256))?.media)
    .map(row => computeBlobStorageKey({ workspaceId: String(row.workspace_id), sha256: String(row.source_sha256) })));
  return { byId, byHash, privateKeys };
}

/** A blob travels only with a retained owner of its bytes; document bytes stay marked share-owned. O(1). */
function projectAssetBlob(required: { row: Row; owners: MediaOwners }, _options: Record<string, never> = {}): Row | null {
  const kinds = required.owners.byHash.get(ownerKey(required.row.workspace_id, required.row.sha256));
  if (!kinds) return null;
  return { ...required.row, ...(kinds.document || required.row.document_owned === 1 ? { document_owned: 1, created_by_principal: "share" } : {}) };
}

/** A rendition of a retained owner: ordinary owners may not reach document-only bytes; a document
 * keeps only its `original`, which must be its own source blob. O(1).
 * @throws SiteShareRefusal INVALID_DOCUMENT for either forged reference. */
function projectRendition(required: { row: Row; owner: Row; privateKeys: ReadonlySet<string> }, _options: Record<string, never> = {}): Row | null {
  const { row, owner } = required;
  // A public rendition must never borrow a document-only source, even across owners.
  // Check before the import worker remaps keys and loses the source ownership boundary.
  if (owner.kind !== "document") {
    if (required.privateKeys.has(String(row.storage_key))) throw new SiteShareRefusal({ code: "INVALID_DOCUMENT", message: "Ordinary rendition references a private document blob." });
    return row;
  }
  if (row.transform_name !== "original") return null;
  if (row.storage_key !== computeBlobStorageKey({ workspaceId: String(owner.workspace_id), sha256: String(owner.source_sha256) })) throw new SiteShareRefusal({ code: "INVALID_DOCUMENT", message: "Document original rendition has an invalid blob key." });
  return row;
}

/** Validate document identity against its retained blob before reading bytes through storage.
 * O(media + blob rows) time/space; missing/corrupt document references explicitly refuse.
 */
async function documentReferences(required: { target: Kernel }, _options: Record<string, never> = {}): Promise<NonNullable<ShareDatabaseProjection["documents"]>> {
  const blobs = await required.target.run(db => db.selectFrom("asset_blobs").selectAll().execute());
  const byHash = new Map(blobs.map(row => [ownerKey(row.workspace_id, row.sha256), row]));
  const documents = await required.target.run(db => db.selectFrom("media").selectAll().where("kind", "=", "document").execute());
  return documents.map(row => {
    const sha256 = String(row.source_sha256);
    const blob = byHash.get(ownerKey(row.workspace_id, row.source_sha256));
    const storageKey = computeBlobStorageKey({ workspaceId: String(row.workspace_id), sha256 });
    if (!/^[a-f0-9]{64}$/.test(sha256) || !blob || blob.storage_key !== storageKey || blob.status !== "active" || typeof row.original_filename !== "string") throw new SiteShareRefusal({ code: "INVALID_DOCUMENT", message: "Document source blob is missing or has an invalid key/hash." });
    documentContentType({ filename: row.original_filename });
    return { storageKey, sha256, originalFilename: row.original_filename };
  });
}

/** True when `text` holds anything credential-shaped. O(text). */
function hasSecretShape(required: { text: string }, _options: Record<string, never> = {}): boolean {
  return redactSecretShapes({ text: required.text }).redactions > 0;
}

/**
 * Scans projected text values separately from SQLite's concatenated record encoding.
 * @throws SiteShareRefusal SECRET_IN_CONTENT without exposing a value, column or row.
 * @complexity O(projected bytes) time; O(largest table) space, bounded by the snapshot cap.
 */
async function requireProjectedSecretFree({ target }: { target: Kernel }, _options = {}): Promise<void> {
  for (const table of await listTables(target)) {
    const rows = await target.run(db => db.selectFrom(table).selectAll().execute());
    for (const row of rows) {
      for (const value of Object.values(row)) {
        if (typeof value === "string") requireShareSecretFree({ path: "database/content.db", bytes: Buffer.from(value) });
      }
    }
  }
}

/** Only non-secret portable definitions/workspace values travel. Secret-bearing definitions/values are omitted, never rewritten. */
async function copySettings(source: Kernel, target: Kernel): Promise<void> {
  const definitions = await source.run(db => db.selectFrom("setting_definitions").selectAll().where("secret", "=", 0).where("status", "=", "active").execute());
  for (const definition of definitions) {
    const schema = portableDefinitionSchema({ definition });
    if (!schema) continue;
    await target.run(db => db.insertInto("setting_definitions").values(definition).execute());
    await copyWorkspaceValues({ source, target, definition, schema });
  }
}

/** The value schema of a definition that may travel — workspace-scoped, publishable, secret-free,
 * with a default its own schema accepts — else null. O(definition text).
 * @throws SyntaxError when the stored schema or default is not JSON. */
function portableDefinitionSchema(required: { definition: Row }, _options: Record<string, never> = {}): SettingValueSchema | null {
  const { definition } = required;
  if (!(Number(definition.scopes) & 2) || !Object.hasOwn(PUBLISHABLE_SETTINGS, `${definition.namespace}:${definition.key}`)) return null;
  const schema = JSON.parse(String(definition.schema_json)) as SettingValueSchema;
  // Preserve ordinary SEO text verbatim. A secret anywhere in a definition omits it whole;
  // changing a schema or default to make redaction validate would silently damage the site.
  if (Object.values(definition).some(value => hasSecretShape({ text: String(value) }))) return null;
  const defaultValue = JSON.parse(String(definition.default_json)) as JsonValue;
  return validateValueAgainstSchema(schema, defaultValue) ? schema : null;
}

/** Copies the definition's current-version workspace values that may travel, stamped `share`.
 * O(values × value size). */
async function copyWorkspaceValues(required: { source: Kernel; target: Kernel; definition: Row; schema: SettingValueSchema }, _options: Record<string, never> = {}): Promise<void> {
  const { definition } = required;
  const rows = await required.source.run(db => db.selectFrom("setting_values_workspace").selectAll().where("setting_id", "=", definition.setting_id).where("def_version", "=", definition.version).execute());
  for (const row of rows) {
    const portable = portableValue({ row, schema: required.schema });
    if (portable) await required.target.run(db => db.insertInto("setting_values_workspace").values({ ...row, value_json: JSON.stringify(portable.value), updated_by: "share" }).execute());
  }
}

/** The value one workspace row carries (null when cleared), or null when the row must be omitted:
 * a secret-shaped stored value, or a set value its schema rejects. O(value size).
 * @throws SyntaxError when a set value is not JSON. */
function portableValue(required: { row: Row; schema: SettingValueSchema }, _options: Record<string, never> = {}): { value: JsonValue } | null {
  const { row } = required;
  const value = row.state === "cleared" ? null : JSON.parse(String(row.value_json)) as JsonValue;
  if (hasSecretShape({ text: String(row.value_json) }) || row.state !== "cleared" && !validateValueAgainstSchema(required.schema, value)) return null;
  return { value };
}

/**
 * Build a fresh database from a consistent snapshot through trusted bootstrap only. Source SQL,
 * triggers, search projections and migration rows are never copied. Queries and inserts use the
 * existing storage kernel; source FK order is replaced by the policy's parent-before-child order.
 * Source staging is private/read-only and always removed; the live database is never touched.
 * @throws SiteShareRefusal for caps, unknown populated tables, or unsupported schema.
 * @complexity O(snapshot + portable rows) time/space, bounded to the v1 expanded cap.
 */
export async function sanitizeShareDatabase(required: { snapshot: Buffer }, optional: { signal?: AbortSignal; statfs?: StagingSpacePort } = {}): Promise<ShareDatabaseProjection> {
  optional.signal?.throwIfAborted();
  if (required.snapshot.length > SHARE_LIMITS.maxExpandedBytes) throw new SiteShareRefusal({ code: "LIMIT_EXCEEDED", message: "Database exceeds the 300 MiB cap." });
  const staging = await mkdtemp(path.join(tmpdir(), "tovu-share-projection-"));
  let source: Kernel | undefined;
  let fresh: ReturnType<typeof openContentDb> | undefined;
  try {
    const filePath = path.join(staging, "snapshot.db");
    const space = await (optional.statfs ?? statfs)(staging);
    if (space.bavail * space.bsize < required.snapshot.length + 16 * 1024 * 1024) throw new SiteShareRefusal({ code: "INSUFFICIENT_STORAGE", message: "Insufficient private staging space for this database share." });
    await writeFile(filePath, required.snapshot, { flag: "wx", mode: 0o600 });
    source = openSqliteFileKernel<Tables>(filePath, { readOnly: true });
    fresh = openContentDb({ filePath: ":memory:" });
    const target = sqliteKernel<Tables>(fresh);
    const from = source;
    const present = new Set(await listTables(from));
    const plugins = await prepareSharePluginTables({ target, present });
    await refuseUnknownTables(source, new Set([...await listTables(target), ...plugins.private]));
    await target.transaction(async () => {
      for (const table of SHARE_TABLES) {
        if (!present.has(table)) throw new SiteShareRefusal({ code: "UNSUPPORTED_SCHEMA", message: `Share requires current table '${table}'. Update this site first.` });
        await copyTable({ source: from, target, table }, { signal: optional.signal });
      }
      for (const table of plugins.portable) await copyTable({ source: from, target, table }, { signal: optional.signal, portablePlugin: true });
      await copySettings(from, target);
    });
    await backfillPostSearchIndex(fresh);
    const documents = await documentReferences({ target });
    const media = [
      ...await target.run(db => db.selectFrom("asset_blobs").select(["storage_key as storageKey", "sha256"]).execute()) as { storageKey: string; sha256: string }[],
      ...await target.run(db => db.selectFrom("asset_renditions").select("storage_key as storageKey").execute()) as { storageKey: string }[],
    ];
    // Older shares included Trash/orphan sidecars. v2 emits only retained owners, so
    // arbitrary unreferenced archive media must refuse rather than be pruned on import.
    await requireProjectedSecretFree({ target });
    const bytes = sqliteClientOf(fresh).serialize();
    requireShareSecretFree({ path: "database/content.db", bytes });
    return { bytes, media, documents, archiveMedia: await archiveMediaSources({ target }) };
  } finally {
    await source?.close();
    if (fresh) closeSqliteConnection(fresh);
    await rm(staging, { recursive: true, force: true });
  }
}

/** Snapshot metadata for the archive selector. Three bulk reads, then indexed lookups per item. */
async function archiveMediaSources({ target }: { target: Kernel }): Promise<ArchiveMediaSource[]> {
  const rows = await target.run(db => db.selectFrom("media").selectAll().execute());
  const blobs = await target.run(db => db.selectFrom("asset_blobs").selectAll().execute());
  const renditions = await target.run(db => db.selectFrom("asset_renditions").selectAll().where("transform_name", "=", "public").execute());
  const transforms = await target.run(db => db.selectFrom("transform_registry").selectAll().where("name", "=", "public").orderBy("version", "asc").execute());
  const byHash = new Map(blobs.map(row => [ownerKey(row.workspace_id, row.sha256), row]));
  const byKey = new Map(blobs.map(row => [String(row.storage_key), row]));
  const definitions = new Map(transforms.map(row => [String(row.workspace_id), row]));
  const publics = new Map(renditions.map(row => [ownerKey(row.workspace_id, [row.asset_id, row.version]), row]));
  return rows.map(row => {
    const blob = byHash.get(ownerKey(row.workspace_id, row.source_sha256));
    if (!blob) throw new SiteShareRefusal({ code: "MISSING_MEDIA", message: `Media '${row.id}' has no source blob.` });
    const definition = definitions.get(String(row.workspace_id));
    const rendition = definition && publics.get(ownerKey(row.workspace_id, [row.id, definition.version]));
    return { id: String(row.id), workspaceId: String(row.workspace_id), slug: String(row.slug ?? row.id), kind: String(row.kind),
      originalFilename: row.original_filename === null ? null : String(row.original_filename), storageKey: String(blob.storage_key), sha256: String(blob.sha256), documentOwned: Boolean(blob.document_owned),
      ...(definition ? { public: { version: Number(definition.version), params: JSON.parse(String(definition.params_json)),
        ...(rendition ? { storageKey: String(rendition.storage_key), sha256: renditionHash({ key: String(rendition.storage_key), blob: byKey.get(String(rendition.storage_key)) }) } : {}) } } : {}) };
  });
}

/** Rewrites only the fresh share projection. No live DB or blob store is changed.
 * Rebuild sidecars so original and latest public point at the same copy; other renditions regenerate.
 * @throws SiteShareRefusal if copies do not cover the snapshot, or secret scanning refuses.
 * @complexity O(media + copies) indexed reads/writes, bounded by the share snapshot cap.
 */
export async function rewriteArchiveMedia(required: { bytes: Buffer; copies: readonly ArchiveMediaCopy[] }, optional: { signal?: AbortSignal } = {}): Promise<Buffer> {
  const staging = await mkdtemp(path.join(tmpdir(), "tovu-archive-media-"));
  let target: Kernel | undefined;
  try {
    const file = path.join(staging, "content.db");
    await writeFile(file, required.bytes, { mode: 0o600, flag: "wx" });
    target = openSqliteFileKernel<Tables>(file);
    await rewriteMediaRows({ target, copies: required.copies }, optional);
    await requireProjectedSecretFree({ target });
    const bytes = sqliteConnectionOf(target)!.serialize();
    requireShareSecretFree({ path: "content.db", bytes });
    return bytes;
  } finally { await target?.close(); await rm(staging, { recursive: true, force: true }); }
}

async function rewriteMediaRows(required: { target: Kernel; copies: readonly ArchiveMediaCopy[] }, optional: { signal?: AbortSignal }): Promise<void> {
  const { target } = required;
  const media = await target.run(db => db.selectFrom("media").selectAll().execute());
  const byId = new Map(media.map(row => [ownerKey(row.workspace_id, row.id), row]));
  const blobs = await target.run(db => db.selectFrom("asset_blobs").selectAll().execute());
  const byHash = new Map(blobs.map(row => [ownerKey(row.workspace_id, row.sha256), row]));
  if (byId.size !== required.copies.length) throw new SiteShareRefusal({ code: "INVALID_MEDIA", message: "Archive media does not cover the snapshot." });
  await target.transaction(async () => {
    await target.run(db => db.deleteFrom("asset_renditions").execute());
    await target.run(db => db.deleteFrom("asset_blobs").execute());
    for (const copy of required.copies) {
      optional.signal?.throwIfAborted();
      const row = byId.get(ownerKey(copy.workspaceId, copy.id));
      if (!row) throw new SiteShareRefusal({ code: "INVALID_MEDIA", message: "Unknown archive media item." });
      await target.run(db => db.updateTable("media").set({ source_sha256: copy.sha256 }).where("id", "=", copy.id).where("workspace_id", "=", copy.workspaceId).execute());
      await target.run(db => db.insertInto("asset_blobs").values(archiveBlobRow({ copy, media: row, existing: byHash.get(ownerKey(copy.workspaceId, copy.sha256)) }))
        .onConflict(oc => oc.columns(["workspace_id", "sha256"]).doUpdateSet({ document_owned: sql`max(document_owned, excluded.document_owned)` })).execute());
      for (const rendition of [{ name: "original", version: 1 }, ...(copy.publicVersion === undefined ? [] : [{ name: "public", version: copy.publicVersion }])]) {
        await target.run(db => db.insertInto("asset_renditions").values({ id: copy.id + ":" + rendition.name, workspace_id: copy.workspaceId, asset_id: copy.id, transform_name: rendition.name, version: rendition.version, storage_key: copy.storageKey, created_at: row.created_at }).execute());
      }
    }
  });
}

/** Preserve unchanged blob metadata and sticky document privacy while replacing its path/hash. */
function archiveBlobRow(required: { copy: ArchiveMediaCopy; media: Row; existing?: Row | undefined }): Row {
  const { copy, media } = required;
  const original: Row = required.existing ?? { id: copy.workspaceId + ":" + copy.sha256, created_by_principal: "share", created_at: media.created_at, status: "active", tombstoned_at: null };
  const documentOwned = Boolean(copy.documentOwned || media.kind === "document" || original.document_owned);
  const contentType = copy.contentType === "application/octet-stream" ? original.content_type ?? copy.contentType : copy.contentType;
  return { ...original, workspace_id: copy.workspaceId, sha256: copy.sha256, storage_key: copy.storageKey, content_type: contentType, document_owned: documentOwned ? 1 : 0 };
}

function renditionHash(required: { key: string; blob: Row | undefined }): string | undefined {
  if (typeof required.blob?.sha256 === "string") return required.blob.sha256;
  return /[a-f0-9]{64}$/.exec(required.key)?.[0];
}

import { sql } from "kysely";
import { SqlSecretsVaultRepo, type SecretsVaultDatabase } from "@jini-ai/db/secrets-vault";
import { buildVaultAad, type VaultQuery, type VaultRecord } from "@jini-ai/platform/secrets/credential-sets";
import type { KeyringPort, SealedSecret, SecretSealerPort, SiteKeyHandle } from "@jini-ai/platform/secrets";
import type { ContentKernel } from "./content-kernel.js";
import type { StorageKernel } from "./kernel/port.js";
import { listColumns, listTables } from "./kernel/dialect.js";
import { deviceAad } from "./repos/oauth-pending-store.js";

/** @file Host inventory over Jini's vault plus catalog coverage for unknown sealed columns.
 * Jini owns vault persistence and AAD; the host scan adds unknown plugin columns and the retained
 * device-code store (`oauth_device_authorizations`).
 * Catalog discovery must remain: a plugin's unregistered sealed table must never disappear from
 * the count guarding a key replacement. Restore copies are artifacts, not live credentials.
 * Only safe identity and enum reasons leave this module; payloads, metadata, hints and errors do not.
 */
export type OpensUnderActiveKey = true | false | "unknown";
export type SealedCredentialUnknownReason = "no-descriptor" |
  "incomplete-sealed-row" | "unrecognized-aad-version" | "unsupported-alg" | "no-site-key" | "active-key-unavailable";
export interface SealedCredentialEntry {
  table: string; column: string; workspaceId: string | null; rowId: string | null;
  label: string; sealedKeyId: string | null; opensUnderActiveKey: OpensUnderActiveKey;
  unknownReason: SealedCredentialUnknownReason | null;
}
export interface SealedColumnSummary {
  table: string; column: string; coverage: "classified" | "no-descriptor"; sealedRows: number;
}
export interface SealedCredentialInventory {
  activeKeyId: string | null; columns: readonly SealedColumnSummary[]; entries: readonly SealedCredentialEntry[];
  /** Configurations without envelopes survive discard and do not count as sealed values. */
  metadataOnly: readonly Pick<SealedCredentialEntry, "workspaceId" | "rowId" | "label">[];
  /** Envelopes still awaiting the host boot/recovery codec. */
  legacySealed: number;
  totals: { sealed: number; opens: number; doesNotOpen: number; unknown: number };
}
export interface VaultCredentialKeyDeps {
  kernel: ContentKernel; sealer: Pick<SecretSealerPort, "open">;
  /** The host's migration codec chooses precisely one legacy AAD; ordinary rows use Jini's AAD. */
  aadFor?: (input: { record: VaultRecord }) => string | undefined;
}
export interface SealedCredentialInventoryDeps extends VaultCredentialKeyDeps {
  sealer: Pick<SecretSealerPort, "seal" | "open">; keyring: Pick<KeyringPort, "activeKey">;
  /** Prevent a file-generating keyring from minting a key merely to inspect locked data. */
  hasSiteKeySource: () => boolean;
}
export interface SealedCredentialInventoryOptions { maxEntries?: number }
export class SealedCredentialInventoryLimitError extends Error {
  readonly sealedRows: number; readonly maxEntries: number;
  constructor(input: { sealedRows: number; maxEntries: number }) {
    super("Sealed credential inventory exceeds its limit; refusing an understated count");
    this.name = "SealedCredentialInventoryLimitError";
    this.sealedRows = input.sealedRows; this.maxEntries = input.maxEntries;
  }
}
export interface DiscoveredSealedColumn {
  table: string; column: string; tableColumns: ReadonlySet<string>; notNull: boolean;
}
/** Internal snapshot. Never serialize it: envelopes and vault metadata are private. */
export interface VaultCredentialValue {
  ref: DiscoveredSealedColumn; sealed: SealedSecret | null; ciphertext: string;
  entry: Pick<SealedCredentialEntry, "table" | "column" | "workspaceId" | "rowId" | "label" | "sealedKeyId">;
  record?: VaultRecord; device?: { workspaceId: string; serverId: string };
  guard?: Record<string, unknown>;
  aad: string | undefined; reason: SealedCredentialUnknownReason | null;
}
export interface VaultCredentialSnapshot {
  values: VaultCredentialValue[]; metadataOnly: SealedCredentialInventory["metadataOnly"]; columns: SealedColumnSummary[];
}

/** Catalog suffix of every sealed envelope column; shared with the key-minting gate's scan. */
export const SEALED_COLUMN_SUFFIX = "sealed_ciphertext";
/** Quad siblings for a catalog name, quoted verbatim by callers. */
export function siblingColumns(column: string): { keyId: string; nonce: string; alg: string } {
  const prefix = column.slice(0, -SEALED_COLUMN_SUFFIX.length);
  return { keyId: `${prefix}sealed_key_id`, nonce: `${prefix}sealed_nonce`, alg: `${prefix}sealed_alg` };
}
/** Shared restore-artifact classification for inventory and the key-minting gate. */
export function isVaultRestoreArtifact({ table }: { table: string }): boolean {
  return table.startsWith("_vault_backup_");
}
/** Catalog truth, in code-unit order. O(t) catalog reads for t live tables. */
export async function discoverSealedColumns(kernel: ContentKernel): Promise<DiscoveredSealedColumn[]> {
  const refs: DiscoveredSealedColumn[] = [];
  for (const table of (await listTables(kernel)).sort()) {
    if (isVaultRestoreArtifact({ table })) continue;
    const columns = await listColumns(kernel, table);
    const tableColumns = new Set(columns.map(column => column.name));
    for (const column of columns) {
      if (column.name.endsWith(SEALED_COLUMN_SUFFIX)) refs.push({ table, column: column.name, tableColumns, notNull: column.notNull });
    }
  }
  return refs;
}
interface VaultScope { workspace_id: string; kind: VaultQuery["kind"]; owner_key: string; principal_id: string | null }
/** Use the owning Jini adapter's row decoding, one read per kind/owner/principal group, never per row. */
async function readVault({ deps, ref }: { deps: VaultCredentialKeyDeps; ref: DiscoveredSealedColumn }): Promise<{
  values: VaultCredentialValue[]; metadataOnly: SealedCredentialInventory["metadataOnly"];
}> {
  const repo = new SqlSecretsVaultRepo({ kernel: deps.kernel as unknown as StorageKernel<SecretsVaultDatabase> });
  const scopes = await deps.kernel.query<VaultScope>(sql`
    SELECT DISTINCT workspace_id,kind,owner_key,principal_id FROM secrets_vault ORDER BY workspace_id,kind,owner_key`);
  const values: VaultCredentialValue[] = [];
  const metadataOnly: Array<SealedCredentialInventory["metadataOnly"][number]> = [];
  for (const scope of scopes) {
    for (const record of await repo.list({ workspaceId: scope.workspace_id, kind: scope.kind, ownerKey: scope.owner_key, principalId: scope.principal_id })) {
      // The kind and ID are safe handles. Never trust arbitrary metadata or a legacy label here.
      const identity = { workspaceId: record.workspaceId, rowId: record.id, label: `${record.kind} (${record.id})` };
      if (!record.sealed) { metadataOnly.push(identity); continue; }
      values.push({ ref, record, sealed: record.sealed, ciphertext: record.sealed.ciphertext, ...selectVaultAad({ deps, record }),
        entry: { ...identity, table: ref.table, column: ref.column, sealedKeyId: record.sealed.keyId } });
    }
  }
  return { values, metadataOnly };
}
/**
 * Exactly one AAD per sealed vault record: the host codec's choice when it has one, else Jini's.
 * A legacy AAD with no codec, or any throw while choosing, is an unknown lineage, never an error.
 *
 * @complexity O(1).
 */
function selectVaultAad({ deps, record }: { deps: VaultCredentialKeyDeps; record: VaultRecord }): Pick<VaultCredentialValue, "aad" | "reason"> {
  try {
    if (deps.aadFor) return { aad: deps.aadFor({ record }), reason: null };
    if (record.meta.legacyAad !== undefined) return { aad: undefined, reason: "unrecognized-aad-version" };
    return { aad: buildVaultAad(record), reason: null };
  } catch { return { aad: undefined, reason: "unrecognized-aad-version" }; }
}
/** Device codes still have a live owner. Other catalog columns remain visible but unclassified. */
async function readOther({ deps, ref }: { deps: VaultCredentialKeyDeps; ref: DiscoveredSealedColumn }): Promise<VaultCredentialValue[]> {
  const siblings = siblingColumns(ref.column);
  const optional = (name: string) => ref.tableColumns.has(name) ? sql.id(name) : sql`NULL`;
  const device = isDeviceCodeColumn({ ref });
  const rows = await deps.kernel.query<Record<string, unknown>>(sql`SELECT ${sql.id(ref.column)} AS ciphertext,
    ${optional(siblings.keyId)} AS key_id, ${optional(siblings.nonce)} AS nonce, ${optional(siblings.alg)} AS alg,
    ${device ? sql.id("workspace_id") : sql`NULL`} AS workspace_id,
    ${device ? sql.id("server_id") : sql`NULL`} AS server_id FROM ${sql.id(ref.table)} WHERE ${sql.id(ref.column)} IS NOT NULL`);
  return rows.map(row => otherValue({ ref, siblings, row, identity: device ? deviceIdentity({ row }) : undefined }));
}
/** The retained device-code store's own envelope column, with the identity columns its AAD needs. */
function isDeviceCodeColumn({ ref }: { ref: DiscoveredSealedColumn }): boolean {
  return ref.table === "oauth_device_authorizations" && ref.column === "sealed_ciphertext" &&
    ref.tableColumns.has("workspace_id") && ref.tableColumns.has("server_id");
}
/** A device row's owner, only when both identity values are strings. */
function deviceIdentity({ row }: { row: Record<string, unknown> }): { workspaceId: string; serverId: string } | undefined {
  return typeof row.workspace_id === "string" && typeof row.server_id === "string"
    ? { workspaceId: row.workspace_id, serverId: row.server_id } : undefined;
}
/** The quad as an envelope only when all four values are strings; anything partial is no envelope. */
function sealedQuad({ row }: { row: Record<string, unknown> }): SealedSecret | null {
  return [row.key_id, row.ciphertext, row.nonce, row.alg].every(value => typeof value === "string")
    ? { keyId: row.key_id as string, ciphertext: row.ciphertext as string, nonce: row.nonce as string, alg: row.alg as string } : null;
}
/**
 * One device-code or unknown-column row as a snapshot value. The guard keeps only the quad columns
 * the table really has; only a device identity selects an AAD and a classified verdict.
 *
 * @complexity O(1).
 */
function otherValue({ ref, siblings, row, identity }: {
  ref: DiscoveredSealedColumn; siblings: ReturnType<typeof siblingColumns>; row: Record<string, unknown>;
  identity: { workspaceId: string; serverId: string } | undefined;
}): VaultCredentialValue {
  const sealed = sealedQuad({ row });
  return { ref, sealed, ciphertext: String(row.ciphertext),
    guard: Object.fromEntries([[ref.column, row.ciphertext], [siblings.keyId, row.key_id], [siblings.nonce, row.nonce], [siblings.alg, row.alg]]
      .filter(([column]) => ref.tableColumns.has(column as string))), ...(identity ? { device: identity } : {}),
    aad: identity ? deviceAad(identity.workspaceId, identity.serverId) : undefined,
    reason: !sealed ? "incomplete-sealed-row" : identity ? null : "no-descriptor",
    entry: otherEntry({ ref, row, identity }) };
}
/** The safe identity of a device-code or unknown-column row: ids and a fixed label, never row payloads. */
function otherEntry({ ref, row, identity }: {
  ref: DiscoveredSealedColumn; row: Record<string, unknown>; identity: { workspaceId: string; serverId: string } | undefined;
}): VaultCredentialValue["entry"] {
  return { table: ref.table, column: ref.column, workspaceId: identity?.workspaceId ?? null,
    rowId: identity?.serverId ?? null, label: identity ? `Pending device sign-in (${identity.serverId})` : `Unclassified ${ref.table}.${ref.column}`,
    sealedKeyId: typeof row.key_id === "string" ? row.key_id : null };
}
/** Non-null envelope values across `refs`, one COUNT per column; a missing count row counts as zero. O(columns) reads. */
async function countSealedRows({ deps, refs }: { deps: VaultCredentialKeyDeps; refs: readonly DiscoveredSealedColumn[] }): Promise<number> {
  let count = 0;
  for (const ref of refs) {
    const [row] = await deps.kernel.query<{ count: number | string }>(sql`SELECT COUNT(*) AS count FROM ${sql.id(ref.table)} WHERE ${sql.id(ref.column)} IS NOT NULL`);
    count += Number(row?.count ?? 0);
  }
  return count;
}
/** One consistent snapshot; count first and refuse truncation. O(catalog + groups + rows) reads/storage. */
export async function snapshotVaultCredentials(deps: VaultCredentialKeyDeps,
  { maxEntries = 10_000 }: SealedCredentialInventoryOptions = {},
): Promise<VaultCredentialSnapshot> {
  if (!Number.isSafeInteger(maxEntries) || maxEntries < 1) throw new RangeError("maxEntries must be a positive integer");
  return deps.kernel.transaction(async () => {
    const refs = await discoverSealedColumns(deps.kernel);
    const count = await countSealedRows({ deps, refs });
    if (count > maxEntries) throw new SealedCredentialInventoryLimitError({ sealedRows: count, maxEntries });
    const snapshot: VaultCredentialSnapshot = { values: [], metadataOnly: [], columns: [] };
    for (const ref of refs) {
      const read = ref.table === "secrets_vault" && ref.column === "sealed_ciphertext"
        ? await readVault({ deps, ref }) : { values: await readOther({ deps, ref }), metadataOnly: [] };
      snapshot.values.push(...read.values);
      snapshot.metadataOnly = [...snapshot.metadataOnly, ...read.metadataOnly];
      snapshot.columns.push({ table: ref.table, column: ref.column,
        coverage: ref.table === "secrets_vault" || ref.table === "oauth_device_authorizations" ? "classified" : "no-descriptor", sealedRows: read.values.length });
    }
    return snapshot;
  });
}
/** Exactly one selected AAD; failures are safe verdicts, never crypto error strings. */
export async function opensVaultCredential({ value, sealer }: { value: VaultCredentialValue; sealer: VaultCredentialKeyDeps["sealer"] }): Promise<boolean> {
  if (value.reason || !value.sealed) return false;
  try { await sealer.open({ sealed: value.sealed }, { aad: value.aad }); return true; } catch { return false; }
}
/** Probe before classification and after failed opens: a broken active key is unknown, not dead data. */
async function probe({ deps, key }: { deps: SealedCredentialInventoryDeps; key: SiteKeyHandle }): Promise<string | null> {
  try {
    const plaintext = "sealed-credential-inventory-probe";
    const aad = "sealed-credential-inventory-probe:v1";
    const sealed = await deps.sealer.seal({ plaintext, key, aad });
    return await deps.sealer.open({ sealed }, { aad }) === plaintext ? sealed.alg : null;
  } catch { return null; }
}
/** Whether a key source exists, the active key when it can be read, and the algorithm its probe proved. */
interface ActiveKeyCheck { present: boolean; key: SiteKeyHandle | null; alg: string | null }
/**
 * Reads the active key once, only when a source exists, and probes it. Never mints a key and never
 * surfaces a keyring or crypto error: an unreadable key is a null key.
 *
 * @complexity O(1) keyring reads and one probe.
 */
async function checkActiveKey({ deps }: { deps: SealedCredentialInventoryDeps }): Promise<ActiveKeyCheck> {
  const present = deps.hasSiteKeySource();
  let key: SiteKeyHandle | null = null;
  if (present) { try { key = await deps.keyring.activeKey({}); } catch { /* Safe unknown verdict below. */ } }
  const alg = key ? await probe({ deps, key }) : null;
  return { present, key, alg };
}
/**
 * The first reason, in precedence order, that a row cannot be opened under the active key, or the
 * key to open it with: snapshot reason, no key source, unusable key, then algorithm mismatch.
 *
 * @complexity O(1).
 */
function readyKeyFor({ value, check }: { value: VaultCredentialValue; check: ActiveKeyCheck }):
  { key: SiteKeyHandle } | { reason: SealedCredentialUnknownReason } {
  if (value.reason) return { reason: value.reason };
  if (!check.present) return { reason: "no-site-key" };
  if (!check.key || !check.alg) return { reason: "active-key-unavailable" };
  if (value.sealed?.alg !== check.alg) return { reason: "unsupported-alg" };
  return { key: check.key };
}
/**
 * One row's verdict. A failed open re-probes the key, so a key that broke mid-scan reports unknown
 * rather than "does not open".
 *
 * @complexity O(1) opens plus at most one probe.
 */
async function verdictFor({ deps, value, check }: { deps: SealedCredentialInventoryDeps; value: VaultCredentialValue; check: ActiveKeyCheck }):
  Promise<Pick<SealedCredentialEntry, "opensUnderActiveKey" | "unknownReason">> {
  const ready = readyKeyFor({ value, check });
  if ("reason" in ready) return { opensUnderActiveKey: "unknown", unknownReason: ready.reason };
  const opens = await opensVaultCredential({ value, sealer: deps.sealer });
  if (!opens && await probe({ deps, key: ready.key }) === null) return { opensUnderActiveKey: "unknown", unknownReason: "active-key-unavailable" };
  return { opensUnderActiveKey: opens, unknownReason: null };
}
/** Per-verdict totals over the entries. O(n). */
function tallyVerdicts({ entries }: { entries: readonly SealedCredentialEntry[] }): SealedCredentialInventory["totals"] {
  return { sealed: entries.length, opens: entries.filter(row => row.opensUnderActiveKey === true).length,
    doesNotOpen: entries.filter(row => row.opensUnderActiveKey === false).length,
    unknown: entries.filter(row => row.opensUnderActiveKey === "unknown").length };
}
/** Read-only safe inventory; no key derivation without an existing source, no plaintext output. */
export async function inventoryVaultCredentials(deps: SealedCredentialInventoryDeps,
  options: SealedCredentialInventoryOptions = {},
): Promise<SealedCredentialInventory> {
  const snapshot = await snapshotVaultCredentials(deps, options);
  const check = await checkActiveKey({ deps });
  const entries: SealedCredentialEntry[] = [];
  for (const value of snapshot.values) entries.push({ ...value.entry, ...await verdictFor({ deps, value, check }) });
  return { activeKeyId: check.key?.keyId ?? null, columns: snapshot.columns, entries, metadataOnly: snapshot.metadataOnly,
    legacySealed: snapshot.values.filter(value => value.record?.meta.legacyAad !== undefined).length,
    totals: tallyVerdicts({ entries }) };
}

import { sql } from "kysely";
import { SqlSecretsVaultRepo, type SecretsVaultDatabase } from "@jini-ai/db/secrets-vault";
import type { SecretSealerPort, SiteKeyHandle } from "@jini-ai/platform/secrets";
import type { VaultRecord } from "@jini-ai/platform/secrets/credential-sets";
import type { StorageKernel } from "./kernel/port.js";
import { opensVaultCredential, snapshotVaultCredentials, siblingColumns,
  type VaultCredentialKeyDeps, type VaultCredentialValue } from "./vault-credential-inventory.js";

/** @file Last-resort host recovery. Jini retains CAS, default promotion and envelope persistence.
 * Callers take a restore point. Unlike restore artifacts, unknown live columns remain in coverage.
 * The retained device store has no revision; it and unknown columns keep their full-envelope guard.
 */
export type SealedCredentialKeyDeps = VaultCredentialKeyDeps;
export interface ResealCredentialsDeps extends VaultCredentialKeyDeps {
  sealer: Pick<SecretSealerPort, "seal" | "open">; key: SiteKeyHandle; previous: Pick<SecretSealerPort, "open">;
  /** Host codec normalizes legacy rows or rotates ordinary rows through Jini, with CAS. */
  resealRecord: (input: { record: VaultRecord; previous: Pick<SecretSealerPort, "open"> }) => Promise<void>;
}
const OPTIONAL_ENVELOPES = new Set(["site-assistant", "personal-execution", "media-provider", "publish-peer"]);

/** Lock workspaces in a deterministic order, matching every Jini vault writer and boot normalization. */
async function lockWorkspaces({ deps, values }: { deps: SealedCredentialKeyDeps; values: VaultCredentialValue[] }): Promise<void> {
  const workspaces = values.flatMap(value => value.record ? [value.record.workspaceId] : []);
  for (const workspaceId of [...new Set(workspaces)].sort()) await deps.kernel.lockKey(`secrets_vault:${workspaceId}`);
}
/** Recheck all revisions BEFORE mutations: default promotion may legitimately advance later rows. */
async function currentValues({ deps, values }: { deps: SealedCredentialKeyDeps; values: VaultCredentialValue[] }): Promise<VaultCredentialValue[]> {
  const repo = new SqlSecretsVaultRepo({ kernel: deps.kernel as unknown as StorageKernel<SecretsVaultDatabase> });
  const current: VaultCredentialValue[] = [];
  for (const value of values) {
    if (!value.record) { current.push(value); continue; }
    const row = await repo.find(value.record);
    if (row?.revision === value.record.revision) current.push(value);
  }
  return current;
}
/** Unlink first in the same transaction, then delete the vault row (FK is deliberately RESTRICT).
 * OAuth refresh cannot resurrect the discarded session; a fresh connect is required.
 */
async function unlinkMcp({ deps, record }: { deps: SealedCredentialKeyDeps; record: VaultRecord }): Promise<void> {
  if (record.kind === "mcp-env") await deps.kernel.execute(sql`UPDATE external_mcp_servers SET env_secret_id=NULL
    WHERE workspace_id=${record.workspaceId} AND env_secret_id=${record.id}`);
  if (record.kind === "mcp-auth") await deps.kernel.execute(sql`UPDATE external_mcp_servers SET oauth_secret_id=NULL,
    oauth_status='needs_reauth', oauth_expires_at=NULL, oauth_refresh_lease_until=NULL
    WHERE workspace_id=${record.workspaceId} AND oauth_secret_id=${record.id}`);
}
/** Remove only a current record. Settings survive optional clears; hints and legacy markers do not. */
async function discardVaultValue({ deps, value }: { deps: SealedCredentialKeyDeps; value: VaultCredentialValue }): Promise<number> {
  if (!value.record) return mutateOther({ deps, value });
  const repo = new SqlSecretsVaultRepo({ kernel: deps.kernel as unknown as StorageKernel<SecretsVaultDatabase> });
  const record = await repo.find(value.record);
  if (!record) return 0;
  if (OPTIONAL_ENVELOPES.has(record.kind)) {
    const { legacyAad: _legacy, normalization: _flag, ...meta } = record.meta;
    await repo.put({ expectedRevision: record.revision, record: { ...record, meta, sealed: null,
      last4: null, tokenLength: null, revision: record.revision + 1 } });
    return 1;
  }
  await unlinkMcp({ deps, record });
  return Number(await repo.delete({ workspaceId: record.workspaceId, id: record.id, expectedRevision: record.revision }));
}
/** Old device/unknown stores lack revisions: compare the complete envelope, plus known device PK.
 * Use RETURNING to report actual changes; concurrent replacement is never counted as discarded.
 */
async function mutateOther({ deps, value, sealed }: {
  deps: SealedCredentialKeyDeps; value: VaultCredentialValue; sealed?: { keyId: string; ciphertext: string; nonce: string; alg: string };
}): Promise<number> {
  const { ref } = value;
  const siblings = siblingColumns(ref.column);
  const envelope = value.guard ?? { [ref.column]: value.ciphertext };
  const guards = Object.entries(envelope).map(([column, value]) => value === null
    ? sql`${sql.id(column)} IS NULL` : sql`${sql.id(column)}=${value}`);
  if (value.device) guards.push(sql`workspace_id=${value.device.workspaceId}`, sql`server_id=${value.device.serverId}`);
  const match = sql.join(guards, sql` AND `);
  if (!sealed && ref.notNull) {
    return (await deps.kernel.query(sql`DELETE FROM ${sql.id(ref.table)} WHERE ${match} RETURNING ${sql.id(ref.column)}`)).length;
  }
  const prefix = ref.column.slice(0, -"sealed_ciphertext".length);
  const companions = ["masked", "key_tail", "token_tail"].map(name => `${prefix}${name}`).filter(name => ref.tableColumns.has(name));
  const values = sealed ? { [ref.column]: sealed.ciphertext, [siblings.keyId]: sealed.keyId, [siblings.nonce]: sealed.nonce, [siblings.alg]: sealed.alg }
    : Object.fromEntries([ref.column, siblings.keyId, siblings.nonce, siblings.alg, ...companions].filter(name => ref.tableColumns.has(name)).map(name => [name, null]));
  const assignments = sql.join(Object.entries(values).map(([column, value]) => sql`${sql.id(column)}=${value}`));
  return (await deps.kernel.query(sql`UPDATE ${sql.id(ref.table)} SET ${assignments} WHERE ${match} RETURNING ${sql.id(ref.column)}`)).length;
}
/** Restore-point guarded discard; snapshot races survive and a later failure rolls back all writes. */
export async function discardVaultCredentialsNotOpening(deps: SealedCredentialKeyDeps, _options = {}): Promise<{ discarded: number; kept: number }> {
  const { values } = await snapshotVaultCredentials(deps);
  const unreadable: VaultCredentialValue[] = [];
  for (const value of values) if (!await opensVaultCredential({ value, sealer: deps.sealer })) unreadable.push(value);
  const discarded = await deps.kernel.transaction(async () => {
    await lockWorkspaces({ deps, values });
    const eligible = await currentValues({ deps, values: unreadable });
    let removed = 0;
    for (const value of eligible) removed += await discardVaultValue({ deps, value });
    return removed;
  });
  return { discarded, kept: values.length - discarded };
}
/** Normalize legacy envelopes under the recovered key even if they already open there. Ordinary
 * rows rotate through Jini only when the previous key opens them. Unknown AADs remain recoverable.
 */
export async function resealVaultCredentialsOpeningUnder(deps: ResealCredentialsDeps, _options = {}): Promise<{ resealed: number; unreadable: number }> {
  const { values } = await snapshotVaultCredentials(deps);
  const moves: Array<{ value: VaultCredentialValue; previous: ResealCredentialsDeps["previous"] }> = [];
  let unreadable = 0;
  for (const value of values) {
    const opens = await opensVaultCredential({ value, sealer: deps.sealer });
    if (opens && value.record?.meta.legacyAad === undefined) continue;
    if (opens) { moves.push({ value, previous: deps.sealer }); continue; }
    if (!await opensVaultCredential({ value, sealer: deps.previous })) { unreadable += 1; continue; }
    moves.push({ value, previous: deps.previous });
  }
  const resealed = await deps.kernel.transaction(async () => {
    await lockWorkspaces({ deps, values });
    const eligible = new Set(await currentValues({ deps, values: moves.map(move => move.value) }));
    let moved = 0;
    for (const { value, previous } of moves) {
      if (!eligible.has(value)) continue;
      if (value.record) { await deps.resealRecord({ record: value.record, previous }); moved += 1; continue; }
      if (!value.sealed) continue;
      const plaintext = await previous.open({ sealed: value.sealed }, { aad: value.aad });
      const sealed = await deps.sealer.seal({ plaintext, key: deps.key, aad: value.aad ?? "" });
      if (await deps.sealer.open({ sealed }, { aad: value.aad }) !== plaintext) throw new Error("Credential recovery verification failed");
      moved += await mutateOther({ deps, value, sealed });
    }
    return moved;
  });
  return { resealed, unreadable };
}

import fs from "node:fs";
import { randomUUID } from "node:crypto";
import { createNodeAtomicFilesystem, writeFileAtomic } from "@jini-ai/platform/fs";

/**
 * @file Dev restart-on-request channel (owner decision OD-S1): after `sites_switch_site`,
 * the server asks `development/scripts/dev.mjs` to restart its API child onto the new site.
 * The server only writes a supervisor request file; it never kills, signals or re-execs
 * itself. Automatic restart is limited to supervised dev processes because only that
 * supervisor can bring the server back.
 *
 * The port exists only when `dev.mjs` set {@link DEV_RESTART_REQUEST_FILE_ENV} (a per-supervisor
 * temp path). `tovu serve`, `npm start`, the desktop app and hosted boots never set it, so there
 * `devRestartPortFromEnv()` returns `null` and callers fall back to restart instructions.
 *
 * A file, not IPC: the API child is `npx -> tsx watch -> node`, so an IPC channel on the direct
 * child never reaches the real server, and the tool handler may run in the agent daemon (a further
 * process down), which inherits the env var but has no channel to `dev.mjs` at all.
 */

/** Set by `dev.mjs` on the API child (and inherited by the agent daemon it spawns). */
export const DEV_RESTART_REQUEST_FILE_ENV = "TOVU_DEV_RESTART_REQUEST_FILE";

/** How long a request waits before it is written, so the tool result and the assistant's short
 *  reply reach the chat before the server (and the daemon running the turn) goes down. */
export const DEV_RESTART_DELAY_MS = 3000;

export type DevRestartDecision = { accepted: true } | { accepted: false; reason: string };

export interface DevRestartPort {
  /** False when the launcher is pinned by an explicit shell site override. */
  canSwitchSite?: boolean;
  /** Legacy requests write after the chat delivery delay. Opt-in callers await the supervisor's
   * precheck; acceptance schedules a restart and does not claim a completed boot. */
  requestRestart(required: { reason: string }, optional?: { awaitAcceptance?: boolean }): void | Promise<DevRestartDecision | void>;
}

export interface DevRestartPortOptional {
  env?: Readonly<Record<string, string | undefined>>;
  writeFile?: (path: string, data: string) => void;
  readFile?: (path: string) => string | null;
  removeFile?: (path: string) => void;
  newId?: () => string;
  schedule?: (fn: () => void, ms: number) => void;
  delayMs?: number;
  log?: (message: string) => void;
}

/** Ask the supervisor's existing precheck before claiming acceptance. Each request has its own
 * reply file; a missing, malformed or unreadable acknowledgement fails closed without error text.
 * @returns Acceptance of a scheduled request, never proof that the new API has booted.
 * @complexity O(1) space and at most 150 small reply reads over fifteen seconds.
 */
function requestRestartAcceptance({ requestFile, reason }: { requestFile: string; reason: string },
  options: DevRestartPortOptional & Required<Pick<DevRestartPortOptional, "writeFile" | "schedule">>): Promise<DevRestartDecision> {
  const requestId = (options.newId ?? randomUUID)();
  const replyFile = `${requestFile}.${requestId}.result`;
  const read = options.readFile ?? (file => fs.existsSync(file) ? fs.readFileSync(file, "utf8") : null);
  const remove = options.removeFile ?? (file => fs.rmSync(file, { force: true }));
  return new Promise(resolve => {
    let remaining = 150;
    const poll = () => {
      try {
        const text = read(replyFile);
        if (text !== null) {
          const decision = JSON.parse(text);
          remove(replyFile);
          if (decision?.accepted === true) { resolve({ accepted: true }); return; }
          if (decision?.accepted === false && typeof decision.reason === "string") { resolve({ accepted: false, reason: decision.reason }); return; }
          throw new Error("Invalid supervisor acknowledgement");
        }
        if (--remaining === 0) { resolve({ accepted: false, reason: "The dev supervisor did not confirm the restart request." }); return; }
        options.schedule(poll, 100);
      } catch {
        resolve({ accepted: false, reason: "Could not confirm the restart with the dev supervisor." });
      }
    };
    try {
      options.writeFile(requestFile, JSON.stringify({ reason, requestId, requestedAt: new Date().toISOString(), pid: process.pid }));
      options.schedule(poll, 100);
    } catch {
      resolve({ accepted: false, reason: "Could not send the restart request to the dev supervisor." });
    }
  });
}

/**
 * @returns the port when this process runs under `dev.mjs`, otherwise `null`.
 * @complexity O(1); the write is one small file.
 */
export function devRestartPortFromEnv(optional: DevRestartPortOptional = {}): DevRestartPort | null {
  const env = optional.env ?? process.env;
  const requestFile = env[DEV_RESTART_REQUEST_FILE_ENV];
  if (!requestFile) return null;
  // The supervisor polls this file; publish whole JSON so it cannot consume a partial request.
  const writeFile = optional.writeFile ?? ((filePath: string, content: string) => writeFileAtomic({ filePath, content, fs: createNodeAtomicFilesystem({}) }));
  const schedule = optional.schedule ?? ((fn: () => void, ms: number) => void setTimeout(fn, ms).unref?.());
  const log = optional.log ?? ((message: string) => console.error(message));
  return {
    canSwitchSite: env.TOVU_DEV_SITE_PINNED !== "1",
    requestRestart({ reason }, { awaitAcceptance = false } = {}) {
      if (awaitAcceptance) return requestRestartAcceptance({ requestFile, reason }, { ...optional, writeFile, schedule });
      schedule(() => {
        try {
          writeFile(requestFile, JSON.stringify({ reason, requestedAt: new Date().toISOString(), pid: process.pid }));
        } catch (err) {
          log(`[dev-restart] could not ask the dev supervisor to restart: ${err instanceof Error ? err.message : String(err)}`);
        }
      }, optional.delayMs ?? DEV_RESTART_DELAY_MS);
    },
  };
}

/**
 * @file The ONE way an end-to-end harness lets a guarded outbound client reach a fixture server on
 * this machine, without weakening any production path.
 *
 * Every assistant-supplied URL (`web_fetch_page`, `media_import_from_url`) goes through a guarded
 * client that refuses loopback, and media import also refuses plain `http:`. A site-import journey
 * needs a whole fixture website, and an offline one can only live on `127.0.0.1`. So this module
 * opens exactly the origins a harness names, and nothing else:
 *
 * - **Exact origins only.** Scheme + loopback literal + explicit port (`http://127.0.0.1:41234`).
 *   Another port on the same loopback host, `localhost` (DNS-resolved, so rebindable), or any other
 *   private address is still refused.
 * - **Checked on every hop.** The guard calls the transport once per hop with the hop's own URL and
 *   pinned peer, so the check lives there: a redirect from an allowed origin to another loopback
 *   port, or a non-allowed `http:` hop, is refused at the hop that introduces it. Other private
 *   ranges never reach the transport at all (the guard's own address check still runs for them).
 * - **Injected, never read from env.** A composition root receives the list from a harness-only
 *   entrypoint (`development/e2e/support/site-import-api.ts`). `apps/website/src/index.ts` and
 *   `tovu serve` pass none, and with none {@link createTestOriginHttpClientFactory} returns
 *   `createDefaultHttpClient` itself, so production builds exactly the clients it built before.
 *
 * Architectural role: `platform/http` Tier-2 library, composition-root-facing, like `client.ts`.
 */
import { createNodeGuardedHttpPorts, EgressRefusedError, type DnsResolver, type EgressPolicy } from "@jini-ai/platform/http/guarded";
import { classifyAddress, createDefaultHttpClient, createHttpClient, type HttpClientOptions } from "./client.js";
import type { HttpClientPort, HttpTransportAdapter } from "./ports.js";

/** Same shape as `createDefaultHttpClient`, so a composition root can take either. */
export type EgressHttpClientFactory = (policy: EgressPolicy, options?: HttpClientOptions) => HttpClientPort;

const LOOPBACK_LITERALS = new Set(["127.0.0.1", "[::1]"]);
const REFUSED_HOP_MESSAGE = "egress to the requested host was refused by this site's outbound network policy";

/**
 * Validates and normalizes harness-supplied origins. Throws on anything that is not
 * `http(s)://<loopback literal>:<explicit port>` with no path, so a typo fails the harness loudly
 * instead of silently opening (or silently not opening) a host.
 * @returns The normalized `URL.origin` strings.
 * @complexity O(n) in the number of origins.
 */
export function parseTestOrigins({ origins }: { origins: readonly string[] }): ReadonlySet<string> {
  const parsed = new Set<string>();
  for (const raw of origins) {
    let url: URL;
    try { url = new URL(raw); } catch { throw new TypeError(`test origin '${raw}' is not a URL`); }
    const exact = (url.protocol === "http:" || url.protocol === "https:") && LOOPBACK_LITERALS.has(url.hostname)
      && url.port !== "" && raw.replace(/\/$/, "") === url.origin && !url.username && !url.password;
    if (!exact) throw new TypeError(`test origin '${raw}' must be http(s)://127.0.0.1:<port> or http(s)://[::1]:<port>, nothing more`);
    parsed.add(url.origin);
  }
  return parsed;
}

/**
 * Per-hop check over the policy the caller asked for: an allowed origin passes; any other hop must
 * satisfy that ORIGINAL policy's scheme list and private-address rule, which the widened policy
 * handed to the guard no longer enforces for loopback.
 */
function refuseUnlistedHop(
  { allowed, policy, transport }: { allowed: ReadonlySet<string>; policy: EgressPolicy; transport: HttpTransportAdapter },
): HttpTransportAdapter {
  return {
    requestPinned(request, peer) {
      const url = new URL(request.url);
      if (!allowed.has(url.origin)) {
        const host = url.hostname.replace(/^\[|\]$/g, "");
        const schemeRefused = !policy.allowedSchemes.includes(url.protocol.slice(0, -1));
        const addressRefused = policy.denyPrivateAddresses && !policy.devHostAllowlist.includes(host) && classifyAddress(peer.ip) !== "public";
        if (schemeRefused || addressRefused) {
          throw new EgressRefusedError({ message: `egress to '${url.origin}' rejected: not an allowed test origin` }, { callerSafeMessage: REFUSED_HOP_MESSAGE });
        }
      }
      return transport.requestPinned(request, peer);
    },
  };
}

/**
 * Builds the client factory a composition root uses for assistant-supplied URLs.
 * @param required.allowedOrigins - Harness-supplied exact loopback origins; empty in production.
 * @param optional.transport/dns - Test seams; default to the native pinned transport and resolver.
 * @returns `createDefaultHttpClient` when the list is empty; otherwise a factory whose clients may
 *   also reach exactly those origins (plain `http:` included) and nothing else the policy refuses.
 * @complexity O(1) per hop (set lookup + address classification).
 */
export function createTestOriginHttpClientFactory(
  { allowedOrigins }: { allowedOrigins: readonly string[] },
  { transport, dns }: { transport?: HttpTransportAdapter; dns?: DnsResolver } = {},
): EgressHttpClientFactory {
  if (allowedOrigins.length === 0) return createDefaultHttpClient;
  const allowed = parseTestOrigins({ origins: allowedOrigins });
  const origins = [...allowed].map((origin) => new URL(origin));
  return (policy, options = {}) => {
    const native = createNodeGuardedHttpPorts({});
    const widened: EgressPolicy = {
      ...policy,
      allowedSchemes: [...new Set([...policy.allowedSchemes, ...origins.map((url) => url.protocol.slice(0, -1))])],
      devHostAllowlist: [...new Set([...policy.devHostAllowlist, ...origins.map((url) => url.hostname.replace(/^\[|\]$/g, ""))])],
    };
    const base: HttpTransportAdapter = transport ?? { requestPinned: (request, peer) => native.transport.requestPinned({ request, peer }) };
    return createHttpClient(
      { transport: refuseUnlistedHop({ allowed, policy, transport: base }), policy: widened },
      { dns: dns ?? native.dns, clock: native.clock, ...options },
    );
  };
}

import type { HttpClientPort, HttpRequest, HttpResponse } from "@jini-ai/core/primitives";
import { assertSafeUserFacingUrl as assertJiniUserFacingUrl, createOAuthUrlGuard, defaultOAuthMessages, OAuthError as JiniOAuthError, type OAuthDiscoveryPolicy, type OAuthFetch, type OAuthHttpPorts, type OAuthUrlGuard } from "@jini-ai/oauth";
import { isBlockedExternalApiHostname, isLoopbackApiHost } from "@jini-ai/platform/net";

import { toLegacyEndpointError } from "./legacy-endpoint-error.js";

/**
 * @file Outbound-URL safety for `src/platform/oauth/`.
 *
 * Two different trust levels meet in this module and they get two different functions, because
 * collapsing them would apply the weaker rule to the more dangerous input:
 *
 * - {@link assertSafeProviderEndpoint} guards an endpoint an OPERATOR configured. That is a
 *   privileged, authenticated act, so the bar is "don't let a mis-typed or hostile provider
 *   descriptor turn Tovu into an SSRF proxy into its own network".
 * - {@link assertSafeUserFacingUrl} guards a URL the PROVIDER sent back — RFC 8628's
 *   `verification_uri` and `verification_uri_complete`. That string is rendered to an operator as
 *   something to click. It is attacker-controlled the moment a provider is compromised or
 *   impersonated, so `javascript:`, `data:` and friends must never survive this function.
 *
 * The block-list itself is not reimplemented. `@jini-ai/platform/net`
 * already owns loopback/RFC1918/link-local/CGNAT/multicast classification and is exercised by its
 * own parity tests; a second copy here would be a second thing to keep correct.
 *
 * The legacy testing/DB seam below checks URL syntax and literal host classification.
 * Jini consumers use createTovuOAuthHttpPorts instead: r01's guarded HTTP port validates and pins
 * DNS at connection time, closing the rebinding gap without hiding transport policy in OAuth.
 */

/** `http` is permitted ONLY for loopback, so an operator can develop against a local authorization
 *  server without the module offering a plaintext-token path to anywhere else.
 * @complexity O(1); no I/O. */
function createLegacySeamGuard(): OAuthUrlGuard {
  // The legacy testing/DB seam permits loopback explicitly; production gets the default-closed factory below.
  return createTovuOAuthGuard({}, { allowLoopbackHttp: true });
}

/**
 * Validates an operator-configured OAuth endpoint before Tovu sends anything to it.
 *
 * @param raw - The configured absolute URL.
 * @param label - Which endpoint, for the message (`"token endpoint"`, `"authorization endpoint"`).
 * @returns The parsed URL, so the caller uses the value that was validated rather than re-parsing.
 * @throws {OAuthError} `OAUTH_UNSAFE_ENDPOINT` on a non-absolute, non-https, or internal-address URL.
 * @complexity O(n) in the URL length.
 */
export function assertSafeProviderEndpoint(raw: string, label: string): URL {
  try {
    return createLegacySeamGuard().assertSafeUrl({ raw, label: "provider endpoint" });
  } catch (error) {
    throw toLegacyEndpointError({ error }, { prefix: `${label}: ` });
  }
}

/**
 * Validates a URL the PROVIDER supplied that will be shown to an operator as a link.
 *
 * Stricter than {@link assertSafeProviderEndpoint} in one way that matters: credentials embedded in
 * the URL (`https://user:pass@host/...`) are refused. A device-flow verification link is pasted or
 * clicked by a human, and an embedded userinfo component is both a phishing primitive and a way to
 * make a hostile host look like a trusted one in a truncated UI.
 *
 * @throws {OAuthError} `OAUTH_UNSAFE_ENDPOINT`.
 * @complexity O(n) in the URL length.
 */
export function assertSafeUserFacingUrl(raw: string): URL {
  try {
    return assertJiniUserFacingUrl({ raw, guard: createLegacySeamGuard() });
  } catch (error) {
    throw toLegacyEndpointError({ error });
  }
}

/** Tovu endpoint policy for Jini OAuth. The guard and pinned transport are separate ports because
 * a synchronous hostname check cannot prevent DNS rebinding at connection time.
 * Local plaintext OAuth is an explicit development choice, never a library fallback.
 * @complexity O(n) in URL length; no I/O.
 */
export function createTovuOAuthGuard(_required: Record<string, never>, optional: { allowLoopbackHttp?: boolean } = {}): OAuthUrlGuard {
  return createOAuthUrlGuard({
    assertAllowed({ url, label }) {
      const hostname = url.hostname.toLowerCase();
      if (!isLoopbackApiHost({ hostname }) && isBlockedExternalApiHostname({ hostname })) {
        throw new JiniOAuthError({ code: "OAUTH_UNSAFE_ENDPOINT",
          message: `${label}: provider endpoint resolves to an internal address, which is not allowed`,
          operatorAction: "Point this provider at a publicly reachable authorization server." });
      }
    },
  }, { allowLoopbackHttp: optional.allowLoopbackHttp === true });
}

/** Adapts r01's canonical guarded HTTP port to OAuth's fetch ABI. Redirects fail before credentials
 * cross origins; caller cancellation and the 15-second idle budget cover the complete body read.
 * A clipped body is refused rather than parsed as a complete token or metadata response.
 * The transport and response bounds rationale lives in Jini/packages/platform/src/http/guarded/.
 * @complexity O(n) in the bounded response body; one guarded outbound request.
 */
export function createTovuOAuthHttpPorts(
  { http }: { http: HttpClientPort },
  optional: { allowLoopbackHttp?: boolean } = {},
): OAuthHttpPorts {
  return {
    guard: createTovuOAuthGuard({}, optional),
    async fetchFn({ url }, init = {}) {
      const response = await http.send({ request: toGuardedOAuthRequest({ url, init }) }, { redirect: "error" });
      return toOAuthFetchResponse({ response });
    },
  };
}

/** Translates one OAuth fetch call into the guarded port's request, refusing shapes OAuth never emits.
 * @throws {TypeError} On a method other than GET/POST, a non-string body, or a `Request` URL.
 * @complexity O(h) in the header count; no I/O. */
function toGuardedOAuthRequest({ url, init }: { readonly url: Parameters<OAuthFetch>[0]["url"]; readonly init: RequestInit }): HttpRequest {
  // OAuth emits only GET/POST and string form/JSON bodies. Refuse unsupported requests so an
  // accidental new caller cannot silently drop a method or credential-bearing body.
  const method = init.method ?? "GET";
  if (method !== "GET" && method !== "POST") throw new TypeError("unsupported OAuth request method");
  const { body } = init;
  if (body !== undefined && typeof body !== "string") throw new TypeError("OAuth request body must be a string");
  if (url instanceof Request) throw new TypeError("OAuth URL must be an explicit URL");
  return {
    url: String(url), method, headers: Object.fromEntries(new Headers(init.headers).entries()),
    idleTimeoutMs: 15_000, maxResponseBytes: 64 * 1024,
    ...(body === undefined ? {} : { body }),
    ...(init.signal == null ? {} : { signal: init.signal }),
  };
}

/** Builds the fetch `Response` OAuth parses from a guarded-port response.
 * @throws {JiniOAuthError} `OAUTH_MALFORMED_RESPONSE` when the port clipped the body.
 * @complexity O(n) in the bounded body plus header count; no I/O. */
function toOAuthFetchResponse({ response }: { readonly response: HttpResponse }): Response {
  if (response.bodyTruncated) throw new JiniOAuthError({ code: "OAUTH_MALFORMED_RESPONSE",
    message: "the OAuth response exceeded the outbound response limit",
    operatorAction: "This provider's OAuth endpoint returned an oversized response." });
  // Fetch forbids bodies on 204/205/304, even when the native port returns an empty string.
  return new Response([204, 205, 304].includes(response.status) ? null : response.bodyText,
    { status: response.status, headers: { ...response.headers } });
}

/** Tovu copy; the protocol and reserved-parameter protections live in Jini's OAuth package. */
export const tovuOAuthMessages = {
  ...defaultOAuthMessages,
  reservedAuthorizationParameter: ({ parameter }: { readonly parameter: string }) =>
    `'${parameter}' is set by Tovu and cannot be overridden for this provider`,
  registrationRejectedAction: "This server refused to register Tovu as a client — check its OAuth requirements, or supply a client id by hand.",
};

/** Bind discovered endpoints to the exact issuer while retaining the host's explicit loopback
 * development exception. Safe URL syntax alone cannot prevent credential exfiltration to a
 * different public origin. The scheme and private-host decisions still belong to the guard. */
export function createTovuIssuerBoundDiscoveryPolicy({ guard }: { readonly guard: OAuthUrlGuard }): OAuthDiscoveryPolicy {
  return {
    assertMetadata({ issuer, document }) {
      if (document.issuer !== undefined && document.issuer !== issuer)
        rejectDiscoveredMetadata("OAuth metadata issuer does not equal the requested issuer");
      const origin = guard.assertSafeUrl({ raw: issuer, label: "authorization server issuer" }).origin;
      for (const key of ["authorization_endpoint", "token_endpoint", "registration_endpoint", "device_authorization_endpoint"]) {
        const raw = document[key];
        if (raw === undefined || raw === null) continue;
        if (typeof raw !== "string") rejectDiscoveredMetadata(`OAuth metadata ${key} is not an absolute URL`);
        const endpoint = guard.assertSafeUrl({ raw, label: `discovered ${key.replace(/_/g, " ")}` });
        if (endpoint.origin !== origin || endpoint.username || endpoint.password)
          rejectDiscoveredMetadata(`OAuth metadata ${key} does not share the issuer's origin`);
      }
    },
  };
}

/** A declaration, not a const arrow, so TypeScript narrows on its `never` return without a dead
 * `continue` after each call.
 * @throws {JiniOAuthError} Always `OAUTH_UNSAFE_ENDPOINT`. */
function rejectDiscoveredMetadata(message: string): never {
  throw new JiniOAuthError({ code: "OAUTH_UNSAFE_ENDPOINT", message,
    operatorAction: "Check the authorization server issuer and discovery endpoints before connecting." });
}

/** Keep Tovu's Settings route wording while retaining Jini's typed terminal/retryable errors.
 * Provider bodies are never copied into an operator action; only fixed library copy is adapted. */
export async function withTovuOAuthCopy<T>({ call }: { readonly call: () => Promise<T> }): Promise<T> {
  try { return await call(); }
  catch (caught) {
    // Guarded transport clipping is already a structured protocol error. Jini wraps fetch
    // failures as unreachable, so retain the bounded-response verdict rather than its wrapper.
    const error = caught instanceof JiniOAuthError && caught.code === "OAUTH_PROVIDER_UNREACHABLE"
      && caught.cause instanceof JiniOAuthError && caught.cause.code === "OAUTH_MALFORMED_RESPONSE"
      ? caught.cause : caught;
    if (!(error instanceof JiniOAuthError)) throw error;
    const operatorAction = error.operatorAction.replace("the connection settings", "Settings → External MCP");
    if (operatorAction === error.operatorAction) throw error;
    throw new JiniOAuthError({ code: error.code, message: error.message, operatorAction }, {
      cause: error.cause, providerErrorCode: error.providerErrorCode, retryAfterSeconds: error.retryAfterSeconds,
    });
  }
}

import type { KeyringPort } from "@jini-ai/platform/secrets";

/** The parts of a store vault's `required` input that crypto guards read. Both are read at call time,
 * never captured, so a guard always sees the store's current keyring and translator. */
export interface StorageFailureSource {
  keyring?: KeyringPort | undefined;
  storageError: (error?: unknown) => Error;
}

/** Only crypto errors become the feature's safe storage error; the original error is its argument.
 * @throws whatever `source.storageError` returns, for any sync or async failure of `operation`.
 * @complexity O(1) around one awaited operation.
 */
export async function protectStorage<T>(
  { operation, source }: { operation: () => Promise<T>; source: Pick<StorageFailureSource, "storageError"> },
  _optional = {},
): Promise<T> {
  try { return await operation(); } catch (error) { throw source.storageError(error); }
}

/** Keyring port for a store vault. A missing keyring raises the storage error inside the guard, which
 * then translates it once more, so the feature receives storageError(storageError()). Jini's vault
 * service calls only `activeKey`; `derive` and `deriveSigningSecret` complete the port contract.
 * @complexity O(1) per call; delegates all key work to the injected keyring.
 */
export function createStoreKeyring({ source }: { source: StorageFailureSource }, _optional = {}): KeyringPort {
  const withKeyring = <T>({ use }: { use: (keyring: KeyringPort) => Promise<T> }): Promise<T> => protectStorage({ source, operation: () => {
    if (!source.keyring) throw source.storageError();
    return use(source.keyring);
  } });
  return {
    derive: input => withKeyring({ use: keyring => keyring.derive(input) }),
    deriveSigningSecret: input => withKeyring({ use: keyring => keyring.deriveSigningSecret(input) }),
    activeKey: () => withKeyring({ use: keyring => keyring.activeKey({}) }),
  };
}

import { createVaultMetaParsers, isCopyableKind, SecretsVaultService, VAULT_KINDS, VaultError,
  type VaultRepoPort, type VaultContext,
  type VaultKind, type VaultMeta, type VaultMetaParser, type VaultMetaParsers, type VaultOptions } from "@jini-ai/platform/secrets/credential-sets";
import type { Clock } from "@jini-ai/core/primitives";
import type { KeyringPort, SecretSealerPort } from "@jini-ai/platform/secrets";
import { createStoreKeyring, protectStorage } from "./store-vault-guards.js";
import { assertHostMetaRules, assertRecoveryMeta, parseStructuralMeta, withRecoveryMeta } from "./vault-meta-rules.js";

/** Tovu owns catalogs and safe-metadata policy; Jini owns structural parsing and the vault lifecycle. */
export interface TovuVaultPolicy {
  validateMeta(input: { kind: VaultKind; meta: VaultMeta }): VaultMeta;
  /** Workspace registry first, bundled registry second, as in the former publish backfill.
   * Missing plugins leave their legacy records recoverable instead of guessing a vendor. */
  legacyPublishCredential(input: { workspaceId: string; providerId: string }): { vendorId: string; tokenField: string } | undefined;
  tokenField(input: { kind: VaultKind; provider: string | null }): string | undefined;
}

/** Register host policy in Jini's complete-shape parsers (also used on reads and merged patches).
 * Provenance is retained for recovery; legacy AAD markers are deliberately not accepted here.
 * @throws VaultError or host policy errors for unsafe/invalid metadata.
 * @complexity O(metadata size); no I/O or module-owned registry state.
 */
export function createTovuVaultKinds(
  { policy }: { policy: TovuVaultPolicy },
  _optional: Record<string, never> = {},
): { metaParsers: VaultMetaParsers; policy: TovuVaultPolicy; isCopyableKind: typeof isCopyableKind } {
  return { metaParsers: createHostMetaParsers({ policy }), policy, isCopyableKind };
}

/** Jini's parsers with one host parser per kind; only the policy's metadata decision is consulted.
 * @complexity O(kinds) setup; no I/O.
 */
function createHostMetaParsers({ policy }: { policy: Pick<TovuVaultPolicy, "validateMeta"> }, _optional = {}): VaultMetaParsers {
  const base = createVaultMetaParsers({});
  const parsers = Object.fromEntries([...VAULT_KINDS, "custom" as const].map(kind => [kind, createHostParser({ kind, base, policy })]));
  return createVaultMetaParsers({}, { parsers: parsers as VaultMetaParsers });
}

/** One kind's host parser. Jini hands it a JSON-safe clone that already passed its own checks.
 * Order: recovery provenance, structural parse, host rules, then the host policy's catalog decision.
 * @throws VaultError, CredentialInputError, TypeError (unparseable origin) or host policy errors.
 * @complexity O(metadata size); no I/O.
 */
function createHostParser(
  { kind, base, policy }: { kind: VaultKind; base: VaultMetaParsers; policy: Pick<TovuVaultPolicy, "validateMeta"> },
  _optional = {},
): VaultMetaParser {
  return ({ meta, provider }, _options: VaultOptions = {}) => {
    const input = meta as VaultMeta;
    assertRecoveryMeta({ meta: input });
    const { migration, normalization, ...plain } = input;
    const parsed = parseStructuralMeta({ kind, meta: plain, provider, base });
    assertHostMetaRules({ kind, meta: parsed });
    return withRecoveryMeta({ meta: policy.validateMeta({ kind, meta: parsed }), migration, normalization });
  };
}

/** Feature permissions stay at their existing boundary; this host policy constrains the injected
 * service to one Tovu-owned kind. Only crypto errors become the feature's safe storage error.
 * @complexity Constant setup; the Jini service owns all persistence and sealing work.
 */
export function createTovuStoreVault(required: {
  repo: { vault?: VaultRepoPort }; kind: "media-provider" | "vendor" | "custom" | "site-assistant" | "personal-execution"; sealer: SecretSealerPort;
  keyring?: KeyringPort; clock?: Clock; storageError: (error?: unknown) => Error;
  /** Assistant stores constrain the full session/site scope and mint stable singleton IDs. */
  context?: VaultContext; newId?: (input: VaultOptions) => string;
}, _options = {}): SecretsVaultService {
  if (!required.repo.vault) throw new VaultError({ code: "invalid-record" });
  const protect = <T>(operation: () => Promise<T>): Promise<T> => protectStorage({ operation, source: required });
  return new SecretsVaultService({ repo: required.repo.vault, metaParsers: storeMetaParsers,
    authorize: async ({ context }) => {
      if (required.context && context.workspaceId !== required.context.workspaceId) throw new VaultError({ code: "context" });
      if (context.kind !== required.kind || context.ownerKey !== "tovu" || context.principalId !== (required.context?.principalId ?? null) ||
        ("binding" in context && context.binding !== null)) throw new VaultError({ code: "context" });
    },
    keyring: createStoreKeyring({ source: required }),
    sealer: { seal: input => protect(() => required.sealer.seal({ plaintext: input.plaintext, key: input.key, aad: input.aad })),
      open: (input, options) => protect(() => required.sealer.open(input, options)) },
    now: () => new Date(required.clock?.nowMs() ?? 0).toISOString(),
    newId: () => { if (required.newId) return required.newId({}); throw new VaultError({ code: "invalid-record" }); },
  });
}

// Immutable registration; feature stores validate their inputs, these parsers also validate reads.
const storeMetaParsers = createHostMetaParsers({ policy: { validateMeta: ({ meta }) => meta } });

/** Parse complete feature metadata through the same registration used by the vault service. */
export function parseTovuStoreMeta(input: { kind: "media-provider" | "vendor" | "custom" | "site-assistant" | "personal-execution" | "api-connection"; meta: unknown; provider?: string | null | undefined }, _options = {}): VaultMeta {
  return storeMetaParsers[input.kind](input);
}

/** Binary label order for labelled kinds (`custom`, `publish-peer`): what their pre-vault label
 * index returned on every dialect. Labels are unique per workspace and kind, so ties never occur.
 * @complexity O(1) per comparison. */
export function byVaultLabel(a: { label: string }, b: { label: string }): number {
  return a.label < b.label ? -1 : a.label > b.label ? 1 : 0;
}

import { VaultError, type VaultJson, type VaultKind, type VaultMeta, type VaultMetaParsers } from "@jini-ai/platform/secrets/credential-sets";
import { assertCredentialFreeField } from "#src/contracts/core/credential-token";
import { CUSTOM_CREDENTIAL_CATEGORIES } from "#src/features/custom-credentials/types";
import { parseApiConnectionMeta } from "./vault-api-connection-meta.js";

/** Tovu's host rules for vault metadata, run inside Jini's complete-shape parsers by `createTovuVaultKinds`.
 * Every rule is pure and throws on the first problem; callers rely on the order documented per function. */

const NORMALIZATION_STATUSES = ["missing-key", "unopenable", "invalid-meta", "catalog-unavailable", "conflict"];
const MIGRATION_LABEL_FIELDS = ["originalLabel", "mappedLabel"];
const DESCRIPTION_FIELDS = ["host", "port", "database", "user"];
const SUCCESS_RUN_FIELDS = ["copied", "snapshotAt", "tableCount", "rowCount"];
const FAILURE_RUN_FIELDS = ["copied", "snapshotAt", "code", "message"];
const CREDENTIAL_FREE_TEXT_FIELDS = ["baseUrl", "model", "username", "accountLabel"];

function invalidMeta(): VaultError {
  return new VaultError({ code: "invalid-meta" });
}

/** Recovery provenance (`migration`, `normalization`) rides beside ordinary metadata.
 * Legacy AAD markers are deliberately not accepted here.
 * @throws VaultError invalid-meta for a legacy AAD marker, unknown status or non-object migration;
 *   CredentialInputError when a migration label holds a credential.
 * @complexity O(1); fixed field checks, no I/O.
 */
export function assertRecoveryMeta({ meta }: { meta: VaultMeta }, _optional = {}): void {
  if (Object.hasOwn(meta, "legacyAad")) throw invalidMeta();
  const { migration, normalization } = meta;
  if (normalization !== undefined && (typeof normalization !== "string" || !NORMALIZATION_STATUSES.includes(normalization))) throw invalidMeta();
  if (migration !== undefined) assertMigrationProvenance({ migration });
}

function assertMigrationProvenance({ migration }: { migration: VaultJson }, _optional = {}): void {
  if (migration === null || typeof migration !== "object" || Array.isArray(migration)) throw invalidMeta();
  for (const field of MIGRATION_LABEL_FIELDS) {
    const value = migration[field];
    if (typeof value === "string") assertCredentialFreeField({ value, field });
  }
}

/** Dispatch Tovu's api-connection formats or Jini's kind parser, retaining a destination's `savedAt`.
 * @throws VaultError invalid-meta from structural parsing or a non-string `savedAt`; Jini's OAuth error for invalid token metadata.
 * @complexity O(metadata size); one structural parse, no I/O.
 */
export function parseStructuralMeta(
  { kind, meta, provider, base }: { kind: VaultKind; meta: VaultMeta; provider: string | null | undefined; base: VaultMetaParsers },
  _optional = {},
): VaultMeta {
  if (kind === "api-connection") return parseApiConnectionMeta({ meta });
  if (kind !== "database-destination") return base[kind]({ meta, provider });
  // savedAt describes the destination save, not the last metadata patch. Old migrated rows
  // omit it and use createdAt; it must survive later lastRun updates without changing.
  const { savedAt, ...destinationMeta } = meta;
  const parsed = base[kind]({ meta: destinationMeta, provider });
  if (savedAt === undefined) return parsed;
  if (typeof savedAt !== "string") throw invalidMeta();
  parsed.savedAt = savedAt;
  return parsed;
}

/** Host read/write invariants on structurally parsed metadata, including merged lastRun patches.
 * Order: peer binding, destination description and run, custom category, then credential-free text,
 * additional origins and worksFor entries.
 * @throws VaultError for malformed descriptions, peer bindings, run summaries, categories or origins;
 *   CredentialInputError when a plain field holds a credential; TypeError for an unparseable origin.
 * @complexity O(metadata size); fixed field checks, no I/O.
 */
export function assertHostMetaRules({ kind, meta }: { kind: VaultKind; meta: VaultMeta }, _optional = {}): void {
  if (kind === "publish-peer") assertPublishPeerMeta({ meta });
  if (kind === "database-destination") assertDatabaseDestinationMeta({ meta });
  assertCustomCategory({ kind, meta });
  assertCredentialFreeMeta({ meta });
}

function assertPublishPeerMeta({ meta }: { meta: VaultMeta }, _optional = {}): void {
  if (typeof meta.baseUrl !== "string" || typeof meta.remoteWorkspaceId !== "string" || !meta.remoteWorkspaceId) throw invalidMeta();
}

/** No connection URI is metadata: a destination is described only by its four plain fields. */
function assertDatabaseDestinationMeta({ meta }: { meta: VaultMeta }, _optional = {}): void {
  const description = meta.description as VaultMeta | null | undefined;
  if (!description || DESCRIPTION_FIELDS.some(field => typeof description[field] !== "string") ||
    !hasOnlyFields({ record: description, fields: DESCRIPTION_FIELDS })) throw invalidMeta();
  for (const [field, value] of Object.entries(description)) assertCredentialFreeField({ value: value as string, field });
  if (meta.lastRun === null) return;
  assertRunSummary({ run: meta.lastRun as VaultMeta | null | undefined });
}

function assertRunSummary({ run }: { run: VaultMeta | null | undefined }, _optional = {}): void {
  if (!run || typeof run.snapshotAt !== "string" || typeof run.copied !== "boolean") throw invalidMeta();
  const valid = run.copied
    ? hasOnlyFields({ record: run, fields: SUCCESS_RUN_FIELDS }) && [run.tableCount, run.rowCount].every(value => isRunCount({ value }))
    : hasOnlyFields({ record: run, fields: FAILURE_RUN_FIELDS }) && typeof run.code === "string" && typeof run.message === "string";
  if (!valid) throw invalidMeta();
}

function hasOnlyFields({ record, fields }: { record: VaultMeta; fields: readonly string[] }, _optional = {}): boolean {
  return Object.keys(record).every(field => fields.includes(field));
}

function isRunCount({ value }: { value: VaultJson | undefined }, _optional = {}): boolean {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

function assertCustomCategory({ kind, meta }: { kind: VaultKind; meta: VaultMeta }, _optional = {}): void {
  const isCustom = kind === "custom" || (kind === "vendor" && meta.credentialType === "custom");
  if (isCustom && !CUSTOM_CREDENTIAL_CATEGORIES.includes(meta.category as typeof CUSTOM_CREDENTIAL_CATEGORIES[number])) throw invalidMeta();
}

function assertCredentialFreeMeta({ meta }: { meta: VaultMeta }, _optional = {}): void {
  for (const field of CREDENTIAL_FREE_TEXT_FIELDS) {
    const value = meta[field];
    if (typeof value === "string") assertCredentialFreeField({ value, field });
  }
  if (Array.isArray(meta.additionalHosts)) for (const value of meta.additionalHosts) assertCredentialFreeOrigin({ value });
  if (Array.isArray(meta.worksFor)) for (const value of meta.worksFor) {
    assertCredentialFreeField({ value: value as string, field: "worksFor" });
  }
}

/** One additional host: a canonical origin (no path, query or trailing slash) holding no credential.
 * Jini's structural parser already guarantees strings; the type check stays as defence in depth.
 * @throws VaultError invalid-meta for a non-string or non-origin; TypeError for an unparseable URL;
 *   CredentialInputError for a credential-shaped origin.
 * @complexity O(value length); no I/O.
 */
export function assertCredentialFreeOrigin({ value }: { value: VaultJson }, _optional = {}): void {
  if (typeof value !== "string" || new URL(value).origin !== value) throw invalidMeta();
  assertCredentialFreeField({ value, field: "additionalHosts" });
}

/** Re-attach recovery provenance after host policy, only when the input carried it. */
export function withRecoveryMeta(
  { meta, migration, normalization }: { meta: VaultMeta; migration: VaultJson | undefined; normalization: VaultJson | undefined },
  _optional = {},
): VaultMeta {
  return { ...meta, ...(migration === undefined ? {} : { migration }), ...(normalization === undefined ? {} : { normalization }) };
}

import { format } from "node:util";
import { Writable } from "node:stream";
import { StringDecoder } from "node:string_decoder";

import type { ServerLogBuffer, ServerLogLevel, ServerLogSource } from "./log-buffer.js";

/**
 * @file Formats console output once and redacts it before either the terminal or buffer sees it.
 * Generic (no Tovu concepts) — moves to `@jini-ai/diagnostics` with the buffer.
 *
 * Capture must never break logging: a failing redactor emits a safe placeholder, never raw text;
 * a failing or full buffer can only lose the captured copy, never the original console call.
 */

type ConsoleMethod = "debug" | "log" | "info" | "warn" | "error";

/**
 * Frames child output before invoking the caller's existing redactor, including an unterminated
 * final line. Never closes the parent sink. Oversized lines are discarded whole so cutting a
 * credential before redaction cannot expose a fragment. Redactor failures emit fixed copy.
 * @param required Parent sink and redaction policy; no process globals are read.
 * @param optional Input-line and rendered-line limits, in characters.
 * @returns A writable for one child stream; ending it, or its source unpiping at EOF, flushes the last line.
 * @complexity O(n) time for n input characters; O(maxLineLength) retained space.
 * @example child.stderr.pipe(createRedactedOutputSink({ sink: process.stderr, redact }));
 */
export function createRedactedOutputSink(
  { sink, redact }: { sink: Pick<Writable, "write">; redact: (text: string) => string },
  { maxLineLength = 65_536, maxLength = 2_000 }: { maxLineLength?: number; maxLength?: number } = {},
): Writable {
  const decoder = new StringDecoder("utf8");
  let pending = "";
  let oversized = false;
  const emit = () => {
    let safe = "[output redaction failed]";
    try { safe = oversized ? "[oversized output line omitted]" : redact(pending); }
    catch { /* Raw child bytes must never be the fallback. */ }
    if (safe) sink.write(`${safe.slice(0, maxLength)}\n`);
    pending = "";
    oversized = false;
  };
  const append = (text: string) => {
    let start = 0;
    while (start < text.length) {
      const newline = text.indexOf("\n", start);
      const end = newline === -1 ? text.length : newline;
      if (!oversized && pending.length + end - start > maxLineLength) { pending = ""; oversized = true; }
      else if (!oversized) pending += text.slice(start, end);
      if (newline === -1) return;
      emit();
      start = newline + 1;
    }
  };
  const flush = () => { append(decoder.end()); if (pending || oversized) emit(); };
  const writable = new Writable({
    write(chunk: Buffer, _encoding, done) { append(decoder.write(chunk)); done(); },
    final(done) { flush(); done(); },
  });
  // A source piped with { end: false } (Jini's daemon adapter keeps host sinks open across respawns)
  // never calls end(); its EOF only unpipes, and the unterminated last line is often the native crash.
  writable.on("unpipe", flush);
  return writable;
}

const LEVEL_BY_METHOD: Record<ConsoleMethod, ServerLogLevel> = {
  debug: "debug", log: "info", info: "info", warn: "warn", error: "error",
};

/** The slice of `console` the tee replaces; injectable so tests never patch the real console. */
export type TeeableConsole = Record<ConsoleMethod, (...args: unknown[]) => void>;

export interface InstallConsoleTeeRequired {
  readonly buffer: ServerLogBuffer;
}

export interface InstallConsoleTeeOptional {
  /** Defaults to the global `console`. */
  readonly target?: TeeableConsole;
  readonly source?: ServerLogSource;
  /** Applied before both copies; defaults to identity. Redactor failure never exposes raw text. */
  readonly redact?: (text: string) => string;
}

function safeAppend(buffer: ServerLogBuffer, level: ServerLogLevel, source: ServerLogSource, message: string): void {
  try {
    buffer.append({ level, source, message });
  } catch {
    // Losing one captured line is acceptable; throwing out of console.error is not.
  }
}

/**
 * Wraps console.debug/log/info/warn/error so each call is also appended to the buffer.
 * The original method receives the formatted, redacted string before the buffer copy is appended.
 * @param required The buffer to append to.
 * @param optional Console to patch (tests), source tag and injected redactor.
 * @returns Uninstall, restoring exactly the methods this call replaced.
 * @complexity O(n) formatting space/time for n output characters, plus the injected redactor and buffer.
 * @example const uninstall = installConsoleTee({ buffer });
 */
export function installConsoleTee(required: InstallConsoleTeeRequired, optional: InstallConsoleTeeOptional = {}): () => void {
  const target = optional.target ?? (console as unknown as TeeableConsole);
  const source = optional.source ?? "server";
  const redact = optional.redact ?? (text => text);
  const originals = new Map<ConsoleMethod, (...args: unknown[]) => void>();
  for (const method of Object.keys(LEVEL_BY_METHOD) as ConsoleMethod[]) {
    const original = target[method];
    originals.set(method, original);
    target[method] = (...args: unknown[]) => {
      let message = "[log redaction failed]";
      try {
        message = redact(format(...args));
      } catch {
        // Formatting or redaction failure must never send the raw arguments to a log shipper.
      }
      original.call(target, message);
      safeAppend(required.buffer, LEVEL_BY_METHOD[method], source, message);
    };
  }
  return () => {
    for (const [method, original] of originals) target[method] = original;
  };
}

import path from "node:path";
import { format } from "node:util";

import { redactSecretShapes } from "#src/contracts/core/secret-redaction";

import { installConsoleTee } from "./console-tee.js";
import { createLogBuffer, DEFAULT_MAX_ENTRIES, type ServerLogBuffer, type ServerLogEntry, type ServerLogSource } from "./log-buffer.js";
import { createRotatingLogFileSink, readLogFileTail, type LogFileFsPort } from "./log-file.js";

export { installConsoleTee, type TeeableConsole } from "./console-tee.js";
export { createLogBuffer, DEFAULT_MAX_BYTES, DEFAULT_MAX_ENTRIES, type ServerLogAppendInput, type ServerLogBuffer, type ServerLogEntry, type ServerLogLevel, type ServerLogSource } from "./log-buffer.js";
export { createRotatingLogFileSink, readLogFileTail, type LogFileFsPort } from "./log-file.js";

/**
 * @file The ONE process-wide server log buffer. Console is process-global, so its capture is too:
 * boot installs the tee once per process, and every reader (the admin route and the
 * `system_read_server_logs` chat tool) reads through `readProcessServerLogs`.
 *
 * Redaction uses Tovu's `redactSecretShapes` (secret VALUES only — paths, ids and prose stay
 * readable, per that helper's 2026-09-16 owner ruling).
 *
 * Two processes, two files, one log (L2): the main server (`index.ts`, `cli serve`) writes
 * `<site>/ops/logs/server.log`; the agent daemon (`agent-daemon-server.ts`, where the daemon-path
 * chat tool runs) writes `<site>/ops/logs/daemon.log`. One writer per file, so rotation never races.
 * Readers in either process merge both files by time, so each sees the whole picture, including
 * lines from before a crash/restart. Each process tees its OWN console because that is the only
 * place the real level is known: the daemon logs routine breadcrumbs with `console.error`, and its
 * piped stderr alone cannot tell those apart from real errors. The in-memory buffer is the fallback
 * when no file is attached (memory-DB runs, tests).
 */

let processBuffer: ServerLogBuffer | null = null;
let uninstallCapture: (() => void) | null = null;
let readFilePaths: readonly string[] = [];
let detachFile: (() => void) | null = null;
let identity = { release: 'tovu@unknown-dev', environment: 'local' };
let traceIds: () => { traceId: string; spanId: string } | undefined = () => undefined;

/** Composition supplies a live site tracing reader; IDs are read at append time, never generated. */
export function setServerLogTraceReader(required: { traceIds: () => { traceId: string; spanId: string } | undefined }, _optional = {}): void {
  traceIds = required.traceIds;
}

/** Created lazily so a test or tool that only reads gets an empty buffer, never a crash. */
export function getServerLogBuffer(): ServerLogBuffer {
  processBuffer ??= createLogBuffer({ redact: text => redactSecretShapes({ text }).text }, { metadata: () => ({ ...identity, ...traceIds() }) });
  return processBuffer;
}

/** True once boot has installed the console tee in this process. */
export function isServerLogCaptureInstalled(): boolean {
  return uninstallCapture !== null;
}

/**
 * Starts copying this process's console output into the process buffer, plus a fatal uncaught
 * exception (which Node prints without going through `console`). `uncaughtExceptionMonitor` only
 * observes: Node's default crash behavior is unchanged. Idempotent.
 * @param optional Which process this is (default "server").
 * @returns Uninstall (tests only; production keeps capture for the process lifetime).
 * @complexity O(1).
 */
export function installServerLogCapture(optional: { source?: ServerLogSource; release?: string; environment?: string } = {}, _options: Record<string, never> = {}): () => void {
  if (uninstallCapture === null) {
    identity = { release: optional.release ?? identity.release, environment: optional.environment ?? identity.environment };
    const source = optional.source ?? "server";
    const buffer = getServerLogBuffer();
    const untee = installConsoleTee({ buffer }, { source, redact: text => redactSecretShapes({ text }).text });
    const onFatal = (err: unknown) => {
      try { buffer.append({ level: "error", source, message: `[uncaughtException] ${format(err)}` }); } catch { /* never mask the crash */ }
    };
    process.on("uncaughtExceptionMonitor", onFatal);
    uninstallCapture = () => { untee(); process.off("uncaughtExceptionMonitor", onFatal); };
  }
  return () => {
    uninstallCapture?.();
    uninstallCapture = null;
  };
}

/** `<siteDir>/ops/logs/{server,daemon}.log` — the one place both processes agree the logs live. */
export function serverLogFilePaths(required: { siteDir: string }): Record<ServerLogSource, string> {
  const dir = path.join(required.siteDir, "ops", "logs");
  return { server: path.join(dir, "server.log"), daemon: path.join(dir, "daemon.log") };
}

/**
 * Persists every buffered line to this process's rotating log file, starting with the lines already
 * buffered before the site directory was known; reads then merge `filePath` with `alsoRead` (the
 * other process's file). Idempotent: a second call is ignored.
 * @param required This process's own log file (from `serverLogFilePaths`).
 * @param optional The other process's log file(s) and a filesystem port (tests).
 * @returns Detach (tests only).
 * @complexity O(buffered lines) once, then O(1) per line.
 */
export function attachServerLogFile(required: { filePath: string }, optional: { alsoRead?: readonly string[]; fs?: LogFileFsPort } = {}): () => void {
  if (detachFile === null) {
    const sink = createRotatingLogFileSink({ filePath: required.filePath }, { fs: optional.fs });
    const buffer = getServerLogBuffer();
    for (const entry of buffer.entries()) sink.write(entry);
    const unsubscribe = buffer.subscribe(entry => sink.write(entry));
    readFilePaths = [required.filePath, ...(optional.alsoRead ?? [])];
    detachFile = () => { unsubscribe(); readFilePaths = []; detachFile = null; };
  }
  return () => detachFile?.();
}

/**
 * Reads this process's view of the server log: the attached log files merged by time when attached,
 * otherwise the in-memory buffer.
 * @param optional Filesystem port (tests).
 * @returns Entries oldest first (at most the buffer cap), and whether anything is recording them.
 * @complexity O(tail bytes x files) plus an O(n log n) merge.
 */
export function readProcessServerLogs(optional: { fs?: LogFileFsPort } = {}): { entries: readonly ServerLogEntry[]; capturing: boolean } {
  if (readFilePaths.length > 0) {
    const perFile = readFilePaths.map(filePath => readLogFileTail({ filePath }, { maxEntries: DEFAULT_MAX_ENTRIES, fs: optional.fs }));
    // ISO-8601 UTC strings sort lexically; the stable sort keeps each file's own order for ties.
    const merged = perFile.flatMap(entries => entries ?? []).sort((a, b) => (a.at < b.at ? -1 : a.at > b.at ? 1 : 0));
    return { entries: merged.slice(-DEFAULT_MAX_ENTRIES), capturing: perFile.some(entries => entries !== null) };
  }
  return { entries: getServerLogBuffer().entries(), capturing: isServerLogCaptureInstalled() };
}

import fs from "node:fs";
import path from "node:path";

import type { ServerLogEntry } from "./log-buffer.js";

/**
 * @file Persisted tail of the server log buffer (slice L2, gap A-04): one JSON entry per line in
 * `<file>`, rotated to `<file>.1` at a size cap, so recent errors survive a crash/restart and so a
 * SECOND process (the agent daemon, where the daemon-path chat tool runs) can read what the main
 * process captured. Generic — moves to `@jini-ai/diagnostics` with the buffer.
 *
 * One writer per file: only the process that owns the console tee writes; readers only read. Entries
 * arrive already redacted from the buffer, so nothing unredacted ever reaches disk.
 *
 * Writes are synchronous, like `console.*` itself to a file or pipe, so a crash right after an error
 * line still leaves that line on disk. A write failure (disk full, permissions) silently disables
 * the sink: it must never log about itself, because its own log line would come straight back here.
 */

const DEFAULT_LOG_FILE_MAX_BYTES = 5_000_000;
const DEFAULT_LOG_TAIL_BYTES = 2_000_000;

/** The filesystem calls the sink and reader need; injectable so rotation is testable in memory. */
export interface LogFileFsPort {
  appendFile(filePath: string, data: string): void;
  /** Size in bytes, or null when the file does not exist. */
  size(filePath: string): number | null;
  rename(from: string, to: string): void;
  mkdirp(dir: string): void;
  /** The last `maxBytes` of the file as UTF-8, or null when it does not exist. */
  readTail(filePath: string, maxBytes: number): string | null;
}

export const nodeLogFileFs: LogFileFsPort = {
  appendFile: (filePath, data) => fs.appendFileSync(filePath, data, { mode: 0o600 }),
  size: filePath => {
    try { return fs.statSync(filePath).size; } catch { return null; }
  },
  rename: (from, to) => fs.renameSync(from, to),
  mkdirp: dir => { fs.mkdirSync(dir, { recursive: true }); },
  readTail: (filePath, maxBytes) => {
    let fd: number;
    try { fd = fs.openSync(filePath, "r"); } catch { return null; }
    try {
      const size = fs.fstatSync(fd).size;
      const length = Math.min(size, maxBytes);
      const bytes = Buffer.alloc(length);
      fs.readSync(fd, bytes, 0, length, size - length);
      return bytes.toString("utf8");
    } finally {
      fs.closeSync(fd);
    }
  },
};

export interface LogFileSink {
  write(entry: ServerLogEntry): void;
  /** False once a write has failed; the sink then drops everything. */
  isHealthy(): boolean;
}

/**
 * Appends entries as JSON lines, rotating `<file>` to `<file>.1` (replacing any older `.1`) before
 * a write would push it past `maxBytes`. At most about 2 x maxBytes on disk.
 * @param required The log file path.
 * @param optional Size cap and filesystem port.
 * @returns The sink.
 * @complexity O(entry size) per write; one stat at creation.
 */
export function createRotatingLogFileSink(required: { filePath: string }, optional: { maxBytes?: number; fs?: LogFileFsPort } = {}): LogFileSink {
  const io = optional.fs ?? nodeLogFileFs;
  const maxBytes = optional.maxBytes ?? DEFAULT_LOG_FILE_MAX_BYTES;
  let healthy = true;
  let size: number | null = null;
  return {
    write(entry) {
      if (!healthy) return;
      try {
        if (size === null) {
          io.mkdirp(path.dirname(required.filePath));
          size = io.size(required.filePath) ?? 0;
        }
        const line = `${JSON.stringify(entry)}\n`;
        const lineBytes = Buffer.byteLength(line);
        if (size > 0 && size + lineBytes > maxBytes) {
          io.rename(required.filePath, `${required.filePath}.1`);
          size = 0;
        }
        io.appendFile(required.filePath, line);
        size += lineBytes;
      } catch {
        healthy = false;
      }
    },
    isHealthy: () => healthy,
  };
}

function isEntry(value: unknown): value is ServerLogEntry {
  if (typeof value !== "object" || value === null) return false;
  const e = value as Record<string, unknown>;
  return typeof e.seq === "number" && typeof e.at === "string" && typeof e.level === "string" && typeof e.source === "string" && typeof e.message === "string";
}

/** Parses complete log entries, ignoring malformed fragments and torn lines. O(text length). */
function parseLines({ text }: { text: string }, _options = {}): ServerLogEntry[] {
  const lines = text.split("\n");
  const out: ServerLogEntry[] = [];
  for (const line of lines) {
    if (line === "") continue;
    try {
      const parsed: unknown = JSON.parse(line);
      if (isEntry(parsed)) out.push(parsed);
    } catch {
      // A torn final line from a crash mid-write is skipped, not fatal.
    }
  }
  return out;
}

/**
 * Parses the newest `budget` bytes of one log file.
 * @param required Filesystem port, file path, its stat size (null when absent) and the byte budget.
 * @returns The file's whole entries oldest first; empty when the file is absent or vanished before the read.
 * @complexity O(budget).
 */
function readTailEntries(required: { io: LogFileFsPort; filePath: string; size: number | null; budget: number }, _options = {}): ServerLogEntry[] {
  if (required.size === null) return [];
  return parseLines({ text: required.io.readTail(required.filePath, required.budget) ?? "" });
}

/**
 * Reads the newest entries from `<file>.1` then `<file>`, at most `maxBytes` in total.
 * @param required The log file path.
 * @param optional Byte budget, entry cap and filesystem port.
 * @returns Entries oldest first, or null when neither file exists.
 * @complexity O(maxBytes).
 */
export function readLogFileTail(required: { filePath: string }, optional: { maxBytes?: number; maxEntries?: number; fs?: LogFileFsPort } = {}): ServerLogEntry[] | null {
  const io = optional.fs ?? nodeLogFileFs;
  const budget = optional.maxBytes ?? DEFAULT_LOG_TAIL_BYTES;
  const currentSize = io.size(required.filePath);
  const rotatedPath = `${required.filePath}.1`;
  const rotatedSize = io.size(rotatedPath);
  if (currentSize === null && rotatedSize === null) return null;
  const current = readTailEntries({ io, filePath: required.filePath, size: currentSize, budget });
  const remaining = budget - Math.min(currentSize ?? 0, budget);
  const rotated = remaining <= 0 ? [] : readTailEntries({ io, filePath: rotatedPath, size: rotatedSize, budget: remaining });
  const all = [...rotated, ...current];
  return optional.maxEntries === undefined ? all : all.slice(-optional.maxEntries);
}

import os from "node:os";
import path from "node:path";
import { redactText } from "@jini-ai/diagnostics";

/** Path-name characters: a home followed by one of these is a sibling path (`/rootfs`), not the home. */
const NOT_PATH_CONTINUATION = "(?![A-Za-z0-9._-])";

/**
 * Credential and home-path redaction for local child, native and gate output before it is shown or stored.
 * Jini's username policy masks only `/Users/<u>`, `/home/<u>` and `\Users\<u>`; a home outside those
 * roots (root's `/root`, a service account's custom HOME) would otherwise pass through verbatim,
 * so the literal home directory is masked as `~` after the shared redactor runs.
 * @param required.text Untrusted text to redact.
 * @param optional.homeDir Home directory to mask; `os.homedir()` by default.
 * @returns The redacted text; a filesystem-root home is left to the username policy alone,
 *   since masking it would erase every absolute path.
 * @complexity O(n) time and space for n text characters.
 */
export function redactLocalText({ text }: { text: string }, { homeDir = os.homedir() }: { homeDir?: string } = {}): string {
  const redacted = redactText({ text }, { username: path.basename(homeDir) });
  const home = homeDir.replace(/[\\/]+$/, "");
  if (!home || path.parse(homeDir).root === homeDir) return redacted;
  const escaped = home.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return redacted.replace(new RegExp(`${escaped}${NOT_PATH_CONTINUATION}`, "g"), "~");
}

