import type { SiteStore } from "./site-store.js";
import type { SitesWorkspace } from "./sites-home.js";
import { resolveSiteDatabasePaths } from "./site-databases.js";
import fs from "node:fs";
import path from "node:path";
import type { AtomicFilesystemPort } from "@jini-ai/platform/fs";

import { contentKernel } from "../db/content-kernel.js";
import { closeSqliteConnection } from "../db/kernel/index.js";
import { prepareContentStore } from "../db/prepare-content-store.js";
import { type ContentDb, migrateSqliteContentFile, openSqliteContentConnection } from "../db/sqlite/content-db.js";
import { writeJsonFileAtomic } from "./atomic-write.js";
import { SiteCorruptError, SiteDirInvalidError } from "./errors.js";
import { completeKeyOnlySiteMeta } from "./key-only-site-meta.js";
import { readSiteDir } from "./read-site-dir.js";
import { resolveInstallDirTarget } from "./resolve-install-dir-target.js";
import { resolveWorkspace } from "./resolve-workspace.js";
import { compareSchemaVersion, runtimeSchemaVersion } from "./schema-guard.js";
import { parseSiteStorage } from "./site-storage.js";
import type { ConfigJson, SiteMetaJson, SiteStorage } from "./types.js";

/**
 * @file SPEC-003 C-008 — `bootSiteDir`, `tovu serve`'s validate -> guard -> migrate+stamp ->
 * resolve orchestration (BR-05/BR-06).
 *
 * Purpose:
 * Owns BR-06's stamp-write-after-migrate ordering in one place (CIC U-002): the schema guard
 * (step 4) runs BEFORE the db is ever opened, so a newer-or-divergent site's `content.db` is
 * never touched (AC-06); the `.site-meta.json` stamp rewrite (step 5) happens only AFTER
 * `migrate()` has already returned successfully, both fields written together in one atomic
 * operation (U-002-B2/ORD1); workspace resolution (step 6) is the final gate before the caller
 * (`cli/commands/serve.ts`) binds a listener (U-002-ORD2).
 *
 * Architectural role:
 * `site-dir` domain logic. No dependency on `cli/**` or `express` — this function never binds a
 * port; that is `cli`'s job (BR-05 step 7 lives one layer up). Every fs/db path here is derived
 * from the ONE resolved `target` (INV-01, CIC U-004).
 */

export interface BootSiteDirRequired {
  deps: BootSiteDirDeps;
  dir: string;
}

export interface BootSiteDirOptions {
  /** Resolve this exact workspace id instead of the default (oldest) — `tovu serve --workspace <id>`. */
  workspaceId?: string;
  /** Shared user config is injectable for isolated app-data/site fixtures. */
  workspace?: SitesWorkspace;
  /** Atomic metadata effects; defaults to the native filesystem, with Jini owning replacement. */
  metadataFilesystem?: AtomicFilesystemPort;
}

interface BootSiteDirResultBase {
  workspaceId: string;
  config: ConfigJson;
}

/** A SQLite site: the one open, migrated `content.db` handle. */
export interface SqliteSiteDirBoot extends BootSiteDirResultBase {
  storage: Extract<SiteStorage, { kind: "sqlite" }>;
  db: ContentDb;
  store?: undefined;
}

/** A Postgres/PGlite site (`.site-meta.json` `storage`): the store `openSiteStore` opened, at head. */
export interface StoreSiteDirBoot extends BootSiteDirResultBase {
  storage: Exclude<SiteStorage, { kind: "sqlite" }>;
  store: SiteStore;
  db?: undefined;
}

export type BootSiteDirResult = SqliteSiteDirBoot | StoreSiteDirBoot;

/**
 * Closes what {@link bootSiteDir} opened. `composed` is the store `createSiteRouteDeps` handed to
 * `onStoreOpened` when the composition got that far: closing it stops the composition's sweeps
 * (guest-chat, submission-IP retention; waiting for a pass in flight) and then closes `boot.store`
 * (Postgres/PGlite) or the `chat.db` the composition opened beside `content.db` (SQLite). Without
 * it, `boot.store` is closed directly. SQLite's borrowed `content.db` closes LAST, and even when
 * that close rejects: closing it first left a sweep batch still in flight on a closed connection.
 */
export async function closeSiteDirBoot(boot: BootSiteDirResult, composed?: Pick<SiteStore, "close">): Promise<void> {
  try {
    if (composed !== undefined) await composed.close();
    else if (boot.store !== undefined) await boot.store.close();
  } finally {
    if (boot.db !== undefined) closeSqliteConnection(boot.db);
  }
}

/**
 * Validate, guard, migrate, stamp, and resolve the workspace for `serve` (BR-05).
 *
 * @param required.dir - the install dir path; resolved once (CIC U-004) into `target`.
 * @param required.deps - host-owned repairs, store opening and vault normalization.
 * @param options.workspaceId - when supplied, resolve exactly this workspace id instead of the
 *   default (oldest) — threaded from `tovu serve --workspace <id>`.
 * @returns (as a promise; every failure below is a rejection) `{ storage, db | store, workspaceId,
 *   config }` — on SQLite `db` is the one open, migrated content.db handle; on Postgres/PGlite
 *   (`.site-meta.json` `storage`) `store` is the one opened store (see {@link bootStoreSiteDir}).
 *   `cli/commands/serve.ts` passes either straight to `createSiteRouteDeps`'s `overrides` (no
 *   second db is ever opened for the same boot).
 * @throws {SiteDirInvalidError} `config.json`/`.site-meta.json` invalid (via `readSiteDir`), a
 *   key-only `.site-meta.json` that cannot be completed (`key-only-site-meta.ts`), or `content.db`
 *   missing entirely.
 * @throws {SiteNewerThanRuntimeError} the site's schema is newer than, or diverges from, this
 *   runtime's (BR-05 step 4) — thrown BEFORE the db is opened, so it is never written (AC-06).
 * @throws {SiteCorruptError} `content.db` is unreadable/locked/corrupt (EC-05, RT-002), or the
 *   workspace table has zero rows (BR-05 step 6, via `resolveWorkspace`).
 * @throws {ValidationError} `options.workspaceId` was supplied but matches no workspace row.
 * @complexity Bounded — one db open+migrate, at most one atomic stamp rewrite, one workspace
 *   SELECT per call; not a function of any caller-controlled collection.
 * @overallScore 100
 */
export async function bootSiteDir(required: BootSiteDirRequired, options: BootSiteDirOptions = {}): Promise<BootSiteDirResult> {
  const { dir, deps } = required;
  const target = resolveInstallDirTarget(dir);

  // A dev site's `.site-meta.json` may hold only its site-key fields (`npm run dev` mints that
  // shape); complete it from the db first, or `readSiteDir` refuses a site that serves fine in dev.
  // Every folder boot (`serve`, `export`, `plugin install`, the desktop) comes through here.
  await completeKeyOnlySiteMeta({ dir: target });

  // BR-05 steps 1-2: dir/config/meta validation (SiteDirInvalidError).
  const { config, meta } = readSiteDir({ dir: target });
  const storage = parseSiteStorage(meta.storage);
  if (storage.kind !== "sqlite") return bootStoreSiteDir({ deps, target, storage, config, meta }, options);

  const dbPath = resolveSiteDatabasePaths({ dir: target, siteId: meta.siteId }, { workspace: options.workspace }).contentDbPath;
  if (!fs.existsSync(dbPath)) {
    throw new SiteDirInvalidError(`bootSiteDir: content.db is missing at ${dbPath}`);
  }

  // BR-05 step 4: schema guard, BEFORE the db is ever opened — a newer-or-divergent site's
  // content.db must never be written (AC-06), so this must not be reordered after the open below.
  const decision = compareSchemaVersion({ schemaVersion: meta.schemaVersion, schemaTag: meta.schemaTag });

  // BR-05 step 3 (continued): open + migrate (the runner; a copy in `ops/` first when a step is
  // pending). A locked/corrupt db surfaces here (EC-05, RT-002).
  let db: ContentDb;
  try {
    db = openSqliteContentConnection(dbPath);
  } catch (err) {
    throw new SiteCorruptError(`bootSiteDir: content.db at ${dbPath} could not be opened: ${(err as Error).message}`);
  }

  try {
    await migrateSqliteContentFile(db, dbPath);

    // The watermark singleton row every content store carries.
    await prepareContentStore(contentKernel(db));
    // The stored-data repairs every other store opener runs. The CLI hands this handle to the
    // composition as `overrides.db`, which skips `openSiteContentDb` (where SQLite runs them), so
    // without this `tovu serve <dir>`/`tovu export <dir>` never repaired a SQLite install.
    await deps.runBootDataRepairs({ kernel: contentKernel(db) });

    // BR-05 step 5 / BR-06 / CIC U-002-B2/ORD1: the stamp rewrite happens ONLY when a migration
    // was actually needed, both fields together, in one atomic operation, and only AFTER
    // `migrateSqliteContentFile` above has returned successfully.
    if (decision === "migrate") {
      const runtime = runtimeSchemaVersion();
      const updatedMeta: SiteMetaJson = { ...meta, schemaVersion: runtime.index, schemaTag: runtime.tag };
      writeJsonFileAtomic({ filePath: path.join(target, ".site-meta.json"), data: updatedMeta }, { filesystem: options.metadataFilesystem });
    }

    // BR-05 step 6 / CIC U-002-ORD2: workspace resolution is the final gate before the caller
    // may bind a listener — this must run AFTER the stamp write above, not before.
    const workspace = await resolveWorkspace({ kernel: contentKernel(db) }, { workspaceId: options.workspaceId });

    // Folder-only consumers (export/plugin operations) also need normalized credential payloads.
    await deps.normalizeSiteVaultAtBoot({ kernel: contentKernel(db), workspaceId: workspace.id, siteDir: target,
      clock: { nowMs: () => Date.now() } });

    // EC-07: an unrecognized templateId is provenance-only — warn, never block serving.
    if (meta.templateId !== "starter") {
      // eslint-disable-next-line no-console
      console.warn(`bootSiteDir: unrecognized .site-meta.json templateId "${meta.templateId}" at ${target} — proceeding (provenance only)`);
    }

    return { storage, db, workspaceId: workspace.id, config };
  } catch (err) {
    closeSqliteConnection(db);
    throw err;
  }
}

/**
 * The Postgres/PGlite arm of {@link bootSiteDir}: `openSiteStore` (connection secret → migrations
 * to head → prepared store), then the same workspace gate. The SQLite schema guard and its
 * `.site-meta.json` stamp are skipped: they describe `content.db`'s legacy chain, and a Postgres
 * store's own history is its migration ledger, which the runner checks while it opens.
 *
 * @throws whatever `openSiteStore` throws (`StorageSecretError`, `PgliteOwnerLockedError` when the
 *   PGlite data dir is already served, a migration failure); `resolveWorkspace`'s errors. The store is
 *   closed before any rejection.
 */
async function bootStoreSiteDir(
  required: { deps: BootSiteDirDeps; target: string; storage: StoreSiteDirBoot["storage"]; config: ConfigJson; meta: SiteMetaJson },
  options: BootSiteDirOptions
): Promise<StoreSiteDirBoot> {
  const { deps, target, storage, config, meta } = required;
  const store = await deps.openSiteStore({
    storage,
    dbPath: path.join(target, "content.db"),
    chatDbPath: path.join(target, "chat.db"),
    role: "owner",
  });
  try {
    const workspace = await resolveWorkspace({ kernel: store.content }, { workspaceId: options.workspaceId });
    await deps.normalizeSiteVaultAtBoot({ kernel: store.content, workspaceId: workspace.id, siteDir: target,
      clock: { nowMs: () => Date.now() } });
    if (meta.templateId !== "starter") {
      // eslint-disable-next-line no-console
      console.warn(`bootSiteDir: unrecognized .site-meta.json templateId "${meta.templateId}" at ${target} — proceeding (provenance only)`);
    }
    return { storage, store, workspaceId: workspace.id, config };
  } catch (err) {
    await store.close();
    throw err;
  }
}

import { sql } from "kysely";

import type { ContentKernel } from "../db/content-kernel.js";
import { openPgliteKernel } from "../db/kernel/drivers/pglite.js";
import { acquireOwnerLock, PgliteOwnerLockedError, runningPgliteOwner } from "../db/kernel/drivers/pglite-owner.js";
import { copyServedPgliteTo, StorageOpError, storageOps } from "../db/kernel/ops.js";
import type { StorageKernel } from "../db/kernel/port.js";
import { CHAT_LEDGER_TABLE } from "../db/migrations/index.js";
import { resetLegacySiteTitlePin } from "../db/sqlite/reset-legacy-site-title-pin.js";
import { InternalError, ValidationError } from "./errors.js";

/**
 * @file The PGlite half of `duplicateSite` (R1g): the `content.db` counterpart for a site stored on
 * PGlite. The copy is a consistent dump of the source's data dir restored into the new site's
 * (`storageOps.copyTo`), then the new copy is made the duplicate's own:
 *
 * - AI chat history is left behind, as on SQLite (where `chat.db` is simply not copied): every table
 *   in the `ai_chat` schema is emptied; its migration ledger is kept, so the copy is at head.
 * - The source's legacy site-title pin is reset (SPEC-050 REQ-12), exactly as `duplicateContentDb`.
 * - Compacted and verified (`VACUUM` + `CHECKPOINT` + ledger read-back) before it is handed back.
 *
 * Reaching the source: when THIS process serves it (duplicating the site you are running), through
 * its owner's exclusive window; otherwise the source must be stopped — the copy takes the data dir's
 * owner lock for the duration, so nothing writes to it meanwhile. A source served by another live
 * process is refused (its owner is the only one who may open it).
 */

/** The `ai_chat` tables emptied in a copy: all of them but the migration ledger. */
async function purgeAiChat(kernel: StorageKernel<unknown>): Promise<void> {
  const tables = await kernel.query<{ name: string }>(
    sql`SELECT table_name AS name FROM information_schema.tables
        WHERE table_schema = 'ai_chat' AND table_type = 'BASE TABLE' AND table_name <> ${CHAT_LEDGER_TABLE}
        ORDER BY table_name`
  );
  if (tables.length === 0) return;
  await kernel.execute(sql`TRUNCATE ${sql.join(tables.map((t) => sql.table(`ai_chat.${t.name}`)))}`);
}

/** Copies the source data dir to `targetDataDir` through the right door (see this file's header). */
async function copySource(sourceDataDir: string, targetDataDir: string): Promise<void> {
  const owner = runningPgliteOwner(sourceDataDir);
  if (owner !== undefined) {
    await copyServedPgliteTo(owner, targetDataDir);
    return;
  }
  let release: () => void;
  try {
    release = acquireOwnerLock(sourceDataDir);
  } catch (err) {
    if (err instanceof PgliteOwnerLockedError) {
      throw new ValidationError(`the site being duplicated is running (process ${err.pid ?? "unknown"}); stop it, or duplicate it from inside that site, then retry`);
    }
    throw err;
  }
  // Nested so the lock is released however the open, the copy or the close fails: the open can
  // throw synchronously, and a rejected close must not skip `release()` for the process's life.
  try {
    const source = openPgliteKernel<unknown>({ dataDir: sourceDataDir });
    try {
      await storageOps(source).copyTo(targetDataDir);
    } finally {
      await source.close();
    }
  } finally {
    release();
  }
}

/**
 * Copies a PGlite site's data dir to `targetDataDir` (which must not exist) with its AI chat emptied
 * and its legacy title pin reset.
 *
 * @throws {ValidationError} the source is served by another live process.
 * @throws {InternalError} the copy, the purge or the final verification failing (the driver's message kept).
 * @complexity One dump + restore of the whole data dir, one TRUNCATE, one VACUUM — bounded by the site's size.
 */
export async function duplicatePgliteStore(required: { sourceDataDir: string; targetDataDir: string }): Promise<void> {
  const { sourceDataDir, targetDataDir } = required;
  try {
    await copySource(sourceDataDir, targetDataDir);
  } catch (err) {
    if (err instanceof ValidationError) throw err;
    throw new InternalError(`duplicatePgliteStore: copying to ${targetDataDir} failed: ${(err as Error).message}`);
  }
  const target = openPgliteKernel<unknown>({ dataDir: targetDataDir });
  try {
    await purgeAiChat(target);
    await resetLegacySiteTitlePin({ db: target as ContentKernel });
    await storageOps(target).compactAndVerify();
  } catch (err) {
    if (err instanceof StorageOpError) throw new InternalError(`duplicatePgliteStore: ${err.message}`);
    throw err;
  } finally {
    await target.close();
  }
}

/** CMS local-site lifecycle policy. Effects stay behind the host process port; no spawn on import.
 * Capacity and folder mutations share one lane so concurrent requests cannot trash a starting site.
 */
import { SITE_NAME_PATTERN } from "./site-registry.js";

export type LocalSiteStatus = "starting" | "running" | "stopped" | "crashed";
export interface LocalSiteState {
  name: string; status: LocalSiteStatus; pid: number | null; port: number | null;
  daemonPort: number | null; adminUrl: string | null;
  app?: string; external?: boolean;
}
export class LocalSiteError extends Error {
  // Desktop loads this module through Node's strip-only TypeScript support.
  readonly code: string;

  constructor(code: string) {
    super(code);
    this.code = code;
    this.name = "LocalSiteError";
  }
}
export interface LocalSiteProcess {
  pid: number;
  onExit(required: { listener: () => void }): void;
  ready(): Promise<boolean>;
  /** Resolve only after the whole tree (including a detached daemon) has exited. */
  terminate(): Promise<void>;
  /** Synchronous signal path for host exit; async stop still verifies completion. */
  killNow(): void;
}
export interface LocalSiteProcessPort {
  isPortFree(required: { port: number }): Promise<boolean>;
  launch(required: { name: string; port: number; daemonPort: number }): Promise<LocalSiteProcess>;
  schedule(required: { run: () => void; delayMs: number }): () => void;
  dispose?(): Promise<void>;
  existing?(required: { name: string }): LocalSiteState | null;
  listExisting?(): LocalSiteState[];
}
export interface LocalSiteSupervisorPort {
  start(required: { name: string }, optional?: Record<string, never>): Promise<LocalSiteState>;
  stop(required: { name: string }, optional?: Record<string, never>): Promise<LocalSiteState>;
  list(): LocalSiteState[];
  withStoppedSite<T>(required: { name: string; task: () => Promise<T> }, optional?: Record<string, never>): Promise<T>;
  shutdown(): Promise<void>;
  killNow(): void;
}
interface Entry { state: LocalSiteState; child?: LocalSiteProcess; cancel?: () => void; probes: number; misses: number }

/** Validate before a name reaches a path or command. @complexity O(n), bounded to 100 chars. */
export function assertLocalSiteName({ name }: { name: string }, _optional = {}): void {
  if (name.length < 1 || name.length > 100 || !SITE_NAME_PATTERN.test(name)) throw new LocalSiteError("VALIDATION_ERROR");
}

/** Create a host-owned lifecycle with a bounded scan and DI effects. @complexity O(s) per list/cap. */
export function createLocalSiteSupervisor(
  { processPort, servingName, scheme }: { processPort: LocalSiteProcessPort; servingName: string; scheme: "http" | "https" },
  { maxConcurrent = 3, excludedPorts = [], readyAttempts = 240 }: { maxConcurrent?: number; excludedPorts?: readonly number[]; readyAttempts?: number } = {},
): LocalSiteSupervisorPort {
  if (!Number.isInteger(maxConcurrent) || maxConcurrent < 1 || maxConcurrent > 20) throw new LocalSiteError("INVALID_SITE_LIMIT");
  const entries = new Map<string, Entry>();
  const reserved = new Set([3000, 5173, 4319, ...excludedPorts]);
  let closed = false;
  let lane: Promise<unknown> = Promise.resolve();
  function serial<T>(task: () => Promise<T>): Promise<T> {
    const next = lane.then(task);
    lane = next.catch(() => {});
    return next;
  }
  function checkName(name: string) {
    assertLocalSiteName({ name });
    if (name === servingName) throw new LocalSiteError("SITE_SERVING");
    if (closed) throw new LocalSiteError("SITE_HOST_STOPPING");
  }
  async function allocate(): Promise<number> {
    for (let port = 3101; port < 4101; port++) {
      if (reserved.has(port)) continue;
      if (!(await processPort.isPortFree({ port }))) continue;
      reserved.add(port);
      return port;
    }
    throw new LocalSiteError("SITE_PORTS_EXHAUSTED");
  }
  async function reap(entry: Entry, status: "stopped" | "crashed") {
    entry.cancel?.();
    try { await entry.child?.terminate(); }
    catch { throw new LocalSiteError("SITE_STOP_FAILED"); }
    // Reservations survive a failed stop: a still-live child cannot share a replacement's port.
    if (entry.state.port !== null) reserved.delete(entry.state.port);
    if (entry.state.daemonPort !== null) reserved.delete(entry.state.daemonPort);
    entry.child = undefined;
    entry.state = { ...entry.state, status, pid: null, port: null, daemonPort: null, adminUrl: null };
  }
  function crash(entry: Entry) {
    entry.state.status = "crashed";
    entry.cancel?.();
    const child = entry.child;
    // A Stop queued ahead of this reaper may already have reaped this child: its "stopped" stands.
    void serial(async () => { if (entry.child === child) await reap(entry, "crashed"); }).catch(() => {});
  }
  function canProbe(entry: Entry) {
    return !closed && (entry.state.status === "starting" || entry.state.status === "running");
  }
  async function probe(entry: Entry) {
    const child = entry.child;
    if (!child || !canProbe(entry)) return;
    const ready = await childReady(child);
    if (entry.child !== child || !canProbe(entry)) return;
    if (recordProbe({ entry, ready, readyAttempts }) === "crash") crash(entry);
    else scheduleProbe(entry);
  }
  function scheduleProbe(entry: Entry) {
    entry.cancel = processPort.schedule({ run: () => { void probe(entry); }, delayMs: entry.state.status === "starting" ? 500 : 5000 });
  }
  async function start(name: string): Promise<LocalSiteState> {
    checkName(name);
    const current = currentState(name);
    if (current) return current;
    if ([...entries.values()].filter((entry) => entry.child || entry.state.status === "starting").length >= maxConcurrent) throw new LocalSiteError("SITE_LIMIT");
    const entry: Entry = { state: { name, status: "starting", pid: null, port: null, daemonPort: null, adminUrl: null }, probes: 0, misses: 0 };
    entries.set(name, entry);
    try {
      return await launch(entry);
    } catch (error) {
      await reap(entry, "crashed");
      const foreign = processPort.existing?.({ name });
      if (foreign) return foreign;
      if (error instanceof LocalSiteError) throw error;
      throw new LocalSiteError("SITE_START_FAILED");
    }
  }
  /** A site another app runs, or this host's own live child, answers Start without a new launch. */
  function currentState(name: string): LocalSiteState | undefined {
    const foreign = processPort.existing?.({ name });
    const previous = entries.get(name);
    if (foreign && !previous?.child) return foreign;
    if (!previous?.child) return undefined;
    if (previous.state.status === "crashed") throw new LocalSiteError("SITE_STOP_FAILED");
    return { ...previous.state };
  }
  async function launch(entry: Entry): Promise<LocalSiteState> {
    const { name } = entry.state;
    const port = await allocate();
    entry.state.port = port;
    const daemonPort = await allocate();
    entry.state.daemonPort = daemonPort;
    if (closed) throw new LocalSiteError("SITE_HOST_STOPPING");
    const child = await processPort.launch({ name, port, daemonPort });
    entry.child = child;
    entry.state.pid = child.pid;
    entry.state.adminUrl = `${scheme}://localhost:${port}/admin/`;
    child.onExit({ listener: () => { if (entries.get(name) === entry && entry.child && entry.state.status !== "stopped") crash(entry); } });
    if (closed) { await reap(entry, "stopped"); throw new LocalSiteError("SITE_HOST_STOPPING"); }
    scheduleProbe(entry);
    return { ...entry.state };
  }
  const supervisor: LocalSiteSupervisorPort = {
    start: ({ name }) => serial(() => start(name)),
    stop: ({ name }) => serial(async () => {
      checkName(name);
      const entry = entries.get(name);
      if (!entry?.child && processPort.existing?.({ name })) throw new LocalSiteError("SITE_RUNNING_ELSEWHERE");
      if (!entry) return { name, status: "stopped", pid: null, port: null, daemonPort: null, adminUrl: null };
      // Withdraw exit observation before signalling, so a deliberate stop never becomes a crash.
      entry.state.status = "stopped";
      try { await reap(entry, "stopped"); } catch (error) { entry.state.status = "crashed"; throw error; }
      return { ...entry.state };
    }),
    list: () => {
      const known = new Map([...entries.values()].map((entry) => [entry.state.name, { ...entry.state }]));
      for (const state of processPort.listExisting?.() ?? []) if (!entries.get(state.name)?.child) known.set(state.name, state);
      return [...known.values()];
    },
    withStoppedSite: ({ name, task }) => serial(async () => {
      checkName(name);
      const entry = entries.get(name);
      if (processPort.existing?.({ name }) || entry?.child || entry?.state.status === "starting") throw new LocalSiteError("SITE_RUNNING");
      return task();
    }),
    killNow() { closed = true; for (const entry of entries.values()) { entry.cancel?.(); entry.state.status = "stopped"; entry.child?.killNow(); } },
    shutdown() {
      supervisor.killNow();
      return serial(async () => {
        await Promise.all([...entries.values()].map((entry) => reap(entry, "stopped")));
        await processPort.dispose?.();
      });
    },
  };
  return supervisor;
}

/** Readiness failures are bounded local misses, never a crash on their own. */
async function childReady(child: LocalSiteProcess): Promise<boolean> {
  try { return await child.ready(); } catch { /* Retry bounded local readiness failures. */ return false; }
}

/** Count one probe and decide whether the site has timed out starting or lost a running server.
 * @returns "crash" after `readyAttempts` unready probes while starting or three misses while running.
 */
function recordProbe({ entry, ready, readyAttempts }: { entry: Entry; ready: boolean; readyAttempts: number }): "crash" | "again" {
  entry.probes++;
  if (ready) { entry.state.status = "running"; entry.misses = 0; }
  else entry.misses++;
  if (entry.state.status === "starting" && entry.probes >= readyAttempts) return "crash";
  if (entry.state.status === "running" && entry.misses >= 3) return "crash";
  return "again";
}

/** Start a site and wait until its server answers, so a caller that hands out `adminUrl` (site import's
 * "Open" link) never links to a port that is still booting. Returns the latest state once it leaves
 * `starting`, or the still-starting state after `attempts` waits (callers stay under the admin
 * client's 60 s request timeout; the supervisor keeps probing either way).
 * @complexity O(attempts × s) — one bounded `list()` scan per wait.
 */
export async function startLocalSiteWhenRunning(
  { supervisor, name }: { supervisor: Pick<LocalSiteSupervisorPort, "start" | "list">; name: string },
  { attempts = 90, intervalMs = 500, sleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms)) }: { attempts?: number; intervalMs?: number; sleep?: (ms: number) => Promise<void> } = {},
): Promise<LocalSiteState> {
  let state = await supervisor.start({ name });
  for (let waits = 0; state.status === "starting" && waits < attempts; waits++) {
    await sleep(intervalMs);
    state = supervisor.list().find((entry) => entry.name === name) ?? state;
  }
  return state;
}

/** Stopped-site CLI owner, reused by automatic desktop startup relocation. Dry-run performs no stop, mkdir, lock cleanup, registry write or move. */
import fs from "node:fs";
import path from "node:path";
import Database from "better-sqlite3";
import { verifySqliteIntegrity } from "@jini-ai/db/sqlite";
import { checkpointStoppedSqliteWal } from "../db/kernel/checkpoint-stopped-wal.js";
import { resolveSiteDatabasePaths } from "./site-databases.js";
import { withFileLock, moveDirectoryVerified } from "@jini-ai/platform/fs";
import { createSitesWorkspace, type SitesWorkspace } from "./sites-home.js";
import { readSiteDir } from "./read-site-dir.js";
import { sitesProjectReferences } from "./sites-project-references.js";
import type { DirectoryRunningRecord } from "@jini-ai/platform/fs";
import { assertLocalSiteName } from "./local-site-supervisor.js";
import { ValidationError } from "./errors.js";

export interface MovePlan { from: string; to: string; id: string; name: string; running: DirectoryRunningRecord | null;
  databases: { from: string; to: string }[];
}
export interface SitesMovePorts {
  workspace: SitesWorkspace;
  /** Kept for source compatibility; running sites are now always refused, never stopped. */
  stop(required: { dir: string; running: DirectoryRunningRecord }): Promise<void>;
  relocateDirectory: typeof moveDirectoryVerified;
  verifyDatabase(required: { path: string }): string;
}
/** Selection/reporting for legacy discovery; an absent or empty selection includes all sites. */
interface SitesMovePlanOptions {
  workspace?: SitesWorkspace;
  sites?: readonly string[];
  onSkipped?: (required: { dir: string }) => void;
  onRunning?: (required: { dir: string; running: DirectoryRunningRecord }) => void;
  /** Explicit roots select one validated site from the released nested default. */
  sourceRoots?: readonly string[];
  projectsPaths?: readonly string[];

}
/** Inspect validated immediate children in the released nested default. Symlinked roots/sites and target collisions
 * are refused. No valid metadata is guessed for a legacy folder; initialize/repair it first.
 * Dot-folders and folders without both markers are reported through onSkipped, without validation.
 * @param options.sites - Optional checkout folder names to include, rather than display names.
 * @returns Move plans for selected sites; reads files only and preserves all real-site errors.
 * @example planSitesMove({ repoRoot }, { sites: ["tovu-dev"] });
 * @complexity O(n + s) directory/selection work and O(n) plan storage for n children, s selections,
 * plus the existing per-site metadata/catalog reads.
 */
export function planSitesMove({ repoRoot }: { repoRoot: string }, { workspace = createSitesWorkspace({}, { cwd: repoRoot, catalogRecovery: false }), sites, onSkipped, sourceRoots }: SitesMovePlanOptions = {}): MovePlan[] {
  const home = workspace.home({});
  const nestedRoot = workspace.nestedSitesRoot({});
  const formerRoots = nestedRoot ? [nestedRoot] : [];
  const selectedNames = new Set(sites);
  return [...new Set(sourceRoots ?? formerRoots)].flatMap((candidate) => {
    const root = openSourceRoot({ candidate, formerRoots, repoRoot, home });
    return root ? planRootMoves({ root, home, workspace, selectedNames }, { onSkipped }) : [];
  });
}

/** Validate one source root before any of its children are read.
 * @returns The real root, or undefined when it is absent or already is the sites home.
 * @throws A root outside the former default, a symlinked root, or a checkout root holding the home.
 * @complexity O(1) filesystem probes.
 */
function openSourceRoot({ candidate, formerRoots, repoRoot, home }: { candidate: string; formerRoots: readonly string[]; repoRoot: string; home: string }): string | undefined {
  // Relocate within the implicit Documents home family only: local ~/Tovu sites must never be silently
  // transferred into synced Documents. Checkout compatibility roots remain discovery sources.
  if (!formerRoots.includes(path.resolve(candidate))) throw new Error("Only sites inside the former default sites/ folder can be moved to Documents/Tovu.");
  if (!fs.existsSync(candidate)) return undefined;
  if (fs.lstatSync(candidate).isSymbolicLink()) throw new Error("The source sites folder must not be a symlink.");
  const root = fs.realpathSync(candidate);
  if (path.resolve(candidate) === path.join(repoRoot, "sites") && (home === root || home.startsWith(root + path.sep))) throw new Error("Sites home must be outside the checkout sites folder.");
  return home === root ? undefined : root;
}

/** Plan every selected site folder directly inside one validated root, reporting non-site folders.
 * @complexity O(n) children of the root plus each selected site's metadata/catalog reads.
 */
function planRootMoves({ root, home, workspace, selectedNames }: { root: string; home: string; workspace: SitesWorkspace; selectedNames: ReadonlySet<string> }, { onSkipped }: Pick<SitesMovePlanOptions, "onSkipped"> = {}): MovePlan[] {
  const plans: MovePlan[] = [];
  for (const entry of fs.readdirSync(root, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    const from = path.join(root, entry.name);
    if (!isSiteFolder({ name: entry.name, dir: from })) onSkipped?.({ dir: from });
    else if (isSelected({ name: entry.name, selectedNames })) plans.push(planSiteMove({ from, to: path.join(home, entry.name), workspace }));
  }
  return plans;
}

/** A site folder is visible (no dot prefix) and carries both site markers. */
function isSiteFolder({ name, dir }: { name: string; dir: string }): boolean {
  return !name.startsWith(".") && fs.existsSync(path.join(dir, "config.json")) && fs.existsSync(path.join(dir, ".site-meta.json"));
}

/** An absent or empty selection includes all sites. */
function isSelected({ name, selectedNames }: { name: string; selectedNames: ReadonlySet<string> }): boolean {
  return selectedNames.size === 0 || selectedNames.has(name);
}

/** Read one site's identity and plan its folder and database moves without writing anything.
 * @throws Invalid metadata, a target collision, or a database that cannot move safely.
 */
function planSiteMove({ from, to, workspace }: { from: string; to: string; workspace: SitesWorkspace }): MovePlan {
  const { meta, config } = readSiteDir({ dir: from });
  assertMoveTargetAbsent({ to });
  const databases = planDatabaseMoves({ from, to, siteId: meta.siteId, workspace });
  return { from, to, id: meta.siteId, name: config.name, databases, running: workspace.running({ path: from }).peek({}) };
}

/** Refuse any existing entry at the target, even a dangling symlink; other probe errors propagate. */
function assertMoveTargetAbsent({ to }: { to: string }): void {
  try { fs.lstatSync(to); }
  catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return;
    throw error;
  }
  throw new Error(`Move target already exists: ${to}`);
}

/** Pair each existing database with its destination under the configured placement.
 * @throws App-data placement inside the moved site, a non-file database/sidecar, or a target collision.
 * @complexity O(1): two databases with three files each.
 */
function planDatabaseMoves({ from, to, siteId, workspace }: { from: string; to: string; siteId: string; workspace: SitesWorkspace }): MovePlan["databases"] {
  const existing = resolveSiteDatabasePaths({ dir: from, siteId }, { workspace, reserveIdentity: false });
  const placement = workspace.config({}).databases;
  const selected = resolveSiteDatabasePaths({ dir: to, siteId }, { workspace, placement });
  if (selected.contentDbPath.startsWith(from + path.sep)) throw new Error("App-data databases must be outside the site being moved.");
  const databases = [{ from: existing.contentDbPath, to: selected.contentDbPath }, { from: existing.chatDbPath, to: selected.chatDbPath }]
    .filter((db) => fs.existsSync(db.from)).map((db) => ({ ...db,
      // Existing in-site placement wins: a folder rename carries the DB atomically, so a
      // folder-level move needs neither a new DB copy nor a second backup of those same bytes.
      to: placement === "inSite" && db.from.startsWith(from + path.sep) ? path.join(to, path.relative(from, db.from)) : db.to,
    }));
  for (const db of databases) assertDatabaseMovable({ db });
  return databases;
}

/** Each database file and sidecar must be a regular file, and a relocated one must not overwrite anything. */
function assertDatabaseMovable({ db }: { db: { from: string; to: string } }): void {
  for (const suffix of ["", "-wal", "-shm"]) {
    if (fs.existsSync(db.from + suffix) && !fs.lstatSync(db.from + suffix).isFile()) throw new Error(`Database move requires a regular file: ${db.from + suffix}`);
    if (db.from !== db.to && fs.existsSync(db.to + suffix)) throw new Error(`Database move target already exists: ${db.to + suffix}`);
  }
}

/** Require the site stopped, reserve both identities against boots, then verify and commit.
 * A crashed apply retains a verified destination or the original; it never silently overwrites.
 * @param options.sites - Optional checkout folder names, retained across every locked re-plan.
 * @returns Dry-run plans or only successfully moved sites; dry runs only read, apply moves folders/databases and updates the registry.
 * @throws Existing validation, collision, running-site and database-integrity errors.
 * @example await moveSitesHome({ repoRoot }, { sites: ["tovu-dev"] });
 * @complexity O(total site bytes + SQLite verification), plus registry I/O.
 */
export async function moveSitesHome(
  { repoRoot }: { repoRoot: string }, { apply = false, workspace = createSitesWorkspace({}, { cwd: repoRoot, catalogRecovery: false }), verifyDatabase = inspectStoppedDatabase, relocateDirectory = moveDirectoryVerified, sites, onSkipped, onRunning = warnRunning, sourceRoots, projectsPaths }: Partial<SitesMovePorts> & SitesMovePlanOptions & { apply?: boolean } = {},
): Promise<MovePlan[]> {
  const plans = planSitesMove({ repoRoot }, { workspace, sites, onSkipped, sourceRoots });
  if (!apply) return plans;
  const home = workspace.home({});
  // Lock parents can create directories too; refuse an absent volume before acquiring any lane.
  if (!workspace.homeAvailable({})) throw new Error(`Sites home volume is unavailable: ${home}. Mount it or choose a local folder in Sites settings.`);
  const replan = () => planSitesMove({ repoRoot }, { workspace, sites, sourceRoots });
  const moved: MovePlan[] = [];
  await withFileLock({ lockPath: `${home}.move.lock`, run: async () => {
    // Running sites are refused individually; stopped siblings can move without forcing a stop.
    // Journal/exclusive-lock admission still precedes every byte copied for stopped sites.
    admitStoppedSites({ plans: replan() }, { onRunning });
    // Re-plan after obtaining the migration lane: another apply may have completed while waiting.
    for (const plan of replan().filter((candidate) => !candidate.running)) {
      await moveOneSite({ plan, workspace }, { relocateDirectory, verifyDatabase, projectsPaths });
      moved.push(plan);
    }
  } }, { createParent: true, staleMs: Infinity });
  return moved;
}

/** Default running-site report for the CLI and desktop callers. */
function warnRunning({ dir, running }: { dir: string; running: DirectoryRunningRecord }): void {
  console.warn(`Skipped running site in ${running.app}: ${dir}. Stop it before moving it.`);
}

/** Report each running site, prove every stopped site's databases closed, and refuse a batch with only running sites.
 * @throws The first site's running error when every planned site is running, or a database admission error.
 * @complexity O(p) plans plus one exclusive probe per stopped database.
 */
function admitStoppedSites({ plans }: { plans: readonly MovePlan[] }, { onRunning }: { onRunning: NonNullable<SitesMovePlanOptions["onRunning"]> }): void {
  for (const plan of plans) {
    if (plan.running) onRunning({ dir: plan.from, running: plan.running });
    else for (const db of plan.databases) assertDatabaseStopped({ path: db.from });
  }
  const [first] = plans;
  if (first?.running && plans.every((plan) => plan.running)) throw new Error(`Site is running in ${first.running.app}: ${first.from}. Stop it before moving it.`);
}

/** Move one stopped site under its target creation lock while both identities are reserved.
 * @throws A site or target claimed by another app, a database admission error, or a failed verified move.
 * @complexity The site's bytes plus SQLite verification and catalog I/O.
 */
async function moveOneSite({ plan, workspace }: { plan: MovePlan; workspace: SitesWorkspace }, ports: SiteRelocationPorts): Promise<void> {
  await withFileLock({ lockPath: `${plan.to}.creation.lock`, run: async () => {
    const live = workspace.running({ path: plan.from }).peek({});
    if (live) throw new Error(`Site is running in ${live.app}: ${plan.from}. Stop it before moving it.`);
    for (const db of plan.databases) assertDatabaseStopped({ path: db.from });
    const reservation = workspace.claim({ path: plan.from, app: "Migration" });
    if (!reservation.acquired) throw new Error(`Another app started this site: ${plan.from}`);
    let targetToken: string | undefined;
    try {
      const targetReservation = workspace.claim({ path: plan.to, app: "Migration" });
      if (!targetReservation.acquired) throw new Error(`Another app started the move target: ${plan.to}`);
      targetToken = targetReservation.record.token;
      fs.mkdirSync(workspace.home({}), { recursive: true });
      relocateSite({ plan, workspace }, ports);
    } finally {
      // Release at the new path only after the move, so cleanup never recreates the source.
      // Leases now live in app-data, so release both identities even after the source moves.
      workspace.running({ path: plan.from }).release({ token: reservation.record.token });
      if (targetToken) workspace.running({ path: plan.to }).release({ token: targetToken });
    }
  } }, { createParent: true, staleMs: Infinity });
}

type SiteRelocationPorts = Pick<SitesMovePorts, "relocateDirectory" | "verifyDatabase"> & Pick<SitesMovePlanOptions, "projectsPaths">;

/** Verified folder move whose commit re-checks identity and updates the registry and desktop catalogs. */
function relocateSite({ plan, workspace }: { plan: MovePlan; workspace: SitesWorkspace }, { relocateDirectory, verifyDatabase, projectsPaths }: SiteRelocationPorts): void {
  relocateDirectory({ from: plan.from, to: plan.to, commit: () => {
    const verified = readSiteDir({ dir: plan.to });
    if (verified.meta.siteId !== plan.id) throw new Error("Moved site's identity did not match.");
    workspace.relocate({ from: plan.from, to: plan.to,
      entry: { id: plan.id, name: plan.name, path: plan.from, createdBy: "migrated", lastOpened: null },
      references: sitesProjectReferences({ workspace, from: plan.from, to: plan.to }, { projectsPaths }),
    });
  } }, { excluded: [".tovu-running.json", ".tovu-running.json.lock"],
    relocateFiles: ({ target }) => plan.databases.map((db) => ({
      from: db.from.startsWith(plan.from + path.sep) ? path.join(target, path.relative(plan.from, db.from)) : db.from,
      to: db.to, sidecars: ["-wal", "-shm"],
    })), verifyFile: verifyDatabase,
  });
}
/** Released hosts have no lease. SQLite's exclusive lock is the admission proof. Never copy a live SQLite inode.
 * A WAL/SHM that survives while this probe holds that lock was left by an unclean stop (no process has the DB):
 * its committed frames are checkpointed into the main file, exactly as the site's next open would, and the
 * stale SHM is removed under the lock; close deletes the emptied WAL. Any journal still present afterwards refuses.
 * @complexity O(1) probes per DB, plus one checkpoint of a leftover WAL; no rows are read.
 */
export function assertDatabaseStopped({ path: file }: { path: string }, _options = {}): void {
  const db = new Database(file, { fileMustExist: true, timeout: 0 });
  try {
    // EXCLUSIVE locking mode keeps the lock until close and uses a heap wal-index, never the stale SHM.
    db.exec("PRAGMA locking_mode=EXCLUSIVE; BEGIN EXCLUSIVE; ROLLBACK;");
    checkpointStoppedSqliteWal({ db, path: file });
    fs.rmSync(file + "-shm", { force: true });
  } catch (error) {
    if ((error as { code?: string }).code?.startsWith("SQLITE_BUSY")) throw new Error(`Database is open in another process: ${file}. Stop it before moving it.`);
    throw error;
  } finally { db.close(); }
  for (const suffix of ["-wal", "-shm"]) {
    if (fs.existsSync(file + suffix)) throw new Error(`Database journal exists: ${file + suffix}. Stop the site and close/checkpoint its database before moving it.`);
  }
}
/** Read-only verification of every user table plus SQLite's full integrity check through Jini's
 * existing SQLite inspector. It now supports strict counts; its diagnostics mode still reports
 * partial results. No process is signalled: a recycled PID is not permission to stop another app.
 * Row counts include tables with unusual quoted names and distinguish identical totals per table.
 * @param options.verifyIntegrity - Integrity/row-count inspector; defaults to Jini's SQLite inspector.
 * @complexity O(database pages + all table rows), one stopped connection per verification.
 */
export function inspectStoppedDatabase({ path: file }: { path: string }, { verifyIntegrity = verifySqliteIntegrity }: { verifyIntegrity?: typeof verifySqliteIntegrity } = {}): string {
  // SQLite can create WAL/SHM even for a readonly connection. Remember exactly what existed;
  // only this inspection's artifacts may be removed, never a pre-existing journal.
  const absentSidecars = ["-wal", "-shm"].map((suffix) => file + suffix).filter((sidecar) => !fs.existsSync(sidecar));
  let db: Database.Database | undefined;
  try {
    db = new Database(file, { readonly: true, fileMustExist: true });
    const checked = verifyIntegrity({ db }, { includeRowCounts: true });
    if (!checked.ok) throw new Error(`SQLite integrity_check failed for ${path.basename(file)}: ${checked.issues.map((issue) => issue.message).join('; ')}`);
    if (!checked.rowCounts) throw new Error("Build @jini-ai/db before running the stopped-site database mover.");
    return JSON.stringify(checked.rowCounts);
  } finally {
    try { db?.close(); }
    finally { for (const sidecar of absentSidecars) fs.rmSync(sidecar, { force: true }); }
  }
}

/** Move one selected nested-default site through the existing stopped/verified mover.
 * Callers resolve the directory from their catalog; this boundary rejects arbitrary source roots.
 * @returns The verified destination; throws on a running site, missing marker or collision.
 * @example await moveLegacySite({ dir }, { workspace });
 * @complexity The selected site's bytes plus SQLite verification and catalog I/O.
 */
export async function moveLegacySite({ dir }: { dir: string }, { workspace = createSitesWorkspace({}), projectsPaths, repoRoot = process.cwd() }: {
  workspace?: SitesWorkspace; projectsPaths?: readonly string[]; repoRoot?: string;
} = {}): Promise<string> {
  if (fs.lstatSync(dir).isSymbolicLink()) throw new Error("The source site must not be a symlink.");
  const from = fs.realpathSync(dir), root = path.dirname(from);
  if (root !== workspace.nestedSitesRoot({})) throw new Error("Only sites inside the former default sites/ folder can be moved to Documents/Tovu.");
  const moved = await moveSitesHome({ repoRoot }, { apply: true, workspace, sites: [path.basename(from)], sourceRoots: [root], projectsPaths });
  if (moved.length !== 1) throw new Error("No site matched this move. Check its folder and the default Documents/Tovu home.");
  return moved[0]!.to;
}

/** Rename a direct child of the configured sites home, preserving display name and identity.
 * Uses the stopped-site mover, including leases, DB checks, verified rollback and Jini's
 * registry relocate transaction. Filesystem/planning/move ports permit tests without home I/O.
 * @returns The old/new folder paths after the verified move commits.
 * @throws Invalid names, unsafe source, existing target, live owner or relocation failure.
 * @example await renameSiteFolder({ oldName: "old-site", newName: "new-site" });
 * @complexity O(site bytes + SQLite verification + catalog/reference bytes), via the mover.
 */
export async function renameSiteFolder(
  { oldName, newName }: { oldName: string; newName: string },
  { workspace: suppliedWorkspace, filesystem = fs, planMove = planSiteMove, moveSite = moveOneSite }: {
    workspace?: SitesWorkspace;
    filesystem?: Pick<typeof fs, "lstatSync" | "realpathSync">;
    planMove?: typeof planSiteMove;
    moveSite?: typeof moveOneSite;
  } = {},
): Promise<{ from: string; to: string }> {
  assertLocalSiteName({ name: oldName });
  assertLocalSiteName({ name: newName });
  // Windows device names are invalid directories even when the command runs on another OS.
  if (/^(con|prn|aux|nul|com[1-9]|lpt[1-9])$/i.test(newName)) throw new ValidationError("Site folder name is reserved on Windows.");
  const workspace = suppliedWorkspace ?? createSitesWorkspace({});
  const home = filesystem.realpathSync(workspace.home({}));
  const from = path.join(home, oldName), to = path.join(home, newName);
  if (!filesystem.lstatSync(from).isDirectory()) throw new ValidationError("The source site must be a real directory, not a symlink.");
  const plan = planMove({ from, to, workspace });
  if (plan.running) throw new Error(`Site is running in ${plan.running.app}: ${from}. Stop it before renaming it.`);
  await moveSite({ plan, workspace }, { relocateDirectory: moveDirectoryVerified, verifyDatabase: inspectStoppedDatabase });
  return { from, to };
}

import fs, { constants } from "node:fs";
import path from "node:path";
import { createHash, randomUUID } from "node:crypto";
import type { RawFilePort, RawFileSnapshot } from "#src/features/publish-content/backstop-ports";
import { checkRawFilePath, BACKSTOP_LIMITS } from "#src/features/publish-content/backstop-policy";
import { normalizeMode } from "#src/features/publish-content/file-tree-policy";

function missing(error: unknown): boolean { return (error as { code?: string })?.code === "ENOENT"; }
function sha(bytes: Uint8Array): string { return createHash("sha256").update(bytes).digest("hex"); }

const LINK_REFUSAL = "Links are never sent; choose a regular file inside the site folder.";
const NOT_REGULAR_REFUSAL = "Choose a regular file inside the site folder.";

/** The `node:fs` calls this adapter makes, injectable so fault paths are testable without races. */
export type BackstopFilesystem = Pick<typeof fs, "lstatSync" | "mkdirSync" | "openSync" | "closeSync" | "readFileSync" | "writeFileSync" | "renameSync" | "unlinkSync" | "chmodSync">;

/** lstat that reports an absent path as null; every other failure propagates. */
function lstatOrNull({ file }: { file: string }, { filesystem }: { filesystem: BackstopFilesystem }): fs.Stats | null {
  try { return filesystem.lstatSync(file); } catch (error) { if (missing(error)) return null; throw error; }
}

/** Walk each component below the root without following links. An absent component means the
 * file is new, which is safe. @complexity O(c) lstat calls for c path components.
 */
function componentsRefusal({ root, parts }: { root: string; parts: readonly string[] }, { filesystem }: { filesystem: BackstopFilesystem }): string | null {
  let current = root;
  for (const [index, part] of parts.entries()) {
    current = path.join(current, part);
    const stat = lstatOrNull({ file: current }, { filesystem });
    if (!stat) return null;
    if (stat.isSymbolicLink()) return LINK_REFUSAL;
    if (index < parts.length - 1 ? !stat.isDirectory() : !stat.isFile()) return NOT_REGULAR_REFUSAL;
  }
  return null;
}

/** Single CMS site-file adapter. lstat every component, never follow a link; stage on the same
 * filesystem and rename only verified regular bytes. Previous files stay in a private folder for
 * one-click undo, rather than relying on the whole-db restore/restart path.
 * @param options.filesystem - The `node:fs` calls used; defaults to Node's.
 */
export function createRawFileSitePort({ siteDir }: { siteDir: string }, { filesystem = fs }: { filesystem?: BackstopFilesystem } = {}): RawFilePort {
  const { lstatSync, mkdirSync, openSync, closeSync, readFileSync, writeFileSync, renameSync, unlinkSync, chmodSync } = filesystem;
  const root = path.resolve(siteDir);
  function check(relPath: string): string | null {
    const denied = checkRawFilePath({ relPath });
    if (denied) return denied;
    try {
      // lstat never follows a link: a linked site folder is not a directory here.
      if (!lstatSync(root).isDirectory()) return "The site folder must be a real directory, never a link.";
      return componentsRefusal({ root, parts: relPath.split("/") }, { filesystem });
    } catch (error) { return missing(error) ? "The site folder is unavailable." : "This file cannot be inspected safely."; }
  }
  function target(relPath: string): string {
    const reason = check(relPath);
    if (reason) throw new Error(reason);
    return path.join(root, ...relPath.split("/"));
  }
  function read(relPath: string): RawFileSnapshot | null {
    const filename = target(relPath);
    let fd: number;
    try { fd = openSync(filename, constants.O_RDONLY | constants.O_NOFOLLOW); } catch (error) { if (missing(error)) return null; throw error; }
    try {
      const stat = lstatSync(filename);
      if (stat.size > BACKSTOP_LIMITS.bytes) throw new Error("Choose files totaling at most 50 MB per send.");
      return { absPath: filename, bytes: readFileSync(fd), mode: normalizeMode(stat.mode) };
    } finally { closeSync(fd); }
  }
  function privateDir(name: ".publish-staging" | ".publish-previous"): string {
    const dir = path.join(root, name);
    // lstat never follows a link, so a linked folder fails isDirectory() too.
    const stat = lstatOrNull({ file: dir }, { filesystem });
    if (!stat) mkdirSync(dir, { mode: 0o700 });
    else if (!stat.isDirectory()) throw new Error("The publish staging folder is not a safe directory.");
    chmodSync(dir, 0o700);
    return dir;
  }
  function parents(relPath: string): void {
    let current = root;
    for (const part of relPath.split("/").slice(0, -1)) {
      current = path.join(current, part);
      const stat = lstatOrNull({ file: current }, { filesystem });
      if (!stat) mkdirSync(current, { mode: 0o755 });
      else if (!stat.isDirectory()) throw new Error(LINK_REFUSAL);
    }
  }
  /** A backup's bytes, or `null` when it is gone. Never follows a link. */
  function readBackup(backup: string): Buffer | null {
    let fd: number;
    try { fd = openSync(backup, constants.O_RDONLY | constants.O_NOFOLLOW); } catch (error) { if (missing(error)) return null; throw error; }
    try { return readFileSync(fd); } finally { closeSync(fd); }
  }
  function alreadyRestored(inverse: { relPath: string; sha256: string | null }): boolean {
    const current = read(inverse.relPath);
    return current !== null && sha(current.bytes) === inverse.sha256;
  }
  function removeCreatedFile({ relPath }: { relPath: string }, _optional = {}): void {
    try { unlinkSync(target(relPath)); } catch (error) { if (!missing(error)) throw error; }
  }
  function replace(relPath: string, bytes: Uint8Array, mode: number): void {
    target(relPath);
    if (bytes.byteLength > BACKSTOP_LIMITS.bytes) throw new Error("Choose files totaling at most 50 MB per send.");
    const stage = path.join(privateDir(".publish-staging"), randomUUID());
    try {
      writeFileSync(stage, bytes, { mode: normalizeMode(mode), flag: "wx" });
      // The process umask must not change the normalized mode included in the checked hash.
      chmodSync(stage, normalizeMode(mode));
      if (sha(readFileSync(stage)) !== sha(bytes)) throw new Error("The staged file failed its checksum check.");
      parents(relPath);
      renameSync(stage, target(relPath));
    } finally {
      try { unlinkSync(stage); } catch (error) { if (!missing(error)) throw error; }
    }
  }
  return {
    check: async ({ relPath }) => check(relPath),
    read: async ({ relPath }) => read(relPath),
    capture: async ({ relPath }) => {
      const prior = read(relPath);
      if (!prior) return { relPath, backupName: null, sha256: null, size: null, mode: 0o644 };
      const backupName = randomUUID();
      writeFileSync(path.join(privateDir(".publish-previous"), backupName), prior.bytes, { mode: 0o600, flag: "wx" });
      return { relPath, backupName, sha256: sha(prior.bytes), size: prior.bytes.byteLength, mode: prior.mode };
    },
    replace: async ({ relPath, bytes, mode }) => replace(relPath, bytes, mode),
    restore: async ({ inverse }) => {
      if (inverse.backupName === null) {
        removeCreatedFile({ relPath: inverse.relPath });
        return;
      }
      if (!/^[a-f0-9-]{36}$/.test(inverse.backupName)) throw new Error("The saved undo file has an unsafe address.");
      const backup = path.join(privateDir(".publish-previous"), inverse.backupName);
      const bytes = readBackup(backup);
      // A repeated undo finds its copy already reclaimed below: done when the file holds those bytes.
      if (bytes === null && alreadyRestored(inverse)) return;
      if (bytes === null) throw new Error("The saved undo file is missing.");
      if (sha(bytes) !== inverse.sha256) throw new Error("The saved undo file failed its checksum check.");
      replace(inverse.relPath, bytes, inverse.mode);
      // The undo is spent and nothing else reads this copy; kept, every overwrite would leave up to
      // 50 MB behind for good.
      try { unlinkSync(backup); } catch (error) { if (!missing(error)) throw error; }
    },
  };
}

import { resolveSiteDatabasePaths } from "./site-databases.js";
import { existsSync } from "node:fs";
import { join } from "node:path";

import { findKeyDependentData, scanOpenedKernel } from "../db/key-dependent-data.js";
import { openPgliteKernel } from "../db/kernel/drivers/pglite.js";
import { acquireOwnerLock } from "../db/kernel/drivers/pglite-owner.js";
import { openPostgresKernel } from "../db/kernel/drivers/postgres.js";
import { PGLITE_DATA_DIR_NAME, STORAGE_SECRET_FILENAME } from "./layout.js";
import { resolveSiteStorage } from "./site-storage.js";
import type { SiteStorage } from "./types.js";

/**
 * @file "Does this site hold data only its current site key can open?" for a whole site folder, on
 * every storage kind (ADR-067). `ensureSiteKey` (injected by the boot callers) refuses to mint or
 * adopt a key over such data, and the admin site key route reports `"missing-with-data"` from it.
 * A PGlite or Postgres site has no `content.db`, so scanning that file alone saw "no data" there.
 */

/**
 * Whether the site in `siteDir` holds key-dependent data, on whichever storage its
 * `.site-meta.json` names. Runs before the site's store is opened (boot), so it opens the store
 * itself and closes it again; the rows are only read.
 *
 * - `.storage-secret.json` present: yes — the Postgres connection string is sealed with the key.
 * - SQLite: this site's `content.db` (`findKeyDependentData`); no file yet is "no data".
 * - PGlite: `<site>/pglite/`, opened in-process under the data dir's owner lock (only one process
 *   may open it). No database there yet is "no data".
 * - Postgres: the database the `secretRef.env` variable names.
 *
 * Fails closed: an unreadable meta file, a PGlite data dir another process owns, a Postgres site
 * whose connection string cannot be read, or any open/query failure counts as "has data" — a key
 * minted over a store nobody inspected could orphan sealed rows.
 *
 * @complexity O(1) file checks plus one store open and `hasKeyDependentData`'s cost.
 */
export async function findSiteKeyDependentData(siteDir: string, optional: { env?: NodeJS.ProcessEnv } = {}): Promise<boolean> {
  if (existsSync(join(siteDir, STORAGE_SECRET_FILENAME))) return true;
  let storage: SiteStorage;
  try {
    storage = resolveSiteStorage(siteDir);
  } catch {
    return true;
  }
  switch (storage.kind) {
    case "sqlite": {
      const contentDbPath = resolveSiteDatabasePaths({ dir: siteDir }).contentDbPath;
      return existsSync(contentDbPath) ? findKeyDependentData([contentDbPath]) : false;
    }
    case "pglite":
      return pgliteHasKeyDependentData(join(siteDir, PGLITE_DATA_DIR_NAME));
    case "postgres":
      return postgresHasKeyDependentData(storage, optional.env ?? process.env);
  }
}

/** `PG_VERSION` is written by initdb: without it there is no database in the dir, and opening one would create it. */
async function pgliteHasKeyDependentData(dataDir: string): Promise<boolean> {
  if (!existsSync(join(dataDir, "PG_VERSION"))) return false;
  let releaseLock: () => void;
  try {
    releaseLock = acquireOwnerLock(dataDir);
  } catch {
    return true;
  }
  try {
    return await scanOpenedKernel(() => openPgliteKernel<unknown>({ dataDir }));
  } finally {
    releaseLock();
  }
}

/** `secretRef: "site"` with no `.storage-secret.json` (checked by the caller) has nothing to connect with. */
async function postgresHasKeyDependentData(storage: Extract<SiteStorage, { kind: "postgres" }>, env: NodeJS.ProcessEnv): Promise<boolean> {
  if (storage.secretRef === "site") return true;
  const connectionString = env[storage.secretRef.env];
  if (connectionString === undefined || connectionString.trim() === "") return true;
  return scanOpenedKernel(() => openPostgresKernel<unknown>({ connectionString, max: 1 }));
}

import fs from "node:fs";
import { withFileLock, type DirectoryRecord, type DirectoryRunningRecord } from "@jini-ai/platform/fs";
import path from "node:path";

import { ValidationError, InitDirNotEmptyError } from "./errors.js";
import type { InitSitePort, InitSiteResult, InitSiteRestorePort } from "./init-site.js";
import { resolveSiteDatabasePaths } from "./site-databases.js";
import { readSiteDir } from "./read-site-dir.js";
import { resolveSiteRoot, SITE_SELECTION_PINNED_ENV, type ResolveSiteRootOptional } from "./site-root.js";
import { createSitesWorkspace, type SitesWorkspace } from "./sites-home.js";
import { readSiteRunning } from "./site-running.js";
import { isSiteSwitcherEnabled } from "./site-switcher-enabled.js";
import { resolveRuntimeMode } from "#src/contracts/core/runtime-mode";

/**
 * @file Admin "Sites" screen backend, list + create half (2026-09-04 sites-switcher decision,
 * `ADS-memory/reports/2026-09-04-sites-switcher-decision.md`).
 *
 * Historical rationale (before the 2026-10-09 shared-home registry): `sites/<name>/` had always been a pure filesystem convention — no registry file, no DB table
 * (confirmed: `sites/README.md`, no code anywhere builds a "which sites exist" list before this).
 * `listSites` is the first thing that enumerates it, and it does so by directory scan plus the
 * SAME `readSiteDir` validator `serve` already trusts, rather than inventing a second notion of
 * "what makes a directory a site."
 *
 * `createSite` is a thin wrapper over `initSite` — the exact function `tovu init <dir>` calls —
 * so a site created here and one created by the CLI are byte-identical (same template, same seed,
 * same `.site-meta.json` commit-marker discipline, INV-02). Nothing here duplicates that logic.
 *
 * Deliberately read-only with respect to boot state: neither function here touches
 * `resolveSiteRoot`'s `TOVU_SITE_DIR`/`TOVU_SITE` precedence, the running process's own binding,
 * or any already-open `content.db` handle. `listSites`'s `active` flag is a fresh, read-only
 * re-derivation of `resolveSiteRoot()`, computed fresh on every call (never cached), so it always
 * reflects whatever this process actually booted with. See `active-site.ts` for the one function
 * in this feature slice that DOES write boot-relevant state — and even that one only writes a
 * file a FUTURE boot reads, never anything the live process consults.
 *
 * Today the shared catalog owns discovery across apps and arbitrary adopted folders; checkout
 * scanning remains a compatibility source. Creation targets the configured home.
 *
 * Architectural role: `site-dir` domain logic (INV-06) — no `express`/`cli` import, so a future
 * non-CLI caller (the desktop host, ADR-011) can reuse this directly, same as every sibling module
 * in this directory.
 */

/**
 * Site-folder-name format: lowercase letters, digits, dashes only. Deliberately narrower than
 * `initSite`'s own free-text `--name` (a display name, 1..200 chars, no format constraint) —
 * THIS value doubles as a path segment (`path.join(sitesRoot, name)`), so it must stay
 * filesystem- and URL-safe, and specifically must reject `.`, `/`, and empty segments so a
 * caller-supplied name can never resolve outside `sitesRoot` (no `..` is even expressible in this
 * character class). Mirrors `post.ts`'s `SLUG_FORMAT_PATTERN` shape for the same reason slugs use
 * it: a narrow, unambiguous, easy-to-audit charset.
 */
export const SITE_NAME_PATTERN = /^[a-z0-9-]+$/;
const MAX_SITE_NAME_LENGTH = 100;

export interface SiteListEntry {
  /** The folder name under `sites/` — also the stable identifier `activateSite`'s route takes. */
  name: string;
  /** Absolute path to `sites/<name>/`. */
  dir: string;
  /** `config.json.name` — the site's own display name (may differ from the folder name). */
  displayName: string;
  /** `.site-meta.json.createdAt`, from `initSite`'s own commit-marker write. */
  createdAt: string;
  /** True when `dir` is the site THIS process is currently bound to (`resolveSiteRoot()`), i.e.
   *  the one that would still be served by a request handled right now, not any pending choice a
   *  not-yet-actioned `activateSite` call may have persisted for the NEXT boot. */
  active: boolean;
  id?: string;
  running?: DirectoryRunningRecord | null;
}

export type ListSitesOptional = ResolveSiteRootOptional;

/**
 * Enumerate every real site under `<cwd>/sites/`. A directory counts as a site only once it
 * carries a valid `.site-meta.json` + `config.json` (init's own commit-marker discipline, INV-02),
 * so a partial/interrupted `initSite` never appears half-listed, and a stray non-site entry
 * (`.DS_Store`, a scratch folder, a future `out/`-style build artifact some site keeps beside
 * `sites/`) is silently skipped rather than surfaced as a corrupt site — this is a best-effort
 * discovery scan, not a validator whose job is to fail loudly on every stray file.
 *
 * @complexity O(n) in the number of entries directly under `sites/` — bounded by how many sites an
 *   operator has actually created, never by a single request's own input.
 */
export function listSites(optional: ListSitesOptional = {}): SiteListEntry[] {
  const workspace = createSitesWorkspace({}, optional);
  const currentSiteDir = resolveSiteRoot(optional);
  const registry = workspace.registry({});
  const sites: SiteListEntry[] = [];
  const discovered: DirectoryRecord[] = [];
  const usedNames = new Set<string>();
  const listedPaths = new Set<string>();
  for (const candidate of candidateSiteDirs({ workspace })) {
    const site = readSiteCandidate({ dir: candidate });
    if (!site) continue;
    const dir = fs.realpathSync(candidate);
    if (listedPaths.has(dir)) continue;
    listedPaths.add(dir);
    const { config, meta } = site;
    const name = routeName({ basename: path.basename(dir), siteId: meta.siteId }, { usedNames });
    usedNames.add(name);
    discovered.push({ id: meta.siteId, name: config.name, path: dir, createdBy: "discovered", lastOpened: null });
    sites.push({ id: meta.siteId, name, dir, displayName: config.name, createdAt: meta.createdAt,
      active: dir === currentSiteDir, running: readSiteRunning({ dir }, { workspace }) });
  }
  if (discovered.length) registry.merge({ entries: discovered });
  return sites;
}

/** Catalog rows first, then every immediate subdirectory of each discovery root (unvalidated).
 * @complexity O(r + n): r catalog rows plus n entries across the roots.
 */
function candidateSiteDirs({ workspace }: { workspace: Pick<SitesWorkspace, "registry" | "roots"> }): Set<string> {
  const known = new Set(workspace.registry({}).list({}).map((entry) => entry.path));
  for (const root of workspace.roots({})) {
    for (const entry of readRootEntries({ root })) if (entry.isDirectory()) known.add(path.join(root, entry.name));
  }
  return known;
}

function readRootEntries({ root }: { root: string }): fs.Dirent[] {
  try { return fs.readdirSync(root, { withFileTypes: true }); }
  catch (error) {
    // No sites directory at all is an honest empty discovery result on a fresh checkout.
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw error;
  }
}

function readSiteCandidate({ dir }: { dir: string }): ReturnType<typeof readSiteDir> | undefined {
  try { return readSiteDir({ dir }); }
  catch {
    // Not a valid site (missing/corrupt config.json or .site-meta.json) — skip it rather than
    // fail the whole listing over one stray or half-written directory (see listSites's doc).
    return undefined;
  }
}

/** The folder name when it is a safe, unused route; otherwise the marker's site id. */
function routeName({ basename, siteId }: { basename: string; siteId: string }, { usedNames }: { usedNames: ReadonlySet<string> }): string {
  // Arbitrary adopted folders can share basenames or contain spaces. The marker ID supplies a
  // safe route identifier in those cases; no caller ever supplies an arbitrary filesystem path.
  return SITE_NAME_PATTERN.test(basename) && basename.length <= MAX_SITE_NAME_LENGTH && !usedNames.has(basename) ? basename : siteId;
}

/** Folder-name validation (distinct from `initSite`'s own `--name` display-name rule — see
 *  {@link SITE_NAME_PATTERN}'s doc for why format matters here and not there). */
function validateSiteName({ name }: { name: string }, _optional = {}): string {
  assertPortableSiteName({ name });
  const trimmed = name.trim();
  if (trimmed.length === 0 || trimmed.length > MAX_SITE_NAME_LENGTH || !SITE_NAME_PATTERN.test(trimmed)) {
    throw new ValidationError(`createSite: name must be 1..${MAX_SITE_NAME_LENGTH} lowercase letters, digits, and dashes`);
  }
  return trimmed;
}

/** Refuse site names Windows treats as devices or cannot create, even when this host is Unix.
 * @throws {ValidationError} A device name (including extensions), trailing dot or space.
 * @complexity O(name length), no I/O.
 */
export function assertPortableSiteName({ name }: { name: string }, _optional = {}): void {
  if (/^(?:con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\.|$)/i.test(name.trimStart()) || /[. ]$/.test(name)) {
    throw new ValidationError("Site names must not use Windows device names or end with a dot or space.");
  }
}

export interface CreateSiteRequired {
  name: string;
  adminPassword?: string;
  displayName?: string;
}

export interface SiteCreationAllocation extends InitSiteResult { name: string; dbPath: string }

export interface CreateSiteResult extends InitSiteResult {
  name: string;
}

export type CreateSiteOptions = ListSitesOptional & { initSite?: InitSitePort; workspace?: SitesWorkspace; verifiedRestore?: InitSiteRestorePort; collisionSafe?: boolean; onAllocated?: (required: SiteCreationAllocation) => void; beforeRegister?: (required: CreateSiteResult) => void };
export type CreateSitePort = (required: CreateSiteRequired, optional?: CreateSiteOptions) => Promise<CreateSiteResult>;

/**
 * Create a new site under `sites/<name>/` through the SAME `initSite` orchestration `tovu init`
 * uses (BR-01's 8-step ordering, commit-marker discipline included) — never a parallel
 * implementation. `name` doubles as both the folder name and `config.json`'s display-name default
 * (`initSite`'s own `resolveSiteName` falls back to the target's basename, which is `name` here).
 * @param required.deps - the initializer bound by the embedding host.
 *
 * @throws {ValidationError} an invalid `name` (this function's own folder-name format check, run
 *   BEFORE `initSite` is even called — nothing is written for a malformed name).
 * @throws whatever `initSite` throws for an occupied target or an internal failure (e.g.
 *   `InitDirNotEmptyError` when `sites/<name>/` already exists) — see that function's own contract;
 *   nothing here re-classifies those errors.
 * @complexity initSite's byte cost plus O(sites + name collisions) for collision-safe imports;
 *   name selection is bounded to 10,000 candidates under a shared home lock.
 */
export async function createSite(required: CreateSiteRequired & { deps: { initSite: InitSitePort } }, optional: CreateSiteOptions = {}): Promise<CreateSiteResult> {
  const name = validateSiteName({ name: required.name });
  const workspace = optional.workspace ?? createSitesWorkspace({}, optional);
  const home = workspace.home({});
  if (!workspace.homeAvailable({})) throw new ValidationError(`Sites home volume is unavailable: ${home}. Mount it or choose a local folder in Sites settings.`);
  fs.mkdirSync(home, { recursive: true });
  const create = async (picked: string): Promise<CreateSiteResult> => {
    const dir = path.join(home, picked);
    return withFileLock({ lockPath: `${dir}.creation.lock`, run: async () => {
      if (optional.collisionSafe && fs.existsSync(dir)) throw new InitDirNotEmptyError("Import target was occupied while waiting for its creation lock.");
      const result = await (optional.initSite ?? required.deps.initSite)({ dir, name: required.displayName ?? picked, adminPassword: required.adminPassword }, { workspace, onAllocated: allocation => optional.onAllocated?.({ ...allocation, name: picked }), ...(optional.verifiedRestore ? { verifiedRestore: optional.verifiedRestore } : {}) });
      try {
        optional.beforeRegister?.({ ...result, name: picked });
        workspace.registry({}).merge({ entries: [{ id: result.siteId, name: picked, path: result.dir, createdBy: "Web", lastOpened: null }] });
      } catch (error) {
        if (optional.verifiedRestore) {
          // The catalog write can fail after init committed. Roll back only this fresh import.
          removeUncommittedSite({ dir: result.dir, contentDbPath: () => resolveSiteDatabasePaths({ dir: result.dir, siteId: result.siteId },
            { workspace, placement: workspace.config({}).databases, reserveIdentity: false }).contentDbPath });
          workspace.registry({}).remove({ path: result.dir });
        }
        throw error;
      }
      return { ...result, name: picked };
    } }, { staleMs: Infinity });
  };
  if (!optional.collisionSafe) return create(name);
  // Name selection and import creation share a home-level lane; ordinary creators retain their
  // per-name lock, so an intervening ordinary create is retried with the next suffix.
  return withFileLock({ lockPath: path.join(home, ".import-creation.lock"), run: async () => {
    const occupied = new Set(workspace.registry({}).list({}).map(row => row.name));
    for (let suffix = 1; suffix <= 10_000; suffix++) {
      const candidate = suffix === 1 ? name : name.slice(0, 90) + "-" + suffix;
      if (fs.existsSync(path.join(home, candidate)) || occupied.has(candidate)) continue;
      try { return await create(candidate); }
      catch (error) {
        if ((error as Error).name !== "InitDirNotEmptyError") throw error;
      }
    }
    throw new ValidationError("No collision-free import site name is available.");
  } }, { staleMs: Infinity });
}

/** Reconcile a journaled fresh import under the same locks as creation. A catalog commit
 * plus initSite's marker is authoritative; otherwise discard only the allocated fresh files.
 * Throws on conflicting ownership rather than removing another site. O(catalog + site bytes).
 */
/** Undo an uncommitted creation: the commit marker first (so the database path is resolved as for a
 * markerless folder), then an app-data database folder outside the site, then the site folder.
 */
function removeUncommittedSite({ dir, contentDbPath }: { dir: string; contentDbPath: () => string }): void {
  fs.rmSync(path.join(dir, ".site-meta.json"), { force: true });
  const dbPath = contentDbPath();
  if (!dbPath.startsWith(dir + path.sep)) fs.rmSync(path.dirname(dbPath), { recursive: true, force: true });
  fs.rmSync(dir, { recursive: true, force: true });
}

export async function reconcileSiteCreation(required: { allocation: SiteCreationAllocation; workspace: SitesWorkspace }, _options: Record<string, never> = {}): Promise<"ready" | "failed"> {
  const { allocation, workspace } = required;
  return withFileLock({ lockPath: path.join(path.dirname(allocation.dir), ".import-creation.lock"), run: () =>
    withFileLock({ lockPath: `${allocation.dir}.creation.lock`, run: () => {
      const entries = workspace.registry({}).list({});
      const owner = entries.find(entry => entry.path === allocation.dir || entry.id === allocation.siteId);
      if (owner) {
        if (owner.path !== allocation.dir || owner.id !== allocation.siteId || readSiteDir({ dir: allocation.dir }).meta.siteId !== allocation.siteId) throw new ValidationError("Interrupted import has conflicting site ownership; manual recovery required.");
        return "ready" as const;
      }
      if (fs.existsSync(path.join(allocation.dir, ".site-meta.json")) && readSiteDir({ dir: allocation.dir }).meta.siteId !== allocation.siteId) throw new ValidationError("Interrupted import directory belongs to another site; manual recovery required.");
      removeUncommittedSite({ dir: allocation.dir, contentDbPath: () => allocation.dbPath });
      return "failed" as const;
    } }, { staleMs: Infinity })
  }, { staleMs: Infinity });
}

/**
 * Whether a listed directory carries `initSite`'s own commit markers (`config.json` +
 * `.site-meta.json`, INV-02) — which is exactly the difference between a folder `tovu serve` would
 * accept and one it would refuse with `SiteDirInvalidError`.
 *
 * A distinct STATE rather than a loosened validator. {@link listSites} still means "directories
 * `serve` would accept", because that is what its two write-path callers (this route's Activate,
 * and `features/sites/tool-registrations.ts`'s duplicate-source lookup) need it to mean.
 */
export type SiteRegistration = "registered" | "unregistered";

/**
 * A {@link SiteListEntry} carrying the one fact the strict listing has no way to express: whether
 * this row is a real initialized site or the directory this process happens to be serving without
 * one. Every field except {@link ServingSiteListEntry.registration} means what it does on the base
 * type; see {@link includeServingSite} for what an `unregistered` row's fields are derived from.
 */
export interface ServingSiteListEntry extends SiteListEntry {
  registration: SiteRegistration;
}

export interface IncludeServingSiteOptional {
  /** Directory stat port; node:fs by default. */
  stat?: (dir: string) => fs.Stats;
}

export interface IncludeServingSiteRequired {
  /** {@link listSites}'s own output — unmodified, and every entry becomes `registered`. */
  sites: readonly SiteListEntry[];
  /** {@link describeSiteBinding}'s output for the SAME `cwd`/`env`, so the two agree about which
   *  directory "serving" means. */
  binding: SiteBinding;
}

/** The served directory's `fs.Stats` when it exists and is a directory, `null` otherwise. One
 *  `statSync`, reused for the entry's `createdAt`, so the existence check and the timestamp can
 *  never describe two different states of the filesystem.
 *
 *  @complexity O(1) — a single stat. */
function readServingDirStat(dir: string, { stat: statDir }: { stat: (dir: string) => fs.Stats }): fs.Stats | null {
  try {
    const stat = statDir(dir);
    return stat.isDirectory() ? stat : null;
  } catch {
    return null;
  }
}

/**
 * The synthetic row for a served directory that {@link listSites} rejected.
 *
 * Every field is a fact about the directory itself rather than a guess at what its missing
 * `config.json`/`.site-meta.json` would have said:
 * - `displayName` is the folder name, because no `config.json` exists to read one from.
 * - `createdAt` is the FOLDER's own creation time, not `initSite`'s commit-marker timestamp (there
 *   isn't one). `birthtime` where the filesystem records it, `mtime` where it reports zero.
 * - `active` is unconditionally `true`: this function is only ever called for the directory this
 *   process is bound to, which is what makes the `unregistered`-implies-`active` invariant hold.
 *
 * @complexity O(1).
 */
function describeUnregisteredServingSite(binding: SiteBinding, stat: fs.Stats): ServingSiteListEntry {
  const born = stat.birthtimeMs > 0 ? stat.birthtime : stat.mtime;
  return {
    name: binding.name,
    dir: binding.dir,
    displayName: binding.name,
    createdAt: born.toISOString(),
    active: true,
    registration: "unregistered",
  };
}

/**
 * The listing the admin Sites screen renders: every real site, plus the directory this process is
 * actually serving when that directory is not one of them.
 *
 * ## Why this exists rather than a change to `listSites`
 *
 * This repo's own `sites/tovu-dev` carries neither marker file, so `readSiteDir` rejects it,
 * `listSites` drops it, and the screen showed "All sites 0" while that exact folder was being
 * served. Loosening `readSiteDir` would have fixed the screen by breaking the contract two write
 * paths depend on: Activate uses `listSites` as its existence check, and `sites_duplicate_site`
 * uses it to find a duplicate SOURCE — and `duplicateSite` reads the source's `.site-meta.json`
 * schema stamp, so handing it a marker-less directory turns a clean refusal into a thrown
 * `SiteDirInvalidError` mid-operation. Composing here instead leaves both untouched.
 *
 * ## The invariant callers may rely on
 *
 * An `unregistered` entry is ALWAYS the served one (`active: true`), because that is the only
 * entry this function ever adds. So a UI that disables Activate for whatever is already serving —
 * as the Sites screen does — can never route an `unregistered` name to Activate's strict
 * `listSites` lookup and collect a `SITE_NOT_FOUND`.
 *
 * A directory that does not exist, or a path that is a file, adds nothing: a card for a folder
 * that is not there would be its own kind of lie.
 *
 * @param required.sites - `listSites()`'s output for some `cwd`/`env`.
 * @param required.binding - `describeSiteBinding()`'s output for that SAME `cwd`/`env`.
 * @returns Every input entry as `registered`, in input order, plus at most one appended
 *   `unregistered` entry for the served directory.
 * @complexity O(n) in the number of sites already listed, plus one `stat`.
 */
export function includeServingSite(required: IncludeServingSiteRequired, { stat = (dir: string) => fs.statSync(dir) }: IncludeServingSiteOptional = {}): ServingSiteListEntry[] {
  const { binding } = required;
  const registered: ServingSiteListEntry[] = required.sites.map((site) => ({ ...site, registration: "registered" }));
  if (registered.some((site) => site.dir === binding.dir)) return registered;
  const served = readServingDirStat(binding.dir, { stat });
  if (served === null) return registered;
  return [...registered, describeUnregisteredServingSite(binding, served)];
}

/** What THIS process is actually bound to right now — see {@link describeSiteBinding}. */
export interface SiteBinding {
  /** Absolute path this process resolved at boot (`resolveSiteRoot()`), re-derived fresh. */
  dir: string;
  /** `dir`'s folder name — the `TOVU_SITE` vocabulary `persistActiveSite` writes in. */
  name: string;
  /**
   * True when `TOVU_SITE_DIR` is set in this process's environment.
   *
   * Load-bearing for the admin Sites screen, not a diagnostic nicety: `resolveSiteRoot`'s
   * precedence puts `TOVU_SITE_DIR` ABOVE the `TOVU_SITE` line `persistActiveSite` writes, so when
   * this is true an activate is inert — the next boot resolves the override and ignores the
   * persisted choice entirely. A UI that offered Activate without saying so would promise a switch
   * that cannot happen.
   */
  dirOverridden: boolean;
  /**
   * False when `dir` was resolved from an explicit, arbitrary install-dir argument (`tovu serve
   * <dir>` / `bootSiteDir`) rather than from THIS function's own `{cwd, env}`-relative
   * `<cwd>/sites/<name>` convention.
   *
   * `listSites`/`createSite`/`persistActiveSite`/`sites_duplicate_site` all resolve their OWN
   * `sites/` root from a `cwd` — `process.cwd()` by default, which is a DIFFERENT computation from
   * whatever `dir` this binding names. The Sites routes and tools therefore never let it default:
   * they pass {@link switcherBaseForBinding}'s base, which exists only when this is `true`. `false`
   * tells those write paths to refuse rather than silently write under an unrelated `<cwd>/sites`.
   *
   * `describeSiteBinding` used to hardcode this `true`, on the stated reasoning that its own
   * `{cwd, env}` resolution always agrees with the switcher's. That reasoning did not cover
   * `TOVU_SITE_DIR`, which `resolveSiteRoot` honors outright and which can name any path on the
   * disk — so an override pointing outside `<cwd>/sites` produced a binding that CLAIMED to be
   * switchable while the switcher's own root was somewhere else entirely. It is computed now (see
   * {@link describeSiteBinding}), and additionally forced off by
   * {@link SITE_BINDING_NOT_SWITCHABLE_ENV} for the one case no path comparison can detect: a
   * `tovu serve <dir>` boot whose `<dir>` happens to sit under `<cwd>/sites` but was still pinned
   * by an explicit argument rather than chosen through the switcher.
   */
  switcherCompatible: boolean;
  /** Repo base is independent of the selected shared home; .env remains repo-owned. */
  switcherBase?: string;
}

/**
 * Describe the site binding this process is serving from, read-only and re-derived on every call
 * (never cached), so it always reflects what a request handled right now would actually see.
 *
 * Separate from {@link listSites}'s per-entry `active` flag because the two answer different
 * questions, and the difference is exactly what the admin Sites screen has to be honest about:
 * `active` can be `false` on EVERY row (the live site directory carries no `.site-meta.json`
 * commit marker, so `listSites` skips it — the pre-marker `sites/tovu-dev` in this repo is that
 * case today), and a screen that only had the list would then render "no sites" while a site is
 * plainly being served.
 *
 * @complexity O(n) registered sites and home entries, plus the binding membership lookup.
 */
/**
 * Set (to any value) by a boot that was pinned to an explicit install-dir argument — `tovu serve
 * <dir>`, via `cli/commands/serve.ts`'s `pinServedSiteDirIntoEnv`. Written into the SERVING
 * process's own environment so the agent daemon it `spawn()`s inherits it (2026-09-07 audit, claim
 * #4).
 *
 * WHY AN ENV FLAG AND NOT JUST THE PATH CHECK BELOW: the API process gets its non-switchable
 * binding handed to it directly (`composition/deps.ts`'s `siteBinding` override), but the daemon is
 * a separate process that builds its OWN `RouteDeps` via `createSiteRouteDepsForWorkspace` and so
 * falls back to this function. The daemon is also where `sites_duplicate_site` actually executes —
 * so the guard `features/sites/tool-registrations.ts` raises for a non-switchable binding was
 * enforced by the HTTP routes and bypassed by the agent tool. A path comparison alone cannot close
 * it: `tovu serve ./sites/tovu-dev` names a directory that IS `<cwd>/sites`-relative, yet was still
 * pinned by argument rather than chosen through the switcher, and the two processes must agree
 * about that either way.
 */
export const SITE_BINDING_NOT_SWITCHABLE_ENV = "TOVU_SITE_BINDING_NOT_SWITCHABLE";

/** Whether `dir` is a direct child of the `<cwd>/sites` root the Sites-switcher's own write paths
 *  resolve — the condition that makes a binding safe to switch/duplicate against. @complexity O(1). */
function isUnderSwitcherSitesRoot(dir: string, optional: ListSitesOptional): boolean {
  const cwd = optional.cwd ?? process.cwd();
  return path.dirname(dir) === path.resolve(cwd, "sites") || isInSitesWorkspace({ dir, workspace: createSitesWorkspace({}, optional) });
}

/** One workspace answers both questions: directly under the shared home, or a catalog-registered folder.
 * Windows compares resolved paths without case/separator differences. No filesystem probes.
 * @complexity O(n × path length) for n catalog entries.
 */
export function isInSitesWorkspace({ dir, workspace }: { dir: string; workspace: Pick<SitesWorkspace, "home" | "registry"> }, { platform = process.platform }: { platform?: NodeJS.Platform } = {}): boolean {
  const paths = platform === "win32" ? path.win32 : path.posix;
  const canonical = (value: string) => platform === "win32" ? paths.resolve(value).toLowerCase() : paths.resolve(value);
  return canonical(paths.dirname(paths.resolve(dir))) === canonical(workspace.home({})) ||
    workspace.registry({}).list({}).some((entry) => canonical(entry.path) === canonical(dir));
}

export function describeSiteBinding(optional: ListSitesOptional = {}): SiteBinding {
  const dir = resolveSiteRoot(optional);
  const env = optional.env ?? process.env;
  return {
    dir,
    name: path.basename(dir),
    dirOverridden: env.TOVU_SITE_DIR !== undefined && env[SITE_SELECTION_PINNED_ENV] !== "1",
    switcherBase: optional.cwd ?? process.cwd(),
    switcherCompatible:
      env[SITE_BINDING_NOT_SWITCHABLE_ENV] === undefined && isUnderSwitcherSitesRoot(dir, optional),
  };
}

/**
 * The base directory the Sites-switcher's `sites/` root and `.env` live under, read off the boot
 * binding — `null` when the binding is not switchable (an install-dir boot has no `sites/` tree).
 *
 * WHY THIS AND NOT `process.cwd()`: `listSites`/`createSite`/`persistActiveSite`/
 * `readPersistedActiveSite` all default their base to `process.cwd()`. A request handler that let
 * them default listed, created and activated in whatever tree the process happened to be standing
 * in, while `siteBinding` named another one (development/todos.md, "The sites route and
 * `sites_duplicate_site` re-derive the site binding from `process.cwd()`"). A switchable binding's
 * `dir` is, by {@link describeSiteBinding}'s own definition, a direct child of `<base>/sites`, so
 * the base is recoverable from the binding alone — every Sites route and tool passes this instead.
 *
 * @complexity O(1) — path arithmetic only.
 */
export function switcherBaseForBinding(binding: SiteBinding): string | null {
  return binding.switcherCompatible ? binding.switcherBase ?? path.dirname(path.dirname(binding.dir)) : null;
}

/**
 * The base a NEW sibling site (an import) is created from, or `null` when this process must not
 * create local sites. Absorbs {@link switcherBaseForBinding}: an enabled switcher keeps its base.
 * A pinned boot (desktop's `tovu serve <home>/<name>`) whose site already lives in the shared sites
 * home also qualifies — creating a sibling there never switches what this process serves, so the
 * switcher flag (which also gates Activate) is not the right question. Production never qualifies.
 * @complexity O(n) registered sites, one workspace resolution.
 */
export function siteCreationBaseForBinding(required: { binding: SiteBinding }, optional: ListSitesOptional = {}): string | null {
  const { binding } = required;
  const env = optional.env ?? process.env;
  // NODE_ENV is the image's own signal; TOVU_RUNTIME_MODE also covers a hand-run `npm start` server.
  if (env.NODE_ENV === "production" || resolveRuntimeMode({ env }) === "production") return null;
  const switcherBase = isSiteSwitcherEnabled(env) ? switcherBaseForBinding(binding) : null;
  if (switcherBase !== null) return switcherBase;
  const cwd = binding.switcherBase ?? optional.cwd ?? process.cwd();
  return isInSitesWorkspace({ dir: binding.dir, workspace: createSitesWorkspace({}, { ...optional, env, cwd }) }) ? cwd : null;
}

/** The served install dir as a one-row listing when `tovu serve` would accept it, else nothing.
 *  @complexity O(1) — one `readSiteDir`. */
function listServedSiteOnly(binding: SiteBinding): SiteListEntry[] {
  try {
    const { config, meta } = readSiteDir({ dir: binding.dir });
    return [{ name: binding.name, dir: binding.dir, displayName: config.name, createdAt: meta.createdAt, active: true }];
  } catch {
    return [];
  }
}

export interface ListSitesForBindingRequired {
  binding: SiteBinding;
}

export interface ListSitesForBindingOptional {
  /** Defaults to {@link listSites}. Called with the binding's own base, never left to default. */
  listSites?: (optional?: ListSitesOptional) => readonly SiteListEntry[];
}

/**
 * {@link listSites} for the tree the process is BOUND to, not the one it is standing in.
 *
 * - Switchable binding: `listSites` over `<base>/sites` ({@link switcherBaseForBinding}), with
 *   `active` re-read against `binding.dir` — `listSites`'s own `active` re-derives the served dir
 *   from `{cwd, env}`, which is exactly the re-derivation this function exists to avoid.
 * - Install-dir binding (`tovu serve <dir>`): there is no related `sites/` tree, so the only site is
 *   the served one, listed when `tovu serve` would accept it. Listing `<cwd>/sites` here reported an
 *   unrelated checkout's sites as this server's.
 *
 * @complexity O(n) in the entries under the bound `sites/`, or one `readSiteDir` for an install dir.
 */
export function listSitesForBinding(required: ListSitesForBindingRequired, optional: ListSitesForBindingOptional = {}): SiteListEntry[] {
  const { binding } = required;
  const base = switcherBaseForBinding(binding);
  if (base === null) return listServedSiteOnly(binding);
  return (optional.listSites ?? listSites)({ cwd: base }).map((site) => ({ ...site, active: site.dir === binding.dir }));
}

/** Server boot owns the lease; host launchers only observe it. Never release on SIGTERM before
 * storage has closed. Process exit (or proven dead-pid cleanup) is the terminal ownership boundary.
 */
import { createSitesWorkspace, type SitesWorkspace } from "./sites-home.js";
import { readSiteDir } from "./read-site-dir.js";
import { SiteDirInvalidError } from "./errors.js";
import type { DirectoryRunningRecord } from "@jini-ai/platform/fs";

export function readSiteRunning({ dir }: { dir: string }, { workspace = createSitesWorkspace({}) }: { workspace?: SitesWorkspace } = {}): DirectoryRunningRecord | null {
  return workspace.running({ path: dir }).read({});
}
export function runningSiteUrl({ record }: { record: DirectoryRunningRecord }, _options = {}): string | null {
  return record.port > 0 ? `${record.scheme}://localhost:${record.port}/admin/` : null;
}
/** Must precede all database reads/writes; a concurrent loser cannot open content.db.
 * @throws An actionable running/starting message; malformed locks also fail closed.
 * @complexity O(1) JSON I/O and liveness probe.
 */
export function claimSiteRunning(
  { dir, app, scheme = "http" }: { dir: string; app: "Web" | "Desktop"; scheme?: "http" | "https" },
  { workspace = createSitesWorkspace({}), readSite = readSiteDir }: { workspace?: SitesWorkspace; readSite?: typeof readSiteDir } = {},
) {
  const claim = workspace.claim({ path: dir, app, scheme });
  if (!claim.acquired) throw new Error(`Running in ${claim.record.app} (${claim.record.port > 0 ? `port ${claim.record.port}` : "starting"}). ${runningSiteUrl({ record: claim.record }) ?? "Wait for this site to finish starting."}`);
  const lock = workspace.running({ path: dir });
  const release = () => lock.release({ token: claim.record.token });
  process.once("exit", release);
  return { ready: ({ port }: { port: number }, _options = {}) => {
    lock.update({ token: claim.record.token, port });
    let site: ReturnType<typeof readSiteDir>;
    try { site = readSite({ dir }); }
    catch (error) {
      // The existing checkout default can run without install-dir markers; do not invent them.
      if (error instanceof SiteDirInvalidError) return;
      throw error;
    }
    workspace.registry({}).merge({ entries: [{ id: site.meta.siteId, name: site.config.name, path: dir, createdBy: app, lastOpened: null }] });
    workspace.registry({}).opened({ path: dir, at: new Date().toISOString() });
  },
    release: (_required: Record<string, never> = {}, _options = {}) => { process.removeListener("exit", release); release(); } };
}

import fs from "node:fs";
import path from "node:path";

import { SiteDirInvalidError } from "./errors.js";
import type { SiteStorage } from "./types.js";

/**
 * @file Which database engine a site runs on — `.site-meta.json`'s optional `storage` field
 * (R1 plan §0, ADR-067).
 *
 * Lenient on purpose: a site folder may carry a partial meta file (the dev site's holds only its
 * site-key fields until `key-only-site-meta.ts` completes it, and the same-directory dev boot never
 * runs `readSiteDir`), or none at all, and
 * both mean SQLite, exactly as before this field existed. Only a `storage` value that is present
 * and wrong is refused, because guessing SQLite for a site that asked for Postgres would boot an
 * empty store in its place.
 */

export const SITE_META_FILENAME = ".site-meta.json";

/** The storage every site has unless its meta file says otherwise. */
export const DEFAULT_SITE_STORAGE: SiteStorage = Object.freeze({ kind: "sqlite" }) as SiteStorage;

/** Keys that would put a connection secret in the meta file; O3 keeps it sealed or in the environment. */
const SECRET_BEARING_KEYS = ["connectionString", "url", "password"] as const;

/** An environment variable name: letters, digits and `_`, not starting with a digit. */
const ENV_NAME = /^[A-Za-z_][A-Za-z0-9_]*$/;

function invalid(reason: string): never {
  throw new SiteDirInvalidError(`${SITE_META_FILENAME} storage ${reason}`);
}

function parseSecretRef(value: unknown): "site" | { env: string } {
  if (value === "site") return "site";
  const env = (value as { env?: unknown } | null)?.env;
  if (typeof value === "object" && value !== null && typeof env === "string" && ENV_NAME.test(env)) return { env };
  return invalid(`secretRef must be "site" or { "env": "<VARIABLE_NAME>" }`);
}

/**
 * Validates a meta file's `storage` value. `undefined` (the field is absent) is SQLite.
 *
 * @throws {SiteDirInvalidError} for an unknown `kind`, a malformed `secretRef`, or a connection
 *   secret written into the meta file.
 */
export function parseSiteStorage(value: unknown): SiteStorage {
  if (value === undefined) return DEFAULT_SITE_STORAGE;
  if (typeof value !== "object" || value === null) return invalid("must be an object with a kind");
  const candidate = value as Record<string, unknown>;
  for (const key of SECRET_BEARING_KEYS) {
    if (key in candidate) invalid(`must not hold "${key}": the connection string is sealed with the site key or read from the environment`);
  }
  switch (candidate.kind) {
    case "sqlite":
      return { kind: "sqlite" };
    case "pglite":
      return { kind: "pglite" };
    case "postgres":
      return { kind: "postgres", secretRef: parseSecretRef(candidate.secretRef) };
    default:
      return invalid(`kind ${JSON.stringify(candidate.kind)} is not one of "sqlite", "pglite", "postgres"`);
  }
}

/**
 * The storage for the site in `siteDir`, read from its `.site-meta.json`.
 *
 * @param siteDir - the site folder, or `":memory:"` (always SQLite).
 * @returns SQLite when the meta file or its `storage` field is absent.
 * @throws {SiteDirInvalidError} when the meta file is not JSON or its `storage` is invalid.
 * @complexity O(1) — one small file read.
 */
export function resolveSiteStorage(siteDir: string): SiteStorage {
  if (siteDir === ":memory:") return DEFAULT_SITE_STORAGE;
  let raw: string;
  try {
    raw = fs.readFileSync(path.join(siteDir, SITE_META_FILENAME), "utf8");
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return DEFAULT_SITE_STORAGE;
    throw err;
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    throw new SiteDirInvalidError(`${SITE_META_FILENAME} is not valid JSON: ${(err as Error).message}`);
  }
  return parseSiteStorage((parsed as { storage?: unknown } | null)?.storage);
}

