} from "@jini-ai/user-management/server";
import type { PrincipalKind } from "#src/contracts/core/gated-mutations/ports";
import { parseAuthenticatedJsonBody } from "../shared/json-body-parsers.js";
import type { ClockDeps, IdentityDeps, RouteDeps } from "../../routes/types.js";
import { authenticateApiKey, type ApiKeyServiceDeps } from "#src/features/identity/api-key-service";
import { createRateLimiter, LOGIN_STRICT, resolveClientIp } from "#src/contracts/core/rate-limit/rate-limit";
import { createBootSessionTokenStore, redeemBootSessionToken } from "#src/features/identity/boot-session-token";
import { allowsLocalOwnerSignInRequest, bootLocalOwnerSignIn, type LocalOwnerSignInPolicy } from "../../runtime/boot/local-owner-signin.js";
import { DEFAULT_OWNER_PASSWORD } from "#src/features/identity/wiring";
import { callerMayManageUserTrash, principalHoldsBuiltinAdminRole, principalHoldsOwnerWildcard } from "#src/features/identity/delete-user-service";
import { canPublishToLive } from "#src/features/publish-content/live-site-policy";

/**
 * @file Real session auth for the admin origin (ADR-021 / SPEC-006).
 *
 * Purpose:
 * Gates /api/admin/* behind a server-side session backed by the `identity`
 * library's principal/RBAC model. This REPLACES the pre-SPEC-006
 * hardcoded-credential HMAC-cookie scheme (stateless signed `{userId, exp}`
 * token, a single env-var username/password pair, always resolving to the
 * literal actor `"user-local"`) with real argon2id password verification
 * against the seeded `users` table and a real, server-side, revocable
 * `sessions` row per login (REQ-06).
 *
 * How it relates to the project:
 * - Registered by `server/app.ts` ahead of admin routes.
 * - `TOVU_ADMIN_USER`/`TOVU_ADMIN_PASSWORD` still set the *seeded* owner's
 *   username/password at first boot (`identity/seed.ts`) — same env vars as
 *   before, but they now seed a real hashed credential rather than being
 *   compared directly on every login.
 * - Route handlers that need "who is calling" read `getAuthedPrincipal(res)`
 *   (set here once per request) rather than re-parsing the cookie.
 * - The login route is additionally guarded by the `LOGIN_STRICT` rate-limit
 *   profile (REQ-14/AC-18, `core/rate-limit/rate-limit.ts`) before credentials are checked.
 *
 * SPEC-006 REQ-08 (2026-08-24): the gate now accepts a SECOND credential type — an issued API key
 * presented as `Authorization: Bearer <raw-key>` (or `ApiKey <raw-key>`, the spelling api.spec §2
 * uses; both are accepted so an ordinary HTTP client's bearer-token support works unchanged). Both
 * credentials resolve to the same thing — a `PrincipalRecord` on `res.locals` — so every existing
 * `getAuthedPrincipal`/`authorize()` call downstream is untouched by the addition: an api_key
 * principal's grants come from its issuance snapshot and are evaluated by the same `authorize()`.
 *
 * The cookie is tried first, so a browser request behaves EXACTLY as before and the header path is
 * reached only when there is no session to find.
 *
 * Scope: this applies to every surface that mounts `requireAdminSession`, which today is
 * `/api/admin` (`modules/core.ts`) AND `/api/assistant/chats` (`modules/assistant-chats.ts`) — not
 * `/api/admin` alone. Both are admin-authenticated surfaces whose per-route authorization is
 * unchanged, so a key reaches exactly the routes its snapshotted permissions already allow;
 * `openapi/006-identity-and-authorization.yaml` documents the `/api/admin` half.
 *
 * Architectural role:
 * `requireAdminSession`/`registerAuthRoutes` are middleware/route factories
 * that close over the identity repos + hasher + the `identityReady` seed
 * promise (`registerAuthRoutes` still takes the full `RouteDeps` bag it's
 * registered against; `requireAdminSession`/`currentPrincipal` take only
 * `SessionAuthDeps` — see that type's own doc) — the composition roots
 * (`server/app.ts`) pass `routeDeps` in either way, since `RouteDeps` is a
 * strict superset of `SessionAuthDeps`. Not a port (ADR-006): one real
 * session/credential implementation.
 */
const SESSION_COOKIE = "tovu_session";

// The extracted minter keeps the 32-byte hex bearer and SHA-256 digest in
// user-management/server/session-tokens.ts; binding it preserves existing session rows.
const sessionTokens = new NodeSessionTokens({});
// Tovu's absolute 30-day lifetime is product policy, passed explicitly to both minting paths.
const SESSION_TTL_MS = 30 * 24 * 60 * 60 * 1000;

/**
 * `Bearer <raw-key>` or `ApiKey <raw-key>`, case-insensitive on the scheme. The captured group is
 * a live credential: it is passed straight to `authenticateApiKey` and is never logged, echoed in
 * an error body, or attached to `res.locals`.
 */
const API_KEY_AUTHORIZATION_PATTERN = /^(?:Bearer|ApiKey)[ \t]+(\S+)$/i;

/** How the current request authenticated. Route families that must not be reachable by a machine
 *  credential (see `routes/admin/api-keys/*`) branch on this.
 *
 * `"publish_key"` is resolved by `publish-trust-auth.ts`'s `requirePublishTrust`, NOT by
 * `currentCredential` below — a publishing session token is never a credential this file can
 * issue or validate, and it reaches only the routes `grant.ts`'s `PUBLISH_TRUST_ROUTES` names.
 * It is listed here so the existing `rejectUnlessSessionCredential` guard (which admits only
 * `"session"`) refuses it on every machine-credential-forbidden route without a second edit. */
export type AuthCredentialKind = "session" | "api_key" | "publish_key";

/**
 * Maps how a request authenticated onto the principal class a gated ceremony records
 * (`core/gated-mutations/ports.ts`'s `PrincipalKind`).
 *
 * Exists so a route stops hardcoding `principalKind: "user"` for every caller. The mapping is
 * total and deliberately has no default arm: a new credential kind is a compile error here rather
 * than a silent re-label of automation as a human.
 *
 * `"agent"` is unreachable from this mapping because no agent authenticates through the admin HTTP
 * gate — agent-driven ceremonies pass their own kind directly from each feature's own
 * `tool-registrations.ts`.
 *
 * @complexity O(1).
 */
export function gatedPrincipalKindFor(kind: AuthCredentialKind): PrincipalKind {
  switch (kind) {
    case "session":
      return "user";
    case "api_key":
      return "api_key";
    case "publish_key":
      return "publish_key";
  }
}

/**
 * A principal an admin credential may resolve to: any kind but a site `member`. Members sign in on
 * the member origin with their own session (ADR-030 §3) and `authorize()` denies them every
 * operator permission (F3144); `currentCredential` also refuses an operator session or API key that
 * resolves to one, so admin routes can rely on this type.
 */
export type OperatorPrincipalRecord = PrincipalRecord & { kind: Exclude<IdentityPrincipalKind, "member"> };

function isOperatorPrincipal(principal: PrincipalRecord): principal is OperatorPrincipalRecord {
  return principal.kind !== "member";
}

/** A resolved credential: who is calling, and which of the two credential types proved it. */
export interface AuthenticatedCredential {
  principal: OperatorPrincipalRecord;
  kind: AuthCredentialKind;
}

/**
 * Deps `requireAdminSession`/`currentPrincipal` actually need: the identity repos (9 fields) plus
 * clock/idGen for `identity/*`'s `login`/`logout`/`validateSession`. Narrower than full `RouteDeps` —
 * see `routes/types.ts`'s `ClockDeps`/`IdentityDeps` doc for why this Slice-1 extraction exists.
 */
type SessionAuthDeps = IdentityDeps & ClockDeps;

/** Assemble the `IdentityRepos` bag `identity/*` functions expect from `RouteDeps`'s flat fields. */
function identityReposFrom(deps: IdentityDeps): IdentityRepos {
  return {
    transactions: deps.transactions,
    principals: deps.principalRepo,
    users: deps.userRepo,
    sessions: deps.sessionRepo,
    roles: deps.roleRepo,
    policies: deps.policyRepo,
    policyPermissions: deps.policyPermissionRepo,
    rolePolicies: deps.rolePolicyRepo,
    principalRoles: deps.principalRoleRepo,
    principalPolicies: deps.principalPolicyRepo,
  };
}

/** Bind the host's ISO clock and the required bearer strategy to Jini's auth ports. */
function authServiceDepsFrom(deps: SessionAuthDeps): AuthServiceDeps {
  return {
    repos: identityReposFrom(deps),
    hasher: deps.passwordHasher,
    clock: { nowMs: () => Date.parse(deps.clock.nowIso()) },
    idGen: deps.idGen,
    tokens: sessionTokens,
  };
}

/** Assemble the `ApiKeyServiceDeps` bag `authenticateApiKey` expects from `RouteDeps`'s flat fields. */
function apiKeyServiceDepsFrom(deps: SessionAuthDeps): ApiKeyServiceDeps {
  return {
    ...authServiceDepsFrom(deps),
    apiKeys: deps.apiKeyRepo,
    secretHasher: deps.apiKeySecretHasher,
  };
}

function readSessionToken({ req, localOwnerSignIn }: { req: Request; localOwnerSignIn: LocalOwnerSignInPolicy }, _optional = {}): string | null {
  // The port cookie is a dev capability, never a second production authentication name.
  const localToken = localOwnerSignIn.enabled ? readRequestCookie({ request: req, name: localSessionCookieName(req) }) : undefined;
  return localToken ?? readRequestCookie({ request: req, name: SESSION_COOKIE }) ?? null;
}

/** Revoke only the two session cookies this listener clears, using Jini's idempotent revoker.
 * Clearing a browser cookie alone leaves a captured bearer usable until expiry.
 * @complexity O(1): at most two session lookups/revocations; other tabs' sessions stay valid.
 */
async function revokeRequestSessions({ deps, req }: { deps: SessionAuthDeps; req: Request }, _optional = {}): Promise<void> {
  const tokens = new Set([readRequestCookie({ request: req, name: SESSION_COOKIE }),
    readRequestCookie({ request: req, name: localSessionCookieName(req) })]);
  for (const rawToken of tokens) {
    if (rawToken) await logout({ deps: authServiceDepsFrom(deps), input: { workspaceId: deps.workspaceId, rawToken } });
  }
}

/** Cookies ignore ports. Local browser sites need separate names to remain signed in together. */
function localSessionCookieName(req: Request): string {
  return `${SESSION_COOKIE}_local_${req.socket?.localPort ?? 0}`;
}

/** REQ-06: `HttpOnly`, `SameSite=Strict`, `Secure`, bound to the admin origin. */
function setSessionCookie(res: Response, rawToken: string, expiresAtIso: string, { name = SESSION_COOKIE }: { name?: string } = {}): void {
  const maxAge = Math.max(0, new Date(expiresAtIso).getTime() - Date.now());
  res.cookie(name, rawToken, { httpOnly: true, path: "/", maxAge, sameSite: "strict", secure: true });
  // A deliberate password sign-in supersedes local owner bootstrap, including a non-owner login.
  if (name === SESSION_COOKIE && readRequestCookie({ request: res.req, name: localSessionCookieName(res.req) })) {
    res.clearCookie(localSessionCookieName(res.req), { httpOnly: true, path: "/", sameSite: "strict", secure: true });
  }
}

function clearSessionCookie(res: Response): void {
  res.clearCookie(SESSION_COOKIE, { httpOnly: true, path: "/", sameSite: "strict", secure: true });
  if (readRequestCookie({ request: res.req, name: localSessionCookieName(res.req) })) {
    res.clearCookie(localSessionCookieName(res.req), { httpOnly: true, path: "/", sameSite: "strict", secure: true });
  }
}

/** Pull the raw key out of an `Authorization` header, or `null` when there is no key-shaped one. */
function readApiKeyCredential(req: Request): string | null {
  const header = req.headers.authorization;
  if (!header) return null;
  const match = API_KEY_AUTHORIZATION_PATTERN.exec(header.trim());
  return match ? match[1] : null;
}

/**
 * Resolve whichever credential this request carries to its principal, applying every fail-closed
 * check for that credential type. Awaits `deps.identityReady` first so this never races first-boot
 * seeding.
 *
 * The cookie is tried first and the `Authorization` header only when no session resolved, so an
 * ordinary browser request without a local port cookie keeps its existing behavior. Local dev
 * cookies use the same validator and repos; only their browser cookie name differs.
 * Both paths are all-or-nothing: `validateSession` and `authenticateApiKey` each return `null` for
 * every rejection reason (missing, invalid, expired, revoked, disabled principal) rather than a
 * distinguishable error, so the 401 below cannot be used as an oracle either way.
 *
 * @returns the principal plus WHICH credential proved it, or `null`.
 * @complexity O(1) — one cookie parse plus one session lookup, or one header parse plus one
 *   indexed api-key lookup and one key derivation.
 * @overallScore 100
 */
export async function currentCredential(
  deps: SessionAuthDeps,
  req: Request,
  { localOwnerSignIn = bootLocalOwnerSignIn }: { localOwnerSignIn?: LocalOwnerSignInPolicy } = {},
): Promise<AuthenticatedCredential | null> {
  const rawToken = readSessionToken({ req, localOwnerSignIn });
  if (rawToken) {
    await deps.identityReady;
    const resolved = await validateSession({
      deps: authServiceDepsFrom(deps),
      input: { workspaceId: deps.workspaceId, rawToken },
    });
    // A member principal is refused like a missing session (no oracle): only a hand-minted row
    // could pair one with an operator session.
    if (resolved?.principal && isOperatorPrincipal(resolved.principal)) return { principal: resolved.principal, kind: "session" };
  }

  const rawKey = readApiKeyCredential(req);
  if (!rawKey) return null;

  await deps.identityReady;
  const authenticated = await authenticateApiKey({
    deps: apiKeyServiceDepsFrom(deps),
    input: { workspaceId: deps.workspaceId, rawKey },
  });
  return authenticated && isOperatorPrincipal(authenticated.principal)
    ? { principal: authenticated.principal, kind: "api_key" }
    : null;
}

/**
 * Resolve the current request's credential to its principal, discarding which credential it was.
 * Thin wrapper over `currentCredential` — kept because callers that only ever needed "who is
 * calling" should not have to destructure a shape they ignore.
 *
 * @complexity O(1) — see `currentCredential`.
 * @overallScore 100
 */
export async function currentPrincipal(deps: SessionAuthDeps, req: Request,
  options: { localOwnerSignIn?: LocalOwnerSignInPolicy } = {},
): Promise<OperatorPrincipalRecord | null> {
  return (await currentCredential(deps, req, options))?.principal ?? null;
}

/**
 * Read the principal `requireAdminSession` attached to this request. Route
 * handlers under `/api/admin` call this instead of re-parsing the cookie.
 * Throws if called on a request that didn't pass through
 * `requireAdminSession` first — a wiring bug, not a runtime auth outcome.
 */
export function getAuthedPrincipal(res: Response): OperatorPrincipalRecord {
  const principal = res.locals.principal as OperatorPrincipalRecord | undefined;
  if (!principal) {
    throw new Error(
      "getAuthedPrincipal: no principal on res.locals — requireAdminSession must run before this route"
    );
  }
  return principal;
}

/**
 * Read HOW the current request authenticated (SPEC-006 REQ-08). Route families that must stay
 * out of reach of a machine credential call this and refuse anything but `"session"` — the
 * spec-level rule that an API key can never mint, issue, or revoke another API key, which is what
 * keeps key issuance from being a privilege-escalation primitive.
 *
 * Throws if called on a request that didn't pass through `requireAdminSession` first — a wiring
 * bug, not a runtime auth outcome (same contract as `getAuthedPrincipal`).
 */
export function getAuthedCredentialKind(res: Response): AuthCredentialKind {
  const kind = res.locals.authCredentialKind as AuthCredentialKind | undefined;
  if (!kind) {
    throw new Error(
      "getAuthedCredentialKind: no credential kind on res.locals — requireAdminSession must run before this route"
    );
  }
  return kind;
}

/** What every route family that refuses a machine credential sends — identical shape whether the
 *  refusal came from `routes/api-keys/*` or `routes/system/site-key.ts`, so a caller can branch
 *  on `code`/`details.reason` without knowing which family answered. */
export interface CredentialKindForbiddenBody {
  error: string;
  code: "FORBIDDEN";
  details: { permission: string; reason: "credential_kind_not_permitted" };
}

/**
 * The shared "this action must stay out of reach of a machine credential" guard
 * (`getAuthedCredentialKind`'s own doc names the rule). Two route families call this today:
 * `routes/api-keys/deps.ts`'s `rejectApiKeyCredential` (an api_key may never mint, issue, or
 * revoke another key — SPEC-006 REQ-08) and `routes/system/site-key.ts` (an api_key may never
 * read or mint the site key, since a leaked key would then expose every other stored
 * credential). Both need the identical 403 shape, so this is the one place that shape is spelled
 * out; each caller supplies only the wording and the permission name its own 403 body should carry.
 *
 * Runs before any body read or existence check that route performs, so an api_key caller learns
 * nothing beyond "this credential type is not permitted here."
 *
 * @returns `true` when the request may proceed. On `false` the 403 has already been sent.
 * @complexity O(1).
 */
export function rejectUnlessSessionCredential(
  res: Response,
  context: { message: string; permission: string }
): boolean {
  if (getAuthedCredentialKind(res) === "session") return true;

  const body: CredentialKindForbiddenBody = {
    error: context.message,
    code: "FORBIDDEN",
    details: { permission: context.permission, reason: "credential_kind_not_permitted" },
  };
  res.status(403).json(body);
  return false;
}

/**
 * Express middleware factory: reject unauthenticated /api/admin requests; attach the principal,
 * then parse the JSON body at the authenticated limit (`json-body-parsers.ts`).
 *
 * Steps aside for a request `publish-trust-auth.ts`'s `requirePublishTrust` already resolved. That
 * gate mounts immediately before this one and only ever reaches `next()` with a credential
 * attached when it has verified the token's MAC, its audience, its expiry, its grant AND that the
 * request is on a route `grant.ts`'s `PUBLISH_TRUST_ROUTES` names — so by the time this sees the
 * marker, every check this middleware would perform has a stricter counterpart that already ran.
 * `res.locals` is server-side and per-request: no client can set the marker.
 * Credential-store failures go to Express's error handler through `next(error)`.
 */
export function requireAdminSession(deps: SessionAuthDeps,
  { localOwnerSignIn = bootLocalOwnerSignIn }: { localOwnerSignIn?: LocalOwnerSignInPolicy } = {},
) {
  return async function requireAdminSessionMiddleware(
    req: Request,
    res: Response,
    next: NextFunction
  ): Promise<void> {
    try {
      if (res.locals.authCredentialKind === "publish_key") {
        parseAuthenticatedJsonBody(req, res, next);
        return;
      }

      const credential = await currentCredential(deps, req, { localOwnerSignIn });
      if (!credential) {
        res.status(401).json({ error: "unauthenticated", code: "UNAUTHENTICATED" });
        return;
      }
      res.locals.principal = credential.principal;
      res.locals.authCredentialKind = credential.kind;
      // The app-level parser leaves gated paths unparsed, so an anonymous body is never read.
      parseAuthenticatedJsonBody(req, res, next);
    } catch (error) {
      // Forward failed credential resolution; Express 4 drops rejected middleware promises.
      next(error);
    }
  };
}

/**
 * Loopback peer addresses. IPv4-mapped IPv6 (`::ffff:127.0.0.1`) is what Node reports for an IPv4
 * client on a dual-stack listener, so it belongs here; `localhost` deliberately does not, because
 * this is compared against a resolved socket address, never a name.
 */
const LOOPBACK_PEERS = new Set(["127.0.0.1", "::1", "::ffff:127.0.0.1"]);

/**
 * Whether this request came from this machine.
 *
 * Proven from the SOCKET, not inferred from the bind address: `serve.ts` binds `127.0.0.1` by
 * default (LAN-bind plan, 2026-09-23), but `TOVU_HOST` can widen that, and `index.ts` still binds
 * every interface by default — so a remote client is possible on either boot path and this check
 * stays regardless of what either one is currently bound to.
 * `req.ip`/`X-Forwarded-For` are deliberately not consulted — a header is attacker-controlled, and
 * this is the check that stands between a boot token and the network.
 *
 * @complexity O(1).
 */
function isLoopbackPeer(req: Request): boolean {
  const peer = req.socket.remoteAddress;
  return typeof peer === "string" && LOOPBACK_PEERS.has(peer);
}

/**
 * Mint a session row for an already-identified principal and return its raw token.
 *
 * Thin wrapper over `@jini-ai/user-management/server`'s `createSessionForPrincipal` (2026-09-06) — the
 * library's own password-free session minter, factored out of `login()` so this route no longer
 * has to hand-roll session construction. This used to duplicate `auth-service.ts`'s private
 * `hashToken`/token-generation inline (with its own base64url encoding, diverging from the
 * library's hex) because `login()` was the only minter and hard-requires a password; that
 * duplication, and the encoding drift it carried, is gone now that both paths share one minter.
 * The caller still VERIFIES the result through the library's own `validateSession` before handing
 * the cookie out — that check is what would have caught the old drift, and stays as defense in
 * depth even though the shared minter removes the drift's actual cause.
 *
 * @complexity O(1) — one session write (inside the shared minter).
 */
async function mintSessionForPrincipal(deps: SessionAuthDeps, principalId: string): Promise<{ rawToken: string; expiresAt: string }> {
  const { session, rawToken } = await createSessionForPrincipal({
    deps: authServiceDepsFrom(deps),
    input: { workspaceId: deps.workspaceId, principalId },
  }, { sessionTtlMs: SESSION_TTL_MS });
  return { rawToken, expiresAt: session.expiresAt };
}

/** Resolve the seeded boot owner only after identity initialization, refusing non-operators. */
async function resolveBootOwner(
  { deps }: { deps: SessionAuthDeps },
  _optional = {},
): Promise<{ principalId: string; principal: OperatorPrincipalRecord } | null> {
  await deps.identityReady;
  const principalId = await deps.ownerPrincipalId;
  const principal = await deps.principalRepo.findById({ workspaceId: deps.workspaceId, id: principalId });
  if (!principal || principal.status !== "active" || !isOperatorPrincipal(principal)) return null;
  return { principalId, principal };
}

/** Shared desktop/browser exchange: consume once, verify the real session, then set its cookie.
 * Resolves null after sending the existing rejection body. Repository failures propagate.
 * @complexity O(1): a bounded number of principal/session lookups and one session write.
 */
export async function redeemOwnerBootSession(
  { deps, res, token }: { deps: SessionAuthDeps; res: Response; token: unknown },
  { redeem = redeemBootSessionToken, cookieName = SESSION_COOKIE }: { redeem?: (token: unknown) => boolean; cookieName?: string } = {},
): Promise<OperatorPrincipalRecord | null> {
  if (!redeem(token)) {
    res.status(401).json({ error: "invalid or spent boot token", code: "UNAUTHENTICATED" });
    return null;
  }
  const owner = await resolveBootOwner({ deps });
  if (!owner) {
    res.status(500).json({ error: "internal error" });
    return null;
  }
  const { principalId, principal } = owner;
  const { rawToken, expiresAt } = await mintSessionForPrincipal(deps, principalId);
  // The fork guard promised in `mintSessionForPrincipal`'s doc: prove the row this route just
  // wrote is one the library itself will accept, BEFORE setting a cookie on it. Without this, a
  // future change to the library's private token hashing would leave every desktop launch
  // silently unauthenticated with nothing pointing at the cause.
  const confirmed = await validateSession({
    deps: authServiceDepsFrom(deps), input: { workspaceId: deps.workspaceId, rawToken },
  });
  if (!confirmed?.principal) {
    res.status(500).json({ error: "internal error" });
    return null;
  }
  // The ordinary desktop cookie also replaces/clears local bootstrap; revoke what it supersedes.
  if (cookieName === SESSION_COOKIE) await revokeRequestSessions({ deps, req: res.req });
  setSessionCookie(res, rawToken, expiresAt, { name: cookieName });
  return principal;
}

/** Told after an owner or admin signs in. Only the serving app passes one (its automatic form pull);
 * `signedIn` must return at once: it runs after the session cookie is set and is never awaited. */
export interface AdminSignInPort {
  signedIn(required?: Record<string, never>, optional?: Record<string, never>): void;
}

/** The site's owner (an unconstrained `*` holder) or a holder of the built-in `admin` role — the
 * identity feature's two role classifiers, never a permission string, so a custom role that was
 * granted broad permissions does not count. @complexity Owner check first; role lookup only if not.
 */
async function isOwnerOrBuiltinAdmin({ deps, principalId }: { deps: SessionAuthDeps; principalId: string }, _optional = {}): Promise<boolean> {
  const authDeps = authServiceDepsFrom(deps);
  if (await principalHoldsOwnerWildcard({ deps: authDeps, workspaceId: deps.workspaceId, principalId })) return true;
  return principalHoldsBuiltinAdminRole({ deps: authDeps, workspaceId: deps.workspaceId, principalId });
}

/** After a successful sign-in, tells `port` when the principal is the owner or an admin. Returns at
 * once: the role lookup runs in the background, and its failure (or the port's) is logged without
 * any identity detail and never reaches the sign-in response. @complexity O(1) here. */
function signalAdminSignIn({ deps, principalId, port }: { deps: SessionAuthDeps; principalId: string; port: AdminSignInPort | undefined }, _optional = {}): void {
  if (!port) return;
  void isOwnerOrBuiltinAdmin({ deps, principalId })
    .then((eligible) => { if (eligible) port.signedIn(); })
    .catch(() => console.warn("[admin-auth] post-sign-in form pull check failed; sign-in is unaffected"));
}

/** Registers login/logout/me and the loopback boot exchange before the admin session gate.
 * `onAdminSignIn` hears every owner/admin sign-in: password login and both boot-session exchanges. */
export function registerAuthRoutes(app: Express, deps: RouteDeps,
  { localOwnerSignIn = bootLocalOwnerSignIn, onAdminSignIn }: { localOwnerSignIn?: LocalOwnerSignInPolicy; onAdminSignIn?: AdminSignInPort } = {},
): void {
  // REQ-14/AC-18: LOGIN_STRICT (10 req/60s per client IP) brute-force guard on
  // AUTH_LOGIN. One limiter instance per `registerAuthRoutes` call, so each
  // `createApp()`/`createRouteDeps()` pair (and therefore each test's server)
  // gets an isolated counter store rather than sharing process-wide state.
  const loginRateLimiter = createRateLimiter({ profile: LOGIN_STRICT, clock: { nowMs: () => Date.parse(deps.clock.nowIso()) } });

  app.post("/api/admin/v1/auth/login", async (req, res) => {
    try {
      await deps.identityReady;

      // Client-IP resolution (api.spec §3): no explicit trusted-proxy list is supplied here.
      // resolveClientIp falls back to Express's req.ip under the host's trust-proxy policy,
      // or the socket peer; an untrusted X-Forwarded-For is never honored.
      const clientIp = resolveClientIp(req);
      const rateLimitResult = await loginRateLimiter.check({ key: clientIp });
      if (!rateLimitResult.allowed) {
        res.setHeader("Retry-After", String(rateLimitResult.retryAfterSeconds));
        res.status(429).json({
          error: "too many login attempts",
          code: "RATE_LIMIT_EXCEEDED",
          details: { retryAfterSeconds: rateLimitResult.retryAfterSeconds },
        });
        return;
      }

      const username = String(req.body?.username ?? "");
      const password = String(req.body?.password ?? "");

      const { principal, session, rawToken } = await login({
        deps: authServiceDepsFrom(deps),
        input: {
          workspaceId: deps.workspaceId,
          username,
          password,
        },
      }, {
        ip: req.ip,
        userAgent: req.get("user-agent") ?? undefined,
        sessionTtlMs: SESSION_TTL_MS,
      });

      // Credentials succeeded; revoke both superseded bearers before clearing/replacing cookies.
      await revokeRequestSessions({ deps, req });
      setSessionCookie(res, rawToken, session.expiresAt);
      signalAdminSignIn({ deps, principalId: principal.id, port: onAdminSignIn });
      res.json({ user: { id: principal.id, username } });
    } catch (err) {
      if (err instanceof AuthInvalidCredentialsError) {
        res.status(401).json({ error: "invalid username or password", code: "UNAUTHENTICATED" });
        return;
      }
      res.status(500).json({ error: "internal error" });
    }
  });

  app.post("/api/admin/v1/auth/logout", async (req, res) => {
    // Express 4 drops a rejected async handler, so without this a failing identity bootstrap or
    // session store leaves the request hanging instead of answering like the login route does.
    try {
      await deps.identityReady;
      await revokeRequestSessions({ deps, req });
      clearSessionCookie(res);
      res.json({ ok: true });
    } catch {
      res.status(500).json({ error: "internal error" });
    }
  });

  /**
   * Exchange a single-use boot token for an ordinary admin session.
   *
   * Exists so a process that STARTED this server can prove it started it without knowing a
   * password. The token is minted only when the launcher passed `--emit-boot-token`, lives in this
   * process's memory for one launch, and is destroyed on first redemption
   * (`features/identity/boot-session-token.ts`).
   *
   * **This route knows nothing about who is calling it.** No desktop/Electron branch, no
   * `TOVU_DESKTOP_*` name — the contract is only "a valid single-use loopback token starts a
   * session", so nothing here has to change or be removed if a particular launcher goes away.
   *
   * Every rejection is a flat 401 with no distinguishing detail: unarmed, wrong, and already-spent
   * are indistinguishable to a caller, so this cannot be used as an oracle for whether a token
   * exists. There is deliberately NO arm in which an unminted token means "allow" — an unarmed
   * store refuses every input, so an ordinary `tovu serve` (which mints nothing) has this route
   * present but permanently closed.
   *
   * The session it creates is an ordinary one: a real, revocable `sessions` row bound to the seeded
   * owner principal, resolved by the same `validateSession` and gated by the same `authorize()` as
   * a password login. Nothing downstream can tell the difference, and no bypass flag is threaded
   * anywhere.
   */
  app.post("/api/admin/v1/auth/boot-session", async (req, res, next) => {
    // Checked before the token is even looked at, so a remote caller cannot probe redemption.
    if (!isLoopbackPeer(req)) {
      res.status(403).json({ error: "boot-session is loopback-only", code: "FORBIDDEN" });
      return;
    }
    try {
      const principal = await redeemOwnerBootSession({ deps, res, token: req.body?.token });
      if (!principal) return;
      signalAdminSignIn({ deps, principalId: principal.id, port: onAdminSignIn });
      res.json({ user: { id: principal.id } });
    } catch (error) { next(error); }
  });

  // Desktop must present its private launch capability before browser-style header admission.
  // The browser has no private parent stdout pipe. A launcher-armed, same-origin loopback
  // request uses a request-scoped one-time token; no raw boot token is exposed to JS or logs.
  // Separate stores prevent concurrent tabs, or the desktop's still-armed token, burning each other.
  app.post("/api/admin/v1/auth/local-boot-session", async (req, res, next) => {
    if (!localOwnerSignIn.enabled || (localOwnerSignIn.acceptsCapability &&
      !localOwnerSignIn.acceptsCapability({ capability: req.get("x-tovu-desktop-owner-signin") }))) {
      res.status(404).json({ error: "local owner sign-in is disabled", code: "NOT_FOUND" });
      return;
    }
    if (!isLoopbackPeer(req) || !allowsLocalOwnerSignInRequest({
      host: req.headers.host, origin: req.get("origin"), fetchSite: req.get("sec-fetch-site"),
      fetchMode: req.get("sec-fetch-mode"), headers: req.headers,
    })) {
      res.status(403).json({ error: "local owner sign-in requires a same-origin loopback request", code: "FORBIDDEN" });
      return;
    }
    res.setHeader("Cache-Control", "no-store");
    try {
      // Keep an existing human session; auto sign-in must never promote a non-owner account.
      const existing = await currentPrincipal(deps, req, { localOwnerSignIn });
      if (existing) { res.json({ user: { id: existing.id } }); return; }
      const store = createBootSessionTokenStore();
      const principal = await redeemOwnerBootSession({ deps, res, token: store.mint() }, {
        redeem: store.redeem, cookieName: localSessionCookieName(req),
      });
      if (!principal) return;
      signalAdminSignIn({ deps, principalId: principal.id, port: onAdminSignIn });
      res.json({ user: { id: principal.id } });
    } catch (error) { next(error); }
  });

  app.get("/api/admin/v1/auth/me", async (req, res) => {
    const principal = await currentPrincipal(deps, req, { localOwnerSignIn });
    if (!principal) {
      res.status(401).json({ error: "unauthenticated", code: "UNAUTHENTICATED" });
      return;
    }

    const userRow = await deps.userRepo.findByPrincipalId({
      workspaceId: deps.workspaceId,
      principalId: principal.id,
    });
    const effectivePermissions = await getEffectivePermissions({
      deps: identityReposFrom(deps),
      input: { workspaceId: deps.workspaceId, principalId: principal.id },
    });
    // Delete-user plan v2 (2026-09-24), Slice 4 — the admin Users screen's row-menu Delete item
    // needs to know, for the SIGNED-IN caller, whether they are actually allowed to trash/restore/
    // purge users (the OWNER DECISION 2026-09-24 gate: owner or the built-in `admin` role — see
    // `delete-user-service.ts`'s `callerMayManageUserTrash` for why that is NOT the same test as
    // `effectivePermissions.includes("*")`: the built-in admin role deliberately holds no `user.
    // manage`/`*` grant, so a permission-string check alone would hide a working affordance from an
    // admin-role caller even though the DELETE route itself already lets them use it). Reuses the
    // exact function the route layer and the Trash restore/purge override both gate on, so this
    // affordance-hiding flag can never drift from the real boundary — see that function's own doc
    // comment ("NOT A SECURITY BOUNDARY", `lib/permissions.ts`'s header on the admin side).
    const authServiceDeps = authServiceDepsFrom(deps);
    const canManageUserTrash = await callerMayManageUserTrash({
      deps: authServiceDeps,
      workspaceId: deps.workspaceId,
      callerPrincipalId: principal.id,
    });

    res.json({
      user: { id: principal.id, username: userRow?.username ?? principal.displayName },
      effectivePermissions,
      canManageUserTrash,
      // Affordance flag, not the boundary: the admin hides every Publish entry point when this is
      // `false` (the live site); the push routes refuse on their own (`live-site-policy.ts`).
      canPublishToLive: canPublishToLive(),
    });
  });

  // Password-banner plan (2026-09-24), Slice 2: tells the DASHBOARD (not deployment-overview,
  // which is owner-only and `system.read`-gated) whether the SIGNED-IN CALLER's own stored
  // credential still verifies against `DEFAULT_OWNER_PASSWORD`. No extra permission is needed —
  // it's a check against your own row, so it can't be used to probe anyone else's password.
  // Deliberately a separate route from `/auth/me` rather than a field on it: that route runs on
  // every admin boot, and only the dashboard needs the ~tens-of-ms argon2id verify this adds.
  //
  // Results are memoized by the stored hash: argon2id is deliberately expensive, and a signed-in
  // session could otherwise call this in a loop. A hash is salted per write, so any password change
  // produces a new key and is re-verified — the cache can never report a stale answer. Capped and
  // cleared wholesale; it only holds hashes already in the DB and booleans.
  const defaultPasswordByHash = new Map<string, boolean>();
  const usesDefaultPasswordFor = async (passwordHash: string): Promise<boolean> => {
    const cached = defaultPasswordByHash.get(passwordHash);
    if (cached !== undefined) return cached;
    const result = await deps.passwordHasher.verify({ hash: passwordHash, password: DEFAULT_OWNER_PASSWORD });
    if (defaultPasswordByHash.size >= 256) defaultPasswordByHash.clear();
    defaultPasswordByHash.set(passwordHash, result);
    return result;
  };
  app.get("/api/admin/v1/auth/me/password-status", async (req, res) => {
    const principal = await currentPrincipal(deps, req, { localOwnerSignIn });
    if (!principal) {
      res.status(401).json({ error: "unauthenticated", code: "UNAUTHENTICATED" });
      return;
    }

    const userRow = await deps.userRepo.findByPrincipalId({
      workspaceId: deps.workspaceId,
      principalId: principal.id,
    });
    const usesDefaultPassword = userRow
      ? await usesDefaultPasswordFor(userRow.passwordHash)
      : false;

    res.json({ usesDefaultPassword });
  });
}

import { createAgentPluginUpdateEffects, requireUpdateMcpDeps } from "#src/features/agent-plugins/update-effects";
import type { Request, RequestHandler, Response } from "express";
import { raw } from "express";

import { maxAgentPluginInstallArchiveBytes } from "../../../../../features/agent-plugins/lifecycle.js";
import { installUploadedAgentPlugin } from "#src/features/agent-plugins/install-upload";
import { isAgentPluginName } from "@jini-ai/agent-plugins/lifecycle";
import { loadAgentPluginSearchCandidates } from "#src/features/agent-plugins/tool-registrations";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { AgentPluginsRouteDeps, AgentPluginsRouteRegistrar } from "./deps.js";
import { bodyParseRefusal, installErrorResponse, installedAgentPluginRow, type InstallRefusal } from "./install-response.js";

/**
 * @file `AGENT_PLUGIN_INSTALL_ZIP` — `POST /api/admin/v1/workspaces/:workspaceId/agent-plugins/install/zip?expectedSha256=<hex>`
 * (2026-10-06). The Agent Plugins screen's "Add a plugin" upload. Raw `application/zip` body, the
 * same transport `routes/plugins/install.ts` uses for site plugins; all install work is
 * `installUploadedAgentPlugin` (`features/agent-plugins/install-upload.ts`), which goes through
 * the one `installAgentPlugin` the bundled seed uses and leaves the plugin switched off.
 *
 * No `TOVU_PLUGIN_LOCAL_INSTALL` opt-in, unlike site plugins: those packages run server code, while
 * nothing in an uploaded Agent Plugin runs (`trusted-plugin-files.ts` trusts bundled digests only).
 * Gated on `admin.plugins.enable`, the permission the enable switch beside it already needs.
 *
 * Answers 201 with the new row in `list.ts`'s shape, or 200 when the same bytes were already there.
 * Error bodies carry a code and a plain message; no host path ever reaches them.
 *
 * `AGENT_PLUGIN_UPDATE_ZIP` — `POST .../agent-plugins/:pluginId/update/zip?expectedSha256=&expectedOldDigest=`
 * (2026-10-21) shares this handler: the same upload checks, then `installUploadedAgentPlugin({ update })`,
 * which hands the candidate to the lifecycle owner's update transaction. `expectedOldDigest` is the
 * row's `archiveDigest` the operator saw; a changed, bundled, pending or downgraded plugin is a 409
 * with the owner's code. Answers 200 with the updated row and any compatibility warnings.
 */

const DIGEST_REFUSAL: InstallRefusal = { status: 400, body: { code: "VALIDATION_ERROR", error: "expectedSha256 must be the file's lowercase hex SHA-256." } };
const NOT_ZIP_REFUSAL: InstallRefusal = { status: 400, body: { code: "VALIDATION_ERROR", error: "An application/zip upload is required." } };
const REPLACE_REFUSAL: InstallRefusal = { status: 400, body: { code: "VALIDATION_ERROR", error: "replace must be true or false." } };
const PLUGIN_ID_REFUSAL: InstallRefusal = { status: 400, body: { code: "VALIDATION_ERROR", error: "pluginId is not a valid Agent Plugin id." } };
const OLD_DIGEST_REFUSAL: InstallRefusal = { status: 400, body: { code: "VALIDATION_ERROR", error: "expectedOldDigest must be the installed revision's lowercase hex SHA-256." } };

/** Which installed revision an update replaces: the URL's plugin id and the digest the operator saw. */
interface UpdateTarget {
  readonly pluginId: string;
  readonly expectedOldDigest: string;
}

/** A checked upload: the zip bytes, the digest the client computed, and whether to replace. */
interface ZipUpload {
  readonly archive: Buffer;
  readonly expectedSha256: string;
  readonly replace: boolean;
}

/** Sends a refusal, logging its operator-side warning first when it has one. */
function sendRefusal(res: Response, refusal: InstallRefusal): void {
  if (refusal.warning) console.warn(refusal.warning);
  res.status(refusal.status).json(refusal.body);
}

/**
 * Checks the query and reads the raw zip body, in this order: digest, content type, body, replace.
 * Runs only after authorization, so no unauthorized request gets its body parsed.
 * @complexity O(b) in body bytes, capped by the raw parser's limit.
 */
async function readZipUpload(required: { req: Request; res: Response; parseZip: RequestHandler }): Promise<ZipUpload | InstallRefusal> {
  const { req, res, parseZip } = required;
  const expectedSha256 = req.query.expectedSha256;
  if (typeof expectedSha256 !== "string" || !/^[a-f0-9]{64}$/.test(expectedSha256)) return DIGEST_REFUSAL;
  // ZIP parsing follows authorization, as in `routes/plugins/install.ts`.
  if (!req.is("application/zip")) return NOT_ZIP_REFUSAL;
  const parseError = await new Promise<unknown>((resolve) => parseZip(req, res, (error?: unknown) => resolve(error)));
  if (parseError) return bodyParseRefusal(parseError);

  const replace = req.query.replace;
  if (replace !== undefined && replace !== "true" && replace !== "false") return REPLACE_REFUSAL;
  return { archive: req.body as Buffer, expectedSha256, replace: replace === "true" };
}

/** The update target from the URL and query, or the refusal for a malformed one. A plain install
 *  has no target. Checked after authorization and before the body is read.
 *  @complexity O(1). */
function readUpdateTarget({ req }: { req: Request }, _optional: Record<string, never> = {}): { update?: UpdateTarget } | InstallRefusal {
  if (req.params.pluginId === undefined) return {};
  const pluginId = req.params.pluginId;
  // The Agent Plugins name grammar (`plugin.json` `name`), owned by Jini's manifest parser: the URL id
  // is checked against it before it names anything on disk.
  if (!isAgentPluginName({ value: pluginId })) return PLUGIN_ID_REFUSAL;
  const expectedOldDigest = req.query.expectedOldDigest;
  if (typeof expectedOldDigest !== "string" || !/^[a-f0-9]{64}$/.test(expectedOldDigest)) return OLD_DIGEST_REFUSAL;
  return { update: { pluginId, expectedOldDigest } };
}

/** The installer's optional ports; an update adds its MCP effects and settings-snapshot owner. */
function installOptions(required: { deps: AgentPluginsRouteDeps; actor: string }, optional: { update?: UpdateTarget } = {}) {
  const { deps, actor } = required;
  const base = { layout: deps.agentPluginLayout, pluginHost: deps.pluginHost };
  if (!optional.update) return base;
  return { ...base, mcpProvisioning: createAgentPluginUpdateEffects({ deps: requireUpdateMcpDeps({ deps }), actor }), snapshotSettings: deps.snapshotAgentPluginSettings };
}

export const registerAgentPluginInstallRoute: AgentPluginsRouteRegistrar = (app, deps) => {
  const parseZip = raw({ type: "application/zip", limit: maxAgentPluginInstallArchiveBytes(), inflate: false });
  const installHandler: RequestHandler = async (req, res) => {
    if (String(req.params.workspaceId) !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }
    try {
      const principal = getAuthedPrincipal(res);
      if (!(await authorizeOrRespond(res, deps.authorize, { principalId: principal.id, permission: "admin.plugins.enable", workspaceId: deps.workspaceId }))) return;
      const target = readUpdateTarget({ req });
      if ("status" in target) return sendRefusal(res, target);
      const upload = await readZipUpload({ req, res, parseZip });
      if ("status" in upload) return sendRefusal(res, upload);
      const result = await installUploadedAgentPlugin({ ...upload, workspaceId: deps.workspaceId, actor: principal.id, ...target },
        installOptions({ deps, actor: principal.id }, target));
      const candidate = (await loadAgentPluginSearchCandidates(deps)).find((entry) => entry.pluginId === result.plugin.pluginId);
      // An update replaces an existing row, so it is never 201.
      const status = result.alreadyInstalled || target.update ? 200 : 201;
      res.status(status).json({ alreadyInstalled: result.alreadyInstalled, warnings: result.warnings ?? [], agentPlugin: installedAgentPluginRow(candidate) });
    } catch (error) {
      const refusal = installErrorResponse(error);
      // A 500 is redacted for the client, so the operator's log is the only place its cause survives.
      if (refusal.status === 500) console.error("[agent-plugins] install/update request failed", error);
      sendRefusal(res, refusal);
    }
  };
  app.post("/api/admin/v1/workspaces/:workspaceId/agent-plugins/install/zip", installHandler);
  app.post("/api/admin/v1/workspaces/:workspaceId/agent-plugins/:pluginId/update/zip", installHandler);
};

import type { Request, Response } from "express";

import { pluginMemory } from "#src/features/agent-plugins/memory";
import { listInstalledPlugins } from "../../../../../features/agent-plugins/lifecycle.js";
import { DEFAULT_PLUGIN_MEMORY_LIMITS } from "@jini-ai/agent-plugins/persistent-state";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { AgentPluginsRouteDeps, AgentPluginsRouteRegistrar } from "./deps.js";

/** A note write: exactly `entryPath` and `text`, both strings. */
interface NoteWrite {
  readonly entryPath: string;
  readonly text: string;
}

/**
 * True only for an object whose keys are exactly `entryPath` and `text`, both strings.
 * @complexity O(k) in the body's key count.
 */
function isNoteWrite(body: unknown): body is NoteWrite {
  return !(!body || typeof body !== "object" || Array.isArray(body) ||
    Object.keys(body).some(key => key !== "entryPath" && key !== "text") ||
    !("entryPath" in body) || typeof body.entryPath !== "string" || !("text" in body) || typeof body.text !== "string");
}

/**
 * Validates and writes one user note, answering the refusal itself.
 * @returns false when a refusal was sent.
 * @complexity O(k) validation plus one note write.
 */
async function writeNoteOrRespond(required: { body: unknown; memory: ReturnType<typeof pluginMemory>; res: Response }): Promise<boolean> {
  const { body, memory, res } = required;
  if (!isNoteWrite(body)) {
    res.status(400).json({ error: "entryPath and text are required", code: "VALIDATION_ERROR" }); return false;
  }
  try { await memory.writeNote({ entryPath: body.entryPath, text: body.text }); }
  catch { res.status(422).json({ error: "note path, text or size is invalid", code: "PLUGIN_MEMORY_INVALID" }); return false; }
  return true;
}

/** @complexity O(p) in installed plugin count. */
async function isInstalled(deps: AgentPluginsRouteDeps, pluginId: string): Promise<boolean> {
  const workspace = deps.agentPluginLayout.forWorkspace(deps.workspaceId);
  return (await listInstalledPlugins(workspace.root)).some(plugin => plugin.pluginId === pluginId);
}

/** The user's notes editor writes notes only; learned knowledge stays separately readable. */
export const registerAgentPluginMemoryRoutes: AgentPluginsRouteRegistrar = (app, deps) => {
  const url = "/api/admin/v1/workspaces/:workspaceId/agent-plugins/:pluginId/memory";
  const handle = (write: boolean) => async (req: Request, res: Response) => {
    if (String(req.params.workspaceId) !== deps.workspaceId) { res.status(404).json({ error: "workspace was not found" }); return; }
    try {
      const principal = getAuthedPrincipal(res);
      if (!(await authorizeOrRespond(res, deps.authorize, { principalId: principal.id,
        permission: write ? "admin.plugins.enable" : "admin.plugins.read", workspaceId: deps.workspaceId }))) return;
      const pluginId = String(req.params.pluginId);
      if (!(await isInstalled(deps, pluginId))) {
        res.status(404).json({ error: "agent plugin was not found", code: "AGENT_PLUGIN_NOT_FOUND" }); return;
      }
      const memory = pluginMemory({ workspaceId: deps.workspaceId, pluginId }, { layout: deps.agentPluginLayout });
      if (write && !(await writeNoteOrRespond({ body: req.body, memory, res }))) return;
      const [learned, notes] = await Promise.all([memory.list({ kind: "learned" }), memory.list({ kind: "notes" })]);
      res.json({ pluginId, learned, notes, limits: DEFAULT_PLUGIN_MEMORY_LIMITS });
    } catch { res.status(500).json({ error: "internal error", code: "INTERNAL_ERROR" }); }
  };
  app.get(url, handle(false));
  app.put(url, handle(true));
};

import { resolveExecutionCredential, resolveSiteAssistantApiKey } from "#src/assistant/index";
import type { AssistantExecutionRouteDeps } from "./execution-deps.js";

/**
 * @file The single chokepoint deciding WHICH key a BYOK probe sends and WHERE it sends it, shared by
 * `test-connection.ts` and `list-models.ts`.
 *
 * ## Two stored credentials, two opt-ins
 *
 * There are exactly three keys a probe can carry, and this module is where that choice is made:
 * the one typed into the request body, the workspace's SITE credential (`useStoredCredential`), and
 * the calling admin's OWN execution credential (`useAdminStoredCredential`). The last two are
 * separate flags on purpose and must never be merged into one "use whatever is stored": they are
 * different secrets belonging to different subjects, and the screens that probe them are different
 * screens. Collapsing them would let the AI Assistant tab silently probe the admin's personal key,
 * or Settings → Execution mode silently probe the visitor's — the exact confusion ADR-058 §5 makes
 * structural.
 *
 * ## The boundary this exists to hold
 *
 * ADR-058 makes the SITE credential write-only: `get-site-credential.ts` returns `isSet` + `masked`
 * and never the key, so not even an `admin.assistant.manage` holder can read back a key someone else
 * saved. Both probe routes then take `useStoredCredential: true`, decrypt that key server-side, and
 * make one outbound call with it.
 *
 * Those two facts are only compatible if the CALLER cannot choose the destination. Before this
 * module they could: `baseUrl` came from the request body, so a single authenticated request could
 * name any host and have the server deliver the decrypted key to it — turning a write-only secret
 * into a readable one, silently, with nothing persisted and nothing to notice afterwards.
 *
 * The SSRF guard in `@jini-ai/agent-runtime`'s `connection-guard.ts` does not close this and was
 * never meant to. It blocks loopback/RFC1918/link-local/CGNAT/multicast — *internal* address space,
 * to stop a caller pivoting into the server's own network. A public host an attacker controls is
 * exactly what it is designed to let through, because that is what every real provider is.
 *
 * ## The rule
 *
 * A key the caller supplied goes wherever the caller says. It is their secret, typed into their own
 * form; sending it to a host they named is the operation they asked for, and `AiAssistant.tsx`'s
 * `runKeyTest` documents that consent explicitly.
 *
 * A key the caller CANNOT read goes only where the server already recorded it belongs. The stored
 * row carries its own `baseUrl` (`site-credential-store.ts`'s `ResolvedSiteAssistantCredential`);
 * that value, not the request body's, is what reaches the wire. The distinction is consent: an
 * operator can consent with their own credential and cannot consent with one they have never seen.
 *
 * ## Why a mismatch is a 400 rather than a silent substitution
 *
 * Both are equally safe — either way the caller's string never reaches the network. Rejecting is
 * chosen because substituting would make the probe answer a question nobody asked: an operator who
 * switched the endpoint field to Anthropic and pressed "Test connection" would get a green result
 * measured against the stored Google endpoint, and reasonably read it as "Anthropic works". A 400
 * naming both endpoints is the honest answer, and it is also the correct one on the merits — a key
 * issued for one provider cannot meaningfully be probed against another. Type a key for the new
 * endpoint, or save the endpoint first.
 *
 * ## What this deliberately does NOT close
 *
 * `put-site-credential.ts` lets the same `admin.assistant.manage` principal write `baseUrl`. Such a
 * principal can therefore still point the stored credential at a host they control and have the key
 * delivered there. That path is not silent the way this one was: it persists, `get-site-credential`
 * reports it back, it shows in the admin UI, and it breaks the live visitor assistant
 * (`server/modules/site-assistant.ts` uses the same stored endpoint) — so it is self-revealing where
 * a body parameter left no trace at all. Closing it properly means constraining which endpoints may
 * be STORED, which is an allow-list and a product decision: `connection-guard.ts` deliberately
 * permits loopback for local Ollama, and real deployments point at custom gateways. That belongs in
 * the credential-write route with an explicit policy, not smuggled in here.
 */

/** Mirrors `connection-guard.ts`'s own `validateBaseUrl` normalization (`trim()` then strip trailing
 *  slashes) so this comparison agrees with the string the guard would actually parse — a stored
 *  `"https://x/"` and a requested `"https://x"` are the same endpoint and must not read as a
 *  mismatch. Deliberately does NOT lowercase: a URL's host is case-insensitive but its path is not,
 *  and folding case here would let `/V1` and `/v1` compare equal. */
function normalizeEndpoint(baseUrl: string): string {
  return String(baseUrl).trim().replace(/\/+$/, "");
}

export interface ProbeCredentialRejection {
  error: string;
  code: "STORED_CREDENTIAL_ENDPOINT_UNSET" | "STORED_CREDENTIAL_ENDPOINT_MISMATCH";
}

export type ProbeCredentialResolution =
  | { ok: true; apiKey: string; baseUrl: string }
  | { ok: false; failure: ProbeCredentialRejection };

export interface ResolveProbeCredentialInput {
  /** The endpoint from the request body. Used as-is for a caller-supplied key; used only as a
   *  equality check against the stored endpoint when the stored key is in play. */
  requestedBaseUrl: string;
  /** The key from the request body, if any. Non-empty always wins — see this file's header. */
  typedKey: string;
  /** `body.useStoredCredential === true`, already narrowed by the caller. Must stay an explicit
   *  opt-in and never be softened to "empty key ⇒ use the stored one": these routes are shared with
   *  Settings → Execution mode, whose key is a DIFFERENT credential (the admin's own), and an
   *  implicit fallback would let an operator with an empty field silently probe with the visitor
   *  credential. */
  useStoredCredential: boolean;
  /**
   * `body.useAdminStoredCredential === true`. Opts in to the CALLING PRINCIPAL'S OWN
   * `admin_execution_credentials` row — never another principal's, because the row is looked up by
   * the session's `principalId` (passed here from `getAuthedPrincipal`), not by anything in the
   * request.
   *
   * Same explicit-opt-in rule as `useStoredCredential`, for the same reason, and the two are
   * deliberately not one flag — see this file's header.
   *
   * Defaults to `false`, so every existing caller is unaffected.
   */
  useAdminStoredCredential?: boolean;
  /** The session principal, required only when `useAdminStoredCredential` is set. Must come from
   *  `getAuthedPrincipal(res)` and NEVER from the request body: it is the whole reason this branch
   *  can only ever open the caller's own row. */
  principalId?: string;
}

/**
 * Resolves the `(apiKey, baseUrl)` pair a probe should actually use, or the rejection to return.
 *
 * @returns `ok: true` with the exact values to hand to `@jini-ai/agent-runtime`. When the stored
 * credential is used, `baseUrl` is the SERVER's own stored string rather than the caller's — the two
 * are known equal by then, so this changes no behavior, but it means the bytes on the wire are the
 * ones the server approved. Same pin-what-you-validated discipline `connection-guard.ts`'s
 * `pinnedFetch` applies to the resolved address.
 *
 * A missing row, an unset key, a missing site key and a corrupt ciphertext all arrive from
 * `resolveSiteAssistantApiKey` as `null` and are treated identically to "no stored key": the probe
 * proceeds with an empty key against the requested endpoint, letting the provider return its own
 * auth error, which is a truer message than a synthesized one. Nothing is exposed by that path —
 * there is no secret to protect in any of those cases.
 *
 * @complexity O(1) — at most one repo read plus one decrypt. No unbounded collection, no per-item
 * I/O, no caller-controlled iteration: the resource-bounds pre-check has nothing to cap here.
 * @overallScore 100
 */
export async function resolveProbeCredential(
  deps: AssistantExecutionRouteDeps,
  input: ResolveProbeCredentialInput
): Promise<ProbeCredentialResolution> {
  if (input.typedKey.trim()) {
    return { ok: true, apiKey: input.typedKey, baseUrl: input.requestedBaseUrl };
  }
  if (!input.useStoredCredential && !input.useAdminStoredCredential) {
    return { ok: true, apiKey: "", baseUrl: input.requestedBaseUrl };
  }

  if (input.useAdminStoredCredential) {
    return resolveStoredCredentialAgainstItsOwnEndpoint(
      await resolveExecutionCredential(
        // One sealing capability app-wide — `siteAssistantSecretSealer` is the same sealer
        // `assistant-byok.ts` and `live-model-cache.ts` open this row with. See
        // `routes/types.ts`'s `adminExecutionCredentialRepo` doc.
        { repo: deps.adminExecutionCredentialRepo, sealer: deps.siteAssistantSecretSealer },
        { workspaceId: deps.workspaceId, principalId: String(input.principalId ?? "") }
      ),
      input.requestedBaseUrl,
      "admin execution credential"
    );
  }

  return resolveStoredCredentialAgainstItsOwnEndpoint(
    await resolveSiteAssistantApiKey(
      { repo: deps.siteAssistantCredentialRepo, sealer: deps.siteAssistantSecretSealer },
      { workspaceId: deps.workspaceId }
    ),
    input.requestedBaseUrl,
    "stored site assistant credential"
  );
}

/**
 * The endpoint pin, shared by both stored-credential branches: a key the caller cannot read may
 * only be sent to the endpoint the SERVER already recorded for it.
 *
 * Extracted rather than duplicated per credential because the rule is a property of "the caller
 * cannot consent to this destination", not of which row the key came from — and a second copy is
 * exactly how one of the two would eventually drift into accepting a body-supplied endpoint. Both
 * stored credentials are write-only to the same permission, so both need it identically.
 *
 * @param stored - The resolved credential, or `null` for every "there is nothing to protect here"
 *   outcome (no row, no key, missing site key, corrupt ciphertext). `null` returns an empty key
 *   against the requested endpoint, letting the provider return its own auth error — a truer message
 *   than a synthesized one, and nothing is exposed because there is no secret in play.
 * @param requestedBaseUrl - The endpoint from the request body. Compared, never sent.
 * @param subject - How the credential is named in the two rejection messages.
 * @returns The `(apiKey, baseUrl)` pair to put on the wire — always the SERVER's own stored
 *   endpoint string, not the caller's, so the bytes sent are the ones the server approved.
 * @complexity O(1) — two string normalizations and one comparison.
 */
function resolveStoredCredentialAgainstItsOwnEndpoint(
  stored: { apiKey: string; baseUrl: string | null } | null,
  requestedBaseUrl: string,
  subject: string
): ProbeCredentialResolution {
  if (!stored) {
    return { ok: true, apiKey: "", baseUrl: requestedBaseUrl };
  }

  if (!stored.baseUrl?.trim()) {
    return {
      ok: false,
      failure: {
        error: `the ${subject} has no saved endpoint, so this probe has no approved destination — save a base URL for the credential first, or supply an apiKey in this request`,
        code: "STORED_CREDENTIAL_ENDPOINT_UNSET",
      },
    };
  }

  if (normalizeEndpoint(stored.baseUrl) !== normalizeEndpoint(requestedBaseUrl)) {
    return {
      ok: false,
      failure: {
        // Naming the stored endpoint leaks nothing: `get-site-credential.ts` and
        // `get-execution-credential.ts` both already return `baseUrl` in full to this exact
        // permission. Only the key is write-only.
        error: `the ${subject} is saved for '${stored.baseUrl}' and cannot be probed against '${requestedBaseUrl}' — save the new endpoint first, or supply an apiKey for it in this request`,
        code: "STORED_CREDENTIAL_ENDPOINT_MISMATCH",
      },
    };
  }

  return { ok: true, apiKey: stored.apiKey, baseUrl: stored.baseUrl };
}

import type { Express, Response } from "express";

import type { CommentWriteService, CommentStatus, ModerationAction } from "@jini-ai/cms/comments";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";

/**
 * @file ADR-031 §6/§9 (SPEC-033) — the 5 moderation action routes (approve/spam/trash/restore/
 * purge). One file, not five — the 5 actions are near-identical (permission check → parse
 * expectedVersion → call the write-service → map the result to a status code), so a single
 * parameterized registrar per action is a reasonable simplification over 5 near-duplicate files
 * (Article III). Each still registers its OWN route/permission pairing explicitly, not a generic
 * `/action/:verb` dispatcher — route paths and permission strings stay grep-able and explicit.
 */
export type AdminCommentsModerateDeps = Pick<RouteDeps, "workspaceId" | "authorize"> & {
  commentWriteService: CommentWriteService;
};

interface ActionSpec {
  path: string;
  permission: string;
  action: ModerationAction;
  toStatus: CommentStatus | null; // null = purge, which has no toStatus
}

/**
 * v1 simplification: `restore` always targets `approved`, regardless of whether the comment was
 * previously `trash` or `spam` — the moderation_log's own `fromStatus` still records exactly
 * which, so this is a UX default (an operator restoring anything wants it visible again), not a
 * loss of audit information.
 */
const ACTIONS: readonly ActionSpec[] = [
  { path: "approve", permission: "comments.moderate", action: "approve", toStatus: "approved" },
  { path: "spam", permission: "comments.moderate", action: "mark_spam", toStatus: "spam" },
  { path: "trash", permission: "comments.delete", action: "trash", toStatus: "trash" },
  { path: "restore", permission: "comments.moderate", action: "restore", toStatus: "approved" },
];

function parseExpectedVersion(raw: unknown): number | null {
  const n = typeof raw === "number" ? raw : typeof raw === "string" ? Number(raw) : NaN;
  return Number.isInteger(n) && n >= 0 ? n : null;
}

/** This route's `{expectedVersion, note}` body, read once — `null` means `expectedVersion` failed
 *  validation. @complexity O(1). */
function parseModerationBody(rawBody: unknown): { expectedVersion: number; note: string | null } | null {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  const expectedVersion = parseExpectedVersion(body.expectedVersion);
  if (expectedVersion === null) return null;
  return { expectedVersion, note: typeof body.note === "string" ? body.note : null };
}

/** Writes the response for a completed `applyModeration` call — 204 on success, the
 *  not-found/version-conflict split mapped from `result.reason` otherwise. @complexity O(1). */
function respondToModerationResult(res: Response, result: Awaited<ReturnType<CommentWriteService["applyModeration"]>>): void {
  if (!result.ok) {
    const status = result.reason === "not-found" ? 404 : 409;
    res.status(status).json({ error: result.reason, currentVersion: "currentVersion" in result ? result.currentVersion : undefined });
    return;
  }
  res.status(204).end();
}

export function registerAdminCommentsModerateRoutes(app: Express, deps: AdminCommentsModerateDeps): void {
  for (const spec of ACTIONS) {
    app.post(`/api/admin/v1/workspaces/:workspaceId/comments/:commentId/${spec.path}`, async (req, res) => {
      if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
        res.status(404).json({ error: "workspace was not found" });
        return;
      }

      try {
        const principal = getAuthedPrincipal(res);
        const authResult = await deps.authorize({
          principalId: principal.id,
          permission: spec.permission,
          workspaceId: deps.workspaceId,
          entityType: "comment",
          entityId: req.params.commentId,
        });
        if (!authResult.allowed) {
          res.status(403).json({
            error: `principal '${principal.id}' is not authorized for '${spec.permission}' (${authResult.reason})`,
            code: "FORBIDDEN",
            details: { permission: spec.permission, reason: authResult.reason },
          });
          return;
        }

        const parsedBody = parseModerationBody(req.body);
        if (!parsedBody) {
          res.status(400).json({ error: "expectedVersion is required and must be a non-negative integer" });
          return;
        }

        const result = await deps.commentWriteService.applyModeration({
          workspaceId: deps.workspaceId,
          id: req.params.commentId,
          expectedVersion: parsedBody.expectedVersion,
          action: spec.action,
          toStatus: spec.toStatus!,
          actorPrincipalId: principal.id,
          note: parsedBody.note,
        });

        respondToModerationResult(res, result);
      } catch (err) {
        console.error(`[comments/moderate] unexpected error applying '${spec.action}'`, err);
        res.status(500).json({ error: "internal error", code: "INTERNAL_ERROR" });
      }
    });
  }

  app.post("/api/admin/v1/workspaces/:workspaceId/comments/:commentId/purge", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "comments.delete.force",
        workspaceId: deps.workspaceId,
        entityType: "comment",
        entityId: req.params.commentId,
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'comments.delete.force' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "comments.delete.force", reason: authResult.reason },
        });
        return;
      }

      const body = req.body as Record<string, unknown>;
      const result = await deps.commentWriteService.purge({
        workspaceId: deps.workspaceId,
        id: req.params.commentId,
        actorPrincipalId: principal.id,
        note: typeof body.note === "string" ? body.note : null,
      });

      if (!result.ok) {
        res.status(404).json({ error: result.reason });
        return;
      }
      res.status(204).end();
    } catch (err) {
      console.error("[comments/moderate] unexpected error purging a comment", err);
      res.status(500).json({ error: "internal error", code: "INTERNAL_ERROR" });
    }
  });
}

import type { Express } from "express";

import { readCommerceStatus } from "@jini-ai/commerce";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";

/** Dependencies required by the Commerce status transport adapter. */
export type AdminCommerceStatusDeps = Pick<RouteDeps, "workspaceId" | "authorize"> & { lipay?: import("@jini-ai/commerce").CommercePaymentRuntimePort };

/**
 * Registers the authenticated, workspace-scoped Commerce operational-status endpoint.
 *
 * The handler performs no payment operation and reads no credentials. Its only runtime query is
 * the narrow provider catalog exposed through `readCommerceStatus`.
 *
 * @param app - Express application receiving the route.
 * @param deps - Tenant, authorization, and optional payment-runtime dependencies.
 * @returns Nothing; registration mutates only the supplied Express router.
 * @throws Unexpected authorization or adapter programming failures follow the app's existing
 * Express error path; expected workspace and permission failures are returned as 404/403.
 *
 * @complexity Registration is O(1). Each request is O(p + c), where p is registered payment
 * providers and c is their declared capability array entries; no external I/O is performed here.
 */
export function registerAdminCommerceStatusRoute(
  app: Express,
  deps: AdminCommerceStatusDeps
): void {
  app.get("/api/admin/v1/workspaces/:workspaceId/commerce/status", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "admin.integrations.manage",
        workspaceId: deps.workspaceId,
        entityType: "integration",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'admin.integrations.manage' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "admin.integrations.manage", reason: authResult.reason },
        });
        return;
      }

      res.status(200).json(
        readCommerceStatus({
          workspaceId: deps.workspaceId,
          resolvePaymentRuntime: () => deps.lipay ?? null,
        })
      );
    } catch (err) {
      // Adapter exceptions may contain secrets; return only the fixed error response.
      res.status(500).json({ error: "internal error", code: "INTERNAL_ERROR" });
    }
  });
}

import type { Express } from "express";

import { acquireOperationLock, releaseOperationLock } from "#src/contracts/core/operation-lock";
import { authorizeForHooks, confirm, execute, ForbiddenError, PlanStaleError, plan, type GatedMutationHooks } from "#src/contracts/core/gated-mutations/gateway";
import { TokenAlreadyRedeemedError, TokenExpiredError } from "#src/contracts/core/gated-mutations/token";
import {
  executeMigrateForward,
  MigrationAlreadyInFlightError,
  RestorePointUnavailableError,
} from "#src/features/database/migrate-forward/execute";
import { buildConfirmOnlyHooks } from "#src/contracts/core/gated-mutations/composition";
import { buildMigrateForwardHooks } from "#src/features/database/gated-hooks";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";

/**
 * @file SPEC-017 C-103/C-105 — `POST /api/admin/v1/database/migrate-forward/{plan,confirm,execute}`
 * (ADR-041 §3's forward-migrate ceremony). Gated by `database.read` (`plan`) / `database.migrate`
 * (`confirm`/`execute`). Mirrors `routes/admin/taxonomy/merge-term.ts`'s 3-endpoint shape — the
 * `/execute` step additionally wires `core/operation-lock.ts`'s cross-domain lock via
 * `migrate-forward/execute.ts`'s own `executeMigrateForward` orchestration wrapper (U-003-ORD1:
 * lock acquired strictly before the gateway's own `execute()` runs).
 */
function statusFor(err: unknown): { status: number; code: string } {
  if (err instanceof ForbiddenError) return { status: 403, code: err.reasonCode };
  if (err instanceof PlanStaleError) return { status: 409, code: "PLAN_STALE" };
  if (err instanceof TokenExpiredError) return { status: 409, code: "TOKEN_EXPIRED" };
  if (err instanceof TokenAlreadyRedeemedError) return { status: 409, code: "TOKEN_ALREADY_REDEEMED" };
  if (err instanceof RestorePointUnavailableError) return { status: 409, code: "RESTORE_POINT_UNAVAILABLE" };
  if (err instanceof MigrationAlreadyInFlightError) return { status: 409, code: "OPERATION_IN_FLIGHT" };
  return { status: 500, code: "INTERNAL_ERROR" };
}

export function registerAdminDatabaseMigrateForwardRoutes(app: Express, deps: RouteDeps): void {
  app.post("/api/admin/v1/database/migrate-forward/plan", async (_req, res) => {
    try {
      const principal = getAuthedPrincipal(res);
      const hooks = buildMigrateForwardHooks({
        workspaceId: deps.workspaceId,
        actorId: principal.id,
        clock: deps.clock,
        idGen: deps.idGen,
        dbOps: deps.dbOps,
        restorePointsRepo: deps.restorePointsRepo,
        databaseLedgerRepo: deps.databaseLedgerRepo,
      });

      const result = await plan({
        deps: deps.gatedMutations.gatewayDeps,
        principalId: principal.id,
        principalKind: "user",
        hooks: hooks as unknown as GatedMutationHooks<unknown, unknown>,
      });

      res.json(result);
    } catch (err) {
      const { status, code } = statusFor(err);
      res.status(status).json({ error: err instanceof Error ? err.message : "internal error", code });
    }
  });

  app.post("/api/admin/v1/database/migrate-forward/confirm", async (req, res) => {
    try {
      const principal = getAuthedPrincipal(res);
      const { planId, planHash } = req.body ?? {};
      if (typeof planId !== "string" || typeof planHash !== "string") {
        res.status(400).json({ error: "'planId' and 'planHash' (strings) are required", code: "VALIDATION_ERROR" });
        return;
      }

      const hooks = buildConfirmOnlyHooks({
        domain: "database.migrate",
        readPermission: "database.read",
        mutatePermission: "database.migrate",
        scopeId: deps.workspaceId,
        scopeKind: "instance",
      });

      const record = await confirm({
        deps: deps.gatedMutations.gatewayDeps,
        principalId: principal.id,
        principalKind: "user",
        hooks,
        planId,
        planHash,
      });

      res.json({ confirmationToken: record.confirmationToken });
    } catch (err) {
      const { status, code } = statusFor(err);
      res.status(status).json({ error: err instanceof Error ? err.message : "internal error", code });
    }
  });

  app.post("/api/admin/v1/database/migrate-forward/execute", async (req, res) => {
    try {
      const principal = getAuthedPrincipal(res);

      // Audit finding AUD-001 (2026-07-16, external audit TM-20260716-full-session-001):
      // executeMigrateForward acquires the shared cross-domain operation lock strictly before
      // gatewayExecute() runs (U-003-ORD1) -- that ordering exists for mutation-failure/lock-leak
      // safety, not authorization, so an unauthorized-but-authenticated caller could still reach
      // and briefly hold the lock before the gateway's own authorize() rejected them, contending
      // with a concurrent authorized migration. Authorize inline, before any lock acquisition; the
      // gateway's fresh authorize() re-check at execute time (CIC U-001) remains the authoritative
      // check and is unchanged by this.
      //
      // Routed through `authorizeForHooks` (not a hardcoded `deps.authorize` workspace-scoped
      // call) with `scopeKind: "instance"` -- `database.migrate`'s real scope, per
      // `features/database/gated-hooks.ts`'s `buildMigrateForwardHooks` doc comment -- so this
      // pre-check agrees with what `execute()`'s own internal check will decide. A hardcoded
      // workspace-scoped check here would let a workspace-scoped-but-not-instance-authorized
      // caller pass this gate, briefly hold the lock, and only then be rejected deeper inside
      // `execute()` -- reopening the very race AUD-001 closed, one layer up.
      const authResult = await authorizeForHooks(
        deps.gatedMutations.gatewayDeps,
        buildConfirmOnlyHooks({
          domain: "database.migrate",
          readPermission: "database.read",
          mutatePermission: "database.migrate",
          scopeId: deps.workspaceId,
          scopeKind: "instance",
        }),
        { principalId: principal.id, permission: "database.migrate" }
      );
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'database.migrate' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "database.migrate", reason: authResult.reason },
        });
        return;
      }

      const { confirmationToken } = req.body ?? {};
      if (typeof confirmationToken !== "string") {
        res.status(400).json({ error: "'confirmationToken' (string) is required", code: "VALIDATION_ERROR" });
        return;
      }

      const hooks = buildMigrateForwardHooks({
        workspaceId: deps.workspaceId,
        actorId: principal.id,
        clock: deps.clock,
        idGen: deps.idGen,
        dbOps: deps.dbOps,
        restorePointsRepo: deps.restorePointsRepo,
        databaseLedgerRepo: deps.databaseLedgerRepo,
      });

      const capabilities = await deps.dbOps.getCapabilities();

      const result = await executeMigrateForward({
        siteId: deps.workspaceId,
        confirmationToken,
        costClass: capabilities.restorePoint.costClass,
        operationLock: { acquireOperationLock, releaseOperationLock },
        gatewayExecute: () =>
          execute({
            deps: deps.gatedMutations.gatewayDeps,
            principalId: principal.id,
            principalKind: "user",
            hooks: hooks as unknown as GatedMutationHooks<unknown, { migrated: true }>,
            confirmationToken,
          }),
      });

      res.json(result);
    } catch (err) {
      const { status, code } = statusFor(err);
      res.status(status).json({ error: err instanceof Error ? err.message : "internal error", code });
    }
  });
}

import type { Express, Request, Response } from "express";

import { probeExternalMcpServer, type ExternalMcpProbeServiceDeps } from "#src/server/runtime/services/external-mcp-probe";
export type { ExternalMcpProbeSessionFactory } from "#src/server/runtime/services/external-mcp-probe";
import { OUTBOUND_CALL_PER_IP, createRateLimiter, resolveClientIp, type RateLimiter } from "#src/contracts/core/rate-limit/rate-limit";
import type { ExternalMcpRouteDeps } from "./deps.js";
import { guardExternalMcpRequest } from "./guard.js";

/**
 * @file `POST .../mcp-servers/:serverId/probe` (C-007) — connects to ONE configured server, once,
 * lists its tools, describes the surface, and closes. Registers nothing into any `ToolRegistry`, so
 * R5 (`mcp-federation/trust.ts`'s "frozen at connect") is untouched by this route — see the
 * write-tools implementation outline §3.1/C-4 for the full argument that a probe run in the admin
 * web server cannot un-freeze anything the daemon holds.
 *
 * ## D-7: hosted connections only
 *
 * A `stdio` row is refused before anything is attempted, rather than spawned. The daemon already
 * pays the cost of a local-command child process at boot, with its own timeout and its own
 * catch-and-close (`mcp-federation/bootstrap.ts`); this on-demand admin action is a strictly worse
 * place for that risk to live a second time — a leaked child here is a leaked child in the process
 * serving the whole admin UI, not a subprocess the daemon already knows how to reap. The motivating
 * connection (Higgsfield) is hosted, so this is not a regression for the case that exists today; a
 * `stdio` operator keeps the plain text-field path exactly as it works now.
 *
 * ## Rate limiting sits IN FRONT of the guard
 *
 * Same ordering `oauth.ts` uses and for the same reason: a hit that will be rejected by the
 * permission check has still made this process reach for an outbound socket on the operator's own
 * credentials if the limiter did not run first.
 *
 * ## INV-006 — no secret in the response
 *
 * The response body is built ONLY from `describeRemoteToolSurface`'s output — a pure function over
 * the remote's `tools/list` reply and the two operator name lists (`mcp-federation/trust.ts`). It
 * never touches the resolved launch spec's headers/env, so there is no code path by which a bearer
 * token, a client secret, or an env value could reach this route's response. Any other error this
 * route can raise is either fixed, Tovu-authored copy, or a stored failure REASON string that
 * `external-mcp-store.ts` itself already guarantees is secret-free (it exists specifically to be
 * shown to the operator). See this file's test for the direct property assertion.
 */

export type ExternalMcpProbeRouteDeps = ExternalMcpRouteDeps & ExternalMcpProbeServiceDeps;

/** Builds this route's own probe rate limiter. Reuses {@link OUTBOUND_CALL_PER_IP} rather than
 *  a new profile: a probe is the same self-DoS shape that profile already names — a real outbound
 *  call using the workspace's own credentials — with its own instance so a burst on one connector
 *  family never eats another's budget. */
export function createExternalMcpProbeLimiter(deps: Pick<ExternalMcpRouteDeps, "clock">): RateLimiter {
  return createRateLimiter({ profile: OUTBOUND_CALL_PER_IP, clock: deps.clock });
}

/** Answers the shared limiter check, writing the 429 itself. Mirrors `oauth.ts`'s
 *  `withinRateLimit` — not imported from there, so this route stays independent of a sibling
 *  family's file (see the implementation outline's own "different failure modes, different copy"
 *  argument for why `probe.ts` and `admissions.ts` are separate files in the first place). */
async function withinProbeRateLimit(limiter: RateLimiter, req: Request, res: Response): Promise<boolean> {
  const result = await limiter.check({ key: resolveClientIp(req) });
  if (result.allowed) return true;
  res.setHeader("Retry-After", String(result.retryAfterSeconds));
  res.status(429).json({
    error: "too many probe attempts",
    code: "RATE_LIMIT_EXCEEDED",
    details: { retryAfterSeconds: result.retryAfterSeconds },
  });
  return false;
}

/**
 * `POST .../mcp-servers/:serverId/probe`.
 *
 * @complexity O(t) in the remote's advertised tool count, plus one round trip.
 */
export function registerAdminExternalMcpProbeRoute(app: Express, deps: ExternalMcpProbeRouteDeps, limiter: RateLimiter): void {
  app.post("/api/admin/v1/workspaces/:workspaceId/mcp-servers/:serverId/probe", async (req, res) => {
    if (!(await withinProbeRateLimit(limiter, req, res))) return;
    try {
      if (!(await guardExternalMcpRequest(deps, req.params.workspaceId, res))) return;
      const serverId = String(req.params.serverId ?? "");

      const outcome = await probeExternalMcpServer(deps, serverId);
      res.status(outcome.ok ? 200 : outcome.status).json(outcome.body);
    } catch (error) {
      // eslint-disable-next-line no-console
      console.error("external-mcp probe route failed");
      res.status(500).json({ error: "internal error", code: "INTERNAL_ERROR" });
    }
  });
}

import type { MediaRecord } from "#src/features/media/index";
import type { MediaRouteDeps } from "./deps.js";

type ByteSizeDeps = Pick<MediaRouteDeps, "workspaceId" | "assetBlobRepo" | "blobStore">;
/** The one field this reads from each `MediaRecord`: its source blob's content hash. */
type ByteSizeMedia = { readonly source: Pick<MediaRecord["source"], "sha256"> };

/** Only the returned media batch is visited; original keys come from the blob repo port.
 * LocalFsBlobStore memoizes successful stat results by content-addressed key. Older built Jini
 * adapters remain importable and report unknown until their sizeOf capability is available.
 * One missing/unreadable blob must not prevent the operator from seeing the rest of the library.
 */
export async function resolveMediaByteSizes(
  { deps, media }: { deps: ByteSizeDeps; media: readonly ByteSizeMedia[] },
  _optional: Record<string, never> = {},
): Promise<Map<string, number | null>> {
  const sha256s = [...new Set(media.map((item) => item.source.sha256))];
  const sizes = new Map<string, number | null>();
  // Structural capability check also supports the installed declaration before Jini is rebuilt.
  const store = deps.blobStore as ByteSizeDeps["blobStore"] & {
    sizeOf?: (required: { storageKey: string }, optional?: Record<string, never>) => Promise<number | null>;
  };
  let cursor = 0;
  const worker = async () => {
    while (cursor < sha256s.length) {
      const sha256 = sha256s[cursor++]!;
      let size: number | null = null;
      try {
        if (store.sizeOf) {
          const blob = await deps.assetBlobRepo.findByHash({ workspaceId: deps.workspaceId, sha256 });
          if (blob) size = await store.sizeOf({ storageKey: blob.storageKey });
        }
      } catch {
        // Per-row failure stays unknown; the adapter does not cache absent/error results.
      }
      sizes.set(sha256, size);
    }
  };
  await Promise.all(Array.from({ length: Math.min(8, sha256s.length) }, worker));
  return sizes;
}

import { replaceMediaFile } from '@jini-ai/cms/media';
import type { Express, Response } from 'express';
import { decodeStrictBase64 } from '#src/contracts/core/index';
import { DEFAULT_ALLOWED_MIME_TYPES, MediaValidationError, TOVU_MAX_UPLOAD_BYTES,
  resolveUploadContentType, type MediaRecord } from '#src/features/media/index';
import { getAuthedPrincipal } from '#src/server/inbound/admin-http/dev-auth';
import type { MediaRouteDeps } from './deps.js';
import { authorizeMediaOrRespond, readRouteParam, rejectForeignWorkspace, sendMediaNotFound,
  sendValidationOrInternalError } from './route-guards.js';
import { toStoredMediaResponse } from './stored-media-response.js';

/** The declared content type and base64 payload, refused unless the filename, type and payload are
 *  all non-empty strings. @complexity O(1). */
function readReplacementFields({ body }: { body: unknown }): { contentType: string; dataBase64: string } {
  const values = (body ?? {}) as Record<string, unknown>;
  const { filename, contentType, dataBase64 } = values;
  if (typeof filename !== 'string' || !filename.trim() || typeof contentType !== 'string' || !contentType ||
    typeof dataBase64 !== 'string' || !dataBase64) {
    throw new MediaValidationError({ message: 'filename, contentType, and dataBase64 are required' });
  }
  return { contentType, dataBase64 };
}

/** Decodes and verifies the replacement bytes: strict base64, within the host upload cap, and an
 *  allowed type as sniffed from the bytes (not the declared label). A non-empty strict-base64
 *  payload always decodes to at least one byte, and `replaceMediaFile` refuses empty bytes too.
 *  @complexity O(n) in the payload length. */
function parseReplacement({ body }: { body: unknown }) {
  const { contentType, dataBase64 } = readReplacementFields({ body });
  const bytes = decodeStrictBase64(dataBase64);
  if (!bytes) throw new MediaValidationError({ message: 'dataBase64 is not valid base64' });
  if (bytes.byteLength > TOVU_MAX_UPLOAD_BYTES) {
    throw new MediaValidationError({ message: `uploaded file exceeds the ${TOVU_MAX_UPLOAD_BYTES / (1024 * 1024)} MB size cap` });
  }
  const verified = resolveUploadContentType({ bytes, declaredContentType: contentType });
  if (!DEFAULT_ALLOWED_MIME_TYPES.has(verified)) {
    throw new MediaValidationError({ message: `content type '${verified}' is not allowed for upload` });
  }
  return { bytes, contentType: verified };
}

/** Loads the asset to replace, or writes the refusal and returns `null`: 404 when it does not exist,
 *  409 when it is trashed, 503 when the repository cannot switch a file transactionally. Runs before
 *  the body is decoded. @complexity O(1) — one indexed lookup. */
async function findReplaceableMedia({ deps, res, id }: { deps: MediaRouteDeps; res: Response; id: string }): Promise<MediaRecord | null> {
  const media = await deps.mediaRepo.findById({ workspaceId: deps.workspaceId, id });
  if (!media) { sendMediaNotFound({ res, mediaId: id }); return null; }
  if (media.status !== 'active') {
    res.status(409).json({ error: 'trashed media cannot be replaced', code: 'ENTITY_IN_TRASH' }); return null;
  }
  if (typeof deps.mediaRepo.replaceFileIfVersion !== 'function' ||
    typeof deps.mediaRepo.saveRenditionIfSource !== 'function') {
    res.status(503).json({ error: 'media file replacement is unavailable', code: 'MEDIA_REPLACE_UNAVAILABLE' }); return null;
  }
  return media;
}

/** Same JSON upload protocol and per-entity permission as the host's media metadata route.
 * Source replacement is explicit; PATCH metadata still cannot change a source hash. */
export function registerAdminMediaReplaceRoute({ app, deps }: { app: Express; deps: MediaRouteDeps },
  _optional: Record<string, never> = {}): void {
  app.post('/api/admin/v1/workspaces/:workspaceId/media/:mediaId/replace', async (req, res) => {
    if (rejectForeignWorkspace({ req, res, workspaceId: deps.workspaceId })) return;
    try {
      const id = readRouteParam({ req, name: 'mediaId' });
      const principal = getAuthedPrincipal(res);
      const authorized = await authorizeMediaOrRespond({ res, authorize: deps.authorize, params: { principalId: principal.id,
        permission: 'media.update', workspaceId: deps.workspaceId, entityType: 'media', entityId: id } });
      if (!authorized) return;
      const media = await findReplaceableMedia({ deps, res, id });
      if (!media) return;
      const upload = parseReplacement({ body: req.body });
      const saved = await replaceMediaFile({ deps, media, ...upload, principalId: principal.id }, { maxUploadBytes: TOVU_MAX_UPLOAD_BYTES });
      if (!saved) {
        res.status(409).json({ error: 'media changed while replacing its file', code: 'MEDIA_REPLACE_CONFLICT' }); return;
      }
      res.json(await toStoredMediaResponse({ deps, media: saved, contentType: upload.contentType, byteLength: upload.bytes.byteLength }));
    } catch (error) {
      sendValidationOrInternalError({ res, error });
    }
  });
}

import type { Express, Response } from 'express';
import { MediaNotFoundError, MediaValidationError, readDocumentText } from '@jini-ai/cms/media';
import { getAuthedPrincipal } from '#src/server/inbound/admin-http/dev-auth';
import type { MediaRouteDeps } from './deps.js';

/** Private source reads share Library tools' 64 KiB UTF-8 paging policy. Authorize before bytes. */
export function registerAdminMediaTextRoute(required: { app: Express; deps: MediaRouteDeps },
  _optional: Record<string, never> = {}): void {
  const { app, deps } = required;
  app.get('/api/admin/v1/workspaces/:workspaceId/media/:mediaId/text', async (req, res) => {
    res.set('Cache-Control', 'private, no-store').set('X-Content-Type-Options', 'nosniff');
    if (String(req.params.workspaceId) !== deps.workspaceId) { res.status(404).json({ error: 'workspace was not found' }); return; }
    try {
      const principal = getAuthedPrincipal(res);
      const id = String(req.params.mediaId);
      const access = await deps.authorize({ principalId: principal.id, permission: 'media.read', workspaceId: deps.workspaceId, entityType: 'media', entityId: id });
      if (!access.allowed) { res.status(403).json({ error: 'media.read is required', code: 'FORBIDDEN' }); return; }
      res.json(await readDocumentText({ deps: { mediaRepo: deps.mediaRepo, blobRepo: deps.assetBlobRepo, blobStore: deps.blobStore },
        input: { workspaceId: deps.workspaceId, id, offset: parseTextOffset(req.query.offset) } }));
    } catch (error) {
      sendTextReadFailure({ res, error });
    }
  });
}

/** An omitted offset pages from byte 0; anything but a run of decimal digits is refused before any read.
 *  @complexity O(n) in the offset's length. */
function parseTextOffset(rawOffset: unknown): number {
  if (rawOffset === undefined) return 0;
  if (typeof rawOffset !== 'string' || !/^\d+$/u.test(rawOffset)) throw new MediaValidationError({ message: 'offset must be a non-negative byte offset' });
  return Number(rawOffset);
}

/** 404 for a missing document, 400 for a refused read, otherwise a private 500.
 *  @complexity O(1). */
function sendTextReadFailure({ res, error }: { res: Response; error: unknown }): void {
  const status = error instanceof MediaNotFoundError ? 404 : error instanceof MediaValidationError ? 400 : 500;
  res.status(status).json({ error: status === 500 ? 'internal error' : (error as Error).message });
}

import { captureMediaUploaded } from "#src/features/media/analytics";
import { MAX_DOCUMENT_BYTES, documentContentType, type MediaKind } from "@jini-ai/cms/media";
import { createDocumentArchiveReader } from "#src/features/media/document-archive";
import type { Request, Response } from "express";

import { MediaConflictError, MediaValidationError, resolveUploadContentType, TOVU_MAX_UPLOAD_BYTES, uploadMedia } from "#src/features/media/index";
import { decodeStrictBase64 } from "#src/contracts/core/index";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { MediaRouteRegistrar } from "./deps.js";
import { parseOptionalStringField } from "./parse.js";
import { authorizeMediaOrRespond, rejectForeignWorkspace, sendValidationOrInternalError } from "./route-guards.js";
import { toStoredMediaResponse } from "./stored-media-response.js";

/** An upload request's fields after {@link parseUploadRequestFields}. */
interface UploadRequestFields {
  kind: MediaKind;
  filename: string;
  contentType: string;
  dataBase64: string;
  alt: string | undefined;
  caption: string | undefined;
  credit: string | undefined;
}

/** An omitted `kind` is an ordinary media upload; anything other than `media`/`document` is refused.
 *  @complexity O(1). */
function parseUploadKind(raw: unknown): MediaKind {
  const kind = raw ?? "media";
  if (kind !== "media" && kind !== "document") throw new MediaValidationError({ message: "invalid media kind" });
  return kind;
}

/** The three required upload fields plus the three optional metadata fields, parsed off an untyped
 *  body in one place, or `null` if a required field is missing or the wrong shape. `dataBase64` must
 *  be a non-empty string — an absent or non-string value is rejected here rather than reaching
 *  `Buffer.from`. `alt`/`caption`/`credit` go through `parse.js`'s `parseOptionalStringField`, which
 *  throws `MediaValidationError` for a non-string, non-null, non-undefined value — the caller MUST
 *  invoke this inside a `try`/`catch` (or otherwise catch synchronously), not treat it as
 *  throw-free the way the `null` return above is. On upload there is no existing value to preserve,
 *  so an explicit `null` here is equivalent to omitting the field (both end up `""` — see
 *  `uploadMedia`'s `input.alt?.trim() ?? ""`), unlike `update.ts`'s PATCH route where `null` clears
 *  a possibly-non-empty existing value.
 *  @complexity O(1). */
function parseUploadRequestFields(rawBody: unknown): UploadRequestFields | null {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  const kind = parseUploadKind(body.kind);
  const filename = typeof body.filename === "string" ? body.filename : "";
  const contentType = String(body.contentType ?? "");
  const dataBase64 = body.dataBase64;
  if (!filename || (kind === "media" && !contentType) || typeof dataBase64 !== "string" || !dataBase64) {
    return null;
  }
  return {
    kind,
    filename,
    contentType,
    dataBase64,
    alt: parseOptionalStringField(body.alt, "alt"),
    caption: parseOptionalStringField(body.caption, "caption"),
    credit: parseOptionalStringField(body.credit, "credit"),
  };
}

/**
 * Runs {@link parseUploadRequestFields} and turns both of its failure modes — a thrown
 * `MediaValidationError` (malformed `alt`/`caption`/`credit`) and a `null` return (a required field
 * missing or the wrong shape) — into an already-written 400 response, returning `null` either way
 * so the route handler can bail with one `if (!fields) return;` instead of nesting its own
 * try/catch. Pulled out of the handler to stay under this repo's complexity ceiling, and because
 * this synchronous parse call must be caught here rather than left to the handler's own try/catch
 * further down: Express 4 does not catch a synchronous throw from an async handler outside a
 * try/catch (see the `getAuthedPrincipal` comment below) — an uncaught throw here would hang the
 * request instead of 400ing it.
 *
 * @complexity O(1).
 */
function parseUploadRequestFieldsOrRespond(
  req: Request,
  res: Response
): ReturnType<typeof parseUploadRequestFields> {
  let fields: ReturnType<typeof parseUploadRequestFields>;
  try {
    fields = parseUploadRequestFields(req.body);
  } catch (error) {
    sendValidationOrInternalError({ res, error });
    return null;
  }
  if (!fields) {
    res.status(400).json({ error: "filename, contentType, and dataBase64 are required" });
  }
  return fields;
}

/**
 * Decodes the upload's bytes and verifies their content type, throwing `MediaValidationError` for
 * an over-long document payload or invalid base64.
 *
 * @complexity O(n) in the encoded payload length.
 */
function decodeUploadPayload(
  { kind, filename, contentType, dataBase64 }: Pick<UploadRequestFields, "kind" | "filename" | "contentType" | "dataBase64">,
): { bytes: Uint8Array; contentType: string } {
  // Refuse document base64 inflation before allocation, then let the shared ingress owner
  // check actual bytes. Authorization precedes decoding, archive work, and storage I/O.
  if (kind === "document" && dataBase64.length > 4 * Math.ceil(MAX_DOCUMENT_BYTES / 3)) {
    throw new MediaValidationError({ message: "document exceeds the 10 MiB limit" });
  }
  // `decodeStrictBase64`, not `Buffer.from(x, "base64")`: the latter never throws (it skips
  // characters outside the alphabet instead of refusing them), so a bare try/catch around it can
  // never fire — see that function's own header.
  const bytes = decodeStrictBase64(dataBase64);
  if (!bytes) throw new MediaValidationError({ message: "dataBase64 is not valid base64" });
  // Trust sniffed bytes rather than the client label. HTML/unknown bytes are rejected;
  // uploadMedia sanitizes accepted SVG before hashing/storage.
  const verified = kind === "document" ? documentContentType({ filename }) : resolveUploadContentType({ bytes, declaredContentType: contentType });
  return { bytes, contentType: verified };
}

/** Slug allocation is a courtesy lookup before save. Concurrent uploads can choose the same free
 *  slug; the durable repo enforces uniqueness with `MediaConflictError` (409). Otherwise a validation
 *  failure is 400 and anything else a private 500.
 *  @complexity O(1). */
function sendUploadFailure({ res, error }: { res: Response; error: unknown }): void {
  if (error instanceof MediaConflictError) {
    res.status(409).json({ error: error.message });
    return;
  }
  sendValidationOrInternalError({ res, error });
}

/**
 * POST a new media upload. Gated by `media.upload` (SPEC-021 REQ-39/OQ-01, ADR-027 §7).
 *
 * Request body is JSON with base64-encoded bytes (`dataBase64`) rather than a
 * multipart/form-data stream — this repo has no multipart-parsing dependency
 * yet (no `multer` in `package.json`), and adding one is out of scope for this
 * walking skeleton. This is a real, disclosed simplification: a production
 * upload path should stream bytes (multipart or raw octet-stream), not
 * base64-inflate them through JSON. `express.json()`'s body-size limit was
 * bumped in `server/app.ts` to accommodate this (see that file's comment).
 */
export const registerAdminMediaUploadRoute: MediaRouteRegistrar = (app, deps) => {
  app.post("/api/admin/v1/workspaces/:workspaceId/media", async (req, res) => {
    if (rejectForeignWorkspace({ req, res, workspaceId: deps.workspaceId })) return;

    const fields = parseUploadRequestFieldsOrRespond(req, res);
    if (!fields) return;
    const { kind, filename, alt, caption, credit } = fields;

    try {
      // Inside the try: requireAdminSession always sets res.locals.principal before this
      // route runs, but Express 4 doesn't catch a synchronous throw from an async handler
      // outside try/catch (the request would otherwise hang instead of 500ing).
      const principal = getAuthedPrincipal(res);
      const authorized = await authorizeMediaOrRespond({ res, authorize: deps.authorize, params: {
        principalId: principal.id,
        permission: "media.upload",
        workspaceId: deps.workspaceId,
        entityType: "media",
      } });
      if (!authorized) return;

      const { bytes, contentType: verifiedContentType } = decodeUploadPayload(fields);

      const { media } = await uploadMedia({
        deps: {
          clock: deps.clock,
          idGen: deps.idGen,
          mediaRepo: deps.mediaRepo,
          blobRepo: deps.assetBlobRepo,
          renditionRepo: deps.assetRenditionRepo,
          blobStore: deps.blobStore,
          documentArchiveReader: createDocumentArchiveReader({}),
        },
        input: {
          workspaceId: deps.workspaceId,
          kind,
          bytes,
          filename,
          contentType: verifiedContentType,
          alt,
          caption,
          credit,
          createdByPrincipal: principal.id,
        },
      }, { maxUploadBytes: TOVU_MAX_UPLOAD_BYTES });

      // Only media uses the per-blob sniff cache; document type is its validated filename policy.
      // Record the sniffed type so the admin's type filter agrees with what `original.ts` serves
      // (it never trusts the upload-time string either). Written AFTER `uploadMedia` because the
      // blob row it updates is created there.
      if (kind === "media") await deps.mediaContentTypeStore.set({
        workspaceId: deps.workspaceId,
        sha256: media.source.sha256,
        contentType: verifiedContentType,
      });

      const family = verifiedContentType.split("/")[0];
      captureMediaUploaded({ tracker: deps.tracker, actorId: principal.id, byteLength: bytes.byteLength,
        kind: kind === "document" ? "document" : family === "image" || family === "audio" || family === "video" ? family : "other", source: "admin" });
      res.status(201).json(await toStoredMediaResponse({ deps, media, contentType: verifiedContentType, byteLength: bytes.byteLength }));
    } catch (error) {
      sendUploadFailure({ res, error });
    }
  });
};

import { createMemberAccessResolver } from "#src/features/members/index";
import type { JsonObject } from "@jini-ai/core/primitives";

import { type PublicPostRecord as PostRecord } from "#src/features/post/index";
import { getPresentationSettings } from "#src/features/presentation/index";
import { postPublicPath } from "#src/platform/routing/adapter";
import { isBarePageChoice, NO_THEME_ID, resolveTemplateBranchChoice } from "#src/features/theme/index";
import {
  renderViaTemplate,
  resolveActiveTheme,
  resolveHtmlEmbedsForRender,
  resolveMediaAssetMetadataForRender,
  resolveMediaTransformVersionsForRender,
  resolveStaticMenusForRender,
  resolveWidgetsForRender,
} from "#src/server/inbound/public-http/routes/site/pages";
import { renderBareEntryDocument } from "../../../public-http/http/site/bare-page.js";
import { resolveSiteTitle } from "#src/features/settings/index";

import type { ContentRouteDeps } from "../content/deps.js";

/**
 * Never persisted — a shallow clone rendered once for this response and discarded.
 *
 * `pendingBodyHtml` is only ever applied when `post.bodyFormat === "html"` — a `"doc"`-format post
 * has no HTML body to preview, and applying it there would silently disagree with the
 * `bodyJson` override on the same clone.
 *
 * @complexity O(1).
 */
function buildPreviewPost(
  post: PostRecord,
  overrideTemplateChoice: string | null,
  pendingBodyJson: JsonObject | undefined,
  pendingBodyHtml: string | undefined
): PostRecord {
  return {
    ...post,
    templateChoice: overrideTemplateChoice,
    ...(pendingBodyJson !== undefined ? { bodyJson: pendingBodyJson } : {}),
    ...(pendingBodyHtml !== undefined && post.bodyFormat === "html" ? { bodyHtml: pendingBodyHtml } : {}),
  };
}

/**
 * Bare-page preview (owner ruling 2026-09-23, S5) — mirrors `pages.ts`'s own `renderBarePage`, but
 * built from `ContentRouteDeps`-compatible (Pick-typed) exports only, since this route's `deps` is
 * narrower than the full `RouteDeps` those two functions require. Inline `widgetEmbed` nodes resolve
 * through `resolveWidgetsForRender(deps, null, post)`, the same `theme: null` call the live bare
 * render makes: a doc-format Page can be bare too (the `templateChoice` query/API, not only the Pages
 * picker), and skipping it previewed every inline widget as the placeholder. Skips the SEO
 * `extraHead` fold (`buildExtraHead` is private to `pages.ts` and needs `originRegistry`, not in
 * `ContentRouteDeps`) — a disclosed, low-stakes trim: this is a never-indexed admin iframe, not the
 * public site S4 already covers.
 */
async function renderBarePreview(deps: ContentRouteDeps, post: PostRecord): Promise<string> {
  const [siteTitle, widgets, pageHtmlEmbeds, mediaTransformVersions, mediaAssetMetadata] = await Promise.all([
    resolveSiteTitle(
      {
        settingsRepo: deps.settingsRepo,
        preservationStore: deps.siteTitlePreservationStore,
        workspaceRepo: deps.workspaceRepo,
        siteDisplayName: deps.siteDisplayName,
      },
      { workspaceId: deps.workspaceId }
    ),
    resolveWidgetsForRender(deps, null, post),
    resolveHtmlEmbedsForRender(deps, post),
    resolveMediaTransformVersionsForRender(deps),
    resolveMediaAssetMetadataForRender(deps, post),
  ]);
  return renderBareEntryDocument({
    post,
    siteTitle,
    pageHtmlEmbeds,
    widgetInlineResolved: widgets.inlineResolved,
    mediaTransformVersions,
    mediaAssetMetadata,
  });
}

/** The route preserves these state-conflict statuses; the tool publishes the actionable message. */
export class TemplatePreviewRenderError extends Error {
  constructor(readonly status: number, message: string) { super(message); this.name = "TemplatePreviewRenderError"; }
}
export interface PostPreviewRenderInput {
  post: PostRecord;
  templateChoice?: string | null | undefined;
  bodyJson?: JsonObject | undefined;
  bodyHtml?: string | undefined;
}
export interface PostPreviewRenderResult { html: string; templateChoice: string | null }
/** Selects pending content first, then the already-authorized unpublished row's own body. */
function resolvePreviewBodyOverrides(
  { post, pendingBodyJson, pendingBodyHtmlOverride }: {
    post: PostRecord;
    pendingBodyJson: JsonObject | undefined;
    pendingBodyHtmlOverride: string | undefined;
  },
  _options: Record<string, never> = {}
): { bodyJson: JsonObject | undefined; bodyHtml: string | undefined } {
  // 2026-09-16, owner: "it should render even in unpublished state." The template's own
  // `{"type":"content"}` slot resolves through a VISIBILITY-FILTERED resolver
  // (`resolver-service.ts`'s `findPublishedPostById`), which finds nothing for an unpublished
  // row — so a draft previewed with styled chrome and NO BODY AT ALL, the REQ-28 placeholder
  // where its content should be. Measured, not inferred, before this change.
  //
  // The row's own body is the right answer here and is already in hand: this request fetched it
  // by id and `deps.authorize` already cleared this principal for `content.read` above, so the
  // operator can read this exact body from the admin API anyway. Rendering it into a `no-store`,
  // admin-only preview response exposes nothing new — the guard exists to keep unpublished
  // content off the PUBLIC site, and this route is not that.
  //
  // Scoped to unpublished rows deliberately: a published row's preview keeps resolving through
  // the resolver exactly as before, byte for byte, so this cannot change what the owner already
  // sees for the overwhelmingly common case. A genuine pending override always wins over it.
  const unpublished = post.status !== "published";
  const bodyJson = pendingBodyJson ?? (unpublished && post.bodyFormat === "doc" ? post.bodyJson : undefined);
  const bodyHtml = pendingBodyHtmlOverride ?? (unpublished && post.bodyFormat === "html" ? (post.bodyHtml ?? undefined) : undefined);

  return { bodyJson, bodyHtml };
}

/**
 * Renders an already-authorized row through the existing bare/theme pipelines, without writes.
 * Omitted templateChoice uses the saved choice; null and an empty string retain their distinct
 * template-selection meanings. Unsaved body fields override this render only.
 * @throws TemplatePreviewRenderError when a theme is unavailable for a template preview.
 * @complexity One bounded page render plus the existing theme, embed and menu repository reads.
 * @example await renderPostPreview(deps, { post, templateChoice: "article.html", bodyJson: pending });
 */
export async function renderPostPreview(deps: ContentRouteDeps, input: PostPreviewRenderInput): Promise<PostPreviewRenderResult> {
  const post = input.post;
  const overrideTemplateChoice = input.templateChoice === undefined ? post.templateChoice ?? null : input.templateChoice;
  const pendingBodyJson = input.bodyJson;
  const pendingBodyHtml = input.bodyHtml;
  const pendingBodyHtmlOverride = post.bodyFormat === "html" ? pendingBodyHtml : undefined;

  const previewPost = buildPreviewPost(post, overrideTemplateChoice, pendingBodyJson, pendingBodyHtml);

  // Bare-page preview (owner ruling 2026-09-23, S5) — checked BEFORE any theme resolution/409: a
  // bare Page renders identically regardless of theme, mirroring `renderBarePage`'s own placement
  // ahead of the `theme === null` check on the public site (`pages.ts`'s
  // `renderTemplateBranchIfEligible`).
  if (isBarePageChoice(previewPost)) {
    const html = await renderBarePreview(deps, previewPost);
    // `isBarePageChoice` only holds for `templateChoice === ""`, so the bare arm's choice is always
    // exactly that empty string -- never null/undefined (a `?? null` here was unreachable).
    return { html, templateChoice: "" };
  }

  const { settings } = await getPresentationSettings({
    deps: { repo: deps.presentationRepo },
    input: { workspaceId: deps.workspaceId },
  });
  const resolved = resolveActiveTheme(deps, settings.activeThemeId);
  if (resolved === null) {
    throw new TemplatePreviewRenderError(500, "no themes installed");
  }
  // Producer 4 of the optional-theme design. The thing this route previews IS a theme file, so
  // with the theme deliberately off there is nothing coherent to render. Before this guard the
  // route did not fail — it walked `resolveTemplate` -> `renderStaticPage` -> a `theme.pages`
  // lookup returning `undefined`, and landed on a `?? ""`, serving an EMPTY BODY with a 200.
  // The operator saw a blank preview pane and no reason for it, indistinguishable from a broken
  // template. 409 rather than 500: nothing is broken and nothing about the request is
  // malformed; the site's current state simply conflicts with what was asked for. This is an
  // admin tool, not a public surface, so an explicit error is right here even though the public
  // site answers the same state by rendering unstyled.
  if (resolved === NO_THEME_ID) {
    throw new TemplatePreviewRenderError(409, "this site has no active theme, so there is no template to preview — activate a theme to use the template picker");
  }
  const theme = resolved;

  const { bodyJson: previewBodyJson, bodyHtml: previewBodyHtml } = resolvePreviewBodyOverrides({
    post, pendingBodyJson, pendingBodyHtmlOverride,
  });

  // 2026-09-16 fix. This route used to hand `previewPost` straight to `renderViaTemplate`, while
  // the PUBLIC route reaches that same function only through `renderTemplateBranchIfEligible`,
  // which first asks `resolveTemplateBranchChoice` which template actually applies. For a
  // `kind: "page"`, `bodyFormat: "html"` row with no `templateChoice` — the state every
  // agent-created Page starts in, and the state the picker's "No template chosen" puts one back
  // into — the two answers differed: the public site resolved the theme's page shell, this route
  // fell through `resolveTemplate`'s "never chosen" arm onto `theme.manifest.templates[0]`
  // (`posts-default.html` on live `basic`) or, for the explicit `""`, onto the diagnostic page.
  // Either way the preview pane showed something the public URL never would. Asking the same
  // question the public route asks is the whole fix.
  //
  // `"ineligible"` keeps this route's PRE-EXISTING behavior (render `previewPost` as-is) rather
  // than matching the public site, which falls to a generic non-template render this route has no
  // access to. That remains a divergence for a `doc`-format Page with no template — narrower than
  // the one being closed, unreachable from the Pages picker (which only renders for `"html"`
  // format), and closing it means wiring a second render pipeline into an admin route, which is a
  // different change from this bug fix.
  const branch = resolveTemplateBranchChoice({ theme, post: previewPost });
  // A shallow clone for THIS render only — nothing is written back, exactly as the public route's
  // own page-shell arm does it, so the row stays untemplated and a later explicit pick still wins.
  const renderedPost = branch.kind === "page-shell" ? { ...previewPost, templateChoice: branch.templateChoice } : previewPost;

  const staticMenus = await resolveStaticMenusForRender(deps, theme, postPublicPath({ slug: post.slug }));
  // Preview the anonymous visitor's listing, never the admin's privileges. Passing access enables
  // the live pipeline's assembled-document resolution (plain, paged and keyed See more batches),
  // after pending content has been applied; no second listing fetch/render implementation.
  const postPreviewsAccess = {
    resolver: createMemberAccessResolver({ deps }),
    context: { isAuthenticated: false, activeTierIds: [], isPaid: false },
  };
  const html = await renderViaTemplate(deps, theme, renderedPost, staticMenus, previewBodyJson, previewBodyHtml, undefined, false, postPreviewsAccess);

  return { html, templateChoice: renderedPost.templateChoice ?? null };
}

import express, { type RequestHandler } from "express";
import type { JsonObject } from "@jini-ai/core/primitives";

import { getAdminPostByIdOrSlug, PostNotFoundError } from "#src/features/post/index";
import { renderPostPreview, TemplatePreviewRenderError } from "./template-preview-render.js";
// Clone/draft/theme-branch rationale lives beside renderPostPreview in template-preview-render.ts.
import { getAuthedPrincipal } from "../../dev-auth.js";
import type { ContentRouteRegistrar } from "../content/deps.js";

/**
 * @file Template-preview fix (2026-08-11, extended 2026-08-12) — `ADS-memory/reports/implementation/
 * 2026-08-11-template-preview-render-bug.md` has the original root-cause writeup. Short version: both
 * editors' Preview tab shows the real published page/post (`siteUrl`, full theme CSS/nav/footer) only
 * when `status === "published" && !dirty`; picking a DIFFERENT template than the one already saved
 * marks the row dirty (by design — it is an unsaved change), which used to fall the preview all the
 * way back to the raw, unstyled body with no template applied at all. That fallback also does not
 * read `templateChoice`, so switching between templates while dirty rendered byte-identical output —
 * "it doesn't re-render" was a symptom of the SAME cause as "it renders with no CSS", not two bugs.
 *
 * This route lets the editor preview the row through a PENDING (possibly unsaved) template choice AND
 * a PENDING body, reusing the exact render pipeline the public site uses (`renderViaTemplate`) rather
 * than a second, drift-prone implementation — the one thing it does differently from a normal page
 * load is override `templateChoice`/`bodyJson` on an in-memory clone of the fetched record before
 * rendering; nothing is written back to storage. Looked up by id via `getAdminPostByIdOrSlug` (any
 * status, unlike the public `getPublishedPostBySlug` the live-site iframe branch uses) rather than by
 * public slug — but the editors deliberately only ROUTE a `status === "published"` row through this
 * endpoint (see `PagePreview`/`PostPreview`'s own doc comments): a draft's own `{"type":"content"}`
 * slot still resolves through `resolveHtmlPageEmbeds`'s visibility-filtered "content" resolver
 * (`resolver-service.ts`'s guard 2), which returns nothing for an unpublished row, so a `GET`-only
 * request for a draft (no pending body attached — still all either editor currently sends for one,
 * as of this paragraph) shows styled chrome around an EMPTY body — confirmed live in this route's own
 * integration test (`admin-post-template-preview.test.ts`'s draft case). The id-based lookup stays
 * status-agnostic at THIS layer regardless: **a `POST` carrying the matching pending body (`bodyJson`
 * or, as of 2026-09-09, `bodyHtml` — see that paragraph below) bypasses this SAME visibility guard for
 * exactly that one already-authorized id**, which is what actually lets a draft preview its real,
 * unsaved content once a caller sends one — the admin UI widening to send one for a draft is tracked
 * separately from this route's own capability.
 *
 * **Pending body (2026-08-12)**: the owner's own reported bug — any content edit (not just a
 * template-picker change) sets `contentDirty`, which used to drop the preview all the way to the raw
 * `SrcDocSandbox` fallback with no theme CSS, because the DIRTY case had no way to hand this route the
 * operator's UNSAVED `bodyJson`. The naive alternative (point the dirty case at this route with only
 * `templateChoice` threaded, as originally built) renders the last-SAVED body — silently stale, worse
 * than the honest unstyled fallback it would replace. Fixed by accepting an optional `bodyJson` on
 * `POST` (see the handler below) and threading it through as
 * `ResolveHtmlPageEmbedsDeps.pendingContentOverride` (`Jini/packages/cms/src/widgets/resolver-service.ts`) — the ONE place
 * the current entity's own `{"type":"content"}` slot re-fetches by id
 * (`findPublishedPostById`/`features/post/post.ts`), silently discarding any in-memory-only override
 * that never reached that call. `GET` (unchanged, still template-choice-only) and `POST` (new, also
 * accepts a pending body) share this same handler — a `GET` request's `req.body` is always empty, so
 * `pendingBodyJson` is `undefined` on every pre-existing caller and that path is byte-for-byte
 * unchanged.
 *
 * **`bodyHtml` (2026-09-09, the `"html"`-format half of the same pending-body fix)**: `bodyJson` only
 * ever helps a `"doc"`-format post/Post — a Page written through the Pages admin editor is
 * `bodyFormat: "html"` and stores `bodyHtml`, not `bodyJson` (`features/post/post.ts`'s
 * `resolveUpdateBodyFields`, `repo.sqlite.ts`'s `toRecord`/inverse-column mapping). Overriding
 * `bodyJson` for an html-format row would do nothing — `renderViaTemplate`'s render path never reads
 * `bodyJson` for an html-format entity's own body (see `resolveHtmlFormatContentMarkers`'s own doc).
 * So this route ALSO accepts an optional `bodyHtml` form/JSON field, extracted by
 * {@link extractPendingBodyHtml} (a plain string — no `JSON.parse` needed, unlike `bodyJson`'s
 * TipTap-document shape) and threaded through as `renderViaTemplate`'s own `pendingBodyHtml`
 * parameter, which that function forwards to {@link resolveHtmlFormatContentMarkers}'s
 * `pendingHtmlOverride` — the equivalent bypass of that function's OWN `findPublishedPostById`
 * visibility guard, for the exact same reason and under the exact same "matches only the one id this
 * caller already fetched and authorized" scoping `pendingContentOverride` already uses for `bodyJson`.
 * The extracted renderer only builds this override when the FETCHED row's own `bodyFormat` is
 * `"html"` — an `bodyHtml` field sent for a `"doc"`-format post is ignored, never applied, since that
 * row has no `bodyHtml` column to preview in the first place.
 *
 * `POST`, not a widened `GET` query string, because a TipTap `bodyJson` document has no realistic
 * upper bound the way a `templateChoice` filename does. The admin client cannot simply point an
 * `<iframe src>` at a `POST` URL (this file's own `GET`-era doc, below, explains why the iframe needs
 * a REAL URL rather than `srcDoc` — root-relative `/theme-assets/...` paths); the real browser
 * mechanism for "POST a body, land on a real URL, inside a specific iframe" is a hidden `<form
 * method="post" target="{iframe name}">` submit — NOT `fetch()` (a `fetch` response is just a string in
 * JS; landing it in the iframe as a REAL document again means either `srcDoc` — the exact thing this
 * route exists to avoid — or a `blob:` URL, whose relative-URL resolution against `/theme-assets/...`
 * is unverified here and would need its own live check before relying on it).
 *
 * A plain HTML form POST always encodes as `application/x-www-form-urlencoded`, never
 * `application/json` — this route accepts BOTH: `app.ts`'s global `express.json({limit: "15mb"})`
 * handles a `fetch`-style JSON POST (if the admin-side implementation ever prefers that transport for
 * something other than the iframe itself), and this route ADDITIONALLY mounts its own
 * `express.urlencoded` on the `POST` registration only (scoped here, not globally in `app.ts`, since no
 * other route needs it) for the classic form-submit case — where `bodyJson` arrives as a
 * JSON-stringified STRING form field, not a parsed object, so {@link isJsonObject}'s check on the raw
 * value is followed by one `JSON.parse` attempt for exactly that shape (see the handler below).
 *
 * Mounted under `/api/admin/v1/workspaces/:workspaceId/posts/:postId/...`, the same URL family
 * `get-by-id.ts`/`update.ts` already use for both Posts and Pages (`PostEditor.tsx`'s own header:
 * "Shared between posts and pages via the same `/admin/posts/{id}` route") — `getAdminPostByIdOrSlug`
 * is kind-blind, so one route serves both editors' Preview tabs. Gated by the same global
 * `requireAdminSession` mount every other `/api/admin/*` route relies on (`app.ts`), so no extra
 * auth wiring is needed here beyond calling `getAuthedPrincipal` the same way `get-by-id.ts` does.
 *
 * Returns `text/html` directly rather than JSON — the client points an `<iframe src>`/form-target
 * straight at this URL (same reasoning `middleware/theme-page-preview.ts` gives for why a themed
 * preview has to be a real URL rather than posted into a `srcDoc` sandbox: the rendered HTML's asset
 * paths are root-relative to `/theme-assets/{themeId}/...`, which only resolves correctly when the
 * browser believes it's looking at a real page, not an inline document).
 */

/** Same minimal "is this a JSON object, not an array/primitive/null" shape check
 * `features/post/post.ts`'s own private `isJsonObject` and `Jini/packages/cms/src/widgets/resolver-service.ts`'s
 * `isPlainObject` use — kept as a separate local copy rather than importing either (neither is
 * exported, and this module already avoids reaching into `features/post`'s internals beyond its
 * published surface). Guards the POST body's `bodyJson` field: a malformed value (string, array,
 * `null`) is rejected here rather than handed to `renderViaTemplate`/`renderDocNode`, which expect an
 * actual TipTap document shape — same defensive shape check `updatePost`'s own `isJsonObject` applies
 * to a SAVED body, just re-applied here for a PENDING one (never persisted either way). */
function isJsonObject(value: unknown): value is JsonObject {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Extracts a validated pending-body override from `req.body.bodyJson`, accepting it in either shape a
 * real caller can produce (see this file's header for why both transports are supported): already a
 * parsed object (`express.json()` — a `fetch`-style JSON POST), or a JSON-stringified STRING
 * (`express.urlencoded()` — a classic `<form>` submit, where every field is a string regardless of
 * what it encodes). A `JSON.parse` failure on the string form, or any other shape (number, boolean,
 * array, already-invalid parsed object), returns `undefined` — the same "malformed input degrades to
 * the saved-body render, never a 400/crash" contract this file's read-only-preview reasoning states
 * elsewhere, since this endpoint has nothing to reject a bad request FOR (it writes nothing).
 */
function extractPendingBodyJson(body: unknown): JsonObject | undefined {
  if (!isJsonObject(body)) return undefined;
  const raw = body.bodyJson;
  if (isJsonObject(raw)) return raw;
  if (typeof raw === "string") {
    try {
      const parsed: unknown = JSON.parse(raw);
      return isJsonObject(parsed) ? parsed : undefined;
    } catch {
      return undefined;
    }
  }
  return undefined;
}

/**
 * Extracts a validated pending-body override from `req.body.bodyHtml` — the `"html"`-format
 * counterpart to {@link extractPendingBodyJson}, above. Simpler than that one: a plain HTML string
 * arrives identically from either transport (`express.json()`'s parsed field or
 * `express.urlencoded()`'s form field are both already strings here — there is no JSON-stringified
 * intermediate shape to `JSON.parse`, unlike a TipTap document). Any non-string value (missing,
 * number, object, array) returns `undefined` — the same "malformed input degrades to the saved-body
 * render, never a 400/crash" contract {@link extractPendingBodyJson} follows, since this endpoint
 * writes nothing and so has nothing to reject a bad request FOR.
 */
function extractPendingBodyHtml(body: unknown): string | undefined {
  if (!isJsonObject(body)) return undefined;
  const raw = body.bodyHtml;
  return typeof raw === "string" ? raw : undefined;
}

/**
 * Tri-state query contract, matching `templateChoice`'s own tri-state (see `resolveTemplate`'s
 * doc): the key absent entirely means "never chosen" (`null`), present but empty
 * (`?templateChoice=`) means the explicit "No template chosen" opt-out (`""`), present with a
 * value means that template filename. The admin client always sends one of the first two shapes
 * explicitly — see `templatePreviewUrl` in `apps/admin/src/lib/api.ts`.
 *
 * @complexity O(1).
 */
function resolveOverrideTemplateChoice(rawTemplateChoice: unknown): string | null {
  return rawTemplateChoice === undefined ? null : String(rawTemplateChoice);
}

/** The preview is author-controlled HTML served from the admin origin. The editors' iframe already
 *  sandboxes it (`PAGE_PREVIEW_IFRAME_SANDBOX`, `apps/admin/src/features/pages/rules.ts`); this header
 *  applies the same flags when the URL is opened on its own, as a top-level tab. Never
 *  `allow-same-origin`: with it, a preview's script could call admin APIs with the session cookie. */
const PREVIEW_CSP = "sandbox allow-scripts allow-forms allow-popups";

export const registerAdminPostTemplatePreviewRoute: ContentRouteRegistrar = (app, deps) => {
  const handlePreviewRequest: RequestHandler = async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).type("text/plain").send("workspace was not found");
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "content.read",
        workspaceId: deps.workspaceId,
      });
      if (!authResult.allowed) {
        res.status(403).type("text/plain").send(`principal '${principal.id}' is not authorized for 'content.read'`);
        return;
      }

      const { post } = await getAdminPostByIdOrSlug({
        deps: { repo: deps.postRepo },
        input: { workspaceId: deps.workspaceId, idOrSlug: String(req.params.postId ?? "") },
      });

      const overrideTemplateChoice = resolveOverrideTemplateChoice(req.query.templateChoice);

      // Pending body override (2026-08-12) — POST-only. `req.body` is parsed by whichever of
      // `express.json()` (`app.ts`'s global mount) or this route's own `express.urlencoded()` (below)
      // matched the request's `Content-Type`; a `GET` request never carries a body, so `req.body` is
      // empty there and `pendingBodyJson` stays `undefined` — the exact "byte-identical to before this
      // existed" behavior this file's header promises for `GET`.
      const pendingBodyJson = extractPendingBodyJson(req.body);
      const pendingBodyHtml = extractPendingBodyHtml(req.body);
      const { html } = await renderPostPreview(deps, {
        post, templateChoice: overrideTemplateChoice,
        bodyJson: pendingBodyJson, bodyHtml: pendingBodyHtml,
      });

      // Never cached: re-requested on every template selection, and a cached response would show
      // the operator a stale template and read as "the picker did nothing" — the exact bug this
      // route exists to fix (mirrors `theme-page-preview.ts`'s identical no-store rule).
      res.set("Cache-Control", "no-store").set("Content-Security-Policy", PREVIEW_CSP).type("html").send(html);
    } catch (err) {
      if (err instanceof TemplatePreviewRenderError) {
        res.status(err.status).type("text/plain").send(err.message);
        return;
      }
      if (err instanceof PostNotFoundError) {
        res.status(404).type("text/plain").send(err.message);
        return;
      }
      res.status(500).type("text/plain").send("preview render failed");
    }
  };

  const path = "/api/admin/v1/workspaces/:workspaceId/posts/:postId/template-preview";
  app.get(path, handlePreviewRequest);
  // `express.urlencoded` scoped to this ONE route's POST registration (not a global `app.ts` mount —
  // no other route needs it) so a classic `<form method="post" target="{iframe}">` submit, which
  // browsers always encode as `application/x-www-form-urlencoded`, populates `req.body` too. A
  // `fetch`-style JSON POST still works unchanged via `app.ts`'s global `express.json()`; Express
  // dispatches to whichever parser matches the request's actual `Content-Type`, so mounting both here
  // is additive, never a double-parse of the same request.
  app.post(path, express.urlencoded({ extended: false, limit: "15mb" }), handlePreviewRequest);
};

