import type { AgentRunStatus } from "#src/platform/observability/index";
import { redactedError } from "#src/platform/observability/report-error";
import { registerInstalledExtensionTools } from "../installed-extension-tools.js";
import { installFirstPartyToolContributors } from "../tool-catalog-manifest.js";
import type { ServerModuleHandle } from "./types.js";
import { buildDaemonAttachmentTools, createDaemonApprovalMemory, createDaemonAwareInstallAttachmentReader, registerAssistantToolExecRoutes } from "./assistant-tool-exec.js";
import type { ToolExecutionRouteTarget } from "@jini-ai/daemon/http";
import type { AttachmentLookup } from "@jini-ai/daemon/http";

export const BYOK_TURN_PATH = "/api/admin/v1/assistant/byok-turn";

/** Exported so `assistant-byok-routes.test.ts` can assert the exact composed `system` string against
 *  this same literal rather than duplicating it — see {@link resolveByokSystemPrompt}'s doc for the
 *  composition this constant is the fixed half of. */
export const SYSTEM_PREAMBLE =
  SITE_GUIDE_POINTER +
  "You are the Tovu admin assistant, running with the operator's own AI provider key (BYOK mode). " +
  "Use the tools you are given to inspect and manage this Tovu site on the operator's behalf. " +
  "Keep replies short and direct: lead with the answer, skip preamble and skip restating the " +
  "request. Use headers, lists, or tables only when they carry real structure. Give full detail " +
  "when asked, and never trade correctness for brevity — error text, failing output, and " +
  "confirmations for destructive actions keep their full content. " +
  "Only call tools that exist in your tool list; never invent one. " + CREDENTIAL_GUIDANCE + " " + PERMANENT_DELETE_GUIDANCE;

/** How long one BYOK turn waits on `ByokToolSurface.awaitFederation` before giving up and running
 *  with whatever tools are searchable so far — see that method's own doc for why the wait is bounded
 *  rather than open-ended. Only a turn that lands before the lazy boot pass has settled (normally just the
 *  first API-mode turn after boot) can actually wait this long; a roster-change reload is never
 *  awaited here, and every later turn finds the boot pass already settled and returns at once. 5s, per the owner's own sizing
 *  (`design-byok-external-mcp-2026-09-24.md` §2.1 item 6). */
export const FEDERATION_TURN_WAIT_MS = 5_000;

/** Appended to the system prompt (see {@link resolveByokSystemPrompt}) on a turn whose
 *  `awaitFederation` call timed out rather than settling — the same "no silent withholding" rule
 *  `agent-daemon-server.ts:643-647` already enforces for its own turns: a model that cannot yet see a
 *  just-registered external-MCP tool is told WHY a search might come up empty, rather than being left
 *  to guess the tool does not exist. */
export const FEDERATION_STILL_CONNECTING_NOTE =
  "External MCP servers are still connecting, so their tools may not be searchable yet. If a tool you need is missing, say so and suggest asking again in a moment.";

/** Bounds one BYOK turn's history the same way `assistant-transport.ts`'s `MAX_TRANSCRIPT_TURNS`
 *  bounds the daemon path's flattened prompt — each turn is a fresh provider request billed for its
 *  whole input, so an unbounded history would make every later message in a long chat more
 *  expensive than the last. */
const MAX_HISTORY_MESSAGES = 40;

/** Raises the bound each `run*ToolTurn` adapter would otherwise take from its own
 *  `DEFAULT_MAX_TOOL_TURNS` (8 — verified directly in all four of `@jini-ai/agent-runtime`'s
 *  `providers/{anthropic-messages,openai-chat,azure-chat,google-messages}.ts`, each of which reads
 *  `options.maxToolTurns ?? DEFAULT_MAX_TOOL_TURNS`). 8 is sized for a caller that names a real tool
 *  per action; this route's meta-tool surface costs up to 3 calls per real action
 *  (`search_tools` → `describe_tool` → `execute_delegated_tool`), so 8 truncates an ordinary
 *  multi-step task at roughly its second or third real operation — silently, because a truncated
 *  turn is reported to the client as an ordinary stop. 24 keeps ~6-8 real actions in reach at that
 *  3-calls-each cost. */
const BYOK_MAX_TOOL_TURNS = 24;

/** SSE framing. Local to this module, same convention (and same reason: kept in one place so event
 *  names cannot drift between branches) as `site-assistant.ts`'s identical helper — not shared
 *  cross-module because both are a few lines and neither has a second real caller yet. */
function sse(res: Response, event: string, data: unknown): void {
  res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
}

function beginStream(req: Request, res: Response): void {
  res.status(200).set({
    "content-type": "text/event-stream",
    "cache-control": "no-cache, no-transform",
    // Same reasoning as `site-assistant.ts`'s identical guard: HTTP/2 throws
    // `ERR_HTTP2_INVALID_CONNECTION_HEADER` on a `connection` header, and dropping it changes
    // nothing observable for an HTTP/1.1 client (keep-alive is already its default there).
    ...(req.httpVersionMajor < 2 ? { connection: "keep-alive" } : {}),
    "x-accel-buffering": "no",
  });
  res.flushHeaders?.();
}

function isPlainMessage(value: unknown): value is { role: unknown; content: unknown; secretRedacted?: unknown } {
  return typeof value === "object" && value !== null;
}

/**
 * Transforms one `SurfaceEmission` into the bare `RunAgentPayload`-shaped object this route's own
 * `sse(res, "agent", ...)` writes onto the wire.
 *
 * Mirrors `@jini-ai/daemon`'s `delegated-tool-bridge.ts` `emitSurface` closure byte-for-byte (traced
 * directly, not inferred): `emission.channel` becomes the payload's `type`, `emission.payload`'s own
 * fields are spread in beside it (after stripping any `type`/`toolUseId` a handler tried to smuggle
 * in, so a handler cannot forge either), and `toolUseId` is injected only for the `'mcp-ui'` channel —
 * the one channel whose client-side renderer (`McpUiSurfaceCard`) actually reads it for correlation.
 * This is what lets `apps/admin/src/lib/assistant-transport.ts`'s already-shipped
 * `translateRunAgentPayload` switch render a BYOK-mode surface exactly like a daemon-mode one, with no
 * new frontend branching — see this module's own header for the full trace.
 *
 * Verified end-to-end for `'mcp-ui'` only (`assistant-byok-routes.test.ts`), the one channel a real
 * catalog tool (`content_post_delete`) uses today. Kept channel-agnostic, like its daemon
 * counterpart, so a future channel is not silently dropped — but an untested channel inherits that
 * counterpart's own disclosed scope, not a new guarantee this function makes.
 *
 * @complexity O(k) in `emission.payload`'s own key count.
 * @overallScore 100
 */
export function toWireSurfacePayload(emission: SurfaceEmission, toolUseId: string): Record<string, unknown> {
  const safePayload: Record<string, unknown> = { ...emission.payload };
  delete safePayload.type;
  delete safePayload.toolUseId;
  return {
    ...safePayload,
    type: emission.channel,
    ...(emission.channel === "mcp-ui" ? { toolUseId } : {}),
  };
}

/** One raw history entry -> a valid {@link ByokChatMessage}, or `null` if it isn't one — the single
 *  per-entry validation `resolveMessages` below loops over. */
function toByokChatMessage(entry: unknown): ByokChatMessage | null {
  if (!isPlainMessage(entry)) return null;
  const role = entry.role === "user" || entry.role === "assistant" ? entry.role : null;
  const content = typeof entry.content === "string" ? entry.content : null;
  if (role === null || content === null || content.length === 0) return null;
  const modelContent = role === "user" ? guardUserText({ text: content }, {
    modelNote: CREDENTIAL_PASTE_MODEL_NOTE, secretRedacted: entry.secretRedacted === true,
  }) : content;
  return { role, content: modelContent };
}

/** Validates and bounds the client-supplied history. Fail-soft on individual malformed entries
 *  (dropped, not rejected) — mirrors `site-assistant.ts`'s own `resolveBoundedHistory` posture for
 *  the sibling visitor-assistant route: history is passive background context the caller did not
 *  just author this instant, so a malformed entry degrades the turn's context rather than the whole
 *  request. */
export function resolveMessages(raw: unknown): ByokChatMessage[] {
  if (!Array.isArray(raw)) return [];
  const messages: ByokChatMessage[] = [];
  for (const entry of raw) {
    const message = toByokChatMessage(entry);
    if (message) messages.push(message);
  }
  return messages.slice(-MAX_HISTORY_MESSAGES);
}

/**
 * Composes this route's `system` prompt in the fixed order §2.1 item 6 of
 * `design-byok-external-mcp-2026-09-24.md` specifies: {@link SYSTEM_PREAMBLE}, then the federation
 * runtime's own `refusalPrefix()` (when this turn's surface actually has drift to report), then
 * {@link FEDERATION_STILL_CONNECTING_NOTE} (when this turn's `awaitFederation` call timed out rather
 * than settling), then the admin Instructions tab's custom overlay (`core.instructions.custom`), when
 * the operator has set one — every present part joined with the Local CLI path's own separator
 * (`agent-daemon-server.ts`: `` `${base}\n\n${custom}` ``), so an operator's custom instructions still
 * apply identically in both execution modes rather than only to Local CLI runs, and a still-connecting
 * federation boot pass never silently withholds a tool the model would otherwise assume does not exist
 * (the same rule `agent-daemon-server.ts:643-647` already enforces for its own turns).
 *
 * `federation.refusalPrefix`/`federation.stillConnecting` are `handleTurn`'s own read of THIS turn's
 * `awaitFederation(FEDERATION_TURN_WAIT_MS)` outcome and `ByokToolSurface.federation?.refusalPrefix()`
 * — passed in rather than resolved here, since this function has no surface of its own to ask.
 *
 * Re-reads `core.instructions.custom` fresh on every call rather than caching it at module load or
 * across turns: this route has no long-lived process to refresh a cache against between requests (each
 * `handleTurn` invocation is its own request/response lifecycle), so a plain re-read is both simpler
 * and sufficient here — unlike the Local CLI path, which needs `custom-instructions.ts`'s
 * `createCustomInstructionsCache` bridge specifically because `PromptAugmenter.systemOverlay()` is
 * called synchronously inside the daemon's `run()`. `resolveCustomInstructions` never throws (fails
 * open to `""` on any read error) and `formatCustomInstructionsOverlay` returns `null` for unset,
 * empty, or whitespace-only text, so a turn with no federation drift/timeout and an operator who has
 * never opened the Instructions tab gets exactly {@link SYSTEM_PREAMBLE} back, unchanged.
 *
 * @complexity O(1) — one `resolveCustomInstructions` read (itself O(1)) plus a trim/length check.
 * @overallScore 100
 */
/**
 * How a BYOK turn ended, for its agent-run span. An abort (the browser went away) is `canceled`
 * whatever else happened; a throw is `failed` with that error. Provider adapters report their own
 * failures (an HTTP error, a blocked prompt, a bad baseUrl) as an `error` event and still resolve, so
 * a turn that resolved after reporting one is `failed` too: resolving alone is not success.
 * @complexity O(1), pure.
 */
export function byokTurnOutcome(
  { aborted, reportedError }: { aborted: boolean; reportedError: boolean },
  { thrown }: { thrown?: { error: unknown } } = {},
): { status: AgentRunStatus; error?: unknown } {
  if (aborted) return { status: "canceled" };
  if (thrown) return { status: "failed", error: thrown.error };
  return { status: reportedError ? "failed" : "succeeded" };
}

/**
 * Stamps each provider `usage` event with the wall time since the previous one (the first since
 * `startedAt`). Provider adapters report tokens only, and the chat's "Done · 16s" line needs a
 * `durationMs` (it shows nothing without time or cost); the client sums a turn's usage events, so
 * per-event deltas add up to the turn's elapsed time however many usage frames a provider streams.
 * No `costUsd`: there is no pricing table and the chat never estimates money from tokens.
 * @complexity O(1) per event; holds one timestamp.
 */
export function createByokUsageTimer(
  { startedAt }: { startedAt: number },
  { now = Date.now }: { now?: () => number } = {},
): (event: ByokTurnEvent) => ByokTurnEvent & { durationMs?: number } {
  let mark = startedAt;
  return (event) => {
    if (event.type !== "usage") return event;
    const at = now();
    const durationMs = Math.max(0, at - mark);
    mark = at;
    return { ...event, durationMs };
  };
}

async function resolveByokSystemPrompt(
  routeDeps: RouteDeps,
  federation: { readonly refusalPrefix: string; readonly stillConnecting: boolean },
): Promise<string> {
  const customInstructions = await resolveCustomInstructions(
    {
      settingsRepo: routeDeps.settingsRepo,
      settingsReady: routeDeps.settingsUiTabsReady,
      getEffective: routeDeps.getEffective,
      instructionsNamespace: routeDeps.instructionsNamespace,
    },
    { workspaceId: routeDeps.workspaceId },
  );
  const customOverlay = formatCustomInstructionsOverlay(customInstructions);
  const parts = [SYSTEM_PREAMBLE];
  if (federation.refusalPrefix.length > 0) parts.push(federation.refusalPrefix);
  if (federation.stillConnecting) parts.push(FEDERATION_STILL_CONNECTING_NOTE);
  if (customOverlay !== null) parts.push(customOverlay);
  return parts.join("\n\n");
}

/**
 * Return type widened past the generic {@link ServerModuleHandle} to also expose the composed
 * `toolSurface` — specifically so `app.ts` can capture `.toolSurface.surfaceExchanges` and hand it to
 * `createAssistantModule`'s redemption proxy WITHOUT importing `byok-tool-surface.ts` directly
 * itself. That's not a style preference: `app.ts` already transitively reaches `byok-tool-surface.ts`
 * through this module (which has always imported it), so reading the value off this return object
 * costs the composition root zero new edges in the dependency graph; a direct
 * `import { createByokToolSurface } from "../assistant/byok-tool-surface"` in `app.ts` would add one,
 * and — traced empirically via `npm run check:architecture` before landing this — that one new edge
 * from the highest-fan-out file in the whole codebase was enough to flip ~17 other files into the
 * "core" classification (both fan-in and fan-out above the graph median), regressing that ratcheted
 * metric. This shape gets the identical runtime behavior (one surface, built once, shared by both
 * modules) for zero graph cost.
 */
export interface AssistantByokModuleHandle extends ServerModuleHandle {
  readonly toolSurface: ByokToolSurface;
  /** Mounts the agent daemon's tool RPC over `toolSurface` (`assistant-tool-exec.ts`). */
  readonly registerToolExecRoutes: (required: { readonly router: ToolExecutionRouteTarget }) => void;
}

/**
 * @param toolSurface - Defaults to a fresh `createByokToolSurface(routeDeps)`, built once right here
 * when the caller doesn't supply one — the production path (`app.ts`) always takes this default, so
 * it never needs its own `byok-tool-surface.ts` import (see {@link AssistantByokModuleHandle}'s doc
 * for why that specifically matters). The explicit parameter exists for tests that need to observe or
 * override the composed surface — e.g. injecting a short-TTL `surfaceExchangeStore` via
 * `createByokToolSurface`'s own override to prove the no-hang bound in milliseconds rather than the
 * production 5.5-minute ceiling — without which this module would have no seam to reach it through.
 * Optional (rather than a plain default parameter) specifically so
 * `installFirstPartyToolContributors()` below is guaranteed to run BEFORE the default
 * `createByokToolSurface(routeDeps)` construction, not as part of evaluating this function's own
 * argument list — a default-parameter expression evaluates before the function body starts, which
 * would be too early for the install call to have any effect on the surface it composes.
 */
type ByokTurnInputs = { messages: ByokChatMessage[]; principal: Principal; credential: ResolvedByokCredential };

/** BYOK bypasses the daemon lifecycle, but publishes the same normalized model/tool events.
 * Reuse its recorder so both execution modes report generations with the same semantics. */
function startByokTrace(
  { routeDeps, run, credential, messages }: { routeDeps: Pick<RouteDeps, "aiTraceSink">; run: { id: string }; credential: ResolvedByokCredential; messages: ByokChatMessage[] },
  _optional = {},
) {
  const trace = routeDeps.aiTraceSink ? createAiTraceRecorder({ sink: routeDeps.aiTraceSink, runId: run.id, agentId: credential.protocol },
    { provider: credential.protocol, model: credential.model, exactSecrets: [credential.apiKey] }) : undefined;
  trace?.start(routeDeps.aiTraceSink?.capture === "full" ? { input: messages.at(-1)?.content ?? null } : {});
  return trace;
}

function byokTraceOutcome({ aborted, reportedError }: { aborted: boolean; reportedError: boolean }, _optional = {}): "cancelled" | "failed" | "succeeded" {
  const { status } = byokTurnOutcome({ aborted, reportedError });
  if (status === "canceled") return "cancelled";
  return status === "succeeded" ? "succeeded" : "failed";
}

/**
 * The two gates `handleTurn` must clear before it opens a stream: the client-supplied history must
 * resolve to a non-empty, user-ending message list, and a usable BYOK credential (request-supplied
 * or the admin's own stored row) must resolve. Both can end the request on their own; consolidated
 * here so `handleTurn` itself is a single `if (!inputs) return;` rather than two separate guards.
 */
async function resolveTurnInputsOrRespond(
  req: Request,
  res: Response,
  credentialPort: ExecutionCredentialPort,
  routeDeps: RouteDeps,
): Promise<ByokTurnInputs | null> {
  const body = (req.body ?? {}) as { messages?: unknown; byok?: RequestSuppliedByokConfig; pageContext?: unknown; attachmentIds?: unknown };
  const history = resolveMessages(body.messages);
  if (history.length === 0 || history[history.length - 1]?.role !== "user") {
    res.status(400).json({ error: "'messages' must end with a non-empty user message", code: "VALIDATION_ERROR" });
    return null;
  }
  // The admin screen block, same as a Local CLI run's (`run-page-context.ts`): degrade-only, so a
  // malformed `pageContext` means "the turn does not know the screen", never a rejected request.
  const messages = [...withPageContextBlock({ messages: history, pageContext: readRunPageContext(body.pageContext) })];

  const authed = getAuthedPrincipal(res);
  const credential = await credentialPort.resolve({
    requestBody: body.byok ?? {},
    workspaceId: routeDeps.workspaceId,
    principalId: authed.id,
  });
  if (!credential) {
    res.status(400).json({
      error:
        "no usable BYOK credential — supply 'byok' with a supported protocol, a non-empty apiKey, and a model, or save one first in Settings",
      code: "VALIDATION_ERROR",
    });
    return null;
  }

  if (!await attachTurnMessagesOrRespond({ attachmentIds: body.attachmentIds, messages, principalId: authed.id, routeDeps, res })) return null;
  return { messages, principal: { id: authed.id }, credential };
}

/** Validates attachment references and adds the owner-scoped byte preparation to the newest message.
 * Invalid or unavailable attachments stop the request before SSE begins; omitted references do nothing.
 * At most ten references are passed to the existing attachment preparation owner.
 * @complexity O(attachment bytes) preparation, with at most ten references; mutates the last message. */
async function attachTurnMessagesOrRespond({ attachmentIds, messages, principalId, routeDeps, res }: {
  attachmentIds: unknown; messages: ByokChatMessage[]; principalId: string; routeDeps: RouteDeps; res: Response;
}, _options: Record<string, never> = {}): Promise<boolean> {
  if (attachmentIds !== undefined) {
    if (!Array.isArray(attachmentIds) || attachmentIds.length > 10 ||
      attachmentIds.some(ref => typeof ref !== "string" || !ref)) {
      res.status(400).json({ error: "Invalid message attachments", code: "VALIDATION_ERROR" });
      return false;
    }
    try {
      const prepared = await prepareByokMessageAttachments({ refs: attachmentIds, principalId, uploadDirectory: routeDeps.siteStoragePaths.chatAttachmentsDir }, {});
      const last = messages[messages.length - 1]!;
      messages[messages.length - 1] = { ...last, content: last.content + prepared.notice, images: prepared.images };
    } catch {
      res.status(400).json({ error: "Attachment is unavailable. Reattach it before sending.", code: "VALIDATION_ERROR" });
      return false;
    }
  }
  return true;
}

/** @param optional.attachmentLookup Test seam for the daemon's attachment store (`assistant-tool-exec.ts`). */
export function createAssistantByokModule(
  routeDeps: RouteDeps & ByokToolSurfaceDeps,
  toolSurface?: ByokToolSurface,
  { attachmentLookup }: { attachmentLookup?: AttachmentLookup } = {},
): AssistantByokModuleHandle {
  // Must run before `createByokToolSurface` (below, or the caller's own instance's earlier
  // construction) calls `buildAssistantToolRegistrations`: that function reads whatever
  // this composition's explicit core registries hold, and those registries start empty every
  // process boot. See `tool-catalog-manifest.ts`'s own header for why this call lives here and in
  // `agent-daemon-server.ts`, and nowhere else. Idempotent, so a test supplying its own `toolSurface`
  // (built from an already-installed registry) pays nothing extra for this still running.
  const contributions = {
    contributors: createContributionRegistry({ keyOf: ({ contribution }: { contribution: ToolContributor }) => contribution.domain }),
    derivedContributors: createContributionRegistry({ keyOf: ({ contribution }: { contribution: DerivedToolContributor }) => contribution.domain }),
  };
  // `outboundTestOrigins` is set only by the site-import journey harness; absent, this factory is
  // `createDefaultHttpClient` itself (`platform/http/test-origin-allowlist.ts`).
  // The agent daemon's tool RPC runs on this same surface (`assistant-tool-exec.ts`); the daemon-call
  // adapters below change nothing for a BYOK turn.
  installFirstPartyToolContributors({ contributions }, { observability: routeDeps.observability, chatAttachmentsDir: routeDeps.siteStoragePaths.chatAttachmentsDir,
    createHttpClient: createTestOriginHttpClientFactory({ allowedOrigins: routeDeps.outboundTestOrigins ?? [] }),
    readInstallAttachment: createDaemonAwareInstallAttachmentReader({ uploadDirectory: routeDeps.siteStoragePaths.chatAttachmentsDir }) });
  const surfaceDeps = routeDeps.conversationToolApprovals ? { ...routeDeps, nativeApprovalMemory: routeDeps.nativeApprovalMemory ?? createDaemonApprovalMemory({
    store: routeDeps.conversationToolApprovals, workspaceId: routeDeps.workspaceId, clock: routeDeps.clock }) } : routeDeps;
  // The public contract and both roots require complete BYOK dependencies;
  // no cast may conceal a missing runtime port.
  let automaticPluginRuns: ReturnType<typeof createAutomaticPluginRuns>;
  const resolvedToolSurface =
    toolSurface ??
    createByokToolSurface(surfaceDeps, {
      contributions,
      hostRegistrations: ({ registrations }) => buildDaemonAttachmentTools({ deps: routeDeps, registrations }, attachmentLookup ? { getLookup: () => attachmentLookup } : {}),
      prepareGuidance: (required, optional) => automaticPluginRuns.prepareGuidance(required, optional),
      // The root injects the audit sink; see RouteDeps.toolAttemptAuditSink for why
      // consumers must not open their own database. A supplied toolSurface bypasses this branch.
      toolAttemptAudit: { sink: routeDeps.toolAttemptAuditSink, workspaceId: routeDeps.workspaceId },
      // Feature registrars `assistant/` must not import by value (module cycles) — injected here.
      registerInstalledExtensions: async (registry, deps, log) => {
        await registerInstalledExtensionTools(registry, deps, log);
        // The awaited extension pass also lets the run controller bind to this surface below.
        registry.register(automaticPluginRuns.loadRegistration);
      },
    });
  automaticPluginRuns = createAutomaticPluginRuns({ deps: routeDeps, surfaces: { surfaceExchanges: resolvedToolSurface.surfaceExchanges } });
  const credentialPort = createStoredExecutionCredentialPort({
    repo: routeDeps.adminExecutionCredentialRepo,
    sealer: routeDeps.siteAssistantSecretSealer,
  });

  return {
    name: "assistant-byok",
    toolSurface: resolvedToolSurface,
    registerToolExecRoutes: ({ router }) => registerAssistantToolExecRoutes({ router, toolSurface: resolvedToolSurface }, {}),
    registerRoutes: (app: Express) => {
      app.use(BYOK_TURN_PATH, requireAdminSession(routeDeps));
      app.post(BYOK_TURN_PATH, (req: Request, res: Response, next: NextFunction) => {
        void handleTurn(req, res).catch((error: unknown) => {
          console.error("[assistant-byok] unhandled error", error);
          if (res.headersSent) {
            sse(res, "error", { message: "assistant failed" });
            res.end();
          } else {
            next(error);
          }
        });
      });
    },
  };

  /** Loads explicit picks independently, so one unavailable plugin cannot discard the others.
   * Returns the ordered prompt suffix and whether any pick failed; failures never escape.
   * @complexity One sequential lifecycle resolution per pinned reference; O(guidance bytes) space. */
  async function loadPinnedPluginGuidance({ pinned }: { pinned: string[] }, _options: Record<string, never> = {}): Promise<{ prefix: string; skippedPinned: boolean }> {
    let skippedPinned = false;
    let prefix = "";
    for (const pluginId of pinned) {
      // Explicit attachments bypass relevance matching, but a failed attachment must not end a run
      // or discard guidance from the other picks. The lifecycle still enforces activation and trust.
      try {
        const resolved = await resolveAgentPluginRefs([pluginId], routeDeps.agentPluginLayout.forWorkspace(routeDeps.workspaceId), 'inject');
        if (resolved.ok) prefix += `\n\n${resolved.promptPrefix}`;
        else skippedPinned = true;
      } catch { skippedPinned = true; }
    }
    return { prefix, skippedPinned };
  }

  /** Starts the existing automatic plugin lifecycle and appends its guidance; failure leaves the prompt intact.
   * Emits consent/usage surfaces through this turn's response and logs a preflight failure.
   * @complexity One automatic-use preparation; candidate discovery/ranking belongs to that owner. */
  async function appendAutomaticPluginGuidance({ run, principal, conversationId, pluginBody, messages, pinned, abort, res, system }: {
    run: { id: string }; principal: Principal; conversationId: string;
    pluginBody: { agentPluginState?: unknown; userPrompt?: unknown }; messages: ByokChatMessage[];
    pinned: string[]; abort: AbortController; res: Response; system: string;
  }, _options: Record<string, never> = {}): Promise<string> {
    try {
      const guidance = await automaticPluginRuns.start({ runId: run.id, context: {
        principal, conversationId, state: readChatAgentPluginState({ value: pluginBody.agentPluginState }),
        query: typeof pluginBody.userPrompt === 'string' ? pluginBody.userPrompt.slice(0, 16000) : messages[messages.length - 1]?.content ?? '', pinned, signal: abort.signal,
        emitSurface: async emission => { sse(res, 'agent', toWireSurfacePayload(emission, `agent-plugins:${run.id}`)); },
        publish: async value => { sse(res, 'agent', { type: 'agent_plugins', ...value }); },
      } });
      if (guidance) system += `\n\n${guidance}`;
    } catch { console.warn('[agent-plugins] automatic BYOK preflight unavailable'); }

    return system;
  }

  /** Composes pinned and automatic guidance before provider planning; plugin failures remain fail-soft.
   * Registers response-close cleanup and returns the augmented prompt.
   * @complexity O(pinned references + guidance bytes), plus the automatic lifecycle's preparation. */
  async function preparePluginGuidance({ req, res, run, principal, messages, abort, system }: {
    req: Request; res: Response; run: { id: string }; principal: Principal; messages: ByokChatMessage[]; abort: AbortController; system: string;
  }, _options: Record<string, never> = {}): Promise<string> {
    // Preflight uses the same catalog/consent/guidance owner as CLI, before the provider plans.
    const pluginBody = (req.body ?? {}) as { conversationId?: unknown; agentPluginState?: unknown; pluginRefIds?: unknown; userPrompt?: unknown };
    const conversationId = typeof pluginBody.conversationId === 'string' ? pluginBody.conversationId : undefined;
    const pinned = Array.isArray(pluginBody.pluginRefIds) ? pluginBody.pluginRefIds.filter((id): id is string => typeof id === 'string') : [];
    const { prefix, skippedPinned } = await loadPinnedPluginGuidance({ pinned });
    system += prefix;
    if (skippedPinned) sse(res, 'agent', { type: 'status', label: 'Some selected Agent Plugins could not be loaded and were skipped.' });
    res.on('close', () => automaticPluginRuns.forget({ runId: run.id }));
    if (!conversationId) return system;
    return appendAutomaticPluginGuidance({ run, principal, conversationId, pluginBody, messages, pinned, abort, res, system });
  }

  async function handleTurn(req: Request, res: Response): Promise<void> {
    const inputs = await resolveTurnInputsOrRespond(req, res, credentialPort, routeDeps);
    if (!inputs) return;
    const { messages, principal, credential } = inputs;

    // `ready` resolves once the installed-extension-tools pass (Agent Plugins, Agent Skills, enabled
    // plugin-capability tools) has been applied to `resolvedToolSurface`'s registry AND its
    // `search_tools`/`describe_tool` catalog rebuilt to include them — see `ByokToolSurface.ready`'s
    // own doc. Awaited here, once per turn, so `search_tools` can find a just-registered extension
    // tool before the model's first tool call this turn, not only after it. Resolves instantly for
    // every turn after the first (the promise is already settled) and for a caller-supplied
    // `toolSurface` that predates this field, which has no `ready` to wait on at all.
    await (resolvedToolSurface.ready ?? Promise.resolve());

    // Starts (or awaits) this surface's lazy federation boot pass, bounded to
    // `FEDERATION_TURN_WAIT_MS` — see `ByokToolSurface.awaitFederation`'s own doc. Only a turn that
    // lands before the boot pass has settled can actually wait (a roster-change reload is never
    // awaited here); every later turn finds the boot pass already settled and this resolves at
    // once. `federation?.refusalPrefix()` reads whatever drift THIS surface has accumulated so far,
    // live — empty before federation has admitted anything, and always when this surface was built
    // with `installExtensions: false` (`federation` is `undefined` there).
    const federationOutcome = await resolvedToolSurface.awaitFederation(FEDERATION_TURN_WAIT_MS);
    let system = await resolveByokSystemPrompt(routeDeps, {
      refusalPrefix: resolvedToolSurface.federation?.refusalPrefix() ?? "",
      stillConnecting: !federationOutcome.settled,
    });

    const run = { id: randomUUID() };

    beginStream(req, res);
    // Same reasoning as `site-assistant.ts`'s identical guard: a browser tab closing must stop the
    // upstream provider call and any in-flight tool execution, not run to completion unobserved.
    const abort = new AbortController();
    res.on("close", () => {
      if (!res.writableEnded) abort.abort();
    });

    system = await preparePluginGuidance({ req, res, run, principal, messages, abort, system });

    // Older injected surfaces retain their wrapper contract; production creates one exposure per run.
    const toolRun = resolvedToolSurface.createRun?.({ principal, run });

    // Starts with the meta-tool set and promotes concrete definitions after describe_tool.
    // The legacy dispatch below is owned by the same surface: `call.name` is one of
    // `search_tools`/`describe_tool`/`execute_delegated_tool`, and a real tool id arrives as the
    // third one's `toolId` argument. The unwrap, the status mapping, and the "model named something
    // that isn't callable" case all live in `byok-tool-surface.ts` beside the descriptors that
    // create them, so the two cannot drift apart. Authorization is unmoved by any of this — see
    // `META_TOOL_DESCRIPTORS`' own doc.
    //
    // `emitSurface` is built fresh per call (not once for the whole turn), because it needs THIS
    // call's own `call.id` as the correlation `toolUseId` a rendered mcp-ui card is tagged with —
    // `runByokProviderTurn`'s adapters invoke `executeTool` once per model-issued tool call, so a new
    // closure per invocation costs nothing a turn with real tool calls wasn't already paying.
    const executeTool = (call: { id: string; name: string; input: unknown }) => {
      const emitSurface: SurfaceEmitter = async (emission) => {
        sse(res, "agent", toWireSurfacePayload(emission, call.id));
      };
      if (toolRun) return toolRun.executeTool(call, { signal: abort.signal, emitSurface });
      return resolvedToolSurface.executeMetaTool(principal, run, call, abort.signal, emitSurface);
    };

    // One agent-run span per turn (its own trace root); the turn runs inside it, so its tool calls'
    // DB and outbound spans nest under the run rather than the long-lived request.
    return routeDeps.tracker.trace({ name: "assistant.run", run: async (span) => {
      const aiTrace = startByokTrace({ routeDeps, run, credential, messages });
      routeDeps.tracker.capture({ name: "assistant_run_started", userId: principal.id }, { properties: { chatSurface: "admin", logicalRunId: run.id, eventId: `assistant-start:${run.id}` } });
      let reportedError = false;
      // A failed turn (a provider error event or a throw, not an owner's cancel) is an incident for
      // the error tracker too: the protocol and run id only, the key blanked even without a known shape.
      const reportRunFailure = (error: unknown) => routeDeps.tracker.error({ error: error instanceof Error ? error : redactedError({ error }) }, { context: { operation: "assistant.run", attributes: { agent: credential.protocol, runId: run.id }, exactSecrets: [credential.apiKey] } });
      const stampUsage = createByokUsageTimer({ startedAt: Date.now() });
      function finishFailedTurn({ error }: { error: unknown }, _optional = {}): void {
        aiTrace?.observe({ type: "error", message: error instanceof Error ? error.message : String(error) });
        aiTrace?.finish({ outcome: abort.signal.aborted ? "cancelled" : "failed" });
        routeDeps.tracker.capture({ name: "assistant_run_finished", userId: principal.id }, { properties: { chatSurface: "admin", logicalRunId: run.id, outcome: abort.signal.aborted ? "cancelled" : "failed", eventId: `assistant-finish:${run.id}` } });
        span.setOutcome(byokTurnOutcome({ aborted: abort.signal.aborted, reportedError }, { thrown: { error } }));
        if (!abort.signal.aborted && !reportedError) reportRunFailure(error);
        sse(res, "error", { type: "error", message: error instanceof Error ? error.message : String(error) });
        sse(res, "end", { reason: "error" });
        res.end();
      }
      let result: ByokProviderTurnResult;
      try {
        result = await runByokProviderTurn({
          protocol: credential.protocol,
          apiKey: credential.apiKey,
          ...(credential.baseUrl ? { baseUrl: credential.baseUrl } : {}),
          model: credential.model,
          ...(credential.maxTokens !== undefined ? { maxTokens: credential.maxTokens } : {}),
          maxToolTurns: BYOK_MAX_TOOL_TURNS,
          system,
          messages,
          // 3 descriptors, not all 131. The full catalog is ~119 KB (~30 k tokens) of `inputSchema`
          // re-sent on EVERY message; the meta-set is under 1 KB and initially reaches the same tools through
          // `search_tools` → `describe_tool` → `execute_delegated_tool`. See `META_TOOL_DESCRIPTORS`.
          tools: toolRun?.getToolSnapshot() ?? resolvedToolSurface.metaTools,
          getToolSnapshot: toolRun?.getToolSnapshot,
          onSchemaFallback: ({ toolId, protocol, reason }) => {
            console.warn("[assistant-byok] tool schema fallback", { toolId, protocol, reason });
          },
          executeTool,
          signal: abort.signal,
          // `error`-typed events get their OWN SSE event name, not folded into `agent` — mirrors the
          // daemon path's distinct `source.addEventListener("error", ...)` on the client
          // (`assistant-transport.ts`), which is what actually calls `handlers.onError` rather than
          // rendering an unrecognized `ext` event. Everything else rides `agent` unchanged, reusing
          // `translateRunAgentPayload`'s existing switch on the client with zero new cases.
          onEvent: (event: ByokTurnEvent) => {
            aiTrace?.observe(event as unknown as Record<string, unknown>);
            // Reporting a disconnect's AbortError would mark this active span failed despite its canceled outcome.
            if (event.type === "error" && !abort.signal.aborted && !reportedError) { reportedError = true; reportRunFailure(new Error(event.message)); }
            sse(res, event.type === "error" ? "error" : "agent", stampUsage(event));
          },
        });
      } catch (error) {
        finishFailedTurn({ error });
        return;
      }

      span.setOutcome(byokTurnOutcome({ aborted: abort.signal.aborted, reportedError }));
      aiTrace?.finish({ outcome: byokTraceOutcome({ aborted: abort.signal.aborted, reportedError }) });
      routeDeps.tracker.capture({ name: "assistant_run_finished", userId: principal.id }, { properties: { chatSurface: "admin", logicalRunId: run.id, outcome: byokTraceOutcome({ aborted: abort.signal.aborted, reportedError }), eventId: `assistant-finish:${run.id}` } });
      sse(res, "end", { reason: result.stopReason ?? "stop" });
      res.end();
    } }, { agent: { runId: run.id, agentName: credential.protocol } });
  }
}

import { createNoopTracker } from "@jini-ai/diagnostics/observability";
import type { Tracker } from "@jini-ai/diagnostics/observability";
/**
 * @file Saves an admin-chat turn when its agent run ends — whether or not a browser is still watching.
 *
 * Purpose (FINDING A, `ADS-memory/reports/2026-09-27-stuck-chat-root-cause.md`):
 * the browser used to be the only thing that ever wrote a finished turn. Close the tab mid-run, lose
 * a headless client, or let a restart kill the run, and the row stayed `running` with no content:
 * the answer the run produced existed only in the daemon's memory, and was gone at its next restart.
 *
 * How:
 * Server acceptance writes the logical assistant message before dispatch. This module follows
 * each daemon attempt and checkpoints its projection, independently of browser lifetime. The
 * original browser-created-stub gap is closed: even a tab lost before receiving a run id has a
 * durable binding. Legacy stub PUTs still start watches during the transition.
 *
 * A dropped/stalled stream is not proof of process death. The previous/current daemon probe,
 * bounded follow/readWithinBound loop and one-second trailing checkpoints remain here as the
 * live/uncertain arms of ONE recover() coordinator. A verified missing or failed attempt advances
 * run_id by CAS and continues the same message. Exhaustion preserves saved output and finalizes
 * once; it never asks an operator to resend. Export apps still must not initiate serving recovery.
 * A detached daemon can survive failed teardown, so parent exit alone remains insufficient proof.
 *
 * Every write goes through `ChatRunLedger.settle`, which only changes a row that still belongs to
 * this run and is not yet terminal. A browser receives the saved projection and cannot
 * terminalize a daemon run through the store (`tenant-scope.ts`). A stale attempt cannot checkpoint or settle after its CAS fence.
 *
 * Why finalization stays in the API: the accepted row, principal and attempt meet here, and a
 * daemon cannot finalize its own death. The daemon saves early session locators and mutation
 * barriers through the same guarded persistence ports; projection recovery remains API-owned.
 */
import type { ChatMessage } from "@jini-ai/chat/core";
import { randomUUID } from "node:crypto";
import { createDurableRecovery } from "#src/assistant/durable-runs/recover";
import type { DurableRecovery, DurableRun, RecoveryTrigger } from "#src/assistant/durable-runs/ports";
import { verifyAttemptChildDead } from "#src/server/inbound/assistant/attempt-process-identity";
import { agentCarriesOwnMemory } from "#src/assistant/agent-session-preset";
import { isProcessAlive } from "@jini-ai/sidecar";
import type { SupervisorScheduler } from "@jini-ai/sidecar/supervisor";
import { createNodeSupervisorScheduler } from "@jini-ai/sidecar/supervisor/node";

import { AGENT_DAEMON_TOKEN_ENV_VAR, RUN_PRINCIPAL_HEADER, type ChatRunLedger, type RunSettlement } from "#src/assistant/index";
import {
  isDaemonRunId,
  readSseFrames,
  runContentFromEvents,
  runEventsForSave,
  translateRunFrame,
  type RunFrameCarry,
} from "#src/contracts/core/assistant-run-events";
import { isTerminalRunStatus, type AgentEvent } from "@jini-ai/chat/core";

import { createNoopObservabilityPort, trackFetch, type AgentRunStatus, type ObservabilityPort } from "#src/platform/observability/index";

import { getAgentDaemonUrl } from "../../lifecycle/agent-daemon-port.js";

/** The persisted run's owner, supplied by storage rather than an HTTP client. */
export interface RunDaemonRequest {
  readonly runId: string;
  readonly principalId: string;
}

/** What the finalizer needs from the daemon. Injected so tests can stand in a fake daemon. */
export interface RunDaemonClient {
  /** Opens `/api/runs/:id/events` from event 0. Resolves with the raw response. */
  openEvents(required: RunDaemonRequest, optional?: { signal?: AbortSignal }): Promise<Response>;
  /** `GET /api/runs/:id`'s HTTP status, or `null` when the daemon could not be reached at all. */
  runStatus(required: RunDaemonRequest, optional?: { signal?: AbortSignal }): Promise<number | null>;
  launch?(required: { run: DurableRun; request: { contextRef: string; agentId?: string } }, optional: {}): Promise<void>;
  cancel?(required: RunDaemonRequest, optional: {}): Promise<void>;
}

export interface AssistantRunFinalizerOptions {
  readonly ledger: ChatRunLedger;
  readonly daemon?: RunDaemonClient;
  /** Previous site daemon, used only for adopted watches; new sends always use the current daemon. */
  readonly recoveryDaemon?: RunDaemonClient;
  readonly now?: () => number;
  /** Wait between reconnects when the stream drops but the daemon still has the run. */
  readonly reconnectDelayMs?: number;
  /** Reconnects before resolving uncertainty. Runs with fresh live proof keep watching. */
  readonly maxReconnects?: number;
  /** Hard window without live proof, including stalled event requests/streams. Default 120 s.
   * A final status probe can add at most statusTimeoutMs; HTTP availability alone is not proof. */
  readonly resolutionTimeoutMs?: number;
  /** Bound every status probe, including boot discovery and the final liveness check. Default 5 s. */
  readonly statusTimeoutMs?: number;
  /** Jini's timer port; tests advance recovery deadlines without real sleeps or module mocks. */
  readonly scheduler?: SupervisorScheduler;
  /** Least time between two in-flight checkpoints of one run. Default 1000 ms; tests pass 0. */
  readonly checkpointIntervalMs?: number;
  /**
   * Saved-payload size above which checkpoints back off to `largeCheckpointIntervalMs`, measured
   * as string characters in the saved events (a lower bound of their serialized size). Each
   * checkpoint rewrites the whole projection, so a many-MB turn at the 1 s cadence churns ~100 MB/s
   * (memory cause 3). Default 5_000_000.
   */
  readonly largeCheckpointBytes?: number;
  /** Least time between checkpoints once the saved payload exceeds `largeCheckpointBytes`. Default 5000 ms. */
  readonly largeCheckpointIntervalMs?: number;
  /**
   * Records each watched run as one agent run (`RouteDeps.observability`). This is the API-side
   * point that learns every daemon run's terminal outcome, so it is where that signal belongs; the
   * daemon cannot report its own death. Also traces the default daemon client's loopback requests.
   * Default: the no-op port.
   */
  readonly observability?: ObservabilityPort;
  /** Agent-run spans use the facade; the raw port above only decorates the default HTTP client. */
  readonly tracker?: Tracker;
  readonly verifyChildDead?: (required: { pid: number; startedAt: string }, optional: {}) => Promise<boolean>;
  readonly supportsNativeResume?: (required: { agentId: string }, optional: {}) => boolean;
}

export interface AssistantRunFinalizer {
  recover: DurableRecovery["recover"];
  /** Serving boot only: adopt persisted runs and resolve interruptions/uncertainty within a bound. */
  reconcileInterrupted(required?: { now?: number }, optional?: {}): Promise<number>;
  /**
   * Starts watching `message`'s run, if it is an in-flight daemon run not already watched. A no-op for
   * a user turn, a terminal turn, a turn with no run id, or a BYOK/AG-UI run id.
   */
  watch(input: { principalId: string; conversationId: string; message: ChatMessage }, optional?: { daemon?: RunDaemonClient; attemptBase?: AgentEvent[] }): void;
  /** Resolves when every watch started so far has settled or failed to persist. For tests. */
  idle(): Promise<void>;
  /** How many runs are being watched right now. */
  activeCount(): number;
}

function daemonHeaders(principalId: string): Record<string, string> {
  const headers: Record<string, string> = { [RUN_PRINCIPAL_HEADER]: principalId, Accept: "text/event-stream" };
  const token = process.env[AGENT_DAEMON_TOKEN_ENV_VAR];
  if (token) headers.Authorization = `Bearer ${token}`;
  return headers;
}

/** The real daemon, over loopback HTTP — the same URL, token and principal header the proxy uses.
 *  Each request is one outbound span through `observability` (host/port and status, never the run id
 *  or token); the events request's span ends at the response headers, not with the stream. */
export function createHttpRunDaemonClient(
  { observability }: { observability: ObservabilityPort },
  optional: {
    /** Serving boot snapshots the prior site's registry before the replacement daemon publishes.
     * A 404 from a new port says nothing about a run still executing on the previous port. */
    previousDaemon?: () => Promise<{ url: string; pid: number } | null>;
    isAlive?: (required: { pid: number }) => boolean;
    currentUrl?: () => string;
    fetch?: typeof fetch;
  } = {},
): RunDaemonClient {
  // The global `fetch` read per call, so a test that swaps it is still honored.
  const send = trackFetch({ fetch: (url: string, init?: RequestInit) => (optional.fetch ?? fetch)(url, init), observability });
  const previous = optional.previousDaemon?.().then((record) => ({ record }), (error: unknown) => ({ error }));
  async function origin(): Promise<string> {
    const result = await previous;
    if (result && "error" in result) throw result.error;
    const record = result?.record;
    if (record && (optional.isAlive ?? isProcessAlive)({ pid: record.pid })) return record.url;
    return (optional.currentUrl ?? getAgentDaemonUrl)();
  }
  // Recovery may probe several runs concurrently. A fallback for one owner's run must never
  // redirect another run's stream to a replacement that does not hold its slot.
  const replayOrigins = new Map<string, string>();
  const replayKey = ({ runId, principalId }: RunDaemonRequest, _optional = {}) => JSON.stringify([principalId, runId]);
  async function statusAt(
    { url, runId, principalId }: RunDaemonRequest & { url: string },
    { signal }: { signal?: AbortSignal } = {},
  ): Promise<number | null> {
    try {
      const response = await send(`${url}/api/runs/${encodeURIComponent(runId)}`, {
        headers: daemonHeaders(principalId), signal: signal ?? AbortSignal.timeout(5_000),
      });
      // The response headers establish the status; a stalled body must not stall recovery.
      void response.body?.cancel().catch(() => undefined);
      return response.status;
    } catch {
      return null;
    }
  }
  return {
    async launch({ run, request }, _options) {
      const response = await send(`${(optional.currentUrl ?? getAgentDaemonUrl)()}/api/runs`, {
        method: "POST", headers: { ...daemonHeaders(run.principalId!), "Content-Type": "application/json" },
        body: JSON.stringify({ ...request, runId: run.runId, idempotencyKey: run.runId }), signal: AbortSignal.timeout(10_000),
      });
      if (!response.ok) throw new Error(`continuation rejected (${response.status})`);
      await response.body?.cancel();
    },
    async cancel(required, _options) {
      const url = replayOrigins.get(replayKey(required)) ?? await origin();
      const response = await send(`${url}/api/runs/${encodeURIComponent(required.runId)}/cancel`, {
        method: "POST", headers: { ...daemonHeaders(required.principalId), "Content-Type": "application/json" },
        body: JSON.stringify({ reason: "recovery-fence" }), signal: AbortSignal.timeout(5_000),
      });
      await response.body?.cancel();
    },
    openEvents: async (required, { signal } = {}) =>
      send(`${replayOrigins.get(replayKey(required)) ?? await origin()}/api/runs/${encodeURIComponent(required.runId)}/events`, { headers: daemonHeaders(required.principalId), signal }),
    async runStatus(required, requestOptions = {}) {
      try {
        const url = await origin();
        const status = await statusAt({ ...required, url }, requestOptions);
        if (status !== null && status !== 404) {
          replayOrigins.delete(replayKey(required));
          return status;
        }
        const current = (optional.currentUrl ?? getAgentDaemonUrl)();
        if (url === current || requestOptions.signal?.aborted) return status;
        // PID existence can mean PID reuse. A prior endpoint that cannot find this id may also
        // be a surviving daemon predating a NEW accepted attempt on the current port. Probe both
        // before declaring death; a live prior response always wins. A registry read error still
        // fails closed because the owning address is then unknown.
        const currentStatus = await statusAt({ ...required, url: current }, requestOptions);
        if (currentStatus === 200) replayOrigins.set(replayKey(required), current);
        else replayOrigins.delete(replayKey(required));
        return currentStatus;
      } catch {
        return null;
      }
    },
  };
}

/** One run being watched: the events received on the current connection, and whether it failed. */
interface Watch {
  readonly daemon: RunDaemonClient;
  readonly abortStream: AbortController;
  resolutionDeadline: number;
  readonly principalId: string;
  readonly conversationId: string;
  readonly messageId: string;
  readonly runId: string;
  readonly attemptBase: AgentEvent[];
  events: AgentEvent[];
  /** Keep the last complete checkpoint while a reconnect is still replaying an earlier prefix. */
  retainedEvents: AgentEvent[];
  /** Split-echo-line memory for the current connection; reset with `events` on every replay. */
  frameCarry?: RunFrameCarry;
  failed: boolean;
  /** Event count, start time and approximate payload size of the latest checkpoint attempt
   *  (writes are best effort). The size picks the interval before the next one. */
  checkpointedEvents: number;
  checkpointedAt: number;
  checkpointedBytes: number;
  /** Only one best-effort progress write at a time; later frames are coalesced into the next one. */
  checkpointPending: boolean;
  /** Stops progress scheduling as soon as the terminal outcome is known, before its durable write. */
  terminal: boolean;
  /** The trailing checkpoint armed when the interval skipped one (see `checkpoint`). */
  trailing?: ReturnType<typeof setTimeout>;
}

function recoverySettings({ options }: { options: AssistantRunFinalizerOptions }, _optional = {}) {
  return { reconnectDelayMs: options.reconnectDelayMs ?? 2_000, maxReconnects: Math.max(0, options.maxReconnects ?? 30),
    resolutionTimeoutMs: options.resolutionTimeoutMs ?? 120_000, statusTimeoutMs: options.statusTimeoutMs ?? 5_000,
    checkpointIntervalMs: options.checkpointIntervalMs ?? 1_000, largeCheckpointBytes: options.largeCheckpointBytes ?? 5_000_000,
    largeCheckpointIntervalMs: options.largeCheckpointIntervalMs ?? 5_000 };
}

/**
 * String characters in a JSON-shaped value: a cheap lower bound of its serialized size, measured
 * without serializing it (the point is to avoid another multi-MB string per checkpoint).
 * @complexity O(nodes) time, O(depth) stack.
 */
function approximateJsonBytes(value: unknown): number {
  if (typeof value === "string") return value.length;
  if (value === null || typeof value !== "object") return 1;
  let total = 0;
  for (const item of Array.isArray(value) ? value : Object.values(value)) total += approximateJsonBytes(item);
  return total;
}

function watchable({ message }: { message: ChatMessage }, _optional = {}): boolean {
  if (message.role !== "assistant" || !message.runId || !isDaemonRunId(message.runId)) return false;
  return message.runStatus !== undefined && !isTerminalRunStatus({ status: message.runStatus });
}

type StreamResult = { kind: "ended"; status: RunSettlement["status"] } | { kind: "gone" } | { kind: "dropped" } | { kind: "unresolved" };

/**
 * @complexity O(frame bytes + serialized checkpoint bytes) per run; O(collected events) space,
 *   with one open daemon connection and at most one pending checkpoint per in-flight run.
 */
export function createAssistantRunFinalizer(options: AssistantRunFinalizerOptions, _optional = {}): AssistantRunFinalizer {
  const observability = options.observability ?? createNoopObservabilityPort({});
  const tracker = options.tracker ?? createNoopTracker({});
  const daemon = options.daemon ?? createHttpRunDaemonClient({ observability });
  const now = options.now ?? Date.now;
  const { reconnectDelayMs, maxReconnects, resolutionTimeoutMs, statusTimeoutMs, checkpointIntervalMs, largeCheckpointBytes, largeCheckpointIntervalMs } = recoverySettings({ options });
  const scheduler = options.scheduler ?? createNodeSupervisorScheduler({});
  const active = new Map<string, { watch: Watch; done: Promise<void> }>();
  const recoveryStore = options.ledger.durable;
  const newAttempts = new Set<string>();
  const recovery = recoveryStore ? createDurableRecovery({
    store: recoveryStore, now, mintRunId: randomUUID,
    async probe(run, _options) {
      const status = await probe({ runId: run.runId, principalId: run.principalId! }, { client: newAttempts.has(run.runId) ? daemon : options.recoveryDaemon ?? daemon });
      if (status === 404) return "dead";
      return status === 200 ? "live" : "uncertain";
    },
    attach(run, _options) { finalizer.watch({ principalId: run.principalId!, conversationId: run.conversationId, message: run.message }, {
      attemptBase: [...run.attemptBase], daemon: newAttempts.has(run.runId) ? daemon : options.recoveryDaemon ?? daemon,
    }); },
    async launch(required, optional) {
      if (!daemon.launch) throw new Error("daemon continuation port is unavailable");
      newAttempts.add(required.run.runId);
      await daemon.launch(required, optional);
    },
    cancelAttempt: async (run, optional) => (newAttempts.has(run.runId) ? daemon : options.recoveryDaemon ?? daemon).cancel?.({ runId: run.runId, principalId: run.principalId! }, optional),
    // No process identity is guessed from daemon PID existence. Until the executor provides a
    // verified child identity, reconstruction is the safe universal continuation path.
    verifyChildDead: options.verifyChildDead ?? ((required, _options) => verifyAttemptChildDead(required, {})),
    supportsNativeResume: options.supportsNativeResume ?? (({ agentId }, _options) => agentCarriesOwnMemory({ agentId: agentId }, {})),
    settle: (required, _options) => options.ledger.settle(required),
  }, {}) : undefined;

  async function withinDeadline<T>(
    { work, timeoutMs }: { work: Promise<T>; timeoutMs: number },
    { fallback }: { fallback: T },
  ): Promise<T> {
    let cancel!: () => void;
    const timeout = new Promise<T>((resolve) => {
      cancel = scheduler.schedule({ delayMs: Math.max(0, timeoutMs), run: () => resolve(fallback) });
    });
    try { return await Promise.race([work, timeout]); }
    finally { cancel(); }
  }

  async function probe(
    required: RunDaemonRequest,
    { client }: { client: RunDaemonClient },
  ): Promise<number | null> {
    const abort = new AbortController();
    try {
      return await withinDeadline({
        work: client.runStatus(required, { signal: abort.signal }).catch(() => null), timeoutMs: statusTimeoutMs,
      }, { fallback: null });
    } finally { abort.abort(); }
  }

  const delay = (required: { ms: number }, _optional = {}) => new Promise<void>((resolve) => {
    scheduler.schedule({ delayMs: required.ms, run: resolve });
  });

  /** Stop progress scheduling and await the ledger's atomic terminal write; persistence errors propagate. */
  async function settle(watch: Watch, status: RunSettlement["status"], events: AgentEvent[]): Promise<void> {
    watch.terminal = true;
    watch.abortStream.abort();
    clearTimeout(watch.trailing);
    watch.trailing = undefined;
    await options.ledger.settle({
      conversationId: watch.conversationId,
      messageId: watch.messageId,
      runId: watch.runId,
      status,
      content: runContentFromEvents(events),
      events: runEventsForSave(events),
      endedAt: now(),
    });
  }

  async function recoverWatch(watch: Watch, trigger: RecoveryTrigger): Promise<void> {
    const events = interruptionEvents(watch);
    await options.ledger.checkpoint({ ...watch, content: runContentFromEvents(events), events: runEventsForSave(events) });
    watch.terminal = true;
    watch.abortStream.abort();
    clearTimeout(watch.trailing);
    if (!recovery) {
      // Only a fresh status 404 selects "stream". Reconnect/deadline exhaustion is uncertain;
      // without durable recovery's budget and session quarantine, retain this run's saved row.
      if (trigger !== "stream") return;
      await settle(watch, "canceled", [...events, { kind: "status", label: "Stopped. Saved work is above." }]);
      return;
    }
    // A launch can still be committing after durable acceptance. Space repeated missing-run
    // probes so its short grace window cannot turn into a hot loop of adopted watches.
    await delay({ ms: reconnectDelayMs });
    await recovery.recover({ messageId: watch.messageId, expectedRunId: watch.runId, trigger }, {});
  }

  function interruptionEvents(watch: Watch): AgentEvent[] {
    // Storage coalesces text deltas. Equal event counts can still mean a shorter replay prefix,
    // so both text length and event count must catch up before replacing the retained checkpoint.
    return watch.events.length >= watch.retainedEvents.length &&
      runContentFromEvents(watch.events).length >= runContentFromEvents(watch.retainedEvents).length
      ? watch.events : watch.retainedEvents;
  }

  /**
   * Saves what the run has produced so far, when it has grown since the last save and the interval
   * has passed. Only growth counts: a reconnect replays from event 0, and a checkpoint of the
   * replay's first events would shrink the saved answer.
   *
   * A save the interval skips is not dropped: a trailing checkpoint is armed for the end of the
   * interval. Without it, a run that goes quiet (a long tool call) right after a skipped frame kept
   * its last text and tool-call start in memory only, lost on any stop — the process `exit` flush
   * that used to cover a graceful stop is gone (an `exit` listener cannot await an async write).
   * At most one checkpoint is pending per run. It never blocks frame consumption: otherwise a
   * slow progress write holds an already-buffered `end` behind it, leaving a finished turn running
   * for startup repair to misclassify. Later progress is coalesced when the pending write finishes.
   * Terminal settlement uses the ledger's terminal guard to reject any late checkpoint.
   * Once the last saved payload exceeded `largeCheckpointBytes`, the interval is
   * `largeCheckpointIntervalMs` instead: each write rewrites the whole projection.
   * @complexity O(saved events) per write, with one pending write and one trailing timer per run.
   */
  async function checkpoint(watch: Watch): Promise<void> {
    if (watch.terminal || watch.checkpointPending) return;
    if (watch.events.length <= watch.checkpointedEvents) return;
    const interval = watch.checkpointedBytes > largeCheckpointBytes ? largeCheckpointIntervalMs : checkpointIntervalMs;
    const wait = interval - (now() - watch.checkpointedAt);
    if (wait > 0) {
      if (!watch.trailing) {
        watch.trailing = setTimeout(() => {
          watch.trailing = undefined;
          void checkpoint(watch);
        }, wait);
        watch.trailing.unref();
      }
      return;
    }
    clearTimeout(watch.trailing);
    watch.trailing = undefined;
    watch.checkpointedEvents = watch.events.length;
    watch.checkpointedAt = now();
    watch.checkpointPending = true;
    const events = runEventsForSave(watch.events);
    watch.checkpointedBytes = approximateJsonBytes(events);
    // Best effort: a failed checkpoint only loses what a restart would keep; the stream goes on.
    await options.ledger
      .checkpoint({
        conversationId: watch.conversationId,
        messageId: watch.messageId,
        runId: watch.runId,
        content: runContentFromEvents(watch.events),
        events,
      })
      .catch((error: unknown) => console.error(`[assistant-run-finalizer] checkpoint of run ${watch.runId} failed`, error))
      .finally(() => {
        watch.checkpointPending = false;
        void checkpoint(watch);
      });
  }

  /** Reads one connection to the end. The daemon replays from event 0 on every connection, so the
   *  events collected by an earlier, dropped connection are discarded rather than doubled. */
  async function readStream(watch: Watch): Promise<StreamResult> {
    const signal = watch.abortStream.signal;
    const response = await watch.daemon.openEvents({ runId: watch.runId, principalId: watch.principalId }, { signal });
    if (signal.aborted) {
      void response.body?.cancel().catch(() => undefined);
      return { kind: "dropped" };
    }
    if (response.status === 404) return { kind: "gone" };
    if (!response.ok || !response.body) return { kind: "dropped" };
    watch.retainedEvents = [...interruptionEvents(watch)];
    watch.events = [...watch.attemptBase];
    watch.frameCarry = {};
    watch.failed = false;
    // Cancel the reader as well as HTTP when a bounded resolution settles the row. Fakes may
    // ignore the request signal; late frames must not change a settled watch's checkpoint.
    for await (const frame of readSseFrames(response.body.pipeThrough(new TransformStream(), { signal }))) {
      if (signal.aborted) return { kind: "dropped" };
      const result = applyStreamFrame(watch, frame);
      if (result) return result;
    }
    return { kind: "dropped" };
  }

  function applyStreamFrame(watch: Watch, frame: { event: string; data: string }): StreamResult | undefined {
    const outcome = translateRunFrame(frame.event, frame.data, watch.frameCarry);
    watch.events.push(...outcome.events);
    if (outcome.error) watch.failed = true;
    if (outcome.terminal) {
      watch.terminal = true;
      return { kind: "ended", status: watch.failed && outcome.terminal === "succeeded" ? "failed" : outcome.terminal };
    }
    void checkpoint(watch);
    return undefined;
  }

  async function retainLiveWatch(watch: Watch): Promise<boolean> {
    if (!recovery) return true;
    // follow/readWithinBound are recovery's live arm. Reuse their fresh proof for this attempt
    // so reconnects and quiet approval waits neither probe twice nor spend the recovery budget.
    const result = await recovery.recover({ messageId: watch.messageId, expectedRunId: watch.runId, trigger: "timeout" }, { liveRunId: watch.runId });
    return result === "reattached" || result === "waiting";
  }

  /** A quiet stream (or a request stuck before headers) still needs bounded resolution. Keep the
   * same stream when the owning daemon answers live, so long tool/card waits are not interrupted. */
  async function readWithinBound(watch: Watch): Promise<StreamResult> {
    const stream = readStream(watch).catch((): StreamResult => ({ kind: "dropped" }));
    for (;;) {
      const result = await withinDeadline<StreamResult | { kind: "timeout" }>({
        work: stream, timeoutMs: watch.resolutionDeadline - now(),
      }, { fallback: { kind: "timeout" } });
      if (result.kind !== "timeout") return result;
      const status = await probe({ runId: watch.runId, principalId: watch.principalId }, { client: watch.daemon });
      // An end frame arriving during the final probe outranks an inconclusive HTTP response.
      if (watch.terminal) return stream;
      if (status !== 200) {
        // The deadline policy resolves uncertainty too; transport/auth errors cannot leave the
        // transcript spinning forever. The final fresh probe always gives a live daemon priority.
        return { kind: "unresolved" };
      }
      if (!await retainLiveWatch(watch)) { watch.terminal = true; watch.abortStream.abort(); return { kind: "unresolved" }; }
      watch.resolutionDeadline = now() + resolutionTimeoutMs;
    }
  }

  /** Renews a freshly verified live watch; uncertainty keeps the current reconnect budget.
   * A live run may outlast that budget, so restart counting rather than abandon its saved row.
   * Returns the next counter, or undefined after recovery relinquishes this watch and its stream.
   * @complexity O(1) bookkeeping plus one existing durable-recovery call for a live run. */
  async function prepareReconnect({ watch, status, attempt }: { watch: Watch; status: number | null; attempt: number }, _options: Record<string, never> = {}): Promise<number | undefined> {
    if (status !== 200) return attempt;
    if (!await retainLiveWatch(watch)) {
      watch.terminal = true;
      watch.abortStream.abort();
      return undefined;
    }
    watch.resolutionDeadline = now() + resolutionTimeoutMs;
    if (attempt === maxReconnects) {
      // Keep monitoring a live run even after exhausting reconnects: its later death must
      // not strand the row until another browser attachment or serving boot.
      return -1;
    }
    return attempt;
  }

  /** Follows the run to a terminal outcome or bounded resolution and reports it to the tracker. */
  async function follow(watch: Watch): Promise<AgentRunStatus> {
    for (let attempt = 0; ; attempt += 1) {
      const result = await readWithinBound(watch);
      const resolved = await resolveStreamOutcome(watch, result);
      if (resolved) return resolved;
      // A dropped stream alone proves nothing: a daemon may be mid-respawn or waiting on a card.
      // Recheck its owning endpoint before either retrying or applying the bounded fallback. Even
      // an events 404 must not override a fresh live answer from the daemon that holds the slot.
      const status = await probe({ runId: watch.runId, principalId: watch.principalId }, { client: watch.daemon });
      if (shouldRecover({ status, result, attempt, watch })) {
        await recoverWatch(watch, status === 404 ? "stream" : "timeout");
        return "interrupted";
      }
      const nextAttempt = await prepareReconnect({ watch, status, attempt });
      if (nextAttempt === undefined) return "interrupted";
      attempt = nextAttempt;
      await delay({ ms: Math.min(reconnectDelayMs, Math.max(0, watch.resolutionDeadline - now())) });
    }
  }

  function shouldRecover({ status, result, attempt, watch }: { status: number | null; result: StreamResult; attempt: number; watch: Watch }, _options = {}): boolean {
    return status === 404 || (status !== 200 && (result.kind === "gone" || attempt === maxReconnects || now() >= watch.resolutionDeadline));
  }

  async function resolveStreamOutcome(watch: Watch, result: StreamResult): Promise<AgentRunStatus | undefined> {
    if (result.kind === "ended") {
      if (result.status === "failed" && recovery) await recoverWatch(watch, "attempt-failed");
      else await settle(watch, result.status, interruptionEvents(watch));
      return result.status;
    }
    if (result.kind === "unresolved") { await recoverWatch(watch, "timeout"); return "interrupted"; }
    return undefined;
  }

  const finalizer: AssistantRunFinalizer = {
    recover: async (required, optional) => recovery ? recovery.recover(required, optional) : "gone",
    reconcileInterrupted(required = {}, _optional = {}) {
      return options.ledger.reconcileInterrupted({ now: required.now ?? now() }, {
        recover: async ({ message }) => {
          if (!message.runId) return false;
          if (recovery) {
            const result = await recovery.recover({ messageId: message.id, trigger: "boot" }, {});
            return result !== "gone";
          }
          return false;
        },
      });
    },
    watch({ principalId, conversationId, message }, optional = {}) {
      const runId = message.runId;
      if (!watchable({ message }) || !runId) return;
      if (active.has(runId) && !active.get(runId)!.watch.terminal) return;

      const watch = makeWatch({ principalId, conversationId, message, runId,
        daemon: optional.daemon ?? daemon, attemptBase: optional.attemptBase ?? [], now: now(), resolutionTimeoutMs,
      });
      startWatch(watch);
    },

    async idle() {
      while (active.size > 0) await Promise.all([...active.values()].map((entry) => entry.done));
    },

    activeCount: () => active.size,
  };

  function makeWatch({ principalId, conversationId, message, runId, daemon, attemptBase, now, resolutionTimeoutMs }: {
    principalId: string; conversationId: string; message: ChatMessage; runId: string; daemon: RunDaemonClient; attemptBase: AgentEvent[]; now: number; resolutionTimeoutMs: number;
  }, _options = {}): Watch {
    return {
        daemon,
        abortStream: new AbortController(),
        resolutionDeadline: now + resolutionTimeoutMs,
        principalId,
        conversationId,
        messageId: message.id,
        runId,
        attemptBase,
        events: [...(message.events ?? [])],
        retainedEvents: [...(message.events ?? [])],
        failed: false,
        checkpointedEvents: message.events?.length ?? 0,
        checkpointedAt: Number.NEGATIVE_INFINITY,
        checkpointedBytes: 0,
        checkpointPending: false,
        terminal: false,
    };
  }

  function startWatch(watch: Watch) {
      const { runId, conversationId } = watch;
      // Inside the run's scope, so the ledger writes the loop makes are recorded under the run.
      const done = tracker.trace({ name: "assistant.run", run: async (span) => {
        try { span.setOutcome({ status: await follow(watch) }); }
        catch (error) {
          // A watch that threw proved nothing about the run itself; the error says why it stopped.
          span.setOutcome({ status: "abandoned", error });
          console.error(`[assistant-run-finalizer] watching run ${runId} failed`, error);
        }
      } }, { agent: { runId, conversationId } })
        .finally(() => {
          watch.abortStream.abort();
          clearTimeout(watch.trailing);
          newAttempts.delete(runId);
          if (active.get(runId)?.watch === watch) active.delete(runId);
        });
      active.set(runId, { watch, done });
  }
  return finalizer;
}

// Chat routes and the daemon proxy meet on the same ledger instance. Sharing this coordinator
// avoids a browser-triggered recovery creating an independent boot/finalization engine.
type SharedFinalizer = {
  readonly finalizer: AssistantRunFinalizer;
  readonly options: Omit<AssistantRunFinalizerOptions, "recoveryDaemon"> & { recoveryDaemon?: RunDaemonClient };
};
const sharedFinalizers = new WeakMap<ChatRunLedger, SharedFinalizer>();
export function assistantRunFinalizerFor(required: AssistantRunFinalizerOptions, _optional = {}): AssistantRunFinalizer {
  const existing = sharedFinalizers.get(required.ledger);
  if (existing) {
    // An export app can construct the route module before serving composition opts into boot
    // recovery. Install its prior-daemon port on the same coordinator rather than freezing the
    // earlier export defaults or creating a second recovery engine.
    if (required.recoveryDaemon) existing.options.recoveryDaemon = required.recoveryDaemon;
    return existing.finalizer;
  }
  const options = { ...required };
  const finalizer = createAssistantRunFinalizer(options, {});
  sharedFinalizers.set(required.ledger, { finalizer, options });
  return finalizer;
}

