/** A dependency omitted by peer composition must fail visibly, never fall back to active data. */
export class CrossSiteUnavailable extends ToolInputError {
  readonly field: string;
  constructor(field: string) {
    super({ message: `This read needs ${field}, which isn't available for another site.` });
    this.field = field;
    this.name = 'CrossSiteUnavailable';
  }
}

/** Poison every operation except promise assimilation, which must terminate immediately.
 * @param required.field - Dependency name only, never a path.
 * @returns A callable poison; property access/call/construction throws CrossSiteUnavailable.
 * @complexity O(1).
 */
function unavailable({ field }: { field: string }, _options = {}): never {
  // A normal function remains constructible, so `new poison()` reaches the same refusal trap.
  function fail(): never { throw new CrossSiteUnavailable(field); }
  return new Proxy(fail, {
    get: (_target, key) => key === 'then' ? undefined : fail(),
    apply: fail, construct: fail,
  }) as never;
}

type PeerBag = {
  deps: AssistantToolRegistryDeps;
  principal: Principal;
  registrations: Map<string, ToolRegistration>;
  usedAt: number;
  busy: number;
  timer?: ReturnType<typeof setTimeout>;
  close(): Promise<void>;
};

/** Refuse directory/blob symlinks escaping the target's own tree before any file read.
 * @returns The canonical path. @throws ToolInputError with path-free text on escape.
 * @complexity O(depth) filesystem resolution, no directory traversal.
 */
function confinedPath({ root, file }: { root: string; file: string }, _options = {}): string {
  const canonical = fs.realpathSync(file);
  const relative = path.relative(fs.realpathSync(root), canonical);
  if (relative === '..' || relative.startsWith(`..${path.sep}`) || path.isAbsolute(relative)) {
    throw new ToolInputError({ message: 'This site has files outside its local folder.' });
  }
  return canonical;
}

/** Theme discovery itself reads files before individual theme handlers can apply containment.
 * Reject symlinks in the peer tree, including engine roots and manifest/template files, so discovery
 * cannot expose another site's files. Rechecked on roster access because other processes edit themes.
 * @returns void. @throws ToolInputError on an escaping root or any linked file/directory.
 * @complexity O(f) directory entries for f theme files; native recursive enumeration never follows symlinks.
 */
function assertPeerThemes({ siteDir, themesDir }: { siteDir: string; themesDir: string }, _options = {}): void {
  if (!fs.existsSync(themesDir)) return;
  confinedPath({ root: siteDir, file: themesDir });
  if (fs.readdirSync(themesDir, { withFileTypes: true, recursive: true }).some(entry => entry.isSymbolicLink())) {
    throw new ToolInputError({ message: 'Linked theme files cannot be read from another site.' });
  }
}

/** Build only plain repositories over borrowed, read-only handles. No boot/seed/migration services.
 * @param required - Target paths, checked schema, owner and open kernels.
 * @returns A fail-closed dependency bag for the existing domain builders.
 * @throws CrossSiteUnavailable on use of an omitted dependency; filesystem/SQL errors propagate to the resolver.
 * @complexity O(r + t) wiring for r repositories and t discovered theme files; no per-record SQL fan-out.
 */
async function composePeer({ source, contentDbPath, kernel, chat, journal, introspection, ownerId, workspaceId }: {
  contentDbPath: string;
  source: RegisteredSiteSource; kernel: ReturnType<typeof openSqliteFileKernel<ContentDatabase>>;
  chat: ReturnType<typeof openNativeSqlite>; journal: ReturnType<typeof openSqliteFileKernel<JournalDatabase>>;
  introspection: SqliteDatabaseIntrospectionAdapter; ownerId: string; workspaceId: string;
}, _options = {}): Promise<AssistantToolRegistryDeps> {
  const systemClock = createSystemClock(), idGen = createRandomUuidGenerator();
  const clock = { ...systemClock, nowIso: () => nowIso({ clock: systemClock }) };
  const identity = createSqliteIdentityRouteDeps({ db: kernel, workspaceId, clock, idGen,
    ownerCredentials: DEFAULT_OWNER_CREDENTIALS, permissionGrants: createAppPermissionGrants({}),
    reconcileGrantsOnBoot: false, readOnlyOwnerPrincipalId: ownerId }, { apiKeyRepo: unavailable({ field: 'apiKeyRepo' }) });
  await identity.identityReady;
  const postRepo = new SqlitePostRepo(kernel), settingsRepo = new SqliteSettingsRepo(kernel);
  const presentationRepo = new SqlitePresentationSettingsRepo(kernel);
  const entryRefsRepo = new SqliteEntryRefsRepo(kernel), mediaRepo = new SqliteMediaRepo(kernel);
  const mediaContentTypeStore = new SqliteMediaContentTypeStore(kernel);
  const transformDefinitionRepo = new SqliteTransformDefinitionRepo(kernel);
  const originRegistry = new OriginRegistry({ repo: new SqliteOriginSettingRepo(kernel) });
  const themesDir = path.join(source.dir, 'themes'), uploadsDir = path.join(source.dir, 'uploads');
  for (const file of [themesDir, uploadsDir]) if (fs.existsSync(file)) confinedPath({ root: source.dir, file });
  assertPeerThemes({ siteDir: source.dir, themesDir });
  const themes = discoverAllBuiltInThemes({ dir: themesDir, source: 'built-in' });
  const blobs = new LocalFsBlobStore({ rootDir: uploadsDir });
  // Reuse the SQLite adapter's capability answer without granting its backup/restore effects.
  const dbOps = new SqliteDbOpsAdapter({ connection: { backup: unavailable({ field: 'dbOps.captureRestorePoint' }) },
    filePath: contentDbPath, readWatermark: unavailable({ field: 'dbOps.readWatermark' }) });
  const trashRepo = new SqliteTrashRepo(kernel);
  const formDeliveryRepo = new SqlFormDeliveryRepo({ kernel });
  const seoDeps = createSeoDeps({ deps: { postRepo, settingsRepo, mediaRepo, mediaContentTypeStore, transformDefinitionRepo, originRegistry, clock } }, {});
  const bag = {
    ...identity, contentKernel: kernel, workspaceId, clock, idGen, settingsRepo, getEffective,
    // Optional build-time settings are explicit so builders don't iterate a poison value.
    extraDeniedSettings: [], settingsUiTabsReady: Promise.resolve(), settingsReady: Promise.resolve(), siteTitleReady: Promise.resolve(),
    peerSiteReads: undefined, isSiteSwitcherEnabled: () => false, devRestart: null,
    postRepo, postSearch: postSearchIndexFor(kernel), entryRefsRepo,
    pagesHtmlStore: (scope: Parameters<AssistantToolRegistryDeps['pagesHtmlStore']>[0], options: Parameters<AssistantToolRegistryDeps['pagesHtmlStore']>[1] = {}) => new PagesHtmlDocumentStore(scope, { ...options, db: kernel, clock, entryRefsRepo, revisions: postRepo }),
    mediaRepo, assetBlobRepo: new SqliteAssetBlobRepo(kernel), assetRenditionRepo: new SqliteAssetRenditionRepo(kernel), mediaContentTypeStore, transformDefinitionRepo,
    // Only read capabilities are exposed; neither a stray blob write nor an escaping stored key can reach disk.
    blobStore: {
      get: async ({ storageKey }: { storageKey: string }) => {
        confinedPath({ root: source.dir, file: uploadsDir });
        confinedPath({ root: uploadsDir, file: path.join(uploadsDir, storageKey) });
        return blobs.get({ storageKey });
      },
      exists: async ({ storageKey }: { storageKey: string }) => {
        if (fs.existsSync(uploadsDir)) confinedPath({ root: source.dir, file: uploadsDir });
        if (!fs.existsSync(path.join(uploadsDir, storageKey))) return false;
        confinedPath({ root: uploadsDir, file: path.join(uploadsDir, storageKey) });
        return blobs.exists({ storageKey });
      },
      sizeOf: async ({ storageKey }: { storageKey: string }) => {
        if (fs.existsSync(uploadsDir)) confinedPath({ root: source.dir, file: uploadsDir });
        if (!fs.existsSync(path.join(uploadsDir, storageKey))) return null;
        confinedPath({ root: uploadsDir, file: path.join(uploadsDir, storageKey) });
        return blobs.sizeOf({ storageKey });
      },
      put: unavailable({ field: 'blobStore.put' }), putIfAbsent: unavailable({ field: 'blobStore.putIfAbsent' }), delete: unavailable({ field: 'blobStore.delete' }),
    },
    // The existing factories borrow their connection; construction/get/history reads never write.
    workspaceRepo: new SqliteWorkspaceRepo(kernel), chatHistory: createChatStoreFactory(chat),
    formDefinitionRepo: new SqliteFormDefinitionRepo(kernel), formSubmissionRepo: new SqliteFormSubmissionRepo(kernel),
    // Status reads only (the repo's plan-once write stays unreachable), over the peer's own outbox rows;
    // the handler scopes them to the peer workspaceId above, and rows carry ids and safe codes, never answers.
    formDeliveryStatus: { forSubmission: formDeliveryRepo.forSubmission.bind(formDeliveryRepo), recentUnfinished: formDeliveryRepo.recentUnfinished.bind(formDeliveryRepo) },
    taxonomyRepo: new SqliteTaxonomyRepo({ db: kernel, workspaceId }), termRepo: new SqliteTermRepo({ db: kernel, workspaceId }),
    entryTermRepo: new SqliteEntryTermRepo({ db: kernel, workspaceId }), taxonomyRevisionRepo: new SqliteTaxonomyRevisionRepo({ db: kernel, workspaceId }),
    menuRepo: new SqliteMenuRepo(kernel), navLocationBindingRepo: new SqliteNavLocationBindingRepo(kernel),
    entryRepo: new SqliteEntryRepo(kernel), contentTypeRepo: new SqliteContentTypeRepo(kernel),
    themesDir, get themes() { assertPeerThemes({ siteDir: source.dir, themesDir }); return themes; },
    // Preview-switcher reads the peer preference through the existing resolver; expose no writer.
    presentationRepo: { findByWorkspaceId: presentationRepo.findByWorkspaceId.bind(presentationRepo),
      save: unavailable({ field: 'presentationRepo.save' }), listAll: unavailable({ field: 'presentationRepo.listAll' }) },
    // Use the renderer's resolver over the peer's read-only settings, never the active site's closure.
    resolveActiveThemeId: () => resolveActiveThemeId({ presentationRepo, workspaceId }),
    commentRepo: new SqliteCommentRepo({ store: kernel }, {}), commentsReady: Promise.resolve(), commentsSettingsReady: Promise.resolve(),
    memberRepo: new SqliteMemberRepo(kernel), memberTierRepo: new SqliteMemberTierRepo(kernel), memberSubscriptionRepo: new SqliteMemberSubscriptionRepo(kernel),
    newsletterReady: Promise.resolve(), newsletterCampaignRepo: new SqliteNewsletterCampaignRepo(kernel), newsletterListRepo: new SqliteNewsletterListRepo(kernel),
    newsletterSubscriptionRepo: new SqliteNewsletterSubscriptionRepo(kernel), newsletterAudienceSnapshotRepo: new SqliteNewsletterAudienceSnapshotRepo(kernel), newsletterSendRepo: new SqliteNewsletterSendRepo(kernel),
    redirectRepo: SqliteRedirectRepo({ store: kernel }, {}), originRegistry, seoDeps, seoReady: Promise.resolve(),
    // redirects_list hides Trashed rules (03fb27a27) by reading the PEER's Trash rows; every write stays poisoned.
    redirectsWriteDeps: readsOnly({ field: 'redirectsWriteDeps', reads: { isInTrash: async ({ workspaceId: id, id: entityId }: { workspaceId: string; id: string }) =>
      (await trashRepo.findByEntity({ workspaceId: id, entityType: REDIRECT_ENTITY_TYPE, entityId })) !== null } }),
    widgetBindingRepo: new SqliteWidgetRegionBindingRepo(kernel), changeSets: new SqliteChangeSetRepo(kernel),
    registry: buildTrashRegistry(), trash: { list: trashRepo.list.bind(trashRepo) },
    databaseIntrospection: introspection, dbOps: { getCapabilities: dbOps.getCapabilities.bind(dbOps) },
    gatedMutations: { gatewayDeps: buildGatewayDeps({ clock, idGen, authorize: identity.authorize,
      authorizeInstance: buildOwnerOnlyInstanceAuthorize({ ownerPrincipalId: identity.ownerPrincipalId }), tokens: unavailable({ field: 'gatedMutations.tokens' }) }) },
    databaseLedgerRepo: new SqliteDatabaseLedgerRepo({ db: journal, siteId: workspaceId }),
    migrationRunsRepo: new SqliteMigrationRunsRepo({ db: journal, siteId: workspaceId }),
    restorePointsRepo: new SqliteRestorePointsRepo({ db: journal, siteId: workspaceId }),
  };
  // Spreading active deps would let a read silently return the ACTIVE site's data under another site's label.
  return new Proxy(bag, { get: (target, field, receiver) => Reflect.has(target, field)
    ? Reflect.get(target, field, receiver) : field === 'then' ? undefined : unavailable({ field: String(field) }) }) as unknown as AssistantToolRegistryDeps;
}

/** A peer port that exposes only the named reads; every other member is a CrossSiteUnavailable poison.
 * @complexity O(1) per access. */
function readsOnly({ field, reads }: { field: string; reads: Record<string, unknown> }, _options = {}): never {
  return new Proxy(reads, { get: (target, key) => Reflect.has(target, key)
    ? Reflect.get(target, key) : key === 'then' ? undefined : unavailable({ field: `${field}.${String(key)}` }) }) as never;
}

/** Reject invalid cache bounds before registry access or database opens. O(1). */
function validatePeerCacheBounds({ maxSites, idleMs }: { maxSites: number; idleMs: number }, _options = {}): void {
  if (!Number.isInteger(maxSites) || maxSites < 1 || !Number.isFinite(idleMs) || idleMs <= 0) throw new TypeError('Invalid peer cache bounds');
}

/** Resolve safe registry names and cache at most maxSites write-free peer bags.
 * @param required.currentSiteDir - The boot-selected active site, never request input.
 * @param optional - Workspace/open/clock/timer ports and small LRU bounds for hermetic tests.
 * @returns A resolver whose close releases all handles and idle timers.
 * @throws ToolInputError with fixed, path-free refusals for unavailable peers or behind schemas.
 * @complexity O(n + t + f) per cold resolution for n registered sites, t tools and f theme files; warm lookup is O(n).
 * @example createPeerSiteReads({ currentSiteDir }, { workspace, localHost: true });
 */
export function createPeerSiteReads({ currentSiteDir }: { currentSiteDir: string }, {
  workspace, localHost = isLocalTovuHost({}, {}), openContent = openSqliteFileKernel, openChat = openNativeSqlite,
  maxSites = 3, idleMs = 5 * 60_000, now = Date.now, schedule = setTimeout,
}: { workspace?: SitesWorkspace; localHost?: boolean; openContent?: typeof openSqliteFileKernel; openChat?: typeof openNativeSqlite;
  maxSites?: number; idleMs?: number; now?: () => number; schedule?: typeof setTimeout } = {}): PeerSiteReads {
  validatePeerCacheBounds({ maxSites, idleMs });
  const cache = new Map<string, PeerBag>();
  const running = new Set<Promise<unknown>>();
  let closed = false;
  // Serialize cold opens, evictions and close: concurrent first reads must not create duplicate bags.
  let pending: Promise<unknown> = Promise.resolve();
  // Lazy workspace resolution keeps registry/filesystem access behind the adapter's owner gate.
  const catalog = () => (workspace ??= createSitesWorkspace({}));
  const assertLocal = () => {
    if (!localHost) throw new ToolInputError({ message: 'Reading another site needs a local Tovu host.' });
  };
  const isCurrentSite: PeerSiteReads['isCurrentSite'] = ({ siteName }) => {
    assertLocal();
    try {
      return catalog().registry({}).list({}).some(entry => {
        if (entry.name !== siteName) return false;
        try { return fs.realpathSync(entry.path) === fs.realpathSync(currentSiteDir); } catch { return false; }
      });
    } catch { throw new ToolInputError({ message: 'The local site registry cannot be read.' }); }
  };
  /** Close an evicted/idle entry exactly once. @complexity O(1), at most three handles. */
  const remove = async (key: string, entry: PeerBag) => {
    if (cache.get(key) !== entry || entry.busy) return;
    cache.delete(key);
    clearTimeout(entry.timer);
    await entry.close();
  };
  /** Reset an unref'd idle timer; an injected clock can also expire entries on the next resolve. */
  const touch = (key: string, entry: PeerBag) => {
    entry.usedAt = now();
    cache.delete(key); cache.set(key, entry);
    clearTimeout(entry.timer);
    entry.timer = schedule(() => {
      pending = pending.then(() => remove(key, entry)).catch(() => {});
    }, idleMs);
    entry.timer.unref();
  };
  /** Open and compose one read-only peer; failed provisional opens close all acquired handles.
   * @complexity O(t + f) for t registrations and f theme files, plus bounded schema/owner reads. */
  const openPeer = async ({ source, paths, request }: {
    source: RegisteredSiteSource;
    paths: ReturnType<typeof resolveSiteDatabasePaths>;
    request: Parameters<PeerSiteReads['resolve']>[0];
  }, _options = {}): Promise<PeerBag> => {
    const kernel = openContent<ContentDatabase>(paths.contentDbPath, { readOnly: true });
    let chat: ReturnType<typeof openChat> | undefined, journal: ReturnType<typeof openContent<JournalDatabase>> | undefined;
    try {
      const introspection = new SqliteDatabaseIntrospectionAdapter({ db: kernel, dbPath: paths.contentDbPath });
      const schema = await introspection.getSchemaState(), pendingMigrations = await introspection.listPendingMigrations();
      if (schema.status === 'behind' || pendingMigrations.items.length > 0) throw new ToolInputError({ message: `Open ${source.name} in Tovu once to upgrade it.` });
      if (schema.status !== 'in-sync') throw new ToolInputError({ message: 'This site has an unsupported database schema. Open it in Tovu first.' });
      const workspaceId = (await resolveWorkspace({ kernel })).id;
      // Users are site-local: never reuse the caller's principal or infer ownership from username/email.
      const owners = await kernel.query<{ principal_id: string }>(sql`SELECT DISTINCT u.principal_id
        FROM identity_users u JOIN principal_roles pr ON pr.principal_id=u.principal_id AND pr.workspace_id=u.workspace_id
        JOIN roles r ON r.id=pr.role_id AND r.workspace_id=pr.workspace_id
        WHERE u.workspace_id=${workspaceId} AND r.name='owner' LIMIT 2`);
      if (owners.length !== 1) throw new ToolInputError({ message: 'The target site must have exactly one owner to read it.' });
      if (!fs.existsSync(paths.chatDbPath)) throw new ToolInputError({ message: "This site's chat database is missing. Open the site in Tovu first." });
      const chatOptions = { readonly: true, fileMustExist: true, timeout: 5000 };
      chat = openChat(paths.chatDbPath, chatOptions);
      const journalPath = path.join(path.dirname(paths.contentDbPath), 'ops', 'database-journal.db');
      if (!fs.existsSync(journalPath)) throw new ToolInputError({ message: "This site's database journal is missing. Open the site in Tovu first." });
      journal = openContent<JournalDatabase>(journalPath, { readOnly: true });
      const deps = await composePeer({ source, contentDbPath: paths.contentDbPath, kernel, chat, journal, introspection, ownerId: owners[0]!.principal_id, workspaceId });
      const registrations = new Map(request.buildRegistrations(deps).filter(registration => isReadOnlyTool({ descriptor: registration.descriptor })).map(registration => [registration.descriptor.id, registration]));
      const peerChat = chat, peerJournal = journal;
      const entry: PeerBag = { deps, registrations, usedAt: now(), busy: 0, principal: constrainPrincipalToReadOnlyTools({ principal: { id: owners[0]!.principal_id } }),
        close: async () => { try { peerChat.close(); } finally { try { await peerJournal?.close(); } finally { await kernel.close(); } } } };
      return entry;
    } catch (error) {
      await Promise.allSettled([Promise.resolve().then(() => chat?.close()), journal?.close(), kernel.close()]);
      throw error;
    }
  };
  /** Expire idle bags, then evict the least recently used idle bag only for a cold open. O(cache size). */
  const cachedOrMakeRoom = async ({ key }: { key: string }, _options = {}): Promise<PeerBag | undefined> => {
    for (const [id, entry] of cache) if (now() - entry.usedAt >= idleMs) await remove(id, entry);
    const entry = cache.get(key);
    if (entry) return entry;
    while (cache.size >= maxSites) {
      const candidate = [...cache].find(([, bag]) => bag.busy === 0);
      if (!candidate) throw new ToolInputError({ message: 'Other-site reads are busy. Try again.' });
      const [id, oldest] = candidate;
      await remove(id, oldest);
    }
    return undefined;
  };
  const resolve: PeerSiteReads['resolve'] = required => {
    const work = pending.then(async () => {
      assertLocal();
      if (closed) throw new ToolInputError({ message: 'Cross-site reads are closed.' });
      try {
        if (isCurrentSite({ siteName: required.siteName })) return 'current' as const;
        const active = resolveSiteDatabasePaths({ dir: currentSiteDir }, { workspace: catalog(), reserveIdentity: false });
        const matches = registeredSources({ workspace: catalog(), targetSiteId: active.siteId, targetSiteDir: currentSiteDir, targetFile: active.contentDbPath }).filter(source => source.name === required.siteName);
        if (matches.length !== 1) throw new ToolInputError({ message: 'No readable local site has that name. Use sites_list to find a site.' });
        const source = matches[0]!;
        if (resolveSiteStorage(source.dir).kind !== 'sqlite') throw new ToolInputError({ message: 'Only local SQLite sites can be read.' });
        const paths = resolveSiteDatabasePaths({ dir: source.dir }, { workspace: catalog(), reserveIdentity: false });
        const key = `${source.siteId}:${paths.contentDbPath}`;
        let entry = await cachedOrMakeRoom({ key });
        if (!entry) {
          entry = await openPeer({ source, paths, request: required });
          cache.set(key, entry);
        }

        touch(key, entry);
        const registration = entry.registrations.get(required.toolId);
        if (!registration) throw new ToolInputError({ message: "This tool can't read another site." });
        const selected = entry;
        return { principal: entry.principal, site: source, handler: async (ctx: ToolExecutionContext, optional?: ToolExecutionOptions) => {
          if (closed || cache.get(key) !== selected) throw new ToolInputError({ message: 'This site read expired. Try again.' });
          selected.busy++;
          clearTimeout(selected.timer);
          // Track the entire handler lifetime so close/idle/eviction cannot interrupt an active read.
          const read = Promise.resolve().then(() => registration.handler(ctx, optional));
          running.add(read);
          try { return await read; }
          finally { running.delete(read); selected.busy--; if (!closed) touch(key, selected); }
        } };
      } catch (error) {
        if (error instanceof ToolInputError) throw error;
        // SQLite/config errors may contain private paths; expose only a fixed refusal to the model.
        throw new ToolInputError({ message: 'This site cannot be read. Open it in Tovu and try again.' });
      }
    });
    pending = work.catch(() => {});
    return work;
  };
  return { readDomains: CROSS_SITE_READ_DOMAINS, excludedReadTools: new Set(Object.keys(CROSS_SITE_EXCLUDED_TOOLS)), isCurrentSite, resolve,
    async close() { closed = true; await pending; await Promise.allSettled([...running]); await Promise.all([...cache].map(([key, entry]) => remove(key, entry))); },
  };
}

import { credentialDeletionRepo } from "#src/features/vendor-credentials/project-scope";
import { isBuiltInExternalMcpServer } from "#src/features/external-mcp/built-in-connections";
import { OwnerRequiredError } from "@jini-ai/user-management";
import { assertUserAccountAction, SelfDeleteError, callerMayManageUserTrash } from "#src/features/identity/delete-user-service";
import { identityServiceDepsFrom } from "#src/server/inbound/admin-http/routes/users/deps";
import { isDeepStrictEqual } from "node:util";
import { ToolInputError } from "@jini-ai/core";
import { purgeMedia, MediaNotFoundError, MediaStillReferencedError } from "#src/features/media/index";
import { deleteCustomCredential, describeCredential as describeCustomCredential } from "#src/features/custom-credentials/index";
import { deletePublishCredential, findPublishCredentialRecord } from "#src/features/deployments/publish-credentials/index";
import { deleteSourceControlCredential, describeCredential as describeSourceControlCredential } from "#src/features/source-control/index";
import { deleteExternalMcpServer } from "#src/assistant/index";
import { mayActOnEntityType } from "#src/features/trash/index";
import { type TrashItem } from "@jini-ai/cms/trash";
import type { PermanentDeletePlan, PermanentDeleteToolDeps } from "#src/features/permanent-delete/tool-registrations";
import type { PermanentDeleteToolId } from "#src/features/permanent-delete/agent-tools";
import type { RouteDeps } from "#src/server/routes/types";

/** Host adapter only: the tools never import server or reach credential services directly. */
type Deps = Pick<RouteDeps,
  "workspaceId" | "authorize" | "clock" | "trash" | "registry" | "ownerPrincipalId" | "principalRepo" |
  "mediaRepo" | "entryRefsRepo" | "postRepo" | "assetBlobRepo" | "assetRenditionRepo" | "blobStore" | "forgetRemovedMedia" |
  "idGen" | "userRepo" | "sessionRepo" | "roleRepo" | "policyRepo" | "policyPermissionRepo" | "rolePolicyRepo" | "principalRoleRepo" | "principalPolicyRepo" | "passwordHasher" | "transactions" | "tokens" |
  "commentRepo" | "commentWriteService" | "externalMcpServerRepo" | "builtInExternalMcpServerIds" | "customCredentialSetRepo" |
  "vendorCredentialSetRepo" | "contentKernel" | "loadDeployTargets" | "sourceControlCredentialSetRepo"
>;
const PAGE_SIZE = 100;

/** Caller-correctable lookup refusal; never reveals a credential's secret material. */
function notFound(toolId: string): ToolInputError {
  return new ToolInputError({ message: `${toolId}: item was not found. List the resource and check its id.` });
}

/**
 * Snapshot one resource without decrypting it. The private copy includes ciphertext so rotation
 * during the human wait invalidates consent, while the card exposes only the supplied label/id.
 * Reuses existing delete services; their internal transactions/default promotion remain intact.
 * @param spec - Loader, label formatter and existing deletion service for one fixed saved id.
 * @returns A card preview with an effect that rechecks the snapshot immediately before deleting.
 * @throws ToolInputError for missing or changed records. Service failures propagate to redaction.
 * @complexity O(s) copying/comparing a record of size s plus two indexed reads and service cost.
 */
async function recordPlan<T>(spec: {
  toolId: PermanentDeleteToolId; id: string; load(): Promise<T | null>;
  label(record: T): string; remove(): Promise<Record<string, unknown>>; warning?: string;
}): Promise<PermanentDeletePlan> {
  const found = await spec.load();
  if (!found) throw notFound(spec.toolId);
  const snapshot = structuredClone(found);
  return {
    details: [{ label: "Count", value: "1" }, { label: "Item", value: `${spec.label(found)} (${spec.id})` }],
    ...(spec.warning ? { warning: spec.warning } : {}),
    execute: async () => {
      const current = await spec.load();
      if (!current) throw notFound(spec.toolId);
      if (!isDeepStrictEqual(current, snapshot)) {
        throw new ToolInputError({ message: `${spec.toolId}: item changed while confirmation was open. Request a new confirmation; nothing was deleted.` });
      }
      return spec.remove();
    },
  };
}

/**
 * Yield listed Trash rows through the public port. Entity-type filters keep user lookup scoped;
 * keyset pagination covers every page. No entity payload is ever parsed.
 * @complexity O(n) Trash rows in the requested kinds; O(100) transient page space.
 */
async function* listedTrashItems(deps: Deps, entityTypes?: string[]): AsyncGenerator<TrashItem> {
  let cursor: string | null = null;
  const now = deps.clock.nowIso();
  do {
    const page = await deps.trash.list({ workspaceId: deps.workspaceId, now, limit: PAGE_SIZE }, { cursor, ...(entityTypes ? { entityTypes } : {}) });
    yield* page.items;
    cursor = page.nextCursor;
  } while (cursor !== null);
}

/** Find one row without retaining the entire Trash; returns null when absent.
 * @complexity O(n) row comparisons, O(100) page space.
 */
async function findTrashItem(deps: Deps, matches: (item: TrashItem) => boolean, entityTypes?: string[]): Promise<TrashItem | null> {
  for await (const item of listedTrashItems(deps, entityTypes)) {
    if (matches(item)) return item;
  }
  return null;
}

/** Preserve the existing per-kind evaluator, with the dedicated permanent-delete force gates.
 * Self and seeded-owner protection applies to ALL Trash purge tools, not only user-delete.
 * @complexity O(1) plus one authorization/owner lookup.
 */
async function mayPurgeItem(deps: Deps, item: TrashItem, principalId: string): Promise<boolean> {
  if (item.entityType === "user") {
    const identity = identityServiceDepsFrom(deps);
    try {
      await assertUserAccountAction({ deps: identity, workspaceId: deps.workspaceId, principalId: item.entityId, action: "purge" },
        { callerPrincipalId: principalId, seededOwnerPrincipalId: await deps.ownerPrincipalId });
    } catch (error) {
      if (error instanceof SelfDeleteError || error instanceof OwnerRequiredError) return false;
      throw error;
    }
    return callerMayManageUserTrash({ deps: identity, workspaceId: deps.workspaceId, callerPrincipalId: principalId });
  }
  const forcePermission = item.entityType === "media" ? "media.delete.force" : item.entityType === "comment" ? "comments.delete.force" : null;
  if (forcePermission) {
    return (await deps.authorize({ workspaceId: deps.workspaceId, principalId, permission: forcePermission, entityType: item.entityType, entityId: item.entityId })).allowed;
  }
  return (await mayActOnEntityType(deps, { principalId, entityType: item.entityType, entityId: item.entityId })).allowed;
}

/**
 * Fix the reviewed selection before opening the card, then let Trash resolve/authorize each stored
 * row again inside purgeSelected. New arrivals and replacements cannot inherit old consent.
 * @throws ToolInputError when any selected row is unauthorized, before its title is shown.
 * @complexity O(k) authorization calls and snapshot space for k selected rows.
 */
async function trashPlan(deps: Deps, toolId: PermanentDeleteToolId, items: TrashItem[], principalId: string): Promise<PermanentDeletePlan> {
  const snapshots = new Map(items.map(item => [item.id, structuredClone(item)]));
  for (const item of items) {
    if (!await mayPurgeItem(deps, item, principalId)) throw new ToolInputError({ message: `${toolId}: permission denied for a selected Trash item. Nothing was deleted.` });
  }
  return {
    // Jini owns scrollable detail rendering; keep the complete reviewed list in its native code block.
    details: [{ label: "Count", value: String(items.length) }, ...(toolId === "trash_empty"
      ? [{ label: "Trash items", value: items.map(item => `${item.entityType}: ${item.displayTitle} (${item.id})`).join("\n"), format: "code" as const }]
      : items.map(item => ({ label: item.entityType, value: `${item.displayTitle} (${item.id})` })))],
    execute: async () => {
      const current: TrashItem[] = [];
      for await (const item of listedTrashItems(deps)) {
        if (toolId === "trash_empty" || snapshots.has(item.id)) current.push(item);
      }
      const currentById = new Map(current.map(item => [item.id, item]));
      if (currentById.size !== snapshots.size || [...snapshots].some(([id, snapshot]) => !isDeepStrictEqual(currentById.get(id), snapshot))) {
        throw new ToolInputError({ message: `${toolId}: target set changed while confirmation was open. Request a new confirmation; nothing was deleted.` });
      }
      const report = await deps.trash.purgeSelected({
        workspaceId: deps.workspaceId, ids: [...snapshots.keys()], actor: { principalId },
        authorizeItem: async ({ item }) => isDeepStrictEqual(item, snapshots.get(item.id)) && await mayPurgeItem(deps, item, principalId),
      });
      return { removed: report.purged > 0, purged: report.purged, results: report.results };
    },
  };
}

async function prepareUserTrash({ deps, toolId, id, principalId }: {
  deps: Deps; toolId: PermanentDeleteToolId; id: string; principalId: string;
}, _options = {}): Promise<PermanentDeletePlan> {
  if (id === principalId || id === await deps.ownerPrincipalId) throw new ToolInputError({ message: "identity_user_delete: cannot permanently delete yourself or the seeded owner." });
  const item = await findTrashItem(deps, item => item.entityId === id, ["user"]);
  if (!item) {
    const principal = await deps.principalRepo.findById({ workspaceId: deps.workspaceId, id });
    if (!principal) throw notFound(toolId);
    throw new ToolInputError({ message: "identity_user_delete: user is not in Trash. Move the user to Trash first, then request permanent deletion." });
  }
  return trashPlan(deps, toolId, [item], principalId);
}

/** Prepare the exact public Trash selection across every page. The single-user branch follows
 * the existing Trash-only deletion ladder. No new arrival inherits consent after preparation.
 * @complexity O(n) reads for n listed items, O(n) snapshot/card space for Empty Trash.
 */
async function prepareTrash(deps: Deps, toolId: PermanentDeleteToolId, id: string | null, principalId: string): Promise<PermanentDeletePlan> {
  if (toolId === "trash_empty") {
    const items: TrashItem[] = [];
    for await (const item of listedTrashItems(deps)) items.push(item);
    if (items.length === 0) throw new ToolInputError({ message: "trash_empty: Trash is empty. Nothing to permanently delete." });
    return trashPlan(deps, toolId, items, principalId);
  }
  if (id === null) throw notFound(toolId);
  if (toolId === "identity_user_delete") return prepareUserTrash({ deps, toolId, id, principalId });
  const item = await findTrashItem(deps, item => item.id === id);
  if (!item) throw notFound(toolId);
  return trashPlan(deps, toolId, [item], principalId);
}

/**
 * Bind each confirmed effect to the same resource service the admin route uses. Credential lookups
 * never decrypt; publish-host lookup uses the current vendor table and deploy registry.
 * @param deps - Workspace-scoped ports from the host's composition root.
 * @returns Permission evaluator and preparation adapter for all nine permanent-delete tools.
 * @throws ToolInputError for missing targets, changed state and deletion-ladder refusals.
 * @complexity O(1) to compose; each preparation delegates the costs documented above.
 */
export function buildPermanentDeleteDeps(deps: Deps): PermanentDeleteToolDeps {
  return {
    workspaceId: deps.workspaceId, authorize: deps.authorize,
    // The trash ids return before the switch, which covers every other id; TypeScript cannot see
    // that through `includes`, so it would add `undefined` to the result type.
    prepare: (async (toolId, id, principalId) => {
      if (["trash_empty", "trash_purge_item", "identity_user_delete"].includes(toolId)) return prepareTrash(deps, toolId, id, principalId);
      if (id === null) throw notFound(toolId);
      const key = { workspaceId: deps.workspaceId, id };
      switch (toolId) {
        case "media_purge_asset":
          return recordPlan({
            toolId, id, load: async () => {
              const asset = await deps.mediaRepo.findById(key);
              if (asset && asset.status !== "trashed") throw new ToolInputError({ message: "media_purge_asset: media must be trashed first. Use media_trash_asset, then request permanent deletion." });
              return asset;
            }, label: asset => asset.title,
            warning: "The asset and renditions are permanently removed. Shared file bytes remain; unshared bytes follow the existing garbage-collection grace period.",
            remove: async () => {
              try {
                await purgeMedia({ deps: { mediaRepo: deps.mediaRepo, entryRefsRepo: deps.entryRefsRepo, postRepo: deps.postRepo, blobRepo: deps.assetBlobRepo, renditionRepo: deps.assetRenditionRepo, blobStore: deps.blobStore, clock: deps.clock }, input: key });
                await deps.forgetRemovedMedia(key);
                return { removed: true, id };
              } catch (error) {
                if (error instanceof MediaNotFoundError || error instanceof MediaStillReferencedError) throw new ToolInputError({ message: error.message });
                throw error;
              }
            },
          });
        case "comments_purge_comment":
          return recordPlan({ toolId, id, load: () => deps.commentRepo.findById(key), label: comment => `Comment by ${comment.authorName}`, remove: async () => {
            const result = await deps.commentWriteService.purge({ ...key, actorPrincipalId: principalId, note: null });
            if (!result.ok) throw notFound(toolId);
            return { removed: true, id };
          } });
        case "external_mcp_delete": {
          if (isBuiltInExternalMcpServer({ serverId: id, ids: deps.builtInExternalMcpServerIds })) {
            throw new ToolInputError({ message: "built-in MCP connections cannot be removed" });
          }
          const serverKey = { workspaceId: deps.workspaceId, serverId: id };
          return recordPlan({ toolId, id, load: () => deps.externalMcpServerRepo.findByServerId(serverKey), label: server => server.label ?? server.serverId,
            warning: "Deletes saved configuration and authentication. Its tools refuse future calls; restart the assistant to remove their stale listings.",
            remove: async () => {
              if (!await deleteExternalMcpServer({ repo: deps.externalMcpServerRepo }, serverKey)) throw notFound(toolId);
              return { removed: true, id, restartRequired: true };
            },
          });
        }
        case "custom_credential_delete":
          // This site's own key, else the attached project key (deletion is refused while other sites use it).
          return recordPlan({ toolId, id, load: () => describeCustomCredential({ repo: credentialDeletionRepo({ repo: deps.customCredentialSetRepo }) }, key), label: credential => credential.label,
            warning: "Deletes the saved custom credential. The token is not revoked at its provider.",
            remove: async () => { await deleteCustomCredential({ repo: credentialDeletionRepo({ repo: deps.customCredentialSetRepo }) }, key); return { removed: true, id }; } });
        case "deployment_delete_provider_credential":
          return recordPlan({ toolId, id, load: async () => {
            const record = await findPublishCredentialRecord({ repo: credentialDeletionRepo({ repo: deps.vendorCredentialSetRepo }) }, key);
            if (!record) return null;
            const hosts = (await deps.loadDeployTargets(deps.workspaceId)).list().filter(host => host.descriptor.credential?.vendorId === record.vendorId).map(host => host.descriptor.id);
            return { ...record, affectedHosts: hosts };
          }, label: credential => `${credential.label} (${credential.vendorId}); used by publish hosts: ${credential.affectedHosts.join(", ") || "none"}`,
            warning: "Deletes this vendor credential shared by its publish hosts. Another credential may become the default. Deployed sites remain; the token is not revoked at its provider.",
            remove: async () => { await deletePublishCredential({ repo: credentialDeletionRepo({ repo: deps.vendorCredentialSetRepo }), transaction: deps.contentKernel }, key); return { removed: true, id }; } });
        case "source_control_delete_credential":
          return recordPlan({ toolId, id, load: () => describeSourceControlCredential({ repo: credentialDeletionRepo({ repo: deps.sourceControlCredentialSetRepo }) }, key), label: credential => credential.label,
            warning: "Deletes the saved source-control credential. Another credential may become the default. Repositories remain; the token is not revoked at its provider.",
            remove: async () => { await deleteSourceControlCredential({ repo: credentialDeletionRepo({ repo: deps.sourceControlCredentialSetRepo }) }, key); return { removed: true, id }; } });
      }
    }) as PermanentDeleteToolDeps["prepare"],
  };
}

import { type LoadPluginContributions, createTovuAgentPluginLifecycle, type TrustedPluginPackage } from '#src/features/agent-plugins/lifecycle';
import { credentialCardsContribution, mergePluginCredentialCards } from '#src/features/agent-plugins/credential-cards';
import { parseDeployTargetsFile } from '#src/features/deployments/deploy-targets/registry';
import { parseSourceControlProvidersFile } from '#src/features/source-control/provider-registry';
import { parseMailAdaptersFile } from '#src/features/agent-plugins/mail-adapter-registry';
import type { AgentPluginLayout } from '#src/features/agent-plugins/layout';
import { readProviderPluginLink } from '#src/features/agent-plugins/identity';
import type { LoadPluginCredentialCards, PluginCredentialCard } from '#src/features/custom-credentials/plugin-credential-card';

type ReadFile = (required: { plugin: TrustedPluginPackage; filename: string }, optional?: Record<string, never>) => Promise<string>;

function isApiCard({ card }: { card: PluginCredentialCard }, _options = {}): boolean {
  return card.saveKind === undefined || card.saveKind === 'api';
}

/** Read only descriptors contributed by the declaring package, through the lifecycle's contained port.
 * Missing or invalid descriptors grant no ownership; a parsed card may explicitly own its API label.
 * Cross-plugin label conflicts are refused by the existing merge. O(descriptors); no modules execute.
 */
async function ownsDestination({ plugin, card, readFile }: { plugin: TrustedPluginPackage; card: PluginCredentialCard; readFile: ReadFile }, _options = {}): Promise<boolean> {
  // A provider settings card writes only the provider plugin this agent plugin declares itself the face of.
  if (card.saveKind === 'provider-settings') return card.saveTarget !== undefined && card.saveTarget === await linkedProviderOf({ plugin, readFile });
  const identities = await readOwnedIdentities({ plugin, readFile });
  if (card.saveTarget !== undefined && !identities.has(card.saveTarget)) return false;
  if (isApiCard({ card }) && card.ownedApiLabel === card.label) return true;
  const identity = isApiCard({ card }) ? card.label : card.saveTarget ?? card.providerId;
  return identities.has(identity);
}

/** Bind active trusted contributions once; lookups remain fresh for activation changes.
 * Ownership checks and duplicate refusals cannot change a domain store. O(plugins + cards).
 */
export function createPluginCredentialCardsLoader({ agentPluginLayout, loadMailCards }: { agentPluginLayout: AgentPluginLayout; loadMailCards: LoadPluginCredentialCards }, options: { loadContributions?: LoadPluginContributions; readFile?: ReadFile; onRefusal?: (refusal: string) => void } = {}): LoadPluginCredentialCards {
  const warn = options.onRefusal ?? (message => console.warn(`[plugin-credential-cards] ${message}`));
  let lifecycle: ReturnType<typeof createTovuAgentPluginLifecycle> | undefined;
  // Tool catalogs can be built before a site is bound; only a lookup needs the fixed layout.
  const owner = () => lifecycle ??= createTovuAgentPluginLifecycle({ layout: agentPluginLayout });
  const readFile: ReadFile = options.readFile ?? (({ plugin, filename }) => owner().readTrustedPluginFile(plugin, filename));
  const definition = { ...credentialCardsContribution, load: async ({ plugin, descriptor }: Parameters<typeof credentialCardsContribution.load>[0]) =>
    await ownsDestination({ plugin, card: descriptor, readFile }) ? { ...descriptor, pluginId: plugin.pluginId }
      : `credential card '${descriptor.providerId}' from '${plugin.pluginId}' was refused: destination is not owned by this plugin` };
  return async workspaceId => {
    const mailCards = await loadMailCards(workspaceId);
    try {
      const loadContributions = options.loadContributions ?? owner().loadPluginContributions;
      const result = await loadContributions({ workspaceId, definition }, { requireActive: true, orderByPluginId: true });
      for (const refusal of result.refusals) warn(refusal);
      return mergePluginCredentialCards({ mailCards, manifestCards: result.items }, { onRefusal: warn });
    } catch {
      warn('Optional manifest cards could not be loaded; retaining mail cards and domain defaults.');
      return mailCards;
    }
  };
}

/** The provider plugin this agent plugin declares itself the face of (`identity.ts`), or undefined.
 *  An unreadable manifest grants nothing. */
async function linkedProviderOf({ plugin, readFile }: { plugin: TrustedPluginPackage; readFile: ReadFile }, _options = {}): Promise<string | undefined> {
  try { return readProviderPluginLink({ manifest: JSON.parse(await readFile({ plugin, filename: 'plugin.json' })) }); }
  catch { return undefined; }
}

/** Actual descriptors grant identity ownership; display text alone never does. O(descriptors). */
async function readOwnedIdentities({ plugin, readFile }: { plugin: TrustedPluginPackage; readFile: ReadFile }, _options = {}): Promise<Set<string>> {
  const identities = new Set([plugin.pluginId]);
  const sources = [
    { filename: 'tovu-deploy-targets.json', parse: parseDeployTargetsFile },
    { filename: 'tovu-source-control.json', parse: parseSourceControlProvidersFile },
    { filename: 'tovu-mail-adapters.json', parse: parseMailAdaptersFile },
  ];
  for (const source of sources) {
    try {
      const parsed = source.parse(await readFile({ plugin, filename: source.filename }));
      if (!parsed.ok) continue;
      for (const entry of parsed.descriptors) {
        identities.add(entry.id);
        if ('credentialLabel' in entry) identities.add(entry.credentialLabel);
      }
    } catch { /* Missing or broken descriptors grant no ownership. */ }
  }
  return identities;
}

/** The host is the only cross-family composition point. Bind the existing lifecycle owners;
 * discovery is metadata-only and fresh on each call so disable/uninstall cannot leave stale grants. */
import path from 'node:path';
import { redactSecrets } from '@jini-ai/core';
import { withFileLock } from '@jini-ai/platform/fs/file-lock';
import { createPluginLookup, readPluginIdentity, assertPluginIdentityAvailable, type PluginProvider } from '@jini-ai/core/plugin-directory';
import type { InstalledAgentPlugin } from '@jini-ai/agent-plugins/lifecycle';
import type { PluginActivationRepoPort } from '@jini-ai/plugins/host';
import type { PluginDiscoveryRecord } from '@jini-ai/plugins/host/node';
import type { AgentPluginHostCapability, PluginHostPort } from '#src/contracts/headless/plugin-host';
import { listInstalledPlugins, preferBundledAgentPluginDigests, readBundledAgentPluginDigests } from '#src/features/agent-plugins/lifecycle';
import { readInstalledAgentPluginIdentity } from '#src/features/agent-plugins/identity';
import { agentPluginActivations } from '#src/features/agent-plugins/activation-effects';
import { setAgentPluginEnabled } from '#src/features/agent-plugins/set-enabled';
import { runAgentPluginUninstall, type AgentPluginUninstallToolDeps } from '#src/features/agent-plugins/uninstall-tool';
import { provisionAgentPluginMcpServers, resolveAgentPluginMcpServers } from '#src/features/agent-plugins/federate-mcp';
import type { Clock } from '@jini-ai/core/primitives';
import type { ExternalMcpStoreDeps } from '#src/assistant/index';

export interface TovuPluginHostDeps extends AgentPluginUninstallToolDeps {
  readonly discoverPlugins: () => Promise<readonly PluginDiscoveryRecord[]>;
  readonly pluginActivationRepo: PluginActivationRepoPort;
  readonly clock: Clock;
  readonly externalMcpServerRepo: ExternalMcpStoreDeps['repo'];
  readonly siteAssistantSecretSealer: ExternalMcpStoreDeps['sealer'];
  readonly siteAssistantSecretKeyring: ExternalMcpStoreDeps['keyring'];
  readonly listInstalledAgentPlugins?: typeof listInstalledPlugins;
  readonly setAgentPluginEnabled?: typeof setAgentPluginEnabled;
  readonly assertAgentPluginActivationsWritable?: typeof agentPluginActivations.assertAgentPluginActivationsWritable;
}

/** Bind both plugin families to one workspace. Read manifests through the same installed-package
 * index; the extra manifest read bridges existing compiled lifecycle versions until Jini builds.
 * @throws Unreadable activation (fail closed).
 * Unreadable/invalid or ambiguous manifest metadata is omitted with a warning. Admission retains
 * every valid revision identity, including revisions omitted from lookup, to prevent takeovers.
 * @complexity O(p log p) per lookup, plus existing discovery/activation I/O for p installs.
 */
export function createTovuPluginHost(
  { deps }: { deps: TovuPluginHostDeps },
  optional: {
    readAgentManifest?: (required: { plugin: InstalledAgentPlugin }, optional?: Record<string, never>) => Promise<Readonly<Record<string, unknown>>>;
    resolveEnabled?: (required: { workspaceRoot: string; pluginId: string }, optional?: Record<string, never>) => Promise<boolean>;
    warn?: (message: string) => void;
    resolveMcpServers?: typeof resolveAgentPluginMcpServers;
    provisionMcpServers?: typeof provisionAgentPluginMcpServers;
  } = {},
): PluginHostPort {
  const resolveWorkspaceRoot = () => deps.agentPluginLayout.forWorkspace(deps.workspaceId).root;
  const listInstalled = async () => (deps.listInstalledAgentPlugins ?? listInstalledPlugins)(resolveWorkspaceRoot());
  const warn = optional.warn ?? ((message: string) => console.warn(`[plugins] ${message}`));
  const readAgentIdentity = optional.readAgentManifest
    ? async ({ plugin }: { plugin: InstalledAgentPlugin }) => readPluginIdentity({ manifest: await optional.readAgentManifest!({ plugin }), name: plugin.pluginId, namespace: 'tovu' })
    : readInstalledAgentPluginIdentity;

  const listSiteProviders = async ({ forAdmission }: { forAdmission: boolean }, _options = {}): Promise<PluginProvider[]> => {
    const providers: PluginProvider[] = [];
    for (const record of await deps.discoverPlugins()) {
      if (record.status !== 'valid' || !record.manifest) {
        warn(`Plugin '${record.id}': invalid installed manifest omitted from metadata lookup.`);
        continue;
      }
      let parsed: ReturnType<typeof readPluginIdentity>;
      try { parsed = readPluginIdentity({ manifest: record.manifest as unknown as Readonly<Record<string, unknown>>, name: record.id, namespace: 'tovu' }); }
      catch { warn(`Plugin '${record.id}': installed identity manifest is unreadable or invalid; omitted from metadata lookup.`); continue; }
      const { warnings, ...identity } = parsed;
      warnings.forEach(warn);
      const activation = forAdmission ? null : await deps.pluginActivationRepo.getActivation({ workspaceId: deps.workspaceId, pluginId: record.id });
      providers.push({ ...identity, version: record.version, enabled: activation?.enabled === true, family: 'site-runtime', localId: record.id });
    }
    return providers;
  };

  const resolveAgentProviders = async ({ agentProviders, workspaceRoot }: {
    agentProviders: Map<string, PluginProvider[]>; workspaceRoot: string;
  }, _options = {}): Promise<PluginProvider[]> => {
    const providers: PluginProvider[] = [];
    for (const [pluginId, revisions] of agentProviders) {
      // Multiple digests are revisions of one install, not duplicate provider registrations.
      // Without a recorded winner the existing lifecycle refuses to guess; discovery follows it
      // by omitting this plugin, while unrelated lookup and installation remain available.
      if (revisions.length !== 1) {
        const declaredIds = new Set(revisions.map(provider => provider.id).filter(id => id !== `unknown/${pluginId}`));
        warn(`Plugin '${pluginId}': ${declaredIds.size > 1 ? 'conflicting publisher identities' : 'ambiguous installed revisions'}; omitted from metadata lookup.`);
        continue;
      }
      let enabled: boolean;
      if (optional.resolveEnabled) enabled = await optional.resolveEnabled({ workspaceRoot, pluginId });
      else {
        const activation = await agentPluginActivations.resolveAgentPluginActivation({ workspaceRoot, pluginId });
        enabled = activation.verdict === 'active';
      }
      providers.push({ ...revisions[0]!, enabled });
    }
    return providers;
  };

  const listAgentProviders = async ({ workspaceRoot, forAdmission }: {
    workspaceRoot: string; forAdmission: boolean;
  }, _options = {}): Promise<PluginProvider[]> => {
    const providers: PluginProvider[] = [];
    const agentProviders = new Map<string, PluginProvider[]>();
    // A legacy revision may acquire its first publisher identity at upgrade; old frozen
    // digests can remain present from older installs until successful publication prunes them.
    // Reuse that owner's selection; metadata lookup must not invent a newest-version policy.
    const installed = await listInstalled();
    const preferred = forAdmission ? installed : preferBundledAgentPluginDigests(installed, await readBundledAgentPluginDigests(workspaceRoot));
    const preferredKeys = new Set(preferred.map(plugin => `${plugin.pluginId}:${plugin.archiveDigest}`));
    for (const plugin of installed) {
      let parsed: ReturnType<typeof readPluginIdentity>;
      try { parsed = await readAgentIdentity({ plugin }); }
      catch { warn(`Plugin '${plugin.pluginId}': installed identity manifest is unreadable or invalid; omitted from metadata lookup.`); continue; }
      const { warnings, ...identity } = parsed;
      warnings.forEach(warn);
      const provider: PluginProvider = { ...identity, version: plugin.version ?? null, enabled: false, family: 'agent-plugin', localId: plugin.pluginId };
      if (forAdmission) { providers.push(provider); continue; }
      if (!preferredKeys.has(`${plugin.pluginId}:${plugin.archiveDigest}`)) continue;
      const revisions = agentProviders.get(plugin.pluginId) ?? [];
      revisions.push(provider);
      agentProviders.set(plugin.pluginId, revisions);
    }
    return providers.concat(await resolveAgentProviders({ agentProviders, workspaceRoot }));
  };

  const listProviders = async ({ forAdmission = false }: { forAdmission?: boolean } = {}, _options = {}) => {
    const workspaceRoot = resolveWorkspaceRoot();
    const providers = await listSiteProviders({ forAdmission });
    return providers.concat(await listAgentProviders({ workspaceRoot, forAdmission }));
  };
  const lookup = createPluginLookup({ listPlugins: listProviders }, { warn });

  const agentPlugins: AgentPluginHostCapability = {
    listInstalled,
    assertWritable: async () => (deps.assertAgentPluginActivationsWritable ?? agentPluginActivations.assertAgentPluginActivationsWritable)({ workspaceRoot: resolveWorkspaceRoot() }),
    setEnabled: async (input: Parameters<AgentPluginHostCapability["setEnabled"]>[0]) => (deps.setAgentPluginEnabled ?? setAgentPluginEnabled)({ ...input, agentPluginLayout: deps.agentPluginLayout }),
    /** Provisioning must use the same two owners as the admin toggle. A failed connection never
     * rolls back a successful activation; report fixed diagnostics without credential material. */
    provisionMcp: async ({ pluginId, principalId }: { pluginId: string; principalId: string }) => {
      try {
        const servers = await (optional.resolveMcpServers ?? resolveAgentPluginMcpServers)({ agentPluginLayout: deps.agentPluginLayout, workspaceId: deps.workspaceId, pluginId });
        const result = await (optional.provisionMcpServers ?? provisionAgentPluginMcpServers)({ repo: deps.externalMcpServerRepo, sealer: deps.siteAssistantSecretSealer, keyring: deps.siteAssistantSecretKeyring, clock: deps.clock }, { workspaceId: deps.workspaceId, pluginId, servers, principalId });
        for (const failure of result.failed) {
          warn(redactSecrets({ input: `Plugin '${pluginId}': MCP provisioning for server '${failure.serverKey}' failed — ${failure.reason}` }));
        }
      } catch (error) {
        warn(redactSecrets({ input: `Plugin '${pluginId}': MCP provisioning could not run — ${error instanceof Error ? error.message : String(error)}` }));
      }
    },
    uninstall: async (input: Parameters<AgentPluginHostCapability["uninstall"]>[0]) => runAgentPluginUninstall(deps, input.surfaces, input.ctx, input.pluginId, input.executionOptions),
  };
  return {
    ...lookup,
    withInstallIdentity: ({ candidate, run }) => withFileLock({
      lockPath: path.join(deps.agentPluginLayout.root, '.publisher-identity.lock'),
      run: async () => { assertPluginIdentityAvailable({ candidate, installed: await listProviders({ forAdmission: true }) }); return run(); },
    }, { createParent: true }),
    getHostCapability: ({ capability }) => capability === 'agent-plugin-lifecycle' ? agentPlugins : undefined };
}

