/** Executable metadata for one compiled-in plugin. Discovery consumes only `manifest`; the enable
 * callback consumes the import seam after integrity/sdkRange checks. Site-artifact sources can use
 * the same shape once their install-dir resolver is composed here. */
export interface PluginRuntimeSource extends BuiltInPluginSource {
  readonly source: "built-in";
  readonly entryPath: string;
  readonly importModule: (entryPath: string) => Promise<unknown>;
  /** The built-in's own source folder, shown read-only by the admin Plugins screen's
   * package-files viewer (`routes/plugins/files.ts`). Omitted ⇒ that viewer lists no files. */
  readonly sourceDir?: string;
}

/** What `loadPlugin()` and `attachLoadedPlugin()` need for one enable attempt, resolved by
 * {@link resolveLoadTarget}. `importModule` is omitted (not `undefined`-valued) for a site target
 * so the host binding supplies the contained snapshot importer; only a built-in target carries
 * an explicit scalar override (its test/production seam, unchanged by this type). */
interface PluginLoadTarget {
  readonly manifest: PluginManifest;
  readonly entryPath: string;
  readonly attachmentSource: AttachmentSource;
  readonly importModule?: (entryPath: string) => Promise<unknown>;
}

/**
 * Resolves ONE enable attempt's load target (Milestone 1b, 2026-08-20): a compiled-in built-in
 * plugin uses the composition root's own static `PluginRuntimeSource` — entirely unchanged from
 * before this slice, so every existing built-in test (including ones that inject a synthetic
 * `entryPath`/`importModule`, e.g. the auto-quarantine fixture) keeps behaving identically. A
 * site-installed plugin has no static source to find, so its target is derived instead from the
 * SAME discovery record `onPluginEnabled` already fetched this call — reusing `record.manifest`
 * (see that field's own doc for why this, not a second file read, is the TOCTOU-safe choice) and
 * `siteEntryPath()`'s REQ-02 layout convention.
 *
 * Deliberately does not itself touch integrity/`sdkRange`/`import()` — those stay exactly where
 * CIC U-001 requires them, inside `loadPlugin()`'s own fixed step order. This function only decides
 * WHICH manifest/entryPath/import-hook `loadPlugin()` is handed; it never calls `import()` itself
 * and never lets a caller reach one without going through `loadPlugin()`'s ordering first.
 *
 * @returns `null` when the id is neither a known built-in nor a valid, installDir-reachable site
 * record — the caller's existing fail-closed `PLUGIN_EXPORT_INVALID` behavior is unchanged.
 * @complexity O(sources.length) — one linear scan of the static built-in list; no I/O of its own.
 */
function resolveLoadTarget(params: {
  pluginId: string;
  sources: readonly PluginRuntimeSource[];
  record: PluginDiscoveryRecord;
  installDir: string | undefined;
}): PluginLoadTarget | null {
  const { pluginId, sources, record, installDir } = params;

  const builtIn = sources.find((candidate) => candidate.manifest.id === pluginId);
  if (builtIn) {
    return {
      manifest: builtIn.manifest,
      entryPath: builtIn.entryPath,
      attachmentSource: builtIn.source,
      importModule: builtIn.importModule,
    };
  }

  if (record.source === "site" && installDir !== undefined && record.manifest !== undefined) {
    return {
      manifest: record.manifest,
      entryPath: siteEntryPath({ installDir, id: record.id, version: record.version }),
      attachmentSource: record.source,
    };
  }

  return null;
}

/**
 * A plugin id safe to use as a single filesystem path segment (Milestone 2, 2026-08-20) — the same
 * character class `src/features/agent-plugins/layout.ts`'s `SAFE_PLUGIN_ID_PATTERN` uses,
 * independently declared here rather than imported: that module is a DIFFERENT, unrelated plugin
 * system (agent-plugins.org format; see this file's own `PluginRuntimeSource` doc history and
 * Milestone 1's handoff for why the two are never wired together), and importing from it would
 * create exactly that coupling for a one-line regex. `.` and `-` are allowed mid-string (matching
 * real semver-adjacent plugin ids like `word-count`) but the pattern has no `/`, no `..`, and no
 * leading/trailing separator — it cannot itself produce a path-traversal segment.
 */
const SAFE_PLUGIN_ID_SEGMENT = /^[a-z0-9]+(?:[-.][a-z0-9]+)*$/;

/** Thrown when `pluginId` is not safe to use as a filesystem path segment
 * under `installDir` — either it fails {@link SAFE_PLUGIN_ID_SEGMENT}'s allowlist, or (defense in
 * depth, in case some future caller's id validation elsewhere ever drifts) the resolved absolute
 * path would land outside `installDir` after resolution. Deliberately fails closed on EITHER
 * check independently, not just the one presumed sufficient. */
export class PluginUninstallPathError extends Error {
  constructor(pluginId: string) {
    super(`plugin id '${pluginId}' is not a safe filesystem path segment — refusing to remove it`);
    this.name = "PluginUninstallPathError";
  }
}

/** A site plugin's version folder name as discovery read it from disk: one segment, no
 * separator, no leading dot. Checked together with {@link SAFE_PLUGIN_ID_SEGMENT} before either is
 * joined into a path. */
const SAFE_VERSION_SEGMENT = /^[0-9A-Za-z][0-9A-Za-z.+-]*$/;

/**
 * Where one discovered plugin's files live, for the package-files viewer: a built-in's own
 * `sourceDir`, or a site plugin's `<installDir>/<id>/<version>/` (REQ-02's layout, the same one
 * `siteEntryPath()` joins). The directory is its own container for a built-in; `installDir` is the
 * container for a site plugin, so `readPluginPackageFiles()`'s realpath check keeps a symlinked id
 * or version folder from reaching outside it.
 *
 * @returns `null` when there is no directory to show: a built-in without `sourceDir`, or a site
 *   record while `installDir` is unset.
 * @throws {PluginPackagePathError} a site record's id or version is not one safe path segment — a
 *   site record's id comes from its own manifest, so it is untrusted text until checked here.
 * @complexity O(sources.length).
 */
function resolvePackageLocation(params: {
  record: PluginDiscoveryRecord;
  sources: readonly PluginRuntimeSource[];
  installDir: string | undefined;
}): { rootDir: string; containerDir: string } | null {
  const { record, sources, installDir } = params;
  if (record.source === "built-in") {
    const sourceDir = sources.find((candidate) => candidate.manifest.id === record.id)?.sourceDir;
    return sourceDir === undefined ? null : { rootDir: sourceDir, containerDir: sourceDir };
  }
  if (installDir === undefined) return null;
  if (!SAFE_PLUGIN_ID_SEGMENT.test(record.id) || !SAFE_VERSION_SEGMENT.test(record.version)) {
    throw new PluginPackagePathError(`plugin '${record.id}' version '${record.version}' is not a safe path segment`);
  }
  return { rootDir: path.join(installDir, record.id, record.version), containerDir: installDir };
}

export interface ComposePluginRuntimeRequired {
  readonly productTracker?: () => Pick<Tracker, 'capture'>;
  /** Review pins and first-boot defaults supplied only by the product composition roots. */
  readonly browserProviderApprovals?: readonly BundledBrowserProviderApproval[];
  readonly bundledEnabledIds?: readonly string[];
  readonly pluginSourcePolicy?: PluginSourcePolicyPort;
  readonly getPluginHost?: () => import("#src/contracts/headless/plugin-host").PluginHostPort | undefined;
  readonly workspaceId: string;
  readonly clock: ClockPort;
  readonly activationRepo: PluginActivationRepoPort;
  readonly sources: readonly PluginRuntimeSource[];
  /** Consecutive hook failures before quarantine. Omitted uses the registry default. */
  readonly failureThreshold?: number;
  /** Runs one Tier-2 (`tier: "tier-2"`) plugin call in isolation. Omitted ⇒ a fresh Node worker
   * per call (`server/runtime/plugin-tier2/run-in-worker.ts`); tests inject a shorter timeout. */
  readonly tier2CallRunner?: Tier2CallRunner;
  /** Site-installed plugin scan root, forwarded verbatim to `discoverPlugins({ installDir })`
   * (REQ-02). Omitted ⇒ legacy mode: built-ins only, identical to today's behavior (discovery.ts's
   * own EC-09/AC-16 contract) — this parameter only ADDS reachability for site-installed plugins,
   * it never changes what a caller who omits it observes. */
  readonly installDir?: string;
  /** Names core itself holds (routes, tools, permissions, tables, … — `claim-conflicts.ts` claims,
   * prefix claims allowed). A plugin claiming one is refused at enable and quarantined at boot.
   * Omitted ⇒ no core claims: plugin-vs-plugin conflicts are still detected. The real roots pass
   * `TOVU_CORE_EXTENSION_CLAIMS` (`core-extension-claims.ts`). */
  readonly coreClaims?: readonly ExtensionClaim[];
  /** Where plugins' declared content types are created (AW-7 Tier 1) — the roots bind
   * `createDeclaredContentTypePorts` over their content-type repo. Omitted ⇒ a plugin that declares
   * content types is refused at enable (see `declarative-enable.ts`). */
  readonly declaredContentTypes?: DeclaredContentTypePorts;
}

export interface PluginRuntimeBindings {
  /** Call after provider teardown and stopped hook users; drains copies and releases owned graphs. */
  readonly dispose: (required: Record<string, never>, optional?: Record<string, never>) => Promise<void>;
  /** Successfully attached, admitted providers only; disable/quarantine retires their assets. */
  readonly browserProviders: (input: Record<string, never>, options?: Record<string, never>) => { generation: number; providers: readonly AdmittedBrowserProvider[] };
  readonly pluginSource?: PluginSourcePort;
  readonly pluginSourcePolicy: PluginSourcePolicyPort;
  /** Actual loaded snapshot revision, used by the existing cross-process activation poll. */
  readonly pluginLoadedVersion: (required: { id: string }, optional?: Record<string, never>) => string | undefined;
  readonly pluginInstaller?: PluginInstallerPort;
  readonly hookRegistry: HookRegistry;
  readonly pluginContributions: PluginContributionRegistry;
  /** Provider factories of admitted provider plugins only (`createPluginProviderHost` reads this).
   * Separate from `pluginContributions`, whose route/tool/widget snapshots carry no providers. */
  readonly providerContributions: PluginContributionRegistry;
  /**
   * Boot-only: loads the given provider plugins when each is installed and enabled here, admitting
   * their factories into `providerContributions`. Provider plugins are loaded nowhere else (boot
   * re-attach and enable skip them), so a running provider is never replaced mid-process; enabling
   * one takes effect at the next boot, disabling or quarantining one retires it immediately.
   * @returns The ids actually loaded. Per-plugin failures are logged and skipped, never thrown.
   */
  readonly loadProviderPlugins: (required: { pluginIds: readonly string[] }, optional?: { timeoutMs?: number }) => Promise<readonly string[]>;
  /** Installed + enabled plugins here that declare providers, with their declarations (manifest only). */
  readonly listProviderPlugins: (required: Record<string, never>, optional?: Record<string, never>) => Promise<readonly { pluginId: string; providers: NonNullable<NonNullable<PluginManifest["contributes"]>["providers"]> }[]>;
  readonly discoverPlugins: () => Promise<readonly PluginDiscoveryRecord[]>;
  /** Discovery with the enabled activations' version pins: the versions boot runs (a pin never falls forward). */
  readonly discoverActivePlugins: () => Promise<readonly PluginDiscoveryRecord[]>;
  readonly onPluginEnabled: (pluginId: string) => Promise<void>;
  readonly onPluginDisabled: (pluginId: string) => void;
  readonly locatePluginPackageDirs: (pluginId: string) => Promise<{
    liveParent: string;
    liveNames: readonly string[];
    parkedDir: string;
  }>;
  /** Lists one discovered plugin's own files, read-only and bounded, for the admin Plugins
   * screen's package-files viewer — see {@link resolvePackageLocation} and
   * `Jini/packages/plugins/src/host/node/package-files.ts`. Rejects with `PluginPackagePathError` for an
   * unsafe id/version or a directory that resolves outside its container. */
  readonly readPluginPackageFiles: (record: PluginDiscoveryRecord) => Promise<PluginPackageFiles>;
  readonly beforeSaveHook: BeforeSaveHookPort;
  /** Admin preview (AW-7): one attached plugin's beforeSave patch for a draft, nothing saved or
   * counted toward quarantine. `null` ⇒ not attached. See `HookRegistry.previewBeforeSave`. */
  readonly previewPluginBeforeSave: PluginBeforeSavePreview;
  /**
   * P0a fix (2026-09-23): re-runs `onPluginEnabled` for every plugin `activationRepo` durably
   * marks `enabled` for THIS composition's `workspaceId`. Before this existed, nothing replayed
   * that durable state into a freshly-constructed (empty) `hookRegistry` — a plugin enabled in a
   * prior process looked enabled in the admin UI and in `listAll()`, but its filter/action/
   * contribution never fired again until an operator disabled and re-enabled it. Best-effort: one
   * plugin failing to re-attach (e.g. its package was removed from disk) is logged and skipped, not
   * thrown, so it can never block the rest of boot (mirrors `seedBundledAgentPlugins`'s own
   * per-package isolation).
   */
  readonly attachEnabledPluginsAtBoot: () => Promise<void>;
  /** Every discovered plugin that has a name conflict right now — an enabled loser, or a plugin that
   * is off and WOULD be refused if turned on — for the admin screen and `plugins_list`. See
   * `Jini/packages/plugins/src/host/plugin-claims.ts`'s `resolvePluginConflicts`. */
  readonly listPluginConflicts: () => Promise<ReadonlyMap<string, readonly PluginConflict[]>>;
}

/** True when a manifest declares provider factories (`contributes.providers`). */
function declaresProviders({ manifest }: { manifest: PluginManifest | undefined }): boolean {
  return (manifest?.contributes?.providers?.length ?? 0) > 0;
}

/**
 * Server-layer composition for SPEC-005's runtime half. The application roots own the concrete
 * activation repo/source list; this helper builds the per-load core handles, delegates module
 * ownership/setup to `loadPlugin()`, and performs the one shared attach operation only after setup
 * has completed successfully.
 */
export function composePluginRuntime(required: ComposePluginRuntimeRequired, _optional: Record<string, never> = {}): PluginRuntimeBindings {
  const { activationRepo, clock, sources, installDir } = required;
  const quarantineDeps = { clock, repo: activationRepo, onQuarantined: ({ pluginId }: { pluginId: string; workspaceId: string }) =>
    required.productTracker?.().capture({ name: "plugin_quarantined", userId: "system" }, { properties: { pluginId, pluginKind: "cms", reasonClass: "lifecycle" } }) };
  // The install directory owns versions; its sibling runtime directory owns executable graphs.
  const snapshots = installDir === undefined ? undefined : createPluginModuleSnapshotLifecycle({ runtimeRoot: path.resolve(installDir) + "-runtime" });
  const pendingAttachments = new Set<Promise<void>>();
  let closing = false;
  const pluginSourcePolicy = required.pluginSourcePolicy ?? createSitePluginPolicy({ env: process.env });
  const loadedVersions = new Map<string, string>();
  const browserProviders = new Map<string, readonly AdmittedBrowserProvider[]>();
  let browserGeneration = 0;
  const pluginContributions = createPluginContributionRegistry({});
  const providerContributions = createPluginContributionRegistry({});
  // Only boot's configured selection may admit provider factories (`loadProviderPlugins`).
  const selectedProviders = new Set<string>();
  const loadEpochs = new Map<string, number>();
  const tier2CallRunner = required.tier2CallRunner ?? createTier2WorkerRunner({});
  const hookRegistry = createHookRegistry({ pluginSdkBinding: pluginHostBinding.pluginSdkBinding }, {
    ...(required.failureThreshold === undefined ? {} : { failureThreshold: required.failureThreshold }),
    onQuarantine: async (input) => {
      onPluginDisabled(input.pluginId);
      await quarantinePlugin({ deps: quarantineDeps, input });
    },
  });
  // Reachability fix (previously always omitted `installDir`, so a plugin placed on disk was
  // never scanned no matter how the composition root itself was configured — see this function's
  // required-params doc).
  const discoverPlugins = () =>
    discoverPluginRuntimePlugins({ ...pluginHostBinding, builtIns: sources, ...(installDir === undefined ? {} : { installDir }) });

  /** Retained versions make the activation row's existing active pointer meaningful at boot
   * and reload. A newly installed version is not running until controlled reload advances it. */
  async function discoverActivePlugins(): Promise<readonly PluginDiscoveryRecord[]> {
    const rows = await activationRepo.listAll();
    const versions = new Map(rows.filter(row => row.workspaceId === required.workspaceId && row.enabled).map(row => [row.pluginId, row.version]));
    return discoverPluginRuntimePlugins({ ...pluginHostBinding, builtIns: sources, ...(installDir === undefined ? {} : { installDir }) }, { versions });
  }

  const coreClaims = required.coreClaims ?? [];

  async function listPluginConflicts(
    discovery?: readonly PluginDiscoveryRecord[],
    optional: { candidateId?: string } = {},
  ): Promise<ReadonlyMap<string, readonly PluginConflict[]>> {
    const [records, activations] = await Promise.all([discovery ?? discoverPlugins(), activationRepo.listAll()]);
    return resolvePluginConflicts({ ...pluginHostBinding, workspaceId: required.workspaceId, discovery: records, activations, coreClaims }, optional);
  }

  /** Install preview (2026-10-04): what the staged package would clash with if turned on in THIS
   * workspace now. A synthetic valid record stands in for it and REPLACES an installed version of the
   * same id, so an upgrade is judged by its new manifest only. */
  async function installPreviewConflicts(required: { manifest: PluginManifest }): Promise<readonly PluginConflict[]> {
    const { manifest } = required;
    const staged: PluginDiscoveryRecord = { id: manifest.id, name: manifest.name, version: manifest.version, source: "site", tier: manifest.tier, status: "valid", errors: [], manifest };
    const discovery = [...(await discoverPlugins()).filter((record) => record.id !== manifest.id), staged];
    return (await listPluginConflicts(discovery, { candidateId: manifest.id })).get(manifest.id) ?? [];
  }

  /** Enable-time conflict gate (2026-10-04): runs before `loadPlugin()`, so a plugin that would
   * take a name core or an enabled plugin holds never has its code imported. The candidate is
   * ordered after every enabled plugin — it is the newer one by definition. */
  async function assertNoConflicts(pluginId: string, discovery: readonly PluginDiscoveryRecord[]): Promise<void> {
    const conflicts = (await listPluginConflicts(discovery, { candidateId: pluginId })).get(pluginId);
    if (conflicts) throw new PluginConflictError({ pluginId, conflicts });
  }

  async function onPluginEnabled(pluginId: string): Promise<void> {
    // A package replacement and an enable cannot race: save-before-callback activation is
    // compensated if install owns the directory lock, while installs refuse an enabled row.
    if (installDir !== undefined) await assertPluginInstallIdle({ installDir });
    const discovery = await discoverActivePlugins();
    const record = discovery.find((candidate) => candidate.id === pluginId);
    if (!record) {
      throw new PluginLoadError(pluginId, "PLUGIN_EXPORT_INVALID");
    }
    await assertNoConflicts(pluginId, discovery);
    // Provider plugins initialize once, at boot, before application work (`loadProviderPlugins`).
    if (declaresProviders({ manifest: record.manifest })) return;
    // No manifest ⇒ an invalid record: `attachPlugin`'s own fail-closed path reports it.
    if (!record.manifest) return attachPlugin(pluginId, record);
    // Declared contributions (AW-7 Tier 1) are applied only now, after the conflict gate; a tier-1
    // plugin's `loadCode` is never called.
    await enableDeclaredPlugin(
      { ...pluginHostBinding, pluginId, workspaceId: required.workspaceId, manifest: record.manifest, loadCode: () => attachPlugin(pluginId, record), unloadCode: () => onPluginDisabled(pluginId) },
      required.declaredContentTypes ? { contentTypes: required.declaredContentTypes } : {},
    );
    loadedVersions.set(pluginId, record.version);
  }

  /** Load + attach one already-cleared plugin — `onPluginEnabled`'s body after its gates, shared
   * with boot, which clears every enabled plugin in ONE pass instead (see
   * `attachEnabledPluginsAtBoot`: per-plugin "candidate last" ordering would refuse the older
   * winner of a boot-time pair as well as the newer one). */
  function attachPlugin(pluginId: string, record: PluginDiscoveryRecord): Promise<void> {
    if (closing) return Promise.reject(new PluginSnapshotLifecycleError({ code: "SNAPSHOTS_CLOSED" }));
    const attachment = performPluginAttachment(pluginId, record);
    pendingAttachments.add(attachment);
    void attachment.then(() => pendingAttachments.delete(attachment), () => pendingAttachments.delete(attachment));
    return attachment;
  }

  /** Keep import and setup in the same shutdown drain: setup may make late graph imports too. */
  async function performPluginAttachment(pluginId: string, record: PluginDiscoveryRecord): Promise<void> {
    const epoch = (loadEpochs.get(pluginId) ?? 0) + 1;
    loadEpochs.set(pluginId, epoch);
    const target = resolveLoadTarget({ pluginId, sources, record, installDir });
    if (!target) {
      throw new PluginLoadError(pluginId, "PLUGIN_EXPORT_INVALID");
    }
    const { manifest, entryPath, attachmentSource } = target;
    // The SDK backing (content.read/extend bound to the running filter, single declared beforeSave
    // filter) is shared with the Tier-2 worker — see `invocation-core-deps.ts`.
    const invocation = pluginHostBinding.createInvocationCoreDeps({ pluginId, declaredHooks: manifest.hooks });
    const capture = createPluginContributionCapture({ manifest });
    let scopedSdk: PluginSdk | undefined;
    const coreDeps = { ...invocation.coreDeps, contributions: capture };

    // CIC U-001: Jini invokes this required port only AFTER integrity/sdkRange checks. A site
    // target takes the contained immutable snapshot; built-in seams retain their original path.
    const moduleImporter = resolveRuntimeImporter({ target, record });
    const result = await loadPlugin(
      { ...pluginHostBinding, record, manifest, entryPath, coreDeps, importModule: moduleImporter,
        browserProviderApprovals: required.browserProviderApprovals ?? [],
        providerContributions: { registry: providerContributions, isSelected: ({ pluginId: id }) => selectedProviders.has(id) },
        pluginSdkBinding: { ...pluginHostBinding.pluginSdkBinding,
          buildSdk: ({ sdk }) => {
            const host = required.getPluginHost?.();
            scopedSdk = { ...pluginHostBinding.pluginSdkBinding.buildSdk({ sdk }),
              ...(host ? { plugins: createPluginLookupFacade({ lookup: host }) } : {}),
            };
            return scopedSdk;
          },
        },
      },
      {},
    );
    if (!result.loaded) {
      throw new PluginLoadError(pluginId, result.reason);
    }

    // A disable or a newer load during import/setup must not resurrect the retired generation.
    if (loadEpochs.get(pluginId) !== epoch || !scopedSdk) throw new PluginLoadError(pluginId, 'PLUGIN_SETUP_FAILED');
    const contributions = capture.seal({ sdk: scopedSdk });
    const filter = invocation.capturedFilter();
    if (manifest.hooks.includes(HOOK_CONTENT_ENTRY_BEFORE_SAVE) && filter === null) {
      throw new PluginLoadError(pluginId, "PLUGIN_HOOK_NOT_ATTACHED");
    }
    publishPluginAttachment({ pluginId, manifest, attachmentSource, filter, contributions,
      providers: result.browserProviders ?? [], version: record.version });
  }

  function resolveRuntimeImporter({ target, record }: { target: PluginLoadTarget; record: PluginDiscoveryRecord }, _options = {}) {
    // Tier 2 (ADR-024 §3/§4): the plugin's code must never be imported into this process. Its
    // import seam probes it in a fresh worker and hands `loadPlugin()` a proxy whose filter is an
    // RPC; supplied as `loadPlugin()`'s required `importModule` port, so integrity + sdkRange
    // still run first (CIC U-001). Only a built-in reaches here as tier-2: discovery marks a site
    // tier-2 package invalid (the worker is no sandbox yet). Were site tier-2 ever allowed, its worker
    // would need the seam's `resolveWorkerEntry` pointed at the integrity-checked module snapshot,
    // since an injected worker seam bypasses the host's default snapshot importer.
    return target.manifest.tier === "tier-2"
      ? createTier2ImportSeam({ ...pluginHostBinding, manifest: target.manifest, runCall: tier2CallRunner })
      : createPluginModuleImporter({ manifest: target.manifest, source: record.source }, {
          ...(target.importModule === undefined ? {} : { importModule: target.importModule }),
          ...(snapshots === undefined ? {} : { snapshots }),
        });
  }

  function publishPluginAttachment({ pluginId, manifest, attachmentSource, filter, contributions, providers, version }: {
    pluginId: string; manifest: PluginManifest; attachmentSource: AttachmentSource;
    filter: Parameters<typeof attachLoadedPlugin>[0]["filter"] | null;
    contributions: ReturnType<ReturnType<typeof createPluginContributionCapture>["seal"]>;
    providers: readonly AdmittedBrowserProvider[]; version: string;
  }, _options = {}): void {
    if (filter === null) {
      pluginContributions.replace({ contributions });
      retainBrowserProviders({ pluginId, providers });
      hookRegistry.detach({ pluginId });
      loadedVersions.set(pluginId, version);
      return;
    }

    try {
      attachLoadedPlugin({
        pluginId,
        source: attachmentSource,
        hookRegistry,
        filter,
        declaredFields: manifest.fields,
      });
      pluginContributions.replace({ contributions });
      retainBrowserProviders({ pluginId, providers });
      loadedVersions.set(pluginId, version);
    } catch (error) {
      hookRegistry.detach({ pluginId });
      throw new PluginLoadError(pluginId, "PLUGIN_HOOK_ATTACH_FAILED", { cause: error });
    }
  }

  /** Publish admission only after successful attachment; no partial setup can leak assets.
   * @complexity O(1) map replacement; Jini already owns the immutable asset bytes.
   */
  function retainBrowserProviders({ pluginId, providers }: { pluginId: string; providers: readonly AdmittedBrowserProvider[] }): void {
    if (providers.length === 0 && !browserProviders.has(pluginId)) return;
    browserProviders.set(pluginId, providers);
    browserGeneration++;
  }

  function onPluginDisabled(pluginId: string): void {
    if (browserProviders.delete(pluginId)) browserGeneration++;
    loadEpochs.set(pluginId, (loadEpochs.get(pluginId) ?? 0) + 1);
    pluginContributions.detach({ pluginId });
    // Retires the provider generation: the provider host disposes its initialized resources.
    selectedProviders.delete(pluginId);
    providerContributions.detach({ pluginId });
    hookRegistry.detach({ pluginId });
    loadedVersions.delete(pluginId);
  }

  /** Boot-time conflict pass (2026-10-04): the newer plugin of every conflicting pair is turned off
   * through the same durable quarantine record hook failures use, with the clash as its reason, so
   * it shows on the admin row and stays off on the next boot instead of racing the older one. */
  async function quarantineConflictingAtBoot(
    conflicts: ReadonlyMap<string, readonly PluginConflict[]>,
    enabledIds: ReadonlySet<string>,
  ): Promise<ReadonlySet<string>> {
    const quarantined = new Set<string>();
    for (const [pluginId, pluginConflicts] of conflicts) {
      if (!enabledIds.has(pluginId)) continue;
      const reason = describeBootConflictQuarantine({ conflicts: pluginConflicts });
      await quarantinePlugin({ deps: quarantineDeps, input: { pluginId, workspaceId: required.workspaceId, consecutiveFailures: 0, reason } });
      onPluginDisabled(pluginId);
      // eslint-disable-next-line no-console
      console.warn(`[plugin-runtime] '${pluginId}' quarantined at boot: ${reason}`);
      quarantined.add(pluginId);
    }
    return quarantined;
  }

  async function initializeBootDefaults(_required: Record<string, never>, _options = {}) {
    // Serialize first-boot defaults with boot attachment. Existing disabled/quarantined rows win.
    const initialized = await initializeBundledPlugins({
      deps: { clock, repo: activationRepo, discovery: required.bundledEnabledIds?.length ? await discoverPlugins().catch((error: unknown) => {
        console.warn("[plugin-runtime] bundled discovery failed; chart providers remain unavailable", error);
        return [];
      }) : [], onEnabled: onPluginEnabled, onDisabled: onPluginDisabled },
      input: { workspaceId: required.workspaceId, pluginIds: required.bundledEnabledIds ?? [] },
    });
    for (const failure of initialized.failed) console.warn(`[plugin-runtime] bundled initialization failed for '${failure.pluginId}'`, failure.error);
    return initialized;
  }

  async function attachEnabledPluginsAtBoot(): Promise<void> {
    await snapshots?.ready;
    const initialized = await initializeBootDefaults({}, {});
    const records = await activationRepo.listAll();
    const enabledHere = records.filter(
      (record) => record.workspaceId === required.workspaceId && record.enabled
    );
    if (enabledHere.length === 0) return;
    let discovery: readonly PluginDiscoveryRecord[];
    let quarantined: ReadonlySet<string>;
    try {
      discovery = await discoverActivePlugins();
      quarantined = await quarantineConflictingAtBoot(
        await listPluginConflicts(discovery),
        new Set(enabledHere.map((record) => record.pluginId)),
      );
    } catch (error) {
      // Fail closed: without a finished conflict pass there is no telling which of two clashing
      // plugins should run, so none is attached this boot (each would previously have failed its
      // own discovery read here anyway). Logged, not thrown — same isolation as a per-plugin failure.
      // eslint-disable-next-line no-console
      console.warn(`[plugin-runtime] boot conflict check failed, no plugin attached: ${error instanceof Error ? error.message : String(error)}`);
      for (const record of enabledHere) onPluginDisabled(record.pluginId);
      return;
    }
    for (const record of enabledHere) {
      // The initializer already attached it.
      if (quarantined.has(record.pluginId) || initialized.enabled.includes(record.pluginId)) continue;
      await reattachBootPlugin({ pluginId: record.pluginId, discovery });
    }
  }

  async function reattachBootPlugin({ pluginId, discovery }: { pluginId: string; discovery: readonly PluginDiscoveryRecord[] }, _options = {}): Promise<void> {
    try {
      if (installDir !== undefined) await assertPluginInstallIdle({ installDir });
      const discovered = discovery.find((candidate) => candidate.id === pluginId);
      if (!discovered) throw new PluginLoadError(pluginId, "PLUGIN_EXPORT_INVALID");
      // A tier-1 plugin has no code to re-attach; its declared types were stored at enable.
      // Provider plugins were already loaded by `loadProviderPlugins`, ahead of application work.
      if (discovered.manifest?.tier === "tier-1" || declaresProviders({ manifest: discovered.manifest })) return;
      await attachPlugin(pluginId, discovered);
    } catch (error) {
      // eslint-disable-next-line no-console
      console.warn(
        `[plugin-runtime] boot re-attach failed for '${pluginId}': ${
          error instanceof Error ? error.message : String(error)
        }`
      );
    }
  }

  /** Import + setup of one selected provider plugin, bounded: boot never waits on a stalled plugin. On the
   *  deadline the caller revokes the selection (`onPluginDisabled`), so a late setup cannot publish. */
  async function attachProviderWithin({ record, timeoutMs }: { record: PluginDiscoveryRecord; timeoutMs: number }): Promise<void> {
    let timer: ReturnType<typeof setTimeout> | undefined;
    const deadline = new Promise<never>((_, reject) => {
      timer = setTimeout(() => reject(new Error(`provider plugin load timed out after ${timeoutMs} ms`)), timeoutMs);
    });
    const attached = attachPlugin(record.id, record);
    // Observed even after the deadline wins, so a late failure is never an unhandled rejection.
    attached.catch(() => {});
    try { await Promise.race([attached, deadline]); } finally { clearTimeout(timer); }
  }

  async function listProviderPlugins(_required: Record<string, never>, _options = {}) {
    const enabled = new Set((await activationRepo.listAll())
      .filter((row) => row.workspaceId === required.workspaceId && row.enabled).map((row) => row.pluginId));
    return (await discoverActivePlugins())
      .filter((record) => enabled.has(record.id) && declaresProviders({ manifest: record.manifest }))
      .map((record) => ({ pluginId: record.id, providers: record.manifest!.contributes!.providers! }));
  }

  async function loadProviderPlugins({ pluginIds }: { pluginIds: readonly string[] }, options: { timeoutMs?: number } = {}): Promise<readonly string[]> {
    const wanted = new Set(pluginIds);
    if (wanted.size === 0) return [];
    const enabled = new Set((await activationRepo.listAll())
      .filter((row) => row.workspaceId === required.workspaceId && row.enabled).map((row) => row.pluginId));
    const loaded: string[] = [];
    for (const record of await discoverActivePlugins()) {
      if (!wanted.has(record.id) || !enabled.has(record.id) || !declaresProviders({ manifest: record.manifest })) continue;
      selectedProviders.add(record.id);
      try {
        await attachProviderWithin({ record, timeoutMs: options.timeoutMs ?? 10_000 });
        loaded.push(record.id);
      } catch (error) {
        onPluginDisabled(record.id);
        console.warn(`[plugin-runtime] provider plugin '${record.id}' failed to load; its contract stays on the noop: ${error instanceof Error ? error.message : String(error)}`);
      }
    }
    return loaded;
  }

  async function locatePluginPackageDirs(pluginId: string): Promise<{
    liveParent: string;
    liveNames: readonly string[];
    parkedDir: string;
  }> {
    if (installDir === undefined) {
      throw new Error(`locatePluginPackageDirs: no installDir configured for this composition root — cannot remove '${pluginId}'`);
    }
    if (!SAFE_PLUGIN_ID_SEGMENT.test(pluginId)) {
      throw new PluginUninstallPathError(pluginId);
    }
    const installRoot = path.resolve(installDir);
    const liveDir = path.resolve(installRoot, pluginId);
    if (liveDir === installRoot || !liveDir.startsWith(installRoot + path.sep)) {
      throw new PluginUninstallPathError(pluginId);
    }
    const parkedRoot = path.resolve(path.dirname(installRoot), `${path.basename(installRoot)}-trash`);
    const parkedDir = path.resolve(parkedRoot, pluginId);
    if (parkedDir === parkedRoot || !parkedDir.startsWith(parkedRoot + path.sep)) {
      throw new PluginUninstallPathError(pluginId);
    }
    const liveNames = await lstat(liveDir).then(
      () => [pluginId],
      (error: unknown) => {
        if (typeof error === "object" && error !== null && "code" in error && error.code === "ENOENT") return [];
        throw error;
      },
    );
    return { liveParent: installRoot, liveNames, parkedDir };
  }

  async function readPluginPackageFiles(record: PluginDiscoveryRecord): Promise<PluginPackageFiles> {
    const location = resolvePackageLocation({ record, sources, installDir });
    if (location === null) return { files: [], truncated: false };
    return readPluginPackageDirectory({ input: location });
  }

  const pluginInstaller: PluginInstallerPort | undefined = installDir === undefined ? undefined : {
      preview: (input, options = {}) => previewSitePluginInstall({ ...input, deps: { ...pluginHostBinding, ...options, installDir, builtInIds: sources.map((source) => source.manifest.id), builtInManifests: sources.map((source) => source.manifest), repo: activationRepo, conflicts: installPreviewConflicts } }),
      install: async (input, options = {}) => {
        const deps = { ...pluginHostBinding, ...options, installDir, builtInIds: sources.map((source) => source.manifest.id), builtInManifests: sources.map((source) => source.manifest), repo: activationRepo, conflicts: installPreviewConflicts };
        const preview = await previewSitePluginInstall({ ...input, deps });
        // Admission uses this manifest's identity; publication must retain those exact bytes.
        const run = () => installSitePlugin({ ...input, expectedDigest: input.expectedDigest ?? preview.digest, deps });
        const host = required.getPluginHost?.();
        if (!host) return run();
        return host.withInstallIdentity({ candidate: { id: preview.publisherId ?? `unknown/${preview.id}`, localId: preview.id, family: "site-runtime" }, run });
      },
  };
  async function reloadActivation({ row, id, discovery }: {
    row: Awaited<ReturnType<PluginActivationRepoPort["listAll"]>>[number]; id: string; discovery: readonly PluginDiscoveryRecord[];
  }, _options = {}): Promise<void> {
    const here = row.workspaceId === required.workspaceId;
    try {
      await setPluginEnabled({ deps: { clock, repo: activationRepo, discovery,
        onEnabled: here ? onPluginEnabled : async () => {}, onDisabled: here ? onPluginDisabled : () => {} },
        input: { workspaceId: row.workspaceId, pluginId: id, enabled: true } });
    } catch (error) {
      if (here) await restoreReloadedPlugin({ id, workspaceId: row.workspaceId });
      throw error;
    }
  }

  async function assertReloadApproved({ id, enabledCount, discovery }: {
    id: string; enabledCount: number; discovery: readonly PluginDiscoveryRecord[];
  }, _options = {}): Promise<void> {
    // Consent gap (2026-10-12): a re-seal that widens what a running plugin can reach waits for
    // the owner. Thrown here, the source service reports it as reloadError and keeps every
    // retained version; the approved version keeps running until plugins_set_enabled is confirmed.
    const next = discovery.find(record => record.id === id)?.manifest;
    const added = enabledCount > 0 && next ? addedPluginCapabilities({ approved: await pluginSource?.readApproval({ id }, {}), next: pluginCapabilitySet({ manifest: next }) }) : [];
    if (added.length > 0) throw new Error(`PLUGIN_APPROVAL_REQUIRED: this version adds ${added.join(', ')}. The approved version keeps running; ask the owner to approve it by enabling it again with plugins_set_enabled.`);
  }

  async function restoreReloadedPlugin({ id, workspaceId }: { id: string; workspaceId: string }, _options = {}): Promise<void> {
    // setPluginEnabled already restored the old activation row. Re-enter the same loader
    // to pin its retained bytes, rather than turning a working plugin off for a bad update.
    try { await onPluginEnabled(id); }
    catch (rollbackError) {
      console.warn(`[plugin-runtime] Plugin '${id}' restored-version reload failed`, rollbackError);
      onPluginDisabled(id);
      await quarantinePlugin({ deps: quarantineDeps, input: { pluginId: id, workspaceId, consecutiveFailures: 0, reason: 'Source reload and restored-version reload failed; fix the draft or use plugin_source_rollback.' } });
    }
  }

  const pluginSource = composeSourceService({}, {});

  function composeSourceService(_required: Record<string, never>, _options = {}): PluginSourcePort | undefined {
    if (installDir === undefined || pluginInstaller === undefined) return undefined;
    return createPluginSourceService({
      ...pluginHostBinding, installDir, installer: pluginInstaller, policy: pluginSourcePolicy,
      pruneVersions: ({ id }) => pruneSitePluginVersions({ id, installDir, repo: activationRepo }),
      builtInIds: sources.map(source => source.manifest.id),
      // readDefinedPlugin accepts this SDK wrapper ABI; no package imports are needed from an
      // external site's Documents folder. Owner: full server access for now. TODO: sandbox tier-3.
      scaffoldEntry: `export default { definition: { setup(sdk) {
  /* Register declared content filters here.
   * To add the examples below, declare capabilities http.route.register and tools.register,
   * and contributes: { routes: ['GET /hello'], tools: ['echo'] } in tovu.plugin.json.
   * Routes mount at /api/p/<plugin-id>/hello. Widgets use render.contribute and contributes.widgets.
   * sdk.routes.add({ method: 'GET', path: '/hello', access: 'public', handler: () => ({ body: { hello: true } }) });
   * sdk.tools.add({ name: 'echo', description: 'Echo input', inputSchema: { type: 'object' }, handler: ({ input }) => input });
   * sdk.widgets.add({ name: '<declared-widget-name>', render: () => '<strong>Hello</strong>' });
   */
} } };\n`,
      reload: async ({ id }) => {
        const enabled = (await activationRepo.listAll()).filter(row => row.pluginId === id && row.enabled);
        const discovery = await discoverPlugins();
        await assertReloadApproved({ id, enabledCount: enabled.length, discovery });
        // Load here before publishing active pointers to other processes. Their existing poll sees
        // a version change and re-enters the same validated loader, replacing module snapshots.
        enabled.sort((a, b) => Number(b.workspaceId === required.workspaceId) - Number(a.workspaceId === required.workspaceId));
        for (const row of enabled) {
          await reloadActivation({ row, id, discovery });
        }
        return enabled.some(row => row.workspaceId === required.workspaceId);
      },
    });
  }

  return {
    dispose: async (input, options = {}) => {
      closing = true;
      await Promise.allSettled([...pendingAttachments]);
      await snapshots?.dispose(input, options);
    },
    browserProviders: () => ({ generation: browserGeneration, providers: [...browserProviders.values()].flat() }),
    ...(pluginInstaller === undefined ? {} : { pluginInstaller }),
    ...(pluginSource === undefined ? {} : { pluginSource }),
    pluginSourcePolicy,
    pluginLoadedVersion: ({ id }) => loadedVersions.get(id),
    hookRegistry,
    pluginContributions,
    providerContributions,
    loadProviderPlugins,
    listProviderPlugins,
    discoverPlugins,
    discoverActivePlugins,
    onPluginEnabled,
    onPluginDisabled,
    locatePluginPackageDirs,
    readPluginPackageFiles,
    beforeSaveHook: (entry) => hookRegistry.runBeforeSave({ entry }),
    previewPluginBeforeSave: (pluginId, entry) => hookRegistry.previewBeforeSave({ pluginId, entry }),
    attachEnabledPluginsAtBoot,
    listPluginConflicts: () => listPluginConflicts(),
  };
}

/** Tovu-app usage projection. Site events keep their original payload on the independent branch. */
import type { ProductEvent, ProductEventProperties } from '@jini-ai/analytics/product';
import { TOOL_ATTEMPT_PHASES } from '@jini-ai/daemon/tool-audit';

const source = Object.freeze(['admin', 'assistant', 'service']);
const chatSurface = Object.freeze(['admin', 'daemon', 'public']);
const runOutcome = Object.freeze(['succeeded', 'failed', 'cancelled', 'canceled']);
const toolOutcome = Object.freeze(TOOL_ATTEMPT_PHASES.filter(phase => phase !== 'requested'));
type Rules = Readonly<Record<string, readonly string[] | 'boolean' | 'number'>>;

/** Closed property vocabularies, frozen at both levels. IDs, tool names, target names and text
 * have no rule: installed plugins and deploy targets are open catalogs, not product labels.
 * Call-site property inventory (variants share the same projection below):
 * - assistant run starts (assistant/byok modules, daemon): chatSurface, logicalRunId, eventId.
 * - run finishes (same plus run-ledger, site-assistant): the above plus outcome.
 * - assistant-chats chat starts: chatSurface, conversationId, source, eventId.
 * - assistant-chats/site-assistant messages: chatSurface, conversationId?, inputKind, eventId.
 * - tool-use-events/site-assistant: toolId, outcome, chatSurface, attemptId, eventId.
 * - site-admin creation: targetSiteId, templateKind, source.
 * - import-backend: targetSiteId, operationId, eventId, source.
 * - export-run: outcome, operationId, eventId, source.
 * - content-events publishes: eventId, resourceKind, resourceId, source, initialStatus?.
 * - presentation/theme setters: themeId, source.
 * - plugin install routes/tools: pluginId, pluginKind, source; toggles also enabled.
 * - media/analytics: kind, bytesBucket, source.
 * - publish-site/publish-agent-tools: target?, reasonClass, source.
 * - plugin install failures: operationKind, reasonClass, surface, retryable.
 * - provider-settings-save: contract, pluginId, action.
 * - browser-telemetry: route (renamed and shortened to screen).
 * Unlisted identity/free-text properties are intentionally omitted, including tool IDs rather
 * than inventing a category taxonomy. Product events never retain outbox/deduplication IDs.
 */
export const PRODUCT_EVENTS: Readonly<Record<string, Rules>> = Object.freeze(Object.fromEntries(Object.entries({
  app_started: { launchMode: ['fresh', 'update'] },
  desktop_screen_viewed: { screen: ['home', 'projects', 'templates', 'marketplace', 'tasks', 'generation', 'activity', 'updates', 'deploy', 'diagnostics', 'api-keys', 'settings', 'account', 'appearance', 'create_website'] },
  desktop_action: { action: ['create_website', 'add_existing_website', 'open_admin', 'open_preview', 'start_site', 'stop_site', 'open_settings', 'check_updates', 'open_chat'] },
  admin_pageview: {},
  assistant_run_started: { chatSurface },
  assistant_run_finished: { chatSurface, outcome: runOutcome },
  assistant_chat_started: { chatSurface, source },
  assistant_message_sent: { chatSurface, inputKind: ['text'], source },
  assistant_tool_used: { chatSurface, outcome: toolOutcome },
  site_created: { templateKind: ['default'], source },
  site_imported: { source },
  site_exported: { outcome: ['completed', 'errored'], source },
  post_published: { resourceKind: ['post'], source, initialStatus: ['draft', 'published', 'scheduled'] },
  page_published: { resourceKind: ['page'], source, initialStatus: ['draft', 'published', 'scheduled'] },
  theme_changed: { source },
  plugin_installed: { pluginKind: ['cms'], source },
  plugin_toggled: { pluginKind: ['cms'], enabled: 'boolean', source },
  media_uploaded: { kind: ['image', 'audio', 'video', 'document', 'other'], bytesBucket: ['<100KB', '<1MB', '<10MB', '10MB+'], source },
  site_publish_blocked: { reasonClass: ['auth', 'config', 'consent', 'busy'], source },
  operation_failed: { operationKind: ['plugin_install'], reasonClass: ['refused', 'internal'], surface: ['admin', 'assistant'], retryable: 'boolean' },
  provider_configured: { contract: ['observability', 'product_analytics', 'ai_trace'], action: ['save'] },
}).map(([name, rules]) => [name, Object.freeze(Object.fromEntries(Object.entries(rules).map(([key, rule]) => [key, Array.isArray(rule) ? Object.freeze(rule) : rule])))])));

/** Reduce an existing route template to two segments; later segments can contain site slugs.
 * @returns The projected admin screen, or undefined outside admin. @complexity O(n) route length.
 */
export function productAdminScreen({ route }: { route: unknown }, _options = {}): string | undefined {
  if (typeof route !== 'string') return undefined;
  const parts = route.split(/[?#]/, 1)[0]!.split('/');
  if (parts[1] !== 'admin') return undefined;
  return parts[2] ? `/admin/${parts[2]}` : '/admin';
}

/** Check one declared value without coercion. @complexity O(e) in the small enum size. */
function allowedValue({ rule, value }: { rule: Rules[string]; value: unknown }, _options = {}): boolean {
  if (rule === 'boolean') return typeof value === 'boolean';
  if (rule === 'number') return typeof value === 'number' && Number.isFinite(value);
  return typeof value === 'string' && rule.includes(value);
}

/** Project only catalog properties and replace all caller identity with installation identity.
 * Unknown fields and invalid enum values are omitted; invalid booleans/numbers refuse the event.
 * @returns A fresh event, or undefined for unapproved names/values/identity. No effects.
 * @example projectProductEvent({ event: { name: 'app_started', userId: 'ignored' }, installationId: 'fake-install' });
 * @complexity O(k) declared keys, bounded by the frozen catalog; no caller-property scan.
 */
export function projectProductEvent({ event, installationId }: { event: ProductEvent; installationId: string | null }, _options = {}): ProductEvent | undefined {
  if (!installationId || !Object.hasOwn(PRODUCT_EVENTS, event.name)) return undefined;
  if (event.name === 'admin_pageview') {
    const screen = productAdminScreen({ route: event.properties?.route });
    return screen ? { name: 'admin_screen_viewed', userId: installationId, properties: { screen } } : undefined;
  }
  const properties = declaredProperties({ rules: PRODUCT_EVENTS[event.name]!, properties: event.properties });
  return properties ? { name: event.name, userId: installationId, properties } : undefined;
}

/** Declared keys only; invalid enums are omitted, invalid booleans/numbers refuse the event.
 * @complexity O(k) declared keys.
 */
function declaredProperties({ rules, properties }: { rules: Rules; properties: ProductEvent['properties'] }, _options = {}): ProductEventProperties | undefined {
  const projected: Record<string, ProductEventProperties[string]> = {};
  for (const [key, rule] of Object.entries(rules)) {
    const value = properties?.[key];
    if (value === undefined) continue;
    if (!allowedValue({ rule, value })) {
      if (Array.isArray(rule)) continue;
      return undefined;
    }
    projected[key] = value;
  }
  return projected;
}

/** Install-level telemetry for Tovu's desktop processes, independent of every site's providers. */
import { readFileSync, statSync } from 'node:fs';
import { readFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { redactSecrets } from '@jini-ai/core';
import { maskLocalPaths } from '@jini-ai/diagnostics';
import { createNoopObservabilityPort, type CrashUpload, type ErrorReport, type ObservabilityPort } from '@jini-ai/diagnostics/observability';
import { createNoopProductAnalytics, withProductAnalyticsGuards, type ProductAnalyticsPort } from '@jini-ai/analytics/product';
import type { PluginDiscoveryRecord } from '@jini-ai/plugins/host/node';
import { redactLocalText } from '#src/platform/server-logs/redact-local-text';
import { productAdminScreen, projectProductEvent } from '#src/server/runtime/composition/product-events';
import { processBuildRelease } from './build-release.js';

export interface ProductConsent { crashes: boolean; usage: boolean; installationId: string | null; }
export interface ProductTelemetry {
  /** Successful config/provider initialization; desktop must not prompt on a failed boot. */
  active?: boolean;
  observability: ObservabilityPort;
  productAnalytics: ProductAnalyticsPort;
  crashUpload?: CrashUpload;
  dispose(): Promise<void>;
}
interface ConfigEntry { plugin: string; input: Readonly<Record<string, unknown>>; }
export interface ProductTelemetryConfig { observability?: ConfigEntry; productAnalytics?: ConfigEntry; }
export interface ProductTelemetryRequired { configPath: string; preferencePath: string; processRole: 'server' | 'daemon' | 'desktop-main'; release: string; }
export interface ProductProviderInput { config: ProductTelemetryConfig; attribution: { attributes: Record<string, string>; groups: Record<string, string> }; release: string; }
export interface ProductTelemetryOptions {
  loadProviders?: (required: ProductProviderInput) => Promise<ProductTelemetry>;
  readConsent?: () => ProductConsent;
  warn?: (message: string) => void;
}
const OFF: ProductConsent = Object.freeze({ crashes: false, usage: false, installationId: null });
const WARNING = '[product-telemetry] unavailable; product reporting is disabled';
// Five levels above composition/: Resources in the staged desktop bundle (stage-website-shared keeps
// website/src/server/runtime/composition below it), the payload root in a packaged child, apps/ in a
// checkout. Stack frames below it stay readable as app:///…; every other local path is masked.
const INSTALL_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../../../..');
// Frames are home-redacted before masking, so the root is retained in its redacted spelling too.
const KEEP_ROOTS = [INSTALL_ROOT, redactLocalText({ text: INSTALL_ROOT })];

/** Parse the existing desktop preference key; malformed values never grant consent. O(1). */
function consentOf({ value }: { value: unknown }, _options = {}): ProductConsent {
  const record = (value as { productTelemetry?: Partial<ProductConsent> } | null)?.productTelemetry;
  return { crashes: record?.crashes === true, usage: record?.usage === true,
    installationId: typeof record?.installationId === 'string' ? record.installationId : null };
}

/** One cache per process consumer. Stat every event, parse only after mtime changes; any I/O or
 * parse failure is off, including deletion after a previously successful read.
 * @param required Preference path supplied by desktop main, never a site setting.
 * @param options File effects are injectable for exact read-count tests.
 * @returns The synchronous per-event consent reader for analytics and error gates.
 * @complexity O(1) stat per event; O(n) preference bytes only on a changed mtime.
 */
export function createProductConsentReader({ preferencePath }: { preferencePath: string }, { stat = statSync, read = readFileSync }: {
  stat?: (file: string) => { mtimeMs: number }; read?: (file: string, encoding: 'utf8') => string;
} = {}): () => ProductConsent {
  let mtime: number | undefined;
  let cached = OFF;
  return () => {
    let next: number;
    try { next = stat(preferencePath).mtimeMs; }
    catch { mtime = undefined; cached = OFF; return OFF; }
    if (next === mtime) return cached;
    mtime = next;
    cached = OFF;
    try { cached = consentOf({ value: JSON.parse(read(preferencePath, 'utf8')) }); }
    catch { /* An unchanged unreadable/malformed record stays cached as off. */ }
    return cached;
  };
}

/** Validate one optional config entry before any provider code runs. O(n) plugin id length. */
function validEntry({ entry }: { entry: ConfigEntry | undefined }, _options = {}): boolean {
  if (entry === undefined) return true;
  if (!entry || typeof entry.plugin !== 'string' || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(entry.plugin)) return false;
  return Boolean(entry.input) && typeof entry.input === 'object' && !Array.isArray(entry.input);
}

/** Validate a vendor-neutral config before any provider code runs. O(1) entries, no effects. */
function configOf({ value }: { value: unknown }, _options = {}): ProductTelemetryConfig {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('InvalidProductConfig');
  const config = value as ProductTelemetryConfig;
  // An empty document would mark telemetry active (and prompt for consent) with nothing to send.
  if (!config.observability && !config.productAnalytics) throw new Error('InvalidProductConfig');
  for (const key of ['observability', 'productAnalytics'] as const) {
    const entry = config[key];
    if (!validEntry({ entry })) throw new Error('InvalidProductConfig');
  }
  return config;
}

/** No config and failed boot use the existing noop owners. O(1), no effects. */
function noopTelemetry(_required: Record<string, never>, _options = {}): ProductTelemetry {
  return { observability: createNoopObservabilityPort({}), productAnalytics: createNoopProductAnalytics({}), async dispose() {} };
}

/** Select the configured contract from discovery's validated manifest, never from config data.
 * @throws To boot on missing/invalid artifacts or a missing contract. @complexity O(p + c) catalog.
 */
function productProviderOf({ records, pluginId, contract }: { records: readonly PluginDiscoveryRecord[]; pluginId: string; contract: string }, _options = {}) {
  const record = records.find(item => item.id === pluginId);
  const manifest = record?.manifest;
  if (!record || !manifest) throw new Error('ProductProviderUnavailable');
  const provider = manifest.contributes?.providers?.find(item => item.contract === contract);
  if (!provider) throw new Error('ProductProviderUnavailable');
  return { record, manifest, provider };
}

/** Bind artifact discovery and the existing product SDK once; Jini owns integrity, import ordering,
 * provider validation and lifecycle. This is composition glue, never a second plugin runtime.
 * @throws To the boot boundary, which releases earlier resources and stays on both noops.
 * @complexity O(a) discovery/integrity in bundled artifact bytes; at most two provider loads.
 */
async function loadProductProviders(required: ProductProviderInput, _options = {}): Promise<ProductTelemetry> {
  const [{ discoverPlugins, loadProviderPluginArtifact, siteEntryPath }, { pluginHostBinding, createPluginModuleImporter }, { PROVIDER_CONTRACTS }] = await Promise.all([
    import('@jini-ai/plugins/host/node'), import('../../../features/plugin-runtime/host-binding.js'), import('./provider-plugins.js'),
  ]);
  // The staged desktop bundle has no node_modules ancestor: resolve from the payload/shell roots too.
  const catalogPath = createRequire(import.meta.url).resolve('@jini-ai/provider-plugins/catalog', {
    paths: [path.dirname(fileURLToPath(import.meta.url)), path.join(INSTALL_ROOT, 'tovu'), path.join(INSTALL_ROOT, 'app.asar')],
  });
  const installDir = path.join(path.dirname(catalogPath), 'plugins');
  const records = await discoverPlugins({ ...pluginHostBinding, builtIns: [], installDir });
  const resources: Awaited<ReturnType<typeof loadProviderPluginArtifact>>[] = [];
  const result = noopTelemetry({});
  result.dispose = async () => { await Promise.all(resources.map(resource => resource.dispose({}))); };
  try {
    for (const [key, contract] of [['observability', 'observability'], ['productAnalytics', 'product_analytics']] as const) {
      const entry = required.config[key];
      if (!entry) continue;
      const { record, manifest, provider } = productProviderOf({ records, pluginId: entry.plugin, contract });
      const unavailable = (): never => { throw new Error('ProductProviderHasNoSiteContext'); };
      const resource = await loadProviderPluginArtifact({ load: { ...pluginHostBinding, record, manifest,
        entryPath: siteEntryPath({ installDir, id: record.id, version: record.version }),
        importModule: createPluginModuleImporter({ manifest, source: 'built-in' }),
        coreDeps: { getCurrentEntry: unavailable, writeExtField: unavailable, attachFilter: unavailable } },
        contracts: PROVIDER_CONTRACTS, contract, id: provider.id,
        input: { ...entry.input, release: required.release, environment: required.attribution.attributes.environment, attribution: required.attribution } }, { factoryOptions: { info() {} } });
      resources.push(resource);
      // The provider host validated the selected contract before returning its opaque port.
      Object.assign(result, { [key]: resource.port });
    }
    return result;
  } catch (error) { await result.dispose(); throw error; }
}

/** Credential + PII redaction precedes truncation so a cut cannot hide a secret's shape. O(n). */
function scrub({ text }: { text: string }, _options = {}): string {
  return maskLocalPaths({ text: redactSecrets({ input: redactLocalText({ text }) }) }, { keepRoots: KEEP_ROOTS });
}

/** Project diagnostic context without carrying site IDs, URLs, user identities or raw route slugs.
 * @returns Only the permitted context keys, with local text scrubbed. @complexity O(n) selected text.
 */
function errorContext({ context }: Pick<ErrorReport, 'context'>, _options = {}): ErrorReport['context'] {
  const attributes: Record<string, string | number> = {};
  for (const key of ['process', 'code', 'signal'] as const) {
    const value = context.attributes?.[key];
    if (typeof value === 'string') attributes[key] = scrub({ text: value }).slice(0, 100);
    else if (typeof value === 'number' && Number.isFinite(value)) attributes[key] = value;
  }
  const route = productAdminScreen({ route: context.attributes?.route });
  if (route) attributes.route = route;
  return { operation: scrub({ text: context.operation }).slice(0, 100), attributes,
    ...(context.level === 'warning' ? { level: 'warning' as const } : {}) };
}

const PRODUCT_METRIC_UNITS: Readonly<Record<string, string>> = Object.freeze({
  'process.memory.rss': 'By', 'process.memory.heap_used': 'By', 'process.count': '{process}', 'process.uptime': 's',
});
const PRODUCT_METRIC_PROCESSES = new Set(['main', 'renderer', 'server', 'daemon', 'other']);

/** Product errors follow crash consent; numeric gauges follow usage consent with fixed labels.
 * Causes/custom Error fields and caller-named metric attributes never cross.
 * All lifecycle signals retain the singleton noop implementations (no product traces).
 * @returns A port retaining local error admission and metric capability.
 * @complexity O(n) error and permitted context text per report; O(1) per metric.
 */
function productObservability({ inner, readConsent }: { inner: ObservabilityPort; readConsent: () => ProductConsent }, _options = {}): ObservabilityPort {
  return { ...createNoopObservabilityPort({}),
    get supportsMetric() { return inner.supportsMetric === true; },
    metric(input, options = {}) {
      if (readConsent().usage !== true || !Object.hasOwn(PRODUCT_METRIC_UNITS, input.name)) return;
      const process = options.attributes?.process;
      if (typeof process !== 'string' || !PRODUCT_METRIC_PROCESSES.has(process) || !Number.isFinite(input.value) || input.value < 0) return;
      return inner.metric({ name: input.name, value: input.value }, { kind: 'gauge', unit: PRODUCT_METRIC_UNITS[input.name], attributes: { process } });
    }, reportError({ error, context }) {
      if (readConsent().crashes !== true) return false;
      const original = error instanceof Error ? error : new Error(String(error));
      const safe = new Error(scrub({ text: original.message }).slice(0, 300));
      safe.name = scrub({ text: original.name }).slice(0, 100);
      safe.stack = scrub({ text: original.stack ?? '' });
      return inner.reportError({ error: safe, context: errorContext({ context }) });
    } };
}

/** Catalog projection precedes the shared privacy guard: caller IDs and discarded fields cannot
 * affect the install-level identity or leak to a provider. Identify is inert; AI content absent.
 * @complexity O(k) bounded catalog projection plus the existing analytics guard.
 */
function productAnalytics({ inner, readConsent }: { inner: ProductAnalyticsPort; readConsent: () => ProductConsent }, _options = {}): ProductAnalyticsPort {
  const guarded = withProductAnalyticsGuards({ inner: { capture: event => inner.capture(event), identify() {} }, consent: () => readConsent().usage === true });
  return { identify() {}, capture(event) {
    const projected = projectProductEvent({ event, installationId: readConsent().installationId });
    if (projected) return guarded.capture(projected);
  } };
}

/** Release a partially booted output and emit one fixed diagnostic; neither effect may fail boot.
 * @returns Both existing noops. @complexity O(1) plus the provider owner's bounded disposal.
 */
async function failedProductBoot({ providers, warn }: { providers?: ProductTelemetry; warn?: (message: string) => void }, _options = {}): Promise<ProductTelemetry> {
  try { await providers?.dispose(); } catch { /* Boot must remain available even if provider cleanup fails. */ }
  try { (warn ?? console.warn)(WARNING); } catch { /* A diagnostic sink cannot fail boot. */ }
  return noopTelemetry({});
}

/** Boot both install-level outputs atomically. No config/read/load/init failure escapes or prints
 * config/error text; partial provider resources are disposed by their loading owner.
 * @param required Paths, process role and release supplied by the desktop launch boundary.
 * @param options Provider loader, synchronous consent reader and fixed-warning sink.
 * @returns Guarded outputs, optional native-upload configuration and owned teardown.
 * @example bootProductTelemetry({ configPath, preferencePath, processRole: 'server', release });
 * @complexity O(config + bundled artifact bytes) at boot; per-event costs documented above.
 */
export async function bootProductTelemetry(required: ProductTelemetryRequired, options: ProductTelemetryOptions = {}): Promise<ProductTelemetry> {
  let providers: ProductTelemetry | undefined;
  try {
    const config = configOf({ value: JSON.parse(await readFile(required.configPath, 'utf8')) });
    providers = await (options.loadProviders ?? loadProductProviders)({ config, release: required.release,
      attribution: { attributes: { source: 'desktop', release: required.release, environment: 'desktop',
        'service.version': required.release, 'deployment.environment': 'desktop', os: process.platform, arch: process.arch, process: required.processRole }, groups: {} } });
    const readConsent = options.readConsent ?? createProductConsentReader({ preferencePath: required.preferencePath });
    const crashUpload = providers.observability.crashUpload?.({ release: required.release, environment: 'desktop' });
    return { active: true, observability: productObservability({ inner: providers.observability, readConsent }),
      productAnalytics: productAnalytics({ inner: providers.productAnalytics, readConsent }),
      ...(crashUpload ? { crashUpload } : {}), dispose: providers.dispose };
  } catch {
    return failedProductBoot({ providers, warn: options.warn });
  }
}

/** Children opt in only when main supplied both paths. No env means no file reads, warnings or
 * provider loads; ordinary web/dev composition retains its existing ports and tracker behavior.
 * @returns Undefined without an active launch configuration. @complexity O(1) beyond boot.
 */
export async function bootProductTelemetryFromEnv({ env = process.env, processRole = 'server' }: { env?: NodeJS.ProcessEnv | undefined; processRole?: 'server' | 'daemon' | undefined }, options: ProductTelemetryOptions = {}): Promise<ProductTelemetry | undefined> {
  const configPath = env.TOVU_PRODUCT_TELEMETRY_CONFIG;
  const preferencePath = env.TOVU_PRODUCT_TELEMETRY_PREFS;
  if (!configPath || !preferencePath) return undefined;
  return bootProductTelemetry({ configPath, preferencePath, processRole, release: env.TOVU_PRODUCT_RELEASE || processBuildRelease({}) }, options);
}

import { createTracker, createTrackerWarning, createTelemetryTestProbe } from "@jini-ai/diagnostics/observability/node";
import type { ConsentPluginContribution } from '../../inbound/public-http/middleware/site-cookie-consent.js';
import { createHash } from 'node:crypto';
import { createTelemetryDeliveryMonitor, describeTelemetryFailure, type Tracker, type ProviderTelemetryReport, type TelemetryTestResult } from "@jini-ai/diagnostics/observability";
import { combineObservabilityPorts, createNoopObservabilityPort, type ObservabilityPort } from "@jini-ai/diagnostics/observability";
import { createAiGenerationSink, createNoopProductAnalytics, fanOutProductAnalytics, withProductAnalyticsGuards, type ProductAnalyticsConsent, type ProductAnalyticsConsentRevision, type ProductAnalyticsPort, type BrowserAnalyticsContribution } from "@jini-ai/analytics/product";
import { createFanOutAiTraceSink, type AiTraceSink } from "@jini-ai/agent-runtime/ai-trace";
import { createPluginProviderHost, pluginProviderStartupGuidance, isProviderSettingRequired, type PluginContributionRegistry, type PluginProviderContract, type PluginProviderDeclaration, type PluginProviderLease } from "@jini-ai/plugins/host";

import type { ProviderConfigSource, ProviderPluginConfig } from "./provider-config-source.js";
import { bootProductTelemetryFromEnv, type ProductTelemetry, type ProductTelemetryOptions } from './product-telemetry.js';
import { processBuildRelease } from './build-release.js';

/**
 * @file Provider plugins at boot (provider wave 2, 2026-10-25): observability, product analytics and
 * AI tracing come from Jini's first-party provider plugins (`@jini-ai/provider-plugins`), never from
 * vendor SDKs in Tovu core. Replaces the env-driven `require()` of an OTel adapter that lived in
 * `platform/observability`: an install pays for an SDK only when the provider plugin is INSTALLED +
 * ENABLED + CONFIGURED, and every other contract keeps its existing noop.
 *
 * Configuration: each provider plugin DECLARES its settings in its manifest (public + secret fields;
 * `PluginProviderDeclaration.settings`), the owner fills them on the plugin's settings card in the
 * admin (Plugins → the plugin → Settings), and they are saved sealed through `ProviderConfigSource`
 * (`provider-config-source.ts`: the project store when one is configured, else the site vault). A
 * provider is "configured" when every required declared field has a value; its saved values are its
 * factory's required args, plus host identity (`serviceName`) and site attribution (`attributionFor`). Never env, files, logs or chat. Tovu
 * boot holds no per-vendor mapping: everything it needs to know comes from the manifest; the
 * settings adapter alone normalizes retired persisted choices before they reach this boundary.
 *
 * Order: initialized (awaited, each bounded by the provider host's timeout) before the composition
 * root decorates kernels and HTTP clients, so application work never starts on a half-built port.
 * Disposed with the site store. Disabling or quarantining a provider plugin retires its contribution
 * generation, which disposes its resources; its port then goes inert (`gatedPort`) until it is reapplied.
 */

export type ProviderContract = "observability" | "product_analytics" | "ai_trace";

/** Which site sends every signal (owner 2026-10-25): sites of one project can share one backend. */
export interface SiteIdentity {
  readonly siteId: string;
  readonly siteSlug: string;
  readonly environment: "local" | "desktop" | "fly";
  readonly projectId: string;
}

/**
 * The neutral `attribution` factory input (`@jini-ai/provider-plugins`) for one contract: Tovu names
 * the keys per contract, never per vendor — observability uses OpenTelemetry's resource conventions
 * (`deployment.environment` + `tovu.*`), product analytics event properties plus a `site` group, AI
 * traces metadata plus a `site:<slug>` tag.
 * @complexity O(1).
 */
export function attributionFor({ contract, site }: { contract: ProviderContract; site: SiteIdentity }, { release = processBuildRelease({}) }: { release?: string } = {}): Readonly<Record<string, unknown>> {
  if (contract === "observability") {
    return { attributes: { "tovu.site.id": site.siteId, "tovu.site.slug": site.siteSlug, "deployment.environment": site.environment, "tovu.project.id": site.projectId, "service.version": release } };
  }
  const attributes = { site_id: site.siteId, site_slug: site.siteSlug, environment: site.environment, project_id: site.projectId, release };
  return contract === "product_analytics" ? { attributes, groups: { site: site.siteId } } : { attributes, tags: [`site:${site.siteSlug}`] };
}

/** One installed + enabled plugin's provider declarations, read from its manifest (no code runs). */
export interface ProviderPluginDeclarations {
  readonly pluginId: string;
  readonly providers: readonly PluginProviderDeclaration[];
}

/**
 * Whether a provider key was saved the retired way: wave 2 stored it as an API credential labelled
 * `plugin:<plugin id>`, which boot no longer reads. Matched by label on the non-decrypting listing,
 * so no secret is ever opened; the admin settings card turns a match into a re-entry notice.
 * @complexity O(n) in the workspace's (small) credential count.
 */
export function legacyProviderCredentialCheck(
  required: { listLabels: () => Promise<readonly { label: string }[]> },
  _optional: Record<string, never> = {},
): (input: { pluginId: string }) => Promise<boolean> {
  return async ({ pluginId }) => (await required.listLabels()).some((row) => row.label === `plugin:${pluginId}`);
}

/**
 * The factory input a provider's saved settings make, or undefined when it is not configured: no row
 * saved, no declared settings, or a required declared field without a value. Only declared names pass.
 * A blank public field takes the plugin's declared `default` (e.g. its vendor's cloud host).
 * @complexity O(f) declared fields.
 */
export function providerInputOf({ declaration, saved }: { declaration: PluginProviderDeclaration; saved: ProviderPluginConfig | null }, _optional = {}): Readonly<Record<string, string>> | undefined {
  const fields = declaration.settings ?? [];
  if (!saved || fields.length === 0) return undefined;
  const defaults = Object.fromEntries(fields.filter((field) => !field.secret && field.default).map((field) => [field.name, field.default!]));
  const values: Record<string, string | undefined> = { ...defaults, ...Object.fromEntries(Object.entries(saved.settings).filter(([, value]) => value.trim() !== "")), ...saved.secrets };
  const present = (name: string) => (values[name] ?? "").trim() !== "";
  if (fields.some((field) => isProviderSettingRequired({ field, values }) && !present(field.name))) return undefined;
  return Object.fromEntries(fields.filter((field) => present(field.name)).map((field) => [field.name, values[field.name]!]));
}

const hasMethods = ({ value, names }: { value: unknown; names: readonly string[] }): boolean =>
  typeof value === "object" && value !== null && names.every((name) => typeof (value as Record<string, unknown>)[name] === "function");

/** Domain-owned port checks; a plugin never supplies or replaces these validators. */
export const PROVIDER_CONTRACTS: readonly PluginProviderContract[] = [
  // `metric` is not required: contract v1 providers predate it, and gatedPort routes a missing method to the noop.
  { contract: "observability", validate: ({ provider }) => hasMethods({ value: provider, names: ["trackRequest", "trackDbQuery", "trackOutboundCall", "trackAgentRun", "trackOperation", "reportError"] }) ? undefined : "not an ObservabilityPort" },
  { contract: "product_analytics", validate: ({ provider }) => hasMethods({ value: provider, names: ["capture", "identify"] }) && validAiCapability({ provider }) ? undefined : "not a ProductAnalyticsPort" },
  { contract: "ai_trace", validate: ({ provider }) => hasMethods({ value: provider, names: ["record"] }) ? undefined : "not an AiTraceSink" },
];

/** Optional capabilities remain optional; malformed declarations are refused before composition.
 * @complexity O(1). */
function validAiCapability({ provider }: { provider: unknown }): boolean {
  const port = provider as ProductAnalyticsPort;
  return (port.captureAiGeneration === undefined || typeof port.captureAiGeneration === "function")
    && (port.browserAnalytics === undefined || typeof port.browserAnalytics === 'function')
    && (port.includeAiContent === undefined || typeof port.includeAiContent === "boolean");
}

export interface ProviderPluginRuntime {
  readonly providerContributions: PluginContributionRegistry;
  /** Installed + enabled plugins that declare providers, from their manifests; no plugin code runs. */
  listProviderPlugins(required: Record<string, never>, optional?: Record<string, never>): Promise<readonly ProviderPluginDeclarations[]>;
  /** `timeoutMs` bounds each plugin's import + setup; a plugin past it is revoked and left on the noop. */
  loadProviderPlugins(required: { pluginIds: readonly string[] }, optional?: { timeoutMs?: number }): Promise<readonly string[]>;
}

export interface ProviderPluginPorts {
  readonly browserAnalytics?: (required: { surface: 'site' | 'admin' }) => readonly BrowserAnalyticsContribution[];
  /** Cookie-consent adapters of the attached analytics plugins, each mounted under `base/<pluginId>`. */
  readonly consentAdapters?: (required: { base: string }) => readonly ConsentPluginContribution[];
  readonly observability: ObservabilityPort;
  readonly tracker: Tracker;
  /** Used only after the public boundary has validated the visitor's consent proof. */
  readonly visitorTracker?: Tracker;
  observabilityEnabled?: () => boolean;
  telemetryStatus: ReturnType<typeof createTelemetryDeliveryMonitor>["read"];
  sendTelemetryTest(required: { error: Error }, optional?: Record<string, never>): Promise<TelemetryTestResult>;
  /** Undefined when neither a trace nor analytics provider is declared; slots can activate live. */
  readonly aiTraceSink: AiTraceSink | undefined;
  appliesAt(required: { pluginId: string }, optional?: Record<string, never>): "now" | "restart" | "failed";
  reapply(required: { pluginId: string }, optional?: Record<string, never>): Promise<import("@jini-ai/plugins/host").PluginProviderApplyResult>;
  /** Idempotent; bounded per resource by the provider host. */
  dispose(required: Record<string, never>, optional?: Record<string, never>): Promise<void>;
}

export interface BootProviderPluginsRequired {
  /** Build identity supplied once by the host; defaults to this running product's manifest. */
  readonly release?: string;
  readonly processRole?: 'server' | 'daemon';
  readonly runtime: ProviderPluginRuntime;
  /** Saved settings per plugin. Read failures are treated as "not configured". */
  readonly config: ProviderConfigSource;
  readonly serviceName: string;
  /** Carried by every signal as the factory's `attribution` input. */
  readonly site: SiteIdentity;
  readonly consent: ProductAnalyticsConsent;
  readonly consentRevision: ProductAnalyticsConsentRevision;
}

export interface BootProviderPluginsOptional {
  readonly env?: NodeJS.ProcessEnv;
  readonly productTelemetry?: ProductTelemetryOptions;
  readonly initializeTimeoutMs?: number;
  readonly warn?: (message: string) => void;
  readonly info?: (message: string) => void;
}

type ProviderSlot = { pluginId: string; contract: ProviderContract; id: string;
  declaration: PluginProviderDeclaration; lease?: PluginProviderLease; input?: string; initializationObserved?: boolean };
/** An absent input is already inert; a configured input must also retain a current generation. */
function unchangedSlot({ slot, signature }: { slot: ProviderSlot; signature: string | undefined }, _optional = {}): boolean {
  if (signature !== slot.input) return false;
  return signature === undefined || slot.lease?.isCurrent({}) === true;
}

/** Legacy browser contributors cannot promise retirement of downloaded SDKs on a live change. */
function browserNeedsRestart({ slot, saved }: { slot: ProviderSlot; saved: ProviderPluginConfig | null }, _optional = {}): boolean {
  if (slot.contract !== 'product_analytics' || !slot.lease) return false;
  const input = providerInputOf({ declaration: slot.declaration, saved });
  if (unchangedSlot({ slot, signature: input === undefined ? undefined : JSON.stringify(input) })) return false;
  const port = slot.lease.port as ProductAnalyticsPort;
  try {
    return (['site', 'admin'] as const).some(surface => {
      const browser = port.browserAnalytics?.({ surface });
      return browser !== undefined && browser.supportsLiveConsent !== true;
    });
  } catch { return true; }
}
const KNOWN_CONTRACTS = new Set<string>(["observability", "product_analytics", "ai_trace"]);

/** Each contract's inert behavior, used once a lease is retired. */
const NOOP_PORTS: Readonly<Record<ProviderContract, () => object>> = {
  observability: () => createNoopObservabilityPort({}),
  product_analytics: () => createNoopProductAnalytics({}),
  ai_trace: (): AiTraceSink => ({ record() {}, flush: async () => {}, shutdown: async () => {} }),
};

/**
 * Disable/quarantine retires a lease and disposes its resources, but composed ports were built at
 * boot: every call re-checks `isCurrent()` first so a retired lease admits no new work (Jini's lease
 * contract) and the call takes the contract's noop path instead. Methods the port lacks (e.g. an AI
 * trace sink without `flush`) take the noop path too.
 * @complexity O(m) at boot for m contract methods; O(1) per gated call.
 */
function gatedPort({ slot, contract, testProbe }: { slot: ProviderSlot; contract: ProviderContract; testProbe: ReturnType<typeof createTelemetryTestProbe> }): unknown {
  const noop = NOOP_PORTS[contract]() as Record<string, (...args: unknown[]) => unknown>;
  const names = Object.keys(noop).filter(name => typeof noop[name] === "function");
  // Keep the optional hook available before attachment; every call follows the current slot.
  if (contract === "product_analytics") names.push("captureAiGeneration", "browserAnalytics");
  const browserCache = new Map<string, { lease: unknown; contribution: unknown }>();
  const gated = Object.fromEntries(names.map((name) => [name, (...args: unknown[]) => {
    const lease = slot.lease;
    const port = lease?.port as Record<string, unknown> | undefined;
    const live = port?.[name];
    if (!lease?.isCurrent({}) || typeof live !== "function") return noop[name]?.(...args);
    if (name === 'browserAnalytics') {
      const surface = (args[0] as { surface: string }).surface;
      const cached = browserCache.get(surface);
      if (cached?.lease === lease) return cached.contribution;
      const contribution = live.apply(port, args);
      browserCache.set(surface, { lease, contribution });
      return contribution;
    }
    const result = live.apply(port, args);
    testProbe.accepted({ providerId: `${slot.pluginId}/${slot.id}`, method: name, input: args[0], supportsMetric: port!.supportsMetric === true });
    return result;
  }]));
  if (contract === "observability") Object.defineProperty(gated, "supportsMetric", {
    get: () => slot.lease?.isCurrent({}) === true && (slot.lease.port as ObservabilityPort).supportsMetric === true,
  });
  if (contract === "product_analytics") Object.assign(gated, { consentAdapter: gatedConsentAdapter({ slot }) });
  if (contract === "product_analytics") Object.defineProperty(gated, "includeAiContent", {
    get: () => slot.lease?.isCurrent({}) === true && (slot.lease.port as ProductAnalyticsPort).includeAiContent === true,
  });
  if (contract === "ai_trace") Object.defineProperty(gated, "capture", {
    get: () => slot.lease?.isCurrent({}) ? (slot.lease.port as AiTraceSink).capture : "metadata",
  });
  return gated;
}

/** The current plugin's cookie-consent contribution. Each plugin's assets live under its own id, so two
 * plugins never collide; a detached slot or a plugin without the hook contributes nothing. @complexity O(1). */
function gatedConsentAdapter({ slot }: { slot: ProviderSlot }, _optional = {}): (required: { base: string }) => unknown {
  return ({ base }) => {
    const port = slot.lease?.isCurrent({}) ? slot.lease.port as { consentAdapter?: (required: { path: string }) => unknown } : undefined;
    return typeof port?.consentAdapter === 'function' ? port.consentAdapter({ path: `${base}/${slot.pluginId}` }) : undefined;
  };
}

/** Composes guarded analytics, trace destinations and independent observability without vendor knowledge.
 * @complexity O(p + s) at boot for p analytics providers and s trace sinks; no external I/O. */
function composePorts({ leases, consent, consentRevision, site, warn, product }: { warn: (message: string) => void; leases: ReadonlyMap<ProviderContract, unknown[]>; consent: ProductAnalyticsConsent; consentRevision: ProductAnalyticsConsentRevision; site: SiteIdentity; product?: ProductTelemetry }) {
  const analytics = (leases.get("product_analytics") ?? []) as ProductAnalyticsPort[];
  const sinks = [...(leases.get("ai_trace") ?? [])] as AiTraceSink[];
  const failed = createTrackerWarning({}, { warn });
  const inner = fanOutProductAnalytics({ ports: analytics }, { onFailure: failed });
  // Jini snapshots capability flags at construction; the site wrappers must follow live opt-ins.
  const productAnalytics = analytics.length === 0 ? createNoopProductAnalytics({}) : {
    ...withProductAnalyticsGuards({ inner, consent }, { consentRevision }),
    get includeAiContent() { return inner.includeAiContent === true; },
  };
  // Site-scoped operator activity: consent is the site's telemetry setting; no synthetic person
  // identity or prompt-derived id is needed. The plugin attaches the same site group as other events.
  const generations = createAiGenerationSink({ analytics: productAnalytics, userId: `site:${site.siteId}` });
  if (generations) sinks.push({ ...generations, get capture() { return productAnalytics.includeAiContent === true ? "full" : "metadata"; } });
  const siteObservability = combineObservabilityPorts({ ports: (leases.get("observability") ?? []) as ObservabilityPort[] }, { onFailure: failed });
  // Product consent is install-level, outside the site's guard. Browser SDKs, visitor activity
  // and AI generations retain only the site branch; product never accepts their content/identity.
  const observability = product ? combineObservabilityPorts({ ports: [siteObservability, product.observability] }, { onFailure: failed }) : siteObservability;
  const trackerAnalytics = product ? fanOutProductAnalytics({ ports: [productAnalytics, product.productAnalytics] }, { onFailure: failed }) : productAnalytics;
  const browserCache = new Map<string, { inputs: readonly BrowserAnalyticsContribution[]; output: readonly BrowserAnalyticsContribution[] }>();
  return {
    observability,
    // Optional and untyped on the Jini port: a plugin without it (or one that throws) adds nothing.
    consentAdapters: (required: { base: string }): readonly ConsentPluginContribution[] => analytics.flatMap(port => {
      const build = (port as { consentAdapter?: (input: { base: string }) => ConsentPluginContribution | undefined }).consentAdapter;
      try { const contribution = typeof build === 'function' ? build.call(port, required) : undefined; return contribution ? [contribution] : []; }
      catch { failed(); return []; }
    }),
    browserAnalytics: (required: { surface: 'site' | 'admin' }): readonly BrowserAnalyticsContribution[] => {
      const contributions = analytics.flatMap(port => {
        try { const contribution = port.browserAnalytics?.(required); return contribution ? [contribution] : []; }
        catch { failed(); return []; }
      });
      const cached = browserCache.get(required.surface);
      if (cached && cached.inputs.length === contributions.length && contributions.every((item, index) => item === cached.inputs[index])) return cached.output;
      // One revision for the complete inventory: retiring any provider invalidates every old SDK.
      // Cache by live lease contributions; polls never rebuild source or rehash unchanged providers.
      const revision = createHash('sha256').update(JSON.stringify(contributions)).digest('hex');
      const output = contributions.map(contribution => ({ ...contribution, configuration: {
        url: `/_jini/browser-analytics?surface=${required.surface}`, revision,
      } }));
      browserCache.set(required.surface, { inputs: contributions, output });
      return output;
    },
    tracker: createTracker({ observability, productAnalytics: trackerAnalytics }, { warn }),
    // A site's "send test error" exercises the site's own providers, never Tovu's product branch.
    siteTracker: product ? createTracker({ observability: siteObservability, productAnalytics }, { warn }) : undefined,
    // Public callers own visitor proof checks; the owner's admin preference cannot veto them.
    visitorTracker: createTracker({ observability: siteObservability, productAnalytics: withProductAnalyticsGuards({ inner, consent: () => true }) }, { warn }),
    shutdownGenerations: () => generations?.shutdown?.(),
    aiTraceSink: sinks.length === 0 ? undefined : {
      ...createFanOutAiTraceSink({ sinks }),
      get capture() { return sinks.some((sink) => sink.capture === "full") ? "full" as const : "metadata" as const; },
    },
  };
}

/**
 * Selects, loads and initializes provider plugins, then composes one port per contract.
 * @param required Plugin runtime, saved-settings source, service identity and the operator's telemetry consent.
 * @param optional Initialization bound (also bounds each plugin's import + setup), warning sink.
 * @returns Ports (noop where nothing is configured) and the shared teardown. Never throws for a
 *   provider failure: that contract stays on its noop and the reason is logged.
 * @complexity O(p) settings reads plus one load and one bounded initialization per configured provider.
 */
export async function bootProviderPlugins(required: BootProviderPluginsRequired, optional: BootProviderPluginsOptional = {}): Promise<ProviderPluginPorts> {
  const release = required.release ?? processBuildRelease({});
  const warn = optional.warn ?? ((message: string) => console.warn(`[provider-plugins] ${message}`));
  const delivery = createTelemetryDeliveryMonitor({ warn });
  const testProbe = createTelemetryTestProbe({});
  const timeoutMs = optional.initializeTimeoutMs ?? 10_000;
  const slots: ProviderSlot[] = (await required.runtime.listProviderPlugins({})).flatMap(({ pluginId, providers }) =>
    providers.filter(declaration => KNOWN_CONTRACTS.has(declaration.contract)).map(declaration => ({ pluginId,
      contract: declaration.contract as ProviderContract, id: declaration.id, declaration })));
  const loaded = new Set<string>();
  const host = createPluginProviderHost({ contributions: required.runtime.providerContributions, contracts: PROVIDER_CONTRACTS }, {
    initializeTimeoutMs: timeoutMs,
    onError: ({ pluginId, phase }) => warn(`provider plugin '${pluginId}' ${phase} failed`),
  });
  const queues = new Map<string, Promise<import("@jini-ai/plugins/host").PluginProviderApplyResult>>();
  const applied = new Map<string, "now" | "restart" | "failed">();
  let tracker: Tracker | undefined;
  const initializations: import('@jini-ai/analytics/product').ProductEvent[] = [];
  function initialization({ slot, outcome, reasonClass }: { slot: ProviderSlot; outcome: 'success' | 'failure' | 'noop'; reasonClass: 'ready' | 'not_configured' | 'initialization_failed' }): void {
    slot.initializationObserved = true;
    const event = { name: 'provider_initialized', userId: `site:${required.site.siteId}`,
      properties: { contract: slot.contract, providerId: slot.id, outcome, reasonClass } };
    if (tracker) tracker.capture({ name: event.name, userId: event.userId }, { properties: event.properties });
    else initializations.push(event);
  }
  let closed = false;
  async function replaceSlot(slot: ProviderSlot, saved: ProviderPluginConfig | null): Promise<void> {
    const input = providerInputOf({ declaration: slot.declaration, saved });
    const signature = input === undefined ? undefined : JSON.stringify(input);
    if (unchangedSlot({ slot, signature })) {
      if (!slot.initializationObserved) initialization({ slot, outcome: 'noop', reasonClass: 'not_configured' });
      return;
    }
    const old = slot.lease;
    try {
      const lease = input ? await host.initialize({ contract: slot.contract, id: slot.id,
        // Host environment is only a default: a card's saved environment (Sentry) wins, and a blank one
        // is already dropped by providerInputOf. Release stays host-owned; no card declares it.
        input: { environment: required.site.environment, ...input, serviceName: required.serviceName, release,
          attribution: attributionFor({ contract: slot.contract, site: required.site }, { release }) } }, {
        factoryOptions: {
          reportTelemetry: (report: ProviderTelemetryReport) => delivery.report({ providerId: `${slot.pluginId}/${slot.id}`, report }),
          info: optional.info ?? ((message: string) => console.info(message)),
        },
      }) : undefined;
      if (input && !lease) throw new Error("ProviderUnavailable");
      slot.lease = lease;
      slot.input = signature;
    } catch (error) {
      // A removed or changed key must never keep sending through the previous lease.
      slot.lease = undefined;
      slot.input = undefined;
      throw error;
    } finally { await old?.dispose({}); }
  }
  /** Success reflects the complete plugin, since a later failure retires every earlier lease.
   * @complexity O(s * f) for s slots with f declared settings; O(s) pending observations. */
  async function applySlots({ selected, saved }: { selected: ProviderSlot[]; saved: ProviderPluginConfig | null }): Promise<void> {
    const changed: ProviderSlot[] = [];
    for (const slot of selected) {
      const input = providerInputOf({ declaration: slot.declaration, saved });
      if (!unchangedSlot({ slot, signature: input === undefined ? undefined : JSON.stringify(input) })) changed.push(slot);
      await replaceSlot(slot, saved);
    }
    for (const slot of changed) initialization({ slot, outcome: slot.lease ? 'success' : 'noop', reasonClass: slot.lease ? 'ready' : 'not_configured' });
  }
  /** Reuse a current registration, otherwise admit the configured plugin through the runtime owner.
   * @throws Error when admission fails; apply owns retiring all of the plugin's leases.
   * @complexity O(s * f + r) for selected slots, fields and registered contributions; one bounded load.
   */
  async function ensureLoaded({ pluginId, selected, saved }: { pluginId: string; selected: readonly ProviderSlot[]; saved: ProviderPluginConfig | null }, _optional = {}): Promise<void> {
    if (!selected.some(slot => providerInputOf({ declaration: slot.declaration, saved }))) return;
    if (loaded.has(pluginId) && required.runtime.providerContributions.list({}).some(snapshot => snapshot.pluginId === pluginId)) return;
    const admitted = await required.runtime.loadProviderPlugins({ pluginIds: [pluginId] }, { timeoutMs });
    if (!admitted.includes(pluginId)) throw new Error("ProviderUnavailable");
    loaded.add(pluginId);
  }
  /** Apply one saved snapshot, retiring every selected lease on failure and logging only its class.
   * @returns Live-apply timing; missing slots and closed hosts require restart; initialization/admission failures carry safe guidance.
   * @complexity O(s * f + r) slot settings/registrations plus bounded provider load and initialization.
   */
  async function apply({ pluginId }: { pluginId: string }, _optional = {}): Promise<import("@jini-ai/plugins/host").PluginProviderApplyResult> {
    if (closed) return "restart";
    const selected = slots.filter(slot => slot.pluginId === pluginId);
    if (selected.length === 0) return "restart";
    try {
      const saved = await required.config.read({ pluginId });
      const restartBrowser = selected.some(slot => browserNeedsRestart({ slot, saved }));
      await ensureLoaded({ pluginId, selected, saved });
      await applySlots({ selected, saved });
      return restartBrowser ? 'restart' : 'now';
    } catch (error) {
      for (const slot of selected) initialization({ slot, outcome: 'failure', reasonClass: 'initialization_failed' });
      const retired = selected.map(slot => { const lease = slot.lease; slot.lease = undefined; slot.input = undefined; return lease; });
      await Promise.all(retired.map(lease => lease?.dispose({})));
      // Class only: an SDK's construction error can quote the endpoint or DSN it was given.
      // Names are allowlisted too: custom Error.name values can themselves contain credentials.
      warn(`provider plugin '${pluginId}' did not initialize: ${error instanceof Error ? describeTelemetryFailure({ error }).errorClass : typeof error}`);
      return { appliesAt: "failed", ...(pluginProviderStartupGuidance({ error })
        ?? { reason: "The provider could not initialize.", action: "Check the plugin settings and installation, then save again." }) };
    }
  }
  function reapply(input: { pluginId: string }): Promise<import("@jini-ai/plugins/host").PluginProviderApplyResult> {
    const next = (queues.get(input.pluginId) ?? Promise.resolve("now" as const)).then(() => apply(input));
    const recorded = next.then(result => { applied.set(input.pluginId, typeof result === "string" ? result : result.appliesAt); return result; });
    queues.set(input.pluginId, recorded);
    return recorded;
  }
  const leases = new Map<ProviderContract, unknown[]>();
  for (const slot of slots) {
    if (slot.contract === "observability" || slot.contract === "product_analytics") delivery.register({ providerId: `${slot.pluginId}/${slot.id}` });
    leases.set(slot.contract, [...(leases.get(slot.contract) ?? []), gatedPort({ slot, contract: slot.contract, testProbe })]);
  }
  await Promise.all([...new Set(slots.map(slot => slot.pluginId))].map(pluginId => reapply({ pluginId })));
  const product = await bootProductTelemetryFromEnv({ env: optional.env, processRole: required.processRole }, { warn, ...optional.productTelemetry });
  const { shutdownGenerations, siteTracker, ...ports } = composePorts({ leases, consent: required.consent, consentRevision: required.consentRevision, site: required.site, warn, product });
  tracker = ports.tracker;
  // Boot settles before a tracker exists. Flush only through the healthy, consenting facade;
  // local diagnostics remain authoritative when analytics itself failed to initialize.
  for (const event of initializations) tracker.capture({ name: event.name, userId: event.userId }, { properties: event.properties });
  initializations.length = 0;
  let disposal: Promise<void> | undefined;
  return { ...ports, telemetryStatus: delivery.read,
    observabilityEnabled: () => slots.some(slot => slot.contract === "observability" && slot.lease?.isCurrent({}) === true),
    sendTelemetryTest: ({ error }) => testProbe.send({ tracker: siteTracker ?? ports.tracker, error, userId: `site:${required.site.siteId}` }),
    reapply, appliesAt: ({ pluginId }) => applied.get(pluginId) ?? "now",
    async dispose() {
      closed = true;
      // A concurrent fatal flush must await the same drain already started by store teardown.
      disposal ??= Promise.all(queues.values()).then(async () => {
        await Promise.all([shutdownGenerations(), host.dispose({}), product?.dispose()]);
      });
      await disposal;
    } };
}

import { isProviderSettingRequired, type PluginProviderSettingField } from "@jini-ai/plugins/host";
import type { PluginDiscoveryRecord } from "@jini-ai/plugins/host/node";

import { ProviderConfigUnreadableError, ProviderStoreUnavailableError, type ProviderConfigSource, type ProviderKeyUsage } from "./provider-config-source.js";
import { providerInputOf } from "./provider-plugins.js";
import type { Tracker } from '@jini-ai/diagnostics/observability';

/**
 * @file The one save rule for a provider plugin's settings (2026-10-25), shared by the admin settings
 * card (`routes/plugins/provider-settings.ts`) and the assistant's key card (a `provider-settings`
 * credential card an agent plugin declares, `features/custom-credentials/provider-settings-card.ts`).
 * Same declared fields, same validation, same secret re-entry rule, same `ProviderConfigSource`
 * (site first, then attached project rows), so a key saved from chat and one saved from Settings are the same row.
 */

type SavedConfig = { settings: Readonly<Record<string, string>>; secrets: Readonly<Record<string, string>> };
export type ProviderSettingsRefusal = { code: string; error: string };
type SavedProviderSettings = { saved: true; configured: boolean; appliesAt: "now" | "restart" | "failed"; message?: string } & ProviderKeyUsage;
type NextConfig = { config: SavedConfig } | { refusal: ProviderSettingsRefusal };

const INVALID = { refusal: { code: "PROVIDER_SETTINGS_INVALID", error: "values must map declared setting names to text" } };

/** The plugin's declared settings fields (all its providers, first declaration of a name wins).
 *  Undefined when the plugin is not discovered or declares none. @complexity O(p + f). */
export function declaredProviderSettingFields({ records, pluginId }: { records: readonly PluginDiscoveryRecord[]; pluginId: string }): PluginProviderSettingField[] | undefined {
  const record = records.find((candidate) => candidate.id === pluginId);
  const fields = new Map<string, PluginProviderSettingField>();
  for (const provider of record?.manifest?.contributes?.providers ?? []) for (const field of provider.settings ?? []) if (!fields.has(field.name)) fields.set(field.name, field);
  return fields.size === 0 ? undefined : [...fields.values()];
}

/** `values` as `[declared name, text]` pairs; undefined when malformed or naming an undeclared field. */
function requestValues({ values, fields }: { values: unknown; fields: ReadonlyMap<string, PluginProviderSettingField> }): [string, string][] | undefined {
  if (!values || typeof values !== "object" || Array.isArray(values)) return undefined;
  const entries = Object.entries(values as Record<string, unknown>);
  return entries.every(([name, value]) => fields.has(name) && typeof value === "string") ? (entries as [string, string][]) : undefined;
}

/** Labels of the fields `pick` selects, joined for a message. */
const labelsOf = (fields: readonly PluginProviderSettingField[], pick: (field: PluginProviderSettingField) => boolean) =>
  fields.filter(pick).map((field) => field.label).join(", ");

/**
 * Submitted values → the next saved config. A blank secret keeps the saved one, but only while every
 * public field is unchanged: an endpoint or host decides where the secret is sent, so changing one
 * with a kept secret would let an admin redirect a key they never saw to their own server. Then the
 * kept secrets must be entered again, and the save is refused with a message naming them.
 */
export function nextProviderConfig({ values, fields, current }: { values: unknown; fields: readonly PluginProviderSettingField[]; current: SavedConfig | null }): NextConfig {
  const entries = requestValues({ values, fields: new Map(fields.map((field) => [field.name, field])) });
  if (!entries) return INVALID;
  const secretNames = new Set(fields.filter((field) => field.secret).map((field) => field.name));
  const settings: Record<string, string> = { ...current?.settings };
  const entered: Record<string, string> = {};
  for (const [name, value] of entries) (secretNames.has(name) ? entered : settings)[name] = value.trim();
  const secrets: Record<string, string> = { ...current?.secrets };
  for (const [name, value] of Object.entries(entered)) if (value !== "") secrets[name] = value;
  // A blank public field means the plugin's declared default, so filling in that default is no change.
  const effective = (field: PluginProviderSettingField, value: string | undefined) => value || field.default || "";
  const changed = labelsOf(fields, (field) => !field.secret && effective(field, settings[field.name]) !== effective(field, current?.settings[field.name]));
  const kept = labelsOf(fields, (field) => !entered[field.name] && Boolean(current?.secrets[field.name]));
  if (changed && kept) return { refusal: { code: "PROVIDER_SETTINGS_SECRET_REENTRY", error: `Changing ${changed} needs ${kept} entered again.` } };
  return { config: { settings, secrets } };
}

/** The saved config a save builds on. One this machine cannot open counts as nothing saved, so the save
 *  overwrites it (the card has already asked for the settings again); any other failure surfaces. */
export async function currentProviderConfig({ config, pluginId }: { config: ProviderConfigSource; pluginId: string }): Promise<SavedConfig | null> {
  return config.read({ pluginId }).catch((error: unknown) => {
    if (error instanceof ProviderConfigUnreadableError) return null;
    throw error;
  });
}

/** Refuse the first missing requirement using effective defaults and kept secrets; no values escape.
 * @complexity O(f) time and space in declared fields. */
function requiredSettingsRefusal({ fields, config }: { fields: readonly PluginProviderSettingField[]; config: SavedConfig }, _optional = {}): ProviderSettingsRefusal | undefined {
  const values = Object.fromEntries(fields.map((field) => [field.name, (field.secret ? config.secrets[field.name] : config.settings[field.name])?.trim() || field.default || ""]));
  const missing = fields.find((field) => isProviderSettingRequired({ field, values }) && !values[field.name]);
  if (!missing) return undefined;
  return { code: "PROVIDER_SETTINGS_REQUIRED", error: `${missing.label} is required.${missing.hint ? ` ${missing.hint}` : ""}` };
}

/**
 * Validates and writes one save through `config`. Returns the refusal instead of writing when the
 * values are malformed, a required field is missing or a kept secret would follow a changed public field, and as a refusal when the
 * project store could not open this run (`ProviderStoreUnavailableError`), so both cards show why.
 * @complexity O(f) plus one read and one write of the config row.
 */
export async function saveProviderSettings({ config, pluginId, fields, values, reapply, telemetry }: {
  config: ProviderConfigSource; pluginId: string; fields: readonly PluginProviderSettingField[]; values: unknown; reapply?: (input: { pluginId: string }) => Promise<import("@jini-ai/plugins/host").PluginProviderApplyResult>;
  telemetry?: { tracker: Tracker; contracts: readonly string[]; userId: string };
}, _optional = {}): Promise<SavedProviderSettings | { refusal: ProviderSettingsRefusal }> {
  const next = nextProviderConfig({ values, fields, current: await currentProviderConfig({ config, pluginId }) });
  if ("refusal" in next) return next;
  const refusal = requiredSettingsRefusal({ fields, config: next.config });
  if (refusal) return { refusal };
  try {
    await config.write({ pluginId, config: next.config });
  } catch (error) {
    if (error instanceof ProviderStoreUnavailableError) return { refusal: { code: error.code, error: error.message } };
    throw error;
  }
  return savedProviderSettingsResult({ config, pluginId, fields, saved: next.config }, { ...(reapply ? { reapply } : {}), ...(telemetry ? { telemetry } : {}) });
}

/** Report a committed save independently from startup; both cards receive the same safe guidance.
 * @returns Save status and safe startup guidance. @complexity O(c + f) contracts/fields plus usage/reapply I/O.
 */
async function savedProviderSettingsResult({ config, pluginId, fields, saved }: {
  config: ProviderConfigSource; pluginId: string; fields: readonly PluginProviderSettingField[]; saved: SavedConfig;
}, { reapply, telemetry }: Pick<Parameters<typeof saveProviderSettings>[0], "reapply" | "telemetry"> = {}): Promise<SavedProviderSettings> {
  const usage = await config.usage({ pluginId });
  const applied = reapply ? await reapply({ pluginId }) : "restart";
  const appliesAt = typeof applied === "string" ? applied : applied.appliesAt;
  const message = typeof applied === "string" ? undefined : `Saved, but the provider could not start. ${applied.reason} ${applied.action}`;
  if (telemetry) for (const contract of new Set(telemetry.contracts)) telemetry.tracker.capture({ name: 'provider_configured', userId: telemetry.userId }, { properties: { contract, pluginId, action: 'save' } });
  const configured = usage.usedByThisSite && providerInputOf({ declaration: { contract: "", id: pluginId, contractVersion: 1, settings: fields }, saved }) !== undefined;
  return { saved: true as const, configured, ...usage, appliesAt, ...(message ? { message } : {}) };
}

/** What the assistant may know about a provider plugin's settings: presence only, never a value. */
export interface ProviderSettingsStatus extends ProviderKeyUsage {
  readonly configured: boolean;
  readonly store: ProviderConfigSource["scope"];
  readonly appliesAt: "now" | "restart" | "failed";
  /** Labels of required fields still without a value (a declared default counts as a value). */
  readonly missing: readonly string[];
  readonly unreadable?: true;
}

/**
 * Configured means boot would start the provider: every required declared field has a value
 * (`providerInputOf`, the boot rule). Reads effective settings to validate header alternatives; returns labels and presence only.
 * @complexity O(f) plus one config read.
 */
export async function providerSettingsStatus({ config, pluginId, fields }: { config: ProviderConfigSource; pluginId: string; fields: readonly PluginProviderSettingField[] }, _optional = {}): Promise<ProviderSettingsStatus> {
  const view = await config.readSettings({ pluginId });
  const saved = view && !view.unreadable ? await currentProviderConfig({ config, pluginId }) : null;
  // Nothing saved still counts declared defaults, so `missing` names only what the person must enter.
  const input = providerInputOf({ declaration: { contract: "", id: pluginId, contractVersion: 1, settings: fields.map(({ requiredWhen: _when, ...field }) => ({ ...field, required: false })) }, saved: saved ?? { settings: {}, secrets: {} } }) ?? {};
  const missing = fields.filter((field) => isProviderSettingRequired({ field, values: input }) && !input[field.name]).map((field) => field.label);
  const usage = await config.usage({ pluginId });
  return { configured: missing.length === 0 && saved !== null && usage.usedByThisSite, ...usage, appliesAt: "now", missing, ...(view?.unreadable ? { unreadable: true as const } : {}) };
}

/**
 * The assistant key card's host ports (`features/custom-credentials/provider-settings-card.ts`), bound
 * to this module's rule and the same `ProviderConfigSource` the admin route uses.
 * @complexity O(p + f) per call: one discovery read plus one config read/write.
 */
export function bindProviderSettingsCardPorts({ config, discoverPlugins, reapply, tracker, userId }: { config: ProviderConfigSource; discoverPlugins: () => Promise<readonly PluginDiscoveryRecord[]>; reapply?: (input: { pluginId: string }) => Promise<import("@jini-ai/plugins/host").PluginProviderApplyResult>; tracker?: Tracker; userId?: string }) {
  const fields = async ({ pluginId }: { pluginId: string }) => declaredProviderSettingFields({ records: await discoverPlugins(), pluginId });
  return {
    fields,
    usage: ({ pluginId }: { pluginId: string }) => config.usage({ pluginId }),
    readSettings: async ({ pluginId }: { pluginId: string }) => {
      const view = await config.readSettings({ pluginId });
      return view && !view.unreadable ? view : null;
    },
    save: async ({ pluginId, values }: { pluginId: string; values: Readonly<Record<string, string>> }) => {
      const records = await discoverPlugins();
      const declared = declaredProviderSettingFields({ records, pluginId });
      if (!declared) return { refusal: "This plugin declares no provider settings." };
      const contracts = (records.find(record => record.id === pluginId)?.manifest?.contributes?.providers ?? []).map(provider => provider.contract);
      const saved = await saveProviderSettings({ config, pluginId, fields: declared, values, reapply,
        ...(tracker && userId ? { telemetry: { tracker, userId, contracts } } : {}) });
      return "refusal" in saved ? { refusal: saved.refusal.error } : { ...saved };
    },
  };
}

/**
 * `provider_status` rows: every discovered plugin that declares provider settings, with its enabled
 * flag and quarantine reason (activation record) and `providerSettingsStatus`. Presence only.
 * @complexity O(p) plugins, one activation read and one settings read per provider plugin.
 */
export async function listProviderStatuses({ config, discoverPlugins, activation, appliesAt }: {
  appliesAt?: (input: { pluginId: string }) => "now" | "restart" | "failed";
  config: ProviderConfigSource; discoverPlugins: () => Promise<readonly PluginDiscoveryRecord[]>;
  activation: (required: { pluginId: string }) => Promise<{ enabled: boolean; quarantineReason?: string } | null>;
}) {
  const records = await discoverPlugins();
  const rows = [];
  for (const { id: pluginId } of records) {
    const fields = declaredProviderSettingFields({ records, pluginId });
    if (!fields) continue;
    const state = await activation({ pluginId });
    rows.push({ pluginId, fields: fields.map(field => ({ ...field, required: field.required === true })), settingsCard: { tool: "credential_save" as const, input: { kind: "provider-settings" as const, target: pluginId } }, enabled: state?.enabled === true, ...(await providerSettingsStatus({ config, pluginId, fields })),
      ...(appliesAt ? { appliesAt: appliesAt({ pluginId }) } : {}),
      ...(state?.quarantineReason ? { quarantine: state.quarantineReason } : {}) });
  }
  return rows;
}

/** Shared local-host policy and registered source discovery; never boot or repair another site. */
import fs from "node:fs";
import path from "node:path";
import { resolveRuntimeMode } from "#src/contracts/core/runtime-mode";
import type { SitesWorkspace } from "#src/platform/site-dir/sites-home";
import { resolveSiteDatabasePaths } from "#src/platform/site-dir/site-databases";
import { readSiteMetaJson } from "#src/features/webhooks/site-key-sources";
import { bootLocalOwnerSignIn } from "../boot/local-owner-signin.js";
import { detectDeploymentSignals } from "../boot/boot-readiness-warnings.js";

import type { RegisteredSiteSource } from '#src/assistant/host-contracts';
export type { RegisteredSiteSource } from '#src/assistant/host-contracts';
type RegisteredEntry = RegisteredSiteSource & { registeredId: string };

/** Recognize desktop/local hosts without deployment signals. Never reads a site registry.
 * @throws Propagates runtime-mode configuration errors. @complexity O(1) environment checks.
 */
export function isLocalTovuHost(_required: Record<string, never>, _options = {}): boolean {
  return bootLocalOwnerSignIn.enabled ||
    (resolveRuntimeMode() === "local" && detectDeploymentSignals({ env: process.env }).length === 0);
}

/** Registry IDs are discovery, never a request-supplied path. Exclude both sides of an identity collision.
 * O(n) small metadata/filesystem probes and maps for n registered folders; no source databases open.
 */
export function registeredSources({ workspace, targetSiteId, targetSiteDir, targetFile }: {
  workspace: SitesWorkspace; targetSiteId: string; targetSiteDir: string; targetFile: string | undefined;
}, _options = {}): RegisteredSiteSource[] {
  const entries = readRegisteredEntries({ workspace });
  const identities = new Map<string, number>();
  const folders = new Map<string, number>();
  for (const source of entries) {
    identities.set(source.siteId, (identities.get(source.siteId) ?? 0) + 1);
    folders.set(source.dir, (folders.get(source.dir) ?? 0) + 1);
  }
  const currentDir = fs.realpathSync(targetSiteDir);
  return entries.filter(source => {
    if (source.siteId !== source.registeredId || source.siteId === targetSiteId || source.dir === currentDir ||
      identities.get(source.siteId) !== 1 || folders.get(source.dir) !== 1) return false;
    return hasSeparateDatabase({ source, workspace, targetFile });
  });
}

function readRegisteredEntries({ workspace }: { workspace: SitesWorkspace }, _options = {}): RegisteredEntry[] {
  const entries: RegisteredEntry[] = [];
  for (const entry of workspace.registry({}).list({})) {
    try {
      const dir = fs.realpathSync(entry.path);
      if (!fs.statSync(dir).isDirectory() || dir.split(path.sep).includes("site-trash")) continue;
      const meta = readSiteMetaJson(dir);
      if (typeof meta?.siteId !== "string" || !meta.siteId) continue;
      entries.push({ siteId: meta.siteId, name: entry.name, dir, registeredId: entry.id });
    } catch { /* Missing/unreadable folders are unavailable choices, never repaired here. */ }
  }
  return entries;
}

function hasSeparateDatabase({ source, workspace, targetFile }: {
  source: RegisteredSiteSource; workspace: SitesWorkspace; targetFile: string | undefined;
}, _options = {}): boolean {
  try {
    const sourceFile = resolveSiteDatabasePaths({ dir: source.dir }, { workspace, reserveIdentity: false }).contentDbPath;
    if (!targetFile || targetFile === ":memory:" || !fs.existsSync(sourceFile)) return true;
    // Folder identities alone cannot detect a symlink/hardlink to the live target database.
    const a = fs.statSync(sourceFile), b = fs.statSync(targetFile);
    return a.dev !== b.dev || a.ino !== b.ino;
  } catch { return false; }
}

import { createTrashScheduler } from "#src/features/trash/scheduler.node";
import { startThemeWatcher } from "#src/features/theme/theme-watcher";
import { startPostGoLiveSweep } from "#src/features/post/go-live";
import type { Express } from "express";

import { startOutboxDrainer, type OutboxDrainer } from "#src/contracts/core/events/index";
import { startTrashSweeper, type TrashSweeper } from "@jini-ai/cms/trash";
import { createApp } from "./app.js";
import { createServingFormPullTrigger } from "./form-pull-triggers.js";
import { startServingWebhookDeliveryWorker, type WebhookDeliveryWorker } from "./webhook-delivery-worker.js";
import { startDomainBindingSweeper, type DomainBindingSweeper } from "./domain-binding-sweeper.js";
import { startSiteSearchMaintenance, type SiteSearchMaintenance } from "./modules/site-search.js";

/**
 * @file `createApp` plus the site-serving process's background loops — the outbox drainer
 * (2026-09-14), Trash auto-purge sweeper (2026-09-20), theme watcher, assistant-run recovery and the
 * site-search maintenance loop (2026-10-21) — as one step.
 *
 * Callers: the two site-serving boot paths and nothing else. `src/index.ts` serves the dev API and the
 * container image (`Dockerfile` CMD). `cli/commands/serve.ts` is `tovu serve`, which the desktop app
 * spawns per site window. Pinned by `server/__tests__/unit/serving-app-boot-wiring.unit.test.ts`.
 *
 * Why not inside `createApp`: `createApp` also runs where no site is served and nothing may drain.
 * That covers the static exporter (`routeDeps.createSiteApp()`, including inside the agent daemon)
 * and `app.ts`'s eager module-level `app`, which every importer of `app.ts` builds. The agent daemon
 * itself only enqueues (`agent-daemon-deps.ts`).
 * Assistant recovery has the same ownership rule: an export app built by a live chat run is not
 * a web restart. Sweeping during its route registration canceled that very run's transcript while
 * its daemon still held the conversation (2026-10-05); only a serving boot may probe and recover.
 *
 * Order is the point. `createApp` subscribes every handler (SEO sitemap invalidation, forms notify,
 * webhook fan-out, newsletter batches, redirect hits) onto `routeDeps.bus` synchronously, and only
 * then does the drainer start. A drainer started first could mark rows delivered with no handlers
 * attached, the same loss this fix closes in the daemon.
 *
 * The post go-live sweep (2026-10-21, `features/post/go-live.ts`) follows the drainer's rules for the
 * same reason: it enqueues `entry.published` for scheduled posts whose time has come, so it starts
 * after `createApp` and only here. It runs only when `routeDeps.postGoLiveCandidates` is bound.
 *
 * The automatic form pull (`form-pull-triggers.ts`) follows the same two rules: it imports
 * submissions and enqueues their events, so its startup pull runs only after `createApp` attached
 * the subscribers, and only a serving process pulls — at startup and on owner/admin sign-in.
 *
 * The webhook delivery loop (`webhook-delivery-worker.ts`) sends what `createApp`'s integrations
 * module enqueued, so it too runs only here: a POST of a site's data from a process nobody serves
 * is the drainer's loss in reverse.
 *
 * The due-bindings DNS sweep (`domain-binding-sweeper.ts`, 2026-10-21) re-checks `domain_binding`
 * rows on their backoff schedule; same rule — only a serving process writes a site's tracking state.
 * It runs only when the root pre-bound `verifyDueDomainBindings` (the hermetic root does not).
 */

/**
 * Builds the site app and starts its background loops.
 *
 * @param routeDeps the serving process's composed deps; its `outbox`/`bus`/`clock` feed the
 *   drainer, and its pre-bound `sweepTrash` feeds the sweeper.
 * @param optional.outboxDrainIntervalMs idle wait between drains (default: the drainer's own).
 * @param optional.trashSweepIntervalMs idle wait between sweeps (default: the sweeper's own hour).
 * @param optional.webhookDeliveryIntervalMs idle wait between webhook delivery ticks (default: the worker's own 15 s).
 * @param optional.domainBindingSweepIntervalMs idle wait between due-bindings DNS sweeps (default: the sweeper's own minute).
 * @returns the Express app, background handles (stop all at shutdown; `formPullTrigger.stop` and
 *   `siteSearchMaintenance.stop` wait for a running pass), and
 *   `bootWork`: the background passes `createApp` started and returned before they finished
 *   (`CreateAppOptions.onBootWork`). A caller that closes the store awaits these first.
 * @complexity O(1) beyond `createApp`.
 */
export function createServingApp(
  routeDeps: NonNullable<Parameters<typeof createApp>[0]>,
  optional: { outboxDrainIntervalMs?: number; trashSweepIntervalMs?: number; webhookDeliveryIntervalMs?: number; domainBindingSweepIntervalMs?: number } = {}
): { app: Express; outboxDrainer: OutboxDrainer; trashSweeper: TrashSweeper; themeWatcher: ReturnType<typeof startThemeWatcher>; formPullTrigger: { stop(): Promise<void> }; postGoLiveSweep: { stop(): Promise<void> }; webhookDeliveryWorker: WebhookDeliveryWorker; domainBindingSweeper: DomainBindingSweeper; siteSearchMaintenance: SiteSearchMaintenance; bootWork: Promise<void>[] } {
  const bootWork: Promise<void>[] = [];
  const formPull = createServingFormPullTrigger({ autoPull: routeDeps.formSubmissionsAutoPull, workspaceId: routeDeps.workspaceId });
  const app = createApp(routeDeps, { recoverAssistantChatRuns: true, onBootWork: (work) => bootWork.push(work), onAdminSignIn: formPull.signIn });
  const outboxDrainer = startOutboxDrainer(
    { outbox: routeDeps.outbox, bus: routeDeps.bus, clock: routeDeps.clock },
    { intervalMs: optional.outboxDrainIntervalMs, tracker: routeDeps.tracker }
  );
  // Unlike the drainer, the sweeper has no ordering dependency on `createApp` — it reads and writes
  // only `trashed_items` and the domain markers, and publishes nothing onto the bus. It starts here
  // anyway, and only here, for the other half of the drainer's reason: this is the one process pair
  // that serves a site. A sweep in the exporter or the agent daemon would hard-delete a site's rows
  // from a process nobody is watching, on a schedule nobody set.
  const trashSweeper = startTrashSweeper(
    {
      sweep: routeDeps.sweepTrash, clock: { nowMs: () => Date.parse(routeDeps.clock.nowIso()) },
      scheduler: createTrashScheduler({}), leaseOwner: `trash-sweeper-${Math.random().toString(36).slice(2, 10)}`
    },
    {
      intervalMs: optional.trashSweepIntervalMs,
      onError: ({ error }) => console.error("[trash-sweeper] sweep failed; retrying after the idle interval", error)
    }
  );
  const candidates = routeDeps.postGoLiveCandidates;
  const postGoLiveSweep = candidates
    ? startPostGoLiveSweep({ deps: { repo: candidates, outbox: routeDeps.outbox, clock: routeDeps.clock }, workspaceId: routeDeps.workspaceId })
    : { stop: async () => {} };
  const themeWatcher = startThemeWatcher({ themes: routeDeps.themes, themesDir: routeDeps.themesDir });
  const webhookDeliveryWorker = startServingWebhookDeliveryWorker(
    { deps: routeDeps },
    optional.webhookDeliveryIntervalMs === undefined ? {} : { intervalMs: optional.webhookDeliveryIntervalMs }
  );
  const domainBindingSweeper = startDomainBindingSweeper(
    { sweep: routeDeps.verifyDueDomainBindings },
    optional.domainBindingSweepIntervalMs === undefined ? {} : { intervalMs: optional.domainBindingSweepIntervalMs }
  );
  // After `createApp`: the pulled submissions' events need their subscribers attached.
  formPull.pullNow();
  // Site search upkeep (reconcile + resumable backfill, and the boot rebuild for a site with no index
  // yet). Serving-only for the sweeper's reason: it writes to search backends on a schedule, which only
  // the process serving the site may do. A no-op handle when the composition has no search runtime.
  const siteSearchMaintenance = startSiteSearchMaintenance({ runtime: routeDeps.siteSearch });
  return { app, outboxDrainer, trashSweeper, themeWatcher, formPullTrigger: { stop: formPull.stop }, postGoLiveSweep, webhookDeliveryWorker, domainBindingSweeper, siteSearchMaintenance, bootWork };
}

/** @file Composition for `@jini-ai/cookie-consent`: the one engine switch and the server analytics gate.
 * TODO(P4): the old engine goes, `selectCookieConsent` always returns the deps and the env switch is deleted. */
import type { Request } from 'express';
import type { RegionResolver } from '@jini-ai/cookie-consent';
import type { LoadPluginContributions } from '#src/features/agent-plugins/lifecycle';
import { loadSiteRegionResolvers } from '#src/features/consent/region-plugins';
import type { RouteDeps } from '#src/server/routes/types';
import { readSiteAnalyticsProof, siteReceiptAllowsAnalytics, type SiteCookieConsentDeps } from '../../inbound/public-http/middleware/site-cookie-consent.js';

/** Region readers are re-read at most once a minute, so switching a host plugin on or off applies
 * without a restart and a page view never waits on the plugin directory. */
const REGION_TTL_MS = 60_000;

/**
 * THE switch. `TOVU_CONSENT_ENGINE=cookie-consent` selects the new engine; anything else keeps the old
 * one. `TOVU_CONSENT_INGRESS` names the host plugin in front of this server (e.g. `cloudflare`); only
 * its region readers are trusted. `TOVU_CONSENT_REGION_HEADER` (older setting) still works as one
 * more trusted header. Neither set = strict for everyone (Fly, Electron).
 * @complexity O(1); region readers load lazily.
 */
export function selectCookieConsent(
  { workspaceId, loadContributions }: { workspaceId: string; loadContributions: LoadPluginContributions },
  { env = process.env, nowMs = Date.now }: { env?: NodeJS.ProcessEnv; nowMs?: () => number } = {},
): SiteCookieConsentDeps | undefined {
  if (env.TOVU_CONSENT_ENGINE?.trim() !== 'cookie-consent') return undefined;
  const ingress = env.TOVU_CONSENT_INGRESS?.trim() || undefined;
  const legacyHeader = env.TOVU_CONSENT_REGION_HEADER?.trim() || undefined;
  let cached: { at: number; value: Promise<readonly RegionResolver[]> } | undefined;
  return {
    regionResolvers: () => {
      if (cached && nowMs() - cached.at < REGION_TTL_MS) return cached.value;
      cached = { at: nowMs(), value: loadSiteRegionResolvers({ workspaceId, loadContributions }, { ingress, legacyHeader }) };
      return cached.value;
    },
  };
}

/** Replace the visitor analytics proof/delivery ports with the cookie-consent reading of the same rule:
 * a server receipt for an analytics grant under the current policy. Excluded visitors are never captured.
 * @complexity O(cookie header) plus one policy read per call. */
export function bindCookieConsentAnalyticsGate(
  { deps }: { deps: RouteDeps },
  { isExcluded = async () => false }: { isExcluded?: (required: { request: Request }) => Promise<boolean> } = {},
): void {
  deps.visitorAnalyticsProof = async ({ request }) => {
    try { return await isExcluded({ request }) ? undefined : await readSiteAnalyticsProof({ deps, req: request }); }
    catch { return undefined; }
  };
  // Rechecked at delivery: a withdrawn (retired) or forged receipt, or one from before the latest
  // publication, no longer counts.
  deps.visitorAnalyticsDeliveryAllowed = async ({ proof }) => {
    try { return await siteReceiptAllowsAnalytics({ deps, proof }); }
    catch { return false; }
  };
}

