import { existsSync } from "node:fs";
import { join } from "node:path";

import type { ContentDatabase } from "#src/platform/db/content-database.generated";
import type { ContentKernel } from "#src/platform/db/content-kernel";
import { openSqliteFileKernel } from "#src/platform/db/kernel/drivers/sqlite";
import { discardVaultCredentialsNotOpening, resealVaultCredentialsOpeningUnder } from "#src/platform/db/vault-credential-recovery";
import { STORAGE_SECRET_FILENAME } from "#src/platform/site-dir/layout";
import { FixedSiteKeyKeyring } from "#src/features/webhooks/keyring.env";
import { AesGcmSecretSealer } from "#src/features/webhooks/secret-sealer.aesgcm";
import { installSiteKey, mintSiteKeyHex } from "#src/features/webhooks/site-key-ensure";
import { readSealedConnectionString, writeSealedConnectionString } from "./storage-secret.js";
import { SqlSecretsVaultRepo, type SecretsVaultDatabase } from "@jini-ai/db/secrets-vault";
import { buildVaultAad, SecretsVaultService, VAULT_KINDS, VaultError, type VaultMetaParsers, type VaultRecord } from "@jini-ai/platform/secrets/credential-sets";
import type { SecretSealerPort } from "@jini-ai/platform/secrets";
import type { StorageKernel } from "#src/platform/db/kernel/port";
import { inventoryVaultCredentials } from "#src/platform/db/vault-credential-inventory";
import { legacyVaultAad } from "./vault-legacy-codecs.js";
import { createTovuVaultKinds } from "#src/platform/secrets/vault-kinds";
import { legacyContext, loadSiteVaultKinds, recoverLegacyVaultRecord } from "./vault-boot.js";

/**
 * @file What the admin Site key route's last-resort recovery ("Paste your old token", "Start
 * fresh") needs beyond HTTP, built here because the route may not import the key writer
 * (`site-key-ensure.ts`) or the storage kernel's sealed-row code. `app.ts` hands
 * {@link siteKeyRecovery} to `registerAdminSiteKeyRoutes`.
 *
 * Every check runs against a candidate key held only in memory (`FixedSiteKeyKeyring`), so nothing
 * is written until the caller decides. The store checked is the running site's own kernel when
 * there is one, otherwise its `content.db` opened (and closed) here.
 */

/** Whether `.storage-secret.json` (a Postgres site's sealed connection string) opens under a key. */
export type StorageSecretCheck = "absent" | "opens" | "locked";

export interface SiteKeyKeyCheck {
  /** Sealed credential values in the site's database. */
  readonly sealed: number;
  /** How many of them open under the checked key. */
  readonly opens: number;
  readonly storageSecret: StorageSecretCheck;
  readonly metadataOnly: number;
  readonly legacy: number;
}

export interface SiteKeyRecoveryInput {
  readonly siteDir: string;
  /** The running site's own store, when it has one open. */
  readonly contentKernel?: ContentKernel;
  readonly hex: string;
}

/** Counts sealed values (and the storage secret) that open under `input.hex`.
 *  @complexity {@link inventoryVaultCredentials}'s cost plus one small file read. */
async function checkKey(input: SiteKeyRecoveryInput): Promise<SiteKeyKeyCheck> {
  const sealer = new AesGcmSecretSealer(new FixedSiteKeyKeyring(input.hex));
  const keyring = new FixedSiteKeyKeyring(input.hex);
  const counts = await withSiteKernel(input, async kernel => {
    const inventory = await inventoryVaultCredentials({ kernel, sealer, keyring, hasSiteKeySource: () => true, aadFor: recoveryAad });
    return { sealed: inventory.totals.sealed, opens: inventory.totals.opens, metadataOnly: inventory.metadataOnly.length,
      legacy: inventory.legacySealed };
  }, { sealed: 0, opens: 0, metadataOnly: 0, legacy: 0 });
  return { ...counts, storageSecret: await checkStorageSecret(input.siteDir, sealer) };
}

/** Removes every sealed value that does not open under `input.hex`. The caller takes a restore point
 *  first. @complexity {@link discardVaultCredentialsNotOpening}'s cost. */
async function discardNotOpening(input: SiteKeyRecoveryInput): Promise<{ discarded: number; kept: number }> {
  const sealer = new AesGcmSecretSealer(new FixedSiteKeyKeyring(input.hex));
  return withSiteKernel(input, (kernel) => discardVaultCredentialsNotOpening({ kernel, sealer, aadFor: recoveryAad }), { discarded: 0, kept: 0 });
}

export interface SiteKeyResealInput extends SiteKeyRecoveryInput {
  /** The key currently in place, which values saved since the switch were sealed under. */
  readonly previousHex: string;
}

/** Moves every sealed value (and `.storage-secret.json`) that opens under `previousHex` but not
 *  under `hex` onto `hex`, so switching to `hex` strands nothing. The caller takes a restore point
 *  first. @complexity {@link resealVaultCredentialsOpeningUnder}'s cost plus one small file rewrite. */
async function resealFrom(input: SiteKeyResealInput): Promise<{ resealed: number; unreadable: number }> {
  const keyring = new FixedSiteKeyKeyring(input.hex);
  const sealer = new AesGcmSecretSealer(keyring);
  const previous = new AesGcmSecretSealer(new FixedSiteKeyKeyring(input.previousHex));
  const key = await keyring.activeKey();
  const counts = await withSiteKernel(
    input,
    (kernel) => resealVaultCredentialsOpeningUnder({ kernel, sealer, key, previous, aadFor: recoveryAad,
      resealRecord: ({ record, previous }) => resealRecord({ kernel, siteDir: input.siteDir, keyring, sealer, record, previous }),
    }),
    { resealed: 0, unreadable: 0 }
  );
  if ((await checkStorageSecret(input.siteDir, sealer)) !== "locked") return counts;
  let connectionString: string;
  try {
    connectionString = await readSealedConnectionString({ siteDir: input.siteDir }, { sealer: previous });
  } catch {
    return { ...counts, unreadable: counts.unreadable + 1 };
  }
  await writeSealedConnectionString({ siteDir: input.siteDir, connectionString }, { sealer, keyring });
  return { ...counts, resealed: counts.resealed + 1 };
}

async function checkStorageSecret(siteDir: string, sealer: AesGcmSecretSealer): Promise<StorageSecretCheck> {
  if (!existsSync(join(siteDir, STORAGE_SECRET_FILENAME))) return "absent";
  try {
    await readSealedConnectionString({ siteDir }, { sealer });
    return "opens";
  } catch {
    return "locked";
  }
}

/** Runs `use` on the site's open store, or on its `content.db` opened for this call; `empty` when
 *  the site has no database yet. */
async function withSiteKernel<R>(input: SiteKeyRecoveryInput, use: (kernel: ContentKernel) => Promise<R>, empty: R): Promise<R> {
  if (input.contentKernel !== undefined) return use(input.contentKernel);
  const dbPath = resolveSiteDatabasePaths({ dir: input.siteDir }).contentDbPath;
  if (!existsSync(dbPath)) return empty;
  const kernel = openSqliteFileKernel<ContentDatabase>(dbPath);
  try {
    return await use(kernel);
  } finally {
    await kernel.close();
  }
}

/** The recovery half of the route's `SiteKeyServices`. */
export const siteKeyRecovery = { checkKey, discardNotOpening, resealFrom, installSiteKey, mintSiteKeyHex };

/** Check the pinned historical context, otherwise call Jini's current AAD builder. Never guess. */
export function recoveryAad({ record }: { record: VaultRecord }, _options = {}): string | undefined {
  // Includes the pinned former custom-kind vault marker; recovery shares boot's exact codec.
  const legacy = legacyContext({ record });
  return legacy ? legacyVaultAad({ record, legacy }) : buildVaultAad(record);
}

/** Legacy recovery reuses boot normalization. Ordinary rotation calls Jini's lifecycle with a
 * source opener and target sealer, removing the safe failure flag once the payload is recovered.
 * The route has already authorized site-key management; this service is constrained to that row.
 */
async function resealRecord(input: {
  kernel: ContentKernel; siteDir: string; keyring: FixedSiteKeyKeyring; sealer: AesGcmSecretSealer;
  record: VaultRecord; previous: Pick<SecretSealerPort, "open">;
}, _options = {}): Promise<void> {
  const clock = { nowMs: () => Date.now() };
  if (input.record.meta.legacyAad !== undefined) {
    const registry = await loadSiteVaultKinds({ workspaceId: input.record.workspaceId, siteDir: input.siteDir });
    await recoverLegacyVaultRecord({ input: { ...input, kernel: input.kernel as unknown as StorageKernel<unknown>,
      workspaceId: input.record.workspaceId, siteId: input.record.workspaceId, clock, registry },
      record: input.record, previous: input.previous });
    return;
  }
  const parsers = Object.fromEntries([...VAULT_KINDS, "custom" as const].map(kind => [kind, ({ meta, provider }: { meta: unknown; provider?: string | null | undefined }) => {
    const parsed = recoveryKinds.metaParsers[kind]({ meta, provider });
    const { normalization: _flag, ...plain } = parsed;
    return plain;
  }])) as VaultMetaParsers;
  const service = new SecretsVaultService({
    repo: new SqlSecretsVaultRepo({ kernel: input.kernel as unknown as StorageKernel<SecretsVaultDatabase> }),
    keyring: input.keyring, metaParsers: parsers, now: () => new Date(clock.nowMs()).toISOString(),
    newId: () => { throw new VaultError({ code: "invalid-record" }); },
    authorize: async ({ context }) => {
      if (buildVaultAad({ ...context, id: input.record.id, binding: "binding" in context ? context.binding : input.record.binding }) !== buildVaultAad(input.record)) throw new VaultError({ code: "context" });
    },
    sealer: { open: (required, options) => input.previous.open(required, options), seal: async required => {
      const sealed = await input.sealer.seal({ plaintext: required.plaintext, key: required.key, aad: required.aad });
      if (await input.sealer.open({ sealed }, { aad: required.aad }) !== required.plaintext) throw new VaultError({ code: "invalid-record" });
      return sealed;
    } },
  });
  await service.rotate({ ...input.record, expectedRevision: input.record.revision });
}

// Ordinary rotation needs only the established safe metadata registration, not plugin discovery.
const recoveryKinds = createTovuVaultKinds({ policy: {
  validateMeta: ({ meta }) => meta, legacyPublishCredential: () => undefined, tokenField: () => undefined,
} });

import type { Tracker } from "@jini-ai/diagnostics/observability";
import type { ToolAttemptAuditSink } from "@jini-ai/daemon/tool-audit";

/**
 * @file `assistant_tool_used` product events (provider wave 2, 2026-10-25), read off the tool-attempt
 * audit trail: every assistant tool call (admin chat, daemon, site visitor) already passes through
 * this one sink, so decorating it covers them all without touching any executor. One event per
 * settled attempt (the `requested` row is skipped), carrying the tool id and its outcome phase only —
 * never input, output or error text. A tool the model invented is labelled `unknown`, since its
 * name is model text.
 */

/** A commit-aware sink keeps audit failure containment while exposing actual insertion evidence. */
export interface CommittedToolAttemptAuditSink extends ToolAttemptAuditSink {
  appendCommitted(required: Parameters<ToolAttemptAuditSink["append"]>[0], optional?: Parameters<ToolAttemptAuditSink["append"]>[1]): Promise<boolean>;
}

/** Capture committed settled attempts through the consent-gated product port. A sink without
 * insertion evidence retains audit behavior but cannot authorize a product event.
 * @returns The original audit failure behavior plus commit evidence for request-scoped observers.
 * @example withToolUseEvents({ sink: persistedAudit, tracker }, {});
 * @complexity O(1) time and space per attempt beyond the wrapped sink.
 */
export function withToolUseEvents({ sink, tracker }: { sink: ToolAttemptAuditSink & Partial<CommittedToolAttemptAuditSink>; tracker: Tracker }, _optional = {}): CommittedToolAttemptAuditSink {
  async function appendCommitted(required: Parameters<ToolAttemptAuditSink["append"]>[0], optional?: Parameters<ToolAttemptAuditSink["append"]>[1]): Promise<boolean> {
    const committed = sink.appendCommitted ? await sink.appendCommitted(required, optional) : (await sink.append(required, optional), false);
    // Public attempts need a request-scoped visitor decision; operator consent cannot authorize them.
    if (!committed || required.phase === "requested" || required.principalId === "anonymous-visitor") return committed;
    const toolId = required.phase === "unknown-tool" ? "unknown" : required.toolId;
    tracker.capture({ name: "assistant_tool_used", userId: required.principalId }, { properties: {
      toolId, outcome: required.phase, chatSurface: "admin", attemptId: required.attemptId,
      eventId: `assistant-tool:${required.attemptId}`,
    } });
    return committed;
  }
  return { append: async (required, optional) => { await appendCommitted(required, optional); }, appendCommitted };
}

import { homedir } from "node:os";
import { join } from "node:path";
import { resolveRuntimeMode } from "#src/contracts/core/runtime-mode";
import { resolveProductRoot } from "#src/platform/site-dir/product-root";
import { EnvOrFileKeyring } from "#src/features/webhooks/keyring.env";
import { resolveSiteKeyId, siteKeySources } from "#src/features/webhooks/site-key-sources";
import { createTovuAgentPluginLifecycle, type LoadPluginContributions } from "#src/features/agent-plugins/lifecycle";
import { resolveAgentPluginLayout } from "#src/features/agent-plugins/layout";
import { loadBundledDeployTargetRegistry, loadDeployTargetRegistry } from "#src/features/deployments/deploy-targets/registry";
import { sql } from "kysely";
import type { Clock } from "@jini-ai/core/primitives";
import { SqlSecretsVaultRepo, type SecretsVaultDatabase } from "@jini-ai/db/secrets-vault";
import { AesGcmSecretSealer, credentialTokenHint, type KeyringPort, type SiteKeyHandle, type SecretSealerPort } from "@jini-ai/platform/secrets";
import { buildVaultAad, VaultError, VAULT_KINDS, type VaultKind, type VaultMeta, type VaultRecord, type VaultRepoPort } from "@jini-ai/platform/secrets/credential-sets";
import { acquireOperationLock, releaseOperationLock } from "#src/contracts/core/operation-lock";
import { assertCredentialFreeField } from "#src/contracts/core/credential-token";
import type { StorageKernel } from "#src/platform/db/kernel/port";
import { legacyTargetProvider, legacyVaultAad, normalizeLegacyVaultPayload, type VaultLegacyContext } from "./vault-legacy-codecs.js";
import { createTovuVaultKinds } from "#src/platform/secrets/vault-kinds";

type BlockReason = "missing-key" | "unopenable" | "invalid-meta" | "catalog-unavailable" | "conflict";
export interface VaultKindCoverage {
  rows: number; envelopes: number; attempted: number; succeeded: number; dropped: number; blocked: number;
  legacyRemaining: number; unopenable: number;
}
export interface VaultBootReport {
  green: boolean;
  kinds: Record<VaultKind, VaultKindCoverage>;
  /** Safe identity/reason only; errors, plaintext and ciphertext never enter diagnostics. */
  flagged: { id: string; kind: VaultKind; reason: BlockReason }[];
}
export interface VaultBootInput {
  kernel: StorageKernel<unknown>; siteId: string; workspaceId: string; clock: Clock;
  keyring: KeyringPort; sealer: SecretSealerPort; registry: ReturnType<typeof createTovuVaultKinds>;
}
class RowBlocked extends Error {
  constructor(readonly reason: BlockReason) { super(`vault normalization: ${reason}`); }
}

/** Original context is host metadata, structurally checked before calling an old codec. */
export function legacyContext({ record }: { record: VaultRecord }): VaultLegacyContext | null {
  if (record.meta.legacyAad === undefined) return null;
  const value = legacyMetadataObject({ value: record.meta.legacyAad });
  const migration = legacyMetadataObject({ value: record.meta.migration });
  if (migration.mappedId !== record.id || !hasLegacyIdentityFields({ value }) ||
    ![value.principalId, value.provider, value.serverId].every(field => field === null || typeof field === "string") ||
    ["table", "workspaceId", "id", "principalId", "provider", "serverId", "aadVersion"].some(key => migration[key] !== value[key])) {
    throw new RowBlocked("invalid-meta");
  }
  return value as unknown as VaultLegacyContext;
}

function legacyMetadataObject({ value }: { value: unknown }, _options = {}): VaultMeta {
  if (value === null || typeof value !== "object" || Array.isArray(value)) throw new RowBlocked("invalid-meta");
  return value as VaultMeta;
}

function hasLegacyIdentityFields({ value }: { value: VaultMeta }, _options = {}): boolean {
  return typeof value.table === "string" && typeof value.workspaceId === "string" &&
    typeof value.id === "string" && typeof value.aadVersion === "number";
}

/** Resolve a moved legacy row's exact target scope. A taken label means the moved row is a
 * duplicate and is dropped; otherwise keep its label and preserve conflicting defaults.
 * @complexity O(group size) time/space; one metadata-only scope read, no ciphertext hydration.
 */
async function targetGroup({ input, record, provider }: { input: VaultBootInput; record: VaultRecord; provider: string | null },
  _options = {},
): Promise<{ label: string; isDefault: boolean } | null> {
  if (provider === record.provider) return { label: record.label, isDefault: record.isDefault };
  const rows = await input.kernel.query<{ id: string; label: string; is_default: boolean | number }>(sql`
    SELECT id,label,is_default FROM secrets_vault WHERE workspace_id=${record.workspaceId} AND kind=${record.kind}
      AND owner_key=${record.ownerKey}
      AND ${record.principalId === null ? sql`principal_id IS NULL` : sql`principal_id=${record.principalId}`}
      AND ${provider === null ? sql`provider IS NULL` : sql`provider=${provider}`} AND id<>${record.id}`);
  if (rows.some(row => row.label === record.label)) return null;
  return { label: record.label, isDefault: record.isDefault && !rows.some(row => row.is_default === true || row.is_default === 1) };
}

/** Return null for a moved duplicate before crypto; otherwise open under precisely one historical
 * AAD, normalize, validate, re-seal and reopen/compare.
 * No failed row is written with new ciphertext. Metadata-only rows need no key.
 * @complexity O(payload + metadata + target group size) time/space, at most two opens and one seal.
 */
async function normalizedRecord({ input, record, legacy, previous = input.sealer }: LegacyRecordInput): Promise<VaultRecord | null> {
  const provider = normalizationProvider({ input, record, legacy });
  const group = await targetGroup({ input, record, provider });
  if (group === null) return null;
  const { plaintext, key } = await openLegacyRecord({ input, record, legacy, previous });
  const { normalized, meta: parsedMeta } = parseLegacyRecord({ input, record, legacy, plaintext });
  let meta = parsedMeta;
  if (meta.migration !== null && typeof meta.migration === "object" && !Array.isArray(meta.migration)) {
    meta = { ...meta, migration: { ...meta.migration, mappedLabel: group.label, mappedProvider: normalized.provider } };
  }
  const replacement: VaultRecord = { ...record, ...group, provider: normalized.provider, meta,
    revision: record.revision + 1, updatedAt: new Date(input.clock.nowMs()).toISOString(), last4: null, tokenLength: null };
  await sealNormalizedRecord({ input, replacement, normalized, key });
  return replacement;
}

type LegacyRecordInput = { input: VaultBootInput; record: VaultRecord; legacy: VaultLegacyContext; previous?: Pick<SecretSealerPort, "open"> };

function normalizationProvider({ input, record, legacy }: LegacyRecordInput, _options = {}): string | null {
  let provider = record.provider;
  if (record.sealed && legacy.table === "publish_credential_sets") {
    // The catalog owns provider reassignment; detect duplicates without opening their ciphertext.
    try {
      legacyVaultAad({ record, legacy });
      provider = legacyTargetProvider({ record, legacy, policy: input.registry.policy }).provider;
    } catch (error) {
      throw new RowBlocked(error instanceof Error && error.message === "VAULT_CATALOG_UNAVAILABLE" ? "catalog-unavailable" : "invalid-meta");
    }
  }
  return provider;
}

async function openLegacyRecord({ input, record, legacy, previous = input.sealer }: LegacyRecordInput, _options = {}): Promise<{ plaintext: string | null; key: SiteKeyHandle }> {
  let plaintext: string | null = null;
  let key!: SiteKeyHandle; // Non-null payloads require plaintext opened after key acquisition.
  if (record.sealed) {
    try { key = await input.keyring.activeKey({}); } catch { throw new RowBlocked("missing-key"); }
    try { plaintext = await previous.open({ sealed: record.sealed }, { aad: legacyVaultAad({ record, legacy }) }); }
    catch { throw new RowBlocked("unopenable"); }
  } else {
    // Even an empty envelope must not erase an unsupported or mismatched lineage marker.
    try { legacyVaultAad({ record, legacy }); } catch { throw new RowBlocked("invalid-meta"); }
  }
  return { plaintext, key };
}

function parseLegacyRecord({ input, record, legacy, plaintext }: LegacyRecordInput & { plaintext: string | null }, _options = {}) {
  let normalized: ReturnType<typeof normalizeLegacyVaultPayload>;
  let meta: VaultMeta;
  try {
    normalized = normalizeLegacyVaultPayload({ record, legacy, plaintext, policy: input.registry.policy });
    meta = input.registry.metaParsers[record.kind]({ meta: normalized.meta, provider: normalized.provider });
    assertCredentialFreeField({ value: record.label, field: "label" });
  } catch (error) {
    throw new RowBlocked(error instanceof Error && error.message === "VAULT_CATALOG_UNAVAILABLE" ? "catalog-unavailable" : "invalid-meta");
  }
  return { normalized, meta };
}

async function sealNormalizedRecord({ input, replacement, normalized, key }: {
  input: VaultBootInput; replacement: VaultRecord; normalized: ReturnType<typeof normalizeLegacyVaultPayload>; key: SiteKeyHandle;
}, _options = {}): Promise<void> {
  if (normalized.payload !== null) {
    const payloadText = JSON.stringify(normalized.payload);
    const aad = buildVaultAad(replacement);
    try {
      replacement.sealed = await input.sealer.seal({ plaintext: payloadText, key, aad });
      if (await input.sealer.open({ sealed: replacement.sealed }, { aad }) !== payloadText) throw new RowBlocked("unopenable");
    } catch { throw new RowBlocked("unopenable"); }
    if (normalized.hintToken !== undefined) {
      const hint = credentialTokenHint({ token: normalized.hintToken });
      replacement.last4 = hint.last4;
      replacement.tokenLength = hint.length;
    }
  }
}

/** CAS the whole normalization result, or delete a moved duplicate when after is null.
 * The raw host write permits legacy provider reassignment,
 * which Jini's ordinary put correctly rejects as an immutable-identity change. Writers still
 * share the exact Jini workspace lock; no second vault repository or crypto implementation.
 * @throws RowBlocked on revision conflict; propagates storage errors.
 * @complexity O(payload + metadata) time/space; one guarded write, no crypto.
 */
async function saveNormalized({ input, before, after }: { input: VaultBootInput; before: VaultRecord; after: VaultRecord | null }): Promise<void> {
  if (after === null) {
    const rows = await input.kernel.query<{ id: string }>(sql`DELETE FROM secrets_vault
      WHERE workspace_id=${before.workspaceId} AND id=${before.id} AND revision=${before.revision} RETURNING id`);
    if (rows.length !== 1) throw new RowBlocked("conflict");
    return;
  }
  const envelope = normalizedEnvelope({ record: after });
  const rows = await input.kernel.query<{ id: string }>(sql`UPDATE secrets_vault SET
    provider=${after.provider}, label=${after.label}, is_default=${input.kernel.dialect === "sqlite" ? Number(after.isDefault) : after.isDefault},
    sealed_key_id=${envelope.keyId}, sealed_ciphertext=${envelope.ciphertext},
    sealed_nonce=${envelope.nonce}, sealed_alg=${envelope.alg},
    last4=${after.last4}, token_length=${after.tokenLength}, meta=${JSON.stringify(after.meta)},
    revision=${after.revision}, updated_at=${after.updatedAt}
    WHERE workspace_id=${before.workspaceId} AND id=${before.id} AND revision=${before.revision} RETURNING id`);
  if (rows.length !== 1) throw new RowBlocked("conflict");
}

function normalizedEnvelope({ record }: { record: VaultRecord }, _options = {}) {
  return { keyId: record.sealed?.keyId ?? null, ciphertext: record.sealed?.ciphertext ?? null,
    nonce: record.sealed?.nonce ?? null, alg: record.sealed?.alg ?? null };
}

/** Safe flag-only CAS leaves ciphertext, legacy identity and other metadata intact for recovery. */
async function flagRecord({ input, record, reason }: { input: VaultBootInput; record: VaultRecord; reason: BlockReason }): Promise<void> {
  if (record.meta.normalization === reason) return;
  await input.kernel.execute(sql`UPDATE secrets_vault SET meta=${JSON.stringify({ ...record.meta, normalization: reason })}, revision=revision+1
    WHERE workspace_id=${record.workspaceId} AND id=${record.id} AND revision=${record.revision}`);
}

/** Boot runs before consumers are constructed. The shared operation lock is the first effect;
 * the transaction then locks `secrets_vault:<workspaceId>` exactly as ALL Jini SQL writers do.
 * Moved duplicates are counted and dropped; missing keys keep surviving rows flagged, and normal
 * envelopes are checked too: no false green report.
 * @throws Lock denial, I/O errors or commit failure; row failures have safe flagged outcomes.
 * @complexity O(n + sum of moved target group sizes + payload work) time; O(n + largest group +
 * largest payload) space. One pass over n workspace rows, not a per-request inventory path.
 * No old-process draining.
 */
export async function normalizeVaultAtBoot(input: VaultBootInput,
  { report: observe = () => {} }: { report?: (input: VaultBootReport) => void } = {},
): Promise<VaultBootReport> {
  const deps = { clock: input.clock };
  const acquired = await acquireOperationLock({ deps, input: { siteId: input.siteId, operationKind: "vault-normalization" } });
  if (!acquired.ok) throw new Error(acquired.error.code);
  try {
    const report = await input.kernel.transaction(async () => {
      await input.kernel.lockKey(`secrets_vault:${input.workspaceId}`);
      const repo = new SqlSecretsVaultRepo({ kernel: input.kernel as StorageKernel<SecretsVaultDatabase> });
      // Unopened sites retain the old kind until 0013 is activated for their database. Count it
      // without changing authenticated identity; only an explicit legacyAad marker requests resealing.
      const report: VaultBootReport = { green: false, flagged: [], kinds: Object.fromEntries([...VAULT_KINDS, "custom" as const].map(kind => [kind,
        { rows: 0, envelopes: 0, attempted: 0, succeeded: 0, dropped: 0, blocked: 0, legacyRemaining: 0, unopenable: 0 }])) as VaultBootReport["kinds"] };
      const identities = await input.kernel.query<{ id: string }>(sql`SELECT id FROM secrets_vault WHERE workspace_id=${input.workspaceId} ORDER BY id`);
      for (const { id } of identities) {
        await normalizeBootRow({ input, repo, report, id });
      }
      report.green = report.flagged.length === 0 && Object.values(report.kinds).every(kind => kind.legacyRemaining === 0 && kind.unopenable === 0);
      return report;
    });
    observe(report);
    return report;
  } finally {
    await releaseOperationLock({ deps, input: { siteId: input.siteId, handle: acquired.value } });
  }
}

async function validateCurrentRecord({ input, record }: { input: VaultBootInput; record: VaultRecord }, _options = {}): Promise<void> {
  // Ordinary feature reads have no legacy fallback; readiness proves that exact path.
  try { input.registry.metaParsers[record.kind]({ meta: record.meta, provider: record.provider }); } catch { throw new RowBlocked("invalid-meta"); }
  const { normalization: _flag, ...meta } = record.meta;
  if (record.sealed) {
    try { await input.keyring.activeKey({}); } catch { throw new RowBlocked("missing-key"); }
    try {
      const payload = JSON.parse(await input.sealer.open({ sealed: record.sealed }, { aad: buildVaultAad(record) }));
      if (payload === null || typeof payload !== "object" || Array.isArray(payload)) throw new RowBlocked("unopenable");
    }
    catch { throw new RowBlocked("unopenable"); }
  }
  if (record.meta.normalization !== undefined) await input.kernel.execute(sql`UPDATE secrets_vault
    SET meta=${JSON.stringify(meta)}, revision=revision+1 WHERE workspace_id=${record.workspaceId} AND id=${record.id} AND revision=${record.revision}`);
}

async function normalizeBootRow({ input, repo, report, id }: {
  input: VaultBootInput; repo: Pick<VaultRepoPort, "find">; report: VaultBootReport; id: string;
}, _options = {}): Promise<void> {
  let record = await repo.find({ workspaceId: input.workspaceId, id });
  if (!record) throw new RowBlocked("conflict");
  const coverage = report.kinds[record.kind];
  coverage.rows += 1;
  if (record.sealed) coverage.envelopes += 1;
  const hasLegacy = record.meta.legacyAad !== undefined;
  if (hasLegacy) coverage.attempted += 1;
  try {
    const legacy = legacyContext({ record });
    if (legacy) {
      const after = await normalizedRecord({ input, record, legacy });
      await saveNormalized({ input, before: record, after });
      if (after === null) { coverage.dropped += 1; return; }
      record = after;
      coverage.succeeded += 1;
    } else {
      await validateCurrentRecord({ input, record });
    }
  } catch (error) {
    await reportBlockedRow({ input, record, error, coverage, hasLegacy, report, id });
  }
}

function blockedRowReason({ error }: { error: unknown }, _options = {}): BlockReason {
  return error instanceof RowBlocked ? error.reason
    : error instanceof VaultError && error.code === "conflict" ? "conflict" : "invalid-meta";
}

async function reportBlockedRow({ input, record, error, coverage, hasLegacy, report, id }: {
  input: VaultBootInput; record: VaultRecord; error: unknown; coverage: VaultKindCoverage;
  hasLegacy: boolean; report: VaultBootReport; id: string;
}, _options = {}): Promise<void> {
  if (!(error instanceof RowBlocked) && !(error instanceof Error && error.name === "VaultError")) throw error;
  const reason = blockedRowReason({ error });
  await flagRecord({ input, record, reason });
  coverage.blocked += 1;
  if (hasLegacy) coverage.legacyRemaining += 1;
  if (reason === "unopenable" || reason === "missing-key") coverage.unopenable += 1;
  report.flagged.push({ id, kind: record.kind, reason });
}

/** Host wiring shared by folder boot and direct composition; both await it before consumers.
 * Reuses the installed contribution loader and the bundled deploy fallback from the old backfill.
 * Missing keys are resolved only inside normalization, so a flagged report remains observable.
 * @complexity O(plugin catalog + vault rows); normalization owns the lock, CAS and crypto work.
 */
export async function normalizeSiteVaultAtBoot<Database>(required: {
  kernel: StorageKernel<Database>; workspaceId: string; siteDir?: string; clock: Clock;
}, optional: {
  keyring?: KeyringPort; sealer?: SecretSealerPort; loadContributions?: LoadPluginContributions;
  report?: (report: VaultBootReport) => void;
} = {}): Promise<VaultBootReport> {
  const keyring = optional.keyring ?? new EnvOrFileKeyring({ sources: siteKeySources({
    mode: resolveRuntimeMode(), env: process.env, home: homedir(), cwd: process.cwd(),
    siteKeyId: required.siteDir ? resolveSiteKeyId({ siteDir: required.siteDir }) : undefined,
  }) });
  const sealer = optional.sealer ?? new AesGcmSecretSealer({ keyring });
  const registry = await loadSiteVaultKinds(required, { loadContributions: optional.loadContributions });
  // Normalization uses raw SQL, independent of the caller's typed content-query surface.
  return normalizeVaultAtBoot({ ...required, kernel: required.kernel as unknown as StorageKernel<unknown>,
    siteId: required.workspaceId, keyring, sealer, registry }, {
    report: optional.report ?? (report => {
      // Safe coverage only: neither crypto errors nor secret material belong in boot logs.
      if (report.green) console.info("vault boot coverage", report);
      else console.warn("vault boot coverage flagged", report);
    }),
  });
}

/** Shared catalog resolution for boot and key recovery; no second legacy provider owner. */
export async function loadSiteVaultKinds(input: { workspaceId: string; siteDir?: string },
  { loadContributions: loadContributionsOverride }: { loadContributions?: LoadPluginContributions } = {},
): Promise<ReturnType<typeof createTovuVaultKinds>> {
  const loadContributions = loadContributionsOverride ?? createTovuAgentPluginLifecycle({
    layout: resolveAgentPluginLayout({ siteDir: input.siteDir }),
  }).loadPluginContributions;
  const registries = await Promise.all([
    loadDeployTargetRegistry({ workspaceId: input.workspaceId }, { loadContributions }),
    // Every bundled plugin's source, not one: a legacy publish row must resolve its vendor even
    // before the hosting plugin that now owns its target has been seeded and switched on.
    loadBundledDeployTargetRegistry({ sourceRoot: join(resolveProductRoot(), "content", "agent-plugins") }),
  ]);
  const registry = createTovuVaultKinds({ policy: {
    validateMeta: ({ meta }) => meta,
    legacyPublishCredential: ({ providerId }) => registries.map(registry => registry.get(providerId)?.descriptor.credential).find(spec => spec !== undefined),
    tokenField: ({ kind, provider }) => kind === "vendor"
      ? registries.flatMap(registry => registry.list()).find(target => target.descriptor.credential?.vendorId === provider)?.descriptor.credential?.tokenField
      : kind === "custom" || kind === "source-control" ? "token" : undefined,
  } });
  return registry;
}

/** Recover through boot's shared normalization: delete moved duplicates, otherwise validate and
 * re-seal/reopen the legacy envelope.
 * Caller holds the Jini workspace writer lock; the original revision still guards the commit.
 * @complexity O(payload + metadata + target group size) time/space; one CAS write, no crypto for drops.
 */
export async function recoverLegacyVaultRecord(required: {
  input: VaultBootInput; record: VaultRecord; previous: Pick<SecretSealerPort, "open">;
}, _options = {}): Promise<void> {
  const legacy = legacyContext({ record: required.record });
  if (!legacy) throw new RowBlocked("invalid-meta");
  const after = await normalizedRecord({ ...required, legacy });
  await saveNormalized({ input: required.input, before: required.record, after });
}

/**
 * Tovu daemon wiring over @jini-ai/sidecar/supervisor and its /node process adapter.
 * Tovu owns environment,
 * workspace identity, readiness, log wording and process signal handlers; Jini owns retries,
 * single-flight replacement, terminal shutdown and production process-tree cleanup.
 *
 * Keep this assembly separate from the entrypoint, whose module-load boot prevents direct
 * unit imports. Register signals once in the singleton wrapper: installing them per respawn
 * would accumulate process listeners. Terminal shutdown must refuse manual recovery, while
 * a tripped crash cap must permit it. On-demand recovery also covers missing-script spawn
 * failures and old trips; the host's 30s cooldown prevents request traffic from becoming a
 * respawn storm. The package publishes each child synchronously to keep recovery single-flight.
 *
 * Identity proof before killing: daemon argv carries --workspace so a future reconciler
 * can verify an instance from its live command line, without reading an environment dump
 * that might expose secrets. Registry ownership and production tree cleanup belong to the
 * Node adapter; this host supplies the site-scoped registry path and launch identity.
 */
import { isDaemonLifecycleLogQuiet } from "./daemon-lifecycle-log.js";
import { execFileSync } from "node:child_process";
import { createRequire } from "node:module";
import {
  createNodeDaemonProcessAdapter,
  createNodeSupervisorScheduler,
  type NodeDaemonProcessOptions,
} from "@jini-ai/sidecar/supervisor/node";
import { createDaemonSupervisor as createSidecarSupervisor } from "@jini-ai/sidecar/supervisor";
import type { DaemonSupervisorRequired, SpawnedDaemonProcess as SidecarDaemonProcess, SupervisorScheduler } from "@jini-ai/sidecar/supervisor";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { redactLocalText } from "../../../platform/server-logs/redact-local-text.js";
import { createRedactedOutputSink } from "../../../platform/server-logs/console-tee.js";

import { clearAssistantDaemonFailure, recordAssistantDaemonFailure } from "./readiness-state.js";
import { getAgentDaemonPortForSpawnEnv } from "./agent-daemon-port.js";
import { createAssistantDaemonRegistry } from "./assistant-daemon-registry.js";
import { AGENT_DAEMON_EXIT_CODE, createRespawnPolicy } from "#src/assistant/index";
import type { RespawnDecision, RespawnPolicy } from "#src/assistant/index";

/**
 * The minimal shape this module needs from a spawned daemon process. Node's real `ChildProcess`
 * satisfies this structurally with no adapter needed; tests pass a lightweight `EventEmitter`-based
 * double instead so no real OS process is ever spawned in a unit test (see this file's own test).
 */
export interface SpawnedDaemonProcess {
  // Optional, matching Node's own `ChildProcess.pid` shape exactly (not `pid: number | undefined`)
  // — a required property typed `T | undefined` and an optional `pid?: T` are NOT structurally
  // interchangeable to the type checker, and the real `spawn()` return value only satisfies the
  // optional form.
  readonly pid?: number;
  on(event: "exit", listener: (code: number | null, signal: NodeJS.Signals | null) => void): unknown;
  on(event: "error", listener: (error: Error) => void): unknown;
  kill(signal?: NodeJS.Signals): boolean;
}

export interface DaemonSupervisorDeps {
  /** Caller-owned Node child factory. The production singleton uses Jini's Node adapter instead. */
  spawnDaemonProcess: () => SpawnedDaemonProcess;
  /** Defaults to a fresh {@link createRespawnPolicy} instance with production settings — pass an
   *  override in tests to shrink the backoff/cap thresholds so retries happen in milliseconds. */
  policy?: RespawnPolicy;
  /** Timer port for the package retry loop; defaults to the Node scheduler. */
  scheduler?: SupervisorScheduler;
  /** Only used to compose human-readable failure messages. Defaults to
   *  `JINI_AGENT_DAEMON_PORT ?? "4319"`, matching what the daemon itself resolves
   *  (`agent-daemon-server.ts`). */
  daemonPort?: string;
  /** Injectable clock for `ensureStarted()`'s cooldown — real `Date.now` in production, a
   *  controllable fake in tests. */
  now?: () => number;
  /** Minimum interval between two `ensureStarted()`-triggered re-arms when nothing is currently
   *  running or scheduled (see this file's own header). Defaults to 30s, matching the backoff
   *  ladder's own cap — traffic-driven and time-driven retries then share one worst-case ceiling. */
  onDemandCooldownMs?: number;
  /** Platform for the injected Node-child termination seam. */
  // The platform seam makes the Windows tree-kill branch assertable on any test host.
  platform?: NodeJS.Platform;
  /** win32-only tree-kill for the injected Node-child seam instead of the POSIX process-group signal
   *  (`process.kill(-pid, "SIGTERM")`), which Windows has no equivalent for. Defaults to
   *  {@link taskkillTree} (`taskkill /pid <pid> /T /F`); never called on POSIX. */
  killTree?: (pid: number) => void;
  /** When `true`, the ROUTINE lifecycle lines — the first spawn and a deliberate (shutdown/restart)
   *  exit — are not printed; an unexpected exit and every respawn still are, since those are what an
   *  operator correlates a dead chat against. Defaults to {@link isDaemonLifecycleLogQuiet} (`TOVU_DAEMON_LIFECYCLE_LOG=off`),
   *  which `npm start` (`development/scripts/start.mjs`) sets so its output is one URL line. */
  quietRoutineLifecycle?: boolean;
  /** Where lifecycle breadcrumbs go. Defaults to `console.log`; injected in tests. */
  log?: (line: string) => void;
}

/** Returned by both `restart()` and `ensureStarted()` — `reason` is present only when `ok` is
 *  `false`. */
export interface DaemonSupervisorActionResult {
  ok: boolean;
  reason?: string;
}

export interface DaemonSupervisor {
  /** Perform the first spawn attempt. Call exactly once per supervisor instance. */
  start(): void;
  /**
   * The manual restart seam — the piece that answers "a human's not gonna know how to restart a
   * Node process": clears the respawn policy, cancels any pending scheduled retry, and spawns a
   * replacement daemon, regardless of whether the crash-loop cap had tripped. If a daemon process
   * is still alive, it is killed first and the replacement is spawned only after it actually
   * exits — spawning immediately alongside a still-live daemon would just collide on the same
   * port and fail with the exact EADDRINUSE this supervisor otherwise guards against.
   *
   * Refuses with `{ ok: false, reason: "shutting down" }` once `shutdown()` has run — a manual
   * restart racing the process's own SIGTERM-driven teardown must never resurrect a daemon the
   * process is actively trying to kill. See this file's own header for the terminating-vs-tripped
   * distinction.
   */
  restart(): DaemonSupervisorActionResult;
  /**
   * The on-demand/lazy-start seam — see this file's own header for why automatic respawn alone
   * does not cover every case this closes (a daemon that never started, or a cap that tripped long
   * before anyone showed up). Single-flight and cooldown-guarded; safe to call from a hot request
   * path. Refuses the same way `restart()` does once `shutdown()` has run.
   */
  ensureStarted(): DaemonSupervisorActionResult;
  /** Deliberate shutdown: stops any future automatic respawn AND any future `restart()`/
   *  `ensureStarted()` call, cancels a pending scheduled retry, and kills the currently-running
   *  daemon (process-group kill, falling back to the direct child). Safe to call even when no
   *  daemon is currently running. */
  shutdown(): void;
}

/**
 * Default Windows tree-kill for the caller-owned Node-child seam; production tree-stop is Jini's.
 * Windows has no POSIX process groups. Killing only the npx/tsx launcher would orphan the
 * daemon beneath it, so taskkill /T walks its descendants instead.
 *
 * @param pid the child's own pid (never negated — there is no process-group id to negate on win32).
 * @complexity One OS command; the OS walks the process tree.
 */
function taskkillTree(pid: number): void {
  execFileSync("taskkill", ["/pid", String(pid), "/T", "/F"], { stdio: "ignore" });
}

/** Same reasoning `index.ts` used for EADDRINUSE specifically: naming the real cause here is what
 *  turns an unexplained "exited unexpectedly (code 1)" into something an operator can act on. */
function computeExitReasonCode(code: number | null, signal: NodeJS.Signals | null, daemonPort: string): string {
  if (code === AGENT_DAEMON_EXIT_CODE.PORT_IN_USE) {
    return `agent daemon could not bind 127.0.0.1:${daemonPort} — address already in use`;
  }
  return `agent daemon exited unexpectedly (code ${code}, signal ${signal ?? "none"})`;
}

/** Tovu's final readiness wording distinguishes repeated bind failures from general crash loops. */
function buildGiveUpReasonCode(decision: Extract<RespawnDecision, { action: "give-up" }>, lastReasonCode: string, daemonPort: string): string {
  if (decision.kind === "port-conflict") {
    return (
      `gave up after ${decision.attempts} attempts trying to bind 127.0.0.1:${daemonPort} — likely a zombie ` +
      `process still holding the port; find it with \`lsof -ti :${daemonPort} -sTCP:LISTEN\`, stop it, then use ` +
      `the manual restart to try again`
    );
  }
  return `gave up after ${decision.attempts} attempts in ${Math.round(decision.windowMs / 1000)}s: ${lastReasonCode}`;
}

/**
 * Translate a host Node child (including existing injected doubles) into Jini's process port.
 * @complexity O(1) wrapping; subscriptions and signals delegate directly to the child.
 */
function adaptDaemonProcess({ child }: { child: SpawnedDaemonProcess }): SidecarDaemonProcess {
  return {
    get pid() { return child.pid; },
    on(input) {
      if (input.event === "exit") child.on("exit", (code, signal) => input.listener({ code, signal }));
      else child.on("error", (error) => input.listener({ error }));
    },
    kill(_required, { signal } = {}) { return child.kill(signal); },
  };
}

/** Bind the package's spawn-failure wording to Tovu's existing readiness message. */
function formatFailureReason(reason: string): string {
  const prefix = "failed to start daemon: ";
  if (reason.startsWith(prefix)) {
    return `failed to start the agent daemon — the assistant will be unavailable: ${reason.slice(prefix.length)}`;
  }
  return reason;
}

type DaemonProcessPorts = Pick<DaemonSupervisorRequired, "spawnDaemonProcess" | "terminateProcess">;
type DaemonHostOptions = Omit<DaemonSupervisorDeps, "spawnDaemonProcess">;

/**
 * Supply Tovu's readiness and wording ports to Jini's supervisor without reproducing its state.
 * @param ports Explicit spawn and termination effects, owned by the host assembly.
 * @param options Tovu clock, retry profile, cooldown, scheduler and log settings.
 * @returns Lifecycle methods with Tovu's existing action-result wording.
 * @throws RangeError for invalid retry/cooldown budgets.
 * @complexity O(1) assembly/event formatting, excluding the injected policy and process ports.
 */
function bindDaemonSupervisor(ports: DaemonProcessPorts, options: DaemonHostOptions = {}): DaemonSupervisor {
  const clock = options.now ?? Date.now;
  const daemonPort = options.daemonPort ?? process.env.JINI_AGENT_DAEMON_PORT ?? "4319";
  const log = options.log ?? ((line: string) => console.log(line));
  const supervisor = createSidecarSupervisor({
    ...ports,
    policy: options.policy ?? createRespawnPolicy({ now: clock }),
    now: clock,
    scheduler: options.scheduler ?? createNodeSupervisorScheduler({}),
    classifyExit: ({ code, signal }) => ({
      isPortConflict: code === AGENT_DAEMON_EXIT_CODE.PORT_IN_USE,
      reason: computeExitReasonCode(code, signal, daemonPort),
    }),
    failureReporter: {
      clear: clearAssistantDaemonFailure,
      record: ({ reason }) => recordAssistantDaemonFailure(formatFailureReason(reason)),
    },
    logger: {
      emit(event) {
        if (event.type === "failure") {
          console.error(`[daemon-supervisor] ${formatFailureReason(event.reason)}`);
          return;
        }
        const at = new Date(event.at).toISOString();
        if (event.type === "spawn") {
          log(`[daemon-supervisor] ${at} spawned agent daemon pid=${event.pid ?? "unknown"}`);
          return;
        }
        log(`[daemon-supervisor] ${at} agent daemon pid=${event.pid ?? "unknown"} exited (code=${String(event.code)}, signal=${String(event.signal)}, deliberate=${event.deliberate}) — any run in flight died with it`);
      },
    },
  }, {
    onDemandCooldownMs: options.onDemandCooldownMs ?? 30_000,
    quietRoutineLifecycle: options.quietRoutineLifecycle ?? isDaemonLifecycleLogQuiet(),
    formatGiveUp: ({ decision, lastReason }) => buildGiveUpReasonCode(decision, lastReason, daemonPort),
  });
  return {
    ...supervisor,
    ensureStarted() {
      const result = supervisor.ensureStarted();
      if (result.reason === "cooling down before trying again") {
        return { ok: false, reason: "an on-demand restart was already attempted recently — cooling down before trying again" };
      }
      return result;
    },
  };
}

/**
 * Keep the existing injected Node-child seam for host callers and lifecycle tests.
 * Production uses Jini's complete Node process-tree adapter below; this seam keeps the caller's
 * platform/tree-kill port and translates subscriptions rather than owning any retry state.
 * @param deps Host child factory and optional policy/platform/log settings.
 * @returns A package supervisor bound to the existing host ports.
 * @complexity O(1) assembly, excluding injected ports and retry-window pruning.
 */
export function createDaemonSupervisor(deps: DaemonSupervisorDeps): DaemonSupervisor {
  const platform = deps.platform ?? process.platform;
  const killTree = deps.killTree ?? taskkillTree;
  return bindDaemonSupervisor({
    spawnDaemonProcess: () => adaptDaemonProcess({ child: deps.spawnDaemonProcess() }),
    terminateProcess({ child }) {
      if (child.pid === undefined) return;
      try {
        if (platform === "win32") killTree(child.pid);
        else process.kill(-child.pid, "SIGTERM");
      } catch {
        try { child.kill({}, { signal: "SIGTERM" }); } catch { /* already gone */ }
      }
    },
  }, deps);
}

/**
 * Resolves the daemon's own script path the same way `index.ts`'s original code did — by
 * swapping this file's extension — so the same code path launches `agent-daemon-server.ts` under
 * `tsx` in dev and the compiled `agent-daemon-server.js` under plain `node` in a built `dist/`.
 *
 * NOT co-located any more: this file lives in `server/runtime/lifecycle/` (runtime-infrastructure
 * concern), while `agent-daemon-server.ts` moved to `server/inbound/assistant/` (inbound-HTTP-surface
 * concern) in the same `src/server/` split that separated them — a same-directory `path.join` here
 * silently resolved to a nonexistent file the moment that split landed (masked until something
 * actually spawned the daemon and hit `ERR_MODULE_NOT_FOUND`, since nothing type-checks a runtime
 * string path). The `../../inbound/assistant/` offset is symmetric in both trees: `tsc`'s `rootDir`
 * mirrors this whole `server/` subtree unchanged, so `runtime/lifecycle/` -> `inbound/assistant/` is
 * the same two-up-two-down hop under `tsx` and under compiled `dist/`.
 */
export function resolveDaemonScriptPath(): string {
  const isCompiled = import.meta.filename.endsWith(".js");
  return path.join(
    import.meta.dirname,
    "../../inbound/assistant",
    isCompiled ? "agent-daemon-server.js" : "agent-daemon-server.ts",
  );
}

/** Host-owned site/workspace identity supplied consistently across daemon respawns. */
export interface DaemonSpawnEnvInput {
  workspaceId: string;
  /** This process's own already-resolved site root (`deps.ts`'s `siteDir()` for `index.ts`, or the
   *  CLI's `<dir>` argument for `cli/commands/serve.ts`) — see {@link buildDaemonSpawnEnvOverrides}. */
  siteDir: string;
  daemonPortOverride: string | undefined;
  /** A PGlite site's owner socket (`SiteStore.pgliteSocketPath`), passed as `TOVU_PG_SOCKET` so the
   *  daemon, a store client, connects to the socket this process serves. Absent on SQLite/Postgres. */
  pgSocketPath?: string;
}

/**
 * Builds the env overrides layered onto `process.env` for every daemon spawn. Pure — no `spawn()`
 * call — specifically so the "does the child agree with the parent" invariant can be asserted
 * directly against `resolveSiteRoot()` in a test, without spawning a real process.
 *
 * `TOVU_SITE_DIR` (2026-08-29 follow-up fix): the child previously inherited only `process.env`
 * unchanged, so it resolved its OWN site via `resolveSiteRoot()`'s cwd-relative fallback
 * (`<cwd>/sites/tovu-dev`) — agreeing with the parent only by the accident of sharing its cwd. Two
 * confirmed live failures: Tovu-Runner's cwd has no `sites/tovu-dev` at all (crash-loop), and this
 * repo's own root DOES have one as a fixture, so a `tovu serve <other-dir>` run from here bound its
 * port cleanly while silently attached to the WRONG site's database — the exact wrong-site-data
 * hazard the original port fix closed, just moved one layer down. Omitted (not overridden) whenever
 * the parent's own env already pins `TOVU_SITE_DIR`, same "explicit always wins" discipline as the
 * port override below; `TOVU_CONTENT_DB`/`TOVU_MEDIA_UPLOADS_DIR`/`TOVU_THEMES_DIR` are untouched by
 * this function, so each keeps overriding its own subpath independently regardless (`deps.ts`'s own
 * `?? join(siteDir(), ...)` precedence never even consults `siteDir()` once its own var is set).
 *
 * @complexity O(1).
 */
export function buildDaemonSpawnEnvOverrides(input: DaemonSpawnEnvInput): NodeJS.ProcessEnv {
  return {
    TOVU_WORKSPACE: input.workspaceId,
    TOVU_PARENT_PID: String(process.pid),
    // Self-allocation fix (2026-08-28): when neither `JINI_AGENT_DAEMON_URL` nor
    // `JINI_AGENT_DAEMON_PORT` was set, `agent-daemon-port.ts` picked a free port for THIS process
    // — the child would otherwise fall back to its own module-scope default (4319,
    // `agent-daemon-server.ts:133`) and bind somewhere the proxy above never asked it to listen.
    ...(input.daemonPortOverride !== undefined ? { JINI_AGENT_DAEMON_PORT: input.daemonPortOverride } : {}),
    ...(process.env.TOVU_SITE_DIR === undefined ? { TOVU_SITE_DIR: input.siteDir } : {}),
    ...(input.pgSocketPath !== undefined ? { TOVU_PG_SOCKET: input.pgSocketPath } : {}),
  };
}

/**
 * Builds the daemon child's own argv — split out of {@link createRealDaemonProcessPorts} so the
 * discriminating `--workspace <id>` token (see this file's own header, "identity proof before
 * killing") is directly assertable without spawning a real process.
 *
 * The token is inert to the daemon itself: `agent-daemon-server.ts` reads its workspace from
 * `TOVU_WORKSPACE` (`buildDaemonSpawnEnvOverrides`) and never inspects `process.argv` at all
 * (confirmed — no `process.argv` reference anywhere in that file), so appending it changes nothing
 * about how the daemon behaves. Its only job is to give a FUTURE reconciler something to prove
 * identity against, the same way `tovu-server.cjs` already proves a `tovu serve` child's identity
 * from its own `<siteDir> --port <n>` argv — before this token, the daemon's argv was byte-identical
 * across every instance (`[daemonPath]`/`["tsx", daemonPath]`), so an argv-substring proof like
 * Tovu-Runner's `isProjectSidecar` had nothing to match against.
 *
 * @complexity O(1).
 */
export function buildDaemonSpawnArgs(input: { daemonPath: string; workspaceId: string }): string[] {
  return [input.daemonPath, "--workspace", input.workspaceId];
}

/**
 * Proves a live process's argv still belongs to `workspaceId` — an argv-substring match, the same
 * technique as Tovu-Runner's `isProjectSidecar` (`project-provisioner.ts:701-716`), adapted to a seam
 * that has nowhere yet to persist a daemon pid across a restart (see this file's own header). Pure
 * and synchronous: the caller supplies the live command line (e.g. from `ps -o command=`), never an
 * env dump — reading a child's environment via `ps eww`/`pgrep -fl` is banned in this codebase
 * because both can leak another process's live secrets.
 *
 * Checks the token's trailing boundary, not a bare `.includes()`: `--workspace workspace-70` would
 * otherwise satisfy a look-up for `workspace-7` too (a plain substring match), misidentifying a pid
 * that legitimately belongs to a different, similarly-prefixed workspace id.
 *
 * @complexity O(1) — one indexOf plus one boundary check.
 */
export function isDaemonProcessForWorkspace(commandLine: string, workspaceId: string): boolean {
  const token = `--workspace ${workspaceId}`;
  const start = commandLine.indexOf(token);
  if (start === -1) return false;
  const boundaryIndex = start + token.length;
  return boundaryIndex === commandLine.length || /\s/.test(commandLine[boundaryIndex]);
}

/**
 * Bind current Tovu launch settings to the package Node adapter. Each spawn gets a fresh env
 * snapshot, while its registry stays scoped to the resolved site for the whole supervisor boot.
 * The daemon must write this record only after listening (r15 entrypoint wiring).
 * Jini's writer fsyncs the file and directory and preserves destination mode; a directory-sync
 * rejection can occur after replacement is visible. Publication errors belong to that child
 * boot path, rather than triggering a second write here before the daemon has bound its port.
 * @param input Workspace, resolved site, proxy port and optional PGlite socket.
 * @param optional Native spawn and output ports for direct tests; each child gets fresh redacting sinks.
 * @returns Process ports; construction never starts a process or writes a registry record.
 * @complexity O(e) environment copying per spawn for e variables; package tree-stop is O(p) processes.
 */
export function createRealDaemonProcessPorts(input: DaemonSpawnEnvInput, optional: Pick<NodeDaemonProcessOptions, "spawn" | "stdout" | "stderr"> = {}): DaemonProcessPorts {
  const daemonPath = resolveDaemonScriptPath();
  const args = buildDaemonSpawnArgs({ daemonPath, workspaceId: input.workspaceId });
  // The local host must prove a detached daemon still belongs to this API before reaping a cached PID.
  if (process.env.TOVU_LOCAL_SITE_OWNER_PID) args.push(`--local-site-api-pid=${process.pid}`);
  const { registryPath, registry } = createAssistantDaemonRegistry({ siteDir: input.siteDir }, {});
  function createProcessAdapter() {
    const isCompiled = daemonPath.endsWith(".js");
    return createNodeDaemonProcessAdapter({
      command: process.execPath,
      // Preload awaits pruning before tsx starts; keep the supervisor's synchronous child contract.
      // `--import tsx` instead of `tsx/cli`: the CLI relaunches a second node, one more process per site.
      // Every --import is a file URL; a bare `C:\` path is read as a URL scheme on Windows.
      args: isCompiled ? args : ["--import",
        new URL("../../../../../../development/scripts/prune-tsx-cache.mjs?prune", import.meta.url).href,
        "--import", pathToFileURL(createRequire(import.meta.url).resolve("tsx")).href,
        "--import", new URL("../../../../../../development/scripts/dev-source-maps-off.mjs", import.meta.url).href,
        ...args],
      cwd: process.cwd(),
      // Every respawn binds the same workspace and parent pid (D10/watchdog contract),
      // while refreshing process.env so repaired launch configuration can take effect.
      env: {
        ...process.env,
        ...buildDaemonSpawnEnvOverrides(input),
        TOVU_AGENT_DAEMON_REGISTRY_PATH: registryPath,
      },
      registry,
    }, { ...optional,
      stdout: createRedactedOutputSink({ sink: optional.stdout ?? process.stdout,
        redact: text => redactLocalText({ text }) }),
      stderr: createRedactedOutputSink({ sink: optional.stderr ?? process.stderr,
        redact: text => redactLocalText({ text }) }),
      platform: process.platform,
    });
  }
  // Termination uses the same registry identity; launch env is refreshed only when spawning.
  const cleanupAdapter = createProcessAdapter();
  return {
    spawnDaemonProcess: () => createProcessAdapter().spawnDaemonProcess(),
    terminateProcess: ({ child }) => {
      daemonStopWork = cleanupAdapter.terminateProcess({ child });
      return daemonStopWork;
    },
  };
}

// Module-singleton wrapper: the only place in this file that touches real process.on.
// Top-level boot starts after readiness; restart and lazy-start callers share this lifecycle.
let singleton: DaemonSupervisor | undefined;
// The package owns termination; this host only retains its completion for site-store teardown.
let daemonStopWork: Promise<void> = Promise.resolve();

/**
 * Latches shutdown even before the singleton exists. A pending readiness continuation
 * can otherwise start a daemon after shutdown ran, leaving a child no caller will reap.
 * The guard belongs to the shared lifecycle owner, protecting every start/shutdown caller.
 * Set once by shutdownAssistantDaemon and never cleared during a real process lifetime:
 * a process already asked to terminate must never start another daemon.
 */
let shutdownRequested = false;

/**
 * Test-only reset of this module's singleton state (mirrors `resetToolContributorsForTests` /
 * `resetFederatedMcpPresetsForTests` — same "process-wide module state must not leak between
 * `node:test` cases in the same file" convention). No production caller ever needs this: a real
 * process boots once and either starts the daemon or doesn't.
 */
export function resetAssistantDaemonSingletonForTests(): void {
  singleton = undefined;
  shutdownRequested = false;
  daemonStopWork = Promise.resolve();
}

export interface StartAssistantDaemonOptions {
  /**
   * Default `true`: this call registers its own
   * `process.on(SIGINT/SIGTERM/SIGHUP/"exit", ...)` handlers, and the signal handlers call
   * `process.exit(0)` themselves once the daemon is torn down.
   *
   * `cli/commands/serve.ts` passes `false`: that command already owns its own
   * BR-07 graceful-shutdown sequence, registered via `process.once(...)` on the SAME two signals.
   * Node invokes every registered listener for a signal, not just the first — a second listener
   * here calling `process.exit(0)` immediately would race `serve.ts`'s graceful drain (finish the
   * in-flight request, close the db, then exit) and could cut it short before it completes. A
   * caller that opts out this way must call {@link shutdownAssistantDaemon} itself from its own
   * shutdown sequence instead, or the daemon child is leaked as an orphan.
   */
  registerProcessSignalHandlers?: boolean;
  /**
   * Test seam only. Overrides the real {@link createRealDaemonProcessPorts} the module-singleton
   * wrapper otherwise builds internally, so a test can assert whether a spawn attempt happened at
   * all without ever touching `child_process` or spawning a real OS process (this repo's test
   * scripts do not pass `--experimental-test-module-mocks`, so `node:test`'s `mock.module()` is not
   * an available alternative here — see `resolve-test-agent-outcome.ts`'s header for the same
   * constraint). No production caller passes this; mirrors {@link DaemonSupervisorDeps.spawnDaemonProcess}
   * one layer up.
   */
  spawnDaemonProcess?: (input: DaemonSpawnEnvInput) => SpawnedDaemonProcess;
  /** Overrides only the native launch effect, retaining the production argv/env assembly. */
  nativeSpawn?: NodeDaemonProcessOptions["spawn"];
}

/**
 * Start the assistant daemon supervisor for this process boot. Safe to call only once — a second
 * call is ignored (logged, not thrown) rather than silently spawning a second supervisor that
 * would fight the first one for the same port and the same `process.on(signal, ...)` slot.
 */
export function startAssistantDaemon(
  input: { workspaceId: string; siteDir: string; pgSocketPath?: string },
  options: StartAssistantDaemonOptions = {},
): void {
  if (shutdownRequested) {
    console.error("[daemon-supervisor] startAssistantDaemon called after shutdownAssistantDaemon() already ran this process boot — refusing to spawn a daemon the process is already tearing down");
    return;
  }

  if (singleton !== undefined) {
    console.error("[daemon-supervisor] startAssistantDaemon called more than once this process boot — ignoring");
    return;
  }

  // Resolved once, here, rather than inside `spawnDaemonProcess` — `ensureAgentDaemonPortResolved()`
  // (called by both real boot paths before `createApp()`) has already settled by the time this runs,
  // so the same value this process's own proxy is using is what gets threaded into the child's env
  // and into `daemonPort` (used only for this supervisor's human-readable failure text).
  const daemonPortOverride = getAgentDaemonPortForSpawnEnv();
  const spawnEnv: DaemonSpawnEnvInput = {
    workspaceId: input.workspaceId,
    siteDir: input.siteDir,
    daemonPortOverride,
    pgSocketPath: input.pgSocketPath,
  };
  let supervisor: DaemonSupervisor;
  if (options.spawnDaemonProcess !== undefined) {
    const spawnDaemonProcess = options.spawnDaemonProcess;
    supervisor = createDaemonSupervisor({
      spawnDaemonProcess: () => spawnDaemonProcess(spawnEnv),
      daemonPort: daemonPortOverride,
    });
  } else {
    supervisor = bindDaemonSupervisor(createRealDaemonProcessPorts(spawnEnv, { spawn: options.nativeSpawn }), { daemonPort: daemonPortOverride });
  }
  singleton = supervisor;
  supervisor.start();

  if (options.registerProcessSignalHandlers === false) return;

  // `"exit"` alone is not enough: it does not run when this process is terminated by a signal,
  // which is how a dev server actually dies (Ctrl-C, or `tsx watch` cycling on a file change).
  process.on("exit", () => supervisor.shutdown());
  for (const signal of ["SIGINT", "SIGTERM", "SIGHUP"] as const) {
    process.on(signal, () => {
      supervisor.shutdown();
      process.exit(0);
    });
  }
}

/**
 * The explicit teardown seam for a caller that opted out of this module's own signal handling (see
 * {@link StartAssistantDaemonOptions.registerProcessSignalHandlers}) — `cli/commands/serve.ts`'s
 * BR-07 shutdown calls this instead. A no-op if the daemon was never started this process boot.
 * @returns The package process-tree stop, including the daemon's graceful database close.
 * @complexity O(1) here; process-tree enumeration and bounded termination belong to Jini.
 */
export function shutdownAssistantDaemon(): Promise<void> {
  // Set unconditionally, BEFORE the `singleton?.shutdown()` no-op-when-absent check below — see
  // `shutdownRequested`'s own doc for why this must latch even when no supervisor exists yet.
  shutdownRequested = true;
  singleton?.shutdown();
  return daemonStopWork;
}

export type RestartAssistantDaemonResult = DaemonSupervisorActionResult;

/**
 * The manual restart seam an admin action calls. Returns a result rather than throwing so a route
 * handler can report it back to the caller directly (`{ ok: true }`, or `{ ok: false, reason }` —
 * either because the daemon was never started this boot, or because the process is currently
 * shutting down; see `DaemonSupervisor.restart()`'s own doc for why that second case must refuse).
 */
export function restartAssistantDaemon(): RestartAssistantDaemonResult {
  if (singleton === undefined) {
    return { ok: false, reason: "the assistant daemon was never started this process boot" };
  }
  return singleton.restart();
}

export type EnsureAssistantDaemonStartedResult = DaemonSupervisorActionResult;

/**
 * The on-demand/lazy-start seam — see this file's own header for the full rationale. Intended
 * caller: `server/modules/assistant.ts`'s daemon-proxy code, at the point it discovers the daemon
 * is unreachable, so a request that needs the assistant can trigger recovery itself instead of the
 * assistant staying down until an operator notices and either restarts Tovu or presses the manual
 * restart action. Single-flight and cooldown-guarded — safe to call on every such request, not
 * just the first one.
 */
export function ensureAssistantDaemonStarted(): EnsureAssistantDaemonStartedResult {
  if (singleton === undefined) {
    return { ok: false, reason: "the assistant daemon was never started this process boot" };
  }
  return singleton.ensureStarted();
}

import { credentialText } from '../../../contracts/core/credential-copy.js';
/** Shared saved-server probe used by the admin route and assistant tools. Never spawns local commands or invokes remote tools. */
import {
  connectMcpHttpSession,
  createFetchMcpHttpExchange,
  ExternalMcpReauthRequiredError,
  externalMcpSettingsDeepLink,
  readEnabledExternalMcpConfigs,
  resolveExternalMcpAuthMode,
  resolveExternalMcpOAuthStatus,
  toResolvedFederatedConnections,
  type ExternalMcpOAuthService,
  type ExternalMcpServerRecord,
} from "#src/assistant/index";
import type { FederatedMcpConnectionConfig, McpHttpLaunchSpec, McpSessionPort } from "@jini-ai/mcp/federation";
import { McpAuthFailedError, McpProtocolError, describeRemoteToolSurface } from "@jini-ai/mcp/federation";
import type { ExternalMcpToolDeps } from "#src/features/external-mcp/deps";

/** Injectable session factory — the seam a route test scripts instead of opening a real socket.
 *  Same shape `mcp-federation/bootstrap.ts`'s own `connect` parameter uses for the identical reason:
 *  the protocol code under test should be the real thing, not a second hand-rolled fake of it. */
export type ExternalMcpProbeSessionFactory = (spec: McpHttpLaunchSpec, requestTimeoutMs: number) => Promise<McpSessionPort>;

export type ExternalMcpProbeServiceDeps = Pick<ExternalMcpToolDeps, "workspaceId" | "clock" | "externalMcpServerRepo" | "siteAssistantSecretSealer"> & {
  /**
   * Optional: only consulted for a connection whose `authMode` is `"oauth"`.
   * `readEnabledExternalMcpConfigs`'s own `oauth` parameter is equally optional, for the same
   * reason — a deployment that has never wired an OAuth service can still probe a `none`/
   * `static_env` connection, so this route must not demand the service just to run at all.
   */
  readonly externalMcpOAuth?: ExternalMcpOAuthService;
  /** Defaults to the real hosted MCP client. See {@link ExternalMcpProbeSessionFactory}. */
  readonly connect?: ExternalMcpProbeSessionFactory;
};

/** The real session factory: one handshake against the resolved hosted endpoint, bounded by the
 *  connection's own `connectTimeoutMs`. Deliberately NOT the same bound `bootstrap.ts`'s
 *  `defaultConnect` uses for the identical transport: that session is long-lived and its bound
 *  governs every later `tools/call` too, so it uses `callTimeoutMs`. This one issues an `initialize`
 *  handshake via {@link connectMcpHttpSession} followed by this route's own single `listTools`
 *  call, then is closed immediately after — for THIS session, `connectTimeoutMs` bounds the
 *  handshake and is the correct bound rather than a reused wrong one.
 *  @complexity O(1) beyond the remote's round-trip. */
async function defaultProbeConnect(spec: McpHttpLaunchSpec, requestTimeoutMs: number): Promise<McpSessionPort> {
  return connectMcpHttpSession({ exchange: createFetchMcpHttpExchange({ fetch }), spec, requestTimeoutMs });
}

/** One resolved, probeable target: the trust-tier config `describeRemoteToolSurface` needs, and the
 *  hosted launch spec to connect with. */
interface ProbeTarget {
  readonly federationConfig: FederatedMcpConnectionConfig;
  readonly launch: McpHttpLaunchSpec;
}

/** One outcome of {@link resolveProbeTarget}: either a usable target, or a response this route
 *  should send verbatim without ever attempting a connection. Modelled as a union rather than
 *  throwing, because every branch here is an ordinary, expected outcome (unknown id, wrong
 *  transport, disabled row, stale authorization) — none of them is exceptional. */
type ProbeTargetResolution = { readonly ok: true; readonly target: ProbeTarget } | { readonly ok: false; readonly status: number; readonly body: Record<string, unknown> };

/** Refuses a `stdio` row (D-7), a disabled row, and the common `needs_reauth` case, all from the
 *  record alone — before any credential is ever resolved. Split out of {@link resolveProbeTarget}
 *  purely to keep that function's complexity under the shop ceiling.
 *  @returns The response to send, or `null` to continue resolving.
 *  @complexity O(1). */
function refuseBeforeResolving(record: ExternalMcpServerRecord, serverId: string): Extract<ProbeTargetResolution, { ok: false }> | null {
  if (record.transport === "stdio") {
    return {
      ok: false,
      status: 400,
      body: {
        error: "probe is not available for local-command servers yet — type tool names directly instead",
        code: "PROBE_UNSUPPORTED_TRANSPORT",
        details: { field: "transport" },
      },
    };
  }
  if (!record.enabled) {
    return {
      ok: false,
      status: 400,
      body: { error: "this server is disabled — enable it before probing", code: "MCP_SERVER_DISABLED", details: { field: "enabled" } },
    };
  }
  if (resolveExternalMcpAuthMode(record) === "oauth" && resolveExternalMcpOAuthStatus(record) === "needs_reauth") {
    const error = new ExternalMcpReauthRequiredError({ serverId, label: record.label });
    return { ok: false, status: 409, body: { error: error.message, code: error.code, details: { retryable: false, settingsLink: error.settingsLink } } };
  }
  return null;
}

/** Turns one `readEnabledExternalMcpConfigs` MISS (the server resolved to neither a usable config
 *  nor — because it is enabled and past the early checks — anything but a failure entry) into a
 *  response. Split out of {@link resolveProbeTarget} purely to keep that function's complexity under
 *  the shop ceiling.
 *  @complexity O(1) given the caller already located `failure`. */
function respondToResolutionFailure(serverId: string, reason: string): Extract<ProbeTargetResolution, { ok: false }> {
  /** `true` only for the fixed prose {@link resolveProbeTarget}'s failure branch and
   *  `external-mcp-oauth.ts`'s `ExternalMcpReauthRequiredError` share today — see this file's header
   *  on the residual race this covers: a row whose STORED status is `"connected"` but whose live token
   *  refresh fails with an invalid grant during this exact probe call. The common case (a row already
   *  parked `needs_reauth`) never reaches this function — {@link refuseBeforeResolving} catches the
   *  stored status directly, before `readEnabledExternalMcpConfigs` is ever called. A future wording
   *  change in either source string would silently widen this to the generic 502 branch instead of
   *  409, never the other direction — the safer failure mode for a coupling this loose. */
  if (reason.includes("authorization expired or was revoked")) {
    return {
      ok: false,
      status: 409,
      body: { error: reason, code: "EXTERNAL_MCP_REAUTH_REQUIRED", details: { retryable: false, settingsLink: externalMcpSettingsDeepLink(serverId) } },
    };
  }
  return { ok: false, status: 502, body: { error: reason, code: "MCP_SERVER_UNREACHABLE" } };
}

/** Resolves one `serverId` into a probeable target, or the exact response to send instead. Never
 *  spawns a child process — see this file's D-7 header. Built on `readEnabledExternalMcpConfigs`/
 *  `toResolvedFederatedConnections`, the same pair the daemon's own boot path resolves credentials
 *  through, so a probe's target is derived exactly the way a real connect would be, rather than by a
 *  second, parallel reading of the row.
 *  @complexity O(n) in the workspace's configured server count — bounded by the store's own
 *  per-workspace server cap. */
async function resolveProbeTarget(deps: ExternalMcpProbeServiceDeps, serverId: string): Promise<ProbeTargetResolution> {
  const record = await deps.externalMcpServerRepo.findByServerId({ workspaceId: deps.workspaceId, serverId });
  if (!record) {
    return { ok: false, status: 400, body: { error: `no external MCP server is configured as '${serverId}'`, code: "INVALID_MCP_SERVER", details: { field: "id" } } };
  }

  const earlyRefusal = refuseBeforeResolving(record, serverId);
  if (earlyRefusal) return earlyRefusal;

  const { configs, failures } = await readEnabledExternalMcpConfigs(
    { repo: deps.externalMcpServerRepo, sealer: deps.siteAssistantSecretSealer, oauth: deps.externalMcpOAuth?.tokenResolver },
    deps.workspaceId,
  );

  const config = configs.find((candidate) => candidate.serverId === serverId);
  if (!config) {
    const failure = failures.find((candidate) => candidate.serverId === serverId);
    return respondToResolutionFailure(serverId, failure?.reason ?? "this server's connection could not be resolved");
  }

  const [resolved] = toResolvedFederatedConnections([config]);
  // Defensive, not reachable given the transport check above (`config.transport` mirrors
  // `record.transport` — both come from the same row): the whole point of D-7 is that this route
  // must never launch a child process, and a launch-spec SHAPE check right before connecting is the
  // cheapest possible second guarantee of that, independent of whatever produced `resolved`.
  if (!resolved || !("url" in resolved.launch)) {
    return { ok: false, status: 400, body: { error: "probe is not available for local-command servers yet", code: "PROBE_UNSUPPORTED_TRANSPORT" } };
  }

  return { ok: true, target: { federationConfig: resolved.config, launch: resolved.launch } };
}

/** Recognizes the probe's supported opaque HTTP and typed MCP authentication failures. */
function isProbeAuthFailure({ error }: { error: unknown }, _options = {}): boolean {
  const status = error && typeof error === 'object' ? (error as { status?: unknown; statusCode?: unknown }).status ?? (error as { statusCode?: unknown }).statusCode : undefined;
  return status === 401 || status === 403 || error instanceof McpAuthFailedError || (error instanceof McpProtocolError && /with HTTP (401|403)$/.test(error.message));
}

/** Only real Error instances and recognized protocol messages count as timeouts. */
function isProbeTimeoutFailure({ error }: { error: unknown }, _options = {}): boolean {
  return error instanceof Error && (error.name === 'AbortError' || error.name === 'TimeoutError' || (error instanceof McpProtocolError && /request (?:timed out|was aborted)/.test(error.message)));
}

/** Connects once, lists, describes, and closes — the `finally` is the whole safety story for the
 *  outbound session, matching W-002's own framing in the implementation outline. Split out of the
 *  route handler purely to keep it under the shop ceiling.
 *  @complexity O(t) in the remote's advertised tool count, plus one round trip. */
async function runProbe(connect: ExternalMcpProbeSessionFactory, target: ProbeTarget): Promise<{ ok: true; tools: ReturnType<typeof describeRemoteToolSurface> } | { ok: false; kind: "auth" | "timeout" | "unreachable" }> {
  let session: McpSessionPort | undefined;
  try {
    session = await connect(target.launch, target.federationConfig.connectTimeoutMs);
    const tools = await session.listTools();
    return { ok: true, tools: describeRemoteToolSurface({ tools, config: target.federationConfig }) };
  } catch (err) {
    // Report the failed connection without logging upstream errors that may contain credentials.
    // Upstream bodies/errors may contain credentials; only the closed category crosses this boundary.
    const auth = isProbeAuthFailure({ error: err });
    const timeout = isProbeTimeoutFailure({ error: err });
    return { ok: false, kind: auth ? 'auth' : timeout ? 'timeout' : 'unreachable' };
  } finally {
    await session?.close({}).catch(() => undefined);
  }
}

/** Resolves credentials, probes once, then closes. Expected refusals retain the admin response contract.
 * OAuth resolution can refresh and persist a grant, so this operation is not declared read-only.
 * @complexity O(n + t) time and O(n + t) space for saved servers and advertised tools, plus bounded I/O.
 */
export async function probeExternalMcpServer(deps: ExternalMcpProbeServiceDeps, serverId: string) {
  const resolution = await resolveProbeTarget(deps, serverId);
  if (!resolution.ok) return resolution;
  const outcome = await runProbe(deps.connect ?? defaultProbeConnect, resolution.target);
  if (!outcome.ok) {
    const failure = { auth: { status: 401, code: 'MCP_AUTH_REJECTED' }, timeout: { status: 504, code: 'MCP_TIMEOUT' }, unreachable: { status: 502, code: 'MCP_SERVER_UNREACHABLE' } }[outcome.kind];
    return { ok: false as const, status: failure.status, body: { error: credentialText({ id: outcome.kind }), code: failure.code } };
  }
  return { ok: true as const, body: { tools: outcome.tools, probedAt: new Date(deps.clock.nowMs()).toISOString() } };
}

/** Cloudflare-only HTTP owner. All network effects use the injected, traced host transport. */
export const API_ROOT = 'https://api.cloudflare.com/client/v4';
export const segment = ({ value }, _options = {}) => encodeURIComponent(value);
/** Cloudflare rejects `per_page` above 10 on the Pages projects list (error 8000024, HTTP 400). */
export const PAGES_PROJECTS_PAGING = { perPage: 10, maxPages: 11 };
/** Cloudflare caps `per_page` at 50 on the zones list (the default 100 is refused). */
export const ZONES_PAGING = { perPage: 50, maxPages: 20 };

/** Safe, stable refusal; upstream bodies can contain credentials and never cross this boundary. */
export function refusal({ kit, code, message, status = 400 }, _options = {}) {
  const error = new kit.DeployError(`${code}: ${message}`, status, { errorCode: code });
  error.code = code;
  return error;
}

function nextStep({ status }, _options = {}) {
  if (status === 401 || status === 403) return 'Check the token permissions and account/zone scope in the Cloudflare skill, then preview again.';
  if (status === 429) return 'Cloudflare is rate limiting this account. Wait, then preview again.';
  return 'Check the named resource in Cloudflare, then preview again.';
}

/** Bind credential and HTTP once. Requests never follow redirects with a bearer token. */
export function createApi({ credential, kit }, _options = {}) {
  if (!credential.token || !credential.accountId) throw refusal({ kit, code: 'CLOUDFLARE_CREDENTIAL_REQUIRED', message: 'Save a Cloudflare API token and Account ID in the secure connection form.' });
  const accountPath = `/accounts/${segment({ value: credential.accountId })}`;
  async function response({ path, method = 'GET', body, jwt }, options = {}) {
    const init = requestInit({ method, body, token: jwt ?? credential.token });
    let resp;
    try { resp = await kit.fetch(`${API_ROOT}${path}`, init, { timeoutMs: options.timeoutMs ?? kit.timeouts.QUICK }); }
    catch { throw refusal({ kit, code: 'CLOUDFLARE_UNREACHABLE', message: `${method} ${path} could not reach Cloudflare. Check your connection and retry.`, status: 502 }); }
    if (options.allowMissing && resp.status === 404) return { missing: true };
    return decodeResponse({ resp, method, path, kit });
  }
  async function request(input, options = {}) {
    const json = await response(input, options);
    if (json.missing) return null;
    return json.result ?? json;
  }
  async function list({ path }, { maxPages = 100, perPage = 100 } = {}) {
    const items = [];
    let pagination = { count: 0, pages: 0 };
    for (let page = 1; page <= maxPages; page += 1) {
      const separator = path.includes('?') ? '&' : '?';
      const json = await response({ path: `${path}${separator}page=${page}&per_page=${perPage}` });
      if (!Array.isArray(json.result)) throw refusal({ kit, code: 'CLOUDFLARE_INVENTORY_UNKNOWN', message: `${path} did not return a complete list. Check read permissions and preview again.`, status: 502 });
      items.push(...json.result);
      pagination = paginationState({ previous: pagination, info: json.result_info });
      if (items.length > maxPages * perPage) throw refusal({ kit, code: 'CLOUDFLARE_INVENTORY_UNKNOWN', message: `${path} exceeded the inventory item limit. Narrow the account and preview again.`, status: 409 });
      const more = hasNextPage({ info: json.result_info, page, perPage, count: json.result.length });
      assertCompletePage({ kit, path, pagination, itemCount: items.length, lastCount: json.result.length, more });
      if (!more) return items;
    }
    throw refusal({ kit, code: 'CLOUDFLARE_INVENTORY_UNKNOWN', message: `${path} exceeded the ${maxPages}-page inventory limit. Narrow the account scope or contact support; no domain changes are safe.`, status: 409 });
  }
  return { request, list, accountPath, accountId: credential.accountId, zoneId: credential.zoneId, kit };
}

function paginationState({ previous, info }, _options = {}) {
  return { count: Math.max(previous.count, Number(info?.total_count) || 0), pages: Math.max(previous.pages, Number(info?.total_pages) || 0) };
}
function assertCompletePage({ kit, path, pagination, itemCount, lastCount, more }, _options = {}) {
  if ((!more && itemCount < pagination.count) || (lastCount === 0 && pagination.pages > 1)) throw refusal({ kit, code: 'CLOUDFLARE_INVENTORY_UNKNOWN', message: `${path} returned an incomplete inventory page. Refresh read permissions and preview again; no domain changes are safe.`, status: 409 });
}

async function decodeResponse({ resp, method, path, kit }, _options = {}) {
  let json;
  try { json = await resp.json(); }
  catch { throw refusal({ kit, code: 'CLOUDFLARE_INVALID_RESPONSE', message: `${method} ${path} returned unreadable data. Retry; if it persists check Cloudflare status.`, status: 502 }); }
  if (json === null || typeof json !== 'object') throw refusal({ kit, code: 'CLOUDFLARE_INVALID_RESPONSE', message: `${method} ${path} returned no usable response object. Retry the request and check Cloudflare status.`, status: 502 });
  if (!resp.ok || json?.success === false) throw apiFailure({ kit, json, method, path, status: resp.status });
  return json;
}

function apiFailure({ kit, json, method, path, status }, _options = {}) {
  const error = refusal({ kit, code: 'CLOUDFLARE_API_ERROR', message: `${method} ${path} failed (HTTP ${status}). ${nextStep({ status })}`, status });
  // Classify duplicate creation races without returning Cloudflare's potentially secret-bearing text.
  const errors = Array.isArray(json.errors) ? json.errors : [];
  error.details.alreadyExists = errors.some(item => /already exist|already bound|already been taken|already in use|duplicate/i.test(String(item?.message)));
  return error;
}

function requestInit({ method, body, token }, _options = {}) {
  const headers = { Authorization: `Bearer ${token}` };
  const init = { method, headers, redirect: 'error' };
  if (body instanceof FormData) init.body = body;
  else if (body !== undefined) { headers['Content-Type'] = 'application/json'; init.body = JSON.stringify(body); }
  return init;
}

/** Empty pages before a reported end are incomplete, not evidence of absence. */
function hasNextPage({ info, page, perPage, count }, _options = {}) {
  if (Number.isFinite(info?.total_pages)) return page < info.total_pages;
  if (Number.isFinite(info?.total_count)) return page * (info.per_page ?? perPage) < info.total_count;
  return count >= perPage;
}

import { createHash } from 'node:crypto';
import { refusal } from './api.mjs';

/** Stable Pages/Workers dedup key; native crypto avoids a native/WASM dependency.
 * Retains Pages' historical data+extension hash so existing uploads stay deduplicated. */
/**
   * Deterministic content hash used purely as Cloudflare Pages' per-asset
   * dedup key (the direct-upload protocol needs a stable 32-hex-char key per
   * file, not a specific algorithm). Swapped from the OD origin's
   * `blake3-wasm` to Node's built-in `crypto` so this package carries no
   * native/WASM dependency — see `source-map.md`.
   */
export function assetHash({ file, data }, _options = {}) {
  const extension = file.includes('.') ? file.slice(file.lastIndexOf('.') + 1) : '';
  return createHash('sha256').update(`${Buffer.from(data).toString('base64')}${extension}`).digest('hex').slice(0, 32);
}

/** Root _headers/_redirects are configuration, never public assets. A nested copy remains an asset.
 * Host security headers replace the site's root _headers because they are host policy.
 * @complexity O(n + bytes) time and space; n is capped by the selected hosting plan. */
export function prepareAssets({ files, responseHeaders, kit }, { maxFiles = 20_000 } = {}) {
  const normalized = files.map(file => ({ ...file, file: file.file.replaceAll('\\', '/').replace(/^\.\//, '') }));
  const headers = responseHeaders && Object.keys(responseHeaders).length > 0;
  const supplied = headers ? [...normalized.filter(file => file.file !== '_headers'), { file: '_headers', data: renderHeaders({ headers: responseHeaders }) }] : normalized;
  if (supplied.length > maxFiles) throw refusal({ kit, code: 'CLOUDFLARE_ASSET_COUNT_LIMIT', message: `${supplied.length} files exceed this destination's ${maxFiles}-file limit (including generated files). Reduce the export or explicitly select a supported paid Workers plan.` });
  const manifest = {};
  const byHash = new Map();
  const config = {};
  for (const file of supplied) addAsset({ file, manifest, byHash, config, kit });
  return { manifest, byHash, config };
}

function addAsset({ file, manifest, byHash, config, kit }, _options = {}) {
  if (!file.file || file.file.startsWith('/') || file.file.split('/').includes('..')) throw refusal({ kit, code: 'CLOUDFLARE_ASSET_PATH', message: `Export path ${file.file} must be relative without '..'. Fix the export and retry.` });
  const data = Buffer.from(file.data);
  if (data.length > 25 * 1024 * 1024) throw refusal({ kit, code: 'CLOUDFLARE_ASSET_SIZE_LIMIT', message: `${file.file} exceeds 25 MiB. Resize the file and export again.` });
  if (file.file === '_headers' || file.file === '_redirects') { config[file.file] = data.toString('utf8'); return; }
  const path = `/${file.file}`;
  if (Object.hasOwn(manifest, path)) throw refusal({ kit, code: 'CLOUDFLARE_ASSET_PATH', message: `Duplicate export path ${path}. Fix the export and retry.` });
  const hash = assetHash({ file: file.file, data });
  manifest[path] = { hash, size: data.length };
  byHash.set(hash, { hash, data, contentType: file.contentType ?? 'application/octet-stream' });
}

export function renderHeaders({ headers }, _options = {}) {
  return `/*\n${Object.entries(headers).map(([name, value]) => `  ${name}: ${value}`).join('\n')}\n`;
}

/** Respect both Pages limits. A single oversize request is refused before any upload.
 * @complexity O(n) over unique missing assets; at most 100 per request. */
export function chunkUploads({ files }, { maxFiles = 100, maxBytes = 75 * 1024 * 1024 } = {}) {
  const chunks = [];
  let chunk = [];
  let bytes = 2; // JSON array brackets.
  for (const file of files) {
    const size = Math.ceil(file.data.length / 3) * 4 + Buffer.byteLength(file.contentType) + file.hash.length + 128;
    if (size + 2 > maxBytes) throw new Error('CLOUDFLARE_UPLOAD_LIMIT: One asset cannot fit in the upload request. Reduce its size.');
    if (chunk.length >= maxFiles || bytes + size > maxBytes) { chunks.push(chunk); chunk = []; bytes = 2; }
    chunk.push(file);
    bytes += size;
  }
  if (chunk.length) chunks.push(chunk);
  return chunks;
}

import { readFile } from 'node:fs/promises';
import { refusal, segment } from './api.mjs';

/** Form submissions destination: one D1 database per site Worker plus the bundled receiver.
 * Forms, fields and full validation stay in Tovu; this file only provisions storage and transport. */
export const FORMS_BINDING = 'TOVU_FORMS';
export const FORMS_SECRET_BINDING = 'TOVU_FORMS_SECRET';
/** Routed to the Worker before static assets, so a missing asset can never answer a form POST. */
export const FORMS_WORKER_ROUTES = ['/forms/*', '/_tovu/*'];
export const FREE_PLAN_NOTE = 'Free plan limits: 100,000 Worker requests/day, D1 100,000 row writes/day and 500 MB per database (shared with the rest of this Cloudflare account).';
const D1_PAGING = { perPage: 100, maxPages: 10 };
const SLUG = /^[a-z0-9][a-z0-9-]{0,99}$/;
const FIELD_NAME = /^[A-Za-z0-9_.[\]-]{1,100}$/;
const MAX_FORMS = 50;
const MAX_FIELDS = 100;

/** Forward-only, plugin-owned. Append a new version; never edit or reorder an applied one. */
export const MIGRATIONS = Object.freeze([
  { version: 1, sql: [
    'CREATE TABLE IF NOT EXISTS submissions (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, form_slug TEXT NOT NULL, answers_json TEXT NOT NULL, submitted_at TEXT NOT NULL, ip TEXT NULL, pulled_at TEXT NULL)',
    'CREATE INDEX IF NOT EXISTS submissions_pending ON submissions (pulled_at, seq)',
    'CREATE TABLE IF NOT EXISTS rate_windows (key TEXT PRIMARY KEY, window_start INTEGER NOT NULL, count INTEGER NOT NULL)',
    'CREATE INDEX IF NOT EXISTS rate_windows_start ON rate_windows (window_start)',
  ] },
]);
const MIGRATIONS_TABLE = 'CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL)';

/** Validates the host's generic `formDestination` input. `null` means no active forms: assets-only Worker.
 * @complexity O(forms * fields), both capped. */
export function normalizeForms({ formDestination, kit }, { requireSecret = true } = {}) {
  const forms = formDestination?.forms ?? [];
  if (!Array.isArray(forms) || forms.length > MAX_FORMS) throw formsRefusal({ kit, message: `Expected at most ${MAX_FORMS} forms in the form manifest. Disable unused forms in Tovu, then publish again.` });
  if (forms.length === 0) return null;
  const secret = formDestination.secret;
  if (requireSecret) checkReceiverSecret({ secret, kit });
  return { forms: forms.map(form => normalizeForm({ form, kit })), secret };
}

function checkReceiverSecret({ secret, kit }, _options = {}) {
  if (typeof secret !== 'string' || secret.length < 32) throw formsRefusal({ kit, message: 'The form receiver key is missing. Publish again from Tovu so it can create the key.' });
}

function normalizeForm({ form, kit }, _options = {}) {
  if (!SLUG.test(form?.slug ?? '')) throw formsRefusal({ kit, message: `Form slug "${String(form?.slug).slice(0, 100)}" cannot be served here. Use lowercase letters, digits and hyphens, then publish again.` });
  checkFieldCount({ form, kit });
  const successPath = form.successPath;
  checkSuccessPath({ form, successPath, kit });
  return { slug: form.slug, fields: form.fields.map(field => normalizeField({ field, kit, slug: form.slug })), ...(successPath ? { successPath } : {}) };
}

function checkFieldCount({ form, kit }, _options = {}) {
  if (!Array.isArray(form.fields) || form.fields.length === 0 || form.fields.length > MAX_FIELDS) throw formsRefusal({ kit, message: `Form ${form.slug} needs 1-${MAX_FIELDS} fields. Fix the form in Tovu, then publish again.` });
}

function checkSuccessPath({ form, successPath, kit }, _options = {}) {
  if (successPath === undefined) return;
  if (typeof successPath !== 'string' || !/^\/(?![/\\])[^\\\s]{0,499}$/.test(successPath)) throw formsRefusal({ kit, message: `Form ${form.slug} has an unusable success page. Use a path on this site starting with "/".` });
}

function normalizeField({ field, kit, slug }, _options = {}) {
  if (!FIELD_NAME.test(field?.name ?? '')) throw formsRefusal({ kit, message: `Form ${slug} has a field name that cannot be served here. Rename the field in Tovu, then publish again.` });
  const max = field.maxLength;
  checkMaxLength({ max, kit, slug, name: field.name });
  return { name: field.name, required: field.required === true, ...(Number.isInteger(max) ? { maxLength: max } : {}), ...(field.multiple === true ? { multiple: true } : {}) };
}

function checkMaxLength({ max, kit, slug, name }, _options = {}) {
  if (max === undefined || max === null) return;
  if (!(Number.isInteger(max) && max >= 1 && max <= 5000)) throw formsRefusal({ kit, message: `Form ${slug} field ${name} has an invalid maximum length. Use 1-5000.` });
}

function formsRefusal({ kit, message, status = 400, code = 'CLOUDFLARE_FORMS_INVALID' }, _options = {}) {
  return refusal({ kit, code, message, status });
}

/** Stable per-site identity derived from the Worker name; never random, so republish reuses it. */
export function databaseName({ resourceName }, _options = {}) {
  return `tovu-forms-${resourceName}`.slice(0, 63);
}

const PERMISSION_STEP = 'Edit the saved Cloudflare API token: add Account > D1 > Edit (dashboard: My Profile > API Tokens > the token > Edit), keep its existing Workers permissions, then preview again.';

/** Exact-name lookup. A 401/403 is reported as the missing D1 permission, never as "absent". */
export async function findDatabase({ api, kit, name }, _options = {}) {
  try {
    const items = await api.list({ path: `${api.accountPath}/d1/database?name=${segment({ value: name })}` }, D1_PAGING);
    return items.find(item => item.name === name) ?? null;
  } catch (error) {
    if (error.status === 401 || error.status === 403) throw formsRefusal({ kit, code: 'CLOUDFLARE_D1_PERMISSION_REQUIRED', status: 403, message: `Form submissions need D1 access. ${PERMISSION_STEP}` });
    throw error;
  }
}

/** Read-only preview lines for the publish confirmation. Pages has no receiver in v1.
 * @complexity One bounded D1 inventory read. */
export async function previewForms({ api, kit, resourceName, targetId, formDestination }, _options = {}) {
  const normalized = normalizeForms({ formDestination, kit }, { requireSecret: false });
  if (!normalized) return undefined;
  const count = normalized.forms.length;
  if (targetId !== 'cloudflare-workers') {
    return { status: 'unsupported', forms: count, changes: [], message: `This site has ${count} active form(s), but Cloudflare Pages publishing cannot receive submissions yet. Publish to Cloudflare Workers to accept form submissions; on Pages the forms will not submit.` };
  }
  const name = databaseName({ resourceName });
  let existing;
  try { existing = await findDatabase({ api, kit, name }); }
  catch (error) {
    if (error.code !== 'CLOUDFLARE_D1_PERMISSION_REQUIRED') throw error;
    return { status: 'permission-required', forms: count, changes: [], message: error.message.replace(/^CLOUDFLARE_D1_PERMISSION_REQUIRED: /, '') };
  }
  return { status: 'on', forms: count,
    changes: [{ action: existing ? 'reuse' : 'create', resource: 'd1-database', name, ...(existing ? { databaseId: existing.uuid } : {}) },
      { action: 'bind', resource: 'worker', resourceName, routes: FORMS_WORKER_ROUTES }],
    message: `Form submissions: on (${count} form${count === 1 ? '' : 's'}). Submissions are stored in D1 database ${name} (${existing ? 'reused' : 'created'}) in this Cloudflare account and pulled into Tovu admin on demand. ${FREE_PLAN_NOTE}` };
}

/** Find-or-create the database, then apply pending migrations. Never drops or recreates anything.
 * @complexity One inventory read, at most one create, 2 + pending-migration queries. */
export async function provisionForms({ api, kit, resourceName }, _options = {}) {
  const name = databaseName({ resourceName });
  const database = await findDatabase({ api, kit, name }) ?? await createDatabase({ api, kit, name });
  if (typeof database?.uuid !== 'string' || !database.uuid) throw formsRefusal({ kit, code: 'CLOUDFLARE_D1_INVALID', status: 502, message: `D1 database ${name} returned no id. Check it in the Cloudflare dashboard, then publish again.` });
  const applied = await migrate({ api, kit, databaseId: database.uuid });
  return { databaseId: database.uuid, databaseName: name, applied };
}

async function createDatabase({ api, kit, name }, _options = {}) {
  try { return await api.request({ path: `${api.accountPath}/d1/database`, method: 'POST', body: { name } }); }
  catch (error) {
    // A concurrent publish may have created it first; the exact-name lookup is authoritative.
    if (!error.details?.alreadyExists) throw error;
    return findDatabase({ api, kit, name });
  }
}

async function query({ api, databaseId, sql, params = [] }, _options = {}) {
  const result = await api.request({ path: `${api.accountPath}/d1/database/${segment({ value: databaseId })}/query`, method: 'POST', body: { sql, params } });
  return Array.isArray(result) ? result.flatMap(item => item?.results ?? []) : [];
}

/** Applies each missing version in order; returns the versions applied by this call. */
export async function migrate({ api, kit, databaseId }, _options = {}) {
  await query({ api, databaseId, sql: MIGRATIONS_TABLE });
  const rows = await query({ api, databaseId, sql: 'SELECT version FROM schema_migrations' });
  const done = new Set(rows.map(row => Number(row.version)));
  const applied = [];
  for (const migration of MIGRATIONS.filter(item => !done.has(item.version))) {
    // Every statement is idempotent (IF NOT EXISTS), so a version interrupted before its marker reruns safely.
    // One statement per request: the REST endpoint binds `params` to a single statement.
    for (const sql of migration.sql) await query({ api, databaseId, sql });
    await query({ api, databaseId, sql: 'INSERT OR IGNORE INTO schema_migrations (version, applied_at) VALUES (?, ?)', params: [migration.version, new Date(kit.now?.() ?? Date.now()).toISOString()] });
    applied.push(migration.version);
  }
  return applied;
}

let receiverSource;
/** The receiver module text, read once from this plugin's own folder (path-separator safe). */
export async function receiverModule(_required = {}, _options = {}) {
  receiverSource ??= await readFile(new URL('../worker/forms-receiver.mjs', import.meta.url), 'utf8');
  return receiverSource;
}

const MAX_PAGE_ROUTES = 90;
const FORM_MARKER = /<form\b[^>]*\bdata-form-slug="/i;
/** Exact routes of exported pages that contain one of the site's forms, so the Worker runs first on
 * them and can show the "sent" state after a submission. Other pages and every asset stay on the free
 * static path. Over the cap only the first pages are listed; the submission itself works everywhere.
 * @complexity O(HTML bytes). */
export function formPageRoutes({ files }, { max = MAX_PAGE_ROUTES } = {}) {
  const routes = [];
  for (const file of files ?? []) {
    const path = String(file.file ?? '').replaceAll('\\', '/').replace(/^\.?\//, '');
    if (!path.endsWith('.html') || !FORM_MARKER.test(Buffer.from(file.data ?? '').toString('utf8'))) continue;
    const page = routesForPage({ path });
    if (routes.length + page.length > max) break;
    routes.push(...page);
  }
  return routes;
}

/** `a/index.html` answers at `/a/` and `/a`; `a.html` at `/a.html` and `/a` (auto-trailing-slash). */
function routesForPage({ path }, _options = {}) {
  if (path === 'index.html') return ['/'];
  if (path.endsWith('/index.html')) { const dir = `/${path.slice(0, -'index.html'.length)}`; return [dir, dir.slice(0, -1)]; }
  return [`/${path}`, `/${path.slice(0, -'.html'.length)}`];
}

/** Worker modules and bindings for a site with forms. The manifest is compiled in; visitors never supply it. */
export async function formsWorkerParts({ manifest, secret, databaseId }, { pageRoutes = [] } = {}) {
  const main = "import { handleRequest } from './receiver.mjs';\nimport manifest from './forms-manifest.mjs';\nexport default { fetch: (request, env) => handleRequest({ request, env, manifest }) };\n";
  return {
    modules: [
      { name: 'index.mjs', source: main },
      { name: 'receiver.mjs', source: await receiverModule() },
      { name: 'forms-manifest.mjs', source: `export default ${JSON.stringify({ forms: manifest.forms })};\n` },
    ],
    bindings: [{ type: 'd1', name: FORMS_BINDING, id: databaseId }, { type: 'secret_text', name: FORMS_SECRET_BINDING, text: secret }],
    runWorkerFirst: [...FORMS_WORKER_ROUTES, ...pageRoutes],
  };
}

/** Private pull API client. The receiver key travels only in the Authorization header. */
async function receiverCall({ kit, destination, path, init = {} }, _options = {}) {
  const origin = receiverOrigin({ kit, url: destination?.url });
  if (typeof destination.secret !== 'string' || destination.secret.length < 32) throw formsRefusal({ kit, code: 'CLOUDFLARE_FORMS_KEY_REQUIRED', message: 'The form receiver key is missing. Republish the site so Tovu can reinstall it, then pull again.' });
  const resp = await receiverFetch({ kit, origin, path, init, secret: destination.secret });
  checkReceiverStatus({ kit, origin, resp });
  try { return await resp.json(); }
  catch { throw formsRefusal({ kit, code: 'CLOUDFLARE_FORMS_INVALID_RESPONSE', status: 502, message: `${origin} returned unreadable data. Republish the site, then pull again.` }); }
}

async function receiverFetch({ kit, origin, path, init, secret }, _options = {}) {
  try { return await kit.fetch(`${origin}${path}`, { ...init, headers: { ...init.headers, Authorization: `Bearer ${secret}` }, redirect: 'error' }, { timeoutMs: kit.timeouts.QUICK }); }
  catch { throw formsRefusal({ kit, code: 'CLOUDFLARE_FORMS_UNREACHABLE', status: 502, message: `${origin} could not be reached. Check the site is published, then pull again.` }); }
}

function checkReceiverStatus({ kit, origin, resp }, _options = {}) {
  if (resp.status === 401) throw formsRefusal({ kit, code: 'CLOUDFLARE_FORMS_UNAUTHORIZED', status: 401, message: `${origin} refused the form receiver key. Republish the site to reinstall the key, then pull again.` });
  if (resp.status === 404 || resp.status === 405) throw formsRefusal({ kit, code: 'CLOUDFLARE_FORMS_RECEIVER_MISSING', status: 404, message: `${origin} has no form receiver. Republish the site with at least one active form, then pull again.` });
  if (!resp.ok) throw formsRefusal({ kit, code: 'CLOUDFLARE_FORMS_UNAVAILABLE', status: 502, message: `${origin} answered HTTP ${resp.status}. Retry the pull in a few minutes.` });
}

function receiverOrigin({ kit, url }, _options = {}) {
