    if (!response.ok) return { ok: false, code: "provider-error", message: await providerErrorMessage(response, "GitHub repository lookup failed") };
    const body = await readJsonBody(response);
    if (!body.ok) return { ok: false, code: "provider-error", message: body.message };
    const defaultBranch = typeof body.json.default_branch === "string" ? body.json.default_branch : "main";
    return /** @type {const} */ ({ ok: true, defaultBranch });
  }

  /** A 404 is a branch that does not exist yet (the commit creates it). @param {string} token
   *  @param {string} owner @param {string} repo @param {string} branch
   *  @returns {Promise<{ ok: true, tipSha: string | undefined } | StepFailure>} */
  async function fetchBranchTip(token, owner, repo, branch) {
    const result = await githubFetch(`${GITHUB_API}/repos/${enc(owner)}/${enc(repo)}/git/ref/heads/${encPath(branch)}`, { headers: githubHeaders(token) });
    if (result.kind !== "response") return nonResponseFailure(result);
    const { response } = result;
    if (response.status === 404) return { ok: true, tipSha: undefined };
    if (!response.ok) return { ok: false, code: "provider-error", message: await providerErrorMessage(response, "GitHub branch lookup failed") };
    const body = await readJsonBody(response);
    if (!body.ok) return { ok: false, code: "provider-error", message: body.message };
    const object = body.json.object;
    const sha = isPlainObject(object) && typeof object.sha === "string" ? object.sha : "";
    if (!sha) return { ok: false, code: "provider-error", message: "GitHub branch lookup response did not include a sha" };
    return { ok: true, tipSha: sha };
  }

  /** Fails the whole commit on failure (see this file's header). @param {string} token @param {string} owner
   *  @param {string} repo @param {string} commitSha @returns {Promise<{ ok: true, treeSha: string } | StepFailure>} */
  async function fetchParentTree(token, owner, repo, commitSha) {
    const result = await githubFetch(`${GITHUB_API}/repos/${enc(owner)}/${enc(repo)}/git/commits/${enc(commitSha)}`, { headers: githubHeaders(token) });
    if (result.kind !== "response") return nonResponseFailure(result);
    const { response } = result;
    if (!response.ok) return { ok: false, code: "provider-error", message: await providerErrorMessage(response, "GitHub parent-commit lookup failed") };
    const body = await readJsonBody(response);
    if (!body.ok) return { ok: false, code: "provider-error", message: body.message };
    const tree = body.json.tree;
    const sha = isPlainObject(tree) && typeof tree.sha === "string" ? tree.sha : "";
    if (!sha) return { ok: false, code: "provider-error", message: "GitHub parent-commit response did not include a tree sha" };
    return { ok: true, treeSha: sha };
  }

  /** @param {string} token @param {string} owner @param {string} repo @param {string} branch
   *  @returns {Promise<{ ok: true, files: readonly PreviouslyManagedFile[] } | StepFailure>} */
  async function fetchManagedManifest(token, owner, repo, branch) {
    const result = await githubFetch(`${GITHUB_API}/repos/${enc(owner)}/${enc(repo)}/contents/${encPath(MANAGED_MANIFEST_PATH)}?ref=${enc(branch)}`, { headers: githubHeaders(token) });
    if (result.kind !== "response") return nonResponseFailure(result);
    const { response } = result;
    if (response.status === 404) return { ok: true, files: [] }; // verified: no manifest yet — safe, not "unreadable"
    if (!response.ok) return { ok: false, code: "provider-error", message: await providerErrorMessage(response, "GitHub managed-manifest lookup failed") };

    const body = await readJsonBody(response);
    if (!body.ok) return { ok: false, code: "provider-error", message: "GitHub managed-manifest response did not parse as JSON — cannot confirm which paths this adapter previously owned." };
    const content = typeof body.json.content === "string" ? body.json.content : undefined;
    if (content === undefined) {
      return { ok: false, code: "provider-error", message: "GitHub managed-manifest response did not include file content — cannot confirm which paths this adapter previously owned." };
    }
    /** @type {unknown} */
    let parsed;
    try {
      parsed = JSON.parse(Buffer.from(content, "base64").toString("utf8"));
    } catch {
      return { ok: false, code: "provider-error", message: "GitHub managed-manifest content is not valid JSON — cannot confirm which paths this adapter previously owned." };
    }
    const files = parseManagedManifestShape(parsed);
    if (files === undefined) {
      return { ok: false, code: "provider-error", message: "GitHub managed-manifest content did not match a recognized shape — cannot confirm which paths this adapter previously owned." };
    }
    return { ok: true, files };
  }

  /** Soft-degrades: any failure is `unverifiable`, which keeps the path. @param {string} token
   *  @param {string} owner @param {string} repo @param {string} branch @param {string} path
   *  @returns {Promise<{ kind: "found", sha: string } | { kind: "confirmed-absent" } | { kind: "unverifiable" }>} */
  async function fetchLiveBlobSha(token, owner, repo, branch, path) {
    const result = await githubFetch(`${GITHUB_API}/repos/${enc(owner)}/${enc(repo)}/contents/${encPath(path)}?ref=${enc(branch)}`, { headers: githubHeaders(token) });
    if (result.kind !== "response") return { kind: "unverifiable" };
    if (result.response.status === 404) return { kind: "confirmed-absent" };
    if (!result.response.ok) return { kind: "unverifiable" };
    const body = await readJsonBody(result.response);
    if (!body.ok) return { kind: "unverifiable" };
    return typeof body.json.sha === "string" ? { kind: "found", sha: body.json.sha } : { kind: "unverifiable" };
  }

  /** @param {string} token @param {string} owner @param {string} repo @param {string | Buffer} data */
  function createBlob(token, owner, repo, data) {
    return postForSha(`${GITHUB_API}/repos/${enc(owner)}/${enc(repo)}/git/blobs`, { content: Buffer.from(data).toString("base64"), encoding: "base64" }, "blob creation", token);
  }

  /** One blob per distinct content (identical files share a blob). @param {string} token
   *  @param {string} owner @param {string} repo @param {readonly CommitFile[]} files */
  async function buildFileTreeEntries(token, owner, repo, files) {
    /** @type {Map<string, string>} */
    const blobShaByHash = new Map();
    /** @type {Record<string, unknown>[]} */
    const tree = [];
    const currentPaths = new Set();
    /** @type {{ path: string, sha: string }[]} */
    const currentFileShas = [];
    for (const file of files) {
      currentPaths.add(file.path);
      const hash = sha256Hex(file.data);
      let blobSha = blobShaByHash.get(hash);
      if (!blobSha) {
        const blobResult = await createBlob(token, owner, repo, file.data);
        if (!blobResult.ok) return blobResult;
        blobSha = blobResult.sha;
        blobShaByHash.set(hash, blobSha);
      }
      tree.push({ path: file.path, mode: "100644", type: "blob", sha: blobSha });
      currentFileShas.push({ path: file.path, sha: blobSha });
    }
    return /** @type {const} */ ({ ok: true, tree, currentPaths, currentFileShas });
  }

  /** @param {string} token @param {string} owner @param {string} repo @param {string} branch
   *  @param {readonly PreviouslyManagedFile[]} candidates */
  async function resolveDeletionCandidates(token, owner, repo, branch, candidates) {
    /** @type {Record<string, unknown>[]} */
    const deletions = [];
    /** @type {string[]} */
    const deletedPaths = [];
    /** @type {string[]} */
    const divergedPaths = [];
    for (const candidate of candidates) {
      if (candidate.sha === undefined) {
        divergedPaths.push(candidate.path);
        continue;
      }
      const verdict = classifyLiveResult(await fetchLiveBlobSha(token, owner, repo, branch, candidate.path), candidate.sha);
      if (verdict === "skip") continue;
      if (verdict === "diverged") {
        divergedPaths.push(candidate.path);
        continue;
      }
      deletedPaths.push(candidate.path);
      deletions.push({ path: candidate.path, mode: "100644", type: "blob", sha: null });
    }
    return { deletions, deletedPaths, divergedPaths };
  }

  /** @param {string} token @param {string} owner @param {string} repo @param {string} branch
   *  @param {readonly CommitFile[]} files @param {string | undefined} baseTreeSha
   *  @param {readonly PreviouslyManagedFile[] | undefined} previousManagedFiles */
  async function buildTree(token, owner, repo, branch, files, baseTreeSha, previousManagedFiles) {
    const fileTree = await buildFileTreeEntries(token, owner, repo, files);
    if (!fileTree.ok) return fileTree;

    const candidates = (previousManagedFiles ?? []).filter((f) => !fileTree.currentPaths.has(f.path) && f.path !== MANAGED_MANIFEST_PATH);
    const { deletions, deletedPaths, divergedPaths } = await resolveDeletionCandidates(token, owner, repo, branch, candidates);

    const manifestBlob = await createBlob(
      token,
      owner,
      repo,
      JSON.stringify({ version: 2, files: fileTree.currentFileShas.slice().sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0)) })
    );
    if (!manifestBlob.ok) return manifestBlob;

    const tree = [...fileTree.tree, ...deletions, { path: MANAGED_MANIFEST_PATH, mode: "100644", type: "blob", sha: manifestBlob.sha }];
    const treeResult = await postForSha(
      `${GITHUB_API}/repos/${enc(owner)}/${enc(repo)}/git/trees`,
      { tree, ...(baseTreeSha !== undefined ? { base_tree: baseTreeSha } : {}) },
      "tree creation",
      token
    );
    if (!treeResult.ok) return treeResult;
    return /** @type {const} */ ({ ok: true, sha: treeResult.sha, deletedPaths, divergedPaths });
  }

  /** @param {string} token @param {string} owner @param {string} repo @param {string} branch
   *  @param {string} sha @param {"create" | "update"} mode */
  async function writeRef(token, owner, repo, branch, sha, mode) {
    const url = mode === "create" ? `${GITHUB_API}/repos/${enc(owner)}/${enc(repo)}/git/refs` : `${GITHUB_API}/repos/${enc(owner)}/${enc(repo)}/git/refs/heads/${encPath(branch)}`;
    /** @type {RequestInit} */
    const init =
      mode === "create"
        ? { method: "POST", headers: githubHeaders(token, { "Content-Type": "application/json" }), body: JSON.stringify({ ref: `refs/heads/${branch}`, sha }) }
        : { method: "PATCH", headers: githubHeaders(token, { "Content-Type": "application/json" }), body: JSON.stringify({ sha }) };

    const result = await githubFetch(url, init);
    if (result.kind !== "response") return nonResponseFailure(result);
    const { response } = result;
    if (response.ok) return /** @type {const} */ ({ ok: true });
    if (mode === "update" && response.status === 422) {
      return /** @type {const} */ ({ ok: false, code: "diverged", message: "the branch has moved since this commit started — refusing to overwrite it" });
    }
    return { ok: false, code: "provider-error", message: await providerErrorMessage(response, `GitHub branch ${mode} failed`) };
  }

  /** A new branch has no parent, no base tree and no manifest. @param {string} token @param {string} owner
   *  @param {string} repo @param {string} branch @param {string | undefined} parentSha */
  async function resolveCommitPrerequisites(token, owner, repo, branch, parentSha) {
    if (parentSha === undefined) return /** @type {const} */ ({ ok: true, baseTreeSha: undefined, previousManagedFiles: undefined, parents: [] });

    const parentTreeResult = await fetchParentTree(token, owner, repo, parentSha);
    if (!parentTreeResult.ok) return parentTreeResult;
    const manifestResult = await fetchManagedManifest(token, owner, repo, branch);
    if (!manifestResult.ok) return manifestResult;
    return /** @type {const} */ ({ ok: true, baseTreeSha: parentTreeResult.treeSha, previousManagedFiles: manifestResult.files, parents: [parentSha] });
  }

  /** @param {{ input: { branch?: string }, defaultBranch: string }} required */
  function siteCommitBranch({ input, defaultBranch }, _options = {}) {
    return input.branch ?? defaultBranch;
  }

  /** @param {{ baseTreeSha: string | undefined, treeSha: string }} required */
  function unchangedSiteTree({ baseTreeSha, treeSha }, _options = {}) {
    return baseTreeSha !== undefined && baseTreeSha === treeSha;
  }

  /**
   * @param {{ token: string, owner: string, repo: string, branch?: string, commitMessage: string, files: readonly CommitFile[] }} input
   * @complexity O(f) requests in the file count, plus one per path a previous export owned and dropped.
   */
  return async function commitSite(input) {
    const { token, owner, repo, commitMessage, files } = input;

    const repoResult = await fetchRepo(token, owner, repo);
    if (!repoResult.ok) return repoResult;
    const branch = siteCommitBranch({ input, defaultBranch: repoResult.defaultBranch });

    const tipResult = await fetchBranchTip(token, owner, repo, branch);
    if (!tipResult.ok) return tipResult;
    const parentSha = tipResult.tipSha;
    const branchCreated = parentSha === undefined;

    const prereqs = await resolveCommitPrerequisites(token, owner, repo, branch, parentSha);
    if (!prereqs.ok) return prereqs;

    const treeResult = await buildTree(token, owner, repo, branch, files, prereqs.baseTreeSha, prereqs.previousManagedFiles);
    if (!treeResult.ok) return treeResult;

    if (unchangedSiteTree({ baseTreeSha: prereqs.baseTreeSha, treeSha: treeResult.sha })) {
      return { ok: false, code: "no-changes", message: "nothing changed since the branch's last commit" };
    }

    const commitResult = await postForSha(
      `${GITHUB_API}/repos/${enc(owner)}/${enc(repo)}/git/commits`,
      { message: commitMessage, tree: treeResult.sha, parents: prereqs.parents },
      "commit creation",
      token
    );
    if (!commitResult.ok) return commitResult;

    const refResult = await writeRef(token, owner, repo, branch, commitResult.sha, branchCreated ? "create" : "update");
    if (!refResult.ok) return refResult;

    return {
      ok: true,
      branch,
      branchCreated,
      commitSha: commitResult.sha,
      commitUrl: `https://github.com/${owner}/${repo}/commit/${commitResult.sha}`,
      filesChanged: files.length,
      filesDeleted: treeResult.deletedPaths.length,
      divergedPaths: treeResult.divergedPaths,
    };
  };
}

/** @param {{ kind: string, sha?: string }} liveResult @param {string} recordedSha @returns {"skip" | "diverged" | "delete"} */
function classifyLiveResult(liveResult, recordedSha) {
  if (liveResult.kind === "confirmed-absent") return "skip";
  if (liveResult.kind === "unverifiable") return "diverged";
  return liveResult.sha === recordedSha ? "delete" : "diverged";
}

/** @param {unknown} entry @returns {PreviouslyManagedFile | undefined} */
function parseManifestV2Entry(entry) {
  if (!isPlainObject(entry) || typeof entry.path !== "string") return undefined;
  const sha = typeof entry.sha === "string" && GIT_SHA_PATTERN.test(entry.sha) ? entry.sha : undefined;
  return { path: entry.path, sha };
}

/** v2 carries each path's blob sha; v1 only paths (every v1 path is treated as unverifiable).
 *  @param {unknown} parsed @returns {PreviouslyManagedFile[] | undefined} */
function parseManagedManifestShape(parsed) {
  if (!isPlainObject(parsed)) return undefined;
  if (parsed.version === 2 && Array.isArray(parsed.files)) {
    /** @type {PreviouslyManagedFile[]} */
    const files = [];
    for (const entry of parsed.files) {
      const one = parseManifestV2Entry(entry);
      if (!one) return undefined;
      files.push(one);
    }
    return files;
  }
  if (parsed.version === 1 && Array.isArray(parsed.paths) && parsed.paths.every((path) => typeof path === "string")) {
    return parsed.paths.map((path) => ({ path, sha: undefined }));
  }
  return undefined;
}

// @ts-check
import { createHash } from "node:crypto";

/**
 * @file Writes files into a GitHub repository through a saved custom credential, in ONE commit on top
 * of exactly the tree the human confirmed. Moved out of core
 * (`apps/website/src/features/custom-credentials/github-write-files.ts`) unchanged in behavior; the
 * low-level helpers here are shared with `backup-push.mjs`.
 *
 * Two phases. `planFileWrite` is read-only reconnaissance run BEFORE the confirmation dialog: the
 * branch tip, its tree, and whether each path already exists (so the dialog can say "update" or
 * "create"). `commitFiles` runs only after the human confirms, and builds on the plan's parent commit
 * and tree, so a branch that moved in between answers 422 on the (unforced) ref update and is
 * reported `diverged`, never overwritten.
 *
 * Every request goes through core's guarded HTTP client (`kit.httpClient`, egress policy applied)
 * with the `Authorization` header core built from the saved connection. A thrown send is
 * `network-unreachable` with fixed caller-safe text (an egress refusal says so); its detail is
 * `logDetail`, for the server log only.
 *
 * @typedef {import("./github.mjs").Kit} Kit
 * @typedef {{ baseUrl: string, authorization: string, owner: string, repo: string }} Target
 * @typedef {{ path: string, content: string }} WriteFile
 * @typedef {{ status: number, bodyText: string, headers?: Record<string, string> }} HttpResponse
 * @typedef {{ ok: false, code: "provider-error", message: string }
 *   | { ok: false, code: "network-unreachable", message: string, logDetail: string }} Failure
 */

const GITHUB_API_VERSION = "2026-03-10";
const GITHUB_WRITE_FILES_TIMEOUT_MS = 30_000;
/** The Contents API lists at most this many entries per directory; a full listing may be truncated. */
const CONTENTS_API_DIRECTORY_LISTING_CAP = 1000;
const GITHUB_UNREACHABLE_MESSAGE = "GitHub could not be reached: the request failed before any response arrived (a network error or timeout).";

/** @param {string} value */
export function enc(value) {
  return encodeURIComponent(value);
}

/** @param {string} path */
export function encPath(path) {
  return path.split("/").map(enc).join("/");
}

/** `<baseUrl>/repos/<owner>/<repo>`. @param {Target} target */
export function repoPathOf(target) {
  const base = target.baseUrl.endsWith("/") ? target.baseUrl.slice(0, -1) : target.baseUrl;
  return `${base}/repos/${enc(target.owner)}/${enc(target.repo)}`;
}

/** @param {HttpResponse} response */
export function isOk(response) {
  return response.status >= 200 && response.status < 300;
}

/** @param {unknown} value @param {string} field */
export function extractStringField(value, field) {
  if (typeof value !== "object" || value === null) return "";
  const candidate = /** @type {Record<string, unknown>} */ (value)[field];
  return typeof candidate === "string" ? candidate : "";
}

/** @param {HttpResponse} response @returns {{ ok: true, json: any } | { ok: false, message: string }} */
export function parseJsonBody(response) {
  try {
    return { ok: true, json: JSON.parse(response.bodyText) };
  } catch {
    return { ok: false, message: "GitHub returned a non-JSON response." };
  }
}

/** @param {HttpResponse} response @param {string} fallback */
export function providerErrorMessage(response, fallback) {
  const body = parseJsonBody(response);
  const providerMessage = body.ok && typeof body.json?.message === "string" ? body.json.message : undefined;
  return providerMessage ? `${fallback}: ${providerMessage}` : `${fallback} (status ${response.status})`;
}

/** @param {string} path @returns {Failure} */
function notRegularFileFailure(path) {
  return { ok: false, code: "provider-error", message: `'${path}' already exists on the branch but is not a regular file — refusing to overwrite it with a blob` };
}

/** @param {string} path */
function splitRepoPath(path) {
  const idx = path.lastIndexOf("/");
  return idx === -1 ? { dir: "", name: path } : { dir: path.slice(0, idx), name: path.slice(idx + 1) };
}

/** A regular file, not a symlink or submodule (both report `download_url: null`). @param {unknown} entry */
function isRegularFileEntry(entry) {
  if (extractStringField(entry, "type") !== "file") return false;
  return !(entry !== null && typeof entry === "object" && /** @type {Record<string, unknown>} */ (entry).download_url === null);
}

/** GitHub's own words for its secondary (abuse) rate limit, in a 403 body that carries no header. */
const SECONDARY_RATE_LIMIT_PATTERN = /secondary rate limit|abuse detection/i;

/** @param {HttpResponse} response @param {string} name */
function headerOf(response, name) {
  const headers = response.headers ?? {};
  const found = Object.keys(headers).find((key) => key.toLowerCase() === name);
  return found === undefined ? undefined : headers[found];
}

/** @param {{ response: HttpResponse, status: number }} required */
function isGitHubRateLimited({ response, status }, _options = {}) {
  return status === 429 || (status === 403 && (headerOf(response, "retry-after") !== undefined || headerOf(response, "x-ratelimit-remaining") === "0" || SECONDARY_RATE_LIMIT_PATTERN.test(response.bodyText)));
}

/** @param {{ response: HttpResponse, retryAfter: number, policy: RetryPolicy }} required */
function gitHubRateLimitDelay({ response, retryAfter, policy }, _options = {}) {
  if (Number.isFinite(retryAfter) && retryAfter >= 0) return retryAfter * 1000;
  const reset = Number(headerOf(response, "x-ratelimit-reset"));
  if (headerOf(response, "x-ratelimit-remaining") === "0" && Number.isFinite(reset)) return Math.max(0, reset * 1000 - Date.now()) + 1000;
  return policy.rateLimitWaitMs;
}

/**
 * How long to wait before retrying a request GitHub may answer differently next time, or
 * `undefined` when it will not: an egress refusal, or a 4xx that is not a rate limit, is final.
 * GitHub's documented order: `retry-after` (seconds) first, then `x-ratelimit-reset` when
 * `x-ratelimit-remaining` is 0, then at least a minute for a secondary limit without either.
 *
 * @param {{ kind: "response", response: HttpResponse } | { kind: "network-unreachable", refused: boolean }} result
 * @param {number} attempt - 1 for the first retry.
 * @param {RetryPolicy} policy
 * @returns {number | undefined}
 * @complexity O(headers).
 */
export function retryDelayMs(result, attempt, policy) {
  const backoff = Math.min(policy.maxBackoffMs, policy.baseBackoffMs * 2 ** (attempt - 1));
  if (result.kind !== "response") return result.refused ? undefined : backoff;
  const { status } = result.response;
  const retryAfter = Number(headerOf(result.response, "retry-after"));
  const rateLimited = isGitHubRateLimited({ response: result.response, status });
  if (!rateLimited) return status >= 500 && status <= 599 ? backoff : undefined;
  return gitHubRateLimitDelay({ response: result.response, retryAfter, policy });
}

/**
 * @typedef {{ maxAttempts: number, baseBackoffMs: number, maxBackoffMs: number, rateLimitWaitMs: number, maxWaitMs: number }} RetryPolicy
 * `maxWaitMs` caps one wait: GitHub asking for longer (an hourly limit) is reported, not slept on.
 */

/**
 * The credentialed GitHub calls, bound to one kit.
 *
 * @param {Kit} kit
 * @param {{ timeoutMs?: number, retry?: RetryPolicy }} [options] - `timeoutMs` is each request's
 *   socket-idle budget (the egress policy may cap it lower). `retry` re-sends a request that failed
 *   transiently ({@link retryDelayMs}); every GitHub Git Data write is safe to repeat (a blob or tree
 *   is addressed by its content, and a non-force ref update to the same commit is a no-op). Without
 *   it a request is sent once, as `custom_credential_write_files` always has.
 */
export function createGitDataClient(kit, options = {}) {
  const timeoutMs = options.timeoutMs ?? GITHUB_WRITE_FILES_TIMEOUT_MS;
  const sleep = kit.sleep ?? ((ms) => new Promise((resolve) => setTimeout(resolve, ms)));

  /**
   * @param {Target} target @param {{ method: "GET" | "POST" | "PATCH", url: string, body?: string }} request
   * @returns {Promise<{ kind: "response", response: HttpResponse } | { kind: "network-unreachable", message: string, logDetail: string }>}
   */
  async function send(target, request) {
    let result = await sendOnce(target, request);
    const policy = options.retry;
    for (let attempt = 1; policy !== undefined && attempt < policy.maxAttempts; attempt++) {
      const waitMs = retryDelayMs(result, attempt, policy);
      if (waitMs === undefined || waitMs > policy.maxWaitMs) break;
      await sleep(waitMs);
      result = await sendOnce(target, request);
    }
    if (result.kind === "response") return result;
    return { kind: "network-unreachable", message: result.message, logDetail: result.logDetail };
  }

  /**
   * @param {Target} target @param {{ method: "GET" | "POST" | "PATCH", url: string, body?: string }} request
   * @returns {Promise<{ kind: "response", response: HttpResponse } | { kind: "network-unreachable", refused: boolean, message: string, logDetail: string }>}
   */
  async function sendOnce(target, request) {
    try {
      const response = await kit.httpClient.send({
        method: request.method,
        url: request.url,
        headers: {
          Authorization: target.authorization,
          Accept: "application/vnd.github+json",
          "X-GitHub-Api-Version": GITHUB_API_VERSION,
          ...(request.body !== undefined ? { "Content-Type": "application/json" } : {}),
        },
        timeoutMs,
        ...(request.body !== undefined ? { body: request.body } : {}),
      });
      return { kind: "response", response };
    } catch (err) {
      const described = kit.describeTransportError(err);
      const refused = described.refusal !== undefined;
      const message = refused ? `the request to GitHub was refused: ${described.refusal}` : GITHUB_UNREACHABLE_MESSAGE;
      return { kind: "network-unreachable", refused, message, logDetail: described.logDetail };
    }
  }

  /** @param {{ message: string, logDetail: string }} result @returns {Failure} */
  function nonResponseFailure(result) {
    return { ok: false, code: "network-unreachable", message: result.message, logDetail: result.logDetail };
  }

  /** A 404 is `found: false`, not a failure. @param {Target} target @param {string} url @param {string} failureFallback
   *  @returns {Promise<{ ok: true, found: false } | { ok: true, found: true, json: any } | Failure>} */
  async function getJson(target, url, failureFallback) {
    const result = await send(target, { method: "GET", url });
    if (result.kind !== "response") return nonResponseFailure(result);
    if (result.response.status === 404) return { ok: true, found: false };
    if (!isOk(result.response)) return { ok: false, code: "provider-error", message: providerErrorMessage(result.response, failureFallback) };
    const body = parseJsonBody(result.response);
    if (!body.ok) return { ok: false, code: "provider-error", message: body.message };
    return { ok: true, found: true, json: body.json };
  }

  /** @param {Target} target @param {string} url @param {Record<string, unknown>} body @param {string} failureFallback
   *  @returns {Promise<{ ok: true, json: any } | Failure>} */
  async function postJson(target, url, body, failureFallback) {
    const result = await send(target, { method: "POST", url, body: JSON.stringify(body) });
    if (result.kind !== "response") return nonResponseFailure(result);
    if (!isOk(result.response)) return { ok: false, code: "provider-error", message: providerErrorMessage(result.response, failureFallback) };
    const parsed = parseJsonBody(result.response);
    if (!parsed.ok) return { ok: false, code: "provider-error", message: parsed.message };
    return { ok: true, json: parsed.json };
  }

  /** @param {Target} target @param {string | Uint8Array} content @returns {Promise<{ ok: true, sha: string } | Failure>} */
  async function createBlob(target, content) {
    const bytes = typeof content === "string" ? Buffer.from(content, "utf8") : Buffer.from(content.buffer, content.byteOffset, content.byteLength);
    const result = await postJson(target, `${repoPathOf(target)}/git/blobs`, { content: bytes.toString("base64"), encoding: "base64" }, "GitHub blob creation failed");
    if (!result.ok) return result;
    const sha = extractStringField(result.json, "sha");
    if (!sha) return { ok: false, code: "provider-error", message: "GitHub blob creation response did not include a sha" };
    return { ok: true, sha };
  }

  /** Unforced: a 422 means the branch moved. @param {Target} target @param {string} branch @param {string} sha
   *  @returns {Promise<{ ok: true } | { ok: false, code: "diverged", message: string } | Failure>} */
  async function updateRef(target, branch, sha) {
    const result = await send(target, { method: "PATCH", url: `${repoPathOf(target)}/git/refs/heads/${encPath(branch)}`, body: JSON.stringify({ sha }) });
    if (result.kind !== "response") return nonResponseFailure(result);
    if (result.response.status === 422) {
      return { ok: false, code: "diverged", message: "the branch has moved since this write was confirmed — refusing to overwrite it" };
    }
    if (!isOk(result.response)) return { ok: false, code: "provider-error", message: providerErrorMessage(result.response, "GitHub branch update failed") };
    return { ok: true };
  }

  return { send, nonResponseFailure, getJson, postJson, createBlob, updateRef };
}

/** @typedef {ReturnType<typeof createGitDataClient>} GitDataClient */

/** The two write-files operations. @param {GitDataClient} git */
export function createFileWriter(git) {
  /** @param {Target} target @param {string} branch @param {string} path */
  async function checkOneFileExistence(target, branch, path) {
    const result = await git.getJson(target, `${repoPathOf(target)}/contents/${encPath(path)}?ref=${enc(branch)}`, `GitHub lookup of '${path}' failed`);
    if (!result.ok) return result;
    if (!result.found) return { ok: true, state: { path, exists: false } };
    if (Array.isArray(result.json) || result.json.type !== "file") return notRegularFileFailure(path);
    return { ok: true, state: { path, exists: true } };
  }

  /** @param {string} path @param {unknown} entry */
  function stateFromListingEntry(path, entry) {
    if (entry === undefined) return { ok: true, state: { path, exists: false } };
    if (!isRegularFileEntry(entry)) return notRegularFileFailure(path);
    return { ok: true, state: { path, exists: true } };
  }

  /** @param {{ files: readonly WriteFile[] }} required */
  function groupWriteFilesByDirectory({ files }, _options = {}) {
    /** @type {Map<string, WriteFile[]>} */
    const filesByDir = new Map();
    for (const file of files) {
      const { dir } = splitRepoPath(file.path);
      const bucket = filesByDir.get(dir);
      if (bucket) bucket.push(file);
      else filesByDir.set(dir, [file]);
    }

    return filesByDir;
  }

  /** @param {{ target: Target, branch: string, dirFiles: WriteFile[], entries: any[], stateByPath: Map<string, { path: string, exists: boolean }> }} required */
  async function resolveDirectoryFileStates({ target, branch, dirFiles, entries, stateByPath }, _options = {}) {
    const entryByName = new Map(entries.map((entry) => [extractStringField(entry, "name"), entry]));
    const listingMayBeIncomplete = entries.length >= CONTENTS_API_DIRECTORY_LISTING_CAP;
    for (const file of dirFiles) {
      const entry = entryByName.get(splitRepoPath(file.path).name);
      const resolved = entry || !listingMayBeIncomplete ? stateFromListingEntry(file.path, entry) : await checkOneFileExistence(target, branch, file.path);
      if (!resolved.ok) return resolved;
      stateByPath.set(file.path, resolved.state);
    }
    return { ok: true };
  }

  /** @param {{ target: Target, branch: string, dir: string, dirFiles: WriteFile[], stateByPath: Map<string, { path: string, exists: boolean }> }} required */
  async function checkDirectoryFileExistence({ target, branch, dir, dirFiles, stateByPath }, _options = {}) {
    const listUrl = `${repoPathOf(target)}/contents${dir ? `/${encPath(dir)}` : ""}?ref=${enc(branch)}`;
    const listResult = await git.getJson(target, listUrl, `GitHub directory lookup of '${dir}' failed`);
    if (!listResult.ok) return listResult;
    if (!listResult.found) {
      for (const file of dirFiles) stateByPath.set(file.path, { path: file.path, exists: false });
      return { ok: true };
    }
    const entries = listResult.json;
    if (!Array.isArray(entries)) {
      return { ok: false, code: "provider-error", message: `'${dir}' is a file on the branch, not a directory` };
    }
    return resolveDirectoryFileStates({ target, branch, dirFiles, entries, stateByPath });
  }

  /** One directory listing per distinct parent directory, falling back to a per-file lookup only when
   *  a listing may be truncated. @param {Target} target @param {string} branch @param {readonly WriteFile[]} files */
  async function checkFileExistence(target, branch, files) {
    const filesByDir = groupWriteFilesByDirectory({ files });

    /** @type {Map<string, { path: string, exists: boolean }>} */
    const stateByPath = new Map();
    for (const [dir, dirFiles] of filesByDir) {
      const resolved = await checkDirectoryFileExistence({ target, branch, dir, dirFiles, stateByPath });
      if (!resolved.ok) return resolved;
    }
    return { ok: true, fileStates: files.map((file) => stateByPath.get(file.path)) };
  }

  /** @param {Target & { branch: string, files: readonly WriteFile[] }} input */
  async function planFileWrite(input) {
    const repoPath = repoPathOf(input);
    const refJson = await git.getJson(input, `${repoPath}/git/ref/heads/${encPath(input.branch)}`, "GitHub branch lookup failed");
    if (!refJson.ok) return refJson;
    if (!refJson.found) return { ok: false, code: "branch-not-found", message: `branch '${input.branch}' does not exist in ${input.owner}/${input.repo}` };
    const parentCommitSha = extractStringField(refJson.json.object, "sha");
    if (!parentCommitSha) return { ok: false, code: "provider-error", message: "GitHub branch lookup response did not include a sha" };

    const commitJson = await git.getJson(input, `${repoPath}/git/commits/${enc(parentCommitSha)}`, "GitHub parent-commit lookup failed");
    if (!commitJson.ok) return commitJson;
    if (!commitJson.found) return { ok: false, code: "provider-error", message: "GitHub parent-commit lookup returned 404 for a sha this call just resolved" };
    const baseTreeSha = extractStringField(commitJson.json.tree, "sha");
    if (!baseTreeSha) return { ok: false, code: "provider-error", message: "GitHub parent-commit response did not include a tree sha" };

    const existence = await checkFileExistence(input, input.branch, input.files);
    if (!existence.ok) return existence;
    return { ok: true, plan: { parentCommitSha, baseTreeSha, fileStates: existence.fileStates } };
  }

  /** @param {{ target: Target, treeSha: string, trees: Map<string, any[]> }} required */
  async function readModeTree({ target, treeSha, trees }, _options = {}) {
    let tree = trees.get(treeSha);
    if (!tree) {
      const result = await git.getJson(target, `${repoPathOf(target)}/git/trees/${enc(treeSha)}`, "GitHub file-mode lookup failed");
      if (!result.ok) return result;
      if (!result.found || !Array.isArray(result.json.tree) || result.json.truncated === true) {
        return { ok: false, code: "provider-error", message: "GitHub returned an incomplete tree — refusing to guess file modes" };
      }
      tree = result.json.tree;
      trees.set(treeSha, tree);
    }
    return { ok: true, tree };
  }

  /** @param {{ entry: any }} required */
  function isModeDirectory({ entry }, _options = {}) {
    return entry.type === "tree" && typeof entry.sha === "string" && !!entry.sha;
  }

  /** @param {{ entry: any, path: string }} required */
  function modeFromBlobEntry({ entry, path }, _options = {}) {
    if (entry.type !== "blob" || !["100644", "100755"].includes(entry.mode)) return notRegularFileFailure(path);
    return { ok: true, mode: entry.mode };
  }

  /** @param {{ target: Target, baseTreeSha: string, file: WriteFile, trees: Map<string, any[]> }} required */
  async function readFileMode({ target, baseTreeSha, file, trees }, _options = {}) {
    let treeSha = baseTreeSha;
    const segments = file.path.split("/");
    for (let index = 0; index < segments.length; index++) {
      const loaded = await readModeTree({ target, treeSha, trees });
      if (!loaded.ok) return loaded;
      const entry = loaded.tree.find(entry => entry.path === segments[index]);
      if (!entry) break;
      if (index === segments.length - 1) return modeFromBlobEntry({ entry, path: file.path });
      if (!isModeDirectory({ entry })) return notRegularFileFailure(file.path);
      treeSha = entry.sha;
    }
    return { ok: true, mode: "100644" };
  }

  /** Read each directory of the CONFIRMED tree, never the mutable branch. Non-recursive
   * lookups avoid GitHub's recursive-tree truncation limit and preserve executable blobs.
   * @param {{ target: Target, baseTreeSha: string, files: readonly WriteFile[] }} required */
  async function readFileModes({ target, baseTreeSha, files }) {
    /** @type {Map<string, any[]>} */
    const trees = new Map();
    /** @type {Map<string, string>} */
    const modes = new Map();
    for (const file of files) {
      const result = await readFileMode({ target, baseTreeSha, file, trees });
      if (!result.ok) return result;
      modes.set(file.path, result.mode);
    }
    return { ok: true, modes };
  }

  /** @param {{ input: Target & { files: readonly WriteFile[] }, modes: Map<string, string> }} required */
  async function buildWriteBlobEntries({ input, modes }, _options = {}) {
    /** @type {Map<string, string>} */
    const blobShaByHash = new Map();
    /** @type {Record<string, unknown>[]} */
    const entries = [];
    for (const file of input.files) {
      const hash = createHash("sha256").update(Buffer.from(file.content, "utf8")).digest("hex");
      let blobSha = blobShaByHash.get(hash);
      if (!blobSha) {
        const blobResult = await git.createBlob(input, file.content);
        if (!blobResult.ok) return blobResult;
        blobSha = blobResult.sha;
        blobShaByHash.set(hash, blobSha);
      }
      entries.push({ path: file.path, mode: modes.get(file.path), type: "blob", sha: blobSha });
    }
    return { ok: true, entries };
  }

  /**
   * @param {Target & { branch: string, commitMessage: string, files: readonly WriteFile[] }} input
   * @param {{ parentCommitSha: string, baseTreeSha: string }} plan
   */
  async function commitFiles(input, plan) {
    const repoPath = repoPathOf(input);
    const fileModes = await readFileModes({ target: input, baseTreeSha: plan.baseTreeSha, files: input.files });
    if (!fileModes.ok) return fileModes;
    const blobs = await buildWriteBlobEntries({ input, modes: fileModes.modes });
    if (!blobs.ok) return blobs;

    const treeResult = await git.postJson(input, `${repoPath}/git/trees`, { tree: blobs.entries, base_tree: plan.baseTreeSha }, "GitHub tree creation failed");
    if (!treeResult.ok) return treeResult;
    const newTreeSha = extractStringField(treeResult.json, "sha");
    if (!newTreeSha) return { ok: false, code: "provider-error", message: "GitHub tree creation response did not include a sha" };

    const commitResult = await git.postJson(
      input,
      `${repoPath}/git/commits`,
      { message: input.commitMessage, tree: newTreeSha, parents: [plan.parentCommitSha] },
      "GitHub commit creation failed"
    );
    if (!commitResult.ok) return commitResult;
    const commitSha = extractStringField(commitResult.json, "sha");
    if (!commitSha) return { ok: false, code: "provider-error", message: "GitHub commit creation response did not include a sha" };

    const refResult = await git.updateRef(input, input.branch, commitSha);
    if (!refResult.ok) return refResult;
    return { ok: true, commitSha, commitUrl: `https://github.com/${input.owner}/${input.repo}/commit/${commitSha}` };
  }

  return { planFileWrite, commitFiles };
}

/**
 * @file What the Google Sheets form destination reports back to the forms delivery ledger: the
 * contract's `FormDeliveryResult` and the translation from the plugin's safe Google errors to the
 * contract's nine codes.
 *
 * Exists because only the bare code, `retryable`, `retryAfterMs` and `outcome` ever reach the
 * ledger (the host drops everything else, and a thrown error would become a generic retryable
 * failure). So every failure of a delivery is turned into one of those values here, in one table,
 * and no message, Google text, token or answer ever leaves the adapter. What the person does next
 * for each code is documented in `skills/google-workspace/references/form-delivery.md`.
 */
import { GoogleWorkspaceError } from '../lib/request-policy.mjs';

/** A refusal decided by the adapter itself (config, mapping, dedupe limit, product off). */
export class DeliveryRefusal extends Error {
  /**
   * @param {{ code: string, retryable: boolean }} required A contract code; `message` is the code.
   * @param {{ outcome?: 'not-applied' | 'unknown' }} [optional] Defaults to `not-applied`: every
   *   adapter refusal happens before the append is sent, except the uncertain-append verdict.
   */
  constructor(required, optional = {}) {
    super(required.code);
    this.name = 'DeliveryRefusal';
    this.code = required.code;
    this.retryable = required.retryable;
    this.outcome = optional.outcome ?? 'not-applied';
  }
}

/**
 * Plugin safe code → [contract code, retryable]. Authorization problems are not retried: the job
 * fails at once and stays in the ledger as failed (it is not re-sent after a reconnect). Quota,
 * product-off and transient failures are retried within the forms retry policy (about 8 attempts
 * over about a day), then the job fails.
 */
const CONTRACT_CODES = new Map([
  ['not-connected', ['authorization-required', false]], ['reconnect-required', ['authorization-required', false]],
  ['account-changed', ['authorization-required', false]], ['missing-permission', ['authorization-required', false]],
  ['file-not-granted', ['resource-not-granted', false]], ['access-denied', ['resource-not-granted', false]],
  ['admin-policy', ['resource-not-granted', false]],
  ['quota-delay', ['rate-limited', true]],
  ['invalid-request', ['mapping-invalid', false]], ['invalid-input', ['configuration-invalid', false]],
  ['limit-exceeded', ['destination-limit', false]],
  ['uncertain-outcome', ['outcome-unknown', true]],
  ['product-disabled', ['adapter-unavailable', true]],
  ['conflict', ['delivery-failed', true]], ['service-unavailable', ['delivery-failed', true]], ['network-error', ['delivery-failed', true]],
]);

/** `{ ok: false, error }` with only the fields the contract keeps. @complexity O(1). */
export function failureResult(required, _optional = {}) {
  const { code, retryable, outcome, retryAfterMs } = required;
  return { ok: false, error: { code, retryable, ...(outcome ? { outcome } : {}), ...(retryAfterMs === undefined ? {} : { retryAfterMs }) } };
}

/**
 * The result a failed delivery reports. A plugin error keeps its outcome and Retry-After; anything
 * unrecognised is a retryable `delivery-failed` with no outcome claimed, and its text is dropped.
 * @param {{ error: unknown }} required
 * @complexity O(1).
 */
export function resultForError(required, _optional = {}) {
  const { error } = required;
  if (error instanceof DeliveryRefusal) return failureResult(error);
  if (!(error instanceof GoogleWorkspaceError)) return failureResult({ code: 'delivery-failed', retryable: true });
  const [code, retryable] = CONTRACT_CODES.get(error.code) ?? ['delivery-failed', false];
  return failureResult({ code, retryable, outcome: error.outcome, retryAfterMs: error.retryAfterMs });
}

/**
 * @file The form destinations the destination panel saves: one host form-delivery binding per form
 * (by its short name), for this plugin's Sheets adapter over its own connection, through the host's
 * `deliveryBindings` capability. The binding config is what the Sheets destination reads
 * (`{ spreadsheetId, accountId, tabs: { <formSlug>: { sheetId } } }`, see
 * `form-destinations/README.md`) plus the spreadsheet and tab names the panels show.
 *
 * Exists so a saved choice IS the delivery binding: there is no second copy to keep in step, and the
 * connection panel's account-switch screen lists exactly what delivery uses. Values are metadata
 * only, never a token or a cell.
 */
import { CONNECTION_ID } from './surface-actions.mjs';

/** This plugin's form-destination adapter id (`tovu-form-destinations.json`). */
export const SHEETS_ADAPTER_ID = 'google-sheets';
export const MAX_FORM_DESTINATIONS = 50;

/** A form's short name: also a property name in the binding config, so no `__proto__`-style names. */
export const FORM_SLUG_PATTERN = /^[a-z0-9][a-z0-9_-]{0,63}$/;

/** The one form a binding saved here is for, or null for a binding this panel did not write. @complexity O(1). */
function formSlugOf(binding) {
  const slug = binding.formIds?.length === 1 ? binding.formIds[0] : null;
  return slug !== null && FORM_SLUG_PATTERN.test(slug) ? slug : null;
}

/** The saved destination a binding holds, or null when its config is not in the shape `saveFormDestination` writes. @complexity O(1). */
function destinationOf(binding, formSlug) {
  const { spreadsheetId, accountId, tabs, title, tabTitle } = binding.config;
  const sheetId = tabs?.[formSlug]?.sheetId;
  const valid = typeof spreadsheetId === 'string' && typeof accountId === 'string' && Number.isInteger(sheetId) && typeof title === 'string' && typeof tabTitle === 'string';
  return valid ? { bindingId: binding.bindingId, enabled: binding.enabled, spreadsheetId, title, url: `https://docs.google.com/spreadsheets/d/${spreadsheetId}/edit`, sheetId, tabTitle, accountId } : null;
}

/**
 * The saved destinations, keyed by form slug: this plugin's Sheets bindings that name one form;
 * any other binding of the adapter is left out (and left alone).
 * @param {{ deliveryBindings: { list(): Promise<readonly { bindingId: string, enabled: boolean, adapterId: string, formIds?: readonly string[], config: Record<string, unknown> }[]> } }} required
 * @returns {Promise<Record<string, { bindingId: string, enabled: boolean, spreadsheetId: string, title: string, url: string, sheetId: number, tabTitle: string, accountId: string }>>}
 * @complexity O(b), one host read.
 */
export async function readFormDestinations(required, _optional = {}) {
  const entries = (await required.deliveryBindings.list()).flatMap((binding) => {
    const formSlug = binding.adapterId === SHEETS_ADAPTER_ID ? formSlugOf(binding) : null;
    const destination = formSlug === null ? null : destinationOf(binding, formSlug);
    return destination === null ? [] : [[formSlug, destination]];
  });
  return Object.fromEntries(entries);
}

/**
 * Saves one form's destination as its delivery binding (a new one, or the form's existing one).
 * `accountId` is the account the spreadsheet was verified with: the host freezes it into every
 * delivery job and refuses a job once the connection holds another account (an account switch never
 * silently moves where rows go).
 * @param {{ deliveryBindings: { save(draft: object): Promise<object> }, formSlug: string, destination: { spreadsheetId: string, title: string, sheetId: number, tabTitle: string, accountId: string } }} required
 * @param {{ bindingId?: string, enabled?: boolean }} [optional] The existing binding id and enabled
 *   state for reassignment; normal destination saves enable delivery by default.
 * @complexity O(1), one host write.
 */
export async function saveFormDestination(required, optional = {}) {
  const { formSlug, destination } = required;
  await required.deliveryBindings.save({
    ...(optional.bindingId === undefined ? {} : { bindingId: optional.bindingId }),
    adapterId: SHEETS_ADAPTER_ID, connectionId: CONNECTION_ID, enabled: optional.enabled ?? true, formIds: [formSlug],
    config: {
      spreadsheetId: destination.spreadsheetId, accountId: destination.accountId, tabs: { [formSlug]: { sheetId: destination.sheetId } },
      title: destination.title, tabTitle: destination.tabTitle,
    },
  });
}

/**
 * @file The server half of "Choose spreadsheet", shared by the Picker panel and the form-destination
 * panel: the hosted Picker's bootstrap and its selection check, and the desktop native Picker's start
 * and finish. Every path ends in `verifySelectedSpreadsheet` (`picker-selection.mjs`) before a
 * selection is returned, so nothing a browser or a callback claims is saved unchecked.
 *
 * Hosted: the bootstrap opens a Picker session in the plugin's own settings (random id, the account
 * the token belongs to, 15-minute expiry) and gives the surface ONLY a short-lived access token plus
 * the public Picker config. A selection is accepted only for a live session of this surface, and
 * only for that same account.
 *
 * Desktop: Google's native Picker runs in the system browser as a code + PKCE sign-in with
 * `trigger_onepick` and the spreadsheet MIME filter. The pending attempt (the host's opaque attempt
 * id plus the expected account) is kept in the plugin's settings, the frame polls `finish`, and the
 * `picked_file_ids` callback field is read only through the host's consume-once inbox, which fills
 * only after the sign-in's state and code checked out. A cancel returns no selection and changes
 * nothing.
 *
 * Which path runs: the host says (`context.hostKind`), never the config. Desktop always uses the
 * native Picker in the system browser; hosted uses the JS Picker, which needs a browser key and app
 * id, so a hosted site without both is `unavailable` (`picker-not-configured`) rather than falling
 * back to a flow built for the desktop app.
 */
import { DESKTOP_PICKER_START_PARAMS, parsePickedFileIds, verifySelectedSpreadsheet } from './picker-selection.mjs';
import { GoogleWorkspaceError } from './request-policy.mjs';
import { SHEETS_PRODUCT_ID } from './sheets-client.mjs';
import { CONNECTION_ID, sheetsUnavailableReason, surfaceAccount, surfaceRefusal, surfaceSheetsClient } from './surface-actions.mjs';

/** Public config the hosted JS Picker needs; placeholders the operator sets, never secrets. */
export const PICKER_CONFIG_NAMES = Object.freeze({ developerKey: 'TOVU_GOOGLE_PICKER_BROWSER_KEY', appId: 'TOVU_GOOGLE_PICKER_APP_ID' });

/** Long enough to browse Drive in the Picker; short enough that a forgotten tab stops being usable. */
export const PICKER_SESSION_TTL_MS = 15 * 60_000;

const sessionKey = (surfaceId) => `picker-session:${surfaceId}`;
const attemptKey = (surfaceId) => `picker-attempt:${surfaceId}`;

/** What the frame and chat may see of a verified spreadsheet: metadata only. */
export const metadataOf = ({ spreadsheetId, title, url }) => ({ spreadsheetId, title, url });

/** Both hosted Picker values, or null when either is unset. @complexity O(1): two config reads. */
async function hostedPickerConfig(publicConfig) {
  const developerKey = await publicConfig.get({ name: PICKER_CONFIG_NAMES.developerKey });
  const appId = await publicConfig.get({ name: PICKER_CONFIG_NAMES.appId });
  return developerKey && appId ? { developerKey, appId } : null;
}

/** The bootstrap for a Picker that cannot run here: the safe code and its fixed sentence. @complexity O(1). */
const unavailable = (reason) => ({ mode: 'unavailable', reason, message: new GoogleWorkspaceError({ code: reason }).message });

/** A stored session that is this surface's, unexpired, and the one the frame names. @complexity O(1). */
function isLiveSession(session, sessionId, nowMs) {
  return typeof session?.id === 'string' && session.id === sessionId && typeof session.accountId === 'string'
    && typeof session.expiresAt === 'number' && session.expiresAt > nowMs;
}

/** A stored desktop attempt in the shape `start` wrote. @complexity O(1). */
function isPendingAttempt(pending) {
  return typeof pending?.attemptId === 'string' && typeof pending.accountId === 'string' && typeof pending.expiresAt === 'number';
}

/**
 * Builds the Picker flow.
 * @param {object} [_required]
 * @param {{ now?: () => number, randomId?: () => string }} [optional] Clock and session-id source (tests).
 * @returns {{ bootstrap: Function, verifyHosted: Function, startSystemBrowser: Function, finishSystemBrowser: Function }}
 *   Each takes the handler call (`{ capabilities, context, input?, fail? }`); the verified results
 *   are `{ spreadsheetId, title, url, accountId }` (the caller strips `accountId` before replying).
 * @complexity O(1) to build; each step is a bounded number of host and Google calls.
 */
export function createPickerFlow(_required = {}, optional = {}) {
  const now = optional.now ?? Date.now;
  const randomId = optional.randomId ?? (() => globalThis.crypto.randomUUID());

  /** Opens a hosted session: the account, the token, the public config. @complexity O(1): three requests. */
  async function openHostedSession(capabilities, context, config) {
    const account = await surfaceAccount({ capabilities });
    const accessToken = await capabilities.connections.getAccessToken({ connectionId: CONNECTION_ID });
    const session = { id: randomId(), accountId: account.accountId, expiresAt: now() + PICKER_SESSION_TTL_MS };
    await capabilities.state.set({ key: sessionKey(context.surfaceId), value: session });
    return { mode: 'hosted', accountLabel: account.displayName, picker: { accessToken, ...config, sessionId: session.id } };
  }

  return {
    /**
     * The surface's start data: `unavailable` (with the safe code and its fixed sentence), `system-browser`,
     * or `hosted` with the Picker session. The one answer that carries an access token.
     */
    async bootstrap({ capabilities, context }) {
      const reason = await sheetsUnavailableReason({ capabilities });
      if (reason !== null) return unavailable(reason);
      if (context.hostKind === 'desktop') return { mode: 'system-browser' };
      const config = await hostedPickerConfig(capabilities.publicConfig);
      return config === null ? unavailable('picker-not-configured') : openHostedSession(capabilities, context, config);
    },

    /** Hosted: the frame's `{ sessionId, fileId }` → the verified spreadsheet, for the session's account only. */
    async verifyHosted({ capabilities, context, input, fail }) {
      const session = await capabilities.state.get({ key: sessionKey(context.surfaceId) });
      if (!isLiveSession(session, input.sessionId, now())) throw surfaceRefusal({ fail, code: 'picker-expired' });
      return verifySelectedSpreadsheet({ client: surfaceSheetsClient({ capabilities }), connectionRef: CONNECTION_ID, fileId: input.fileId, expectedAccountId: session.accountId });
    },

    /** Desktop: starts the native Picker sign-in; the host page opens it in the system browser. */
    async startSystemBrowser({ capabilities, context }) {
      // The account read goes through the Sheets client, so Sheets being off refuses here, before any sign-in.
      const account = await surfaceAccount({ capabilities });
      // Native Picker allows drive.file only, so this re-consent asks for the Sheets scope set alone.
      const started = await capabilities.connections.begin(
        { connectionId: CONNECTION_ID, action: 'reconnect' },
        { scopeSetIds: [SHEETS_PRODUCT_ID], startParams: { ...DESKTOP_PICKER_START_PARAMS } },
      );
      const pending = { attemptId: started.attemptId, accountId: account.accountId, expiresAt: Date.parse(started.expiresAt) };
      await capabilities.state.set({ key: attemptKey(context.surfaceId), value: pending });
      return { expiresAt: started.expiresAt };
    },

    /**
     * Desktop: polls the pending attempt. `{ status: 'none' | 'waiting' | 'expired' | 'cancelled' }`,
     * or `{ status: 'selected', spreadsheet }` once the callback's file id checked out.
     */
    async finishSystemBrowser({ capabilities, context }) {
      const key = attemptKey(context.surfaceId);
      const pending = await capabilities.state.get({ key });
      if (!isPendingAttempt(pending)) return { status: 'none' };
      if (pending.expiresAt <= now()) { await capabilities.state.delete({ key }); return { status: 'expired' }; }
      const fields = await capabilities.connections.takeCallbackFields({ connectionId: CONNECTION_ID, attemptId: pending.attemptId });
      if (fields === null) return { status: 'waiting' };
      await capabilities.state.delete({ key });
      const fileId = parsePickedFileIds({ value: fields.picked_file_ids });
      if (fileId === null) return { status: 'cancelled' };
      const spreadsheet = await verifySelectedSpreadsheet({ client: surfaceSheetsClient({ capabilities }), connectionRef: CONNECTION_ID, fileId, expectedAccountId: pending.accountId });
      return { status: 'selected', spreadsheet };
    },
  };
}

/** The reply shape of a desktop poll: the spreadsheet's metadata only. @complexity O(1). */
export function pollReply(required, _optional = {}) {
  const { outcome } = required;
  return outcome.status === 'selected' ? { status: 'selected', spreadsheet: metadataOf(outcome.spreadsheet) } : { status: outcome.status };
}

/** The plugin-settings key holding the spreadsheets picked on the Picker panel, newest first. */
export const PICKED_SPREADSHEETS_KEY = 'picked-spreadsheets';
const MAX_PICKED = 10;

/**
 * The picked spreadsheets kept in the plugin's settings (metadata and the account they were picked
 * with), newest first; entries in any other shape are dropped.
 * @param {{ state: { get(input: { key: string }): Promise<unknown> } }} required
 * @returns {Promise<Array<{ spreadsheetId: string, title: string, url: string, accountId: string }>>}
 * @complexity O(n), n ≤ 10.
 */
export async function readPickedSpreadsheets(required, _optional = {}) {
  const stored = await required.state.get({ key: PICKED_SPREADSHEETS_KEY });
  return Array.isArray(stored) ? stored.filter((entry) => typeof entry?.spreadsheetId === 'string' && typeof entry.accountId === 'string') : [];
}

/**
 * Saves a VERIFIED selection at the top of the picked list (one entry per spreadsheet, at most 10).
 * @param {{ state: { get: Function, set: Function }, spreadsheet: { spreadsheetId: string, title: string, url: string, accountId: string } }} required
 * @complexity O(n), n ≤ 10.
 */
export async function rememberPickedSpreadsheet(required, _optional = {}) {
  const { state, spreadsheet } = required;
  const others = (await readPickedSpreadsheets({ state })).filter((entry) => entry.spreadsheetId !== spreadsheet.spreadsheetId);
  const entry = { ...metadataOf(spreadsheet), accountId: spreadsheet.accountId };
  await state.set({ key: PICKED_SPREADSHEETS_KEY, value: [entry, ...others].slice(0, MAX_PICKED) });
}

/**
 * @file Tool `sheets_named_ranges` (`p_google_workspace__sheets_named_ranges`): list, add, update or delete named
 * ranges. Destructive because deleting or re-pointing a named range breaks formulas that use it.
 *
 * Exists as a named wrapper over the reviewed named-range request kinds.
 */
import { assertOutputWithin, getSpreadsheet, resourceLines, runBatchUpdate, sheetsClientFor, spreadsheetLine } from '../../lib/sheets-client.mjs';
import { gridRangeLabel } from '../../lib/sheets-a1.mjs';

/** The fields an update changes: only the ones given. @complexity O(1). */
const updatedFields = (input) => ['name', 'range'].filter((field) => input[field] !== undefined).join(',');

/** action → the one batch request it sends. */
const REQUESTS = {
  add: (input) => ({ addNamedRange: { namedRange: { name: input.name, range: input.range } } }),
  update: (input) => ({ updateNamedRange: { namedRange: { namedRangeId: input.namedRangeId, ...(input.name === undefined ? {} : { name: input.name }), ...(input.range === undefined ? {} : { range: input.range }) }, fields: updatedFields(input) } }),
  delete: (input) => ({ deleteNamedRange: { namedRangeId: input.namedRangeId } }),
};

export default {
  async invoke({ input, capabilities, signal }) {
    const client = sheetsClientFor({ capabilities });
    if (input.action === 'list') {
      const body = await getSpreadsheet({ client, connectionRef: input.connectionRef, spreadsheetId: input.spreadsheetId, fields: 'namedRanges' }, { signal });
      return assertOutputWithin({ value: { action: 'list', namedRanges: body?.namedRanges ?? [] } });
    }
    const { replies } = await runBatchUpdate({ client, connectionRef: input.connectionRef, spreadsheetId: input.spreadsheetId, requests: [REQUESTS[input.action](input)] }, { signal });
    const added = replies[0]?.addNamedRange?.namedRange;
    return { action: input.action, ...(added ? { namedRange: added } : { namedRangeId: input.namedRangeId }) };
  },
  describeAffectedResources({ input }) {
    const where = input.range ? ` at ${gridRangeLabel({ range: input.range })}` : '';
    const lines = {
      list: 'list named ranges (no change)',
      add: `add named range "${input.name}"${where}`,
      update: `change named range ${input.namedRangeId}${input.name === undefined ? '' : ` to "${input.name}"`}${where} (formulas using it follow the change)`,
      delete: `delete named range ${input.namedRangeId} (formulas using it stop working)`,
    };
    return resourceLines({ lines: [spreadsheetLine(input), lines[input.action]] });
  },
};

/**
 * @file The connection panel in the browser: renders the handler's panel view (account, products,
 * revocation state) and sends the person's choices as declared actions. All wording comes from
 * `connection-view.mjs`; this file only wires buttons to actions.
 *
 * Sign-ins: the panel is a sandboxed frame that cannot open links or popups, so `sign-in` only asks
 * the server to start one; the admin page above the panel then offers "Continue to sign-in" (in the
 * desktop app it opens the system browser). The panel polls the status until the sign-in finishes or
 * its link expires. The Google Account page (to remove access by hand while a revocation is
 * pending) is opened the same way, through the surface client's `openLink`.
 */
import { DISCONNECT_CONFIRM_TEXT, REASSIGN_HINT, connectionSummary, productRows, reassignmentMessage, revocationMessage } from './connection-view.mjs';
import { busy, connectToHost, failureText, h, notice as noticeLine, show, tip, wait } from './dom.mjs';

const POLL_MS = 4000;
let client;
let app;
let notice = null;
/** True while the panel asks "Disconnect and revoke?"; the revocation is sent only from that step. */
let confirmingDisconnect = false;

const call = (action, payload = {}) => client.call({ action, payload });

/** Polls the status after a sign-in started, until the connection changes or the link expires. */
async function followSignIn(before, expiresAt) {
  while (Date.now() < Date.parse(expiresAt)) {
    await wait(POLL_MS);
    const view = await call('status');
    // The sign-in finished: the "continue to sign-in" instruction no longer applies.
    if (JSON.stringify(view.connection) !== JSON.stringify(before.connection)) { notice = null; return render(view); }
  }
  notice = { text: 'The sign-in link expired. Start it again if you still want to change the connection.', tone: 'warn' };
  return render(await call('status'));
}

/** Runs one action from a button; failures become the notice (with "Try again" when the host says
 * a retry can help), never a thrown page error. */
async function run(work) {
  try {
    await busy(app, work);
  } catch (error) {
    notice = { text: failureText(error), retry: error?.retryable === true ? () => run(work) : undefined };
    render(lastView);
  }
}

const SIGN_IN_ACTIONS = { connect: 'connect', reconnect: 'reconnect', switch: 'switch', grant: 'add-scopes' };

/** What each summary button does. */
function onAction(action, view) {
  if (action in SIGN_IN_ACTIONS) return run(async () => {
    const started = await call('sign-in', { action: SIGN_IN_ACTIONS[action] });
    notice = { text: 'Continue with the "Continue to sign-in" button the admin page shows above this panel. This panel updates when you are done.', tone: 'info' };
    render(view);
    await followSignIn(view, started.expiresAt);
  });
  if (action === 'disconnect') { confirmingDisconnect = true; notice = null; return render(view); }
  if (action === 'confirm-disconnect' || action === 'retry-revocation') return run(async () => {
    confirmingDisconnect = false;
    const result = await call('disconnect');
    notice = { text: revocationMessage({ revocation: result.revocation }), tone: result.revocation === 'confirmed' ? 'ok' : 'warn' };
    render(result);
  });
  if (action === 'confirm-switch') return run(async () => {
    const result = await call('confirm-switch', { reassign: tickedDestinations() });
    notice = { text: reassignmentMessage({ reassignment: result.reassignment, destinations: view.destinations }), tone: result.reassignment.failed.length === 0 ? 'ok' : 'warn' };
    render(result);
  });
  return run(async () => { notice = null; render(await call(action)); });
}

/** The form slugs whose "move to the new account" box is ticked right now. */
function tickedDestinations() {
  return [...app.querySelectorAll('input[name="reassign"]')].filter((box) => box.checked).map((box) => box.value);
}

/** One unticked checkbox per destination while a switch is staged: moving one is always a choice. */
function reassignList(destinations) {
  return h('fieldset', { class: 'list reassign' }, [
    h('legend', {}, [REASSIGN_HINT]),
    ...destinations.map((entry) => h('label', { class: 'check' }, [
      h('input', { type: 'checkbox', name: 'reassign', value: entry.formSlug }),
      `${entry.formSlug}: ${entry.title} / ${entry.tabTitle}`,
    ])),
  ]);
}

/**
 * The Google Account page, opened by the admin page (the frame cannot open links): only this
 * surface's declared `linkOrigins` open. The address stays visible in case the host refuses.
 */
function accountAccessLink(url) {
  const open = () => client.openLink({ url }).catch((error) => { notice = { text: failureText(error) }; render(lastView); });
  return h('p', { class: 'account-link' }, [
    'Or remove access yourself:', ' ',
    h('button', { type: 'button', class: 'small', onClick: open }, ['Open Google Account page']),
    ' ', h('span', { class: 'url' }, [url]),
  ]);
}

/** The second step of "Disconnect and revoke": nothing is sent until the person confirms here. */
function disconnectConfirmation(view) {
  const cancel = () => { confirmingDisconnect = false; render(view); };
  return h('div', { class: 'confirm', role: 'group', 'aria-label': 'Confirm disconnect' }, [
    h('p', {}, [DISCONNECT_CONFIRM_TEXT]),
    h('div', { class: 'actions' }, [
      h('button', { type: 'button', class: 'danger', onClick: () => onAction('confirm-disconnect', view) }, ['Yes, disconnect and revoke']),
      h('button', { type: 'button', onClick: cancel }, ['Cancel']),
    ]),
  ]);
}

function connectionCard(view) {
  const summary = connectionSummary({ connection: view.connection });
  const switching = Boolean(view.connection.pendingSwitchAccountLabel);
  // At most one primary action, and none while all is well (connected); the irreversible one reads
  // as dangerous and sits apart at the end.
  const buttonClass = (entry, index) => (entry.action === 'disconnect' ? 'danger-quiet' : index === 0 && summary.tone !== 'ok' ? 'primary' : undefined);
  return h('section', { class: 'card', 'aria-labelledby': 'account-heading' }, [
    h('div', { class: 'head' }, [
      h('span', { class: `dot ${summary.tone}`, 'aria-hidden': 'true' }),
      h('h2', { id: 'account-heading' }, [summary.heading]),
      tip('About the Google connection', summary.detail),
    ]),
    switching && view.destinations.length > 0 ? reassignList(view.destinations) : null,
    h('div', { class: 'actions' }, summary.buttons.map((entry, index) => h('button', { type: 'button', class: buttonClass(entry, index), onClick: () => onAction(entry.action, view) }, [entry.label]))),
    confirmingDisconnect ? disconnectConfirmation(view) : null,
    view.connection.status === 'revocation-pending' ? accountAccessLink(view.accountAccessUrl) : null,
  ]);
}

function productsCard(view) {
  const rows = productRows({ products: view.products, connection: view.connection });
  return h('section', { class: 'card', 'aria-labelledby': 'products-heading' }, [
    h('div', { class: 'head' }, [
      h('h2', { id: 'products-heading' }, ['Products']),
      tip('About products', 'Turning a product on or off changes only what Tovu does; it never changes what Google granted.'),
    ]),
    h('ul', { class: 'rows' }, rows.map((row) => h('li', { class: 'product' }, [
      h('div', { class: 'product-name' }, [
        h('span', { class: 'name-line' }, [h('strong', {}, [row.label]), tip(`About ${row.label}`, row.note)]),
        h('span', { class: row.grant ? 'state warn' : 'state' }, [row.state]),
      ]),
      row.grant ? h('button', { type: 'button', class: 'primary small', onClick: () => onAction('grant', view) }, ['Grant permission']) : null,
      // A switch drawn from the toggle button: the visible track is decoration; its text is the action.
      h('button', { type: 'button', class: 'switch', 'aria-pressed': String(row.enabled), onClick: () => run(async () => { notice = null; render(await call('set-product', { productId: row.id, enabled: !row.enabled })); }) }, [
        h('span', { class: 'sr-only' }, [row.toggleLabel]),
      ]),
    ]))),
  ]);
}

let lastView = null;

function render(view) {
  lastView = view;
  // A null view only comes from a failed first `status`, which always sets the notice first (and
  // with no view there are no buttons, so no later action can render null again).
  if (view === null) return show(app, noticeLine(notice));
  return show(app,
    notice ? noticeLine(notice) : null,
    connectionCard(view),
    productsCard(view));
}

/**
 * Starts the panel in a frame: connects to the host and renders the status once the host's init
 * arrives. Exported so a test can start a fresh panel (fresh state) in its own jsdom window; the
 * last line starts the real one.
 * @param {{ window: Window, document: Document }} required
 */
export function initConnectionPanel(required) {
  client = connectToHost({ window: required.window });
  app = required.document.getElementById('app');
  notice = null;
  confirmingDisconnect = false;
  lastView = null;
  client.ready.then(load);
}

/** The first `status`; a failure the host calls retryable offers "Try again" (another `status`). */
function load() {
  return call('status').then(render, (error) => { notice = { text: failureText(error), retry: error?.retryable === true ? load : undefined }; render(null); });
}

initConnectionPanel({ window, document });

/**
 * @file The few browser helpers the three panels share: connect to the host through the copied
 * admin-surface client, build elements, and show status text.
 *
 * Exists so every panel builds its DOM the same safe way: text always goes through `textContent`
 * (never `innerHTML`), because titles, labels and messages come from Google or the host and must
 * never be parsed as markup inside the panel.
 */
import { createAdminSurfaceClient } from './surface-client.mjs';

/**
 * The client for this frame: listens to the parent's messages only (the client checks the source),
 * and applies the admin's design tokens to this frame's root so `panel.css` matches the admin.
 * @param {{ window: Window }} required - the frame's window (a test passes its own jsdom window).
 */
export function connectToHost(required) {
  const { window: frame } = required;
  closeTipsOnOutsideClick(frame.document);
  return createAdminSurfaceClient({
    parent: frame.parent,
    listen: (handler) => { frame.addEventListener('message', handler); return () => frame.removeEventListener('message', handler); },
  }, { themeRoot: frame.document.documentElement });
}

/**
 * An element with attributes, event handlers (`on<Event>` functions) and children (strings become text).
 * @param {string} tag
 * @param {Record<string, string | boolean | Function | undefined>} [props]
 * @param {Array<Node | string | null | undefined>} [children]
 * @returns {HTMLElement}
 */
export function h(tag, props = {}, children = []) {
  const element = document.createElement(tag);
  for (const [name, value] of Object.entries(props)) {
    if (typeof value === 'function') element.addEventListener(name.slice(2).toLowerCase(), value);
    else if (value === true) element.setAttribute(name, '');
    else if (typeof value === 'string') element.setAttribute(name, value);
  }
  element.append(...children.filter((child) => child !== null && child !== undefined));
  return element;
}

let nextTip = 0;

/**
 * An "i" toggletip: the explanation shows on hover, keyboard focus or tap, instead of a paragraph
 * on screen. The trigger is a focusable span (not a `<button>`), so the panels' button lists stay
 * their actions only; its text stays in the DOM and is the trigger's accessible description.
 * @param {string} label - what the explanation is about ("About Products").
 * @param {string} text
 * @param {{ bodyClass?: string }} [optional] - an extra class on the explanation (e.g. `intro`).
 */
export function tip(label, text, optional = {}) {
  nextTip += 1;
  const id = `tip-${nextTip}`;
  const toggle = (event) => {
    if (event.type === 'keydown' && event.key !== 'Enter' && event.key !== ' ' && event.key !== 'Escape') return;
    event.preventDefault();
    const wrapper = event.currentTarget.parentElement;
    const open = event.key === 'Escape' ? false : !wrapper.classList.contains('open');
    wrapper.classList.toggle('open', open);
    event.currentTarget.setAttribute('aria-expanded', String(open));
  };
  return h('span', { class: 'tip' }, [
    h('span', { class: 'tip-icon', role: 'button', tabindex: '0', 'aria-label': label, 'aria-describedby': id, 'aria-expanded': 'false', onClick: toggle, onKeydown: toggle }, ['i']),
    h('span', { class: optional.bodyClass ? `tip-body ${optional.bodyClass}` : 'tip-body', role: 'tooltip', id }, [text]),
  ]);
}

/** Taps elsewhere close an open toggletip (once per document). */
function closeTipsOnOutsideClick(doc) {
  if (doc.tipsWired) return;
  doc.tipsWired = true;
  doc.addEventListener('click', (event) => {
    for (const open of doc.querySelectorAll('.tip.open')) {
      if (!open.contains(event.target)) { open.classList.remove('open'); open.firstChild.setAttribute('aria-expanded', 'false'); }
    }
  });
}

/**
 * A compact status line. `tone`: 'error' (default, plain `notice`), 'ok', 'info' or 'warn'. With
 * `retry`, a "Try again" button sits inside the same box (outside the `.notice` text).
 * @param {{ text: string, tone?: string, retry?: () => void }} required
 */
export function notice(required) {
  const { text, tone = 'error', retry } = required;
  const line = h('p', { class: tone === 'error' ? 'notice' : `notice ${tone}`, role: 'status' }, [text]);
  if (!retry) return line;
  return h('div', { class: `notice-group ${tone}` }, [line, h('button', { type: 'button', class: 'small', onClick: retry }, ['Try again'])]);
}

const FOCUSABLE = 'button:not([disabled]), input:not([disabled]), select:not([disabled]), a[href], [tabindex="0"]';

/** What identifies a focused control across a re-render: its id, else its tag and visible name. */
function focusKey(element, root) {
  if (!element || element === root || !root.contains(element)) return null;
  return { id: element.id, tag: element.tagName, name: element.getAttribute('aria-label') ?? element.textContent.trim() };
}

function matchesFocusKey({ control, key }, _options = {}) {
  return (key.id && control.id === key.id)
    || (control.tagName === key.tag && (control.getAttribute('aria-label') ?? control.textContent.trim()) === key.name);
}

/**
 * Replaces a region's content, keeping keyboard focus where the person was: on the same control
 * when it is still there, else on the first control of the new content (never lost to `<body>`).
 */
export function show(root, ...nodes) {
  const key = focusKey(root.ownerDocument.activeElement, root) ?? root.pendingFocus ?? null;
  root.pendingFocus = null;
  root.replaceChildren(...nodes.filter(Boolean));
  if (key === null) return;
  const controls = [...root.querySelectorAll(FOCUSABLE)];
  const same = controls.find(control => matchesFocusKey({ control, key }));
  (same ?? controls[0])?.focus();
}

/** The sentence to show for a failed call: the host's or plugin's fixed message. */
export function failureText(error) {
  // The host's schema check names JSON paths ("$.spreadsheetId has the wrong length"): developer text.
  if (error?.code === 'invalid-payload') return 'Some details are missing or not valid. Check them and try again.';
  return typeof error?.message === 'string' && error.message ? error.message : 'Something went wrong. Try again.';
}

/** Runs `work` with every button in `root` disabled, so one click sends one request. */
export async function busy(root, work) {
  // Disabling the focused button drops focus to <body>; `show` restores it from here.
  root.pendingFocus = focusKey(root.ownerDocument.activeElement, root);
  const buttons = [...root.querySelectorAll('button')];
  for (const control of buttons) control.disabled = true;
  try { return await work(); } finally { for (const control of buttons) control.disabled = false; }
}

/** Resolves after `ms` (the desktop Picker and sign-in polls). */
export const wait = (ms) => new Promise((resolve) => { setTimeout(resolve, ms); });

/**
 * @file "Choose spreadsheet" in the browser, shared by the Picker panel and the form-destination
 * panel. Resolves with the server-VERIFIED spreadsheet metadata, or null when the person cancelled
 * (nothing is saved on cancel).
 *
 * Hosted: loads Google's JS Picker (the one script origin the surface's CSP allows) and opens it with
 * the bootstrap's short-lived access token and public config, spreadsheets only, one file. The file
 * id it returns is only a claim: it goes to `verify-picked` with the Picker session id, and only the
 * server's answer is used.
 *
 * Desktop: the native Picker runs in the system browser. `start-system-picker` makes the server start
 * that sign-in (the admin page offers the link; this frame cannot open one), then the frame polls
 * `finish-system-picker` until the server reports a verified selection, a cancel, or the expiry.
 */
import { wait } from './dom.mjs';
import { pollText } from './picker-view.mjs';

const SPREADSHEET_MIME_TYPE = 'application/vnd.google-apps.spreadsheet';
const PICKER_SCRIPT = 'https://apis.google.com/js/api.js';
const POLL_MS = 3000;

/**
 * Loads Google's Picker library once. Rejects when the script is blocked or fails, and forgets the
 * failure so the next "Choose spreadsheet" (the message says "try again") loads it again.
 */
let pickerLibrary;
function loadPickerLibrary() {
  pickerLibrary ??= new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = PICKER_SCRIPT;
    script.onerror = () => { pickerLibrary = undefined; reject(new Error('Google\'s file picker could not load (a blocked script, network, or browser setting). Allow apis.google.com and try again.')); };
    script.onload = () => window.gapi.load('picker', { callback: () => resolve(window.google.picker), onerror: script.onerror });
    document.head.append(script);
  });
  return pickerLibrary;
}

/** Opens the hosted Picker; resolves with the picked file id, or null on cancel. */
async function pickHostedFileId(config) {
  const picker = await loadPickerLibrary();
  return new Promise((resolve) => {
    const view = new picker.DocsView(picker.ViewId.SPREADSHEETS).setMimeTypes(SPREADSHEET_MIME_TYPE);
    const onEvent = (data) => {
      const action = data[picker.Response.ACTION];
      if (action === picker.Action.PICKED) resolve(data[picker.Response.DOCUMENTS]?.[0]?.[picker.Document.ID] ?? null);
      else if (action === picker.Action.CANCEL) resolve(null);
    };
    new picker.PickerBuilder()
