      await Promise.all(Array.from({ length: Math.min(VERCEL_UPLOAD_CONCURRENCY, queue.length) }, worker));
  }
  function vercelUploadTransportError({ err }, _options = {}) {
      // Node's fetch reports every transport failure as a bare "fetch failed"; the cause (a
      // reset socket, a TLS or DNS error) is the only part that says what happened.
      const cause = err?.cause?.message || err?.cause?.code;
      return new DeployError(`Vercel file upload failed: ${err?.message ?? err}${cause ? ` (${cause})` : ''}`, 502);
  }
  async function tryVercelFileUpload({ config, sha, data, attempt }, _options = {}) {
      try {
          return await fetchWithTimeout(`${VERCEL_API}/v2/files${vercelTeamQuery(config)}`, redirectGuardInit({
              method: 'POST',
              headers: {
                  Authorization: `Bearer ${config.token}`,
                  'Content-Type': 'application/octet-stream',
                  'Content-Length': String(data.length),
                  'x-vercel-digest': sha,
              },
              body: data,
          }), { timeoutMs: FETCH_TIMEOUT_MS.UPLOAD });
      }
      catch (err) {
          // A dropped connection is retried like a 5xx (the first real plannie publish lost one of
          // ~200 uploads that way); a timeout is not, since each try already waited the full bound.
          if (attempt < VERCEL_UPLOAD_ATTEMPTS && !/timed out/i.test(String(err?.message))) {
              await sleep(1000 * attempt);
              return undefined;
          }
          throw vercelUploadTransportError({ err });
      }
  }
  async function uploadVercelFile(config, sha, data) {
      for (let attempt = 1; ; attempt += 1) {
          const resp = await tryVercelFileUpload({ config, sha, data, attempt });
          if (resp === undefined) continue;
          assertNotRedirected(resp, 'Vercel file upload');
          if (resp.ok) {
              // Drain the small JSON ack so the connection goes back to the pool.
              await resp.arrayBuffer().catch(() => undefined);
              return;
          }
          if (attempt < VERCEL_UPLOAD_ATTEMPTS && (resp.status === 429 || resp.status >= 500)) {
              await resp.arrayBuffer().catch(() => undefined);
              await sleep(1000 * attempt);
              continue;
          }
          throw vercelError(await readVercelJson(resp), resp.status);
      }
  }
  /**
   * Polls a just-created Vercel deployment until it reaches a terminal
   * `readyState` (`READY`/`ERROR`) or the fixed 30-attempt budget is spent
   * (~1s for the first 5 attempts, 2s thereafter — roughly a minute).
   *
   * A response this file cannot parse as JSON is treated as "keep polling,"
   * not an error — same reasoning as `github-pages.ts`'s `pollGitHubPagesBuild`
   * (fixed 2026-08-16 for the identical bug class): the deployment already
   * exists server-side by the time this loop runs (the create call above
   * already succeeded), so a transient/edge/empty poll response is exactly as
   * uninformative as a stuck in-progress state, never a reason to report an
   * already-created deployment as failed. Any other non-2xx response whose
   * body DID parse still fails fast, unchanged.
   *
   * @complexity O(30) network round-trips, bounded and fixed regardless of input size.
   * @overallScore 90/100
   * @tradeoffs Fixed attempt/backoff constants (lifted verbatim from the OD
   *   origin) rather than caller-configurable ones — acceptable for now since
   *   `publish` has no caller-facing timeout knob yet either; flagged as a
   *   minor extensibility gap rather than a correctness issue.
   */
  async function pollVercelDeployment(config, id) {
      let last = null;
      for (let i = 0; i < 30; i += 1) {
          await sleep(i < 5 ? 1000 : 2000);
          const resp = await fetchWithTimeout(`${VERCEL_API}/v13/deployments/${encodeURIComponent(id)}${vercelTeamQuery(config)}`, redirectGuardInit({ headers: { Authorization: `Bearer ${config.token}` } }), { timeoutMs: FETCH_TIMEOUT_MS.DEPLOY });
          assertNotRedirected(resp, 'Vercel deployment status poll');
          let json;
          try {
              json = await readVercelJson(resp);
          }
          catch {
              // Nothing usable to report yet — keep polling within the same fixed budget
              // rather than turning an ambiguous mid-poll hiccup into a reported failure.
              continue;
          }
          if (!resp.ok)
              throw vercelError(json, resp.status);
          last = json;
          if (json.readyState === 'READY' || json.readyState === 'ERROR')
              return json;
      }
      return last;
  }
  function vercelTeamQuery(config) {
      const params = new URLSearchParams();
      if (config.teamId)
          params.set('teamId', config.teamId);
      else if (config.teamSlug)
          params.set('slug', config.teamSlug);
      const s = params.toString();
      return s ? `?${s}` : '';
  }
  /**
   * Derives a Vercel-safe project name from a caller-supplied label, falling
   * back to a random id if the label sanitizes to nothing. Replaces the OD
   * origin's hardcoded `od-${projectId}` convention.
   */
  function safeVercelProjectName(projectName) {
      return safeProjectLabel(projectName, 80) || `deploy-${Math.random().toString(36).slice(2, 10)}`;
  }
  async function readVercelJson(resp) {
      try {
          return (await resp.json());
      }
      catch {
          throw new DeployError('Vercel returned a non-JSON response.', resp.status || 502);
      }
  }
  function vercelErrorField({ json, field }, _options = {}) {
      return json?.error && typeof json.error === 'object' ? json.error[field] : undefined;
  }
  function vercelError(json, status) {
      const code = vercelErrorField({ json, field: 'code' });
      const message = vercelErrorField({ json, field: 'message' }) ||
          json?.message ||
          `Vercel request failed (${status}).`;
      if (code === 'forbidden' || /permission/i.test(String(message))) {
          return new DeployError("You don't have permission to create a project.", status, json);
      }
      return new DeployError(String(message), status, json);
  }
  function deploymentUrl(json) {
      const url = json?.url || json?.alias?.[0] || '';
      if (!url)
          return '';
      return /^https?:\/\//i.test(url) ? url : `https://${url}`;
  }
  function appendDeploymentAlias({ alias, urls }, _options = {}) {
      if (typeof alias === 'string')
          urls.push(alias);
      else if (alias && typeof alias === 'object') {
          const a = alias;
          if (typeof a.domain === 'string')
              urls.push(a.domain);
          else if (typeof a.url === 'string')
              urls.push(a.url);
      }
  }
  function appendDeploymentAliases({ json, urls }, _options = {}) {
      for (const alias of json.alias ?? []) {
          if (typeof alias === 'string')
              urls.push(alias);
      }
      for (const alias of json.aliases ?? []) {
          appendDeploymentAlias({ alias, urls });
      }
  }
  /**
   * `if (!json) continue` skips a response that is not there. Of this file's one call site,
   * `deploymentUrlCandidates(publicHost, ready, created)` in `publish()`, `created` is always a parsed
   * `JsonObject` (`readVercelJson` returns one or throws), but `ready` is `null` when every one of
   * `pollVercelDeployment`'s 30 status reads was unparseable (each such read is skipped with
   * `continue`, so `last` is never assigned) — then only `created` supplies candidates. Same guard
   * `netlify.ts`'s own `netlifyUrlCandidates` keeps for the same reason.
   */
  function deploymentUrlCandidates(publicHost, ...responses) {
      // Aliases (the production `<project>.vercel.app` among them) are tried before `url`: `url` is the
      // per-deployment address, which Deployment Protection puts behind Vercel's login by default.
      const urls = [];
      const deploymentUrls = [];
      for (const json of responses) {
          if (!json)
              continue;
          if (typeof json.url === 'string')
              deploymentUrls.push(json.url);
          appendDeploymentAliases({ json, urls });
      }
      const candidates = [...new Set([...urls, ...deploymentUrls].map(normalizeDeploymentUrl).filter(Boolean))];
      // The public `<project>.vercel.app` alias goes first when Vercel lists it. Vercel orders aliases
      // its own way, so the team-scoped `<project>-<team>.vercel.app` (behind Deployment Protection)
      // can come first, and the reachability wait stops at the first `protected` answer: a publish
      // whose public alias served 200 was reported `protected` (2026-10-11).
      const publicUrl = normalizeDeploymentUrl(publicHost);
      return candidates.includes(publicUrl) ? [publicUrl, ...candidates.filter((url) => url !== publicUrl)] : candidates;
  }

  return { VercelDeployTarget, isVercelProtectedResponse };
}

/**
 * Reads one credential-check response WITHOUT touching its body: 401/403 means the host refused the
 * credential, any other failure says nothing about it (a 5xx, a rate limit).
 *
 * @param {Response} response
 * @returns {{ ok: true } | { ok: false, reason: "rejected" | "unreachable", statusCode: number }}
 */
function classifyCredentialResponse(response) {
  if (response.ok) return { ok: true };
  return { ok: false, reason: response.status === 401 || response.status === 403 ? "rejected" : "unreachable", statusCode: response.status };
}

/**
 * The token's account `user.username` from a `GET /v2/user` body, or `undefined`. Reads no other field.
 * @param {unknown} body
 * @returns {string | undefined}
 */
function readVercelUsername(body) {
  const user = typeof body === "object" && body !== null ? /** @type {Record<string, unknown>} */ (body).user : undefined;
  const username = typeof user === "object" && user !== null ? /** @type {Record<string, unknown>} */ (user).username : undefined;
  return typeof username === "string" && username !== "" ? username : undefined;
}

/** The module contract Tovu's deploy-target registry loads (`DeployTargetModule`). The one config
 *  field is the optional Vercel `teamId`. */
export default {
  /** @param {{ credential: { token: string }, config: { teamId?: string }, kit: any }} context */
  create({ credential, config, kit }) {
    const { VercelDeployTarget } = bindVercel(kit);
    return new VercelDeployTarget({ token: credential.token, ...(typeof config.teamId === "string" ? { teamId: config.teamId } : {}) });
  },
  /**
   * `GET /v2/user`: 401/403 for a bad token. Reads back only `user.username`, required on both body
   * shapes Vercel's OpenAPI schema declares and public (`vercel.com/<username>`), never email,
   * billing or `defaultTeamId`.
   * @param {{ credential: { token: string }, kit: any }} context
   */
  async verifyCredential({ credential, kit }) {
    const response = await kit.fetch("https://api.vercel.com/v2/user", { headers: { Authorization: `Bearer ${credential.token}` } }, { timeoutMs: kit.timeouts.QUICK });
    const check = classifyCredentialResponse(response);
    if (!check.ok) return check;
    return { ok: true, accountLabel: readVercelUsername(await response.json().catch(() => undefined)) };
  },
  /** @param {{ teamId?: unknown }} config */
  validateConfig(config) {
    if (typeof config.teamId === "string" && config.teamId.trim() === "") return "teamId must not be blank when provided";
    return null;
  },
  basePath() {
    return undefined;
  },
};

/**
 * @file `@tovu/sdk` — the entire plugin-author public contract (SPEC-005 REQ-08, ADR-005 rule 1,
 * ADR-024 §3 ABI freeze).
 *
 * Purpose:
 * This file IS the public API. Everything a plugin's `server/index.mjs` may import from
 * `@tovu/sdk` is exported here and nowhere else — the runtime's internal core modules are never
 * reachable through this package (enforced by `package.json`'s `exports` map, not by this file). Hook
 * names, capability tokens, and the `definePlugin`/`PluginSdk` shapes are part of this public
 * surface and follow the ADR-005 deprecation ladder — changing any exported name/shape here is
 * an ecosystem-breaking change once a third-party plugin exists (ADR-005 "the compatibility
 * promise must exist before the first third-party plugin").
 *
 * ADR-024 §3 ABI compliance (ties REQ-05/REQ-08 to the newer governing ADR, ratified after this
 * spec's original approval): every hook is treated as always-awaited by core regardless of
 * whether a given filter function is itself `async` (`BeforeSaveFilter`'s return type is
 * `ExtPatch | Promise<ExtPatch>`); `ContentEntryDraft` is a plain, structured-clone-safe snapshot
 * — never a live ORM entity or class instance; and the `PluginSdk` object a plugin receives is a
 * freshly-built handle of plain closures, never a reference to a live core singleton. This file
 * only declares the TYPES for that contract; the runtime object satisfying `PluginSdk` (with its
 * capability-gated stub-vs-absent behavior, CIC U-003) is built by
 * `Jini/packages/plugins/src/host/capability-sdk.ts` inside core, not here — this package has zero
 * dependency on `src/` (Module Map: "Must never import anything from `src/` — it is consumed by
 * plugin code, not by core").
 *
 * Architectural role:
 * TDD-certified implementation (implementation outline C-001…C-004). Signatures and JSDoc are
 * design-frozen; `definePlugin()` is a pure identity wrap — no side effects, no I/O — that exists
 * for the plugin author's type inference; `loadPlugin()` in `Jini/packages/plugins/src/host/node/loader.ts` is what
 * actually invokes the wrapped `definition.setup(sdk)`. Verified against
 * `__tests__/unit/sdk-public-api.unit.test.ts`.
 */

/** C-004 — the exactly-three v1 capability tokens (REQ-04). A manifest declaring any other
 * string is `invalid` with `CAPABILITY_UNKNOWN` (validated in `Jini/packages/plugins/src/host/manifest.ts`, not
 * here — this file is the single source of truth for the token *strings* only). */
export const CONTENT_READ = "content.read" as const;
export const CONTENT_EXTEND = "content.extend" as const;
export const HOOKS_ATTACH = "hooks.attach" as const;
export const HTTP_ROUTE_REGISTER = "http.route.register" as const;
export const TOOLS_REGISTER = "tools.register" as const;
export const RENDER_CONTRIBUTE = "render.contribute" as const;

/** Union of every valid capability token string. ADR-024 §6: the namespace SHAPE is frozen, but
 * its CONTENTS may grow — this union widens as later hooks (hooks v2 plan) add their own tokens,
 * additive-only, per the SDK's semver rule (ADR-005). */
export type CapabilityToken = typeof CONTENT_READ | typeof CONTENT_EXTEND | typeof HOOKS_ATTACH | typeof HTTP_ROUTE_REGISTER | typeof TOOLS_REGISTER | typeof RENDER_CONTRIBUTE;

/** C-003 — the v1 hook point (REQ-05), kept forever (hooks v2 plan §3.3). Declared points are
 * enumerable via `tovu hooks list` (AC-15) and, as of hooks v2, `HOOK_POINTS` (`./hooks.js`) — this
 * constant is the single source of truth for the point's OWN name string; `HOOK_POINTS`'s entry
 * for it must match. */
export const HOOK_CONTENT_ENTRY_BEFORE_SAVE = "content.entry.beforeSave" as const;

/** hooks v2 plan §3.1 — the one typed hook catalog (data) plus its companion type map, re-exported
 * here so a plugin author imports everything from `@tovu/sdk`'s package root (ADR-005 rule 1: no
 * other import surface exists). See `./hooks.ts`'s own file doc for why this is a value AND type
 * export while `hooks.ts` itself only ever `import type`s from this file (no runtime cycle). */
import {
  HOOK_POINTS,
  type HookKind,
  type HookPointDescriptor,
  type HookPointName,
  type HookSignatures,
  type FilterHookName,
  type ActionHookName,
  type ContributionHookName,
} from "./hooks.js";
export {
  HOOK_POINTS,
  type HookKind,
  type HookPointDescriptor,
  type HookPointName,
  type HookSignatures,
  type FilterHookName,
  type ActionHookName,
  type ContributionHookName,
};

/** The merged-into-`ext.{pluginId}` shape a `beforeSave` filter returns (state.spec.md §2
 * `SdkSurface.ExtPatch`). Values are restricted to the four JSON-primitive types BR-06's field
 * `type` vocabulary supports (`string | integer | number | boolean` — `integer` collapses to
 * `number` at the JS/TS type level; BR-06's validator distinguishes integer-vs-number at the
 * value level, not the type level). */
export type ExtPatch = Readonly<Record<string, string | number | boolean>>;

/**
 * The read-only entry snapshot a `beforeSave` filter receives (REQ-05, RT-001). A v1 filter
 * cannot mutate core entry fields — this type has no setters, and every field is `readonly`
 * (ADR-024 §3: plain, serializable, never a live ORM row). `ext` reflects every OTHER plugin's
 * already-written namespaces at the time this filter runs (TB-01 composition order) — never this
 * plugin's own not-yet-written patch.
 */
export interface ContentEntryDraft {
  readonly id: string;
  readonly workspaceId: string;
  readonly title: string;
  /** Per-entry meta description when available; omitted when the host has no override. */
  readonly metaDescription?: string;
  readonly slug: string;
  readonly status: "draft" | "published";
  readonly bodyJson: Readonly<Record<string, unknown>>;
  readonly ext: Readonly<Record<string, Readonly<Record<string, unknown>>>>;
}

/** Per-invocation context passed alongside the entry draft. */
export interface HookContext {
  readonly pluginId: string;
  readonly workspaceId: string;
}

/** REQ-05's literal filter signature: `(entry, ctx) => ExtPatch`. ADR-024 §3: always treated as
 * awaited by core, so a synchronous filter and an `async` filter are equally valid. Kept as its
 * own named type (rather than inlining `FilterFn<"content.entry.beforeSave">`) because it predates
 * `HookSignatures` and is part of the pinned public surface (ADR-005) — `FilterFn` below is
 * structurally identical for this one hook. */
export type BeforeSaveFilter = (
  entry: Readonly<ContentEntryDraft>,
  ctx: HookContext
) => ExtPatch | Promise<ExtPatch>;

/** hooks v2 plan §3.3 — the generic filter/action/contribution function shapes, one family
 * covering every hook `HookSignatures` declares for that kind, instead of one hand-written
 * signature per hook. Every hook payload is always treated as possibly-async (ADR-024 §3), exactly
 * like `BeforeSaveFilter`. */
export type FilterFn<K extends FilterHookName> = (
  input: Readonly<HookSignatures[K]["input"]>,
  ctx: HookContext
) => HookSignatures[K]["output"] | Promise<HookSignatures[K]["output"]>;
export type ActionFn<K extends ActionHookName> = (
  payload: Readonly<HookSignatures[K]["payload"]>,
  ctx: HookContext
) => void | Promise<void>;
export type ContributionFn<K extends ContributionHookName> = (
  ctx: Readonly<HookSignatures[K]["context"]> & HookContext
) => HookSignatures[K]["contributes"] | Promise<HookSignatures[K]["contributes"]>;

/** Options common to every `addFilter`/`addAction`/`addContribution` call (hooks v2 plan §3.3).
 * Omitted ⇒ the registry's own default (ADR-024 §7: every hook has an explicit, deterministic
 * order — "default" is this SDK's convenience, not an incidental ordering). */
export interface HookAttachOptions {
  readonly priority?: number;
}

/**
 * The capability-scoped handle passed to `PluginDefinition.setup`. Built fresh per plugin load
 * (never a shared module-level singleton, ADR Decision item 2) by
 * `Jini/packages/plugins/src/host/capability-sdk.ts`. **Every surface below is always present on a real `PluginSdk`
 * instance** — an ungranted capability's surface is a stub that throws a typed `CAPABILITY_DENIED`
 * error when invoked, never an absent/`undefined` property (CIC U-003; this file declares the
 * TYPE only, the runtime stub-vs-absent behavior lives in `Jini/packages/plugins/src/host/capability-sdk.ts`).
 */
// Generic contribution contracts stay with Jini's runtime owner. The SDK declares that package
// as a dependency so a plugin consumer resolves these types without the host application's deps.
export type { PluginRouteContribution, PluginToolContribution, PluginWidgetContribution, PluginContribution, PluginRouteInput, PluginRouteResult, PluginAuthContext, PluginProviderContribution, PluginProviderFactory, PluginProviderResource } from '@jini-ai/plugins/host';

export interface PluginSdk {
  readonly routes: { add(required: import('@jini-ai/plugins/host').PluginRouteContribution, optional?: Record<string, never>): void };
  readonly tools: { add(required: import('@jini-ai/plugins/host').PluginToolContribution, optional?: Record<string, never>): void };
  readonly widgets: { add(required: import('@jini-ai/plugins/host').PluginWidgetContribution, optional?: Record<string, never>): void };
  /** Gated by `providers.register` (tier-3 only). Registers an inert provider factory the manifest
   * declares under `contributes.providers`; the host initializes it only when the plugin is
   * installed, enabled and configured, and disposes it on disable or shutdown. */
  readonly providers: { register(required: import('@jini-ai/plugins/host').PluginProviderContribution, optional?: Record<string, never>): void };
  /** Explicit route/tool/widget record; uses the selected surface capability, not hooks.attach. */
  addContribution(required: import('@jini-ai/plugins/host').PluginContribution, optional?: Record<string, never>): void;
  /** Live metadata lookup supplied by the host, shared with agent plugins. No execution grant. */
  readonly plugins?: {
    getPlugin(required: { id: string; family?: string }, optional?: Record<string, never>): Promise<{ id: string; version: string | null; enabled: boolean } | null>;
    findProviders(required: { capability: string }, optional?: { enabledOnly?: boolean }): Promise<readonly { id: string; version: string | null; enabled: boolean }[]>;
  };
  readonly content: {
    /** Gated by `content.read` (REQ-04). Read-only accessor mirroring the filter's own `entry`
     * argument — present for API completeness so a plugin can read the current draft from any
     * capability-scoped closure it holds, not only inside the filter callback itself. */
    read(): Readonly<ContentEntryDraft>;
    /** Gated by `content.extend` (REQ-04/REQ-06). Declares/writes one value into this plugin's
     * own `ext.{pluginId}.{field}` namespace; validated by BR-06 (path namespacing + declared
     * type) at the core boundary, not by this SDK object itself. */
    extend(field: string, value: string | number | boolean): void;
  };
  /** Gated by `hooks.attach` (REQ-04/REQ-05). Attaches a filter to a declared hook point.
   * Attaching to any name other than one of `FilterHookName` is rejected at validation time
   * (`HOOK_UNKNOWN`, EC-05) before this method could ever be reached with a bad name. Widened
   * (hooks v2 plan §3.3) from the single `HOOK_CONTENT_ENTRY_BEFORE_SAVE` literal to a generic `K`
   * — every existing call site (passing that one literal) still type-checks unchanged, since it
   * remains the only `FilterHookName` member as of this SDK version. */
  addFilter<K extends FilterHookName>(hookName: K, filter: FilterFn<K>, opts?: HookAttachOptions): void;
  /** Gated by `hooks.attach` (hooks v2 plan §3.3). Always present on a real `PluginSdk` instance
   * (CIC U-003) — an ungranted capability throws `CapabilityDeniedError` when actually CALLED, not
   * by being absent. `ActionHookName` has no members yet (Wave 1's action hooks are a later slice
   * in this same lane), so no name currently type-checks here — additive, not yet reachable. */
  /** Unsupported until an action hook is cataloged; throws explicitly instead of a no-op. */
  addAction<K extends ActionHookName>(hookName: K, action: ActionFn<K>, opts?: HookAttachOptions): void;
  /** Legacy hook form: no contribution hook is cataloged, so runtime calls fail explicitly.
   * The object form above registers real route/tool/widget contributions using their own grants.
   * Uncataloged legacy calls retain the hooks.attach denial boundary (CIC U-003). */
  addContribution<K extends ContributionHookName>(hookName: K, contribution: ContributionFn<K>, opts?: HookAttachOptions): void;
}

/** A plugin author's registration entry point payload. */
export interface PluginDefinition {
  /** Called once per load, immediately after `import()`, with a fresh capability-scoped
   * `PluginSdk` (ADR Decision item 2). May be async. */
  setup(sdk: PluginSdk): void | Promise<void>;
}

/** The typed return value of `definePlugin` — an opaque, identity-only wrapper (REQ-08). */
export interface Plugin {
  readonly definition: PluginDefinition;
}

/**
 * Wraps a `PluginDefinition` for type inference at the plugin author's call site. Pure identity
 * at runtime (no side effects, no I/O) — `Jini/packages/plugins/src/host/node/loader.ts` invokes the wrapped `definition.setup(sdk)`
 * after the load pipeline's integrity/sdkRange/import steps all pass (BR-01).
 *
 * @param def - The plugin's registration definition (`{ setup(sdk) => void }`).
 * @returns The same definition, typed as `Plugin`. `definePlugin` itself never calls `setup` —
 *   that is `loadPlugin`'s job, after the verify-before-import pipeline succeeds (BR-01 step 4).
 * @complexity O(1) — pure identity wrap, no I/O, no traversal.
 * @overallScore 100/100
 */
export function definePlugin(def: PluginDefinition): Plugin {
  return { definition: def };
}
